INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 1, 'Na początku Bóg stworzył niebo i ziemię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 2, 'A ziemia była bezkształtna i pusta i ciemność była nad głębią, a Duch Boży unosił się nad wodami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 3, 'I Bóg powiedział: Niech stanie się światłość. I stała się światłość.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 4, 'Bóg widział, że światłość była dobra. I oddzielił Bóg światłość od ciemności.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 5, 'I nazwał Bóg światłość dniem, a ciemność nazwał nocą. I nastał wieczór i poranek, dzień pierwszy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 6, 'Potem Bóg powiedział: Niech stanie się firmament pośrodku wód i niech oddzieli wody od wód.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 7, 'I uczynił Bóg firmament, i oddzielił wody, które są pod firmamentem, od wód, które są nad firmamentem. I tak się stało.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 8, 'I Bóg nazwał firmament niebem. I nastał wieczór i poranek, dzień drugi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 9, 'Potem Bóg powiedział: Niech się zbiorą w jednym miejscu wody, które są pod niebem, i niech się ukaże sucha powierzchnia. I tak się stało.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 10, 'I Bóg nazwał suchą powierzchnię ziemią, a zbiorowisko wód – morzami. I Bóg widział, że to było dobre.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 11, 'Potem Bóg powiedział: Niech ziemia zrodzi trawę, rośliny wydające nasiona i drzewo urodzajne przynoszące owoc według swego rodzaju, którego nasienie będzie w nim na ziemi. I tak się stało.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 12, 'I ziemia wydała trawę, rośliny wydające nasienie według swego rodzaju i drzewo przynoszące owoc, w którym było nasienie według swego rodzaju. I Bóg widział, że to było dobre.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 13, 'I nastał wieczór i poranek, dzień trzeci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 14, 'Potem Bóg powiedział: Niech się staną światła na firmamencie nieba, by oddzielały dzień od nocy, i niech stanowią znaki, pory roku, dni i lata.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 15, 'I niech będą światłami na firmamencie nieba, aby świeciły nad ziemią. I tak się stało.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 16, 'I Bóg uczynił dwa wielkie światła: światło większe, aby rządziło dniem, i światło mniejsze, aby rządziło nocą, oraz gwiazdy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 17, 'I Bóg umieścił je na firmamencie nieba, aby świeciły nad ziemią;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 18, 'I żeby rządziły dniem i nocą, i oddzielały światłość od ciemności. I Bóg widział, że to było dobre.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 19, 'I nastał wieczór i poranek, dzień czwarty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 20, 'Potem Bóg powiedział: Niech wody hojnie wydadzą żywe istoty, a ptactwo niech lata nad ziemią, pod firmamentem nieba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 21, 'I Bóg stworzył wielkie wieloryby i wszelkie pływające istoty żywe, które hojnie wydały wody, według ich rodzaju oraz wszelkie ptactwo skrzydlate według jego rodzaju. I Bóg widział, że to było dobre.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 22, 'Bóg błogosławił je, mówiąc: Bądźcie płodne i rozmnażajcie się, i wypełniajcie wody morskie, a ptactwo niech się rozmnaża na ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 23, 'I nastał wieczór i poranek, dzień piąty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 24, 'Bóg powiedział też: Niech ziemia wyda istoty żywe według swego rodzaju: bydło, zwierzęta pełzające i zwierzęta ziemi według swego rodzaju. I tak się stało.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 25, 'I Bóg uczynił zwierzęta ziemi według swego rodzaju i bydło według swego rodzaju, i wszelkie zwierzęta, które pełzają po ziemi według swego rodzaju. I Bóg widział, że to było dobre.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 26, 'Potem Bóg powiedział: Uczyńmy człowieka na nasz obraz według naszego podobieństwa; niech panuje nad rybami morskimi i ptactwem niebieskim, nad bydłem i całą ziemią oraz nad wszelkimi zwierzętami pełzającymi, które pełzają po ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 27, 'Stworzył więc Bóg człowieka na swój obraz, na obraz Boga go stworzył; stworzył ich mężczyzną i kobietą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 28, 'I Bóg błogosławił im. Potem Bóg powiedział do nich: Bądźcie płodni i rozmnażajcie się, napełniajcie ziemię i czyńcie ją sobie poddaną; panujcie nad rybami morskimi i nad ptactwem niebieskim, i nad wszelkimi zwierzętami, które poruszają się po ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 29, 'I Bóg powiedział: Oto dałem wam wszelkie rośliny wydające z siebie nasienie, które są na powierzchni całej ziemi, i wszelkie drzewo mające owoc drzewa, wydające z siebie nasienie – będą one dla was pokarmem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 30, 'I wszelkim zwierzętom ziemi, i wszelkiemu ptactwu niebieskiemu, i wszystkiemu, co pełza po ziemi i ma w sobie życie, pokarmem będą wszelkie rośliny zielone. I tak się stało.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 31, 'I Bóg widział wszystko, co uczynił, a było to bardzo dobre. I nastał wieczór i poranek, dzień szósty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 1, 'Tak ukończone zostały niebiosa i ziemia oraz wszystkie ich zastępy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 2, 'W siódmym dniu Bóg ukończył swe dzieło, które uczynił; i odpoczął siódmego dnia od wszelkiego swego dzieła, które stworzył.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 3, 'I Bóg błogosławił siódmy dzień, i poświęcił go, bo w nim odpoczął od wszelkiego swego dzieła, które Bóg stworzył i uczynił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 4, 'Takie są dzieje stworzenia niebios i ziemi w dniu, w którym Pan Bóg uczynił ziemię i niebiosa;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 5, 'Wszelkie krzewy polne, zanim były na ziemi, i wszelkie rośliny polne, nim wzeszły. Bo Pan Bóg jeszcze nie spuścił deszczu na ziemię i nie było człowieka, który by uprawiał ziemię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 6, 'Ale z ziemi wychodziła para, która nawilżała całą powierzchnię ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 7, 'Wtedy Pan Bóg ukształtował człowieka z prochu ziemi i tchnął w jego nozdrza tchnienie życia. I człowiek stał się żywą duszą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 8, 'Pan Bóg zasadził też ogród w Edenie, na wschodzie, i umieścił tam człowieka, którego ukształtował.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 9, 'I wywiódł Pan Bóg z ziemi wszelkie drzewa miłe dla oka i których owoce były dobre do jedzenia oraz drzewo życia pośrodku ogrodu i drzewo poznania dobra i zła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 10, 'A z Edenu wypływała rzeka, aby nawadniać ogród; i stamtąd dzieliła się na cztery główne rzeki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 11, 'Nazwa pierwszej – Piszon; to ta, która okrąża całą ziemię Chawila, gdzie znajduje się złoto.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 12, 'A złoto tej ziemi jest wyborne. Tam też jest bdellium i kamień onyksowy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 13, 'Nazwa drugiej rzeki – Gichon; ta okrąża całą ziemię Kusz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 14, 'Nazwa zaś trzeciej rzeki – Chiddekel; płynie ona na wschód ku Asyrii. A czwarta rzeka to Eufrat.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 15, 'Pan Bóg wziął więc człowieka i umieścił go w ogrodzie Eden, aby go uprawiał i strzegł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 16, 'I rozkazał Pan Bóg człowiekowi: Możesz jeść do woli z każdego drzewa ogrodu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 17, 'Ale z drzewa poznania dobra i zła jeść nie będziesz, bo tego dnia, kiedy zjesz z niego, na pewno umrzesz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 18, 'Pan Bóg powiedział też: Niedobrze, by człowiek był sam; uczynię mu odpowiednią dla niego pomoc.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 19, 'I ukształtował Pan Bóg z ziemi wszelkie zwierzęta polne i wszelkie ptactwo niebieskie, i przyprowadził je do Adama, aby zobaczyć, jak je nazwie; a jak Adam nazwał każdą istotę żywą, taka była jej nazwa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 20, 'I Adam nadał nazwy wszelkiemu bydłu i ptactwu niebieskiemu, i wszelkim zwierzętom polnym. Dla Adama jednak nie znalazła się pomoc odpowiednia dla niego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 21, 'Wtedy Pan Bóg zesłał głęboki sen na Adama; a gdy zasnął, wyjął jedno z jego żeber i zapełnił ciałem miejsce po nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 22, 'I z tego żebra, które Pan Bóg wyjął z Adama, utworzył kobietę i przyprowadził ją do Adama.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 23, 'I Adam powiedział: To teraz jest kość z moich kości i ciało z mojego ciała; dlatego będzie nazwana kobietą, bo z mężczyzny została wzięta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 24, 'Dlatego opuści mężczyzna swojego ojca i swoją matkę i połączy się ze swoją żoną, i będą jednym ciałem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 25, 'I oboje, Adam i jego żona, byli nadzy, a nie wstydzili się.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 1, 'A wąż był bardziej przebiegły niż wszystkie zwierzęta polne, które Pan Bóg uczynił. Powiedział on do kobiety: Czy Bóg rzeczywiście powiedział: Nie wolno wam jeść ze wszystkich drzew tego ogrodu?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 2, 'I kobieta odpowiedziała wężowi: Możemy jeść owoce z drzew tego ogrodu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 3, 'Ale o owocu drzewa, które jest pośrodku ogrodu, Bóg powiedział: Nie będziecie z niego jeść ani go dotykać, abyście nie umarli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 4, 'I wąż powiedział do kobiety: Na pewno nie umrzecie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 5, 'Ale Bóg wie, że tego dnia, gdy z niego zjecie, otworzą się wasze oczy i będziecie jak bogowie znający dobro i zło.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 6, 'A gdy kobieta spostrzegła, że owoc drzewa był dobry do jedzenia i miły dla oka, a drzewo godne pożądania dla zdobycia wiedzy, wzięła z niego owoc i zjadła; dała też swemu mężowi, który był z nią; i on zjadł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 7, 'I otworzyły się im obojgu oczy i poznali, że są nadzy. Spletli więc liście figowe i zrobili sobie przepaski.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 8, 'Wtedy usłyszeli głos Pana Boga chodzącego po ogrodzie w powiewie dziennym. I Adam, i jego żona ukryli się przed obliczem Pana Boga wśród drzew ogrodu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 9, 'I Pan Bóg zawołał na Adama, i zapytał go: Gdzie jesteś?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 10, 'On odpowiedział: Usłyszałem twój głos w ogrodzie i zląkłem się, gdyż jestem nagi, i ukryłem się.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 11, 'Bóg zapytał: Kto ci powiedział, że jesteś nagi? Czy zjadłeś z drzewa, z którego zakazałem ci jeść?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 12, 'Adam odpowiedział: Kobieta, którą mi dałeś, aby była ze mną, ona dała mi z tego drzewa i zjadłem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 13, 'Pan Bóg zapytał kobietę: Co zrobiłaś? I odpowiedziała kobieta: Wąż mnie zwiódł i zjadłam.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 14, 'Wtedy Pan Bóg powiedział do węża: Ponieważ to uczyniłeś, będziesz przeklęty wśród wszelkiego bydła i wśród wszelkich zwierząt polnych. Na brzuchu będziesz się czołgać i proch będziesz jeść po wszystkie dni swego życia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 15, 'I wprowadzę nieprzyjaźń między tobą a kobietą, między twoim potomstwem a jej potomstwem. Ono zrani ci głowę, a ty zranisz mu piętę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 16, 'A do kobiety powiedział: Wielce pomnożę twoje cierpienia i twoje poczęcia, w bólu będziesz rodzić dzieci. Twoje pragnienie będzie ku twemu mężowi, a on będzie nad tobą panować.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 17, 'Do Adama zaś powiedział: Ponieważ usłuchałeś głosu swojej żony i zjadłeś z drzewa, o którym ci przykazałem, mówiąc: Nie będziesz z niego jadł – przeklęta będzie ziemia z twego powodu, w trudzie będziesz z niej spożywać po wszystkie dni twego życia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 18, 'Ona będzie ci rodzić ciernie i oset i będziesz spożywał rośliny polne.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 19, 'W pocie czoła będziesz spożywał chleb, aż wrócisz do ziemi, gdyż z niej zostałeś wzięty. Bo jesteś prochem i w proch się obrócisz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 20, 'I Adam nadał swojej żonie imię Ewa, bo ona była matką wszystkich żyjących.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 21, 'I Pan Bóg sporządził dla Adama i jego żony odzienie ze skór i przyodział ich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 22, 'Wtedy Pan Bóg powiedział: Oto człowiek stał się jak jeden z nas, znający dobro i zło. Wygnajmy go więc, aby nie wyciągnął swej ręki i nie wziął z drzewa życia, by jeść i żyć na wieki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 23, 'Pan Bóg wydalił go więc z ogrodu Eden, aby uprawiał ziemię, z której został wzięty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 24, 'Tak wygnał człowieka i postawił na wschód od ogrodu Eden cherubinów i płomienisty miecz obracający się we wszystkie strony, aby strzegły drogi do drzewa życia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 1, 'Potem Adam obcował ze swoją żoną Ewą, a ta poczęła i urodziła Kaina. I powiedziała: Otrzymałam mężczyznę od Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 2, 'I urodziła jeszcze jego brata Abla. Abel był pasterzem owiec, a Kain był rolnikiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 3, 'Z biegiem czasu zdarzyło się, że Kain przyniósł Panu ofiarę z plonów ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 4, 'Także Abel przyniósł z pierworodnych swej trzody i z ich tłuszczu. A Pan wejrzał na Abla i jego ofiarę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 5, 'Lecz na Kaina i jego ofiarę nie wejrzał. Kain rozgniewał się bardzo i spochmurniała jego twarz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 6, 'Wtedy Pan zapytał Kaina: Dlaczego się rozgniewałeś? Czemu spochmurniała twoja twarz?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 7, 'Jeśli będziesz dobrze czynił, czy nie zostaniesz wywyższony? A jeśli nie będziesz dobrze czynił, grzech leży u drzwi; a do ciebie będzie jego pragnienie, a ty będziesz nad nim panować.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 8, 'I Kain rozmawiał ze swoim bratem Ablem. A gdy byli na polu, Kain powstał przeciwko swemu bratu Ablowi i zabił go.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 9, 'Wtedy Pan zapytał Kaina: Gdzie jest twój brat Abel? On odpowiedział: Nie wiem. Czy ja jestem stróżem mego brata?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 10, 'Bóg zapytał: Cóż uczyniłeś? Głos krwi twego brata woła do mnie z ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 11, 'Teraz więc przeklęty będziesz na ziemi, która otworzyła swe usta, aby przyjąć krew twego brata przelaną przez twoją rękę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 12, 'Gdy będziesz uprawiał ziemię, nie da ci już swego plonu. Tułaczem i zbiegiem będziesz na ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 13, 'Wtedy Kain powiedział do Pana: Zbyt ciężka jest moja kara, bym mógł ją znieść.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 14, 'Oto wyganiasz mnie dziś z powierzchni ziemi, a przed twoją twarzą będę ukryty. Będę tułaczem i zbiegiem na ziemi, a stanie się tak, że ktokolwiek mnie spotka, zabije mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 15, 'Pan mu odpowiedział: Zaprawdę, ktokolwiek zabije Kaina, poniesie siedmiokrotną zemstę. I nałożył Pan na Kaina piętno, aby nie zabił go nikt, kto by go spotkał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 16, 'Wtedy odszedł Kain sprzed oblicza Pana i zamieszkał w ziemi Nod, na wschód od Edenu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 17, 'I Kain obcował ze swoją żoną, a ona poczęła i urodziła Henocha. Zbudował też miasto i nazwał je imieniem swego syna – Henoch.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 18, 'Henochowi urodził się Irad, a Irad spłodził Mechujaela, a Mechujael spłodził Matuszaela, a Matuszael spłodził Lameka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 19, 'I Lamek pojął sobie dwie żony. Imię jednej było Ada, a drugiej – Silla.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 20, 'Ada urodziła Jabala, który był ojcem mieszkających w namiotach i pasterzy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 21, 'Jego brat miał na imię Jubal, a był on ojcem wszystkich grających na harfie i na flecie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 22, 'Silla urodziła Tubalkaina, który był rzemieślnikiem wszelkiej roboty od miedzi i żelaza. Siostrą Tubalkaina była Noema.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 23, 'I Lamek powiedział swym żonom, Adzie i Silli: Słuchajcie mego głosu, żony Lameka, posłuchajcie moich słów; zabiłem mężczyznę za zranienie mnie i młodzieńca za siniec.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 24, 'Jeśli Kain ma być pomszczony siedem razy, to Lamek siedemdziesiąt siedem razy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 25, 'I Adam znów obcował ze swoją żoną, a ona urodziła syna i nadała mu imię Set, mówiąc: Dał mi Bóg inne potomstwo za Abla, którego zabił Kain.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 26, 'Setowi też urodził się syn i nadał mu imię Enosz. Wtedy zaczęto wzywać imienia Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 1, 'To jest księga rodu Adama. W dniu, w którym Bóg stworzył człowieka, uczynił go na podobieństwo Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 2, 'Stworzył ich mężczyzną i kobietą; błogosławił ich i nadał im imię Adam w dniu, w którym zostali stworzeni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 3, 'Adam żył sto trzydzieści lat i spłodził syna na swoje podobieństwo, na swój obraz, i nadał mu imię Set.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 4, 'A dni Adama po spłodzeniu Seta było osiemset lat i spłodził synów i córki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 5, 'A tak wszystkich dni, które żył Adam, było dziewięćset trzydzieści lat i umarł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 6, 'Set żył sto pięć lat i spłodził Enosza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 7, 'Po spłodzeniu Enosza Set żył osiemset siedem lat i spłodził synów i córki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 8, 'Wszystkich dni Seta było dziewięćset dwanaście lat i umarł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 9, 'Enosz żył dziewięćdziesiąt lat i spłodził Kenana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 10, 'Po spłodzeniu Kenana Enosz żył osiemset piętnaście lat i spłodził synów i córki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 11, 'Wszystkich dni Enosza było dziewięćset pięć lat i umarł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 12, 'Kenan żył siedemdziesiąt lat i spłodził Mahalaleela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 13, 'Po spłodzeniu Mahalaleela Kenan żył osiemset czterdzieści lat i spłodził synów i córki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 14, 'Wszystkich dni Kenana było dziewięćset dziesięć lat i umarł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 15, 'Mahalaleel żył sześćdziesiąt pięć lat i spłodził Jareda.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 16, 'Po spłodzeniu Jareda Mahalaleel żył osiemset trzydzieści lat i spłodził synów i córki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 17, 'Wszystkich dni Mahalaleela było osiemset dziewięćdziesiąt pięć lat i umarł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 18, 'Jared żył sto sześćdziesiąt dwa lata i spłodził Henocha.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 19, 'Po spłodzeniu Henocha Jared żył osiemset lat i spłodził synów i córki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 20, 'Wszystkich dni Jareda było dziewięćset sześćdziesiąt dwa lata i umarł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 21, 'Henoch żył sześćdziesiąt pięć lat i spłodził Matuzalema.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 22, 'Po spłodzeniu Matuzalema Henoch chodził z Bogiem trzysta lat i spłodził synów i córki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 23, 'Wszystkich dni Henocha było trzysta sześćdziesiąt pięć lat.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 24, 'Henoch chodził z Bogiem, a potem już go nie było, bo Bóg go zabrał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 25, 'Matuzalem żył sto osiemdziesiąt siedem lat i spłodził Lameka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 26, 'Po spłodzeniu Lameka Matuzalem żył siedemset osiemdziesiąt dwa lata i spłodził synów i córki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 27, 'Wszystkich dni Matuzalema było dziewięćset sześćdziesiąt dziewięć lat i umarł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 28, 'Lamek żył sto osiemdziesiąt dwa lata i spłodził syna.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 29, 'I nadał mu imię Noe, mówiąc: Ten nas pocieszy w naszej pracy i w trudzie naszych rąk, z powodu ziemi, którą Pan przeklął.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 30, 'Po spłodzeniu Noego Lamek żył pięćset dziewięćdziesiąt pięć lat i spłodził synów i córki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 31, 'Wszystkich dni Lameka było siedemset siedemdziesiąt siedem lat i umarł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 32, 'A gdy Noe miał pięćset lat, spłodził Sema, Chama i Jafeta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 1, 'Gdy ludzie zaczęli się mnożyć na ziemi i rodziły im się córki;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 2, 'Synowie Boży, widząc, że córki ludzkie były piękne, brali sobie za żony wszystkie, które sobie upodobali.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 3, 'I powiedział Pan: Mój duch nie będzie na zawsze się spierał z człowiekiem, bo jest on ciałem. Będzie więc jego dni sto dwadzieścia lat.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 4, 'A w tych dniach byli na ziemi olbrzymi; nawet i potem, gdy synowie Boży zbliżali się do córek ludzkich, a one rodziły im synów. To są mocarze, którzy od dawna byli sławnymi mężczyznami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 5, 'A gdy Pan widział, że wielka jest niegodziwość ludzi na ziemi i wszystkie zamysły i myśli ich serca były tylko złe po wszystkie dni;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 6, 'Żałował Pan, że uczynił człowieka na ziemi, i ubolewał nad tym całym sercem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 7, 'I Pan powiedział: Zgładzę z powierzchni ziemi człowieka, którego stworzyłem, zarówno człowieka, jak i bydło, zwierzęta pełzające i ptactwo niebieskie, bo żałuję, że ich uczyniłem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 8, 'Ale Noe znalazł łaskę w oczach Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 9, 'To są dzieje rodu Noego: Noe był człowiekiem sprawiedliwym i doskonałym w swoich czasach. I Noe chodził z Bogiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 10, 'A Noe spłodził trzech synów: Sema, Chama i Jafeta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 11, 'Ale ziemia zepsuła się w oczach Boga i napełniła się nieprawością.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 12, 'Wtedy Bóg wejrzał na ziemię, a oto była zepsuta, bo wszelkie ciało wypaczyło swoją drogę na ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 13, 'I Bóg powiedział do Noego: Nadszedł koniec wszelkiego ciała przed moim obliczem, bo ziemia przez nie jest pełna nieprawości; wytracę je więc wraz z ziemią.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 14, 'Zbuduj sobie arkę z drewna gofer, zrobisz w arce przegrody i oblejesz ją wewnątrz i na zewnątrz smołą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 15, 'A zbudujesz ją w ten sposób: Długość arki będzie na trzysta łokci, pięćdziesiąt łokci – jej szerokość, a trzydzieści łokci – jej wysokość.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 16, 'Zrobisz okno w arce, a zakończysz je na łokieć od góry. Drzwi umieścisz z boku arki, zrobisz w niej dolne, drugie i trzecie piętro.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 17, 'A ja, oto ja sprowadzę potop wód na ziemię, aby wytracić wszelkie ciało, w którym jest tchnienie życia pod niebem. Wszystko, co jest na ziemi, zginie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 18, 'Ale z tobą zawrę moje przymierze; i wejdziesz do arki, ty i twoi synowie, i twoja żona, i żony twoich synów z tobą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 19, 'I ze wszystkich zwierząt wszelkiego ciała po jednej parze wprowadzisz do arki, aby uchowały się z tobą żywe, będą to samiec i samica.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 20, 'Z ptactwa według jego rodzaju i z bydła według jego rodzaju, i z wszelkich ziemskich zwierząt pełzających według ich rodzaju, po parze z każdego rodzaju wejdą z tobą, aby żywe zostały.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 21, 'A ty weźmiesz ze sobą wszelki pokarm, który się nadaje do jedzenia, i zabierzesz do siebie, i będzie tobie i im na pokarm.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 22, 'I Noe tak uczynił. Zrobił wszystko tak, jak mu Bóg rozkazał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 1, 'Potem Pan powiedział do Noego: Wejdź ty wraz z całym twoim domem do arki, gdyż widziałem cię, że jesteś sprawiedliwy przede mną w tym pokoleniu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 2, 'Z każdego zwierzęcia czystego weź sobie po siedem par, samca i samicę jego; ale ze zwierząt nieczystych – po jednej parze, samca i samicę jego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 3, 'Także z ptactwa niebieskiego po siedem par, samca i samicę, aby zachować przy życiu ich potomstwo na całej powierzchni ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 4, 'Pozostaje bowiem jeszcze siedem dni, a potem spuszczę deszcz na ziemię, na czterdzieści dni i czterdzieści nocy, i zgładzę z powierzchni ziemi wszelkie stworzenie, które uczyniłem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 5, 'Noe uczynił więc wszystko, co mu Pan rozkazał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 6, 'Noe miał sześćset lat, gdy przyszedł potop wód na ziemię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 7, 'I wszedł Noe, a z nim jego synowie, jego żona i żony jego synów do arki ze względu na wody potopu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 8, 'Ze zwierząt czystych i nieczystych i z ptactwa, i ze wszystkiego, co pełza po ziemi;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 9, 'Po parze weszło do Noego do arki, samiec i samica, jak Bóg rozkazał Noemu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 10, 'A po siedmiu dniach wody potopu spadły na ziemię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 11, 'W sześćsetnym roku życia Noego, w drugim miesiącu, siedemnastego dnia tego miesiąca, w tym właśnie dniu, przerwały się wszystkie źródła wielkiej głębi i otworzyły się okna nieba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 12, 'I deszcz padał na ziemię czterdzieści dni i czterdzieści nocy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 13, 'W tym właśnie dniu weszli do arki Noe oraz jego synowie – Sem, Cham i Jafet, a z nimi żona Noego i trzy żony jego synów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 14, 'Oni i wszelkie zwierzęta według swego rodzaju, wszelkie bydło według swego rodzaju, wszelkie zwierzęta pełzające, które pełzają po ziemi według swego rodzaju, wszelkie ptaki według swego rodzaju i wszelkie stworzenia skrzydlate.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 15, 'I tak weszły do Noego do arki, po parze z każdego ciała, w którym było tchnienie życia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 16, 'A te, które weszły, samiec i samica z każdego ciała weszły, jak mu Bóg rozkazał. I zamknął Pan za nim drzwi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 17, 'A potop trwał na ziemi czterdzieści dni i wody wezbrały, i podniosły arkę, i unosiła się nad ziemią.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 18, 'Wody wzmogły się i wezbrały bardzo nad ziemią, i pływała arka po wodach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 19, 'I wody bardzo się wzmogły nad ziemią, i zakryły wszystkie wysokie góry, które były pod całym niebem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 20, 'Wody wezbrały na piętnaście łokci wzwyż i góry zostały zakryte.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 21, 'Zginęło więc wszelkie ciało poruszające się na ziemi: ptactwo, bydło, zwierzęta i wszelkie zwierzęta pełzające, które pełzają po ziemi, i wszyscy ludzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 22, 'Wszystko, co miało w nozdrzach tchnienie życia, wszystko, co żyło na suchym lądzie, zginęło.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 23, 'Tak zostało zgładzone wszelkie stworzenie, które było na powierzchni ziemi, od człowieka aż do bydła, zwierząt pełzających i ptactwa niebieskiego. Wszystko to zostało zgładzone z ziemi. Pozostał tylko Noe i ci, którzy z nim byli w arce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 24, 'A wody wezbrały nad ziemią sto pięćdziesiąt dni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 1, 'Bóg pamiętał jednak o Noem i wszystkich zwierzętach, i wszelkim bydle, które było z nim w arce, i sprowadził Bóg wiatr na ziemię, a wody zaczęły opadać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 2, 'I źródła głębi i okna nieba zamknęły się, i deszcz z nieba został zatrzymany.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 3, 'Wody stopniowo ustępowały z powierzchni ziemi, a po upływie stu pięćdziesięciu dni wody opadły.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 4, 'I arka osiadła na górach Ararat w siódmym miesiącu, siedemnastego dnia tego miesiąca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 5, 'A wody opadały nadal aż do dziesiątego miesiąca. I w dziesiątym miesiącu, pierwszego dnia, ukazały się szczyty gór.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 6, 'Po upływie czterdziestu dni Noe otworzył okno arki, które zrobił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 7, 'I wypuścił kruka, który wylatywał i wracał, aż wyschły wody na ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 8, 'Potem wypuścił gołębicę, aby zobaczyć, czy wody opadły z powierzchni ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 9, 'A gdy gołębica nie znalazła dla siebie miejsca spoczynku, wróciła do niego do arki, bo wody były jeszcze na całej powierzchni ziemi. Wyciągnął więc swoją rękę, pochwycił ją i wziął do siebie do arki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 10, 'A gdy odczekał jeszcze drugie siedem dni, ponownie wypuścił gołębicę z arki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 11, 'I gołębica wróciła do niego pod wieczór, a oto w dziobie zerwany liść oliwny. Tak Noe poznał, że wody opadły z powierzchni ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 12, 'Odczekał jeszcze drugie siedem dni i wypuścił gołębicę, ale już do niego nie wróciła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 13, 'W sześćset pierwszym roku, w pierwszym miesiącu, pierwszego dnia, wyschły wody na ziemi. Wtedy Noe zdjął przykrycie arki i zobaczył, że powierzchnia ziemi była sucha.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 14, 'A w drugim miesiącu, dwudziestego siódmego dnia tego miesiąca, wyschła ziemia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 15, 'I Bóg powiedział do Noego:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 16, 'Wyjdź z arki, ty i z tobą twoja żona, twoi synowie i żony twoich synów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 17, 'Wyprowadź ze sobą wszystkie zwierzęta, które są z tobą, z wszelkiego ciała, ptactwa, bydła i wszelkich zwierząt pełzających, które pełzają po ziemi, i niech się rozrodzą na ziemi, niech będą płodne i niech się rozmnażają na ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 18, 'Wyszedł więc Noe i z nim jego synowie, jego żona i żony jego synów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 19, 'Wyszły także z arki wszelkie bydlęta, wszelkie zwierzęta pełzające, wszelkie ptactwo oraz wszystko, co pełza po ziemi, według swoich rodzajów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 20, 'Potem Noe zbudował ołtarz dla Pana i wziął z każdego czystego zwierzęcia i z każdego czystego ptactwa, i złożył całopalenia na tym ołtarzu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 21, 'I Pan poczuł miłą woń, i Pan powiedział w swoim sercu: Nie będę więcej przeklinał ziemi z powodu człowieka, bo myśl serca człowieka jest zła od jego młodości. Nie wytracę więcej wszystkiego, co żyje, jak teraz uczyniłem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 22, 'Póki ziemia będzie trwać, nie ustaną siew i żniwo, zimno i gorąco, lato i zima, dzień i noc.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 1, 'I Bóg błogosławił Noego i jego synów, i powiedział im: Bądźcie płodni i rozmnażajcie się, i napełniajcie ziemię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 2, 'A strach i lęk przed wami będzie nad wszelkim zwierzęciem ziemi, nad wszelkim ptactwem nieba, nad wszystkim, co się porusza na ziemi, i nad wszelkimi rybami morza; oddane są w wasze ręce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 3, 'Wszystko, co się porusza i żyje, będzie dla was pokarmem, podobnie jak rośliny zielone, daję wam to wszystko.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 4, 'Lecz nie będziecie jeść mięsa z jego życiem, to jest z jego krwią.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 5, 'A ja będę żądał waszej krwi, to jest waszego życia; od każdego zwierzęcia będę jej żądał, jak i od ręki człowieka; od ręki każdego brata jego będę żądał życia człowieka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 6, 'Kto przeleje krew człowieka, przez człowieka będzie przelana jego krew, bo na obraz Boga człowiek został stworzony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 7, 'Wy zaś bądźcie płodni i rozmnażajcie się; rozradzajcie się na ziemi i rozmnażajcie się na niej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 8, 'Potem Bóg powiedział do Noego i do jego synów z nim:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 9, 'A ja, oto ja ustanawiam moje przymierze z wami i z waszym potomstwem po was;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 10, 'I z wszelką żywą istotą, która jest z wami, z ptactwem, bydłem oraz z wszelkim zwierzęciem ziemi, które jest z wami, od wszystkich, które wyszły z arki, aż do każdego zwierzęcia ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 11, 'Ustanowię moje przymierze z wami. Nie będzie już więcej zgładzone wszelkie ciało wodami potopu ani nie będzie już więcej potopu, który miałby zniszczyć ziemię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 12, 'I Bóg powiedział: To jest znak przymierza, które ja ustanawiam między mną a wami i między wszelką żywą istotą, która jest z wami, na wieczne pokolenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 13, 'Kładę na obłoku mój łuk, który będzie na znak przymierza między mną a ziemią.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 14, 'I stanie się, gdy wzbudzę obłok nad ziemią, że ukaże się łuk na obłoku;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 15, 'I wspomnę na moje przymierze, które jest między mną a wami oraz wszelką żywą istotą cielesną. Nie będzie już więcej wód potopu, który miałby zniszczyć wszelkie ciało.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 16, 'Będzie więc ten łuk na obłoku i spojrzę na niego, aby przypomnieć sobie wieczne przymierze między Bogiem a wszelką żywą istotą cielesną, która jest na ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 17, 'I Bóg powiedział do Noego: To jest znak przymierza, które ustanowiłem między mną a wszelkim ciałem, które jest na ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 18, 'A synami Noego, którzy wyszli z arki, byli: Sem, Cham i Jafet. Cham jest ojcem Kanaana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 19, 'To są trzej synowie Noego, przez których napełniła się ludem cała ziemia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 20, 'Wtedy Noe zaczął uprawiać ziemię i zasadził winnicę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 21, 'Potem pił wino i upił się; i leżał odkryty w swoim namiocie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 22, 'A Cham, ojciec Kanaana, zobaczył nagość swego ojca i opowiedział o tym dwom swoim braciom na dworze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 23, 'Wtedy Sem i Jafet wzięli szatę, założyli ją sobie na ramiona, weszli tyłem i zakryli nagość swego ojca; a ich twarze były odwrócone, tak że nie widzieli nagości swego ojca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 24, 'A gdy Noe obudził się po winie, dowiedział się, co mu zrobił jego młodszy syn;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 25, 'I powiedział: Niech będzie przeklęty Kanaan, będzie sługą sług swoich braci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 26, 'Potem dodał: Niech będzie błogosławiony Pan Bóg Sema, a niech Kanaan będzie jego sługą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 27, 'Niech Bóg rozprzestrzeni Jafeta i niech mieszka on w namiotach Sema, a niech będzie Kanaan jego sługą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 28, 'I Noe żył po potopie trzysta pięćdziesiąt lat.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 29, 'I wszystkich dni Noego było dziewięćset pięćdziesiąt lat i umarł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 1, 'Oto dzieje rodu synów Noego: Sema, Chama i Jafeta, którym po potopie urodzili się synowie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 2, 'Synowie Jafeta: Gomer, Magog, Madaj, Jawan, Tubal, Meszek i Tiras.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 3, 'Synowie Gomera: Aszkenaz, Rifat i Togarma.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 4, 'Synowie Jawana: Elisza, Tarszisz, Kittim i Dodanim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 5, 'Od nich rozdzielone zostały wyspy narodów po swych ziemiach; każdy według swojego języka i według swoich rodów, w swoich narodach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 6, 'A synowie Chama: Kusz, Misraim, Put i Kanaan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 7, 'Synowie zaś Kusza: Seba, Chawila, Sabta, Rama i Sabteka. Synowie Ramy: Szeba i Dedan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 8, 'Kusz spłodził Nimroda, który zaczął być mocarzem na ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 9, 'Ten był mocarnym myśliwym przed Panem. Dlatego mówi się: Tak jak Nimrod, mocarny myśliwy przed Panem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 10, 'Początkiem jego królestwa były Babel, Erek, Akkad i Kalne w ziemi Szinear.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 11, 'Z tej ziemi wyszedł Assur i zbudował Niniwę i miasto Rechobot, i Kalach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 12, 'Także wielkie miasto Resan pomiędzy Niniwą i Kalach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 13, 'Misraim zaś spłodził Ludima, Ananima, Lahabima i Naftuchima;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 14, 'Oraz Patrusyma, Kasluchima (z których pochodzą Filistyni) i Kaftoryma.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 15, 'Kanaan zaś spłodził Sydona, swego pierworodnego, i Cheta;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 16, 'I Jebusytów, Amorytów, i Girgaszytów;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 17, 'I Chiwwitów, Arkitów, i Sinitów;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 18, 'I Arwadytów, Semarytów, i Chamatytów. A potem rozproszyły się rody Kananejczyków.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 19, 'A granica Kananejczyków biegła od Sydonu w kierunku Gerary aż do Gazy, w kierunku Sodomy i Gomory, Adamy i Seboima aż do Leszy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 20, 'To są synowie Chama według ich rodów i języków, w ich ziemiach i narodach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 21, 'A Semowi, ojcu wszystkich synów Ebera, starszemu bratu Jafeta, urodzili się synowie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 22, 'Synowie Sema: Elam, Assur, Arpachszad, Lud i Aram.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 23, 'Synowie Arama: Us, Chul, Geter i Masz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 24, 'Arpachszad zaś spłodził Szelacha, a Szelach spłodził Ebera.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 25, 'Eberowi urodzili się dwaj synowie: imię jednego – Peleg, gdyż za jego dni ziemia została rozdzielona; a imię jego brata – Joktan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 26, 'Joktan spłodził Almodada, Szelefa, Chasarmaweta i Jeracha;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 27, 'Hadorama, Uzala i Diklę;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 28, 'Obala, Abimaela i Szeba;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 29, 'Ofira, Chawilę i Jobaba; ci wszyscy byli synami Joktana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 30, 'A obszar ich zamieszkania ciągnął się od Meszy w kierunku Sefar, wschodniej góry.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 31, 'To są synowie Sema według ich rodów i języków, w ich ziemiach i narodach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 32, 'To są rody synów Noego według ich pokoleń i w ich narodach. Od nich wywodzą się narody, które rozprzestrzeniły się na ziemi po potopie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 1, 'Na całej ziemi był jeden język i jedna mowa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 2, 'A gdy wędrowali od wschodu, znaleźli równinę w ziemi Szinear i tam mieszkali.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 3, 'I mówili jeden do drugiego: Chodźcie, zróbmy cegły i wypalmy je w ogniu; i mieli cegłę zamiast kamienia, a smołę zamiast zaprawy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 4, 'Potem powiedzieli: Chodźcie, zbudujmy sobie miasto i wieżę, której szczyt sięgałby do nieba, i uczyńmy sobie imię, abyśmy się nie rozproszyli po powierzchni całej ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 5, 'A Pan zstąpił, aby zobaczyć miasto i wieżę, które synowie ludzcy budowali.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 6, 'I Pan powiedział: Oto lud jest jeden i wszyscy mają jeden język, a jest to dopiero początek ich dzieła. Teraz nic nie powstrzyma ich od wykonania tego, co zamierzają uczynić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 7, 'Zstąpmy więc i pomieszajmy tam ich język, aby jeden nie zrozumiał języka drugiego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 8, 'I tak Pan rozproszył ich stamtąd po całej powierzchni ziemi; i przestali budować miasto.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 9, 'Dlatego nazwano je Babel, bo tam Pan pomieszał język całej ziemi. I stamtąd Pan rozproszył ich po całej powierzchni ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 10, 'To są dzieje rodu Sema: Gdy Sem miał sto lat, spłodził Arpachszada, dwa lata po potopie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 11, 'Po spłodzeniu Arpachszada Sem żył pięćset lat i spłodził synów i córki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 12, 'Arpachszad żył trzydzieści pięć lat i spłodził Szelacha.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 13, 'Po spłodzeniu Szelacha Arpachszad żył czterysta trzy lata i spłodził synów i córki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 14, 'Szelach żył trzydzieści lat i spłodził Ebera.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 15, 'Po spłodzeniu Ebera Szelach żył czterysta trzy lata i spłodził synów i córki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 16, 'Eber żył trzydzieści cztery lata i spłodził Pelega.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 17, 'Po spłodzeniu Pelega Eber żył czterysta trzydzieści lat i spłodził synów i córki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 18, 'Peleg żył trzydzieści lat i spłodził Reu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 19, 'Po spłodzeniu Reu Peleg żył dwieście dziewięć lat i spłodził synów i córki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 20, 'Reu żył trzydzieści dwa lata i spłodził Seruga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 21, 'Po spłodzeniu Seruga Reu żył dwieście siedem lat i spłodził synów i córki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 22, 'Serug żył trzydzieści lat i spłodził Nachora.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 23, 'Po spłodzeniu Nachora Serug żył dwieście lat i spłodził synów i córki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 24, 'Nachor żył dwadzieścia dziewięć lat i spłodził Teracha.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 25, 'Po spłodzeniu Teracha Nachor żył sto dziewiętnaście lat i spłodził synów i córki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 26, 'Terach żył siedemdziesiąt lat i spłodził Abrama, Nachora i Harana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 27, 'A to są rody Teracha: Terach spłodził Abrama, Nachora i Harana. Haran zaś spłodził Lota.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 28, 'I Haran umarł za życia swego ojca Teracha w ziemi swego urodzenia, w Ur chaldejskim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 29, 'I Abram, i Nachor pojęli sobie żony: imię żony Abrama było Saraj, a imię żony Nachora – Milka. Była ona córką Harana, ojca Milki i Jeski.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 30, 'A Saraj była niepłodna, nie miała dzieci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 31, 'I Terach wziął swego syna Abrama i swego wnuka Lota, syna Harana, i swoją synową Saraj, żonę swego syna Abrama; i wyruszyli razem z Ur chaldejskiego, aby udać się do ziemi Kanaan. Gdy przybyli do Charanu, zamieszkali tam.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 32, 'I dni Teracha było dwieście pięć lat, i umarł w Charanie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 1, 'I Pan powiedział do Abrama: Wyjdź z twojej ziemi i od twojej rodziny, i z domu twego ojca do ziemi, którą ci pokażę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 2, 'A uczynię z ciebie wielki naród, będę ci błogosławił i rozsławię twoje imię, i będziesz błogosławieństwem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 3, 'I będę błogosławił tym, którzy tobie będą błogosławić; a tych, którzy przeklinają ciebie, będę przeklinać. W tobie będą błogosławione wszystkie narody ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 4, 'Wyszedł więc Abram, jak mu Pan rozkazał, poszedł z nim też Lot. Abram miał siedemdziesiąt pięć lat, gdy wyszedł z Charanu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 5, 'I Abram wziął swoją żonę Saraj, Lota, syna brata swego, i cały dobytek, który zgromadzili, i dusze, które nabyli w Charanie, i wyszli, aby udać się do ziemi Kanaan; i przybyli do ziemi Kanaan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 6, 'Abram przeszedł tę ziemię aż do miejsca Sychem, do równiny More. Na tej ziemi byli wówczas Kananejczycy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 7, 'I Pan ukazał się Abramowi, i powiedział: Twemu potomstwu dam tę ziemię. I Abram zbudował tam ołtarz dla Pana, który mu się ukazał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 8, 'A stamtąd przeniósł się do góry na wschód od Betel i tam rozbił swój namiot między Betel od zachodu i Aj od wschodu. Tam również zbudował ołtarz dla Pana i wzywał imienia Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 9, 'Potem Abram wyruszył, idąc ku południu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 10, 'A nastał głód na tej ziemi. Abram zstąpił więc do Egiptu, aby tam gościć; ciężki bowiem był głód na ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 11, 'A gdy zbliżał się do Egiptu, powiedział do swej żony Saraj: Oto wiem, że jesteś piękną kobietą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 12, 'Gdy Egipcjanie cię zobaczą, powiedzą: To jego żona; i zabiją mnie, a ciebie zostawią przy życiu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 13, 'Mów, proszę, że jesteś moją siostrą, aby mi się dobrze wiodło ze względu na ciebie i abym dzięki tobie pozostał przy życiu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 14, 'Gdy Abram wszedł do Egiptu, Egipcjanie zobaczyli, że ta kobieta jest bardzo piękna.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 15, 'Ujrzeli ją też dostojnicy faraona i chwalili ją przed nim. I zabrano tę kobietę do domu faraona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 16, 'Ten dobrze traktował Abrama ze względu na nią. Abram miał więc owce, woły, osły, służących i służące, oślice i wielbłądy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 17, 'Pan jednak dotknął faraona i jego dom wielkimi plagami z powodu Saraj, żony Abrama.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 18, 'Faraon wezwał więc Abrama i powiedział: Coś ty mi zrobił? Czemu mi nie powiedziałeś, że ona jest twoją żoną?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 19, 'Dlaczego mówiłeś: Ona jest moją siostrą, tak że mogłem ją wziąć sobie za żonę? A teraz – oto twoja żona, weź ją i idź.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 20, 'I faraon rozkazał o nim swoim ludziom, i odprawili go wraz z żoną i wszystkim, co było jego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 1, 'Tak więc Abram wyszedł z Egiptu, on i jego żona, i wszystko, co miał, i Lot z nim, i udali się ku południu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 2, 'A Abram był bardzo bogaty w bydło, srebro i złoto.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 3, 'I szedł, robiąc postoje, od południa aż do Betel, do tego miejsca, gdzie poprzednio był jego namiot, między Betel a Aj;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 4, 'Do miejsca, gdzie poprzednio zbudował ołtarz. Tam wezwał Abram imienia Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 5, 'Lot, który szedł z Abramem, również miał owce, woły i namioty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 6, 'A ziemia ta nie mogła ich pomieścić, żeby mieszkali razem, bo ich majątek był tak wielki, że nie mogli mieszkać razem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 7, 'I wynikła sprzeczka między pasterzami stad Abrama a pasterzami stad Lota. Kananejczycy i Peryzzyci mieszkali wówczas na tej ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 8, 'Abram powiedział więc do Lota: Proszę, niech nie będzie sporu między mną a tobą, także między moimi pasterzami a twoimi pasterzami, bo jesteśmy braćmi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 9, 'Czyż cała ziemia nie stoi przed tobą? Odłącz się, proszę, ode mnie. Jeśli pójdziesz w lewo, ja pójdę w prawo, a jeśli ty pójdziesz w prawo, ja pójdę w lewo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 10, 'Wtedy Lot podniósł swe oczy i zobaczył, że cała równina nad Jordanem była dobrze nawodniona – zanim Pan zniszczył Sodomę i Gomorę – jak ogród Pana, jak ziemia Egiptu, aż do Zoar.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 11, 'Lot wybrał więc sobie całą tę równinę nad Jordanem i udał się na wschód. I rozłączyli się bracia jeden od drugiego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 12, 'Abram mieszkał w ziemi Kanaan, a Lot mieszkał w miastach tej równiny i rozbił swój namiot aż do Sodomy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 13, 'Ale mężczyźni Sodomy byli źli i wielkimi grzesznikami przed Panem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 14, 'I Pan powiedział do Abrama, gdy Lot już odłączył się od niego: Podnieś teraz swe oczy i spójrz z miejsca, na którym teraz jesteś, na północ i na południe, na wschód i na zachód.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 15, 'Bo całą ziemię, którą widzisz, dam tobie i twemu potomstwu na wieki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 16, 'I rozmnożę twoje potomstwo jak proch ziemi, tak że jeśli ktoś będzie mógł zliczyć proch ziemi, to również twoje potomstwo będzie policzone.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 17, 'Wstań i przejdź tę ziemię wzdłuż i wszerz, bo dam ci ją.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 18, 'Abram zwinął więc namiot, przyszedł i mieszkał na równinach Mamre, które są w Hebronie, i tam zbudował ołtarz dla Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 1, 'Za dni Amrafela, króla Szinearu, Arioka, króla Ellasaru, Kedorlaomera, króla Elamu i Tidala, króla narodów;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 2, 'Prowadzili wojnę z Berą, królem Sodomy, z Birszą, królem Gomory, z Szinabem, królem Admy, z Szemeberem, królem Seboim, i z królem miasta Beli, czyli Soaru.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 3, 'Wszyscy oni połączyli się w dolinie Siddim, gdzie dziś jest Morze Słone.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 4, 'Dwanaście lat służyli Kedorlaomerowi, a w trzynastym roku zbuntowali się.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 5, 'I tak w roku czternastym nadciągnął Kedorlaomer z królami, którzy z nim byli, i pobił Rafaitów w Asztarot-Karnaim, Zuzytów w Ham, Emitów w Szawe-Kiriataim;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 6, 'I Chorytów na ich górze Seir aż do równiny Paran, która jest przy pustyni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 7, 'Potem zawrócili i przybyli do En-Miszpat, czyli Kadesz, i wybili całą krainę Amalekitów, a także Amorytów mieszkających w Chasason-Tamar.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 8, 'Wtedy wyruszyli król Sodomy oraz król Gomory, król Admy, król Seboim i król Beli, czyli Soaru, i ustawili się do bitwy z nimi w dolinie Siddim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 9, 'Z Kedorlaomerem, królem Elamu, Tidalem, królem narodów, Amrafelem, królem Szinearu i Ariokiem, królem Ellasaru – czterech królów przeciw pięciu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 10, 'A dolina Siddim była pełna dołów ze smołą. Gdy uciekali królowie Sodomy i Gomory, wpadli tam, a pozostali uciekli na górę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 11, 'A tamci zabrali wszelkie mienie Sodomy i Gomory oraz całą ich żywność i odeszli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 12, 'Zabrali też Lota, bratanka Abrama, wraz z jego mieniem i odeszli. Mieszkał on bowiem w Sodomie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 13, 'I przyszedł jeden zbieg, i oznajmił to Abramowi Hebrajczykowi, który mieszkał na równinach Mamrego Amoryty, brata Eszkola i Anera. Oni bowiem byli sprzymierzeni z Abramem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 14, 'Gdy Abram usłyszał, że jego brat został pojmany, wyprawił swoich trzystu osiemnastu wyszkolonych sług, urodzonych w jego domu, i ścigał ich aż do Dan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 15, 'W nocy podzielili się, on i jego słudzy, napadli na nich i pobili ich. Potem ścigali ich aż do Choby, która leży po lewej stronie Damaszku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 16, 'Odzyskał całe mienie i odbił swego brata Lota wraz z jego mieniem, a także kobiety i ludzi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 17, 'Gdy wracał po pobiciu Kedorlaomera i królów, którzy z nim byli, król Sodomy wyszedł mu na spotkanie w dolinie Szawe, czyli w dolinie królewskiej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 18, 'A Melchisedek, król Salemu, wyniósł chleb i wino. Był on kapłanem Boga Najwyższego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 19, 'I błogosławił mu, mówiąc: Niech będzie błogosławiony Abram przez Boga Najwyższego, właściciela nieba i ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 20, 'I niech będzie błogosławiony Bóg Najwyższy, który wydał twoich wrogów w twoje ręce. I Abram dał mu dziesięcinę ze wszystkiego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 21, 'A król Sodomy powiedział do Abrama: Oddaj mi ludzi, a mienie weź dla siebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 22, 'Lecz Abram odpowiedział królowi Sodomy: Podniosłem swą rękę do Pana Boga Najwyższego, właściciela nieba i ziemi;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 23, 'Że nie wezmę najmniejszej nitki ani rzemyka od obuwia, ani niczego, co należy do ciebie, abyś nie powiedział: Ja wzbogaciłem Abrama.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 24, 'Tylko to, co moi słudzy zjedli, oraz przydział mężczyzn, którzy poszli ze mną: Anera, Eszkola i Mamrego; niech oni wezmą swój przydział.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 1, 'Po tych wydarzeniach słowo Pana doszło do Abrama w widzeniu: Nie bój się, Abramie. Ja jestem twoją tarczą i twoją niezmiernie obfitą nagrodą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 2, 'I Abram powiedział: Panie Boże, co mi dasz, skoro ja jestem bezdzietny, a szafarzem mego domu jest ten Damasceńczyk Eliezer?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 3, 'Abram dodał: Oto nie dałeś mi potomka, a sługa urodzony w moim domu będzie moim dziedzicem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 4, 'A oto dotarło do niego słowo Pana: Nie on będzie twoim dziedzicem, lecz ten, który wyjdzie z twego wnętrza, będzie twoim dziedzicem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 5, 'Potem wyprowadził go na dwór i powiedział: Spójrz teraz na niebo i policz gwiazdy, jeśli będziesz mógł je policzyć; i powiedział mu: Takie będzie twoje potomstwo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 6, 'I uwierzył Panu, i poczytano mu to za sprawiedliwość.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 7, 'Potem powiedział do niego: Ja jestem Panem, który cię wyprowadził z Ur chaldejskiego, aby ci dać tę ziemię w posiadanie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 8, 'Abram zapytał: Panie Boże, po czym poznam, że ją odziedziczę?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 9, 'I odpowiedział mu: Weź dla mnie trzyletnią jałówkę, trzyletnią kozę i trzyletniego barana, a także synogarlicę i pisklę gołębia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 10, 'Wziął więc to wszystko i rozciął na połowy; a jedną część położył naprzeciwko drugiej, ale ptaków nie rozcinał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 11, 'Kiedy zleciało się ptactwo do tej padliny, Abram je odganiał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 12, 'Gdy słońce zachodziło, głęboki sen ogarnął Abrama i oto groza wielkiej ciemności zapadła na niego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 13, 'I Pan powiedział do Abrama: Wiedz o tym dobrze, że twoje potomstwo będzie przybyszem w cudzej ziemi i wezmą je w niewolę, i będzie uciskane przez czterysta lat.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 14, 'A ja osądzę ten naród, któremu będą służyć; a potem wyjdą stamtąd z wielkim dobytkiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 15, 'Ale ty odejdziesz w pokoju do twoich ojców i będziesz pochowany w dobrej starości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 16, 'A w czwartym pokoleniu wrócą tutaj, bo jeszcze nie dopełniła się nieprawość Amorytów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 17, 'Gdy słońce zaszło i nastała ciemność, oto ukazał się dymiący piec i ognista pochodnia, która przechodziła między tymi połowami zwierząt.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 18, 'W tym właśnie dniu Pan zawarł przymierze z Abramem, mówiąc: Twemu potomstwu dam tę ziemię, od rzeki Egiptu aż do wielkiej rzeki, rzeki Eufrat;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 19, 'Kenitów, Kenizytów i Kadmonitów;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 20, 'Chetytów, Peryzzytów i Refaitów;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 21, 'Amorytów, Kananejczyków, Girgaszytów i Jebusytów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 1, 'Saraj, żona Abrama, nie urodziła mu dzieci. Miała zaś służącą Egipcjankę, która miała na imię Hagar.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 2, 'I powiedziała Saraj do Abrama: Oto Pan nie pozwolił mi urodzić. Wejdź, proszę, do mojej służącej, może z niej będę miała dzieci. I Abram usłuchał głosu Saraj.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 3, 'Wzięła więc Saraj, żona Abrama, swoją służącą Hagar, Egipcjankę, i dała ją swemu mężowi Abramowi za żonę po dziesięciu latach zamieszkania Abrama w ziemi Kanaan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 4, 'Obcował więc z Hagar, a ona poczęła. A gdy spostrzegła, że poczęła, ze wzgardą patrzyła na swoją panią.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 5, 'I Saraj powiedziała do Abrama: Jesteś winien mojej krzywdy. Dałam moją służącą w twe ramiona. Ona jednak, widząc, że poczęła, patrzyła na mnie ze wzgardą. Niech Pan rozsądzi między mną a tobą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 6, 'Abram powiedział do Saraj: Oto twoja służąca jest w twoim ręku, zrób z nią, co uważasz za słuszne. I gdy Saraj dręczyła ją, uciekła od niej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 7, 'I Anioł Pana znalazł ją u źródła wód na pustyni, u źródła przy drodze do Szur.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 8, 'I zapytał: Hagar, służąco Saraj, skąd przyszłaś i dokąd idziesz? Ona odpowiedziała: Uciekam od swojej pani Saraj.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 9, 'Anioł Pana powiedział jej: Wróć do swojej pani i poddaj się pod jej władzę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 10, 'Powiedział jej też Anioł Pana: Rozmnożę twoje potomstwo tak bardzo, że z powodu jego mnogości nie będzie go można policzyć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 11, 'Potem Anioł Pana powiedział jej: Oto poczęłaś i urodzisz syna, a nadasz mu imię Izmael, bo Pan usłyszał twoje cierpienie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 12, 'Będzie on dzikim człowiekiem: jego ręka będzie przeciwko wszystkim, a ręka wszystkich przeciwko jemu; i będzie mieszkać w obecności wszystkich swoich braci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 13, 'I nazwała Pana, który mówił do niej: Ty jesteś Bogiem, który mnie widzi. Powiedziała bowiem: Czyż tu nie spoglądałem na tego, który widzi mnie?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 14, 'Dlatego nazwała tę studnię studnią Żyjącego, który widzi mnie. Jest ona między Kadesz i Bered.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 15, 'Potem Hagar urodziła Abramowi syna. I nadał Abram swemu synowi, którego urodziła Hagar, imię Izmael.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 16, 'A Abram miał osiemdziesiąt sześć lat, gdy Hagar urodziła mu Izmaela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 1, 'Gdy Abram miał dziewięćdziesiąt dziewięć lat, Pan ukazał się Abramowi i powiedział do niego: Ja jestem Bogiem Wszechmogącym. Chodź przed moim obliczem i bądź doskonały.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 2, 'A zawrę moje przymierze między mną a tobą i rozmnożę cię bardzo obficie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 3, 'Wtedy Abram upadł na twarz, a Bóg powiedział do niego:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 4, 'Oto ja ustanawiam moje przymierze z tobą i będziesz ojcem wielu narodów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 5, 'Nie będziesz już się nazywał Abram, ale twoje imię będzie Abraham, bo ustanowiłem cię ojcem wielu narodów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 6, 'Uczynię cię niezmiernie płodnym i od ciebie wywiodę narody, i od ciebie będą pochodzić królowie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 7, 'I utwierdzę moje przymierze między mną a tobą oraz twoim potomstwem po tobie przez wszystkie pokolenia jako wieczne przymierze, abym był ci Bogiem i twemu potomstwu po tobie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 8, 'Dam tobie i twemu potomstwu po tobie ziemię, w której teraz przebywasz, całą ziemię Kanaan, jako własność na wieki, i będę ich Bogiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 9, 'Potem Bóg powiedział Abrahamowi: Ty zaś zachowuj moje przymierze, ty i twoje potomstwo po tobie przez wszystkie pokolenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 10, 'A takie jest moje przymierze, które będziecie zachowywać, między mną a wami i między twoim potomstwem po tobie: Każdy mężczyzna wśród was ma być obrzezany.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 11, 'Obrzezacie więc ciało waszego napletka; to będzie znakiem przymierza między mną a wami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 12, 'Każdy syn wśród was w ósmym dniu życia będzie obrzezany, każdy mężczyzna przez wszystkie pokolenia, tak narodzony w domu, jak i nabyty za pieniądze od jakiegokolwiek cudzoziemca, który nie pochodzi z twego potomstwa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 13, 'Urodzony w twoim domu i nabyty za twoje pieniądze musi być obrzezany. A moje przymierze będzie na waszym ciele jako wieczne przymierze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 14, 'A nieobrzezany mężczyzna, któremu nie obrzezano ciała jego napletka, ta dusza będzie wykluczona ze swego ludu, bo złamała moje przymierze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 15, 'Potem Bóg powiedział do Abrahama: Twojej żony Saraj nie będziesz już nazywał imieniem Saraj, ale jej imię będzie Sara.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 16, 'I będę jej błogosławił, i dam ci z niej syna. Będę jej błogosławił i będzie matką narodów, i od niej będą pochodzić królowie narodów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 17, 'Wtedy Abraham upadł na twarz i roześmiał się, i mówił w swoim sercu: Czy stuletniemu człowiekowi urodzi się syn? I czy Sara w wieku dziewięćdziesięciu lat urodzi?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 18, 'I Abraham powiedział do Boga: Oby tylko Izmael żył przed twoim obliczem!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 19, 'A Bóg powiedział: Naprawdę, twoja żona Sara urodzi ci syna i nadasz mu imię Izaak. I utwierdzę moje przymierze z nim jako wieczne przymierze i z jego potomstwem po nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 20, 'Co do Izmaela też cię wysłuchałem. Oto błogosławiłem mu i uczynię go płodnym, i rozmnożę go bardzo obficie. Spłodzi on dwunastu książąt i uczynię go wielkim narodem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 21, 'Ale moje przymierze utwierdzę z Izaakiem, którego Sara urodzi ci za rok o tej porze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 22, 'Gdy skończył z nim rozmowę, Bóg wzniósł się nad Abrahama.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 23, 'Wtedy Abraham wziął swego syna Izmaela, wszystkich urodzonych w swym domu oraz wszystkich nabytych za pieniądze, wszystkich mężczyzn wśród domowników Abrahama, i obrzezał ciała ich napletków tego samego dnia, jak Bóg mu mówił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 24, 'Abraham miał dziewięćdziesiąt dziewięć lat, gdy obrzezano ciało jego napletka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 25, 'A jego syn Izmael miał trzynaście lat, gdy obrzezano ciało jego napletka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 26, 'Tego samego dnia obrzezano Abrahama i jego syna Izmaela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 27, 'I wszyscy mężczyźni jego domu, urodzeni w domu i nabyci za pieniądze od cudzoziemców, zostali obrzezani z nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 1, 'Potem Pan ukazał mu się na równinie Mamre, a on siedział u wejścia do swego namiotu w najgorętszej porze dnia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 2, 'I podniósł swe oczy, i zobaczył, że naprzeciwko siebie stanęli trzej mężczyźni. Gdy ich ujrzał, pobiegł od wejścia do namiotu na ich spotkanie i skłonił się do ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 3, 'I powiedział: Mój Panie, jeśli znalazłem teraz łaskę w twoich oczach, nie omijaj, proszę, swego sługi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 4, 'Pozwól, by przyniesiono trochę wody, abyście mogli obmyć sobie nogi, potem odpoczniecie pod drzewem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 5, 'I przyniosę kęs chleba, abyście posilili swoje serca. Potem odejdziecie, po to bowiem przyszliście do mnie, swego sługi. A oni powiedzieli: Uczyń tak, jak powiedziałeś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 6, 'Abraham pospieszył do namiotu, do Sary, i powiedział: Przygotuj szybko trzy miarki najlepszej mąki i zrób podpłomyki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 7, 'Abraham zaś poszedł do stada, wziął młode i wyborne cielę i dał je słudze, który szybko je przyrządził.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 8, 'Wziął też masło, mleko i cielę, które przyrządził, i postawił przed nimi. A gdy oni jedli, on stał przy nich pod drzewem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 9, 'I zapytali go: Gdzie jest twoja żona Sara? A on odpowiedział: Jest w namiocie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 10, 'Wtedy powiedział Pan: Na pewno wrócę do ciebie za rok o tej porze, a oto twoja żona Sara będzie miała syna. A Sara przysłuchiwała się u wejścia do namiotu, które było za nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 11, 'Abraham i Sara byli starzy, w podeszłym wieku. I przestało już u Sary bywać według zwyczaju kobiet.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 12, 'Sara roześmiała się więc w sobie, mówiąc: Teraz, gdy się zestarzałam i mój pan jest starcem, mam doznawać rozkoszy?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 13, 'Wtedy Pan powiedział do Abrahama: Dlaczego Sara roześmiała się, mówiąc: Czy naprawdę urodzę, gdy się zestarzałam?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 14, 'Czy jakakolwiek rzecz jest za trudna dla Pana? W przyszłym roku o tej porze wrócę do ciebie, a Sara będzie miała syna.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 15, 'I Sara zaparła się, mówiąc: Nie śmiałam się – bo się bała. A on powiedział: Przeciwnie, śmiałaś się.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 16, 'Potem ci mężczyźni wstali stamtąd i skierowali wzrok ku Sodomie. Abraham zaś szedł z nimi, aby ich odprowadzić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 17, 'Wtedy Pan powiedział: Czy mam zataić przed Abrahamem, co zamierzam uczynić?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 18, 'Przecież Abraham na pewno rozmnoży się w lud wielki i możny, a w nim będą błogosławione wszystkie narody ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 19, 'Znam go bowiem i wiem, że będzie nakazywał swoim synom i swemu domowi po sobie, aby strzegli drogi Pana oraz czynili sprawiedliwość i sąd; aby Pan sprowadził na Abrahama to, co mu powiedział.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 20, 'Potem Pan powiedział: Ponieważ okrzyk Sodomy i Gomory jest wielki i ich grzech jest bardzo ciężki;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 21, 'Zstąpię teraz i zobaczę, czy postępują według tego okrzyku, który doszedł do mnie. A jeśli nie, dowiem się.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 22, 'Wtedy ci mężczyźni odwrócili wzrok i poszli stamtąd do Sodomy, ale Abraham jeszcze stał przed Panem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 23, 'I Abraham zbliżył się, i powiedział: Czy wytracisz sprawiedliwego razem z niegodziwym?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 24, 'Jeśli będzie pięćdziesięciu sprawiedliwych w tym mieście, czy je wytracisz i nie oszczędzisz tego miejsca ze względu na pięćdziesięciu sprawiedliwych, którzy w nim są?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 25, 'Niech to będzie dalekie od ciebie, byś miał uczynić coś takiego i zabić sprawiedliwego z niegodziwym, żeby sprawiedliwy był jak niegodziwy. Niech to będzie dalekie od ciebie! Czy Sędzia całej ziemi nie postąpi sprawiedliwie?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 26, 'Wtedy Pan odpowiedział: Jeśli znajdę w Sodomie pięćdziesięciu sprawiedliwych w samym mieście, oszczędzę całe miejsce ze względu na nich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 27, 'A Abraham odpowiedział: Oto ośmielam się teraz mówić do mojego Pana, choć jestem prochem i popiołem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 28, 'Gdyby do tych pięćdziesięciu sprawiedliwych zabrakło pięciu, czy z powodu braku tych pięciu zniszczysz całe miasto? I odrzekł: Nie zniszczę, jeśli znajdę tam czterdziestu pięciu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 29, 'Odezwał się ponownie do niego i powiedział: A gdyby znalazło się tam czterdziestu? I odpowiedział: Nie uczynię tego ze względu na tych czterdziestu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 30, 'I Abraham powiedział: Niech się nie gniewa mój Pan, że zapytam: A gdyby znalazło się tam trzydziestu? Odpowiedział: Nie uczynię tego, jeśli znajdę tam trzydziestu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 31, 'Rzekł jeszcze: Oto ośmielam się teraz mówić do mego Pana: A gdyby znalazło się tam dwudziestu? Odpowiedział: Nie zniszczę go ze względu na tych dwudziestu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 32, 'Powiedział: Niech się nie gniewa mój Pan, że jeszcze tylko raz przemówię: A gdyby znalazło się tam dziesięciu? Odpowiedział: Nie zniszczę go ze względu na tych dziesięciu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 33, 'Gdy Pan skończył rozmowę z Abrahamem, odszedł. Abraham zaś wrócił do siebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 1, 'I dwaj aniołowie przyszli wieczorem do Sodomy, a Lot siedział w bramie Sodomy. Gdy Lot ich zobaczył, wstał i wyszedł im naprzeciw, i skłonił się twarzą do ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 2, 'I powiedział: Oto proszę, moi panowie, wstąpcie teraz do domu swego sługi, przenocujcie i umyjcie sobie nogi. Potem rano wstaniecie i pójdziecie w swoją drogę. Oni odpowiedzieli: Nie, przenocujemy na ulicy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 3, 'Gdy bardzo na nich nalegał, zboczyli do niego i weszli do jego domu. Wtedy wyprawił im ucztę i napiekł przaśnego chleba, i jedli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 4, 'Lecz zanim się położyli, mężczyźni z miasta, mężczyźni z Sodomy, młodzi i starzy, mieszkańcy ze wszystkich stron, otoczyli dom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 5, 'I wołali do Lota, i zapytali go: Gdzie są ci mężczyźni, którzy przyszli do ciebie w nocy? Wyprowadź ich do nas, abyśmy z nimi obcowali.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 6, 'Wtedy Lot wyszedł do nich do wejścia i zamknął za sobą drzwi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 7, 'I powiedział: Moi bracia, proszę was, nie czyńcie tak niegodziwie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 8, 'Mam dwie córki, które jeszcze nie obcowały z mężczyzną. Pozwólcie, że wyprowadzę je do was, a czyńcie z nimi, co się wam podoba. Tylko tym mężczyznom nic nie czyńcie, bo dlatego weszli pod cień mego dachu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 9, 'A oni odpowiedzieli: Odsuń się! I dodali: Ten przyszedł tu jako przybysz, a nas chce sądzić? Z tobą postąpimy gorzej niż z nimi. I napierali gwałtownie na tego mężczyznę, na Lota, i przybliżyli się, aby wyważyć drzwi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 10, 'Ale ci mężczyźni wysunęli ręce, wciągnęli Lota do siebie, do domu, i zamknęli drzwi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 11, 'Mężczyzn zaś, którzy byli u drzwi domu, od najmniejszego aż do największego, porazili ślepotą, tak że na próżno usiłowali znaleźć drzwi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 12, 'Potem ci mężczyźni powiedzieli do Lota: Jeśli masz tu kogoś jeszcze, zięcia, synów i córki lub kogokolwiek innego w mieście, wyprowadź ich z tego miejsca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 13, 'Zniszczymy bowiem to miejsce, ponieważ ich okrzyk wzmógł się przed Panem i Pan posłał nas, abyśmy je zniszczyli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 14, 'Lot wyszedł więc i powiedział do swoich zięciów, którzy mieli poślubić jego córki: Wstańcie, wyjdźcie z tego miejsca, bo Pan zniszczy to miasto. Ale jego zięciom wydawało się, że żartuje.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 15, 'A gdy już zaczynało świtać, aniołowie ponaglali Lota, mówiąc: Wstań, weź swoją żonę i swoje dwie córki, które tu są, abyś nie zginął z powodu nieprawości tego miasta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 16, 'A gdy się ociągał, ci mężczyźni chwycili jego rękę, rękę jego żony i ręce jego dwóch córek – Pan bowiem ulitował się nad nim – i wyprowadzili go, i pozostawili go poza miastem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 17, 'I gdy wyprowadzili ich stamtąd, on powiedział: Uciekaj, abyś ocalił swoje życie. Nie oglądaj się wstecz ani nie zatrzymuj się nigdzie na tej równinie. Uciekaj na górę, abyś nie zginął.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 18, 'A Lot powiedział do nich: O nie, Panie!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 19, 'Oto twój sługa znalazł łaskę w twoich oczach i pomnożyłeś swoje miłosierdzie, które mi wyświadczyłeś, ratując mi życie; ale ja nie mogę uciec na tę górę, bo może dosięgnie mnie jakieś nieszczęście i zginę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 20, 'Oto jest tu w pobliżu miasto, do którego mógłbym uciec, i jest małe. Proszę, pozwól mi tam uciec (czyż nie jest ono małe?), a moja dusza będzie żyć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 21, 'Odpowiedział mu: Oto wysłuchałem cię w tej sprawie. Nie zniszczę tego miasta, o którym mówiłeś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 22, 'Spiesz się i uchodź tam, bo nie będę mógł nic uczynić, dopóki tam nie dojdziesz. Dlatego dano temu miastu nazwę Soar.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 23, 'Słońce wzeszło nad ziemią, gdy Lot wszedł do Soaru.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 24, 'Wtedy Pan spuścił deszcz siarki i ognia od Pana z nieba na Sodomę i Gomorę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 25, 'I zniszczył te miasta, całą tę równinę i wszystkich mieszkańców tych miast, a także roślinność tej ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 26, 'Lecz żona Lota, idąc za nim, obejrzała się wstecz i stała się słupem soli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 27, 'Abraham zaś wstał rano i udał się na to miejsce, gdzie stał przed Panem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 28, 'Gdy spojrzał w stronę Sodomy i Gomory, i całej ziemi tej równiny, zobaczył, że dym unosił się nad tą ziemią jak dym z pieca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 29, 'A gdy Bóg zniszczył miasta tej równiny, pamiętał Bóg o Abrahamie i wybawił Lota z samego środka zagłady, kiedy zniszczył te miasta, w których Lot mieszkał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 30, 'Potem Lot wyszedł z Soaru i mieszkał na górze ze swoimi dwiema córkami, bo bał się mieszkać w Soarze. Zamieszkał więc w jaskini, on i jego dwie córki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 31, 'I starsza powiedziała do młodszej: Nasz ojciec jest stary, a nie ma na ziemi mężczyzny, który by obcował z nami według zwyczaju całej ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 32, 'Chodź, upójmy naszego ojca winem i położymy się z nim, abyśmy zachowały potomstwo naszego ojca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 33, 'Upoiły więc swego ojca winem tej nocy. I starsza weszła i spała ze swym ojcem, ale on nie spostrzegł ani kiedy się położyła, ani kiedy wstała.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 34, 'Nazajutrz starsza powiedziała do młodszej: Oto zeszłej nocy spałam ze swym ojcem, upójmy go winem także tej nocy, wtedy wejdź ty i połóż się z nim, a tak zachowamy potomstwo naszego ojca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 35, 'Upoiły więc swego ojca winem także i tej nocy. Wtedy młodsza poszła i spała z nim, ale on nie spostrzegł ani kiedy się położyła, ani kiedy wstała.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 36, 'Tak obie córki Lota poczęły ze swego ojca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 37, 'Gdy starsza urodziła syna, nadała mu imię Moab. On jest ojcem dzisiejszych Moabitów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 38, 'Młodsza również urodziła syna i nadała mu imię Ben-Ammi. On jest ojcem synów dzisiejszych Ammonitów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 1, 'Potem Abraham wyruszył stamtąd do ziemi południowej i zamieszkał między Kadesz a Szur, i był przybyszem w Gerarze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 2, 'Tam Abraham powiedział o swej żonie Sarze: Ona jest moją siostrą. Dlatego Abimelek, król Geraru, posłał po Sarę i wziął ją.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 3, 'Lecz Bóg przyszedł do Abimeleka we śnie w nocy i powiedział mu: Umrzesz z powodu tej kobiety, którą wziąłeś, bo ona ma męża.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 4, 'Ale Abimelek jeszcze nie zbliżył się do niej i powiedział: Panie, czy zabijesz też lud sprawiedliwy?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 5, 'Czy on sam nie mówił mi: Ona jest moją siostrą? I czy ona również nie mówiła: On jest moim bratem? Uczyniłem to w prostocie mego serca i z czystymi rękami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 6, 'Wtedy Bóg powiedział mu we śnie: Wiem, że uczyniłeś to w prostocie swego serca. Dlatego powstrzymałem cię, abyś nie zgrzeszył przeciwko mnie, i nie dopuściłem, abyś jej dotknął.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 7, 'Teraz więc zwróć żonę mężowi, bo on jest prorokiem i będzie się modlił za ciebie, a będziesz żył. Jeśli jej nie zwrócisz, wiedz, że na pewno umrzesz, ty i wszystko, co jest twoje.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 8, 'Abimelek wstał zatem wcześnie rano, zwołał wszystkie swoje sługi i do ich uszu opowiedział wszystko. Gdy ci mężczyźni to usłyszeli, bardzo się przestraszyli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 9, 'Potem Abimelek wezwał Abrahama i powiedział mu: Co nam uczyniłeś? W czym zgrzeszyłem przeciwko tobie, że sprowadziłeś na mnie i na moje królestwo tak wielki grzech? Postąpiłeś ze mną tak, jak nie należy postępować.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 10, 'Abimelek zapytał jeszcze Abrahama: Co widziałeś, że tak postąpiłeś?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 11, 'Abraham odpowiedział: Bo myślałem – na pewno nie ma w tym miejscu bojaźni Bożej i zabiją mnie z powodu mojej żony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 12, 'Zresztą ona naprawdę jest moją siostrą, córką mego ojca, choć nie córką mojej matki. I została moją żoną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 13, 'Gdy więc Bóg wyprawił mnie na wędrówkę z domu mego ojca, powiedziałem do niej: Oto przysługa, jaką mi wyświadczysz – w każdym miejscu, do którego przyjdziemy, mów o mnie: To jest mój brat.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 14, 'Wtedy Abimelek wziął owce i woły oraz służących i służące i dał Abrahamowi, i zwrócił mu jego żonę Sarę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 15, 'I Abimelek powiedział: Oto moja ziemia jest przed tobą. Zamieszkaj, gdzie ci się podoba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 16, 'A do Sary powiedział: Dałem twemu bratu tysiąc srebrników. Oto on jest zasłoną twoich oczu u wszystkich, którzy są z tobą, i u wszystkich innych. O tym Sara została pouczona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 17, 'Wtedy Abraham modlił się do Boga i Bóg uzdrowił Abimeleka, a także jego żonę i jego służące, i one rodziły.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 18, 'Pan bowiem zamknął wszystkie łona domu Abimeleka z powodu Sary, żony Abrahama.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 1, 'A Pan nawiedził Sarę, jak powiedział, i uczynił Pan Sarze, jak zapowiedział.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 2, 'Sara poczęła bowiem i urodziła Abrahamowi syna w jego starości w tym czasie, który przepowiedział mu Bóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 3, 'Abraham nadał swemu synowi, który mu się urodził, którego mu urodziła Sara, imię Izaak.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 4, 'I Abraham obrzezał swego syna Izaaka, gdy ten miał osiem dni, jak Bóg mu rozkazał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 5, 'A Abraham miał sto lat, gdy mu się urodził jego syn Izaak.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 6, 'Wtedy Sara powiedziała: Bóg dał mi powód do śmiechu; ktokolwiek o tym usłyszy, będzie się śmiał ze mną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 7, 'I dodała: Kto by powiedział Abrahamowi, że Sara będzie karmiła piersią dzieci? Gdyż urodziłam mu syna w jego starości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 8, 'Dziecko rosło i zostało odstawione od piersi. I Abraham wyprawił wielką ucztę w dniu odstawienia Izaaka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 9, 'Gdy Sara zobaczyła syna Egipcjanki Hagar, którego ta urodziła Abrahamowi, szydzącego;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 10, 'Powiedziała do Abrahama: Wyrzuć tę niewolnicę i jej syna, bo syn tej niewolnicy nie będzie dziedziczyć z moim synem Izaakiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 11, 'Słowa te wydały się Abrahamowi bardzo przykre ze względu na jego syna.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 12, 'Wtedy Bóg powiedział do Abrahama: Niech ci nie będzie przykro z powodu chłopca i twojej niewolnicy. Posłuchaj wszystkiego, co Sara mówi do ciebie, bo w Izaaku będzie nazwane twoje potomstwo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 13, 'Syna zaś tej niewolnicy również uczynię narodem, bo jest on twoim potomstwem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 14, 'Abraham wstał więc wcześnie rano, wziął chleb i bukłak wody i dał Hagar, wkładając jej to na ramię, oraz wziął dziecko i odprawił ją. Ona zaś odeszła i błąkała się po pustyni Beer-Szeby.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 15, 'A gdy skończyła się woda w bukłaku, porzuciła dziecko pod jednym z krzewów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 16, 'Potem odeszła i usiadła naprzeciw niego w odległości strzału z łuku. Mówiła bowiem: Nie będę patrzyła na śmierć dziecka. Usiadła więc naprzeciw niego i zaczęła głośno płakać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 17, 'I Bóg usłyszał głos chłopca, i Anioł Boga zawołał na Hagar z nieba: Co ci jest, Hagar? Nie bój się, bo Bóg usłyszał głos chłopca tam, gdzie jest.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 18, 'Wstań, podnieś chłopca i weź go za rękę, bo uczynię go wielkim narodem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 19, 'Wtedy Bóg otworzył jej oczy i zobaczyła studnię z wodą. Poszła więc, napełniła bukłak wodą i dała chłopcu pić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 20, 'I Bóg był z chłopcem. Urósł i mieszkał na pustyni, i stał się łucznikiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 21, 'A mieszkał na pustyni Paran. I jego matka wzięła dla niego żonę z ziemi Egiptu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 22, 'W tym czasie Abimelek wraz z dowódcą swego wojska Pikolem powiedział do Abrahama: Bóg jest z tobą we wszystkim, co czynisz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 23, 'Teraz więc przysięgnij mi tu na Boga, że nie postąpisz zdradliwie wobec mnie ani mego syna, ani mego wnuka. Ale według miłosierdzia, które ci okazałem, postąpisz ze mną i z ziemią, w której jesteś przybyszem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 24, 'Abraham odpowiedział: Przysięgam.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 25, 'I Abraham poskarżył się Abimelekowi z powodu studni z wodą, którą mu przemocą zabrali słudzy Abimeleka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 26, 'Abimelek powiedział: Nie wiem, kto to uczynił. Ani nie powiedziałeś mi o tym, ani nie słyszałem o tym aż dopiero dziś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 27, 'Abraham wziął więc owce i woły i dał je Abimelekowi, i obaj zawarli przymierze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 28, 'I Abraham wydzielił z trzody siedmioro jagniąt.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 29, 'Abimelek zapytał Abrahama: Po co te siedmioro jagniąt, które postawiłeś osobno?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 30, 'A on odpowiedział: Te siedem owiec weźmiesz z moich rąk, aby były świadectwem, że wykopałem tę studnię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 31, 'Dlatego nazwano to miejsce Beer-Szeba, bo tam obaj sobie przysięgli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 32, 'Tak zawarli przymierze w Beer-Szebie. Potem Abimelek i Pikol, dowódca jego wojska, wstali i wrócili do ziemi Filistynów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 33, 'Abraham zaś zasadził drzewa w Beer-Szebie i wzywał tam imienia Pana, Boga wiecznego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 34, 'I Abraham gościł w ziemi Filistynów przez wiele dni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 1, 'Po tych wydarzeniach Bóg wystawił Abrahama na próbę i powiedział do niego: Abrahamie! A on odpowiedział: Oto jestem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 2, 'I Bóg powiedział: Weź teraz swego syna, twego jedynego, którego miłujesz, Izaaka, idź do ziemi Moria i tam złóż go na ofiarę całopalną na jednej górze, o której ci powiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 3, 'Abraham wstał więc wcześnie rano, osiodłał swego osła i wziął ze sobą dwóch służących i swego syna Izaaka, narąbał drew na ofiarę całopalną, wstał i poszedł na miejsce, o którym mu Bóg powiedział.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 4, 'A trzeciego dnia Abraham podniósł swe oczy i zobaczył z daleka to miejsce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 5, 'Wtedy Abraham powiedział do swoich służących: Zostańcie tu z osłem, a ja i chłopiec pójdziemy tam, oddamy cześć Bogu i wrócimy do was.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 6, 'Wziął więc Abraham drwa na ofiarę całopalną i włożył je na swego syna Izaaka, a sam wziął do ręki ogień i nóż i poszli obaj razem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 7, 'I Izaak powiedział do swego ojca Abrahama: Mój ojcze! A on odpowiedział: Oto jestem, mój synu. I Izaak zapytał: Oto ogień i drwa, a gdzie jest baranek na ofiarę całopalną?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 8, 'Abraham odpowiedział: Bóg sobie upatrzy baranka na ofiarę całopalną, mój synu. I szli obaj razem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 9, 'A gdy przyszli na miejsce, o którym mu Bóg powiedział, Abraham zbudował tam ołtarz, ułożył na nim drwa, związał swego syna Izaaka i położył go na ołtarzu na drwach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 10, 'Potem Abraham wyciągnął rękę i wziął nóż, aby zabić swego syna.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 11, 'Lecz Anioł Pana zawołał do niego z nieba: Abrahamie, Abrahamie! A on odpowiedział: Oto jestem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 12, 'Anioł powiedział: Nie podnoś ręki na chłopca i nic mu nie czyń, bo teraz wiem, że boisz się Boga i nie odmówiłeś mi swego jedynego syna.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 13, 'A Abraham podniósł swe oczy i spojrzał, a oto za nim baran zaplątał się rogami w zaroślach. Abraham poszedł więc i wziął barana, i złożył go na ofiarę całopalną zamiast swego syna.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 14, 'I Abraham nadał temu miejscu nazwę: Pan upatrzy. Dlatego po dziś dzień mówią: Na górze Pana będzie upatrzony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 15, 'Wtedy Anioł Pana ponownie zawołał z nieba na Abrahama:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 16, 'Przysiągłem na siebie samego, mówi Pan: Ponieważ to uczyniłeś i nie odmówiłeś mi swego syna, twego jedynego;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 17, 'Błogosławiąc, będę ci błogosławić, a rozmnażając, rozmnożę twoje potomstwo jak gwiazdy na niebie i jak piasek na brzegu morza; a twoje potomstwo odziedziczy bramy swoich nieprzyjaciół.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 18, 'I w twoim potomstwie będą błogosławione wszystkie narody ziemi, dlatego że posłuchałeś mojego głosu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 19, 'Abraham wrócił więc do swoich służących i wstali, i wspólnie udali się do Beer-Szeby. Abraham bowiem mieszkał w Beer-Szebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 20, 'Po tych wydarzeniach doniesiono Abrahamowi: Oto Milka również urodziła dzieci twemu bratu Nachorowi;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 21, 'Usa, jego pierworodnego, Buza, jego brata, i Kemuela, ojca Arama;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 22, 'I Keseda, Chazo, Pildasza, Jidlafa i Betuela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 23, 'Betuel zaś spłodził Rebekę. Tych ośmiu urodziła Milka Nachorowi, bratu Abrahama.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 24, 'A jego nałożnica, której imię było Reuma, urodziła też Tebacha, Gachama, Tachasza i Maakę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 1, 'A Sara dożyła stu dwudziestu siedmiu lat. Tyle było lat życia Sary.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 2, 'Sara umarła w mieście Kiriat-Arba, czyli w Hebronie, w ziemi Kanaan. I Abraham przyszedł, aby odbyć żałobę po Sarze i opłakiwać ją.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 3, 'Potem Abraham wstał od swej zmarłej i powiedział do synów Cheta:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 4, 'Jestem wśród was przybyszem i przychodniem. Dajcie mi na własność grób między wami, abym pogrzebał moją zmarłą sprzed mojego oblicza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 5, 'Synowie Cheta odpowiedzieli Abrahamowi:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 6, 'Słuchaj nas, mój panie: Jesteś księciem Boga wśród nas. Pochowaj swoją zmarłą w naszych najlepszych grobach. Nikt z nas nie odmówi ci swego grobu, abyś pochował swoją zmarłą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 7, 'Wtedy Abraham wstał, pokłonił się ludowi tej ziemi, czyli synom Cheta;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 8, 'I powiedział do nich: Jeśli zgadzacie się, abym pochował moją zmarłą sprzed mojego oblicza, posłuchajcie mnie i wstawcie się za mną do Efrona, syna Sochara;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 9, 'Aby mi ustąpił swą jaskinię Makpela, która znajduje się na końcu jego pola. Niech mi ją odda za odpowiednią cenę jako grób na własność wśród was.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 10, 'A Efron siedział wśród synów Cheta. Odpowiedział więc Efron Chetyta Abrahamowi w obecności synów Cheta i wszystkich, którzy wchodzili w bramę jego miasta:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 11, 'Nie, panie mój, posłuchaj mnie. Daję ci to pole i jaskinię, która na nim jest. Daję ją tobie w obecności synów mego ludu. Pochowaj swoją zmarłą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 12, 'Wtedy Abraham pokłonił się przed ludem tej ziemi;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 13, 'I powiedział do Efrona w obecności ludu tej ziemi: Raczej jeśli się da, proszę, posłuchaj mnie. Dam ci pieniądze za pole, weź je ode mnie, a pochowam tam moją zmarłą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 14, 'Efron odpowiedział Abrahamowi:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 15, 'Mój panie, posłuchaj mnie. Ta ziemia jest warta czterysta syklów srebra, ale cóż to jest między mną a tobą? Pochowaj swoją zmarłą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 16, 'I Abraham wysłuchał Efrona. Odważył więc Abraham Efronowi srebro, które ten wymienił w obecności synów Cheta: czterysta syklów srebra, jakie były w obiegu u kupców.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 17, 'Tak więc pole Efrona, które jest w Makpelu naprzeciw Mamre, pole i jaskinia, która na nim jest, i wszystkie drzewa, które były na polu i wkoło na wszystkich jego granicach, przeszły;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 18, 'Na własność Abrahama w obecności synów Cheta i wszystkich, którzy wchodzili w bramę tego miasta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 19, 'Potem Abraham pochował swoją żonę Sarę w jaskini pola w Makpelu naprzeciwko Mamre, czyli Hebronie, w ziemi Kanaan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 20, 'I zostały oddane Abrahamowi pole i jaskinia, która była na nim, jako grób na własność, przez synów Cheta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 1, 'A Abraham był stary, w podeszłym wieku, a Pan błogosławił mu we wszystkim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 2, 'I Abraham powiedział do swego starszego sługi w swym domu, który zarządzał wszystkim, co miał: Połóż, proszę, swą rękę pod moje biodro;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 3, 'I przysięgnij mi na Pana, Boga nieba i Boga ziemi, że nie weźmiesz dla mego syna żony z córek Kananejczyków, wśród których mieszkam;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 4, 'Ale pójdziesz do mojej ziemi i do mojej rodziny i stamtąd weźmiesz żonę dla mego syna Izaaka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 5, 'Sługa mu odpowiedział: A jeśli kobieta nie zechce pójść ze mną do tej ziemi, czy wtedy mam zaprowadzić twego syna do ziemi, z której wyszedłeś?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 6, 'Abraham mu odpowiedział: Strzeż się, abyś tam nie zaprowadził mego syna.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 7, 'Pan Bóg nieba, który mnie wziął z domu mego ojca i z ziemi mojej rodziny i który mówił ze mną, i przysiągł mi: Twemu potomstwu dam tę ziemię; on pośle przed tobą swego anioła i weźmiesz stamtąd żonę dla mego syna.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 8, 'A jeśli ta kobieta nie zechce pójść z tobą, będziesz zwolniony z mojej przysięgi. Tylko nie prowadź tam mego syna.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 9, 'Wtedy sługa podłożył rękę pod biodro swego pana Abrahama i przysiągł mu to.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 10, 'Potem ów sługa wziął dziesięć wielbłądów z wielbłądów swego pana i poszedł – bo miał w swych rękach wszystkie dobra swego pana. Wstał i udał się do Aram-Naharaim, do miasta Nachora.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 11, 'I dał wielbłądom odpocząć przy studni poza miastem w wieczornej porze, w tym czasie, kiedy kobiety zwykły wychodzić czerpać wodę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 12, 'I powiedział: Panie, Boże mego pana Abrahama, daj mi, proszę, pomyślne spotkanie i okaż łaskę mojemu panu Abrahamowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 13, 'Oto stoję przy studni, a córki mieszkańców tego miasta wyjdą czerpać wodę;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 14, 'Niech dziewczyna, której powiem: Przechyl, proszę, twój dzban, abym mógł się napić, a ona odpowie: Pij i napoję także twoje wielbłądy – będzie tą, którą przeznaczyłeś dla twego sługi Izaaka; a po tym poznam, że okazałeś łaskę mojemu panu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 15, 'I zanim przestał mówić, oto wyszła Rebeka, która się urodziła Betuelowi, synowi Milki, żony Nachora, brata Abrahama, z dzbanem na ramieniu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 16, 'Była ona bardzo piękną dziewczyną, dziewicą, z którą nie obcował żaden mężczyzna. Zeszła do studni, napełniła swój dzban i wracała.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 17, 'Wtedy ów sługa wybiegł do niej i powiedział: Proszę, pozwól mi się napić trochę wody z twego dzbana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 18, 'A ona odpowiedziała: Pij, panie mój. I szybko pochyliła swój dzban na swoją rękę, i dała mu pić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 19, 'A gdy dała mu się napić, powiedziała: Naczerpię wody także dla twoich wielbłądów, aby napiły się do woli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 20, 'Wylała prędko wodę ze swego dzbana w koryto i pobiegła znowu do studni czerpać wodę, i naczerpała dla wszystkich jego wielbłądów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 21, 'A ów mężczyzna zdumiewał się nią, zastanawiając się w milczeniu, czy Pan poszczęścił jego podróży, czy nie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 22, 'Gdy więc wielbłądy się napiły, ów mężczyzna wyjął i dał na jej ręce złoty kolczyk ważący pół sykla i dwie bransolety ważące dziesięć syklów złota.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 23, 'I zapytał: Czyją jesteś córką? Powiedz mi, proszę. Czy jest w domu twego ojca miejsce dla nas na nocleg?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 24, 'A ona mu odpowiedziała: Jestem córką Betuela, syna Milki, którego urodziła Nachorowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 25, 'Po czym dodała: Jest u nas dosyć słomy i paszy oraz miejsce na nocleg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 26, 'I ów mężczyzna uklęknął i oddał pokłon Panu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 27, 'I powiedział: Błogosławiony Pan, Bóg mego pana Abrahama, który nie oddalił swego miłosierdzia i swojej prawdy od mego pana, bo gdy byłem w drodze, Pan przyprowadził mnie do domu braci mego pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 28, 'I dziewczyna pobiegła, i w domu swej matki oznajmiła, co się stało.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 29, 'A Rebeka miała brata imieniem Laban. I Laban wybiegł do tego człowieka, do studni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 30, 'Gdy zobaczył kolczyk i bransolety na rękach swej siostry i usłyszał słowa swej siostry Rebeki: Tak mówił do mnie ten człowiek, podszedł do tego człowieka, a oto on stał przy wielbłądach u studni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 31, 'I powiedział do niego: Wejdź, błogosławiony przez Pana. Czemu stoisz na dworze? Przygotowałem już dom i miejsce dla wielbłądów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 32, 'Wszedł więc ów człowiek do domu. I Laban rozsiodłał wielbłądy, i dał słomy i paszy wielbłądom, i wody do umycia jego nóg oraz nóg tych mężczyzn, którzy z nim byli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 33, 'I położył przed nim jedzenie, aby jadł, ale on powiedział: Nie będę jadł, dopóki nie przedstawię swojej sprawy. Laban powiedział: Mów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 34, 'I powiedział: Jestem sługą Abrahama.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 35, 'Pan pobłogosławił bardzo mego pana i stał się on zamożny. Dał mu bowiem owce i woły, srebra i złota, służących i służące, wielbłądy i osły.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 36, 'A Sara, żona mego pana, urodziła memu panu w jego starości syna, któremu dał wszystko, co ma.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 37, 'I mój pan kazał mi przysiąc, mówiąc: Nie weźmiesz dla mego syna żony z córek Kananejczyków, w których ziemi mieszkam;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 38, 'Ale pójdziesz do domu mego ojca i do moich krewnych i stamtąd weźmiesz żonę dla mojego syna.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 39, 'I zapytałem mego pana: A jeśli ta kobieta nie zechce pójść ze mną?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 40, 'Odpowiedział mi: Pan, przed którym chodzę, pośle swego anioła z tobą i poszczęści twojej drodze; i weźmiesz dla mego syna żonę spośród moich krewnych i z domu mego ojca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 41, 'Będziesz jednak zwolniony z mojej przysięgi, jeśli przyjdziesz do moich krewnych, a oni ci jej nie dadzą. Wtedy będziesz wolny od mojej przysięgi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 42, 'Przyszedłem więc dziś do studni i powiedziałem: Panie, Boże mego pana Abrahama, jeśli teraz chcesz poszczęścić mojej podróży, którą odbywam;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 43, 'Oto stoję przy studni wody. Niech panna, która wyjdzie czerpać wodę, a której powiem: Daj mi, proszę, napić się trochę wody z twego dzbana;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 44, 'A ona odpowie mi: I ty pij, naczerpię też dla twoich wielbłądów – niech ona będzie żoną, którą przeznaczył Pan dla syna mego pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 45, 'Zanim przestałem mówić w swym sercu, oto przyszła Rebeka, niosąc swój dzban na ramieniu, i zeszła do studni, i czerpała. Powiedziałem do niej: Proszę, daj mi pić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 46, 'A ona szybko zdjęła swój dzban i powiedziała: Pij, a twoje wielbłądy też napoję. Piłem więc, a ona napoiła też wielbłądy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 47, 'I zapytałem ją: Czyją jesteś córką? Odpowiedziała: Jestem córką Betuela, syna Nachora, którego urodziła mu Milka. Wtedy włożyłem kolczyk na jej twarz i bransolety na jej ręce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 48, 'Potem uklęknąłem i oddałem pokłon Panu, i błogosławiłem Pana, Boga mego pana Abrahama, który mnie prowadził właściwą drogą, abym wziął córkę brata mego pana dla jego syna.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 49, 'Teraz więc, jeśli chcecie postąpić życzliwie i właściwie wobec mojego pana, powiedzcie mi. A jeśli nie, to też mi powiedzcie, żebym zwrócił się w prawo lub w lewo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 50, 'Wtedy Laban i Betuel odpowiedzieli: Ta sprawa pochodzi od Pana. My nie możemy ci powiedzieć ani dobrze, ani źle.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 51, 'Oto przed tobą Rebeka, weź ją i idź, niech będzie żoną syna twego pana, jak powiedział Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 52, 'Gdy sługa Abrahama usłyszał ich słowa, uklęknął na ziemi i oddał pokłon Panu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 53, 'Następnie ów sługa wyjął srebrne i złote klejnoty, i szaty i oddał je Rebece. Dał też kosztowności jej bratu i matce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 54, 'Potem jedli i pili, on i mężczyźni, którzy z nim byli, i zostali tam na noc. A gdy wstali rano, on powiedział: Odprawcie mnie do mego pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 55, 'Jej brat i matka powiedzieli: Niech dziewczyna zostanie z nami chociaż dziesięć dni, a potem pójdzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 56, 'A on powiedział do nich: Nie zatrzymujcie mnie, skoro Pan poszczęścił mojej drodze; odprawcie mnie, abym jechał do mego pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 57, 'Odpowiedzieli: Zawołajmy dziewczynę i spytajmy, co na to powie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 58, 'Zawołali więc Rebekę i zapytali ją: Czy chcesz jechać z tym człowiekiem? A ona odpowiedziała: Pojadę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 59, 'Wtedy wyprawili swoją siostrę Rebekę, jej mamkę, sługę Abrahama i jego ludzi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 60, 'I błogosławili Rebece, mówiąc jej: Jesteś naszą siostrą, rozmnóż się w tysiąc tysięcy, a twoje potomstwo niech posiądzie bramy swych nieprzyjaciół.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 61, 'Potem Rebeka ze swymi służącymi wstała i wsiadła na wielbłądy, i jechały za tym mężczyzną. Sługa ów wziął Rebekę i odjechał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 62, 'A Izaak właśnie wracał od studni Lachaj-Roj, bo mieszkał w ziemi południowej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 63, 'I wyszedł Izaak na pole pod wieczór, aby rozmyślać. Gdy podniósł swe oczy, zobaczył zbliżające się wielbłądy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 64, 'Rebeka też podniosła swe oczy i zobaczyła Izaaka, i zsiadła z wielbłąda;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 65, 'Bo zapytała sługę: Kim jest ten mężczyzna, który idzie do nas przez pole? I sługa odpowiedział: To jest mój pan. A ona wzięła zasłonę i nakryła się.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 66, 'I opowiedział ów sługa Izaakowi o wszystkim, co zrobił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 67, 'A Izaak wprowadził ją do namiotu swojej matki Sary i wziął Rebekę za żonę, i kochał ją. I Izaak pocieszył się po śmierci swojej matki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 1, 'Potem Abraham pojął drugą żonę, której było na imię Ketura.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 2, 'Ona urodziła mu Zimrana, Jokszana, Medana, Midiana, Jiszbaka i Szuacha.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 3, 'Jokszan spłodził Szebę i Dedana. A synami Dedana byli Aszszurim, Letuszim i Leummim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 4, 'Synami Midiana byli: Efa, Efer, Henoch, Abida i Eldaa. Wszyscy oni byli synami Ketury.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 5, 'I Abraham dał Izaakowi wszystko, co miał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 6, 'A synom nałożnic, które miał, Abraham dał upominki i jeszcze za swojego życia wyprawił ich z dala od swego syna Izaaka ku wschodowi, do ziemi wschodniej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 7, 'Oto liczba lat życia, których dożył Abraham: sto siedemdziesiąt pięć lat.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 8, 'Abraham oddał ducha i umarł w dobrej starości, podeszły w latach i syty życia; i został przyłączony do swego ludu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 9, 'I jego synowie, Izaak i Izmael, pochowali go w jaskini Makpela, na polu Efrona, syna Sochara Chetyty, które było naprzeciwko Mamre;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 10, 'Na polu, które Abraham kupił od synów Cheta. Tam zostali pochowani Abraham i Sara, jego żona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 11, 'A po śmierci Abrahama Bóg błogosławił jego synowi Izaakowi, a Izaak mieszkał przy studni Lachaj-Roj.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 12, 'To są dzieje rodu Izmaela, syna Abrahama, którego urodziła Abrahamowi Hagar, Egipcjanka, służąca Sary.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 13, 'I to są imiona synów Izmaela według ich rodów: Nebajot, pierworodny Izmaela, po nim Kedar, Abdeel i Mibsam;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 14, 'Miszma, Duma i Massa;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 15, 'Chadar, Tema, Jetur, Nafisz i Kedma.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 16, 'To są synowie Izmaela, a to ich imiona według ich miasteczek i zamków; dwunastu książąt w ich narodach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 17, 'A lat życia Izmaela było sto trzydzieści siedem. Oddał ducha i umarł, i został przyłączony do swego ludu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 18, 'I mieszkali od Chawila aż do Szur, który leży naprzeciwko Egiptu, na drodze do Asyrii. I umarł w obecności wszystkich swych braci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 19, 'To zaś są dzieje rodu Izaaka, syna Abrahama: Abraham spłodził Izaaka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 20, 'Izaak miał czterdzieści lat, gdy pojął za żonę Rebekę, córkę Betuela Syryjczyka, z Paddan-Aram, siostrę Labana, Syryjczyka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 21, 'A Izaak modlił się do Pana za swoją żonę, gdyż była niepłodna. I Pan go wysłuchał, i jego żona Rebeka poczęła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 22, 'A gdy dzieci walczyły ze sobą w jej łonie, powiedziała: Jeśli tak się zdarza, dlaczego poczęłam? Poszła więc, aby zapytać Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 23, 'I Pan jej odpowiedział: Dwa narody są w twoim łonie i dwa ludy wyjdą z twego wnętrza. Jeden lud będzie mocniejszy niż drugi i starszy będzie służył młodszemu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 24, 'A gdy nadszedł czas porodu, okazało się, że w jej łonie były bliźnięta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 25, 'I wyszedł pierwszy syn czerwony i cały pokryty owłosieniem jak szatą; i nadali mu imię Ezaw.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 26, 'A potem wyszedł jego brat, trzymając swą ręką za piętę Ezawa, i nadano mu imię Jakub. Izaak miał sześćdziesiąt lat, gdy oni mu się urodzili.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 27, 'A gdy dzieci urosły, Ezaw został człowiekiem biegłym w myślistwie i człowiekiem pola. Jakub zaś był człowiekiem spokojnym, mieszkającym w namiotach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 28, 'I Izaak kochał Ezawa, bo jadał z jego łowu, Rebeka zaś kochała Jakuba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 29, 'I Jakub ugotował sobie potrawę, a w tym czasie przyszedł Ezaw z pola spracowany.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 30, 'Ezaw powiedział więc do Jakuba: Daj mi jeść, proszę cię, z tej czerwonej potrawy, bo jestem spracowany. Dlatego nadano mu imię Edom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 31, 'Jakub powiedział: Sprzedaj mi dziś twoje pierworództwo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 32, 'A Ezaw odpowiedział: Oto jestem bliski śmierci, na cóż mi pierworództwo?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 33, 'Jakub powiedział: Przysięgnij mi dziś. Przysiągł mu więc i sprzedał Jakubowi swoje pierworództwo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 34, 'Jakub dał więc Ezawowi chleba i potrawę z soczewicy, a on jadł i pił, a potem powstał i poszedł. W ten sposób Ezaw pogardził swoim pierworództwem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 1, 'Potem nastał głód na ziemi, po tym pierwszym głodzie, który był za dni Abrahama. Izaak udał się więc do Abimeleka, króla Filistynów, do Geraru.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 2, 'Wtedy Pan ukazał mu się i powiedział: Nie idź do Egiptu, ale mieszkaj w ziemi, którą ci wskażę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 3, 'Bądź przybyszem w tej ziemi, a ja będę z tobą i będę ci błogosławił. Tobie bowiem i twemu potomstwu dam te wszystkie krainy i dotrzymam przysięgi, którą złożyłem twemu ojcu Abrahamowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 4, 'I rozmnożę twoje potomstwo jak gwiazdy na niebie, i dam twemu potomstwu wszystkie te krainy. A będą błogosławione w twoim potomstwie wszystkie narody ziemi;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 5, 'Dlatego że Abraham posłuchał mego głosu i strzegł mego nakazu, moich przykazań, moich ustaw i moich praw.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 6, 'Izaak zamieszkał więc w Gerarze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 7, 'A gdy mężczyźni tego miejsca pytali o jego żonę, odpowiedział: To moja siostra. Bał się bowiem mówić: To moja żona, by mężczyźni tego miejsca nie zabili go z powodu Rebeki, bo była bardzo piękna.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 8, 'Gdy mieszkał tam już dłuższy czas, król Filistynów Abimelek wyjrzał przez okno i zobaczył, że Izaak pieścił swą żonę Rebekę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 9, 'Abimelek wezwał więc Izaaka i powiedział: To jest na pewno twoja żona. Dlaczego mówiłeś: To moja siostra? Izaak mu odpowiedział: Bo mówiłem sobie: Abym nie umarł z jej powodu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 10, 'Abimelek powiedział: Coś ty nam zrobił? Mało brakowało, a ktoś z ludu spałby z twoją żoną i tak sprowadziłbyś na nas grzech.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 11, 'Rozkazał więc Abimelek całemu ludowi: Kto by dotknął tego człowieka albo jego żony, na pewno umrze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 12, 'Wówczas Izaak posiał w tej ziemi i zebrał w tym roku stokrotny plon, bo Pan mu błogosławił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 13, 'I wzbogacił się ów człowiek, i rozwijał się coraz bardziej, aż stał się bardzo zamożny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 14, 'Miał trzody owiec i stada wołów oraz wiele sług, tak że Filistyni mu zazdrościli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 15, 'I wszystkie studnie, które wykopali słudzy jego ojca, za dni jego ojca Abrahama, Filistyni zasypali i napełnili je ziemią.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 16, 'I Abimelek powiedział do Izaaka: Odejdź od nas, bo jesteś dużo zamożniejszy od nas.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 17, 'Izaak odszedł więc stamtąd i rozbił namioty w dolinie Gerar, i tam zamieszkał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 18, 'Potem Izaak na nowo odkopał studnie, które wykopali za dni jego ojca Abrahama, a które Filistyni zasypali po śmierci Abrahama, i nadał im te same nazwy, jakie nadał im jego ojciec.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 19, 'Wtedy słudzy Izaaka kopali w tej dolinie i znaleźli tam studnię ze źródlaną wodą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 20, 'Lecz pasterze z Geraru kłócili się z pasterzami Izaaka, mówiąc: To nasza woda. Nazwał więc tę studnię Esek, bo spierali się z nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 21, 'Gdy wykopali drugą studnię, również kłócili się o nią. Dlatego nazwał ją Sitna.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 22, 'Potem przeniósł się stamtąd i wykopał kolejną studnię, o którą już nie było sporu. Nazwał ją więc Rechobot i mówił: Oto teraz Pan dał nam miejsce, abyśmy się rozmnażali na ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 23, 'I wyruszył stamtąd do Beer-Szeby.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 24, 'Tej nocy ukazał mu się Pan i powiedział: Ja jestem Bogiem twego ojca Abrahama. Nie bój się, bo jestem z tobą. Będę ci błogosławił i rozmnożę twoje potomstwo ze względu na mego sługę Abrahama.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 25, 'Zbudował więc tam ołtarz i wzywał imienia Pana, i rozbił tam swój namiot. Tam też słudzy Izaaka wykopali studnię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 26, 'Wtedy przybyli do niego z Geraru Abimelek i Achuzat, jeden z jego przyjaciół, oraz dowódca jego wojska Pikol.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 27, 'Izaak zapytał ich: Po co przybyliście do mnie, skoro mnie nienawidzicie i wypędziliście mnie od siebie?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 28, 'A oni odpowiedzieli: Zobaczyliśmy naprawdę, że Pan jest z tobą, więc powiedzieliśmy: Niech będzie teraz przysięga między nami, między nami a tobą, i ustanowimy przymierze z tobą;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 29, 'Abyś nam nie czynił nic złego, jak i my też nie dotknęliśmy ciebie i tylko dobrze ci czyniliśmy, i pozwoliliśmy ci odejść w pokoju; a ty teraz jesteś błogosławiony przez Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 30, 'Wtedy wyprawił im ucztę; jedli więc i pili.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 31, 'Nazajutrz wstali wcześnie rano i złożyli sobie wzajemnie przysięgę. Potem Izaak pożegnał się z nimi i odeszli od niego w pokoju.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 32, 'Tego samego dnia słudzy Izaaka przyszli i opowiedzieli mu o studni, którą wykopali: Znaleźliśmy wodę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 33, 'I nazwał ją Szibea. Dlatego to miasto nazywa się Beer-Szeba aż do dzisiaj.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 34, 'Gdy Ezaw miał czterdzieści lat, pojął sobie za żonę Judytę, córkę Beeriego Chetyty, i Bosmat, córkę Elona Chetyty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 35, 'Były one przyczyną utrapień Izaaka i Rebeki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 1, 'A gdy Izaak się zestarzał i jego oczy osłabły, tak że nie mógł widzieć, wezwał swego starszego syna Ezawa i powiedział do niego: Synu mój! A on odpowiedział: Oto jestem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 2, 'Izaak powiedział: Oto zestarzałem się już i nie znam dnia swojej śmierci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 3, 'Teraz więc weź, proszę, swoją broń, kołczan i łuk, wyjdź na pole i upoluj mi zwierzynę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 4, 'I przygotuj mi smaczną potrawę, jaką lubię, i przynieś mi ją, a będę jadł, aby moja dusza błogosławiła ci, zanim umrę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 5, 'A Rebeka słyszała, gdy Izaak mówił do swego syna Ezawa. I Ezaw wyszedł na pole, aby upolować zwierzynę i ją przynieść.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 6, 'I Rebeka powiedziała do swego syna Jakuba: Słyszałam, jak twój ojciec mówił do twego brata Ezawa:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 7, 'Przynieś mi zwierzynę i przygotuj mi smaczną potrawę, abym jadł i błogosławił ci przed Panem, zanim umrę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 8, 'Teraz więc, mój synu, posłuchaj mego głosu w tym, co ci każę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 9, 'Idź do trzody i przynieś mi stamtąd dwoje dobrych koźląt, a przygotuję z nich dla twego ojca smaczną potrawę, jaką lubi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 10, 'I zaniesiesz twemu ojcu, i będzie jadł, aby ci błogosławił, zanim umrze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 11, 'Wtedy Jakub powiedział do swej matki Rebeki: Przecież mój brat Ezaw jest człowiekiem owłosionym, a ja jestem człowiekiem gładkim;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 12, 'Jeśli mój ojciec mnie dotknie, okażę się w jego oczach oszustem, ściągnę na siebie przekleństwo, a nie błogosławieństwo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 13, 'Jego matka odpowiedziała mu: Mój synu, niech na mnie spadnie twoje przekleństwo. Tylko posłuchaj mego głosu, idź i przynieś mi je.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 14, 'Poszedł więc, wziął i przyniósł je swej matce, a ona przygotowała smaczną potrawę, jaką lubił jego ojciec.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 15, 'Potem Rebeka wzięła szaty swego starszego syna Ezawa, najcenniejsze, jakie miała u siebie w domu, i ubrała w nie swego młodszego syna Jakuba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 16, 'A skórkami koźląt owinęła mu ręce i gładką szyję.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 17, 'I dała chleb i smaczną potrawę, którą przygotowała, w ręce swego syna Jakuba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 18, 'A on poszedł do swego ojca i powiedział: Mój ojcze! A on odpowiedział: Oto jestem. Kto ty jesteś, mój synu?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 19, 'Jakub odpowiedział swemu ojcu: Ja jestem Ezaw, twój pierworodny. Zrobiłem, jak mi kazałeś. Podnieś się, proszę, siądź i jedz z mojej zwierzyny, aby mi błogosławiła twoja dusza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 20, 'Izaak zapytał swego syna: Jakże tak szybko to znalazłeś, mój synu? A on odpowiedział: To Pan, twój Bóg, sprawił, że mi się udało.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 21, 'Potem Izaak powiedział do Jakuba: Zbliż się, proszę, abym cię dotknął, mój synu, czy ty jesteś moim synem Ezawem, czy nie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 22, 'Jakub podszedł więc do swego ojca Izaaka, który dotknął go i powiedział: Głos jest głosem Jakuba, ale ręce są rękami Ezawa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 23, 'I nie rozpoznał go, bo jego ręce były owłosione jak ręce jego brata Ezawa. I błogosławił mu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 24, 'I zapytał: Czy ty jesteś moim synem Ezawem? A on odpowiedział: Jestem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 25, 'Potem powiedział: Podaj mi, żebym jadł ze zwierzyny mego syna, aby błogosławiła ci moja dusza. Wtedy podał mu i jadł. Przyniósł mu też wina, a on pił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 26, 'Jego ojciec Izaak powiedział mu: Podejdź teraz i pocałuj mnie, mój synu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 27, 'Podszedł więc i pocałował go. Gdy poczuł zapach jego szat, błogosławił mu, mówiąc: Oto zapach mego syna jak zapach pola, które Pan błogosławił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 28, 'Niech Bóg da ci z rosy nieba i żyzność ziemi oraz obfitość zboża i wina.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 29, 'Niech ludzie ci służą i niech ci się kłaniają narody. Bądź panem twoich braci i niech ci się kłaniają synowie twojej matki. Niech będzie przeklęty, kto cię przeklina, a niech będzie błogosławiony, kto cię błogosławi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 30, 'Gdy Izaak skończył błogosławić Jakuba i ledwie Jakub odszedł sprzed oblicza swego ojca Izaaka, jego brat Ezaw wszedł z łowów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 31, 'On także przygotował smaczną potrawę, przyniósł ją swemu ojcu i powiedział mu: Podnieś się, mój ojcze, i jedz ze zwierzyny twego syna, aby błogosławiła mi twoja dusza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 32, 'Jego ojciec Izaak zapytał go: Kim jesteś? A on odpowiedział: Jestem twoim synem, twoim pierworodnym, Ezawem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 33, 'Wtedy Izaak bardzo się przeraził i zapytał: Któż to? A gdzie jest ten, co ułowił zwierzynę i przyniósł mi, a ja jadłem ze wszystkiego, zanim ty przyszedłeś, i błogosławiłem mu? Będzie więc błogosławionym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 34, 'A gdy Ezaw usłyszał słowa swego ojca, podniósł donośny krzyk pełen goryczy i powiedział swemu ojcu: Błogosław też i mi, mój ojcze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 35, 'A on mu powiedział: Twój brat podstępnie przyszedł i wziął twoje błogosławieństwo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 36, 'Ezaw powiedział: Czy nie słusznie nadano mu imię Jakub? Podszedł mnie bowiem już dwukrotnie: wziął moje pierworództwo, a teraz zabrał moje błogosławieństwo. I zapytał: Czy nie zachowałeś dla mnie błogosławieństwa?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 37, 'Izaak odpowiedział Ezawowi: Ustanowiłem go panem nad tobą i wszystkich jego braci dałem mu za sługi, i zapewniłem mu zboże i wino. Cóż więc mogę dla ciebie zrobić, mój synu?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 38, 'I Ezaw powiedział do swego ojca: Czy masz tylko jedno błogosławieństwo, mój ojcze? Błogosław także i mnie, mój ojcze. I Ezaw podniósł głos i zapłakał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 39, 'I jego ojciec Izaak odpowiedział mu: Twoje mieszkanie będzie z żyznej ziemi i z rosy nieba z góry.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 40, 'A będziesz żył z twego miecza i będziesz służył twemu bratu. Ale gdy stanie się, że będziesz panował, zrzucisz jego jarzmo z twojej szyi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 41, 'Dlatego Ezaw nienawidził Jakuba z powodu błogosławieństwa, którym mu błogosławił jego ojciec. I Ezaw mówił w swym sercu: Zbliżają się dni żałoby po moim ojcu, wtedy zabiję mego brata Jakuba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 42, 'I doniesiono Rebece o słowach jej starszego syna Ezawa. Kazała więc przywołać swego młodszego syna Jakuba i powiedziała do niego: Oto twój brat Ezaw pociesza się tym, że cię zabije.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 43, 'Teraz więc, mój synu, posłuchaj mego głosu, wstań i uciekaj do mego brata Labana, do Charanu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 44, 'Pozostań u niego przez pewien czas, aż ucichnie gniew twego brata;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 45, 'Aż ustąpi zapalczywość twego brata na ciebie i zapomni o tym, co mu zrobiłeś. Wtedy każę cię stamtąd sprowadzić. Czemu mam być pozbawiona was obu w jednym dniu?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 46, 'I Rebeka powiedziała do Izaaka: Obrzydło mi życie z powodu córek Cheta. Jeśli Jakub też weźmie sobie żonę z córek Cheta, jakie są na tej ziemi, po co mi życie?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 1, 'Wtedy Izaak wezwał Jakuba i błogosławił mu, i rozkazał: Nie bierz sobie żony z córek Kanaanu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 2, 'Ale wstań i idź do krainy Paddan-Aram, do domu Betuela, ojca twojej matki, i weź sobie stamtąd żonę z córek Labana, brata twojej matki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 3, 'A Bóg Wszechmogący niech ci błogosławi i niech cię uczyni płodnym i rozmnoży, abyś stał się licznym ludem;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 4, 'I niech ci da błogosławieństwo Abrahama, tobie i twemu potomstwu z tobą, abyś odziedziczył ziemię, na której jesteś przybyszem, którą Bóg dał Abrahamowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 5, 'I tak Izaak wysłał Jakuba, który udał się do krainy Paddan-Aram, do Labana, syna Betuela, Syryjczyka, brata Rebeki, matki Jakuba i Ezawa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 6, 'A Ezaw widział, że Izaak błogosławił Jakubowi i posłał go do krainy Paddan-Aram, aby stamtąd wziął sobie żonę, i że błogosławiąc mu, przykazał: Nie weźmiesz żony z córek Kanaanu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 7, 'I że Jakub był posłuszny swemu ojcu oraz swojej matce, i poszedł do krainy Paddan-Aram;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 8, 'Widział też Ezaw, że córki Kanaanu nie podobają się jego ojcu Izaakowi;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 9, 'Wtedy Ezaw poszedł do Izmaela i oprócz żon, które już miał, wziął za żonę Machalat, córkę Izmaela, syna Abrahama, siostrę Nebajota.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 10, 'A Jakub wyszedł z Beer-Szeby i udał się do Charanu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 11, 'Przyszedł na pewne miejsce i tam nocował, bo słońce już zaszło. Wziął jeden z kamieni z tego miejsca, podłożył go sobie pod głowę i zasnął na tym miejscu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 12, 'I śniło mu się, że na ziemi stała drabina, a jej szczyt sięgał nieba. A oto aniołowie Boży wstępowali i zstępowali po niej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 13, 'A Pan stał nad nią i powiedział: Ja jestem Pan, Bóg twego ojca Abrahama i Bóg Izaaka. Ziemię, na której leżysz, dam tobie i twemu potomstwu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 14, 'A twoje potomstwo będzie jak proch ziemi i rozprzestrzenisz się na zachód i na wschód, na północ i na południe. A w tobie i w twoim potomstwie będą błogosławione wszystkie narody ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 15, 'Oto ja jestem z tobą i będę cię strzegł, gdziekolwiek pójdziesz, i przyprowadzę cię z powrotem do tej ziemi. Bo nie opuszczę cię, aż spełnię to, co ci obiecałem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 16, 'Gdy Jakub zbudził się ze snu, powiedział: Naprawdę Pan jest na tym miejscu, a ja o tym nie wiedziałem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 17, 'I przestraszył się, i powiedział: O, jakie straszne to miejsce! To nie może być nic innego jak dom Boży i brama nieba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 18, 'I Jakub wstał wcześnie rano, wziął kamień, który podłożył sobie pod głowę i postawił go na znak, i nalał oliwy na jego wierzch.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 19, 'I nadał temu miejscu nazwę Betel, lecz przedtem miasto nazywało się Luz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 20, 'Wtedy Jakub złożył ślub, mówiąc: Jeśli Bóg będzie ze mną i będzie mnie strzegł na tej drodze, którą idę, jeśli da mi chleb do jedzenia i odzież do ubrania;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 21, 'I jeśli wrócę w pokoju do domu mego ojca, to Pan będzie moim Bogiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 22, 'A ten kamień, który postawiłem na znak, będzie domem Bożym. I ze wszystkiego, co mi dasz, będę ci na pewno oddawał dziesięcinę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 1, 'Wtedy Jakub wyruszył w drogę i poszedł do ziemi ludów Wschodu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 2, 'I spojrzał, a oto w polu studnia i trzy stada owiec leżących przy niej. Z tej studni pojono bowiem stada, a wielki kamień przykrywał wierzch tej studni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 3, 'A gdy schodziły się wszystkie stada, odsuwano kamień z wierzchu studni i pojono owce. Potem znów zasuwano kamień na wierzch studni na jego miejsce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 4, 'Jakub zapytał ich: Moi bracia, skąd jesteście? I odpowiedzieli: Jesteśmy z Charanu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 5, 'Zapytał ich: Czy znacie Labana, syna Nachora? Odpowiedzieli: Znamy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 6, 'Potem zapytał: Czy dobrze się miewa? A oni odpowiedzieli: Dobrze. Oto właśnie jego córka Rachela nadchodzi ze stadem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 7, 'Wtedy powiedział: Oto jeszcze jest jasny dzień i nie czas zganiać stada. Napójcie owce i idźcie, popaście je.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 8, 'Oni odpowiedzieli: Nie możemy, dopóki nie zbiorą się wszystkie stada i nie odsuną kamienia z wierzchu studni. Wtedy napoimy stada.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 9, 'A gdy jeszcze tak z nimi rozmawiał, nadeszła Rachela z owcami swego ojca, bo je pasła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 10, 'I gdy Jakub ujrzał Rachelę, córkę Labana, brata swej matki, z owcami Labana, brata swej matki, podszedł, odsunął kamień z wierzchu studni i napoił owce Labana, brata swojej matki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 11, 'Potem Jakub pocałował Rachelę i głośno zapłakał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 12, 'I Jakub powiedział Racheli, że jest bratem jej ojca i że jest synem Rebeki. Ona pobiegła więc i oznajmiła to swemu ojcu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 13, 'A gdy Laban usłyszał wieść o Jakubie, synu swojej siostry, wybiegł mu naprzeciw, objął go, ucałował i zaprowadził do swego domu. A on opowiedział Labanowi o wszystkim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 14, 'Wtedy Laban powiedział mu: Ty naprawdę jesteś z moich kości i z mojego ciała. I Jakub mieszkał u niego przez cały miesiąc.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 15, 'Potem Laban powiedział do Jakuba: Czyż dlatego, że jesteś moim bratem, będziesz mi służyć za darmo? Powiedz mi, jaka ma być twoja zapłata.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 16, 'A Laban miał dwie córki: starsza miała na imię Lea, młodsza zaś Rachela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 17, 'Lea miała czułe oczy, Rachela zaś była piękna i miła dla oka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 18, 'Jakub kochał Rachelę i powiedział: Będę ci służył siedem lat za twoją młodszą córkę Rachelę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 19, 'Laban odpowiedział: Lepiej mi ją dać tobie niż innemu mężczyźnie. Zamieszkaj ze mną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 20, 'I Jakub służył za Rachelę siedem lat, które wydawały mu się jak kilka dni, bo ją kochał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 21, 'Potem Jakub powiedział do Labana: Daj mi moją żonę, bo wypełniły się moje dni, abym z nią obcował.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 22, 'Wtedy Laban zebrał wszystkich mężczyzn tego miejsca i wyprawił ucztę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 23, 'A gdy nastał wieczór, wziął swoją córkę Leę i wprowadził ją do Jakuba, a on obcował z nią.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 24, 'Laban dał też swoją służącą Zilpę swej córce Lei za służącą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 25, 'Rano okazało się, że to była Lea. Powiedział więc do Labana: Cóż mi zrobiłeś? Czy nie za Rachelę ci służyłem? Dlaczego mnie oszukałeś?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 26, 'Laban odpowiedział: Nie ma u nas zwyczaju, aby młodszą wydawać za mąż przed starszą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 27, 'Dopełnij jej tydzień, a dam ci i tę za służbę, którą mi odsłużysz drugie siedem lat.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 28, 'I Jakub tak zrobił, i dopełnił jej tydzień. Potem Laban dał mu swoją córkę Rachelę za żonę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 29, 'Laban dał też swoją służącą Bilhę swej córce Racheli za służącą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 30, 'Wtedy Jakub obcował też z Rachelą i kochał Rachelę bardziej niż Leę, i służył mu jeszcze drugie siedem lat.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 31, 'A gdy Pan widział, że Lea była znienawidzona, otworzył jej łono. Rachela zaś była bezpłodna.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 32, 'Lea poczęła więc i urodziła syna, i nadała mu imię Ruben. Powiedziała bowiem: Pan naprawdę wejrzał na moje utrapienie. Dlatego teraz mój mąż będzie mnie kochać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 33, 'Gdy znów poczęła i urodziła syna, powiedziała: Pan usłyszał, że byłam znienawidzona. Dlatego dał mi także tego syna. I nadała mu imię Symeon.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 34, 'Potem znów poczęła i urodziła syna, i powiedziała: Tym razem mój mąż przywiąże się do mnie, bo urodziłam mu trzech synów. Dlatego nadała mu imię Lewi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 35, 'Gdy jeszcze raz poczęła i urodziła syna, powiedziała: Teraz już będę chwalić Pana. Dlatego nadała mu imię Juda. I przestała rodzić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 1, 'Gdy Rachela widziała, że nie rodzi dzieci Jakubowi, zazdrościła swej siostrze i powiedziała do Jakuba: Daj mi dzieci, bo inaczej umrę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 2, 'Jakub rozgniewał się na Rachelę i powiedział: Czy ja jestem Bogiem, który odmówił ci owocu twego łona?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 3, 'A ona odpowiedziała: Oto moja służąca Bilha. Obcuj z nią i urodzi na moich kolanach, i będę miała z niej dzieci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 4, 'Dała mu więc swoją służącą Bilhę za żonę, a Jakub z nią obcował.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 5, 'Bilha poczęła i urodziła Jakubowi syna.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 6, 'I Rachela powiedziała: Bóg mnie osądził i usłyszał mój głos, i dał mi syna. Dlatego nadała mu imię Dan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 7, 'Potem Bilha, służąca Racheli, znowu poczęła i urodziła Jakubowi drugiego syna.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 8, 'Wtedy Rachela powiedziała: Dzielnie walczyłam z moją siostrą i zwyciężyłam. I nadała mu imię Neftali.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 9, 'A gdy Lea widziała, że przestała rodzić, wzięła swoją służącą Zilpę i dała ją Jakubowi za żonę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 10, 'I Zilpa, służąca Lei, urodziła Jakubowi syna.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 11, 'Wtedy Lea powiedziała: Przyszedł oddział. I nadała mu imię Gad.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 12, 'Potem Zilpa, służąca Lei, urodziła Jakubowi drugiego syna.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 13, 'I Lea powiedziała: To na moje szczęście, bo kobiety będą mnie nazywać szczęśliwą. I nadała mu imię Aszer.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 14, 'A w czasie żniwa pszenicznego Ruben wyszedł i znalazł na polu mandragory, i przyniósł je do swojej matki Lei. Wtedy Rachela powiedziała do Lei: Daj mi, proszę, z mandragor twego syna.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 15, 'A ona jej odpowiedziała: Mało ci, że zabrałaś mi mojego męża, to teraz chcesz też zabrać mandragory mego syna? Wtedy Rachela powiedziała: Niech śpi z tobą tej nocy za mandragory twego syna.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 16, 'A gdy Jakub wracał wieczorem z pola, Lea wyszła mu naprzeciw i powiedziała: Masz do mnie przyjść, bo nabyłam cię za mandragory mego syna. I spał z nią tej nocy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 17, 'A Bóg wysłuchał Leę i poczęła, i urodziła Jakubowi piątego syna.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 18, 'I Lea powiedziała: Bóg mi oddał moją zapłatę za to, że dałam moją służącą swemu mężowi. I nadała mu imię Issachar.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 19, 'Potem Lea znowu poczęła i urodziła Jakubowi szóstego syna.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 20, 'I Lea mówiła: Bóg obdarzył mnie wspaniałym darem. Teraz mój mąż będzie ze mną mieszkał, bo urodziłam mu sześciu synów. I nadała mu imię Zebulon.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 21, 'Potem urodziła córkę i nadała jej imię Dina.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 22, 'Bóg wspomniał też na Rachelę i wysłuchał ją Bóg, i otworzył jej łono.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 23, 'Poczęła więc i urodziła syna, i powiedziała: Bóg zabrał moją hańbę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 24, 'Nadała mu imię Józef i powiedziała: Niech Pan da mi drugiego syna.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 25, 'Gdy Rachela urodziła Józefa, Jakub powiedział do Labana: Puść mnie, abym wrócił do mego miejsca i do mojej ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 26, 'Daj mi moje żony i moje dzieci, za które ci służyłem, abym mógł iść. Wiesz przecież, jak ci służyłem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 27, 'I Laban powiedział do niego: Proszę, jeśli znalazłem łaskę w twoich oczach, zostań ze mną. Doznałem bowiem tego, że Pan mi błogosławił ze względu na ciebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 28, 'Mówił dalej: Wyznacz swoją zapłatę, a dam ci ją.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 29, 'Wtedy Jakub mu odpowiedział: Ty wiesz, jak ci służyłem i jaki stał się przy mnie twój dobytek.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 30, 'Miałeś bowiem niewiele przed moim przyjściem, a bardzo się to pomnożyło i Pan błogosławił ci, odkąd tu jestem. Kiedy jednak mam się starać o swój dom?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 31, 'I Laban zapytał: Cóż mam ci dać? Jakub odpowiedział: Nic mi nie dasz. Ale jeśli zrobisz to, co ci powiem, wtedy wrócę i będę pasł twoje stado, i strzegł go.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 32, 'Obejdę dziś wszystkie twoje stada i odłączę z nich każde bydło pstre i nakrapiane i każde bydło ciemne wśród owiec, a nakrapiane i pstre wśród kóz. To będzie moja zapłata.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 33, 'Potem moja sprawiedliwość da świadectwo o mnie, gdy przyjdzie czas, abyś mi zapłacił. Wszystko, co nie będzie pstre i nakrapiane wśród kóz, a ciemne wśród owiec, niech będzie mi poczytane za kradzież.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 34, 'Laban powiedział: Niech się stanie według twego słowa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 35, 'W tym dniu odłączył kozły prążkowane i nakrapiane i wszystkie kozy pstre i nakrapiane, i wszystkie, które miały jakąś białą plamkę, także i czarne wśród owiec, i oddał je w ręce swych synów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 36, 'I Laban odłączył się od Jakuba na odległość trzech dni drogi. A Jakub pasł resztę stada Labana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 37, 'Wtedy Jakub nabrał zielonych prętów topolowych, laskowych i kasztanowych i miejscami poobdzierał je z kory do białego, obnażając białość, która była na prętach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 38, 'Gdy stada przychodziły pić, przed stadami nakładł do rynien i koryt z wodą tych prętów, które poobdzierał z kory, aby parzyły się stada, przychodząc pić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 39, 'I stada parzyły się przy tych prętach i rodziły jagnięta prążkowane, pstre i nakrapiane.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 40, 'I Jakub odłączył jagnięta, a owce stawiał przodem do jagniąt prążkowanych i do wszystkich ciemnych w stadzie Labana, a swoje stada stawiał osobno i nie łączył ich ze stadem Labana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 41, 'A gdy silniejsze zwierzęta się parzyły, Jakub kładł pręty w koryta, przed oczy zwierząt, aby parzyły się przed prętami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 42, 'Lecz gdy przychodziły słabsze zwierzęta, nie kładł ich. I słabsze były Labana, a silniejsze Jakuba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 43, 'I tak wzbogacił się bardzo ten człowiek, i miał wiele stad, a także służące i służących oraz wielbłądy i osły.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 1, 'Potem Jakub usłyszał, jak synowie Labana mówili: Jakub zabrał wszystko, co należało do naszego ojca, i z tego, co było naszego ojca, zdobył całe to bogactwo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 2, 'Jakub widział też oblicze Labana, że nie było w stosunku do niego takie jak wcześniej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 3, 'Wtedy Pan powiedział do Jakuba: Wróć do ziemi swoich ojców i do swojej rodziny, a będę z tobą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 4, 'Jakub kazał więc przywołać Rachelę i Leę na pole do swojego stada.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 5, 'I powiedział im: Widzę oblicze waszego ojca, że nie jest w stosunku do mnie takie jak wcześniej, ale Bóg mego ojca był ze mną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 6, 'Wy też same wiecie, że ze wszystkich moich sił służyłem waszemu ojcu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 7, 'Ale wasz ojciec oszukał mnie i dziesięć razy zmieniał moją zapłatę. Bóg jednak nie pozwolił mu skrzywdzić mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 8, 'Jeśli powiedział: Pstre będą twoją zapłatą, to wszystkie stada rodziły pstre; a gdy mówił: Prążkowane będą twoją zapłatą, to wszystkie stada rodziły prążkowane.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 9, 'W ten sposób Bóg odebrał dobytek waszemu ojcu i dał go mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 10, 'Gdy bowiem był czas parzenia się stad, podniosłem swe oczy i widziałem we śnie, że samce łączyły się z bydłami prążkowanymi, pstrymi i biało nakrapianymi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 11, 'Wtedy Anioł Boga powiedział mi we śnie: Jakubie! A ja odpowiedziałem: Oto jestem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 12, 'Potem powiedział: Podnieś teraz swe oczy i zobacz wszystkie samce łączące się z owcami prążkowanymi, pstrymi i biało nakrapianymi. Widziałem bowiem wszystko, co Laban ci uczynił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 13, 'Ja jestem Bogiem z Betel, gdzie namaściłeś kamień i gdzie złożyłeś mi ślub. Teraz więc wstań, wyjdź z tej ziemi i wróć do ziemi twojej rodziny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 14, 'I Rachela, i Lea odpowiedziały mu: Czy mamy jeszcze jakąś cząstkę i dziedzictwo w domu naszego ojca?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 15, 'Czy nie jesteśmy uważane u niego za obce? Sprzedał nas bowiem i jeszcze przejadł nasz majątek.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 16, 'Bo całe bogactwo, które Bóg odebrał naszemu ojcu, jest nasze i naszych synów. Dlatego teraz zrób wszystko, co ci Bóg rozkazał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 17, 'Jakub wstał więc i wsadził swych synów i swe żony na wielbłądy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 18, 'I zabrał całe swoje stado i cały swój majątek, który zdobył, swój dobytek, który nabył w Paddan-Aram, aby wrócić do swego ojca Izaaka, do ziemi Kanaan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 19, 'Gdy Laban odszedł strzyc swoje owce, Rachela ukradła posążki należące do jej ojca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 20, 'I Jakub wykradł się potajemnie od Labana Syryjczyka, nie oznajmiając mu, że ucieka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 21, 'Uciekł więc ze wszystkim, co miał. Wstał i przeprawił się przez rzekę, i udał się ku górze Gilead.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 22, 'A trzeciego dnia doniesiono Labanowi, że Jakub uciekł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 23, 'Wziął więc ze sobą swoich braci, gonił go przez siedem dni i doścignął go na górze Gilead.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 24, 'Lecz Bóg przyszedł do Labana Syryjczyka tej nocy we śnie i powiedział mu: Strzeż się, abyś nie mówił do Jakuba ani dobrze, ani źle.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 25, 'Laban dogonił Jakuba, gdy Jakub rozbił swój namiot na górze. Laban ze swoimi braćmi też rozbił namiot na górze Gilead.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 26, 'Wtedy Laban powiedział do Jakuba: Coś ty zrobił, że się wykradłeś potajemnie ode mnie i uprowadziłeś moje córki jak pojmane mieczem?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 27, 'Dlaczego potajemnie uciekłeś i wykradłeś się ode mnie, i nic mi nie powiedziałeś, abym mógł wyprawić cię z radością, z pieśniami, z bębnem i harfą?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 28, 'I nie pozwoliłeś mi ucałować moich synów i moich córek? Naprawdę głupio postąpiłeś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 29, 'Jest to w mocy mojej ręki, aby zrobić wam coś złego, ale Bóg waszego ojca powiedział mi zeszłej nocy: Strzeż się, abyś nie mówił do Jakuba ani dobrze, ani źle.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 30, 'A teraz, gdy chciałeś odejść, bo bardzo tęskniłeś za domem twego ojca, dlaczego ukradłeś moje bożki?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 31, 'I Jakub odpowiedział Labanowi: Bałem się, bo myślałem, że siłą odbierzesz mi twoje córki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 32, 'Lecz ten, u kogo znajdziesz twoje bożki, niech umrze. Sprawdź w obecności naszych braci, czy coś twojego jest u mnie, i weź sobie. Jakub nie wiedział bowiem, że Rachela je ukradła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 33, 'Laban wszedł więc do namiotu Jakuba i do namiotu Lei, a także do namiotu obu służących, ale nic nie znalazł. Gdy wyszedł z namiotu Lei, wszedł do namiotu Racheli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 34, 'A Rachela wzięła posążki, włożyła je pod siodło wielbłądzie i usiadła na nich. Laban przeszukał cały namiot, ale nic nie znalazł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 35, 'Powiedziała do swego ojca: Niech się mój pan nie gniewa, że nie mogę wstać przed tobą, bo mam kobiecą przypadłość. I szukał, ale nie znalazł posążków.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 36, 'Wtedy Jakub rozgniewał się i zganił Labana. I Jakub powiedział do Labana: Jakie jest moje przestępstwo i jaki mój grzech, że goniłeś mnie w gniewie?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 37, 'Oto przeszukałeś wszystkie moje rzeczy. Co znalazłeś z rzeczy należących do twego domu? Połóż to tutaj przed moimi i twoimi braćmi i niech rozsądzą między nami dwoma.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 38, 'Dwadzieścia lat mieszkałem z tobą. Twoje owce i twoje kozy nie roniły, a baranów z twego stada nie jadłem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 39, 'Rozszarpanego przez zwierzę nie przynosiłem do ciebie, wynagradzałem ci szkodę; z mojej ręki domagałeś się tego, co było ukradzione we dnie i co było ukradzione w nocy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 40, 'Bywało, że we dnie męczył mnie upał, a mróz w nocy, tak że sen odchodził od moich oczu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 41, 'Dwadzieścia lat ci służyłem w twoim domu: czternaście lat za twoje dwie córki, a sześć lat za twoje bydło. A po dziesięć razy zmieniałeś moją zapłatę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 42, 'Gdyby Bóg mojego ojca, Bóg Abrahama i bojaźń Izaaka, nie był ze mną, pewnie byś mnie teraz odprawił z niczym. Ale Bóg wejrzał na moje utrapienie i na pracę moich rąk i przestrzegł cię zeszłej nocy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 43, 'Wtedy Laban odpowiedział Jakubowi: Córki te są moimi córkami i dzieci te są moimi dziećmi, i dobytek ten to mój dobytek, i wszystko, co widzisz, jest moje. Ale cóż mogę dziś uczynić tym moim córkom albo dzieciom, które urodziły?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 44, 'Chodź więc, zawrzyjmy przymierze, ja i ty, i niech to będzie świadectwem między mną a tobą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 45, 'I Jakub wziął kamień, i postawił go jako pomnik.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 46, 'Potem Jakub powiedział do swoich braci: Nazbierajcie kamieni. Wzięli więc kamienie i zrobili stos, i jedli tam na tym stosie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 47, 'I Laban nazwał go Jegar Sahaduta, a Jakub go nazwał Galed.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 48, 'Bo Laban mówił: Ten stos niech będzie dziś świadkiem między mną a tobą. Dlatego Jakub nazwał go Galed;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 49, 'I Myspa, bo Laban powiedział: Niech Pan czuwa nade mną i nad tobą, gdy się oddalimy od siebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 50, 'Jeśli będziesz krzywdził moje córki i jeśli pojmiesz inne żony oprócz moich córek, to choć nie ma tu z nami nikogo, patrz: Bóg jest świadkiem między mną a tobą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 51, 'I Laban mówił dalej do Jakuba: Oto ten stos kamieni i oto ten pomnik, który postawiłem między mną a tobą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 52, 'Ten stos jest świadkiem i ten pomnik jest świadkiem tego, że ja do ciebie nie pójdę dalej za ten stos i ty też nie pójdziesz do mnie za ten stos i pomnik w złym zamiarze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 53, 'Bóg Abrahama i Bóg Nachora, Bóg ich ojca, niech rozsądzi między nami. Jakub przysiągł więc przez bojaźń swego ojca Izaaka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 54, 'Potem Jakub złożył na wzgórzu ofiarę i wezwał swych braci do jedzenia chleba. Jedli więc chleb i nocowali na tym wzgórzu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 55, 'Nazajutrz wcześnie rano Laban wstał, ucałował swoich synów i swoje córki i błogosławił im. A Laban odszedł i wrócił na swoje miejsce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 1, 'Jakub też poszedł swoją drogą i spotkali go aniołowie Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 2, 'Gdy Jakub ich ujrzał, powiedział: To obóz Boga. I nadał temu miejscu nazwę Machanaim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 3, 'Potem Jakub wysłał przed sobą posłańców do swego brata Ezawa, do ziemi Seir, do krainy Edomu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 4, 'I rozkazał im: Tak powiecie do mego pana Ezawa: To mówi twój sługa Jakub: Byłem gościem u Labana i przebywałem z nim aż do tego czasu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 5, 'Mam woły, osły i owce, służących i służące, a posyłam oznajmić to memu panu, żebym znalazł łaskę w twoich oczach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 6, 'Posłańcy wrócili do Jakuba i mówili: Przyszliśmy do twego brata Ezawa, a on też idzie naprzeciwko ciebie, a z nim czterystu mężów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 7, 'Jakub bardzo się przestraszył i ogarnęła go trwoga. Podzielił więc lud, który z nim był, oraz owce, woły i wielbłądy na dwa obozy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 8, 'I powiedział: Jeśli Ezaw przyjdzie do jednego obozu i uderzy na niego, to drugi obóz ocaleje.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 9, 'Potem Jakub powiedział: Boże mego ojca Abrahama i Boże mego ojca Izaaka, Panie, który do mnie powiedziałeś: Wróć do twojej ziemi i do twojej rodziny, a będę ci wyświadczał dobro.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 10, 'Nie jestem godzien wszelkiego miłosierdzia i całej wierności, które okazałeś swemu słudze. Bo tylko o lasce przeszedłem ten Jordan, a teraz mam dwa obozy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 11, 'Wyrwij mnie, proszę, z ręki mego brata, z ręki Ezawa, bo się go boję, że przyjdzie i zabije mnie i matki z dziećmi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 12, 'Ty bowiem powiedziałeś: Na pewno będę ci wyświadczał dobro i rozmnożę twoje potomstwo jak piasek morski, który nie może być zliczony z powodu jego mnóstwa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 13, 'I przenocował tam tej nocy, i wziął z tego, co miał pod ręką, dar dla swego brata Ezawa;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 14, 'Dwieście kóz i dwadzieścia kozłów, dwieście owiec i dwadzieścia baranów;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 15, 'Trzydzieści karmiących wielbłądzic z młodymi, czterdzieści krów i dziesięć wołów, dwadzieścia oślic i dziesięcioro ośląt.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 16, 'I oddał je w ręce swoich sług, każde stado oddzielnie, i powiedział do swoich sług: Idźcie przede mną i zachowajcie odstęp między stadami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 17, 'I rozkazał pierwszemu: Gdy spotka cię mój brat Ezaw, a spyta cię: Czyj jesteś? I dokąd idziesz? A czyje to stado przed tobą?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 18, 'Wtedy odpowiesz: To jest dar od twego sługi Jakuba, posłany memu panu Ezawowi. A oto on sam idzie za nami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 19, 'Tak też rozkazał drugiemu i trzeciemu, i wszystkim idącym za tymi stadami: Tymi słowy mówcie do Ezawa, gdy go spotkacie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 20, 'Powiecie mu też: Oto twój sługa Jakub idzie za nami. Myślał bowiem: Przebłagam go darem, który idzie przede mną, a potem zobaczę jego oblicze. Może mnie przyjmie łaskawie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 21, 'I poszedł przed nim ten dar, a sam przenocował tej nocy ze swoim obozem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 22, 'Wstał tej nocy, wziął obie swe żony i dwie swoje służebnice oraz jedenastu swoich synów i przeszedł przez bród Jabboku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 23, 'I wziął ich, przeprawił przez tę rzekę i przeprowadził wszystko, co miał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 24, 'Jakub zaś został sam. I walczył z nim pewien mężczyzna aż do wzejścia zorzy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 25, 'A widząc, że nie może go pokonać, dotknął go w staw biodrowy i wytrącił biodro Jakubowi ze stawu, gdy się z nim mocował.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 26, 'I powiedział: Puść mnie, bo już wzeszła zorza. Odpowiedział: Nie puszczę cię, aż mi pobłogosławisz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 27, 'Wtedy mu powiedział: Jakie jest twoje imię? I odpowiedział: Jakub.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 28, 'I powiedział: Twoim imieniem nie będzie już Jakub, ale Izrael, bo mężnie zmagałeś się z Bogiem i z ludźmi i zwyciężyłeś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 29, 'I Jakub spytał: Powiedz mi, proszę, twoje imię. A on odpowiedział: Czemu pytasz o moje imię? I tam mu błogosławił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 30, 'Jakub nadał więc temu miejscu nazwę Penuel, mówiąc: Widziałem bowiem Boga twarzą w twarz, a moja dusza została zachowana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 31, 'I kiedy minął miejsce Penuel, wzeszło słońce, a on utykał z powodu swojego biodra.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 32, 'Dlatego do dziś synowie Izraela nie jadają ścięgna, które jest w stawie biodrowym, gdyż dotknął Jakuba w staw biodrowy, w ścięgno, które się skurczyło.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 1, 'Potem Jakub podniósł oczy i zobaczył, że Ezaw nadchodzi, a z nim czterystu mężczyzn. Podzielił więc dzieci między Leę, Rachelę a dwie służące.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 2, 'I postawił na przodzie służące i ich dzieci, za nimi Leę i jej dzieci, a na końcu Rachelę z Józefem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 3, 'Sam zaś wyszedł przed nich i pokłonił się siedem razy aż do ziemi, zanim doszedł do swego brata.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 4, 'Ale Ezaw wybiegł mu naprzeciw, objął go, rzucił mu się na szyję i całował go. I płakali.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 5, 'Potem podniósł oczy, zobaczył żony i dzieci i zapytał: A kim są ci przy tobie? I odpowiedział: To są dzieci, które Bóg w swej łaskawości dał twemu słudze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 6, 'Wtedy przybliżyły się służące ze swoimi dziećmi i pokłoniły się.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 7, 'Przybliżyła się też Lea ze swoimi dziećmi i pokłoniły się. Potem przybliżyli się Józef i Rachela i pokłonili się.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 8, 'I Ezaw zapytał: Co znaczy cały ten obóz, z którym się spotkałem? Jakub odpowiedział: Abym znalazł łaskę w oczach mego pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 9, 'Wtedy Ezaw powiedział: Ja mam dosyć, mój bracie, zatrzymaj to, co twoje.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 10, 'I Jakub powiedział: Nie, proszę, jeśli znalazłem teraz łaskę w twoich oczach, przyjmij dar z mojej ręki, bo gdy zobaczyłem twoje oblicze, to jakbym widział oblicze Boga, i ty łaskawie mnie przyjąłeś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 11, 'Przyjmij, proszę, mój dar, który ci przyniosłem, bo Bóg hojnie mi błogosławił, a mam dość wszystkiego. I tak nalegał na niego, że to przyjął.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 12, 'Ezaw powiedział: Ruszajmy w drogę i chodźmy, a ja pójdę przed tobą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 13, 'I Jakub mu odpowiedział: Mój pan wie, że mam ze sobą dzieci wątłe, a owce i krowy karmią młode. Jeśli popędzi się je przez cały dzień, zginie całe stado.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 14, 'Niech mój pan, proszę, idzie przed swoim sługą, a ja będę szedł powoli, jak nadąży stado, które jest przede mną, i jak nadążą dzieci, aż przyjdę do mego pana do Seiru.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 15, 'Wtedy Ezaw powiedział: Zostawię więc przy tobie część ludzi, którzy są ze mną. A on odpowiedział: A na cóż to? Obym znalazł łaskę w oczach mego pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 16, 'I tego dnia Ezaw wrócił swą drogą do Seiru.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 17, 'A Jakub wyruszył do Sukkot i zbudował sobie dom, i zrobił szałasy dla swoich stad. Dlatego nazwał to miejsce Sukkot.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 18, 'I Jakub przyszedł szczęśliwie do miasta Sychem, które było w ziemi Kanaan, gdy wrócił z Paddan-Aram, i rozbił obóz przed miastem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 19, 'I za sto monet kupił od synów Hemora, ojca Sychema, część pola, na którym rozbił swój namiot.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 20, 'Tam też postawił ołtarz i nazwał go: Mocny Bóg Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 1, 'I Dina, córka Lei, którą urodziła Jakubowi, wyszła, aby zobaczyć córki tej ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 2, 'A gdy zobaczył ją Sychem, syn Chamora Chiwwity, książę tej ziemi, porwał ją, spał z nią i ją zhańbił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 3, 'I przylgnęła jego dusza do Diny, córki Jakuba, a zakochał się w dziewczynie i czule do niej mówił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 4, 'Potem Sychem powiedział do swego ojca Chamora: Weź mi tę dziewczynę za żonę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 5, 'A Jakub usłyszał, że jego córka Dina została zhańbiona, a jego synowie byli przy jego stadach na polu. Jakub więc milczał aż do ich przyjścia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 6, 'Wtedy Chamor, ojciec Sychema, wyszedł do Jakuba, aby z nim porozmawiać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 7, 'A gdy synowie Jakuba przyszli z pola i to usłyszeli, ubolewali nad tym i bardzo się rozgniewali, że dopuścił się haniebnego czynu w Izraelu, śpiąc z córką Jakuba, czego nie wolno robić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 8, 'I Chamor powiedział do nich: Mój syn Sychem przylgnął duszą do waszej córki. Dajcie mu ją, proszę, za żonę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 9, 'Spowinowaćcie się z nami. Dajcie nam wasze córki i bierzcie sobie nasze córki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 10, 'I będziecie z nami mieszkać, a ziemia będzie przed wami. Mieszkajcie i handlujcie w niej, i osadzajcie się w niej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 11, 'I Sychem mówił też do jej ojca i braci: Niech znajdę łaskę w waszych oczach, a co mi powiecie, to dam.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 12, 'Zażądajcie ode mnie jak największego wiana i darów, a dam, jak mi powiecie; tylko dajcie mi tę dziewczynę za żonę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 13, 'Wtedy synowie Jakuba odpowiedzieli Sychemowi i jego ojcu Chamorowi, mówiąc podstępnie, bo zhańbił ich siostrę Dinę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 14, 'I powiedzieli im: Nie możemy dać naszej siostry nieobrzezanemu mężczyźnie, gdyż byłaby to dla nas hańba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 15, 'Zgodzimy się z wami tylko w ten sposób, jeśli zechcecie być do nas podobni i każdy z waszych mężczyzn będzie obrzezany.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 16, 'Wtedy damy wam nasze córki, a wasze córki weźmiemy sobie. Zamieszkamy z wami i staniemy się jednym ludem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 17, 'Ale jeśli nas nie usłuchacie i nie dacie się obrzezać, weźmiemy naszą córkę i odejdziemy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 18, 'I słowa ich spodobały się Chamorowi i jego synowi Sychemowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 19, 'Młodzieniec nie odkładał więc tego, bo zakochał się w córce Jakuba. A był on ze wszystkich najbardziej szanowany w domu swego ojca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 20, 'Gdy Chamor i jego syn Sychem przyszli do bramy swego miasta, powiedzieli do mężczyzn swego miasta:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 21, 'Ci mężczyźni spokojnie z nami żyją. Niech więc mieszkają w tej ziemi i handlują w niej, bo oto nasza ziemia jest dość przestronna dla nich. Będziemy brać sobie ich córki za żony, a nasze córki będziemy im dawać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 22, 'Zgodzą się ci mężczyźni mieszkać z nami, byśmy byli jednym ludem, ale pod warunkiem, że każdy mężczyzna u nas będzie obrzezany, tak jak i oni są obrzezani.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 23, 'Czyż ich stada i dobytek oraz wszelkie ich bydło nie będą nasze? Na to tylko im pozwólmy, a zamieszkają z nami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 24, 'I usłuchali Chamora i jego syna Sychema wszyscy wychodzący z bramy swego miasta. I został obrzezany każdy mężczyzna, który wychodził z bramy swego miasta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 25, 'A trzeciego dnia, gdy najbardziej cierpieli, dwaj synowie Jakuba, Symeon i Lewi, bracia Diny, wzięli swoje miecze i śmiało weszli do miasta, i pomordowali wszystkich mężczyzn.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 26, 'Zabili ostrzem miecza także Chamora oraz jego syna Sychema i zabrali Dinę z domu Sychema, i odeszli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 27, 'Synowie Jakuba wpadli do pomordowanych i złupili miasto za to, że zhańbili ich siostrę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 28, 'Zabrali ich owce, woły i osły oraz to, co było w mieście i na polu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 29, 'Cały ich majątek, wszystkie ich dzieci i żony wzięli do niewoli i zrabowali wszystko, co było w domach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 30, 'Wtedy Jakub powiedział do Symeona i Lewiego: Zaniepokoiliście mnie, czyniąc mnie obrzydliwym u mieszkańców tej ziemi, u Kananejczyków i Peryzzytów. Ja mam niewielką liczbę ludzi, a oni zbiorą się przeciwko mnie i uderzą na mnie. I tak zginę ja i mój dom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 31, 'A oni odpowiedzieli: Czyż miał traktować naszą siostrę jak nierządnicę?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 1, 'Potem Bóg powiedział do Jakuba: Wstań, wstąp do Betel i tam zamieszkaj. Zbuduj tam ołtarz Bogu, który ci się ukazał, gdy uciekałeś przed swoim bratem Ezawem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 2, 'Wtedy Jakub powiedział do swych domowników i do wszystkich, którzy z nim byli: Usuńcie obcych bogów, którzy są wśród was, oczyśćcie się i zmieńcie swoje szaty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 3, 'Wstańmy i pójdźmy do Betel; tam zbuduję ołtarz Bogu, który mnie wysłuchał w dniu mego utrapienia i był ze mną w drodze, którą chodziłem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 4, 'Oddali więc Jakubowi wszystkich obcych bogów, których mieli, i kolczyki, które mieli w uszach, i Jakub zakopał je pod tym dębem, który był niedaleko Sychem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 5, 'Potem wyruszyli w drogę. A strach Boży padł na okoliczne miasta i nie ścigali synów Jakuba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 6, 'Jakub przyszedł więc do Luz, które jest w ziemi Kanaan, czyli do Betel, on i cały lud, który z nim był.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 7, 'I zbudował tam ołtarz, a nazwał to miejsce El-Betel, bo tam ukazał mu się Bóg, gdy uciekał przed swoim bratem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 8, 'Wtedy umarła Debora, mamka Rebeki, i została pogrzebana przy Betel pod dębem. I nazwano go Allon-Bachut.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 9, 'I Bóg znowu ukazał się Jakubowi, gdy ten wracał z Paddan-Aram, i błogosławił mu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 10, 'I powiedział mu Bóg: Twoje imię jest Jakub. Nie będziesz już jednak zwany Jakubem, ale twoim imieniem będzie Izrael. I nadał mu imię Izrael.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 11, 'I Bóg mu powiedział: Ja jestem Bóg Wszechmogący. Bądź płodny i rozmnażaj się. Z ciebie powstanie naród i wiele narodów, a z twoich bioder wyjdą królowie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 12, 'Ziemię, którą dałem Abrahamowi i Izaakowi, dam tobie i twemu potomstwu po tobie dam tę ziemię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 13, 'I Bóg odszedł od niego z miejsca, na którym z nim rozmawiał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 14, 'Potem Jakub postawił pomnik na tym miejscu, gdzie Bóg z nim rozmawiał, pomnik kamienny, i wylał na nim ofiarę z płynów, i polał go oliwą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 15, 'I Jakub nadał temu miejscu, gdzie Bóg z nim rozmawiał, nazwę Betel.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 16, 'Potem wyruszyli z Betel i gdy mieli kawałek drogi do Efraty, Rachela zaczęła rodzić, a poród miała ciężki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 17, 'Gdy rodziła w wielkich bólach, położna powiedziała do niej: Nie bój się, bo i tego syna będziesz miała.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 18, 'Kiedy uchodziła z niej dusza, bo tam umarła, nadała mu imię Benoni; ale jego ojciec nazwał go Beniamin.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 19, 'Tak to umarła Rachela i została pogrzebana na drodze do Efraty, czyli Betlejem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 20, 'I Jakub postawił pomnik na jej grobie. To jest pomnik grobu Racheli aż do dziś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 21, 'Potem Izrael wyruszył stamtąd i rozbił swój namiot za wieżą Eder.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 22, 'A gdy Izrael mieszkał w tej krainie, Ruben poszedł i spał z Bilhą, nałożnicą swego ojca, i Izrael usłyszał o tym. A synów Jakuba było dwunastu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 23, 'Synowie Lei: Ruben, pierworodny Jakuba, potem Symeon, Lewi, Juda, Issachar i Zebulon.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 24, 'Synowie Racheli: Józef i Beniamin.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 25, 'A synowie Bilhy, służącej Racheli: Dan i Neftali.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 26, 'Synowie Zilpy, służącej Lei: Gad i Aszer. To są synowie Jakuba, którzy mu się urodzili w Paddan-Aram.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 27, 'I Jakub przyszedł do swego ojca Izaaka, do Mamre, do miasta Arba, czyli Hebronu, gdzie przebywali Abraham i Izaak.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 28, 'A dni Izaaka było sto osiemdziesiąt lat.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 29, 'I Izaak oddał ducha, i umarł, i został przyłączony do swego ludu, stary i syty dni; a pogrzebali go jego synowie, Ezaw i Jakub.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 1, 'To są dzieje rodu Ezawa, czyli Edomu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 2, 'Ezaw pojął swoje żony z córek Kanaanu: Adę, córkę Elona Chetyty, Oholibamę, córkę Any, córki Sibeona Chiwwity;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 3, 'I Basmat, córkę Izmaela, siostrę Nebajota.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 4, 'I Ada urodziła Ezawowi Elifaza, a Basmat urodziła Rehuela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 5, 'Oholibama urodziła Jeusza, Jalama i Koracha. To są synowie Ezawa, którzy mu się urodzili w ziemi Kanaan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 6, 'I Ezaw wziął swoje żony, synów, córki i wszystkich domowników, swoje stada, wszystkie bydła i całe swoje mienie, które zdobył w ziemi Kanaan, i odszedł od swego brata Jakuba do innej ziemi;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 7, 'Bo ich majątek był tak wielki, że nie mogli mieszkać razem, i ziemia, na której przebywali, nie mogła ich utrzymać z powodu mnóstwa ich stad.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 8, 'I Ezaw zamieszkał na górze Seir. Ezaw to Edom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 9, 'A to są dzieje rodu Ezawa, ojca Edomitów, na górze Seir.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 10, 'I to są imiona synów Ezawa: Elifaz, syn Ady, żony Ezawa, Rehuel, syn Basmat, żony Ezawa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 11, 'Synami zaś Elifaza byli: Teman, Omar, Sefo, Gatam i Kenaz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 12, 'A Timna była nałożnicą Elifaza, syna Ezawa, i urodziła Elifazowi Amaleka. To są synowie Ady, żony Ezawa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 13, 'To są synowie Rehuela: Nachat, Zerach, Szamma i Mizza. Byli oni synami Basmat, żony Ezawa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 14, 'A ci byli synami żony Ezawa Oholibamy, córki Any, córki Sibeona. Urodziła ona Ezawowi Jeusza, Jalama i Koracha.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 15, 'To są książęta spośród synów Ezawa, synowie Elifaza, pierworodnego Ezawa: książę Teman, książę Omar, książę Sefo, książę Kenaz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 16, 'Książę Korach, książę Gatam, książę Amalek. Ci książęta pochodzą z Elifaza, w ziemi Edom, to są synowie Ady.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 17, 'To są synowie Rehuela, syna Ezawa: książę Nachat, książę Zerach, książę Szamma, książę Mizza. Ci książęta pochodzą z Rehuela, w ziemi Edom. Oni są synami Basmat, żony Ezawa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 18, 'A to są synowie Oholibamy, żony Ezawa: książę Jeusz, książę Jalam, książę Korach. Ci książęta pochodzą z Oholibamy, córki Any, żony Ezawa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 19, 'To są synowie Ezawa, czyli Edom, i to są ich książęta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 20, 'A to są synowie Seira, Choryty, mieszkańcy tej ziemi: Lotan, Szobal, Sibeon i Ana;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 21, 'Diszon, Eser i Diszan. To są książęta Chorytów, synowie Seira w ziemi Edom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 22, 'Synami Lotana byli: Chori i Hemam; a siostrą Lotana była Tamna.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 23, 'Synowie zaś Szobala: Alwan, Manachat, Ebal, Szefo i Onam.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 24, 'Synami Sibeona są Ajja i Ana. To ten Ana, który znalazł muły na pustyni, gdy pasł osły swego ojca Sibeona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 25, 'A to są dzieci Any: Diszon i Oholibama, córka Any.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 26, 'I synowie Diszona: Chemdan, Eszban, Jitran i Keran.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 27, 'To są synowie Esera: Bilhan, Zaawan i Akan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 28, 'I synowie Diszana: Us i Aran.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 29, 'To są książęta Chorytów: książę Lotan, książę Szobal, książę Sibeon, książę Ana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 30, 'Książę Diszon, książę Eser, książę Diszan. Są to książęta Chorytów, według ich księstw, w ziemi Seir.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 31, 'To są królowie, którzy panowali w ziemi Edom, zanim panował król nad synami Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 32, 'W Edomie panował Bela, syn Beora, a nazwa jego miasta – Dinhaba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 33, 'I Bela umarł, a w jego miejsce panował Jobab, syn Zeracha z Bosry.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 34, 'Jobab umarł, a w jego miejsce panował Chuszam z ziemi Temanitów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 35, 'Chuszam umarł, a w jego miejsce panował Hadad, syn Bedada, który pokonał Midianitów na polu Moab, a nazwa jego miasta – Awit.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 36, 'Hadad umarł, a w jego miejsce panował Samla z Masreki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 37, 'Samla umarł, a w jego miejsce panował Saul z Rechobot nad Rzeką.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 38, 'Saul umarł, a w jego miejsce panował Baalchanan, syn Akbora.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 39, 'Baalchanan, syn Akbora, umarł, a w jego miejsce panował Hadar, a nazwa jego miasta – Pahu, a imię jego żony to Mehetabel, była to córka Matredy, córki Mezahaba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 40, 'To są imiona książąt Ezawa, według ich rodów i miejscowości i według ich imion: książę Timna, książę Alwa, książę Jetet.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 41, 'Książę Oholibama, książę Ela, książę Pinon.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 42, 'Książę Kenaz, książę Teman, książę Mibsar.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 43, 'Książę Magdiel, książę Iram. To są książęta Edomu według miejsca ich zamieszkania w ziemi ich posiadłości. To jest Ezaw, ojciec Edomitów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 1, 'Jakub mieszkał w ziemi, gdzie jego ojciec był przybyszem, w ziemi Kanaan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 2, 'To są dzieje rodu Jakuba: Gdy Józef miał siedemnaście lat, pasł stada ze swoimi braćmi; młodzieniec był z synami Bilhy i z synami Zilpy, żony swego ojca. I Józef donosił ojcu o ich złej sławie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 3, 'A Izrael kochał Józefa najbardziej ze wszystkich swoich synów, bo urodził mu się w starości. I zrobił mu szatę wielobarwną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 4, 'Gdy jego bracia widzieli, że ojciec kocha go bardziej niż wszystkich jego braci, znienawidzili go i nie potrafili przyjaźnie z nim rozmawiać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 5, 'Pewnego razu Józefowi przyśnił się sen, a gdy opowiedział go swoim braciom, tym bardziej go znienawidzili.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 6, 'Bo powiedział im: Posłuchajcie, proszę, snu, który mi się przyśnił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 7, 'Wiązaliśmy snopy na polu, a oto mój snop podniósł się i stanął, a wasze snopy otoczyły go i pokłoniły się mojemu snopowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 8, 'I odpowiedzieli mu jego bracia: Czyżbyś miał królować nad nami? Czyż miałbyś nami rządzić? I jeszcze bardziej go znienawidzili z powodu snów i słów jego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 9, 'Śnił mu się jeszcze drugi sen i opowiedział go swoim braciom: Znowu śnił mi się sen, a oto słońce, księżyc i jedenaście gwiazd pokłoniły mi się.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 10, 'Gdy opowiedział to swemu ojcu i swoim braciom, jego ojciec zgromił go i powiedział mu: Cóż to za sen, który ci się śnił? Czy ja i twoja matka przyjdziemy z twoimi braćmi, aby ci się kłaniać aż do ziemi?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 11, 'I jego bracia zazdrościli mu, ale jego ojciec rozważał tę sprawę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 12, 'Potem jego bracia odeszli, aby paść trzody swego ojca w Sychem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 13, 'I Izrael powiedział do Józefa: Czy twoi bracia nie pasą trzody w Sychem? Chodź, a poślę cię do nich. A on odpowiedział: Oto jestem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 14, 'Wtedy powiedział mu: Idź teraz i dowiedz się, jak się mają twoi bracia i co się dzieje z trzodami, i daj mi znać. Wysłał go więc z doliny Hebronu, a on przyszedł do Sychem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 15, 'I spotkał go pewien człowiek, gdy błąkał się po polu. I człowiek ten zapytał go: Czego szukasz?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 16, 'A on odpowiedział: Szukam moich braci. Powiedz mi, proszę, gdzie oni pasą trzody.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 17, 'Człowiek ten odpowiedział: Odeszli stąd, bo słyszałem, jak mówili: Pójdźmy do Dotan. I Józef poszedł za swoimi braćmi i znalazł ich w Dotan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 18, 'Gdy ujrzeli go z daleka, zanim do nich przyszedł, naradzali się, aby go zabić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 19, 'I mówili jeden do drugiego: Oto idzie mistrz od snów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 20, 'Teraz więc chodźcie, zabijmy go i wrzućmy do jakiejś studni, i powiemy: Pożarł go zły zwierz. I zobaczymy, co będzie z jego snów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 21, 'Ruben, gdy to usłyszał, chciał go wybawić z ich rąk i powiedział: Nie zabijajmy go.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 22, 'Ruben powiedział też do nich: Nie wylewajcie krwi, ale wrzućcie go do tej studni, która jest na pustyni, i nie podnoście na niego ręki. A mówił to, aby go wybawić z ich rąk i przywrócić go swemu ojcu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 23, 'Gdy Józef przyszedł do swoich braci, obdarli go z jego szaty, z szaty wielobarwnej, którą miał na sobie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 24, 'Następnie chwycili go i wrzucili do studni, która była pusta, bez wody.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 25, 'Potem usiedli, aby jeść chleb, a gdy podnieśli swoje oczy, zobaczyli grupę Izmaelitów idących z Gileadu. Ich wielbłądy niosły wonne korzenie, kadzidło i mirrę, a szły, aby to zanieść do Egiptu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 26, 'Wtedy Juda powiedział do swoich braci: Jaki pożytek będzie z tego, że zabijemy naszego brata i zataimy jego krew?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 27, 'Chodźcie, sprzedajmy go Izmaelitom, a nie podnośmy na niego naszej ręki, bo to jest nasz brat i nasze ciało. I bracia go usłuchali.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 28, 'A gdy przechodzili Midianici, kupcy, wyciągnęli Józefa ze studni i sprzedali go Izmaelitom za dwadzieścia srebrników, a oni zaprowadzili Józefa do Egiptu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 29, 'Gdy Ruben wrócił do tej studni, Józefa już w studni nie było. I rozdarł swoje szaty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 30, 'Potem wrócił do swoich braci i powiedział: Nie ma chłopca, a ja dokąd pójdę?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 31, 'Wtedy wzięli szatę Józefa, zabili kozła i umoczyli szatę we krwi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 32, 'I posłali tę wielobarwną szatę, aby ją zaniesiono do jego ojca, i powiedzieli: Znaleźliśmy to. Zobacz, czy to szata twego syna, czy nie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 33, 'A on rozpoznał ją i powiedział: To jest szata mego syna, pożarł go zły zwierz. Józef na pewno został rozszarpany.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 34, 'Wtedy Jakub rozdarł swoje szaty, włożył wór na biodra i opłakiwał swego syna przez wiele dni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 35, 'I zeszli się wszyscy jego synowie i wszystkie jego córki, aby go pocieszyć, lecz nie dał się pocieszyć, ale mówił: Naprawdę zstąpię za moim synem do grobu. I opłakiwał go jego ojciec.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 36, 'A Midianici sprzedali Józefa do Egiptu Potifarowi, dworzaninowi faraona, dowódcy straży.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 1, 'W tym czasie Juda odszedł od swoich braci i wstąpił do pewnego mieszkańca Adullam, który miał na imię Chira.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 2, 'I Juda zobaczył tam córkę Kananejczyka, który miał na imię Szua; pojął ją i obcował z nią.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 3, 'A ona poczęła i urodziła syna, i nadał mu imię Er.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 4, 'I znów poczęła i urodziła syna, i nadała mu imię Onan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 5, 'Potem znowu urodziła syna i nadała mu imię Szela. A Juda był w Kezib, gdy mu go urodziła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 6, 'I Juda wziął dla swojego pierworodnego syna Era żonę imieniem Tamar.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 7, 'A Er, pierworodny Judy, był zły w oczach Pana, więc Pan go zabił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 8, 'Wtedy Juda powiedział do Onana: Obcuj z żoną twego brata i ożeń się z nią, i wzbudź twemu bratu potomstwo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 9, 'Lecz Onan wiedział, że to potomstwo nie miało być jego; gdy obcował z żoną swego brata, wyrzucał swoje nasienie na ziemię, aby nie wzbudzić potomstwa swemu bratu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 10, 'I nie podobało się Panu to, co Onan robił, dlatego i jego Pan zabił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 11, 'Wtedy Juda powiedział do swojej synowej Tamar: Mieszkaj w domu twego ojca jako wdowa, aż dorośnie mój syn Szela. Powiedział bowiem: Oby on też nie umarł jak jego bracia. I Tamar odeszła, i mieszkała w domu swego ojca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 12, 'Po długim czasie umarła córka Szuy, żona Judy. Gdy Juda już pocieszył się, poszedł wraz ze swoim przyjacielem Chirą Adullamitą do Timny, do tych, co strzygli jego owce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 13, 'I powiedziano o tym Tamarze: Oto twój teść idzie do Timny, aby strzyc swoje owce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 14, 'Zdjęła więc z siebie wdowie szaty, okryła się welonem i tak zasłonięta usiadła na rozstaju drogi, która prowadziła do Timny. Widziała bowiem, że Szela dorósł, a ona nie została mu dana za żonę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 15, 'A gdy Juda zobaczył ją, pomyślał, że to nierządnica, bo zakryła swoją twarz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 16, 'Zszedł więc do niej z drogi i powiedział: Proszę, pozwól mi obcować z tobą. Nie wiedział bowiem, że to była jego synowa. I powiedziała: Co mi dasz, abyś mógł ze mną obcować?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 17, 'I odpowiedział: Poślę ci koźlątko ze stada. A ona rzekła: Dasz mi zastaw, dopóki nie przyślesz?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 18, 'I powiedział: Cóż mam ci dać w zastaw? A ona odpowiedziała: Twój pierścień, twój sznur i twoją laskę, którą masz w ręce. Dał jej więc i obcował z nią; a ona poczęła z niego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 19, 'Potem wstała, odeszła, zdjęła z siebie welon i włożyła wdowie szaty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 20, 'A Juda posłał koźlątko przez swego przyjaciela Adullamitę, aby odebrał zastaw z ręki tej kobiety, ale ten jej nie znalazł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 21, 'I pytał ludzi w tym miejscu: Gdzie jest ta nierządnica, która była na rozstaju tej drogi? Oni odpowiedzieli: Nie było tu żadnej nierządnicy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 22, 'Wrócił więc do Judy i powiedział: Nie znalazłem jej. I ludzie w tym miejscu powiedzieli: Nie było tu żadnej nierządnicy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 23, 'Wtedy Juda powiedział: Niech sobie zatrzyma ten zastaw, abyśmy nie stali się pośmiewiskiem. Oto posyłałem to koźlątko, a ty jej nie znalazłeś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 24, 'Po upływie około trzech miesięcy powiedziano Judzie: Twoja synowa Tamar stała się nierządnicą i oto jest brzemienna z nierządu. Wtedy Juda powiedział: Wyprowadźcie ją i niech będzie spalona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 25, 'A gdy została wyprowadzona, posłała do swego teścia wiadomość: Jestem brzemienna z mężczyzny, do którego należą te rzeczy. Powiedziała przy tym: Rozpoznaj, proszę, czyj to pierścień, sznur i laska.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 26, 'Wtedy Juda rozpoznał je i powiedział: Ona jest sprawiedliwsza ode mnie, ponieważ nie dałem jej memu synowi Szeli. I więcej z nią nie obcował.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 27, 'Gdy nadszedł czas jej porodu, okazało się, że w jej łonie są bliźnięta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 28, 'A gdy rodziła, jedno dziecko wytknęło rękę, a położna ujęła ją i zawiązała na ręce czerwoną nić, mówiąc: Ten wyszedł pierwszy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 29, 'Gdy on cofnął swoją rękę, oto wyszedł jego brat i powiedziała: Jak się przedarłeś? Na tobie niech będzie rozerwanie. I nadała mu imię Peres.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 30, 'A potem wyszedł jego brat, na którego ręce była czerwona nić. I nadała mu imię Zerach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 1, 'A Józef został zaprowadzony do Egiptu. I Potifar, dworzanin faraona, dowódca straży, Egipcjanin, kupił go od Izmaelitów, którzy go tam zaprowadzili.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 2, 'Pan był z Józefem, tak że stał się człowiekiem, któremu się dobrze powodziło, i mieszkał w domu swego pana Egipcjanina.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 3, 'Jego pan widział, że Pan jest z nim i że Pan szczęści mu we wszystkim, co on czyni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 4, 'I Józef znalazł łaskę w jego oczach, i służył mu. Uczynił go zarządcą swego domu i wszystko, co miał, oddał w jego ręce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 5, 'A od tego czasu, gdy uczynił go zarządcą swego domu i wszystkiego, co miał, Pan błogosławił domowi Egipcjanina ze względu na Józefa. I błogosławieństwo Pana było nad wszystkim, co miał w domu i na polu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 6, 'Dlatego oddał wszystko, co miał, w ręce Józefa i o niczym u siebie nie wiedział, tylko o chlebie, który spożywał. A Józef był przystojny i miły dla oka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 7, 'Po tych wydarzeniach żona jego pana zwróciła swe oczy na Józefa i powiedziała: Połóż się ze mną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 8, 'Ale odmówił i powiedział do żony swego pana: Mój pan nie wie tak dobrze jak ja, co jest w jego domu, bo wszystko, co miał, oddał w moje ręce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 9, 'I nie ma w tym domu nikogo większego ode mnie, i nie zabronił mi niczego oprócz ciebie, bo ty jesteś jego żoną. Jak więc mógłbym popełnić tak wielkie zło i zgrzeszyć przeciwko Bogu?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 10, 'I chociaż namawiała Józefa dzień w dzień, on nie zgadzał się z nią położyć ani z nią być.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 11, 'Pewnego dnia, gdy wszedł do domu, aby wykonać swoje obowiązki, a nie było tam nikogo z domowników;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 12, 'Uchwyciła go za szatę i powiedziała: Połóż się ze mną. Ale on zostawił swoją szatę w jej ręku, uciekł i wyszedł na zewnątrz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 13, 'A gdy ona zobaczyła, że zostawił szatę w jej ręku i uciekł na zewnątrz;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 14, 'Zawołała swoich domowników i powiedziała do nich: Patrzcie, pan sprowadził do nas Hebrajczyka, aby nas zelżył. Przyszedł bowiem do mnie, aby się ze mną położyć, ale krzyknęłam donośnym głosem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 15, 'A gdy usłyszał, że podnoszę swój głos i wołam, zostawił szatę u mnie, uciekł i wyszedł na zewnątrz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 16, 'I zatrzymała u siebie jego szatę, aż przyszedł do domu jego pan;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 17, 'I powiedziała do niego te słowa: Przyszedł do mnie sługa, ten Hebrajczyk, którego przyprowadziłeś do nas, aby mnie zelżyć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 18, 'A gdy podniosłam swój głos i zawołałam, zostawił szatę u mnie i uciekł na zewnątrz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 19, 'Gdy jego pan usłyszał słowa swojej żony, które do niego powiedziała: Tak mi uczynił twój sługa, rozgniewał się bardzo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 20, 'Potem pan Józefa wziął go i oddał do więzienia, tam gdzie sadzano więźniów królewskich. I przebywał tam w więzieniu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 21, 'A Pan był z Józefem, okazał mu miłosierdzie i dał mu łaskę w oczach przełożonego więzienia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 22, 'Przełożony więzienia oddał więc pod władzę Józefa wszystkich więźniów, którzy byli w więzieniu; a wszystkim, co tam się działo, on zarządzał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 23, 'A przełożony więzienia nie doglądał tego, co mu powierzył, bo Pan był z nim, i co on czynił, to Pan szczęścił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 1, 'Po tych wydarzeniach podczaszy króla Egiptu i jego piekarz dopuścili się wykroczenia przeciwko swojemu panu, królowi Egiptu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 2, 'Faraon więc rozgniewał się na obu swoich dworzan, na przełożonego podczaszych i na przełożonego piekarzy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 3, 'I oddał ich do więzienia w domu dowódcy straży, na miejsce, gdzie Józef był więźniem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 4, 'A dowódca straży oddał ich pod nadzór Józefa, który im służył. I przebywali jakiś czas w więzieniu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 5, 'Pewnej nocy obydwaj – podczaszy i piekarz króla Egiptu, którzy byli więźniami w więzieniu – mieli sen, każdy inny, według swego tłumaczenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 6, 'A Józef przyszedł do nich rano i spostrzegł, że są smutni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 7, 'I zapytał dworzan faraona, którzy byli z nim w więzieniu, w domu jego pana: Czemu macie dziś tak smutne twarze?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 8, 'I odpowiedzieli mu: Śnił się nam sen, a nie ma nikogo, kto by go wytłumaczył. Józef powiedział do nich: Czy nie do Boga należą wytłumaczenia? Opowiedzcie mi, proszę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 9, 'Wtedy przełożony podczaszych opowiedział swój sen Józefowi: Śniło mi się, że przede mną była winorośl;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 10, 'I na winorośli były trzy gałązki. A ona jakby wypuszczała pąki i wychodził jej kwiat, i jej grona wydały dojrzałe winogrona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 11, 'A kubek faraona był w mojej ręce. Wziąłem więc winogrona i wyciskałem je do kubka faraona, i podawałem kubek w ręce faraona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 12, 'Wtedy Józef powiedział mu: Takie jest wytłumaczenie tego snu: Trzy gałązki to trzy dni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 13, 'Po trzech dniach faraon wywyższy twą głowę i przywróci cię na twój urząd, i będziesz podawał kubek faraona w jego rękę jak dawniej, gdy byłeś jego podczaszym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 14, 'Tylko wspomnij na mnie, gdy się będziesz miał dobrze, i wyświadcz mi, proszę, tę przysługę i wspomnij o mnie faraonowi, i uwolnij mnie z tego domu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 15, 'Bo siłą uprowadzono mnie z ziemi hebrajskiej, a do tego nic złego tu nie zrobiłem, żeby mnie wrzucono do tego więzienia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 16, 'A przełożony piekarzy, widząc, że dobrze wytłumaczył sen, powiedział do Józefa: Ja też miałem sen, a oto trzy białe kosze na mojej głowie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 17, 'A w najwyższym koszu były wszelkie rodzaje pieczywa dla faraona, a ptaki jadły je z kosza, który był na mojej głowie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 18, 'Wtedy Józef odpowiedział: Takie jest wytłumaczenie snu: Trzy kosze to trzy dni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 19, 'Po trzech dniach faraon zetnie ci głowę i powiesi cię na drzewie, a ptaki będą jadły twoje ciało.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 20, 'A trzeciego dnia, w dniu urodzin faraona, urządził on ucztę dla wszystkich swoich sług i w ich obecności kazał sprowadzić przełożonego podczaszych i przełożonego piekarzy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 21, 'I przywrócił przełożonego podczaszych na jego urząd, aby podawał kubek do rąk faraona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 22, 'A przełożonego piekarzy powiesił, jak im Józef wytłumaczył.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 23, 'Jednak przełożony podczaszych nie pamiętał o Józefie, ale zapomniał o nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 1, 'Po upływie dwóch lat śniło się faraonowi, że stał nad rzeką.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 2, 'A oto z rzeki wychodziło siedem pięknych i tłustych krów, które się pasły na łące.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 3, 'Oto też za nimi wychodziło z rzeki siedem innych krów, brzydkich i chudych, które stanęły obok pierwszych krów nad brzegiem rzeki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 4, 'I te brzydkie i chude krowy pożarły siedem pięknych i tłustych krów. Wtedy faraon się obudził.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 5, 'A gdy usnął, śnił po raz drugi. A oto siedem pełnych i cudnych kłosów wyrastało z jednego źdźbła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 6, 'Oto też siedem kłosów cienkich i wysuszonych od wiatru wschodniego wyrastało za nimi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 7, 'I te cienkie kłosy pożarły siedem pięknych i pełnych kłosów. Wtedy faraon się obudził, a był to sen.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 8, 'A gdy nastał ranek, był zaniepokojony w duchu i kazał wezwać wszystkich wróżbitów i mędrców Egiptu. I opowiedział im faraon swoje sny, ale nie było nikogo, kto by potrafił je faraonowi wytłumaczyć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 9, 'Wtedy przełożony podczaszych powiedział do faraona: Przypominam sobie dziś moje grzechy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 10, 'Faraon rozgniewał się na swoje sługi i oddał mnie pod straż w domu dowódcy straży, mnie i przełożonego piekarzy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 11, 'Tam jednej nocy śnił się nam sen, mnie i jemu; każdemu śnił się sen według jego wytłumaczenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 12, 'A był tam z nami młodzieniec, Hebrajczyk, sługa dowódcy straży, któremu opowiedzieliśmy nasze sny, a on wytłumaczył je nam, każdemu według jego snu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 13, 'I stało się tak, jak nam wytłumaczył: Mnie faraon przywrócił na moje miejsce, a tamtego powiesił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 14, 'Faraon kazał więc wezwać Józefa i prędko go wyprowadzono z więzienia. Ostrzygł się, zmienił szaty i przyszedł do faraona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 15, 'I faraon powiedział do Józefa: Śnił mi się sen, a nie ma nikogo, kto potrafi mi go wytłumaczyć. Ale słyszałem, jak mówiono o tobie, że gdy usłyszysz sen, umiesz go wytłumaczyć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 16, 'Józef odpowiedział faraonowi: To nie ja, ale Bóg da faraonowi szczęśliwą odpowiedź.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 17, 'Faraon powiedział więc do Józefa: Oto w moim śnie stałem na brzegu rzeki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 18, 'A z rzeki wychodziło siedem tłustych i pięknych krów i pasły się na łące.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 19, 'Za nimi zaś wychodziło siedem innych krów, nędznych, szpetnych i chudych; w całej ziemi Egiptu nie widziałem tak brzydkich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 20, 'I chude i szpetne krowy pożarły siedem pierwszych tłustych krów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 21, 'A choć je zjadły, nie było widać, że zjadły, ale były szpetne jak i przedtem. I obudziłem się.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 22, 'Potem widziałem we śnie, jak oto siedem kłosów, pełnych i dorodnych, wyrastało z jednego źdźbła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 23, 'A za nimi wyrastało siedem kłosów suchych, cienkich i wyschniętych od wschodniego wiatru.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 24, 'I te cienkie kłosy pożarły tych siedem dorodnych kłosów. I opowiedziałem to wróżbitom, ale nie było nikogo, kto by potrafił mi to wytłumaczyć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 25, 'Wtedy Józef powiedział do faraona: Sen faraona jest jeden – Bóg oznajmił faraonowi, co uczyni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 26, 'Siedem pięknych krów to siedem lat, a siedem dorodnych kłosów to też siedem lat. Jest to jeden sen.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 27, 'Siedem zaś chudych i szpetnych krów, które wychodziły za nimi, to siedem lat; a siedem pustych kłosów i wyschniętych od wschodniego wiatru to będzie siedem lat głodu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 28, 'A oto, co powiedziałem faraonowi: Bóg ukazał faraonowi, co uczyni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 29, 'Nadchodzi siedem lat wielkiej obfitości w całej ziemi Egiptu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 30, 'A po nich nastąpi siedem lat głodu i cała obfitość ziemi Egiptu pójdzie w zapomnienie, i głód wytrawi ziemię;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 31, 'Tak że obfitość ziemi nie będzie znana z powodu przyszłego głodu, bo będzie bardzo ciężki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 32, 'A skoro sen śnił się faraonowi dwukrotnie, oznacza to, że ta rzecz jest postanowiona przez Boga i Bóg śpieszy ją wykonać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 33, 'Teraz więc niech faraon znajdzie roztropnego i mądrego człowieka i postawi go nad ziemią Egiptu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 34, 'Niech faraon tak postąpi i ustanowi urzędników nad ziemią, i zbierze piątą część plonów ziemi Egiptu przez te siedem lat obfitości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 35, 'Niech zbierają wszelką żywność w tych nadchodzących dobrych latach i zgromadzą zboża do dyspozycji faraona, i niech przechowują żywność w miastach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 36, 'Żywność ta będzie zapasem dla ziemi na te siedem lat głodu, które będą w ziemi Egiptu, aby ziemia nie niszczała od głodu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 37, 'I podobało się to faraonowi i wszystkim jego sługom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 38, 'Faraon zapytał więc swoje sługi: Czy znajdziemy człowieka mu podobnego, w którym jest Duch Boży?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 39, 'Potem faraon powiedział do Józefa: Skoro Bóg oznajmił ci to wszystko, nie ma żadnego tak rozumnego i mądrego jak ty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 40, 'Ty będziesz nad moim domem, a cały mój lud będzie postępować według rozkazu twoich ust. Tylko tronem będę większy od ciebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 41, 'Faraon powiedział jeszcze do Józefa: Oto ustanowiłem cię nad całą ziemią Egiptu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 42, 'Zdjął więc faraon pierścień z ręki i włożył go na rękę Józefa, oblekł go też w szatę bisiorową, a na szyję włożył mu złoty łańcuch.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 43, 'I kazał go wozić na swoim drugim rydwanie, i wołano przed nim: Na kolana! I ustanowił go rządcą całej ziemi Egiptu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 44, 'Potem faraon powiedział do Józefa: Ja jestem faraonem, a bez twego pozwolenia nikt na całej ziemi Egiptu nie podniesie ani ręki, ani nogi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 45, 'I faraon nadał Józefowi imię Safnat Paneach, i dał mu za żonę Asenat, córkę Poti-Fery, kapłana z On. I Józef wyjechał na całą ziemię Egiptu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 46, 'Józef miał trzydzieści lat, gdy stanął przed faraonem, królem Egiptu. Potem Józef odszedł od faraona i objechał całą ziemię Egiptu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 47, 'A przez tych siedem urodzajnych lat ziemia rodziła obficie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 48, 'I Józef zgromadził całą żywność tych siedmiu lat, która była w ziemi Egiptu, i składał żywność w miastach. Składał w miastach urodzajne plony z otaczających je pól.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 49, 'Józef więc nagromadził zboża tak wiele jak piasku morskiego, aż przestano je liczyć, bo było go bez liku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 50, 'A zanim nastały lata głodu, Józefowi urodzili się dwaj synowie, których mu urodziła Asenat, córka Poti-Fery, kapłana z On.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 51, 'Józef nadał pierworodnemu imię Manasses, gdyż mówił: Bóg dał mi zapomnieć o całej mojej udręce i o całym domu mego ojca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 52, 'A drugiemu nadał imię Efraim, gdyż mówił: Bóg rozmnożył mnie w ziemi mego utrapienia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 53, 'I skończyło się siedem lat obfitości, która była w ziemi Egiptu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 54, 'I nadeszło siedem lat głodu, tak jak Józef przepowiedział. I głód był we wszystkich krainach, ale w całej ziemi Egiptu był chleb.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 55, 'Gdy jednak na całej ziemi Egiptu był głód, lud wołał do faraona o chleb. I faraon powiedział wszystkim Egipcjanom: Idźcie do Józefa, a co wam powie, zróbcie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 56, 'I na całej ziemi był głód. Józef otworzył więc wszystkie spichlerze, w których było zboże, i sprzedawał Egipcjanom, bo głód wzmógł się w ziemi Egiptu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 57, 'I ze wszystkich krajów przyjeżdżano do Egiptu, by kupować żywność od Józefa, bo wzmógł się głód na całej ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 1, 'Gdy Jakub dowiedział się, że w Egipcie jest zboże, powiedział do swoich synów: Czemu się patrzycie jeden na drugiego?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 2, 'I mówił im: Oto słyszałem, że w Egipcie jest zboże. Jedźcie tam i kupcie je nam stamtąd, abyśmy żyli, a nie pomarli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 3, 'Dziesięciu braci Józefa wyruszyło więc do Egiptu, aby kupić zboże.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 4, 'Ale Jakub nie posłał Beniamina, brata Józefa, z jego braćmi, bo powiedział: By nie spotkało go jakieś nieszczęście.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 5, 'Synowie Izraela przybyli więc wraz z innymi, aby kupić zboże, gdyż był głód w ziemi Kanaan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 6, 'A Józef był rządcą tej ziemi i to on sprzedawał zboża całej ludności tej ziemi. A gdy przyszli bracia Józefa, pokłonili mu się twarzą do ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 7, 'Gdy Józef ujrzał swych braci, poznał ich, lecz udawał przed nimi obcego i rozmawiał z nimi surowo. Zapytał ich: Skąd przyszliście? Odpowiedzieli: Z ziemi Kanaan, aby nakupić żywności.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 8, 'Józef rozpoznał swoich braci, ale oni go nie poznali.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 9, 'I Józef przypomniał sobie sny, które mu się śniły o nich, i powiedział im: Jesteście szpiegami i przyszliście, aby wypatrzyć nieobronne miejsca tej ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 10, 'A oni mu odpowiedzieli: Nie, mój panie. Twoi słudzy przyszli, aby nakupić żywności.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 11, 'Wszyscy jesteśmy synami jednego człowieka. Jesteśmy uczciwi. Twoi słudzy nie są szpiegami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 12, 'A on powiedział do nich: Nie, ale przyszliście wypatrzyć nieobronne miejsca tej ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 13, 'Powiedzieli: Było nas, twoich sług, dwunastu braci, synów jednego człowieka w ziemi Kanaan. Najmłodszy jest z naszym ojcem w domu, a jednego już nie ma.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 14, 'Józef rzekł im: Jest tak, jak wam powiedziałem – jesteście szpiegami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 15, 'Zostaniecie co do tego wybadani: Na życie faraona, nie wyjdziecie stąd, dopóki nie przyjdzie tu wasz młodszy brat.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 16, 'Wyślijcie jednego z was, aby przyprowadził waszego brata, a wy zostaniecie w więzieniu, aż wasze słowa się potwierdzą, czy mówicie prawdę. A jeśli nie, na życie faraona, jesteście szpiegami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 17, 'I oddał ich pod straż na trzy dni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 18, 'A trzeciego dnia Józef powiedział do nich: Zróbcie tak, a będziecie żyć, bo ja się boję Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 19, 'Jeśli jesteście uczciwi, niech jeden z waszych braci pozostanie związany tu w więzieniu; a wy jedźcie i odnieście zboże, aby się pozbyć głodu z waszych domów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 20, 'I przyprowadźcie do mnie waszego najmłodszego brata, a wasze słowa sprawdzą się i nie umrzecie. I tak zrobili.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 21, 'Mówili jeden do drugiego: Naprawdę zgrzeszyliśmy przeciwko naszemu bratu, bo widząc strapienie jego duszy, gdy nas błagał, nie wysłuchaliśmy go. Dlatego przyszło na nas to utrapienie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 22, 'Wtedy Ruben odpowiedział im: Czyż nie mówiłem wam: Nie grzeszcie przeciw chłopcu? A nie usłuchaliście. Oto teraz żąda się odpowiedzialności za jego krew.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 23, 'Lecz oni nie wiedzieli, że Józef rozumie, bo rozmawiał z nimi przez tłumacza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 24, 'Wtedy odwrócił się od nich i zapłakał. Potem obrócił się do nich i rozmawiał z nimi. Wziął spośród nich Symeona i związał go na ich oczach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 25, 'Potem Józef rozkazał, aby napełniono ich wory zbożem i każdemu z nich wrzucono do jego wora pieniądze, i żeby dano im żywność na drogę. I tak zrobiono.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 26, 'Wtedy oni włożyli zboża na swoje osły i odjechali stamtąd.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 27, 'I gdy jeden z nich rozwiązał swój wór, aby w gospodzie dać karmę swemu osłu, zobaczył swoje pieniądze; były bowiem na wierzchu jego wora.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 28, 'I powiedział do swoich braci: Zwrócono mi pieniądze, oto są w moim worze. Wtedy zamarło im serce i przerazili się, mówiąc jeden do drugiego: Cóż to nam Bóg uczynił?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 29, 'Potem przyszli do swego ojca Jakuba, do ziemi Kanaan, i opowiedzieli mu wszystko, co im się przydarzyło:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 30, 'Ten człowiek, pan tej ziemi, rozmawiał z nami surowo i wziął nas za szpiegów ziemi;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 31, 'Powiedzieliśmy mu: Jesteśmy uczciwi, nie jesteśmy szpiegami;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 32, 'Było nas dwunastu braci, synów naszego ojca; jednego już nie ma, a najmłodszy jest teraz z naszym ojcem w ziemi Kanaan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 33, 'I ten człowiek, pan tej ziemi, powiedział do nas: Po tym poznam, że jesteście uczciwi; zostawcie jednego z waszych braci u mnie, weźcie zboże, aby pozbyć się głodu z waszych domów, i idźcie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 34, 'Potem przyprowadźcie waszego najmłodszego brata do mnie, abym poznał, że nie jesteście szpiegami, ale ludźmi uczciwymi. Wtedy oddam wam waszego brata, a w tej ziemi będziecie mogli handlować.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 35, 'A gdy opróżniali swoje wory, każdy znalazł w swoim worze węzeł pieniędzy. Gdy wraz ze swoim ojcem zobaczyli węzły z pieniędzmi, przerazili się.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 36, 'Wtedy ich ojciec Jakub powiedział im: Osierociliście mnie. Nie ma Józefa i Symeona, a weźmiecie Beniamina; całe zło się na mnie zwaliło.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 37, 'Ruben powiedział do swego ojca: Zabij moich dwóch synów, jeśli go z powrotem nie przyprowadzę. Oddaj go pod moją opiekę, a ja ci go zwrócę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 38, 'Ale on powiedział: Mój syn nie pójdzie z wami, gdyż jego brat umarł i tylko on jeden został. Jeśli przydarzy mu się nieszczęście na drodze, którą pójdziecie, w żalu doprowadzicie mnie, osiwiałego, do grobu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 1, 'A ciężki głód panował w tej ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 2, 'I gdy zużyli zboże, które przynieśli z Egiptu, ich ojciec powiedział do nich: Idźcie znowu i kupcie nam trochę żywności.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 3, 'Juda powiedział do niego: Ten człowiek uroczyście nam oświadczył: Nie zobaczycie mojej twarzy, jeśli nie będzie z wami waszego brata.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 4, 'Jeśli więc poślesz naszego brata z nami, pojedziemy i nakupimy ci żywności;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 5, 'Ale jeśli nie poślesz, nie pojedziemy, bo ten człowiek mówił do nas: Nie zobaczycie mojej twarzy, jeśli nie będzie z wami waszego brata.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 6, 'Izrael zapytał: Dlaczego sprawiliście mi ból, mówiąc temu człowiekowi, że macie jeszcze brata?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 7, 'Odpowiedzieli: Ten człowiek dokładnie się wypytał o nas i naszą rodzinę: Żyje jeszcze wasz ojciec? Macie jeszcze jakiegoś brata? I odpowiedzieliśmy mu na jego pytania. Skąd mogliśmy wiedzieć, że powie: Przyprowadźcie mi tu waszego brata?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 8, 'I Juda powiedział do swego ojca Izraela: Poślij chłopca ze mną. Powstaniemy i pojedziemy, abyśmy żyli, a nie pomarli z głodu, tak my, jak i ty, i nasze dzieci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 9, 'Ja biorę odpowiedzialność za niego, ode mnie się go domagaj. Jeśli nie przyprowadzę go do ciebie i nie stawię go przed tobą, na zawsze będę ponosił za to winę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 10, 'Gdybyśmy bowiem nie zwlekali, wrócilibyśmy już dwa razy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 11, 'Wtedy Izrael, ich ojciec, powiedział do nich: Jeśli tak musi być, zróbcie w ten sposób: weźcie z najlepszych owoców ziemi w wasze naczynia i zanieście je temu człowiekowi w darze – trochę balsamu, trochę miodu, wonności, mirry, orzechów i migdałów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 12, 'Weźcie też ze sobą podwójną sumę pieniędzy, a pieniądze wrzucone na wierzch waszych worów zabierzcie ze sobą, bo może to była pomyłka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 13, 'Weźcie także waszego brata, wstańcie i jedźcie znowu do tego człowieka;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 14, 'A niech Bóg Wszechmogący da wam miłosierdzie przed tym człowiekiem, aby wam wypuścił waszego drugiego brata i Beniamina. A jeśli mam stracić swoje dzieci, to je stracę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 15, 'Mężczyźni wzięli więc ten dar, zabrali ze sobą podwójną sumę pieniędzy oraz Beniamina, wstali i pojechali do Egiptu, i stanęli przed Józefem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 16, 'A gdy Józef zobaczył z nimi Beniamina, powiedział do zarządcy jego domu: Wprowadź tych ludzi do domu, zabij bydlę i przyrządź, bo ci ludzie w południe będą jedli ze mną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 17, 'Człowiek ten zrobił, jak mu Józef rozkazał, i wprowadził tych ludzi do domu Józefa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 18, 'Gdy zostali wprowadzeni do domu Józefa, bali się i mówili: Wprowadzono nas tu z powodu tych pieniędzy, które za pierwszym razem włożono do naszych worów, aby rzucić na nas oszczerstwo, napaść na nas i wziąć w niewolę nas i nasze osły.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 19, 'Podeszli do zarządcy domu Józefa i rozmawiali z nim w drzwiach domu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 20, 'I powiedzieli: Pozwól, panie. Przyjechaliśmy za pierwszym razem kupić żywności.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 21, 'A gdy przyjechaliśmy do gospody i rozwiązaliśmy nasze wory, pieniądze każdego były na wierzchu jego wora, nasze pieniądze w pełnej wadze. Przywieźliśmy je więc ze sobą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 22, 'Przywieźliśmy też inne pieniądze ze sobą, aby nakupić żywności. Nie wiemy, kto włożył nasze pieniądze do naszych worów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 23, 'A on powiedział: Pokój wam, nie bójcie się. Bóg wasz, Bóg waszego ojca, dał wam skarb do waszych worów. Wasze pieniądze doszły do mnie. I wyprowadził do nich Symeona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 24, 'Człowiek ten wprowadził tych ludzi do domu Józefa, dał im wody, aby umyli sobie nogi; dał też karmę ich osłom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 25, 'Potem przygotowali dar, zanim Józef przyszedł w południe. Słyszeli bowiem, że tam mieli jeść chleb.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 26, 'A gdy Józef wszedł do domu, przynieśli mu dar, który mieli ze sobą w tym domu, i pokłonili mu się aż do ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 27, 'I dowiadywał się, jak się im powodzi, i zapytał: Czy wasz ojciec jest zdrowy, ten starzec, o którym mi opowiadaliście? Czy jeszcze żyje?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 28, 'A oni odpowiedzieli: Twój sługa, nasz ojciec, jest zdrowy, jeszcze żyje. I uklękli, i pokłonili mu się.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 29, 'Wtedy podniósł swe oczy i zobaczył swego brata Beniamina, syna swej matki, i zapytał: Czy to jest wasz najmłodszy brat, o którym mi opowiadaliście? I powiedział mu: Niech Bóg będzie ci miłosierny, miły synu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 30, 'I nagle Józef wyszedł, bo wzruszył się do głębi swym bratem, i szukał miejsca, gdzie mógłby zapłakać. Wszedł więc do komnaty i tam płakał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 31, 'Potem umył swoją twarz, wyszedł i gdy się opanował, powiedział: Kładźcie chleb.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 32, 'Położono jemu osobno, im osobno i osobno Egipcjanom, którzy z nim jedli. Egipcjanie bowiem nie mogą jeść chleba z Hebrajczykami, gdyż to budzi odrazę u Egipcjan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 33, 'I usiedli przed nim, pierworodny według swego pierworództwa, a młodszy według swej młodości. I dziwili się ci mężczyźni, patrząc jeden na drugiego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 34, 'Potem brał potrawy sprzed siebie i kazał im zanieść. A porcja Beniamina była pięciokrotnie większa od porcji ich wszystkich. Pili i podpili sobie z nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 1, 'Wtedy Józef rozkazał zarządcy swego domu: Napełnij wory tych ludzi zbożem, ile tylko mogą unieść, a pieniądze każdego włóż na wierzch jego wora.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 2, 'Mój kielich też, kielich srebrny, włóż na wierzch wora najmłodszego razem z pieniędzmi za zboże. I zrobił według słów Józefa, jak mu rozkazał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 3, 'O świcie wyprawiono tych ludzi razem z ich osłami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 4, 'Gdy wyszli z miasta i byli niedaleko, Józef powiedział do zarządcy swego domu: Wstań, goń tych ludzi, a gdy ich dogonisz, powiedz do nich: Czemu oddaliście złem za dobro?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 5, 'Czy to nie jest kielich, z którego pija mój pan i z którego wróży? Źle postąpiliście, dopuszczając się tego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 6, 'Ten dogonił ich więc i powiedział do nich te słowa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 7, 'Ale oni mu odpowiedzieli: Dlaczego mój pan mówi takie słowa? Nie daj Boże, aby twoi słudzy mieli tak postąpić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 8, 'Przecież pieniądze, które znaleźliśmy na wierzchu naszych worów, przynieśliśmy do ciebie z powrotem z ziemi Kanaan. Jakże mielibyśmy kraść z domu twego pana srebro lub złoto?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 9, 'U którego z twoich sług to się znajdzie, niech umrze, a my będziemy niewolnikami mego pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 10, 'On powiedział: Niech będzie tak, jak mówicie. Przy którym znajdzie się kielich, ten będzie niewolnikiem, a wy będziecie niewinni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 11, 'Wtedy każdy szybko zdjął swój wór na ziemię i rozwiązał go.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 12, 'I szukał, zaczynając od starszego, a kończąc na najmłodszym. I znalazł kielich w worze Beniamina.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 13, 'Wtedy rozdarli swoje szaty, każdy załadował swego osła i wrócili do miasta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 14, 'Przyszedł więc Juda i jego bracia do domu Józefa, który tam jeszcze był. I upadli przed nim na ziemię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 15, 'I Józef zapytał ich: Co zrobiliście? Czy nie wiedzieliście, że taki człowiek jak ja potrafi wróżyć?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 16, 'Wtedy Juda odpowiedział: Cóż możemy odpowiedzieć memu panu? Co możemy mówić i jak mamy się usprawiedliwić? Bóg znalazł nieprawość u twoich sług. Oto jesteśmy niewolnikami mego pana, zarówno my, jak i ten, u którego znalazł się kielich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 17, 'A on odpowiedział: Nie daj Boże, abym miał tak uczynić. Człowiek, w którego ręku znaleziono kielich, będzie moim niewolnikiem. Wy zaś jedźcie w pokoju do waszego ojca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 18, 'Wtedy Juda podszedł do niego i powiedział: Mój panie! Pozwól twemu słudze mówić słowo do uszu mego pana, a niech nie zapala się twój gniew na twego sługę, gdyż ty jesteś jak sam faraon.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 19, 'Mój pan pytał swoich sług: Czy macie ojca albo brata?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 20, 'Wtedy odpowiedzieliśmy memu panu: Mamy ojca, starca, i chłopca małego spłodzonego w jego starości. Jego brat umarł i tylko on został po swej matce, i jego ojciec go kocha.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 21, 'Potem mówiłeś do nas, swoich sług: Przyprowadźcie go do mnie, abym mógł go zobaczyć własnymi oczyma.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 22, 'I mówiliśmy do mego pana: Chłopiec nie będzie mógł opuścić swego ojca, bo gdyby opuścił swego ojca, ten by umarł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 23, 'Wtedy powiedziałeś do swoich sług: Jeśli nie przyjdzie z wami wasz najmłodszy brat, więcej nie zobaczycie mojej twarzy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 24, 'Gdy więc przyszliśmy do twego sługi, mego ojca, powtórzyliśmy mu te słowa mego pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 25, 'Wtedy nasz ojciec powiedział: Jedźcie znowu i kupcie nam trochę żywności.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 26, 'I powiedzieliśmy: Nie możemy tam iść. Lecz jeśli będzie z nami nasz najmłodszy brat, wtedy pojedziemy. Bo nie będziemy mogli zobaczyć twarzy tego człowieka, jeśli nie będzie z nami naszego najmłodszego brata.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 27, 'I twój sługa, mój ojciec, powiedział do nas: Wy wiecie, że moja żona urodziła mi dwóch synów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 28, 'Jeden wyszedł ode mnie i powiedziałem: Na pewno został rozszarpany przez zwierzę i nie widziałem go do dziś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 29, 'A jeśli zabierzecie mi też tego i spotka go nieszczęście, wtedy w żalu doprowadzicie mnie, osiwiałego, do grobu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 30, 'Dlatego jeśli przyjdę do twego sługi, mojego ojca, a nie będzie z nami chłopca, z którym jest bardzo związany;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 31, 'Stanie się tak, że jak tylko zobaczy, że chłopca nie ma, umrze. A twoi słudzy doprowadzą twego sługę, naszego ojca, osiwiałego, z żalu do grobu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 32, 'Bo twój sługa wziął na siebie odpowiedzialność przed ojcem i mówił: Jeśli go nie przyprowadzę, będę po wszystkie dni winien grzechu przeciw mojemu ojcu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 33, 'Teraz więc, proszę, niech twój sługa zostanie niewolnikiem mego pana zamiast tego chłopca, a niech chłopak idzie ze swymi braćmi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 34, 'Bo jak ja mam wrócić do mego ojca, gdy nie będzie ze mną tego chłopca? Nie chciałbym patrzeć na rozpacz, która by dotknęła mego ojca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 1, 'Wtedy Józef nie mógł się dalej powstrzymać przed wszystkimi, którzy stali przed nim, i zawołał: Wyprowadźcie wszystkich ode mnie. I nikt przy nim nie został, gdy Józef dał się poznać swoim braciom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 2, 'I wybuchnął tak głośnym płaczem, że słyszeli to Egipcjanie, słyszał też dom faraona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 3, 'I Józef powiedział do swoich braci: Ja jestem Józef. Czy mój ojciec jeszcze żyje? A jego bracia nie mogli mu odpowiedzieć, bo zatrwożyli się wobec niego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 4, 'Wtedy Józef powiedział do swoich braci: Zbliżcie się, proszę, do mnie. A gdy zbliżyli się, powiedział: Ja jestem Józef, wasz brat, którego sprzedaliście do Egiptu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 5, 'Jednak teraz nie smućcie się ani się nie bójcie, że sprzedaliście mnie tutaj. Bóg bowiem posłał mnie przed wami dla zachowania waszego życia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 6, 'Bo już dwa lata trwa głód na ziemi, a jeszcze pięć lat zostaje, w których nie będzie ani orki, ani żniwa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 7, 'Bóg posłał mnie więc przed wami, aby zachować wam potomność na ziemi i żeby ocalić wam życie dzięki wielkiemu wybawieniu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 8, 'Tak więc nie wy mnie tu posłaliście, ale Bóg, który mnie ustanowił ojcem dla faraona i panem całego jego domu oraz władcą nad całą ziemią Egiptu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 9, 'Idźcie więc szybko do mego ojca i powiedzcie do niego: Tak mówi twój syn Józef: Bóg uczynił mnie panem całego Egiptu, przyjedź do mnie, nie zwlekaj.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 10, 'Będziesz mieszkał w ziemi Goszen i będziesz blisko mnie, ty, twoi synowie i synowie twoich synów, twoje owce i woły, i wszystko, co masz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 11, 'Będę cię tam żywił, bo będzie jeszcze pięć lat głodu, byś nie zginął z niedostatku ty, twój dom i wszystko, co masz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 12, 'A oto wasze oczy i oczy mego brata Beniamina widzą, że moje usta do was mówią.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 13, 'Opowiedzcie też memu ojcu o całej mojej chwale w Egipcie i o wszystkim, co widzieliście; spieszcie się więc i przyprowadźcie tu mego ojca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 14, 'Potem rzucił się na szyję swemu bratu Beniaminowi i zapłakał. Beniamin też płakał na jego szyi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 15, 'I pocałował wszystkich swoich braci, i płakał nad nimi. Potem jego bracia rozmawiali z nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 16, 'I rozgłoszono tę wieść w domu faraona: Przyjechali bracia Józefa. I podobało się to faraonowi i jego sługom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 17, 'Wtedy faraon powiedział do Józefa: Powiedz swoim braciom: Zróbcie tak: Załadujcie swoje zwierzęta i idźcie, wróćcie do ziemi Kanaan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 18, 'Zabierzcie waszego ojca i waszych domowników i przyjedźcie do mnie. A dam wam dobre miejsce w ziemi Egiptu i będziecie się żywić tym, co najlepsze z tej ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 19, 'I rozkaż im: Tak zróbcie: Weźcie sobie z ziemi Egiptu wozy dla waszych dzieci i dla waszych żon, weźcie też waszego ojca i przyjedźcie tutaj.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 20, 'Nie żałujcie waszych sprzętów, gdyż dobro całej ziemi Egiptu będzie wasze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 21, 'Tak zrobili więc synowie Izraela. Józef dał im wozy zgodnie z rozkazem faraona, dał im też żywności na drogę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 22, 'Dał każdemu z nich szaty na zmianę, a Beniaminowi dał trzysta srebrników i pięć szat na zmianę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 23, 'Posłał też swemu ojcu takie rzeczy: dziesięć osłów niosących najlepsze płody Egiptu i dziesięć oślic niosących zboże, chleb i żywność na drogę dla jego ojca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 24, 'Wyprawił więc swoich braci i gdy odjeżdżali, powiedział do nich: Nie kłóćcie się po drodze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 25, 'Wyjechali z Egiptu i przyjechali do ziemi Kanaan, do swego ojca Jakuba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 26, 'I oznajmili mu: Józef jeszcze żyje i jest władcą nad całą ziemią Egiptu. I zasłabło jego serce, bo im nie wierzył.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 27, 'Lecz oni powtórzyli mu wszystkie słowa Józefa, które im powiedział. A kiedy zobaczył wozy, które Józef posłał, aby go na nich przywieziono, ożył duch ich ojca Jakuba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 28, 'I Izrael powiedział: To mi wystarczy. Mój syn Józef jeszcze żyje. Pójdę i zobaczę go, zanim umrę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 1, 'Tak więc Izrael wyruszył w drogę ze wszystkim, co miał; a gdy przybył do Beer-Szeby, złożył ofiary Bogu swego ojca Izaaka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 2, 'Wtedy Bóg powiedział do Izraela w nocnym widzeniu: Jakubie, Jakubie! A on odpowiedział: Oto jestem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 3, 'I powiedział: Ja jestem Bogiem, Bogiem twego ojca. Nie bój się zejść do Egiptu, bo tam cię rozmnożę w wielki naród.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 4, 'Pójdę z tobą do Egiptu i wyprowadzę cię stamtąd z powrotem, a Józef położy swoją rękę na twoje oczy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 5, 'I Jakub wyruszył z Beer-Szeby. I synowie Izraela wzięli swego ojca Jakuba, swoje dzieci i swe żony na wozy, które faraon posłał, aby go przywieziono.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 6, 'Zebrali też swe stada i swój dobytek, który zdobyli w ziemi Kanaan, i przyjechali do Egiptu, Jakub i całe jego potomstwo razem z nim;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 7, 'Swych synów i synów swoich synów, swoje córki i córki swoich synów oraz całe swoje potomstwo prowadził ze sobą do Egiptu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 8, 'A to są imiona synów Izraela, którzy weszli do Egiptu – Jakub i jego synowie: pierworodny Jakuba, Ruben.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 9, 'Synowie Rubena: Henoch, Pallu, Chesron i Karmi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 10, 'Synowie Symeona: Jemuel, Jamin, Ohad, Jakin, Sochar i Szaul, syn kobiety Kananejki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 11, 'Synowie Lewiego: Gerszon, Kehat i Merari.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 12, 'Synowie Judy: Er, Onan, Szela, Peres i Zerach. Lecz Er i Onan umarli w ziemi Kanaan. A synami Peresa byli: Chesron i Chamul.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 13, 'Synowie Issachara: Tola, Puwwa, Job i Szimron.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 14, 'Synowie Zebulona: Sered, Elon i Jachleel.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 15, 'A to są synowie Lei, których – jak i córkę Dinę, urodziła Jakubowi w Paddan-Aram. Wszystkich dusz jego synów i córek było trzydzieści trzy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 16, 'Synowie Gada: Sifion, Chaggi, Szuni, Esbon, Eri, Arodi i Areli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 17, 'Synowie Aszera: Jimna, Jiszwa, Jiszwi, Beria i siostra ich Serach. A synowie Berii: Cheber i Malkiel.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 18, 'To są synowie Zilpy, którą Laban dał swej córce Lei, których ona urodziła Jakubowi – szesnaście dusz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 19, 'Synowie Racheli, żony Jakuba: Józef i Beniamin.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 20, 'Józefowi zaś urodzili się w ziemi Egiptu Manasses i Efraim, których urodziła Asenat, córka Poti-Fery, kapłana z On.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 21, 'Synowie Beniamina: Bela, Beker, Aszbel, Gera, Naaman, Echi, Rosz, Muppim, Chuppim i Ard.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 22, 'To są synowie Racheli, którzy się urodzili Jakubowi. Wszystkich dusz – czternaście.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 23, 'Synowie Dana: Chuszim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 24, 'Synowie Neftalego: Jachseel, Guni, Jeser i Szillem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 25, 'To są synowie Bilhy, którą Laban dał swej córce Racheli, i których urodziła Jakubowi. Wszystkich dusz – siedem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 26, 'Wszystkich, którzy przyszli z Jakubem do Egiptu, pochodzących z jego lędźwi, oprócz żon synów Jakuba, wszystkich dusz było sześćdziesiąt sześć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 27, 'A synów Józefa, którzy mu się urodzili w Egipcie, były dwie dusze. I tak wszystkich dusz z domu Jakuba, które weszły do Egiptu, było siedemdziesiąt.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 28, 'I Jakub posłał przed sobą Judę do Józefa, aby go uprzedził, zanim przybędzie do Goszen. I przybyli do ziemi Goszen.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 29, 'I Józef zaprzągł swój wóz, i wyjechał naprzeciw swemu ojcu Izraelowi do Goszen. A gdy go zobaczył, rzucił mu się na szyję i długo płakał na jego szyi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 30, 'Wtedy Izrael powiedział do Józefa: Mogę już umrzeć, skoro ujrzałem twoją twarz, że jeszcze żyjesz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 31, 'Józef powiedział do swoich braci i do domu swego ojca: Pójdę zawiadomić faraona i powiem mu: Moi bracia i dom mego ojca, którzy byli w ziemi Kanaan, przyjechali do mnie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 32, 'A ci mężczyźni są pasterzami, bo zajmowali się hodowlą bydła. Przyprowadzili więc swoje owce i woły, i wszystko, co mieli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 33, 'A gdy wezwie was faraon i zapyta: Czym się zajmujecie?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 34, 'Odpowiecie: Twoi słudzy od swego dzieciństwa aż do dziś są pasterzami, my i nasi ojcowie. W ten sposób będziecie mogli mieszkać w ziemi Goszen, bo Egipcjanie brzydzą się każdym pasterzem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 1, 'Józef więc przyszedł i powiedział faraonowi: Mój ojciec i moi bracia ze swymi owcami, wołami i ze wszystkim, co mają, przybyli z ziemi Kanaan; oto są w ziemi Goszen.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 2, 'A spośród swych braci wziął pięciu mężczyzn i przedstawił ich faraonowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 3, 'I faraon zapytał jego braci: Czym się zajmujecie? A oni odpowiedzieli faraonowi: Twoi słudzy są pasterzami, my i nasi ojcowie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 4, 'Powiedzieli jeszcze do faraona: Przyszliśmy, aby przebywać w tej ziemi, bo nie ma paszy dla stad, które mają twoi słudzy, gdyż ciężki głód panuje w ziemi Kanaan. Teraz prosimy, pozwól, aby twoi słudzy mieszkali w ziemi Goszen.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 5, 'Wtedy faraon powiedział do Józefa: Twój ojciec i twoi bracia przybyli do ciebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 6, 'Ziemia Egiptu jest przed tobą. W najlepszym miejscu tej ziemi osadź twego ojca i twoich braci, niech mieszkają w ziemi Goszen. A jeśli wiesz, że są wśród nich dzielni ludzie, uczyń ich przełożonymi nad moimi stadami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 7, 'I Józef przyprowadził swego ojca Jakuba, i postawił go przed faraonem. A Jakub błogosławił faraona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 8, 'Faraon zapytał Jakuba: Ile lat życia sobie liczysz?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 9, 'Jakub odpowiedział faraonowi: Liczba lat mego pielgrzymowania to sto trzydzieści. Krótkie i złe były lata mego życia i nie osiągnąłem wieku moich ojców podczas ich pielgrzymowania.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 10, 'Potem Jakub pobłogosławił faraona i odszedł sprzed jego oblicza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 11, 'Wtedy Józef osiedlił swego ojca i swoich braci i dał im posiadłość w ziemi Egiptu, w najlepszym miejscu tej krainy, w ziemi Ramses, jak rozkazał faraon.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 12, 'I Józef żywił chlebem swego ojca i swoich braci, i cały dom swego ojca, aż do najmniejszego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 13, 'A w całej ziemi nie było chleba, bo panował bardzo ciężki głód i była utrapiona przez głód ziemia Egiptu i ziemia Kanaan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 14, 'Józef zebrał więc wszystkie pieniądze, które znajdowały się w ziemi Egiptu i w ziemi Kanaan, za żywność, którą kupowano. I Józef wniósł te pieniądze do skarbu faraona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 15, 'A gdy zabrakło pieniędzy w ziemi Egiptu i w ziemi Kanaan, wszyscy Egipcjanie przyszli do Józefa i powiedzieli: Daj nam chleba. Dlaczego mamy umierać na twoich oczach? Gdyż nam już zabrakło pieniędzy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 16, 'Józef na to odpowiedział: Dajcie wasze bydła, a dam wam żywność za wasze bydła, skoro zabrakło wam pieniędzy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 17, 'Przyprowadzili więc swoje bydła do Józefa; i Józef dał im chleb za konie, za trzody owiec, za stada wołów i za osły. W tym roku zaopatrywał ich w żywność w zamian za wszelkie ich bydło.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 18, 'A gdy minął ten rok, przyszli do niego w następnym roku i powiedzieli: Nie ukryjemy przed naszym panem, że już skończyły się nam pieniądze, a stada bydła należą do naszego pana. Nie zostaje nam nic przed naszym panem jak tylko nasze ciała i nasze pole.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 19, 'Dlaczego mamy umierać na twoich oczach, zarówno my, jak i nasza ziemia? Kupuj za chleb nas i nasze pole, a my i nasza ziemia będziemy w niewoli u faraona. Daj nam tylko ziarno, abyśmy żyli, a nie pomarli, i by ziemia nie opustoszała.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 20, 'I tak kupił Józef całą ziemię Egiptu dla faraona, bo każdy Egipcjanin sprzedał swoje pole, gdyż wzmógł się wśród nich głód. I cała ziemia stała się własnością faraona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 21, 'I przeniósł lud do miast, od jednego krańca Egiptu do drugiego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 22, 'Nie kupił tylko ziemi kapłanów, bo kapłani mieli żywność przydzieloną im przez faraona i żywili się swoją żywnością, którą dał im faraon. Dlatego nie sprzedali swej ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 23, 'Potem Józef powiedział do ludu: Oto teraz kupiłem was i waszą ziemię dla faraona. Macie tu ziarno, obsiejcie nim pola.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 24, 'A piątą część waszych plonów oddacie faraonowi, cztery zaś części będą wasze – na obsianie pól i na żywność dla tych, którzy są w waszych domach, i na żywność dla waszych dzieci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 25, 'Wtedy odpowiedzieli: Uratowałeś nam życie! Obyśmy znaleźli łaskę w oczach swego pana, a będziemy niewolnikami faraona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 26, 'I Józef ustanowił to jako prawo aż do dziś w ziemi Egiptu, aby faraonowi oddawano piątą część plonów. Tylko ziemia samych kapłanów nie stała się własnością faraona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 27, 'Izrael mieszkał w ziemi Egiptu, w ziemi Goszen. Nabywali w niej posiadłości na własność, byli płodni i bardzo się rozmnożyli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 28, 'I Jakub żył w ziemi Egiptu siedemnaście lat. A w sumie Jakub przeżył sto czterdzieści siedem lat.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 29, 'I zbliżył się czas śmierci Izraela. Wezwał więc swego syna Józefa i powiedział do niego: Jeśli teraz znalazłem łaskę w twoich oczach, połóż, proszę, twoją rękę pod moje biodro, a wyświadcz mi tę łaskę i wierność: Proszę, nie chowaj mnie w Egipcie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 30, 'Ale gdy zasnę z moimi ojcami, wywieziesz mnie z Egiptu i pochowasz mnie w ich grobie. A on powiedział: Uczynię według twego słowa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 31, 'A Jakub powiedział: Przysięgnij mi. I przysiągł mu. Potem Izrael pokłonił się na wezgłowie łoża.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 1, 'Gdy to się stało, dano znać Józefowi: Oto twój ojciec zachorował. Wziął więc ze sobą swoich dwóch synów, Manassesa i Efraima.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 2, 'I powiedziano Jakubowi: Oto twój syn Józef idzie do ciebie. A Izrael zebrał siłę i usiadł na łożu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 3, 'Wtedy Jakub powiedział do Józefa: Bóg Wszechmogący ukazał mi się w Luz, w ziemi Kanaan, i błogosławił mi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 4, 'I powiedział do mnie: Oto ja uczynię cię płodnym i rozmnożę cię, i wywiodę z ciebie wielki lud. I dam tę ziemię twemu potomstwu po tobie w wieczne dziedzictwo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 5, 'Dlatego teraz twoi dwaj synowie, Efraim i Manasses, którzy urodzili ci się w ziemi Egiptu, zanim przyszedłem tu do ciebie do Egiptu, są moimi. Będą moi jak Ruben i Symeon.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 6, 'Ale twoje dzieci, które spłodzisz po nich, będą twoje; będą zwane w swych posiadłościach imieniem swoich braci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 7, 'A gdy wracałem z Paddan, umarła mi Rachela w ziemi Kanaan, w drodze, gdy byłem jeszcze w niewielkiej odległości od Efraty, i pogrzebałem ją tam przy drodze do Efraty, czyli Betlejem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 8, 'A gdy Izrael zobaczył synów Józefa, zapytał: Czyi oni są?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 9, 'Józef odpowiedział swemu ojcu: To są moi synowie, których Bóg dał mi tutaj. A on powiedział: Proszę, przyprowadź ich do mnie, abym im błogosławił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 10, 'A oczy Izraela były tak słabe ze starości, że nie mógł widzieć. I przyprowadził ich do niego, a Jakub ich pocałował i uścisnął.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 11, 'Potem Izrael powiedział do Józefa: Nie spodziewałem się, że będę jeszcze oglądał twoją twarz, a oto Bóg dał mi widzieć nawet twoje potomstwo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 12, 'Wtedy Józef odsunął ich od jego kolan i pokłonił się twarzą aż do ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 13, 'Potem Józef wziął obydwu i postawił Efraima po swojej prawej ręce, czyli po lewej stronie Izraela; a Manassesa po swojej lewej ręce, czyli po prawej stronie Izraela, i przyprowadził ich do niego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 14, 'Izrael wyciągnął swoją prawą rękę, położył ją na głowę Efraima, który był młodszy, a swoją lewą rękę na głowę Manassesa, umyślnie pokładając swoje ręce, choć pierworodny był Manasses.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 15, 'I błogosławił Józefowi, mówiąc: Bóg, przed którego obliczem chodzili moi ojcowie, Abraham i Izaak, Bóg, który mnie żywił od mej młodości aż do dziś;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 16, 'Anioł, który wybawił mnie ze wszelkiego zła, niech błogosławi tym chłopcom i niech będą nazywani od mego imienia i od imienia moich ojców, Abrahama i Izaaka, i niech się rozmnożą na ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 17, 'A gdy Józef zobaczył, że jego ojciec położył swoją prawą rękę na głowę Efraima, nie podobało mu się to. Wziął więc rękę swego ojca, aby ją przenieść z głowy Efraima na głowę Manassesa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 18, 'I Józef powiedział do swego ojca: Nie tak, mój ojcze. Ten bowiem jest pierworodny, połóż swoją prawą rękę na jego głowę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 19, 'Ale jego ojciec wzbraniał się i powiedział: Wiem, mój synu, wiem. Ten też stanie się ludem i on też urośnie, ale jego młodszy brat go przewyższy, a z jego potomstwa wyjdzie mnóstwo narodów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 20, 'Błogosławił im więc tego dnia, mówiąc: Przez ciebie Izrael będzie błogosławił, mówiąc: Niech Bóg cię uczyni jak Efraim i jak Manasses. Tak wyróżnił Efraima przed Manassesem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 21, 'Potem Izrael powiedział do Józefa: Oto ja umieram, ale Bóg będzie z wami i przywróci was do ziemi waszych ojców.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 22, 'Oto daję ci jedną część więcej niż twoim braciom, którą nabyłem moim mieczem i moim łukiem z ręki Amorytów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 1, 'Potem Jakub wezwał swoich synów i powiedział: Zbierzcie się, a oznajmię wam, co was spotka w waszych ostatnich dniach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 2, 'Zbierzcie się i słuchajcie, synowie Jakuba, a słuchajcie waszego ojca Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 3, 'Rubenie, mój pierworodny, ty jesteś moją mocą i początkiem mojej siły, pierwszy dostojeństwem i pierwszy męstwem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 4, 'Niestabilny jak woda, nie będziesz przodować, bo wstąpiłeś do łoża twego ojca; wstępując do mojego posłania, zbezcześciłeś je.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 5, 'Symeon i Lewi, bracia, ich miecze to narzędzia przemocy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 6, 'Niech moja dusza nie wchodzi w ich radę, niech moja sława nie jednoczy się z ich zgromadzeniem, bo w swej zapalczywości zabili człowieka, a w samowoli wywrócili mur.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 7, 'Przeklęta ich zapalczywość, bo uparta, i ich gniew, bo zatwardziały. Rozdzielę ich w Jakubie, a rozproszę ich w Izraelu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 8, 'Judo, to ciebie będą chwalić twoi bracia, twoja ręka będzie na karku twoich nieprzyjaciół, synowie twego ojca będą ci się kłaniać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 9, 'Judo, szczenię lwie, wróciłeś od łupu, mój synu. Skłonił się i położył się jak lew i jak lwica. Któż go obudzi?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 10, 'Nie będzie odjęte berło od Judy ani prawodawca spomiędzy jego nóg, aż przyjdzie Szylo i jemu będą posłuszne narody.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 11, 'Przywiąże do winorośli swoje oślę, a do wybornej winorośli – oślątko swojej oślicy. Wypierze w winie swoją szatę, a we krwi winogron – swoje odzienie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 12, 'Jego oczy czerwone od wina, a zęby białe od mleka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 13, 'Zebulon będzie mieszkać na morskim brzegu, przy porcie okrętów, a jego granice będą aż do Sydonu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 14, 'Issachar jak osioł kościsty leżący między dwoma brzemionami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 15, 'Zobaczył, że spoczynek jest dobry i ziemię, że jest urocza, nachylił swe ramię, by dźwigać, i stał się sługą składającym daninę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 16, 'Dan będzie sądzić swój lud jako jedno z pokoleń Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 17, 'Dan będzie wężem na drodze, żmiją na ścieżce kąsającą końskie pięty, tak że jeździec spadnie do tyłu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 18, 'Oczekuję twego zbawienia, Panie!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 19, 'Gad będzie zwyciężony przez wojsko, ale on na koniec zwycięży.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 20, 'Od Aszera będzie tłusty chleb, a on dostarczy przysmaków królewskich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 21, 'Neftali jak wypuszczona łania, mówiący piękne słowa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 22, 'Józef, latorośl płodna, latorośl płodna przy źródle, a jej szczepy rozchodzą się po murze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 23, 'Choć napoili go goryczą i strzelali do niego, i nienawidzili go strzelcy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 24, 'Jednak jego łuk został potężny i wzmocniły się ramiona jego rąk dzięki rękom mocnego Boga Jakuba, stamtąd pasterz i opoka Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 25, 'Od Boga twego ojca, który będzie cię wspomagał, i od Wszechmogącego, który ci pobłogosławi błogosławieństwami nieba z wysoka i błogosławieństwami głębin leżących na dole, i błogosławieństwami piersi i łona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 26, 'Błogosławieństwa twego ojca będą mocniejsze niż błogosławieństwa moich przodków aż do granic pagórków wiecznych. Będą nad głową Józefa i nad wierzchem głowy odłączonego od swych braci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 27, 'Beniamin jak drapieżny wilk, rano będzie jeść zdobycz, a wieczorem będzie dzielił łupy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 28, 'Oto wszystkich dwanaście pokoleń Izraela i to, co im powiedział ich ojciec, gdy im błogosławił. Każdemu według jego błogosławieństwa błogosławił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 29, 'Potem im nakazał: Ja będę przyłączony do mojego ludu. Pogrzebcie mnie z moimi ojcami w jaskini, która jest na polu Efrona Chetyty;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 30, 'W jaskini, która jest na polu Makpela naprzeciwko Mamre w ziemi Kanaan. Kupił ją wraz z polem Abraham od Efrona Chetyty jako grób na własność.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 31, 'Tam pogrzebano Abrahama i jego żonę Sarę, tam pogrzebano Izaaka i jego żonę Rebekę. Tam też pogrzebałem Leę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 32, 'Pole to i jaskinię na nim kupiono od synów Cheta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 33, 'A gdy Jakub przestał mówić do swoich synów, złożył swoje nogi na łoże i umarł, i został przyłączony do swego ludu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 1, 'Wtedy Józef przypadł do twarzy swego ojca i płakał nad nim, i całował go.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 2, 'Potem Józef rozkazał swoim sługom, lekarzom, aby zabalsamowali jego ojca. I lekarze zabalsamowali Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 3, 'I minęło czterdzieści dni, bo tyle trwa balsamowanie. Egipcjanie opłakiwali go przez siedemdziesiąt dni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 4, 'Po upływie dni żałoby Józef powiedział do domowników faraona: Jeśli znalazłem teraz łaskę w waszych oczach, powiedzcie, proszę, do uszu faraona:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 5, 'Mój ojciec zobowiązał mnie przysięgą i powiedział: Oto ja umieram. Pogrzebiesz mnie w moim grobie, który sobie wykopałem w ziemi Kanaan. Teraz, proszę, pozwól mi pojechać i pogrzebać mego ojca, a potem wrócę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 6, 'Faraon powiedział: Jedź i pogrzeb twego ojca, jak cię zobowiązał przysięgą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 7, 'Józef pojechał więc, aby pogrzebać swego ojca. Jechali też z nim wszyscy słudzy faraona, także starsi jego domu i wszyscy starsi ziemi Egiptu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 8, 'I cały dom Józefa, jego bracia i dom jego ojca. Tylko swoje dzieci, swoje owce i swoje woły zostawili w ziemi Goszen.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 9, 'Wyruszyły też z nimi wozy i wyruszyli jeźdźcy. A orszak był bardzo wielki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 10, 'I przyjechali aż do klepiska Atad, które jest za Jordanem, i tam opłakiwali go wielkim i bardzo głębokim lamentem. Józef przez siedem dni obchodził żałobę po swym ojcu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 11, 'A gdy obywatele ziemi Kanaan zobaczyli tę żałobę na klepisku Atad, mówili: To ciężka żałoba Egipcjan. Dlatego nazwano to miejsce Ebel-Misraim; leży ono za Jordanem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 12, 'Jego synowie uczynili więc z nim tak, jak im rozkazał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 13, 'Jego synowie zawieźli go do ziemi Kanaan i pogrzebali go w jaskini na polu Makpela naprzeciwko Mamre, którą kupił Abraham wraz z polem od Efrona Chetyty jako grób na własność.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 14, 'Po pogrzebie swego ojca Józef wrócił do Egiptu wraz ze swymi braćmi i ze wszystkimi, którzy pojechali z nim na pogrzeb jego ojca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 15, 'A bracia Józefa, widząc, że ich ojciec umarł, mówili: Może Józef będzie nas nienawidził i odpłaci nam sowicie za to wszystko zło, które mu uczyniliśmy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 16, 'Kazali więc powiedzieć do Józefa: Twój ojciec, zanim umarł, nakazał:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 17, 'Tak powiedzcie Józefowi: Proszę, wybacz teraz przestępstwo twoich braci i ich grzech, że wyrządzili ci zło. Proszę, wybacz teraz występek sługom Boga twego ojca. I Józef płakał, gdy to mówili do niego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 18, 'I jego bracia podeszli, i upadli przed nim, mówiąc: Oto jesteśmy twoimi sługami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 19, 'Józef powiedział do nich: Nie bójcie się. Czyż ja jestem na miejscu Boga?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 20, 'Obmyśliliście zło przeciwko mnie, ale Bóg obrócił to w dobro, żeby sprawić to, co się dziś dzieje, aby zachować tak wielki lud.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 21, 'Teraz więc nie bójcie się. Ja będę żywić was i wasze dzieci. I tak ich pocieszał, i serdecznie z nimi rozmawiał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 22, 'I Józef mieszkał w Egipcie, on sam i dom jego ojca. A Józef żył sto dziesięć lat.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 23, 'Józef oglądał synów Efraima aż do trzeciego pokolenia. Także synowie Makira, syna Manassesa, wychowali się na kolanach Józefa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 24, 'Potem Józef powiedział do swoich braci: Ja umrę, ale Bóg na pewno was nawiedzi i wyprowadzi z tej ziemi do ziemi, którą przysiągł Abrahamowi, Izaakowi i Jakubowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 25, 'Józef zobowiązał więc przysięgą synów Izraela i powiedział: Bóg na pewno was nawiedzi, a wtedy zabierzcie stąd moje kości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 26, 'I Józef umarł, mając sto dziesięć lat. Zabalsamowano go i złożono do trumny w Egipcie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 1, 'Oto imiona synów Izraela, którzy przybyli z Jakubem do Egiptu; każdy przybył ze swoją rodziną:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 2, 'Ruben, Symeon, Lewi i Juda;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 3, 'Issachar, Zebulon i Beniamin;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 4, 'Dan, Neftali, Gad i Aszer.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 5, 'A wszystkich dusz, które wyszły z bioder Jakuba, było siedemdziesiąt. Józef zaś już był w Egipcie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 6, 'Potem umarli Józef, wszyscy jego bracia i całe to pokolenie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 7, 'A synowie Izraela byli płodni, rozrodzili się, rozmnożyli i bardzo umacniali, a ziemia była ich pełna.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 8, 'Wówczas nastał nad Egiptem nowy król, który nie znał Józefa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 9, 'I powiedział do swego ludu: Oto lud synów Izraela stał się liczniejszy i potężniejszy od nas.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 10, 'Postąpmy więc z nimi mądrze, by się nie rozmnożyli, bo gdyby przyszła wojna, mogliby przyłączyć się do naszych wrogów i walczyć przeciwko nam, i opuścić ziemię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 11, 'Ustanowiono więc nad nimi nadzorców, aby ich gnębili ciężarami. I lud Izraela zbudował dla faraona miasta na składy: Pitom i Ramzes.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 12, 'Ale im bardziej ich gnębili, tym bardziej się rozmnażali i rośli, tak że zatrwożyli się z powodu synów Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 13, 'I Egipcjanie zmuszali synów Izraela do ciężkiej pracy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 14, 'I uprzykrzali im życie uciążliwą pracą przy glinie i przy cegłach, i przy każdej robocie na polu. Do wszelkiej pracy zmuszali ich bez litości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 15, 'I król Egiptu rozkazał hebrajskim położnym, z których jedna miała na imię Szifra, a druga Pua;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 16, 'Powiedział: Gdy będziecie przy porodach hebrajskich kobiet i zobaczycie, że urodził się syn, zabijcie go, a jeśli córka, niech zostanie przy życiu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 17, 'Lecz położne bały się Boga i nie robiły tak, jak im rozkazał król Egiptu, ale pozostawiały chłopców przy życiu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 18, 'Wtedy król Egiptu wezwał położne i powiedział do nich: Dlaczego tak postąpiłyście, że pozostawiłyście chłopców przy życiu?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 19, 'Położne odpowiedziały faraonowi: Hebrajskie kobiety nie są takie jak egipskie kobiety. Są bowiem żywotne, rodzą wcześniej, zanim przyjdzie do nich położna.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 20, 'I Bóg dobrze czynił tym położnym, a lud się mnożył i bardzo się wzmocnił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 21, 'A ponieważ położne bały się Boga, zbudował im domy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 22, 'Wtedy faraon rozkazał całemu swemu ludowi: Każdego syna, który się urodzi, wrzućcie do rzeki, a każdą córkę pozostawcie przy życiu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 1, 'Pewien mężczyzna z rodu Lewiego pojął za żonę córkę z rodu Lewiego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 2, 'Kobieta ta poczęła i urodziła syna, a gdy zobaczyła, że jest piękny, ukrywała go przez trzy miesiące.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 3, 'Ale gdy nie mogła go dłużej ukrywać, wzięła koszyk z sitowia, wysmarowała żywicą i smołą, włożyła do niego dziecko i umieściła między trzcinami na brzegu rzeki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 4, 'A jego siostra stała daleko, aby wiedzieć, co się z nim stanie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 5, 'Wtedy zeszła do rzeki córka faraona, aby się wykąpać, a jej służące przechadzały się po brzegu rzeki. Gdy zobaczyła koszyk w trzcinie, posłała swą służącą, aby go wzięła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 6, 'Kiedy go otworzyła, zobaczyła dziecko, a chłopiec płakał. Ulitowała się nad nim i powiedziała: To jedno z hebrajskich dzieci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 7, 'Wówczas jego siostra zapytała córkę faraona: Czy mam pójść i zawołać ci mamkę spośród hebrajskich kobiet, aby ci wykarmiła to dziecko?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 8, 'Córka faraona odpowiedziała jej: Idź. Dziewczynka poszła więc i zawołała matkę tego dziecka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 9, 'Do niej powiedziała córka faraona: Weź to dziecko i wykarm mi je, a ja dam ci należną zapłatę. Kobieta wzięła więc dziecko i wykarmiła je.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 10, 'A gdy dziecko podrosło, przyprowadziła je do córki faraona i stało się jej synem. I nadała mu imię Mojżesz, bo mówiła: Wyciągnęłam go z wody.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 11, 'Kiedy Mojżesz dorósł, wyszedł do swych braci i widział ich ciężary. Zobaczył też Egipcjanina, który bił Hebrajczyka, jednego z jego braci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 12, 'Rozejrzał się na wszystkie strony, a gdy zobaczył, że nikogo nie ma, zabił Egipcjanina i ukrył go w piasku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 13, 'A gdy wyszedł następnego dnia, oto kłócili się dwaj Hebrajczycy. Wtedy zapytał tego, który wyrządzał krzywdę: Dlaczego bijesz swego bliźniego?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 14, 'Ten mu odpowiedział: Któż cię ustanowił przełożonym i sędzią nad nami? Czy zamierzasz mnie zabić, jak zabiłeś Egipcjanina? Wtedy Mojżesz zląkł się i powiedział: Na pewno sprawa wyszła na jaw.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 15, 'Gdy faraon usłyszał o sprawie, usiłował zabić Mojżesza. Lecz Mojżesz uciekł przed faraonem i zamieszkał w ziemi Midian. I zatrzymał się tam przy pewnej studni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 16, 'A kapłan Midianitów miał siedem córek. Przyszły one, naczerpały wody i napełniły koryta, aby napoić stado swego ojca;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 17, 'Ale nadeszli pasterze i odganiali je. Wtedy Mojżesz wstał, obronił je i napoił ich bydło.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 18, 'Gdy wróciły do swego ojca Reuela, ten zapytał: Dlaczego dziś przyszłyście tak szybko?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 19, 'One odpowiedziały: Jakiś Egipcjanin wybawił nas z rąk pasterzy, naczerpał nam też wody i napoił stado.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 20, 'Wtedy zapytał swoje córki: A gdzie on jest? Dlaczego zostawiłyście tego człowieka? Zawołajcie go, aby zjadł chleb.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 21, 'Mojżesz zgodził się zamieszkać u tego człowieka, a ten dał Mojżeszowi swoją córkę Seforę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 22, 'Ta urodziła mu syna, któremu nadał imię Gerszom, bo mówił: Byłem przybyszem w obcej ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 23, 'Po dłuższym czasie umarł król Egiptu, a synowie Izraela wzdychali i wołali z powodu niewoli. Ich wołanie z powodu niewoli dotarło do Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 24, 'Bóg usłyszał ich jęk i wspomniał Bóg na swoje przymierze z Abrahamem, Izaakiem i Jakubem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 25, 'I spojrzał Bóg na synów Izraela, i miał Bóg na nich wzgląd.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 1, 'Mojżesz pasał stado swego teścia Jetra, kapłana Midianitów. Zaprowadził stado na drugą stronę pustyni i przyszedł do góry Bożej, do Horebu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 2, 'I Anioł Pana ukazał mu się w płomieniu ognia, ze środka krzewu. Spojrzał, a oto krzew płonął ogniem, lecz nie spłonął.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 3, 'Wtedy Mojżesz powiedział: Podejdę i zobaczę to wielkie zjawisko, dlaczego ten krzew się nie spala.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 4, 'A gdy Pan widział, że podchodził, aby to zobaczyć, zawołał do niego Bóg ze środka tego krzewu: Mojżeszu, Mojżeszu! A on odpowiedział: Oto jestem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 5, 'Wtedy powiedział: Nie zbliżaj się tu. Zdejmij buty z nóg, bo miejsce, na którym stoisz, jest ziemią świętą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 6, 'I dodał: Ja jestem Bogiem twego ojca, Bogiem Abrahama, Bogiem Izaaka i Bogiem Jakuba. I Mojżesz zakrył twarz, bo bał się patrzeć na Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 7, 'Pan powiedział: Przyjrzałem się utrapieniom mojego ludu, który jest w Egipcie, i słyszałem ich krzyk z powodu nadzorców, gdyż znam jego cierpienia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 8, 'Dlatego zstąpiłem, aby wybawić go z ręki Egipcjan i wyprowadzić z tej ziemi do ziemi dobrej i przestronnej, do ziemi opływającej mlekiem i miodem, na miejsce Kananejczyków, Chetytów, Amorytów, Peryzzytów, Chiwwitów i Jebusytów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 9, 'Teraz oto dotarł do mnie krzyk synów Izraela. Widziałem też ucisk, jakim dręczą ich Egipcjanie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 10, 'Dlatego teraz idź, poślę cię do faraona, abyś wyprowadził mój lud, synów Izraela, z Egiptu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 11, 'Mojżesz powiedział do Boga: Kimże ja jestem, abym miał iść do faraona i wyprowadzić synów Izraela z Egiptu?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 12, 'Bóg odpowiedział: Oto ja będę z tobą, a to będzie znakiem dla ciebie, że ja cię posłałem: gdy wyprowadzisz ten lud z Egiptu, będziecie służyć Bogu na tej górze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 13, 'Mojżesz powiedział do Boga: Kiedy pójdę do synów Izraela i powiem im: Bóg waszych ojców posłał mnie do was, a oni zapytają mnie, jakie jest jego imię, cóż im odpowiem?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 14, 'Wtedy Bóg odrzekł do Mojżesza: Jestem, Który Jestem. I dodał: Tak powiesz synom Izraela: Jestem posłał mnie do was.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 15, 'I mówił jeszcze Bóg do Mojżesza: Tak powiesz synom Izraela: Pan, Bóg waszych ojców, Bóg Abrahama, Bóg Izaaka i Bóg Jakuba, posłał mnie do was. To jest moje imię na wieki i takim ma pozostać w pamięci po wszystkie pokolenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 16, 'Idź, zgromadź starszych Izraela i mów do nich: Ukazał mi się Pan, Bóg waszych ojców, Bóg Abrahama, Izaaka i Jakuba, i powiedział: Nawiedziłem was i widziałem, co wam uczyniono w Egipcie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 17, 'I postanowiłem: Wyprowadzę was z utrapienia Egiptu do ziemi Kananejczyków, Chetytów, Amorytów, Peryzzytów, Chiwwitów i Jebusytów, do ziemi opływającej mlekiem i miodem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 18, 'Wtedy usłuchają twego głosu. I pójdziesz ty i starsi Izraela do króla Egiptu i powiecie do niego: Pan, Bóg Hebrajczyków, spotkał się z nami. Dlatego teraz pozwól nam pójść, proszę, w trzy dni drogi na pustynię, aby złożyć ofiarę Panu, naszemu Bogu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 19, 'Wiem, że król Egiptu nie pozwoli wam odejść, chyba że przez potężną rękę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 20, 'Wyciągnę więc rękę i uderzę Egipt wszystkimi moimi cudami, które będę czynił pośród niego. A potem was wypuści.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 21, 'Sprawię, że ten lud znajdzie przychylność w oczach Egipcjan. I stanie się tak, gdy będziecie wychodzić, że nie wyjdziecie z pustymi rękami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 22, 'Ale każda kobieta pożyczy od swojej sąsiadki i od tej, która u niej przebywa, srebrne i złote przedmioty oraz szaty. Włożycie je na waszych synów i na wasze córki i złupicie Egipt.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 1, 'Potem Mojżesz odpowiedział: Lecz oni mi nie uwierzą i nie usłuchają mego głosu, bo powiedzą: Pan ci się nie ukazał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 2, 'Pan zapytał go: Co masz w swojej ręce? Odpowiedział: Laskę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 3, 'I rozkazał: Rzuć ją na ziemię. Rzucił ją więc na ziemię i zamieniła się w węża; i Mojżesz przed nim uciekał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 4, 'Następnie Pan powiedział do Mojżesza: Wyciągnij rękę i chwyć go za ogon. Wyciągnął więc rękę i chwycił go, i ten zamienił się w laskę w jego ręce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 5, 'Uczyń tak, aby uwierzyli, że ukazał ci się Pan, Bóg ich ojców, Bóg Abrahama, Bóg Izaaka i Bóg Jakuba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 6, 'Pan powiedział mu jeszcze: Włóż teraz rękę w zanadrze. Włożył więc rękę w zanadrze, a gdy ją wyjął, była pokryta trądem jak śniegiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 7, 'I powiedział: Włóż ponownie rękę w zanadrze. I włożył znowu rękę w zanadrze, a gdy ją wyjął, stała się znowu jak reszta jego ciała.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 8, 'Jeśli więc ci nie uwierzą i nie usłuchają głosu pierwszego znaku, to uwierzą głosowi drugiego znaku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 9, 'A jeśli nie uwierzą obu tym znakom i nie usłuchają twego głosu, to weźmiesz wody z rzeki i wylejesz ją na ziemię. Wtedy ta woda, którą weźmiesz z rzeki, zamieni się na ziemi w krew.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 10, 'Mojżesz powiedział do Pana: Proszę, Panie, nie jestem wymowny – ani przedtem, ani odkąd przemówiłeś do twego sługi, bo mam powolną mowę i ociężały język.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 11, 'Pan mu odpowiedział: Któż uczynił usta człowieka? Albo kto czyni niemego lub głuchego, widzącego lub ślepego? Czyż nie ja, Pan?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 12, 'Teraz więc idź, a ja będę przy twoich ustach i pouczę cię, co masz mówić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 13, 'Mojżesz powiedział: Proszę, Panie, poślij tego, kogo masz posłać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 14, 'Wtedy zapalił się gniew Pana na Mojżesza i powiedział: Czyż Aaron, Lewita, nie jest twoim bratem? Wiem, że on potrafi dobrze mówić. Oto on wyjdzie ci na spotkanie, a gdy cię zobaczy, uraduje się w swoim sercu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 15, 'Ty będziesz mówił do niego i włożysz słowa w jego usta. A ja będę przy twoich ustach i przy jego ustach i pouczę was, co macie czynić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 16, 'On będzie mówił za ciebie do ludu. On będzie dla ciebie jakby ustami, a ty dla niego będziesz jakby Bogiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 17, 'I weź w rękę tę laskę, którą będziesz czynił znaki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 18, 'Odszedł więc Mojżesz i wrócił do swego teścia Jetra, i powiedział do niego: Pozwól mi wrócić do moich braci, którzy są w Egipcie, aby zobaczyć, czy jeszcze żyją. Jetro odpowiedział Mojżeszowi: Idź w pokoju.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 19, 'Pan rzekł do Mojżesza w ziemi Midian: Idź, wróć do Egiptu, bo pomarli wszyscy, którzy czyhali na twoje życie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 20, 'Mojżesz więc wziął swoją żonę i swoich synów, wsadził ich na osła i wyruszył do ziemi Egiptu. Wziął też Mojżesz laskę Boga do ręki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 21, 'Pan powiedział do Mojżesza: Gdy pójdziesz i wrócisz do Egiptu, dopilnuj, abyś wszystkich cudów, które dałem ci do ręki, dokonał przed faraonem. A ja zatwardzę jego serce, tak że nie wypuści ludu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 22, 'I powiesz do faraona: Tak mówi Pan: Izrael jest moim synem, moim pierworodnym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 23, 'Mówię ci: Wypuść mego syna, aby mi służył. Jeśli będziesz się wzbraniał wypuścić go, zabiję twojego syna, twego pierworodnego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 24, 'A w czasie drogi, w gospodzie, Pan zastąpił drogę Mojżeszowi i chciał go zabić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 25, 'Wtedy Sefora wzięła ostry kamień, odcięła napletek swego syna i rzuciła do jego stóp, i powiedziała: Naprawdę jesteś dla mnie oblubieńcem krwi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 26, 'I Pan odstąpił od niego. Wtedy nazwała go oblubieńcem krwi z powodu obrzezania.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 27, 'A do Aarona Pan powiedział: Wyjdź naprzeciw Mojżeszowi na pustynię. Wyszedł więc i spotkał go na górze Boga, i pocałował go.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 28, 'Wtedy Mojżesz powtórzył Aaronowi wszystkie słowa Pana, który go posłał, i wszystkie znaki, które nakazał mu uczynić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 29, 'Mojżesz i Aaron poszli więc i zebrali wszystkich starszych synów Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 30, 'I Aaron powiedział wszystkie słowa, które Pan mówił do Mojżesza, a Mojżesz czynił znaki na oczach ludu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 31, 'I lud uwierzył. I gdy usłyszeli, że Pan nawiedził synów Izraela i że wejrzał na ich utrapienie, pochylili się i oddali pokłon.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 1, 'Potem Mojżesz i Aaron przyszli do faraona i powiedzieli: Tak mówi Pan, Bóg Izraela: Wypuść mój lud, aby dla mnie obchodził święto na pustyni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 2, 'Faraon odparł: Któż to jest Pan, abym miał słuchać jego głosu i wypuścić Izraela? Nie znam Pana, a Izraela też nie wypuszczę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 3, 'I odpowiedzieli: Bóg Hebrajczyków ukazał się nam. Pozwól nam iść trzy dni drogą na pustynię i złożyć ofiarę Panu, naszemu Bogu, by nie nawiedził nas zarazą albo mieczem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 4, 'Król Egiptu zapytał ich: Dlaczego wy, Mojżeszu i Aaronie, odrywacie lud od pracy? Idźcie do waszych robót.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 5, 'I faraon dodał: Oto lud tej ziemi jest teraz liczny, a wy go odrywacie od robót.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 6, 'Rozkazał więc faraon tego dnia nadzorcom ludu i jego przełożonym:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 7, 'Już więcej nie będziecie dawać ludowi słomy do wyrobu cegły, jak dotychczas. Niech sami idą i zbierają sobie słomę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 8, 'Wyznaczcie im tę samą liczbę cegieł, jaką wyrabiali poprzednio, nic nie zmniejszajcie. Próżnują bowiem i dlatego wołają: Pozwól nam pójść i złożyć ofiarę naszemu Bogu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 9, 'Niech praca tych ludzi będzie cięższa, aby byli nią zajęci, a nie ufali kłamliwym słowom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 10, 'Wtedy wyszli nadzorcy ludu i jego przełożeni i powiedzieli do ludu: Tak mówi faraon: Nie będę wam dawał słomy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 11, 'Sami idźcie, zbierajcie sobie słomę, gdzie ją możecie znaleźć. Mimo to nic nie będzie odjęte z waszej pracy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 12, 'Lud rozproszył się więc po całej ziemi Egiptu, aby zbierać ścierń zamiast słomy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 13, 'A nadzorcy przynaglali, mówiąc: Wykonujcie wasze roboty, codzienną pracę jak wtedy, gdy wam dawano słomę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 14, 'I bito przełożonych spośród synów Izraela, których nadzorcy faraona postawili nad nimi, i pytano ich: Dlaczego ani wczoraj, ani dzisiaj nie wykonaliście tej ilości cegieł jak poprzednio?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 15, 'Przełożeni spośród synów Izraela przyszli więc do faraona i wołali: Czemu postępujesz tak ze swoimi sługami?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 16, 'Nie dają twoim sługom słomy, a mówią: Róbcie cegłę. I oto biją twe sługi, a to wina twojego ludu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 17, 'On odpowiedział: Próżnujecie, próżnujecie i dlatego mówicie: Pozwól nam pójść i złożyć ofiarę Panu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 18, 'Teraz więc idźcie i pracujcie. Słomy wam nie dadzą, ale macie dostarczać taką samą ilość cegieł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 19, 'A przełożeni spośród synów Izraela zobaczyli, że są w złym położeniu, ponieważ mówiono: Nie zmniejszacie nic z dziennego wyrobu cegieł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 20, 'Gdy wychodzili od faraona, spotkali Mojżesza i Aarona, którzy na nich czekali.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 21, 'I powiedzieli do nich: Niech Pan wejrzy na was i osądzi, bo sprawiliście, że staliśmy się wstrętni w oczach faraona i w oczach jego sług, i daliście im do ręki miecz, aby nas zabili.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 22, 'Wtedy Mojżesz wrócił do Pana i powiedział: Panie, dlaczego wyrządziłeś to zło twojemu ludowi? Dlaczego mnie tu posłałeś?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 23, 'Odkąd bowiem poszedłem do faraona, aby mówić w twoim imieniu, gorzej się obchodzi z tym ludem; a ty nie wybawiłeś swego ludu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 1, 'Wtedy Pan powiedział do Mojżesza: Teraz zobaczysz, co uczynię faraonowi. Mocną ręką bowiem wypuści ich i mocną ręką wypędzi ich ze swojej ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 2, 'Nadto Bóg mówił do Mojżesza: Ja jestem Panem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 3, 'Objawiłem się Abrahamowi, Izaakowi i Jakubowi pod tym imieniem: Bóg Wszechmogący, ale z mojego imienia Jehowa nie byłem przez nich poznany.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 4, 'Ustanowiłem też z nimi moje przymierze, aby dać im ziemię Kanaan, ziemię ich pielgrzymowania, w której przebywali jako obcy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 5, 'Usłyszałem także jęk synów Izraela, których Egipcjanie trzymają w niewoli, i wspomniałem na moje przymierze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 6, 'Dlatego powiedz synom Izraela: Ja jestem Pan, wyprowadzę was spod ciężarów Egipcjan, wyrwę was z ich niewoli i wybawię was wyciągniętym ramieniem i przez wielkie sądy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 7, 'Wezmę was sobie za lud i będę wam Bogiem. Poznacie, że ja jestem Pan, wasz Bóg, który was wyprowadza spod ciężarów Egipcjan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 8, 'I wprowadzę was do ziemi, którą przysiągłem dać Abrahamowi, Izaakowi i Jakubowi; i dam ją wam w dziedzictwo. Ja jestem Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 9, 'I Mojżesz mówił tak do synów Izraela, ale nie usłuchali go z powodu udręki ducha i ciężkiej niewoli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 10, 'Wtedy Pan powiedział do Mojżesza:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 11, 'Idź, powiedz faraonowi, królowi Egiptu, żeby wypuścił synów Izraela ze swej ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 12, 'Mojżesz zaś odpowiedział przed Panem: Oto synowie Izraela nie posłuchali mnie, jakże więc posłucha mnie faraon? Jestem przecież nieobrzezanych warg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 13, 'Wtedy Pan przemówił do Mojżesza i Aarona i dał im rozkaz dla synów Izraela i dla faraona, króla Egiptu, aby wyprowadzili synów Izraela z ziemi Egiptu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 14, 'Oto naczelnicy domów ich ojców: synowie Rubena, pierworodnego Izraela: Henoch, Pallu, Chesron i Karmi. To są rodziny Rubena.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 15, 'Synowie Symeona: Jemuel, Jamin, Ohad, Jakin, Sochar i Szaul, syn Kananejki. To są rodziny Symeona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 16, 'Oto imiona synów Lewiego według ich pokoleń: Gerszon, Kehat i Merari. A lat życia Lewiego było sto trzydzieści siedem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 17, 'Synowie Gerszona: Libni i Szimei, według ich rodzin.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 18, 'Synowie Kehata: Amram, Ishar, Chebron i Uzziel. A lat życia Kehata było sto trzydzieści trzy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 19, 'Synowie Merariego: Machli i Muszi. To są rodziny Lewiego według ich pokoleń.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 20, 'I Amram pojął za żonę Jokebed, swoją ciotkę, która urodziła mu Aarona i Mojżesza. A lat życia Amrama było sto trzydzieści siedem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 21, 'Synowie Ishara: Korach, Nefeg i Zikri.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 22, 'Synowie Uzziela: Miszael, Elsafan i Sitri.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 23, 'I Aaron pojął za żonę Eliszebę, córkę Aminadaba, siostrę Nachszona. Ona mu urodziła Nadaba, Abihu, Eleazara i Itamara.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 24, 'A synowie Koracha: Assir, Elkana i Abiasaf. To są rodziny Korachitów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 25, 'I Eleazar, syn Aarona, pojął za żonę jedną z córek Putiela. Ona mu urodziła Pinchasa. Oto są naczelnicy ojców Lewitów według ich rodzin.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 26, 'To są ci właśnie Aaron i Mojżesz, do których mówił Pan: Wyprowadźcie synów Izraela z ziemi Egiptu według ich zastępów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 27, 'To oni mówili do faraona, króla Egiptu, aby wyprowadzić synów Izraela z Egiptu. To jest właśnie Mojżesz i Aaron.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 28, 'A w tym dniu, kiedy Pan mówił do Mojżesza w ziemi Egiptu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 29, 'Pan powiedział do niego: Ja jestem Pan. Mów do faraona, króla Egiptu, wszystko, co do ciebie mówię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 30, 'Mojżesz zaś odpowiedział przed Panem: Oto jestem nieobrzezanych warg, jakże posłucha mnie faraon?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 1, 'I Pan powiedział do Mojżesza: Oto ustanowiłem cię bogiem dla faraona, a twój brat Aaron będzie twoim prorokiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 2, 'Ty powiesz wszystko, co ci rozkażę. A twój brat Aaron będzie mówił do faraona, aby wypuścił synów Izraela ze swojej ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 3, 'A ja zatwardzę serce faraona i pomnożę moje znaki i cuda w ziemi Egiptu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 4, 'Faraon was nie posłucha, lecz ja położę moją rękę na Egipcie i wyprowadzę moje zastępy, mój lud, synów Izraela, z ziemi Egiptu przez wielkie sądy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 5, 'A Egipcjanie poznają, że ja jestem Pan, gdy wyciągnę rękę na Egipt i wyprowadzę synów Izraela spośród nich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 6, 'Mojżesz i Aaron uczynili więc, jak im Pan przykazał; tak właśnie uczynili.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 7, 'Mojżesz miał osiemdziesiąt lat, a Aaron osiemdziesiąt trzy lata, gdy mówili do faraona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 8, 'Wtedy Pan powiedział do Mojżesza i Aarona:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 9, 'Gdy faraon powie wam: Uczyńcie jakiś cud, wtedy powiesz do Aarona: Weź swą laskę i rzuć ją przed faraonem, a zamieni się w węża.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 10, 'Mojżesz i Aaron przyszli do faraona i uczynili tak, jak Pan rozkazał. Aaron rzucił swoją laskę przed faraonem i jego sługami, a ona zamieniła się w węża.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 11, 'Wtedy faraon wezwał mędrców i czarowników. I ci egipscy czarownicy uczynili to samo swoimi czarami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 12, 'Każdy z nich rzucił swoją laskę, a zamieniły się w węże. Lecz laska Aarona pożarła ich laski.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 13, 'Serce faraona stało się jednak zatwardziałe i nie posłuchał ich, jak Pan zapowiedział.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 14, 'Potem Pan powiedział do Mojżesza: Serce faraona jest zatwardziałe, wzbrania się wypuścić lud.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 15, 'Idź do faraona rankiem, kiedy wyjdzie nad wodę. Staniesz naprzeciwko niego nad brzegiem rzeki i weźmiesz do ręki laskę, która się zamieniła w węża;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 16, 'I powiesz mu: Pan, Bóg Hebrajczyków, posłał mnie do ciebie, mówiąc: Wypuść mój lud, aby mi służył na pustyni, a oto dotąd nie posłuchałeś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 17, 'Dlatego tak mówi Pan: Po tym poznasz, że ja jestem Pan. Oto uderzę laską, która jest w mojej ręce, w wody, które są w rzece, a one zamienią się w krew.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 18, 'Ryby, które są w rzece, pozdychają i rzeka będzie cuchnąć. Egipcjanie się zmęczą poszukiwaniem wody z rzeki do picia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 19, 'Pan mówił dalej do Mojżesza: Powiedz Aaronowi: Weź swoją laskę i wyciągnij rękę nad wody Egiptu, nad ich rzeki, nad ich strugi, nad ich jeziora i nad wszelkie zbiorowiska wód, a one zamienią się w krew. Krew będzie na całej ziemi Egiptu, tak w naczyniach drewnianych, jak i w kamiennych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 20, 'Mojżesz i Aaron uczynili tak, jak Pan rozkazał. Aaron podniósł laskę i uderzył wody rzeki na oczach faraona i jego sług. I wszystkie wody rzeki zamieniły się w krew.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 21, 'Ryby, które były w rzece, pozdychały i rzeka zaczęła cuchnąć, tak że Egipcjanie nie mogli pić z niej wody. A krew była w całej ziemi Egiptu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 22, 'Lecz egipscy czarownicy uczynili to samo swoimi czarami. Pozostało więc zatwardziałe serce faraona i nie posłuchał ich, jak Pan zapowiedział.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 23, 'Faraon odwrócił się i poszedł do swego domu, i tego również nie wziął sobie do serca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 24, 'I wszyscy Egipcjanie kopali wokół rzeki w poszukiwaniu wody do picia, bo nie mogli pić wody z rzeki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 25, 'I upłynęło siedem dni od chwili, gdy Pan uderzył rzekę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 1, 'Potem Pan powiedział do Mojżesza: Idź do faraona i powiedz mu: Tak mówi Pan: Wypuść mój lud, aby mi służył.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 2, 'A jeśli będziesz się wzbraniał wypuścić go, oto dotknę żabami wszystkich twoich granic.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 3, 'Rzeka zaroi się od żab, które wypełzną i wedrą się do twego domu, do twej sypialni, na twoje łoże, do domu twoich sług, między twój lud, do twoich pieców i w twoje dzieże.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 4, 'Żaby wpełzną zarówno na ciebie, jak i na twój lud i na wszystkie twoje sługi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 5, 'Pan dalej mówił do Mojżesza: Powiedz Aaronowi: Wyciągnij rękę ze swą laską nad rzeki, nad strugi i nad jeziora i sprowadź żaby na ziemię Egiptu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 6, 'Aaron wyciągnął więc rękę nad wody Egiptu, a żaby wypełzły i pokryły ziemię Egiptu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 7, 'Lecz czarownicy uczynili to samo swoimi czarami i sprowadzili żaby na ziemię Egiptu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 8, 'Potem faraon wezwał Mojżesza i Aarona i powiedział: Módlcie się do Pana, aby oddalił żaby ode mnie i od mojego ludu, a wypuszczę lud, aby złożył ofiarę Panu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 9, 'Mojżesz odpowiedział faraonowi: Dam ci ten zaszczyt. Powiedz, kiedy mam się modlić za ciebie, za twoje sługi i za twój lud, aby wyginęły żaby u ciebie i w twoich domach, a zostały tylko te w rzece.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 10, 'A on powiedział: Jutro. Wtedy Mojżesz odpowiedział: Stanie się według twego słowa, abyś wiedział, że nie ma nikogo jak Pan, nasz Bóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 11, 'Żaby odejdą od ciebie, z twoich domów, od twoich sług i twego ludu, zostaną tylko w rzece.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 12, 'Wtedy Mojżesz i Aaron wyszli od faraona. I Mojżesz zawołał do Pana z powodu żab, które zesłał na faraona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 13, 'I Pan uczynił według słowa Mojżesza, że żaby wyginęły z domów, ze wsi i z pól.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 14, 'Zbierano je na stosy i ziemia zaczęła cuchnąć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 15, 'Gdy faraon zauważył, że nadeszło wytchnienie, zatwardził swoje serce i nie posłuchał ich, jak Pan zapowiedział.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 16, 'I Pan powiedział do Mojżesza: Powiedz Aaronowi: Wyciągnij swoją laskę i uderz pył ziemi, aby zamienił się we wszy na całej ziemi Egiptu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 17, 'I tak uczynili. Aaron wyciągnął rękę ze swoją laską i uderzył pył ziemi, który zamienił się we wszy na ludziach i na bydle. Wszelki pył ziemi zamienił się we wszy na całej ziemi Egiptu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 18, 'Czarownicy czynili to samo swoimi czarami, aby sprowadzić wszy, ale nie mogli. I wszy były na ludziach i na bydle.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 19, 'Wtedy czarownicy powiedzieli do faraona: To jest palec Boży. Ale serce faraona pozostało zatwardziałe i nie posłuchał ich, jak Pan zapowiedział.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 20, 'I Pan powiedział do Mojżesza: Wstań rano i stań przed faraonem, kiedy wyjdzie nad wodę, i powiedz mu: Tak mówi Pan: Wypuść mój lud, aby mi służył;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 21, 'Bo jeśli nie wypuścisz mego ludu, ześlę rozmaite muchy na ciebie, na twe sługi, na twój lud i na twoje domy. I domy Egipcjan, a także ziemia, na której są, będą pełne rozmaitych much.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 22, 'W owym dniu oddzielę ziemię Goszen, w której mieszka mój lud, aby tam nie było rozmaitych much. I poznasz, że ja jestem Pan pośrodku ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 23, 'Oddzielę znakiem odkupienia mój lud od twojego ludu. Jutro ten znak nastąpi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 24, 'I Pan tak uczynił. Rozmaite uciążliwe muchy naszły dom faraona, domy jego sług i całą ziemię Egiptu. I ziemia została zniszczona przez rozmaite muchy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 25, 'Faraon wezwał wówczas Mojżesza i Aarona i powiedział: Idźcie, złóżcie na tej ziemi ofiarę waszemu Bogu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 26, 'Mojżesz odpowiedział: Nie godzi się tak czynić; bo to, co złożylibyśmy w ofierze Panu, naszemu Bogu, byłoby zgorszeniem dla Egipcjan. A gdybyśmy na oczach Egipcjan złożyli w ofierze to, co jest zgorszeniem, czyż nie ukamienowaliby nas?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 27, 'Pójdziemy w trzy dni drogi na pustynię i złożymy ofiarę Panu, naszemu Bogu, jak nam rozkaże.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 28, 'Faraon odpowiedział: Wypuszczę was, abyście mogli złożyć ofiarę Panu, waszemu Bogu, na pustyni, tylko nie oddalajcie się zbytnio. Wstawcie się też za mną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 29, 'Mojżesz powiedział: Wychodzę od ciebie i wstawię się za tobą u Pana, aby rozmaite muchy odeszły jutro od faraona, od jego sług i od jego ludu. Tylko niech faraon już więcej nie oszukuje, nie chcąc wypuścić ludu, by złożył ofiarę Panu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 30, 'Mojżesz wyszedł więc od faraona i wstawił się u Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 31, 'I Pan uczynił według słowa Mojżesza, i oddalił rozmaite muchy od faraona, od jego sług i od jego ludu. Nie została ani jedna.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 32, 'Jednak faraon i tym razem zatwardził swe serce i nie wypuścił ludu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 1, 'Potem Pan powiedział do Mojżesza: Idź do faraona i powiedz mu: Tak mówi Pan, Bóg Hebrajczyków: Wypuść mój lud, aby mi służył;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 2, 'Bo jeśli będziesz się wzbraniał go wypuścić i nadal będziesz go zatrzymywał;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 3, 'Oto ręka Pana będzie na twoje stada, które są na polu, na koniach, na osłach, na wielbłądach, na wołach i na owcach. Będzie bardzo ciężka zaraza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 4, 'Pan rozdzieli stada Izraela i stada Egiptu, aby nie zdechło nic ze wszystkiego, co należy do synów Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 5, 'I Pan wyznaczył czas, mówiąc: Jutro Pan to uczyni na tej ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 6, 'Nazajutrz Pan tak uczynił. Pozdychały wszystkie stada Egiptu, lecz ze stad synów Izraela nie zdechło ani jedno.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 7, 'Faraon posłał więc na zwiady, a oto z bydła Izraela nie zdechło ani jedno. Ale serce faraona pozostało zatwardziałe i nie wypuścił ludu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 8, 'Potem Pan powiedział do Mojżesza i Aarona: Weźcie pełne garści popiołu z pieca i niech Mojżesz rozrzuci go ku niebu na oczach faraona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 9, 'Zamieni się w pył na całej ziemi Egiptu, który spowoduje wrzody pęczniejące ropą na ludziach i na zwierzętach na całej ziemi Egiptu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 10, 'Wzięli więc popiół z pieca i stanęli przed faraonem, a Mojżesz rozrzucił popiół ku niebu i powstały wrzody pęczniejące ropą na ludziach i na zwierzętach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 11, 'Czarownicy zaś nie mogli stanąć przed Mojżeszem z powodu wrzodów, bo wrzody były na nich i na wszystkich Egipcjanach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 12, 'I Pan zatwardził serce faraona, i ten nie posłuchał ich, jak Pan zapowiedział Mojżeszowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 13, 'Pan powiedział do Mojżesza: Wstań rano, stań przed faraonem i powiedz mu: Tak mówi Pan, Bóg Hebrajczyków: Wypuść mój lud, aby mi służył;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 14, 'Tym razem bowiem ześlę wszystkie moje plagi na twoje serce, na twoje sługi i na twój lud, abyś wiedział, że nie ma równego mi na całej ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 15, 'Bo teraz wyciągnę rękę i uderzę ciebie i twój lud zarazą, i będziesz wytracony z ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 16, 'Lecz dlatego cię postawiłem, aby okazać na tobie moją moc i żeby rozgłaszano moje imię na całej ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 17, 'A ty jeszcze się wynosisz i stajesz przeciw memu ludowi, nie chcąc go wypuścić?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 18, 'Jutro o tej porze spuszczę bardzo ciężki grad, jakiego nie było w Egipcie od dnia jego założenia aż do tego czasu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 19, 'Poślij więc teraz i zgromadź swoje bydło i wszystko, co masz na polu; bo każdy człowiek i każde zwierzę, które znajdzie się na polu, a nie zostanie zegnane do domu, zginie, gdy na nich spadnie grad.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 20, 'Kto więc ze sług faraona uląkł się słowa Pana, kazał uciekać swym sługom wraz z bydłem do domu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 21, 'Ale kto nie wziął do serca słowa Pana, ten zostawił swe sługi i bydło na polu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 22, 'Pan powiedział do Mojżesza: Wyciągnij rękę ku niebu, by spadł grad na całej ziemi Egiptu, na ludzi, na bydło i na wszelkie rośliny polne w ziemi Egiptu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 23, 'I Mojżesz wyciągnął swą laskę ku niebu, a Pan zesłał grzmoty i grad i na ziemię zstąpił ogień. Pan spuścił grad na ziemię Egiptu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 24, 'I był grad i ogień zmieszany z bardzo ciężkim gradem, jakiego nie było w całej ziemi Egiptu, odkąd stał się narodem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 25, 'Grad poraził na całej ziemi Egiptu cokolwiek było na polu, od człowieka aż do zwierzęcia. Poraził też wszelkie rośliny polne i połamał wszystkie drzewa na polu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 26, 'Tylko w ziemi Goszen, gdzie mieszkali synowie Izraela, nie było gradu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 27, 'Faraon kazał więc wezwać Mojżesza i Aarona i powiedział do nich: Tym razem zgrzeszyłem. Pan jest sprawiedliwy, a ja i mój lud jesteśmy niegodziwi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 28, 'Wstawcie się u Pana, aby ustały Boże grzmoty i grad, bo już dość. Wypuszczę was i nie będziecie tu dłużej mieszkać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 29, 'Mojżesz powiedział do niego: Gdy wyjdę z miasta, wyciągnę ręce do Pana, a grzmoty ustaną i nie będzie więcej gradu, abyś wiedział, że ziemia należy do Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 30, 'Ale wiem, że ty i twoi słudzy jeszcze nie boicie się Pana Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 31, 'Len i jęczmień zostały zbite, bo jęczmień miał już kłosy, a len zakwitł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 32, 'Pszenica jednak i żyto nie zostały zbite, bo były późniejsze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 33, 'Mojżesz wyszedł więc od faraona za miasto i wyciągnął ręce do Pana. Ustały wtedy grzmoty i grad, a deszcz nie padał na ziemię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 34, 'Kiedy faraon zobaczył, że deszcz, grad i grzmoty ustały, jeszcze bardziej zgrzeszył i zatwardził serce, on i jego słudzy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 35, 'I serce faraona pozostało zatwardziałe i nie wypuścił synów Izraela, jak Pan zapowiedział przez Mojżesza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 1, 'Potem Pan powiedział do Mojżesza: Idź do faraona, bo zatwardziłem jego serce i serca jego sług, abym czynił te moje znaki wśród nich;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 2, 'I abyś opowiadał do uszu swoich synów i wnuków, co uczyniłem w Egipcie i o moich znakach, których wśród nich dokonałem, abyście wiedzieli, że ja jestem Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 3, 'Mojżesz i Aaron poszli więc do faraona i mówili mu: Tak mówi Pan, Bóg Hebrajczyków: Jak długo będziesz się wzbraniał uniżyć przede mną? Wypuść mój lud, aby mi służył.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 4, 'Bo jeśli będziesz się wzbraniał wypuścić mój lud, oto sprowadzę jutro szarańczę w twoje granice.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 5, 'Ona przykryje powierzchnię ziemi tak, że nie będzie jej widać, i pożre resztki, jakie wam zostały po gradzie, i strawi każde drzewo rosnące na polu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 6, 'Napełni twoje domy, domy wszystkich twoich sług i domy wszystkich Egipcjan, czego nie widzieli twoi ojcowie ani ojcowie twoich ojców od początku swego pobytu na ziemi aż do tego dnia. Potem odwrócił się i wyszedł od faraona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 7, 'Wtedy słudzy faraona powiedzieli do niego: Jak długo ten człowiek będzie dla nas sidłem? Wypuść tych ludzi, aby służyli Panu, swemu Bogu. Czy jeszcze nie wiesz, że Egipt został zniszczony?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 8, 'Wezwano więc ponownie Mojżesza z Aaronem do faraona, a on powiedział do nich: Idźcie, służcie Panu, waszemu Bogu. Którzy to mają iść?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 9, 'Mojżesz odpowiedział: Pójdziemy z naszymi dziećmi i starcami, z naszymi synami i córkami, z naszymi trzodami i bydłem, bo musimy obchodzić święto dla Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 10, 'Powiedział im: Niech Pan tak będzie z wami, jak ja wypuszczę was i wasze dzieci. Patrzcie, bo coś złego macie przed sobą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 11, 'Nie tak! Idźcie sami mężczyźni i służcie Panu, tego właśnie chcieliście. I wypędzono ich sprzed oblicza faraona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 12, 'Potem Pan powiedział do Mojżesza: Wyciągnij rękę nad ziemię Egiptu po szarańczę, aby spadła na ziemię Egiptu i pożarła wszelkie rośliny ziemi, wszystko to, co pozostało po gradzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 13, 'I Mojżesz wyciągnął swoją laskę nad ziemię Egiptu, a Pan sprowadził na ziemię wschodni wiatr na cały ten dzień i całą noc. Gdy nadszedł ranek, wschodni wiatr przyniósł szarańczę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 14, 'Szarańcza pojawiła się na całej ziemi Egiptu i obsiadła wszystkie granice Egiptu. Była ona tak uciążliwa, że podobnej szarańczy nigdy przedtem nie było i po niej takiej nie będzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 15, 'Pokryła powierzchnię całej ziemi, tak że ziemia pociemniała. Pożarła całą roślinność ziemi i wszelkie owoce drzew, które zostały po gradzie. Nie pozostało nic zielonego na drzewach ani z roślinności polnej w całej ziemi Egiptu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 16, 'Dlatego faraon czym prędzej wezwał Mojżesza i Aarona i powiedział: Zgrzeszyłem przeciwko Panu, waszemu Bogu, i przeciwko wam.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 17, 'Teraz więc wybaczcie, proszę, mój grzech jeszcze ten raz i wstawcie się u Pana, waszego Boga, aby tylko oddalił ode mnie tę śmierć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 18, 'I Mojżesz wyszedł od faraona i wstawił się u Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 19, 'A Pan odwrócił bardzo silny wiatr zachodni, który porwał szarańczę i wrzucił ją do Morza Czerwonego. Nie została ani jedna szarańcza we wszystkich granicach Egiptu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 20, 'Pan jednak zatwardził serce faraona i ten nie wypuścił synów Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 21, 'Wtedy Pan powiedział do Mojżesza: Wyciągnij rękę ku niebu, a nastanie na ziemi Egiptu taka ciemność, że będzie można jej dotknąć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 22, 'I Mojżesz wyciągnął rękę ku niebu, i nastała gęsta ciemność w całej ziemi Egiptu, która trwała trzy dni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 23, 'Jeden nie widział drugiego i nikt przez te trzy dni nie podniósł się ze swego miejsca. Lecz w domach wszystkich synów Izraela było światło.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 24, 'A faraon wezwał Mojżesza i powiedział: Idźcie, służcie Panu. Tylko niech wasze trzody i bydła zostaną i niech idą z wami wasze dzieci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 25, 'I Mojżesz odpowiedział: Dasz nam także ofiary i całopalenia, które złożymy w ofierze Panu, naszemu Bogu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 26, 'Pójdzie więc też z nami nasz dobytek, nie zostanie nawet kopyto. Z niego bowiem weźmiemy, aby służyć Panu, naszemu Bogu, gdyż nie wiemy, czym mamy służyć Panu, dopóki tam nie przyjdziemy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 27, 'Lecz Pan zatwardził serce faraona i ten nie chciał ich wypuścić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 28, 'Faraon powiedział do Mojżesza: Idź ode mnie i strzeż się, abyś więcej nie widział mego oblicza. Tego dnia bowiem, w którym zobaczysz moje oblicze, umrzesz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 29, 'Mojżesz odpowiedział: Dobrze powiedziałeś. Nie zobaczę więcej twego oblicza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 1, 'I Pan powiedział do Mojżesza: Sprowadzę jeszcze jedną plagę na faraona i na Egipt, potem wypuści was stąd. A gdy was wypuści, całkowicie was stąd wypędzi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 2, 'Powiedz teraz do uszu ludu, aby każdy mężczyzna pożyczył od swego sąsiada i każda kobieta od swej sąsiadki srebrne i złote przedmioty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 3, 'A Pan dał ludowi łaskę w oczach Egipcjan. Mojżesz także był bardzo wielkim mężem w ziemi Egiptu w oczach sług faraona i w oczach ludu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 4, 'Wtedy Mojżesz powiedział: Tak mówi Pan: O północy przejdę przez Egipt.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 5, 'I umrze wszystko, co pierworodne w ziemi Egiptu, od pierworodnego syna faraona, który miał zasiadać na jego tronie, aż do pierworodnego niewolnicy, która jest przy żarnach, i wszelkie pierworodne bydła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 6, 'I będzie wielki krzyk w całej ziemi Egiptu, jakiego nigdy przedtem nie było i jakiego potem nie będzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 7, 'Ale na nikogo z synów Izraela pies nie ruszy swym językiem, ani na człowieka, ani na bydlę, abyście wiedzieli, że Pan uczynił różnicę między Egipcjanami a Izraelem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 8, 'I przyjdą do mnie wszyscy twoi słudzy, i będą mi się kłaniać, mówiąc: Wyjdź ty i cały lud, który jest pod twoim przywództwem. Potem wyjdę. I wyszedł od faraona z wielkim gniewem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 9, 'Pan powiedział do Mojżesza: Faraon nie posłucha was, aby mnożyły się moje cuda w ziemi Egiptu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 10, 'Mojżesz i Aaron czynili więc te wszystkie cuda przed faraonem. Lecz Pan zatwardził serce faraona i ten nie wypuścił synów Izraela ze swojej ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 1, 'Pan powiedział jeszcze do Mojżesza i Aarona w ziemi Egiptu:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 2, 'Ten miesiąc będzie dla was początkiem miesięcy, będzie dla was pierwszym miesiącem roku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 3, 'Powiedzcie całemu zgromadzeniu Izraela: Dziesiątego dnia tego miesiąca każdy weźmie sobie baranka dla rodziny, jednego baranka dla domu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 4, 'A jeśli rodzina jest zbyt mała, aby zjeść baranka, niech dobierze go razem z sąsiadem, który jest najbliższy jej domu, według liczby dusz, naliczywszy tyle osób, ile mogłoby zjeść baranka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 5, 'Wasz baranek ma być bez skazy, jednoroczny samiec. Weźmiecie go spośród owiec albo kóz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 6, 'Będziecie go strzegli aż do czternastego dnia tego miesiąca, a wtedy całe zgromadzenie Izraela zabije go pod wieczór.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 7, 'Potem wezmą z jego krwi i pokropią oba węgary i nadproże domu, w którym będą go spożywać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 8, 'I będą jeść tej nocy mięso pieczone przy ogniu i przaśny chleb; będą je jeść z gorzkimi ziołami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 9, 'Nie jedzcie z niego nic surowego ani ugotowanego w wodzie, lecz tylko upieczone przy ogniu, z jego głową, nogami i wnętrznościami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 10, 'Nie zostawicie z niego niczego do rana; a jeśliby coś z niego zostało do rana, spalicie to w ogniu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 11, 'Tak oto będziecie go spożywać: Wasze biodra będą przepasane, obuwie na waszych nogach i laska w waszym ręku. Będziecie go jeść pośpiesznie. To Pascha Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 12, 'Gdyż tej nocy przejdę przez ziemię Egiptu i zabiję wszystko, co pierworodne w ziemi Egiptu, od człowieka aż do zwierzęcia, a nad wszystkimi bogami Egiptu dokonam sądu, ja, Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 13, 'A ta krew będzie dla was znakiem na domach, w których będziecie. Gdy bowiem ujrzę krew, ominę was i nie dotknie was plaga zniszczenia, gdy będę zabijał w ziemi Egiptu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 14, 'Ten dzień będzie dla was pamiątką i będziecie go obchodzić jako święto dla Pana po wszystkie pokolenia. Będziecie go obchodzić jako ustawę wieczną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 15, 'Przez siedem dni będziecie jeść przaśny chleb. Już w pierwszym dniu usuniecie zakwas z waszych domów, bo ktokolwiek będzie jadł coś kwaszonego, od pierwszego dnia aż do siódmego, ta dusza zostanie wykluczona z Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 16, 'W tym pierwszym dniu będzie święte zgromadzenie, także siódmego dnia będziecie mieć święte zgromadzenie. W tych dniach nie będziecie wykonywać żadnej pracy. Będzie wam tylko wolno przygotować to, czego każdy potrzebuje do jedzenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 17, 'I będziecie obchodzić Święto Przaśników, bo w tym właśnie dniu wyprowadziłem wasze zastępy z ziemi Egiptu. Dlatego będziecie obchodzić ten dzień po wszystkie pokolenia jako ustawę wieczną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 18, 'W pierwszym miesiącu, od wieczora czternastego dnia tego miesiąca do wieczora dnia dwudziestego pierwszego tego miesiąca, będziecie jeść przaśny chleb.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 19, 'Przez siedem dni nie znajdzie się żaden zakwas w waszych domach. Ktokolwiek bowiem będzie jadł coś kwaszonego, ta dusza zostanie wykluczona ze zgromadzenia Izraela, zarówno przybysz, jak i urodzony w tej ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 20, 'Nie będziecie jeść nic kwaszonego; we wszystkich waszych domach będziecie jeść przaśne chleby.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 21, 'Wtedy Mojżesz wezwał wszystkich starszych Izraela i powiedział im: Wybierzcie i weźcie sobie baranka dla swych rodzin i zabijcie go jako paschę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 22, 'Weźmiecie też wiązkę hizopu i zanurzycie we krwi, która jest w misie, i pokropicie nadproże i oba węgary tą krwią, która jest w misie. Niech nikt z was nie wychodzi za drzwi swego domu aż do rana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 23, 'Pan bowiem przejdzie, aby zabijać Egipcjan, a gdy ujrzy krew na nadprożu i na obu węgarach, Pan ominie drzwi i nie pozwoli niszczycielowi wejść do waszych domów, aby was zabić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 24, 'Będziecie przestrzegać tego jako ustawy dla ciebie i twoich synów aż na wieki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 25, 'Kiedy wejdziecie do ziemi, którą da wam Pan, jak to obiecał, będziecie przestrzegać tego obrzędu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 26, 'A gdy wasi synowie zapytają was: Co oznacza ten wasz obrzęd?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 27, 'Wtedy odpowiecie: To ofiara paschy Pana, który ominął domy synów Izraela w Egipcie, gdy zabijał Egipcjan, a nasze domy ocalił. Potem lud schylił się i oddał pokłon.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 28, 'I synowie Izraela odeszli, i uczynili, jak Pan rozkazał Mojżeszowi i Aaronowi, tak właśnie zrobili.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 29, 'A o północy Pan zabił wszystko, co pierworodne w ziemi Egiptu, od pierworodnego syna faraona, zasiadającego na jego tronie, aż do pierworodnego więźnia, który był w więzieniu, oraz wszystko, co pierworodne z bydła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 30, 'Wstał tej nocy faraon, a z nim wszyscy jego słudzy oraz wszyscy Egipcjanie; i podniósł się w Egipcie wielki krzyk, bo nie było domu, w którym nie byłoby umarłego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 31, 'Faraon wezwał Mojżesza i Aarona w nocy i powiedział: Wstańcie, wyjdźcie spośród mego ludu, wy i synowie Izraela. Idźcie i służcie Panu, jak mówiliście.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 32, 'Zabierzcie też swoje trzody i bydła, jak żądaliście, i idźcie. Mnie też błogosławcie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 33, 'I Egipcjanie przynaglali lud, aby ich jak najszybciej wyprawić z ziemi, bo mówili: Wszyscy pomrzemy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 34, 'Wziął więc lud swoje ciasto, zanim się zakwasiło, i dzieże owinięte w swoje szaty i kładli je na swoje ramiona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 35, 'Synowie Izraela postąpili według nakazu Mojżesza i pożyczyli od Egipcjan srebrne i złote przedmioty oraz szaty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 36, 'A Pan dał ludowi łaskę w oczach Egipcjan, tak że im pożyczyli. I złupili Egipcjan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 37, 'Wyruszyli więc synowie Izraela z Ramzes do Sukkot, około sześciuset tysięcy pieszych mężczyzn, nie licząc dzieci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 38, 'Ale szło z nimi też mnóstwo obcego ludu oraz owce i bydło, bardzo liczny dobytek.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 39, 'I popiekli przaśne placki z ciasta, które wynieśli z Egiptu, bo nie było zakwaszone. Ponieważ zostali wygnani z Egiptu, nie mogli zwlekać i nie przygotowali sobie też żadnej żywności.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 40, 'A czas przebywania synów Izraela, którzy mieszkali w Egipcie, wynosił czterysta trzydzieści lat.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 41, 'I stało się tak, że po upływie czterystu trzydziestu lat, tego samego dnia, wszystkie zastępy Pana wyszły z ziemi Egiptu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 42, 'Ta noc ma być obchodzona dla Pana, dlatego że wyprowadził ich z ziemi Egiptu. Ta noc ma być więc obchodzona dla Pana przez wszystkich synów Izraela po wszystkie ich pokolenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 43, 'I Pan powiedział do Mojżesza i Aarona: Taka jest ustawa Paschy: Żaden obcy nie będzie z niej spożywał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 44, 'Każdy jednak wasz sługa nabyty za pieniądze będzie mógł z niej spożywać, jeśli tylko go obrzezacie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 45, 'Cudzoziemiec i najemnik nie będą z niej spożywać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 46, 'W jednym domu będzie spożywany baranek. Nie wyniesiesz z domu nic z jego mięsa i nie złamiecie jego kości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 47, 'Całe zgromadzenie Izraela tak z nim postąpi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 48, 'A jeśli jakiś cudzoziemiec będzie twoim gościem i będzie chciał obchodzić Paschę dla Pana, niech najpierw zostanie obrzezany każdy mężczyzna jego domu, a potem niech przystąpi i obchodzi ją. Wtedy będzie jak urodzony w tej ziemi. A ktokolwiek nie jest obrzezany, nie będzie z niej spożywał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 49, 'Jedno prawo będzie dla urodzonego w ziemi i dla cudzoziemca, który jest gościem wśród was.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 50, 'Wszyscy synowie Izraela uczynili więc, jak Pan rozkazał Mojżeszowi i Aaronowi, tak właśnie uczynili.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 51, 'Tego samego dnia Pan wyprowadził synów Izraela z ziemi Egiptu według ich zastępów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 1, 'I Pan powiedział do Mojżesza:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 2, 'Poświęć mi wszystko, co pierworodne. Wszystko, co otwiera łono u synów Izraela, tak wśród ludzi, jak i wśród bydła. To należy do mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 3, 'Mojżesz powiedział więc do ludu: Pamiętajcie ten dzień, w którym wyszliście z Egiptu, z domu niewoli. Pan bowiem potężną ręką wyprowadził was stamtąd. Nie będziecie jeść nic kwaszonego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 4, 'Dziś wychodzicie, w miesiącu Abib.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 5, 'A gdy Pan wprowadzi cię do ziemi Kananejczyków, Chetytów, Amorytów, Chiwwitów i Jebusytów, którą przysiągł dać waszym ojcom, ziemię opływającą mlekiem i miodem, wtedy będziesz obchodził ten obrzęd w tym samym miesiącu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 6, 'Przez siedem dni będziesz jeść przaśny chleb, a siódmego dnia będzie święto dla Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 7, 'Będziesz jadł przaśny chleb przez siedem dni i nie może znaleźć się u ciebie nic kwaszonego ani żaden zakwas nie może być widziany we wszystkich twoich granicach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 8, 'W tym dniu opowiesz swemu synowi: Obchodzę to ze względu na to, co Pan dla mnie uczynił, gdy wychodziłem z Egiptu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 9, 'To będzie jako znak na twojej ręce i jako pamiątka przed twoimi oczyma, aby prawo Pana było na twoich ustach. Pan bowiem potężną ręką wyprowadził cię z Egiptu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 10, 'Będziesz przestrzegał tej ustawy w wyznaczonym czasie, z roku na rok.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 11, 'A gdy Pan wprowadzi cię do ziemi Kanaan, jak przysiągł tobie i twoim ojcom, i da ją tobie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 12, 'Wtedy przeznaczysz dla Pana wszystko, co otwiera łono, i każdy płód otwierający łono z twojego bydła, każdy samiec będzie dla Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 13, 'Każde zaś pierworodne oślę wykupisz barankiem, a jeśli nie wykupisz, złamiesz mu kark. Wykupisz też każdego pierworodnego człowieka wśród twoich synów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 14, 'A gdy w przyszłości twój syn cię zapyta: Cóż to jest? Wtedy odpowiesz mu: Pan wyprowadził nas potężną ręką z Egiptu, z domu niewoli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 15, 'Gdy bowiem faraon stał się twardy i wzbraniał się nas wypuścić, wtedy Pan zabił wszystko, co pierworodne w ziemi Egiptu, od pierworodnego z ludzi aż do pierworodnego z bydła. Dlatego składam w ofierze Panu wszystkie samce otwierające łono, ale każdego pierworodnego z moich synów wykupuję.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 16, 'To będzie jako znak na twojej ręce i jako przepaska ozdobna między twoimi oczyma, że Pan potężną ręką wyprowadził nas z Egiptu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 17, 'A stało się tak, że gdy faraon wypuścił lud, Bóg nie prowadził go drogą przez ziemię Filistynów, chociaż była bliższa. Bóg bowiem powiedział: Żeby lud na widok wojny nie żałował i nie wrócił do Egiptu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 18, 'Ale Bóg prowadził lud okrężną drogą przez pustynię nad Morzem Czerwonym. I synowie Izraela wyszli z ziemi Egiptu w bojowym szyku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 19, 'Mojżesz wziął też ze sobą kości Józefa, gdyż ten zobowiązał synów Izraela przysięgą, mówiąc: Na pewno Bóg was nawiedzi. Zabierzcie więc stąd ze sobą moje kości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 20, 'Wyruszyli z Sukkot i rozbili obóz w Etam, na skraju pustyni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 21, 'A Pan szedł przed nimi za dnia w słupie obłoku, by prowadzić ich drogą, a nocą w słupie ognia, by im świecić, żeby mogli iść dniem i nocą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 22, 'Nie oddalał od ludu ani słupa obłoku za dnia, ani słupa ognia nocą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 1, 'Pan powiedział do Mojżesza:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 2, 'Powiedz synom Izraela, aby zawrócili i rozbili obóz przed Pi-Hachirot, pomiędzy Migdol a morzem, naprzeciw Baal-Sefon. Rozbijcie obóz naprzeciw niego nad morzem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 3, 'Faraon bowiem powie o synach Izraela: Pobłądzili w ziemi, pustynia ich zamknęła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 4, 'I zatwardzę serce faraona, tak że będzie ich ścigać. I będę wysławiony dzięki faraonowi i dzięki całemu jego wojsku, a Egipcjanie poznają, że ja jestem Pan. I tak uczynili.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 5, 'Gdy doniesiono królowi Egiptu, że lud ucieka, odmieniło się serce faraona i jego sług przeciw ludowi i powiedzieli: Co zrobiliśmy, że zwolniliśmy Izraela od służenia nam?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 6, 'Zaprzągł więc swój rydwan i wziął ze sobą swoich ludzi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 7, 'Wziął też sześćset wyborowych rydwanów i wszystkie rydwany Egiptu oraz przełożonych nad każdym z nich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 8, 'I Pan zatwardził serce faraona, króla Egiptu, który ścigał synów Izraela, synowie Izraela wyszli jednak pod potężną ręką.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 9, 'I Egipcjanie ścigali ich: wszystkie konie i rydwany faraona, jego jeźdźcy i wojska, i dogonili ich w obozie nad morzem, niedaleko Pi-Hachirot, naprzeciw Baal-Sefon.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 10, 'A gdy faraon zbliżył się, synowie Izraela podnieśli swe oczy i spostrzegli, że oto Egipcjanie ciągną za nimi, i bardzo się przerazili. Wtedy synowie Izraela wołali do Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 11, 'I mówili do Mojżesza: Czy dlatego, że nie było grobów w Egipcie, wyprowadziłeś nas, abyśmy pomarli na pustyni? Dlaczego nam to uczyniłeś, że nas wyprowadziłeś z Egiptu?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 12, 'Czyż nie mówiliśmy ci tego w Egipcie: Zostaw nas w spokoju, abyśmy służyli Egipcjanom? Bo lepiej nam było służyć Egipcjanom, niż umierać na pustyni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 13, 'Mojżesz odpowiedział ludowi: Nie bójcie się, stójcie i patrzcie na wybawienie Pana, które wam dziś okaże. Egipcjan bowiem, których teraz widzicie, nie zobaczycie nigdy więcej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 14, 'Pan będzie za was walczył, a wy będziecie milczeć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 15, 'I Pan powiedział do Mojżesza: Dlaczego wołasz do mnie? Powiedz synom Izraela, aby ruszyli;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 16, 'Ty zaś podnieś swą laskę, wyciągnij rękę nad morze i rozdziel je. A synowie Izraela niech idą środkiem morza po suchej ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 17, 'A oto ja, ja zatwardzę serca Egipcjan, że wejdą za nimi. I będę wysławiony dzięki faraonowi i całemu jego wojsku, jego rydwanom i jeźdźcom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 18, 'I Egipcjanie poznają, że ja jestem Pan, gdy będę wysławiony dzięki faraonowi, jego rydwanom i jeźdźcom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 19, 'Wówczas Anioł Boga, który szedł przed obozem Izraela, przeszedł na jego tyły. Słup obłoku również odszedł sprzed niego i stanął za nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 20, 'Wszedł więc między obóz Egipcjan i obóz Izraela. Ten był dla Egipcjan obłokiem ciemności, ale Izraelitom oświetlał noc. W ten sposób jedni do drugich nie zbliżyli się przez całą noc.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 21, 'Wtedy Mojżesz wyciągnął rękę nad morze, a Pan rozpędził morze silnym wiatrem wschodnim, który wiał przez całą noc, i osuszył morze, a wody się rozstąpiły.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 22, 'I synowie Izraela szli środkiem morza po suchej ziemi. Wody były dla nich murem, po ich prawej i lewej stronie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 23, 'Egipcjanie zaś ścigali ich i weszli za nimi, wszystkie konie faraona, jego rydwany i jeźdźcy, w sam środek morza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 24, 'O straży porannej Pan spojrzał na obóz Egipcjan ze słupa ognia i obłoku i pomieszał wojsko Egipcjan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 25, 'I odrywał koła ich rydwanów, tak że z trudem je wlekli. Egipcjanie powiedzieli więc: Uciekajmy przed Izraelem, gdyż Pan walczy za niego przeciw Egipcjanom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 26, 'Pan powiedział do Mojżesza: Wyciągnij rękę nad morze, aby wody wróciły na Egipcjan, na ich rydwany i na ich jeźdźców.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 27, 'Mojżesz wyciągnął więc rękę nad morze, a ono o poranku powróciło do swojej mocy, Egipcjanie zaś uciekali mu naprzeciw. Tak Pan pogrążył Egipcjan w środku morza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 28, 'Wtedy wody wróciły i okryły rydwany i jeźdźców, i całe wojsko faraona, które weszło za nimi w morze. Nie pozostał ani jeden z nich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 29, 'Lecz synowie Izraela szli po suchej ziemi środkiem morza, a wody były dla nich murem, po ich prawej i lewej stronie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 30, 'Tak Pan w tym dniu wybawił Izraela z ręki Egipcjan. I Izraelici widzieli martwych Egipcjan na brzegu morza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 31, 'Izrael widział to wielkie dzieło, którego Pan dokonał nad Egipcjanami. I lud się bał Pana, i uwierzył Panu oraz Mojżeszowi, jego słudze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 1, 'Wówczas Mojżesz i synowie Izraela zaśpiewali Panu tę pieśń: Będę śpiewał Panu, bo bardzo się wywyższył. Konia i jego jeźdźca wrzucił w morze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 2, 'Pan moją mocą i moją chwałą, bo stał się dla mnie zbawieniem. To mój Bóg, dlatego zbuduję mu przybytek, to Bóg mego ojca, dlatego będę go wywyższał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 3, 'Pan jest wojownikiem, Pan to jego imię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 4, 'Rydwany faraona i jego wojsko wrzucił w morze, a jego wyborni wodzowie zostali potopieni w Morzu Czerwonym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 5, 'Okryły ich głębiny, poszli w głębię jak kamień.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 6, 'Twoja prawica, Panie, jest uwielbiona w mocy. Twoja prawica, Panie, starła nieprzyjaciela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 7, 'A w wielkości twego majestatu powaliłeś swoich przeciwników. Zesłałeś swój gniew, który pożarł ich jak słomę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 8, 'Pod tchnieniem twoich nozdrzy zebrały się wody, cieknące wody stanęły jak wał i głębiny osiadły pośrodku morza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 9, 'Nieprzyjaciel mówił: Będę ścigał, dogonię, będę dzielił łupy; nasyci się nimi moja dusza, dobędę swój miecz, zgładzi ich moja ręka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 10, 'Powiałeś swoim wiatrem, okryło ich morze. Zatonęli jak ołów w potężnych wodach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 11, 'Któż jest podobny do ciebie wśród bogów, Panie? Któż jest jak ty, wspaniały w świętości, straszliwy w chwale, czyniący cuda?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 12, 'Wyciągnąłeś swoją prawicę, pochłonęła ich ziemia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 13, 'Wiedziesz w swoim miłosierdziu ten lud, który odkupiłeś. Prowadzisz w swej potędze do swego świętego przybytku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 14, 'Usłyszą o tym narody i zadrżą. Smutek przejmie obywateli Filistei.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 15, 'Wtedy zlękną się książęta Edomu, mocarzy Moabu ogarnie strach; struchleją wszyscy obywatele Kanaanu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 16, 'Padnie na nich strach i lęk; z powodu potęgi twego ramienia zamilkną jak kamień, aż przejdzie twój lud, Panie, aż przejdzie lud, który sobie nabyłeś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 17, 'Wprowadzisz go i zasadzisz na górze twego dziedzictwa, na miejscu, Panie, które uczyniłeś swoim mieszkaniem, w świątyni, Panie, którą umocniły twoje ręce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 18, 'Pan będzie królował na wieki wieków.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 19, 'Weszły bowiem konie faraona z jego rydwanami i z jego jeźdźcami w morze, a Pan skierował na nich wody morskie; synowie Izraela zaś szli po suchej ziemi środkiem morza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 20, 'Wtedy prorokini Miriam, siostra Aarona, wzięła bęben w rękę, a wszystkie kobiety wyszły za nią z bębnami i w pląsach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 21, 'I Miriam powiedziała do nich: Śpiewajcie Panu, bo jest bardzo wywyższony; konia i jego jeźdźca wrzucił do morza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 22, 'Potem Mojżesz poprowadził Izraela znad Morza Czerwonego i wyszli na pustynię Szur. Szli trzy dni przez pustynię i nie znaleźli wody.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 23, 'A gdy przybyli do Mary, nie mogli pić z wód Mary, bo były gorzkie. Dlatego nazwano to miejsce Mara.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 24, 'Wtedy lud szemrał przeciw Mojżeszowi, mówiąc: Cóż będziemy pić?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 25, 'I Mojżesz wołał do Pana, a Pan wskazał mu drzewo, które on wrzucił do wody, a woda stała się słodka. Tam ustanowił dla nich ustawę i prawo i tam ich wystawił na próbę;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 26, 'I powiedział: Jeśli będziesz pilnie słuchał głosu Pana, twego Boga, i będziesz robił to, co prawe w jego oczach, i nakłonisz uszy ku jego przykazaniom, i będziesz przestrzegał wszystkich jego ustaw, to nie ześlę na ciebie żadnej choroby, jaką zesłałem na Egipt, gdyż ja jestem Pan, który cię uzdrawia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 27, 'I przybyli do Elim, gdzie było dwanaście źródeł wody i siedemdziesiąt palm; tam rozbili obóz nad wodami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 1, 'Potem wyruszyli z Elim i całe zgromadzenie synów Izraela przybyło na pustynię Sin, która leży między Elim a Synajem, piętnastego dnia drugiego miesiąca po ich wyjściu z ziemi Egiptu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 2, 'I całe zgromadzenie synów Izraela szemrało przeciw Mojżeszowi i Aaronowi na pustyni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 3, 'Synowie Izraela mówili do nich: Obyśmy pomarli z ręki Pana w ziemi Egiptu, gdy siadaliśmy nad garncami mięsa, gdy najadaliśmy się chleba do syta! Bo wyprowadziliście nas na tę pustynię, by całą tę rzeszę zamorzyć głodem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 4, 'Wtedy Pan powiedział do Mojżesza: Oto spuszczę wam jak deszcz chleb z nieba. Lud będzie wychodził i każdego dnia będzie zbierał według potrzeby dziennej, abym mógł go wystawić na próbę, czy będzie postępował zgodnie z moim prawem, czy nie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 5, 'A szóstego dnia przyrządzą to, co przyniosą, a będzie tego dwa razy tyle, co zbierają codziennie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 6, 'Mojżesz i Aaron mówili do wszystkich synów Izraela: Wieczorem poznacie, że Pan wyprowadził was z ziemi Egiptu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 7, 'A rano ujrzycie chwałę Pana, usłyszał bowiem wasze szemrania przeciw Panu. A my, czym jesteśmy, że szemrzecie przeciwko nam?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 8, 'Mojżesz mówił dalej: Pan da wam wieczorem mięso do jedzenia, a rano chleb do syta. Pan bowiem usłyszał wasze szemrania, które podnosicie przeciw niemu. A my, czym jesteśmy? Wasze szemrania nie są przeciwko nam, ale przeciwko Panu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 9, 'Mojżesz powiedział do Aarona: Powiedz całemu zgromadzeniu synów Izraela: Zbliżcie się przed oblicze Pana, gdyż usłyszał wasze szemranie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 10, 'Gdy Aaron mówił do całego zgromadzenia synów Izraela, spojrzeli w stronę pustyni, a oto chwała Pana ukazała się w obłoku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 11, 'Potem Pan powiedział do Mojżesza:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 12, 'Usłyszałem szemranie synów Izraela. Powiedz do nich: Pod wieczór będziecie jeść mięso, a rano będziecie nasyceni chlebem. I poznacie, że ja jestem Pan, wasz Bóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 13, 'Wieczorem stało się tak, że zleciały się przepiórki i pokryły obóz, a rano dokoła obozu leżała rosa;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 14, 'A gdy warstwa rosy się uniosła, ukazało się na powierzchni pustyni coś bardzo małego, okrągłego, drobnego jak szron na ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 15, 'Gdy synowie Izraela to zobaczyli, mówili jeden do drugiego: To manna, gdyż nie wiedzieli, co to było. I Mojżesz powiedział do nich: To jest chleb, który Pan dał wam do jedzenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 16, 'Oto co Pan rozkazał: Niech każdy zbiera z niego tyle, ile trzeba do jedzenia, omer na osobę, według liczby osób. Niech każdy zbiera dla tych, którzy są w jego namiocie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 17, 'I synowie Izraela tak uczynili, i zbierali jedni więcej, drudzy mniej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 18, 'A gdy to mierzyli omerem, to ten, kto nazbierał więcej, nie miał nadmiaru, temu zaś, kto nazbierał mało, nie zabrakło. Każdy zbierał według tego, co mógł zjeść.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 19, 'Mojżesz mówił też do nich: Niech nikt nie pozostawia z tego nic do rana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 20, 'Jednak nie usłuchali Mojżesza i zostawili niektórzy z tego aż do rana, i zamieniło się w robaki, i cuchnęło. I Mojżesz rozgniewał się na nich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 21, 'Zbierali to więc każdego ranka, każdy według tego, co mógł zjeść. A gdy słońce zaczynało grzać, topniało.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 22, 'A gdy nastał szósty dzień, zbierali dwa razy więcej chleba, po dwa omery na każdego. I wszyscy przełożeni zgromadzenia przyszli i powiedzieli o tym Mojżeszowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 23, 'On zaś powiedział im: Oto co Pan mówił: Jutro będzie odpoczynek, święty szabat dla Pana. Upieczcie, co macie upiec, ugotujcie, co macie ugotować, a co zostanie, zostawcie sobie i zachowajcie do jutra.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 24, 'Zostawili więc to do rana, jak Mojżesz rozkazał, i nie cuchnęło ani nie było w tym robaków.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 25, 'I Mojżesz powiedział: Jedzcie to dziś, bo dziś jest szabat dla Pana. Dziś nie znajdziecie tego na polu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 26, 'Przez sześć dni będziecie to zbierać, a w siódmym dniu jest szabat, w nim tego nie będzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 27, 'A siódmego dnia niektórzy z ludu wyszli, aby zbierać, ale nic nie znaleźli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 28, 'Wtedy Pan powiedział do Mojżesza: Jak długo będziecie się wzbraniać przed przestrzeganiem moich przykazań i moich praw?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 29, 'Patrzcie, Pan dał wam szabat, dlatego w szóstym dniu daje wam chleb na dwa dni. Niech każdy zostanie na swoim miejscu, niech nikt nie wychodzi ze swego miejsca w siódmym dniu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 30, 'Odpoczywał więc lud siódmego dnia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 31, 'I dom Izraela nadał temu pokarmowi nazwę manna. Była jak nasienie kolendry, biała, o smaku placków z miodem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 32, 'Mojżesz powiedział: Tak rozkazał Pan: Napełnij nim omer na przechowanie dla waszych przyszłych pokoleń, aby widziały ten chleb, którym was karmiłem na pustyni, gdy wyprowadziłem was z ziemi Egiptu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 33, 'Potem Mojżesz powiedział do Aarona: Weź naczynie, wsyp do niego pełen omer manny i postaw je przed Panem na przechowanie dla waszych przyszłych pokoleń.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 34, 'Jak Pan przykazał Mojżeszowi, tak Aaron postawił je przed Świadectwem na przechowanie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 35, 'A synowie Izraela jedli mannę przez czterdzieści lat, aż przybyli do ziemi zamieszkałej. Jedli mannę, aż przybyli do granic ziemi Kanaan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 36, 'A omer to dziesiąta część efy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 1, 'Całe zgromadzenie synów Izraela wyruszyło z pustyni Sin, robiąc postoje, według rozkazu Pana, i rozbili obóz w Refidim, gdzie nie było wody, aby lud mógł się napić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 2, 'Dlatego lud spierał się z Mojżeszem, mówiąc: Dajcie nam wody, abyśmy się napili. Mojżesz odpowiedział im: Dlaczego kłócicie się ze mną? Czemu wystawiacie Pana na próbę?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 3, 'Lud zaś pragnął tam wody i szemrał przeciwko Mojżeszowi, mówiąc: Po co wyprowadziłeś nas z Egiptu, aby uśmiercić nas, nasze dzieci i nasze bydło pragnieniem?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 4, 'Wtedy Mojżesz zawołał do Pana: Cóż mam uczynić z tym ludem? Jeszcze trochę, a mnie ukamienują.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 5, 'I Pan powiedział do Mojżesza: Idź przed ludem i weź ze sobą niektórych ze starszych Izraela. Weź także w rękę swoją laskę, którą uderzyłeś w rzekę, i idź.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 6, 'Oto stanę przed tobą tam, na skale na Horebie, i uderzysz w skałę, a wypłynie z niej woda, którą lud będzie pił. I Mojżesz uczynił tak na oczach starszych Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 7, 'I nadał temu miejscu nazwę Massa i Meriba z powodu kłótni synów Izraela i dlatego, że wystawili na próbę Pana, mówiąc: Czy Pan jest wśród nas, czy nie?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 8, 'Tymczasem Amalek nadciągnął, aby walczyć z Izraelem w Refidim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 9, 'I Mojżesz powiedział do Jozuego: Wybierz nam mężczyzn, wyrusz i stocz bitwę z Amalekiem. Ja zaś jutro stanę na szczycie wzgórza z laską Boga w ręku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 10, 'Jozue uczynił więc, jak mu Mojżesz rozkazał, i stoczył bitwę z Amalekiem. A Mojżesz, Aaron i Chur weszli na szczyt wzgórza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 11, 'Gdy Mojżesz podnosił rękę, przeważał Izrael, a gdy opuszczał rękę, przeważał Amalek.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 12, 'Ale ręce Mojżesza były ociężałe. Wzięli więc kamień i podłożyli pod niego, i usiadł na nim. A Aaron i Chur podpierali jego ręce, jeden z jednej, drugi z drugiej strony. I jego ręce były stale podniesione aż do zachodu słońca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 13, 'Jozue rozgromił więc Amaleka i jego lud ostrzem miecza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 14, 'Wtedy Pan powiedział do Mojżesza: Zapisz to na pamiątkę w księdze i powtórz do uszu Jozuego, że wymażę zupełnie pamięć o Amaleku pod niebem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 15, 'Potem Mojżesz zbudował ołtarz i nadał mu nazwę: Pan moją chorągwią;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 16, 'Bo powiedział: Ręka tronu Pana i wojna Pana będzie przeciwko Amalekowi z pokolenia na pokolenie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 1, 'A gdy teść Mojżesza Jetro, kapłan Midianitów, usłyszał o wszystkim, co Bóg uczynił dla Mojżesza i swego ludu Izraela, że Pan wyprowadził Izraela z Egiptu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 2, 'Wtedy Jetro, teść Mojżesza, wziął żonę Mojżesza Seforę, którą ten wcześniej odesłał;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 3, 'Oraz jej dwóch synów, z których jednemu było na imię Gerszom, bo Mojżesz powiedział: Jestem przybyszem w cudzej ziemi;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 4, 'Drugi zaś miał na imię Eliezer, bo mówił: Bóg mego ojca był moją pomocą i wybawił mnie od miecza faraona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 5, 'Jetro, teść Mojżesza, przybył wraz z jego synami i żoną do Mojżesza na pustynię, gdzie obozował przy górze Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 6, 'I kazał powiedzieć Mojżeszowi: Ja, twój teść Jetro, idę do ciebie wraz z twoją żoną i z oboma jej synami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 7, 'Mojżesz wyszedł więc swemu teściowi naprzeciw, pokłonił się i ucałował go. Potem wypytywali się wzajemnie o powodzenie i weszli do namiotu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 8, 'Mojżesz opowiedział swemu teściowi wszystko, co Pan uczynił faraonowi i Egipcjanom ze względu na Izraela, o całym trudzie, który ich spotkał w drodze, i jak Pan ich wybawił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 9, 'Jetro cieszył się ze wszelkiego dobra, które Pan uczynił Izraelowi, że wybawił go z ręki Egipcjan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 10, 'I Jetro powiedział: Niech będzie błogosławiony Pan, który was wybawił z ręki Egipcjan i z ręki faraona i który wybawił lud z niewoli egipskiej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 11, 'Teraz wiem, że Pan jest większy od wszystkich bogów, bo gdy oni zuchwale powstawali przeciwko niemu, to od tego poginęli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 12, 'Potem Jetro, teść Mojżesza, wziął całopalenie i ofiary dla Boga. Przyszedł też Aaron i wszyscy starsi Izraela, aby jeść chleb z teściem Mojżesza przed Bogiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 13, 'Nazajutrz Mojżesz usiadł, aby sądzić lud. I lud stał przed Mojżeszem od rana aż do wieczora.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 14, 'Gdy teść Mojżesza zobaczył wszystko, co on czynił dla ludu, powiedział: Cóż to jest, co ty czynisz dla ludu? Dlaczego ty siedzisz sam, a cały lud stoi przed tobą od rana aż do wieczora?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 15, 'Wtedy Mojżesz odpowiedział swemu teściowi: Bo lud przychodzi do mnie, aby się radzić Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 16, 'Gdy mają jakąś sprawę, przychodzą do mnie, a ja rozsądzam między nimi i oznajmiam ustawy Boga i jego prawa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 17, 'Teść Mojżesza powiedział do niego: Niedobra to rzecz, którą czynisz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 18, 'Zamęczycie się i ty, i ten lud, który jest z tobą, bo ta sprawa jest zbyt ciężka dla ciebie. Sam jej nie podołasz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 19, 'Dlatego posłuchaj teraz mego głosu, poradzę ci, a Bóg będzie z tobą. Wstawiaj się za ludem przed Bogiem i zanoś sprawy Bogu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 20, 'Nauczaj go też ustaw i praw, wskazuj im drogę, którą mają chodzić, i czyny, które mają spełniać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 21, 'Upatrz też sobie wśród całego ludu mężczyzn dzielnych i bojących się Boga, mężczyzn prawdomównych, którzy nienawidzą chciwości, i ustanów ich przełożonymi nad tysiącem, nad setką, nad pięćdziesiątką i nad dziesiątką.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 22, 'Niech oni sądzą lud w każdym czasie. A gdy będzie ważniejsza sprawa, zaniosą ją do ciebie, ale każdą mniej ważną sprawę sami będą sądzić. W ten sposób ulżysz sobie, gdy poniosą ciężar z tobą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 23, 'Jeśli tak uczynisz, a Bóg tak ci nakaże, wytrwasz i cały ten lud będzie wracać na swoje miejsce w pokoju.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 24, 'Mojżesz usłuchał więc rady swego teścia i uczynił wszystko, jak mu powiedział.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 25, 'I Mojżesz wybrał z całego Izraela dzielnych mężczyzn, i ustanowił ich przełożonymi nad ludem, nad tysiącem, nad setką, nad pięćdziesiątką i nad dziesiątką;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 26, 'I sądzili lud w każdym czasie. Trudne sprawy zanosili do Mojżesza, a każdą drobniejszą sprawę sami sądzili.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 27, 'Potem Mojżesz odprawił swego teścia, który odszedł do swej ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 1, 'W trzecim miesiącu od wyjścia synów Izraela z ziemi Egiptu, w tym samym dniu, przyszli na pustynię Synaj.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 2, 'Bo wyruszyli z Refidim i po przybyciu na pustynię Synaj rozbili obóz na pustyni; tam Izrael obozował naprzeciw góry.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 3, 'A Mojżesz wstąpił do Boga i Pan zawołał do niego z góry: Tak powiesz domowi Jakuba i oznajmisz synom Izraela:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 4, 'Widzieliście, co uczyniłem Egipcjanom i jak niosłem was na skrzydłach orłów, i przyprowadziłem was do siebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 5, 'Dlatego teraz, jeśli posłuchacie mego głosu i będziecie przestrzegać mojego przymierza, będziecie moją szczególną własnością ponad wszystkie narody, bo do mnie należy cała ziemia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 6, 'A wy będziecie mi królestwem kapłanów i narodem świętym. To są słowa, które będziesz mówić do synów Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 7, 'Wtedy Mojżesz przyszedł i zwołał starszych ludu, i wyłożył im wszystkie te słowa, które mu Pan nakazał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 8, 'Cały lud odpowiedział wspólnie: Uczynimy wszystko, co Pan powiedział. I Mojżesz zaniósł słowa ludu do Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 9, 'Pan powiedział do Mojżesza: Oto przyjdę do ciebie w gęstym obłoku, aby lud słyszał, gdy będę z tobą rozmawiał, i uwierzył ci na zawsze. A Mojżesz przekazał Panu słowa ludu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 10, 'Pan zaś mówił do Mojżesza: Idź do ludu i uświęć ich dziś i jutro, i niech wypiorą swoje szaty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 11, 'Niech będą gotowi na trzeci dzień. Trzeciego dnia bowiem Pan zstąpi na oczach całego ludu na górę Synaj.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 12, 'I wyznaczysz ludowi granice dokoła, mówiąc: Strzeżcie się, abyście nie wstępowali na górę ani nie dotykali jej podnóża. Każdy, kto dotknie góry, poniesie śmierć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 13, 'Nie dotknie go ręka, ale ukamienują go albo przeszyją strzałami; czy to zwierzę, czy człowiek, nie będzie żyć. Gdy przeciągle będą trąbić, niech podejdą do góry.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 14, 'Mojżesz zstąpił więc z góry do ludu i uświęcił lud, a oni uprali swoje szaty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 15, 'I mówił do ludu: Bądźcie gotowi na trzeci dzień, nie zbliżajcie się do żon.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 16, 'Trzeciego dnia o poranku pojawiły się grzmoty i błyskawice, i gęsty obłok nad górą, i bardzo potężny głos trąby, tak że cały lud, który był w obozie, zadrżał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 17, 'I Mojżesz wyprowadził lud z obozu na spotkanie z Bogiem, i stanęli u stóp góry.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 18, 'A góra Synaj cała dymiła, gdyż Pan zstąpił na nią w ogniu. Dym unosił się z niej jak dym z pieca i cała góra bardzo się trzęsła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 19, 'A gdy głos trąby się przeciągał i coraz bardziej się rozlegał, Mojżesz mówił, a Bóg odpowiadał mu głosem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 20, 'I Pan zstąpił na górę Synaj, na szczyt góry. Wtedy Pan wezwał Mojżesza na szczyt góry i Mojżesz tam wstąpił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 21, 'Potem Pan powiedział do Mojżesza: Zejdź, przestrzeż lud, by nie przekroczył granicy, aby zobaczyć Pana, i aby wielu z nich nie zginęło.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 22, 'Nawet kapłani, którzy zbliżają się do Pana, niech się uświęcą, by ich Pan nie wytracił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 23, 'I Mojżesz powiedział do Pana: Lud nie może wejść na górę Synaj, ponieważ ty nas przestrzegłeś, mówiąc: Wyznacz granice wokół góry i uświęć ją.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 24, 'Pan powiedział do niego: Idź, zejdź, a potem wstąpisz ty i Aaron z tobą. Lecz kapłani i lud niech nie przekraczają granicy, by wstąpić do Pana, aby ich nie wytracił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 25, 'Mojżesz zszedł więc do ludu i powiedział im to.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 1, 'I Bóg mówił te wszystkie słowa:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 2, 'Ja jestem Pan, twój Bóg, który cię wyprowadził z ziemi Egiptu, z domu niewoli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 3, 'Nie będziesz miał innych bogów przede mną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 4, 'Nie będziesz czynił sobie żadnego rzeźbionego posągu ani żadnej podobizny czegokolwiek, co jest w górze na niebie, co jest nisko na ziemi ani co jest w wodach pod ziemią.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 5, 'Nie będziesz oddawał im pokłonu ani nie będziesz im służył, bo ja jestem Pan, twój Bóg, Bóg zazdrosny, nawiedzający nieprawość ojców na synach do trzeciego i czwartego pokolenia tych, którzy mnie nienawidzą;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 6, 'A okazujący miłosierdzie tysiącom tych, którzy mnie miłują i strzegą moich przykazań.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 7, 'Nie będziesz brał imienia Pana, twego Boga, nadaremnie, gdyż Pan nie zostawi bez kary tego, który bierze jego imię nadaremnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 8, 'Pamiętaj o dniu szabatu, aby go święcić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 9, 'Sześć dni będziesz pracować i wykonywać wszystkie swoje prace;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 10, 'Ale siódmy dzień jest szabatem Pana, twego Boga. W tym dniu nie będziesz wykonywał żadnej pracy – ani ty, ani twój syn, ani twoja córka, ani twój sługa, ani twoja służąca, ani twoje bydło, ani twój gość, który jest w obrębie twoich bram.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 11, 'Pan bowiem przez sześć dni stworzył niebo i ziemię, morze i wszystko, co jest w nich, a siódmego dnia odpoczął. Dlatego Pan błogosławił dzień szabatu i uświęcił go.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 12, 'Czcij swego ojca i swoją matkę, aby twoje dni były długie na ziemi, którą Pan, twój Bóg, da tobie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 13, 'Nie będziesz zabijał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 14, 'Nie będziesz cudzołożył.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 15, 'Nie będziesz kradł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 16, 'Nie będziesz fałszywie świadczył przeciw twemu bliźniemu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 17, 'Nie będziesz pożądał domu twego bliźniego ani nie będziesz pożądał żony twego bliźniego, ani jego sługi, ani jego służącej, ani jego wołu, ani jego osła, ani żadnej rzeczy, która należy do twego bliźniego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 18, 'Wtedy cały lud widział gromy i błyskawice i słyszał głos trąby, i dostrzegał dymiącą górę. Gdy lud to widział, cofnął się i stanął z daleka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 19, 'I mówił do Mojżesza: Ty mów do nas, a będziemy słuchać, ale niech Bóg do nas nie mówi, byśmy nie pomarli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 20, 'Mojżesz odpowiedział ludowi: Nie bójcie się. Bóg bowiem przyszedł, aby was wystawić na próbę i żeby jego bojaźń była przed waszym obliczem, byście nie grzeszyli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 21, 'Stał więc lud z daleka, a Mojżesz zbliżył się do gęstego mroku, w którym był Bóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 22, 'I Pan powiedział do Mojżesza: Tak powiesz synom Izraela: Widzieliście, że mówiłem do was z nieba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 23, 'Nie będziecie czynić przy mnie bogów ze srebra ani bogów ze złota nie będziecie sobie czynić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 24, 'Uczynisz mi ołtarz z ziemi i będziesz składać na nim twoje całopalenia i twoje ofiary pojednawcze, twoje owce i twoje bydło. Na każdym miejscu, gdzie upamiętnię swoje imię, przyjdę do ciebie i będę ci błogosławił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 25, 'A jeśli uczynisz mi ołtarz kamienny, nie buduj go z ciosanego kamienia. Jeśli bowiem przyłożysz do niego żelazne narzędzie, zbezcześcisz go.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 26, 'Nie będziesz wstępował po stopniach do mojego ołtarza, aby twoja nagość nie była przy nim odkryta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 1, 'A oto prawa, które im przedstawisz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 2, 'Jeśli kupisz niewolnika – Hebrajczyka, sześć lat będzie ci służyć, a w siódmym roku wyjdzie na wolność bez wykupu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 3, 'Jeśli sam przyszedł, sam odejdzie; a jeśli miał żonę, jego żona odejdzie z nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 4, 'Jeśli jego pan dał mu żonę, a ona urodziła mu synów lub córki, to jego żona i dzieci będą należały do jego pana, a on odejdzie sam.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 5, 'A jeśli niewolnik powie: Kocham mojego pana, moją żonę i moich synów, nie wyjdę na wolność;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 6, 'Wtedy jego pan zaprowadzi go do sędziów i przyprowadzi go do drzwi albo do ich słupka; i jego pan szydłem przekłuje mu ucho, i będzie jego niewolnikiem na zawsze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 7, 'Jeśli zaś kto sprzeda swoją córkę, aby była niewolnicą, nie odejdzie ona, jak odchodzą niewolnicy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 8, 'Jeśli się nie spodoba swemu panu, który zamierzał ją poślubić, niech pozwoli, aby została odkupiona. Nie ma prawa sprzedać jej obcemu ludowi, ponieważ zrobiłby jej krzywdę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 9, 'A jeśli przeznaczył ją dla swego syna, to postąpi z nią według prawa córek.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 10, 'Jeśli weźmie sobie za żonę jeszcze inną, nie umniejszy jej pożywienia, jej ubrania ani prawa małżeńskiego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 11, 'A jeśli nie zapewni jej tych trzech rzeczy, wtedy wyjdzie ona darmo bez okupu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 12, 'Kto uderzy człowieka tak, że ten umrze, poniesie śmierć;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 13, 'A jeśli nie czyhał na niego, ale Bóg podał go w jego rękę, wyznaczę miejsce, do którego będzie mógł uciec.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 14, 'Ale jeśli ktoś czyha na swego bliźniego i podstępnie go zabija, to nawet od mojego ołtarza go weźmiesz, aby umarł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 15, 'Kto uderzy swego ojca albo swoją matkę, poniesie śmierć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 16, 'Kto uprowadzi człowieka i sprzeda go lub zostanie on znaleziony w jego ręku, poniesie śmierć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 17, 'Kto złorzeczy swemu ojcu lub swojej matce, poniesie śmierć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 18, 'A jeśli mężczyźni się pokłócą i jeden uderzy drugiego kamieniem lub pięścią, tak że ten nie umrze, ale musi położyć się w łóżku;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 19, 'To jeśli wstanie i będzie mógł chodzić po ulicy o lasce, ten, który uderzył, będzie niewinny; wypłaci mu tylko odszkodowanie i będzie łożyć na jego leczenie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 20, 'Jeśli zaś ktoś uderzy kijem swego niewolnika lub swoją niewolnicę tak, że umrą pod jego ręką, musi ponieść karę;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 21, 'Jeśli jednak niewolnik zostaje przy życiu dzień lub dwa, nie będzie karany; bo niewolnik to jego pieniądze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 22, 'Jeśli mężczyźni się pokłócą i uderzą kobietę brzemienną, tak że wyjdzie z niej płód, jednak bez żadnej szkody, to musi ponieść karę, jaką nałoży na niego mąż tej kobiety, a da według uznania sędziów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 23, 'Jeśli jednak dojdzie do szkody, wtedy dasz życie za życie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 24, 'Oko za oko, ząb za ząb, rękę za rękę, nogę za nogę;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 25, 'Oparzenie za oparzenie, ranę za ranę, siniec za siniec.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 26, 'Jeśli ktoś uderzy w oko swego niewolnika lub w oko swojej niewolnicy, tak że je wybije, za jego oko wypuści go na wolność.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 27, 'Jeśli też ktoś wybije ząb swemu niewolnikowi lub ząb swojej niewolnicy, za jego ząb wypuści go na wolność.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 28, 'Jeśli czyjś wół ubodzie na śmierć mężczyznę lub kobietę, ten wół musi zostać ukamienowany, a jego mięsa nie wolno jeść. Właściciel wołu zaś będzie niewinny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 29, 'Jeśli jednak wół bódł przedtem i ostrzegano o tym jego właściciela, ten zaś nie pilnował go, i wół zabił mężczyznę lub kobietę, wół będzie ukamienowany i jego właściciel poniesie śmierć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 30, 'Jeśli nałożono mu karę pieniężną, wtedy da za swoją duszę okup, jaki na niego nałożą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 31, 'Choćby ubódł syna lub córkę, postąpią z nim według tego samego prawa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 32, 'Jeśli wół ubodzie niewolnika lub niewolnicę, da ich panu trzydzieści syklów srebra, a wół będzie ukamienowany.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 33, 'Jeśli ktoś zostawi studnię odkrytą lub jeśli ktoś wykopie studnię i nie nakryje jej, a wpadnie w nią wół lub osioł;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 34, 'Właściciel tej studni musi wyrównać stratę i wynagrodzi ich właścicielowi, a zdechłe zwierzę będzie należeć do niego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 35, 'Także jeśli czyjś wół ubodzie na śmierć wołu jego sąsiada, wtedy sprzedadzą żywego wołu i podzielą się zapłatą za niego; podzielą się też tym zdechłym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 36, 'Ale jeśli było wiadomo, że ten wół bódł przedtem, a jego właściciel nie pilnował go, musi oddać wołu za wołu, a zdechłe zwierzę będzie należeć do niego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 1, 'Jeśli ktoś ukradnie wołu lub owcę i zabije je albo sprzeda, odda pięć wołów za jednego wołu i cztery owce za jedną owcę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 2, 'Jeśli złodziej zostanie przyłapany przy włamaniu i tak pobity, że umrze, ten, kto zabił, nie będzie winien przelanej krwi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 3, 'Jeśli to zrobi po wschodzie słońca, będzie winien krwi, gdyż złodziej powinien wypłacić odszkodowanie. Jeśli nic nie ma, będzie sprzedany za swoją kradzież.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 4, 'Jeśli zostaną znalezione w jego ręku skradzione dobra jeszcze żywe, czy to wół, czy osioł, czy owca, zwróci podwójnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 5, 'Gdyby ktoś wypasł pole lub winnicę, bo puścił swoje bydło, aby się pasło na cudzym polu, wypłaci odszkodowanie z najlepszych plonów swego pola i z najlepszych plonów swej winnicy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 6, 'Jeśli wybuchnie ogień, a trafi na ciernie i spali stóg lub zboże na pniu, lub samo pole, ten, co wzniecił ogień, musi wypłacić odszkodowanie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 7, 'Jeśli ktoś da swemu bliźniemu pieniądze lub przedmioty do przechowania i zostanie to ukradzione z domu tego człowieka, to jeśli złodziej zostanie znaleziony, zwróci podwójnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 8, 'Jeśli złodziej nie zostanie znaleziony, pan tego domu stawi się przed sędziami, by okazało się, czy nie wyciągnął ręki po własność swego bliźniego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 9, 'W każdej spornej sprawie o wołu, osła, owcę, szatę czy jakąkolwiek zgubę, gdyby ktoś powiedział, że to jest jego, sprawa obydwu ma trafić do sędziów; kogo sędziowie uznają winnym, ten wynagrodzi podwójnie swemu bliźniemu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 10, 'Jeśli ktoś odda swemu bliźniemu na przechowanie osła, wołu, owcę lub inne zwierzę, a ono zdechnie, zostanie okaleczone lub uprowadzone i nikt tego nie zobaczy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 11, 'Wówczas przysięga przed Panem rozstrzygnie między obydwoma, że nie wyciągnął ręki po własność swego bliźniego. Właściciel przyjmie tę przysięgę, a drugi nie wypłaci odszkodowania.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 12, 'Jeśli jednak to zostało mu skradzione, wypłaci właścicielowi odszkodowanie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 13, 'Jeśli zostało rozszarpane, to przyniesie je jako dowód, a za rozszarpane nie zapłaci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 14, 'Jeśli ktoś pożyczy zwierzę od swego bliźniego, a ono zostanie okaleczone lub zdechnie podczas nieobecności jego właściciela, musi wypłacić odszkodowanie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 15, 'Jeśli jego właściciel był przy nim, nie zapłaci; a jeśli było wynajęte, zapłaci tylko za wynajem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 16, 'Jeśli ktoś uwiedzie dziewicę, która nie jest poślubiona, i położy się z nią, musi jej dać posag i weźmie ją sobie za żonę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 17, 'Jeśli jej ojciec żadną miarą nie zgodzi się dać mu jej, odważy pieniądze według zwyczaju panieńskiego posagu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 18, 'Nie zostawisz czarownicy przy życiu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 19, 'Każdy, kto spółkuje ze zwierzęciem, poniesie śmierć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 20, 'Kto składa ofiary bogom, poza samym Panem, zostanie stracony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 21, 'Nie zrobisz krzywdy przybyszowi ani nie będziesz go uciskać, gdyż i wy byliście przybyszami w ziemi Egiptu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 22, 'Nie będziecie dręczyć żadnej wdowy ani sieroty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 23, 'Jeśli będziesz je dręczył, a one będą wołać do mnie, na pewno wysłucham ich wołania.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 24, 'Wtedy rozpali się mój gniew i pobiję was mieczem, i wasze żony będą wdowami, a wasi synowie sierotami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 25, 'Jeśli pożyczysz pieniądze ubogiemu z mego ludu, który mieszka wśród was, nie postąpisz wobec niego jak lichwiarz, nie będziesz go obciążać lichwą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 26, 'Jeśli weźmiesz w zastaw szatę twego bliźniego, oddasz mu ją przed zachodem słońca;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 27, 'Bo to ubranie jest jedynym okryciem jego ciała, w tym też śpi. Jeśli będzie do mnie wołał, wysłucham go, bo jestem litościwy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 28, 'Nie będziesz złorzeczyć sędziom, a przełożonego twego ludu nie będziesz przeklinać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 29, 'Nie będziesz zwlekał ze złożeniem pierwocin twego zboża i płynnych zbiorów. Oddasz mi pierworodnego z twoich synów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 30, 'To samo zrobisz z twoimi wołami i owcami. Siedem dni pierworodny będzie ze swoją matką, a ósmego dnia oddasz mi go.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 31, 'Będziecie dla mnie świętym ludem i nie będziecie jeść mięsa rozszarpanego na polu; wyrzucicie je psom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 1, 'Nie będziesz rozgłaszał fałszywych wieści. Nie wchodź w spółkę z bezbożnym, by być fałszywym świadkiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 2, 'Nie idź za większością, aby wyrządzić zło, i nie zeznawaj w sprawie, ulegając zdaniu większości, by naginać sąd.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 3, 'I nie okazuj przychylności ubogiemu w jego sprawie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 4, 'Jeśli napotkasz błądzącego wołu swego wroga lub jego osła, musisz odprowadzić go do niego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 5, 'Jeśli zobaczysz, że osioł tego, który cię nienawidzi, leży pod swoim ciężarem, nie odmówisz mu pomocy. Owszem, masz mu z nim pomóc.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 6, 'Nie naginaj sądu twego ubogiego w jego sprawie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 7, 'Trzymaj się z dala od nieuczciwej sprawy. Nie zabijaj niewinnego i sprawiedliwego, bo nie usprawiedliwię bezbożnego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 8, 'Nie będziesz też brać darów, ponieważ dar zaślepia mądrych i wypacza słowa sprawiedliwych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 9, 'Nie uciskaj również przybysza, bo sami wiecie, jak się czuje przybysz, gdyż byliście przybyszami w ziemi Egiptu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 10, 'Przez sześć lat będziesz obsiewał swoją ziemię i zbierał jej plony;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 11, 'A w siódmym roku zostawisz ją odłogiem, żeby odpoczęła, aby jedli ubodzy twego ludu, a co zostanie po nich, zjedzą zwierzęta polne. Tak też postąpisz ze swoją winnicą i swoim sadem oliwnym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 12, 'Przez sześć dni będziesz wykonywać swoją pracę, ale siódmego dnia odpoczniesz, aby odpoczął twój wół i twój osioł i żeby odetchnął syn twojej niewolnicy i przybysz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 13, 'A we wszystkim, co wam powiedziałem, bądźcie ostrożni. Nie wspominajcie też imienia obcych bogów, niech nie będzie słyszane z twoich ust.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 14, 'Trzy razy w roku będziesz obchodzić dla mnie święto.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 15, 'Będziesz obchodzić Święto Przaśników. Siedem dni będziesz jeść przaśniki, jak ci nakazałem, w miesiącu Abib, bo w nim wyszedłeś z Egiptu. Nie pokażecie się przede mną z pustymi rękami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 16, 'I Święto Żniw, pierwocin twojej pracy, tego, co posiałeś na polu. I także Święto Zbiorów pod koniec roku, gdy zbierzesz z pola owoce swojej pracy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 17, 'Trzy razy w roku wszyscy twoi mężczyźni mają się pokazać przed Panem Bogiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 18, 'Nie będziesz ofiarował krwi mojej ofiary z chlebem kwaszonym, a tłuszcz mojej ofiary nie zostanie przez noc aż do poranka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 19, 'Przyniesiesz do domu Pana, twego Boga, pierwociny z pierwszych plonów swojej ziemi. Nie będziesz gotował koźlęcia w mleku jego matki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 20, 'Oto posyłam Anioła przed tobą, aby cię strzegł w drodze i doprowadził do miejsca, które przygotowałem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 21, 'Zważaj na niego i słuchaj jego głosu; nie pobudzaj go do gniewu, bo nie przebaczy waszych przestępstw, gdyż moje imię jest w nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 22, 'Bo jeśli będziesz pilnie słuchać jego głosu i uczynisz wszystko, co powiem, będę wrogiem twoich wrogów i będę dręczyć tych, którzy cię dręczyli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 23, 'Mój Anioł bowiem pójdzie przed tobą i wprowadzi cię do Amorytów, Chetytów, Peryzzytów, Kananejczyków, Chiwwitów i Jebusytów, i wytracę ich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 24, 'Nie będziesz oddawał pokłonu ich bogom ani nie będziesz im służył, ani nie postępuj według ich czynów, ale do gruntu zburz ich i doszczętnie pokrusz ich posągi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 25, 'Będziecie służyć Panu, waszemu Bogu, a on będzie błogosławić twój chleb i twoją wodę; i oddalę od ciebie chorobę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 26, 'Nie będzie w twojej ziemi roniącej ani niepłodnej. Dopełnię liczbę twoich dni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 27, 'Poślę mój strach przed tobą i strwożę wszelki lud, przeciw któremu pójdziesz, i sprawię, że wszyscy twoi wrogowie uciekną przed tobą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 28, 'Poślę też przed tobą szerszenie, które wypędzą Chiwwitów, Kananejczyków i Chetytów sprzed twego oblicza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 29, 'Nie wypędzę ich sprzed twojego oblicza w jednym roku, by ziemia nie zmieniła się w pustynię i nie namnożył się przeciwko tobie dziki zwierz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 30, 'Pomału będę ich wypędzał sprzed twego oblicza, aż się rozmnożysz i posiądziesz ziemię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 31, 'A ustanowię twoje granice od Morza Czerwonego aż do Morza Filistynów, od pustyni aż do rzeki. Oddam bowiem w wasze ręce mieszkańców tej ziemi, a ty wypędzisz ich sprzed twego oblicza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 32, 'Nie zawrzesz przymierza z nimi ani z ich bogami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 33, 'Nie wolno im mieszkać w twojej ziemi, by cię nie doprowadzili do grzechu przeciwko mnie. Jeśli bowiem będziesz służył ich bogom, będzie to dla ciebie sidłem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 1, 'I powiedział do Mojżesza: Wstąpcie do Pana ty i Aaron, Nadab i Abihu oraz siedemdziesięciu ze starszych Izraela i oddajcie pokłon z daleka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 2, 'Tylko sam Mojżesz zbliży się do Pana. Oni zaś nie zbliżą się ani lud nie wstąpi z nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 3, 'Mojżesz przyszedł więc i opowiedział ludowi wszystkie słowa Pana i wszystkie prawa. I cały lud odpowiedział jednym głosem: Wypełnimy wszystkie słowa, które Pan powiedział.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 4, 'Wtedy Mojżesz spisał wszystkie słowa Pana. A kiedy rano wstał, zbudował ołtarz u stóp góry i ustawił dwanaście słupów, według liczby dwunastu pokoleń Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 5, 'I posłał młodzieńców z synów Izraela, i ci ofiarowali całopalenia, i złożyli Panu cielce jako ofiary pojednawcze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 6, 'Potem Mojżesz wziął połowę krwi i wlał do czaszy, a drugą połową pokropił ołtarz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 7, 'Następnie wziął księgę przymierza i czytał ludowi, a oni powiedzieli: Wypełnimy wszystko, co Pan mówił, i będziemy posłuszni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 8, 'Mojżesz wziął też krew i pokropił lud, mówiąc: Oto krew przymierza, które Pan zawarł z wami, według wszystkich tych słów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 9, 'I wstąpili Mojżesz, Aaron, Nadab i Abihu oraz siedemdziesięciu ze starszych Izraela;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 10, 'I widzieli Boga Izraela, a pod jego nogami było jakby dzieło z szafirowego kamienia jak niebo, gdy jest jasne.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 11, 'A na przywódców synów Izraela Pan nie wyciągnął swej ręki, choć widzieli Boga, jedli i pili.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 12, 'Wtedy Pan powiedział do Mojżesza: Wstąp do mnie na górę i bądź tam, a dam ci kamienne tablice, prawo i przykazania, które napisałem, abyś ich nauczał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 13, 'Mojżesz wstał więc wraz z Jozuem, swoim sługą; i Mojżesz wstąpił na górę Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 14, 'A do starszych powiedział: Zostańcie tu, aż wrócimy do was. A oto Aaron i Chur będą z wami. Kto by miał jakąś sprawę, niech idzie do nich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 15, 'Wtedy Mojżesz wstąpił na górę, a obłok zakrył górę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 16, 'I chwała Pana spoczęła na górze Synaj, a obłok okrywał ją przez sześć dni. W siódmym dniu Pan zawołał na Mojżesza spośród obłoku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 17, 'A wygląd chwały Pana w oczach synów Izraela był jak ogień pożerający na szczycie góry.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 18, 'I Mojżesz wszedł w środek obłoku, i wstąpił na górę. A był Mojżesz na górze czterdzieści dni i czterdzieści nocy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 1, 'I Pan powiedział do Mojżesza:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 2, 'Powiedz synom Izraela, aby przynieśli mi dar. Od każdego człowieka, który daje dobrowolnie ze swego serca, zbierzcie dar dla mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 3, 'A to są dary, które zbierzecie od nich: złoto, srebro i miedź;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 4, 'Błękitna tkanina, purpura, karmazyn, bisior i sierść kozia;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 5, 'Skóry baranie farbowane na czerwono, skóry borsucze i drewno akacjowe;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 6, 'Oliwa do oświetlenia, wonności na olejek do namaszczania i na wonne kadzidło;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 7, 'Kamienie onyksowe i kamienie do osadzenia efodu i pektorału.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 8, 'I zbudują mi świątynię, abym mieszkał pośród nich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 9, 'Według wszystkiego, co ci ukażę, według wzoru przybytku i wzoru wszystkich jego naczyń, tak uczynicie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 10, 'Uczynią też arkę z drewna akacjowego. Jej długość będzie na dwa i pół łokcia, jej szerokość – na półtora łokcia, a jej wysokość – na półtora łokcia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 11, 'I pokryjesz ją szczerym złotem, wewnątrz i na zewnątrz pokryjesz ją, a na niej dokoła uczynisz złotą listwę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 12, 'Odlejesz też do niej cztery złote pierścienie, które przymocujesz do czterech jej narożników: dwa pierścienie do jednego jej boku i dwa pierścienie do drugiego jej boku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 13, 'Uczynisz drążki z drewna akacjowego i pokryjesz je złotem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 14, 'I włożysz drążki w pierścienie na bokach arki, aby na nich noszono arkę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 15, 'Drążki te pozostaną w pierścieniach arki; nie będą z niej wyjmowane.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 16, 'W arkę włożysz świadectwo, które ci dam.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 17, 'Uczynisz też przebłagalnię ze szczerego złota. Jej długość będzie na dwa i pół łokcia, a jej szerokość – na półtora łokcia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 18, 'I uczynisz dwa złote cherubiny: wykujesz je ze złota na obu końcach przebłagalni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 19, 'Jednego cherubina uczynisz na jednym końcu, a drugiego cherubina na drugim końcu. Z samej przebłagalni uczynicie cherubiny na obu jej końcach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 20, 'A cherubiny będą mieć skrzydła rozpostarte ku górze, zakrywając swymi skrzydłami przebłagalnię. Ich twarze zaś będą zwrócone ku sobie, twarze cherubinów będą zwrócone ku przebłagalni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 21, 'I położysz przebłagalnię na wierzchu arki, a w arkę włożysz świadectwo, które ci dam.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 22, 'Tam będę się z tobą spotykać i sponad przebłagalni, spomiędzy dwóch cherubinów, którzy są nad arką świadectwa, będę z tobą rozmawiać o wszystkim, co ci rozkażę dla synów Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 23, 'Uczynisz też stół z drewna akacjowego. Jego długość będzie na dwa łokcie, jego szerokość – na jeden łokieć, a jego wysokość – na półtora łokcia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 24, 'I pokryjesz go szczerym złotem, i uczynisz dokoła niego złotą listwę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 25, 'Uczynisz też dokoła niego obramowanie szerokie na cztery palce i złotą listwę dokoła obramowania.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 26, 'Uczynisz też do niego cztery złote pierścienie i przymocujesz je na czterech narożnikach, które są przy jego czterech nogach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 27, 'Przy tym obramowaniu będą pierścienie, przez które przewloką drążki do noszenia stołu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 28, 'A te drążki uczynisz z drewna akacjowego i pokryjesz je złotem, i będzie na nich noszony stół.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 29, 'Uczynisz też jego misy, czasze, przykrycia i kubki do nalewania; wykonasz je ze szczerego złota.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 30, 'I na ten stół nieustannie będziesz kłaść przede mną chleby pokładne.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 31, 'Uczynisz też świecznik ze szczerego złota. Ów świecznik będzie wykuty: jego podstawa, ramiona, kielichy, gałki i kwiaty będą z tej samej bryły.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 32, 'Z jego boków będzie wychodzić sześć ramion: trzy ramiona świecznika z jednego boku i trzy ramiona świecznika z drugiego boku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 33, 'Trzy kielichy na kształt migdału na jednym ramieniu, wraz z gałką i kwiatem; i trzy kielichy na kształt migdału na drugim ramieniu, wraz z gałką i kwiatem. Tak będzie na wszystkich sześciu ramionach wychodzących ze świecznika.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 34, 'Ale na trzonie świecznika będą cztery kielichy na kształt migdału, z gałkami i kwiatami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 35, 'I będzie gałka pod dwoma jego ramionami, także gałka pod następnymi dwoma ramionami i gałka pod innymi dwoma ramionami: tak będzie pod sześcioma ramionami wychodzącymi ze świecznika.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 36, 'Z niego samego będą wychodzić gałki i ramiona, wszystko to w całości będzie wykute ze szczerego złota.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 37, 'Uczynisz też do niego siedem lamp i zapalisz je, aby świeciły w przeciwległą stronę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 38, 'Także jego szczypce i naczynia na popiół mają być ze szczerego złota.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 39, 'Uczynisz go i wszystkie naczynia z talentu szczerego złota.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 40, 'Uważaj, abyś uczynił wszystko według wzoru tego, co ci ukazano na górze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 1, 'Uczynisz też przybytek z dziesięciu zasłon ze skręconego bisioru, z błękitnej tkaniny oraz z purpury i karmazynu, na których wyhaftujesz cherubiny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 2, 'Długość jednej zasłony ma wynosić dwadzieścia osiem łokci, a szerokość jednej zasłony – cztery łokcie. Wszystkie zasłony będą miały jednakowe wymiary.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 3, 'Pięć zasłon będzie spiętych jedna z drugą; także drugie pięć zasłon będzie spiętych jedna z drugą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 4, 'I uczynisz błękitne pętle na brzegu jednej zasłony, gdzie skraje mają się spinać. Uczynisz je też na brzegu drugiej zasłony, gdzie skraje mają się spinać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 5, 'Pięćdziesiąt pętli uczynisz na jednej zasłonie i pięćdziesiąt pętli uczynisz na brzegu drugiej zasłony, w miejscu, gdzie ma być spięta z drugą. Pętle będą jedna naprzeciw drugiej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 6, 'Uczynisz też pięćdziesiąt złotych haczyków i złączysz jedną zasłonę z drugą tymi haczykami. I tak przybytek będzie stanowił jedną całość.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 7, 'Uczynisz też zasłony z koziej sierści do przykrycia przybytku z wierzchu. Uczynisz jedenaście takich zasłon.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 8, 'Długość jednej zasłony ma wynosić trzydzieści łokci, a szerokość jednej zasłony – cztery łokcie. Wszystkie jedenaście zasłon będzie mieć jednakowe wymiary.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 9, 'I zepniesz pięć zasłon osobno, a sześć zasłon osobno. Szóstą zasłonę złożysz we dwoje na przodzie namiotu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 10, 'Uczynisz też pięćdziesiąt pętli na brzegu jednej zasłony, na końcu, gdzie ma być spięta, i pięćdziesiąt pętli z brzegu drugiej zasłony do spinania drugiego brzegu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 11, 'Uczynisz też pięćdziesiąt miedzianych haczyków i włożysz haczyki w pętle, i zepniesz namiot, aby stanowił jedną całość.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 12, 'A część, która zbywa z zasłon namiotu, to jest pozostała połowa zasłony, będzie zwisać z tyłu przybytku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 13, 'A łokieć z jednej i łokieć z drugiej strony, który zbywa z długości zasłon namiotu, będzie wisiał po obu stronach przybytku, po jednej i drugiej, żeby go okrywać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 14, 'Uczynisz też przykrycie na namiot ze skór baranich farbowanych na czerwono i przykrycie ze skór borsuczych na wierzch.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 15, 'Uczynisz też do przybytku prosto stojące deski z drewna akacjowego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 16, 'Długość jednej deski ma wynosić dziesięć łokci, a szerokość jednej deski – półtora łokcia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 17, 'Jedna deska będzie miała dwa czopy, ułożone jeden naprzeciw drugiego. Tak uczynisz przy wszystkich deskach przybytku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 18, 'Uczynisz więc deski do przybytku: dwadzieścia desek na stronę południową, ku południu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 19, 'Uczynisz też czterdzieści srebrnych podstawek pod tych dwadzieścia desek; dwie podstawki pod jedną deskę do dwóch jej czopów, także do drugiej deski dwie podstawki do dwóch jej czopów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 20, 'Na drugim boku przybytku od strony północnej uczynisz dwadzieścia desek.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 21, 'A do nich czterdzieści srebrnych podstawek: dwie podstawki pod jedną deskę i dwie podstawki pod drugą deskę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 22, 'A na zachodnią stronę przybytku uczynisz sześć desek.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 23, 'Uczynisz dwie deski jako narożniki przybytku po obydwu stronach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 24, 'Będą one złączone od spodu, będą także złączone u góry do jednego pierścienia. Tak będzie przy tych obu, będą dla dwóch narożników.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 25, 'I tak będzie osiem desek, a ich srebrnych podstawek szesnaście, dwie podstawki pod jedną deską i dwie podstawki pod drugą deską.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 26, 'Uczynisz też drążki z drewna akacjowego: będzie ich pięć do desek jednej strony przybytku;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 27, 'Pięć także drążków do desek drugiej strony przybytku, a także pięć drążków do desek zachodniej strony przybytku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 28, 'Środkowy drążek w połowie wysokości desek będzie przechodzić od jednego końca do drugiego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 29, 'Deski pokryjesz złotem i uczynisz do nich złote pierścienie, przez które mają przechodzić drążki. Drążki też pokryjesz złotem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 30, 'Wystawisz więc przybytek według wzoru, który ci ukazano na górze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 31, 'Uczynisz też zasłonę z błękitnej tkaniny, purpury, karmazynu i skręconego bisioru; na niej wyhaftujesz cherubiny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 32, 'I zawiesisz ją na czterech słupach z drewna akacjowego pokrytych złotem – ich haki też będą złote – stojących na czterech srebrnych podstawkach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 33, 'A zasłonę zawiesisz na haczykach i wniesiesz za zasłonę arkę świadectwa, a ta zasłona będzie oddzielać wam Miejsce Święte od Najświętszego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 34, 'Położysz też przebłagalnię na arce świadectwa w Miejscu Najświętszym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 35, 'A przed zasłoną postawisz stół, a naprzeciw stołu, po południowej stronie przybytku – świecznik, a stół postawisz po stronie północnej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 36, 'Uczynisz też do wejścia namiotu zasłonę z błękitnej tkaniny, purpury, karmazynu i skręconego bisioru, haftowaną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 37, 'A do tej zasłony uczynisz pięć słupów z drewna akacjowego, które pokryjesz złotem, i ich haki będą złote. I ulejesz do nich pięć miedzianych podstawek.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 1, 'Uczynisz też ołtarz z drewna akacjowego, długi na pięć łokci i szeroki na pięć łokci. Ołtarz będzie kwadratowy i wysoki na trzy łokcie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 2, 'I uczynisz rogi na jego czterech narożnikach; jego rogi będą z tego samego. I pokryjesz go miedzią.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 3, 'Uczynisz też do niego kociołki do zsypywania popiołu oraz szufle, miednice, widełki i łopaty na rozżarzone węgle. Wszystkie naczynia do niego uczynisz z miedzi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 4, 'Uczynisz też do niego miedzianą kratę na kształt sieci, a na tej kracie, na czterech jej narożnikach, uczynisz cztery miedziane pierścienie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 5, 'I umieścisz ją u dołu pod obramowaniem ołtarza, tak aby krata sięgała do połowy ołtarza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 6, 'Uczynisz też drążki do ołtarza, drążki z drewna akacjowego, i pokryjesz je miedzią.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 7, 'Drążki te będą włożone w pierścienie i będą one na obydwu stronach ołtarza, aby można go było nosić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 8, 'Uczynisz go z desek, aby był pusty wewnątrz. Niech go uczynią tak, jak ci pokazano na górze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 9, 'Uczynisz też dziedziniec przybytku. Na południu po prawej stronie zasłony dziedzińca będą ze skręconego bisioru o długości stu łokci na jedną stronę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 10, 'Do tego dwadzieścia słupów i dwadzieścia miedzianych podstawek. Haczyki na słupach i ich klamry będą ze srebra.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 11, 'Podobnie wzdłuż strony północnej będą zasłony o długości stu łokci, do tego dwadzieścia słupów i dwadzieścia miedzianych podstawek. Haczyki na słupach i ich klamry będą ze srebra.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 12, 'A na szerokości dziedzińca od strony zachodniej będą zasłony na pięćdziesiąt łokci, a do tego dziesięć słupów i dziesięć podstawek.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 13, 'Szerokość dziedzińca z przodu, po stronie wschodniej, będzie wynosić pięćdziesiąt łokci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 14, 'Po jednej stronie wejścia będą zasłony na piętnaście łokci, a do tego trzy słupy i trzy podstawki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 15, 'Po drugiej stronie będą zasłony na piętnaście łokci, a do tego trzy słupy i trzy podstawki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 16, 'A do wejścia dziedzińca będzie zasłona na dwadzieścia łokci z błękitnej tkaniny, z purpury i karmazynu oraz skręconego bisioru, haftowana. Do tego cztery słupy i cztery podstawki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 17, 'Wszystkie słupy dokoła dziedzińca będą miały srebrne klamry. Ich haczyki będą ze srebra, a ich podstawki – z miedzi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 18, 'Długość dziedzińca będzie wynosić sto łokci, a szerokość – pięćdziesiąt, wszędzie jednakowa, a wysokość – pięć łokci, zasłony będą ze skręconego bisioru, jej podstawki zaś z miedzi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 19, 'Wszystkie naczynia przybytku do wszelkiej służby w nim i wszystkie jego kołki, i wszystkie kołki dziedzińca będą z miedzi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 20, 'Rozkażesz synom Izraela, aby przynieśli do ciebie czystą, wytłoczoną oliwę do oświetlenia, aby lampy zawsze się paliły.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 21, 'W Namiocie Zgromadzenia przed zasłoną, za którą jest arka świadectwa, Aaron i jego synowie będą je stawiać przed Panem od wieczora aż do poranka. Będzie to wieczna ustawa wśród ich potomków dla synów Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 1, 'Przywołaj do siebie twego brata Aarona i wraz z nim jego synów, spośród synów Izraela, aby sprawowali dla mnie urząd kapłański: Aarona, Nadaba i Abihu, Eleazara i Itamara, synów Aarona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 2, 'Uczynisz święte szaty dla twego brata Aarona, na cześć i na ozdobę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 3, 'Porozmawiasz też ze wszystkimi zdolnymi rzemieślnikami, których napełniłem duchem mądrości, aby wykonali szaty dla Aarona na jego poświęcenie, aby mi sprawował urząd kapłański.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 4, 'Oto szaty, które wykonają: pektorał, efod, ornat, tunika haftowana, mitra i pas. I uczynią te święte szaty dla twego brata Aarona i jego synów, aby mi sprawowali urząd kapłański.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 5, 'I wezmą złoto, błękitną tkaninę, purpurę, karmazyn i bisior.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 6, 'I uczynią efod ze złota, błękitnej tkaniny, purpury, karmazynu i skręconego bisioru, haftowany.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 7, 'Będzie on miał dwa naramienniki zszyte na dwóch końcach i tak będą razem połączone.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 8, 'A pas, którym będzie przepasany efod, zostanie podobnie uczyniony ze złota, błękitnej tkaniny, purpury, karmazynu i skręconego bisioru.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 9, 'I weźmiesz dwa kamienie onyksu i wyryjesz na nich imiona synów Izraela;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 10, 'Sześć ich imion na jednym kamieniu i sześć pozostałych imion na drugim kamieniu, według kolejności ich narodzenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 11, 'Tak jak rytownik, który wykuwa pieczęć, wyryjesz na obu kamieniach imiona synów Izraela i osadzisz je w złotych oprawach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 12, 'I umieścisz te dwa kamienie na naramiennikach efodu jako kamienie pamiątkowe dla synów Izraela. I Aaron będzie nosić ich imiona przed Panem na obu swych ramionach na pamiątkę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 13, 'Uczynisz też złote oprawy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 14, 'A także dwa łańcuszki ze szczerego złota. Upleciesz je i przymocujesz te plecione łańcuszki do opraw.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 15, 'Uczynisz też pektorał wyrokowania, wyhaftowany, podobnie jak efod. Uczynisz go ze złota, błękitnej tkaniny, purpury, karmazynu i skręconego bisioru.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 16, 'Będzie kwadratowy, złożony we dwoje, na piędź długości i na piędź szerokości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 17, 'I uczynisz w nim oprawy dla kamieni, cztery rzędy kamieni, w tym porządku: karneol, topaz i szmaragd w pierwszym rzędzie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 18, 'W drugim zaś rzędzie: karbunkuł, szafir i diament;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 19, 'W trzecim rzędzie: hiacynt, agat i ametyst;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 20, 'W czwartym rzędzie: beryl, onyks i jaspis. Będą one osadzone w złotych oprawach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 21, 'A tych kamieni z imionami synów Izraela będzie dwanaście, według ich imion. Będą ryte jak na pieczęci, każdy z własnym imieniem, według dwunastu pokoleń.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 22, 'Uczynisz do pektorału łańcuszki plecione ze szczerego złota.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 23, 'Do pektorału uczynisz też dwa złote pierścienie i przymocujesz te dwa pierścienie do obu jego rogów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 24, 'I przewleczesz dwa złote łańcuszki przez oba pierścienie na rogach pektorału.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 25, 'Drugie zaś końce obu łańcuszków przymocujesz do dwóch opraw i przytwierdzisz z przodu do naramienników efodu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 26, 'Uczynisz też dwa złote pierścienie, które przymocujesz do dwóch rogów pektorału na wewnętrznym brzegu, który jest od strony efodu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 27, 'Do tego uczynisz kolejne dwa złote pierścienie, które przymocujesz do dwóch stron efodu u dołu, naprzeciwko jego połączenia, powyżej pasa efodu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 28, 'Te pierścienie zwiążą pektorał z pierścieniami efodu sznurem z błękitnej tkaniny, aby był nad pasem efodu, żeby pektorał nie odstawał od efodu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 29, 'I Aaron będzie nosił imiona synów Izraela na pektorale wyrokowania, na swych piersiach, gdy będzie wchodził do Miejsca Świętego, na wieczną pamiątkę przed Panem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 30, 'Włożysz też do pektorału wyrokowania Urim i Tummim, które będą na sercu Aarona, gdy będzie wchodził przed Pana. I Aaron nieustannie będzie nosił na sercu przed Panem sąd synów Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 31, 'Uczynisz też ornat pod efod, cały z błękitnej tkaniny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 32, 'A na wierzchu w środku będzie miał otwór. Dokoła otworu będzie pleciona obwódka na wzór pancerza, aby się nie rozdzierał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 33, 'Uczynisz też u jego dołu jabłka granatu z błękitnej tkaniny, purpury i karmazynu dokoła brzegu, a między nimi dokoła złote dzwonki;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 34, 'Złoty dzwonek i jabłko granatu i znowu złoty dzwonek i jabłko granatu, dokoła dolnego brzegu ornatu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 35, 'I Aaron będzie to miał na sobie podczas służby, aby słychać było jego dźwięk, gdy będzie wchodził do Miejsca Świętego przed Pana i gdy będzie wychodzić, żeby nie umarł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 36, 'Uczynisz też blaszkę ze szczerego złota, a na niej wyryjesz jak na pieczęci: Świętość Panu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 37, 'Przymocujesz ją do sznura z błękitnej tkaniny i będzie na mitrze, będzie na przodzie mitry.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 38, 'I będzie na czole Aarona, aby nosił Aaron nieprawość poświęconych rzeczy, które synowie Izraela poświęcać będą przy wszystkich świętych darach. Będzie nieustannie na jego czole, aby im zjednał łaskę u Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 39, 'Utkasz tunikę z bisioru, mitrę także uczynisz z bisioru, wyhaftujesz też pas.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 40, 'Również dla synów Aarona wykonasz szaty, też pasy i mitry uczynisz im na cześć i na ozdobę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 41, 'I ubierzesz w nie twego brata Aarona i wraz z nim jego synów. Namaścisz ich, poświęcisz i uświęcisz, aby mi sprawowali urząd kapłański.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 42, 'Wykonasz im też lniane spodnie dla zakrycia nagości ciała. Będą od bioder aż po uda.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 43, 'A będą one na Aaronie i na jego synach, gdy będą wchodzić do Namiotu Zgromadzenia lub gdy będą przystępować do ołtarza, aby służyć w Miejscu Świętym, aby nie ściągnęli na siebie winy i nie pomarli. Będzie to wieczna ustawa dla niego i jego potomstwa po nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 1, 'Oto co masz uczynić, aby poświęcić ich do sprawowania mi urzędu kapłańskiego: Weź jednego młodego cielca i dwa barany bez skazy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 2, 'I przaśne chleby, przaśne placki zaprawione oliwą i przaśne podpłomyki posmarowane oliwą. Uczynisz je z wybornej mąki pszennej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 3, 'Włożysz je do jednego kosza i przyniesiesz je w tym koszu z cielcem i z dwoma baranami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 4, 'Aaronowi i jego synom każesz zbliżyć się do wejścia do Namiotu Zgromadzenia i obmyjesz ich wodą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 5, 'Potem weźmiesz szaty i ubierzesz Aarona w tunikę, w ornat pod efod, w efod i pektorał i opaszesz go pasem efodu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 6, 'I włożysz mu na głowę mitrę, a na mitrę wstawisz świętą koronę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 7, 'Następnie weźmiesz olejek do namaszczenia i wylejesz na jego głowę, i namaścisz go.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 8, 'Potem każesz się przybliżyć jego synom i ubierzesz ich w szaty;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 9, 'I przepaszesz ich pasem, Aarona i jego synów, i włożysz na nich mitry, i będzie do nich należało kapłaństwo na mocy wiecznej ustawy. Poświęcisz też Aarona i jego synów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 10, 'Przyprowadzisz też cielca przed Namiot Zgromadzenia i Aaron oraz jego synowie włożą swoje ręce na głowę cielca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 11, 'I zabijesz cielca przed Panem u wejścia do Namiotu Zgromadzenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 12, 'Potem weźmiesz krew cielca i pomażesz swym palcem rogi ołtarza, a resztkę krwi wylejesz u podnóża ołtarza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 13, 'Weźmiesz też cały tłuszcz okrywający wnętrzności, płat wątroby i obie nerki z tłuszczem na nich i spalisz to na ołtarzu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 14, 'A mięso cielca, jego skórę i jego odchody spalisz w ogniu za obozem, bo to jest ofiara za grzech.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 15, 'Weźmiesz także jednego barana, na którego głowę Aaron i jego synowie włożą swoje ręce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 16, 'Następnie zabijesz tego barana i weźmiesz jego krew, i pokropisz dokoła wierzch ołtarza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 17, 'Barana porąbiesz na części, opłuczesz jego trzewia i nogi i położysz je na jego częściach i na jego głowie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 18, 'I spalisz całego tego barana na ołtarzu. Jest to całopalenie dla Pana, miła woń, ofiara spalona dla Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 19, 'Potem weźmiesz drugiego barana, a Aaron i jego synowie włożą swoje ręce na głowę barana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 20, 'Wtedy zabijesz tego barana, weźmiesz nieco z jego krwi i posmarujesz koniec ucha Aarona, końce prawych uszu jego synów i wielkie palce ich prawych rąk, także wielkie palce ich prawych stóp, i pokropisz tą krwią ołtarz dokoła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 21, 'Weźmiesz też nieco z krwi, która jest na ołtarzu, także z olejku do namaszczenia, i pokropisz Aarona, jego szaty oraz jego synów i szaty jego synów wraz z nim. Tak zostanie poświęcony on i jego szaty, a wraz z nim jego synowie i szaty jego synów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 22, 'Potem weźmiesz z barana łój, ogon, tłuszcz okrywający wnętrzności, płat wątroby, obie nerki, łój, który jest na nich, i prawą łopatkę, bo to jest baran poświęcenia;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 23, 'I jeden bochen chleba, jeden placek chlebowy na oliwie i jeden podpłomyk z kosza przaśników, który jest przed Panem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 24, 'To wszystko położysz na ręce Aarona i na ręce jego synów i będziesz tym kołysać jako ofiarą kołysania przed Panem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 25, 'Potem weźmiesz to z ich rąk i spalisz na ołtarzu jako całopalenie, na miłą woń przed Panem. Jest to ofiara spalona dla Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 26, 'Weźmiesz też pierś barana poświęcenia Aarona i będziesz ją kołysać jako ofiarą kołysania przed Panem. A to będzie twój dział.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 27, 'Poświęcisz też pierś kołysania i łopatkę wzniesienia, którą kołysano i którą wznoszono, z barana poświęcenia dla Aarona i dla jego synów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 28, 'A będzie to dla Aarona i jego synów od synów Izraela na mocy wiecznej ustawy, gdyż jest to ofiara wzniesienia. Ofiara wzniesienia będzie wzięta od synów Izraela z ich ofiar pojednawczych. To będzie ich ofiara wzniesienia dla Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 29, 'A święte szaty Aarona będą należeć po nim do jego synów, aby byli w nich namaszczeni i poświęceni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 30, 'Siedem dni będzie w nich chodził kapłan, jego syn, który zajmie jego miejsce, gdy będzie wchodził do Namiotu Zgromadzenia, aby służyć w Miejscu Świętym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 31, 'Weźmiesz też barana poświęcenia i ugotujesz jego mięso w miejscu świętym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 32, 'Aaron i jego synowie będą jeść mięso tego barana i chleb, który jest w koszu, przy wejściu do Namiotu Zgromadzenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 33, 'Będą jeść to, czym dokonano przebłagania, gdy ich poświęcono i uświęcono. Obcy zaś nie będzie z tego jadł, bo jest to rzecz święta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 34, 'A jeśli zostałoby coś z mięsa poświęcenia lub z chleba aż do poranka, spalisz resztki w ogniu. Nie wolno tego jeść, bo jest to rzecz święta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 35, 'Tak więc postąpisz z Aaronem i jego synami według wszystkiego, co ci przykazałem. Przez siedem dni będziesz ich poświęcać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 36, 'Każdego dnia złożysz cielca na ofiarę za grzech dla przebłagania. Oczyścisz ołtarz, dokonując na nim przebłagania, i namaścisz go, aby go poświęcić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 37, 'Siedem dni będziesz dokonywał przebłagania za ołtarz i poświęcisz go, i będzie to ołtarz najświętszy. Ktokolwiek dotknie się ołtarza, musi być poświęcony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 38, 'Oto co masz składać na ołtarzu: dwa roczne baranki, codziennie i ustawicznie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 39, 'Jednego baranka złożysz w ofierze rano, a drugiego baranka złożysz w ofierze wieczorem;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 40, 'I wraz z pierwszym barankiem dziesiątą część efy mąki pszennej zmieszanej z czwartą częścią hinu wytłoczonej oliwy, a na ofiarę z płynów czwartą część hinu wina.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 41, 'A drugiego baranka złożysz w ofierze wieczorem według obrzędu porannej ofiary i według ofiary z płynów, jako miłą woń i spaloną ofiarę dla Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 42, 'To będzie nieustanne całopalenie przez wszystkie pokolenia u wejścia do Namiotu Zgromadzenia przed Panem, gdzie będę się z wami spotykać, aby tam z tobą rozmawiać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 43, 'Tam też będę się spotykać z synami Izraela i to miejsce zostanie poświęcone moją chwałą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 44, 'Bo poświęcę Namiot Zgromadzenia i ołtarz, poświęcę też Aarona i jego synów, aby mi sprawowali urząd kapłański.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 45, 'I będę mieszkał pośród synów Izraela, i będę ich Bogiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 46, 'I poznają, że ja jestem Pan, ich Bóg, który wyprowadził ich z ziemi Egiptu, aby mieszkać pośród nich, ja, Pan, ich Bóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 1, 'Uczynisz też ołtarz do spalania kadzidła. Uczynisz go z drewna akacjowego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 2, 'Na łokieć długi i na łokieć szeroki, będzie kwadratowy, na dwa łokcie wysoki. Jego rogi będą z tego samego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 3, 'Pokryjesz go szczerym złotem, jego wierzch i ściany wokoło oraz rogi. Uczynisz też dokoła niego złotą listwę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 4, 'Pod listwą, na dwóch jego narożnikach, po obu jego stronach, uczynisz też dwa złote pierścienie, a przez nie przewleczesz drążki, aby był na nich noszony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 5, 'Drążki te uczynisz z drewna akacjowego i pokryjesz je złotem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 6, 'Następnie postawisz go przed zasłoną, za którą jest arka świadectwa, przed przebłagalnią, która jest nad świadectwem, gdzie będę się z tobą spotykać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 7, 'I każdego poranka Aaron będzie spalał na nim wonne kadzidło. Gdy będzie przygotowywał lampy, będzie je spalał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 8, 'Także wieczorem, gdy Aaron rozpali lampy, będzie spalał kadzidło, będzie to ustawiczne kadzenie przed Panem przez wszystkie wasze pokolenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 9, 'Nie składajcie na nim obcego kadzidła ani całopalenia, ani ofiary pokarmowej, nie będziecie też na nim składać ofiary z płynów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 10, 'Tylko raz do roku Aaron dokona na jego rogach przebłagania krwią z ofiary na przebłaganie grzechu. Raz do roku odprawi przebłaganie na nim przez wszystkie wasze pokolenia. Będzie to najświętsza rzecz dla Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 11, 'Potem Pan powiedział do Mojżesza:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 12, 'Gdy przeliczysz synów Izraela podlegających spisowi, każdy da Panu okup za swą duszę podczas spisu, aby nie dotknęła ich plaga, gdy będą zliczeni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 13, 'To będzie dawać każdy, kto podlega spisowi: pół sykla według sykla świątynnego – sykl to dwadzieścia ger. Pół sykla wyniesie więc ofiara dla Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 14, 'Każdy podległy spisowi, od dwudziestego roku życia wzwyż, odda Panu ofiarę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 15, 'Bogaty nie da więcej, a ubogi nie da mniej niż pół sykla, gdy będą dawać Panu ofiarę na przebłaganie za swoje dusze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 16, 'A weźmiesz pieniądze przebłagania od synów Izraela i dasz je na służbę Namiotu Zgromadzenia. Będzie to dla synów Izraela pamiątką przed Panem, na przebłaganie za wasze dusze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 17, 'Potem Pan powiedział do Mojżesza:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 18, 'Uczynisz też miedzianą kadź do obmywania i do niej miedzianą podstawę i postawisz ją między Namiotem Zgromadzenia a ołtarzem, i nalejesz do niej wody.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 19, 'Aaron i jego synowie będą w niej obmywać swoje ręce i nogi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 20, 'Gdy będą wchodzić do Namiotu Zgromadzenia, obmyją się wodą, aby nie pomarli. Podobnie gdy będą przystępować do ołtarza, aby służyć i spalać ofiarę ogniową dla Pana;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 21, 'Obmyją swoje ręce i nogi, aby nie pomarli. Będzie to dla nich wieczną ustawą, dla niego i jego potomstwa, przez wszystkie ich pokolenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 22, 'Pan powiedział jeszcze do Mojżesza:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 23, 'Weź sobie też najlepsze wonności: pięćset syklów najczystszej mirry, połowę tego, czyli dwieście pięćdziesiąt syklów, wonnego cynamonu i dwieście pięćdziesiąt syklów ziela tataraku;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 24, 'Pięćset syklów kasji według sykla świątynnego i hin oliwy z oliwek.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 25, 'Uczynisz z tego święty olejek do namaszczenia, wyborną maść, dzieło zielarza. Będzie to święty olejek do namaszczenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 26, 'Namaścisz nim Namiot Zgromadzenia i arkę świadectwa;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 27, 'I stół wraz ze wszystkimi jego naczyniami, świecznik i jego przybory oraz ołtarz kadzenia;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 28, 'Ołtarz do całopalenia ze wszystkimi jego naczyniami i kadź z jej podstawą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 29, 'I poświęcisz je, aby stały się najświętsze. Ktokolwiek się ich dotknie, musi być poświęcony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 30, 'Namaścisz też Aarona i jego synów i poświęcisz ich, aby mi sprawowali urząd kapłański.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 31, 'Synom Izraela powiesz: To będzie dla mnie świętym olejkiem namaszczenia przez wszystkie wasze pokolenia;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 32, 'Nie wolno go wylewać na ciało człowieka i nie wolno sporządzić innego o podobnym składzie, bo jest święty i dla was będzie święty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 33, 'Ktokolwiek sporządzi podobny i namaści nim kogoś obcego, będzie wykluczony ze swego ludu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 34, 'I Pan powiedział do Mojżesza: Weź sobie wonności: balsam, onychę, wonne galbanum i czyste kadzidło, wszystko o takiej samej wadze;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 35, 'I uczynisz z tego wonne kadzidło, dzieło zielarza, dobrze mieszane, czyste i święte.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 36, 'Część z niego zetrzesz na proszek i będziesz go kłaść przed świadectwem w Namiocie Zgromadzenia, gdzie będę się z tobą spotykać. Będzie to najświętsze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 37, 'Kadzideł, które sporządzicie według tego składu, nie sporządzicie dla siebie. Będzie to święte dla Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 38, 'Ktokolwiek by uczynił coś podobnego, aby rozkoszować się jego wonią, będzie wykluczony ze swego ludu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 1, 'Potem Pan powiedział do Mojżesza:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 2, 'Oto powołałem po imieniu Besalela, syna Uriego, syna Chura, z pokolenia Judy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 3, 'I napełniłem go Duchem Bożym, mądrością, rozumem, wiedzą i znajomością we wszelkim rzemiośle;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 4, 'Aby umiejętnie obmyślał projekty, do wyrobu ze złota, srebra i miedzi;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 5, 'Do obrabiania kamieni do oprawy i do ciosania drewna, aby wykonał wszelkie rodzaje dzieła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 6, 'Oto dałem mu Oholiaba, syna Achisamaka, z pokolenia Dana. Wlałem też mądrość w serce każdego uzdolnionego, aby uczynili wszystko, co ci przykazałem:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 7, 'Namiot Zgromadzenia, arkę świadectwa, przebłagalnię, która ma być nad nią, i wszystkie sprzęty namiotu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 8, 'Stół i naczynia do niego, szczerozłoty świecznik ze wszystkimi naczyniami do niego i ołtarz kadzenia;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 9, 'Ołtarz całopalenia ze wszystkimi naczyniami do niego i kadź wraz z jej podstawą;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 10, 'Szaty do służby, święte szaty dla Aarona, kapłana, i szaty dla jego synów do sprawowania kapłaństwa;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 11, 'Olejek namaszczenia i wonne kadzidło do Miejsca Świętego. Wykonają według wszystkiego, co ci przykazałem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 12, 'Potem Pan powiedział do Mojżesza:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 13, 'Powiedz też synom Izraela: Koniecznie macie przestrzegać moich szabatów, bo to jest znak między mną a wami przez wszystkie wasze pokolenia, abyście wiedzieli, że ja jestem Pan, który was uświęca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 14, 'Przestrzegajcie więc szabatu, gdyż jest on dla was święty. Kto by go naruszył, poniesie śmierć. Każdy bowiem, kto wykonuje pracę w tym dniu, zostanie wytracony spośród swego ludu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 15, 'Przez sześć dni będzie się wykonywać pracę, ale siódmy dzień jest szabatem odpoczynku, świętym dla Pana. Ktokolwiek wykona pracę w dniu szabatu, poniesie śmierć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 16, 'Dlatego synowie Izraela będą przestrzegać szabatu, zachowując szabat przez wszystkie pokolenia jako wieczną ustawę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 17, 'Jest on wiecznym znakiem między mną a synami Izraela, bo w sześć dni Pan uczynił niebo i ziemię, a siódmego dnia przestał i odpoczął.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 18, 'A gdy dokończył rozmowę z Mojżeszem na górze Synaj, Pan dał mu dwie tablice świadectwa, tablice kamienne napisane palcem Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 1, 'A gdy lud widział, że Mojżesz opóźnia swoje zejście z góry, zebrał się przed Aaronem i mówił do niego: Wstań, zrób nam bogów, którzy by szli przed nami, bo nie wiemy, co się stało z Mojżeszem, tym mężem, który nas wyprowadził z ziemi Egiptu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 2, 'Wtedy Aaron im powiedział: Zdejmijcie złote kolczyki, które są w uszach waszych żon, waszych synów i córek, i przynieście do mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 3, 'I cały lud pozdejmował złote kolczyki, które były w ich uszach, i zanieśli je do Aarona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 4, 'Gdy on przyjął je z ich rąk, ukształtował je rylcem i uczynił z nich odlanego cielca. I powiedzieli: Oto są twoi bogowie, Izraelu, którzy cię wyprowadzili z ziemi Egiptu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 5, 'Widząc to, Aaron zbudował przed nim ołtarz i zawołał: Jutro będzie święto Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 6, 'A nazajutrz wstali wcześnie rano, ofiarowali całopalenia i przynieśli ofiary pojednawcze. I lud usiadł, aby jeść i pić, i wstał, aby się bawić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 7, 'Wtedy Pan powiedział do Mojżesza: Idź, zejdź na dół, bo zepsuł się twój lud, który wyprowadziłeś z ziemi Egiptu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 8, 'Szybko zboczyli z drogi, którą im przykazałem. Zrobili sobie odlanego cielca, oddali mu pokłon i złożyli mu ofiary, mówiąc: Oto są twoi bogowie, Izraelu, którzy cię wyprowadzili z ziemi Egiptu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 9, 'Pan mówił dalej do Mojżesza: Widziałem ten lud, a oto jest on ludem twardego karku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 10, 'Teraz więc zostaw mnie, aby się rozpalił mój gniew na nich i abym ich zgładził, a z ciebie uczynię wielki naród.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 11, 'I Mojżesz modlił się do Pana, swego Boga, i powiedział: Dlaczego, Panie, rozpala się twój gniew przeciwko twemu ludowi, który wyprowadziłeś z ziemi Egiptu wielką mocą i potężną ręką?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 12, 'Dlaczego Egipcjanie mieliby mówić: Wyprowadził ich ku złemu, aby ich pozabijać w górach i aby zgładzić ich z powierzchni ziemi? Odwróć się od zapalczywości twojego gniewu i żałuj nieszczęścia, jakie chcesz zesłać na twój lud.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 13, 'Wspomnij na Abrahama, Izaaka i Izraela, twoje sługi, którym przysiągłeś na samego siebie i mówiłeś do nich: Rozmnożę wasze potomstwo jak gwiazdy na niebie i całą tę ziemię, o której mówiłem, dam waszemu potomstwu i odziedziczą ją na wieki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 14, 'I Pan żałował nieszczęścia, które miał zesłać na swój lud.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 15, 'Mojżesz odwrócił się więc i zszedł z góry, mając w ręku dwie tablice świadectwa, tablice zapisane po obu stronach. Były zapisane i na jednej, i na drugiej stronie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 16, 'Tablice te były dziełem Boga, a pismo też było pismem Boga wyrytym na tablicach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 17, 'Gdy Jozue usłyszał głos wołającego ludu, powiedział do Mojżesza: Odgłosy bitwy w obozie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 18, 'On odpowiedział: Nie jest to głos zwyciężających ani głos pokonanych. Słyszę raczej głos śpiewających.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 19, 'Gdy się przybliżył do obozu, zobaczył cielca i tańce. Mojżesz wówczas rozgniewał się bardzo, rzucił z rąk tablice i stłukł je pod górą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 20, 'Wziął też cielca, którego zrobili, spalił go w ogniu, skruszył na proch, wysypał na wodę i kazał ją pić synom Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 21, 'Potem Mojżesz powiedział do Aarona: Cóż ci ten lud zrobił, że sprowadziłeś na niego tak wielki grzech?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 22, 'Aaron odpowiedział: Niech się nie rozpala gniew mego pana. Ty znasz ten lud i wiesz, jak jest skłonny do zła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 23, 'Mówili mi bowiem: Zrób nam bogów, którzy by szli przed nami, gdyż nie wiemy, co się stało z Mojżeszem, tym mężem, który nas wyprowadził z ziemi Egiptu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 24, 'I odpowiedziałem im: Kto ma złoto, niech je zdejmie z siebie. Dali mi je i wrzuciłem je w ogień, i tak powstał ten cielec.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 25, 'Gdy Mojżesz widział obnażony lud, bo Aaron uczynił go nagim ku jego hańbie wobec jego wrogów;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 26, 'Wtedy Mojżesz stanął w bramie obozu i powiedział: Kto jest za Panem, niech przystąpi do mnie. I zebrali się przy nim wszyscy synowie Lewiego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 27, 'I powiedział do nich: Tak mówi Pan, Bóg Izraela: Niech każdy przypasze swój miecz do swojego boku. Przejdźcie przez obóz tam i z powrotem, od jednej bramy do drugiej, i zabijajcie każdy swego brata i każdy swego przyjaciela, i każdy swego bliźniego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 28, 'I synowie Lewiego postąpili według słowa Mojżesza. Tego dnia poległo z ludu około trzech tysięcy mężczyzn.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 29, 'Bo Mojżesz powiedział: Poświęćcie dziś Panu swoje ręce, każdy na swego syna i na swego brata, aby dał wam dziś błogosławieństwo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 30, 'Nazajutrz zaś Mojżesz powiedział do ludu: Popełniliście wielki grzech. Wstąpię teraz do Pana, może go przebłagam za wasz grzech.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 31, 'Mojżesz więc wrócił do Pana i powiedział: Proszę, ten lud popełnił wielki grzech, bo zrobił sobie bogów ze złota.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 32, 'Teraz jednak przebacz ich grzech, a jeśli nie, wymaż mnie, proszę, z twojej księgi, którą napisałeś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 33, 'Pan powiedział do Mojżesza: Tego wymażę z mojej księgi, kto zgrzeszył przeciwko mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 34, 'Idź teraz, prowadź ten lud, gdzie ci rozkazałem. Oto mój Anioł pójdzie przed tobą. Ale w dniu mego nawiedzenia ich też nawiedzę za ich grzech.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 35, 'Pan ukarał więc lud za to, że zrobił cielca, którego sporządził Aaron.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 1, 'Potem Pan mówił do Mojżesza: Idź, wyrusz stąd, ty i lud, który wyprowadziłeś z ziemi Egiptu, do ziemi, którą przysiągłem Abrahamowi, Izaakowi i Jakubowi, mówiąc: Dam ją twemu potomstwu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 2, 'Poślę przed tobą Anioła i wyrzucę Kananejczyka, Amorytę, Chetytę, Peryzzytę, Chiwwitę i Jebusytę;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 3, 'Do ziemi opływającej mlekiem i miodem. Lecz sam nie pójdę z tobą, bo jesteś ludem twardego karku, bym cię w drodze nie wytracił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 4, 'Gdy lud usłyszał te złe wieści, zasmucił się i nikt nie włożył na siebie swoich ozdób.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 5, 'Pan bowiem powiedział do Mojżesza: Powiedz synom Izraela: Jesteście ludem twardego karku. Przyjdę niespodziewanie pośród ciebie i wytracę cię. Teraz więc zdejmij z siebie swoje ozdoby, abym wiedział, co mam ci uczynić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 6, 'I synowie Izraela zdjęli swoje ozdoby przy górze Horeb.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 7, 'A Mojżesz wziął namiot i rozbił go poza obozem, z dala od obozu, i nazwał go Namiotem Zgromadzenia. Każdy, kto chciał się poradzić Pana, wychodził do Namiotu Zgromadzenia, który był poza obozem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 8, 'A gdy Mojżesz wychodził do namiotu, cały lud powstawał i każdy stał u wejścia do swego namiotu, i patrzył na Mojżesza, aż wszedł do namiotu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 9, 'Gdy Mojżesz wchodził do namiotu, słup obłoku zstępował i stawał u wejścia do namiotu, i Pan rozmawiał z Mojżeszem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 10, 'A cały lud widział słup obłoku stojący u wejścia do namiotu. Wtedy cały lud powstawał i oddawał pokłon, każdy u wejścia do swego namiotu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 11, 'I Pan rozmawiał z Mojżeszem twarzą w twarz, jak człowiek rozmawia ze swoim przyjacielem. Potem Mojżesz wracał do obozu, a jego sługa Jozue, syn Nuna, młodzieniec, nie opuszczał namiotu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 12, 'I Mojżesz powiedział do Pana: Oto mówisz mi: Prowadź ten lud, a nie oznajmiłeś mi, kogo poślesz ze mną. Ponadto powiedziałeś: Znam cię po imieniu, znalazłeś też łaskę w moich oczach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 13, 'Teraz więc, jeśli znalazłem łaskę w twoich oczach, ukaż mi, proszę, twoją drogę, żebym cię poznał i żebym znalazł łaskę w twoich oczach. Zważ także, że ten naród jest twoim ludem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 14, 'I Pan odpowiedział: Moje oblicze pójdzie przed tobą i dam ci odpoczynek.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 15, 'Mojżesz powiedział do niego: Jeśli twoje oblicze nie pójdzie z nami, nie wyprowadzaj nas stąd.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 16, 'Po czym bowiem będzie można poznać, że ja i twój lud znaleźliśmy łaskę w twoich oczach? Czy nie po tym, że pójdziesz z nami? W ten sposób ja i twój lud będziemy wyróżnieni spośród wszystkich ludów, które są na ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 17, 'I Pan powiedział do Mojżesza: Uczynię także to, o czym mówiłeś, bo znalazłeś łaskę w moich oczach i znam cię po imieniu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 18, 'Mojżesz powiedział też: Ukaż mi, proszę, twoją chwałę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 19, 'A on odpowiedział: Sprawię, że cała moja dobroć przejdzie przed twoją twarzą, i wypowiem imię Pana przed tobą. Zmiłuję się, nad kim się zmiłuję, i zlituję się, nad kim się zlituję.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 20, 'I dodał: Nie będziesz mógł widzieć mego oblicza, bo nie może człowiek ujrzeć mnie i pozostać przy życiu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 21, 'Pan mówił dalej: Oto miejsce przy mnie, staniesz na skale.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 22, 'A gdy będzie przechodzić moja chwała, postawię cię w rozpadlinie skalnej i zakryję cię swoją dłonią, aż przejdę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 23, 'Potem odejmę dłoń i ujrzysz mnie od tyłu, ale moje oblicze nie będzie widziane.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 1, 'I Pan powiedział do Mojżesza: Wyciosaj sobie dwie kamienne tablice, podobne do pierwszych, a napiszę na tych tablicach słowa, które były na pierwszych tablicach, które stłukłeś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 2, 'A bądź gotów jutro rano i wstąp rankiem na górę Synaj; staniesz przede mną na szczycie tej góry.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 3, 'Ale niech nikt nie wchodzi z tobą, niech nikt też nie będzie widziany na całej górze; również owce i woły niech się nie pasą naprzeciwko tej góry.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 4, 'Mojżesz wyciosał więc dwie kamienne tablice podobne do pierwszych, a gdy wstał rano, wstąpił na górę Synaj, jak Pan mu rozkazał, i wziął w ręce dwie kamienne tablice.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 5, 'I Pan zstąpił w obłoku, stanął tam z nim, i wypowiedział imię Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 6, 'Wtedy przechodził Pan przed nim i wołał: Pan, Pan, Bóg miłosierny i litościwy, nieskory do gniewu, a bogaty w miłosierdzie i prawdę;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 7, 'Zachowujący miłosierdzie nad tysiącami, przebaczający nieprawość, przestępstwo i grzech, lecz nieusprawiedliwiający winnego, nawiedzający nieprawość ojców na synach i na synach ich synów do trzeciego i czwartego pokolenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 8, 'Mojżesz więc spiesznie pochylił się do ziemi i oddał pokłon;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 9, 'I powiedział: Jeśli znalazłem teraz łaskę w twoich oczach, Panie, niech Pan idzie, proszę, pośród nas, bo ten lud jest twardego karku. Wybacz nasze nieprawości i nasz grzech, a weź nas za dziedzictwo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 10, 'Odpowiedział: Oto ustanowię przymierze. Przed całym twoim ludem będę czynił cuda, jakie nie były dokonane na całej ziemi i w żadnym narodzie. I cały lud, wśród którego przebywasz, zobaczy dzieło Pana, gdyż straszne będzie to, co uczynię z tobą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 11, 'Przestrzegaj tego, co dziś ci rozkazuję: Oto wypędzę sprzed twojego oblicza Amorytę, Kananejczyka, Chetytę, Peryzzytę, Chiwwitę i Jebusytę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 12, 'Strzeż się, abyś nie zawarł przymierza z obywatelami tej ziemi, do której wejdziesz, żeby to nie było sidłem pośród ciebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 13, 'Dlatego zburzycie ich ołtarze, połamiecie ich bożki i wyrąbiecie ich święte gaje.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 14, 'Nie będziesz oddawał pokłonu innemu bogu, bo Pan, którego imię jest Zazdrosny, jest Bogiem zazdrosnym;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 15, 'Abyś nie zawierał przymierza z mieszkańcami tej ziemi, abyś – gdy oni popełniają nierząd ze swymi bogami i składają ofiary swym bogom – nie został zawołany, by jeść z ich ofiar;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 16, 'I nie brał spośród ich córek żony dla swych synów, a wtedy cudzołożyłyby ich córki ze swymi bogami i doprowadziłyby twoich synów do nierządu ze swymi bogami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 17, 'Nie będziesz czynił sobie odlewanych bożków.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 18, 'Będziesz zachowywał Święto Przaśników. Przez siedem dni będziesz jeść przaśniki, jak ci rozkazałem, w miesiącu Abib, gdyż w miesiącu Abib wyszedłeś z Egiptu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 19, 'Wszystko, co otwiera łono, jest moje, a także każdy pierworodny samiec z twego dobytku, zarówno spośród owiec, jak i wołów;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 20, 'Ale pierworodne oślę odkupisz owcą, a jeśli go nie odkupisz, złamiesz mu kark. Odkupisz każdego pierworodnego z twych synów i nie pokażą się przede mną z pustymi rękami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 21, 'Sześć dni będziesz pracować, a siódmego dnia odpoczniesz; odpoczniesz w czasie orania i w czasie żniwa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 22, 'Będziesz obchodził też Święto Tygodni, pierwociny żniwa pszenicy, i Święto Zbiorów na koniec roku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 23, 'Trzy razy do roku wszyscy twoi mężczyźni pokażą się przed obliczem Pana Boga, Boga Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 24, 'Bo wypędzę przed tobą narody i rozszerzę twoje granice; nikt nie będzie pożądał twojej ziemi, gdy trzy razy do roku pójdziesz, aby pokazać się przed obliczem Pana, twego Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 25, 'Nie będziesz składał krwi mojej ofiary razem z zakwasem i nic z ofiary obchodu święta Paschy nie zostanie do rana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 26, 'Przyniesiesz do domu Pana, twego Boga, pierwociny plonów twej ziemi. Nie będziesz gotował koźlęcia w mleku jego matki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 27, 'Potem Pan powiedział do Mojżesza: Zapisz sobie te słowa, bo według tych słów ustanowiłem przymierze z tobą i Izraelem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 28, 'I był tam z Panem czterdzieści dni i czterdzieści nocy, nie jadł chleba i nie pił wody. I Pan napisał na tablicach słowa przymierza, dziesięć przykazań.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 29, 'I gdy Mojżesz zstępował z góry Synaj – a miał Mojżesz w ręku dwie tablice świadectwa, gdy zstępował z góry – Mojżesz nie wiedział, że skóra jego twarzy lśniła, gdy Pan z nim rozmawiał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 30, 'Aaron i wszyscy synowie Izraela zobaczyli Mojżesza, a oto skóra jego twarzy lśniła, i bali się zbliżyć do niego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 31, 'Ale Mojżesz zawołał ich i Aaron oraz wszyscy przywódcy zgromadzenia Izraela wrócili do niego. I Mojżesz rozmawiał z nimi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 32, 'Potem podeszli też wszyscy synowie Izraela, a on przykazał im wszystko, o czym Pan z nim rozmawiał na górze Synaj.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 33, 'A póki Mojżesz z nimi rozmawiał, miał na swojej twarzy zasłonę;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 34, 'Ale gdy Mojżesz wchodził przed oblicze Pana, aby z nim rozmawiać, zdejmował zasłonę, póki nie wyszedł. Gdy zaś wyszedł, mówił do synów Izraela, co mu nakazano.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 35, 'I synowie Izraela patrzyli na twarz Mojżesza, a skóra twarzy Mojżesza lśniła. I Mojżesz znowu kładł zasłonę na swoją twarz, póki nie wszedł, aby z nim rozmawiać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 1, 'Potem Mojżesz zebrał całe zgromadzenie synów Izraela i mówił do nich: Oto są słowa, które Pan rozkazał, abyście je wypełnili.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 2, 'Przez sześć dni będzie wykonywana praca, ale siódmy dzień będzie dla was świętem, szabatem odpoczynku dla Pana. Kto w nim wykona pracę, poniesie śmierć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 3, 'Nie rozniecicie ognia w żadnym z waszych mieszkań w dzień szabatu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 4, 'Mojżesz powiedział też do całego zgromadzenia synów Izraela: Oto słowo, które Pan przykazał:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 5, 'Złóżcie Panu dar od siebie: każdy, kto jest ochotnego serca, niech przyniesie Panu dar: złoto, srebro i miedź;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 6, 'Błękitną tkaninę, purpurę, karmazyn, bisior i kozią sierść;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 7, 'I skóry baranie farbowane na czerwono i skóry borsucze, i drewno akacjowe;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 8, 'Oliwę do oświetlenia, wonności na olejek do namaszczania i na wonne kadzidło;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 9, 'Kamienie onyksu i kamienie do osadzenia efodu i pektorału.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 10, 'A wszyscy spośród was, którzy są uzdolnieni, przyjdą i będą robić wszystko, co Pan rozkazał:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 11, 'Przybytek, jego namiot i przykrycie, haczyki do niego i deski, drążki do niego, słupy i podstawki;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 12, 'Arkę i drążki do niej, przebłagalnię i zasłonę do osłonięcia;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 13, 'Stół i drążki do niego, wszystkie jego naczynia i chleby pokładne;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 14, 'Świecznik do oświetlenia i jego przybory, lampy do niego i oliwę do świecenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 15, 'Także ołtarz kadzenia z drążkami do niego, olejek do namaszczania, wonne kadzidło i zasłonę do wejścia do przybytku;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 16, 'Ołtarz całopalenia, miedzianą kratę do niego, drążki i wszystkie naczynia do niego, kadź i jej podstawę;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 17, 'Zasłony do dziedzińca, słupy i podstawki do nich, zasłonę do wejścia na dziedziniec.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 18, 'Kołki do przybytku i kołki do dziedzińca z ich sznurami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 19, 'Szaty służebne do usługiwania w Miejscu Świętym, święte szaty kapłana Aarona i szaty dla jego synów, do sprawowania urzędu kapłańskiego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 20, 'Wtedy całe zgromadzenie synów Izraela odeszło od Mojżesza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 21, 'I przyszedł każdy, kogo serce pobudziło, i każdy, w którym duch był ochoczy; i przynieśli Panu dar do wykonania Namiotu Zgromadzenia, na wszelką służbę w nim i na święte szaty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 22, 'Przychodzili więc mężczyźni i kobiety, każdy, kto był ochotnego serca, i przynosili bransoletki, kolczyki, pierścienie, naszyjniki i wszelkie złote przedmioty i każdy przynosił Panu ofiarę ze złota.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 23, 'Każdy też, kto miał błękitną tkaninę, purpurę, karmazyn, bisior, kozią sierść, skóry baranie farbowane na czerwono i skóry borsucze, przynosił je.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 24, 'Każdy, kto ofiarował dar ze srebra i miedzi, przynosił na ofiarę dla Pana; każdy też, kto miał drewno akacjowe, do wszelkiej pracy tej służby, przynosił je.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 25, 'I wszystkie uzdolnione kobiety przędły swymi rękami i przynosiły to, co naprzędły: z błękitnej tkaniny, purpury, karmazynu i bisioru.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 26, 'A wszystkie kobiety, których serca były obdarzone zdolnością, przędły kozią sierść.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 27, 'Przełożeni zaś przynosili kamienie onyksu i kamienie do osadzenia efodu i pektorału;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 28, 'Także wonności i oliwę do świecenia i na olejek do namaszczania, i na wonne kadzidła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 29, 'Wszyscy synowie Izraela przynosili Panu dobrowolną ofiarę, każdy mężczyzna i każda kobieta, w których było serce ochocze do składania ofiar na każde dzieło, które Pan przez Mojżesza rozkazał wykonać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 30, 'Potem Mojżesz powiedział do synów Izraela: Oto Pan powołał po imieniu Besalela, syna Uriego, syna Chura, z pokolenia Judy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 31, 'I napełnił go Duchem Bożym, mądrością, rozumem i umiejętnością we wszelkim rzemiośle;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 32, 'Aby umiejętnie wymyślał wzory, aby wyrabiał ze złota, srebra i miedzi;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 33, 'Do obrabiania kamieni do oprawy, do ciosania drewna, aby wykonał wszelkie rodzaje dzieła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 34, 'Włożył mu w serce też zdolność, aby mógł uczyć innych, on, i Oholiab, syn Achisamaka, z pokolenia Dana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 35, 'Napełnił ich mądrością serca, aby wykonywali wszelkie rzemiosło rytownicze, obmyślania projektów, hafciarskie z błękitnej tkaniny, purpury, karmazynu i bisioru i tkackie, aby obmyślali i zręcznie wykonywali każdą pracę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 1, 'Tak więc wykonali Besalel i Oholiab, i wszyscy uzdolnieni mężczyźni, którym Bóg dał mądrość i rozum, aby umieli wykonać każdą pracę do służby w świątyni, według wszystkiego, co Pan rozkazał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 2, 'I Mojżesz wezwał Besalela i Oholiaba, i każdego uzdolnionego mężczyznę, któremu Pan włożył w serce mądrość, którego serce pobudziło, aby przystąpić do wykonywania tej pracy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 3, 'I wzięli od Mojżesza wszystkie dary, które synowie Izraela przynieśli na dzieło służby w świątyni, aby ją wykonać. Oni zaś nadal przynosili mu dobrowolne dary każdego poranka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 4, 'Przyszli więc wszyscy uzdolnieni, którzy wykonywali wszelką pracę przy świątyni, każdy od swojej pracy, którą wykonywał;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 5, 'I powiedzieli do Mojżesza: Lud przynosi dużo więcej niż potrzeba do wykonania tej służby, którą Pan rozkazał uczynić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 6, 'Mojżesz rozkazał więc, aby ogłoszono w obozie: Niech już ani mężczyzna, ani kobieta nie przynosi więcej ofiar na budowę świątyni. I powstrzymano lud od ich przynoszenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 7, 'Bo to, co mieli, wystarczyło do wykonania wszelkiej pracy, a nawet zbywało.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 8, 'I wszyscy uzdolnieni rzemieślnicy wykonali pracę przybytku: dziesięć zasłon ze skręconego bisioru, błękitnej tkaniny, purpury i karmazynu. Zrobili je z haftowanymi cherubinami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 9, 'Długość jednej zasłony była na dwadzieścia osiem łokci, a jej szerokość – na cztery łokcie. Wszystkie zasłony miały jednakowe wymiary.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 10, 'I spięli pięć zasłon jedną z drugą, także drugie pięć zasłon spięli jedną z drugą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 11, 'Porobili też pętle z błękitnej tkaniny na brzegu jednej zasłony, na końcu, gdzie mają się spinać. Zrobili je także na brzegu drugiej zasłony, na końcu, gdzie mają się spinać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 12, 'Pięćdziesiąt pętli zrobili na jednej zasłonie i pięćdziesiąt pętli zrobili na brzegu zasłony, w miejscu, gdzie ma być spięta z drugą. Pętle były jedna naprzeciw drugiej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 13, 'Zrobili też pięćdziesiąt złotych haczyków i spięli jedną zasłonę z drugą tymi haczykami. I tak przybytek stanowił jedną całość.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 14, 'Wykonali też zasłony z koziej sierści na namiot do przykrycia przybytku z wierzchu, zrobili jedenaście zasłon.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 15, 'Długość jednej zasłony była na trzydzieści łokci, a jej szerokość – na cztery łokcie. Jedenaście zasłon miało jednakowe wymiary.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 16, 'I spięli pięć zasłon osobno, a sześć zasłon osobno.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 17, 'Zrobili też pięćdziesiąt pętli na brzegu jednej zasłony, na końcu, gdzie ma być spięta, i pięćdziesiąt pętli zrobili na brzegu drugiej zasłony do spięcia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 18, 'Zrobili też pięćdziesiąt miedzianych haczyków do spięcia namiotu, aby stanowił jedną całość.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 19, 'Zrobili ponadto przykrycie na namiot ze skór baranich czerwono farbowanych i przykrycie ze skór borsuczych na wierzch.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 20, 'Zrobili też prosto stojące deski do przybytku z drewna akacjowego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 21, 'Długość jednej deski wynosiła dziesięć łokci, a jej szerokość – półtora łokcia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 22, 'Jedna deska miała dwa czopy ułożone jeden naprzeciw drugiego. Tak zrobili przy wszystkich deskach przybytku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 23, 'Zrobili też deski do przybytku, dwadzieścia desek na stronę południową, ku południowemu wiatrowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 24, 'I zrobili ze srebra czterdzieści podstawek pod dwadzieścia desek: dwie podstawki pod jedną deskę do dwóch jej czopów, także dwie podstawki pod drugą deskę do dwóch jej czopów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 25, 'Także na drugim boku przybytku od strony północnej zrobili dwadzieścia desek;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 26, 'I do nich czterdzieści srebrnych podstawek: dwie podstawki pod jedną deskę i dwie podstawki pod drugą deskę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 27, 'Ale po zachodniej stronie przybytku zrobili sześć desek.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 28, 'Dwie deski zrobili na narożniki przybytku po obydwu stronach;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 29, 'A były złączone od spodu, były też złączone u góry do jednego pierścienia. Tak zrobili po obu stronach na dwóch narożnikach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 30, 'Było więc osiem desek i do nich szesnaście srebrnych podstawek, po dwie podstawki pod każdą deską.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 31, 'Zrobili też drążki z drewna akacjowego; pięć do desek jednej strony przybytku;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 32, 'A także pięć drążków do desek drugiej strony przybytku, również pięć drążków do desek zachodniej strony przybytku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 33, 'I zrobili też środkowy drążek, aby przechodził przez środek desek od końca do końca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 34, 'A deski pokryli złotem i zrobili do nich pierścienie ze złota jako uchwyty dla drążków, i drążki pokryli złotem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 35, 'Zrobili też zasłonę z błękitnej tkaniny, purpury, karmazynu i skręconego bisioru. Zrobili ją z misternie wyhaftowanymi cherubinami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 36, 'A do niej zrobili cztery słupy z drewna akacjowego i pokryli je złotem, haki do nich też były ze złota, i odlali do nich cztery srebrne podstawki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 37, 'Zrobili też zasłonę do wejścia do namiotu z błękitnej tkaniny, purpury, karmazynu i skręconego bisioru, haftowaną;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 38, 'A do niej pięć słupów z haczykami i pokryli złotem ich głowice i klamry, a pięć podstawek do nich było z miedzi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 1, 'I Besalel zrobił arkę z drewna akacjowego, a jej długość była na dwa i pół łokcia, a jej szerokość – na półtora łokcia, także jej wysokość to półtora łokcia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 2, 'I pokrył ją szczerym złotem wewnątrz i na zewnątrz i zrobił wokół niej złotą listwę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 3, 'Odlał też do niej cztery złote pierścienie do czterech jej narożników: dwa pierścienie po jednej jej stronie, a dwa pierścienie po drugiej jej stronie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 4, 'Zrobił również drążki z drewna akacjowego i pokrył je złotem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 5, 'I włożył drążki w pierścienie po obu stronach arki, aby arka była na nich noszona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 6, 'Zrobił też przebłagalnię ze szczerego złota: jej długość była na dwa i pół łokcia, a jej szerokość – na półtora łokcia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 7, 'Zrobił dwa cherubiny wykute ze złota na obu końcach przebłagalni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 8, 'Jednego cherubina na jednym końcu, a drugiego cherubina na drugim końcu. Zrobił cherubiny z przebłagalni wystające na obu jej końcach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 9, 'A cherubiny miały rozpostarte skrzydła, z wierzchu zakrywały swymi skrzydłami przebłagalnię, a ich twarze były zwrócone ku sobie, twarze cherubinów były zwrócone ku przebłagalni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 10, 'Zrobił też stół z drewna akacjowego, jego długość była na dwa łokcie, jego szerokość – na jeden łokieć, a wysokość – na półtora łokcia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 11, 'I pokrył go szczerym złotem, i zrobił wokół niego złotą listwę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 12, 'Zrobił wokół niego też listwę o szerokości dłoni; zrobił również złote obramowanie wokoło tej listwy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 13, 'I odlał do niego cztery złote pierścienie, i przyprawił je do czterech narożników u jego czterech nóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 14, 'Naprzeciwko tej listwy były pierścienie, przez które przewleczono drążki do noszenia stołu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 15, 'Porobił drążki z drewna akacjowego do noszenia stołu i powlókł je złotem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 16, 'Zrobił też ze szczerego złota naczynia do stołu, misy do niego, czasze, przykrycia i kubki do nalewania.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 17, 'Zrobił także świecznik ze szczerego złota. Wykuł ze złota ten świecznik. Jego podstawa, ramiona, kielichy, gałki i kwiaty były z tej samej bryły.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 18, 'Sześć ramion wychodziło z obu boków: trzy ramiona z jednego boku świecznika i trzy ramiona z drugiego boku świecznika.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 19, 'Trzy kielichy na kształt migdała na jednym ramieniu, także gałka i kwiat; i trzy kielichy na kształt migdała na drugim ramieniu, także gałka i kwiat. Tak było na wszystkich sześciu ramionach wychodzących ze świecznika.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 20, 'Ale na samym świeczniku były cztery kielichy na kształt migdała, jego gałki i jego kwiaty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 21, 'I była gałka pod dwoma jego ramionami, także gałka pod następnymi dwoma jego ramionami, i znów gałka pod dwoma innymi jego ramionami. Tak było pod sześcioma ramionami wychodzącymi z niego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 22, 'Ich gałki i ramiona były z tej samej bryły. Wszystko to w całości było wykute ze szczerego złota.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 23, 'Zrobił też do niego siedem lamp oraz szczypce i naczynia na popiół ze szczerego złota.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 24, 'Zrobił go i wszystkie naczynia do niego z talentu szczerego złota.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 25, 'Zrobił także ołtarz do kadzenia z drewna akacjowego, na łokieć długi i na łokieć szeroki, kwadratowy, na dwa łokcie wysoki, a z niego wychodziły rogi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 26, 'I pokrył go szczerym złotem – jego wierzch, jego ściany wokoło i jego rogi. Zrobił też dokoła niego złotą listwę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 27, 'Zrobił dwa złote pierścienie do niego, pod jego listwą, na dwóch jego narożnikach, po obu bokach, przez które przewleczono drążki, aby był na nich noszony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 28, 'Zrobił także drążki z drewna akacjowego i pokrył je złotem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 29, 'Sporządził też olejek do świętego namaszczenia i wonne kadzidło, tak jak się robi wonności.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 1, 'Zrobił również ołtarz do całopalenia z drewna akacjowego, na pięć łokci długi i na pięć łokci szeroki, kwadratowy, na trzy łokcie wysoki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 2, 'I zrobił rogi na jego czterech narożnikach, rogi wychodziły z niego. I pokrył go miedzią.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 3, 'Zrobił też wszystkie naczynia do ołtarza, kociołki, szufle, miednice, widełki i łopaty na rozżarzone węgle. Wszystkie naczynia do niego zrobił z miedzi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 4, 'Zrobił także do ołtarza miedzianą kratę na kształt sieci pod obramowaniem, od spodu aż do połowy wysokości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 5, 'I odlał cztery pierścienie na czterech rogach miedzianej kraty jako uchwyty na drążki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 6, 'Porobił również drążki z drewna akacjowego i pokrył je miedzią.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 7, 'I włożył drążki w te pierścienie po obu bokach ołtarza, aby był na nich noszony; zrobił go z desek, wewnątrz był pusty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 8, 'Zrobił też kadź z miedzi i do niej miedzianą podstawę ze zwierciadeł kobiet, które gromadnie przychodziły przed wejście do Namiotu Zgromadzenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 9, 'Zrobił także dziedziniec: na południu po prawej stronie zasłony dziedzińca były ze skręconego bisioru, na sto łokci;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 10, 'Do nich dwadzieścia słupów, a do nich dwadzieścia miedzianych podstawek; haki na słupach i ich klamry ze srebra.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 11, 'Także po stronie północnej zasłony na sto łokci; do nich dwadzieścia słupów i do nich dwadzieścia miedzianych podstawek; haki na słupach i ich klamry ze srebra.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 12, 'A od zachodniej strony były zasłony na pięćdziesiąt łokci; do nich dziesięć słupów i do nich dziesięć podstawek; haki na słupach i ich klamry ze srebra.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 13, 'A z przodu po stronie wschodniej były zasłony na pięćdziesiąt łokci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 14, 'Zasłony na piętnaście łokci były po jednej stronie, do nich trzy słupy i trzy podstawki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 15, 'I po drugiej stronie bramy dziedzińca, z jednej i z drugiej strony, piętnaście łokci zasłon, do nich trzy słupy i trzy podstawki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 16, 'Wszystkie zasłony dziedzińca wokoło były ze skręconego bisioru;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 17, 'A podstawki słupów z miedzi, haki na słupach i klamry ze srebra, także pokrycia ich głowic ze srebra; wszystkie słupy dziedzińca były oklamrowane srebrem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 18, 'Zasłona do bramy dziedzińca była haftowana, z błękitnej tkaniny, purpury, karmazynu i skręconego bisioru; długa na dwadzieścia łokci, wysoka na pięć łokci jak inne zasłony dziedzińca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 19, 'A do nich cztery słupy i cztery miedziane podstawki; haki do nich były ze srebra, pokrycia ich głowic i klamry też były ze srebra.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 20, 'Wszystkie kołki przybytku i dziedzińca wokoło były z miedzi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 21, 'Oto obliczenie rzeczy do przybytku, do Przybytku Świadectwa, które zostały obliczone na rozkaz Mojżesza przez Itamara, syna kapłana Aarona, do służby Lewitów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 22, 'A Besalel, syn Uriego, syna Chura, z pokolenia Judy, zrobił wszystko, co Pan rozkazał Mojżeszowi;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 23, 'A z nim Oholiab, syn Achisamaka, z pokolenia Dana, rytownik, wybitny rzemieślnik i haftujący na błękitnej tkaninie, na purpurze, na karmazynie i na bisiorze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 24, 'Całego złota zużytego na wykonanie wszelkich robót świątyni – złota z darów – było dwadzieścia dziewięć talentów i siedemset trzydzieści syklów według sykla świątynnego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 25, 'Srebra zaś od przeliczonych spośród zgromadzenia było sto talentów i tysiąc siedemset siedemdziesiąt pięć syklów według sykla świątynnego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 26, 'Od każdej głowy pół sykla według sykla świątynnego, od wszystkich, którzy zostali policzeni, od dwudziestu lat i wyżej, a ludzi tych było sześćset trzy tysiące pięciuset pięćdziesięciu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 27, 'A było sto talentów srebra do odlewania podstawek świątyni i podstawek zasłony; sto podstawek ze stu talentów; talent na podstawkę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 28, 'A z tysiąca siedmiuset siedemdziesięciu pięciu syklów zrobił haki na słupy i pokrył ich głowice, i oklamrował je.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 29, 'Miedzi zaś złożonej w ofierze było siedemdziesiąt talentów i dwa tysiące czterysta syklów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 30, 'I odlał z niej podstawki do wejścia do Namiotu Zgromadzenia i miedziany ołtarz, i do niego miedzianą kratę oraz wszystkie naczynia do ołtarza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 31, 'I podstawki do dziedzińca wokoło, podstawki do bramy dziedzińca, wszystkie kołki przybytku oraz kołki dziedzińca wokoło.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 1, 'Także z błękitnej tkaniny, purpury i karmazynu zrobili szaty do służby, do posługiwania w świątyni. Zrobili też święte szaty dla Aarona, jak Pan rozkazał Mojżeszowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 2, 'I zrobili efod ze złota, błękitnej tkaniny, purpury, karmazynu i skręconego bisioru.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 3, 'Naklepali też złote blaszki i nacięli z nich nici do przetykania haftem błękitnej tkaniny, purpury, karmazynu i bisioru.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 4, 'Zrobili do niego naramienniki, aby się jeden z drugim mógł złączyć. Łączyły się na dwóch końcach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 5, 'Także pas do efodu, który był na nim, z tego samego był i tak samo zrobiony: ze złota, błękitnej tkaniny, purpury, karmazynu i skręconego bisioru, jak Pan rozkazał Mojżeszowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 6, 'Do tego obrobili kamienie onyksu osadzone w złotych oprawkach, wyryte tak jak pieczęci bywają ryte, z imionami synów Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 7, 'I umieścili je na naramiennikach efodu, aby były kamieniami pamiątkowymi dla synów Izraela, jak Pan rozkazał Mojżeszowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 8, 'Zrobili też haftowany pektorał podobnie jak efod: ze złota, błękitnej tkaniny, purpury, karmazynu i skręconego bisioru.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 9, 'Był kwadratowy; zrobili podwójny pektorał, na piędź długości i na piędź szerokości, złożony we dwoje.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 10, 'I osadzili w nim cztery rzędy kamieni w tym porządku: karneol, topaz i szmaragd w pierwszym rzędzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 11, 'A w drugim rzędzie: karbunkuł, szafir i diament.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 12, 'A w trzecim rzędzie: hiacynt, agat i ametyst.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 13, 'A w czwartym rzędzie: beryl, onyks i jaspis, wszystkie osadzone w złotych oprawach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 14, 'A tych kamieni z imionami synów Izraela było dwanaście, według ich imion, które ryte były jak na pieczęci; każdy według swego imienia, według dwunastu pokoleń.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 15, 'Zrobili też do pektorału łańcuszki plecione ze szczerego złota.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 16, 'Zrobili także dwie złote oprawki i dwa złote pierścienie i przyczepili te dwa pierścienie do obu rogów pektorału.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 17, 'I włożyli te dwa złote łańcuszki w oba pierścienie u rogów pektorału.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 18, 'Drugie zaś końce obu łańcuszków przymocowali do tych dwóch oprawek i przyprawili z przodu do naramienników efodu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 19, 'Zrobili również dwa złote pierścienie, które przymocowali do dwóch rogów pektorału na jego wewnętrznym brzegu, który był od strony efodu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 20, 'Zrobili jeszcze dwa złote pierścienie, które przyprawili na dwie strony efodu, u dołu, naprzeciwko jego spojenia, ponad pasem efodu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 21, 'I przywiązali pektorał jego pierścieniami do pierścieni efodu sznurem błękitnym, aby był nad pasem efodu, żeby pektorał nie odstawał od efodu, jak Pan rozkazał Mojżeszowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 22, 'Zrobili także tkany płaszcz pod efod, cały z błękitnej tkaniny;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 23, 'A pośrodku płaszcza otwór, jak otwór w pancerzu, i obwódkę dokoła brzegu, aby się nie rozdzierał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 24, 'Także u dołu tego płaszcza zrobili jabłka granatu z błękitnej tkaniny, purpury, karmazynu i skręconego bisioru.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 25, 'Zrobili też dzwonki ze szczerego złota i pozawieszali te dzwonki między te jabłka granatu u dołu dokoła płaszcza, pośród jabłek granatu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 26, 'Dzwonek, a potem jabłko granatu i znów dzwonek, i jabłko granatu, u dołu dokoła płaszcza do usługiwania, jak Pan rozkazał Mojżeszowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 27, 'Zrobili też dla Aarona i jego synów szaty tkane z bisioru.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 28, 'Mitrę także z bisioru i ozdobne mitry z bisioru, i spodnie ze skręconego bisioru.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 29, 'Pas także ze skręconego bisioru, błękitnej tkaniny, purpury i karmazynu, haftowany, jak Pan rozkazał Mojżeszowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 30, 'Zrobili też blaszkę do świętej korony ze szczerego złota i wyryli na niej napis jak na pieczęci: Świętość Panu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 31, 'A przymocowali do niej sznur z błękitnej tkaniny, aby była przywiązana na przodzie mitry, jak Pan rozkazał Mojżeszowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 32, 'I tak skończyły się wszystkie prace około przybytku, czyli Namiotu Zgromadzenia. I synowie Izraela zrobili wszystko, jak Pan rozkazał Mojżeszowi; tak zrobili.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 33, 'I przynieśli ten przybytek do Mojżesza, namiot i wszystkie naczynia do niego, jego haki, deski, drążki, słupy i podstawki;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 34, 'Przykrycie ze skór baranich farbowanych na czerwono, przykrycie ze skór borsuczych i zasłonę do osłonięcia;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 35, 'Arkę świadectwa i drążki do niej, i przebłagalnię;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 36, 'Stół, wszystkie naczynia do niego i chleb pokładny;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 37, 'Szczerozłoty świecznik, lampy do niego – lampy ustawione w porządku – i wszystkie naczynia do niego, i oliwę do świecenia;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 38, 'Także złoty ołtarz, olejek do namaszczania, wonne kadzidło i zasłonę do wejścia do namiotu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 39, 'Miedziany ołtarz i do niego miedzianą kratę, drążki i wszystkie naczynia do niego, kadź i podstawę do niej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 40, 'Zasłony do dziedzińca, słupy i podstawki do niego, zasłonę do bramy dziedzińca, sznury i kołki do niej i wszelkie naczynia do służby w przybytku, czyli do Namiotu Zgromadzenia;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 41, 'Szaty do służby w posługiwaniu w świątyni, święte szaty dla kapłana Aarona i szaty jego synów do sprawowania urzędu kapłańskiego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 42, 'Według wszystkiego, co Pan rozkazał Mojżeszowi, tak synowie Izraela wykonali całą tę pracę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 43, 'I Mojżesz obejrzał tę całą robotę, a zrobili ją, jak Pan rozkazał; tak właśnie zrobili. I Mojżesz im błogosławił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 1, 'Potem Pan powiedział do Mojżesza:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 2, 'W pierwszym dniu, pierwszego miesiąca, wystawisz przybytek, czyli Namiot Zgromadzenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 3, 'I postawisz tam arkę świadectwa, i zakryjesz ją zasłoną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 4, 'Wstawisz stół i ustawisz na nim to, co należy; wniesiesz także świecznik i zapalisz jego lampy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 5, 'Postawisz też złoty ołtarz do kadzenia przed arką świadectwa i zawiesisz zasłonę przy wejściu do przybytku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 6, 'Postawisz także ołtarz całopalenia przed wejściem do przybytku, do Namiotu Zgromadzenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 7, 'Postawisz też kadź między Namiotem Zgromadzenia a ołtarzem i nalejesz do niej wody.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 8, 'Wystawisz również i dziedziniec wokoło i zawiesisz zasłonę w bramie dziedzińca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 9, 'Potem weźmiesz olejek do namaszczania i namaścisz przybytek i wszystko, co w nim jest, i poświęcisz go ze wszystkimi jego naczyniami, a będzie święty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 10, 'Namaścisz też ołtarz całopalenia i wszystkie jego naczynia i poświęcisz ołtarz, a stanie się najświętszym ołtarzem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 11, 'I namaścisz kadź i jej podstawę, i poświęcisz ją.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 12, 'Potem każesz podejść Aaronowi i jego synom przed wejście do Namiotu Zgromadzenia i umyjesz ich wodą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 13, 'Obleczesz Aarona w święte szaty i namaścisz go, i poświęcisz go, aby mi sprawował urząd kapłański.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 14, 'Także jego synom każesz podejść i obleczesz ich w szaty;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 15, 'I namaścisz ich, jak namaściłeś ich ojca, aby mi sprawowali urząd kapłański. A ich namaszczenie będzie dla nich wiecznym kapłaństwem po wszystkie ich pokolenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 16, 'Mojżesz uczynił więc wszystko, jak mu Pan rozkazał; tak uczynił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 17, 'I tak pierwszego miesiąca, drugiego roku, pierwszego dnia miesiąca, został wzniesiony przybytek.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 18, 'I Mojżesz wystawił przybytek, podstawił jego podstawki, postawił deski, włożył drążki i postawił jego słupy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 19, 'Rozciągnął też namiot nad przybytkiem i z wierzchu nałożył przykrycie namiotu nad nim, jak Pan rozkazał Mojżeszowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 20, 'Potem wziął świadectwo i włożył je do arki, i włożył drążki u arki, i umieścił przebłagalnię z wierzchu na arce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 21, 'I wniósł arkę do przybytku, i zawiesił zasłonę zakrywającą, i zasłonił arkę świadectwa, jak Pan rozkazał Mojżeszowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 22, 'Postawił też stół w Namiocie Zgromadzenia po północnej stronie przybytku przed zasłoną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 23, 'I poukładał na nim chleby przed Panem, jak Pan rozkazał Mojżeszowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 24, 'Postawił też świecznik w Namiocie Zgromadzenia naprzeciwko stołu, po południowej stronie przybytku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 25, 'Zapalił też lampy przed Panem, jak Pan rozkazał Mojżeszowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 26, 'Ustawił i złoty ołtarz w Namiocie Zgromadzenia przed zasłoną;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 27, 'I zapalił na nim wonne kadzidło, jak Pan rozkazał Mojżeszowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 28, 'Potem zawiesił zasłonę u wejścia do przybytku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 29, 'Postawił też ołtarz całopalenia u wejścia do przybytku, czyli do Namiotu Zgromadzenia, i złożył na nim całopalenie i ofiarę pokarmową, jak Pan rozkazał Mojżeszowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 30, 'Potem umieścił kadź między Namiotem Zgromadzenia a ołtarzem i nalał do niej wody do obmywania.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 31, 'I Mojżesz, Aaron i jego synowie obmyli w niej swoje ręce i nogi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 32, 'Gdy wchodzili do Namiotu Zgromadzenia i gdy zbliżali się do ołtarza, obmywali się, jak Pan rozkazał Mojżeszowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 33, 'Na koniec wystawił dziedziniec dokoła przybytku i ołtarza oraz zawiesił zasłonę w bramie dziedzińca. I tak Mojżesz zakończył tę pracę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 34, 'Wtedy obłok okrył Namiot Zgromadzenia, a chwała Pana napełniła przybytek.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 35, 'I Mojżesz nie mógł wejść do Namiotu Zgromadzenia, bo spoczywał nad nim obłok, a chwała Pana napełniła przybytek.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 36, 'A gdy obłok wznosił się znad przybytku, synowie Izraela wyruszali w swoje wędrówki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 37, 'A jeśli obłok nie wznosił się, nie wyruszali aż do dnia, kiedy się unosił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 38, 'A obłok Pana był nad przybytkiem w ciągu dnia, w nocy zaś ogień był nad nim na oczach całego domu Izraela, w czasie całej ich wędrówki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 1, 'I Pan zawołał do Mojżesza, i powiedział do niego z Namiotu Zgromadzenia:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 2, 'Przemów do synów Izraela i powiedz im: Jeśli ktoś z was zechce złożyć Panu ofiarę, niech złoży ją z bydła, ze stada albo z trzody.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 3, 'Jeśli jego ofiara całopalna będzie ze stada, niech złoży samca bez skazy. Niech go złoży dobrowolnie przed Panem u wejścia do Namiotu Zgromadzenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 4, 'I położy swą rękę na głowie ofiary całopalnej, a zostanie przyjęta jako przebłaganie za niego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 5, 'Potem zabije tego cielca przed Panem. A kapłani, synowie Aarona, ofiarują krew i pokropią tą krwią z wierzchu dokoła ołtarz, który jest przed wejściem do Namiotu Zgromadzenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 6, 'I obedrze ofiarę całopalną ze skóry, i pokroi ją na części.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 7, 'Wtedy synowie kapłana Aarona położą ogień na ołtarzu i ułożą drwa na ogniu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 8, 'Potem kapłani, synowie Aarona, porządnie ułożą te części oraz głowę i tłuszcz na drwach leżących na ogniu na ołtarzu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 9, 'A jego wnętrzności i nogi obmyje wodą. I kapłan spali to wszystko na ołtarzu. To jest całopalenie, ofiara ogniowa, miła woń dla Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 10, 'A jeśli jego ofiara na całopalenie będzie z trzody, owiec lub kóz, niech weźmie samca bez skazy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 11, 'I zabije go obok ołtarza po północnej stronie przed Panem. A kapłani, synowie Aarona, pokropią jego krwią z wierzchu ołtarz dokoła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 12, 'Potem pokroi go na części wraz z jego głową i tłuszczem. A kapłan ułoży je porządnie na drwach leżących na ogniu na ołtarzu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 13, 'Wnętrzności zaś i nogi obmyje wodą. I kapłan weźmie to wszystko, i spali na ołtarzu. To jest całopalenie, ofiara ogniowa, miła woń dla Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 14, 'A jeśli jego ofiara na całopalenie dla Pana będzie z ptactwa, niech weźmie swoją ofiarę z synogarlic albo z młodych gołębi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 15, 'Kapłan przyniesie go do ołtarza, ukręci mu głowę i spali na ołtarzu, a jego krew wyciśnie na ścianę ołtarza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 16, 'I usunie wole wraz z jego pierzem i wyrzuci je na popielisko, obok ołtarza po wschodniej stronie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 17, 'I naderwie jego skrzydła, ale ich nie oderwie. I kapłan spali to na ołtarzu, na drwach leżących na ogniu. To jest całopalenie, ofiara ogniowa, miła woń dla Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 1, 'Gdy ktoś zechce złożyć Panu ofiarę pokarmową, niech jego ofiara będzie z mąki pszennej. Niech poleje ją oliwą i położy na niej kadzidła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 2, 'I przyniesie ją do synów Aarona, kapłanów, a kapłan weźmie stamtąd pełną garść tej mąki pszennej wraz z oliwą i całym kadzidłem i spali to na ołtarzu jako pamiątkę. To jest ofiara ogniowa, miła woń dla Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 3, 'To zaś, co zostanie z tej ofiary pokarmowej, będzie dla Aarona i jego synów. Jest to najświętsza część z ofiar ogniowych dla Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 4, 'A jeśli będziesz składał ofiarę pokarmową upieczoną w piecu, niech to będą przaśne placki z mąki pszennej zmieszane z oliwą albo przaśne podpłomyki skropione oliwą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 5, 'Jeśli zaś będziesz składał ofiarę pokarmową smażoną na patelni, niech będzie ona z mąki pszennej niezakwaszonej, zmieszanej z oliwą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 6, 'Połamiesz ją na kawałki i polejesz oliwą. To jest ofiara pokarmowa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 7, 'A jeśli będziesz składał ofiarę pokarmową gotowaną w rondlu, niech ona będzie z mąki pszennej z oliwą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 8, 'I przyniesiesz Panu ofiarę pokarmową tak przyrządzoną. Oddasz ją kapłanowi, a on odniesie ją do ołtarza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 9, 'I kapłan weźmie z tej ofiary pokarmowej część na pamiątkę i spali na ołtarzu. To jest ofiara ogniowa, miła woń dla Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 10, 'To zaś, co pozostanie z ofiary pokarmowej, będzie należeć do Aarona i jego synów. Jest to najświętsza część z ofiar ogniowych dla Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 11, 'Żadna ofiara pokarmowa, jaką będziecie składać Panu, nie będzie przygotowywana z zakwasem, bo żadnego zakwasu ani żadnego miodu nie będziecie spalać na ofiarę ogniową dla Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 12, 'Możecie je składać Panu jako ofiarę pierwocin, ale nie będziecie ich kłaść na ołtarzu na miłą woń.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 13, 'Każdą z ofiar pokarmowych posolisz i nie pozbawisz soli przymierza twego Boga swej ofiary pokarmowej. Przy każdej twojej ofierze złożysz sól.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 14, 'A jeśli będziesz składał Panu ofiarę pokarmową z pierwocin, to złożysz świeże kłosy prażone na ogniu, zboże wykruszone ze świeżych kłosów jako ofiarę pokarmową z twoich pierwszych plonów;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 15, 'Nalejesz na nią oliwy i położysz na nią kadzidła. To jest ofiara pokarmowa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 16, 'Wtedy kapłan spali na pamiątkę trochę jej wykruszonego zboża i oliwy wraz z całym jej kadzidłem. To jest ofiara ogniowa dla Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 1, 'A jeśli ktoś będzie chciał złożyć ofiarę pojednawczą, a byłaby ze stada – czy to samca, czy samicę – niech złoży ją bez skazy przed Panem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 2, 'I położy rękę na głowie swojej ofiary, i zabije ją przed wejściem do Namiotu Zgromadzenia. I synowie Aarona, kapłani, pokropią krwią z wierzchu dokoła ołtarz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 3, 'Potem z ofiary pojednawczej złoży Panu ofiarę ogniową: tłuszcz okrywający wnętrzności i cały tłuszcz, który jest na nich;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 4, 'Obie nerki z tłuszczem, który jest na nich i na lędźwiach, i płat tłuszczu na wątrobie oddzieli wraz z nerkami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 5, 'I synowie Aarona spalą to na ołtarzu razem z ofiarą całopalną, która jest na drwach leżących na ogniu. To jest ofiara ogniowa na miłą woń dla Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 6, 'Jeśli zaś jego ofiara na ofiarę pojednawczą dla Pana będzie z trzody, czy to samiec, czy samica, niech złoży ją bez skazy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 7, 'Jeśli składa owcę na swoją ofiarę, niech złoży ją przed Panem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 8, 'I położy rękę na głowie swojej ofiary, i zabije ją przed Namiotem Zgromadzenia. I synowie Aarona pokropią jej krwią z wierzchu dokoła ołtarz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 9, 'I z ofiary pojednawczej złoży Panu ofiarę ogniową: jej tłuszcz, cały ogon, który odetnie przy samej kości ogonowej, tłuszcz okrywający wnętrzności oraz cały tłuszcz na wnętrznościach;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 10, 'Obie nerki z tłuszczem, który jest na nich i na lędźwiach, i płat tłuszczu na wątrobie, który oddzieli wraz z nerkami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 11, 'I kapłan spali to na ołtarzu. To jest pokarm ofiary ogniowej dla Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 12, 'Jeśli zaś jego ofiara będzie kozą, niech złoży ją przed Panem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 13, 'Położy rękę na jej głowie i zabije ją przed Namiotem Zgromadzenia. I synowie Aarona pokropią jej krwią ołtarz dokoła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 14, 'I złoży z niej Panu swoją ofiarę na ofiarę ogniową: tłuszcz okrywający wnętrzności i cały tłuszcz na wnętrznościach;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 15, 'Obie nerki z tłuszczem, który jest na nich i na lędźwiach, i płat tłuszczu na wątrobie, który oddzieli wraz z nerkami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 16, 'I kapłan spali to na ołtarzu. To jest pokarm ofiary ogniowej na miłą woń. Wszelki bowiem tłuszcz należy do Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 17, 'To jest wieczna ustawa dla waszych pokoleń, we wszystkich waszych mieszkaniach: Nie będziecie jeść żadnego tłuszczu ani żadnej krwi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 1, 'I Pan powiedział do Mojżesza:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 2, 'Przemów do synów Izraela i powiedz im: Gdyby ktoś zgrzeszył nieświadomie przeciw któremuś z przykazań Pana i zrobił coś, czego nie wolno robić, i przekroczyłby jedno z nich:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 3, 'Jeśli to namaszczony kapłan zgrzeszył jak ktoś z ludu, niech złoży Panu za swój grzech, którego się dopuścił, młodego cielca bez skazy jako ofiarę za grzech.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 4, 'I przyprowadzi tego cielca przed wejście do Namiotu Zgromadzenia przed Pana, położy rękę na głowie tego cielca i zabije go przed Panem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 5, 'I namaszczony kapłan weźmie nieco krwi tego cielca, i wniesie ją do Namiotu Zgromadzenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 6, 'Potem kapłan umoczy swój palec we krwi i siedem razy pokropi tą krwią przed Panem, przed zasłoną Miejsca Świętego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 7, 'I kapłan pomaże tą krwią rogi ołtarza wonnego kadzidła, który jest przed Panem w Namiocie Zgromadzenia; resztę zaś krwi tego cielca wyleje u podstawy ołtarza całopalenia, który jest przy wejściu do Namiotu Zgromadzenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 8, 'A cały tłuszcz wyjmie z cielca na ofiarę za grzech: tłuszcz okrywający wnętrzności i cały tłuszcz, który jest na wnętrznościach;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 9, 'Obie nerki z tłuszczem, który jest na nich i na lędźwiach, i płat tłuszczu na wątrobie, który oddzieli wraz z nerkami;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 10, 'Tak jak wyjmuje się go z cielca ofiary pojednawczej. I kapłan spali to na ołtarzu całopalenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 11, 'Skórę zaś tego cielca i całe jego mięso wraz z głową i nogami, jego wnętrzności i odchody;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 12, 'A więc całego cielca, wyniesie poza obóz na miejsce czyste, gdzie wysypuje się popiół, i spali go na drwach, na ogniu. Będzie spalony tam, gdzie wysypują popiół.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 13, 'Gdyby całe zgromadzenie Izraela zgrzeszyło nieświadomie, a sprawa była ukryta przed oczami zgromadzenia, i uczynili coś przeciw któremuś z przykazań Pana, czego nie wolno czynić, i w ten sposób zawinili;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 14, 'Kiedy grzech, którego się dopuścili, wyjdzie na jaw, wtedy zgromadzenie złoży młodego cielca jako ofiarę za grzech i przyprowadzi go przed Namiot Zgromadzenia;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 15, 'A starsi zgromadzenia włożą ręce na głowę cielca przed Panem. I zabiją tego cielca przed Panem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 16, 'Wtedy namaszczony kapłan wniesie nieco krwi cielca do Namiotu Zgromadzenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 17, 'I kapłan umoczy swój palec w tej krwi, i pokropi nią siedem razy przed Panem, przed zasłoną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 18, 'Potem pomaże tą krwią rogi ołtarza, który jest przed Panem w Namiocie Zgromadzenia; resztę zaś krwi wyleje u podstawy ołtarza całopalenia, który jest przy wejściu do Namiotu Zgromadzenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 19, 'Cały tłuszcz wyjmie z niego i spali na ołtarzu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 20, 'I postąpi z tym cielcem tak samo jak postąpił z cielcem złożonym za grzech; tak właśnie z nim postąpi. W ten sposób kapłan dokona za nich przebłagania i będzie im przebaczone.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 21, 'Potem wyniesie tego cielca poza obóz i spali go, tak jak spalił pierwszego cielca. To jest ofiara za grzech zgromadzenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 22, 'Gdyby przełożony ludu zgrzeszył nieświadomie i przekroczył jedno z przykazań Pana, swego Boga, czyniąc coś, czego nie wolno czynić, i w ten sposób zawinił;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 23, 'Lub gdyby uświadomił sobie swój grzech, który popełnił, to przyprowadzi na ofiarę kozła z kóz, samca bez skazy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 24, 'Położy rękę na głowie tego kozła i zabije go na tym miejscu, gdzie się zabija ofiary całopalne przed Panem. To jest ofiara za grzech.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 25, 'I kapłan weźmie na palec nieco krwi ofiary za grzech, i pomaże rogi ołtarza całopalenia, a resztę krwi wyleje u podstawy ołtarza całopalenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 26, 'Cały zaś jego tłuszcz spali na ołtarzu, tak jak tłuszcz ofiary pojednawczej. W ten sposób kapłan dokona za niego przebłagania za jego grzech i będzie mu przebaczony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 27, 'Gdyby ktoś spośród ludu zgrzeszył nieświadomie i przekroczył jedno z przykazań Pana, czyniąc coś, czego nie wolno czynić, i w ten sposób zawinił;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 28, 'Lub gdyby uświadomił sobie swój grzech, który popełnił, to przyprowadzi na ofiarę kozę z kóz, samicę bez skazy, za swój grzech, którego się dopuścił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 29, 'Potem położy rękę na głowie tej ofiary za grzech i zabije ją na miejscu ofiar całopalnych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 30, 'Kapłan zaś weźmie na palec nieco jej krwi i pomaże rogi ołtarza całopalenia, a resztę krwi wyleje u podstawy ołtarza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 31, 'Cały jej tłuszcz oddzieli – tak jak oddziela się tłuszcz z ofiary pojednawczej – i kapłan spali to na ołtarzu na miłą woń dla Pana. Tak kapłan dokona przebłagania za niego i będzie mu przebaczone.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 32, 'A jeśli przyprowadzi owcę na ofiarę za grzech, niech przyprowadzi samicę bez skazy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 33, 'I położy rękę na głowie tej ofiary za grzech, i zabije ją jako ofiarę za grzech na tym miejscu, gdzie się zabija ofiary całopalne.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 34, 'Potem kapłan weźmie na palec nieco krwi ofiary za grzech i pomaże rogi ołtarza całopalenia, a resztę krwi wyleje u podstawy ołtarza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 35, 'I cały jej tłuszcz oddzieli – tak jak oddziela się tłuszcz z owcy ofiary pojednawczej – i kapłan spali to na ołtarzu, na ofiarach całopalnych dla Pana. W ten sposób kapłan dokona za niego przebłagania za jego grzech, którego się dopuścił, i będzie mu przebaczony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 1, 'Gdyby ktoś zgrzeszył przez to, że usłyszał przekleństwo i był tego świadkiem lub widział czy dowiedział się o tym, a tego nie oznajmił, będzie obciążony nieprawością;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 2, 'Albo jeśli ktoś dotknął czegoś nieczystego, czy to padliny nieczystego zwierzęcia, czy padliny nieczystego bydlęcia, czy padliny nieczystego zwierzęcia pełzającego, a nie jest tego świadomy, i tak będzie nieczysty i winny;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 3, 'Lub jeśli ktoś dotknął jakiejkolwiek nieczystości ludzkiej, przez którą stanie się nieczysty, a nie jest tego świadomy, a potem się o tym dowie, będzie winny;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 4, 'Albo jeśli ktoś przysiągł, mówiąc wargami, że źle lub dobrze uczyni w czymkolwiek, co ów człowiek powie w przysiędze, a nie jest tego świadomy, lecz potem sobie uświadomi, będzie winny w jednej z tych rzeczy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 5, 'Jeśli więc jest winny jednej z tych rzeczy, ma wyznać swój grzech;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 6, 'I przyprowadzi Panu ofiarę za przewinienie z powodu swego grzechu, który popełnił: samicę z trzody, owcę albo kozę na ofiarę za grzech, a kapłan dokona za niego przebłagania za jego grzech.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 7, 'A jeśli nie stać go na owcę, niech przyniesie Panu jako ofiarę za swoje przewinienie, które popełnił, dwie synogarlice lub dwa młode gołębie: jednego na ofiarę za grzech, a drugiego na całopalenie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 8, 'I przyniesie je do kapłana, a on najpierw złoży to, co ma być na ofiarę za grzech, i ukręci jego głowę przy szyi, ale jej nie oddzieli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 9, 'I pokropi krwią tej ofiary za grzech ścianę ołtarza, a resztę krwi wyciśnie u podstawy ołtarza. To jest ofiara za grzech.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 10, 'Drugiego zaś złoży jako całopalenie według przepisu. W ten sposób kapłan dokona za niego przebłagania za jego grzech, który popełnił, i będzie mu przebaczony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 11, 'A jeśli nie stać go na dwie synogarlice lub dwa młode gołębie, niech ten, który zgrzeszył, przyniesie na swoją ofiarę dziesiątą część efy mąki pszennej na ofiarę za swój grzech. Nie naleje jednak na nią oliwy ani nie położy na nią kadzidła, gdyż jest to ofiara za grzech.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 12, 'Przyniesie ją do kapłana, a kapłan nabierze z niej pełną garść jako pamiątkę i spali ją na ołtarzu na ofiarach całopalnych dla Pana. To jest ofiara za grzech.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 13, 'I kapłan dokona za niego przebłagania za jego grzech, który popełnił w jednej z tych spraw, i będzie mu przebaczony. Reszta zaś będzie dla kapłana, jak przy ofierze pokarmowej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 14, 'Pan powiedział jeszcze do Mojżesza:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 15, 'Jeśli ktoś popełni przewinienie i zgrzeszy nieświadomie przy rzeczach poświęconych Panu, to przyprowadzi Panu jako ofiarę za swoje przewinienie barana bez skazy z trzody oraz twoje oszacowanie w syklach srebra według sykla świątynnego na ofiarę za przewinienie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 16, 'I odda kapłanowi za to, czym przewinił przy rzeczach poświęconych, i dołoży do tego jedną piątą. I kapłan dokona za niego przebłagania baranem, będącym ofiarą za przewinienie, a będzie mu przebaczone.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 17, 'Jeśli ktoś zgrzeszy i przekroczy nieświadomie którekolwiek z przykazań Pana, czyniąc to, czego nie wolno, stanie się winny i będzie obciążony nieprawością.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 18, 'Przyprowadzi do kapłana barana z trzody bez skazy według twojego oszacowania na ofiarę za przewinienie. A kapłan dokona za niego przebłagania za jego uchybienie, którego nieświadomie się dopuścił, i będzie mu przebaczone.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 19, 'Jest to ofiara za przewinienie, gdyż w istocie zawinił przeciwko Panu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 1, 'Potem Pan powiedział do Mojżesza:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 2, 'Jeśli ktoś zgrzeszy i popełni przewinienie przeciwko Panu przez to, że zaprze się wobec bliźniego rzeczy powierzonej lub oddanej do przechowania, lub zrabowanej, albo przez to, że oszukał bliźniego;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 3, 'Albo jeśli znalazł rzecz zgubioną i zaprzeczał temu lub przysięgał fałszywie w jakiejkolwiek z tych spraw, które człowiek czyni, i przez to grzeszy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 4, 'Skoro więc tak zgrzeszył i stał się winnym, zwróci to, co zrabował lub zdobył przez oszustwo, lub to, co mu powierzono, lub rzecz zgubioną, którą znalazł;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 5, 'Albo to, o czymkolwiek fałszywie przysięgał. Zwróci całą należność i dołoży do niej jedną piątą, i odda temu, do kogo to należało, w dniu swojej ofiary za przewinienie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 6, 'A do kapłana przyprowadzi Panu ofiarę za swoje przewinienie: barana z trzody bez skazy według twego oszacowania na ofiarę za przewinienie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 7, 'I kapłan dokona za niego przebłagania przed Panem, i będzie mu przebaczone, cokolwiek uczynił, przez co stał się winny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 8, 'I Pan powiedział do Mojżesza:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 9, 'Rozkaż Aaronowi i jego synom: Takie jest prawo całopalenia: Jest to całopalenie, bo będzie palone na ołtarzu przez całą noc aż do rana; a ogień na ołtarzu nieustannie będzie płonął.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 10, 'I kapłan włoży swoją lnianą szatę i na swoje ciało lniane spodnie oraz zbierze popiół z całopalenia, które ogień strawił na ołtarzu, i wysypie go obok ołtarza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 11, 'Potem zdejmie swe szaty i ubierze się w inne, i wyniesie popiół za obóz, na czyste miejsce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 12, 'A ogień na ołtarzu będzie płonął nieustannie, nie będzie gaszony. Kapłan rozpali na nim drwa każdego ranka i położy na nim ofiarę całopalną, i spali na nim tłuszcz ofiar pojednawczych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 13, 'Ogień będzie płonął na ołtarzu nieustannie, nie będzie gaszony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 14, 'Takie jest prawo ofiary pokarmowej: Synowie Aarona będą ją składać przed Panem, przed ołtarzem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 15, 'Kapłan weźmie garść mąki z ofiary pokarmowej wraz z oliwą i całym kadzidłem, które będzie na ofierze pokarmowej, i spali to na ołtarzu jako pamiątkę na miłą woń dla Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 16, 'A to, co z niej zostanie, będą jeść Aaron i jego synowie. Będzie to spożywane bez zakwasu na miejscu świętym, spożyją to na dziedzińcu Namiotu Zgromadzenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 17, 'Nie będą tego piec na zakwasie. Dałem to im bowiem jako ich dział z moich ofiar ogniowych; jest to rzecz najświętsza, tak jak ofiara za grzech i ofiara za przewinienie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 18, 'Każdy mężczyzna spośród synów Aarona będzie to spożywać. Jest to ustawa wieczna dla waszych pokoleń, dotycząca ofiar ogniowych Pana. Każdy, kto ich dotknie, będzie poświęcony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 19, 'Potem Pan powiedział do Mojżesza:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 20, 'Taka jest ofiara Aarona i jego synów, którą będą składać Panu w dniu swego namaszczenia: dziesiąta część efy mąki pszennej jako nieustanna ofiara pokarmowa, połowa jej rano, a połowa wieczorem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 21, 'Będzie ona przyrządzona na patelni z oliwą. Przyniesiesz ją smażoną i będziesz składać w kawałkach jako ofiarę pokarmową na miłą woń dla Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 22, 'Kapłan namaszczony na jego miejsce spośród jego synów będzie ją składać. Jest to ustawa wieczna dla Pana, cała będzie spalona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 23, 'I każda kapłańska ofiara pokarmowa będzie spalona w całości. Nie może być spożywana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 24, 'Potem Pan powiedział do Mojżesza:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 25, 'Powiedz Aaronowi i jego synom: Takie jest prawo ofiary za grzech: Na miejscu, gdzie będzie zabijana ofiara całopalna, zostanie zabita przed Panem ofiara za grzech. Jest to rzecz najświętsza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 26, 'Kapłan, który będzie ją składał za grzech, będzie ją jeść. Będzie spożywana na miejscu świętym, na dziedzińcu Namiotu Zgromadzenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 27, 'Każdy, kto dotknie jej mięsa, będzie poświęcony. A jeśli szata będzie opryskana jej krwią, wypierzesz na miejscu świętym to, co zostało opryskane.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 28, 'A naczynie gliniane, w którym ją gotowano, zostanie stłuczone. A jeśli była gotowana w naczyniu miedzianym, zostanie wyszorowane i wypłukane wodą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 29, 'Każdy mężczyzna spośród kapłanów będzie ją jeść. Jest to rzecz najświętsza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 30, 'A żadna ofiara za grzech, której krew wnosi się do Namiotu Zgromadzenia dla oczyszczenia w świątyni, nie będzie jedzona, lecz zostanie spalona w ogniu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 1, 'Takie jest prawo ofiary za przewinienie: jest to rzecz najświętsza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 2, 'Na miejscu, gdzie zabijają ofiarę całopalną, zabiją ofiarę za przewinienie, a pokropią jej krwią z wierzchu dokoła ołtarz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 3, 'I kapłan złoży w ofierze cały jej tłuszcz, ogon i tłuszcz pokrywający wnętrzności;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 4, 'Obie nerki z tłuszczem, który jest na nich i na lędźwiach, i płat tłuszczu na wątrobie, który oddzieli wraz z nerkami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 5, 'I kapłan spali to na ołtarzu jako ofiarę ogniową dla Pana. To jest ofiara za przewinienie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 6, 'Każdy mężczyzna spośród kapłanów będzie z niej jeść, będzie spożywana na miejscu świętym. Jest to rzecz najświętsza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 7, 'Zarówno do ofiary za grzech, jak i do ofiary za przewinienie odnosi się jednakowe prawo: będą one należeć do tego kapłana, który dokonuje przebłagania.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 8, 'Do kapłana, który składa czyjąś ofiarę całopalną, będzie należeć skóra tej ofiary, którą złożył.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 9, 'Także każda ofiara pokarmowa upieczona w piecu i wszystko, co przyrządzone w rondlu albo na patelni, będzie należeć do kapłana, który je składa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 10, 'Lecz każda ofiara pokarmowa zmieszana z oliwą albo sucha będzie należeć do wszystkich synów Aarona, do każdego w równej części.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 11, 'A takie jest prawo ofiary pojednawczej, którą będzie się składać Panu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 12, 'Jeśli ktoś składa ją jako ofiarę dziękczynną, złoży z ofiarą dziękczynną przaśne placki zmieszane z oliwą, przaśne podpłomyki pomazane oliwą i placki z mąki pszennej zmieszane z oliwą i smażone.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 13, 'Oprócz tych placków złoży jako ofiarę chleb zakwaszony wraz z ofiarą dziękczynną ze swoich ofiar pojednawczych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 14, 'I z niego będzie składał Panu po jednym chlebie z każdej ofiary jako ofiarę wzniesienia. Będzie to należeć do kapłana, który kropi krwią ofiar pojednawczych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 15, 'Mięso z dziękczynnej ofiary pojednawczej należy spożyć w dniu składania jego ofiary; nic z niego nie zostawią do rana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 16, 'A jeśli jego ofiara jest darem ślubowanym lub dobrowolnym, należy ją spożyć w dniu jej złożenia; a to, co z niej zostanie, spożyją nazajutrz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 17, 'Lecz jeśli coś z mięsa tej ofiary zostanie do trzeciego dnia, będzie spalone w ogniu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 18, 'A jeśli ktoś zje mięso tej ofiary pojednawczej trzeciego dnia, nie zostanie przyjęta ani nie zostanie policzona temu, który ją złożył. Będzie to obrzydliwością, a kto ją spożyje, będzie obciążony nieprawością.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 19, 'Mięso, które dotknie czegoś nieczystego, nie będzie spożywane, ale zostanie spalone w ogniu. Inne mięso zaś może jeść każdy, kto jest czysty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 20, 'A ktokolwiek spożyje mięso z ofiary pojednawczej, która należy do Pana, będąc nieczysty, to taki człowiek zostanie wykluczony ze swego ludu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 21, 'A kto dotknie czegoś nieczystego: nieczystości ludzkiej lub nieczystego zwierzęcia lub jakiejkolwiek nieczystej obrzydliwości, a spożyje mięso z ofiary pojednawczej, która należy do Pana, to taki człowiek zostanie wykluczony ze swego ludu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 22, 'Pan powiedział jeszcze do Mojżesza:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 23, 'Powiedz synom Izraela: Nie będziecie jedli żadnego tłuszczu wołu, owcy ani kozy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 24, 'Tłuszcz zwierzęcia padłego lub tłuszcz rozszarpanego może być używany do wszelkich celów, ale spożywać go nie wolno.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 25, 'Ktokolwiek bowiem spożyje tłuszcz zwierzęcia złożonego Panu jako ofiarę ogniową, ten zostanie wykluczony ze swego ludu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 26, 'Żadnej krwi nie będziecie jeść we wszystkich waszych mieszkaniach – ani z ptaków, ani ze zwierząt.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 27, 'Każdy człowiek, który spożyje jakąkolwiek krew, zostanie wykluczony ze swego ludu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 28, 'Pan powiedział jeszcze do Mojżesza:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 29, 'Powiedz synom Izraela: Kto będzie składał Panu ofiarę pojednawczą, niech przyniesie Panu swoją ofiarę ze swoich ofiar pojednawczych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 30, 'Własnoręcznie przyniesie Panu ofiarę ogniową; przyniesie tłuszcz wraz z mostkiem, aby kołysać nim jako ofiarą kołysaną przed Panem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 31, 'Potem kapłan spali tłuszcz na ołtarzu, a mostek będzie należał do Aarona i jego synów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 32, 'A prawą łopatkę oddacie kapłanowi jako ofiarę wzniesienia z waszych ofiar pojednawczych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 33, 'Kto spośród synów Aarona będzie składał krew ofiar pojednawczych i tłuszcz, weźmie jako swoją część prawą łopatkę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 34, 'Gdyż mostek kołysania i łopatkę wzniesienia wziąłem od synów Izraela z ich ofiar pojednawczych i dałem je kapłanowi Aaronowi oraz jego synom od synów Izraela na mocy wiecznej ustawy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 35, 'To jest część z ofiar ogniowych Pana z powodu namaszczenia Aarona i jego synów od dnia, kiedy przyprowadził ich, aby pełnili służbę kapłańską dla Pana;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 36, 'O którym Pan rozkazał, aby im dawano od synów Izraela w dniu, w którym ich namaścił, na mocy wiecznej ustawy dla ich pokoleń.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 37, 'Takie jest prawo całopalenia, ofiary pokarmowej, ofiary za grzech, ofiary za przewinienie, ofiary poświęcenia i ofiary pojednawczej;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 38, 'Które Pan nadał Mojżeszowi na górze Synaj w dniu, kiedy nakazał synom Izraela, aby składali swoje ofiary Panu na pustyni Synaj.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 1, 'Potem Pan powiedział do Mojżesza:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 2, 'Weź Aarona i z nim jego synów, ich szaty, oliwę do namaszczenia, cielca na ofiarę za grzech, dwa barany i kosz przaśnych chlebów;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 3, 'I zgromadź cały lud przy wejściu do Namiotu Zgromadzenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 4, 'I Mojżesz zrobił tak, jak mu Pan rozkazał; i zgromadził się cały lud przy wejściu do Namiotu Zgromadzenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 5, 'Wtedy Mojżesz powiedział do zgromadzenia: Oto co Pan rozkazał uczynić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 6, 'I kazał Mojżesz zbliżyć się Aaronowi i jego synom, i obmył ich wodą;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 7, 'Potem włożył tunikę na niego i przepasał go pasem, ubrał go w płaszcz, nałożył na niego efod i przepasał go pasem efodu, i przymocował go nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 8, 'Włożył też na niego pektorał i do pektorału włożył Urim i Tummim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 9, 'Włożył także na jego głowę mitrę, a na mitrze z przodu umieścił złotą blaszkę, świętą koronę, jak Pan rozkazał Mojżeszowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 10, 'Mojżesz wziął też oliwę do namaszczenia i namaścił przybytek oraz wszystkie rzeczy, które w nim były, i poświęcił je.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 11, 'Potem pokropił nią ołtarz siedem razy i namaścił ołtarz wraz ze wszystkimi jego przyborami, również kadź i jej podstawę, aby je poświęcić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 12, 'Wylał także oliwę do namaszczenia na głowę Aarona i namaścił go, aby go poświęcić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 13, 'Potem Mojżesz kazał zbliżyć się synom Aarona, włożył na nich tuniki, przepasał ich pasami i włożył im na głowy mitry, jak Pan rozkazał Mojżeszowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 14, 'Przyprowadził też cielca na ofiarę za grzech, a Aaron i jego synowie włożyli ręce na głowę cielca ofiary za grzech.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 15, 'Następnie Mojżesz zabił go, wziął jego krew i pomazał palcem rogi ołtarza dokoła, i oczyścił ołtarz. Resztę zaś krwi wylał u podstawy ołtarza i poświęcił go dla dokonywania na nim przebłagania.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 16, 'Potem wziął cały tłuszcz pokrywający wnętrzności, płat tłuszczu na wątrobie i obie nerki razem z ich tłuszczem i spalił to Mojżesz na ołtarzu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 17, 'A cielca, jego skórę, mięso i odchody spalił w ogniu poza obozem, tak jak Pan rozkazał Mojżeszowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 18, 'Potem przyprowadził barana na całopalenie. I Aaron, i jego synowie włożyli ręce na głowę tego barana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 19, 'Mojżesz zabił go i pokropił jego krwią ołtarz dokoła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 20, 'Potem podzielił barana na części i spalił Mojżesz głowę, części i tłuszcz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 21, 'Wnętrzności zaś i nogi opłukał wodą; i Mojżesz spalił całego barana na ołtarzu. Jest to całopalenie na miłą woń, ofiara ogniowa dla Pana, jak Pan rozkazał Mojżeszowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 22, 'Potem kazał przyprowadzić drugiego barana, barana poświęcenia. I Aaron, i jego synowie włożyli ręce na głowę tego barana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 23, 'I Mojżesz zabił go, wziął nieco z jego krwi i pomazał nią koniec prawego ucha Aarona, kciuk jego prawej ręki i wielki palec jego prawej nogi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 24, 'Kazał też zbliżyć się synom Aarona i pomazał Mojżesz tą krwią koniec ich prawego ucha, kciuki ich prawej ręki i wielkie palce ich prawej nogi. I Mojżesz pokropił krwią dokoła ołtarza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 25, 'Potem wziął tłuszcz, ogon, cały tłuszcz pokrywający wnętrzności, płat tłuszczu na wątrobie oraz obie nerki z ich tłuszczem i prawą łopatkę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 26, 'Także z kosza przaśnych chlebów, który był przed Panem, wziął jeden przaśny placek, jeden placek chleba z oliwą oraz jeden podpłomyk i położył je na kawałki tłuszczu i na prawej łopatce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 27, 'I dał to wszystko do rąk Aarona i do rąk jego synów i kołysał to jako ofiarę kołysaną przed Panem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 28, 'Następnie Mojżesz wziął to z ich rąk i spalił na ołtarzu na ofierze całopalnej. To była ofiara poświęcenia na miłą woń, ofiara ogniowa dla Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 29, 'Mojżesz wziął też mostek i kołysał go jako ofiarę kołysaną przed Panem. Była to bowiem część Mojżesza z barana poświęcenia, jak mu Pan rozkazał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 30, 'Wziął też Mojżesz trochę oliwy do namaszczenia i nieco krwi z ołtarza, i pokropił nimi Aarona i jego szaty, a także jego synów i ich szaty. Tak poświęcił Aarona i jego szaty, jego synów i ich szaty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 31, 'I Mojżesz powiedział do Aarona i jego synów: Ugotujcie to mięso przy wejściu do Namiotu Zgromadzenia i tam je spożywajcie wraz z chlebem, który jest w koszu poświęcenia, jak przykazałem: Aaron i jego synowie będą to spożywać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 32, 'A to, co pozostanie z mięsa i chleba, spalicie w ogniu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 33, 'Nie odchodźcie od wejścia do Namiotu Zgromadzenia przez siedem dni, aż do dnia, kiedy wypełni się czas waszego poświęcenia. Przez siedem dni bowiem będziecie poświęcani.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 34, 'Tak jak dziś uczyniono, tak Pan nakazał czynić, aby dokonać za was przebłagania.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 35, 'Dlatego przy wejściu do Namiotu Zgromadzenia będziecie przebywać dzień i noc przez siedem dni i będziecie pełnili straż Pana, abyście nie pomarli. Tak mi bowiem rozkazano.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 36, 'I Aaron oraz jego synowie uczynili to wszystko, co im Pan rozkazał przez Mojżesza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 1, 'A ósmego dnia Mojżesz wezwał Aarona, jego synów i starszych Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 2, 'I powiedział do Aarona: Weź sobie młodego cielca na ofiarę za grzech i barana na całopalenie, oba bez skazy, i złóż je w ofierze przed Panem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 3, 'A do synów Izraela powiesz: Weźcie kozła z kóz na ofiarę za grzech oraz cielca i barana, jednoroczne i bez skazy, na całopalenie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 4, 'Także wołu i barana na ofiary pojednawcze, by złożyć je przed Panem, i ofiarę pokarmową zmieszaną z oliwą; bo dziś Pan wam się ukaże.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 5, 'I przyprowadzili to, co Mojżesz rozkazał, przed Namiot Zgromadzenia. A cały lud zbliżył się i stanął przed Panem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 6, 'Wtedy Mojżesz powiedział: Oto co Pan nakazał wam uczynić; a ukaże się wam chwała Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 7, 'Do Aarona zaś Mojżesz powiedział: Zbliż się do ołtarza i złóż swoją ofiarę za grzech i swoje całopalenie, i dokonaj przebłagania za siebie i lud. Złóż też ofiarę ludu i dokonaj za niego przebłagania, jak Pan rozkazał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 8, 'Aaron zbliżył się więc do ołtarza i zabił cielca na ofiarę za grzech za siebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 9, 'I synowie Aarona podali mu krew, a on umoczył swój palec we krwi i pomazał nią rogi ołtarza, a resztę krwi wylał u podstawy ołtarza;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 10, 'Ale tłuszcz, nerki i płat tłuszczu na wątrobie z ofiary za grzech spalił na ołtarzu, jak Pan rozkazał Mojżeszowi;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 11, 'Mięso zaś i skórę spalił w ogniu poza obozem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 12, 'Zabił też ofiarę całopalną, a synowie Aarona podali mu krew, którą pokropił ołtarz dokoła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 13, 'Przynieśli mu też ofiarę całopalną podzieloną na części wraz z głową, a on spalił to na ołtarzu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 14, 'Obmył też wnętrzności oraz nogi i spalił je z ofiarą całopalną na ołtarzu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 15, 'Potem przyprowadził ofiarę ludu. Wziął kozła przeznaczonego na ofiarę za grzech za lud, zabił go i złożył na ofiarę za grzech, tak jak poprzednio.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 16, 'Przyprowadził też ofiarę całopalną i uczynił z nią według przepisu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 17, 'Przyprowadził też ofiarę pokarmową. Wziął z niej pełną garść i spalił na ołtarzu, oprócz ofiary całopalnej porannej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 18, 'Zabił też wołu i barana jako ofiarę pojednawczą za lud. I synowie Aarona podali mu krew, którą pokropił ołtarz dokoła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 19, 'Podali mu także tłuszcz z wołu i barana, ogon, tłuszcz pokrywający wnętrzności oraz nerki i płat tłuszczu na wątrobie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 20, 'Włożyli też tłuszcz na mostkach, a on spalił tłuszcz na ołtarzu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 21, 'Mostki zaś i prawą łopatkę Aaron kołysał na ofiarę kołysaną przed Panem, jak Mojżesz nakazał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 22, 'Potem Aaron podniósł ręce w stronę ludu i pobłogosławił go, a po złożeniu ofiary za grzech, ofiary całopalnej i ofiary pojednawczej zszedł na dół.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 23, 'Wtedy Mojżesz i Aaron weszli do Namiotu Zgromadzenia, potem wyszli i pobłogosławili lud. I chwała Pana ukazała się całemu ludowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 24, 'I wyszedł ogień sprzed Pana, i strawił na ołtarzu ofiarę całopalną oraz tłuszcz. A gdy cały lud to ujrzał, krzyknął z radości i upadł na twarz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 1, 'A Nadab i Abihu, synowie Aarona, wzięli każdy swoją kadzielnicę, włożyli do nich ogień, nałożyli na nie kadzidła i ofiarowali przed Panem obcy ogień, którego im nie nakazał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 2, 'Wtedy wyszedł ogień sprzed Pana i pochłonął ich, i pomarli przed Panem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 3, 'Wówczas Mojżesz powiedział do Aarona: Oto co Pan powiedział: W tych, którzy zbliżają się do mnie, będę uświęcony i będę uwielbiony przed całym ludem. I Aaron zamilkł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 4, 'Mojżesz wezwał Miszaela i Elsafana, synów Uzziela, stryja Aarona, i powiedział do nich: Zbliżcie się i wynieście waszych braci sprzed świątyni poza obóz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 5, 'Podeszli więc i wynieśli ich w ich tunikach poza obóz, jak Mojżesz nakazał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 6, 'Potem Mojżesz powiedział do Aarona i jego synów, Eleazara i Itamara: Nie obnażajcie swoich głów ani nie rozdzierajcie swoich szat, abyście nie pomarli i aby Bóg nie rozgniewał się na całe zgromadzenie. Lecz wasi bracia, cały dom Izraela, niech opłakują ten pożar, który Pan rozpalił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 7, 'Nie odchodźcie od wejścia do Namiotu Zgromadzenia, abyście nie pomarli, ponieważ oliwa namaszczenia Pana jest na was. I postąpili według słowa Mojżesza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 8, 'Następnie Pan powiedział do Aarona:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 9, 'Nie pij wina ani mocnego napoju, ani ty, ani twoi synowie z tobą, gdy będziecie wchodzić do Namiotu Zgromadzenia, abyście nie pomarli. To będzie ustawa wieczna dla wszystkich waszych pokoleń;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 10, 'Abyście mogli rozróżniać między tym, co święte, a tym, co pospolite, między tym, co nieczyste, a tym, co czyste;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 11, 'I abyście nauczali synów Izraela wszystkich ustaw, które Pan nakazał im przez Mojżesza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 12, 'I Mojżesz powiedział do Aarona oraz jego pozostałych synów, Eleazara i Itamara: Weźcie ofiarę pokarmową, która pozostała z ofiar ogniowych Pana, i jedzcie ją bez zakwasu przy ołtarzu. Jest to bowiem rzecz najświętsza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 13, 'Będziecie ją spożywać w miejscu świętym, bo jest to część należna tobie i twoim synom z ofiar ogniowych Pana. Tak mi bowiem rozkazano.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 14, 'Także mostek kołysania i łopatkę wzniesienia będziecie spożywać w miejscu czystym, ty, twoi synowie i twoje córki z tobą. To bowiem należy się tobie, a także twoim synom, dane wam z ofiar pojednawczych synów Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 15, 'Przyniosą łopatkę wzniesienia i mostek kołysania wraz z tłuszczem z ofiar ogniowych, aby kołysać je przed Panem; a będzie to dla ciebie i twoich synów z tobą na mocy ustawy wiecznej, tak jak Pan rozkazał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 16, 'Potem Mojżesz pilnie szukał kozła na ofiarę za grzech, ale okazało się, że został on już spalony. I rozgniewał się na synów Aarona, Eleazara i Itamara, którzy mu pozostali, i mówił:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 17, 'Dlaczego nie zjedliście ofiary za grzech w miejscu świętym? Przecież jest ona rzeczą najświętszą, którą dano wam, abyście nosili nieprawość całego ludu, abyście dokonali za niego przebłagania przed Panem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 18, 'Oto jej krwi nie wniesiono do wnętrza miejsca świętego. Powinniście byli ją jeść na miejscu świętym, jak nakazałem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 19, 'Wtedy Aaron odpowiedział Mojżeszowi: Oto dziś złożyli swoją ofiarę za grzech i swoją ofiarę całopalną przed Panem, a taka rzecz mnie spotkała. Gdybym dziś spożył ofiarę za grzech, czy to by się spodobało Panu?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 20, 'Gdy Mojżesz to usłyszał, uznał to za słuszne.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 1, 'Potem Pan przemówił do Mojżesza i Aarona tymi słowy:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 2, 'Powiedzcie synom Izraela: Oto są zwierzęta, które będziecie mogli jeść spośród wszystkich zwierząt, które są na ziemi;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 3, 'Wszystkie zwierzęta, które mają rozdzielone kopyta i racice oraz przeżuwają – je możecie jeść.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 4, 'Jednak spośród tych, które przeżuwają albo mają tylko rozdzielone kopyta, nie będziecie jedli: wielbłąda, który choć przeżuwa, ale nie ma rozdzielonego kopyta – będzie dla was nieczysty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 5, 'Także królika, który choć przeżuwa, ale nie ma rozdzielonego kopyta – będzie dla was nieczysty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 6, 'Również zająca, który choć przeżuwa, ale nie ma rozdzielonego kopyta – będzie dla was nieczysty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 7, 'Świni, która choć ma rozdzielone kopyto i racice, ale nie przeżuwa – będzie dla was nieczysta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 8, 'Nie będziecie jeść ich mięsa ani dotykać ich padliny – będą dla was nieczyste.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 9, 'To będziecie jeść spośród wszystkiego, co żyje w wodach: wszystko, co w wodach – w morzach i rzekach – ma płetwy i łuski. To będziecie jeść.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 10, 'Wszystko zaś, co nie ma płetw ani łusek w morzach i rzekach spośród wszystkiego, co się porusza w wodach, i spośród wszystkich stworzeń wodnych, będzie dla was obrzydliwością.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 11, 'Będą dla was obrzydliwością; nie będziecie jedli ich mięsa, a ich padliną będziecie się brzydzić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 12, 'Wszystko w wodach, co nie ma płetw ani łusek, będzie dla was obrzydliwością.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 13, 'Tymi zaś będziecie się brzydzić z ptactwa i jeść ich nie będziecie, bo są obrzydliwością: orzeł, orłosęp i rybołów;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 14, 'Sęp i kania według ich rodzaju;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 15, 'Wszelki kruk według jego rodzaju;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 16, 'Struś, sowa, mewa i jastrząb według ich rodzaju;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 17, 'Puszczyk, kormoran i puchacz;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 18, 'Łabędź, pelikan i ścierwnik;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 19, 'Bocian, czapla według jej rodzaju, dudek i nietoperz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 20, 'Wszelkie skrzydlate owady chodzące na czterech odnóżach będą dla was obrzydliwością.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 21, 'Jednak spośród wszystkich skrzydlatych owadów, które mają cztery odnóża, możecie jeść te, które mają z tyłu przedłużone odnóża do skakania po ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 22, 'Te z nich możecie jeść: szarańcza według jej rodzaju, szarańcza pustynna według jej rodzaju, skoczek według jego rodzaju i konik polny według jego rodzaju.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 23, 'Wszelkie zaś inne skrzydlate pełzające istoty mające cztery odnóża będą dla was obrzydliwością.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 24, 'Przez nie staniecie się nieczyści. Każdy, kto dotknie ich padliny, będzie nieczysty aż do wieczora;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 25, 'A ktokolwiek będzie nosił ich padlinę, upierze swoje szaty i będzie nieczysty aż do wieczora.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 26, 'Padlina wszystkich zwierząt, które mają rozdzielone kopyto, ale nie mają racicy i nie przeżuwają, będzie dla was nieczysta. Każdy, kto jej dotknie, będzie nieczysty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 27, 'A wszystko, co chodzi na łapach spośród wszystkich zwierząt chodzących na czterech nogach, będzie dla was nieczyste. Kto dotknie ich padliny, będzie nieczysty aż do wieczora.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 28, 'A kto będzie nosił ich padlinę, upierze swoje szaty i będzie nieczysty aż do wieczora. Są one dla was nieczyste.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 29, 'Także spośród zwierząt, które pełzają po ziemi, będą dla was nieczyste: łasica, mysz i żółw według ich rodzaju;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 30, 'Jeż, jaszczurka, tchórz, ślimak i kret.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 31, 'Te będą dla was nieczyste spośród wszystkich pełzających zwierząt. Kto ich dotknie, gdy są martwe, będzie nieczysty aż do wieczora.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 32, 'A każda rzecz, na którą upadnie coś zdechłego z nich, będzie nieczysta, zarówno drewniane naczynie, jak i szata, a także skóra, worek lub jakikolwiek inny przedmiot, którym wykonuje się pracę; należy je włożyć do wody i będzie nieczyste aż do wieczora. Potem będzie czyste.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 33, 'Wszelkie zaś gliniane naczynie, do którego wpadnie którekolwiek z nich, wraz ze wszystkim, co znajduje się w nim, będzie nieczyste, a naczynie rozbijecie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 34, 'Każdy pokarm, który się spożywa, do którego dostanie się woda z tego naczynia, będzie nieczysty. I wszelki napój, który by się piło z takiego naczynia, będzie nieczysty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 35, 'Wszystko, na co upadnie cokolwiek z ich padlin, będzie nieczyste, czy to piec, czy palenisko; mają być zniszczone. Są bowiem nieczyste i będą dla was nieczyste.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 36, 'Lecz źródło i studnie, zbiorniki wody, będą czyste. Cokolwiek jednak dotknie ich padliny, będzie nieczyste.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 37, 'A jeśli coś z ich padliny upadnie na jakiekolwiek ziarno przeznaczone do siewu, to pozostanie czyste.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 38, 'Jeśli jednak coś z ich padliny upadnie na ziarno zmoczone wodą, będzie ono dla was nieczyste.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 39, 'Jeśli zdechnie zwierzę, które możecie jeść, to ten, kto dotknie jego padliny, będzie nieczysty aż do wieczora.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 40, 'A kto by jadł jego padlinę, upierze swoje szaty i będzie nieczysty aż do wieczora. Ten, kto by wynosił tę padlinę, upierze swoje szaty i będzie nieczysty aż do wieczora.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 41, 'Także wszelkie zwierzęta pełzające po ziemi są obrzydliwością; nie będziecie ich jeść.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 42, 'Niczego, co pełza na brzuchu, i niczego, co chodzi na czterech lub więcej odnóżach spośród wszystkich zwierząt pełzających po ziemi, nie będziecie jeść, bo są obrzydliwością.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 43, 'Nie plugawcie siebie samych przez wszelkie te zwierzęta pełzające po ziemi i nie zanieczyszczajcie się nimi, byście nie stali się nieczyści;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 44, 'Gdyż ja jestem Pan, wasz Bóg. Uświęcajcie się więc i bądźcie świętymi, bo ja jestem święty. I nie zanieczyszczajcie się żadnym zwierzęciem pełzającym po ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 45, 'Gdyż ja jestem Pan, który was wyprowadził z ziemi Egiptu, aby być waszym Bogiem. Bądźcie więc świętymi, bo ja jestem święty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 46, 'To jest prawo dotyczące zwierząt, ptactwa i wszelkich żywych istot poruszających się w wodach, a także wszelkich istot pełzających po ziemi;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 47, 'Dla rozróżnienia między nieczystym a czystym, między zwierzętami, które można jeść, a których jeść nie wolno.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 1, 'I Pan przemówił do Mojżesza:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 2, 'Powiedz synom Izraela: Jeśli kobieta pocznie i urodzi chłopca, będzie nieczysta przez siedem dni; jak w dniach jej odłączenia z powodu swej miesięcznej słabości, będzie nieczysta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 3, 'A ósmego dnia zostanie obrzezany jego napletek.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 4, 'Potem ona pozostanie przez trzydzieści trzy dni we krwi swego oczyszczenia; nie dotknie żadnej świętej rzeczy ani nie wejdzie do świątyni, aż wypełnią się dni jej oczyszczenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 5, 'A jeśli urodzi dziewczynkę, będzie nieczysta przez dwa tygodnie, jak podczas jej odłączenia. Potem pozostanie przez sześćdziesiąt sześć dni we krwi swego oczyszczenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 6, 'A gdy wypełnią się dni jej oczyszczenia po synu lub po córce, przyniesie do kapłana przed wejście do Namiotu Zgromadzenia rocznego baranka na całopalenie i młodego gołębia lub synogarlicę na ofiarę za grzech;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 7, 'Ten złoży to w ofierze przed Panem i dokona za nią przebłagania; i tak będzie oczyszczona od upływu swojej krwi. Takie jest prawo dla tej, która urodziła chłopca lub dziewczynkę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 8, 'A jeśli nie może przynieść baranka, to przyniesie dwie synogarlice lub dwa młode gołębie: jednego na całopalenie, a drugiego na ofiarę za grzech. I kapłan dokona za nią przebłagania i będzie czysta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 1, 'Pan powiedział dalej do Mojżesza i Aarona:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 2, 'Gdyby człowiek miał na skórze swego ciała nabrzmienie, wysypkę lub białą plamę i będzie to wyglądało na skórze jego ciała jak plaga trądu, zostanie przyprowadzony do kapłana Aarona lub do któregoś z jego synów, kapłanów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 3, 'Wtedy kapłan obejrzy chore miejsce na skórze jego ciała. Jeśli włos w tym miejscu zbielał i to miejsce zdaje się być bardziej wklęsłe niż pozostała skóra ciała, to jest to plaga trądu. Gdy kapłan go obejrzy, uzna go za nieczystego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 4, 'A jeśli plama na skórze jego ciała jest biała i z wyglądu nie jest głębsza niż skóra, i włosy na niej nie zbielały, wtedy kapłan odosobni chorego na siedem dni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 5, 'Potem kapłan obejrzy go siódmego dnia. Jeśli wydaje mu się, że chore miejsce zatrzymało się i nie rozszerzyło na skórze, wtedy kapłan odosobni go na kolejne siedem dni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 6, 'I kapłan ponownie obejrzy go siódmego dnia. Jeśli chore miejsce przyciemniało i nie rozszerzyło się na skórze, wtedy kapłan uzna go za czystego. Jest to wysypka. Wypierze on swoje szaty i będzie czysty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 7, 'Jeśli jednak wysypka mocno się rozszerzyła na skórze po obejrzeniu przez kapłana w celu oczyszczenia, pokaże się znowu kapłanowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 8, 'Jeśli kapłan zobaczy, że wysypka rozszerzyła się na skórze, uzna go za nieczystego. Jest to trąd.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 9, 'Gdy plaga trądu pojawi się na człowieku, zostanie przyprowadzony do kapłana;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 10, 'I kapłan obejrzy go. A jeśli jest na skórze białe nabrzmienie, przez które włosy zbielały, i na tym nabrzmieniu jest żywe mięso;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 11, 'Jest to zastarzały trąd na skórze jego ciała; i kapłan uzna go za nieczystego, a nie odosobni go, gdyż jest nieczysty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 12, 'A jeśli trąd rozszerza się na skórze i pokryje całą skórę zarażonego od głowy aż do stóp, gdziekolwiek kapłan spojrzy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 13, 'Wtedy kapłan obejrzy; a jeśli trąd pokrył całe jego ciało, uzna zarażonego za czystego. Cały zbielał, więc jest czysty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 14, 'Jednak w dniu, gdy ukaże się na nim żywe mięso, będzie nieczysty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 15, 'I kapłan obejrzy żywe mięso i uzna go za nieczystego. Żywe mięso bowiem jest nieczyste. Jest to trąd.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 16, 'Jeśli jednak żywe mięso ustąpi i stanie się białe, wtedy przyjdzie do kapłana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 17, 'I kapłan obejrzy go. Jeśli chore miejsce zbielało, kapłan uzna zarażonego za czystego. Jest on czysty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 18, 'Jeśli zaś na skórze pojawił się wrzód, a potem się zagoił;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 19, 'A na miejscu tego wrzodu pojawi się białe nabrzmienie lub białoczerwonawa plama, wtedy zostanie pokazana kapłanowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 20, 'I kapłan obejrzy ją, a jeśli z wyglądu jest głębsza niż skóra i włosy na niej zbielały, kapłan uzna go za nieczystego. Jest to plaga trądu, która rozwinęła się na wrzodzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 21, 'Jeśli jednak kapłan zobaczy, że nie ma na niej białych włosów i że nie jest głębsza niż skóra, ale pociemniała, wtedy kapłan odosobni go na siedem dni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 22, 'A jeśli rozszerza się mocno na skórze, kapłan uzna go za nieczystego. Jest to plaga trądu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 23, 'Jeśli jednak ta biała plama pozostanie na swoim miejscu i nie rozszerzy się, jest to zapalenie wrzodu; i kapłan uzna go za czystego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 24, 'Jeśli ktoś ma na skórze oparzelinę i na żywym mięsie pojawi się plama białoczerwonawa lub biała;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 25, 'To kapłan obejrzy ją. Jeśli włos na plamie zbielał i z wyglądu jest ona głębsza niż skóra, jest to trąd, który rozwinął się na oparzelinie. Kapłan uzna go więc za nieczystego. Jest to plaga trądu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 26, 'A jeśli kapłan zobaczy, że na tej plamie nie ma białych włosów ani nie jest ona głębsza niż skóra, ale pociemniała, to kapłan odosobni go na siedem dni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 27, 'W siódmym dniu kapłan go obejrzy. Jeśli mocno rozszerzyła się na skórze, kapłan uzna go za nieczystego. Jest to plaga trądu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 28, 'A jeśli ta plama pozostanie na swoim miejscu, a nie rozszerzyła się na skórze, ale pociemniała, jest to nabrzmienie po oparzeniu; i kapłan uzna go za czystego. Jest to zapalenie po oparzeniu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 29, 'Jeśli na głowie lub brodzie mężczyzny albo kobiety pojawi się chore miejsce;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 30, 'To kapłan obejrzy to miejsce. Jeśli z wyglądu jest głębsze niż skóra i włos na niej jest żółty i cienki, wtedy kapłan uzna takiego za nieczystego. Jest to łuszczyca, trąd na głowie lub na brodzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 31, 'Jeśli jednak kapłan obejrzy miejsce tego liszaju, a z wyglądu nie jest ono głębsze niż skóra i nie ma na nim czarnych włosów, to kapłan odosobni dotkniętego plagą liszaju na siedem dni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 32, 'W siódmym dniu kapłan obejrzy to miejsce. Jeśli liszaj nie rozszerzył się i nie ma na nim żółtych włosów, i liszaj z wyglądu nie jest głębszy niż skóra;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 33, 'To ten człowiek będzie ogolony, ale liszaju nie będzie golić; i kapłan odosobni dotkniętego liszajem na kolejne siedem dni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 34, 'Siódmego dnia kapłan obejrzy ten liszaj. Jeśli liszaj nie rozszerzył się na skórze i z wyglądu nie jest głębszy niż skóra, kapłan uzna go za czystego, a on wypierze swoje ubranie i będzie czysty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 35, 'A jeśli liszaj mocno się rozszerzył na skórze po jego oczyszczeniu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 36, 'To kapłan obejrzy go. Jeśli liszaj rozszerza się na skórze, kapłan nie będzie już szukał żółtego włosa, jest on nieczysty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 37, 'Jeśli jednak wydaje mu się, że liszaj pozostał bez zmiany i wyrosły na nim czarne włosy, to liszaj został wyleczony, jest on czysty i kapłan uzna go za czystego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 38, 'Jeśli u mężczyzny lub kobiety ukażą się na skórze ciała białe plamy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 39, 'To kapłan je obejrzy. Jeśli te białe plamy na skórze ich ciała są przyciemnione, jest to wyrzut, który się rozwinął na skórze; jest on czysty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 40, 'Także mężczyzna, któremu włosy wypadły z głowy, jest łysy, ale czysty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 41, 'A jeśli wypadły mu włosy z przodu głowy, to ma łyse czoło, ale jest czysty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 42, 'Jeśli jednak na łysinie albo na łysym czole pojawi się białoczerwonawa rana, jest to trąd, który się rozwinął na jego łysinie albo na łysym czole.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 43, 'I kapłan go obejrzy. Jeśli nabrzmienie rany jest białoczerwonawe na jego łysinie albo na łysym czole, jak wygląda trąd na skórze ciała;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 44, 'To taki człowiek jest trędowaty, jest on nieczysty. I kapłan uzna go za całkowicie nieczystego, bo na jego głowie jest jego trąd.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 45, 'Trędowaty zaś, który ma na sobie tę plagę, będzie miał rozdarte szaty, jego głowa będzie odkryta, zakryje sobie usta i będzie wołał: Nieczysty! Nieczysty!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 46, 'Przez wszystkie dni, póki jest na nim plaga, będzie skalany, bo jest nieczysty. Będzie mieszkał sam; jego mieszkanie będzie poza obozem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 47, 'Jeśli też na szacie będzie plaga trądu, na szacie wełnianej lub lnianej;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 48, 'Czy to na osnowie, czy na wątku z lnu lub wełny, czy też na skórze, czy na jakimkolwiek wyrobie skórzanym;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 49, 'A będzie to plaga zielonkawa albo czerwonawa na szacie lub na skórze, na osnowie lub na wątku, lub na jakimkolwiek przedmiocie skórzanym, jest to plaga trądu i będzie pokazana kapłanowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 50, 'Kapłan obejrzy tę plagę i odosobni zarażoną rzecz na siedem dni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 51, 'W siódmym dniu obejrzy tę plagę. Jeśli plaga rozszerzyła się na szacie czy na osnowie albo wątku, na skórze lub na jakimś przedmiocie wykonanym ze skóry, jest to plaga trądu złośliwego, przedmiot jest nieczysty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 52, 'Spali więc tę szatę czy osnowę albo wątek, czy to z wełny, czy z lnu, czy z jakiegokolwiek przedmiotu skórzanego, na którym jest plaga. Jest to bowiem trąd złośliwy, będzie spalony w ogniu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 53, 'Jeśli jednak kapłan zobaczy, że ta plaga nie rozszerzyła się na szacie ani na osnowie, ani na wątku, ani na jakimkolwiek przedmiocie skórzanym;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 54, 'To kapłan rozkaże, aby wyprano to, na czym jest plaga, i odosobni to na kolejne siedem dni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 55, 'I kapłan obejrzy plagę po wypraniu. Jeśli ta plaga nie zmieniła swojej barwy, choćby plaga nie rozszerzyła się, to jest to rzecz nieczysta, spalisz ją w ogniu; rzecz jest przeżarta bądź z wierzchniej, bądź ze spodniej strony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 56, 'Jeśli jednak kapłan zobaczy, że po wypraniu plaga pociemniała, oderwie ją z szaty lub ze skóry czy z osnowy, czy z wątku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 57, 'A jeśli nadal będzie widoczna na szacie czy na osnowie lub na wątku, albo na jakimś przedmiocie skórzanym, jest to szerzący się trąd. Spalisz w ogniu to, na czym jest ta plaga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 58, 'Szatę zaś lub osnowę czy wątek albo każdy przedmiot skórzany, z którego po wypraniu odeszłaby plaga, wypierzesz powtórnie i będzie to czyste.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 59, 'To jest prawo dotyczące plagi trądu na szacie wełnianej lub lnianej czy na osnowie, czy wątku albo na jakimkolwiek przedmiocie skórzanym, aby uznać je za czyste lub nieczyste.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 1, 'Potem Pan powiedział do Mojżesza:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 2, 'Takie będzie prawo dotyczące trędowatego w dniu jego oczyszczenia: będzie przyprowadzony do kapłana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 3, 'A kapłan wyjdzie poza obóz. Jeśli kapłan zobaczy, że plaga trądu została uleczona na trędowatym;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 4, 'To kapłan każe, by wziąć dla oczyszczającego się dwa żywe i czyste ptaki, drewno cedrowe, karmazyn i hizop.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 5, 'I kapłan każe zabić jednego ptaka nad naczyniem glinianym, nad wodą źródlaną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 6, 'Następnie weźmie żywego ptaka, drewno cedrowe, karmazyn i hizop i umoczy to wszystko z żywym ptakiem we krwi ptaka zabitego nad źródlaną wodą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 7, 'I pokropi siedem razy oczyszczającego się od trądu, i uzna go za czystego, a żywego ptaka wypuści na otwarte pole.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 8, 'Ten, który się poddaje oczyszczeniu, upierze swoje szaty, ogoli wszystkie swoje włosy, umyje się wodą i będzie czysty. Potem wejdzie do obozu i będzie mieszkał przez siedem dni poza swoim namiotem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 9, 'A siódmego dnia ogoli wszystkie swoje włosy, głowę, brodę i brwi nad swoimi oczami i ogoli wszystkie inne włosy. Potem wypierze swoje szaty i obmyje swoje ciało w wodzie, i będzie czysty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 10, 'Ósmego dnia weźmie dwa baranki bez skazy i jedną owcę jednoroczną bez skazy, trzy dziesiąte efy mąki pszennej zmieszanej z oliwą na ofiarę pokarmową i jeden log oliwy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 11, 'A kapłan dokonujący oczyszczenia postawi człowieka, który ma być oczyszczony, oraz to wszystko przed Panem, u wejścia do Namiotu Zgromadzenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 12, 'Potem kapłan weźmie jednego baranka i złoży go w ofierze za przewinienie wraz z logiem oliwy, i będzie to kołysał na ofiarę kołysania przed Panem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 13, 'Potem zabije tego baranka na miejscu, gdzie się zabija ofiarę za grzech i ofiarę całopalną, na miejscu świętym. Zarówno bowiem ofiara za grzech, jak i ofiara za przewinienie należą do kapłana. Jest to rzecz najświętsza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 14, 'Następnie kapłan weźmie nieco krwi z ofiary za przewinienie i pomaże nią koniuszek prawego ucha oczyszczającego się, kciuk jego prawej ręki i wielki palec jego prawej nogi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 15, 'Kapłan weźmie też nieco z logu oliwy i wyleje na swoją lewą dłoń;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 16, 'I umoczy swój prawy palec w oliwie, która jest na jego lewej dłoni, i tym palcem pokropi oliwą siedem razy przed Panem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 17, 'A z reszty oliwy, która jest na jego dłoni, kapłan pomaże koniuszek prawego ucha oczyszczającego się, kciuk jego prawej ręki i wielki palec jego prawej nogi nad miejscem pomazanym krwią ofiary za przewinienie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 18, 'A resztę oliwy, która jest na dłoni kapłana, wyleje na głowę oczyszczającego się. Tak kapłan dokona za niego przebłagania przed Panem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 19, 'Kapłan złoży także ofiarę za grzech i dokona przebłagania za oczyszczającego się ze swojej nieczystości, po czym zabije ofiarę całopalną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 20, 'I kapłan złoży na ołtarzu ofiarę całopalną i ofiarę pokarmową. Tak kapłan dokona za niego przebłagania i będzie on czysty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 21, 'Jeśli jednak jest on tak ubogi, że nie stać go na to, wtedy weźmie jednego baranka na ofiarę za przewinienie, na kołysanie, by dokonano za niego przebłagania, i jedną dziesiątą efy mąki pszennej zmieszanej z oliwą na ofiarę pokarmową oraz log oliwy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 22, 'I dwie synogarlice albo dwa młode gołębie, na co go stać; jeden będzie na ofiarę za grzech, a drugi na ofiarę całopalną;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 23, 'I przyniesie je ósmego dnia dla swego oczyszczenia do kapłana, przed wejście do Namiotu Zgromadzenia przed Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 24, 'Kapłan weźmie baranka na ofiarę za przewinienie oraz log oliwy i kapłan będzie to kołysał na ofiarę kołysania przed Panem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 25, 'Potem zabije baranka na ofiarę za przewinienie i kapłan weźmie nieco krwi ofiary za przewinienie, i pomaże koniuszek prawego ucha oczyszczającego się, kciuk jego prawej ręki i wielki palec jego prawej nogi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 26, 'Kapłan naleje także oliwy na swoją lewą dłoń.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 27, 'I oliwą, która jest na jego lewej dłoni, kapłan będzie kropić siedem razy swoim prawym palcem przed Panem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 28, 'Kapłan też pomaże tą oliwą, która jest na jego dłoni, koniuszek prawego ucha oczyszczającego się, kciuk jego prawej ręki i wielki palec jego prawej nogi nad miejscem pomazanym krwią ofiary za przewinienie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 29, 'A resztą oliwy, która jest na dłoni kapłana, pomaże głowę oczyszczającego się, aby dokonać za niego przebłagania przed Panem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 30, 'Potem złoży jedną synogarlicę albo jednego młodego gołębia, na co go było stać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 31, 'Z tego, na co go stać, jedno będzie na ofiarę za grzech, a drugie na ofiarę całopalną razem z ofiarą pokarmową. I tak kapłan dokona przebłagania za oczyszczającego się przed Panem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 32, 'To jest prawo dotyczące tego, na którym będzie plaga trądu, a którego nie stać na ofiarę za swoje oczyszczenie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 33, 'Potem Pan powiedział do Mojżesza i Aarona:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 34, 'Gdy wejdziecie do ziemi Kanaan, którą daję wam w posiadanie, a ja dopuszczę plagę trądu na jakimś domu z waszej posiadłości;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 35, 'To właściciel domu przyjdzie i powie kapłanowi: Zdaje mi się, jakby plaga trądu jest w moim domu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 36, 'Wówczas kapłan każe opróżnić dom, zanim sam wejdzie, aby obejrzeć tę plagę, żeby się nie zanieczyściło to wszystko, co jest w domu. Potem kapłan wejdzie, aby obejrzeć ten dom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 37, 'I obejrzy tę plagę. Jeśli zobaczy na ścianach domu, że plaga występuje jak dołki zielonkawe lub czerwonawe, które wydają się być głębsze niż ściana;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 38, 'Wtedy kapłan wyjdzie przed drzwi tego domu i zamknie ten dom na siedem dni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 39, 'Siódmego dnia kapłan wróci i obejrzy. Jeśli plaga rozszerzyła się na ścianach tego domu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 40, 'Kapłan każe wyrwać te kamienie, na których jest plaga, i wyrzucić je poza miasto na miejsce nieczyste;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 41, 'A dom każe oskrobać wewnątrz dokoła; i wysypią proch, który oskrobali, poza miasto na miejsce nieczyste;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 42, 'Potem wezmą inne kamienie i wstawią je na miejsce tamtych kamieni; wezmą też inny tynk i otynkują dom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 43, 'A jeśli ta plaga się odnowi i rozszerzy się w domu po wyrzuceniu kamienia, po oskrobaniu domu i po jego otynkowaniu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 44, 'Wtedy wejdzie kapłan i obejrzy. Jeśli zobaczy, że plaga się rozszerzyła w domu, jest to złośliwy trąd w tym domu. Jest on nieczysty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 45, 'Potem zburzy ten dom, jego kamienie, jego drewno i cały tynk tego domu, i wyniesie poza miasto na miejsce nieczyste.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 46, 'A kto by wszedł do tego domu podczas jego zamknięcia, będzie nieczysty aż do wieczora.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 47, 'Kto by spał w tym domu, wypierze swoje szaty, a kto by jadł w tym domu, wypierze swoje szaty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 48, 'Lecz jeśli kapłan wejdzie i zobaczy, że plaga nie szerzy się w domu po jego tynkowaniu, to kapłan uzna, że ten dom jest czysty, gdyż plaga została uleczona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 49, 'A weźmie na oczyszczenie tego domu dwa ptaki, drewno cedrowe, karmazyn i hizop;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 50, 'I zabije jednego ptaka nad glinianym naczyniem, nad wodą źródlaną;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 51, 'Potem weźmie drewno cedrowe, hizop, karmazyn oraz żywego ptaka i umoczy to wszystko we krwi zabitego ptaka i w źródlanej wodzie i pokropi ten dom siedem razy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 52, 'I tak oczyści ten dom krwią tego ptaka, źródlaną wodą, żywym ptakiem, drewnem cedrowym, hizopem i karmazynem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 53, 'Żywego zaś ptaka wypuści poza miasto na otwarte pole. Tak dokona przebłagania za ten dom i będzie on czysty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 54, 'Takie jest prawo dotyczące każdej plagi trądu i liszaju:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 55, 'Trądu na ubraniu i w domu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 56, 'Nabrzmienia, wysypki i białej plamy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 57, 'Aby pouczać, kiedy coś jest nieczyste, a kiedy czyste. To jest prawo dotyczące trądu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 1, 'Potem Pan powiedział do Mojżesza i Aarona:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 2, 'Przemówcie do synów Izraela i powiedzcie im: Jeśli mężczyzna ma wyciek ze swego ciała, to jest on nieczysty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 3, 'A na tym będzie polegała nieczystość jego wycieku: Jeśli jego ciało wypuszcza wyciek albo jeśli jego ciało zatrzymuje wyciek, to jest jego nieczystość.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 4, 'Każde posłanie, na którym będzie leżał chory na wyciek, będzie nieczyste, i wszystko, na czym usiądzie, będzie nieczyste.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 5, 'Kto dotknie jego posłania, wypierze swoje szaty i umyje się w wodzie, i będzie nieczysty aż do wieczora.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 6, 'A kto usiądzie na tym, na czym siedział chory na wyciek, wypierze swoje szaty i umyje się w wodzie, i będzie nieczysty aż do wieczora.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 7, 'A kto dotknie ciała mężczyzny chorego na wyciek, wypierze swoje szaty i umyje się w wodzie, i będzie nieczysty aż do wieczora.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 8, 'A jeśli chory na wyciek plunie na człowieka czystego, ten wypierze swoje szaty i umyje się w wodzie, i będzie nieczysty aż do wieczora.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 9, 'Każde też siodło, na którym będzie siedział chory na wyciek, będzie nieczyste.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 10, 'Kto dotknie jakiejkolwiek rzeczy, która była pod nim, będzie nieczysty aż do wieczora. A kto przenosi cokolwiek z tego, wypierze swoje szaty i umyje się w wodzie, i będzie nieczysty aż do wieczora.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 11, 'Każdy też, kogo dotknie chory na wyciek, który nie umył swoich rąk w wodzie, wypierze swoje szaty i umyje się w wodzie, i będzie nieczysty aż do wieczora.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 12, 'A naczynie gliniane, którego dotknie chory na wyciek, będzie stłuczone, a każde drewniane naczynie będzie umyte wodą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 13, 'A gdy chory na wyciek zostanie oczyszczony od swego wycieku, odliczy sobie siedem dni na swoje oczyszczenie, wypierze swe szaty i obmyje swoje ciało źródlaną wodą, i będzie czysty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 14, 'Ósmego dnia weźmie sobie dwie synogarlice albo dwa młode gołębie, przyjdzie przed Pana do wejścia do Namiotu Zgromadzenia i odda je kapłanowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 15, 'A kapłan złoży je w ofierze: jednego na ofiarę za grzech, a drugiego na ofiarę całopalną. Tak dokona kapłan przebłagania za niego przed Panem z powodu jego wycieku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 16, 'Jeśli mężczyźnie wypłynie nasienie obcowania, obmyje w wodzie całe swe ciało i będzie nieczysty aż do wieczora.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 17, 'Każda też szata i każda skóra, na których będzie nasienie obcowania, będą wyprane wodą i będą nieczyste aż do wieczora.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 18, 'Dotyczy to także kobiety, z którą obcuje mężczyzna mający wypływ nasienia obcowania: oboje umyją się w wodzie i będą nieczyści aż do wieczora.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 19, 'A jeśli kobieta ma upływ, a jest to upływ krwi z jej ciała, to przez siedem dni będzie w swojej nieczystości. Każdy, kto jej dotknie, będzie nieczysty aż do wieczora.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 20, 'Wszystko, na czym się położy w trakcie swojej nieczystości, będzie nieczyste. Wszystko, na czym usiądzie, będzie nieczyste.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 21, 'Każdy, kto dotknie jej posłania, wypierze swoje szaty i umyje się wodą, i będzie nieczysty aż do wieczora.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 22, 'Każdy, kto dotknie tego, na czym siedziała, wypierze swoje szaty i umyje się wodą, i będzie nieczysty aż do wieczora.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 23, 'Jeśli coś było na jej posłaniu albo na czymkolwiek siedziała, a ktoś tego dotknie, będzie nieczysty aż do wieczora.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 24, 'A jeśli mężczyzna położy się z nią, a jej nieczystość będzie na nim, to będzie on nieczysty przez siedem dni i każde posłanie, na którym się położy, będzie nieczyste.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 25, 'Jeśli kobieta będzie miała upływ krwi przez wiele dni poza czasem swej nieczystości albo jeśli upływ krwi będzie trwał dłużej niż czas jej odłączenia, wtedy będzie nieczysta przez wszystkie dni upływu jej nieczystości jak w czasie jej odłączenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 26, 'Każde posłanie, na którym się położy przez wszystkie dni swojego upływu, będzie dla niej jak posłanie jej odłączenia. I wszystko, na czym usiądzie, będzie nieczyste tak jak nieczystość jej odłączenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 27, 'Ktokolwiek dotknie tych rzeczy, będzie nieczysty, i wypierze swoje szaty, i umyje się w wodzie, i będzie nieczysty aż do wieczora.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 28, 'A gdy będzie oczyszczona ze swego upływu, odliczy sobie siedem dni, a potem będzie czysta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 29, 'A dnia ósmego weźmie sobie dwie synogarlice lub dwa młode gołębie i przyniesie je kapłanowi przed wejście do Namiotu Zgromadzenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 30, 'A kapłan złoży jednego na ofiarę za grzech i drugiego na ofiarę całopalną: tak dokona kapłan przebłagania za nią przed Panem z powodu upływu jej nieczystości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 31, 'Tak będziecie odłączać synów Izraela od ich nieczystości, aby nie pomarli w swojej nieczystości, gdy zanieczyszczają mój przybytek, który jest wśród nich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 32, 'Takie jest prawo dotyczące tego, który ma wyciek i z którego wypływa nasienie spółkowania, przez co staje się nieczysty;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 33, 'Oraz kobiety w czasie jej nieczystości i osoby, która ma wyciek, tak mężczyzny, jak i niewiasty, i mężczyzny, który się położy z kobietą nieczystą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 1, 'Potem Pan mówił do Mojżesza po śmierci dwóch synów Aarona, którzy umarli, gdy złożyli ofiarę przed Panem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 2, 'I Pan powiedział do Mojżesza: Powiedz swojemu bratu Aaronowi, żeby nie wchodził w każdym czasie do Miejsca Świętego poza zasłonę przed przebłagalnią, która jest na arce, aby nie umarł. W obłoku bowiem będę się ukazywać nad przebłagalnią.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 3, 'Oto w taki sposób Aaron będzie wchodzić do Świętego Miejsca: z młodym cielcem na ofiarę za grzech i z baranem na całopalenie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 4, 'Ubierze się w świętą lnianą tunikę, na ciele będzie miał lniane spodnie, opasze się lnianym pasem i włoży na głowę lnianą mitrę. To są święte szaty; obmyje więc swoje ciało w wodzie i założy je.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 5, 'A od zgromadzenia synów Izraela weźmie dwa kozły na ofiarę za grzech i jednego baranka na całopalenie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 6, 'I Aaron złoży swego cielca na ofiarę za grzech za siebie samego, i dokona przebłagania za siebie i swój dom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 7, 'Weźmie też dwa kozły i postawi je przed Panem u wejścia do Namiotu Zgromadzenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 8, 'I Aaron rzuci losy o dwa kozły, jeden los dla Pana, a drugi los dla kozła ofiarnego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 9, 'I przyprowadzi Aaron tego kozła, na którego padł los dla Pana, i złoży go w ofierze za grzech.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 10, 'Ale kozła, na którego padł los dla kozła ofiarnego, postawi żywego przed Panem, aby nim dokonać przebłagania i wypuścić go na pustynię jako kozioł ofiarny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 11, 'I przyprowadzi Aaron cielca na ofiarę za grzech za siebie samego, i dokona przebłagania za siebie i swój dom, i zabije cielca na ofiarę za grzech za siebie samego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 12, 'Następnie weźmie pełną kadzielnicę węgla rozpalonego z ołtarza przed Panem oraz dwie pełne garści wonnego utłuczonego kadzidła i wniesie poza zasłonę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 13, 'I nasypie kadzidło na ogień przed Panem, aby obłok kadzidła okrył przebłagalnię, która jest nad arką, aby nie umarł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 14, 'Potem weźmie z krwi tego cielca i pokropi swym palcem nad przebłagalnią ku wschodowi. Przed przebłagalnią będzie kropić tą krwią siedem razy swym palcem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 15, 'Następnie zabije kozła na ofiarę za grzech za lud i wniesie jego krew poza zasłonę, i uczyni z jego krwią, jak uczynił z krwią cielca: pokropi nią nad przebłagalnią i przed przebłagalnią.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 16, 'Tak dokona przebłagania nad Miejscem Świętym za nieczystości synów Izraela, za ich przestępstwa i za wszystkie ich grzechy. Tak też uczyni z Namiotem Zgromadzenia, który jest wśród nich, pośrodku ich nieczystości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 17, 'A żaden człowiek nie może przebywać w Namiocie Zgromadzenia, gdy on będzie wchodzić do Miejsca Świętego, by dokonać przebłagania, aż wyjdzie i dokona przebłagania sam za siebie, swój dom i za całe zgromadzenie Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 18, 'Potem wyjdzie do ołtarza, który jest przed Panem, i dokona za niego przebłagania: weźmie nieco krwi cielca i krwi kozła i pomaże rogi ołtarza dokoła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 19, 'Pokropi go z wierzchu tą krwią swym palcem siedem razy, oczyści go i poświęci go od nieczystości synów Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 20, 'A gdy dokona przebłagania za Miejsce Święte, Namiot Zgromadzenia i ołtarz, przyprowadzi żywego kozła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 21, 'I Aaron położy obie ręce na głowie żywego kozła, wyznawać będzie nad nim wszystkie nieprawości synów Izraela i wszystkie ich przestępstwa ze wszystkimi ich grzechami i złoży je na głowę tego kozła, i wypuści go przez wyznaczonego człowieka na pustynię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 22, 'Tak poniesie ten kozioł na sobie wszystkie ich nieprawości do ziemi pustej. I wypuści tego kozła na pustynię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 23, 'Potem Aaron wejdzie do Namiotu Zgromadzenia, zdejmie z siebie lniane szaty, które włożył, gdy wszedł do Miejsca Świętego, i zostawi je tam.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 24, 'Obmyje też swoje ciało w wodzie na Miejscu Świętym i włoży swoje szaty, wyjdzie i złoży swoje całopalenie i całopalenie ludu i dokona przebłagania za siebie i za lud.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 25, 'A tłuszcz ofiary za grzech spali na ołtarzu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 26, 'A ten, który wypuścił kozła jako kozła ofiarnego, wypierze swoje szaty i obmyje swoje ciało w wodzie, potem wejdzie do obozu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 27, 'Cielca zaś ofiary za grzech i kozła ofiary za grzech, których krew została wniesiona do Miejsca Świętego dla przebłagania, wyniosą poza obóz i spalą w ogniu ich skóry, ich mięso i ich gnój.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 28, 'A ten, który je spali, wypierze swoje szaty i obmyje swoje ciało w wodzie, potem wejdzie do obozu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 29, 'To będzie dla was wieczną ustawą: W dziesiątym dniu tego siódmego miesiąca będziecie trapić swoje dusze i nie będziecie wykonywać żadnej pracy, zarówno rodowity mieszkaniec, jak i przybysz, który gości wśród was;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 30, 'Bo w tym dniu kapłan dokona za was przebłagania, aby was oczyścić od wszystkich waszych grzechów, abyście byli oczyszczeni przed Panem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 31, 'Będzie to dla was szabatem odpoczynku i będziecie trapić wasze dusze ustawą wieczną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 32, 'A dokona przebłagania kapłan, który jest namaszczony i poświęcony do pełnienia służby na miejsce swego ojca, a włoży lniane szaty, szaty święte;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 33, 'I dokona przebłagania za Miejsce Najświętsze i Namiot Zgromadzenia, i za ołtarz, dokona też przebłagania za kapłanów i cały lud zgromadzenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 34, 'I będzie to dla was wieczną ustawą, aby raz w roku dokonywać za synów Izraela przebłagania za wszystkie ich grzechy. I uczynił Mojżesz tak, jak mu Pan rozkazał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 1, 'Wtedy Pan powiedział do Mojżesza:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 2, 'Mów do Aarona i do jego synów, i do wszystkich synów Izraela i powiedz im: Oto co Pan nakazał:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 3, 'Ktokolwiek z domu Izraela zabije wołu, owcę albo kozę w obozie lub zabije je poza obozem;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 4, 'A nie przyprowadzi tego przed wejście do Namiotu Zgromadzenia, aby złożyć w ofierze Panu przed przybytkiem Pana, to będzie on winien krwi, bo przelał krew. Ten człowiek zostanie wykluczony spośród swego ludu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 5, 'Ma tak być, aby synowie Izraela przyprowadzili swoje ofiary, które dotychczas zabijali na polu, by przyprowadzili je do Pana przed wejście do Namiotu Zgromadzenia, do kapłana, i złożyli je jako ofiary pojednawcze Panu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 6, 'Kapłan pokropi krwią ołtarz Pana u wejścia do Namiotu Zgromadzenia, a tłuszcz spali jako miłą woń dla Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 7, 'I nie będą już więcej składać swoich ofiar demonom, z którymi uprawiali nierząd. To będzie dla nich wieczna ustawa przez wszystkie ich pokolenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 8, 'Powiedz im jeszcze: Jeśli ktokolwiek z domu Izraela albo z przybyszów mieszkających wśród was będzie składał całopalenie lub inną ofiarę;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 9, 'A nie przyprowadzi jej przed wejście do Namiotu Zgromadzenia, aby ją złożyć Panu, to człowiek ten będzie wykluczony ze swego ludu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 10, 'A gdyby ktokolwiek z domu Izraela lub z przybyszów, którzy goszczą wśród was, spożywał jakąkolwiek krew, to zwrócę swoje oblicze przeciw człowiekowi, który spożywa krew, i wykluczę go spośród jego ludu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 11, 'Życie wszelkiego ciała bowiem jest we krwi. Ja dałem ją wam na ołtarz dla dokonywania przebłagania za wasze dusze, gdyż to krew dokonuje przebłagania za duszę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 12, 'Dlatego powiedziałem synom Izraela: Żadna dusza wśród was nie będzie spożywała krwi ani żaden przybysz, który gości wśród was, nie będzie spożywał krwi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 13, 'I ktokolwiek z synów Izraela lub z przybyszów, którzy goszczą wśród was, upoluje jakieś zwierzę lub ptaka, które wolno jeść, to wypuści jego krew i przykryje ją piaskiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 14, 'Gdyż to jest życie wszelkiego ciała, krew stanowi jego życie. Dlatego powiedziałem synom Izraela: Krwi wszelkiego ciała spożywać nie będziecie, bo życiem wszelkiego ciała jest jego krew. Ktokolwiek ją spożywa, zostanie wytracony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 15, 'Każda dusza, która spożywa zwierzę padłe lub rozszarpane, czy to rodowity mieszkaniec, czy przybysz, wypierze swoje szaty i obmyje się w wodzie, i będzie nieczysta aż do wieczora. Potem będzie czysta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 16, 'Ale jeśli nie wypierze swoich szat ani nie obmyje swego ciała, obciąży się nieprawością.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 1, 'Pan powiedział jeszcze do Mojżesza:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 2, 'Przemów do synów Izraela i powiedz im: Ja jestem Pan, wasz Bóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 3, 'Nie czyńcie według zwyczajów ziemi Egiptu, w której mieszkaliście, ani według zwyczajów ziemi Kanaan, do której was prowadzę, też nie czyńcie, a według ich ustaw nie postępujcie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 4, 'Wypełniajcie moje prawa i przestrzegajcie moich ustaw, abyście postępowali według nich. Ja jestem Pan, wasz Bóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 5, 'Przestrzegajcie więc moich ustaw i moich praw, bo jeśli człowiek je wypełnia, będzie przez nie żył. Ja jestem Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 6, 'Nikt z was nie będzie zbliżał się do swojego krewnego, by odsłonić jego nagość. Ja jestem Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 7, 'Nie będziesz odsłaniał nagości swego ojca lub matki; ona jest twoją matką, nie odkryjesz jej nagości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 8, 'Nie będziesz odsłaniał nagości żony twego ojca; to jest nagość twego ojca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 9, 'Nie będziesz odsłaniał nagości córki twego ojca lub córki twojej matki, czy urodziła się w domu, czy poza domem – nie odkryjesz ich nagości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 10, 'Nie będziesz odsłaniał nagości córki twego syna lub nagości córki twojej córki, bo są one twoją nagością.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 11, 'Nie będziesz odsłaniał nagości córki żony twego ojca, która się narodziła z twego ojca, bo ona jest twoją siostrą, nie odkryjesz jej nagości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 12, 'Nie będziesz odsłaniał nagości siostry twego ojca, bo jest ona bliską krewną twego ojca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 13, 'Nie będziesz odsłaniał nagości siostry twojej matki, bo ona jest bliską krewną twojej matki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 14, 'Nie będziesz odsłaniał nagości brata twego ojca, nie zbliżysz się do jego żony; ona jest twoją ciocią.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 15, 'Nie będziesz odsłaniał nagości twojej synowej; ona jest żoną twego syna, nie odkryjesz jej nagości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 16, 'Nie będziesz odsłaniał nagości żony twego brata, bo to jest nagość twego brata.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 17, 'Nie będziesz odsłaniał nagości kobiety i jej córki; nie weźmiesz córki jej syna ani córki jej córki, aby odkryć jej nagość, bo są one jej bliskimi krewnymi. Jest to niegodziwość.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 18, 'Nie weźmiesz siostry twej żony, abyś jej nie trapił, odsłaniając jej nagość za jej życia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 19, 'Nie zbliżaj się do kobiety, aby odsłaniać jej nagość w czasie jej odłączenia z powodu nieczystości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 20, 'Nie będziesz obcował z żoną twego bliźniego, bo stałbyś się nią nieczysty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 21, 'Nie pozwalaj żadnemu z twoich potomków przejść przez ogień dla Molocha, abyś nie bezcześcił imienia twego Boga. Ja jestem Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 22, 'Nie będziesz obcował z mężczyzną jak z kobietą. Jest to obrzydliwość.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 23, 'Nie będziesz też obcował z żadnym zwierzęciem, bo stałbyś się tym nieczysty. Kobieta nie będzie stawać przed zwierzęciem w celu obcowania z nim. Jest to zboczenie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 24, 'Nie kalajcie się tym wszystkim, gdyż tym wszystkim kalały się narody, które wypędzam przed wami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 25, 'Także i ziemia stała się skalana. Nawiedziłem więc jej nieprawość w niej i ziemia zwymiotowała swoich mieszkańców.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 26, 'Przestrzegajcie więc moich ustaw i moich praw i nie dopuszczajcie się żadnych z tych obrzydliwości, ani rodowity mieszkaniec, ani przybysz, który gości wśród was;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 27, '(Wszystkich bowiem tych obrzydliwości dopuszczali się ludzie tej ziemi, którzy byli przed wami, i ziemia stała się skalana);');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 28, 'Aby was ziemia nie zwymiotowała, gdy ją zanieczyścicie, jak zwymiotowała narody, które były przed wami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 29, 'Bo ktokolwiek dopuści się jakiejś z tych wszystkich obrzydliwości, wszyscy, którzy tak czynią, zostaną wykluczeni spośród swego ludu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 30, 'Przestrzegajcie więc moich ustaw, aby nie czynić żadnego z obrzydliwych zwyczajów, które były czynione przed wami, abyście nie skalali się nimi. Ja jestem Pan, wasz Bóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 1, 'Potem Pan powiedział do Mojżesza:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 2, 'Przemów do całego zgromadzenia synów Izraela i powiedz im: Bądźcie święci, bo ja, Pan, wasz Bóg, jestem święty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 3, 'Niech każdy z was boi się swojej matki i swojego ojca i niech przestrzega moich szabatów. Ja jestem Pan, wasz Bóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 4, 'Nie będziecie się zwracać do bożków i nie czyńcie sobie odlewanych bogów. Ja jestem Pan, wasz Bóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 5, 'A gdy będziecie składać Panu ofiarę pojednawczą, składajcie ją dobrowolnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 6, 'Będziecie ją spożywali w dniu, w którym ją złożycie w ofierze, i nazajutrz. A co pozostanie do trzeciego dnia, będzie spalone w ogniu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 7, 'A jeśli spożyjecie ją trzeciego dnia, będzie obrzydliwa i nie zostanie przyjęta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 8, 'Ktokolwiek ją spożyje, obciąży się nieprawością, bo zbezcześcił świętość Pana. Ta dusza będzie wykluczona spośród swego ludu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 9, 'Gdy będziecie żąć zboża waszej ziemi, nie będziesz żął swego pola do samego skraju ani nie będziesz zbierał pokłosia po swoim żniwie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 10, 'Także gron swej winnicy nie będziesz obierał całkowicie i nie zbieraj z winnicy winogron, które upadły; zostawisz je dla ubogiego i przybysza. Ja jestem Pan, wasz Bóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 11, 'Nie będziecie kraść, nie będziecie oszukiwać i nie będziecie okłamywać jeden drugiego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 12, 'Nie będziecie przysięgać fałszywie na moje imię i nie będziecie bezcześcić imienia swego Boga. Ja jestem Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 13, 'Nie będziesz uciskać swego bliźniego i nie będziesz go wyzyskiwać. Zapłata najemnika nie zostanie u ciebie aż do rana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 14, 'Nie będziesz złorzeczył głuchemu, a przed ślepym nie będziesz stawiał przeszkody, ale będziesz się bał swego Boga. Ja jestem Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 15, 'Nie będziesz postępował niesłusznie w sądzie. Nie będziesz miał względu na osobę ubogiego i nie wyróżniaj osoby bogatego. Sprawiedliwie będziesz sądził swego bliźniego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 16, 'Nie będziesz szerzył oszczerstw wśród swego ludu. Nie będziesz nastawał na krew swego bliźniego. Ja jestem Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 17, 'Nie będziesz w swoim sercu nienawidził swego brata. Będziesz upominał swego bliźniego i nie zniesiesz u niego grzechu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 18, 'Nie będziesz się mścił i nie będziesz chować urazy do synów swego ludu, lecz będziesz miłował swego bliźniego jak samego siebie. Ja jestem Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 19, 'Będziesz przestrzegać moich ustaw. Nie będziesz parzył swego bydła z bydłem innego rodzaju. Nie będziesz obsiewał swego pola dwoma rodzajami ziarna. Także nie będziesz wkładał na siebie szaty utkanej z dwóch różnych przędzy, jak z wełny i lnu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 20, 'Jeśli mężczyzna obcuje z kobietą, która jest niewolnicą, poślubioną mężowi, lecz jeszcze niewykupioną ani nieobdarzoną wolnością, oboje będą karani, ale nie zostaną zabici, ponieważ nie była wolna.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 21, 'I przyprowadzi Panu ofiarę za swoje przewinienie przed wejście do Namiotu Zgromadzenia, to jest barana za przewinienie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 22, 'Wówczas kapłan dokona przed Panem przebłagania za niego przez barana za przewinienie za jego grzech, którego się dopuścił. I będzie mu odpuszczony jego grzech, który popełnił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 23, 'A gdy wejdziecie do ziemi i zasadzicie wszelkie drzewa dające owoc, wtedy będziecie uważać ich owoce za nieobrzezane. Przez trzy lata będziecie je mieć za nieobrzezane, nie będziecie ich jeść.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 24, 'Lecz w czwartym roku wszystkie ich owoce będą poświęcone jako ofiara na chwałę Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 25, 'A w piątym roku będziecie jeść ich owoc, aby mnożył się wam jego urodzaj. Ja jestem Pan, wasz Bóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 26, 'Nie będziecie jeść niczego z krwią. Nie będziecie uprawiać wróżbiarstwa ani czarów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 27, 'Nie będziecie obcinać włosów dokoła waszej głowy ani nie będziecie przycinać końców swojej brody.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 28, 'Nie będziecie robić żadnych nacięć na swoim ciele za umarłych ani czynić żadnego piętna na sobie. Ja jestem Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 29, 'Nie będziesz hańbił swojej córki, nakłaniając ją do nierządu, aby ziemia nie uległa nierządowi i nie napełniła się rozpustą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 30, 'Będziecie przestrzegać moich szabatów i moją świątynię będziecie czcić. Ja jestem Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 31, 'Nie będziecie się zwracać do czarowników ani szukać rady u wróżbitów, abyście się przez nich nie skalali. Ja jestem Pan, wasz Bóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 32, 'Przed siwizną wstaniesz i uczcisz osobę starca, i bój się swego Boga. Ja jestem Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 33, 'Jeśli przybysz będzie mieszkał z tobą w waszej ziemi, nie czyńcie mu krzywdy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 34, 'Przybysz, który gości u was, będzie jak jeden urodzony wśród was. Będziesz go miłować jak samego siebie, bo i wy byliście przybyszami w ziemi Egiptu. Ja jestem Pan, wasz Bóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 35, 'Nie czyńcie nieprawości w sądzie, w miarach, w wagach i w objętości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 36, 'Wagi sprawiedliwe, odważniki sprawiedliwe, efę sprawiedliwą i kwartę sprawiedliwą będziecie mieć. Ja jestem Pan, wasz Bóg, który wyprowadził was z ziemi Egiptu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 37, 'Będziecie więc przestrzegać wszystkich moich ustaw i wszystkich moich praw i będziecie je wypełniać. Ja jestem Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 1, 'Potem Pan powiedział do Mojżesza:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 2, 'Powiedz synom Izraela: Ktokolwiek z synów Izraela albo z przybyszów mieszkających w Izraelu złoży Molochowi w ofierze kogoś ze swego potomstwa, poniesie śmierć. Lud tej ziemi go ukamienuje.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 3, 'I ja zwrócę moje oblicze przeciwko temu człowiekowi i wyłączę go spośród jego ludu, dlatego że złożył ofiarę Molochowi ze swego potomstwa, by zanieczyścić moją świątynię i zbezcześcić moje święte imię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 4, 'A jeśli lud tej ziemi zasłoni swe oczy przed takim człowiekiem, który złożył Molochowi ofiarę ze swego potomstwa, i nie zabije go;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 5, 'To zwrócę swoje oblicze przeciw temu człowiekowi i przeciw jego domowi i wyłączę go oraz wszystkich, którzy cudzołożyli za jego przykładem, by uprawiać nierząd z Molochem, spośród ich ludu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 6, 'Przeciwko człowiekowi, który zwróci się do czarowników i wróżbitów, by cudzołożyć za ich przykładem, zwrócę swoje oblicze i wyłączę go spośród jego ludu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 7, 'Uświęcajcie się więc i bądźcie święci, bo ja jestem Pan, wasz Bóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 8, 'Będziecie przestrzegać moich ustaw i wypełniać je. Ja jestem Pan, który was uświęca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 9, 'Ktokolwiek bowiem złorzeczy swemu ojcu albo swej matce, poniesie śmierć. Złorzeczył swemu ojcu i swej matce, więc jego krew spadnie na niego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 10, 'Mężczyzna, który dopuści się cudzołóstwa z czyjąś żoną, ponieważ cudzołożył z żoną swego bliźniego, poniesie śmierć, zarówno cudzołożnik, jak i cudzołożnica.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 11, 'Mężczyzna, który położy się z żoną swego ojca, odsłonił nagość swego ojca: oboje poniosą śmierć, ich krew spadnie na nich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 12, 'Jeśli mężczyzna położy się ze swoją synową, oboje poniosą śmierć. Dopuścili się zboczenia, ich krew spadnie na nich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 13, 'Także jeśli mężczyzna obcuje z mężczyzną tak jak z kobietą, to obaj popełnili obrzydliwość. Poniosą śmierć, ich krew spadnie na nich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 14, 'Jeśli mężczyzna pojmie za żonę kobietę i jej matkę, to jest to niegodziwość. W ogniu spalą i jego, i je, aby nie było tej niegodziwości wśród was.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 15, 'Także mężczyzna, jeśli się położy ze zwierzęciem, poniesie śmierć. Zwierzę też zabijecie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 16, 'Jeśli kobieta zbliża się do jakiegoś zwierzęcia, aby się z nim położyć, zabijesz kobietę i zwierzę. Poniosą śmierć, ich krew będzie na nich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 17, 'Jeśli mężczyzna pojmie swoją siostrę, córkę swego ojca albo córkę swej matki i zobaczy jej nagość, i ona zobaczy jego nagość, to jest to hańba. Będą wytraceni na oczach swego ludu. Odsłonił nagość swej siostry, obciążył się swoją nieprawością.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 18, 'A jeśli mężczyzna położy się z kobietą w czasie jej słabości i odkryje jej nagość, i obnaży jej źródło, a ona też odsłoni źródło swojej krwi, to oboje zostaną wykluczeni spośród swego ludu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 19, 'Nie będziesz odsłaniał nagości siostry swej matki ani siostry swego ojca, bo kto obnaża swoją krewną, obciąża się swoją nieprawością.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 20, 'Jeśli mężczyzna kładzie się z żoną swego stryja, odsłania nagość swego stryja. Obciążą się swoim grzechem, umrą bez dzieci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 21, 'Także jeśli mężczyzna pojmie żonę swego brata, to jest to nieczystość. Odsłania nagość swego brata, będą bezdzietni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 22, 'Przestrzegajcie więc wszystkich moich ustaw i wszystkich moich praw i wypełniajcie je, aby was nie wyrzuciła ziemia, do której was wprowadzę, abyście w niej mieszkali.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 23, 'A nie postępujcie według obyczajów tego narodu, który wypędzam przed wami. To wszystko bowiem czynili i obrzydziłem ich sobie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 24, 'Wam zaś powiedziałem: Wy posiądziecie ich ziemię i dam ją wam jako posiadłość – ziemię opływającą mlekiem i miodem. Ja jestem Pan, wasz Bóg, który oddzielił was od innych narodów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 25, 'Będziecie więc rozróżniać między zwierzęciem czystym a nieczystym i między ptakiem nieczystym a czystym. Nie kalajcie waszych dusz przez zwierzęta i ptactwo, i wszystko, co pełza po ziemi, co oddzieliłem od was jako nieczyste.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 26, 'I będziecie dla mnie święci, bo ja, Pan, jestem święty i oddzieliłem was od innych narodów, abyście byli moimi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 27, 'Mężczyzna lub kobieta, w których będzie duch czarownika albo wróżbity, poniosą śmierć: będą ukamienowani, ich krew spadnie na nich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 1, 'Pan powiedział też do Mojżesza: Mów do kapłanów, synów Aarona i powiedz im: Niech nikt z was nie zanieczyści się z powodu umarłych spośród swego ludu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 2, 'Z wyjątkiem najbliższych krewnych, czyli swej matki, swego ojca, swego syna, swej córki i swego brata;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 3, 'A także swej siostry dziewicy, bliskiej mu, która nie miała męża; z jej powodu może się zanieczyścić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 4, 'Jako przełożony wśród swego ludu nie zanieczyści się, tak żeby był skalany.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 5, 'Nie będą sobie czynili łysiny na swej głowie ani nie będą golić skrajów swej brody, ani nie będą nacinać swego ciała.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 6, 'Będą święci dla swego Boga i nie będą bezcześcili imienia swego Boga, składają bowiem ofiary Pana spalane w ogniu oraz chleb swego Boga. Będą więc święci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 7, 'Nie pojmą sobie za żonę nierządnicy lub naruszonej w panieństwie; nie będą także pojmować kobiety oddalonej przez jej męża, gdyż każdy z nich jest święty dla swego Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 8, 'Miej go więc za świętego, bo on składa w ofierze chleb twego Boga; dlatego będzie święty dla ciebie, bo ja, Pan, który was poświęca, jestem święty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 9, 'Jeśli córka kapłana zbezcześci się przez nierząd, zbezcześci swego ojca. Będzie spalona w ogniu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 10, 'Najwyższy kapłan wśród swoich braci, na którego głowę została wylana oliwa namaszczenia i który został poświęcony, aby wkładać na siebie święte szaty, nie będzie odsłaniał swej głowy i nie rozedrze swoich szat;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 11, 'I nie zbliży się do żadnego zmarłego, nawet nie zanieczyści się z powodu swego ojca lub z powodu swej matki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 12, 'Nie wyjdzie ze świątyni i nie zbezcześci świątyni swego Boga, gdyż korona oliwy namaszczenia swego Boga jest na nim: Ja jestem Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 13, 'I weźmie sobie dziewicę za żonę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 14, 'Nie weźmie sobie ani wdowy, ani oddalonej, ani zhańbionej, ani nierządnicy, lecz weźmie sobie za żonę dziewicę ze swego ludu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 15, 'I nie zbezcześci swego potomstwa wśród swego ludu, bo ja jestem Pan, który go uświęca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 16, 'Przemówił dalej Pan do Mojżesza, mówiąc:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 17, 'Powiedz Aaronowi tymi słowy: Ktokolwiek z twego potomstwa w ich pokoleniach miał jakąś wadę, niech nie zbliża się, aby składać w ofierze chleb swego Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 18, 'Żaden mężczyzna, który ma jakąś wadę, nie zbliży się: ani niewidomy, ani chromy, ani mający płaski nos, ani nieproporcjonalnie zbudowany;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 19, 'Ani ten, który ma złamaną nogę lub rękę;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 20, 'Ani garbaty, ani z bielmem na oku, ani chory na świerzb, ani pokryty liszajami, ani eunuch:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 21, 'Żaden mężczyzna z potomków kapłana Aarona, który ma jakąś wadę, nie zbliży się, by składać ofiary Pana spalane w ogniu. Ma wadę, więc nie zbliży się, aby składać w ofierze chleb swego Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 22, 'Może jednak spożywać chleb swego Boga, zarówno święty, jak i najświętszy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 23, 'Lecz nie może wchodzić poza zasłonę ani zbliżać się do ołtarza, bo ma wadę, żeby nie zbezcześcił mojej świątyni. Ja bowiem jestem Pan, który ją poświęca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 24, 'I Mojżesz powiedział to Aaronowi, jego synom i wszystkim synom Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 1, 'I powiedział Pan do Mojżesza:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 2, 'Powiedz Aaronowi i jego synom, aby powstrzymywali się od świętych rzeczy synów Izraela i nie zbezcześcili mojego świętego imienia w tym, co mi poświęcają. Ja jestem Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 3, 'Powiedz im: Ktokolwiek z waszego potomstwa w waszych pokoleniach zbliży się do świętych rzeczy, które synowie Izraela poświęcają Panu, będąc nieczystym, ten będzie wytracony sprzed mego oblicza. Ja jestem Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 4, 'Ktokolwiek z potomstwa Aarona będzie trędowaty albo będzie cierpiał na wyciek, nie będzie spożywał z rzeczy poświęconych, dopóki nie stanie się czysty. A kto dotknie jakiejś nieczystości z powodu zmarłego lub tego, z którego wypływa nasienie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 5, 'Lub kto dotknie czegoś, co pełza po ziemi, przez co stanie się nieczysty, lub człowieka, który uczyni go nieczystym z powodu jakiejkolwiek jego nieczystości;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 6, 'Ten, kto dotknie czegoś takiego, będzie nieczysty aż do wieczora i nie będzie jadł z rzeczy poświęconych, aż obmyje swoje ciało w wodzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 7, 'Po zachodzie słońca będzie czysty i potem będzie jeść z rzeczy poświęconych, bo to jest jego pokarm.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 8, 'Nie będzie jadł padliny ani mięsa rozszarpanego przez zwierzę, aby się tym nie zanieczyścić. Ja jestem Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 9, 'Będą więc przestrzegać mojego nakazu, aby nie obciążyli się grzechem i nie umarli za to, że go zbezcześcili. Ja jestem Pan, który ich poświęca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 10, 'Żaden obcy nie będzie jadł z rzeczy świętych: ani gość kapłana, ani jego najemnik nie będzie jadł z rzeczy świętych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 11, 'A jeśli kapłan kupi człowieka za swoje pieniądze, to ten może je jeść, również urodzony w jego domu; oni mogą jeść z jego pokarmów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 12, 'A jeśli córka kapłana wyjdzie za mąż za obcego, to nie będzie ona jeść z ofiar rzeczy świętych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 13, 'Jeśli zaś córka kapłana zostanie wdową albo zostanie oddalona przez męża i nie ma dzieci, a wróci do domu swego ojca jak w swojej młodości, to będzie mogła jeść chleb swego ojca, lecz żaden obcy nie będzie z niego jadł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 14, 'A jeśli ktoś przez nieuwagę zje z rzeczy świętych, to doda do tego jedną piątą i odda kapłanowi wraz z rzeczą świętą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 15, 'Nie będą bezcześcić rzeczy świętych, które synowie Izraela ofiarują Panu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 16, 'I tak obciążać ich nieprawością za występek, gdy będą jedli ich święte rzeczy, gdyż ja, Pan, ich uświęcam.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 17, 'Potem Pan powiedział do Mojżesza:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 18, 'Przemów do Aarona, jego synów i wszystkich synów Izraela i powiedz im: Ktokolwiek z domu Izraela lub spośród przybyszów w Izraelu złoży swoją ofiarę zgodnie ze wszystkimi swoimi ślubami lub wszystkimi dobrowolnymi darami, które złoży Panu na ofiarę całopalenia;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 19, 'To złoży ze swojej woli samca bez skazy, z bydła, owiec lub kóz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 20, 'Nie będziecie ofiarować niczego, co ma wadę, bo nie zostanie przyjęte od was.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 21, 'Jeśli ktoś składa Panu ofiarę pojednawczą, wypełniając ślub lub jako dobrowolny dar z bydła albo z trzody, musi to być bez wady, aby zostało przyjęte. Nie będzie na nim żadnej zmazy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 22, 'Nie będziecie ofiarowywać Panu zwierzęcia ślepego, kulawego, okaleczonego, owrzodzonego, chorego na świerzb, pokrytego liszajami. Nie będziecie też składać go Panu na ołtarz jako ofiary spalanej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 23, 'Wołu albo jagnię niekształtne lub niewyrośnięte możesz złożyć jako ofiarę dobrowolną, ale jako ofiara ślubowana nie będą przyjęte.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 24, 'Nie będziecie ofiarowywać Panu nic zgniecionego, posiniaczonego, rozerwanego lub skaleczonego. Nie będziecie tego czynić w waszej ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 25, 'Nie będziecie też ofiarowywać na chleb waszego Boga z ręki cudzoziemca takich zwierząt, bo jest w nich skaza, mają wadę. Nie zostaną przyjęte od was.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 26, 'Potem Pan powiedział do Mojżesza:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 27, 'Gdy się urodzi wół, owca lub koza, to będzie przez siedem dni przy swej matce, a od ósmego dnia i dalej będzie przyjęte jako ofiara spalona dla Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 28, 'Nie zabijajcie w tym samym dniu krowy lub owcy wraz z jej małym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 29, 'A gdy będziecie składali Panu ofiarę dziękczynną, będziecie ją składać z własnej woli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 30, 'Tego samego dnia zostanie spożyta; nie zostawicie z niej nic do rana. Ja jestem Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 31, 'Dlatego będziecie przestrzegać moich przykazań i wypełniać je. Ja jestem Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 32, 'I nie będziecie bezcześcić mojego świętego imienia, bo będę uświęcony pośród synów Izraela. Ja jestem Pan, który was uświęca;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 33, 'Który was wyprowadził z ziemi Egiptu, aby być waszym Bogiem. Ja jestem Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 1, 'I Pan powiedział do Mojżesza:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 2, 'Przemów do synów Izraela i powiedz im: Uroczyste święta Pana, które będziecie ogłaszać jako święte zgromadzenia. One są moimi uroczystymi świętami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 3, 'Przez sześć dni będziecie wykonywać pracę, ale siódmy dzień będzie szabatem odpoczynku, świętym zgromadzeniem, nie będziecie wykonywać wtedy żadnej pracy. Jest to szabat Pana we wszystkich waszych domach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 4, 'Oto uroczyste święta Pana, święte zgromadzenia, które będziecie ogłaszać w ich oznaczonych porach:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 5, 'W pierwszym miesiącu, czternastego dnia tego miesiąca, o zmierzchu, jest Pascha Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 6, 'A piętnastego dnia tego miesiąca będzie Święto Przaśników dla Pana. Przez siedem dni będziecie jeść przaśne chleby.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 7, 'Pierwszego dnia będziecie mieć święte zgromadzenie. Nie będziecie wykonywać żadnej uciążliwej pracy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 8, 'Lecz będziecie składali Panu ofiarę spalaną przez siedem dni. Siódmego dnia będzie święte zgromadzenie. Nie będziecie wykonywać żadnej ciężkiej pracy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 9, 'I Pan powiedział do Mojżesza:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 10, 'Przemów do synów Izraela i powiedz im: Gdy wejdziecie do ziemi, którą wam daję, i będziecie zbierać plony, wtedy przyniesiecie do kapłana snop z pierwocin waszego plonu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 11, 'I on będzie kołysał tym snopem przed Panem, aby był przyjęty za was. Nazajutrz po sabacie kapłan będzie nim kołysał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 12, 'W dniu kołysania tym snopem złożycie w ofierze rocznego baranka bez skazy jako całopalenie dla Pana;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 13, 'Wraz z nim na ofiarę pokarmową dwie dziesiąte efy mąki pszennej zmieszanej z oliwą jako ofiarę spalaną Panu na miłą woń, a do tego także ofiarę z płynów, jedną czwartą hinu wina.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 14, 'Nie będziecie jeść chleba ani prażonego ziarna, ani świeżych kłosów aż do dnia, w którym przyniesiecie ofiarę waszemu Bogu. Będzie to wieczna ustawa przez wszystkie wasze pokolenia, we wszystkich waszych mieszkaniach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 15, 'I odliczycie sobie od pierwszego dnia po szabacie, od dnia, w którym przynieśliście snop kołysania, siedem pełnych tygodni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 16, 'Aż do pierwszego dnia po siódmym szabacie odliczycie pięćdziesiąt dni i wtedy złożycie Panu nową ofiarę pokarmową.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 17, 'Przyniesiecie z waszych domów dwa chleby na ofiarę kołysania. Będą one z dwóch dziesiątych efy mąki pszennej, upieczone na zakwasie; to będą pierwociny dla Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 18, 'Razem z tym chlebem złożycie w ofierze siedem rocznych baranków bez skazy, jednego młodego cielca i dwa barany. Będą one na ofiarę całopalenia dla Pana wraz z ich ofiarą pokarmową i ofiarami z płynów. Będzie to ofiara spalana na miłą woń dla Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 19, 'Złożycie też jednego kozła na ofiarę za grzech i dwa roczne baranki na ofiarę pojednawczą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 20, 'I kapłan będzie je kołysał razem z chlebem pierwocin na ofiarę kołysania przed Panem wraz z dwoma barankami. One będą poświęcone Panu, przeznaczone dla kapłana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 21, 'I ogłosicie w tym dniu święto; będzie to dla was święte zgromadzenie. Nie będziecie wykonywać żadnej uciążliwej pracy. To będzie wieczysta ustawa we wszystkich waszych domach, przez wszystkie wasze pokolenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 22, 'A gdy będziecie zbierać plony waszej ziemi, nie będziesz wycinać doszczętnie skraju twego pola i nie będziesz zbierać pokłosia twoich plonów. Zostawisz je dla ubogiego i przybysza. Ja jestem Pan, wasz Bóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 23, 'Pan dalej mówił do Mojżesza:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 24, 'Przemów do synów Izraela i powiedz im: W siódmym miesiącu, pierwszego dnia tego miesiąca, będziecie mieli szabat, upamiętnienie przez trąbienie, święte zgromadzenie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 25, 'Nie będziecie wykonywać żadnej uciążliwej pracy, lecz złożycie Panu ofiarę spalaną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 26, 'Pan powiedział jeszcze do Mojżesza:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 27, 'Lecz dziesiątego dnia tego siódmego miesiąca będzie Dzień Przebłagania. Będzie to dla was święte zgromadzenie; będziecie trapić swoje dusze i składać Panu ofiarę spalaną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 28, 'W tym dniu nie będziecie wykonywać żadnej pracy, gdyż jest to Dzień Przebłagania, żeby dokonano dla was przebłagania przed Panem, waszym Bogiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 29, 'Każdy bowiem człowiek, który nie będzie trapił swojej duszy tego dnia, zostanie wykluczony ze swego ludu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 30, 'Także każdego, kto będzie wykonywał jakąkolwiek pracę w tym dniu, zgładzę spośród jego ludu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 31, 'Nie będziecie wykonywać żadnej pracy; będzie to wieczysta ustawa przez wszystkie wasze pokolenia, we wszystkich waszych domach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 32, 'Będzie to dla was szabat odpoczynku i będziecie trapić swoje dusze. Dziewiątego dnia tego miesiąca, wieczorem, od wieczora aż do wieczora, będziecie obchodzić wasz szabat.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 33, 'Pan dalej mówił do Mojżesza:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 34, 'Przemów do synów Izraela i powiedz im: Piętnastego dnia tego siódmego miesiąca będzie Święto Namiotów przez siedem dni dla Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 35, 'Pierwszego dnia będzie święte zgromadzenie. Nie będziecie wykonywać żadnej uciążliwej pracy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 36, 'Przez siedem dni będziecie składać Panu ofiarę spalaną. Ósmego dnia będziecie mieć święte zgromadzenie i będziecie składać Panu ofiarę spalaną. Jest to święto, żadnej uciążliwej pracy nie będziecie wykonywać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 37, 'To są święta Pana, które ogłosicie jako święte zgromadzenia, abyście składali Panu ofiarę spalaną, całopalenie, ofiarę pokarmową, ofiarę pojednawczą i ofiary z płynów, każdą w swój dzień;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 38, 'Oprócz szabatów Pana, oprócz waszych darów, oprócz wszystkich waszych ślubów i wszystkich waszych dobrowolnych ofiar, które będziecie składać Panu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 39, 'Piętnastego dnia siódmego miesiąca, gdy zbierzecie plony ziemi, będziecie obchodzili święto dla Pana przez siedem dni; w pierwszym dniu będzie odpoczynek, także w ósmym dniu będzie odpoczynek.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 40, 'Pierwszego dnia weźmiecie sobie owoce z najlepszych drzew, gałązki palmowe, gałązki gęstych drzew i wierzbiny znad potoku i będziecie się weselić przed Panem, waszym Bogiem, przez siedem dni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 41, 'Będziecie obchodzić to święto dla Pana przez siedem dni, co rok. Będzie to wieczysta ustawa przez wszystkie wasze pokolenia. W siódmym miesiącu będziecie je obchodzić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 42, 'Przez siedem dni będziecie mieszkać w szałasach. Wszyscy urodzeni Izraelici będą mieszkać w szałasach;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 43, 'Aby wasze pokolenia wiedziały, że kazałem synom Izraela mieszkać w szałasach, gdy wyprowadziłem ich z ziemi Egiptu. Ja jestem Pan, wasz Bóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 44, 'I ogłosił Mojżesz synom Izraela te święta Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 1, 'I Pan powiedział do Mojżesza:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 2, 'Rozkaż synom Izraela, aby przynieśli ci czystą, wyciśniętą oliwę z oliwek, na oświetlenie, aby lampy ciągle się paliły.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 3, 'Aaron sporządzi je na zewnątrz zasłony Świadectwa, w Namiocie Zgromadzenia, aby się paliły od wieczora aż do poranka przed Panem nieustannie. Będzie to wieczysta ustawa przez wszystkie wasze pokolenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 4, 'Będzie ustawiał lampy na czystym świeczniku przed Panem nieustannie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 5, 'Weźmiesz też mąki pszennej i upieczesz z niej dwanaście placków, każdy placek będzie z dwóch dziesiątych efy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 6, 'Potem ułożysz je w dwóch rzędach, po sześć w każdym rzędzie, na czystym stole przed Panem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 7, 'Na każdy rząd położysz czystego kadzidła, aby było pamiątką na chlebie, ofiarą spaloną dla Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 8, 'W każdy dzień szabatu kapłan będzie je nieustannie układać przed Panem, biorąc je od synów Izraela jako wieczne przymierze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 9, 'I będą należały do Aarona i jego synów: będą je jeść w miejscu świętym, gdyż jest to dla nich najświętsza rzecz ze spalanych ofiar Pana jako wieczysta ustawa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 10, 'W tym czasie syn Izraelitki, którego ojcem był Egipcjanin, wyszedł między synów Izraela. I pokłócił się w obozie syn tej Izraelitki z pewnym Izraelitą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 11, 'I syn Izraelitki bluźnił imieniu Pana i przeklinał. Przyprowadzono go więc do Mojżesza. A jego matce było na imię Szelomit, była córką Dibriego, z pokolenia Dana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 12, 'I osadzili go pod strażą, żeby im oznajmiono, co Pan rozkaże uczynić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 13, 'Wtedy Pan powiedział do Mojżesza:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 14, 'Wyprowadź bluźniercę poza obóz i niech wszyscy, którzy to słyszeli, położą swoje ręce na jego głowie i niech ukamienuje go całe zgromadzenie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 15, 'A synom Izraela powiedz tak: Ktokolwiek przeklnie swego Boga, obciąży się swym grzechem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 16, 'Ten również, kto zbluźnił imieniu Pana, poniesie śmierć: Ukamienuje go całe zgromadzenie. Zarówno przybysz, jak i rodowity mieszkaniec, jeśli zbluźni imieniu Pana, poniesie śmierć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 17, 'Każdy, kto zabije jakiegokolwiek człowieka, poniesie śmierć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 18, 'A kto zabije zwierzę, zwróci inne: zwierzę za zwierzę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 19, 'Kto też ranił swego bliźniego, niech mu uczynią tak, jak on uczynił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 20, 'Złamanie za złamanie, oko za oko, ząb za ząb; jak ranił człowieka, tak niech mu oddadzą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 21, 'Kto zabije zwierzę, zwróci inne; lecz kto zabije człowieka, poniesie śmierć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 22, 'Będziecie mieli jedno prawo zarówno dla przybysza, jak i dla rodowitego mieszkańca, gdyż ja jestem Pan, wasz Bóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 23, 'I Mojżesz przemówił do synów Izraela, a wyprowadzili bluźniercę poza obóz i ukamienowali go. I synowie Izraela uczynili tak, jak Pan przykazał Mojżeszowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 1, 'Potem Pan powiedział do Mojżesza na górze Synaj:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 2, 'Przemów do synów Izraela i powiedz im: Gdy wejdziecie do ziemi, którą wam daję, wtedy ziemia będzie obchodzić szabat dla Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 3, 'Przez sześć lat będziesz obsiewał swoje pole i przez sześć lat będziesz obcinał swoją winnicę, i zbierał z niej plony;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 4, 'Lecz w siódmym roku ziemia będzie mieć szabat odpoczynku, szabat dla Pana. Nie będziesz obsiewał swego pola ani obcinał swojej winnicy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 5, 'Nie będziesz żął tego, co samo wyrośnie po twoich żniwach, ani nie będziesz zbierał winogron twojej zaniechanej winnicy. To będzie rok odpoczynku dla ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 6, 'I szabat ziemi będzie dla was pokarmem: dla ciebie, dla twego sługi, dla twojej służącej, dla twego najemnika i dla przybysza, który mieszka u ciebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 7, 'Także dla twego bydła i zwierząt, które są w twojej ziemi; cały jej plon będzie służyć za pokarm.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 8, 'Policzysz też sobie siedem lat szabatowych, to jest siedem razy po siedem lat; okres siedmiu szabatowych lat będzie wynosił czterdzieści dziewięć lat.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 9, 'Wtedy w dziesiątym dniu siódmego miesiąca każesz zatrąbić w trąbę o donośnym dźwięku; w Dniu Przebłagania zatrąbicie po całej waszej ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 10, 'Poświęcicie pięćdziesiąty rok i ogłosicie wolność w ziemi wszystkim jej mieszkańcom. Będzie to dla was rok jubileuszowy. Każdy z was wróci do swojej posiadłości i do swojej rodziny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 11, 'Rok pięćdziesiąty będzie dla was rokiem jubileuszowym. Nie będziecie siać ani żąć tego, co samo wyrosło, ani zbierać winogron z winnic zaniechanych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 12, 'Jest to bowiem rok jubileuszowy, będzie dla was święty. Będziecie jeść to, co na polu urośnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 13, 'W tym roku jubileuszowym każdy z was wróci do swojej posiadłości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 14, 'Jeśli sprzedasz coś swemu bliźniemu albo kupisz coś od niego, niech jeden nie oszukuje drugiego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 15, 'Według liczby lat po roku jubileuszowym kupisz od swego bliźniego i według liczby lat plonów on sprzeda tobie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 16, 'Im więcej będzie lat, tym wyższa będzie cena, a im mniej będzie lat, tym niższa będzie cena, ponieważ on sprzedaje ci ilość rocznych plonów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 17, 'Nie będziecie oszukiwać jeden drugiego, lecz będziesz się bał swego Boga, gdyż ja jestem Pan, wasz Bóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 18, 'Wykonujcie moje ustawy i przestrzegajcie moich praw, i wypełniajcie je, a będziecie mieszkać w tej ziemi bezpiecznie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 19, 'Ziemia wyda swój plon i będziecie jedli do syta, i będziecie bezpiecznie w niej mieszkać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 20, 'A jeśli powiecie: Cóż będziemy jeść w siódmym roku, jeśli nie będziemy siać ani zbierać naszych plonów?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 21, 'Wtedy rozkażę, żeby moje błogosławieństwo przyszło na was w szóstym roku i wyda plon na trzy lata.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 22, 'I będziecie siać w ósmym roku, ale będziecie jeść ze starego plonu aż do dziewiątego roku; dopóki nie nadejdą jego plony, będziecie jeść stare.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 23, 'Ziemia nie będzie sprzedawana na zawsze, gdyż ziemia należy do mnie, a wy jesteście u mnie gośćmi i przybyszami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 24, 'A w całej ziemi waszej posiadłości ustanowicie dla ziemi prawo wykupu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 25, 'Jeśli twój brat zubożeje, a sprzeda coś ze swojej własności i przyjdzie najbliższy krewny, mający prawo wykupu, to niech wykupi, co jego brat sprzedał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 26, 'A jeśli ktoś nie ma nikogo, kto może to wykupić, lecz sam będzie mógł i znajdzie środki na wykup;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 27, 'To odliczy lat od swojej sprzedaży, zwróci resztę temu, komu sprzedał, i wróci do swojej posiadłości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 28, 'Lecz jeśli nie ma środków, aby zwrócić, to pozostanie to, co sprzedał, w ręku tego, który to kupił aż do roku jubileuszowego. W roku jubileuszowym zwolni mu to, a ten wróci do swojej posiadłości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 29, 'Jeśli ktoś sprzeda dom mieszkalny w mieście otoczonym murami, będzie miał prawo wykupu do końca roku sprzedaży; będzie miał prawo wykupu przez cały rok.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 30, 'A jeśli zostanie wykupiony do końca roku, wtedy ten dom w mieście otoczonym murami zostanie własnością na zawsze tego, który go kupił, oraz jego potomków. Nie będzie zwolniony w roku jubileuszowym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 31, 'Ale domy we wsiach, które nie są otoczone murami, będą traktowane na równi z polami ziemi. Będą podlegały prawu wykupu i w roku jubileuszowym zostaną zwolnione.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 32, 'Co do miast Lewitów i domów w miastach ich posiadłości, to Lewitom zawsze przysługuje prawo wykupu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 33, 'A jeśli ktoś kupuje od Lewitów, to kupiony dom lub miejska posiadłość zostaną zwolnione w roku jubileuszowym, gdyż domy miast Lewitów są ich posiadłością pośród synów Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 34, 'Ale pole wokół ich miast nie będzie sprzedawane, gdyż jest ich wieczystą posiadłością.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 35, 'Jeśli twój brat zubożeje i jego ręka osłabnie przy tobie, wspomożesz go, aby mógł żyć przy tobie jako gość lub przybysz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 36, 'Nie bierz od niego lichwy ani odsetek, lecz bój się swego Boga, aby twój brat mógł się żywić przy tobie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 37, 'Nie dasz mu swoich pieniędzy na lichwę ani nie pożyczysz mu swojej żywności dla zysku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 38, 'Ja jestem Pan, wasz Bóg, który was wyprowadził z ziemi Egiptu, aby dać wam ziemię Kanaan i być waszym Bogiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 39, 'Jeśli też zubożeje twój brat przy tobie i zaprzeda się tobie, nie będziesz go obarczał niewolniczą pracą;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 40, 'Będzie u ciebie jako najemnik i jako przybysz; aż do roku jubileuszowego będzie ci służyć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 41, 'Potem odejdzie od ciebie, on i jego dzieci z nim, i wróci do swojej rodziny i do posiadłości swoich przodków.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 42, 'Oni bowiem są moimi sługami, których wyprowadziłem z ziemi Egiptu. Nie będą sprzedawani jako niewolnicy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 43, 'Nie będziesz srogo panował nad nimi, ale będziesz się bał swego Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 44, 'Twój niewolnik i twoja niewolnica, których będziesz miał, będą z tych narodów, które są wokoło was; od nich będziecie kupować niewolnika i niewolnicę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 45, 'Także spośród synów przybyszów mieszkających wśród was będziecie kupować i z potomstwa tych, którzy są z wami, urodzonych w waszej ziemi. Oni będą waszą własnością.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 46, 'Będziecie ich przekazywać waszym dzieciom w dziedzictwie, na dziedziczną własność; będą wam służyć na zawsze. Lecz nad waszymi braćmi, synami Izraela, nikt z was nie będzie srogo panował.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 47, 'A jeśli gość lub przybysz wzbogaci się przy tobie, a twój brat zubożeje przy nim i sprzeda się gościowi lub przybyszowi przy tobie lub potomstwu rodziny przybysza;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 48, 'To po sprzedaniu może zostać wykupiony; ktokolwiek z jego braci może go wykupić;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 49, 'Albo jego stryj, albo syn jego stryja może go wykupić, albo ktokolwiek z jego bliskich krewnych z jego rodziny może go wykupić, albo jeśli go stać, sam siebie wykupi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 50, 'I rozliczy się ze swoim nabywcą od roku swego sprzedania aż do roku jubileuszowego; a pieniądze, za które się sprzedał, zostaną obliczone według liczby lat; postąpi z nim jak z najemnikiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 51, 'Jeśli zostało jeszcze wiele lat, to według ich liczby zwróci swój wykup z pieniędzy, za które został kupiony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 52, 'A jeśli do roku jubileuszowego zostało niewiele lat, to rozliczy się z nim i według ich liczby tych lat zwróci swój wykup.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 53, 'Będzie u niego jako najemnik, rok po roku; nie będzie nad nim srogo panował na twoich oczach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 54, 'A jeśli nie zostanie wykupiony tymi sposobami, wtedy wyjdzie wolny w roku jubileuszowym, on razem ze swoimi dziećmi;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 55, 'Bo synowie Izraela są moimi sługami. Są moimi sługami, których wyprowadziłem z ziemi Egiptu. Ja jestem Pan, wasz Bóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 1, 'Nie czyńcie sobie bożków ani rzeźbionego posągu ani nie stawiajcie stel, ani kamiennych rzeźb w waszej ziemi, by im oddawać pokłon, bo ja jestem Pan, wasz Bóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 2, 'Będziecie zachowywać moje szabaty i czcić moją świątynię. Ja jestem Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 3, 'Jeśli będziecie postępować według moich ustaw i przestrzegać moich przykazań, i wykonywać je;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 4, 'To ześlę wam deszcze we właściwym czasie i ziemia wyda swój plon, i drzewa polne wydadzą swój owoc;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 5, 'Młocka będzie trwać do winobrania, a winobranie do siewu; będziecie jeść swój chleb do syta i mieszkać bezpiecznie w swojej ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 6, 'Udzielę ziemi pokoju, położycie się i nikt was nie będzie straszył. Usunę z ziemi groźne zwierzę i miecz nie przejdzie przez waszą ziemię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 7, 'Będziecie ścigać waszych wrogów i upadną przed wami od miecza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 8, 'Pięciu z was będzie ścigać stu, a stu z was będzie ścigać dziesięć tysięcy. I wasi wrogowie padną przed wami od miecza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 9, 'Zwrócę się bowiem ku wam i rozplenię was, rozmnożę was i utwierdzę moje przymierze z wami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 10, 'I będziecie jedli zboże z poprzednich zbiorów, potem wyniesiecie stare, gdy nastaną nowe.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 11, 'Umieszczę też mój przybytek wśród was i moja dusza nie obrzydzi was sobie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 12, 'I będę przechadzał się wśród was, i będę waszym Bogiem, a wy będziecie moim ludem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 13, 'Ja jestem Pan, wasz Bóg, który wyprowadził was z ziemi Egiptu, abyście już nie byli ich niewolnikami; i połamałem więzy waszego jarzma, abyście chodzili wyprostowani.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 14, 'Jeśli jednak nie posłuchacie mnie i nie wykonacie wszystkich tych przykazań;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 15, 'I jeśli wzgardzicie moimi ustawami, i wasza dusza będzie się brzydzić moimi sądami, tak że nie wykonacie wszystkich moich przykazań i złamiecie moje przymierze;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 16, 'To i ja z wami tak postąpię: Dotknę was przerażeniem, wycieńczeniem i gorączką, które wyniszczą wam oczy i napełnią wasze dusze boleścią. Na próżno będziecie siać wasze ziarno, bo zjedzą je wasi wrogowie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 17, 'I zwrócę moje oblicze przeciwko wam, i zostaniecie pobici przez waszych wrogów. Ci, którzy was nienawidzą, będą panować nad wami i będziecie uciekali, choć nikt was nie będzie ścigać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 18, 'A jeśli mimo to nie posłuchacie mnie, będę karał was siedem razy więcej za wasze grzechy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 19, 'Złamię pychę waszej potęgi i niebo nad wami uczynię jak z żelaza, a waszą ziemię jak z miedzi;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 20, 'I wasza praca będzie szła na próżno, bo wasza ziemia nie wyda swego plonu, a drzewa ziemi nie wydadzą swego owocu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 21, 'A jeśli będziecie postępować na przekór mnie i nie zechcecie mnie słuchać, to przydam wam siedem razy więcej plag za wasze grzechy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 22, 'Ześlę też na was dzikie zwierzęta, które was osierocą, wyniszczą wasze bydło i zmniejszą waszą liczbę, tak że opustoszeją wasze drogi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 23, 'A jeśli przez to nie poprawicie się, ale będziecie postępować na przekór mnie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 24, 'To i ja postąpię na przekór wam i będę was karał siedmiokrotnie za wasze grzechy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 25, 'I sprowadzę na was miecz, który pomści złamane przymierze; gdy zbierzecie się w swych miastach, wtedy ześlę zarazę pomiędzy was i będziecie wydani w ręce wroga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 26, 'A gdy złamię podporę waszego chleba, dziesięć kobiet będzie piec wasz chleb w jednym piecu i będą wam wydzielać wasz chleb na wagę; będziecie jeść, lecz się nie nasycicie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 27, 'A jeśli mimo to nie posłuchacie mnie, ale będziecie postępować na przekór mnie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 28, 'To ja też postąpię na przekór wam z gniewem; też będę was karać siedmiokrotnie za wasze grzechy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 29, 'I będziecie jeść ciało waszych synów i ciało waszych córek.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 30, 'Zniszczę wasze wyżyny, zburzę wasze posągi i rzucę wasze szczątki na szczątki waszych bożków, a moja dusza będzie się wami brzydzić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 31, 'I zamienię wasze miasta w ruiny, i zburzę wasze świątynie, i więcej nie przyjmę waszych wdzięcznych wonności.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 32, 'I spustoszę ziemię tak, że zdumieją się nad nią wasi wrogowie, którzy w niej mieszkają.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 33, 'A was rozproszę między narodami i dobędę miecz za wami; wasza ziemia będzie spustoszona i wasze miasta zburzone.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 34, 'Wtedy ziemia ucieszy się swoimi szabatami przez wszystkie dni swojego spustoszenia, a wy będziecie w ziemi waszych wrogów. Wtedy ziemia odpocznie i ucieszy się swoimi szabatami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 35, 'Przez wszystkie dni swojego spustoszenia będzie odpoczywać, gdyż nie odpoczywała w czasie waszych szabatów, kiedy w niej mieszkaliście.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 36, 'A tym, którzy z was pozostaną, ześlę do ich serc lękliwość w ziemiach ich wrogów, tak że będzie ich ścigać szelest opadającego liścia i będą uciekać jak przed mieczem, i będą padać, chociaż nikt nie będzie ich ścigać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 37, 'I padną jeden na drugiego jakby od miecza, choć nikt ich nie będzie ścigać. Nie będziecie mogli się ostać przed waszymi wrogami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 38, 'Zginiecie wśród narodów i pożre was ziemia waszych wrogów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 39, 'A ci z was, którzy zostaną, zgniją z powodu swojej nieprawości w ziemi swoich wrogów; także z powodu nieprawości swoich ojców zgniją wraz z nimi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 40, 'Ale jeśli wyznają swoją nieprawość i nieprawość swoich ojców oraz przewinienie, którymi wystąpili przeciwko mnie, oraz to, że postępowali na przekór mnie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 41, 'I że ja postępowałem na przekór im, i wprowadziłem ich do ziemi ich wrogów; jeśli wtedy ukorzą się ich nieobrzezane serca i będą znosić karę za swoje nieprawości;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 42, 'Wtedy wspomnę na moje przymierze z Jakubem i na moje przymierze z Izaakiem, wspomnę też na moje przymierze z Abrahamem, wspomnę i na tę ziemię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 43, 'A ziemia będzie przez nich opuszczona i ucieszy się swoimi szabatami, gdy będzie spustoszona z ich powodu. Będą cierpliwie nosić karę za swoją nieprawość, ponieważ wzgardzili moimi sądami i ich dusza obrzydziła sobie moje ustawy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 44, 'Lecz mimo tego wszystkiego, gdy będą w ziemi swoich wrogów, nie odrzucę ich ani nie obrzydzę ich sobie tak, by ich wytępić i złamać moje przymierze z nimi, gdyż ja jestem Pan, ich Bóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 45, 'Ale dla nich wspomnę na przymierze ich przodków, których wyprowadziłem z ziemi Egiptu na oczach pogan, aby być ich Bogiem. Ja jestem Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 46, 'To są ustawy, sądy i prawa, które ustanowił Pan między sobą a synami Izraela na górze Synaj za pośrednictwem Mojżesza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 1, 'Potem Pan powiedział do Mojżesza:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 2, 'Przemów do synów Izraela i powiedz im: Jeśli ktoś złoży Panu szczególny ślub, da okup według twojego oszacowania.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 3, 'A takie będzie twoje oszacowanie: Za mężczyznę w wieku od dwudziestu do sześćdziesięciu lat będzie wynosiło pięćdziesiąt syklów srebra według sykla świątynnego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 4, 'A jeśli to jest kobieta, twoje oszacowanie będzie wynosiło trzydzieści syklów;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 5, 'A jeśli to będzie ktoś w wieku od pięciu do dwudziestu lat, wtedy twoje oszacowanie za osobę płci męskiej będzie wynosiło dwadzieścia syklów, a za osobę płci żeńskiej – dziesięć syklów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 6, 'A jeśli to jest dziecko w wieku od jednego miesiąca do pięciu lat, wtedy twoje oszacowanie za chłopca będzie wynosiło pięć syklów srebra, a za dziewczynkę twoje oszacowanie będzie wynosiło trzy sykle srebra.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 7, 'A jeśli to jest ktoś w wieku od sześćdziesięciu lat wzwyż, jeśli to jest mężczyzna, wtedy twoje szacowanie będzie wynosiło piętnaście syklów, a za kobietę – dziesięć syklów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 8, 'Lecz jeśli jest tak ubogi, że nie może zapłacić twego oszacowania, wtedy postawią go przed kapłanem i kapłan go oszacuje. Według możności tego, który ślubował, oszacuje go kapłan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 9, 'Jeśli to, co będzie Panu składane w ofierze, jest ze zwierząt, to wszystko z tego, które będzie oddane Panu, będzie święte;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 10, 'Nie zamieni go ani nie zastąpi go czym innym, ani lepszego gorszym, ani gorszego lepszym. Jeśli jednak nawet zastąpi zwierzę innym zwierzęciem, to ono i to, czym zostało zastąpione, będzie święte.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 11, 'A jeśli to będzie nieczyste zwierzę, którego nie składa się Panu w ofierze, wtedy stawi to zwierzę przed kapłanem;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 12, 'I kapłan je oszacuje, według tego, czy jest dobre, czy marne. Jak ty, kapłanie, je oszacujesz, tak będzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 13, 'A jeśli zechce je wykupić, to doda jedną piątą do twojego oszacowania.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 14, 'Jeśli ktoś poświęci swój dom, żeby był święty dla Pana, wtedy kapłan oszacuje go według tego, czy jest dobry, czy marny. Jak kapłan go oszacuje, tak zostanie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 15, 'A jeśli ten, który poświęcił, zechce wykupić swój dom, to doda jedną piątą wartości twego oszacowania i dom będzie jego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 16, 'Jeśli ktoś poświęci Panu część pola swojej posiadłości, wtedy twoje oszacowanie będzie według ilości wysianego ziarna; chomer jęczmienia odpowiada pięćdziesięciu syklom srebra.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 17, 'Jeśli poświęcił swoje pole do roku jubileuszowego, to zostanie według twego oszacowania.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 18, 'Ale jeśli poświęcił swoje pole po roku jubileuszowym, wtedy kapłan obliczy mu pieniądze według lat, które zostają do roku jubileuszowego, i zostanie to odjęte od twego szacowania.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 19, 'A jeśli ten, który poświęcił pole, zechce je wykupić, to doda jedną piątą wartości twego oszacowania i pole będzie jego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 20, 'Ale jeśli nie wykupi pola, lecz będzie ono sprzedane komuś innemu, nie może być już wykupione.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 21, 'I to pole, gdy stanie się wolne w roku jubileuszowym, będzie święte dla Pana jako pole poświęcone; stanie się posiadłością kapłana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 22, 'A jeśli ktoś poświęca Panu kupione pole, które nie należy do pól jego posiadłości;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 23, 'Wówczas kapłan obliczy mu wysokość oszacowania aż do roku jubileuszowego i on tego samego dnia odda sumę twego szacowania jako rzecz świętą Panu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 24, 'A w roku jubileuszowym pole wróci do tego, od którego zostało kupione, do którego posiadłość tej ziemi należy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 25, 'A każde twoje oszacowanie będzie według sykla świątynnego. Jeden sykl będzie wynosił dwadzieścia ger.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 26, 'Jednak pierworodnego ze zwierząt, które jako pierworodne należą do Pana, nikt nie poświęci, czy to wołu, czy owcy; należy do Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 27, 'A jeśli będzie ze zwierząt nieczystych, to wykupi je według twego oszacowania i doda do tego jedną piątą; a jeśli nie zostanie wykupione, niech zostanie sprzedane według twego oszacowania.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 28, 'Natomiast każda rzecz poświęcona, którą kto poświęca Panu ze wszystkiego, co ma – czy to z ludzi, czy ze zwierząt, czy z pola swojej posiadłości – nie będzie sprzedawana ani wykupiona, bo wszelka rzecz poświęcona jest najświętsza dla Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 29, 'To, co poświęcone, które będzie poświęcone przez człowieka, nie będzie odkupione, ale poniesie śmierć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 30, 'Wszelka dziesięcina ziemi – czy to z nasienia ziemi, czy z owocu drzewa – należy do Pana. Jest ona poświęcona Panu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 31, 'Ale jeśli ktoś zechce wykupić część swoich dziesięcin, doda do nich jedną piątą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 32, 'Także wszelka dziesięcina z bydła i z trzody, ze wszystkiego, co przechodzi pod laską pasterską, każde dziesiąte będzie poświęcone Panu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 33, 'Nikt nie będzie przebierał między dobrym a marnym ani nie będzie go zamieniać; a jeśli je nawet zamieni, to ono i to, na co zostało zamienione, będzie święte. Nie można tego wykupić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 34, 'To są przykazania, które Pan rozkazał Mojżeszowi dla synów Izraela na górze Synaj.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 1, 'Pan przemówił do Mojżesza na pustyni Synaj, w Namiocie Zgromadzenia, pierwszego dnia drugiego miesiąca, w drugim roku po ich wyjściu z ziemi Egiptu, tymi słowy:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 2, 'Policzcie całe zgromadzenie synów Izraela według ich rodzin i według domów ich ojców, licząc imiona wszystkich mężczyzn, głowa po głowie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 3, 'Od dwudziestu lat wzwyż, wszystkich w Izraelu zdolnych do walki. Ty i Aaron policzycie ich według ich oddziałów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 4, 'I będzie z wami jeden mężczyzna z każdego pokolenia, głowa domu swoich ojców.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 5, 'A oto imiona mężczyzn, którzy będą z wami: z pokolenia Rubena – Elizur, syn Szedeura;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 6, 'Z Symeona – Szelumiel, syn Suriszaddaja;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 7, 'Z Judy – Nachszon, syn Amminadaba;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 8, 'Z Issachara – Netaneel, syn Suara;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 9, 'Z Zebulona – Eliab, syn Chelona;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 10, 'Z synów Józefa: z Efraima – Eliszama, syn Ammihuda, z Manassesa – Gamliel, syn Pedahsura;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 11, 'Z Beniamina – Abidan, syn Gideoniego;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 12, 'Z Dana – Achiezer, syn Ammiszaddaja;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 13, 'Z Aszera – Pagiel, syn Okrana;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 14, 'Z Gada – Eliasaf, syn Deuela;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 15, 'Z Neftalego – Achira, syn Enana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 16, 'Ci powołani, sławni spośród zgromadzenia, byli naczelnikami pokoleń swych ojców, wodzami tysięcy w Izraelu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 17, 'Mojżesz i Aaron przyjęli więc tych mężczyzn, którzy zostali imiennie wyznaczeni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 18, 'I zebrali całe zgromadzenie w pierwszym dniu drugiego miesiąca, a każdy podawał swoje pochodzenie według swych rodzin, według domów swych ojców i według liczby imion, od dwudziestu lat wzwyż, głowa po głowie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 19, 'Jak Pan rozkazał Mojżeszowi, tak policzył ich na pustyni Synaj.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 20, 'Synów Rubena, pierworodnego Izraela, ich potomków według ich rodzin, według domów ich ojców, według liczby imion, głowa po głowie, wszystkich mężczyzn od dwudziestu lat wzwyż, wszystkich zdolnych do walki;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 21, 'Naliczono z pokolenia Rubena czterdzieści sześć tysięcy pięciuset.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 22, 'Synów Symeona, ich potomków według ich rodzin, według domów ich ojców, naliczonych według liczby imion, głowa po głowie, wszystkich mężczyzn od dwudziestu lat wzwyż, wszystkich zdolnych do walki;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 23, 'Naliczono z pokolenia Symeona pięćdziesiąt dziewięć tysięcy trzystu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 24, 'Synów Gada, ich potomków według ich rodzin, według domów ich ojców, według liczby imion, od dwudziestu lat wzwyż, wszystkich zdolnych do walki;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 25, 'Naliczono z pokolenia Gada czterdzieści pięć tysięcy sześciuset pięćdziesięciu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 26, 'Synów Judy, ich potomków według ich rodzin, według domów ich ojców, według liczby imion, od dwudziestu lat wzwyż, wszystkich zdolnych do walki;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 27, 'Naliczono z pokolenia Judy siedemdziesiąt cztery tysiące sześciuset.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 28, 'Synów Issachara, ich potomków według ich rodzin, według domów ich ojców, według liczby imion, od dwudziestu lat wzwyż, wszystkich zdolnych do walki;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 29, 'Naliczono z pokolenia Issachara pięćdziesiąt cztery tysiące czterystu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 30, 'Synów Zebulona, ich potomków według ich rodzin, według domów ich ojców, według liczby imion, od dwudziestu lat wzwyż, wszystkich zdolnych do walki;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 31, 'Naliczono z pokolenia Zebulona pięćdziesiąt siedem tysięcy czterystu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 32, 'Synów Józefa, z synów Efraima, ich potomków według ich rodzin, według domów ich ojców, według liczby imion, od dwudziestu lat wzwyż, wszystkich zdolnych do walki;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 33, 'Naliczono z pokolenia Efraima czterdzieści tysięcy pięciuset.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 34, 'Synów Manassesa, ich potomków według ich rodzin, według domów ich ojców, według liczby imion, od dwudziestu lat wzwyż, wszystkich zdolnych do walki;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 35, 'Naliczono z pokolenia Manassesa trzydzieści dwa tysiące dwustu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 36, 'Synów Beniamina, ich potomków według ich rodzin, według domów ich ojców, według liczby imion, od dwudziestu lat wzwyż, wszystkich zdolnych do walki;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 37, 'Naliczono z pokolenia Beniamina trzydzieści pięć tysięcy czterystu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 38, 'Synów Dana, ich potomków według ich rodzin, według domów ich ojców, według liczby imion, od dwudziestu lat wzwyż, wszystkich zdolnych do walki;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 39, 'Naliczono z pokolenia Dana sześćdziesiąt dwa tysiące siedmiuset.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 40, 'Synów Aszera, ich potomków według ich rodzin, według domów ich ojców, według liczby imion, od dwudziestu lat wzwyż, wszystkich zdolnych do walki;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 41, 'Naliczono z pokolenia Aszera czterdzieści jeden tysięcy pięciuset.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 42, 'Synów Neftalego, ich potomków według ich rodzin, według domów ich ojców, według liczby imion, od dwudziestu lat wzwyż, wszystkich zdolnych do walki;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 43, 'Naliczono z pokolenia Neftalego pięćdziesiąt trzy tysiące czterystu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 44, 'To są ci, których policzyli Mojżesz, Aaron i książęta Izraela, dwunastu mężczyzn, po jednym z każdego domu swych ojców.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 45, 'I było wszystkich policzonych synów Izraela, według domów ich ojców, od dwudziestu lat wzwyż, wszystkich zdolnych do walki w Izraelu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 46, 'Wszystkich policzonych było sześćset trzy tysiące pięciuset pięćdziesięciu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 47, 'Lecz Lewici nie zostali policzeni z nimi według pokolenia swych ojców.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 48, 'Pan rozkazał bowiem Mojżeszowi:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 49, 'Tylko pokolenia Lewiego nie spisuj i nie licz go razem z synami Izraela;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 50, 'Lecz ustanowisz Lewitów nad Przybytkiem Świadectwa i nad wszystkimi jego naczyniami, i nad wszystkim, co do niego należy. Oni będą nosić przybytek i wszystkie jego sprzęty; oni też będą go obsługiwać i rozbijać obóz dokoła przybytku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 51, 'A gdy przybytek będzie miał wyruszyć, Lewici go rozbiorą; także gdy przybytek ma być wznoszony, Lewici ustawią go; a obcy, który się do niego zbliży, poniesie śmierć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 52, 'I synowie Izraela będą rozbijać namioty, każdy w swoim obozie i każdy pod swoim sztandarem, według swych zastępów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 53, 'Lecz Lewici rozbiją obóz wokół Przybytku Świadectwa, aby gniew nie spadł na zgromadzenie synów Izraela. Lewici będą pełnić straż przy Przybytku Świadectwa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 54, 'I synowie Izraela uczynili zgodnie ze wszystkim, co Pan rozkazał Mojżeszowi, tak właśnie uczynili.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 1, 'Potem Pan przemówił do Mojżesza i Aarona:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 2, 'Każdy z synów Izraela rozbije obóz przy swoim sztandarze, pod znakami domów swych ojców. Będą rozbijać obóz w pewnej odległości od Namiotu Zgromadzenia, wokół niego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 3, 'Od strony wschodniej rozbiją obóz ludzie pod sztandarem obozu Judy, według swych oddziałów, a wodzem nad synami Judy będzie Nachszon, syn Amminadaba;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 4, 'A jego policzony zastęp wynosił siedemdziesiąt cztery tysiące sześciuset ludzi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 5, 'Obok niego rozbije obóz pokolenie Issachara, a wodzem synów Issachara będzie Netaneel, syn Suara;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 6, 'A jego policzony zastęp wynosił pięćdziesiąt cztery tysiące czterystu ludzi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 7, 'Obok nich – pokolenie Zebulona, a wodzem synów Zebulona będzie Eliab, syn Chelona;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 8, 'A jego policzony zastęp wynosił pięćdziesiąt siedem tysięcy czterystu ludzi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 9, 'Wszystkich policzonych w obozie Judy, według ich zastępów, było sto osiemdziesiąt sześć tysięcy czterystu. Oni wyruszą pierwsi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 10, 'Od strony południowej będzie sztandar obozu Rubena, według swych zastępów, a wodzem synów Rubena będzie Elisur, syn Szedeura;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 11, 'A jego policzony zastęp wynosił czterdzieści sześć tysięcy pięciuset ludzi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 12, 'Obok niego rozbije obóz pokolenie Symeona, a wodzem synów Symeona będzie Szelumiel, syn Suriszaddaja;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 13, 'A jego policzony zastęp wynosił pięćdziesiąt dziewięć tysięcy trzystu ludzi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 14, 'Następnie pokolenie Gada, a wodzem synów Gada będzie Eliasaf, syn Reuela;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 15, 'A jego policzony zastęp wynosił czterdzieści pięć tysięcy sześciuset pięćdziesięciu ludzi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 16, 'Wszystkich policzonych w obozie Rubena, według ich zastępów, było sto pięćdziesiąt jeden tysięcy czterystu pięćdziesięciu. Oni wyruszą w drugiej kolejności.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 17, 'Następnie wyruszy Namiot Zgromadzenia z obozem Lewitów pośrodku obozu. Jak będą obozować, tak będą wyruszać, każdy na swoim miejscu, pod swoim sztandarem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 18, 'Od strony zachodniej będzie sztandar obozu Efraima, według swych zastępów, a wodzem synów Efraima będzie Eliszama, syn Ammihuda;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 19, 'A jego policzony zastęp wynosił czterdzieści tysięcy pięciuset ludzi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 20, 'Obok niego pokolenie Manassesa, a wodzem synów Manassesa będzie Gamliel, syn Pedahsura.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 21, 'A jego policzony zastęp wynosił trzydzieści dwa tysiące dwustu ludzi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 22, 'Następnie pokolenie Beniamina, a wodzem synów Beniamina będzie Abidan, syn Gideoniego;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 23, 'A jego policzony zastęp wynosił trzydzieści pięć tysięcy czterystu ludzi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 24, 'Wszystkich policzonych w obozie Efraima było sto osiem tysięcy stu według swoich zastępów. Oni wyruszą w trzeciej kolejności.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 25, 'Od strony północnej będzie sztandar obozu Dana, według swych zastępów, a wodzem synów Dana będzie Achiezer, syn Ammiszadaja;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 26, 'A jego policzony zastęp wynosił sześćdziesiąt dwa tysiące siedmiuset ludzi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 27, 'Obok niego rozbije obóz pokolenie Aszera, a wodzem synów Aszera będzie Pagiel, syn Okrana;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 28, 'A jego policzony zastęp wynosił czterdzieści jeden tysięcy pięciuset ludzi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 29, 'Następnie pokolenie Neftalego, a wodzem synów Neftalego będzie Achira, syn Enana;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 30, 'A jego policzony zastęp wynosił pięćdziesiąt trzy tysiące czterystu ludzi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 31, 'Wszystkich policzonych w obozie Dana było sto pięćdziesiąt siedem tysięcy sześciuset. Oni wyruszą ostatni pod swoimi sztandarami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 32, 'To są policzeni spośród synów Izraela według domów ich ojców. Wszystkich policzonych w obozach, według ich zastępów, było sześćset trzy tysiące pięciuset pięćdziesięciu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 33, 'Lewitów zaś nie liczono wśród synów Izraela, jak Pan rozkazał Mojżeszowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 34, 'I synowie Izraela uczynili zgodnie ze wszystkim, co Pan rozkazał Mojżeszowi: tak rozbijali obozy przy swych sztandarach i tak wyruszali, każdy według swych rodzin i według domów swych ojców.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 1, 'To są dzieje rodu Aarona i Mojżesza w dniu, w którym Pan rozmawiał z Mojżeszem na górze Synaj.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 2, 'A to są imiona synów Aarona: pierworodny Nadab, potem Abihu, Eleazar i Itamar.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 3, 'To są imiona synów Aarona, namaszczonych kapłanów, których poświęcił, aby pełnili urząd kapłański.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 4, 'Lecz Nadab i Abihu umarli przed Panem, gdy ofiarowali inny ogień przed Panem na pustyni Synaj, i odeszli bez potomków. Eleazar i Itamar pełnili więc urząd kapłański przed obliczem swego ojca Aarona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 5, 'Wtedy Pan powiedział do Mojżesza:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 6, 'Każ się zbliżyć pokoleniu Lewiego i postaw ich przed kapłanem Aaronem, aby mu służyli;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 7, 'I pełnili straż, która go obowiązuje oraz straż całego zgromadzenia, przed Namiotem Zgromadzenia, wykonując służbę przybytku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 8, 'Będą strzec wszystkich sprzętów Namiotu Zgromadzenia i pełnić straż synów Izraela, wykonując służbę przybytku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 9, 'Oddasz więc Lewitów Aaronowi i jego synom; będą mu całkowicie oddani spośród synów Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 10, 'Aarona zaś i jego synów ustanowisz, aby pełnili swoje kapłaństwo. A obcy, który się zbliży, poniesie śmierć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 11, 'Potem Pan powiedział do Mojżesza:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 12, 'Oto wziąłem Lewitów spośród synów Izraela na miejsce wszystkich pierworodnych, którzy otwierają łono wśród synów Izraela, i dlatego Lewici będą należeć do mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 13, 'Do mnie bowiem należy wszystko, co pierworodne. W dniu, kiedy zabiłem wszystko, co pierworodne w ziemi Egiptu, poświęciłem sobie wszystko, co pierworodne w Izraelu, od człowieka aż do zwierzęcia. Będą należeć do mnie; ja jestem Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 14, 'Pan powiedział też do Mojżesza na pustyni Synaj:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 15, 'Policz synów Lewiego według domów ich ojców i według ich rodzin. Policzysz każdego mężczyznę w wieku od jednego miesiąca wzwyż.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 16, 'I Mojżesz policzył ich według słowa Pana, jak mu rozkazano.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 17, 'Oto imiona synów Lewiego: Gerszon, Kehat i Merari.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 18, 'A imiona synów Gerszona według ich domów: Libni i Szimei.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 19, 'A synowie Kehata według swych domów: Amram, Ishar, Chebron i Uzziel.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 20, 'Synowie zaś Merariego według swych domów: Machli i Muszi. To są rodziny Lewiego według domów ich ojców.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 21, 'Od Gerszona pochodzi rodzina Libnitów i rodzina Szimeitów. To są rodziny Gerszonitów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 22, 'Liczba wszystkich policzonych mężczyzn w wieku od jednego miesiąca wzwyż wynosiła u nich siedem tysięcy pięciuset.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 23, 'Rodziny Gerszonitów rozbiją obóz za przybytkiem od strony zachodniej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 24, 'A wodzem domu ojca Gerszonitów będzie Eliasaf, syn Laela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 25, 'A pod strażą synów Gerszona w Namiocie Zgromadzenia będzie przybytek i namiot, jego przykrycie i zasłona u wejścia do Namiotu Zgromadzenia;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 26, 'I zasłony dziedzińca, zasłona u wejścia na dziedziniec, który otacza przybytek i ołtarz wokoło, oraz jego sznury potrzebne do wszelkich prac.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 27, 'Od Kehata zaś pochodzą rodziny: Amramitów, Isharytów, Chebronitów i Uzzielitów. To są rodziny Kehatytów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 28, 'Liczba wszystkich mężczyzn w wieku od jednego miesiąca wzwyż wynosiła osiem tysięcy sześciuset pełniących straż w świątyni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 29, 'Rodziny synów Kehata rozbiją obóz po południowej stronie przybytku;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 30, 'A wodzem domu ojca rodziny Kehatytów będzie Elisafan, syn Uzziela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 31, 'Pod ich strażą będzie arka, stół, świecznik, ołtarze i sprzęty świątyni, którymi będą usługiwać, oraz zasłona wraz z całą jej obsługą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 32, 'Naczelnym wodzem Lewitów będzie Eleazar, syn kapłana Aarona, on będzie miał nadzór nad tymi, którzy pełnią straż w świątyni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 33, 'Od Merariego pochodzą zaś rodziny Machlitów i Muszytów. To są rodziny Merarytów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 34, 'A liczba wszystkich policzonych mężczyzn w wieku od jednego miesiąca wzwyż wynosiła u nich sześć tysięcy dwustu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 35, 'Wodzem zaś domu ojca rodzin Merariego był Suriel, syn Abichaila. Oni rozbiją obóz po stronie północnej przybytku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 36, 'A pod nadzorem i strażą synów Merariego będą deski przybytku, jego drążki, słupy i podstawki oraz wszystkie jego sprzęty wraz z całą jego obsługą;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 37, 'Także słupy wokoło dziedzińca, ich podstawki, kołki i ich sznury.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 38, 'A przed przybytkiem od strony wschodniej, przed Namiotem Zgromadzenia, rozbiją obóz Mojżesz, Aaron i jego synowie, pełniący straż w świątyni za synów Izraela; a obcy, który się zbliży, poniesie śmierć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 39, 'Wszystkich Lewitów policzonych przez Mojżesza i Aarona na rozkaz Pana według ich rodzin, wszystkich mężczyzn w wieku od jednego miesiąca wzwyż było dwadzieścia dwa tysiące.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 40, 'Wtedy Pan powiedział do Mojżesza: Policz wszystkich pierworodnych mężczyzn spośród synów Izraela w wieku od jednego miesiąca wzwyż i sporządź spis ich imion.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 41, 'I weźmiesz dla mnie Lewitów – ja jestem Pan – w zamian za wszystkich pierworodnych spośród synów Izraela, a także bydła Lewitów zamiast wszystkiego, co pierworodne, wśród bydła synów Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 42, 'Mojżesz policzył więc wszystkich pierworodnych spośród synów Izraela, tak jak Pan mu rozkazał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 43, 'A liczba wszystkich pierworodnych mężczyzn w wieku od jednego miesiąca wzwyż, według liczby imion, wynosiła dwadzieścia dwa tysiące dwieście siedemdziesiąt trzy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 44, 'I Pan powiedział do Mojżesza:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 45, 'Weź Lewitów na miejsce wszystkich pierworodnych spośród synów Izraela, a także bydło Lewitów na miejsce ich bydła; i Lewici będą należeć do mnie. Ja jestem Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 46, 'A jako wykup za tych dwustu siedemdziesięciu trzech pierworodnych spośród synów Izraela, którzy przewyższają liczbę Lewitów;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 47, 'Weźmiesz po pięć syklów na głowę według sykla świątynnego: sykl po dwadzieścia ger.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 48, 'I oddasz te pieniądze Aaronowi i jego synom jako wykup za tych, którzy przewyższają ich liczbę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 49, 'Mojżesz wziął więc pieniądze wykupu od tych, którzy przewyższali liczbę wykupionych przez Lewitów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 50, 'Od pierworodnych synów Izraela wziął tysiąc trzysta sześćdziesiąt pięć syklów według sykla świątynnego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 51, 'I Mojżesz oddał te pieniądze wykupu Aaronowi i jego synom według słowa Pana, tak jak Pan rozkazał Mojżeszowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 1, 'I Pan przemówił do Mojżesza i Aarona tymi słowy:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 2, 'Policz synów Kehata spośród synów Lewiego według ich rodzin i według domów ich ojców;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 3, 'Od trzydziestego roku życia wzwyż aż do pięćdziesiątego roku życia; wszystkich, którzy są zdolni do służby, aby wykonywali pracę w Namiocie Zgromadzenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 4, 'Służbą synów Kehata w Namiocie Zgromadzenia będzie troska o rzeczy najświętsze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 5, 'Gdy obóz będzie ruszał, przyjdzie Aaron ze swymi synami i zdejmą zasłonę okrywającą, którą okryją arkę świadectwa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 6, 'A położą na niej przykrycie ze skór borsuczych i na tym rozciągną nakrycie z błękitnej tkaniny, i założą jej drążki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 7, 'Stół chlebów pokładnych również przykryją tkaniną z błękitu i położą na nim misy, czasze, przystawki i kubki do nalewania; a będzie na nim nieustanny chleb.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 8, 'I rozciągną na tym tkaninę karmazynową i przykryją to przykryciem ze skór borsuczych, i założą jego drążki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 9, 'Wezmą też tkaninę z błękitu, którą okryją świecznik do świecenia i jego lampy, szczypce, naczynia na popiół oraz wszystkie jego naczynia na oliwę, których się przy nim używa;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 10, 'I owiną go wraz ze wszystkimi jego naczyniami przykryciem ze skór borsuczych i umieszczą na drążkach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 11, 'Rozciągną nad złotym ołtarzem tkaninę z błękitu i przykryją go przykryciem ze skór borsuczych, i założą jego drążki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 12, 'Wezmą też wszystkie sprzęty do służby, którymi służą w świątyni, owiną je tkaniną z błękitu, przykryją je okryciem ze skór borsuczych i umieszczą na drążkach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 13, 'Następnie oczyszczą ołtarz z popiołu i rozciągną na nim purpurową tkaninę;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 14, 'I położą na nim wszystkie jego sprzęty używane do służby przy nim: kadzielnice, widełki, łopatki i kropielnice, wszystkie naczynia ołtarza, i rozciągną na nim przykrycie ze skór borsuczych, i założą jego drążki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 15, 'Kiedy Aaron i jego synowie skończą przykrywanie świątyni wraz ze wszystkimi jej naczyniami, gdy obóz będzie miał wyruszyć, wtedy przyjdą synowie Kehata, aby je nieść. Lecz nie będą dotykać świętych przedmiotów, aby nie umarli. To jest służba synów Kehata przy Namiocie Zgromadzenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 16, 'A Eleazar, syn kapłana Aarona, będzie troszczył się o oliwę do oświetlenia, wonne kadzidło, stałą ofiarę pokarmową i oliwę do namaszczania oraz będzie doglądał przybytku i wszystkiego, co w nim jest, i w miejscu świętym i przy jego naczyniach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 17, 'Potem Pan powiedział do Mojżesza i Aarona:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 18, 'Nie pozwólcie, by pokolenie rodzin Kehatytów zostało wycięte spośród Lewitów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 19, 'Ale to im uczynicie, aby żyli i nie pomarli, gdy będą się zbliżać do rzeczy najświętszych: Aaron i jego synowie przyjdą i wyznaczą każdemu z nich, co ma czynić i co ma nieść.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 20, 'Lecz niech nie wchodzą się przyglądać, kiedy rzeczy święte będą przykrywane, by nie pomarli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 21, 'Pan dalej mówił do Mojżesza:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 22, 'Policz synów Gerszona według domów ich ojców i według ich rodzin;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 23, 'Policz tych, którzy są w wieku od trzydziestu lat wzwyż aż do lat pięćdziesięciu; wszystkich, którzy są zdolni do tej pracy, aby mogli pełnić służbę przy Namiocie Zgromadzenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 24, 'A to będzie zadanie rodzin Gerszonitów, do służby i do noszenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 25, 'Będą nosić zasłony przybytku, Namiot Zgromadzenia, jego przykrycie i przykrycie borsucze, które jest na wierzchu, oraz zasłonę u wejścia do Namiotu Zgromadzenia;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 26, 'Zasłony dziedzińca i zasłonę u bramy wejściowej na dziedziniec, który otacza przybytek i ołtarz wokoło, ich sznury i wszystkie przybory do pracy przy nich oraz wszystko, co jest do tego zrobione; tak będą służyć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 27, 'Wszelka służba synów Gerszonitów związana ze wszystkimi ich ciężarami oraz z całą ich służbą ma odbywać się zgodnie z rozkazem Aarona i jego synów; i powierzycie im troskę o wszystkie ich ciężary.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 28, 'To będzie zadanie rodzin synów Gerszonitów w Namiocie Zgromadzenia, a nadzór nad nimi będzie miał Itamar, syn kapłana Aarona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 29, 'A synów Merariego policzysz według ich rodzin i według domów ich ojców;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 30, 'Policzysz tych, którzy są w wieku od trzydziestu lat wzwyż aż do lat pięćdziesięciu, wszystkich zdolnych do tej pracy, aby mogli pełnić służbę przy Namiocie Zgromadzenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 31, 'A to będzie ich zadanie przy służbie w Namiocie Zgromadzenia: będą nosić deski przybytku, jego drążki, słupy i podstawki;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 32, 'Słupy otaczające dziedziniec, ich podstawki, kołki i sznury wraz ze wszystkimi ich przyborami oraz wszystko, co należy do ich służby. A z przedmiotów, które są im powierzone do noszenia, zrobicie wykaz według nazw.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 33, 'To będzie zadanie rodzin synów Merariego według całej ich służby przy Namiocie Zgromadzenia pod nadzorem Itamara, syna kapłana Aarona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 34, 'Mojżesz, Aaron i naczelnicy zgromadzenia policzyli synów Kehata według ich rodzin i według domów ich ojców;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 35, 'Tych będących w wieku od trzydziestu lat wzwyż aż do lat pięćdziesięciu, którzy byli zdolni do tej pracy, aby mogli pełnić służbę przy Namiocie Zgromadzenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 36, 'A policzonych według ich rodzin było dwa tysiące siedmiuset pięćdziesięciu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 37, 'Byli to ci policzeni z rodzin Kehatytów, wszyscy, którzy mieli pełnić służbę przy Namiocie Zgromadzenia, których policzyli Mojżesz i Aaron zgodnie z rozkazem Pana przekazanym przez Mojżesza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 38, 'A policzonych synów Gerszona według ich rodzin i według domów ich ojców;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 39, 'Tych, którzy byli w wieku od trzydziestu lat wzwyż aż do lat pięćdziesięciu, zdolnych do pracy, aby mogli pełnić służbę przy Namiocie Zgromadzenia;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 40, 'Policzonych według ich rodzin i domów ich ojców było dwa tysiące sześciuset trzydziestu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 41, 'Byli to ci policzeni z rodzin synów Gerszona, wszyscy, którzy mieli pełnić służbę w Namiocie Zgromadzenia, których policzyli Mojżesz i Aaron zgodnie z rozkazem Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 42, 'A policzonych z rodzin synów Merariego według ich rodzin i domów ich ojców;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 43, 'Tych, którzy byli w wieku trzydziestu lat wzwyż aż do lat pięćdziesięciu, zdolnych do pracy, aby mogli pełnić służbę przy Namiocie Zgromadzenia;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 44, 'A policzonych według ich rodzin było trzy tysiące dwustu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 45, 'A to są policzeni z rodzin synów Merariego, których policzyli Mojżesz i Aaron zgodnie z rozkazem Pana przekazanym przez Mojżesza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 46, 'Wszystkich Lewitów policzonych, których policzyli Mojżesz, Aaron i naczelnicy Izraela według ich rodzin i domów ich ojców;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 47, 'W wieku trzydziestu lat wzwyż aż do lat pięćdziesięciu; wszystkich policzonych, którzy przychodzili pełnić zadanie służby i noszenia ciężarów w Namiocie Zgromadzenia;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 48, 'Było osiem tysięcy pięciuset osiemdziesięciu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 49, 'Zgodnie z rozkazem Pana zostali policzeni przez Mojżesza, każdy z osobna według jego służby i według jego ciężaru. Policzono tych, których Pan rozkazał liczyć Mojżeszowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 1, 'I Pan powiedział do Mojżesza:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 2, 'Rozkaż synom Izraela, aby usunęli z obozu każdego trędowatego, każdego cierpiącego na wyciek i każdego, który zanieczyścił się przy umarłym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 3, 'Usuniecie zarówno mężczyznę, jak i kobietę; usuniecie ich poza obóz, aby nie zanieczyścili obozu tych, wśród których mieszkam.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 4, 'I synowie Izraela tak uczynili, i usunęli ich poza obóz. Jak Pan rozkazał Mojżeszowi, tak uczynili synowie Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 5, 'I powiedział Pan do Mojżesza:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 6, 'Powiedz synom Izraela: Jeśli mężczyzna lub kobieta popełnią jakikolwiek grzech ludzki, popełniając występek przeciwko Panu, a ta osoba byłaby winna;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 7, 'Wtedy wyzna swój grzech, którego się dopuściła, i zwróci w całości to, czym zawiniła, dodając do tego jedną piątą, i odda temu, wobec kogo zgrzeszyła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 8, 'A jeśli człowiek ten nie ma krewnego, któremu można by zwrócić odszkodowanie, niech będzie ono oddane Panu i niech przypadnie kapłanowi z wyjątkiem barana przebłagania, którym dokona za niego przebłagania.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 9, 'Każda też ofiara ze wszystkich poświęconych rzeczy synów Izraela, które przyniosą do kapłana, będzie należeć do niego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 10, 'Poświęcone rzeczy każdego człowieka będą należeć do niego; cokolwiek ktoś odda kapłanowi, będzie należeć do niego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 11, 'Potem Pan powiedział do Mojżesza:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 12, 'Przemów do synów Izraela i powiedz im: Jeśli czyjaś żona zbłądzi i dopuści się grzechu przeciwko niemu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 13, 'A inny mężczyzna obcuje z nią, lecz będzie to ukryte przed oczami jej męża i tajne, i stanie się ona nieczysta, a nie będzie żadnego świadka przeciwko niej ani nie zostanie ona przyłapana;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 14, 'Gdyby dopadł go duch zazdrości i podejrzewałby swoją żonę, która stała się nieczysta, albo gdyby dopadł go duch zazdrości i podejrzewałby ją, choć nie stała się nieczysta;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 15, 'Wówczas ten mąż przyprowadzi swoją żonę do kapłana i przyniesie ofiarę za nią – jedną dziesiątą efy mąki jęczmiennej. Nie wyleje na nią oliwy ani nie nałoży na nią kadzidła, gdyż jest to ofiara podejrzenia, ofiara pamięci, przypominająca grzech.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 16, 'A kapłan każe się jej zbliżyć i stawi ją przed Panem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 17, 'I kapłan wleje wodę poświęconą do glinianego naczynia, weźmie też trochę prochu, który jest na podłodze przybytku, i doda do wody.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 18, 'Potem kapłan postawi kobietę przed Panem, odkryje jej głowę i położy na jej rękach ofiarę pamięci, czyli ofiarę podejrzenia. Kapłan zaś będzie miał w ręku wodę gorzką, niosącą przekleństwa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 19, 'I kapłan zaprzysięgnie ją, i powie do kobiety: Jeśli nie położył się z tobą inny mężczyzna i jeśli nie dopuściłaś się grzechu nieczystości wobec swego męża, to bądź nietknięta przez tę wodę gorzką niosącą przekleństwa;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 20, 'Jeśli jednak byłaś niewierna swemu mężowi i stałaś się nieczysta, ponieważ oprócz twego męża obcował z tobą inny mężczyzna;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 21, 'Wtedy kapłan zaprzysięgnie tę kobietę przysięgą przekleństwa i powie do niej: Niech Pan uczyni cię przekleństwem i klątwą wśród twego ludu, gdy Pan sprawi, że twoje biodro zwiotczeje i twoje łono spuchnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 22, 'Niech ta woda niosąca przekleństwo przeniknie twoje wnętrzności, aby spuchło twoje łono i zwiotczało twoje biodro. I odpowie kobieta: Amen, amen.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 23, 'Potem kapłan napisze te przekleństwa w księdze i zmyje je tą gorzką wodą;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 24, 'I da wypić kobiecie gorzką wodę niosącą przekleństwo; i woda przekleństwa przeniknie ją, i zamieni się w gorycz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 25, 'Potem kapłan weźmie z rąk tej kobiety ofiarę podejrzenia i będzie ją kołysał przed Panem, i złoży ją na ołtarzu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 26, 'Kapłan weźmie też pełną garść ofiary jako pamiątkę i spali to na ołtarzu, potem da kobiecie wypić tę wodę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 27, 'A gdy da jej wypić tę wodę, stanie się tak, że jeśli stała się nieczysta i sprzeniewierzyła się swemu mężowi, to woda przekleństwa przeniknie ją i zamieni się w gorycz, i spuchnie jej łono, i zwiotczeje jej biodro, i kobieta stanie się przekleństwem wśród swego ludu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 28, 'Jeśli jednak kobieta ta nie stała się nieczysta, ale jest czysta, to będzie bez winy i będzie rodzić dzieci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 29, 'Takie jest prawo dotyczące podejrzenia, gdy żona będzie niewierna swemu mężowi i stanie się nieczysta;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 30, 'Albo gdy dopadnie męża duch zazdrości i będzie podejrzewał swoją żonę, i stawi ją przed Panem, a kapłan postąpi z nią według tego prawa;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 31, 'Wówczas mąż nie będzie winny grzechu, a kobieta obciąży się nieprawością.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 1, 'I Pan powiedział do Mojżesza:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 2, 'Przemów do synów Izraela i powiedz do nich: Gdy mężczyzna albo kobieta złoży szczególny ślub nazirejczyka, aby się poświęcić Panu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 3, 'Niech powstrzyma się od wina i mocnego napoju; nie będzie pił octu z wina i octu z mocnego napoju; nie będzie pił żadnego soku z winogron i nie będzie jeść winogron, ani świeżych, ani suszonych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 4, 'Przez wszystkie dni swego oddzielenia nie będzie jeść niczego, co pochodzi z winorośli, od ziarenka aż do łupiny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 5, 'Przez wszystkie dni ślubu swego oddzielenia brzytwa nie dotknie jego głowy. Dopóki nie wypełni się czas, na który poświęcił się Panu, będzie święty i zapuści włosy na swojej głowie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 6, 'Nie zbliży się do umarłego przez cały okres swego oddzielenia dla Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 7, 'Nie zanieczyści się przy ojcu, matce, bracie czy siostrze, którzy umarli, gdyż ma na głowie poświęcenie dla swego Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 8, 'Przez wszystkie dni swego oddzielenia będzie świętym dla Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 9, 'I gdyby ktoś nagle przy nim umarł i zanieczyścił jego poświęconą głowę, to ogoli swoją głowę w dniu swego oczyszczenia; ogoli ją siódmego dnia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 10, 'A ósmego dnia przyniesie dwie synogarlice lub dwa młode gołębie do kapłana, przed wejście do Namiotu Zgromadzenia;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 11, 'I kapłan złoży jednego na ofiarę za grzech, a drugiego na ofiarę całopalenia, i dokona za niego przebłagania za to, że zgrzeszył przy umarłym, i tego samego dnia poświęci jego głowę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 12, 'Potem poświęci Panu dni swego oddzielenia i przyniesie rocznego baranka za przewinienie. Minione dni jednak przepadną, gdyż jego oddzielenie zostało zanieczyszczone.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 13, 'A takie jest prawo nazirejczyka: Gdy wypełnią się dni jego oddzielenia, przyprowadzi się go przed wejście do Namiotu Zgromadzenia;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 14, 'I złoży Panu w ofierze jednego rocznego baranka bez skazy na ofiarę całopalenia, jedną roczną owcę bez skazy na ofiarę za grzech i jednego barana bez skazy na ofiarę pojednawczą;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 15, 'Do tego kosz przaśnych chlebów z mąki pszennej, placki zmieszane z oliwą oraz przaśne podpłomyki pomazane oliwą z ich ofiarą pokarmową i ofiarą z płynów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 16, 'I kapłan przyniesie to przed Pana i złoży jego ofiarę za grzech oraz jego całopalenie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 17, 'Barana zaś złoży Panu na ofiarę pojednawczą wraz z koszem przaśnych chlebów. Kapłan złoży też jego ofiarę pokarmową oraz jego ofiarę z płynów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 18, 'I nazirejczyk ogoli swoją poświęconą głowę u wejścia do Namiotu Zgromadzenia i weźmie włosy ze swojej poświęconej głowy, i położy je na ogień, który jest pod ofiarą pojednawczą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 19, 'Następnie kapłan weźmie ugotowaną łopatkę barana, jeden przaśny placek z kosza i jeden przaśny podpłomyk i złoży to w ręce nazirejczyka, gdy ten ogoli swoje poświęcone włosy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 20, 'I kapłan będzie to kołysał jako ofiarę kołysania przed Panem; jest to święta rzecz i należy do kapłana wraz z mostkiem kołysania i łopatką wzniesienia. Potem nazirejczyk będzie mógł pić wino.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 21, 'Takie jest prawo dotyczące nazirejczyka, który składa ślub, jak i jego ofiary dla Pana za jego oddzielenie, oprócz tego, na co go stać. Zgodnie ze swoim ślubem, który złożył, tak uczyni według prawa swego oddzielenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 22, 'Potem Pan powiedział do Mojżesza:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 23, 'Powiedz Aaronowi i jego synom: Tak będziecie błogosławić synów Izraela, mówiąc do nich:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 24, 'Niech ci błogosławi Pan i niech cię strzeże;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 25, 'Niech Pan rozjaśni nad tobą swoje oblicze i niech ci będzie łaskawy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 26, 'Niech Pan zwróci ku tobie swoje oblicze i niech da ci pokój.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 27, 'I będą wzywać mojego imienia nad synami Izraela, a ja im będę błogosławił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 1, 'W dniu, w którym Mojżesz zakończył wznoszenie przybytku, namaścił go i poświęcił wraz ze wszystkimi jego sprzętami, a także ołtarz ze wszystkimi jego naczyniami, namaścił je i poświęcił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 2, 'Naczelnicy Izraela, głowy domów swoich ojców, którzy byli naczelnikami z każdego pokolenia i przełożonymi nad tymi, którzy zostali spisani, złożyli ofiary.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 3, 'Przynieśli swoje ofiary przed Pana: sześć krytych wozów, dwanaście wołów, po jednym wozie na dwóch naczelników i po jednym wole na każdego, i przyprowadzili to przed przybytek.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 4, 'Wtedy Pan powiedział do Mojżesza:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 5, 'Weź to od nich na potrzebę służby w Namiocie Zgromadzenia i oddaj to Lewitom, każdemu według potrzeby jego służby.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 6, 'Mojżesz wziął więc te wozy i woły i oddał je Lewitom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 7, 'Dwa wozy i cztery woły dał synom Gerszona według potrzeby ich służby.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 8, 'Cztery zaś wozy i osiem wołów dał synom Merariego według potrzeby ich służby, pod nadzorem Itamara, syna kapłana Aarona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 9, 'Ale synom Kehata nie dał nic, bo ich służba w świątyni polegała na noszeniu na ramionach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 10, 'Naczelnicy ofiarowali swoje dary przed ołtarzem na jego poświęcenie, w tym dniu, w którym został namaszczony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 11, 'I Pan powiedział do Mojżesza: Niech złożą swoje ofiary, inny naczelnik każdego dnia, na poświęcenie ołtarza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 12, 'Pierwszego dnia swoją ofiarę złożył Nachszon, syn Amminadaba, z pokolenia Judy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 13, 'A jego ofiarę stanowiły: jedna srebrna misa wagi stu trzydziestu syklów, jedna srebrna czasza wagi siedemdziesięciu syklów według sykla świątynnego, obydwie pełne mąki pszennej zmieszanej z oliwą, na ofiarę pokarmową;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 14, 'Jedna czara z dziesięciu syklów złota pełna kadzidła;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 15, 'Jeden młody cielec, jeden baran i jedno roczne jagnię na ofiarę całopalną;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 16, 'Jeden kozioł z kóz na ofiarę za grzech;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 17, 'A na ofiarę pojednawczą – dwa woły, pięć baranów, pięć kozłów i pięć jednorocznych jagniąt. To była ofiara Nachszona, syna Amminadaba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 18, 'Drugiego dnia ofiarę złożył Netaneel, syn Suara, naczelnik z pokolenia Issachara.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 19, 'Złożył on w ofierze jedną srebrną misę wagi stu trzydziestu syklów, jedną srebrną czaszę wagi siedemdziesięciu syklów według sykla świątynnego, obydwie pełne mąki pszennej zmieszanej z oliwą, na ofiarę pokarmową;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 20, 'Jedną czarę z dziesięciu syklów złota pełną kadzidła;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 21, 'Jednego młodego cielca, jednego barana i jedno roczne jagnię na ofiarę całopalną;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 22, 'Jednego kozła z kóz na ofiarę za grzech;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 23, 'A na ofiarę pojednawczą – dwa woły, pięć baranów, pięć kozłów i pięć jednorocznych jagniąt. To była ofiara Netaneela, syna Suara.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 24, 'Trzeciego dnia ofiarę złożył naczelnik synów Zebulona Eliab, syn Chelona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 25, 'Jego ofiarę stanowiły: jedna srebrna misa wagi stu trzydziestu syklów, jedna srebrna czasza wagi siedemdziesięciu syklów według sykla świątynnego, obydwie pełne mąki pszennej zmieszanej z oliwą, na ofiarę pokarmową;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 26, 'Jedna czara z dziesięciu syklów złota pełna kadzidła;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 27, 'Jeden młody cielec, jeden baran i jedno roczne jagnię na ofiarę całopalną;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 28, 'Jeden kozioł z kóz na ofiarę za grzech;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 29, 'A na ofiarę pojednawczą – dwa woły, pięć baranów, pięć kozłów i pięć jednorocznych jagniąt. To była ofiara Eliaba, syna Chelona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 30, 'Czwartego dnia ofiarę złożył naczelnik synów Rubena Elizur, syn Szedeura.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 31, 'Jego ofiarę stanowiły: jedna srebrna misa wagi stu trzydziestu syklów, jedna srebrna czasza wagi siedemdziesięciu syklów według sykla świątynnego, obydwie pełne mąki pszennej zmieszanej z oliwą, na ofiarę pokarmową;');
