INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 36, 'Piątego dnia ofiarę złożył naczelnik synów Symeona Szelumiel, syn Suriszaddaja.');
