INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 42, 'Szóstego dnia ofiarę złożył naczelny synów Gada Eliasaf, syn Deuela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 43, 'Jego ofiarę stanowiły: jedna srebrna misa wagi stu trzydziestu syklów, jedna srebrna czasza wagi siedemdziesięciu syklów według sykla świątynnego, obydwie pełne mąki pszennej zmieszanej z oliwą, na ofiarę pokarmową;');
