INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 48, 'Siódmego dnia ofiarę złożył naczelnik synów Efraima Eliszama, syn Ammihuda.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 49, 'Jego ofiarę stanowiły: jedna srebrna misa wagi stu trzydziestu syklów, jedna srebrna czasza wagi siedemdziesięciu syklów według sykla świątynnego, obydwie pełne mąki pszennej zmieszanej z oliwą, na ofiarę pokarmową;');
