INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 54, 'Ósmego dnia ofiarę złożył naczelnik synów Manassesa Gamliel, syn Pedahsura.');
