INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 60, 'Dziewiątego dnia ofiarę złożył naczelnik synów Beniamina Abidan, syn Gideoniego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 61, 'Jego ofiarę stanowiły: jedna srebrna misa wagi stu trzydziestu syklów, jedna srebrna czasza wagi siedemdziesięciu syklów według sykla świątynnego, obydwie pełne mąki pszennej zmieszanej z oliwą, na ofiarę pokarmową;');
