INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 65, 'A na ofiarę pojednawczą – dwa woły, pięć baranów, pięć kozłów i pięć jednorocznych jagniąt. To była ofiara Abidana, syna Gideoniego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 66, 'Dziesiątego dnia ofiarę złożył naczelnik synów Dana Achiezer, syn Ammiszaddaja.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 67, 'Jego ofiarę stanowiły: jedna srebrna misa wagi stu trzydziestu syklów, jedna srebrna czasza wagi siedemdziesięciu syklów według sykla świątynnego, obydwie pełne mąki pszennej zmieszanej z oliwą, na ofiarę pokarmową;');
