INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 71, 'A na ofiarę pojednawczą – dwa woły, pięć baranów, pięć kozłów i pięć jednorocznych jagniąt. To była ofiara Achiezera, syna Ammiszadaja.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 72, 'Jedenastego dnia ofiarę złożył naczelnik synów Aszera Pagiel, syn Okrana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 73, 'Jego ofiarę stanowiły: jedna srebrna misa wagi stu trzydziestu syklów, jedna srebrna czasza wagi siedemdziesięciu syklów według sykla świątynnego, obydwie pełne mąki pszennej zmieszanej z oliwą, na ofiarę pokarmową;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 74, 'Jedna czara z dziesięciu syklów złota pełna kadzidła;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 75, 'Jeden młody cielec, jeden baran i jedno roczne jagnię na ofiarę całopalną;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 76, 'Jeden kozioł z kóz na ofiarę za grzech;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 77, 'A na ofiarę pojednawczą – dwa woły, pięć baranów, pięć kozłów i pięć jednorocznych jagniąt. To była ofiara Pagiela, syna Okrana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 78, 'Dwunastego dnia ofiarę złożył naczelnik synów Neftalego Achira, syn Enana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 79, 'Jego ofiarę stanowiły: jedna srebrna misa wagi stu trzydziestu syklów, jedna srebrna czasza wagi siedemdziesięciu syklów według sykla świątynnego, obydwie pełne mąki pszennej zmieszanej z oliwą, na ofiarę pokarmową;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 80, 'Jedna czara z dziesięciu syklów złota pełna kadzidła;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 81, 'Jeden młody cielec, jeden baran i jedno roczne jagnię na ofiarę całopalną;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 82, 'Jeden kozioł z kóz na ofiarę za grzech;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 83, 'A na ofiarę pojednawczą – dwa woły, pięć baranów, pięć kozłów i pięć jednorocznych jagniąt. To była ofiara Achiry, syna Enana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 84, 'To było poświęcenie ołtarza, w tym dniu, w którym został namaszczony przez naczelników Izraela: dwanaście srebrnych mis, dwanaście srebrnych czasz, dwanaście złotych czar;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 85, 'Każda srebrna misa ważyła sto trzydzieści syklów, każda czasza – siedemdziesiąt syklów. Całego srebra w tych naczyniach było dwa tysiące czterysta syklów według sykla świątynnego;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 86, 'Złotych czar było dwanaście, pełnych kadzidła; każda ważyła dziesięć syklów według sykla świątynnego. Całego złota w tych czarach było sto dwadzieścia syklów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 87, 'Wszystkich zwierząt na ofiarę całopalną było: dwanaście cielców, dwanaście baranów, dwanaście jednorocznych jagniąt wraz z ich ofiarą pokarmową i dwanaście kozłów z kóz na ofiarę za grzech.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 88, 'A wszystkich zwierząt na ofiarę pojednawczą było: dwadzieścia cztery woły, sześćdziesiąt baranów, sześćdziesiąt kozłów i sześćdziesiąt jednorocznych jagniąt. To było poświęcenie ołtarza po jego namaszczeniu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 89, 'A gdy Mojżesz wchodził do Namiotu Zgromadzenia, aby rozmawiać z Bogiem, wtedy słyszał głos mówiącego do niego z przebłagalni, która była nad arką świadectwa, spomiędzy dwóch cherubinów. I przemawiał do niego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 1, 'I Pan przemówił do Mojżesza tymi słowy:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 2, 'Powiedz Aaronowi: Gdy zapalisz lampy, siedem lamp ma rzucać światło na przednią stronę świecznika.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 3, 'I Aaron tak uczynił. Z przedniej strony świecznika zapalił lampy, tak jak Pan rozkazał Mojżeszowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 4, 'Świecznik był wykuty ze złota, od trzonu aż po kwiaty był kuty. Zgodnie ze wzorem, który Pan pokazał Mojżeszowi, tak zrobił świecznik.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 5, 'Potem Pan powiedział do Mojżesza:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 6, 'Weź Lewitów spośród synów Izraela i oczyść ich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 7, 'I tak postąpisz z nimi, aby ich oczyścić: Pokrop ich wodą oczyszczenia, a oni niech ogolą całe swoje ciało i wypiorą swoje szaty, wtedy będą czyści.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 8, 'Następnie niech wezmą młodego cielca wraz z jego ofiarą pokarmową z mąki pszennej zmieszanej z oliwą, drugiego zaś młodego cielca weźmiesz na ofiarę za grzech.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 9, 'I przyprowadzisz Lewitów przed Namiot Zgromadzenia, i zbierzesz całe zgromadzenie synów Izraela;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 10, 'I przyprowadzisz Lewitów przed Pana, a synowie Izraela położą na nich swoje ręce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 11, 'Wtedy Aaron przedstawi Lewitów przed Panem jako ofiarę od synów Izraela, aby pełnili służbę dla Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 12, 'Lewici zaś położą swoje ręce na głowy cielców. Ty złożysz jednego na ofiarę za grzech, a drugiego na ofiarę całopalną dla Pana, aby dokonać przebłagania za Lewitów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 13, 'Następnie postawisz Lewitów przed Aaronem i przed jego synami i przedstawisz ich jako ofiarę dla Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 14, 'W ten sposób oddzielisz Lewitów spośród synów Izraela i Lewici będą należeć do mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 15, 'Potem Lewici wejdą, aby służyć w Namiocie Zgromadzenia, gdy ich oczyścisz i przedstawisz jako ofiarę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 16, 'Oni bowiem są mi oddani spośród synów Izraela; w miejsce każdego, kto otwiera łono, w miejsce wszystkich pierworodnych synów Izraela wziąłem ich sobie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 17, 'Gdyż do mnie należy wszystko, co pierworodne wśród synów Izraela, zarówno z ludzi, jak i ze zwierząt. Poświęciłem ich sobie w dniu, w którym zabiłem wszystko, co pierworodne w ziemi Egiptu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 18, 'Wziąłem Lewitów w zamian za wszystkich pierworodnych wśród synów Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 19, 'I dałem Lewitów jako dar Aaronowi i jego synom spośród synów Izraela, aby pełnili służbę synów Izraela w Namiocie Zgromadzenia i dokonywali przebłagania za nich, aby nie spadła na synów Izraela żadna kara, gdy będą zbliżać się do świątyni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 20, 'Wtedy Mojżesz i Aaron oraz całe zgromadzenie synów Izraela postąpili z Lewitami tak, jak Pan rozkazał Mojżeszowi o Lewitach; tak postąpili z nimi synowie Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 21, 'Lewici oczyścili się i wyprali swoje szaty, a Aaron przedstawił ich jako ofiarę przed Panem i dokonał przebłagania za nich, aby ich oczyścić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 22, 'Potem Lewici weszli, aby pełnić swoją służbę w Namiocie Zgromadzenia przed Aaronem i przed jego synami. Jak Pan rozkazał Mojżeszowi odnośnie do Lewitów, tak z nimi postąpili.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 23, 'I Pan powiedział do Mojżesza:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 24, 'Oto co dotyczy Lewitów: Od dwudziestego piątego roku życia wzwyż przystąpią, by pełnić służbę w Namiocie Zgromadzenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 25, 'A od pięćdziesiątego roku życia przestaną pełnić służbę i więcej nie będą służyć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 26, 'Będą jednak usługiwać swym braciom w Namiocie Zgromadzenia w pełnieniu straży, lecz samej służby nie będą pełnić. Tak postąpisz z Lewitami w sprawie ich służby.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 1, 'I przemówił Pan do Mojżesza na pustyni Synaj, w pierwszym miesiącu drugiego roku po ich wyjściu z ziemi Egiptu, tymi słowy:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 2, 'Niech synowie Izraela obchodzą Paschę w wyznaczonym czasie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 3, 'Będziecie ją obchodzić w wyznaczonym czasie, czternastego dnia tego miesiąca pod wieczór; macie ją obchodzić według wszystkich jej obrzędów i wszystkich jej ceremonii.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 4, 'Mojżesz nakazał więc synom Izraela, aby obchodzili Paschę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 5, 'I obchodzili Paschę w pierwszym miesiącu, czternastego dnia, pod wieczór, na pustyni Synaj. Zgodnie ze wszystkim, co Pan nakazał Mojżeszowi, tak synowie Izraela uczynili.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 6, 'Byli jednak pewni ludzie, którzy zanieczyścili się przy zwłokach ludzkich, i nie mogli obchodzić Paschy tego dnia. Przyszli więc w tym dniu do Mojżesza i Aarona;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 7, 'I powiedzieli do niego: Zanieczyściliśmy się przy zwłokach ludzkich. Czemu nie będzie nam wolno złożyć Panu ofiar w wyznaczonym czasie wspólnie z synami Izraela?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 8, 'Mojżesz odpowiedział im: Stójcie, a ja posłucham, co Pan rozkaże o was.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 9, 'Wtedy Pan powiedział do Mojżesza:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 10, 'Powiedz synom Izraela tak: Jeśli kto z was lub z waszych potomków zanieczyści się przy zmarłym albo też będzie w dalekiej podróży, mimo to będzie obchodził Paschę dla Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 11, 'Będą ją obchodzić w drugim miesiącu, czternastego dnia, pod wieczór, i będą ją jeść z przaśnymi chlebami i z gorzkimi ziołami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 12, 'Nie pozostawią z niej nic do rana ani nie połamią jej kości. Zgodnie ze wszystkimi przepisami Paschy będą ją obchodzić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 13, 'Lecz człowiek, który jest czysty, a nie znajduje się w drodze, i nie będzie obchodził Paschy, to ta dusza będzie wykluczona ze swego ludu, bo ofiary Pana nie złożyła w wyznaczonym czasie. Ten człowiek obciąża się grzechem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 14, 'A jeśli przybysz, który mieszka pośród was, będzie obchodził Paschę dla Pana, to ma ją obchodzić według ustawy i zwyczajów Paschy. Będzie jedna ustawa dla was, zarówno dla przybysza, jak i dla rodowitego mieszkańca ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 15, 'W dniu, w którym wystawiono przybytek, obłok okrył przybytek, czyli Namiot Świadectwa, a wieczorem był nad przybytkiem i przypominał z wyglądu ogień, aż do rana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 16, 'Tak było stale: obłok okrywał go w dzień, a w nocy jakby ogień.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 17, 'A gdy obłok unosił się znad namiotu, wtedy synowie Izraela wyruszali, a gdziekolwiek obłok zatrzymał się, tam synowie Izraela rozbijali obóz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 18, 'Na rozkaz Pana synowie Izraela wyruszali i na rozkaz Pana rozbijali obóz. Przez wszystkie dni, w których obłok pozostawał nad przybytkiem, stali obozem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 19, 'A kiedy obłok pozostawał nad przybytkiem przez wiele dni, wtedy synowie Izraela przestrzegali rozkazu Pana i nie wyruszali.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 20, 'Lecz gdy obłok pozostawał nad przybytkiem przez kilka dni, na rozkaz Pana stawali obozem i na rozkaz Pana wyruszali.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 21, 'A gdy obłok pozostawał od wieczora do rana i unosił się rano, wówczas wyruszali. Czy obłok unosił się za dnia, czy w nocy, oni wyruszali.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 22, 'A jeśli obłok trwał i pozostawał nad przybytkiem przez dwa dni albo przez miesiąc bądź też przez rok, synowie Izraela stali obozem i nie wyruszali, lecz gdy się unosił, wyruszali.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 23, 'Na rozkaz Pana stawali obozem i na rozkaz Pana wyruszali. Przestrzegali nakazu Pana, tak jak Pan rozkazał przez Mojżesza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 1, 'Potem Pan powiedział do Mojżesza:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 2, 'Zrób sobie dwie srebrne trąby. Wykonasz je robotą kutą, a będą ci służyć do zwoływania ludu i do nawoływania w drogę obozów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 3, 'A gdy w nie zadmą, wtedy cały lud zgromadzi się do ciebie, u wejścia do Namiotu Zgromadzenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 4, 'A jeśli zadmą tylko w jedną trąbę, zejdą się do ciebie wodzowie, naczelnicy tysięcy Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 5, 'Gdy zatrąbicie, wydając urwany dźwięk, wtedy wyruszą obozy rozłożone po stronie wschodniej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 6, 'A gdy drugi raz zatrąbicie, wydając urwany głos, wyruszą obozy rozłożone po stronie południowej. Będą trąbić, wydając urwany dźwięk, kiedy mają wyruszyć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 7, 'Ale gdy będziecie zwoływać lud, zatrąbicie bez wydawania urywanego dźwięku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 8, 'A synowie Aarona, kapłani, zadmą w trąby. Będzie to wieczysta ustawa dla was przez wszystkie wasze pokolenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 9, 'A gdy w waszej ziemi wyruszycie na wojnę przeciw wrogowi, który was gnębi, zadmiecie w trąby urwanym dźwiękiem; a przypomnicie się Panu, waszemu Bogu, i zostaniecie wybawieni od waszych wrogów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 10, 'Także w dniu waszej radości, w wasze uroczyste święta oraz podczas waszych nowiów zadmiecie w trąby przy waszych ofiarach całopalnych i przy waszych ofiarach pojednawczych; będą one dla was pamiątką przed waszym Bogiem. Ja jestem Pan, wasz Bóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 11, 'I w drugim roku, drugiego miesiąca, dwudziestego dnia tego miesiąca uniósł się obłok znad Przybytku Świadectwa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 12, 'I synowie Izraela wyruszyli z pustyni Synaj, a obłok zatrzymał się na pustyni Paran.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 13, 'I po raz pierwszy wyruszyli tak, jak Pan rozkazał przez Mojżesza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 14, 'Pierwsza ruszyła chorągiew obozu synów Judy według swoich zastępów, a na czele jego wojska był Nachszon, syn Amminadaba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 15, 'Na czele wojska pokolenia synów Issachara był Netaneel, syn Suara.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 16, 'Na czele wojska pokolenia synów Zebulona był Eliab, syn Chelona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 17, 'Potem złożono przybytek i wyruszyli synowie Gerszona i synowie Merariego, niosąc przybytek.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 18, 'Następnie ruszyła chorągiew obozu Rubena według swoich zastępów, a na czele jego wojska był Elizur, syn Szedeura.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 19, 'Na czele wojska pokolenia synów Symeona był Szelumiel, syn Suriszaddaja.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 20, 'Na czele wojska pokolenia synów Gada był Eliasaf, syn Duela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 21, 'Następnie wyruszyli Kehatyci, niosąc świątynię. Zanim przyszli, inni ustawiali przybytek.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 22, 'Potem ruszyła chorągiew obozu synów Efraima według swoich zastępów, a na czele jego wojska był Eliszama, syn Ammihuda.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 23, 'Na czele wojsk pokolenia synów Manassesa był Gamliel, syn Pedahsura.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 24, 'Na czele wojska pokolenia synów Beniamina był Abidan, syn Gideoniego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 25, 'Następnie ruszyła chorągiew obozu synów Dana, tworząc tylną straż wszystkich obozów, według swoich zastępów, a na czele jego wojska był Achiezer, syn Ammiszaddaja.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 26, 'Na czele wojska pokolenia synów Aszera był Pagiel, syn Okrana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 27, 'Na czele wojska pokolenia synów Neftalego był Achira, syn Enana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 28, 'Taki był porządek marszu synów Izraela według ich zastępów i tak ruszali.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 29, 'Potem Mojżesz powiedział do Chobaba, syna Reuela Midianity, swego teścia: Wyruszamy do miejsca, o którym Pan powiedział: Dam je wam. Chodź z nami, a wyświadczymy ci dobro, ponieważ Pan obiecał wiele dobrego Izraelowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 30, 'Ten mu odpowiedział: Nie pójdę, lecz wrócę do mojej ziemi i do mojej rodziny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 31, 'Mojżesz powiedział: Proszę, nie opuszczaj nas, bo ty wiesz, gdzie na pustyni możemy rozbić obóz, i możesz być naszym przewodnikiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 32, 'Jeśli pójdziesz z nami, wyświadczymy ci to dobro, które Pan nam uczyni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 33, 'I wyruszyli od góry Pana w drogę na trzy dni, a arka przymierza Pana szła przed nimi podczas tych trzech dni drogi, aby upatrzyć dla nich miejsce odpoczynku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 34, 'A obłok Pana był nad nimi za dnia, gdy wyruszali z obozu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 35, 'A gdy arka miała ruszyć, wtedy Mojżesz mówił: Powstań, Panie, a niech rozproszą się twoi wrogowie i niech uciekają przed tobą ci, którzy cię nienawidzą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 36, 'Gdy zaś się zatrzymywała, wtedy mówił: Wróć, Panie, do niezliczonych tysięcy Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 1, 'A lud zaczął się skarżyć, co się Panu nie podobało. Gdy więc Pan to usłyszał, bardzo się rozgniewał. I ogień Pana zapalił się przeciwko niemu i pochłonął krańce obozu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 2, 'Wtedy wołał lud na Mojżesza, a Mojżesz pomodlił się do Pana i ogień zgasł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 3, 'I nazwał to miejsce Tabera, bo ogień Pana zapalił się przeciwko nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 4, 'A pospólstwo, które było wśród nich, ogarnęło pragnienie. Synowie Izraela też płakali na nowo i mówili: Któż nas nakarmi mięsem?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 5, 'Wspominamy ryby, które jedliśmy w Egipcie za darmo, ogórki, melony, pory, cebulę i czosnek.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 6, 'A teraz nasza dusza wyschła, bo nic innego przed oczami nie mamy oprócz tej manny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 7, 'A manna była jak nasienie kolendry, a jej kolor jak kolor bdellium.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 8, 'Ludzie wychodzili i zbierali ją, i mełli w żarnach albo tłukli w moździerzach, potem gotowali w kotłach i robili z niej placki. Jej smak był jak smak świeżej oliwy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 9, 'Gdy bowiem nocą opadała rosa na obóz, spadała też na niego manna.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 10, 'Wtedy Mojżesz usłyszał, że lud płacze w swoich rodzinach, każdy przy wejściu do swojego namiotu. Wówczas mocno zapłonął gniew Pana, a i Mojżeszowi to się nie podobało.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 11, 'I Mojżesz powiedział do Pana: Dlaczego tak źle się obchodzisz ze swoim sługą? Dlaczego nie znalazłem łaski w twoich oczach, że włożyłeś na mnie ciężar całego tego ludu?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 12, 'Czy ja począłem cały ten lud? Czy ja go zrodziłem, że mówisz do mnie: Nieś go na swoim łonie jak opiekun nosi niemowlę do ziemi, którą przysiągłeś ich ojcom?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 13, 'Skąd wezmę mięso, aby dać całemu temu ludowi? Płaczą bowiem przede mną i mówią: Daj nam mięsa, abyśmy mogli jeść.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 14, 'Nie mogę sam znosić całego tego ludu, gdyż jest dla mnie zbyt ciężki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 15, 'A jeśli tak ze mną postępujesz, to raczej zabij mnie, proszę, jeśli znalazłem łaskę w twoich oczach, abym nie patrzył na swoją niedolę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 16, 'I Pan powiedział do Mojżesza: Zbierz mi siedemdziesięciu mężczyzn spośród starszych Izraela, o których wiesz, że są starszymi ludu oraz jego przełożonymi, przyprowadź ich do Namiotu Zgromadzenia i niech tam staną wraz z tobą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 17, 'A ja zstąpię i będę tam z tobą rozmawiał. Potem wezmę z ducha, który jest na tobie, i złożę na nich. Będą nosić razem z tobą brzemię ludu, abyś nie musiał go nosić ty sam.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 18, 'A do ludu powiesz: Poświęćcie się na jutro, a będziecie jeść mięso. Płakaliście bowiem, a to dotarło do uszu Pana: Któż nas nakarmi mięsem? Bo było nam lepiej w Egipcie! Pan da wam więc mięso i będziecie jeść.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 19, 'Będziecie je jeść nie przez jeden dzień ani nie przez dwa dni, ani przez pięć, ani przez dziesięć dni, ani przez dwadzieścia dni;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 20, 'Lecz przez cały miesiąc, aż wam wyjdzie przez nozdrza i zupełnie wam obrzydnie. Wzgardziliście bowiem Panem, który jest wśród was, i płakaliście przed nim, mówiąc: Po co wyszliśmy z Egiptu?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 21, 'Mojżesz powiedział: Sześćset tysięcy pieszych liczy ten lud, pośród którego mieszkam, a ty powiedziałeś: Dam im mięsa i będą jeść przez cały miesiąc.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 22, 'Czy można zabić tyle owiec i wołów, aby im wystarczyło? Czy można dla nich zebrać wszystkie ryby morskie, aby mieli dosyć?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 23, 'Pan powiedział do Mojżesza: Czy ręka Pana jest zbyt krótka? Teraz zobaczysz, czy moje słowo się wypełni, czy też nie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 24, 'Mojżesz wyszedł więc i opowiedział ludowi słowa Pana. Następnie zebrał siedemdziesięciu mężczyzn spośród starszych ludu i postawił ich wokół namiotu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 25, 'Wtedy Pan zstąpił w obłoku i przemówił do niego. Potem wziął z ducha, który był na nim, i dał go siedemdziesięciu starszym. A gdy spoczął na nich duch, prorokowali i nie przestali.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 26, 'Lecz dwaj mężczyźni pozostali w obozie: jeden miał na imię Eldad, a drugi – Medad. Na nich też spoczął duch, bo oni byli wśród spisanych, choć nie przybyli do namiotu. Prorokowali jednak w obozie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 27, 'Wtedy młodzieniec przybiegł i powiedział do Mojżesza: Eldad i Medad prorokują w obozie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 28, 'A Jozue, syn Nuna, sługa Mojżesza i jeden z jego młodzieńców, powiedział: Mojżeszu, panie mój, zabroń im.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 29, 'Mojżesz odpowiedział: Czy jesteś zazdrosny o mnie? Oby cały lud Pana zamienił się w proroków, aby Pan złożył na nim swego ducha!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 30, 'Wtedy Mojżesz wrócił do obozu wraz ze starszymi Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 31, 'I zerwał się wiatr od Pana, który porwał od morza przepiórki i zrzucił je na obóz, na jeden dzień drogi z jednej strony i na jeden dzień drogi z drugiej strony, wokół obozu, wysoko na dwa łokcie nad ziemią.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 32, 'Lud stał przez cały dzień, przez całą noc i przez cały następny dzień i zbierał przepiórki. Ten, kto zebrał najmniej, miał dziesięć chomerów. I rozłożyli je sobie wokół obozu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 33, 'Lecz gdy mięso było między ich zębami, jeszcze nieprzeżute, gniew Pana zapłonął przeciw ludowi i uderzył go wielką plagą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 34, 'I nazwano to miejsce Kibrot-Hattaawa, bo tam pochowano lud, który zapragnął mięsa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 35, 'A z Kibrot-Hattaawy lud wyruszył do Chaserot; i mieszkał w Chaserot.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 1, 'Wtedy Miriam i Aaron mówili źle przeciwko Mojżeszowi z powodu etiopskiej kobiety, którą pojął. Pojął bowiem za żonę Etiopkę;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 2, 'I mówili: Czy Pan przemawiał tylko przez Mojżesza? Czy nie przemawiał też przez nas? A Pan to usłyszał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 3, 'A Mojżesz był człowiekiem bardzo pokornym, najbardziej ze wszystkich ludzi, którzy żyli na ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 4, 'I nagle Pan powiedział do Mojżesza, Aarona i Miriam: Wyjdźcie we troje do Namiotu Zgromadzenia. I wyszli we troje.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 5, 'Wtedy Pan zstąpił w słupie obłoku, stanął u wejścia do namiotu i wezwał Aarona i Miriam; a oni przyszli oboje.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 6, 'I powiedział do nich: Słuchajcie teraz moich słów: Jeśli będzie wśród was prorok, ja, Pan, objawię mu się w widzeniu, będę mówił do niego we śnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 7, 'Lecz nie tak jest z moim sługą Mojżeszem, który jest wierny w całym moim domu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 8, 'Z ust do ust mówię do niego, jawnie, a nie w zagadkach; on ogląda postać Pana. Dlaczego nie baliście się mówić źle przeciwko memu słudze Mojżeszowi?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 9, 'I zapłonął gniew Pana przeciwko nim, i odszedł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 10, 'Obłok także odstąpił znad namiotu i oto Miriam stała się trędowata, biała jak śnieg. Gdy Aaron spojrzał na Miriam, oto była trędowata.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 11, 'Wtedy Aaron powiedział do Mojżesza: Ach, mój panie! Proszę, nie poczytaj nam tego grzechu, że głupio postąpiliśmy i zgrzeszyliśmy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 12, 'Niech ona nie będzie jak martwy płód, którego ciało jest już na wpół rozłożone, gdy wychodzi z łona swojej matki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 13, 'Wtedy Mojżesz zawołał do Pana: Boże, proszę, uzdrów ją teraz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 14, 'I Pan odpowiedział Mojżeszowi: Gdyby jej ojciec plunął jej w twarz, czyż nie musiałaby się wstydzić przez siedem dni? Niech przez siedem dni będzie wyłączona z obozu, a potem zostanie przyjęta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 15, 'I Miriam została wyłączona z obozu na siedem dni. Lud jednak nie wyruszył, póki Miriam nie została przyjęta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 16, 'Potem lud wyruszył z Chaserot i rozbił obóz na pustyni Paran.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 1, 'I Pan powiedział do Mojżesza:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 2, 'Wyślij mężczyzn, aby wyszpiegowali ziemię Kanaan, którą daję synom Izraela. Z każdego pokolenia ich ojców wyślecie po jednym mężczyźnie; tych, którzy są wśród nich wodzami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 3, 'Wysłał ich więc Mojżesz z pustyni Paran, zgodnie z rozkazem Pana. Wszyscy ci mężczyźni byli naczelnikami wśród synów Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 4, 'A oto są ich imiona: z pokolenia Rubena – Szamua, syn Zakkura.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 5, 'Z pokolenia Symeona – Szafat, syn Choriego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 6, 'Z pokolenia Judy – Kaleb, syn Jefunnego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 7, 'Z pokolenia Issachara – Jigal, syn Józefa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 8, 'Z pokolenia Efraima – Ozeasz, syn Nuna.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 9, 'Z pokolenia Beniamina – Palti, syn Rafua.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 10, 'Z pokolenia Zebulona – Gaddiel, syn Sodiego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 11, 'Z pokolenia Józefa, to jest z potomstwa Manassesa – Gaddi, syn Susiego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 12, 'Z pokolenia Dana – Ammiel, syn Gemalliego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 13, 'Z pokolenia Aszera – Setur, syn Mikaela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 14, 'Z pokolenia Neftalego – Nachbi, syn Wafsiego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 15, 'Z pokolenia Gada – Geuel, syn Makiego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 16, 'To są imiona mężczyzn, których Mojżesz wysłał, aby wyszpiegowali ziemię. A Ozeaszowi, synowi Nuna, nadał imię Jozue.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 17, 'A gdy Mojżesz wysłał ich, aby wyszpiegowali ziemię Kanaan, powiedział do nich: Idźcie w tę stronę, na południe, i wejdźcie na górę;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 18, 'I obejrzyjcie ziemię, jaka ona jest, oraz lud, który w niej mieszka, czy jest silny, czy słaby, czy jest ich mało, czy wielu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 19, 'I jaka jest ziemia, w której mieszkają: czy jest dobra, czy zła. I jakie są miasta, w których mieszkają: czy to są obozowiska, czy warownie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 20, 'I jaka jest ziemia: czy urodzajna, czy jałowa; czy są na niej drzewa, czy nie. Bądźcie odważni i przynieście nam z owocu tamtej ziemi. A był to czas dojrzewania winogron.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 21, 'Poszli więc i wyszpiegowali ziemię, od pustyni Syn aż do Rechob, którędy wchodzi się do Chamat.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 22, 'A kierując się na południe, dotarli do Hebronu, gdzie byli Achiman, Szeszaj i Talmaj, synowie Anaka; a Hebron zbudowano siedem lat przed Soan w Egipcie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 23, 'Potem przybyli do potoku Eszkol i ucięli tam gałąź z jedną kiścią winogron, i nieśli ją we dwóch na drążku; wzięli też jabłka granatu i figi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 24, 'I nazwano to miejsce potokiem Eszkol od winogrona, które synowie Izraela tam ucięli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 25, 'I po czterdziestu dniach wrócili z wyszpiegowania ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 26, 'A kiedy wrócili, przyszli do Mojżesza, Aarona i całego zgromadzenia synów Izraela na pustynię Paran, do Kadesz; zdali sprawę im oraz całemu zgromadzeniu, pokazali im też owoce tej ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 27, 'I opowiedzieli mu: Przyszliśmy do ziemi, do której nas wysłałeś. Ona rzeczywiście opływa mlekiem i miodem, a to są jej owoce;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 28, 'Tylko że lud, który mieszka w tej ziemi, jest silny, a miasta są obwarowane i bardzo wielkie; widzieliśmy tam również synów Anaka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 29, 'Amalekici mieszkają w południowej części ziemi, a Chetyci, Jebusyci, Amoryci mieszkają w górach; Kananejczycy zaś mieszkają nad morzem i nad brzegiem Jordanu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 30, 'Wtedy Kaleb uspokajał lud szemrzący przeciw Mojżeszowi i mówił: Pójdźmy i posiądźmy ziemię, bo zdołamy ją podbić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 31, 'Lecz mężczyźni, którzy z nim poszli, powiedzieli: Nie możemy wyruszyć przeciw tamtemu ludowi, bo jest silniejszy od nas.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 32, 'I rozpuścili wśród synów Izraela złą wieść o ziemi, którą wyszpiegowali, mówiąc: Ziemia, przez którą przeszliśmy, aby ją zbadać, jest ziemią, która pożera swoich mieszkańców, a wszyscy ludzie, których w niej widzieliśmy, to ludzie wysokiego wzrostu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 33, 'Tam też widzieliśmy olbrzymów, synów Anaka, pochodzących od olbrzymów. Przy nich wydaliśmy się sobie jak szarańcza, takimi też byliśmy w ich oczach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 1, 'Wtedy całe zgromadzenie podniosło donośny lament i lud płakał tej nocy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 2, 'I wszyscy synowie Izraela szemrali przeciwko Mojżeszowi i Aaronowi; i całe zgromadzenie mówiło do nich: Obyśmy pomarli w ziemi Egiptu albo na tej pustyni!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 3, 'Po co Pan prowadzi nas do tej ziemi? Abyśmy padli od miecza? Aby nasze żony i dzieci stały się łupem? Czy nie lepiej nam wrócić do Egiptu?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 4, 'I mówili między sobą: Ustanówmy sobie wodza i wróćmy do Egiptu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 5, 'Wtedy Mojżesz i Aaron upadli na twarz przed całym zgromadzeniem synów Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 6, 'A Jozue, syn Nuna, i Kaleb, syn Jefunnego, którzy byli wśród tych, co wyszpiegowali ziemię, rozdarli swoje szaty;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 7, 'I powiedzieli do całego zgromadzenia synów Izraela: Ziemia, przez którą przeszliśmy, aby ją wyszpiegować, jest ziemią bardzo dobrą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 8, 'Jeśli Pan upodoba nas sobie, to wprowadzi nas do tej ziemi i da ją nam – tę ziemię, która opływa mlekiem i miodem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 9, 'Tylko nie buntujcie się przeciwko Panu ani nie bójcie się ludu tej ziemi, bo będą naszym chlebem; ich obrona odwróciła się od nich, a Pan jest z nami. Nie bójcie się ich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 10, 'I całe zgromadzenie mówiło, aby ich ukamienować; ale chwała Pana ukazała się wszystkim synom Izraela nad Namiotem Zgromadzenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 11, 'I Pan powiedział do Mojżesza: Jak długo ten lud będzie mnie drażnić? Jak długo nie będzie mi wierzyć pomimo tych wszystkich znaków, które wśród nich uczyniłem?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 12, 'Uderzę ich zarazą i wydziedziczę, a ciebie uczynię narodem większym i silniejszym niż oni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 13, 'Lecz Mojżesz powiedział do Pana: Usłyszą o tym Egipcjanie, spośród których wyprowadziłeś ten lud swoją mocą;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 14, 'I opowiedzą o tym obywatelom tej ziemi. Gdyż słyszeli, że ty, Panie, jesteś pośród tego ludu, że ty, Panie, bywasz widziany twarzą w twarz, że twój obłok stoi nad nimi i że kroczysz przed nimi w słupie obłoku za dnia, a w słupie ognia w nocy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 15, 'Gdybyś więc zabił ten lud jak jednego człowieka, to narody, które słyszały o twojej sławie, mówiłyby tak:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 16, 'Ponieważ Pan nie mógł wprowadzić tego ludu do ziemi, którą im przysiągł, to zabił ich na pustyni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 17, 'Teraz więc proszę, niech się okaże wielka moc mojego Pana, jak powiedziałeś:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 18, 'Pan nierychły do gniewu i pełen wielkiego miłosierdzia, przebaczający nieprawość i przestępstwo, który nie uniewinnia winnego, lecz nawiedza nieprawość ojców na synach do trzeciego i czwartego pokolenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 19, 'Przebacz, proszę, nieprawość twego ludu według wielkości twego miłosierdzia, tak jak przebaczałeś temu ludowi od Egiptu aż dotąd.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 20, 'Wtedy Pan powiedział: Przebaczyłem według twego słowa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 21, 'Ale jak żyję i jak cała ziemia jest napełniona chwałą Pana;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 22, 'Tak wszyscy, którzy widzieli moją chwałę i moje znaki, które czyniłem w Egipcie i na pustyni, a wystawiali mnie na próbę już dziesięciokrotnie i nie słuchali mego głosu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 23, 'Nie zobaczą tej ziemi, którą przysiągłem ich ojcom, a żaden z tych, którzy mnie rozdrażnili, nie zobaczy jej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 24, 'Ale mojego sługę Kaleba za to, że był w nim inny duch i trwał całkowicie przy mnie, wprowadzę do ziemi, do której wszedł, a jego potomstwo ją odziedziczy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 25, 'A ponieważ Amalekici i Kananejczycy mieszkają w dolinie, to jutro zawróćcie i wyruszcie na pustynię, w kierunku Morza Czerwonego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 26, 'Ponadto Pan powiedział do Mojżesza i Aarona:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 27, 'Jak długo mam znosić ten zły lud, który szemrze przeciwko mnie? Słyszałem szemrania synów Izraela, jakie mówią przeciwko mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 28, 'Powiedz im: Jak żyję, mówi Pan, uczynię wam, jak mówiliście do moich uszu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 29, 'Na tej pustyni legną wasze trupy i wszyscy spisani wśród was, w pełnej liczbie, od dwudziestu lat wzwyż, którzy szemraliście przeciwko mnie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 30, 'Nie wejdziecie do tej ziemi, którą przysiągłem dać wam na mieszkanie, z wyjątkiem Kaleba, syna Jefunnego, i Jozuego, syna Nuna;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 31, 'A wasze dzieci, o których mówiliście, że staną się łupem, te wprowadzę i one zobaczą ziemię, którą wy wzgardziliście.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 32, 'Wasze trupy zaś legną na tej pustyni;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 33, 'A wasi synowie będą się tułali po tej pustyni przez czterdzieści lat i poniosą karę za wasze cudzołóstwa, aż wasze trupy zniszczeją na pustyni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 34, 'Według liczby dni, w ciągu których wyszpiegowaliście ziemię, to znaczy czterdzieści dni, dzień za rok, będziecie ponosić karę za wasze nieprawości przez czterdzieści lat i poznacie pomstę za odstąpienie ode mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 35, 'Ja, Pan, powiedziałem, że tak postąpię z całym tym niegodziwym zgromadzeniem, które się zmówiło przeciwko mnie; na tej pustyni zginą i tu pomrą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 36, 'Wtedy mężczyźni, których Mojżesz wysłał na wyszpiegowanie ziemi, a po powrocie pobudzili całe zgromadzenie do szemrania przeciwko niemu, rozpuszczając złą wieść o tej ziemi;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 37, 'Ci mężczyźni, którzy rozpowiadali złą wieść o ziemi, pomarli przed Panem wskutek plagi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 38, 'Lecz Jozue, syn Nuna, i Kaleb, syn Jefunnego, pozostali żywi spośród tych mężczyzn, którzy poszli wyszpiegować ziemię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 39, 'I Mojżesz powtórzył te słowa wszystkim synom Izraela, i lud bardzo płakał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 40, 'Wstali więc wcześnie rano, wstąpili na szczyt góry i powiedzieli: Oto jesteśmy, pójdziemy na to miejsce, o którym Pan nam powiedział, bo zgrzeszyliśmy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 41, 'Lecz Mojżesz powiedział im: Dlaczego przekraczacie słowo Pana? To się wam nie uda.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 42, 'Nie wyruszajcie, ponieważ nie ma Pana wśród was, abyście nie zostali pobici przez waszych wrogów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 43, 'Gdyż Amalekici i Kananejczycy są tam przed wami i polegniecie od miecza. Ponieważ odwróciliście się od Pana, to Pan nie będzie z wami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 44, 'Oni jednak uparli się, by wejść na szczyt góry. Lecz arka przymierza Pana i Mojżesz nie oddalili się z obozu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 45, 'Wtedy Amalekici i Kananejczycy mieszkający na tej górze zstąpili, pobili ich i ścigali aż do Chormy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 1, 'I Pan powiedział do Mojżesza:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 2, 'Przemów do synów Izraela i powiedz im: Gdy przyjdziecie do ziemi waszego mieszkania, którą wam daję;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 3, 'I będziecie chcieli złożyć Panu ofiarę spalaną na całopalenie, ofiarę bądź poślubioną, bądź dobrowolną lub też w wasze uroczyste święta, aby złożyć Panu miłą woń z wołów albo z owiec;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 4, 'To niech składający Panu ofiarę złoży na ofiarę pokarmową dziesiątą część efy mąki pszennej zmieszanej z czwartą częścią hinu oliwy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 5, 'A czwartą część hinu wina na ofiarę z płynów przygotujesz przy całopaleniu lub innej ofierze na każde jagnię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 6, 'Przy baranie zaś złożysz na ofiarę pokarmową dwie dziesiąte efy mąki pszennej zmieszanej z trzecią częścią hinu oliwy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 7, 'A na ofiarę z płynów złożysz jedną trzecią hinu wina jako miłą woń dla Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 8, 'Gdy zaś będziesz składał cielca na ofiarę całopalną lub na ofiarę wypełnienia ślubu albo na ofiarę pojednawczą dla Pana;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 9, 'Wtedy wraz z cielcem złożysz na ofiarę pokarmową trzy dziesiąte efy mąki pszennej zmieszanej z połową hinu oliwy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 10, 'Na ofiarę pokarmową złożysz też połowę hinu wina, na ofiarę spalaną jako miłą woń dla Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 11, 'Tak należy postąpić przy każdym wole, przy każdym baranie, jagnięciu lub koźlęciu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 12, 'Według liczby, którą składacie, tak uczynicie z każdą ich sztuką według ich liczby.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 13, 'Każdy rodowity mieszkaniec postąpi w ten sposób, gdy będzie składał ofiarę spalaną jako miłą woń dla Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 14, 'A jeśli obcy gości u was lub mieszka z wami od pokoleń i będzie chciał złożyć ofiarę spalaną jako miłą woń dla Pana, uczyni to tak, jak wy czynicie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 15, 'Będzie jedna ustawa dla was i dla przybysza, który mieszka wśród was; będzie to ustawa wieczysta przez wszystkie wasze pokolenia. Przybysz będzie przed Panem tak jak wy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 16, 'Będzie jedno prawo i jeden sąd dla was i przybysza, który mieszka wśród was.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 17, 'I Pan powiedział do Mojżesza:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 18, 'Przemów do synów Izraela i powiedz im: Gdy wejdziecie do ziemi, do której was wprowadzę;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 19, 'A będziecie jeść chleb tej ziemi, to złożycie Panu ofiarę wzniesienia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 20, 'Złożycie jako ofiarę wzniesienia placek z pierwocin waszych ciast; złożycie go tak jak ofiarę wzniesienia z klepiska.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 21, 'Będziecie składać Panu ofiarę wzniesienia z pierwocin waszych ciast przez wszystkie wasze pokolenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 22, 'A gdybyście zbłądzili i nie wypełnili wszystkich tych przykazań, które Pan nadał przez Mojżesza;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 23, 'Tego wszystkiego, co Pan wam rozkazał przez Mojżesza, od tego dnia, w którym Pan to nakazał, i potem przez wszystkie wasze pokolenia;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 24, 'Jeśli popełniono ten błąd nieświadomie przez zgromadzenia, to całe zgromadzenie złoży jednego młodego cielca na całopalenie, na miłą woń dla Pana, wraz z jego ofiarą pokarmową i ofiarą z płynów według zwyczaju, oraz jednego kozła ze stada na ofiarę za grzech.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 25, 'I kapłan dokona przebłagania za całe zgromadzenie synów Izraela, i będzie im przebaczone, gdyż stało się to nieświadomie. A oni przyniosą Panu swoją ofiarę na ofiarę spalaną i swoją ofiarę za grzech przed Panem za swój błąd.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 26, 'I będzie przebaczone całemu zgromadzeniu synów Izraela i przybyszowi, który mieszka pośród nich, ponieważ cały lud popełnił to nieświadomie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 27, 'A jeśli tylko jedna osoba zgrzeszy nieświadomie, wtedy przyniesie roczną kozę na ofiarę za grzech;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 28, 'I kapłan dokona przebłagania za człowieka, który zbłądził, grzesząc wobec Pana nieświadomie; dokona za niego przebłagania i będzie mu przebaczone.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 29, 'Będzie jedno prawo dla tego, który grzeszy nieświadomie, zarówno dla rodowitego mieszkańca wśród synów Izraela, jak i dla przybysza, który mieszka pośród nich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 30, 'Lecz człowiek, który bezczelnie zgrzeszy świadomie, zarówno rodowity mieszkaniec, jak i przybysz, znieważa Pana; człowiek ten zostanie wykluczony spośród swego ludu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 31, 'Wzgardził bowiem słowem Pana i złamał jego przykazanie; taki człowiek musi zostać wykluczony; na nim ciąży jego nieprawość.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 32, 'A gdy synowie Izraela byli na pustyni, spotkali człowieka zbierającego drwa w dzień szabatu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 33, 'I ci, którzy go spotkali zbierającego drwa, przyprowadzili go do Mojżesza i Aarona, i do całego zgromadzenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 34, 'I osadzili go pod strażą, bo jeszcze im nie oznajmiono, jak należy z takim postąpić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 35, 'Wtedy Pan powiedział do Mojżesza: Ten człowiek musi ponieść śmierć; niech całe zgromadzenie go ukamienuje poza obozem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 36, 'Całe zgromadzenie wyprowadziło go poza obóz i ukamienowało, i umarł, jak Pan rozkazał Mojżeszowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 37, 'I Pan powiedział do Mojżesza:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 38, 'Przemów do synów Izraela i powiedz im, aby robili sobie frędzle na skrajach swoich szat przez wszystkie pokolenia, a do frędzli niech przyprawią sznurek z błękitnej tkaniny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 39, 'I będziecie mieć te frędzle, żebyście na nie spoglądali i przypominali sobie wszystkie przykazania Pana, aby je wypełnić, a nie podążali za własnym sercem i własnymi oczami, za którymi idąc, cudzołożylibyście;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 40, 'Abyście pamiętali i wypełniali wszystkie moje przykazania, i byli święci dla waszego Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 41, 'Ja jestem Pan, wasz Bóg, który was wyprowadził z ziemi Egiptu, aby być waszym Bogiem. Ja jestem Pan, wasz Bóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 1, 'Wtedy Korach, syn Ishara, syna Kehata, syna Lewiego, oraz Datan i Abiram, synowie Eliaba, i On, syn Peleta, synowie Rubena, wzięli ludzi;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 2, 'I powstali przeciw Mojżeszowi, a wraz z nimi dwustu pięćdziesięciu mężczyzn spośród synów Izraela, naczelników zgromadzenia powołanych do rady, ludzi poważanych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 3, 'Zebrali się oni przeciw Mojżeszowi i Aaronowi i powiedzieli do nich: Bierzecie zbyt dużo na siebie! Przecież całe to zgromadzenie, wszyscy oni są święci i wśród nich jest Pan. Dlaczego więc wynosicie się ponad zgromadzenie Pana?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 4, 'Gdy Mojżesz to usłyszał, upadł na twarz;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 5, 'I powiedział do Koracha i do całej jego gromady: Jutro rano Pan pokaże, kto jest jego, kto jest święty i może zbliżyć się do niego. Kogo bowiem wybrał, temu pozwoli zbliżyć się do siebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 6, 'Tak więc uczynicie: Weźcie sobie kadzielnice, ty, Korach i cała twoja gromada.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 7, 'I włóżcie w nie ogień, i jutro umieśćcie w nich kadzidło przed Panem; a ten człowiek, którego Pan wybierze, będzie święty. Bierzecie zbyt dużo na siebie, synowie Lewiego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 8, 'I powiedział Mojżesz do Koracha: Słuchajcie, proszę, synowie Lewiego;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 9, 'Czy wam to mało, że Bóg Izraela oddzielił was od zgromadzenia Izraela, aby zbliżyć was do siebie, abyście pełnili służbę w przybytku Pana i abyście stali przed zgromadzeniem, i mu służyli?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 10, 'I ciebie, a wraz z tobą wszystkich twoich braci, synów Lewiego, zbliżył do siebie, a wy jeszcze zabiegacie o kapłaństwo?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 11, 'Dlatego ty i cała twoja gromada zbuntowaliście się przeciw Panu, bo kim jest Aaron, że szemracie przeciw niemu?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 12, 'Wtedy Mojżesz kazał przywołać Datana i Abirama, synów Eliaba, lecz oni odpowiedzieli: Nie przyjdziemy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 13, 'Nie dość, że nas wyprowadziłeś z ziemi opływającej mlekiem i miodem, aby nas uśmiercić na tej pustyni, to jeszcze chcesz obwołać się naszym władcą?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 14, 'Ponadto nie wprowadziłeś nas do ziemi opływającej mlekiem i miodem ani nie dałeś nam w dziedzictwo pól i winnic. Czy chcesz tym mężczyznom wyłupić oczy? Nie przyjdziemy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 15, 'Wtedy Mojżesz bardzo się rozgniewał i powiedział do Pana: Nie zważaj na ich ofiarę. Nie wziąłem od nich żadnego osła ani też nikogo z nich nie skrzywdziłem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 16, 'Potem Mojżesz powiedział do Koracha: Ty i cała twoja gromada stawcie się jutro przed Panem; ty, oni i Aaron:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 17, 'Każdy z was niech weźmie swoją kadzielnicę i nałoży w nią kadzidła, i niech każdy przyniesie przed Pana swoją kadzielnicę, razem dwieście pięćdziesiąt kadzielnic, również ty i Aaron; każdy przyniesie swoją kadzielnicę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 18, 'Każdy więc wziął swoją kadzielnicę, włożył w nią ogień, nałożył na niego kadzidła i stanęli u wejścia do Namiotu Zgromadzenia wraz z Mojżeszem i Aaronem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 19, 'A Korach zebrał przeciwko nim całe zgromadzenie u wejścia do Namiotu Zgromadzenia i wtedy chwała Pana ukazała się całemu ludowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 20, 'I Pan powiedział do Mojżesza i Aarona:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 21, 'Odłączcie się od tego zgromadzenia, abym mógł je w jednej chwili zniszczyć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 22, 'Lecz oni upadli na twarz i powiedzieli: O Boże, Boże duchów wszelkiego ciała! Czy jeśli zgrzeszy jeden człowiek, będziesz się gniewał na całe zgromadzenie?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 23, 'Pan powiedział do Mojżesza:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 24, 'Przemów do zgromadzenia i powiedz im: Oddalcie się od namiotu Koracha, Datana i Abirama.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 25, 'Mojżesz wstał więc i podszedł do Datana i Abirama, a za nim poszli starsi Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 26, 'I powiedział do zgromadzenia: Oddalcie się, proszę, od namiotów tych bezbożnych ludzi i nie dotykajcie niczego, co do nich należy, abyście nie zginęli przez wszystkie ich grzechy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 27, 'I oddalili się od namiotów Koracha, Datana i Abirama z każdej strony. Datan zaś i Abiram wyszli i stali u wejścia do swoich namiotów razem ze swoimi żonami, synami i małymi dziećmi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 28, 'Wtedy Mojżesz powiedział: Po tym poznacie, że Pan mnie posłał, abym dokonał wszystkich tych dzieł, i że nic z własnej woli nie czynię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 29, 'Jeśli ci ludzie umrą taką śmiercią jak wszyscy ludzie albo zostaną ukarani tak jak inni, to nie Pan mnie posłał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 30, 'Ale jeśli Pan uczyni coś nowego i ziemia otworzy swoją paszczę, i pochłonie ich oraz wszystko, co do nich należy, i żywcem zstąpią do piekła, wtedy poznacie, że ci mężczyźni rozdrażnili Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 31, 'Gdy tylko skończył wypowiadać wszystkie te słowa, ziemia rozstąpiła się pod nimi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 32, 'A ziemia otworzyła swoją paszczę, i pochłonęła ich oraz ich domy i wszystkich ludzi, którzy byli przy Korachu, i cały ich dobytek.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 33, 'I zstąpili oni razem ze wszystkim, co mieli, żywcem do piekła, i ziemia ich okryła; tak zginęli spośród zgromadzenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 34, 'Wszyscy zaś Izraelici, którzy stali wokół nich, uciekli na ich krzyk, bo mówili: By i nas ziemia nie pochłonęła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 35, 'Wyszedł też ogień od Pana i pochłonął tych dwustu pięćdziesięciu mężczyzn, którzy ofiarowali kadzidło.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 36, 'I Pan powiedział do Mojżesza:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 37, 'Powiedz do Eleazara, syna kapłana Aarona, niech pozbiera kadzielnice z tego pogorzeliska, a ogień niech rozrzuci dalej. Są bowiem poświęcone.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 38, 'A kadzielnice tych, którzy zgrzeszyli przeciwko własnym duszom, rozbijcie na blachy na pokrycie ołtarza. Ofiarowali je bowiem przed Panem, są więc poświęcone. Dlatego będą znakiem dla synów Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 39, 'Pozbierał więc kapłan Eleazar miedziane kadzielnice, w których ofiarowali ci, którzy spłonęli, i rozbito je na blachy na pokrycie ołtarza;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 40, 'Na pamiątkę dla synów Izraela, aby żaden obcy, który nie jest z potomstwa Aarona, nie zbliżał się do składania kadzidła przed Panem i żeby go nie spotkało to, co spotkało Koracha i jego gromady, jak Pan mu powiedział przez Mojżesza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 41, 'A nazajutrz całe zgromadzenie synów Izraela szemrało przeciwko Mojżeszowi i Aaronowi: Wy spowodowaliście śmierć ludu Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 42, 'I gdy zgromadzenie zbierało się przeciw Mojżeszowi i Aaronowi, spojrzeli w stronę Namiotu Zgromadzenia, a oto okrył go obłok i ukazała się chwała Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 43, 'Wtedy Mojżesz z Aaronem przyszli przed Namiot Zgromadzenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 44, 'I Pan powiedział do Mojżesza:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 45, 'Wyjdźcie spośród tego zgromadzenia, a zniszczę je w mgnieniu oka; i upadli na twarz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 46, 'Potem Mojżesz powiedział do Aarona: Weź kadzielnicę, włóż w nią ogień z ołtarza, nałóż też kadzidła i pójdź szybko do zgromadzenia, i zrób przebłaganie za nich, bo już wyszedł gniew od Pana i już zaczęła się plaga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 47, 'Aaron wziął więc kadzielnicę, jak mu rozkazał Mojżesz, i pobiegł w środek zgromadzenia, a oto już zaczęła się plaga wśród ludzi; nałożył kadzidła i dokonał przebłagania za lud.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 48, 'I Aaron stał między umarłymi i żywymi i plaga została powstrzymana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 49, 'Tych, co umarli od tej plagi, było czternaście tysięcy siedemset, oprócz tych, którzy umarli w związku ze sprawą Koracha.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 50, 'Potem Aaron wrócił do Mojżesza przed wejście do Namiotu Zgromadzenia, a plaga została zatrzymana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 1, 'Potem Pan powiedział do Mojżesza:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 2, 'Mów do synów Izraela i weź od każdego z nich po lasce według domów ich ojców, od wszystkich ich naczelników według domów ich ojców dwanaście lasek, a imię każdego napisz na jego lasce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 3, 'A imię Aarona napiszesz na lasce Lewiego, gdyż jedna laska będzie dla każdego naczelnika z domu ich ojców.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 4, 'I położysz je w Namiocie Zgromadzenia przed Świadectwem, gdzie się z wami spotykam.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 5, 'I stanie się tak, że laska tego, kogo wybiorę, zakwitnie; i uśmierzę przed sobą szemrania synów Izraela, jakie kierują przeciwko wam.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 6, 'Gdy Mojżesz przekazał to synom Izraela, wszyscy ich naczelnicy oddali mu swoje laski, po jednej lasce od każdego naczelnika z domu swego ojca, razem dwanaście lasek. Wśród ich lasek była też laska Aarona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 7, 'Potem Mojżesz złożył te laski przed Panem w Namiocie Świadectwa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 8, 'Nazajutrz, gdy Mojżesz przyszedł do Namiotu Świadectwa, oto laska Aarona, z domu Lewiego, zakwitła, wypuściła pączki, wydała kwiat i dojrzałe migdały.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 9, 'Wtedy Mojżesz wyniósł wszystkie laski sprzed Pana do wszystkich synów Izraela; a gdy je ujrzeli, każdy z nich wziął swoją laskę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 10, 'I Pan powiedział do Mojżesza: Połóż laskę Aarona z powrotem przed Świadectwem, aby była zachowana na znak dla buntowników, a położysz kres ich szemraniu przeciwko mnie, aby nie pomarli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 11, 'I Mojżesz tak uczynił; jak Pan mu rozkazał, tak uczynił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 12, 'I synowie Izraela powiedzieli do Mojżesza: Oto umieramy, giniemy, wszyscy giniemy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 13, 'Każdy, kto zbliża się do przybytku Pana, umrze. Czy mamy doszczętnie zginąć?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 1, 'Potem Pan powiedział do Aarona: Ty, twoi synowie i dom twego ojca z tobą, odpowiecie za nieprawość świątyni. Ty i twoi synowie z tobą również odpowiecie za nieprawość waszego kapłaństwa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 2, 'A twoim braciom z pokolenia Lewiego, z rodu twego ojca, pozwól do siebie przychodzić, aby dołączyli do ciebie i usługiwali tobie; ty zaś i twoi synowie z tobą będziecie pełnić służbę przed Namiotem Świadectwa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 3, 'Oni będą przestrzegać twego nakazu i pełnić straż nad całym namiotem. Nie mogą jednak zbliżać się do sprzętów świątyni i do ołtarza, żeby nie pomarli ani oni, ani wy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 4, 'Przyłączą się do ciebie i będą pełnić straż przy Namiocie Zgromadzenia, przy każdej służbie namiotu. Lecz żaden obcy niech się do was nie zbliża.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 5, 'Wy będziecie pełnić straż w świątyni i straż przy ołtarzu, aby już nie spadł gniew na synów Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 6, 'Oto wziąłem waszych braci Lewitów spośród synów Izraela. Oni są wam oddani jako dar dla Pana, aby pełnili służbę w Namiocie Zgromadzenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 7, 'Ty zaś i twoi synowie z tobą będziecie strzec waszego kapłaństwa przy każdej służbie ołtarza i poza zasłoną, i będziecie służyć. Dałem wam urząd waszego kapłaństwa jako dar; obcy, który się zbliży, poniesie śmierć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 8, 'Pan mówił dalej do Aarona: Oto dałem tobie pod straż moje ofiary wzniesione ze wszystkich poświęconych rzeczy synów Izraela. Z powodu namaszczenia dałem je tobie i twoim synom prawem wieczystym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 9, 'To będzie należeć do ciebie z rzeczy najświętszych, które nie zostaną spalone: każda ich ofiara, każda ich ofiara pokarmowa, każda ich ofiara za grzech i każda ich ofiara za przewinienie, które będą mi składać, będą to rzeczy najświętsze dla ciebie i twoich synów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 10, 'W miejscu najświętszym będziesz to jeść; wszyscy mężczyźni będą z tego jedli. Będzie to dla ciebie rzeczą świętą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 11, 'To też będzie dla ciebie: ofiara wzniesienia ich darów ze wszystkimi ofiarami kołysania synów Izraela. Daję je tobie, twoim synom i twoim córkom z tobą prawem wieczystym. Każdy czysty w twoim domu będzie je spożywać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 12, 'Wszystko, co najlepsze z oliwy, i wszystko, co najlepsze z wina, oraz zboże, ich pierwociny, które ofiarują Panu, dałem tobie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 13, 'Pierwociny ze wszystkich rzeczy znajdujących się w ich ziemi, które przyniosą Panu, będą twoje. Każdy czysty w twoim domu będzie je spożywać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 14, 'Wszystko, co jest poświęcone w Izraelu, będzie twoje.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 15, 'Wszystko, co otwiera łono wszelkiego ciała, które przynoszą Panu, zarówno z ludzi, jak i z bydła, będzie twoje; lecz pierworodnego z ludzi wykupisz, także pierworodne z nieczystych zwierząt wykupisz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 16, 'A wykup tego, który ma jeden miesiąc, dasz według twego oszacowania pięć syklów srebra według sykla świątynnego, który wynosi dwadzieścia ger.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 17, 'Ale pierworodnego z krowy, pierworodnego z owcy lub pierworodnego z kozy nie wykupisz; są one święte. Ich krew wylejesz na ołtarz, a ich tłuszcz zapalisz jako ofiarę spaloną, jako miłą woń dla Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 18, 'Ale ich mięso będzie twoje, podobnie jak mostek wzniesienia i prawa łopatka są twoje.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 19, 'Wszystkie ofiary wzniesienia z poświęconych rzeczy, które będą przynosić Panu synowie Izraela, daję tobie, twoim synom i twoim córkom z tobą prawem wieczystym. Jest to wieczyste przymierze soli przed Panem, dla ciebie i twojego potomstwa wraz z tobą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 20, 'Potem Pan powiedział do Aarona: Nie będziesz miał dziedzictwa w ich ziemi i nie będziesz miał żadnego działu wśród nich. Ja jestem twoim działem i twoim dziedzictwem pośród synów Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 21, 'Oto zaś synom Lewiego dałem jako dziedzictwo wszystkie dziesięciny w Izraelu za ich służbę, którą pełnią w Namiocie Zgromadzenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 22, 'A niech synowie Izraela nie zbliżają się już do Namiotu Zgromadzenia, aby nie obciążyli się grzechem i nie umarli;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 23, 'Ale sami Lewici będą pełnić służbę w Namiocie Zgromadzenia i sami poniosą karę za swoją nieprawość. Będzie to ustawa wieczysta przez wszystkie wasze pokolenia, że Lewici nie będą mieli dziedzictwa pośród synów Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 24, 'Dałem bowiem Lewitom w dziedzictwo dziesięciny synów Izraela, które przynoszą Panu jako ofiarę wzniesienia. Dlatego powiedziałem o nich: Nie będą mieli dziedzictwa pośród synów Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 25, 'Potem Pan powiedział do Mojżesza:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 26, 'Przemów do Lewitów i powiedz im: Gdy przyjmujecie od synów Izraela dziesięciny, które dałem wam od nich jako wasze dziedzictwo, wtedy złożycie Panu jako ofiarę wzniesienia dziesiątą część z dziesięciny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 27, 'A wasza ofiara wzniesienia będzie wam poczytana za zboże z klepiska i za obfitość z tłoczni winnej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 28, 'W ten sposób też i wy macie składać Panu ofiarę wzniesienia ze wszystkich waszych dziesięcin, które przyjmujecie od synów Izraela; kapłanowi Aaronowi oddacie z nich ofiarę wzniesienia należną Panu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 29, 'Ze wszystkich waszych darów będziecie składać Panu wszelką ofiarę wzniesienia; ze wszystkiego, co najlepsze, ofiarujcie jego poświęconą część.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 30, 'Powiesz im też: Gdy będziecie oddawać z tego, co najlepsze, wtedy będzie to poczytane Lewitom jako plon z klepiska i jako plon z tłoczni winnej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 31, 'I będziecie to jeść na każdym miejscu, wy i wasi domownicy, ponieważ to jest wasza zapłata za waszą służbę w Namiocie Zgromadzenia;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 32, 'I nie obciążycie się grzechem za to, gdy będziecie składać, co najlepsze z tego, i nie splugawicie rzeczy poświęconych synów Izraela, i nie umrzecie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 1, 'I Pan powiedział do Mojżesza i Aarona:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 2, 'To jest ustawa prawa, którą nadał Pan: Powiedz synom Izraela, aby przyprowadzili do ciebie czerwoną jałówkę, zdrową i bez skazy, na której jeszcze nie było jarzma.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 3, 'Oddacie ją kapłanowi Eleazarowi, który ją wyprowadzi poza obóz, i zostanie przed nim zabita.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 4, 'A kapłan Eleazar weźmie nieco z jej krwi na swój palec i pokropi nią siedem razy na wprost przed Namiotem Zgromadzenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 5, 'Potem każe spalić jałówkę na swoich oczach: spali jej skórę, mięso, krew wraz z jej odchodami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 6, 'I kapłan weźmie drewno cedrowe, hizop i karmazyn i wrzuci to do ognia, w którym płonie jałówka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 7, 'Wtedy kapłan wypierze swoje szaty i umyje swoje ciało wodą; potem wejdzie do obozu i będzie nieczysty do wieczora.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 8, 'Również ten, który ją będzie palić, wypierze swoje szaty w wodzie i umyje swoje ciało wodą, i będzie nieczysty do wieczora.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 9, 'Człowiek czysty zbierze popiół tej jałówki i złoży go poza obozem na miejscu czystym; będzie on przechowywany dla zgromadzenia synów Izraela do wody oczyszczenia; jest to ofiara za grzech.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 10, 'Ten, który zbierał popiół jałówki, wypierze swoje szaty i będzie nieczysty do wieczora. Będzie to ustawa wieczysta dla synów Izraela i dla przybysza mieszkającego wśród was.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 11, 'Kto dotknie jakiegokolwiek ludzkiego trupa, będzie nieczysty przez siedem dni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 12, 'Taki oczyści się tą wodą w trzecim i siódmym dniu i będzie czysty. Jeśli jednak nie oczyści się w trzecim i siódmym dniu, będzie nieczysty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 13, 'Kto dotknie zwłok człowieka zmarłego, a nie oczyści się, ten zanieczyści przybytek Pana; ta dusza będzie wykluczona z Izraela. Człowiek ten nie został bowiem pokropiony wodą oczyszczenia; będzie nieczysty, a jego nieczystość pozostanie na nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 14, 'Taka jest ustawa, gdy człowiek umrze w namiocie: ktokolwiek wejdzie do tego namiotu i cokolwiek znajduje się w tym namiocie będzie nieczyste przez siedem dni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 15, 'Każde naczynie odkryte, które nie ma przymocowanej pokrywy, będzie nieczyste.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 16, 'Kto dotknie na polu zabitego mieczem lub umarłego, lub kości ludzkich, lub grobu będzie nieczysty przez siedem dni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 17, 'Wezmą dla tego nieczystego nieco popiołu jałówki spalonej za grzech i na to wleją do naczynia źródlanej wody.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 18, 'Człowiek czysty weźmie hizop, zmoczy go w tej wodzie i pokropi namiot oraz wszystkie naczynia i wszystkich ludzi, którzy tam byli, także tego, który dotknął kości lub zabitego, lub zmarłego, lub grobu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 19, 'Człowiek czysty pokropi nieczystego w trzecim i siódmym dniu, a gdy go oczyści w siódmym dniu, wypierze on swoje szaty i umyje się wodą, i wieczorem będzie czysty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 20, 'A człowiek, który stał się nieczysty, a nie oczyścił się, zostanie wykluczony spośród zgromadzenia, gdyż ta dusza zbezcześciła świątynię Pana. Człowiek ten nie został pokropiony wodą oczyszczenia i jest nieczysty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 21, 'Będzie to dla nich ustawą wieczystą: kto skrapia wodą oczyszczenia, wypierze swoje szaty, a kto dotknie tej wody oczyszczenia, będzie nieczysty do wieczora.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 22, 'Czegokolwiek dotknie nieczysty, będzie nieczyste; również człowiek, który tego dotknie, będzie nieczysty do wieczora.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 1, 'I przyszło całe zgromadzenie synów Izraela na pustynię Syn w pierwszym miesiącu. I lud zamieszkał w Kadesz. Tam umarła Miriam i tam została pogrzebana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 2, 'A gdy zabrakło wody dla ludu, zebrali się przeciw Mojżeszowi i Aaronowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 3, 'Lud spierał się z Mojżeszem, mówiąc: Obyśmy umarli, gdy nasi bracia umarli przed Panem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 4, 'Dlaczego przyprowadziliście to zgromadzenie Pana na tę pustynię, abyśmy tu pomarli wraz z naszym bydłem?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 5, 'Po co wyprowadziliście nas z Egiptu, aby nas wprowadzić na to złe miejsce; na miejsce, w którym nie ma ani zboża, ani fig, ani winogron, ani jabłek granatu, nie ma nawet wody do picia?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 6, 'Wtedy Mojżesz i Aaron przeszli sprzed ludu przed wejście do Namiotu Zgromadzenia i upadli na twarze. A chwała Pana ukazała się im.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 7, 'I Pan powiedział do Mojżesza:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 8, 'Weź laskę, zgromadźcie cały lud, ty i twój brat Aaron, i przemówcie na ich oczach do tej skały, a ona wyda z siebie wodę; wydobędziesz dla nich wodę ze skały i dasz pić całemu zgromadzeniu oraz ich zwierzętom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 9, 'Wziął więc Mojżesz laskę sprzed oblicza Pana, tak jak mu rozkazał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 10, 'I Mojżesz z Aaronem zgromadzili cały lud przed skałą, i Mojżesz mówił do nich: Słuchajcie teraz, buntownicy! Czy z tej skały mamy wyprowadzić dla was wodę?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 11, 'Następnie Mojżesz podniósł rękę i uderzył swoją laską dwa razy w skałę. Wtedy wypłynęła obficie woda i napiło się zgromadzenie oraz jego bydło.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 12, 'I Pan powiedział do Mojżesza i Aarona: Ponieważ nie uwierzyliście mi, by mnie poświęcić na oczach synów Izraela, dlatego nie wprowadzicie tego zgromadzenia do ziemi, którą im daję.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 13, 'To są wody Meriba, gdzie synowie Izraela spierali się z Panem i został poświęcony w nich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 14, 'Potem Mojżesz wysłał z Kadesz posłańców do króla Edomu, mówiąc: Tak mówi twój brat Izrael: Ty znasz całą udrękę, która nas spotkała;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 15, 'Jak nasi ojcowie zstąpili do Egiptu i mieszkaliśmy w Egipcie wiele lat; i Egipcjanie dręczyli nas i naszych ojców;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 16, 'I wołaliśmy do Pana, a wysłuchał naszego głosu i posłał Anioła, i wyprowadził nas z Egiptu. Teraz jesteśmy w Kadesz, w mieście przy twojej granicy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 17, 'Pozwól nam, proszę, przejść przez twoją ziemię; nie pójdziemy przez pola ani przez winnice i nie będziemy pić wód ze studni. Pójdziemy drogą królewską, nie zboczymy ani w prawo, ani w lewo, dopóki nie przejdziemy twoich granic.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 18, 'Edom odpowiedział mu: Nie przejdziesz przez moją ziemię, bo inaczej wyjdę przeciwko tobie z mieczem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 19, 'I synowie Izraela powiedzieli mu: Pójdziemy główną drogą, a jeśli będziemy pili twoją wodę, my i nasze zwierzęta, zapłacimy za to. Niczego innego nie żądamy; tylko przejdziemy pieszo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 20, 'A on odpowiedział: Nie przejdziesz. I Edom wyruszył naprzeciwko nim z licznym ludem i mocną ręką.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 21, 'Tak Edom nie pozwolił Izraelowi przejść przez swoje granice. Izrael więc odstąpił od niego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 22, 'I synowie Izraela, całe zgromadzenie, wyruszyli z Kadesz i przyszli do góry Hor.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 23, 'I Pan powiedział do Mojżesza i Aarona na górze Hor, na granicy ziemi Edomu:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 24, 'Aaron zostanie przyłączony do swego ludu; nie wejdzie bowiem do ziemi, którą dałem synom Izraela, ponieważ sprzeciwiliście się mojemu słowu przy wodach Meriba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 25, 'Weź Aarona i jego syna Eleazara i przyprowadź ich na górę Hor;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 26, 'I zdejmij z Aarona jego szaty, a ubierz w nie jego syna Eleazara. Aaron zaś zostanie przyłączony do swego ludu i tam umrze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 27, 'I Mojżesz uczynił tak, jak Pan rozkazał; i wstąpili na górę Hor na oczach całego zgromadzenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 28, 'Mojżesz zdjął z Aarona jego szaty i ubrał w nie jego syna Eleazara. Aaron umarł tam na wierzchu góry, a Mojżesz i Eleazar zeszli z góry.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 29, 'Gdy całe zgromadzenie zobaczyło, że Aaron nie żyje, opłakiwał Aarona cały dom Izraela przez trzydzieści dni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 1, 'A gdy król Aradu, Kananejczyk, który mieszkał na południu, usłyszał, że Izrael nadciąga drogą, którą przeszli szpiedzy, stoczył walkę z Izraelem i wziął jeńców.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 2, 'Wtedy Izrael złożył Panu ślub, mówiąc: Jeśli wydasz ten lud w moje ręce, całkowicie zniszczę ich miasta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 3, 'I Pan wysłuchał głosu Izraela, i wydał mu Kananejczyków. Całkowicie zniszczyli ich oraz ich miasta, a nadano temu miejscu nazwę Chorma.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 4, 'Potem wyruszyli od góry Hor w kierunku Morza Czerwonego, aby obejść ziemię Edom. I lud bardzo się zniechęcił w drodze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 5, 'Lud zaczął więc mówić przeciw Bogu i Mojżeszowi: Dlaczego wyprowadziliście nas z Egiptu, abyśmy pomarli na tej pustyni? Bo nie ma chleba ani wody, a nasza dusza obrzydziła sobie ten cienki chleb.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 6, 'Zesłał więc Pan na lud węże jadowite, które go kąsały; i pomarło wiele osób z Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 7, 'I lud przyszedł do Mojżesza, i powiedział: Zgrzeszyliśmy przez to, że mówiliśmy przeciw Panu i przeciw tobie. Módl się do Pana, aby oddalił od nas te węże. I Mojżesz modlił się za lud.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 8, 'Wtedy Pan powiedział do Mojżesza: Wykonaj jadowitego węża i umieść go na drzewcu. I stanie się tak, że każdy ukąszony, kiedy spojrzy na niego, będzie żył.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 9, 'Mojżesz wykonał więc węża miedzianego i umieścił go na drzewcu; gdy wąż kogoś ukąsił, a ten spojrzał na węża miedzianego, pozostawał przy życiu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 10, 'I wyruszyli synowie Izraela, i rozbili obóz w Obot.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 11, 'A z Obot wyruszyli i rozbili obóz w Ijje-Haabarim na pustyni, która leży naprzeciw Moabu ku wschodowi słońca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 12, 'Stamtąd wyruszyli i rozbili obóz nad potokiem Zered.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 13, 'Stamtąd wyruszyli i rozbili obóz po drugiej stronie rzeki Arnon, która wypływa na pustyni od granicy Amorytów; Arnon stanowi bowiem granicę Moabu między Moabitami a Amorytami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 14, 'Dlatego jest powiedziane w księdze wojen Pana: Jak uczynił w Morzu Czerwonym i w potokach Arnonu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 15, 'U ujścia tych potoków, które ciągnie się ku osadzie Ar i przylega do granicy Moabu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 16, 'Stamtąd udali się do Beer; to jest ta studnia, o której Pan powiedział do Mojżesza: Zgromadź lud, a dam mu wody.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 17, 'Wtedy Izrael śpiewał tę pieśń: Wzbierz studnio! Śpiewajcie o niej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 18, 'To studnia, którą wykopali naczelnicy; wykopali ją dostojnicy ludu wraz z prawodawcą swoimi laskami. A z tej pustyni poszli do Mattany;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 19, 'A z Mattany do Nahalielu, a z Nahalielu do Bamot;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 20, 'A z Bamot do kotliny, która jest w ziemi Moabu, i do szczytu Pizga wznoszącego się nad Jeszimonem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 21, 'I Izrael wysłał posłańców do Sichona, króla Amorytów, mówiąc:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 22, 'Pozwól nam przejść przez twoją ziemię; nie pójdziemy ani przez pola, ani przez winnice; nie będziemy pić wód ze studni. Pójdziemy drogą królewską, dopóki nie przejdziemy twoich granic.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 23, 'Sichon jednak nie pozwolił Izraelowi przejść przez swoją granicę; Sichon zebrał cały swój lud i wyszedł przeciw Izraelowi na pustynię, a gdy przyszedł do Jahazy, stoczył bitwę z Izraelem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 24, 'I Izrael pobił go ostrzem miecza, i wziął w posiadanie jego ziemię od Arnonu do Jabboku, aż do ziemi synów Ammona, gdyż granica Ammonitów była silna.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 25, 'Wtedy Izrael zdobył wszystkie te miasta i zamieszkał we wszystkich miastach Amorytów, w Cheszbonie i we wszystkich przylegających do niego wsiach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 26, 'Cheszbon był miastem Sichona, króla Amorytów, który walczył z królem Moabu i zabrał mu z rąk całą jego ziemię aż po Arnon.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 27, 'Dlatego mówią w przypowieści: Wejdźcie do Cheszbonu i niech się odbuduje, i umocni miasto Sichona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 28, 'Ponieważ ogień wyszedł z Cheszbonu, płomień z miasta Sichona; i pochłonął Ar moabskie oraz wzgórza Arnonu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 29, 'Biada tobie, Moabie! Zginąłeś, ludu Kemosza! Wydał swoich synów na tułaczkę i swoje córki w niewolę Sichonowi, królowi Amorytów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 30, 'Strzelaliśmy do nich, zginął Cheszbon aż po Dibon; a zburzyliśmy je aż do Nofach, które idzie aż do Medeby.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 31, 'Tak to Izrael zamieszkał w ziemi Amorytów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 32, 'Wtedy Mojżesz wysłał wywiadowców do Jazer na wyszpiegowanie, a oni zdobyli jego wsie i wypędzili Amorytów, którzy tam byli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 33, 'Potem zawrócili i poszli w kierunku Baszanu; tam Og, król Baszanu, wyszedł przeciwko nim, on i cały jego lud, do walki w Edre.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 34, 'Wtedy Pan powiedział do Mojżesza: Nie bój się go, gdyż wydałem go w twoje ręce wraz z całym jego ludem i ziemią i uczynisz z nim tak, jak uczyniłeś z Sichonem, królem Amorytów, który mieszkał w Cheszbonie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 35, 'I pobili go i jego synów oraz cały jego lud, tak że nikogo z niego nie pozostawili przy życiu, i wzięli w posiadanie jego ziemię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 1, 'Potem synowie Izraela wyruszyli i rozbili obóz na równinach Moabu, z tej strony Jordanu naprzeciw Jerycha.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 2, 'A Balak, syn Sippora, widział wszystko, co Izrael uczynił Amorytom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 3, 'Wtedy Moab bardzo się zląkł tego ludu, bo był liczny; i zatrwożył się Moab z powodu synów Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 4, 'Powiedział więc Moab do starszych Midianu: Teraz to mnóstwo pożre wszystko wokół nas, jak wół pożera trawę na polu. A w tym czasie królem Moabu był Balak, syn Sippora.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 5, 'I wysłał posłańców do Balaama, syna Beora, do Petor, które leży nad rzeką ziemi synów jego ludu, aby go wezwać tymi słowy: Oto z Egiptu wyszedł lud, który okrył powierzchnię ziemi i stanął naprzeciwko mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 6, 'Dlatego teraz przyjdź, proszę, i przeklnij mi ten lud, bo jest silniejszy ode mnie. Może zdołam go pobić i wypędzić z ziemi, bo wiem, że komu błogosławisz, będzie błogosławiony, a kogo przeklinasz, będzie przeklęty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 7, 'Wtedy starsi Moabu i starsi Midianu wybrali się w drogę, mając w swych rękach zapłatę za wróżbę. Przyszli do Balaama i przekazali mu słowa Balaka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 8, 'On zaś powiedział do nich: Pozostańcie tu na noc, a dam wam odpowiedź, jaką mi oznajmi Pan. I zostali książęta Moabu u Balaama.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 9, 'I przyszedł Bóg do Balaama, i powiedział: Cóż to za ludzie są u ciebie?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 10, 'Balaam odpowiedział Bogu: Balak, syn Sippora, król Moabu, wysłał ich do mnie, mówiąc:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 11, 'Oto z Egiptu wyszedł lud, który okrył powierzchnię ziemi. Przyjdź więc teraz, przeklnij mi go; może zdołam go pokonać i wypędzić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 12, 'Bóg powiedział do Balaama: Nie idź z nimi i nie przeklnij tego ludu, bo jest on błogosławiony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 13, 'Gdy Balaam wstał rano, powiedział do książąt Balaka: Wracajcie do waszej ziemi, bo Pan nie pozwala mi iść z wami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 14, 'Wstali więc książęta Moabu, przyszli do Balaka i powiedzieli: Balaam nie chciał iść z nami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 15, 'Wtedy Balak ponownie wysłał książąt – liczniejszych i dostojniejszych od pierwszych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 16, 'Przybyli oni do Balaama i powiedzieli mu: Tak mówi Balak, syn Sippora: Nie zwlekaj z przyjściem do mnie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 17, 'Ja bowiem wielce cię uczczę i uczynię wszystko, co mi powiesz, tylko przyjdź, proszę, i przeklnij mi ten lud.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 18, 'Balaam odpowiedział sługom Balaka: Choćby Balak dał mi swój dom pełen srebra i złota, nie mógłbym przekroczyć słowa Pana, mego Boga, i uczynić przeciwko niemu czegoś małego czy wielkiego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 19, 'Lecz zostańcie tu i wy, proszę, na noc, a dowiem się, co Pan jeszcze będzie do mnie mówił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 20, 'I przyszedł Bóg do Balaama w nocy, i powiedział do niego: Jeśli ci mężczyźni przyjdą, aby cię wezwać, wstań i idź z nimi; uczynisz jednak, co ci rozkażę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 21, 'Wstał więc Balaam rano, osiodłał swoją oślicę i pojechał z książętami Moabu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 22, 'I zapłonął gniew Boga, że on poszedł; i stanął Anioł Pana na drodze jako przeciwnik. On zaś jechał na swojej oślicy i z nim dwaj jego słudzy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 23, 'A gdy oślica zobaczyła Anioła Pana stojącego na drodze z obnażonym mieczem w ręku, zboczyła z drogi i poszła w pole. Balaam zaś bił oślicę, aby ją zawrócić na drogę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 24, 'Wtedy Anioł Pana stanął na ścieżce między winnicami, a płot był z jednej i z drugiej strony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 25, 'A gdy oślica zobaczyła Anioła Pana, przyparła do muru i przygniotła do niego nogę Balaama; a on znowu ją bił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 26, 'Potem Anioł Pana poszedł dalej i stanął w ciasnym miejscu, gdzie nie można go było wyminąć ani z prawej, ani z lewej strony;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 27, 'A gdy oślica zobaczyła Anioła Pana, padła pod Balaamem. Wtedy Balaam bardzo się rozgniewał i bił oślicę kijem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 28, 'Wtedy Pan otworzył usta tej oślicy, a ona powiedziała do Balaama: Cóż ci uczyniłam, że już trzy razy mnie zbiłeś?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 29, 'Balaam odpowiedział oślicy: Ponieważ drwisz ze mnie. Gdybym miał miecz w ręku, teraz bym cię zabił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 30, 'Oślica powiedziała do Balaama: Czy nie jestem twoją oślicą, na której jeździsz, odkąd mnie dostałeś aż do dziś? Czy miałam zwyczaj tak tobie czynić? A on odpowiedział: Nie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 31, 'Wówczas Pan otworzył oczy Balaama i zobaczył Anioła Pana stojącego na drodze z obnażonym mieczem w ręku; i pochylił się, i upadł na twarz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 32, 'A Anioł Pana powiedział do niego: Dlaczego zbiłeś swoją oślicę trzy razy? Oto wyszedłem, by się tobie sprzeciwić, bo twoja droga jest przewrotna przede mną;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 33, 'A oślica widziała mnie i ustępowała przede mną trzy razy; gdyby nie ustąpiła przede mną, już bym cię teraz zabił, a ją pozostawił przy życiu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 34, 'Balaam powiedział więc do Anioła Pana: Zgrzeszyłem, bo nie wiedziałem, że stanąłeś naprzeciwko mnie na drodze; dlatego teraz, jeśli to ci się nie podoba, zawrócę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 35, 'Lecz Anioł Pana powiedział do Balaama: Jedź z tymi ludźmi, ale będziesz mówił tylko to, co tobie powiem. I poszedł Balaam z książętami Balaka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 36, 'A gdy Balak usłyszał, że Balaam nadchodzi, wyszedł mu naprzeciw, do pewnego miasta Moabu, które leżało na granicy Arnonu, na końcu granicy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 37, 'I Balak powiedział do Balaama: Czyż nie posłałem do ciebie pilnie, aby cię wezwać? Dlaczego nie przyszedłeś do mnie? Czyż nie potrafię cię uczcić?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 38, 'Balaam odpowiedział Balakowi: Oto przybyłem do ciebie. Czy mogę cokolwiek powiedzieć? Będę mówił słowo, które Bóg włoży w moje usta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 39, 'Poszedł więc Balaam z Balakiem i przyszli do Kiriat-Chusot.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 40, 'Balak złożył w ofierze woły i owce i posłał do Balaama oraz do książąt, którzy z nim byli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 41, 'A nazajutrz Balak zabrał Balaama i zaprowadził go na wyżyny Baala, skąd mógł widzieć kraniec obozu ludu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 1, 'I Balaam powiedział do Balaka: Zbuduj mi tu siedem ołtarzy i przygotuj mi tu siedem cielców i siedem baranów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 2, 'Uczynił więc Balak tak, jak powiedział Balaam; potem Balak i Balaam ofiarowali po jednym cielcu i jednym baranie na każdym ołtarzu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 3, 'Wtedy Balaam powiedział do Balaka: Pozostań przy swoim całopaleniu, a ja pójdę; może Pan spotka się ze mną, a cokolwiek mi objawi, powiem ci. I poszedł na wzgórze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 4, 'I Bóg spotkał się z Balaamem; i Balaam powiedział do niego: Postawiłem siedem ołtarzy i ofiarowałem po jednym cielcu i jednym baranie na każdym ołtarzu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 5, 'Wówczas Pan włożył słowa w usta Balaama i powiedział: Wróć do Balaka i tak mu powiedz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 6, 'I wrócił do niego, a oto stał przy swoim całopaleniu, on i wszyscy książęta Moabu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 7, 'I rozpoczął swą przypowieść, mówiąc: Balak, król Moabu, sprowadził mnie z Aramu, z gór wschodnich tymi słowy: Przyjdź, przeklnij mi Jakuba, przyjdź, złorzecz Izraelowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 8, 'Jakże mam przeklinać tego, kogo Bóg nie przeklął? I jak mam złorzeczyć temu, komu Pan nie złorzeczył?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 9, 'Gdyż widzę go ze szczytu skał, spoglądam na niego z pagórków; oto ten lud będzie mieszkać osobno, do innych narodów nie będzie zaliczony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 10, 'Któż policzy proch Jakuba, któż policzy choćby czwartą część Izraela? Niech umrę śmiercią sprawiedliwych i niech mój koniec będzie taki jak ich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 11, 'Wtedy Balak powiedział do Balaama: Cóż mi uczyniłeś? Sprowadziłem cię, abyś przeklął moich wrogów, a oto ty im wielce błogosławiłeś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 12, 'A on odpowiedział: Czy nie mam pilnować tego, by mówić to, co Pan włożył w moje usta?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 13, 'I Balak powiedział do niego: Chodź, proszę, ze mną na inne miejsce, z którego będziesz mógł ich widzieć; zobaczysz tylko ich skraj, wszystkich nie zobaczysz. Przeklnij mi ich stamtąd.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 14, 'I zaprowadził go na pole Sofim, na szczyt góry Pizga; tam zbudował siedem ołtarzy i ofiarował po jednym cielcu i jednym baranie na każdym ołtarzu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 15, 'I powiedział do Balaka: Pozostań tu przy swoim całopaleniu, a ja pójdę tam na spotkanie Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 16, 'I Pan wyszedł na spotkanie z Balaamem, włożył słowa w jego usta i powiedział: Wróć do Balaka i tak mu powiedz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 17, 'Przyszedł więc do niego, a oto on stał przy swoim całopaleniu, a z nim książęta Moabu. I Balak zapytał go: Cóż ci Pan powiedział?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 18, 'I rozpoczął swą przypowieść tymi słowy: Wstań, Balaku, i słuchaj; nakłoń swego ucha, synu Sippora.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 19, 'Bóg nie jest człowiekiem, aby miał kłamać, ani synem człowieczym, żeby miał żałować. Czy on powie coś, a tego nie uczyni? Czy wypowie, a nie spełni?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 20, 'Oto otrzymałem rozkaz, żeby błogosławić; on błogosławił, a ja tego nie mogę odwrócić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 21, 'Nie dostrzegł nieprawości w Jakubie ani nie widział przestępstwa w Izraelu. Pan, jego Bóg, jest z nim, a okrzyk króla – przy nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 22, 'Bóg wyprowadził ich z Egiptu, jego moc jest jak u jednorożca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 23, 'Nie ma bowiem zaklęcia przeciw Jakubowi ani wróżby przeciw Izraelowi. Już od tego czasu będzie się mówić o Jakubie i o Izraelu: Czego dokonał Bóg!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 24, 'Oto lud powstanie jak silny lew, jak młody lew się podnosi; nie położy się, aż pożre zdobycz i wypije krew zabitych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 25, 'Wtedy Balak powiedział do Balaama: Ani ich nie przeklinaj więcej, ani im też nie błogosław.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 26, 'I Balaam odpowiedział Balakowi: Czy nie powiedziałem ci, że cokolwiek powie Pan, to uczynię?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 27, 'Balak powiedział do Balaama: Chodź, proszę, zaprowadzę cię na inne miejsce, może się spodoba Bogu, żebyś ich stamtąd przeklął.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 28, 'Wtedy Balak wziął Balaama na szczyt Peor, który wznosi się nad pustynią.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 29, 'I Balaam powiedział do Balaka: Zbuduj mi siedem ołtarzy i przygotuj mi tu siedem cielców i siedem baranów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 30, 'Balak uczynił więc tak, jak mu rozkazał Balaam, i ofiarował po jednym cielcu i jednym baranie na każdym ołtarzu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 1, 'Gdy Balaam zauważył, że Pan upodobał sobie błogosławić Izraela, nie poszedł jak przedtem szukać wróżby, lecz zwrócił swoją twarz ku pustyni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 2, 'I Balaam podniósł swoje oczy, i zobaczył Izraela obozującego według swoich pokoleń. Wtedy Duch Boży spoczął na nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 3, 'I rozpoczął swoją przypowieść tymi słowy: Wypowiedź Balaama, syna Beora, wypowiedź człowieka, który ma otwarte oczy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 4, 'Wypowiedź tego, który słyszał słowa Boga, który miał widzenie Wszechmocnego, a padając, miał otwarte oczy:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 5, 'Jak piękne są twoje namioty, Jakubie, twoje przybytki, Izraelu!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 6, 'Rozciągnęły się jak doliny, jak ogrody przy rzece, jak aloesy, które Pan zasadził, jak cedry nad wodami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 7, 'Popłynie woda z jego wiadra, jego nasienie będzie w wielu wodach, jego król przewyższy Agaga i jego królestwo będzie wyniesione.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 8, 'Bóg wyprowadził go z Egiptu, jego moc jest jak u jednorożca; pożre wrogie sobie narody, pokruszy ich kości i przeszyje je swymi strzałami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 9, 'Położył się, leży jak lew, jak silny lew: któż go obudzi? Błogosławiony ten, kto cię błogosławi, a przeklęty ten, kto cię przeklina.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 10, 'Wtedy zapłonął gniew Balaka na Balaama i klasnął w dłonie. I Balak powiedział do Balaama: Wezwałem cię, abyś przeklinał moich wrogów, a oto już trzy razy ich błogosławiłeś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 11, 'Uciekaj więc teraz do siebie. Powiedziałem, że wielce cię uczczę, lecz oto Pan pozbawił cię tej czci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 12, 'I Balaam powiedział do Balaka: Czy i twoim posłom, których do mnie wysłałeś, nie powiedziałem:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 13, 'Choćby Balak dał mi swój dom pełen srebra i złota, nie będę mógł przekroczyć słowa Pana, bym sam z siebie uczynił coś dobrego lub złego; co Pan mi powie, to będę mówił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 14, 'Teraz idę do mego ludu, ale chodź i oznajmię ci, co ten lud uczyni twemu ludowi w przyszłości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 15, 'I rozpoczął swoją przypowieść tymi słowy: Wypowiedź Balaama, syna Beora, wypowiedź człowieka, który ma otwarte oczy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 16, 'Wypowiedź tego, który słyszał słowa Boga, który ma wiedzę o Najwyższym, który miał widzenie Wszechmocnego, a padając, miał otwarte oczy:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 17, 'Ujrzę go, ale nie teraz; zobaczę go, ale nie z bliska; gwiazda wzejdzie z Jakuba, berło powstanie z Izraela i pobije książąt Moabu oraz wytraci wszystkich synów Seta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 18, 'Edom stanie się posiadłością, Seir też stanie się posiadłością swoich wrogów, a Izrael będzie sobie poczynał mężnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 19, 'Z Jakuba powstanie władca i wyniszczy resztki miasta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 20, 'A gdy spojrzał na Amaleka, rozpoczął swą przypowieść tymi słowy: Amalek był pierwszym z narodów, lecz jego końcem będzie wieczna zguba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 21, 'Potem spojrzał na Kenitów i rozpoczął swą przypowieść tymi słowy: Twoje mieszkanie jest mocne, a swoje gniazdo założyłeś na skale;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 22, 'A jednak Kenita będzie spustoszony, aż Aszszur weźmie cię w niewolę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 23, 'Znowu rozpoczął swą przypowieść tymi słowy: Ach! Któż żyw zostanie, gdy Bóg to uczyni?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 24, 'Przypłyną bowiem okręty od wybrzeża Kittim i pognębią Aszszur, pognębią też Eber; lecz i oni sami zginą na zawsze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 25, 'Potem Balaam wstał i odszedł, i wrócił do siebie. Balak także poszedł swoją drogą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 1, 'Potem Izrael zamieszkał w Szittim i lud zaczął uprawiać nierząd z córkami Moabu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 2, 'One zapraszały lud do ofiar swoich bogów. A lud jadł i oddawał pokłon ich bogom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 3, 'I Izrael przyłączył się do Baal-Peora, i Pan bardzo rozgniewał się na Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 4, 'Wtedy Pan powiedział do Mojżesza: Zbierz wszystkich naczelników ludu i powieś ich przed Panem na słońcu, aby zapalczywość gniewu Pana odwróciła się od Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 5, 'Mojżesz powiedział więc do sędziów Izraela: Niech każdy z was zabije swoich ludzi, którzy przyłączyli się do Baal-Peora.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 6, 'A oto jeden z synów Izraela przyszedł i przyprowadził do swoich braci Midianitkę na oczach Mojżesza i na oczach całego zgromadzenia synów Izraela, którzy płakali przed wejściem do Namiotu Zgromadzenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 7, 'Gdy zobaczył to Pinchas, syn Eleazara, syna Aarona, kapłana, wstał spośród zgromadzenia i wziął do ręki oszczep.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 8, 'I poszedł za tym Izraelitą do namiotu, przebił oboje, tego Izraelitę oraz kobietę przez jej podbrzusze. I plaga wśród synów Izraela została powstrzymana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 9, 'A tych, którzy umarli od tej plagi, było dwadzieścia cztery tysiące.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 10, 'Potem Pan powiedział do Mojżesza:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 11, 'Pinchas, syn Eleazara, syna Aarona, kapłana, odwrócił mój gniew od synów Izraela, gdyż okazał wśród nich gorliwość ze względu na mnie, tak że nie wytraciłem synów Izraela w mojej zazdrości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 12, 'Dlatego powiedz mu: Oto zawieram z nim moje przymierze pokoju;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 13, 'Będzie to dla niego i dla jego potomstwa po nim przymierze wiecznego kapłaństwa, ponieważ okazał gorliwość o swego Boga i dokonał przebłagania za synów Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 14, 'A imię tego Izraelity, który został zabity wraz z Midianitką, było Zimri; był to syn Salu, naczelnika domu swego ojca, z pokolenia Symeona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 15, 'Imię zabitej Midianitki było Kozbi, była to córka Sura, naczelnika w swoim narodzie i w domu swego ojca w Midianie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 16, 'I Pan powiedział do Mojżesza:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 17, 'Odnoście się wrogo do Midianitów i pobijcie ich;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 18, 'Ponieważ oni odnosili się wrogo do was przez swoje podstępy, a podeszli was przez Baal-Peora i przez ich siostrę Kozbi, córkę księcia Midianu, która została zabita w dniu plagi z powodu Peora.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 1, 'A po tej pladze Pan powiedział do Mojżesza i Eleazara, syna Aarona, kapłana:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 2, 'Policzcie całe zgromadzenie synów Izraela, od dwudziestego roku życia wzwyż, według domów ich ojców, wszystkich zdolnych do walki w Izraelu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 3, 'Przemówił więc Mojżesz i kapłan Eleazar do nich na równinach Moabu, nad Jordanem, naprzeciw Jerycha:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 4, 'Policzcie lud, od dwudziestego roku życia wzwyż, jak Pan rozkazał Mojżeszowi i synom Izraela, którzy wyszli z ziemi Egiptu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 5, 'Ruben, pierworodny Izraela: synowie Rubena to Henoch, od którego pochodzi rodzina Henochitów; Pallu, od którego pochodzi rodzina Palluitów;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 6, 'Chesron, od którego pochodzi rodzina Chesronitów, i Karmi, od którego pochodzi rodzina Karmitów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 7, 'To są rodziny Rubenitów; a było ich policzonych czterdzieści trzy tysiące siedmiuset trzydziestu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 8, 'A synowie Pallu to Eliab.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 9, 'Synowie zaś Eliaba to Nemuel, Datan i Abiram. To ten Datan i Abiram, osławieni wśród zgromadzenia, którzy zbuntowali się przeciwko Mojżeszowi i Aaronowi z gromadą Koracha, gdy zbuntowali się przeciwko Panu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 10, 'I ziemia otworzyła swoją paszczę, i pochłonęła ich razem z Korachem, podczas gdy cała gromada zginęła; ogień pochłonął dwustu pięćdziesięciu mężczyzn. Stali się oni znakiem;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 11, 'Lecz synowie Koracha nie umarli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 12, 'Synowie Symeona według swych rodzin to: Nemuel, od którego pochodzi rodzina Nemuelitów, Jamin, od którego rodzina Jaminitów, Jachin, od którego rodzina Jachinitów;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 13, 'Zerach, od którego rodzina Zerachitów, Szaul, od którego rodzina Szaulitów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 14, 'To są rodziny Symeonitów; a było ich dwadzieścia dwa tysiące dwustu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 15, 'Synowie Gada według swych rodzin to: Sefon, od którego pochodzi rodzina Sefonitów, Chaggi, od którego rodzina Chaggitów, Szuni, od którego rodzina Szunitów;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 16, 'Ozni, od którego rodzina Oznitów, Er, od którego rodzina Erytów;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 17, 'Arod, od którego rodzina Arodytów, Ariel, od którego rodzina Arielitów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 18, 'To są rodziny synów Gada według ich spisu, czterdzieści tysięcy pięciuset.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 19, 'Synowie Judy to Er i Onan. Er i Onan umarli w ziemi Kanaan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 20, 'Synowie Judy według swych rodzin to: Szela, od którego pochodzi rodzina Szelitów, Peres, od którego rodzina Peresytów, Zerach, od którego rodzina Zerachitów;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 21, 'Synowie Peresa to: Chesron, od którego rodzina Chesronitów, Chamul, od którego rodzina Chamulitów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 22, 'To są rodziny Judy według ich spisu, siedemdziesiąt sześć tysięcy pięciuset.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 23, 'Synowie Issachara według swych rodzin to: Tola, od którego pochodzi rodzina Tolaitów, Puwwa, od którego rodzina Puwwitów;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 24, 'Jaszub, od którego rodzina Jaszubitów, Szimrona, od którego rodzina Szimronitów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 25, 'To są rodziny Issachara według ich spisu, sześćdziesiąt cztery tysiące trzystu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 26, 'Synowie Zebulona według swych rodzin to: Sered, od którego pochodzi rodzina Seredytów, Elon, od którego rodzina Elonitów, Jachleel, od którego rodzina Jachleelitów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 27, 'A to są rodziny Zebulonitów według ich spisu, sześćdziesiąt tysięcy pięciuset.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 28, 'Synowie Józefa według swych rodzin to Manasses i Efraim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 29, 'Synowie Manassesa to: Makir, od którego pochodzi rodzina Makirytów; a Makir spłodził Gileada, od Gileada pochodzi rodzina Gileadczyków;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 30, 'To są synowie Gileada: Jezer, od którego rodzina Jezerytów, Chelek, od którego rodzina Chelekitów;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 31, 'Asriel, od którego rodzina Asrielitów, Szechem, od którego rodzina Szechemitów;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 32, 'Szemida, od którego rodzina Szemidaitów, oraz Chefer, od którego rodzina Cheferytów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 33, 'A Selofchad, syn Chefera, nie miał synów, lecz tylko córki, a imiona córek Selofchada to: Machla, Noa, Chogla, Milka i Tirsa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 34, 'To są rodziny Manassesa według ich spisu, pięćdziesiąt dwa tysiące siedmiuset.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 35, 'To są synowie Efraima według swych rodzin: Szutelach, od którego pochodzi rodzina Szutelachitów, Becher, od którego rodzina Becherytów, Tachan, od którego rodzina Tachanitów;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 36, 'A to są synowie Szutelacha: Eran, od którego rodzina Eranitów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 37, 'To są rodziny synów Efraima według ich spisu: trzydzieści dwa tysiące pięciuset. To są synowie Józefa według swych rodzin.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 38, 'A synowie Beniamina według swych rodzin to: Bela, od którego pochodzi rodzina Belaitów, Aszbel, od którego rodzina Aszbelitów, Achiram, od którego rodzina Achiramitów;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 39, 'Szufam, od którego rodzina Szufamitów, Chufam, od którego rodzina Chufamitów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 40, 'Synowie Beli to Ard i Naaman, od Arda rodzina Ardytów, a od Naamana rodzina Naamitów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 41, 'To są synowie Beniamina według swych rodzin. Ich liczba wynosi czterdzieści pięć tysięcy sześciuset.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 42, 'To są synowie Dana według swych rodzin: Szucham, od którego pochodzi rodzina Szuchamitów. To są rodziny Dana według swych rodzin.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 43, 'Wszystkich rodzin Szuchamitów według ich spisu było sześćdziesiąt cztery tysiące czterystu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 44, 'Synowie Aszera według swych rodzin to: Jimna, od którego pochodzi rodzina Jimnaitów, Jiszwi, od którego rodzina Jiszwitów, Beria, od którego rodzina Beriaitów;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 45, 'Synowie Berii to: Cheber, od którego rodzina Cheberytów, Malkiel, od którego rodzina Malkielitów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 46, 'A córce Aszera było na imię Sarach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 47, 'To są rodziny synów Aszera według ich spisu: pięćdziesiąt trzy tysiące czterystu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 48, 'Synowie Neftalego według swych rodzin to: Jachseel, od którego pochodzi rodzina Jachseelitów, Guni, od którego rodzina Gunitów;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 49, 'Jeser, od którego rodzina Jeserytów, Szillem, od którego rodzina Szillemitów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 50, 'To są rodziny Neftalego według ich rodzin. Ich liczba wynosi czterdzieści pięć tysięcy czterystu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 51, 'To jest liczba synów Izraela: sześćset jeden tysięcy siedemset trzydziestu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 52, 'I Pan powiedział do Mojżesza:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 53, 'Pomiędzy nich zostanie podzielona ziemia jako dziedzictwo według liczby imion.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 54, 'Liczniejszemu dasz większe dziedzictwo, a mniej licznemu dasz mniejsze dziedzictwo. Każdemu będzie dane jego dziedzictwo według liczby policzonych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 55, 'Ziemia jednak będzie rozdzielona przez losowanie; otrzymają dziedzictwo według imion pokoleń swoich ojców.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 56, 'Zgodnie z losem będzie rozdzielone dziedzictwo pomiędzy liczne i nieliczne.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 57, 'Oto policzeni z Lewitów według swych rodzin: Gerszon, od którego pochodzi rodzina Gerszonitów, Kehat, od którego rodzina Kehatytów, Merari, od którego rodzina Meraritów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 58, 'To są rodziny Lewiego: rodzina Libnitów, rodzina Chebronitów, rodzina Machlitów, rodzina Muszitów, rodzina Korachitów; a Kehat spłodził Amrama.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 59, 'A żonie Amrama było na imię Jochebed, była to córka Lewiego, która mu się urodziła w Egipcie; to ona urodziła Amramowi Aarona i Mojżesza oraz ich siostrę Miriam.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 60, 'Aaronowi urodzili się Nadab i Abihu, Eleazar i Itamar.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 61, 'Ale Nadab i Abihu umarli, gdy ofiarowali inny ogień przed Panem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 62, 'A ich liczba wynosiła dwadzieścia trzy tysiące, wszystkich mężczyzn od miesiąca wzwyż; nie zostali jednak policzeni wśród synów Izraela, gdyż nie dano im dziedzictwa pośród synów Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 63, 'To są ci policzeni przez Mojżesza i kapłana Eleazara; oni policzyli synów Izraela na równinach Moabu, nad Jordanem, naprzeciw Jerycha.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 64, 'Lecz wśród nich nie było nikogo z tych policzonych przez Mojżesza i kapłana Aarona, gdy policzyli synów Izraela na pustyni Synaj;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 65, 'Pan bowiem powiedział o nich: Z pewnością umrą na pustyni. I nie pozostał żaden z nich oprócz Kaleba, syna Jefunnego, i Jozuego, syna Nuna.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 1, 'Wtedy przyszły córki Selofchada, syna Chefera, syna Gileada, syna Makira, syna Manassesa, z rodu Manassesa, syna Józefa; a to są imiona jego córek: Machla, Noa, Chogla, Milka i Tirsa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 2, 'I stanęły przed Mojżeszem, przed kapłanem Eleazarem, przed naczelnikami i całym zgromadzeniem u wejścia do Namiotu Zgromadzenia i powiedziały:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 3, 'Nasz ojciec umarł na pustyni, ale nie należał do zgrai tych, którzy zbuntowali się przeciw Panu w gromadzie Koracha. Umarł za własny grzech, a nie miał synów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 4, 'Dlaczego imię naszego ojca miałoby zniknąć z jego rodziny przez to, że nie miał syna? Dajcie nam posiadłość pośród braci naszego ojca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 5, 'Mojżesz przedstawił więc ich sprawę Panu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 6, 'I Pan powiedział do Mojżesza:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 7, 'Córki Selofchada słusznie mówią: Daj im koniecznie dziedziczną posiadłość pośród braci ich ojca, a przenieś na nie dziedzictwo ich ojca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 8, 'I przemów do synów Izraela tak: Jeśli ktoś umrze, a nie miał syna, wtedy przeniesiecie jego dziedzictwo na jego córkę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 9, 'A jeśli nie miał córki, to dacie jego dziedzictwo jego braciom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 10, 'A jeśli nie miał braci, to dacie jego dziedzictwo braciom jego ojca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 11, 'A jeśli jego ojciec nie miał braci, to dacie jego dziedzictwo najbliższemu krewnemu z jego rodziny, aby je odziedziczył. I będzie to dla synów Izraela ustawą prawną, jak Pan rozkazał Mojżeszowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 12, 'Potem Pan powiedział do Mojżesza: Wstąp na tę górę Abarim i spójrz na ziemię, którą dałem synom Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 13, 'A gdy ją zobaczysz, zostaniesz i ty przyłączony do swego ludu, jak został przyłączony twój brat Aaron.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 14, 'Dlatego że sprzeciwiliście się mojemu rozkazowi na pustyni Syn, podczas buntu zgromadzenia, i nie uświęciliście mnie na ich oczach u tych wód. To są wody Meriba w Kadesz, na pustyni Syn.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 15, 'Wtedy Mojżesz powiedział do Pana:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 16, 'Niech Pan, Bóg duchów wszelkiego ciała, ustanowi męża nad zgromadzeniem;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 17, 'Który będzie wychodził przed nim i który będzie wchodził przed nim, który będzie je wyprowadzał i który będzie je przyprowadzał, aby zgromadzenie Pana nie było jak owce, które nie mają pasterza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 18, 'Pan powiedział do Mojżesza: Weź do siebie Jozuego, syna Nuna, męża, w którym jest mój Duch, i połóż na nim swoją rękę;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 19, 'I postaw go przed kapłanem Eleazarem i przed całym zgromadzeniem, i na ich oczach daj mu polecenie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 20, 'I przenieś na niego część swojej godności, aby go słuchało całe zgromadzenie synów Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 21, 'Będzie on stawał przed kapłanem Eleazarem, aby ten za niego radził się przed Panem za pośrednictwem sądu Urim. Na jego rozkaz będą wychodzić i na jego rozkaz będą wchodzić – on, a z nim wszyscy synowie Izraela, całe zgromadzenie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 22, 'I Mojżesz uczynił tak, jak Pan mu rozkazał. Wziął Jozuego i postawił go przed kapłanem Eleazarem i przed całym zgromadzeniem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 23, 'Następnie położył na niego swoje ręce i dał mu polecenie, tak jak Pan nakazał przez Mojżesza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 1, 'I Pan powiedział do Mojżesza:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 2, 'Rozkaż synom Izraela i powiedz im: Przestrzegajcie składania mi w wyznaczonym czasie mojej ofiary, mojego pokarmu dla moich spalanych ofiar na miłą woń dla mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 3, 'I powiedz im: To jest ofiara spalana, którą będziecie składać Panu: dwa roczne baranki bez skazy codziennie, na nieustanne całopalenie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 4, 'Jednego baranka będziesz składać rankiem, a drugiego wieczorem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 5, 'Do tego na ofiarę pokarmową jedną dziesiątą efy mąki pszennej zmieszanej z jedną czwartą hinu wytłoczonej oliwy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 6, 'To jest nieustanne całopalenie, które ustalono na górze Synaj jako miłą woń, ofiarę spalaną dla Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 7, 'A jej ofiarą z płynów będzie jedna czwarta hinu na jednego baranka; ofiarę z płynów, z mocnego napoju, wylejesz w miejscu świętym dla Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 8, 'Drugiego baranka będziesz składał wieczorem; złożysz go podobnie jak poranną ofiarę pokarmową i ofiarę z płynów – jako ofiarę spalaną na miłą woń dla Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 9, 'Lecz w dniu szabatu złożysz dwa roczne baranki bez skazy i dwie dziesiąte efy mąki pszennej zmieszanej z oliwą na ofiarę z pokarmów wraz z jej ofiarą z płynów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 10, 'To jest całopalenie sobotnie w każdy szabat, oprócz nieustannego całopalenia i jego ofiary z płynów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 11, 'A na początku każdego waszego miesiąca będziecie składać Panu całopalenie: dwa młode cielce, jednego barana, siedem rocznych baranków bez skazy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 12, 'I trzy dziesiąte efy mąki pszennej zmieszanej z oliwą na ofiarę pokarmową na każdego cielca oraz dwie dziesiąte efy mąki pszennej zmieszanej z oliwą na ofiarę pokarmową na każdego barana;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 13, 'I jedną dziesiątą efy mąki pszennej zmieszanej z oliwą na ofiarę pokarmową na każdego baranka jako całopalenie na miłą woń, ofiarę spalaną dla Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 14, 'Ich ofiarami z płynów będą: pół hinu wina na każdego cielca, jedna trzecia hinu na każdego barana i jedna czwarta hinu na każdego baranka; to jest całopalenie na nowiu księżyca przez wszystkie miesiące roku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 15, 'Także jednego kozła ze stada jako ofiarę za grzech będziecie składać Panu oprócz nieustannego całopalenia oraz jego ofiary z płynów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 16, 'A pierwszego miesiąca, czternastego dnia, jest Pascha Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 17, 'A piętnastego dnia tego miesiąca jest uroczyste święto: przez siedem dni będziecie jeść przaśne chleby.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 18, 'Pierwszego dnia będzie święte zgromadzenie, nie będziecie wykonywać żadnej ciężkiej pracy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 19, 'Lecz złożycie Panu ofiarę spalaną na całopalenie: dwa młode cielce, jednego barana i siedem rocznych baranków. Mają być bez skazy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 20, 'A ich ofiara pokarmowa będzie z mąki pszennej zmieszanej z oliwą: będziecie składać trzy dziesiąte efy na każdego cielca, a dwie dziesiąte na każdego barana;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 21, 'Po jednej dziesiątej efy złożysz na każdego baranka z tych siedmiu baranków;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 22, 'I jednego kozła na ofiarę za grzech, na dokonanie przebłagania za was.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 23, 'Będziecie to wszystko składać oprócz porannego całopalenia, które jest nieustannym całopaleniem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 24, 'Tak każdego dnia przez te siedem dni będziecie składać pokarm ofiary spalanej na miłą woń dla Pana. Będziecie to składać oprócz nieustannego całopalenia i jego ofiary z płynów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 25, 'A siódmego dnia będziecie mieli święte zgromadzenie; nie będziecie wykonywać żadnej ciężkiej pracy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 26, 'A w dniu pierwocin, gdy będziecie składać Panu nową ofiarę pokarmową, gdy się wypełnią wasze tygodnie, będziecie mieli święte zgromadzenie; nie będziecie wykonywać żadnej ciężkiej pracy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 27, 'I złożycie Panu całopalenie na miłą woń: dwa młode cielce, jednego barana, siedem rocznych baranków.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 28, 'A na ich ofiarę pokarmową z mąki pszennej zmieszanej z oliwą: trzy dziesiąte efy na każdego cielca, dwie dziesiąte na każdego barana;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 29, 'Po jednej dziesiątej na każdego baranka z tych siedmiu baranków;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 30, 'I jednego kozła z kóz na dokonanie przebłagania za was.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 31, 'Będziecie to wszystko składać oprócz nieustannego całopalenia i jego ofiary pokarmowej, które mają być bez skazy, wraz z ich ofiarami z płynów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 1, 'Pierwszego dnia siódmego miesiąca będziecie mieli święte zgromadzenie; nie będziecie wykonywać żadnej ciężkiej pracy. Będzie to dla was dzień wesołego trąbienia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 2, 'I złożycie jako całopalenie, na miłą woń dla Pana, jednego młodego cielca, jednego barana oraz siedem rocznych baranków bez skazy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 3, 'A ich ofiarą pokarmową z mąki pszennej zmieszanej z oliwą będzie: trzy dziesiąte efy na cielca, dwie dziesiąte części na barana;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 4, 'I jedna dziesiąta na każdego baranka z tych siedmiu baranków;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 5, 'Oraz jednego kozła z kóz jako ofiarę za grzech, by dokonać za was przebłagania;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 6, 'Oprócz comiesięcznego całopalenia i jego ofiary pokarmowej, oprócz nieustannego całopalenia i jego ofiary pokarmowej oraz ich ofiar z płynów, zgodnie z ich przepisem, na miłą woń; będzie to ofiara spalana dla Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 7, 'Dziesiątego dnia tego siódmego miesiąca będziecie mieć święte zgromadzenie i będziecie trapić swoje dusze. Nie będziecie wykonywać żadnej ciężkiej pracy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 8, 'I złożycie Panu całopalenie, na miłą woń, jednego młodego cielca, jednego barana i siedem rocznych baranków. Mają być bez skazy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 9, 'A ich ofiarą pokarmową z mąki pszennej zmieszanej z oliwą będzie: trzy dziesiąte efy na cielca, dwie dziesiąte na barana;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 10, 'I jedna dziesiąta na każdego baranka z tych siedmiu baranków;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 11, 'Oraz jednego kozła z kóz na ofiarę za grzech oprócz ofiary za grzech na przebłaganie i oprócz nieustannego całopalenia i jego ofiary pokarmowej oraz ich ofiar z płynów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 12, 'A piętnastego dnia tego siódmego miesiąca będziecie mieć święte zgromadzenie. Nie będziecie wykonywać żadnej ciężkiej pracy, lecz będziecie obchodzić święto dla Pana przez siedem dni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 13, 'I złożycie całopalenie jako ofiarę spalaną, na miłą woń dla Pana, trzynaście młodych cielców, dwa barany i czternaście rocznych baranków. Mają być bez skazy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 14, 'A ich ofiarą pokarmową z mąki pszennej zmieszanej z oliwą będzie: trzy dziesiąte efy na każdego cielca z tych trzynastu cielców i dwie dziesiąte na każdego barana z tych dwóch baranów;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 15, 'I jedna dziesiąta na każdego baranka z tych czternastu baranków;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 16, 'Oraz jednego kozła z kóz na ofiarę za grzech oprócz nieustannego całopalenia, jego ofiary pokarmowej i jego ofiary z płynów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 17, 'A drugiego dnia złożycie dwanaście młodych cielców, dwa barany, czternaście rocznych baranków bez skazy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 18, 'I ich ofiarę pokarmową, i ich ofiary z płynów do każdego cielca, do każdego barana i do każdego baranka, według ich liczby i według ich przepisów;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 19, 'Oraz jednego kozła z kóz na ofiarę za grzech, oprócz nieustannego całopalenia, jego ofiary pokarmowej i ich ofiar z płynów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 20, 'A trzeciego dnia złożycie jedenaście cielców, dwa barany, czternaście rocznych baranków bez skazy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 21, 'I ich ofiarę pokarmową, i ich ofiary z płynów do każdego cielca, do każdego barana i do każdego baranka, według ich liczby i według ich przepisów;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 22, 'Oraz jednego kozła na ofiarę za grzech oprócz nieustannego całopalenia, jego ofiary pokarmowej i jego ofiary z płynów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 23, 'A czwartego dnia złożycie dziesięć cielców, dwa barany, czternaście rocznych baranków bez skazy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 24, 'Ich ofiarę pokarmową i ich ofiary z płynów do każdego cielca, do każdego barana i do każdego baranka, według ich liczby i według ich przepisów;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 25, 'Oraz jednego kozła z kóz na ofiarę za grzech oprócz nieustannego całopalenia, jego ofiary pokarmowej i jego ofiary z płynów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 26, 'A piątego dnia złożycie dziewięć cielców, dwa barany, czternaście rocznych baranków bez skazy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 27, 'I ich ofiarę pokarmową, i ich ofiary z płynów do każdego cielca, do każdego barana i do każdego baranka, według ich liczby i według ich przepisów;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 28, 'Oraz jednego kozła na ofiarę za grzech oprócz nieustannego całopalenia, jego ofiary pokarmowej i jego ofiary z płynów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 29, 'A szóstego dnia złożycie osiem cielców, dwa barany, czternaście rocznych baranków bez skazy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 30, 'I ich ofiarę pokarmową, i ich ofiary z płynów do każdego cielca, do każdego barana i do każdego baranka, według ich liczby i według ich przepisów;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 31, 'Oraz jednego kozła na ofiarę za grzech oprócz nieustannego całopalenia, jego ofiary pokarmowej i jego ofiar z płynów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 32, 'A siódmego dnia złożycie siedem cielców, dwa barany, czternaście rocznych baranków bez skazy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 33, 'I ich ofiarę pokarmową, i ich ofiary z płynów do każdego cielca, do każdego barana i do każdego baranka, według ich liczby i według ich przepisów;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 34, 'Oraz jednego kozła na ofiarę za grzech oprócz nieustannego całopalenia, jego ofiary pokarmowej i jego ofiary z płynów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 35, 'A ósmego dnia będziecie mieli uroczyste święto. Nie będziecie wykonywać żadnej ciężkiej pracy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 36, 'Złożycie całopalenie jako ofiarę spalaną, na miłą woń dla Pana, jednego cielca, jednego barana, siedem rocznych baranków bez skazy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 37, 'Ich ofiarę pokarmową i ich ofiary z płynów do cielca, do barana i do każdego baranka, według ich liczby i według ich przepisów;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 38, 'Oraz jednego kozła na ofiarę za grzech oprócz nieustannego całopalenia, jego ofiary pokarmowej i jego ofiary z płynów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 39, 'To wszystko będziecie składać Panu podczas waszych uroczystych świąt oprócz waszych ślubów i dobrowolnych ofiar na wasze całopalenia, na wasze ofiary pokarmowe, na wasze ofiary z płynów i na wasze ofiary pojednawcze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 40, 'I Mojżesz powiedział synom Izraela wszystko, co Pan mu rozkazał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 1, 'Potem Mojżesz powiedział do naczelników pokoleń pośród synów Izraela: Oto co Pan rozkazał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 2, 'Jeśli mężczyzna złoży Panu ślub lub przysięgę i zwiąże swoją duszę zobowiązaniem, to nie złamie swego słowa; wypełni wszystko według tego, co wyszło z jego ust.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 3, 'Jeśli kobieta złoży Panu ślub i zwiąże się zobowiązaniem w domu swego ojca, w swojej młodości;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 4, 'A jej ojciec usłyszy ślub i zobowiązanie, którym związała swoją duszę, a jej ojciec będzie milczał o tym, wtedy wszystkie jej śluby będą ważne i każde zobowiązanie, którym związała swą duszę, będzie ważne.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 5, 'Lecz jeśli jej ojciec sprzeciwi się jej w dniu, kiedy usłyszy o wszystkich jej ślubach i zobowiązaniach, którymi związała swoją duszę, wtedy nie będą ważne; Pan przebaczy jej, gdyż jej ojciec sprzeciwił się temu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 6, 'Ale jeśli mając męża, złożyła ślub lub wypowiedziała swymi ustami coś, czym związała swoją duszę;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 7, 'A jej mąż to usłyszał i milczał o tym w dniu, gdy to usłyszał, to jej śluby będą ważne i jej zobowiązania, którymi związała swoją duszę, będą ważne.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 8, 'Lecz jeśli w dniu, gdy jej mąż usłyszał o tym, sprzeciwił się temu, to unieważnia jej ślub, który złożyła, i to, co wypowiedziała swymi ustami, czym związała swoją duszę; a Pan jej przebaczy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 9, 'Ale każdy ślub wdowy i rozwiedzionej, którym związały swoją duszę, będzie ważny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 10, 'Lecz jeśli w domu swego męża złożyła ślub lub związała swoją duszę zobowiązaniem przysięgi;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 11, 'A jej mąż usłyszał to i milczał o tym, i nie sprzeciwił się temu, wtedy wszystkie jej śluby będą ważne i każdy obowiązek, którym zobowiązała swoją duszę, będzie ważny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 12, 'Ale jeśli jej mąż sprzeciwił się temu w dniu, kiedy to usłyszał, to wszelki ślub i zobowiązanie, jakie padły z jej ust, będą nieważne; jej mąż je unieważnił; a Pan jej przebaczy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 13, 'Wszelki ślub i wszelką przysięgę zobowiązania na trapienie duszy może jej mąż potwierdzić lub może unieważnić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 14, 'A jeśli jej mąż będzie milczał dzień po dniu, to potwierdza wszystkie jej śluby i wszystkie jej zobowiązania, które ją wiążą. Potwierdza je, ponieważ milczał o tym w dniu, kiedy je usłyszał;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 15, 'Lecz jeśli je usłyszał i dopiero później unieważni, to poniesie jej nieprawość.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 16, 'To są ustawy, które Pan przykazał Mojżeszowi, między mężem a jego żoną, między ojcem a jego córką w jej młodości, póki jest w domu swego ojca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 1, 'I Pan powiedział do Mojżesza:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 2, 'Pomścij krzywdy synów Izraela na Midianitach. Potem zostaniesz przyłączony do swego ludu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 3, 'Mojżesz powiedział więc do ludu: Przygotujcie spośród siebie mężczyzn do bitwy, aby wyruszyli przeciw Midianitom i dokonali na nich zemsty Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 4, 'Wyślecie na wojnę po tysiącu z każdego pokolenia, ze wszystkich pokoleń Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 5, 'I wyznaczono z tysięcy Izraela po tysiącu z każdego pokolenia, dwanaście tysięcy gotowych do walki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 6, 'I Mojżesz wysłał ich na wojnę po tysiącu z każdego pokolenia; posłał też z nimi Pinchasa, syna kapłana Eleazara, na wojnę, a w jego ręku były święte sprzęty i trąby sygnałowe.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 7, 'Wtedy walczyli z Midianitami, jak Pan rozkazał Mojżeszowi, i pozabijali wszystkich mężczyzn.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 8, 'Oprócz innych zabitych, zabili też królów Midianu: Ewiego, Rekema, Sura, Chura i Rebę – pięciu królów Midianu. Zabili też mieczem Balaama, syna Beora.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 9, 'Synowie Izraela wzięli do niewoli kobiety Midianu i ich dzieci; zabrali też całe ich bydło i trzody, i cały ich majątek;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 10, 'Spalili też ogniem wszystkie ich miasta, w których mieszkali, oraz wszystkie ich zamki;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 11, 'I zabrali cały łup oraz całą zdobycz zarówno z ludzi, jak i ze zwierząt;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 12, 'I przyprowadzili więźniów, zdobycz i łup do Mojżesza, do kapłana Eleazara i do zgromadzenia synów Izraela, do obozu na równinach Moabu, które są nad Jordanem, naprzeciw Jerycha.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 13, 'A Mojżesz, kapłan Eleazar i wszyscy naczelnicy zgromadzenia wyszli im naprzeciw poza obóz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 14, 'I Mojżesz bardzo się rozgniewał na dowódców wojska, tysiączników i setników, którzy wrócili z walki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 15, 'I mówił do nich Mojżesz: Czy zostawiliście przy życiu wszystkie kobiety?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 16, 'Oto one za radą Balaama spowodowały, że synowie Izraela dopuścili się przewinienia przeciwko Panu w związku z Peorem, a to sprowadziło plagę na zgromadzenie Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 17, 'Zabijcie więc teraz wszystkich chłopców spośród dzieci, zabijcie też każdą kobietę, która obcowała z mężczyzną;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 18, 'Lecz wszystkie dziewczyny, które nie obcowały z mężczyzną, zostawcie przy życiu dla siebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 19, 'A wy sami zostańcie przez siedem dni poza obozem. Każdy, kto zabił człowieka, i każdy, kto dotknął zabitego, niech się oczyści trzeciego i siódmego dnia, wy i wasi jeńcy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 20, 'Oczyśćcie również każdą szatę, wszelkie przedmioty skórzane i wszystko, co wykonano z koziej sierści, a także wszelkie drewniane przedmioty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 21, 'Potem kapłan Eleazar powiedział do wojowników, którzy wyruszyli na wojnę: Taka jest ustawa prawa, którą Pan nadał Mojżeszowi:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 22, 'Tylko złoto, srebro, miedź, żelazo, cynę i ołów;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 23, 'Wszystko, co może znieść ogień, przeprowadzicie przez ogień i będzie czyste; jednak najpierw będzie oczyszczone wodą oczyszczenia. Wszystko zaś, co nie może znieść ognia, oczyścicie wodą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 24, 'Siódmego dnia wypierzecie też swoje szaty i będziecie czyści, a potem wejdziecie do obozu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 25, 'Następnie Pan powiedział do Mojżesza:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 26, 'Razem z kapłanem Eleazarem i głowami spośród ojców zgromadzenia policz całą zdobycz uprowadzoną w ludziach i zwierzętach;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 27, 'I podziel zdobycz na dwie części: pomiędzy tych, którzy wyruszyli na wojnę, i pomiędzy całe zgromadzenie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 28, 'Od wojowników, którzy wyruszyli na wojnę, pobierz też daninę dla Pana, po jednym na pięćset, tak z ludzi, jak i wołów, osłów i owiec;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 29, 'Weź to z ich połowy i oddaj kapłanowi Eleazarowi na ofiarę wzniesienia dla Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 30, 'A z połowy synów Izraela weź po jednym z pięćdziesięciu z ludzi, wołów, osłów, owiec, słowem ze wszystkich zwierząt, i oddaj to Lewitom, którzy pełnią straż przy przybytku Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 31, 'I Mojżesz, i kapłan Eleazar uczynili tak, jak Pan rozkazał Mojżeszowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 32, 'A zdobycz z pozostałego łupu, który zdobyli wojownicy, wynosiła sześćset siedemdziesiąt pięć tysięcy owiec;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 33, 'Siedemdziesiąt dwa tysiące wołów;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 34, 'Sześćdziesiąt jeden tysięcy osłów;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 35, 'I trzydzieści dwa tysiące kobiet, które nie obcowały z mężczyzną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 36, 'Połowa przypadająca w udziale tym, którzy wyruszyli na wojnę, wynosiła trzysta trzydzieści siedem tysięcy pięćset owiec.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 37, 'Danina dla Pana z tych owiec wynosiła sześćset siedemdziesiąt pięć sztuk.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 38, 'Wołów było trzydzieści sześć tysięcy, a z tego danina dla Pana – siedemdziesiąt dwie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 39, 'Osłów było trzydzieści tysięcy pięćset, a z tego danina dla Pana – sześćdziesiąt jeden.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 40, 'Ludzi było szesnaście tysięcy, a z tego danina dla Pana – trzydzieści dwie osoby.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 41, 'I Mojżesz oddał kapłanowi Eleazarowi daninę na ofiarę wzniesienia dla Pana, tak jak Pan rozkazał Mojżeszowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 42, 'A z połowy należącej do synów Izraela, którą Mojżesz oddzielił od tych, którzy wyruszyli na wojnę;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 43, '(Połowa należąca do zgromadzenia wynosiła trzysta trzydzieści siedem tysięcy pięćset owiec;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 44, 'Trzydzieści sześć tysięcy wołów;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 45, 'Trzydzieści tysięcy pięćset osłów;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 46, 'I szesnaście tysięcy osób).');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 47, 'Z tej połowy należącej do synów Izraela Mojżesz wziął po jednym na pięćdziesiąt z ludzi i zwierząt, i dał to Lewitom pełniącym straż przy przybytku Pana, tak jak Pan rozkazał Mojżeszowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 48, 'Wtedy przyszli do Mojżesza dowódcy wojska, tysiącznicy i setnicy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 49, 'I powiedzieli do niego: My, twoi słudzy, policzyliśmy wojowników, którzy byli pod naszym dowództwem, i nie brakuje z nas ani jednego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 50, 'Dlatego przynieśliśmy na ofiarę dla Pana to, co każdy zdobył: złote przedmioty, łańcuszki, bransolety, pierścienie, kolczyki i naszyjniki, by dokonać przebłagania za nasze dusze przed Panem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 51, 'Mojżesz i kapłan Eleazar przyjęli więc od nich to złoto, wszystkie wykonane przedmioty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 52, 'A całego złota tej ofiary, którą oddali Panu, od tysiączników i setników, było szesnaście tysięcy siedemset pięćdziesiąt syklów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 53, 'Wojownicy bowiem zatrzymali łup, każdy dla siebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 54, 'Mojżesz i kapłan Eleazar przyjęli to złoto od tysiączników i setników i zanieśli do Namiotu Zgromadzenia jako pamiątkę synów Izraela przed Panem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 1, 'A synowie Rubena i synowie Gada mieli bardzo liczne stada. Gdy zobaczyli ziemię Jazer i ziemię Gilead, że jest to miejsce odpowiednie dla bydła;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 2, 'Przyszli ci synowie Gada i synowie Rubena i powiedzieli do Mojżesza, kapłana Eleazara oraz do naczelników zgromadzenia:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 3, 'Atarot, Dibon, Jazer, Nimra, Cheszbon, Eleale, Sebam, Nebo i Beon;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 4, 'Ziemia, którą Pan podbił przed zgromadzeniem Izraela, jest ziemią odpowiednią dla bydła, a twoi słudzy mają liczne bydło.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 5, 'Mówili dalej: Jeśli znaleźliśmy łaskę w twoich oczach, niech ta ziemia będzie dana twoim sługom w posiadanie, a nie przeprowadzaj nas za Jordan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 6, 'Wtedy Mojżesz odpowiedział synom Gada i synom Rubena: Czy wasi bracia pójdą na wojnę, a wy tu będziecie siedzieć?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 7, 'Dlaczego zniechęcacie serca synów Izraela, aby nie przeprawili się do ziemi, którą dał im Pan?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 8, 'Tak właśnie postępowali wasi ojcowie, gdy ich posłałem z Kadesz-Barnea, aby wyszpiegowali tę ziemię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 9, 'Kiedy dotarli aż do doliny Eszkol i zobaczyli ziemię, zniechęcili serca synów Izraela, aby nie weszli do ziemi, którą Pan im dał;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 10, 'Dlatego w tym dniu zapłonął gniew Pana i przysiągł:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 11, 'Na pewno nikt z tych ludzi, którzy wyszli z Egiptu, od dwudziestego roku życia wzwyż, nie ujrzy tej ziemi, którą przysiągłem Abrahamowi, Izaakowi i Jakubowi, ponieważ nie szli za mną w pełni;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 12, 'Oprócz Kaleba, syna Jefunnego, Kenizyty, i Jozuego, syna Nuna, ponieważ oni w pełni szli za Panem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 13, 'I zapłonął gniew Pana na Izraela, i sprawił, że tułali się po pustyni przez czterdzieści lat, aż wyginęło całe pokolenie, które czyniło źle w oczach Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 14, 'A oto powstaliście w miejsce waszych ojców jako plemię grzesznych ludzi, aby jeszcze bardziej wzmóc zapalczywość gniewu Pana przeciw Izraelowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 15, 'Jeśli bowiem odwrócicie się od kroczenia za nim, wtedy on znowu pozostawi ich na tej pustyni, a w ten sposób zgubicie cały ten lud.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 16, 'Wtedy zbliżyli się do niego i powiedzieli: Tu zbudujemy zagrody dla naszego bydła i miasta dla naszych dzieci;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 17, 'My zaś sami zbrojnie i ochoczo pójdziemy przed synami Izraela, aż zaprowadzimy ich na ich miejsce, a nasze dzieci będą mieszkały w miastach obwarowanych ze względu na mieszkańców tej ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 18, 'Nie wrócimy do swoich domów, dopóki każdy spośród synów Izraela nie otrzyma swojego dziedzictwa;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 19, 'Nie weźmiemy dziedzictwa razem z nimi po tamtej stronie Jordanu i dalej, ponieważ nasze dziedzictwo przypadło nam po tej stronie Jordanu, po stronie wschodniej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 20, 'Mojżesz powiedział im: Jeśli uczynicie to, co powiedzieliście, i uzbrojeni pójdziecie przed Panem na wojnę;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 21, 'I każdy z was zbrojnie przejdzie Jordan przed Panem, aż wypędzi swoich wrogów przed sobą;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 22, 'I ziemia zostanie podbita przed Panem, a potem wrócicie, to będziecie niewinni przed Panem i przed Izraelem; a ta ziemia będzie waszą posiadłością przed Panem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 23, 'Lecz jeśli nie uczynicie tego, oto zgrzeszycie przeciw Panu, a wiedzcie, że wasz grzech was znajdzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 24, 'Budujcie więc miasta dla waszych dzieci i zagrody dla waszych owiec; uczyńcie to, co wyszło z waszych ust.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 25, 'Wtedy synowie Gada i synowie Rubena powiedzieli do Mojżesza: Twoi słudzy uczynią tak, jak nasz pan rozkazuje.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 26, 'Nasze dzieci, nasze żony, nasze trzody i całe nasze bydło pozostaną tu, w miastach Gileadu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 27, 'Twoi słudzy natomiast, wszyscy uzbrojeni na wojnę, pójdą przed Panem, jak mówi nasz pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 28, 'I Mojżesz wydał rozkaz o nich kapłanowi Eleazarowi, Jozuemu, synowi Nuna, i naczelnikom spośród ojców pokoleń synów Izraela;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 29, 'Mojżesz powiedział im: Jeśli synowie Gada i synowie Rubena przejdą z wami za Jordan, wszyscy uzbrojeni do wojny przed Panem, a ziemia zostanie podbita przed wami, wtedy dacie im ziemię Gilead w posiadanie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 30, 'Lecz jeśli uzbrojeni nie przejdą z wami, wtedy otrzymają dziedzictwo pośród was w ziemi Kanaan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 31, 'Synowie Gada i synowie Rubena odpowiedzieli: Uczynimy to, co Pan powiedział do twoich sług;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 32, 'Pójdziemy uzbrojeni przed Panem do ziemi Kanaan, a posiadłość naszego dziedzictwa zostanie po tej stronie Jordanu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 33, 'Mojżesz dał wtedy synom Gada, synom Rubena i połowie pokolenia Manassesa, syna Józefa, królestwo Sichona, króla Amorytów, i królestwo Oga, króla Baszanu, ziemię z jej miastami i granicami, a także miasta tej ziemi dokoła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 34, 'I synowie Gada odbudowali Dibon, Atarot i Aroer;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 35, 'Atrot, Szofan, Jazer i Jogboha;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 36, 'Bet-Nimra, Bet-Haran, miasta warowne i zagrody dla stad.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 37, 'Synowie Rubena zaś odbudowali Cheszbon, Eleale i Kiriataim;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 38, 'Nebo, Baal-Meon, ich nazwy zmieniono, także Sybma; a miasta, które zbudowali, nazwali od swoich imion.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 39, 'Synowie Makira, syna Manassesa, poszli do Gileadu, zdobyli go i wypędzili Amorytów, którzy tam mieszkali.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 40, 'I Mojżesz dał Gilead Makirowi, synowi Manassesa, a ten w nim zamieszkał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 41, 'Potem Jair, syn Manassesa, poszedł i zdobył ich wsie, które nazwał Chawot-Jair.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 42, 'Także i Nobe poszedł i zdobył Kenat z jego wioskami, które nazwał Nobe, od swojego imienia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 1, 'Oto miejsca postojów synów Izraela, którzy wyszli z ziemi Egiptu ze swymi zastępami pod wodzą Mojżesza i Aarona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 2, 'Na rozkaz Pana Mojżesz spisał ich wymarsze według etapów. A oto ich wymarsze według etapów:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 3, 'Wyruszyli z Ramses w pierwszym miesiącu, piętnastego dnia tego pierwszego miesiąca; nazajutrz po święcie Paschy synowie Izraela wyszli pod potężną ręką na oczach wszystkich Egipcjan;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 4, 'Podczas gdy Egipcjanie grzebali wszystkich pierworodnych, których Pan zabił wśród nich. Także i nad ich bogami Pan dokonał sądu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 5, 'Wyruszyli więc synowie Izraela z Ramses i rozbili obóz w Sukkot.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 6, 'Wyruszyli z Sukkot i rozbili obóz w Etam, które leży na skraju pustyni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 7, 'Wyruszyli z Etam i wrócili do Pi-Hachirot, które leży naprzeciw Baal-Sefon, i rozbili obóz przed Migdol.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 8, 'Wyruszyli z Pi-Hachirot, przeszli przez środek morza na pustyni i po trzech dniach drogi po pustyni Etam rozbili obóz w Mara.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 9, 'Wyruszyli z Mara i przyszli do Elim. A w Elim było dwanaście źródeł wody i siedemdziesiąt palm i tam rozbili obóz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 10, 'Wyruszyli z Elim i rozbili obóz nad Morzem Czerwonym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 11, 'Wyruszyli znad Morza Czerwonego i rozbili obóz na pustyni Sin.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 12, 'Wyruszyli z pustyni Sin i rozbili obóz w Dofka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 13, 'Wyruszyli z Dofka i rozbili obóz w Alusz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 14, 'Wyruszyli z Alusz i rozbili obóz w Refidim, gdzie lud nie miał wody do picia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 15, 'Wyruszyli z Refidim i rozbili obóz na pustyni Synaj.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 16, 'Wyruszyli z pustyni Synaj i rozbili obóz w Kibrot-Hattaawa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 17, 'Wyruszyli z Kibrot-Hattaawa i rozbili obóz w Chaserot.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 18, 'Wyruszyli z Chaserot i rozbili obóz w Ritma.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 19, 'Wyruszyli z Ritma i rozbili obóz w Rimmon-Peres.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 20, 'Wyruszyli z Rimmon-Peres i rozbili obóz w Libnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 21, 'Wyruszyli z Libny i rozbili obóz w Rissa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 22, 'Wyruszyli z Rissa i rozbili obóz w Kehelata.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 23, 'Wyruszyli z Kehelata i rozbili obóz na górze Szefer.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 24, 'Wyruszyli z góry Szefer i rozbili obóz w Charada.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 25, 'Wyruszyli z Charada i rozbili obóz w Makhelot.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 26, 'Wyruszyli z Makhelot i rozbili obóz w Tachat.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 27, 'Wyruszyli z Tachat i rozbili obóz w Terach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 28, 'Wyruszyli z Terach i rozbili obóz w Mitka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 29, 'Wyruszyli z Mitka i rozbili obóz w Chaszmona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 30, 'Wyruszyli z Chaszmona i rozbili obóz w Moserot.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 31, 'Wyruszyli z Moserot i rozbili obóz w Bene-Jaakan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 32, 'Wyruszyli z Bene-Jaakan i rozbili obóz w Chor-Haggidgad.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 33, 'Wyruszyli z Chor-Haggidgad i rozbili obóz w Jotbata.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 34, 'Wyruszyli z Jotbata i rozbili obóz w Abrona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 35, 'Wyruszyli z Abrona i rozbili obóz w Esjon-Geber.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 36, 'Wyruszyli z Esjon-Geber i rozbili obóz na pustyni Syn, to jest w Kadesz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 37, 'Wyruszyli z Kadesz i rozbili obóz na górze Hor, na granicy ziemi Edomu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 38, 'Wtedy wstąpił kapłan Aaron na górę Hor na rozkaz Pana i tam umarł w czterdziestym roku po wyjściu synów Izraela z ziemi Egiptu, w pierwszym dniu piątego miesiąca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 39, 'Aaron miał sto dwadzieścia trzy lata, kiedy umarł na górze Hor.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 40, 'A król Aradu, Kananejczyk, który mieszkał na południu w ziemi Kanaan, usłyszał, że nadciągają synowie Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 41, 'Wyruszyli z góry Hor i rozbili obóz w Salmona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 42, 'Wyruszyli z Salmona i rozbili obóz w Punon.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 43, 'Wyruszyli z Punon i rozbili obóz w Obot.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 44, 'Wyruszyli z Obot i rozbili obóz w Ijje-Abarim, na granicy Moabu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 45, 'Wyruszyli z Ijjim i rozbili obóz w Dibon-Gad.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 46, 'Wyruszyli z Dibon-Gad i rozbili obóz w Almon-Diblataim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 47, 'Wyruszyli z Almon-Diblataim i rozbili obóz na górach Abarim, naprzeciwko Nebo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 48, 'Wyruszyli z gór Abarim i rozbili obóz na równinach Moabu, nad Jordanem, naprzeciw Jerycha.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 49, 'I rozłożyli się nad Jordanem, od Bet-Jeszimot aż do Abel-Szittim, na równinach Moabu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 50, 'I Pan przemówił do Mojżesza na równinach Moabu, nad Jordanem, naprzeciw Jerycha, tymi słowy:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 51, 'Przemów do synów Izraela i powiedz im: Gdy przeprawicie się przez Jordan do ziemi Kanaan;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 52, 'Wtedy wypędzicie przed sobą wszystkich mieszkańców tej ziemi i zniszczycie wszystkie ich obrazy i wszystkie ich odlane posągi i spustoszycie wszystkie ich wyżyny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 53, 'A wypędziwszy mieszkańców ziemi, zamieszkacie w niej, gdyż dałem wam tę ziemię w posiadanie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 54, 'I rozdzielicie tę ziemię przez losowanie jako dziedzictwo, według waszych rodzin. Liczniejszemu dacie większe dziedzictwo, a mniej licznemu dacie mniejsze dziedzictwo. Gdzie komu los przypadnie, to będzie jego; otrzymacie dziedzictwo według pokolenia waszych ojców.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 55, 'Jeśli jednak nie wypędzicie przed sobą mieszkańców tej ziemi, wtedy ci, których z nich pozostawicie, będą jak ciernie w waszych oczach i jak kolce dla waszych boków i będą was gnębić w tej ziemi, w której będziecie mieszkać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 56, 'Wtedy uczynię wam to, co zamierzałem uczynić im.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 1, 'Potem Pan powiedział do Mojżesza:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 2, 'Rozkaż synom Izraela i powiedz im: Gdy wejdziecie do ziemi Kanaan, to jest ziemia, która wam przypadnie jako dziedzictwo, ziemia Kanaan w swoich granicach;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 3, 'Wasza południowa granica będzie od pustyni Syn wzdłuż granic Edomu, a granica południowa pobiegnie od brzegu Morza Słonego, od wschodu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 4, 'Granica ta skręci od południa ku Maale-Akrabbim i pobiegnie aż do Syn, i dojdzie od południa do Kadesz-Barnea. Stamtąd pobiegnie do Chasar-Addar i przejdzie aż do Asmon.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 5, 'A ta granica skręci od Asmon aż do rzeki Egiptu, a skończy się przy morzu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 6, 'Jako zachodnią granicę będziecie mieli Morze Wielkie – ono będzie waszą zachodnią granicą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 7, 'A to będzie wasza północna granica: od Morza Wielkiego wymierzycie sobie do góry Hor.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 8, 'Potem od góry Hor wymierzycie granicę aż do wejścia do Hemat; a krańce tej granicy sięgną do Sedada.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 9, 'Następnie granica ta pobiegnie aż do Zifronu, a skończy się w Chasar-Enan. To będzie wasza północna granica.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 10, 'A wschodnią granicę wymierzycie od Chasar-Enan do Szefam.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 11, 'Granica ta pobiegnie od Szefam aż do Ribla, od wschodu Ain; i ta granica zejdzie w dół, i dosięgnie brzegu morza Kinneret od wschodu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 12, 'Następnie ta granica zejdzie ku Jordanowi, a zakończy się przy Morzu Słonym. To będzie wasza ziemia ze swymi granicami wokoło.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 13, 'Wtedy Mojżesz rozkazał synom Izraela: To jest ziemia, którą odziedziczycie przez losowanie, którą Pan rozkazał dać dziewięciu i pół pokoleniu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 14, 'Bo pokolenie synów Rubena według domów swych ojców i pokolenie synów Gada według domów swych ojców już otrzymały swoje dziedzictwo i połowa pokolenia Manassesa już otrzymała swoje dziedzictwo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 15, 'Te dwa i pół pokolenia otrzymały swoje dziedzictwo po tej stronie Jordanu, naprzeciw Jerycha, na wschodzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 16, 'I Pan powiedział do Mojżesza:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 17, 'Oto imiona mężczyzn, którzy rozdzielą wam ziemię: kapłan Eleazar i Jozue, syn Nuna.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 18, 'Weźmiecie też po jednym naczelniku z każdego pokolenia do rozdzielenia ziemi w dziedzictwo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 19, 'A oto imiona tych mężczyzn: z pokolenia Judy – Kaleb, syn Jefunnego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 20, 'Z pokolenia synów Symeona – Samuel, syn Ammihuda.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 21, 'Z pokolenia Beniamina – Eliad, syn Kislona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 22, 'Z pokolenia synów Dana – naczelnik Bukki, syn Jogliego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 23, 'Z synów Józefa, z pokolenia synów Manassesa – naczelnik Channiel, syn Efoda;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 24, 'A z pokolenia synów Efraima – naczelnik Kemuel, syn Sziftana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 25, 'Z pokolenia Zebulona – naczelnik Elisafan, syn Parnacha.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 26, 'Z pokolenia synów Issachara – naczelnik Paltiel, syn Azzana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 27, 'Z pokolenia synów Aszera – naczelnik Achihud, syn Szelomiego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 28, 'A z pokolenia synów Neftalego – naczelnik Pedahel, syn Ammihuda.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 29, 'To są ci, którym Pan rozkazał rozdzielić dziedzictwo synom Izraela w ziemi Kanaan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 1, 'I Pan powiedział do Mojżesza na równinach Moabu, nad Jordanem, naprzeciw Jerycha:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 2, 'Rozkaż synom Izraela, aby dali Lewitom ze swej dziedzicznej posiadłości miasta na zamieszkanie, dacie Lewitom też pastwiska dokoła ich miast.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 3, 'Będą mieli miasta na mieszkanie, a ich pastwiska będą dla ich bydła, dla ich dobytku i dla wszystkich ich zwierząt.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 4, 'Pastwiska miast, które dacie Lewitom, będą rozciągać się na tysiąc łokci wokół murów miasta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 5, 'Odmierzycie również poza miastem dwa tysiące łokci po stronie wschodniej, po stronie południowej też dwa tysiące łokci, także po stronie zachodniej dwa tysiące łokci i po stronie północnej dwa tysiące łokci, a miasto będzie w środku. To będą pastwiska ich miast.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 6, 'A spośród tych miast, które dacie Lewitom, sześć będzie miastami schronienia, które przekażecie, aby mógł tam uciec zabójca. Oprócz nich dacie im czterdzieści dwa miasta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 7, 'Wszystkich miast, które dacie Lewitom, będzie czterdzieści osiem wraz z ich pastwiskami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 8, 'A miasta, które im dacie, będą pochodziły z posiadłości synów Izraela; od liczniejszego dacie więcej, a od mniej licznego dacie mniej; każdy da Lewitom ze swoich miast stosownie do otrzymanego dziedzictwa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 9, 'Potem Pan powiedział do Mojżesza:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 10, 'Przemów do synów Izraela i powiedz im: Gdy przejdziecie przez Jordan do ziemi Kanaan;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 11, 'Wyznaczcie sobie miasta, które będą dla was miastami schronienia, aby mógł tam uciec zabójca, który zabił kogoś nieumyślnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 12, 'Te miasta będą dla was miastami schronienia przed mścicielem, aby zabójca nie poniósł śmierci, zanim nie stanie przed zgromadzeniem na sąd.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 13, 'A z miast, które oddacie, sześć będzie dla was miastami schronienia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 14, 'Trzy miasta dacie z tej strony Jordanu, a trzy miasta dacie w ziemi Kanaan; będą one miastami schronienia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 15, 'Tych sześć miast będzie schronieniem dla synów Izraela, dla obcego i dla przybysza, który mieszka wśród was, aby mógł tam uciec każdy, kto by zabił człowieka nieumyślnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 16, 'Jeśli jednak uderzy go przedmiotem żelaznym, tak że ten umrze, jest mordercą. Morderca poniesie śmierć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 17, 'Jeśli uderzy go kamieniem, który ma w ręce i którym można zabić, a ten umrze, jest mordercą. Morderca poniesie śmierć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 18, 'Albo jeśli uderzy go ręcznym przedmiotem drewnianym, którym można zabić, a ten umrze, jest mordercą. Morderca poniesie śmierć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 19, 'Mściciel krwi sam zabije tego mordercę. Gdziekolwiek go spotka, sam go zabije.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 20, 'Jeśli z nienawiści popchnie go albo rzuci w niego czymś z zasadzki, a ten umrze;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 21, 'Albo jeśli z wrogości uderzy go ręką, a ten umrze, to ten, który uderzył, poniesie śmierć, bo jest mordercą. Mściciel krwi zabije mordercę, gdziekolwiek go spotka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 22, 'Lecz jeśli niespodziewanie i bez wrogości go popchnie albo rzuci w niego czymkolwiek bez zasadzki;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 23, 'Albo jeśli nie widząc, upuści na niego jakiś kamień, którym można zabić, a ten umrze, chociaż nie był jego wrogiem ani nie szukał jego krzywdy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 24, 'Wtedy zgromadzenie rozsądzi pomiędzy tym, który zabił, a między mścicielem krwi według tych praw.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 25, 'I zgromadzenie wybawi zabójcę z rąk mściciela krwi; zgromadzenie też przekaże go miastu schronienia, do którego uciekł. Tam będzie mieszkał aż do śmierci najwyższego kapłana, namaszczonego olejem świętym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 26, 'Lecz jeśli zabójca wyjdzie poza granice swojego miasta schronienia, do którego uciekł;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 27, 'I mściciel trafi tam na niego poza granicą jego miasta schronienia, i zabije zabójcę, to nie będzie winien krwi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 28, 'Ten bowiem ma mieszkać w swoim mieście schronienia aż do śmierci najwyższego kapłana. Lecz po śmierci najwyższego kapłana zabójca może wrócić do ziemi swojej posiadłości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 29, 'To będzie dla was ustawa prawna przez wszystkie wasze pokolenia, we wszystkich waszych domach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 30, 'Ktokolwiek zabije człowieka, to na podstawie zeznania świadków zostanie zabity zabójca. Lecz jeden świadek nie może świadczyć przeciwko komuś, by skazać go na śmierć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 31, 'Nie weźmiecie też okupu za życie zabójcy, który zasługuje na śmierć. Musi ponieść śmierć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 32, 'Nie weźmiecie też okupu od tego, który uciekł do swojego miasta schronienia, aby mógł wrócić i zamieszkać w swojej ziemi, zanim umrze kapłan;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 33, 'Abyście nie bezcześcili ziemi, w której będziecie, gdyż krew bezcześci ziemię; a ziemia nie może być inaczej oczyszczona od przelanej w niej krwi jak tylko krwią tego, który ją przelał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 34, 'Nie zanieczyszczajcie więc ziemi, w której mieszkacie, w której przebywam też ja. Ja bowiem jestem Pan, który przebywa wśród synów Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 1, 'Wtedy przystąpili naczelnicy spośród ojców synów Gileada, syna Makira, syna Manassesa, z domów Józefa, i mówili przed Mojżeszem i przed książętami, naczelnikami ojców synów Izraela:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 2, 'Pan nakazał memu panu rozdzielić ziemię w dziedzictwo synom Izraela przez losowanie; mojemu panu rozkazano też przez Pana dać dziedzictwo naszego brata Selofchada jego córkom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 3, 'Jeśli więc któryś z synów innego pokolenia synów Izraela pojmie je za żony, to ich dziedzictwo zostanie odjęte od dziedzictwa naszych ojców i przyłączone do dziedzictwa pokolenia, do którego będą należeć; w ten sposób nasze dziedzictwo się zmniejszy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 4, 'A gdy nadejdzie rok jubileuszowy dla synów Izraela, wtedy ich dziedzictwo zostanie przyłączone do dziedzictwa pokolenia, do którego będą należeć; i tak ich dziedzictwo zostanie odjęte od dziedzictwa pokolenia naszych ojców.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 5, 'Wtedy Mojżesz rozkazał synom Izraela zgodnie ze słowem Pana: Słusznie mówi pokolenie synów Józefa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 6, 'Oto co Pan rozkazał w sprawie córek Selofchada: Niech wychodzą za mąż, za kogo chcą, ale mogą wyjść tylko za kogoś z domu pokolenia swoich ojców;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 7, 'Aby dziedzictwo synów Izraela nie było przenoszone z jednego pokolenia na drugie pokolenie. Każdy bowiem z synów Izraela ma pozostać przy dziedzictwie pokolenia swoich ojców.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 8, 'I każda córka, która posiada dziedzictwo w jakimś pokoleniu synów Izraela, wyjdzie za mąż za kogoś z domu pokolenia swego ojca, aby synowie Izraela dziedziczyli, każdy dziedzictwo swoich ojców.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 9, 'Dziedzictwo bowiem nie będzie przenoszone z jednego pokolenia na drugie pokolenie, lecz każde z pokoleń synów Izraela ma pozostać przy swoim dziedzictwie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 10, 'Jak Pan rozkazał Mojżeszowi, tak uczyniły córki Selofchada.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 11, 'Bo Machla, Tirsa, Chogla, Milka i Noa, córki Selofchada, wyszły za mąż za synów swoich stryjów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 12, 'Wyszły za mąż w rodzinach synów Manassesa, syna Józefa; w ten sposób ich dziedzictwo pozostało przy pokoleniu domu ich ojca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 13, 'To są przykazania i prawa, które Pan nakazał synom Izraela przez Mojżesza na równinach Moabu, nad Jordanem, naprzeciw Jerycha.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 1, 'Oto słowa, które Mojżesz wypowiedział do całego Izraela po tej stronie Jordanu na pustyni, na równinie, naprzeciw Morza Czerwonego, pomiędzy Faran, Tofel, Laban, Chaserot a Dizahab.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 2, 'A jedenaście dni drogi jest od Horebu przez górę Seir do Kadesz-Barnea.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 3, 'W czterdziestym roku, jedenastego miesiąca, pierwszego dnia tego miesiąca, Mojżesz powiedział synom Izraela to wszystko, co Pan mu dla nich rozkazał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 4, 'Gdy pobił Sichona, króla Amorytów, który mieszkał w Cheszbonie, i Oga, króla Baszanu, który mieszkał w Asztarot w Edrei;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 5, 'Po tej stronie Jordanu, w ziemi Moabu, Mojżesz zaczął objaśniać to prawo:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 6, 'Pan, nasz Bóg, przemówił do nas na Horebie: Dość długo przebywacie na tej górze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 7, 'Zawróćcie i wyruszcie, a idźcie w stronę góry Amorytów oraz do wszystkich miejsc leżących w jej pobliżu, na równinie, w górach i w dolinie, na południu i na wybrzeżu morza, do ziemi Kanaan i do Libanu, aż do wielkiej rzeki, rzeki Eufrat.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 8, 'Oto położyłem przed wami tę ziemię. Wejdźcie do niej i weźcie w posiadanie tę ziemię, którą Pan przysiągł dać waszym ojcom: Abrahamowi, Izaakowi i Jakubowi oraz ich potomstwu po nich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 9, 'I powiedziałem wam w tamtym czasie: Nie mogę już sam was nosić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 10, 'Pan, wasz Bóg, rozmnożył was, a oto jesteście dziś tak liczni jak gwiazdy na niebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 11, 'Niech Pan, Bóg waszych ojców, rozmnoży was jeszcze tysiąckroć i błogosławi wam, tak jak wam obiecał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 12, 'Jak mogę sam znosić troskę o was, wasz ciężar i wasze spory?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 13, 'Wybierzcie spośród siebie mężczyzn mądrych, rozumnych i doświadczonych w waszych pokoleniach, a ja ustanowię ich waszymi przywódcami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 14, 'Wtedy odpowiedzieliście mi: Dobra to rzecz, którą nakazałeś uczynić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 15, 'I wybrałem naczelników z waszych pokoleń, mężczyzn mądrych i doświadczonych, i ustanowiłem ich waszymi zwierzchnikami: przełożonymi nad tysiącami, nad setkami, nad pięćdziesięcioma i nad dziesięcioma oraz urzędnikami dla waszych pokoleń.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 16, 'I rozkazałem waszym sędziom w tym czasie: Wysłuchujcie spraw między waszymi braćmi i sądźcie sprawiedliwie pomiędzy każdym mężczyzną a jego bratem czy obcym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 17, 'Nie miejcie względu na osoby w sądzie; wysłuchujcie zarówno małego, jak i wielkiego. Nie bójcie się nikogo, ponieważ jest to sąd Boga. Jeśli sprawa będzie dla was zbyt trudna, przedstawcie ją mnie i ja jej wysłucham.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 18, 'I przykazałem wam w tamtym czasie wszystko, co macie czynić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 19, 'Potem wyruszyliśmy z Horebu i przeszliśmy przez całą tę wielką i straszną pustynię, którą widzieliście po drodze do góry Amorytów, jak nakazał nam Pan, nasz Bóg, i przyszliśmy aż do Kadesz-Barnea.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 20, 'I powiedziałem do was: Przyszliście do góry Amorytów, którą daje nam Pan, nasz Bóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 21, 'Oto Pan, twój Bóg, położył przed tobą tę ziemię. Idź i weź ją w posiadanie, jak ci powiedział Pan, Bóg twoich ojców; nie bój się i nie lękaj się.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 22, 'I przyszliście do mnie wszyscy, i tak powiedzieliście: Wyślijmy mężczyzn przed sobą, aby wyszpiegowali nam tę ziemię i zdali nam sprawę o drodze, którą mamy iść, i o miastach, do których mamy wejść.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 23, 'To mi się spodobało, więc wybrałem spośród was dwunastu mężczyzn, po jednym z każdego pokolenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 24, 'Oni zaś wyruszyli i weszli na górę, potem dotarli do doliny Eszkol i przebadali ziemię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 25, 'Zabrali też ze sobą owoc tej ziemi i przynieśli do nas, i zdając nam o tym sprawę, powiedzieli: Ziemia, którą daje nam Pan, nasz Bóg, jest dobra.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 26, 'Lecz nie chcieliście iść i buntowaliście się przeciw nakazowi Pana, swojego Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 27, 'I szemraliście w swoich namiotach, mówiąc: Z nienawiści do nas Pan wyprowadził nas z ziemi Egiptu, aby nas wydać w ręce Amorytów na naszą zgubę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 28, 'Dokąd pójdziemy? Nasi bracia napełnili nasze serca strachem, gdy mówili: Ten lud jest wyższy i roślejszy od nas, miasta są wielkie i obwarowane aż do nieba, a ponadto widzieliśmy tam synów Anakitów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 29, 'Wtedy mówiłem do was: Nie lękajcie się ani nie bójcie się ich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 30, 'Pan, wasz Bóg, który idzie przed wami, będzie walczyć za was, tak jak wam uczynił w Egipcie na waszych oczach;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 31, 'I na pustyni, gdzie widziałeś, jak Pan, twój Bóg, nosił cię tak, jak ojciec nosi swego syna, przez całą drogę, którą szliście, aż przybyliście na to miejsce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 32, 'Lecz mimo to nie uwierzyliście Panu, swojemu Bogu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 33, 'Który szedł przed wami w drodze, wypatrując dla was miejsca do rozbicia obozu, nocą w ogniu, aby wskazać wam drogę, którą macie iść, we dnie zaś w obłoku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 34, 'A Pan usłyszał głos waszych słów i bardzo się rozgniewał, i przysiągł tymi słowy:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 35, 'Żaden człowiek z tego złego pokolenia nie zobaczy tej dobrej ziemi, którą przysiągłem dać waszym ojcom;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 36, 'Oprócz Kaleba, syna Jefunnego; on ją zobaczy i jemu dam ziemię, którą stąpał, a także jego synom, gdyż chodził całkowicie za Panem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 37, 'Także na mnie rozgniewał się Pan z waszego powodu, mówiąc: Ty również tam nie wejdziesz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 38, 'Jozue, syn Nuna, który ci służy, on tam wejdzie. Umacniaj go, gdyż on ją poda w dziedzictwo Izraelowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 39, 'Także wasze dzieci, o których mówiliście, że staną się łupem, i wasi synowie, którzy w tym dniu nie odróżniali dobra od zła, oni tam wejdą i im ją oddam, a oni ją wezmą w posiadanie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 40, 'A wy zawróćcie i idźcie na pustynię drogą ku Morzu Czerwonemu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 41, 'Wtedy odpowiedzieliście mi: Zgrzeszyliśmy przeciwko Panu, pójdziemy i będziemy walczyć zgodnie z tym wszystkim, co nakazał nam Pan, nasz Bóg. I każdy z was przypasał sobie broń wojenną i chcieliście wejść na górę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 42, 'I Pan powiedział do mnie: Powiedz im: Nie wstępujcie ani nie walczcie, gdyż nie ma mnie wśród was, abyście nie byli pobici przez swoich wrogów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 43, 'Powiedziałem wam o tym, lecz nie słuchaliście, ale zbuntowaliście się przeciw nakazowi Pana i uparliście się, i weszliście na górę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 44, 'Wtedy Amoryci, którzy mieszkali na tej górze, wystąpili przeciwko wam i ścigali was, jak to czynią pszczoły, i pobili was w Seirze aż do Chorma.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 45, 'Potem wróciliście i płakaliście przed Panem; lecz Pan nie wysłuchał waszego głosu i nie nakłonił ku wam swego ucha.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 46, 'I mieszkaliście w Kadesz przez wiele dni, według liczby dni, ile tam mieszkaliście.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 1, 'Potem zawróciliśmy i wyruszyliśmy na pustynię, drogą w kierunku Morza Czerwonego, tak jak mi Pan powiedział, i przez wiele dni krążyliśmy dokoła góry Seir.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 2, 'I Pan powiedział do mnie:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 3, 'Dosyć krążyliście dokoła tej góry. Skierujcie się na północ;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 4, 'I rozkaż ludowi: Będziecie przechodzić przez granicę waszych braci, synów Ezawa, którzy mieszkają w Seirze. Oni będą się was bać, lecz wy strzeżcie się bardzo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 5, 'Nie prowokujcie ich, gdyż nie dam wam ich ziemi nawet na szerokość stopy, bo Ezawowi dałem w posiadanie górę Seir.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 6, 'Żywność będziecie kupowali od nich za pieniądze, abyście mieli co jeść; także wodę od nich będziecie kupować za pieniądze, abyście mieli co pić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 7, 'Gdyż Pan, twój Bóg, błogosławił cię w każdym dziele twoich rąk i znał twoją drogę na tej wielkiej pustyni. Już przez czterdzieści lat Pan, twój Bóg, był z tobą, a niczego ci nie brakowało.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 8, 'Ominęliśmy więc naszych braci, synów Ezawa, mieszkających w Seirze, drogą równinną od Elat i od Esjon-Geber, po czym skręciliśmy i udaliśmy się w stronę pustyni Moabu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 9, 'I Pan powiedział do mnie: Nie napadaj na Moabitów ani nie rozniecaj z nimi wojny, bo nie dam ci ich ziemi w posiadanie; Ar bowiem dałem w posiadanie synom Lota.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 10, 'Poprzednio mieszkali w niej Emici, lud potężny, liczny i wysoki jak Anakici;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 11, 'Uważano ich też za olbrzymów jak Anakitów, lecz Moabici nazywają ich Emitami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 12, 'Przedtem w Seirze mieszkali również Choryci, ale synowie Ezawa wypędzili ich i wyniszczyli przed sobą, po czym zamieszkali na ich miejscu, jak uczynił Izrael w ziemi swego posiadania, którą dał im Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 13, 'Wstańcie więc i przeprawcie się przez potok Zered. I przeprawiliśmy się przez potok Zered.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 14, 'A czas, który upłynął od naszego wyjścia z Kadesz-Barnea aż do przeprawienia się przez potok Zered, wynosił trzydzieści osiem lat, aż wyginęło z obozu całe pokolenie wojowników, tak jak im to Pan poprzysiągł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 15, 'Ręka Pana bowiem zaciążyła nad nimi, aby wyniszczyć ich z obozu, aż wyginęli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 16, 'A gdy wszyscy wojownicy spośród ludu wyginęli i umarli;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 17, 'Pan przemówił do mnie:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 18, 'Dziś przejdziesz przez Ar, granicę Moabu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 19, 'I zbliżysz się do synów Ammona; nie napadaj na nich i nie rozniecaj z nimi wojny, bo nie dam ci w posiadanie ziemi synów Ammona, dałem ją bowiem w posiadanie synom Lota.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 20, '(Także i tę ziemię uważano za ziemię olbrzymów. Olbrzymi mieszkali w niej wcześniej, a Ammonici nazywają ich Zamzummitami;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 21, 'Lud potężny, liczny i wysoki jak Anakici; lecz Pan wygubił ich przed nimi, a Ammonici ich wypędzili i zamieszkali na ich miejscu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 22, 'Podobnie jak uczynił synom Ezawa mieszkającym w Seirze, przed którymi wytracił Chorytów; i wypędzili ich, i zamieszkali na ich miejscu aż do dziś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 23, 'Także Awwitów, którzy mieszkali w Chazerim aż do Gazy, wytracili Kaftoryci, którzy wyszli z Kaftor, i zamieszkali na ich miejscu).');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 24, 'Wstańcie więc, wyruszcie i przeprawcie się przez rzekę Arnon. Oto daję w twoje ręce Sichona, króla Cheszbonu, Amorytę, oraz jego ziemię. Zacznij ją zajmować i rozpocznij z nim wojnę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 25, 'Od dziś zacznę wzbudzać strach i lęk przed tobą wśród narodów, które są pod całym niebem; kiedy usłyszą wieść o tobie, będą drżeć i będą się ciebie lękać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 26, 'Wysłałem więc posłańców z pustyni Kedemot do Sichona, króla Cheszbonu, ze słowami pokoju:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 27, 'Pozwól mi przejść przez twoją ziemię. Pójdę tylko drogą, nie zboczę ani na prawo, ani na lewo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 28, 'Sprzedasz mi za pieniądze żywność, abym mógł się pożywić; wody także za pieniądze mi dasz, abym pił. Tylko przejdę pieszo;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 29, 'Jak mi to uczynili synowie Ezawa, którzy mieszkają w Seirze, i Moabici, którzy mieszkają w Ar, aż się przeprawię przez Jordan, do ziemi, którą daje nam Pan, nasz Bóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 30, 'Lecz Sichon, król Cheszbonu, nie pozwolił nam przejść przez swoją ziemię, gdyż Pan, twój Bóg, zatwardził jego ducha i uczynił jego serce uparte, aby go wydać w twoje ręce, jak to dzisiaj widzisz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 31, 'Wtedy Pan powiedział do mnie: Oto zacząłem już wydawać ci Sichona i jego ziemię. Zacznij ją zajmować, abyś odziedziczył jego ziemię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 32, 'Wtedy Sichon wyruszył przeciwko nam, on i cały jego lud, aby zmierzyć się z nami w bitwie w Jahaz;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 33, 'Lecz Pan, nasz Bóg, wydał go nam i pobiliśmy go, jego synów i cały jego lud.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 34, 'I zdobyliśmy w tym czasie wszystkie jego miasta, i zniszczyliśmy doszczętnie we wszystkich miastach mężczyzn, kobiety i dzieci; nie pozostawiliśmy spośród nich nikogo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 35, 'Tylko bydło zagarnęliśmy dla siebie i łupy z miast, które zdobyliśmy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 36, 'Od Aroeru, leżącego nad brzegiem rzeki Arnon, i od miasta położonego w dolinie aż do Gileadu nie było miasta nie do zdobycia; wszystkie wydał nam Pan, nasz Bóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 37, 'Tylko do ziemi synów Ammona nie zbliżyłeś się, do żadnego miejsca na brzegu rzeki Jabbok ani do miast w górach, ani do żadnych miejsc, których Pan, nasz Bóg, nam zabronił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 1, 'Potem zawróciliśmy i poszliśmy drogą w kierunku Baszanu. I wyszedł nam naprzeciw Og, król Baszanu – on i cały jego lud – by stoczyć z nami bitwę w Edrei.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 2, 'Wtedy Pan powiedział do mnie: Nie bój się go, gdyż wydałem go w twoje ręce wraz z całym jego ludem i ziemią; uczynisz mu, jak uczyniłeś Sichonowi, królowi Amorytów, który mieszkał w Cheszbonie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 3, 'Pan, nasz Bóg, wydał więc w nasze ręce również Oga, króla Baszanu, i cały jego lud. Pobiliśmy go tak, że nikt po nim nie pozostał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 4, 'Zdobyliśmy w tym czasie wszystkie jego miasta; nie było miasta, którego im nie zabraliśmy: sześćdziesiąt miast, całą krainę Argob, królestwo Oga w Baszanie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 5, 'Wszystkie te miasta były obwarowane wysokimi murami, bramami i ryglami, a oprócz tego było bardzo wiele nieobwarowanych miasteczek.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 6, 'I spustoszyliśmy je, jak uczyniliśmy Sichonowi, królowi Cheszbonu, zniszczyliśmy we wszystkich miastach mężczyzn, kobiety i dzieci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 7, 'Lecz całe bydło i łupy z miast zgarnęliśmy dla siebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 8, 'W tym czasie wzięliśmy również z ręki dwóch królów Amorytów ziemię, która leży po tej stronie Jordanu, od rzeki Arnon aż do góry Hermon;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 9, '(Sydończycy nazywają Hermon Sirionem, a Amoryci – Sanirem).');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 10, 'Wszystkie miasta na równinie i cały Gilead oraz cały Baszan aż do Salka i Edrei, miasta królestwa Oga w Baszanie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 11, 'Gdyż tylko sam Og, król Baszanu, pozostał z olbrzymów; a jego łoże, łoże żelazne, czy nie znajduje się w Rabbie synów Ammona? Długie na dziewięć łokci, a szerokie na cztery łokcie, według łokcia męskiego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 12, 'A ziemię, którą wzięliśmy w posiadanie w tym czasie od Aroeru, który leży nad rzeką Arnon, i połowę góry Gilead oraz jej miasta dałem Rubenitom i Gadytom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 13, 'A resztę Gileadu i cały Baszan, królestwa Oga, dałem połowie pokolenia Manassesa: całą krainę Argob i cały Baszan nazwano ziemią olbrzymów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 14, 'Jair, syn Manassesa, posiadł całą krainę Argob aż do granicy Geszurytów i Machaty i nazwał ją od swego imienia Baszan-Chawot-Jair; nazywa się tak aż do dziś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 15, 'Makirowi zaś dałem Gilead.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 16, 'A Rubenitom i Gadytom dałem krainę od Gileadu aż do rzeki Arnon, ze środkiem rzeki jako granicą, aż do rzeki Jabbok, która jest granicą synów Ammona;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 17, 'Do tego równinę i Jordan z granicą od Kinneret aż do Morza Równinnego, czyli Morza Słonego, pod górą Pizga na wschodzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 18, 'W tym czasie rozkazałem wam: Pan, wasz Bóg, dał wam tę ziemię w posiadanie. Pójdziecie uzbrojeni przed waszymi braćmi, synami Izraela, wszyscy wojownicy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 19, 'Tylko wasze żony i dzieci oraz wasze bydło (gdyż wiem, że macie wiele stad) zostaną w waszych miastach, które wam dałem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 20, 'Aż Pan da odpoczynek waszym braciom, jak również wam, i aż oni posiądą ziemię, którą Pan, wasz Bóg, dał im za Jordanem. Wtedy każdy wróci do swojej posiadłości, którą wam dałem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 21, 'W tym czasie przykazałem też Jozuemu: Twoje oczy widziały wszystko, co Pan, wasz Bóg, uczynił tym dwom królom. Tak samo uczyni Pan wszystkim królestwom, do których pójdziesz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 22, 'Nie bójcie się ich, ponieważ sam Pan, wasz Bóg, walczy za was.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 23, 'I prosiłem Pana w tym czasie:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 24, 'Panie Boże, ty zacząłeś okazywać twemu słudze swoją wielkość i swoją potężną rękę; któryż bóg na niebie albo na ziemi potrafi czynić takie potężne dzieła jak ty?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 25, 'Pozwól mi, proszę, przejść i zobaczyć tę dobrą ziemię, która jest za Jordanem, tę dobrą górę i Liban.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 26, 'Lecz Pan rozgniewał się na mnie z waszego powodu i nie wysłuchał mnie. I Pan powiedział do mnie: Dosyć, nie mów już do mnie w tej sprawie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 27, 'Wejdź na szczyt góry Pizga i podnieś oczy na zachód, na północ, na południe i na wschód, i przypatrz się temu własnymi oczami, gdyż nie przejdziesz tego Jordanu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 28, 'Ale rozkaż Jozuemu, zachęć go i wzmocnij, gdyż on pójdzie przed tym ludem i on da mu w dziedzictwo ziemię, którą zobaczysz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 29, 'Mieszkaliśmy więc w dolinie naprzeciw Bet-Peor.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 1, 'Teraz więc, o Izraelu, słuchaj nakazów i praw, których uczę was wypełniać, abyście żyli i weszli, i posiedli ziemię, którą daje wam Pan, Bóg waszych ojców.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 2, 'Nie dodawajcie do słowa, które ja wam nakazuję, ani z niego nie ujmujcie, abyście przestrzegali przykazań Pana, waszego Boga, które ja wam nakazuję.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 3, 'Wasze oczy widziały, co Pan uczynił z powodu Baal-Peora, jak każdego człowieka, który poszedł za Baal-Peorem, Pan, twój Bóg, wytracił spośród was.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 4, 'A wy, którzy przylgnęliście do Pana, swojego Boga, żyjecie wszyscy aż do dziś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 5, 'Spójrzcie, nauczyłem was nakazów i praw, jak mi nakazał Pan, mój Bóg, abyście tak czynili w tej ziemi, do której wchodzicie, aby ją wziąć w posiadanie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 6, 'Przestrzegajcie ich więc i wypełniajcie je; to bowiem jest wasza mądrość i wasz rozum w oczach narodów, które usłyszą o wszystkich tych nakazach i powiedzą: Zaprawdę, ten wielki naród jest mądrym i rozumnym ludem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 7, 'Który bowiem naród jest tak wielki, by mieć bogów tak bliskich jak Pan, nasz Bóg, we wszystkim, ilekroć go wzywamy?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 8, 'Albo który naród jest tak wielki, by mieć nakazy i prawa tak sprawiedliwe jak całe to prawo, które dziś wam przedkładam?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 9, 'Tylko miej się na baczności i strzeż swej duszy pilnie, abyś nie zapomniał o tych rzeczach, które twoje oczy widziały, i aby nie odstępowały one od twego serca po wszystkie dni twego życia. Ale ucz ich swoich synów i synów swoich synów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 10, 'Nie zapominaj o dniu, w którym stałeś przed Panem, swoim Bogiem, na Horebie, gdy Pan powiedział do mnie: Zgromadź mi lud, abym im przekazał swoje słowa, aby nauczyli się mnie bać przez wszystkie dni swego życia na ziemi i żeby uczyli tego swoich synów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 11, 'Wtedy zbliżyliście się i stanęliście pod górą, a góra płonęła ogniem aż po samo niebo, okryta ciemnością, obłokiem i mrokiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 12, 'I Pan przemówił do was spośród ognia. Usłyszeliście dźwięk słów, lecz nie widzieliście żadnej postaci, tylko głos usłyszeliście.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 13, 'Wówczas oznajmił wam swoje przymierze, które nakazał wam wypełniać, dziesięć przykazań, które napisał na dwóch kamiennych tablicach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 14, 'W tym czasie Pan rozkazał mi nauczać was nakazów i praw, abyście je wypełniali w ziemi, do której idziecie, aby ją wziąć w posiadanie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 15, 'Strzeżcie więc pilnie swoich dusz, gdyż nie widzieliście żadnej postaci w dniu, w którym Pan przemówił do was na Horebie spośród ognia;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 16, 'Abyście się nie zepsuli i nie czynili sobie rzeźbionego posągu, podobizny wszelkiej postaci w kształcie mężczyzny lub kobiety;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 17, 'W kształcie jakiegokolwiek zwierzęcia, które jest na ziemi, w kształcie wszelkiego ptaka skrzydlatego, który lata w powietrzu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 18, 'W kształcie czegokolwiek, co pełza po ziemi, w kształcie wszelkiej ryby, która jest w wodach pod ziemią.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 19, 'I abyś – gdy podniesiesz swoje oczy ku niebu i ujrzysz słońce, księżyc i gwiazdy, cały zastęp niebios – nie dał się zwieść, by oddać im pokłon i im służyć, ponieważ Pan, twój Bóg, przydzielił je wszystkim ludom pod całym niebem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 20, 'Lecz Pan was wziął i wyprowadził z pieca do topienia żelaza, z Egiptu, abyście byli jego ludem, jego dziedzictwem, jak dziś jesteście.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 21, 'I Pan rozgniewał się na mnie z waszego powodu, i przysiągł, że nie przejdę Jordanu i nie wejdę do tej dobrej ziemi, którą Pan, twój Bóg, daje tobie w dziedzictwo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 22, 'Ja bowiem umrę w tej ziemi, nie przejdę Jordanu. Wy zaś przejdziecie i posiądziecie tę dobrą ziemię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 23, 'Strzeżcie się, abyście nie zapomnieli o przymierzu Pana, swojego Boga, które z wami zawarł, i nie czynili sobie żadnego rzeźbionego posągu lub podobizny czegokolwiek, czego ci zakazał Pan, twój Bóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 24, 'Bo Pan, twój Bóg, jest ogniem trawiącym, Bogiem zazdrosnym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 25, 'Gdy urodzisz synów i wnuki i zestarzejecie się w tej ziemi, jeśli popsujecie się i uczynicie sobie rzeźbiony posąg lub podobiznę czegokolwiek, i dopuścicie się zła w oczach Pana, swojego Boga, pobudzając go do gniewu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 26, 'To biorę dziś na świadków przeciwko wam niebo i ziemię, że prędko wyginiecie doszczętnie z ziemi, do której przejdziecie przez Jordan, aby ją posiąść; nie przedłużycie w niej swych dni, bo zostaniecie całkowicie wytępieni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 27, 'Pan rozproszy was między narodami i mało z was zostanie pośród narodów, do których Pan was zaprowadzi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 28, 'Tam będziecie służyli bogom, dziełom ludzkich rąk, drewnu i kamieniowi, które nie widzą ani nie słyszą, nie jedzą ani nie wąchają.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 29, 'Jeśli jednak stamtąd będziesz szukać Pana, swego Boga, wtedy znajdziesz go, jeśli będziesz go szukał całym swym sercem i całą swą duszą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 30, 'Gdy znajdziesz się w ucisku i spotka cię to wszystko w ostatnich dniach, jeśli wtedy zawrócisz do Pana, swego Boga, i będziesz słuchał jego głosu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 31, 'Ponieważ Pan, twój Bóg, jest miłosiernym Bogiem, nie opuści cię ani cię nie zniszczy, ani nie zapomni o przymierzu z twoimi ojcami, które im poprzysiągł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 32, 'Zapytaj się bowiem dawnych czasów, które były przed tobą od dnia, kiedy Bóg stworzył człowieka na ziemi, i od jednego krańca nieba aż do drugiego, czy stała się kiedykolwiek rzecz podobna do tej tak wielkiej albo czy słyszano kiedykolwiek o czymś takim?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 33, 'Czy słyszał kiedykolwiek jakiś naród głos Boga mówiącego spośród ognia, tak jak ty słyszałeś, i pozostał żywy?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 34, 'Albo czy Bóg spróbował przyjść i wziąć sobie naród spośród innego narodu przez doświadczenia, przez znaki, przez cuda i przez wojny, potężną ręką i wyciągniętym ramieniem, wśród wielkich i strachliwych dzieł jak to wszystko, co na twoich oczach Pan, wasz Bóg, uczynił dla was w Egipcie?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 35, 'Tobie to ukazano, abyś wiedział, że Pan jest Bogiem i nie ma innego oprócz niego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 36, 'Dał ci słyszeć swój głos z nieba, aby cię pouczyć, a na ziemi ukazał ci swój wielki ogień i usłyszałeś jego słowa spośród ognia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 37, 'A ponieważ umiłował twoich ojców, wybrał ich potomstwo po nich i wyprowadził cię z Egiptu przed sobą swoją wielką mocą;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 38, 'Aby wypędzić przed tobą narody większe i potężniejsze od ciebie, by cię wprowadzić i dać ci ich ziemię w dziedzictwo, jak to jest dzisiaj.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 39, 'Poznaj więc dziś i weź to sobie do swego serca, że Pan jest Bogiem wysoko na niebie i nisko na ziemi. Nie ma innego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 40, 'Przestrzegaj więc jego nakazów i przykazań, które dziś tobie nakładam, aby się dobrze powodziło tobie i twoim synom po tobie; abyś też przedłużył swe dni na ziemi, którą Pan, twój Bóg, daje tobie przez wszystkie dni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 41, 'Wtedy Mojżesz wydzielił trzy miasta po tej stronie Jordanu na wschodzie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 42, 'Aby mógł tam uciec zabójca, który zabił swego bliźniego nieumyślnie i wcześniej nie nienawidził go, aby uciekł on do jednego z tych miast i pozostał żywy:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 43, 'Beser na pustyni, w ziemi równinnej Rubenitów, Ramot w Gileadzie Gadytów i Golan w Baszanie Manassytów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 44, 'Oto prawo, które Mojżesz przedłożył synom Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 45, 'To są świadectwa, nakazy i prawa, które Mojżesz ogłosił synom Izraela, kiedy wyszli z Egiptu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 46, 'Po tej stronie Jordanu, w dolinie naprzeciw Bet-Peor, w ziemi Sichona, króla Amorytów, mieszkającego w Cheszbonie, którego Mojżesz i synowie Izraela pobili po wyjściu z Egiptu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 47, 'I posiedli jego ziemię i ziemię Oga, króla Baszanu – dwóch królów Amorytów, którzy byli po tej stronie Jordanu na wschodzie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 48, 'Od Aroeru, leżącego nad brzegiem rzeki Arnon, aż do góry Sirion, czyli Hermon;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 49, 'I całą równinę po tej stronie Jordanu na wschodzie aż do Morza Pustego, pod zdrojami Pizga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 1, 'I Mojżesz zwołał całego Izraela, i powiedział do nich: Słuchaj, Izraelu, nakazów i praw, które dziś mówię do twoich uszu; nauczcie się ich i przestrzegajcie, i wypełniajcie je.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 2, 'Pan, nasz Bóg, zawarł z nami przymierze na Horebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 3, 'Pan zawarł to przymierze nie z naszymi ojcami, ale z nami, którzy tu wszyscy dziś jesteśmy przy życiu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 4, 'Twarzą w twarz rozmawiał z wami Pan na górze spośród ognia;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 5, 'Ja stałem w tym czasie pomiędzy Panem a wami, aby oznajmić wam słowo Pana, gdyż baliście się ognia i nie wstąpiliście na górę. A on powiedział:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 6, 'Ja jestem Pan, twój Bóg, który cię wyprowadził z ziemi Egiptu, z domu niewoli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 7, 'Nie będziesz miał innych bogów przede mną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 8, 'Nie czyń sobie rzeźbionego posągu ani żadnej podobizny czegokolwiek, co jest w górze na niebie, co jest nisko na ziemi ani tego, co jest w wodach pod ziemią;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 9, 'Nie będziesz oddawał im pokłonu ani nie będziesz im służył, gdyż ja jestem Pan, twój Bóg, Bóg zazdrosny, nawiedzający nieprawość ojców na synach do trzeciego i czwartego pokolenia tych, którzy mnie nienawidzą;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 10, 'A okazujący miłosierdzie tysiącom tych, którzy mnie miłują i strzegą moich przykazań.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 11, 'Nie będziesz brał imienia Pana, twego Boga, nadaremnie, gdyż Pan nie zostawi bez kary tego, który bierze jego imię nadaremnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 12, 'Przestrzegaj dnia szabatu, abyś go święcił, tak jak ci nakazał Pan, twój Bóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 13, 'Przez sześć dni będziesz pracował i wykonywał wszelką swoją pracę;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 14, 'Lecz siódmy dzień jest szabatem Pana, twego Boga. Nie będziesz wykonywał żadnej pracy w tym dniu ani ty, ani twój syn, ani twoja córka, ani twój sługa, ani twoja służąca, ani twój wół, ani twój osioł, ani żadne twoje bydło, ani twój gość, który jest w twych bramach; aby odpoczął twój sługa i twoja służąca – jak i ty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 15, 'I pamiętaj, że byłeś niewolnikiem w ziemi Egiptu i że Pan, twój Bóg, wyprowadził cię stamtąd potężną ręką i wyciągniętym ramieniem. Dlatego Pan, twój Bóg, nakazał ci obchodzić dzień szabatu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 16, 'Czcij swego ojca i swoją matkę, tak jak nakazał ci Pan, twój Bóg, aby przedłużone były twoje dni i żeby ci się dobrze powodziło na ziemi, którą Pan, twój Bóg, da tobie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 17, 'Nie będziesz zabijał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 18, 'Nie będziesz cudzołożył.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 19, 'Nie będziesz kradł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 20, 'Nie będziesz mówił fałszywego świadectwa przeciw twemu bliźniemu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 21, 'Nie będziesz pragnął żony swego bliźniego ani nie będziesz pożądał domu swego bliźniego, ani jego pola, ani jego sługi czy służącej, ani jego wołu czy osła, ani żadnej rzeczy, która należy do twego bliźniego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 22, 'Te słowa wypowiedział Pan do całego waszego zgromadzenia na górze spośród ognia, obłoku i ciemności donośnym głosem. I nic nie dodał. Potem napisał je na dwóch tablicach kamiennych i dał mi je.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 23, 'A gdy usłyszeliście głos spośród ciemności, a góra płonęła ogniem, zbliżyliście się do mnie, wszyscy naczelnicy waszych pokoleń oraz starsi;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 24, 'I powiedzieliście: Oto Pan, nasz Bóg, ukazał nam swoją chwałę i wielkość i słyszeliśmy jego głos spośród ognia. Dziś widzieliśmy, że Bóg przemawia do człowieka, a ten pozostaje przy życiu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 25, 'Dlaczego więc teraz mamy umrzeć? Bo ten wielki ogień nas pochłonie. Jeśli nadal będziemy słyszeć głos Pana, naszego Boga, pomrzemy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 26, 'Któż bowiem spośród wszelkiego ciała słyszał głos Boga żywego mówiącego spośród ognia, tak jak my, a pozostał przy życiu?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 27, 'Zbliż się ty i wysłuchaj wszystkiego, co będzie mówił Pan, nasz Bóg. Ty zaś powiesz nam wszystko, co powie do ciebie Pan, nasz Bóg, a my posłuchamy i wykonamy to.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 28, 'I Pan wysłuchał głosu waszych słów, kiedy mówiliście do mnie, i powiedział Pan do mnie: Słyszałem głos słów tego ludu, które wypowiedzieli do ciebie. Wszystko, co powiedzieli, jest słuszne.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 29, 'Oby ich serce było takie, by się mnie bali i przestrzegali wszystkich moich przykazań przez wszystkie dni, aby dobrze się powodziło im i ich synom na wieki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 30, 'Idź i powiedz im: Wróćcie do swoich namiotów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 31, 'A ty zostań tu przy mnie, a powiem ci wszystkie przykazania, nakazy i prawa, których będziesz ich nauczał, aby je wypełniali w ziemi, którą daję im w posiadanie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 32, 'Dopilnujcie wypełniania tego tak, jak wam nakazał Pan, wasz Bóg. Nie zbaczajcie ani w prawo, ani w lewo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 33, 'Będziecie chodzić wszelką drogą, którą wam nakazał Pan, wasz Bóg, abyście żyli, aby dobrze się wam powodziło i żebyście przedłużyli swoje dni na ziemi, którą posiądziecie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 1, 'A oto przykazania, nakazy i prawa, których Pan, wasz Bóg, nakazał was nauczyć, żebyście je wypełniali w ziemi, do której idziecie, by ją posiąść;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 2, 'Ażebyś bał się Pana, swego Boga, tak byś przestrzegał wszystkich jego nakazów i przykazań, które tobie nakazuję, tobie, twojemu synowi i synowi twego syna, po wszystkie dni twego życia, i aby twoje dni się przedłużyły.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 3, 'Słuchaj więc, Izraelu, i pilnuj wypełniania tego, aby dobrze ci się powodziło i żebyście się bardzo rozmnożyli, tak jak obiecał ci Pan, Bóg twoich ojców, w ziemi opływającej mlekiem i miodem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 4, 'Słuchaj, Izraelu! Pan, nasz Bóg, Pan jest jeden.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 5, 'Będziesz miłował Pana, swego Boga, całym swym sercem, całą swą duszą i z całej swej siły;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 6, 'A te słowa, które ja dziś nakazuję tobie, będą w twoim sercu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 7, 'I będziesz je często przypominał swoim synom i rozmawiał o nich, przebywając w swoim domu, idąc drogą, kładąc się i wstając.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 8, 'Przywiążesz je jako znak do swoich rąk i będą jako przepaski między twymi oczami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 9, 'Wypiszesz je też na odrzwiach swego domu i na swoich bramach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 10, 'A gdy Pan, twój Bóg, wprowadzi cię do ziemi, którą poprzysiągł twoim ojcom: Abrahamowi, Izaakowi i Jakubowi, że da tobie miasta wielkie i dobre, których nie budowałeś;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 11, 'I wypełnione dobrami domy, których nie napełniałeś, i wykute studnie, których nie wykuwałeś, winnice i ogrody oliwne, których nie sadziłeś; gdy więc będziesz jadł do syta;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 12, 'Strzeż się, abyś nie zapomniał Pana, który cię wyprowadził z ziemi Egiptu, z domu niewoli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 13, 'Będziesz się bał Pana, swego Boga, i będziesz mu służyć, i na jego imię przysięgać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 14, 'Nie pójdziecie za obcymi bogami, za bogami narodów, które są dokoła was;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 15, '(Pan bowiem, twój Bóg, znajdujący się pośród ciebie, jest Bogiem zazdrosnym), by nie rozpalił się gniew Pana, twego Boga, przeciw tobie i aby nie wytępił cię z powierzchni ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 16, 'Nie będziecie wystawiać na próbę Pana, swojego Boga, tak jak go wystawialiście na próbę w Massa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 17, 'Będziecie pilnie przestrzegać przykazań Pana, swojego Boga, jego świadectw i nakazów, które ci nakazał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 18, 'A czyń to, co jest prawe i dobre w oczach Pana, aby ci się dobrze powodziło, abyś wszedł i posiadł tę dobrą ziemię, którą Pan przysiągł twoim ojcom;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 19, 'Aby wypędzić przed tobą wszystkich twoich wrogów, jak to Pan powiedział.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 20, 'A gdy twój syn zapyta cię kiedyś: Co to za świadectwa, nakazy i prawa, które wam nakazał Pan, nasz Bóg?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 21, 'Wtedy powiesz swemu synowi: Byliśmy niewolnikami faraona w Egipcie i Pan wyprowadził nas z Egiptu potężną ręką.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 22, 'I na naszych oczach Pan czynił w Egipcie znaki i cuda, wielkie i dotkliwe, nad faraonem i nad całym jego domem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 23, 'Lecz wyprowadził nas stamtąd, aby nas wprowadzić i dać nam tę ziemię, którą przysiągł naszym ojcom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 24, 'I Pan nakazał nam wypełniać wszystkie te nakazy i bać się Pana, naszego Boga, żeby nam się dobrze powodziło po wszystkie dni, aby nas zachować przy życiu, tak jak dziś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 25, 'I będzie to nasza sprawiedliwość, gdy będziemy przestrzegać wszystkich tych przykazań i wypełniać je przed Panem, naszym Bogiem, tak jak nam nakazał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 1, 'Gdy Pan, twój Bóg, wprowadzi cię do ziemi, do której wchodzisz, by ją posiąść, i gdy wypędzi przed tobą wiele narodów: Chetytów, Girgaszytów, Amorytów, Kananejczyków, Peryzzytów, Chiwwitów i Jebusytów – siedem narodów liczniejszych i potężniejszych niż ty;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 2, 'Gdy więc Pan, twój Bóg, wyda je tobie, wytępisz je, doszczętnie je wyniszczysz, nie zawrzesz z nimi przymierza i nie zlitujesz się nad nimi;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 3, 'Nie będziesz z nimi zawierał małżeństw: swej córki nie dasz ich synowi i ich córki nie weźmiesz dla swego syna;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 4, 'Gdyż odwiodłaby twego syna od kroczenia za mną, by służyli innym bogom. Wtedy rozpaliłby się gniew Pana na was i prędko by was wytępił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 5, 'Lecz tak z nimi postąpicie: Zburzycie ich ołtarze, pokruszycie ich pomniki, wytniecie ich gaje i spalicie ogniem ich rzeźbione posągi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 6, 'Ty bowiem jesteś świętym ludem dla Pana, swego Boga: Pan, twój Bóg, wybrał cię, abyś był dla niego szczególnym ludem spośród wszystkich narodów, które są na ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 7, 'Pan umiłował was i wybrał was nie dlatego, że byliście liczniejsi od innych narodów, gdyż byliście najmniej liczni ze wszystkich narodów;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 8, 'Lecz ponieważ Pan was umiłował i chciał dochować przysięgi, którą złożył waszym ojcom, Pan wyprowadził was potężną ręką i wykupił was z domu niewoli, z ręki faraona, króla Egiptu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 9, 'Uznaj więc, że Pan, twój Bóg, jest Bogiem, Bogiem wiernym, który zachowuje przymierze i miłosierdzie do tysiącznego pokolenia względem tych, którzy go miłują i przestrzegają jego przykazań;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 10, 'A odpłaca w twarz tym, którzy go nienawidzą, aby ich zniszczyć. Nie zwleka z karą dla tego, który go nienawidzi; odpłaci mu w twarz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 11, 'Przestrzegaj więc przykazań, nakazów i praw, które ja dziś nakazuję ci wypełnić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 12, 'Jeśli będziecie słuchać tych praw, przestrzegać ich i wypełniać je, wtedy Pan, twój Bóg, dochowa ci przymierza i miłosierdzia, które poprzysiągł twoim ojcom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 13, 'I będzie cię miłował, błogosławił ci i rozmnoży cię. I pobłogosławi owoc twego łona i owoc twojej ziemi: twoje zboże, twoje wino i twoją oliwę, przyrost twoich krów i trzody twoich owiec na ziemi, którą poprzysiągł twoim ojcom dać tobie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 14, 'Będziesz błogosławiony ponad wszystkie narody. Nie będzie niepłodnego i niepłodnej ani wśród ciebie, ani wśród twego bydła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 15, 'Pan oddali też od ciebie każdą chorobę i nie ześle na ciebie żadnych dotkliwych chorób Egiptu, które poznałeś, lecz ześle je na wszystkich, którzy cię nienawidzą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 16, 'I wytępisz wszystkie narody, które Pan, twój Bóg, tobie wyda; nie zlituje się nad nimi twoje oko. I nie będziesz służył ich bogom, bo byłoby to dla ciebie sidłem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 17, 'Jeśli powiesz w swym sercu: Te narody są liczniejsze ode mnie, jakże będę mógł je wypędzić?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 18, 'Nie bój się ich, ale dobrze pamiętaj to, co Pan, twój Bóg, uczynił faraonowi i całemu Egiptowi;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 19, 'Te wielkie doświadczenia, które twoje oczy widziały, te znaki, cuda, potężną rękę i wyciągnięte ramię, którymi Pan, twój Bóg, cię wyprowadził. Tak uczyni Pan, twój Bóg, wszystkim narodom, których się boisz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 20, 'Ponadto Pan, twój Bóg, ześle na nich szerszenie, aż wyginą ci, którzy pozostali, i ci, którzy ukryli się przed tobą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 21, 'Nie drżyj przed nimi, gdyż Pan, twój Bóg, jest pośród ciebie, Bóg wielki i straszliwy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 22, 'I Pan, twój Bóg, wypędzi przed tobą te narody z wolna i po trosze: Nie będziesz mógł wytępić ich szybko, aby nie rozmnożyły się przeciw tobie zwierzęta polne.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 23, 'Lecz Pan, twój Bóg, wyda je tobie i porazi je wielką klęską, aż będą wyniszczone.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 24, 'I wyda ich królów w twoje ręce i zgładzisz ich imię spod nieba. Nikt nie ostoi się przed tobą, aż ich wytępisz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 25, 'Rzeźbione posągi ich bogów spalisz w ogniu. Nie będziesz pożądał srebra ani złota, które jest na nich, ani nie będziesz brał go dla siebie, byś nie został przez nie usidlony, ponieważ to budzi odrazę u Pana, twego Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 26, 'Nie wnoś takiej obrzydliwości do swego domu, abyś się nie stał przekleństwem tak jak i ona. Będziesz się nią bardzo brzydził i czuł do niej ogromny wstręt, gdyż to jest przekleństwo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 1, 'Wszystkich przykazań, które ci dziś nakazuję, będziecie przestrzegać i wypełniać je, abyście żyli, rozmnażali się, weszli i posiedli ziemię, którą Pan przysiągł waszym ojcom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 2, 'Pamiętaj całą drogę, którą prowadził cię Pan, twój Bóg, przez te czterdzieści lat po pustyni, by cię ukorzyć i doświadczać, aby poznać, co jest w twoim sercu, czy będziesz przestrzegał jego przykazań, czy nie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 3, 'Upokorzył cię, dawał ci odczuć głód i karmił cię manną, której nie znałeś ani ty, ani twoi ojcowie, aby cię nauczyć, że nie samym chlebem człowiek żyje, ale że człowiek żyje każdym słowem, które wychodzi z ust Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 4, 'Twoja odzież nie zniszczyła się na tobie i twoja noga nie opuchła przez te czterdzieści lat.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 5, 'Rozważ więc w swym sercu, że jak człowiek karze swego syna, tak Pan, twój Bóg, karze ciebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 6, 'Dlatego przestrzegaj przykazań Pana, swego Boga, abyś chodził jego drogami i bał się go.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 7, 'Pan, twój Bóg, prowadzi cię bowiem do ziemi dobrej, do ziemi potoków wód, źródeł i głębin, wytryskających w dolinach i górach;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 8, 'Do ziemi pszenicy i jęczmienia, winorośli, figowców i drzew granatu; do ziemi oliwy i miodu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 9, 'Do ziemi, w której będziesz jeść chleb, nie odczuwając niedostatku; w której niczego ci nie zabraknie; do ziemi, której kamienie są żelazem, a z jej gór będziesz wydobywać miedź.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 10, 'Gdy będziesz jadł do syta, będziesz błogosławił Pana, swego Boga, za dobrą ziemię, którą ci dał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 11, 'Strzeż się, byś nie zapomniał Pana, swego Boga, i nie zaniedbał jego przykazań, jego praw i jego nakazów, które ci dziś nakazuję;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 12, 'Aby – gdy najesz się do syta, pobudujesz piękne domy i zamieszkasz w nich;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 13, 'I kiedy twoje bydło i owce rozmnożą się, przybędzie ci srebra i złota oraz wszystko, co będziesz miał, powiększy się;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 14, 'Twoje serce nie uniosło się i abyś nie zapomniał Pana, swego Boga, który cię wyprowadził z ziemi Egiptu, z domu niewoli;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 15, 'Który cię przeprowadził przez tę wielką i straszną pustynię, gdzie były węże jadowite i skorpiony, przez suchą ziemię, bez wody, i wydobył ci wodę z krzemiennej skały;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 16, 'Który cię karmił na pustyni manną, której nie znali twoi ojcowie, aby cię ukorzyć i doświadczać, by w przyszłości wyświadczyć ci dobro;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 17, 'Abyś nie mówił w swym sercu: Moja moc i siła mojej ręki zdobyły mi to bogactwo;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 18, 'Ale pamiętaj Pana, swego Boga, gdyż to on daje ci siłę do zdobywania bogactwa, aby potwierdzić swoje przymierze, które poprzysiągł twoim ojcom, jak się to dziś okazuje.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 19, 'Ale jeśli całkiem zapomnisz Pana, swego Boga, i pójdziesz za innymi bogami, będziesz im służył i oddawał pokłon, to oświadczam wam dziś, że na pewno zginiecie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 20, 'Jak narody, które Pan niszczy przed wami, tak zginiecie, ponieważ nie słuchaliście głosu Pana, waszego Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 1, 'Słuchaj, Izraelu! Dziś przejdziesz przez Jordan, aby wejść i zawładnąć narodami większymi i potężniejszymi od ciebie, miastami wielkimi i obwarowanymi aż po samo niebo;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 2, 'Ludem wielkim i wysokim, synami Anakitów, których znasz i o których słyszałeś, kiedy mówiono: Któż się może ostać wobec synów Anaka?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 3, 'Wiedz zatem dzisiaj, że Pan, twój Bóg, przeprawia się przed tobą; jak ogień trawiący, zniszczy ich i poniży przed tobą, abyś ich wypędził i wytracił szybko, jak ci to obiecał Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 4, 'A gdy Pan, twój Bóg, wypędzi ich przed tobą, nie mów w swym sercu: Dzięki mojej sprawiedliwości Pan mnie wprowadził, abym posiadł tę ziemię. Lecz z powodu niegodziwości tych narodów Pan wygnał je przed tobą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 5, 'Nie dzięki swojej sprawiedliwości ani prawości swego serca wchodzisz, aby posiąść ich ziemię, lecz z powodu niegodziwości tych narodów Pan, twój Bóg, wypędza je przed tobą, i aby dopełnić słowo, które Pan poprzysiągł twoim ojcom: Abrahamowi, Izaakowi i Jakubowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 6, 'Wiedz zatem, że nie dzięki twojej sprawiedliwości Pan, twój Bóg, daje ci tę dobrą ziemię w posiadanie, gdyż jesteś ludem twardego karku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 7, 'Pamiętaj, a nie zapominaj, jak pobudzałeś do gniewu Pana, swego Boga, na pustyni. Od tego dnia, w którym wyszedłeś z ziemi Egiptu, aż do waszego przyjścia na to miejsce buntowaliście się przeciwko Panu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 8, 'Także przy Horebie pobudziliście Pana do gniewu i rozgniewał się Pan na was tak, że chciał was wytępić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 9, 'Gdy wstąpiłem na górę, aby otrzymać kamienne tablice, tablice przymierza, które Pan zawarł z wami, przebywałem na górze przez czterdzieści dni i czterdzieści nocy, nie jedząc chleba i nie pijąc wody.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 10, 'Wtedy Pan dał mi dwie kamienne tablice zapisane palcem Boga, na których były wszystkie te słowa, które Pan powiedział wam na górze spośród ognia, w dniu waszego zgromadzenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 11, 'A kiedy minęło czterdzieści dni i czterdzieści nocy, Pan dał mi dwie tablice kamienne, tablice przymierza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 12, 'I Pan powiedział do mnie: Wstań, zejdź stąd szybko, gdyż zepsuł się twój lud, który wyprowadziłeś z Egiptu. Szybko zboczyli z drogi, którą im nakazałem, i uczynili sobie odlany posąg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 13, 'Pan powiedział też do mnie: Widziałem ten lud, a jest to lud twardego karku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 14, 'Zostaw mnie, a ich wytępię i wytracę ich imię spod nieba, a z ciebie uczynię naród potężniejszy i większy od nich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 15, 'Wtedy zawróciłem i zszedłem z góry. Góra płonęła ogniem, a dwie tablice przymierza były w obu moich rękach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 16, 'A gdy spojrzałem, oto zgrzeszyliście przeciw Panu, waszemu Bogu, bo uczyniliście sobie lanego cielca. Szybko zboczyliście z drogi, którą Pan wam nakazał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 17, 'Wtedy wziąłem te dwie tablice, wyrzuciłem je z rąk i stłukłem je na waszych oczach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 18, 'Potem upadłem przed Panem jak za pierwszym razem, przez czterdzieści dni i czterdzieści nocy nie jadłem chleba i nie piłem wody z powodu wszystkich waszych grzechów, które popełniliście, czyniąc zło w oczach Pana, pobudzając go do gniewu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 19, 'Bałem się bowiem tej zapalczywości i gniewu, którymi Pan zapłonął przeciwko wam, by was wytępić. Lecz i tym razem Pan mnie wysłuchał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 20, 'Również na Aarona Pan bardzo się rozgniewał i chciał go zgładzić. W tym czasie modliłem się też za Aarona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 21, 'A wasz grzech, to jest cielca, którego uczyniliście, wziąłem i spaliłem w ogniu, potłukłem go i pokruszyłem, aż się stał miałki jak proch. I wrzuciłem jego proch do potoku wypływającego z góry.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 22, 'Potem w Tabera, w Massa i w Kibrot-Hattaawa pobudziliście Pana do gniewu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 23, 'A gdy Pan wysłał was z Kadesz-Barnea, mówiąc: Idźcie i weźcie w posiadanie ziemię, którą wam dałem, zbuntowaliście się przeciw nakazowi Pana, waszego Boga, nie uwierzyliście mu i nie usłuchaliście jego głosu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 24, 'Buntowaliście się przeciw Panu od dnia, kiedy was poznałem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 25, 'Dlatego upadłem przed Panem i leżałem przez czterdzieści dni i czterdzieści nocy, bo Pan już powiedział, że was wytępi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 26, 'I modliłem się do Pana tymi słowy: Panie Boże, nie gub swego ludu i swego dziedzictwa, które odkupiłeś swoją wielkością, które wyprowadziłeś z Egiptu potężną ręką.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 27, 'Wspomnij na swoje sługi: Abrahama, Izaaka i Jakuba; nie patrz na zatwardziałość tego ludu, na jego niegodziwość i grzech;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 28, 'Aby nie mówiono w tej ziemi, z której nas wyprowadziłeś: Ponieważ Pan nie mógł wprowadzić ich do ziemi, którą im obiecał, i ponieważ ich znienawidził, wyprowadził ich, aby ich zgładzić na pustyni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 29, 'Oni są twoim ludem i twoim dziedzictwem, które wyprowadziłeś swą wielką mocą i wyciągniętym ramieniem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 1, 'W tym czasie Pan powiedział do mnie: Wyciosaj sobie dwie tablice kamienne podobne do pierwszych i wstąp do mnie na górę; uczyń też drewnianą arkę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 2, 'A napiszę na tych tablicach słowa, które były na pierwszych tablicach, które rozbiłeś; potem włożysz je do arki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 3, 'Uczyniłem więc arkę z drewna akacjowego i wyciosałem dwie tablice kamienne podobne do pierwszych, i wstąpiłem na górę, trzymając w rękach dwie tablice.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 4, 'I Pan napisał na tych tablicach takie pismo jak poprzednio, dziesięć przykazań, które Pan wypowiedział do was na górze spośród ognia w dniu zgromadzenia. I dał mi je Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 5, 'Potem zawróciłem i zszedłem z góry, i włożyłem tablice do arki, którą uczyniłem, i tam się znajdują, tak jak Pan mi rozkazał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 6, 'Wtedy synowie Izraela wyruszyli od Beerot należącego do synów Jaakana do Mosery. Tam umarł Aaron i tam został pogrzebany. A jego syn Eleazar sprawował urząd kapłański w jego miejsce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 7, 'Stamtąd wyruszyli do Gudgody, a z Gudgody do Jotbata, do ziemi potoków wód.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 8, 'W tym czasie Pan oddzielił pokolenie Lewiego do noszenia arki przymierza Pana, do stawania przed Panem, by mu służyć i błogosławić w jego imię aż do dziś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 9, 'Dlatego pokolenie Lewiego nie ma działu ani dziedzictwa wśród swoich braci; Pan jest jego dziedzictwem, jak mu powiedział Pan, twój Bóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 10, 'A ja pozostałem na górze, jak poprzednio, czterdzieści dni i czterdzieści nocy; także tym razem Pan mnie wysłuchał i nie chciał cię wytępić Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 11, 'Potem Pan powiedział do mnie: Wstań, wyrusz przed tym ludem, żeby weszli i posiedli ziemię, którą poprzysiągłem dać ich ojcom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 12, 'Teraz więc, Izraelu, czego żąda od ciebie Pan, twój Bóg? Tylko tego, abyś się bał Pana, swego Boga, abyś chodził wszystkimi jego drogami i abyś go miłował, i służył Panu, swemu Bogu, z całego swego serca i całą swoją duszą;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 13, 'Abyś przestrzegał przykazań Pana i jego nakazów, które ja ci dziś nakazuję dla twojego dobra.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 14, 'Oto do Pana, twego Boga, należą niebiosa, niebiosa niebios, ziemia i wszystko, co jest na niej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 15, 'Jednak Pan upodobał sobie twoich ojców i umiłował ich, i wybrał ich potomstwo po nich, czyli was, ze wszystkich narodów, jak to jest dzisiaj.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 16, 'Obrzeżcie więc nieobrzezanie swojego serca i nie zatwardzajcie już swojego karku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 17, 'Gdyż Pan, wasz Bóg, jest Bogiem bogów i Panem panów, Bogiem wielkim, potężnym i straszliwym, który nie ma względu na osoby i nie przyjmuje darów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 18, 'On wymierza sprawiedliwość sierocie i wdowie i miłuje przybysza, dając mu chleb i odzież.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 19, 'Miłujcie więc i wy przybysza, bo sami byliście przybyszami w ziemi Egiptu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 20, 'Będziesz się bał Pana, swego Boga, jemu będziesz służył, do niego będziesz lgnąć i na jego imię będziesz przysięgał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 21, 'On jest twoją chwałą i twoim Bogiem, który uczynił dla ciebie wielkie i straszliwe rzeczy, które widziały twoje oczy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 22, 'W liczbie siedemdziesięciu dusz zeszli twoi ojcowie do Egiptu, a teraz Pan, twój Bóg, uczynił cię tak licznym jak gwiazdy niebieskie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 1, 'Miłuj więc Pana, swego Boga, i przestrzegaj jego nakazu, jego ustaw, jego praw i jego przykazań przez wszystkie dni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 2, 'A poznajcie dziś (bo nie mówię do waszych synów, którzy nie znali i nie widzieli karania Pana, waszego Boga) jego wielkość, jego potężną rękę i jego wyciągnięte ramię;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 3, 'Jego cuda i jego dzieła, których dokonał w Egipcie na faraonie, królu Egiptu, i na całej jego ziemi;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 4, 'I co uczynił wojskom Egiptu, ich koniom i ich rydwanom: sprawił, że wody Morza Czerwonego zalały je, gdy was gonili, i wytracił ich Pan aż do dziś;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 5, 'Także i to, co uczynił dla was na pustyni, aż do waszego przybycia na to miejsce;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 6, 'I to, co uczynił Datanowi i Abiramowi, synom Eliaba, syna Rubena, gdy ziemia otworzyła swe usta i pochłonęła ich spośród całego Izraela razem z ich rodzinami, namiotami i całym ich dobytkiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 7, 'A wasze oczy widziały wszystkie te wielkie dzieła Pana, których dokonał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 8, 'Przestrzegajcie więc każdego przykazania, które wam dziś nakazuję, abyście się umocnili, weszli i posiedli ziemię, do której wchodzicie, aby ją wziąć w posiadanie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 9, 'I żebyście przedłużyli swoje dni na ziemi, którą Pan poprzysiągł dać waszym ojcom i ich potomstwu, ziemię opływającą mlekiem i miodem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 10, 'Ziemia bowiem, do której wchodzisz, aby ją posiąść, nie jest jak ziemia Egiptu, z której wyszliście, którą zasiewałeś swoim ziarnem i nawadniałeś przy pomocy swoich nóg, jak ogród jarzyn.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 11, 'Lecz ziemia, do której wchodzicie, aby ją posiąść, jest ziemią gór i dolin, która pije wodę deszczu z nieba;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 12, 'Jest to ziemia, o którą Pan, twój Bóg, się troszczy, i na której oczy Pana, twego Boga, stale spoczywają, od początku roku do jego końca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 13, 'A jeśli będziecie pilnie słuchać moich przykazań, które wam dziś nakazuję – żebyście miłowali Pana, swojego Boga, i służyli mu z całego swego serca i całą swoją duszą;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 14, 'Wtedy dam waszej ziemi w odpowiednim czasie deszcz wczesny i późny i będziesz zbierał swoje zboża, swoje wino i swoją oliwę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 15, 'Dam też trawę na twoich polach dla twojego bydła, a będziesz jadł do syta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 16, 'Strzeżcie się, aby wasze serce nie dało się zwieść, abyście nie odstąpili i nie służyli innym bogom, i nie oddawali im pokłonu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 17, 'Bo wówczas zapali się gniew Pana przeciwko wam i zamknie on niebo, aby nie było deszczu i aby ziemia nie wydała swego plonu, i szybko wyginiecie z tej dobrej ziemi, którą Pan wam daje.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 18, 'Weźcie więc te moje słowa do swego serca i do swej duszy i przywiążcie je do swojej ręki jako znak, i niech będą jak przepaski między waszymi oczami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 19, 'I nauczcie ich swoje dzieci, rozmawiając o nich, gdy siedzisz w domu i gdy będziesz w drodze, gdy się kładziesz i gdy wstajesz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 20, 'Wypiszesz je też na odrzwiach swego domu i na swoich bramach;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 21, 'Aby się pomnożyły wasze dni i dni waszych dzieci w ziemi, którą Pan poprzysiągł dać waszym ojcom, dopóki niebo będzie trwać nad ziemią.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 22, 'Bo jeśli będziecie pilnie przestrzegać wszystkich przykazań, które ja wam nakazuję wypełniać, żebyście miłowali Pana, swojego Boga, i chodzili wszystkimi jego drogami, lgnąc do niego;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 23, 'Wtedy Pan wypędzi przed wami wszystkie te narody i zawładniecie narodami większymi i potężniejszymi od was.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 24, 'Każde miejsce, po którym stąpać będzie stopa waszej nogi, będzie wasze: od pustyni i Libanu, od rzeki Eufrat aż do morza zachodniego będzie wasza granica.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 25, 'Nikt nie ostoi się przed wami. Pan, wasz Bóg, wzbudzi strach i lęk przed wami po całej ziemi, którą będziecie deptać, jak wam powiedział.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 26, 'Oto dziś kładę przed wami błogosławieństwo i przekleństwo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 27, 'Błogosławieństwo, jeśli będziecie posłuszni przykazaniom Pana, swojego Boga, które dziś wam nakazuję.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 28, 'A przekleństwo, jeśli nie będziecie posłuszni przykazaniom Pana, swojego Boga, i zboczycie z drogi, którą wam dziś nakazuję, aby pójść za innymi bogami, których nie poznaliście.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 29, 'Gdy Pan, twój Bóg, wprowadzi cię do ziemi, do której wchodzisz, aby ją posiąść, umieścisz to błogosławieństwo na górze Gerizim, a przekleństwo na górze Ebal.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 30, 'Czy nie znajdują się one za Jordanem, po drodze w kierunku zachodu słońca, w ziemi Kananejczyków, którzy mieszkają na stepie, naprzeciwko Gilgal, przy równinie More?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 31, 'Wy bowiem przejdziecie przez Jordan, aby wejść i posiąść ziemię, którą daje wam Pan, wasz Bóg, i posiądziecie ją i w niej zamieszkacie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 32, 'Dopilnujcie, abyście wypełniali wszystkie nakazy i prawa, które dziś wam przedkładam.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 1, 'To są nakazy i prawa, których wypełnienia dopilnujcie w ziemi, którą daje ci Pan, Bóg waszych ojców, żebyś ją dziedzicznie otrzymał po wszystkie dni swojego życia na ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 2, 'Doszczętnie zniszczycie wszystkie miejsca, w których narody, którymi wy zawładniecie, służyli swoim bogom na wysokich górach, na wzgórzach i pod każdym zielonym drzewem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 3, 'Zburzycie ich ołtarze, potłuczecie ich pomniki i spalicie w ogniu ich gaje; porąbiecie też wyrzeźbione posągi ich bogów i wytracicie ich imiona z tego miejsca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 4, 'Nie postępujcie tak z Panem, swoim Bogiem;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 5, 'Lecz do miejsca, które Pan, wasz Bóg, wybierze ze wszystkich waszych pokoleń, aby tam umieścić swoje imię i zamieszkać, właśnie tam będziecie uczęszczać i tam będziecie przychodzić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 6, 'Tam będziecie przynosić swoje całopalenia, ofiary, dziesięciny i ofiary wzniesienia, swoje ofiary ślubowane i dobrowolne oraz pierworodne ze swojego bydła i owiec.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 7, 'I tam będziecie jeść przed Panem, swoim Bogiem, i będziecie się radować ze wszystkiego, co osiągnęły wasze ręce, wy i wasze rodziny, w czym pobłogosławi cię Pan, twój Bóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 8, 'Nie będziecie postępować zgodnie z tym wszystkim, co my tu dziś czynimy: każdy, co jest dobre w jego oczach;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 9, 'Jeszcze nie przyszliście bowiem do odpoczynku i do dziedzictwa, które Pan, twój Bóg, daje tobie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 10, 'Ale gdy przejdziecie przez Jordan, będziecie mieszkać w ziemi, którą Pan, wasz Bóg, daje wam w dziedzictwo, gdy tam da wam odpoczynek od wszystkich waszych wrogów wokoło i zamieszkacie bezpiecznie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 11, 'Wtedy na miejsce, które Pan, wasz Bóg, wybierze sobie, by w nim przebywało jego imię, przyniesiecie wszystko, co wam nakazuję: wasze całopalenia, ofiary, dziesięciny i ofiary wzniesienia, oraz wszystkie najlepsze ofiary ślubowane, które będziecie ślubować Panu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 12, 'I będziecie się radować przed Panem, swoim Bogiem, wy, wasi synowie, wasze córki, wasi słudzy, wasze służące oraz Lewita, który jest w waszych bramach, ponieważ nie ma działu ani dziedzictwa z wami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 13, 'Strzeż się, abyś nie składał swoich całopaleń na każdym miejscu, które zobaczysz;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 14, 'Lecz tylko na miejscu, które wybierze Pan w jednym z twoich pokoleń, tam będziesz składał swoje całopalenia i tam będziesz czynił wszystko, co ci nakazuję.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 15, 'Jeśli jednak twoja dusza zapragnie, możesz zabić i jeść mięso według błogosławieństwa Pana, swego Boga, które da tobie we wszystkich twoich bramach. Może je jeść nieczysty i czysty, podobnie jak sarnę albo jelenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 16, 'Tylko krwi nie będziecie spożywać; wylejecie ją na ziemię jak wodę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 17, 'Nie będziesz mógł w swoich bramach spożywać dziesięciny ze swego zboża, wina i oliwy, pierworodnych ze swego bydła i swoich owiec ani żadnej ze swoich ofiar ślubowanych, które ślubowałeś, ze swoich dobrowolnych ofiar lub z ofiary wzniesienia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 18, 'Lecz będziesz je spożywał przed Panem, swoim Bogiem, na miejscu, które wybierze Pan, twój Bóg, spożyjesz ty, twój syn, twoja córka, twój sługa, twoja służąca oraz Lewita, który jest w twoich bramach. I będziesz się radował przed Panem, swoim Bogiem, ze wszystkiego, co osiągną twoje ręce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 19, 'Strzeż się, abyś nie opuszczał Lewity przez wszystkie twoje dni na ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 20, 'Gdy Pan, twój Bóg, poszerzy twoją granicę, tak jak ci zapowiedział, a powiesz: Będę jadł mięso, ponieważ twoja dusza pragnie jeść mięso, to możesz go spożyć tyle, ile tylko zapragnie twoja dusza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 21, 'A jeśli daleko od ciebie będzie miejsce, które Pan, twój Bóg, wybierze, aby tam przebywało jego imię, wtedy zabijesz ze swego bydła i ze swoich owiec, które da ci Pan, tak jak ci nakazałem, i będziesz jadł w swoich bramach cokolwiek twoja dusza zapragnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 22, 'Jak się je sarnę lub jelenia, tak będziesz je spożywać. Zarówno nieczysty, jak i czysty może je spożywać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 23, 'Tylko wystrzegaj się, byś nie spożywał krwi, bo krew jest życiem, i nie będziesz spożywał życia razem z mięsem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 24, 'Nie będziesz jej spożywał, wylej ją na ziemię jak wodę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 25, 'Nie będziesz jej spożywał, aby się dobrze powodziło tobie i twoim synom po tobie, gdy uczynisz to, co jest dobre w oczach Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 26, 'Tylko twoje rzeczy święte, które będziesz miał, i twoje ofiary ślubowane weźmiesz i przyniesiesz na miejsce, które wybierze Pan;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 27, 'I złożysz swoje całopalenia, mięso i krew na ołtarzu Pana, swego Boga. Lecz krew twoich ofiar będzie wylana na ołtarzu Pana, twego Boga, mięso zaś spożyjesz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 28, 'Przestrzegaj i słuchaj wszystkich tych słów, które ci nakazuję, aby dobrze się powodziło tobie i twoim synom po tobie aż na wieki, gdy będziesz czynić to, co dobre i prawe w oczach Pana, twojego Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 29, 'Gdy Pan, twój Bóg, wytępi przed tobą narody, do których idziesz, by nimi zawładnąć, i opanujesz je, i zamieszkasz w ich ziemi;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 30, 'Strzeż się, byś się nie dał usidlić, idąc za nimi, gdy będą wytępione przed tobą; nie pytaj się też o ich bogów, mówiąc: W jaki sposób te narody służyły swoim bogom? Tak samo i ja uczynię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 31, 'Nie uczynisz tak Panu, swemu Bogu, gdyż wszystko, czym brzydzi się Pan i czego nienawidzi, czynili swoim bogom; nawet swoich synów i swoje córki palili w ogniu dla swoich bogów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 32, 'Cokolwiek wam nakazuję, pilnie wypełniajcie. Nic do tego nie dodasz ani od tego nie ujmiesz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 1, 'Jeśli powstanie pośród was prorok albo ktoś, kto ma sny, i ukaże ci znak lub cud;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 2, 'I stanie się ten znak albo cud, o którym ci oznajmił, i powie: Pójdźmy za innymi bogami, których ty nie znasz, i służmy im;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 3, 'Nie usłuchasz słów tego proroka ani tego, który ma sny, gdyż Pan, wasz Bóg, doświadcza was, aby poznać, czy miłujecie Pana, swego Boga, z całego swego serca i całą swoją duszą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 4, 'Za Panem, swoim Bogiem, będziecie chodzić, jego będziecie się bać, przestrzegać jego przykazań i słuchać jego głosu, będziecie mu służyć i do niego lgnąć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 5, 'A ten prorok albo ten, który ma sny, poniesie śmierć, gdyż namówił do odstępstwa od Pana, waszego Boga (który wyprowadził was z ziemi Egiptu i odkupił was z domu niewoli), by sprowadzić cię z drogi, którą Pan, twój Bóg, nakazał ci iść. W ten sposób wykorzenisz to zło spośród siebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 6, 'Jeśli twój brat, syn twojej matki, albo twój syn bądź twoja córka albo żona spoczywająca na twym łonie, albo twój przyjaciel, który jest dla ciebie jak twoja dusza, będą cię namawiać, mówiąc potajemnie: Pójdźmy i służmy innym bogom, których nie poznałeś ani ty, ani twoi ojcowie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 7, 'Któremuś z bogów tych narodów, które są dokoła was, tych blisko ciebie lub daleko od ciebie, od jednego końca ziemi aż do jej drugiego końca;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 8, 'Nie ulegniesz mu ani go nie usłuchasz; twoje oko nie zlituje się nad nim, nie zmiłujesz się nad nim ani nie ukryjesz go;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 9, 'Ale koniecznie go zabijesz; najpierw twoja ręka będzie nad nim, by go zabić, a potem ręka całego ludu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 10, 'I ukamienujesz go na śmierć, ponieważ chciał odwieść cię od Pana, twego Boga, który cię wyprowadził z ziemi Egiptu, z domu niewoli;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 11, 'A cały Izrael usłyszy o tym i będzie się bał, i już nie popełni takiego zła pośród was.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 12, 'A jeśli usłyszysz, że w jednym z twoich miast, które Pan, twój Bóg, daje ci na mieszkanie, ktoś powie:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 13, 'Wyszli pewni ludzie Beliala spośród ciebie i uwodzą mieszkańców miasta, mówiąc: Pójdźmy i służmy innym bogom, których nie poznaliście;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 14, 'Wtedy przeprowadzisz dochodzenie, zbadasz i pilnie wypytasz. Jeśli okaże się prawdą i rzeczą pewną, że popełniono taką obrzydliwość pośród was;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 15, 'Koniecznie wytracisz mieszkańców tego miasta ostrzem miecza, zniszczysz je doszczętnie i wszystko, co w nim jest, również jego bydło, ostrzem miecza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 16, 'A cały jego łup zbierzesz na środku placu i doszczętnie spalisz w ogniu miasto razem z całym łupem dla Pana, swego Boga. I będzie zwaliskiem wiecznym, nigdy nie zostanie odbudowane.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 17, 'I nie zostanie w twoich rękach nic z tych rzeczy przeklętych, aby Pan odwrócił gniew swojej zapalczywości i okazał ci miłosierdzie, i zmiłował się nad tobą, i rozmnożył cię, jak poprzysiągł twoim ojcom;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 18, 'Gdy będziesz słuchał głosu Pana, swego Boga, zachowując wszystkie jego przykazania, które ci dziś nakazuję, byś czynił to, co prawe w oczach Pana, twojego Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 1, 'Jesteście dziećmi Pana, swojego Boga. Nie będziecie się kaleczyć ani robić łysiny między swymi oczyma po umarłym;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 2, 'Jesteś bowiem ludem świętym dla Pana, swego Boga, i Pan wybrał cię, abyś był dla niego szczególnym ludem spośród wszystkich narodów, które są na ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 3, 'Nie będziesz jeść nic obrzydliwego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 4, 'Oto zwierzęta, które możecie jeść: wół, owca i koza;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 5, 'Jeleń, sarna, daniel, koziorożec, antylopa, dziki wół i kozica.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 6, 'I każde zwierzę, które ma rozdzielone kopyto, podzielone na pół racice i które spośród zwierząt przeżuwa, te będziecie jeść.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 7, 'Lecz z tych, które przeżuwają lub które mają rozdzielone kopyta, nie będziecie jeść wielbłąda, zająca i królika. One bowiem przeżuwają, ale nie mają rozdzielonych kopyt; będą dla was nieczyste.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 8, 'Także świni, bo choć ma kopyto rozdzielone, nie przeżuwa; będzie dla was nieczysta. Ich mięsa nie będziecie jeść i ich padliny nie będziecie dotykać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 9, 'To będziecie jeść ze wszystkiego, co jest w wodzie: wszystko, co ma płetwy i łuski, będziecie jeść.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 10, 'Lecz wszystkiego, co nie ma płetw i łusek, nie będziecie jeść; będzie to dla was nieczyste.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 11, 'Wszelkie czyste ptactwo będziecie jeść.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 12, 'Lecz oto te, których jeść nie będziecie: orzeł, orłosęp i rybołów;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 13, 'Sokół, kania i sęp według jego rodzaju;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 14, 'I kruk według jego rodzaju;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 15, 'Struś, sowa, mewa i jastrząb według jego rodzaju;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 16, 'Puszczyk, puchacz i łabędź;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 17, 'Pelikan, ścierwnik i kormoran;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 18, 'Bocian i czapla według ich rodzaju, dudek i nietoperz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 19, 'Wszelkie owady skrzydlate będą dla was nieczyste, nie będziecie ich jeść.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 20, 'Możecie jeść każdego ptaka czystego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 21, 'Nie będziecie jeść żadnej padliny. Dasz to do spożycia przybyszowi, który jest w twoich bramach, albo sprzedasz cudzoziemcowi, gdyż jesteś ludem świętym dla Pana, swego Boga. Nie będziesz gotować koźlęcia w mleku jego matki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 22, 'Ochoczo będziesz dawać dziesięciny z całego zbioru swego nasienia, które co roku wydaje pole.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 23, 'A będziesz spożywać przed Panem, swoim Bogiem, w miejscu, które wybierze na mieszkanie dla swego imienia, dziesięcinę ze swego zboża, wina i oliwy oraz z pierworodnych swoich wołów i trzód, byś uczył się bać Pana, swego Boga, po wszystkie dni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 24, 'A jeśli daleka będzie twoja droga i nie będziesz mógł tego tam zanieść, jeśli odległe jest od ciebie to miejsce, które wybierze Pan, twój Bóg, na mieszkanie dla swego imienia, gdy Pan, twój Bóg, będzie cię błogosławić;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 25, 'Wtedy spieniężysz to, pieniądze zawiniesz w swoich rękach i pójdziesz na miejsce, które wybierze Pan, twój Bóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 26, 'I za te pieniądze kupisz wszystko, czego zapragnie twoja dusza: woły, owce, wino czy mocny napój lub wszystko, czego zechce twoja dusza. I będziesz tam jadł przed Panem, swoim Bogiem, i będziesz się cieszył, ty i twój dom;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 27, 'Oraz Lewita, który mieszka w twoich bramach; nie opuścisz go, gdyż nie ma działu ani dziedzictwa z tobą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 28, 'Po upływie trzech lat odłożysz wszystkie dziesięciny ze zbiorów tego samego roku i złożysz ją w swoich bramach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 29, 'Wtedy przyjdzie Lewita, który nie ma działu ani dziedzictwa z tobą, oraz przybysz, sierota i wdowa, którzy są w twoich bramach, i będą jeść do syta, aby Pan, twój Bóg, błogosławił cię w każdej pracy twoich rąk, której się podejmiesz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 1, 'Po upływie każdego siódmego roku ustanowisz darowanie długów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 2, 'A to jest sposób darowania: każdy wierzyciel daruje pożyczkę, jakiej udzielił swemu bliźniemu; nie będzie domagał się zwrotu od swego bliźniego lub od swego brata, ponieważ obwołano darowanie długów dla Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 3, 'Od obcego możesz domagać się zwrotu, lecz co będziesz miał u swego brata, twoja ręka daruje;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 4, 'Do czasu, gdy nie będzie pośród was ubogich, ponieważ Pan będzie cię hojnie błogosławił w ziemi, którą Pan, twój Bóg, daje ci w dziedziczne posiadanie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 5, 'Jeśli tylko będziesz uważnie słuchał głosu Pana, swego Boga, byś pilnował wypełniania wszystkich przykazań, które dziś ci nakazuję;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 6, 'Gdyż Pan, twój Bóg, będzie cię błogosławić, tak jak ci obiecał; będziesz pożyczał wielu narodom, a sam od nikogo nie będziesz pożyczał; będziesz panował nad wieloma narodami, a one nad tobą nie zapanują.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 7, 'Jeśli będzie u ciebie jakiś ubogi spośród twoich braci w którymkolwiek z twoich miast w ziemi, którą ci daje Pan, twój Bóg, nie zatwardzaj swego serca ani nie zamykaj swej ręki przed swoim ubogim bratem;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 8, 'Ale hojnie otworzysz mu swoją rękę i chętnie pożyczysz mu tyle, ile będzie potrzebował, czego mu będzie brakowało.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 9, 'Strzeż się, by nie powstała w twoim sercu niegodziwa myśl, byś nie mówił: Zbliża się rok siódmy, rok darowania długów – i abyś nie patrzył surowo na swego ubogiego brata i nic mu nie dał; wtedy on wołałby do Pana przeciwko tobie i obciążyłbyś się grzechem;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 10, 'Chętnie mu dasz i twoje serce nie będzie ubolewało, gdy mu dajesz, gdyż Pan, twój Bóg, będzie cię za to błogosławił w każdym twoim dziele i w każdym twoim przedsięwzięciu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 11, 'Ubogich bowiem nie zabraknie w waszej ziemi. Dlatego nakazuję ci: Otworzysz hojnie swoją rękę swemu bratu, nędznemu i ubogiemu w twej ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 12, 'Jeśli zaprzeda ci się twój brat, Hebrajczyk lub Hebrajka, a będzie ci służyć przez sześć lat, to w siódmym roku wypuścisz go od siebie na wolność.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 13, 'A gdy wypuścisz go od siebie na wolność, nie wypuścisz go z pustymi rękami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 14, 'Hojnie go obdarujesz ze swego bydła, klepiska i tłoczni. Dasz mu z tego, w czym pobłogosławił cię Pan, twój Bóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 15, 'I będziesz pamiętać, że sam byłeś niewolnikiem w ziemi Egiptu i że, Pan, twój Bóg, wykupił cię. Dlatego ja nakazuję ci to dziś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 16, 'Ale jeśli on ci powie: Nie odejdę od ciebie – bo miłuje ciebie i twój dom i ponieważ jest mu u ciebie dobrze;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 17, 'Wtedy weźmiesz szydło i przekłujesz mu ucho, przykładając je o drzwi, i będzie twoim sługą na wieki. Tak samo postąpisz ze swoją służącą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 18, 'Niech nie będzie ci przykro, że wypuścisz go od siebie na wolność, gdyż służąc ci przez sześć lat, wysłużył podwójną zapłatę najemnika. A Pan, twój Bóg, będzie cię błogosławił we wszystkim, co uczynisz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 19, 'Każdego pierworodnego samca ze swego bydła albo z owiec poświęcisz Panu, swemu Bogu. Nie będziesz używał do pracy pierworodnego z cielców ani nie będziesz strzygł pierworodnego ze swoich owiec.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 20, 'Będziesz je spożywał każdego roku przed Panem, swoim Bogiem, ty i twój dom, w miejscu, które wybierze Pan;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 21, 'A gdyby miało jakąś wadę, było kulawe, ślepe lub miało jakąkolwiek inną wadę, nie złożysz go na ofiarę Panu, swemu Bogu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 22, 'Zjesz je w swoich bramach. Zarówno nieczysty, jak i czysty może je jeść, tak jak sarnę i jelenia;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 23, 'Tylko jego krwi nie będziesz spożywał; wylejesz ją na ziemię jak wodę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 1, 'Przestrzegaj miesiąca Abib i obchodź Paschę dla Pana, swego Boga, ponieważ w miesiącu Abib Pan, twój Bóg, wyprowadził cię w nocy z Egiptu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 2, 'Złożysz Panu, swemu Bogu, ofiarę paschalną z owiec i wołów w miejscu, które Pan wybierze na mieszkanie dla swego imienia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 3, 'Nie będziesz jadł wraz z nią chleba kwaszonego; przez siedem dni będziesz jadł z nią przaśniki, chleb utrapienia – gdyż w pośpiechu wyszedłeś z ziemi Egiptu – abyś pamiętał dzień swego wyjścia z ziemi Egiptu po wszystkie dni swego życia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 4, 'Nie zobaczy się u ciebie kwasu we wszystkich twoich granicach przez siedem dni. Z mięsa, które złożyłeś pierwszego dnia wieczorem, nie zostawisz nic przez noc do rana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 5, 'Nie będziesz mógł składać ofiary paschalnej w żadnej twojej miejscowości, którą daje ci Pan, twój Bóg;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 6, 'Lecz w miejscu, które Pan, twój Bóg, wybierze na mieszkanie dla swego imienia, tam będziesz składał ofiarę paschalną wieczorem o zachodzie słońca, w porze swego wyjścia z Egiptu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 7, 'Upieczesz ją i spożyjesz w miejscu, które Pan, twój Bóg, wybierze. Potem rano zawrócisz i pójdziesz do swoich namiotów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 8, 'Przez sześć dni będziesz jadł przaśniki, a siódmego dnia będzie uroczyste święto dla Pana, twego Boga. Nie będziesz wtedy wykonywał żadnej pracy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 9, 'Odliczysz sobie siedem tygodni. Zaczniesz liczyć te siedem tygodni od zapuszczenia sierpa w zboże.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 10, 'Potem będziesz obchodził Święto Tygodni dla Pana, swego Boga, z dobrowolną ofiarą twojej ręki, którą dasz stosownie do tego, jak cię błogosławił Pan, twój Bóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 11, 'A w miejscu, które Pan, twój Bóg, wybierze na mieszkanie dla swego imienia, będziesz się radował przed Panem, swoim Bogiem, ty, twój syn i twoja córka, twój sługa i twoja służąca, Lewita, który jest w twoich bramach, przybysz, sierota i wdowa, którzy będą wśród was.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 12, 'I będziesz pamiętał, że byłeś niewolnikiem w Egipcie. Dlatego pilnuj wypełnienia tych nakazów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 13, 'Będziesz obchodził Święto Namiotów przez siedem dni, gdy zbierzesz plony ze swojego klepiska i tłoczni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 14, 'I będziesz się radował podczas tego święta, ty, twój syn i twoja córka, twój sługa i twoja służąca, Lewita, który jest w twoich bramach, przybysz, sierota i wdowa, którzy będą w obrębie twoich bram.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 15, 'Przez siedem dni będziesz obchodził uroczyste święto dla Pana, swego Boga, w miejscu, które Pan wybierze, gdyż Pan, twój Bóg, będzie cię błogosławił we wszystkich twoich zbiorach i w każdej pracy twoich rąk; i będziesz pełny radości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 16, 'Trzy razy w roku wszyscy twoi mężczyźni pokażą się przed Panem, twoim Bogiem, w miejscu, które on wybierze: na Święto Przaśników, na Święto Tygodni i na Święto Namiotów. A nikt nie pokaże się przed Panem z pustymi rękami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 17, 'Każdy przyjdzie z darem ze swojej ręki według błogosławieństwa Pana, twojego Boga, które on ci daje.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 18, 'Ustanowisz sobie sędziów i urzędników we wszystkich swoich miastach, które Pan, twój Bóg, daje ci dla wszystkich waszych pokoleń, aby sądzili lud sprawiedliwym sądem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 19, 'Nie będziesz naginał sądu, nie będziesz miał względu na osobę i nie będziesz brał daru, gdyż dar zaślepia oczy mądrych i wypacza słowa sprawiedliwych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 20, 'Podążaj całkowicie za sprawiedliwością, abyś żył i posiadł ziemię, którą daje ci Pan, twój Bóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 21, 'Nie posadzisz sobie gaju z żadnego drzewa dokoła ołtarza Pana, swego Boga, jaki sobie zbudujesz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 22, 'Nie postawisz sobie posągu, gdyż Pan, twój Bóg, nienawidzi tego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 1, 'Nie złożysz Panu, swemu Bogu, ofiary z cielca lub owcy, które mają skazę lub jakąkolwiek wadę, gdyż to budzi odrazę w Panu, twym Bogu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 2, 'Jeśli znajdzie się pośród was w jakimkolwiek z twoich miast, które daje ci Pan, twój Bóg, mężczyzna czy kobieta, którzy dopuszczą się zła w oczach Pana, twego Boga, przekraczając jego przymierze;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 3, 'I idąc, będą służyć innym bogom i oddawać pokłon im lub słońcu, księżycowi albo całemu zastępowi niebios, czego nie nakazałem;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 4, 'I zostanie ci o tym doniesione, a ty wysłuchasz tego, zbadasz to dokładnie i okaże się to prawdą i rzeczą pewną, że popełniono taką obrzydliwość w Izraelu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 5, 'Wtedy wyprowadzisz do swoich bram tego mężczyznę lub tę kobietę, którzy dopuścili się tego zła, i tego mężczyznę lub tę kobietę ukamienujesz, aż umrą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 6, 'Na podstawie zeznania dwóch lub trzech świadków ma być zabity skazany na śmierć; nie wolno skazać go na śmierć na podstawie zeznania jednego świadka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 7, 'Ręka świadków będzie na nim, aby go zabić, a potem ręce całego ludu. Tak usuniesz zło spośród siebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 8, 'Jeśli sprawa sądowa dotycząca przelania krwi, roszczeń, zranień oraz sporów w twoich bramach będzie dla ciebie za trudna, wtedy wstaniesz i pójdziesz do miejsca, które Pan, twój Bóg, wybierze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 9, 'I przyjdziesz do kapłanów Lewitów, i do sędziego, który w tym czasie będzie urzędował, i poradzisz się ich, a oni oznajmią ci orzeczenie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 10, 'I postąpisz zgodnie z orzeczeniem, które ci przekażą na tym miejscu, które Pan wybrał, i pilnie wykonasz wszystko tak, jak cię pouczą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 11, 'Postąpisz zgodnie z pouczeniem prawa, którego ci udzielą, i zgodnie z rozstrzygnięciem, które ci przekażą. Nie odstąpisz od orzeczenia, które ci oznajmią ani na prawo, ani na lewo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 12, 'A człowiek, który postąpi zuchwale i nie posłucha kapłana pełniącego tam służbę przed Panem, twoim Bogiem, lub sędziego, poniesie śmierć. Tak usuniesz to zło z Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 13, 'A cały lud usłyszy o tym i będzie się bał, i nie postąpi już zuchwale.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 14, 'Gdy wejdziesz do ziemi, którą daje ci Pan, twój Bóg, gdy posiądziesz ją i zamieszkasz w niej, i powiesz sobie: Ustanowię nad sobą króla tak jak wszystkie okoliczne narody;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 15, 'Tego tylko ustanowisz królem nad sobą, którego Pan, twój Bóg, wybierze. Spośród swoich braci ustanowisz nad sobą króla; nie możesz ustanowić nad sobą cudzoziemca, który nie jest twoim bratem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 16, 'Tylko niech nie pomnaża sobie koni ani nie prowadzi ludu do Egiptu, aby nabyć wiele koni, ponieważ Pan wam powiedział: Nie wracajcie tą drogą nigdy więcej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 17, 'Nie będzie też pomnażał sobie żon, aby jego serce się nie odwróciło; niech nie nabywa zbyt wiele srebra i złota.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 18, 'A gdy już zasiądzie na swym królewskim tronie, napisze sobie w księdze odpis tego prawa od kapłanów Lewitów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 19, 'I będzie go miał przy sobie, i będzie go czytał po wszystkie dni swego życia, aby się nauczył bać Pana, swego Boga, by przestrzegał wszystkich słów tego prawa oraz tych ustaw i aby je wykonywał;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 20, 'Aby jego serce nie wynosiło się ponad jego braci i żeby nie odstąpił od tego przykazania ani na prawo, ani na lewo, aby żył długo w swoim królestwie, on i jego synowie, pośród Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 1, 'Kapłani lewiccy oraz całe pokolenie Lewiego nie będą mieli działu ani dziedzictwa z Izraelem. Będą spożywać ofiary ogniowe Pana i jego dziedzictwo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 2, 'Nie będą mieli dziedzictwa pośród swoich braci. Pan jest ich dziedzictwem, tak jak im powiedział.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 3, 'A taka będzie należność kapłanów od ludu, od tych, którzy składają ofiarę, czy to wołu, czy owcę: oddadzą kapłanowi łopatkę, obie szczęki i żołądek.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 4, 'Oddasz mu pierwociny swego zboża, wina i oliwy oraz pierwociny wełny ze swoich owiec.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 5, 'Jego bowiem wybrał Pan, twój Bóg, ze wszystkich twoich pokoleń, aby stawał i służył w imię Pana, on i jego synowie, po wszystkie dni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 6, 'A jeśli przyjdzie Lewita z jednego z twoich miast z całego Izraela, gdzie przebywa, a przyjdzie z całym pragnieniem swej duszy do miejsca, które Pan wybierze;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 7, 'Wtedy będzie służyć w imię Pana, swego Boga, tak jak wszyscy jego bracia Lewici, którzy tam stoją przed Panem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 8, 'Będą jeść równą część oprócz tego, co mają ze sprzedaży ojcowizny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 9, 'Gdy wejdziesz do ziemi, którą Pan, twój Bóg, ci daje, nie ucz się postępować według obrzydliwości tych narodów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 10, 'Niech nie znajdzie się pośród was nikt, kto by przeprowadzał swego syna lub córkę przez ogień, ani wróżbita, ani wróżbiarz, ani jasnowidz, ani czarownik;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 11, 'Ani zaklinacz, ani nikt, kto by wywoływał duchy, ani czarnoksiężnik, ani nekromanta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 12, 'Każdy bowiem, kto czyni takie rzeczy, budzi odrazę w Panu. Z powodu tych obrzydliwości Pan, twój Bóg, wypędza przed tobą te narody.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 13, 'Będziesz doskonały przed Panem, swoim Bogiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 14, 'Gdyż te narody, które opanujesz, słuchają wieszczbiarzy i wróżbitów, lecz tobie nie pozwala na to Pan, twój Bóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 15, 'Pan, twój Bóg, wzbudzi ci proroka podobnego do mnie spośród ciebie, spośród twoich braci. Jego będziecie słuchać;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 16, 'Zgodnie z tym wszystkim, o co prosiłeś Pana, swego Boga, na Horebie, w dniu zgromadzenia: Niech już nie słucham głosu Pana, swego Boga, i niech już nie patrzę na ten wielki ogień, abym nie umarł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 17, 'Wtedy Pan powiedział do mnie: Słusznie powiedzieli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 18, 'Wzbudzę im proroka podobnego do ciebie spośród ich braci i włożę moje słowa w jego usta, a on powie im wszystko, co mu rozkażę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 19, 'I jeśli ktoś nie będzie posłuszny moim słowom, które będzie on mówić w moim imieniu, zażądam od niego zdania sprawy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 20, 'Natomiast prorok, który odważy się mówić słowo w moim imieniu, którego mu nie nakazałem mówić, albo będzie mówił w imieniu obcych bogów, taki prorok poniesie śmierć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 21, 'A jeśli powiesz w swym sercu: Jak rozpoznamy to słowo, którego Pan nie wypowiedział?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 22, 'Gdy prorok będzie coś mówił w imieniu Pana, a to się nie spełni ani nie nastąpi, to jest to słowo, którego Pan nie wypowiedział, lecz prorok mówił to z zuchwalstwa. Nie bój się go.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 1, 'Gdy Pan, twój Bóg, wytępi narody, których ziemię ci daje Pan, twój Bóg, a posiądziesz ją i zamieszkasz w ich miastach i w ich domach;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 2, 'Wydzielisz sobie trzy miasta pośród twojej ziemi, którą Pan, twój Bóg, daje ci w posiadanie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 3, 'Przygotujesz sobie drogę i podzielisz na trzy części obszar twojej ziemi, którą Pan, twój Bóg, daje ci w posiadanie, aby mógł tam uciekać każdy zabójca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 4, 'A to będzie prawo zabójcy, który będzie mógł tam uciec, aby pozostać przy życiu: Kto zabije swego bliźniego nieumyślnie, a wcześniej nie nienawidził go;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 5, 'Na przykład gdyby ktoś szedł ze swym bliźnim do lasu ścinać drzewa, uchwycił ręką siekierę, by ściąć drzewo, a siekiera odpadła z toporzyska i trafiła jego bliźniego tak, że umarłby, ucieknie on do jednego z tych miast, aby pozostał przy życiu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 6, 'Aby mściciel krwi, gdy jego serce się rozpali, nie ścigał zabójcy i nie dogonił go na dalekiej drodze, i nie zabił go, ponieważ nie zasłużył on na śmierć, gdyż wcześniej go nie nienawidził.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 7, 'Dlatego nakazuję ci: Wydzielisz sobie trzy miasta;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 8, 'A gdy Pan, twój Bóg, rozszerzy twoje granice, jak poprzysiągł twoim ojcom, i da ci całą ziemię, którą obiecał dać twoim ojcom;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 9, 'Jeśli będziesz przestrzegał i wypełniał wszystkie te przykazania, które ja ci dziś nakazuję, abyś miłował Pana, swego Boga, i chodził jego drogami po wszystkie dni, wtedy dodasz sobie jeszcze trzy miasta do tamtych trzech miast;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 10, 'Aby nie była wylana krew niewinna pośrodku twojej ziemi, którą Pan, twój Bóg, daje ci w dziedzictwo, aby krew na tobie nie ciążyła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 11, 'Ale jeśli ktoś nienawidzi swego bliźniego i będzie na niego czyhał, powstanie przeciw niemu i śmiertelnie go uderzy, a ten umrze, a potem ucieknie do jednego z tych miast;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 12, 'Wtedy starsi tego miasta poślą po niego i sprowadzą go stamtąd, i wydadzą go w ręce mściciela krwi, aby poniósł śmierć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 13, 'Twoje oko nie zlituje się nad nim, lecz usuniesz niewinną krew z Izraela, aby ci się dobrze powodziło.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 14, 'Nie przesuniesz granicy swego bliźniego założonej przez przodków w twoim dziedzictwie, które posiądziesz w ziemi, którą Pan, twój Bóg, daje ci w posiadanie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 15, 'Jeden świadek nie może powstać przeciwko człowiekowi w jakiejkolwiek nieprawości lub w jakimkolwiek grzechu ze wszystkich grzechów, jakie ktoś popełni. Na podstawie zeznania dwóch lub trzech świadków oparte będzie każde słowo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 16, 'Jeśli fałszywy świadek powstanie przeciwko komuś, by oskarżać go o przestępstwo;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 17, 'Wtedy obaj mężczyźni, którzy mają spór, staną przed Panem i przed kapłanami, i sędziami, którzy będą sprawować w tym czasie urząd;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 18, 'I sędziowie dokładnie zbadają sprawę. Jeśli się okaże, że ten świadek jest fałszywym świadkiem, że złożył fałszywe zeznanie przeciwko swemu bratu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 19, 'Uczynicie mu tak, jak on zamierzał uczynić swemu bratu. I usuniesz zło spośród siebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 20, 'A pozostali usłyszą o tym, zlękną się i nie dopuszczą już takiego złego czynu pośród ciebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 21, 'Twoje oko się nie zlituje: życie za życie, oko za oko, ząb za ząb, ręka za rękę, noga za nogę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 1, 'Gdy wyruszysz na wojnę przeciw swoim wrogom i zobaczysz konie, rydwany i lud liczniejszy od ciebie, nie bój się ich, gdyż jest z tobą Pan, twój Bóg, który cię wyprowadził z ziemi Egiptu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 2, 'A gdy będziecie się zbliżać do walki, kapłan wystąpi i przemówi do ludu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 3, 'I powie do niego: Słuchaj, Izraelu! Dziś staczacie bitwę ze swymi wrogami. Niech wasze serce nie słabnie, nie bójcie się, nie trwóżcie ani nie lękajcie się ich;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 4, 'Gdyż Pan, wasz Bóg, idzie z wami, aby za was walczyć z waszymi wrogami i was wybawić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 5, 'Dowódcy również przemówią do ludu i powiedzą: Jeśli jest ktoś, kto zbudował nowy dom, a jeszcze go nie poświęcił, niech idzie i wraca do swego domu, aby nie zginął w bitwie i aby ktoś inny go nie poświęcił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 6, 'Albo jeśli jest ktoś, kto zasadził winnicę i jeszcze nie spożywał z niej owocu, niech idzie i wraca do swego domu, by nie zginął w bitwie i aby ktoś inny z niej nie spożywał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 7, 'Albo jeśli jest ktoś, kto poślubił żonę, a jeszcze jej nie pojął, niech idzie i wraca do swego domu, by nie zginął w bitwie i aby inny jej nie pojął.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 8, 'Dowódcy jeszcze przemówią do ludu i powiedzą: Jeśli ktoś jest bojaźliwy i lękliwego serca, niech idzie i wraca do swego domu, aby serce jego braci nie było słabe jak jego serce jest słabe.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 9, 'A gdy dowódcy przestaną mówić do ludu, wtedy wyznaczą dowódców wojsk na czele ludu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 10, 'Gdy podejdziesz do jakiegoś miasta, aby je zdobyć, zaoferujesz mu pokój.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 11, 'A jeśli odpowie ci z pokojem i otworzy ci bramy, wtedy cały lud znajdujący się w nim stanie się twoim hołdownikiem i będzie ci służył.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 12, 'Jeśli jednak nie zawrze z tobą pokoju, lecz wznieci przeciw tobie wojnę, oblegniesz je.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 13, 'A gdy Pan, twój Bóg, wyda je w twoje ręce, zabijesz w nim każdego mężczyznę ostrzem miecza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 14, 'Tylko kobiety, dzieci, bydło oraz wszystko, co będzie w mieście, cały łup z niego, weźmiesz sobie jako zdobycz; i będziesz jadł z łupu swoich wrogów, których daje ci Pan, twój Bóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 15, 'Tak postąpisz ze wszystkim miastami bardzo oddalonymi od ciebie, które nie należą do miast tych narodów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 16, 'Ale z miast tych narodów, które Pan, twój Bóg, daje ci w dziedzictwo, żadnej duszy nie zostawisz przy życiu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 17, 'Lecz doszczętnie je wytępisz: Chetytów, Amorytów, Kananejczyków, Peryzzytów, Chiwwitów i Jebusytów, jak ci nakazał Pan, twój Bóg;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 18, 'Aby nie uczyli was czynić według wszystkich swoich obrzydliwości, jakie czynili swym bogom, i abyście nie zgrzeszyli przeciw Panu, swojemu Bogu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 19, 'Gdy przez wiele dni będziesz oblegał jakieś miasto, walcząc przeciwko niemu, aby je zdobyć, nie niszcz jego drzew, wycinając je siekierą. Będziesz bowiem z nich jeść, więc nie wycinaj ich (bo drzewa polne są dla życia człowieka), aby ich użyć do oblężenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 20, 'Tylko te drzewa, o których wiesz, że nie rodzą owoców, zniszczysz i wytniesz; i zbudujesz narzędzia przeciwko temu miastu, które z tobą walczy, aż je opanujesz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 1, 'Jeśli w ziemi, którą Pan, twój Bóg, daje ci w posiadanie, zostanie znaleziony zabity człowiek leżący na polu, a nie wiadomo, kto go zabił;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 2, 'Wtedy twoi starsi i sędziowie wyjdą i zmierzą odległość do miast leżących dokoła zabitego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 3, 'A starsi tego miasta, które leży najbliżej zabitego, wezmą jałówkę, której jeszcze nie użyto do pracy i która jeszcze nie ciągnęła w jarzmie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 4, 'I zaprowadzą starsi tego miasta jałówkę do kamienistej doliny, gdzie nigdy nie uprawiano ani nie zasiewano, i tam utną kark jałówki w tej dolinie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 5, 'Potem przyjdą kapłani, synowie Lewiego, gdyż ich wybrał Pan, twój Bóg, aby mu służyli i aby błogosławili w imię Pana, a według ich uznania ma być rozstrzygnięty każdy spór i każde zranienie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 6, 'I wszyscy starsi tego miasta, które leży najbliżej zabitego, umyją swoje ręce nad jałówką, którą ścięto w dolinie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 7, 'I oświadczą: Nasze ręce nie wylały tej krwi i nasze oczy tego nie widziały.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 8, 'Panie, przyjmij przebłaganie za twój lud Izraela, który odkupiłeś, a nie poczytaj twemu ludowi Izraela niewinnej krwi. I będą oczyszczeni od tej krwi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 9, 'W ten sposób usuniesz niewinną krew spośród siebie, gdy uczynisz to, co jest prawe w oczach Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 10, 'Gdy też wyruszysz na wojnę przeciwko swoim wrogom i Pan, twój Bóg, wyda ich w twoje ręce, i weźmiesz z nich jeńców;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 11, 'I zobaczysz wśród jeńców piękną kobietę, którą sobie upodobasz, i chciałbyś pojąć ją za żonę;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 12, 'Wtedy przyprowadzisz ją do swego domu, a ona ogoli swoją głowę i obetnie sobie paznokcie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 13, 'I złoży z siebie szatę, w której została pojmana, zostanie w twoim domu i będzie opłakiwać swego ojca i matkę przez cały miesiąc. Potem będziesz z nią obcował i będziesz jej mężem, a ona będzie twoją żoną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 14, 'A jeśli nie będzie ci się podobać, wtedy pozwolisz jej odejść, dokąd zechce; żadną miarą nie sprzedasz jej za pieniądze i nie będziesz nią kupczyć, gdyż ją poniżyłeś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 15, 'Gdyby mężczyzna miał dwie żony, jedną kochaną, a drugą znienawidzoną, i one urodzą mu synów – kochana i znienawidzona – a pierworodny będzie synem znienawidzonej;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 16, 'To gdy będzie przydzielał dobra swoim synom w dziedzictwo, nie będzie mógł ustanowić pierworodnym syna kochanej przed pierworodnym synem znienawidzonej;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 17, 'Ale za pierworodnego uzna syna znienawidzonej, dając mu podwójną część wszystkiego, co ma, gdyż on jest początkiem jego siły, jemu przysługuje prawo pierworództwa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 18, 'Jeśli ktoś ma syna upartego i krnąbrnego, który nie słucha ani głosu swojego ojca, ani głosu swojej matki, a choć go karcą, nie słucha ich;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 19, 'Wtedy jego ojciec i matka wezmą go i przyprowadzą do starszych swego miasta i do bramy jego miejscowości;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 20, 'I powiedzą do starszych miasta: Ten nasz syn jest uparty i krnąbrny, nie słucha naszego głosu, jest żarłokiem i pijakiem;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 21, 'Wtedy wszyscy mężczyźni tego miasta ukamienują go na śmierć; w ten sposób usuniesz zło spośród siebie, a cały Izrael usłyszy o tym i będzie się bać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 22, 'A jeśli ktoś popełni grzech zasługujący na śmierć i poniesie śmierć, a powiesisz go na drzewie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 23, 'Jego trup nie pozostanie na drzewie przez noc, lecz musisz go pochować tego samego dnia, bo ten, kto wisi, jest przeklęty przez Boga. Nie będziesz plugawił twojej ziemi, którą Pan, twój Bóg, daje ci w dziedzictwo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 1, 'Jeśli zobaczysz zabłąkanego wołu albo owcę swego brata, nie omijaj ich, lecz koniecznie odprowadź je do swego brata.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 2, 'A jeśli twój brat nie jest blisko ciebie albo nie znasz go, to zaprowadź je do swego domu i będą u ciebie, aż twój brat będzie ich poszukiwał i wtedy mu je zwrócisz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 3, 'Tak samo postąpisz z jego osłem, tak samo postąpisz z jego szatą i tak samo postąpisz z każdą zgubioną rzeczą swego brata, która mu zginęła, a ty ją znalazłeś. Nie omijaj jej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 4, 'Jeśli zobaczysz, że osioł albo wół twego brata upadł na drodze, nie omijaj ich, lecz niezwłocznie pomóż mu je podnieść.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 5, 'Kobieta nie będzie nosiła ubrania mężczyzny ani mężczyzna nie włoży na siebie ubrania kobiety, gdyż ci, którzy tak czynią, budzą odrazę u Pana, twego Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 6, 'Jeśli przed sobą na drodze napotkasz ptasie gniazdo na jakimkolwiek drzewie lub na ziemi, z pisklętami lub jajkami, a matka wysiaduje pisklęta lub jajka, nie zabierzesz matki z młodymi;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 7, 'Lecz wypuścisz matkę na wolność, a młode weźmiesz sobie, aby ci się dobrze powodziło i abyś przedłużył swoje dni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 8, 'Gdy zbudujesz nowy dom, wtedy uczynisz na swoim dachu ogrodzenie, byś nie sprowadził krwi na swój dom, gdyby ktoś z niego spadł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 9, 'Nie zasiewaj w swojej winnicy różnych rodzajów ziarna, abyś nie splugawił plonu posianego ziarna i zbioru winnicy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 10, 'Nie będziesz orał wołem razem z osłem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 11, 'Nie będziesz nosił szaty utkanej z wełny razem z lnem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 12, 'Sporządzisz sobie frędzle na czterech rogach swego płaszcza, którym będziesz się okrywał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 13, 'Jeśli mężczyzna pojmie żonę, będzie z nią obcował, a potem ją znienawidzi;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 14, 'I sprawi, że będą o niej mówić źle, i zniesławi jej imię, mówiąc: Pojąłem tę żonę, lecz gdy obcowałem z nią, nie stwierdziłem u niej dziewictwa;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 15, 'Wtedy ojciec i matka dziewczyny wezmą i zaniosą dowody dziewictwa tej dziewczyny do starszych miasta, do bramy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 16, 'I ojciec tej dziewczyny powie do starszych: Dałem swoją córkę temu mężczyźnie za żonę, a on jej nienawidzi;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 17, 'A oto sam daje powód, aby mówiono o niej źle, mówiąc: Nie stwierdziłem u twej córki dziewictwa; lecz oto są dowody dziewictwa mojej córki. Wtedy rozłożą prześcieradło przed starszymi miasta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 18, 'Wtedy starsi miasta wezmą tego mężczyznę i ukarzą go.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 19, 'I nałożą na niego grzywnę wynoszącą sto syklów srebra, które oddadzą ojcu tej dziewczyny, ponieważ zniesławił dziewicę Izraela. Pozostanie jego żoną i nie będzie mógł jej oddalić po wszystkie swoje dni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 20, 'Lecz jeśli oskarżenie będzie słuszne, a nie znajdą się dowody dziewictwa tej dziewczyny;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 21, 'Wtedy wyprowadzą tę dziewczynę do drzwi domu jej ojca i mężczyźni tego miasta ukamienują ją na śmierć, gdyż popełniła haniebny czyn w Izraelu, uprawiając nierząd w domu swego ojca. Tak usuniesz zło spośród siebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 22, 'Jeśli znajdzie się mężczyznę leżącego z zamężną kobietą, wtedy oboje umrą, mężczyzna, który leżał z kobietą, i ta kobieta. Tak usuniesz zło z Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 23, 'Jeśli dziewczynę, która jest dziewicą zaślubioną mężowi, napotka jakiś mężczyzna w mieście i będzie z nią obcował;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 24, 'Wtedy wyprowadzisz oboje do bramy miasta i ukamienujecie ich na śmierć; dziewczynę za to, że będąc w mieście, nie krzyczała, a mężczyznę za to, że zhańbił żonę swego bliźniego. Tak usuniesz zło spośród siebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 25, 'Lecz jeśli mężczyzna napotka zaślubioną dziewczynę w polu, porwie ją i zgwałci, wtedy poniesie śmierć tylko mężczyzna, który z nią obcował.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 26, 'Ale dziewczynie nic nie uczynisz; dziewczyna nie zasługuje na śmierć, gdyż jest podobnie jak w przypadku, gdy ktoś powstaje przeciwko swemu bliźniemu i morduje go.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 27, 'Napotkał ją bowiem w polu, a gdy zaślubiona dziewczyna krzyczała, nie było nikogo, kto by ją uratował.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 28, 'Jeśli mężczyzna napotka dziewczynę, która jest dziewicą i niezaślubiona, pochwyci ją i będzie z nią obcował, i zostaną przyłapani;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 29, 'Wtedy mężczyzna, który z nią obcował, da ojcu dziewczyny pięćdziesiąt syklów srebra i będzie ona jego żoną; a ponieważ ją zhańbił, nie będzie mógł jej oddalić po wszystkie swoje dni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 30, 'Nie pojmie mężczyzna żony swego ojca i nie odkryje brzegu szaty swego ojca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 1, 'Ten, kto ma zgniecione jądra lub odcięty członek, nie wejdzie do zgromadzenia Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 2, 'Żaden bękart nie wejdzie do zgromadzenia Pana; nawet jego dziesiąte pokolenie nie wejdzie do zgromadzenia Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 3, 'Nie wejdzie też Ammonita ani Moabita do zgromadzenia Pana; nawet ich dziesiąte pokolenie nie wejdzie do zgromadzenia Pana aż na wieki;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 4, 'Dlatego że nie wyszli do was z chlebem i wodą w czasie, gdy wyszliście z Egiptu i byliście w drodze, i ponieważ najęli za opłatę przeciw tobie Balaama, syna Beora, z Petor w Mezopotamii, aby cię przeklinał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 5, 'Pan, twój Bóg, nie chciał jednak wysłuchać Balaama, lecz zamienił ci Pan, twój Bóg, przekleństwo w błogosławieństwo, gdyż umiłował cię Pan, twój Bóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 6, 'Nie zabiegaj o ich pokój ani dobro po wszystkie swoje dni na wieki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 7, 'Nie będziesz się brzydził Edomitą, gdyż jest on twoim bratem. Nie będziesz się brzydził Egipcjaninem, gdyż byłeś przybyszem w jego ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 8, 'Dzieci, które urodzą się im w trzecim pokoleniu, wejdą do zgromadzenia Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 9, 'Gdy wyruszysz z wojskiem przeciwko swoim wrogom, wystrzegaj się wszelkiej niegodziwości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 10, 'Jeśli będzie pośród was człowiek nieczysty z powodu nocnego zdarzenia, to wyjdzie za obóz i nie wróci do niego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 11, 'A pod wieczór umyje się wodą, a gdy zajdzie słońce, wejdzie do obozu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 12, 'Będziesz też miał miejsce za obozem, gdzie będziesz wychodził;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 13, 'I wśród swoich przyborów będziesz miał łopatkę; a gdy wyjdziesz na zewnątrz za potrzebą, wykopiesz nią dołek, potem odwrócisz się i przykryjesz swoje nieczystości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 14, 'Pan, twój Bóg, przechadza się bowiem pośród twego obozu, aby cię wybawić i wydać ci twoich wrogów; niech więc twój obóz będzie święty, aby nie widział u ciebie żadnej nieprzyzwoitości i nie odwrócił się od ciebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 15, 'Nie wydasz panu sługi, który uciekł do ciebie od swego pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 16, 'Będzie z tobą mieszkał pośród ciebie w miejscu, które sobie wybierze w jednym z twoich miast, gdzie mu się podoba. Nie będziesz go gnębił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 17, 'Nie będzie żadnej nierządnicy wśród córek Izraela ani nie będzie sodomity wśród synów Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 18, 'Nie przyniesiesz do domu Pana, swego Boga, zapłaty nierządnicy ani zarobku psa jako ofiary ślubowanej, gdyż obie rzeczy budzą odrazę u Pana, twego Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 19, 'Nie będziesz brał odsetek od brata za pożyczone pieniądze, żywność ani cokolwiek, co się pożycza na procent.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 20, 'Obcemu możesz pożyczać na procent, lecz swemu bratu nie pożyczysz na procent, aby Pan, twój Bóg, błogosławił cię w każdym dziele twoich rąk w ziemi, do której wchodzisz, by ją posiąść.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 21, 'Jeśli złożysz Panu, swemu Bogu, jakiś ślub, nie zwlekaj z jego spełnieniem, gdyż Pan, twój Bóg, z pewnością będzie się tego domagał od ciebie, a na tobie będzie ciążył grzech.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 22, 'Lecz jeśli nie będziesz ślubował, grzech nie będzie na tobie ciążył.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 23, 'To, co wyjdzie z twoich ust, wypełnisz i uczynisz, gdyż dobrowolnie ślubowałeś Panu, swemu Bogu, co powiedziałeś swoimi ustami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 24, 'Gdy wejdziesz do winnicy swego bliźniego, możesz jeść do syta tyle winogron, ile chcesz, lecz do swego naczynia nie wkładaj.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 25, 'Gdy wejdziesz w zboże swego bliźniego, możesz zrywać kłosy swoją ręką, lecz sierpa nie zapuszczaj w zboże swego bliźniego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 1, 'Jeśli mężczyzna poślubi kobietę i zostanie jej mężem, a potem zdarzy się, że nie znajdzie ona upodobania w jego oczach, gdyż znalazł u niej coś nieprzyzwoitego, wtedy wypisze jej list rozwodowy, wręczy go jej i odprawi ją ze swego domu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 2, 'A gdy ona opuści jego dom, może wyjść za mąż za innego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 3, 'A jeśli drugi mąż ją znienawidzi, wypisze jej list rozwodowy, wręczy go jej i odprawi ją ze swego domu, albo jeśli umrze ten drugi mąż, który pojął ją za żonę;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 4, 'To ten pierwszy mąż, który ją odprawił, nie będzie mógł powtórnie pojąć jej za żonę, gdyż jest ona splugawiona; to bowiem jest obrzydliwością przed Panem. Nie dopuszczaj do popełnienia takiego grzechu w ziemi, którą Pan, twój Bóg, daje ci w dziedzictwo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 5, 'Mężczyzna, który niedawno się ożenił, nie pójdzie na wojnę ani nie będzie obciążony żadnym obowiązkiem pracy. Będzie wolny w swym domu przez jeden rok i będzie cieszyć się swoją żoną, którą pojął.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 6, 'Nikt nie weźmie w zastaw kamienia młyńskiego górnego ani dolnego, gdyż to brałby jakby jego życie w zastaw.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 7, 'Jeśli znajdzie się człowiek, który porwał kogoś ze swych braci, z synów Izraela, i handluje nim lub go sprzedał, to ten złodziej poniesie śmierć; tak usuniesz zło spośród siebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 8, 'Uważaj na plagę trądu, aby pilnie przestrzegać i czynić wszystko, czego was uczą kapłani Lewici. Dopilnujcie wypełnienia tego, co im nakazałem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 9, 'Pamiętaj o tym, co Pan, twój Bóg, uczynił Miriam w drodze, gdy wyszliście z Egiptu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 10, 'Gdy coś pożyczysz swemu bliźniemu, nie wchodź do jego domu, aby wziąć od niego zastaw.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 11, 'Będziesz stał na dworze, a człowiek, któremu pożyczyłeś, wyniesie do ciebie zastaw przed dom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 12, 'A jeśli ten człowiek jest ubogi, nie położysz się spać z jego zastawem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 13, 'Koniecznie zwrócisz mu zastaw o zachodzie słońca, żeby mógł spać w swojej odzieży i błogosławić cię. To zostanie ci poczytane za sprawiedliwość przed Panem, twoim Bogiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 14, 'Nie wyrządzisz krzywdy ubogiemu i nędznemu najemnikowi spośród swoich braci lub obcych, którzy są w twojej ziemi, w obrębie twoich bram.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 15, 'Tego samego dnia dasz mu jego zapłatę, przed zachodem słońca. Jest bowiem ubogi i z tego się żywi; by nie wołał do Pana przeciwko tobie, a to obciążyło cię grzechem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 16, 'Ojcowie nie poniosą śmierci za dzieci ani dzieci nie poniosą śmierci za ojców. Każdy za swój grzech poniesie śmierć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 17, 'Nie naginaj sądu obcego ani sieroty i nie bierz w zastaw odzieży wdowy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 18, 'Ale pamiętaj, że byłeś niewolnikiem w Egipcie i że Pan, twój Bóg, wybawił cię stamtąd. Dlatego nakazuję ci, abyś to czynił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 19, 'Gdy będziesz żął zboże na swoim polu i zapomnisz snopka na polu, to nie wracaj, aby go wziąć. Będzie to dla obcego, sieroty i wdowy, aby ci błogosławił Pan, twój Bóg, w każdym dziele twoich rąk.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 20, 'Gdy będziesz otrząsał swoje drzewo oliwne, nie przeglądaj drugi raz gałązek. Będzie to dla obcego, sieroty i wdowy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 21, 'Gdy będziesz zbierał winogrona ze swojej winnicy, nie zbieraj pozostałych gron. Będzie to dla obcego, sieroty i wdowy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 22, 'I pamiętaj, że byłeś niewolnikiem w ziemi Egiptu. Dlatego nakazuję ci, abyś to czynił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 1, 'Jeśli powstanie spór między mężczyznami i staną oni przed sądem, by ich sądzono, wtedy usprawiedliwią sprawiedliwego i potępią niegodziwego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 2, 'A jeśli niegodziwy zasłuży na karę chłosty, to sędzia każe go położyć i w jego obecności bić w liczbie odpowiadającej jego niegodziwości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 3, 'Może mu wymierzyć czterdzieści razów, ale nie więcej, gdyż przez większą liczbę razów twój brat zostałby wzgardzony w twoich oczach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 4, 'Nie zawiążesz pyska młócącemu wołowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 5, 'Jeśli bracia mieszkają razem, a jeden z nich umrze, nie pozostawiając dziecka, żona zmarłego nie wyjdzie za mąż za obcego, lecz brat jej męża wejdzie do niej, pojmie ją sobie za żonę i wypełni wobec niej obowiązek powinowactwa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 6, 'A pierworodny syn, którego ona urodzi, przejmie imię zmarłego brata, aby jego imię nie zginęło z Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 7, 'A jeśli ten mężczyzna nie zechce pojąć swojej bratowej, to jego bratowa pójdzie do bramy, do starszych, i powie: Brat mego męża nie chce wzbudzić swemu bratu imienia w Izraelu i nie chce wypełnić wobec mnie obowiązku powinowactwa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 8, 'Wtedy starsi miasta przywołają go i przemówią do niego. Jeśli będzie stał przy swoim i powie: Nie chcę jej pojąć za żonę;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 9, 'Wówczas jego bratowa podejdzie do niego na oczach starszych, zdejmie mu z nogi jego but, plunie mu w twarz i powie: Tak postępuje się z mężczyzną, który nie chce odbudować domu swego brata.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 10, 'I nazwą go w Izraelu: Dom tego, któremu zdjęto but.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 11, 'Jeśli dwaj mężczyźni będą się kłócić ze sobą i żona jednego z nich zbliża się, aby wyrwać swego męża z ręki tego, który go bije, i wyciągnie ona rękę, i uchwyci go za wstydliwe części;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 12, 'To odetniesz jej rękę, nie zlituje się nad nią twoje oko.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 13, 'Nie będziesz miał w swym worku dwojakich odważników, większego i mniejszego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 14, 'Nie będziesz miał w swoim domu dwojakiej efy, większej i mniejszej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 15, 'Będziesz miał wagę dokładną i sprawiedliwą, będziesz też miał efę dokładną i sprawiedliwą, aby się przedłużyły twoje dni na ziemi, którą daje ci Pan, twój Bóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 16, 'Gdyż każdy, kto postępuje niesprawiedliwie, budzi odrazę u Pana, twego Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 17, 'Pamiętaj, co ci uczynił Amalek w drodze, kiedy wyszliście z Egiptu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 18, 'Jak spotkał cię w drodze i napadł na twoje tyły, na wszystkich słabych idących za tobą, gdy byłeś zmęczony i znużony, i nie bał się Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 19, 'Gdy więc Pan, twój Bóg, da ci odpoczynek od wszystkich twych wrogów dokoła w ziemi, którą Pan, twój Bóg, daje ci w dziedziczne posiadanie, to wymażesz spod nieba pamięć o Amaleku. Nie zapominaj o tym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 1, 'Gdy wejdziesz do ziemi, którą Pan, twój Bóg, daje ci w dziedzictwo, gdy posiądziesz ją i zamieszkasz w niej;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 2, 'Wtedy weźmiesz pierwociny ze wszystkich owoców ziemi, które złożysz w ofierze ze swojej ziemi danej ci przez Pana, twojego Boga, i włożysz je do kosza, i udasz się na miejsce, które wybierze Pan, twój Bóg, na mieszkanie dla swego imienia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 3, 'I przyjdziesz do kapłana, który w tym czasie będzie pełnić służbę, i powiesz do niego: Wyznaję dziś Panu, twemu Bogu, że wszedłem do ziemi, którą Pan poprzysiągł naszym ojcom, że nam ją da.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 4, 'Wtedy kapłan weźmie kosz z twojej ręki i postawi go przed ołtarzem Pana, twego Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 5, 'I odezwiesz się, i powiesz przed Panem, swoim Bogiem: Mój ojciec był Syryjczykiem bliskim śmierci, zstąpił do Egiptu, gdzie przebywał w nielicznej garstce i stał się tam wielkim narodem, potężnym i licznym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 6, 'Lecz Egipcjanie źle nas traktowali, dręczyli nas i nakładali na nas ciężką pracę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 7, 'Wtedy wołaliśmy do Pana, Boga naszych ojców, i Pan wysłuchał naszego głosu, i wejrzał na nasze utrapienie, naszą pracę i nasz ucisk;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 8, 'I wywiódł nas Pan z Egiptu potężną ręką i wyciągniętym ramieniem wśród wielkiej grozy, znaków i cudów;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 9, 'I przyprowadził nas na to miejsce, i dał nam tę ziemię, ziemię opływającą mlekiem i miodem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 10, 'Teraz oto przyniosłem pierwociny z owoców ziemi, którą mi dałeś, Panie. I położysz je przed Panem, swoim Bogiem, i oddasz pokłon przed Panem, swoim Bogiem;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 11, 'I będziesz się radował ze wszystkich dóbr, które Pan, twój Bóg, dał tobie i twemu domowi, ty, Lewita i przybysz, który jest pośród ciebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 12, 'A gdy zakończysz składanie wszystkich dziesięcin swoich zbiorów w trzecim roku, roku dziesięcin, gdy oddasz je Lewicie, przybyszowi, sierocie oraz wdowie, aby najedli się do syta w twoich bramach;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 13, 'Wtedy powiesz przed Panem, swoim Bogiem: Wziąłem z domu to, co jest poświęcone, i dałem też z tego Lewicie, przybyszowi, sierocie oraz wdowie zgodnie ze wszystkimi twoimi przykazaniami, które mi nakazałeś. Nie przekroczyłem twoich przykazań ani nie zapomniałem ich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 14, 'Nie jadłem z tego w czasie żałoby, niczego z tego nie odjąłem do użytku pospolitego, ani też nic z tego nie dałem dla zmarłych. Usłuchałem głosu Pana, mojego Boga, uczyniłem wszystko, co mi nakazałeś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 15, 'Spójrz ze swego świętego przybytku z nieba, i błogosław swemu ludowi Izraela oraz ziemi, którą nam dałeś, tak jak poprzysiągłeś naszym ojcom, ziemi mlekiem i miodem płynącej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 16, 'Dziś Pan, twój Bóg, nakazuje ci wypełnić te ustawy i prawa. Przestrzegaj ich więc i wypełniaj je z całego swego serca i całą swoją duszą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 17, 'Dziś oświadczyłeś, że Pan jest twoim Bogiem, że będziesz chodził jego drogami, przestrzegał jego ustaw, przykazań i praw oraz że będziesz słuchał jego głosu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 18, 'Pan zaś oświadczył dziś, że będziesz jego szczególnym ludem, jak ci obiecał, i że masz przestrzegać wszystkich jego przykazań;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 19, 'Że wywyższy cię ponad wszystkie narody, które uczynił, w chwale, w sławie i we czci, i że masz być ludem świętym dla Pana, swego Boga, tak jak powiedział.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 1, 'Wtedy Mojżesz i starsi Izraela nakazali ludowi: Przestrzegajcie wszystkich przykazań, które wam dziś nakazuję.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 2, 'A w dniu, w którym przeprawicie się przez Jordan do ziemi, którą daje ci Pan, twój Bóg, ustawisz sobie wielkie kamienie i pobielisz je wapnem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 3, 'I wypiszesz na nich wszystkie słowa tego prawa, gdy tylko przeprawisz się, abyś wszedł do ziemi, którą daje ci Pan, twój Bóg, do ziemi mlekiem i miodem płynącej, jak ci obiecał Pan, Bóg twoich ojców.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 4, 'Gdy więc przeprawicie się przez Jordan, ustawicie te kamienie, o których wam dziś nakazuję, na górze Ebal, i pobielisz je wapnem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 5, 'Tam też zbudujesz ołtarz Panu, swemu Bogu, ołtarz z kamieni. Nie będziesz ich ciosał narzędziem z żelaza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 6, 'Z kamieni nieciosanych zbudujesz ołtarz Panu, swemu Bogu, i na nim będziesz składał całopalenia Panu, swemu Bogu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 7, 'Złożysz też ofiary pojednawcze i będziesz tam jadł, i radował się przed Panem, swoim Bogiem;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 8, 'I na tych kamieniach bardzo wyraźnie wypiszesz wszystkie słowa tego prawa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 9, 'Potem Mojżesz i kapłani Lewici powiedzieli do całego Izraela: Milcz i słuchaj, Izraelu. Dziś stałeś się ludem Pana, swego Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 10, 'Będziesz więc słuchał głosu Pana, swego Boga, i będziesz wypełniał jego przykazania i ustawy, które dziś ci nakazuję.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 11, 'W tym samym dniu Mojżesz nakazał ludowi:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 12, 'Oto ci, którzy staną, by błogosławić lud na górze Gerizim, gdy przeprawicie się przez Jordan: Symeon, Lewi, Juda, Issachar, Józef i Beniamin.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 13, 'Oto zaś ci staną na górze Ebal, by przeklinać: Ruben, Gad, Aszer, Zebulon, Dan i Neftali.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 14, 'I odezwą się Lewici, i przemówią donośnym głosem do wszystkich mężczyzn Izraela:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 15, 'Przeklęty człowiek, który wykona wyrzeźbiony lub odlewany posąg – obrzydliwość dla Pana, dzieło rąk rzemieślnika, i postawi w ukrytym miejscu. A cały lud odpowie: Amen.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 16, 'Przeklęty, kto lekceważy swego ojca i swoją matkę. A cały lud powie: Amen.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 17, 'Przeklęty, kto przesuwa granicę swego bliźniego. A cały lud powie: Amen.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 18, 'Przeklęty, kto sprowadza ślepego z drogi, aby błądził. A cały lud powie: Amen.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 19, 'Przeklęty, kto nagina sądu przybysza, sieroty i wdowy. A cały lud powie: Amen.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 20, 'Przeklęty, kto obcuje z żoną swego ojca, bo odkrywa brzeg płaszcza swego ojca. A cały lud powie: Amen.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 21, 'Przeklęty, kto obcuje z jakimkolwiek zwierzęciem. A cały lud powie: Amen.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 22, 'Przeklęty, kto obcuje ze swoją siostrą, córką swego ojca lub córką swojej matki. A cały lud powie: Amen.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 23, 'Przeklęty, kto obcuje ze swoją teściową. A cały lud powie: Amen.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 24, 'Przeklęty, kto zabija potajemnie swego bliźniego. A cały lud powie: Amen.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 25, 'Przeklęty, kto przyjmuje dary, by zabić niewinnego człowieka. A cały lud powie: Amen.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 26, 'Przeklęty, kto nie trwa w wypełnianiu słów tego prawa. A cały lud powie: Amen.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 1, 'Jeśli będziesz pilnie słuchał głosu Pana, swego Boga, by przestrzegać i wypełniać wszystkie jego przykazania, które ci dziś nakazuję, to Pan, twój Bóg, wywyższy cię ponad wszystkie narody ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 2, 'I spłyną na ciebie te wszystkie błogosławieństwa, i dosięgną cię, jeśli będziesz słuchał głosu Pana, swego Boga:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 3, 'Błogosławiony będziesz w mieście i błogosławiony będziesz na polu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 4, 'Błogosławiony będzie owoc twego łona, owoc twojej ziemi, owoc twego bydła, przyrost twego stada oraz trzody twoich owiec.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 5, 'Błogosławiony będzie twój kosz i twoja dzieża.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 6, 'Błogosławiony będziesz, gdy będziesz wchodził, i błogosławiony, gdy będziesz wychodził.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 7, 'Pan sprawi, że twoi wrogowie, którzy powstaną przeciwko tobie, zostaną pobici przed tobą. Jedną drogą wyruszą przeciwko tobie, a siedmioma drogami będą przed tobą uciekać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 8, 'Pan przykaże, aby było z tobą błogosławieństwo w twoich spichlerzach i we wszystkim, do czego wyciągniesz swoją rękę; i będzie ci błogosławił w ziemi, którą daje ci Pan, twój Bóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 9, 'Pan ustanowi cię dla siebie świętym ludem, tak jak ci poprzysiągł, jeśli będziesz przestrzegać przykazań Pana, swego Boga, i chodził jego drogami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 10, 'I wszystkie narody ziemi zobaczą, że jesteś nazywany imieniem Pana, i będą się ciebie lękać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 11, 'Pan obdarzy cię obfitością dobra, owocu twego łona, owocu twego bydła, owocu twego pola, w ziemi, którą Pan poprzysiągł twoim ojcom, że ją tobie da.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 12, 'Pan otworzy dla ciebie swój bogaty skarbiec, niebo, aby dawać deszcz twojej ziemi w odpowiednim czasie i błogosławić wszelką pracę twoich rąk. Będziesz pożyczał wielu narodom, a sam od nikogo nie będziesz pożyczał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 13, 'I Pan umieści cię na czele, a nie na końcu; i będziesz tylko na górze, a nie będziesz na dole, jeśli będziesz słuchał przykazań Pana, swego Boga, które ci dziś nakazuję, abyś ich przestrzegał i je wypełniał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 14, 'I nie odstąpisz od żadnego słowa, które ja wam dziś nakazuję, ani na prawo, ani na lewo, by iść za innymi bogami i im służyć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 15, 'Lecz jeśli nie będziesz słuchał głosu Pana, swego Boga, by przestrzegać wszystkich jego przykazań i ustaw, które ci dziś nakazuję, i wypełniać je, to spadną na ciebie wszystkie te przekleństwa i cię dosięgną:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 16, 'Przeklęty będziesz w mieście, przeklęty będziesz na polu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 17, 'Przeklęty będzie twój kosz i twoja dzieża.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 18, 'Przeklęty będzie owoc twego łona, owoc twojej ziemi, przyrost twego bydła oraz trzody twoich owiec.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 19, 'Przeklęty będziesz, kiedy będziesz wchodził, i przeklęty, kiedy będziesz wychodził.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 20, 'Pan ześle na ciebie przekleństwo, trwogę i karę we wszystkim, do czego wyciągniesz swoją rękę i co czynić będziesz, aż zostaniesz zniszczony i szybko zginiesz z powodu niegodziwości swoich czynów, przez które mnie opuściłeś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 21, 'Pan sprawi, że przylgnie do ciebie zaraza, aż cię wyniszczy z ziemi, do której idziesz, by ją posiąść.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 22, 'Pan uderzy cię suchotami, febrą, zapaleniem, silną gorączką, mieczem, suszą i pleśnią, które będą cię prześladować, aż zginiesz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 23, 'Niebo nad twoją głową stanie się miedzią, a ziemia pod tobą – żelazem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 24, 'Pan ześle na twą ziemię jak deszcz proch i pył, które na ciebie spadną z nieba, aż cię zniszczy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 25, 'Pan sprawi, że zostaniesz pobity przed swymi wrogami. Jedną drogą wyruszysz przeciwko nim, lecz siedmioma drogami będziesz uciekał przed nimi, i będziesz wysiedlony do wszystkich królestw ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 26, 'A twój trup będzie pokarmem dla wszelkiego ptactwa nieba i zwierząt ziemi i nikt ich nie odpędzi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 27, 'Pan dotknie cię wrzodem egipskim, hemoroidami, świerzbem i liszajem, z których nie zdołasz się wyleczyć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 28, 'Pan dotknie cię obłędem, ślepotą i przerażeniem serca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 29, 'W południe będziesz chodził po omacku, jak ślepy w ciemności, i nie powiedzie ci się na twoich drogach. Będziesz uciskany i łupiony po wszystkie dni, a nikt cię nie wybawi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 30, 'Poślubisz sobie żonę, lecz inny mężczyzna będzie z nią obcować. Zbudujesz dom, lecz w nim nie zamieszkasz. Zasadzisz winnicę, lecz z niej nie skorzystasz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 31, 'Twój wół zostanie zabity na twoich oczach, ale nie będziesz go jadł. Twój osioł zostanie ci zabrany sprzed twego oblicza, ale nie zwrócą ci go. Twoje owce zostaną oddane twoim wrogom, ale nikt cię nie uratuje.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 32, 'Twoi synowie i twoje córki zostaną wydani innemu narodowi, a twoje oczy, wypatrując ich, zasłabną z tęsknoty za nimi przez cały dzień, a twoja ręka będzie bezsilna.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 33, 'Owoc twojej ziemi i całą twoją pracę pożre naród, którego ty nie znasz, i będziesz tylko uciskany i dręczony po wszystkie dni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 34, 'I oszalejesz na widok tego, co zobaczą twoje oczy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 35, 'Pan dotknie cię złośliwym wrzodem na kolanach i na goleniach, którego nie będzie można wyleczyć, od stopy aż po czubek głowy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 36, 'Pan zaprowadzi ciebie i twojego króla, którego ustanowisz nad sobą, do narodu, którego nie znałeś ani ty, ani twoi ojcowie. Tam będziesz służył innym bogom, drewnu i kamieniowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 37, 'I będziesz dziwowiskiem, tematem przysłowia i pośmiewiskiem wśród wszystkich narodów, do których Pan cię zaprowadzi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 38, 'Dużo ziarna wyniesiesz na pole, lecz mało zbierzesz, gdyż pożre je szarańcza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 39, 'Winnicę zasadzisz i uprawisz, ale nie będziesz pił wina ani zbierał winogron, gdyż pożre je robactwo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 40, 'Będziesz miał drzewa oliwne we wszystkich swoich granicach, lecz nie namaścisz się oliwą, bo twoje oliwki opadną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 41, 'Spłodzisz synów i córki, ale nie będą twoje, bo pójdą w niewolę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 42, 'Wszystkie twoje drzewa i owoc twojej ziemi pożre szarańcza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 43, 'Cudzoziemiec, który jest pośród ciebie, wzniesie się wielce nad tobą, a ty schylisz się bardzo nisko.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 44, 'On będzie tobie pożyczał, a ty jemu nie będziesz pożyczał. On będzie na czele, a ty będziesz na końcu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 45, 'I spadną na ciebie wszystkie te przekleństwa, i będą cię ścigały, i dosięgną cię, aż cię zniszczą, ponieważ nie słuchałeś głosu Pana, swego Boga, by przestrzegać jego przykazań i ustaw, które ci nakazał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 46, 'A te plagi będą na tobie i na twym potomstwie jako znak i cud na wieki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 47, 'Dlatego, że nie służyłeś Panu, swemu Bogu, w radości i z weselem serca, gdy miałeś obfitość wszystkiego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 48, 'I będziesz służył swoim wrogom, których Pan ześle na ciebie, w głodzie, w pragnieniu, w nagości i w niedostatku wszystkiego. I włoży żelazne jarzmo na twoją szyję, aż cię wyniszczy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 49, 'Pan sprowadzi na ciebie naród z daleka, z krańców ziemi, który przyleci jak orzeł; naród, którego języka nie zrozumiesz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 50, 'Naród o srogim obliczu, który nie będzie miał względu na starego ani się nad dzieckiem nie zlituje;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 51, 'I pożre owoc twego bydła i owoc twojej ziemi, aż cię zniszczy. I nie zostawi ci ani zboża, ani moszczu, ani oliwy, ani przyrostu twych wołów, ani trzód twych owiec, aż cię wyniszczy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 52, 'I oblegnie cię we wszystkich twoich bramach, aż w całej twojej ziemi upadną twoje wysokie i obronne mury, w których pokładałeś ufność. Oblegnie cię we wszystkich twoich bramach, na całej twojej ziemi, którą daje ci Pan, twój Bóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 53, 'Będziesz jadł płód swego łona, ciało swoich synów i córek, których dał ci Pan, twój Bóg, w czasie oblężenia i ucisku, jakimi twój wróg cię przytłoczy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 54, 'Mężczyzna delikatny pośród was i w rozkoszy wychowany będzie spoglądał złym okiem na swego brata, na swą własną żonę i na resztę swych dzieci, które pozostały.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 55, 'I nie da żadnemu z nich z ciała swych dzieci, które będzie jadł, dlatego że nic innego mu nie zostało w oblężeniu i ucisku, jakimi twój wróg cię uciśnie we wszystkich twoich bramach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 56, 'Kobieta delikatna pośród was i w rozkoszy wychowana, która nie chciała postawić swojej nogi na ziemi z powodu delikatności i rozkoszy, będzie spoglądała złym okiem na męża swego łona, na swego syna i na swoją córkę;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 57, 'I na swe łożysko, które wychodzi z niej przy porodzie, i na swoje dzieci, które urodzi. Potajemnie będzie je bowiem jeść z braku wszystkiego w czasie oblężenia i ucisku, jakimi twój wróg przytłoczy cię w twoich bramach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 58, 'Jeśli nie będziesz pilnował wypełnienia wszystkich słów tego prawa, które są napisane w tej księdze, żebyś się bał tego chwalebnego i strasznego imienia: Pan, twój Bóg;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 59, 'Pan ześle na ciebie i na twoje potomstwo niezwykłe plagi, plagi wielkie i niekończące się, także ciężkie i długotrwałe choroby.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 60, 'I sprowadzi na ciebie wszystkie choroby egipskie, których się lękałeś, i przylgną one do ciebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 61, 'Także wszelką chorobę i wszelką plagę, która nie jest napisana w księdze tego prawa, Pan sprowadzi na ciebie, aż cię wytępi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 62, 'I pozostanie was niewielu, którzy przedtem byliście tak liczni jak gwiazdy niebieskie, bo nie posłuchałeś głosu Pana, swego Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 63, 'I będzie tak, że jak Pan radował się wami, czyniąc wam dobrze i rozmnażając was, tak Pan będzie się wami radował, niszcząc was i gładząc was; i będziecie wykorzenieni z ziemi, do której idziecie, aby ją posiąść.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 64, 'I Pan rozproszy cię wśród wszystkich narodów, od jednego krańca ziemi aż do drugiego; tam będziesz służył innym bogom, których nie znałeś ani ty, ani twoi ojcowie – nawet drewnu i kamieniowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 65, 'A wśród tych narodów nie zaznasz wytchnienia ani stopa twojej nogi nie odpocznie. A Pan da ci tam lękliwe serce, wyczerpane oczy i smutek duszy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 66, 'I twoje życie będzie przed tobą jakby w zawieszeniu, będziesz się lękał w nocy i we dnie i nie będziesz pewien swego życia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 67, 'Rano powiesz: Oby już był wieczór, a wieczorem powiesz: Oby już był ranek; z powodu strachu w twoim sercu, który będziesz odczuwać, i z powodu tego, co zobaczą twoje oczy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 68, 'I Pan zawróci cię do Egiptu na okrętach drogą, o której ci powiedziałem, że już jej nie zobaczysz. Tam będziecie się sprzedawać swoim wrogom jako niewolnicy i niewolnice, ale nikt was nie kupi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 1, 'To są słowa przymierza, które Pan nakazał Mojżeszowi zawrzeć z synami Izraela w ziemi Moabu, oprócz przymierza, które zawarł z nimi na Horebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 2, 'I Mojżesz zwołał cały Izrael, i przemówił do nich: Widzieliście wszystko, co Pan uczynił na waszych oczach w ziemi Egiptu faraonowi, wszystkim jego sługom i całej jego ziemi:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 3, 'Te wielkie próby, które widziały twoje oczy, znaki i wielkie cuda.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 4, 'Ale Pan nie dał wam serca do zrozumienia ani oczu do patrzenia, ani uszu do słuchania aż do dziś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 5, 'I prowadziłem was przez czterdzieści lat po pustyni. Wasze szaty nie zniszczyły się na was i wasze obuwie na waszych nogach się nie zużyło.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 6, 'Nie jedliście chleba, nie piliście wina i mocnego napoju, abyście poznali, że ja jestem Pan, wasz Bóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 7, 'A gdy przyszliście na to miejsce, Sichon, król Cheszbonu, i Og, król Baszanu, wyruszyli przeciwko nam do walki, i pobiliśmy ich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 8, 'I wzięliśmy ich ziemię, i daliśmy ją jako dziedzictwo Rubenitom, Gadytom i połowie pokolenia Manassesa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 9, 'Przestrzegajcie więc słów tego przymierza i wypełniajcie je, aby się wam szczęśliwie powodziło we wszystkim, co będziecie czynić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 10, 'Stoicie dziś wszyscy przed Panem, swoim Bogiem: naczelnicy waszych pokoleń, wasi starsi, wasi przełożeni, wszyscy mężczyźni Izraela;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 11, 'Wasze dzieci, wasze żony i przybysz, który mieszka w twoim obozie; od tego, który rąbie drwa, po tego, który czerpie wodę;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 12, 'Aby wejść w przymierze z Panem, swoim Bogiem, i w jego przysięgę, którą Pan, twój Bóg, zawiera dziś z tobą;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 13, 'Aby cię dziś ustanowić dla siebie ludem i żeby on sam był dla ciebie Bogiem, tak jak ci powiedział i tak jak poprzysiągł twoim ojcom: Abrahamowi, Izaakowi i Jakubowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 14, 'Nie tylko z wami zawieram to przymierze i tę przysięgę;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 15, 'Lecz z każdym, kto dziś stoi tu z nami przed Panem, naszym Bogiem, i z każdym, kogo tu dziś z nami nie ma.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 16, 'Wy bowiem wiecie, jak mieszkaliśmy w ziemi Egiptu i jak przechodziliśmy wśród narodów, które minęliśmy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 17, 'I widzieliście ich obrzydliwości i posągi z drewna i kamienia, ze srebra i złota, które są u nich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 18, 'Niech nie będzie wśród was mężczyzny ani kobiety, ani rodziny, ani pokolenia, których serce odwróciłoby się dziś od Pana, naszego Boga, by iść i służyć bogom tych narodów i żeby nie było wśród was korzenia wydającego żółć i piołun;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 19, 'Który gdy usłyszy słowa tego przekleństwa, pobłogosławi sobie w sercu, mówiąc: Będę miał pokój, chociaż będę postępował według zdania mego serca, dodając pijaństwo do pragnienia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 20, 'Pan nie zechce mu przebaczyć, lecz zapali się gniew Pana i jego zazdrość przeciwko temu człowiekowi, spadną na niego wszystkie przekleństwa, które są zapisane w tej księdze, i Pan wymaże jego imię spod nieba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 21, 'I Pan go oddzieli ku złemu ze wszystkich pokoleń Izraela według wszystkich przekleństw przymierza zapisanych w księdze tego Prawa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 22, 'A wasze przyszłe pokolenie, wasi synowie, którzy powstaną po was, i cudzoziemiec, który przyjdzie z dalekiej ziemi, powiedzą, gdy zobaczą plagi tej ziemi i choroby, którymi Pan ją dotknął;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 23, 'Bo siarka i sól wypalą całą tę ziemię, że nie będzie obsiewana ani też nie będzie wydawać owocu i nie urośnie na niej żadna trawa jak w przypadku zniszczenia Sodomy i Gomory, Admy i Seboim, które Pan zniszczył w swoim gniewie i zapalczywości;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 24, 'A zapytają wszystkie narody: Dlaczego Pan tak postąpił z tą ziemią? Cóż to za żar tej wielkiej zapalczywości?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 25, 'I odpowiedzą: Ponieważ porzucili przymierze Pana, Boga swych ojców, które zawarł z nimi, gdy ich wyprowadził z ziemi Egiptu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 26, 'Poszli bowiem służyć innym bogom i oddali im pokłon – bogom, których nie znali i których im nie przydzielił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 27, 'Dlatego gniew Pana zapłonął przeciw tej ziemi, aby sprowadzić na nią wszelkie przekleństwa zapisane w tej księdze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 28, 'I Pan wykorzenił ich z ich ziemi w gniewie i zapalczywości oraz w wielkim oburzeniu i wyrzucił ich do obcej ziemi, jak to dziś widzicie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 29, 'Rzeczy tajemne należą do Pana, naszego Boga, a objawione – do nas i naszych synów na wieki, abyśmy wypełniali wszystkie słowa tego prawa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 1, 'A gdy spadnie na ciebie to wszystko, błogosławieństwo i przekleństwo, które przedłożyłem przed tobą, a wspomnisz je sobie w swym sercu pośród wszystkich narodów, do których Pan, twój Bóg, cię wypędzi;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 2, 'I zawrócisz do Pana, swego Boga, i będziesz słuchał jego głosu we wszystkim, co ci dziś nakazuję, ty i twoi synowie, z całego swego serca i całą swoją duszą;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 3, 'Wtedy Pan, twój Bóg, wyprowadzi cię z twego więzienia i zlituje się nad tobą, i przywróci, i zgromadzi cię ze wszystkich narodów, wśród których Pan, twój Bóg, cię rozproszył.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 4, 'Choćby twoi wygnani byli na krańcu nieba, stamtąd zgromadzi cię Pan, twój Bóg, i stamtąd cię zabierze;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 5, 'I Pan, twój Bóg, przyprowadzi cię do ziemi, którą odziedziczyli twoi ojcowie, i posiądziesz ją, i będzie ci wyświadczać dobro oraz rozmnoży cię bardziej niż twoich przodków.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 6, 'Pan, twój Bóg, obrzeza twoje serce i serce twego potomstwa, abyś miłował Pana, swego Boga, z całego swego serca i całą swoją duszą, abyś żył.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 7, 'I włoży Pan, twój Bóg, wszystkie te przekleństwa na twoich wrogów i na tych, którzy cię nienawidzą i którzy cię prześladowali.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 8, 'A ty zawrócisz i będziesz słuchał głosu Pana i wypełniał wszystkie jego przykazania, które ci dziś nakazuję.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 9, 'I Pan, twój Bóg, poszczęści tobie w każdej sprawie twych rąk, w owocu twego łona, w owocu twego bydła i w owocu twej ziemi, ku dobremu. Pan bowiem znowu będzie się cieszył tobą, czyniąc ci dobro, jak się cieszył twoimi ojcami;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 10, 'Jeśli będziesz słuchał głosu Pana, swego Boga, by przestrzegać jego przykazań i ustaw zapisanych w księdze tego Prawa, i jeśli zawrócisz do Pana, swego Boga, z całego swego serca i całą swoją duszą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 11, 'To przykazanie bowiem, które ci dziś nakazuję, nie jest zakryte przed tobą ani nie jest zbyt dalekie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 12, 'Nie jest w niebie, byś miał mówić: Któż dla nas wstąpi do nieba i przyniesie je nam, i opowie je nam, abyśmy je wypełniali?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 13, 'Nie jest też ono za morzem, byś miał mówić: Któż dla nas popłynie za morze i przyniesie je nam, i opowie je nam, abyśmy je wypełniali.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 14, 'Lecz to słowo jest bardzo blisko ciebie, w twoich ustach i w twoim sercu, abyś je wypełniał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 15, 'Oto dziś położyłem przed tobą życie i dobro oraz śmierć i zło;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 16, 'Gdyż dziś ci nakazuję, abyś miłował Pana, swego Boga, i chodził jego drogami, i przestrzegał jego przykazań, ustaw i praw, abyś żył i rozmnożył się, i Pan, twój Bóg, będzie ci błogosławił w ziemi, do której idziesz, aby ją posiąść.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 17, 'Jeśli zaś twoje serce odwróci się i nie posłuchasz, ale dasz się odwieść, będziesz oddawał pokłon innym bogom i im służył;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 18, 'Oznajmiam wam dziś, że na pewno zginiecie i nie przedłużycie swych dni na ziemi, do której się przeprawiasz przez Jordan, aby tam wejść i posiąść ją.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 19, 'Biorę dziś na świadków przeciwko wam niebo i ziemię, że położyłem przed tobą życie i śmierć, błogosławieństwo i przekleństwo. Wybierz więc życie, abyś żył, ty i twoje potomstwo;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 20, 'I miłował Pana, swego Boga, słuchał jego głosu i do niego lgnął. On bowiem jest twoim życiem i przedłużeniem twoich dni, abyś mieszkał w ziemi, którą Pan poprzysiągł dać twoim ojcom: Abrahamowi, Izaakowi i Jakubowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 1, 'Potem Mojżesz poszedł i powiedział te słowa całemu Izraelowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 2, 'Powiedział do nich: Mam dziś sto dwadzieścia lat, nie mogę już wychodzić i wchodzić. A Pan powiedział mi też: Nie przejdziesz przez Jordan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 3, 'Sam Pan, twój Bóg, przejdzie przed tobą i on wytępi te narody przed tobą, a ty je posiądziesz. A Jozue przejdzie przed tobą, jak Pan powiedział.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 4, 'I Pan uczyni im tak, jak uczynił Sichonowi i Ogowi, królom Amorytów, i ich ziemi, gdy ich zniszczył.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 5, 'Pan wyda ich wam, a wy uczynicie im zgodnie ze wszystkimi przykazaniami, które wam nakazałem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 6, 'Wzmocnijcie się i bądźcie mężni, nie bójcie się ani się nie lękajcie ich, gdyż Pan, twój Bóg, on sam pójdzie z tobą, nie porzuci cię ani cię nie opuści.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 7, 'Następnie Mojżesz przywołał Jozuego i powiedział do niego przed całym Izraelem: Wzmocnij się i bądź mężny, bo ty wejdziesz z tym ludem do ziemi, którą Pan poprzysiągł dać ich ojcom, a ty im ją dasz w dziedzictwo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 8, 'A sam Pan pójdzie przed tobą, on będzie z tobą, nie porzuci cię ani cię nie opuści. Nie bój się ani się nie lękaj.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 9, 'Wtedy Mojżesz zapisał to prawo i oddał je kapłanom, synom Lewiego, którzy nosili arkę przymierza Pana, i wszystkim starszym Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 10, 'Mojżesz nakazał im też: Po upływie każdego siódmego roku, w wyznaczonej porze roku darowania długów, w Święto Namiotów;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 11, 'Gdy cały Izrael przybędzie, aby się stawić przed Panem, twoim Bogiem, na miejscu, które wybierze, odczytasz to prawo do uszu całego Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 12, 'Zgromadzisz lud: mężczyzn, kobiety, dzieci i obcych, którzy są w obrębie twoich bram, aby słuchali i uczyli się, aby się bali Pana, swojego Boga, i pilnowali wypełnienia wszystkich słów tego prawa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 13, 'Ich synowie, którzy jeszcze nie znają, niech też słuchają i uczą się bać Pana, waszego Boga, po wszystkie dni waszego życia na ziemi, do której przeprawiacie się przez Jordan, aby ją posiąść.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 14, 'Potem Pan powiedział do Mojżesza: Oto zbliżają się dni twojej śmierci. Przywołaj Jozuego i stawcie się w Namiocie Zgromadzenia, a ja mu wydam polecenie. Poszedł więc Mojżesz i Jozue i stawili się w Namiocie Zgromadzenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 15, 'I Pan ukazał się w namiocie w słupie obłoku. A słup obłoku stanął nad wejściem do namiotu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 16, 'I Pan powiedział do Mojżesza: Oto zaśniesz ze swoimi ojcami, a ten lud powstanie i będzie uprawiał nierząd, idąc za bogami cudzoziemców tej ziemi, do której wchodzi, by wśród nich zamieszkać, i opuści mnie, i złamie moje przymierze, które z nim zawarłem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 17, 'W tym dniu zapłonie mój gniew przeciwko nim, opuszczę ich i skryję swe oblicze przed nimi, a oni będą pożarci i spotka ich wiele nieszczęść i utrapień i powiedzą w tym dniu: Czy nie dlatego, że naszego Boga nie ma pośród nas, spotkały nas te nieszczęścia?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 18, 'Lecz ja zupełnie zakryję swe oblicze w tym dniu z powodu całego zła, które czynili, zwracając się ku innym bogom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 19, 'Teraz więc zapiszcie sobie tę pieśń i naucz jej synów Izraela. Włóż ją w ich usta, aby ta pieśń była dla mnie świadectwem przeciwko synom Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 20, 'Gdy bowiem wprowadzę ich do ziemi, którą poprzysiągłem ich ojcom, do ziemi mlekiem i miodem płynącej, i będą jeść do syta, i utyją, wtedy zwrócą się ku innym bogom i będą im służyć, a mnie rozdrażnią i złamią moje przymierze;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 21, 'I kiedy spotka ich wiele nieszczęść i utrapień, ta pieśń będzie świadkiem przeciwko nim, gdyż nie zostanie zapomniana w ustach ich potomstwa. Znam bowiem ich zamysł i to, co jeszcze dziś będą czynić, zanim wprowadzę ich do ziemi, którą im poprzysiągłem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 22, 'I Mojżesz napisał tę pieśń tego dnia, i nauczył jej synów Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 23, 'Potem nakazał Jozuemu, synowi Nuna: Wzmocnij się i bądź mężny, bo ty wprowadzisz synów Izraela do ziemi, którą im poprzysiągłem, a ja będę z tobą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 24, 'I kiedy Mojżesz skończył zapisywać słowa tego prawa w księdze;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 25, 'Nakazał Mojżesz Lewitom, którzy nosili arkę przymierza Pana:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 26, 'Weźcie księgę tego Prawa i połóżcie ją obok arki przymierza Pana, waszego Boga, aby tam była świadkiem przeciwko tobie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 27, 'Znam bowiem twój upór i twój twardy kark. Oto dziś, dopóki jeszcze żyję z wami, buntujecie się przeciwko Panu, a cóż dopiero po mojej śmierci?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 28, 'Zgromadźcie u mnie wszystkich starszych waszych pokoleń i waszych dowódców, żebym mówił do ich uszu te słowa i wezwał na świadków przeciwko nim niebo i ziemię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 29, 'Wiem bowiem, że po mojej śmierci zepsujecie się całkowicie i zboczycie z drogi, którą wam nakazałem. I spotka was nieszczęście w ostateczne dni, gdyż będziecie czynić to, co złe w oczach Pana, drażniąc go dziełem swoich rąk.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 30, 'I Mojżesz przemówił do uszu całego zgromadzenia Izraela słowami tej pieśni aż do końca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 1, 'Słuchajcie, niebiosa, a będę mówić; niech i ziemia słucha słów moich ust.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 2, 'Moja nauka będzie kropić jak deszcz, moja mowa będzie ściekać jak rosa, jak drobny deszcz na zioła, jak krople na trawę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 3, 'Będę bowiem głosił imię Pana. Uznajcie wielkość naszego Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 4, 'On jest Skałą, a jego dzieło jest doskonałe, bo wszystkie jego drogi są sprawiedliwe. Jest Bogiem prawdziwym i bez nieprawości, sprawiedliwym i prawym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 5, 'Zepsuli się, ich skaza nie jest skazą jego dzieci; pokolenie złe i przewrotne.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 6, 'Tak to odpłacasz Panu, ludu głupi i niemądry? Czy nie jest on twoim ojcem, który cię nabył dla siebie? Czy nie on cię uczynił i utwierdził?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 7, 'Wspomnij dni dawne, rozważ lata wielu pokoleń. Zapytaj swego ojca, a oznajmi ci; swoich starszych, a powiedzą ci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 8, 'Gdy Najwyższy rozdzielał dziedzictwa narodom, a oddzielał synów Adama, wyznaczył granice narodom według liczby synów Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 9, 'Działem Pana jest bowiem jego lud, Jakub jest jego wydzielonym dziedzictwem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 10, 'Znalazł go na pustynnej ziemi i na wielkim, strasznym pustkowiu. Obwodził go, uczył, strzegł jak źrenicy swego oka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 11, 'Jak orzeł pobudza swoje młode, trzepocze skrzydłami nad swymi orlętami, rozpościera swoje skrzydła, bierze je i nosi je na skrzydłach;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 12, 'Tak Pan sam prowadził go i nie było z nim żadnego obcego boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 13, 'Wzniósł go po wysokich miejscach ziemi, aby żywił się plonami pól, i pozwolił mu ssać miód ze skały i oliwę ze skalnego krzemienia;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 14, 'Masło od krów i mleko od owiec wraz z tłuszczem jagniąt, barany odchowane w Baszanie, kozły razem z tłuszczem ziaren pszenicy, a piłeś z wybornej krwi winogron.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 15, 'Lecz Jeszurun utył i wierzgał – otyłeś, obrosłeś w tłuszcz, zgrubiałeś; opuściłeś Boga, który cię uczynił, i lekceważyłeś Skałę swego zbawienia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 16, 'Pobudzili go do zazdrości obcymi bogami, rozdrażnili go obrzydliwościami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 17, 'Składali ofiary demonom, a nie Bogu; nowym bogom, których nie znali, świeżo przybyłym, których się nie bali wasi ojcowie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 18, 'O Skale, która cię spłodziła, zapomniałeś, i zapomniałeś Boga, swego Stwórcę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 19, 'Gdy Pan to zobaczył, wzgardził nimi z powodu rozdrażnienia swoich synów i córek.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 20, 'I powiedział: Zakryję przed nimi swoje oblicze, zobaczę, jaki będzie ich koniec. Są bowiem pokoleniem przewrotnym, synami, w których nie ma wiary.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 21, 'Oni mnie pobudzili do zazdrości tym, co nie jest Bogiem; rozdrażnili mnie swymi marnościami. Ja też pobudzę ich do zazdrości tymi, którzy nie są ludem, rozdrażnię ich przez głupi naród.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 22, 'Zapłonął bowiem ogień mojego gniewu i spłonie aż do głębin piekła, i pożre ziemię i jej plony, i wypali posady gór.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 23, 'Zgromadzę na nich nieszczęścia, zużyję na nich moje strzały.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 24, 'Będą wyczerpani z głodu i strawieni gorączką i gorzką zarazą. Wyślę na nich też zęby bestii, z jadem gadów ziemskich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 25, 'Na zewnątrz osieroci ich miecz, a w domach – strach, tak młodzieńca, jak i dziewicę, niemowlę i sędziwego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 26, 'Powiedziałem: Rozproszę ich po kątach, wymażę pamięć o nich wśród ludzi;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 27, 'Gdybym się nie obawiał pychy wroga, by ich wrogowie nie powstali i nie powiedzieli: Nasza wielka ręka, a nie Pan, uczyniła to wszystko.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 28, 'Ten naród bowiem jest pozbawiony rady i nie ma rozumu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 29, 'Oby byli mądrzy, zrozumieliby to i zważaliby na swój koniec.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 30, 'Jakże mógłby jeden gonić tysiąc i dwóch zmusić do ucieczki dziesięć tysięcy, gdyby ich Skała nie zaprzedała ich i Pan ich nie wydał?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 31, 'Bo ich skała nie jest jak nasza Skała, nasi wrogowie sami są sędziami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 32, 'Ich winorośl bowiem pochodzi z winorośli Sodomy i z pól Gomory, ich grona to grona trujące, ich kiście są gorzkie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 33, 'Ich wino jest jadem smoków, okrutną trucizną żmij.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 34, 'Czy to nie jest u mnie ukryte, zapieczętowane w moich skarbcach?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 35, 'Do mnie należy zemsta i odpłata; ich noga poślizgnie się w wyznaczonym czasie. Bliski bowiem jest dzień ich klęski, a ich przyszłość spieszy się do nich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 36, 'Pan bowiem będzie sądzić swój lud, zlituje się nad swymi sługami, gdy zobaczy, że ich siła ustała i że nie ma ani niewolnika, ani wolnego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 37, 'I powie: Gdzie są ich bogowie? Ta skała, w której pokładali ufność?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 38, 'Ci, co jadali tłuszcz ich ofiar i pili wino ich ofiar z płynów? Niech wstaną i wam pomogą, niech będą waszym schronieniem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 39, 'Spójrzcie teraz, że to ja, tylko ja jestem, a nie ma innych bogów oprócz mnie. Ja zabijam i ożywiam, ja ranię i ja leczę, i nikt nie wyrwie z mojej ręki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 40, 'Podnoszę bowiem swą rękę ku niebu i mówię: Ja żyję na wieki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 41, 'Jeśli zaostrzę swój błyszczący miecz i moja ręka chwyci sąd, dokonam zemsty na swoich wrogach i odpłacę tym, którzy mnie nienawidzą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 42, 'Krwią upoję moje strzały, mój miecz naje się mięsa, krwią zabitych i pojmanych, jak tylko zacznę mścić się nad wrogami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 43, 'Weselcie się, narody, z jego ludem, gdyż on pomści krew swoich sług i odpłaci zemstą swoim wrogom, a będzie łaskawy dla swej ziemi i swego ludu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 44, 'Przyszedł więc Mojżesz i powiedział wszystkie słowa tej pieśni do uszu tego ludu, on i Ozeasz, syn Nuna.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 45, 'A gdy Mojżesz skończył mówić wszystkie te słowa do całego Izraela;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 46, 'Powiedział do nich: Weźcie sobie do serca wszystkie te słowa, które wam dzisiaj oświadczam, byście przykazywali je waszym dzieciom, by pilnowały wypełnienia wszystkich słów tego prawa;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 47, 'Nie jest to bowiem dla was słowem pustym, gdyż jest waszym życiem. I dzięki niemu przedłużycie swoje dni na ziemi, do której się przeprawiacie przez Jordan, aby ją posiąść.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 48, 'I tego samego dnia Pan powiedział do Mojżesza:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 49, 'Wstąp na tę górę Abarim, na górę Nebo, która jest w ziemi Moabu naprzeciw Jerycha, i spójrz na ziemię Kanaan, którą daję synom Izraela w posiadanie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 50, 'I umrzesz na tej górze, na którą wstąpisz, i zostaniesz przyłączony do swego ludu, tak jak umarł twój brat Aaron na górze Hor i został przyłączony do swego ludu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 51, 'Za to, że wystąpiliście przeciwko mnie pośród synów Izraela przy wodach Meriba w Kadesz, na pustyni Syn, i nie poświęciliście mnie pośród synów Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 52, 'Przed sobą zobaczysz ziemię, lecz nie wejdziesz do tej ziemi, którą daję synom Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 1, 'A to jest błogosławieństwo, którym Mojżesz, mąż Boży, pobłogosławił synów Izraela przed swoją śmiercią.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 2, 'Powiedział: Pan przyszedł z Synaju i z Seiru wzeszedł dla nich, zajaśniał z góry Paran i przyszedł z dziesięcioma tysiącami świętych; z jego prawicy wyszło dla nich ogniste prawo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 3, 'Doprawdy, on umiłował lud; wszyscy jego święci są w twych rękach i oni usiedli u twoich stóp; przyjmują twoje słowa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 4, 'Mojżesz dał nam prawo, dziedzictwo zgromadzenia Jakuba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 5, 'I był królem w Jeszurunie, gdy się zebrali naczelnicy ludu wraz z pokoleniami Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 6, 'Niech żyje Ruben i niech nie umiera; niech jego mężczyzn będzie dużo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 7, 'Potem też dał błogosławieństwo dla Judy i powiedział: Wysłuchaj, Panie, głosu Judy, i przyprowadź go do jego ludu. Niech starczy mu sił jego rąk, a ty bądź mu pomocą przeciw jego wrogom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 8, 'A o Lewim powiedział: Niech twoje Tummim i Urim będą przy twoim świętym, którego doświadczyłeś w Massa, z którym spierałeś się u wód Meriba;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 9, 'Który powiedział swemu ojcu i matce: Nie widziałem go; nie znał też swych braci ani nie znał swych synów. Oni bowiem przestrzegają twoich słów i zachowują twoje przymierze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 10, 'Będą uczyć Jakuba twoich sądów, a Izraela twego prawa. Będą kłaść kadzidło przed tobą i całopalenia na twoim ołtarzu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 11, 'Błogosław, Panie, jego siłę, i przyjmij dzieło jego rąk; skrusz biodra jego wrogów i tych, którzy go nienawidzą, aby już nie powstali.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 12, 'A o Beniaminie powiedział: Umiłowany przez Pana będzie mieszkał przy nim bezpiecznie; Pan będzie go bronił każdego dnia, a on będzie przebywał między jego ramionami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 13, 'O Józefie powiedział: Niech jego ziemia będzie błogosławiona przez Pana, z najlepszych rzeczy niebios, z rosy i z otchłani rozłożonej pod ziemią.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 14, 'I z najcenniejszych plonów słońca, z najcenniejszych plonów księżyca;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 15, 'I z najlepszych skarbów gór starożytnych, z najlepszych darów odwiecznych pagórków;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 16, 'I z najcenniejszych owoców ziemi i jej obfitości oraz z przychylności tego, który przebywał w krzaku. Niech to błogosławieństwo spłynie na głowę Józefa i na czubek głowy tego, który został oddzielony od swoich braci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 17, 'Jego chwała jest jak pierworodny wół, a jego rogi jak rogi jednorożca. Nimi będzie bódł wszystkie narody aż po krańce ziemi; a są to dziesiątki tysięcy Efraima i tysiące Manassesa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 18, 'A o Zebulonie powiedział: Wesel się, Zebulonie, gdy wyruszasz, a ty, Issacharze, w swoich namiotach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 19, 'Zwołują ludy na górę, tam będą składać ofiary sprawiedliwości. Będą bowiem ssać z obfitości morza i ze skarbów ukrytych w piasku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 20, 'A o Gadzie powiedział: Błogosławiony ten, kto rozprzestrzeni Gada. Będzie mieszkać jak lew, a urwie ramię i głowę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 21, 'Upatrzył sobie najlepszą część, gdyż tam został mu wyznaczony dział przez prawodawcę; przyszedł z naczelnikami ludu i wykonał sprawiedliwość Pana i jego sądy z Izraelem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 22, 'A o Danie powiedział: Dan to szczenię lwie, wyskoczy z Baszanu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 23, 'A o Neftalim powiedział: Neftali, nasycony przychylnością i pełen błogosławieństwa Pana, posiądź zachód i południe.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 24, 'A o Aszerze powiedział: Aszer będzie błogosławiony dziećmi, niech się podoba swoim braciom i niech kąpie swoje nogi w oliwie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 25, 'Twoje obuwie będzie z żelaza i miedzi; a ile twoich dni, taka będzie twoja siła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 26, 'Nikt nie jest jak Bóg Jeszuruna, który jeździ po niebie, by tobie pomóc, i po obłokach w swym majestacie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 27, 'Twoim schronieniem jest wieczny Bóg, a pod tobą są wieczne ramiona. On wypędzi przed tobą wroga i powie: Wyniszcz go.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 28, 'Wtedy Izrael będzie mieszkać bezpiecznie sam. Źródło Jakuba – w ziemi zboża i wina, a niebiosa spuszczą rosę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 29, 'Błogosławiony jesteś, Izraelu! Któż do ciebie podobny, ludu zbawiony przez Pana, który jest tarczą twego ratunku i mieczem twego dostojeństwa! Twoi wrogowie poddadzą się tobie obłudnie, a ty zdepczesz ich wyniosłość.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 1, 'Potem Mojżesz wstąpił z równin Moabu na górę Nebo, na szczyt Pizga, który jest naprzeciw Jerycha. I Pan pokazał mu całą ziemię, od Gileadu aż po Dan;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 2, 'I całą ziemię Neftalego, ziemię Efraima i Manassesa oraz całą ziemię Judy aż po Morze Zachodnie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 3, 'I stronę południową, i równinę doliny Jerycha, miasta palm aż po Soar.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 4, 'Wtedy Pan mu powiedział: To jest ziemia, którą poprzysiągłem Abrahamowi, Izaakowi i Jakubowi, mówiąc: Dam ją twemu potomstwu. Pozwoliłem ci ją zobaczyć na własne oczy, ale do niej nie wejdziesz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 5, 'Tam właśnie umarł Mojżesz, sługa Pana, w ziemi Moabu, według słowa Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 6, 'I pogrzebał go w dolinie, w ziemi Moabu, naprzeciw Bet-Peor, a nikt nie zna jego grobu aż po dziś dzień.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 7, 'Mojżesz miał sto dwadzieścia lat, gdy umarł. Jego wzrok nie był przyćmiony i jego siła go nie opuściła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 8, 'I synowie Izraela opłakiwali Mojżesza na równinach Moabu przez trzydzieści dni. Potem skończyły się dni płaczu i żałoby po Mojżeszu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 9, 'A Jozue, syn Nuna, był pełen ducha mądrości, bo Mojżesz włożył na niego swoje ręce. I synowie Izraela byli mu posłuszni i czynili tak, jak Pan nakazał Mojżeszowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 10, 'I nie powstał już prorok w Izraelu równy Mojżeszowi, którego Pan znał twarzą w twarz;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 11, 'We wszystkich znakach i cudach, dla których Pan posłał go, by je czynił w ziemi Egiptu wobec faraona, wszystkich jego sług i całej jego ziemi;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 12, 'I we wszystkich sprawach potężnej ręki, i w całej wielkiej grozie, którą Mojżesz wywołał na oczach całego Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 1, 'Po śmierci Mojżesza, sługi Pana, powiedział Pan do Jozuego, syna Nuna, sługi Mojżesza:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 2, 'Mojżesz, mój sługa, umarł; teraz więc wstań, przepraw się przez ten Jordan, ty i cały ten lud, do ziemi, którą daję im, synom Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 3, 'Każde miejsce, po którym będzie stąpać wasza noga, dałem wam, jak obiecałem Mojżeszowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 4, 'Od pustyni i od Libanu aż do wielkiej rzeki, rzeki Eufrat, cała ziemia Chetytów, aż do Morza Wielkiego na zachodzie, będzie wasza granica.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 5, 'Nikt nie ostoi się przed tobą po wszystkie dni twego życia; jak byłem z Mojżeszem, tak będę z tobą. Nie porzucę cię ani cię nie opuszczę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 6, 'Wzmocnij się i bądź mężny. Ty bowiem dasz temu ludowi w dziedzictwo ziemię, którą przysiągłem dać ich ojcom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 7, 'Tylko wzmocnij się i bądź bardzo mężny, abyś pilnował wypełniania wszystkiego według prawa, które nakazał ci Mojżesz, mój sługa. Nie odstępuj od niego ani na prawo, ani na lewo, aby ci się wiodło, dokądkolwiek pójdziesz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 8, 'Niech ta księga Prawa nie oddala się od twoich ust, ale rozmyślaj o niej we dnie i w nocy, abyś pilnował wypełnienia wszystkiego, co w niej jest napisane. Wtedy bowiem poszczęści się twojej drodze i będzie ci się wiodło.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 9, 'Czyż ci nie nakazałem? Wzmocnij się i bądź mężny. Nie lękaj się i nie przerażaj, gdyż Pan, twój Bóg, jest z tobą, dokądkolwiek pójdziesz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 10, 'Wtedy Jozue rozkazał przełożonym ludu:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 11, 'Przejdźcie przez obóz i rozkażcie ludowi: Przygotujcie sobie żywność, bo za trzy dni przejdziecie przez ten Jordan, aby wejść i posiąść ziemię, którą Pan, wasz Bóg, daje wam w posiadanie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 12, 'A do Rubenitów, Gadytów i połowy pokolenia Manassesa Jozue powiedział:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 13, 'Przypomnijcie sobie słowo, które nakazał wam Mojżesz, sługa Pana: Pan, wasz Bóg, zapewnił wam odpoczynek i dał wam tę ziemię;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 14, 'Niech wasze żony, dzieci i bydło zostaną w ziemi, którą Mojżesz dał wam po tej stronie Jordanu; wy zaś, wszyscy dzielni wojownicy, pójdziecie uzbrojeni przed waszymi braćmi i będziecie im pomagać;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 15, 'Aż Pan da odpoczynek waszym braciom, jak i wam, i oni posiądą ziemię, którą daje im Pan, wasz Bóg. Potem wrócicie do ziemi swojej posiadłości, którą dał wam Mojżesz, sługa Pana, po tej stronie Jordanu na wschodzie, i posiądziecie ją.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 16, 'I odpowiedzieli Jozuemu: Wszystko, co nam nakazałeś, uczynimy i gdziekolwiek nas poślesz, pójdziemy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 17, 'Jak byliśmy posłuszni Mojżeszowi we wszystkim, tak będziemy posłuszni i tobie. Niech tylko Pan, twój Bóg, będzie z tobą, jak był z Mojżeszem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 18, 'Ktokolwiek sprzeciwi się twemu rozkazowi i nie będzie posłuszny twoim słowom we wszystkim, co mu rozkażesz, niech umrze. Tylko wzmocnij się i bądź mężny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 1, 'Potem Jozue, syn Nuna, wysłał potajemnie z Szittim dwóch szpiegów, mówiąc: Idźcie, obejrzyjcie ziemię i Jerycho. Poszli więc i weszli do domu pewnej nierządnicy, która miała na imię Rachab, i tam odpoczęli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 2, 'I doniesiono królowi Jerycha: Oto jacyś mężczyźni spośród synów Izraela przyszli tu tej nocy, aby wybadać tę ziemię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 3, 'Król Jerycha posłał więc do Rachab, rozkazując: Wyprowadź mężczyzn, którzy przyszli do ciebie i weszli do twego domu, bo przyszli wybadać całą tę ziemię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 4, 'Kobieta jednak wzięła tych dwóch mężczyzn, ukryła ich i powiedziała: To prawda, że przyszli do mnie mężczyźni, ale nie wiedziałam, skąd oni są.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 5, 'A gdy miano zamykać bramę o zmierzchu, mężczyźni ci wyszli i nie wiem, dokąd poszli. Ścigajcie ich prędko, to ich dogonicie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 6, 'Ona zaś zaprowadziła ich na dach i przykryła wiązkami lnu, które rozłożyła na dachu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 7, 'Wysłani mężczyźni ścigali ich w kierunku Jordanu aż do brodów; i jak tylko ścigający wyszli, zamknięto bramę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 8, 'A zanim usnęli, ona wyszła do nich na dach;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 9, 'I powiedziała do tych mężczyzn: Wiem, że Pan dał wam tę ziemię, bo strach przed wami padł na nas i wszyscy obywatele tej ziemi truchleją przed wami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 10, 'Słyszeliśmy bowiem, jak Pan wysuszył przed wami wody Morza Czerwonego, gdy wychodziliście z Egiptu, i co uczyniliście dwom królom amorejskim, którzy byli po tamtej stronie Jordanu, Sichonowi i Ogowi, których pobiliście.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 11, 'Gdy o tym usłyszeliśmy, nasze serca struchlały i nie było już odwagi w nikim z waszego powodu; bo Pan, wasz Bóg, jest Bogiem wysoko na niebie i nisko na ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 12, 'Dlatego teraz, proszę, przysięgnijcie mi na Pana, że jak ja okazałam wam miłosierdzie, tak i wy okażecie miłosierdzie domowi mego ojca, i dajcie mi pewny znak;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 13, 'Że zachowacie przy życiu mego ojca i moją matkę, moich braci i moje siostry, i wszystko, co do nich należy, i ocalicie nas od śmierci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 14, 'Odpowiedzieli jej mężczyźni: Ręczymy za was naszym życiem, jeśli nie wydacie tej naszej sprawy, i gdy Pan odda nam tę ziemię, okażemy ci miłosierdzie i wierność.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 15, 'Potem spuściła ich na sznurze z okna, bo jej dom przylegał do muru i ona mieszkała w murze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 16, 'I powiedziała im: Idźcie w góry, by nie spotkali was ścigający; ukryjcie się tam przez trzy dni, aż powrócą ścigający, a potem pójdziecie swoją drogą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 17, 'Mężczyźni powiedzieli jej: Będziemy wolni od tej przysięgi, którą kazałaś nam złożyć;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 18, 'Gdy wejdziemy do ziemi, przywiążesz do okna czerwony sznur, po którym nas spuściłaś, i zbierzesz u siebie, w domu swego ojca, swoją matkę, swoich braci i cały dom swego ojca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 19, 'Ktokolwiek bowiem wyjdzie poza drzwi twego domu, jego krew spadnie mu na głowę, a my będziemy bez winy. Lecz krew każdego, kto będzie z tobą w domu, spadnie na naszą głowę, jeśli czyjaś ręka go dotknie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 20, 'Jeśli jednak wydasz naszą sprawę, będziemy wolni od przysięgi, którą kazałaś nam złożyć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 21, 'I odpowiedziała: Jak powiedzieliście, niech tak będzie. Wtedy wypuściła ich i poszli. I przywiązała czerwony sznur do okna.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 22, 'Odeszli więc i przyszli na górę, i pozostali tam przez trzy dni, aż powrócili ścigający. A ścigający szukali ich po wszystkich drogach, ale nie znaleźli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 23, 'I zawrócili ci dwaj mężczyźni, zeszli z góry, przeprawili się przez rzekę, przyszli do Jozuego, syna Nuna, i opowiedzieli mu wszystko, co się z nimi działo;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 24, 'I mówili do Jozuego: Pan oddał w nasze ręce całą tę ziemię, bo wszyscy obywatele tej ziemi struchleli przed nami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 1, 'Jozue wstał wcześnie rano i on oraz wszyscy synowie Izraela wyruszyli z Szittim, i przyszli nad Jordan; i tam przenocowali, zanim się przeprawili przez rzekę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 2, 'A po upływie trzech dni przełożeni przeszli przez obóz;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 3, 'I rozkazali ludowi: Gdy ujrzycie arkę przymierza Pana, swojego Boga, i niosących ją kapłanów Lewitów, wy także wyruszycie ze swego miejsca i pójdziecie za nią.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 4, 'Pomiędzy wami a nią niech będzie jednak odległość około dwóch tysięcy łokci. Nie zbliżajcie się do niej, abyście poznali drogę, którą macie iść, gdyż nie szliście tą drogą nigdy dotąd.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 5, 'Wtedy Jozue powiedział do ludu: Poświęćcie się, gdyż jutro Pan dokona cudów pośród was.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 6, 'Do kapłanów zaś Jozue powiedział: Weźcie arkę przymierza i idźcie przed ludem. Wzięli więc arkę przymierza i szli przed ludem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 7, 'I Pan powiedział do Jozuego: Dziś zacznę cię wywyższać na oczach całego Izraela, aby poznali, że jak byłem z Mojżeszem, tak będę i z tobą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 8, 'Rozkaż kapłanom niosącym arkę przymierza: Gdy dojdziecie do brzegu wód Jordanu, zatrzymajcie się w Jordanie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 9, 'Wtedy Jozue powiedział do synów Izraela: Zbliżcie się i słuchajcie słów Pana, swojego Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 10, 'I Jozue dodał: Po tym poznacie, że Bóg żywy jest wśród was i że na pewno wypędzi przed wami Kananejczyków, Chetytów, Chiwwitów, Peryzzytów, Girgaszytów, Amorytów i Jebusytów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 11, 'Oto arka przymierza Pana całej ziemi przejdzie przed wami przez Jordan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 12, 'Teraz więc wybierzcie sobie dwunastu mężczyzn z pokoleń Izraela, po jednym z każdego pokolenia;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 13, 'A gdy stopy kapłanów niosących arkę Pana, Pana całej ziemi, staną w wodzie Jordanu, wtedy wody Jordanu się rozdzielą i wody płynące z góry staną jak jeden wał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 14, 'Gdy więc lud wyruszył ze swoich namiotów, aby przeprawić się przez Jordan, a kapłani niosący arkę przymierza szli przed ludem;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 15, 'I kiedy niosący arkę przyszli nad Jordan, a nogi kapłanów, którzy nieśli arkę, zanurzyły się w wodzie przy brzegu (Jordan bowiem wzbiera i wylewa na wszystkie swoje brzegi przez cały czas żniwa);');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 16, 'Wtedy wody płynące z góry zatrzymały się i stanęły jak jeden wał bardzo daleko od miasta Adam leżącego w pobliżu Sartan. A te, które płynęły w dół do Morza Pustyni, czyli do Morza Słonego, odpłynęły zupełnie. I tak lud przeprawił się naprzeciw Jerycha.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 17, 'A kapłani niosący arkę przymierza Pana stali pewnie na suchej ziemi pośrodku Jordanu, a wszyscy Izraelici szli po suchej ziemi, aż cały lud przeprawił się przez Jordan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 1, 'A gdy cały lud zakończył przeprawę przez Jordan, Pan powiedział do Jozuego:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 2, 'Wybierzcie sobie z ludu dwunastu mężczyzn, po jednym z każdego pokolenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 3, 'I rozkażcie im: Weźcie sobie stąd, ze środka Jordanu, z tego miejsca, gdzie nogi kapłanów stały pewnie, dwanaście kamieni, zabierzcie je ze sobą i połóżcie w miejscu, gdzie tej nocy będziecie nocować.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 4, 'Jozue wezwał więc dwunastu mężczyzn, których wybrał spośród synów Izraela, po jednym z każdego pokolenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 5, 'I Jozue powiedział do nich: Pójdźcie przed arką Pana, swojego Boga, na środek Jordanu i niech każdy weźmie po jednym kamieniu na swe ramię, według liczby pokoleń synów Izraela;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 6, 'Aby to było znakiem wśród was, gdy potem wasi synowie zapytają: Co znaczą dla was te kamienie?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 7, 'Wtedy powiecie im, że wody Jordanu rozdzieliły się przed arką przymierza Pana; gdy przechodziła przez Jordan, rozdzieliły się wody Jordanu; i te kamienie będą pamiątką dla synów Izraela na wieki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 8, 'I synowie Izraela uczynili tak, jak rozkazał Jozue. Wzięli dwanaście kamieni ze środka Jordanu, jak powiedział Pan do Jozuego, według liczby pokoleń synów Izraela, zanieśli je ze sobą na miejsce noclegu i tam je złożyli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 9, 'Jozue też postawił dwanaście kamieni na środku Jordanu, w miejscu, gdzie stały nogi kapłanów niosących arkę przymierza. Pozostają tam aż do dziś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 10, 'Kapłani zaś niosący arkę stali na środku Jordanu, aż wypełniło się to wszystko, co Pan rozkazał Jozuemu powiedzieć ludowi zgodnie ze wszystkim, co Mojżesz nakazał Jozuemu. Lud natomiast spieszył się i przeszedł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 11, 'Gdy cały lud przeszedł, przeszli też i arka Pana, i kapłani przed ludem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 12, 'Synowie Rubena, synowie Gada i połowa pokolenia Manassesa również przeszli uzbrojeni przed synami Izraela, jak im Mojżesz nakazał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 13, 'Około czterdziestu tysięcy uzbrojonych wojowników przeszło przed Panem do walki na równinach Jerycha.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 14, 'W tym dniu Pan wywyższył Jozuego na oczach całego Izraela i bali się go, jak bali się Mojżesza przez wszystkie dni jego życia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 15, 'Potem Pan powiedział do Jozuego:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 16, 'Rozkaż kapłanom niosącym arkę świadectwa, aby wyszli z Jordanu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 17, 'Rozkazał więc Jozue kapłanom: Wyjdźcie z Jordanu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 18, 'A gdy kapłani niosący arkę przymierza Pana wyszli ze środka Jordanu i stopy ich stanęły na suchej ziemi, wody Jordanu wróciły na swoje miejsce i płynęły jak przedtem, wypełnione po brzegi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 19, 'Lud wyszedł z Jordanu dziesiątego dnia pierwszego miesiąca i rozbił obóz w Gilgal, po wschodniej stronie Jerycha.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 20, 'A te dwanaście kamieni, które wyniesiono z Jordanu, Jozue ustawił w Gilgal.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 21, 'I powiedział do synów Izraela: Gdy w przyszłości wasi synowie zapytają swoich ojców: Co znaczą te kamienie?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 22, 'Wtedy powiecie swoim synom: Izrael przeszedł przez Jordan po suchej ziemi;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 23, 'Pan Bóg bowiem osuszył wody Jordanu przed wami, aż się przeprawiliście – tak jak Pan, wasz Bóg, uczynił z Morzem Czerwonym, które wysuszył przed nami, aż przeszliśmy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 24, 'Aby wszystkie narody ziemi poznały, że ręka Pana jest potężna, i żebyście bali się Pana, swojego Boga, po wszystkie dni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 1, 'A gdy wszyscy królowie amoryccy, którzy mieszkali po zachodniej stronie Jordanu, i wszyscy królowie Kanaanu, którzy mieszkali nad morzem, usłyszeli, że Pan wysuszył wody Jordanu przed synami Izraela, aż się przeprawili, struchlało ich serce i stracili całą odwagę wobec synów Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 2, 'W tym czasie Pan powiedział do Jozuego: Zrób sobie ostre noże i ponownie obrzezaj synów Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 3, 'Jozue zrobił więc sobie ostre noże i obrzezał synów Izraela na pagórku napletków.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 4, 'A oto powód, dla którego Jozue ich obrzezał: Cały lud, który wyszedł z Egiptu, płci męskiej, wszyscy wojownicy, pomarli na pustyni, w drodze po wyjściu z Egiptu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 5, 'Cały lud, który wyszedł, był obrzezany. Lecz cały lud, który urodził się na pustyni, w drodze po wyjściu z Egiptu, nie był obrzezany.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 6, 'Czterdzieści lat bowiem synowie Izraela chodzili po pustyni, aż wymarł cały naród wojowników, którzy wyszli z Egiptu, gdyż nie słuchali głosu Pana. Przysiągł im Pan, że nie pozwoli im zobaczyć ziemi, którą Pan pod przysięgą obiecał ich ojcom, że nam ją da, ziemię opływającą mlekiem i miodem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 7, 'Ich synów, których wzbudził na ich miejsce, Jozue obrzezał. Byli bowiem nieobrzezani, gdyż ich nie obrzezano w drodze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 8, 'A gdy już cały lud został obrzezany, pozostał on na swoim miejscu w obozie aż do wyzdrowienia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 9, 'Potem Pan powiedział do Jozuego: Dzisiaj zdjąłem z was hańbę Egiptu. Dlatego to miejsce nazywa się Gilgal aż do dziś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 10, 'Wtedy synowie Izraela rozbili obóz w Gilgal i obchodzili święto Paschy czternastego dnia tego miesiąca, wieczorem, na równinach Jerycha.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 11, 'Nazajutrz po święcie Paschy jedli z plonów tej ziemi, chleby przaśne i prażone ziarno, tego samego dnia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 12, 'I następnego dnia po tym, jak zaczęli jeść zboża tej ziemi, ustała manna; i synowie Izraela już więcej manny nie mieli, ale jedli tegoroczne plony ziemi Kanaan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 13, 'A gdy Jozue był w pobliżu Jerycha, podniósł oczy i spojrzał, a oto mąż stał naprzeciw niego z wydobytym mieczem w ręku. Jozue podszedł do niego i zapytał: Czy ty jesteś po naszej stronie, czy po stronie naszych wrogów?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 14, 'A on odpowiedział: Nie, gdyż jako wódz wojska Pana teraz przyszedłem. Wtedy Jozue upadł twarzą do ziemi, oddał pokłon i zapytał: Co mój Pan rozkaże swemu słudze?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 15, 'I wódz wojska Pana powiedział do Jozuego: Zdejmij obuwie ze swoich nóg, bo miejsce, na którym stoisz, jest święte. I Jozue tak uczynił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 1, 'A Jerycho było szczelnie zamknięte z powodu synów Izraela. Nikt z niego nie wychodził i nikt do niego nie wchodził.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 2, 'Wtedy Pan powiedział do Jozuego: Oto dałem w twoje ręce Jerycho, jego króla i jego dzielnych wojowników.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 3, 'I wy, wszyscy wojownicy, będziecie obchodzić miasto, okrążając je raz. Uczynicie tak przez sześć dni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 4, 'A siedmiu kapłanów będzie niosło przed arką siedem trąb z rogów baranich. Siódmego zaś dnia obejdziecie miasto siedem razy, a kapłani będą dąć w trąby.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 5, 'A gdy przeciągle będą trąbić w baranie rogi i usłyszycie głos trąby, cały lud wzniesie wielki okrzyk, a mury miasta runą i lud wejdzie do miasta, każdy wprost przed siebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 6, 'Wtedy Jozue, syn Nuna, wezwał kapłanów i powiedział im: Weźcie arkę przymierza i niech siedmiu kapłanów niesie siedem trąb z baranich rogów przed arką Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 7, 'Potem powiedział do ludu: Idźcie i obejdźcie miasto, a uzbrojeni wojownicy niech idą przed arką Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 8, 'A gdy Jozue powiedział to ludowi, siedmiu kapłanów niosących siedem trąb z baranich rogów wyruszyło przed arką Pana i dęli w trąby. A arka przymierza Pana szła za nimi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 9, 'Uzbrojeni wojownicy zaś szli przed kapłanami, którzy dęli w trąby, a pozostałe oddziały szły za arką. Gdy szli, dęto w trąby.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 10, 'A Jozue nakazał ludowi: Nie krzyczcie, niech nie będzie słychać waszego głosu ani niech żadne słowo nie wyjdzie z waszych ust aż do dnia, w którym wam powiem: Wznieście okrzyk! Wtedy wydacie okrzyk.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 11, 'Tak więc arka Pana okrążyła miasto raz, po czym wrócili do obozu i przenocowali w nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 12, 'Jozue wstał wcześnie rano, a kapłani wzięli arkę Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 13, 'A siedmiu kapłanów niosących siedem trąb z rogów baranich szło nieprzerwanie przed arką Pana, dmąc w trąby. Uzbrojeni wojownicy szli przed nimi, a pozostałe oddziały szły za arką Pana. Gdy szli, dęto w trąby.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 14, 'Na drugi dzień okrążyli miasto raz i wrócili do obozu. Tak czynili przez sześć dni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 15, 'Lecz dnia siódmego wstali rano o świcie i okrążyli miasto w ten sam sposób siedem razy. Tylko tego dnia okrążyli miasto siedem razy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 16, 'A za siódmym razem, gdy kapłani zadęli w trąby, Jozue powiedział do ludu: Wznieście teraz okrzyk, bo Pan wydaje wam miasto.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 17, 'I miasto będzie przeklęte dla Pana, ono samo i wszystko, co się w nim znajduje. Tylko nierządnica Rachab zostanie przy życiu, ona i wszyscy, którzy są z nią w domu, gdyż ukryła posłańców, których wysłaliśmy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 18, 'Wy jednak strzeżcie się tego, co przeklęte, abyście sami nie stali się przekleństwem, gdy weźmiecie z obłożonego przekleństwem, i byście nie ściągnęli przekleństwa na obóz Izraela, i nie sprowadzili na niego nieszczęścia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 19, 'Wszelkie srebro i złoto oraz przedmioty miedziane i żelazne będą poświęcone Panu. Zostaną złożone do skarbca Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 20, 'Wtedy lud wydał okrzyk, gdy zadęto w trąby. A kiedy lud usłyszał dźwięk trąb i wydał potężny okrzyk, runęły mury, a lud wszedł do miasta, każdy prosto przed siebie, i zdobyli miasto;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 21, 'I zniszczyli ostrzem miecza wszystko, co było w mieście: mężczyzn i kobiety, dzieci i starców, woły, owce i osły.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 22, 'Lecz dwóm mężczyznom, którzy wybadali tę ziemię, Jozue powiedział: Wejdźcie do domu nierządnicy i wyprowadźcie stamtąd tę kobietę oraz wszystko, co do niej należy, tak jak jej przysięgliście.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 23, 'Weszli więc młodzieńcy, zwiadowcy, i wyprowadzili Rachab, jej ojca, jej matkę i jej braci oraz wszystko, co do niej należało. Wyprowadzili całą jej rodzinę i zostawili ich poza obozem Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 24, 'A miasto i wszystko, co w nim było, spalili ogniem. Tylko srebro i złoto oraz przedmioty miedziane i żelazne złożyli do skarbca domu Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 25, 'Jozue zostawił przy życiu nierządnicę Rachab, dom jej ojca i wszystko, co do niej należało; mieszka ona w Izraelu aż do dziś, ponieważ ukryła posłańców, których Jozue wysłał na wybadanie Jerycha.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 26, 'W tym czasie Jozue złożył przysięgę: Niech będzie przeklęty przed Panem człowiek, który powstanie i odbuduje to miasto, Jerycho. Na swoim pierworodnym założy jego fundament, a na swoim najmłodszym postawi jego bramy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 27, 'I Pan był z Jozuem, którego sława rozchodziła się po całej ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 1, 'Lecz synowie Izraela dopuścili się przestępstwa na tym, co przeklęte. Akan bowiem, syn Karmiego, syna Zabdiego, syna Zeracha, z pokolenia Judy, wziął z tego, co przeklęte. I zapłonął gniew Pana przeciw synom Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 2, 'Tymczasem Jozue posłał kilku mężczyzn z Jerycha do Aj, które leży blisko Bet-Awen, na wschód od Betel, i powiedział do nich: Idźcie i zbadajcie tę ziemię. Mężczyźni poszli więc i zbadali Aj.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 3, 'Potem wrócili do Jozuego i powiedzieli mu: Niech nie wyrusza cały lud. Niech wyruszy około dwóch lub trzech tysięcy mężczyzn i niech zburzą Aj. Nie trudź całego ludu, bo tamtych jest niewielu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 4, 'Wyruszyło więc z ludu około trzech tysięcy mężczyzn. Uciekli jednak przed ludźmi z Aj.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 5, 'Ludzie z Aj zabili około trzydziestu sześciu z nich. Ścigali ich bowiem od bramy aż do Szebarim i zabili ich, gdy ci schodzili z góry. Dlatego serce ludu omdlało i stało się jak woda.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 6, 'Wtedy Jozue rozdarł swoje szaty, upadł twarzą na ziemię przed arką Pana i leżał tak aż do wieczora, on i starsi Izraela, i sypali proch na swoje głowy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 7, 'Potem Jozue powiedział: Ach, Panie Boże, czemu przeprowadziłeś ten lud za Jordan? Czy po to, aby nas wydać w ręce Amorytów na zniszczenie? Obyśmy raczej pozostali za Jordanem!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 8, 'O Panie, cóż powiem, gdy Izrael uciekł przed swymi wrogami?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 9, 'Usłyszą o tym bowiem Kananejczycy i wszyscy mieszkańcy tej ziemi i otoczą nas zewsząd, i wymażą nasze imię z ziemi. I cóż uczynisz dla swego wielkiego imienia?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 10, 'Wtedy Pan powiedział do Jozuego: Wstań! Dlaczego tak leżysz na swej twarzy?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 11, 'Izrael zgrzeszył, złamali także moje przymierze, które im nakazałem. Wzięli bowiem z tego, co przeklęte, ukradli, skłamali i schowali to wśród swoich rzeczy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 12, 'Dlatego synowie Izraela nie mogli się ostać przed swymi wrogami, ale uciekli przed nimi, bo stali się przekleństwem. Nie będę więcej z wami, jeśli nie wytępicie spośród was tego, co przeklęte.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 13, 'Wstań, poświęć lud i powiedz: Poświęćcie się na jutro, bo tak mówi Pan, Bóg Izraela: Pośród ciebie, Izraelu, jest to, co przeklęte. Nie staniecie przed swymi wrogami, dopóki nie usuniecie spośród siebie tego, co obłożone jest przekleństwem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 14, 'Wystąpicie więc jutro rano według waszych pokoleń. Wówczas pokolenie, które Pan wskaże, wystąpi według rodzin; a rodzina, którą Pan wskaże, wystąpi według domów; a z domu, który Pan wskaże, wystąpią poszczególni mężczyźni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 15, 'A ten, u kogo zostanie znalezione to, co przeklęte, będzie spalony ogniem, on i wszystko, co do niego należy, bo złamał przymierze Pana i dopuścił się haniebnego czynu w Izraelu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 16, 'Jozue wstał więc wcześnie rano i kazał wystąpić Izraelowi według ich pokoleń; i zostało wskazane pokolenie Judy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 17, 'I kazał wystąpić rodzinom Judy, i została wskazana rodzina Zerachitów. Potem kazał wystąpić wszystkim osobom z rodziny Zerachitów i został wskazany dom Zabdiego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 18, 'Następnie kazał wystąpić wszystkim osobom z jego domu i został wskazany Akan, syn Karmiego, syna Zabdiego, syna Zeracha, z pokolenia Judy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 19, 'I Jozue powiedział do Akana: Synu mój, oddaj, proszę, chwałę Panu, Bogu Izraela, i złóż mu wyznanie. Powiedz mi, co uczyniłeś, a nie ukrywaj tego przede mną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 20, 'Wtedy Akan odpowiedział Jozuemu: Rzeczywiście, to ja zgrzeszyłem przeciw Panu, Bogu Izraela. Oto co uczyniłem:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 21, 'Gdy zobaczyłem wśród łupów piękny płaszcz babiloński, dwieście syklów srebra i pręt złota ważący pięćdziesiąt syklów, pożądałem ich i wziąłem je. Oto są one zakopane w ziemi, w środku mego namiotu, a srebro pod nimi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 22, 'Jozue wysłał więc posłańców, którzy pobiegli do namiotu, a oto te rzeczy były ukryte w jego namiocie, a srebro pod nimi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 23, 'I zabrali je z namiotu, przynieśli do Jozuego oraz do wszystkich synów Izraela i położyli je przed Panem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 24, 'Wtedy Jozue i cały Izrael z nim wzięli Akana, syna Zeracha, srebro, płaszcz i pręt złota, jego synów i córki, jego woły, osły, owce, namiot oraz wszystko, co miał, i zaprowadzili ich do doliny Akor.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 25, 'I Jozue powiedział: Dlaczego sprowadziłeś na nas nieszczęście? Pan dzisiaj sprowadzi nieszczęście na ciebie. I cały lud Izraela ukamienował go, a po ukamienowaniu ich spalili ogniem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 26, 'Potem wznieśli nad nim wielki stos kamieni, który trwa aż do dziś. I Pan odwrócił się od zapalczywości swego gniewu. Dlatego to miejsce nazywa się doliną Akor aż do dziś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 1, 'Potem Pan powiedział do Jozuego: Nie bój się ani się nie lękaj. Weź ze sobą wszystkich wojowników, powstań i wyrusz do Aj. Patrz, daję w twoje ręce króla Aj, jego lud i jego ziemię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 2, 'I postąpisz z Aj i jego królem tak, jak postąpiłeś z Jerychem i jego królem. Tym razem weźmiecie sobie jego łupy i bydło. Zastaw zasadzkę na miasto od jego tyłu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 3, 'Powstali więc Jozue i wszyscy wojownicy, by wyruszyć przeciwko Aj. Jozue wybrał trzydzieści tysięcy bardzo dzielnych mężczyzn i wysłał ich nocą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 4, 'I rozkazał im: Uważajcie, przygotujcie zasadzkę za miastem. Nie oddalajcie się od miasta zbyt daleko i bądźcie wszyscy w pogotowiu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 5, 'Ja zaś i cały lud, który jest ze mną, podejdziemy pod miasto; a gdy oni wyjdą nam naprzeciw, jak za pierwszym razem, uciekniemy przed nimi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 6, 'A oni pójdą za nami, aż ich odciągniemy od miasta, bo powiedzą: Uciekają przed nami, tak jak za pierwszym razem, gdyż będziemy uciekać przed nimi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 7, 'Wtedy wyjdziecie z zasadzki i opanujecie miasto. Pan bowiem, wasz Bóg, odda je w wasze ręce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 8, 'A gdy zdobędziecie miasto, podpalicie je. Postąpicie zgodnie ze słowem Pana. Patrzcie, ja to wam rozkazuję.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 9, 'Jozue więc ich wysłał, a oni poszli przygotować zasadzkę; i zostali między Betel a Aj, na zachód od Aj. Jozue zaś spędził tę noc wśród ludu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 10, 'Następnego dnia Jozue wstał wcześnie rano, obliczył lud i poszedł przed nim wraz ze starszymi Izraela przeciwko Aj.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 11, 'Wszyscy wojownicy, którzy z nim byli, wyruszyli, przybyli pod miasto i rozbili obóz po północnej stronie Aj, tak że między nimi a Aj była dolina.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 12, 'Następnie wziął około pięciu tysięcy mężczyzn, których umieścił w zasadzce między Betel a Aj, po zachodniej stronie miasta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 13, 'I ustawiono lud, całe wojsko po północnej stronie miasta, a tych, którzy przygotowali zasadzkę – po zachodniej stronie. Jozue zaś wyruszył tej nocy na środek doliny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 14, 'Gdy spostrzegł to król Aj, ludzie z miasta pośpieszyli się, wstali wcześnie rano i wyruszyli do walki z Izraelem – on i cały jego lud – w wyznaczonym czasie przed równiną. Nie wiedział jednak, że za miastem została przygotowana na nich zasadzka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 15, 'Wtedy Jozue i cały Izrael udawali pokonanych przez nich i uciekali drogą wiodącą ku pustyni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 16, 'I zwołano cały lud, który był w mieście, aby ich ścigać. Ścigali więc Jozuego i zostali odciągnięci od miasta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 17, 'W Aj i Betel nie pozostał nikt, kto by nie wyruszył za Izraelem; i pozostawili miasto otwarte, i ścigali Izraelitów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 18, 'Wtedy Pan powiedział do Jozuego: Podnieś oszczep, który masz w ręce, w kierunku Aj, gdyż dam je w twoje ręce. I Jozue podniósł oszczep, który miał w ręce, w kierunku miasta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 19, 'A gdy tylko podniósł rękę, ludzie, którzy byli w zasadzce, powstali szybko ze swego miejsca, pobiegli i weszli do miasta, zajęli je i szybko podpalili.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 20, 'A gdy ludzie z Aj obejrzeli się, zobaczyli, że dym wznosi się z miasta ku niebu, a nie mieli siły uciekać ani w jedną, ani w drugą stronę. Tymczasem lud, który uciekał na pustynię, zwrócił się przeciw ścigającym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 21, 'Jozue bowiem i cały lud Izraela zobaczyli, że ludzie z zasadzki zajęli miasto i że z miasta unosi się dym, zawrócili więc i zaczęli zabijać ludzi z Aj.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 22, 'A drudzy wyszli im naprzeciw z miasta i zostali oni otoczeni przez Izraelitów, jedni z jednej, a drudzy z drugiej strony. I zabili ich tak, że nikt z nich nie pozostał przy życiu ani nie uciekł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 23, 'Króla Aj jednak pojmali żywcem i przyprowadzili do Jozuego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 24, 'Gdy więc Izraelici wybili wszystkich mieszkańców Aj na polu, na pustyni, gdzie ich ścigali, i gdy wszyscy oni polegli od miecza, aż zostali zgładzeni, wszyscy Izraelici zawrócili do Aj i pobili je ostrzem miecza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 25, 'Wszystkich poległych tego dnia, mężczyzn i kobiet, było dwanaście tysięcy, byli to wszyscy mieszkańcy Aj.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 26, 'A Jozue nie opuścił ręki, którą wyciągnął z oszczepem, aż zgładził wszystkich mieszkańców Aj.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 27, 'Tylko bydło i łupy tego miasta Izraelici podzielili między siebie według słowa Pana, które przekazał on Jozuemu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 28, 'Wtedy Jozue spalił Aj i uczynił je wieczną mogiłą i pustynią aż do dziś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 29, 'A króla Aj powiesił na drzewie aż do wieczora. A gdy słońce zaszło, Jozue kazał zdjąć jego zwłoki z drzewa i porzucić je przy samej bramie miasta, i wznieść nad nim wielki stos kamieni, który trwa aż do dziś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 30, 'Wtedy Jozue zbudował ołtarz dla Pana, Boga Izraela, na górze Ebal;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 31, 'Jak nakazał synom Izraela Mojżesz, sługa Pana, i jak jest napisane w księdze Prawa Mojżesza: ołtarz z całych kamieni, których nie tknęło żadne żelazo. I na nim złożyli Panu całopalenia i ofiary pojednawcze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 32, 'Tam też napisał na kamieniach odpis Prawa Mojżesza, który napisał w obecności synów Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 33, 'A cały Izrael oraz jego starsi, przełożeni i sędziowie stali po obu stronach arki przed kapłanami lewitami, którzy nosili arkę przymierza Pana, zarówno przybysz, jak i rodowity, połowa ich naprzeciw góry Gerizim, a połowa naprzeciw góry Ebal jak przedtem nakazał Mojżesz, sługa Pana, aby błogosławić lud Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 34, 'Potem czytał wszystkie słowa prawa, błogosławieństwa i przekleństwa według wszystkiego, co zostało napisane w księdze Prawa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 35, 'Nie było ani jednego słowa ze wszystkiego, co Mojżesz nakazał, którego Jozue nie odczytał przed całym zgromadzeniem Izraela, przed kobietami, dziećmi i przybyszami, którzy mieszkali wśród nich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 1, 'A gdy usłyszeli o tym wszyscy królowie, którzy byli po tej stronie Jordanu w górach, na równinach i nad całym brzegiem Morza Wielkiego aż po Liban: Chetyci, Amoryci, Kananejczycy, Peryzzyci, Chiwwici i Jebusyci:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 2, 'Zebrali się razem, aby jednomyślnie walczyć przeciw Jozuemu i Izraelowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 3, 'Lecz mieszkańcy Gibeonu, gdy usłyszeli o tym, co Jozue uczynił z Jerychem i Aj;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 4, 'Użyli podstępu i wyruszyli, udając posłów, i wzięli stare wory na swoje osły i stare, popękane i połatane bukłaki na wino;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 5, 'I stare, i połatane obuwie na nogi, stare szaty na siebie, a cały chleb, który ze sobą zabrali w drogę, był suchy i spleśniały.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 6, 'Wtedy przybyli do Jozuego, do obozu w Gilgal, i powiedzieli do niego i do mężczyzn Izraela: Przyszliśmy z dalekiego kraju. Zawrzyjcie więc teraz przymierze z nami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 7, 'Lecz mężczyźni Izraela odpowiedzieli Chiwwitom: A może mieszkacie wśród nas, jakże więc możemy zawrzeć z wami przymierze?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 8, 'A oni powiedzieli Jozuemu: Jesteśmy twoimi sługami. I Jozue zapytał ich: Kim jesteście i skąd przybywacie?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 9, 'Odpowiedzieli mu: Twoi słudzy przybyli z bardzo dalekiego kraju ze względu na imię Pana, twego Boga. Usłyszeliśmy bowiem o jego sławie oraz o wszystkim, co uczynił w Egipcie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 10, 'I o wszystkim, co uczynił dwom królom amoryckim, którzy byli za Jordanem, Sichonowi, królowi Cheszbonu, i Ogowi, królowi Baszanu, który był w Asztarot.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 11, 'I nasi starsi i wszyscy mieszkańcy naszego kraju nakazali nam: Weźcie ze sobą żywność na drogę, wyjdźcie im naprzeciw i powiedzcie im: Jesteśmy waszymi sługami, zawrzyjcie więc teraz przymierze z nami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 12, 'Ten nasz chleb był jeszcze ciepły, gdy wzięliśmy go z naszych domów w dniu, kiedy wyruszyliśmy do was; a teraz jest suchy i spleśniały.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 13, 'I te bukłaki na wino, które napełniliśmy, były nowe, a oto popękały. Także nasze szaty i obuwie zniszczyły się z powodu bardzo długiej podróży.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 14, 'A mężczyźni Izraela wzięli z ich żywności, lecz nie radzili się Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 15, 'Wtedy Jozue zawarł z nimi pokój i ustanowił z nimi przymierze, że zachowa ich przy życiu. Także naczelnicy zgromadzenia im przysięgli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 16, 'Lecz po trzech dniach, po zawarciu z nimi przymierza, usłyszeli, że są oni sąsiadami i że mieszkają wśród nich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 17, 'Wtedy synowie Izraela wyruszyli i po trzech dniach dotarli do ich miast. Miastami ich były: Gibeon, Kefira, Beerot i Kiriat-Jearim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 18, 'I nie wytracili ich synowie Izraela, gdyż naczelnicy zgromadzenia przysięgli im na Pana, Boga Izraela. I całe zgromadzenie szemrało przeciw naczelnikom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 19, 'I wszyscy naczelnicy powiedzieli do całego zgromadzenia: Przysięgliśmy im na Pana, Boga Izraela, dlatego teraz nie możemy ich tknąć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 20, 'Tak więc postąpimy z nimi: zachowamy ich przy życiu, żeby nie spadł na nas gniew z powodu przysięgi, którą im złożyliśmy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 21, 'Ponadto naczelnicy powiedzieli im: Niech pozostaną przy życiu, ale niech rąbią drewno i noszą wodę dla całego zgromadzenia – zgodnie z tym, co obiecali naczelnicy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 22, 'Potem Jozue wezwał ich i zapytał: Dlaczego nas oszukaliście, mówiąc: Jesteśmy z bardzo daleka, skoro mieszkacie wśród nas?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 23, 'Teraz więc jesteście przeklęci i nie przestaniecie być niewolnikami rąbiącymi drewno i noszącymi wodę dla domu mego Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 24, 'Oni odpowiedzieli Jozuemu: Oznajmiono dokładnie twoim sługom, że Pan, twój Bóg, rozkazał swemu słudze Mojżeszowi dać wam całą ziemię i zgładzić przed wami wszystkich mieszkańców tej ziemi. Dlatego bardzo się baliśmy o nasze życie z waszego powodu i dlatego tak postąpiliśmy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 25, 'A teraz oto jesteśmy w twoich rękach. Uczyń z nami to, co uważasz za dobre i słuszne.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 26, 'I postąpił tak z nimi, i wybawił ich z rąk synów Izraela, żeby ich nie zabili.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 27, 'I w tym dniu Jozue nakazał im narąbać drewna i nosić wodę dla zgromadzenia oraz dla ołtarza Pana w miejscu, które miał wybrać. I jest tak aż do dziś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 1, 'A gdy Adonisedek, król Jerozolimy, usłyszał, że Jozue zdobył Aj i zburzył je – bo jak uczynił z Jerychem i jego królem, tak uczynił z Aj i jego królem – i że mieszkańcy Gibeonu zawarli pokój z Izraelem i mieszkają wśród nich;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 2, 'Bardzo się przestraszył, ponieważ Gibeon był wielkim miastem, jak jedno z miast królewskich, i ponieważ był większy niż Aj, a wszyscy jego mężczyźni byli waleczni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 3, 'Adonisedek, król Jerozolimy, posłał więc wezwanie do Hohama, króla Hebronu, do Pirama, króla Jarmutu, do Jafii, króla Lakisz, i do Debira, króla Eglonu:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 4, 'Przyjdźcie do mnie i pomóżcie mi, abyśmy zwalczyli Gibeonitów, ponieważ zawarli pokój z Jozuem i synami Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 5, 'Zebrało się więc i wyruszyło pięciu królów amoryckich: król Jerozolimy, król Hebronu, król Jarmutu, król Lakisz, król Eglonu, oni sami i całe ich wojska, rozbili obóz naprzeciwko Gibeonu i uderzyli na niego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 6, 'Wtedy mieszkańcy Gibeonu posłali prośbę do Jozuego i do obozu w Gilgal: Nie cofaj swej ręki od swych sług. Przybądź do nas szybko, wybaw nas i pomóż nam, gdyż zebrali się przeciwko nam wszyscy królowie amoryccy, którzy mieszkają w górach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 7, 'Wyruszył więc Jozue z Gilgal, on i wszyscy wojownicy z nim, i wszyscy dzielni wojownicy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 8, 'I Pan powiedział do Jozuego: Nie bój się ich, gdyż oddałem ich w twoje ręce i żaden z nich nie ostoi się przed tobą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 9, 'Jozue uderzył więc na nich znienacka – całą noc ciągnął z Gilgal.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 10, 'I Pan rozgromił ich przed Izraelem, który zadał im wielką klęskę w Gibeonie, i ścigał ich drogą wznoszącą się do Bet-Choron, i bił ich aż do Azeki i Makkedy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 11, 'A gdy uciekali przed Izraelem i zbiegali do Bet-Choron, Pan zrzucał na nich z nieba wielkie kamienie aż do Azeki, i umarli. Więcej ich zginęło od kamieni gradowych niż tych, których synowie Izraela zabili mieczem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 12, 'Tego dnia, kiedy Pan oddał Amorytów w ręce synów Izraela, Jozue powiedział do Pana na oczach Izraela: Słońce, zatrzymaj się nad Gibeonem, a ty, księżycu, w dolinie Ajjalonu!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 13, 'I zatrzymało się słońce, i księżyc stanął, aż zemścił się lud na swych wrogach. Czy nie jest to napisane w księdze Jaszara? Zatrzymało się więc słońce pośrodku nieba i nie śpieszyło się zachodzić niemal przez cały dzień.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 14, 'I nie było podobnego dnia, w którym Pan wysłuchał głosu człowieka, ani przedtem, ani potem. Pan bowiem walczył za Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 15, 'Potem Jozue wrócił wraz z całym Izraelem do obozu w Gilgal.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 16, 'A tych pięciu królów uciekło i skryło się w jaskini w Makkedzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 17, 'I doniesiono o tym Jozuemu: Znaleziono pięciu królów, którzy się ukryli w jaskini w Makkedzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 18, 'I Jozue powiedział: Zatoczcie wielkie kamienie do wejścia jaskini i postawcie przy niej ludzi, aby ich strzegli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 19, 'Wy zaś nie zatrzymujcie się, ścigajcie waszych wrogów i uderzcie na nich od tyłu. Nie pozwólcie im uciec do swoich miast. Pan bowiem, wasz Bóg, oddał ich w wasze ręce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 20, 'A gdy Jozue i synowie Izraela zadali im wielką klęskę, wytracając ich doszczętnie, wtedy ci, którzy pozostali przy życiu, uciekli do warownych miast.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 21, 'Wtedy cały lud wrócił bezpiecznie do obozu, do Jozuego w Makkedzie. Nikt nie odważył się nawet ust otworzyć przeciw synom Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 22, 'Potem Jozue powiedział: Otwórzcie wejście do jaskini i wyprowadźcie do mnie tych pięciu królów z jaskini.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 23, 'I uczynili tak, i wyprowadzili do niego tych pięciu królów z jaskini: króla Jerozolimy, króla Hebronu, króla Jarmutu, króla Lakisz i króla Eglonu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 24, 'A gdy wyprowadzili tych królów do Jozuego, Jozue zwołał wszystkich mężczyzn Izraela i powiedział do dowódców wojowników, którzy mu towarzyszyli: Zbliżcie się i postawcie swoje nogi na karkach tych królów. Zbliżyli się więc i postawili swoje nogi na ich karkach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 25, 'Wtedy Jozue powiedział do nich: Nie bójcie się ani nie lękajcie, wzmocnijcie się i bądźcie mężni. Tak bowiem uczyni Pan wszystkim waszym wrogom, z którymi będziecie walczyć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 26, 'Potem Jozue uderzył ich, zabił i powiesił na pięciu drzewach. I wisieli na drzewach aż do wieczora.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 27, 'A gdy zaszło słońce, Jozue rozkazał, aby zdjęto ich z drzew i wrzucono do jaskini, w której się ukrywali, a wejście do jaskini zawalono wielkimi kamieniami, które są tam aż do dziś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 28, 'Tego samego dnia Jozue zdobył Makkedę i pobił ją ostrzem miecza; zabił też jej króla oraz wszelką duszę, która tam była. Nikogo nie pozostawił przy życiu i uczynił z królem Makkedy tak, jak uczynił z królem Jerycha.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 29, 'Potem Jozue wraz z całym Izraelem wyruszył z Makkedy do Libny i walczył przeciw Libnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 30, 'A Pan także i ją oraz jej króla oddał w ręce Izraela, i pobił ją ostrzem miecza, i wszelką duszę, która w niej była. Nikogo w niej nie pozostawił przy życiu i uczynił z jej królem tak, jak uczynił z królem Jerycha.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 31, 'Potem Jozue wraz z całym Izraelem wyruszył z Libny do Lakisz, obległ je i walczył przeciw niemu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 32, 'I Pan oddał Lakisz w ręce Izraela, i zdobył je na drugi dzień, i pobili je ostrzem miecza, a także wszelką duszę, która w nim była, tak samo jak uczynił w Libnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 33, 'Wtedy Horam, król Gezer, przybył na ratunek Lakisz, ale Jozue pobił go i jego lud, tak że nikogo w nim nie pozostawił przy życiu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 34, 'Potem Jozue wraz z całym Izraelem wyruszył z Lakisz do Eglonu; oblegli go i walczyli przeciwko niemu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 35, 'I zdobyli go tego samego dnia, i pobili go ostrzem miecza. Wszelką duszę, która w nim była, zabił tego samego dnia, tak samo jak uczynił w Lakisz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 36, 'Potem Jozue wraz z całym Izraelem wyruszył z Eglonu do Hebronu i walczyli przeciwko niemu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 37, 'I zdobyli go, i pobili ostrzem miecza wraz z jego królem, wszystkie jego miasta, a także wszelką duszę, która w nim była. Nikogo nie pozostawił przy życiu, tak samo jak uczynił w Eglonie. Wytracił go oraz wszelką duszę, która w nim była.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 38, 'Stamtąd Jozue wraz z całym Izraelem wrócił do Debiru i walczył przeciwko niemu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 39, 'I zdobył go, jego króla i wszystkie jego miasta; pobili go ostrzem miecza i wytracili wszystkie dusze, które w nim były. Nikogo nie pozostawił przy życiu; jak uczynił z Hebronem, tak uczynił z Debirem i jego królem, i jak przedtem uczynił z Libną i jej królem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 40, 'W ten sposób Jozue pobił całą ziemię górną i południową, i polną, i podgórną oraz wszystkich ich królów. Nikogo nie pozostawił przy życiu, ale wytracił wszystkie dusze, tak jak mu rozkazał Pan, Bóg Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 41, 'I Jozue pobił ich od Kadesz-Barnea aż do Gazy oraz całą ziemię Goszen aż do Gibeonu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 42, 'A wszystkich tych królów oraz ich ziemie Jozue zdobył za jednym razem, gdyż Pan, Bóg Izraela, walczył za Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 43, 'Potem Jozue wrócił wraz z całym Izraelem do obozu w Gilgal.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 1, 'A gdy usłyszał o tym Jabin, król Chasoru, posłał wiadomość do Jobaba, króla Madonu, do króla Szimronu, do króla Akszafu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 2, 'I do królów, którzy byli na północy, w górach i na polach, na południe od Kinneret, na równinach i w krainach Dor na zachodzie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 3, 'Do Kananejczyków na wschodzie i na zachodzie, do Amorytów, Chetytów, Peryzzytów, Jebusytów w górach i Chiwwitów pod górą Hermon, w ziemi Mispa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 4, 'I wyruszyli oni wraz z całym swym wojskiem, lud liczny jak piasek na brzegu morskim, mający bardzo wiele koni i rydwanów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 5, 'A gdy wszyscy ci królowie zgromadzili się, przybyli i razem rozbili obóz nad wodami Meromu, aby walczyć przeciwko Izraelowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 6, 'I Pan powiedział do Jozuego: Nie bój się ich, bo jutro o tej porze wydam ich wszystkich pobitych Izraelowi. Ich koniom podetniesz ścięgna, a ich rydwany spalisz ogniem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 7, 'Wtedy Jozue i cały waleczny lud z nim wyruszyli niespodziewanie przeciwko nim nad wody Meromu i napadli na nich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 8, 'I Pan wydał ich w ręce Izraela, który pobił ich i ścigał aż do Sydonu Wielkiego i aż do Misreft-Maim, i aż do doliny Mispa na wschodzie. Pobili ich tak, że nikogo nie pozostawili przy życiu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 9, 'I Jozue uczynił im tak, jak mu Pan rozkazał: ich koniom podciął ścięgna, a ich rydwany spalił ogniem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 10, 'W tym czasie Jozue zawrócił i zdobył Chasor, a jego króla zabił mieczem. Chasor bowiem był przedtem głową wszystkich tych królestw.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 11, 'Każdą duszę, która w nim była, pobili ostrzem miecza, wytracając ją. Nikt nie pozostał przy życiu, a Chasor spalił ogniem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 12, 'Jozue zdobył też wszystkie miasta tych królów i pojmał wszystkich królów, pobił ich ostrzem miecza i wytracił, tak jak nakazał Mojżesz, sługa Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 13, 'Izrael nie spalił jednak żadnego z miast warownych, oprócz samego Chasoru, który spalił Jozue.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 14, 'Cały łup tych miast oraz bydło synowie Izraela zabrali dla siebie; tylko wszystkich ludzi pobili ostrzem miecza, aż ich zgładzili, nie zostawiając nikogo przy życiu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 15, 'Jak Pan rozkazał Mojżeszowi, swemu słudze, tak Mojżesz nakazał Jozuemu i tak Jozue uczynił; nie zaniedbał niczego z tego wszystkiego, co Pan rozkazał Mojżeszowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 16, 'Tak Jozue zdobył całą ziemię: góry i całą ziemię na południu, całą ziemię Goszen, równiny, pola i górę Izrael z jej równiną;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 17, 'Od góry Halak, która wznosi się ku Seirowi, aż do Baal-Gad w dolinie Libanu pod górą Hermon. A wszystkich królów pojmał, pobił i pozabijał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 18, 'Przez długi czas Jozue prowadził wojnę z tymi wszystkimi królami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 19, 'Nie było miasta, które by zawarło pokój z synami Izraela, oprócz Chiwwitów, którzy mieszkali w Gibeonie; wszystkie inne zdobyli podczas wojny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 20, 'Od Pana bowiem wyszło, by zatwardzić ich serca, aby wyruszali na bitwę z Izraelem i żeby ich wyniszczył bez miłosierdzia, aż do wytracenia, jak Pan rozkazał Mojżeszowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 21, 'W tym czasie Jozue wyruszył i wytracił Anakitów z gór, z Hebronu, z Debiru, z Anabu, ze wszystkich gór Judy i ze wszystkich gór Izraela. Jozue zniszczył ich razem z ich miastami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 22, 'Nikt z Anakitów nie został w ziemi synów Izraela; zostali tylko w Gazie, w Gat i w Azdodzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 23, 'Zdobył więc Jozue całą ziemię, tak jak Pan powiedział do Mojżesza, i oddał ją Jozue jako dziedzictwo Izraelowi zgodnie z ich przydziałami według pokoleń. I ziemia zaznała pokoju od wojny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 1, 'A oto królowie ziemi, których pobili synowie Izraela i posiedli ich ziemię za Jordanem na wschodzie, od rzeki Arnon aż do góry Hermon, i całą równinę na wschodzie:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 2, 'Sichon, król Amorytów, który mieszkał w Cheszbonie, a panował od Aroeru, leżącego nad brzegiem rzeki Arnon, i od połowy tej rzeki oraz połowy Gileadu aż do rzeki Jabbok, granicy synów Ammona;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 3, 'A od równin aż do morza Kinneret na wschodzie, i aż do Morza Równiny, czyli Morza Słonego, na wschód, w kierunku Bet-Jeszimot, i od południa pod górę Pisga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 4, 'I obszar Oga, króla Baszanu, który pozostał z Refaitów i mieszkał w Asztarot i w Edrei;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 5, 'Panował on na górze Hermon, i w Salce oraz w całym Baszanie aż do granic Geszurytów i Maakatytów i nad połową Gileadu, granicą Sichona, króla Cheszbonu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 6, 'Pobił ich Mojżesz, sługa Pana, wraz z synami Izraela. I Mojżesz, sługa Pana, dał tę ziemię w posiadanie Rubenitom i Gadytom, i połowie pokolenia Manassesa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 7, 'A oto królowie ziemi, których pobili Jozue i synowie Izraela po zachodniej stronie Jordanu, od Baal-Gad w dolinie Libanu aż do góry Chalak, która wznosi się ku Seirowi, a których obszar Jozue dał pokoleniom Izraela w posiadanie według ich przydziałów;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 8, 'Na górach, na równinach, na polach, na nizinach, na pustyni i na południowej ziemi; ziemie Chetytów, Amorytów, Kananejczyków, Peryzzytów, Chiwwitów i Jebusytów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 9, 'Król Jerycha – jeden; król Aj, które jest obok Betel – jeden.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 10, 'Król Jerozolimy – jeden; król Hebronu – jeden.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 11, 'Król Jarmutu – jeden; król Lakisz – jeden.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 12, 'Król Eglonu – jeden; król Gezer – jeden.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 13, 'Król Debir – jeden; król Gederu – jeden.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 14, 'Król Chormy – jeden; król Aradu – jeden.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 15, 'Król Libny – jeden; król Adullam – jeden.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 16, 'Król Makkedy – jeden; król Betel – jeden.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 17, 'Król Tappuach – jeden; król Cheferu – jeden.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 18, 'Król Afek – jeden; król Laszaronu – jeden.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 19, 'Król Madonu – jeden; król Chasoru – jeden.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 20, 'Król Szimron-Meronu – jeden; król Achszafu – jeden.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 21, 'Król Tanaku – jeden; król Megiddo – jeden.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 22, 'Król Kedeszu – jeden; król Jokneamu z Karmelu – jeden.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 23, 'Król Doru z krainy Dor – jeden; król narodów z Gilgal – jeden.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 24, 'Król Tirsy – jeden. Wszystkich królów było trzydziestu jeden.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 1, 'I gdy Jozue zestarzał się i był w podeszłym wieku, Pan powiedział do niego: Zestarzałeś się i posunąłeś się w latach, a pozostało jeszcze dużo ziemi do zdobycia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 2, 'Oto ziemia, która pozostała: wszystkie okręgi Filistynów i Geszurytów;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 3, 'Od Szichoru, który jest naprzeciw Egiptu, aż do granicy Akaronu na północy – jest to ziemia przynależąca do Kananejczyków, pięciu książąt filistyńskich: z Gazy, Aszdodu, Aszkelonu, Gat i Ekronu, oraz Awwici;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 4, 'Od południa: cała ziemia Kananejczyków oraz Meara, która należy do Sydończyków, aż do Afek i aż do granicy Amorytów;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 5, 'I ziemia Gibilitów i cały Liban na wschodzie, od Baal-Gad pod górę Hermon, aż do wejścia do Chamat.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 6, 'Wszystkich mieszkańców gór od Libanu aż do Misrefot-Maim i wszystkich Sydończyków wypędzę przed synami Izraela. Tylko podziel ją losem między Izraelitów jako dziedzictwo, tak jak ci rozkazałem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 7, 'Rozdziel więc teraz tę ziemię jako dziedzictwo dziewięciu pokoleniom i połowie pokolenia Manassesa;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 8, 'Gdyż z drugą połową Rubenici i Gadyci otrzymali już swoje dziedzictwo, które dał im Mojżesz za Jordanem na wschodzie, jak przydzielał im Mojżesz, sługa Pana;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 9, 'Od Aroeru, leżącego nad brzegiem rzeki Arnon, i od miasta, które jest w środku rzeki, wraz z całą równiną Medeby aż do Dibonu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 10, 'I wszystkie miasta Sichona, króla Amorytów, który królował w Cheszbonie, aż do granicy synów Ammona;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 11, 'Także Gilead i obszar Geszurytów i Maakatytów, całą górę Hermon i cały Baszan aż do Salka;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 12, 'Całe królestwo Oga w Baszanie, który królował w Asztarot i w Edrei; był on ostatnim z Refaitów, których Mojżesz pobił i wypędził.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 13, 'Lecz synowie Izraela nie wypędzili Geszurytów i Maakatytów, dlatego Geszuryci i Maakatyci mieszkają pośród Izraelitów do dziś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 14, 'Tylko pokoleniu Lewiego nie dał dziedzictwa; ofiary spalane dla Pana, Boga Izraela, są jego dziedzictwem, jak mu Bóg powiedział.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 15, 'Mojżesz dał więc pokoleniu synów Rubena dziedzictwo według ich rodzin.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 16, 'Ich granica była od Aroeru, leżącego nad brzegiem rzeki Arnon, i od miasta, które jest w środku rzeki, wraz z całą równiną ku Medebie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 17, 'Cheszbon i wszystkie przyległe do niego miasta, które były na równinie: Dibon, Bamot-Baal i Bet-Baal-Meon;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 18, 'Jahaza, Kedemot i Mefaat;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 19, 'Kiriataim, Sibma i Seret-Haszszachar na górze w dolinie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 20, 'Bet-Peor, Aszdod-Pisga i Bet-Jeszimot.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 21, 'I wszystkie miasta na równinie oraz całe królestwo Sichona, króla Amorytów, który królował w Cheszbonie, a którego Mojżesz zabił tak jak książąt Midianu: Ewi, Rekem, Sur, Chur, Reba, książęta Sichona zamieszkali w tej ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 22, 'I wróżbitę Balaama, syna Beora, wraz z innymi zabitymi synowie Izraela zabili mieczem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 23, 'Granicą synów Rubena był Jordan ze swymi granicami. Oto dziedzictwo synów Rubena według ich rodzin, miast i przyległych do nich wsi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 24, 'Mojżesz dał też dziedzictwo pokoleniu Gada, synom Gada według ich rodzin.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 25, 'A ich granice obejmowały Jazer i wszystkie miasta Gileadu oraz połowę ziemi synów Ammona aż do Aroeru leżącego naprzeciw Rabby;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 26, 'I od Cheszbonu aż do Ramat-Mispa i Betonim oraz od Machanaim aż do granicy Debiru.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 27, 'W dolinie zaś: Bet-Haram, Bet-Nimra, Sukkot i Safon, resztę królestwa Sichona, króla Cheszbonu, Jordan i jego pogranicze aż do końca morza Kinneret po wschodniej stronie Jordanu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 28, 'Oto dziedzictwo synów Gada według ich rodzin, miast i przyległych do nich wsi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 29, 'Mojżesz dał też posiadłość połowie pokolenia Manassesa; przypadła ona połowie pokolenia synów Manassesa według ich rodzin.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 30, 'Ich granica była od Machanaim, obejmowała cały Baszan i całe królestwo Oga, króla Baszanu oraz wszystkie wsie Jaira, które są w Baszanie, sześćdziesiąt miast.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 31, 'Połowę Gileadu, Asztarot i Erdei, miasta królestwa Oga w Baszanie, dał synom Makira, syna Manassesa, a ściśle – połowie synów Makira według ich rodzin.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 32, 'Oto posiadłości, które Mojżesz podzielił na polach Moabu za Jordanem, naprzeciw Jerycha na wschodzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 33, 'Lecz pokoleniu Lewiego Mojżesz nie dał dziedzictwa, gdyż Pan, Bóg Izraela, sam jest ich dziedzictwem, jak im to powiedział.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 1, 'A oto co synowie Izraela odziedziczyli w ziemi Kanaan, co przydzielili im jako dziedzictwo kapłan Eleazar i Jozue, syn Nuna, oraz naczelnicy wśród ojców pokoleń synów Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 2, 'Ich dziedzictwa dokonano za pomocą losów, jak Pan rozkazał przez Mojżesza, dla dziewięciu i pół pokolenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 3, 'Gdyż Mojżesz dał dziedzictwo dwom pokoleniom i połowie pokolenia za Jordanem, ale Lewitom nie dał dziedzictwa wśród nich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 4, 'Synowie Józefa stanowili bowiem dwa pokolenia: Manassesa i Efraima. Lewitom więc nie dano udziału w ziemi oprócz miast do zamieszkania z przyległymi do nich pastwiskami dla ich stad i dobytku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 5, 'Jak Pan rozkazał Mojżeszowi, tak postąpili synowie Izraela i podzielili ziemię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 6, 'Wtedy synowie Judy przyszli do Jozuego w Gilgal i powiedział do niego Kaleb, syn Jefunnego, Kenizzyta: Ty wiesz, co Pan powiedział Mojżeszowi, mężowi Boga, o mnie i o tobie w Kadesz-Barnea.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 7, 'Miałem czterdzieści lat, gdy Mojżesz, sługa Pana, posłał mnie z Kadesz-Barnea na wybadanie ziemi i przyniosłem mu wiadomość zgodnie z tym, co miałem w sercu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 8, 'Lecz moi bracia, którzy chodzili ze mną, zatrwożyli serce ludu. Ja zaś poszedłem całkowicie za Panem, swoim Bogiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 9, 'W tym dniu Mojżesz przysiągł: Zaprawdę, ziemia, którą deptała twoja noga, stanie się dziedzictwem twoim i twoich synów na wieki, ponieważ całkowicie poszedłeś za Panem, moim Bogiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 10, 'A teraz oto Pan zachował mnie przy życiu, jak powiedział; już minęło czterdzieści pięć lat od tego czasu, kiedy Pan powiedział to do Mojżesza, gdy Izraelici wędrowali po pustyni. I oto mam dziś osiemdziesiąt pięć lat;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 11, 'A jeszcze dziś jestem tak silny, jak byłem w tym dniu, gdy Mojżesz mnie wysłał. Jaka wtedy była moja siła, taka jest teraz moja siła do wojny, by wyruszać i wracać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 12, 'Teraz więc daj mi tę górę, o której Pan powiedział w owym dniu. Sam bowiem słyszałeś tego dnia, że tam są Anakici, a miasta są wielkie i warowne. Jeśli Pan będzie ze mną, wypędzę ich, jak mi Pan obiecał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 13, 'I Jozue błogosławił mu, i dał Kalebowi, synowi Jefunnego, Hebron w dziedzictwo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 14, 'Dlatego Hebron stał się dziedzictwem Kaleba, syna Jefunnego Kenizzyty, aż do dziś, bo całkowicie poszedł za Panem, Bogiem Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 15, 'A Hebron zwano wcześniej Kiriat-Arba. Arba był wielkim człowiekiem wśród Anakitów. A ziemia zaznała pokoju od wojny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 1, 'Taki był los pokolenia synów Judy według ich rodzin: aż do granic Edomu przy pustkowiu Cin na południu sięgał kraniec granicy południowej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 2, 'A ich granica południowa biegła od krańca Morza Słonego, od zatoki zwróconej ku południowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 3, 'I biegła od południa, ku Maale-Akrabbim, i ciągnęła się aż do Cin; a wznosząc się na południu do Kadesz-Barnea, przebiegała do Chesronu, i wznosiła się do Addary, i skręcała do Karka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 4, 'Stamtąd przechodziła do Asmon i dochodziła do rzeki Egiptu, a kończyła się przy morzu. Taka będzie wasza granica na południu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 5, 'Granicą zaś od wschodu było Morze Słone aż do końca Jordanu, a granica północna była od zatoki morskiej przy ujściu Jordanu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 6, 'Granica ciągnęła się do Bet-Chogla i biegła od północy aż do Bet-Araba; stamtąd granica wznosiła się do kamienia Bohana, syna Rubena.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 7, 'Następnie granica wznosiła się do Debiru od doliny Akor i zwracała się ku północy do Gilgal leżącego naprzeciw wzniesienia Adummim, położonego na południe od rzeki. Dalej granica ciągnęła się do wód En-Szemesz i kończyła się przy En-Rogiel.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 8, 'Dalej granica wznosiła się doliną syna Hinnom do stoku Jebusyty od południa, czyli do Jerozolimy. Stamtąd wznosiła się na szczyt góry położonej naprzeciw doliny Hinnom na zachodzie i na krańcu doliny Refaimitów na północy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 9, 'Potem granica skręcała od szczytu góry aż do źródła wody Neftoach i biegła aż do miast góry Efron; dalej ciągnęła się do Baala, czyli Kiriat-Jearim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 10, 'Następnie granica skręcała od Baala na zachodzie do góry Seir i przechodziła do zbocza góry Jearim od północy, czyli Kesalon, potem schodziła do Bet-Szemesz i przechodziła do Timny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 11, 'Później granica wychodziła do zbocza Ekronu na północy i skręcała do Szikronu, i przebiegała przez górę Baala; stamtąd wychodziła do Jabneel i kończyła się przy morzu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 12, 'A granicą zachodnią było Morze Wielkie i jego wybrzeże. Oto granica synów Judy dokoła według ich rodzin.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 13, 'Kalebowi zaś, synowi Jefunnego, dał Jozue dział pośród synów Judy, jak Pan nakazał Jozuemu, miasto Arba, ojca Anaka, czyli Hebron.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 14, 'I Kaleb wypędził stamtąd trzech synów Anaka: Szeszaja i Achimana, i Talmaja, potomków Anaka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 15, 'Stamtąd wyruszył przeciwko mieszkańcom Debiru, które dawniej nazywało się Kiriat-Sefer.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 16, 'I Kaleb powiedział: Kto pobije Kiriat-Sefer i zdobędzie je, temu dam swoją córkę Aksę za żonę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 17, 'I zdobył je Otniel, syn Kenaza, brata Kaleba; i dał mu swoją córkę Aksę za żonę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 18, 'A gdy ona przyszła do niego, namawiała go, aby prosił jej ojca o pole. Kiedy zsiadła z osła, Kaleb zapytał ją: Czego sobie życzysz?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 19, 'A ona odpowiedziała: Daj mi błogosławieństwo; skoro dałeś mi ziemię południową, daj mi też źródła wód. I dał jej źródła górne i źródła dolne.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 20, 'Oto dziedzictwo pokolenia synów Judy według ich rodzin.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 21, 'Miastami granicznymi pokolenia synów Judy w stronę granicy Edomu na południu były: Kabseel, Eder, Jagur;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 22, 'Kina, Dimona, Adada;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 23, 'Kedesz, Chasor, Jetnan;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 24, 'Zif, Telam, Bealot;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 25, 'Chasor-Chadatta i Keriot-Chesron, czyli Chasor;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 26, 'Amam, Szema, Molada;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 27, 'Hasar-Gadda, Cheszmon, Bet-Pelet;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 28, 'Chasar-Szual, Beer-Szeba, Biziota;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 29, 'Baala, Ijjim, Esem;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 30, 'Eltolad, Kesil, Chorma;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 31, 'Siklag, Madmana, Sansanna;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 32, 'Lebaot, Szilchim, Ain i Rimmon. Wszystkich miast było dwadzieścia dziewięć z przyległymi do nich wioskami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 33, 'Na nizinie: Esztaol, Sorea, Aszna;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 34, 'Zanoach, En-Gannim, Tappuach, Enam;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 35, 'Jarmut, Adullam, Soko, Azeka;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 36, 'Szaaraim, Aditaim, Gedera i Gederotaim: czternaście miast wraz z przyległymi do nich wioskami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 37, 'Senan, Chadasza, Migdal-Gad;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 38, 'Dilan, Mispe, Jokteel;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 39, 'Lakisz, Boskat, Eglon;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 40, 'Kabon, Lachmas, Kitlisz;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 41, 'Gederot, Bet-Dagon, Naama i Makkeda: szesnaście miast wraz z przyległymi do nich wioskami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 42, 'Libna, Eter, Aszan;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 43, 'Jeftach, Aszna, Nesib;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 44, 'Keila, Akzib i Maresza: dziewięć miast wraz z przyległymi do nich wioskami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 45, 'Ekron i przyległe do niego miasteczka i wioski;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 46, 'Od Ekronu aż do morza wszystkie miasta, które leżą w pobliżu Aszdodu, i przyległe do nich wioski;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 47, 'Aszdod i przyległe do niego miasteczka i wioski, Gaza i przyległe do niej miasteczka i wioski, aż do rzeki Egiptu i Morza Wielkiego, które jest granicą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 48, 'A w górach: Szamir, Jattir, Soko;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 49, 'Danna, Kiriat-Sanna, czyli Debir;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 50, 'Anab, Esztemo, Anim;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 51, 'Goszen, Cholon i Gilo: jedenaście miast wraz z przyległymi do nich wioskami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 52, 'Arab, Duma, Eszan;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 53, 'Janum, Bet-Tappuach, Afeka;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 54, 'Chumta, Kiriat-Arba, czyli Hebron, Sijor: dziewięć miast wraz z przyległymi do nich wioskami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 55, 'Maon, Karmel, Zif, Jutta;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 56, 'Jizreel, Jokdeam, Zanoach;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 57, 'Kain, Gibea i Timna: dziesięć miast wraz z przyległymi do nich wioskami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 58, 'Chalchul, Bet-Sur, Gedor;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 59, 'I Maarat, Bet-Anot i Eltekon: sześć miast wraz z przyległymi do nich wioskami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 60, 'Kiriat-Baal, czyli Kiriat-Jearim i Rabba: dwa miasta wraz z przyległymi do nich wioskami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 61, 'A na pustyni: Bet-Araba, Middin, Sekaka;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 62, 'Nibszan, miasto Soli i En-Gedi: sześć miast wraz z przyległymi do nich wioskami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 63, 'Lecz Jebusytów, mieszkańców Jerozolimy, synowie Judy nie mogli wypędzić; dlatego Jebusyci mieszkają z synami Judy w Jerozolimie aż do dziś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 1, 'A los synów Józefa przypadł od Jordanu przy Jerychu do wód Jerycha na wschodzie, do pustyni, która rozciąga się od Jerycha przez górę Betel;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 2, 'Od Betel biegnie do Luz i dalej do granic Archy, do Atarot.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 3, 'Potem ciągnie się ku zachodowi do granicy Jaflety, aż do granicy dolnego Bet-Choron i aż do Gezer, i kończy się przy morzu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 4, 'Tak więc synowie Józefa, Manasses i Efraim, wzięli dziedzictwo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 5, 'A granica synów Efraima według ich rodzin – granica ich dziedzictwa na wschodzie – była od Atarot-Addar aż do górnego Bet-Choron.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 6, 'I ta granica biegła w kierunku morza do Mikmetat na północy, potem skręcała na wschód do Taanat-Szilo i przechodziła obok jej wschodniej strony aż do Janocha;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 7, 'I ciągnęła się od Janocha do Atarot i Naarat, i dochodziła do Jerycha, a kończyła się przy Jordanie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 8, 'Od Tappuach granica biegła na zachód do potoku Kana, a kończyła się przy morzu. Takie było dziedzictwo pokolenia synów Efraima według ich rodzin.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 9, 'Synowie Efraima mieli też wydzielone miasta pośrodku dziedzictwa synów Manassesa – wszystkie te miasta wraz z przyległymi do nich wioskami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 10, 'I nie wygnali Kananejczyków, mieszkających w Gezer. I mieszkają Kananejczycy pośród Efraimitów aż do dziś, i stali się sługami składającymi daninę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 1, 'Los przypadł też pokoleniu Manassesa, bo był on pierworodnym Józefa. Przypadł Makirowi, pierworodnemu Manassesa, ojcu Gileada, a ponieważ był wojownikiem, otrzymał Gilead i Baszan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 2, 'Dział otrzymali też inni synowie Manassesa według ich rodzin: synowie Abiezera, synowie Cheleka, synowie Asriela, synowie Sychema, synowie Chefera i synowie Szemidy. Ci byli synami Manassesa, syna Józefa – mężczyźni według ich rodzin.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 3, 'Lecz Selofchad, syn Chefera, syna Gileada, syna Makira, syna Manassesa, nie miał synów, tylko córki. Oto imiona jego córek: Machla, Noa, Chogla, Milka i Tirsa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 4, 'Przyszły one przed kapłana Eleazara, przed Jozuego, syna Nuna, oraz przed naczelników i powiedziały: Pan rozkazał Mojżeszowi, aby dał nam dziedzictwo pośród naszych braci; i Jozue dał im zgodnie z rozkazem Pana dziedzictwo pośród braci ich ojca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 5, 'I przypadło Manassesowi dziesięć działów oprócz ziemi Gilead i Baszan, które były za Jordanem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 6, 'Córki Manassesa otrzymały bowiem dziedzictwo pośród jego synów, a ziemia Gilead przypadła pozostałym synom Manassesa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 7, 'I granica Manassesa ciągnęła się od Aszera do Michmetat, które leży naprzeciw Szechem, a dalej biegła na prawo do mieszkańców w En-Tappuach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 8, 'Ziemia Tappuach należała do Manassesa, ale Tappuach na granicy Manassesa należało do synów Efraima.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 9, 'Granica ta biegła do potoku Kana, na południe od tego potoku. Te miasta Efraimitów leżą wśród miast Manassesa, ale granica Manassesa biegła od północy tego potoku, a kończyła się przy morzu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 10, 'Na południu był dział Efraima, a na północy Manassesa, a jego granicą było morze. Z Aszerem graniczy na północy, a z Issacharem na wschodzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 11, 'I Manasses posiadał w działach Issachara i Aszera Bet-Szean i przyległe do niego miasteczka, Jibleam i przyległe do niego miasteczka, mieszkańców Dor i przyległe do niego miasteczka, mieszkańców Endor i przyległe do niego miasteczka, mieszkańców Tanaku i przyległe do niego miasteczka oraz mieszkańców Megiddo i przyległe do niego miasteczka – trzy okręgi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 12, 'Lecz synowie Manassesa nie mogli wypędzić z tych miast ich mieszkańców, dlatego Kananejczycy dalej mieszkali w tej ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 13, 'A gdy synowie Izraela wzmocnili się, kazali Kananejczykom płacić daninę, ale nie wypędzili ich całkowicie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 14, 'Wtedy synowie Józefa powiedzieli do Jozuego: Dlaczego dałeś nam w dziedzictwo jeden los i jeden dział? Jesteśmy przecież ludem wielkim i Pan dotychczas nam błogosławił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 15, 'I Jozue odpowiedział im: Jeśli jesteście ludem wielkim, idźcie do lasu i wykarczujcie tam sobie miejsce w ziemi Peryzzytów i Refaitów, skoro za ciasno jest wam na górze Efraim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 16, 'Synowie Józefa odpowiedzieli: Góra nam nie wystarczy, a wszyscy Kananejczycy, którzy mieszkają w dolinach, mają żelazne rydwany, zarówno ci, którzy mieszkają w Bet-Szean i w przyległych do niego miasteczkach, jak i ci, którzy mieszkają w dolinie Jizreel.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 17, 'Wtedy Jozue powiedział do domu Józefa, do Efraima i Manassesa: Jesteś ludem wielkim i twoja moc jest wielka, nie będziesz miał tylko jednego losu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 18, 'Lecz otrzymasz górę; a że tam jest las, to go wykarczujesz i będziesz miał jego granice. Wypędzisz bowiem Kananejczyków, choć mają żelazne rydwany i są potężni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 1, 'Wtedy całe zgromadzenie synów Izraela zebrało się w Szilo i wznieśli tam Namiot Zgromadzenia, gdyż ziemia została przez nich opanowana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 2, 'A pozostało wśród synów Izraela siedem pokoleń, którym nie przydzielono ich dziedzictwa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 3, 'Wtedy Jozue powiedział do synów Izraela: Jak długo będziecie zwlekać z tym, aby wejść i posiąść ziemię, którą dał wam Pan, Bóg waszych ojców?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 4, 'Wybierzcie spośród siebie po trzech mężczyzn z każdego pokolenia, których poślę, aby obeszli ziemię i opisali ją według ich dziedzictwa, a potem powrócą do mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 5, 'I podzielą ją na siedem części: Juda pozostanie w swych granicach na południu, a dom Józefa pozostanie w swych granicach na północy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 6, 'Sporządźcie więc opis ziemi, dzieląc ją na siedem części, i przynieście go tu do mnie, a ja rzucę dla was losy tu przed Panem, naszym Bogiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 7, 'Lewici bowiem nie mają działu pośród was, gdyż ich dziedzictwem jest kapłaństwo Pana; a Gad, Ruben i połowa pokolenia Manassesa otrzymali swe dziedzictwa po wschodniej stronie Jordanu, które dał im Mojżesz, sługa Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 8, 'Wtedy ci mężczyźni wstali i poszli, a Jozue nakazał tym, którzy szli, aby opisali ziemię: Idźcie i obejdźcie ziemię, i opiszcie ją, a potem wróćcie do mnie, a ja rzucę dla was losy przed Panem tu, w Szilo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 9, 'Odeszli więc ci mężczyźni i obchodzili ziemię, i opisali ją w księdze według miast, dzieląc na siedem części; potem wrócili do Jozuego, do obozu w Szilo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 10, 'I Jozue rzucił dla nich losy w Szilo przed Panem, i tam podzielił Jozue ziemię synom Izraela według ich przydziałów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 11, 'I padł los dla pokolenia synów Beniamina według ich rodzin, a granica ich losu wypadła między synami Judy a synami Józefa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 12, 'Ich granica po stronie północnej zaczynała się od Jordanu, biegła na północne zbocze Jerycha, ciągnęła się przez góry na zachód i kończyła się przy pustyni Bet-Awen.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 13, 'A stamtąd granica biegła do Luz, od strony południowej Luz, czyli Betel, a schodziła do Atarot-Addar pod górę, która leży na południe od dolnego Bet-Choron.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 14, 'Potem granica skręcała obok morza na południe od góry położonej naprzeciw Bet-Choron na południu, i kończyła się w Kiriat-Baal, czyli Kiriat-Jearim, mieście synów Judy. To jest strona zachodnia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 15, 'Strona zaś południowa zaczynała się od końca Kiriat-Jearim; następnie granica biegła na zachód i dochodziła do źródła wód Neftoach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 16, 'I granica ta ciągnęła się do końca góry położonej naprzeciw doliny syna Hinnom, leżącej w dolinie Refaim na północy, i schodziła do doliny Hinnom po stronie Jebus na południe, i stamtąd biegła do źródła Rogiel.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 17, 'Potem skręcała na północ i dochodziła do En-Szemesz, i dalej do Gelilot, które jest naprzeciw wzniesienia Adummim, stamtąd schodziła do kamienia Bohana, syna Rubena.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 18, 'Następnie przebiegała ku zboczu, które było naprzeciw Araby na północ, i ciągnęła się do Araby.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 19, 'Stamtąd granica biegła do zbocza Bet-Chogla na północy, a kończyła się przy zatoce północnej Morza Słonego, na południu od ujścia Jordanu. To była granica południowa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 20, 'Jordan zaś stanowi granicę od strony wschodniej. To było dziedzictwo synów Beniamina według otaczających jego granic, według ich rodzin.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 21, 'A miastami pokolenia synów Beniamina według ich rodzin były: Jerycho, Bet-Chogla i dolina Kesis;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 22, 'Bet-Araba, Semaraim, Betel;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 23, 'Awwim, Para, Ofra;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 24, 'Kefar-Ammonaj, Ofni i Geba: dwanaście miast wraz z przyległymi do nich wioskami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 25, 'Gibeon, Rama, Beerot;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 26, 'Mispa, Kefira, Mosa;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 27, 'Rekem, Jerpeel, Tarala;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 28, 'Sela, Elef, Jebus, czyli Jerozolima, Gibeat i Kiriat: czternaście miast wraz z przyległymi do nich wioskami. To było dziedzictwo synów Beniamina według ich rodzin.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 1, 'Potem padł drugi los dla Symeona, dla pokolenia synów Symeona według ich rodzin, a ich dziedzictwo znajdowało się pośród dziedzictwa synów Judy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 2, 'A otrzymali oni w dziedzictwie: Beer-Szeba, Szeba, Molada;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 3, 'Chasar-Szual, Bala, Esem;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 4, 'Eltolad, Betul, Chorma;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 5, 'Siklag, Bet-Markabot, Chasar-Susa;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 6, 'Bet-Lebaot i Szaruchen: trzynaście miast wraz z przyległymi do nich wioskami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 7, 'Ain, Rimmon, Eter, Aszan: cztery miasta wraz z przyległymi do nich wioskami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 8, 'Oraz wszystkie wioski, które były dokoła tych miast, aż do Baalat-Beer, Ramat południowy. To było dziedzictwo pokolenia synów Symeona według ich rodzin.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 9, 'Dziedzictwo synów Symeona zostało wzięte z działu synów Judy, ponieważ dział synów Judy był dla nich zbyt wielki. Synowie Symeona otrzymali więc dziedzictwo pośród ich dziedzictwa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 10, 'Potem padł trzeci los dla synów Zebulona według ich rodzin, a granica ich dziedzictwa sięgała aż do Sarid.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 11, 'A ich granica wznosiła się w kierunku morza do Marala, dochodziła do Dabbeszet i ciągnęła się aż do potoku, który jest naprzeciw Jokneam.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 12, 'I zwracała się od Sarid na wschód do granicy Kislot-Tabor, a stamtąd biegła do Daberat i wznosiła się do Jafia;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 13, 'Stamtąd biegła na wschód do Gat-Chefer, do Et-Kasin, dochodziła do Rimmon i skręcała do Nea.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 14, 'Następnie granica otaczała od północy do Channaton i kończyła się w dolinie Jiftach-El.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 15, 'Obejmowała również Kattat, Nahalal, Szimron, Idala i Betlejem: dwanaście miast wraz z przyległymi do nich wioskami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 16, 'Oto dziedzictwo synów Zebulona według ich rodzin, te miasta i przyległe do nich wioski.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 17, 'Czwarty los przypadł Issacharowi, czyli synom Issachara według ich rodzin.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 18, 'A ich granica obejmowała: Jizreel, Kesulot, Szunem;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 19, 'Chafaraim, Szijon, Anacharat;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 20, 'Rabbit, Kiszjon, Ebes;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 21, 'Remet, En-Gannim, En-Chadda i Bet-Passes.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 22, 'A ich granica dochodziła do Taboru, Szachasima i Bet-Szemesz, a kończyła się przy Jordanie: szesnaście miast i przyległe do nich wioski.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 23, 'Oto dziedzictwo pokolenia synów Issachara według ich rodzin, te miasta oraz przyległe do nich wioski.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 24, 'Potem padł piąty los dla pokolenia synów Aszera według ich rodzin.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 25, 'I ich granica obejmowała: Chelkat, Chali, Beten, Akszaf;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 26, 'Alammelek, Amad i Miszal, a dochodziła do Karmelu na zachodzie i do Szichor-Libnat.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 27, 'Stamtąd skręcała na wschód do Bet-Dagon i biegła aż do Zebulona i do doliny Jiftach-El na północ od Bet-Emek i Neiel i wychodziła do Kabulu po lewej stronie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 28, 'I do Ebronu, Rechobu, Chammonu i Kany aż do Wielkiego Sydonu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 29, 'Potem granica skręcała do Rama aż do warownego miasta Tyr; stamtąd skręcała do Chosa i kończyła się przy morzu, od wybrzeża do Akzibu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 30, 'Obejmowała również Umma, Afek i Rechob: dwadzieścia dwa miasta oraz przyległe do nich wioski.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 31, 'Oto dziedzictwo pokolenia synów Aszera według ich rodzin, te miasta i przyległe do nich wioski.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 32, 'Potem dla synów Neftalego padł szósty los, dla synów Neftalego według ich rodzin.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 33, 'Ich granica biegła od Chelef, od Helon do Saanannim, Adami, czyli Nekeb, oraz Jabneel aż do Lakum i kończyła się przy Jordanie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 34, 'Następnie ta granica skręcała na zachód do Aznot-Tabor, a stamtąd biegła do Chukkok i ciągnęła się na południe do Zebulona, na zachodzie dochodziła do Aszera, a do Judy nad Jordanem na wschodzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 35, 'A miastami warownymi są: Siddim, Ser, Chammat, Rakkat, Kinneret;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 36, 'Adama, Rama, Chasor;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 37, 'Kedesz, Edrei, En-Chasor;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 38, 'Jereon, Migdal-El, Chorem, Bet-Anat i Bet-Szemesz: dziewiętnaście miast oraz przyległe do nich wioski.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 39, 'Oto dziedzictwo pokolenia synów Neftalego według ich rodzin, te miasta oraz przyległe do nich wioski.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 40, 'Potem padł siódmy los dla pokolenia synów Dana według ich rodzin.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 41, 'A granica ich dziedzictwa obejmowała: Sorea, Esztaol, Ir-Szemesz;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 42, 'Szaalabin, Ajjalon, Jitla;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 43, 'Elon, Timna, Ekron;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 44, 'Elteke, Gibbeton, Baalat;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 45, 'Jehud, Bene-Berak, Gat-Rimmon;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 46, 'Me-Jarkon i Rakkon z granicą naprzeciw Jafy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 47, 'Lecz obszar synów Dana był zbyt mały. Synowie Dana wyruszyli więc do walki z Leszem, zdobyli je, pobili je ostrzem miecza, wzięli je w dziedzictwo i mieszkali w nim. I nazwali Leszem Dan, od imienia swego ojca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 48, 'Oto dziedzictwo pokolenia synów Dana według ich rodzin, te miasta oraz przyległe do nich wioski.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 49, 'A gdy dokończyli dzielenie ziemi według jej granic, synowie Izraela dali spośród siebie dziedzictwo Jozuemu, synowi Nuna.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 50, 'Zgodnie z rozkazem Pana dali mu miasto, o które poprosił, Timnat-Serach na górze Efraim, gdzie zbudował miasto i mieszkał w nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 51, 'Oto dziedzictwa, które losem podzielili w posiadanie kapłan Eleazar, Jozue, syn Nuna, i naczelnicy ojców pokoleń synów Izraela w Szilo przed Panem, u wejścia do Namiotu Zgromadzenia, i dokończyli podział ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 1, 'Potem Pan powiedział do Jozuego:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 2, 'Powiedz synom Izraela: Wyznaczcie sobie miasta schronienia, o których mówiłem wam przez Mojżesza;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 3, 'Aby tam uciekał zabójca, który by zabił człowieka niechcący i mimowolnie. Będą dla was schronieniem przed mścicielem krwi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 4, 'Gdy ktoś ucieknie do jednego z tych miast i stanie przy wejściu do bramy miejskiej, opowie do uszu starszych tego miasta swoją sprawę, a oni przyjmą go do miasta do siebie i dadzą mu miejsce, i będzie z nimi mieszkał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 5, 'A gdy będzie go ścigał mściciel krwi, to nie wydadzą zabójcy w jego ręce, gdyż nieumyślnie zabił swego bliźniego i nie czuł do niego przedtem nienawiści.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 6, 'I będzie mieszkał w tym mieście, dopóki nie stanie przed zgromadzeniem na sąd i aż do śmierci najwyższego kapłana, który będzie w tym czasie. Wtedy zabójca wróci i przyjdzie do swego miasta i do swego domu, do miasta, z którego uciekł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 7, 'I wyznaczyli Kedesz w Galilei na górze Neftalego, Sychem na górze Efraim oraz Kiriat-Arba, czyli Hebron, na górze Judy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 8, 'Z drugiej zaś strony Jordanu, na wschód od Jerycha, wyznaczyli Beser na pustyni, na równinie, z pokolenia Rubena, Ramot w Gileadzie z pokolenia Gada oraz Golan w Baszanie z pokolenia Manassesa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 9, 'Oto miasta ucieczki dla wszystkich synów Izraela i cudzoziemców, którzy mieszkają pośród nich, aby mógł tam uciec każdy, kto zabił kogoś przez nieuwagę i nie poniósł śmierci z ręki mściciela krwi, zanim stanie przed zgromadzeniem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 1, 'Wtedy naczelnicy wśród ojców Lewitów przyszli do kapłana Eleazara, do Jozuego, syna Nuna, i do naczelników wśród ojców pokoleń synów Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 2, 'I powiedzieli do nich w Szilo, w ziemi Kanaan: Pan rozkazał przez Mojżesza, abyście nam dali miasta do mieszkania wraz z ich pastwiskami dla naszego bydła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 3, 'Synowie Izraela dali więc Lewitom ze swego dziedzictwa zgodnie ze słowem Pana te miasta oraz ich pastwiska.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 4, 'Padł los dla rodzin Kehatytów: synowie kapłana Aarona spośród Lewitów otrzymali losem trzynaście miast od pokolenia Judy, od pokolenia Symeona i od pokolenia Beniamina.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 5, 'A pozostali synowie Kehata otrzymali losem dziesięć miast od rodzin pokolenia Efraima, od pokolenia Dana i od połowy pokolenia Manassesa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 6, 'A synowie Gerszona otrzymali losem trzynaście miast od rodzin pokolenia Issachara, od pokolenia Aszera, od pokolenia Neftalego i od połowy pokolenia Manassesa w Baszanie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 7, 'Także synowie Merariego według swoich rodzin otrzymali dwanaście miast od pokolenia Rubena, od pokolenia Gada i od pokolenia Zebulona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 8, 'Synowie Izraela dali więc Lewitom przez losowanie te miasta i ich pastwiska, jak rozkazał Pan przez Mojżesza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 9, 'Dali z pokolenia synów Judy i z pokolenia synów Symeona następujące miasta wymienione z nazwy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 10, 'I otrzymali je synowie Aarona, z rodzin Kehatytów, spośród synów Lewiego, gdyż dla nich padł pierwszy los.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 11, 'I dano im miasto Arba, ojca Anaka, czyli Hebron, w górach Judy i leżące wokół niego pastwiska;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 12, 'Ale pole tego miasta i przyległe do niego wioski dano w posiadanie Kalebowi, synowi Jefunnego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 13, 'Synom kapłana Aarona dano miasto schronienia dla zabójcy: Hebron i jego pastwiska, a także Libnę i jej pastwiska;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 14, 'Jattir i jego pastwiska, Esztemoa i jego pastwiska;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 15, 'Cholon i jego pastwiska, Debir i jego pastwiska;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 16, 'Ain i jego pastwiska, Juttę i jej pastwiska oraz Bet-Szemesz i jego pastwiska: dziewięć miast od tych dwóch pokoleń.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 17, 'A od pokolenia Beniamina: Gibeon i jego pastwiska, Gebę i jej pastwiska;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 18, 'Anatot i jego pastwiska, Almon i jego pastwiska: cztery miasta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 19, 'Wszystkich miast synów Aarona, kapłanów, było trzynaście wraz z ich pastwiskami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 20, 'Ale rodzinom synów Kehata, Lewitom, którzy pozostali z synów Kehata, dano przez losowanie miasta od pokolenia Efraima.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 21, 'A dano im miasto schronienia dla zabójcy: Sychem i jego pastwiska na górze Efraim, a także Gezer i jego pastwiska;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 22, 'Kibsaim i jego pastwiska oraz Bet-Choron i jego pastwiska: cztery miasta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 23, 'Także od pokolenia Dana: Elteko i jego pastwiska, Gibbaton i jego pastwiska;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 24, 'Ajjalon i jego pastwiska, Gat-Rimmon i jego pastwiska: cztery miasta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 25, 'A od połowy pokolenia Manassesa: Tanak i jego pastwiska oraz Gat-Rimmon i jego pastwiska: dwa miasta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 26, 'Wszystkich miast wraz z ich pastwiskami dla pozostałych rodzin synów Kehata było dziesięć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 27, 'Synom Gerszona, z rodzin Lewiego, dano od połowy pokolenia Manassesa miasta schronienia dla zabójcy: Golan w Baszanie i jego pastwiska oraz Beeszterę i jej pastwiska: dwa miasta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 28, 'Od pokolenia Issachara Kiszjon i jego pastwiska, Dobrat i jego pastwiska;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 29, 'Jarmut i jego pastwiska oraz En-Gannim i jego pastwiska: cztery miasta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 30, 'A od pokolenia Aszera Miszeal i jego pastwiska, Abdon i jego pastwiska;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 31, 'Chelkat i jego pastwiska oraz Rechob i jego pastwiska: cztery miasta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 32, 'A od pokolenia Neftalego dano miasto schronienia dla zabójcy: Kedesz w Galilei i jego pastwiska, Chammot-Dor i jego pastwiska oraz Kartan i jego pastwiska: trzy miasta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 33, 'Wszystkich miast dla Gerszonitów według ich rodzin było trzynaście wraz z ich pastwiskami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 34, 'Potem rodzinom synów Merariego, pozostałym Lewitom, dano od pokolenia Zebulona: Jokneam i jego pastwiska, Kartę i jej pastwiska;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 35, 'Dimnę i jej pastwiska, Nahalal i jego pastwiska: cztery miasta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 36, 'A od pokolenia Rubena Beser i jego pastwiska, Jahaza i jej pastwiska;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 37, 'Kedemot i jego pastwiska, Mefaat i jego pastwiska: cztery miasta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 38, 'Od pokolenia Gada dano miasta schronienia dla zabójcy: Ramot w Gileadzie i jego pastwiska, Machanaim i jego pastwiska;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 39, 'Cheszbon i jego pastwiska, Jazer i jego pastwiska: razem cztery miasta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 40, 'Wszystkich miast przydzielonych losem dla synów Merariego według ich rodzin, którzy jeszcze pozostali z rodzin Lewitów, było dwanaście.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 41, 'Wszystkich miast Lewitów pośród dziedzictwa synów Izraela było czterdzieści osiem wraz z ich pastwiskami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 42, 'A każde z tych miast miało dokoła siebie pastwiska; tak było z każdym z tych miast.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 43, 'Dał więc Pan Izraelowi całą ziemię, którą przysiągł dać ich ojcom; i posiedli ją, i mieszkali w niej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 44, 'Dał im Pan także odpoczynek ze wszystkich stron, tak jak przysiągł ich ojcom. Nie ostał się przed nimi nikt spośród wszystkich ich wrogów, wszystkich ich wrogów wydał Pan w ich ręce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 45, 'Nie zawiodło żadne słowo ze wszystkich dobrych słów, które Pan obiecał domowi Izraela; wszystko się wypełniło.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 1, 'Wtedy Jozue przywołał Rubenitów, Gadytów oraz połowę pokolenia Manassesa;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 2, 'I powiedział do nich: Strzegliście wszystkiego, co wam nakazał Mojżesz, sługa Pana, i byliście posłuszni memu głosowi we wszystkim, co wam nakazałem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 3, 'Nie opuściliście swoich braci przez ten długi czas aż do dziś, ale strzegliście pilnie rozkazu Pana, waszego Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 4, 'A teraz Pan, wasz Bóg, dał odpoczynek waszym braciom, jak im obiecał. Zawróćcie więc teraz i idźcie do waszych namiotów i do ziemi waszej własności, którą dał wam Mojżesz, sługa Pana, po drugiej stronie Jordanu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 5, 'Tylko uważajcie pilnie, by zachować przykazanie i prawo, które nakazał wam Mojżesz, sługa Pana – abyście miłowali Pana, swojego Boga, kroczyli wszystkimi jego drogami, zachowywali jego przykazania, lgnęli do niego i służyli mu z całego swego serca i z całej swej duszy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 6, 'Potem Jozue błogosławił im i odesłał ich, a oni odeszli do swoich namiotów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 7, 'Mojżesz bowiem dał jednej połowie pokolenia Manassesa posiadłość w Baszanie, ale drugiej jego połowie Jozue dał dział z ich braćmi po zachodniej stronie Jordanu. A gdy Jozue odesłał ich do ich namiotów, błogosławił im.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 8, 'I powiedział do nich: Wracajcie z wielkimi bogactwami do waszych namiotów, z bardzo licznymi stadami, ze srebrem, złotem, miedzią i żelazem oraz z wielką liczbą szat. Podzielcie się ze swymi braćmi łupem po waszych wrogach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 9, 'Wtedy synowie Rubena i synowie Gada oraz połowa pokolenia Manassesa zawrócili i opuścili synów Izraela w Szilo, które leży w ziemi Kanaan, aby pójść do ziemi Gilead, do ziemi swojej własności, którą dziedzicznie otrzymali zgodnie ze słowem Pana za pośrednictwem Mojżesza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 10, 'I gdy przybyli w okolice Jordanu położone w ziemi Kanaan synowie Rubena i synowie Gada oraz połowa pokolenia Manassesa, zbudowali tam ołtarz nad Jordanem, ołtarz wielki i okazały.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 11, 'I synowie Izraela usłyszeli, że mówiono: Oto synowie Rubena, synowie Gada i połowa pokolenia Manassesa zbudowali ołtarz naprzeciw ziemi Kanaan w okolicy Jordanu, gdzie przeszli synowie Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 12, 'Gdy więc synowie Izraela o tym usłyszeli, zebrało się całe zgromadzenie synów Izraela w Szilo, aby wyruszyć przeciw nim na wojnę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 13, 'I synowie Izraela wysłali do synów Rubena, synów Gada i połowy pokolenia Manassesa, do ziemi Gilead, Pinchasa, syna kapłana Eleazara;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 14, 'A z nim dziesięciu naczelników, po jednym z każdego rodu ze wszystkich pokoleń Izraela; każdy naczelnik był głową rodu swoich ojców wśród tysięcy Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 15, 'Ci przyszli do synów Rubena, synów Gada i połowy pokolenia Manassesa, do ziemi Gilead, i powiedzieli do nich:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 16, 'Tak mówi całe zgromadzenie Pana: Cóż to za przestępstwo, którego się dopuściliście wobec Boga Izraela, że odwróciliście się dziś od Pana, budując sobie ołtarz, aby zbuntować się dziś przeciw Panu?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 17, 'Czy mało nam nieprawości popełnionej w Peor, z której nie jesteśmy oczyszczeni po dziś dzień, a za którą na zgromadzenie Pana spadła plaga;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 18, 'Że wy dziś odwróciliście się, żeby nie pójść za Panem? A ponieważ buntujecie się dziś przeciw Panu, jutro on rozgniewa się na całe zgromadzenie Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 19, 'A jeśli ziemia waszej posiadłości jest nieczysta, przeprowadźcie się do ziemi dziedzictwa Pana, w której znajduje się przybytek Pana, i weźcie sobie posiadłości pośród nas; tylko nie buntujcie się przeciw Panu ani nie buntujcie się przeciwko nam, budując sobie ołtarz poza ołtarzem Pana, naszego Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 20, 'Czy to nie Akan, syn Zeracha, dopuścił się przestępstwa przy rzeczach przeklętych i czy gniew nie spadł na całe zgromadzenie Izraela? I nie tylko on umarł za swoją nieprawość.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 21, 'Wtedy synowie Rubena, synowie Gada i połowa pokolenia Manassesa odpowiedzieli naczelnikom nad tysiącami Izraela:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 22, 'Pan, Bóg bogów, Pan, Bóg bogów, on wie, i Izrael też się dowie: Jeśli stało się to przez bunt albo przestępstwo przeciw Panu – niech nas dziś nie oszczędzi;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 23, 'Jeśli zbudowaliśmy sobie ołtarz, aby się odwrócić od Pana i aby składać na nim całopalenia i ofiary pokarmowe lub pojednawcze, to niech Pan to rozezna;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 24, 'Czy nie zrobiliśmy tak raczej z obawy przed tym, że w przyszłości wasi synowie powiedzą naszym synom: Cóż wy macie wspólnego z Panem, Bogiem Izraela?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 25, 'Oto Pan ustanowił Jordan granicą między nami a wami, synowie Rubena i synowie Gada; nie macie działu w Panu. W ten sposób wasi synowie odwrócą naszych synów od bojaźni Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 26, 'Dlatego powiedzieliśmy: Uczyńmy tak i zbudujmy sobie ołtarz, nie do całopaleń ani do innych ofiar;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 27, 'Lecz aby był świadkiem między nami a wami i między naszymi pokoleniami po nas i abyśmy służyli Panu przed jego obliczem w naszych całopaleniach, ofiarach pokarmowych i ofiarach pojednawczych, aby w przyszłości wasi synowie nie powiedzieli naszym synom: Nie macie udziału w Panu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 28, 'Powiedzieliśmy więc: Gdy w przyszłości tak powiedzą nam albo naszemu potomstwu, wtedy odpowiemy: Patrzcie na podobieństwo ołtarza Pana, który wznieśli nasi ojcowie, nie dla całopaleń ani dla innych ofiar, ale żeby był świadkiem między nami a wami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 29, 'Nie daj Boże, żebyśmy mieli buntować się przeciw Panu i odwrócić się dziś od Pana, budując ołtarz do całopaleń, ofiar pokarmowych i innych ofiar poza ołtarzem Pana, naszego Boga, który znajduje się przed jego przybytkiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 30, 'A gdy kapłan Pinchas, naczelnicy zgromadzenia i przełożeni nad tysiącami Izraela, którzy z nim byli, usłyszeli słowa, które mówili synowie Rubena, synowie Gada i synowie Manassesa, uznali je za słuszne.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 31, 'I Pinchas, syn kapłana Eleazara, powiedział do synów Rubena, synów Gada i synów Manassesa: Dzisiaj przekonaliśmy się, że Pan jest pośród nas, bo nie dopuściliście się tego przestępstwa przeciw Panu i wyzwoliliście synów Izraela z ręki Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 32, 'Wtedy Pinchas, syn kapłana Eleazara, oraz naczelnicy powrócili od synów Rubena i od synów Gada z ziemi Gilead do ziemi Kanaan, do synów Izraela, i zdali im sprawę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 33, 'I spodobało się to synom Izraela; synowie Izraela błogosławili Boga i nie mówili więcej o wyruszeniu przeciw nim na wojnę, by zniszczyć ziemię, w której mieszkali synowie Rubena i synowie Gada.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 34, 'Synowie Rubena i Gada nazwali ten ołtarz Ed, mówiąc: Świadkiem będzie między nami, że Pan jest Bogiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 1, 'A po długim czasie, gdy Pan dał Izraelowi odpoczynek od wszystkich ich okolicznych wrogów, a Jozue był już stary i w podeszłym wieku;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 2, 'Jozue przywołał całego Izraela, jego starszych, jego naczelników, jego sędziów i jego przełożonych i powiedział do nich: Jestem już stary i w podeszłym wieku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 3, 'A wy widzieliście wszystko, co Pan, wasz Bóg, uczynił wszystkim tym narodom ze względu na was, gdyż Pan, wasz Bóg, sam walczył za was.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 4, 'Spójrzcie, podzieliłem wam losem narody, które pozostały, jako dziedzictwo dla waszych pokoleń, i wszystkie narody, które wytraciłem, od Jordanu aż do Morza Wielkiego na zachodzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 5, 'A Pan, wasz Bóg, sam je wypędzi przed wami i wygna je sprzed waszych oczu, i posiądziecie dziedzicznie ich ziemię, jak wam to powiedział Pan, wasz Bóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 6, 'Umacniajcie się bardzo, by strzec i wypełniać wszystko, co jest napisane w księdze Prawa Mojżesza, nie odstępując od niego na prawo ani na lewo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 7, 'Nie mieszajcie się z tymi narodami, które pozostały pośród was, ani nie wspominajcie imion ich bogów, ani na nich nie przysięgajcie, ani im nie służcie, ani nie oddawajcie im pokłonu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 8, 'Ale lgnijcie do Pana, swojego Boga, tak jak czyniliście aż do dziś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 9, 'Pan bowiem wypędził przed wami narody wielkie i potężne i nikt nie mógł ostać się przed wami aż do dziś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 10, 'Jeden z was będzie ścigał tysiąc, gdyż Pan, wasz Bóg, sam walczy za was, jak wam obiecał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 11, 'Strzeżcie się więc pilnie, byście miłowali Pana, waszego Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 12, 'Jeśli bowiem odwrócicie się i przylgniecie do pozostałych narodów, do tych, które pozostały pośród was, i spowinowacicie się z nimi, i pomieszacie się z nimi, a one z wami;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 13, 'To wiedzcie na pewno, że Pan, wasz Bóg, nie będzie więcej wyganiał tych narodów przed wami, ale będą dla was sidłem i pułapką, biczem na wasze boki i cierniem dla waszych oczu, aż wyginiecie z tej przewybornej ziemi, którą dał wam Pan, wasz Bóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 14, 'A oto idę dziś drogą całej ziemi; poznajcie więc z całego swojego serca i całą swoją duszą, że nie zawiodło żadne słowo ze wszystkich dobrych słów, które mówił o was Pan, wasz Bóg; wszystkie wam się wypełniły, a nie zawiodło żadne słowo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 15, 'Dlatego tak jak wam się wypełniło każde dobre słowo, które obiecał wam Pan, wasz Bóg, tak Pan sprowadzi na was każde złe słowo, aż was wytraci z tej przewybornej ziemi, którą wam dał Pan, wasz Bóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 16, 'Jeśli złamiecie przymierze Pana, swojego Boga, które wam przykazał, i pójdziecie służyć obcym bogom, i będziecie oddawać im pokłon, wtedy gniew Pana rozpali się przeciw wam i zginiecie prędko z tej przewybornej ziemi, którą wam dał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 1, 'Potem Jozue zebrał wszystkie pokolenia Izraela w Sychem i zwołał starszych Izraela, jego naczelników, jego sędziów i jego przełożonych, a ci stawili się przed Bogiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 2, 'I Jozue powiedział do całego ludu: Tak mówi Pan, Bóg Izraela: Po drugiej stronie rzeki mieszkali od dawnych czasów wasi ojcowie, Terach, ojciec Abrahama i Nachora, i służyli obcym bogom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 3, 'Wtedy zabrałem waszego ojca Abrahama z drugiej strony rzeki i prowadziłem go przez całą ziemię Kanaan, i rozmnożyłem jego potomstwo, dając mu Izaaka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 4, 'Dałem też Izaakowi Jakuba i Ezawa, a Ezawowi dałem górę Seir, aby ją posiadł, ale Jakub i jego synowie zeszli do Egiptu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 5, 'I posłałem Mojżesza i Aarona, i ukarałem Egipt plagami, które uczyniłem pośród niego. Potem wyprowadziłem was.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 6, 'I wyprowadziłem waszych ojców z Egiptu, i przybyliście nad morze, a Egipcjanie ścigali waszych ojców na rydwanach i koniach aż do Morza Czerwonego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 7, 'Wtedy wołali do Pana, a on uczynił ciemność między wami a Egipcjanami i sprowadził na nich morze, które ich okryło. Wasze oczy widziały, co uczyniłem w Egipcie. I przebywaliście na pustyni przez długi czas.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 8, 'Potem przyprowadziłem was do ziemi Amorytów mieszkających za Jordanem, którzy walczyli przeciwko wam; ale oddałem ich w wasze ręce i posiedliście ich ziemię, a zgładziłem ich przed wami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 9, 'Powstał też Balak, syn Sippora, król Moabu, aby walczyć przeciw Izraelowi. Posłał też i wezwał Balaama, syna Beora, aby was przeklinał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 10, 'I nie chciałem słuchać Balaama; dlatego raczej błogosławił wam. I tak wybawiłem was z jego rąk.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 11, 'Przeprawiliście się potem przez Jordan i przyszliście do Jerycha. I walczyli przeciwko wam ludzie z Jerycha, a także Amoryci, Peryzzyci, Kananejczycy, Chetyci, Girgaszyci, Chiwwici i Jebusyci, ale oddałem ich w wasze ręce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 12, 'I wysłałem przed wami szerszenie, które wypędziły przed wami dwóch królów amoryckich – nie twoim mieczem ani twoim łukiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 13, 'I dałem wam ziemię, na której nie trudziliście się, i miasta, których nie budowaliście, a w których mieszkacie; spożywacie z winnic i sadów oliwnych, których nie sadziliście.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 14, 'Teraz więc bójcie się Pana i służcie mu w szczerości i prawdzie. Usuńcie bogów, którym służyli wasi ojcowie za rzeką i w Egipcie, a służcie Panu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 15, 'A jeśli wam się zdaje, że źle jest służyć Panu, wybierzcie sobie dziś, komu będziecie służyć: czy bogom, którym służyli wasi ojcowie po drugiej stronie rzeki, czy bogom Amorytów, w których ziemi mieszkacie. Lecz ja i mój dom będziemy służyli Panu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 16, 'I lud odpowiedział: Nie daj Boże, byśmy mieli opuścić Pana, a służyć cudzym bogom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 17, 'Pan bowiem, nasz Bóg, to on wyprowadził nas i naszych ojców z ziemi Egiptu, z domu niewoli, i uczynił na naszych oczach te wielkie znaki, i strzegł nas przez całą drogę, którą szliśmy, i wśród wszystkich ludów, między którymi przechodziliśmy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 18, 'I Pan wypędził przed nami wszystkie ludy i Amorytów mieszkających na tej ziemi. Tak więc będziemy służyli Panu, bo on jest naszym Bogiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 19, 'Wtedy Jozue powiedział do ludu: Nie możecie służyć Panu, gdyż on jest Bogiem świętym, Bogiem zazdrosnym, nie przebaczy waszych przestępstw ani waszych grzechów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 20, 'Jeśli opuścicie Pana, a będziecie służyli cudzym bogom, odwróci się od was, ześle na was nieszczęście i zniszczy was, choć przedtem dobrze wam czynił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 21, 'I lud odpowiedział Jozuemu: Nie tak, ale Panu będziemy służyć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 22, 'Wtedy Jozue powiedział do ludu: Sami jesteście świadkami przeciwko sobie, że wybraliście sobie Pana, aby mu służyć. A oni powiedzieli: Jesteśmy świadkami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 23, 'I powiedział: Teraz więc usuńcie cudzych bogów, którzy są pośród was, i zwróćcie wasze serca ku Panu, Bogu Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 24, 'I lud odpowiedział Jozuemu: Panu, naszemu Bogu, będziemy służyć i jego głosu będziemy słuchać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 25, 'Tak zawarł Jozue w tym dniu przymierze z ludem i nadał mu w Sychem prawo i nakaz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 26, 'I Jozue spisał te słowa w księdze Prawa Bożego, wziął też wielki kamień i postawił go pod dębem, który był przy świątyni Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 27, 'Wtedy Jozue powiedział do całego ludu: Oto ten kamień będzie dla nas świadkiem, gdyż słyszał wszystkie słowa Pana, które powiedział do nas, i będzie świadkiem przeciwko wam, byście się nie wyparli swojego Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 28, 'Potem Jozue odesłał lud, każdego do swego dziedzictwa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 29, 'Po tych wydarzeniach umarł Jozue, syn Nuna, sługa Pana, mając sto dziesięć lat.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 30, 'I pogrzebali go na obszarze jego dziedzictwa w Timnat-Serach, które znajduje się na górze Efraim, na północ od góry Gaasz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 31, 'Izrael służył Panu przez wszystkie dni Jozuego i przez wszystkie dni starszych, którzy przeżyli Jozuego, a którzy znali wszystkie dzieła Pana, jakie czynił dla Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 32, 'A kości Józefa, które synowie Izraela przenieśli z Egiptu, pogrzebali w Sychem, na części pola, które Jakub kupił od synów Chamora, ojca Sychema, za sto monet. I stało się ono dziedzictwem synów Józefa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 33, 'Umarł również Eleazar, syn Aarona, i pogrzebali go na pagórku Pinchasa, jego syna, który został mu dany na górze Efraim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 1, 'Po śmierci Jozuego synowie Izraela pytali Pana: Któż z nas wyruszy pierwszy przeciwko Kananejczykom, aby walczyć z nimi?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 2, 'I Pan powiedział: Wyruszy Juda. Oto dałem ziemię w jego ręce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 3, 'Juda powiedział do swego brata Symeona: Chodź ze mną do mego losu, a będziemy walczyć z Kananejczykami. Potem ja pójdę z tobą do twego losu. I Symeon poszedł z nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 4, 'Wyruszył więc Juda, a Pan wydał Kananejczyków i Peryzzytów w ich ręce i zabili w Bezek dziesięć tysięcy mężczyzn.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 5, 'W Bezek znaleźli Adoni-Bezeka i walczyli z nim, i zabili Kananejczyków i Peryzzytów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 6, 'I Adoni-Bezek uciekł, oni zaś ścigali go; a gdy go pojmali, ucięli mu kciuki u rąk i paluchy u nóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 7, 'Wtedy Adoni-Bezek powiedział: Siedemdziesięciu królów z obciętymi kciukami u rąk i paluchami u nóg zbierało okruchy pod moim stołem. Jak ja uczyniłem, tak mi Bóg odpłacił. I przyprowadzili go do Jerozolimy, i tam umarł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 8, 'Przedtem bowiem synowie Judy walczyli przeciwko Jerozolimie, zdobyli ją i pobili ostrzem miecza, a miasto spalili ogniem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 9, 'Potem synowie Judy wyruszyli, aby walczyć z Kananejczykami mieszkającymi w górach, na południu i na nizinie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 10, 'Następnie Juda wyruszył przeciwko Kananejczykom, którzy mieszkali w Hebronie (a Hebron przedtem nazywał się Kiriat-Arba), i pobił Szeszaja, Achimana i Talmaja.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 11, 'Stamtąd wyruszył przeciwko mieszkańcom Debiru, a Debir przedtem nazywał się Kiriat-Sefer.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 12, 'I Kaleb powiedział: Temu, kto pobije Kiriat-Sefer i zdobędzie je, dam swoją córkę Aksę za żonę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 13, 'Zdobył je Otniel, syn Kenaza, młodszego brata Kaleba. I dał mu swoją córkę Aksę za żonę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 14, 'A gdy ona przyszła do niego, namawiała go, aby prosił jej ojca o pole; i zsiadła z osła, a Kaleb zapytał ją: Czego sobie życzysz?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 15, 'A ona odpowiedziała: Daj mi błogosławieństwo. Skoro dałeś mi ziemię południową, daj mi też źródła wód. I Kaleb dał jej źródła górne i źródła dolne.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 16, 'Synowie Kenity, teścia Mojżesza, wyruszyli z miasta palm razem z synami Judy na pustynię Judy leżącą na południu od Arad. Gdy tam przybyli, zamieszkali z ludem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 17, 'Potem Juda wyruszył ze swym bratem Symeonem i zabili Kananejczyków mieszkających w Sefat, i zburzyli je, i nazwali to miasto Chorma.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 18, 'Juda zdobył też Gazę wraz z jej granicami, Aszkelon wraz z jego granicami i Ekron wraz z jego granicami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 19, 'I Pan był z Judą, który posiadł górę, lecz nie mógł wypędzić mieszkańców doliny, bo ci mieli żelazne rydwany.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 20, 'Kalebowi zaś dano Hebron, jak powiedział Mojżesz. Stamtąd wygnał on trzech synów Anaka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 21, 'Ale synowie Beniamina nie wygnali Jebusytów mieszkających w Jerozolimie; dlatego Jebusyci mieszkają z synami Beniamina w Jerozolimie aż do dziś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 22, 'Wyruszył też dom Józefa przeciwko Betel, a Pan był z nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 23, 'I dom Józefa wyszpiegował Betel – a miasto to przedtem nazywało się Luz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 24, 'A gdy szpiedzy zobaczyli człowieka wychodzącego z miasta, powiedzieli do niego: Prosimy, pokaż nam wejście do miasta, a okażemy ci miłosierdzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 25, 'I pokazał im wejście do miasta, a oni pobili miasto ostrzem miecza, lecz tego człowieka wraz z całą jego rodziną puścili wolno.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 26, 'I tak człowiek ten udał się do ziemi Chetytów, zbudował miasto i nadał mu nazwę Luz. To jest jego nazwa aż do dziś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 27, 'Manasses nie wypędził też mieszkańców Bet-Szean i jego miasteczek ani mieszkańców Tanaku i jego miasteczek, ani mieszkańców Dor i jego miasteczek, ani mieszkańców Jibleam i jego miasteczek, ani mieszkańców Megiddo i jego miasteczek. Kananejczycy nadal mieszkali więc w tej ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 28, 'A gdy Izrael się wzmocnił, kazał Kananejczykom płacić daninę i nie wygnał ich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 29, 'Także i Efraim nie wypędził Kananejczyków mieszkających w Gezer, dlatego Kananejczycy mieszkali wśród nich w Gezer.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 30, 'Zebulon również nie wypędził mieszkańców Kitron ani mieszkańców Nahalol, dlatego Kananejczycy mieszkali wśród nich i płacili im daninę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 31, 'Aszer także nie wypędził mieszkańców Akko ani mieszkańców Sydonu, Achlab, Akzibu, Chelba, Afik i Rechob.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 32, 'I Aszer mieszkał pośród Kananejczyków mieszkających w tej ziemi, gdyż ich nie wypędził.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 33, 'Neftali też nie wypędził mieszkańców Bet-Szemesz ani mieszkańców Bet-Anat i mieszkał wśród Kananejczyków mieszkających w tej ziemi. Jednakże mieszkańcy Bet-Szemesz i Bet-Anat płacili mu daninę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 34, 'Amoryci zaś wyparli synów Dana w góry, tak że nie pozwalali im schodzić do doliny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 35, 'Amoryci utrzymali się i mieszkali na górze Cheres, w Ajjalonie i w Szaalbin, lecz wzmocniła się ręka domu Józefa i zaczęli mu płacić daninę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 36, 'A granica Amorytów biegła od wzniesienia do Akrabbim, od skały i wyżej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 1, 'I wstąpił Anioł Pana z Gilgal do Bokim, i powiedział: Wyprowadziłem was z Egiptu i przyprowadziłem was do ziemi, którą przysiągłem waszym ojcom, i powiedziałem: Nigdy nie naruszę swego przymierza z wami;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 2, 'Wy jednak nie zawierajcie przymierza z mieszkańcami tej ziemi, a ich ołtarze zburzcie. Lecz nie słuchaliście mojego głosu. Dlaczego tak postąpiliście?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 3, 'Dlatego też powiedziałem: Nie wypędzę ich przed wami, lecz będą wam jak ciernie na boki, a ich bogowie będą dla was sidłem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 4, 'Gdy Anioł Pana wypowiedział te słowa do wszystkich synów Izraela, lud podniósł głos i zapłakał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 5, 'Nadali temu miejscu nazwę Bokim i tam złożyli Panu ofiarę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 6, 'Gdy Jozue rozesłał lud, synowie Izraela rozeszli się, każdy do swego dziedzictwa, aby posiąść ziemię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 7, 'Lud służył Panu przez wszystkie dni Jozuego i przez wszystkie dni starszych, którzy przeżyli Jozuego i widzieli wszystkie wielkie dzieła Pana, jakie uczynił dla Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 8, 'A Jozue, syn Nuna, sługa Pana, umarł w wieku stu dziesięciu lat;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 9, 'I pogrzebali go na obszarze jego dziedzictwa w Timnat-Cheres, na górze Efraim, na północ od góry Gaasz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 10, 'Także całe to pokolenie zostało przyłączone do swoich ojców. I powstało po nim inne pokolenie, które nie znało Pana ani też dzieł, których dokonał dla Izraela;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 11, 'I synowie Izraela czynili to, co złe w oczach Pana, i służyli Baalom;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 12, 'I opuścili Pana, Boga swoich ojców, który wyprowadził ich z ziemi Egiptu, i poszli za cudzymi bogami, za bogami okolicznych narodów, i oddawali im pokłon, i tak pobudzili Pana do gniewu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 13, 'Opuścili Pana, a służyli Baalowi i Asztartom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 14, 'Wtedy zapłonął gniew Pana przeciw Izraelowi, wydał ich w ręce grabieżców, którzy ich grabili, i sprzedał ich w ręce ich okolicznych wrogów, tak że nie mogli się dalej ostać przed swymi wrogami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 15, 'A gdziekolwiek wyruszyli, ręka Pana była przeciwko nim ku nieszczęściu, jak Pan powiedział i jak Pan im przysiągł; i byli bardzo uciskani.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 16, 'Potem Pan wzbudził sędziów, którzy ich wyzwalali z rąk grabieżców;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 17, 'Lecz także swoich sędziów nie słuchali, ale uprawiali nierząd z obcymi bogami i oddawali im pokłon. Szybko zboczyli z drogi, którą kroczyli ich ojcowie, słuchający przykazań Pana; ci tak nie postępowali.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 18, 'A gdy Pan wzbudzał im sędziów, to Pan był z każdym sędzią i wybawiał ich z rąk ich wrogów przez wszystkie dni sędziego. Pan bowiem litował się nad ich jękiem z powodu tych, którzy ich uciskali i trapili.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 19, 'Jednak po śmierci sędziego odwracali się i psuli się bardziej niż ich ojcowie, chodząc za cudzymi bogami i służąc im oraz oddając im pokłon; nie odstępowali od swoich czynów ani od swej upartej drogi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 20, 'Zapłonął więc gniew Pana przeciw Izraelowi i powiedział: Ponieważ ten naród złamał moje przymierze, które zawarłem z jego ojcami, i nie usłuchał mojego głosu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 21, 'Ja też odtąd nie wypędzę przed nim żadnego z narodów, które pozostawił Jozue, kiedy umarł;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 22, 'Aby przez nie doświadczyć Izraela, czy będą strzec drogi Pana, aby po niej kroczyć, jak strzegli jej ich ojcowie, czy też nie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 23, 'Pan więc pozostawił te narody, nie wypędzając ich szybko, ani ich nie wydał w ręce Jozuego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 1, 'A oto narody, które Pan pozostawił, aby przez nie doświadczyć Izraela, czyli tych wszystkich, którzy nie zaznali żadnych wojen o Kanaan;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 2, 'Aby pokolenia synów Izraela ich doświadczyły, aby nauczyły się sztuki wojennej, te, które jej przedtem nie zaznały:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 3, 'Pięciu książąt filistyńskich oraz wszyscy Kananejczycy, Sydończycy i Chiwwici mieszkający na górze Libanu, od góry Baal-Hermon aż do wejścia do Chamat.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 4, 'Oni pozostali, aby przez nich doświadczyć Izraela; by poznać, czy będą posłuszni przykazaniom Pana, które dał ich ojcom przez Mojżesza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 5, 'Tak więc synowie Izraela mieszkali pośród Kananejczyków, Chetytów, Amorytów, Peryzzytów, Chiwwitów i Jebusytów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 6, 'I brali sobie ich córki za żony, a swe córki dawali ich synom i służyli ich bogom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 7, 'I synowie Izraela czynili to, co złe w oczach Pana: zapomnieli o Panu, swym Bogu, i służyli Baalom i gajom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 8, 'Wtedy zapłonął gniew Pana przeciw Izraelowi i wydał ich w ręce Kuszan-Riszataima, króla Mezopotamii. I synowie Izraela służyli Kuszan-Risztaimowi przez osiem lat.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 9, 'A gdy synowie Izraela wołali do Pana, Pan wzbudził synom Izraela wybawcę, który ich wybawił – Otniela, syna Keneza, młodszego brata Kaleba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 10, 'Zstąpił na niego Duch Pana i sądził Izraela; a gdy wyruszył na wojnę, Pan wydał w jego ręce Kuszan-Riszataima, króla Mezopotamii, i jego ręka wzmocniła się nad Kuszan-Riszataimem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 11, 'I ziemia zaznała pokoju przez czterdzieści lat, aż umarł Otniel, syn Keneza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 12, 'Potem synowie Izraela znowu czynili to, co złe w oczach Pana. I Pan wzmocnił przeciw Izraelowi Eglona, króla Moabu, bo czynili to, co złe w oczach Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 13, 'Ten zgromadził przy sobie synów Ammona i Amaleka, wyruszył i pobił Izraela, i zajął miasto palm.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 14, 'Tak więc synowie Izraela służyli Eglonowi, królowi Moabu, przez osiemnaście lat.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 15, 'A gdy synowie Izraela wołali do Pana, Pan wzbudził im wybawcę – Ehuda, syna Gery, Beniaminitę, człowieka leworęcznego. I synowie Izraela posłali przez niego dar Eglonowi, królowi Moabu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 16, 'I Ehud sporządził sobie miecz o dwóch ostrzach, długości jednego łokcia, i przypasał go sobie pod szatą do prawego biodra.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 17, 'I przyniósł dar Eglonowi, królowi Moabu. Eglon zaś był człowiekiem bardzo otyłym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 18, 'A gdy oddał dar, odprawił ludzi, którzy dar przynieśli;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 19, 'A sam wrócił z kamiennych gór, które były w Gilgal, i powiedział: Mam do ciebie tajną sprawę, o królu. A ten odpowiedział: Cisza! I wyszli od niego wszyscy, którzy przed nim stali.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 20, 'Wtedy Ehud podszedł do niego. On zaś siedział w letniej komnacie, którą miał tylko dla siebie. I Ehud powiedział: Mam dla ciebie słowo od Boga. A ten powstał z tronu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 21, 'Wtedy Ehud wyciągnął lewą rękę, dobył miecz ze swego prawego biodra i wbił go w jego brzuch.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 22, 'A rękojeść weszła razem z ostrzem i tłuszcz zamknął się za ostrzem tak, że nie mógł wyjąć miecza z jego brzucha; i wyszły z niego nieczystości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 23, 'Potem Ehud wyszedł przez przedsionek, zamknął za sobą drzwi komnaty i zasunął rygle.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 24, 'A gdy wyszedł, przyszli słudzy i kiedy zobaczyli, że drzwi komnaty były zamknięte, powiedzieli: Z pewnością król odpoczywa w letniej komnacie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 25, 'I czekali długo, aż poczuli się zawstydzeni. Widząc, że on nie otwiera drzwi komnaty, wzięli klucz i otworzyli; a oto ich pan leżał na ziemi martwy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 26, 'Lecz Ehud uciekł, kiedy oni zwlekali z wejściem, minął kamienne góry i uciekł aż do Seiru.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 27, 'A gdy przyszedł, zadął w trąbę na górze Efraim; i synowie Izraela zeszli z nim z góry, a on na ich czele.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 28, 'I powiedział do nich: Pójdźcie za mną. Pan bowiem wydał waszych wrogów, Moabitów, w wasze ręce. Poszli więc za nim, zajęli brody Jordanu do Moabu i nie pozwalali nikomu przejść.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 29, 'W tym czasie zabili około dziesięciu tysięcy mężczyzn spośród Moabitów, samych krzepkich i walecznych, i nikt nie uszedł z życiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 30, 'W tym dniu Moab został poniżony pod ręką Izraela; i ziemia żyła w pokoju przez osiemdziesiąt lat.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 31, 'A po nim był Szamgar, syn Anata. Zabił on sześciuset mężczyzn spośród Filistynów ościeniem na woły. On także wybawił Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 1, 'A po śmierci Ehuda synowie Izraela znowu czynili to, co złe w oczach Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 2, 'I Pan wydał ich w ręce Jabina, króla Kanaanu, który królował w Chasor. Dowódcą jego wojska był Sisera, który mieszkał w pogańskim Charoszet.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 3, 'I synowie Izraela wołali do Pana. Miał tamten bowiem dziewięćset żelaznych rydwanów i mocno uciskał synów Izraela przez dwadzieścia lat.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 4, 'W tym czasie sądziła Izraela prorokini Debora, żona Lappidota.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 5, 'I mieszkała pod palmą Debory, między Rama a Betel, na górze Efraim, a synowie Izraela przychodzili do niej na sąd.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 6, 'Posłała ona i wezwała Baraka, syna Abinoama, z Kedesz-Neftali, i powiedziała do niego: Czy Pan, Bóg Izraela nie rozkazał: Idź, udaj się na górę Tabor i weź ze sobą dziesięć tysięcy mężczyzn z synów Neftalego i z synów Zebulona?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 7, 'I przyprowadzę do ciebie, do rzeki Kiszon, Siserę, dowódcę wojska Jabina, jego rydwany i jego liczne oddziały, i wydam go w twoje ręce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 8, 'Barak zaś powiedział do niej: Jeśli pójdziesz ze mną, pójdę, lecz jeśli nie pójdziesz ze mną, nie pójdę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 9, 'Ona odpowiedziała: Na pewno pójdę z tobą. Nie tobie jednak przypadnie chwała z tej wyprawy, na którą wyruszysz. Pan bowiem wyda Siserę w ręce kobiety. I Debora wstała, i udała się z Barakiem do Kedesz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 10, 'Wtedy Barak wezwał Zebulona i Neftalego do Kedesz i wyruszył, a za nim dziesięć tysięcy mężczyzn. Szła z nim także Debora.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 11, 'A Cheber Kenita odłączył się od Kenitów, od synów Chobaba, teścia Mojżesza, i rozbił swój namiot aż do równin w Saananim, które jest przy Kedesz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 12, 'I doniesiono Siserze, że Barak, syn Abinoama, wyruszył na górę Tabor.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 13, 'Sisera zebrał więc wszystkie swoje rydwany, to jest dziewięćset żelaznych rydwanów, oraz cały lud, który z nim był, od pogańskiego Charoszet aż do rzeki Kiszon.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 14, 'Wtedy Debora powiedziała do Baraka: Wstań, bo to jest dzień, w którym Pan wyda Siserę w twoje ręce. Czyż Pan nie idzie przed tobą? Barak zszedł więc z góry Tabor, a dziesięć tysięcy mężczyzn zeszło za nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 15, 'I Pan rozgromił Siserę, wszystkie wozy oraz całe jego wojsko ostrzem miecza przed Barakiem, tak że Sisera zeskoczył z rydwanu i uciekał pieszo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 16, 'Lecz Barak ścigał rydwany i wojsko aż do pogańskiego Charoszet. I poległo od ostrza miecza całe wojsko Sisery; nie pozostał ani jeden z jego wojowników.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 17, 'A Sisera uciekł pieszo do namiotu Jael, żony Chebera Kenity, ponieważ panował pokój między Jabinem, królem Chasoru, a domem Chebera Kenity.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 18, 'A Jael wyszła naprzeciw Siserze i powiedziała do niego: Wejdź, mój panie, wejdź do mnie, nie bój się. Wszedł więc do niej do namiotu, a ona przykryła go kocem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 19, 'Wtedy powiedział do niej: Daj mi, proszę, napić się trochę wody, bo jestem spragniony. A ona otworzyła bukłak z mlekiem, dała mu się napić i przykryła go.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 20, 'I powiedział do niej: Stój przy wejściu do namiotu, a jeśli ktoś przyjdzie i zapyta cię: Czy jest tu ktoś? – odpowiesz: Nie ma.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 21, 'Potem Jael, żona Chebera, wzięła kołek od namiotu, chwyciła do ręki młot, podeszła do niego po cichu i wbiła kołek w jego skroń, tak że ten utkwił w ziemi, bo on twardo spał, gdyż był zmęczony. I w ten sposób umarł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 22, 'Tymczasem Barak ścigał Siserę i Jael wyszła mu naprzeciw, i powiedziała do niego: Chodź, a pokażę ci człowieka, którego szukasz. I wstąpił do niej, a oto Sisera leżał martwy z kołkiem w skroni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 23, 'Tak Bóg tego dnia poniżył przed synami Izraela Jabina, króla Kanaanu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 24, 'I ręka synów Izraela coraz bardziej nacierała na Jabina, króla Kanaanu, i uciskała go, aż zgładzili Jabina, króla Kanaanu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 1, 'Tego dnia Debora i Barak, syn Abinoama, śpiewali:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 2, 'Błogosławcie Pana za zemstę dokonaną w Izraelu, za to, że lud dobrowolnie się ofiarował.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 3, 'Słuchajcie, królowie, nadstawcie uszu, książęta: Ja Panu, ja będę śpiewać, będę śpiewać Panu, Bogu Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 4, 'Panie, gdy wyszedłeś z Seiru, gdy przechodziłeś przez pole Edom, ziemia drżała, niebiosa kropiły, a obłoki kropiły wodą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 5, 'Góry topniały przed Panem jak góra Synaj – przed Panem, Bogiem Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 6, 'Za dni Szamgara, syna Anata, za dni Jael wyludniły się drogi, a ci, którzy wyruszyli w drogę, chodzili krętymi ścieżkami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 7, 'Opustoszały wsie w Izraelu, opustoszały, aż powstałam ja, Debora, aż powstałam jako matka w Izraelu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 8, 'Gdy Izrael wybrał sobie nowych bogów, wtedy w bramach nastała wojna; tarczy jednak ani włóczni nie było widać wśród czterdziestu tysięcy w Izraelu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 9, 'Moje serce skłania się ku wodzom Izraela, tym, którzy dobrowolnie się ofiarowali. Błogosławcie Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 10, 'Wy, którzy jeździcie na białych oślicach i zasiadacie na sądach, i którzy chodzicie po drogach, opowiadajcie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 11, 'Że ucichł trzask strzelców w miejscach, gdzie czerpie się wodę; tam niech opowiadają o sprawiedliwości Pana, sprawiedliwości w jego wsiach w Izraelu. Wtedy lud Pana zstąpi do bram.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 12, 'Przebudź się, przebudź, Deboro; przebudź się, przebudź i zaśpiewaj pieśń! Powstań, Baraku, i prowadź do niewoli swych jeńców, synu Abinoama.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 13, 'Wtedy ci, którzy pozostali, panowali nad możnymi z ludu. Pan dopomógł mi panować nad mocarzami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 14, 'Z Efraima wyszedł ich korzeń przeciw Amalekowi, za tobą Beniamin wśród twego ludu; z Makir wyszli przywódcy, a z Zebulona pisarze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 15, 'Także książęta Issachara byli z Deborą; Issachara też, jak i Baraka pieszo posłano do doliny. Lecz w oddziałach Rubena toczyły się wielkie rozważania serca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 16, 'Czemu siedziałeś między oborami, słuchając wrzasku stad? W oddziałach Rubena toczyły się wielkie rozważania serca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 17, 'Gilead mieszkał za Jordanem, a dlaczego Dan przebywał na okrętach? Aszer pozostał na brzegu morskim i mieszkał w swoich zatokach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 18, 'Zebulon to lud, który narażał swe życie, podobnie jak Neftali – na wzniesieniach pól.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 19, 'Przybyli królowie i walczyli, walczyli wówczas królowie Kanaanu w Tanak, nad wodami Megiddo; nie odnieśli jednak korzyści w srebrze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 20, 'Z nieba walczyły; gwiazdy ze swoich miejsc walczyły z Siserą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 21, 'Rzeka Kiszon ich porwała, pradawna rzeka, rzeka Kiszon. Podeptałaś, o duszo moja, mocarzy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 22, 'Wtedy się roztrzaskały kopyta końskie od rozpędu mocarzy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 23, 'Przeklinajcie Meroz, powiedział Anioł Pana, przeklinajcie srodze jego obywateli, bo nie przyszli na pomoc Panu, na pomoc Panu przeciwko mocarzom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 24, 'Błogosławiona między kobietami Jael, żona Chebera Kenity; będzie błogosławiona nad kobietami mieszkającymi w namiocie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 25, 'Prosił o wodę, a ona dała mleka, a w okazałym naczyniu przyniosła masło.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 26, 'Swą lewą ręką sięgnęła po kołek, a prawą – po młot kowalski; uderzyła Siserę, przebiła jego głowę, przeszyła i przekłuła jego skronie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 27, 'Zwinął się u jej nóg, padł, leżał; zwinął się u jej nóg, padł; gdzie się zwinął, tam padł zabity.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 28, 'Matka Sisery wyglądała przez okno i wołała przez kratę: Dlaczego jego rydwan opóźnia się z przybyciem? Dlaczego zwlekają koła jego zaprzęgów?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 29, 'Najmądrzejsze z jej kobiet odpowiedziały, jak i ona sama sobie odpowiadała:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 30, 'Czyż nie trafili na łup i nie dzielą go? Każdy mężczyzna dostanie pannę albo dwie; różnobarwne łupy oddają Siserze, różnobarwne łupy haftowane, różnobarwne łupy haftowane z obu stron, na szyję biorących łupy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 31, 'Tak niech zginą wszyscy twoi wrogowie, Panie. A ci, którzy ciebie miłują, niech będą jak słońce, gdy wschodzi w swojej mocy. I ziemia żyła w pokoju przez czterdzieści lat.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 1, 'Potem synowie Izraela czynili to, co złe w oczach Pana. Wydał ich więc Pan w ręce Midianitów na siedem lat.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 2, 'A ręka Midianitów wzmocniła się nad Izraelem, tak że synowie Izraela kopali sobie przed Midianitami kryjówki w górach, jaskinie i warownie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 3, 'Bywało, że gdy Izrael coś zasiał, przychodzili Midianici, Amalekici i ludzie ze wschodu i najeżdżali go;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 4, 'I rozbijali obóz naprzeciwko niego, i niszczyli plony ziemi aż po granice Gazy. Nie pozostawiali nic na pożywienie Izraelitom – ani owiec, ani wołów, ani osłów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 5, 'Przybywali bowiem ze swymi stadami i namiotami, a przychodzili jak szarańcza tak licznie, że nie można było zliczyć ich ani ich wielbłądów. Tak wkraczali do ziemi, aby ją spustoszyć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 6, 'Dlatego Izrael bardzo zubożał z powodu Midianitów i synowie Izraela wołali do Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 7, 'A gdy synowie Izraela wołali do Pana z powodu Midianitów;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 8, 'Pan posłał do synów Izraela proroka, który powiedział do nich: Tak mówi Pan, Bóg Izraela: Ja wyprowadziłem was z ziemi Egiptu i wywiodłem was z domu niewoli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 9, 'I wyrwałem was z rąk Egipcjan oraz z rąk wszystkich, którzy was trapili. Wypędziłem ich przed wami i dałem wam ich ziemię;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 10, 'I powiedziałem wam: Ja jestem Pan, wasz Bóg, nie bójcie się bogów Amorytów, w których ziemi mieszkacie; lecz nie posłuchaliście mego głosu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 11, 'Wtedy przyszedł Anioł Pana i stanął pod dębem, który stał w Ofra, należącym do Joasza, Abiezerita. A jego syn Gedeon młócił zboże w tłoczni, aby je ukryć przed Midianitami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 12, 'Wówczas ukazał mu się Anioł Pana i powiedział do niego: Pan z tobą, dzielny wojowniku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 13, 'Gedeon mu odpowiedział: Mój Panie, proszę, jeśli Pan jest z nami, dlaczego przyszło na nas to wszystko? Gdzie są teraz wszystkie jego cuda, o których opowiadali nam nasi ojcowie, mówiąc: Czy Pan nie wyprowadził nas z Egiptu? A teraz Pan nas opuścił i wydał w ręce Midianitów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 14, 'Wtedy Pan spojrzał na niego i powiedział: Idź w tej swojej mocy, a wybawisz Izraela z rąk Midianitów. Czyż nie ja cię posłałem?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 15, 'On zaś powiedział do niego: Mój Panie, proszę, czym wybawię Izraela? Oto moja rodzina jest biedna w Manassesa, a ja jestem najmniejszy w domu swego ojca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 16, 'I Pan powiedział do niego: Ponieważ ja będę z tobą, pobijesz Midianitów jak jednego męża.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 17, 'A on mu odpowiedział: Jeśli znalazłem łaskę w twoich oczach, daj mi znak, że to ty rozmawiasz ze mną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 18, 'Nie odchodź stąd, proszę, aż wrócę do ciebie i przyniosę ci swoją ofiarę i położę ją przed tobą. I odpowiedział: Poczekam, aż wrócisz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 19, 'Gedeon poszedł więc i przyrządził koźlę oraz przaśne chleby z jednej efy mąki. Mięso włożył do kosza, a polewkę mięsną wlał do garnka i przyniósł to do niego pod dąb, i ofiarował.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 20, 'I Anioł Boga powiedział do niego: Weź mięso i przaśne chleby i połóż na tej skale, a polewkę wylej. I tak uczynił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 21, 'Wtedy Anioł Pana wyciągnął koniec laski, którą miał w ręce, i dotknął mięsa oraz przaśników; i wydobył się ogień ze skały i strawił mięso i przaśne chleby. Potem Anioł Pana zniknął sprzed jego oczu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 22, 'A gdy Gedeon zrozumiał, że to był Anioł Pana, powiedział: Ach, Panie Boże! Widziałem bowiem Anioła Pana twarzą w twarz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 23, 'I Pan mu powiedział: Pokój z tobą. Nie bój się, nie umrzesz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 24, 'Dlatego więc Gedeon zbudował tam ołtarz dla Pana i nazwał go: Pan jest pokojem. Do dziś znajduje się on w Ofra Abiezerytów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 25, 'Tej nocy Pan mu powiedział: Weź młodego cielca, który należy do twego ojca, oraz drugiego cielca siedmioletniego i zburz ołtarz Baala należący do twego ojca, i zetnij gaj, który jest przy nim;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 26, 'A zbuduj ołtarz dla Pana, swego Boga, na szczycie tej skały, na równym miejscu; weź tego drugiego cielca i złóż z niego całopalenie na drwach z gaju, który zetniesz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 27, 'Wziął więc Gedeon dziesięciu mężczyzn spośród swoich sług i uczynił tak, jak Pan mu rozkazał. A ponieważ bał się domu swego ojca i mieszkańców miasta, nie uczynił tego za dnia, lecz uczynił to w nocy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 28, 'A gdy mieszkańcy miasta wstali wczesnym rankiem, zobaczyli zburzony ołtarz Baala i ścięty gaj, który był obok niego, i tego drugiego cielca złożonego na całopalenie na zbudowanym ołtarzu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 29, 'I mówili jeden do drugiego: Któż to uczynił? A gdy się o to pytali i dowiadywali, powiedzieli: Uczynił to Gedeon, syn Joasza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 30, 'Wtedy mieszkańcy miasta powiedzieli do Joasza: Wyprowadź swego syna, niech umrze, gdyż zburzył ołtarz Baala i ściął gaj, który był przy nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 31, 'A Joasz odpowiedział wszystkim, którzy stali dokoła niego: Czy chcecie stawać w obronie Baala? Czy chcecie go wybawić? Kto chciałby go bronić, niech umrze tego ranka. Jeśli jest bogiem, niech sam się spiera o to, że zburzono jego ołtarz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 32, 'I nazwano go tego dnia Jerubbaal, mówiąc: Niech Baal się spiera z nim, bo zburzył on jego ołtarz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 33, 'Wtedy wszyscy Midianici i Amalekici oraz ludzie ze wschodu zebrali się razem, przeprawili się przez Jordan i rozbili obóz w dolinie Jizreel.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 34, 'Lecz Duch Pana ogarnął Gedeona, a on zadął w trąbę i zwołał do siebie dom Abiezera.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 35, 'I wyprawił posłańców do całego pokolenia Manassesa, które zebrało się przy nim. Wysłał też posłańców do Aszera, do Zebulona i Neftalego; i wyruszyli im na spotkanie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 36, 'Wtedy Gedeon powiedział do Boga: Jeśli moją ręką wybawisz Izraela, jak powiedziałeś;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 37, 'To ja położę runo wełny na klepisku. Jeśli rosa spadnie tylko na runo, a cała ziemia będzie sucha, wtedy będę wiedział, że moją ręką wybawisz Izraela, jak powiedziałeś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 38, 'I tak się stało. Gdy wstał nazajutrz, ścisnął runo i wycisnął rosę z runa – pełną czaszę wody.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 39, 'Gedeon powiedział jeszcze do Boga: Niech nie zapłonie twój gniew przeciwko mnie, że przemówię jeszcze raz. Pozwól, proszę, że powtórzę doświadczenie z runem: niech będzie suche tylko samo runo, a na całej ziemi niech będzie rosa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 40, 'I Bóg tak uczynił tej nocy: samo runo było suche, a na całej ziemi była rosa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 1, 'Wstał więc Jerubbaal, czyli Gedeon, wcześnie rano, wraz z całym ludem, który był z nim, i rozbili obóz przy źródle Charod. A obóz Midianitów był na północ od nich, u stóp wzgórza More, w dolinie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 2, 'I Pan powiedział do Gedeona: Lud, który przebywa z tobą, jest zbyt liczny, abym wydał Midianitów w jego ręce, gdyż Izrael mógłby się chełpić przede mną, mówiąc: Moja ręka mnie wybawiła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 3, 'Wołaj więc teraz do uszu ludu: Kto jest lękliwy i bojaźliwy, niech zawróci, a rano niech idzie precz ku górze Gilead. Wtedy z ludu zawróciły dwadzieścia dwa tysiące, a dziesięć tysięcy pozostało.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 4, 'I Pan powiedział do Gedeona: Lud jest jeszcze zbyt liczny. Zaprowadź go do wody, a tam go doświadczę. Ten, o którym ci powiem: Ten pójdzie z tobą, on pójdzie z tobą, a ten, o którym ci powiem: Ten nie pójdzie z tobą, on nie pójdzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 5, 'Zaprowadził więc lud nad wodę, a Pan powiedział do Gedeona: Każdego, kto będzie chłeptał wodę swym językiem, jak chłepce pies, postawisz osobno; także każdy, który uklęknie na kolana, aby pić, stanie osobno.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 6, 'A liczba tych, którzy chłeptali wodę z ręki podnoszonej do ust, wynosiła trzystu mężczyzn; cała zaś reszta ludu klękała na kolana, aby pić wodę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 7, 'Wtedy Pan powiedział do Gedeona: Przez tych trzystu mężczyzn, którzy chłeptali wodę, wybawię was i wydam Midianitów w twoje ręce, a reszta ludu niech wraca – każdy do siebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 8, 'Ten lud wziął więc ze sobą żywność oraz swe trąby. A pozostałych mężczyzn Izraela odesłał, każdego do swego namiotu, i zatrzymał tylko trzystu mężczyzn; a obóz Midianitów był poniżej, w dolinie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 9, 'Tej nocy Pan powiedział do niego: Wstań, zejdź do obozu, bo wydałem go w twoje ręce;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 10, 'A jeśli boisz się iść, zejdź do obozu z Purą, swoim sługą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 11, 'I usłyszysz, co będą mówić, a potem twoje ręce wzmocnią się, aby wyruszyć na obóz. Zeszli więc on i Pura, jego sługa, aż do krańca przedniej straży obozu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 12, 'A Midianici, Amalekici oraz cały lud ze wschodu leżeli w dolinie, liczni jak szarańcza, a ich wielbłądów było bez liku, jak niezliczony jest piasek na morskim brzegu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 13, 'Gdy Gedeon tam przyszedł, pewien człowiek opowiadał swemu towarzyszowi sen: Oto miałem sen. Bochen chleba jęczmiennego wtoczył się do obozu Midianitów, dotarł aż do namiotu i uderzył w niego, aż upadł, i wywrócił go dołem do góry, i zapadł się namiot.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 14, 'Jego towarzysz odpowiedział: To nic innego jak tylko miecz Gedeona, syna Joasza, męża Izraela; Bóg wydał w jego ręce Midianitów i cały obóz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 15, 'Gdy Gedeon usłyszał opowiadanie o tym śnie i jego wytłumaczenie, podziękował Bogu, a gdy wrócił do obozu Izraela, powiedział: Wstańcie, gdyż Pan dał w wasze ręce obóz Midianitów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 16, 'Wtedy podzielił tych trzystu mężczyzn na trzy oddziały i dał w ręce każdemu z nich trąby oraz puste dzbany, a w dzbanach – pochodnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 17, 'I powiedział do nich: Patrzcie na mnie i czyńcie to samo, co ja. Oto pójdę do krańca obozu, a co ja będę czynić, to i wy czyńcie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 18, 'Gdy zadmę w trąbę, ja i wszyscy, którzy są ze mną, wtedy wy też zadmiecie w trąby wokół całego obozu i będziecie mówili: Miecz Pana i Gedeona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 19, 'Przyszedł więc Gedeon wraz ze stu mężami, którzy z nim byli, do krańca obozu, właśnie wtedy, gdy zaczęła się środkowa straż. I zadęli w trąby, i potłukli dzbany, które mieli w rękach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 20, 'Zadęły w trąby więc te trzy oddziały i potłukły dzbany; trzymając w lewej ręce pochodnie, a w prawej ręce trąby, aby zadąć, wołały: Miecz Pana i Gedeona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 21, 'I stanęli, każdy na swoim miejscu, dokoła obozu, a wszyscy w obozie powstali, krzyczeli i uciekali.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 22, 'Gdy więc tych trzystu mężczyzn zadęło w trąby, Pan obrócił miecz jednego przeciw drugiemu w całym obozie. I tak wojsko uciekło aż do Bet-Szitta w Serera, aż do granicy Abel-Mechola, w stronę Tabbat.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 23, 'Wtedy zebrali się mężczyźni Izraela z Neftalego, z Aszera i całego pokolenia Manassesa i ścigali Midianitów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 24, 'Potem Gedeon rozesłał posłańców po całym pogórzu Efraim, mówiąc: Zejdźcie na spotkanie Midianitom, a zajmijcie przed nimi wody aż do Bet-Bara i Jordanu. Zebrali się więc wszyscy mężczyźni z Efraima i zajęli wody aż do Bet-Bara i Jordanu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 25, 'Pojmali przy tym dwóch książąt Midianu, Oreba i Zeeba; Oreba zabili na skale Oreba, a Zeeba zabili przy tłoczni Zeeba. Ścigali dalej Midianitów, a głowy Oreba i Zeeba przynieśli do Gedeona za Jordan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 1, 'I mężczyźni z Efraima powiedzieli do niego: Dlaczego tak z nami postąpiłeś, że nie wezwałeś nas, gdy wyruszyłeś do walki z Midianitami? I mocno się z nim spierali.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 2, 'A on powiedział: Cóż takiego uczyniłem w porównaniu z wami? Czyż nie lepszy jest ostatni zbiór winogron Efraima niż pierwszy zbiór Abiezera?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 3, 'Bóg wydał w wasze ręce książąt Midianu – Oreba i Zeeba. Cóż mogłem takiego uczynić w porównaniu z wami? Gdy to powiedział, ich duch uspokoił się wobec niego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 4, 'A gdy Gedeon przybył do Jordanu, przeprawił się przez niego wraz z trzystoma mężczyznami, którzy z nim byli, znużonymi i w pościgu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 5, 'I powiedział do mieszkańców Sukkot: Dajcie, proszę, po bochenku chleba ludowi, który idzie za mną, bo jest znużony, a ja ścigam Zebacha i Salmunnę, królów Midianu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 6, 'Lecz książęta Sukkot odpowiedzieli mu: Czy dłonie Zebacha i Salmunny są już w twoich rękach, żebyśmy mieli dać twemu wojsku chleba?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 7, 'Gedeon odpowiedział: Kiedy Pan wyda Zebacha i Salmunnę w moje ręce, wtedy wymłócę wasze ciała cierniem pustyni i ostami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 8, 'Potem wyruszył stamtąd do Penuel i mówił do nich podobnie, ale ludzie z Penuel odpowiedzieli mu tak samo jak odpowiedzieli mieszkańcy Sukkot.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 9, 'Powiedział więc też mężczyznom z Penuel: Gdy wrócę w pokoju, zburzę tę wieżę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 10, 'A Zebach i Salmunna byli w Karkor, a z nimi ich wojsko w liczbie około piętnastu tysięcy, wszyscy, którzy pozostali z całego wojska ludzi ze wschodu; a poległo sto dwadzieścia tysięcy mężczyzn dobywających miecz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 11, 'Wtedy Gedeon ciągnął drogą tych, którzy mieszkali w namiotach, na wschód od Nobach i Jogbeha, i uderzył na obóz, który czuł się bezpieczny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 12, 'A gdy Zebach i Salmunna uciekli, ścigał ich i pojmał obu królów Midianu, Zebecha i Salmunnę, całe zaś wojsko rozgromił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 13, 'Potem Gedeon, syn Joasza, wrócił z bitwy, zanim wzeszło słońce;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 14, 'I schwytał młodzieńca spośród mieszkańców Sukkot, i wypytał go, a ten spisał mu książąt Sukkot i jego starszych, siedemdziesięciu siedmiu mężczyzn.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 15, 'Wtedy przyszedł do mężów Sukkot i powiedział: Oto Zebach i Salmunna, z powodu których mi urągaliście, mówiąc: Czy dłonie Zebacha i Salmunny są już w twoich rękach, abyśmy mieli dać chleba twoim znużonym mężczyznom?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 16, 'Wziął więc starszych tego miasta oraz ciernie z pustyni i osty i wysmagał nimi mężczyzn Sukkot.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 17, 'Zburzył także wieżę Penuel i zabił mężczyzn tego miasta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 18, 'Potem powiedział do Zebacha i Salmunny: Co to byli za mężczyźni, których zabiliście w Tabor? A oni odpowiedzieli: Byli tacy jak ty; każdy z nich z wyglądu jak syn króla.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 19, 'I powiedział: To byli moi bracia, synowie mojej matki. Jak żyje Pan, gdybyście zachowali ich przy życiu, nie zabiłbym was.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 20, 'Potem powiedział do Jetera, swego pierworodnego: Wstań i zabij ich. Lecz młodzieniec nie dobył swego miecza, ponieważ bał się, gdyż był jeszcze chłopcem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 21, 'Wtedy Zebach i Salmunna powiedzieli: Ty wstań i rzuć się na nas, jaki bowiem mężczyzna, taka jego siła. Wstał więc Gedeon, zabił Zebacha i Salmunnę i zabrał klejnoty, które były na szyjach ich wielbłądów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 22, 'I powiedzieli Izraelici do Gedeona: Panuj nad nami, ty i twój syn, i syn twego syna. Wybawiłeś nas bowiem z rąk Midianitów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 23, 'Lecz Gedeon odpowiedział im: Nie ja będę panował nad wami ani nie mój syn będzie panował nad wami. Pan będzie panował nad wami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 24, 'Gedeon powiedział jeszcze do nich: Będę was prosił o jedną rzecz, aby każdy z was dał mi kolczyki ze swego łupu. Mieli bowiem złote kolczyki, bo byli Izmaelitami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 25, 'I powiedzieli: Chętnie damy. Rozpostarli szatę i każdy rzucał na nią kolczyki ze swoich łupów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 26, 'I waga tych złotych kolczyków, o które poprosił, wyniosła tysiąc siedemset syklów złota, nie licząc klejnotów i wisiorków, i szkarłatnych szat, które nosili królowie Midianu, i nie licząc łańcuchów, które były na szyjach ich wielbłądów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 27, 'A Gedeon zrobił z tego efod i umieścił go w swoim mieście, w Ofra. Tam cały Izrael, chodząc za nim, uprawiał nierząd, a stało się to sidłem dla Gedeona i jego domu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 28, 'Tak Midianici zostali poniżeni przed synami Izraela i nie podnieśli już swoich głów. A ziemia żyła w pokoju przez czterdzieści lat za dni Gedeona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 29, 'Wrócił więc Jerubbaal, syn Joasza, i mieszkał w swoim domu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 30, 'A Gedeon miał siedemdziesięciu synów, którzy wyszli z jego bioder. Miał bowiem wiele żon.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 31, 'Również jego nałożnica, która była w Sychem, urodziła mu syna i nadała mu imię Abimelek.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 32, 'Potem Gedeon, syn Joasza, umarł w szczęśliwej starości i został pogrzebany w grobie swego ojca Joasza, w Ofra Abiezerytów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 33, 'A gdy Gedeon umarł, synowie Izraela odwrócili się i uprawiali nierząd, idąc za Baalami, i ustanowili sobie Baal-Berita swoim bogiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 34, 'I synowie Izraela nie pamiętali o Panu, swym Bogu, który ich wyrwał z rąk wszystkich okolicznych wrogów;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 35, 'I nie okazali miłosierdzia domowi Jerubbaala, Gedeona, za wszystkie dobrodziejstwa, jakie wyświadczył on Izraelowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 1, 'Wtedy Abimelek, syn Jerubbaala, poszedł do Sychem, do braci swej matki, i mówił do nich oraz do całej rodziny domu ojca swej matki:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 2, 'Powiedzcie do uszu wszystkich przełożonych Sychem: Co jest dla was lepsze: aby panowało nad wami siedemdziesięciu ludzi, wszyscy synowie Jerubbaala, czy żeby panował nad wami jeden człowiek? Pamiętajcie, że jestem z waszej kości i waszego ciała.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 3, 'Wtedy bracia jego matki opowiadali o nim wszystkie te słowa do uszu wszystkich przełożonych Sychem, a ich serce skłoniło się ku Abimelekowi, bo powiedzieli: To jest nasz brat.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 4, 'I dali mu siedemdziesiąt srebrników z domu Baal-Berita, a Abimelek najął za nie ludzi, lekkomyślnych próżniaków, którzy poszli za nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 5, 'Potem przyszedł do domu swojego ojca w Ofra i na jednym kamieniu zabił swoich braci, synów Jerubbaala, siedemdziesięciu ludzi. Został tylko Jotam, najmłodszy syn Jerubbaala, ponieważ się ukrył.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 6, 'Wtedy zebrali się wszyscy mężczyźni Sychem i cały dom Millo, poszli i obwołali Abimeleka królem na równinie, gdzie stał słup w Sychem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 7, 'Gdy doniesiono o tym Jotamowi, poszedł, stanął na szczycie góry Gerizim, podniósł głos i zawołał do nich: Posłuchajcie mnie, panowie Sychem, a was też Bóg usłyszy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 8, 'Zebrały się drzewa, aby namaścić nad sobą króla. I powiedziały do oliwki: Króluj nad nami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 9, 'Lecz oliwka odpowiedziała: Czy mam porzucić swój tłuszcz, przez który czci się Boga i ludzi, i pójść, aby być postawiona nad drzewami?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 10, 'Potem drzewa powiedziały do drzewa figowego: Chodź ty i króluj nad nami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 11, 'Lecz drzewo figowe odpowiedziało im: Czy mam porzucić swoją słodycz i wyborny owoc i pójść, aby być postawione nad drzewami?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 12, 'Następnie drzewa powiedziały do winorośli: Chodź ty i króluj nad nami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 13, 'Lecz winorośl odpowiedziała im: Czy mam porzucić swój moszcz, który cieszy Boga i ludzi, i pójść, aby być postawiona nad drzewami?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 14, 'I wszystkie drzewa powiedziały do ostu: Chodź ty i króluj nad nami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 15, 'A oset odpowiedział drzewom: Jeśli naprawdę chcecie namaścić mnie na króla nad sobą, chodźcie i chrońcie się w moim cieniu. A jeśli nie, niech ogień wyjdzie z ostu i spali cedry libańskie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 16, 'Teraz więc, jeśli postąpiliście uczciwie i szczerze, ustanawiając sobie Abimeleka królem, i jeśli dobrze obeszliście się z Jerubbaalem i jego domem i odpłaciliście mu za dobrodziejstwa jego ręki;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 17, 'Mój ojciec walczył bowiem za was i narażał swe życie na niebezpieczeństwo, aby was wyrwać z ręki Midianitów;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 18, 'Wy zaś powstaliście dziś przeciw domowi mego ojca i zabiliście na jednym kamieniu jego synów, siedemdziesięciu ludzi, a syna jego służącej, Abimeleka, ustanowiliście królem nad ludźmi Sychem, dlatego że jest waszym bratem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 19, 'Jeśli więc uczciwie i szczerze obeszliście się dziś z Jerubbaalem i z jego domem, cieszcie się z Abimeleka, a on niech się też cieszy z was.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 20, 'Lecz jeśli nie, niech wyjdzie ogień z Abimeleka i pożre mężczyzn Sychem i dom Millo; niech też wyjdzie ogień od mężczyzn Sychem i z domu Millo i pożre Abimeleka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 21, 'Wtedy Jotam umknął, uciekł i przybył do Beer, gdzie mieszkał z obawy przed swym bratem Abimelekiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 22, 'A gdy Abimelek panował nad Izraelem przez trzy lata;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 23, 'Bóg posłał złego ducha między Abimeleka a mężczyzn Sychem; i mężczyźni Sychem zbuntowali się przeciw Abimelekowi;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 24, 'Aby została pomszczona krzywda dokonana na siedemdziesięciu synach Jerubbaala, aby ich krew spadła na ich brata Abimeleka, który ich zabił, i na mężczyzn Sychem, którzy pomogli mu zabić swoich braci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 25, 'I mężczyźni Sychem zasadzili się na niego na szczycie gór i napadali na każdego, kto przechodził tamtą drogą. I doniesiono o tym Abimelekowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 26, 'Przyszedł też Gaal, syn Obeda, wraz ze swoimi braćmi, i przybył do Sychem, a mężczyźni Sychem zaufali mu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 27, 'Potem wyszli na pola, zbierali plony swoich winnic, tłoczyli winogrona i urządzili zabawę. Następnie weszli do domu swoich bogów, jedli, pili i złorzeczyli Abimelekowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 28, 'Wtedy Gaal, syn Obeda, powiedział: Kim jest Abimelek i czym jest Sychem, żebyśmy mu służyli? Czy to nie jest syn Jerubbaala, a Zebul nie jest jego urzędnikiem? Służcie raczej mężczyznom Chamora, ojca Sychema. Dlaczego mielibyśmy służyć jemu?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 29, 'Oby kto dał ten lud w moje ręce, abym usunął Abimeleka! I powiedział Abimelekowi: Zbierz sobie wojsko i wyjdź.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 30, 'A gdy Zebul, przełożony tego miasta, usłyszał słowa Gaala, syna Obeda, zapłonął gniewem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 31, 'I potajemnie wyprawił posłańców do Abimeleka, mówiąc: Oto Gaal, syn Obeda, wraz ze swoimi braćmi przyszedł do Sychem i oto podburzają miasto przeciwko tobie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 32, 'Wstańcie więc nocą, ty i lud, który jest z tobą, i uczyńcie zasadzkę w polu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 33, 'A rano, gdy słońce wzejdzie, wstaniesz i uderzysz na miasto. A gdy on i lud, który jest z nim, wyjdą przeciwko tobie, uczynisz z nim według swego uznania.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 34, 'Wstał więc w nocy Abimelek wraz z całym ludem, który z nim był, i zasadzili się na Sychem w czterech oddziałach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 35, 'A Gaal, syn Obeda, wyszedł i stanął w samej bramie miasta; wtedy Abimelek wraz z ludem, który z nim był, wyszedł z zasadzki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 36, 'A gdy Gaal zobaczył lud, powiedział do Zebula: Oto lud schodzi ze szczytu gór. Zebul odpowiedział mu: Widzisz cień gór i bierzesz go za ludzi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 37, 'I Gaal powiedział powtórnie: Oto lud schodzi z góry, a jeden oddział idzie drogą przez równinę Meonenim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 38, 'Wtedy Zebul powiedział do niego: Gdzież teraz są twoje usta, które mówiły: Kim jest Abimelek, abyśmy mu mieli służyć? Czyż to nie ten lud, którym wzgardziłeś? Wyjdź teraz i walcz z nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 39, 'Wyszedł więc Gaal na czele mężczyzn Sychem i walczył z Abimelekiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 40, 'I Abimelek ścigał go, gdy przed nim uciekał, a poległo wielu rannych aż do samej bramy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 41, 'Potem Abimelek został w Arum. A Zebul wygnał Gaala z jego braćmi tak, że nie mogli mieszkać w Sychem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 42, 'Nazajutrz lud wyszedł w pole i doniesiono o tym Abimelekowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 43, 'Wziął więc lud, podzielił go na trzy oddziały i zasadził się w polu; a gdy zobaczył, że lud wychodzi z miasta, uderzył na niego i pobił go.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 44, 'Abimelek i oddziały, które z nim były, wyruszyli i stanęli u samej bramy miasta, inne dwa oddziały zaś uderzyły na wszystkich, którzy byli na polu, i pobiły ich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 45, 'I Abimelek nacierał na miasto przez cały ten dzień, i zdobył je; a lud, który w nim był, zabił, miasto zaś zburzył i rozsiał na nim sól.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 46, 'A kiedy usłyszeli o tym wszyscy mężczyźni, którzy byli w wieży Sychem, weszli do twierdzy domu boga Berit.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 47, 'I doniesiono Abimelekowi, że zgromadzili się tam wszyscy mężczyźni z wieży Sychem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 48, 'Wtedy Abimelek wszedł na górę Salmon, on i cały lud, który z nim był; zabrał ze sobą siekierę, uciął gałąź z drzewa, wziął ją, włożył na swoje ramiona i powiedział do ludu, który z nim był: Co widzicie, że uczyniłem, szybko czyńcie to samo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 49, 'Każdy więc z całego ludu uciął swoją gałąź i poszedł za Abimelekiem; potem kładli je dokoła twierdzy i spalili nimi twierdzę ogniem. I zginęli tam wszyscy ludzie z wieży Sychem, około tysiąca mężczyzn i kobiet.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 50, 'Potem Abimelek poszedł do Tebes, rozbił obóz naprzeciwko Tebes i zdobył je.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 51, 'Lecz w środku miasta była potężna wieża, do której uciekli wszyscy mężczyźni, kobiety i wszyscy naczelnicy miasta. Zamknęli ją za sobą i weszli na dach wieży.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 52, 'Wtedy Abimelek podszedł aż do samej wieży i nacierał na nią. Kiedy stanął u samych drzwi wieży, chciał ją spalić ogniem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 53, 'A pewna kobieta zrzuciła kawałek kamienia młyńskiego na głowę Abimeleka i rozbiła mu czaszkę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 54, 'On natychmiast zawołał młodzieńca, który nosił jego broń, i powiedział mu: Dobądź swój miecz i zabij mnie, by nie mówiono o mnie: Kobieta go zabiła. Przebił go więc jego giermek, tak że umarł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 55, 'A gdy mężczyźni Izraela zobaczyli, że Abimelek umarł, rozeszli się, każdy do swego miejsca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 56, 'Tak Bóg odpłacił Abimelekowi za zło, które wyrządził swemu ojcu, zabijając siedemdziesięciu swych braci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 57, 'I całe zło mężczyzn Sychem Bóg obrócił na ich głowy. Tak przyszło na nich przekleństwo Jotama, syna Jerubbaala.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 1, 'Po Abimeleku powstał, aby bronić Izraela, Tola, syn Puy, syna Doda, mężczyzna z pokolenia Issachara. Mieszkał on w Szamir, na górze Efraim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 2, 'Sądził on Izraela przez dwadzieścia trzy lata, po czym umarł i został pogrzebany w Szamir.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 3, 'A po nim powstał Jair Gileadczyk, który sądził Izraela przez dwadzieścia dwa lata.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 4, 'Miał on trzydziestu synów, którzy jeździli na trzydziestu oślętach, a mieli trzydzieści miast zwanych do dziś Chawot-Jair, a są one w ziemi Gilead.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 5, 'Umarł Jair i został pogrzebany w Kamon.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 6, 'A synowie Izraela znowu czynili to, co złe w oczach Pana, służąc Baalom i Asztartom, bogom Syrii, bogom Sydonu, bogom Moabu, bogom synów Ammona i bogom filistyńskim, a opuścili Pana i nie służyli mu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 7, 'Dlatego gniew Pana zapłonął przeciw Izraelowi i wydał ich w ręce Filistynów oraz w ręce synów Ammona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 8, 'Oni trapili i uciskali synów Izraela od tego roku przez osiemnaście lat – wszystkich synów Izraela, którzy byli za Jordanem w ziemi Amorytów, która jest w Gileadzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 9, 'Synowie Ammona przeprawili się też za Jordan, aby walczyć z Judą i Beniaminem, a także z domem Efraima, i Izrael był bardzo uciskany.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 10, 'Wtedy synowie Izraela wołali do Pana: Zgrzeszyliśmy przeciw tobie, bo opuściliśmy naszego Boga, a służyliśmy Baalom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 11, 'I Pan powiedział do synów Izraela: Czy nie wybawiłem was od Egipcjan, od Amorytów, od synów Ammona i od Filistynów?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 12, 'I od Sydończyków, Amalekitów i Mahanitów, którzy was gnębili? Gdy wołaliście do mnie, czy nie wybawiłem was z ich rąk?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 13, 'Lecz wy mnie opuściliście i służyliście obcym bogom. Dlatego już was więcej nie wybawię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 14, 'Idźcie i wołajcie do bogów, których sobie wybraliście. Niech oni was wybawią w czasie waszego ucisku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 15, 'Synowie Izraela odpowiedzieli Panu: Zgrzeszyliśmy. Uczyń z nami, co wydaje się dobre w twoich oczach, tylko wybaw nas, prosimy, dzisiaj.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 16, 'Wyrzucili więc obcych bogów spośród siebie i służyli Panu, a Pan wzruszył się niedolą Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 17, 'Tymczasem synowie Ammona zebrali się i rozbili obóz w Gileadzie. Także synowie Izraela zebrali się i rozbili obóz w Mispie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 18, 'Wtedy lud i przełożeni Gileadu mówili między sobą: Kto pierwszy podejmie walkę z synami Ammona, ten stanie na czele wszystkich mieszkańców Gileadu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 1, 'A Jefte Gileadczyk był dzielnym wojownikiem, a był synem nierządnicy. Jeftego spłodził Gilead.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 2, 'Ale również żona Gileada urodziła mu synów; gdy więc synowie tej żony dorośli, wygnali Jeftego, mówiąc mu: Nie będziesz brał dziedzictwa w domu naszego ojca, gdyż jesteś synem obcej kobiety.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 3, 'Jefte uciekł więc przed swoimi braćmi i zamieszkał w ziemi Tob. Przyłączyli się do niego ludzie próżni i wyruszali z nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 4, 'Po pewnym czasie synowie Ammona walczyli z Izraelem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 5, 'A gdy Ammonici zaczęli walczyć z Izraelem, starsi z Gileadu poszli sprowadzić Jeftego z ziemi Tob.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 6, 'I powiedzieli mu: Chodź i bądź naszym dowódcą, a będziemy walczyć przeciwko synom Ammona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 7, 'Lecz Jefte odpowiedział starszym Gileadu: Czy wy nie znienawidziliście mnie i nie wygnaliście mnie z domu mego ojca? Dlaczego przyszliście do mnie teraz, gdy znajdujecie się w ucisku?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 8, 'Wtedy starsi Gileadu powiedzieli do Jeftego: Dlatego teraz zwracamy się do ciebie, abyś poszedł z nami i walczył przeciwko synom Ammona, i był naszym wodzem nad wszystkimi mieszkańcami Gileadu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 9, 'I Jefte odpowiedział starszym z Gileadu: Jeśli sprowadzicie mnie, abym walczył przeciwko synom Ammona, a Pan mi ich wyda, czy będę waszym wodzem?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 10, 'I starsi Gileadu odpowiedzieli Jeftemu: Pan będzie świadkiem między nami, jeśli nie postąpimy według twego słowa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 11, 'Wtedy Jefte poszedł ze starszymi Gileadu i lud ustanowił go nad sobą dowódcą i wodzem. I Jefte powtórzył wszystkie te słowa przed Panem w Mispie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 12, 'Potem Jefte wyprawił posłańców do króla synów Ammona, mówiąc: Co zaszło między mną a tobą, że wyruszyłeś przeciwko mnie, aby walczyć w mojej ziemi?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 13, 'Król synów Ammona odpowiedział posłańcom Jeftego: Ponieważ Izrael po wyjściu z Egiptu zajął moją ziemię od Arnonu aż do Jabbok i aż do Jordanu. Dlatego teraz zwróć mi ją pokojowo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 14, 'Jefte po raz drugi wyprawił posłańców do króla synów Ammona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 15, 'I powiedział mu: Tak mówi Jefte: Izrael nie zajął ziemi Moabu ani ziemi synów Ammona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 16, 'Lecz gdy Izrael wychodził z Egiptu przez pustynię aż do Morza Czerwonego i przyszedł do Kadesz;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 17, 'Wtedy Izrael wyprawił posłów do króla Edomu, mówiąc: Pozwól mi, proszę, przejść przez twoją ziemię. Lecz król Edomu nie pozwolił. Posłał także do króla Moabu, i on nie pozwolił. Izrael więc pozostał w Kadesz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 18, 'A gdy szedł przez pustynię, obszedł ziemię Edomu i ziemię Moabu i przyszedł od wschodniej strony ziemi Moabu, i rozbił obóz za Arnonem, lecz nie wszedł w granice Moabu, bo Arnon jest granicą Moabu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 19, 'Dlatego Izrael wyprawił posłańców do Sichona, króla Amorytów, króla w Cheszbonie, i Izrael powiedział mu: Pozwól nam, proszę, przejść przez twoją ziemię aż do mego miejsca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 20, 'Lecz Sichon nie dowierzał Izraelowi, że chce przejść przez jego granicę; przeciwnie, Sichon zebrał cały swój lud i rozbił obóz w Jahaza, i stoczył bitwę z Izraelem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 21, 'Pan, Bóg Izraela, wydał zaś Sichona i cały jego lud w ręce Izraela, który ich pobił. Izrael wziął więc w posiadanie całą ziemię Amorytów, którzy w niej mieszkali.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 22, 'Tak wziął w posiadanie wszystkie granice Amorytów: od Arnon aż do Jabbok i od pustyni aż do Jordanu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 23, 'Teraz więc Pan, Bóg Izraela, wypędził Amorytów przed swym ludem Izraelem, a ty chcesz ją posiąść?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 24, 'Czyż nie weźmiesz w posiadanie tego, co daje ci posiąść Kemosz, twój bóg? Tak i my posiądziemy ziemię tego, kogo Pan, nasz Bóg, wygnał przed nami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 25, 'A teraz – czy jesteś lepszy od Balaka, syna Sippora, króla Moabu? Czy on się kiedyś spierał z Izraelem? Czy kiedyś z nim walczył?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 26, 'Oto przez trzysta lat Izrael mieszkał w Cheszbonie i w przyległych do niego wioskach, także w Aroerze i w przyległych do niego wioskach oraz we wszystkich miastach, które są przy granicy Arnonu. Dlaczego nie próbowaliście ich odzyskać przez ten czas?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 27, 'Nie ja zawiniłem tobie, ale ty wyrządzasz mi zło, że walczysz ze mną. Niech Pan, który jest Sędzią, rozsądzi dziś między synami Izraela a synami Ammona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 28, 'Lecz król synów Ammona nie posłuchał słów Jeftego, które mu przekazał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 29, 'Wtedy Duch Pana zstąpił na Jeftego, który przeszedł przez Gilead i Manassesa, przeszedł też przez Mispę w Gileadzie, a z Mispy w Gileadzie ciągnął przeciw synom Ammona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 30, 'Tam Jefte złożył Panu ślub, mówiąc: Jeśli naprawdę wydasz synów Ammona w moje ręce;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 31, 'Wtedy to, co wyjdzie z drzwi mego domu naprzeciw mnie, gdy wrócę w pokoju od synów Ammona, będzie należało do Pana albo ofiaruję to na całopalenie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 32, 'Wyruszył więc Jefte przeciwko synom Ammona, by walczyć z nimi, a Pan wydał ich w jego ręce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 33, 'I zadał im wielką klęskę od Aroeru aż do wejścia do Menit – w dwudziestu miastach – i aż do równiny winnic. Tak synowie Ammona zostali poniżeni przed synami Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 34, 'A gdy Jefte wracał do Mispy, do swego domu, oto jego córka wyszła mu naprzeciw, z bębnami i muzyką. A była ona jedynaczką, bo nie miał żadnego syna ani innej córki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 35, 'I gdy ją zobaczył, rozdarł swoje szaty i powiedział: Ach, moja córko, bardzo mnie zasmuciłaś! I jesteś z tych, którzy mnie zasmucają, bo złożyłem ślub Panu i nie mogę tego cofnąć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 36, 'Ona mu odpowiedziała: Ojcze mój, jeśli złożyłeś ślub Panu, uczyń ze mną tak, jak wypowiedziały twoje usta; Pan bowiem dał ci pomstę na twoich wrogach, na synach Ammona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 37, 'Powiedziała też do swego ojca: Tylko uczyń dla mnie to jedno: wypuść mnie na dwa miesiące, bym mogła pójść i chodzić po górach, i opłakiwać moje dziewictwo, ja i moje towarzyszki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 38, 'A on powiedział: Idź. I wypuścił ją na dwa miesiące. Poszła więc wraz ze swoimi towarzyszkami i opłakiwała swoje dziewictwo w górach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 39, 'A gdy minęły dwa miesiące, wróciła do swego ojca i wypełnił on na niej swój ślub, który złożył, a ona nie obcowała z mężczyzną. I weszło to w zwyczaj w Izraelu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 40, 'Że każdego roku schodziły się córki Izraela, aby przez cztery dni w roku rozmawiać z córką Jeftego Gileadczyka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 1, 'Potem zebrali się mężczyźni Efraimici i wyruszyli na północ, po czym powiedzieli do Jeftego: Dlaczego poszedłeś walczyć przeciwko synom Ammona, a nas nie wezwałeś, abyśmy poszli z tobą? Spalimy ogniem twój dom nad tobą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 2, 'I Jefte powiedział im: Ja i mój lud mieliśmy niemały spór z synami Ammona; i wzywałem was, lecz nie wybawiliście mnie z ich rąk.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 3, 'A widząc, że nie chcieliście mnie wybawić, naraziłem swoje życie i wyruszyłem na synów Ammona, a Pan wydał ich w moje ręce. Dlaczego więc przyszliście dziś do mnie, by walczyć ze mną?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 4, 'Zebrał więc Jefte wszystkich mężczyzn z Gileadu i walczył z Efraimem. I mężczyźni z Gileadu pobili Efraima, gdyż ci mówili: Wy, Gileadczycy, którzy mieszkacie między Efraimitami a Manassesytami, jesteście zbiegami z Efraima.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 5, 'I Gileadczycy odebrali brody Jordanu Efraimowi. A gdy uciekający Efraimita mówił: Pozwólcie mi przejść, wtedy mężczyźni Gileadu pytali: Czy jesteś Efraimitą? A jeśli odpowiadał: Nie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 6, 'Wtedy mówili do niego: Wymów teraz: szibbolet, a ten mówił: sibbolet, bo inaczej nie mógł wymówić. Wtedy chwytali go i zabijali przy brodach Jordanu. I poległo w tym czasie z Efraima czterdzieści dwa tysiące.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 7, 'A Jefte Gileadczyk sądził Izraela przez sześć lat. Potem umarł Jefte Gileadczyk i został pogrzebany w jednym z miast Gileadu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 8, 'Po nim sądził Izraela Ibsan z Betlejem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 9, 'A miał trzydziestu synów i trzydzieści córek, które powydawał z domu za mąż, a spoza domu sprowadził trzydzieści żon dla swoich synów. I sądził Izraela przez siedem lat.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 10, 'Potem Ibsan umarł i został pogrzebany w Betlejem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 11, 'A po nim sądził Izraela Elon Zebulonita. Sądził on Izraela przez dziesięć lat.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 12, 'Potem Elon Zebulonita umarł i został pogrzebany w Ajjalonie, w ziemi Zebulona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 13, 'A po nim sądził Izraela Abdon, syn Hillela, Piratończyk.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 14, 'Miał on czterdziestu synów i trzydziestu wnuków, którzy jeździli na siedemdziesięciu oślętach. Sądził on Izraela przez osiem lat.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 15, 'Potem umarł Abdon, syn Hillela, Piratończyk, i został pogrzebany w Piratonie, w ziemi Efraima, na górze Amalekitów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 1, 'Potem synowie Izraela znowu czynili to, co złe w oczach Pana. I wydał ich Pan w ręce Filistynów na czterdzieści lat.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 2, 'A był pewien mężczyzna z Sorea, z pokolenia Dana, imieniem Manoach, a jego żona była niepłodna i nie rodziła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 3, 'I Anioł Pana ukazał się tej kobiecie, i powiedział do niej: Oto jesteś niepłodna i nie rodziłaś, ale poczniesz i urodzisz syna.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 4, 'Dlatego teraz strzeż się, nie pij wina ani mocnego napoju i nie jedz nic nieczystego;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 5, 'Bo oto poczniesz i urodzisz syna, a brzytwa nie dotknie jego głowy, bo to dziecko będzie nazirejczykiem dla Boga już od łona. I zacznie on wybawiać Izraela z rąk Filistynów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 6, 'Wtedy kobieta przyszła i powiedziała swemu mężowi: Przyszedł do mnie mąż Boży, którego oblicze było jak oblicze Anioła Boga, bardzo straszne. Nie pytałam go, skąd jest, nie oznajmił mi też swego imienia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 7, 'Powiedział mi tylko: Oto poczniesz i urodzisz syna. Teraz więc nie pij wina ani mocnego napoju i nie jedz niczego nieczystego, gdyż dziecko będzie nazirejczykiem dla Boga już od łona aż do dnia swojej śmierci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 8, 'Wtedy Manoach modlił się do Pana, mówiąc: Proszę, Panie mój, niech mąż Boży, którego posłałeś, przyjdzie znowu do nas i nauczy nas, co mamy czynić z dzieckiem, które się urodzi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 9, 'I Bóg wysłuchał głosu Manoacha. Przyszedł znowu Anioł Boga do tej kobiety, gdy siedziała na polu, lecz nie było przy niej jej męża Manoacha.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 10, 'Kobieta pobiegła więc szybko i opowiedziała swemu mężowi: Oto ukazał mi się ten mąż, który przyszedł do mnie tamtego dnia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 11, 'A Manoach wstał i poszedł za swoją żoną. Gdy przyszedł do tego męża, powiedział mu: Czy jesteś tym mężem, który rozmawiał z moją żoną? A on odpowiedział: Jestem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 12, 'Manoach powiedział: Niech się teraz spełni twoje słowo. Lecz jak mamy postępować z dzieckiem i co mamy dla niego zrobić?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 13, 'I Anioł Pana odpowiedział Manoachowi: Niech twoja żona wystrzega się wszystkiego, co jej powiedziałem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 14, 'Niech nie je niczego, co pochodzi z winorośli; także niech nie pije wina ani mocnego napoju, ani niech nie je żadnej rzeczy nieczystej. Niech przestrzega wszystkiego, co jej przykazałem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 15, 'Wtedy Manoach powiedział do Anioła Pana: Pozwól, proszę, że cię zatrzymamy i przygotujemy dla ciebie koźlątko.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 16, 'Lecz Anioł Pana odpowiedział Manoachowi: Choćbyś mnie zatrzymał, nie będę jadł twego chleba. Ale jeśli chcesz złożyć całopalenie, złóż je Panu. Manoach nie wiedział bowiem, że to był Anioł Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 17, 'I Manoach powiedział do Anioła Pana: Jakie jest twoje imię, abyśmy cię uczcili, gdy spełni się twoje słowo?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 18, 'Anioł Pana odpowiedział: Dlaczego pytasz o moje imię, które jest tajemnicze?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 19, 'Wziął więc Manoach koźlę oraz ofiarę pokarmową i złożył to na skale Panu. A uczynił on cud, a Manoach i jego żona patrzyli na to.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 20, 'A gdy płomień wznosił się z ołtarza ku niebu, wtedy Anioł Pana wstąpił w płomień ołtarza, a Manoach i jego żona, widząc to, upadli na twarze na ziemię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 21, 'I Anioł Pana już więcej nie ukazał się Manoachowi ani jego żonie. Wtedy Manoach poznał, że to był Anioł Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 22, 'Potem Manoach powiedział do swojej żony: Na pewno umrzemy, bo widzieliśmy Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 23, 'Jego żona zaś odpowiedziała mu: Gdyby Pan chciał nas zabić, nie przyjąłby z naszych rąk całopalenia i ofiary pokarmowej ani nie ukazałby nam tego wszystkiego, ani nie objawiłby nam teraz takich rzeczy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 24, 'Kobieta urodziła więc syna i nadała mu imię Samson. I dziecko rosło, a Pan mu błogosławił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 25, 'I Duch Pana zaczął go pobudzać w obozie Dan, między Sorea a Esztaol.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 1, 'Samson poszedł do Timny i zobaczył tam kobietę z córek Filistynów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 2, 'A gdy wrócił, oznajmił swemu ojcu i swej matce: Widziałem w Timnie kobietę z córek Filistynów. Weźcie mi ją więc za żonę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 3, 'Jego ojciec i matka powiedzieli mu: Czy nie ma kobiety wśród córek twych braci ani w całym moim ludzie, że chcesz iść i wziąć sobie żonę spośród nieobrzezanych Filistynów? Samson odpowiedział swemu ojcu: Weźcie mi tę, bo spodobała się moim oczom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 4, 'A jego ojciec i matka nie wiedzieli, że to wyszło od Pana, bo on szukał sposobności przeciwko Filistynom. W tym czasie bowiem Filistyni panowali nad Izraelem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 5, 'Samson poszedł więc ze swoim ojcem i swoją matką do Timny i przyszli do winnic Timny. A oto młody, ryczący lew wybiegł mu naprzeciw.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 6, 'Wtedy Duch Pana zawładnął nim i rozdarł on lwa, jakby rozdarł koźlę, choć nie miał nic w ręku. Jednak swojemu ojcu i swojej matce nie powiedział o tym, co uczynił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 7, 'Potem przyszedł i rozmawiał z tą kobietą, a ona podobała się Samsonowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 8, 'A kiedy po kilku dniach wrócił, aby ją pojąć za żonę, zboczył z drogi, aby obejrzeć padlinę lwa. A oto rój pszczół i miód były w padlinie lwa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 9, 'Wziął go do rąk, szedł drogą i jadł, a gdy przyszedł do swego ojca i swej matki, dał im i jedli. Nie powiedział im jednak, że miodu nabrał z padliny lwa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 10, 'Potem jego ojciec poszedł do tej kobiety i Samson wyprawił tam wesele. Tak bowiem zwykli czynić młodzieńcy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 11, 'A gdy Filistyni ujrzeli go, wzięli trzydziestu towarzyszy, aby przy nim byli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 12, 'I Samson powiedział do nich: Zadam wam zagadkę. Jeśli ją rozwiążecie w ciągu siedmiu dni wesela i wyjaśnicie mi ją, dam wam trzydzieści prześcieradeł i trzydzieści szat zamiennych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 13, 'A jeśli mi jej nie rozwiążecie, wtedy to wy dacie mi trzydzieści prześcieradeł i trzydzieści szat zamiennych. Odpowiedzieli mu: Zadaj swoją zagadkę, a my jej posłuchamy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 14, 'I powiedział do nich: Z pożerającego wyszedł pokarm, a z mocnego wyszła słodycz. I przez trzy dni nie mogli rozwiązać tej zagadki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 15, 'I powiedzieli siódmego dnia do żony Samsona: Namów swego męża, aby nam zdradził zagadkę, inaczej spalimy ogniem ciebie i dom twego ojca. Czy po to nas wezwaliście, aby nas ograbić? Czy nie po to?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 16, 'Płakała więc żona Samsona przed nim, mówiąc: Tak naprawdę nienawidzisz mnie i nie kochasz mnie. Zadałeś synom mego ludu zagadkę i nie chcesz mi jej wyjaśnić. I powiedział jej: Oto nie wyjaśniłem jej swojemu ojcu i swojej matce, a tobie miałbym ją wyjaśnić?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 17, 'I płakała przed nim przez siedem dni, póki trwało wesele. A siódmego dnia wyjaśnił jej, bo mu się naprzykrzała. A ona powiedziała zagadkę synom swego ludu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 18, 'A siódmego dnia przed zachodem słońca mężczyźni tego miasta powiedzieli do niego: Cóż słodszego nad miód, a co mocniejszego nad lwa? On im odpowiedział: Gdybyście nie orali moją jałowicą, nie odgadlibyście mojej zagadki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 19, 'Potem zstąpił na niego Duch Pana i poszedł do Aszkelonu, zabił trzydziestu mężczyzn spośród nich, zdjął z nich łupy i dał szaty zamienne tym, którzy rozwiązali zagadkę. I rozpalił się jego gniew, i poszedł do domu swojego ojca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 20, 'Żona Samsona zaś została oddana jego towarzyszowi, który był jego przyjacielem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 1, 'Po kilku dniach, w czasie żniw pszenicy, Samson odwiedził swoją żonę. Przyniósł jej koźlątko i mówił: Wejdę do swojej żony, do jej pokoju. Lecz jej ojciec nie pozwolił mu wejść.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 2, 'Jej ojciec powiedział: Myślałem, że ją znienawidziłeś, dałem ją więc twemu towarzyszowi. Czy jej młodsza siostra nie jest piękniejsza od niej? Weź ją sobie zamiast niej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 3, 'I Samson odpowiedział im: Już teraz będę bez winy wobec Filistynów, choć uczynię im coś złego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 4, 'Poszedł więc Samson i nałapał trzysta lisów, wziął pochodnie, przywiązał ogon do ogona, a pośrodku między dwoma ogonami uwiązał po jednej pochodni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 5, 'Potem podpalił pochodnie i wypuścił je na zboża Filistynów, i spalił tak stogi, jak i stojące zboża oraz winnice z oliwkami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 6, 'Wtedy Filistyni powiedzieli: Któż to uczynił? I odpowiedziano: Samson, zięć Timnity, ponieważ ten odebrał mu żonę i dał ją jego towarzyszowi. Poszli więc Filistyni i spalili ją i jej ojca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 7, 'Samson powiedział im: Chociaż tak uczyniliście, jeszcze się zemszczę na was, a potem ustąpię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 8, 'I zadał im wielką klęskę, bijąc od bioder aż do goleni, po czym odszedł i zamieszkał na wierzchołku skały Etam.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 9, 'Wtedy Filistyni wyruszyli, rozbili obóz w Judzie i rozciągnęli się aż do Lechi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 10, 'Mężczyźni Judy wówczas powiedzieli: Dlaczego wyruszyliście przeciwko nam? I odpowiedzieli: Przyszliśmy, aby związać Samsona i uczynić mu tak, jak on nam uczynił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 11, 'Wyruszyło więc trzy tysiące mężczyzn z Judy na szczyt skały Etam i powiedzieli do Samsona: Czy nie wiesz, że Filistyni panują nad nami? I co nam uczyniłeś? I odpowiedział im: Jak oni mi uczynili, tak ja im uczyniłem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 12, 'I powiedzieli mu: Przyszliśmy, aby cię związać i wydać w ręce Filistynów. Samson odpowiedział im: Przysięgnijcie mi, że sami się na mnie nie targniecie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 13, 'A oni mu odpowiedzieli: Nie, tylko zwiążemy cię i wydamy w ich ręce, lecz cię nie zabijemy. Związali go więc dwoma nowymi powrozami i sprowadzili go ze skały.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 14, 'Gdy przybył do Lechi, Filistyni z krzykiem wyszli mu na spotkanie. Wtedy Duch Pana zawładnął nim i powrozy, które były na jego ramionach, stały się jak lniane nici spalone ogniem i rozerwały się więzy na jego rękach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 15, 'Następnie znalazł świeżą oślą szczękę, wyciągnął po nią rękę, wziął ją i zabił nią tysiąc mężczyzn.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 16, 'Potem Samson powiedział: Szczęką oślą, stos na stosach, szczęką oślą zabiłem tysiąc mężczyzn.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 17, 'A gdy przestał mówić, wyrzucił szczękę z ręki i nazwał to miejsce Ramat-Lechi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 18, 'Wtedy odczuł wielkie pragnienie i zawołał do Pana: Ty dałeś przez rękę swego sługi to wielkie wybawienie, a teraz mam umrzeć z pragnienia albo wpaść w ręce nieobrzezanych?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 19, 'A Bóg rozszczepił wgłębienie skalne, które było w Lechi, i wyszły z niego wody. Napił się i ożył jego duch, i odzyskał siły. Dlatego nadał temu miejscu nazwę: En-Hakkore, a jest ono w Lechi aż do dziś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 20, 'I sądził Izraela za dni Filistynów przez dwadzieścia lat.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 1, 'Potem Samson poszedł do Gazy i gdy zobaczył tam nierządnicę, obcował z nią.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 2, 'I powiadomiono mieszkańców Gazy: Przybył tu Samson. Otoczyli go więc i czyhali na niego przez całą noc w bramie miasta. Zachowywali się cicho przez całą noc, mówiąc: Gdy zacznie świtać, zabijemy go.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 3, 'Ale Samson spał do północy, a o północy wstał, chwycił wrota bramy miejskiej z dwoma słupami i wyrwał je z zasuwą, potem włożył na swoje ramiona i zaniósł je na szczyt góry, która była naprzeciw Hebronu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 4, 'Potem w dolinie Sorek zakochał się w kobiecie, która miała na imię Dalila.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 5, 'I przyszli do niej książęta Filistynów i powiedzieli jej: Oszukaj go i dowiedz się, w czym tkwi jego wielka siła i jak moglibyśmy go pokonać, by go związać i gnębić, a każdy z nas da ci tysiąc sto srebrników.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 6, 'Powiedziała więc Dalila do Samsona: Powiedz mi, proszę, w czym tkwi twoja wielka siła i czym można by cię związać, by cię gnębić?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 7, 'Samson jej odpowiedział: Gdyby mnie związano siedmioma świeżymi witkami, które jeszcze nie wyschły, wtedy osłabnę i będę jak każdy inny człowiek.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 8, 'I książęta Filistynów przynieśli jej siedem świeżych witek, które jeszcze nie wyschły, i związała go nimi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 9, 'Tymczasem czyhający na niego siedzieli u niej w komorze. Wtedy powiedziała mu: Filistyni nad tobą, Samsonie! Lecz on zerwał witki, jakby ktoś zerwał zgrzebną nić, gdy dotknie jej ogień. Nie poznano więc, w czym tkwiła jego siła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 10, 'Potem Dalila powiedziała do Samsona: Oszukałeś mnie i skłamałeś mi. Teraz powiedz mi, proszę, czym można by cię związać?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 11, 'A on jej odpowiedział: Gdyby mnie związano nowymi powrozami, których jeszcze nie używano, wtedy osłabnę i będę jak każdy inny człowiek.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 12, 'Dalila wzięła więc nowe powrozy i związała go nimi, i powiedziała do niego: Filistyni nad tobą, Samsonie! A czyhający na niego siedzieli w komorze, lecz on porwał je ze swych ramion jak nici.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 13, 'Wtedy Dalila powiedziała do Samsona: Aż dotąd szydziłeś ze mnie i okłamywałeś mnie. Powiedz mi, czym można by cię związać? I powiedział jej: Jeśli spleciesz siedem pasm z mojej głowy w osnowę przędzy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 14, 'Ona wtedy przybiła je kołkiem i powiedziała do niego: Filistyni nad tobą, Samsonie! Lecz on obudził się ze snu i wyrwał kołek z osnową i z wałkiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 15, 'Znowu powiedziała do niego: Jak możesz mówić: Kocham cię, skoro twoje serce nie jest ze mną. Już trzykrotnie mnie oszukałeś i nie powiedziałeś mi, w czym tkwi twoja wielka siła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 16, 'A gdy mu się tak naprzykrzała słowami każdego dnia i naciskała na niego tak, że jego dusza zmęczyła się na śmierć;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 17, 'Wtedy otworzył przed nią całe swoje serce i powiedział jej: Brzytwa nigdy nie dotknęła mojej głowy, bo jestem nazirejczykiem dla Boga już z łona mojej matki. Jeśli zostanę ogolony, odejdzie ode mnie moja siła, osłabnę i będę jak każdy inny człowiek.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 18, 'A gdy Dalila spostrzegła, że otworzył przed nią całe swoje serce, wezwała książąt Filistynów, mówiąc: Przyjdźcie raz jeszcze, gdyż otworzył przede mną całe swoje serce. Przyszli więc do niej książęta Filistynów, niosąc srebro w rękach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 19, 'Wtedy uśpiła go na swoich kolanach, przywołała pewnego człowieka i kazała zgolić siedem pasm jego głowy; potem zaczęła go gnębić, a jego siła odeszła od niego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 20, 'I powiedziała: Filistyni nad tobą, Samsonie! A gdy się obudził ze snu, powiedział: Wyjdę jak poprzednio i otrząsnę się. Lecz nie wiedział, że Pan odstąpił od niego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 21, 'Wtedy Filistyni pojmali go, wyłupili mu oczy i zaprowadzili do Gazy, a tam związali go dwoma spiżowymi łańcuchami i musiał mleć w domu więźniów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 22, 'Potem włosy na jego głowie zaczęły odrastać po ogoleniu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 23, 'A książęta Filistynów zebrali się, aby złożyć swemu bogu Dagonowi wielką ofiarę i radować się. Mówili bowiem: Nasz bóg wydał w nasze ręce Samsona, naszego wroga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 24, 'Kiedy ludzie widzieli go, chwalili swego boga, bo mówili: Nasz bóg wydał w nasze ręce naszego wroga, tego, który pustoszył naszą ziemię i który wielu z naszych pozabijał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 25, 'A gdy ich serca się rozweseliły, powiedzieli: Zawołajcie Samsona, aby nas zabawiał. Przywołano więc Samsona z domu więźniów, aby ich zabawiał. I postawili go między dwiema kolumnami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 26, 'Wtedy Samson powiedział do chłopca, który go trzymał za rękę: Poprowadź mnie, abym mógł dotknąć kolumn, na których stoi dom, abym się o nie oparł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 27, 'A dom był pełen mężczyzn i kobiet, byli tam wszyscy książęta Filistynów, na dachu zaś było około trzech tysięcy mężczyzn i kobiet, którzy się przyglądali, gdy Samson ich zabawiał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 28, 'Wówczas Samson wezwał Pana i powiedział: Panie Boże, wspomnij na mnie, proszę, i wzmocnij mnie tylko ten jeden raz, Boże, abym mógł się zemścić już na Filistynach za dwoje moich oczu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 29, 'Ujął więc Samson obie środkowe kolumny, na których stał dom i o które się wsparł, jedną swoją prawą ręką, a drugą swoją lewą ręką.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 30, 'Potem Samson powiedział: Niech umrę z Filistynami. A gdy się o nie mocno oparł, dom upadł na książąt i na cały lud, który w nim był. A martwych, których zabił przy swojej śmierci, było więcej niż tych, których zabił za swego życia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 31, 'I przyszli jego bracia i cały dom jego ojca, wzięli go, wrócili i pogrzebali go między Sorea a Esztaol, w grobie Manoacha, jego ojca. A sądził on Izraela przez dwadzieścia lat.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 1, 'A był pewien człowiek z góry Efraim imieniem Micheasz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 2, 'Powiedział on do swojej matki: Te tysiąc sto srebrników, które ci ukradziono, z powodu których przeklinałaś i o których mówiłaś do moich uszu, otóż to srebro jest u mnie, ja je wziąłem. I jego matka powiedziała: Błogosławiony jesteś, mój synu, przez Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 3, 'I zwrócił swej matce owe tysiąc sto srebrników, po czym matka powiedziała: Poświęciłam to srebro Panu ze swojej ręki dla ciebie, mój synu, aby uczyniono z niego posąg ryty oraz posąg odlany, dlatego teraz oddaję ci je.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 4, 'Lecz on zwrócił to srebro swojej matce. Wtedy jego matka wzięła dwieście srebrników, dała je złotnikowi, a on uczynił z nich posąg ryty oraz posąg odlany, które stały potem w domu Micheasza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 5, 'A Micheasz miał u siebie kaplicę bogów, sporządził też efod i terafim i poświęcił jednego ze swych synów, aby był jego kapłanem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 6, 'W tych dniach nie było króla w Izraelu, każdy czynił to, co było słuszne w jego oczach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 7, 'Był pewien młodzieniec z Betlejem judzkiego, z pokolenia Judy. Był on Lewitą i tam przebywał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 8, 'Ten człowiek wyruszył z miasta Betlejem judzkiego, aby zamieszkać, gdzie mu się trafi. Wędrując tak, przyszedł na górę Efraim aż do domu Micheasza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 9, 'Micheasz powiedział do niego: Skąd przychodzisz? I odpowiedział mu: Jestem Lewitą z Betlejem judzkiego, a idę, aby zamieszkać, gdzie mi się trafi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 10, 'I Micheasz powiedział mu: Zostań u mnie i bądź mi za ojca i za kapłana, a dam ci dziesięć srebrników rocznie, drugą szatę i wyżywienie. I Lewita poszedł za nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 11, 'I spodobało się Lewicie mieszkać z tym człowiekiem; a ten młodzieniec stał się dla niego jakby jednym z jego synów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 12, 'Micheasz poświęcił Lewitę i młodzieniec ten został jego kapłanem, i mieszkał w domu Micheasza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 13, 'Wtedy Micheasz powiedział: Teraz wiem, że Pan będzie mnie błogosławił, gdyż mam Lewitę za kapłana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 1, 'W tych dniach nie było króla w Izraelu, toteż w tych dniach pokolenie Dana szukało sobie dziedzictwa do zamieszkania. Aż do tego dnia bowiem nie przypadło im dziedzictwo pośród pokoleń Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 2, 'Synowie Dana wyprawili więc ze swoich granic pięciu mężczyzn ze swego pokolenia, walecznych mężczyzn z Sorea i Esztaol, aby wyszpiegowali ziemię i zbadali ją. Powiedzieli do nich: Idźcie, zbadajcie ziemię. Ci przybyli na górę Efraim, aż do domu Micheasza, i tam przenocowali.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 3, 'Gdy byli blisko domu Micheasza, poznali głos młodzieńca Lewity. Wstąpili więc tam i zapytali go: Kto cię tu przyprowadził? I co tu robisz? I jaką masz tu sprawę?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 4, 'A on im odpowiedział: Tak a tak postąpił ze mną Micheasz, najął mnie i jestem jego kapłanem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 5, 'I powiedzieli do niego: Prosimy, poradź się Boga, abyśmy się dowiedzieli, czy poszczęści się nam nasza droga, którą idziemy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 6, 'I kapłan im odpowiedział: Idźcie w pokoju. Pan bowiem czuwa nad waszą drogą, którą idziecie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 7, 'Poszło więc tych pięciu mężczyzn i przybyli do Lajisz. I zobaczyli, że lud, który w nim był, mieszkał beztrosko, według zwyczaju Sydończyków, spokojnie i bezpiecznie, i że nie było władcy, który by ich trapił w tej ziemi. Ponadto byli daleko od Sydończyków i nie mieli z nikim żadnych interesów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 8, 'Gdy więc wrócili do swych braci do Sorea i Esztaol, ich bracia zapytali ich: Co powiecie?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 9, 'Odpowiedzieli: Wstańcie i wyruszajmy przeciwko nim. Widzieliśmy bowiem ziemię, a jest ona bardzo dobra. A wy stoicie? Nie ociągajcie się z wyruszeniem i wejściem do tej ziemi, aby ją posiąść.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 10, 'Gdy wejdziecie, przyjdziecie do ludu bezpiecznego, do ziemi przestronnej. Bóg bowiem dał ją w wasze ręce; to miejsce, gdzie nie brakuje niczego z tego wszystkiego, co jest na ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 11, 'I wyruszyło stamtąd z pokolenia Dana, z Sorea i Esztaol, sześciuset mężczyzn uzbrojonych do walki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 12, 'Będąc w drodze, rozbili obóz przy Kiriat-Jearim w Judzie. Dlatego to miejsce nazywa się Machane-Dan aż do dziś. A znajduje się za Kiriat-Jearim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 13, 'A kiedy wyruszyli stamtąd na górę Efraim, przybyli aż do domu Micheasza;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 14, 'I odezwało się tych pięciu mężczyzn, którzy szli, aby wyszpiegować ziemię Lajisz, i powiedzieli do swych braci: Czy wiecie, że w tych domach znajduje się efod i terafim, a także posąg ryty oraz posąg odlany? Rozważcie więc teraz, co macie czynić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 15, 'Skierowali się więc tam i przyszli do domu młodzieńca Lewity, do domu Micheasza, i pozdrowili go.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 16, 'Lecz sześciuset mężczyzn uzbrojonych do walki, którzy byli z synów Dana, stało u wejścia do bramy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 17, 'I tych pięciu mężczyzn, którzy poszli, aby wyszpiegować ziemię, zabrało ryty posąg, efod, terafim i odlany posąg. A kapłan stał u wejścia do bramy wraz z sześciuset mężczyznami uzbrojonymi do walki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 18, 'A gdy ci, którzy weszli do domu Micheasza, wzięli ryty posąg, efod, terafim i odlany posąg, kapłan powiedział do nich: Co robicie?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 19, 'Oni odpowiedzieli mu: Milcz! Połóż rękę na usta i chodź z nami, i bądź dla nas ojcem i kapłanem. Czyż lepiej ci być kapłanem w domu jednego człowieka, czy być kapłanem całego pokolenia i rodu w Izraelu?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 20, 'I uradowało się serce kapłana. Wziął więc efod, terafim i ryty posąg i przyłączył się do tego ludu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 21, 'A oni zawrócili i poszli, a przed sobą puścili dzieci i bydło oraz to, co kosztowniejsze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 22, 'A gdy byli już daleko od domu Micheasza, wtedy mężczyźni, którzy mieszkali w domach blisko domu Micheasza, zebrali się i zaczęli ścigać synów Dana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 23, 'I wołali za synami Dana. Ci zaś odwrócili się i powiedzieli do Micheasza: Co ci jest, że zebrałeś tych ludzi?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 24, 'I odpowiedział: Zabraliście moich bogów, które uczyniłem, oraz kapłana i poszliście sobie. Co mi więc pozostaje? Jak jeszcze możecie mówić: Co ci jest?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 25, 'Na to synowie Dana odpowiedzieli: Niech nie słyszymy za sobą twego głosu, by się nie rzucili na was rozgniewani ludzie, a straciłbyś swe życie i życie swego domu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 26, 'Poszli więc synowie Dana swoją drogą, a Micheasz, widząc, że byli silniejsi od niego, zawrócił i poszedł do swego domu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 27, 'Oni zaś zabrali to, co wykonał Micheasz, oraz kapłana, którego miał, i przybyli do Lajisz, do ludu spokojnego i bezpiecznego. I pobili go ostrzem miecza, a miasto spalili ogniem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 28, 'A nie było nikogo, kto by ich ratował, gdyż byli daleko od Sydonu i nie mieli z nikim żadnych interesów. A miasto to leżało w dolinie, która jest w Bet-Rechob. Oni odbudowali miasto i zamieszkali w nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 29, 'I nazwali to miasto Dan od imienia swego ojca Dana, który urodził się Izraelowi. A przedtem miasto to nosiło nazwę Lajisz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 30, 'I synowie Dana ustawili sobie ryty posąg. A Jonatan, syn Gerszona, syna Manassesa, on i jego synowie byli kapłanami dla pokolenia Dana aż do czasu uprowadzenia do niewoli mieszkańców tej ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 31, 'Postawili sobie ten ryty posąg, który uczynił Micheasz, po wszystkie dni, póki dom Boży był w Szilo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 1, 'W tych dniach, kiedy nie było króla w Izraelu, pewien Lewita, mieszkający przy zboczu góry Efraim, wziął sobie nałożnicę z Betlejem judzkiego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 2, 'A jego nałożnica dopuściła się nierządu przeciwko niemu, potem odeszła od niego do domu swego ojca, do Betlejem judzkiego; i była tam u niego przez cztery miesiące.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 3, 'Wstał więc jej mąż i poszedł za nią, aby przebłagać ją i sprowadzić z powrotem. Miał ze sobą swego sługę i parę osłów. Wtedy ona wprowadziła go do domu swego ojca, a gdy ojciec tej dziewczyny zobaczył go, uradował się z jego przyjścia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 4, 'I zatrzymał go jego teść, ojciec tej dziewczyny, i zamieszkał u niego przez trzy dni. Jedli, pili i nocowali tam.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 5, 'A czwartego dnia, gdy obudzili się wcześnie rano, wstał on, aby odejść. Ale ojciec tej dziewczyny powiedział do swego zięcia: Posil swoje serce odrobiną chleba, a potem pójdziecie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 6, 'Usiedli więc i jedli obaj razem, i napili się. Potem ojciec tej dziewczyny powiedział do jej męża: Zostań, proszę, i przenocuj tu, i niech twoje serce się raduje.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 7, 'A gdy ten mężczyzna wstał, aby wyruszyć w drogę, jego teść nalegał na niego, znowu więc przenocował tam.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 8, 'Piątego dnia wstał wcześnie rano, aby iść; lecz ojciec tej dziewczyny powiedział: Posil, proszę, swoje serce. I zwlekali aż do schyłku dnia, i jedli obaj razem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 9, 'Kiedy ten mężczyzna wstał, aby wyruszyć w drogę wraz ze swoją nałożnicą i swoim sługą, jego teść, ojciec tej dziewczyny, powiedział: Oto dzień już chyli się ku wieczorowi, przenocujcie tu, proszę. Oto dzień się kończy, przenocujcie tu i niech twoje serce się raduje. Jutro rano wyprawicie się w drogę i pójdziesz do swego domu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 10, 'Lecz mężczyzna ten nie chciał zostać na noc, ale wstał i odszedł, i przyszedł do miejsca naprzeciw Jebus, czyli do Jerozolimy. Miał ze sobą dwa juczne osły i swoją nałożnicę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 11, 'A gdy byli blisko Jebus, a dzień chylił się ku końcowi, wtedy sługa powiedział do swego pana: Chodź, proszę, wstąpmy do tego miasta Jebusytów i przenocujmy w nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 12, 'Jego pan mu odpowiedział: Nie wstępujmy do miasta cudzoziemców, którzy nie należą do synów Izraela, ale idźmy aż do Gibea.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 13, 'Powiedział jeszcze do swego sługi: Chodźmy i zbliżmy się do jednego z tych miejsc, aby przenocować w Gibea lub w Rama.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 14, 'Przeszli więc i poszli dalej, a słońce zaszło im przy Gibea, które należy do pokolenia Beniamina.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 15, 'I udali się tam, aby wejść i przenocować w Gibea. A gdy wszedł, usiadł na ulicy w mieście, gdyż nie było nikogo, kto by ich przyjął do domu i przenocował.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 16, 'A oto pewien starzec szedł wieczorem ze swej pracy na polu; ten człowiek pochodził z góry Efraim i był przybyszem w Gibea. Ludzie zaś tego miejsca byli Beniaminatami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 17, 'Gdy podniósł swe oczy, zobaczył tego podróżnego na ulicy miasta. I zapytał go starzec: Dokąd idziesz i skąd przybyłeś?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 18, 'On odpowiedział mu: Idziemy z Betlejem judzkiego aż na zbocze góry Efraim, skąd pochodzę. Poszedłem do Betlejem judzkiego, a teraz idę do domu Pana, ale nie ma nikogo, kto by mnie przyjął do domu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 19, 'Mamy słomę i siano dla naszych osłów, także chleb i wino mam dla siebie i dla twojej służącej, i dla sługi, który jest z twoimi sługami. Nie brak nam niczego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 20, 'Wtedy starzec mu powiedział: Pokój z tobą. Każdy twój brak będzie moją sprawą; tylko nie nocuj na ulicy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 21, 'Wprowadził go więc do swego domu i dał osłom obrok; a gdy umyli swe nogi, jedli i pili.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 22, 'A gdy rozweselili swoje serca, oto mężczyźni tego miasta, synowie Beliala, otoczyli dom i kołatali do drzwi, i mówili do gospodarza tego domu, do starca: Wyprowadź człowieka, który wszedł do twego domu, abyśmy z nim obcowali.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 23, 'A ten człowiek, gospodarz domu, wyszedł do nich i powiedział im: Nie, moi bracia, nie czyńcie, proszę, tej niegodziwości, gdyż ten człowiek wszedł do mego domu, nie czyńcie tej sprośności.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 24, 'Oto jest tu moja córka, dziewica, oraz jego nałożnica; wyprowadzę je zaraz, żebyście je znieważali i uczynili z nimi, co wydaje się wam słuszne. Tylko temu człowiekowi nie czyńcie tej niegodziwości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 25, 'Lecz ci mężczyźni nie chcieli słuchać jego głosu. Wziął więc ten człowiek swoją nałożnicę i wyprowadził ją do nich na dwór; obcowali z nią i gwałcili ją przez całą noc aż do rana. Potem ją puścili, gdy wschodziła zorza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 26, 'A o świcie ta kobieta przyszła i upadła przy drzwiach domu tego człowieka, gdzie przebywał jej pan; leżała tam, aż się rozwidniło.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 27, 'Potem jej pan wstał rano, otworzył drzwi domu i wyszedł, aby wyruszać w drogę. A oto kobieta, jego nałożnica, leżała u drzwi domu z rękami na progu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 28, 'I powiedział do niej: Wstań, pójdźmy. Lecz ona nic nie odpowiedziała. Wziął ją więc ten człowiek na osła i poszedł do swego miejsca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 29, 'A gdy przyszedł do swego domu, wziął nóż, chwycił swoją nałożnicę, rozciął ją wraz z kośćmi na dwanaście części i rozesłał ją po wszystkich granicach Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 30, 'A każdy, kto to widział, mówił: Nigdy nie wydarzyło się nic takiego ani nie widziano niczego takiego od dnia wyjścia synów Izraela z Egiptu aż do tego dnia. Zastanówcie się nad tym, naradźcie się i mówcie o tym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 1, 'Wtedy wyszli wszyscy synowie Izraela i zebrało się całe zgromadzenie jednomyślnie od Dan aż do Beer-Szeby i do ziemi Gilead do Pana w Mispie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 2, 'I przywódcy całego ludu, wszystkich pokoleń Izraela, stanęli w zgromadzeniu ludu Bożego: czterysta tysięcy pieszych dobywających miecz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 3, 'I synowie Beniamina usłyszeli, że synowie Izraela zebrali się w Mispie. Wtedy synowie Izraela powiedzieli: Powiedzcie, jak doszło do tej niegodziwości?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 4, 'I ten Lewita, mąż zabitej kobiety, odpowiedział: Przybyłem wraz z moją nałożnicą do Gibea, która należy do Beniamina, aby tam przenocować.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 5, 'I mężczyźni z Gibea powstali przeciwko mnie i w nocy otoczyli dom, zamierzając mnie zabić, a moją nałożnicę tak gwałcili, aż umarła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 6, 'Wziąłem więc swoją nałożnicę, rozciąłem ją na części i rozesłałem ją do wszystkich krain dziedzictwa Izraela. Dopuszczono się bowiem w Izraelu haniebnego i sprośnego czynu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 7, 'Oto wy wszyscy jesteście synami Izraela, rozważcie to między sobą i radźcie o tym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 8, 'I powstał cały lud jednomyślnie, mówiąc: Nikt z nas nie pójdzie do swego namiotu ani nie odejdzie do swego domu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 9, 'Ale teraz tak uczynimy miastu Gibea: Wyruszymy przeciwko niemu według losu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 10, 'Z każdego pokolenia Izraela weźmiemy po dziesięciu mężczyzn ze stu, stu z tysiąca i tysiąc z dziesięciu tysięcy, żeby dostarczali żywność dla ludu, który wyruszy do Gibea Beniamina, by pomścić wszelką sprośność, której się dopuszczono w Izraelu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 11, 'Zebrał się więc cały lud Izraela przeciwko miastu, zżyty ze sobą jak jeden mąż.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 12, 'Potem pokolenia Izraela wysłały mężczyzn do wszystkich domów synów Beniamina, mówiąc: Co to za niegodziwość popełniono wśród was?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 13, 'Wydajcie więc teraz tych mężczyzn, synów Beliala, którzy są w Gibea, abyśmy ich pozabijali i usunęli zło z Izraela. Lecz synowie Beniamina nie chcieli słuchać głosu swoich braci, synów Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 14, 'Co więcej, zebrali się synowie Beniamina z innych miast w Gibea, aby walczyć z synami Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 15, 'I tego dnia naliczono synów Beniamina z ich miast dwadzieścia sześć tysięcy mężczyzn dobywających miecz, oprócz mieszkańców Gibea, których naliczono siedmiuset doborowych mężczyzn.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 16, 'Wśród całego ludu było siedmiuset doborowych mężczyzn, leworęcznych, a każdy z nich potrafił ciskać z procy kamieniem do włosa i nie chybiał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 17, 'Izraelitów zaś naliczono, oprócz synów Beniamina, czterysta tysięcy mężczyzn dobywających miecz, wszyscy byli wojownikami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 18, 'Wtedy synowie Izraela powstali, poszli do domu Bożego i radzili się Boga, mówiąc: Któż z nas ma wyruszyć pierwszy do walki z synami Beniamina? I Pan odpowiedział: Juda wyruszy pierwszy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 19, 'Powstali więc synowie Izraela rano i rozbili obóz naprzeciw Gibea.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 20, 'Potem synowie Izraela wyruszyli do walki z synami Beniamina i ustawili się w szyku bojowym do walki przeciw Gibea.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 21, 'Lecz synowie Beniamina wyszli z Gibea i zabili tego dnia dwadzieścia dwa tysiące mężczyzn z Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 22, 'Potem mężczyźni z ludu Izraela pokrzepili się i znowu ustawili się w szyku bojowym do walki na tym miejscu, gdzie ustawili się pierwszego dnia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 23, 'Najpierw jednak synowie Izraela poszli i płakali przed Panem aż do wieczora, i pytali Pana: Czy mamy jeszcze iść i walczyć z synami Beniamina, naszego brata? I Pan odpowiedział: Idźcie przeciwko nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 24, 'I wyruszyli synowie Izraela przeciwko synom Beniamina drugiego dnia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 25, 'Lecz synowie Beniamina wyszli przeciwko nim z Gibea drugiego dnia i znowu zabili osiemnaście tysięcy mężczyzn z synów Izraela, wszystkich mężczyzn dobywających miecz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 26, 'Wtedy wszyscy synowie Izraela i cały lud udali się i przyszli do domu Bożego, i płacząc, trwali tam przed Panem i pościli w tym dniu aż do wieczora, i składali całopalenia i ofiary pojednawcze przed Panem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 27, 'I synowie Izraela pytali Pana (tam bowiem w tych dniach była arka przymierza Boga;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 28, 'A Pinchas, syn Eleazara, syna Aarona, sprawował przy niej służbę w tych dniach): Czy mamy jeszcze wyruszać do walki z synami Beniamina, naszego brata, czy też tego zaniechać? I Pan odpowiedział: Wyruszcie, gdyż jutro wydam ich w wasze ręce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 29, 'Wtedy Izrael przygotował zasadzki zewsząd dokoła Gibea.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 30, 'I trzeciego dnia synowie Izraela wyruszyli przeciwko synom Beniamina i ustawili się w szyku bojowym przeciwko Gibea jak za pierwszym i drugim razem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 31, 'Synowie Beniamina także wyszli przeciwko ludowi i zostali odciągnięci od miasta. Zaczęli bić lud i zabijać jak za pierwszym i drugim razem na drogach, z których jedna prowadziła do Betel, a druga do Gibea na polu, a zabili około trzydziestu mężczyzn z Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 32, 'I synowie Beniamina powiedzieli: Są pobici przez nas jak i poprzednio. Lecz synowie Izraela mówili: Uciekajmy i odciągnijmy ich od miasta aż na drogi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 33, 'Powstali więc wszyscy mężczyźni Izraela ze swego miejsca i ustawili się w szyku bojowym w Baal-Tamar; tymczasem ci z Izraela, którzy przygotowali zasadzkę, wyszli ze swych miejsc, z łąk Gibea.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 34, 'A tak wyszło naprzeciw Gibea dziesięć tysięcy doborowych mężczyzn z całego Izraela; była to bitwa zacięta, a tamci nie wiedzieli, że ma ich spotkać nieszczęście.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 35, 'I Pan pobił Beniamina przed Izraelem i w tym dniu synowie Izraela zabili dwadzieścia pięć tysięcy stu mężczyzn z Beniamina, wszystkich dobywających miecz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 36, 'Wtedy synowie Beniamina widzieli, że są pobici; mężczyźni Izraela ustępowali bowiem miejsca przed Beniaminem, licząc na zasadzki, które przygotowali naprzeciw Gibea.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 37, 'A ci, którzy uczestniczyli w zasadzce, pospieszyli się i uderzyli na Gibea, a następnie pobili ostrzem miecza wszystkich, którzy byli w mieście.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 38, 'A mężczyźni Izraela mieli umówiony znak z tymi, którzy ukryli się w zasadzce, że ci wypuszczą z miasta wielki dym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 39, 'Gdy więc mężczyźni Izraela cofnęli się przed bitwą, synowie Beniamina zaczęli bić i zabili około trzydziestu mężczyzn z Izraela. Mówili bowiem: Na pewno są pobici przed nami, jak i w pierwszej bitwie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 40, 'Ale gdy płomień i dym jak słup zaczęły wznosić się z miasta, wtedy synowie Beniamina obejrzeli się, a oto ogień z miasta wznosił się aż ku niebu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 41, 'A kiedy mężczyźni Izraela zawrócili, mężowie Beniamina przerazili się, widząc, że spadło na nich nieszczęście.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 42, 'I uciekali przed mężczyznami Izraela drogą na pustynię, a wojsko doganiało ich i ci, którzy wybiegli z miast, zabijali ich pośród siebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 43, 'Otoczyli więc Beniamina i gonili ich bez przerwy, a pokonali ich naprzeciw Gibea na wschodzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 44, 'Poległo wtedy z Beniamina osiemnaście tysięcy mężczyzn, wszyscy byli wojownikami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 45, 'Z tych zaś, którzy zawrócili i uciekali na pustynię, na skałę Rimmon, wyłapali po drogach i zabili pięć tysięcy mężczyzn. Gonili ich aż do Gidom, gdzie zabili dwa tysiące mężczyzn spośród nich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 46, 'A tak wszystkich poległych z Beniamina tego dnia było dwadzieścia pięć tysięcy mężczyzn dobywających miecz, wszyscy byli wojownikami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 47, 'Tylko sześciuset mężczyzn zawróciło i uciekło na pustynię, na skałę Rimmon, i zostali na skale Rimmon przez cztery miesiące.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 48, 'Potem mężczyźni Izraela wrócili do synów Beniamina i wybili ich ostrzem miecza w mieście, zarówno ludzi, jak i bydło oraz wszystko, co znaleźli. Spalili ogniem także wszystkie miasta, które pozostały.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 1, 'Mężczyźni Izraela przysięgli też w Mispie: Żaden z nas nie da swojej córki Beniaminowi za żonę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 2, 'Udał się więc lud do domu Bożego, gdzie trwał aż do wieczora przed Bogiem, podnosząc lament i gorzko płacząc.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 3, 'I powiedzieli: O Panie, Boże Izraela, dlaczego to się stało w Izraelu, że ubyło dzisiaj z Izraela jedno pokolenie?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 4, 'A nazajutrz lud wstał wcześnie rano i zbudował tam ołtarz, i złożył całopalenia oraz ofiary pojednawcze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 5, 'Potem synowie Izraela powiedzieli: Kto spośród wszystkich pokoleń Izraela nie przyszedł do zgromadzenia do Pana? Złożyli bowiem uroczystą przysięgę przeciw temu, który by nie przyszedł do Pana do Mispy, mówiąc: Poniesie śmierć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 6, 'I synom Izraela było żal Beniamina, swego brata, i mówili: Dziś zostało odcięte jedno pokolenie od Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 7, 'Co uczynimy dla tych, którzy pozostali, aby mieli żony, skoro przysięgliśmy na Pana, że im nie damy naszych córek za żony?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 8, 'Powiedzieli więc: Czy jest ktoś wśród pokoleń Izraela, kto nie przyszedł do Mispy do Pana? A oto nie przyszedł do obozu zgromadzenia nikt z Jabesz-Gilead.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 9, 'Gdy bowiem przeliczono lud, nie było tam nikogo z mieszkańców Jabesz-Gilead.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 10, 'Wtedy zgromadzenie wysłało tam dwanaście tysięcy walecznych mężczyzn, nakazując im: Idźcie i zabijcie mieszkańców Jabesz-Gilead ostrzem miecza wraz z kobietami i dziećmi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 11, 'A tak macie postąpić: Każdego mężczyznę i każdą kobietę, która obcowała z mężczyzną, zabijecie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 12, 'I znaleźli wśród mieszkańców Jabesz-Gilead czterysta młodych dziewic, które nie obcowały z mężczyzną, i przyprowadzili je do obozu w Szilo, które było w ziemi Kanaan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 13, 'Potem całe zgromadzenie posłało do synów Beniamina, którzy byli na skale Rimmon, aby oznajmiać im pokój.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 14, 'Wrócił więc Beniamin w tym czasie i dano im żony, które zachowali przy życiu spośród kobiet z Jabesz-Gilead, lecz nie starczyło ich dla nich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 15, 'A ludowi było żal Beniamina, ponieważ Pan uczynił wyłom wśród pokoleń Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 16, 'Wtedy starsi zgromadzenia powiedzieli: A co uczynimy dla pozostałych, aby mieli żony, skoro zostały zgładzone kobiety z Beniamina?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 17, 'Ponadto powiedzieli: Musi być dziedzictwo dla pozostałych z Beniamina, aby nie zaginęło pokolenie z Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 18, 'My jednak nie możemy im dać żon z naszych córek, gdyż synowie Izraela przysięgli: Przeklęty ten, kto da żonę Beniaminowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 19, 'Potem powiedzieli: Oto co roku odbywa się uroczyste święto Pana w Szilo, które leży na północ od Betel, na wschód od drogi wiodącej od Betel do Sychem, a na południe od Lebony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 20, 'Nakazali więc synom Beniamina: Idźcie i przygotujcie zasadzkę w winnicach;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 21, 'I wypatrujcie, gdy córki Szilo wyjdą gromadnie do tańca, wtedy wyjdźcie z winnic i niech każdy z was porwie sobie żonę spośród córek Szilo, a potem idźcie do ziemi Beniamina.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 22, 'A gdy przyjdą ich ojcowie albo bracia, by skarżyć się przed nami, powiemy im: Zmiłujcie się nad nimi ze względu na nas, ponieważ nie wzięliśmy dla każdego z nich żony na wojnie, a wy też im ich nie daliście, gdyż bylibyście wtedy winni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 23, 'Wtedy synowie Beniamina uczynili tak i wzięli sobie żony spośród tańczących, które porwali, odpowiednio do swojej liczby. Potem odeszli i wrócili do swego dziedzictwa, odbudowali miasta i zamieszkali w nich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 24, 'W tym czasie synowie Izraela rozeszli się stamtąd, każdy do swego pokolenia i do swego domu, a każdy poszedł stamtąd do swego dziedzictwa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 25, 'W tych dniach nie było króla w Izraelu. Każdy czynił to, co było słuszne w jego oczach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 1, 'Zdarzyło się, że w czasach, kiedy rządzili sędziowie, nastał głód na ziemi. I pewien człowiek z Betlejem judzkiego wyruszył wraz ze swoją żoną i dwoma synami, aby zamieszkać w ziemi Moabu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 2, 'Ten człowiek miał na imię Elimelech, jego żona – Noemi, a jego dwaj synowie – Machlon i Kilion. Byli oni Efratejczykami z Betlejem judzkiego. Przybyli do ziemi Moabu i tam zamieszkali.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 3, 'Potem umarł Elimelech, mąż Noemi, a ona pozostała sama z dwoma synami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 4, 'Ci pojęli sobie za żony Moabitki: jedna miała na imię Orfa, a druga – Rut. I mieszkali tam około dziesięciu lat.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 5, 'Potem obaj, Machlon i Kilion, również umarli; i tak kobieta ta pozostała sama bez swoich dwóch synów i bez męża.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 6, 'Wtedy powstała wraz ze swoimi synowymi, aby wrócić z ziemi Moabu, gdyż usłyszała w ziemi Moabu, że Pan nawiedził swój lud i dał mu chleb.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 7, 'Wyszła więc z miejsca, w którym była, a wraz z nią jej dwie synowe i udały się w drogę powrotną do ziemi Judy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 8, 'I powiedziała Noemi do swych dwóch synowych: Idźcie, niech każda z was powróci do domu swojej matki. Niech Pan okaże wam miłosierdzie, tak jak okazałyście je zmarłym i mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 9, 'Niech Pan sprawi, aby każda z was znalazła pokój w domu swego męża. I pocałowała je, a one podniosły głosy i zapłakały.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 10, 'I mówiły do niej: Wrócimy raczej z tobą do twego ludu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 11, 'Lecz Noemi odpowiedziała: Zawróćcie, moje córki. Czemu chcecie iść ze mną? Czy mam jeszcze w swoim łonie synów, którzy zostaliby waszymi mężami?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 12, 'Zawróćcie, moje córki, idźcie, bo jestem zbyt stara, aby wyjść za mąż. A nawet gdybym powiedziała: mam jeszcze nadzieję, to choćbym tej nocy wyszła za mąż i również urodziła synów;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 13, 'Czy czekałybyście na nich, aż dorosną? Czy ze względu na nich pozostałybyście bez męża? Nie, moje córki. Odczuwam bowiem wielką gorycz ze względu na was, gdyż ręka Pana obróciła się przeciwko mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 14, 'A one znowu podniosły głosy i zaczęły płakać. I Orfa pocałowała swoją teściową, ale Rut pozostała przy niej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 15, 'Wtedy Noemi powiedziała do niej: Oto twoja szwagierka wróciła do swego ludu i do swoich bogów. Wróć także ty za swoją szwagierką.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 16, 'Rut jednak odpowiedziała: Nie nalegaj na mnie, abym cię opuściła i odeszła od ciebie. Gdziekolwiek bowiem pójdziesz i ja pójdę, a gdziekolwiek zamieszkasz i ja zamieszkam. Twój lud będzie moim ludem, a twój Bóg będzie moim Bogiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 17, 'Gdzie ty umrzesz, tam i ja umrę, i tam będę pogrzebana. Niech mi to Pan uczyni i niech do tego dorzuci, jeśli coś innego niż śmierć oddzieli mnie od ciebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 18, 'A gdy Noemi widziała, że uparła się, aby z nią iść, przestała jej odradzać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 19, 'I szły obie razem, aż przyszły do Betlejem. A gdy przybyły do Betlejem, całe miasto ogarnęło poruszenie z ich powodu i mówiono: Czy to jest Noemi?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 20, 'Lecz ona powiedziała do nich: Nie nazywajcie mnie Noemi, lecz nazywajcie mnie Mara, ponieważ Wszechmogący napełnił mnie wielką goryczą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 21, 'Wyszłam stąd pełna, a Pan sprowadził mnie pustą. Czemu nazywacie mnie Noemi, skoro Pan wystąpił przeciwko mnie i Wszechmogący sprowadził na mnie nieszczęście?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 22, 'Wróciła więc Noemi, a z nią Rut Moabitka, jej synowa, która wróciła z krainy Moabu. A przyszły do Betlejem na początku żniw jęczmienia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 1, 'A Noemi miała krewnego ze strony męża, człowieka bardzo zamożnego z domu Elimelecha. Miał on na imię Boaz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 2, 'I Rut Moabitka powiedziała do Noemi: Pozwól mi pójść na pole zbierać kłosy za tym, w którego oczach znajdę łaskę. A ona odpowiedziała: Idź, moja córko.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 3, 'Poszła więc, a gdy przybyła, zbierała na polu za żniwiarzami. I zdarzyło się przypadkiem, że trafiła na część pola Boaza, który był z rodziny Elimelecha.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 4, 'A oto Boaz przybył z Betlejem i powiedział do żniwiarzy: Pan z wami. A oni mu odpowiedzieli: Niech ci Pan błogosławi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 5, 'Wtedy Boaz zapytał swego sługę postawionego nad żniwiarzami: Czyja to dziewczyna?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 6, 'I sługa postawiony nad żniwiarzami odpowiedział mu: To jest ta młoda Moabitka, która przyszła z Noemi z ziemi Moabu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 7, 'Powiedziała: Pozwól mi, proszę, zbierać i gromadzić kłosy między snopami za żniwiarzami. Przyszła więc i pozostała od rana aż dotąd, a w domu krótko odpoczywała.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 8, 'Wtedy Boaz powiedział do Rut: Słuchaj mnie, moja córko! Nie chodź zbierać kłosów na inne pole i nie odchodź stąd, ale pozostań tu z moimi służącymi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 9, 'Spójrz na pole, na którym będą żąć, i chodź za nimi, ponieważ nakazałem swoim sługom, żeby cię nie tykali. A jeśli będziesz spragniona, idź do naczyń i napij się z tego, co czerpią moi słudzy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 10, 'Wtedy upadła na twarz i pokłoniła się aż do ziemi, i powiedziała do niego: Dlaczego znalazłam łaskę w twoich oczach, że zwracasz na mnie uwagę, choć jestem cudzoziemką?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 11, 'Boaz odpowiedział jej: Dokładnie opowiedziano mi o wszystkim, co uczyniłaś dla swojej teściowej po śmierci swego męża, i to, jak opuściłaś swego ojca i swą matkę oraz ziemię, w której się urodziłaś, i przyszłaś do ludu, którego przedtem nie znałaś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 12, 'Niech Pan wynagrodzi twój uczynek i niech będzie pełna twoja zapłata od Pana, Boga Izraela, pod którego skrzydła przyszłaś się schronić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 13, 'A ona odpowiedziała: Znalazłam łaskę w twoich oczach, mój panie. Pocieszyłeś mnie bowiem i mówiłeś do serca swej służącej, chociaż nie jestem równa żadnej z twoich służących.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 14, 'I Boaz jej powiedział: Gdy będzie czas posiłku, przychodź tu i jedz chleb, i maczaj swój kawałek w occie. I usiadła przy żniwiarzach, on zaś podał jej prażone ziarno, które jadła aż do syta, i jeszcze jej zostało.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 15, 'A gdy wstała, aby zbierać kłosy, Boaz nakazał swoim sługom: Pozwólcie jej zbierać nawet między snopami i nie zawstydzajcie jej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 16, 'Co więcej, umyślnie upuszczajcie dla niej kłosy i zostawiajcie je, aby mogła je zbierać, i nie gańcie jej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 17, 'Tak zbierała na tym polu aż do wieczora, potem wymłóciła to, co zebrała. Było tego około efy jęczmienia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 18, 'Następnie wzięła to i poszła do miasta, i jej teściowa zobaczyła to, co nazbierała. Wyjęła też i dała jej to, co pozostało jej z posiłku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 19, 'I teściowa zapytała ją: Gdzie zbierałaś dziś kłosy i gdzie pracowałaś? Niech będzie błogosławiony ten, który zwrócił na ciebie uwagę. I opowiedziała swej teściowej, u kogo pracowała: Człowiek, u którego dziś pracowałam, ma na imię Boaz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 20, 'Potem Noemi odezwała się do swojej synowej: Niech będzie błogosławiony przez Pana, który nie zaniechał swego miłosierdzia dla żywych i umarłych. Ponadto Noemi powiedziała: Ten człowiek jest naszym krewnym, jednym spośród blisko z nami spokrewnionych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 21, 'Wtedy Rut Moabitka powiedziała: Ten człowiek powiedział jeszcze do mnie: Pozostań z moimi sługami, póki nie skończą całego mojego żniwa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 22, 'Noemi powiedziała do Rut, swej synowej: To dobrze, moja córko, że będziesz chodziła z jego służącymi, aby cię nie spotkali na innym polu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 23, 'Pozostała więc ze służącymi Boaza i zbierała kłosy, dopóki nie skończyły się żniwa jęczmienia i pszenicy, a mieszkała ze swoją teściową.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 1, 'Potem Noemi, jej teściowa, powiedziała do niej: Moja córko, czy nie powinnam ci szukać odpoczynku, abyś się dobrze miała?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 2, 'I czyż Boaz nie jest naszym krewnym, z którego służącymi byłaś? Oto dziś w nocy będzie on przewiewał jęczmień na klepisku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 3, 'Umyj się więc i namaść, nałóż na siebie swoje szaty i zejdź na klepisko, lecz nie daj się poznać temu człowiekowi, dopóki nie skończy jeść i pić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 4, 'A gdy położy się spać, upatrz miejsce, na którym się położy, podejdź, odkryj jego nogi i połóż się, a on ci powie, co masz czynić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 5, 'I Rut powiedziała do niej: Uczynię wszystko, co mi każesz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 6, 'Zeszła więc na klepisko i uczyniła to, co jej nakazała teściowa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 7, 'A gdy Boaz najadł się i napił, i jego serce się rozweseliło, poszedł położyć się przy stosie zboża. Wtedy ona przyszła po cichu, odkryła jego nogi i położyła się.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 8, 'O północy mężczyzna zląkł się, obrócił, a oto kobieta leżała u jego stóp.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 9, 'I powiedział: Kto ty jesteś? Odpowiedziała: Jestem Rut, twoja służąca. Rozciągnij swój płaszcz nad swoją służącą, bo jesteś ze mną blisko spokrewniony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 10, 'A on odpowiedział: Błogosławiona jesteś przez Pana, moja córko. Większą miłość okazałaś teraz niż na początku, gdyż nie poszłaś za młodzieńcami, czy to ubogimi, czy bogatymi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 11, 'Teraz więc, moja córko, nie bój się. Uczynię wszystko, co powiedziałaś, gdyż całe miasto mego ludu wie, że jesteś cnotliwą kobietą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 12, 'A chociaż to prawda, że jestem z tobą blisko spokrewniony, to jednak bliżej jest z tobą spokrewniony inny ode mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 13, 'Zostań tu przez noc, a rankiem, jeśli zechce cię on wykupić, dobrze, niech wykupi. Lecz jeśli nie zechce cię wykupić, ja cię wykupię, jak żyje Pan! Śpij tu aż do rana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 14, 'Spała więc u jego stóp aż do rana. Wstała jednak w porze, gdy człowiek nie jest w stanie rozpoznać drugiego. Mówił bowiem Boaz: Niech nikt się nie dowie, że kobieta przyszła na klepisko.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 15, 'I dodał: Daj okrycie, które masz na sobie, i trzymaj je. A gdy trzymała je, odmierzył jej sześć miar jęczmienia i włożył to na nią. Potem poszła do miasta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 16, 'A gdy przyszła do teściowej, ta zapytała ją: Kto ty jesteś, moja córko? I opowiedziała jej wszystko, co ten człowiek uczynił dla niej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 17, 'I dodała: Oto dał mi sześć miar jęczmienia. Powiedział bowiem do mnie: Nie możesz wrócić z pustymi rękami do swojej teściowej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 18, 'Wtedy Noemi powiedziała: Bądź spokojna, moja córko, aż się dowiesz, jak potoczą się rzeczy, gdyż ten człowiek nie spocznie, dopóki nie zakończy dzisiaj tej sprawy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 1, 'Potem Boaz udał się do bramy i tam usiadł. A oto przechodził spokrewniony, o którym mówił Boaz. I powiedział do niego: Człowieku! Podejdź i usiądź tutaj. Tamten więc przyszedł i usiadł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 2, 'Wtedy Boaz wziął dziesięciu starszych tego miasta i mówił do nich: Usiądźcie tutaj. I usiedli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 3, 'I przemówił do tamtego spokrewnionego: Noemi, która wróciła z ziemi Moabu, sprzedaje kawałek ziemi, która należała do naszego brata Elimelecha.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 4, 'I pomyślałem sobie, że należy cię o tym powiadomić tymi słowy: Kup go w obecności siedzących tutaj i starszych mego ludu. Jeśli chcesz go wykupić, wykup. Lecz jeśli nie chcesz go wykupić, powiedz mi, abym wiedział. Nikt bowiem nie ma prawa wykupu przed tobą, ja zaś jestem po tobie. Wtedy on odpowiedział: Ja wykupię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 5, 'Boaz jeszcze dodał: W dniu, kiedy wykupisz pole z rąk Noemi, kupisz je również od Rut Moabitki, żony zmarłego, aby wzbudzić imię zmarłego na jego dziedzictwie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 6, 'Spokrewniony odpowiedział: Nie mogę go wykupić, żebym czasem nie poniósł szkody na własnym dziedzictwie. Ty wykup dla siebie moje prawo wykupu, gdyż ja nie mogę go wykupić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 7, 'A taki był dawniej zwyczaj w Izraelu co do prawa wykupu i co do zamiany dla zatwierdzenia każdej sprawy: człowiek zdejmował swój but i dawał go swojemu bliźniemu. Było to poświadczeniem w Izraelu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 8, 'Wtedy ów spokrewniony powiedział do Boaza: Wykup je sobie. I zdjął swój but.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 9, 'Potem Boaz przemówił do starszych i całego ludu: Dziś jesteście świadkami, że nabyłem z ręki Noemi wszystko, co należało do Elimelecha, oraz wszystko, co należało do Kiliona i Machlona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 10, 'Także Rut Moabitkę, żonę Machlona, nabyłem sobie za żonę, aby wzbudzić imię zmarłego na jego dziedzictwie, aby nie zginęło imię zmarłego wśród jego braci ani z bramy jego miejsca. Wy jesteście dziś tego świadkami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 11, 'I cały lud, który był w bramie miasta, oraz starsi powiedzieli: Jesteśmy świadkami. Niech Pan sprawi, aby kobieta, która wchodzi do twojego domu, była jak Rachel i jak Lea, które zbudowały dom Izraela. Postępuj godnie w Efrata i zdobądź sobie imię w Betlejem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 12, 'Niech twój dom – przez potomstwo, które Pan da ci z tej młodej kobiety – będzie jak dom Faresa, którego Tamar urodziła Judzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 13, 'Boaz wziął więc sobie Rut i stała się jego żoną. A gdy z nią obcował, Pan sprawił, że poczęła i urodziła syna.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 14, 'Wtedy kobiety powiedziały do Noemi: Błogosławiony Pan, który nie zostawił cię dziś bez spokrewnionego, aby jego imię było znane w Izraelu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 15, 'On będzie pociechą dla twojej duszy i żywicielem w twojej starości. Urodziła go bowiem twoja synowa, która cię miłuje i która jest dla ciebie lepsza niż siedmiu synów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 16, 'Wzięła więc Noemi dziecko, położyła je na swym łonie i była dla niego piastunką.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 17, 'I sąsiadki nadały mu imię. Mówiły bowiem: Narodził się syn Noemi. I nadały mu imię Obed. On to jest ojcem Jessego, ojca Dawida.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 18, 'A oto potomkowie Peresa: Peres spłodził Chesrona;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 19, 'A Chesron spłodził Rama, a Ram spłodził Amminadaba;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 20, 'A Amminadab spłodził Nachszona, a Nachszon spłodził Salmona;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 21, 'A Salmon spłodził Boaza, a Boaz spłodził Obeda;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 22, 'A Obed spłodził Jessego, a Jesse spłodził Dawida.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 1, 'Był pewien człowiek z Ramataim-Sofim, z góry Efraim, imieniem Elkana, syn Jerochama, syna Elihu, syna Tochu, syna Sufa Efratejczyka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 2, 'Miał on dwie żony, jednej było na imię Anna, a drugiej – Peninna. Peninna miała dzieci, Anna zaś była bezdzietna.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 3, 'Człowiek ten co roku udawał się ze swego miasta, aby oddać cześć i złożyć ofiarę Panu zastępów w Szilo. Tam byli dwaj synowie Helego, Chofni i Pinchas, kapłani Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 4, 'A gdy nadszedł dzień, w którym Elkana składał ofiarę, dał swojej żonie Peninnie oraz wszystkim jej synom i córkom części z ofiary;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 5, 'Ale Annie dał jedną wyborną część, gdyż miłował Annę, choć Pan zamknął jej łono.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 6, 'Jej przeciwniczka zaś bardzo jej dokuczała, aby tylko ją rozgniewać z tego powodu, że Pan zamknął jej łono.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 7, 'I tak Elkana czynił każdego roku, a ilekroć Anna przychodziła do domu Pana, w ten sposób Peninna jej dokuczała. Ta zaś płakała i nie jadła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 8, 'Wtedy Elkana, jej mąż, powiedział do niej: Anno, czemu płaczesz? Dlaczego nie jesz? Czemu tak smuci się twoje serce? Czy ja nie jestem dla ciebie lepszy niż dziesięciu synów?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 9, 'I gdy najedli się, i napili w Szilo, Anna wstała. A kapłan Heli siedział na krześle przy odrzwiach świątyni Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 10, 'A ona, z goryczą w duszy, modliła się do Pana i strasznie płakała.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 11, 'I złożyła ślub, mówiąc: Panie zastępów, jeśli wejrzysz na utrapienie swojej służącej i wspomnisz na mnie, i nie zapomnisz swojej służącej, ale dasz swej służącej męskiego potomka, wtedy oddam go Panu na wszystkie dni jego życia, a brzytwa nie dotknie jego głowy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 12, 'A gdy długo modliła się przed Panem, Heli przypatrywał się jej ustom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 13, 'Lecz Anna mówiła w swym sercu i tylko jej wargi się poruszały, ale jej głosu nie było słychać. Heli sądził więc, że jest pijana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 14, 'I Heli powiedział do niej: Jak długo będziesz pijana? Wytrzeźwiej od swego wina.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 15, 'Anna zaś odpowiedziała: Nie, mój panie. Jestem kobietą utrapionego ducha. Nie piłam ani wina, ani mocnego napoju, lecz wylałam swoją duszę przed Panem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 16, 'Nie uważaj swojej służącej za kobietę Beliala, gdyż z nadmiaru troski i smutku aż dotąd mówiłam.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 17, 'Wtedy Heli odpowiedział: Idź w pokoju, a niech Bóg Izraela spełni twoją prośbę, którą zaniosłaś do niego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 18, 'I powiedziała: Niech twoja służąca znajdzie łaskę w twoich oczach. I ta kobieta poszła swoją drogą, i jadła, a jej twarz już nie była smutna.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 19, 'Nazajutrz wstali wcześnie rano, pokłonili się przed Panem, wrócili się i przybyli do swego domu w Rama. I Elkana obcował z Anną, swoją żoną, a Pan wspomniał na nią.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 20, 'I gdy się wypełniły dni potem, jak Anna poczęła, urodziła syna i nadała mu imię Samuel, gdyż mówiła: Uprosiłam go u Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 21, 'Potem ten człowiek, Elkana, wraz z całym swoim domem udał się, aby złożyć Panu doroczną ofiarę oraz wypełnić swój ślub.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 22, 'Lecz Anna nie poszła, bo mówiła swemu mężowi: Nie pójdę, aż dziecko będzie odstawione od piersi, potem je zaprowadzę, żeby ukazało się przed Panem i zostało tam na zawsze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 23, 'Jej mąż Elkana odpowiedział: Czyń to, co ci się wydaje słuszne; pozostań, aż go odstawisz. Niech tylko Pan utwierdzi swoje słowo. Kobieta pozostała więc i karmiła piersią swego syna, aż do odstawienia go od piersi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 24, 'A gdy go odstawiła, wzięła go ze sobą wraz z trzema cielcami, z jedną efą mąki i bukłakiem wina i przyprowadziła go do domu Pana w Szilo; a dziecko było małe.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 25, 'I zabili cielca, i przyprowadzili dziecko do Heliego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 26, 'A ona powiedziała: Proszę, mój panie! Jak żyje twoja dusza, mój panie, to ja jestem tą kobietą, która stała tu przy tobie, modląc się do Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 27, 'Prosiłam o to dziecko i Pan spełnił moją prośbę, którą zaniosłam do niego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 28, 'Dlatego też oddaję je Panu. Na wszystkie dni jego życia zostaje oddane Panu. I oddał tam pokłon Panu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 1, 'Wtedy Anna modliła się i powiedziała: Moje serce raduje się w Panu, mój róg jest wywyższony w Panu. Moje usta szeroko otworzyły się przeciwko moim wrogom, gdyż raduję się z twego zbawienia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 2, 'Nikt nie jest tak święty jak Pan. Nie ma bowiem nikogo oprócz ciebie i nikt nie jest taką skałą jak nasz Bóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 3, 'Nie mówcie już pysznych słów i niech z waszych ust nie wychodzą słowa wyniosłe. Pan bowiem jest Bogiem wiedzy, on waży czyny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 4, 'Łuki mocarzy zostały złamane, a słabi są przepasani mocą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 5, 'Syci najmują się za chleb, a głodni przestali głodować. Nawet niepłodna urodziła siedmioro, a wielodzietna więdnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 6, 'Pan zabija i ożywia, wprowadza do grobu i wyprowadza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 7, 'Pan czyni ubogim i bogatym, poniża i wywyższa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 8, 'Podnosi z prochu ubogiego, a z gnoju podnosi żebraka, by posadzić ich z książętami i pozwolić im odziedziczyć tron chwały. Do Pana bowiem należą filary ziemi, na nich osadził świat.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 9, 'Strzeże stóp swych świętych, a bezbożni zamilkną w ciemności, bo nie swoją siłą zwycięży człowiek.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 10, 'Pan pokruszy swoich przeciwników i zagrzmi przeciwko nim z nieba. Pan będzie sądził krańce ziemi, udzieli siły swemu królowi i wywyższy róg swego pomazańca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 11, 'Potem Elkana wrócił do Rama, do swego domu, a dziecko służyło Panu przy kapłanie Helim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 12, 'Lecz synowie Heliego byli synami Beliala i nie znali Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 13, 'Był bowiem taki zwyczaj kapłanów wobec ludu: kiedy ktoś składał ofiarę, sługa kapłana przychodził, gdy mięso się gotowało, z trójzębnymi widelcami w ręce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 14, 'I wkładał je do garnka, kotła, rondla lub misy i to, co wyjął widełkami, kapłan zabierał dla siebie. Tak czynili w Szilo wszystkim Izraelitom, którzy tam przychodzili.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 15, 'Ponadto, zanim jeszcze spalono tłuszcz, przychodził sługa kapłana i mówił do człowieka składającego ofiary: Daj mięso na pieczeń dla kapłana, bo nie weźmie on od ciebie mięsa gotowanego, tylko surowe.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 16, 'A jeśli taki człowiek mu odpowiedział: Niech najpierw spalą tłuszcz, a potem weź sobie, czego pragnie twoja dusza, wtedy on mówił: Nic z tego! Daj teraz! A jeśli nie dasz, zabiorę siłą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 17, 'Tak więc grzech tych sług był bardzo wielki przed Panem, gdyż ludzie lekceważyli ofiary Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 18, 'Samuel zaś służył przed Panem jako chłopiec, przepasany lnianym efodem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 19, 'A jego matka robiła mu mały płaszcz i przynosiła mu go co roku, gdy chodziła z mężem składać doroczną ofiarę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 20, 'I Heli błogosławił Elkanie i jego żonie, mówiąc: Niech Pan da ci potomstwo z tej kobiety za uproszonego, którego oddała Panu. I wracali do swojego domu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 21, 'I Pan nawiedził Annę, a ona poczęła i urodziła trzech synów i dwie córki. A chłopiec Samuel dorastał przed Panem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 22, 'Heli zaś bardzo się zestarzał i usłyszał o wszystkim, co jego synowie czynili wobec całego Izraela, oraz o tym, że obcowali z kobietami, które się zbierały przy wejściu do Namiotu Zgromadzenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 23, 'I powiedział do nich: Dlaczego czynicie takie rzeczy? Słyszę o waszych złych czynach od całego ludu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 24, 'Nie, moi synowie, gdyż niedobra to wieść, którą słyszę. Doprowadzacie lud Pana do przestępstwa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 25, 'Jeśli człowiek zgrzeszy przeciw człowiekowi, będzie go sądzić sędzia, ale jeśli człowiek zgrzeszy przeciw Panu, któż się za nim wstawi? Oni jednak nie posłuchali głosu swego ojca, bo Pan chciał ich zabić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 26, 'A chłopiec Samuel rósł i podobał się zarówno Panu, jak i ludziom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 27, 'Potem przyszedł mąż Boży do Heliego i powiedział mu: Tak mówi Pan: Czy nie objawiłem się wyraźnie domowi twego ojca, gdy byli w Egipcie w domu faraona?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 28, 'I wybrałem go sobie spośród wszystkich pokoleń Izraela na kapłana, aby składał ofiary na moim ołtarzu, palił kadzidło i nosił efod przede mną. Dałem też domowi twego ojca wszystkie ofiary ogniowe od synów Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 29, 'Dlaczego podeptaliście moją ofiarę krwawą i pokarmową, które rozkazałem składać w przybytku? Dlaczego bardziej uczciłeś swoich synów ode mnie, abyście utuczyli się z pierwocin wszystkich ofiar pokarmowych Izraela, mojego ludu?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 30, 'Dlatego Pan, Bóg Izraela, mówi: Wprawdzie powiedziałem: Twój dom i dom twego ojca będzie chodzić przede mną na wieki, ale teraz Pan mówi: Nie będzie tak! Tych bowiem, którzy mnie czczą, ja będę czcić, a ci, którzy mną gardzą, będą wzgardzeni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 31, 'Oto nadchodzą dni, gdy odetnę twe ramię i ramię domu twego ojca, aby już nie było starca w twoim domu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 32, 'I zobaczysz przeciwnika w przybytku, wśród całego szczęścia, którego Bóg udzieli Izraelowi, i nie będzie starca w twoim domu po wszystkie dni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 33, 'Lecz nie wytracę od swego ołtarza każdego człowieka spośród ciebie, aby trapić twe oczy i ścisnąć boleścią twoją duszę. Cały przyrost twego domu umrze w sile wieku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 34, 'A to będzie znakiem, który przyjdzie na twoich dwóch synów, Chofniego i Pinchasa: obydwaj umrą tego samego dnia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 35, 'I wzbudzę sobie kapłana wiernego, który będzie postępował według mego serca i mojej myśli. Zbuduję mu trwały dom, a on będzie chodził przed moim pomazańcem po wszystkie dni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 36, 'I stanie się tak, że ktokolwiek pozostanie w twoim domu, ten przyjdzie i pokłoni mu się za srebrną monetę i za kawałek chleba, mówiąc: Dopuść mnie, proszę, do jednego z urzędów kapłańskich, abym mógł jeść kawałek chleba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 1, 'A chłopiec Samuel służył Panu przed Helim. W tych dniach słowo Pana było drogocenne i nie było jawnego widzenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 2, 'Pewnego dnia, gdy Heli leżał na swoim miejscu, a jego oczy już zaczęły słabnąć i nie mógł widzieć;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 3, 'A lampa Boża jeszcze nie zgasła w świątyni Pana, gdzie była arka Boga, i Samuel też się położył;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 4, 'Pan zawołał Samuela, a on odpowiedział: Oto jestem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 5, 'I przybiegł do Heliego, i powiedział: Oto jestem, gdyż mnie wołałeś. A on odparł: Nie wołałem, wróć i połóż się. Poszedł więc i położył się.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 6, 'Pan ponownie zawołał Samuela. I Samuel wstał, poszedł do Heliego i powiedział: Oto jestem, gdyż mnie wołałeś. On mu odpowiedział: Nie wołałem, mój synu; wróć i połóż się.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 7, 'A Samuel jeszcze nie znał Pana i słowo Pana nie zostało mu jeszcze objawione.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 8, 'I Pan zawołał Samuela po raz trzeci. Wstał więc, poszedł do Heliego i powiedział: Oto jestem, gdyż mnie wołałeś. Wtedy Heli zrozumiał, że Pan wołał chłopca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 9, 'I Heli powiedział do Samuela: Idź, połóż się, a jeśli cię zawoła, powiedz: Mów, Panie, bo twój sługa słucha. Samuel poszedł więc i położył się na swoim miejscu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 10, 'Potem Pan przyszedł, stanął i zawołał tak jak poprzednio: Samuelu, Samuelu! I Samuel odpowiedział: Mów, bo twój sługa słucha.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 11, 'Wtedy Pan powiedział do Samuela: Oto uczynię taką rzecz w Izraelu, że każdemu, kto o niej usłyszy, zadzwoni w obu uszach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 12, 'W tym dniu dokonam na Helim wszystkiego, co mówiłem przeciwko jego domowi, od początku do końca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 13, 'I dałem mu poznać, że osądzę jego dom na wieki za nieprawość, o której wiedział. Jego synowie bowiem postępowali nikczemnie, a on ich nie poskromił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 14, 'Dlatego przysiągłem domowi Heliego, że nieprawość domu Heliego nigdy nie będzie oczyszczona żadną ofiarą krwawą ani ofiarą pokarmową.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 15, 'I Samuel do rana leżał, po czym otworzył drzwi domu Pana. Samuel jednak bał się oznajmić Heliemu o widzeniu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 16, 'Wtedy Heli zawołał Samuela: Samuelu, synu mój. Ten odpowiedział: Oto jestem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 17, 'I zapytał: Cóż to za słowa, które Pan ci powiedział? Nie ukrywaj tego, proszę, przede mną. Niech Bóg tak ci uczyni i tamto dorzuci, jeśli ukryjesz przede mną cokolwiek z tego, co ci powiedział.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 18, 'Samuel opowiedział mu więc wszystko i nie ukrył nic przed nim. A on odparł: To Pan. Niech czyni to, co dobre w jego oczach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 19, 'I Samuel rósł, a Pan był z nim i nie pozwolił upaść na ziemię żadnemu z jego słów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 20, 'A cały Izrael od Dan aż do Beer-Szeby poznał, że Samuel stał się wiernym prorokiem Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 21, 'Pan zaś ukazywał się znowu w Szilo. Pan bowiem objawił się Samuelowi w Szilo przez słowo Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 1, 'I słowo Samuela dotarło do całego Izraela. W tym czasie Izrael wyruszył przeciwko Filistynom do walki i rozbili obóz koło Ebenezer. Filistyni zaś rozbili obóz w Afek.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 2, 'Wtedy Filistyni ustawili się w szyku bojowym przeciwko Izraelowi. Gdy walka rozgorzała, Izrael został pobity przez Filistynów, którzy zabili na polu bitwy około czterech tysięcy ludzi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 3, 'I kiedy lud wrócił do obozu, starsi Izraela powiedzieli: Dlaczego Pan pobił nas dziś przed Filistynami? Sprowadźmy do siebie z Szilo arkę przymierza Pana, by weszła między nas i wybawiła nas z rąk naszych wrogów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 4, 'Posłał więc lud do Szilo, by sprowadzić stamtąd arkę przymierza Pana zastępów, który zasiada między cherubinami. Byli tam też z arką przymierza Boga dwaj synowie Helego, Chofni i Pinchas.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 5, 'A gdy arka przymierza Pana przybyła do obozu, cały Izrael zawołał wielkim głosem, że aż ziemia zadrżała.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 6, 'Kiedy Filistyni usłyszeli ten okrzyk, pytali: Cóż to za wielki okrzyk w obozie Hebrajczyków? I dowiedzieli się, że arka Pana przybyła do obozu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 7, 'I Filistyni zlękli się, gdyż mówiono: Bóg przybył do ich obozu. I mówili: Biada nam, bo czegoś takiego nigdy przedtem nie było.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 8, 'Biada nam! Któż nas wybawi z rąk tych potężnych bogów? To są ci bogowie, którzy porazili Egipt wszelką plagą na pustyni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 9, 'Umacniajcie się i bądźcie mężni, o Filistyni, abyście nie służyli Hebrajczykom, tak jak oni wam służyli. Bądźcie więc mężni i walczcie!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 10, 'Wtedy Filistyni walczyli, a Izrael został pokonany i każdy uciekał do swego namiotu. Była to wielka klęska, gdyż poległo trzydzieści tysięcy z piechoty Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 11, 'I arka Boga została zabrana, a dwaj synowie Heliego, Chofni i Pinchas, polegli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 12, 'A pewien Beniaminita uciekł z bitwy i przyszedł do Szilo tego samego dnia w podartej szacie i z prochem na swojej głowie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 13, 'Kiedy przyszedł, oto Heli siedział na krześle przy drodze i wyczekiwał, bo jego serce drżało o arkę Boga. Gdy ten człowiek przyszedł do miasta i opowiedział o tym, całe miasto podniosło krzyk.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 14, 'I kiedy Heli usłyszał ten krzyk, powiedział: Cóż to za zgiełk? A ten człowiek śpiesznie przyszedł i oznajmił o tym Heliemu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 15, 'A Heli miał już dziewięćdziesiąt osiem lat i jego oczy tak zasłabły, że nie mógł nic widzieć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 16, 'Człowiek ten powiedział do Heliego: Przychodzę z bitwy, bo dziś z niej uciekłem. On zaś zapytał: Cóż tam się stało, mój synu?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 17, 'Posłaniec odpowiedział: Izrael uciekł przed Filistynami i lud poniósł wielką klęskę. Zginęli także twoi dwaj synowie, Chofni i Pinchas, a arka Boga została zabrana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 18, 'A gdy wspomniał o arce Boga, Heli spadł z krzesła na wznak obok bramy, złamał sobie kark i umarł. Był bowiem człowiekiem starym i ociężałym, a sądził Izraela przez czterdzieści lat.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 19, 'Jego synowa, żona Pinchasa, była brzemienna i bliska porodu, a gdy usłyszała wieści o zabraniu arki Bożej i o śmierci jej teścia i męża, skuliła się i urodziła. Dosięgły ją bowiem bóle porodowe.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 20, 'Gdy umierała, kobiety, które były przy niej, powiedziały: Nie bój się, bo urodziłaś syna. Lecz ona nic nie odpowiedziała ani nie zwróciła na to uwagi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 21, 'I nazwała dziecko Ikabod, mówiąc: Odeszła chwała od Izraela – z powodu zabrania arki Boga i z powodu jej teścia i męża.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 22, 'Dlatego powiedziała: Odeszła chwała od Izraela, gdyż arka Boga została zabrana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 1, 'A Filistyni wzięli arkę Boga i zanieśli ją z Ebenezer do Aszdodu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 2, 'Następnie Filistyni wzięli arkę Boga i wprowadzili do świątyni Dagona, i postawili obok Dagona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 3, 'A gdy nazajutrz rano Aszdodyci wstali, oto Dagon leżał twarzą do ziemi przed arką Pana. Podnieśli więc Dagona i postawili go na swoim miejscu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 4, 'Gdy zaś wstali kolejnego dnia rano, oto Dagon leżał twarzą do ziemi przed arką Pana. Głowa Dagona i obie dłonie jego rąk leżały odcięte na progu, z Dagona pozostał tylko tułów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 5, 'Dlatego kapłani Dagona i wszyscy, którzy wchodzą do świątyni Dagona, nie stąpają na progu Dagona w Aszdodzie aż do dziś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 6, 'Lecz ręka Pana zaciążyła nad mieszkańcami Aszdodu i niszczyła ich. Ukarał ich wrzodami – zarówno Aszdod, jak i jego okolice.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 7, 'Gdy więc mieszkańcy Aszdodu zauważyli, co się działo, powiedzieli: Arka Boga Izraela nie może z nami zostać, gdyż jego ręka jest surowa wobec nas i wobec Dagona, naszego boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 8, 'Zwołali więc i zebrali u siebie wszystkich książąt filistyńskich i powiedzieli: Co mamy zrobić z arką Boga Izraela? I odpowiedzieli: Niech arka Boga Izraela zostanie przeniesiona do Gat. I przeniesiono tam arkę Boga Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 9, 'A gdy ją przenieśli, ręka Pana powstała przeciwko miastu i dotknęła je wielkim uciskiem. Pokarała mieszkańców miasta, od najmniejszego do największego, i pojawiły się u nich wrzody w ukrytych miejscach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 10, 'Wysłali więc arkę Boga do Ekronu. A gdy arka Boga przybyła do Ekronu, Ekronici zawołali: Przynieśli do nas arkę Boga Izraela, aby zgładzić nas i nasz lud.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 11, 'Dlatego zwołali i zgromadzili wszystkich książąt filistyńskich, i powiedzieli: Odeślijcie arkę Boga Izraela, niech powróci na swoje miejsce, aby nie zabiła nas i naszego ludu. W całym mieście panował bowiem śmiertelny strach i bardzo zaciążyła tam ręka Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 12, 'A mieszkańcy, którzy nie umarli, byli dotknięci wrzodami. I krzyk miasta wznosił się ku niebu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 1, 'I arka Pana przebywała w ziemi Filistynów przez siedem miesięcy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 2, 'Wtedy Filistyni zwołali kapłanów i wróżbitów i zapytali: Co mamy zrobić z arką Pana? Powiedzcie nam, jak mamy ją odesłać na swoje miejsce?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 3, 'Ci odpowiedzieli: Jeśli odsyłacie arkę Boga Izraela, nie odsyłajcie jej z niczym, lecz koniecznie oddajcie mu ofiarę za grzech: wtedy będziecie uzdrowieni i dowiecie się, czemu jego ręka nie odstąpiła od was.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 4, 'I powiedzieli: Jaką ofiarę za grzech mamy mu złożyć? Odpowiedzieli: Według liczby książąt filistyńskich pięć wrzodów złotych i pięć myszy złotych. Ta sama bowiem plaga dotknęła was wszystkich i waszych książąt.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 5, 'I sporządzicie podobizny waszych wrzodów i podobizny waszych myszy, które niszczą ziemię, i oddacie chwałę Bogu Izraela. Może odejmie swoją rękę od was, waszych bogów i waszej ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 6, 'Dlaczego zatwardzacie swoje serca tak, jak Egipcjanie i faraon zatwardzali swoje serca? Czy nie dopiero wtedy, gdy czynił wśród nich cudowne rzeczy, wypuścili ich, aby wyszli?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 7, 'Teraz więc przygotujcie nowy wóz, weźcie dwie mleczne krowy, na które nie nałożono jarzma, i zaprzęgnijcie te krowy do wozu, a ich cielęta odprowadźcie od nich do domu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 8, 'Weźcie też arkę Pana i włóżcie ją na wóz; a złote przedmioty, które oddajecie jako ofiarę za grzech, włóżcie do skrzynki obok niej. Po czym puśćcie go i niech jedzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 9, 'Wtedy patrzcie – jeśli pojedzie drogą własnej granicy do Bet-Szemesz, to Pan wyrządził nam to wielkie zło. Lecz jeśli nie, to będziemy wiedzieli, że to nie jego ręka nas dotknęła, ale to, co nas spotkało, było przypadkiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 10, 'I ci ludzie tak uczynili: wzięli dwie mleczne krowy i zaprzęgli je do wozu, a ich cielęta zamknęli w domu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 11, 'Potem włożyli arkę Pana na wóz oraz skrzynkę ze złotymi myszami i z podobiznami swoich wrzodów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 12, 'I krowy poszły prostą drogą ku Bet-Szemesz. Szły jednym gościńcem, a idąc, ryczały i nie zbaczały ani w prawo, ani w lewo. A książęta filistyńscy szli za nimi aż do granicy Bet-Szemesz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 13, 'W tym czasie mieszkańcy Bet-Szemesz żęli pszenicę w dolinie, a gdy podnieśli swe oczy, zobaczyli arkę i uradowali się na jej widok.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 14, 'Wóz zaś dotarł na pole Jozuego z Bet-Szemesz i tam się zatrzymał, tam też był wielki kamień. Wtedy porąbali drewno z tego wozu i złożyli Panu krowy na ofiarę całopalną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 15, 'Lewici zdjęli arkę Pana oraz skrzynkę obok niej, w której były złote przedmioty, i postawili to na tym wielkim kamieniu. Ludzie zaś z Bet-Szemesz w tym dniu złożyli Panu całopalenia i ofiary.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 16, 'Gdy pięciu książąt filistyńskich zobaczyło to wszystko, tego samego dnia powrócili do Ekronu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 17, 'A oto złote wrzody, które Filistyni oddali Panu jako ofiarę za grzech: za Aszdod – jeden, za Gazę – jeden, za Aszkelon – jeden, za Gat – jeden i za Ekron – jeden.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 18, 'Dodatkowo złote myszy według liczby wszystkich miast filistyńskich należących do pięciu książąt, zarówno warownych miast, jak i wiosek bez muru, i aż do tego wielkiego kamienia, na którym postawili arkę Pana. Znajduje się aż do dziś na polu Jozuego z Bet-Szemesz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 19, 'Lecz Pan wytracił spośród ludzi z Bet-Szemesz, ponieważ zaglądali do arki Pana, zabił z ludu pięćdziesiąt tysięcy siedemdziesiąt osób. I lud ich opłakiwał, ponieważ Pan zadał ludowi wielką klęskę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 20, 'Ludzie z Bet-Szemesz mówili: Któż zdoła ostać się przed tym świętym Panem Bogiem? I do kogo on pójdzie od nas?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 21, 'Wyprawili więc posłańców do mieszkańców Kiriat-Jearim z wiadomością: Filistyni zwrócili arkę Pana. Przyjdźcie i zabierzcie ją do siebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 1, 'Przyszli więc ludzie z Kiriat-Jearim, zabrali arkę Pana i wnieśli ją do domu Abinadaba na wzgórzu. Eleazara zaś, jego syna, poświęcili, aby strzegł arki Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 2, 'A od dnia przybycia arki do Kiriat-Jearim upłynęło dużo czasu, to jest dwadzieścia lat, a cały dom Izraela płakał za Panem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 3, 'I Samuel powiedział do całego domu Izraela: Jeśli z całego swego serca nawrócicie się do Pana, wyrzućcie spośród siebie obcych bogów oraz Asztarty i przygotujcie swoje serce Panu, i służcie tylko jemu. Wtedy wybawi was z ręki Filistynów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 4, 'Synowie Izraela usunęli więc Baalów i Asztarty i służyli tylko Panu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 5, 'Wtedy Samuel powiedział: Zgromadźcie całego Izraela w Mispie, a ja będę modlił się za wami do Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 6, 'Zgromadzili się więc w Mispie i czerpali wodę, którą wylewali przed Panem. Pościli tam tego dnia i mówili: Zgrzeszyliśmy przeciw Panu. A Samuel sądził synów Izraela w Mispie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 7, 'A gdy Filistyni usłyszeli, że synowie Izraela zgromadzili się w Mispie, wyruszyli książęta filistyńscy przeciw Izraelowi. Kiedy usłyszeli o tym synowie Izraela, zlękli się Filistynów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 8, 'I synowie Izraela powiedzieli do Samuela: Nie przestawaj wołać za nami do Pana, naszego Boga, aby nas wybawił z ręki Filistynów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 9, 'Samuel wziął więc jedno jagnię ssące i złożył je Panu w ofierze całopalnej. I Samuel wołał do Pana za Izraelem, a Pan go wysłuchał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 10, 'A kiedy Samuel składał całopalenie, Filistyni nadciągnęli, aby walczyć z Izraelem. Lecz w tym dniu Pan zagrzmiał wielkim grzmotem nad Filistynami i rozproszył ich tak, że zostali pobici przed Izraelem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 11, 'A Izraelici wyruszyli z Mispy, gonili Filistynów i bili ich aż pod Bet-Kar.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 12, 'Wtedy Samuel wziął kamień, ustawił go między Mispą a Szen i nazwał go Ebenezer, mówiąc: Aż dotąd pomagał nam Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 13, 'Tak zostali upokorzeni Filistyni i już nie przekraczali granic Izraela, a ręka Pana była przeciwko Filistynom po wszystkie dni Samuela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 14, 'Izraelowi zostały przywrócone miasta, które Filistyni zabrali Izraelowi, od Ekronu aż do Gat, a ich granice wyzwolił Izrael z ręki Filistynów. I pokój panował między Izraelem a Amorytami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 15, 'A Samuel sądził Izraela po wszystkie dni swego życia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 16, 'Co roku chodził też i obchodził Betel, Gilgal i Mispę i sądził Izraela we wszystkich tych miejscach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 17, 'Potem wracał do Rama, ponieważ tam był jego dom. Tam sądził Izraela i tam też zbudował ołtarz Panu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 1, 'A gdy Samuel zestarzał się, ustanowił swoich synów sędziami nad Izraelem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 2, 'Jego pierworodny syn miał na imię Joel, a drugi syn – Abija; byli oni sędziami w Beer-Szebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 3, 'Jednak jego synowie nie chodzili jego drogami, lecz skłaniali się ku zyskowi, brali łapówki i wypaczali sąd.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 4, 'Zebrali się więc wszyscy starsi Izraela i przyszli do Samuela, do Rama;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 5, 'I powiedzieli mu: Oto zestarzałeś się, a twoi synowie nie chodzą twoimi drogami. Ustanów nam więc króla, aby nas sądził, jak to jest u wszystkich narodów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 6, 'Lecz Samuelowi nie podobało się to, że mówili: Daj nam króla, aby nas sądził. I modlił się Samuel do Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 7, 'Wtedy Pan powiedział do Samuela: Posłuchaj głosu tego ludu we wszystkim, co ci powiedzą, gdyż nie tobą wzgardzili, ale mną wzgardzili, abym nie królował nad nimi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 8, 'A zgodnie ze wszystkim, co uczynili od tego dnia, kiedy wyprowadziłem ich z Egiptu, aż do dziś, gdy mnie opuścili i służyli obcym bogom, tak też czynią z tobą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 9, 'Teraz więc posłuchaj ich głosu, ale stanowczo ostrzeż ich i oznajmij im prawo króla, który będzie nad nimi panować.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 10, 'I Samuel powiedział wszystkie słowa Pana do ludu, który go prosił o króla;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 11, 'I mówił: Takie będzie prawo króla, który będzie panował nad wami: Będzie brał waszych synów, by ich osadzić w swych rydwanach, ustanowić ich jeźdźcami, a inni będą biegać przed jego rydwanem;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 12, 'I ustanowi ich sobie dowódcami nad tysiącami i nad pięćdziesiątkami; wyznaczy ich, aby uprawiali jego rolę i zbierali jego plony, i robili sprzęt wojenny oraz sprzęt do jego rydwanów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 13, 'Wasze córki również zabierze, aby przyrządzały wonności oraz aby były kucharkami i piekarkami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 14, 'Zabierze też wasze pola, winnice i sady oliwne, te najlepsze, i da swoim sługom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 15, 'Z waszych zasiewów i winnic będzie pobierał dziesięcinę i odda ją swoim urzędnikom i sługom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 16, 'Weźmie również wasze sługi i służące oraz waszych najlepszych młodzieńców, a także wasze osły, i zatrudni w swojej pracy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 17, 'Pobierze dziesięcinę z waszych trzód, a wy będziecie jego sługami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 18, 'I będziecie wołać tego dnia z powodu waszego króla, którego sobie wybraliście, a Pan nie wysłucha was w tym dniu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 19, 'Lud jednak nie chciał posłuchać głosu Samuela i mówił: Nie tak, ale niech będzie król nad nami;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 20, 'Abyśmy też byli jak wszystkie narody – aby nasz król sądził nas, aby nam przewodził i prowadził nasze wojny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 21, 'A Samuel wysłuchał wszystkich słów ludu i powtórzył je do uszu Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 22, 'I Pan powiedział do Samuela: Posłuchaj ich głosu i ustanów nad nimi króla. Samuel powiedział więc do mężczyzn Izraela: Idźcie każdy do swego miasta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 1, 'Był pewien człowiek z pokolenia Beniamina, któremu na imię było Kisz – syn Abiela, syna Cerora, syna Bekorata, syna Afiacha, Beniaminita, dzielny mąż.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 2, 'Miał on syna imieniem Saul, urodziwego młodzieńca. Nie było nikogo spośród synów Izraela przystojniejszego niż on. Wzrostem o głowę przewyższał cały lud.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 3, 'A zaginęły oślice Kisza, ojca Saula. Wtedy Kisz powiedział do swego syna Saula: Weź teraz ze sobą jednego ze sług i wstań, idź, poszukaj oślic.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 4, 'Przeszedł więc przez górę Efraim i przez ziemię Szalisza, lecz ich nie znaleźli. Przeszli także przez ziemię Szaalim, ale ich nie znaleźli. Przeszli też przez ziemię Beniamina i ich nie znaleźli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 5, 'Kiedy przyszli do ziemi Suf, Saul powiedział do swego sługi, który z nim był: Chodź, wracajmy, by czasem mój ojciec nie zaniechał troski o oślice i nie martwił się o nas.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 6, 'Ten mu odpowiedział: Oto teraz w tym mieście jest mąż Boży, człowiek szanowany; wszystko, co mówi, spełnia się. Pójdźmy więc tam, może wskaże nam drogę, którą mamy iść.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 7, 'Wtedy Saul odpowiedział swemu słudze: Jeśli pójdziemy, cóż przyniesiemy temu człowiekowi? Chleb bowiem wyczerpał się już w naszych torbach i nie mamy podarunku, który moglibyśmy przynieść mężowi Bożemu. Cóż mamy?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 8, 'Sługa znowu odpowiedział Saulowi: Oto mam przy sobie ćwierć srebrnego sykla. Dam to mężowi Bożemu, aby oznajmił nam naszą drogę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 9, 'Dawniej w Izraelu, kiedy ktoś szedł poradzić się Boga, tak mówił: Chodźcie, pójdziemy do widzącego. Dzisiejszego proroka bowiem dawniej nazywano widzącym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 10, 'Wtedy Saul powiedział do swego sługi: Słuszne jest twoje słowo, chodź, pójdziemy. I udali się do miasta, w którym był mąż Boży.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 11, 'A gdy wchodzili na górę do miasta, spotkali dziewczęta, które wyszły naczerpać wody. I zapytali je: Czy jest tu widzący?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 12, 'One odpowiedziały im: Tak, oto jest przed tobą. Pośpiesz się, dziś bowiem przyszedł do miasta, gdyż dziś lud składa ofiary na wyżynie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 13, 'Gdy wejdziecie do miasta, znajdziecie go, zanim pójdzie na wyżynę na posiłek. Lud bowiem nie będzie jadł, dopóki on nie przyjdzie, gdyż on błogosławi ofiarę. Dopiero potem jedzą zaproszeni. Idźcie więc, bo właśnie teraz go spotkacie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 14, 'Ruszyli więc do miasta. A gdy wchodzili do miasta, oto Samuel wychodził im naprzeciw, udając się na wyżynę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 15, 'A Pan wyjawił Samuelowi na dzień przed przybyciem Saula, mówiąc mu:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 16, 'Jutro w tym czasie wyślę do ciebie człowieka z ziemi Beniamina. Jego namaścisz na wodza nad moim ludem Izraelem; a on wybawi mój lud z rąk Filistynów. Wejrzałem bowiem na swój lud, gdyż jego lament dotarł do mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 17, 'A gdy Samuel zobaczył Saula, Pan mu powiedział: Oto człowiek, o którym ci powiedziałem. Właśnie on będzie panował nad moim ludem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 18, 'Wtedy Saul zbliżył się do Samuela w bramie i powiedział: Proszę, powiedz mi, gdzie jest dom widzącego?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 19, 'Samuel odpowiedział Saulowi: Ja jestem widzący. Idź przede mną na wyżynę. Dziś będziecie jeść ze mną, a jutro rano odprawię cię i powiem ci wszystko, co jest w twoim sercu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 20, 'A co do oślic, które ci zaginęły trzy dni temu, nie martw się, bo już się znalazły. I na kogo jest zwrócone wszelkie pragnienie Izraela? Czy nie na ciebie i na cały dom twego ojca?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 21, 'Saul odpowiedział: Czyż nie jestem Beniaminitą – z najmniejszego pokolenia Izraela? I czyż moja rodzina nie jest najmniejsza ze wszystkich rodzin pokolenia Beniamina? Dlaczego więc mówisz do mnie takie słowa?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 22, 'I Samuel zabrał Saula i jego sługę, zaprowadził ich do sali i dał im pierwsze miejsce wśród zaproszonych, a było ich około trzydziestu ludzi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 23, 'Wtedy Samuel powiedział do kucharza: Podaj tę część, którą ci dałem i o której ci mówiłem: Zatrzymaj ją u siebie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 24, 'Kucharz przyniósł łopatkę i to, co było na niej, i położył przed Saulem, a Samuel powiedział: Oto co zostało, połóż to przed sobą i jedz, bo kiedy powiedziałem: Wezwałem lud – zostało to zachowane dla ciebie na tę chwilę. I Saul jadł razem z Samuelem tego dnia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 25, 'A gdy zeszli z wyżyny do miasta, Samuel rozmawiał z Saulem na dachu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 26, 'Potem wstali wcześnie rano. I gdy zaczęło świtać, Samuel zawołał Saula na dach, mówiąc: Wstań, a wyprawię cię. Saul wstał więc i obaj wyszli z domu, on i Samuel.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 27, 'A gdy schodzili ku granicy miasta, Samuel odezwał się do Saula: Powiedz słudze, aby poszedł przed nami. I gdy ten poszedł, dodał: Ty zaś zatrzymaj się na chwilę, abym ci oznajmił słowo Boże.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 1, 'Wtedy Samuel wziął flakonik oliwy i wylał ją na jego głowę, pocałował go i powiedział: Czyż Pan nie namaścił cię na wodza nad swoim dziedzictwem?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 2, 'Gdy dziś odejdziesz ode mnie, spotkasz dwóch mężczyzn przy grobie Racheli, na granicy Beniamina w Celcach, którzy ci powiedzą: Znalazły się oślice, których poszedłeś szukać, a twój ojciec zaniechał troski o oślice i martwi się o was, mówiąc: Cóż mam uczynić dla swego syna?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 3, 'A gdy odejdziesz stamtąd dalej i przyjdziesz aż na pole Tabor, spotkają cię tam trzej mężczyźni idący do Boga, do Betel. Jeden będzie niósł troje koźląt, drugi będzie niósł trzy bochenki chleba, a trzeci będzie niósł bukłak wina.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 4, 'I pozdrowią cię w pokoju, i dadzą ci dwa chleby, które weźmiesz z ich rąk.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 5, 'Potem przyjdziesz na pagórek Boży, gdzie jest załoga filistyńska. A gdy tam będziesz wchodził do miasta, spotkasz się z gromadą proroków schodzących z wyżyny. Przed nimi będą: cytra, bęben, flet i harfa, a oni będą prorokować.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 6, 'Wtedy zstąpi na ciebie Duch Pana i będziesz prorokował wraz z nimi, i przemienisz się w innego człowieka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 7, 'A gdy te znaki spełnią się na tobie, czyń wszystko, co zdoła zrobić twoja ręka, gdyż Bóg jest z tobą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 8, 'Potem pójdziesz przede mną do Gilgal, a ja przyjdę do ciebie, aby złożyć całopalenia i ofiary pojednawcze. Przez siedem dni będziesz czekał, aż przyjdę do ciebie i pokażę to, co masz czynić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 9, 'I kiedy odwrócił się, aby odejść od Samuela, Bóg przemienił mu serce na inne i w tym dniu spełniły się wszystkie te znaki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 10, 'I gdy przybyli na pagórek, spotkała go gromada proroków i spoczął na nim Duch Boży, i prorokował pośród nich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 11, 'A kiedy wszyscy, którzy go wcześniej znali, zobaczyli, że prorokuje razem z prorokami, mówili jeden do drugiego: Cóż się stało synowi Kisza? Czy również Saul jest wśród proroków?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 12, 'Pewien człowiek spośród nich zapytał: A kto jest ich ojcem? Dlatego powstało przysłowie: Czyż i Saul jest wśród proroków?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 13, 'A kiedy przestał prorokować, przyszedł na wyżynę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 14, 'Potem stryj Saula powiedział do niego i do jego sługi: Gdzie byliście? I odpowiedział: Szukaliśmy oślic. A widząc, że ich nie ma, poszliśmy do Samuela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 15, 'I stryj Saula powiedział: Powiedz mi, proszę, co wam powiedział Samuel.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 16, 'Saul odpowiedział swemu stryjowi: Zapewnił nas, że oślice się znalazły. Lecz nie powiedział mu o sprawie królestwa, o którym Samuel mówił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 17, 'Potem Samuel zwołał lud do Pana do Mispy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 18, 'I przemówił do synów Izraela: Tak mówi Pan, Bóg Izraela: Ja wyprowadziłem Izraela z Egiptu i wybawiłem was z rąk Egipcjan oraz z rąk wszystkich królestw, które was uciskały;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 19, 'Lecz wy dziś odrzuciliście waszego Boga, który was wybawił od wszystkich nieszczęść i ucisków, i powiedzieliście mu: Ustanów króla nad nami. Teraz więc ustawcie się przed Panem według waszych pokoleń i według waszych tysięcy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 20, 'A gdy Samuel kazał zbliżyć się wszystkim pokoleniom Izraela, los padł na pokolenie Beniamina.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 21, 'Potem kazał zbliżyć się pokoleniu Beniamina według jego rodzin i los padł na dom Matriego i trafił na Saula, syna Kisza. I szukali go, lecz go nie znaleźli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 22, 'Pytali więc Pana znowu: Czy przyjdzie jeszcze ten człowiek? Pan odpowiedział: Oto ukrył się wśród tobołów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 23, 'Pobiegli i przyprowadzili go stamtąd. Gdy stanął pośród ludu, wzrostem przewyższał o głowę cały lud.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 24, 'I Samuel powiedział do całego ludu: Widzicie, kogo wybrał sobie Pan – że wśród całego ludu nie ma mu równego? A cały lud krzyknął: Niech żyje król!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 25, 'Wtedy Samuel ogłosił ludowi prawo królewskie, spisał je w księdze i złożył przed Panem. Potem Samuel odesłał cały lud, każdego do swego domu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 26, 'Również i Saul poszedł do swego domu do Gibea. A szli za nim wojownicy, których serca Bóg dotknął.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 27, 'Lecz synowie Beliala powiedzieli: Ten ma nas wybawić? Wzgardzili nim i nie przynieśli mu żadnych darów. On zaś milczał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 1, 'Wtedy nadciągnął Nachasz Ammonita i rozbił obóz przeciwko Jabesz-Gilead. I wszyscy mieszkańcy Jabesz powiedzieli do Nachasza: Zawrzyj z nami przymierze, a będziemy ci służyć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 2, 'Odpowiedział im Nachasz Ammonita: Zawrę z wami przymierze, pod warunkiem że każdemu z was wyłupię prawe oko i będzie to hańba dla całego Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 3, 'Starsi z Jabesz odpowiedzieli mu: Daj nam siedem dni na rozesłanie posłańców po wszystkich granicach Izraela. A jeśli nie będzie nikogo, kto by nas uratował, wtedy wyjdziemy do ciebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 4, 'Przyszli więc posłańcy do Gibea, miasta Saula, i powtórzyli te słowa do uszu ludu. Cały lud zaś podniósł donośny lament i płakał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 5, 'A oto Saul wracał za wołami z pola i pytał się: Co się stało ludowi, że płacze? I opowiedzieli mu wszystkie słowa mieszkańców Jabesz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 6, 'Gdy Saul usłyszał te słowa, zstąpił na niego Duch Boży i Saul zapałał wielkim gniewem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 7, 'I wziął parę wołów, rozrąbał je na części i rozesłał je przez posłańców po wszystkich granicach Izraela, mówiąc: Tak się stanie z wołami każdego, kto nie wyruszy za Saulem i Samuelem. I padł strach Pana na lud, i wyruszyli jak jeden mąż.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 8, 'Potem dokonał ich przeglądu w Bezek – było trzysta tysięcy synów Izraela, a mężczyzn Judy trzydzieści tysięcy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 9, 'I powiedzieli posłańcom, którzy przyszli: Tak powiedzcie mieszkańcom Jabesz-Gilead: Jutro, gdy przygrzeje słońce, zostaniecie wybawieni. Posłańcy wrócili więc i oznajmili to mieszkańcom Jabesz, a oni ucieszyli się.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 10, 'Wtedy mieszkańcy Jabesz powiedzieli: Jutro wyjdziemy do was i uczynicie z nami wszystko, co się wam podoba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 11, 'Nazajutrz Saul podzielił lud na trzy oddziały. One wtargnęły do środka obozu podczas straży porannej i biły Ammonitów aż do dziennej spiekoty. Ci, którzy pozostali, rozpierzchli się tak, że dwóch razem nie zostało.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 12, 'Wtedy lud powiedział do Samuela: Kto to mówił: Czy Saul będzie królować nad nami? Wydajcie tych ludzi, abyśmy ich zabili.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 13, 'I Saul odpowiedział: Nikt nie zostanie zabity w tym dniu, gdyż dzisiaj Pan dokonał wybawienia w Izraelu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 14, 'Potem Samuel odezwał się do ludu: Chodźcie, pójdziemy do Gilgal i tam odnowimy królestwo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 15, 'Cały lud wyruszył więc do Gilgal i tam ustanowili Saula królem przed Panem w Gilgal. Tam też składali ofiary pojednawcze przed Panem i bardzo się radowali, Saul i wszyscy Izraelici.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 1, 'Wtedy Samuel przemówił do całego Izraela: Posłuchałem waszego głosu we wszystkim, o czym mi mówiliście, i ustanowiłem nad wami króla.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 2, 'A teraz król chodzi przed wami. Ja zaś zestarzałem się i osiwiałem. Oto moi synowie są z wami, a ja chodziłem przed wami od mojej młodości aż do dziś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 3, 'Oto jestem tu. Świadczcie przeciwko mnie przed Panem i przed jego pomazańcem: Czy komu zabrałem wołu? Czy komu zabrałem osła? Czy kogoś oszukałem? Czy kogoś uciskałem? Czy z czyjejś ręki przyjąłem podarunek, aby na coś przymknąć oczy? Jeśli tak, oddam wam wszystko.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 4, 'I odpowiedzieli: Nie oszukałeś nas ani nie uciskałeś nas, ani nie wziąłeś żadnej rzeczy z niczyjej ręki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 5, 'Wtedy powiedział do nich: Pan jest świadkiem przeciwko wam, świadkiem jest też dzisiaj pomazaniec, że nic nie znaleźliście w mojej ręce. A oni odpowiedzieli: On jest świadkiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 6, 'Samuel przemówił dalej do ludu: To Pan, który ustanowił Mojżesza i Aarona i który wyprowadził waszych ojców z ziemi Egiptu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 7, 'Dlatego teraz stańcie, abym spierał się z wami przed Panem o wszystkie sprawiedliwe dzieła Pana, które czynił wam i waszym ojcom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 8, 'Gdy Jakub przybył do Egiptu, a wasi ojcowie wołali do Pana, posłał Pan Mojżesza i Aarona, którzy wyprowadzili waszych ojców z Egiptu i posadzili ich na tym miejscu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 9, 'A gdy zapomnieli Pana, swego Boga, wydał ich w ręce Sisery, dowódcy wojska Chasoru, w ręce Filistynów i w ręce króla Moabu, a oni walczyli z nimi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 10, 'Lecz gdy wołali do Pana, mówiąc: Zgrzeszyliśmy, bo opuściliśmy Pana i służyliśmy Baalom i Asztartom. Teraz jednak wybaw nas z rąk naszych wrogów, a będziemy tobie służyli;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 11, 'Wtedy Pan posłał Jerubbaala, Bedana, Jeftego i Samuela i wyrwał was z rąk waszych wrogów, którzy was otaczali, i mieszkaliście bezpiecznie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 12, 'A gdy widzieliście, że Nachasz, król synów Ammona, nadciągnął przeciwko wam, powiedzieliście do mnie: Nie tak, lecz król będzie panował nad nami. Choć Pan, wasz Bóg, był waszym królem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 13, 'Teraz więc oto jest król, którego sobie wybraliście, którego żądaliście. Oto Pan ustanowił nad wami króla.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 14, 'Jeśli będziecie się bali Pana, jemu służyli, słuchali jego głosu i nie sprzeciwiali się słowu Pana, wtedy i wy, i król, który panuje nad wami, będziecie szczęśliwie chodzić za Panem, swoim Bogiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 15, 'Lecz jeśli nie będziecie słuchać głosu Pana, a sprzeciwicie się słowu Pana, to ręka Pana będzie przeciwko wam, tak jak była przeciwko waszym ojcom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 16, 'Teraz stójcie więc i zobaczcie tę wielką rzecz, którą Pan uczyni na waszych oczach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 17, 'Czy nie dziś są żniwa pszeniczne? Będę wzywał Pana, a on ześle grzmoty i deszcz, abyście poznali i zobaczyli, jak wielka jest wasza niegodziwość, której się dopuściliście w oczach Pana, żądając dla siebie króla.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 18, 'Samuel wołał więc do Pana, a Pan zesłał grzmoty i deszcz tego samego dnia. I cały lud bardzo bał się Pana i Samuela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 19, 'Wtedy cały lud powiedział do Samuela: Módl się za swoimi sługami do Pana, swego Boga, abyśmy nie pomarli. Dodaliśmy bowiem do wszystkich naszych grzechów to zło, że prosiliśmy dla siebie o króla.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 20, 'Samuel odpowiedział ludowi: Nie bójcie się. Wprawdzie uczyniliście całe to zło. Nie odstępujcie jednak od Pana, lecz służcie Panu z całego swego serca;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 21, 'A nie zbaczajcie z tej drogi, by iść za marnościami, które w niczym wam nie pomogą ani was nie wybawią, gdyż są marnością.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 22, 'Pan bowiem nie opuści swego ludu przez wzgląd na swoje wielkie imię, gdyż spodobało się Panu uczynić was swoim ludem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 23, 'A jeśli chodzi o mnie, nie daj Boże, bym miał grzeszyć przeciw Panu, przestając się modlić za was. Przeciwnie, będę was uczył dobrej i prostej drogi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 24, 'Tylko bójcie się Pana i służcie mu w prawdzie z całego swego serca. Spójrzcie, jak wielkie rzeczy wam uczynił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 25, 'Lecz jeśli będziecie trwać w niegodziwości, to zarówno wy, jak i wasz król zginiecie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 1, 'Saul królował już rok, a gdy królował dwa lata nad Izraelem;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 2, 'Wybrał sobie trzy tysiące ludzi z Izraela. Dwa tysiące było przy Saulu w Mikmas i na górze Betel, a tysiąc był z Jonatanem w Gibea Beniamina. Resztę ludu rozesłał, każdego do swego namiotu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 3, 'Wtedy Jonatan pobił załogę Filistynów, która była w Geba, o czym usłyszeli Filistyni. Saul zadął więc w trąbę po całej ziemi i powiedział: Niech usłyszą o tym Hebrajczycy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 4, 'I cały Izrael usłyszał, że mówiono: Saul pobił załogę Filistynów i z tego powodu Izrael stał się obmierzły dla Filistynów. I zwołano lud, by wyruszył za Saulem do Gilgal.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 5, 'Filistyni też zgromadzili się do walki z Izraelem: trzydzieści tysięcy rydwanów i sześć tysięcy jeźdźców, a ludu tak dużo jak piasku nad brzegiem morza. I nadciągnęli, i rozbili obóz w Mikmas, na wschód od Bet-Awen.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 6, 'A gdy Izraelici widzieli, że są w niebezpieczeństwie – gdyż lud był strapiony – ukryli się w jaskiniach, zaroślach, skałach, twierdzach i jamach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 7, 'Niektórzy Hebrajczycy przeprawili się za Jordan, do ziemi Gad i Gilead. Lecz Saul jeszcze został w Gilgal, a cały lud szedł za nim strwożony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 8, 'I czekał przez siedem dni zgodnie z czasem wyznaczonym przez Samuela. Kiedy jednak Samuel nie przyszedł do Gilgal, cały lud odszedł od niego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 9, 'Wtedy Saul powiedział: Przynieście mi całopalenie i ofiary pojednawcze. I złożył całopalenie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 10, 'Gdy skończył składać całopalenie, oto przyszedł Samuel, a Saul wyszedł mu naprzeciw, aby go przywitać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 11, 'I Samuel zapytał: Co uczyniłeś? Saul odpowiedział: Ponieważ widziałem, że lud rozchodzi się ode mnie, że ty nie przyszedłeś w oznaczonym czasie, a Filistyni zgromadzili się w Mikmas;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 12, 'Wtedy powiedziałem: Oto Filistyni zstąpią na mnie do Gilgal, a ja jeszcze nie zjednałem sobie Pana. Przezwyciężyłem się więc i złożyłem całopalenie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 13, 'Samuel powiedział do Saula: Głupio postąpiłeś. Nie zachowałeś przykazania Pana, swego Boga, które ci nadał. Pan bowiem teraz utwierdziłby twoje królestwo nad Izraelem aż na wieki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 14, 'Lecz teraz twoje królestwo się nie ostoi. Pan wyszukał sobie człowieka według swego serca i Pan ustanowił go wodzem nad swoim ludem, gdyż nie zachowałeś tego, co ci Pan rozkazał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 15, 'Wtedy Samuel wstał i wyruszył z Gilgal do Gibea Beniamina. I Saul policzył lud, który znajdował się przy nim: było ich wszystkich około sześciuset mężczyzn.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 16, 'Saul więc i jego syn Jonatan oraz lud, który znajdował się przy nich, zostali w Gibea Beniamina. Filistyni zaś rozbili obóz w Mikmas.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 17, 'I łupieżcy wyszli z obozu Filistynów w trzech oddziałach: jeden oddział skierował się w stronę Ofry, do ziemi Szaul.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 18, 'Drugi oddział skierował się w stronę Bet-Choron. Trzeci zaś oddział udał się w stronę granicy przylegającej do doliny Seboim – ku pustyni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 19, 'Lecz w całej ziemi Izraela nie było żadnego kowala, bo Filistyni mówili: Niech Hebrajczycy nie robią mieczów ani włóczni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 20, 'Cały Izrael schodził więc do Filistynów, by każdy naostrzył sobie swój lemiesz, redlicę, siekierę i motykę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 21, 'Mieli bowiem tylko pilnik do ścierania lemieszy, motyk, wideł, siekier i ościeni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 22, 'Tak więc się stało, że w dniu bitwy nie można było znaleźć miecza ani włóczni w ręku całego ludu, który był z Saulem i Jonatanem. Znajdowały się tylko u Saula i jego syna Jonatana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 23, 'A załoga Filistynów wyruszyła na przełęcz Mikmas.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 1, 'Pewnego dnia Jonatan, syn Saula, powiedział do swego giermka: Chodź, pójdziemy do załogi Filistynów, która jest po tamtej stronie. Lecz swemu ojcu nic o tym nie powiedział.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 2, 'Saul zaś pozostał na krańcu Gibea pod drzewem granatu, które było w Migron. A lud, który był z nim, liczył około sześciuset mężczyzn.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 3, 'A Achiasz, syn Achituba, brata Ikaboda, syna Pinchasa, syna Helego, kapłana Pana w Szilo, nosił wtedy efod. Lud zaś nie wiedział, że Jonatan odszedł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 4, 'Między przełęczami, gdzie Jonatan chciał przejść do załogi Filistynów, była ostra skała po jednej stronie i ostra skała po drugiej stronie; jedną z nich nazywano Boses, a drugą – Senne.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 5, 'Jedna skała była zwrócona na północ, naprzeciw Mikmas, a druga – na południe, naprzeciw Gibea.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 6, 'I Jonatan powiedział do swego giermka: Chodź, pójdziemy do załogi tych nieobrzezanych, może Pan zadziała dla nas, gdyż Panu nietrudno wybawić przez wielu czy przez niewielu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 7, 'Jego giermek odpowiedział mu: Czyń wszystko, co jest w twoim sercu. Idź, oto ja jestem z tobą według twojej woli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 8, 'Wtedy Jonatan powiedział: Pójdziemy do tych ludzi i pokażemy się im.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 9, 'Jeśli powiedzą nam: Czekajcie, aż przyjdziemy do was, to zatrzymamy się na swym miejscu i nie pójdziemy do nich;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 10, 'Lecz jeśli powiedzą: Chodźcie do nas, to pójdziemy, gdyż Pan wydał ich w nasze ręce. To będzie dla nas znakiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 11, 'Pokazali się więc obaj straży filistyńskiej. I Filistyni powiedzieli: Oto Hebrajczycy wychodzą z nor, w których się ukryli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 12, 'I ludzie ze straży odezwali się do Jonatana i giermka: Podejdźcie do nas, a pokażemy wam coś. Jonatan powiedział do swego giermka: Chodź za mną, gdyż Pan wydał ich w ręce Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 13, 'Jonatan wspinał się na swych rękach i nogach, a jego giermek szedł za nim. I padali przed Jonatanem, a jego giermek, idący za nim, dobijał ich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 14, 'To była pierwsza klęska, jaką zadali Jonatan i jego giermek. Zabili około dwudziestu ludzi, na przestrzeni około morgi pola.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 15, 'I padł strach na obóz w polu i na cały lud. Przeraziły się także załoga oraz łupieżcy, a ziemia zatrzęsła się, wywołując wielką trwogę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 16, 'I strażnicy Saula w Gibea Beniamina zobaczyli, że tłum się rozpierzchł i biegł w bezładzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 17, 'Wtedy Saul powiedział do ludu, który przy nim był: Dokonajcie przeglądu i zobaczcie, kto od nas odszedł. A gdy dokonali przeglądu, okazało się, że nie było Jonatana i jego giermka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 18, 'Saul powiedział do Achiasza: Przynieś arkę Boga, gdyż arka Boga była w tym czasie u synów Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 19, 'Kiedy Saul jeszcze mówił do kapłana, zamieszanie w obozie filistyńskim trwało i coraz bardziej się wzmagało. Saul powiedział więc do kapłana: Cofnij rękę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 20, 'Potem Saul i cały lud, który z nim był, zebrali się i przyszli na miejsce bitwy, a miecz każdego był zwrócony przeciwko drugiemu i porażka była bardzo wielka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 21, 'A Hebrajczycy, którzy byli przedtem z Filistynami i którzy zewsząd z nimi wyruszyli do obozu, również przeszli na stronę Izraelitów, którzy byli z Saulem i Jonatanem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 22, 'Wszyscy też Izraelici, którzy ukryli się na górze Efraim, gdy usłyszeli, że Filistyni uciekają, wyruszyli za nimi w pościg w tej bitwie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 23, 'I Pan wybawił Izraela w tym dniu, bitwa zaś przeniosła się aż do Bet-Awen.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 24, 'A Izraelici byli strudzeni w tym dniu. Saul bowiem zaprzysiągł lud, mówiąc: Przeklęty człowiek, który jadłby jakikolwiek posiłek przed wieczorem, dopóki nie zemszczę się na swoich wrogach. Dlatego nikt z ludu nie skosztował żadnego posiłku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 25, 'Wtedy cały lud tej ziemi przyszedł do lasu, gdzie był miód na ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 26, 'A gdy lud wszedł do lasu, ujrzał spływający miód. Nikt jednak nie podniósł ręki do ust, bo lud bał się tej przysięgi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 27, 'Lecz Jonatan nie słyszał, jak jego ojciec zaprzysięgał lud. Ściągnął więc koniec laski, którą miał w ręku, namoczył go w plastrze miodu i podniósł rękę do ust, a jego oczy rozbłysły.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 28, 'Wtedy ktoś z ludu odezwał się: Twój ojciec zaprzysiągł lud, mówiąc: Przeklęty człowiek, który jadłby dzisiaj posiłek. A lud był wyczerpany.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 29, 'Jonatan odpowiedział: Mój ojciec sprowadza nieszczęście na ziemię. Patrzcie, proszę, jak rozbłysły moje oczy, dlatego że skosztowałem trochę tego miodu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 30, 'Co dopiero, gdyby lud najadł się dziś z łupu swoich wrogów, który zdobył! Czy klęska wśród Filistynów nie byłaby większa?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 31, 'W tym dniu pobili Filistynów od Mikmas aż do Ajjalon, a lud był bardzo wyczerpany.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 32, 'Wtedy lud rzucił się na łup, brał owce, woły i cielęta i zarzynał je na ziemi, i jadł je razem z krwią.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 33, 'I doniesiono o tym Saulowi: Oto lud grzeszy przeciw Panu, jedząc razem z krwią. A on powiedział: Zgrzeszyliście. Przytoczcie do mnie teraz wielki kamień.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 34, 'Potem Saul powiedział: Rozproszcie się między ludem i powiedzcie mu: Niech każdy przyprowadzi do mnie swego wołu i swoją owcę, zabijajcie je tu i jedzcie, a nie grzeszcie przeciwko Panu, jedząc razem z krwią. Każdy więc z ludu przyprowadził tej nocy własnoręcznie swego wołu i tam go zabijał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 35, 'Saul zbudował też ołtarz dla Pana. Był to pierwszy ołtarz, który zbudował dla Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 36, 'Następnie Saul powiedział: Puśćmy się w pogoń za Filistynami nocą, łupmy ich aż do świtu, a nie zostawmy ani jednego z nich. Odpowiedzieli mu: Czyń wszystko, co ci się wydaje słuszne. Kapłan zaś powiedział: Przystąpmy tu do Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 37, 'Saul zapytał więc Boga: Czy mam puścić się w pogoń za Filistynami? Czy wydasz ich w ręce Izraela? Lecz nie odpowiedział mu tego dnia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 38, 'Wtedy Saul powiedział: Zbliżcie się wszyscy przywódcy ludu, zbadajcie i zobaczcie, na czym polega ten dzisiejszy grzech.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 39, 'Bo jak żyje Pan, który wybawia Izraela, choćby to był grzech mego syna Jonatana, poniesie śmierć. I nikt z całego ludu mu nie odpowiedział.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 40, 'Potem rzekł do całego Izraela: Wy będziecie po jednej stronie, a ja i mój syn Jonatan będziemy po drugiej stronie. I lud odpowiedział Saulowi: Czyń, co uważasz za słuszne.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 41, 'Saul powiedział więc do Pana, Boga Izraela: Okaż prawdę. I los padł na Jonatana i Saula, a lud z tego uszedł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 42, 'Potem Saul powiedział: Rzućcie los między mną a moim synem Jonatanem. I los padł na Jonatana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 43, 'Wtedy Saul powiedział do Jonatana: Powiedz mi, co uczyniłeś? Jonatan odpowiedział mu: Skosztowałem tylko trochę miodu końcem laski, którą miałem w ręku. Oto mam umrzeć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 44, 'Saul odpowiedział: Niech mi to Bóg uczyni, a do tego dorzuci. Musisz umrzeć, Jonatanie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 45, 'Lud jednak powiedział do Saula: Czy ma umrzeć Jonatan, który uczynił to wielkie wybawienie w Izraelu? Nie daj Boże! Jak żyje Pan, ani jeden włos z jego głowy nie spadnie na ziemię, gdyż z pomocą Bożą uczynił to dzisiaj. I tak lud wybawił Jonatana, i nie umarł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 46, 'Wtedy Saul zaniechał pościgu za Filistynami, Filistyni zaś powrócili do swego miejsca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 47, 'A Saul objął królestwo nad Izraelem i walczył ze wszystkimi swymi wrogami dokoła: z Moabem, synami Ammona, Edomem, królami Soby i Filistynami. I gdziekolwiek się zwrócił, zwyciężał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 48, 'Zebrał również wojsko, pobił Amalekitów i wyrwał Izraela z rąk tych, którzy go pustoszyli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 49, 'Synami Saula byli: Jonatan, Jiszwi i Malkiszua. Imiona jego dwóch córek: imię pierworodnej – Merab, a młodszej – Mikal;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 50, 'Żona Saula miała na imię Achinoam, była córką Achimaasa. Wódz jego wojska miał na imię Abner, był synem Nera, stryja Saula.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 51, 'Kisz był ojcem Saula, a Ner, ojciec Abnera, był synem Abiela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 52, 'Przez całe życie Saula trwała zacięta wojna z Filistynami. A gdy Saul zobaczył jakiegoś silnego i dzielnego mężczyznę, zabierał go do siebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 1, 'Potem Samuel powiedział do Saula: Pan zesłał mnie, abym cię namaścił na króla nad jego ludem, nad Izraelem. Teraz więc posłuchaj głosu słów Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 2, 'Tak mówi Pan zastępów: Wspomniałem na to, co Amalek uczynił Izraelowi, jak się na niego zasadził na drodze, gdy wychodził z Egiptu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 3, 'Teraz idź, pobij Amaleka i zniszcz wszystko, co ma. Nie lituj się nad nimi, lecz zabijaj i mężczyzn, i kobiety, dzieci i niemowlęta, woły i owce, wielbłądy i osły.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 4, 'Saul zebrał więc lud i policzył go w Telaim: było dwieście tysięcy pieszych i dziesięć tysięcy mężczyzn z Judy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 5, 'Potem Saul przybył do miasta Amaleka i urządził zasadzkę w dolinie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 6, 'I Saul powiedział do Kenitów: Idźcie, odstąpcie od Amalekitów i wyjdźcie spośród nich, abym was nie wytracił wraz z nimi. Okazaliście bowiem życzliwość wszystkim synom Izraela, gdy wychodzili z Egiptu. I tak Kenici odstąpili od Amalekitów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 7, 'Wtedy Saul pobił Amalekitów od Chawila aż do wejścia do Szur, leżącego naprzeciw Egiptu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 8, 'Pochwycił żywcem Agaga, króla Amalekitów, a cały lud zgładził ostrzem miecza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 9, 'Lecz Saul i lud oszczędzili Agaga i to, co najlepsze z owiec, wołów, tłustych zwierząt, baranów, oraz wszystko, co było dobre i nie chcieli tego zniszczyć. Zniszczyli zaś wszystko, co było nikczemne i nędzne.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 10, 'Wtedy doszło do Samuela słowo Pana:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 11, 'Żałuję, że ustanowiłem Saula królem. Odwrócił się bowiem ode mnie i nie wypełnił mego słowa. I Samuel bardzo się rozgniewał, i wołał do Pana przez całą noc.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 12, 'A gdy Samuel wstał wcześnie rano, by spotkać się z Saulem, doniesiono Samuelowi: Saul przybył do Karmelu i tam właśnie postawił sobie pomnik, po czym zawrócił, poszedł i przybył do Gilgal.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 13, 'A gdy Samuel przyszedł do Saula, Saul mu powiedział: Błogosławiony jesteś przez Pana. Wypełniłem słowo Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 14, 'Lecz Samuel powiedział: A co to za beczenie owiec w moich uszach i co to za ryk wołów, który słyszę?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 15, 'Saul odpowiedział: Przyprowadzili je od Amalekitów. Lud bowiem oszczędził to, co najlepsze z owiec i wołów, aby je ofiarować Panu, twemu Bogu. To zaś, co pozostało, wytępiliśmy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 16, 'Wtedy Samuel powiedział do Saula: Stój, a powiem ci, co Pan mówił do mnie tej nocy. Odpowiedział mu: Powiedz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 17, 'Samuel rzekł: Czyż to nie wtedy, gdy byłeś mały w swoich oczach, stałeś się głową pokoleń Izraela i Pan namaścił cię na króla nad Izraelem?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 18, 'Potem Pan posłał cię w drogę i powiedział: Idź, wytrać tych grzeszników, Amalekitów, i walcz z nimi, aż ich wytępisz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 19, 'Dlaczego więc nie posłuchałeś głosu Pana, lecz rzuciłeś się na łup i uczyniłeś to zło w oczach Pana?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 20, 'Wtedy Saul odpowiedział Samuelowi: Przecież posłuchałem głosu Pana. Poszedłem drogą, którą mnie posłał Pan, i przyprowadziłem Agaga, króla Amalekitów, a Amalekitów wytraciłem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 21, 'Lud natomiast wziął z łupu owce i woły, najlepsze z tego, co miało być zniszczone, aby je ofiarować Panu, twemu Bogu, w Gilgal.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 22, 'Samuel odpowiedział: Czy Pan ma takie samo upodobanie w całopaleniach i ofiarach jak w posłuszeństwie głosowi Pana? Oto posłuszeństwo jest lepsze niż ofiara, lepiej jest słuchać, niż ofiarowywać tłuszcz baranów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 23, 'Bunt bowiem jest jak grzech czarów, a upór jest jak nieprawość i bałwochwalstwo. Ponieważ odrzuciłeś słowo Pana, on także odrzucił cię jako króla.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 24, 'Wtedy Saul powiedział do Samuela: Zgrzeszyłem, ponieważ przekroczyłem rozkaz Pana i twoje słowa, gdyż bałem się ludu i posłuchałem jego głosu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 25, 'Teraz jednak przebacz mi, proszę, mój grzech i zawróć ze mną, abym oddał pokłon Panu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 26, 'Lecz Samuel odpowiedział Saulowi: Nie zawrócę z tobą, ponieważ odrzuciłeś słowo Pana, a Pan odrzucił ciebie, abyś nie był już królem nad Izraelem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 27, 'A gdy Samuel odwrócił się, aby odejść, Saul chwycił skraj jego płaszcza i ten rozdarł się.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 28, 'Wtedy Samuel powiedział mu: Pan oddarł ci dziś królestwo Izraela i dał je twemu bliźniemu, lepszemu od ciebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 29, 'Ponadto Mocarz Izraela nie kłamie i nie będzie żałować, gdyż nie jest człowiekiem, aby miał żałować.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 30, 'A on odpowiedział: Zgrzeszyłem. Teraz jednak uszanuj mnie, proszę, wobec starszych mego ludu i wobec Izraela i zawróć ze mną, abym oddał pokłon Panu, twemu Bogu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 31, 'Zawrócił więc Samuel i szedł za Saulem, a Saul oddał pokłon Panu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 32, 'Potem Samuel rzekł: Przyprowadźcie do mnie Agaga, króla Amalekitów. Agag podszedł do niego odważnie i powiedział: Na pewno ustąpiła gorycz śmierci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 33, 'Lecz Samuel powiedział: Jak twój miecz pozbawiał kobiety ich dzieci, tak wśród kobiet twoja matka będzie pozbawiona dzieci. I Samuel posiekał Agaga na kawałki przed Panem w Gilgal.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 34, 'Potem Samuel udał się do Rama, a Saul poszedł do swego domu w Gibea Saulowym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 35, 'I Samuel nie zobaczył już Saula aż do dnia swojej śmierci. Bolał jednak Samuel nad Saulem, a Pan żałował, że uczynił Saula królem nad Izraelem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 1, 'Wtedy Pan powiedział do Samuela: Jak długo będziesz bolał nad Saulem, skoro odrzuciłem go, aby nie królował nad Izraelem? Napełnij swój róg oliwą i idź, posyłam cię do Jessego Betlejemity. Tam bowiem upatrzyłem sobie króla wśród jego synów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 2, 'Samuel powiedział: Jak mam pójść? Saul bowiem o tym usłyszy i zabije mnie. Pan odpowiedział: Weź ze sobą jałowicę ze stada i powiedz: Przyszedłem, aby złożyć Panu ofiarę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 3, 'I wezwij Jessego na ofiarę, a ja ci oznajmię, co masz czynić. A namaścisz mi tego, którego ci wskażę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 4, 'Samuel uczynił więc tak, jak mu powiedział Pan, i przybył do Betlejem. Wtedy starsi miasta z drżeniem wyszli mu naprzeciw i zapytali: Czy przychodzisz w pokoju?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 5, 'Odpowiedział: W pokoju. Przyszedłem, aby złożyć Panu ofiarę. Poświęćcie się i przyjdźcie ze mną na składanie ofiary. Poświęcił też Jessego i jego synów i zaprosił ich na składanie ofiary.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 6, 'A gdy przyszli, ujrzał Eliaba i powiedział: Na pewno stoi przed Panem jego pomazaniec.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 7, 'Lecz Pan powiedział do Samuela: Nie patrz na jego urodę ani na jego wysoki wzrost, gdyż go odrzuciłem. Pan bowiem nie patrzy na to, na co patrzy człowiek, bo człowiek patrzy na to, co jest przed oczami, ale Pan patrzy na serce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 8, 'Jesse zawołał wtedy Abinadaba i kazał mu przejść przed Samuelem. A on powiedział: Tego też Pan nie wybrał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 9, 'Potem Jesse kazał przejść Szammie. A on powiedział: Tego też Pan nie wybrał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 10, 'W ten sposób Jesse kazał przejść siedmiu swoim synom przed Samuelem. I Samuel powiedział do Jessego: Pan nie wybrał tych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 11, 'Potem Samuel zapytał Jessego: Czy to już wszyscy twoi synowie? Odpowiedział: Został jeszcze najmłodszy, który pasie owce. Wtedy Samuel powiedział do Jessego: Poślij po niego i przyprowadź go, gdyż nie usiądziemy, dopóki on tu nie przyjdzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 12, 'Posłał więc po niego i przyprowadził go. Był on rudy i miał piękne oczy oraz ładny wygląd. I Pan powiedział: Wstań, namaść go, bo to jest on.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 13, 'Samuel wziął więc róg z oliwą i namaścił go pośród jego braci. I od tego dnia Duch Pana zstępował na Dawida. Samuel zaś wstał i poszedł do Rama.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 14, 'Lecz Duch Pana opuścił Saula i zaczął go trapić zły duch od Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 15, 'Wtedy słudzy Saula powiedzieli do niego: Oto teraz trapi cię zły duch od Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 16, 'Niech nasz pan rozkaże swoim sługom, którzy są przed tobą, by poszukali człowieka, który umie grać na harfie. A gdy będzie na tobie ten zły duch od Boga, człowiek ten zagra swą ręką i ulży ci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 17, 'Saul odpowiedział swoim sługom: Proszę, upatrzcie mi człowieka, który umiałby dobrze grać, i przyprowadźcie go do mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 18, 'Jeden ze sług odpowiedział: Oto widziałem syna Jessego Betlejemity, który umie grać. Jest to dzielny wojownik, człowiek waleczny, roztropny i przystojny, a Pan jest z nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 19, 'Saul wysłał więc posłańców do Jessego i powiedział: Poślij do mnie swego syna Dawida, który jest przy trzodzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 20, 'Wtedy Jesse wziął osła, chleb, bukłak wina oraz jedno koźlę i posłał to wszystko Saulowi przez swego syna Dawida.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 21, 'I Dawid przybył do Saula, i stanął przed nim. Ten ukochał go bardzo i Dawid został jego giermkiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 22, 'Potem Saul posłał do Jessego, mówiąc: Proszę, niech Dawid stoi przede mną, bo znalazł łaskę w moich oczach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 23, 'A gdy zły duch od Boga zstępował na Saula, Dawid brał harfę i grał swą ręką melodię. Wtedy Saul doznawał ulgi i czuł się lepiej, a zły duch odchodził od niego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 1, 'Wtedy Filistyni zebrali swoje wojska do walki i zgromadzili się w Soko, które należy do Judy, rozbili obóz między Soko a Azeką, w Efes-Dammim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 2, 'Saul zaś i Izraelici zebrali się i rozbili obóz w dolinie Ela, i ustawili się w szyku bojowym przeciw Filistynom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 3, 'Filistyni stali na górze po jednej stronie, Izraelici zaś stali na górze po drugiej stronie, a między nimi była dolina.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 4, 'Wtedy z obozu Filistynów wyszedł pewien wojownik z Gat imieniem Goliat, wysoki na sześć łokci i jedną piędź.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 5, 'Na głowie miał spiżowy hełm i był ubrany w łuskowy pancerz; waga pancerza wynosiła pięć tysięcy syklów miedzi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 6, 'Miał również spiżowe nagolenice na nogach i spiżową tarczę między ramionami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 7, 'Drzewce jego włóczni były jak wał tkacki, grot jego włóczni ważył sześćset syklów żelaza, a przed nim szedł człowiek niosący jego tarczę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 8, 'Stanął on i zawołał do wojsk Izraela: Po co ustawiacie się w szyku bojowym? Czy ja nie jestem Filistynem, a wy sługami Saula? Wybierzcie spośród siebie człowieka i niech zejdzie do mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 9, 'Jeśli zdoła ze mną walczyć i zabije mnie, będziemy waszymi niewolnikami. Lecz jeśli ja go pokonam i go zabiję, wy będziecie naszymi niewolnikami i będziecie nam służyć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 10, 'Filistyn dodał: Rzucam dziś wyzwanie wojskom Izraela. Dajcie mi człowieka, a będziemy ze sobą walczyć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 11, 'Gdy Saul i cały Izrael usłyszeli słowa Filistyna, zlękli się i bardzo zatrwożyli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 12, 'Dawid był synem tego Efratejczyka z Betlejem judzkiego, imieniem Jesse, który miał ośmiu synów. Za czasów Saula był on stary i podeszły w latach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 13, 'Trzej starsi synowie Jessego wyruszyli i udali się za Saulem na wojnę. Imiona jego trzech synów, którzy poszli na wojnę, to: Eliab, pierworodny, drugi po nim – Abinadab i trzeci – Szamma.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 14, 'A Dawid był najmłodszy, a trzej najstarsi poszli za Saulem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 15, 'Dawid zaś odchodził od Saula i wracał, aby paść trzodę swego ojca w Betlejem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 16, 'A Filistyn występował rano i wieczorem i stawał tak przez czterdzieści dni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 17, 'I Jesse powiedział do swego syna Dawida: Weź teraz dla swych braci tę efę prażonego ziarna i tych dziesięć chlebów i biegnij do obozu, do swoich braci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 18, 'Zanieś też tych dziesięć serów dowódcy oddziału, dowiedz się, jak się mają twoi bracia, i weź ich zastaw.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 19, 'A Saul wraz z nimi i wszystkimi synami Izraela byli w dolinie Ela, walcząc z Filistynami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 20, 'Wstał więc Dawid wcześnie rano, powierzył trzodę stróżowi, zabrał to wszystko i wyruszył, tak jak mu Jesse nakazał. Gdy przybył do obozu, wojsko wyruszało do bitwy i wydało okrzyk wojenny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 21, 'Izraelici i Filistyni ustawili się już bowiem w szyku bojowym, szyk przeciwko szykowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 22, 'Wtedy Dawid zostawił toboły pod opieką stróża taboru i pobiegł na pole bitwy. Gdy przybył, przywitał się ze swoimi braćmi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 23, 'Gdy z nimi rozmawiał, oto wojownik imieniem Goliat, Filistyn z Gat, wystąpił z szeregów filistyńskich i zaczął wypowiadać te same słowa. I Dawid to usłyszał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 24, 'A wszyscy Izraelici na widok tego człowieka uciekali przed nim i bardzo się bali.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 25, 'I Izraelici mówili: Czy widzicie tego człowieka, który występuje? Występuje, by rzucać wyzwanie Izraelowi. Lecz tego, kto go zabije, król wzbogaci wielkim bogactwem i da mu swoją córkę, a dom jego ojca uczyni wolnym w Izraelu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 26, 'Wtedy Dawid zapytał ludzi stojących przy nim: Co dadzą temu, kto zabije tego Filistyna i odejmie hańbę z Izraela? Bo kim jest ten nieobrzezany Filistyn, że rzuca wyzwanie wojskom Boga żywego?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 27, 'I lud odpowiedział mu te same słowa: To dadzą temu, kto go zabije.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 28, 'A jego starszy brat, Eliab, usłyszał, że rozmawia z tymi ludźmi. I Eliab zapłonął gniewem na Dawida, i powiedział: Po co tu przyszedłeś i komu zostawiłeś tych parę owiec na pustyni? Znam twoją pychę i przewrotność twego serca, bo przyszedłeś, aby przypatrywać się bitwie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 29, 'Wtedy Dawid powiedział: Cóż teraz uczyniłem? Czy nie mam tu sprawy?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 30, 'I odwrócił się od niego do kogoś innego, i pytał się jak przedtem. A lud odpowiedział mu tak jak poprzednio.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 31, 'I usłyszano słowa, które wypowiedział Dawid, i powtórzono je Saulowi. Saul wezwał go więc do siebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 32, 'Wtedy Dawid powiedział do Saula: Niech niczyje serce nie upada z jego powodu. Twój sługa pójdzie i będzie walczył z tym Filistynem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 33, 'Lecz Saul odpowiedział Dawidowi: Ty nie możesz iść przeciwko temu Filistynowi, by z nim walczyć. Jesteś bowiem chłopcem, a on jest wojownikiem od swojej młodości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 34, 'Dawid odpowiedział Saulowi: Twój sługa pasł trzodę swego ojca, a gdy przychodził lew lub niedźwiedź i porywał barana z trzody;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 35, 'Wtedy goniłem go, uderzałem na niego i wyrywałem mu go z paszczy. I kiedy rzucał się na mnie, chwytałem go za gardło, biłem i zabijałem go.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 36, 'Twój sługa zabił i lwa, i niedźwiedzia. Ten nieobrzezany Filistyn będzie jak jeden z nich, gdyż rzucił wyzwanie wojskom Boga żywego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 37, 'Ponadto Dawid powiedział: Pan, który wyrwał mnie z łapy lwa i niedźwiedzia, wyrwie mnie również z rąk tego Filistyna. Wtedy Saul powiedział do Dawida: Idź i niech Pan będzie z tobą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 38, 'I Saul ubrał Dawida w swoją zbroję, włożył mu na głowę spiżowy hełm i ubrał go w pancerz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 39, 'Dawid przypasał też jego miecz do swojej zbroi i próbował chodzić, bo nigdy wcześniej tego nie nosił. Wtedy Dawid powiedział do Saula: Nie mogę w tym chodzić, bo nie przywykłem do tego. I Dawid zdjął to z siebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 40, 'Potem wziął do ręki swój kij i wybrał sobie pięć gładkich kamieni z potoku, i włożył je do torby pasterskiej, którą miał przy sobie, i z procą w ręku przybliżył się do Filistyna.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 41, 'Filistyn również ruszył i zbliżał się do Dawida, a jego giermek szedł przed nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 42, 'A gdy Filistyn spojrzał i zobaczył Dawida, wzgardził nim, dlatego że był młodzieńcem – rudym i przystojnym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 43, 'I Filistyn powiedział do Dawida: Czyż jestem psem, że przychodzisz do mnie z kijem? I przeklinał Filistyn Dawida przez swoich bogów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 44, 'Filistyn powiedział jeszcze do Dawida: Chodź do mnie, a dam twoje ciało ptakom powietrznym i zwierzętom polnym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 45, 'Wtedy Dawid odpowiedział Filistynowi: Ty przychodzisz do mnie z mieczem, włócznią i tarczą, a ja przychodzę do ciebie w imię Pana zastępów, Boga wojsk Izraela, któremu rzuciłeś wyzwanie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 46, 'Dziś Pan wyda cię w moje ręce, a ja cię zabiję i odetnę ci głowę, a dam dzisiaj trupy wojsk Filistynów ptakom powietrznym i dzikim zwierzętom. I cała ziemia pozna, że jest Bóg w Izraelu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 47, 'I całe to zgromadzenie pozna, że nie mieczem ani włócznią wybawia Pan, gdyż walka należy do Pana i on wyda was w nasze ręce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 48, 'A gdy Filistyn wstał, ruszył i zbliżał się do Dawida, Dawid również pośpiesznie pobiegł na pole walki naprzeciw Filistyna.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 49, 'I Dawid sięgnął ręką do torby, wyjął z niej kamień, cisnął go z procy i ugodził Filistyna w czoło tak, że kamień utkwił mu w czole. I ten upadł twarzą na ziemię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 50, 'Tak Dawid zwyciężył Filistyna procą i kamieniem. Uderzył Filistyna i zabił go, choć Dawid nie miał w ręku miecza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 51, 'Dawid podbiegł, stanął nad Filistynem, wziął jego miecz, dobył go z pochwy, zabił go i odciął mu nim głowę. A kiedy Filistyni zobaczyli, że ich bohater umarł, uciekli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 52, 'Wtedy powstali Izraelici i Judejczycy, wydali okrzyk i ścigali Filistynów aż do wejścia do doliny i aż do bram Ekronu. I ranni Filistyni padali na drodze od Szaaraim aż do Gat i Ekronu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 53, 'Potem synowie Izraela wrócili z pościgu za Filistynami i złupili ich obóz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 54, 'A Dawid wziął głowę tego Filistyna i przyniósł ją do Jerozolimy, a jego zbroję włożył do swego namiotu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 55, 'Gdy Saul zobaczył, że Dawid wyrusza naprzeciw Filistyna, zapytał Abnera, dowódcę wojska: Czyim synem jest ten młodzieniec, Abnerze? Abner odpowiedział: Jak żyje twoja dusza, królu, nie wiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 56, 'Wtedy król powiedział: Dowiedz się, czyim synem jest ten młodzieniec.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 57, 'Kiedy Dawid wracał po zabiciu Filistynów, Abner wziął go i przyprowadził przed Saula, a głowa Filistyna była jeszcze w jego ręku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 58, 'I Saul zapytał go: Czyim synem jesteś, młodzieńcze? Dawid odpowiedział: Jestem synem twego sługi Jessego Betlejemity.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 1, 'Kiedy przestał rozmawiać z Saulem, dusza Jonatana związała się z duszą Dawida i Jonatan umiłował go jak własną duszę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 2, 'I Saul wziął go tego dnia, i nie pozwolił mu wrócić do domu swego ojca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 3, 'A Jonatan zawarł z Dawidem przymierze, bo miłował go jak własną duszę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 4, 'Jonatan zdjął płaszcz, który miał na sobie, dał go Dawidowi, podobnie jak swoje szaty – aż do miecza, łuku i pasa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 5, 'I Dawid wyruszał, dokądkolwiek Saul go posyłał, i postępował roztropnie. Saul ustanowił go więc nad wojownikami, a on zyskał przychylność w oczach całego ludu, a także w oczach sług Saula.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 6, 'A gdy wracali, a Dawid też wracał po zabiciu Filistyna, kobiety ze wszystkich miast Izraela wyszły na spotkanie królowi Saulowi ze śpiewem, pląsami i radością – z bębnami i gęślami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 7, 'Kobiety śpiewały na przemian, grały i mówiły: Saul pobił swoje tysiące, ale Dawid swoich dziesiątki tysięcy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 8, 'I Saul bardzo się rozgniewał, gdyż nie podobały mu się te słowa. Powiedział: Przyznali Dawidowi dziesiątki tysięcy, a mnie przyznali tylko tysiące. Czego mu brak? Tylko królestwa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 9, 'Od tego dnia Saul nieprzychylnie patrzył na Dawida.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 10, 'Następnego dnia zły duch od Boga zstąpił na Saula i on prorokował pośrodku domu, a Dawid grał swą ręką melodię – jak przedtem. Saul zaś trzymał w ręku włócznię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 11, 'I Saul rzucił włócznię, bo myślał: Przybiję Dawida do ściany. Lecz Dawid dwukrotnie się przed nim uchylił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 12, 'I Saul zaczął bać się Dawida, ponieważ Pan był z nim, a od Saula odstąpił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 13, 'Saul oddalił go więc od siebie i uczynił go dowódcą nad tysiącem, a on wyruszał i powracał przed ludem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 14, 'We wszystkich swoich drogach Dawid postępował roztropnie, gdyż Pan był z nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 15, 'Gdy Saul widział, że tak bardzo roztropnie postępuje, bał się go.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 16, 'Lecz cały Izrael i Juda kochali Dawida, bo on wyruszał i powracał przed nimi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 17, 'I Saul powiedział do Dawida: Oto moja najstarsza córka Merab. Dam ci ją za żonę, tylko bądź dla mnie dzielnym mężem i prowadź wojny Pana. Saul bowiem mówił sobie tak: Niech moja ręka go nie dosięgnie, ale niech go dosięgnie ręka Filistynów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 18, 'Wtedy Dawid powiedział do Saula: Kim jestem i czym jest moje życie lub rodzina mojego ojca w Izraelu, żebym miał zostać zięciem króla?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 19, 'Gdy jednak przyszedł czas oddania Dawidowi córki Saula, Merab, oddano ją za żonę Adrielowi z Mecholi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 20, 'Ale Mikal, córka Saula, pokochała Dawida. Gdy więc doniesiono o tym Saulowi, spodobało mu się to.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 21, 'I Saul powiedział: Dam mu ją, aby była dla niego sidłem i aby ręka Filistynów była na nim. Powiedział więc Saul do Dawida: Zostaniesz dzisiaj moim zięciem z moją drugą córką.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 22, 'Wtedy Saul nakazał swoim sługom: Powiedzcie do Dawida w tajemnicy: Oto król ma w tobie upodobanie i wszyscy jego słudzy kochają cię. Zostań więc teraz zięciem króla.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 23, 'Słudzy Saula powtórzyli te słowa do uszu Dawida, a Dawid odpowiedział: Czy wam się wydaje, że to błaha rzecz być zięciem króla? Jestem przecież człowiekiem ubogim i mało znaczącym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 24, 'Wtedy słudzy Saula oznajmili mu: Tak powiedział Dawid.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 25, 'Saul odpowiedział: Tak powiedzcie Dawidowi: Król nie chce innego wiana jak tylko sto napletków filistyńskich, aby się pomścić na swoich wrogach. Saul planował bowiem, że Dawid wpadnie w ręce Filistynów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 26, 'Gdy jego słudzy powtórzyli te słowa Dawidowi, spodobało się to Dawidowi, że ma zostać zięciem króla. A te dni jeszcze się nie wypełniły.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 27, 'Wstał więc Dawid i poszedł, on i jego ludzie, i zabił spośród Filistynów dwustu mężczyzn. Potem Dawid przyniósł ich napletki i oddał je w pełnej liczbie królowi, aby zostać zięciem króla. I Saul dał mu swą córkę Mikal za żonę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 28, 'A gdy Saul zobaczył i przekonał się, że Pan jest z Dawidem i że jego córka Mikal go kocha;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 29, 'Tym bardziej Saul obawiał się Dawida. I Saul stał się wrogiem Dawida na zawsze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 30, 'A książęta Filistynów robili wypady. A przy każdym ich wypadzie Dawid postępował roztropniej niż wszyscy słudzy Saula, tak że jego imię stało się bardzo sławne.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 1, 'Wtedy Saul mówił do swego syna Jonatana i do wszystkich swoich sług, aby zabili Dawida.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 2, 'Lecz Jonatan, syn Saula, bardzo miłował Dawida. I Jonatan doniósł Dawidowi, mówiąc: Mój ojciec Saul chce cię zabić. Teraz więc strzeż się do rana i siedź w ukryciu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 3, 'A ja wyjdę i stanę przy swoim ojcu na polu, tam gdzie ty będziesz. Będę rozmawiał o tobie ze swoim ojcem, a cokolwiek zobaczę, powiadomię cię o tym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 4, 'Jonatan mówił więc dobrze o Dawidzie ze swym ojcem Saulem i powiedział mu: Niech król nie grzeszy przeciwko swemu słudze Dawidowi, gdyż on nie zgrzeszył przeciw tobie, a jego czyny są raczej dla ciebie bardzo pożyteczne:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 5, 'On przecież narażał swoje życie i zabił Filistyna, i Pan dokonał wielkiego wybawienia dla całego Izraela. Sam to widziałeś i uradowałeś się. Dlaczego więc miałbyś grzeszyć przeciw niewinnej krwi i bez powodu zabić Dawida?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 6, 'I Saul posłuchał słów Jonatana, i przysiągł: Jak żyje Pan, nie zostanie zabity.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 7, 'Jonatan zawołał więc Dawida i powtórzył mu wszystkie te słowa. Potem Jonatan przyprowadził Dawida do Saula i przebywał z nim, tak jak poprzednio.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 8, 'Gdy znowu wybuchła wojna, Dawid wyruszył przeciw Filistynom i walczył z nimi, i zadał im wielką klęskę tak, że uciekli przed nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 9, 'A zły duch od Pana opanował Saula, kiedy siedział w swym domu, trzymając włócznię w ręku, Dawid zaś grał swą ręką melodię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 10, 'I Saul chciał przybić Dawida włócznią do ściany, lecz ten wymknął się Saulowi i włócznia utkwiła w ścianie, a Dawid wybiegł i uciekł tej nocy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 11, 'Potem Saul wysłał posłańców do domu Dawida, aby go pilnowali i rano zabili. Lecz Mikal, jego żona, powiedziała o tym Dawidowi: Jeśli nie ujdziesz z życiem tej nocy, jutro zostaniesz zabity.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 12, 'Mikal spuściła więc Dawida przez okno, a on odszedł, uciekł i ocalał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 13, 'A Mikal wzięła bożka i położyła na łożu, a poduszkę z koziej sierści umieściła pod jego głową i przykryła szatą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 14, 'Gdy Saul wysłał posłańców, aby porwali Dawida, powiedziała: Jest chory.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 15, 'Saul znowu wysłał posłańców, aby zobaczyli Dawida, nakazując: Przynieście go do mnie na łożu, abym go zabił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 16, 'A gdy posłańcy przyszli, oto na łożu był bożek, a poduszka z koziej skóry była pod jego głową.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 17, 'I Saul powiedział do Mikal: Dlaczego mnie tak oszukałaś i wypuściłaś mego wroga, aby uszedł? Mikal odpowiedziała Saulowi: On mi powiedział: Puść mnie, dlaczego miałbym cię zabić?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 18, 'Dawid uciekł więc i ocalał, następnie przybył do Samuela, do Rama, i opowiedział mu wszystko, co Saul mu uczynił. Potem wraz z Samuelem poszli do Najot i tam zamieszkali.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 19, 'I doniesiono Saulowi: Oto Dawid jest w Najot, w Rama.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 20, 'Wtedy Saul wysłał posłańców, aby pojmali Dawida. Gdy zobaczyli gromadę prorokujących proroków oraz Samuela stojącego na ich czele, Duch Boży zstąpił na posłańców i oni także zaczęli prorokować.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 21, 'Kiedy doniesiono o tym Saulowi, wysłał innych posłańców, lecz i oni prorokowali. Saul wysłał i trzecich posłańców, lecz także i ci prorokowali.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 22, 'Potem on sam poszedł do Rama i gdy przyszedł do wielkiej studni, która jest w Seku, zapytał: Gdzie jest Samuel i Dawid? Odpowiedziano mu: Oto są w Najot, w Rama.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 23, 'I szedł stamtąd do Najot w Rama, lecz na niego też zstąpił Duch Boży, tak że idąc, prorokował, aż przyszedł do Najot w Rama.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 24, 'I zdjął z siebie szaty i także prorokował przed Samuelem, leżąc nagi przez cały dzień i całą noc. Stąd powiedzenie: Czyż i Saul między prorokami?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 1, 'Tymczasem Dawid uciekł z Najot w Rama, przyszedł do Jonatana i mówił przed nim: Cóż uczyniłem? Jaka jest moja nieprawość? Jaki jest mój grzech wobec twego ojca, że czyha na moje życie?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 2, 'Odpowiedział mu: Nie daj Boże! Nie umrzesz. Oto mój ojciec nie czyni niczego wielkiego ani małego, zanim mnie o tym nie powiadomi. Czyż mój ojciec miałby to przede mną ukrywać? Nie uczyni tego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 3, 'Lecz Dawid przysiągł: Na pewno twój ojciec wie, że znalazłem łaskę w twoich oczach i myśli: Niech o tym nie wie Jonatan, żeby się nie martwił. Zaprawdę jednak, jak żyje Pan i jak żyje twoja dusza, tylko jeden krok dzieli mnie od śmierci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 4, 'Jonatan odpowiedział Dawidowi: Czegokolwiek twoja dusza pragnie, uczynię to dla ciebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 5, 'Wtedy Dawid powiedział do Jonatana: Oto jutro jest nów księżyca, a ja zwykle zasiadam z królem przy stole. Pozwól mi odejść i ukryć się w polu aż do wieczora trzeciego dnia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 6, 'Jeśli twój ojciec będzie o mnie wypytywał, odpowiesz: Dawid bardzo mnie prosił, aby mógł pobiec do swego miasta, Betlejem, gdyż tam cała rodzina składa doroczną ofiarę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 7, 'Jeśli odpowie: Dobrze – będzie to oznaczać pokój dla twego sługi. Lecz jeśli się rozgniewa, wiedz, że postanowił coś złego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 8, 'Okaż więc miłosierdzie swemu słudze, gdyż doprowadziłeś swego sługę do przymierza Pana z tobą. Jeśli jednak jest we mnie jakaś nieprawość, to ty mnie zabij. Po co masz mnie prowadzić do swego ojca?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 9, 'Jonatan odpowiedział: Nie daj Boże! Gdybym rzeczywiście wiedział, że mój ojciec postanowił coś złego względem ciebie, czyżbym cię o tym nie powiadomił?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 10, 'I Dawid powiedział do Jonatana: Któż mnie powiadomi, jeśli twój ojciec da ci surową odpowiedź?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 11, 'Jonatan odpowiedział Dawidowi: Chodź, wyjdźmy na pole. I obaj wyszli na pole.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 12, 'Wtedy Jonatan powiedział do Dawida: Niech Pan, Bóg Izraela – gdy jutro o tej porze lub pojutrze wybadam swego ojca, i jeśli to będzie coś dobrego o Dawidzie, a nie poślę do ciebie ani nie powiadomię cię o tym;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 13, 'To niech Pan odpłaci Jonatanowi i do tego dorzuci. Lecz jeśli mój ojciec będzie chciał wyrządzić ci zło, to powiadomię cię o tym i odprawię cię, abyś mógł odejść w pokoju. A niech Pan będzie z tobą, jak był z moim ojcem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 14, 'I jeśli będę żył, okaż mi miłosierdzie Pana, ale choćbym i umarł;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 15, 'Nie odbieraj swego miłosierdzia memu domowi na wieki, nawet gdy Pan wytraci wszystkich wrogów Dawida z powierzchni ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 16, 'Jonatan zawarł więc przymierze z domem Dawida, mówiąc: Niech Pan szuka tego z ręki wrogów Dawida.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 17, 'Jonatan ponownie przysiągł Dawidowi, gdyż go miłował. Miłował go bowiem, jak miłował własną duszę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 18, 'Wtedy Jonatan powiedział do niego: Jutro jest nów. Zauważą, że ciebie nie ma, ponieważ twoje miejsce będzie puste.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 19, 'Po trzech dniach w ukryciu udasz się szybko na miejsce, gdzie ukrywałeś się, gdy omawialiśmy sprawę, i zatrzymasz się przy kamieniu Ezel.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 20, 'A ja wypuszczę trzy strzały obok niego, jak gdyby do celu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 21, 'A potem poślę chłopca, mówiąc mu: Idź, znajdź strzały. Jeśli powiem chłopcu: Oto strzały znajdują się za tobą, bliżej, przynieś je – wtedy przyjdź, gdyż będzie to oznaczać dla ciebie pokój i nie stanie ci się nic złego, jak żyje Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 22, 'Jeśli zaś powiem chłopcu: Oto strzały znajdują się przed tobą, tam dalej – to idź, bo Pan cię wypuścił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 23, 'A co do sprawy, o której rozmawialiśmy, Pan będzie świadkiem między mną a tobą na wieki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 24, 'Dawid ukrył się więc w polu. A gdy nastał nów, król zasiadł do stołu, aby się posilić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 25, 'A gdy król zasiadł na swoim miejscu jak zazwyczaj, na miejscu przy ścianie, Jonatan powstał. Abner siedział obok Saula, miejsce zaś Dawida było puste.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 26, 'Saul jednak nie powiedział nic tego dnia, bo myślał: Coś mu się przydarzyło i jest nieczysty, a nie oczyścił się.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 27, 'A gdy następnego dnia, drugiego po nowiu, miejsce Dawida pozostało puste, Saul zapytał swego syna Jonatana: Dlaczego syn Jessego nie przyszedł na posiłek ani wczoraj, ani dziś?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 28, 'Jonatan odpowiedział Saulowi: Dawid usilnie mnie prosił, aby mógł pójść do Betlejem;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 29, 'Mówił: Pozwól mi pójść, proszę, bo nasza rodzina składa ofiarę w mieście i mój brat wezwał mnie tam. Teraz więc, jeśli znalazłem łaskę w twoich oczach, pozwól mi iść i zobaczyć swoich braci. Dlatego nie przyszedł do stołu królewskiego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 30, 'Wtedy Saul zapłonął gniewem na Jonatana i powiedział mu: Synu przewrotnej i upornej kobiety, czyż nie wiem, że wybrałeś sobie syna Jessego na własną hańbę i na hańbę nagości swojej matki?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 31, 'Jak długo bowiem syn Jessego będzie żył na ziemi, nie ostoisz się ty ani twoje królestwo. Teraz więc poślij po niego i przyprowadź go do mnie, bo musi umrzeć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 32, 'Wtedy Jonatan odpowiedział swemu ojcu Saulowi: Dlaczego ma umrzeć? Cóż uczynił?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 33, 'I Saul rzucił w niego włócznię, aby go przebić. Przez to Jonatan wiedział, że jego ojciec postanowił zabić Dawida.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 34, 'Jonatan wstał więc od stołu w wielkim gniewie i nie jadł już posiłku w drugim dniu po nowiu. Martwił się bowiem o Dawida, bo jego ojciec tak go zelżył.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 35, 'Rankiem Jonatan wyszedł w pole o czasie umówionym z Dawidem, a był z nim mały chłopiec.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 36, 'I powiedział do swego chłopca: Biegnij i poszukaj strzał, które wypuszczę. Gdy chłopiec biegł, on wypuścił strzałę, by padła dalej, przed nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 37, 'A gdy chłopiec dotarł na miejsce, gdzie była strzała, którą Jonatan wypuścił, zawołał Jonatan za chłopcem i powiedział: Czyż strzała nie jest dalej od ciebie?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 38, 'I Jonatan wołał za chłopcem: Szybko, pośpiesz się, nie stój! Chłopiec Jonatana zebrał strzały i przyszedł do swego pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 39, 'Lecz chłopiec nic nie wiedział, tylko Jonatan i Dawid znali sprawę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 40, 'I Jonatan oddał swój oręż swemu chłopcu, i powiedział mu: Idź, odnieś to do miasta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 41, 'A gdy chłopiec odszedł, Dawid wstał z miejsca, od strony południowej, upadł twarzą na ziemię i ukłonił się trzy razy. Potem pocałowali się wzajemnie i razem płakali, a Dawid obficiej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 42, 'I Jonatan powiedział do Dawida: Idź w pokoju. Obaj bowiem poprzysięgliśmy sobie w imię Pana, mówiąc: Niech Pan będzie między mną a tobą i między moim potomstwem a twoim potomstwem na wieki. Wstał więc i odszedł, a Jonatan wszedł do miasta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 1, 'Potem Dawid przyszedł do Nob, do kapłana Achimeleka. Achimelek wyszedł przestraszony naprzeciw Dawida i zapytał go: Dlaczego jesteś sam i nie ma z tobą nikogo?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 2, 'Dawid odpowiedział kapłanowi Achimelekowi: Król zlecił mi pewną sprawę, nakazując: Niech nikt nie wie o tej sprawie, z którą cię wysyłam i którą ci zleciłem. Z tego powodu umówiłem się ze swoimi sługami w pewnym miejscu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 3, 'Teraz więc, co masz pod ręką? Daj mi do ręki pięć chlebów lub cokolwiek się znajdzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 4, 'Kapłan odpowiedział Dawidowi: Nie mam pod ręką zwykłego chleba, tylko chleb poświęcony. Dam ci go, ale pod warunkiem, że słudzy wstrzymali się od kobiet.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 5, 'Dawid odpowiedział kapłanowi: Na pewno kobiety były oddalone od nas przez trzy dni, odkąd wyruszyłem. Naczynia młodzieńców są więc święte. A chleb jest w pewien sposób zwykły, chociaż został dziś poświęcony w naczyniu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 6, 'Kapłan dał mu więc poświęcony chleb, gdyż nie było tam innego chleba oprócz chleba pokładnego, który zabrano sprzed oblicza Pana, aby w dniu jego usunięcia położyć świeży chleb.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 7, 'W tym dniu był tam pewien człowiek spośród sług Saula, zatrzymany przed Panem. Miał na imię Doeg, był to Edomita, przełożony nad pasterzami Saula.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 8, 'I Dawid zapytał Achimeleka: Czy nie masz tu pod ręką włóczni albo miecza? Bo nie wziąłem ze sobą ani swego miecza, ani żadnej swojej broni, gdyż sprawa króla była pilna.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 9, 'Kapłan odpowiedział: Miecz Goliata, Filistyna, którego zabiłeś w dolinie Ela, jest zawinięty w szatę za efodem. Jeśli chcesz go sobie wziąć, weź. Nie ma tu bowiem innego oprócz tego. Dawid odpowiedział: Nie ma od niego lepszego. Daj mi go.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 10, 'Dawid wstał więc i uciekł tego dnia przed Saulem, i przybył do Akisza, króla Gat.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 11, 'A słudzy Akisza mówili do niego: Czy to nie jest Dawid, król ziemi? Czy nie o nim śpiewano wśród pląsów: Saul pobił swoje tysiące, a Dawid swoich dziesiątki tysięcy?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 12, 'I Dawid wziął sobie te słowa do serca, i bardzo się bał Akisza, króla Gat.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 13, 'Zmienił więc przed nimi swoje zachowanie i udawał szalonego w ich rękach, bazgrał na wrotach bramy i pozwalał, aby ślina spływała mu po brodzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 14, 'Wtedy Akisz powiedział do swoich sług: Oto widzicie człowieka szalonego. Dlaczego przyprowadziliście go do mnie?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 15, 'Czy brakuje mi szaleńców, że przyprowadziliście tego, aby szalał przede mną? Czy on ma wejść do mego domu?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 1, 'Potem Dawid odszedł stamtąd i uciekł do jaskini Adullam. Kiedy jego bracia i cała rodzina jego ojca usłyszeli o tym, przyszli tam do niego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 2, 'I zebrali się wokół niego wszyscy, którzy byli uciśnieni, wszyscy, którzy byli zadłużeni, oraz wszyscy, którzy byli rozgoryczeni, a on stał się ich przywódcą. I było przy nim około czterystu mężczyzn.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 3, 'Stamtąd Dawid poszedł do Mispy w Moabie i powiedział do króla Moabu: Pozwól, proszę, by mój ojciec i moja matka przyszli i mieszkali z wami, aż się dowiem, co Bóg ze mną uczyni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 4, 'Przyprowadził ich więc przed króla Moabu i mieszkali u niego przez wszystkie dni, kiedy Dawid przebywał w warowni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 5, 'Potem prorok Gad powiedział do Dawida: Nie pozostawaj w warowni. Wyrusz i wróć do ziemi judzkiej. Dawid wyruszył więc i przybył do lasu Cheret.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 6, 'W czasie gdy Saul usłyszał, że pojawił się Dawid oraz ludzie, którzy z nim byli, Saul przebywał w Gibea pod drzewem w Rama, z włócznią w ręku, a wszyscy jego słudzy stali przy nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 7, 'Saul powiedział więc do swych sług, którzy stali przy nim: Słuchajcie, Beniaminici: Czy syn Jessego da wam wszystkim pola i winnice i czy wszystkich was ustanowi tysiącznikami i setnikami?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 8, 'Czy dlatego sprzysięgliście się wszyscy przeciwko mnie i nie ma nikogo, kto by mi wyjawił, że mój syn zawarł przymierze z synem Jessego, i nie ma nikogo wśród was, kto by mi współczuł i powiadomił mnie, że mój syn podburzył mego sługę przeciwko mnie, aby czyhał na mnie, jak to jest dzisiaj?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 9, 'Wtedy Doeg Edomita, przełożony sług Saula, odpowiedział: Widziałem syna Jessego, gdy przyszedł do Nob, do Achimeleka, syna Achituba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 10, 'Ten radził się Pana w jego sprawie i dał mu żywność, dał mu też miecz Goliata Filistyna.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 11, 'Wtedy król posłał, by wezwać kapłana Achimeleka, syna Achituba, i cały dom jego ojca, czyli kapłanów, którzy byli w Nob. I wszyscy oni przyszli do króla.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 12, 'Saul powiedział: Słuchaj teraz, synu Achituba. A ten odpowiedział: Oto jestem, mój panie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 13, 'Saul zapytał go: Dlaczego sprzysięgliście się przeciwko mnie, ty i syn Jessego, że dałeś mu chleb i miecz i radziłeś się Boga w jego sprawie, by powstał przeciwko mnie, czyhając na mnie, jak to jest dzisiaj?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 14, 'Achimelek odpowiedział królowi: I któż spośród wszystkich twoich sług jest tak wierny jak Dawid, zięć króla, który wyrusza na twój rozkaz i jest szanowany w twoim domu?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 15, 'Czyż dopiero dziś zacząłem radzić się Boga w jego sprawie? Dalekie to ode mnie! Niech król nie obciąża swego sługi ani całego domu mego ojca o nic takiego. Twój sługa bowiem nie miał o tym wszystkim najmniejszego pojęcia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 16, 'Król powiedział: Musisz umrzeć, Achimeleku, ty i cały dom twego ojca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 17, 'Potem król nakazał sługom, którzy stali przy nim: Odwróćcie się i zabijcie kapłanów Pana, gdyż ich ręka także jest z Dawidem, a chociaż wiedzieli, że on uciekł, nie powiadomili mnie. Lecz słudzy króla nie chcieli podnieść ręki na kapłanów Pana i rzucić się na nich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 18, 'Wtedy król powiedział do Doega: Odwróć się i rzuć na kapłanów. I Doeg Edomita odwrócił się i rzucił na kapłanów, i zabił w tym dniu osiemdziesięciu pięciu mężczyzn noszących lniany efod.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 19, 'Również Nob, miasto kapłanów, wybił ostrzem miecza: mężczyzn i kobiety, dzieci i niemowlęta, woły, osły i owce – wszystko to ostrzem miecza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 20, 'Uszedł tylko jeden syn Achimeleka, syna Achituba, imieniem Abiatar, uciekł on do Dawida.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 21, 'Abiatar zawiadomił Dawida, że Saul zabił kapłanów Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 22, 'I Dawid powiedział do Abiatara: Wiedziałem już tego dnia, gdy był tam Doeg Edomita, że z pewnością doniesie o tym Saulowi. To ja spowodowałem śmierć wszystkich osób domu twego ojca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 23, 'Zostań ze mną, nie bój się. Kto bowiem czyha na moje życie, czyha też na twoje życie. Lecz u mnie będziesz bezpieczny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 1, 'Wtedy doniesiono Dawidowi: Oto Filistyni zdobywają Keilę i plądrują klepiska.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 2, 'I Dawid radził się Pana: Czy mam iść i uderzyć na tych Filistynów? Pan odpowiedział Dawidowi: Idź i pobij Filistynów, i wybawisz Keilę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 3, 'Ludzie Dawida powiedzieli mu: Oto boimy się tu, w ziemi judzkiej, a cóż dopiero, jeśli pójdziemy do Keili przeciw wojskom Filistynów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 4, 'Dawid ponownie radził się Pana. A Pan odpowiedział mu: Wstań, idź do Keili, gdyż wydam Filistynów w twoje ręce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 5, 'Dawid wyruszył więc ze swoimi ludźmi do Keili, walczył z Filistynami, uprowadził ich stada i zadał im wielką klęskę. Tak Dawid wybawił mieszkańców Keili.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 6, 'A gdy Abiatar, syn Achimeleka, uciekł do Dawida do Keili, przyniósł w swej ręce efod.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 7, 'Potem doniesiono Saulowi, że Dawid przybył do Keili. I Saul powiedział: Bóg wydał go w moje ręce, gdyż sam się zamknął, wchodząc do miasta mającego bramy i rygle.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 8, 'Saul zwołał więc cały lud na wojnę, by wyruszyć do Keili i oblegać Dawida oraz jego ludzi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 9, 'A gdy Dawid dowiedział się, że Saul potajemnie knuje zło przeciw niemu, powiedział do kapłana Abiatara: Przynieś tu efod.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 10, 'I Dawid przemówił: Panie, Boże Izraela, twój sługa usłyszał dokładnie, że Saul chce przyjść do Keili, aby zburzyć miasto z mego powodu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 11, 'Czy starsi Keili wydadzą mnie w jego ręce? Czy przyjdzie też Saul, jak twój sługa usłyszał? Panie, Boże Izraela, proszę, powiedz twemu słudze. Pan odpowiedział: Przyjdzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 12, 'Wtedy Dawid zapytał: Czy starsi Keili wydadzą mnie i moich ludzi w ręce Saula? Pan odpowiedział: Wydadzą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 13, 'Dawid wstał więc wraz ze swoimi ludźmi, których było około sześciuset, wyszli z Keili i udali się, gdzie mogli. A gdy doniesiono Saulowi, że Dawid uciekł z Keili, zaniechał wyprawy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 14, 'Dawid zaś przebywał na pustyni w miejscach obronnych i pozostał na górze w pustyni Zif. A Saul szukał go przez wszystkie te dni, lecz Bóg nie wydał go w jego ręce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 15, 'A gdy Dawid zobaczył, że Saul wyruszył, aby czyhać na jego życie, został w lesie na pustyni Zif.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 16, 'Wtedy Jonatan, syn Saula, wstał i udał się do Dawida do lasu, i wzmocnił jego rękę w Bogu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 17, 'I powiedział do niego: Nie bój się, bo nie znajdzie cię ręka Saula, mego ojca. Ty będziesz królował nad Izraelem, ja zaś będę drugim po tobie. Wie o tym także Saul, mój ojciec.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 18, 'I obaj zawarli przymierze przed Panem, po czym Dawid pozostał w lesie, a Jonatan wrócił do domu swego ojca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 19, 'Wtedy mieszkańcy Zif przyszli do Saula do Gibea i powiedzieli: Czyż Dawid nie ukrywa się u nas w miejscach obronnych w lesie, na wzgórzu Chakila, które leży po prawej stronie Jeszimona?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 20, 'Teraz więc, królu, według pragnienia swojej duszy, by zejść, zejdź czym prędzej, a my postaramy się wydać go w ręce króla.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 21, 'Saul odpowiedział: Błogosławieni jesteście przez Pana, że zlitowaliście się nade mną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 22, 'Idźcie, proszę, i przygotujcie się pilnie; dowiedzcie się, kto go tam widział, i wypatrzcie miejsce, w którym przebywa. Mówiono bowiem, że postępuje bardzo przebiegle.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 23, 'Wypatrzcie więc wszystkie jego kryjówki, w których się ukrywa, i wywiadujcie się o nie. Potem wróćcie do mnie z pewną wiadomością, a pójdę z wami. Jeśli będzie w ziemi, wtedy będę go szukał wśród wszystkich tysięcy w Judzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 24, 'Wstali więc i poszli do Zif przed Saulem. Dawid zaś i jego ludzie byli na pustyni Maon, na równinie po południowej stronie Jeszimona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 25, 'Saul wraz z jego ludźmi również poszli, aby go szukać. Gdy doniesiono o tym Dawidowi, ten zstąpił do skały i mieszkał na pustyni Maon. Kiedy Saul o tym usłyszał, ścigał Dawida na pustyni Maon.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 26, 'I Saul szedł po jednej stronie góry, a Dawid i jego ludzie szli po drugiej stronie góry. I Dawid spieszył się, aby ujść przed Saulem, gdyż Saul i jego ludzie już otaczali Dawida i jego ludzi, aby ich pojmać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 27, 'Tymczasem posłaniec przybył do Saula, mówiąc: Pośpiesz się i chodź, bo Filistyni wtargnęli do ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 28, 'Saul zawrócił więc od pościgu za Dawidem i wyruszył przeciw Filistynom. Dlatego nazwano to miejsce Sela-Hammalekot.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 29, 'Dawid zaś wyruszył stamtąd i przebywał w miejscach obronnych w En-Gedi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 1, 'A gdy Saul wrócił z pościgu za Filistynami, doniesiono mu: Oto Dawid przebywa na pustyni En-Gedi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 2, 'Saul wziął więc trzy tysiące doborowych mężczyzn spośród całego Izraela i wyruszył na poszukiwanie Dawida i jego ludzi po skałach dzikich kóz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 3, 'I przybył do owczych zagród przy drodze, gdzie była jaskinia. Wszedł do niej Saul, by zakryć sobie nogi. Dawid zaś i jego ludzie siedzieli w głębi jaskini.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 4, 'Ludzie Dawida powiedzieli do niego: Oto dzień, o którym Pan ci powiedział: Oto wydam twego wroga w twoje ręce, abyś z nim uczynił to, co wyda ci się słuszne. Dawid wstał więc i po cichu odciął skraj płaszcza Saula.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 5, 'Potem jednak serce Dawida zadrżało z tego powodu, że odciął skraj płaszcza Saula.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 6, 'I zwrócił się do swoich ludzi: Nie daj Boże, żebym miał to uczynić memu panu, pomazańcowi Pana, bym miał wyciągnąć swoją rękę na niego, ponieważ jest pomazańcem Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 7, 'Tymi słowami Dawid powstrzymał swych ludzi i nie pozwolił im powstać przeciw Saulowi. Saul zaś wyszedł z jaskini i poszedł swoją drogą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 8, 'Potem Dawid również wstał, wyszedł z jaskini i zawołał za Saulem: Mój panie, królu! Kiedy Saul obejrzał się za siebie, Dawid schylił się twarzą ku ziemi i pokłonił się.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 9, 'Następnie Dawid powiedział do Saula: Dlaczego słuchasz opowieści ludzi, którzy mówią: Oto Dawid pragnie twojej zguby?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 10, 'Oto dziś twoje oczy widzą, że Pan wydał cię w jaskini w moje ręce. I namawiano mnie, bym cię zabił, lecz oszczędziłem cię i powiedziałem: Nie wyciągnę swojej ręki na mego pana, bo jest pomazańcem Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 11, 'Zobacz, mój ojcze, zobacz skraj swego płaszcza w mojej ręce. Odcinając ci bowiem skraj twego płaszcza, nie zabiłem cię. Wiedz i zobacz, że nie ma w mojej ręce złości ani nieprawości, ani też nie zgrzeszyłem przeciwko tobie. A ty czyhasz na moje życie, by mi je odebrać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 12, 'Niech Pan rozsądzi między mną a tobą i niech Pan za mnie zemści się na tobie. Lecz nie podniosę swojej ręki na ciebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 13, 'Jak mówi starodawne przysłowie: Od niegodziwych pochodzi niegodziwość, ale nie podniosę swojej ręki na ciebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 14, 'Za kim wyruszył król Izraela? Kogo gonisz? Zdechłego psa? Jedną pchłę?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 15, 'Niech Pan będzie sędzią i niech rozsądzi między mną a tobą, niech zobaczy i ujmie się w mojej sprawie, i niech mnie wyzwoli z twojej ręki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 16, 'I kiedy Dawid przestał mówić te słowa do Saula, Saul zawołał: Czy to jest twój głos, synu mój, Dawidzie? I Saul podniósł swój głos, i zapłakał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 17, 'Potem powiedział do Dawida: Jesteś sprawiedliwszy ode mnie, bo oddałeś mi dobrem, a ja tobie oddałem złem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 18, 'Dziś pokazałeś, że świadczysz mi dobro. Choć bowiem Pan wydał mnie w twoje ręce, nie zabiłeś mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 19, 'Gdy ktoś spotka swego wroga, to czy wypuści go na dobrą drogę? Niech Pan odpłaci ci dobrem za to, co mi dziś uczyniłeś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 20, 'A teraz oto wiem, że z pewnością będziesz królem i że królestwo Izraela ostoi się w twojej ręce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 21, 'Przysięgnij mi więc na Pana, że nie wytępisz mojego potomstwa po mnie i nie wytracisz mojego imienia z domu mego ojca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 22, 'I Dawid przysiągł Saulowi. Potem Saul wrócił do swego domu, a Dawid i jego ludzie udali się do miejsca obronnego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 1, 'Tymczasem Samuel umarł. I zebrali się wszyscy Izraelici, opłakiwali go i pogrzebali go w jego domu w Rama. Wtedy Dawid wstał i udał się na pustynię Paran.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 2, 'A był pewien człowiek w Maon, który miał posiadłość w Karmelu. Był to człowiek zamożny: miał bowiem trzy tysiące owiec i tysiąc kóz. Wtedy właśnie strzygł swoje owce w Karmelu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 3, 'Człowiek ten miał na imię Nabal, a jego żona nazywała się Abigail. Była to kobieta roztropna i piękna, ale jej mąż był nieokrzesany i występny, pochodził z rodu Kaleba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 4, 'Gdy Dawid dowiedział się na pustyni, że Nabal strzyże swoje owce;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 5, 'Posłał dziesięciu sług i powiedział im: Idźcie do Karmelu i udajcie się do Nabala, i pozdrówcie go w moim imieniu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 6, 'I tak powiecie do tego, który żyje spokojnie: Pokój niech będzie tobie, pokój twemu domowi i pokój wszystkiemu, co posiadasz!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 7, 'Właśnie słyszałem, że u ciebie strzygą owce. Gdy twoi pasterze przebywali z nami, nie wyrządziliśmy im żadnej krzywdy i nic im nie zginęło przez cały czas ich pobytu w Karmelu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 8, 'Zapytaj swoich sług, a powiedzą ci. Niech więc my, twoi słudzy, znajdziemy łaskę w twoich oczach, gdyż przybyliśmy w dobrym dniu. Daj, proszę, swoim sługom i twemu synowi Dawidowi cokolwiek znajdzie twoja ręka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 9, 'Przyszli więc słudzy Dawida i powtórzyli Nabalowi wszystkie te słowa w imieniu Dawida, i czekali.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 10, 'Nabal odpowiedział sługom Dawida: Któż to jest Dawid? Któż to jest syn Jessego? Wielu sług ucieka dziś od swoich panów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 11, 'Czyż mam wziąć swój chleb, swoją wodę i mięso swego bydła, które zabiłem dla strzygących moje owce, i dać ludziom, o których nie wiem, skąd są?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 12, 'Słudzy Dawida zawrócili i udali się w drogę, a gdy przybyli, powiedzieli mu wszystkie te słowa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 13, 'Wtedy Dawid powiedział swym ludziom: Niech każdy przypasze swój miecz. Każdy więc przypasał swój miecz, Dawid również przypasał swój miecz. I wyruszyło za Dawidem około czterystu ludzi, a dwustu zostało przy taborze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 14, 'Tymczasem jeden ze sług doniósł o tym Abigail, żonie Nabala: Oto Dawid przysłał posłańców z pustyni, aby błogosławić naszemu panu, lecz on ich zwymyślał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 15, 'Ale ludzie ci byli dla nas bardzo dobrzy i nie wyrządzili nam żadnej krzywdy ani nic nam nie zginęło przez cały czas, gdy przebywaliśmy z nimi w polu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 16, 'Byli dla nas murem zarówno w nocy, jak i w dzień, przez cały czas, kiedy byliśmy z nimi, pasąc trzodę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 17, 'Teraz zatem wiedz o tym i rozważ to, co masz czynić, gdyż postanowiono nieszczęście wobec naszego pana i całego jego domu. On bowiem jest synem Beliala, tak że nie można z nim rozmawiać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 18, 'Wtedy Abigail pośpieszyła się, wzięła dwieście chlebów, dwa bukłaki wina, pięć przyrządzonych owiec, pięć miar prażonego ziarna, sto pęczków rodzynków oraz dwieście placków figowych i załadowała to na osły.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 19, 'Potem powiedziała swoim sługom: Idźcie przede mną, a ja podążę za wami. Lecz swemu mężowi Nabalowi nie powiedziała o tym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 20, 'I gdy jechała na ośle, i zjeżdżała pod osłoną góry, oto Dawid i jego ludzie zjeżdżali naprzeciwko niej i spotkała ich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 21, 'Tymczasem Dawid powiedział: Naprawdę, niepotrzebnie strzegłem na pustyni wszystkiego, co należało do tego człowieka, tak że nic nie zginęło ze wszystkiego, co ma, bo on odpłaca mi złem za dobre.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 22, 'Niech to uczyni Bóg wrogom Dawida i niech do tego dorzuci, jeśli do rana pozostawię ze wszystkich, co do niego należą, aż do najmniejszego szczenięcia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 23, 'Kiedy Abigail zobaczyła Dawida, pośpiesznie zsiadła z osła i upadła przed Dawidem na twarz, i pokłoniła się aż do ziemi;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 24, 'Potem upadła mu do nóg i powiedziała: Niech na mnie spadnie nieprawość, mój panie. Pozwól, proszę, by twoja służąca przemówiła do ciebie i posłuchaj słów swojej służącej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 25, 'Niech mój pan, proszę, nie obraża się na tego syna Beliala, Nabala, gdyż jest on jak jego imię. Na imię ma Nabal i jest w nim głupota. Ja zaś, twoja służąca, nie widziałam sług mego pana, które przysłałeś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 26, 'Teraz więc, mój panie, jak żyje Pan i jak żyje twoja dusza, skoro Pan powstrzymał cię od rozlewu krwi i od dokonania zemsty twoją własną ręką, to niech teraz będą jak Nabal twoi wrogowie i ci, którzy pragną krzywdy mego pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 27, 'Teraz więc to błogosławieństwo, które twoja służąca przyniosła swemu panu, niech będzie oddane sługom, którzy chodzą za moim panem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 28, 'Przebacz, proszę, występek swojej służącej, gdyż Pan z pewnością uczyni memu panu trwały dom, ponieważ mój pan prowadzi walki Pana, a nie znaleziono zła w tobie przez wszystkie twoje dni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 29, 'Lecz pewien człowiek powstał, by cię prześladować i czyhać na twoje życie, ale dusza mego pana będzie zachowana w wiązance życia u Pana, twego Boga. Dusze zaś twych wrogów wyrzuci on jak z procy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 30, 'A gdy Pan uczyni memu panu wszystko dobre, co wypowiedział o tobie, i ustanowi cię władcą nad Izraelem;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 31, 'Wtedy nie będzie to dla ciebie strapieniem ani wyrzutem sumienia mego pana, że przelałeś niewinną krew bądź dokonałeś zemsty. Gdy więc Pan dobrze uczyni memu panu, wspomnij na swoją służącą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 32, 'I Dawid powiedział do Abigail: Błogosławiony niech będzie Pan, Bóg Izraela, który wysłał cię dziś na spotkanie ze mną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 33, 'Błogosławiony twój rozsądek, błogosławiona bądź i ty, która powstrzymałaś mnie dzisiaj od rozlewu krwi i od dokonania zemsty moją własną ręką.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 34, 'Zaprawdę bowiem, jak żyje Pan, Bóg Izraela, który powstrzymał mnie od wyrządzenia ci krzywdy, gdybyś się nie pośpieszyła i nie zajechała mi drogi, to Nabalowi nie pozostałby do świtu nikt, aż do najmniejszego szczenięcia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 35, 'Dawid przyjął więc z jej ręki to, co mu przyniosła, i powiedział do niej: Idź w pokoju do swego domu. Oto wysłuchałem twego głosu i przyjąłem cię łaskawie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 36, 'A gdy Abigail wróciła do Nabala, oto wyprawiał ucztę w swoim domu niczym ucztę królewską. A serce Nabala było w nim wesołe, gdyż był bardzo pijany, toteż nie powiedziała mu żadnego słowa aż do świtu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 37, 'Lecz rano, gdy Nabal wytrzeźwiał od wina, jego żona opowiedziała mu o wszystkim, a jego serce w nim zamarło i stał się on jak kamień.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 38, 'A gdy minęło mniej więcej dziesięć dni, Pan poraził Nabala, tak że umarł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 39, 'Gdy Dawid usłyszał, że Nabal umarł, powiedział: Błogosławiony Pan, który pomścił mnie na Nabalu za wyrządzoną mi zniewagę, swego sługę powstrzymał od zła, a niegodziwość Nabala zwrócił Pan na jego głowę. Potem Dawid posłał po Abigail i rozmówił się z nią, chcąc ją pojąć za żonę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 40, 'Słudzy Dawida przybyli więc do Abigail do Karmelu i powiedzieli do niej: Dawid przysłał nas do ciebie, by pojąć cię za żonę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 41, 'Ona wstała, pokłoniła się twarzą do ziemi i powiedziała: Oto niech twoja służąca będzie sługą do obmywania stóp sługom mego pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 42, 'Wtedy Abigail wstała pośpiesznie i wsiadła na osła z pięcioma swymi dziewczętami, które z nią chodziły. I tak pojechała za posłańcami Dawida, i została jego żoną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 43, 'Dawid wziął też Achinoam z Jizreel i obie zostały jego żonami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 44, 'Tymczasem Saul oddał swoją córkę Mikal, żonę Dawida, Paltiemu, synowi Lajisza z Gallim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 1, 'Zifejczycy przyszli do Saula, do Gibea, i powiedzieli: Czy Dawid nie ukrywa się na wzgórzu Hakila, naprzeciwko Jeszimonu?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 2, 'Saul wyruszył więc i udał się na pustynię Zif, a razem z nim trzy tysiące doborowych mężczyzn spośród Izraela, aby szukać Dawida na pustyni Zif.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 3, 'Saul rozbił obóz na wzgórzu Hakila, które leży naprzeciwko Jeszimonu, przy drodze. Dawid zaś przebywał na pustyni i dowiedział się, że Saul przybył za nim na pustynię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 4, 'Dawid wysłał więc zwiadowców i przekonał się, że Saul rzeczywiście przybył.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 5, 'Wtedy Dawid wstał i przybył na miejsce, gdzie Saul rozbił obóz. I Dawid spostrzegł miejsce, gdzie leżeli Saul i Abner, syn Nera, dowódca jego wojska. Saul bowiem spał w środku obozu, a ludzie leżeli wokół niego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 6, 'I Dawid odezwał się do Achimeleka Chetyty i do Abiszaja, syna Serui, brata Joaba: Kto pójdzie ze mną do Saula do obozu? Abiszaj odpowiedział: Ja pójdę z tobą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 7, 'Przyszli więc Dawid i Abiszaj w nocy do tych ludzi. I oto Saul, leżąc, spał w środku obozu, a jego włócznia była wbita w ziemię przy jego głowie. Abner zaś i ludzie leżeli dokoła niego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 8, 'Wtedy Abiszaj powiedział do Dawida: Dziś Bóg wydał twego wroga w twoje ręce. Pozwól mi więc teraz go przybić włócznią do ziemi jeden raz, drugiego nie będzie trzeba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 9, 'Ale Dawid odpowiedział Abiszajowi: Nie zabijaj go, bo któż może wyciągnąć rękę na pomazańca Pana i pozostać niewinny?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 10, 'Dawid dodał: Jak żyje Pan, sam Pan go zabije albo nadejdzie jego dzień i umrze, albo wyruszy na wojnę i zginie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 11, 'Nie daj Boże, abym miał wyciągnąć swoją rękę na pomazańca Pana. Tylko weź, proszę, włócznię, która jest przy jego głowie, oraz dzban na wodę i odejdźmy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 12, 'Dawid wziął więc włócznię i dzban na wodę, które leżały przy głowie Saula, i odeszli. Nikt tego nie widział ani nie zauważył, ani się nie obudził, bo wszyscy spali. Spadł na nich bowiem twardy sen od Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 13, 'Potem Dawid przeszedł na drugą stronę i stanął na szczycie góry daleko od obozu, tak że odległość między nimi była wielka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 14, 'Wtedy Dawid zawołał do ludzi i do Abnera, syna Nera: Czy nie odezwiesz się, Abnerze? Abner odpowiedział: Któż ty jesteś, który wołasz do króla?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 15, 'Dawid odpowiedział Abnerowi: Czy ty nie jesteś dzielnym mężczyzną? A któż w Izraelu jest jak ty? Dlaczego więc nie strzegłeś króla, swego pana? Przyszedł bowiem jeden z ludu, aby zabić króla, twego pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 16, 'Nie jest dobre to, co uczyniłeś. Jak żyje Pan, zasługujecie na śmierć, bo nie strzegliście swojego pana, pomazańca Pana. A teraz patrz, gdzie jest włócznia króla i dzban na wodę, które były przy jego głowie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 17, 'Wtedy Saul rozpoznał głos Dawida i zawołał: Czy to twój głos, mój synu, Dawidzie? Dawid odpowiedział: To mój głos, mój panie, królu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 18, 'I dodał: Dlaczego mój pan ściga swego sługę? Cóż bowiem uczyniłem? A jakież zło znajduje się w moich rękach?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 19, 'Teraz więc, proszę, niech mój pan, król, posłucha słów swego sługi. Jeśli Pan pobudził cię przeciwko mnie, niech przyjmie ofiary. Lecz jeśli synowie ludzcy, to niech będą przeklęci przed Panem, gdyż wypędzają mnie dziś, abym nie mieszkał w dziedzictwie Pana, mówiąc: Idź, służ obcym bogom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 20, 'A teraz niech moja krew nie zostanie wylana na ziemię przed obliczem Pana. Wyszedł bowiem król Izraela, aby szukać jednej pchły, jak wtedy, gdy poluje się na kuropatwę w górach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 21, 'Wtedy Saul powiedział: Zgrzeszyłem. Wróć, mój synu, Dawidzie, bo nie uczynię ci już nic złego, ponieważ dziś moja dusza była cenna w twoich oczach. Oto głupio postąpiłem i wielce zbłądziłem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 22, 'Dawid odpowiedział: Oto włócznia króla. Niech przyjdzie jeden ze sług i ją odbierze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 23, 'I niech Pan wynagrodzi każdemu za jego sprawiedliwość i wierność. Pan bowiem wydał cię dziś w moje ręce, ale nie chciałem wyciągnąć swojej ręki na pomazańca Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 24, 'Oto jak poważane było dziś twoje życie w moich oczach, tak niech będzie poważane moje życie w oczach Pana i niech mnie Pan wybawi z wszelkiego ucisku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 25, 'Wtedy Saul powiedział do Dawida: Bądź błogosławiony ty, mój synu, Dawidzie. Wielu dzieł dokonasz i będziesz zwyciężał. Potem Dawid poszedł swoją drogą, a Saul wrócił na swoje miejsce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 1, 'Dawid jednak powiedział sobie w sercu: Któregoś dnia zginę z ręki Saula. Nie ma dla mnie nic lepszego, niż bym uszedł szybko do ziemi Filistynów. Wtedy Saul będzie zrozpaczony szukaniem mnie po wszystkich granicach Izraela. I tak ujdę z jego rąk.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 2, 'Powstał więc Dawid i wraz z sześciuset ludźmi, którzy byli z nim, poszedł do Akisza, syna Maoka, króla Gat.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 3, 'I Dawid mieszkał u Akisza w Gat, on i jego ludzie, każdy ze swoją rodziną: Dawid i jego dwie żony, Achinoam Jizreelitka i Abigail, dawna żona Nabala, Karmelitka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 4, 'A gdy doniesiono Saulowi, że Dawid uciekł do Gat, przestał go szukać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 5, 'I Dawid powiedział do Akisza: Jeśli teraz znalazłem łaskę w twoich oczach, niech mi dadzą miejsce w jednym z miast tego kraju, abym tam mieszkał. Dlaczego bowiem twój sługa miałby mieszkać w mieście królewskim wraz z tobą?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 6, 'Akisz dał mu więc w tym dniu Siklag. Dlatego Siklag należy do królów Judy aż do dziś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 7, 'A okres, który Dawid przebywał w krainie Filistynów, wynosił rok i cztery miesiące.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 8, 'Dawid i jego ludzie wyprawiali się i najeżdżali Geszurytów, Girzytów i Amalekitów. Ci bowiem od dawna mieszkali w tej ziemi leżącej przy wejściu do Szur aż do ziemi Egiptu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 9, 'I Dawid pustoszył tę ziemię, i nie pozostawiał przy życiu ani mężczyzny, ani kobiety. Zabierał zaś owce, woły, osły i wielbłądy, a także szaty, zawracał i przybywał do Akisza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 10, 'A gdy Akisz pytał: Gdzie byliście dzisiaj na wyprawie? Dawid odpowiadał: Na południu Judy, na południe od Jerachmeelitów i na południe od Kenitów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 11, 'Dawid nie zostawiał przy życiu ani mężczyzny, ani kobiety, aby ich nie przyprowadzić do Gat. Mówił: Aby nie skarżyli na nas i nie mówili: Tak uczynił Dawid i taki był jego zwyczaj przez wszystkie dni, kiedy mieszkał w ziemi Filistynów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 12, 'Akisz zaś wierzył Dawidowi i mówił: Został znienawidzony przez swój lud, Izrael. Pozostanie więc moim sługą na zawsze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 1, 'W tym czasie Filistyni zgromadzili swe wojska na wojnę, aby walczyć z Izraelem. Wtedy Akisz powiedział do Dawida: Na pewno wiesz, że razem ze mną wyruszysz na wojnę, ty i twoi ludzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 2, 'Dawid odpowiedział Akiszowi: Sam się przekonasz, co uczyni twój sługa. Akisz powiedział do Dawida: Ustanowię więc ciebie stróżem swojej głowy na zawsze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 3, 'A Samuel już umarł i opłakiwał go cały Izrael, i pogrzebali go w jego mieście, Rama. Saul zaś usunął czarowników i wróżbitów z ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 4, 'Wtedy Filistyni zebrali się, nadciągnęli i rozbili obóz w Szunem. Saul również zgromadził cały Izrael i rozbił obóz w Gilboa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 5, 'A gdy Saul zobaczył obóz Filistynów, zląkł się i jego serce mocno zadrżało.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 6, 'I Saul radził się Pana, lecz Pan mu nie odpowiedział ani przez sny, ani przez Urim, ani przez proroków.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 7, 'Saul zwrócił się więc do swoich sług: Poszukajcie mi kobiety czarownicy, a pójdę do niej i poradzę się jej. Jego słudzy odpowiedzieli mu: Oto jest w Endor kobieta czarownica.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 8, 'Wtedy Saul przebrał się, wkładając inne szaty, poszedł wraz z dwoma mężczyznami i przyszli do tej kobiety w nocy. I powiedział: Proszę cię, powróż mi przez ducha wieszczego, a wywołaj mi tego, kogo ci wymienię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 9, 'Lecz kobieta odpowiedziała mu: Ty wiesz, co uczynił Saul – że zgładził czarowników i wróżbitów z ziemi. Czemu zastawiasz sidła na moje życie, by wydać mnie na śmierć?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 10, 'Saul przysiągł jej na Pana: Jak żyje Pan, nie spadnie na ciebie żadna kara z tego powodu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 11, 'Wtedy kobieta zapytała: Kogo mam ci wywołać? A on odpowiedział: Wywołaj mi Samuela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 12, 'A gdy kobieta zobaczyła Samuela, krzyknęła głośno i powiedziała do Saula: Czemu mnie oszukałeś? Przecież ty jesteś Saul!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 13, 'Król powiedział do niej: Nie bój się. Cóż widziałaś? Kobieta odpowiedziała Saulowi: Widziałam bogów wstępujących z ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 14, 'Pytał dalej: Jak wyglądał? Odpowiedziała: Wstępuje stary mężczyzna, a jest on ubrany w płaszcz. I Saul poznał, że to Samuel, schylił się twarzą do ziemi i pokłonił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 15, 'Samuel zaś powiedział do Saula: Dlaczego nie dajesz mi spokoju i wywołujesz mnie? Saul odpowiedział: Jestem w wielkim ucisku, gdyż Filistyni walczą ze mną, a Bóg odstąpił ode mnie i już nie odpowiada mi ani przez proroków, ani przez sny. Dlatego cię przyzwałem, abyś mi oznajmił, co mam czynić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 16, 'Samuel powiedział: Czemu więc mnie pytasz, skoro Pan odstąpił od ciebie i stał się twoim wrogiem?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 17, 'I Pan uczynił mu, jak zapowiedział przeze mnie: Pan wyrwał królestwo z twoich rąk i dał je twemu bliźniemu – Dawidowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 18, 'Ponieważ nie byłeś posłuszny głosowi Pana ani nie wykonałeś jego srogiego gniewu nad Amalekiem, Pan tak ci dzisiaj uczynił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 19, 'Ponadto Pan wyda Izraela wraz z tobą w ręce Filistynów, a jutro ty i twoi synowie będziecie ze mną. Pan wyda również wojsko Izraela w ręce Filistynów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 20, 'Saul natychmiast upadł jak długi na ziemię, bo bardzo się zląkł słów Samuela. Nie było w nim też siły, gdyż nic nie jadł przez cały dzień i całą noc.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 21, 'Potem kobieta podeszła do Saula, a widząc, że bardzo się zląkł, powiedziała mu: Oto twoja służąca posłuchała twego głosu, naraziłam swoje życie i posłuchałam twoich słów, które mówiłeś do mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 22, 'Teraz więc posłuchaj i ty, proszę, głosu swojej służącej. Położę przed tobą kawałek chleba, abyś zjadł i posilił się, zanim wyruszysz w drogę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 23, 'Lecz on wzbraniał się i mówił: Nie będę jadł. Jego słudzy zaś wraz z kobietą przymusili go. I posłuchał ich głosu, wstał z ziemi i usiadł na łóżku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 24, 'A ta kobieta miała w domu tuczne cielę. Pośpieszyła więc i zabiła je, potem wzięła mąkę, rozczyniła ją i upiekła z niej przaśniki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 25, 'Następnie przyniosła to przed Saula i przed jego sługi, a gdy zjedli, powstali i poszli tej samej nocy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 1, 'Wtedy Filistyni zebrali wszystkie swoje wojska w Afek. Izraelici zaś rozbili obóz przy źródle, które jest w Jizreel.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 2, 'A książęta filistyńscy ciągnęli setkami i tysiącami, a Dawid i jego ludzie ciągnęli na końcu z Akiszem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 3, 'Książęta filistyńscy zapytali: Po co tutaj ci Hebrajczycy? Akisz odpowiedział książętom filistyńskim: Czyż to nie jest Dawid, sługa Saula, króla Izraela, który był przy mnie przez te dni, nawet przez te lata, a nie znalazłem w nim żadnej winy od tego dnia, kiedy zbiegł do mnie, aż po dziś dzień?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 4, 'Lecz książęta filistyńscy rozgniewali się i powiedzieli mu: Odpraw tego człowieka i niech wróci do swego miejsca, które mu wyznaczyłeś. Niech nie idzie z nami do bitwy, aby w czasie walki nie stał się naszym przeciwnikiem. Czym bowiem mógłby odzyskać łaskę u swego pana jak nie głowami tych mężczyzn?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 5, 'Czyż to nie jest ten Dawid, o którym śpiewano wśród tańców: Pobił Saul swoje tysiące, lecz Dawid swoich dziesiątki tysięcy?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 6, 'Wtedy Akisz wezwał Dawida i powiedział mu: Jak żyje Pan, jesteś prawy, a twoje wychodzenie ze mną z obozu i wchodzenie do niego było dobre w moich oczach. Nie znalazłem bowiem w tobie nic złego od dnia, kiedy przybyłeś do mnie, aż do dziś. Nie podobasz się jednak książętom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 7, 'Teraz więc zawróć i idź w pokoju, byś nie czynił niczego, co byłoby złe w oczach książąt filistyńskich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 8, 'Dawid powiedział do Akisza: Cóż uczyniłem? Co znalazłeś u swego sługi od dnia, w którym byłem przy tobie, aż do dziś, że nie mogę wyruszyć do walki z wrogami swego pana, króla?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 9, 'Akisz odpowiedział Dawidowi: Wiem, że jesteś dobry w moich oczach, jak anioł Boga, ale książęta filistyńscy powiedzieli: Niech nie wyrusza z nami do bitwy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 10, 'Dlatego wstań wcześnie rano wraz ze sługami swego pana, którzy przyszli z tobą. Wstańcie skoro świt i odejdźcie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 11, 'Dawid wraz ze swoimi ludźmi wstał więc wcześnie rano, aby odejść i powrócić do ziemi Filistynów. Filistyni zaś nadciągnęli do Jizreel.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 1, 'A gdy trzeciego dnia Dawid i jego ludzie przybyli do Siklag, Amalekici najechali już na południe i na Siklag, zburzyli Siklag i spalili go ogniem;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 2, 'I zabrali do niewoli kobiety, które w nim były. Nikogo nie zabili, od najmniejszego aż do wielkiego, ale uprowadzili ich i odeszli swoją drogą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 3, 'A gdy Dawid i jego ludzie przyszli do miasta, było ono spalone ogniem, a ich żony, synów i córki zabrano do niewoli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 4, 'Wtedy Dawid i lud, który z nim był, podnieśli swój głos i płakali, aż im zabrakło sił do płaczu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 5, 'Zabrano do niewoli także obie żony Dawida: Achinoam Jizreelitkę i Abigail, dawną żonę Nabala z Karmelu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 6, 'I Dawid znalazł się w wielkim utrapieniu, bo lud chciał go ukamienować. Dusza całego ludu bowiem była rozgoryczona z powodu swoich synów i córek. Dawid zaś wzmocnił się w Panu, swym Bogu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 7, 'Wtedy Dawid powiedział do kapłana Abiatara, syna Achimeleka: Przynieś mi, proszę, efod. I Abiatar przyniósł efod Dawidowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 8, 'I Dawid radził się Pana, pytając: Czy mam ścigać to wojsko? Czy je dogonię? Pan odpowiedział mu: Ścigaj, bo na pewno dogonisz i na pewno odbierzesz łup.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 9, 'Dawid wyruszył więc, on i sześciuset ludzi, których miał ze sobą, i dotarli do potoku Besor. Tam niektórzy pozostali.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 10, 'Dawid zaś ścigał ich wraz z czterystu ludźmi. Dwustu ludzi bowiem pozostało, gdyż byli zbyt zmęczeni, żeby przejść przez potok Besor.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 11, 'A w polu natknęli się na Egipcjanina i przyprowadzili go do Dawida. Dali mu chleba i jadł, dali mu też wody i pił;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 12, 'Dali mu także kawałek placka figowego i dwa pęczki rodzynków. Kiedy to zjadł, ożył w nim jego duch, gdyż przez trzy dni i trzy noce nie jadł chleba ani nie pił wody.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 13, 'Wtedy Dawid zapytał go: Do kogo należysz? Skąd jesteś? Odpowiedział: Jestem młodym Egipcjaninem, sługą Amalekity. Mój pan porzucił mnie, bo zachorowałem trzy dni temu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 14, 'Najechaliśmy na południe od Keretytów, obszar Judy i na południe od Kaleba i podpaliliśmy Siklag ogniem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 15, 'Dawid zapytał go: Czy mógłbyś mnie zaprowadzić do tej zgrai? Odpowiedział: Przysięgnij mi na Boga, że mnie nie zabijesz ani mnie nie wydasz w ręce mego pana, a zaprowadzę cię do tej zgrai.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 16, 'I zaprowadził go, a oto byli rozproszeni po całej ziemi, jedli, pili i świętowali z powodu całego tego wielkiego łupu, który zabrali z ziemi Filistynów i z ziemi Judy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 17, 'I Dawid bił ich od zmierzchu aż do wieczora dnia następnego. Żaden z nich nie ocalał oprócz czterystu młodzieńców, którzy wsiedli na wielbłądy i uciekli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 18, 'Tak Dawid odzyskał wszystko, co zabrali Amalekici. Dawid uratował także swoje dwie żony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 19, 'Nie zabrakło im nikogo, od najmniejszego do największego, ani synów, ani córek, ani łupu, ani niczego, co im zabrali. Dawid odzyskał wszystko.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 20, 'Potem Dawid zabrał wszystkie trzody i stada, które pędzono przed jego dobytkiem, i mówiono: To jest łup Dawida.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 21, 'I Dawid przybył do tych dwustu ludzi, którzy byli tak zmęczeni, że nie mogli iść za Dawidem, i którym kazał zostać przy potoku Besor. Wyszli oni naprzeciw Dawida i naprzeciw ludzi, którzy z nim byli. A gdy Dawid zbliżył się do tych ludzi, pozdrowił ich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 22, 'Lecz wszyscy źli ludzie i synowie Beliala, którzy poszli z Dawidem, powiedzieli: Ponieważ ci nie poszli z nami, nie damy im nic z łupu, który odzyskaliśmy, oddamy tylko każdemu jego żonę i dzieci. Niech ich wezmą i odejdą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 23, 'Wtedy Dawid powiedział: Moi bracia, nie uczynicie tak z tym, co Pan nam dał. On nas strzegł i wydał w nasze ręce zgraję, która na nas napadła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 24, 'I któż was posłucha w tej sprawie? Bo jaki jest udział tego, który wyruszył na bitwę, taki też będzie udział tego, który został przy taborze; jednakowo się podzielą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 25, 'I tak zostało od tego dnia na przyszłość: ustalono to jako prawo i zwyczaj w Izraelu aż do dziś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 26, 'A gdy Dawid przybył do Siklag, posłał część łupu starszym Judy, swym przyjaciołom, ze słowami: Oto błogosławieństwo dla was z łupu wrogów Pana;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 27, 'Tym, którzy byli w Betel, i tym w Ramat na południu, i tym w Jattir;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 28, 'I tym w Aroerze, i tym w Sifmot, i tym w Esztemoa;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 29, 'I tym w Rachal, i tym w miastach Jerachmeelitów, i tym w miastach Kenitów;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 30, 'I tym w Chorma, i tym w Choraszan, i tym w Atach;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 31, 'I tym w Hebronie, i tym we wszystkich miejscach, gdzie pomieszkiwał Dawid wraz ze swymi ludźmi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 1, 'Tymczasem Filistyni walczyli z Izraelem, a Izraelici uciekli przed Filistynami i polegli na górze Gilboa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 2, 'Wtedy Filistyni ścigali Saula i jego synów i zabili Jonatana, Abinadaba i Malkiszuę, synów Saula.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 3, 'A gdy rozgorzała bitwa przeciwko Saulowi, łucznicy trafili na niego i został przez nich ciężko zraniony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 4, 'I Saul powiedział do swego giermka: Dobądź swój miecz i przebij mnie nim, aby nie przyszli ci nieobrzezani i nie przebili mnie, i nie znęcali się nade mną. Ale jego giermek nie chciał, ponieważ bardzo się bał. Saul wziął więc miecz i sam rzucił się na niego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 5, 'A gdy jego giermek zobaczył, że Saul umarł, rzucił się i on na swój miecz i umarł razem z nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 6, 'Tego dnia umarli więc razem Saul, jego trzej synowie, jego giermek oraz wszyscy jego ludzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 7, 'A gdy Izraelici, którzy mieszkali po tamtej stronie doliny i którzy mieszkali za Jordanem, zobaczyli, że Izraelici uciekali i że Saul i jego synowie umarli, opuścili miasta i uciekli. Przyszli więc Filistyni i mieszkali w nich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 8, 'Kiedy nazajutrz Filistyni przyszli, aby złupić zabitych, znaleźli Saula i jego trzech synów leżących na górze Gilboa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 9, 'Odcięli mu głowę, zdarli z niego zbroję i posłali po całej ziemi filistyńskiej, aby obwieścić o tym w świątyni swoich bożków i wśród ludu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 10, 'Jego zbroję położyli w świątyni Asztarty, a jego ciało przybili do muru Bet-Szean.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 11, 'Kiedy mieszkańcy Jabesz-Gilead usłyszeli o tym, co Filistyni uczynili Saulowi;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 12, 'Powstali wszyscy dzielni mężczyźni i szli przez całą noc, i zdjęli ciało Saula oraz ciała jego synów z muru Bet-Szean, po czym wrócili do Jabesz i tam je spalili.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 13, 'Wzięli potem ich kości i pogrzebali je pod drzewem w Jabesz. I pościli przez siedem dni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 1, 'Po śmierci Saula, gdy Dawid po rozgromieniu Amalekitów wrócił i zatrzymał się w Siklag przez dwa dni;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 2, 'Trzeciego dnia pewien człowiek przybył z obozu Saula z podartymi szatami i z prochem na głowie. Gdy przyszedł do Dawida, padł na ziemię i pokłonił mu się.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 3, 'Dawid zapytał go: Skąd przybywasz? Odpowiedział mu: Uciekłem z obozu Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 4, 'Dawid znowu zapytał: Co się stało? Proszę, powiedz mi. Odpowiedział: Lud uciekł z pola bitwy, a wielu ludzi padło i poległo, także Saul i jego syn Jonatan polegli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 5, 'Wtedy Dawid zapytał młodzieńca, który mu to powiedział: Skąd wiesz, że Saul i jego syn Jonatan umarli?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 6, 'Młodzieniec, który mu to oznajmił, odpowiedział: Przypadkiem znalazłem się na górze Gilboa, a oto Saul opierał się na swojej włóczni, a rydwany i jeźdźcy doganiali go.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 7, 'Kiedy obejrzał się i zobaczył mnie, zawołał na mnie. Odpowiedziałem: Oto jestem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 8, 'I zapytał mnie: Kim jesteś? Odpowiedziałem mu: Jestem Amalekitą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 9, 'Wtedy powiedział mi: Stań, proszę, nade mną i zabij mnie, bo ogarnęła mnie udręka, a moje życie jest jeszcze we mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 10, 'Stanąłem więc nad nim i zabiłem go, bo wiedziałem, że nie przeżyje po swoim upadku. Potem wziąłem koronę, która była na jego głowie, oraz naramiennik, który miał na ramieniu, i przyniosłem je tutaj do swojego pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 11, 'Wtedy Dawid chwycił swoje szaty i rozdarł je, tak uczynili również wszyscy ludzie, którzy z nim byli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 12, 'Lamentowali i płakali, i pościli aż do wieczora po Saulu i jego synu Jonatanie, po ludzie Pana i po domu Izraela, że padli od miecza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 13, 'I Dawid zapytał młodzieńca, który mu to powiedział: Skąd jesteś? Odpowiedział: Jestem synem przybysza, Amalekity.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 14, 'Dawid znowu zapytał go: Jakże nie bałeś się wyciągnąć swej ręki, aby zabić pomazańca Pana?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 15, 'Następnie Dawid zawołał jednego ze sług i rozkazał: Podejdź i zabij go. Ten uderzył go tak, że umarł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 16, 'Dawid powiedział do niego: Twoja krew na twoją głowę, bo twoje usta świadczyły przeciw tobie, gdy mówiły: Zabiłem pomazańca Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 17, 'Wtedy Dawid podniósł lament nad Saulem i jego synem Jonatanem;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 18, 'Polecił także, aby synów Judy uczono strzelać z łuku. Oto co napisane jest w księdze Jaszara:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 19, 'Piękno Izraela poległo na twoich wzgórzach. Jakże padli mocarze!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 20, 'Nie opowiadajcie o tym w Gat ani nie rozgłaszajcie tego po ulicach w Aszkelonie, aby się nie cieszyły córki Filistynów, by się nie radowały córki nieobrzezanych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 21, 'O góry Gilboa! Niech nie pada na was ani rosa, ani deszcz i niech tam nie będzie pól żyznych. Tam bowiem została skalana tarcza mocarzy, tarcza Saula, jakby nie była namaszczona oliwą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 22, 'Od krwi zabitych, od tłuszczu mocarzy nie cofał się łuk Jonatana, a miecz Saula nie wracał daremnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 23, 'Saul i Jonatan, ukochani i mili za życia, a w śmierci nie byli rozdzieleni, szybsi od orłów, silniejsi od lwów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 24, 'Córki Izraela, płaczcie nad Saulem, który was przyodziewał w piękny szkarłat i który włożył złote klejnoty na wasze szaty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 25, 'Jakże padli mocarze pośród bitwy! Jonatanie, na twych wzgórzach zostałeś zabity.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 26, 'Żal mi ciebie, mój bracie, Jonatanie. Byłeś mi bardzo miły. Twoja miłość była dla mnie cenniejsza niż miłość kobiety.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 27, 'Jakże padli mocarze i przepadły narzędzia wojny!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 1, 'Po tym wydarzeniu Dawid zapytał Pana: Czy mam iść do któregoś z miast Judy? Pan mu odpowiedział: Idź. I Dawid zapytał: Dokąd mam pójść? Odpowiedział: Do Hebronu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 2, 'Dawid wyruszył więc tam razem ze swoimi dwiema żonami: Achinoam Jizreelitką i Abigail, dawną żoną Nabala z Karmelu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 3, 'Dawid zabrał także ludzi, którzy z nim byli, każdego z jego rodziną. I zamieszkali w miastach Hebronu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 4, 'Wtedy przyszli mężczyźni Judy i namaścili tam Dawida na króla nad domem Judy. Wówczas też doniesiono Dawidowi, że to mieszkańcy Jabesz-Gilead pogrzebali Saula.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 5, 'Dawid wyprawił więc posłańców do mieszkańców Jabesz-Gilead z takim przesłaniem: Błogosławieni jesteście przez Pana, ponieważ okazaliście tę łaskę swemu panu Saulowi i pogrzebaliście go.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 6, 'Niech teraz Pan okaże wam łaskę i prawdę, a ja też odwdzięczę się wam za to dzieło dobroci, którego dokonaliście.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 7, 'Teraz więc niech wasze ręce się umocnią i bądźcie dzielni, bo choć umarł wasz pan Saul, to mnie dom Judy namaścił na króla nad sobą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 8, 'Lecz Abner, syn Nera, dowódca wojsk Saula, wziął Iszboszeta, syna Saula, i przyprowadził go do Machanaim;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 9, 'I ustanowił go królem nad Gileadem, Aszerem, Jizreelem, Efraimem, Beniaminem i całym Izraelem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 10, 'Iszboszet, syn Saula, miał czterdzieści lat, kiedy zaczął królować nad Izraelem, a panował dwa lata. Tylko dom Judy poszedł za Dawidem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 11, 'A okres, w którym Dawid był królem w Hebronie nad domem Judy, wynosił siedem lat i sześć miesięcy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 12, 'Potem Abner, syn Nera, i słudzy Iszboszeta, syna Saula, wyruszyli z Machanaim do Gibeonu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 13, 'Także Joab, syn Serui, wraz ze sługami Dawida wyruszyli i spotkali się przy stawie gibeońskim. Jedni zatrzymali się po jednej stronie stawu, a drudzy po drugiej stronie stawu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 14, 'Wtedy Abner zawołał do Joaba: Niech teraz wstaną młodzieńcy i niech się bawią przed nami. I Joab odpowiedział: Niech wstaną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 15, 'Wstali więc i wystąpiła liczba dwunastu Beniaminitów ze strony Iszboszeta, syna Saula, i dwunastu spośród sług Dawida.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 16, 'Każdy pochwycił swego przeciwnika za głowę i utopił swój miecz w jego boku, tak że padli razem. Dlatego miejsce to nazwano Helkatassurym, leży ono w Gibeonie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 17, 'W tym dniu rozgorzała bardzo zacięta walka. Abner i wojownicy Izraela zostali pokonani przez sługi Dawida.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 18, 'Byli tam również trzej synowie Serui: Joab, Abiszaj i Asahel. Asahel był szybkonogi jak dzika sarna.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 19, 'I Asahel ruszył w pogoń za Abnerem, i nie zbaczał ani w prawo, ani w lewo w tym pościgu za Abnerem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 20, 'A kiedy Abner obejrzał się za siebie, zapytał: Czy to ty jesteś, Asahelu? A on mu odpowiedział: To ja.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 21, 'Wtedy Abner powiedział mu: Skręć w prawo albo w lewo i schwytaj sobie jednego z młodzieńców, i zabierz sobie jego zbroję. Lecz Asahel nie chciał od niego odstąpić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 22, 'Abner ponownie więc powiedział do Asahela: Odstąp ode mnie. Czemu miałbym cię powalić na ziemię? Jakże mógłbym wtedy podnieść swoją twarz na Joaba, twego brata?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 23, 'Gdy jednak nie chciał odstąpić, Abner uderzył go końcem włóczni pod piąte żebro, tak że włócznia wyszła z drugiej strony. Padł tam i umarł na miejscu, a wszyscy, którzy przychodzili do tego miejsca, gdzie Asahel padł i umarł, przystawali.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 24, 'Lecz Joab i Abiszaj rzucili się w pogoń za Abnerem. I gdy zachodziło słońce, dotarli do wzgórza Amma, które leży naprzeciw Giach, przy drodze na pustynię Gibeon.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 25, 'Wtedy synowie Beniamina zebrali się wokół Abnera, utworzyli jeden oddział i stanęli na szczycie pewnego wzgórza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 26, 'I Abner zawołał do Joaba: Czy miecz będzie pożerał na zawsze? Czy nie wiesz, że koniec będzie gorzki? Kiedy wreszcie powiesz ludowi, aby zawrócił od ścigania swych braci?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 27, 'Joab odpowiedział: Jak żyje Bóg, gdybyś się nie odezwał, to dopiero rano lud odstąpiłby, każdy od ścigania swego brata.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 28, 'Joab zadął więc w trąbę i cały lud zatrzymał się, i nie ścigał dalej Izraela ani nie wznowiono walki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 29, 'A Abner i jego ludzie szli całą noc przez step, przeprawili się przez Jordan i przeszli przez cały Bitron, aż dotarli do Machanaim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 30, 'Joab zaś, gdy zawrócił z pościgu za Abnerem, zebrał cały lud, a ze sług Dawida zabrakło dziewiętnastu mężczyzn oraz Asahela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 31, 'Słudzy Dawida natomiast tak pobili ludzi z Beniamina i spośród Abnera, że zmarło trzystu sześćdziesięciu mężczyzn.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 32, 'Następnie zabrali Asahela i pogrzebali go w grobie jego ojca, w Betlejem. Potem Joab i jego ludzie szli całą noc i o świcie dotarli do Hebronu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 1, 'A wojna między domem Saula a domem Dawida trwała długo. Dawid jednak stawał się mocniejszy, a dom Saula stawał się coraz słabszy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 2, 'I Dawidowi w Hebronie urodzili się synowie. Jego pierworodnym był Amnon z Achinoam Jizreelitki;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 3, 'Drugim był Kilab z Abigail, dawnej żony Nabala z Karmelu, trzecim – Absalom, syn Maaki, córki Talmaja, króla Geszur;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 4, 'Czwartym był Adoniasz, syn Chaggity, piątym – Szefatiasz, syn Abitali;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 5, 'I szóstym był Jitream z Egli, żony Dawida. Ci urodzili się Dawidowi w Hebronie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 6, 'I dopóki trwała wojna między domem Saula a domem Dawida, Abner wzmacniał się w domu Saula.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 7, 'A Saul miał nałożnicę, której na imię było Rispa, córkę Aji. Iszboszet zapytał Abnera: Czemu wszedłeś do nałożnicy mego ojca?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 8, 'Wtedy Abner bardzo się rozgniewał z powodu słów Iszboszeta i powiedział: Czy jestem głową psa? Dziś okazałem przeciw Judzie miłosierdzie domowi Saula, twego ojca, jego braciom i przyjaciołom, i nie wydałem cię w ręce Dawida, a ty dziś obciążasz mnie winą z powodu tej kobiety.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 9, 'Niech Bóg to uczyni Abnerowi i do tego dorzuci, jeśli nie dokonam tego, co Pan przysiągł Dawidowi;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 10, 'Aby przenieść królestwo z domu Saula i umocnić tron Dawida nad Izraelem i nad Judą, od Dan aż do Beer-Szeby.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 11, 'I nie mógł odpowiedzieć Abnerowi ani słowa, bo się go bał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 12, 'Wtedy Abner wyprawił posłańców do Dawida, aby powiedzieli w jego imieniu: Czyja jest ziemia? I żeby mówili: Zawrzyj ze mną przymierze, a oto moja ręka będzie z tobą, by sprowadzić do ciebie cały Izrael.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 13, 'Odpowiedział: Dobrze, zawrę z tobą przymierze. Ale żądam od ciebie jednej rzeczy: Nie zobaczysz mojej twarzy, dopóki nie przyprowadzisz do mnie Mikal, córki Saula, gdy przyjdziesz mnie zobaczyć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 14, 'I Dawid wyprawił posłańców do Iszboszeta, syna Saula, żądając: Oddaj mi moją żonę Mikal, którą poślubiłem sobie za sto napletków filistyńskich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 15, 'Iszboszet posłał więc po nią i zabrał ją od męża, Paltiela, syna Lajisza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 16, 'Jej mąż szedł z nią i płakał, idąc za nią aż do Bachurim. Wtedy Abner powiedział do niego: Idź, wracaj. I wrócił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 17, 'Potem Abner prowadził rozmowy ze starszymi Izraela: Już dawno chcieliście, aby Dawid był królem nad wami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 18, 'Teraz więc uczyńcie to. Pan bowiem powiedział o Dawidzie tak: Przez rękę swojego sługi Dawida wybawię swój lud Izraela z ręki Filistynów i z ręki wszystkich jego wrogów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 19, 'Abner powiedział to samo do uszu Beniaminitów. Potem Abner poszedł, aby zawiadomić Dawida w Hebronie o wszystkim, co wydało się słuszne Izraelowi i całemu domowi Beniamina.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 20, 'A gdy Abner przybył wraz z dwudziestoma mężczyznami do Dawida do Hebronu, Dawid wyprawił ucztę dla Abnera i dla mężczyzn, którzy z nim byli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 21, 'Wtedy Abner powiedział do Dawida: Wstanę i pójdę, aby zgromadzić przy królu, moim panu, cały Izrael, żeby zawarli z tobą przymierze i żebyś królował nad wszystkim, czego pragnie twoja dusza. Potem Dawid odprawił Abnera, który poszedł w pokoju.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 22, 'A oto słudzy Dawida wraz z Joabem wracali z wyprawy, przynosząc ze sobą obfity łup. Abnera zaś już nie było u Dawida w Hebronie, gdyż go odprawił, i tamten odszedł w pokoju.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 23, 'Kiedy przybył Joab wraz z całym wojskiem, które z nim było, doniesiono Joabowi: Abner, syn Nera, przyszedł do króla, lecz on go odprawił, i tamten odszedł w pokoju.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 24, 'Joab przyszedł więc do króla i zapytał: Cóż uczyniłeś? Oto przyszedł do ciebie Abner. Dlaczego go odprawiłeś, aby mógł odejść?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 25, 'Znasz Abnera, syna Nera, wiesz, że przyszedł cię zdradzić i poznać twoje wyjścia i wejścia, i dowiedzieć się o wszystkim, co czynisz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 26, 'Wtedy Joab wyszedł od Dawida i wyprawił posłańców za Abnerem, którzy zawrócili go od studni Sira. Dawid zaś o tym nie wiedział.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 27, 'A gdy Abner wrócił do Hebronu, Joab odprowadził go na bok do bramy, aby z nim porozmawiać po cichu, i tam przebił go pod piątym żebrem, tak że umarł, za krew swego brata Asahela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 28, 'Kiedy Dawid usłyszał o tym później, powiedział: Ja i moje królestwo jesteśmy niewinni przed Panem na wieki za krew Abnera, syna Nera.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 29, 'Niech ona spadnie na głowę Joaba i na cały dom jego ojca i niech nie braknie w domu Joaba człowieka cierpiącego na wyciek ani trędowatego, ani chodzącego o lasce, ani upadającego od miecza, ani niemającego chleba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 30, 'Tak to Joab i jego brat Abiszaj zabili Abnera za to, że on zabił ich brata Asahela w bitwie pod Gibeonem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 31, 'Potem Dawid nakazał Joabowi i całemu ludowi, który z nim był: Porozdzierajcie wasze szaty, nałóżcie wory i opłakujcie Abnera. A król Dawid szedł za marami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 32, 'Gdy pogrzebali Abnera w Hebronie, król podniósł swój głos i zapłakał nad grobem Abnera, płakał też cały lud.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 33, 'Król lamentował z powodu Abnera i powiedział: Czyż tak miał umrzeć Abner, jak umiera nikczemnik?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 34, 'Twoje ręce nie były związane, a twoje nogi nie były skute w kajdany. Padłeś jak ten, który pada przed bezbożnymi. Wtedy cały lud jeszcze mocniej płakał nad nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 35, 'Gdy cały lud przyszedł, by skłonić Dawida do zjedzenia posiłku jeszcze za dnia, Dawid przysiągł: Niech mi Bóg to uczyni i do tego dorzuci, jeśli przed zachodem słońca skosztuję chleba lub czegoś innego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 36, 'Kiedy cały lud to zobaczył, uznał to za słuszne, podobnie jak wszystko, co czynił król.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 37, 'Tego dnia cały lud przekonał się, że nie od króla wyszło, żeby zabić Abnera, syna Nera.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 38, 'I król powiedział do swoich sług: Czyż nie wiecie, że dziś poległ w Izraelu wielki dowódca?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 39, 'A ja dziś jestem słaby, choć zostałem namaszczony na króla. Ci zaś ludzie, synowie Serui, są dla mnie zbyt uciążliwi. Niech Pan odpłaci czyniącemu zło według jego niegodziwości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 1, 'Gdy syn Saula Iszboszet usłyszał, że Abner poległ w Hebronie, opadły mu ręce i cały Izrael był przerażony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 2, 'Syn Saula miał też dwóch ludzi, dowódców oddziałów: jeden miał na imię Baana, a drugi – Rekab. Byli oni synami Rimmona Beerotczyka, z synów Beniamina. Beerot był bowiem także zaliczany do Beniamina;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 3, 'Bo Beerotczycy uciekli do Gittaim i byli tam przybyszami, i są nimi aż do dziś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 4, 'A Jonatan, syn Saula, miał jednego syna chromego na obie nogi. Gdy miał on bowiem pięć lat, a nadeszła wieść z Jizreel o śmierci Saula i Jonatana, jego piastunka pochwyciła go i uciekła. Ale w pośpiechu tej ucieczki upadł i został kaleką. Miał na imię Mefiboszet.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 5, 'Synowie Rimmona Beerotczyka, Rekab i Baana, wyruszyli więc i przyszli do domu Iszboszeta w najgorętszej porze dnia, w południe, gdy spał on w łożu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 6, 'Weszli oni do jego domu pod pretekstem zakupu pszenicy i tam przebili go pod piątym żebrem. Potem Rekab i jego brat Baana uciekli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 7, 'Gdy bowiem weszli do domu, on spał na swoim łożu w sypialni. Wtedy przebili go, uśmiercili i ucięli mu głowę. Potem zabrali ją i szli drogą pustynną przez całą noc.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 8, 'I przynieśli głowę Iszboszeta do Dawida do Hebronu, i powiedzieli do króla: Oto głowa Iszboszeta, syna Saula, twojego wroga, który czyhał na twoją duszę. Pan dzisiaj dokonał za mojego pana, króla, zemsty na Saulu i jego potomstwie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 9, 'Lecz Dawid odpowiedział Rekabowi i jego bratu Baanie, synom Rimmona Beerotczyka: Jak żyje Pan, który wybawił moją duszę z wszelkiego ucisku;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 10, 'Jeśli tego, który mi powiedział: Oto umarł Saul, sądząc, że przynosi dobrą nowinę, pojmałem i zabiłem w Siklag, chociaż myślał, że wynagrodzę go za jego wieści;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 11, 'Tym bardziej, gdy niegodziwi ludzie zabili sprawiedliwego człowieka w jego domu, na własnym łożu. Czy teraz nie powinienem zażądać jego krwi z waszych rąk i zgładzić was z ziemi?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 12, 'Dawid rozkazał więc sługom, a oni zabili ich, obcięli im ręce i nogi i powiesili ich nad stawem w Hebronie. Głowę zaś Iszboszeta wzięli i pochowali w grobie Abnera w Hebronie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 1, 'Wtedy wszystkie pokolenia Izraela zeszły się u Dawida w Hebronie i powiedziały: Oto jesteśmy twoją kością i twoim ciałem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 2, 'Już dawniej, gdy Saul był królem nad nami, ty wyprowadzałeś i przyprowadzałeś Izraela. I Pan powiedział do ciebie: Ty będziesz pasł mój lud Izraela i ty będziesz wodzem nad Izraelem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 3, 'Wszyscy starsi Izraela przyszli więc do króla do Hebronu i król Dawid zawarł z nimi przymierze w Hebronie przed Panem, a oni namaścili Dawida na króla nad Izraelem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 4, 'Dawid miał trzydzieści lat, gdy zaczął królować, a królował czterdzieści lat.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 5, 'W Hebronie królował nad Judą siedem lat i sześć miesięcy, w Jerozolimie zaś królował trzydzieści trzy lata nad całym Izraelem i Judą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 6, 'I król oraz jego ludzie poszli do Jerozolimy przeciw Jebusytom zamieszkującym w tej ziemi, a oni powiedzieli do Dawida: Nie wejdziesz tutaj, dopóki nie wyniesiesz ślepych i chromych. Myśleli bowiem: Dawid tu nie wejdzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 7, 'Dawid jednak zdobył twierdzę Syjon, to jest miasto Dawida.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 8, 'Dawid powiedział w tym dniu: Ktokolwiek pokona Jebusytów, wchodząc przez kanał, i zabije ślepych i chromych, których nienawidzi dusza Dawida, ustanowię go dowódcą. Dlatego mówiono: Ślepi i chromi nie wejdą do tego domu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 9, 'I tak zamieszkał Dawid w tej twierdzy, i nazwał ją miastem Dawida. Dawid obudował je też wokoło, od Millo i wnętrza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 10, 'I Dawid stale wzrastał w potędze, a Pan Bóg zastępów był z nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 11, 'Wtedy Hiram, król Tyru, wysłał posłańców do Dawida z drzewem cedrowym, cieślami i murarzami i zbudowali dom dla Dawida.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 12, 'I Dawid poznał, że Pan utwierdził go jako króla nad Izraelem i że wywyższył jego królestwo ze względu na swój lud Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 13, 'A po przybyciu z Hebronu Dawid wziął sobie jeszcze więcej nałożnic i żon z Jerozolimy. I urodziło się Dawidowi więcej synów i córek.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 14, 'Oto imiona tych, którzy mu się urodzili w Jerozolimie: Szammua, Szobab, Natan i Salomon;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 15, 'Jibchar, Eliszua, Nefeg i Jafia;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 16, 'Eliszama, Eliada i Elifelet.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 17, 'A gdy Filistyni usłyszeli, że Dawid został namaszczony na króla nad Izraelem, wszyscy Filistyni wyruszyli, aby szukać Dawida. Kiedy Dawid o tym usłyszał, zstąpił do twierdzy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 18, 'Wtedy Filistyni przybyli i rozciągnęli się w dolinie Refaim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 19, 'I Dawid radził się Pana: Czy mam ruszyć na Filistynów? Czy wydasz ich w moje ręce? Pan odpowiedział Dawidowi: Idź, gdyż z całą pewnością wydam Filistynów w twoje ręce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 20, 'Dawid przybył więc do Baal-Perasim i tam ich pobił, i powiedział: Pan rozerwał moich wrogów przede mną jak rwąca woda. Dlatego nazwał to miejsce Baal-Perasim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 21, 'I porzucili tam swoje bożki, a Dawid i jego ludzie spalili je.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 22, 'I Filistyni znowu nadciągnęli, i rozciągnęli się w dolinie Refaim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 23, 'Gdy Dawid radził się Pana, Pan odpowiedział: Nie ruszaj na nich, lecz obejdź ich z tyłu i uderz na nich od strony drzew morwowych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 24, 'A gdy usłyszysz odgłos kroków dochodzących od wierzchołków drzew morwowych, wtedy wyruszysz, gdyż wtedy Pan wyjdzie przed tobą, aby pokonać wojska Filistynów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 25, 'I Dawid uczynił tak, jak mu Pan rozkazał, i pobił Filistynów od Geba aż do wejścia do Gezer.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 1, 'I Dawid ponownie zebrał wszystkich doborowych mężczyzn z Izraela, trzydzieści tysięcy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 2, 'Potem Dawid wraz z całym ludem, który z nim był, powstał i wyruszył z Baali judzkiej, aby przenieść stamtąd arkę Boga, która nosi imię Pana zastępów zasiadającego między cherubinami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 3, 'I umieścili arkę Boga na nowym wozie, i wywieźli ją z domu Abinadaba położonego w Gibea. A Uzza i Achio, synowie Abinadaba, prowadzili ten nowy wóz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 4, 'I wyprowadzili go z domu Abinadaba położonego w Gibea wraz z arką Boga. A Achio szedł przed arką.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 5, 'Dawid zaś i cały Izrael grali przed Panem na wszelkich instrumentach z drewna jodłowego: na harfach, cytrach, bębnach, piszczałkach i cymbałach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 6, 'A gdy przybyli do klepiska Nachona, Uzza wyciągnął rękę do arki Boga i pochwycił ją, gdyż woły ją szarpnęły.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 7, 'I zapłonął gniew Pana przeciwko Uzzie, i Bóg zabił go za uchybienie. I umarł tam przy arce Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 8, 'I Dawid był wielce niezadowolony, że Pan tak srogo poraził Uzzę, i nazwał to miejsce Peres-Uzza, i tak jest do dziś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 9, 'Dawid zląkł się Pana tego dnia i powiedział: Jakże ma przyjść do mnie arka Pana?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 10, 'Dlatego Dawid nie chciał sprowadzić arki Pana do siebie, do swego miasta, lecz wprowadził ją do domu Obed-Edoma, Gittyty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 11, 'I arka Pana pozostała w domu Obed-Edoma, Gittyty, przez trzy miesiące. A Pan błogosławił Obed-Edomowi i całemu jego domowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 12, 'A doniesiono królowi Dawidowi: Pan błogosławi domowi Obed-Edoma i wszystkiemu, co posiada, ze względu na arkę Boga. Dawid poszedł więc i sprowadził z wielką radością arkę Boga z domu Obed-Edoma do miasta Dawida.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 13, 'A gdy ci, którzy nieśli arkę Pana, zrobili sześć kroków, składał w ofierze woły i tuczne zwierzęta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 14, 'I Dawid tańczył przed Panem z całych sił; był przepasany lnianym efodem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 15, 'Tak Dawid i cały dom Izraela sprowadzili arkę Pana z okrzykami i przy dźwiękach trąby.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 16, 'A gdy arka Pana weszła do miasta Dawida, Mikal, córka Saula, wyglądała przez okno i zobaczyła króla Dawida, jak skakał i tańczył przed Panem, i wzgardziła nim w swoim sercu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 17, 'Sprowadzili więc arkę Pana i ustawili ją na swoim miejscu w środku namiotu, który rozpiął dla niej Dawid. I Dawid złożył przed Panem całopalenia i ofiary pojednawcze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 18, 'A gdy Dawid skończył składać całopalenia i ofiary pojednawcze, błogosławił ludowi w imię Pana zastępów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 19, 'I rozdał wśród całego ludu i całego zgromadzenia Izraela, zarówno mężczyznom, jak i kobietom, każdemu po jednym bochenku chleba, po jednym kawałku mięsa i po jednym bukłaku wina. Potem cały lud odszedł, każdy do swojego domu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 20, 'Potem Dawid wrócił, aby pobłogosławić swój dom. I Mikal, córka Saula, wyszła naprzeciw Dawidowi, i powiedziała: O jakże wspaniały był dziś król Izraela, który się obnażył dziś na oczach służących swych sług, tak jak się obnaża jakiś niepoważny człowiek!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 21, 'Wtedy Dawid powiedział do Mikal: Grałem przed Panem, który wybrał raczej mnie niż twego ojca i niż cały jego dom, aby ustanowić mnie wodzem nad ludem Pana, nad Izraelem. Będę więc grał przed Panem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 22, 'I poniżę się jeszcze bardziej niż dotąd, i będę jeszcze bardziej godny pogardy w swoich oczach, lecz u służących, o których mi mówiłaś, będę poważany.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 23, 'Mikal, córka Saula, nie miała więc dzieci aż do dnia swej śmierci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 1, 'Gdy król zamieszkał w swoim domu, a Pan dał mu odpoczynek od wszystkich jego wrogów wokoło;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 2, 'Król powiedział do proroka Natana: Zobacz, proszę, ja mieszkam w domu cedrowym, a arka Boga mieszka za zasłoną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 3, 'Wtedy Natan odpowiedział królowi: Idź i uczyń wszystko, co jest w twoim sercu, gdyż Pan jest z tobą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 4, 'Lecz tej samej nocy doszło do Natana słowo Pana:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 5, 'Idź i powiedz mojemu słudze Dawidowi: Tak mówi Pan: Czy ty zbudujesz mi dom, abym w nim mieszkał?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 6, 'Nie mieszkałem bowiem w żadnym domu od dnia, w którym wyprowadziłem synów Izraela z Egiptu, aż do dziś, lecz wędrowałem w namiocie i w przybytku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 7, 'I wszędzie, gdzie wędrowałem ze wszystkimi synami Izraela, czy powiedziałem do któregoś z sędziów Izraela, którym nakazałem paść mój lud Izraela: Dlaczego nie budujecie mi domu cedrowego?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 8, 'Teraz więc tak powiesz mojemu słudze Dawidowi: Tak mówi Pan zastępów: Wziąłem ciebie z owczarni, gdzie chodziłeś za owcami, abyś był wodzem nad moim ludem, nad Izraelem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 9, 'I byłem z tobą wszędzie, dokądkolwiek chodziłeś, wytraciłem przed tobą wszystkich twoich wrogów i uczyniłem twoje imię wielkim jak imię wielkich ludzi, którzy są na ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 10, 'Ustanowię miejsce dla mojego ludu Izraela i zasadzę go tam, by mógł mieszkać na swoim miejscu, i nie poruszy się więcej ani już nie będą go uciskać synowie nieprawości jak dawniej;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 11, 'Od czasu, kiedy ustanowiłem sędziów nad moim ludem Izraelem i dałem ci odpoczynek od wszystkich twoich wrogów. Tobie też Pan oznajmia, że zbuduje ci dom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 12, 'Gdy się dopełnią twoje dni i zaśniesz ze swoimi ojcami, wzbudzę po tobie twojego potomka, który wyjdzie z twego wnętrza, i umocnię jego królestwo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 13, 'On zbuduje dom dla mojego imienia, a ja utwierdzę tron jego królestwa na wieki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 14, 'Ja będę mu ojcem, a on będzie mi synem. Jeśli zgrzeszy, skarcę go rózgą ludzką i razami synów ludzkich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 15, 'Lecz moje miłosierdzie nie odstąpi od niego, tak jak je cofnąłem od Saula, którego odrzuciłem przed tobą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 16, 'I twój dom, i twoje królestwo będą utwierdzone na wieki przed tobą, a twój tron będzie trwał na wieki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 17, 'Zgodnie z tymi wszystkimi słowami i zgodnie z tym całym widzeniem mówił Natan do Dawida.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 18, 'Wtedy wszedł król Dawid, usiadł przed Panem i przemówił: Kimże ja jestem, Panie Boże, i czymże jest mój dom, że doprowadziłeś mnie aż dotąd?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 19, 'Lecz i to było jeszcze mało w twoich oczach, Panie Boże, gdyż złożyłeś również obietnicę o domu twojego sługi na daleką przyszłość. Czy taki jest zwyczaj u ludzi, Panie Boże?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 20, 'I cóż więcej może powiedzieć ci Dawid? Ty bowiem znasz swojego sługę, Panie Boże.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 21, 'Ze względu na twoje słowo i zgodnie z twoim sercem uczyniłeś wszystkie te wielkie rzeczy, dając poznać je twemu słudze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 22, 'Dlatego jesteś wielki, Panie Boże. Nie ma bowiem nikogo podobnego do ciebie i nie ma Boga oprócz ciebie, zgodnie z tym, co usłyszeliśmy na własne uszy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 23, 'I czyż jest taki naród na ziemi jak twój lud Izrael, dla którego Bóg wyruszył, aby wykupić go sobie jako lud, by uczynić wielkim swoje imię i dokonać dla nich wielkich i straszliwych rzeczy w twojej ziemi, przed twoim ludem, który wykupiłeś sobie z Egiptu, spośród narodów i ich bogów?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 24, 'Ustanowiłeś sobie bowiem swój lud, Izraela, aby był dla ciebie ludem na wieki. A ty, Panie, stałeś się jego Bogiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 25, 'Teraz więc, Panie Boże, utwierdź na wieki słowo, które wypowiedziałeś o swoim słudze i o jego domu, i czyń, jak powiedziałeś;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 26, 'Aby twoje imię było wielbione na wieki, aby mówiono: Pan zastępów jest Bogiem nad Izraelem, a dom twego sługi Dawida będzie utwierdzony przed tobą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 27, 'Ty bowiem, Panie zastępów, Boże Izraela, objawiłeś swemu słudze, mówiąc: Zbuduję ci dom. Dlatego twój sługa ośmielił się skierować do ciebie tę modlitwę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 28, 'A teraz, Panie Boże, ty jesteś tym Bogiem, a twoje słowa są prawdą, obiecałeś swemu słudze tę dobroć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 29, 'Teraz więc racz pobłogosławić dom swego sługi, aby przed tobą trwał na wieki. Ty bowiem, Panie Boże, to powiedziałeś i dzięki twojemu błogosławieństwu dom twego sługi będzie błogosławiony na wieki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 1, 'Po tych wydarzeniach Dawid pobił Filistynów i ujarzmił ich. Dawid zabrał też z rąk Filistynów Meteg-Amma.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 2, 'Pobił także Moabitów, których zmierzył sznurem i ułożył na ziemi. Wymierzył ich dwa sznury do zabicia, a jeden cały sznur do zachowania przy życiu. I Moabici zostali sługami Dawida płacącymi daninę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 3, 'Dawid pobił również Hadadezera, syna Rechoba, króla Soby, kiedy ten wyruszał, aby przywrócić swoją granicę nad rzeką Eufrat.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 4, 'I Dawid zabrał mu tysiąc rydwanów, siedmiuset jeźdźców i dwadzieścia tysięcy piechoty. I Dawid popodcinał ścięgna wszystkim koniom zaprzęgowym, zostawiając z nich tylko tyle, ile potrzeba do stu rydwanów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 5, 'Kiedy Syryjczycy z Damaszku przybyli na pomoc Hadadezerowi, królowi Soby, Dawid pobił spośród Syryjczyków dwadzieścia dwa tysiące ludzi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 6, 'Potem Dawid umieścił załogi w Syrii, w Damaszku, a Syryjczycy zostali sługami Dawida płacącymi daninę. I Pan bronił Dawida wszędzie, dokądkolwiek się udał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 7, 'Dawid zabrał też złote tarcze, które mieli słudzy Hadadezera, i przyniósł je do Jerozolimy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 8, 'I z Betachu i z Berotaj, miast Hadadezera, król Dawid zabrał bardzo dużo brązu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 9, 'Gdy Toi, król Chamat, usłyszał, że Dawid pokonał całe wojsko Hadadezera;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 10, 'Wysłał swego syna Jorama do króla Dawida, aby go pozdrowił w pokoju i aby powinszował mu tego, że walczył z Hadadezerem i pokonał go. Hadadezer bowiem prowadził wojnę z Toi. I Joram przyniósł ze sobą przedmioty ze srebra, ze złota i z brązu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 11, 'Również i te król Dawid poświęcił Panu wraz ze srebrem i złotem, które poświęcił, zabranym od wszystkich narodów, które podbił;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 12, 'Od Syrii, od Moabu, od synów Ammona, od Filistynów, od Amaleka i z łupów Hadadezera, syna Rechoba, króla Soby.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 13, 'I tak Dawid uczynił sławnym swoje imię, gdy wrócił po pokonaniu Syryjczyków w Dolinie Soli w liczbie osiemnastu tysięcy mężczyzn.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 14, 'Umieścił w Edomie załogi, na całej ziemi Edomu rozmieścił je. I wszyscy Edomczycy stali się sługami Dawida. I Pan bronił Dawida wszędzie, dokądkolwiek się udał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 15, 'I Dawid królował nad całym Izraelem, i sprawował sąd nad całym swym ludem, i wymierzał mu sprawiedliwość.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 16, 'Joab, syn Serui, był postawiony nad wojskiem, a Jehoszafat, syn Achiluda, był kronikarzem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 17, 'Sadok, syn Achituba, i Achimelek, syn Abiatara, byli kapłanami, a Serajasz – pisarzem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 18, 'Benajasz, syn Jehojady, był postawiony nad Keretytami i Peletytami, a synowie Dawida byli książętami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 1, 'Wtedy Dawid zapytał: Czy pozostał jeszcze ktoś z domu Saula, abym mógł okazać mu miłosierdzie ze względu na Jonatana?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 2, 'A z domu Saula był sługa imieniem Siba. Został on wezwany do Dawida i król zapytał go: Czy ty jesteś Siba? Odpowiedział: To ja, twój sługa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 3, 'Król pytał dalej: Czy nie ma jeszcze kogoś z domu Saula, abym mógł okazać mu miłosierdzie Boże? Siba odpowiedział królowi: Jest jeszcze syn Jonatana, chromy na nogi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 4, 'Król zapytał go: Gdzie on jest? Siba odpowiedział królowi: Oto jest w domu Makira, syna Ammiela, w Lo-Debar.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 5, 'Król Dawid posłał więc, by go sprowadzić z domu Makira, syna Ammiela, z Lo-Debar.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 6, 'A gdy Mefiboszet, syn Jonatana, syna Saula, przybył do Dawida, upadł na twarz i pokłonił mu się. I Dawid powiedział: Mefiboszecie! Ten odpowiedział: Oto twój sługa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 7, 'Dawid powiedział do niego: Nie bój się, bo z całą pewnością okażę ci miłosierdzie ze względu na twego ojca Jonatana i przywrócę ci wszystkie ziemie twego ojca Saula, a ty zawsze będziesz jadał chleb przy moim stole.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 8, 'Wtedy ukłonił się i powiedział: Czym jest twój sługa, że zwracasz się do zdechłego psa, jakim jestem?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 9, 'Następnie król wezwał Sibę, sługę Saula, i powiedział mu: Wszystko, co należało do Saula i do całego jego domu, dałem synowi twego pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 10, 'Będziesz więc uprawiał jego ziemię, ty, twoi synowie i twoi słudzy. Będziesz zbierał plony, aby syn twego pana mógł jeść chleb. Mefiboszet natomiast, syn twego pana, będzie zawsze jadał chleb przy moim stole. A Siba miał piętnastu synów i dwudziestu sług.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 11, 'Siba odpowiedział królowi: Wszystko, co mój pan, król, rozkazał swemu słudze, to twój sługa uczyni. A Mefiboszet – dodał król – będzie jadał przy moim stole jak jeden z synów króla.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 12, 'Mefiboszet miał też małego syna imieniem Mika. A wszyscy, którzy mieszkali w domu Siby, byli sługami Mefiboszeta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 13, 'Tak Mefiboszet mieszkał w Jerozolimie, gdyż zawsze jadał przy stole króla. A był chromy na obie nogi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 1, 'Po tych wydarzeniach umarł król synów Ammona, a jego syn Chanun królował w jego miejsce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 2, 'Wtedy Dawid powiedział: Okażę życzliwość Chanunowi, synowi Nachasza, tak jak jego ojciec okazał mi życzliwość. I Dawid wysłał swe sługi, by pocieszyć go po stracie jego ojca. Słudzy Dawida przyszli więc do ziemi synów Ammona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 3, 'Lecz książęta synów Ammona powiedzieli do swego pana Chanuna: Czy myślisz, że Dawid chce uczcić twego ojca i dlatego przysłał do ciebie pocieszycieli? Czy nie po to raczej Dawid posyła swoje sługi do ciebie, aby przypatrzyli się miastu i przeszpiegowali je, by potem je zburzyć?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 4, 'Chanun wziął więc sługi Dawida, zgolił im brody do połowy, poobcinał ich szaty do połowy, aż do pośladków, i odesłał ich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 5, 'A gdy doniesiono o tym Dawidowi, wysłał im na spotkanie posłów, ponieważ ci mężczyźni byli bardzo znieważeni. I król powiedział im: Zostańcie w Jerychu, aż wam brody odrosną, a potem wróćcie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 6, 'Gdy synowie Ammona spostrzegli, że obrzydli Dawidowi, posłali i wynajęli sobie dwadzieścia tysięcy piechoty Syryjczyków z Bet-Rekob i Syryjczyków z Soby, od króla Maaki tysiąc mężczyzn, a z Isztobu dwanaście tysięcy mężczyzn.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 7, 'Kiedy Dawid o tym usłyszał, wysłał Joaba z całym zastępem dzielnych wojowników.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 8, 'Wtedy synowie Ammona wyszli i ustawili się w szyku bojowym przed wejściem do bramy. Syryjczycy zaś z Soby i z Rechob oraz ci z Isztobu i Maaki stanęli osobno w polu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 9, 'Gdy Joab zobaczył wojska wystawione przeciwko sobie z przodu i z tyłu, wybrał ludzi spośród wszystkich wyborowych mężczyzn w Izraelu i ustawił ich w szyku bojowym przeciwko Syryjczykom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 10, 'A resztę ludzi oddał pod rękę swego brata Abiszaja, aby ich ustawił w szyku bojowym przeciwko synom Ammona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 11, 'I powiedział: Jeśli Syryjczycy będą silniejsi ode mnie, przyjdziesz mi z pomocą, a jeśli synowie Ammona będą silniejsi od ciebie, ja przyjdę tobie z pomocą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 12, 'Bądź odważny i walczmy mężnie za swój lud i za miasta naszego Boga, a niech Pan uczyni to, co jest dobre w jego oczach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 13, 'Joab wraz z ludem, który był z nim, wyruszył więc do bitwy z Syryjczykami. A oni uciekli przed nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 14, 'Gdy synowie Ammona zobaczyli, że Syryjczycy uciekli, uciekli i oni przed Abiszajem i weszli do miasta. Wtedy Joab zawrócił od synów Ammona i przybył do Jerozolimy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 15, 'Kiedy Syryjczycy zobaczyli, że są pobici przez Izraela, zebrali się razem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 16, 'I Hadadezer posłał po Syryjczyków, którzy byli za rzeką, i sprowadził ich. Przybyli oni do Helam, a Szobak, dowódca wojska Hadadezera, prowadził ich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 17, 'Gdy doniesiono o tym Dawidowi, zebrał cały Izrael, przeprawił się przez Jordan i przybył do Helam. A Syryjczycy ustawili się w szyku bojowym przeciw Dawidowi i stoczyli z nim bitwę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 18, 'Lecz Syryjczycy uciekli przed Izraelem i spośród Syryjczyków Dawid zabił ludzi z siedmiuset rydwanów oraz czterdzieści tysięcy jeźdźców. Zranił też Szobaka, dowódcę ich wojska, który tam zmarł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 19, 'Kiedy wszyscy królowie, poddani Hadadezera, zobaczyli, że są pobici przez Izraela, zawarli pokój z Izraelem i służyli im. I Syryjczycy bali się odtąd iść na pomoc synom Ammona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 1, 'Na początku roku, w czasie, kiedy królowie zwykli wyjeżdżać na wojnę, Dawid wysłał Joaba wraz ze swoimi sługami oraz cały Izrael. Spustoszyli oni synów Ammona i oblegli Rabbę. Dawid zaś został w Jerozolimie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 2, 'Pewnego dnia pod wieczór Dawid wstał z łoża i przechadzał się po dachu domu królewskiego. I zobaczył z dachu kąpiącą się kobietę, a kobieta była bardzo piękna.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 3, 'I Dawid posłał, i zapytał o tę kobietę. I powiedziano mu: Czy to nie Batszeba, córka Eliama, żona Uriasza Chetyty?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 4, 'Dawid wysłał więc po nią posłańców i wziął ją. A gdy przyszła do niego, położył się z nią, gdyż była oczyszczona od swojej nieczystości. Potem wróciła do swego domu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 5, 'Kobieta ta poczęła, więc posłała, by zawiadomić Dawida: Jestem brzemienna.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 6, 'Wtedy Dawid posłał do Joaba rozkaz: Przyślij do mnie Uriasza Chetytę. Joab wysłał więc Uriasza do Dawida.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 7, 'A gdy Uriasz przybył do niego, Dawid pytał go o to, jak się wiedzie Joabowi, jak się wiedzie ludowi i jak przebiega wojna.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 8, 'Następnie Dawid powiedział do Uriasza: Idź do swego domu i umyj sobie nogi. I Uriasz wyszedł z domu króla, a za nim niesiono potrawy od króla.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 9, 'Lecz Uriasz spał przy bramie domu króla razem ze wszystkimi sługami swego pana, a do swojego domu nie poszedł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 10, 'I doniesiono Dawidowi: Uriasz nie poszedł do swego domu. Dawid zapytał Uriasza: Czy nie przybyłeś z podróży? Czemu więc nie poszedłeś do swego domu?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 11, 'Uriasz odpowiedział Dawidowi: Arka, Izrael i Juda przebywają w namiotach, mój pan Joab i słudzy mojego pana obozują w otwartym polu, a ja miałbym wejść do swojego domu, aby jeść, pić i spać ze swoją żoną? Jak żyjesz i jak żyje twoja dusza, nie uczynię tego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 12, 'Wtedy Dawid powiedział do Uriasza: Zostań tu jeszcze dziś, a jutro cię odprawię. I Uriasz został w Jerozolimie przez ten i kolejny dzień.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 13, 'Potem Dawid wezwał go, aby jadł i pił w jego obecności, i upoił go. Lecz wieczorem wyszedł i spał na swoim łożu ze sługami swego pana, a do swego domu nie poszedł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 14, 'Następnego ranka Dawid napisał więc list do Joaba i wysłał go przez rękę Uriasza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 15, 'A w liście napisał tak: Postawcie Uriasza na czele najbardziej zaciętej bitwy, a potem odstąpcie od niego, aby został trafiony i zginął.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 16, 'I kiedy Joab obejrzał miasto, postawił Uriasza w miejscu, o którym wiedział, że byli tam dzielni ludzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 17, 'A gdy ludzie z miasta wypadli, stoczyli bitwę z Joabem i padło z ludu kilka sług Dawida, poległ także Uriasz Chetyta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 18, 'Wtedy Joab wysłał posłańca i zawiadomił Dawida o wszystkim, co działo się podczas bitwy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 19, 'A posłańcowi rozkazał: Gdy skończysz opowiadać królowi o tym, co się wydarzyło na bitwie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 20, 'I jeśli król się rozgniewa, i zapyta: Czemu podeszliście tak blisko do miasta, by walczyć? Czyż nie wiedzieliście, że strzelają z muru?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 21, 'Kto zabił Abimeleka, syna Jerubbeszeta? Czyż nie kobieta, która zrzuciła na niego z muru kawałek kamienia młyńskiego, tak że umarł w Tebes? Czemu podeszliście do muru? Wtedy powiesz: Zginął również twój sługa Uriasz Chetyta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 22, 'Poszedł więc posłaniec, a gdy przybył, opowiedział Dawidowi wszystko, z czym wysłał go Joab.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 23, 'Posłaniec mówił do Dawida: Tamci ludzie nas przemogli i wyszli przeciw nam na pole, a my ścigaliśmy ich aż do samej bramy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 24, 'Wtedy łucznicy strzelali z muru do twoich sług i zginęło kilku ze sług króla. Zginął również twój sługa Uriasz Chetyta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 25, 'Wtedy Dawid powiedział do posłańca: Tak powiesz Joabowi: Nie zamartwiaj się tą sprawą, bo miecz pożera raz tego, raz innego. Wzmocnij natarcie na miasto i zburz je, ty sam dodawaj mu otuchy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 26, 'A gdy żona Uriasza usłyszała, że jej mąż Uriasz umarł, zaczęła opłakiwać swego męża.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 27, 'Kiedy żałoba przeminęła, Dawid posłał po nią i sprowadził ją do swego domu. Została jego żoną i urodziła mu syna. Lecz to, co zrobił Dawid, nie podobało się Panu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 1, 'Wtedy Pan posłał Natana do Dawida. Ten przybył do niego i powiedział: W pewnym mieście było dwóch ludzi, jeden bogaty, a drugi ubogi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 2, 'Bogaty miał bardzo dużo owiec i wołów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 3, 'A ubogi nie miał nic oprócz jednej małej owieczki, którą kupił i żywił. Wyrosła przy nim wraz z jego dziećmi, jadła jego chleb i piła z jego kubka, spała na jego łonie i była mu jak córka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 4, 'I przyszedł gość do tego bogatego, a jemu było żal wziąć ze swoich owiec albo ze swoich wołów, aby przyrządzić ucztę dla gościa, który do niego przyszedł. Wziął więc owieczkę tego ubogiego i przyrządził ją dla człowieka, który do niego przyszedł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 5, 'Wtedy Dawid mocno zapłonął gniewem na tego człowieka i powiedział do Natana: Jak żyje Pan, człowiek, który to uczynił, zasługuje na śmierć;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 6, 'Za owcę wynagrodzi poczwórnie, dlatego że tak uczynił i nie miał litości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 7, 'Wtedy Natan powiedział do Dawida: Ty jesteś tym człowiekiem. Tak mówi Pan, Bóg Izraela: Ja cię namaściłem, abyś był królem nad Izraelem, i ja cię wybawiłem z rąk Saula;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 8, 'Dałem ci dom twego pana i żony twego pana na twe łono, dałem ci dom Izraela i Judy, a gdyby tego było za mało, dałbym ci jeszcze więcej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 9, 'Dlaczego wzgardziłeś słowem Pana, czyniąc to zło w jego oczach? Zabiłeś mieczem Uriasza Chetytę, a jego żonę wziąłeś sobie za żonę, jego zaś zabiłeś mieczem synów Ammona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 10, 'Teraz więc miecz nigdy nie odstąpi od twojego domu, ponieważ wzgardziłeś mną i wziąłeś żonę Uriasza Chetytę, by była twoją żoną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 11, 'Tak mówi Pan: Oto wzbudzę przeciwko tobie nieszczęście z twego własnego domu, wezmę twoje żony sprzed twoich oczu i dam je twemu bliźniemu, a on położy się z twoimi żonami wobec tego słońca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 12, 'I chociaż ty uczyniłeś to potajemnie, ja jednak uczynię to przed całym Izraelem i przed słońcem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 13, 'Wtedy Dawid powiedział do Natana: Zgrzeszyłem przeciw Panu. Natan zaś odpowiedział Dawidowi: Pan też przebaczył ci twój grzech, nie umrzesz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 14, 'Ponieważ jednak przez ten czyn dałeś wrogom Pana powód, by bluźnili, syn, który ci się urodził, na pewno umrze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 15, 'Potem Natan wrócił do swego domu. A Pan poraził dziecko, które żona Uriasza urodziła Dawidowi, i ciężko zachorowało.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 16, 'Wtedy Dawid wstawił się u Boga za dzieckiem. I Dawid pościł, a gdy wrócił do siebie, leżał całą noc na ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 17, 'I starsi jego domu przyszli do niego, aby go podnieść z ziemi. On jednak nie chciał i nie jadł z nimi chleba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 18, 'A siódmego dnia dziecko umarło. I słudzy Dawida bali się powiedzieć mu, że dziecko umarło. Mówili bowiem: Oto póki dziecko jeszcze żyło, mówiliśmy do niego, a on nie słuchał naszego głosu. Jak powiemy, że dziecko umarło, dopiero będzie się trapił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 19, 'Gdy jednak Dawid zobaczył, że jego słudzy szepcą między sobą, zrozumiał, że dziecko umarło. Dawid więc zapytał swoich sług: Czy dziecko umarło? Odpowiedzieli: Umarło.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 20, 'Wtedy Dawid wstał z ziemi, umył się i namaścił, zmienił swoje szaty i wszedł do domu Pana, aby oddać mu pokłon. Potem wrócił do swego domu i kazał przynieść posiłek, i położyli przed nim chleb, i jadł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 21, 'Jego słudzy zapytali go: Co znaczy to, co uczyniłeś? Póki dziecko jeszcze żyło, pościłeś i płakałeś, a gdy dziecko umarło, wstałeś i jadłeś chleb.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 22, 'Odpowiedział: Póki dziecko jeszcze żyło, pościłem i płakałem. Mówiłem bowiem: Któż wie, może Pan zmiłuje się nade mną i dziecko będzie żyło.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 23, 'Lecz teraz, gdy już umarło, dlaczego miałbym pościć? Czy mogę je przywrócić do życia? Ja pójdę do niego, ale ono do mnie nie wróci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 24, 'I Dawid pocieszał swoją żonę Batszebę. Wszedł do niej i położył się z nią. Potem urodziła syna, a on nadał mu imię Salomon. A Pan go umiłował.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 25, 'Posłał więc przez Natana proroka i nadał mu imię Jedidija ze względu na Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 26, 'Potem Joab walczył przeciw Rabbie synów Ammona i zdobył miasto królewskie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 27, 'I Joab wysłał posłańców do Dawida, i powiedział: Walczyłem przeciw Rabbie i zdobyłem miasto wód.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 28, 'Teraz więc zbierz resztę ludu, oblegaj miasto i zdobądź je, abym to nie ja zdobył miasto i aby nie przypisano zwycięstwa memu imieniu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 29, 'Dawid zebrał więc cały lud, udał się do Rabby, walczył przeciwko niej i zdobył ją.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 30, 'Zdjął też koronę z głowy jej króla, która ważyła talent złota i była ozdobiona drogocennymi kamieniami. I włożono ją na głowę Dawida. Wywiózł też z miasta bardzo wielki łup.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 31, 'Wyprowadził mieszkańców miasta i podał ich pod piły, żelazne brony i żelazne siekiery i zmusił ich do przejścia przez piec do wypalania cegieł. Tak uczynił ze wszystkimi miastami synów Ammona. Potem Dawid wrócił wraz z całym ludem do Jerozolimy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 1, 'Później stało się tak: Absalom, syn Dawida, miał piękną siostrę imieniem Tamar. I zakochał się w niej Amnon, syn Dawida.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 2, 'I dręczył się Amnon tak, że zachorował z powodu swojej siostry Tamar. Była bowiem dziewicą i Amnonowi zdawało się rzeczą trudną, aby uczynić jej cokolwiek.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 3, 'Lecz Amnon miał przyjaciela imieniem Jonadab, syna Szimy, brata Dawida. A Jonadab był człowiekiem bardzo przebiegłym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 4, 'Ten go zapytał: Dlaczego ty, synu królewski, tak mizerniejesz z dnia na dzień? Dlaczego mi nic nie mówisz? Amnon odpowiedział: Zakochałem się w Tamar, siostrze mojego brata Absaloma.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 5, 'Jonadab powiedział mu: Połóż się do łóżka i udawaj chorego. Gdy twój ojciec przyjdzie, aby cię odwiedzić, powiesz mu: Pozwól, proszę, aby przyszła moja siostra Tamar i dała mi jeść, aby przygotowała posiłek na moich oczach, bym to widział i jadł z jej ręki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 6, 'Amnon położył się więc i udawał chorego. A gdy król przyszedł go odwiedzić, Amnon powiedział do króla: Pozwól, proszę, aby moja siostra Tamar przyszła i przygotowała na moich oczach dwa placki, abym jadł z jej ręki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 7, 'Wtedy Dawid posłał Tamar do domu, mówiąc: Idź teraz do domu twego brata Amnona i przygotuj mu posiłek.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 8, 'Tamar przyszła więc do domu swego brata Amnona, a on leżał. Wzięła mąkę i zagniotła ciasto, po czym uczyniła placki na jego oczach i upiekła je.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 9, 'Potem wzięła patelnię i wyłożyła je przed nim, lecz nie chciał jeść. I Amnon rozkazał: Niech wszyscy wyjdą ode mnie. Wszyscy wyszli więc od niego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 10, 'Wtedy Amnon powiedział do Tamar: Przynieś jedzenie do sypialni, abym jadł z twojej ręki. Tamar wzięła więc placki, które przyrządziła, i przyniosła je swemu bratu Amnonowi do sypialni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 11, 'A gdy podawała mu je do jedzenia, pochwycił ją i powiedział do niej: Chodź, połóż się ze mną, moja siostro.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 12, 'Ona mu odpowiedziała: Nie, mój bracie, nie hańb mnie, bo tak się nie postępuje w Izraelu. Nie popełniaj tego haniebnego czynu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 13, 'Dokąd bowiem się udam ze swoją hańbą? A ty staniesz się jak jeden z ludzi nikczemnych w Izraelu. Proszę, porozmawiaj raczej z królem, bo on ci mnie nie odmówi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 14, 'Lecz on nie chciał posłuchać jej głosu, ale przemógł ją i zhańbił, i położył się z nią.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 15, 'Potem Amnon znienawidził ją tak bardzo, że nienawiść, którą ją znienawidził, była większa niż miłość, jaką ją miłował. I Amnon powiedział jej: Wstań, idź stąd!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 16, 'Odpowiedziała: Z jakiego powodu? Wyrzucając mnie, czynisz mi większą krzywdę niż ta, którą już wyrządziłeś. Ale nie chciał jej posłuchać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 17, 'Wtedy zawołał swego sługę, który mu usługiwał, i rozkazał: Wyprowadź tę kobietę ode mnie i zarygluj za nią drzwi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 18, 'A miała na sobie kolorową suknię, gdyż w takie szaty ubierały się córki króla, które były dziewicami. Wtedy jego sługa wyprowadził ją i zaryglował za nią drzwi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 19, 'I Tamar posypała swą głowę popiołem, rozdarła kolorową suknię, którą nosiła, położyła rękę na głowie i odeszła, głośno płacząc.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 20, 'Wtedy jej brat Absalom zapytał ją: Czy twój brat Amnon był z tobą? Ale milcz, moja siostro. To twój brat. Nie bierz tego do serca. Tamar mieszkała więc w osamotnieniu w domu swego brata Absaloma.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 21, 'Gdy król Dawid usłyszał o tym wszystkim, bardzo się rozgniewał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 22, 'Absalom zaś nie rozmawiał z Amnonem ani źle, ani dobrze. Absalom bowiem nienawidził Amnona za to, że zhańbił jego siostrę Tamar.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 23, 'Po upływie dwóch lat, gdy strzyżono owce Absaloma w Baal-Chasor, które znajduje się w pobliżu Efraim, Absalom zaprosił wszystkich synów króla.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 24, 'Absalom przyszedł do króla i powiedział: Oto teraz strzygą owce twemu słudze. Proszę, niech król i jego słudzy pójdą z twoim sługą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 25, 'Lecz król powiedział do Absaloma: Nie, mój synu. Teraz nie pójdziemy wszyscy, aby nie być dla ciebie ciężarem. A chociaż nalegał na niego, on nie chciał iść, ale go błogosławił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 26, 'Wtedy Absalom powiedział: Jeśli nie, proszę, niech pójdzie z nami mój brat Amnon. Król zapytał go: Po cóż miałby iść z tobą?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 27, 'A gdy Absalom nalegał na niego, posłał z nim Amnona i wszystkich synów króla.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 28, 'Absalom zaś nakazał swoim sługom: Zauważcie, kiedy serce Amnona podochoci się winem, a gdy powiem wam: Zabijcie Amnona, zabijcie go, nie bójcie się. Ja bowiem nakazuję to wam. Bądźcie odważni i sprawcie się dzielnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 29, 'I słudzy Absaloma uczynili z Amnonem tak, jak im nakazał Absalom. Wtedy wszyscy synowie króla wstali, każdy z nich dosiadł swego muła, i uciekli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 30, 'A gdy jeszcze byli w drodze, dotarła do Dawida wieść: Absalom pozabijał wszystkich synów króla i nie pozostał z nich ani jeden.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 31, 'Wtedy król wstał i rozdarł swoje szaty, i położył się na ziemi. Wszyscy jego słudzy stali dokoła niego w rozdartych szatach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 32, 'Wtedy odezwał się Jonadab, syn Szimy, brata Dawida: Niech mój pan nie myśli, że zabito wszystkich młodzieńców, synów króla, bo tylko Amnon został zabity. Takie bowiem było postanowienie w umyśle Absaloma od tego dnia, w którym zhańbił jego siostrę Tamar.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 33, 'Teraz więc niech mój pan, król, nie dopuszcza tego do serca, myśląc, że zginęli wszyscy synowie króla, gdyż tylko Amnon zginął.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 34, 'Absalom zaś uciekł. A gdy młodzieniec pełniący straż podniósł oczy i spojrzał, oto za nim mnóstwo ludzi przychodziło drogą ze zbocza góry.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 35, 'I Jonadab powiedział do króla: Oto synowie króla nadchodzą. Stało się tak, jak twój sługa powiedział.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 36, 'A gdy przestał mówić, oto przybyli synowie króla, podnieśli głos i płakali. Król i wszyscy jego słudzy również gorzko płakali.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 37, 'Absalom zaś uciekł i poszedł do Talmaja, syna Ammihuda, króla Geszur. A Dawid opłakiwał swego syna przez wszystkie te dni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 38, 'Absalom uciekł więc i przyszedł do Geszur, gdzie przebywał przez trzy lata.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 39, 'Potem król Dawid zapragnął zobaczyć Absaloma. Był już bowiem pocieszony po śmierci Amnona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 1, 'A Joab, syn Serui, spostrzegł, że serce króla skłaniało się ku Absalomowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 2, 'Posłał więc Joab do Tekoa i sprowadził stamtąd pewną mądrą kobietę, do której powiedział: Proszę, udawaj, że jesteś w żałobie, ubieraj się w szaty żałobne i nie namaszczaj się olejkiem, ale bądź jak kobieta, która od dłuższego czasu opłakuje zmarłego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 3, 'Potem idź do króla i mów do niego w ten sposób. I Joab pouczył ją, co ma mówić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 4, 'A gdy kobieta z Tekoa mówiła do króla, upadła twarzą do ziemi i oddała mu pokłon. Powiedziała: Ratuj, królu!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 5, 'I król ją zapytał: Co ci jest? Ona zaś odpowiedziała: Jestem wdową, mój mąż umarł;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 6, 'Twoja służąca miała dwóch synów, którzy pokłócili się ze sobą na polu. A gdy nie było nikogo, kto by ich rozdzielił, jeden uderzył drugiego i zabił go.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 7, 'A oto cała rodzina powstała przeciw twojej służącej i powiedziała: Wydaj tego, który zabił swego brata, byśmy mogli go zabić za życie jego brata, którego zamordował, a także zgładzimy dziedzica. W ten sposób zgaszą mój węgielek, który pozostał, aby nie zostawić po moim mężu ani imienia, ani potomka na ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 8, 'Wtedy król powiedział do kobiety: Idź do swego domu, a ja wydam rozkaz w twojej sprawie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 9, 'I kobieta z Tekoa odpowiedziała królowi: Mój panie, królu, niech ta nieprawość spadnie na mnie i na dom mego ojca. A król i jego tron niech będzie bez winy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 10, 'Król powiedział: Jeśli ktoś będzie mówił przeciwko tobie, przyprowadź go do mnie, a już więcej cię nie dotknie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 11, 'Wtedy ona powiedziała: Wspomnij, proszę, królu, na Pana, swego Boga, i nie pozwól mścicielom krwi sprowadzić większej zguby, aby mój syn nie został zgładzony. I odpowiedział: Jak żyje Pan, nie spadnie nawet jeden włos twego syna na ziemię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 12, 'Kobieta powiedziała: Pozwól, proszę, że twoja służąca przemówi jeszcze jedno słowo do mego pana, króla. Odpowiedział: Mów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 13, 'Wtedy kobieta powiedziała: Czemu więc wymyśliłeś podobną rzecz przeciw ludowi Bożemu? Król bowiem mówi to słowo, sam będąc winny, ponieważ król nie sprowadza z powrotem swego wygnańca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 14, 'Wszyscy bowiem umieramy i jesteśmy jak woda rozlana na ziemi, której nie można zebrać. Bóg jednak nie odebrał mu życia, ale obmyśla sposób na to, by wygnaniec nie pozostawał na wygnaniu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 15, 'Przyszłam więc teraz, by mówić o tym mojemu panu, królowi, gdyż lud mnie przestraszył. Dlatego twoja służąca powiedziała: Przemówię teraz do króla, może król spełni prośbę swojej służącej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 16, 'Król bowiem wysłucha swojej służącej i wybawi ją z ręki człowieka, który chce zgładzić mnie i mojego syna z Bożego dziedzictwa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 17, 'Twoja służąca też powiedziała: Teraz słowo mojego pana, króla, będzie pocieszeniem. Gdyż mój pan, król, jest jak anioł Boga, rozsądzając między dobrem a złem. Niech Pan, twój Bóg, będzie z tobą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 18, 'Wtedy król odezwał się do kobiety: Proszę, nie ukrywaj przede mną tego, o co zapytam. Kobieta odpowiedziała: Niech mówi mój pan, król.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 19, 'Król więc zapytał: Czy nie ma w tym wszystkim ręki Joaba? Kobieta odpowiedziała: Jak żyje twoja dusza, mój panie, królu, nic nie odbiega ani w prawo, ani w lewo od tego wszystkiego, co mówił mój pan, król. Istotnie twój sługa Joab mi to rozkazał i on to włożył w usta twojej służącej wszystkie te słowa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 20, 'Twój sługa Joab sprawił, że zmieniłam postać tych słów. Mój pan jednak jest mądry mądrością anioła Boga, tak że wie wszystko, co się dzieje na ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 21, 'Król więc powiedział do Joaba: Oto teraz uczyń tę rzecz. Idź i sprowadź młodzieńca Absaloma.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 22, 'I Joab upadł twarzą do ziemi, pokłonił się i błogosławił króla. Potem Joab powiedział: Dziś twój sługa poznał, że znalazłem łaskę w twoich oczach, mój panie, królu, ponieważ król spełnił prośbę swego sługi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 23, 'Wtedy Joab wstał i wyruszył do Geszur, i sprowadził Absaloma do Jerozolimy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 24, 'Król jednak powiedział: Niech wróci do swego domu, ale mojej twarzy nie zobaczy. Absalom wrócił więc do swego domu, ale twarzy króla nie zobaczył.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 25, 'A w całym Izraelu nie było mężczyzny tak osławionego z powodu urody jak Absalom: od stóp jego nóg aż po czubek głowy nie było na nim skazy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 26, 'A gdy strzygł swoją głowę – a strzygł ją co roku, bo włosy mu ciążyły i dlatego ją strzygł – włosy jego głowy ważyły dwieście syklów według wagi królewskiej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 27, 'I Absalomowi urodzili się trzej synowie i jedna córka, która miała na imię Tamar. Była to kobieta o pięknym wyglądzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 28, 'I Absalom mieszkał w Jerozolimie dwa lata, a twarzy króla nie zobaczył.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 29, 'Absalom posłał więc po Joaba, aby ten go posłał do króla, lecz on nie chciał przyjść do niego. Potem posłał drugi raz, ale nie chciał przyjść.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 30, 'Wtedy powiedział do swoich sług: Patrzcie, pole Joaba jest obok mojego i ma tam jęczmień. Idźcie i podpalcie je. I słudzy Absaloma podpalili to pole.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 31, 'Potem Joab wstał, przyszedł do Absaloma do jego domu i zapytał go: Czemu twoi słudzy podpalili moje pole?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 32, 'Absalom odpowiedział Joabowi: Oto posłałem po ciebie, mówiąc: Przyjdź tutaj, a wyślę cię do króla, abyś zapytał: Po co przybyłem z Geszur? Lepiej mi było tam jeszcze zostać. Teraz pozwól mi więc zobaczyć twarz króla. A jeśli jest we mnie jakaś nieprawość, niech mnie zabije.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 33, 'Wtedy Joab przybył do króla i oznajmił mu to. Gdy wezwał Absaloma, ten przyszedł do króla i pokłonił się twarzą do ziemi przed królem. A król ucałował Absaloma.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 1, 'Potem Absalom sprawił sobie rydwany i konie, a także pięćdziesięciu mężczyzn, którzy przed nim biegali.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 2, 'Absalom wstawał wcześnie rano i stawał przy drodze do bramy. A każdego, kto miał sprawę i udawał się do króla na sąd, Absalom przyzywał do siebie i pytał: Z jakiego miasta jesteś? Ten odpowiadał: Twój sługa jest z jednego z pokoleń Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 3, 'Wtedy Absalom mówił mu: Patrz, twoja sprawa jest dobra i sprawiedliwa, ale u króla nie ma nikogo, kto by cię wysłuchał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 4, 'Potem Absalom mówił: O gdyby mnie ustanowiono sędzią w tej ziemi, aby mógł przychodzić do mnie każdy, kto ma sprawę lub spór, to wymierzałbym mu sprawiedliwość.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 5, 'A gdy ktoś się zbliżał i pokłonił mu się, wyciągał rękę, obejmował go i całował.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 6, 'Tak Absalom postępował z całym Izraelem, który przychodził do króla na sąd. I Absalom wykradał serca ludu Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 7, 'Po upływie czterdziestu lat Absalom powiedział do króla: Proszę, pozwól mi iść i wypełnić w Hebronie ślub, który złożyłem Panu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 8, 'Twój sługa bowiem złożył ślub, kiedy przebywał w Geszur w Syrii, mówiąc: Jeśli Pan naprawdę przywróci mnie do Jerozolimy, wtedy będę służyć Panu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 9, 'I król odpowiedział mu: Idź w pokoju. Wstał więc i udał się do Hebronu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 10, 'Lecz Absalom rozesłał szpiegów do wszystkich pokoleń Izraela, aby mówili: Gdy tylko usłyszycie dźwięk trąby, powiedzcie: Absalom króluje w Hebronie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 11, 'Z Absalomem wyruszyło dwustu zaproszonych mężczyzn z Jerozolimy, którzy szli w swojej prostocie, nie wiedząc o niczym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 12, 'Gdy Absalom składał ofiary, wezwał on także Achitofela, Gilonitę, doradcę Dawida, z jego miasta Gilo. I spisek się wzmagał, bo coraz więcej ludzi przystawało do Absaloma.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 13, 'Potem do Dawida przyszedł posłaniec, mówiąc: Serca ludzi Izraela zwróciły się do Absaloma.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 14, 'Wtedy Dawid powiedział do wszystkich swoich sług, którzy byli z nim w Jerozolimie: Wstańcie i uciekajmy, bo inaczej nie ujdziemy przed Absalomem. Spieszcie się z wymarszem, żeby czasem nie dopadł nas znienacka, nie sprowadził na nas nieszczęścia i nie wytępił miasta ostrzem miecza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 15, 'Słudzy króla powiedzieli do niego: Wszystko, co postanowi nasz pan, król, oto twoi słudzy uczynią.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 16, 'Król wyszedł więc pieszo, a z nim cały jego dom. Król zostawił jednak dziesięć kobiet, nałożnic, aby pilnowały domu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 17, 'A gdy król wyszedł pieszo wraz z całym ludem, zatrzymali się w pewnym odległym miejscu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 18, 'Wszyscy jego słudzy szli przy nim, a wszyscy Keretyci, wszyscy Peletyci, wszyscy Gittyci, w liczbie sześciuset mężczyzn, którzy przyszli za nim z Gat, przeszli przed królem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 19, 'Wtedy król zapytał Ittaja Gittytę: Czemu i ty idziesz z nami? Wróć do siebie i pozostań przy królu. Jesteś bowiem cudzoziemcem, a nawet wygnańcem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 20, 'Dopiero wczoraj przyszedłeś, a dziś miałbym cię zabrać, abyś się tułał z nami? Skoro sam nie wiem, dokąd idę, ty wróć i odprowadź swoich braci. Niech będą z tobą miłosierdzie i prawda.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 21, 'Ale Ittaj odpowiedział królowi: Jak żyje Pan i jak żyje mój pan, król, gdziekolwiek będzie mój pan, król, czy to na śmierć, czy na życie, tam też będzie twój sługa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 22, 'I Dawid powiedział do Ittaja: Idź więc i przejdź. Przeszedł więc Ittaj Gittyta i wszyscy jego mężczyźni, i wszystkie dzieci, które z nim były.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 23, 'I cała ziemia głośno płakała, cały lud zaś przeszedł. Potem sam król przeszedł przez potok Cedron i w ten sposób cały lud przeszedł, i skierował się na drogę ku pustyni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 24, 'A oto był z nim i Sadok, i wszyscy Lewici niosący arkę przymierza Boga. Postawili arkę Boga, a Abiatar wstąpił, aż cały lud wyszedł z miasta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 25, 'Potem król powiedział do Sadoka: Odnieś arkę Boga do miasta. Jeśli znajdę łaskę w oczach Pana, to przywróci mnie i pokaże mi ją oraz jej przybytek.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 26, 'Ale jeśli powie: Nie mam w tobie upodobania – oto jestem, niech mi uczyni, co jest dobre w jego oczach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 27, 'Król powiedział jeszcze do kapłana Sadoka: Czy nie jesteś widzącym? Wróć do miasta w pokoju wraz ze swoimi dwoma synami – Achimaasem, twoim synem, i Jonatanem, synem Abiatara.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 28, 'Oto będę czekał na równinach pustyni, dopóki nie nadejdzie od was słowo dające mi znać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 29, 'Sadok i Abiatar odnieśli więc arkę Boga do Jerozolimy i tam pozostali.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 30, 'Dawid zaś wstępował na Górę Oliwną, wstępował i płakał, a głowę miał zakrytą i szedł boso. Cały lud, który był z nim, każdy z nakrytą głową, wstępował i płakał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 31, 'Wtedy doniesiono Dawidowi: Achitofel jest wśród spiskowców z Absalomem. Dawid powiedział: O Panie, proszę, obróć w głupstwo radę Achitofela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 32, 'Kiedy Dawid dotarł na szczyt góry, gdzie oddał pokłon Bogu, oto wyszedł mu na spotkanie Chuszaj Arkita w rozdartej szacie i z prochem na głowie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 33, 'Dawid powiedział do niego: Jeśli pójdziesz ze mną, będziesz mi ciężarem;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 34, 'Lecz jeśli wrócisz do miasta i powiesz Absalomowi: Królu, będę twoim sługą. Jak byłem dotąd sługą twego ojca, tak teraz będę twoim sługą – wtedy na moją korzyść obrócisz wniwecz radę Achitofela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 35, 'Czyż nie ma tam z tobą kapłanów Sadoka i Abiatara? Cokolwiek więc usłyszysz z domu króla, doniesiesz o tym kapłanom Sadokowi i Abiatarowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 36, 'Oto są tam też z nimi ich dwaj synowie, Achimaas, syn Sadoka, i Jonatan, syn Abiatara. Przez nich przyślecie do mnie każde słowo, które usłyszycie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 37, 'Przybył więc Chuszaj, przyjaciel Dawida, do miasta, a Absalom także wjechał do Jerozolimy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 1, 'A gdy Dawid zszedł trochę ze szczytu góry, oto Siba, sługa Mefiboszeta, zaszedł mu drogę z parą osiodłanych osłów, na których było dwieście chlebów, sto pęczków rodzynek, sto świeżych owoców i bukłak wina.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 2, 'Wtedy król zapytał Sibę: Po co to? Siba odpowiedział: Osły są dla rodziny króla, by na nich jeździła, chleb i owoc na posiłek dla sług, a wino jest do picia dla znużonych na pustyni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 3, 'Zapytał król: A gdzie jest syn twego pana? Siba odpowiedział królowi: Został w Jerozolimie. Powiedział bowiem: Dziś dom Izraela przywróci mi królestwo mojego ojca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 4, 'Wtedy król powiedział do Siby: Oto twoje jest wszystko, co należało do Mefiboszeta. Siba pokłonił się i odpowiedział: Obym znalazł łaskę w twoich oczach, mój panie, królu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 5, 'Kiedy król Dawid przybył do Bachurim, oto wyszedł stamtąd człowiek z rodziny domu Saula imieniem Szimei, syn Gery. Ten wyszedł, a gdy szedł, przeklinał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 6, 'I rzucał kamieniami w Dawida i wszystkie sługi króla Dawida, chociaż cały lud i wszyscy wojownicy szli po jego prawej i lewej stronie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 7, 'I tak mówił Szimei, przeklinając: Wyjdź, wyjdź, krwawy człowieku, człowieku Beliala.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 8, 'Pan sprowadził na ciebie całą krew domu Saula, w miejsce którego zostałeś królem, i oddał Pan królestwo w ręce Absaloma, twego syna. A oto twoje zło spotkało ciebie, bo jesteś krwawym człowiekiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 9, 'Wtedy Abiszaj, syn Serui, powiedział do króla: Czemu ten zdechły pies przeklina mojego pana, króla? Pozwól, że pójdę i utnę mu głowę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 10, 'Ale król odpowiedział: Co ja mam z wami, synowie Serui? Niech przeklina, gdyż Pan mu kazał: Przeklinaj Dawida. Któż więc może powiedzieć: Czemu tak czynisz?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 11, 'Dawid powiedział jeszcze do Abiszaja i do wszystkich swoich sług: Oto mój syn, który wyszedł z mego wnętrza, nastaje na moje życie. Cóż dopiero ten Beniaminita? Zostawcie go, niech przeklina, bo Pan mu tak rozkazał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 12, 'Może Pan wejrzy na moje utrapienie i odpłaci mi dobrem za jego dzisiejsze przekleństwo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 13, 'Dawid i jego ludzie szli więc drogą, Szimei zaś szedł zboczem góry obok niego, a idąc, przeklinał, rzucał kamieniami w niego i miotał prochem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 14, 'I tak król i cały lud, który był z nim, przybyli znużeni i odpoczęli tam.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 15, 'Lecz Absalom i cały lud, mężczyźni Izraela, przyszli do Jerozolimy, a Achitofel był z nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 16, 'A gdy Chuszaj Arkita, przyjaciel Dawida, przyszedł do Absaloma, Chuszaj powiedział do Absaloma: Niech żyje król, niech żyje król!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 17, 'Wtedy Absalom zapytał Chuszaja: Taka to jest twoja miłość do twego przyjaciela? Czemu nie poszedłeś ze swoim przyjacielem?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 18, 'Chuszaj odpowiedział Absalomowi: Nie! Lecz kogo wybierze Pan, ten lud i wszyscy mężczyźni Izraela, do tego będę należał i z nim pozostanę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 19, 'Po drugie: Komu będę służył? Czy nie jego synowi? Jak służyłem twemu ojcu, tak będę i tobie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 20, 'Wtedy Absalom powiedział do Achitofela: Radźcie, co mam czynić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 21, 'Achitofel odpowiedział Absalomowi: Wejdź do nałożnic swego ojca, które zostawił, aby strzegły domu. A gdy cały Izrael usłyszy, że zostałeś znienawidzony przez swego ojca, wtedy wzmocnią się ręce wszystkich, którzy są z tobą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 22, 'Rozbili więc dla Absaloma namiot na dachu. I Absalom wszedł do nałożnic swego ojca na oczach całego Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 23, 'A rada Achitofela, której udzielał w tym czasie, była niczym rada od Boga. Taka była wszelka rada Achitofela, zarówno u Dawida, jak i u Absaloma.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 1, 'Potem Achitofel powiedział do Absaloma: Pozwól, że wybiorę dwanaście tysięcy mężczyzn i wyruszę tej nocy w pościg za Dawidem;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 2, 'I napadnę na niego, póki jest znużony i ręce ma słabe, i przerażę go. Ucieknie cały lud, który jest z nim, a ja zabiję samego króla.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 3, 'I przyprowadzę cały lud do ciebie, gdyż życie człowieka, na które nastajesz, jest jakby powrócili wszyscy do ciebie. Wtedy cały lud będzie miał pokój.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 4, 'Spodobało się to Absalomowi i wszystkim starszym Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 5, 'Absalom powiedział jednak: Zawołajcie szybko również Chuszaja Arkitę i posłuchajmy także, co on powie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 6, 'A gdy Chuszaj przyszedł do Absaloma, Absalom powiedział do niego: Tak powiedział Achitofel – czy mamy postąpić według jego rady? Jeśli nie, powiedz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 7, 'Wtedy Chuszaj odpowiedział Absalomowi: Rada, którą tym razem dał Achitofel, nie jest dobra.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 8, 'Chuszaj dodał: Znasz swego ojca i jego ludzi. Są dzielnymi wojownikami rozjuszonymi w sercu jak niedźwiedzica na polu, której zabrano młode. Ponadto twój ojciec jest wojownikiem i nie będzie nocował z ludem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 9, 'A teraz zapewne ukrywa się w jakiejś jaskini albo w jakimś innym miejscu. I jeśli ktoś z twoich padnie na początku, to wtedy każdy, kto o tym usłyszy, powie: Klęska spadła na lud, który szedł za Absalomem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 10, 'Wtedy nawet najdzielniejszy, którego serce jest jak serce lwa, struchleje. Cały Izrael bowiem wie, że twój ojciec jest dzielny, a wszyscy, którzy są z nim, są mężni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 11, 'Dlatego radzę, aby zgromadzić przy sobie cały Izrael, od Dan aż do Beer-Szeby, tak licznie, jak liczny jest piasek nad morzem, i abyś ty osobiście wyruszył na bitwę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 12, 'A tak napadniemy na niego w którymś miejscu, gdzie się znajduje, i spadniemy na niego, jak rosa spada na ziemię. I nie pozostanie ani on, ani żaden z tych wszystkich mężczyzn, którzy są z nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 13, 'A jeśli schronił się w którymś mieście, wtedy cały Izrael przyniesie do tego miasta powrozy, a ściągniemy je aż do potoku, tak że nie zostanie tam ani jeden kamyk.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 14, 'Wtedy Absalom i wszyscy mężczyźni Izraela powiedzieli: Lepsza jest rada Chuszaja Arkity niż rada Achitofela. Pan bowiem postanowił zniweczyć dobrą radę Achitofela, aby Pan sprowadził nieszczęście na Absaloma.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 15, 'I Chuszaj opowiedział kapłanom Sadokowi i Abiatarowi: Tak a tak radził Achitofel Absalomowi i starszym Izraela, lecz ja tak a tak radziłem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 16, 'Teraz więc szybko poślijcie i donieście Dawidowi: Nie zatrzymuj się tej nocy w równinach pustyni, lecz bezzwłocznie przepraw się, aby król nie został pochłonięty wraz z całym ludem, który jest z nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 17, 'A Jonatan i Achimaas stali przy Enrogel. I przyszła dziewczyna, i przekazała im wieści, a oni poszli i donieśli o tym królowi Dawidowi. Nie mogli się bowiem pokazywać, wchodząc do miasta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 18, 'Zobaczył ich jednak pewien chłopiec i doniósł Absalomowi. Lecz oni obaj szybko poszli i weszli do domu pewnego człowieka w Bachurim, który miał studnię na swoim podwórzu, i weszli do niej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 19, 'Potem kobieta wzięła płachtę, rozciągnęła ją z wierzchu na studni i rozsypała na niej ziarno. I niczego nie zauważono.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 20, 'Kiedy przyszli słudzy Absaloma do domu tej kobiety, zapytali: Gdzie są Achimaas i Jonatan? Kobieta odpowiedziała im: Przeszli przez rzekę. A gdy szukali ich i nie znaleźli, powrócili do Jerozolimy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 21, 'Po ich odejściu tamci wyszli ze studni i poszli powiadomić króla Dawida. Powiedzieli do niego: Wstańcie i przeprawcie się szybko przez wodę. Achitofel bowiem tak a tak radził przeciwko wam.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 22, 'Dawid wstał więc wraz z całym ludem, który z nim był, i przeprawili się przez Jordan. Do brzasku nie brakowało ani jednego człowieka, który by się nie przeprawił przez Jordan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 23, 'Kiedy Achitofel zobaczył, że nie postąpiono zgodnie z jego radą, osiodłał osła, wstał i wrócił do swego domu, do swego miasta. Potem wydał zarządzenia odnośnie do swego domu, powiesił się i umarł, a został pogrzebany w grobie swego ojca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 24, 'A Dawid już przybył do Machanaim, gdy Absalom przeprawił się przez Jordan, on i wszyscy mężczyźni Izraela z nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 25, 'I Absalom ustanowił Amasę dowódcą wojska w miejsce Joaba. Amasa był synem mężczyzny imieniem Jitra, Izraelity, który obcował z Abigail, córką Nachasza, siostrą Serui, matki Joaba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 26, 'A Izrael i Absalom rozbili obóz w ziemi Gilead.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 27, 'I kiedy Dawid przybył do Machanaim, Szobi, syn Nachasza z Rabby synów Ammona, i Makir, syn Ammiela z Lo-Debar, i Barzillaj, Gileadczyk z Rogelim;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 28, 'Przynieśli posłania, misy, naczynia gliniane, pszenicę, jęczmień, mąkę, ziarno prażone, bób, soczewicę, prażony groch;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 29, 'Miód, masło, owce i sery krowie. Przynieśli Dawidowi i ludowi, który był z nim, na pożywienie. Mówili bowiem: Lud jest głodny, znużony i spragniony na pustyni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 1, 'Wtedy Dawid policzył lud, który z nim był, i ustanowił nad nim dowódców nad tysiącami i dowódców nad setkami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 2, 'Potem Dawid posłał trzecią część ludu pod ręką Joaba, trzecią część pod ręką Abiszaja, syna Serui, brata Joaba, i trzecią część pod ręką Ittaja Gittyty. I król powiedział do ludu: Ja również wyruszę z wami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 3, 'Ale lud odpowiedział: Nie wyruszysz. Jeśli bowiem my uciekniemy, oni nie zwrócą na nas uwagi, i choćby połowa z nas poległa, też nie zwrócą na nas uwagi. Ty zaś jesteś dla nas jak dziesięć tysięcy. Teraz więc będzie lepiej, abyś mógł przyjść nam z pomocą z miasta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 4, 'Odpowiedział im król: Uczynię to, co wydaje się wam słuszne. Król stanął więc przy bramie, a cały lud wychodził setkami i tysiącami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 5, 'I król nakazał Joabowi, Abiszajowi i Ittajowi: Łagodnie traktujcie mi młodzieńca, Absaloma. A cały lud słyszał, jak król wydał wszystkim dowódcom rozkaz o Absalomie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 6, 'Lud wyruszył więc w pole przeciw Izraelowi i doszło do bitwy w lesie Efraima.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 7, 'Lud Izraela został tam pobity przez sługi Dawida i stała się wielka klęska tego dnia: poległo dwadzieścia tysięcy osób.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 8, 'Bitwa bowiem rozproszyła się na całą okolicę, a las pochłonął tego dnia więcej ludzi, niż pożarł miecz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 9, 'I Absalom natknął się na sługi Dawida. Absalom jechał na mule, a muł wbiegł pod gęste gałęzie wielkiego dębu. Wtedy jego głowa zaczepiła się o dąb i zawisł między niebem a ziemią. Lecz muł, który był pod nim, poszedł dalej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 10, 'Zobaczył to pewien człowiek i powiadomił Joaba: Oto widziałem Absaloma wiszącego na dębie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 11, 'Wtedy Joab powiedział do człowieka, który go o tym powiadomił: Jeśli widziałeś, to czemu go tam nie zabiłeś i nie zrzuciłeś na ziemię? Dałbym ci dziesięć srebrników i jeden pas.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 12, 'Człowiek ten odpowiedział Joabowi: Choćbym otrzymał na ręce tysiąc srebrników, nie podniósłbym ręki na syna króla. Słyszeliśmy bowiem, jak król nakazał tobie, Abiszajowi i Ittajowi: Zachowajcie wszyscy młodzieńca, Absaloma.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 13, 'Chyba że chciałbym postąpić zdradliwie przeciw własnej duszy, gdyż żadna sprawa nie jest tajona przed królem. Nawet ty sam byłbyś przeciwko mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 14, 'Wtedy Joab odpowiedział: Nie będę z tobą tracić czasu. Wziął więc do ręki trzy strzały i wbił je w serce Absaloma, gdy ten jeszcze wisiał żywy na dębie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 15, 'Potem dziesięciu młodzieńców, giermków Joaba, otoczyło Absaloma – bili go i zabili.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 16, 'Wtedy Joab zadął w trąbę i lud wrócił z pogoni za Izraelem, bo Joab zatrzymał lud.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 17, 'Wzięli zaś Absaloma, wrzucili go do głębokiego dołu w tym lesie i wznieśli nad nim wielki stos kamieni. I cały Izrael uciekł, każdy do swego namiotu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 18, 'A Absalom za swego życia postawił sobie pomnik w dolinie królewskiej, bo mówił: Nie mam syna, który by upamiętnił moje imię. Nazwał więc ten pomnik swoim imieniem i zwie się on Miejscem Absaloma aż do dziś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 19, 'Wtedy Achimaas, syn Sadoka, powiedział: Pozwól mi iść i zanieść królowi dobrą nowinę, że Pan wybawił go z ręki jego wrogów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 20, 'Lecz Joab mu odpowiedział: Nie byłbyś dziś zwiastunem dobrej nowiny, lecz zaniesiesz ją w innym dniu. Dziś natomiast nie zaniesiesz dobrej nowiny, gdyż zginął syn króla.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 21, 'Potem Joab odezwał się do Kuszego: Idź i opowiedz królowi, co widziałeś. Kusz pokłonił się Joabowi i pobiegł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 22, 'Achimaas, syn Sadoka, ponownie powiedział do Joaba: Niech się dzieje, co chce, pozwól, proszę, bym pobiegł za Kuszem. Joab zapytał: Dlaczego miałbyś biec, mój synu, skoro nie masz żadnej dobrej wieści do zwiastowania?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 23, 'Odpowiedział: Niech się dzieje, co chce, pobiegnę. Joab mu powiedział: Biegnij. Achimaas pobiegł więc prostszą drogą i wyprzedził Kuszego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 24, 'A Dawid siedział między dwiema bramami. I strażnik wszedł na dach bramy przy murze, a gdy podniósł oczy, zobaczył, że jakiś mężczyzna biegnie samotnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 25, 'Wtedy strażnik zawołał i powiadomił o tym króla. Król powiedział: Jeśli jest sam, to w jego ustach jest dobra nowina. A gdy ten szedł spiesznie i zbliżał się;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 26, 'Strażnik zobaczył drugiego biegnącego mężczyznę. I strażnik zawołał do odźwiernego: Oto biegnie samotnie drugi mężczyzna. Król powiedział: Ten również przynosi dobrą nowinę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 27, 'Wtedy strażnik powiedział: Wydaje mi się, że bieg pierwszego przypomina bieg Achimaasa, syna Sadoka. Król odpowiedział: To dobry człowiek, przychodzi z dobrą nowiną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 28, 'Achimaas zawołał do króla: Pokój! I pokłonił się królowi twarzą do ziemi, i powiedział: Niech będzie błogosławiony Pan, twój Bóg, który wydał tych ludzi, którzy podnieśli ręce przeciw memu panu, królowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 29, 'Król zapytał: Czy dobrze się ma młodzieniec Absalom? Achimaas odpowiedział: Widziałem wielkie zamieszanie, gdy Joab wysyłał sługę króla i mnie, twego sługę, ale nie wiem, co to było.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 30, 'Potem król powiedział: Odejdź na bok i stań tam. On więc odstąpił i stanął.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 31, 'Wtedy przybył Kusz i powiedział: Mam dobrą nowinę, mój panie, królu! Pan cię wybawił dzisiaj z ręki wszystkich, którzy powstali przeciw tobie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 32, 'Król zapytał Kuszego: Czy dobrze się ma młodzieniec Absalom? Odpowiedział Kusz: Oby wrogowie mego pana, króla, i wszyscy, którzy powstają przeciw tobie na nieszczęście, byli jak ten młodzieniec!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 33, 'Wtedy król zasmucił się, wstąpił do komnaty nad bramą i zapłakał. A idąc, tak mówił: Mój synu, Absalomie! Mój synu, mój synu, Absalomie! Obym ja umarł zamiast ciebie! Absalomie, mój synu, mój synu!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 1, 'I zawiadomiono Joaba: Oto król płacze i lamentuje z powodu Absaloma.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 2, 'Tak więc zwycięstwo tego dnia zamieniło się w żałobę dla całego ludu. Lud bowiem usłyszał w tym dniu, jak mówiono: Król ubolewa nad swoim synem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 3, 'I lud wkradał się tego dnia, gdy wchodzili do miasta, tak jak wkrada się lud, który jest okryty hańbą i ucieka z bitwy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 4, 'A król zasłonił swoją twarz i wołał donośnym głosem: Mój synu, Absalomie, Absalomie, mój synu, mój synu!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 5, 'Wtedy Joab wszedł do króla do domu i powiedział: Okryłeś dziś wstydem twarze wszystkich swoich sług, którzy dzisiaj ocalili twoje życie, życie twoich synów i córek oraz życie twoich żon i nałożnic.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 6, 'Miłujesz tych, którzy cię nienawidzą, a nienawidzisz tych, którzy cię miłują. Pokazałeś bowiem dziś, że dowódcy i słudzy są dla ciebie niczym. Gdyż dzisiaj poznałem, że gdyby Absalom przeżył, a my wszyscy dziś poleglibyśmy, to by ci się bardzo spodobało.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 7, 'Teraz wstań więc, wyjdź i przemów łagodnie do swoich sług. Przysięgam bowiem na Pana, że jeśli nie wyjdziesz, nikt nie pozostanie przy tobie tej nocy, a będzie to gorsze niż całe zło, jakie spotkało cię od twej młodości aż dotąd.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 8, 'Wtedy król wstał i zasiadł w bramie. Zawiadomiono cały lud: Oto król zasiadł w bramie. I cały lud stawił się przed królem. Izraelici zaś uciekli, każdy do swego namiotu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 9, 'I cały lud, we wszystkich pokoleniach, rozprawiał ze sobą: Król wyrwał nas z rąk naszych wrogów i on nas wyrwał z rąk Filistynów, a teraz uciekł z ziemi przed Absalomem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 10, 'Lecz Absalom, którego namaściliśmy nad sobą, zginął w bitwie. Czemu więc teraz nic nie mówicie o sprowadzeniu króla z powrotem?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 11, 'Posłał więc król Dawid do kapłanów Sadoka i Abiatara taką wiadomość: Powiedzcie starszym Judy: Dlaczego macie być ostatni przy sprowadzeniu króla z powrotem do jego domu? Słowa całego Izraela doszły bowiem do króla, do jego domu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 12, 'Jesteście moimi braćmi, moją kością i moim ciałem. Dlaczego więc macie być ostatnimi przy sprowadzeniu króla?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 13, 'A do Amasy powiedzcie: Czy nie jesteś moją kością i moim ciałem? Niech Bóg mi to uczyni i tamto dorzuci, jeśli nie będziesz dowódcą wojska przede mną po wszystkie dni na miejsce Joaba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 14, 'W ten sposób ujął serce wszystkich ludzi Judy jakby jednego człowieka, dlatego posłali do króla wiadomość: Wracaj razem ze wszystkimi swoimi sługami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 15, 'Król wrócił więc i przybył nad Jordan. A lud Judy wyruszył do Gilgal, aby wyjść królowi na spotkanie i przeprowadzić króla przez Jordan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 16, 'Pospieszył się także Szimei, syn Gery, Beniaminita z Bachurim, i wyruszył z ludem Judy na spotkanie króla Dawida.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 17, 'A było z nim tysiąc mężczyzn z Beniamina oraz Siba, sługa domu Saula, wraz ze swoimi piętnastoma synami i dwudziestoma sługami. I przeprawili się przez Jordan do króla.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 18, 'Przepłynęła też tratwa, aby przewieziono dom króla i aby mogła służyć do czegokolwiek, co wydaje mu się słuszne. A Szimei, syn Gery, upadł przed królem, gdy się przeprawił przez Jordan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 19, 'I powiedział do króla: Niech mój pan nie poczyta mi nieprawości i niech nie wspomina na to, co lekkomyślnie uczynił twój sługa tego dnia, gdy mój pan, król, wychodził z Jerozolimy, i nie bierze sobie tego do serca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 20, 'Twój sługa wie bowiem, że zgrzeszył. A oto dziś przyszedłem pierwszy z całego domu Józefa, aby wyjść na spotkanie mojego pana, króla.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 21, 'Wtedy odezwał się Abiszaj, syn Serui, i zapytał: Czy Szimei nie powinien zostać zabity za to, że przeklął pomazańca Pana?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 22, 'Ale Dawid odpowiedział: Co ja mam z wami, synowie Serui, że dziś jesteście dla mnie przeciwnikami? Czy dziś ktoś powinien ponieść śmierć w Izraelu? Czyż nie wiem, że ja dzisiaj zostałem królem nad Izraelem?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 23, 'I król powiedział do Szimejego: Nie umrzesz. I król mu to przysiągł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 24, 'Także Mefiboszet, syn Saula, wyszedł królowi na spotkanie. Nie mył on nóg ani nie strzygł brody, ani nie prał swoich szat od dnia odejścia króla aż do dnia, w którym wrócił w pokoju.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 25, 'I kiedy przybył na spotkanie króla w Jerozolimie, zapytał go król: Dlaczego nie poszedłeś ze mną, Mefiboszecie?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 26, 'A on mu odpowiedział: Mój panie, królu, mój sługa mnie oszukał. Twój sługa bowiem powiedział: Osiodłam sobie osła, żeby na nim pojechać z królem, gdyż twój sługa jest kulawy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 27, 'On zaś oczernił twego sługę przed moim panem, królem. Lecz mój pan, król, jest jak anioł Boga. Uczyń więc, co jest dobre w twoich oczach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 28, 'Wszyscy bowiem z domu mego ojca byliśmy godni śmierci przed moim panem, królem. A jednak ty posadziłeś twego sługę między tymi, którzy jadają u twego stołu. Jakie mam więc prawo skarżenia się jeszcze przed królem?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 29, 'Wtedy król powiedział mu: Po co jeszcze mówisz o swoich sprawach? Już powiedziałem: Ty i Siba podzielcie się polem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 30, 'A Mefiboszet powiedział do króla: Niech nawet weźmie wszystko, skoro mój pan, król, wrócił w pokoju do swego domu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 31, 'Również Barzillaj Gileadczyk przybył z Rogelim, przeprawił się z królem przez Jordan, aby go odprowadzić za Jordan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 32, 'A Barzillaj był bardzo stary, miał osiemdziesiąt lat. On to zaopatrywał króla, dopóki przebywał w Machanaim, bo był bardzo bogatym człowiekiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 33, 'Król powiedział do Barzillaja: Chodź ze mną, a będę cię utrzymywał u siebie w Jerozolimie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 34, 'Lecz Barzillaj odpowiedział królowi: Ile lat życia mi pozostało, żebym miał iść z królem do Jerozolimy?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 35, 'Mam dzisiaj osiemdziesiąt lat. Czy mogę rozróżnić między dobrem a złem? Czy twój sługa poczuje smak tego, co je albo pije? Czy mogę jeszcze słuchać głosu śpiewaków i śpiewaczek? Po co więc twój sługa miałby być jeszcze ciężarem dla swego pana, króla?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 36, 'Twój sługa pójdzie jeszcze trochę za Jordan z królem. Czemu król miałby mi dawać taką nagrodę?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 37, 'Pozwól, proszę, twemu słudze powrócić, abym umarł w swoim mieście, przy grobie swego ojca i swej matki. Lecz oto twój sługa Kimham, niech on pójdzie z moim panem, królem. Uczyń mu to, co jest dobre w twoich oczach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 38, 'Król odpowiedział: Niech idzie ze mną Kimham, a ja mu uczynię to, co będzie dobre w twoich oczach. A czegokolwiek będziesz sobie życzył ode mnie, to uczynię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 39, 'I cały lud przeprawił się przez Jordan. Gdy król przeprawił się, pocałował król Barzillaja i błogosławił mu. Ten zaś wrócił do swego miejsca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 40, 'Potem król udał się do Gilgal, poszedł też z nim Kimham. Cały lud Judy towarzyszył królowi, a także połowa ludu Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 41, 'A oto wszyscy ludzie Izraela przyszli do króla i zapytali go: Czemu nasi bracia, ludzie z Judy, wykradli cię i przeprowadzili króla i jego dom przez Jordan wraz ze wszystkimi ludźmi Dawida?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 42, 'I wszyscy ludzie Judy odpowiedzieli ludziom Izraela: Ponieważ król jest z nami spokrewniony. A dlaczego gniewacie się z tego powodu? Czy król za to dawał nam jeść albo czy obdarował nas jakimś darem?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 43, 'Wtedy ludzie Izraela odpowiedzieli ludziom Judy: Mamy w królu dziesięć części, toteż mamy większe prawo do Dawida niż wy. Dlaczego nas lekceważyliście? Czy nie my pierwsi mówiliśmy o sprowadzeniu z powrotem swego króla? Ale słowa ludzi Judy były surowsze niż słowa ludzi Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 1, 'I znalazł się tam przypadkiem człowiek Beliala imieniem Szeba, syn Bikriego, Beniaminita. Ten zadął w trąbę i powiedział: Nie mamy działu w Dawidzie ani nie mamy dziedzictwa w synu Jessego. Każdy do swojego namiotu, o Izraelu!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 2, 'Odstąpili więc od Dawida wszyscy ludzie Izraela i poszli za Szebą, synem Bikriego. Ale ludzie Judy, od Jordanu aż do Jerozolimy, trzymali się swego króla.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 3, 'I Dawid przyszedł do swego domu w Jerozolimie. Wtedy król wziął dziesięć kobiet, nałożnic, które pozostawił, aby strzegły domu, umieścił je w strzeżonym domu i utrzymywał, ale nie obcował z nimi. Pozostały one zamknięte aż do dnia swej śmierci, jakby we wdowieństwie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 4, 'Potem król powiedział do Amasy: Zbierz mi mężczyzn Judy w ciągu trzech dni, ty także się staw.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 5, 'Poszedł więc Amasa, by zebrać lud Judy. Lecz przekroczył termin, który mu wyznaczył.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 6, 'I Dawid powiedział do Abiszaja: Teraz Szeba, syn Bikriego, uczyni nam gorzej niż Absalom. Weź więc sługi twego pana i ścigaj go, by nie znalazł sobie obronnych miast i nie wymknął się nam.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 7, 'Wtedy wyszli z nim ludzie Joaba oraz Keretyci, Peletyci i wszyscy dzielni wojownicy. Wyruszyli z Jerozolimy w pościg za Szebą, synem Bikriego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 8, 'A gdy byli przy wielkim kamieniu, który jest w Gibeonie, Amasa wyszedł im naprzeciw. A Joab miał na sobie przepasaną szatę, a na niej pas z mieczem w pochwie przypasany do bioder. Gdy on się zbliżał, miecz wypadł mu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 9, 'I Joab zapytał Amasę: Czy masz się dobrze, mój bracie? I Joab ujął Amasę prawą ręką za brodę, jakby miał go pocałować.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 10, 'Lecz Amasa nie zwrócił uwagi na miecz, który był w ręce Joaba. Ten uderzył go nim pod piąte żebro i wylał jego wnętrzności na ziemię bez zadawania drugiego ciosu, i Amasa umarł. A Joab i jego brat Abiszaj puścili się w pogoń za Szebą, synem Bikriego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 11, 'Wtedy stanął przy nim jeden ze sług Joaba i powiedział: Ktokolwiek sprzyja Joabowi i ktokolwiek jest za Dawidem, niech idzie za Joabem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 12, 'Tymczasem Amasa tarzał się we krwi na środku drogi. A gdy ten człowiek zobaczył, że cały lud zatrzymuje się, usunął Amasę z drogi na pole i zarzucił na niego szatę. Zauważył bowiem, że każdy, kto obok niego przechodzi, zatrzymuje się.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 13, 'A gdy usunięto go z drogi, wszyscy szli za Joabem, by ścigać Szebę, syna Bikriego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 14, 'Ten przeszedł przez wszystkie pokolenia Izraela aż do Abel i Bet-Maaka, a wszyscy Berici zebrali się i poszli za nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 15, 'A kiedy tam nadciągnęli, oblegli go w Abel Bet-Maaka i usypali wał przeciw miastu, tak że stali przed murem, i cały lud, który był z Joabem, uderzał, by zburzyć mur.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 16, 'Wtedy pewna mądra kobieta zawołała z miasta: Słuchajcie, słuchajcie! Powiedzcie, proszę, do Joaba: Zbliż się tutaj, a porozmawiam z tobą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 17, 'Gdy zbliżył się do niej, kobieta zapytała: Czy ty jesteś Joab? Odpowiedział: Jestem. Wtedy powiedziała: Słuchaj słów twojej służącej. Odpowiedział: Słucham.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 18, 'Ona mówiła dalej: W dawnych czasach mówiono: Koniecznie należy radzić się w Abelu – i tak sprawa się zakończyła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 19, 'Ja jestem jednym ze spokojnych i wiernych w Izraelu, a ty chcesz zniszczyć miasto i matkę w Izraelu. Dlaczego chcesz zburzyć dziedzictwo Pana?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 20, 'Joab odpowiedział jej: Nie daj, nie daj Boże, abym miał zburzyć albo zniszczyć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 21, 'Nie tak ma się sprawa. Tylko pewien człowiek z góry Efraim imieniem Szeba, syn Bikriego, podniósł rękę przeciw królowi Dawidowi. Wydajcie jego samego, a odstąpię od miasta. Kobieta odpowiedziała Joabowi: Oto jego głowa zostanie ci rzucona przez mur.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 22, 'Kobieta poszła więc do całego ludu w swojej mądrości. Ścięto głowę Szebie, synowi Bikriego, i rzucono ją do Joaba. Ten zaś zadął w trąbę i wszyscy rozeszli się spod miasta, każdy do swojego namiotu. A Joab wrócił do króla do Jerozolimy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 23, 'I Joab był dowódcą całego wojska Izraela. A Benajasz, syn Jehojady, dowódcą Keretytów i Peletytów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 24, 'Adoram był poborcą daniny, a Jehoszafat, syn Ahiluda, kronikarzem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 25, 'Szewa – pisarzem, a Sadok i Abiatar byli kapłanami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 26, 'Również Ira Jairyta był naczelnym dostojnikiem u Dawida.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 1, 'I za czasów Dawida panował głód przez trzy lata, rok po roku. Dawid szukał więc oblicza Pana, a Pan odpowiedział: To z powodu Saula i jego krwawego domu, ponieważ wymordował Gibeonitów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 2, 'Wtedy król wezwał Gibeonitów i przemówił do nich. A Gibeonici nie wywodzili się z synów Izraela, ale z resztki Amorytów. I chociaż synowie Izraela przysięgli im, Saul jednak usiłował wytępić ich w swej gorliwości względem synów Izraela i Judy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 3, 'Dawid zapytał więc Gibeonitów: Cóż mam dla was uczynić? A czym was ułagodzić, abyście błogosławili dziedzictwo Pana?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 4, 'I odpowiedzieli mu Gibeonici: Nie chodzi nam o srebro ani o złoto od Saula i jego domu, ani o to, żeby zabito kogoś w Izraelu. A on odpowiedział: Cokolwiek powiecie, to dla was uczynię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 5, 'Oni powiedzieli do króla: Co do mężczyzny, który nas wygubił i zmierzał do tego, aby nas wytępić, żeby nikt z nas nie pozostał we wszystkich granicach Izraela;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 6, 'Wydajcie nam siedmiu z jego synów, a my powiesimy ich przed Panem w Gibea Saula, który był wybrańcem Pana. Król odpowiedział: Wydam ich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 7, 'Lecz król oszczędził Mefiboszeta, syna Jonatana, syna Saula, z powodu przysięgi Pana, która była między nimi, między Dawidem a Jonatanem, synem Saula.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 8, 'Ale król wziął dwóch synów Rispy, córki Aji, których urodziła Saulowi, Armoniego i Mefiboszeta, i pięciu synów siostry Mikal, córki Saula, których urodziła Adrielowi, synowi Barzillaja z Mecholi;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 9, 'I wydał ich w ręce Gibeonitów, a oni powiesili ich na górze przed Panem. Razem umarło ich siedmiu, zostali zabici w pierwsze dni żniw, na początku żniw jęczmienia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 10, 'Wtedy Rispa, córka Aji, wzięła wór i rozciągnęła go na skale, na początku żniw, aż do czasu, gdy spadł na nich deszcz z nieba, i nie pozwalała, aby ptactwo powietrzne zbliżało się do nich za dnia, ani zwierzęta polne – nocą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 11, 'Potem doniesiono Dawidowi o tym, co uczyniła Rispa, córka Aji, nałożnica Saula.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 12, 'Dawid poszedł więc i wziął kości Saula i kości Jonatana, jego syna, od starszych Jabesz-Gilead, którzy ukradli je z placu Bet-Szan, gdzie ich zawiesili Filistyni w dniu zabicia Saula przez Filistynów w Gilboa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 13, 'Wziął więc stamtąd kości Saula i kości Jonatana, jego syna; zebrano też kości powieszonych;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 14, 'I pogrzebali kości Saula i Jonatana, jego syna, w ziemi Beniamina w Sela, w grobie Kisza, jego ojca. Uczynili wszystko, co król nakazał. Potem Bóg dał się ubłagać co do ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 15, 'Później znowu doszło do wojny między Filistynami a Izraelem. I Dawid wyruszył wraz ze swymi sługami i walczyli z Filistynami, a Dawid był znużony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 16, 'Wtedy Iszbibenob, który wywodził się z synów pewnego olbrzyma, a którego włócznia ważyła trzysta syklów brązu i który miał przepasany nowy miecz, postanowił, że zabije Dawida.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 17, 'Lecz Abiszaj, syn Serui, przyszedł mu z pomocą, uderzył Filistyna i zabił go. Wtedy ludzie Dawida przysięgli mu: Nie będziesz już wyruszał z nami do bitwy, abyś nie zgasił pochodni Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 18, 'Potem znowu była bitwa z Filistynami w Gob. Wtedy Sibbekaj Chuszatyta zabił Safa, który pochodził z synów tego olbrzyma.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 19, 'Była też jeszcze inna wojna z Filistynami w Gob, podczas której Elchanan, syn Jaara Oregima z Betlejem, zabił brata Goliata Gittyty, którego drzewce włóczni były jak wał tkacki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 20, 'Ponadto toczyła się jeszcze wojna w Gat, gdzie był człowiek wysokiego wzrostu, mający po sześć palców u rąk i po sześć palców u nóg, razem dwadzieścia cztery. On także był synem tego olbrzyma.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 21, 'Gdy urągał on Izraelowi, zabił go Jonatan, syn Szimei, brata Dawida.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 22, 'Ci czterej byli synami tego olbrzyma z Gat, a polegli z ręki Dawida i z ręki jego sług.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 1, 'Dawid wypowiedział Panu słowa tej pieśni w dniu, gdy Pan go wybawił z rąk wszystkich jego wrogów i z ręki Saula;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 2, 'Powiedział: Pan jest moją skałą, moją twierdzą i moim wybawicielem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 3, 'Bóg moją opoką, której będę ufał, moją tarczą i rogiem mojego zbawienia, moją wieżą i moją ucieczką, moim zbawicielem; wybawiasz mnie od przemocy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 4, 'Wzywałem Pana, który jest godny chwały, a będę wybawiony od moich wrogów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 5, 'Ogarnęły mnie bowiem boleści śmierci i zatrwożyły mnie potoki bezbożnych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 6, 'Boleści piekła mnie oplotły, pochwyciły mnie sidła śmierci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 7, 'W moim utrapieniu wzywałem Pana i wołałem do mojego Boga. Ze swojej świątyni usłyszał mój głos, a moje wołanie dotarło do jego uszu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 8, 'Wtedy ziemia poruszyła się i zadrżała, a posady nieba zatrzęsły się i zachwiały od jego gniewu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 9, 'Z jego nozdrzy unosił się dym, z jego ust buchnął ogień trawiący, węgle zapaliły się od niego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 10, 'Nachylił niebiosa i zstąpił, a ciemność była pod jego stopami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 11, 'Dosiadł cherubina i latał, i ukazał się na skrzydłach wiatru.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 12, 'Z ciemności uczynił wokół siebie namiot, z ciemnych wód i z gęstych obłoków nieba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 13, 'Od jego blasku rozpaliły się węgle ogniste.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 14, 'Zagrzmiał Pan z nieba, Najwyższy wydał swój głos.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 15, 'Wypuścił strzały i rozproszył ich; błyskawicę – i ich rozgromił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 16, 'I ukazały się głębiny morza, i odsłoniły się fundamenty świata od upomnienia Pana, od podmuchu tchnienia jego nozdrzy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 17, 'Posłał z wysoka, chwycił mnie, wyciągnął z wielkich wód.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 18, 'Ocalił mnie od mojego potężnego wroga i od tych, którzy mnie nienawidzą, choć byli ode mnie mocniejsi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 19, 'Zaskoczyli mnie w dniu mego utrapienia, lecz Pan był moją podporą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 20, 'Wyprowadził mnie na miejsce przestronne, wybawił mnie, bo mnie sobie upodobał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 21, 'Nagrodził mnie Pan według mojej sprawiedliwości, oddał mi według czystości moich rąk.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 22, 'Strzegłem bowiem dróg Pana i nie odstąpiłem niegodziwie od mojego Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 23, 'Bo miałem przed oczyma wszystkie jego nakazy i od jego praw się nie odwróciłem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 24, 'Byłem wobec niego nienaganny i wystrzegałem się swojej nieprawości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 25, 'Dlatego oddał mi Pan według mojej sprawiedliwości, według mojej czystości przed jego oczyma.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 26, 'Ty z miłosiernym miłosiernie się obejdziesz, a z człowiekiem nienagannym postąpisz nienagannie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 27, 'Wobec czystego okażesz się czysty, a wobec przewrotnego postąpisz przewrotnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 28, 'Lecz wybawiasz lud strapiony, a twoje oczy są na wyniosłych, by ich poniżać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 29, 'Ty bowiem jesteś moją pochodnią, o Panie; Pan rozjaśni moje ciemności.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 30, 'Bo z tobą przebiłem się przez wojsko, z moim Bogiem przeskoczyłem mur.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 31, 'Droga Boga jest doskonała, słowo Pana w ogniu wypróbowane. Tarczą jest dla wszystkich, którzy mu ufają.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 32, 'Bo któż jest Bogiem oprócz Pana? Któż skałą oprócz naszego Boga?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 33, 'Bóg jest moją siłą i mocą, on czyni doskonałą moją drogę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 34, 'Moje nogi czyni jak u łani i stawia mnie na wyżynach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 35, 'Ćwiczy moje ręce do walki, tak że mogę kruszyć spiżowy łuk swymi ramionami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 36, 'Dałeś mi też tarczę swego zbawienia, a twoja dobrotliwość uczyniła mnie wielkim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 37, 'Rozszerzyłeś ścieżkę dla mych kroków, tak że moje stopy się nie zachwiały.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 38, 'Ścigałem moich wrogów i wytraciłem ich, nie zawróciłem, aż ich nie wyniszczyłem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 39, 'I wyniszczyłem ich, i powaliłem, tak że nie mogli powstać, upadli pod moje stopy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 40, 'Przepasałeś mnie mocą do walki, powaliłeś pod moje stopy moich przeciwników.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 41, 'Zmuszałeś moich wrogów do ucieczki, abym wykorzenił tych, którzy mnie nienawidzą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 42, 'Patrzyli, lecz nie było nikogo, kto by ich wybawił; spoglądali na Pana, lecz ich nie wysłuchał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 43, 'Starłem ich jak proch ziemi, zdeptałem ich jak błoto na ulicach, rozrzuciłem ich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 44, 'Ty wyzwoliłeś mnie od kłótni ludzkich, zachowałeś mnie, abym był głową narodów. Będzie mi służył lud, którego nie znałem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 45, 'Cudzoziemcy będą udawać uległość. Jak tylko usłyszą, będą mi posłuszni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 46, 'Cudzoziemcy zmarnieją i będą drżeć w swoich warowniach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 47, 'Pan żyje, niech będzie błogosławiona moja skała, niech będzie wywyższony Bóg, skała mojego zbawienia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 48, 'Bóg dokonuje za mnie zemsty i poddaje mi narody;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 49, 'Wyprowadza mnie spośród moich wrogów. Ty wywyższyłeś mnie ponad moich przeciwników, ocaliłeś mnie od gwałtownika.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 50, 'Dlatego będę cię, Panie, sławił wśród narodów i będę śpiewał twojemu imieniu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 51, 'On jest wieżą zbawienia dla swego króla i na wieki okazuje miłosierdzie swemu pomazańcowi Dawidowi i jego potomstwu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 1, 'Oto ostatnie słowa Dawida. Dawid, syn Jessego, mężczyzna, który został wywyższony, pomazaniec Boga Jakuba i miły psalmista Izraela, powiedział:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 2, 'Duch Pana mówił przeze mnie, a jego słowo jest na moim języku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 3, 'Bóg Izraela przemówił, Skała Izraela mówiła do mnie: Ten, który panuje nad ludem, ma być sprawiedliwy, ma panować w bojaźni Bożej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 4, 'Będzie jak światło poranka, gdy słońce wschodzi, jak poranek bez chmur i jak od jego blasku po deszczu wyrasta ruń z ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 5, 'I choć mój dom nie jest taki przed Bogiem, to jednak zawarł ze mną wieczne przymierze, utwierdzone we wszystkim i pewne. A to jest całe moje zbawienie i całe moje pragnienie, chociaż on jeszcze nie daje temu wzrostu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 6, 'Lecz wszyscy synowie Beliala będą jak ciernie wyrzucone, których się ręką nie bierze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 7, 'Ten zaś, kto chce ich dotknąć, musi uzbroić się w żelazo i drzewce włóczni. Zostaną doszczętnie spaleni ogniem na miejscu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 8, 'Oto są imiona dzielnych wojowników, których miał Dawid: Tachmonita, który zajął główne miejsce wśród trzech dowódców, to właśnie Adino Esnita. To on wywijał swoją włócznią przeciw ośmiuset i pokonał ich za jednym razem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 9, 'Po nim był Eleazar, syn Dody, Achochita, jeden z trzech dzielnych wojowników, którzy byli z Dawidem, kiedy urągali Filistynom, którzy zebrali się do bitwy, a Izraelici wycofali się;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 10, 'To on powstał i bił się z Filistynami, aż mu ręka omdlała i przywarła do miecza. Tego dnia Pan sprawił wielkie zwycięstwo. Lud zaś zawrócił tylko po to, żeby zabrać łupy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 11, 'A po nim był Szamma, syn Agego, Hararyta. Gdy bowiem Filistyni zebrali się w oddział, gdzie była działka pola pełnego soczewicy, a lud uciekł przed Filistynami;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 12, 'Wtedy on stanął w środku tej działki, obronił ją i pobił Filistynów. A Pan sprawił wielkie zwycięstwo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 13, 'Ci trzej spośród trzydziestu dowódców zeszli się i przyszli do Dawida w czasie żniw do jaskini Adullam, podczas gdy oddział Filistynów rozbił obóz w dolinie Refaim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 14, 'A Dawid w tym czasie przebywał w miejscu obronnym, a załoga filistyńska była wtedy w Betlejem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 15, 'Wówczas Dawid poczuł pragnienie i powiedział: Oby ktoś dał mi się napić wody ze studni betlejemskiej, która jest przy bramie!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 16, 'Wtedy ci trzej waleczni wojownicy przebili się przez obóz Filistynów i zaczerpnęli wody ze studni betlejemskiej, która była przy bramie. Zabrali ją i przynieśli do Dawida. On jednak nie chciał jej pić, lecz wylał ją dla Pana;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 17, 'I powiedział: Niech Pan mnie strzeże od tego, abym miał to uczynić. Czyż to nie krew mężczyzn, którzy poszli z narażeniem życia? I nie chciał jej pić. Tego dokonali ci trzej waleczni wojownicy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 18, 'Abiszaj, brat Joaba, syn Serui, był na czele trzech. On to podniósł swoją włócznię przeciw trzystu i pobił ich, i był sławny wśród tych trzech.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 19, 'Z tych trzech był najsławniejszy i stał się ich dowódcą. Nie dorównał jednak tamtym trzem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 20, 'Benajasz, syn Jehojady, syn dzielnego męża z Kabseel, który dokonał wielu czynów, to on zabił dwóch wojowników z Moabu. On też w śnieżnym dniu zszedł do jamy i zabił lwa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 21, 'Zabił również Egipcjanina, człowieka godnego podziwu. Egipcjanin ten miał w ręku włócznię. On zaś poszedł do niego z kijem, wyrwał włócznię z ręki Egipcjanina i zabił go jego własną włócznią.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 22, 'Tego dokonał Benajasz, syn Jehojady, był najsławniejszy wśród tych trzech dzielnych wojowników.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 23, 'Był sławniejszy niż trzydziestu, nie dorównał jednak owym trzem. I Dawid postawił go nad swoją strażą przyboczną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 24, 'Asahel, brat Joaba, był wśród trzydziestu. A są nimi: Elchanan, syn Dodo z Betlejem;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 25, 'Szamma Charodczyk, Elika Charodczyk;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 26, 'Cheles Peletyta, Ira, syn Ikkesza, Tekoitczyk;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 27, 'Abiezer Anatotczyk, Mebunaj Chuszatyta;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 28, 'Salmon Achochita, Maharaj Netofatyta;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 29, 'Cheleb, syn Baany, Netofatyta, Itaj, syn Ribaja, z Gibea synów Beniamina;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 30, 'Benajasz Piratończyk, Hiddaj z potoków Gaasz;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 31, 'Abi-Albon Arbatczyk, Azmawet Barchumitczyk;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 32, 'Eliachba Szaalbończyk, Jonatan, z synów Jaszena;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 33, 'Szamma Hararyta, Achiam, syn Szarara, Hararyta;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 34, 'Elifelet, syn Achasbaja, syna Maachatyty, Eliam, syn Achitofela Gilonity;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 35, 'Chesraj Karmelita, Paaraj Arbitczyk;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 36, 'Jigal, syn Natana z Soby, Bani Gadytczyk;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 37, 'Selek Ammonita, Nacharaj Beerotczyk, giermek Joaba, syna Serui;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 38, 'Ira Jitryta, Gareb Jitryta;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 39, 'Uriasz Chetyta. Razem wszystkich trzydziestu siedmiu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 1, 'Wtedy znowu zapłonął gniew Pana przeciw Izraelowi, gdy szatan pobudził Dawida przeciwko nim, mówiąc: Idź, policz Izraela i Judę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 2, 'Król powiedział do Joaba, dowódcy wojska, który był z nim: Przebiegnij teraz wszystkie pokolenia Izraela od Dan aż do Beer-Szeby i policzcie lud, abym poznał jego liczbę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 3, 'Lecz Joab odpowiedział królowi: Niech Pan, twój Bóg, doda do ludu sto razy tyle, ile ich jest, i niech oczy mojego pana, króla, to zobaczą. Lecz czemu mój pan, król, żąda tego?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 4, 'Słowo króla jednak przemogło Joaba i dowódców wojska. Joab i dowódcy wojska wyszli więc od króla, aby policzyć lud Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 5, 'Przeprawili się przez Jordan i rozbili obóz przy Aroerze, po prawej stronie miasta, które leży w środku rzeki Gad i przy Jazer.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 6, 'Następnie przybyli do Gileadu i do ziemi Dolnej Hadsy, a stamtąd przybyli do Dan-Jaan, potem skręcili do Sydonu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 7, 'Później przyszli do twierdzy Tyru i do wszystkich miast Chiwwitów i Kananejczyków, skąd udali się na południe Judy aż do Beer-Szeby.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 8, 'A gdy obeszli całą ziemię, przybyli do Jerozolimy po upływie dziewięciu miesięcy i dwudziestu dni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 9, 'I Joab podał królowi liczbę spisanej ludności. A w Izraelu było osiemset tysięcy dzielnych wojowników dobywających miecz, mężczyzn Judy było zaś pięćset tysięcy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 10, 'A serce Dawida zadrżało po tym, jak obliczył lud. I Dawid powiedział do Pana: Bardzo zgrzeszyłem, że to uczyniłem. Lecz teraz, Panie, proszę, zgładź nieprawość swego sługi, gdyż bardzo głupio postąpiłem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 11, 'A gdy Dawid wstał rano, oto słowo Pana doszło do proroka Gada, widzącego Dawida:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 12, 'Idź i powiedz Dawidowi: Tak mówi Pan: Trzy rzeczy daję ci do wyboru, wybierz jedną z nich, abym ci ją uczynił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 13, 'Przyszedł więc Gad do Dawida, oznajmił mu i powiedział: Czy ma nastać siedem lat głodu w twojej ziemi, czy chcesz uciekać przez trzy miesiące przed swoimi wrogami, którzy będą cię ścigać, czy też w twojej ziemi ma być przez trzy dni zaraza? Zastanów się teraz i rozważ, co mam odpowiedzieć temu, który mnie posłał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 14, 'Dawid odpowiedział Gadowi: Jestem w udręce. Wpadnijmy raczej w rękę Pana, gdyż wielkie jest jego miłosierdzie. Niech nie wpadnę w rękę człowieka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 15, 'Pan zesłał więc na Izraela zarazę od rana do ustalonego czasu. Umarło z ludu od Dan do Beer-Szeby siedemdziesiąt tysięcy mężczyzn.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 16, 'A gdy Anioł wyciągnął rękę nad Jerozolimą, aby ją zniszczyć, wtedy Pan użalił się nad tym nieszczęściem i powiedział do Anioła, który niszczył lud: Dosyć, powstrzymaj rękę. A Anioł Pana był przy klepisku Arawny Jebusyty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 17, 'I gdy Dawid ujrzał Anioła karzącego lud, powiedział do Pana: Oto ja zgrzeszyłem, ja źle postąpiłem. Lecz te owce cóż uczyniły? Proszę, niech twoja ręka obróci się na mnie i na dom mojego ojca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 18, 'Tego dnia przyszedł Gad do Dawida i powiedział mu: Idź, zbuduj Panu ołtarz na klepisku Arawny Jebusyty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 19, 'Dawid poszedł więc zgodnie ze słowem Gada, jak to Pan rozkazał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 20, 'Kiedy Arawna spojrzał, zobaczył króla i jego sługi zbliżających się do niego. I Arawna wyszedł, i pokłonił się królowi twarzą do ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 21, 'Wtedy Arawna zapytał: Dlaczego mój pan, król, przyszedł do swego sługi? Dawid odpowiedział: Aby kupić od ciebie to klepisko i na nim zbudować Panu ołtarz, żeby plaga została powstrzymana wśród ludu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 22, 'Arawna powiedział do Dawida: Niech mój pan, król, weźmie i złoży to, co uzna za słuszne. Oto woły na całopalenie, a sprzęty młocarskie i jarzma wołów na drwa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 23, 'To wszystko jako król dawał Arawna królowi. I Arawna powiedział do króla: Niech Pan, twój Bóg, ma w tobie upodobanie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 24, 'Lecz król powiedział do Arawny: Nie, ale koniecznie kupię to od ciebie za pieniądze. Nie będę składać Panu, swojemu Bogu, całopaleń, które nic nie kosztują. Kupił więc Dawid to klepisko i woły za pięćdziesiąt syklów srebra.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 25, 'I Dawid zbudował tam Panu ołtarz, i złożył całopalenia i ofiary pojednawcze. I Pan dał się ubłagać co do ziemi i plaga w Izraelu została powstrzymana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 1, 'Gdy król Dawid zestarzał się i posunął w latach, to choć okrywano go szatami, nie mógł się rozgrzać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 2, 'Jego słudzy powiedzieli mu więc: Niech poszukają dla naszego pana, króla, młodej dziewicy, która stawałaby przed królem i pielęgnowała go. Niech kładzie się na twoim łonie, żeby nasz pan, król, mógł się rozgrzać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 3, 'Szukali więc pięknej dziewczyny po wszystkich obszarach Izraela i znaleźli Abiszag Szunamitkę, i przyprowadzili ją do króla.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 4, 'Dziewczyna ta była bardzo piękna; pielęgnowała króla i służyła mu, ale król z nią nie obcował.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 5, 'Lecz Adoniasz, syn Chaggity, wywyższał się, mówiąc: Ja zostanę królem. Zaopatrzył się w rydwany i jeźdźców oraz pięćdziesięciu mężczyzn, którzy biegali przed nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 6, 'Jego ojciec nigdy go nie upominał, mówiąc: Czemu to uczyniłeś? Był on też bardzo przystojny, jego matka urodziła go po Absalomie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 7, 'Porozumiał się z Joabem, synem Serui, i z kapłanem Abiatarem, a oni przystali z Adoniaszem i pomogli mu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 8, 'Lecz kapłan Sadok, Benajasz, syn Jehojady, prorok Natan, Szimei, Rei oraz dzielni wojownicy Dawida nie sprzyjali Adoniaszowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 9, 'Potem Adoniasz zabił owce, woły i tuczne bydło przy kamieniu Zochelet, blisko źródła Rogel, i zaprosił wszystkich swych braci, synów króla, oraz wszystkich mężczyzn Judy, sługi króla.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 10, 'Lecz nie zaprosił proroka Natana, Benajasza i dzielnych wojowników oraz swego brata Salomona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 11, 'Wtedy Natan zapytał Batszebę, matkę Salomona: Czy nie słyszałaś, że Adoniasz, syn Chaggity, króluje, a nasz pan, Dawid, o tym nie wie?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 12, 'Chodź więc teraz, proszę, dam ci radę, abyś ocaliła swoje życie i życie swego syna, Salomona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 13, 'Idź i wejdź do króla Dawida, i powiedz mu: Czyż ty, mój panie, królu, nie przysiągłeś swojej służącej: Twój syn Salomon będzie królował po mnie i on zasiądzie na moim tronie? Dlaczego więc króluje Adoniasz?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 14, 'A oto gdy ty będziesz tam jeszcze rozmawiała z królem, ja wejdę za tobą i potwierdzę twoje słowa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 15, 'Batszeba weszła więc do króla do komnaty. Król już się bardzo zestarzał, a Abiszag Szunamitka usługiwała królowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 16, 'Wtedy Batszeba uklękła i oddała pokłon królowi, a król zapytał: Czego chcesz?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 17, 'A ona mu odpowiedziała: Mój panie, ty przysiągłeś swojej służącej na Pana, swego Boga: Twój syn, Salomon, będzie królował po mnie i on zasiądzie na moim tronie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 18, 'A oto teraz Adoniasz króluje, a ty, mój panie, królu, o tym nie wiesz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 19, 'Zabił bowiem woły, tuczne bydło i bardzo dużo owiec i zaprosił wszystkich synów króla, kapłana Abiatara oraz dowódcę wojska, Joaba, ale twego sługi Salomona nie zaprosił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 20, 'Lecz ty, mój panie, królu, wiesz, że oczy całego Izraela są zwrócone na ciebie, abyś im oznajmił, kto zasiądzie na tronie mego pana, króla, po nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 21, 'W przeciwnym razie, gdy mój pan, król, zaśnie ze swymi ojcami, ja i mój syn Salomon będziemy uważani za przestępców.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 22, 'A gdy jeszcze rozmawiała z królem, przyszedł prorok Natan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 23, 'I oznajmiono królowi: Oto prorok Natan. I gdy wszedł przed oblicze króla, pokłonił się królowi twarzą do ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 24, 'Potem Natan powiedział: Mój panie, królu, czy ty powiedziałeś: Adoniasz będzie królował po mnie i on zasiądzie na moim tronie?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 25, 'Dziś bowiem zstąpił i zabił woły, tuczne bydło oraz bardzo dużo owiec, i zaprosił wszystkich synów króla, dowódców wojsk oraz kapłana Abiatara, a oto oni jedzą z nim i piją, i mówią: Niech żyje król Adoniasz!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 26, 'Lecz mnie, twego sługi, i kapłana Sadoka, i Benajasza, syna Jehojady, oraz twego sługi Salomona nie zaprosił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 27, 'Czy wyszło to od mego pana, króla, a nie oznajmiłeś swemu słudze, kto zasiądzie po nim na tronie mego pana, króla?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 28, 'Król Dawid odpowiedział: Zawołajcie mi Batszebę. Ta weszła przed oblicze króla i stanęła przed nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 29, 'Wtedy król przysiągł: Jak żyje Pan, który wybawił moją duszę z wszelkiego ucisku;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 30, 'Jak przysiągłem ci na Pana, Boga Izraela: Twój syn Salomon będzie królować po mnie i on zasiądzie na moim tronie zamiast mnie, tak dziś uczynię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 31, 'Batszeba schyliła się twarzą ku ziemi i pokłonił się królowi, i powiedziała: Niech żyje mój pan, król Dawid, na wieki!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 32, 'Potem król Dawid rozkazał: Zawołajcie mi kapłana Sadoka, proroka Natana i Benajasza, syna Jehojady. I tamci weszli przed oblicze króla.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 33, 'A król powiedział im: Weźcie ze sobą sługi waszego pana, wsadźcie mego syna Salomona na moją mulicę i sprowadźcie go do Gichonu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 34, 'A tam niech kapłan Sadok i prorok Natan namaszczą go na króla nad Izraelem. Następnie zadmijcie w trąbę i powiedzcie: Niech żyje król Salomon!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 35, 'Potem pójdziecie za nim, a on przyjdzie i zasiądzie na moim tronie, i będzie królował na moje miejsce. Jego bowiem ustanowiłem wodzem nad Izraelem i nad Judą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 36, 'Benajasz, syn Jehojady, odpowiedział królowi: Amen. Niech to stwierdzi Pan, Bóg mego pana, króla.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 37, 'Jak Pan był z moim panem, królem, tak niech będzie z Salomonem i niech wywyższy jego tron nad tron mego pana, króla Dawida.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 38, 'Poszli więc kapłan Sadok, prorok Natan i Benajasz, syn Jehojady, oraz Keretyci i Peletyci i wsadzili Salomona na mulicę króla Dawida, i zaprowadzili go do Gichonu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 39, 'Wtedy kapłan Sadok wziął róg olejku z namiotu i namaścił Salomona. Potem zadęto w trąbę, a cały lud powiedział: Niech żyje król Salomon!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 40, 'I cały lud szedł za nim. Lud także grał na fletach i tak bardzo się radował, że ziemia drżała od jego głosu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 41, 'I usłyszeli to Adoniasz oraz wszyscy zaproszeni, którzy z nim byli, a właśnie skończyli ucztę. A gdy Joab usłyszał głos trąby, zapytał: Cóż to za krzyk poruszonego miasta?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 42, 'A gdy on jeszcze mówił, przyszedł Jonatan, syn kapłana Abiatara. Adoniasz powiedział mu: Wejdź, jesteś bowiem dzielnym człowiekiem i przynosisz dobrą nowinę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 43, 'Wtedy Jonatan odpowiedział Adoniaszowi: Nasz pan, król Dawid, ustanowił królem Salomona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 44, 'Król bowiem posłał z nim kapłana Sadoka i proroka Natana oraz Benajasza, syna Jehojady, do tego Keretytów i Peletytów, którzy wsadzili go na mulicę króla;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 45, 'Następnie kapłan Sadok i prorok Natan namaścili go na króla w Gichonie. I wyruszyli stamtąd, tak się radując, że miasto zadrżało. Stąd ten krzyk, który usłyszeliście.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 46, 'A Salomon zasiadł już na tronie królestwa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 47, 'Ponadto przyszli słudzy króla, aby błogosławić naszemu panu, królowi Dawidowi, mówiąc: Niech Bóg sławniejszym uczyni imię Salomona niż twoje imię i niech wywyższy jego tron ponad twój tron. A król skłonił się na swym łożu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 48, 'Również sam król powiedział: Błogosławiony niech będzie Pan, Bóg Izraela, który dał dziś zasiadającego na moim tronie, a moje oczy to widzą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 49, 'Wtedy zlękli się wszyscy zaproszeni, którzy byli z Adoniaszem, i wstali, i poszli każdy swoją drogą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 50, 'Adoniasz także, bojąc się Salomona, wstał, poszedł i uchwycił się rogów ołtarza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 51, 'I doniesiono o tym Salomonowi: Oto Adoniasz boi się króla Salomona i uchwycił się rogów ołtarza, mówiąc: Niech mi dziś przysięgnie król Salomon, że nie zabije swego sługi mieczem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 52, 'Wtedy Salomon odpowiedział: Jeśli okaże się godziwym człowiekiem, nie spadnie mu nawet włos na ziemię, ale jeśli znajdzie się w nim zło, poniesie śmierć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 53, 'Król Salomon posłał więc, aby go sprowadzono od ołtarza. Kiedy przyszedł, pokłonił się królowi Salomonowi. A powiedział mu Salomon: Idź do swego domu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 1, 'A gdy zbliżał się czas śmierci Dawida, rozkazał Salomonowi, swemu synowi:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 2, 'Idę drogą całej ziemi. Ty umacniaj się i okaż się mężczyzną;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 3, 'Zachowuj nakaz Pana, swego Boga, abyś chodził jego drogami i przestrzegał jego ustaw, jego przykazań, jego praw i jego świadectw, jak jest napisane w Prawie Mojżesza, aby ci się wiodło we wszystkim, co będziesz czynił, i wszędzie, dokądkolwiek się zwrócisz;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 4, 'Aby Pan spełnił swoje słowo, które zapowiedział o mnie: Jeśli twoi synowie będą strzec swej drogi, postępując przede mną w prawdzie, z całego swego serca i z całej swej duszy, to wtedy nie zabraknie ci mężczyzny na tronie Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 5, 'Ty wiesz także, co uczynił mi Joab, syn Serui, co uczynił dwom dowódcom wojska Izraela, Abnerowi, synowi Nera, i Amasie, synowi Jetery, których zabił i przelał krew w czasie pokoju jak na wojnie, i zbroczył tą krwią wojny swój pas na biodrach i swoje obuwie na nogach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 6, 'Uczynisz więc według swojej mądrości, jednak nie dopuść, aby w sędziwym wieku zstąpił w pokoju do grobu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 7, 'Lecz synom Barzillaja Gileadczyka okaż łaskę i niech należą do tych, którzy jadają przy twoim stole. Oni bowiem przyszli do mnie, kiedy uciekałem przed twoim bratem Absalomem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 8, 'Oto jest też u ciebie Szimei, syn Gery, Beniaminita z Bachurim, który złorzeczył mi ostro w tym dniu, kiedy szedłem do Machanaim. Lecz wyszedł mi na spotkanie nad Jordanem i przysiągłem mu na Pana: Nie zabiję cię mieczem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 9, 'Teraz jednak nie daruj mu tego. Jesteś bowiem człowiekiem mądrym i będziesz wiedział, co masz mu uczynić, by posłać go w sędziwym wieku zbroczonego krwią do grobu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 10, 'Potem Dawid zasnął ze swymi ojcami i został pogrzebany w mieście Dawida.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 11, 'A czas panowania Dawida nad Izraelem wynosił czterdzieści lat. W Hebronie królował siedem lat, a w Jerozolimie królował trzydzieści trzy lata.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 12, 'Zasiadł więc Salomon na tronie Dawida, swego ojca, i jego królestwo zostało mocno utwierdzone.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 13, 'Potem przyszedł Adoniasz, syn Chaggity, do Batszeby, matki Salomona. Ta go zapytała: Czy twoje przyjście oznacza pokój? A on odpowiedział: Pokój.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 14, 'Następnie dodał: Mam do ciebie sprawę. Odpowiedziała: Mów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 15, 'Wtedy powiedział: Ty wiesz, że do mnie należało królestwo i że cały Izrael patrzył na mnie i chciał, abym królował. Królestwo jednak uległo zmianie i dostało się memu bratu, bo przypadło mu ono od Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 16, 'Teraz mam więc do ciebie jedną prośbę, nie odmawiaj mi tego. Odpowiedziała: Mów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 17, 'Wtedy powiedział: Powiedz, proszę, do Salomona, króla – bo wiem, że tobie nie odmówi – aby dał mi Abiszag Szunamitkę za żonę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 18, 'Batszeba odpowiedziała: Dobrze, przemówię za tobą do króla.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 19, 'Poszła więc Batszeba do króla Salomona, aby przemówić do niego za Adoniaszem. I król wstał na jej spotkanie, pokłonił się jej i usiadł na swym tronie. Kazał też postawić krzesło swojej matce, a ona usiadła po jego prawicy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 20, 'I powiedziała: Mam do ciebie jedną małą prośbę, nie odmawiaj mi. Król odpowiedział jej: Proś, moja matko, bo ci nie odmówię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 21, 'Wtedy powiedziała: Niech Abiszag Szunamitka będzie dana za żonę twemu bratu, Adoniaszowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 22, 'Król Salomon odpowiedział swojej matce: A dlaczego prosisz o Abiszag Szunamitkę dla Adoniasza? Poproś także dla niego o królestwo. Jest bowiem moim starszym bratem i ma za sobą kapłana Abiatara i Joaba, syna Serui.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 23, 'I król Salomon przysiągł na Pana: Niech Bóg mi to uczyni i tamto dorzuci, jeśli Adoniasz nie wypowiedział tych słów przeciwko własnemu życiu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 24, 'A teraz, jak żyje Pan, który mnie ustanowił i posadził na tronie Dawida, mego ojca, i który zbudował mi dom, jak obiecał, Adoniasz dziś zostanie zabity.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 25, 'Wtedy król Salomon posłał Benajasza, syna Jehojady, i ten zadał mu cios, tak że umarł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 26, 'A do kapłana Abiatara król powiedział: Idź do Anatot, do swojej posiadłości, gdyż zasłużyłeś na śmierć. Dziś jednak nie zabiję cię, ponieważ nosiłeś arkę Pana przed Dawidem, moim ojcem, i ponieważ wycierpiałeś wszystko, co mój ojciec wycierpiał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 27, 'I Salomon usunął Abiatara, by nie był kapłanem Pana, aby spełniło się słowo Pana, które wypowiedział o domu Helego w Szilo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 28, 'Gdy wieść o tym doszła do Joaba – Joab bowiem dołączył do Adoniasza, chociaż do Absaloma nie dołączył – Joab uciekł do namiotu Pana i uchwycił się rogów ołtarza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 29, 'I doniesiono królowi Salomonowi o tym, że Joab uciekł do namiotu Pana i jest przy ołtarzu. Wtedy Salomon posłał Benajasza, syna Jehojady, mówiąc: Idź, zabij go.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 30, 'Benajasz przyszedł więc do namiotu Pana i powiedział do niego: Tak mówi król: Wyjdź. Ten odpowiedział: Nie wyjdę, ale tu umrę. Benajasz przekazał odpowiedź królowi: Tak mówił Joab i tak mi odpowiedział.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 31, 'I król mu polecił: Uczyń, jak powiedział. Zabij go i pogrzeb go, a oczyścisz mnie i dom mego ojca z niewinnej krwi, którą przelał Joab.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 32, 'A Pan sprowadzi jego krew na jego własną głowę, ponieważ zadał cios dwom mężczyznom sprawiedliwszym i lepszym niż on sam i zabił ich mieczem bez wiedzy mego ojca Dawida – Abnera, syna Nera, dowódcę wojska Izraela, i Amasę, syna Jetery, dowódcę wojska Judy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 33, 'Ich krew spadnie na głowę Joaba i na głowę jego potomstwa na wieki. Dla Dawida zaś i jego potomstwa, jego domu i jego tronu niech będzie pokój od Pana na wieki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 34, 'Benajasz, syn Jehojady, poszedł więc, rzucił się na niego i zabił go. I został pogrzebany w swoim domu na pustyni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 35, 'Król na jego miejsce postawił na czele wojska Benajasza, syna Jehojady, a kapłana Sadoka król postawił na miejsce Abiatara.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 36, 'Potem król posłał po Szimejego i przyzwał go, i powiedział mu: Zbuduj sobie dom w Jerozolimie i zamieszkaj tam, i nigdy stamtąd nie wychodź.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 37, 'Tego dnia bowiem, w którym wyjdziesz i przekroczysz potok Cedron, wiedz dobrze, że na pewno umrzesz. Twoja krew spadnie na twoją głowę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 38, 'Wtedy Szimei powiedział do króla: Dobre jest to słowo. Jak mój pan, król, powiedział, tak twój sługa uczyni. I mieszkał Szimei w Jerozolimie przez wiele dni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 39, 'I zdarzyło się po trzech latach, że dwaj słudzy Szimejego uciekli do Akisza, syna Maaki, króla Gat. I dano znać Szimejemu: Oto twoi słudzy są w Gat.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 40, 'Szimei wstał więc, osiodłał swego osła i wyruszył do Gat, do Akisza, aby szukać swoich sług. Potem Szimei wrócił i przyprowadził swe sługi z Gat.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 41, 'I doniesiono Salomonowi, że Szimei poszedł z Jerozolimy do Gat i powrócił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 42, 'Wtedy król posłał po Szimejego i wezwał go, i powiedział mu: Czy nie przysiągłem na Pana i nie oświadczyłem ci, mówiąc: Tego dnia, w którym wyjdziesz, wiedz dobrze, że na pewno umrzesz? I odpowiedziałeś mi: Dobre to słowo, które słyszałem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 43, 'Dlaczego więc nie przestrzegałeś przysięgi Pana i nakazu, który ci dałem?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 44, 'Następnie król powiedział do Szimejego: Znasz całe zło, którego jest świadome twoje serce, a które wyrządziłeś memu ojcu Dawidowi. Pan sprowadzi więc twoje zło na twoją głowę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 45, 'A król Salomon będzie błogosławiony i tron Dawida zostanie utwierdzony przed Panem na wieki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 46, 'Tak więc król wydał rozkaz Benajaszowi, synowi Jehojady; i ten wyszedł, zadał mu cios i zabił go. I tak królestwo zostało utwierdzone w ręce Salomona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 1, 'I Salomon spowinowacił się z faraonem, królem Egiptu. Pojął bowiem za żonę córkę faraona i przyprowadził ją do miasta Dawida, zanim skończył budować swój dom i dom Pana oraz mur dokoła Jerozolimy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 2, 'Lud jednak składał ofiary na wyżynach, dlatego że do tego czasu nie został jeszcze zbudowany dom dla imienia Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 3, 'I Salomon miłował Pana, postępując zgodnie z przykazaniami Dawida, swego ojca, tylko że składał ofiary i spalał kadzidło na wyżynach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 4, 'Król udał się więc do Gibeonu, aby tam złożyć ofiary, bo tam była wielka wyżyna. Na tym ołtarzu Salomon złożył tysiąc ofiar całopalnych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 5, 'W Gibeonie Pan ukazał się Salomonowi w nocy we śnie. Bóg powiedział: Proś o to, co mam ci dać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 6, 'Salomon odpowiedział: Ty okazałeś swemu słudze Dawidowi, memu ojcu, wielkie miłosierdzie, gdyż postępował przed tobą w prawdzie, sprawiedliwości i prawości serca przy tobie. I zachowałeś dla niego tę wielką łaskę, że dałeś mu syna, który zasiadł na jego tronie, jak to się dzieje dziś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 7, 'Teraz więc, o Panie, mój Boże, ty ustanowiłeś swego sługę królem w miejsce Dawida, mego ojca, a ja jestem małym dzieckiem i nie wiem, jak wyruszać ani jak wracać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 8, 'Twój sługa jest wśród twego ludu, który wybrałeś, ludu wielkiego, którego z powodu wielkiej liczby nie można zliczyć ani spisać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 9, 'Daj więc swemu słudze serce rozumne, aby mógł sądzić twój lud i rozróżniać między dobrem a złem. Któż bowiem może sądzić ten twój tak wielki lud?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 10, 'I spodobało się to Panu, że Salomon o to poprosił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 11, 'Wtedy Bóg powiedział do niego: Ponieważ poprosiłeś o to, a nie poprosiłeś dla siebie o długie życie ani nie poprosiłeś dla siebie o bogactwo, ani też nie poprosiłeś o wytracenie swoich wrogów, ale poprosiłeś dla siebie o rozum dla rozróżnienia w sprawach sądowych;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 12, 'Oto uczyniłem według twoich słów: Dałem ci serce mądre i rozumne, tak że podobnego tobie nie było przed tobą ani po tobie nie powstanie nikt jak ty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 13, 'Dam ci także to, o co nie prosiłeś, a więc bogactwo i sławę, tak że wśród królów nie będzie nikogo równego tobie po wszystkie twoje dni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 14, 'A jeśli będziesz chodził moimi drogami, przestrzegając moich ustaw i przykazań, jak postępował Dawid, twój ojciec, wtedy przedłużę twoje dni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 15, 'A gdy Salomon obudził się, zrozumiał, że to był sen. Wrócił więc do Jerozolimy, stanął przed arką przymierza Pana i złożył całopalenia i ofiary pojednawcze oraz wyprawił ucztę wszystkim swoim sługom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 16, 'Wtedy przyszły do króla dwie kobiety, nierządnice, i stanęły przed nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 17, 'Jedna z kobiet powiedziała: Proszę cię, mój panie, ja i ta kobieta mieszkamy w jednym domu. Ja urodziłam przy niej w tym domu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 18, 'A trzeciego dnia po moim porodzie urodziła również ta kobieta. I byłyśmy razem, nie było z nami nikogo innego w domu; tylko my dwie byłyśmy w tym domu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 19, 'W nocy umarł syn tej kobiety, ponieważ przygniotła go.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 20, 'Wstała więc o północy, wzięła mego syna od mego boku, gdy twoja służąca spała, i położyła go na swym łonie, a swego zmarłego syna położyła na moim łonie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 21, 'Kiedy wstałam rano, aby nakarmić swego syna piersią, oto był martwy. Lecz gdy przyjrzałam się rano, zobaczyłam, że to nie był mój syn, którego urodziłam.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 22, 'Wtedy druga kobieta odezwała się: Nie! Moim synem jest ten żywy, a twoim synem jest ten umarły. Lecz tamta powiedziała: Nie! Twoim synem jest ten umarły, a moim synem jest ten żywy. I tak się spierały przed królem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 23, 'Wtedy król powiedział: Ta mówi: Ten żywy jest moim synem, a twoim synem ten umarły, a tamta mówi: Nie tak – twoim synem jest ten umarły, a moim synem jest ten żywy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 24, 'Król powiedział więc: Przynieście mi miecz. I przyniesiono miecz przed króla.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 25, 'Wtedy król powiedział: Rozetnijcie żywe dziecko na dwoje i dajcie połowę jednej i połowę drugiej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 26, 'Lecz kobieta, do której należał żywy syn, zdjęta litością nad swoim synem, powiedziała do króla: Proszę, mój panie, dajcie jej to żywe dziecko, tylko nie zabijajcie go! Lecz druga powiedziała: Niech nie będzie ani moje, ani twoje, rozetnijcie je.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 27, 'Wtedy król odpowiedział: Dajcie jej żywe dziecko, a nie zabijajcie go. Ona jest jego matką.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 28, 'A kiedy cały lud Izraela usłyszał o tym wyroku, który wydał król, bał się króla. Widzieli bowiem, że jest w nim mądrość Boża do sprawowania sądu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 1, 'Tak więc król Salomon był królem nad całym Izraelem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 2, 'A oto jego dostojnicy: Azariasz, syn Sadoka, kapłan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 3, 'Elichoref i Achiasz, synowie Sziszy, pisarze; Jehoszafat, syn Achiluda, kronikarz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 4, 'Benajasz, syn Jehojady, dowódca wojska; Sadok i Abiatar, kapłani.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 5, 'Azariasz, syn Natana, przełożony namiestników, Zabud, syn Natana, naczelny dostojnik, przyjaciel króla.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 6, 'Achiszar, przełożony dworu, i Adoniram, syn Abdy, odpowiedzialny za daninę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 7, 'Salomon miał też dwunastu namiestników nad całym Izraelem, którzy zaopatrywali króla i cały jego dwór w żywność. Każdy z nich przez jeden miesiąc w roku miał dostarczać żywność.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 8, 'A oto ich imiona: syn Chura – na górze Efraim;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 9, 'Syn Dekara – w Makas, Szaalbim – w Bet-Szemesz i Elon-Bet-Chanan;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 10, 'Syn Cheseda – w Arubot, do niego należało Soko i cała ziemia Chefer;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 11, 'Syn Abinadaba – nad całym obszarem Dor; jego żoną była Tafat, córka Salomona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 12, 'Baana, syn Achiluda, do którego należały Tanak i Megiddo oraz całe Bet-Szean, które leży przy Sartan pod Jizreelem, od Bet-Szean aż do Abel-Mechola, aż poza Jokmeam.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 13, 'Syn Geber – w Ramot-Gilead, do niego należały wsie Jaira, syna Manassesa, które leżą w Gileadzie. Do niego też należała kraina Argob, która jest w Baszanie – sześćdziesiąt wielkich miast mających mury i brązowe rygle.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 14, 'Achinadab, syn Iddo – w Machanaim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 15, 'Achimaas – w Neftalim; on też pojął za żonę Basemat, córkę Salomona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 16, 'Baana, syn Chuszaia – w Aszer i Alot.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 17, 'Jehoszafat, syn Paruacha – w Issacharze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 18, 'Szimei, syn Eli – w Beniaminie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 19, 'Geber, syn Uriego – w ziemi Gilead, ziemi Sichona, króla Amorytów, i Oga, króla Baszanu. Był on jedynym namiestnikiem tej ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 20, 'A Juda i Izrael byli tak liczni jak piasek nad morzem. Jedli, pili i radowali się.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 21, 'A Salomon panował nad wszystkimi królestwami od rzeki aż do ziemi Filistynów, aż do granicy Egiptu. Płaciły one daninę i służyły Salomonowi po wszystkie dni jego życia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 22, 'Wyżywienie dla Salomona na jeden dzień wynosiło trzydzieści kor najlepszej mąki i sześćdziesiąt kor zwykłej mąki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 23, 'Dziesięć tucznych wołów, dwadzieścia wołów z pastwiska, sto owiec, nie licząc jeleni, saren, danieli i tucznego drobiu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 24, 'Panował bowiem nad całym obszarem z tej strony rzeki, od Tifsach aż do Gazy, nad wszystkimi królami z tej strony rzeki. I miał pokój ze wszystkich stron dokoła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 25, 'Juda i Izrael mieszkali bezpiecznie, każdy pod swoją winoroślą i pod swoim drzewem figowym, od Dan aż do Beer-Szeby, po wszystkie dni Salomona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 26, 'Salomon miał też czterdzieści tysięcy koni w stajniach do swoich rydwanów i dwanaście tysięcy jeźdźców.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 27, 'Namiestnicy, każdy w swoim miesiącu, zaopatrywali w żywność króla Salomona i wszystkich, którzy przychodzili do stołu króla Salomona, tak że niczego nie brakowało.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 28, 'Także jęczmień i słomę dla koni i mułów sprowadzali na to miejsce, gdzie one przebywały, każdy według swojego obowiązku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 29, 'A Bóg dał Salomonowi mądrość i bardzo wielkie zrozumienie oraz przestronność serca jak piasek, który jest na brzegu morskim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 30, 'I mądrość Salomona była większa od mądrości wszystkich narodów wschodnich i od wszelkiej mądrości Egiptu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 31, 'Był mądrzejszy niż wszyscy ludzie, niż Etan Ezrachita, Heman, Kalkol i Darda, synowie Machola. Był sławny wśród wszystkich okolicznych narodów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 32, 'Wypowiedział trzy tysiące przysłów, a jego pieśni było tysiąc pięć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 33, 'Wypowiadał się też o drzewach, poczynając od cedru na Libanie aż do hizopu, który wyrasta z muru. Mówił też o zwierzętach, ptakach, płazach i rybach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 34, 'Przychodzili więc ludzie ze wszystkich narodów, aby słuchać mądrości Salomona, od wszystkich królów ziemi, którzy słyszeli o jego mądrości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 1, 'Hiram, król Tyru, wysłał swoje sługi do Salomona, bo usłyszał, że namaszczono go na króla w miejsce jego ojca. Hiram bowiem kochał Dawida przez wszystkie dni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 2, 'Salomon też posłał do Hirama taką wiadomość:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 3, 'Ty wiesz, że mój ojciec Dawid nie mógł budować domu dla imienia Pana, swego Boga, z powodu wojen, które go otaczały, dopóki Pan nie poddał jego wrogów pod stopy jego nóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 4, 'Lecz teraz Pan, mój Bóg, dał mi zewsząd odpoczynek, nie ma żadnego przeciwnika ani złego wydarzenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 5, 'Oto postanowiłem zbudować dom dla imienia Pana, swego Boga, zgodnie z tym, co Pan powiedział memu ojcu Dawidowi: Twój syn, którego posadzę po tobie na twoim tronie, on zbuduje dom dla mojego imienia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 6, 'Teraz więc rozkaż, aby ścięto dla mnie cedry z Libanu, a moi słudzy będą z twoimi sługami. Dam ci zapłatę dla twoich sług, jaką wyznaczysz. Ty wiesz bowiem, że wśród nas nie ma nikogo, kto by umiał rąbać drzewo tak jak Sydończycy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 7, 'Gdy Hiram usłyszał słowa Salomona, bardzo się ucieszył i powiedział: Błogosławiony niech będzie dzisiaj Pan, który dał Dawidowi mądrego syna, aby był nad tym wielkim ludem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 8, 'Wtedy Hiram posłał do Salomona wiadomość: Wysłuchałem tego, co mi przesłałeś. Uczynię wszystko zgodnie z twoim życzeniem co do drewna cedrowego i drewna cyprysowego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 9, 'Moi słudzy sprowadzą je z Libanu nad morze, a ja każę je złożyć na tratwy i przeprawić przez morze aż do miejsca, które mi wskażesz. Tam je rozładują, a ty je zabierzesz. Ty też spełnisz moje życzenie i dostarczysz żywność dla mojego dworu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 10, 'Hiram dostarczał więc Salomonowi drewno cedrowe i drewno cyprysowe, tyle ile Salomon chciał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 11, 'Salomon z kolei dostarczał Hiramowi dwadzieścia tysięcy kor pszenicy na żywność dla jego dworu i dwadzieścia kor czystej oliwy. Tyle Salomon dostarczał Hiramowi każdego roku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 12, 'A Pan dał Salomonowi mądrość, tak jak mu obiecał. I panował pokój między Hiramem a Salomonem, zawarli też ze sobą przymierze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 13, 'Potem król Salomon kazał wybrać robotników z całego Izraela, a było tych robotników trzydzieści tysięcy mężczyzn.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 14, 'Co miesiąc wysyłał ich do Libanu po dziesięć tysięcy na zmianę: miesiąc przebywali w Libanie, a dwa miesiące w domu. Przełożonym tych robotników był Adoniram.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 15, 'Salomon miał też siedemdziesiąt tysięcy ludzi do dźwigania ciężarów oraz osiemdziesiąt tysięcy robotników w kamieniołomach w górach;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 16, 'Oprócz naczelnych urzędników Salomona, którzy nadzorowali pracę, miał też trzy tysiące trzystu przełożonych nad ludźmi wykonującymi pracę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 17, 'Król rozkazał również, aby przywieziono kamienie wielkie, kamienie drogie i kamienie ciosane na założenie fundamentów domu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 18, 'Ciosali je więc budowniczowie Salomona i Hirama oraz Gibilici. I tak przygotowali drewno i kamienie na budowę domu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 1, 'W roku czterysta osiemdziesiątym po wyjściu synów Izraela z ziemi Egiptu, w czwartym roku panowania Salomona nad Izraelem, w miesiącu Ziw, to jest drugim miesiącu, Salomon rozpoczął budować dom Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 2, 'A ten dom, który król Salomon budował dla Pana, miał sześćdziesiąt łokci długości, dwadzieścia łokci szerokości i trzydzieści łokci wysokości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 3, 'Przedsionek domu przed świątynią miał dwadzieścia łokci długości, stosownie do szerokości domu, i dziesięć łokci szerokości przed domem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 4, 'I zrobił okna w domu, od wewnątrz przestronne, a od zewnątrz wąskie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 5, 'Przy murze domu zbudował skrzydła dokoła, przy murach domu dokoła świątyni i Miejsca Najświętszego. Porobił też dokoła pomieszczenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 6, 'Dolna część skrzydła miała pięć łokci szerokości, środkowa – sześć łokci, a trzecia – siedem łokci. Uczynił bowiem uskoki dokoła domu na zewnątrz, aby belki nie wchodziły do murów domu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 7, 'Podczas prac nad domem budowano go z wyrobionego kamienia, który przywożono. W czasie budowy nie było więc słychać w domu ani młota, ani siekiery, ani żadnego innego narzędzia z żelaza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 8, 'Drzwi do średniej części były po prawej stronie domu; po krętych schodach wchodziło się do środkowej części, a ze środkowej – do trzeciej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 9, 'Tak więc zbudował dom i ukończył go, i pokrył sklepienie domu belkami i deskami cedrowymi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 10, 'Zbudował też przybudówkę przy całym domu wysoką na pięć łokci – była ona połączona z domem belkami cedrowymi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 11, 'Potem słowo Pana doszło do Salomona:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 12, 'Odnośnie do domu, który budujesz – jeśli będziesz postępował według moich ustaw i wykonywał moje sądy, i zachowywał wszystkie moje przykazania, postępując według nich, wtedy spełnię moje słowo wobec ciebie, które wypowiedziałem do Dawida, twego ojca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 13, 'I zamieszkam wśród synów Izraela, i nie opuszczę swego ludu Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 14, 'Tak Salomon zbudował dom i wykończył go.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 15, 'Mury domu obłożył wewnątrz deskami cedrowymi, od podłogi domu aż do sufitu. Wyłożył je drewnem wewnątrz, a podłogę domu pokrył deskami cyprysowymi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 16, 'Zbudował też przegrodę z desek cedrowych długą na dwadzieścia łokci, od jednej strony do drugiej strony domu, od podłogi aż do sufitu. W ten sposób zbudował wewnętrzny przybytek, aby był Miejscem Najświętszym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 17, 'Sam dom, czyli świątynia przed Miejscem Najświętszym, miał czterdzieści łokci długości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 18, 'A na deskach cedrowych wewnątrz domu wyrzeźbiono pąki i rozkwitłe kwiaty. Wszystko było z cedru, tak że kamienia nie było widać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 19, 'A Miejsce Najświętsze wewnątrz domu urządził tak, by tam umieścić arkę przymierza Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 20, 'To Miejsce Najświętsze, umieszczone w przedniej części domu, miało dwadzieścia łokci długości, dwadzieścia łokci szerokości i dwadzieścia łokci wysokości. I pokrył je szczerym złotem, ołtarz cedrowy także pokrył złotem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 21, 'I w ten sposób Salomon wyłożył wnętrze domu szczerym złotem, i przed przegrodą, którą również pokrył złotem, rozciągnął złote łańcuchy przed Miejscem Najświętszym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 22, 'Cały dom pokrył złotem; tak go wykończył. Cały ołtarz, który znajdował się przed Miejscem Najświętszym, także pokrył złotem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 23, 'W Miejscu Najświętszym uczynił też dwa cherubiny z drzewa oliwnego wysokie na dziesięć łokci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 24, 'Pięć łokci miało jedno skrzydło cherubina i pięć łokci miało drugie skrzydło cherubina: dziesięć łokci było od końca jednego skrzydła aż do końca drugiego skrzydła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 25, 'Dziesięć łokci miał też drugi cherubin: oba cherubiny miały ten sam rozmiar i kształt.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 26, 'Wysokość jednego cherubina wynosiła dziesięć łokci, tak samo wysokość drugiego cherubina.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 27, 'I postawił cherubiny w głębi wnętrza domu, i skrzydła cherubinów rozpościerały się tak, że skrzydło jednego dotykało jednej ściany, a skrzydło drugiego cherubina dotykało drugiej ściany; ich skrzydła dotykały się w środku domu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 28, 'I pokrył cherubiny złotem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 29, 'Nadto wszystkie ściany dokoła domu wewnątrz i na zewnątrz ozdobił wyrytymi cherubinami, palmami i rozkwitłymi kwiatami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 30, 'Podłogę domu wyłożył złotem wewnątrz i na zewnątrz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 31, 'U wejścia do Miejsca Najświętszego wykonał drzwi z drzewa oliwnego. Nadproża i węgary zajmowały piątą część muru.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 32, 'Podwójne drzwi wykonane były z drzewa oliwnego; wyrzeźbił na nich cherubiny, palmy i rozkwitłe kwiaty i pokrył je złotem. Cherubiny i palmy też wyłożył złotem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 33, 'W ten sam sposób uczynił odrzwia z drzewa oliwnego u wejścia do świątyni – zajmowały one jedną czwartą część muru.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 34, 'A podwójne drzwi wykonane były z drewna cyprysowego. Dwie obracające się deski tworzyły jedno skrzydło i dwie obracające się deski – drugie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 35, 'Na nich wyrył cherubiny, palmy i rozkwitłe kwiaty i pokrył złotem dokładnie nałożonym na rzeźby.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 36, 'Obudował też dziedziniec trzema warstwami ociosanych kamieni i jedną warstwą belek cedrowych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 37, 'W czwartym roku, w miesiącu Ziw, położono fundamenty domu Pana;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 38, 'A w jedenastym roku, w miesiącu Bul, to jest ósmym miesiącu, dom został wykończony we wszystkich szczegółach i ze wszystkimi jego wymogami. A budował go przez siedem lat.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 1, 'Swój dom natomiast Salomon budował trzynaście lat i cały swój dom wykończył.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 2, 'Zbudował też dom lasu Libanu, długi na sto łokci, szeroki na pięćdziesiąt łokci i wysoki na trzydzieści łokci. Na czterech rzędach kolumn cedrowych wspierały się belki cedrowe.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 3, 'Był on pokryty dachem cedrowym, zbudowanym na belkach, które wznosiły się na czterdziestu pięciu kolumnach, po piętnaście w każdym rzędzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 4, 'Były też trzy rzędy okien, jedno okno naprzeciwko drugiego w trzech szeregach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 5, 'Wszystkie drzwi i odrzwia były prostokątne, również okna. Okna były naprzeciw siebie w trzech rzędach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 6, 'Zbudował też przedsionek kolumnowy, długi na pięćdziesiąt łokci i szeroki na trzydzieści łokci. A przed nim znajdował się przedsionek, przed nim były także kolumny i belki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 7, 'Ponadto zbudował przedsionek tronowy, w którym sądził, przedsionek sądowy. Był on pokryty cedrem od podłogi aż do sufitu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 8, 'A w swoim domu, w którym mieszkał, znajdował się drugi dziedziniec za przedsionkiem i był tak samo wykonany. Salomon zbudował także dom podobny do tego przedsionka dla córki faraona, którą poślubił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 9, 'To wszystko wykonane było z kosztownych kamieni wyciosanych na miarę i ciętych piłą, wewnątrz i na zewnątrz, od podłogi aż do sufitu, od dworu aż do wielkiego dziedzińca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 10, 'A fundament wykonany był z kosztownych kamieni, kamieni wielkich, z kamieni na dziesięć łokci i z kamieni na osiem łokci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 11, 'A nad tym były kamienie kosztowne wyciosane na miarę, z deskami cedrowymi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 12, 'Wielki dziedziniec miał dokoła trzy rzędy ociosanych kamieni i jeden rząd belek cedrowych, tak samo jak wewnętrzny dziedziniec domu Pana i przedsionek tego domu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 13, 'Król Salomon posłał po Hirama i sprowadził go z Tyru.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 14, 'Był on synem wdowy z pokolenia Neftalego, a jego ojciec był obywatelem Tyru. Był brązownikiem, pełnym mądrości, zrozumienia i umiejętności wykonania wszelkich wyrobów z brązu. Przybył do króla Salomona i wykonał wszystkie zlecone przez niego prace.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 15, 'Odlał dwie kolumny z brązu – jedna kolumna miała osiemnaście łokci wysokości, a jej obwód wynosił dwanaście łokci. Taka sama była druga kolumna.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 16, 'Potem wykonał dwie głowice, aby je umieścić na wierzchu kolumn, odlane były z brązu. Jedna i druga głowica miały pięć łokci wysokości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 17, 'Wykonał też siatki na kształt krat i plecionki na kształt łańcuchów do głowic, które były na wierzchołkach kolumn – siedem dla jednej głowicy i siedem dla drugiej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 18, 'Po wykonaniu kolumn sporządził dwa rzędy jabłek granatu dokoła na jednej siatce, aby pokrywały głowice na wierzchołkach kolumn. Tak samo zrobił na drugiej głowicy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 19, 'Głowice, które znajdowały się na wierzchołkach kolumn w przedsionku, były w kształcie lilii wielkości czterech łokci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 20, 'Głowice na obu kolumnach, zarówno w górnej części, jak i przy środkowej części pod siatką, miały jabłka granatu. Było ich dwieście, umieszczone w dwóch rzędach dokoła, na jednej i na drugiej głowicy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 21, 'Potem postawił te kolumny w przedsionku świątyni. Postawił jedną kolumnę po prawej stronie i nazwał ją Jakin. Postawił drugą kolumnę po lewej stronie i nazwał ją Boaz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 22, 'A na wierzchołkach tych kolumn wykonana była ozdoba na kształt lilii. Tak została wykończona praca nad kolumnami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 23, 'Wykonał też odlewane morze na dziesięć łokci od brzegu do brzegu. Było ono idealnie okrągłe, miało pięć łokci wysokości i trzydzieści łokci obwodu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 24, 'A pod jego brzegiem znajdowały się pąki, wszędzie dokoła, po dziesięć na łokieć, a otaczały morze dokoła. Odlano dwa rzędy tych pąków.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 25, 'Morze stało na dwunastu wołach. Trzy były zwrócone na północ, trzy – na zachód, trzy – na południe i trzy – na wschód. Morze stało na nich z wierzchu, a wszystkie ich zady były zwrócone do środka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 26, 'Jego grubość była na szerokość dłoni, a jego brzeg wykonany był jak brzeg kielicha, na kształt kwiatu lilii. Mieściło w sobie dwa tysiące bat.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 27, 'Uczynił też dziesięć podstaw z brązu, każda podstawa miała cztery łokcie długości, cztery łokcie szerokości i trzy łokcie wysokości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 28, 'Podstawy wykonano w ten sposób: miały listwy dokoła i te listwy umieszczone były między szczeblami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 29, 'A na tych listwach, znajdujących się między szczeblami, były lwy, woły i cherubiny, a na szczeblach umieszczona była podstawa z wierzchu, a pod tymi lwami i wołami – elementy plecione.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 30, 'Każda podstawa miała cztery koła z brązu oraz płyty z brązu. Na czterech rogach znajdowały się podpory, które były odlane pod kadzią, obok każdego z plecionych elementów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 31, 'Otwór podstawy od wewnątrz głowicy i wzwyż miał łokieć, był on okrągły jak kształt podstawy – na półtora łokcia. Na otworze umieszczone były płaskorzeźby i listwy czworokątne, nie okrągłe.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 32, 'Pod listwami znajdowały się cztery koła, a osie kół były przymocowane do podstawy, a każde koło miało półtora łokcia wysokości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 33, 'A wykonano te koła, jak wykonuje się koło rydwanu. Ich osie, dzwony, szprychy i piasty były wszystkie odlewane.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 34, 'Na czterech rogach każdej podstawy znajdowały się cztery podpory, które razem z podstawą stanowiły całość.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 35, 'Na wierzchu podstawy umieszczona była obręcz wysoka na pół łokcia. A na wierzchu podstawy były jej szczeble i listwy, które tworzyły z nią całość.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 36, 'Na płaszczyznach tych szczebelków i na listwach wyrył cherubiny, lwy i palmy, stosownie do miejsca dla każdego, oraz inne elementy dokoła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 37, 'W ten sam sposób uczynił dziesięć podstaw: wszystkie miały ten sam odlew, ten sam wymiar i ten sam kształt.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 38, 'Potem wykonał dziesięć kadzi z brązu. Jedna kadź mieściła czterdzieści bat i każda z nich miała cztery łokcie. Na każdej z dziesięciu podstaw stała jedna kadź.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 39, 'I umieścił pięć podstaw po prawej stronie domu i pięć po lewej stronie domu. Umieścił też morze po prawej stronie domu na południowym wschodzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 40, 'Hiram wykonał też kociołki, łopatki i miednice. Hiram zakończył więc wykonywanie całej pracy, którą uczynił dla króla Salomona do domu Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 41, 'Wykonał mianowicie dwie kolumny, dwie okrągłe głowice, które były na szczycie dwóch kolumn, dwie siatki do pokrycia tych dwóch okrągłych głowic na szczycie kolumn;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 42, 'Czterysta jabłek granatu do tych dwóch siatek, po dwa rzędy jabłek granatu na każdą siatkę, które okrywały dwie okrągłe głowice na szczycie kolumn;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 43, 'Dziesięć podstaw i dziesięć kadzi na podstawach;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 44, 'Jedno morze i pod nim dwanaście wołów;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 45, 'Oraz garnki, łopatki i miednice. Wszystkie naczynia, które Hiram uczynił dla króla Salomona do domu Pana, były z polerowanego brązu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 46, 'Król odlewał je na równinie nad Jordanem w gliniastej ziemi, między Sukkot a Sartan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 47, 'Ale Salomon nie ważył wszystkich tych naczyń, gdyż było ich mnóstwo, i nie obliczono wagi brązu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 48, 'Salomon uczynił też wszystkie przedmioty do domu Pana: złoty ołtarz, złoty stół, na którym leżały chleby pokładne;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 49, 'Świeczniki ze szczerego złota – pięć po prawej stronie i pięć po lewej stronie przed Najświętszym Miejscem – oraz kwiaty, lampy i szczypce ze złota;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 50, 'Misy i nożyce, miednice, czasze, kadzielnice ze szczerego złota i złote zawiasy do drzwi wewnętrznego domu, czyli Miejsca Najświętszego, także do drzwi domu świątyni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 51, 'Tak więc ukończono wszelką pracę, którą wykonał król Salomon dla domu Pana. I Salomon wniósł tam rzeczy, które poświęcił jego ojciec Dawid – srebro, złoto i naczynia – i włożył je do skarbców domu Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 1, 'Potem Salomon zebrał starszych Izraela i wszystkich naczelników pokoleń, przywódców rodów synów Izraela, u siebie w Jerozolimie, aby przenieść arkę przymierza Pana z miasta Dawida, którym jest Syjon.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 2, 'Zebrali się więc u króla Salomona wszyscy mężczyźni Izraela na święto w miesiącu Etanim, to jest siódmym miesiącu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 3, 'A gdy przybyli wszyscy starsi Izraela, kapłani wzięli arkę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 4, 'I przenieśli arkę Pana, Namiot Zgromadzenia i wszystkie święte naczynia, które były w Namiocie. Przenieśli je kapłani i Lewici.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 5, 'Król Salomon i całe zgromadzenie Izraela zebrane u niego przed arką złożyli wraz z nim w ofierze owce i woły, których nie można było liczyć ani spisać z powodu wielkiej liczby.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 6, 'Następnie kapłani wnieśli arkę przymierza Pana na jej miejsce do wnętrza domu, do Miejsca Najświętszego, pod skrzydła cherubinów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 7, 'Cherubiny bowiem miały rozpostarte skrzydła nad miejscem arki i okrywały od góry arkę i jej drążki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 8, 'I powyciągali drążki, tak że ich końce było widać z Miejsca Świętego przed Miejscem Najświętszym, ale nie były widoczne na zewnątrz. I są tam aż do dziś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 9, 'W arce nie było nic oprócz dwóch kamiennych tablic, które Mojżesz włożył do niej na Horebie, gdy Pan zawarł przymierze z synami Izraela po ich wyjściu z Egiptu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 10, 'A gdy kapłani wyszli z Miejsca Świętego, obłok napełnił dom Pana;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 11, 'Tak że kapłani nie mogli pozostać i pełnić służby z powodu tego obłoku, bo chwała Pana napełniła dom Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 12, 'Wtedy przemówił Salomon: Pan powiedział, że będzie mieszkać w mroku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 13, 'Już zbudowałem ci dom na mieszkanie – miejsce, w którym będziesz przebywać na wieki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 14, 'Potem król obrócił swą twarz i błogosławił całemu zgromadzeniu Izraela, a całe zgromadzenie Izraela stało.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 15, 'I przemówił: Błogosławiony niech będzie Pan, Bóg Izraela, który swymi ustami mówił do mego ojca Dawida i swą ręką wypełnił to, co obiecał:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 16, 'Od dnia, w którym wyprowadziłem swój lud Izraela z Egiptu, nie wybrałem żadnego miasta spośród wszystkich pokoleń Izraela do zbudowania domu, by moje imię tam przebywało. Lecz wybrałem Dawida, aby był postawiony nad moim ludem Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 17, 'Dawid, mój ojciec, postanowił w swoim sercu, że zbuduje dom dla imienia Pana, Boga Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 18, 'Lecz Pan powiedział do mego ojca Dawida: Ponieważ postanowiłeś w swoim sercu, by zbudować dom dla mojego imienia, dobrze uczyniłeś, że tak postanowiłeś w sercu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 19, 'Nie ty jednak będziesz budował ten dom, ale twój syn, który wyjdzie z twoich bioder, on zbuduje dom dla mego imienia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 20, 'Pan wypełnił swoje słowo, które powiedział. A ja powstałem w miejsce Dawida, swego ojca, i usiadłem na tronie Izraela, jak Pan zapowiedział, i zbudowałem dom dla imienia Pana, Boga Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 21, 'I przeznaczyłem tam miejsce dla arki, w której znajduje się przymierze Pana, które zawarł z naszymi ojcami, gdy wyprowadził ich z ziemi Egiptu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 22, 'Następnie Salomon stanął przed ołtarzem Pana wobec całego zgromadzenia Izraela i wyciągnął swoje ręce ku niebu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 23, 'I powiedział: Panie, Boże Izraela, nie ma Boga w górze na niebie ani w dole na ziemi podobnego tobie, który przestrzegałby przymierza i miłosierdzia wobec swoich sług, którzy postępują przed tobą całym swoim sercem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 24, 'Dotrzymałeś swojemu słudze Dawidowi, memu ojcu, tego, co mu obiecałeś. Swoimi ustami to powiedziałeś i swoją ręką to wypełniłeś, jak to jest dziś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 25, 'Teraz więc, Panie, Boże Izraela, dotrzymaj swemu słudze Dawidowi, memu ojcu, obietnicy, którą mu dałeś, kiedy mówiłeś: Nie zabraknie ci przede mną potomka, który zasiadałby na tronie Izraela, jeśli tylko twoi synowie będą strzec swej drogi, postępując przede mną tak, jak ty postępowałeś przede mną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 26, 'A teraz, Boże Izraela, proszę, niech będzie potwierdzone twoje słowo, które wypowiedziałeś do swego sługi Dawida, mego ojca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 27, 'Czyż naprawdę jednak Bóg zamieszka na ziemi? Oto niebiosa i niebiosa niebios nie mogą cię ogarnąć, a cóż dopiero ten dom, który zbudowałem?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 28, 'Zważ na modlitwę swego sługi i na jego prośbę, Panie, mój Boże, wysłuchaj wołania i modlitwy, które twój sługa zanosi dziś do ciebie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 29, 'Aby twoje oczy były otwarte nad tym domem w nocy i we dnie, nad tym miejscem, o którym powiedziałeś: Tam będzie moje imię; abyś wysłuchał modlitwy, którą w tym miejscu zanosi twój sługa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 30, 'Wysłuchaj prośby swego sługi i swego ludu Izraela, gdy będą się modlić w tym miejscu. Wysłuchaj z miejsca swojego zamieszkania – z nieba, a gdy wysłuchasz, przebacz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 31, 'Jeśli ktoś zgrzeszy przeciw swemu bliźniemu, a ten zobowiąże go do przysięgi, a ta przysięga przyjdzie przed twój ołtarz w tym domu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 32, 'Ty wysłuchaj w niebie, racz działać i osądź swoje sługi, potępiaj niegodziwego, sprowadzając mu na głowę jego czyny, a usprawiedliwiaj sprawiedliwego, oddając mu według jego sprawiedliwości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 33, 'Gdy twój lud Izraela zostanie pobity przez wroga za to, że zgrzeszył przeciw tobie, a nawróci się do ciebie, wyzna twoje imię i będzie się modlić, i błagać cię w tym domu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 34, 'Ty wysłuchaj w niebie i przebacz grzech swemu ludowi Izraela, i przyprowadź ich znów do ziemi, którą dałeś ich ojcom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 35, 'Kiedy niebo będzie zamknięte i nie będzie deszczu z powodu tego, że zgrzeszyli przeciwko tobie, ale będą się modlić w tym miejscu i wyznawać twoje imię, i odwrócą się od swoich grzechów, bo ich upokorzyłeś;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 36, 'Ty wysłuchaj z nieba i przebacz grzech swoich sług i swego ludu Izraela, naucz ich dobrej drogi, po której mają kroczyć, i spuść deszcz na swoją ziemię, którą dałeś swojemu ludowi w dziedzictwo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 37, 'Jeśli będzie w ziemi głód, jeśli będzie zaraza, susza, rdza, szarańcza lub robactwo, jeśli jego wróg będzie go uciskał w ziemi jego zamieszkania, jeśli będzie jakakolwiek plaga lub choroba;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 38, 'Wszelkiej modlitwy i wszelkiego błagania, jakie zaniesie jakikolwiek człowiek lub cały twój lud Izraela, kto tylko uzna plagę swego serca i wyciągnie swoje ręce ku temu domowi;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 39, 'Wtedy ty wysłuchaj w niebie, w miejscu swego zamieszkania, i przebacz, racz działać i oddaj każdemu według wszystkich jego dróg, bo ty znasz jego serce – gdyż jedynie ty znasz serca wszystkich synów ludzkich;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 40, 'Aby się ciebie bali po wszystkie dni, które będą żyć na ziemi, którą dałeś naszym ojcom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 41, 'Również i cudzoziemca, który nie jest z twego ludu Izraela, a jednak przybędzie z dalekiej ziemi przez wzgląd na twoje imię;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 42, '(Usłyszą bowiem o twoim wielkim imieniu, twojej mocnej ręce i twoim wyciągniętym ramieniu), gdy przyjdzie i będzie się modlić ku temu domowi;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 43, 'Ty wysłuchaj w niebie, w miejscu swego zamieszkania, i uczyń wszystko, o co ten cudzoziemiec będzie do ciebie wołać, aby wszystkie narody ziemi poznały twoje imię i bały się ciebie tak, jak twój lud Izraela, i aby wiedziały, że twoje imię jest wzywane nad tym domem, który zbudowałem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 44, 'Jeśli twój lud wyruszy na wojnę przeciwko swemu wrogowi drogą, którą go poślesz, i będzie się modlić do Pana, zwracając się ku miastu, które wybrałeś, i ku domowi, który zbudowałem dla twego imienia;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 45, 'To wysłuchaj w niebie ich modlitwy i błagania i broń ich sprawy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 46, 'Jeśli zgrzeszą przeciw tobie – bo nie ma człowieka, który by nie zgrzeszył – i rozgniewasz się na nich, i podasz ich wrogowi, który uprowadzi ich w niewolę, do ziemi nieprzyjaciół, dalekiej czy bliskiej;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 47, 'Lecz jeśli wezmą to do serca w tej ziemi, do której zostali uprowadzeni w niewolę, i odwrócą się, i będą cię błagać w ziemi tych, którzy ich pojmali, mówiąc: Zgrzeszyliśmy i postąpiliśmy przewrotnie, popełniliśmy niegodziwość;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 48, 'I zawrócą do ciebie całym swym sercem i całą swą duszą, w ziemi swoich wrogów, którzy ich pojmali, i będą się modlić do ciebie zwróceni ku swojej ziemi, którą dałeś ich ojcom, ku miastu, które wybrałeś, i ku domowi, który zbudowałem dla twego imienia;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 49, 'Wtedy wysłuchaj w niebie, w miejscu swego zamieszkania, ich modlitwy i ich prośby i broń ich sprawy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 50, 'Przebacz swemu ludowi, który zgrzeszył przeciw tobie, i wszystkie ich występki, które popełnili przeciw tobie, a skłoń do miłosierdzia tych, którzy ich pojmali, aby zmiłowali się nad nimi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 51, 'Są bowiem twoim ludem i twoim dziedzictwem, które wyprowadziłeś z Egiptu, z wnętrza pieca do wytopu żelaza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 52, 'Niech twoje oczy będą otwarte na prośbę twego sługi i na prośbę twego ludu Izraela, abyś ich wysłuchał we wszystkim, o co będą wołać do ciebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 53, 'Ty bowiem oddzieliłeś je sobie od wszystkich narodów ziemi na dziedzictwo, jak to powiedziałeś przez swego sługę Mojżesza, gdy wyprowadziłeś naszych ojców z Egiptu, o Panie Boże!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 54, 'Gdy Salomon skończył zanosić do Pana wszystkie te modlitwy i prośby, powstał sprzed ołtarza Pana, gdzie klęczał, i ręce wyciągał ku niebu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 55, 'Stanął i błogosławił całe zgromadzenie Izraela, mówiąc donośnym głosem:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 56, 'Błogosławiony niech będzie Pan, który dał odpoczynek swemu ludowi Izraela, zgodnie z tym wszystkim, co powiedział. Nie uchybił jednemu słowu ze wszystkich swoich dobrych obietnic, które wypowiedział przez swego sługę Mojżesza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 57, 'Niech Pan, nasz Bóg, będzie z nami, jak był z naszymi ojcami. Niech nas nie opuści ani nas nie porzuci;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 58, 'Niech skłoni ku sobie nasze serca, abyśmy kroczyli wszystkimi jego drogami i strzegli jego przykazań, nakazów i praw, które rozkazał naszym ojcom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 59, 'A niech te moje słowa, którymi wyraziłem swoje błaganie przed Panem, będą bliskie Panu, naszemu Bogu we dnie i w nocy, aby bronił sprawy swego sługi i sprawy swego ludu Izraela, według potrzeby każdego dnia;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 60, 'Żeby wszystkie narody ziemi poznały, że Pan jest Bogiem, a innego nie ma.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 61, 'Niech więc wasze serce będzie doskonałe wobec Pana, naszego Boga, abyście postępowali według jego nakazów i przestrzegali jego przykazań tak jak dzisiaj.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 62, 'Potem król, a z nim cały Izrael, złożyli ofiary przed Panem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 63, 'Salomon złożył jako ofiarę pojednawczą, którą ofiarował Panu, dwadzieścia dwa tysiące wołów i sto dwadzieścia tysięcy owiec. Tak król i wszyscy synowie Izraela poświęcili dom Panu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 64, 'W tym samym dniu król poświęcił środkową część dziedzińca, która była przed domem Pana. Tam bowiem złożył całopalenia, ofiary z pokarmów i tłuszcz ofiar pojednawczych, ponieważ ołtarz z brązu, który znajdował się przed Panem, był zbyt mały, aby pomieścić całopalenia, ofiary z pokarmów i tłuszcz ofiar pojednawczych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 65, 'W tym czasie Salomon, a wraz z nim cały Izrael, wielkie zgromadzenie od wejścia do Chamat aż do rzeki Egiptu, obchodzili święto przed Panem, naszym Bogiem, przez siedem dni i przez siedem dni, razem czternaście dni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 66, 'A w ósmym dniu odprawił lud. Błogosławili króla i rozeszli się do swoich namiotów radośni i ciesząc się w swoich sercach z powodu całego dobra, które Pan wyświadczył Dawidowi, swemu słudze, oraz Izraelowi, swemu ludowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 1, 'Kiedy Salomon ukończył budowę domu Pana i domu królewskiego oraz wszystkiego, czego pragnął i co chciał wykonać;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 2, 'Pan ukazał się Salomonowi po raz drugi, podobnie jak mu się ukazał w Gibeonie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 3, 'Pan przemówił do niego: Wysłuchałem twojej modlitwy i prośby, które zanosiłeś przede mną. Poświęciłem ten dom, który zbudowałeś, aby tam przebywało moje imię na wieki. Tam będą moje oczy i serce po wszystkie dni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 4, 'A jeśli będziesz postępował wobec mnie tak, jak postępował twój ojciec Dawid, w doskonałości serca i prawości, i będziesz czynił wszystko, co ci nakazałem, i będziesz przestrzegał moich nakazów i praw;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 5, 'Wtedy utwierdzę tron twego królestwa nad Izraelem na wieki, jak obiecałem Dawidowi, twemu ojcu, mówiąc: Nie zabraknie ci potomka na tronie Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 6, 'Jeśli jednak wy lub wasi synowie zupełnie odwrócicie się ode mnie i nie będziecie strzec moich przykazań i nakazów, które wam dałem, ale pójdziecie służyć innym bogom, i będziecie im oddawać pokłon;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 7, 'Wtedy wytracę Izraela z ziemi, którą mu dałem, a dom, który poświęciłem swojemu imieniu, odrzucę sprzed swojego oblicza. Izrael zaś będzie przedmiotem przypowieści i pośmiewiskiem u wszystkich narodów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 8, 'A temu domowi, który był wyniosły, każdy przechodzący obok zdziwi się i świśnie. I będą pytać: Dlaczego Pan uczynił tak tej ziemi i temu domowi?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 9, 'Wtedy odpowiedzą: Ponieważ opuścili Pana, swego Boga, który wyprowadził ich ojców z ziemi Egiptu, a uchwycili się innych bogów, oddawali im pokłon i służyli im. Dlatego Pan sprowadził na nich całe to nieszczęście.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 10, 'A po upływie dwudziestu lat, w czasie których Salomon zbudował oba domy, dom Pana i dom królewski;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 11, '(A Hiram, król Tyru, dostarczał Salomonowi drzew cedrowych i drzew cyprysowych, i złota, ile tylko chciał), król Salomon dał Hiramowi dwadzieścia miast w ziemi galilejskiej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 12, 'Hiram wyruszył więc z Tyru, aby obejrzeć miasta, które dał mu Salomon, ale mu się nie spodobały.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 13, 'I zapytał: Cóż to za miasta, które mi dałeś, mój bracie? I nazwał je ziemią Kabul, i nazywają się tak aż do dziś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 14, 'Hiram bowiem posłał królowi sto dwadzieścia talentów złota.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 15, 'A to była przyczyna poboru do robót, który król Salomon rozkazał na budowę domu Pana, swojego domu, Millo, muru Jerozolimy, Chasor, Megiddo i Gezer.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 16, 'Faraon bowiem, król Egiptu, wyruszył i zdobył Gezer, i spalił je ogniem, a Kananejczyków, którzy mieszkali w tym mieście, wymordował, i dał je w posagu swojej córce, żonie Salomona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 17, 'Salomon odbudował więc Gezer i Bet-Choron dolne;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 18, 'Baalat i Tadmor na pustyni w tej ziemi;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 19, 'I wszystkie miasta spichlerze, które należały do Salomona, miasta dla rydwanów i miasta dla jeźdźców oraz wszystko, co Salomon pragnął wybudować w Jerozolimie, Libanie i całej ziemi swego panowania.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 20, 'Wszystkie ludy, które ocalały spośród Amorytów, Chetytów, Peryzzytów, Chiwwitów i Jebusytów, które nie były z synów Izraela;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 21, 'Mianowicie potomstwo tych, którzy pozostali po nich w ziemi, których synowie Izraela nie mogli wytracić, Salomon obciążył pracą przymusową aż do dziś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 22, 'Lecz spośród synów Izraela Salomon nikogo nie uczynił niewolnikiem, byli tylko żołnierzami, jego sługami, dostojnikami, oficerami oraz dowódcami jego rydwanów i jeźdźców.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 23, 'Naczelnych przełożonych, którzy nadzorowali pracę dla Salomona, było pięciuset pięćdziesięciu. Oni to kierowali ludźmi, którzy wykonywali pracę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 24, 'Gdy tylko córka faraona przeprowadziła się z miasta Dawida do swego domu, który jej zbudował Salomon, wtedy zbudował Millo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 25, 'Trzy razy w roku Salomon składał całopalenia i ofiary pojednawcze na ołtarzu, który zbudował dla Pana, a spalał kadzidło na ołtarzu, który był przed Panem. Tak ukończył dom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 26, 'Król Salomon zbudował też okręty w Esjon-Geber koło Elat, nad brzegiem Morza Czerwonego, w ziemi Edomu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 27, 'I Hiram posłał na tych okrętach swoje sługi, żeglarzy obeznanych z morzem, razem ze sługami Salomona;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 28, 'Przypłynęli oni do Ofiru i wzięli stamtąd czterysta dwadzieścia talentów złota, i przywieźli je do króla Salomona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 1, 'A gdy królowa Saby usłyszała o sławie Salomona i o imieniu Pana, przybyła, aby go przez zagadki poddać próbie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 2, 'Przybyła do Jerozolimy z bardzo wielkim orszakiem, z wielbłądami niosącymi wonności, bardzo dużo złota i drogocenne kamienie. Gdy przyszła do Salomona, rozmawiała z nim o wszystkim, co leżało jej na sercu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 3, 'Salomon zaś odpowiedział na wszystkie jej pytania. Nie było nic nieznanego królowi, czego nie mógłby jej odpowiedzieć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 4, 'Gdy więc królowa Saby ujrzała całą mądrość Salomona i dom, który zbudował;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 5, 'A także potrawy jego stołu, siadanie jego sług, stawanie jego służących, ich szaty, jego podczaszych oraz schody, po których wstępował do domu Pana, dech zamarł jej w piersi;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 6, 'Wtedy przemówiła do króla: Prawdziwa była ta wieść, którą słyszałam w swojej ziemi o twoich dziełach i twojej mądrości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 7, 'Jednak nie wierzyłam tym słowom, aż przybyłam i zobaczyłam to na własne oczy. I oto nie powiedziano mi nawet połowy. Twoja mądrość i twój dobrobyt są większe od sławy, o której słyszałam.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 8, 'Błogosławieni twoi ludzie, błogosławieni twoi słudzy, którzy zawsze stoją przed tobą i słuchają twojej mądrości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 9, 'Niech będzie błogosławiony Pan, twój Bóg, który cię sobie upodobał, aby cię posadzić na tronie Izraela; a ponieważ Pan umiłował Izraela na wieki, ustanowił cię królem, abyś czynił sąd i sprawiedliwość.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 10, 'Następnie dała królowi sto dwadzieścia talentów złota i bardzo wiele wonności oraz drogocennych kamieni. Nigdy więcej nie przyniesiono tyle wonności, ile królowi Salomonowi dała królowa Saby.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 11, 'Ponadto okręty Hirama, które przywoziły złoto z Ofiru, przywiozły także z Ofiru wielką ilość drewna sandałowego i drogocennych kamieni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 12, 'Z tego drzewa sandałowego król wykonał schody do domu Pana i do domu królewskiego oraz harfy i cytry dla śpiewaków. Nigdy nie sprowadzono takiego drzewa sandałowego i nie widziano aż do dziś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 13, 'Król Salomon zaś dał królowej Saby wszystko, czego zapragnęła i o co poprosiła, nie licząc tego, co jej dał ze swojej królewskiej hojności. Potem odjechała i wróciła do swojej ziemi razem ze swoimi sługami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 14, 'A waga złota, które wpływało do Salomona w ciągu jednego roku, wynosiła sześćset sześćdziesiąt sześć talentów złota;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 15, 'Nie licząc tego, co dostawał od kupców i handlarzy wonności, i od wszystkich królów arabskich oraz namiestników ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 16, 'Król Salomon wykonał więc dwieście tarcz z kutego złota. Na każdą tarczę wychodziło sześćset syklów złota.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 17, 'Wykonał także trzysta puklerzy z kutego złota, używając po trzy miny złota na każdy puklerz. Król umieścił je w domu lasu Libanu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 18, 'Król również sporządził wielki tron z kości słoniowej i pokrył go czystym złotem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 19, 'Tron miał sześć stopni i okrągły szczyt z tyłu. Po obu stronach siedzenia były poręcze, a przy poręczach stały dwa lwy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 20, 'Dwanaście lwów stało na tych sześciu stopniach po obu stronach. Czegoś takiego nie uczyniono w żadnym innym królestwie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 21, 'Wszystkie naczynia, których król Salomon używał do picia, były ze złota, a także wszystkie naczynia domu lasu Libanu były ze szczerego złota. Nie było nic ze srebra, gdyż nie uważano go za cenne w czasach Salomona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 22, 'Królewska flota Tarszisz była bowiem na morzu wraz z flotą Hirama. Raz na trzy lata przypływała flota Tarszisz, przywożąc złoto, srebro, kość słoniową, małpy i pawie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 23, 'Tak więc król Salomon przewyższał wszystkich królów ziemi bogactwem i mądrością.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 24, 'I cała ziemia pragnęła zobaczyć Salomona, aby słuchać jego mądrości, którą Bóg włożył w jego serce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 25, 'Każdy przynosił mu swoje dary: srebrne i złote naczynia, szaty, zbroje, wonności, konie i muły, rokrocznie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 26, 'Salomon nagromadził rydwanów i jeźdźców, tak że miał tysiąc czterysta rydwanów i dwanaście tysięcy jeźdźców, których rozmieścił po miastach rydwanów oraz przy sobie w Jerozolimie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 27, 'Król sprawił, że srebro w Jerozolimie było jak kamienie, a cedry tak liczne jak sykomory na nizinie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 28, 'Sprowadzono też dla Salomona konie z Egiptu i nić lnianą. A kupcy królewscy brali nić lnianą za ustaloną cenę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 29, 'Rydwan wywożono i sprowadzono z Egiptu za sześćset srebrników, a konia – za sto pięćdziesiąt. W ten sposób wszyscy królowie chetyccy i królowie Syrii dostawali je za ich pośrednictwem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 1, 'Król Salomon jednak oprócz córki faraona kochał wiele obcych kobiet: Moabitki, Ammonitki, Edomitki, Sydonitki i Chetytki;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 2, 'Spośród tych narodów, o których Pan powiedział synom Izraela: Nie łączcie się z nimi i niech one nie łączą się z wami; z pewnością bowiem skłonią wasze serca ku swoim bogom. Salomon przylgnął do nich miłością.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 3, 'Miał więc siedemset żon, księżniczek, i trzysta nałożnic. A jego żony odwiodły jego serce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 4, 'Gdy bowiem Salomon się zestarzał, jego żony skłoniły jego serce ku innym bogom. Jego serce nie było więc doskonałe wobec Pana, jego Boga, jak serce Dawida, jego ojca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 5, 'Salomon bowiem poszedł za Asztartą, boginią Sydończyków, i za Milkomem, obrzydliwością Ammonitów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 6, 'Salomon więc czynił to, co złe w oczach Pana, i nie chodził całkowicie za Panem jak Dawid, jego ojciec.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 7, 'Wówczas Salomon zbudował wyżynę dla Kemosza, obrzydliwości Moabu, na górze naprzeciwko Jerozolimy, oraz dla Molocha, obrzydliwości synów Ammona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 8, 'Podobnie uczynił dla wszystkich swoich żon obcej narodowości, które spalały kadzidła i składały ofiary swoim bogom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 9, 'Pan rozgniewał się więc na Salomona za to, że jego serce odwróciło się od Pana, Boga Izraela, który dwukrotnie mu się ukazał;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 10, 'I zakazał mu chodzić za innymi bogami. Lecz on nie przestrzegał tego, co Pan przykazał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 11, 'Pan powiedział więc do Salomona: Ponieważ dopuściłeś się tego i nie przestrzegałeś mojego przymierza ani moich nakazów, które ci przykazałem, na pewno wyrwę ci królestwo i dam je twemu słudze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 12, 'Lecz nie uczynię tego za twego życia ze względu na Dawida, twego ojca, ale wyrwę je z ręki twego syna.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 13, 'Nie wyrwę jednak całego królestwa. Dam jedno pokolenie twemu synowi ze względu na Dawida, mego sługę, i ze względu na Jerozolimę, którą wybrałem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 14, 'Pan wzbudził więc Salomonowi przeciwnika, Hadada Edomitę, z rodu królewskiego w Edomie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 15, 'Stało się bowiem tak, że kiedy Dawid był w Edomie, a Joab, dowódca wojska, wyruszył, aby pogrzebać zabitych, gdyż zabił wszystkich mężczyzn w Edomie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 16, '(Bo Joab mieszkał tam przez sześć miesięcy wraz z całym Izraelem, aż wytracił wszystkich mężczyzn w Edomie).');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 17, 'Hadad uciekł wraz z pewnymi Edomitami spośród sług swego ojca, aby dostać się do Egiptu; Hadad był wtedy małym chłopcem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 18, 'Wyruszyli więc z Midian i przybyli do Paran. Z Paran zabrali ze sobą mężczyzn i przybyli do Egiptu, do faraona, króla Egiptu. Ten dał mu dom, zapewnił mu żywność i dał mu ziemię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 19, 'Hadad znalazł wielką łaskę w oczach faraona, tak że ten dał mu za żonę siostrę swojej żony, siostrę królowej Tachpenes.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 20, 'Siostra Tachpenes urodziła mu syna, Genubata, którego wychowała Tachpenes w domu faraona. Genubat przebywał więc w domu faraona wśród jego synów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 21, 'A gdy Hadad usłyszał w Egipcie, że Dawid zasnął ze swoimi ojcami i że umarł Joab, dowódca wojska, wtedy powiedział do faraona: Pozwól mi wrócić do swojej ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 22, 'Faraon zapytał go: Czego ci u mnie brakuje, że chcesz wrócić do swojej ziemi? Odpowiedział: Niczego. Pozwól mi jednak wrócić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 23, 'Bóg wzbudził mu też przeciwnika w osobie Rezona, syna Eliady, który uciekł od swego pana Hadadezera, króla Soby.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 24, 'Zebrał on wokół siebie ludzi i został przywódcą zgrai, gdy Dawid pobił mieszkańców z Soby. Potem udali się do Damaszku, gdzie mieszkali, a potem panowali nad Damaszkiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 25, 'Był on przeciwnikiem Izraela przez wszystkie dni Salomona, oprócz tego zła, jakie wyrządził mu Hadad. Znienawidził Izraela, gdy został królem Syrii.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 26, 'Jeroboam, syn Nebata Efratejczyka z Seredy i sługa Salomona, którego matka miała na imię Serua i była wdową, również podniósł rękę przeciw królowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 27, 'A taka była przyczyna, dla której podniósł rękę przeciwko królowi: Salomon zbudował Millo i zamknął wyłomy w mieście Dawida, swego ojca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 28, 'A Jeroboam był dzielnym wojownikiem. Gdy Salomon zauważył, że młodzieniec dobrze wykonuje swoją pracę, ustanowił go przełożonym nad wszystkimi sprawami domu Józefa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 29, 'I zdarzyło się w tym czasie, gdy Jeroboam wyszedł z Jerozolimy, że spotkał go na drodze prorok Achiasz Szilonita, odziany w nowy płaszcz. I ci dwaj byli sami na polu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 30, 'Wtedy Achiasz chwycił nowy płaszcz, który miał na sobie, i rozdarł go na dwanaście części.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 31, 'I powiedział do Jeroboama: Weź sobie dziesięć części. Tak bowiem mówi Pan, Bóg Izraela: Oto wyrwę królestwo z ręki Salomona, a tobie dam dziesięć pokoleń.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 32, 'Jemu zaś pozostanie jedno pokolenie ze względu na mego sługę Dawida i ze względu na Jerozolimę, miasto, które wybrałem spośród wszystkich pokoleń Izraela;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 33, 'Dlatego że opuścili mnie i oddali pokłon Asztarcie, bogini Sydończyków, Kemoszowi, bogu Moabitów, i Milkomowi, bogu synów Ammona, a nie chodzili moimi drogami, aby czynić to, co prawe w moich oczach, i przestrzegać moich nakazów i praw, jak to czynił Dawid, jego ojciec.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 34, 'Nie odbiorę całego królestwa z jego ręki, ale pozostawię go księciem po wszystkie dni jego życia ze względu na Dawida, swego sługę, którego wybrałem i który przestrzegał moich przykazań i nakazów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 35, 'Zabiorę natomiast królestwo z ręki jego syna i dam je tobie – dziesięć pokoleń.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 36, 'A jego synowi dam jedno pokolenie, aby Dawid, mój sługa, miał po wszystkie dni pochodnię przede mną w Jerozolimie, w mieście, które sobie wybrałem, aby tam przebywało moje imię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 37, 'Ciebie zaś wezmę i będziesz panował nad wszystkim, czego zapragnie twoja dusza, i będziesz królem nad Izraelem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 38, 'Jeśli więc będziesz słuchał wszystkiego, co ci rozkażę, i będziesz kroczył moimi drogami, i czynił to, co prawe w moich oczach, i przestrzegał moich nakazów i przykazań, jak czynił mój sługa Dawid, wtedy będę z tobą, zbuduję ci dom trwały, jak zbudowałem Dawidowi, i powierzę ci Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 39, 'Dlatego upokorzę potomstwo Dawida, jednak nie po wszystkie dni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 40, 'Salomon usiłował więc zabić Jeroboama, ale Jeroboam wstał i uciekł do Egiptu, do Sziszaka, króla Egiptu. I pozostał w Egipcie aż do śmierci Salomona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 41, 'A pozostałe dzieje Salomona oraz wszystko, co czynił, i jego mądrość, czy nie są zapisane w księdze dziejów Salomona?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 42, 'A czas, w którym Salomon panował w Jerozolimie nad całym Izraelem, obejmował czterdzieści lat.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 43, 'I Salomon zasnął ze swymi ojcami i został pogrzebany w mieście Dawida, swego ojca. I jego syn Roboam królował w jego miejsce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 1, 'Roboam udał się do Sychem, gdyż do Sychem przybył cały Izrael, aby ustanowić go królem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 2, 'I gdy usłyszał o tym Jeroboam, syn Nebata, który był jeszcze w Egipcie (bo uciekł przed królem Salomonem i zamieszkał w Egipcie);');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 3, 'Posłano po niego i wezwano go. Jeroboam oraz całe zgromadzenie Izraela przybyli więc i przemówili do Roboama:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 4, 'Twój ojciec włożył na nas ciężkie jarzmo. Teraz więc ty ulżyj nam w srogiej służbie swego ojca i w jego ciężkim jarzmie, które włożył na nas, a będziemy ci służyć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 5, 'Odpowiedział im: Odejdźcie i wróćcie do mnie po trzech dniach. I lud odszedł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 6, 'Wtedy król Roboam radził się starszych, którzy stawali przed Salomonem, jego ojcem, gdy jeszcze żył, i zapytał: Jak doradzacie odpowiedzieć temu ludowi?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 7, 'Odpowiedzieli mu: Jeśli dziś staniesz się sługą tego ludu i będziesz mu służył, a dając odpowiedź, będziesz mówił do nich łagodne słowa, to będą twoimi sługami przez wszystkie dni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 8, 'Ale on odrzucił radę starszych, którą mu dali, i radził się młodzieńców, którzy razem z nim wzrośli i którzy stawali przed nim;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 9, 'I zapytał ich: A co wy radzicie odpowiedzieć temu ludowi, który poprosił mnie: Ulżyj nam w jarzmie, które włożył na nas twój ojciec.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 10, 'Wtedy młodzieńcy, którzy razem z nim wzrośli, odpowiedzieli mu: Tak odpowiesz temu ludowi, który mówił do ciebie: Twój ojciec włożył na nas ciężkie jarzmo, ale ty ulżyj nam; tak im powiesz: Mój mały palec jest grubszy niż biodra mojego ojca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 11, 'Teraz więc, chociaż mój ojciec nałożył na was ciężkie jarzmo, ja dołożę do waszego jarzma. Mój ojciec karcił was biczami, ale ja będę was karcił skorpionami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 12, 'Przyszedł więc Jeroboam i cały lud do Roboama trzeciego dnia, tak jak król nakazał, mówiąc: Wróćcie do mnie na trzeci dzień.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 13, 'I król dał ludowi surową odpowiedź, gdyż odrzucił radę starszych, którą mu dali;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 14, 'I przemówił do niego według rady młodzieńców, mówiąc: Mój ojciec obciążył was ciężkim jarzmem, ale ja dołożę do waszego jarzma. Mój ojciec karcił was biczami, ale ja będę was karcił skorpionami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 15, 'Król nie usłuchał więc ludu. Sprawa bowiem wyszła od Pana, aby spełnił swoje słowo, które Pan wypowiedział przez Achiasza Szilonitę do Jeroboama, syna Nebata.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 16, 'A gdy cały Izrael zobaczył, że król go nie usłuchał, lud odpowiedział królowi: Jakiż dział mamy w Dawidzie? Nie mamy dziedzictwa w synu Jessego. Do swoich namiotów, o Izraelu! A ty, Dawidzie, troszcz się teraz o swój dom. I rozszedł się Izrael do swoich namiotów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 17, 'Roboam zaś królował tylko nad synami Izraela, którzy mieszkali w miastach Judy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 18, 'Wtedy król Roboam posłał Adorama, który był poborcą, ale cały Izrael ukamienował go tak, że umarł. Król Roboam wsiadł więc w pośpiechu na rydwan i uciekł do Jerozolimy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 19, 'W ten sposób Izrael zbuntował się przeciwko domowi Dawida i trwa to aż do dziś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 20, 'Gdy cały Izrael usłyszał o tym, że Jeroboam wrócił, posłali po niego, wezwali go do zgromadzenia i ustanowili go królem nad całym Izraelem. Przy domu Dawida nie pozostał nikt oprócz pokolenia Judy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 21, 'A gdy Roboam przybył do Jerozolimy, zebrał cały dom Judy i pokolenie Beniamina, razem sto osiemdziesiąt tysięcy doborowych wojowników, aby walczyć z domem Izraela i przywrócić królestwo Roboamowi, synowi Salomona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 22, 'Lecz słowo Boże doszło do Szemajasza, męża Bożego:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 23, 'Powiedz Roboamowi, synowi Salomona, królowi Judy, całemu domowi Judy i Beniamina i reszcie ludu:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 24, 'Tak mówi Pan: Nie wyruszajcie ani nie walczcie ze swoimi braćmi, synami Izraela. Niech każdy wróci do swego domu, bo ta rzecz wyszła ode mnie. I posłuchali rozkazu Pana, i wrócili zgodnie ze słowem Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 25, 'Potem Jeroboam zbudował Sychem na górze Efraim i zamieszkał w nim. Następnie wyszedł stamtąd i zbudował Penuel.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 26, 'Wtedy Jeroboam powiedział sobie w sercu: Wkrótce królestwo powróci do domu Dawida;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 27, 'Bo jeśli lud będzie chodził na składanie ofiary do domu Pana w Jerozolimie, to serce tego ludu zwróci się do swego pana, do Roboama, króla Judy. Zabiją mnie i powrócą do Roboama, króla Judy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 28, 'Król zasięgnął więc rady, po czym sporządził dwa złote cielce i powiedział ludowi: Dość już waszego chodzenia do Jerozolimy. Oto twoi bogowie, Izraelu, którzy cię wyprowadzili z ziemi Egiptu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 29, 'I postawił jednego w Betel, a drugiego umieścił w Dan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 30, 'I stało się to przyczyną grzechu, bo lud chodził do jednego z nich, aż do Dan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 31, 'Pobudował też dom na wyżynach i ustanowił kapłanów spośród pospólstwa, którzy nie pochodzili od synów Lewiego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 32, 'Następnie Jeroboam ustanowił święto w ósmym miesiącu, piętnastego dnia tego miesiąca, na wzór święta, które obchodzono w Judzie, i składał ofiary na ołtarzu. Tak uczynił w Betel, składając ofiary cielcom, które sporządził. Ustanowił też w Betel kapłanów wyżyn, które pobudował.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 33, 'Tak więc składał ofiary na ołtarzu, który sporządził w Betel, piętnastego dnia ósmego miesiąca, w tym miesiącu, który sobie wymyślił, i ustanowił święto dla synów Izraela. I przystąpił do ołtarza, aby spalić kadzidło.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 1, 'A gdy Jeroboam stał przy ołtarzu, aby spalić kadzidło, oto mąż Boży przyszedł z Judy do Betel na słowo Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 2, 'I na słowo Pana zawołał przeciw ołtarzowi: Ołtarzu, ołtarzu, tak mówi Pan: Oto domowi Dawida urodzi się syn imieniem Jozjasz. Ten złoży na tobie kapłanów wyżyn spalających na tobie kadzidła i na tobie spalą kości ludzkie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 3, 'I dał znak tego samego dnia, mówiąc: Taki jest znak, że Pan to powiedział: Oto ołtarz rozpadnie się i rozsypie się popiół, który jest na nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 4, 'A gdy król Jeroboam usłyszał słowo męża Bożego, który zawołał przeciw ołtarzowi w Betel, wyciągnął rękę znad ołtarza, mówiąc: Schwytajcie go. I uschła jego ręka, którą wyciągnął przeciw niemu, i nie mógł jej cofnąć ku sobie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 5, 'Ołtarz zaś rozpadł się, a popiół rozsypał się z ołtarza zgodnie ze znakiem, który dał mąż Boży na słowo Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 6, 'Wtedy król zwrócił się do męża Bożego: Przebłagaj oblicze Pana, swego Boga, i módl się za mnie, aby moja ręka wróciła do mnie. Mąż Boży przebłagał Pana i ręka króla wróciła do niego, i była jak poprzednio.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 7, 'Następnie król poprosił męża Bożego: Chodź ze mną do domu i posil się, a złożę ci dar.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 8, 'Lecz mąż Boży odpowiedział królowi: Choćbyś mi dał połowę swego domu, nie pójdę z tobą ani nie będę jadł chleba, ani pił wody w tym miejscu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 9, 'Tak bowiem mi rozkazano na słowo Pana: Nie będziesz jadł chleba ani nie będziesz pił wody, ani nie wrócisz tą drogą, którą przyszedłeś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 10, 'Poszedł więc inną drogą i nie wrócił tą drogą, którą przyszedł do Betel.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 11, 'A mieszkał w Betel pewien stary prorok. Przyszli do niego jego synowie i opowiedzieli mu o wszystkich czynach, których w tym dniu dokonał mąż Boży w Betel. Powtórzyli też swojemu ojcu słowa, które wypowiedział do króla.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 12, 'Ich ojciec zapytał ich: Którą drogą poszedł? Jego synowie bowiem widzieli, którą drogą poszedł mąż Boży, który przyszedł z Judy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 13, 'I powiedział swoim synom: Osiodłajcie mi osła. Osiodłali mu więc osła i wsiadł na niego;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 14, 'I podążył za mężem Bożym, a gdy znalazł go siedzącego pod dębem, zapytał go: Czy ty jesteś tym mężem Bożym, który przyszedł z Judy? Odpowiedział: Jestem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 15, 'Wtedy powiedział do niego: Chodź ze mną do domu, abyś się posilił chlebem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 16, 'Lecz odpowiedział mu: Nie mogę wrócić z tobą ani pójść z tobą. Nie będę jadł chleba ani pił wody z tobą w tym miejscu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 17, 'Powiedziano bowiem do mnie na słowo Pana: Nie będziesz tam jadł chleba ani pił wody, ani nie pójdziesz z powrotem tą drogą, którą szedłeś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 18, 'I odpowiedział mu: Ja również jestem prorokiem jak ty. Anioł też powiedział do mnie na słowo Pana: Zaprowadź go ze sobą do swego domu, aby jadł chleb i pił wodę. Lecz okłamał go.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 19, 'Zawrócił więc z nim i jadł chleb w jego domu oraz pił wodę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 20, 'A gdy siedzieli przy stole, doszło słowo Pana do proroka, który go zawrócił;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 21, 'I zawołał na męża Bożego, który przyszedł z Judy: Tak mówi Pan: Ponieważ byłeś nieposłuszny słowu Pana i nie przestrzegałeś rozkazu, który dał ci Pan, twój Bóg;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 22, 'Ale zawróciłeś i jadłeś chleb oraz piłeś wodę w miejscu, o którym Pan ci powiedział: Nie będziesz tam jadł chleba ani pił wody, twoje zwłoki nie będą pochowane w grobie twoich ojców.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 23, 'A gdy najadł się chleba i napił, osiodłał osła dla proroka, którego zawrócił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 24, 'A gdy ten odjechał, spotkał go lew w drodze, który go zabił. A jego zwłoki leżały porzucone na drodze i osioł stał obok nich, lew także stał przy zwłokach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 25, 'A oto pewni ludzie przechodzili i zobaczyli porzucone zwłoki na drodze oraz lwa stojącego przy nich. Przyszli więc i opowiedzieli o tym w mieście, w którym mieszkał stary prorok.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 26, 'Kiedy usłyszał o tym prorok, który go zawrócił z drogi, powiedział: To jest mąż Boży, który był nieposłuszny słowu Pana. Dlatego Pan wydał go lwu, który go rozszarpał i zabił, zgodnie ze słowem Pana, które wypowiedział do niego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 27, 'Następnie powiedział do swoich synów: Osiodłajcie mi osła. I osiodłali.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 28, 'Wtedy pojechał i znalazł jego zwłoki porzucone na drodze oraz osła i lwa stojących przy zwłokach. Lecz lew nie pożarł zwłok ani nie rozszarpał osła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 29, 'Wtedy prorok podniósł zwłoki męża Bożego, włożył je na osła i zabrał z powrotem. I stary prorok przybył do swego miasta, aby go opłakiwać i pogrzebać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 30, 'Złożył więc jego zwłoki w swoim grobie. I opłakiwali go, mówiąc: Ach, mój bracie!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 31, 'A kiedy już go pogrzebali, powiedział do swoich synów: Gdy umrę, pogrzebcie mnie w tym grobie, w którym został pogrzebany mąż Boży. Złóżcie moje kości obok jego kości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 32, 'Spełni się bowiem to, co zawołał na słowo Pana przeciw ołtarzowi w Betel i przeciwko wszystkim domom wyżyn, które znajdują się w miastach Samarii.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 33, 'Jednak po tych wydarzeniach Jeroboam nie odwrócił się od swojej złej drogi, ale znowu ustanawiał kapłanów wyżyn z pospólstwa. Kto tylko chciał, tego poświęcał i ten stawał się kapłanem wyżyn.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 34, 'Sprawa ta stała się przyczyną grzechu dla domu Jeroboama, aby został wykorzeniony i zgładzony z powierzchni ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 1, 'W tym czasie zachorował Abiasz, syn Jeroboama.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 2, 'I Jeroboam powiedział do swojej żony: Wstań teraz, przebierz się, aby nie poznano, że jesteś żoną Jeroboama, i idź do Szilo. Jest tam prorok Achiasz, który mi powiedział, że będę królem nad tym ludem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 3, 'Weź ze sobą dziesięć chlebów, placki i dzban miodu i idź do niego. On ci oznajmi, co się stanie z dzieckiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 4, 'Żona Jeroboama tak uczyniła. Wstała i poszła do Szilo, i przybyła do domu Achiasza. Lecz Achiasz już nie widział, gdyż jego oczy osłabły z powodu jego starości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 5, 'A Pan powiedział do Achiasza: Oto żona Jeroboama nadchodzi, aby dowiedzieć się czegoś od ciebie o swoim synu, gdyż jest chory. Powiesz jej tak i tak, bo gdy wejdzie, będzie udawała kogoś innego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 6, 'Gdy więc Achiasz usłyszał odgłos jej kroków, gdy wchodziła przez drzwi, powiedział: Wejdź, żono Jeroboama. Dlaczego udajesz kogoś innego? Zostałem posłany do ciebie z przykrą nowiną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 7, 'Idź, powiedz Jeroboamowi: Tak mówi Pan, Bóg Izraela: Mimo że wywyższyłem cię spośród ludu i ustanowiłem cię księciem nad moim ludem Izraelem;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 8, 'Wyrwałem domowi Dawida królestwo i dałem je tobie, ty jednak nie byłeś jak mój sługa Dawid, który przestrzegał moich przykazań i który chodził za mną całym swym sercem, czyniąc tylko to, co jest prawe w moich oczach;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 9, 'Lecz postępowałeś gorzej niż wszyscy, którzy byli przed tobą. Ty bowiem poszedłeś i uczyniłeś sobie obcych bogów i odlane posągi, aby mnie pobudzić do gniewu, mnie zaś rzuciłeś za plecy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 10, 'Dlatego sprowadzę nieszczęście na dom Jeroboama i wytępię z Jeroboama każdego, aż do najmniejszego szczenięcia, każdego więźnia i opuszczonego w Izraelu, i usunę ostatki domu Jeroboama, jak usuwa się gnój, aż do końca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 11, 'Tego, kto z domu Jeroboama umrze w mieście, zjedzą psy, a tego, kto umrze na polu, zjedzą powietrzne ptaki, ponieważ tak powiedział Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 12, 'Ty zaś wstań i idź do swego domu, a gdy wejdziesz do miasta, dziecko umrze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 13, 'I cały Izrael będzie je opłakiwał, i pogrzebie je, bo jedynie ono z domu Jeroboama zejdzie do grobu, gdyż w nim znalazło się coś dobrego względem Pana, Boga Izraela, w domu Jeroboama.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 14, 'Pan zaś ustanowi sobie króla nad Izraelem, który wytępi dom Jeroboama w tym samym dniu. A co mówię, wzbudzi? I owszem, już wzbudził.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 15, 'I Pan uderzy Izraela tak, że się zachwieje, jak się chwieje trzcina w wodzie, i wykorzeni Izraela z tej dobrej ziemi, którą dał ich ojcom, i rozproszy ich za rzeką za to, że uczynili sobie gaje, pobudzając Pana do gniewu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 16, 'I tak porzuci on Izraela z powodu grzechów Jeroboama, który grzeszył i skłonił Izraela do grzechu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 17, 'Wtedy żona Jeroboama wstała, wyruszyła i przybyła do Tirsy. Gdy przekroczyła próg domu, dziecko umarło.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 18, 'I pogrzebali je, i cały Izrael je opłakiwał zgodnie ze słowem Pana, które zapowiedział przez swego sługę, proroka Achiasza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 19, 'Pozostałe zaś dzieje Jeroboama, jak walczył i jak królował, są zapisane w kronikach o królach Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 20, 'A czas, który królował Jeroboam, wynosił dwadzieścia dwa lata. Potem zasnął ze swoimi ojcami, a jego syn Nadab królował w jego miejsce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 21, 'Roboam zaś, syn Salomona, królował w Judzie. Roboam miał czterdzieści jeden lat, gdy zaczął królować, a królował siedemnaście lat w Jerozolimie, w mieście, które Pan wybrał spośród wszystkich pokoleń Izraela, aby tam przebywało jego imię. Jego matka miała na imię Naama, była Ammonitką.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 22, 'I Juda czynił to, co złe w oczach Pana, i swoimi grzechami, które popełniali, pobudzali go do zazdrości bardziej niż to wszystko, co czynili ich ojcowie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 23, 'Pobudowali sobie bowiem wyżyny, posągi i gaje na każdym wysokim wzgórzu i pod każdym zielonym drzewem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 24, 'Byli też w tej ziemi sodomici. Postępowali oni według wszystkich obrzydliwości pogan, których Pan wypędził sprzed synów Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 25, 'A w piątym roku króla Roboama, przeciw Jerozolimie nadciągnął Sziszak, król Egiptu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 26, 'I zabrał skarby domu Pana oraz skarby domu królewskiego, zabrał wszystko. Zabrał też wszystkie złote tarcze, które wykonał Salomon.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 27, 'Zamiast nich król Roboam wykonał spiżowe tarcze i powierzył je dowódcy straży przybocznej, która strzegła drzwi domu królewskiego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 28, 'Ilekroć król wchodził do domu Pana, straż je nosiła, a potem odnosiła do wartowni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 29, 'A pozostałe dzieje Roboama i wszystko, co czynił, czyż nie są zapisane w kronikach królów Judy?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 30, 'I trwała wojna między Roboamem a Jeroboamem po wszystkie dni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 31, 'Potem Roboam zasnął ze swoimi ojcami i został pogrzebany z nimi w mieście Dawida. A jego matka miała na imię Naama, była Ammonitką. I jego syn Abijam królował w jego miejsce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 1, 'W osiemnastym roku króla Jeroboama, syna Nebata, Abijam zaczął królować nad Judą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 2, 'Trzy lata królował w Jerozolimie, a jego matka miała na imię Maaka i była córką Abiszaloma.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 3, 'Szedł on śladem wszystkich grzechów swego ojca, które popełnił przed nim. Jego serce nie było doskonałe wobec Pana, swego Boga, jak serce Dawida, jego ojca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 4, 'Jednak ze względu na Dawida Pan, jego Bóg, dał mu pochodnię w Jerozolimie, wzbudzając po nim jego syna i umacniając Jerozolimę;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 5, 'Ponieważ Dawid czynił to, co było prawe w oczach Pana, i nie odstąpił od niczego, co mu rozkazał, przez wszystkie dni swego życia, z wyjątkiem sprawy Uriasza Chetyty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 6, 'I trwała wojna między Roboamem a Jeroboamem przez wszystkie dni jego życia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 7, 'A pozostałe dzieje Abijama i wszystko, co czynił, czyż nie są zapisane w kronikach o królach Judy. I trwała wojna między Abijamem a Jeroboamem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 8, 'Potem Abijam zasnął ze swoimi ojcami i pogrzebano go w mieście Dawida. I jego syn Asa królował w jego miejsce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 9, 'W dwudziestym roku Jeroboama, króla Izraela, Asa królował nad Judą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 10, 'I królował czterdzieści jeden lat w Jerozolimie. Jego matka miała na imię Maacha i była córką Abiszaloma.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 11, 'Asa czynił to, co było prawe w oczach Pana, jak Dawid, jego ojciec.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 12, 'Usunął z ziemi sodomitów i wszystkie bożki, które wykonali jego ojcowie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 13, 'Również Maachę, swoją matkę, odsunął od panowania za to, że sporządziła bożka w gaju. Asa zniszczył więc jej bożka i spalił go przy potoku Cedron.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 14, 'I chociaż wyżyny nie zostały zniszczone, jednak serce Asy było doskonałe wobec Pana przez wszystkie jego dni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 15, 'I wniósł do domu Pana rzeczy poświęcone przez swego ojca i rzeczy, które sam poświęcił: srebro, złoto i naczynia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 16, 'I między Asą a Baszą, królem Izraela, trwała wojna przez wszystkie ich dni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 17, 'Basza, król Izraela, nadciągnął przeciwko Judzie i rozbudował Rama, aby nikomu nie pozwolić wychodzić od Asy, króla Judy, i przychodzić do niego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 18, 'Asa wziął więc całe srebro i złoto, które pozostało w skarbcach domu Pana i w skarbcach domu królewskiego, i dał je w ręce swoich sług. Następnie król Asa posłał ich do Ben-Hadada, syna Tabrimona, syna Chezjona, króla Syrii, który mieszkał w Damaszku, mówiąc:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 19, 'Jest przymierze między mną a tobą, między moim ojcem a twoim ojcem. Oto posyłam ci dar: srebro i złoto. Idź, zerwij swoje przymierze z Baszą, królem Izraela, aby odstąpił ode mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 20, 'I Ben-Hadad posłuchał króla Asy, i posłał dowódców swoich wojsk przeciwko miastom Izraela, napadł na Ijon, Dan i Abel-Bet-Maaka oraz całe Kinerot wraz z całą ziemią Neftalego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 21, 'Gdy Basza o tym usłyszał, przestał rozbudowywać Rama i mieszkał w Tirsie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 22, 'Wtedy król Asa zwołał cały lud Judy, bez wyjątku, a lud zabrał z Rama kamienie i drewno, z których Basza budował. I król Asa rozbudował nimi Gibea Beniamina oraz Mispę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 23, 'A pozostałe dzieje Asy, cała jego potęga i wszystko, co czynił, oraz miasta, które zbudował, czyż nie są zapisane w kronikach królów Judy? Jednak w okresie swojej starości zachorował na nogi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 24, 'I Asa zasnął ze swoimi ojcami, i został pogrzebany z nimi w mieście Dawida, swego ojca. A jego syn Jehoszafat królował w jego miejsce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 25, 'W drugim roku Asy, króla Judy, nad Izraelem zaczął królować Nadab, syn Jeroboama i królował nad Izraelem dwa lata.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 26, 'I czynił to, co złe w oczach Pana, idąc drogami swego ojca i w jego grzechu, którym doprowadził Izraela do grzechu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 27, 'I Basza, syn Achiasza, z domu Issachara, uknuł spisek przeciw niemu. Basza zabił go w Gibbeton, który należał do Filistynów. Nadab bowiem i cały Izrael oblegali Gibbeton.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 28, 'Basza zabił go w trzecim roku Asy, króla Judy, i sam królował w jego miejsce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 29, 'Kiedy zaczął królować, wymordował cały dom Jeroboama i nie pozostawił żywej duszy z rodu Jeroboama, dopóki nie wytracił go zgodnie ze słowem Pana, które wypowiedział przez swego sługę Achiasza Szilonitę;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 30, 'Z powodu grzechów Jeroboama, które popełnił i do których skłonił Izraela; z powodu rozdrażnienia, którym pobudził do gniewu Pana, Boga Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 31, 'A pozostałe dzieje Nadaba i wszystko, co czynił, czyż nie są zapisane w kronikach królów Izraela?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 32, 'I między Asą a Baszą, królem Izraela, trwała wojna po wszystkie ich dni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 33, 'W trzecim roku Asy, króla Judy, nad całym Izraelem zaczął królować w Tirsie Basza, syn Achiasza. I królował przez dwadzieścia cztery lata.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 34, 'I czynił to, co złe w oczach Pana, idąc drogami Jeroboama i w jego grzechu, do którego skłonił Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 1, 'Wtedy słowo Pana doszło do Jehu, syna Chananiego, przeciw Baszy:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 2, 'Ponieważ wywyższyłem cię z prochu i ustanowiłem cię wodzem nad swoim ludem Izraelem, a ty poszedłeś drogą Jeroboama i skłoniłeś do grzechu mój lud, Izraela, aby mnie pobudzić do gniewu jego grzechami;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 3, 'Oto zgładzę potomstwo Baszy i potomstwo jego domu i postąpię z twoim domem jak z domem Jeroboama, syna Nebata.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 4, 'Tego, kto z rodu Baszy umrze w mieście, zjedzą psy, a tego, kto umrze na polu, zjedzą powietrzne ptaki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 5, 'A pozostałe dzieje Baszy i to, co czynił, i jego potęga, czyż nie są zapisane w kronikach królów Izraela?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 6, 'Potem Basza zasnął ze swoimi ojcami i został pogrzebany w Tirsie, a jego syn Ela królował w jego miejsce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 7, 'Ponownie przez proroka Jehu, syna Chananiego, doszło słowo Pana przeciw Baszy i przeciw jego domowi za całe zło, które czynił w oczach Pana, pobudzając go do gniewu czynami swoich rąk, stając się podobnym do domu Jeroboama, i za to, że go zabił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 8, 'W dwudziestym szóstym roku Asy, króla Judy, nad Izraelem w Tirsie zaczął królować Ela, syn Baszy, i królował dwa lata.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 9, 'A jego sługa Zimri, dowódca połowy rydwanów, uknuł spisek przeciw niemu, gdy w Tirsie Ela oddawał się pijaństwu w domu Arsy, szafarza domu królewskiego w Tirsie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 10, 'Zimri wszedł tam, uderzył go i zabił – w dwudziestym siódmym roku Asy, króla Judy, i królował w jego miejsce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 11, 'A gdy tylko zaczął królować i zasiadł na swoim tronie, wymordował cały dom Baszy. Nie pozostawił z niego nikogo – ani z jego krewnych, ani przyjaciół – aż do najmniejszego szczenięcia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 12, 'W ten sposób Zimri wytracił cały dom Baszy zgodnie ze słowem Pana, które wypowiedział przeciw Baszy przez proroka Jehu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 13, 'Z powodu wszystkich grzechów Baszy i grzechów jego syna Eli, które popełnili i którymi doprowadzili Izraela do grzechu, pobudzając Pana, Boga Izraela, do gniewu swymi marnościami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 14, 'A pozostałe dzieje Eli i wszystko, co czynił, czyż nie są zapisane w kronikach królów Izraela?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 15, 'W dwudziestym siódmym roku Asy, króla Judy, Zimri królował siedem dni w Tirsie. Lud oblegał wtedy Gibbeton, który należy do Filistynów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 16, 'A gdy lud oblegający miasto usłyszał wieść: Zimri uknuł spisek i zabił króla, wtedy cały Izrael w tym samym dniu w obozie ustanowił królem Omriego, który był dowódcą wojska Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 17, 'Wtedy Omri wyruszył spod Gibbeton wraz z całym Izraelem i oblegli Tirsę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 18, 'A gdy Zimri zobaczył, że miasto zostało zdobyte, wszedł do pałacu domu królewskiego i podpalił nad sobą dom królewski, i umarł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 19, 'Stało się tak z powodu jego grzechów, których się dopuścił, czyniąc to, co złe w oczach Pana, idąc drogą Jeroboama i w jego grzechu – którego się dopuszczał i do którego skłonił Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 20, 'A pozostałe dzieje Zimriego i spisek, który uknuł, czyż nie są zapisane w kronikach królów Izraela?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 21, 'Wtedy lud Izraela podzielił się na dwie części: połowa ludu szła za Tibnim, synem Ginata, aby go obwołać królem, a połowa szła za Omrim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 22, 'Lecz lud, który był za Omrim, przemógł lud, który był za Tibnim, synem Ginata. I umarł Tibni, a królował Omri.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 23, 'W trzydziestym pierwszym roku Asy, króla Judy, nad Izraelem zaczął królować Omri i panował dwanaście lat. W Tirsie królował sześć lat.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 24, 'I kupił wzgórze Samarii od Szemera za dwa talenty srebra, i pobudował na tym wzgórzu, a miasto, które zbudował, nazwał Samarią, od imienia właściciela wzgórza, Szemera.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 25, 'Lecz Omri czynił to, co złe w oczach Pana, i dopuszczał się gorszych rzeczy niż wszyscy, którzy byli przed nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 26, 'Chodził bowiem wszystkimi drogami Jeroboama, syna Nebata, i w jego grzechu, do którego przywiódł Izraela, pobudzając Pana, Boga Izraela, do gniewu swymi marnościami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 27, 'A pozostałe dzieje Omriego, których dokonał, i jego potęga, którą pokazywał, czyż nie są zapisane w kronikach królów Izraela?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 28, 'I Omri zasnął ze swoimi ojcami, i został pogrzebany w Samarii. A jego syn Achab królował w jego miejsce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 29, 'W trzydziestym ósmym roku Asy, króla Judy, nad Izraelem zaczął królować Achab, syn Omriego. Achab, syn Omriego, królował nad Izraelem w Samarii dwadzieścia dwa lata.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 30, 'I Achab, syn Omriego, czynił to, co złe w oczach Pana, bardziej niż wszyscy, którzy byli przed nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 31, 'A jakby nie wystarczyło mu popełnianie grzechów Jeroboama, syna Nebata, to jeszcze pojął za żonę Jezabel, córkę Etbaala, króla Sydończyków, i zaczął służyć Baalowi i oddawać mu pokłon.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 32, 'I wzniósł ołtarz dla Baala w domu Baala, który zbudował w Samarii.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 33, 'Achab zasadził też gaj. Achab czynił więcej, by pobudzać Pana, Boga Izraela, do gniewu niż wszyscy królowie Izraela, którzy byli przed nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 34, 'Za jego czasów Chiel z Betel odbudował Jerycho. Założył fundamenty na Abiramie, swoim pierworodnym, a na Segubie, swoim najmłodszym synu, postawił jego bramy – według słowa Pana, które wypowiedział przez Jozuego, syna Nuna.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 1, 'Wtedy Eliasz Tiszbita, jeden z mieszkańców Gileadu, powiedział do Achaba: Jak żyje Pan, Bóg Izraela, przed którym stoję, nie będzie w tych latach ani rosy, ani deszczu jak tylko na moje słowo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 2, 'I doszło do niego słowo Pana:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 3, 'Odejdź stąd, skieruj się na wschód i skryj się przy potoku Kerit, który jest przed Jordanem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 4, 'I będziesz pił z potoku, krukom zaś rozkazałem, aby cię tam żywiły.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 5, 'Poszedł więc i uczynił według słowa Pana: Poszedł i zamieszkał przy potoku Kerit, leżącym przed Jordanem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 6, 'A kruki przynosiły mu chleb i mięso rano oraz chleb i mięso wieczorem, wodę zaś pił z potoku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 7, 'Lecz po pewnym czasie potok wysechł, gdyż nie było deszczu w tej ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 8, 'I doszło do niego słowo Pana:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 9, 'Wstań, idź do Sarepty sydońskiej i tam zamieszkaj. Oto rozkazałem tam pewnej kobiecie, wdowie, aby cię żywiła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 10, 'Wstał więc i poszedł do Sarepty. Kiedy przybył do bramy miasta, oto kobieta, wdowa, zbierała drwa. Zawołał ją i powiedział: Przynieś mi, proszę, trochę wody w naczyniu, abym się napił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 11, 'A gdy szła, by przynieść wody, zawołał ją i powiedział: Przynieś mi też, proszę, kromkę chleba w swojej ręce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 12, 'I odpowiedziała: Jak żyje Pan, twój Bóg, nie mam pieczonego chleba, mam tylko garść mąki w dzbanie i trochę oliwy w baryłce. Oto zbieram trochę drew, potem przyjdę i przyrządzę to dla siebie i dla mojego syna. A to zjemy, potem umrzemy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 13, 'Wtedy Eliasz powiedział do niej: Nie bój się. Idź, uczyń, jak powiedziałaś. Najpierw jednak zrób z tego dla mnie mały podpłomyk i przynieś mi go. Dla siebie zaś i swego syna zrobisz potem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 14, 'Tak bowiem powiedział Pan, Bóg Izraela: Mąka w dzbanie nie skończy się i oliwy w baryłce nie braknie aż do dnia, w którym Pan spuści deszcz na ziemię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 15, 'Poszła więc i uczyniła według słowa Eliasza. Ona i on oraz jej dom jedli przez wiele dni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 16, 'Nie skończyła się mąka w dzbanie ani nie zabrakło oliwy w baryłce według słowa Pana, które wypowiedział przez Eliasza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 17, 'Po tych wydarzeniach zachorował syn tej kobiety, pani tego domu, a jego choroba była tak ciężka, że przestał oddychać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 18, 'Wtedy powiedziała do Eliasza: Cóż ja mam z tobą, mężu Boży? Przyszedłeś do mnie, aby przypomnieć mi mój grzech i uśmiercić mego syna?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 19, 'I odpowiedział jej: Daj mi swego syna. I wziął go z jej łona, zaniósł na górę do pokoju, w którym mieszkał, i położył go na swoim łóżku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 20, 'I wołał do Pana, i powiedział: Panie, mój Boże, czy także na tę wdowę, u której mieszkam, chcesz sprowadzić nieszczęście, uśmiercając jej syna?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 21, 'I rozciągnął się trzykrotnie nad dzieckiem, i wołał do Pana, i powiedział: Panie, mój Boże, proszę, niech dusza tego dziecka wróci do niego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 22, 'I Pan wysłuchał głosu Eliasza. Dusza dziecka wróciła do niego i ożyło.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 23, 'Wtedy Eliasz wziął dziecko, zniósł je z pokoju do domu i oddał je matce. I Eliasz powiedział: Patrz, twój syn żyje.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 24, 'I kobieta powiedziała do Eliasza: Teraz wiem, że jesteś mężem Bożym i słowo Pana w twoich ustach jest prawdą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 1, 'Po upływie wielu dni, w trzecim roku, doszło do Eliasza słowo Pana: Idź, pokaż się Achabowi, a ja ześlę deszcz na ziemię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 2, 'Eliasz poszedł więc, aby pokazać się Achabowi. A w Samarii panował wielki głód.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 3, 'Achab zawołał wówczas Abdiasza, który był zarządcą jego domu. (A Abdiasz bardzo bał się Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 4, 'Gdy bowiem Jezabel mordowała proroków Pana, Abdiasz wziął stu proroków, ukrył ich po pięćdziesięciu w jaskiniach i żywił ich chlebem i wodą).');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 5, 'I Achab powiedział do Abdiasza: Przejdź przez ziemię do wszystkich źródeł wód i do wszystkich potoków. Może znajdziemy trawę, abyśmy zachowali przy życiu konie i muły i nie utracili całego bydła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 6, 'I podzielili między siebie ziemię, którą mieli obejść. Achab poszedł jedną drogą, a Abdiasz poszedł drugą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 7, 'A gdy Abdiasz był w drodze, Eliasz wyszedł mu naprzeciw. A on go poznał, upadł na twarz i powiedział: Czy to ty, mój panie, Eliaszu?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 8, 'Odpowiedział mu: To ja jestem. Idź i powiedz swemu panu: Oto jest tu Eliasz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 9, 'On zaś powiedział: Czym zgrzeszyłem, że wydajesz swego sługę w ręce Achaba, aby mnie zabił?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 10, 'Jak żyje Pan, twój Bóg, nie ma narodu ani królestwa, gdzie mój pan nie posłał ludzi, aby cię szukać. A gdy powiedziano, że cię nie ma, wtedy kazał przysięgać królestwom i narodom, że cię nie znaleziono.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 11, 'A ty teraz mówisz: Idź, powiedz swemu panu: Oto Eliasz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 12, 'I stanie się tak, że gdy odejdę od ciebie, Duch Pana zaniesie cię, nie wiem dokąd. Gdy przyjdę powiedzieć Achabowi, a on cię nie znajdzie, wtedy mnie zabije. A twój sługa boi się Pana od swej młodości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 13, 'Czyż nie powiedziano memu panu, co uczyniłem, gdy Jezabel mordowała proroków Pana – jak ukryłem stu mężczyzn spośród proroków Pana, po pięćdziesięciu mężczyzn w jaskiniach, i żywiłem ich chlebem i wodą?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 14, 'A teraz mówisz: Idź, powiedz swemu panu: Oto Eliasz. On mnie zabije.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 15, 'Eliasz odpowiedział: Jak żyje Pan zastępów, przed którego obliczem stoję, dziś mu się pokażę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 16, 'Abdiasz poszedł więc, aby spotkać się z Achabem, i oznajmił mu to. I Achab wyruszył na spotkanie z Eliaszem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 17, 'Kiedy Achab zobaczył Eliasza, zapytał go: Czy ty jesteś tym, który dręczy Izrael?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 18, 'Odpowiedział: Nie ja dręczę Izrael, ale ty i dom twego ojca – gdyż porzuciliście przykazania Pana, a ty poszedłeś za Baalami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 19, 'Teraz więc poślij i zgromadź przy mnie cały Izrael na górze Karmel oraz czterystu pięćdziesięciu proroków Baala, a także czterystu proroków z gajów, którzy jadają u stołu Jezabel.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 20, 'Achab posłał więc po wszystkich synów Izraela i zgromadził proroków na górze Karmel.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 21, 'Wtedy Eliasz zbliżył się do całego ludu i powiedział: Jak długo będziecie się wahać między dwoma zdaniami? Jeśli Pan jest Bogiem, idźcie za nim, a jeśli Baal, idźcie za nim. A lud nie odpowiedział mu ani słowa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 22, 'Wtedy Eliasz powiedział do ludu: Tylko ja sam pozostałem jako prorok Pana; a proroków Baala jest czterystu pięćdziesięciu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 23, 'Niech nam dadzą dwa cielce. Niech wybiorą sobie jednego cielca, porąbią go na części i położą na drwach, ale ognia niech nie podkładają. Ja również przygotuję drugiego cielca i położę na drwach, ale ognia nie podłożę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 24, 'Potem wzywajcie imienia swoich bogów, a ja wezwę imienia Pana. A ten Bóg, który odpowie ogniem, niech będzie Bogiem. Cały lud odpowiedział: Dobre jest to, co powiedziałeś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 25, 'Eliasz powiedział więc do proroków Baala: Wybierzcie sobie jednego cielca i przygotujcie go pierwsi, bo was jest więcej. Wzywajcie imienia swoich bogów, ale ognia nie podkładajcie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 26, 'Wzięli więc cielca, którego im dał, a gdy go przygotowali, wzywali imienia Baala, od poranka aż do południa, mówiąc: O Baalu, wysłuchaj nas! Ale nie było głosu ani odpowiedzi. I podskakiwali wokół ołtarza, który zrobili.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 27, 'A gdy nastało południe, Eliasz naśmiewał się z nich, mówiąc: Wołajcie głośniej, przecież to jest bóg, ale może tylko zamyślił się albo jest zajęty, albo też może jest w drodze, albo może śpi i musi się obudzić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 28, 'Wołali więc głośno i nacinali się według swego zwyczaju nożami i włóczniami, aż krew z nich tryskała.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 29, 'I kiedy minęło południe, oni dalej prorokowali aż do czasu składania ofiary z pokarmów, ale nie było głosu ani odpowiedzi, ani znaku uwagi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 30, 'Wtedy Eliasz powiedział do całego ludu: Zbliżcie się do mnie. Cały lud zbliżył się więc do niego. On wtedy naprawił zburzony ołtarz Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 31, 'Potem Eliasz wziął dwanaście kamieni, według liczby pokoleń synów Jakuba, do którego doszło słowo Pana: Izrael będzie twoje imię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 32, 'I z tych kamieni zbudował ołtarz w imię Pana, i wykopał wokół ołtarza rów zdolny pomieścić dwie miary zboża.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 33, 'Potem ułożył drwa, porąbał cielca na części i położył go na drwach. Następnie powiedział: Napełnijcie wodą cztery wiadra i wylejcie ją na ofiarę całopalną i na drwa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 34, 'I powiedział: Powtórzcie to. I powtórzyli. Potem powiedział: Zróbcie to trzeci raz. I zrobili to po raz trzeci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 35, 'I woda spłynęła dokoła ołtarza. I napełniono wodą także rów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 36, 'A gdy nadszedł czas składania ofiary z pokarmów, prorok Eliasz zbliżył się i powiedział: Panie, Boże Abrahama, Izaaka i Izraela, niech dziś poznają, że ty jesteś Bogiem w Izraelu, a ja twoim sługą, i że na twoje słowo uczyniłem to wszystko.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 37, 'Wysłuchaj mnie, Panie, wysłuchaj mnie, aby ten lud poznał, że ty, Panie, jesteś Bogiem i że ty z powrotem nawróciłeś jego serca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 38, 'Wtedy spadł ogień Pana i pochłonął ofiarę całopalną i drwa, i kamienie, i proch. A wodę, która była w rowie, wysuszył.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 39, 'Kiedy cały lud to zobaczył, wszyscy upadli na twarz i mówili: Pan jest Bogiem! Pan jest Bogiem!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 40, 'Wtedy Eliasz powiedział do nich: Chwytajcie proroków Baala, niech żaden z nich nie ujdzie. I schwytano ich. A Eliasz sprowadził ich do potoku Kiszon i tam ich zabił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 41, 'Potem Eliasz powiedział do Achaba: Idź, jedz i pij. Słychać bowiem szum ulewnego deszczu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 42, 'Achab poszedł więc jeść i pić. A Eliasz wstąpił na szczyt Karmelu. Następnie padł na ziemię i włożył twarz między kolana;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 43, 'I powiedział do swego sługi: Idź teraz i popatrz w stronę morza. Ten poszedł, popatrzył i powiedział: Nie ma nic. Wtedy powiedział: Idź i wracaj siedem razy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 44, 'A za siódmym razem powiedział: Oto mała chmurka, jak dłoń człowieka, podnosi się z morza. Wtedy polecił mu: Idź, powiedz Achabowi: Zaprzęgaj rydwan i zjeżdżaj, aby cię deszcz nie zatrzymał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 45, 'Tymczasem niebo zaćmiło się od chmur i wiatru i spadł ulewny deszcz. Achab zaś wsiadł do rydwanu i pojechał do Jizreel.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 46, 'A ręka Pana była nad Eliaszem. Przepasał swoje biodra i pobiegł przed Achabem, aż przybył do Jizreel.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 1, 'Wtedy Achab opowiedział Jezabel o wszystkim, co Eliasz uczynił, oraz o tym, jak zabił mieczem wszystkich proroków.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 2, 'Jezabel wysłała więc posłańca do Eliasza ze słowami: Niech to mi uczynią bogowie i tamto dorzucą, jeśli jutro o tym czasie twojego życia nie uczynię takim jak życie jednego z nich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 3, 'Kiedy to zrozumiał, wstał i odszedł, aby ocalić swoje życie. Przybył do Beer-Szeby, która należy do Judy, i zostawił tam swego sługę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 4, 'A sam poszedł na pustynię na jeden dzień drogi, a gdy tam doszedł, usiadł pod jałowcem i życzył sobie śmierci, mówiąc: Dosyć już, Panie. Zabierz moją duszę, bo nie jestem lepszy od swoich ojców.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 5, 'Potem położył się i zasnął pod tym jałowcem. A wtedy Anioł dotknął go i powiedział mu: Wstań i jedz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 6, 'A gdy spojrzał, oto przy jego głowie leżał placek pieczony na węgielkach i dzban wody. Jadł więc i pił, i znowu się położył.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 7, 'Anioł Pana wrócił ponownie, dotknął go i powiedział: Wstań i jedz, bo masz przed sobą daleką drogę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 8, 'Wstał więc i jadł, i pił, i szedł dzięki mocy tego pokarmu czterdzieści dni i czterdzieści nocy aż do Horebu, góry Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 9, 'Tam wszedł do jaskini, gdzie przenocował. A oto słowo Pana doszło do niego: Co tu robisz, Eliaszu?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 10, 'Odpowiedział: Byłem bardzo gorliwy względem Pana, Boga zastępów. Synowie Izraela bowiem porzucili twoje przymierze, zburzyli twoje ołtarze i pomordowali mieczem twoich proroków. Ja sam tylko pozostałem i szukają mojej duszy, aby mi ją odebrać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 11, 'Wtedy on powiedział: Wyjdź, stań na górze przed Panem. A oto Pan przechodził, a potężny i gwałtowny wiatr rozrywał góry i kruszył skały przed Panem, ale Pan nie był w tym wietrze. Po wietrze było trzęsienie ziemi, ale Pan nie był i w tym trzęsieniu ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 12, 'Po trzęsieniu ziemi był ogień, ale Pan nie był w ogniu. A po tym ogniu był cichy i delikatny głos.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 13, 'Gdy Eliasz go usłyszał, zasłonił płaszczem swoją twarz, wyszedł i stanął u wejścia do jaskini. A oto głos przemówił do niego: Co tu robisz, Eliaszu?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 14, 'A on odpowiedział: Byłem bardzo gorliwy względem Pana, Boga zastępów. Synowie Izraela bowiem porzucili twoje przymierze, zburzyli twoje ołtarze i pomordowali mieczem twoich proroków. Ja sam tylko pozostałem i szukają mojej duszy, aby mi ją odebrać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 15, 'Ale Pan powiedział do niego: Idź, wróć tą samą drogą na pustynię Damaszku. A kiedy tam przybędziesz, namaścisz Chazaela na króla nad Syrią.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 16, 'A Jehu, syna Nimsziego, namaścisz na króla nad Izraelem. Elizeusza zaś, syna Szafata, z Abel-Mechola, namaścisz na proroka po tobie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 17, 'I stanie się tak, że ktokolwiek uniknie miecza Chazaela, tego zabije Jehu, a ktokolwiek uniknie miecza Jehu, tego zabije Elizeusz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 18, 'Jednak zachowałem sobie w Izraelu siedem tysięcy, których kolana nie zginały się przed Baalem i których usta nie całowały go.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 19, 'Odszedł więc stamtąd i znalazł Elizeusza, syna Szafata, gdy orał. Dwanaście zaprzęgów wołów szło przed nim, a on był przy dwunastym. Eliasz przeszedł obok niego i wrzucił na niego swój płaszcz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 20, 'Wtedy opuścił woły, pobiegł za Eliaszem i powiedział: Pozwól mi ucałować swego ojca i swoją matkę, a pójdę za tobą. Odpowiedział: Idź, wróć. Cóż bowiem ci uczyniłem?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 21, 'Odszedł więc od niego, wziął zaprzęg wołów i zabił je. A na sprzęcie tych wołów ugotował ich mięso i dał ludowi, a oni jedli. Potem wstał i poszedł za Eliaszem, i służył mu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 1, 'Wtedy Ben-Hadad, król Syrii, zebrał całe swoje wojsko, a było z nim trzydzieści dwóch królów, konie i rydwany. Wyruszył, obległ Samarię i walczył przeciwko niej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 2, 'I wyprawił posłańców do Achaba, króla Izraela, do miasta, i powiedział mu: Tak mówi Ben-Hadad:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 3, 'Twoje srebro i złoto są moje; także twoje żony i twoi najpiękniejsi synowie są moi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 4, 'Król Izraela odpowiedział: Według twego słowa, królu, mój panie – twój jestem ja i wszystko, co mam.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 5, 'Potem posłańcy wrócili do niego i powiedzieli: Tak powiedział Ben-Hadad: Wprawdzie posłałem do ciebie ludzi, aby ci powiedzieli: Oddasz swoje srebro i złoto, swoje żony i swoich synów oddasz mi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 6, 'Jednak jutro o tej porze poślę swoje sługi do ciebie. Oni przeszukują twój dom i domy twoich sług, a wszystko, co jest cenne w twoich oczach, wezmą w ręce i zabiorą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 7, 'Król Izraela zwołał więc wszystkich starszych ziemi i powiedział im: Rozważcie, proszę, i zobaczcie, że ten człowiek szuka nieszczęścia. Posłał bowiem do mnie po moje żony i moich synów, po moje srebro i złoto, a nie odmówiłem mu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 8, 'Wszyscy starsi i cały lud odpowiedzieli: Nie słuchaj go i nie gódź się.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 9, 'Odpowiedział więc posłom Ben-Hadada: Powiedzcie królowi, memu panu: Wszystko, czego na początku żądałeś od swego sługi, uczynię. Lecz tej rzeczy nie mogę uczynić. Posłańcy odeszli i zanieśli mu odpowiedź.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 10, 'Ben-Hadad znowu posłał do niego sługi i powiedział: Niech mi to uczynią bogowie i tamto dorzucą, jeśli starczy prochu Samarii po pełnej garści dla każdego spośród całego ludu, który idzie za mną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 11, 'Król Izraela odpowiedział: Powiedzcie mu: Niech się nie chlubi ten, kto zapina pas, jak ten, kto go odpina.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 12, 'A gdy Ben-Hadad usłyszał to słowo – a właśnie pił z królami w namiotach – powiedział do swoich sług: Ruszajcie. I ruszyli na miasto.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 13, 'A oto pewien prorok przyszedł do Achaba, króla Izraela, i powiedział: Tak mówi Pan: Czy widzisz cały ten wielki tłum? Oto wydam go dziś w twoje ręce, abyś wiedział, że ja jestem Panem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 14, 'Wtedy Achab zapytał: Przez kogo? Odpowiedział: Tak mówi Pan: Przez sługi książąt prowincji. Zapytał dalej: Kto rozpocznie bitwę? Odpowiedział mu: Ty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 15, 'Dokonał więc przeglądu sług książąt prowincji i było ich dwustu trzydziestu dwóch. A po nich policzył cały lud, wszystkich synów Izraela, i było ich siedem tysięcy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 16, 'I wyruszyli w południe. A Ben-Hadad oddawał się pijaństwu w namiotach, a z nim trzydziestu dwóch królów, którzy go wspierali.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 17, 'Wyszli więc jako pierwsi słudzy książąt prowincji. Gdy Ben-Hadad posłał sługę, powiedziano mu: Ludzie wyszli z Samarii.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 18, 'Polecił: Jeśli wyszli prosić o pokój, pojmijcie ich żywych, również jeśli wyszli walczyć, pojmijcie ich żywych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 19, 'Wyszli więc z miasta słudzy książąt prowincji oraz wojsko razem z nimi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 20, 'A każdy pokonał swego przeciwnika, tak że Syryjczycy uciekli, a Izrael ich ścigał. Ben-Hadad, król Syrii, również uciekł na koniu i z jeźdźcami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 21, 'Potem król Izraela wyruszył i pobił konie i rydwany, a zadał Syryjczykom wielką klęskę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 22, 'Prorok znowu przyszedł do króla Izraela i powiedział mu: Idź, wzmocnij się, rozważ i zastanów się, co masz czynić. Po roku bowiem król Syrii nadciągnie przeciwko tobie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 23, 'Wtedy słudzy króla Syrii powiedzieli do niego: Ich bogowie są bogami gór, dlatego nas pokonali. Walczmy jednak z nimi na równinie i na pewno ich pokonamy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 24, 'Tak więc uczyń: Usuń każdego z królów z jego stanowiska, a na ich miejsce ustanów dowódców.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 25, 'Następnie odlicz sobie wojska takiego jak to wojsko, które ci poległo, koni jak tamte konie i rydwanów jak tamte rydwany. Wtedy stoczymy z nimi bitwę na równinie i na pewno ich pokonamy. I posłuchał ich głosu, i tak uczynił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 26, 'A gdy upłynął rok, Ben-Hadad dokonał przeglądu Syryjczyków i nadciągnął do Afek, aby walczyć z Izraelem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 27, 'Również u synów Izraela dokonano przeglądu, a gdy się zebrali, wyruszyli przeciwko nim. I synowie Izraela rozbili obóz przed nimi jak dwa małe stadka kóz. Syryjczycy zaś napełnili ziemię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 28, 'Wtedy przyszedł mąż Boży i mówił do króla Izraela: Tak mówi Pan: Ponieważ Syryjczycy powiedzieli: Pan jest Bogiem gór, a nie jest Bogiem równin, wydam cały ten wielki tłum w twoje ręce, abyście wiedzieli, że ja jestem Panem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 29, 'Obozowali jedni naprzeciw drugich przez siedem dni. A siódmego dnia stoczyli bitwę i synowie Izraela pobili w jednym dniu sto tysięcy pieszych spośród Syryjczyków.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 30, 'Pozostali zaś uciekli do Afek, do miasta, i runął mur na dwadzieścia siedem tysięcy pozostałych mężczyzn. Ben-Hadad uciekł i wszedł do miasta, gdzie ukrył się w wewnętrznej komnacie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 31, 'Wtedy jego słudzy powiedzieli mu: Oto słyszeliśmy, że królowie domu Izraela są królami miłosiernymi. Pozwól, proszę, że włożymy wory na nasze biodra, powrozy na nasze głowy i wyjdziemy do króla Izraela, może zostawi nas przy życiu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 32, 'Opasali więc worami swoje biodra, włożyli powrozy na swoje głowy, przyszli do króla Izraela i powiedzieli: Ben-Hadad, twój sługa, mówi: Proszę, zachowaj moją duszę przy życiu. Zapytał: Czy jeszcze żyje? To jest mój brat.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 33, 'Ci ludzie wzięli to za dobry znak i szybko podchwycili to słowo od niego, i powiedzieli: Twój brat Ben-Hadad. On zaś powiedział: Idźcie i przyprowadźcie go. Ben-Hadad wyszedł więc do niego i kazał mu wsiąść na rydwan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 34, 'Ben-Hadad powiedział do niego: Miasta, które mój ojciec zabrał twemu ojcu, zwrócę, a ty uczynisz sobie ulice w Damaszku, jak uczynił mój ojciec w Samarii. I odpowiedział: Puszczę cię wolno na podstawie tego przymierza. Tak więc zawarł z nim przymierze i puścił go wolno.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 35, 'Wtedy pewien mąż spośród synów proroków powiedział do swego bliźniego na słowo Pana: Uderz mnie, proszę. Ale ten człowiek nie chciał go uderzyć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 36, 'I powiedział mu: Ponieważ nie posłuchałeś głosu Pana, oto gdy tylko odejdziesz ode mnie, zabije cię lew. A gdy odszedł od niego, spotkał go lew i zabił go.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 37, 'Potem spotkał drugiego mężczyznę i powiedział mu: Uderz mnie, proszę. Człowiek ten tak go uderzył, że go zranił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 38, 'Prorok poszedł więc i czekał na króla na drodze, i zmienił swój wygląd dzięki zasłonie na twarzy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 39, 'A gdy król przejeżdżał, zawołał do króla: Twój sługa wszedł w sam środek bitwy, a oto podszedł pewien mężczyzna i przyprowadził do mnie człowieka, i powiedział: Pilnuj tego człowieka. Jeśli ci się wymknie, zapłacisz swoim życiem za jego życie albo zapłacisz talent srebra.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 40, 'A gdy twój sługa zajął się tym i owym, on zniknął. Król Izraela powiedział do niego: Taki jest twój wyrok, ty sam rozstrzygnąłeś tę sprawę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 41, 'Wtedy on szybko zdjął zasłonę z twarzy i król Izraela rozpoznał, że jest on jednym z proroków.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 42, 'I powiedział do niego: Tak mówi Pan: Ponieważ wypuściłeś ze swojej ręki człowieka przeznaczonego na śmierć, swoim życiem zapłacisz za jego życie i swoim ludem za jego lud.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 43, 'Król Izraela odszedł więc do swego domu smutny i rozgniewany i przybył do Samarii.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 1, 'Po tych wydarzeniach miała miejsce taka sprawa: Nabot Jizreelita miał winnicę, która znajdowała się w Jizreel obok pałacu Achaba, króla Samarii.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 2, 'I Achab powiedział do Nabota: Daj mi swoją winnicę, abym zrobił sobie z niej ogród warzywny, gdyż leży ona blisko mojego domu. Dam ci za nią lepszą winnicę albo – jeśli wolisz – dam ci pieniędzy według wartości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 3, 'Nabot odpowiedział Achabowi: Nie daj, Panie, abym ci dał dziedzictwo swoich ojców.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 4, 'Achab przyszedł więc do swego domu smutny i zagniewany z powodu słów, które Nabot Jizreelita wypowiedział do niego: Nie dam ci dziedzictwa swoich ojców. I położył się na swoim łożu, odwrócił swoją twarz i nie jadł chleba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 5, 'Wtedy przyszła do niego Jezabel, jego żona, i zapytała go: Czemu twój duch jest tak smutny, że nie chcesz jeść chleba?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 6, 'Odpowiedział jej: Bo rozmawiałem z Nabotem Jizreelitą i powiedziałem mu: Daj mi swoją winnicę za pieniądze albo – jeśli chcesz – dam ci za nią inną winnicę. Lecz on odpowiedział: Nie dam ci swojej winnicy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 7, 'Jego żona Jezabel powiedziała do niego: Czyż nie ty teraz sprawujesz władzę nad królestwem Izraela? Wstań, jedz chleb i bądź dobrej myśli. Ja dam ci winnicę Nabota Jizreelity.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 8, 'Napisała więc listy w imieniu Achaba, opieczętowała je jego pieczęcią i wysłała te listy do starszych i do dostojników, którzy byli w jego mieście i mieszkali z Nabotem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 9, 'W listach tak napisała: Ogłoście post i posadźcie Nabota przed ludem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 10, 'I postawcie przed nim dwóch synów Beliala, aby zaświadczyli przeciwko niemu, mówiąc: Złorzeczyłeś Bogu i królowi. Potem wyprowadźcie go i ukamienujcie, aby umarł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 11, 'I mężczyźni tego miasta, mianowicie starsi i dostojnicy mieszkający w jego mieście, uczynili tak, jak im poleciła Jezabel, zgodnie z tym, co było napisane w listach, które do nich wysłała.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 12, 'Ogłosili post i posadzili Nabota przed ludem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 13, 'Potem przyszło dwóch synów Beliala i usiadło przed nim. Ci niegodziwi ludzie zaświadczyli przeciwko niemu, czyli przeciw Nabotowi, przed ludem, mówiąc: Nabot złorzeczył Bogu i królowi. I wyprowadzili go za miasto, i ukamienowali go, i umarł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 14, 'I posłali do Jezabel wiadomość: Nabot został ukamienowany i umarł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 15, 'A gdy Jezabel usłyszała, że Nabot został ukamienowany i umarł, powiedziała do Achaba: Wstań, weź w posiadanie winnicę Nabota Jizreelity, której nie chciał dać ci za pieniądze. Nabot bowiem nie żyje, ale umarł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 16, 'Kiedy Achab usłyszał, że Nabot umarł, wstał i poszedł do winnicy Nabota Jizreelity, aby ją wziąć w posiadanie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 17, 'Wtedy słowo Pana doszło do Eliasza Tiszbity:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 18, 'Wstań, zejdź naprzeciw Achaba, króla Izraela, który przebywa w Samarii. Oto jest w winnicy Nabota, do której zszedł, aby ją wziąć w posiadanie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 19, 'I powiesz takie słowa: Tak mówi Pan: Czy zabiłeś i wziąłeś w posiadanie? Powiesz mu jeszcze: Tak mówi Pan: Na miejscu, gdzie psy lizały krew Nabota, psy będą lizać twoją krew, właśnie twoją.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 20, 'Achab powiedział do Eliasza: Już mnie znalazłeś, mój wrogu? Odpowiedział: Znalazłem, gdyż zaprzedałeś się, aby czynić zło na oczach Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 21, 'Oto sprowadzę na ciebie zło i usunę twoich potomków, i wytępię z domu Achaba każdego, aż do najmniejszego szczenięcia, każdego więźnia i opuszczonego w Izraelu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 22, 'I postąpię z twoim domem jak z domem Jeroboama, syna Nebata, i z domem Baszy, syna Achiasza, z powodu obrazy, którą pobudziłeś mnie do gniewu i przywiodłeś Izraela do grzechu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 23, 'Także o Jezabel Pan powiedział: Psy zjedzą Jezabel przy murze Jizreel.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 24, 'Tego, kto z domu Achaba umrze w mieście, zjedzą psy, a tego, kto umrze na polu, zjedzą ptaki powietrzne.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 25, 'Nie było bowiem nikogo takiego jak Achab, kto by się zaprzedał, aby czynić niegodziwość na oczach Pana, do czego skłoniła go Jezabel, jego żona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 26, 'Postępował bardzo obrzydliwie, chodząc za bożkami całkowicie tak samo, jak czynili Amoryci, których Pan wygnał przed synami Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 27, 'Kiedy Achab usłyszał te słowa, rozdarł swoje szaty, włożył wór na swoje ciało, pościł, spał w worze i chodził pokornie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 28, 'Wtedy słowo Pana doszło do Eliasza Tiszbity:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 29, 'Czy widziałeś, jak Achab upokorzył się przede mną? Ponieważ upokorzył się przede mną, nie sprowadzę tego nieszczęścia za jego dni; ale sprowadzę nieszczęście na jego dom za dni jego syna.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 1, 'A przez trzy lata nie było wojny między Syrią a Izraelem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 2, 'I w trzecim roku Jehoszafat, król Judy, przyjechał do króla Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 3, 'Wtedy król Izraela powiedział do swoich sług: Czy wiecie, że Ramot-Gilead należy do nas? A my zwlekamy z odebraniem go z ręki króla Syrii.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 4, 'Zapytał więc Jehoszafata: Czy wyruszysz ze mną na wojnę do Ramot-Gilead? Jehoszafat odpowiedział królowi Izraela: Ja tak, jak i ty, mój lud tak, jak i twój lud, moje konie, jak i twoje konie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 5, 'Jehoszafat powiedział jeszcze królowi Izraela: Zapytaj dziś, proszę, o słowo Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 6, 'Król Izraela zebrał więc około czterystu proroków i zapytał ich: Czy mam wyruszyć na wojnę do Ramot-Gilead, czy mam tego zaniechać? Odpowiedzieli mu: Wyrusz, bo Pan wyda je w ręce króla.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 7, 'Ale Jehoszafat zapytał: Czy nie ma tu jeszcze jakiegoś proroka Pana, abyśmy mogli go zapytać?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 8, 'Król Izraela odpowiedział Jehoszafatowi: Jest jeszcze jeden człowiek, przez którego moglibyśmy radzić się Pana, ale ja go nienawidzę, bo nie prorokuje mi nic dobrego, tylko to, co złe. Jest to Micheasz, syn Jimli. Jehoszafat powiedział: Niech król tak nie mówi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 9, 'Wtedy król Izraela zawołał pewnego dworzanina i polecił mu: Przyprowadź tu szybko Micheasza, syna Jimli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 10, 'Tymczasem król Izraela i Jehoszafat, król Judy, siedzieli na swoich tronach ubrani w królewskie szaty na placu przed wejściem do bramy Samarii, a przed nimi prorokowali wszyscy prorocy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 11, 'A Sedekiasz, syn Kenaany, sporządził sobie żelazne rogi i powiedział: Tak mówi Pan: Nimi będziesz bódł Syryjczyków, aż ich wytępisz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 12, 'Tak samo prorokowali wszyscy prorocy, mówiąc: Wyrusz do Ramot-Gilead, a poszczęści ci się. Pan bowiem wyda je w ręce króla.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 13, 'Wtedy posłaniec, który poszedł, aby przywołać Micheasza, powiedział do niego: Oto teraz słowa proroków jednomyślnie przekazują królowi to, co dobre. Niech twoje słowo, proszę, będzie jak słowo jednego z nich i mów to, co dobre.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 14, 'Micheasz odpowiedział: Jak żyje Pan, będę mówił to, co Pan mi powie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 15, 'A gdy przyszedł do króla, król powiedział do niego: Micheaszu, czy mamy wyruszyć na wojnę do Ramot-Gilead, czy mamy tego zaniechać? Odpowiedział: Wyrusz, a poszczęści ci się. Pan bowiem wyda je w ręce króla.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 16, 'I król powiedział do niego: Ileż razy mam cię zaprzysięgać, abyś mi nie mówił nic innego jak tylko prawdę w imieniu Pana?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 17, 'Powiedział więc: Widziałem całego Izraela rozproszonego po górach jak owce niemające pasterza. A Pan powiedział: Oni nie mają pana. Niech każdy wraca do swego domu w pokoju.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 18, 'Wtedy król Izraela powiedział do Jehoszafata: Czy nie mówiłem ci, że nie będzie mi prorokować nic dobrego, tylko to, co złe?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 19, 'Tamten powiedział: Słuchaj więc słowa Pana: Widziałem Pana siedzącego na swoim tronie, a wszystkie zastępy niebieskie stojące po jego prawicy i lewicy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 20, 'I Pan zapytał: Kto zwiedzie Achaba, aby wyruszył do Ramot-Gilead i poległ tam? I jeden mówił tak, a drugi inaczej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 21, 'Wtedy wystąpił duch i stanął przed Panem, mówiąc: Ja go zwiodę. Pan go zapytał: Jak?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 22, 'Odpowiedział: Wyjdę i będę duchem kłamliwym w ustach wszystkich jego proroków. Pan mu powiedział: Zwiedziesz go, na pewno ci się uda. Idź i tak uczyń.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 23, 'Teraz więc Pan włożył ducha kłamliwego w usta tych wszystkich twoich proroków, gdyż Pan zapowiedział ci nieszczęście.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 24, 'Wtedy Sedekiasz, syn Kenaany, podszedł do Micheasza i uderzył go w policzek, mówiąc: Którędy odszedł ode mnie Duch Pana, aby mówić z tobą?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 25, 'Micheasz odpowiedział: Ty sam to zobaczysz tego dnia, kiedy wejdziesz do najskrytszej komnaty, aby się ukryć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 26, 'Król Izraela powiedział: Weź Micheasza i zaprowadź go do Amona, namiestnika miasta, i do Joasza, syna króla.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 27, 'I powiesz: Tak mówi król: Wtrąćcie tego człowieka do więzienia i żywcie go chlebem utrapienia i wodą ucisku, aż wrócę w pokoju.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 28, 'Ale Micheasz odpowiedział: Jeśli rzeczywiście wrócisz w pokoju, to Pan nie mówił przeze mnie. I dodał: Słuchajcie wszyscy ludzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 29, 'Tak więc król Izraela i Jehoszafat, król Judy, wyruszyli do Ramot-Gilead.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 30, 'I król Izraela powiedział do Jehoszafata: Przebiorę się i pójdę na bitwę, ty zaś ubierz się w swoje szaty. Następnie król Izraela przebrał się i poszedł na bitwę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 31, 'A król Syrii rozkazał swoim trzydziestu dwom dowódcom rydwanów: Nie walczcie ani z małym, ani z wielkim, tylko z samym królem Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 32, 'A gdy dowódcy rydwanów zobaczyli Jehoszafata, powiedzieli: Na pewno on jest królem Izraela. I zwrócili się przeciwko niemu, aby z nim walczyć, ale Jehoszafat wydał okrzyk.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 33, 'Kiedy dowódcy rydwanów zobaczyli, że on nie jest królem Izraela, odstąpili od niego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 34, 'A pewien mężczyzna na ślepo naciągnął łuk i ugodził króla Izraela między spojenia pancerza. A ten powiedział swojemu woźnicy: Zawróć i wywieź mnie z pola bitwy, bo jestem ranny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 35, 'I bitwa wzmogła się tego dnia. Król stał w rydwanie naprzeciw Syryjczyków i wieczorem umarł, a krew spływała z jego rany na dno rydwanu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 36, 'O zachodzie słońca w obozie wydano rozkaz: Każdy do swego miasta i każdy do swojej ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 37, 'Tak więc król umarł i przywieziono go do Samarii, i pogrzebano go w Samarii.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 38, 'A gdy myto rydwan w sadzawce Samarii, psy lizały jego krew, myto także jego zbroję, według słowa Pana, które zapowiedział.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 39, 'A pozostałe sprawy Achaba i wszystko, co uczynił, oraz dom z kości słoniowej, który wzniósł, a także wszystkie miasta, które zbudował – czy nie są opisane w kronikach królów Izraela?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 40, 'I Achab zasnął ze swymi ojcami, a królował jego syn Achazjasz w jego miejsce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 41, 'A Jehoszafat, syn Asy, zaczął królować nad Judą w czwartym roku Achaba, króla Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 42, 'Jehoszafat miał trzydzieści pięć lat, gdy zaczął królować, a dwadzieścia pięć lat królował w Jerozolimie. Jego matka miała na imię Azuba i była córką Szilchiego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 43, 'I szedł wszystkimi drogami Asy, swego ojca, i nie zboczył z nich, czyniąc to, co było dobre w oczach Pana. Jednak wyżyn nie usunięto. Lud bowiem jeszcze składał ofiary i palił kadzidło na wyżynach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 44, 'Jehoszafat także zawarł pokój z królem Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 45, 'A pozostałe sprawy Jehoszafata i jego potęga, którą pokazywał, i to, jak walczył – czyż nie są zapisane w kronikach królów Judy?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 46, 'Usunął też z ziemi resztę sodomitów, którzy pozostali za dni Asy, jego ojca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 47, 'W tym czasie nie było króla w Edomie. Królem był namiestnik.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 48, 'Jehoszafat zbudował okręty Tarszisz, aby płynęły do Ofiru po złoto. Lecz nie dopłynęły, bo okręty rozbiły się w Esjon-Geber.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 49, 'Wtedy Achazjasz, syn Achaba, powiedział do Jehoszafata: Niech moi słudzy płyną na okrętach z twoimi sługami. Ale Jehoszafat nie chciał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 50, 'I Jehoszafat zasnął ze swymi ojcami, i został pogrzebany wraz z nimi w mieście Dawida, swego ojca. W jego miejsce królował jego syn Joram.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 51, 'Achazjasz, syn Achaba, zaczął królować nad Izraelem w Samarii w siedemnastym roku Jehoszafata, króla Judy, i królował nad Izraelem dwa lata.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 52, 'Czynił to, co złe w oczach Pana, idąc drogą swego ojca, drogą swej matki i drogą Jeroboama, syna Nebata, który przywiódł Izraela do grzechu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 53, 'Służył bowiem Baalowi, oddawał mu pokłon i pobudzał do gniewu Pana, Boga Izraela, według wszystkiego, co czynił jego ojciec.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 1, 'Po śmierci Achaba Moab zbuntował się przeciw Izraelowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 2, 'A Achazjasz wypadł przez kratę swej górnej komnaty w Samarii i zachorował. Wyprawił więc posłańców, mówiąc im: Idźcie i zapytajcie Belzebuba, boga Ekronu, czy wyzdrowieję z tej choroby.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 3, 'Lecz Anioł Pana powiedział do Eliasza Tiszbity: Wstań, wyjdź naprzeciw posłańcom króla Samarii i powiedz im: Czyż nie ma Boga w Izraelu, że idziecie radzić się Belzebuba, boga Ekronu?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 4, 'Dlatego tak mówi Pan: Z łoża, na które się położyłeś, już nie wstaniesz, ale na pewno umrzesz. I Eliasz odszedł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 5, 'A gdy posłańcy wrócili do niego, zapytał ich: Czemu wróciliście?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 6, 'Odpowiedzieli mu: Pewien człowiek wyszedł nam naprzeciw i powiedział do nas: Idźcie, wróćcie do króla, który was posłał, i powiedzcie mu: Tak mówi Pan: Czyż nie ma Boga w Izraelu, że posyłasz posłańców, aby się radzić Belzebuba, boga Ekronu? Z tego powodu z łoża, na którym się położyłeś, nie wstaniesz, ale na pewno umrzesz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 7, 'I zapytał ich: Jak wyglądał ten człowiek, który wyszedł wam naprzeciw i powiedział do was te słowa?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 8, 'Odpowiedzieli mu: Był to owłosiony mężczyzna, przepasany skórzanym pasem na biodrach. I powiedział: To Eliasz Tiszbita.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 9, 'Posłał więc do niego pięćdziesiątnika wraz z jego pięćdziesięcioma. Ten podszedł do niego, a oto siedział na szczycie góry. Powiedział mu: Mężu Boży, król rozkazał, abyś zszedł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 10, 'Eliasz zaś odpowiedział pięćdziesiątnikowi: Jeśli jestem mężem Bożym, niech ogień spadnie z nieba i pochłonie ciebie oraz twoich pięćdziesięciu. Wtedy spadł ogień z nieba i pochłonął go oraz jego pięćdziesięciu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 11, 'Znowu posłał do niego drugiego pięćdziesiątnika wraz z jego pięćdziesięcioma. Ten powiedział do niego: Mężu Boży, tak mówi król: Zejdź natychmiast.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 12, 'A Eliasz odpowiedział mu: Jeśli jestem mężem Bożym, niech spadnie ogień z nieba i pochłonie ciebie oraz twoich pięćdziesięciu. Wtedy ogień Boży spadł z nieba i pochłonął go oraz jego pięćdziesięciu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 13, 'Wtedy znowu posłał trzeciego pięćdziesiątnika wraz z jego pięćdziesięcioma. Poszedł więc trzeci pięćdziesiątnik, a gdy przybył, upadł na kolana przed Eliaszem i poprosił go pokornie: Mężu Boży, proszę, niech moje życie i życie twoich pięćdziesięciu sług będzie cenne w twoich oczach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 14, 'Oto ogień spadł z nieba i pochłonął dwóch poprzednich pięćdziesiątników wraz z ich pięćdziesięcioma. Teraz więc niech moje życie będzie cenne w twoich oczach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 15, 'Wtedy Anioł Pana powiedział do Eliasza: Zejdź z nim, nie bój się go. Wstał więc i zszedł z nim do króla.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 16, 'I powiedział mu: Tak mówi Pan: Ponieważ wysłałeś posłańców, aby radzić się Belzebuba, boga Ekronu, jakby nie było Boga w Izraelu, którego można pytać o jego słowo, z tego powodu z łoża, na którym się położyłeś, nie wstaniesz, ale na pewno umrzesz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 17, 'Umarł więc zgodnie ze słowem Pana, które wypowiedział Eliasz. A ponieważ nie miał syna, królował w jego miejsce Joram – w drugim roku Jorama, syna Jehoszafata, króla Judy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 18, 'A pozostałe dzieje Achazjasza, które czynił, czy nie są zapisane w księdze kronik królów Izraela?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 1, 'I kiedy Pan miał unieść Eliasza wśród wichru do nieba, Eliasz wyruszył z Elizeuszem z Gilgal.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 2, 'I Eliasz powiedział do Elizeusza: Proszę, zostań tu, bo Pan posyła mnie do Betel. Elizeusz odpowiedział: Jak żyje Pan i jak żyje twoja dusza, nie opuszczę cię. Przyszli więc do Betel.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 3, 'Wtedy synowie proroków, którzy byli w Betel, wyszli do Elizeusza i zapytali go: Czy wiesz, że Pan dzisiaj zabierze twego pana znad twojej głowy? Odpowiedział: Wiem, lecz milczcie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 4, 'A Eliasz ponownie powiedział mu: Elizeuszu, proszę, zostań tu, bo Pan posyła mnie do Jerycha. Odpowiedział: Jak żyje Pan i jak żyje twoja dusza, nie opuszczę cię. Przyszli więc do Jerycha.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 5, 'Wtedy synowie proroków, którzy byli w Jerychu, zapytali Elizeusza: Czy wiesz, że Pan dzisiaj zabierze twego pana znad twojej głowy? Odpowiedział: Tak, wiem, lecz milczcie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 6, 'Eliasz znowu powiedział mu: Proszę, zostań tu, bo Pan posyła mnie do Jordanu. Odpowiedział: Jak żyje Pan i jak żyje twoja dusza, nie opuszczę cię. Szli więc dalej obydwaj.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 7, 'A pięćdziesięciu mężów spośród synów proroków poszło i stanęło naprzeciwko nich z daleka. Oni zaś obaj stanęli nad Jordanem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 8, 'Wtedy Eliasz wziął swój płaszcz, zwinął go i uderzył nim wody, a one rozdzieliły się w obydwie strony, tak że przeszli obaj po suchej ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 9, 'A gdy przeszli, Eliasz powiedział do Elizeusza: Proś o to, co mam dla ciebie uczynić, zanim będę od ciebie zabrany. Elizeusz odpowiedział: Proszę, niech spocznie na mnie podwójna część twojego ducha;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 10, 'On zaś powiedział: Poprosiłeś o trudną rzecz. Jeśli mnie zobaczysz, gdy będę zabierany od ciebie, tak ci się stanie. Lecz jeśli nie, to się nie stanie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 11, 'Kiedy więc szli i rozmawiali, oto ognisty rydwan i ogniste konie oddzieliły ich obu. I Eliasz wstąpił wśród wichru do nieba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 12, 'Elizeusz zaś zobaczył to i zawołał: Mój ojcze, mój ojcze! Rydwanie Izraela i jego jeźdźcze. I nie zobaczył go już więcej. Chwycił swoje szaty i rozdarł je na dwie części.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 13, 'Potem podniósł płaszcz Eliasza, który spadł z niego, zawrócił i stanął nad brzegiem Jordanu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 14, 'I wziął płaszcz Eliasza, który spadł z niego, uderzył nim wody i powiedział: Gdzie jest Pan, Bóg Eliasza? Również gdy on uderzył nim wody, rozdzieliły się na dwie strony. I Elizeusz przeszedł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 15, 'A gdy synowie proroków, którzy byli w Jerychu, zobaczyli go z naprzeciwka, powiedzieli: Duch Eliasza spoczął na Elizeuszu. Wyszyli mu więc naprzeciw i pokłonili mu się aż do ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 16, 'I powiedzieli do niego: Oto teraz wśród twoich sług jest pięćdziesięciu dzielnych mężczyzn. Proszę, niech idą i niech szukają twego pana; może Duch Pana uniósł go i spuścił na jakąś górę albo w jakąś dolinę. Lecz on powiedział: Nie posyłajcie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 17, 'A gdy tak nalegali, aż do uprzykrzenia, powiedział: Poślijcie. Posłali więc tych pięćdziesięciu mężczyzn, którzy szukali przez trzy dni, lecz nie znaleźli go.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 18, 'A gdy wrócili do niego – bo przebywał w Jerychu – powiedział do nich: Czyż nie mówiłem wam: Nie idźcie?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 19, 'Potem ludzie tego miasta powiedzieli do Elizeusza: Oto położenie tego miasta jest dobre – jak ty, mój panie, widzisz. Lecz woda jest niedobra i ziemia nieurodzajna.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 20, 'Wtedy powiedział: Przynieście mi nowy dzbanek i włóżcie do niego soli. I przynieśli mu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 21, 'Wówczas poszedł do źródła wód, wrzucił do niego sól i powiedział: Tak mówi Pan: Uzdrowiłem te wody, już nie wyjdzie stąd ani śmierć, ani nieurodzaj.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 22, 'Wody więc zostały uzdrowione i są takie aż do dziś, według słowa Elizeusza, które wypowiedział.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 23, 'Potem wyruszył stamtąd do Betel. A gdy podążał drogą, małe dzieci wyszły z miasta i naśmiewały się z niego, mówiąc mu: Wstąp łysy, wstąp łysy!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 24, 'On zaś odwrócił się, spojrzał na nie i przeklął je w imieniu Pana. Wtedy dwie niedźwiedzice wyszły z lasu i rozszarpały czterdzieścioro dwoje dzieci spośród nich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 25, 'Stamtąd poszedł na górę Karmel, skąd wrócił do Samarii.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 1, 'Joram, syn Achaba, zaczął królować nad Izraelem w Samarii w osiemnastym roku Jehoszafata, króla Judy, i królował dwanaście lat.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 2, 'Czynił on to, co złe w oczach Pana, choć nie tak jak jego ojciec i matka. Usunął bowiem posąg Baala, który sporządził jego ojciec.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 3, 'Trwał jednak w grzechach Jeroboama, syna Nebata, który przywiódł Izraela do grzechu, i nie odstąpił od nich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 4, 'Mesza, król Moabu, był hodowcą owiec i dawał królowi Izraela sto tysięcy jagniąt oraz sto tysięcy baranów wraz z wełną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 5, 'Lecz kiedy Achab umarł, król Moabu zbuntował się przeciw królowi Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 6, 'W tym samym dniu król Joram wyszedł z Samarii i dokonał przeglądu całego Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 7, 'A gdy szedł, posłał do Jehoszafata, króla Judy, taką wiadomość: Król Moabu zbuntował się przeciwko mnie. Czy wyruszysz ze mną na wojnę przeciw Moabowi? Odpowiedział: Wyruszę. Ja tak, jak i ty, mój lud tak, jak i twój lud, moje konie tak, jak i twoje konie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 8, 'I zapytał: Którą drogą pójdziemy? Odpowiedział: Drogą przez pustynię Edomu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 9, 'Wyruszyli więc król Izraela, król Judy i król Edomu. A gdy krążyli drogą przez siedem dni, zabrakło wody dla wojska i dla bydła, które szło za nimi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 10, 'Wtedy król Izraela powiedział: Ach! Oto Pan zwołał tych trzech królów, aby oddać ich w ręce Moabu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 11, 'Lecz Jehoszafat rzekł: Czy nie ma tu proroka Pana, abyśmy przez niego radzili się Pana? Jeden ze sług króla Izraela odpowiedział: Jest tu Elizeusz, syn Szafata, który polewał wodą ręce Eliasza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 12, 'Jehoszafat powiedział: U niego jest słowo Pana. Poszli więc do niego – król Izraela, Jehoszafat i król Edomu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 13, 'Wtedy Elizeusz powiedział do króla Izraela: Co ja mam z tobą? Idź do proroków swojego ojca i do proroków swojej matki. Król Izraela odpowiedział: Nie, bo Pan zwołał tych trzech królów, aby oddać ich w ręce Moabu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 14, 'Elizeusz odpowiedział: Jak żyje Pan zastępów, przed którego obliczem stoję, gdybym nie miał względu na Jehoszafata, króla Judy, nie zważałbym na ciebie ani bym na ciebie nie spojrzał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 15, 'Teraz jednak przyprowadźcie mi harfiarza. A gdy harfiarz grał, spoczęła na nim ręka Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 16, 'I powiedział: Tak mówi Pan: Wykopcie w tej dolinie dużo rowów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 17, 'Tak bowiem mówi Pan: Nie zobaczycie wiatru ani nie zobaczycie deszczu, a jednak ta dolina napełni się wodą tak, że będziecie pić wy, wasze trzody i wasze bydło.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 18, 'Ale to jeszcze mało w oczach Pana. Wyda także Moabitów w wasze ręce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 19, 'Pobijecie wszystkie obwarowane miasta i wszystkie znaczne miasta, zetniecie wszystkie dobre drzewa, zasypiecie wszystkie źródła wód i spustoszycie każde dobre pole kamieniami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 20, 'Rankiem, w porze składania ofiary z pokarmów, oto przypłynęły wody od strony Edomu i ziemia napełniła się wodą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 21, 'Kiedy wszyscy Moabici usłyszeli, że królowie wyruszyli, aby walczyć z nimi, zwołali wszystkich zdolnych do noszenia zbroi, od najmłodszych do najstarszych, i stanęli na granicy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 22, 'Wstali rano, a gdy słońce wzeszło nad wodą, Moabici zobaczyli z naprzeciwka wodę czerwoną jak krew.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 23, 'I powiedzieli: To krew! Z pewnością królowie pobili się i zabili jeden drugiego. Teraz więc po łupy, o Moabie!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 24, 'A gdy przyszli do obozu Izraela, Izraelici powstali i pobili Moabitów, tak że ci uciekali przed nimi. Oni zaś szli naprzód, bijąc Moabitów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 25, 'Zburzyli miasta, na wszystkie dobre pola każdy rzucił swój kamień, aż je pokryli, zasypali wszystkie źródła wód i pościnali wszystkie dobre drzewa. Pozostały tylko kamienne mury Kir-Chareszet, ale procarze otoczyli je i zdobyli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 26, 'Kiedy król Moabu zobaczył, że nie podoła walce, wziął ze sobą siedmiuset mężczyzn dobywających miecz, aby się przebić do króla Edomu, ale nie zdołał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 27, 'Wziął więc swego pierworodnego syna, który miał królować w jego miejsce, i złożył go jako całopalenie na murze. Wtedy powstało wielkie oburzenie przeciw Izraelowi. Oni więc odstąpili od niego i wrócili do swej ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 1, 'A pewna kobieta spośród żon synów proroków wołała do Elizeusza: Twój sługa, mój mąż, umarł. Ty wiesz, że twój sługa bał się Pana. Lecz teraz przyszedł wierzyciel, aby zabrać moich dwóch synów jako niewolników.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 2, 'Elizeusz zapytał ją: Co mogę uczynić dla ciebie? Powiedz mi, co masz w domu? Odpowiedziała: Twoja służąca nie ma nic więcej w domu prócz dzbana oliwy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 3, 'Powiedział: Idź, pożycz sobie naczynia z zewnątrz od wszystkich swoich sąsiadów, naczynia puste – niemało.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 4, 'Potem wejdź do domu, zamknij drzwi za sobą i za swymi synami i nalewaj do wszystkich tych naczyń, a napełnione odstaw.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 5, 'Odeszła więc od niego, zamknęła drzwi za sobą i za swymi synami. Ci przynosili jej naczynia, a ona nalewała.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 6, 'Kiedy naczynia były pełne, powiedziała do swego syna: Przynieś mi jeszcze naczynie. Odpowiedział jej: Nie ma już naczyń. I oliwa przestała płynąć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 7, 'Potem przyszła i opowiedziała o tym mężowi Bożemu. On powiedział jej: Idź, sprzedaj oliwę i spłać dług. Z reszty zaś utrzymuj siebie i swoich synów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 8, 'Zdarzyło się pewnego dnia, że Elizeusz przechodził przez Szunem, gdzie mieszkała zacna kobieta, która zatrzymała go, aby spożył posiłek. Ilekroć więc tamtędy przechodził, wstępował do niej, by spożyć posiłek.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 9, 'Wtedy powiedziała do swego męża: Oto teraz wiem, że ten człowiek, który tędy ciągle przechodzi, jest świętym mężem Bożym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 10, 'Zróbmy mały górny pokój i wstawmy tam dla niego łóżko, stół, krzesło i świecznik. I kiedy przyjdzie do nas, uda się tam.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 11, 'Pewnego dnia, gdy tam przybył, udał się do tego pokoju i tam się położył.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 12, 'I powiedział do Gehaziego, swego sługi: Zawołaj tę Szunamitkę. Zawołał ją i stanęła przed nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 13, 'Wtedy mu rzekł: Powiedz jej: Oto troszczysz się i starasz się o wszystkie nasze potrzeby. Co chcesz, abym dla ciebie uczynił? Czy można przemówić za tobą do króla lub dowódcy wojska? Odpowiedziała: Ja mieszkam pośród swojego ludu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 14, 'On zapytał: Co więc można dla niej uczynić? Gehazi odpowiedział: Oto nie ma syna, a jej mąż jest stary.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 15, 'Polecił więc: Zawołaj ją. Zawołał ją i stanęła w drzwiach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 16, 'I powiedział: O tej porze za rok będziesz piastowała syna. Odpowiedziała: Nie, mój panie, mężu Boży, nie oszukuj swojej służącej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 17, 'Ale kobieta poczęła i urodziła syna po roku o tej porze, jak jej powiedział Elizeusz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 18, 'A gdy chłopiec podrósł, wyszedł pewnego dnia do swego ojca, do żniwiarzy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 19, 'I zawołał do swego ojca: Moja głowa! Moja głowa! On zaś powiedział słudze: Zanieś go do jego matki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 20, 'Wziął go więc i zaniósł do jego matki. I siedział na jej kolanach aż do południa, a potem umarł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 21, 'Wtedy ona poszła na górę i położyła go na łóżku męża Bożego, zamknęła drzwi i wyszła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 22, 'Potem zawołała swego męża i powiedziała: Proszę cię, przyślij mi jednego ze sług i jedną oślicę. Pobiegnę aż do męża Bożego i wrócę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 23, 'On zapytał: Po co chcesz jechać do niego? Nie ma dziś ani nowiu, ani szabatu. Ale ona rzekła: Będzie dobrze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 24, 'Osiodłała więc oślicę i powiedziała do swego sługi: Popędzaj ją i jedź! Nie wstrzymuj jazdy dla mnie, chyba że ci rozkażę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 25, 'Wyruszyła więc i przyjechała do męża Bożego na górę Karmel. A gdy mąż Boży zobaczył ją z daleka, powiedział do Gehaziego, swego sługi: Oto owa Szunamitka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 26, 'Wybiegnij, proszę, na jej spotkanie i zapytaj ją: Czy masz się dobrze? Czy dobrze się ma twój mąż? Czy dobrze się ma twój syn? Odpowiedziała: Dobrze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 27, 'A gdy przyszła do męża Bożego na górę, objęła go za nogi. A Gehazi zbliżył się, aby ją odepchnąć. Lecz mąż Boży powiedział: Zostaw ją, bo jej dusza jest pogrążona w smutku, a Pan zataił to przede mną i nie oznajmił mi tego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 28, 'Wtedy odezwała się: Czy prosiłam swego pana o syna? Czy nie powiedziałam: Nie oszukuj mnie?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 29, 'Wtedy on powiedział do Gehaziego: Przepasz swoje biodra, weź moją laskę do ręki i idź. Jeśli spotkasz kogoś, nie pozdrawiaj go, a jeśli ktoś ciebie pozdrowi, nie odpowiadaj mu. Połóż moją laskę na twarzy chłopca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 30, 'Lecz matka tego chłopca powiedziała: Jak żyje Pan i jak żyje twoja dusza, nie opuszczę cię. Wstał więc i poszedł za nią.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 31, 'Gehazi zaś wyprzedził ich i położył laskę na twarzy chłopca, lecz nie było ani głosu, ani słuchu. Wrócił więc naprzeciw niego i oznajmił mu: Chłopiec się nie obudził.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 32, 'Wtedy Elizeusz wszedł do domu, a oto zmarły chłopiec leżał na jego łóżku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 33, 'Wszedł więc, zamknął drzwi za nimi obydwoma i modlił się do Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 34, 'Następnie wszedł na łóżko, położył się na chłopcu, przyłożył swoje usta do jego ust, swoje oczy do jego oczu i swoje ręce do jego rąk. I rozciągnął się na nim, a ciało chłopca się rozgrzało.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 35, 'Potem wyszedł od niego, przechadzał się po domu tam i z powrotem, po czym wstąpił do pokoju i położył się na nim. Wtedy chłopiec kichnął siedem razy i otworzył oczy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 36, 'Wówczas zawołał Gehaziego i powiedział: Zawołaj Szunamitkę. Zawołał ją, a gdy przyszła do niego, powiedział: Zabierz swego syna.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 37, 'Ona więc weszła, upadła u jego nóg i ukłoniła się aż do ziemi, potem zabrała swego syna i wyszła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 38, 'Następnie Elizeusz wrócił do Gilgal, a w tej ziemi panował głód. Gdy synowie proroków siedzieli przed nim, powiedział do swego sługi: Wstaw wielki kocioł i ugotuj zupę dla synów proroków.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 39, 'Jeden z nich więc wyszedł na pole, aby nazbierać ziół, znalazł dzikie pnącze i narwał z niego pełen płaszcz dzikich owoców. Potem przyszedł i wkroił je do kotła z zupą, bo ich nie znano.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 40, 'Następnie nalano tym mężczyznom do jedzenia. A gdy jedli tę zupę, zawołali: Śmierć w kotle, mężu Boży! I nie mogli jeść.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 41, 'On zaś powiedział: Przynieście więc mąki. Wrzucił ją do kotła i powiedział: Nalej ludowi, aby jadł. I nie było już nic szkodliwego w kotle.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 42, 'Pewien człowiek przyszedł z Baal-Szalisza i przyniósł mężowi Bożemu chleb z pierwocin zbóż, dwadzieścia chlebów jęczmiennych i pełne kłosy świeżego zboża. On powiedział: Daj ludowi, aby jadł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 43, 'Ale jego sługa zapytał: Jak mam to położyć przed stu mężczyznami? Znowu powiedział: Daj ludowi, aby jadł. Tak bowiem mówi Pan: Będą jeść i jeszcze pozostanie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 44, 'Położył więc przed nimi, a ci jedli i jeszcze zostawili, według słowa Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 1, 'Naaman, dowódca króla Syrii, był człowiekiem bardzo poważanym u swego pana i osobą czcigodną. Przez niego bowiem Pan dał wybawienie Syryjczykom. Był on także dzielnym wojownikiem, ale trędowatym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 2, 'Gdy pewnego razu Syryjczycy wyszli w gromadach, uprowadzili z ziemi Izraela małą dziewczynkę, a ona służyła żonie Naamana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 3, 'Powiedziała do swojej pani: O gdyby mój pan udał się do proroka, który jest w Samarii! Ten na pewno uzdrowiłby go z trądu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 4, 'Naaman poszedł więc i oznajmił to swemu panu: Tak a tak powiedziała dziewczynka, która jest z ziemi Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 5, 'Na to król Syrii odpowiedział: Idź, jedź tam, a poślę list do króla Izraela. Wyruszył więc i wziął ze sobą dziesięć talentów srebra, sześć tysięcy syklów złota i dziesięć szat na zmianę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 6, 'I przyniósł list do króla Izraela o następującej treści: Kiedy ten list do ciebie dojdzie, wiedz, że posyłam do ciebie Naamana, swego sługę, abyś go uzdrowił z trądu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 7, 'A gdy król Izraela przeczytał list, rozdarł swoje szaty i powiedział: Czy ja jestem Bogiem, abym mógł uśmiercać i ożywiać, że ten posyła do mnie, abym uzdrowił człowieka z trądu? Zauważcie, proszę, i zobaczcie, że szuka on zaczepki ze mną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 8, 'Kiedy Elizeusz, mąż Boży, usłyszał, że król Izraela rozdarł swoje szaty, posłał do króla wiadomość: Czemu rozdarłeś swoje szaty? Niech on przyjdzie do mnie, a dowie się, że jest prorok w Izraelu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 9, 'Naaman przybył więc swymi końmi i swym rydwanem i stanął przed drzwiami domu Elizeusza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 10, 'Elizeusz zaś wysłał do niego posłańca z tymi słowami: Idź i umyj się siedem razy w Jordanie, a twoje ciało powróci do zdrowia i będziesz czysty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 11, 'Lecz Naaman rozgniewał się i odszedł, mówiąc: Oto myślałem sobie, że na pewno wyjdzie, stanie przy mnie, wezwie imienia Pana, swego Boga, poruszy swoją ręką nad miejscem trądu i uzdrowi trędowatego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 12, 'Czyż Abana i Parpar, rzeki Damaszku, nie są lepsze od wszystkich wód Izraela? Czy nie mógłbym się w nich obmyć i być czysty? Odwrócił się więc i odjechał w gniewie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 13, 'Lecz jego słudzy podeszli i powiedzieli do niego: Mój ojcze, gdyby ten prorok rozkazał ci zrobić coś wielkiego, czy byś tego nie uczynił? Tym bardziej gdy ci powiedział: Obmyj się, a będziesz czysty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 14, 'Poszedł więc i zanurzył się w Jordanie siedem razy, według słowa męża Bożego. I jego ciało stało się jak ciało małego dziecka, i został oczyszczony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 15, 'Potem wrócił do męża Bożego wraz z całym swoim orszakiem, a gdy przybył, stanął przed nim i powiedział: Oto teraz poznałem, że nie ma Boga na całej ziemi poza Izraelem. Przyjmij więc, proszę, dar od swego sługi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 16, 'Lecz on powiedział: Jak żyje Pan, przed którego obliczem stoję, nic nie wezmę. Tamten nalegał na niego, aby wziął, ale odmówił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 17, 'Wtedy Naaman powiedział: Proszę więc, niech dadzą twemu słudze tyle ziemi, ile udźwignie para mułów. Twój sługa bowiem nie będzie już składał ani całopalenia, ani innych ofiar obcym bogom, tylko Panu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 18, 'Jednak w tej sprawie niech Pan przebaczy twemu słudze: gdy mój pan wchodzi do świątyni Rimmona, aby tam oddać pokłon, a opiera się na moim ramieniu, wtedy i ja kłaniam się w świątyni Rimmona. Gdy więc ja się kłaniam w świątyni Rimmona, niech Pan przebaczy twemu słudze w tej sprawie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 19, 'Odpowiedział mu: Idź w pokoju. A gdy odjechał od niego kawałek drogi;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 20, 'Gehazi, sługa Elizeusza, męża Bożego, powiedział: Oto mój pan oszczędził tego Naamana, Syryjczyka, nie przyjmując z jego rąk tego, co przywiózł. Jak żyje Pan, pobiegnę za nim i wezmę coś od niego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 21, 'Gehazi więc pobiegł za Naamanem. Kiedy Naaman zobaczył, że biegnie za nim, zszedł z rydwanu i wyszedł mu naprzeciw, i zapytał: Czy wszystko jest dobrze?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 22, 'Odpowiedział: Dobrze. Mój pan posłał mnie, abym ci powiedział: Oto dopiero teraz przyszli do mnie dwaj młodzieńcy z góry Efraim spośród synów proroków. Daj im, proszę, talent srebra i dwie szaty na zmianę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 23, 'Naaman odpowiedział: Racz wziąć dwa talenty. Nalegał na niego i zawiązał dwa talenty srebra w dwóch workach oraz dwie szaty na zmianę, i włożył na dwóch jego sług, którzy je nieśli przed nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 24, 'A gdy przyszedł do twierdzy, wziął to z ich rąk i złożył w domu. Potem odprawił mężczyzn, a oni odeszli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 25, 'Sam zaś wszedł i stanął przed swoim panem. Elizeusz zapytał go: Skąd wracasz, Gehazi? Odpowiedział: Twój sługa nigdzie nie chodził.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 26, 'Lecz powiedział mu: Czy moje serce nie szło z tobą, kiedy tamten człowiek odwrócił się na swym rydwanie na twoje spotkanie? Czy to był czas przyjmowania srebra, przyjmowania szat, sadów oliwnych, winnic, owiec, wołów, sług i służących?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 27, 'Dlatego też trąd Naamana przylgnie do ciebie i do twojego potomstwa na wieki. I wyszedł od niego trędowaty, biały jak śnieg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 1, 'I synowie proroków powiedzieli do Elizeusza: Oto miejsce, w którym mieszkamy wraz z tobą, jest zbyt ciasne dla nas.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 2, 'Pozwól, że pójdziemy aż nad Jordan, weźmiemy stamtąd każdy po jednej belce i zbudujemy tam sobie miejsce na mieszkanie. Odpowiedział: Idźcie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 3, 'Jeden z nich powiedział: Racz, proszę, pójść ze swoimi sługami. Odpowiedział: Pójdę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 4, 'I poszedł z nimi. Kiedy przybyli nad Jordan, zaczęli ścinać drzewa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 5, 'I zdarzyło się, że jednemu z nich przy ścinaniu drzewa siekierą żelazo wpadło do wody. Zawołał wtedy: Ach, mój panie! Ta była pożyczona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 6, 'Mąż Boży zapytał: Gdzie wpadło? I wskazał mu miejsce. A on uciął drewno, wrzucił tam i żelazo wypłynęło.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 7, 'I powiedział: Weź je sobie. Wyciągnął więc rękę i wziął je.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 8, 'Potem, gdy król Syrii prowadził wojnę z Izraelem, naradzał się ze swoimi sługami, mówiąc: W tym a w tym miejscu będzie mój obóz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 9, 'Wtedy mąż Boży posłał do króla Izraela wiadomość: Strzeż się przechodzić przez to miejsce, bo tam Syryjczycy zrobili zasadzkę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 10, 'Posłał więc król Izraela na to miejsce, o którym mu powiedział mąż Boży, ostrzegając go, i król uratował się nie raz i nie dwa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 11, 'Serce króla Syrii zatrwożyło się z tego powodu. Zwołał więc swoje sługi i zapytał ich: Czemu mi nie powiecie, kto z nas donosi królowi Izraela?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 12, 'Jeden z jego sług odpowiedział: Nikt, mój panie, królu. To prorok Elizeusz, który jest w Izraelu, oznajmia królowi Izraela słowa, które wypowiadasz w swoim pokoju sypialnym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 13, 'On odpowiedział: Idźcie i dowiedzcie się, gdzie on jest, abym posłał po niego i pojmał go. I doniesiono mu: Oto jest w Dotan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 14, 'Posłał więc tam konie i rydwany, i znaczny oddział wojska. Wyruszyli w nocy i oblegli miasto.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 15, 'Kiedy sługa męża Bożego wstał wcześnie rano i wyszedł, oto wojsko otoczyło miasto razem z końmi i rydwanami. Jego sługa powiedział do niego: Ach, mój panie! Cóż mamy czynić?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 16, 'Odpowiedział: Nie bój się, bo więcej jest tych, którzy są z nami, niż tych, którzy są z nimi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 17, 'Wtedy modlił się Elizeusz: Panie, otwórz, proszę, jego oczy, aby widział. Pan otworzył oczy tego sługi i ten zobaczył: oto góra była pełna koni i ognistych rydwanów wokół Elizeusza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 18, 'A gdy Syryjczycy zeszli do niego, Elizeusz modlił się do Pana i powiedział: Proszę, dotknij ten lud ślepotą. I Pan dotknął go ślepotą według słowa Elizeusza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 19, 'Wtedy Elizeusz powiedział do nich: To nie ta droga ani nie to miasto. Pójdźcie za mną, a zaprowadzę was do człowieka, którego szukacie. I zaprowadził ich do Samarii.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 20, 'A gdy weszli do Samarii, Elizeusz powiedział: Panie, otwórz im oczy, aby przejrzeli. Pan otworzył im oczy i zobaczyli, że są w środku Samarii.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 21, 'Gdy król Izraela zobaczył ich, zapytał Elizeusza: Czy mam ich zabić, mój ojcze?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 22, 'Odpowiedział: Nie zabijaj. Czy zabijasz tych, których pojmałeś swoim mieczem i swoim łukiem? Połóż przed nimi chleb i wodę, aby jedli i pili, i wrócili do swego pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 23, 'Przygotował więc dla nich wielką ucztę. A gdy jedli i pili, odprawił ich i poszli do swego pana. Odtąd bandy Syryjczyków już nie wpadały do ziemi Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 24, 'Potem Ben-Hadad, król Syrii, zebrał całe swoje wojsko, wyruszył i obległ Samarię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 25, 'I nastał wielki głód w Samarii. Tak bowiem ją oblegali, że głowa osła kosztowała osiemdziesiąt srebrników, a ćwierć kaba gołębiego gnoju – pięć srebrników.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 26, 'A gdy król Izraela przechodził po murze, pewna kobieta zawołała do niego: Ratuj mnie, mój panie, królu!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 27, 'Odpowiedział: Jeśli Pan cię nie uratuje, jakże ja ciebie uratuję? Czy z klepiska lub z tłoczni?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 28, 'Następnie król zapytał ją: Co ci jest? Odpowiedziała: Ta oto kobieta powiedziała mi: Daj swojego syna, abyśmy go zjadły dzisiaj, a jutro zjemy mojego syna.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 29, 'Ugotowałyśmy więc mojego syna i zjadłyśmy go. Potem powiedziałam jej na drugi dzień: Daj swojego syna, abyśmy go zjadły. Lecz ona ukryła swojego syna.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 30, 'A gdy król usłyszał słowa tej kobiety, rozdarł swoje szaty. I kiedy przechodził po murze, lud zobaczył, że pod spodem nosił wór na swoim ciele.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 31, 'Wtedy król powiedział: Niech mi to uczyni Bóg i tamto dorzuci, jeśli głowa Elizeusza, syna Szafata, ostoi się na nim dzisiaj.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 32, 'Elizeusz zaś siedział w swoim domu i starsi siedzieli razem z nim. I król wysłał przed sobą człowieka. Lecz zanim posłaniec przyszedł do niego, powiedział do starszych: Czy widzicie, że ten syn mordercy posłał, aby mi ucięto głowę? Uważajcie, gdy ten posłaniec przyjdzie, zamknijcie drzwi i zatrzymajcie go przed drzwiami. Czy za nim nie słychać kroków mego pana?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 33, 'A gdy jeszcze z nimi rozmawiał, oto posłaniec przybył do niego i powiedział: To nieszczęście jest od Pana. Czego mam jeszcze oczekiwać od Pana?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 1, 'Wtedy Elizeusz powiedział: Słuchajcie słowa Pana. Tak mówi Pan: Jutro o tej porze w bramie Samarii jedna miara mąki pszennej będzie za jednego sykla i dwie miary jęczmienia też za sykla.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 2, 'Wówczas książę, na którego ramieniu król się wspierał, odezwał się do męża Bożego: Choćby Pan zrobił okna w niebie, czy mogłoby tak się stać? Odpowiedział mu: Oto zobaczysz to na własne oczy, ale jeść z tego nie będziesz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 3, 'A było czterech trędowatych mężczyzn u wejścia bramy. Mówili oni jeden do drugiego: Po co tu siedzimy, aż umrzemy?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 4, 'Jeśli powiemy: Wejdziemy do miasta, w mieście jest głód i tam umrzemy. A jeśli zostaniemy tu, również umrzemy. Teraz więc chodźcie i przejdźmy do obozu Syryjczyków. Jeśli pozostawią nas przy życiu, będziemy żyć, a jeśli nas zabiją, umrzemy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 5, 'Wstali więc o zmierzchu, aby przejść do obozu Syryjczyków. A gdy dotarli do krańca obozu Syryjczyków, oto nikogo tam nie było.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 6, 'Pan bowiem sprawił, że w obozie Syryjczyków słychać było turkot rydwanów, tętent koni i gwar wielkiego wojska. Mówili jeden do drugiego: Oto król Izraela najął przeciwko nam królów chetyckich i królów Egiptu, aby na nas napadli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 7, 'Wstali więc i uciekli o zmierzchu, zostawiając swoje namioty, swoje konie i osły – cały obóz tak, jak był, i uciekli, aby ratować swoje życie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 8, 'A gdy trędowaci dotarli do krańca obozu, weszli do jednego namiotu, jedli, pili, wynieśli stamtąd srebro, złoto i szaty, po czym poszli i ukryli to. Następnie wrócili, weszli do drugiego namiotu, również wynieśli stamtąd łup, odeszli i ukryli go.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 9, 'Wtedy powiedzieli jeden do drugiego: Niedobrze czynimy. Ten dzień jest dniem dobrej nowiny, a my milczymy. Jeśli będziemy czekać aż do brzasku, spotka nas kara. Chodźcie więc teraz, pójdźmy i opowiadajmy o tym domowi króla.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 10, 'Przyszli więc i zawołali na strażnika bramy miejskiej. Powiedzieli im: Przyszliśmy do obozu Syryjczyków, a oto nikogo tam nie było, nie słychać było głosu ludzkiego, widzieliśmy tylko uwiązane konie i osły oraz namioty, tak jak były.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 11, 'Wtedy zawołał on innych strażników, a ci opowiedzieli o tym we wnętrzu domu króla.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 12, 'Wówczas król wstał w nocy i powiedział do swoich sług: Powiem wam, co nam uczynili Syryjczycy: wiedzą, że głodujemy. Wyszli więc z obozu i ukryli się w polu, mówiąc: Gdy wyjdą z miasta, pojmiemy ich żywych i wejdziemy do miasta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 13, 'Jeden z jego sług odpowiedział: Niech wezmą, proszę, pięć spośród reszty koni, które zostały w mieście – oto są one jak całe mnóstwo Izraela, które zostało w nim, oto są one jak całe mnóstwo Izraela, które już zginęło – wyślemy je i zobaczymy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 14, 'Wzięli więc dwa konie zaprzęgowe, które król posłał do obozu Syryjczyków, mówiąc: Idźcie i zobaczcie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 15, 'Szli za nimi aż do Jordanu. A oto cała droga była pełna szat i naczyń, które Syryjczycy porzucili w pośpiechu. Wtedy posłańcy wrócili i oznajmili to królowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 16, 'Wówczas lud wyszedł i złupił obóz Syryjczyków. I jedna miara mąki pszennej była za sykla i dwie miary jęczmienia za sykla, według słowa Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 17, 'A król ustanowił tego księcia, na którego ramieniu się wspierał, nadzorcą bramy. Lud jednak zadeptał go w bramie na śmierć, jak powiedział mąż Boży, który o tym mówił, gdy król zszedł do niego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 18, 'I stało się tak, jak powiedział królowi mąż Boży: Dwie miary jęczmienia za sykla i jedna miara mąki pszennej za sykla będą jutro o tej porze w bramie Samarii.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 19, 'Wtedy ten książę odpowiedział mężowi Bożemu: Choćby Pan zrobił okna w niebie, czy mogłoby tak się stać? Odpowiedział: Oto zobaczysz to na własne oczy, ale jeść z tego nie będziesz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 20, 'I tak się z nim stało. Lud bowiem zadeptał go w bramie i książę umarł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 1, 'Potem Elizeusz odezwał się do tej kobiety, której syna wskrzesił: Wstań i idź, ty i twój dom, zamieszkaj jako przybysz tam, gdziekolwiek będziesz mogła zamieszkać. Pan bowiem wezwał głód, który nawiedzi ziemię na siedem lat.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 2, 'Wstała więc kobieta i uczyniła według słowa męża Bożego. Wyruszyła wraz ze swoim domem i przebywała w ziemi Filistynów przez siedem lat.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 3, 'Po upływie siedmiu lat kobieta wróciła z ziemi Filistynów. I udała się do króla, aby wołać o swój dom i swoje pole.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 4, 'A w tym czasie król rozmawiał z Gehazim, sługą męża Bożego: Opowiedz mi, proszę, o wszystkich wielkich dziełach, których dokonał Elizeusz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 5, 'A gdy on opowiadał królowi, jak wskrzesił umarłego, oto kobieta, której syna wskrzesił, zawołała na króla o swój dom i swoje pole. Gehazi powiedział: Mój panie, królu, to jest ta kobieta i to jej syn, którego wskrzesił Elizeusz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 6, 'Wtedy król wypytał kobietę, a ona mu odpowiedziała. I król przydzielił jej pewnego urzędnika, mówiąc: Przywróć jej wszystko, co do niej należało, oraz wszystkie dochody z pola od dnia, w którym opuściła ziemię, aż do teraz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 7, 'Potem Elizeusz przyszedł do Damaszku, a Ben-Hadad, król Syrii, chorował. I oznajmiono mu: Mąż Boży przyszedł tutaj.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 8, 'Wtedy król powiedział do Chazaela: Weź w ręce dar, wyjdź naprzeciw męża Bożego i przez niego zapytaj Pana: Czy wyzdrowieję z tej choroby?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 9, 'Chazael wyszedł więc naprzeciw niego i wziął ze sobą dar ze wszystkich dóbr Damaszku, załadowany na czterdziestu wielbłądach. Przyszedł i stanął przed nim, i powiedział: Twój syn Ben-Hadad, król Syrii, posłał mnie do ciebie z pytaniem: Czy wyzdrowieję z tej choroby?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 10, 'Elizeusz odpowiedział mu: Idź i powiedz mu: Na pewno wyzdrowiejesz. Lecz Pan objawił mi, że na pewno umrze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 11, 'Wtedy z twarzą zastygłą patrzył na niego, aż tamten się zawstydził. I mąż Boży zapłakał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 12, 'Chazael zapytał go: Czemu mój pan płacze? Odpowiedział: Bo wiem, jakie zło wyrządzisz synom Izraela. Ich twierdze spalisz ogniem, ich młodzieńców pomordujesz mieczem, ich dzieci roztrzaskasz i ich brzemienne rozprujesz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 13, 'Wtedy Chazael powiedział: Co? Czy twój sługa jest psem, żeby miał czynić tak straszną rzecz? Elizeusz odpowiedział: Pan pokazał mi, że ty będziesz królem nad Syrią.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 14, 'Potem odszedł od Elizeusza i przyszedł do swego pana, który zapytał go: Co ci powiedział Elizeusz? Odpowiedział: Powiedział mi, że na pewno wyzdrowiejesz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 15, 'A nazajutrz Chazael wziął kołdrę, zamoczył ją w wodzie i rozciągnął na jego twarzy, tak że umarł. Chazael zaś królował w jego miejsce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 16, 'W piątym roku Jorama, syna Achaba, króla Izraela, gdy Jehoszafat był jeszcze królem Judy, zaczął królować Jehoram, syn Jehoszafata, król Judy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 17, 'Miał trzydzieści dwa lata, kiedy zaczął królować, i królował osiem lat w Jerozolimie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 18, 'Lecz szedł drogami królów Izraela, tak jak to czynił dom Achaba, bo miał za żonę córkę Achaba i czynił to, co złe w oczach Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 19, 'Pan jednak nie chciał wytracić Judy ze względu na Dawida, swego sługę, tak jak mu obiecał, że da pochodnię jemu oraz jego synom po wszystkie dni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 20, 'Za jego dni Edom wyzwolił się spod ręki Judy i ustanowili nad sobą króla.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 21, 'Wyruszył więc Joram do Seiru wraz ze wszystkimi rydwanami. Wstał on w nocy i pobił Edomitów, którzy go otoczyli, oraz dowódców rydwanów. Lud zaś uciekał do swoich namiotów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 22, 'Edom jednak wyzwolił się spod ręki Judy i jest tak aż do dziś. W tym czasie wyzwoliła się również Libna.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 23, 'A pozostałe dzieje Jorama i wszystko, co czynił, czy nie są zapisane w kronikach królów Judy?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 24, 'I Joram zasnął ze swoimi ojcami, i został pogrzebany z nimi w mieście Dawida. W jego miejsce królował jego syn Achazjasz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 25, 'W dwunastym roku Jorama, syna Achaba, króla Izraela, zaczął królować Achazjasz, syn Jorama, króla Judy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 26, 'Achazjasz miał dwadzieścia dwa lata, kiedy zaczął królować, i królował jeden rok w Jerozolimie. Jego matka miała na imię Atalia i była córką Omriego, króla Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 27, 'Szedł on drogą domu Achaba i czynił to, co złe w oczach Pana, jak dom Achaba. Był bowiem zięciem domu Achaba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 28, 'Wyruszył z Joramem, synem Achaba, na wojnę z Chazaelem, królem Syrii, do Ramot-Gilead, ale Syryjczycy zranili Jorama.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 29, 'Król Joram wrócił więc, aby się leczyć w Jizreel z ran, które mu zadali Syryjczycy w Rama, gdy walczył z Chazaelem, królem Syrii. I Achazjasz, syn Jorama, króla Judy, przybył odwiedzić Jorama, syna Achaba, w Jizreel, ponieważ był chory.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 1, 'A prorok Elizeusz zawołał jednego z synów proroków i powiedział mu: Przepasz swoje biodra, weź do ręki ten dzban z oliwą i idź do Ramot-Gilead.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 2, 'A gdy tam przybędziesz, zobaczysz tam Jehu, syna Jehoszafata, syna Nimsziego. Wejdź tam, spraw, by powstał spośród swych braci i wprowadź go do najskrytszej komnaty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 3, 'Następnie weź dzban oliwy, wylej na jego głowę i powiedz: Tak mówi Pan: Namaściłem cię na króla nad Izraelem. Potem otwórz drzwi i uciekaj, nie zwlekaj.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 4, 'Poszedł więc ten młodzieniec – młody prorok – do Ramot-Gilead.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 5, 'A gdy przybył, oto dowódcy wojska siedzieli. A on powiedział: Wodzu! Mam do ciebie słowo. Jehu zapytał: Do którego z nas wszystkich? I odpowiedział: Do ciebie, wodzu!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 6, 'Wtedy wstał i wszedł do domu, a tamten wylał oliwę na jego głowę i powiedział mu: Tak mówi Pan, Bóg Izraela: Namaściłem cię na króla nad ludem Pana, nad Izraelem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 7, 'Wytracisz dom Achaba, swego pana, ja bowiem pomszczę krew swoich sług, proroków i krew wszystkich sług Pana z ręki Jezabel.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 8, 'I tak zginie cały dom Achaba. Wytępię z domu Achaba każdego, aż do najmniejszego szczenięcia, każdego więźnia i opuszczonego w Izraelu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 9, 'I uczynię z domem Achaba jak z domem Jeroboama, syna Nebata, i jak z domem Baszy, syna Achiasza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 10, 'Psy zjedzą Jezabel na polu Jizreel i nie będzie nikogo, kto ją pogrzebie. Potem otworzył drzwi i uciekł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 11, 'A gdy Jehu wyszedł do sług swego pana, jeden z nich zapytał go: Czy wszystko dobrze? Po co ten szaleniec przyszedł do ciebie? Odpowiedział im: Wy znacie tego człowieka i jego słowa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 12, 'Oni powiedzieli: To nieprawda. Powiedz, proszę. A on powiedział: Tak a tak przemówił do mnie: Tak mówi Pan: Namaściłem cię na króla nad Izraelem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 13, 'Wtedy wszyscy pospiesznie wzięli swoje szaty, podłożyli je pod niego na najwyższym stopniu, zadęli w trąbę i zawołali: Jehu jest królem!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 14, 'Wtedy Jehu, syn Jehoszafata, syna Nimsziego, uknuł spisek przeciw Joramowi. (A w tym czasie Joram wraz z całym Izraelem strzegł Ramot-Gilead przed Chazaelem, królem Syrii.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 15, 'Lecz król Joram wrócił, by leczyć się w Jizreel z ran, które mu zadali Syryjczycy, gdy walczył z Chazaelem, królem Syrii). Jehu powiedział: Jeśli się na to zgadzacie, niech nikt nie wychodzi z miasta, aby pójść i oznajmić to w Jizreel.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 16, 'Następnie Jehu wsiadł na rydwan i pojechał do Jizreel, bo tam leżał Joram. Także Achazjasz, król Judy, przyjechał, aby odwiedzić Jorama.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 17, 'A gdy strażnik, który stał na wieży w Jizreel, zobaczył nadjeżdżający oddział Jehu, powiedział: Widzę oddział. Joram rzekł: Weź jeźdźca i wyślij go naprzeciw nich, niech zapyta: Czy jest pokój?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 18, 'Jeździec więc wyruszył mu naprzeciw i zapytał: Tak mówi król: Czy jest pokój? Jehu odpowiedział: Co tobie do pokoju? Zawróć i jedź za mną. Strażnik oznajmił: Posłaniec dotarł do nich, ale nie wraca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 19, 'Wysłał więc drugiego jeźdźca, który przybył do nich i powiedział: Tak mówi król: Czy jest pokój? Jehu odpowiedział: Co tobie do pokoju? Zawróć i jedź za mną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 20, 'Strażnik znowu oznajmił: Dotarł do nich, ale nie wraca. A jego jazda jest jak jazda Jehu, syna Nimsziego, bo jedzie jak szalony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 21, 'Wtedy Joram powiedział: Zaprzęgaj. Zaprzężono więc jego rydwan. I Joram, król Izraela, i Achazjasz, król Judy, wyjechali, każdy na swoim rydwanie. Wyjechali naprzeciw Jehu i spotkali go na polu Nabota Jizreelity.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 22, 'A gdy Joram zobaczył Jehu, zapytał: Czy jest pokój, Jehu? Odpowiedział: Co to za pokój, dopóki trwają cudzołóstwa Jezabel, twojej matki, i jej liczne czary.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 23, 'Wtedy Joram zawrócił i uciekł, mówiąc do Achazjasza: Zdrada, Achazjaszu!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 24, 'A Jehu wziął do rąk łuk i trafił Jorama między ramiona tak, że strzała przeszyła jego serce, a on padł na swój rydwan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 25, 'Potem Jehu odezwał się do Bidkara, swego dowódcy: Weź go i porzuć na polu Nabota Jizreelity. Pamiętasz bowiem: gdy ja i ty jechaliśmy razem za Achabem, jego ojcem, Pan wydał przeciwko niemu ten wyrok:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 26, 'Z pewnością widziałem wczoraj krew Nabota i krew jego synów – mówi Pan. I zemszczę się na tobie na tym polu – mówi Pan. Teraz więc weź go i porzuć na polu według słowa Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 27, 'Gdy zobaczył to Achazjasz, król Judy, zaczął uciekać drogą do domu ogrodowego. Lecz Jehu ścigał go i polecił: Tego także zabijcie na jego rydwanie. I zranili go na wzniesieniu Gur, które jest przy Jibleam. Uciekł do Megiddo i tam umarł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 28, 'Jego słudzy przewieźli go do Jerozolimy i pogrzebali w jego grobie z jego ojcami w mieście Dawida.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 29, 'W jedenastym roku Jorama, syna Achaba, Achazjasz zaczął królować nad Judą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 30, 'Potem Jehu przybył do Jizreel. Gdy Jezabel usłyszała o tym, pomalowała swoją twarz, upiększyła włosy i wyglądała przez okno.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 31, 'A gdy Jehu wjeżdżał przez bramę, zapytała: Czy miał pokój Zimri, który zabił swego pana?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 32, 'On zaś podniósł twarz ku oknu i zawołał: Kto jest ze mną? Kto? Wtedy wyjrzeli ku niemu dwaj albo trzej eunuchowie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 33, 'Powiedział im: Zrzućcie ją. Wtedy zrzucili ją. Jej krew obryzgała mur i konie, a on podeptał ją.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 34, 'A gdy tam wszedł, najadł się i napił, potem powiedział: Zajmijcie się teraz tą przeklętą i pogrzebcie ją. Jest bowiem córką króla.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 35, 'Poszli, aby ją pogrzebać, lecz nie znaleźli z niej nic poza czaszką, stopami i dłońmi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 36, 'Wrócili więc i oznajmili mu to. On zaś powiedział: Wypełniło się słowo Pana, które wypowiedział przez swego sługę Eliasza Tiszbitę: Na polu Jizreel psy zjedzą ciało Jezabel.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 37, 'A trup Jezabel będzie jak gnój leżący na powierzchni roli, na polu Jizreel, tak że nikt nie powie: To jest Jezabel.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 1, 'Achab zaś miał siedemdziesięciu synów w Samarii. I Jehu napisał list, i wysłał go do Samarii do książąt Jizreel – do starszych i do tych, którzy wychowywali synów Achaba – ze słowami:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 2, 'Jak tylko dotrze do was ten list, a są przecież z wami synowie waszego pana, macie też rydwany, konie, miasto obronne i uzbrojenie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 3, 'Upatrzcie sobie najlepszego i najodpowiedniejszego z synów waszego pana, posadźcie na tronie jego ojca i walczcie o dom waszego pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 4, 'Lecz oni bardzo się przerazili i powiedzieli: Oto dwaj królowie nie ostali się przed nim, a jakże my się ostoimy?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 5, 'Wtedy ten, który był postawiony nad domem, i ten, który był nad miastem, starsi oraz wychowawcy synów króla wysłali do Jehu wiadomość: Jesteśmy twoimi sługami. Uczynimy wszystko, co nam rozkażesz. Nie ustanowimy żadnego króla. Czyń, co uznasz za dobre w swoich oczach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 6, 'I napisał do nich drugi list ze słowami: Jeśli jesteście moi i chcecie słuchać mego głosu, weźcie głowy synów waszego pana i przyjdźcie do mnie jutro o tym czasie do Jizreel. A synów królewskich było siedemdziesięciu mężczyzn, przebywających u znakomitych obywateli miasta, którzy ich wychowywali.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 7, 'A gdy doszedł do nich list, wzięli synów królewskich, zabili wszystkich siedemdziesięciu, włożyli ich głowy do koszy i posłali je do niego do Jizreel.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 8, 'Posłaniec przyszedł i oznajmił mu: Przyniesiono głowy synów królewskich. A on powiedział: Ułóżcie je w dwa stosy u wejścia bramy – aż do poranku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 9, 'Rano zaś wyszedł, stanął i przemówił do całego ludu: Jesteście sprawiedliwi. Oto uknułem spisek przeciw swemu panu i zabiłem go, ale kto zabił tych wszystkich?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 10, 'Wiedzcie teraz, że nie upadnie na ziemię nic ze słowa Pana, które Pan wypowiedział przeciwko domowi Achaba. Pan bowiem uczynił to, co wypowiedział przez swego sługę Eliasza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 11, 'Jehu więc zabił wszystkich, którzy pozostali z domu Achaba w Jizreel, wszystkich jego możnych, jego bliskich i jego kapłanów, tak że nie zostawił spośród nich żadnego przy życiu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 12, 'Potem wstał, odszedł i wyruszył do Samarii. Po drodze, gdy był w domu, gdzie pasterze strzygli owce;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 13, 'Jehu spotkał braci Achazjasza, króla Judy, i zapytał: Kim jesteście? Odpowiedzieli: Jesteśmy braćmi Achazjasza i idziemy pozdrowić synów króla i synów królowej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 14, 'Wtedy rozkazał: Pojmijcie ich żywcem. I pojmali ich żywcem, i zabili przy studni tego domu, gdzie strzyżono owce w liczbie czterdziestu dwóch mężczyzn. Nie oszczędził żadnego z nich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 15, 'Potem odjechał stamtąd i spotkał Jonadaba, syna Rechaba, idącego mu naprzeciw. Pozdrowił go i zapytał: Czy twoje serce jest tak szczere jak moje serce wobec twojego serca? Jonadab odpowiedział: Jest. A jeśli jest, to daj mi swoją rękę. Wtedy dał mu swą rękę i wziął go do siebie na rydwan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 16, 'Potem powiedział: Jedź ze mną i zobaczysz moją gorliwość dla Pana. I wiózł go na swoim rydwanie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 17, 'A gdy przyjechał do Samarii, zabił wszystkich, którzy pozostali z domu Achaba w Samarii, i wytracił ich według słowa Pana, które wypowiedział do Eliasza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 18, 'Potem Jehu zebrał cały lud i powiedział do niego: Achab mało służył Baalowi, Jehu będzie mu służył bardziej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 19, 'Teraz więc zwołajcie do mnie wszystkich proroków Baala, wszystkie jego sługi i wszystkich jego kapłanów, niech nikogo nie zabraknie. Złożę bowiem wielką ofiarę Baalowi. Ktokolwiek się nie stawi, nie pozostanie przy życiu. Lecz Jehu działał podstępnie, chcąc wytracić czcicieli Baala.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 20, 'Jehu dalej rozkazał: Ogłoście święto dla Baala. I obwołano je.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 21, 'Potem Jehu rozesłał posłańców po całym Izraelu. I zeszli się wszyscy czciciele Baala, tak że nie było spośród nich nikogo, kto by nie przyszedł. Weszli do domu Baala i wypełnił się dom Baala od krańca aż do krańca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 22, 'Następnie powiedział przełożonemu szatni: Wyłóż szaty dla wszystkich czcicieli Baala. I wyłożył dla nich szaty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 23, 'Wtedy Jehu wraz z Jonadabem, synem Rechaba, wszedł do domu Baala i powiedział czcicielom Baala: Zbadajcie i upewnijcie się, że nie ma z wami nikogo z czcicieli Pana, ale tylko czciciele Baala.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 24, 'Weszli więc, aby złożyć ofiary i całopalenia. Lecz Jehu postawił sobie na zewnątrz osiemdziesięciu mężczyzn, którym powiedział: Jeśli ujdzie ktokolwiek z tego ludu, który wydaję w wasze ręce, to wasze życie będzie zapłatą za jego życie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 25, 'A gdy dokończono składanie całopalenia, Jehu powiedział żołnierzom i dowódcom: Wejdźcie i zabijajcie ich, aby nikt nie uszedł. Zabili więc ich ostrzem miecza i żołnierze i dowódcy powyrzucali ich. Potem poszli do miasta domu Baala.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 26, 'Wyrzucili posągi z domu Baala i spalili je.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 27, 'Rozbili też posąg Baala, zburzyli dom Baala i uczynili z niego wychodek, i jest tak aż do dziś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 28, 'W ten sposób Jehu wytępił Baala z Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 29, 'Nie odstąpił jednak od grzechów Jeroboama, syna Nebata, który do grzechu przywiódł Izraela – od złotych cielców, które były w Betel i w Dan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 30, 'Wtedy Pan powiedział do Jehu: Ponieważ dobrze postąpiłeś, wykonując to, co słuszne w moich oczach, i uczyniłeś domowi Achaba według wszystkiego, co było w moim sercu, to twoi synowie aż do czwartego pokolenia będą zasiadać na tronie Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 31, 'Lecz Jehu nie pilnował tego, aby postępować z całego swego serca według prawa Pana, Boga Izraela. Nie odstąpił od grzechów Jeroboama, który przywiódł Izraela do grzechu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 32, 'W tych dniach Pan zaczął umniejszać Izrael: Chazael pobił ich na całym obszarze Izraela;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 33, 'Od Jordanu ku wschodowi, całą ziemię Gileadu, Gadytów, Rubenitów i Manassytów, od Aroeru, który leży nad rzeką Arnon – Gilead i Baszan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 34, 'A pozostałe dzieje Jehu i wszystko, co czynił, cała jego potęga, czy nie są zapisane w kronikach królów Izraela?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 35, 'I Jehu zasnął ze swymi ojcami, i pogrzebano go w Samarii. A w jego miejsce królował jego syn Jehoachaz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 36, 'A czas, w którym Jehu królował nad Izraelem w Samarii, wynosił dwadzieścia osiem lat.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 1, 'Kiedy Atalia, matka Achazjasza, zobaczyła, że jej syn umarł, powstała i zgładziła całe potomstwo królewskie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 2, 'Ale Jehoszeba, córka króla Jorama, siostra Achazjasza, wzięła Joasza, syna Achazjasza, i wykradła go spośród synów króla, których zabito; i ukryła go przed Atalią wraz z jego mamką w pokoju sypialnym, i nie został zabity.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 3, 'I przebywał z nią sześć lat ukryty w domu Pana. Tymczasem Atalia królowała nad ziemią.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 4, 'A w siódmym roku Jehojada posłał i wezwał setników, dowódców i gwardzistów, przyprowadził ich do siebie, do domu Pana, zawarł z nimi przymierze, kazał im złożyć przysięgę w domu Pana i pokazał im syna króla.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 5, 'I rozkazał im: Oto co macie uczynić: trzecia część z was, którzy przychodzicie w szabat, niech pełni straż w domu królewskim;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 6, 'Trzecia część zostanie w bramie Sur i trzecia część będzie w bramie za gwardzistami. Będziecie trzymali straż nad domem w razie ataku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 7, 'A dwie części spośród was – wszyscy, którzy wychodzą w szabat, niech trzymają straż w domu Pana przy królu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 8, 'A tak otoczycie króla wokół, każdy z bronią w ręku. Ktokolwiek zbliży się do szeregów, niech będzie zabity. A wy bądźcie przy królu, gdy będzie wychodzić i wchodzić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 9, 'Setnicy uczynili wszystko tak, jak rozkazał kapłan Jehojada. Każdy wziął swoich ludzi, którzy przychodzili w szabat, i tych, którzy odchodzili w szabat, i przyszli do kapłana Jehojady.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 10, 'Wtedy kapłan dał setnikom włócznie i tarcze króla Dawida, które były w domu Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 11, 'A gwardziści stali, każdy z bronią w ręku, dokoła króla, od prawej strony świątyni aż do lewej strony świątyni, przy ołtarzu i świątyni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 12, 'Wtedy wyprowadził syna króla, włożył na niego koronę i wręczył mu Świadectwo. I ustanowiono go królem, i namaszczono go, a klaskając w dłonie, wołano: Niech żyje król!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 13, 'Kiedy Atalia usłyszała okrzyk gwardzistów i ludu, przyszła do ludu, do świątyni Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 14, 'A gdy spojrzała, oto król stał przy kolumnie według zwyczaju, a wokół króla książęta i trębacze. Cały lud ziemi radował się i dął w trąby. Wtedy Atalia rozdarła swoje szaty i wołała: Zdrada! Zdrada!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 15, 'Lecz kapłan Jehojada wydał rozkaz setnikom i dowódcom wojska i powiedział do nich: Wyprowadźcie ją ze świątyni poza szeregi, a ktokolwiek pójdzie za nią, niech będzie zabity mieczem. Kapłan bowiem powiedział: Niech nie będzie zabita w domu Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 16, 'Pochwycili więc ją, a gdy weszła na drogę, którą wjeżdżają konie do domu królewskiego, została tam zabita.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 17, 'Wtedy Jehojada zawarł przymierze między Panem a królem i ludem, aby byli ludem Pana, oraz między królem a ludem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 18, 'I cały lud tej ziemi wszedł do domu Baala i zburzył go. Rozbili doszczętnie jego ołtarze i posągi, a Mattana, kapłana Baala, zabili przed ołtarzami. Następnie kapłan ustanowił straż nad domem Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 19, 'Potem wziął setników, dowódców i gwardzistów oraz cały lud tej ziemi. I sprowadzili króla z domu Pana, i przyszli przez bramę gwardii do domu królewskiego. I zasiadł na tronie królów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 20, 'I cały lud tej ziemi radował się, a miasto się uspokoiło. Atalię zabili mieczem przy domu królewskim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 21, 'Jehoasz miał siedem lat, gdy zaczął królować.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 1, 'W siódmym roku Jehu zaczął królować Jehoasz i królował czterdzieści lat w Jerozolimie. Jego matka miała na imię Sibia, była z Beer-Szeby.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 2, 'Jehoasz czynił to, co słuszne w oczach Pana, przez wszystkie swoje dni, w których uczył go kapłan Jehojada.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 3, 'Wyżyn jednak nie zniesiono i lud jeszcze składał ofiary, i palił kadzidło na tych wyżynach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 4, 'I Jehoasz powiedział do kapłanów: Wszystkie pieniądze z ofiar poświęconych, które przynoszone są do domu Pana, pieniądze tych, którzy są spisani, pieniądze każdego według jego oszacowania i wszystkie pieniądze, które ktokolwiek dobrowolnie wnosi do domu Pana;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 5, 'Niech wezmą dla siebie kapłani, każdy od swego znajomego, i niech naprawią szkody domu Pana, gdziekolwiek taka szkoda się znajdzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 6, 'Lecz jeszcze w dwudziestym trzecim roku króla Jehoasza kapłani nie naprawili szkód domu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 7, 'Wtedy król Jehoasz wezwał kapłana Jehojadę oraz pozostałych kapłanów i mówił do nich: Czemu nie naprawiacie szkód domu? Teraz więc nie bierzcie pieniędzy od swoich znajomych, ale oddajcie je na naprawę szkód domu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 8, 'I kapłani zgodzili się na to, aby nie brać pieniędzy od ludu, oraz na to, że nie będą naprawiali szkód domu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 9, 'Wtedy kapłan Jehojada wziął jedną skrzynię, zrobił otwór w jej wieku i postawił ją przy ołtarzu po prawej stronie, którędy wchodzono do domu Pana. Kapłani zaś, którzy strzegli progu, wrzucali tam wszystkie pieniądze, które wnoszono do domu Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 10, 'A gdy widzieli, że w skrzyni było dużo pieniędzy, przychodził pisarz króla i najwyższy kapłan, którzy liczyli i chowali pieniądze znajdujące się w domu Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 11, 'I odważone pieniądze dawali do rąk kierowników robót, przełożonych nad domem Pana. Ci zaś wydawali je na cieśli i budowniczych, którzy naprawiali dom Pana;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 12, 'Na murarzy, na kamieniarzy, na kupno drewna i ciosanych kamieni do naprawy szkód w domu Pana i na wszelkie inne wydatki związane z naprawą tego domu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 13, 'Jednakże z pieniędzy, które przynoszono do domu Pana, nie sporządzono dla domu Pana srebrnych mis, nożyc, czasz, trąb ani żadnych złotych i srebrnych naczyń;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 14, 'Lecz dawano je robotnikom, którzy naprawiali za nie dom Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 15, 'I nie rozliczano ludzi, którym dawano pieniądze do ręki na opłacenie robotników, ponieważ postępowali uczciwie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 16, 'Lecz pieniędzy z ofiar za występek i pieniędzy z ofiar za grzech nie wnoszono do domu Pana, lecz należały do kapłanów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 17, 'Wtedy Chazael, król Syrii, wyruszył, aby walczyć z Gat i zdobył je. Potem Chazael postanowił wyruszyć przeciw Jerozolimie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 18, 'Jehoasz, król Judy, wziął więc wszystkie rzeczy poświęcone, które poświęcili Jehoszafat, Joram i Achazjasz, jego ojcowie, królowie Judy, i to, co sam poświęcił, oraz całe złoto, które znalazło się w skarbcach domu Pana i domu króla, i posłał to do Chazaela, króla Syrii. I ten wycofał się z Jerozolimy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 19, 'A pozostałe dzieje Jehoasza i wszystko, co czynił, czy nie są zapisane w kronikach królów Judy?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 20, 'Potem jego słudzy powstali i uknuli spisek przeciwko niemu, i zabili Joasza w domu na Millo, na drodze schodzącej do Silla;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 21, 'Jozachar, syn Szimeata, i Jozabad, syn Szomera, byli właśnie tymi sługami, którzy zabili go. A pogrzebali go z jego ojcami w mieście Dawida, a jego syn Amazjasz królował w jego miejsce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 1, 'W dwudziestym trzecim roku Joasza, syna Achazjasza, króla Judy, Jehoachaz, syn Jehu, zaczął królować nad Izraelem w Samarii i królował siedemnaście lat.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 2, 'A czynił to, co złe w oczach Pana, naśladując grzechy Jeroboama, syna Nebata, który przywiódł Izraela do grzechu, i nie odstąpił od nich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 3, 'I zapalił się gniew Pana przeciw Izraelowi, i wydał go w rękę Chazaela, króla Syrii, i w rękę Ben-Hadada, syna Chazaela, po wszystkie ich dni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 4, 'Ale gdy Jehoachaz błagał Pana, Pan go wysłuchał. Widział bowiem ucisk Izraela dręczonego przez króla Syrii.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 5, 'I Pan dał Izraelowi wybawcę, tak że wyszli spod ręki Syryjczyków, i synowie Izraela mieszkali w swoich namiotach jak dawniej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 6, 'Jednakże nie odstąpili od grzechów domu Jeroboama, który przywiódł Izraela do grzechu, ale chodzili w nich. A do tego jeszcze w Samarii został gaj.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 7, 'I Jehoachazowi nie pozostało więcej wojska jak tylko pięćdziesięciu jeźdźców, dziesięć rydwanów i dziesięć tysięcy pieszych, gdyż król Syrii wytracił ich i starł w proch.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 8, 'A pozostałe dzieje Jehoachaza i wszystko, co czynił, oraz jego potęga, czy nie są zapisane w kronikach królów Izraela?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 9, 'I Jehoachaz zasnął ze swymi ojcami, i pogrzebano go w Samarii, a jego syn Joasz królował w jego miejsce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 10, 'W trzydziestym siódmym roku Joasza, króla Judy, Jehoasz, syn Jehoachaza, zaczął królować nad Izraelem w Samarii i królował szesnaście lat;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 11, 'I czynił to, co złe w oczach Pana, nie odstępując od żadnych grzechów Jeroboama, syna Nebata, który przywiódł Izraela do grzechu – ale chodząc w nich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 12, 'A pozostałe dzieje Joasza i wszystko, co czynił, oraz jego potęga – to, jak walczył z Amazjaszem, królem Judy, czy nie są zapisane w kronikach królów Izraela?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 13, 'I Joasz zasnął ze swymi ojcami, a Jeroboam zasiadł na jego tronie. I Joasz został pogrzebany w Samarii razem z królami Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 14, 'A Elizeusz zapadł na ciężką chorobę, na którą miał umrzeć. Przyszedł do niego Joasz, król Izraela, i płakał nad nim, mówiąc: Mój ojcze, mój ojcze! Rydwanie Izraela i jego jeźdźcze!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 15, 'Wtedy Elizeusz powiedział mu: Weź łuk i strzały. Wziął więc łuk i strzały.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 16, 'Potem powiedział do króla Izraela: Weź łuk w rękę. I wziął go w rękę. Elizeusz zaś położył swoje ręce na ręce króla.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 17, 'I powiedział: Otwórz okno na wschód. A gdy je otworzył, Elizeusz polecił: Strzelaj! I strzelił, a on powiedział: Strzała wybawienia Pana i strzała wybawienia od Syryjczyków. Pobijesz bowiem Syryjczyków w Afek doszczętnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 18, 'Następnie powiedział: Weź strzały! I wziął. Wtedy rzekł do króla Izraela: Uderz w ziemię! I uderzył trzy razy, i zaprzestał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 19, 'Wtedy mąż Boży rozgniewał się na niego i powiedział: Trzeba było uderzyć pięć lub sześć razy. Wtedy byś pokonał Syrię doszczętnie. Lecz teraz pokonasz Syrię tylko trzy razy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 20, 'Potem Elizeusz umarł i pogrzebali go. A z nastaniem roku moabskie zgraje napadły na ziemię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 21, 'I zdarzyło się, że gdy grzebano pewnego człowieka, zobaczyli taką zgraję. Wrzucili więc tego człowieka do grobu Elizeusza. A gdy ten człowiek został tam wrzucony, dotknął kości Elizeusza, ożył i wstał na nogi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 22, 'Chazael zaś, król Syrii, uciskał lud Izraela po wszystkie dni Jehoachaza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 23, 'Pan jednak zlitował się nad nimi, był dla nich miłosierny i zwrócił się ku nim ze względu na swoje przymierze z Abrahamem, Izaakiem i Jakubem. Nie chciał ich wytracić ani nie odrzucił ich sprzed swego oblicza aż dotąd.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 24, 'I Chazael, król Syrii, umarł, a jego syn Ben-Hadad królował w jego miejsce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 25, 'Jehoasz, syn Jehoachaza, znowu odebrał z ręki Ben-Hadada, syna Chazaela, te miasta, które podczas wojny ten zabrał z ręki jego ojca Jehoachaza. Joasz pokonał go trzy razy i odzyskał miasta Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 1, 'W drugim roku Joasza, syna Jehoachaza, króla Izraela, zaczął królować Amazjasz, syn Joasza, króla Judy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 2, 'Miał dwadzieścia pięć lat, kiedy zaczął królować, i królował dwadzieścia dziewięć lat w Jerozolimie. Jego matka miała na imię Jehoaddan, była z Jerozolimy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 3, 'Czynił on to, co słuszne w oczach Pana, ale nie tak jak Dawid, jego ojciec. Czynił wszystko tak, jak czynił Joasz, jego ojciec.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 4, 'Wyżyn jednak nie zniesiono i lud jeszcze składał ofiary, i palił kadzidło na tych wyżynach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 5, 'A gdy królestwo umocniło się w jego ręku, zabił tych spośród swoich sług, którzy zabili króla, jego ojca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 6, 'Lecz synów morderców nie zabił zgodnie z tym, co jest napisane w księdze Prawa Mojżesza, gdzie Pan rozkazał: Ojcowie nie poniosą śmierci za synów ani synowie nie poniosą śmierci za ojców, ale każdy poniesie śmierć za swój grzech.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 7, 'On też pobił dziesięć tysięcy Edomitów w Dolinie Soli i zdobył w walce Selę, i nadał jej nazwę Jokteel, i tak nazywa się aż do dziś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 8, 'Wtedy Amazjasz wysłał posłańców do Jehoasza, syna Jehoachaza, syna Jehu, króla Izraela, ze słowami: Chodź, spójrzmy sobie w twarze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 9, 'Jehoasz zaś, król Izraela, wysłał do Amazjasza, króla Judy, taką odpowiedź: Oset w Libanie posłał do cedru w Libanie prośbę: Daj swoją córkę mojemu synowi za żonę. Lecz dziki zwierz w Libanie przeszedł i podeptał oset.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 10, 'Rzeczywiście, pobiłeś Edomitów i twoje serce uniosło się pychą. Chwal się tym i siedź w domu. Po co masz wdawać się w nieszczęście, abyś upadł ty i Juda z tobą?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 11, 'Lecz Amazjasz nie posłuchał. Wyruszył więc Jehoasz, król Izraela, i spojrzeli sobie w twarze, on i Amazjasz, król Judy, w Bet-Szemesz, które należy do Judy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 12, 'I Juda został pobity przez Izraela, i uciekł – każdy do swego namiotu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 13, 'A Jehoasz, król Izraela, pojmał Amazjasza, króla Judy, syna Jehoasza, syna Achazjasza, w Bet-Szemesz, przyszedł do Jerozolimy i zburzył mur Jerozolimy od Bramy Efraim aż do Bramy Narożnej, na czterysta łokci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 14, 'I zabrał całe złoto i srebro oraz wszystkie naczynia, które znajdowały się w domu Pana i w skarbcach domu królewskiego, a także zakładników, po czym wrócił do Samarii.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 15, 'A pozostałe dzieje Jehoasza, które czynił, i jego potęga, i to, jak walczył z Amazjaszem, królem Judy, czy nie są zapisane w księdze kronik królów Izraela?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 16, 'I Jehoasz zasnął ze swymi ojcami, i został pogrzebany w Samarii wraz z królami Izraela, a jego syn Jeroboam królował w jego miejsce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 17, 'Amazjasz zaś, syn Joasza, król Judy, żył piętnaście lat po śmierci Jehoasza, syna Jehoachaza, króla Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 18, 'A pozostałe dzieje Amazjasza – czy nie są zapisane w księdze kronik królów Judy?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 19, 'Potem uknuto przeciwko niemu spisek w Jerozolimie. Uciekł do Lakisz, lecz posłano za nim do Lakisz i tam go zabito.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 20, 'Przywieziono go na koniach i został pogrzebany w Jerozolimie ze swymi ojcami, w mieście Dawida.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 21, 'Cały lud Judy wziął Azariasza, który miał szesnaście lat, i ustanowili go królem po jego ojcu Amazjaszu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 22, 'On odbudował Elat i przywrócił je Judzie, po tym jak król zasnął ze swymi ojcami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 23, 'W piętnastym roku Amazjasza, syna Joasza, króla Judy, Jeroboam, syn Joasza, króla Izraela, zaczął królować w Samarii i królował czterdzieści jeden lat.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 24, 'Czynił on to, co złe w oczach Pana. Nie odstąpił od żadnego z grzechów Jeroboama, syna Nebata, który przywiódł Izraela do grzechu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 25, 'On przywrócił granice Izraela od wejścia do Chamat aż do Morza Stepowego, według słowa Pana, Boga Izraela, które wypowiedział przez swego sługę Jonasza, syna Amittaja, proroka z Gat-ha-Chefer.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 26, 'Pan bowiem widział gorzkie utrapienie Izraela. Nie było ani więźnia, ani opuszczonego, ani kogokolwiek, kto by pomógł Izraelowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 27, 'A Pan nie powiedział, że miał wymazać imię Izraela spod niebios. Wybawił ich więc przez rękę Jeroboama, syna Joasza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 28, 'A pozostałe dzieje Jeroboama i wszystko, co czynił, oraz jego potęga, to, jak walczył i jak przywrócił Izraelowi Damaszek i Chamat judzkie – czy nie są zapisane w księdze kronik królów Izraela?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 29, 'I Jeroboam zasnął ze swymi ojcami, z królami Izraela, a Zachariasz, jego syn, królował w jego miejsce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 1, 'W dwudziestym siódmym roku Jeroboama, króla Izraela, Azariasz, syn Amazjasza, króla Judy, zaczął królować.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 2, 'Miał szesnaście lat, kiedy zaczął królować, i królował pięćdziesiąt dwa lata w Jerozolimie. Jego matka miała na imię Jekolia, była z Jerozolimy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 3, 'Czynił on to, co słuszne w oczach Pana, wszystko tak jak czynił Amazjasz, jego ojciec.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 4, 'Wyżyn jednak nie zniesiono. Lud jeszcze składał ofiary i palił kadzidło na wyżynach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 5, 'I Pan dotknął króla – i był trędowaty aż do dnia swojej śmierci, i mieszkał w odosobnionym domu. Jotam więc, syn króla, zarządzał domem i sądził lud ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 6, 'A pozostałe dzieje Azariasza i wszystko, co czynił, czy nie są zapisane w księdze kronik królów Judy?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 7, 'I Azariasz zasnął ze swymi ojcami, i pogrzebano go wraz z nimi w mieście Dawida, a Jotam, jego syn, królował w jego miejsce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 8, 'W trzydziestym ósmym roku Azariasza, króla Judy, Zachariasz, syn Jeroboama, zaczął królować nad Izraelem w Samarii i królował sześć miesięcy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 9, 'I czynił to, co złe w oczach Pana, jak czynili jego ojcowie. Nie odstąpił od grzechów Jeroboama, syna Nebata, który przywiódł Izraela do grzechu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 10, 'Szallum, syn Jabesza, uknuł przeciwko niemu spisek i zranił go przed ludem, zabił go i królował w jego miejsce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 11, 'A pozostałe dzieje Zachariasza oto są zapisane w księdze kronik królów Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 12, 'Takie było słowo Pana, które wypowiedział do Jehu: Twoi synowie do czwartego pokolenia będą zasiadać na tronie Izraela. I tak się stało.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 13, 'Szallum, syn Jabesza, zaczął królować w trzydziestym dziewiątym roku Uzjasza, króla Judy, i królował jeden miesiąc w Samarii.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 14, 'Bo Menachem, syn Gadiego, przyszedł z Tirsy i wszedł do Samarii, i pobił Szalluma, syna Jabesza w Samarii, zabił go i królował w jego miejsce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 15, 'A pozostałe dzieje Szalluma i jego spisek, który uknuł, oto są zapisane w księdze kronik królów Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 16, 'Wtedy Menachem pobił Tifsach i wszystkich, którzy w nim byli, oraz wszystkie jego okolice, począwszy od Tirsy, gdyż nie otworzyli mu bram – dlatego je pobił, a wszystkie brzemienne mieszkanki rozpruwał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 17, 'W trzydziestym dziewiątym roku Azariasza, króla Judy, Menachem, syn Gadiego, zaczął królować nad Izraelem i królował dziesięć lat w Samarii.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 18, 'Czynił on to, co złe w oczach Pana. Przez wszystkie swoje dni nie odstąpił od grzechów Jeroboama, syna Nebata, który przywodził Izraela do grzechu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 19, 'A gdy Pul, król Asyrii, napadł na ziemię, Menachem dał Pulowi tysiąc talentów srebra, aby ten mu pomógł umocnić królestwo w swoim ręku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 20, 'I Menachem wymusił te pieniądze od Izraela, od wszystkich zamożnych – po pięćdziesiąt syklów srebra od każdego – aby je dać królowi Asyrii. Wycofał się więc król Asyrii i nie pozostał w tej ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 21, 'A pozostałe dzieje Menachema i wszystko, co czynił, czy nie są zapisane w księdze kronik królów Izraela?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 22, 'I Menachem zasnął ze swymi ojcami, a Pekachiasz, jego syn, królował w jego miejsce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 23, 'W pięćdziesiątym roku Azariasza, króla Judy, Pekachiasz, syn Menachema, zaczął królować nad Izraelem w Samarii i królował dwa lata.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 24, 'Czynił on to, co złe w oczach Pana. Nie odstąpił od grzechów Jeroboama, syna Nebata, który przywiódł Izraela do grzechu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 25, 'A Pekach, syn Remaliasza, jego dowódca, uknuł spisek przeciwko niemu i zabił go w Samarii, w pałacu domu królewskiego, a wraz z nim Argoba i Aria oraz pięćdziesięciu ludzi spośród Gileadczyków. Zabił go i królował po nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 26, 'A pozostałe dzieje Pekachiasza i wszystko, co czynił, oto są zapisane w księdze kronik królów Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 27, 'W pięćdziesiątym drugim roku Azariasza, króla Judy, Pekach, syn Remaliasza, zaczął królować nad Izraelem w Samarii i królował dwadzieścia lat.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 28, 'Czynił on to, co złe w oczach Pana. Nie odstąpił od grzechów Jeroboama, syna Nebata, który przywiódł Izraela do grzechu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 29, 'Za dni Pekacha, króla Izraela, nadciągnął Tiglat-Pileser, król Asyrii, i zdobył Ijon, Abel-Bet-Maaka, Janoach, Kedesz, Chasor, Gilead i Galileę, i całą ziemię Neftalego, a pojmanych uprowadził do Asyrii.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 30, 'Wtedy Ozeasz, syn Eli, uknuł spisek przeciwko Pekachowi, synowi Remaliasza. Pobił go i zabił, i zaczął królować w jego miejsce w dwudziestym roku Jotama, syna Uzjasza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 31, 'A pozostałe dzieje Pekacha i wszystko, co czynił, oto są zapisane w księdze kronik królów Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 32, 'W drugim roku Pekacha, syna Remaliasza, króla Izraela, Jotam, syn Uzjasza, króla Judy, zaczął królować.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 33, 'Miał dwadzieścia pięć lat, kiedy zaczął królować, i królował szesnaście lat w Jerozolimie. Jego matka miała na imię Jerusza i była córką Sadoka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 34, 'Czynił on to, co słuszne w oczach Pana. Czynił wszystko tak, jak czynił Uzjasz, jego ojciec.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 35, 'Wyżyn jednak nie zniesiono. Lud jeszcze składał ofiary i palił kadzidło na wyżynach. On zbudował Górną Bramę domu Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 36, 'A pozostałe dzieje Jotama i wszystko, co czynił, są zapisane w księdze kronik królów Judy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 37, 'W tych dniach Pan zaczął posyłać przeciw Judzie Resina, króla Syrii, i Pekacha, syna Remaliasza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 38, 'I Jotam zasnął ze swymi ojcami, i został pogrzebany z nimi w mieście Dawida, swego ojca. I Achaz, jego syn, królował w jego miejsce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 1, 'W siedemnastym roku Pekacha, syna Remaliasza, Achaz, syn Jotama, króla Judy, zaczął królować.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 2, 'Achaz miał dwadzieścia lat, kiedy zaczął królować, i królował szesnaście lat w Jerozolimie, ale nie czynił tego, co słuszne w oczach Pana, swego Boga, jak Dawid, jego ojciec;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 3, 'Lecz chodził drogami królów Izraela, a nawet swojego syna przeprowadził przez ogień według obrzydliwości pogan, których Pan wypędził sprzed oblicza synów Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 4, 'Składał ofiary i palił kadzidło na wyżynach, na pagórkach i pod każdym zielonym drzewem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 5, 'Wtedy Resin, król Syrii, i Pekach, syn Remaliasza, król Izraela, wyruszyli na wojnę przeciw Jerozolimie i oblegli Achaza, ale nie mogli go pokonać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 6, 'W tym samym czasie Resin, król Syrii, przywrócił Syrii Elat i wypędził Żydów z Elat, a Syryjczycy przybyli do Elat i mieszkają tam aż do dziś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 7, 'Achaz więc wysłał posłańców do Tiglat-Pilesera, króla Asyrii, ze słowami: Jestem twoim sługą i twoim synem. Przyjdź i wybaw mnie z ręki króla Syrii i z ręki króla Izraela, którzy powstali przeciw mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 8, 'Wtedy Achaz wziął srebro i złoto, które znajdowały się w domu Pana i w skarbcach domu królewskiego, i posłał je jako dar królowi Asyrii.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 9, 'I król Asyrii wysłuchał go. Wyruszył bowiem król Asyrii przeciw Damaszkowi, zdobył go i uprowadził jego mieszkańców do Kir, a Resina zabił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 10, 'Potem król Achaz udał się do Damaszku na spotkanie z Tiglat-Pilserem, królem Asyrii. Gdy zobaczył w Damaszku ołtarz, król Achaz posłał do kapłana Uriasza wzór tego ołtarza i cały plan jego budowy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 11, 'I kapłan Uriasz zbudował ołtarz dokładnie według tego, co król Achaz przesłał z Damaszku. Tak to uczynił kapłan Uriasz, zanim król Achaz wrócił z Damaszku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 12, 'A gdy król wrócił z Damaszku, zobaczył ołtarz, zbliżył się do niego i złożył na nim ofiary.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 13, 'Spalił swoje całopalenie i ofiarę z pokarmów, wylał swoją ofiarę z płynów i pokropił ołtarz krwią swoich ofiar pojednawczych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 14, 'Ołtarz zaś z brązu, który był przed Panem, przeniósł z przedniej części domu, gdzie znajdował się między ołtarzem a domem Pana, i postawił go po północnej stronie ołtarza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 15, 'Król Achaz rozkazał też kapłanowi Uriaszowi: Na wielkim ołtarzu będziesz palił poranną ofiarę całopalną i wieczorną ofiarę z pokarmów, a także całopalną ofiarę króla i jego ofiarę z pokarmów oraz całopalną ofiarę całego ludu ziemi, ich ofiarę z pokarmów i ich ofiary z płynów. Będziesz też kropił na nim wszelką krwią całopalenia i wszelką krwią z ofiar krwawych, ale ołtarz z brązu będzie dla mnie do szukania rady.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 16, 'I kapłan Uriasz uczynił wszystko zgodnie z tym, jak rozkazał król Achaz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 17, 'Król Achaz odciął też listwy podstawek i wyjął z nich kadzie. Zdjął również morze sponad wołów z brązu, które pod nim były, a postawił je na posadzce kamiennej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 18, 'Zadaszenie na szabat, które zbudowano w domu, oraz zewnętrzne wejście królewskie usunął z domu Pana ze względu na króla Asyrii.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 19, 'A pozostałe dzieje Achaza, które czynił, są zapisane w księdze kronik królów Judy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 20, 'I Achaz zasnął ze swymi ojcami, i został pogrzebany z nimi w mieście Dawida. A Ezechiasz, jego syn, królował w jego miejsce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 1, 'W dwunastym roku Achaza, króla Judy, Ozeasz, syn Eli, zaczął królować w Samarii nad Izraelem i królował dziewięć lat.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 2, 'Czynił on to, co złe w oczach Pana, jednak nie tak jak królowie Izraela, którzy byli przed nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 3, 'Przeciw niemu wyruszył Salmanaser, król Asyrii, a Ozeasz został jego sługą i płacił mu daninę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 4, 'I król Asyrii wykrył spisek Ozeasza. Ten bowiem wyprawił posłańców do So, króla Egiptu, i nie posłał corocznej daniny królowi Asyrii. Król Asyrii więc pojmał go i zamknął w więzieniu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 5, 'Król Asyrii najechał całą ziemię, przybył do Samarii i oblegał ją przez trzy lata.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 6, 'A w dziewiątym roku Ozeasza król Asyrii zdobył Samarię, uprowadził Izraela do Asyrii i osiedlił ich w Chalach i Chaborze, nad rzeką Gozan, oraz w miastach Medów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 7, 'A stało się tak, dlatego że synowie Izraela zgrzeszyli przeciw Panu, swemu Bogu, który ich wyprowadził z ziemi Egiptu, spod ręki faraona, króla Egiptu, a bali się obcych bogów;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 8, 'Postępując według ustaw pogan, których Pan wypędził sprzed oblicza synów Izraela, oraz ustaw królów Izraela, które stwarzali.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 9, 'Synowie Izraela robili potajemnie przeciwko Panu, swemu Bogu, to, co nie było słuszne, i pobudowali sobie wyżyny we wszystkich swoich miastach, od wieży strażników aż do miasta warownego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 10, 'Ustawiali sobie posągi i gaje na każdym wyniosłym pagórku i pod każdym zielonym drzewem;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 11, 'I palili tam kadzidła na wszystkich wyżynach, tak jak narody, które Pan wypędził przed nimi, i popełniali niegodziwe czyny, pobudzając Pana do gniewu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 12, 'Służyli bożkom, o których Pan im powiedział: Nie czyńcie tego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 13, 'A Pan świadczył przeciw Izraelowi i przeciw Judzie przez wszystkich proroków i wszystkich widzących, mówiąc: Odwróćcie się od swoich złych dróg i przestrzegajcie moich przykazań i moich nakazów według całego prawa, które nadałem waszym ojcom, a które przekazałem wam przez moje sługi, proroków.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 14, 'Lecz nie słuchali, ale uczynili twardym swój kark, jak kark ich ojców, którzy nie wierzyli w Pana, swego Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 15, 'I wzgardzili jego nakazami i przymierzem, które zawarł z ich ojcami, oraz jego świadectwami, którymi świadczył przeciwko nim, i chodzili za marnościami, stali się próżni i naśladowali pogan, którzy ich otaczali, co do których Pan im rozkazał, aby nie czynili tak jak oni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 16, 'I opuścili wszystkie przykazania Pana, swego Boga, i wykonali sobie lane posągi – dwa cielce. Zrobili sobie też gaje, oddawali pokłon wszystkim zastępom niebieskim i służyli Baalowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 17, 'Przeprowadzali swoich synów i swoje córki przez ogień, uprawiali wróżbiarstwo i czarnoksięstwo i zaprzedali się, aby czynić to, co złe w oczach Pana, pobudzając go do gniewu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 18, 'Dlatego Pan bardzo się rozgniewał na Izraela i odrzucił go sprzed swego oblicza. Nic nie pozostało oprócz samego pokolenia Judy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 19, 'Ale również i Juda nie przestrzegał przykazań Pana, swego Boga, lecz postępował według nakazów, które Izrael stworzył.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 20, 'Pan więc odrzucił całe potomstwo Izraela, trapił ich i wydał w ręce grabieżców, aż wreszcie odrzucił ich sprzed swego oblicza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 21, 'Oderwał bowiem Izraela od domu Dawida, a oni ustanowili królem Jeroboama, syna Nebata. Jeroboam zaś odwiódł Izraela od naśladowania Pana i przywiódł go do popełnienia wielkiego grzechu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 22, 'I synowie Izraela chodzili we wszystkich grzechach Jeroboama, które czynił, a nie odstąpili od nich;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 23, 'Aż Pan odrzucił Izraela sprzed swego oblicza, jak zapowiedział przez wszystkie swoje sługi, proroków. I tak Izrael został uprowadzony ze swojej ziemi do Asyrii, i tak jest aż do dziś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 24, 'Potem król Asyrii sprowadził ludzi z Babilonu, z Kuta, z Awwa i z Chamat, i z Sefarwaim i osiedlił ich w miastach Samarii zamiast synów Izraela. Oni zaś posiedli Samarię i mieszkali w jej miastach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 25, 'A gdy zaczęli tam mieszkać, nie bali się Pana. Pan więc zesłał na nich lwy, które ich zabijały.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 26, 'I doniesiono o tym królowi Asyrii: Narody, które uprowadziłeś i osiedliłeś w miastach Samarii, nie znają zwyczajów Boga tej ziemi. Dlatego zesłał na nich lwy, a oto zabijają ich, ponieważ nie znają zwyczajów Boga tej ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 27, 'Wtedy król Asyrii rozkazał: Zaprowadźcie tam jednego z kapłanów, których stamtąd uprowadziliście, aby poszedł i tam zamieszkał, i nauczał ich zwyczajów Boga tej ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 28, 'Przybył więc jeden z kapłanów, których uprowadzono z Samarii, i zamieszkał w Betel, i nauczał ich, jak mają się bać Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 29, 'Jednakże każdy naród czynił sobie własnych bogów i stawiał ich w domach wyżyn, które Samarytanie pobudowali, każdy naród w swoich miastach, w których mieszkał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 30, 'Babilończycy zrobili Sukkot-Benota, a ludzie z Kuta zrobili Nergala, a ludzie z Chamat zrobili Aszimę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 31, 'Awwici zrobili Nibchaza i Tartaka, a Sefarwaici palili swoje dzieci w ogniu dla Adrameleka i Anameleka, bogów Sefarwaim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 32, 'Tak więc bali się Pana i ustanowili spośród siebie kapłanów wyżyn, którzy składali dla nich ofiary w domach wyżyn.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 33, 'Bali się Pana i służyli swoim bogom według zwyczajów tych narodów, skąd zostali uprowadzeni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 34, 'Aż do tego dnia postępują według dawnych zwyczajów. Nie boją się Pana i nie czynią według jego ustaw, nakazów, prawa i przykazania, które Pan nakazał synom Jakuba, któremu nadał imię Izrael.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 35, 'Pan zawarł też z nimi przymierze i rozkazał im: Nie bójcie się obcych bogów, nie kłaniajcie się im, nie służcie im ani nie składajcie im ofiar;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 36, 'Lecz Pana, który was wyprowadził z ziemi Egiptu wielką mocą i wyciągniętym ramieniem, jego się bójcie, jemu oddawajcie pokłon i jemu składajcie ofiary.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 37, 'Przestrzegajcie także ustaw, nakazów, prawa i przykazań, które wam napisał, i wypełniajcie je po wszystkie dni, a nie bójcie się innych bogów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 38, 'Nie zapominajcie o przymierzu, które zawarłem z wami, i nie bójcie się innych bogów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 39, 'Ale Pana, waszego Boga, bójcie się, a on was wybawi z ręki wszystkich waszych wrogów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 40, 'Lecz oni nie usłuchali, ale postępowali według dawnych zwyczajów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 41, 'Te narody więc bały się Pana i służyły swoim rytym bożkom, zarówno ich dzieci, jak i dzieci ich dzieci. Jak czynili ich ojcowie, tak i oni czynią aż do dziś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 1, 'W trzecim roku Ozeasza, syna Eli, króla Izraela, Ezechiasz, syn Achaza, króla Judy, zaczął królować.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 2, 'Miał on dwadzieścia pięć lat, kiedy zaczął królować, i królował dwadzieścia dziewięć lat w Jerozolimie. Jego matka miała na imię Abi i była córką Zachariasza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 3, 'Czynił on to, co było słuszne w oczach Pana, wszystko tak, jak czynił Dawid, jego ojciec.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 4, 'Zniósł wyżyny, rozbił posągi, powycinał gaje i potłukł węża miedzianego, którego uczynił Mojżesz, bo aż do tego czasu synowie Izraela palili mu kadzidło, i nazwał go Nehustan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 5, 'Zaufał Panu, Bogu Izraela. I spośród wszystkich królów Judy nie było nikogo podobnego do niego ani z tych, którzy byli po nim, ani z tych, którzy byli przed nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 6, 'Przylgnął bowiem do Pana i nie odstępował od niego, ale przestrzegał jego przykazań, które Pan nadał Mojżeszowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 7, 'A Pan był z nim i powodziło mu się, gdziekolwiek wyruszał. Zbuntował się przeciw królowi Asyrii i nie służył mu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 8, 'To on pokonał Filistynów aż do Gazy i jej granic, od wieży strażników aż do miasta warownego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 9, 'W czwartym roku króla Ezechiasza – był to siódmy rok Ozeasza, syna Eli, króla Izraela – Salmanaser, król Asyrii, wyruszył przeciwko Samarii i obległ ją.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 10, 'I zdobył ją pod koniec trzeciego roku. W szóstym roku Ezechiasza – był to dziewiąty rok Ozeasza, króla Izraela – Samaria została zdobyta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 11, 'Wtedy król Asyrii uprowadził Izraela do Asyrii i osiedlił ich w Chalach i Chaborze, przy rzece Gozanu, i w miastach Medów;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 12, 'Ponieważ nie posłuchali głosu Pana, swego Boga, ale przekroczyli jego przymierze oraz to wszystko, co nakazał Mojżesz, sługa Pana. Nie słuchali tego i nie wypełniali.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 13, 'W czternastym roku króla Ezechiasza Sennacheryb, król Asyrii, wyruszył przeciw wszystkim warownym miastom Judy i zdobył je.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 14, 'Wtedy Ezechiasz, król Judy, posłał do króla Asyrii do Lakisz, mówiąc: Postąpiłem źle, odstąp ode mnie. Cokolwiek na mnie nałożysz, poniosę. Król Asyrii nałożył więc na Ezechiasza, króla Judy, trzysta talentów srebra i trzydzieści talentów złota.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 15, 'I Ezechiasz dał mu całe srebro, które się znalazło w domu Pana i w skarbcach domu królewskiego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 16, 'W tym samym czasie Ezechiasz zerwał złoto z drzwi domu Pana oraz ze słupów, które obił sam Ezechiasz, król Judy, i dał je królowi Asyrii.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 17, 'Jednakże król Asyrii posłał z Lakisz Tartana, Rabsarisa i Rabszaka z wielkim wojskiem do Jerozolimy, do króla Ezechiasza. Wyruszyli i przybyli do Jerozolimy. Gdy przybyli, przyszli i zatrzymali się przy kanale górnej sadzawki, która jest przy drodze pola folusznika.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 18, 'A gdy wołali do króla, wyszli do nich Eliakim, syn Chilkiasza, przełożony domu, Szebna, pisarz, oraz Joach, syn Asafa, kronikarz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 19, 'Wtedy Rabszak powiedział do nich: Powiedzcie Ezechiaszowi: Tak mówi wielki król, król Asyrii: Co to za ufność, na której polegasz?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 20, 'Mówisz – ale to słowa daremne – mam dość rady i siły do wojny. Teraz więc w kim pokładasz ufność, że zbuntowałeś się przeciwko mnie?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 21, 'Oto teraz opierasz się na tej nadłamanej lasce trzcinowej – na Egipcie – która gdy ktoś się oprze na niej, wbija mu się w dłoń i przebija ją. Taki jest faraon, król Egiptu, dla wszystkich, którzy mu ufają.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 22, 'A jeśli mi powiecie: Ufamy Panu, naszemu Bogu – czy on nie jest tym, którego wyżyny i ołtarze zniósł Ezechiasz i nakazał Judzie i Jerozolimie: Przed tym ołtarzem w Jerozolimie będziecie oddawać pokłon?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 23, 'Dlatego teraz proszę, daj zastaw memu panu, królowi Asyrii, a dam ci dwa tysiące koni, jeśli zdołasz posadzić na nich jeźdźców.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 24, 'Jakże więc stawisz opór jednemu dowódcy z najmniejszych sług mego pana, a pokładasz nadzieję w Egipcie, że otrzymasz rydwany i jeźdźców?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 25, 'Poza tym – czy bez woli Pana wyruszyłem przeciw temu miejscu, aby je zburzyć? Pan powiedział do mnie: Wyrusz przeciwko tej ziemi i spustosz ją.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 26, 'Wtedy Eliakim, syn Chilkiasza, Szebna i Joach powiedzieli do Rabszaka: Proszę, mów do swoich sług po syryjsku, bo rozumiemy, a nie mów z nami po hebrajsku wobec ludu, który jest na murze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 27, 'Lecz Rabszak odpowiedział: Czy do twego pana i do ciebie posłał mnie mój pan, abym mówił te słowa? Czyż nie do tych mężczyzn siedzących na murze, aby jedli swój kał i pili swój mocz razem z wami?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 28, 'Wstał więc Rabszak i zawołał donośnym głosem po hebrajsku tymi słowami: Słuchajcie słów wielkiego króla, króla Asyrii.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 29, 'Tak mówi król: Niech was nie zwodzi Ezechiasz, bo nie będzie mógł wyrwać was z mojej ręki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 30, 'I nie dajcie się przekonać Ezechiaszowi, by zaufać Panu, gdy mówi: Na pewno Pan nas wybawi i to miasto nie będzie wydane w ręce króla Asyrii.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 31, 'Nie słuchajcie Ezechiasza. Tak bowiem mówi król Asyrii: Zawrzyjcie ze mną przymierze i wyjdźcie do mnie, a każdy będzie jeść ze swojej winorośli i ze swego drzewa figowego i każdy będzie pić wodę ze swojej studni;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 32, 'Aż przyjdę i zabiorę was do ziemi podobnej do waszej, do ziemi zboża i wina, do ziemi chleba i winnic, do ziemi drzew oliwnych, oliwy i miodu. Będziecie żyć, a nie umierać. Nie słuchajcie Ezechiasza, bo was zwodzi, mówiąc: Pan nas wybawi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 33, 'Czy bogowie innych narodów mogli wybawić swoją ziemię z ręki króla Asyrii?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 34, 'Gdzie są bogowie Chamatu i Arpadu? Gdzie są bogowie Sefarwaim, Heny i Iwwy? Czy wyrwali Samarię z moich rąk?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 35, 'Którzy spośród wszystkich bogów tych ziem wybawili swoją ziemię z mojej ręki, żeby Pan miał wybawić Jerozolimę z mojej ręki?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 36, 'Lecz lud milczał i nie odpowiedział mu ani słowa, bo taki był rozkaz króla: Nie odpowiadajcie mu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 37, 'Wtedy przyszli przełożony domu Eliakim, syn Chilkiasza, pisarz Szebna i kronikarz Joach, syn Asafa, do Ezechiasza, z rozdartymi szatami, i oznajmili mu słowa Rabszaka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 1, 'A gdy król Ezechiasz to usłyszał, rozdarł swoje szaty, oblekł się w wór i wszedł do domu Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 2, 'I posłał Eliakima, przełożonego domu, pisarza Szebnę i starszych spośród kapłanów, obleczonych w wory, do proroka Izajasza, syna Amosa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 3, 'I powiedzieli mu: Tak mówi Ezechiasz: Ten dzień jest dniem utrapienia, upomnienia i bluźnierstwa. Nadszedł bowiem czas porodu dzieci, a nie ma siły, aby je urodzić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 4, 'Może Pan, twój Bóg, usłyszy wszystkie słowa Rabszaka, którego przysłał król Asyrii, jego pan, aby znieważać Boga żywego, i pomści słowa, które usłyszał Pan, twój Bóg. Zanieś więc modlitwę za resztkę, która pozostaje.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 5, 'Tak to słudzy króla Ezechiasza przyszli do Izajasza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 6, 'A Izajasz im odpowiedział: Tak powiedzcie waszemu panu: Tak mówi Pan: Nie bój się tych słów, które słyszałeś, którymi mi bluźnili słudzy króla Asyrii.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 7, 'Oto ześlę na niego ducha i usłyszy pewną wieść, wróci do swojej ziemi i sprawię, że padnie od miecza w swojej ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 8, 'Wrócił więc Rabszak i zastał króla Asyrii walczącego przeciwko Libnie. Usłyszał bowiem, że odstąpił od Lakisz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 9, 'Gdy usłyszał, że mówiono o Tirhace, królu Etiopii: Oto wyruszył na wojnę przeciwko tobie, ponownie wysłał posłańców do Ezechiasza, mówiąc:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 10, 'Tak powiedzcie Ezechiaszowi, królowi Judy: Niech cię nie zwodzi twój Bóg, któremu ufasz, mówiąc: Jerozolima nie będzie wydana w ręce króla Asyrii.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 11, 'Oto słyszałeś, co uczynili królowie Asyrii wszystkim ziemiom, niszcząc je. A ty miałbyś zostać wybawiony?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 12, 'Czy bogowie narodów wybawili tych, których wygubili moi ojcowie: Gozan, Charan, Resef, i synów Edenu, którzy byli w Telassar?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 13, 'Gdzie jest król Chamatu, król Arpadu i król miasta Sefarwaim, Heny i Iwwy?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 14, 'Gdy Ezechiasz wziął list z rąk posłów, przeczytał go, wszedł do domu Pana i rozwinął go przed Panem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 15, 'I Ezechiasz modlił się przed Panem, mówiąc: Panie, Boże Izraela, który zasiadasz pomiędzy cherubinami, ty jedynie jesteś Bogiem wszystkich królestw ziemi. Ty stworzyłeś niebo i ziemię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 16, 'Nakłoń ucha, Panie, i wysłuchaj. Otwórz swe oczy, Panie, i spójrz. Słuchaj słów Sennacheryba, które przesłał, aby znieważać Boga żywego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 17, 'To prawda, Panie, że królowie Asyrii spustoszyli narody i ich ziemie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 18, 'I powrzucali ich bogów do ognia. Nie byli bowiem bogami, ale dziełem rąk ludzkich, drewnem i kamieniem; dlatego ich zniszczyli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 19, 'Teraz więc, Panie, nasz Boże, wybaw nas, proszę, z jego ręki, aby wszystkie królestwa ziemi poznały, że jedynie ty, Panie, jesteś Bogiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 20, 'Wtedy Izajasz, syn Amosa, posłał do Ezechiasza, mówiąc: Tak mówi Pan, Bóg Izraela: Wysłuchałem tego, o co mnie prosiłeś w sprawie Sennacheryba, króla Asyrii.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 21, 'Oto słowo, które Pan o nim mówił: Dziewica, córka Syjonu, wzgardziła tobą i śmiała się z ciebie. Córka Jerozolimy kiwała głową za tobą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 22, 'Kogo znieważyłeś i komu bluźniłeś? Przeciwko komu podniosłeś swój głos i wysoko podniosłeś swoje oczy? Przeciw Świętemu Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 23, 'Przez swoich posłańców znieważyłeś Pana i powiedziałeś: Z mnóstwem moich rydwanów wyszedłem na wysokie góry i zbocza Libanu. Wytnę jego wysokie cedry i jego wyborne cyprysy i przyjdę aż do najdalszych jego przybytków, do jego lasu i urodzajnego pola.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 24, 'Ja wykopałem studnię i piłem obce wody, stopami swoich nóg wysuszyłem wszystkie potoki oblężonych miejsc.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 25, 'Czy nie słyszałeś, że ja dawno to uczyniłem i za dawnych dni to sprawiłem? A teraz wypełniam, gdy obracasz warowne miasta w stosy gruzów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 26, 'Ich mieszkańcy stali się słabi, przestraszyli się i zawstydzili. Byli jak trawa polna, jak świeża zieleń i trawa na dachach, jak zboże, które uschło, zanim dojrzało.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 27, 'Znam twoje miejsce pobytu, twoje wyjście i twoje wejście, a także twoją wściekłość przeciwko mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 28, 'Ponieważ twoja wściekłość przeciwko mnie i twoje zamieszanie doszły do moich uszu, włożę swoje kółko w twoje nozdrza i swoje wędzidło na twoje wargi i zawrócę cię tą drogą, którą przyszedłeś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 29, 'A to będzie znakiem dla ciebie: Tego roku będziesz jadł zboże samorodne, w drugim roku także zboże samorodne, w trzecim roku zaś siejcie i zbierajcie żniwo, sadźcie winnice i jedzcie ich owoce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 30, 'Resztka ocalonych z domu Judy ponownie zapuści korzenie w głąb i wyda owoc w górze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 31, 'Z Jerozolimy bowiem wyjdzie resztka i ci, którzy ocaleli – z góry Syjon. Sprawi to gorliwość Pana zastępów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 32, 'Tak więc mówi Pan o królu Asyrii: Nie wejdzie do tego miasta ani nie wypuści tam strzały, nie wyruszy przeciw niemu z tarczą i nie usypie szańców przeciwko niemu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 33, 'Drogą, którą przyszedł, powróci, a do tego miasta nie wejdzie, mówi Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 34, 'Będę bowiem bronił tego miasta i ocalę je ze względu na siebie i ze względu na Dawida, swego sługę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 35, 'Tej samej nocy Anioł Pana wyszedł i zabił w obozie Asyryjczyków sto osiemdziesiąt pięć tysięcy ludzi. A gdy wstali wcześnie rano, oto wszędzie było pełno trupów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 36, 'Sennacheryb, król Asyrii, wycofał się więc i wyruszył. Wrócił i zamieszkał w Niniwie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 37, 'A gdy oddawał pokłon w domu swego boga Nisroka, jego synowie – Adramelek i Sareser – zabili go mieczem. Potem uciekli do ziemi Ararat. I Asarchaddon, jego syn, królował w jego miejsce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 1, 'W tych dniach Ezechiasz śmiertelnie zachorował. Przyszedł do niego prorok Izajasz, syn Amosa, i powiedział mu: Tak mówi Pan: Rozporządź swym domem, bo umrzesz i nie będziesz żył.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 2, 'Wtedy Ezechiasz odwrócił swoją twarz do ściany i modlił się do Pana:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 3, 'O Panie, proszę cię, wspomnij teraz, że postępowałem wobec ciebie w prawdzie i z doskonałym sercem, czyniąc to, co dobre w twoich oczach. I płakał Ezechiasz rzewnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 4, 'Ale zanim Izajasz wyszedł do środkowego dziedzińca, doszło do niego słowo Pana:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 5, 'Wróć i powiedz Ezechiaszowi, wodzowi mego ludu: Tak mówi Pan, Bóg Dawida, twego ojca: Wysłuchałem twojej modlitwy i widziałem twoje łzy. Oto uzdrawiam cię: trzeciego dnia wejdziesz do domu Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 6, 'Dodam też do twoich dni piętnaście lat i wybawię ciebie i to miasto z ręki króla Asyrii. I będę bronić tego miasta ze względu na siebie i ze względu na Dawida, swego sługę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 7, 'Następnie Izajasz powiedział: Przynieście garstkę suchych fig. Gdy wzięli je i położyli na wrzód, wyzdrowiał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 8, 'Ezechiasz zapytał Izajasza: Jaki będzie znak tego, że Pan mnie uzdrowi i że na trzeci dzień pójdę do domu Pana?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 9, 'Izajasz odpowiedział: To będzie znakiem od Pana, że uczyni Pan tę rzecz, którą obiecał: Czy cień ma się posunąć o dziesięć stopni, czy ma się cofnąć o dziesięć stopni?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 10, 'Ezechiasz odpowiedział: Łatwo cieniowi posunąć się o dziesięć stopni. Nie – niech cień cofnie się o dziesięć stopni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 11, 'Wtedy prorok Izajasz zawołał do Pana. I on cofnął cień o dziesięć stopni, po których przesunął się na zegarze słonecznym Achaza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 12, 'W tym czasie Berodach-Baladan, syn Baladana, król Babilonu, posłał listy i dar do Ezechiasza. Usłyszał bowiem, że Ezechiasz chorował.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 13, 'I Ezechiasz wysłuchał posłańców, i pokazał im cały skarbiec swoich kosztowności, srebro, złoto, wonności, drogocenne olejki oraz swoją zbrojownię, a także wszystko, co się znajdowało w jego składach. Nie było nic, czego Ezechiasz by im nie pokazał w swoim domu i w całym swoim państwie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 14, 'Wtedy prorok Izajasz przyszedł do króla Ezechiasza i zapytał go: Co powiedzieli ci mężczyźni i skąd przybyli do ciebie? Ezechiasz odpowiedział: Przybyli z dalekiej ziemi, z Babilonu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 15, 'Znowu zapytał: Co widzieli w twoim domu? Ezechiasz odpowiedział: Widzieli wszystko, co jest w moim domu. Nie było nic, czego bym im nie pokazał w swoich skarbcach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 16, 'Wtedy Izajasz powiedział do Ezechiasza: Słuchaj słowa Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 17, 'Oto przyjdą dni, kiedy wszystko, co jest w twoim domu i co zgromadzili twoi ojcowie aż do tego dnia, zostanie zabrane do Babilonu. Nic nie pozostanie, mówi Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 18, 'Z twoich synów, którzy będą pochodzić od ciebie i których spłodzisz, zabiorą niektórych i będą eunuchami w pałacu króla Babilonu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 19, 'Wtedy Ezechiasz powiedział do Izajasza: Dobre jest słowo Pana, które wypowiedziałeś. I dodał: Czyż ono nie jest dobre, jeśli za moich dni będzie pokój i prawda?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 20, 'A pozostałe dzieje Ezechiasza, cała jego potęga i to, jak zbudował sadzawkę i kanał, którymi sprowadził wodę do miasta, czy nie są zapisane w księdze kronik królów Judy?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 21, 'I Ezechiasz zasnął ze swoimi ojcami, a jego syn Manasses królował w jego miejsce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 1, 'Manasses miał dwanaście lat, kiedy zaczął królować, i królował pięćdziesiąt pięć lat w Jerozolimie. Jego matka miała na imię Chefsiba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 2, 'Czynił on to, co złe w oczach Pana, według obrzydliwości tych narodów, które Pan wypędził przed synami Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 3, 'Odbudował bowiem wyżyny, które zburzył jego ojciec Ezechiasz, wznosił ołtarze dla Baala, posadził gaj, tak jak uczynił Achab, król Izraela, i oddawał pokłon całemu zastępowi nieba, i służył mu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 4, 'Zbudował też ołtarze w domu Pana, o którym Pan powiedział: W Jerozolimie umieszczę swoje imię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 5, 'Zbudował też ołtarze całemu zastępowi nieba w obydwu dziedzińcach domu Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 6, 'Przeprowadził swojego syna przez ogień, uprawiał wróżbiarstwo i czary, ustanowił czarowników i czarnoksiężników. Bardzo wiele złego czynił w oczach Pana, pobudzając go do gniewu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 7, 'Postawił też rzeźbę gaju, którą wykonał, w domu, o którym Pan powiedział do Dawida i do jego syna Salomona: W tym domu i w Jerozolimie, które wybrałem spośród wszystkich pokoleń Izraela, umieszczę swoje imię na wieki;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 8, 'A już więcej nie dopuszczę, by noga Izraela opuściła ziemię, którą dałem ich ojcom, oby tylko pilnie przestrzegali wszystkiego, co im nakazałem, i całego prawa, które im nadał mój sługa Mojżesz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 9, 'Lecz oni nie słuchali. A Manasses zwiódł ich, aby czynili gorzej niż narody, które Pan wytracił przed synami Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 10, 'Wtedy Pan przemówił przez swoje sługi, proroków, mówiąc:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 11, 'Ponieważ Manasses, król Judy, dopuścił się tych obrzydliwości, czyniąc gorsze rzeczy niż wszystko, co czynili Amoryci, którzy byli przed nim, a przywiódł Judę do grzechu przez swoje bożki;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 12, 'Dlatego tak mówi Pan, Bóg Izraela: Oto sprowadzę nieszczęście na Jerozolimę i na Judę, tak że każdemu, kto o tym usłyszy, zadzwoni w obu uszach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 13, 'Rozciągnę bowiem nad Jerozolimą sznur Samarii i pion domu Achaba. I wytrę Jerozolimę, tak jak wyciera się miskę, a po wytarciu odwraca się dnem do góry.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 14, 'I porzucę resztę swojego dziedzictwa, i wydam je w ręce jego wrogów; staną się łupem i pastwą wszystkich swoich wrogów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 15, 'Ponieważ dopuszczali się tego, co złe w moich oczach, i drażnili mnie od dnia, kiedy ich ojcowie wyszli z Egiptu, aż do dziś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 16, 'Ponadto nawet krwi niewinnej Manasses przelał bardzo dużo, tak że napełnił nią Jerozolimę od krańca do krańca, nie licząc swojego grzechu, przez który przywiódł do grzechu Judę, czyniąc to, co złe w oczach Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 17, 'A pozostałe dzieje Manassesa i wszystko, co czynił, i jego grzech, którego się dopuścił, czy nie są zapisane w księdze kronik królów Judy?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 18, 'I Manasses zasnął ze swymi ojcami, i został pogrzebany w ogrodzie swego domu, w ogrodzie Uzzy. I Amon, jego syn, królował w jego miejsce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 19, 'Amon miał dwadzieścia dwa lata, kiedy zaczął królować, i królował dwa lata w Jerozolimie. Jego matka miała na imię Meszullemet i była córką Charusa z Jotba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 20, 'Czynił on to, co złe w oczach Pana, tak jak czynił jego ojciec Manasses.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 21, 'Szedł wszystkimi drogami, którymi szedł jego ojciec, i służył bożkom, którym służył jego ojciec, i oddawał im pokłon;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 22, 'Opuścił Pana, Boga swoich ojców, a nie szedł drogą Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 23, 'I słudzy Amona uknuli spisek przeciw niemu, i zabili króla w jego domu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 24, 'Wtedy lud tej ziemi zabił wszystkich, którzy uknuli spisek przeciw królowi Amonowi. I lud tej ziemi ustanowił w jego miejsce królem Jozjasza, jego syna.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 25, 'A pozostałe dzieje Amona, które czynił, czy nie są zapisane w księdze kronik królów Judy?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 26, 'I pogrzebano go w jego grobie, w ogrodzie Uzzy. A jego syn Jozjasz królował w jego miejsce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 1, 'Jozjasz miał osiem lat, kiedy zaczął królować, i królował trzydzieści jeden lat w Jerozolimie. Jego matka miała na imię Jedida i była córką Adajasza z Boskat.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 2, 'Czynił on to, co było słuszne w oczach Pana, i szedł wszystkimi drogami Dawida, swego ojca, a nie zbaczał ani na prawo, ani na lewo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 3, 'A w osiemnastym roku króla Jozjasza król posłał pisarza, Szafana, syna Azaliasza, syna Meszullama, do domu Pana, mówiąc:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 4, 'Idź do najwyższego kapłana Chilkiasza. Niech zbiera pieniądze, które przyniesiono do domu Pana, a które stróże progu zebrali od ludu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 5, 'I niech je dadzą do rąk kierownikom robót, przełożonym nad domem Pana. A ci niech przekażą je robotnikom pracującym w domu Pana, aby naprawiali szkody domu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 6, 'To jest cieślom, budowniczym i murarzom, oraz na zakup drewna i ciosanego kamienia na naprawę domu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 7, 'Jednak nie trzeba było rozliczać się z nimi z pieniędzy, które dali im do rąk, bo oni postępowali uczciwie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 8, 'Wtedy najwyższy kapłan Chilkiasz powiedział do pisarza, Szafana: Znalazłem księgę Prawa w domu Pana. I Chilkiasz dał księgę Szafanowi, a ten ją czytał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 9, 'Następnie pisarz Szafan przyszedł do króla i zdał sprawę królowi, mówiąc: Twoi słudzy zebrali pieniądze, które znajdowały się w domu Pana, i dali je w ręce kierownikom robót, przełożonym nad domem Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 10, 'Pisarz Szafan oznajmił także królowi: Kapłan Chilkiasz dał mi księgę. I Szafan czytał ją wobec króla.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 11, 'A gdy król usłyszał słowa księgi Prawa, rozdarł swoje szaty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 12, 'Potem król rozkazał kapłanowi Chilkiaszowi, Achikamowi, synowi Szafana, Akborowi, synowi Micheasza, pisarzowi Szafanowi i swojemu słudze Asajaszowi:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 13, 'Idźcie, radźcie się Pana co do mnie, co do ludu i co do całej Judy w związku ze słowami tej księgi, którą znaleziono. Wielki bowiem jest gniew Pana, którym zapłonął przeciwko nam, dlatego że nasi ojcowie nie posłuchali słów tej księgi, aby czynić zgodnie ze wszystkim, co jest dla nas napisane.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 14, 'Tak więc kapłan Chilkiasz, Achikam, Akbor, Szafan i Asajasz poszli do prorokini Chuldy, żony Szalluma, syna Tikwy, syna Charchasza, strażnika szat – mieszkała ona w Jerozolimie, po drugiej stronie miasta – i opowiedzieli jej o tej sprawie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 15, 'Ona zaś powiedziała im: Tak mówi Pan, Bóg Izraela: Powiedzcie mężczyźnie, który was posłał do mnie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 16, 'Tak mówi Pan: Oto sprowadzę nieszczęście na to miejsce i na jego mieszkańców, zgodnie ze wszystkimi słowami tej księgi, które czytał król Judy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 17, 'Za to, że mnie opuścili i palili kadzidło innym bogom, aby pobudzić mnie do gniewu wszystkimi dziełami swoich rąk. Dlatego zapłonie mój gniew przeciwko temu miejscu i nie zagaśnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 18, 'A królowi Judy, który posłał was, aby radzić się Pana, tak powiedzcie: Tak mówi Pan, Bóg Izraela, co do słów, które słyszałeś;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 19, 'Ponieważ twoje serce zmiękło i upokorzyłeś się przed Panem, gdy usłyszałeś, co powiedziałem przeciw temu miejscu i przeciw jego mieszkańcom – że staną się spustoszeniem i klątwą – rozdarłeś swoje szaty i płakałeś przede mną, to i ja również ciebie wysłuchałem, mówi Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 20, 'Dlatego oto przyłączę cię do twoich ojców i będziesz złożony w swoim grobie w pokoju, aby twoje oczy nie oglądały całego nieszczęścia, które sprowadzę na to miejsce. A oni zanieśli tę odpowiedź królowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 1, 'Wtedy król posłał, aby zebrali się wokół niego wszyscy starsi Judy i Jerozolimy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 2, 'Następnie król udał się do domu Pana, a wraz z nim wszyscy mężczyźni Judy, wszyscy mieszkańcy Jerozolimy, kapłani, prorocy oraz cały lud – od najmniejszych do największych. I czytał do ich uszu wszystkie słowa księgi przymierza, którą znaleziono w domu Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 3, 'Potem król stanął przy kolumnie i zawarł przymierze przed Panem, że będą szli za Panem i będą przestrzegać jego przykazań, świadectw i nakazów z całego serca i całą duszą i wypełniać słowa przymierza, które zostały napisane w tej księdze. I cały lud przystąpił do przymierza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 4, 'Wtedy król nakazał najwyższemu kapłanowi Chilkiaszowi, kapłanom drugiego rzędu i stróżom progu wynieść ze świątyni Pana wszystkie przedmioty wykonane dla Baala, do gaju i dla całego zastępu niebieskiego. I spalił je poza Jerozolimą na polu Cedronu, i zaniósł ich popiół do Betel.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 5, 'Zwolnił też z urzędu bałwochwalczych kapłanów, których ustanowili królowie Judy, aby palili kadzidło na wyżynach w miastach Judy i w okolicach Jerozolimy, oraz tych, którzy palili kadzidło Baalowi, słońcu, księżycowi, planetom i całemu zastępowi niebieskiemu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 6, 'Wyniósł gaj z domu Pana poza Jerozolimę, do potoku Cedron, i spalił go przy potoku Cedron, starł go na proch i rozrzucił na grobach synów ludu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 7, 'Zburzył też domy Sodomitów, które znajdowały się przy domu Pana, gdzie kobiety tkały zasłony do gaju.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 8, 'I zwołał wszystkich kapłanów z miast Judy, i splugawił wyżyny, na których kapłani palili kadzidło, od Geba aż do Beer-Szeby, i zburzył wyżyny przy bramach znajdujących się u wejścia bramy Jozuego, namiestnika miasta, po lewej stronie, gdy się wchodzi przez bramę miejską.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 9, 'Jednakże kapłani wyżyn nie przystąpili do ołtarza Pana w Jerozolimie, ale mogli jeść przaśne chleby wśród swoich braci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 10, 'Splugawił również Tofet, które było w dolinie syna Hinnom, aby nikt więcej nie przeprowadził swego syna ani córki przez ogień ku czci Molocha.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 11, 'Usunął też konie, które królowie Judy poświęcili słońcu u wejścia do domu Pana, obok komnaty dworzanina Natanmeleka, która była na przedmieściu, a rydwany słońca spalił ogniem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 12, 'Król zburzył także ołtarze, które znajdowały się na dachu górnej komnaty Achaza, zbudowane przez królów Judy, oraz ołtarze, które uczynił Manasses w obu dziedzińcach domu Pana. Usunął je stamtąd i wrzucił ich proch do potoku Cedron.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 13, 'Król splugawił wyżyny, które stały przed Jerozolimą po prawej stronie Góry Zatracenia i które zbudował Salomon, król Izraela, dla Asztarty, obrzydliwości Sydończyków, dla Kemosza, obrzydliwości Moabitów, i dla Milkoma, obrzydliwości synów Ammona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 14, 'I pokruszył posągi, powycinał gaje, a ich miejsca napełnił kośćmi ludzkimi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 15, 'Ponadto ołtarz, który był w Betel, i wyżynę uczynioną przez Jeroboama, syna Nebata, który przywiódł Izraela do grzechu – także ten ołtarz i wyżynę zburzył. Spalił wyżynę, starł na proch i spalił gaj.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 16, 'A gdy Jozjasz odwrócił się, zobaczył groby, które były tam na górze. Posłał i zabrał kości z tych grobów, i spalił je na ołtarzu, plugawiąc go zgodnie ze słowem Pana wygłoszonym przez męża Bożego, który wypowiedział te rzeczy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 17, 'I zapytał: Co to za napis, który widzę? Ludzie z tego miasta odpowiedzieli: To grób męża Bożego, który przyszedł z Judy i zapowiedział rzeczy, które wykonałeś nad ołtarzem w Betel.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 18, 'Wtedy powiedział: Zostawcie go, niech nikt nie rusza jego kości. Pozostawiono więc jego kości wraz z kośćmi proroka, który przybył z Samarii.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 19, 'Jozjasz usunął też wszystkie świątynie na wyżynach, które były w miastach Samarii zbudowanych przez królów Izraela, aby drażnić Pana. Postąpił z nimi tak samo, jak uczynił w Betel.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 20, 'Pozabijał także wszystkich kapłanów wyżyn, którzy tam byli przy ołtarzach, i spalił na nich ludzkie kości. Potem wrócił do Jerozolimy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 21, 'I król nakazał całemu ludowi: Obchodźcie święto Paschy dla Pana, waszego Boga, tak jak jest napisane w księdze tego przymierza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 22, 'Takiej Paschy nie obchodzono od czasów sędziów, którzy sądzili Izraela, i przez wszystkie dni królów Izraela i królów Judy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 23, 'Dopiero w osiemnastym roku króla Jozjasza obchodzono taką Paschę dla Pana w Jerozolimie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 24, 'Jozjasz usunął również czarowników, wróżbiarzy, posągi, bożki i wszystkie obrzydliwości, które widziano w ziemi Judy i w Jerozolimie, aby wypełnić słowa prawa napisane w księdze, którą znalazł kapłan Chilkiasz w domu Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 25, 'I nie było przed nim króla podobnego do niego, który by wrócił do Pana z całego swego serca, całą swoją duszą i z całej swojej siły, według całego Prawa Mojżesza, i po nim nie powstał nikt jemu podobny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 26, 'Pan jednak nie odwrócił się od zapalczywości swego wielkiego gniewu, którym zapłonął przeciwko Judzie z powodu wszelkich zniewag, którymi rozdrażnił go Manasses.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 27, 'Pan więc powiedział: Również Judę odrzucę sprzed swojego oblicza, jak odrzuciłem Izraela, i wzgardzę tym miastem, które wybrałem, Jerozolimą, i domem tym, o którym powiedziałem: Tam będzie moje imię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 28, 'A pozostałe dzieje Jozjasza i wszystko, co czynił, czy nie są zapisane w księdze kronik królów Judy?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 29, 'Za jego dni faraon Necho, król Egiptu, wyruszył przeciwko królowi Asyrii nad rzekę Eufrat. Król Jozjasz wyruszył przeciwko niemu, a gdy ten go zobaczył, zabił go w Megiddo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 30, 'I jego słudzy przewieźli go zmarłego z Megiddo, sprowadzili go do Jerozolimy i pogrzebali w jego grobie. Potem lud tej ziemi wziął Jehoachaza, syna Jozjasza, namaścił go i ustanowił go królem w miejsce jego ojca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 31, 'Jehoachaz miał dwadzieścia trzy lata, kiedy zaczął królować, i królował trzy miesiące w Jerozolimie. Jego matka miała na imię Chamutal i była córką Jeremiasza z Libny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 32, 'Czynił on to, co złe w oczach Pana, zupełnie tak, jak czynili jego ojcowie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 33, 'Faraon Necho uwięził go w Ribla w ziemi Chamat, aby nie królował w Jerozolimie, i nałożył na ziemię daninę w wysokości stu talentów srebra i jednego talentu złota.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 34, 'Faraon Necho ustanowił królem Eliakima, syna Jozjasza, w miejsce jego ojca Jozjasza, i zmienił jego imię na Joakim, a Jehoachaza zabrał. Ten przyszedł do Egiptu i tam umarł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 35, 'A Joakim dał faraonowi srebro i złoto, ale opodatkował ziemię, aby mógł oddać pieniądze według rozkazu faraona. Pobierał srebro i złoto od ludu ziemi, od każdego według oszacowania, aby je oddać faraonowi Necho.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 36, 'Joakim miał dwadzieścia pięć lat, kiedy zaczął królować, i królował jedenaście lat w Jerozolimie. Jego matka miała na imię Zebidda i była córką Pedajasza z Rumy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 37, 'Czynił on to, co złe w oczach Pana, zupełnie tak, jak czynili jego ojcowie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 1, 'Za jego dni wyruszył Nabuchodonozor, król Babilonu, i Joakim stał się jego sługą przez trzy lata. Potem zbuntował się przeciwko niemu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 2, 'A Pan posłał przeciwko niemu oddziały Chaldejczyków, oddziały Syryjczyków, oddziały Moabitów i oddziały synów Ammona. Posłał ich na Judę, aby go zniszczyć zgodnie ze słowem Pana, które wypowiedział przez swoje sługi, proroków.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 3, 'Owszem, zgodnie z poleceniem Pana spotkało to Judę, aby odrzucić go sprzed jego oblicza za grzechy Manassesa, za to wszystko, co uczynił;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 4, 'A także za krew niewinną, którą przelał, bo napełnił Jerozolimę krwią niewinną, czego Pan nie chciał przebaczyć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 5, 'A pozostałe dzieje Joakima i wszystko, co czynił, czy nie są zapisane w księdze kronik królów Judy?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 6, 'I Joakim zasnął ze swymi ojcami, a jego syn Joachin królował w jego miejsce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 7, 'A król Egiptu już więcej nie wyruszał ze swojej ziemi, gdyż król Babilonu wziął wszystko, co należało do króla Egiptu, od rzeki Egiptu aż do rzeki Eufrat.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 8, 'Joachin miał osiemnaście lat, kiedy zaczął królować, i królował trzy miesiące w Jerozolimie. Jego matka miała na imię Nechuszta i była córką Elnatana z Jerozolimy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 9, 'Czynił on to, co złe w oczach Pana, zupełnie tak, jak czynił jego ojciec.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 10, 'W tym czasie słudzy Nabuchodonozora, króla Babilonu, wyruszyli przeciw Jerozolimie i przyszło do oblężenia miasta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 11, 'Potem sam Nabuchodonozor, król Babilonu, nadciągnął przeciw miastu, a jego słudzy je oblegali.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 12, 'Wtedy Joachin, król Judy, wyszedł do króla Babilonu, on i jego matka, jego słudzy, jego książęta i jego dworzanie. I król Babilonu pojmał go w ósmym roku swego panowania.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 13, 'I wyniósł stamtąd wszystkie skarby domu Pana i skarby domu królewskiego i pokruszył wszystkie przedmioty złote, które wykonał Salomon, król Izraela, dla świątyni Pana, tak jak zapowiedział Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 14, 'I przesiedlił całą Jerozolimę: wszystkich książąt, wszystkich dzielnych wojowników – dziesięć tysięcy jeńców, oraz wszystkich rzemieślników i kowali. Nie pozostał nikt oprócz ubogiego ludu tej ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 15, 'Przeniósł też do Babilonu Joachina. A także matkę króla, żony króla, jego dworzan i dostojników tej ziemi zabrał do niewoli z Jerozolimy do Babilonu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 16, 'Także wszystkich dzielnych mężów w liczbie siedmiu tysięcy, tysiąc rzemieślników i kowali oraz wszystkich zdolnych do walki – tych zabrał król Babilonu do niewoli do Babilonu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 17, 'W jego miejsce król Babilonu ustanowił królem jego stryja Mattaniasza i zmienił mu imię na Sedekiasz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 18, 'Sedekiasz miał dwadzieścia jeden lat, kiedy zaczął królować, i królował jedenaście lat w Jerozolimie. Jego matka miała na imię Chamutal i była córką Jeremiasza z Libny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 19, 'Czynił on to, co złe w oczach Pana, zupełnie tak, jak czynił Joakim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 20, 'Z powodu gniewu Pana przyszło to na Jerozolimę i Judę, aż odrzucił ich sprzed swego oblicza. A Sedekiasz zbuntował się przeciw królowi Babilonu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 1, 'W dziewiątym roku jego panowania, dziesiątego miesiąca, dziesiątego dnia tego miesiąca, Nabuchodonozor, król Babilonu, wraz z całym swoim wojskiem wyruszył przeciw Jerozolimie, rozbił obóz pod nią i zbudował przeciwko niej szańce dokoła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 2, 'I miasto było oblężone aż do jedenastego roku króla Sedekiasza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 3, 'A w dziewiątym dniu czwartego miesiąca wzmógł się głód w mieście i nie było chleba dla ludu tej ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 4, 'Kiedy zrobiono wyłom w murze miasta, wszyscy wojownicy uciekli w nocy przez bramę między dwoma murami obok królewskiego ogrodu. Chaldejczycy zaś znajdowali się dokoła miasta, a król uszedł w stronę pustyni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 5, 'I wojsko Chaldejczyków ścigało króla, i dogoniło go na równinach Jerycha, a całe jego wojsko rozpierzchło się od niego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 6, 'Pojmali więc króla i przyprowadzili go do króla Babilonu, do Ribla, gdzie ten wydał na niego wyrok.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 7, 'I synów Sedekiasza zabili na jego oczach, a Sedekiaszowi wyłupili oczy, zakuli go spiżowymi łańcuchami i uprowadzili do Babilonu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 8, 'W piątym miesiącu, siódmego dnia tego miesiąca – był to dziewiętnasty rok Nabuchodonozora, króla Babilonu – do Jerozolimy przybył Nebuzaradan, dowódca gwardii, sługa króla Babilonu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 9, 'I spalił dom Pana i dom króla; wszystkie domy Jerozolimy i wszystkie wielkie budowle spalił ogniem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 10, 'Całe wojsko Chaldejczyków, które było z dowódcą gwardii, zburzyło mury wokół Jerozolimy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 11, 'Resztę ludu, która pozostała w mieście, zbiegów, którzy przeszli do króla Babilonu, oraz resztę pospólstwa Nebuzaradan, dowódca gwardii, uprowadził do niewoli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 12, 'Lecz dowódca gwardii pozostawił niektórych spośród ubogich tej ziemi, aby byli winogrodnikami i rolnikami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 13, 'Chaldejczycy rozbili kolumny z brązu, które były w domu Pana, podstawy i morze z brązu, które było w domu Pana, a brąz z nich przenieśli do Babilonu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 14, 'Zabrali też kotły, szufle, nożyce, miski oraz wszystkie naczynia z brązu, których używano do służby.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 15, 'Dowódca gwardii zabrał kadzielnice, miednice i to, co było ze złota, jako złoto, i to, co było ze srebra, jako srebro;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 16, 'Dwie kolumny, jedno morze, podstawy, które wykonał Salomon dla domu Pana, a nie było można zmierzyć wagi brązu tych wszystkich przedmiotów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 17, 'Osiemnaście łokci wysokości miała jedna kolumna, a głowica na niej była z brązu. Wysokość głowicy wynosiła trzy łokcie, a siatka i jabłka granatu naokoło głowicy – wszystko było z brązu. Tak samo było na siatce drugiej kolumny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 18, 'Dowódca gwardii zabrał też najwyższego kapłana Serajasza, drugiego kapłana Sofoniasza i trzech stróżów progu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 19, 'Z miasta zaś zabrał dworzanina, który był przełożonym nad wojownikami, pięciu spośród tych, którzy stawali przed królem, a znaleziono ich w mieście, naczelnego pisarza wojskowego dokonującego poboru ludu tej ziemi oraz sześćdziesięciu mężczyzn spośród ludu tej ziemi, których znaleziono w mieście.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 20, 'Tych pojmał Nebuzaradan, dowódca gwardii, i zaprowadził do króla Babilonu do Ribla.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 21, 'I król Babilonu pobił ich, i uśmiercił w Ribla, w ziemi Chamat. Tak został uprowadzony Juda ze swojej ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 22, 'Nad ludem zaś, który jeszcze pozostał w ziemi Judy, a który Nabuchodonozor, król Babilonu, zostawił, ustanowił on Gedaliasza, syna Achikama, syna Szafana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 23, 'A gdy wszyscy dowódcy wojska usłyszeli, oni i ich ludzie, że król Babilonu ustanowił Gedaliasza namiestnikiem, przyszli do Gedaliasza do Mispy. Byli to: Izmael, syn Netaniasza, Jochanan, syn Kareacha, Serajasz, syn Tanchumeta Netofatyta, i Jaazaniasz, syn Maakatczyka, oni i ich ludzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 24, 'Wtedy Gedaliasz przysiągł im i ich ludziom: Nie bójcie się służyć Chaldejczykom. Mieszkajcie w ziemi i służcie królowi Babilonu, a będzie wam dobrze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 25, 'Lecz w siódmym miesiącu przybył Izmael, syn Netaniasza, syna Eliszamy, z rodu królewskiego, a z nim dziesięciu ludzi, i pobili Gedaliasza, i umarł, a także Żydów i Chaldejczyków, którzy byli z nim w Mispie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 26, 'Wówczas cały lud, od najmniejszego do największego, oraz dowódcy wojsk powstali i poszli do Egiptu, bo się bali Chaldejczyków.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 27, 'A w trzydziestym siódmym roku uprowadzenia Joachina, króla Judy, dwunastego miesiąca dwudziestego siódmego dnia tego miesiąca, Ewil-Merodak, król Babilonu, w pierwszym roku jego panowania, ułaskawił Joachina, króla Judy, i wypuścił go z więzienia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 28, 'Rozmawiał z nim łaskawie i wystawił jego tron ponad tron innych królów, którzy byli z nim w Babilonie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 29, 'Zdjął też jego szaty więzienne i jadł chleb zawsze w jego obecności przez wszystkie dni swego życia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 30, 'Codziennie otrzymywał od króla stałe utrzymanie, przez wszystkie dni swego życia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 1, 'Adam, Set, Enosz;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 2, 'Kenan, Mahalaleel, Jered;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 3, 'Henoch, Matuzalem, Lamech;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 4, 'Noe, Sem, Cham i Jafet.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 5, 'Synowie Jafeta: Gomer, Magog, Madaj, Jawan, Tubal, Meszek i Tiras.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 6, 'A synowie Gomera: Aszkenaz, Rifat i Togarma.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 7, 'A synowie Jawana: Elisa i Tarszisz, Cytym i Dodanim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 8, 'Synowie Chama: Kusz, Misraim, Put i Kanaan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 9, 'A synowie Kusza: Seba, Chaawila, Sabta, Rama i Sabteka. A synowie Ramy: Szeba i Dedan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 10, 'Kusz spłodził Nimroda, który zaczął być mocarzem na ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 11, 'Misraim spłodził Ludima, Ananima, Lahabima i Naftuchima;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 12, 'Oraz Patrusyma, Kasluchima, od których wywodzą się Filistyni, i Kaftoryma.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 13, 'Kanaan zaś spłodził Sidona, swego pierworodnego, i Cheta;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 14, 'Jebusytę, Amorytę i Girgaszytę;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 15, 'Chiwwitę, Arkitę i Sinitę;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 16, 'Arwadytę, Semarytę i Chamatytę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 17, 'Synowie Sema: Elam, Assur, Arpachszad, Lud, Aram, Us, Chul, Geter i Meszek.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 18, 'Arpachszad spłodził Szelacha, a Szelach spłodził Ebera.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 19, 'Eberowi zaś urodzili się dwaj synowie: jeden miał na imię Peleg, gdyż za jego czasów ziemia została rozdzielona, a imię brata jego – Joktan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 20, 'Joktan spłodził Almodada, Szelefa, Chasarmaweta i Jeracha;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 21, 'Hadorama, Uzala i Diklę;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 22, 'Ebala, Abimaela i Szeba;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 23, 'Ofira, Chawila i Jobaba. Wszyscy ci byli synami Joktana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 24, 'Sem, Arpachszad, Szelach;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 25, 'Eber, Peleg, Reu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 26, 'Serug, Nachor, Terach;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 27, 'Abram, to jest Abraham.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 28, 'Synowie Abrahama: Izaak i Izmael.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 29, 'A oto są ich rody: pierworodny Izmaela – Nebajot, następnie Kedar, Abdeel i Mibsam;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 30, 'Miszma, Duma, Massa, Hadad i Tema;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 31, 'Jetur, Nafisz i Kedma. Byli oni synami Izmaela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 32, 'A oto synowie Ketury, nałożnicy Abrahama: urodziła ona Zimrana, Jokszana, Medana, Midiana, Jiszbaka i Szuacha. A synowie Jokszana: Szeba i Dedan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 33, 'Synowie Midiana: Efa, Efer, Henoch, Abida i Eldaa. Oni wszyscy byli synami Ketury.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 34, 'I Abraham spłodził Izaaka. Synowie Izaaka: Ezaw i Izrael.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 35, 'A synowie Ezawa: Elifaz, Rehuel, Jeusz, Jalam i Korach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 36, 'Synowie Elifaza: Teman, Omar, Sefo, Gatam, Kenaz, Timna i Amalek.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 37, 'Synowie Rehuela: Nachat, Zerach, Szamma i Mizza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 38, 'A synowie Seira: Lotan, Szobal, Sibeon, Ana, Diszon, Eser i Diszan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 39, 'A synowie Lotana: Chori, Homam; a siostrą Lotana była Timna.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 40, 'Synowie Szobala: Alian, Manachat, Ebal, Szefo i Onam. A synowie Sibeona: Ajja i Ana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 41, 'Synowie Any: Diszon. Synowie Diszona: Chamran i Eszban, Jitran i Keran.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 42, 'Synowie Esera: Bilhan, Zaawan i Jaakan. Synowie Diszana: Us i Aran.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 43, 'To byli królowie, którzy panowali w ziemi Edomu, zanim zapanował król nad synami Izraela: Bela, syn Beora, a jego miasto nazywało się Dinhaba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 44, 'A gdy Bela umarł, królował w jego miejsce Jobab, syn Zeracha z Bosry.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 45, 'A gdy Jobab umarł, królował w jego miejsce Chuszam z ziemi Temanitów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 46, 'A gdy Chuszam umarł, królował w jego miejsce Hadad, syn Bedada, który pobił Midianitów na polu Moabu. A jego miasto nazywało się Awit.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 47, 'A gdy Hadad umarł, królował w jego miejsce Samla z Masreki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 48, 'A gdy Samla umarł, królował w jego miejsce Szaul z Rechobot nad Rzeką.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 49, 'A gdy Szaul umarł, królował w jego miejsce Baalchanan, syn Akbora.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 50, 'A gdy Baalchanan umarł, królował w jego miejsce Hadad. Jego miasto nazywało się Pai, a jego żona miała na imię Mehetabel, była to córka Matredy, córki Mezahaba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 51, 'I Hadad umarł. A książętami Edomu byli: książę Timna, książę Alia, książę Jetet;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 52, 'Książę Oholibama, książę Ela, książę Pinon;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 53, 'Książę Kenaz, książę Teman, książę Mibsar;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 54, 'Książę Magdiel, książę Iram. Oni byli książętami Edomu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 1, 'Oto są synowie Izraela: Ruben, Symeon, Lewi i Juda, Issachar i Zebulon;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 2, 'Dan, Józef, Beniamin, Neftali, Gad i Aszer.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 3, 'Synowie Judy: Er, Onan i Szela. Ci trzej urodzili mu się z córki Szui, Kananejki. Ale Er, pierworodny Judy, był zły w oczach Pana, dlatego go zabił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 4, 'Tamar zaś, jego synowa, urodziła mu Peresa i Zeracha. Wszystkich synów Judy było pięciu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 5, 'Synowie Peresa: Chesron i Chamul.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 6, 'Synowie Zeracha: Zimri, Etan, Heman, Kalkol i Dara, wszystkich ich było pięciu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 7, 'Synowie Karmiego: Achar, który sprowadził nieszczęście na Izraela, gdy zgrzeszył przy rzeczach przeklętych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 8, 'Synowie Etana: Azariasz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 9, 'Synowie Chesrona, którzy mu się urodzili: Jerachmeel, Ram i Kelubaj.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 10, 'Ram zaś spłodził Amminadaba, a Amminadab spłodził Nachszona, księcia synów Judy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 11, 'A Nachszon spłodził Salmę, a Salma spłodził Boaza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 12, 'A Boaz spłodził Obeda, a Obed spłodził Jessego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 13, 'A Jesse spłodził swego pierworodnego Eliaba, jako drugiego – Abinadaba, trzeciego – Szimeę;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 14, 'Czwartego – Netaneela, piątego – Raddaja;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 15, 'Szóstego – Osema, siódmego – Dawida.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 16, 'A ich siostry to Seruja i Abigail. Synowie Serui: Abiszaj, Joab i Asahel – ci trzej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 17, 'Abigail zaś urodziła Amasę, ojcem Amasy był Jeter, Izmaelita.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 18, 'Kaleb, syn Chesrona, spłodził dzieci z Azubą, swoją żoną, i z Jeriotą. A jej synami byli: Jeszer, Szobab i Ardon.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 19, 'A gdy Azuba umarła, Kaleb pojął sobie za żonę Efratę, która urodziła mu Chura.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 20, 'A Chur spłodził Uriego, a Uri spłodził Besaleela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 21, 'Potem Chesron obcował z córką Makira, ojca Gileada, i wziął ją za żonę, mając sześćdziesiąt lat, a ta urodziła mu Seguba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 22, 'A Segub spłodził Jaira, który miał dwadzieścia trzy miasta w ziemi Gilead.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 23, 'Zabrał bowiem Geszurze i Aramowi wsie Jaira oraz Kenat i przyległe do niego miasteczka: razem sześćdziesiąt miast. Wszystkie one należały do synów Makira, ojca Gileada.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 24, 'Po śmierci Chesrona w Kaleb-Efrata, żona Chesrona, Abija, urodziła mu Aszura, ojca Tekoa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 25, 'Synami Jerachmeela, pierworodnego Chesrona, byli: pierworodny Ram, następnie Buna, Oren, Ozem i Achiasz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 26, 'Jerachmeel miał także drugą żonę imieniem Atara. Była ona matką Onama.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 27, 'Synami Rama, pierworodnego Jerachmeela, byli: Maas, Jamin i Eker.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 28, 'Synami Onama byli Szammaj i Jada. Synami Szammaja: Nadab i Abiszur.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 29, 'Żona Abiszura miała na imię Abihail i urodziła mu Achbana i Molida.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 30, 'Synowie Nadaba: Seled i Appaim. Lecz Seled umarł bez potomstwa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 31, 'Synowie Appaima: Jiszi. Synowie Jisziego: Szeszan, a córka Szeszana: Achlaj.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 32, 'Synowie Jady, brata Szammaja: Jeter i Jonatan. A Jeter umarł bez potomstwa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 33, 'Synowie Jonatana: Pelet i Zaza. Byli oni synami Jerachmeela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 34, 'Lecz Szeszan nie miał synów, tylko córki. Miał też Szeszan sługę Egipcjanina imieniem Jarcha.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 35, 'Dał więc Szeszan swemu słudze Jarsze swoją córkę za żonę, a ona urodziła mu Attaja.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 36, 'Attaj spłodził Natana, a Natan spłodził Zabada.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 37, 'Zabad spłodził Eflala, a Eflal spłodził Obeda.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 38, 'Obed spłodził Jehu, a Jehu spłodził Azariasza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 39, 'Azariasz spłodził Chelesa, a Cheles spłodził Eleasę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 40, 'Eleasa spłodził Sismaja, a Sismaj spłodził Szalluma.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 41, 'A Szallum spłodził Jekamiasza, a Jekamiasz spłodził Eliszamę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 42, 'Synami Kaleba, brata Jerachmeela, byli: jego pierworodny Mesza, który był ojcem Zifa, i synowie Mareszy – ojcem Chebrona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 43, 'Synowie Chebrona: Korach, Tappuach, Rekem i Szema.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 44, 'Szema spłodził Rachama, syna Jorkoama, a Rekem spłodził Szammaja.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 45, 'Synem Szammaja był Maon, a Maon był ojcem Bet-Sura.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 46, 'Efa, nałożnica Kaleba, urodziła Charana, Mosę i Gazeza, a Charan spłodził Gazeza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 47, 'Synowie Jahdaja: Regem, Jotam, Geszan, Pelet, Efa i Szaaf.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 48, 'Maaka, druga nałożnica Kaleba, urodziła Szebera i Tyrchanę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 49, 'Urodziła również Szaafa, ojca Madmanny, i Szewę, ojca Makbeny i Gibea. A córką Kaleba była Aksa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 50, 'Ci byli synami Kaleba, syna Chura, pierworodnego Efraty: Szobal, ojciec Kiriat-Jearima;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 51, 'Salma, ojciec Betlejema, i Charef, ojciec Bet-Gadera.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 52, 'Szobal, ojciec Kiriat-Jearima, miał synów: Haroego i połowę Manachytów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 53, 'A rodziny Kiriat-Jearima to: Jitryci, Putyci, Szumatyci i Mirzaici, od których wywodzą się Soreatyci i Esztaolici.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 54, 'Synowie Salmy: Betlejem, Netofatyci, Atrot, rodzina Joaba i połowa Manachytów, Soreici;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 55, 'Rodziny pisarzy mieszkających w Jabes: Tyratyci, Szimeatyci i Sukatyci. Ci są Kenitami, którzy wywodzili się od Chamata, ojca domu Rechaba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 1, 'Oto synowie Dawida, którzy urodzili mu się w Hebronie: pierworodny Ammon z Achinoam, Jizreelitki, drugi Daniel z Abigail, Karmelitki;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 2, 'Trzeci Absalom, syn Maaki, córki Talmaja, króla Geszuru, czwarty Adoniasz, syn Chaggity;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 3, 'Piąty Szefatiasz z Abitali, szósty Jitream z jego żony Egli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 4, 'Tych sześciu urodziło mu się w Hebronie, gdzie królował przez siedem lat i sześć miesięcy. A trzydzieści trzy lata królował w Jerozolimie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 5, 'Ci zaś urodzili mu się w Jerozolimie: Szima, Szobab, Natan i Salomon – ci czterej z Batszui, córki Ammiela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 6, 'I Ibchar, Eliszama, Elifelet;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 7, 'Nogah, Nefeg, Jafia;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 8, 'Eliszama, Eliada i Elifelet – dziewięciu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 9, 'Ci wszyscy byli synami Dawida, nie licząc synów z nałożnic, a ich siostrą była Tamar.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 10, 'Synem Salomona był Roboam, a jego synem Abia, jego synem Asa, jego synem Jehoszafat;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 11, 'Jego synem Joram, jego synem Achazjasz, jego synem Joasz;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 12, 'Jego synem Amazjasz, jego synem Azariasz, jego synem Jotam;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 13, 'Jego synem Achaz, jego synem Ezechiasz, jego synem Manasses;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 14, 'Jego synem Amon, jego synem Jozjasz;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 15, 'A synami Jozjasza byli: pierworodny Jochanan, drugi Joakim, trzeci Sedekiasz, czwarty Szallum.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 16, 'Synowie Joakima: jego syn Jechoniasz i jego syn Sedekiasz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 17, 'Synowie Jechoniasza: Assir, jego syn Szealatiel;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 18, 'Malkiram, Pedajasz, Szeneassar, Jekamiasz, Hoszama i Nedabiasz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 19, 'Synowie Pedajasza: Zorobabel, Szimei. Synowie Zorobabela: Meszullam i Chananiasz, a ich siostra – Szelomit;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 20, 'I Chaszuba, Ohel, Berechiasz, Chasadiasz i Juszabchesed – pięciu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 21, 'Synowie Chananiasza: Pelatiasz i Jesajasz. Synowie Refajasza, synowie Arnana, synowie Obadiasza, synowie Szekaniasza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 22, 'Synowie Szekaniasza: Szemajasz; a synowie Szemajasza: Chattusz, Jigal, Bariach, Neariasz i Szafat – sześciu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 23, 'Synowie Neariasza: Elioenaj, Ezechiasz i Azrikam – trzech.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 24, 'Synowie Elioenaja: Hodawiasz, Eliaszib, Pelajasz, Akkub, Jochanan, Delajasz, Anani – siedmiu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 1, 'Synowie Judy: Peres, Chesron, Karmi, Chur i Szobal.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 2, 'A Reajasz, syn Szobala, spłodził Jachata, a Jachat spłodził Achumaja i Lahada. To są rody Soreatytów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 3, 'A ci pochodzą od ojca Etama: Jizreel, Jiszma i Jidbasz, a ich siostra miała na imię Haselelponi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 4, 'Penuel był ojcem Gedora, a Ezer – ojcem Chuszy. To są synowie Chura, pierworodnego Efraty, ojca Betlejema.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 5, 'A Aszur, ojciec Tekoa, miał dwie żony: Chelę i Naarę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 6, 'I Naara urodziła mu Achuzama, Chefera, Temniego i Achasztariego. Ci byli synami Naary.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 7, 'Synowie Cheli: Seret, Jesochar i Etnan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 8, 'A Koz spłodził Anuba, Zobeba i rody Acharchela, syna Haruma.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 9, 'A Jabes był bardziej poważany niż jego bracia. Jego matka dała mu na imię Jabes, mówiąc: Ponieważ urodziłam go w bólu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 10, 'I Jabes wzywał Boga Izraela, mówiąc: Obyś mi naprawdę błogosławił i rozszerzył moje granice, oby twoja ręka była ze mną, obyś zachował mnie od zła, abym nie był utrapiony. I Bóg spełnił to, o co go prosił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 11, 'A Kelub, brat Szuchy, spłodził Mechira, który był ojcem Esztona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 12, 'A Eszton spłodził Betrafę, Paseacha i Techinnę, ojca Irnachasza. To są mężczyźni z Rechy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 13, 'Synowie Kenaza: Otniel i Serajasz, a synowie Otniela: Chatat i Meonotaj.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 14, 'Meonotaj spłodził Ofrę. Serajasz zaś spłodził Joaba, ojca Charaszimów mieszkających w dolinie – byli bowiem rzemieślnikami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 15, 'Synowie Kaleba, syna Jefunnego: Iru, Ela i Naam. A synem Eli był Kenaz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 16, 'Synowie Jehalleleela: Zif, Zifa, Tiria i Asareel.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 17, 'Synowie Ezry: Jeter, Mered, Efer i Jalon. A żona Mereda urodziła Miriama, Szammaja i Iszbacha, ojca Esztemoi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 18, 'Jego żona Jehudaja urodziła Jereda, ojca Gedora, Chebera, ojca Soko, i Jekutiela, ojca Zanoacha. To są synowie Bitii, córki faraona, którą pojął za żonę Mered.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 19, 'Synowie jego żony Hodijji, siostry Nahama, ojca Keili: Garmity i Esztemoa, Maakatyta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 20, 'Synowie Szimona: Amnon, Rinna, Benchanan i Tilon. A synowie Jisziego: Zochet i Benzochet.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 21, 'Synowie Szeli, syna Judy: Er, ojciec Leki, Laada, ojciec Mareszy i tych rodów, które wytwarzały bisior w domu Aszbea;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 22, 'Jokim i mężczyźni Kozeby oraz Joasz i Saraf, którzy panowali w Moabie, a także Jaszubilechem. To są dawne wydarzenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 23, 'Byli oni garncarzami i mieszkali w sadach i między płotami. Mieszkali tam przy królu i pracowali dla niego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 24, 'Synowie Symeona: Nemuel, Jamin, Jarib, Zerach i Saul.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 25, 'Jego syn Szallum, jego syn Mibsam, jego syn Miszma.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 26, 'A synowie Miszmy: jego syn Chamuel, jego syn Zakkur, jego syn Szimei.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 27, 'Szimei miał szesnastu synów i sześć córek, lecz jego bracia nie mieli wielu synów i wszystkie ich rody nie były tak liczne jak rody synów Judy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 28, 'Mieszkali oni w Beer-Szebie, Molada i w Chasar-Szual;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 29, 'W Bilha, Esem i Tolad;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 30, 'W Betuel, Chorma i Siklag;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 31, 'W Bet-Markabot, Chasar-Susim, Bet-Birei i Szaaraim. To były ich miasta aż do panowania Dawida.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 32, 'A ich wioskami były: Etam, Ain, Rimmon, Token i Aszan, pięć miast;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 33, 'Oraz wszystkie ich wioski położone dokoła tych miast aż do Baal. To były ich miejsca zamieszkania i spisy ich rodów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 34, 'Meszobab, Jamlek i Josza, syn Amazjasza;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 35, 'Joel i Jehu, syn Joszibiasza, syna Serajasza, syna Asiela;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 36, 'I Elioenaj, Jaakoba, Jeszochajasz, Asajasz, Adiel, Jesimiel i Benajasz;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 37, 'Ziza, syn Szifiego, syna Allona, syna Jedajasza, syna Szimriego, syna Semajasza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 38, 'Ci wymienieni imiennie byli naczelnikami w swoich rodach, a rodziny ich ojców bardzo się rozrosły.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 39, 'I dotarli aż do wejścia do Gedor, aż na wschodnią stronę doliny, szukając pastwiska dla swych trzód.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 40, 'I znaleźli obfite i dobre pastwiska oraz ziemię obszerną, spokojną i bezpieczną. Tam bowiem mieszkali przedtem Chamici.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 41, 'Zapisani tu imiennie przyszli za czasów Ezechiasza, króla Judy, zniszczyli ich namioty i przybytki, które się tam znajdowały, doszczętnie wygubili ich i osiedlili się na ich miejscu. Tam bowiem były pastwiska dla ich trzód.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 42, 'Niektórzy z nich, pięciuset mężczyzn spośród synów Symeona, udali się na górę Seir, a ich przywódcami byli: Pelatiasz, Neariasz, Refajasz i Uzziel, synowie Jisziego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 43, 'I pobili resztę ocalałych Amalekitów, i zamieszkali tam do dziś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 1, 'Synowie Rubena, pierworodnego Izraela. Był on pierworodnym, ale ponieważ zbezcześcił łoże swego ojca, jego pierworództwo zostało dane synom Józefa, syna Izraela. Nie spisano więc rodowodu według pierworództwa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 2, 'Juda bowiem był najpotężniejszy wśród swoich braci i od niego pochodził władca, lecz pierworództwo należało do Józefa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 3, 'Synami Rubena, pierworodnego Izraela, byli: Henoch, Pallu, Chesron i Karmi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 4, 'Synowie Joela: jego syn Szemajasz, jego syn Gog, jego syn Szimei;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 5, 'Jego syn Micheasz, jego syn Reajasz, jego syn Baal;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 6, 'Jego syn Beera, którego Tiglat-Pileser, król Asyrii, wziął do niewoli. On był księciem Rubenitów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 7, 'Jego braćmi według swoich rodzin, gdy spisywano rodowody ich pokoleń, byli naczelnicy: Jejel, Zachariasz;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 8, 'I Bela, syn Azaza, syna Szemy, syna Joela, który zamieszkiwał w Aroerze aż po Nebo i Baal-Meon.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 9, 'A na wschodzie zamieszkiwał aż do wejścia na pustkowie od rzeki Eufrat. Ich stada bowiem pomnożyły się w ziemi Gilead.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 10, 'Za czasów Saula prowadzili wojnę z Hagrytami, którzy zostali przez nich pokonani. Zamieszkali więc w ich namiotach w całej wschodniej części Gileadu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 11, 'A synowie Gada mieszkali naprzeciw nich w ziemi Baszanu, aż do Salka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 12, 'Joel był zwierzchnikiem, potem Szafam, następnie Janaj i Szafat w Baszanie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 13, 'A ich braćmi według domów swoich ojców byli: Mikael, Meszullam, Szeba, Joraj, Jakan, Zija i Eber – siedmiu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 14, 'Ci są synami Abichaila, syna Churiego, syna Jaroacha, syna Gileada, syna Mikaela, syna Jesziszaja, syna Jachdo, syna Buza;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 15, 'Achi, syn Abdiela, syna Guniego – głowa domu ich ojców.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 16, 'I mieszkali w Gileadzie, w Baszanie, w jego miasteczkach i na wszystkich pastwiskach Szaronu aż po ich krańce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 17, 'Wszyscy oni spisani zostali według rodowodów za czasów Jotama, króla Judy, i za czasów Jeroboama, króla Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 18, 'Synów Rubena i Gada oraz połowy pokolenia Manassesa, dzielnych wojowników zdolnych do noszenia tarczy i miecza i do strzelania z łuku i wyćwiczonych w boju, było czterdzieści cztery tysiące siedmiuset sześćdziesięciu wyruszających do bitwy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 19, 'Oni prowadzili wojnę z Hagrytami, z Jeturem, z Nafiszem i Nodabem;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 20, 'I otrzymali pomoc przeciwko nim. Wydano więc w ich ręce Hagrytów wraz ze wszystkimi, którzy z nimi byli. Podczas walki bowiem wołali do Boga, a on ich wysłuchał, bo pokładali w nim ufność.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 21, 'I zabrali z ich stad: pięćdziesiąt tysięcy wielbłądów, dwieście pięćdziesiąt tysięcy owiec, dwa tysiące osłów, a ludzi – sto tysięcy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 22, 'Wielu bowiem poległo, gdyż wojna ta wyszła od Boga. I mieszkali na ich miejscu aż do uprowadzenia do niewoli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 23, 'Ale synowie połowy pokolenia Manassesa mieszkali w tej ziemi i rozmnożyli się od Baszanu aż do Baal-Chermon i Seniru, i do góry Hermon.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 24, 'A oto są naczelnicy domów ich ojców: Efer, Jiszi, Eliel, Azriel, Jeremiasz, Hodawiasz i Jachdiel, dzielni wojownicy, ludzie sławni, naczelnicy domu swoich ojców.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 25, 'Lecz zgrzeszyli przeciw Bogu swoich ojców i cudzołożyli, idąc za bogami narodów tej ziemi, które Bóg zniszczył przed nimi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 26, 'Wtedy Bóg Izraela pobudził ducha Pula, króla Asyrii, i ducha Tiglat-Pilesera, króla Asyrii, i uprowadził Rubenitów i Gadytów oraz połowę pokolenia Manassesa i zaprowadził ich do Chalach, do Chabor, do Hara i do rzeki Gozan; są tam aż do dziś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 1, 'Synowie Lewiego: Gerszom, Kehat i Merari.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 2, 'A synowie Kehata: Amram, Ishar, Chebron i Uzziel.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 3, 'A dzieci Amrama: Aaron, Mojżesz i Miriam. Synowie Aarona: Nadab, Abihu, Eleazar i Itamar.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 4, 'Eleazar spłodził Pinchasa, a Pinchas spłodził Abiszuę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 5, 'Abiszua spłodził Bukkiego, a Bukki spłodził Uzziego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 6, 'Uzzi spłodził Zerachiasza, a Zerachiasz spłodził Merajota.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 7, 'Merajot spłodził Amariasza, a Amariasz spłodził Achituba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 8, 'Achitub spłodził Sadoka, a Sadok spłodził Achimaasa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 9, 'Achimaas spłodził Azariasza, a Azariasz spłodził Jochanana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 10, 'Jochanan spłodził Azariasza. On to sprawował urząd kapłański w świątyni, którą Salomon zbudował w Jerozolimie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 11, 'Azariasz spłodził Amariasza, a Amariasz spłodził Achituba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 12, 'Achitub spłodził Sadoka, a Sadok spłodził Szalluma.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 13, 'Szallum spłodził Chilkiasza, a Chilkiasz spłodził Azariasza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 14, 'Azariasz spłodził Serajasza, a Serajasz spłodził Jehocadaka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 15, 'A Jehocadak trafił do niewoli, gdy Pan uprowadził Judę i Jerozolimę przez Nabuchodonozora.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 16, 'Synowie Lewiego: Gerszom, Kehat i Merari.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 17, 'A to są imiona synów Gerszoma: Libni i Szimei.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 18, 'A synowie Kehata: Amram, Ishar, Chebron i Uzziel.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 19, 'Synowie Merariego: Machli i Muszi. A to są rody Lewitów według ich ojców.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 20, 'Od Gerszoma: jego syn Libni, jego syn Jachat, jego syn Zimma;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 21, 'Jego syn Joach, jego syn Iddo, jego syn Zerach, jego syn Jeatraj.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 22, 'Synowie Kehata: jego syn Amminadab, jego syn Korach, jego syn Assir;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 23, 'Jego syn Elkana, jego syn Ebiasaf, jego syn Assir;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 24, 'Jego syn Tachat, jego syn Uriel, jego syn Uzjasz, jego syn Saul.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 25, 'Synowie Elkany: Amasaj, Achimot i Elkana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 26, 'Synowie Elkany: jego syn Sofaj, jego syn Nachat;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 27, 'Jego syn Eliab, jego syn Jerocham, jego syn Elkana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 28, 'Synowie Samuela: pierworodny Waszni i Abiasz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 29, 'Synowie Merariego: Machli, jego syn Libni, jego syn Szimei, jego syn Uzza;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 30, 'Jego syn Szimea, jego syn Chaggiasz, jego syn Asajasz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 31, 'To są ci, których Dawid ustanowił do prowadzenia śpiewu w domu Pana, odkąd spoczęła tam arka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 32, 'I posługiwali śpiewem przed przybytkiem, czyli Namiotem Zgromadzenia, aż Salomon zbudował dom Pana w Jerozolimie. Stawali do swojej służby według swego porządku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 33, 'A oto ci, którzy stawali wraz ze swoimi synami: spośród synów Kehata – śpiewak Heman, syn Joela, syna Samuela;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 34, 'Syna Elkany, syna Jerochama, syna Eliela, syna Toacha;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 35, 'Syna Sufa, syna Elkany, syna Machata, syna Amasaja;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 36, 'Syna Elkany, syna Joela, syna Azariasza, syna Sofoniasza;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 37, 'Syna Tachata, syna Assira, syna Ebiasafa, syna Koracha;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 38, 'Syna Ishara, syna Kehata, syna Lewiego, syna Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 39, 'Oraz jego brat Asaf, który stawał po jego prawicy. Asaf, syn Berechiasza, syna Szimei;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 40, 'Syna Mikaela, syna Baasejasza, syna Malkiasza;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 41, 'Syna Etniego, syna Zeracha, syna Adajasza;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 42, 'Syna Etana, syna Zimmy, syna Szimejego;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 43, 'Syna Jachata, syna Gerszoma, syna Lewiego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 44, 'A ich bracia, synowie Merariego, stawali po lewej stronie: Etan, syn Kisziego, syna Abdiego, syna Malluka;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 45, 'Syna Chaszabiasza, syna Amaziasza, syna Chiłkiasza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 46, 'Syna Amsjego, syna Baniego, syna Szamera;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 47, 'Syna Mochliego, syna Musziego, syna Merariego, syna Lewiego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 48, 'A ich bracia, Lewici, byli ustanowieni do wszelkiej posługi w przybytku domu Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 49, 'Aaron zaś i jego synowie palili kadzidło na ołtarzu całopalenia i na ołtarzu kadzenia, byli odpowiedzialni za wszelką posługę w Miejscu Najświętszym i za dokonywanie przebłagania za Izraela według wszystkiego, co nakazał Mojżesz, sługa Boży.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 50, 'A oto synowie Aarona: jego syn Eleazar, jego syn Pinchas;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 51, 'Jego syn Abiszua, jego syn Bukki, jego syn Uzzi, jego syn Zerachiasz;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 52, 'Jego syn Merajot, jego syn Amariasz, jego syn Achitub;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 53, 'Jego syn Sadok, jego syn Achimaas.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 54, 'A to są ich mieszkania według ich wieży w ich obszarze, to jest synów Aarona, według rodu Kehatytów. Był to bowiem ich los.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 55, 'Oddano im Hebron w ziemi Judy wraz z pastwiskami dokoła niego;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 56, 'Lecz pola miasta i jego wsie dano Kalebowi, synowi Jefunnego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 57, 'Synom Aarona zaś dano spośród miast Judy miasta schronienia: Hebron, Libnę z jego pastwiskami, Jattir i Esztemoę wraz z ich pastwiskami;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 58, 'I Chilen z jego pastwiskami, Debir z jego pastwiskami;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 59, 'Aszan z jego pastwiskami i Bet-Szemesz z jego pastwiskami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 60, 'A od pokolenia Beniamina: Geba z jego pastwiskami, Alemet z jego pastwiskami i Anatot z jego pastwiskami. Wszystkich ich miast było trzynaście według ich rodzin.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 61, 'A pozostałym synom Kehata, spośród rodziny tego pokolenia, przypadło losem dziesięć miast od połowy pokolenia Manassesa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 62, 'A synom Gerszoma według ich rodzin przypadło od pokolenia Issachara, od pokolenia Aszera, od pokolenia Neftalego i od pokolenia Manassesa w Baszanie – trzynaście miast.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 63, 'Synom Merariego według ich rodzin przypadło losem od pokolenia Rubena, od pokolenia Gada i od pokolenia Zebulona – dwanaście miast.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 64, 'Synowie Izraela dali Lewitom te miasta wraz z ich pastwiskami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 65, 'A dali przez los od pokolenia synów Judy, od pokolenia synów Symeona i od pokolenia synów Beniamina te miasta, którym nadali ich imiona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 66, 'A ci, którzy pochodzili z rodu synów Kehata, mieli miasta w granicach pokolenia Efraima.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 67, 'Dano im z miast schronienia: Sychem z jego pastwiskami na górze Efraim i Gezer z jego pastwiskami;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 68, 'Jokmeam z jego pastwiskami, Bet-Choron z jego pastwiskami;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 69, 'Ajjalon z jego pastwiskami i Gat-Rimmon z jego pastwiskami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 70, 'Od połowy pokolenia Manassesa: Aner z jego pastwiskami, Bileam z jego pastwiskami. Dano to rodzinie pozostałych synów Kehata.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 71, 'Synom Gerszoma dano od połowy pokolenia Manassesa Golan w Baszanie z jego pastwiskami i Asztarot z jego pastwiskami;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 72, 'Od pokolenia Issachara – Kedesz z jego pastwiskami, Daberat z jego pastwiskami;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 73, 'Ramot z jego pastwiskami i Anem z jego pastwiskami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 74, 'Od pokolenia Aszera: Maszal z jego pastwiskami, Abdon z jego pastwiskami;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 75, 'Chukok z jego pastwiskami i Rechob z jego pastwiskami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 76, 'Od pokolenia Neftalego: Kedesz w Galilei z jego pastwiskami, Chammon z jego pastwiskami i Kiriataim z jego pastwiskami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 77, 'Pozostałym synom Merariego dano od pokolenia Zebulona Rimmon z jego pastwiskami i Tabor z jego pastwiskami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 78, 'A po drugiej stronie Jordanu koło Jerycha, na wschód od Jordanu, dano od pokolenia Rubena: Beser na pustyni z jego pastwiskami, Jahazę z jej pastwiskami;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 79, 'Kedemot z jego pastwiskami i Mefaat z jego pastwiskami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 80, 'Od pokolenia Gada: Ramot w Gileadzie z jego pastwiskami, Machanaim z jego pastwiskami;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 81, 'Cheszbon z jego pastwiskami i Jazer z jego pastwiskami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 1, 'Synami Issachara byli: Tola, Pua, Jaszub, Szimron – czterej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 2, 'Synowie Tolego: Uzzi, Refajasz, Jeriel, Jachmaj, Jebsam i Szemuel – naczelnicy rodów Toli. Byli oni dzielnymi wojownikami w swoich czasach. Ich liczba za czasów Dawida wynosiła dwadzieścia dwa tysiące sześciuset.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 3, 'Synowie Uzziego: Izrachiasz, a synowie Izrachiasza: Mikael, Obadiasz, Joel i Jeszijasz, pięciu – wszyscy naczelnicy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 4, 'A z nimi, według rodowodów, według domów ich ojców, były oddziały zbrojne do walki w liczbie trzydziestu sześciu tysięcy. Mieli bowiem wiele żon i synów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 5, 'Ich bracia według wszystkich rodów Issachara, dzielni wojownicy, liczyli osiemdziesiąt siedem tysięcy, wszyscy spisani byli według rodowodów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 6, 'Synowie Beniamina: Bela, Beker i Jediael, trzej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 7, 'Synowie Beli: Eszbon, Uzzi, Uzziel, Jerimot i Iri, pięciu – naczelnicy domów ojców, dzielni wojownicy; spisani według rodowodu liczyli dwadzieścia dwa tysiące trzydziestu czterech.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 8, 'Synowie Bekera: Zemira, Joasz, Eliezer, Elioenaj, Omri, Jerimot, Abiasz, Anatot i Alamet. Ci wszyscy byli synami Bekera.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 9, 'A spisani według swoich rodowodów, naczelnicy domów swoich ojców, dzielni wojownicy, liczyli dwadzieścia tysięcy dwustu mężczyzn.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 10, 'Synowie Jediaela: Bilhan, a synowie Bilhana: Jehusz, Beniamin, Ehud, Kenaana, Zetan, Tarszisz i Achiszachar.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 11, 'Ci wszyscy synowie Jediaela, naczelnicy rodów, dzielni wojownicy, liczyli siedemnaście tysięcy dwustu wyruszających na wojnę do bitwy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 12, 'Także Szuppim i Chuppim, synowie Ira, oraz Chuszim, synowie Achera.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 13, 'Synowie Neftalego: Jachasjel, Guni, Jeser i Szallum, synowie Bilhy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 14, 'Synowie Manassesa: Asriel, którego urodziła mu żona (a jego nałożnica Aramejka urodziła Makira, ojca Gileada;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 15, 'A Makir wziął sobie za żonę siostrę Chuppima i Szuppima, która miała na imię Maaka); drugi syn miał na imię Selofchad. Selofchad zaś miał tylko córki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 16, 'Maaka, żona Makira, urodziła syna i nadała mu imię Peresz. Jego brat miał na imię Szeresz, a jego synami byli Ulam i Rekiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 17, 'Synowie Ulama: Bedon. To są synowie Gileada, syna Makira, syna Manassesa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 18, 'Jego siostra Hammoleket urodziła Iszhoda, Abiezera i Machlę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 19, 'Synowie Szemidy: Achian, Szekem, Likchi i Aniam.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 20, 'Synowie Efraima: Szutelach, jego syn Bered, jego syn Tachat, jego syn Elada, jego syn Tachat;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 21, 'Jego syn Zabad, jego syn Szutelach, a także Eser i Elad, których zabili ludzie z Gat urodzeni w tej ziemi. Wtargnęli bowiem, aby zabrać ich stada.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 22, 'Ich ojciec Efraim opłakiwał ich przez wiele dni, a jego bracia przyszli, aby go pocieszyć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 23, 'Potem obcował ze swoją żoną, a ona poczęła i urodziła syna, i nadał mu imię Beria, ponieważ stało się nieszczęście w jego domu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 24, 'Jego córką była Szeera, która zbudowała Bet-Choron dolne i górne oraz Uzen-Szeera.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 25, 'I jego syn Refach, i Reszef, a jego syn Telach, jego syn Tachan;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 26, 'Jego syn Ladan, jego syn Ammihud, jego syn Eliszama;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 27, 'Jego syn Nun, jego syn Jozue.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 28, 'A ich posiadłości i miejsca zamieszkania to Betel i należące do niego miejscowości, na wschód – Naaran, a na zachód – Gezer i należące do niego miejscowości, a także Sychem i należące do niego miejscowości; aż do Gazy i należących do niej miejscowości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 29, 'I aż do granic synów Manassesa, które stanowiły Bet-Szean i należące do niego miejscowości, Tanak i należące do niego miejscowości, Megiddo i należące do niego miejscowości oraz Dor i należące do niego miejscowości. W nich mieszkali synowie Józefa, syna Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 30, 'Synowie Aszera: Jimna, Jiszwa, Jiszwi, Beria i Sera, ich siostra.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 31, 'Synowie Berii: Cheber i Malkiel, który jest ojcem Birzaita.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 32, 'A Cheber spłodził Jafleta, Szomera, Chotama oraz ich siostrę Szuę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 33, 'Synowie Jafleta: Pasak, Bimhal i Aszwat. To są synowie Jafleta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 34, 'Synowie Szomera: Achi, Rohga, Jechubba i Aram.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 35, 'Synowie jego brata Chelema: Sofach, Jimna, Szelesz i Amal.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 36, 'Synowie Sofacha: Suach, Charnefer, Szual, Beri, Jimra;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 37, 'Beser, Hod, Szamma, Szilsza, Jitran i Beera.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 38, 'Synowie Jetera: Jefunne, Pispa i Ara.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 39, 'Synowie Ulli: Arach, Channiel i Risja.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 40, 'Ci wszyscy to synowie Aszera, naczelnicy rodów, wyborowi i dzielni wojownicy, pierwsi wśród książąt. Ich liczba spisana według rodowodu wynosiła dwadzieścia sześć tysięcy zdolnych do walki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 1, 'Beniamin spłodził Belę, swego pierworodnego, Aszbela – drugiego, Achracha – trzeciego;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 2, 'Nocha – czwartego, Rafa – piątego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 3, 'Synami Beli byli: Addar, Gera, Abihud;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 4, 'Abiszua, Naaman, Achoach;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 5, 'Gera, Szefufan i Huram.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 6, 'Oto synowie Ehuda – byli oni naczelnikami rodów mieszkających w Geba i zostali przesiedleni do Manachat;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 7, 'Byli to: Naaman, Achiasz i Gera. On ich przesiedlił i potem spłodził Uzzę i Ahiuda.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 8, 'A Sacharaim spłodził dzieci w krainie Moabu po odprawieniu swoich żon Chuszimy i Baary.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 9, 'Spłodził więc ze swojej żony Chodeszy Jobaba, Sibię, Meszę, Malkoma;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 10, 'Jeusa, Sakiasza i Mirmę. Ci byli jego synami, naczelnikami rodów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 11, 'Z Chuszimy spłodził Abituba i Elpaala.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 12, 'Synowie Elpaala: Eber, Miszam i Szemed, który zbudował Ono i Lod oraz należące do niego miejscowości;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 13, 'A także Beria i Szema, którzy byli naczelnikami rodów mieszkających w Ajjalonie. To oni wypędzili mieszkańców Gat.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 14, 'A Achio, Szaszak, Jeremot;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 15, 'Zebadiasz, Arad, Eder;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 16, 'Mikael, Jiszpa i Jocha – byli to synowie Berii.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 17, 'A Zebadiasz, Meszullam, Chiszki, Cheber;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 18, 'Jiszmeraj, Jiszlia i Jobab – byli synami Elpaala.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 19, 'A Jakim, Zikri, Zabdi;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 20, 'Elioenaj, Silletaj, Eliel;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 21, 'Adajasz, Berajasz, Szimrat – to synowie Szimejego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 22, 'A Jiszpan, Eber, Eliel;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 23, 'Abdon, Zikri, Chanan;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 24, 'Chananiasz, Elam i Antotiasz;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 25, 'Jifdejasz i Penuel – to synowie Szaszaka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 26, 'A Szamszeraj, Szechariasz, Ataliasz;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 27, 'Jaareszjasz, Eliasz i Zikri – to synowie Jerochama.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 28, 'Ci byli naczelnikami rodów, przywódcami według swoich rodowodów, a zamieszkali w Jerozolimie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 29, 'W Gibeonie mieszkał ojciec Gibeona, a jego żona miała na imię Maaka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 30, 'Jego pierworodnym synem był Abdon, a następni to: Sur, Kisz, Baal, Nadab;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 31, 'Gedor, Achio i Zakir.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 32, 'Miklot spłodził Szimeę. Oni także mieszkali ze swoimi braćmi w Jerozolimie, naprzeciw swoich braci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 33, 'Ner spłodził Kisza, a Kisz spłodził Saula, Saul zaś spłodził Jonatana, Malkiszuę, Abinadaba i Eszbaala.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 34, 'Synem Jonatana był Meribbaal, Meribbaal zaś spłodził Micheasza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 35, 'Synowie Micheasza: Piton, Melek, Tarea i Achaz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 36, 'Achaz spłodził Jehoaddę, a Jehoadda spłodził Alemeta, Azmaweta i Zimriego, a Zimri spłodził Mosę;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 37, 'Mosa spłodził Bineę, jego synem był Rafa, jego synem był Eleasa, jego synem był Asel.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 38, 'Asel miał sześciu synów, a oto ich imiona: Azrikam, Bokru, Izmael, Szeariasz, Obadiasz i Chanan. Ci wszyscy byli synami Asela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 39, 'Synowie jego brata Eszeka: Ulam, jego pierworodny, Jeusz – drugi, Elifelet – trzeci;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 40, 'Synowie Ulama byli dzielnymi wojownikami, sprawnymi łucznikami, a mieli wielu synów i wnuków, razem – stu pięćdziesięciu. Ci wszyscy pochodzili z synów Beniamina.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 1, 'Tak wszyscy Izraelici byli spisani w rodowodach, a oto zostały one zapisane w księdze królów Izraela i Judy, a ci zostali uprowadzeni do Babilonu z powodu swego przestępstwa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 2, 'Pierwszymi mieszkańcami, którzy weszli do swych posiadłości w swoich miastach, byli Izraelici, kapłani, Lewici i Netinici.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 3, 'W Jerozolimie mieszkali spośród synów Judy, Beniamina, Efraima i Manassesa:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 4, 'Utaj, syn Ammihuda, syna Omriego, syna Imriego, syna Baniego, z synów Peresa, syna Judy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 5, 'Z Szilonitów: pierworodny Asajasz i jego synowie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 6, 'Z synów Zeracha: Jeuel i ich braci, sześciuset dziewięćdziesięciu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 7, 'Z synów Beniamina: Sallu, syn Meszullama, syna Hodawiasza, syna Hassenuy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 8, 'I Jibnejasz, syn Jerochama, Ela, syn Uzziego, syna Mikriego, i Meszullam, syn Szefatiasza, syna Reuela, syna Jibniasza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 9, 'Ich braci według rodowodów było dziewięćset pięćdziesięciu sześciu. Ci wszyscy byli naczelnikami rodów według domów swoich ojców.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 10, 'Z kapłanów: Jedajasz, Jehojarib, Jakin;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 11, 'I Azariasz, syn Chilkiasza, syna Meszullama, syna Sadoka, syna Merajota, syna Achituba, przełożonego domu Bożego;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 12, 'I Adajasz, syn Jerochama, syna Paszchura, syna Malkiasza, i Maasaj, syn Adiela, syna Jachzery, syna Meszullama, syna Meszillemita, syna Immera;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 13, 'Ich braci, naczelników swoich rodów, było tysiąc siedmiuset sześćdziesięciu, ludzi zdolnych do pełnienia służby w domu Bożym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 14, 'A z Lewitów: Szemejasz, syn Chaszuba, syna Azrikama, syna Chaszabiasza, z synów Merariego;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 15, 'I Bakbakar, Cheresz, Galal, Mattaniasz, syn Micheasza, syna Zikriego, syna Asafa;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 16, 'I Obadiasz, syn Szemajasza, syna Galala, syna Jedutuna, i Berechiasz, syn Asy, syna Elkany, który mieszkał we wsiach Netofatytów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 17, 'A odźwierni: Szallum, Akkub, Talmon, Achiman i ich bracia. Szallum był ich zwierzchnikiem;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 18, 'Który aż dotąd stawał przy bramie królewskiej od wschodu. Ci byli odźwiernymi w obozach synów Lewiego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 19, 'Szallum, syn Korego, syna Ebiazafa, syna Koracha, i jego bracia z domu jego ojca, Korachici, pełnili służbę, byli stróżami progów namiotu, a ich ojcowie byli stróżami wejścia do obozu Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 20, 'Pinchas, syn Eleazara, był niegdyś zwierzchnikiem nad nimi, a Pan był z nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 21, 'Zachariasz, syn Meszelemiasza, był odźwiernym przy wejściu do Namiotu Zgromadzenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 22, 'Wszystkich wybranych na odźwiernych przy bramach było dwustu dwunastu. Byli oni policzeni według ich rodowodu w swoich osiedlach, a ustanowił ich Dawid i Samuel, widzący.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 23, 'Oni więc i ich synowie czuwali nad bramami domu Pana, w domu namiotu, jako stróże.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 24, 'Odźwierni znajdowali się z czterech stron: od wschodu, od zachodu, od północy i od południa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 25, 'Ich bracia zaś, mieszkający w swoich osiedlach, przychodzili co siódmy dzień, w swoich porach, aby być z nimi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 26, 'Czterej bowiem naczelni odźwierni pełnili stałą służbę. Byli to Lewici odpowiedzialni za komnaty i skarbiec domu Bożego;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 27, 'I nocowali dokoła domu Bożego, gdyż do nich należała straż i obowiązek otwierania go każdego ranka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 28, 'Niektórzy z nich mieli pieczę nad naczyniami do służby, by je wnosić i wynosić w tej samej liczbie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 29, 'Inni spośród nich byli ustanowieni do opieki nad naczyniami i przyborami Miejsca Najświętszego – nad mąką pszenną, winem, oliwą, kadzidłem i wonnościami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 30, 'A niektórzy z synów kapłanów sporządzali olejki z wonności.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 31, 'Mattitiasz, spośród Lewitów, pierworodny Szalluma Korachity, był przełożonym nad tym, co przygotowane w patelniach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 32, 'Niektórzy ich bracia spośród synów Kehata byli ustanowieni do opieki nad chlebami pokładnymi, aby je przygotowywać w każdy szabat.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 33, 'Ci byli śpiewakami, naczelnikami rodów Lewitów, którzy mieszkają w komnatach; byli wolni od innych zajęć, gdyż we dnie i w nocy zajmowali się tą służbą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 34, 'Byli oni naczelnikami rodów Lewitów, naczelnikami według swoich rodowodów, a mieszkali w Jerozolimie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 35, 'W Gibeonie mieszkał Jejel, ojciec Gibeona, a jego żona miała na imię Maaka;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 36, 'A jego synem pierworodnym był Abdon, a następni to: Sur, Kisz, Baal, Neer, Nadab;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 37, 'I Gedor, Achio, Zachariasz, i Miklot.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 38, 'A Miklot spłodził Szimmeama. Tamci również mieszkali ze swoimi braćmi w Jerozolimie naprzeciw swoich braci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 39, 'Neer spłodził Kisza, a Kisz spłodził Saula, a Saul spłodził Jonatana, Malkiszuę, Abinadaba i Eszbaala.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 40, 'Synem Jonatana był Meribbaal, a Meribbaal spłodził Micheasza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 41, 'Synowie zaś Micheasza to: Piton, Melek, Tarea i Achaz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 42, 'Achaz spłodził Jarę, a Jara spłodził Alemeta, Azmaweta i Zimriego, a Zimri spłodził Mosę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 43, 'Mosa spłodził Bineę, a jego synem był Rafa, jego synem był Elasa, jego synem był Asel.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 44, 'Asel miał sześciu synów, a oto ich imiona: Azrikam, Bokru, Izmael, Szeariasz, Obadiasz i Chanan. Ci byli synami Asela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 1, 'Gdy Filistyni walczyli z Izraelem, Izraelici uciekli przed nimi i padli zabici na górze Gilboa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 2, 'I Filistyni ścigali Saula i jego synów, i zabili Jonatana, Abinadaba i Malkiszuę, synów Saula.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 3, 'A gdy rozgorzała bitwa przeciw Saulowi, łucznicy trafili w niego i został przez nich ciężko zraniony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 4, 'Wtedy Saul powiedział do swego giermka: Dobądź swój miecz i przebij mnie nim, aby nie przyszli ci nieobrzezani i nie znęcali się nade mną. Ale jego giermek nie chciał tego zrobić, ponieważ bardzo się bał. Saul więc wziął miecz i sam rzucił się na niego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 5, 'A gdy jego giermek zobaczył, że Saul umarł, rzucił się i on na swój miecz i umarł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 6, 'Tak umarli Saul i jego trzej synowie, a cały jego dom zginął razem z nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 7, 'A gdy wszyscy Izraelici, którzy mieszkali w dolinie, zobaczyli, że Izraelici uciekli oraz że Saul i jego synowie umarli, opuścili swoje miasta i uciekli. Przyszli więc Filistyni i mieszkali w nich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 8, 'Kiedy nazajutrz Filistyni przyszli, aby złupić zabitych, znaleźli Saula i jego synów poległych na górze Gilboa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 9, 'Obdarli go więc z szat, wzięli jego głowę i zbroję i rozesłali po całej ziemi filistyńskiej, aby ogłosić radosną wieść swoim bożkom i swojemu ludowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 10, 'Jego zbroję położyli w domu swoich bogów, a jego głowę powiesili w świątyni Dagona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 11, 'Kiedy wszyscy mieszkańcy Jabesz-Gilead usłyszeli o wszystkim, co Filistyni uczynili Saulowi;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 12, 'Powstali wszyscy waleczni mężczyźni, wzięli ciało Saula oraz ciała jego synów, przynieśli je do Jabesz i pogrzebali ich kości pod dębem w Jabesz. Potem pościli przez siedem dni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 13, 'Tak umarł Saul z powodu swojego przestępstwa, które popełnił przeciwko Panu i przeciwko słowu Pana, którego nie przestrzegał, oraz za to, że szukał rady czarownika;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 14, 'A nie radził się Pana. Pan zabił go więc i przeniósł królestwo na Dawida, syna Jessego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 1, 'Wtedy cały Izrael zebrał się przy Dawidzie w Hebronie, mówiąc: Oto jesteśmy twoją kością i twoim ciałem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 2, 'Już przedtem, gdy jeszcze Saul był królem, wyprowadzałeś i wprowadzałeś Izraela. I Pan, twój Bóg, powiedział ci: Ty będziesz pasł mój lud Izraela i ty będziesz wodzem nad moim ludem, Izraelem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 3, 'Przyszli więc wszyscy starsi Izraela do króla do Hebronu i Dawid zawarł z nimi przymierze w Hebronie przed Panem. Namaścili Dawida na króla nad Izraelem zgodnie ze słowem Pana, które wypowiedział przez Samuela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 4, 'I Dawid wyruszył wraz z całym Izraelem do Jerozolimy, to jest Jebus; mieszkańcami tej ziemi byli Jebusyci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 5, 'Wtedy mieszkańcy Jebus powiedzieli do Dawida: Nie wejdziesz tutaj. Dawid jednak zdobył twierdzę Syjon, to jest miasto Dawida.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 6, 'Potem Dawid powiedział: Kto pierwszy pokona Jebusytów, będzie wodzem i naczelnikiem. Wystąpił więc jako pierwszy Joab, syn Serui, i został wodzem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 7, 'I Dawid zamieszkał w twierdzy, dlatego nazwano ją miastem Dawida.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 8, 'Rozbudował miasto wokoło, od Millo, a Joab odbudował resztę miasta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 9, 'A Dawid stawał się coraz potężniejszy, ponieważ Pan zastępów był z nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 10, 'Oto naczelnicy spośród dzielnych wojowników, których miał Dawid i którzy dzielnie starali się z nim o jego królestwo wraz z całym Izraelem, aby uczynić go królem zgodnie ze słowem Pana o Izraelu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 11, 'A oto spis dzielnych wojowników, których miał Dawid: Jaszobeam, syn Chakmoniego, naczelnik dowódców. On to podniósł swoją włócznię przeciw trzystu i pobił ich za jednym razem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 12, 'Po nim Eleazar, syn Dodo, Achochita, jeden spośród trzech dzielnych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 13, 'Był on z Dawidem w Pas-Dammim, gdzie Filistyni zebrali się do walki. Było tam pole pełne jęczmienia, a lud uciekał przed Filistynami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 14, 'I stanęli na środku tego pola, obronili je i pobili Filistynów. Tak dokonał Pan wielkiego wybawienia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 15, 'A trzej spośród trzydziestu dowódców zeszli po skale do Dawida, do jaskini Adullam, podczas gdy wojsko Filistynów obozowało w dolinie Rafaim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 16, 'Dawid bowiem przebywał w tym czasie w miejscu obronnym, a załoga Filistynów znajdowała się wtedy w Betlejem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 17, 'Dawid poczuł wówczas pragnienie i powiedział: Oby ktoś dał mi się napić wody ze studni w Betlejem, która jest przy bramie!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 18, 'Wtedy ci trzej przebili się przez wojsko Filistynów i zaczerpnęli wody ze studni w Betlejem, która jest przy bramie. Zabrali ją i przynieśli do Dawida. Dawid jednak nie chciał jej pić, ale wylał ją na ofiarę dla Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 19, 'I powiedział: Niech Pan mnie strzeże od tego, abym miał to uczynić. Czy mam pić krew tych ludzi, którzy narażali swoje życie? Przynieśli bowiem wodę z narażeniem swego życia. I nie chciał jej pić. Tych dzieł dokonali ci trzej najdzielniejsi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 20, 'A Abiszaj, brat Joaba, stał na czele tych trzech. On to podniósł swoją włócznię przeciw trzystu i pobił ich, i miał sławę wśród tych trzech.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 21, 'Wśród tych trzech był on sławniejszy od pozostałych dwóch i był ich dowódcą. Nie dorównał jednak tamtym trzem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 22, 'Benajasz, syn Jehojady, syn walecznego męża z Kabseela, który dokonał wielu czynów, zabił dwóch wojowników z Moabu. On też zszedł do jamy i zabił lwa w śnieżnym dniu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 23, 'Zabił również Egipcjanina, człowieka o wzroście pięciu łokci. Egipcjanin miał w ręku włócznię, grubą jak wał tkacki. On zaś zszedł do niego z kijem, wyrwał włócznię z ręki Egipcjanina i zabił go jego własną włócznią.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 24, 'Tego dokonał Benajasz, syn Jehojady, i miał sławę wśród tych trzech dzielnych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 25, 'Wśród trzydziestu był on sławny, ale nie dorównał tamtym trzem. I Dawid postawił go na czele swojej straży przybocznej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 26, 'Dzielnymi wojownikami wojska byli: Asahel, brat Joaba, Elchanan, syn Dodo z Betlejem;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 27, 'Szammot z Harodi, Cheles Pelonita;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 28, 'Ira, syn Ikkesza, Tekoitczyk, Abiezer Anatotczyk;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 29, 'Sibbekaj Chuszatyta, Ilaj Achochita;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 30, 'Maharaj Netofatyta, Cheled, syn Baany, Netofatyta;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 31, 'Itaj, syn Ribaja, z Gibea synów Beniamina, Benajasz Piratończyk;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 32, 'Churaj z potoków Gaasz, Abiel Arbatczyk;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 33, 'Azmawet Bacharumczyk, Eliachba Szaalbończyk;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 34, 'Synowie Chaszema Gisończyka, Jonatan, syn Szagiego, Hararyta;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 35, 'Achiam, syn Sakara, Hararyta, Elifal, syn Ura;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 36, 'Chefer Mekeratyta, Achiasz Pelonita;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 37, 'Chesro Karmelita, Naaraj, syn Ezbaja;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 38, 'Joel, brat Natana, Mibchar, syn Hagriego;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 39, 'Selek Ammonita, Nacharaj Berotczyk, giermek Joaba, syna Serui;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 40, 'Ira Jitryta, Gareb Jitryta;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 41, 'Uriasz Chetyta, Zabad, syn Achlaja;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 42, 'Adina, syn Szizy, Rubenita, naczelnik Rubenitów, a wraz z nim trzydziestu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 43, 'Chanan, syn Maaki, Joszafat Mitnita;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 44, 'Uziasz Aszteratczyk, Szama i Jejel, synowie Chotamy Aroerczyka;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 45, 'Jediael, syn Szimriego, i jego brat Jocha, Tizyta;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 46, 'Eliel Machawita, Jeribaj i Joszawiasz, synowie Elnaama, Jitma Moabita;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 47, 'Eliel, Obed i Jaasiel Mezobata.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 1, 'Oto ci, którzy przyszli do Dawida w Siklag, gdy ukrywał się przed Saulem, synem Kisza. Należeli oni do dzielnych wojowników, którzy wspierali go w walce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 2, 'Byli uzbrojeni w łuki i potrafili prawą i lewą ręką miotać kamieniami i strzelać z łuku, a wywodzili się z braci Saula, z Beniamina.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 3, 'Naczelnikiem był Achiezer, potem Joasz, synowie Szemajasza Gibeatczyka, Jezjel i Pelet, synowie Azmaweta, Beraka i Jehu Anatotczyk;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 4, 'I Jiszmaja Gibeonita, dzielny wojownik spośród trzydziestu i dowodzący trzydziestoma, Jeremiasz, Jachaziel, Jochanan i Jozabad Gederatyta;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 5, 'Eluzaj, Jerimot, Bealiasz, Szemariasz i Szefatiasz Charufita;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 6, 'Elkana, Jiszijasz, Azareel, Joezer i Jaszobam – Korachici;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 7, 'Joela i Zebadiasz, synowie Jerochama z Gedoru.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 8, 'Z pokolenia Gada w warowni na pustyni do Dawida przyłączyli się dzielni wojownicy, żołnierze sprawni w boju, noszący tarczę i dzidę, ich twarze były jak twarze lwów, a byli zwinni jak sarny w górach;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 9, 'Ezer pierwszy, Obadiasz drugi, Eliab trzeci;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 10, 'Miszmanna czwarty, Jeremiasz piąty;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 11, 'Attaj szósty, Eliel siódmy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 12, 'Jochanan ósmy, Elzabad dziewiąty;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 13, 'Jeremiasz dziesiąty, Makbanaj jedenasty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 14, 'Wywodzili się oni z synów Gada, dowódcy wojska: najmniejszy był nad stu, a największy – nad tysiącem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 15, 'To są ci, którzy przeszli przez Jordan w pierwszym miesiącu, kiedy wylał na wszystkie brzegi, i zmusili do ucieczki wszystkich mieszkańców dolin na wschód i na zachód.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 16, 'Do warowni do Dawida przyszli także niektórzy z synów Beniamina i Judy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 17, 'I Dawid wyszedł naprzeciw nich, i odpowiedział: Jeśli przyszliście do mnie w pokoju, aby mi pomóc, moje serce połączy się z wami. Lecz jeśli przyszliście, aby mnie wydać moim wrogom, choć moje ręce są wolne od nieprawości, niech wejrzy w to Bóg naszych ojców i niech osądzi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 18, 'Wtedy Duch ogarnął Amasaja, naczelnika dowódców, i powiedział: Jesteśmy twoi, Dawidzie, i jesteśmy z tobą, synu Jessego. Pokój, pokój tobie i pokój twoim pomocnikom! Gdyż tobie pomaga twój Bóg. Dawid więc przyjął ich i ustanowił dowódcami oddziałów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 19, 'Z pokolenia Manassesa niektórzy przyłączyli się do Dawida, gdy wyruszył z Filistynami na wojnę przeciwko Saulowi. Lecz nie pomogli im, gdyż książęta Filistynów po naradzie odesłali go, mówiąc: Ten za cenę naszych głów wróci do swego pana Saula.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 20, 'Gdy szedł do Siklag, przyłączyli się do niego z Manassesa: Adnach, Jozabad, Jediael, Mikael, Jozabad, Elihu i Silletaj, dowódcy nad tysiącami w pokoleniu Manassesa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 21, 'Oni to pomogli Dawidowi przeciw bandzie, bo byli wszyscy dzielnymi wojownikami i dowódcami wojska.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 22, 'W tym czasie dzień za dniem ludzie przybywali do Dawida, aby mu pomagać, aż powstało wielkie wojsko jak wojsko Boże.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 23, 'A oto liczba oddziałów gotowych do boju, które przyszły do Dawida w Hebronie, aby przenieść na niego królestwo Saula zgodnie ze słowem Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 24, 'Z synów Judy, noszących tarczę i włócznię, sześć tysięcy ośmiuset uzbrojonych do boju.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 25, 'Z synów Symeona, dzielnych wojowników na wojnę, siedem tysięcy stu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 26, 'Z synów Lewiego cztery tysiące sześciuset.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 27, 'Także Jehojada, przywódca synów Aarona, a z nim trzy tysiące siedmiuset.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 28, 'I Sadok, młody, dzielny wojownik wraz z domem swego ojca – dwudziestu dwóch dowódców.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 29, 'Z synów Beniamina, braci Saula, trzy tysiące. Dotąd bowiem większość z nich pozostawała w służbie domu Saula.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 30, 'Z synów Efraima dwadzieścia tysięcy ośmiuset dzielnych wojowników, ludzi sławnych w domach swych ojców.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 31, 'Z połowy pokolenia Manassesa osiemnaście tysięcy, którzy imiennie zostali wyznaczeni, aby przyjść i ustanowić Dawida królem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 32, 'Z synów Issachara, umiejących rozpoznać czasy, tak że wiedzieli, co Izrael ma czynić – dwustu naczelników, a wszyscy ich bracia stawali na ich rozkazy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 33, 'Z pokolenia Zebulona tych, którzy wychodzili na wojnę, wyćwiczonych w walce wszelką bronią wojenną – pięćdziesiąt tysięcy stających w szyku bojowym i niemających dwoistego serca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 34, 'Z pokolenia Neftalego – tysiąc dowódców, a z nimi trzydzieści siedem tysięcy uzbrojonych w tarcze i włócznie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 35, 'Z pokolenia Dana gotowych do boju było dwadzieścia osiem tysięcy sześciuset mężczyzn.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 36, 'Z pokolenia Aszera tych, którzy wychodzili na wojnę, wyćwiczonych w walce – czterdzieści tysięcy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 37, 'Z drugiej strony Jordanu z pokolenia Rubena i Gada oraz z połowy pokolenia Manassesa w pełnym uzbrojeniu wojennym – sto dwadzieścia tysięcy mężczyzn.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 38, 'Ci wszyscy wojownicy, którzy stawali w szyku bojowym, całym sercem przyszli do Hebronu, aby ustanowić Dawida królem nad całym Izraelem. Również i cała reszta Izraela była jednomyślna w tym, aby ustanowić Dawida królem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 39, 'I byli tam z Dawidem przez trzy dni, jedząc i pijąc, gdyż ich bracia przygotowali to dla nich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 40, 'Również ci, którzy byli w ich pobliżu, aż po Issachara i Zebulona, i Neftalego, przynosili żywność na osłach, na wielbłądach, na mułach i na wołach: potrawy, mąkę, figi, rodzynki, wino, oliwę oraz woły i owce w wielkiej ilości, bo zapanowała radość w Izraelu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 1, 'A Dawid odbył naradę z tysiącznikami i setnikami oraz ze wszystkimi dowódcami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 2, 'Potem Dawid powiedział do całego zgromadzenia Izraela: Jeśli wam się to podoba i jeśli jest to od Pana, naszego Boga, roześlijmy wiadomość wszędzie do naszych braci, którzy pozostali we wszystkich krainach Izraela, a także do kapłanów i Lewitów – po miastach i ich pastwiskach – i niech się zgromadzą u nas;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 3, 'Abyśmy sprowadzili do nas arkę naszego Boga. Nie pytaliśmy bowiem o nią za czasów Saula.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 4, 'I całe zgromadzenie powiedziało, aby tak czynić, bo ta rzecz podobała się całemu ludowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 5, 'Dawid więc zebrał cały Izrael od egipskiego Szichoru aż do wejścia do Chamat, aby sprowadzić arkę Boga z Kiriat-Jearim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 6, 'Dawid wyruszył wraz z całym Izraelem do Baali, w Kiriat-Jearim, które znajduje się w Judzie, aby sprowadzić stamtąd arkę Pana Boga zasiadającego nad cherubinami, gdzie wzywane jest jego imię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 7, 'I wywieźli arkę Boga na nowym wozie z domu Abinadaba, a Uzza i Achio prowadzili wóz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 8, 'Dawid zaś i cały Izrael grali przed Bogiem ze wszystkich sił, śpiewając przy dźwiękach harf, cytr, bębnów, cymbałów i trąb.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 9, 'A gdy przyszli na klepisko Kidona, Uzza wyciągnął rękę, aby przytrzymać arkę, bo woły się potknęły.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 10, 'I zapłonął gniew Pana przeciwko Uzzie i Pan go zabił, dlatego że wyciągnął rękę do arki. I umarł tam przed Bogiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 11, 'I Dawid był wielce niezadowolony, że Pan tak srogo poraził Uzzę, dlatego nazwał to miejsce Peres-Uzza i tak jest nazywane do dziś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 12, 'I Dawid zląkł się Boga tego dnia, i powiedział: Jak mam wprowadzić do siebie arkę Boga?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 13, 'Dlatego Dawid nie wprowadził arki do siebie, do miasta Dawida, lecz wprowadził ją do domu Obed-Edoma Gittyty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 14, 'I arka Boga pozostała z domownikami Obed-Edoma w jego domu przez trzy miesiące. A Pan błogosławił domowi Obed-Edoma i wszystkiemu, co miał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 1, 'Potem Hiram, król Tyru, wysłał posłów do Dawida wraz z drewnem cedrowym, murarzami i cieślami, aby mu zbudowali dom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 2, 'I Dawid poznał, że Pan potwierdził jego królowanie nad Izraelem, gdyż wywyższył jego królestwo ze względu na swój lud Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 3, 'Dawid pojął więcej żon w Jerozolimie i spłodził więcej synów i córek.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 4, 'A oto imiona tych, którzy mu się urodzili w Jerozolimie: Szammua, Szobab, Natan, Salomon;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 5, 'Jibchar, Eliszua, Elpalet;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 6, 'Noga, Nefeg, Jafia;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 7, 'Eliszama, Beeliada i Elifelet.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 8, 'Kiedy Filistyni usłyszeli, że Dawid został namaszczony na króla nad całym Izraelem, wszyscy Filistyni wyruszyli, aby go szukać. Gdy Dawid usłyszał o tym, wyszedł naprzeciw nich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 9, 'Filistyni przybyli i rozciągnęli się w dolinie Refaim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 10, 'I Dawid radził się Boga, mówiąc: Czy mam wyruszyć przeciw Filistynom i czy wydasz ich w moje ręce? Pan mu odpowiedział: Wyruszaj, a wydam ich w twoje ręce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 11, 'A gdy przybyli do Baal-Perasim, tam Dawid ich pobił. Wtedy Dawid powiedział: Bóg rozerwał moich wrogów przez moją rękę, jak rozrywają się wody. Dlatego nazwał to miejsce Baal-Perasim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 12, 'I porzucili tam swoje bożki, a Dawid rozkazał spalić je ogniem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 13, 'Lecz Filistyni znowu rozciągnęli się w dolinie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 14, 'Dawid więc ponownie radził się Boga, a Bóg mu odpowiedział: Nie ruszaj na nich, ale odwróć się od nich, abyś natarł na nich od strony drzew morwowych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 15, 'A gdy usłyszysz odgłos kroków wśród wierzchołków drzew morwowych, wtedy wyruszysz do bitwy, gdyż Bóg wyruszył przed tobą, aby pobić wojska Filistynów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 16, 'I Dawid uczynił tak, jak mu rozkazał Bóg, i pobili wojska Filistynów od Gibeonu aż do Gezer.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 17, 'I w ten sposób rozsławiło się imię Dawida na wszystkich ziemiach, a Pan sprawił, że bały się go wszystkie narody.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 1, 'A gdy Dawid zbudował sobie domy w mieście Dawida, przygotował miejsce dla arki Boga i rozbił jej namiot.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 2, 'Wtedy Dawid powiedział: Nie wolno nikomu nosić arki Boga oprócz Lewitów. Ich bowiem wybrał Pan, aby nosili arkę Boga i aby służyli mu na wieki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 3, 'Dawid więc zebrał całego Izraela w Jerozolimie, aby przenieść arkę Pana na miejsce, które dla niej przygotował.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 4, 'Zgromadził też Dawid synów Aarona i Lewitów:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 5, 'Z synów Kehata: Uriela naczelnika i jego braci – stu dwudziestu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 6, 'Z synów Merariego: Asajasza naczelnika i jego braci – dwustu dwudziestu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 7, 'Z synów Gerszoma: Joela naczelnika i jego braci – stu trzydziestu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 8, 'Z synów Elisafana: Szemajasza naczelnika i jego braci – dwustu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 9, 'Z synów Chebrona: Eliela naczelnika i jego braci – osiemdziesięciu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 10, 'Z synów Uzziela: Amminadaba naczelnika i jego braci – stu dwunastu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 11, 'Wtedy Dawid wezwał kapłanów Sadoka i Abiatara oraz Lewitów: Uriela, Asajasza, Joela, Szemajasza, Eliela i Amminadaba;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 12, 'I powiedział do nich: Jesteście naczelnikami rodów lewickich. Poświęćcie się wy i wasi bracia, abyście mogli przenieść arkę Pana, Boga Izraela, na miejsce, które dla niej przygotowałem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 13, 'Ponieważ za pierwszym razem tego nie uczyniliście, Pan, nasz Bóg, zesłał na nas nieszczęście, bo nie szukaliśmy go tak, jak należy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 14, 'Poświęcili się więc kapłani i Lewici, aby przenieść arkę Pana, Boga Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 15, 'Synowie Lewitów nieśli arkę Boga, jak rozkazał Mojżesz według słowa Pana, na swoich ramionach na drążkach, które przy niej były.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 16, 'Potem Dawid rozkazał naczelnikom Lewitów, aby ustanowili swoich braci śpiewakami przy instrumentach muzycznych: cytrach, harfach i cymbałach, aby rozbrzmiewał donośny głos pełen radości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 17, 'Lewici ustanowili Hemana, syna Joela, a z jego braci – Asafa, syna Berechiasza, a z synów Merariego, ich braci – Etana, syna Kuszajasza;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 18, 'A z nimi braci ich drugiego stopnia: Zachariasza, Bena, Jaaziela, Szemiramota, Jechiela, Unniego, Eliaba, Benajasza, Maasejasza, Mattitiasza, Elifela, Miknejasza, Obed-Edoma i Jejela – odźwiernych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 19, 'A śpiewacy Heman, Asaf i Etan grali głośno na cymbałach z brązu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 20, 'Zachariasz, Jaziel, Szemiramot, Jechiel, Unni, Elijab, Maasejasz i Benajasz grali na cytrach na Alamot.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 21, 'A Mattitiasz, Elifel, Miknejasz, Obed-Edom, Jejel i Azaziasz grali na harfach na Seminit i prowadzili śpiew.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 22, 'A Kenaniasz, naczelnik Lewitów, odpowiadał za pieśni. Kierował śpiewaniem, bo był uzdolniony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 23, 'Berekiasz i Elkana byli odźwiernymi przy arce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 24, 'A kapłani: Szebaniasz, Joszafat, Netaneel, Amasaj, Zachariasz, Benajasz i Eliezer grali na trąbach przed arką Boga, a Obed-Edom i Jechiasz byli odźwiernymi przy arce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 25, 'Tak więc Dawid, starsi Izraela i tysiącznicy wyruszyli, aby z radością przenieść arkę przymierza Pana z domu Obed-Edoma.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 26, 'I kiedy Bóg wspomógł Lewitów niosących arkę przymierza Pana, złożyli w ofierze siedem wołów i siedem baranów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 27, 'A Dawid był ubrany w szatę z bisioru, podobnie jak wszyscy Lewici, którzy nieśli arkę, śpiewacy i Kenaniasz, kierujący śpiewem. Dawid miał także na sobie lniany efod.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 28, 'I w ten sposób cały Izrael prowadził arkę przymierza Pana wśród radosnych okrzyków, przy dźwięku kornetu, trąb i cymbałów, grając na cytrach i harfach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 29, 'I kiedy arka przymierza Pana wchodziła do miasta Dawida, Mikal, córka Saula, wyglądała przez okno i zobaczyła króla Dawida tańczącego i grającego. I wzgardziła nim w swoim sercu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 1, 'A gdy przynieśli arkę Boga i umieścili ją pośrodku namiotu wzniesionego przez Dawida, złożyli całopalenia i ofiary pojednawcze przed Bogiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 2, 'A gdy Dawid skończył składanie całopaleń i ofiar pojednawczych, błogosławił lud w imię Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 3, 'I rozdał wszystkim Izraelitom, tak mężczyźnie, jak i kobiecie, po bochenku chleba i po kawałku mięsa oraz po bukłaku wina.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 4, 'Ustanowił też niektórych Lewitów sługami przed arką Pana, aby wspominali i chwalili go, i dziękowali Panu, Bogu Izraela:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 5, 'Asafa, naczelnika, a po nim Zachariasza, Jejela, Szemiramota, Jechiela, Mattitiasza, Eliaba, Benajasza i Obed-Edoma: Jejela do gry na instrumentach: cytrach i harfach, a Asafa – na cymbałach;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 6, 'A kapłanów Benajasza i Jachaziela, aby stali nieustannie z trąbami przed arką przymierza Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 7, 'Wtedy w tym dniu Dawid postanowił po raz pierwszy, aby Asaf i jego bracia chwalili Pana tym psalmem:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 8, 'Wysławiajcie Pana, wzywajcie jego imienia, opowiadajcie między narodami sprawy jego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 9, 'Śpiewajcie mu, śpiewajcie mu psalmy, rozmawiajcie o wszystkich jego cudach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 10, 'Chlubcie się jego świętym imieniem, niech się raduje serce szukających Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 11, 'Szukajcie Pana i jego mocy, szukajcie zawsze jego oblicza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 12, 'Przypominajcie sobie dzieła, które czynił, jego cuda i wyroki jego ust.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 13, 'Wy, potomkowie Izraela, jego sługi; wy, synowie Jakuba, jego wybrańcy!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 14, 'On jest Panem, naszym Bogiem, jego sądy na całej ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 15, 'Pamiętajcie zawsze o jego przymierzu, o słowie, które nakazał po tysiąc pokoleń;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 16, 'O przymierzu, które zawarł z Abrahamem, i o przysiędze złożonej Izaakowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 17, 'Ustanowił je jako prawo dla Jakuba, jako wieczne przymierze dla Izraela;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 18, 'Mówiąc: Tobie dam ziemię Kanaan jako dział waszego dziedzictwa;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 19, 'Kiedy było was niewielu, byliście nieliczni i obcy w niej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 20, 'I wędrowali od narodu do narodu, z jednego królestwa do innego ludu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 21, 'Nikomu nie pozwolił ich krzywdzić, nawet karcił królów z ich powodu, mówiąc;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 22, 'Nie dotykajcie moich pomazańców, a moim prorokom nie czyńcie nic złego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 23, 'Śpiewaj Panu, cała ziemio, opowiadajcie dzień po dniu o jego zbawieniu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 24, 'Głoście wśród narodów jego chwałę, pośród wszystkich ludów – jego cudowne dzieła;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 25, 'Wielki bowiem jest Pan i godny wszelkiej chwały, straszliwszy nad wszystkich bogów;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 26, 'Gdyż wszyscy bogowie narodów są bożkami, a Pan uczynił niebiosa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 27, 'Chwała i cześć przed nim, moc i radość w jego przybytku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 28, 'Oddajcie Panu, rodziny narodów, oddajcie Panu chwałę i moc.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 29, 'Oddajcie Panu chwałę jego imienia. Przynoście dary i przychodźcie przed jego oblicze. Oddajcie Panu pokłon w ozdobie świętości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 30, 'Zadrżyj przed nim, cała ziemio. Świat będzie utwierdzony, aby się nie poruszył.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 31, 'Niech się weselą niebiosa i niech się raduje ziemia, niech mówią wśród narodów: Pan króluje!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 32, 'Niech zaszumi morze i to, co je napełnia, niech radują się pola i wszystko, co jest na nich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 33, 'Wtedy radośnie wykrzykną leśne drzewa przed Panem, bo idzie, aby sądzić ziemię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 34, 'Wysławiajcie Pana, bo jest dobry, bo jego miłosierdzie trwa na wieki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 35, 'I mówcie: Zbaw nas, Boże naszego zbawienia, i zgromadź nas, i wybaw nas od pogan, abyśmy wielbili twoje święte imię i chlubili się twoją chwałą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 36, 'Błogosławiony Pan, Bóg Izraela, na wieki wieków. I cały lud powiedział: Amen i chwalił Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 37, 'I Dawid zostawił tam przed arką przymierza Pana Asafa i jego braci, aby nieustannie pełnili służbę przed arką, według potrzeby każdego dnia;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 38, 'Także Obed-Edoma i ich braci, sześćdziesięciu ośmiu; a Obed-Edoma, syna Jedutuna, i Chosę uczynił odźwiernymi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 39, 'Kapłana Sadoka i jego braci kapłanów pozostawił przed przybytkiem Pana na wyżynie w Gibeonie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 40, 'Aby składali Panu nieustannie, rano i wieczorem, całopalenia na ołtarzu całopaleń, zgodnie ze wszystkim, co jest napisane w Prawie Pana, które nadał on Izraelowi;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 41, 'A z nimi pozostawił Hemana i Jedutuna oraz resztę wybranych, imiennie wyznaczonych, aby chwalili Pana, bo jego miłosierdzie trwa na wieki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 42, 'I u nich, u Hemana i Jedutuna, pozostawił trąby i cymbały dla grających na tych i na innych instrumentach muzycznych dla Boga. Synowie zaś Jedutuna byli odźwiernymi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 43, 'Potem cały lud się rozszedł, każdy do swego domu. Dawid też wrócił, aby błogosławić swojemu domowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 1, 'Kiedy Dawid zamieszkał w swoim domu, powiedział do proroka Natana: Oto mieszkam w domu cedrowym, a arka przymierza Pana pod zasłonami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 2, 'Natan powiedział do Dawida: Uczyń wszystko, co jest w twoim sercu, gdyż Bóg jest z tobą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 3, 'Lecz tej samej nocy doszło do Natana słowo Boże, mówiące:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 4, 'Idź i powiedz mojemu słudze Dawidowi: Tak mówi Pan: Nie ty zbudujesz mi dom, w którym zamieszkam.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 5, 'Nie mieszkałem bowiem w żadnym domu od dnia, w którym wyprowadziłem synów Izraela, aż do dziś, ale przechodziłem z namiotu do namiotu i z przybytku do przybytku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 6, 'Wszędzie, gdziekolwiek chodziłem z całym Izraelem, czy powiedziałem do któregoś z sędziów Izraela, którym nakazałem paść mój lud: Dlaczego nie zbudowaliście mi domu cedrowego?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 7, 'Teraz więc tak powiesz mojemu słudze Dawidowi: Tak mówi Pan zastępów: Ja wziąłem ciebie z owczarni od chodzenia za trzodą, abyś był dowódcą nad moim ludem Izraelem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 8, 'I byłem z tobą wszędzie, dokądkolwiek chodziłeś, wytraciłem przed tobą wszystkich twoich wrogów i uczyniłem twoje imię jak imię wielkich ludzi, którzy są na ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 9, 'Ustanowię miejsce dla swego ludu Izraela i zasadzę go tam, i będzie mieszkał na swoim miejscu, i nie poruszy się więcej ani już nie będą go gnębić synowie nieprawości jak dawniej;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 10, 'Od czasu, kiedy ustanowiłem sędziów nad swoim ludem Izraela, i ujarzmię wszystkich twoich wrogów. Oznajmiam ci też, że Pan zbuduje ci dom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 11, 'Gdy się wypełnią twoje dni i będziesz musiał odejść do swoich ojców, wzbudzę po tobie twego potomka, który będzie spośród twoich synów, i utwierdzę jego królestwo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 12, 'On zbuduje mi dom i utwierdzę jego tron na wieki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 13, 'Ja będę mu ojcem, a on będzie mi synem. Nie cofnę od niego swojego miłosierdzia, jak je cofnąłem od tego, który był przed tobą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 14, 'Ustanowię go w moim domu i w moim królestwie na wieki, jego tron będzie utwierdzony na wieki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 15, 'Zgodnie z tymi wszystkimi słowami i zgodnie z całym tym widzeniem, tak mówił Natan do Dawida.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 16, 'Przyszedł więc król Dawid, usiadł przed Panem i powiedział: Kim ja jestem, Panie Boże, i czym jest mój dom, że doprowadziłeś mnie dotąd?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 17, 'Lecz i to było jeszcze mało w twoich oczach, Boże, gdyż złożyłeś też obietnicę o domu swego sługi na daleką przyszłość i wejrzałeś na mnie jak na człowieka wysokiego stanu, Panie Boże.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 18, 'Co więcej może ci powiedzieć Dawid za taką chwałę okazaną twemu słudze? Ty bowiem znasz swego sługę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 19, 'Panie, przez wzgląd na swego sługę i według swego serca uczyniłeś te wszystkie wielkie rzeczy, dając poznać te wszystkie wspaniałe sprawy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 20, 'Panie, nie ma nikogo podobnego do ciebie i nie ma Boga oprócz ciebie według wszystkiego, co słyszeliśmy na własne uszy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 21, 'I czy jest taki naród na ziemi, jak twój lud Izrael, dla którego Bóg wyruszył, aby go sobie wykupić jako swój lud, a przez to uczynić swoje imię wielkim i straszliwym, wypędzając narody przed swoim ludem, który wykupiłeś z Egiptu?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 22, 'Uczyniłeś bowiem twój lud Izraela swoim ludem na wieki i ty, Panie, stałeś się jego Bogiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 23, 'Teraz więc, Panie, niech słowo, które wypowiedziałeś o swoim słudze i o jego domu, będzie utwierdzone na wieki i uczyń, jak powiedziałeś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 24, 'Niech stanie się tak, aby twoje imię było uwielbione na wieki, aby mówiono: Pan zastępów, Bóg Izraela, jest Bogiem nad Izraelem; niech dom Dawida, twego sługi, będzie utwierdzony przed tobą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 25, 'Ty bowiem, mój Boże, objawiłeś swemu słudze, że zbudujesz mu dom. Dlatego twój sługa ośmielił się modlić przed tobą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 26, 'A teraz, Panie, ty jesteś Bogiem i obiecałeś takie dobro swemu słudze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 27, 'Racz więc błogosławić dom swego sługi, aby trwał na wieki przed tobą. Co bowiem ty, Panie, błogosławisz, będzie błogosławione na wieki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 1, 'Po tych wydarzeniach Dawid pobił Filistynów, ujarzmił ich i zabrał z ich rąk Gat i jego wioski.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 2, 'Pobił też Moab i Moabici stali się sługami Dawida składającymi daninę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 3, 'Dawid pobił też Hadadezera, króla Soby w Chamat, gdy ten wyprawił się, aby rozciągnąć swoją władzę nad rzeką Eufrat.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 4, 'Dawid zabrał mu wtedy tysiąc rydwanów, siedem tysięcy jeźdźców i dwadzieścia tysięcy pieszych. I popodcinał Dawid ścięgna wszystkich koniom zaprzęgowym, zostawiając z nich tylko tyle, ile potrzeba do stu rydwanów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 5, 'Kiedy Syryjczycy z Damaszku przybyli na pomoc Hadadezerowi, królowi Soby, Dawid pobił spośród nich dwadzieścia dwa tysiące ludzi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 6, 'Potem Dawid umieścił załogi w Syrii damasceńskiej, a Syryjczycy stali się sługami Dawida składającymi daninę. Tak Pan zachowywał Dawida, dokądkolwiek ten się udał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 7, 'Dawid zabrał też złote tarcze, które mieli słudzy Hadadezera, i przyniósł je do Jerozolimy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 8, 'Również z Tibchat i Kun, miast Hadadezera, Dawid zabrał bardzo dużo brązu, z którego Salomon wykonał morze brązowe, słupy i naczynia brązowe.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 9, 'A gdy usłyszał Tou, król Chamatu, że Dawid pobił całe wojsko Hadadezera, króla Soby;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 10, 'Posłał swego syna Hadorama do króla Dawida, aby go pozdrowił w pokoju i aby mu powinszował tego, że walczył z Hadadezerem i pokonał go – Hadadezer bowiem prowadził wojnę z Tou – i Hadoram przyniósł ze sobą wszelkiego rodzaju naczynia złote, srebrne i brązowe.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 11, 'Również i je król Dawid poświęcił Panu wraz ze srebrem i złotem, które pobrał od wszystkich narodów: od Edomu, od Moabu, od synów Ammona, od Filistynów i od Amaleka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 12, 'I Abiszaj, syn Serui, pobił w Dolinie Soli osiemnaście tysięcy Edomitów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 13, 'I umieścił w Edomie załogi, a wszyscy Edomici stali się sługami Dawida. Tak Pan zachowywał Dawida, dokądkolwiek ten się udał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 14, 'Dawid więc królował nad całym Izraelem i sprawował sąd nad całym swym ludem, i wymierzał mu sprawiedliwość.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 15, 'Joab, syn Serui, był postawiony nad wojskiem, a Jehoszafat, syn Achiluda, był kronikarzem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 16, 'Sadok, syn Achituba, i Abimelek, syn Abiatara, byli kapłanami, a Szawsza był pisarzem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 17, 'Benajasz, syn Jehojady, był postawiony nad Keretytami i Peletytami, a synowie Dawida byli pierwszymi przy królu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 1, 'Potem umarł Nachasz, król synów Ammona, a jego syn królował w jego miejsce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 2, 'Wtedy Dawid powiedział: Okażę życzliwość Chanunowi, synowi Nachasza, bo jego ojciec mnie okazał życzliwość. I Dawid wysłał posłańców, aby go pocieszyć po stracie jego ojca. Przyszli więc słudzy Dawida do ziemi synów Ammona, do Chanuna, aby go pocieszyć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 3, 'Lecz książęta synów Ammona powiedzieli do Chanuna: Czy myślisz, że Dawid chce uczcić twego ojca i dlatego przysłał do ciebie pocieszycieli? Czy nie po to raczej przyszli jego słudzy do ciebie, aby przypatrzyć się tej ziemi, przeszpiegować ją i zburzyć?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 4, 'Chanun wziął więc sługi Dawida, ogolił ich, obciął ich szaty do połowy, aż do pośladków, i odesłał ich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 5, 'Wtedy niektórzy poszli i donieśli Dawidowi o tych ludziach. I wysłał posłów naprzeciw nich, ponieważ ci mężczyźni byli bardzo znieważeni. Król powiedział im: Zostańcie w Jerychu, aż wam brody odrosną, a potem wróćcie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 6, 'Gdy synowie Ammona spostrzegli, że obrzydli Dawidowi, Chanun i synowie Ammona posłali tysiąc talentów srebra, aby sobie wynająć za te pieniądze rydwany i jeźdźców z Mezopotamii, z Syrii-Maaka i z Soby.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 7, 'I najęli sobie za te pieniądze trzydzieści dwa tysiące rydwanów oraz króla Maaki wraz z jego ludem. Przybyli i rozbili obóz naprzeciw Medeby, a synowie Ammona zebrali się ze swoich miast i ustawili się do bitwy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 8, 'A gdy Dawid usłyszał o tym, wysłał Joaba z całym zastępem dzielnych wojowników.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 9, 'Ruszyli więc synowie Ammona i ustawili się w szyku bojowym przed bramą miejską. Królowie zaś, którzy przybyli na pomoc, stanęli osobno w polu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 10, 'Gdy Joab zobaczył, że wojsko szykuje walkę przeciwko niemu z przodu i z tyłu, wybrał mężczyzn spośród wszystkich wyborowych wojowników w Izraelu i ustawił ich w szyku bojowym przeciw Syryjczykom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 11, 'A resztę ludzi oddał pod rękę swego brata Abiszaja – oni ustawili się w szyku bojowym przeciw synom Ammona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 12, 'I powiedział: Jeśli Syryjczycy będą silniejsi ode mnie, przyjdziesz mi na pomoc, a jeśli synowie Ammona będą silniejsi od ciebie, ja przyjdę tobie na pomoc.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 13, 'Bądź odważny i walczmy mężnie za nasz lud i za miasta naszego Boga, a niech Pan uczyni to, co jest dobre w jego oczach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 14, 'Joab więc wraz z ludem, który był z nim, wyruszył do bitwy z Syryjczykami. A oni uciekli przed nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 15, 'Gdy synowie Ammona zobaczyli, że Syryjczycy uciekli, również i oni uciekli przed jego bratem Abiszajem i weszli do miasta. Wtedy Joab wrócił do Jerozolimy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 16, 'Kiedy Syryjczycy zobaczyli, że są pobici przez Izraela, wyprawili posłańców i sprowadzili Syryjczyków, którzy byli za rzeką. I Szofak, dowódca wojska Hadadezera, prowadził ich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 17, 'Gdy doniesiono o tym Dawidowi, ten zebrał cały Izrael, przeprawił się przez Jordan, przybył do nich i ustawił wojsko przeciwko nim w szyku bojowym. A gdy Dawid ustawił wojsko w szyku bojowym przeciwko Syryjczykom, oni walczyli z nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 18, 'Lecz Syryjczycy uciekli przed Izraelem i spośród nich Dawid zabił siedem tysięcy ludzi walczących na rydwanach oraz czterdzieści tysięcy pieszych. Zabił również Szofaka, dowódcę wojska.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 19, 'Kiedy słudzy Hadadezera zobaczyli, że zostali pokonani przez Izraela, zawarli pokój z Dawidem i zostali jego poddanymi. Potem Syryjczycy już nie chcieli udzielić pomocy synom Ammona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 1, 'A na początku roku, w czasie, gdy królowie zwykli wyjeżdżać na wojnę, Joab poprowadził potężne wojsko i spustoszył ziemię synów Ammona, potem nadciągnął i obległ Rabbę, Dawid tymczasem pozostał w Jerozolimie. I Joab zdobył Rabbę, i zburzył ją.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 2, 'Wtedy Dawid zdjął koronę jej króla z jego głowy, a okazało się, że waży ona talent złota, była też ozdobiona drogocennymi kamieniami. I włożono ją na głowę Dawida. Wywiózł też z miasta bardzo dużo łupów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 3, 'Lud, który był w nim, wyprowadził i przeciął piłami, bronami żelaznymi i siekierami. Tak uczynił Dawid ze wszystkimi miastami synów Ammona. Potem Dawid wrócił wraz z całym ludem do Jerozolimy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 4, 'Następnie doszło do wojny z Filistynami w Gezer. Wtedy to Sibbekaj Chuszatyta zabił Sippaja z rodu olbrzyma i tak Filistyni zostali pokonani.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 5, 'I znowu była wojna z Filistynami, kiedy Elchanan, syn Jaira, zabił Lachmiego, brata Goliata Gittyty, którego drzewce włóczni było jak wał tkacki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 6, 'I była jeszcze wojna w Gat, gdzie znajdował się człowiek wysokiego wzrostu, który miał po sześć palców u rąk i nóg, razem – dwadzieścia cztery palce. On również pochodził z rodu tego olbrzyma.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 7, 'A gdy wyzywał Izraela, zabił go Jonatan, syn Szimei, brata Dawida.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 8, 'Ci byli synami jednego olbrzyma z Gat, a polegli z ręki Dawida i z rąk jego sług.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 1, 'Wtedy szatan powstał przeciwko Izraelowi i pobudził Dawida, aby policzył Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 2, 'Dawid więc powiedział do Joaba i do przełożonych nad ludem: Idźcie, policzcie Izraela od Beer-Szeby aż do Dan i donieście mi o ich liczbie, abym ją poznał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 3, 'Lecz Joab odpowiedział: Niech Pan pomnoży swój lud sto razy tyle, ile go jest. Lecz, mój panie, królu, czy nie są oni wszyscy sługami mego pana? Czemu mój pan żąda tego? Czemu miałoby to być przyczyną grzechu dla Izraela?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 4, 'Słowo króla jednak przemogło Joaba. Wyszedł więc Joab, obszedł całego Izraela i wrócił do Jerozolimy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 5, 'I podał Joab Dawidowi liczbę policzonych. A było wszystkich w Izraelu milion sto tysięcy mężczyzn dobywających miecz, a z Judy – czterysta siedemdziesiąt tysięcy mężczyzn dobywających miecz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 6, 'Lecz Lewitów i Beniaminitów nie policzył razem z nimi, gdyż rozkaz króla budził odrazę w Joabie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 7, 'Nie podobała się też Bogu ta rzecz, więc ukarał Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 8, 'Wtedy Dawid powiedział do Boga: Zgrzeszyłem bardzo, czyniąc tę rzecz. Lecz teraz, proszę, zgładź nieprawość swego sługi, gdyż bardzo głupio postąpiłem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 9, 'I Pan powiedział do Gada, widzącego Dawida:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 10, 'Idź i powiedz Dawidowi: Tak mówi Pan: Trzy rzeczy ci przedstawiam, wybierz sobie jedną z nich, abym ci uczynił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 11, 'Przyszedł więc Gad do Dawida i powiedział mu: Tak mówi Pan: Wybierz sobie:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 12, 'Albo trzy lata głodu, albo trzy miesiące klęsk od twoich wrogów, podczas których miecz twoich wrogów będzie cię ścigał, albo trzy dni miecza Pana i zarazy w ziemi, kiedy Anioł Pana będzie niszczył wszystkie granice Izraela. Teraz więc rozważ, co mam odpowiedzieć temu, który mnie posłał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 13, 'Dawid odpowiedział Gadowi: Jestem w wielkiej rozterce. Niech wpadnę raczej w ręce Pana, gdyż wielkie jest jego miłosierdzie. Niech nie wpadnę w ręce człowieka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 14, 'Zesłał więc Pan zarazę na Izraela. I poległo z Izraela siedemdziesiąt tysięcy mężczyzn.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 15, 'Posłał też Bóg Anioła do Jerozolimy, aby ją zniszczyć. A gdy ją niszczył, wejrzał Pan i użalił się nad tym nieszczęściem i powiedział do Anioła, który niszczył: Dosyć już, powstrzymaj rękę. A Anioł Pana stał obok klepiska Ornana Jebusyty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 16, 'Gdy Dawid podniósł oczy, ujrzał Anioła Pana stojącego między ziemią a niebem, a w jego ręce dobyty miecz wyciągnięty nad Jerozolimą. Wtedy Dawid i starsi, ubrani w wory, upadli na twarze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 17, 'I Dawid powiedział do Boga: Czy nie ja rozkazałem policzyć lud? Ja jestem tym, który zgrzeszył i bardzo źle uczynił, ale te owce, co uczyniły? Panie, mój Boże, błagam, niech się obróci twoja ręka przeciwko mnie, domowi mego ojca. Lecz niech się nie rozprzestrzenia ta plaga przeciwko twemu ludowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 18, 'Wtedy Anioł Pana powiedział do Gada, aby oznajmił Dawidowi, że ma iść i zbudować Panu ołtarz na klepisku Ornana Jebusyty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 19, 'Dawid więc poszedł według słowa Gada, który mówił w imieniu Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 20, 'Wtedy Ornan obrócił się i ujrzał Anioła, a jego czterej synowie, którzy byli z nim, ukryli się. A Ornan młócił pszenicę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 21, 'Gdy Dawid przyszedł do Ornana, ten spojrzał i zobaczył Dawida. Wyszedł więc z klepiska i pokłonił się Dawidowi twarzą do ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 22, 'I Dawid powiedział do Ornana: Odstąp mi miejsce tego klepiska, abym zbudował na nim ołtarz Panu. Oddaj mi je za pełną cenę, aby plaga odstąpiła od ludu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 23, 'Ornan odpowiedział Dawidowi: Weź je sobie i niech mój pan, król, uczyni, co uważa za słuszne. Oto oddaję też woły na całopalenia, sprzęty młocarskie na drwa i pszenicę na ofiarę z pokarmów – to wszystko daję.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 24, 'I król Dawid powiedział do Ornana: Nie, raczej kupię wszystko za pełną cenę. Nie wezmę bowiem dla Pana tego, co jest twoje, ani nie będę ofiarował całopaleń, które nic nie kosztują.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 25, 'Dał więc Dawid Ornanowi za to miejsce sykle złota w wadze sześciuset.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 26, 'I Dawid zbudował tam Panu ołtarz, złożył całopalenia i ofiary pojednawcze i wzywał Pana, a on mu odpowiedział z nieba, spuszczając ogień na ołtarz całopalenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 27, 'I Pan rozkazał Aniołowi, by schował swój miecz do pochwy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 28, 'Wtedy Dawid, widząc, że Pan go wysłuchał na klepisku Ornana Jebusyty, składał tam ofiary.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 29, 'Przybytek Pana bowiem, który Mojżesz zbudował na pustyni, oraz ołtarz całopalenia były w tym czasie na wyżynie w Gibeonie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 30, 'Lecz Dawid nie mógł iść do niego, aby radzić się Boga, gdyż bał się miecza Anioła Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 1, 'Wtedy Dawid powiedział: To jest dom Pana Boga i to jest ołtarz całopalenia dla Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 2, 'Dawid rozkazał zgromadzić cudzoziemców, którzy byli w ziemi Izraela, i ustanowił spośród nich kamieniarzy do obróbki kamieni ciosanych na budowę domu Bożego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 3, 'Dawid przygotował też bardzo dużo żelaza na gwoździe do drzwi w bramach i na spojenie oraz niezliczoną wagę brązu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 4, 'Także drzewa cedrowego niezliczoną ilość, bo Sydończycy i Tyryjczycy przywieźli Dawidowi bardzo wiele drewna cedrowego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 5, 'Dawid powiedział: Salomon, mój syn, jest młody i niedoświadczony, a dom, który ma być zbudowany dla Pana, musi być niezmiernie okazały, aby był znany i sławny we wszystkich krajach. Teraz więc poczynię przygotowania za niego. I wiele przygotował Dawid przed swoją śmiercią.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 6, 'Potem zawołał swego syna Salomona i nakazał mu zbudować dom dla Pana, Boga Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 7, 'I Dawid powiedział do Salomona: Synu mój! Pragnąłem zbudować dom dla imienia Pana, swego Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 8, 'Lecz doszło do mnie słowo Pana mówiące: Rozlałeś wiele krwi i prowadziłeś wielkie wojny. Nie będziesz budował domu dla mojego imienia, ponieważ rozlałeś wiele krwi na ziemię przed moim obliczem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 9, 'Oto urodzi ci się syn, który będzie człowiekiem pokoju, bo dam mu odpoczynek od wszystkich jego wrogów wokoło. Będzie miał na imię Salomon, ponieważ za jego dni dam Izraelowi pokój i odpoczynek.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 10, 'On zbuduje dom dla mojego imienia i on będzie mi synem, a ja będę mu ojcem i utwierdzę tron jego królestwa nad Izraelem na wieki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 11, 'Teraz więc, mój synu, niech Pan będzie z tobą i niech ci się powodzi, abyś zbudował dom dla Pana, swego Boga, jak zapowiedział o tobie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 12, 'Oby tylko Pan ci dał roztropność i rozwagę i niech cię ustanowi nad Izraelem, abyś strzegł prawa Pana, swego Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 13, 'Wtedy będzie ci się powodziło, jeśli będziesz strzegł i wypełniał przykazania i prawa, które Pan dał Mojżeszowi dla Izraela. Bądź silny i mężny, nie bój się ani się lękaj.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 14, 'A oto w moim trudzie przygotowałem na dom Pana sto tysięcy talentów złota i tysiąc tysięcy talentów srebra, brązu i żelaza zaś bez wagi, bo tego jest wiele. Przygotowałem również drewno i kamień, a ty możesz do tego dokładać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 15, 'Masz też u siebie wielu rzemieślników, kamieniarzy, murarzy, cieśli i wszelkich biegłych w każdym rzemiośle.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 16, 'Złota, srebra, brązu i żelaza jest bez liku. Wstań więc i działaj, a Pan niech będzie z tobą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 17, 'Dawid też nakazał wszystkim książętom Izraela, aby pomagali jego synowi Salomonowi;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 18, 'Mówiąc: Czy Pan, wasz Bóg, nie jest z wami? Czy nie dał wam odpoczynku wokoło? Dał bowiem w moją rękę mieszkańców tej ziemi, a ziemia została poddana Panu i jego ludowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 19, 'Teraz więc oddajcie swoje serce i swoją duszę ku szukaniu Pana, waszego Boga. Wstańcie i budujcie świątynię Pana Boga, abyście mogli tam wnieść arkę przymierza Pana oraz święte naczynia Boga, do domu, który będzie zbudowany dla imienia Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 1, 'Gdy więc Dawid był już stary i syty dni, ustanowił swego syna Salomona królem nad Izraelem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 2, 'I zgromadził wszystkich książąt Izraela oraz kapłanów i Lewitów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 3, 'Lewitów policzono od trzydziestu lat wzwyż, a ich liczba według głów wynosiła trzydzieści osiem tysięcy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 4, 'Spośród nich dwadzieścia cztery tysiące ustanowiono na służbę w domu Pana, a urzędników i sędziów było sześć tysięcy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 5, 'Ponadto – cztery tysiące odźwiernych i cztery tysiące chwalących Pana na instrumentach, które sporządziłem – powiedział Dawid – ku uwielbieniu Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 6, 'Dawid podzielił ich na zmiany według synów Lewiego: Gerszona, Kehata i Merariego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 7, 'Z Gerszona byli Ladan i Szimei.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 8, 'Synowie Ladana: pierwszy Jechiel, potem Zetam i Joel – ci trzej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 9, 'Synowie Szimejego: Szelomit, Chaziel i Haran – ci trzej byli naczelnikami rodów Ladana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 10, 'A synowie Szimejego: Jachat, Zina, Jeusz i Beria. Ci czterej byli synami Szimejego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 11, 'Jachat był pierwszy, a Ziza drugi. Ale Jeusz i Beria nie mieli wielu synów i dlatego zostali policzeni jako jeden ród.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 12, 'Synowie Kehata: Amram, Ishar, Chebron i Uzziel – czterej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 13, 'Synowie Amrama: Aaron i Mojżesz. Lecz Aaron został odłączony, aby poświęcić najświętsze rzeczy, on i jego synowie, aż na wieki – by spalać kadzidło przed Panem, służyć mu i błogosławić w jego imieniu na wieki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 14, 'Ale synowie Mojżesza, męża Bożego, zostali zaliczeni do pokolenia Lewiego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 15, 'Synowie Mojżesza: Gerszon i Eliezer.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 16, 'Synowie Gerszona: pierwszy Szebuel.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 17, 'Synowie Eliezera: pierwszy Rechabiasz. Eliezer nie miał innych synów, ale synowie Rechabiasza bardzo się rozmnożyli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 18, 'Synowie Ishara: pierwszy Szelomit.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 19, 'Synowie Chebrona: pierwszy Jeriasz, drugi Amariasz, trzeci Jachaziel, a czwarty Jekameam.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 20, 'Synowie Uzziela: pierwszy Mika i drugi Jeszijasz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 21, 'Synowie Merariego: Machli i Muszi. Synowie Machliego: Eleazar i Kisz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 22, 'I Eleazar umarł, nie mając synów, tylko córki. Pojęli je za żony synowie Kisza, ich bracia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 23, 'Synowie Musziego: Machli, Eder i Jeremot – trzej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 24, 'To są synowie Lewiego według swych rodów, głów rodzin, policzeni według liczby imion, głowa po głowie, którzy pełnili służbę w domu Pana od lat dwudziestu wzwyż.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 25, 'Dawid bowiem powiedział: Pan, Bóg Izraela, dał odpoczynek swemu ludowi i będzie mieszkał w Jerozolimie na wieki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 26, 'A Lewici już nie będą nosić przybytku ani wszelkich jego naczyń do jego obsługi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 27, 'Według ostatnich postanowień Dawida Lewici zostali policzeni od lat dwudziestu wzwyż;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 28, 'Ich stanowisko bowiem polegało na posługiwaniu synom Aarona w służbie domu Pana: na dziedzińcach, w komnatach, przy oczyszczaniu wszelkich rzeczy poświęconych i przy pracy wokół służby domu Bożego;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 29, 'I przy chlebie pokładnym, przy mące na ofiarę z pokarmów, przy plackach niekwaszonych, przy tym, co pieczone, i tym, co smażone, i przy wszystkim, co ważone i mierzone.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 30, 'Mieli stawać każdego poranka, by dziękować Panu i wychwalać go, i tak samo wieczorem;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 31, 'Ponadto, mieli składać Panu wszelkie całopalenia w każdy szabat, w czasie nowiu księżyca i w uroczyste święta, według liczby wynikającej z ustalonego porządku – ustawicznie przed Panem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 32, 'I mieli pełnić straż przy Namiocie Zgromadzenia, straż przy świątyni i straż przy synach Aarona, swych braci, w służbie domu Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 1, 'A oto podział synów Aarona. Synami Aarona byli: Nedab, Abihu, Eleazar i Itamar;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 2, 'Ale Nadab i Abihu umarli przed swoim ojcem i nie mieli synów, dlatego Eleazar i Itamar sprawowali urząd kapłański.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 3, 'I Dawid podzielił ich, to jest Sadoka z synów Eleazara i Achimeleka z synów Itamara, według ich urzędu w ich służbie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 4, 'I okazało się, że spośród synów Eleazara było więcej naczelników niż spośród synów Itamara. Tak więc ich podzielono: spośród synów Eleazara było szesnastu naczelników według rodów, a spośród synów Itamara według rodów – ośmiu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 5, 'A zostali podzieleni przez losowanie, zarówno jedni, jak i drudzy, gdyż przełożeni świątyni i przełożeni domu Bożego byli spośród synów Eleazara, jak i spośród synów Itamara.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 6, 'A Szemajasz, syn Netaneela, pisarz z pokolenia Lewiego, spisał ich wobec króla i książąt, kapłana Sadok, Achimeleka, syna Abiatara, oraz naczelników rodów kapłańskich i lewickich. Losowano na przemian jeden dom z rodu Eleazara, drugi – z Itamara.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 7, 'Pierwszy los padł na Jehojariba, drugi na Jedajasza;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 8, 'Trzeci na Charima, czwarty na Seorima;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 9, 'Piąty na Malkiasza, szósty na Mijamina;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 10, 'Siódmy na Hakkosa, ósmy na Abiasza;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 11, 'Dziewiąty na Jeszuę, dziesiąty na Szekaniasza;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 12, 'Jedenasty na Eliasziba, dwunasty na Jakima;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 13, 'Trzynasty na Chuppę, czternasty na Jeszebaba;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 14, 'Piętnasty na Bilgę, szesnasty na Immera;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 15, 'Siedemnasty na Chezira, osiemnasty na Happisesa;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 16, 'Dziewiętnasty na Petachiasza, dwudziesty na Ezechiela;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 17, 'Dwudziesty pierwszy na Jachina, dwudziesty drugi na Gamula;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 18, 'Dwudziesty trzeci na Delajasza, dwudziesty czwarty na Maazjasza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 19, 'Taka była kolejność w służbie, aby wchodzili do domu Pana zgodnie z ustaleniem, jakie pochodziło od ich ojca Aarona, jak mu rozkazał Pan, Bóg Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 20, 'A pozostali z synów Lewiego to: z synów Amrama – Szubael; z synów Szubaela – Jechdejasz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 21, 'Z Rechabiasza: z synów Rechabiasza pierwszym był Jisziasz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 22, 'Z Ishara – Szelomit; z synów Szelomita – Jachat.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 23, 'A synowie Chebrona: pierwszy Jeriasz, drugi Amariasz, trzeci Jachaziel, czwarty Jekameam.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 24, 'Synowie Uzziela: Mika; z synów Miki – Szamir.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 25, 'Brat Miki: Jisziasz; z synów Jisziasza – Zachariasz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 26, 'Synowie Merariego: Machli i Muszi; synowie Jaazjasza: Beno.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 27, 'Synowie Merariego z Jaazjasza: Beno, Szoham, Zakkur i Ibri.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 28, 'Z Machliego: Eleazar, który nie miał synów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 29, 'Z Kisza, synowie Kisza: Jerachmeel.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 30, 'A synowie Musziego: Machli, Eder i Jerimot. Ci byli synami Lewitów według ich rodów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 31, 'Oni również rzucali losy tak samo jak ich bracia, synowie Aarona, przed królem Dawidem, Sadokiem, Achimelekiem oraz naczelnikami rodów kapłańskich i lewickich – naczelnicy rodów na równi z młodszymi ich braćmi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 1, 'Dawid wraz z dowódcami wojska przydzielił do służby synów Asafa, Hemana i Jedutuna, którzy mieli prorokować przy harfach, cytrach i cymbałach. A oto liczba pełniących tę służbę:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 2, 'Z synów Asafa – Zakkur, Józef, Netaniasz i Asarela. Synowie Asafa zależni od Asafa, który prorokował pod kierownictwem króla.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 3, 'Z Jedutuna – synowie Jedutuna: Gedaliasz, Seri, Jeszajasz, Chaszabiasz, Mattitiasz i Szimei, sześciu, pod kierunkiem ich ojca Jedutuna, który prorokował przy harfie, dziękując Panu i wychwalając go.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 4, 'Z Hemana – synowie Hemana: Bukkiasz, Mattaniasz, Uzziel, Szebuel, Jerimot, Chananiasz, Chanani, Eliata, Giddalti, Romamtiezer, Joszbekasza, Malloti, Hotir i Machaziot.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 5, 'Ci wszyscy byli synami Hemana, widzącego królewskiego w słowach Bożych, dla podnoszenia rogu. I Bóg dał Hemanowi czternastu synów i trzy córki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 6, 'Ci wszyscy byli pod kierownictwem swego ojca, przeznaczeni do śpiewu w domu Pana przy cymbałach, cytrach i harfach, do służby w domu Bożym, tak jak król rozkazał Asafowi, Jedutunowi i Hemanowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 7, 'A liczba ich wraz z ich braćmi wyćwiczonymi w pieśniach Pana, wszystkich uzdolnionych, wynosiła dwieście osiemdziesiąt osiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 8, 'I rzucali losy co do swej służby, tak mały, jak i wielki, tak mistrz, jak i uczeń.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 9, 'Pierwszy los padł na Asafa i na Józefa, drugi – na Gedaliasza wraz z jego braćmi i synami, razem było ich dwunastu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 10, 'Trzeci – na Zakkura, na jego synów i braci, razem dwunastu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 11, 'Czwarty – na Jisriego, na jego synów i braci, razem dwunastu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 12, 'Piąty – na Netaniasza, na jego synów i braci, razem dwunastu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 13, 'Szósty – na Bukkiasza, na jego synów i braci, razem dwunastu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 14, 'Siódmy – na Jesarela, na jego synów i braci, razem dwunastu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 15, 'Ósmy – na Jeszajasza, na jego synów i braci, razem dwunastu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 16, 'Dziewiąty – na Mattaniasza, na jego synów i braci, razem dwunastu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 17, 'Dziesiąty – na Szimejego, na jego synów i braci, razem dwunastu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 18, 'Jedenasty – na Azarela, na jego synów i braci, razem dwunastu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 19, 'Dwunasty – na Chaszabiasza, na jego synów i braci, razem dwunastu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 20, 'Trzynasty – na Szubaela, na jego synów i braci, razem dwunastu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 21, 'Czternasty – na Mattitiasza, na jego synów i braci, razem dwunastu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 22, 'Piętnasty – na Jeremota, na jego synów i braci, razem dwunastu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 23, 'Szesnasty – na Chananiasza, na jego synów i braci, razem dwunastu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 24, 'Siedemnasty – na Joszbekasza, na jego synów i braci, razem dwunastu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 25, 'Osiemnasty – na Chananiego, na jego synów i braci, razem dwunastu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 26, 'Dziewiętnasty – na Mallotiego, na jego synów i braci, razem dwunastu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 27, 'Dwudziesty – na Eliatę, na jego synów i braci, razem dwunastu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 28, 'Dwudziesty pierwszy – na Hotira, na jego synów i braci, razem dwunastu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 29, 'Dwudziesty drugi – na Giddaltiego, na jego synów i braci, razem dwunastu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 30, 'Dwudziesty trzeci – na Machaziota, na jego synów i braci, razem dwunastu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 31, 'Dwudziesty czwarty – na Romamtiezera, na jego synów i braci, razem dwunastu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 1, 'Co do zmiany odźwiernych: z Korachitów był Meszelemiasz, syn Koracha, z synów Asafa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 2, 'A z synów Meszelemiasza: pierworodny Zachariasz, drugi Jediael, trzeci Zebadiasz, czwarty Jatniel;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 3, 'Piąty Elam, szósty Jehochanan, siódmy Elioenaj.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 4, 'A z synów Obed-Edoma: pierworodny Szemajasz, drugi Jehozabad, trzeci Joach, czwarty Sakar, piąty Netaneel;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 5, 'Szósty Ammiel, siódmy Issachar, ósmy Peulletaj. Bóg bowiem mu błogosławił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 6, 'Również jego synowi Szemajaszowi urodzili się synowie, którzy rządzili swoim rodem. Byli bowiem bardzo dzielnymi ludźmi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 7, 'Synowie Szemajasza: Otni, Rafael, Obed, Elzabad i ich bracia, ludzie mocni – Elihu i Semakiasz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 8, 'Wszyscy ci byli z synów Obed-Edoma, oni, ich synowie i bracia, mężczyźni bardzo mocni i zdolni do służby, razem sześćdziesięciu dwóch z Obed-Edoma.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 9, 'I Meszelemiasz miał synów i braci, ludzi mocnych – osiemnastu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 10, 'Również Chosa, który był z synów Merariego, miał synów: Szimri zwierzchnik, bo chociaż nie był pierworodnym, jego ojciec ustanowił go zwierzchnikiem;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 11, 'Drugi Chilkiasz, trzeci Tebaliasz, czwarty Zachariasz. Wszystkich synów i braci Chosy było trzynastu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 12, 'Spośród nich wyznaczono zmiany odźwiernych, spośród naczelników, którzy pełnili straż na przemian ze swoimi braćmi przy służbie w domu Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 13, 'I rzucali losy o każdą bramę, tak mały, jak i wielki, według swoich rodów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 14, 'Los dla Szelemiasza padł na stronę wschodnią. Potem rzucili los dla jego syna Zachariasza, mądrego doradcy, i jego los padł na stronę północną;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 15, 'Dla Obed-Edoma – na południową, a jego synom przypadła składnica.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 16, 'Dla Szuppima i Chosy – na stronę zachodnią wraz z bramą Szalleket, przy drodze wiodącej ku górze, straż naprzeciw straży.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 17, 'Od wschodu było sześciu Lewitów, od północy czterech na dzień, od południa czterech na dzień i przy składnicy po dwóch.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 18, 'Przy Parbar na zachodzie: czterech przy drodze, a dwóch przy Parbar.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 19, 'Takie są zmiany odźwiernych spośród synów Koracha i spośród synów Merariego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 20, 'A z pozostałych Lewitów Achiasz postawiony był nad skarbcami domu Bożego i nad skarbcami rzeczy poświęconych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 21, 'Synowie Ladana, którzy byli z synów Gerszonity: z Ladana Gerszonity naczelnicy rodów, Jechiel.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 22, 'Synowie Jechiela: Zetam i jego brat Joel; oni byli postawieni nad skarbcami domu Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 23, 'Spośród Amramitów, Isharytów, Chebronitów i Uzzielitów:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 24, 'Szebuel, syn Gerszoma, syna Mojżesza, przełożony nad skarbcami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 25, 'A jego bracia, od strony Eliezera, to: jego syn Rechabiasz, jego syn Jeszajasz, jego syn Joram, jego syn Zikri i jego syn Szelomit.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 26, 'Szelomit i jego bracia byli postawieni nad wszystkimi skarbcami rzeczy poświęconych, które poświęcił król Dawid, naczelnicy rodów, tysiącznicy, setnicy i dowódcy wojska.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 27, 'To, co zdobyli z wojen i łupów, poświęcali na utrzymanie domu Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 28, 'I wszystko, co poświęcił Samuel, widzący, a także Saul, syn Kisza, Abner, syn Nera, i Joab, syn Serui, oraz wszystko, co zostało poświęcone, było pod opieką Szelomita i jego braci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 29, 'Spośród Isharytów: Kenaniasz i jego synowie zajmowali się sprawami zewnętrznymi Izraela jako urzędnicy i sędziowie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 30, 'Spośród Chebronitów: Chaszabiasz i jego bracia, ludzie dzielni, było ich tysiąc siedemset przełożonych nad Izraelem po zachodniej stronie Jordanu, odpowiadali za każdą sprawę Pana i służbę dla króla.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 31, 'Spośród Chebronitów pochodził Jeriasz, naczelnik Chebronitów, według rodowodów jego ojców. W czterdziestym roku panowania Dawida szukano i znaleziono pośród nich bardzo dzielnych ludzi w Jazer w Gileadzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 32, 'A jego braci, ludzi dzielnych, było dwa tysiące siedmiuset naczelników rodów, których król Dawid ustanowił zwierzchnikami nad Rubenitami, nad Gadytami i nad połową pokolenia Manassesa, by byli odpowiedzialni za wszystkie sprawy Boże i sprawy króla.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 1, 'A oto synowie Izraela według ich liczby: naczelnicy rodów, tysiącznicy, setnicy i urzędnicy, którzy służyli królowi we wszelkiej sprawie związanej z oddziałami przychodzącymi i odchodzącymi co miesiąc, przez wszystkie miesiące w roku. Każdy oddział liczył dwadzieścia cztery tysiące.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 2, 'Nad oddziałem w miesiącu pierwszym stał Jaszobeam, syn Zabdiela, a jego oddział liczył dwadzieścia cztery tysiące.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 3, 'On pochodził z synów Peresa, a był wodzem wszystkich dowódców wojska w miesiącu pierwszym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 4, 'Nad oddziałem w miesiącu drugim stał Dodaj, Achochita. Po nim dowódcą był Miklot, a jego oddział liczył dwadzieścia cztery tysiące.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 5, 'Trzecim dowódcą wojska, na miesiąc trzeci, był Benajasz, syn Jehojady, naczelnego kapłana, a jego oddział liczył dwadzieścia cztery tysiące.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 6, 'Ten to Benajasz był waleczny wśród trzydziestu i dowodził trzydziestoma, a jego syn Ammizabad należał do jego oddziału.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 7, 'Czwartym dowódcą, na miesiąc czwarty, był Asahel, brat Joaba, a po nim jego syn Zebadiasz – jego oddział liczył dwadzieścia cztery tysiące.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 8, 'Piątym dowódcą, na piąty miesiąc, był Szamhut Jizrachita, a jego oddział liczył dwadzieścia cztery tysiące.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 9, 'Szóstym, na miesiąc szósty, był Ira, syn Ikkesza Tekoitczyka, a jego oddział liczył dwudziestu czterech.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 10, 'Siódmym, na miesiąc siódmy, był Cheles Pelonita, z synów Efraima, a jego oddział liczył dwadzieścia cztery tysiące.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 11, 'Ósmym, na miesiąc ósmy, był Sibbekaj Chuszatyta, z Zerachitów, a jego oddział liczył dwadzieścia cztery tysiące.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 12, 'Dziewiątym, na miesiąc dziewiąty, był Abiezer Anatotczyk, z synów Beniamina, a jego oddział liczył dwadzieścia cztery tysiące.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 13, 'Dziesiątym, na miesiąc dziesiąty, był Maharaj Netofatyta, z Zerachitów, a jego oddział liczył dwadzieścia cztery tysiące.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 14, 'Jedenastym, na miesiąc jedenasty, był Benajasz Piratończyk, z synów Efraima, a jego oddział liczył dwadzieścia cztery tysiące.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 15, 'Dwunastym, na miesiąc dwunasty, był Cheldaj Netofatyta, z Otniela, a jego oddział liczył dwadzieścia cztery tysiące.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 16, 'Ponadto nad pokoleniami Izraela postawieni byli: nad Rubenitami przełożonym był Eliezer, syn Zikriego; nad Symeonitami – Szefatiasz, syn Maaki;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 17, 'Nad Lewitami – Chaszabiasz, syn Kemuela, nad Aaronitami – Sadok;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 18, 'Nad Judą – Elihu, jeden z braci Dawida, nad Issacharytami – Omri, syn Mikaela;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 19, 'Nad Zebulonitami – Jiszmajasz, syn Obadiasza, nad Neftalitami – Jerimot, syn Azriela;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 20, 'Nad synami Efraima – Ozeasz, syn Azazjasza, nad połową pokolenia Manassesa – Joel, syn Pedajasza;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 21, 'Nad drugą połową pokolenia Manassesa w Gileadzie – Iddo, syn Zachariasza, nad Beniaminatami – Jaasiel, syn Abnera.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 22, 'Nad Danitami – Azareel, syn Jerochama. Ci byli książętami pokoleń Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 23, 'Dawid nie włączył jednak do spisu nikogo, kto miał dwadzieścia lat lub mniej. Pan powiedział bowiem, że rozmnoży Izraela jak gwiazdy na niebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 24, 'Joab, syn Serui, zaczął ich liczyć, ale nie dokończył, gdyż za to spadł gniew na Izraela. Nie włączono więc tej liczby do spisu w kronikach króla Dawida.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 25, 'Nad skarbcami króla postawiony był Azmawet, syn Adiela; nad dochodami z pól, miast, wsi i zamków – Jonatan, syn Uzjasza;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 26, 'Nad rolnikami, którzy uprawiali ziemię, stał Ezri, syn Keluba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 27, 'Nad winnicami – Szimei Ramatczyk; nad plonami winnic w piwnicach – Zabdi Szifmita.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 28, 'Nad drzewami oliwnymi i sykomorami, które rosły na równinach, postawiony był Baalchanan Gederczyk, a nad składami oliwy – Joasz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 29, 'Nad bydłem pasącym się w Szaronie – Szitraj Szarończyk, nad bydłem zaś w dolinach – Szafat, syn Adlaja.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 30, 'Nad wielbłądami – Obil Izmaelita, nad oślicami – Jechdejasz Meronotyta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 31, 'I nad owcami – Jaziz Hagryta. Ci wszyscy byli zarządcami dobytku króla Dawida.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 32, 'Jonatan, stryj Dawida, był doradcą, człowiekiem mądrym i uczonym. Jechiel, syn Chakmoniego, był z synami króla.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 33, 'Achitofel też był doradcą króla, a Chuszaj Arkita – przyjacielem króla.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 34, 'Po Achitofelu był Jehojada, syn Benajasza, i Abiatar. Joab zaś był dowódcą wojska króla.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 1, 'Potem Dawid zgromadził w Jerozolimie wszystkich książąt Izraela, książąt pokoleń i dowódców oddziałów, którzy służyli królowi, tysiączników, setników i zarządców całego dobytku i posiadłości króla i jego synów, a także urzędników, walecznych i wszystkich dzielnych wojowników.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 2, 'Wtedy król Dawid powstał i przemówił: Słuchajcie mnie, moi bracia i ludu mój! Moim pragnieniem było zbudować dom odpoczynku dla arki przymierza Pana i jako podnóżek naszego Boga i poczyniłem przygotowania do budowy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 3, 'Lecz Bóg powiedział do mnie: Nie zbudujesz domu dla mego imienia, ponieważ jesteś wojownikiem i rozlewałeś krew.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 4, 'Wybrał mnie jednak Pan, Bóg Izraela, spośród całego domu mego ojca, abym był królem nad Izraelem na wieki. Judę bowiem wybrał na władcę, spośród rodu Judy – dom mego ojca, a spośród synów mego ojca, mnie sobie upodobał ustanowić królem nad całym Izraelem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 5, 'Spośród zaś wszystkich moich synów – wielu bowiem synów dał mi Pan – wybrał mego syna Salomona, aby zasiadł na tronie królestwa Pana nad Izraelem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 6, 'I powiedział do mnie: Salomon, twój syn – to on zbuduje mój dom i moje dziedzińce. Jego bowiem wybrałem sobie za syna, a ja mu będę ojcem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 7, 'I utwierdzę jego królestwo na wieki, jeśli podobnie jak dzisiaj będzie trwał w wypełnianiu moich przykazań i praw.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 8, 'Teraz więc na oczach całego Izraela, zgromadzenia Pana, i wobec naszego Boga nakazuję wam: Przestrzegajcie i szukajcie wszystkich przykazań Pana, waszego Boga, abyście mogli posiadać tę dobrą ziemię i zostawić ją jako dziedzictwo swoim dzieciom po was – na wieki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 9, 'A ty, Salomonie, mój synu, poznawaj Boga swego ojca i służ mu sercem doskonałym i dobrowolnym umysłem. Pan bowiem przenika wszystkie serca i zna wszystkie zamysły i myśli. Jeśli będziesz go szukać, znajdziesz go, a jeśli go opuścisz, on odrzuci cię na wieki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 10, 'Miej się teraz na baczności, gdyż Pan cię wybrał, abyś zbudował dom na świątynię; bądź mocny i wykonaj to.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 11, 'Wtedy Dawid przekazał swojemu synowi Salomonowi wzór przedsionka świątyni, jej domów, jej skarbców, jej komnat górnych, jej pomieszczeń wewnętrznych oraz domu dla przebłagalni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 12, 'Do tego wzór wszystkiego, co zaplanował: dziedzińców domu Pana, wszystkich komnat dokoła oraz wszystkich skarbców domu Bożego i skarbców rzeczy poświęconych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 13, 'Także wskazówki co do zmian kapłańskich i lewickich, wszelkiej pracy w służbie domu Pana i co do wszelkich naczyń służby w domu Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 14, 'Dał także odpowiednią wagę złota na wszystkie naczynia złote do każdej posługi; również odpowiednią wagę srebra na wszystkie naczynia srebrne, na wszystkie naczynia do wszelkich posług;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 15, 'Mianowicie odpowiednią wagę na świeczniki złote i ich lampy złote według wagi każdego świecznika i jego lamp, i na świeczniki srebrne według wagi każdego świecznika i jego lamp, stosownie do użycia każdego świecznika.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 16, 'Również dał odpowiednią wagę złota na stoły chlebów pokładnych, na każdy stół, oraz srebra – na stoły srebrne;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 17, 'I szczere złoto na widełki, miednice i kubki, na czasze złote, określoną wagę na każdy z tych przedmiotów i na czasze srebrne – określoną wagę na każdą z nich;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 18, 'Także na ołtarz kadzenia dał określoną wagę szczerego złota oraz złoto na wzór wozu cherubinów, którzy swoimi rozpostartymi skrzydłami okrywali arkę przymierza Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 19, 'To wszystko – powiedział Dawid – przyszło do mnie na piśmie z ręki Pana, abym mógł zrozumieć, jak wykonać ten plan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 20, 'Dawid powiedział do swego syna Salomona: Bądź mocny i dzielny i wykonaj to. Nie bój się ani się nie lękaj, bo Pan Bóg, mój Bóg, będzie z tobą, nie porzuci cię ani nie opuści, dopóki nie dokończysz wszelkiej pracy wokół służby domu Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 21, 'A oto zmiany kapłanów i Lewitów do każdej posługi w domu Bożym będą z tobą w każdej pracy; każdy ochotny i zdolny do wszelkiej posługi. Także książęta i cały lud stawią się na każdy twój rozkaz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 1, 'Potem król Dawid przemówił do całego zgromadzenia: Mój syn Salomon, jedyny, którego Bóg wybrał, jest jeszcze młody i niedoświadczony, a dzieło jest wielkie. Ten pałac bowiem nie jest dla człowieka, ale dla Pana Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 2, 'Według wszystkich swoich sił przygotowałem na dom swojego Boga złoto na przedmioty złote, srebro – na srebrne, brąz – na brązowe, żelazo – na żelazne, drewno – na drewniane, kamienie onyksowe i do osadzania, kamienia błyszczące i różnokolorowe, wszelkiego rodzaju drogie kamienie i marmur w obfitości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 3, 'Ponadto z miłości do domu swego Boga oddaję ze swojego skarbca na dom mego Boga złota i srebra – poza tym wszystkim, co już przygotowałem na święty dom;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 4, 'Mianowicie trzy tysiące talentów złota, złota z Ofiru, i siedem tysięcy talentów najczystszego srebra na pokrycie ścian budynków;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 5, 'Złoto – na przedmioty złote, a srebro – na srebrne i na wszelkie ręczne prace rzemieślników. A kto jeszcze chciałby dziś dobrowolnie złożyć Panu dar?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 6, 'Wtedy dobrowolne dary złożyli naczelnicy rodów, książęta pokoleń Izraela, tysiącznicy, setnicy oraz przełożeni nad robotami króla.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 7, 'I złożyli na służbę domu Bożego pięć tysięcy talentów złota, dziesięć tysięcy darejków, dziesięć tysięcy talentów srebra, osiemnaście tysięcy talentów brązu oraz sto tysięcy talentów żelaza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 8, 'Ci, którzy mieli drogie kamienie, oddali je do skarbca domu Pana na rękę Jechiela Gerszonity.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 9, 'I radował się lud z tego, że tak dobrowolnie złożono dary, gdyż sercem doskonałym, chętnie ofiarowywano Panu. Także i król Dawid wielce się radował.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 10, 'Dawid więc błogosławił Panu przed całym zgromadzeniem i powiedział: Błogosławiony jesteś, Panie, Boże Izraela, naszego ojca, na wieki wieków.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 11, 'Twoja, Panie, jest wielkość, moc, chwała, zwycięstwo i majestat. Wszystko bowiem, co jest na niebie i na ziemi, jest twoje. Do ciebie należy królestwo, a ty jako głowa jesteś wyniesiony ponad wszystko.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 12, 'I bogactwo, i sława pochodzą od ciebie i ty panujesz nad wszystkimi; w twoich rękach jest moc i siła i w twojej ręce jest to, aby wywyższyć i umocnić wszystko.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 13, 'Teraz więc, Boże nasz, dziękujemy ci i wychwalamy chwalebne imię twoje.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 14, 'Lecz kim ja jestem i czym jest mój lud, żebyśmy zdołali ofiarować dobrowolnie te rzeczy? Od ciebie bowiem pochodzi wszystko i daliśmy tobie to, co z twojej ręki otrzymaliśmy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 15, 'Jesteśmy bowiem pielgrzymami i przychodniami przed tobą, tak jak wszyscy nasi ojcowie. Nasze dni na ziemi są jak cień i nie ma czego oczekiwać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 16, 'O Panie, Boże nasz, cały ten dostatek, który przygotowaliśmy dla ciebie na budowę domu dla twojego świętego imienia, pochodzi z twojej ręki i twoje jest to wszystko.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 17, 'Wiem ja, mój Boże, że badasz serca i upodobałeś sobie prawość. Dlatego w prawości swego serca dobrowolnie złożyłem w ofierze to wszystko. Teraz z radością widzę, że również twój lud, który znajduje się tutaj, dobrowolnie składa ci ofiary.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 18, 'Panie, Boże Abrahama, Izaaka i Izraela, naszych ojców, zachowaj na wieki te zamiary i myśli serca swego ludu i skłoń jego serca ku sobie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 19, 'Salomonowi, mojemu synowi, daj serce doskonałe, aby strzegł twoich przykazań, świadectw i ustaw, aby wykonał to wszystko i aby zbudował dom, do którego poczyniłem przygotowania.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 20, 'Potem Dawid przemówił do całego zgromadzenia: Błogosławcie teraz Panu, waszemu Bogu. I całe zgromadzenie błogosławiło Panu, Bogu swoich ojców – pochylili się i oddali pokłon Panu i królowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 21, 'Następnie złożyli Panu ofiary. Nazajutrz złożyli Panu całopalenia: tysiąc wołów, tysiąc baranów, tysiąc jagniąt wraz z ofiarami z płynów i mnóstwem innych ofiar, za całego Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 22, 'Jedli i pili przed Panem tego dnia z wielką radością. I po raz drugi ustanowili królem Salomona, syna Dawida, i namaszczali go dla Pana na władcę, a Sadoka na kapłana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 23, 'Tak więc zasiadł Salomon na tronie Pana jako król po swoim ojcu Dawidzie i powodziło mu się, a cały Izrael był mu posłuszny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 24, 'Również wszyscy książęta i dzielni ludzie, a także wszyscy synowie króla Dawida poddali się królowi Salomonowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 25, 'I Pan wielce wywyższył Salomona przed całym Izraelem i dał mu chwałę królewską, jakiej żaden król przed nim nie miał w Izraelu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 26, 'Tak to Dawid, syn Jessego, królował nad całym Izraelem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 27, 'A czas jego panowania nad Izraelem wynosił czterdzieści lat: w Hebronie królował siedem lat, a w Jerozolimie królował trzydzieści trzy lata.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 28, 'I umarł w późnej starości, syty dni, bogactw i sławy. A w jego miejsce królował Salomon, jego syn.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 29, 'A dzieje króla Dawida, pierwsze i ostatnie, oto zapisane są w księdze Samuela widzącego, w księdze proroka Natana i w księdze Gada widzącego;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 30, 'Wraz z całym jego panowaniem, jego potęgą i wydarzeniami, które dotyczyły jego, Izraela i wszystkich królestw tej ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 1, 'Salomon, syn Dawida, umocnił się w swoim królestwie, a Pan, jego Bóg, był z nim i bardzo go wywyższył.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 2, 'I Salomon przemówił do całego Izraela, do dowódców nad tysiącami, setników i sędziów oraz wszystkich przełożonych nad całym Izraelem, naczelników rodów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 3, 'Salomon więc poszedł, a z nim całe zgromadzenie, na wyżynę, która była w Gibeonie. Tam bowiem znajdował się Namiot Zgromadzenia Bożego, który sporządził Mojżesz, sługa Pana, na pustyni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 4, 'Ale arkę Boga przeniósł Dawid z Kiriat-Jearim na miejsce, które dla niej przygotował, bo rozbił namiot dla niej w Jerozolimie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 5, 'A także ołtarz z brązu, który zrobił Besaleel, syn Uriego, syna Chura, znajdował się tam przed przybytkiem Pana. I tam udał się po radę Salomon oraz całe zgromadzenie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 6, 'I Salomon przystąpił przed Panem do ołtarza z brązu, który był przed Namiotem Zgromadzenia, i złożył na nim tysiąc ofiar całopalnych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 7, 'Tej samej nocy Bóg ukazał się Salomonowi i powiedział do niego: Proś, o co chcesz, a dam tobie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 8, 'Wtedy Salomon powiedział do Boga: Ty okazałeś mojemu ojcu Dawidowi wielkie miłosierdzie i ustanowiłeś mnie królem w jego miejsce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 9, 'A teraz, Panie Boże, niech się spełni twoje słowo, które powiedziałeś do mego ojca Dawida, bo uczyniłeś mnie królem nad ludem, który jest tak liczny, jak proch ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 10, 'Daj mi więc mądrość i wiedzę, abym wychodził i wchodził przed tym ludem; któż bowiem zdoła sądzić ten twój lud, który jest tak wielki?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 11, 'Wtedy Bóg powiedział do Salomona: Ponieważ było to w twoim sercu, a nie prosiłeś o bogactwo, majętności i sławę ani o śmierć tych, którzy cię nienawidzą, ani też nie prosiłeś o długie życie, ale prosiłeś dla siebie o mądrość i wiedzę, abyś mógł sądzić mój lud, nad którym ustanowiłem cię królem;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 12, 'Mądrość i umiejętność będzie ci dana, ponadto dam ci bogactwo, majętności i sławę, jakich nie miał żaden z królów, którzy byli przed tobą, ani nie będzie miał żaden z tych, którzy po tobie nastąpią.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 13, 'Salomon wrócił z tej wyżyny, która była w Gibeonie, sprzed Namiotu Zgromadzenia, do Jerozolimy i królował nad Izraelem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 14, 'I Salomon zgromadził rydwany i jeźdźców, tak że miał tysiąc czterysta rydwanów i dwanaście tysięcy jeźdźców, których rozmieścił w miastach rydwanów i przy sobie w Jerozolimie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 15, 'Król złożył w Jerozolimie złota i srebra, jak kamieni, a cedrów złożył jak sykomor, których na równinie rośnie bardzo dużo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 16, 'Sprowadzono też dla Salomona konie z Egiptu i nić lnianą, bo kupcy króla nabywali ją za określoną cenę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 17, 'I wychodzili, i przywozili z Egiptu rydwan za sześćset syklów srebra, a konia za sto pięćdziesiąt. W ten sposób wszyscy królowie chetyccy i królowie Syrii dostawali je za ich pośrednictwem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 1, 'Wtedy Salomon postanowił zbudować dom dla imienia Pana oraz pałac królewski dla siebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 2, 'I odliczył Salomon siedemdziesiąt tysięcy mężczyzn do noszenia ciężarów i osiemdziesiąt tysięcy mężczyzn do ciosania na górze, a nad nimi – trzy tysiące sześciuset nadzorców.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 3, 'Salomon posłał też do Hurama, króla Tyru, wiadomość: Jak postąpiłeś z moim ojcem Dawidem, gdy przysłałeś mu drzewa cedrowego, aby zbudował sobie dom na mieszkanie, tak postąp ze mną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 4, 'Oto chcę budować dom dla imienia Pana, swego Boga, aby mu go poświęcić i aby palić przed nim wonne kadzidło, składać nieustannie chleb pokładny oraz całopalenia poranne i wieczorne – w szabaty, w dni nowiu oraz w uroczyste święta Pana, naszego Boga. To jest wieczny nakaz w Izraelu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 5, 'A dom, który mam zbudować, będzie wielki, gdyż nasz Bóg jest większy od wszystkich bogów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 6, 'Któż jednak zdoła zbudować mu dom, skoro niebiosa i niebiosa niebios nie mogą go ogarnąć? A kim jestem ja, żebym miał mu dom zbudować? Chyba tylko do palenia przed nim kadzidła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 7, 'Dlatego więc przyślij mi teraz człowieka uzdolnionego w obróbce złota, srebra, brązu, żelaza, purpury, karmazynu i błękitu, i który umie rzeźbić wraz z innymi rzemieślnikami będącymi przy mnie w Judzie i Jerozolimie, wyznaczonymi przez mego ojca Dawida.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 8, 'Przyślij mi też z Libanu drzewa cedrowego, cyprysowego i sandałowego, bo wiem, że twoi słudzy umieją rąbać drzewa w Libanie, a oto moi słudzy będą z twoimi sługami;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 9, 'Aby przygotowali mi jak najwięcej drzewa. Dom bowiem, który chcę zbudować, ma być nad podziw wielki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 10, 'A oto twoim sługom, robotnikom, którzy mają wycinać drzewo, dam dwadzieścia tysięcy kor wymłóconej pszenicy, dwadzieścia tysięcy kor jęczmienia, dwadzieścia tysięcy bat wina oraz dwadzieścia tysięcy bat oliwy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 11, 'Wtedy Huram, król Tyru, odpowiedział w piśmie, które wysłał do Salomona: Ponieważ Pan umiłował swój lud, ustanowił cię nad nim królem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 12, 'Huram mówił dalej: Błogosławiony niech będzie Pan, Bóg Izraela, który uczynił niebo i ziemię, który dał królowi Dawidowi syna mądrego, zdolnego, rozumnego i roztropnego, aby zbudował dom dla Pana oraz pałac królewski dla siebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 13, 'Posyłam ci więc człowieka mądrego, zdolnego i roztropnego: Hurama-Abiego;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 14, 'Syna kobiety spośród córek Dana, którego ojcem był mieszkaniec Tyru, a który umie pracować przy złocie, srebrze, brązie, żelazie, kamieniu, drewnie – z purpurą, błękitem, bisiorem i karmazynem, który umie wykonywać wszelkie rzeźby i obmyślać każdą powierzoną mu pracę, razem z twymi rzemieślnikami i rzemieślnikami mego pana Dawida, twojego ojca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 15, 'Teraz więc niech mój pan przyśle swoim sługom pszenicę, jęczmień, oliwę i wino, o których mówił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 16, 'A my nawycinamy drzew z Libanu, ile ci będzie potrzeba, i sprowadzimy je morzem na tratwach do Jafy, a ty je każesz sprowadzić do Jerozolimy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 17, 'Wtedy Salomon obliczył wszystkich cudzoziemców, którzy byli w ziemi Izraela po tym spisie, którego dokonał jego ojciec Dawid, i znalazło się ich sto pięćdziesiąt trzy tysiące sześciuset.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 18, 'I przeznaczył z nich siedemdziesiąt tysięcy do dźwigania ciężarów, osiemdziesiąt tysięcy do ciosania w górach i trzy tysiące sześciuset nadzorców nad robotami ludu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 1, 'Wtedy Salomon zaczął budować dom Pana w Jerozolimie na górze Moria, która została wskazana Dawidowi, jego ojcu, na miejscu, które Dawid przygotował na klepisku Ornana Jebusyty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 2, 'A zaczął go budować w drugim miesiącu, drugiego dnia, w czwartym roku swojego panowania.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 3, 'Takie są wymiary, według których Salomon zbudował dom Boży: długość – sześćdziesiąt łokci, w łokciach według miary dawnej, szerokość – dwadzieścia łokci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 4, 'Przedsionek zaś, który był przed domem i odpowiadał jego szerokości, miał dwadzieścia łokci długości i sto dwadzieścia łokci wysokości. Wewnątrz pokrył go szczerym złotem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 5, 'A wnętrze wielkiego domu wyłożył drzewem cyprysowym i pokrył czystym złotem, a na wierzchu przyozdobił je palmami i łańcuchami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 6, 'Pokrył też dom drogocennymi kamieniami dla ozdoby, a złoto było złotem z Parwaim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 7, 'Ponadto złotem pokrył dom, belki, odrzwia, jego ściany i jego drzwi, a na ścianach wyrzeźbił cherubiny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 8, 'Zbudował też dom najświętszy, którego długość odpowiadała szerokość domu – dwadzieścia łokci, a jego szerokość – dwadzieścia łokci; i pokrył go czystym złotem o wadze sześciuset talentów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 9, 'Gwoździe ważyły pięćdziesiąt syklów złota. Górne sale także pokrył złotem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 10, 'Wykonał też w domu najświętszym dwa cherubiny misternie rzeźbione i pokrył je złotem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 11, 'A skrzydła cherubinów były długie na dwadzieścia łokci. Skrzydło jednego, na pięć łokci, sięgało ściany domu, a drugie skrzydło, także na pięć łokci, sięgało skrzydła drugiego cherubina.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 12, 'Także skrzydło drugiego cherubina, na pięć łokci, sięgało ściany domu, a drugie skrzydło, na pięć łokci, sięgało skrzydła drugiego cherubina.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 13, 'W ten sposób skrzydła tych cherubinów rozciągały się na dwadzieścia łokci. Stały one na swoich nogach, a ich twarze były zwrócone ku domowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 14, 'Wykonał też zasłonę z błękitu, purpury, karmazynu i bisioru oraz wyhaftował na niej cherubiny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 15, 'Uczynił też przed domem dwie kolumny wysokie na trzydzieści pięć łokci, a głowice, które były na ich wierzchach miały po pięć łokci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 16, 'Zrobił też łańcuszki, jak w Miejscu Najświętszym, a umieścił je na wierzchołkach tych kolumn, wykonał też sto jabłek granatu, które zawiesił na tych łańcuszkach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 17, 'Wzniósł te kolumny przed świątynią, jedną po prawej, a drugą po lewej stronie; prawą nazwał Jakin, a lewą – Boaz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 1, 'Uczynił też ołtarz z brązu długi na dwadzieścia łokci, szeroki na dwadzieścia łokci, a na dziesięć łokci wysoki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 2, 'Wykonał również odlewane morze na dziesięć łokci od brzegu do brzegu. Było ono dokładnie okrągłe, miało pięć łokci wysokości i trzydzieści łokci obwodu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 3, 'A pod nim dokoła znajdowały się podobizny wołów, których było po dziesięć na każdym łokciu, a otaczały morze dokoła. Były dwa rzędy tych wołów odlanych razem z morzem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 4, 'Stało ono na dwunastu wołach, z których trzy spoglądały na północ, trzy spoglądały na zachód, trzy spoglądały na południe, a trzy spoglądały na wschód. Morze stało na nich na wierzchu, a wszystkie ich zady były zwrócone do środka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 5, 'Jego grubość była na szerokość dłoni; a jego brzeg był wykonany jak brzeg kielicha, w kształcie kwiatu lilii. Mieściło w sobie trzy tysiące bat.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 6, 'Wykonał również dziesięć kadzi do obmywania w nich wszystkiego, co należało do całopalenia, i postawił pięć po prawej i pięć po lewej stronie. Ale morze służyło do obmywania się w nim kapłanów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 7, 'Uczynił też dziesięć złotych świeczników w kształcie, jaki miały mieć, i postawił je w świątyni, pięć po prawej i pięć po lewej stronie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 8, 'Uczynił też dziesięć stołów, które postawił w świątyni, pięć po prawej i pięć po lewej stronie. Wykonał też sto złotych czasz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 9, 'Zbudował również dziedziniec kapłanów i wielki dziedziniec oraz bramy do dziedzińca, a bramy pokrył brązem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 10, 'A morze postawił po prawej stronie na południowy wschód.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 11, 'Huram uczynił kociołki, łopatki i miednice. Tak ukończył Huram pracę, którą miał wykonać dla króla Salomona, dla domu Bożego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 12, 'Mianowicie: dwie kolumny z okrągłymi głowicami na wierzchu tych dwóch kolumn oraz dwie siatki, które okrywały dwie okrągłe głowice na szczycie kolumn;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 13, 'I czterysta jabłek granatu do tych dwóch siatek, po dwa rzędy jabłek granatu na każdej siatce, do pokrycia dwóch okrągłych głowic na wierzchach kolumn.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 14, 'Porobił także podstawy oraz kadzie na tych podstawach;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 15, 'Jedno morze i dwanaście wołów pod nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 16, 'Do tego kociołki, łopatki, widełki i wszystkie naczynia do nich porobił Huram-Abi dla króla Salomona, do domu Pana z polerowanego brązu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 17, 'Na równinach Jordanu król odlewał je w gliniastej ziemi, między Sukkot i Seredatą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 18, 'Salomon sporządził więc wszystkie te naczynia w tak wielkiej liczbie, że nie można było obliczyć wagi brązu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 19, 'Sporządził także Salomon wszystkie naczynia, które należały do domu Bożego: złoty ołtarz i stoły, na których składano chleby pokładne;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 20, 'Także świeczniki i ich lampy ze szczerego złota, aby je rozpalano według zwyczaju przed Miejscem Najświętszym;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 21, 'Ponadto kwiaty, lampy i szczypce ze złota, i to z wybornego złota;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 22, 'Do tego nożyce, miednice, czasze i kadzielnice ze szczerego złota; bramy do domu, bramy wewnętrzne do Najświętszego Miejsca oraz drzwi domu, czyli świątyni, ze złota.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 1, 'A tak ukończono wszelką pracę, którą wykonał Salomon dla domu Pana. I Salomon wniósł tam rzeczy, które poświęcił jego ojciec Dawid: srebro, złoto i wszystkie naczynia włożył do skarbców domu Bożego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 2, 'Potem Salomon zebrał starszych z Izraela, wszystkich naczelników z każdego pokolenia, przywódców rodów synów Izraela, w Jerozolimie, aby przenieśli arkę przymierza Pana z miasta Dawida, którym jest Syjon.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 3, 'Zebrali się więc u króla wszyscy mężczyźni Izraela na święto w siódmym miesiącu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 4, 'A gdy się zeszli wszyscy starsi z Izraela, Lewici wzięli arkę;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 5, 'I przenieśli ją, Namiot Zgromadzenia i wszystkie naczynia święte, które były w namiocie. Przenieśli je kapłani i Lewici.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 6, 'Potem król Salomon i całe zgromadzenie Izraela – zebrane u niego przed arką – złożyli w ofierze owce i woły, których nie można było zliczyć ani spisać z powodu wielkiej liczby.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 7, 'Wtedy kapłani wnieśli arkę przymierza Pana do wnętrza domu na jej miejsce, do Miejsca Najświętszego, pod skrzydła cherubinów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 8, 'Cherubiny miały bowiem rozpostarte skrzydła nad miejscem położenia arki i okrywały od góry arkę i jej drążki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 9, 'I powyciągali drążki, tak że ich końce było widać z arki przed Miejscem Najświętszym, ale nie były widoczne na zewnątrz. I są tam aż do dziś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 10, 'W arce nie było nic oprócz dwóch tablic, które Mojżesz tam włożył na Horebie, gdy Pan zawarł przymierze z synami Izraela po ich wyjściu z Egiptu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 11, 'A gdy kapłani wyszli z miejsca świętego (gdyż wszyscy kapłani, którzy byli obecni, poświęcili się, nie przestrzegając podziału na zmiany;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 12, 'Stali też Lewici śpiewacy i wszyscy, którzy byli z Asafa, Hemana, Jedutuna wraz ze swoimi synami i braćmi, ubrani w szaty z bisioru, z cymbałami, lutniami i cytrami, stali na wschodniej stronie ołtarza, a z nimi stu dwudziestu kapłanów grających na trąbach);');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 13, 'I kiedy tak zgodnie trąbili, i śpiewali, i wydawali jeden głos, chwaląc i sławiąc Pana; i gdy podnosili głos przy wtórze trąb, cymbałów i innych instrumentów muzycznych, chwaląc Pana, że jest dobry, że na wieki trwa jego miłosierdzie, wtedy dom, dom Pana, napełnił się obłokiem;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 14, 'Tak że kapłani nie mogli tam ustać, aby pełnić służbę, z powodu tego obłoku, bo chwała Pana napełniła dom Boży.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 1, 'Wtedy przemówił Salomon: Pan powiedział, że będzie mieszkać w mroku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 2, 'A ja zbudowałem dom na mieszkanie dla ciebie i miejsce twojego zamieszkania na wieki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 3, 'Potem król odwrócił się i błogosławił całemu zgromadzeniu Izraela, a całe zgromadzenie Izraela stało.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 4, 'I powiedział: Błogosławiony niech będzie Pan, Bóg Izraela, który swoimi rękami wypełnił to, co mówił swoimi ustami do mojego ojca Dawida:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 5, 'Od dnia, w którym wyprowadziłem swój lud z ziemi Egiptu, nie wybrałem żadnego miasta spośród wszystkich pokoleń Izraela, aby zbudować tam dom, gdzie przebywałoby moje imię, ani nie wybrałem żadnego mężczyzny, który byłby władcą nad moim ludem Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 6, 'Ale wybrałem Jerozolimę, aby tam przebywało moje imię; wybrałem też Dawida, aby był postawiony nad moim ludem Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 7, 'Mój ojciec Dawid postanowił w swoim sercu, że zbuduje dom dla imienia Pana, Boga Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 8, 'Ale Pan powiedział do Dawida, mego ojca: Ponieważ postanowiłeś w swoim sercu, że zbudujesz dom dla mojego imienia, dobrze uczyniłeś, że tak postanowiłeś w sercu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 9, 'Nie ty jednak będziesz budował ten dom, ale twój syn, który wyjdzie z twoich bioder, on zbuduje dom dla mojego imienia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 10, 'Pan więc wypełnił swoje słowo, które powiedział. Powstałem bowiem w miejsce Dawida, swojego ojca, i zasiadłem na tronie Izraela, tak jak Pan powiedział, i zbudowałem ten dom dla imienia Pana, Boga Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 11, 'Tam też umieściłem arkę, w której jest przymierze Pana, jakie zawarł z synami Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 12, 'Wtedy Salomon stanął przed ołtarzem Pana, przed całym zgromadzeniem Izraela, i wyciągnął swoje ręce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 13, 'Salomon bowiem uczynił podwyższenie z brązu, które postawił pośrodku dziedzińca, długie na pięć łokci, szerokie na pięć łokci i wysokie na trzy łokcie. I wstąpił na nie, uklęknął na swoich kolanach przed całym zgromadzeniem Izraela, wyciągnął ręce do nieba;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 14, 'I powiedział: Panie, Boże Izraela, nie ma Boga na niebie i na ziemi podobnego tobie, przestrzegającego przymierza i miłosierdzia wobec swoich sług, którzy postępują przed tobą całym swoim sercem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 15, 'Dotrzymałeś swojemu słudze Dawidowi, memu ojcu, tego, co mu obiecałeś; swoimi ustami to wypowiedziałeś i swoją ręką wypełniłeś, jak to jest dziś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 16, 'Teraz więc, Panie, Boże Izraela, dotrzymaj swemu słudze Dawidowi, memu ojcu, tego, co mu obiecałeś, mówiąc: Nie zabraknie ci przed moim obliczem potomka, który by zasiadał na tronie Izraela, jeśli tylko twoi synowie będą strzec swej drogi i postępować według mojego prawa, tak jak ty postępowałeś przede mną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 17, 'A teraz, Panie, Boże Izraela, niech będzie potwierdzone twoje słowo, które wypowiedziałeś do swego sługi Dawida.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 18, 'Czyż naprawdę jednak Bóg zamieszka z człowiekiem na ziemi? Oto niebiosa i niebiosa niebios nie mogą cię ogarnąć; o ileż mniej ten dom, który zbudowałem?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 19, 'Zważ więc na modlitwę swego sługi i na jego prośbę, Panie, mój Boże, wysłuchaj wołania i modlitwy, które twój sługa zanosi przed tobą;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 20, 'Aby twoje oczy były otwarte nad tym domem we dnie i w nocy, nad tym miejscem, o którym powiedziałeś, że będzie tu przebywać twoje imię; abyś wysłuchiwał modlitwy, którą twój sługa zanosi w tym miejscu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 21, 'Wysłuchaj więc prośby swego sługi i swego ludu Izraela, którą będą zanosić w tym miejscu. Wysłuchaj z miejsca swojego zamieszkania, z nieba, a gdy wysłuchasz, przebacz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 22, 'Jeśli ktoś zgrzeszy przeciwko swemu bliźniemu, a ten zobowiąże go do przysięgi, a ta przysięga przyjdzie przed twój ołtarz w tym domu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 23, 'Ty wysłuchaj z nieba, racz działać i osądź swoje sługi; potępiaj niegodziwego, sprowadzając mu na głowę jego czyny, a usprawiedliwiaj sprawiedliwego, oddając mu według jego sprawiedliwości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 24, 'Jeśli twój lud Izrael zostanie pobity przez wroga za to, że zgrzeszył przeciwko tobie, a nawróci się, wyzna twoje imię i będzie się modlić, i błagać cię w tym domu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 25, 'Ty wysłuchaj z nieba i przebacz grzech swemu ludowi Izraela, i przyprowadź go znów do ziemi, którą dałeś jemu oraz jego ojcom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 26, 'Kiedy niebo będzie zamknięte i nie będzie deszczu z tego powodu, że zgrzeszyli przeciwko tobie, ale będą się modlić w tym miejscu, wyznają twoje imię i odwrócą się od swojego grzechu, bo ich upokorzyłeś;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 27, 'Ty wysłuchaj z nieba i przebacz grzech swoich sług i swojego ludu Izraela, gdy nauczysz ich dobrej drogi, po której mają kroczyć, i ześlij deszcz na swoją ziemię, którą dałeś swojemu ludowi w dziedzictwo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 28, 'Jeśli będzie w ziemi głód, jeśli nastanie zaraza, susza, rdza, szarańcza lub robactwo; jeśli wróg będzie uciskał lud w ziemi jego zamieszkania, jeśli będzie jakakolwiek plaga lub choroba;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 29, 'Wszelkiej modlitwy i wszelkiego błagania, jakie zaniesie którykolwiek człowiek lub cały lud Izraela – kto tylko uzna swoją klęskę i swój ból i podniesie swoje ręce w tym domu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 30, 'Ty wysłuchaj z nieba, z miejsca swojego zamieszkania, przebacz i oddaj każdemu według wszystkich jego dróg, ty, który znasz jego serce – gdyż jedynie ty znasz serca synów ludzkich;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 31, 'Aby się ciebie bali i kroczyli twoimi drogami po wszystkie dni, które będą żyć na ziemi, którą dałeś naszym ojcom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 32, 'Również i cudzoziemca, który nie jest z twojego ludu Izraela, a jednak przyjdzie z dalekiej ziemi przez wzgląd na twoje wielkie imię, na potężną rękę i wyciągnięte ramię, gdy przyjdzie i będzie się modlić w tym domu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 33, 'Ty wysłuchaj z nieba, z miejsca swojego zamieszkania, i uczyń wszystko, o co ten cudzoziemiec będzie do ciebie wołać, aby wszystkie narody ziemi poznały twoje imię i bały się ciebie tak jak twój lud Izraela, i aby wiedziały, że twoje imię jest wzywane nad tym domem, który zbudowałem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 34, 'Jeśli twój lud wyruszy na wojnę przeciwko swoim wrogom, drogą, którą go poślesz, i będzie się modlić, zwracając się ku temu miastu, które wybrałeś, i ku domowi, który zbudowałem dla twojego imienia;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 35, 'Wysłuchaj z nieba ich modlitwy i błagania i broń ich sprawy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 36, 'Jeśli zgrzeszą przeciw tobie – bo nie ma człowieka, który by nie zgrzeszył – i rozgniewasz się na nich, i poddasz ich wrogowi, który uprowadzi ich w niewolę do ziemi dalekiej lub bliskiej;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 37, 'Jeśli wezmą to do serca w tej ziemi, do której zostali uprowadzeni w niewolę, i odwrócą się, i będą się modlić w ziemi swojej niewoli, mówiąc: Zgrzeszyliśmy, źle uczyniliśmy i niegodziwie postępowaliśmy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 38, 'I jeśli zawrócą do ciebie z całego swego serca i całą swoją duszą w ziemi swojej niewoli, do której zostali uprowadzeni, i będą się modlić, zwróceni ku swojej ziemi, którą dałeś ich ojcom, i ku miastu, które wybrałeś, i ku domowi, który zbudowałem dla twojego imienia;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 39, 'Wysłuchaj z nieba, z miejsca swojego zamieszkania, ich modlitwy i ich błagania, broń ich sprawy i przebacz swemu ludowi, który zgrzeszył przeciw tobie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 40, 'A teraz, o Boże, proszę, niech twoje oczy będą otwarte i niech twoje uszy będą uważne na modlitwę zaniesioną w tym miejscu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 41, 'Powstań więc teraz, Panie Boże, i wejdź do miejsca swego odpoczynku, ty i arka twojej mocy. Niech twoi kapłani, Panie Boże, ubiorą się w zbawienie, a twoi święci niech się radują dobrem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 42, 'Panie Boże, nie odwracaj oblicza od swojego pomazańca; pamiętaj o miłosierdziu wobec Dawida, swego sługi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 1, 'A gdy Salomon skończył się modlić, spadł z nieba ogień i pochłonął całopalenie oraz pozostałe ofiary, a chwała Pana wypełniła ten dom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 2, 'I kapłani nie mogli wejść do domu Pana, bo chwała Pana napełniła dom Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 3, 'Wszyscy synowie Izraela, widząc spadający ogień i chwałę Pana nad domem, upadli twarzą do ziemi, na posadzkę, oddali pokłon Panu i chwalili go, mówiąc: Bo jest dobry, bo na wieki trwa jego miłosierdzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 4, 'Wtedy król i cały lud złożyli ofiary przed Panem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 5, 'Król Salomon złożył w ofierze dwadzieścia dwa tysiące wołów i sto dwadzieścia tysięcy owiec. I tak król i cały lud poświęcili dom Boży.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 6, 'Kapłani zaś stali na swoich stanowiskach, również Lewici z instrumentami muzycznymi Pana, które wykonał król Dawid na chwałę Pana – bo na wieki trwa jego miłosierdzie – i oddał nimi chwałę. Naprzeciw nich trąbili kapłani, a cały lud Izraela stał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 7, 'Salomon poświęcił również środek dziedzińca, który znajdował się przed domem Pana, bo tam złożył w ofierze całopalenia i tłuszcz ofiar pojednawczych, gdyż na ołtarzu z brązu, który Salomon wykonał, nie mogły się pomieścić całopalenia, ofiary z pokarmów i tłuszcz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 8, 'W tym czasie Salomon obchodził święto przez siedem dni, a z nim cały Izrael, bardzo wielkie zgromadzenie, od wejścia do Chamat aż do rzeki Egiptu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 9, 'Potem ósmego dnia obchodzili uroczyste święto. Poświęcenie ołtarza trwało bowiem siedem dni i uroczyste święto obchodzili przez siedem dni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 10, 'A dwudziestego trzeciego dnia siódmego miesiąca, król odesłał lud do jego namiotów, radosny i cieszący się w sercu z powodu dobrodziejstwa, które Pan uczynił Dawidowi, Salomonowi i Izraelowi, swojemu ludowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 11, 'I tak Salomon ukończył dom Pana i dom królewski i szczęśliwie wykonał wszystko, co zamierzył w sercu uczynić w domu Pana i w swoim domu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 12, 'Potem Pan ukazał się Salomonowi w nocy i powiedział do niego: Wysłuchałem twojej modlitwy i wybrałem sobie to miejsce na dom ofiary.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 13, 'Jeśli zamknę niebo, żeby nie było deszczu, jeśli rozkażę szarańczy, aby pożarła ziemię, jeśli też ześlę zarazę na swój lud;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 14, 'I jeśli mój lud, który jest nazywany moim imieniem, ukorzy się, będzie modlić się i szukać mojego oblicza, i odwróci się od swoich złych dróg, wtedy wysłucham go z nieba, przebaczę mu grzech i uzdrowię jego ziemię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 15, 'Teraz moje oczy będą otwarte, a moje uszy uważne na modlitwę zaniesioną w tym miejscu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 16, 'Teraz bowiem wybrałem i poświęciłem ten dom, aby tu przebywało moje imię na wieki. Tam będą moje oczy i moje serce po wszystkie dni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 17, 'Ty zaś, jeśli będziesz chodził przede mną, tak jak chodził Dawid, twój ojciec, i będziesz postępował według wszystkiego, co ci nakazałem, i przestrzegał moich nakazów i praw;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 18, 'Wtedy utwierdzę tron twojego królestwa, tak jak przyrzekłem Dawidowi, twojemu ojcu: Nie zabraknie ci potomka panującego nad Izraelem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 19, 'A jeśli odwrócicie się ode mnie i opuścicie moje nakazy i przykazania, które wam podałem, a pójdziecie służyć innym bogom i będziecie im oddawać pokłon;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 20, 'Wtedy wykorzenię ich ze swojej ziemi, którą im dałem, a ten dom, który poświęciłem swojemu imieniu, odrzucę sprzed swojego oblicza i uczynię z niego przedmiot przypowieści i pośmiewiskiem wśród wszystkich narodów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 21, 'A ten dom, który był wyniosły, będzie dla każdego przechodzącego obok przedmiotem zdziwienia, tak że powie: Czemu Pan tak uczynił tej ziemi i temu domowi?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 22, 'Wtedy odpowiedzą: Ponieważ opuścili Pana, Boga swoich ojców, który ich wyprowadził z ziemi Egiptu, a uchwycili się innych bogów, oddawali im pokłon i służyli im. Dlatego sprowadził na nich całe to nieszczęście.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 1, 'A po upływie dwudziestu lat, w których Salomon zbudował dom Pana i swój dom;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 2, 'Odbudował też miasta, które Huram zwrócił Salomonowi, i oddał je na mieszkanie synom Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 3, 'Potem Salomon wyruszył do Chamat Soby i zdobył je.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 4, 'Odbudował też Tadmor na pustyni oraz wszystkie miasta, w których miał składy, a które zbudował w Chamat.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 5, 'Odbudował także Bet-Choron górne i Bet-Choron dolne, miasta warowne, z murami, bramami i ryglami;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 6, 'Również Baalat i wszystkie miasta, w których Salomon miał składy, wszystkie też miasta rydwanów i miasta jeźdźców i wszystko to, co mu się podobało wybudować w Jerozolimie, w Libanie i w całej ziemi swego panowania.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 7, 'A wszystkie ludy, które ocalały spośród Chetytów, Amorytów, Peryzzytów, Chiwwitów i Jebusytów, które nie były z Izraela;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 8, 'Lecz stanowiły potomstwo tych, którzy pozostali po nich w ziemi, a których synowie Izraela nie mogli wytracić – te Salomon obciążył pracą przymusową aż do dziś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 9, 'Ale z synów Izraela Salomon nie uczynił niewolników do swoich prac, byli tylko dzielnymi wojownikami, naczelnikami jego dowódców i przełożonymi nad jego rydwanami i jeźdźcami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 10, 'Ci byli naczelnikami spośród wodzów, których miał król Salomon; było ich dwustu pięćdziesięciu, którzy panowali nad ludem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 11, 'Lecz córkę faraona Salomon przeniósł z miasta Dawida do domu, który jej zbudował. Powiedział bowiem: Moja żona nie będzie mieszkała w domu Dawida, króla Izraela, bo jest święty przez to, że weszła do niego arka Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 12, 'Wtedy Salomon złożył Panu całopalenia na ołtarzu Pana, który zbudował przed przedsionkiem;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 13, 'Zgodnie ze zwyczajem, składając każdego dnia według nakazu Mojżesza, w szabaty, w dni nowiu księżyca i w uroczyste święta, trzy razy w roku: w Święto Przaśników, w Święto Tygodni i w Święto Namiotów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 14, 'I ustanowił według rozporządzenia Dawida, swojego ojca, zmiany kapłanów w ich służbie oraz Lewitów w ich obowiązkach, aby chwalili Boga i służyli przy kapłanach według ustalonego porządku każdego dnia. Odźwiernych też ustanowił według ich zmian przy każdej bramie. Taki bowiem był rozkaz Dawida, męża Bożego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 15, 'I nie odstąpiono w żadnej sprawie od rozkazu króla dotyczącego kapłanów i Lewitów oraz skarbów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 16, 'I tak zostały przygotowane wszystkie dzieła Salomona od dnia, w którym położono fundamenty domu Pana, aż do jego ukończenia. W ten sposób został dokończony dom Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 17, 'Wtedy Salomon wyruszył do Esjon-Geber i do Elot nad brzegiem morza w ziemi Edomu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 18, 'I Huram za pośrednictwem swoich sług, posłał mu okręty i żeglarzy obeznanych z morzem. Wraz ze sługami Salomona popłynęli do Ofiru, wzięli stamtąd czterysta pięćdziesiąt talentów złota i przywieźli je do króla Salomona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 1, 'A gdy królowa Saby usłyszała o sławie Salomona, przybyła do Jerozolimy, aby przez zagadki poddać go próbie. Przybyła z bardzo wielkim orszakiem, z wielbłądami niosącymi wonności, bardzo dużo złota i drogocennych kamieni. Gdy przyszła do Salomona, rozmawiała z nim o wszystkim, co leżało jej na sercu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 2, 'Salomon zaś odpowiedział na wszystkie jej pytania. Nie było nic tajemnego dla Salomona, na co nie mógłby jej odpowiedzieć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 3, 'Gdy więc królowa Saby ujrzała mądrość Salomona i dom, który zbudował;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 4, 'A także potrawy jego stołu, siadanie jego sług, stawanie jego służących, ich szaty, jego podczaszych i ich szaty oraz schody, po których wstępował do domu Pana, dech zamarł jej w piersi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 5, 'Wtedy przemówiła do króla: Prawdziwa była ta wieść, którą słyszałam w mojej ziemi o twoich dziełach i twojej mądrości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 6, 'Jednak nie wierzyłam ich słowom, aż przybyłam i zobaczyłam to wszystko na własne oczy. I oto nie powiedziano mi nawet połowy o twojej wielkiej mądrości. Przeszedłeś bowiem sławę, o której słyszałam.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 7, 'Błogosławieni twoi ludzie i błogosławieni twoi słudzy, którzy zawsze stoją przed tobą i słuchają twojej mądrości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 8, 'Niech będzie błogosławiony Pan, twój Bóg, który cię sobie upodobał, aby cię posadzić na swoim tronie jako króla dla Pana, twojego Boga. A ponieważ twój Bóg umiłował Izraela, aby go umocnić na wieki, dlatego ustanowił cię królem nad nimi, abyś czynił sąd i sprawiedliwość.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 9, 'I dała królowi sto dwadzieścia talentów złota i bardzo wiele wonności oraz drogocennych kamieni. Nigdy nie przywieziono takich wonności, jakie królowa Saby dała królowi Salomonowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 10, 'Ponadto słudzy Hurama i słudzy Salomona, którzy przywieźli złoto z Ofiru, sprowadzili także drzewa sandałowe i drogocenne kamienie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 11, 'Z tego drzewa sandałowego król wykonał schody do domu Pana i do domu królewskiego oraz harfy i cytry dla śpiewaków. Nigdy przedtem nie widziano takich rzeczy w ziemi Judy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 12, 'Król Salomon dał królowej Saby wszystko, czego zapragnęła i o co poprosiła, nie licząc daru za to, co przyniosła do króla. Potem odjechała i wróciła do swojej ziemi razem ze swoimi sługami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 13, 'A waga złota, które wpływało do Salomona w ciągu jednego roku, wynosiła sześćset sześćdziesiąt sześć talentów złota;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 14, 'Nie licząc tego, co dostawał od kupców i handlarzy. Także wszyscy królowie arabscy i namiestnicy ziemi przywozili złoto i srebro Salomonowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 15, 'Wykonał więc król Salomon dwieście tarczy z kutego złota. Na każdą tarczę wychodziło sześćset syklów kutego złota.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 16, 'Wykonał także trzysta puklerzy z kutego złota. Na każdy puklerz wychodziło trzysta syklów złota. I król umieścił je w domu lasu Libanu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 17, 'Król sporządził także wielki tron z kości słoniowej i pokrył go szczerym złotem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 18, 'Tron miał sześć stopni, a podnóżek był ze złota, przymocowany do tronu. Po obu stronach siedzenia były poręcze, a przy poręczach stały dwa lwy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 19, 'Dwanaście lwów stało na tych sześciu stopniach po obu stronach. Czegoś takiego nie uczyniono w żadnym innym królestwie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 20, 'Wszystkie też naczynia, z których pił król Salomon, były złote, i wszystkie sprzęty w domu lasu Libanu były ze szczerego złota. Nie było nic ze srebra, gdyż nie uważano go za cenne w czasach Salomona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 21, 'Królewskie okręty pływały bowiem do Tarszisz wraz ze sługami Hurama. Raz na trzy lata okręty wracały z Tarszisz, przywożąc złoto, srebro, kości słoniowe, małpy i pawie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 22, 'I tak król Salomon przewyższał wszystkich królów ziemi bogactwem i mądrością.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 23, 'Wszyscy więc królowie ziemi pragnęli widzieć Salomona, aby słuchać jego mądrości, którą Bóg włożył w jego serce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 24, 'Każdy z nich przynosił mu swoje dary: naczynia srebrne i złote, szaty, zbroje, wonności, konie i muły, rokrocznie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 25, 'I Salomon miał cztery tysiące przegród dla koni i rydwanów oraz dwanaście tysięcy jeźdźców, których rozmieścił po miastach rydwanów i przy królu w Jerozolimie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 26, 'I panował nad wszystkimi królami od rzeki aż do ziemi Filistynów i do granicy Egiptu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 27, 'Król sprawił, że srebro w Jerozolimie było jak kamienie, a cedry tak liczne jak sykomory na nizinie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 28, 'Sprowadzono też dla Salomona konie z Egiptu i ze wszystkich innych ziem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 29, 'A pozostałych dziejów Salomona, od pierwszych do ostatnich, czy nie zapisano w księdze proroka Natana, w proroctwie Achiasza Szilonity i w widzeniach Jeddo widzącego przeciw Jeroboamowi, synowi Nebata?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 30, 'I Salomon królował w Jerozolimie nad całym Izraelem czterdzieści lat.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 31, 'Potem Salomon zasnął ze swoimi ojcami i pochowano go w mieście Dawida, jego ojca, a syn jego Roboam królował w jego miejsce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 1, 'Roboam udał się do Sychem, gdyż do Sychem przybył cały Izrael, aby ustanowić go królem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 2, 'A gdy usłyszał o tym Jeroboam, syn Nebata, który był w Egipcie, dokąd uciekł przed królem Salomonem, wrócił z Egiptu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 3, 'Wtedy posłano po niego i wezwano go. Przyszedł więc Jeroboam wraz z całym Izraelem i powiedzieli do Roboama:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 4, 'Twój ojciec włożył na nas ciężkie jarzmo. Teraz więc ty ulżyj nam w srogiej niewoli swego ojca i w ciężkim jarzmie, które włożył na nas, a będziemy ci służyć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 5, 'Odpowiedział im: Wróćcie do mnie po trzech dniach. I lud odszedł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 6, 'Wtedy król Roboam radził się starszych, którzy stawali przed Salomonem, jego ojcem, gdy jeszcze żył, pytając: Jaką odpowiedź radzicie dać temu ludowi?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 7, 'Odpowiedzieli mu: Jeśli będziesz dla tego ludu dobry, okażesz im życzliwość i będziesz mówił do nich łagodne słowa, to będą twoimi sługami przez wszystkie dni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 8, 'Ale on odrzucił radę starszych, którą mu dali, i radził się młodzieńców, którzy razem z nim wzrośli i stawali przed nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 9, 'I zapytał ich: A co wy radzicie odpowiedzieć temu ludowi, który poprosił mnie: Ulżyj nam w jarzmie, które włożył na nas twój ojciec?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 10, 'Wtedy młodzieńcy, którzy razem z nim wzrośli, odpowiedzieli mu: Tak odpowiesz temu ludowi, który powiedział tobie: Twój ojciec włożył na nas ciężkie jarzmo, ale ty nam ulżyj; tak im powiesz: Mój mały palec jest grubszy niż biodra mojego ojca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 11, 'Teraz więc chociaż mój ojciec nałożył na was ciężkie jarzmo, ja dołożę do waszego jarzma. Mój ojciec karcił was biczami, ale ja będę was karcił skorpionami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 12, 'Przyszedł więc Jeroboam i cały lud do Roboama trzeciego dnia, tak jak król nakazał, mówiąc: Wróćcie do mnie na trzeci dzień.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 13, 'I król odpowiedział im surowo, bo odrzucił król Roboam radę starców.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 14, 'I przemówił do nich według rady młodzieńców, mówiąc: Mój ojciec obciążył was ciężkim jarzmem, ale ja dołożę do niego. Mój ojciec karcił was biczami, ale ja będę was karcił skorpionami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 15, 'Król więc nie usłuchał ludu, sprawa bowiem wyszła od Boga, aby Pan spełnił swoje słowo, które wypowiedział przez Achiasza Szilonitę do Jeroboama, syna Nebata.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 16, 'A gdy cały Izrael zobaczył, że król ich nie usłuchał, lud odpowiedział królowi: Jakiż dział mamy w Dawidzie? Nie mamy dziedzictwa w synu Jessego. Idźcie każdy do swoich namiotów, Izraelu! A ty, Dawidzie, troszcz się teraz o swój dom. I rozszedł się cały Izrael do swoich namiotów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 17, 'Tylko nad synami Izraela, którzy mieszkali w miastach Judy, królował Roboam.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 18, 'Wtedy król Roboam posłał do synów Izraela Hadorama, który był poborcą, a oni ukamienowali go tak, że umarł. Król Roboam wsiadł więc w pośpiechu na rydwan i uciekł do Jerozolimy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 19, 'I w ten sposób Izrael zbuntował się przeciwko domowi Dawida aż do dziś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 1, 'Kiedy Roboam przybył do Jerozolimy, zebrał spośród domu Judy i Beniamina sto osiemdziesiąt tysięcy mężczyzn – wyborowych wojowników – aby walczyć z Izraelem i przywrócić królestwo Roboamowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 2, 'Lecz słowo Pana doszło do Szemajasza, męża Bożego:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 3, 'Powiedz Roboamowi, synowi Salomona, królowi Judy, i całemu Izraelowi w Judzie i Beniaminie:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 4, 'Tak mówi Pan: Nie wyruszajcie ani nie walczcie ze swoimi braćmi. Niech każdy wróci do swego domu, bo ta rzecz wyszła ode mnie. I posłuchali słowa Pana, i zawrócili z drogi przeciw Jeroboamowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 5, 'I Roboam zamieszkał w Jerozolimie, i odbudował miasta obronne w Judzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 6, 'Odbudował Betlejem, Etam i Tekoa;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 7, 'Bet-Sur, Soko i Adullam;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 8, 'Gat, Mareszę i Zif;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 9, 'Adoraim, Lakisz i Azekę;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 10, 'Sorea, Ajjalon i Hebron, warowne miasta w Judzie i Beniaminie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 11, 'A gdy wzmocnił te twierdze, ustanowił w nich dowódców i zaopatrzył w składy zboża, oliwy i wina.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 12, 'A w każdym mieście złożył tarcze i włócznie i bardzo je umocnił. Tak należały do niego Juda i Beniamin.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 13, 'Kapłani też i Lewici, którzy byli w całym Izraelu, zebrali się u niego, przybywszy ze wszystkich swoich granic.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 14, 'Lewici bowiem opuścili swoje pastwiska i posiadłości i przyszli do Judy i do Jerozolimy, gdyż Jeroboam i jego synowie odsunęli ich od pełnienia służby kapłańskiej dla Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 15, 'I ustanowił sobie kapłanów na wyżynach dla kultu demonów i cielców, które sporządził.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 16, 'A za nimi przybywali do Jerozolimy ze wszystkich pokoleń Izraela ci, którzy zwrócili swoje serca ku szukaniu Pana, Boga Izraela, aby składać ofiary Panu, Bogu swoich ojców.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 17, 'I tak przez trzy lata umocnili królestwo Judy, i utwierdzili Roboama, syna Salomona. Trzy lata bowiem chodzili drogą Dawida i Salomona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 18, 'Potem Roboam wziął sobie za żonę Machalat, córkę Jerimota, syna Dawida, oraz Abihail, córkę Eliaba, syna Jessego;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 19, 'Która mu urodziła synów: Jeusza, Szemariasza i Zahama.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 20, 'A po niej wziął za żonę Maakę, córkę Absaloma, która urodziła mu Abiasza, Attaja, Zizę i Szelomita.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 21, 'Roboam ukochał Maakę, córkę Absaloma, najbardziej ze wszystkich swoich żon i nałożnic. Pojął bowiem osiemnaście żon i sześćdziesiąt nałożnic i spłodził dwudziestu ośmiu synów i sześćdziesiąt córek.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 22, 'I Roboam ustanowił na czele Abiasza, syna Maaki, aby był wodzem wśród jego braci. Zamierzał bowiem uczynić go królem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 23, 'A postępując roztropnie, rozesłał wszystkich pozostałych swoich synów po wszystkich krainach Judy i Beniamina, po wszystkich miastach warownych, i zaopatrzył ich w zapasy żywności. I pragnął wielu żon.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 1, 'A gdy Roboam utwierdził swoje królestwo i umocnił je, opuścił prawo Pana, a wraz z nim cały Izrael.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 2, 'I w piątym roku panowania Roboama Sziszak, król Egiptu, nadciągnął przeciw Jerozolimie, oni bowiem zgrzeszyli przeciw Panu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 3, 'Wyruszył z tysiącem i dwustu rydwanami i z sześćdziesięcioma tysiącami jeźdźców oraz niezliczonym ludem, który nadciągnął z nim z Egiptu: Libijczykami, Sukkijczykami i Kuszytami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 4, 'I zdobył warowne miasta, które były w Judzie, i dotarł aż do Jerozolimy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 5, 'Wtedy prorok Szemajasz przyszedł do Roboama i do książąt Judy, którzy zebrali się w Jerozolimie z obawy przed Sziszakiem, i powiedział do nich: Tak mówi Pan: Wy mnie opuściliście, dlatego i ja was opuściłem i poddałem w ręce Sziszaka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 6, 'Wtedy książęta Izraela i król ukorzyli się i powiedzieli: Sprawiedliwy jest Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 7, 'A gdy Pan zobaczył, że się ukorzyli, słowo Pana doszło do Szemajasza: Ponieważ ukorzyli się, nie wytracę ich, lecz nieco ich wyzwolę, a mój gniew nie wyleje się na Jerozolimę przez ręce Sziszaka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 8, 'Staną się jednak jego sługami, aby wiedzieli, co znaczy służyć mnie, a co królestwom ziemskim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 9, 'Nadciągnął więc Sziszak, król Egiptu, przeciw Jerozolimie i zabrał skarby domu Pana oraz skarby domu królewskiego – zabrał wszystko. Wziął też złote tarcze, które wykonał Salomon.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 10, 'Zamiast nich król Roboam wykonał spiżowe tarcze i powierzył je dowódcom straży przybocznej, którzy strzegli wejścia do domu królewskiego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 11, 'A gdy król wchodził do domu Pana, straż przyboczna przychodziła po nie, a potem odnosiła je do wartowni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 12, 'A ponieważ król się ukorzył, odwrócił się od niego gniew Pana i Pan nie wytracił go całkowicie. Również w Judzie działy się rzeczy dobre.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 13, 'Umocnił się więc król Roboam w Jerozolimie i królował. Roboam miał czterdzieści jeden lat, kiedy zaczął królować, i królował siedemnaście lat w Jerozolimie, w mieście, które Pan wybrał spośród wszystkich pokoleń Izraela, aby tam przebywało jego imię. Jego matka miała na imię Naama i była Ammonitką.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 14, 'On zaś czynił to, co złe, bo nie przygotował swojego serca, aby szukać Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 15, 'Ale dzieje Roboama, od pierwszych do ostatnich, czy nie są zapisane są w księdze proroka Szemajasza oraz widzącego Iddo w opisie rodowodów? A między Roboamem i Jeroboamem toczyły się wojny po wszystkie ich dni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 16, 'Potem Roboam zasnął ze swoimi ojcami i został pogrzebany w mieście Dawida, a jego syn Abiasz królował w jego miejsce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 1, 'W osiemnastym roku króla Jeroboama zaczął królować Abiasz nad Judą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 2, 'Trzy lata królował w Jerozolimie, a jego matka miała na imię Maaka i była córką Uriela z Gibea. I trwała wojna między Abiaszem a Jeroboamem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 3, 'Abiasz więc przyszykował wojsko liczące czterysta tysięcy dzielnych wojowników, wyborowych mężczyzn. Jeroboam także przyszykował przeciwko niemu osiemset tysięcy wyborowych mężczyzn, dzielnych wojowników.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 4, 'Wtedy Abiasz stanął na szczycie góry Semaraim, położonej wśród gór Efraim, i powiedział: Słuchajcie mnie, Jeroboamie i cały Izraelu!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 5, 'Czy nie powinniście wiedzieć, że Pan, Bóg Izraela, dał Dawidowi panowanie nad Izraelem na wieki – jemu i jego synom – przymierzem soli?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 6, 'Lecz powstał Jeroboam, syn Nebata, sługa Salomona, syna Dawida, i zbuntował się przeciw swojemu panu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 7, 'I zebrali się u niego lekkomyślni mężczyźni, synowie Beliala, i wzmocnili się przeciw Roboamowi, synowi Salomona. A Roboam, będąc młodzieńcem i lękliwego serca, nie mógł się im mężnie oprzeć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 8, 'A wy teraz zamierzacie przeciwstawić się królestwu Pana, które jest w rękach synów Dawida; jesteście wielkim tłumem i macie ze sobą złote cielce, które Jeroboam wykonał wam jako bogów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 9, 'Czy nie odrzuciliście kapłanów Pana, synów Aarona, i Lewitów i czy nie ustanowiliście sobie kapłanów jak inne narody ziemi? Ktokolwiek przychodzi z młodym cielcem i siedmioma baranami, aby się poświęcić, staje się kapłanem tych, którzy nie są bogami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 10, 'Ale dla nas Pan jest naszym Bogiem i nie opuściliśmy go. Kapłani, którzy służą Panu, są synami Aarona, a Lewici pełnią swoje obowiązki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 11, 'I każdego ranka i wieczora składają Panu w ofierze całopalenia i wonności oraz układają chleby pokładne na czystym stole, przygotowują także złoty świecznik i jego lampy, aby płonęły co wieczór. W ten oto sposób przestrzegamy rozkazu Pana, naszego Boga, ale wy go opuściliście.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 12, 'Oto więc z nami na czele jest Bóg wraz ze swoimi kapłanami mającymi głośne trąby, aby grzmiały przeciwko wam. Synowie Izraela, nie walczcie z Panem, Bogiem waszych ojców, bo wam się nie powiedzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 13, 'Tymczasem Jeroboam rozkazał uczynić zasadzkę i napaść ich od tyłu. I stali oni przed Judą, a zasadzka była na tyłach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 14, 'Gdy synowie Judy zobaczyli, że walka toczy się z przodu i z tyłu, wołali do Pana, a kapłani zadęli w trąby.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 15, 'Mężczyźni Judy wydali też okrzyk. I kiedy wydali okrzyk, Bóg poraził Jeroboama i całego Izraela przed Abiaszem i Judą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 16, 'I synowie Izraela uciekali przed Judą, ale Bóg wydał ich w ich ręce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 17, 'I Abiasz i jego lud zadali im wielką klęskę, tak że spośród Izraela poległo pięćset tysięcy wyborowych mężczyzn.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 18, 'W tym czasie więc synowie Izraela zostali upokorzeni, a umocnili się synowie Judy, ponieważ polegali na Panu, Bogu swoich ojców.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 19, 'I Abiasz ścigał Jeroboama, i odebrał mu miasta: Betel, Jeszanę i Efron razem z należącymi do nich wioskami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 20, 'Jeroboam nie mógł powrócić już do sił za dni Abiasza i Pan poraził go tak, że umarł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 21, 'A Abiasz umocnił się i wziął sobie czternaście żon, i spłodził dwudziestu dwóch synów i szesnaście córek.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 22, 'Ale pozostałe dzieje Abiasza, jego czyny i słowa są zapisane w księdze proroka Iddo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 1, 'A gdy Abiasz zasnął ze swoimi ojcami, pogrzebano go w mieście Dawida. Wtedy jego syn Asa królował w jego miejsce. Za jego dni w ziemi panował pokój przez dziesięć lat.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 2, 'Asa czynił to, co było dobre i prawe w oczach Pana, jego Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 3, 'Usunął bowiem ołtarze obcych bogów i wyżyny, pokruszył posągi i wyrąbał gaje.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 4, 'Nakazał Judzie szukać Pana, Boga swoich ojców, i przestrzegać prawa i przykazań.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 5, 'Zniósł też ze wszystkich miast Judy wyżyny i posągi, a królestwo za jego czasów zaznało pokoju.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 6, 'Ponadto zbudował miasta warowne w Judzie, ponieważ w ziemi panował pokój i nie było wojny przeciwko niemu w tych latach. Pan bowiem dał mu odpoczynek.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 7, 'I powiedział do Judy: Zbudujmy te miasta i otoczmy je murami, wieżami, bramami i ryglami, póki ziemia jest w naszej mocy. Szukaliśmy bowiem Pana, naszego Boga, szukaliśmy go i dał nam zewsząd odpoczynek. Budowali więc i powodziło się im.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 8, 'I Asa miał wojsko z Judy – trzysta tysięcy noszących tarcze i włócznie, i z Beniamina – dwieście osiemdziesiąt tysięcy noszących puklerz i napinających łuk. Wszyscy oni byli bardzo dzielni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 9, 'Wtedy przeciwko nim nadciągnął Zerach Etiopczyk z wojskiem liczącym tysiąc tysięcy oraz trzystu rydwanami i dotarł aż do Mareszy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 10, 'Nadciągnął też i Asa przeciw niemu i stanęli w szyku bojowym w Dolinie Sefaty w Mareszy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 11, 'Wtedy Asa zawołał do Pana, swego Boga, i powiedział: Panie, ty nie potrzebujesz wielu, aby uratować tego, który nie ma siły. Ratuj nas, Panie, nasz Boże, gdyż na tobie polegamy i w twoje imię idziemy przeciwko temu mnóstwu. Ty jesteś Panem, naszym Bogiem. Niech człowiek nie zyska przewagi nad tobą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 12, 'A Pan poraził Etiopczyków przed Asą i Judą tak, że Etiopczycy uciekli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 13, 'I Asa wraz z ludem, który był z nim, ścigał ich aż do Gerary. I polegli Etiopczycy tak, że nikt się nie uratował, bo zostali starci przed Panem i jego wojskiem. I nabrano bardzo dużo łupów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 14, 'Ponadto pobili wszystkie miasta dokoła Gerary, bo padł na nie strach Pana i złupili wszystkie miasta. Była bowiem w nich wielka zdobycz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 15, 'Napadli także na namioty trzód, uprowadzając wiele owiec i wielbłądów i wrócili do Jerozolimy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 1, 'Wtedy Duch Boży zstąpił na Azariasza, syna Obeda.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 2, 'I wyszedł on naprzeciw Asy, i powiedział mu: Słuchajcie mnie, Aso i całe pokolenie Judy i Beniamina. Pan jest z wami, dopóki jesteście z nim. Jeśli go szukać będziecie, znajdziecie go, ale jeśli go opuścicie, on opuści was.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 3, 'Przez wiele dni Izrael był bez prawdziwego Boga, bez nauczającego kapłana i bez prawa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 4, 'Gdy jednak w swoim nieszczęściu nawrócili się do Pana, Boga Izraela, i szukali go, dawał się im odnaleźć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 5, 'W tamtych czasach nie było pokoju ani dla wychodzącego, ani dla wchodzącego, gdyż wielkie udręki spotkały wszystkich mieszkańców ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 6, 'I naród występował przeciw narodowi, a miasto – przeciw miastu, ponieważ Bóg ich zatrważał wszelkim nieszczęściem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 7, 'Wy więc umacniajcie się i niech nie słabną wasze ręce, bo czeka was zapłata za waszą pracę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 8, 'A gdy Asa usłyszał te słowa i proroctwo proroka Obeda, umocnił się i usunął obrzydliwości z całej ziemi Judy i Beniamina, a także z miast, które zdobył na górze Efraim, i odnowił ołtarz Pana, który stał przed przedsionkiem Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 9, 'Potem zebrał cały lud z Judy i Beniamina oraz przybyszów, którzy byli z nimi z Efraima, Manassesa i Symeona. Bardzo wielu bowiem zbiegło z Izraela do niego, widząc, że z nim był Pan, jego Bóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 10, 'Zgromadzili się więc w Jerozolimie w trzecim miesiącu, w piętnastym roku panowania Asy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 11, 'W tym dniu złożyli Panu ofiary z łupów, które przynieśli: siedemset wołów i siedem tysięcy owiec.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 12, 'I zobowiązali się przymierzem szukać Pana, Boga swoich ojców, z całego swego serca i całą swoją duszą;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 13, 'I że ktokolwiek nie będzie szukał Pana, Boga Izraela, poniesie śmierć – czy to mały, czy wielki, mężczyzna czy kobieta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 14, 'I przysięgli Panu donośnym głosem, wśród okrzyków oraz dźwięków trąb i kornetów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 15, 'A cały lud Judy radował się z tej przysięgi, ponieważ przysięgli z całego serca i z całą chęcią szukali go, a dał się im odnaleźć. I dał im Pan odpoczynek ze wszystkich stron.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 16, 'Ponadto nawet swoją matkę Maakę król Asa pozbawił godności królowej, ponieważ sporządziła posąg w gaju. I Asa ściął jej posąg, pokruszył go i spalił przy potoku Cedron.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 17, 'A choć wyżyny nie zostały zniesione z Izraela, to jednak serce Asy było doskonałe przez wszystkie jego dni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 18, 'Sprowadził też do domu Bożego to, co poświęcił jego ojciec i co on sam poświęcił: srebro, złoto i naczynia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 19, 'I nie było wojny aż do trzydziestego piątego roku panowania Asy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 1, 'W trzydziestym szóstym roku panowania Asy nadciągnął przeciw Judzie Basza, król Izraela, i zbudował Rama, aby nikt nie mógł wychodzić od Asy, króla Judy, i wchodzić do niego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 2, 'Wtedy Asa wziął srebro i złoto ze skarbców domu Pana i domu królewskiego i posłał je do Ben-Hadada, króla Syrii, który mieszkał w Damaszku, mówiąc:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 3, 'Trwa przymierze między mną a tobą, j ak było między moim ojcem a twoim ojcem. Oto posyłam ci srebro i złoto. Idź i zerwij swoje przymierze z Baszą, królem Izraela, aby odstąpił ode mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 4, 'I Ben-Hadad posłuchał króla Asy, i posłał dowódców swoich wojsk przeciwko miastom Izraela. Uderzyli na Ijjon, Dan i Abelmaim oraz wszystkie miasta spichlerze Neftalego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 5, 'Kiedy Basza o tym usłyszał, przestał budować Rama i przerwał swoje roboty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 6, 'Wtedy król Asa wziął ze sobą cały lud Judy i zabrali z Rama kamienie i drewno, z którego budował Basza, a zbudował z niego Geba i Mispę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 7, 'A w tym czasie widzący Chanani przyszedł do Asy, króla Judy, i powiedział mu: Ponieważ polegałeś na królu Syrii, a nie na Panu, swoim Bogu, wojsko króla Syrii uszło ci z ręki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 8, 'Czyż Etiopczycy i Libijczycy nie mieli ogromnego wojska z mnóstwem rydwanów i jeźdźców? A jednak, ponieważ polegałeś na Panu, oddał ich w twoją rękę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 9, 'Oczy Pana przebiegają bowiem całą ziemię, aby pokazywał on swoją moc dla tych, których serce jest doskonałe wobec niego. Głupio postąpiłeś; z tego powodu odtąd będziesz miał wojny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 10, 'Wtedy Asa rozgniewał się na widzącego i wtrącił go do więzienia, bo był tym wzburzony. W tym czasie Asa uciskał także niektórych z ludu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 11, 'Ale pozostałe dzieje Asy, od pierwszych do ostatnich, są zapisane w księdze królów Judy i Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 12, 'I w trzydziestym dziewiątym roku swojego panowania Asa rozchorował się na nogi, a choroba była bardzo ciężka. Jednak w swojej chorobie nie szukał Pana, lecz lekarzy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 13, 'I tak Asa zasnął ze swoimi ojcami, i umarł w czterdziestym pierwszym roku swojego panowania.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 14, 'I pogrzebano go w jego grobie, który sobie przygotował w mieście Dawida. Położono go na łożu wypełnionym wonnościami i rozmaitymi maściami przygotowanymi według sztuki aptekarskiej. I rozpalono mu wielki ogień.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 1, 'Potem w jego miejsce królował Jehoszafat, jego syn, i umocnił się przeciwko Izraelowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 2, 'I umieścił wojska we wszystkich warownych miastach Judy. Umieścił też załogi w ziemi Judy i w miastach Efraima, które zdobył Asa, jego ojciec.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 3, 'A Pan był z Jehoszafatem, ponieważ chodził on pierwszymi drogami swego ojca Dawida i nie szukał Baalów;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 4, 'Lecz szukał Boga swego ojca i postępował według jego przykazań, a nie według czynów ludu Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 5, 'I Pan utwierdził królestwo w jego rękach, a cały lud Judy składał dary Jehoszafatowi, tak że miał wiele bogactwa i wielką sławę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 6, 'Umocniło się jego serce w drogach Pana, tym bardziej więc znosił wyżyny i gaje z ziemi Judy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 7, 'Potem w trzecim roku swojego panowania posłał swoich książąt: Ben-Chaila, Obadiasza, Zachariasza, Netaneela i Micheasza, aby nauczali w miastach Judy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 8, 'Posłał z nimi także Lewitów: Szemajasza, Netaniasza, Zebadiasza, Asahela, Szemiramota, Jehonatana, Adoniasza, Tobiasza i Tobadoniasza – Lewitów, a z nimi Eliszamę i Jehorama, kapłanów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 9, 'Nauczali oni w Judzie, mając ze sobą księgę Prawa Pana, i obchodzili wszystkie miasta Judy, i nauczali lud.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 10, 'A bojaźń Pana padła na wszystkie królestwa ziemi położone dokoła Judy i nie śmiały walczyć przeciwko Jehoszafatowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 11, 'Niektórzy z Filistynów przynosili Jehoszafatowi dary i daniny w srebrze. Arabowie przyprowadzili mu trzody: siedem tysięcy siedemset baranów i siedem tysięcy siedemset kozłów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 12, 'I Jehoszafat wzrastał coraz bardziej w potęgę, i budował w Judzie zamki oraz miasta spichlerze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 13, 'Podjął wiele prac w miastach Judy. I miał wielu dzielnych i potężnych wojowników w Jerozolimie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 14, 'A oto jest ich spis według ich rodów: z Judy tysiącznikami byli: dowódca Adna, a z nim trzysta tysięcy dzielnych wojowników.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 15, 'Przy nim stał dowódca Jehochanan, a z nim dwieście osiemdziesiąt tysięcy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 16, 'Przy nim – Amazjasz, syn Zikriego, który dobrowolnie poświęcił się Panu, a z nim dwieście tysięcy dzielnych wojowników.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 17, 'A z synów Beniamina: Eliada, dzielny wojownik, a z nim dwieście tysięcy mężczyzn uzbrojonych w łuki i tarcze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 18, 'A przy nim – Jehozabad, a z nim sto osiemdziesiąt tysięcy gotowych do boju.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 19, 'Oni służyli królowi, nie licząc tych, których król rozmieścił w warownych miastach po całej ziemi Judy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 1, 'I Jehoszafat miał wiele bogactwa i wielką sławę, i spokrewnił się z Achabem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 2, 'Po kilku latach przybył do Achaba do Samarii. I Achab zabił dla niego i dla ludu, który z nim był, wiele owiec i wołów i namówił go, aby wyruszył do Ramot-Gilead.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 3, 'Achab, król Izraela, zapytał Jehoszafata, króla Judy: Czy wyruszysz ze mną do Ramot-Gilead? A on mu odpowiedział: Ja tak, jak i ty; mój lud, jak i twój lud, będziemy z tobą na wojnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 4, 'Jehoszafat powiedział jeszcze do króla Izraela: Zapytaj dziś, proszę, o słowo Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 5, 'Zebrał więc król Izraela czterystu proroków i zapytał ich: Czy mamy wyruszyć na wojnę do Ramot-Gilead, czy mam tego zaniechać? A oni odpowiedzieli: Wyrusz, bo Bóg wyda je w ręce króla.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 6, 'Ale Jehoszafat zapytał: Czy nie ma tu jeszcze jakiegoś proroka Pana, abyśmy mogli go zapytać?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 7, 'Król Izraela odpowiedział Jehoszafatowi: Jest jeszcze jeden człowiek, przez którego moglibyśmy radzić się Pana, ale ja go nienawidzę, bo nie prorokuje mi nic dobrego, tylko zawsze to, co złe. Jest to Micheasz, syn Jimli. Jehoszafat powiedział: Niech król tak nie mówi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 8, 'Wtedy król Izraela zawołał pewnego dworzanina i polecił mu: Przyprowadź tu szybko Micheasza, syna Jimli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 9, 'Tymczasem król Izraela i Jehoszafat, król Judy, siedzieli na swoich tronach ubrani w królewskie szaty na placu przed wejściem do Samarii, u jej bramy, a przed nimi prorokowali wszyscy prorocy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 10, 'A Sedekiasz, syn Kenaany, sporządził sobie rogi żelazne i powiedział: Tak mówi Pan: Nimi będziesz bódł Syryjczyków, aż ich wytępisz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 11, 'Tak samo prorokowali wszyscy prorocy, mówiąc: Wyrusz do Ramot-Gilead, a poszczęści ci się. Pan bowiem wyda je w ręce króla.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 12, 'Wtedy posłaniec, który poszedł, aby przywołać Micheasza, powiedział do niego: Oto słowa proroków jednomyślnie wypowiadają królowi to, co dobre. Niech twoje słowo, proszę, będzie jak słowo jednego z nich i mów to, co dobre.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 13, 'Micheasz odpowiedział: Jak żyje Pan, będę mówił to, co Bóg mi rozkaże.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 14, 'A gdy przyszedł do króla, król powiedział do niego: Micheaszu, czy mamy wyruszyć na wojnę przeciw Ramot-Gilead, czy tego zaniechać? Odpowiedział: Wyruszcie, a poszczęści się wam, i będą oddani w wasze ręce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 15, 'I król powiedział do niego: Ile razy mam cię zaprzysięgać, abyś mi nie mówił nic innego, jak tylko prawdę w imieniu Pana?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 16, 'Powiedział więc: Widziałem całego Izraela rozproszonego po górach jak owce niemające pasterza. A Pan powiedział: Oni nie mają pana. Niech każdy wraca do swego domu w pokoju.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 17, 'Wtedy król Izraela powiedział do Jehoszafata: Czyż nie mówiłem ci, że nie będzie mi prorokować nic dobrego, tylko to, co złe?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 18, 'Tamten powiedział: Słuchaj więc słowa Pana: Widziałem Pana siedzącego na swoim tronie, a wszystkie zastępy niebieskie stojące po jego prawicy i lewicy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 19, 'I Pan zapytał: Kto zwiedzie Achaba, króla Izraela, aby wyruszył do Ramot-Gilead i poległ tam? I jeden mówił tak, a drugi inaczej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 20, 'Wtedy wystąpił duch, stanął przed Panem i powiedział: Ja go zwiodę. Pan zapytał go: Jak?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 21, 'Odpowiedział: Wyjdę i będę duchem kłamliwym w ustach wszystkich jego proroków. Pan powiedział: Zwiedziesz go, na pewno ci się uda: Idź i uczyń tak.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 22, 'Teraz więc oto Pan włożył ducha kłamliwego w usta tych twoich proroków, gdyż Pan zapowiedział ci nieszczęście.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 23, 'Podbiegł wtedy Sedekiasz, syn Kenaany, i uderzył Micheasza w policzek, mówiąc: Którędy odszedł ode mnie Duch Pana, aby mówić z tobą?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 24, 'Micheasz odpowiedział: Oto ty sam zobaczysz tego dnia, kiedy wejdziesz do najskrytszej komnaty, aby się ukryć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 25, 'Król Izraela powiedział: Weźcie Micheasza i zaprowadźcie go do Amona, namiestnika miasta, i do Joasza, syna królewskiego;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 26, 'I powiecie: Tak mówi król: Wtrąćcie tego człowieka do więzienia i żywcie go chlebem utrapienia i wodą ucisku, aż wrócę w pokoju.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 27, 'Ale Micheasz odpowiedział: Jeśli rzeczywiście wrócisz w pokoju, to Pan nie mówił przeze mnie. I dodał: Słuchajcie wszyscy ludzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 28, 'Tak więc król Izraela i Jehoszafat, król Judy, wyruszyli do Ramot-Gilead.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 29, 'I król Izraela powiedział do Jehoszafata: Przebiorę się i pójdę na bitwę, ty zaś ubierz się w swoje szaty. Następnie król Izraela przebrał się i poszli na bitwę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 30, 'A król Syrii rozkazał swoim dowódcom rydwanów: Nie walczcie ani z małym, ani z wielkim, tylko z samym królem Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 31, 'A gdy dowódcy rydwanów zobaczyli Jehoszafata, powiedzieli: To jest król Izraela. I otoczyli go, aby z nim walczyć. Ale Jehoszafat zawołał i Pan go wspomógł. I Bóg odwrócił ich od niego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 32, 'Kiedy dowódcy rydwanów zobaczyli bowiem, że nie był to król Izraela, odwrócili się od niego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 33, 'A pewien mężczyzna na ślepo naciągnął łuk i ugodził króla Izraela między spojenia pancerza. A ten powiedział swojemu woźnicy: Zawróć i wywieź mnie z pola bitwy, bo jestem ranny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 34, 'I bitwa wzmogła się tego dnia, a król Izraela stał w rydwanie naprzeciw Syryjczykom aż do wieczora. I umarł, gdy zachodziło słońce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 1, 'A Jehoszafat, król Judy, wrócił do swojego domu w pokoju, do Jerozolimy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 2, 'I wyszedł mu naprzeciw widzący Jehu, syn Chananiego, i powiedział do króla Jehoszafata: Czy powinieneś był pomagać bezbożnym i miłować tych, którzy nienawidzą Pana? Przez to właśnie wisi nad tobą gniew Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 3, 'Znalazły się jednak dobre czyny w tobie, bo powycinałeś gaje z ziemi i przygotowałeś swoje serce, aby szukać Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 4, 'Zamieszkał więc Jehoszafat w Jerozolimie. I znowu wyruszył na objazd do ludu, od Beer-Szeby aż do góry Efraim, i nawrócił ich do Pana, Boga swoich ojców.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 5, 'I ustanowił sędziów w ziemi we wszystkich warownych miastach Judy, w każdym mieście.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 6, 'I powiedział do sędziów: Uważajcie na to, co czynicie, bo sądzicie nie dla człowieka, ale dla Pana, który jest z wami podczas sprawowania sądu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 7, 'Niech więc będzie w was bojaźń Pana. Strzeżcie się i czyńcie sprawiedliwość. Nie ma bowiem nieprawości u Pana, Boga naszego, i nie ma względu na osoby ani przyjmowania darów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 8, 'Także i w Jerozolimie Jehoszafat ustanowił niektórych spośród Lewitów, kapłanów i naczelników rodów Izraela dla sądu Pana i do rozstrzygania sporów tych, którzy się udawali do Jerozolimy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 9, 'I nakazał im: Czyńcie to w bojaźni Pana, wiernie i doskonałym sercem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 10, 'A przy wszystkich sporach, które wam przedłożą wasi bracia mieszkający w swoich miastach, czy dotyczą one przelania krwi, czy prawa, przykazania, ustaw czy sądów, napominajcie ich, aby nie grzeszyli przeciwko Panu, aby gniew nie spadł na was i na waszych braci. Tak czyńcie, a nie zgrzeszycie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 11, 'A oto najwyższy kapłan Amariasz będzie postawiony nad wami we wszystkich sprawach Pana, a Zebadiasz, syn Izmaela, książę w domu Judy – we wszystkich sprawach króla. Lewici będą również waszymi urzędnikami. Umacniajcie się i czyńcie tak, a Pan będzie z dobrym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 1, 'Potem na wojnę przeciwko Jehoszafatowi wyruszyli synowie Moabu i synowie Ammona, a wraz z nimi niektórzy mieszkający z Ammonitami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 2, 'Wtedy jacyś ludzie przyszli do Jehoszafata i powiedzieli do niego: Nadciąga przeciwko tobie wielki tłum zza morza, z Syrii, a oto są w Chaseson-Tamar, to jest w En-Gedi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 3, 'Jehoszafat więc uląkł się i postanowił szukać Pana, i zapowiedział post w całej Judzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 4, 'Wówczas lud Judy zgromadził się, aby szukać Pana. Zeszli się także ze wszystkich miast Judy, aby szukać Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 5, 'Jehoszafat stanął pośrodku zgromadzenia Judy i Jerozolimy w domu Pana, przed nowym dziedzińcem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 6, 'I powiedział: Panie, Boże naszych ojców! Czy ty nie jesteś sam Bogiem na niebie? Czy nie ty panujesz nad wszystkimi królestwami narodów? Czy nie w twoich rękach jest moc i siła, tak że nie ma nikogo, kto by mógł się ostać przed tobą?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 7, 'Czy to nie ty, nasz Boże, wypędziłeś mieszkańców tej ziemi przed swoim ludem Izraelem i dałeś ją potomstwu Abrahama, swojego przyjaciela, na wieki?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 8, 'Zamieszkali w niej i zbudowali ci w niej świątynię dla twojego imienia, mówiąc:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 9, 'Jeśli spadnie na nas nieszczęście, miecz pomsty, zaraza albo głód, a staniemy przed tym domem i przed tobą, gdyż twoje imię przebywa w tym domu, i zawołamy do ciebie w naszym ucisku, wtedy wysłuchasz nas i wybawisz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 10, 'Oto teraz synowie Ammona i Moabu oraz lud z góry Seir, przez których nie dopuściłeś Izraelowi przejść, gdy szedł z ziemi Egiptu, tak że ominęli ich i nie wytracili;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 11, 'Oto jak nam odpłacają! Przyszli, aby wyrzucić nas z twojego dziedzictwa, które nam dałeś w posiadanie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 12, 'O nasz Boże, czy nie osądzisz ich? Nie mamy bowiem żadnej mocy przeciw tak wielkiemu mnóstwu, które przyszło na nas, i nie wiemy, co mamy czynić, ale zwracamy nasze oczy ku tobie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 13, 'A cały lud Judy stał przed Panem z małymi dziećmi, żonami i synami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 14, 'Wówczas pośród zgromadzenia Duch Pana zstąpił na Jehaziela, syna Zachariasza, syna Benajasza, syna Jejela, syna Mattaniasza, Lewitę z synów Asafa;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 15, 'Który powiedział: Słuchajcie, wszyscy z Judy i mieszkańcy Jerozolimy, i ty, królu Jehoszafacie. Tak mówi do was Pan: Nie bójcie się ani nie lękajcie tego wielkiego mnóstwa, bo nie wasza jest ta walka, ale Boża.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 16, 'Jutro ruszajcie przeciwko nim. Oto będą iść zboczem góry Sis i znajdziecie ich na końcu potoku przed pustynią Jeruel.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 17, 'Nie wy będziecie się potykać w tej bitwie. Stawcie się, stójcie i oglądajcie wybawienie Pana nad wami, o Judo i Jerozolimo. Nie bójcie się ani nie lękajcie. Jutro wyruszajcie przeciwko nim, a Pan będzie z wami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 18, 'I pokłonił się Jehoszafat twarzą ku ziemi, a cały lud Judy oraz mieszkańcy Jerozolimy padli przed Panem, oddając Panu pokłon.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 19, 'A Lewici z synów Kehata i z synów Koracha wstali i chwalili Pana, Boga Izraela, donośnym i wysokim głosem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 20, 'Wstali potem wczesnym rankiem i wyruszyli na pustynię Tekoa. A gdy wyruszali, Jehoszafat stanął i powiedział: Słuchajcie mnie, Judo i mieszkańcy Jerozolimy. Wierzcie Panu, waszemu Bogu, a będziecie bezpieczni, wierzcie jego prorokom, a poszczęści się wam.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 21, 'Potem naradził się z ludem i ustanowił śpiewaków dla Pana, by go chwalili w ozdobie świętobliwości i szli przed wojskiem, mówiąc: Wysławiajcie Pana, bo na wieki trwa jego miłosierdzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 22, 'A w tym czasie, gdy oni zaczęli śpiewać i chwalić, Pan zastawił zasadzkę na synów Ammona i Moabu oraz na mieszkańców góry Seir, którzy przyszli przeciw Judzie i zostali pobici.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 23, 'Powstali bowiem synowie Ammona i Moabu przeciwko mieszkańcom góry Seir, aby ich pobić i wytracić. A gdy skończyli z mieszkańcami góry Seir, jeden pomagał drugiemu, aż się wspólnie wytracili.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 24, 'A kiedy lud Judy przybył do wieży strażniczej, blisko pustyni, spojrzał na to mnóstwo, a oto trupy leżały na ziemi, nikt nie ocalał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 25, 'Przyszedł więc Jehoszafat i jego lud, aby zebrać ich łupy. Znaleźli przy nich, pośród zwłok, bardzo dużo bogactwa i kosztownych klejnotów, które zdarli z trupów, tak wiele, że nie mogli tego udźwignąć. Przez trzy dni zbierali te łupy, bo było ich tak dużo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 26, 'A w czwartym dniu zebrali się w Dolinie Beraka, bo tam błogosławili Pana. Dlatego nazwano to miejsce Doliną Beraka i tak nazywa się aż do dziś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 27, 'Potem zawrócili wszyscy mężczyźni Judy i Jerozolimy, z Jehoszafatem na czele, aby wrócić do Jerozolimy z radością. Pan bowiem ich rozradował z powodu ich wrogów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 28, 'I wkroczyli do Jerozolimy z harfami, cytrami i trąbami – do domu Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 29, 'I strach Boży padł na wszystkie królestwa ziemi, gdy usłyszały, że Pan walczył przeciw wrogom ludu Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 30, 'I tak królestwo Jehoszafata żyło w pokoju. Jego Bóg bowiem dał mu odpoczynek ze wszystkich stron.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 31, 'I Jehoszafat królował nad Judą. Miał trzydzieści pięć lat, kiedy zaczął królować, i dwadzieścia pięć lat królował w Jerozolimie. Jego matka miała na imię Azuba i była córką Szilchiego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 32, 'A kroczył on drogą swojego ojca Asy i nie zboczył z niej, czyniąc to, co było prawe w oczach Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 33, 'Wyżyny jednak nie zostały zniesione, bo lud jeszcze nie przygotował swojego serca ku Bogu swoich ojców.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 34, 'A pozostałe dzieje Jehoszafata, od pierwszych do ostatnich, są zapisane w księdze Jehu, syna Chananiego, o którym jest napisane w księdze królów Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 35, 'Potem Jehoszafat, król Judy, sprzymierzył się z Achazjaszem, królem Izraela, który postępował niegodziwie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 36, 'A sprzymierzył się z nim po to, aby zbudować okręty płynące do Tarszisz. Te okręty zbudowali w Esjon-Geber.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 37, 'Dlatego Eliezer, syn Dodawahu z Mareszy, prorokował przeciwko Jehoszafatowi, mówiąc: Ponieważ sprzymierzyłeś się z Achazjaszem, Pan zniszczył twoje dzieło. I rozbiły się okręty tak, że nie mogły popłynąć do Tarszisz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 1, 'Potem Jehoszafat zasnął ze swoimi ojcami i został pogrzebany z nimi w mieście Dawida, a jego syn Joram królował w jego miejsce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 2, 'Ten miał braci, synów Jehoszafata: Azariasza, Jechiela, Zachariasza, Azariasza, Mikaela i Szefatiasza. Ci wszyscy byli synami Jehoszafata, króla Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 3, 'Ich ojciec dał im wiele darów w srebrze i złocie oraz kosztowności wraz z warownymi miastami w Judzie. Ale królestwo oddał Joramowi, ponieważ on był pierworodnym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 4, 'Kiedy Joram objął władzę w królestwie swojego ojca, umocnił się i pozabijał mieczem wszystkich swoich braci, a także niektórych z książąt Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 5, 'Joram miał trzydzieści dwa lata, kiedy zaczął królować, i królował osiem lat w Jerozolimie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 6, 'I chodził drogami królów Izraela, tak jak to czynił dom Achaba, bo córka Achaba była jego żoną. I czynił to, co złe w oczach Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 7, 'Pan jednak nie chciał wytracić domu Dawida ze względu na przymierze, które zawarł z Dawidem, i ponieważ obiecał dać pochodnię jemu oraz jego synom, po wszystkie dni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 8, 'Za jego dni Edomici wyzwolili się spod panowania Judy i ustanowili nad sobą króla.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 9, 'Wyruszył więc Joram wraz ze swoimi dowódcami i wszystkimi swoimi rydwanami. I powstał w nocy, i uderzył na Edomitów, którzy otoczyli jego i dowódców jego rydwanów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 10, 'Edomici jednak wyzwolili się spod ręki Judy i tak jest aż do dziś. W tym czasie również Libna wyzwoliła się spod jego ręki, dlatego że Joram opuścił Pana, Boga swoich ojców.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 11, 'Ponadto pobudował wyżyny w górach Judy i przywiódł mieszkańców Jerozolimy do cudzołóstwa, do tego też skłonił Judę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 12, 'Wtedy przyszło do niego pismo od proroka Eliasza tej treści: Tak mówi Pan, Bóg Dawida, twego ojca: Ponieważ nie chodziłeś drogami swego ojca Jehoszafata i drogami Asy, króla Judy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 13, 'Ale chodziłeś drogą królów Izraela i przywiodłeś do cudzołóstwa Judę i mieszkańców Jerozolimy, tak jak cudzołożył dom Achaba, ponadto wymordowałeś swoich braci z domu swego ojca – lepszych od ciebie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 14, 'Oto Pan uderzy wielką plagą twój lud, twoich synów, twoje żony i cały twój majątek;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 15, 'Na ciebie też przyjdzie ciężka choroba, choroba wnętrzności, aż z powodu choroby dzień za dniem będą wypływać twoje wnętrzności.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 16, 'Pan pobudził również przeciw Joramowi ducha Filistynów i Arabów, którzy mieszkali obok Etiopczyków;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 17, 'Wtargnęli oni do Judy, spustoszyli ją i zabrali cały majątek, który znajdował się w domu króla, uprowadzili też jego synów i jego żony, tak że nie pozostał mu żaden syn oprócz Jehoachaza, najmłodszego z jego synów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 18, 'Po tym wszystkim Pan dotknął go nieuleczalną chorobą wnętrzności.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 19, 'A gdy tak mijał dzień po dniu, upłynął okres dwóch lat i wypłynęły jego wnętrzności z powodu tej choroby, i umarł w ciężkich bólach. A lud nie palił mu żadnego ognia, jak to uczynił dla jego ojców.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 20, 'Miał trzydzieści dwa lata, kiedy zaczął królować, i królował osiem lat w Jerozolimie, a odszedł tak, że nikt go nie żałował. I został pogrzebany w mieście Dawida, ale nie w grobach królewskich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 1, 'Potem mieszkańcy Jerozolimy ustanowili Achazjasza, jego najmłodszego syna, królem na jego miejscu, gdyż wszystkich starszych jego braci wymordowała zgraja, która razem z Arabami wtargnęła do obozu. Tak więc zaczął królować Achazjasz, syn Jorama, króla Judy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 2, 'Achazjasz miał czterdzieści dwa lata, kiedy zaczął królować, i królował jeden rok w Jerozolimie. Jego matka miała na imię Atalia i była córką Omriego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 3, 'On również kroczył drogami domu Achaba, bo jego matka radziła mu, aby postępował niegodziwie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 4, 'Czynił więc to, co złe w oczach Pana, tak jak dom Achaba. Oni bowiem na jego zgubę byli jego doradcami po śmierci ojca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 5, 'Chodził za ich radą i wyruszył z Joramem, synem Achaba, królem Izraela, na wojnę przeciw Chazaelowi, królowi Syrii, do Ramot-Gilead. Tam Syryjczycy zranili Jorama.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 6, 'Wrócił więc, aby się leczyć w Jizreel z ran, które zadano mu w Rama, gdy walczył z Chazaelem, królem Syrii. Wtedy Azariasz, syn Jorama, króla Judy, przybył do Jizreel, aby odwiedzić Jorama, syna Achaba, bo był chory.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 7, 'A to, że przybył do Jorama, było od Boga na zgubę Achazjasza. Kiedy bowiem przybył, wyjechał z Joramem przeciw Jehu, synowi Nimsziego, którego Pan namaścił, aby wytracić dom Achaba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 8, 'I kiedy Jehu dokonywał sądu nad domem Achaba, znalazł niektórych książąt Judy i synów braci Achazjasza, którzy służyli Achazjaszowi, i zabił ich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 9, 'Potem szukał Achazjasza i pojmano go, gdy ukrywał się w Samarii. Przyprowadzili go do Jehu i zabili. Potem pogrzebali go, bo mówili: To jest syn Jehoszafata, który szukał Pana całym swoim sercem. I tak już nie było nikogo w domu Achazjasza, kto by mógł przejąć królestwo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 10, 'Kiedy Atalia, matka Achazjasza, zobaczyła, że jej syn umarł, wstała i zgładziła całe potomstwo królewskie z domu Judy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 11, 'Ale Jehoszaba, córka króla, wzięła Joasza, syna Achazjasza, wykradła go spośród synów króla, których potem zabito, i ukryła go wraz z jego mamką w pokoju sypialnym. Tak to ukryła go Jehoszaba, córka króla Jorama, żona kapłana Jehojady i siostra Achazjasza, przed Atalią, aby ta go nie zabiła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 12, 'I przebywał z nimi ukryty w domu Bożym przez sześć lat, podczas gdy Atalia królowała nad ziemią.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 1, 'W roku siódmym Jehojada umocnił się i zawarł przymierze z setnikami: Azariaszem, synem Jerochama, Izmaelem, synem Jochanana, Azariaszem, synem Obeda, Maasejaszem, synem Adajasza, i Elisafatem, synem Zikriego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 2, 'Obeszli oni ziemię Judy, zebrali Lewitów ze wszystkich miast Judy oraz naczelników rodów Izraela i przybyli do Jerozolimy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 3, 'Całe to zgromadzenie zawarło z królem przymierze w domu Bożym. I powiedział im: Oto syn króla będzie królował, tak jak Pan zapowiedział o synach Dawida.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 4, 'Oto co macie uczynić: Trzecia część z was – kapłanów i Lewitów, którzy przychodzicie w szabat – będzie odźwiernymi przy bramach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 5, 'Trzecia część będzie w domu królewskim i trzecia część będzie w bramie fundamentu. Cały zaś lud zostanie w dziedzińcach domu Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 6, 'Niech nikt nie wchodzi do domu Pana prócz kapłanów i usługujących Lewitów. Oni mogą wchodzić, gdyż są poświęceni. A cały lud niech trzyma straż Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 7, 'Lewici otoczą króla ze wszystkich stron, każdy z bronią w ręku. Ktokolwiek wejdzie do domu, poniesie śmierć. Bądźcie przy królu, gdy będzie wchodził i gdy będzie wychodził.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 8, 'I uczynili Lewici oraz cały lud Judy według wszystkiego, co rozkazał kapłan Jehojada. Każdy wziął swoich ludzi, którzy przychodzili w szabat, i tych, którzy odchodzili w szabat, bo kapłan Jehojada nie zwolnił tych zmian.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 9, 'I kapłan Jehojada rozdał setnikom włócznie, tarcze i puklerze, które należały do króla Dawida, a które znajdowały się w domu Bożym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 10, 'Ustawił też cały lud, a każdy miał broń w ręku, od prawej strony domu aż do lewej strony domu, przy ołtarzu i domu, dokoła króla.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 11, 'Wtedy wyprowadzili syna króla, włożyli mu koronę, wręczyli mu Świadectwo i ustanowili go królem. Jehojada i jego synowie namaścili go i wołali: Niech żyje król!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 12, 'Kiedy Atalia usłyszała krzyk zbiegającego się ludu, który chwalił króla, przyszła do ludu do domu Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 13, 'A gdy spojrzała, oto król stał przy kolumnie u wejścia, a wokół króla książęta i trąby. Cały lud tej ziemi radował się i dął w trąby, także śpiewacy z instrumentami muzycznymi oraz ci, którzy kierowali śpiewem. Wtedy Atalia rozdarła swoje szaty, mówiąc: Zdrada! Zdrada!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 14, 'Wówczas kapłan Jehojada rozkazał wystąpić setnikom dowodzącym wojskiem i powiedział do nich: Wyprowadźcie ją poza szeregi, a ktokolwiek pójdzie za nią, niech będzie zabity mieczem. Kapłan bowiem powiedział: Nie zabijajcie jej w domu Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 15, 'Pochwycili ją więc, a gdy przyszła do wejścia Bramy Końskiej przy domu królewskim, tam ją zabili.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 16, 'Wtedy Jehojada zawarł przymierze między nim a całym ludem i królem, aby byli ludem Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 17, 'Potem cały lud wszedł do domu Baala i zburzył go. Pokruszyli jego ołtarze i posągi, a Mattana, kapłana Baala, zabili przed ołtarzami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 18, 'I Jehojada ustanowił przełożonych nad domem Pana pod władzą kapłanów i Lewitów, których Dawid podzielił w domu Pana, aby z radością i pieśniami składali Panu całopalenia, jak jest napisane w Prawie Mojżesza, według rozporządzenia Dawida.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 19, 'Postawił też odźwiernych przy bramach domu Pana, aby nie wchodził nikt, kto byłby w jakikolwiek sposób nieczysty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 20, 'Potem wziął setników, dostojników i przełożonych ludu oraz cały lud ziemi i wyprowadzili króla z domu Pana. Przeszli przez bramę wyższą do domu królewskiego i posadzili króla na tronie królestwa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 21, 'I radował się cały lud ziemi. A miasto zaznało pokoju, gdy Atalię zabito mieczem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 1, 'Joasz miał siedem lat, kiedy zaczął królować, i królował czterdzieści lat w Jerozolimie. Jego matka miała na imię Sibia, była z Beer-Szeby.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 2, 'I Joasz czynił to, co dobre w oczach Pana, przez wszystkie dni kapłana Jehojady.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 3, 'A Jehojada dał mu dwie żony; i spłodził synów i córki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 4, 'Potem w sercu Joasza powstał zamiar, aby odnowić dom Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 5, 'Zebrał więc kapłanów i Lewitów i powiedział do nich: Wyjdźcie do miast Judy i zbierajcie od całego Izraela pieniądze na coroczną naprawę domu waszego Boga. Pospieszcie się z tym. Lewici jednak nie spieszyli się.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 6, 'Wówczas król wezwał najwyższego kapłana Jehojadę i zapytał go: Czemu nie pilnujesz Lewitów, aby przynosili z Judy i Jerozolimy ofiarę na Namiot Świadectwa ustanowioną przez Mojżesza, sługę Pana, i zgromadzenie Izraela?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 7, 'Bezbożna Atalia i jej synowie złupili bowiem dom Boży, a wszystkie rzeczy poświęcone z domu Pana oddali Baalom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 8, 'Król więc rozkazał, aby wykonano skrzynię i umieszczono ją przed bramą domu Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 9, 'I ogłoszono w Judzie i Jerozolimie, aby przynoszono Panu ofiarę nałożoną na Izraela przez Mojżesza, sługę Bożego, na pustyni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 10, 'I radowali się wszyscy książęta oraz cały lud. Przynosili ją i rzucali do tej skrzyni, aż ją napełnili.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 11, 'A kiedy Lewici przynosili skrzynię do urzędu królewskiego i gdy widzieli, że było już wiele pieniędzy, przychodził pisarz królewski oraz pełnomocnik najwyższego kapłana i wypróżniali skrzynię, a potem ją odnosili z powrotem na swoje miejsce. Tak czynili codziennie i zebrali bardzo dużo pieniędzy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 12, 'Król i Jehojada dawali je kierownikom robót domu Pana, a ci najmowali kamieniarzy i cieśli do naprawy domu Pana, a także kowali i brązowników – do umocnienia domu Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 13, 'Tak więc robotnicy pracowali i dzięki nim dzieło zostało wykonane. Doprowadzili dom Boży do właściwego stanu i umocnili go.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 14, 'A gdy skończyli, przynieśli przed króla i Jehojadę resztę pieniędzy, za które sporządzono naczynia do domu Pana: naczynia do służby i składania ofiar, czasze oraz inne naczynia złote i srebrne. I nieustannie składali całopalenia w domu Pana przez wszystkie dni Jehojady.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 15, 'Potem Jehojada zestarzał się i umarł, będąc syty dni. Miał sto trzydzieści lat, gdy umarł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 16, 'I pogrzebano go w mieście Dawida razem z królami, dlatego że czynił dobrze w Izraelu: i względem Boga, i względem jego domu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 17, 'Po śmierci Jehojady przyszli książęta Judy i pokłonili się królowi. Wtedy król ich usłuchał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 18, 'Opuścili dom Pana, Boga swoich ojców, i służyli gajom oraz posągom. Spadł więc gniew na Judę i Jerozolimę z powodu tego występku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 19, 'I posyłał do nich proroków, żeby ich nawrócić do Pana. A choć świadczyli przeciwko nim, nie usłuchali ich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 20, 'Wówczas Duch Boży zstąpił na Zachariasza, syna kapłana Jehojady, który stanął przed ludem i powiedział im: Tak mówi Bóg: Czemu przekraczacie przykazania Pana? Nie powodzi się wam. Skoro wy opuściliście Pana, on też was opuścił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 21, 'Wtedy sprzysięgli się przeciwko niemu i ukamienowali go na rozkaz króla na dziedzińcu domu Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 22, 'I nie pamiętał król Joasz o dobrodziejstwie, jakie wyświadczył mu jego ojciec Jehojada, ale zabił jego syna. Kiedy ten umierał, powiedział: Niech Pan to zobaczy i zemści się.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 23, 'A po upływie roku przeciwko niemu nadciągnęło wojsko Syrii. Przybyło do Judy i Jerozolimy i wyniszczyło z ludu wszystkich książąt, a wszystkie jego łupy posłano królowi Damaszku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 24, 'Przybyło bowiem wojsko Syrii z niewielką liczbą ludzi, a Pan wydał w ich ręce bardzo liczne wojsko, dlatego że opuścili Pana, Boga swoich ojców. I tak dokonano sądu nad Joaszem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 25, 'A gdy się od niego oddalili, zostawiając go w ciężkiej chorobie, jego słudzy sprzysięgli się przeciwko niemu, z powodu krwi synów kapłana Jehojady, i zabili go na jego łożu. Tak więc umarł i pogrzebano go w mieście Dawida, ale nie w grobach królewskich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 26, 'A oto są ci, którzy sprzysięgli się przeciw niemu: Zabad, syn Szimeata, Ammonitki, i Jehozabad, syn Szimrit, Moabitki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 27, 'O jego synach zaś, o wielkim ciężarze nałożonym na niego i o naprawie domu Bożego, jest zapisane w księdze królewskiej. I królował jego syn Amazjasz w jego miejsce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 1, 'Amazjasz miał dwadzieścia pięć lat, kiedy zaczął królować, i królował dwadzieścia dziewięć lat w Jerozolimie. Jego matka miała na imię Jehoaddan, była z Jerozolimy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 2, 'I czynił to, co dobre w oczach Pana, ale niedoskonałym sercem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 3, 'I kiedy jego królestwo było utwierdzone, zabił te spośród swoich sług, które zabiły króla, jego ojca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 4, 'Ich synów jednak nie zabił. Postąpił tak, jak jest napisane w prawie, w Księdze Mojżesza, gdzie Pan dał nakaz, mówiąc: Nie umrą ojcowie za synów ani synowie nie umrą za ojców, ale każdy umrze za swój własny grzech.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 5, 'Wtedy Amazjasz zgromadził lud Judy i ustanowił nad nim dowódców nad tysiącami i setników, według ich rodów, dla całej Judy i Beniamina. Następnie policzył tych, którzy mieli dwadzieścia lat i więcej, a było ich trzysta tysięcy wyborowych mężczyzn gotowych do boju, uzbrojonych w dzidę i tarczę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 6, 'Najął też z Izraela sto tysięcy dzielnych wojowników za sto talentów srebra.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 7, 'Lecz przybył do niego mąż Boży i powiedział: Królu, niech wojsko Izraela nie wyrusza z tobą, bo Pan nie jest z Izraelem, z nikim spośród synów Efraima.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 8, 'Ale jeśli chcesz, idź i umocnij się do bitwy, a Bóg powali cię przed wrogiem. Bóg bowiem ma moc i wspomagać, i przywieść do upadku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 9, 'Wtedy Amazjasz zapytał męża Bożego: A co mam czynić ze stoma talentami, które dałem wojsku Izraela? Mąż Boży odpowiedział: Pan może ci dać o wiele więcej niż to.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 10, 'Oddzielił więc Amazjasz to wojsko, które przybyło do niego z Efraima, aby wróciło do siebie. I rozgniewali się bardzo na Judę, i wrócili do siebie w wielkim gniewie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 11, 'Lecz Amazjasz umocnił się, wyprowadził swój lud i nadciągnął do Doliny Soli, i pobił dziesięć tysięcy synów Seiru.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 12, 'A synowie Judy uprowadzili dziesięć tysięcy żywych, przyprowadzili ich na szczyt skały i zrzucili stamtąd, tak że się wszyscy porozbijali.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 13, 'Żołnierze wojska zaś, których Amazjasz odesłał, aby nie ruszyli z nim na wojnę, wtargnęli do miast Judy, od Samarii aż do Bet-Choron. Zabili w nich trzy tysiące ludzi i zebrali wielką zdobycz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 14, 'Kiedy Amazjasz wrócił po porażce Edomitów, przyprowadził ze sobą bogów synów Seiru i postawił ich jako swoich bogów. Kłaniał się przed nimi i palił im kadzidło.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 15, 'Pan więc rozgniewał się bardzo na Amazjasza i posłał do niego proroka, który mu powiedział: Czemu szukasz bogów tego ludu, którzy nie potrafili wyrwać swojego ludu z twojej ręki?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 16, 'A gdy on do niego mówił, król mu powiedział: Czy wybrano cię doradcą króla? Przestań. Po co mają cię zabić? Prorok więc zaprzestał, ale dodał: Wiem, Bóg zamierza cię zniszczyć za to, że to uczyniłeś i nie posłuchałeś mojej rady.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 17, 'Wtedy Amazjasz, król Judy, naradził się i posłał sługę do Joasza, syna Jehoachaza, syna Jehu, króla Izraela, ze słowami: Przyjdź i spójrzmy sobie w oczy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 18, 'A Joasz, król Izraela, posłał do Amazjasza, króla Judy, odpowiedź: Oset w Libanie posłał do cedru w Libanie prośbę: Daj swoją córkę mojemu synowi za żonę. Wtedy przechodził dziki zwierz z Libanu i podeptał oset.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 19, 'Myślisz: Oto pobiłem Edomitów – dlatego uniosło się twoje serce, by się chlubić. Siedź teraz w domu. Po co masz się narażać na nieszczęście, abyś upadł ty i Juda z tobą?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 20, 'Ale Amazjasz nie posłuchał, a było to od Boga, aby ich wydać w ręce wrogów za to, że szukali bogów Edomu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 21, 'Wyruszył więc Joasz, król Izraela, i spojrzeli sobie w oczy, on i Amazjasz, król Judy, w Bet-Szemesz, które należy do Judy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 22, 'I Juda został rozgromiony przez Izraela, i każdy uciekał do swojego namiotu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 23, 'A Joasz, król Izraela, pojmał w Bet-Szemesz Amazjasza, króla Judy, syna Joasza, syna Jehoachaza, i przyprowadził go do Jerozolimy, gdzie zburzył mur Jerozolimy od Bramy Efraima aż do Bramy Narożnej – na czterysta łokci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 24, 'I zabrał całe złoto i srebro oraz wszystkie naczynia, które znajdowały się w domu Bożym u Obed-Edoma i w skarbcach domu królewskiego, a także zakładników, i wrócił do Samarii.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 25, 'Amazjasz, syn Joasza, król Judy, żył jeszcze piętnaście lat po śmierci Joasza, syna Jehoachaza, króla Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 26, 'A pozostałe dzieje Amazjasza, od pierwszych do ostatnich, czy nie są zapisane w księdze królów Judy i Izraela?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 27, 'A od czasu, kiedy Amazjasz odwrócił się od Pana, uknuli przeciwko niemu spisek w Jerozolimie. Uciekł więc do Lakisz, lecz wysłali za nim pościg do Lakisz i tam go zabili.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 28, 'Potem przywieźli go na koniach i pogrzebali go z jego ojcami w mieście Judy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 1, 'Wtedy cały lud Judy wziął Uzjasza, który miał szesnaście lat, i ustanowił go królem w miejsce jego ojca Amazjasza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 2, 'Ten odbudował Elat i przywrócił go do Judy, kiedy król już zasnął ze swoimi ojcami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 3, 'Uzjasz miał szesnaście lat, kiedy zaczął królować, i królował pięćdziesiąt dwa lata w Jerozolimie. Jego matka miała na imię Jekolia, była z Jerozolimy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 4, 'Czynił on to, co prawe w oczach Pana, według wszystkiego, co czynił jego ojciec Amazjasz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 5, 'I szukał Boga, dopóki żył Zachariasz, który miał rozeznanie w widzeniach Bożych. A przez te wszystkie dni, kiedy szukał Pana, Bóg darzył go powodzeniem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 6, 'Wyruszył do walki z Filistynami, zburzył mury Gat, Jabne i Aszdodu, a odbudował miasta w okolicy Aszdodu i w ziemi Filistynów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 7, 'Wspomagał go bowiem Bóg przeciw Filistynom i Arabom, którzy mieszkali w Gur-Baal, i przeciw Meunitom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 8, 'Ammonici dawali Uzjaszowi daniny, a sława jego imienia rozeszła się aż do wejścia do Egiptu, bo wielce się umocnił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 9, 'I Uzjasz zbudował wieże w Jerozolimie nad Bramą Narożną, nad Bramą Doliny i nad Narożnikiem i umocnił je.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 10, 'Zbudował też wieże na pustyni i wykopał wiele studni, ponieważ miał bardzo dużo stad, zarówno w dolinach, jak i na równinach, także rolników i uprawiających winnice na górach i na Karmelu. Był bowiem rozmiłowany w uprawie ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 11, 'Uzjasz miał też wojsko gotowe do bitwy, które wyruszało na wojnę w odliczonych oddziałach, według spisu dokonanego przez pisarza Jejela i urzędnika Maasejasza, pod nadzorem Chananiasza, jednego z dowódców króla.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 12, 'Całkowita liczba naczelników rodów postawionych nad dzielnymi wojownikami wynosiła dwa tysiące sześciuset.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 13, 'A pod ich rozkazami stało wojsko złożone z trzystu siedmiu tysięcy pięciuset wojowników gotowych do wojny z wielką siłą, aby wesprzeć króla przeciw wrogowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 14, 'Uzjasz przygotował całemu wojsku tarcze, włócznie, hełmy, pancerze, łuki oraz kamienie do proc.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 15, 'Sporządził w Jerozolimie machiny wojenne wymyślone przez zdolnych ludzi, aby stały na wieżach i na narożnikach w celu ciskania strzał i wielkich kamieni. Jego sława rozeszła się daleko, ponieważ doznawał cudownej pomocy, aż stał się potężny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 16, 'Ale kiedy się umocnił, uniosło się jego serce ku jego własnej zgubie. Zgrzeszył przeciw Panu, swemu Bogu, gdyż wszedł do świątyni Pana, aby palić kadzidło na ołtarzu kadzenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 17, 'Wszedł za nim kapłan Azariasz, a z nim osiemdziesięciu kapłanów Pana, odważnych mężczyzn.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 18, 'I sprzeciwili się królowi Uzjaszowi, i powiedzieli mu: Nie do ciebie, Uzjaszu, należy palenie kadzidła Panu, lecz do kapłanów, synów Aarona, którzy są poświęceni, aby palić kadzidło. Wyjdź ze świątyni. Zgrzeszyłeś bowiem i nie przynosi ci to chwały od Pana Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 19, 'Wtedy Uzjasz rozgniewał się, mając w ręku kadzielnicę, by spalić kadzidło. A gdy pałał gniewem na kapłanów, pojawił się trąd na jego czole przed kapłanami w domu Pana, przy ołtarzu kadzenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 20, 'Kiedy najwyższy kapłan Azariasz i wszyscy kapłani spojrzeli na niego, oto miał trąd na czole. Wypchnęli go więc stamtąd, a i on sam spieszył się z wyjściem, bo dotknął go Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 21, 'I tak król Uzjasz był trędowaty aż do dnia swojej śmierci i jako trędowaty mieszkał w domu odosobnienia. Został bowiem wyłączony z domu Pana. W tym czasie jego syn Jotam zarządzał domem królewskim i sądził lud ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 22, 'A pozostałe dzieje Uzjasza, od pierwszych do ostatnich, opisał prorok Izajasz, syn Amosa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 23, 'Zasnął więc Uzjasz ze swoimi ojcami i pogrzebali go z nimi na polu grobów królewskich, gdyż mówili: Trędowaty jest. A jego syn Jotam królował w jego miejsce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 1, 'Jotam miał dwadzieścia pięć lat, kiedy zaczął królować, i królował szesnaście lat w Jerozolimie. Jego matka miała na imię Jerusza, była córką Sadoka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 2, 'Czynił on to, co prawe w oczach Pana, według wszystkiego, co czynił jego ojciec Uzjasz, tylko nie wchodził do świątyni Pana. Ale lud był nadal zepsuty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 3, 'On zbudował bramę górną domu Pana i wykonał wiele prac na murach Ofelu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 4, 'Ponadto pobudował miasta w górach Judy, a w lasach pobudował zamki i wieże.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 5, 'Walczył również z królem Ammonitów i pokonał ich. Synowie Ammona dali mu tego roku sto talentów srebra i dziesięć tysięcy kor pszenicy oraz dziesięć tysięcy kor jęczmienia. Tyle samo dali mu synowie Ammona w drugim i trzecim roku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 6, 'A tak Jotam umocnił się, gdyż przygotował swoje drogi przed Panem, swoim Bogiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 7, 'A pozostałe dzieje Jotama, wszystkie jego wojny i jego drogi, są zapisane w księdze królów Izraela i Judy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 8, 'Miał dwadzieścia pięć lat, kiedy zaczął królować, i królował szesnaście lat w Jerozolimie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 9, 'Potem Jotam zasnął ze swoimi ojcami i pogrzebano go w mieście Dawida. A jego syn Achaz królował w jego miejsce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 1, 'Achaz miał dwadzieścia lat, kiedy zaczął królować, i królował szesnaście lat w Jerozolimie. Nie czynił jednak tego, co prawe w oczach Pana, jak jego ojciec Dawid.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 2, 'Chodził raczej drogami królów Izraela i sporządził lane posągi dla Baalów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 3, 'Palił też kadzidło w dolinie syna Hinnom i spalił swoich synów w ogniu, naśladując obrzydliwości pogan, których Pan wygnał przed synami Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 4, 'Składał także ofiary i palił kadzidło na wyżynach, na wzgórzach i pod każdym zielonym drzewem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 5, 'Dlatego Pan, jego Bóg, wydał go w ręce króla Syrii. Pokonali go i uprowadzili z jego ludu wielu więźniów, i przyprowadzili ich do Damaszku. Został też wydany w ręce króla Izraela, który zadał mu wielką klęskę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 6, 'Pekach, syn Remaliasza, zabił bowiem w Judzie jednego dnia sto dwadzieścia tysięcy samych dzielnych wojowników, ponieważ opuścili Pana, Boga swoich ojców.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 7, 'I Zikri, wojownik z Efraima, zabił Maasejasza, syna króla, Azrikama, przełożonego jego domu, oraz Elkanę, zastępcę króla.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 8, 'Synowie Izraela wzięli też do niewoli spośród ich braci dwieście tysięcy kobiet, synów i córek, zabrali od nich bardzo dużo łupów i uprowadzili całą zdobycz do Samarii.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 9, 'A był tam prorok Pana o imieniu Obed, który wyszedł naprzeciw wojska, kiedy wracało do Samarii, i powiedział im: Oto Pan, Bóg waszych ojców, rozgniewał się na Judę i wydał ich w wasze ręce, a wy ich wymordowaliście z wściekłością, która dosięgła aż nieba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 10, 'A teraz chcecie jeszcze podbić lud z Judy i z Jerozolimy i uczynić z niego niewolników i niewolnice. Czy sami nie macie grzechów wobec Pana, waszego Boga?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 11, 'Teraz więc posłuchajcie mnie i odeślijcie jeńców, których uprowadziliście spośród waszych braci, gdyż zapalczywość gniewu Pana wisi nad wami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 12, 'Wtedy niektórzy z naczelników spośród synów Efraima: Azariasz, syn Jochanana, Berechiasz, syn Meszillemota, Ezechiasz, syn Szalluma, i Amasa, syn Chadlaja, wystąpili przeciwko tym, którzy wracali z wojny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 13, 'I powiedzieli do nich: Nie wprowadzajcie tutaj tych jeńców, gdyż będzie to grzechem wobec Pana, którym zamierzacie nas obciążyć, dołączając go do naszych występków. Wielki bowiem jest nasz grzech i zapalczywość gniewu ciąży nad Izraelem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 14, 'Wojsko więc pozostawiło jeńców i łupy przed książętami i całym zgromadzeniem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 15, 'A mężczyźni, którzy zostali wyznaczeni imiennie, wystąpili i zajęli się jeńcami: korzystając z łupów, przyodziali wszystkich nagich, ubrali ich, dali im obuwie, nakarmili ich i napoili, i namaścili, a słabych odprowadzili na osłach. Wtedy przyprowadzili ich do Jerycha, miasta palm, do ich braci. Potem wrócili do Samarii.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 16, 'W tym czasie król Achaz posłał do królów Asyrii prośbę o pomoc.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 17, 'Znowu bowiem Edomici nadciągnęli, pobili Judę i uprowadzili jeńców.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 18, 'Ponadto Filistyni wtargnęli do miast na równinach i na południu Judy i zdobyli Bet-Szemesz, Ajjalon, Gederot, Soko i podległe im miejscowości oraz Timnę i Gimzo z podległymi im miejscowościami i tam zamieszkali.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 19, 'Pan bowiem poniżył Judę z powodu Achaza, króla Izraela, gdyż obnażył on Judę i przewrotnie zgrzeszył wobec Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 20, 'I przybył do niego Tiglat-Pileser, król Asyrii, który go raczej ucisnął, niż wspomógł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 21, 'Bo choć Achaz wziął skarby z domu Pana, z domu królewskiego oraz od książąt i dał to królowi Asyrii, ten go nie wspomógł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 22, 'A w czasie największego ucisku król Achaz grzeszył jeszcze bardziej przeciwko Panu. Taki to był król Achaz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 23, 'Składał bowiem ofiary bogom z Damaszku, którzy go pokonali, i mówił: Ponieważ bogowie królów Syrii wspomagają ich, będę im składał ofiary, aby i mnie wspomagali. Ale oni stali się przyczyną upadku dla niego i całego Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 24, 'Achaz zabrał naczynia z domu Bożego i pokruszył je. Zamknął też bramy domu Pana i pobudował sobie ołtarze po wszystkich zaułkach Jerozolimy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 25, 'W każdym mieście Judy ustanowił wyżyny, aby tam palono kadzidło innym bogom, i pobudził do gniewu Pana, Boga swoich ojców.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 26, 'A pozostałe jego dzieje i wszystkie jego drogi, od pierwszych do ostatnich, są zapisane w księdze królów Judy i Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 27, 'I Achaz zasnął ze swoimi ojcami, i pogrzebali go w mieście w Jerozolimie. Ale nie wprowadzili do grobów królów Izraela. A Ezechiasz, jego syn, królował w jego miejsce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 1, 'Ezechiasz miał dwadzieścia pięć lat, kiedy zaczął królować, i królował dwadzieścia dziewięć lat w Jerozolimie. Jego matka miała na imię Abijja, była córką Zachariasza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 2, 'A czynił to, co prawe w oczach Pana, według wszystkiego, co czynił jego ojciec Dawid.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 3, 'On to w pierwszym roku swego panowania, w pierwszym miesiącu, otworzył bramy domu Pana i naprawił je.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 4, 'Przyprowadził kapłanów i Lewitów, zgromadził ich na ulicy wschodniej;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 5, 'I powiedział do nich: Słuchajcie mnie, Lewici! Poświęćcie się teraz, poświęćcie też i dom Pana, Boga waszych ojców, i usuńcie plugastwo ze świątyni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 6, 'Nasi ojcowie bowiem zgrzeszyli i czynili to, co złe w oczach Pana, naszego Boga. Opuścili go, odwrócili swoje oblicze od przybytku Pana i odwrócili się do niego tyłem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 7, 'Zamknęli też bramy przedsionka, pogasili lampy, nie palili kadzidła ani nie składali Bogu Izraela ofiar całopalnych w świątyni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 8, 'Dlatego gniew Pana spadł na Judę i Jerozolimę i Pan wydał ich na rozproszenie, na zdumienie i na pośmiewisko, jak sami widzicie swoimi oczami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 9, 'Oto bowiem z tego powodu nasi ojcowie polegli od miecza, a naszych synów, nasze córki i żony uprowadzono do niewoli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 10, 'Teraz więc postanowiłem zawrzeć przymierze z Panem, Bogiem Izraela, aby odwrócił od nas zapalczywość swojego gniewu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 11, 'Moi synowie, nie bądźcie już niedbali, gdyż Pan wybrał was, abyście stali przed nim i służyli mu, abyście byli jego sługami i palili kadzidło.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 12, 'Powstali więc Lewici: Machat, syn Amasaja, Joel, syn Azariasza, z synów Kehata; a z synów Merariego: Kisz, syn Abdiego, i Azariasz, syn Jehallela; a z Gerszonitów: Joach, syn Zimmy, i Eden, syn Joacha;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 13, 'Z synów Elisafana: Szimri i Jejel; z synów Asafa: Zachariasz i Mattaniasz;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 14, 'Z synów Hemana: Jechiel i Szimei; z synów Jedutuna: Szemajasz i Uzziel.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 15, 'I zgromadzili swoich braci, poświęcili się i przyszli zgodnie z rozkazem króla oraz ze słowami Pana, aby oczyścić dom Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 16, 'Wtedy kapłani weszli do wnętrza domu Pana, aby go oczyścić, i wynieśli na dziedziniec domu Pana wszelkie plugastwo, które znaleźli w świątyni Pana. Następnie Lewici zabierali to i wynosili precz do potoku Cedron.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 17, 'Zaczęli poświęcenie w pierwszym dniu pierwszego miesiąca, a ósmego dnia tego miesiąca weszli do przedsionka Pana. Poświęcali dom Pana przez osiem dni i dokończyli szesnastego dnia pierwszego miesiąca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 18, 'Potem poszli do króla Ezechiasza i powiedzieli: Oczyściliśmy cały dom Pana, ołtarz całopalenia i wszystkie jego przedmioty, stół pokładny i wszystkie jego naczynia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 19, 'Wszystkie też naczynia, które król Achaz odrzucił podczas swojego panowania, kiedy zgrzeszył, przygotowaliśmy i poświęciliśmy, a oto są przed ołtarzem Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 20, 'Wstał więc król Ezechiasz o poranku, zgromadził naczelników miasta i poszedł do domu Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 21, 'I przyprowadzono mu siedem cielców, siedem baranów, siedem jagniąt i siedem kozłów na ofiarę za grzech, za królestwo, za świątynię i za Judę. I rozkazał kapłanom, synom Aarona, by złożyli je na ołtarzu Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 22, 'Zabito więc woły, a kapłani wzięli krew i pokropili ołtarz. Zabili też barany i pokropili ołtarz ich krwią. Zabili także jagnięta i pokropili ołtarz ich krwią.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 23, 'Następnie przyprowadzili przed króla i zgromadzenie kozły na ofiarę za grzech, a oni włożyli na nie swoje ręce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 24, 'Potem kapłani je zabili i dokonali na ołtarzu oczyszczenia ich krwią na przebłaganie za całego Izraela. Król bowiem rozkazał złożyć całopalenie i ofiarę za grzech za całego Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 25, 'Postawił też Lewitów w domu Pana z cymbałami, cytrami i harfami, według rozkazu Dawida, Gada, widzącego króla, oraz proroka Natana, gdyż był to rozkaz Pana przez jego proroków.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 26, 'Stanęli więc Lewici z instrumentami Dawida, a kapłani z trąbami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 27, 'I Ezechiasz rozkazał złożyć całopalenie na ołtarzu. A gdy rozpoczęło się całopalenie, zaczęto też śpiewać Panu przy dźwiękach trąb i instrumentów Dawida, króla Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 28, 'Wtedy całe zgromadzenie oddało pokłon, śpiewacy śpiewali i trębacze trąbili. To wszystko trwało aż do końca całopalenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 29, 'A gdy skończyło się całopalenie, król oraz wszyscy, którzy z nim byli, uklękli i oddali pokłon.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 30, 'Wówczas król Ezechiasz i książęta rozkazali Lewitom, by wysławiali Pana słowami Dawida i Asafa widzącego. I wysławiali z wielką radością, kłaniali się i oddali pokłon.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 31, 'Potem Ezechiasz powiedział: Teraz poświęciliście się Panu. Przystąpcie i przyprowadźcie ofiary pojednawcze i dziękczynne do domu Pana. Zgromadzenie przyprowadziło więc ofiary pojednawcze i dziękczynne, a każdy, kto pragnął – ofiary na całopalenie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 32, 'Liczba ofiar na całopalenie, które przyprowadziło zgromadzenie, wynosiła siedemdziesiąt wołów, sto baranów i dwieście jagniąt – wszystko to na całopalenie dla Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 33, 'Jako dary poświęconych było: sześćset wołów i trzy tysiące owiec.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 34, 'Lecz kapłanów było zbyt mało i nie zdołali obedrzeć ze skóry wszystkich ofiar całopalnych. Pomagali im więc ich bracia Lewici, dopóki nie dokończyli tej pracy i dopóki nie poświęcili się inni kapłani. Lewici bowiem bardziej ochotnie poświęcili się niż kapłani.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 35, 'Ponadto było też wiele ofiar całopalnych, z tłuszczem ofiar pojednawczych i z ofiarami z płynów na każde całopalenie. Tak została ustawiona służba w domu Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 36, 'I Ezechiasz wraz z całym ludem radował się z tego, co Bóg przygotował ludowi, gdyż ta rzecz stała się nieoczekiwanie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 1, 'Potem Ezechiasz rozesłał posłańców do całego Izraela i Judy, a do Efraima i Manassesa napisał także listy, aby przybyli do domu Pana w Jerozolimie i obchodzili święto Paschy dla Pana, Boga Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 2, 'Król bowiem postanowił wraz z książętami i całym zgromadzeniem w Jerozolimie, aby obchodzić święto Paschy w drugim miesiącu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 3, 'Gdyż nie mogli go obchodzić w owym czasie, ponieważ liczba poświęconych kapłanów nie była wystarczająca, a i lud nie zgromadził się jeszcze w Jerozolimie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 4, 'Sprawa ta podobała się królowi i całemu zgromadzeniu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 5, 'Postanowili więc ogłosić w całym Izraelu, od Beer-Szeby aż do Dan, aby przybyto do Jerozolimy obchodzić święto Paschy dla Pana, Boga Izraela. Już dawno bowiem go nie obchodzili, jak to było przepisane.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 6, 'Ruszyli więc posłańcy z listami od króla i od jego książąt po całym Izraelu i Judzie, zgodnie z rozkazem króla, mówiąc: Synowie Izraela! Powróćcie do Pana, Boga Abrahama, Izaaka i Izraela, a on powróci do ostatków, które spośród was ocalały z rąk królów Asyrii.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 7, 'I nie bądźcie jak wasi ojcowie i jak wasi bracia, którzy zgrzeszyli przeciwko Panu, Bogu swoich ojców, który wydał ich na spustoszenie, jak to sami widzicie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 8, 'Teraz więc nie zatwardzajcie waszego karku, jak wasi ojcowie. Poddajcie się Panu, przyjdźcie do jego świątyni, którą poświęcił na wieki, i służcie Panu, waszemu Bogu, a odstąpi od was zapalczywość jego gniewu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 9, 'Jeśli bowiem powrócicie do Pana, wasi bracia i synowie otrzymają miłosierdzie u tych, którzy uprowadzili ich w niewolę, tak że powrócą do tej ziemi, bo Pan, wasz Bóg, jest łaskawy i miłosierny i nie odwróci od was swojego oblicza, jeśli powrócicie do niego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 10, 'A gdy posłańcy chodzili od miasta do miasta przez ziemię Efraima i Manassesa aż do Zebulona, naśmiewano się z nich i szydzono.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 11, 'Niektórzy jednak z Aszera, Manassesa i Zebulona ukorzyli się i przyszli do Jerozolimy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 12, 'W Judzie też działała ręka Boża, dając im jedno serce, aby wypełnili rozkaz króla i książąt, według słowa Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 13, 'I zebrało się w Jerozolimie wielu ludzi, aby obchodzić w drugim miesiącu Święto Przaśników. Było to niezmiernie wielkie zgromadzenie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 14, 'Wtedy powstali i usunęli ołtarze, które były w Jerozolimie, wszystkie też ołtarze, na których palono kadzidło, usunęli i wrzucili do potoku Cedron.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 15, 'Potem zabili baranka paschalnego czternastego dnia, w drugim miesiącu. A kapłani i Lewici, będąc zawstydzeni, poświęcili się i przyprowadzili całopalenia do domu Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 16, 'I stali na swoich miejscach według swego urzędu i według prawa Mojżesza, męża Bożego. Kapłani kropili krwią, którą brali z rąk Lewitów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 17, 'Wielu bowiem było w zgromadzeniu, którzy jeszcze się nie poświęcili, dlatego Lewici ofiarowali baranki paschalne za każdego nieczystego, aby go poświęcić Panu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 18, 'Bo wielka liczba tego ludu, zwłaszcza wielu z Efraima, Manassesa, Issachara i Zebulona, nie była oczyszczona i jedli baranka paschalnego niezgodnie z przepisami. Lecz Ezechiasz modlił się za nich, mówiąc: Niech dobrotliwy Pan przebaczy każdemu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 19, 'Kto przygotował swoje serce, aby szukać Boga, Pana Boga swoich ojców, choćby nie był oczyszczony według oczyszczenia świątyni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 20, 'I Pan wysłuchał Ezechiasza, i uzdrowił lud.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 21, 'Tak więc synowie Izraela, którzy byli w Jerozolimie, obchodzili Święto Przaśników przez siedem dni z wielką radością. A Lewici i kapłani wysławiali Pana każdego dnia, śpiewając Panu przy głośnych instrumentach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 22, 'Wtedy Ezechiasz przemówił łaskawie do wszystkich Lewitów, którzy wykazywali dobre rozeznanie w sprawach Pana. I jedli przez siedem dni tego święta, składając ofiary pojednawcze i wyznając grzechy Panu, Bogu swoich ojców.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 23, 'Potem całe zgromadzenie postanowiło obchodzić święto przez drugie siedem dni. Obchodzili więc święto z radością przez kolejne siedem dni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 24, 'Ezechiasz bowiem, król Judy, dał zgromadzeniu tysiąc cielców i siedem tysięcy owiec, a książęta dali zgromadzeniu tysiąc cielców i dziesięć tysięcy owiec. I poświęciło się bardzo wielu kapłanów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 25, 'Tak więc radowało się całe zgromadzenie Judy, kapłani, Lewici oraz całe zgromadzenie, które przybyło z Izraela, a także przybysze, którzy przyszli z ziemi Izraela, i ci, którzy mieszkali w Judzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 26, 'I panowała wielka radość w Jerozolimie, gdyż od czasów Salomona, syna Dawida, króla Izraela, nic podobnego nie wydarzyło się w Jerozolimie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 27, 'Potem powstali kapłani i Lewici i błogosławili ludowi. A ich głos został wysłuchany i ich modlitwa dotarła do świętego przybytku Pana, do nieba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 1, 'A gdy to wszystko się zakończyło, cały lud Izraela, który tam się znajdował, wyruszył do miast Judy i potłukł posągi, wyciął gaje, i zburzył do szczętu wyżyny oraz ołtarze w całej Judzie i Beniaminie, w Efraimie i Manassesie. Potem wszyscy synowie Izraela wrócili, każdy do swojej posiadłości i do swego miasta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 2, 'I Ezechiasz ustanowił zmiany kapłanów i Lewitów według ich podziałów, każdego według jego służby, kapłanów i Lewitów do składania całopaleń i ofiar pojednawczych, aby służyli i dziękowali Panu, a także wysławiali go w bramach jego obozu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 3, 'Przeznaczył także część z majątku królewskiego na całopalenia poranne i wieczorne, na całopalenia w szabaty, nów księżyca i w uroczyste święta, jak to napisane jest w Prawie Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 4, 'Rozkazał też ludowi mieszkającemu w Jerozolimie, aby oddawał należny dział kapłanom i Lewitom, aby mogli wytrwać w prawie Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 5, 'A gdy ten rozkaz rozszedł się, synowie Izraela przynieśli pod dostatkiem pierwocin zboża, moszczu, oliwy, miodu oraz wszelkich płodów rolnych, przynieśli także obfite dziesięciny ze wszystkiego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 6, 'Ponadto synowie Izraela i Judy, którzy mieszkali w miastach Judy, również przynieśli dziesięcinę z wołów i owiec oraz dziesięcinę z rzeczy świętych poświęconych Panu, ich Bogu, i składali to wszystko na stosy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 7, 'W trzecim miesiącu rozpoczęli układać te stosy, a w siódmym miesiącu zakończyli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 8, 'Kiedy przyszedł Ezechiasz wraz z książętami i zobaczyli te stosy, błogosławili Panu i jego ludowi Izraelowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 9, 'Wtedy Ezechiasz wypytywał kapłanów i Lewitów o te stosy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 10, 'Odpowiedział mu Azariasz, najwyższy kapłan z domu Sadoka: Kiedy zaczęto przynosić te ofiary do domu Pana, jedliśmy i nasyciliśmy się, a jeszcze wiele pozostało, gdyż Pan błogosławił swojemu ludowi, a pozostało tego wiele.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 11, 'Rozkazał więc Ezechiasz, aby przygotowano spichlerze w domu Pana. I przygotowano je;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 12, 'I złożono tam wiernie ofiary, dziesięciny i rzeczy poświęcone. Przełożonym nad nimi był Konaniasz, Lewita, a jego brat Szimei był drugi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 13, 'A Jechiel, Azariasz, Nachat, Asahel, Jerimot, Jozabad, Eliel, Ismakiasz, Machat i Benajasz byli nadzorcami pod kierunkiem Konaniasza i jego brata Szimejego, zgodnie z rozkazem króla Ezechiasza i Azariasza, przełożonego domu Bożego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 14, 'Kore, syn Jimny, Lewita, odźwierny przy bramie wschodniej, czuwał nad dobrowolnymi ofiarami dla Boga, rozdzielał ofiary Pana i rzeczy najświętsze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 15, 'Jego pomocnikami byli: Eden, Miniamin, Jeszua, Szemejasz, Amariasz i Szekaniasz, w miastach kapłanów, aby wiernie rozdawać zaopatrzenie swoim braciom według ich zmian, zarówno wielkiemu, jak i małemu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 16, 'A także mężczyznom z ich rodowodu w wieku od trzech lat wzwyż, każdemu wchodzącemu do domu Pana, dzienny dział za ich służbę, według ich obowiązków i zmian;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 17, 'Zarówno tym, którzy spośród rodowodu kapłańskiego byli policzeni według ich rodów, jak i Lewitom od dwudziestego roku życia wzwyż, według ich obowiązków i zmian;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 18, 'Oraz wszystkim dzieciom, żonom, synom i córkom z ich rodu, wśród całego zgromadzenia. Oni bowiem, pełniąc swój urząd, poświęcali się w świętości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 19, 'Także i synom Aarona, kapłanom mieszkającym na polach pastwisk ich miast, we wszystkich miastach, tym mężczyznom, wyznaczonym imiennie, aby oddano należny dział wszystkim mężczyznom spośród kapłanów oraz wszystkim spisanym według rodowodów spośród Lewitów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 20, 'Tak Ezechiasz uczynił w całej Judzie i czynił to, co dobre i prawe, i prawdziwe przed Panem, swoim Bogiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 21, 'W każdej sprawie, którą rozpoczął w służbie domu Bożego, w prawie i przykazaniach, by szukać swojego Boga, czynił wszystko z całego serca, i szczęściło mu się.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 1, 'Po tych sprawach oraz ich ustanowieniu nadciągnął Sennacheryb, król Asyrii, wkroczył do Judy, rozbił obóz naprzeciwko warownych miast i zamierzał je zdobyć dla siebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 2, 'Gdy Ezechiasz zobaczył, że nadciągnął Sennacheryb i że ma zamiar walczyć przeciw Jerozolimie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 3, 'Naradzał się ze swoimi książętami i wojownikami, aby zatkać źródła wód, które były za miastem, a oni pomogli mu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 4, 'Zebrał się więc wielki lud, który zatkał wszystkie źródła oraz potok płynący przez środek ziemi, mówiąc: Czemu nadciągający królowie Asyrii mieliby znaleźć tak wiele wody?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 5, 'Pokrzepił się i odbudował cały zburzony mur, wznosząc go aż do wież, do tego drugi zewnętrzny mur. Umocnił także Millo w mieście Dawida i sporządził wiele włóczni oraz tarcz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 6, 'Ustanowił też dowódców wojska nad ludem, których zgromadził przy sobie na placu bramy miejskiej, i mówił do nich łagodnie:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 7, 'Umacniajcie się i bądźcie mężni, nie bójcie się ani nie lękajcie widoku króla Asyrii ani widoku całego mnóstwa, które jest z nim. Więcej bowiem jest z nami aniżeli z nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 8, 'Z nim jest ramię cielesne, lecz z nami jest Pan, nasz Bóg, aby nam pomóc, ratować nas i prowadzić nasze wojny. Lud więc zaufał słowom Ezechiasza, króla Judy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 9, 'Potem Sennacheryb, król Asyrii, podczas gdy zdobywał Lakisz wraz z całym swoim wojskiem, posłał swoje sługi do Jerozolimy, do Ezechiasza, króla Judy, oraz do wszystkich z Judy, którzy byli w Jerozolimie, aby oznajmić:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 10, 'Tak mówi Sennacheryb, król Asyrii: W czym pokładacie swoją ufność, że pozostajecie w oblężonej Jerozolimie?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 11, 'Czy Ezechiasz nie zwodzi was, abyście wydali siebie na śmierć z głodu i pragnienia, mówiąc: Pan, nasz Bóg, wybawi nas z ręki króla Asyrii?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 12, 'Czy to nie ten Ezechiasz zniósł jego wyżyny i ołtarze, po czym rozkazał Judzie i Jerozolimie: Przed jednym tylko ołtarzem będziecie oddawać pokłon i na nim palić kadzidło?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 13, 'Czy nie wiecie, co ja i moi ojcowie uczyniliśmy wszystkim ludom innych ziem? Czyż bogowie narodów tych ziem mogli w jakiś sposób wyrwać ich ziemie z mojej ręki?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 14, 'Kto spośród wszystkich bogów tych narodów, które moi ojcowie wytracili, mógł wybawić swój lud z mojej ręki, aby też wasz Bóg mógł wyrwać was z mojej ręki?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 15, 'Teraz więc nie dajcie się zwodzić Ezechiaszowi i niech was nie łudzi w ten sposób ani mu nie wierzcie, gdyż żaden bóg spośród wszystkich narodów i królestw nie mógł wyrwać swego ludu z mojej ręki i z ręki moich ojców. Tym bardziej wasz Bóg nie wyrwie was z mojej ręki!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 16, 'Jego słudzy jeszcze więcej mówili przeciw Panu Bogu i przeciwko jego słudze Ezechiaszowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 17, 'Napisał też listy, aby znieważać Pana, Boga Izraela, mówiąc przeciwko niemu tymi słowami: Jak bogowie narodów innych ziemi nie wyrwali swego ludu z mojej ręki, tak Bóg Ezechiasza nie wyrwie swego ludu z mojej ręki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 18, 'Potem wołali donośnym głosem w języku hebrajskim do ludu Jerozolimy, który był na murze, aby go przestraszyć i przerazić, i tak zdobyć miasto.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 19, 'A mówili o Bogu Jerozolimy jak o bogach narodów ziemi, którzy są dziełem rąk ludzkich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 20, 'Z tego powodu król Ezechiasz i prorok Izajasz, syn Amosa, modlili się i wołali do nieba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 21, 'I Pan posłał Anioła, który wytracił wszystkich dzielnych wojowników, dowódców i naczelników w obozie króla Asyrii. Okryty wstydem, wrócił on do swojej ziemi. A gdy wszedł do domu swojego boga, ci, którzy wyszli z jego bioder, zabili go tam mieczem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 22, 'Tak więc Pan wybawił Ezechiasza i mieszkańców Jerozolimy z rąk Sennacheryba, króla Asyrii, i z rąk wszystkich innych wrogów, i zapewnił im pokój ze wszystkich stron.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 23, 'Wtedy wielu przynosiło Panu ofiary do Jerozolimy oraz kosztowne dary dla Ezechiasza, króla Judy. A od tego czasu był wielce poważany w oczach wszystkich narodów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 24, 'W tych dniach Ezechiasz śmiertelnie zachorował. Modlił się do Pana, a on przemówił do niego i dał mu znak.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 25, 'Ezechiasz jednak nie odwdzięczył się za dobrodziejstwa, które zostały mu wyświadczone, gdyż jego serce uniosło się pychą. Dlatego powstał gniew przeciw niemu i przeciw Judzie oraz Jerozolimie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 26, 'Ale Ezechiasz ukorzył się za wyniosłość swojego serca – on i mieszkańcy Jerozolimy – i nie spadł na nich gniew Pana za dni Ezechiasza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 27, 'Ezechiasz posiadał bardzo dużo bogactwa i wielką sławę. Uczynił sobie skarbce na srebro i złoto, drogie kamienie, wonności, tarcze oraz wszelkie kosztowne przedmioty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 28, 'Miał też spichlerze na zbiory zboża, wina i oliwy, obory dla wszelkiego gatunku bydła i zagrody dla trzód.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 29, 'Pobudował sobie miasta i miał liczne stada owiec i wołów, gdyż Bóg dał mu wielki majątek.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 30, 'To właśnie Ezechiasz zatkał źródło wód w górnym Gichonie i przeprowadził je dołem po zachodniej stronie miasta Dawida. I powodziło się Ezechiaszowi we wszystkich jego działaniach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 31, 'Jednak z powodu posłów książąt Babilonu wysłanych do niego, aby dowiedzieć się o znaku, który się wydarzył w ziemi, opuścił go Bóg, aby wystawić go na próbę i poznać wszystko, co było w jego sercu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 32, 'Ale pozostałe dzieje Ezechiasza i jego życzliwość są zapisane w widzeniu proroka Izajasza, syna Amosa, i w księdze królów Judy i Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 33, 'I Ezechiasz zasnął ze swoimi ojcami, i został pogrzebany w najlepszych grobach synów Dawida. A po śmierci cała Juda oraz mieszkańcy Jerozolimy złożyli mu hołd. I jego syn Manasses królował w jego miejsce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 1, 'Manasses miał dwanaście lat, kiedy zaczął królować, i królował pięćdziesiąt pięć lat w Jerozolimie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 2, 'Czynił on to, co złe w oczach Pana, według obrzydliwości tych narodów, które Pan wypędził przed synami Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 3, 'Odbudował bowiem wyżyny, które zburzył jego ojciec Ezechiasz, wznosił ołtarze dla Baalów, posadził gaje i oddawał pokłon całemu zastępowi nieba, i służył im.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 4, 'Zbudował też ołtarze w domu Pana, o którym Pan powiedział: W Jerozolimie będzie moje imię na wieki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 5, 'Ponadto zbudował ołtarze całemu zastępowi nieba w obydwu dziedzińcach domu Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 6, 'Przeprowadził swoich synów przez ogień w dolinie syna Hinnom. Uprawiał wróżbiarstwo, czary i magię, ustanowił czarowników i czarnoksiężników. Bardzo dużo złego czynił w oczach Pana, pobudzając go do gniewu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 7, 'Postawił też posąg rzeźbiony, który wykonał, w domu Bożym, o którym Bóg powiedział do Dawida i do jego syna Salomona: W tym domu i w Jerozolimie, które wybrałem spośród wszystkich pokoleń Izraela, umieszczę swoje imię na wieki;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 8, 'A już nie dopuszczę, by noga Izraela opuściła ziemię, którą przeznaczyłem waszym ojcom, jeśli tylko pilnie będą przestrzegali wszystkiego, co im nakazałem, według całego prawa, nakazów i ustaw przekazanych przez Mojżesza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 9, 'Manasses zwiódł Judę i mieszkańców Jerozolimy tak, że postępowali gorzej niż narody, które Pan wytracił przed synami Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 10, 'Chociaż bowiem Pan mówił do Manassesa i do jego ludu, oni nie słuchali.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 11, 'Dlatego Pan sprowadził na nich dowódców wojska króla Asyrii, którzy pojmali Manassesa spośród cierni, zakuli go w łańcuchy i zaprowadzili do Babilonu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 12, 'Kiedy znalazł się w ucisku, modlił się do Pana, swego Boga, i bardzo się ukorzył przed Bogiem swoich ojców;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 13, 'I modlił się do niego. A on dał się przebłagać, wysłuchał jego modlitwy i przywrócił go do Jerozolimy, do jego królestwa. Wtedy Manasses uznał, że Pan jest Bogiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 14, 'Potem zbudował zewnętrzny mur miasta Dawida, na zachód w kierunku Gichonu, w dolinie, aż do wejścia do Bramy Rybnej, otoczył nim Ofel i wzniósł go bardzo wysoko. Ustanowił też dowódców we wszystkich warownych miastach Judy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 15, 'Usunął również cudzych bogów i posąg z domu Pana oraz wszystkie ołtarze, które zbudował na górze domu Pana i w Jerozolimie, następnie wyrzucił poza miasto.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 16, 'Odnowił ołtarz Pana i złożył na nim ofiary pojednawcze i dziękczynne, a nakazał Judzie służyć Panu, Bogu Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 17, 'Lud jednak jeszcze składał ofiary na wyżynach, ale tylko Panu, swemu Bogu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 18, 'A pozostałe dzieje Manassesa, jego modlitwa do swojego Boga i słowa widzących, którzy przemawiali do niego w imię Pana, Boga Izraela, są zapisane w księdze królów Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 19, 'Jego modlitwa, to, jak został wysłuchany, każdy jego grzech, każde przewinienie oraz miejsca, na których zbudował wyżyny i wystawił gaje i posągi, zanim się ukorzył, są zapisane w księgach widzących.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 20, 'Potem Manasses zasnął ze swoimi ojcami i pogrzebano go w jego domu, a jego syn Amon królował w jego miejsce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 21, 'Amon miał dwadzieścia dwa lata, kiedy zaczął królować, i królował dwa lata w Jerozolimie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 22, 'I czynił to, co złe w oczach Pana, tak jak czynił jego ojciec Manasses. Amon bowiem składał ofiary wszystkim posągom, które sporządził jego ojciec Manasses, i służył im.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 23, 'A nie ukorzył się przed Panem, tak jak ukorzył się jego ojciec Manasses. Przeciwnie, Amon grzeszył coraz bardziej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 24, 'I jego słudzy sprzysięgli się przeciwko niemu, i zabili go w jego domu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 25, 'Ale lud tej ziemi zabił wszystkich, którzy sprzysięgli się przeciw królowi Amonowi, a potem ustanowił jego syna Jozjasza królem w jego miejsce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 1, 'Jozjasz miał osiem lat, kiedy zaczął królować, i królował trzydzieści jeden lat w Jerozolimie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 2, 'Czynił on to, co prawe w oczach Pana, chodząc drogami swego ojca Dawida, i nie zbaczał z nich ani na prawo, ani na lewo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 3, 'Bo w ósmym roku swojego królowania, gdy był jeszcze chłopcem, zaczął szukać Boga swego ojca Dawida, a w dwunastym roku zaczął oczyszczać Judę i Jerozolimę z wyżyn, gajów, rzeźbionych i odlewanych posągów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 4, 'Na jego oczach zburzono ołtarze Baalów i ściął posągi słoneczne umieszczone wysoko nad nimi. Także gaje oraz rzeźbione i odlewane posągi pokruszył i starł, a ich pył rozsypał po grobach tych, którzy im składali ofiary.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 5, 'Kości kapłanów spalił na ich ołtarzach i oczyścił Judę i Jerozolimę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 6, 'Podobnie czynił w miastach Manassesa, Efraima i Symeona, aż do Neftalego, wszędzie dokoła za pomocą kilofów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 7, 'A kiedy zburzył ołtarze i gaje, starł posągi na proch i ściął wszystkie posągi słoneczne w całej ziemi Izraela, wtedy wrócił do Jerozolimy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 8, 'A w osiemnastym roku swego panowania, po oczyszczeniu ziemi i domu Pana, posłał Szafana, syna Azaliasza, Maasejasza, namiestnika miasta, oraz Joacha, syna Joachaza, kronikarza, aby naprawili dom Pana, jego Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 9, 'Kiedy przybyli do najwyższego kapłana Chilkiasza, oddali pieniądze przyniesione do domu Bożego – które Lewici, stróże bram, zebrali od synów Manassesa i Efraima, od całej reszty Izraela i od całej Judy i Beniamina – po czym wrócili do Jerozolimy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 10, 'I oddali je w ręce rzemieślników, którzy mieli nadzór nad pracami w domu Pana, a oni je wypłacili robotnikom, którzy pracowali w domu Pana, naprawiając i umacniając dom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 11, 'Wypłacili je cieślom i murarzom na zakup kamienia ciosanego i drzewa na wiązania i na podłogi domów, które zniszczyli królowie Judy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 12, 'Ci mężczyźni wykonywali tę pracę wiernie. Ich przełożonymi byli: Jachat i Obadiasz, Lewici, z synów Merariego, oraz Zachariasz i Meszullam, z synów Kehata, aby kierowali pracami, oraz każdy Lewita, który umiał grać na instrumentach muzycznych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 13, 'Postawieni byli też nad tymi, którzy nosili ciężary, i nadzorowali robotników przy każdej pracy, a spośród Lewitów byli pisarze, dozorcy i odźwierni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 14, 'A gdy wynoszono pieniądze przyniesione do domu Pana, kapłan Chilkiasz znalazł księgę Prawa Pana, przekazaną przez Mojżesza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 15, 'Wtedy Chilkiasz powiedział do pisarza Szafana: Znalazłem księgę Prawa w domu Pana. I Chilkiasz dał księgę Szafanowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 16, 'Szafan zaniósł księgę królowi i zdał mu sprawę, mówiąc: Twoi słudzy wykonują wszystko, co im poleciłeś;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 17, 'Zebrali bowiem pieniądze, które znajdowały się w domu Pana, i oddali je do rąk nadzorców i robotników.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 18, 'Ponadto pisarz Szafan powiedział królowi: Kapłan Chilkiasz dał mi księgę. I czytał ją Szafan przed królem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 19, 'A gdy król usłyszał słowa prawa, rozdarł swoje szaty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 20, 'Potem król rozkazał Chilkiaszowi, synowi Szafana, Achikamowi, synowi Micheasza, Abdonowi, a także pisarzowi Szafanowi oraz słudze króla Asajaszowi:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 21, 'Idźcie, poradźcie się Pana co do mnie i co do reszty ludu w Izraelu i Judzie w związku ze słowami tej księgi, którą znaleziono. Wielki bowiem jest gniew Pana, który został wylany na nas za to, że nasi ojcowie nie strzegli słowa Pana, aby czynić wszystko, co jest napisane w tej księdze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 22, 'Tak więc poszedł Chilkiasz wraz z tymi, którzy byli przy królu, do prorokini Chuldy, żony Szalluma, syna Tikwy, syna Chasry, strażnika szat – mieszkała ona w Jerozolimie, po drugiej stronie miasta – i opowiedzieli jej o tej sprawie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 23, 'Ona zaś powiedziała im: Tak mówi Pan, Bóg Izraela: Powiedzcie mężczyźnie, który was posłał do mnie:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 24, 'Tak mówi Pan: Oto sprowadzę nieszczęście na to miejsce i na jego mieszkańców, wszystkie przekleństwa zapisane w tej księdze, którą czytali przed królem Judy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 25, 'Za to, że mnie opuścili i palili kadzidło innym bogom, aby pobudzić mnie do gniewu wszystkimi dziełami swoich rąk. Dlatego mój gniew zostanie wylany na to miejsce i nie zagaśnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 26, 'A królowi Judy, który was posłał po radę do Pana, powiedzcie: Tak mówi Pan, Bóg Izraela, o słowach, które słyszałeś:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 27, 'Ponieważ twoje serce zmiękło i ukorzyłeś się przed obliczem Boga, gdy usłyszałeś jego słowa przeciwko temu miejscu i przeciwko jego mieszkańcom, a ukorzyłeś się przede mną, rozdarłeś swoje szaty i płakałeś przede mną, to również i ja wysłuchałem ciebie, mówi Pan;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 28, 'Oto przyłączę cię do twoich ojców i będziesz złożony w swoim grobie w pokoju, aby twoje oczy nie oglądały całego nieszczęścia, które sprowadzam na to miejsce i jego mieszkańców. I zanieśli tę odpowiedź królowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 29, 'Wtedy król posłał po wszystkich starszych Judy i Jerozolimy i zgromadził ich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 30, 'Następnie udał się do domu Pana, a wraz z nim wszyscy mężczyźni Judy, mieszkańcy Jerozolimy, kapłani i Lewici oraz cały lud, od największych do najmniejszych. I czytał do ich uszu wszystkie słowa księgi przymierza, którą znaleziono w domu Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 31, 'Potem król stanął na swoim miejscu i zawarł przymierze przed Panem, że będą szli za Panem i będą przestrzegać jego przykazań, świadectw, nakazów z całego serca, całą swoją duszą i wypełniać słowa tego przymierza, które zostały zapisane w tej księdze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 32, 'Wtedy król nakazał przystąpić do przymierza wszystkim, którzy znajdowali się w Jerozolimie i Beniaminie. I mieszkańcy Jerozolimy postąpili zgodnie z przymierzem Boga, Boga swoich ojców.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 33, 'Wówczas Jozjasz usunął wszystkie obrzydliwości ze wszystkich ziem synów Izraela i zobowiązał wszystkich, którzy się znajdowali w Izraelu, aby służyli Panu, swemu Bogu. Przez wszystkie jego dni nie odstąpili od naśladowania Pana, Boga swoich ojców.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 1, 'Potem Jozjasz obchodził w Jerozolimie święto Paschy dla Pana. I zabito baranka paschalnego czternastego dnia pierwszego miesiąca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 2, 'Ustanowił też kapłanów na swoich urzędach i zachęcił ich do służby w domu Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 3, 'I powiedział Lewitom, którzy nauczali całego Izraela i byli poświęceni Panu: Ustawcie świętą arkę w domu, który zbudował syn Dawida Salomon, król Izraela. Nie będziecie już jej dźwigać na swoich ramionach. Teraz służcie Panu, swojemu Bogu, i jego ludowi Izraela;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 4, 'Przygotujcie się według waszych rodów i według waszych zmian, jak napisał Dawid, król Izraela, i jak napisał jego syn Salomon;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 5, 'I stójcie w świątyni według podziału na rody waszych braci, którzy są z ludu, i według podziału na rody Lewitów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 6, 'Wtedy zabijcie baranka paschalnego, poświęćcie się i przygotujcie waszych braci, by wszystko czynić według słowa Pana przekazanego przez Mojżesza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 7, 'Potem Jozjasz dał ludowi jagnięta i koźlęta z trzody, wszystkie na ofiary święta Paschy dla wszystkich obecnych w liczbie trzydziestu tysięcy, oraz trzy tysiące wołów. To wszystko pochodziło z dóbr króla.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 8, 'Jego książęta złożyli dobrowolne dary ludowi, kapłanom i Lewitom: Chilkiasz, Zachariasz, Jechiel, przełożeni domu Bożego, dali kapłanom na ofiary święta Paschy dwa tysiące sześćset jagniąt i trzysta wołów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 9, 'Ponadto Konaniasz i jego bracia Szemejasz i Netaneel oraz Chaszabiasz, Jejel i Jozabad, naczelnicy z Lewitów, dali innym Lewitom na ofiary święta Paschy pięć tysięcy jagniąt i pięćset wołów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 10, 'Wszystko więc zostało przygotowane do służby, kapłani stanęli na swoich miejscach, a Lewici w swoich zmianach według rozkazu króla.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 11, 'I zabili baranki paschalne, kapłani kropili ich krwią, a Lewici obdzierali je ze skóry.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 12, 'Następnie oddzielili część z nich na całopalenie, aby dać je ludowi według podziału na rody jako ofiarę dla Pana, tak jak jest napisane w księdze Mojżesza. Podobnie też uczyniono z wołami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 13, 'I piekli baranki paschalne na ogniu według zwyczaju, inne zaś ofiary święte gotowali w garnkach, kotłach i rondlach, po czym rozdawali szybko całemu ludowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 14, 'Potem też przygotowali posiłek dla siebie i kapłanów. Kapłani bowiem, synowie Aarona, byli zajęci składaniem całopaleń i tłuszczu aż do nocy. Lewici więc przygotowali posiłek dla siebie i dla kapłanów, synów Aarona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 15, 'Śpiewacy, synowie Asafa, stali na swoich stanowiskach według rozkazu Dawida, Asafa, Hemana i Jedutuna, widzącego króla. Odźwierni też stali przy każdej bramie. Nie musieli opuszczać swojej służby, ponieważ ich bracia Lewici przygotowywali dla nich posiłki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 16, 'Tak więc cała służba została przygotowana w tym dniu, aby obchodzić święto Paschy i składać całopalenia na ołtarzu Pana według rozkazu króla Jozjasza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 17, 'Synowie Izraela, którzy tam się znajdowali, obchodzili w tym czasie święto Paschy, a Święto Przaśników przez siedem dni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 18, 'Żadne święto Paschy podobne do tego nie było obchodzone w Izraelu od czasów proroka Samuela i żaden z królów Izraela nie obchodził tak święta Paschy, jak obchodzili je Jozjasz, kapłani, Lewici, cały lud Judy i Izraela, który się tam znajdował, oraz mieszkańcy Jerozolimy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 19, 'Paschę tę obchodzono w osiemnastym roku panowania Jozjasza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 20, 'Po tym wszystkim, gdy Jozjasz naprawił dom Boży, nadciągnął Necho, król Egiptu, aby walczyć przeciw Karkemisz nad rzeką Eufrat, a Jozjasz wyruszył mu naprzeciw.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 21, 'Ale on posłał do niego swoich posłańców ze słowami: Co ja mam z tobą, królu Judy? Nie przeciw tobie ciągnę dzisiaj, lecz przeciwko domowi, który ze mną walczy. I Bóg nakazał mi, abym się pospieszył. Przestań walczyć z Bogiem, który jest ze mną, aby cię nie zniszczył.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 22, 'Ale Jozjasz nie odwrócił się od niego, lecz zmienił swoje szaty, aby z nim walczyć, i nie posłuchał słów Necho, które pochodziły z ust Boga. Tak więc wyruszył, aby walczyć na równinie Megiddo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 23, 'A łucznicy ugodzili króla Jozjasza i wtedy król powiedział do swoich sług: Wyprowadźcie mnie, bo jestem ciężko ranny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 24, 'Jego słudzy więc wyciągnęli go z rydwanu i wsadzili na inny rydwan, który należał do niego: zawieźli go do Jerozolimy i tam umarł. Potem pogrzebali go w grobach jego ojców, a cały lud Judy i Jerozolimy opłakiwał Jozjasza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 25, 'Jeremiasz też lamentował nad Jozjaszem, a wszyscy śpiewacy i śpiewaczki wspominają Jozjasza w swoich lamentacjach aż do dziś, i uczynili z tego zwyczaj w Izraelu. Oto są zapisane w lamentacjach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 26, 'A pozostałe dzieje Jozjasza, jego życzliwość według tego, co jest napisane w Prawie Pana;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 27, 'I jego czyny pierwsze i ostatnie są zapisane w księdze królów Izraela i Judy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 1, 'Wtedy lud ziemi wziął Jehoachaza, syna Jozjasza, i ustanowił go królem w miejsce jego ojca w Jerozolimie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 2, 'Jehoachaz miał dwadzieścia trzy lata, kiedy zaczął królować, i królował trzy miesiące w Jerozolimie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 3, 'Król Egiptu usunął go z tronu w Jerozolimie i nałożył na ziemię daninę w wysokości stu talentów srebra i jednego talentu złota.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 4, 'Potem król Egiptu ustanowił Eliakima, jego brata, królem nad Judą i Jerozolimą i zmienił jego imię na Joakim. A jego brata Jehoachaza Necho pojmał i uprowadził do Egiptu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 5, 'Joakim miał dwadzieścia pięć lat, kiedy zaczął królować, i królował jedenaście lat w Jerozolimie. Czynił on to, co złe w oczach Pana, swego Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 6, 'Nadciągnął przeciw niemu Nabuchodonozor, król Babilonu, i związał go łańcuchami, aby go uprowadzić do Babilonu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 7, 'Nabuchodonozor zabrał też do Babilonu część naczyń z domu Pana i złożył je w swojej świątyni w Babilonie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 8, 'A pozostałe dzieje Joakima i obrzydliwości, które czynił, i cokolwiek się znajdowało w nim, są zapisane w księdze królów Izraela i Judy. A jego syn Joachin królował w jego miejsce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 9, 'Joachin miał osiem lat, kiedy zaczął królować, i królował trzy miesiące i dziesięć dni w Jerozolimie. Czynił on to, co złe w oczach Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 10, 'Na początku roku król Nabuchodonozor posłał po niego i kazał go przyprowadzić do Babilonu, razem z kosztownymi naczyniami domu Pana, a królem nad Judą i Jerozolimą ustanowił jego brata Sedekiasza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 11, 'Sedekiasz miał dwadzieścia jeden lat, kiedy zaczął królować, i królował jedenaście lat w Jerozolimie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 12, 'Czynił on to, co złe w oczach Pana, swego Boga, i nie ukorzył się przed prorokiem Jeremiaszem, który mówił z ust Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 13, 'Zbuntował się również przeciwko królowi Nabuchodonozorowi, który go zaprzysiągł na Boga. Uczynił twardym swój kark i zatwardził swoje serce, aby się nie nawrócić do Pana, Boga Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 14, 'Również wszyscy przedniejsi kapłani oraz lud bardzo mnożyli nieprawości, naśladując wszystkie obrzydliwości pogan, i zbezcześcili dom Pana, który on poświęcił w Jerozolimie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 15, 'A Pan, Bóg ich ojców, posyłał do nich swoich posłańców, a posyłał, wstając rankiem, ponieważ litował się nad swoim ludem i nad miejscem swego przybytku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 16, 'Ale oni szydzili z posłańców Boga, lekceważyli sobie jego słowa i naśmiewali się z jego proroków, aż gniew Pana na jego lud wzmógł się tak, że nie było już żadnego ratunku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 17, 'Sprowadził więc na nich króla Chaldejczyków, który zabił mieczem ich młodzieńców w domu ich świątyni, a nie zlitował się nad młodzieńcem ani panną, ani starcem, ani sędziwym. Wydał wszystkich w jego ręce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 18, 'Wszystkie naczynia domu Bożego, wielkie i małe, skarby domu Pana i skarby królewskie, i jego książąt, wszystko to wywiózł do Babilonu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 19, 'Potem spalili dom Boży i zburzyli mur Jerozolimy; wszystkie jej pałace spalili ogniem i wszystkie jej kosztowne naczynia zniszczyli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 20, 'A tych, którzy ocaleli od miecza, król uprowadził do Babilonu, tam byli niewolnikami jego i jego synów aż do panowania króla Persji;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 21, 'Żeby wypełniło się słowo Pana wypowiedziane przez usta Jeremiasza, dopóki ziemia nie odprawiła swoich szabatów. Dopóki bowiem ziemia leżała odłogiem, wypełniła szabaty, aż się wypełniło siedemdziesiąt lat.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 22, 'A w pierwszym roku Cyrusa, króla Persji – żeby wypełniło się słowo Pana wypowiedziane przez usta Jeremiasza – Pan wzbudził ducha Cyrusa, króla Persji, aby nakazał ogłosić i rozpisać po całym swoim królestwie, co następuje:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 23, 'Tak mówi Cyrus, król Persji: Wszystkie królestwa ziemi dał mi Pan, Bóg nieba, i on rozkazał mi, abym mu zbudował dom w Jerozolimie, która jest w Judzie. Kto z całego jego ludu jest wśród was, niech Pan, jego Bóg, będzie z nim, i ten niech wyrusza w drogę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 1, 'W pierwszym roku Cyrusa, króla Persji – aby wypełniło się słowo Pana z ust Jeremiasza – Pan wzbudził ducha Cyrusa, króla Persji, tak że ogłosił ustnie po całym swoim królestwie, a także na piśmie, co następuje:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 2, 'Tak mówi Cyrus, król Persji: Pan, Bóg niebios, dał mi wszystkie królestwa ziemi. On też rozkazał mi, abym zbudował dla niego dom w Jerozolimie, która jest w Judzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 3, 'Kto więc spośród was należy do jego ludu, niech będzie z nim jego Bóg; ten niech uda się do Jerozolimy w Judzie i niech buduje dom Pana, Boga Izraela – on jest Bogiem – który jest w Jerozolimie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 4, 'A każdego, kto został w jakimkolwiek miejscu, gdzie teraz przebywa, niech ludzie tego miejsca wspomagają go srebrem, złotem, dobytkiem i bydłem, a także dobrowolnymi ofiarami dla domu Bożego, który jest w Jerozolimie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 5, 'Wtedy powstali przywódcy rodów Judy i Beniamina, kapłani i Lewici, wszyscy, których ducha Bóg pobudził, aby poszli budować dom Pana, będący w Jerozolimie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 6, 'Wszyscy, którzy mieszkali dokoła nich, wspomogli ich naczyniem srebrnym, złotem, dobytkiem, bydłem i kosztownościami, poza tym wszystkim, co dobrowolnie ofiarowano.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 7, 'Również król Cyrus wyniósł naczynia domu Pana, które Nabuchodonozor zabrał z Jerozolimy, i złożył w domu swego boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 8, 'Wyniósł je Cyrus, król Persji, przez ręce skarbnika Mitredata, który rozliczył się z nich z Szeszbassarem, księciem Judy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 9, 'A oto ich liczba: trzydzieści czasz złotych, tysiąc czasz srebrnych, dwadzieścia dziewięć noży;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 10, 'Trzydzieści złotych pucharów, czterysta dziesięć pucharów mniejszej wartości i tysiąc innych naczyń.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 11, 'Wszystkich naczyń złotych i srebrnych – pięć tysięcy czterysta. Wszystko to zabrał Szeszbassar, gdy lud powrócił z niewoli, z Babilonu do Jerozolimy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 1, 'A oto są ludzie prowincji, którzy wyszli z niewoli i wygnania, uprowadzeni do Babilonu przez Nabuchodonozora, króla Babilonu, a powrócili oni do Jerozolimy i Judy – każdy do swojego miasta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 2, 'Przybyli razem z Zorobabelem, Jeszuą, Nehemiaszem, Serajaszem, Reelajaszem, Mardocheuszem, Bilszanem, Misparem, Bigwajem, Rechumem i Baaną. A oto liczba mężczyzn ludu Izraela:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 3, 'Synów Parosza – dwa tysiące stu siedemdziesięciu dwóch;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 4, 'Synów Szefatiasza – trzystu siedemdziesięciu dwóch;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 5, 'Synów Aracha – siedmiuset siedemdziesięciu pięciu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 6, 'Synów Pachat-Moaba, synów Jeszuy i Joaba – dwa tysiące ośmiuset dwunastu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 7, 'Synów Elama – tysiąc dwustu pięćdziesięciu czterech;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 8, 'Synów Zattua – dziewięciuset czterdziestu pięciu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 9, 'Synów Zakkaja – siedmiuset sześćdziesięciu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 10, 'Synów Baniego – sześciuset czterdziestu dwóch;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 11, 'Synów Bebaja – sześciuset dwudziestu trzech;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 12, 'Synów Azgada – tysiąc dwustu dwudziestu dwóch;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 13, 'Synów Adonikama – sześciuset sześćdziesięciu sześciu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 14, 'Synów Bigwaja – dwa tysiące pięćdziesięciu sześciu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 15, 'Synów Adina – czterystu pięćdziesięciu czterech;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 16, 'Synów Atera, z linii Ezechiasza – dziewięćdziesięciu ośmiu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 17, 'Synów Besaja – trzystu dwudziestu trzech;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 18, 'Synów Jory – stu dwunastu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 19, 'Synów Chaszuma – dwustu dwudziestu trzech;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 20, 'Synów Gibbara – dziewięćdziesięciu pięciu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 21, 'Synów z Betlejem – stu dwudziestu trzech;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 22, 'Mężczyzn z Netofy – pięćdziesięciu sześciu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 23, 'Mężczyzn z Anatot – stu dwudziestu ośmiu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 24, 'Synów z Azmawet – czterdziestu dwóch;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 25, 'Synów z Kiriat-Jearim, Kefiry i Beerot – siedmiuset czterdziestu trzech;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 26, 'Synów z Rama i Geba – sześciuset dwudziestu jeden;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 27, 'Mężczyzn z Mikmas – stu dwudziestu dwóch;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 28, 'Mężczyzn z Betela i Aj – dwustu dwudziestu trzech;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 29, 'Synów Nebo – pięćdziesięciu dwóch;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 30, 'Synów Magbisza – stu pięćdziesięciu sześciu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 31, 'Synów drugiego Elama – tysiąc dwustu pięćdziesięciu czterech;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 32, 'Synów Charima – trzystu dwudziestu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 33, 'Synów z Loda, Chadida i Ono – siedmiuset dwudziestu pięciu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 34, 'Synów z Jerycha – trzystu czterdziestu pięciu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 35, 'Synów Senai – trzy tysiące sześciuset trzydziestu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 36, 'Kapłani: synów Jedajasza, z domu Jeszuy – dziewięciuset siedemdziesięciu trzech;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 37, 'Synów Immera – tysiąc pięćdziesięciu dwóch;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 38, 'Synów Paszchura – tysiąc dwustu czterdziestu siedmiu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 39, 'Synów Charima – tysiąc siedemnastu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 40, 'Lewici: synów Jeszuy i Kadmiela, synów Hodawiasza – siedemdziesięciu czterech.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 41, 'Śpiewacy: synów Asafa – stu dwudziestu ośmiu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 42, 'Synowie odźwiernych: synów Szalluma, synów Atera, synów Talmona, synów Akkuba, synów Chatity, synów Szobaja, wszystkich razem – stu trzydziestu dziewięciu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 43, 'Netinici: synów Sichy, synów Chasufy, synów Tabbaota;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 44, 'Synów Kerosa, synów Sijachy, synów Padona;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 45, 'Synów Lebany, synów Hagaby, synów Akkuba;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 46, 'Synów Chagaba, synów Szalmaja, synów Chanana;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 47, 'Synów Giddela, synów Gachara, synów Reajasza;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 48, 'Synów Resina, synów Nekody, synów Gazzama;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 49, 'Synów Uzzy, synów Paseacha, synów Besaja;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 50, 'Synów Asny, synów Mehunima, synów Nefusima;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 51, 'Synów Bakbuka, synów Chakufy, synów Charchura;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 52, 'Synów Basluta, synów Mechidy, synów Charszy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 53, 'Synów Barkosa, synów Sisery, synów Tamacha;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 54, 'Synów Nesjacha, synów Chatify;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 55, 'Synów sług Salomona, synów Sotaja, synów Sofereta, synów Perudy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 56, 'Synów Jaali, synów Darkona, synów Giddela;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 57, 'Synów Szefatiasza, synów Chattila, synów Pocheret-Hassebaima, synów Amiego;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 58, 'Wszystkich Netinitów oraz synów sług Salomona – trzystu dziewięćdziesięciu dwóch.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 59, 'A oto ci, którzy wyruszyli z Tel-Melach, Telcharsa, Keruba, Addan i Immer, ale nie mogli wykazać pochodzenia domu swoich ojców ani swego potomstwa – czy są z Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 60, 'Synów Delajasza, synów Tobiasza, synów Nekody – sześciuset pięćdziesięciu dwóch.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 61, 'A synowie kapłanów: synowie Chobajasza, synowie Kosa, synowie Barzillaja, który pojął za żonę jedną z córek Barzillaja Gileadczyka i przybrał jego imię;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 62, 'Ci szukali swego opisu w rodowodach, ale go nie znaleźli. Zostali więc jako nieczyści wykluczeni z kapłaństwa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 63, 'I Tirszata zakazał im spożywać z rzeczy najświętszych, dopóki nie powstanie kapłan z Urim i z Tummim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 64, 'Całe to zgromadzenie liczyło czterdzieści dwa tysiące trzysta sześćdziesiąt osób;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 65, 'Nie licząc ich sług i służących, których było siedem tysięcy trzysta trzydzieści siedem, a między nimi znajdowało się dwieście śpiewaków i śpiewaczek.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 66, 'Koni mieli siedemset trzydzieści sześć, mułów – dwieście czterdzieści pięć;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 67, 'Wielbłądów – czterysta trzydzieści pięć, osłów – sześć tysięcy siedemset dwadzieścia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 68, 'A niektórzy z naczelników rodów, gdy przyszli do domu Pana, który był w Jerozolimie, składali dobrowolne dary, aby odbudować dom Boży na jego miejscu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 69, 'Według swoich możliwości dali do skarbca na odbudowę sześćdziesiąt jeden tysięcy drachm złota, pięć tysięcy min srebra i sto szat kapłańskich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 70, 'A więc kapłani, Lewici i część ludu oraz śpiewacy, odźwierni i Netinici zamieszkali w swoich miastach, a cała reszta Izraela w swoich miastach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 1, 'A gdy nadszedł siódmy miesiąc, a synowie Izraela znajdowali się w miastach, zgromadził się lud jak jeden mąż w Jerozolimie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 2, 'Wtedy powstał Jeszua, syn Jocadaka, ze swymi braćmi kapłanami, oraz Zorobabel, syn Szealtiela, wraz ze swymi braćmi, i zbudowali ołtarz Boga Izraela, aby na nim składać całopalenia, jak jest napisane w Prawie Mojżesza, męża Bożego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 3, 'Potem postawili ołtarz na swoich fundamentach i chociaż bali się sąsiednich narodów, składali na nim Panu całopalenia – rano i wieczorem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 4, 'Obchodzili też Święto Namiotów, jak jest napisane, i składali codzienne całopalenia w liczbie ustalonej według zwyczaju na każdy dzień;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 5, 'Potem składali całopalenie nieustanne – zarówno w dni nowiu, jak i każde święto poświęcone Panu – oraz dary od każdego, kto składał Panu dobrowolną ofiarę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 6, 'Od pierwszego dnia siódmego miesiąca zaczęli składać Panu całopalenia, chociaż fundamenty świątyni jeszcze nie zostały położone.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 7, 'Dali też pieniądze kamieniarzom i cieślom oraz żywność, napój i oliwę Sydończykom i Tyryjczykom, aby przywozili drzewo cedrowe z Libanu morzem do Jafy, zgodnie z zezwoleniem Cyrusa, króla Persji.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 8, 'A w drugim roku po ich przybyciu do domu Bożego w Jerozolimie, w drugim miesiącu, Zorobabel, syn Szealtiela, i Jeszua, syn Jocadaka, i pozostali ich bracia kapłani i Lewici oraz wszyscy, którzy powrócili z niewoli do Jerozolimy, zaczęli odbudowę, a ustanowili Lewitów od dwudziestu lat wzwyż, aby byli nadzorcami robót wokół domu Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 9, 'I Jeszua, jego synowie i bracia: Kadmiel i jego synowie, synowie Judy, stanęli jak jeden mąż, aby kierować tymi, którzy pracowali przy budowie domu Bożego: synami Chenadada, ich synami i ich braćmi, Lewitami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 10, 'A gdy budowniczowie położyli fundamenty świątyni Pana, postawili kapłanów, ubranych w szaty i z trąbami, oraz Lewitów, synów Asafa, z cymbałami, aby chwalić Pana zgodnie z postanowieniem Dawida, króla Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 11, 'I śpiewali jedni po drugich, chwaląc Pana i dziękując mu za to, że jest dobry – że jego miłosierdzie nad Izraelem trwa na wieki. Cały lud wznosił głośny okrzyk, gdy chwalił Pana za to, że zostały położone fundamenty domu Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 12, 'Lecz wielu kapłanów, Lewitów i naczelników rodów, którzy byli starcami i widzieli tamten pierwszy dom, głośno płakało, gdy na ich oczach zakładano fundamenty tego domu, wielu natomiast innych głośno krzyczało z radości;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 13, 'Tak że lud nie mógł odróżnić głośnego krzyku radości od głośnego płaczu ludu. Lud bowiem wznosił tak wielki okrzyk, że było go słychać z daleka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 1, 'A gdy wrogowie Judy i Beniamina usłyszeli, że lud, który powrócił z niewoli, budował świątynię Panu, Bogu Izraela;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 2, 'Wówczas przybyli do Zorobabela i naczelników rodów i powiedzieli im: Będziemy budować z wami, gdyż szukamy waszego Boga tak jak wy i składamy mu ofiary od czasów Asarchaddona, króla Asyrii, który nas tu przyprowadził.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 3, 'Ale Zorobabel, Jeszua i pozostali naczelnicy rodów z Izraela odpowiedzieli im: Nie wolno wam razem z nami budować domu naszemu Bogu, ale my sami będziemy budować Panu, Bogu Izraela, jak nam rozkazał Cyrus, król Persji.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 4, 'Wtedy lud tej ziemi zaczął zniechęcać lud Judy i przeszkadzał im w budowie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 5, 'Ponadto przekupywał przeciwko nim radców, aby udaremnić ich zamiar po wszystkie dni Cyrusa, króla Persji, aż do panowania Dariusza, króla Persji.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 6, 'Za panowania Aswerusa, na początku jego panowania, napisali skargę przeciwko obywatelom Judy i Jerozolimy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 7, 'A za czasów Artakserksesa Biszlam, Mitredat, Tabeel wraz z pozostałymi towarzyszami napisali do Artakserksesa, króla Persji. List był sporządzony pismem syryjskim i przetłumaczony na język syryjski.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 8, 'Kanclerz Rechum i pisarz Szimszaj napisali do króla Artakserksesa list przeciwko Jerozolimie następującej treści:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 9, 'Kanclerz Rechum, pisarz Szimszaj i pozostali ich towarzysze: Dynajczycy, Afarsadchajczycy, Tarpelajczycy, Afarsajczycy, Arkewijczycy, Babilończycy, Susanchici, Dehawici i Elamici;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 10, 'I reszta narodów, które wielki i sławny Asnappar przyprowadził i osiedlił w miastach Samarii, oraz pozostali, którzy są za rzeką – otóż;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 11, 'To jest odpis listu, który posłali do króla Artakserksesa – Twoi słudzy, ludzie mieszkający za rzeką – otóż:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 12, 'Niech królowi będzie wiadomo, że Żydzi, którzy wyszli od ciebie, przybyli do nas, do Jerozolimy, i odbudowują to buntownicze i niegodziwe miasto, już wznosili mury i położyli fundamenty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 13, 'Niech więc będzie królowi wiadomo, że jeśli to miasto zostanie odbudowane i jego mury będą wzniesione, wtedy podatku, danin ani cła oni nie będą płacić, a to przyniesie szkodę dochodom króla.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 14, 'Teraz więc, ponieważ jesteśmy na utrzymaniu twego pałacu i nie przystoi nam patrzeć na zniewagę króla, posyłamy królowi tę wiadomość;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 15, 'Aby poszukano w księdze kronik twoich ojców, a znajdziesz w niej i dowiesz się, że to miasto jest miastem buntowniczym i przynosi szkodę królom i prowincjom i że od dawien dawna wzniecano w nim bunty. Z tego powodu to miasto zostało zburzone.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 16, 'Zawiadamiamy króla, że jeśli to miasto zostanie odbudowane i jego mury będą wzniesione, wtedy już nie będziesz miał udziału za rzeką.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 17, 'Wtedy król wysłał taką odpowiedź: Kanclerzowi Rechumowi, pisarzowi Szimszajowi i pozostałym ich towarzyszom, którzy mieszkają w Samarii, a także i pozostałym za rzeką: Pokój! Otóż:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 18, 'List, który do nas przysłaliście, został przede mną dokładnie odczytany.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 19, 'Dlatego rozkazałem, aby poszukano. I znaleziono, że to miasto od dawna powstawało przeciwko królom, a bunt i rozruchy były w nim wzniecane;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 20, 'Ponadto potężni królowie panowali nad Jerozolimą i rządzili nad wszystkimi za rzeką, i płacono im podatek, daninę i cło.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 21, 'Wydajcie więc wyrok, aby powstrzymać tych mężczyzn, żeby to miasto nie zostało odbudowane, dopóki inny rozkaz nie będzie przeze mnie wydany.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 22, 'Pilnujcie, abyście nie zaniedbali tego. Dlaczego miałoby to wzrastać na szkodę królów?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 23, 'Gdy więc odpis listu króla Artakserksesa został odczytany przed Rechumem, pisarzem Szimszajem i ich towarzyszami, udali się spiesznie do Żydów w Jerozolimie i siłą i mocą wstrzymali budowę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 24, 'W ten sposób ustała praca przy domu Bożym, który był w Jerozolimie. I została wstrzymana aż do drugiego roku panowania Dariusza, króla Persji.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 1, 'Potem prorocy Aggeusz i Zachariasz, syn Iddo, prorokowali Żydom w Judzie i w Jerozolimie w imię Boga Izraela, mówiąc do nich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 2, 'Wtedy powstali Zorobabel, syn Szealtiela, i Jeszua, syn Jocadaka, i zaczęli budować dom Boży w Jerozolimie; a z nimi prorocy Boga, którzy im pomagali.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 3, 'W tym czasie przyszli do nich Tattenaj, namiestnik zarzecza, i Szetarboznaj oraz ich towarzysze i tak mówili do nich: Kto wam rozkazał budować ten dom i wznosić jego mury?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 4, 'Odpowiedzieliśmy im, jakie są imiona tych mężczyzn, którzy pracują przy tej budowli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 5, 'Lecz oko ich Boga czuwało nad starszymi z Żydów, tak że nie mogli im przeszkadzać, dopóki sprawa ta nie dotarła do Dariusza – o niej donosili mu przez list.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 6, 'To jest odpis listu, który do króla Dariusza posłali Tattenaj, namiestnik zarzecza, Szetarboznaj i jego towarzysze Afarsachajczycy, którzy byli za rzeką.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 7, 'Posłali mu list, w którym było napisane tak: Królowi Dariuszowi wszelkiej pomyślności!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 8, 'Niech będzie królowi wiadomo, że przybyliśmy do prowincji Judy, do domu wielkiego Boga, który jest odbudowywany z wielkich kamieni, a którego ściany są wykładane drewnem. Ta praca posuwa się szybko i szczęści się w ich rękach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 9, 'Pytaliśmy wtedy tych starszych, mówiąc do nich: Kto wam rozkazał budować ten dom i wznosić te mury?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 10, 'Pytaliśmy także o ich imiona, abyśmy mogli ci je oznajmić i zapisać imiona mężczyzn, którzy stoją na ich czele.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 11, 'A tak nam odpowiedzieli: My jesteśmy sługami Boga nieba i ziemi i odbudowujemy dom, który został wzniesiony przed wieloma laty, a który zbudował i wystawił wielki król Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 12, 'Lecz gdy nasi ojcowie pobudzili do gniewu Boga nieba, on wydał ich w ręce Nabuchodonozora, króla Babilonu, Chaldejczyka, który zburzył ten dom, a lud uprowadził do niewoli w Babilonie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 13, 'Jednak w pierwszym roku Cyrusa, króla Babilonu, sam król Cyrus wydał dekret, aby odbudować ten dom Boży.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 14, 'Ponadto złote i srebrne naczynia domu Bożego, które Nabuchodonozor zabrał ze świątyni w Jerozolimie i umieścił w świątyni w Babilonie, król Cyrus wyniósł ze świątyni w Babilonie i zostały przekazane niejakiemu Szeszbassarowi, którego ustanowił namiestnikiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 15, 'I powiedział mu: Weź te naczynia, idź i złóż je w świątyni, która jest w Jerozolimie, a niech dom Boży zostanie odbudowany na swoim miejscu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 16, 'Wtedy ten Szeszbassar przyszedł i położył fundamenty domu Bożego w Jerozolimie, i od tego czasu aż do dzisiaj buduje się go, ale nie jest ukończony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 17, 'Jeśli więc król uzna to za dobrą rzecz, niech poszukają w skarbcach królewskich w Babilonie, czy rzeczywiście tak jest, że król Cyrus rozkazał, aby odbudować ten dom Boży w Jerozolimie, i niech król powiadomi nas o swej woli w tej sprawie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 1, 'Wtedy król Dariusz rozkazał, aby szukano w archiwum, gdzie przechowywano skarby w Babilonie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 2, 'I znaleziono w Achmecie, w pałacu w prowincji Medii, pewien zwój, w którym tak było napisane:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 3, 'W pierwszym roku króla Cyrusa, król Cyrus wydał dekret w sprawie domu Bożego w Jerozolimie: Dom ten ma być odbudowany, to miejsce, gdzie składano ofiary. Fundamenty mają być położone. Jego wysokość – sześćdziesiąt łokci i jego szerokość – sześćdziesiąt łokci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 4, 'Trzy rzędy z kamienia wielkiego i jeden rząd z nowego drewna. Koszty ma pokryć dom królewski.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 5, 'Ponadto złote i srebrne naczynia z domu Bożego, które zabrał Nabuchodonozor ze świątyni w Jerozolimie i przeniósł do Babilonu, mają być zwrócone i przeniesione do świątyni w Jerozolimie na swoje miejsce, i złożone w domu Bożym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 6, 'Teraz więc ty, Tattenaju, namiestniku zarzecza, Szetarboznaju, i wy, Afarsachajczycy, ich towarzysze, którzy jesteście za rzeką, trzymajcie się z dala od tego miejsca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 7, 'Zostawcie w spokoju prace nad tym domem Bożym. Niech namiestnik Żydów i starsi żydowscy odbudują ten dom Boży na swoim miejscu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 8, 'Wydaję też dekret o tym, co macie uczynić dla starszych spośród Żydów na budowę tego domu Bożego, mianowicie: koszty mają być bezzwłocznie wypłacone tym ludziom z dochodów króla, z danin pobieranych za rzeką, aby nie przestawali budować.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 9, 'Także i to, co będzie potrzebne do całopaleń dla Boga niebios: cielce, barany i jagnięta oraz pszenica, sól, wino i oliwa, według rozkazu kapłanów w Jerozolimie, niech im będzie dawane każdego dnia bez zaniedbania;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 10, 'Aby mogli składać wonne ofiary Bogu niebios i aby modlili się za życie króla i jego synów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 11, 'Ponadto wydaję taki dekret: Ktokolwiek zmieni ten rozkaz, to belka z jego domu ma być wyrwana i podniesiona, a on będzie na niej powieszony; jego dom zaś zostanie zamieniony w gnojowisko.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 12, 'A Bóg, który uczynił tam mieszkanie dla swojego imienia, niech zniszczy każdego króla i każdy naród, który by się odważył zmienić ten rozkaz i zniszczyć ten dom Boży w Jerozolimie. Ja, Dariusz, wydałem ten dekret; niech będzie wykonany bezzwłocznie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 13, 'Wtedy Tattenaj, namiestnik zarzecza, Szetarboznaj i ich towarzysze niezwłocznie uczynili tak, jak król Dariusz rozkazał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 14, 'A starsi żydowscy budowali i szczęściło im się według proroctwa Aggeusza, proroka, i Zachariasza, syna Iddo. Budowali i dokończyli dom zgodnie z rozkazem Boga Izraela oraz z rozkazem Cyrusa, Dariusza oraz Artakserksesa, króla Persji.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 15, 'I ten dom został zakończony w trzecim dniu miesiąca Adar, w szóstym roku panowania króla Dariusza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 16, 'Wówczas synowie Izraela, kapłani, Lewici oraz reszta ludu, który powrócił z niewoli, z radością obchodzili poświęcenie tego domu Bożego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 17, 'I złożyli ofiary przy poświęcaniu tego domu Bożego: sto cielców, dwieście baranów, czterysta jagniąt, a jako ofiarę za grzech za całego Izraela – dwanaście kozłów, według liczby pokoleń Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 18, 'Do służby Bożej w Jerozolimie ustanowili kapłanów – według ich oddziałów, i Lewitów – według ich zmian, jak jest napisane w księdze Mojżesza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 19, 'Ci, którzy powrócili z niewoli, obchodzili też Paschę w czternastym dniu pierwszego miesiąca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 20, 'Kapłani bowiem i Lewici oczyścili się jak jeden mąż, wszyscy byli oczyszczeni. Zabili więc baranka paschalnego dla wszystkich, którzy przybyli z niewoli, dla swoich braci kapłanów i dla siebie samych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 21, 'I spożywali to synowie Izraela, którzy powrócili z niewoli, i każdy, kto odłączył się od nieczystości pogan tej ziemi i przyłączył się do nich, aby szukać Pana, Boga Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 22, 'Przez siedem dni z radością obchodzili też Święto Przaśników, gdyż Pan napełnił ich radością i zwrócił ku nim serce króla Asyrii, aby wzmocnił ich ręce przy pracy wokół domu Bożego, Boga Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 1, 'Po tych wydarzeniach, za panowania Artakserksesa, króla Persji, Ezdrasz, syn Serajasza, syna Azariasza, syna Chilkiasza;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 2, 'Syna Szalluma, syna Sadoka, syna Achituba;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 3, 'Syna Amariasza, syna Azariasza, syna Merajota;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 4, 'Syna Zerachiasza, syna Uzziego, syna Bukkiego;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 5, 'Syna Abiszui, syna Pinchasa, syna Eleazara, syna Aarona, najwyższego kapłana;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 6, 'Tenże Ezdrasz wyruszył z Babilonu, a był człowiekiem uczonym w prawie Mojżesza, które dał Pan, Bóg Izraela. A król spełnił wszystkie jego prośby, gdyż ręka Pana, jego Boga, była nad nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 7, 'Wyruszyli też niektórzy z synów Izraela oraz z kapłanów, Lewitów, śpiewaków, odźwiernych i z Netinitów do Jerozolimy w siódmym roku króla Artakserksesa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 8, 'Ezdrasz przybył do Jerozolimy w piątym miesiącu – było to w siódmym roku króla.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 9, 'Wyruszył z Babilonu w pierwszym dniu pierwszego miesiąca, a do Jerozolimy przybył w pierwszym dniu piątego miesiąca, ponieważ była nad nim łaskawa ręka jego Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 10, 'Ezdrasz bowiem przygotował swoje serce, aby szukać prawa Pana i wykonywać je, a także by nauczać w Izraelu ustaw i sądów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 11, 'A oto odpis listu, który król Artakserkses dał Ezdraszowi, kapłanowi i uczonemu, biegłemu w słowach przykazań Pana i w jego ustawach w Izraelu:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 12, 'Artakserkses, król królów, Ezdraszowi, kapłanowi, uczonemu w prawie Boga niebios, mężowi doskonałemu, otóż;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 13, 'Wydaję dekret o tym, że każdy z ludu Izraela, spośród jego kapłanów i Lewitów w moim państwie, kto dobrowolnie pragnie udać się do Jerozolimy, może iść z tobą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 14, 'Ty bowiem zostałeś wysłany przez króla i jego siedmiu doradców, abyś według prawa swego Boga, które masz w swoim ręku, zbadał sprawy w Judei i Jerozolimie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 15, 'I abyś zaniósł srebro i złoto, które król i jego doradcy dobrowolnie ofiarowali Bogu Izraela, którego przybytek jest w Jerozolimie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 16, 'Oraz całe srebro i złoto, które otrzymasz w całej prowincji Babilonu wraz z dobrowolnymi darami od ludu i kapłanów, które dobrowolnie ofiarują na dom swego Boga w Jerozolimie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 17, 'Abyś za te pieniądze bezzwłocznie kupił cielce, barany, jagnięta wraz z przynależnymi do nich ofiarami z pokarmów i płynów i złożył je na ołtarzu domu waszego Boga w Jerozolimie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 18, 'Z pozostałym srebrem i złotem uczyńcie zaś to, co ty i twoi bracia uznacie za słuszne, tak czyńcie, według woli waszego Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 19, 'Naczynia też, które zostały ci dane do służby w domu twojego Boga, oddaj przed Bogiem w Jerozolimie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 20, 'Także i inne potrzeby do domu twojego Boga, za które przyjdzie ci zapłacić, opłać ze skarbca królewskiego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 21, 'A ja, król Artakserkses, wydaję wszystkim podskarbim zarzecza rozkaz o tym, że wszystko, czegokolwiek zażąda od was kapłan Ezdrasz, uczony w prawie Boga niebios, ma być bezzwłocznie wykonane;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 22, 'Aż do stu talentów srebra, stu kor pszenicy, stu bat wina, stu bat oliwy, a soli bez ograniczenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 23, 'Wszystko, co nakazuje Bóg niebios, ma być wykonane starannie dla domu Boga niebios, bo dlaczego ma być wzbudzony jego gniew przeciwko państwu króla i jego synów?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 24, 'Zawiadamiamy was również, że na żadnego z kapłanów, Lewitów, śpiewaków, odźwiernych, Netinitów oraz pozostałych sług tego domu Boga nie wolno nakładać podatku, danin ani cła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 25, 'A ty, Ezdraszu, według mądrości swego Boga, która jest w tobie, ustanów urzędników i sędziów, którzy będą sądzić cały lud zarzecza, wszystkich, którzy znają prawo twego Boga; a tych, którzy go nie znają, macie uczyć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 26, 'Na każdego, kto nie wykona prawa twego Boga i prawa króla, niech bezzwłocznie będzie wydany wyrok – albo śmierci, albo wygnania, albo przepadku mienia, albo więzienia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 27, 'Ezdrasz powiedział: Błogosławiony niech będzie Pan, Bóg naszych ojców, który włożył w serce króla pragnienie, aby ozdobić dom Pana, który jest w Jerozolimie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 28, 'A mnie okazał łaskę wobec króla i jego doradców oraz wszystkich możnych dostojników króla. A ja, będąc wzmocniony ręką Pana, swego Boga, która była nade mną, zgromadziłem naczelników z Izraela, aby wyruszyli ze mną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 1, 'A oto naczelnicy rodów i rodowody tych, którzy wyruszyli ze mną z Babilonu za panowania króla Artakserksesa:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 2, 'Z synów Pinchasa – Gerszom; z synów Itamara – Daniel; z synów Dawida – Chattusz;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 3, 'Z synów Szekaniasza, z synów Parosza – Zachariasz, a z nim spisanych według rodowodów było stu pięćdziesięciu mężczyzn;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 4, 'Z synów Pachat-Moaba – Elioenaj, syn Zerachiasza, a z nim dwustu mężczyzn;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 5, 'Z synów Szekaniasza – syn Jahaziela, a z nim trzystu mężczyzn;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 6, 'Z synów Adina – Ebed, syn Jonatana, a z nim pięćdziesięciu mężczyzn;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 7, 'Z synów Elama – Jeszajasz, syn Ataliasza, a z nim siedemdziesięciu mężczyzn;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 8, 'Z synów Szefatiasza – Zebadiasz, syn Mikaela, a z nim osiemdziesięciu mężczyzn;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 9, 'Z synów Joaba – Obadiasz, syn Jechiela, a z nim dwustu osiemnastu mężczyzn;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 10, 'Z synów Szelomita – syn Josifiasza, a z nim stu sześćdziesięciu mężczyzn;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 11, 'Z synów Bebaja – Zachariasz, syn Bebaja, a z nim dwudziestu ośmiu mężczyzn;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 12, 'Z synów Azgada – Johanan, syn Hakkatana, a z nim stu dziesięciu mężczyzn;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 13, 'Z synów Adonikama wyruszyli ostatni, a oto ich imiona: Elifelet, Jejel i Szemajasz, a z nimi sześćdziesięciu mężczyzn;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 14, 'Z synów Bigwaja – Utaj i Zabbud, a z nimi siedemdziesięciu mężczyzn.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 15, 'I zgromadziłem ich nad rzeką, która płynie do Achawy, i obozowaliśmy tam przez trzy dni. Potem dokonałem przeglądu ludu i kapłanów, a z synów Lewiego nie znalazłem tam żadnego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 16, 'Posłałem więc Eliezera, Ariela, Szemajasza, Elnatana, Jariba, Elnatana, Natana, Zachariasza i Meszullama, naczelników, a także Jojariba i Elnatana, ludzi rozumnych;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 17, 'I dałem przez nich polecenie Iddo, przełożonemu w miejscowości Kasifia, i przekazałem im słowa, które mieli powiedzieć do niego i jego braci Netinitów w miejscowości Kasifia; poleciłem, aby nam przyprowadzili sługi dla domu naszego Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 18, 'I ponieważ łaskawa ręka naszego Boga była nad nami, przyprowadzili do nas, człowieka rozumnego spośród synów Machliego, syna Lewiego, syna Izraela, oraz Szerebiasza wraz z jego synami i braćmi – razem osiemnaście osób;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 19, 'I Chaszabiasza, a z nim Jeszajasz spośród synów Merariego wraz z jego braćmi i ich synów – razem dwadzieścia osób;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 20, 'Ponadto spośród Netinitów, których Dawid i naczelnicy ustanowili do posługiwania Lewitom – dwieście dwadzieścia Netinitów. Ci wszyscy zostali imiennie wyznaczeni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 21, 'Wtedy tam, nad rzeką Achawa, ogłosiłem post, abyśmy ukorzyli się przed naszym Bogiem i abyśmy uprosili u niego szczęśliwą drogę dla nas, naszych dzieci i całego naszego dobytku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 22, 'Wstydziłem się bowiem prosić króla o żołnierzy i jeźdźców, aby nas w drodze ratowali przed wrogami, ponieważ powiedzieliśmy królowi: Ręka naszego Boga jest nad wszystkimi, którzy go szukają, dla ich dobra, ale jego moc i gniew przeciwko wszystkim, którzy go opuszczają.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 23, 'Pościliśmy więc i prosiliśmy o to naszego Boga. A on nas wysłuchał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 24, 'Wtedy spośród przedniejszych kapłanów wydzieliłem dwunastu: Szerebiasza, Chaszabiasza, a z nimi dziesięciu ich braci;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 25, 'I odważyłem im srebro, złoto i naczynia, czyli ofiarę dla domu naszego Boga, którą złożyli: król, jego doradcy, jego dostojnicy oraz cały Izrael tam obecny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 26, 'Odważyłem im więc do rąk sześćset pięćdziesiąt talentów srebra, sto talentów naczyń srebrnych, sto talentów złota;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 27, 'Dwadzieścia złotych pucharów, ważących po tysiąc darejków, i dwa naczynia z wybornego mosiądzu, tak piękne jak złoto.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 28, 'Potem powiedziałem do nich: Wy jesteście poświęceni Panu, naczynia także są poświęcone, a to srebro i złoto są dobrowolnym darem dla Pana, Boga waszych ojców.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 29, 'Pilnujcie i strzeżcie ich, dopóki nie odważycie ich przed przedniejszymi kapłanami, Lewitami i naczelnikami rodów Izraela w Jerozolimie, w komnatach domu Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 30, 'Wzięli więc kapłani i Lewici odważone srebro, złoto i naczynia, aby je zanieść do Jerozolimy, do domu naszego Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 31, 'Potem wyruszyliśmy znad rzeki Achawa dwunastego dnia pierwszego miesiąca, aby udać się do Jerozolimy. A ręka naszego Boga była nad nami i wyrwała nas z ręki wrogów i czyhających na nas w drodze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 32, 'I przybyliśmy do Jerozolimy, i zamieszkaliśmy tam przez trzy dni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 33, 'A czwartego dnia odważono srebro, złoto i naczynia w domu naszego Boga – do ręki Meremota, syna kapłana Uriasza, z którym był Eleazar, syn Pinchasa; z nimi też byli Jozabad, syn Jeszuy, i Noadiasz, syn Binnuja, Lewici;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 34, 'Wszystko według liczby i wagi; i zapisano wagę tego wszystkiego w tym czasie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 35, 'Następnie ci, którzy zostali pojmani, a powrócili z niewoli, złożyli Bogu Izraela ofiarę całopalną: dwanaście cielców za całego Izraela, dziewięćdziesiąt sześć baranów, siedemdziesiąt siedem jagniąt i dwanaście kozłów na ofiarę za grzech, wszystko jako całopalenie Panu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 36, 'I przekazano rozporządzenie króla jego satrapom i namiestnikom zarzecza, a ci wspomagali lud i dom Boży.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 1, 'A gdy zakończono to wszystko, przystąpili do mnie naczelnicy, mówiąc: Lud Izraela, kapłani i Lewici nie odłączyli się od narodów tych ziem; postępują według obrzydliwości Kananejczyków, Chetytów, Peryzzytów, Jebusytów, Ammonitów, Moabitów, Egipcjan i Amorytów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 2, 'Pobrali bowiem ich córki dla siebie i swoich synów, tak że święte nasienie pomieszało się z ludami tych ziem, a w tym grzechu przodowali naczelnicy i przywódcy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 3, 'Gdy to usłyszałem, rozdarłem swoją szatę i swój płaszcz i rwałem włosy ze swojej głowy i brody i siedziałem osłupiony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 4, 'I zgromadzili się wokoło mnie wszyscy, którzy drżeli przed słowem Boga Izraela z powodu przestępstwa tych, którzy powrócili z niewoli, a ja siedziałem osłupiony aż do ofiary wieczornej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 5, 'Ale w czasie ofiary wieczornej wstałem ze swego przygnębienia i w rozdartej szacie i płaszczu upadłem na kolana i wyciągnąłem swoje ręce do Pana, swojego Boga;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 6, 'I powiedziałem: Mój Boże! Wstydzę się i nie śmiem podnieść twarzy do ciebie, mój Boże. Nasze nieprawości bowiem urosły ponad głowę, a nasz grzech dosięgnął aż nieba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 7, 'Od dni naszych ojców aż do dziś tkwimy w wielkim grzechu, a z powodu naszych nieprawości my, nasi królowie i nasi kapłani zostaliśmy wydani w ręce królów tych ziem pod miecz w niewolę, na łup i wstyd na twarzy, jak to jest dzisiaj.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 8, 'Ale teraz, jakby na krótką chwilę, Pan, nasz Bóg, okazał nam łaskę, bo pozostawił nam resztkę ocalonych i dał nam mieszkanie w swoim miejscu świętym, aby nasz Bóg oświecił nasze oczy i podarował nam trochę wytchnienia od naszej niewoli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 9, 'Chociaż bowiem byliśmy niewolnikami, nasz Bóg nie opuścił nas w naszej niewoli, lecz okazał nam łaskę wobec królów Persji, aby dać nam wytchnienie, abyśmy wznieśli dom naszego Boga i naprawili jego spustoszenie, i aby dać nam mur ochrony w Judzie i Jerozolimie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 10, 'Teraz więc, o nasz Boże, co powiemy po tym wszystkim? Opuściliśmy bowiem twoje przykazania;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 11, 'Które nadałeś przez swoje sługi, proroków, mówiąc: Ziemia, do której wchodzicie, by ją wziąć w posiadanie, jest ziemią nieczystą, splamioną nieczystością ludu tych ziem przez jego obrzydliwości, który swoją nieczystością napełnił ją od końca do końca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 12, 'Dlatego nie dawajcie swoich córek ich synom ani nie bierzcie ich córek dla swoich synów, ani nie szukajcie nigdy pokoju z nimi ani ich pomyślności, abyście się wzmocnili i spożywali dobra tej ziemi oraz pozostawili ją w dziedzictwo swoim synom na wieki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 13, 'A po tym wszystkim, co spadło na nas za nasze złe czyny i nasz wielki grzech, chociaż ty, nasz Boże, wymierzyłeś nam karę mniejszą niż nasze nieprawości i dałeś nam takie wybawienie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 14, 'Czy mamy znowu przekraczać twoje przykazania i spowinowacać się z tymi obrzydliwymi narodami? Czy nie rozgniewasz się na nas aż do naszego wyniszczenia, tak że nie zostaną spośród nas ani resztka, ani ocaleni?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 15, 'Panie, Boże Izraela, ty jesteś sprawiedliwy, bo pozostajemy ocaleni, jak się to dziś okazuje. Oto stoimy przed tobą w naszym przewinieniu, choć z tego powodu nie godzi się stać przed tobą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 1, 'A gdy Ezdrasz modlił się i wyznawał grzechy z płaczem, klęcząc przed domem Bożym, zebrał się wokół niego bardzo wielki tłum mężczyzn, kobiet i dzieci z Izraela, a lud bardzo gorzko płakał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 2, 'Wtedy Szekaniasz, syn Jechiela z synów Elama, powiedział do Ezdrasza: My zgrzeszyliśmy przeciwko naszemu Bogu, bo pojęliśmy obce żony z ludu tej ziemi. Ale jest jeszcze nadzieja dla Izraela w tej sprawie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 3, 'Teraz więc zawrzyjmy przymierze z naszym Bogiem – odprawmy wszystkie żony i dzieci z nich urodzone, według rady Pana i tych, którzy drżą przed przykazaniem naszego Boga. Niech to się stanie według prawa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 4, 'Wstań, bo do ciebie należy ta sprawa, a my będziemy z tobą. Wzmocnij się i działaj.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 5, 'Wtedy Ezdrasz wstał i zaprzysiągł przedniejszych kapłanów, Lewitów i całego Izraela, by postąpili według tego słowa. I przysięgli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 6, 'Potem Ezdrasz opuścił dom Boży i udał się do komnaty Jochanana, syna Eliasziba. Kiedy tam wszedł, nie jadł chleba ani nie pił wody, gdyż smucił się z powodu przestępstwa tych, którzy powrócili z niewoli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 7, 'Następnie ogłoszono w Judzie i Jerozolimie wszystkim, którzy powrócili z niewoli, że mają zgromadzić się w Jerozolimie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 8, 'A ktokolwiek nie przyjdzie w ciągu trzech dni, według postanowienia naczelników i starszych, ten zostanie pozbawiony całego mienia, a sam będzie wykluczony ze zgromadzenia tych, którzy powrócili z niewoli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 9, 'Zgromadzili się więc wszyscy mężczyźni z Judy i Beniamina w Jerozolimie w ciągu trzech dni. Było to w dwudziestym dniu dziewiątego miesiąca. A cały lud siedział na placu przed domem Bożym, drżąc z powodu tej sprawy i z powodu deszczu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 10, 'Wtedy Ezdrasz powstał i powiedział do nich: Wy zgrzeszyliście, bo pojęliście obce żony, a przez to pomnożyliście grzech Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 11, 'Teraz więc wyznajcie grzech Panu, Bogu waszych ojców, i spełnijcie jego wolę. Odłączcie się od ludu tej ziemi i od obcych żon.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 12, 'A całe zgromadzenie odpowiedziało donośnym głosem: Jak nam powiedziałeś, tak uczynimy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 13, 'Ale lud jest liczny i pora deszczowa i nie możemy stać na dworze. Ponadto ta sprawa nie jest na jeden dzień ani dwa, gdyż jest nas wielu, którzy dopuściliśmy się tego przestępstwa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 14, 'Prosimy więc, niech nasi przywódcy będą postawieni przed całym zgromadzeniem i wszyscy, którzy w naszych miastach pojęli obce żony, niech przyjdą o wyznaczonej porze – z nimi starsi z każdego miasta oraz ich sędziowie, abyśmy w ten sposób odwrócili od nas zapalczywość gniewu naszego Boga z powodu tej sprawy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 15, 'Tylko Jonatan, syn Asahela, i Jachzejasz, syn Tikwy, zajmowali się tym. I Meszullam i Szabbetaj, Lewici, pomagali im.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 16, 'Tak więc postąpili ci, którzy powrócili z niewoli. I kapłan Ezdrasz wraz z naczelnikami poszczególnych rodów, wszyscy zostali odłączeni imiennie. I zasiedli w pierwszym dniu dziesiątego miesiąca, aby zbadać tę sprawę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 17, 'I do pierwszego dnia pierwszego miesiąca zakończyli sprawę ze wszystkimi mężczyznami, którzy pojęli obce żony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 18, 'Wśród synów kapłanów znaleźli się tacy, którzy pojęli obce żony: spośród synów Jeszuy, syna Jocadaka i jego braci: Maasejasz, Eliezer, Jarib i Gedaliasz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 19, 'Ci zaręczyli, że odprawią swoje żony, a jako że byli winni – każdy złoży barana ze stada za swój występek.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 20, 'A z synów Immera: Chanani i Zebadiasz;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 21, 'A z synów Charima: Maasejasz, Eliasz, Szemajasz, Jechiel i Uzjasz;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 22, 'A z synów Paszchura: Elioenaj, Maasejasz, Izmael, Netaneel, Jozabad i Elasa;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 23, 'A z Lewitów: Jozabad, Szimei, Kelajasz, to jest Kelita, Petachiasz, Juda i Eliezer;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 24, 'A ze śpiewaków: Eliaszib; a z odźwiernych: Szallum, Telem i Uri;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 25, 'A z Izraela, z synów Parosza: Ramiasz, Jezjasz, Malkiasz, Miamin, Eelazar, Malkijasz i Benajasz;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 26, 'A z synów Elama: Mattaniasz, Zachariasz, Jechiel, Abdi, Jeremot i Eliasz;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 27, 'A z synów Zattua: Elioenaj, Eliaszib, Mattaniasz, Jeremot, Zabad i Aziza;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 28, 'A z synów Bebaja: Jehochanan, Chananiasz, Zabbaj i Atlaj;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 29, 'A z synów Baniego: Meszullam, Malluk, Adajasz, Jaszub, Szeal i Jeremot;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 30, 'A z synów Pachat-Moaba: Adna, Kelal, Benajasz, Maasejasz, Mattaniasz, Besaleel, Binnuj i Manasses;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 31, 'A z synów Charima: Eliezer, Jeszsziasz, Malkiasz, Szemajasz, Szymon;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 32, 'Beniamin, Maluk i Szemariasz;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 33, 'Z synów Chaszuma: Mattenaj, Mattatta, Zabad, Elifelet, Jeremaj, Manasses i Szimei;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 34, 'Z synów Baniego: Maadaj, Amram, Uel;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 35, 'Benajasz, Bedejasz, Cheluhu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 36, 'Waniasz, Meremot, Eliaszib;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 37, 'Mattaniasz, Mattenaj, Jaasaj;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 38, 'I Bani, Binnuj, Szimei;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 39, 'I Szelemiasz, Natan, Adajasz;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 40, 'Machnadbaj, Szaszaj, Szaraj;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 41, 'Asarel, Szelemiasz, Szemariasz;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 42, 'Szallum, Amariasz i Józef;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 43, 'Z synów Nebo: Jejel, Mattitiasz, Zabad, Zebina, Jaddaj, Joel i Benajasz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 44, 'Ci wszyscy pojęli obce żony. A były wśród nich żony, które urodziły im dzieci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 1, 'Słowa Nehemiasza, syna Chakaliasza. Oto w miesiącu Kislew, dwudziestego roku, gdy przebywałem w pałacu Suza;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 2, 'Przyszedł Chanani, jeden z moich braci, a wraz z nim niektórzy mężczyźni z Judy. Zapytałem ich o ocalałych Żydów, którzy przeżyli niewolę, i o Jerozolimę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 3, 'I odpowiedzieli mi: Ostatki spośród tych, którzy w tamtej prowincji przeżyli niewolę, są w wielkim utrapieniu i pohańbieniu; ponadto mur Jerozolimy jest zburzony i jej bramy zostały spalone ogniem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 4, 'A gdy usłyszałem te słowa, usiadłem, płakałem i smuciłem się przez kilka dni, pościłem i modliłem się przed Bogiem niebios.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 5, 'I powiedziałem: Ach Panie, Boże niebios, Boże wielki i straszny, który zachowujesz przymierze i okazujesz miłosierdzie tym, którzy cię miłują i przestrzegają twoich przykazań.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 6, 'Niech twoje ucho będzie uważne, a twoje oczy będą otwarte, aby wysłuchać modlitwy twego sługi, którą teraz zanoszę do ciebie dniem i nocą za synów Izraela, twoje sługi, i w której wyznaję grzechy synów Izraela, które popełniliśmy przeciwko tobie. Również ja i dom mego ojca zgrzeszyliśmy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 7, 'Postąpiliśmy bardzo niegodziwie wobec ciebie i nie przestrzegaliśmy przykazań, ustaw ani praw, które nakazałeś Mojżeszowi, swemu słudze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 8, 'Wspomnij, proszę, na słowo, które przekazałeś Mojżeszowi, swemu słudze, gdy powiedziałeś: Jeśli przekroczycie moje przykazania, to rozproszę was między narodami;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 9, 'Lecz jeśli nawrócicie się do mnie i będziecie przestrzegać moich przykazań i wypełniać je, to choćby wasi wygnańcy byli na krańcu nieba, zgromadzę ich stamtąd i przyprowadzę na miejsce, które wybrałem, aby tam przebywało moje imię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 10, 'Oni bowiem są twoimi sługami i twoim ludem, który odkupiłeś swoją wielką mocą i silną ręką.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 11, 'Proszę, Panie, niech twoje ucho będzie uważne na modlitwę twego sługi i na modlitwę twoich sług, którzy pragną bać się twego imienia. Spraw dziś, proszę, aby poszczęściło się twemu słudze, i okaż mu łaskę na oczach tego człowieka. Byłem bowiem podczaszym króla.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 1, 'I oto zdarzyło się w miesiącu Nisan, w dwudziestym roku króla Artakserksesa, gdy stało przed nim wino, że wziąłem je i podałem królowi, a nigdy przedtem nie byłem taki smutny w jego obecności.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 2, 'Król więc zapytał mnie: Czemu tak smutno wyglądasz, skoro nie jesteś chory? Nic innego to jak smutek serca. I bardzo się przeraziłem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 3, 'I powiedziałem do króla: Niech król żyje na wieki. Jakże nie mam wyglądać smutno, gdy miasto, dom grobów moich ojców, jest zburzone, a jego bramy pochłonął ogień?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 4, 'Król ponownie zapytał mnie: O co chciałbyś prosić? Modliłem się więc do Boga niebios.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 5, 'Potem powiedziałem do króla: Jeśli król uważa to za dobre i jeśli twój sługa znalazł łaskę w twoich oczach, proszę, abyś mnie posłał do Judy, do miasta grobów moich ojców, abym je odbudował.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 6, 'Król – obok którego siedziała królowa – zapytał mnie: Jak długo potrwa twoja podróż i kiedy powrócisz? Gdy podałem mu termin, spodobało się to królowi i posłał mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 7, 'Potem powiedziałem królowi: Jeśli król uważa to za dobre, niech mi dadzą listy do namiestników zarzecza, aby mnie przeprowadzili, aż przyjdę do Judy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 8, 'Także list do Asafa, dozorcy lasu królewskiego, aby mi dał drewno na belki do bram pałacu przy domu, na mur miejski i na dom, do którego się wprowadzę. Król więc dał mi listy, gdyż była nade mną łaskawa ręka mego Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 9, 'A gdy przyszedłem do namiestników zarzecza, oddałem im listy króla. A król wyprawił ze mną dowódców wojskowych i jeźdźców.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 10, 'Kiedy Sanballat Choronita i Tobiasz, sługa ammonicki, usłyszeli o tym, bardzo im się nie spodobało to, że przyszedł człowiek, który będzie zabiegał o dobro synów Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 11, 'Gdy więc przyszedłem do Jerozolimy, spędziłem tam trzy dni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 12, 'Potem wstałem w nocy, ja i kilku mężczyzn ze mną – a nikomu nie wyjawiłem, co mój Bóg położył mi na sercu, abym uczynił w Jerozolimie, nie miałem też ze sobą żadnego zwierzęcia oprócz tego, na którym jechałem;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 13, 'I wyjechałem nocą przez Bramę nad Doliną w kierunku Źródła Smoczego do Bramy Gnojnej, i oglądałem mury jerozolimskie, które były zburzone, a których bramy były strawione ogniem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 14, 'Potem dotarłem do Bramy Źródlanej i do Stawu Królewskiego, gdzie dla zwierzęcia, na którym jechałem, nie było już przejścia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 15, 'Jechałem więc nocą przez potok i oglądałem mur, po czym zawróciłem i przejechałem przez Bramę nad Doliną, i tak powróciłem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 16, 'Ale przełożeni nie wiedzieli, dokąd się udałem ani co uczyniłem. Dotychczas bowiem nie oznajmiłem tego ani Żydom, ani kapłanom, ani dostojnikom, ani przełożonym, ani żadnemu z budowniczych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 17, 'Wtedy powiedziałem do nich: Widzicie, w jakiej niedoli się znajdujemy, Jerozolima jest spustoszona i jej bramy spalone są ogniem. Chodźcie i odbudujmy mur Jerozolimy, abyśmy już nie byli zhańbieni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 18, 'A gdy opowiedziałem im o tym, jak łaskawa ręka mego Boga była nade mną, także o słowach, które wypowiedział do mnie król, powiedzieli: Wstańmy i budujmy. I zachęcali się do tego dobrego dzieła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 19, 'Kiedy usłyszeli o tym Sanballat Choronita i Tobiasz, sługa ammonicki, oraz Geszem Arab, szydzili z nas i wzgardzili nami, mówiąc: Co to za rzecz, którą robicie? Czy buntujecie się przeciw królowi?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 20, 'Odpowiedziałem im: Bóg niebios poszczęści nam; my więc, jego słudzy, powstaniemy i odbudujemy. Wy zaś nie macie ani działu, ani prawa, ani pamiątki w Jerozolimie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 1, 'Potem powstał najwyższy kapłan Eliaszib wraz ze swoimi braćmi kapłanami i odbudowali Bramę Owczą. Poświęcili ją i wstawili jej wrota. Poświęcili ją aż do wieży Mea i aż do wieży Chananeela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 2, 'Obok niego budowali mężczyźni z Jerycha, a obok nich budował Zakkur, syn Imriego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 3, 'A Bramę Rybną budowali synowie Senaa, którzy założyli też jej belki, wstawili jej wrota, zamki i rygle.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 4, 'Obok nich naprawiał Meremot, syn Uriasza, syna Kosa, a obok nich naprawiał Meszullam, syn Berechiasza, syna Meszezabeela. Obok nich naprawiał Sadok, syn Baany.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 5, 'Obok nich naprawiali Tekoici, lecz ich dostojnicy nie ugięli swego karku do pracy dla swego Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 6, 'A Bramę Starą naprawiali Jojada, syn Paseacha, i Meszullam, syn Besodiasza. Założyli jej belki i wstawili jej wrota, zamki i rygle.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 7, 'Obok nich naprawiali Melatiasz Gibeonita, Jadon Meronotyta oraz mężczyźni z Gibeonu i Mispy aż do tronu namiestnika z tej strony rzeki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 8, 'Obok nich naprawiał Uzziel, syn Charchajasza, jeden ze złotników, a obok niego naprawiał Chananiasz, syn aptekarza. Obwarowali Jerozolimę aż do Muru Szerokiego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 9, 'Obok nich naprawiał Refajasz, syn Chura, przełożony połowy okręgu Jerozolimy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 10, 'Obok nich naprawiał Jedajasz, syn Charumafa, naprzeciw swego domu. A obok niego naprawiał Chattusz, syn Chaszabnejasza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 11, 'Drugi odcinek i Wieżę Pieców zaś naprawiał Malkiasz, syn Charima, i Chaszub, syn Pachat-Moaba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 12, 'Obok niego naprawiał Szallum, syn Hallochesza, przełożony połowy okręgu Jerozolimy, on i jego córki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 13, 'Bramę nad Doliną naprawiali Chanun i mieszkańcy Zanoach. Odbudowali ją, wstawili jej wrota, zamki i rygle i naprawili tysiąc łokci muru aż do Bramy Gnojnej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 14, 'Lecz Bramę Gnojną naprawiał Malkiasz, syn Rekaba, przełożony okręgu Bet-Hakkerem. On ją odbudował i wstawił jej wrota, zamki i rygle;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 15, 'Bramę Źródlaną naprawiał Szallun, syn Kol-Chozego, przełożony okręgu Mispa. On ją zbudował, pokrył dachem i wstawił jej wrota, zamki i rygle oraz wzniósł mur nad stawem Sziloach przy ogrodzie królewskim aż do schodów prowadzących do miasta Dawida.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 16, 'Za nim naprawiał Nehemiasz, syn Azbuka, przełożony połowy okręgu Bet-Sur, aż do miejsca naprzeciw grobów Dawida i aż do stawu sztucznego, i aż do domu mocarzy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 17, 'Za nim naprawiali Lewici: Rechum, syn Baniego, obok niego naprawiał Chaszabiasz, przełożony połowy okręgu Keila, za swój okręg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 18, 'Za nim naprawiali ich bracia: Bawaj, syn Chenadada, przełożony połowy okręgu Keila.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 19, 'Obok niego naprawiał Ezer, syn Jeszuy, przełożony Mispy, następny odcinek naprzeciw wejścia do zbrojowni przy rogu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 20, 'Za nim naprawiał gorliwie Baruch, syn Zabbaja, dalszy odcinek od rogu aż do drzwi domu arcykapłana Eliasziba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 21, 'Za nim naprawiał Meremot, syn Uriasza, syn Kosa, następny odcinek od drzwi domu Eliasziba aż do końca jego domu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 22, 'Za nim naprawiali kapłani, którzy mieszkali na równinie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 23, 'Za nimi naprawiali Beniamin i Chaszub, naprzeciw swoich domów. Za nimi naprawiał Azariasz, syn Maasejasza, syna Ananiasza, obok swego domu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 24, 'Za nim naprawiał Binnuj, syn Chenadada, następny odcinek od domu Azariasza aż do zakrętu i do narożnika.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 25, 'Palal, syn Uzaja, naprawiał naprzeciw rogu i wieży wystającej z domu królewskiego, która była przy więzieniu. Za nim naprawiał Pedajasz, syn Parosza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 26, 'A Netinici, mieszkający na Ofelu, naprawiali aż naprzeciw Bramy Wodnej na wschodzie i do wieży wystającej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 27, 'Za nimi naprawiali Tekoici dalszy odcinek, naprzeciw wielkiej wieży wystającej aż do muru Ofel.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 28, 'Znad Bramy Końskiej naprawiali kapłani, każdy naprzeciw swego domu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 29, 'Za nimi naprawiał Sadok, syn Immera, naprzeciw swego domu, a za nim naprawiał Szemajasz, syn Szekaniasza, stróż Bramy Wschodniej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 30, 'Za nim naprawiał Chananiasz, syn Szelemiasza, i Chanun, szósty syn Salafa, następny odcinek. Za nim naprawiał Meszullam, syn Berechiasza, naprzeciw swojej komnaty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 31, 'Za nim naprawiał Malkiasz, syn złotnika, aż do domu Netinitów i handlarzy, naprzeciw Bramy Sądowej i aż do Sali Narożnej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 32, 'A pomiędzy Salą Narożną a Bramą Owczą naprawiali złotnicy i handlarze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 1, 'A gdy Sanballat usłyszał, że odbudowujemy mur, rozgniewał się i bardzo się oburzył, i zaczął szydzić z Żydów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 2, 'I powiedział wobec swoich braci i wojska Samarii: Co ci niedołężni Żydzi wyprawiają? Czy im na to pozwolimy? Czy będą składać ofiary? Czy zdołają to skończyć w jeden dzień? Czy wskrzeszą kamienie z kupy gruzu, które spalono?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 3, 'Ale Tobiasz Ammonita, który stał obok niego, powiedział: Nawet jeśli zbudują, przyjdzie lis i przewróci ich kamienny mur.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 4, 'Wysłuchaj, nasz Boże, bo jesteśmy wzgardzeni, i odwróć ich zhańbienie na ich głowę, i wydaj ich na łup w ziemi niewoli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 5, 'Nie zakrywaj ich nieprawości, a niech ich grzech nie będzie wymazany przed tobą. Ciebie bowiem pobudzili do gniewu na oczach budujących.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 6, 'Lecz my nadal odbudowywaliśmy ten mur i mur został spojony aż do połowy, bo lud miał serce do pracy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 7, 'Gdy Sanballat i Tobiasz, Arabowie, Ammonici i Aszdodyci usłyszeli, że mury Jerozolimy są odbudowywane, że wyłomy zaczęły się wypełniać, bardzo się rozgniewali.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 8, 'I wszyscy sprzysięgli się razem, aby przyjść i walczyć przeciw Jerozolimie, i przeszkadzać w robocie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 9, 'My jednak modliliśmy się do naszego Boga i postawiliśmy przeciwko nim straż we dnie i w nocy, bojąc się ich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 10, 'I Judejczycy powiedzieli: Osłabła siła dźwigających, a gruzu jeszcze wiele. Nie będziemy mogli odbudować muru.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 11, 'Ponadto nasi wrogowie powiedzieli: Zanim się dowiedzą i spostrzegą, przyjdziemy między nich i wymordujemy, i wstrzymamy tę pracę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 12, 'A gdy Żydzi mieszkający obok nich przyszli, powiedzieli nam dziesięć razy: Ze wszystkich miejsc, z których przyjdziecie do nas, oni przyjdą na was.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 13, 'Ustawiłem więc lud w niższych miejscach za murem i na wysokich miejscach; ustawiłem ich według rodzin z ich mieczami, włóczniami i łukami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 14, 'A gdy popatrzyłem, wstałem i powiedziałem do dostojników, przełożonych i pozostałych z ludu: Nie bójcie się ich. Wspomnijcie na Pana, wielkiego i budzącego grozę, i walczcie za swoich braci, za swoich synów i swoje córki, za swoje żony i domy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 15, 'I kiedy nasi wrogowie usłyszeli, że nam to oznajmiono, Bóg zniweczył ich radę, a my wszyscy wróciliśmy do muru, każdy do swojej pracy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 16, 'Jednak od tego czasu połowa moich sług pracowała, a druga połowa trzymała włócznie, tarcze, łuki i pancerze. Naczelnicy zaś stali za całym domem Judy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 17, 'Ci, którzy odbudowywali mur, i ci, którzy dźwigali ciężar, i ci, którzy go nakładali, każdy z nich jedną ręką pracował, a w drugiej trzymał broń.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 18, 'A z tych, którzy budowali, każdy miał swój miecz przypasany do boku i tak budowali. A trębacz stał obok mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 19, 'Powiedziałem bowiem do dostojników, przełożonych i pozostałych z ludu: Praca jest wielka i rozległa, a my jesteśmy rozdzieleni na murze, jeden z dala od drugiego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 20, 'W jakimkolwiek miejscu usłyszycie dźwięk trąby, tam ruszajcie do nas. Nasz Bóg będzie walczył za nas.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 21, 'Pracowaliśmy więc przy tym dziele, a druga połowa trzymała włócznie, od pojawienia się zorzy aż do wzejścia gwiazd.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 22, 'W tym czasie powiedziałem też do ludu: Niech każdy nocuje ze swoim sługą w Jerozolimie, aby w nocy słudzy trzymali straż, a w dzień pracowali.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 23, 'Tak więc ani ja, ani moi bracia, ani moi słudzy, ani straż, która była przy mnie, nie zdejmowaliśmy swoich szat, zrobiliśmy to wyłącznie przy obmywaniu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 1, 'I podniósł się wielki krzyk ludu i ich żon przeciwko swym braciom Żydom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 2, 'Niektórzy bowiem mówili: Jest nas wielu wraz z synami i córkami i musimy nabyć zboża, abyśmy mogli jeść i żyć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 3, 'Inni zaś mówili: Nasze pola, winnice i domy musimy dać pod zastaw, aby nabyć zboża na czas głodu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 4, 'Jeszcze inni mówili: Pożyczyliśmy pieniądze, aby dać podatek królowi, zastawiając nasze pola i nasze winnice.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 5, 'A przecież nasze ciało jest jak ciało naszych braci, a nasi synowie są jak ich synowie. A jednak to my musimy oddać naszych synów i nasze córki w niewolę i niektóre z naszych córek są już zaprzedane w niewolę, a my nie mamy siły w naszych rękach, aby je odkupić, gdyż nasze pola i winnice należą do innych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 6, 'I rozgniewałem się bardzo, gdy usłyszałem ich wołanie i te słowa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 7, 'Rozważyłem to w swoim sercu, po czym skarciłem dostojników i przełożonych, mówiąc do nich: Każdy z was uprawia lichwę wobec swoich braci. Zebrałem więc wielkie zgromadzenie przeciwko nim;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 8, 'I powiedziałem do nich: My według naszych możliwości odkupiliśmy swoich braci Żydów, którzy zostali zaprzedani poganom, a wy chcecie sprzedać swoich braci? Chcielibyście ich nam sprzedać? Oni zamilkli, nie znajdując odpowiedzi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 9, 'Ponadto powiedziałem: Nie jest dobre to, co czynicie. Czy nie powinniście kroczyć w bojaźni naszego Boga, by uniknąć zhańbienia od pogan, naszych wrogów?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 10, 'Także ja i moi bracia oraz moi słudzy pożyczyliśmy im pieniądze i zboże. Porzućmy, proszę, tę lichwę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 11, 'Zwróćcie im, proszę, ich pole, winnice, oliwniki i domy oraz setną część pieniędzy, zboża, wina i oliwy, którą od nich pobieracie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 12, 'Wtedy odpowiedzieli: Zwrócimy i nie będziemy domagać się niczego od nich. Uczynimy tak, jak ty powiedziałeś. Wezwałem więc kapłanów i kazałem przysiąc wierzycielom, że postąpią według tej obietnicy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 13, 'Potem wytrząsnąłem swoje zanadrze i powiedziałem: Tak niech Bóg wytrząśnie każdego z jego domu i z owocu jego pracy, kto nie dotrzyma tej obietnicy. Niech tak będzie wytrząśnięty i ogołocony. I całe zgromadzenie powiedziało: Amen. I chwalili Pana. I lud postąpił według tej obietnicy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 14, 'Również od dnia, w którym ustanowiono mnie ich namiestnikiem w ziemi Judy, od dwudziestego aż do trzydziestego drugiego roku króla Artakserksesa, przez dwanaście lat, ja i moi bracia nie jedliśmy chleba przysługującego namiestnikowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 15, 'Dawni namiestnicy, którzy byli przede mną, obciążali lud, pobierając od niego chleb i wino, a ponadto czterdzieści syklów srebra. Ich słudzy również wykorzystywali lud. Lecz ja tak nie postępowałem z bojaźni Bożej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 16, 'Także pracowałem przy naprawie tego muru, a pola nie kupiłem. Wszyscy też moi słudzy zgromadzili się tam do pracy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 17, 'Ponadto przy moim stole byli Żydzi i przełożeni w liczbie stu pięćdziesięciu oraz ci, którzy przychodzili do nas spośród okolicznych pogan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 18, 'Przygotowywano więc dla mnie każdego dnia jednego wołu, sześć wybornych owiec oraz drób, a co dziesięć dni rozmaite wino. Mimo to nie domagałem się chleba przysługującego namiestnikowi, gdyż niewola ciążyła nad tym ludem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 19, 'Wspomnij na mnie, mój Boże, ku memu dobru, ze względu na wszystko, co czyniłem dla tego ludu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 1, 'A gdy Sanballat, Tobiasz, Geszem Arab i pozostali nasi wrogowie usłyszeli, że zbudowałem mur i że nie pozostał w nim żaden wyłom, chociaż jeszcze w tym czasie nie wstawiłem wrót do bram;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 2, 'Wtedy Sanballat i Geszem wysłali do mnie poselstwo ze słowami: Przyjdź, spotkajmy się razem w jednej ze wsi, na równinie Ono. Lecz oni mieli zamiar uczynić mi coś złego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 3, 'Wysłałem więc do nich posłańców z taką odpowiedzią: Wykonuję wielką pracę i nie mogę zejść. Czemu miałaby stanąć ta praca, gdybym jej zaniechał, by zejść do was?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 4, 'Cztery razy przysłali do mnie poselstwo w tej sprawie, a ja odpowiedziałem im tak samo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 5, 'Potem Sanballat po raz piąty przysłał do mnie w ten sam sposób swego sługę z otwartym listem w ręku;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 6, 'A było w nim napisane: Wśród pogan krąży pogłoska – jak powiada Gaszmu – że ty i Żydzi zamierzacie się zbuntować. Dlatego budujesz mur, abyś był ich królem, według tych słów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 7, 'Krąży też pogłoska, że ustanowiłeś proroków, aby opowiadali o tobie w Jerozolimie, mówiąc: Jest król w Judzie. Teraz te słowa dotrą do króla. Przyjdź więc i naradzimy się wspólnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 8, 'Lecz ja wysłałem do niego taką odpowiedź: Nie jest tak, jak powiadasz, ale sam sobie to wymyślasz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 9, 'Oni wszyscy bowiem straszyli nas, mówiąc: Ich ręce osłabną od tej pracy i nie zostanie dokonana. Teraz więc, Boże, wzmocnij moje ręce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 10, 'A gdy wszedłem do domu Szemajasza, syna Delajasza, syna Mehetabeela, gdzie był zamknięty, powiedział mi: Zejdźmy się w domu Bożym, w świątyni, i zamknijmy drzwi. Przyjdą bowiem, aby cię zabić. Tej nocy przyjdą, aby cię zabić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 11, 'A ja odpowiedziałem: Czy człowiek taki jak ja miałby uciekać? Czy ktoś taki jak ja wszedłby do świątyni, aby się ratować? Nie wejdę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 12, 'I poznałem, że to nie Bóg go posłał, ale wypowiedział to proroctwo przeciwko mnie, bo Tobiasz i Sanballat przekupili go.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 13, 'Został przekupiony, abym się uląkł i tak uczynił, i zgrzeszył, aby posłużyło to do zniesławienia mnie, by mnie zhańbić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 14, 'Mój Boże, pamiętaj o Tobiaszu i Sanballacie, według ich uczynków, także o prorokini Noadzie oraz pozostałych prorokach, którzy chcieli mnie straszyć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 15, 'A mur został ukończony dwudziestego piątego dnia miesiąca Elul, w ciągu pięćdziesięciu dwóch dni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 16, 'A gdy usłyszeli o tym wszyscy nasi wrogowie i gdy widzieli to wszyscy poganie, którzy byli wokół nas, bardzo się zniechęcili. Poznali bowiem, że to dzieło zostało wykonane przez naszego Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 17, 'W te dni dostojnicy z Judy wysyłali wiele listów do Tobiasza, a także listy od Tobiasza przychodziły do nich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 18, 'Wielu bowiem w Judzie było z nim związanych przysięgą, gdyż był on zięciem Szekaniasza, syna Aracha; a jego syn Jochanan pojął za żonę córkę Meszullama, syna Berechiasza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 19, 'Opowiadali także przede mną jego dobre czyny i moje słowa donosili jemu. Tobiasz zaś wysyłał listy, aby mnie zastraszyć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 1, 'A gdy mur został odbudowany i wstawiłem wrota, gdy ustanowiono odźwiernych, śpiewaków i Lewitów;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 2, 'Nad Jerozolimą postawiłem Chananiego, swojego brata, a Chananiasza ustanowiłem dowódcą pałacu. On bowiem był wiernym człowiekiem i bał się Boga bardziej niż wielu innych;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 3, 'I powiedziałem do nich: Niech nie otwierają bram Jerozolimy, aż słońce będzie dopiekać; a póki tam stoją, niech zamkną bramy i zaryglują je. Należy ustanowić straż spośród mieszkańców Jerozolimy, każdego na jego posterunku i każdego naprzeciwko własnego domu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 4, 'A miasto było przestronne i wielkie, ale ludu w jego murach było niewiele, a domy jeszcze nie zostały odbudowane.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 5, 'I mój Bóg położył mi na sercu, abym zebrał dostojników, przełożonych i lud, aby zostali spisani według rodowodów. Wtedy znalazłem księgę rodowodów tych, którzy pierwsi powrócili, a znalazłem w niej taki zapis.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 6, 'Oto ludzie tej prowincji, którzy przybyli z niewoli, dokąd zostali uprowadzeni, których uprowadził Nabuchodonozor, król Babilonu, a powrócili do Jerozolimy i do Judy, każdy do swego miasta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 7, 'Przyszli z Zorobabelem, z Jeszuą, Nehemiaszem, Azariaszem, Raamiaszem, Nachamanim, Mardocheuszem, Bilszanem, Misperetem, Bigwajem, Nechumem i Baaną. Oto liczba mężczyzn ludu Izraela:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 8, 'Synów Parosza – dwa tysiące stu siedemdziesięciu dwóch;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 9, 'Synów Szefatiasza – trzystu siedemdziesięciu dwóch;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 10, 'Synów Aracha – sześciuset pięćdziesięciu dwóch;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 11, 'Synów Pachat-Moaba, synów Jeszuy i Joaba – dwa tysiące ośmiuset osiemnastu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 12, 'Synów Elama – tysiąc dwustu pięćdziesięciu czterech;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 13, 'Synów Zattua – ośmiuset czterdziestu pięciu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 14, 'Synów Zakkaja – siedmiuset sześćdziesięciu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 15, 'Synów Binnuja – sześciuset czterdziestu ośmiu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 16, 'Synów Bebaja – sześciuset dwudziestu ośmiu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 17, 'Synów Azgada – dwa tysiące trzystu dwudziestu dwóch;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 18, 'Synów Adonikama – sześciuset sześćdziesięciu siedmiu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 19, 'Synów Bigwaja – dwa tysiące sześćdziesięciu siedmiu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 20, 'Synów Adina – sześciuset pięćdziesięciu pięciu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 21, 'Synów Atera, z linii Ezechiasza – dziewięćdziesięciu ośmiu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 22, 'Synów Chaszuma – trzystu dwudziestu ośmiu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 23, 'Synów Besaja – trzystu dwudziestu czterech;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 24, 'Synów Charifa – stu dwunastu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 25, 'Synów z Gibeonu – dziewięćdziesięciu pięciu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 26, 'Mężczyźni z Betlejem i Netofy – stu osiemdziesięciu ośmiu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 27, 'Mężczyźni z Anatot – stu dwudziestu ośmiu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 28, 'Mężczyźni z Bet-Azmawet – czterdziestu dwóch;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 29, 'Mężczyźni z Kiriat-Jearim, Kefiry i Beerot – siedmiuset czterdziestu trzech;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 30, 'Mężczyźni z Rama i Geba – sześciuset dwudziestu jeden;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 31, 'Mężczyźni z Mikmas – stu dwudziestu dwóch;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 32, 'Mężczyźni z Betel i Aj – stu dwudziestu i trzech;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 33, 'Mężczyźni z drugiego Nebo – pięćdziesięciu dwóch;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 34, 'Synów drugiego Elama – tysiąc dwustu pięćdziesięciu czterech;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 35, 'Synów Charima – trzystu dwudziestu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 36, 'Synów Jerycha – trzystu czterdziestu pięciu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 37, 'Synów z Lod, Chadida i Ono – siedmiuset dwudziestu jeden;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 38, 'Synów Senai – trzy tysiące dziewięciuset trzydziestu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 39, 'Kapłani: synów Jedajasza, z domu Jeszuy – dziewięciuset siedemdziesięciu trzech;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 40, 'Synów Immera – tysiąc pięćdziesięciu dwóch;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 41, 'Synów Paszchura – tysiąc dwustu czterdziestu siedmiu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 42, 'Synów Charima – tysiąc siedemnastu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 43, 'Lewici: synów Jeszuy, Kadmiela, z synów Hodwy – siedemdziesięciu czterech.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 44, 'Śpiewacy: synów Asafa – stu czterdziestu ośmiu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 45, 'Odźwiernych: synów Szalluma, synów Atera, synów Talmona, synów Akkuba, synów Chatity, synów Szobaja – stu trzydziestu ośmiu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 46, 'Netinici: synowie Sichy, synowie Chaszufy, synowie Tabbaota;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 47, 'Synowie Kerosa, synowie Sii, synowie Padona;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 48, 'Synowie Lebana, synowie Chagaby, synowie Szalmaja;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 49, 'Synowie Chanana, synowie Giddela, synowie Gachara;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 50, 'Synowie Reajasza, synowie Resina, synowie Nekody;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 51, 'Synowie Gazzama, synowie Uzzy, synowie Paseacha;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 52, 'Synowie Besaja, synowie Meunitów, synowie Nefisytów;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 53, 'Synowie Bakbuka, synowie Chakufy, synowie Charchura;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 54, 'Synowie Baslita, synowie Mechidy, synowie Charszy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 55, 'Synowie Barkosa, synowie Sisery, synowie Tamacha;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 56, 'Synowie Nesjacha, synowie Chatify;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 57, 'Synowie sług Salomona: synowie Sotaja, synowie Sofereta, synowie Peridy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 58, 'Synowie Jaali, synowie Darkona, synowie Giddela;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 59, 'Synowie Szefatiasza, synowie Chattila, synowie Pocheret-Hassebaima, synowie Amona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 60, 'Wszystkich Netinitów i synów sług Salomona – trzystu dziewięćdziesięciu dwóch.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 61, 'A oto ci, którzy przybyli z Tel-Melach, Tel-Charsza, Kerub, Addan i Immer, ale nie mogli wykazać domu swoich ojców i swego potomstwa – tego, czy pochodzą z Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 62, 'Synów Delajasza, synów Tobiasza, synów Nekody – sześciuset czterdziestu dwóch.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 63, 'A z kapłanów: synowie Chobajasza, synowie Kosa, synowie Barzillaja, który pojął za żonę jedną z córek Barzillaja Gileadczyka i przybrał ich imię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 64, 'Ci szukali swego spisu według rodowodu, ale nie znaleźli, toteż zostali wykluczeni z kapłaństwa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 65, 'Tirszata zakazał im spożywać z pokarmów najświętszych, dopóki nie pojawi się kapłan z Urim i Tummim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 66, 'Całe to zgromadzenie liczyło czterdzieści dwa tysiące trzysta sześćdziesiąt osób;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 67, 'Nie licząc ich sług i służących, których było siedem tysięcy trzysta trzydzieścioro siedmioro. A wśród nich było dwieście czterdzieścioro pięcioro śpiewaków i śpiewaczek.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 68, 'Ich koni – siedemset trzydzieści sześć. Ich mułów – dwieście czterdzieści pięć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 69, 'Wielbłądów – czterysta trzydzieści pięć. Osłów – sześć tysięcy siedemset dwadzieścia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 70, 'A niektórzy z naczelników rodów dali na prace. Tirszata dał do skarbca tysiąc drachm złota, pięćdziesiąt czasz i pięćset trzydzieści szat kapłańskich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 71, 'Niektórzy też z przedniejszych rodów dali do skarbca na pracę dwadzieścia tysięcy drachm złota i dwa tysiące dwieście min srebra.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 72, 'A to, co dała reszta ludu, wynosiło dwadzieścia tysięcy drachm złota, dwa tysiące min srebra i sześćdziesiąt siedem szat kapłańskich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 73, 'Tak więc kapłani, Lewici, odźwierni, śpiewacy, część ludu, Netinici i cały Izrael osiedlili się w swoich miastach. A gdy nastał siódmy miesiąc, synowie Izraela mieszkali w swoich miastach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 1, 'Wówczas zebrał się cały lud jak jeden mąż na placu, który był przed Bramą Wodną, i powiedział do Ezdrasza, uczonego w Piśmie, aby przyniósł księgę Prawa Mojżesza, które Pan nadał Izraelowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 2, 'Wtedy Ezdrasz, kapłan, przyniósł Prawo przed zgromadzenie mężczyzn i kobiet oraz wszystkich, którzy mogli słuchać i rozumieć, a działo się to pierwszego dnia siódmego miesiąca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 3, 'I czytał je przed tym placem, który znajdował się przed Bramą Wodną, od rana aż do południa, przed mężczyznami i kobietami oraz tymi, którzy mogli zrozumieć; a uszy całego ludu były skupione na księdze Prawa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 4, 'Ezdrasz, uczony w Piśmie, stanął na drewnianym podwyższeniu, które przygotowano na ten cel, a obok niego, po prawej stronie, stali: Mattitiasz, Szema, Ananiasz, Uriasz, Chilkiasz i Maasejasz, a po lewej stronie: Pedajasz, Miszael, Malkiasz, Chaszum, Chaszbadana, Zachariasz i Meszullam.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 5, 'Ezdrasz otworzył księgę na oczach całego ludu – gdyż stał wyżej niż on – a gdy ją otworzył, cały lud powstał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 6, 'I Ezdrasz błogosławił Panu, wielkiemu Bogu, a cały lud, podnosząc ręce, odpowiadał: Amen! Amen! Potem skłonili głowy i oddali pokłon Panu, padając twarzą ku ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 7, 'Także Jeszua, Bani, Szerebiasz, Jamin, Akkub, Szabbetaj, Hodiasz, Maasejasz, Kelita, Azariasz, Jozabad, Chanan, Pelajasz i Lewici nauczali lud prawa. A lud stał na swoim miejscu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 8, 'Czytali więc z księgi Prawa Bożego wyraźnie i wyjaśniali znaczenie tak, żeby zrozumiano to, co czytali.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 9, 'Potem Nehemiasz, to jest Tirszata, i Ezdrasz, kapłan i uczony w Piśmie, oraz Lewici, którzy nauczali lud, powiedzieli do całego ludu: Ten dzień jest poświęcony Panu, waszemu Bogu. Nie smućcie się ani nie płaczcie. Cały lud bowiem płakał, słuchając słowa Prawa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 10, 'I powiedział im: Idźcie, jedzcie tłuste potrawy i pijcie słodki napój, i poślijcie porcje tym, którzy sobie nic nie przygotowali. Dzień ten jest bowiem święty dla naszego Pana. Dlatego nie smućcie się, gdyż radość Pana jest waszą siłą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 11, 'A Lewici uspokajali cały lud, mówiąc: Uciszcie się, bo ten dzień jest święty. Nie smućcie się.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 12, 'Rozszedł się więc cały lud, aby jeść i pić, aby rozsyłać porcje i radować się bardzo, gdyż zrozumiał słowa, które mu ogłoszono.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 13, 'Następnego dnia naczelnicy rodów całego ludu, kapłani i Lewici zebrali się wokół Ezdrasza, uczonego w Piśmie, aby zrozumieć słowa Prawa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 14, 'I znaleźli przepis w Prawie, które Pan nadał przez Mojżesza, aby synowie Izraela mieszkali w szałasach podczas święta siódmego miesiąca;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 15, 'I aby ogłoszono i obwołano we wszystkich ich miastach i w Jerozolimie: Wejdźcie na górę i przynieście gałęzie oliwne, gałęzie sosnowe i gałęzie mirtowe, gałęzie palmowe i gałęzie drzew gęstych, abyście czynili szałasy, jak jest napisane.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 16, 'Lud więc wyszedł i przyniósł je, i czynił sobie szałasy, każdy na swoim dachu, na swoich dziedzińcach, na dziedzińcach domu Bożego, na placu Bramy Wodnej i na placu Bramy Efraima.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 17, 'Całe zgromadzenie, wszyscy, którzy powrócili z niewoli, uczynili szałasy i mieszkali w nich, gdyż synowie Izraela nie czynili tego od dni Jozuego, syna Nuna, aż do tego dnia. I panowała wielka radość.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 18, 'I Ezdrasz czytał z księgi Prawa Bożego każdego dnia, od pierwszego dnia aż do ostatniego. Przez siedem dni obchodzili święto, a dnia ósmego odbyło się uroczyste zgromadzenie według zwyczaju.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 1, 'A w dwudziestym czwartym dniu tego miesiąca zgromadzili się synowie Izraela i pościli odziani w wory oraz posypani prochem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 2, 'I potomstwo Izraela odłączyło się od wszystkich cudzoziemców, stanęli i wyznawali swoje grzechy i nieprawości swoich ojców.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 3, 'Stali na swoim miejscu i czytali księgę Prawa Pana, swego Boga, przez ćwierć dnia, a przez drugą ćwierć dnia wyznawali grzechy i oddawali pokłon Panu, swemu Bogu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 4, 'Potem na podwyższeniu dla Lewitów stanęli: Jeszua, Bani, Kadmiel, Szebaniasz, Bunni, Szerebiasz, Bani i Kenani i wołali donośnym głosem do Pana, swego Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 5, 'Następnie Lewici: Jeszua, Kadmiel, Bani, Chaszabnejasz, Szerebiasz, Hodiasz, Szebaniasz i Petachiasz powiedzieli: Powstańcie i błogosławcie Panu, waszemu Bogu, na wieki wieków. I niech będzie błogosławione twoje chwalebne imię, wywyższone nad wszelkie błogosławieństwo i wszelką chwałę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 6, 'Ty, ty jedynie jesteś Panem. Ty uczyniłeś niebiosa, niebiosa niebios i całe ich wojsko, ziemię i wszystko, co jest na niej, morza i wszystko, co w nich jest, ty też utrzymujesz to wszystko; a wojska niebios oddają tobie pokłon.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 7, 'Ty Panie jesteś tym Bogiem, który wybrał Abrama. Wyprowadziłeś go z Ur chaldejskiego i nadałeś mu imię Abraham.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 8, 'A uznałeś, że jego serce jest wierne przed tobą i zawarłeś z nim przymierze, że ziemię Kananejczyka, Chetyty, Amoryty, Peryzzyty, Jebusyty i Girgaszyty dasz jego potomstwu. I dotrzymałeś swojego słowa, bo jesteś sprawiedliwy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 9, 'Widziałeś utrapienie naszych ojców w Egipcie i wysłuchałeś ich wołania nad Morzem Czerwonym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 10, 'Dokonałeś znaków i cudów na faraonie, na wszystkich jego sługach i na całym ludzie jego ziemi. Wiedziałeś bowiem, że zuchwale postępowali z nimi. I w ten sposób uczyniłeś wielkim swoje imię, jak to jest dzisiaj.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 11, 'Rozdzieliłeś morze przed nimi, a oni przeszli przez środek morza po suchej ziemi; ścigających ich wrzuciłeś zaś w głębię jak kamień w wody wzburzone.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 12, 'I słupem obłoku prowadziłeś ich we dnie, a słupem ognia w nocy, aby oświetlić im drogę, którą mieli iść.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 13, 'Potem zstąpiłeś na górę Synaj i mówiłeś do nich z nieba. Dałeś im sprawiedliwe sądy, słuszne prawa, dobre ustawy i przykazania.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 14, 'Oznajmiłeś im swój święty szabat i nadałeś im przykazania, ustawy i prawa przez swego sługę Mojżesza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 15, 'Dałeś im też chleb z nieba, kiedy byli głodni, i wyprowadziłeś im wodę ze skały, kiedy byli spragnieni. Rozkazałeś im wejść do ziemi, którą przysiągłeś im dać w posiadanie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 16, 'Ale oni i nasi ojcowie zuchwale sobie postąpili i uczynili twardym swój kark, i nie słuchali twoich przykazań.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 17, 'Odmówili posłuszeństwa i nie pamiętali o twoich cudach, które dla nich czyniłeś, ale uczynili twardym swój kark i w swoim buncie ustanowili sobie wodza, aby wrócić do swojej niewoli. Lecz ty jesteś Bogiem przebaczenia – łaskawym i miłosiernym, nieskorym do gniewu i wielkiej dobroci – i nie opuściłeś ich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 18, 'Nawet gdy uczynili sobie lanego cielca i powiedzieli: To jest twój Bóg, który cię wyprowadził z ziemi Egiptu, i dopuścili się wielkich bluźnierstw;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 19, 'Ty jednak w swoim wielkim miłosierdziu nie opuściłeś ich na pustyni. Słup obłoku nie odstępował od nich we dnie, prowadząc ich na drodze, ani słup ognisty w nocy, oświetlając ich i drogę, którą mieli iść.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 20, 'Ponadto dałeś im swego dobrego ducha, aby ich pouczał; swojej manny od ich ust nie odjąłeś i dałeś im wodę, gdy byli spragnieni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 21, 'I tak przez czterdzieści lat żywiłeś ich na pustyni i niczego im nie brakowało; ich szaty nie starzały się, a ich nogi nie puchły.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 22, 'Dałeś im królestwa i narody i rozmieściłeś ich po zakątkach, tak że posiedli ziemię Sichona, ziemię króla Heszbonu, i ziemię Oga, króla Baszanu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 23, 'Ich synów rozmnożyłeś jak gwiazdy na niebie i wprowadziłeś ich do ziemi, którą obiecałeś ich ojcom, mówiąc, że wejdą, aby ją posiąść.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 24, 'Weszli więc synowie i posiedli tę ziemię, gdy poniżyłeś przed nimi mieszkańców tej ziemi, Kananejczyków, których wydałeś w ich ręce, oraz ich królów i narody tej ziemi, aby postąpili z nimi według swojej woli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 25, 'Zdobyli warowne miasta i tłustą ziemię i posiedli domy pełne wszelkich dóbr, wykopane studnie, winnice, oliwniki i drzewa owocowe w obfitości. Jedli do syta i utyli, i rozkoszowali się w twojej wielkiej dobroci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 26, 'Ale stali się oporni i zbuntowali się, rzucili twoje Prawo za siebie, zabili twoich proroków, którzy świadczyli przeciwko nim, aby ich nawrócić do ciebie, i dopuszczali się wielkich bluźnierstw.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 27, 'Wydałeś ich więc w ręce ich wrogów, którzy ich uciskali. A gdy w czasie swego ucisku wołali do ciebie, ty z nieba wysłuchałeś ich i według swego wielkiego miłosierdzia dawałeś im wybawicieli, którzy ich wybawiali z rąk wrogów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 28, 'Lecz gdy mieli spokój, znowu czynili zło przed tobą. Dlatego pozostawiłeś ich w ręce ich wrogów, aby panowali nad nimi. Lecz gdy znowu zawracali i wołali do ciebie, ty z nieba wysłuchiwałeś ich i wielokrotnie wybawiałeś ich według swojej litości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 29, 'I świadczyłeś przeciwko nim, aby ich nawrócić ku twojemu Prawu. Oni jednak zuchwale postępowali i nie słuchali twoich przykazań, i grzeszyli przeciwko twoim sądom, przez które – jeśli człowiek je zachowa, będzie żył. Odwracali plecy, czynili twardym swój kark i nie chcieli słuchać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 30, 'Przez wiele lat znosiłeś ich, świadcząc przeciwko nim przez swego Ducha za pośrednictwem swoich proroków, lecz nie chcieli słuchać. Wtedy wydałeś ich w ręce narodów tych ziem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 31, 'Ale ze względu na swoje wielkie miłosierdzie nie wyniszczyłeś i nie opuściłeś ich, gdyż jesteś Bogiem łaskawym i miłosiernym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 32, 'Teraz więc, nasz Boże, Boże wielki, potężny i wzbudzający grozę, dotrzymujący przymierza i miłosierdzia, niech nie wyda ci się małe całe utrapienie, które przyszło na nas, na naszych królów, na naszych książąt, na naszych kapłanów, na naszych proroków, na naszych ojców i na cały twój lud, od czasów królów Asyrii aż do dziś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 33, 'Aczkolwiek ty jesteś sprawiedliwy we wszystkim, co nam przyszło, bo postąpiłeś sprawiedliwie, a my postąpiliśmy niegodziwie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 34, 'Nasi królowie, nasi książęta, nasi kapłani i nasi ojcowie nie wypełnili twojego prawa ani nie przestrzegali twoich przykazań i świadectw, przez które świadczyłeś przeciwko nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 35, 'Oni bowiem, żyjąc w swoim królestwie, pośród twojej wielkiej dobroci, którą im okazałeś, w ziemi przestronnej i tłustej, którą im dałeś, nie służyli tobie ani nie odwrócili się od swoich niegodziwych uczynków.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 36, 'Oto jesteśmy dziś niewolnikami, w ziemi, którą dałeś naszym ojcom, aby jedli jej owoc i dobra, oto jesteśmy niewolnikami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 37, 'Ona wydaje obfite plony królom, których ustanowiłeś nad nami za nasze grzechy. Oni panują nad naszym ciałem i nad naszym bydłem według swojej woli, a my jesteśmy w wielkim ucisku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 38, 'W związku z tym wszystkim zawieramy mocne przymierze i zapisujemy je, a nasi książęta, Lewici i kapłani pieczętują je.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 1, 'A oto ci, którzy pieczętowali: Nehemiasz, Tirszata, syn Chakaliasza, następnie Sedekiasz;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 2, 'Serajasz, Azariasz, Jeremiasz;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 3, 'Paszchur, Amariasz, Malkiasz;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 4, 'Chattusz, Szebaniasz, Malluk;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 5, 'Charim, Meremot, Obadiasz;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 6, 'Daniel, Ginneton, Baruch;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 7, 'Meszullam, Abiasz, Mijamin;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 8, 'Maazjasz, Bilgaj i Szemajasz. To byli kapłani.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 9, 'A Lewici: Jeszua, syn Azaniasza, Binnuj, jeden z synów Chenadada, Kadmiel;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 10, 'I bracia ich: Szebaniasz, Hodiasz, Kelita, Pelajasz, Chanan;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 11, 'Mika, Rechob, Chaszabiasz;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 12, 'Zakkur, Szerebiasz, Szebaniasz;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 13, 'Hodiasz, Bani i Beninu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 14, 'Naczelnicy ludu: Parosz, Pachat-Moab, Elam, Zattu, Bani;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 15, 'Bunni, Azgad, Bebaj;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 16, 'Adoniasz, Bigwaj, Adin;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 17, 'Ater, Ezechiasz, Azzur;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 18, 'Hodiasz, Chaszum, Besaj;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 19, 'Charif, Anatot, Nebaj;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 20, 'Magpiasz, Meszullam, Chezir;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 21, 'Meszezabeel, Sadok, Jaddua;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 22, 'Pelatiasz, Chanan, Anajasz;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 23, 'Ozeasz, Chananiasz, Chaszub;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 24, 'Hallochesz, Pilcha, Szobek;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 25, 'Rechum, Chaszabna, Maasejasz;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 26, 'I Achiasz, Chanan, Anan;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 27, 'Malluk, Charim i Baana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 28, 'A pozostali z ludu, kapłani, Lewici, odźwierni, śpiewacy, Netinici i wszyscy, którzy odłączyli się od narodów tych ziem do prawa Bożego: ich żony, synowie i córki, każdy umiejętny i rozumny;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 29, 'Przyłączyli się do swoich braci i do swoich dostojników, zobowiązując się pod klątwą i przysięgą, że będą postępować według prawa Bożego, które zostało nadane przez Mojżesza, sługę Boga, że będą zachowywać i wypełniać wszystkie przykazania Pana, naszego Pana, oraz jego sądy i ustawy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 30, 'I że nie damy naszych córek narodom tej ziemi ani ich córek nie weźmiemy dla naszych synów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 31, 'A jeśli ludy tej ziemi będą przynosiły na sprzedaż w dzień szabatu jakikolwiek towar albo zboże, nie będziemy brać od nich w szabat ani w święto. Siódmego roku zaniechamy uprawy ziemi oraz żądania wszelkiego długu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 32, 'Ustanowiliśmy sobie też zobowiązanie, że każdego roku będziemy dawać jedną trzecią sykla na służbę w domu naszego Boga;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 33, 'Na chleb pokładny, na nieustanną ofiarę z pokarmów, na nieustanne całopalenia, w szabaty, w dni nowiu, w święta uroczyste, na rzeczy święte, na przebłagalne ofiary za grzech dla Izraela i na wszelkie prace w domu naszego Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 34, 'Rzuciliśmy też losy w sprawie ofiary drewna: kapłani, Lewici i lud, aby przynoszono je do domu naszego Boga według rodów, rokrocznie w oznaczonym czasie, aby było spalane na ołtarzu Pana, naszego Boga, jak jest napisane w Prawie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 35, 'Będziemy też rokrocznie przynosić do domu Pana pierwociny naszej ziemi i pierwociny wszelkiego owocu każdego drzewa;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 36, 'I pierworodnych naszych synów, pierworodne naszego bydła, jak jest napisane w Prawie, i pierworodne naszych wołów i owiec – będziemy przynosić do domu naszego Boga, do kapłanów służących w domu naszego Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 37, 'Również pierwociny naszych ciast i ofiar podniesionych, owoc wszelkiego drzewa, moszczu i oliwy – przyniesiemy to do kapłanów, do komnat domu naszego Boga, a dziesięcinę naszej ziemi do Lewitów, aby ci Lewici otrzymali dziesięcinę z naszej pracy we wszystkich miastach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 38, 'Kapłan, syn Aarona, będzie z Lewitami, gdy będą oni pobierać dziesięcinę. A Lewici wniosą dziesięcinę z dziesięciny do domu naszego Boga, do komnat skarbca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 39, 'Do tych bowiem komnat synowie Izraela i Lewiego mają przynosić ofiarę zboża, moszczu i oliwy tam, gdzie są naczynia świątyni, kapłani pełniący służbę, odźwierni i śpiewacy. Tak oto nie zaniedbamy domu naszego Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 1, 'Przełożeni ludu zamieszkali więc w Jerozolimie, a reszta ludu rzucała losy, aby wyznaczyć jednego z dziesięciu na zamieszkanie w Jerozolimie, w świętym mieście, a dziewięciu pozostałych w innych miastach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 2, 'I lud błogosławił wszystkim mężczyznom, którzy dobrowolnie postanowili zamieszkać w Jerozolimie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 3, 'Oto naczelnicy tej prowincji, którzy zamieszkali w Jerozolimie – ale w innych miastach Judy mieszkali Izraelici, kapłani, Lewici, Netinici i synowie sług Salomona, każdy w swojej posiadłości, w swoim mieście:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 4, 'I tak w Jerozolimie mieszkali niektórzy z synów Judy i Beniamina. Z synów Judy: Ataja, syn Uzjasza, syna Zachariasza, syna Amarasza, syna Szefatiasza, syna Mahalaleela z synów Peresa;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 5, 'Także Maasejasz, syn Barucha, syna Kol-Chozego, syna Chasajasza, syna Chadajasza, syna Jojariba, syna Zachariasza, syna Szilonity.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 6, 'Wszystkich synów Peresa mieszkających w Jerozolimie było czterystu sześćdziesięciu ośmiu dzielnych mężczyzn.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 7, 'A to są synowie Beniamina: Sallu, syn Meszullama, syna Joeda, syna Pedajasza, syna Kolajasza, syna Maasejasza, syna Itiela, syna Jesajasza;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 8, 'A po nim Gabbaj, Sallaj, razem dziewięciuset dwudziestu ośmiu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 9, 'I Joel, syn Zikriego, był ich przełożonym, a Juda, syn Senua, był postawiony jako drugi nad miastem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 10, 'Z kapłanów: Jedajasz, syn Jojariba, i Jachyn;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 11, 'Serajasz, syn Chilkiasza, syna Meszullama, syna Sadoka, syna Merajota, syna Achituba – był on przełożonym domu Bożego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 12, 'I ich bracia, którzy pełnili służbę w domu – razem ośmiuset dwudziestu dwóch. Potem Adajasz, syn Jerochama, syna Pelaliasza, syna Amsiego, syna Zachariasza, syna Paszchura, syna Malkiasza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 13, 'I jego bracia, naczelnicy rodów – dwustu czterdziestu dwóch. I Amaszaj, syn Asareel, syna Achzaja, syna Meszillemota, syna Immera.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 14, 'I ich bracia, dzielni wojownicy – stu dwudziestu ośmiu. Ich przełożonym był Zabdiel, syn Haggedolima.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 15, 'A z Lewitów: Szemejasz, syn Chaszuba, syna Azrikama, syna Chaszabiasza, syna Bunniego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 16, 'Szabbetaj i Jozabad, z przełożonych Lewitów, byli odpowiedzialni za służbę na zewnątrz domu Bożego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 17, 'A Mattaniasz, syn Miki, syna Zabdiego, syna Asafa, kierował pieśń dziękczynną przy modlitwie. A Bakbukiasz był drugim spośród swoich braci, potem Abda, syn Szammuy, syna Galala, syna Jedutuna.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 18, 'Wszystkich Lewitów w świętym mieście było dwustu osiemdziesięciu czterech.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 19, 'Odźwierni: Akkub, Talmon i ich bracia, którzy trzymali straż przy bramach – razem stu siedemdziesięciu dwóch.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 20, 'A pozostali z Izraela, z kapłanów i z Lewitów mieszkali we wszystkich miastach Judy, każdy w swoim dziedzictwie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 21, 'Ale Netinici mieszkali na Ofelu, a Sicha i Giszpa stali na czele Netinitów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 22, 'Przełożonym nad Lewitami w Jerozolimie był Uzzi, syn Baniego, syna Chaszabiasza, syna Mattaniasza, syna Miki. Ci z synów Asafa byli śpiewakami przy służbie w domu Bożym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 23, 'Istniał bowiem co do nich rozkaz króla, wyznaczający śpiewakom dzienną porcję na ich utrzymanie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 24, 'Petachiasz, syn Meszezabeela, z synów Zeracha, syna Judy, był przy boku króla w każdej sprawie dotyczącej ludu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 25, 'A co do wsi i ich pól, niektórzy z synów Judy mieszkali w Kiriat-Arba i przynależnych do niego wsiach, w Dibonie i przynależnych do niego wsiach oraz w Jekkabseel i przynależnych do niego wsiach;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 26, 'W Jeszua, Moladzie i Bet-Pelet;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 27, 'W Chasar-Szual i w Beer-Szebie i przynależnych do niej wsiach;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 28, 'W Siklag i w Mekona i przynależnych do niego wsiach;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 29, 'W En-Rimmon, Sorea i Jarmut;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 30, 'W Zanoach i w Adullam i przynależnych do nich wsiach, w Lakisz i na przynależnych do niego polach i w Azece i przynależnych do niej wsiach. Mieszkali więc od Beer-Szeby aż do doliny Hinnom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 31, 'Synowie Beniamina z Geba mieszkali w Mikmas, Ajja i w Betel i przynależnych do niego wsiach;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 32, 'W Anatot, Nob i Anania;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 33, 'W Chasor, Rama i Gittaim;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 34, 'W Chadid, Seboim i Neballat;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 35, 'W Lod i Ono, i w Dolinie Rzemieślników.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 36, 'A spośród Lewitów mieszkali niektórzy w działach Judy i Beniamina.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 1, 'A oto kapłani i Lewici, którzy przybyli z Zorobabelem, synem Szealtiela, i z Jeszuą: Serajasz, Jeremiasz, Ezdrasz;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 2, 'Amariasz, Malluk, Chattusz;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 3, 'Szekaniasz, Rechum, Meremot;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 4, 'Iddo, Ginneton, Abiasz;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 5, 'Mijamin, Maadiasz, Bilga;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 6, 'Szemajasz, Jojarib, Jedajasz;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 7, 'Sallu, Amok, Chilkiasz, Jedajasz. To byli przedniejsi z kapłanów i ze swoich braci za dni Jeszuy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 8, 'A Lewici: Jeszua, Binnuj, Kadmiel, Szerebiasz, Juda i Mattaniasz, który wraz z braćmi kierował śpiewem pieśni dziękczynnych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 9, 'A Bakbukiasz i Unni, ich bracia, stali naprzeciw nich w swoich służbach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 10, 'Jeszua spłodził Jojakima, a Jojakim spłodził Eliasziba, a Eliaszib spłodził Jojadę;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 11, 'Jojada spłodził Jonatana, a Jonatan spłodził Jadduę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 12, 'A za dni Jojakima naczelnikami rodu byli następujący kapłani: z Serajasza – Merajasz, z Jeremiasza – Chananiasz;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 13, 'Z Ezdrasza – Meszullam, z Amariasza – Jehochanan;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 14, 'Z Malluki – Jonatan, z Szebaniasza – Józef;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 15, 'Z Charima – Adna, z Merajota – Chelkaj;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 16, 'Z Iddo – Zachariasz, z Ginneto – Meszullam;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 17, 'Z Abiasza – Zikri, z Miniamina i Moadiasza – Piltaj;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 18, 'Z Bilgi – Szammua, z Szemajasza – Jonatan;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 19, 'A z Jojariba – Mattenaj, z Jedajasza – Uzzi;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 20, 'Z Sallaj – Kallaj, z Amoka – Eber;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 21, 'Z Chilkiasza – Chaszabiasz, z Jedajasza – Netanaeel.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 22, 'Za dni Eliasziba, Jojady, Jochanana i Jadduy Lewici zostali spisani jako naczelnicy rodów, a także kapłani, aż do panowania Dariusza Persa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 23, 'Synowie Lewiego, naczelnicy rodów, zostali spisani w księdze kronik aż do dni Jochanana, syna Eliasziba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 24, 'Naczelnikami Lewitów byli: Chaszabiasz, Szerebiasz, Jeszua, syn Kadmiela, i ich bracia, którzy stali naprzeciw nich, straż przy straży, aby chwalić i dziękować, według rozkazu Dawida, męża Bożego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 25, 'Mattaniasz i Bakbukiasz, Obadiasz, Meszullam, Talmon i Akkub jako odźwierni trzymali straż przy składnicach u bram.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 26, 'Ci żyli za dni Jojakima, syna Jeszuy, syna Jocadaka, i za dni namiestnika Nehemiasza i Ezdrasza, kapłana i uczonego w Piśmie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 27, 'I na poświęcanie muru Jerozolimy odszukano Lewitów ze wszystkich ich miejsc, aby ich przyprowadzić do Jerozolimy, by mogli obchodzić poświęcenie z radością, dziękczynieniem, przy śpiewaniu, cymbałach, cytrach i harfach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 28, 'Zgromadzili się więc synowie śpiewaków, z równin wokół Jerozolimy i ze wsi Netofatytów;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 29, 'Także z domu Gilgal, z pól Geba i z Azmawet. Śpiewacy bowiem zbudowali sobie wsie wokół Jerozolimy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 30, 'Wtedy kapłani i Lewici oczyścili się, po czym oczyścili też lud, bramy i mur.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 31, 'Następnie kazałem przełożonym Judy wstąpić na mur i ustawiłem dwa wielkie zespoły dziękczynne, z których jeden szedł po murze na prawo, w kierunku Bramy Gnojnej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 32, 'Za nim szedł Hoszajasz i połowa przełożonych Judy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 33, 'Także Azariasz, Ezdrasz i Meszullam;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 34, 'Juda, Beniamin, Szemajasz i Jeremiasz;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 35, 'Potem szli niektórzy z synów kapłanów z trąbami, mianowicie: Zachariasz, syn Jonatana, syna Szemajasza, syna Mattaniasza, syna Michajasza, syna Zakkura, syna Asafa;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 36, 'I jego bracia: Szemajasz, Azarel, Milalaj, Gilalaj, Maaj, Netaneel, Juda, Chanani z instrumentami muzycznymi Dawida, męża Bożego, a Ezdrasz, uczony w Piśmie, szedł przed nimi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 37, 'Następnie przy Bramie Źródlanej, która była naprzeciw nich, szli po schodach miasta Dawida, które prowadzą na mur, znad domu Dawida aż do Bramy Wodnej na wschodzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 38, 'A drugi zespół dziękczynny, a ja za nim, szedł po murze w lewo z drugą połową przełożonych, od Wieży Pieców aż do Muru Szerokiego;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 39, 'I znad Bramy Efraima, nad Bramą Starą, nad Bramą Rybną, obok Wieży Chananeela i Wieży Mea, aż do Bramy Owczej. I stanęli u Bramy Więziennej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 40, 'A tak stanęły oba zespoły dziękczynne w domu Bożym, a wraz z nimi ja i połowa przełożonych ze mną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 41, 'Także kapłani: Eliakim, Maasejasz, Miniamin, Michajasz, Elioenaj, Zachariasz, Chananiasz, z trąbami;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 42, 'I Maasejasz, Szemajasz, Eleazar, Uzzi, Jehochanan, Malkiasz, Elam i Ezer. Śpiewacy głośno śpiewali, a Jizrachiasz był ich kierownikiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 43, 'Tego dnia składali także wielkie ofiary i radowali się. Bóg bowiem dał im wielką radość. Również kobiety i dzieci radowały się, a radość Jerozolimy słychać było z daleka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 44, 'W tym czasie ustanowiono mężczyzn nad składnicami dla skarbów, ofiar, pierwocin i dziesięcin, aby w nich zgromadzono dla kapłanów i Lewitów udziały przyznane im przez Prawo z pól miejskich. Juda bowiem cieszył się z powodu kapłanów i Lewitów pełniących służbę;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 45, 'I śpiewacy i odźwierni pełnili służbę dla swego Boga i służbę oczyszczenia, według rozkazu Dawida i jego syna Salomona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 46, 'Już bowiem dawno, za dni Dawida i Asafa, byli ustanowieni przełożeni nad śpiewakami oraz były ustalone pieśni pochwalne i dziękczynienia dla Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 47, 'Cały Izrael więc za dni Zorobabela i za dni Nehemiasza dawał porcje śpiewakom i odźwiernym na codzienne utrzymanie. Oddawali Lewitom to, co poświęcili, Lewici zaś oddawali to synom Aarona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 1, 'W tym dniu odczytano wobec ludu fragment z księgi Mojżesza. I znaleziono w niej zapis o tym, że Ammonita ani Moabita nigdy nie wejdzie do zgromadzenia Bożego;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 2, 'Ponieważ nie wyszli synom Izraela na spotkanie z chlebem i wodą, lecz wynajęli przeciwko nim Balaama, aby ich przeklął. Nasz Bóg jednak przemienił przekleństwo w błogosławieństwo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 3, 'A gdy usłyszeli to prawo, odłączyli od Izraela wszystkich mieszanego pochodzenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 4, 'Jakiś czas przedtem kapłan Eliaszib, przełożony nad komnatą domu naszego Boga, spowinowacony z Tobiaszem;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 5, 'Przygotował dla niego wielką komnatę, w której składano wcześniej ofiary z pokarmów, kadzidło, naczynia, dziesięciny zboża, moszczu i oliwy, przysługujące Lewitom, śpiewakom i odźwiernym, a także ofiary dla kapłanów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 6, 'Ale przy tym wszystkim nie było mnie w Jerozolimie, gdyż w trzydziestym drugim roku Artakserksesa, króla Babilonu, przyszedłem do króla, a po pewnym czasie wyprosiłem od króla zezwolenie na powrót;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 7, 'A gdy przybyłem do Jerozolimy, dowiedziałem się o występku, którego dopuścił się Eliaszib na korzyść Tobiasza – o tym, że przygotował dla niego komnatę w dziedzińcach domu Bożego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 8, 'A to bardzo mnie oburzyło. Wyrzuciłem więc wszystkie sprzęty domu Tobiasza z komnaty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 9, 'Kazałem wtedy oczyścić te komnaty i z powrotem wniosłem tam sprzęty domu Bożego, dary i kadzidło.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 10, 'Dowiedziałem się także, że przydziały Lewitów nie dostarczono im, a Lewici i śpiewacy, którzy wykonywali pracę, rozbiegli się, każdy do swojego pola.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 11, 'Zgromiłem więc przełożonych, mówiąc: Czemu dom Boży jest opuszczony? Potem zebrałem ich i postawiłem na ich stanowiskach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 12, 'A cały Juda przyniósł dziesięciny ze zboża, moszczu i oliwy do składnic.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 13, 'I nad składnicami ustanowiłem dozorcami Szelemiasza, kapłana, Sadoka, uczonego w Piśmie, i Pedajasza, z Lewitów. Do pomocy mieli Chanana, syna Zakkura, syna Mattaniasza. Oni bowiem uchodzili za wiernych, a ich obowiązkiem było rozdzielanie przydziałów swoim braciom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 14, 'Wspomnij na mnie, mój Boże, za to i nie wymazuj moich dobrych uczynków, których dokonałem dla domu swojego Boga i dla jego służb.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 15, 'W tych dniach widziałem w Judzie ludzi tłoczących prasy w szabat i noszących snopy, które kładli na osły, także winogrona, figi i wszelkie ciężary, które przywozili do Jerozolimy w dzień szabatu. I zgromiłem ich za to, że w ten dzień sprzedają żywność.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 16, 'Także Tyryjczycy, którzy tam mieszkali, przynosili ryby i wszelki towar, a sprzedawali w szabat synom Judy i w Jerozolimie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 17, 'Dlatego zgromiłem przełożonych w Judzie i powiedziałem do nich: Cóż to jest za nieprawość, której się dopuszczacie, bezczeszcząc dzień szabatu?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 18, 'Czy nie tak postępowali wasi ojcowie, za co nasz Bóg sprowadził całe to nieszczęście na nas i na to miasto? A wy ściągacie jeszcze większy gniew na Izraela, bezczeszcząc szabat.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 19, 'A gdy mrok okrył bramy Jerozolimy przed szabatem, rozkazałem zamknąć wrota. Nakazałem też, aby ich nie otwierać aż dopiero po szabacie. Postawiłem również niektórych z moich sług przy bramach, aby nie wnoszono żadnych ciężarów w dzień szabatu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 20, 'Tak więc handlarze i sprzedawcy wszelkiego towaru nocowali raz czy dwa razy poza Jerozolimą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 21, 'Świadczyłem przeciwko nim i powiedziałem do nich: Dlaczego nocujecie przy murze? Jeśli uczynicie to jeszcze raz, podniosę rękę na was. I tak od tego czasu nie przychodzili już w szabat.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 22, 'Następnie rozkazałem Lewitom, aby się oczyścili i przyszli czuwać przy bramach, aby uświęcić dzień szabatu. I pamiętaj mnie za to, mój Boże, i zmiłuj się nade mną według obfitości swojego miłosierdzia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 23, 'W tych dniach widziałem też Żydów, którzy pojęli sobie żony aszdodskie, ammonickie i moabskie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 24, 'A połowa ich dzieci mówiła w języku aszdodskim, nie umiejąc mówić po hebrajsku, ale każdy według języka swego narodu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 25, 'Dlatego zgromiłem ich i przekląłem, a niektórych z nich biłem, wyrwałem ich włosy i zaprzysiągłem ich na Boga: Nie wydawajcie swoich córek ich synom ani nie bierzcie ich córek dla waszych synów ani dla siebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 26, 'Czy nie przez to zgrzeszył Salomon, król Izraela? A przecież wśród wielu narodów nie było króla jak on, był umiłowany przez swego Boga, a Bóg ustanowił go królem nad całym Izraelem. A przecież nawet jego przywiodły do grzechu cudzoziemskie kobiety.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 27, 'Czyż i wam pozwolimy na to, abyście dopuszczali się tego wielkiego zła i grzeszyli przeciwko naszemu Bogu, pojmując za żony cudzoziemki?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 28, 'A jeden z synów Jojady, syna arcykapłana Eliasziba, był zięciem Choronity Sanballata. Wygnałem go więc od siebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 29, 'Zapamiętaj im, mój Boże, że splamili kapłaństwo i przymierze z kapłanami i Lewitami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 30, 'I oczyściłem ich od wszelkiego cudzoziemca, i ustaliłem obowiązki kapłanom i Lewitom, każdemu w swojej służbie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 31, 'I przepisy dotyczące ofiary drewna w ustalonym czasie, a także pierwocin. Wspomnij na mnie, mój Boże, dla mojego dobra.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 1, 'I stało się za dni Aswerusa – tego Aswerusa, który królował od Indii aż do Etiopii nad stu dwudziestoma siedmioma prowincjami;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 2, 'Że w tych dniach, gdy król Aswerus zasiadał na tronie swego królestwa w pałacu Suza;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 3, 'W trzecim roku swego panowania wyprawił u siebie ucztę dla wszystkich swoich książąt i sług. Stawili się przed nim dowódcy Persów i Medów oraz dostojnicy i książęta prowincji.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 4, 'I pokazywał bogactwa i chwałę swego królestwa oraz wspaniałość swego majestatu przez wiele dni, mianowicie przez sto osiemdziesiąt dni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 5, 'A po upływie tych dni król wyprawił ucztę dla wszystkich ludzi znajdujących się w pałacu Suza, od największego aż do najmniejszego, przez siedem dni na dziedzińcu, w ogrodzie pałacu króla.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 6, 'Wisiały w nim białe, zielone i błękitne tkaniny przymocowane sznurami z bisioru i purpury do srebrnych pierścieni na słupach z marmuru. Złote i srebrne łoża stały na posadzce z kryształu i marmuru, z białego i czarnego marmuru.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 7, 'A napój podawano w złotych naczyniach, każde z naczyń było zaś inne, a wina królewskiego było pod dostatkiem, jak przystało na króla.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 8, 'Ale do picia, według polecenia, nikt nikogo nie przymuszał. Tak bowiem rozkazał król wszystkim zarządcom swego domu, aby czynili według woli każdego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 9, 'Królowa Waszti także wyprawiła ucztę dla kobiet w domu królewskim, który należał do króla Aswerusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 10, 'A dnia siódmego, gdy serce króla rozweseliło się winem, rozkazał on Mechumanie, Bizzecie, Charbonie, Bigcie, Abagcie, Zetarowi i Karkasowi, siedmiu eunuchom, którzy służyli przy królu Aswerusie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 11, 'Aby przyprowadzili przed oblicze króla królową Waszti w koronie królewskiej, chcąc pokazać ludowi i książętom jej piękność. Była bowiem bardzo piękna.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 12, 'Ale królowa Waszti odmówiła przyjścia na rozkaz króla, przekazany przez eunuchów. Król więc bardzo się rozgniewał, a gniew w nim zapłonął.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 13, 'Wtedy król zapytał mędrców obeznanych z czasami (gdyż taki był zwyczaj, aby sprawy królewskie przedkładać wszystkim znawcom prawa i sądu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 14, 'A jego najbliższymi byli: Karszena, Szetar, Admata, Tarszisz, Meres, Marsena i Memukan, siedmiu książąt perskich i medyjskich, którzy oglądali oblicze króla i zajmowali pierwsze miejsce w królestwie);');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 15, 'Co według prawa należy czynić z królową Waszti za to, że nie wykonała rozkazu króla Aswerusa przekazanego przez eunuchów?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 16, 'Wtedy Memukan odpowiedział przed królem i książętami: Królowa Waszti wystąpiła nie tylko przeciw samemu królowi, ale przeciw wszystkim książętom i wszystkim ludom, które żyją we wszystkich prowincjach króla Aswerusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 17, 'Kiedy bowiem postępek królowej rozniesie się wśród wszystkich kobiet, wzgardzą one swoimi mężami w swoich oczach i powiedzą: Król Aswerus rozkazał przyprowadzić królową Waszti przed swoje oblicze, a ona nie przyszła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 18, 'Jeszcze dzisiaj księżniczki perskie i medyjskie, które słyszały o postępku królowej, będą mówiły to samo wszystkim książętom króla, a będzie wiele pogardy i gniewu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 19, 'Dlatego więc, jeśli król uzna to za słuszne, niech wyjdzie od króla wyrok i niech będzie wpisany do praw perskich i medyjskich, które są nieodwołalne: Że Waszti nie przyjdzie już przed oblicze króla Aswerusa, a jej godność królewską niech król da innej, lepszej od niej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 20, 'A gdy ten wyrok, wydany przez króla, będzie ogłoszony w całym jego królestwie – a jest ono wielkie – wtedy wszystkie żony okażą szacunek swoim mężom, od wielkiego aż do małego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 21, 'Ta rada podobała się królowi i książętom i król uczynił według rady Memukana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 22, 'I rozesłał listy do wszystkich prowincji królewskich, do każdej prowincji napisany jej własnym pismem, i do każdego ludu w jego języku, aby każdy mężczyzna był panem w swoim domu. A ogłoszono to w języku każdego narodu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 1, 'Po tych wydarzeniach, gdy ustał gniew króla Aswerusa, wspomniał on na Waszti i na to, co uczyniła, oraz dekret, który został wydany przeciwko niej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 2, 'I dworzanie króla, którzy mu usługiwali, powiedzieli: Niech poszukują dla króla młodych dziewic o pięknej urodzie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 3, 'I niech król ustanowi urzędników we wszystkich prowincjach swego królestwa, aby zgromadzili wszystkie młode dziewice o pięknej urodzie w pałacu Suza, w domu kobiet, pod opieką Hegaja, eunucha królewskiego, stróża kobiet, i niech im dadzą środki do ich pielęgnacji.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 4, 'A ta panienka, która spodoba się królowi, zostanie królową w miejsce Waszti. Spodobała się ta rada królowi i tak uczynił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 5, 'A w pałacu Suza był pewien Żyd imieniem Mardocheusz, syn Jaira, syna Szimejego, syna Kisza, z pokolenia Beniamina.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 6, 'Został on uprowadzony z Jerozolimy wraz z innymi pojmanymi, których uprowadzono razem z Jechoniaszem, królem Judy, którego wziął do niewoli Nabuchodonozor, król Babilonu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 7, 'Był on opiekunem Hadassy, to jest Estery, córki swego stryja, nie miała ona bowiem ani ojca, ani matki. A była to panna piękna i urodziwa. Mardocheusz, po śmierci jej ojca i matki, przyjął ją za córkę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 8, 'A gdy ogłoszono rozkaz króla i jego dekret i gdy zgromadzono wiele panien w pałacu Suza pod opieką Hegaja, wzięto też i Esterę do domu króla pod opieką Hegaja, stróża kobiet.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 9, 'I spodobała mu się dziewczyna, i znalazła łaskę w jego oczach, tak że od razu kazał dać jej środki pielęgnacyjne, należną jej część, oraz siedem dobranych dziewcząt z domu króla. Następnie przeniósł ją i jej dziewczęta do najlepszej części w domu kobiet.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 10, 'Ale Estera nie oznajmiła swojego ludu ani pochodzenia, ponieważ Mardocheusz nakazał jej, by tego nie ujawniała.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 11, 'A Mardocheusz każdego dnia przechadzał się przed dziedzińcem domu kobiet, aby się dowiedzieć o zdrowie Estery i co się z nią stanie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 12, 'A gdy nadchodziła kolej na każdą z tych panien, aby wejść do króla Aswerusa po upływie dwunastu miesięcy zgodnie z prawem dla kobiet – był to bowiem okres ich pielęgnacji: sześć miesięcy olejkiem z mirry, a sześć miesięcy wonnościami i innymi środkami pielęgnacji dla kobiet;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 13, 'Wtedy panna udawała się do króla, a czegokolwiek żądała, dawano jej, aby z tym szła z domu kobiet aż do domu królewskiego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 14, 'Wieczorem wychodziła, rano zaś wracała do drugiego domu kobiet pod opiekę Szaaszgaza, eunucha królewskiego, stróża nałożnic. Nie przychodziła już więcej do króla, chyba że spodobała się królowi i wzywano ją po imieniu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 15, 'A gdy przyszła kolej na Esterę, córkę Abichaila, stryja Mardocheusza, który ją przyjął za córkę – aby udała się do króla, nie żądała niczego prócz tego, co polecił Hegaj, eunuch króla, stróż kobiet. I Estera zyskała łaskę w oczach wszystkich, którzy na nią patrzyli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 16, 'Zabrano więc Esterę do króla Aswerusa, do jego domu królewskiego, w dziesiątym miesiącu, to jest w miesiącu Tebet, w siódmym roku jego panowania.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 17, 'I król umiłował Esterę nad wszystkie kobiety, i znalazła ona łaskę i jego przychylność ponad wszystkie panny, tak że włożył jej na głowę koronę królewską i uczynił ją królową w miejsce Waszti.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 18, 'Potem król wyprawił wielką ucztę dla wszystkich swoich książąt i sług, ucztę Estery, a prowincje uwolnił od podatków i porozdawał dary, jak przystało na króla.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 19, 'Gdy ponownie zebrano dziewice, Mardocheusz siedział przy bramie króla.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 20, 'A Estera nie oznajmiła jeszcze swego pochodzenia ani ludu, tak jak jej rozkazał Mardocheusz. Estera wykonała polecenie Mardocheusza, tak jak dawniej, gdy była jeszcze pod jego opieką.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 21, 'W tych dniach, gdy Mardocheusz siedział przy bramie króla, dwaj eunuchowie króla, Bigtan i Teresz, stróże progu, byli rozgniewani i szukali sposobności, aby podnieść rękę na króla Aswerusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 22, 'Dowiedział się o tym Mardocheusz i oznajmił to królowej Esterze, a Estera oznajmiła to królowi w imieniu Mardocheusza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 23, 'A gdy tę sprawę zbadano, okazała się prawdziwa. Powieszono więc obydwu na szubienicy i zapisano to w księgach kronik przed królem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 1, 'Po tych wydarzeniach król Aswerus uczynił wielkim Hamana, syna Hammedaty, Agagitę, wywyższył go i umieścił jego tron ponad wszystkimi książętami, którzy byli przy nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 2, 'A wszyscy słudzy króla, którzy stali w bramie królewskiej, klękali przed Hamanem i oddawali mu pokłon. Tak bowiem rozkazał co do niego król. Ale Mardocheusz nie klękał przed nim ani nie oddawał mu pokłonu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 3, 'Dlatego też słudzy króla, którzy stali w bramie królewskiej, pytali Mardocheusza: Czemu przekraczasz rozkaz króla?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 4, 'A gdy tak do niego dzień po dniu mówili, a on ich nie słuchał, donieśli o tym Hamanowi, aby się przekonać, czy Mardocheusz będzie obstawał przy swoim. Powiedział im bowiem, że jest Żydem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 5, 'A gdy Haman zobaczył, że Mardocheusz nie klęka ani nie oddaje mu pokłonu, Haman napełnił się gniewem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 6, 'Uważał to za rzecz zbyt łagodną podnieść rękę na samego Mardocheusza, ponieważ doniesiono mu, z jakiego ludu pochodzi Mardocheusz. Szukał więc Haman sposobności, aby wytracić wszystkich Żydów, którzy byli w całym królestwie Aswerusa, to jest lud Mardocheusza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 7, 'Tak więc w pierwszym miesiącu, w miesiącu Nisan, w dwunastym roku króla Aswerusa, rzucano przed Hamanem Pur, czyli los, od dnia do dnia i od miesiąca do miesiąca, aż do dwunastego miesiąca, to jest miesiąca Adar.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 8, 'Potem Haman powiedział do króla Aswerusa: Jest pewien lud rozproszony i rozsypany pomiędzy ludami we wszystkich prowincjach twego królestwa. Jego prawa są inne od praw wszystkich ludów, a praw króla nie przestrzega. Dlatego więc nie jest korzystne dla króla tak go pozostawić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 9, 'Jeśli król uzna to za słuszne, niech zostanie zapisane, że ten lud ma być wytracony. A ja odważę dziesięć tysięcy talentów srebra do rąk przełożonych nad tą pracą, aby je wnieśli do skarbca królewskiego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 10, 'Wtedy król zdjął pierścień ze swojej ręki i dał go Hamanowi Agagicie, synowi Hammedaty, wrogowi Żydów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 11, 'Król powiedział do Hamana: Przekazuję ci to srebro i ten lud, abyś uczynił z nim, co ci się podoba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 12, 'Wezwano więc pisarzy króla w pierwszym miesiącu, dnia trzynastego tego miesiąca, i napisano wszystko tak, jak Haman rozkazał, do satrapów królewskich, do namiestników z każdej prowincji i do dowódców każdego ludu z każdej prowincji według jej pisma i do każdego narodu według jego języka. Listy napisano w imieniu króla Aswerusa i opieczętowano je sygnetem króla.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 13, 'Potem rozesłano je przez gońców do wszystkich prowincji królewskich, aby zgładzono, wymordowano i wytracono wszystkich Żydów, od młodego do starca, dzieci i kobiety, w jeden dzień, mianowicie trzynastego dnia dwunastego miesiąca, miesiąca Adar, a ich mienie zagrabiono.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 14, 'A odpis tego pisma miał być podany we wszystkich prowincjach, ogłoszony wszystkim ludom, aby były gotowe na ten dzień.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 15, 'Gońcy więc wyruszyli przynaglani rozkazem króla, a dekret ogłoszono także w pałacu Suza. A król i Haman zasiedli, aby pić, lecz miasto Suza było zatrwożone.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 1, 'Kiedy Mardocheusz dowiedział się o wszystkim, co się stało, rozdarł swoje szaty i przyodział się w wór, następnie posypał się popiołem, wyszedł na środek miasta i lamentował głośno i gorzko.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 2, 'I doszedł aż do bramy królewskiej, gdyż nie wolno było wejść w bramę królewską przyodzianemu w wór.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 3, 'W każdej prowincji, gdzie tylko dotarł rozkaz króla i jego dekret, nastała wielka żałoba wśród Żydów, nastał też post, płacz i lament, a wielu leżało w worze i w popiele.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 4, 'Przyszły więc służące Estery i jej eunuchowie i opowiedzieli jej o tym. Wtedy królowa bardzo się zasmuciła i posłała szaty, aby ubrać Mardocheusza i zdjąć z niego wór. Ale on ich nie przyjął.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 5, 'Wtedy Estera zawołała Hataka, jednego z eunuchów króla, którego on dał jej do posługi, i rozkazała mu pójść do Mardocheusza, aby się dowiedział, co to ma znaczyć i dlaczego tak się stało.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 6, 'Wyszedł więc Hatak do Mardocheusza na plac miejski, który był przed bramą królewską;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 7, 'I Mardocheusz opowiedział mu wszystko, co mu się przydarzyło, także o sumie srebra, którą Haman obiecał odważyć do skarbca królewskiego za Żydów, aby zostali wytraceni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 8, 'Ponadto dał mu odpis dekretu o ich zagładzie, który ogłoszono w Suzie, aby pokazał go Esterze, powiadomił ją i rozkazał, aby poszła do króla, błagając go o swój lud i wstawiając się za nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 9, 'Przyszedł więc Hatak i przekazał Esterze słowa Mardocheusza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 10, 'I Estera odpowiedziała Hatakowi i poleciła mu iść do Mardocheusza:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 11, 'Wszyscy słudzy króla oraz lud z prowincji królewskich wiedzą, że ktokolwiek – mężczyzna lub kobieta – wejdzie do króla na dziedziniec wewnętrzny, nie będąc wezwany, podlega tylko jednemu prawu – ma zostać zabity, z wyjątkiem tego, nad którym król wyciągnie złote berło, ten zostanie przy życiu. Ale mnie nie wezwano, aby wejść do króla, już od trzydziestu dni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 12, 'I powiedziano Mardocheuszowi słowa Estery.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 13, 'Wtedy Mardocheusz polecił przekazać Esterze taką odpowiedź: Nie myśl sobie, że ty jedna spośród wszystkich Żydów ocalejesz w domu królewskim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 14, 'Jeśli bowiem ty całkowicie będziesz milczeć w tym czasie, uwolnienie i wybawienie dla Żydów przyjdzie z innego miejsca, ale ty i dom twego ojca zginiecie. A kto wie, czy nie na tę właśnie chwilę dostąpiłaś godności królestwa?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 15, 'Estera poleciła, by odpowiedziano Mardocheuszowi:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 16, 'Idź, zbierz wszystkich Żydów, którzy się znajdują w Suzie, i pośćcie za mnie, nie jedzcie ani nie pijcie przez trzy dni, nocą i dniem. Ja także i moje służące będziemy pościć, a potem wejdę do króla, choć to niezgodne z prawem. A jeśli zginę, to zginę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 17, 'Poszedł więc Mardocheusz i uczynił wszystko, co mu rozkazała Estera.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 1, 'Trzeciego dnia Estera ubrała się w szaty królowej, stanęła na wewnętrznym dziedzińcu domu króla, naprzeciw domu króla. A król siedział na swoim królewskim tronie w domu króla naprzeciw bramy domu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 2, 'A gdy król zobaczył królową Esterę, stojącą na dziedzińcu, znalazła ona łaskę w jego oczach i król wyciągnął do Estery złote berło, które trzymał w ręku. Estera więc zbliżyła się i dotknęła końca berła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 3, 'Król zapytał ją: Co ci jest, królowo Estero? Jaka jest twoja prośba? Choćbyś prosiła o połowę królestwa, będzie ci dane.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 4, 'Estera odpowiedziała: Jeśli to się królowi podoba, to niech przyjdzie król i Haman dzisiaj na ucztę, którą dla niego przygotowałam.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 5, 'Król powiedział: Zawołajcie szybko Hamana, aby spełnił prośbę Estery. Przyszedł więc król i Haman na ucztę, którą wyprawiła Estera.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 6, 'Potem król zapytał Esterę, gdy się napił wina: Jaka jest twoja prośba, a będzie ci dane. Jakie jest twoje życzenie? Choćbyś prosiła o połowę królestwa, będzie ci dane.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 7, 'Na to Estera odpowiedziała: Oto moje życzenie i moja prośba:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 8, 'Jeśli znalazłam łaskę w oczach króla i jeśli królowi się podoba, aby spełnić moją prośbę i wykonać moje życzenie, to niech przyjdzie król i Haman na ucztę, którą im przygotuję, a jutro uczynię według słowa króla.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 9, 'I wyszedł Haman tego dnia wesoły i dobrej myśli. Ale gdy Haman zobaczył Mardocheusza w bramie królewskiej, że on ani nie powstał, ani się nie poruszył przed nim, napełnił się gniewem na Mardocheusza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 10, 'Opanował się jednak Haman, a gdy przyszedł do domu, posłał po swoich przyjaciół i Zeresz, swoją żonę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 11, 'I opowiadał im Haman o wspaniałości jego bogactwa, o mnóstwie swoich synów oraz o tym wszystkim, jak wielkim król go uczynił i jak go wywyższył ponad innych książąt i sługi króla.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 12, 'Ponadto Haman powiedział: Nawet królowa Estera nikogo oprócz mnie nie zaprosiła na ucztę z królem, którą przygotowała, a jeszcze na jutro zostałem do niej zaproszony z królem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 13, 'Ale to wszystko jest dla mnie niczym, dopóki widzę Żyda Mardocheusza, siedzącego w bramie królewskiej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 14, 'Wtedy jego żona Zeresz oraz wszyscy jego przyjaciele powiedzieli mu: Niech postawią szubienicę wysoką na pięćdziesiąt łokci, a rano powiedz królowi, aby powieszono na niej Mardocheusza. Potem idź wesół z królem na ucztę. I spodobała się Hamanowi ta rada, i rozkazał postawić szubienicę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 1, 'A tej nocy król nie mógł spać, kazał więc przynieść księgę pamiątkową kronik. I odczytano ją przed królem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 2, 'I tam znaleziono zapisek, że to Mardocheusz doniósł na Bigtana i Teresza, dwóch eunuchów króla, stróżów progu, że usiłowali podnieść rękę na króla Aswerusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 3, 'Wtedy król zapytał: Jaką cześć i jaki zaszczyt przyznano za to Mardocheuszowi? Odpowiedzieli słudzy króla, jego dworzanie: Niczego mu nie przyznano.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 4, 'Król zapytał: Kto jest na dziedzińcu? A właśnie Haman przyszedł na zewnętrzny dziedziniec domu królewskiego, aby porozmawiać z królem, by powiesić Mardocheusza na szubienicy, którą dla niego przygotował.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 5, 'Słudzy króla odpowiedzieli mu: Oto Haman stoi na dziedzińcu. Król powiedział: Niech wejdzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 6, 'I Haman wszedł. A król zapytał go: Co uczynić temu mężczyźnie, którego król chce uczcić? A Haman myślał w swoim sercu: Kogo by król chciał uczcić bardziej niż mnie?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 7, 'Odpowiedział Haman królowi: Dla mężczyzny, którego król chce uczcić;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 8, 'Niech przyniosą szatę królewską, w którą się ubiera król, niech przyprowadzą konia, na którym jeździ król, i niech włożą mu koronę królewską na głowę;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 9, 'Potem niech przekażą tę szatę i konia do rąk jednego z najznakomitszych książąt, niech ubiorą tego mężczyznę, którego król chce uczcić, niech go prowadzą na koniu po placu miejskim i niech wołają przed nim: Tak postąpi się z mężczyzną, którego król chce uczcić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 10, 'Wtedy król powiedział do Hamana: Spiesz się, weź szatę i konia, tak jak powiedziałeś, i uczyń tak z Żydem Mardocheuszem, który siedzi w bramie królewskiej. Nie pomiń niczego z tego wszystkiego, co powiedziałeś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 11, 'Haman wziął więc szatę i konia, ubrał Mardocheusza i prowadził go na koniu po placu miejskim, wołając przed nim: Tak postąpi się z mężczyzną, którego król chce uczcić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 12, 'Potem wrócił Mardocheusz do bramy królewskiej, Haman zaś pospieszył się do swego domu smutny, z nakrytą głową.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 13, 'I Haman opowiedział swojej żonie Zeresz i wszystkim swoim przyjaciołom o wszystkim, co mu się przydarzyło. Jego mędrcy i jego żona Zeresz powiedzieli: Jeśli Mardocheusz, przed którym zacząłeś upadać, pochodzi z narodu żydowskiego, to nie przemożesz go, ale niezawodnie upadniesz przed nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 14, 'A gdy oni jeszcze z nim rozmawiali, oto przyszli eunuchowie króla, aby spiesznie zaprowadzić Hamana na ucztę, którą przygotowała Estera.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 1, 'Król i Haman przybyli więc na ucztę do królowej Estery.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 2, 'I drugiego dnia, gdy się napił wina, król znowu zapytał Esterę: Jaka jest twoja prośba, królowo Estero, a będzie ci dane. Jakie jest twoje życzenie? Choćbyś prosiła nawet o połowę królestwa, tak się stanie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 3, 'Wtedy królowa Estera odpowiedziała: Jeśli znalazłam łaskę w twoich oczach, o królu, i jeśli królowi się spodoba, niech będzie mi darowane moje życie na moją prośbę i mój naród na moje życzenie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 4, 'Zostaliśmy bowiem sprzedani, ja i mój lud, aby nas zgładzić, wymordować i wytracić. Gdybyśmy zostali sprzedani jako niewolnicy i niewolnice, milczałabym, chociaż wróg nigdy by nie mógł wynagrodzić tej szkody wyrządzonej królowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 5, 'Wtedy król Aswerus odpowiedział do królowej Estery: Któż to jest i gdzie jest ten, którego serce jest tak nadęte, aby ośmielił się tak uczynić?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 6, 'Estera odpowiedziała: Tym przeciwnikiem i wrogiem jest niegodziwy Haman. I Haman zatrwożył się przed królem i królową.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 7, 'Wówczas król wstał w gniewie, opuścił ucztę i poszedł do ogrodu pałacowego. Haman zaś stał, aby błagać królową Esterę o życie, gdyż widział, że król postanowił jego zgubę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 8, 'Potem król wrócił z ogrodu pałacowego do domu, gdzie się odbywała uczta, a Haman upadł na łoże, na którym siedziała Estera. Wtedy król powiedział: Czy jeszcze chce gwałcić królową przy mnie w domu? A gdy te słowa wyszły z ust króla, natychmiast zakryto twarz Hamana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 9, 'I Charbona, jeden z eunuchów, powiedział do króla: Oto szubienica przygotowana przez Hamana dla Mardocheusza, który dbał o dobro króla, stoi przy domu Hamana, wysoka na pięćdziesiąt łokci. Król powiedział: Powieście go na niej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 10, 'I powieszono Hamana na tej szubienicy, którą przygotował dla Mardocheusza. I tak gniew króla się uspokoił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 1, 'Tego dnia król Aswerus dał królowej Esterze dom Hamana, wroga Żydów, a Mardocheusz przyszedł przed króla, gdyż Estera powiedziała mu, kim on jest dla niej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 2, 'Wtedy król zdjął swój pierścień, który zabrał Hamanowi, i dał go Mardocheuszowi. Estera zaś ustanowiła Mardocheusza nad domem Hamana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 3, 'Potem Estera jeszcze mówiła do króla, upadła mu do nóg i z płaczem prosiła go, aby odwrócił złość Hamana, Agagity, i jego zamiar, który powziął przeciwko Żydom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 4, 'Wtedy król wyciągnął ku Esterze złote berło, a Estera wstała i stanęła przed królem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 5, 'I powiedziała: Jeśli królowi się podoba, jeśli znalazłam łaskę w jego oczach, jeśli król uzna to za słuszne i jeśli ja jestem miła w jego oczach, niech zostanie napisane, aby wycofano listy obmyślone przez Hamana, syna Hammedaty, Agagity, które napisał, aby wytracić Żydów, którzy są we wszystkich prowincjach królewskich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 6, 'Jakże bowiem mogłabym patrzeć na to nieszczęście, które spotka mój lud? Jak mogłabym patrzeć na zgubę mojej rodziny?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 7, 'Wtedy król Aswerus powiedział do królowej Estery i do Żyda Mardocheusza: Oto dałem Esterze dom Hamana, a jego powieszono na szubienicy, ponieważ podniósł rękę na Żydów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 8, 'Napiszcie więc do Żydów to, co uznacie za słuszne, w imieniu króla i zapieczętujcie pierścieniem królewskim. To bowiem, co zostało napisane w imieniu króla i zapieczętowane pierścieniem królewskim, nie może być odwołane.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 9, 'Zwołano więc pisarzy króla w tym czasie, trzeciego miesiąca, to jest miesiąca Siwan, dwudziestego trzeciego dnia tego miesiąca, i napisano wszystko, tak jak nakazał Mardocheusz, do Żydów, do satrapów, do namiestników i do przełożonych prowincji, które rozciągają się od Indii aż do Etiopii, do stu dwudziestu siedmiu prowincji, do każdej prowincji jej pismem i do każdego ludu w jego języku, i do Żydów ich pismem i w ich języku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 10, 'A gdy napisał w imieniu króla Aswerusa i zapieczętował pierścieniem królewskim, rozesłał listy przez gońców jeżdżących na koniach szybkich i na mułach młodych;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 11, 'Że król dał wolność Żydom, którzy byli we wszystkich miastach, aby zgromadzili się i stanęli w obronie swego życia, aby też wytracili, zabili i wygubili wszystkich zbrojnych napadających na nich wśród ludu i prowincji, wraz z ich dziećmi i kobietami, a ich mienie zabrali jako łup;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 12, 'I to w jednym dniu we wszystkich prowincjach króla Aswerusa, mianowicie trzynastego dnia dwunastego miesiąca, to jest miesiąca Adar.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 13, 'Odpis tego pisma, w którym wydano dekret dla każdej prowincji, ogłoszono wszystkim ludom, że Żydzi będą gotowi na ten dzień do pomsty nad swymi wrogami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 14, 'Wtedy wyruszyli gońcy, jeżdżący na szybkich koniach i na mułach, przynaglani rozkazem króla. Dekret ogłoszono także w pałacu Suza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 15, 'A Mardocheusz wyszedł od króla ubrany w niebieskie i białe szaty królewskie, z wielką koroną złotą i w płaszcz z bisioru i purpury. A miasto Suza weseliło i radowało się.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 16, 'Dla Żydów nastały światło i wesele, radość i cześć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 17, 'A w każdej prowincji i w każdym mieście, dokądkolwiek rozkaz króla i jego dekret dotarły, Żydzi mieli wesele, radość, ucztę i doniosły dzień. Wielu zaś spośród ludu tych ziem zostało Żydami. Padł bowiem na nich strach przed Żydami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 1, 'A dwunastego miesiąca, czyli miesiąca Adar, trzynastego dnia tego miesiąca, gdy nadszedł czas wypełnienia rozkazu króla i jego dekretu, tego dnia, kiedy wrogowie Żydów spodziewali się, że będą panować nad nimi, stało się wprost przeciwnie, ponieważ Żydzi panowali nad tymi, którzy ich nienawidzili.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 2, 'Żydzi bowiem zebrali się w swoich miastach we wszystkich prowincjach króla Aswerusa, aby podnieść rękę na tych, którzy pragnęli ich zguby. A nikt nie mógł im stawić oporu, gdyż strach przed nimi padł na wszystkie ludy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 3, 'I wszyscy przełożeni prowincji, satrapowie, namiestnicy i urzędnicy królewscy popierali Żydów, bo padł na nich strach przed Mardocheuszem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 4, 'Mardocheusz był bowiem wielki w domu króla, a jego sława rozchodziła się po wszystkich prowincjach, gdyż Mardocheusz stawał się coraz większy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 5, 'Tak to Żydzi zabili wszystkich swoich wrogów mieczem, mordując i niszcząc, a czynili z tymi, co ich nienawidzili, według swego upodobania.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 6, 'Nawet i w pałacu Suza Żydzi zabili i wytracili pięciuset mężczyzn;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 7, 'I Parszandatę, Dalfona i Aspatę;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 8, 'I Poratę, Adalię i Arydata;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 9, 'I Parmasztę, Arisaja, Aridaja i Wajezatę;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 10, 'Tych dziesięciu synów Hamana, syna Hammedaty, wroga Żydów, zabili, ale po łupy nie wyciągnęli swej ręki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 11, 'Tego samego dnia dotarła do króla wiadomość o liczbie zabitych w pałacu Suza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 12, 'I król powiedział do królowej Estery: W pałacu Suza Żydzi zabili i wytracili pięciuset mężczyzn oraz dziesięciu synów Hamana. A w pozostałych prowincjach królewskich, cóż uczynili? Jaką masz jeszcze prośbę, a będzie spełniona. Czego jeszcze sobie życzysz, a stanie ci się.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 13, 'Estera odpowiedziała: Jeśli się królowi spodoba, niech wolno będzie jutro Żydom, którzy są w Suzie, uczynić według dekretu dzisiejszego i niech powieszą dziesięciu synów Hamana na szubienicy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 14, 'I król rozkazał, aby tak uczyniono. Ogłoszono dekret w Suzie i powieszono dziesięciu synów Hamana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 15, 'A Żydzi, którzy byli w Suzie, zgromadzili się także dnia czternastego miesiąca Adar i zabili w Suzie trzystu mężczyzn, lecz po łupy nie wyciągnęli swojej ręki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 16, 'Pozostali zaś Żydzi, którzy byli w prowincjach królewskich, zebrali się w obronie swojego życia i mieli odpoczynek od swoich wrogów. Zabili siedemdziesiąt pięć tysięcy swoich wrogów, lecz po łupy nie wyciągnęli swojej ręki;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 17, 'W dniu trzynastym miesiąca Adar, a odpoczywali czternastego dnia tego miesiąca i obchodzili go jako dzień uczty i wesela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 18, 'Ale Żydzi, którzy byli w Suzie, zebrali się dnia trzynastego i czternastego tego miesiąca, a piętnastego dnia odpoczęli i obchodzili go jako dzień uczty i wesela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 19, 'Dlatego Żydzi mieszkający we wsiach i w miasteczkach nieobwarowanych obchodzą czternasty dzień miesiąca Adar jako dzień radości, uczty i jako doniosły dzień, w którym posyłają sobie dary żywnościowe.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 20, 'A Mardocheusz spisał te wydarzenia i rozesłał listy do wszystkich Żydów, którzy byli we wszystkich prowincjach króla Aswerusa, bliskich i dalekich;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 21, 'Zobowiązując ich, aby obchodzili czternasty dzień miesiąca Adar i piętnasty dzień tego samego miesiąca, rokrocznie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 22, 'Jako dni, w których Żydzi odpoczęli od swoich wrogów, i miesiąc, który obrócił się im ze smutku w radość, a z płaczu w dzień radości – aby obchodzili je jako dni uczty i wesela oraz posyłania sobie darów żywnościowych, a ubogim darów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 23, 'Wszyscy Żydzi przyjęli to, co sami zaczęli czynić, a co napisał im Mardocheusz;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 24, 'Haman bowiem, syn Hammedaty, Agagity, wróg wszystkich Żydów, wymyślił plan przeciw Żydom, aby ich wytracić, i rzucił Pur, czyli los, aby ich wytracić i zniszczyć;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 25, 'Ale gdy Estera przyszła przed króla, ten wydał dekret na piśmie, aby jego niegodziwy zamiar, który obmyślił przeciwko Żydom, obrócił się na głowę jego, i aby powiesić jego i jego synów na szubienicy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 26, 'Dlatego nazwali te dni Purim, od nazwy Pur. A z powodu wszystkich słów tego listu oraz na podstawie tego, co widzieli i co ich spotkało;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 27, 'Żydzi postanowili i wzięli na siebie, na swoje potomstwo i na wszystkich, którzy się do nich przyłączyli, nieustający obowiązek, aby obchodzono te dwa dni stosownie do pisma i zgodnie z ustalonym czasem każdego roku;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 28, 'I że te dni będą wspominane i obchodzone we wszystkich pokoleniach, w każdej rodzinie, w każdej prowincji i w każdym mieście; że te dni Purim nie zaginą wśród Żydów, a pamięć o nich nie ustanie u ich potomstwa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 29, 'Królowa Estera, córka Abichaila, i Żyd Mardocheusz napisali z całą powagą, aby potwierdzić ten drugi list dotyczący Purim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 30, 'Mardocheusz posłał ten list do wszystkich Żydów, do stu dwudziestu siedmiu prowincji królestwa Aswerusa, ze słowami pokoju i prawdy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 31, 'Aby ustanowić te dni Purim w ustalonym czasie, jak to Żyd Mardocheusz i królowa Estera ustanowili je i jak zobowiązali samych siebie i swoje potomstwo, na pamiątkę postu i ich lamentacji.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 32, 'Nakaz Estery potwierdził ustawę dotyczącą tych dni Purim i zostało to zapisane w księdze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 1, 'Potem król Aswerus nałożył podatek na swoją ziemię i na wyspy morskie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 2, 'A wszystkie dzieła jego potęgi i mocy oraz opis wielkości Mardocheusza, którą wyróżnił go król, czy nie są zapisane w księgach kronik królów Medii i Persji?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 3, 'Żyd Mardocheusz był bowiem drugi po królu Aswerusie, wielki w oczach Żydów i cieszący się uznaniem wśród wielu swoich braci, troszczył się o dobro swego ludu i głosił pokój całemu swemu ludowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 1, 'Był w ziemi Uz człowiek imieniem Hiob; ten człowiek był doskonały i prawy, i bojący się Boga, a stroniący od zła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 2, 'I urodziło mu się siedmiu synów i trzy córki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 3, 'A jego dobytek stanowiło siedem tysięcy owiec, trzy tysiące wielbłądów, pięćset jarzm wołów i pięćset oślic; miał też bardzo liczną służbę. Był on człowiekiem najmożniejszym wśród wszystkich ludzi Wschodu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 4, 'Jego synowie schodzili się i urządzali ucztę, każdy w swoim domu w ustalonym dniu. Posyłali po swoje trzy siostry i zapraszali je, aby jadły i piły wraz z nimi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 5, 'A gdy minęły dni uczty, Hiob posyłał i poświęcał ich. Potem wstawał wczesnym rankiem i składał całopalenia stosownie do ich liczby. Mówił bowiem Hiob: Może moi synowie zgrzeszyli i złorzeczyli Bogu w swoich sercach. Tak Hiob czynił zawsze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 6, 'Zdarzyło się pewnego dnia, gdy synowie Boży przybyli, aby stanąć przed Panem, że też szatan pojawił się wśród nich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 7, 'Wtedy Pan zapytał szatana: Skąd przychodzisz? Szatan odpowiedział Panu: Krążyłem po ziemi i przechadzałem się po niej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 8, 'Pan powiedział do szatana: Czy zwróciłeś uwagę na mojego sługę Hioba – że nie ma nikogo mu równego na ziemi? To człowiek doskonały i prawy, bojący się Boga i stroniący od zła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 9, 'A szatan odpowiedział Panu: Czy Hiob za darmo boi się Boga?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 10, 'Czy nie ogrodziłeś zewsząd jego samego, jego domu i wszystkiego, co ma? Błogosławiłeś dziełom jego rąk, a jego dobytek rozmnożył się na ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 11, 'Ale wyciągnij tylko swoją rękę i dotknij wszystkiego, co ma, a na pewno będzie ci w twarz złorzeczył.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 12, 'Wtedy Pan powiedział do szatana: Oto wszystko, co ma, jest w twojej mocy, tylko na niego nie wyciągaj ręki. I szatan odszedł sprzed oblicza Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 13, 'Zdarzyło się któregoś dnia, gdy jego synowie i córki jedli i pili wino w domu najstarszego brata;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 14, 'Że do Hioba przybył posłaniec i powiedział: Woły orały, a oślice pasły się obok nich;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 15, 'I napadli Sabejczycy, i zabrali je, a sługi pozabijali ostrzem miecza. Uszedłem tylko ja sam, aby cię o tym powiadomić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 16, 'A gdy ten jeszcze mówił, przyszedł inny i powiedział: Ogień Boży spadł z nieba, spalił owce i sługi i pochłonął ich. Uszedłem tylko ja sam, aby cię o tym powiadomić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 17, 'A gdy ten jeszcze mówił, przyszedł inny i powiedział: Chaldejczycy podzieleni na trzy oddziały napadli na wielbłądy, zabrali je, a sługi pozabijali ostrzem miecza. Uszedłem tylko ja sam, aby cię o tym powiadomić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 18, 'A gdy ten jeszcze mówił, przyszedł inny i powiedział: Twoi synowie i córki jedli i pili wino w domu najstarszego brata;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 19, 'A oto gwałtowny wiatr powiał od pustyni i uderzył w cztery węgły domu, tak że zawalił się na dzieci i pomarły. Uszedłem tylko ja sam, aby cię o tym powiadomić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 20, 'Wtedy Hiob wstał, rozdarł swój płaszcz, ogolił swoją głowę, potem upadł na ziemię i oddał pokłon;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 21, 'I powiedział: Nagi wyszedłem z łona swojej matki i nagi tam powrócę. Pan dał, Pan też wziął, niech imię Pana będzie błogosławione.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 22, 'W tym wszystkim Hiob nie zgrzeszył ani nie oskarżał Boga o nic niewłaściwego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 1, 'I znowu pewnego dnia, gdy synowie Boży przybyli, aby stanąć przed Panem, wśród nich przyszedł też szatan, aby stanąć przed Panem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 2, 'Wtedy Pan powiedział do szatana: Skąd przychodzisz? Szatan odpowiedział Panu: Krążyłem po ziemi i przechadzałem się po niej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 3, 'Pan zapytał szatana: Czy zauważyłeś mojego sługę Hioba – że nie ma nikogo mu równego na ziemi? To człowiek doskonały i prawy, bojący się Boga i stroniący od zła. On jeszcze trwa w swojej prawości, choć ty mnie pobudziłeś przeciw niemu, abym go niszczył bez powodu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 4, 'Szatan odpowiedział Panu: Skórę za skórę; wszystko, co człowiek ma, odda za swoje życie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 5, 'Ale wyciągnij tylko swoją rękę i dotknij jego kości i ciała, a na pewno będzie ci w twarz złorzeczył.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 6, 'Wtedy Pan powiedział do szatana: Oto jest w twojej ręce, ale jego życie zachowaj.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 7, 'Wyszedł więc szatan sprzed oblicza Pana i dotknął Hioba bolesnymi wrzodami, od stóp aż po czubek głowy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 8, 'A ten wziął skorupę, aby się nią skrobać, i siedział w popiele.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 9, 'Jego żona powiedziała mu: Jeszcze trwasz w swojej prawości? Złorzecz Bogu i umieraj.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 10, 'I odpowiedział jej: Mówisz, tak jak mówią głupie kobiety. Czy tylko dobro będziemy przyjmować od Boga, a zła przyjmować nie będziemy? W tym wszystkim Hiob nie zgrzeszył swymi ustami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 11, 'A gdy trzej przyjaciele Hioba usłyszeli o całym nieszczęściu, które spadło na niego, przyszli, każdy ze swego miejsca: Elifaz z Temanu, Bildad z Szuach i Sofar z Naamy. Umówili się bowiem, aby przyjść i wraz z nim lamentować, i pocieszyć go.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 12, 'A gdy z daleka podnieśli swoje oczy, nie poznali go. Podnieśli swój głos i płakali, a potem każdy z nich rozdarł swój płaszcz i rzucał proch w górę na swoją głowę;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 13, 'I siedzieli z nim na ziemi przez siedem dni i siedem nocy i żaden z nich nie przemówił do niego ani słowem. Widzieli bowiem ogrom jego bólu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 1, 'Potem Hiob otworzył swoje usta i przeklinał swój dzień.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 2, 'Hiob odezwał się i zawołał:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 3, 'Niech zginie dzień, w którym się urodziłem, i noc, w którą powiedziano: Poczęty mężczyzna.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 4, 'Niech ten dzień stanie się ciemnością, niech o niego nie troszczy się Bóg z wysokości i nie oświetla go światłość.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 5, 'Niech go pokryje ciemność i cień śmierci, niech go ogarnie obłok i przerazi mrok dnia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 6, 'Niech tą nocą zawładnie ciemność, niech nie będzie liczona wśród dni roku i nie wejdzie w liczbę miesięcy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 7, 'Niech ta noc będzie samotna, niech nie będzie w niej radosnego śpiewu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 8, 'Niech przeklną ją ci, którzy przeklinają dzień, którzy są gotowi podnieść swój lament.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 9, 'Niech gwiazdy zaćmią się o zmierzchu, niech nie doczeka się światła ani nie zobaczy zorzy porannej;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 10, 'Bo nie zamknęła drzwi łona mej matki i nie ukryła smutku przed moimi oczami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 11, 'Czemu nie umarłem w łonie? Czemu nie zginąłem, kiedy wyszedłem z łona?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 12, 'Czemu przyjęły mnie kolana? Czemu przyjęły mnie piersi, abym mógł je ssać?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 13, 'Teraz bowiem leżałbym i trwał w spokoju, spałbym i odpoczywał;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 14, 'Z królami i z doradcami ziemi, którzy sobie budowali opustoszałe miejsca;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 15, 'Albo z książętami, którzy mieli złoto i napełnili swe domy srebrem;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 16, 'Albo czemu nie stałem się jak ukryty, martwy płód, jak niemowlęta, które nie widziały światła?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 17, 'Tam bezbożni przestają straszyć, tam pozbawieni siły odpoczywają.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 18, 'Tam więźniowie razem wypoczywają i nie słyszą głosu ciemięzcy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 19, 'Mały i wielki są tam sobie równi i niewolnik jest wolny od swego pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 20, 'Czemu nędznemu dane jest światło, a życie tym, którzy są rozgoryczeni na duszy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 21, 'Którzy z tęsknotą wypatrują śmierci, a ta nie przychodzi, choć jej szukają pilniej niż ukrytych skarbów;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 22, 'Którzy wielce się radują i cieszą, kiedy grób znajdują?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 23, 'Czemu dane jest światło człowiekowi, którego droga jest ukryta i którego Bóg osaczył?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 24, 'Kiedy bowiem mam jeść, przychodzi moje wzdychanie, a moje jęki rozchodzą się jak woda;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 25, 'Bo to, czego się bałem, spotkało mnie, a to, czego się obawiałem, spadło na mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 26, 'Nie byłem bezpieczny, nie miałem spokoju ani odpoczynku, a jednak nadeszła trwoga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 1, 'Wtedy Elifaz z Temanu odpowiedział:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 2, 'Jeśli będziemy rozmawiać z tobą, nie będzie ci przykro? Ale któż może się od mówienia powstrzymać?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 3, 'Oto nauczałeś wielu i ręce słabe umocniłeś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 4, 'Twoje słowa podnosiły upadającego, a omdlałe kolana wzmacniałeś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 5, 'A teraz, gdy to przyszło na ciebie, opadasz z sił, dotknęło cię i się trwożysz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 6, 'Czy twoja bojaźń nie była twoją ufnością, a prawość twoich dróg – twoją nadzieją?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 7, 'Przypomnij sobie, proszę, czy kiedykolwiek zginął ktoś niewinny? Albo gdzie sprawiedliwych wytępiono?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 8, 'Według tego, co zauważyłem, ci, którzy orzą zło i sieją niegodziwość, zbierają je.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 9, 'Od tchnienia Boga giną i od powiewu jego gniewu niszczeją.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 10, 'Ryk lwa, głos dzikiego lwa i zęby lwiątek są złamane.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 11, 'Lew ginie z braku łupu i młode lwicy rozpraszają się.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 12, 'Oto potajemnie doszło do mnie słowo i moje ucho usłyszało szept.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 13, 'W rozmyślaniu o nocnych widzeniach, gdy twardy sen spada na ludzi;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 14, 'Ogarnęły mnie strach i drżenie, od których wszystkie moje kości zadrżały.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 15, 'Wtedy duch przeszedł przed moją twarzą, zjeżyły się włosy na moim ciele.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 16, 'Stanął, lecz nie rozpoznałem jego wyglądu, tylko jakiś kształt był przed moimi oczami; nastała cisza, a potem usłyszałem głos mówiący:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 17, 'Czy śmiertelny człowiek może być sprawiedliwszy niż Bóg? Czy człowiek może być czystszy niż jego Stwórca?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 18, 'Oto swoim sługom nie ufa i w swoich aniołach dostrzega braki;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 19, 'O ileż bardziej w tych, którzy mieszkają w domach glinianych, których podstawa jest w prochu – łatwiej ich zgnieść niż mola.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 20, 'Od poranka aż do wieczora są gładzeni; giną na wieki, a nikt tego nie zauważa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 21, 'Czy ich wspaniałość nie przemija wraz z nimi? Umierają, ale nie w mądrości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 1, 'Wołaj więc, jeśli jest ktoś, kto by ci odpowiedział; i do którego ze świętych się zwrócisz?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 2, 'Gniew bowiem zabija głupiego, a prostaka uśmierca zawiść.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 3, 'Widziałem głupiego, jak zapuścił korzenie, lecz zaraz przekląłem jego mieszkanie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 4, 'Jego synowie są daleko od ratunku, zostają zdeptani w bramie, a nie ma nikogo, kto by ich ocalił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 5, 'Jego żniwo głodny pożera, wydobywa je spośród samych cierni, a chciwy pochłania ich bogactwa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 6, 'Utrapienie bowiem nie powstaje z prochu ani z ziemi nie wyrasta niedola;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 7, 'Lecz człowiek rodzi się na niedolę, jak iskry z węgla wzlatują w górę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 8, 'Ja jednak szukałbym Boga i Bogu przedstawił swoją sprawę;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 9, 'Który czyni rzeczy wielkie i niezbadane, cudowne i niezliczone;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 10, 'Który zsyła deszcz na ziemię i spuszcza wody na pola;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 11, 'Który pokornych stawia wysoko, a smutnych wywyższa ku zbawieniu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 12, 'Który wniwecz obraca zamysły przebiegłych, tak że ich ręce nie wykonują ich zamiaru;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 13, 'Który chwyta mądrych w ich przebiegłości, tak że rada przewrotnych szybko upada.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 14, 'Za dnia napotykają ciemność, a w południe idą po omacku jak w nocy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 15, 'On wybawia ubogiego od miecza, od ich ust, i z ręki mocarza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 16, 'Tak to uciśniony ma nadzieję, a nieprawość zamyka swe usta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 17, 'Oto błogosławiony człowiek, którego Bóg karze; nie gardź więc karceniem Wszechmocnego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 18, 'On bowiem rani, ale i opatruje, uderza, a jego ręce uzdrawiają.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 19, 'Z sześciu nieszczęść cię wyrwie, a w siódmym nie dotknie cię zło.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 20, 'W głodzie wybawi cię od śmierci, a na wojnie od mocy miecza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 21, 'Przed biczem języka będziesz zasłonięty i nie ulękniesz się spustoszenia, gdy nadejdzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 22, 'Będziesz się śmiał ze spustoszenia i głodu, nie będziesz się bał zwierząt ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 23, 'Zawrzesz bowiem przymierze z kamieniami na polu, a okrutny zwierz polny będzie żyć z tobą w pokoju.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 24, 'I poznasz, że twój przybytek jest spokojny; odwiedzisz swoje mieszkanie, a nie zgrzeszysz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 25, 'Poznasz też, że twoje potomstwo się rozmnoży, a twoje dzieci będą jak trawa ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 26, 'W sędziwym wieku zejdziesz do grobu, jak snop zboża zbierany w swym czasie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 27, 'Oto do tego doszliśmy i tak jest. Słuchaj tego i rozważ to sobie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 1, 'Hiob zaś odpowiedział tymi słowami:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 2, 'O gdyby dokładnie zważono moją udrękę i włożono na szalę całe moje nieszczęście!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 3, 'Byłoby to cięższe niż piasek morski. Dlatego moje słowa plączą się.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 4, 'Tkwią we mnie bowiem strzały Wszechmocnego, których jad osuszył mego ducha, a strachy Boże walczą przeciwko mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 5, 'Czy dziki osioł ryczy, gdy ma trawę? Czy wół ryczy nad swoją paszą?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 6, 'Czy można zjeść niesmaczną rzecz bez soli? Czy ma jakiś smak białko jajka?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 7, 'Czego się przedtem moja dusza nie chciała dotknąć, jest to teraz moim bolesnym pokarmem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 8, 'Oby się spełniła moja prośba i Bóg dał mi to, czego pragnę!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 9, 'Oby się Bogu spodobało to, aby mnie zniszczyć, aby opuścić rękę i mnie odciąć!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 10, 'Wtedy miałbym jeszcze pociechę – chociaż pałam boleścią, niech Bóg mi nie folguje – nie zataiłem bowiem słów Świętego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 11, 'Jaka jest moja siła, abym miał wytrwać? Jaki jest mój koniec, abym przedłużał swoje życie?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 12, 'Czy moja siła jest siłą kamieni? Czy moje ciało jest ze spiżu?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 13, 'Czy moja obrona nie jest we mnie? Czy mój rozsądek odszedł ode mnie?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 14, 'Strapionemu należy się litość od przyjaciela, ale on opuścił bojaźń Wszechmogącego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 15, 'Moi bracia zawiedli jak potok, odpływają jak gwałtowne potoki;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 16, 'Które są mętne od lodu, w których śnieg się ukrywa;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 17, 'W czasie roztopów znikają; w czasie upałów nikną ze swego miejsca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 18, 'Wiją się ścieżki ich dróg; rozpływają się w nicość i giną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 19, 'Podróżni z Temy wypatrywali ich; wędrowcy z Seby pokładali w nich nadzieję.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 20, 'Ale zawiedli się w oczekiwaniu, przyszli tam i zawstydzili się.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 21, 'Staliście się niczym; widzicie moją niedolę i lękacie się.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 22, 'Czy powiedziałem: Przynieście mi coś? lub: Dajcie mi z waszego majątku?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 23, 'Lub: Wybawcie mnie z rąk wroga? lub: Wykupcie mnie z rąk okrutników?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 24, 'Pouczcie mnie, a zamilknę; pokażcie mi, w czym zbłądziłem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 25, 'O jak mocne są słowa prawdziwe! Ale cóż sprawi wasze obwinianie?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 26, 'Czy zamierzacie ganić moje słowa i mowę zrozpaczonego, jakby były wiatrem?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 27, 'Nawet sierotę przytłaczacie i kopiecie doły pod swoim przyjacielem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 28, 'Teraz więc zechciejcie spojrzeć na mnie, a zobaczycie, czy kłamię wam w oczy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 29, 'Zawróćcie, proszę, a niech nie będzie w was nieprawości; zawróćcie, a poznacie moją sprawiedliwość w tym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 30, 'Czy w moim języku jest nieprawość? Czy moje podniebienie nie rozeznaje przewrotności?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 1, 'Czy człowiekowi nie jest wyznaczony czas na ziemi? Czy jego dni nie są jak dni najemnika?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 2, 'Jak sługa pragnie cienia, jak najemnik oczekuje zapłaty za swoją pracę;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 3, 'Tak moim udziałem są miesiące próżne, a przeznaczono mi noce bolesne.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 4, 'Gdy się kładę, mówię: Kiedy minie noc, abym mógł wstać? I jestem pełny niepokoju aż do świtu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 5, 'Moje ciało pokryte jest robactwem i strupami w prochu, moja skóra pęka i ropieje.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 6, 'Moje dni biegną szybciej niż czółenko tkackie i przemijają bez nadziei.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 7, 'Pamiętaj, że moje życie jest wiatrem, moje oko już nie zobaczy dobra.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 8, 'Oko, które mnie widziało, już mnie nie zobaczy. Twoje oczy są zwrócone na mnie, a mnie już nie ma.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 9, 'Jak obłok się rozchodzi i przemija, tak ten, kto zstępuje do grobu, nie wraca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 10, 'Nie wróci już do swego domu ani nie pozna go już jego miejsce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 11, 'Dlatego nie mogę powstrzymać swoich ust, będę mówił w utrapieniu swego ducha, będę narzekał w goryczy swojej duszy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 12, 'Czy jestem morzem albo wielorybem, że postawiłeś przy mnie straż?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 13, 'Gdy mówię: Pocieszy mnie moje łóżko i moje posłanie ulży mojemu narzekaniu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 14, 'Wtedy straszysz mnie snami i przerażasz mnie widzeniami;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 15, 'Tak że moja dusza wybrałaby sobie uduszenie, raczej śmierć niż życie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 16, 'Uprzykrzyło mi się życie, nie chcę żyć wiecznie. Zostaw mnie, bo moje dni są marnością.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 17, 'Czym jest człowiek, że go tak wywyższasz i że zwracasz ku niemu swoje serce?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 18, 'Że nawiedzasz go każdego ranka i w każdej chwili doświadczasz?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 19, 'Kiedy odwrócisz się ode mnie i zostawisz mnie, abym mógł przełknąć swoją ślinę?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 20, 'Zgrzeszyłem, cóż mam czynić, stróżu człowieka? Czemu mnie wziąłeś za cel, abym był sam dla siebie ciężarem?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 21, 'Czemu nie przebaczysz mojego przestępstwa i nie zmażesz mojej nieprawości? Teraz bowiem położę się w prochu i gdy rano będziesz mnie szukał, nie będzie mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 1, 'Wtedy Bildad z Szuach odpowiedział:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 2, 'Jak długo będziesz mówił takie rzeczy? Jak długo słowa z twoich ust będą jak gwałtowny wiatr?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 3, 'Czy Bóg wypacza sąd? Czy Wszechmocny wypacza sprawiedliwość?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 4, 'Jeśli twoi synowie zgrzeszyli przeciwko niemu, a on ich odrzucił za ich nieprawość;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 5, 'Jeśli zwrócisz się pilnie do Boga i będziesz błagać Wszechmocnego;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 6, 'Jeśli jesteś czysty i prawy, wtedy na pewno obudzi się dla ciebie i poszczęści mieszkaniu twojej sprawiedliwości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 7, 'A choćby twój początek był niewielki, jednak twój koniec bardzo się rozmnoży.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 8, 'Bo zapytaj, proszę, dawnych pokoleń i rozważ doświadczenie ich ojców;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 9, '(My bowiem jesteśmy wczorajsi i nic nie wiemy, ponieważ nasze dni na ziemi są jak cień).');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 10, 'Czy oni nie pouczą cię i nie powiedzą ci, i czy z ich serc nie wypłyną słowa?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 11, 'Czy sitowie urośnie bez wilgoci? Czy trzcina urośnie bez wody?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 12, 'Chociaż jeszcze jest świeża i nieskoszona, prędzej usycha niż inna trawa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 13, 'Takie są drogi wszystkich, którzy zapominają Boga, i tak zginie nadzieja obłudnika.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 14, 'Jego nadzieja zostanie podcięta, a jego ufność będzie jak pajęczyna.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 15, 'Oprze się o swój dom, ale się nie ostoi; uchwyci się go, ale nie przetrwa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 16, 'Zieleni się na słońcu i w ogrodzie jego świeża latorośl wyrasta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 17, 'Jego korzenie są splątane wśród kamieni i wyrastają spośród nich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 18, 'Ale gdy go wyrwą z jego miejsca, wtedy miejsce to wyprze się go, mówiąc: Nie widziałem cię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 19, 'Takie oto jest szczęście jego drogi, a z ziemi wyrosną inni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 20, 'Oto Bóg nie odrzuci człowieka prawego, ale złoczyńcom nie poda ręki;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 21, 'Aż się napełnią twoje usta uśmiechem, a twoje wargi radością.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 22, 'Gdyż ci, którzy cię nienawidzą, okryją się hańbą, a namiotu niegodziwych już nie będzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 1, 'A Hiob odpowiedział:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 2, 'Doprawdy, wiem, że tak jest. Lecz jak człowiek miałby być usprawiedliwiony przed Bogiem?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 3, 'Gdyby chciał się z nim spierać, nie odpowie mu ani raz na tysiąc.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 4, 'Ma on mądre serce i potężną siłę. Kto mu się sprzeciwił i powodziło mu się?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 5, 'On przenosi góry, a ludzie nie zauważają, przewraca je w swoim gniewie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 6, 'On wstrząsa ziemią z jej miejsca i trzęsą się jej filary.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 7, 'On rozkaże słońcu i ono nie wschodzi, zamyka też gwiazdy pieczęcią.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 8, 'On sam rozciąga niebiosa i kroczy po falach morza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 9, 'On stworzył Niedźwiedzicę, Oriona, Plejady i gwiazdozbiory południa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 10, 'On czyni rzeczy wielkie i niezbadane, cuda, których zliczyć nie można.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 11, 'Oto przechodzi obok mnie, a nie widzę go; mija mnie, a ja go nie dostrzegam.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 12, 'Oto gdy zabiera, któż go powstrzyma? Któż mu powie: Co czynisz?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 13, 'Gdyby Bóg nie odwrócił swego gniewu, zuchwali pomocnicy upadliby pod nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 14, 'Jakże ja mu odpowiem? Jakie słowa wybiorę, aby się z nim spierać?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 15, 'Choćbym był sprawiedliwy, nie odpowiedziałbym mu, lecz błagałbym swojego sędziego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 16, 'Choćbym go wzywał, a on by się odezwał, jeszcze nie uwierzyłbym, że mnie wysłuchał;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 17, 'Kruszy mnie bowiem burzą i pomnaża moje rany bez powodu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 18, 'Nie pozwala mi odetchnąć, raczej napełnia mnie goryczą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 19, 'Jeśli chodzi o siłę, oto jest potężny, a jeśli chodzi o sąd, któż mnie przed nim przyprowadzi?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 20, 'Jeśli się usprawiedliwię, moje usta mnie potępią. Jeśli powiem, że jestem doskonały, to one wykażą, że jestem przewrotny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 21, 'Choćbym był doskonały, przecież nie znałbym swojej duszy; gardziłbym swoim życiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 22, 'Jedno jest pewne, dlatego powiedziałem: On niszczy zarówno doskonałego, jak i niegodziwego;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 23, 'Jeśli bicz nagle zabija, śmieje się on z doświadczenia niewinnych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 24, 'Ziemia została wydana w ręce niegodziwego. On zakrywa oblicze sędziów. A jeśli nie on, któż to czyni?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 25, 'Ale moje dni są szybsze niż goniec, uciekły i nie widziały nic dobrego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 26, 'Przeminęły jak szybkie łodzie, jak orzeł, który rzuca się na żer.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 27, 'Jeśli powiem: Zapomnę o swojej skardze, zaniecham swego gniewu i pocieszę się;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 28, 'Wtedy przerażają mnie wszystkie moje cierpienia, bo wiem, że nie uznasz mnie za niewinnego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 29, 'Jeśli jestem niegodziwy, to czemu trudzę się na próżno?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 30, 'Choćbym się umył wodą ze śniegu i oczyścił mydłem swoje ręce;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 31, 'Ty i tak zanurzysz mnie w dole i moje szaty będą się mną brzydzić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 32, 'On bowiem nie jest człowiekiem jak ja, abym śmiał mu odpowiedzieć i abyśmy razem stanęli przed sądem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 33, 'Nie ma między nami rozjemcy, który mógłby położyć rękę na nas obu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 34, 'Niech tylko zdejmie ze mnie swoją rózgę, a jego groza niech mnie już nie przeraża;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 35, 'Wtedy będę mówił i nie będę się go bać; ale tak nie jest ze mną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 1, 'Moja dusza zmęczona jest życiem; dam upust swemu narzekaniu, będę mówił w goryczy swej duszy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 2, 'Powiem Bogu: Nie potępiaj mnie. Oznajmij mi, czemu wiedziesz ze mną spór?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 3, 'Czy dobrze ci z tym, że mnie uciskasz, że odrzucasz dzieło swoich rąk i sprzyjasz radzie niegodziwych?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 4, 'Czy masz oczy cielesne? Czy widzisz, jak człowiek widzi?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 5, 'Czy twoje dni są jak dni człowieka, a twoje lata jak lata ludzkie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 6, 'Że się wywiadujesz o moją nieprawość i dochodzisz mojego grzechu?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 7, 'Ty wiesz, że nie jestem niegodziwy i nikt nie wyrwie mnie z twoich rąk.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 8, 'Twoje ręce ukształtowały mnie i uczyniły mnie całego ze wszystkich stron, lecz mnie niszczysz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 9, 'Pamiętaj, proszę, że ulepiłeś mnie jak glinę; czy obrócisz mnie w proch?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 10, 'Czy nie wylałeś mnie jak mleko i nie sprawiłeś, że jak ser stężałem?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 11, 'Przyoblekłeś mnie skórą i ciałem, a kośćmi i żyłami pospinałeś mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 12, 'Obdarzyłeś mnie życiem i miłosierdziem, a twoja opatrzność strzegła mego ducha.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 13, 'I chociaż ukryłeś to wszystko w swoim sercu, wiem jednak, że to jest z twojej woli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 14, 'Jeśli grzeszę, ty to spostrzegasz i nie uwolnisz mnie od mojej nieprawości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 15, 'Jeśli jestem niegodziwy, biada mi, a choćbym też był sprawiedliwy, nie podniosę swojej głowy. Jestem syty hańby, zważ na moje utrapienie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 16, 'Gdyż go przybywa; gonisz mnie jak okrutny lew i zachowujesz się dziwnie wobec mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 17, 'Stawiasz przeciwko mnie nowych świadków i pomnażasz nade mną swój gniew; wojsko za wojskiem naciera na mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 18, 'Czemu wyprowadziłeś mnie z łona? Obym umarł i nie widziało mnie żadne oko!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 19, 'Byłbym, jakby mnie nie było, od łona zanieśliby mnie do grobu!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 20, 'Czy nie zostało mi niewiele dni? Przestań więc i odejdź ode mnie, abym nabrał trochę otuchy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 21, 'Zanim odejdę tam, skąd już nie powrócę, do ziemi ciemności i cienia śmierci;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 22, 'Do ziemi ciemnej jak noc i do cienia śmierci i bezładu, gdzie świeci tylko ciemność.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 1, 'Wtedy Sofar z Naamy odpowiedział:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 2, 'Czy nie należy odpowiedzieć na takie mnóstwo słów? Czy człowiek gadatliwy ma być usprawiedliwiony?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 3, 'Czy ludzie mają milczeć na twoje kłamstwa? A gdy kpisz, nikt cię nie zawstydzi?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 4, 'Powiedziałeś bowiem: Moja nauka jest czysta, jestem czysty w twoich oczach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 5, 'O gdyby Bóg zechciał przemówić i otworzyć usta przeciwko tobie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 6, 'Gdyby objawił tajemnice mądrości – że zasługujesz na dwa razy większą karę. Poznaj więc, ile Bóg ci przebaczył za twoją nieprawość.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 7, 'Czy wybadasz tajemnice Boga? Czy zgłębisz doskonałość Wszechmocnego?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 8, 'Są wyżej niż niebiosa, co możesz z tym uczynić? Głębsze niż piekło, czy możesz je poznać?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 9, 'Ich miara jest dłuższa niż ziemia i szersza niż morze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 10, 'Jeśli wycina, zamyka albo gromadzi, któż go powstrzyma?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 11, 'On bowiem zna marność ludzi i widzi niegodziwość. Czy miałby na to nie zważać?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 12, 'Człowiek nierozumny może nabyć rozumu, choć człowiek rodzi się jak źrebię dzikiego osła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 13, 'Jeśli przygotujesz swoje serce i wyciągniesz do niego swoje ręce;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 14, 'Jeśli w twoich rękach jest nieprawość, oddal ją i nie pozwól, aby niegodziwość mieszkała w twoich przybytkach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 15, 'Wtedy podniesiesz swoje oblicze bez zmazy, będziesz stały i nie będziesz się bał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 16, 'Zapomnisz bowiem o swojej udręce i wspomnisz ją tak jak wody, które przepłynęły.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 17, 'I twoje życie będzie jaśniejsze niż południe; twoja ciemność będzie jak poranek.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 18, 'Będziesz ufał, mając nadzieję; będziesz kopać dokoła i odpoczniesz bezpiecznie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 19, 'Położysz się i nikt cię nie przestraszy; wielu uniży się przed twoim obliczem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 20, 'Ale oczy niegodziwych przygasną i nie będzie dla nich ucieczki, a ich nadzieja będzie jak wyzionięcie ducha.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 1, 'Potem Hiob odpowiedział:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 2, 'Doprawdy jesteście ludem i wraz z wami zginie mądrość.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 3, 'Ale ja również mam rozum, jak i wy, i nie jestem od was gorszy. Kto nie zna tych rzeczy?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 4, 'Jestem pośmiewiskiem dla swojego przyjaciela; ja, który wołam do Boga, a on odpowiada; sprawiedliwy i doskonały jest pośmiewiskiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 5, 'Ten, który jest bliski upadku, to pochodnia wzgardzona w umyśle tego, który żyje w pokoju.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 6, 'Namioty łupieżców są spokojne i bezpieczni są ci, którzy drażnią Boga, a którym Bóg obficie daje w ręce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 7, 'Ale zapytaj zwierząt, a one cię pouczą, i ptaków nieba, a powiedzą tobie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 8, 'Albo rozmawiaj z ziemią, a ona cię nauczy, i opowiedzą ci ryby morskie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 9, 'Któż spośród nich wszystkich nie wie, że ręka Pana to wykonała?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 10, 'W jego ręku jest dusza wszelkiej istoty żywej i duch wszelkiego człowieka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 11, 'Czy ucho nie bada mowy, a podniebienie nie smakuje pokarmu?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 12, 'U starców jest mądrość, a w długości dni roztropność.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 13, 'Ale u niego jest mądrość i siła, u niego rada i roztropność.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 14, 'Oto on burzy, a nikt nie może odbudować, zamyka człowieka, a nikt nie może otworzyć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 15, 'Oto gdy zatrzyma wody, wysychają, gdy je wypuści, wywracają ziemię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 16, 'U niego jest moc i mądrość. Do niego należy zwiedziony i zwodziciel.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 17, 'Pozbawia radców mądrości i sędziów czyni głupcami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 18, 'Rozwiązuje więzy królów i przepasuje ich biodra pasem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 19, 'Odprowadza złupionych książąt i wywraca mocarzy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 20, 'Odbiera mowę prawdomównym i zabiera starcom rozsądek.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 21, 'Wylewa pogardę na książąt i osłabia siły mocarzy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 22, 'On odsłania głębokie rzeczy z ciemności i wyprowadza na światło cień śmierci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 23, 'Rozmnaża narody i wytraca je, rozszerza narody i pomniejsza je.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 24, 'On zabiera serca przełożonym ludu ziemi i sprawia, że błądzą po pustyni bezdrożnej;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 25, 'I chodzą po omacku w ciemności bez światła, i sprawia, że zataczają się jak pijani.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 1, 'Oto moje oko widziało to wszystko, moje ucho słyszało i zrozumiało.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 2, 'Co wiecie wy, ja także wiem, nie jestem od was gorszy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 3, 'Dlatego chciałbym mówić z Wszechmocnym i pragnę prawować się z Bogiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 4, 'Wy bowiem jesteście sprawcami kłamstwa, wszyscy jesteście marnymi lekarzami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 5, 'Obyście raczej zamilkli, a uznano by wam to za mądrość.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 6, 'Słuchajcie teraz mojego rozumowania, zważajcie na obronę moich warg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 7, 'Czy w obronie Boga będziecie mówić przewrotnie? Czy za niego będziecie mówić kłamliwie?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 8, 'Czy macie wzgląd na jego osobę? Czy chcecie spierać się po stronie Boga?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 9, 'Czy byłoby dobrze, gdyby was doświadczył? Czy chcecie go oszukać, jak się oszukuje człowieka?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 10, 'Na pewno będzie was karać, jeśli w ukryciu będziecie stronniczy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 11, 'Czy jego majestat was nie przeraża? Czy jego groza na was nie padnie?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 12, 'Wasza pamięć jest jak popiół, a wasze ciała jak ciała z gliny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 13, 'Milczcie, zostawcie mnie, abym przemówił, a niech przyjdzie na mnie, co chce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 14, 'Czemu mam szarpać swoje ciało zębami i kłaść swoje życie w swoje ręce?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 15, 'Oto choćby mnie zabił, jeszcze będę mu ufać. Moich dróg będę jednak przed nim bronić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 16, 'On sam będzie moim zbawieniem, bo żaden obłudnik nie przyjdzie przed jego oblicze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 17, 'Słuchajcie uważnie mojej mowy, niech wasze uszy przyjmą moją wypowiedź.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 18, 'Oto teraz jestem gotowy na sąd i wiem, że zostanę usprawiedliwiony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 19, 'Któż będzie się spierał ze mną? Jeśli bowiem zamilknę, to umrę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 20, 'Tylko dwóch rzeczy mi nie czyń, a nie będę się krył przed tobą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 21, 'Oddal swoją rękę ode mnie i niech twoja groza mnie nie przeraża.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 22, 'Potem zawołaj mnie, a ja ci odpowiem, albo ja przemówię, a ty mi odpowiedz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 23, 'Ile mam nieprawości i grzechów? Daj mi poznać moje przestępstwo i grzech.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 24, 'Czemu zakrywasz swoje oblicze i uważasz mnie za swego wroga?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 25, 'Czy skruszysz liść miotany wiatrem? Czy będziesz gonić suche źdźbło?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 26, 'Piszesz bowiem przeciwko mnie gorzkie rzeczy, każesz mi dziedziczyć nieprawości mojej młodości;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 27, 'Zakułeś moje nogi w dyby, śledzisz wszystkie moje ścieżki i zaznaczasz ślady moich stóp.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 28, 'Niszczeję jak próchno, jak szata, którą zepsują mole.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 1, 'Człowiek, urodzony przez kobietę, ma dni niewiele i ma pełno kłopotów;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 2, 'Wyrasta jak kwiat i zostaje podcięty, znika jak cień i się nie ostaje.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 3, 'A jednak na takiego otwierasz swoje oczy i wzywasz mnie przed siebie na sąd.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 4, 'Któż może wydobyć czystego z nieczystego? Ani jeden.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 5, 'Gdyż jego dni są ustalone, liczba jego miesięcy jest u ciebie; wyznaczyłeś mu kres, którego nie może przekroczyć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 6, 'Odstąp od niego, aby odpoczął, aż zakończy swój dzień jak najemnik.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 7, 'Dla drzewa bowiem jest nadzieja, choć je wytną, że znowu odrośnie, że jego latorośl nie ustanie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 8, 'Choć jego korzeń zestarzeje się w ziemi i jego pień umrze w prochu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 9, 'To jednak gdy poczuje wodę, odrasta i rozpuszcza gałęzie jak sadzonka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 10, 'Ale człowiek umiera i marnieje; a gdy oddaje ducha, gdzie on jest?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 11, 'Jak ubywa wód z morza i rzeka opada, i wysycha;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 12, 'Tak jest z człowiekiem, gdy się położy i już nie wstanie; dopóki niebiosa będą trwać, nie ocknie się ani nie będzie obudzony ze swego snu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 13, 'Obyś mnie w grobie ukrył i schował, aż twój gniew się uciszy, wyznaczył mi czas i wspomniał na mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 14, 'Gdy człowiek umrze, czy znowu ożyje? Przez wszystkie dni wyznaczonego mi czasu będę czekał, aż nadejdzie moja zmiana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 15, 'Zawołasz, a ja ci odpowiem; zatęsknisz za dziełem swoich rąk.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 16, 'Teraz jednak liczysz moje kroki. Czy nie zważasz na mój grzech?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 17, 'Mój występek jest zapieczętowany w woreczku, gromadzisz moje nieprawości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 18, 'Doprawdy, góra pada i rozsypuje się, i skała przesuwa się ze swego miejsca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 19, 'Wody wydrążają kamienie, ulewa podrywa to, co wyrośnie z prochu ziemi, a ty nadzieję człowieka obracasz wniwecz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 20, 'Stale pokonujesz go, a on odchodzi; zmieniasz jego oblicze i odprawiasz go.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 21, 'Jego synowie darzeni są szacunkiem, lecz on o tym nie wie; żyją w pogardzie, lecz na to nie zważa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 22, 'Ale jego własne ciało odczuwa ból, a jego dusza w nim płacze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 1, 'Wtedy Elifaz z Temanu odpowiedział:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 2, 'Czy mądry człowiek ma odpowiadać próżną wiedzą i napełniać swoje wnętrze wiatrem wschodnim?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 3, 'Czy ma się spierać słowami bezużytecznymi i mową, która nie przynosi pożytku?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 4, 'Ty nawet odrzucasz bojaźń i powstrzymujesz modlitwę przed Bogiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 5, 'Twoje usta bowiem pokazują twą nieprawość, posługujesz się mową przebiegłych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 6, 'Twoje usta cię potępiają, a nie ja; twoje wargi świadczą przeciwko tobie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 7, 'Czy jesteś pierwszym człowiekiem, który się urodził? Czy zostałeś stworzony przed pagórkami?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 8, 'Czy słuchałeś tajemnic Boga? Czy tylko w tobie jest mądrość?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 9, 'Cóż ty wiesz, czego my nie wiemy? Cóż ty rozumiesz, czego my nie rozumiemy?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 10, 'Wśród nas są i sędziwi, i starcy, starsi od twego ojca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 11, 'Czy lekceważysz pociechę Boga? Czy masz w sobie coś tajemnego?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 12, 'Czemu cię tak uniosło twoje serce? Czemu swoimi oczami tak mrugasz;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 13, 'Że zwracasz przeciwko Bogu swego ducha i wypuszczasz ze swoich ust takie słowa?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 14, 'Czym jest człowiek, aby miał być czysty, urodzony z kobiety, aby miał być sprawiedliwy?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 15, 'Oto nawet swoim świętym on nie ufa i niebiosa nie są czyste w jego oczach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 16, 'Tym bardziej obrzydły i nikczemny jest człowiek, który pije nieprawość jak wodę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 17, 'Wykażę ci, tylko mnie posłuchaj; opowiem ci, co widziałem;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 18, 'Co mądrzy powiedzieli, a nie zataili, co mieli od przodków swoich;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 19, 'Im samym dana była ziemia i żaden obcy nie przeszedł wśród nich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 20, 'Niegodziwy żyje w udręce przez wszystkie swoje dni i niewiele lat wyznaczono ciemięzcy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 21, 'Głos przerażenia brzmi w jego uszach, że w czasie pokoju napadnie go niszczyciel.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 22, 'Nie wierzy, że miałby wrócić z ciemności, obawia się zewsząd miecza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 23, 'Tuła się za chlebem, pytając, gdzie go znaleźć. Wie, że dzień ciemności został dla niego przygotowany.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 24, 'Przeraża go utrapienie i ucisk; wzmocnią się przeciwko niemu jak król gotowy do boju.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 25, 'Wyciągnął bowiem swą rękę przeciw Bogu, przeciwko Wszechmocnemu się umocnił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 26, 'Naciera na niego, na jego szyję, która jest okryta pod gęstymi grzbietami jego tarcz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 27, 'Swoją twarz kryje bowiem w tłuszczu, a jego tusza zaokrągliła się na lędźwiach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 28, 'Mieszka w opustoszałych miastach i domach, w których nikt nie przebywa, które niebawem staną się ruiną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 29, 'Nie wzbogaci się i nie przetrwa jego majątek ani jego doskonałość nie rozszerzy się na ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 30, 'Nie wyjdzie z ciemności, płomień ususzy jego latorośle, a zginie od tchnienia jego ust.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 31, 'Niech złudzony nie ufa marności, gdyż marność będzie jego zapłatą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 32, 'Przed wypełnieniem jego dni nastąpi, a jego gałązka nie zakwitnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 33, 'Jak winna latorośl utraci swoje niedojrzałe grona, jak oliwka zrzuci swój kwiat.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 34, 'Zgromadzenie obłudników będzie bowiem spustoszone, a ogień strawi namioty przekupstwa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 35, 'Poczęli krzywdę i urodzili nieprawość, a ich łono przygotowuje oszustwo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 1, 'Wtedy Hiob odpowiedział:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 2, 'Słyszałem wiele takich rzeczy; wy wszyscy jesteście przykrymi pocieszycielami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 3, 'Kiedy będzie koniec tych próżnych słów? Albo co cię skłania do tego, że tak odpowiadasz?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 4, 'Ja także mógłbym mówić jak wy; gdybyście byli w moim położeniu, mógłbym nagromadzić słów przeciwko wam i potrząsać głową nad wami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 5, 'Ja jednak pokrzepiałbym was swoimi ustami i poruszanie moich warg ulżyłoby waszym cierpieniom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 6, 'Ale jeśli będę mówił, mojemu bólowi to nie ulży, a jeśli przestanę, czyż opuści mnie?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 7, 'A teraz zmęczył mnie. Spustoszyłeś całe moje zgromadzenie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 8, 'Pomarszczyłeś mnie na świadectwo, a moje wychudzenie powstaje i świadczy przeciwko mnie w twarz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 9, 'Jego gniew mnie porwał, nienawidzi mnie; zgrzyta na mnie zębami. Mój wróg przeszywa mnie wzrokiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 10, 'Otworzyli na mnie swe usta; znieważając, bili mnie po policzkach; zebrali się razem przeciwko mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 11, 'Bóg wydał mnie przewrotnemu, oddał mnie w ręce niegodziwych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 12, 'Żyłem w spokoju, ale on mnie pokruszył; chwycił mnie za kark, roztrzaskał i postawił sobie za cel.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 13, 'Otoczyli mnie jego strzelcy; przeszywa moje nerki, a nie oszczędził; wylał na ziemię moją żółć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 14, 'Rozbija mnie, ranę za raną; naciera na mnie jak olbrzym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 15, 'Uszyłem wór na swoją skórę i prochem zbezcześciłem swój róg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 16, 'Moja twarz jest czerwona od płaczu i na moich powiekach jest cień śmierci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 17, 'Chociaż nie ma żadnej krzywdy na moich rękach, a moja modlitwa jest czysta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 18, 'Ziemio, nie zakrywaj mojej krwi i niech moje wołanie nie znajdzie miejsca!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 19, 'Oto teraz mój świadek jest w niebie, mój obrońca na wysokości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 20, 'Moi przyjaciele szydzą ze mnie, ale moje oko wylewa łzy ku Bogu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 21, 'Oby ktoś spierał się z Bogiem o człowieka jak człowiek spiera się o swego bliźniego!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 22, 'Upłynie bowiem niewiele lat, a pójdę ścieżką, skąd nie powrócę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 1, 'Mój oddech jest skażony, moje dni gasną, groby na mnie czekają.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 2, 'Czy nie szydercy są przy mnie? Czy moje oko nie czuwa przez ich zniewagi?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 3, 'Złóż więc zastaw za mnie u siebie. Któż jest ten, który za mnie poręczy?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 4, 'Ich serce bowiem ukryłeś przed zrozumieniem, dlatego ich nie wywyższysz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 5, 'Kto pochlebia przyjaciołom, tego dzieciom zgasną oczy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 6, 'Uczynił mnie tematem przysłowia wśród ludzi i pośmiewiskiem przed nimi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 7, 'Moje oko zaćmiło się od smutku, a wszystkie moje członki są jak cień.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 8, 'Prawi zdumieją się nad tym, a niewinny powstanie przeciwko obłudnikowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 9, 'Sprawiedliwy będzie trwał przy swojej drodze, a kto ma czyste ręce, nabierze siły.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 10, 'Lecz wy wszyscy zawróćcie i przyjdźcie; bo mądrego wśród was nie znajduję.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 11, 'Moje dni przeminęły, rozwiały się moje zamiary, myśli mego serca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 12, 'Noc zamieniają w dzień, światłość skraca się z powodu ciemności.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 13, 'Gdybym czegoś oczekiwał, grób będzie moim domem, w ciemności rozłożyłem swoje posłanie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 14, 'Powiedziałem do zniszczenia: Jesteś moim ojcem, a robactwu: Moja matko i moja siostro.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 15, 'Gdzie jest więc teraz moja nadzieja? Kto zobaczy moją nadzieję?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 16, 'Zstąpią do zasuw grobu, gdy razem odpoczniemy w prochu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 1, 'Wtedy Bildad z Szuach odpowiedział:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 2, 'Kiedy wreszcie położycie kres tym słowom? Pomyślcie, potem będziemy mówić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 3, 'Czemu uważacie nas za bydło? Czemu jesteśmy obrzydliwi w waszych oczach?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 4, 'Ty, który szarpiesz gniewem swą duszę – czy z twojego powodu będzie opuszczona ziemia i skały będą przesunięte ze swego miejsca?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 5, 'Tak, światło niegodziwych zgaśnie, a iskra jego ognia już nie zaświeci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 6, 'Światło jego przybytku się zaćmi i jego pochodnia nad nim zagaśnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 7, 'Kroki jego siły będą skrępowane, jego własna rada powali go.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 8, 'Jego nogi bowiem zawiodą go w sieć, chodzi po sidłach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 9, 'Sidło uchwyci go za piętę i przemoże go łupieżca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 10, 'Sidło dla niego ukryte jest w ziemi, a pułapka na niego – na drodze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 11, 'Zewsząd będą go przerażać strachy, ścigają go na każdym kroku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 12, 'Głód osłabi jego siły i zniszczenie będzie czyhało u jego boku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 13, 'Pożre żyły jego skóry, pierworodny śmierci pożre jego członki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 14, 'Jego ufność będzie wykorzeniona z jego namiotu i zostanie on przyprowadzony do króla strachów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 15, 'Strach będzie mieszkał w jego namiocie, bo ten nie należy do niego; jego mieszkanie będzie posypane siarką.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 16, 'Od spodu uschną jego korzenie, a z wierzchu będzie obcięta jego gałąź.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 17, 'Pamięć o nim zginie z ziemi, a jego imienia nie wspomną na ulicach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 18, 'Wypędzą go ze światła do ciemności i wyrzucą go z okręgu świata.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 19, 'Nie będzie miał syna ani wnuka pośród swego ludu i nikt nie pozostanie w jego mieszkaniach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 20, 'Ci, którzy przyjdą po nim, osłupieją na jego dzień, tak jak poprzednich ogarnął strach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 21, 'Takie są mieszkania niegodziwych i takie jest miejsce tego, który nie zna Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 1, 'Wtedy Hiob odpowiedział:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 2, 'Jak długo będziecie dręczyć moją duszę i miażdżyć mnie słowami?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 3, 'Już dziesięć razy znieważyliście mnie. Nie wstyd wam, że tak się znęcacie nade mną?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 4, 'A niech tak będzie, że zbłądziłem, błąd zostaje po mojej stronie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 5, 'A jeśli rzeczywiście chcecie się wynosić nade mną i dowodzić mi mojej hańby;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 6, 'Wiedzcie, że to Bóg mnie powalił i swoją siecią mnie otoczył.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 7, 'Oto wołam o krzywdę, ale nikt nie słucha; krzyczę, ale nie ma sądu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 8, 'Zagrodził mi drogę, abym nie mógł przejść, i na moich ścieżkach rozpostarł ciemność.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 9, 'Odarł mnie z mojej chwały i zdjął koronę z mojej głowy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 10, 'Zniszczył mnie ze wszystkich stron i ginę; moją nadzieję wyrwał jak drzewo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 11, 'Zapłonął przeciwko mnie swoim gniewem i uważa mnie za swego wroga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 12, 'Przyszły razem jego oddziały, utorowały przeciw mnie swoją drogę i rozbiły obóz dokoła mojego namiotu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 13, 'Moich braci oddalił ode mnie, a moi znajomi ode mnie stronią.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 14, 'Opuścili mnie moi bliscy, a moi przyjaciele o mnie zapomnieli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 15, 'Przebywający w moim domu i moje służące uważają mnie za obcego. Stałem się cudzoziemcem w ich oczach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 16, 'Wołałem na swego sługę, ale on się nie odzywa, chociaż go błagam swoimi ustami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 17, 'Moim oddechem brzydzi się moja żona, choć błagam ze względu na synów z mojego ciała.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 18, 'Nawet małe dzieci mną gardzą; gdy powstaję, urągają mi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 19, 'Brzydzą się mną wszyscy moi najbliżsi; ci, których kocham, stanęli przeciw mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 20, 'Moje kości przylgnęły do mojej skóry i do mego ciała; pozostała tylko skóra wokół zębów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 21, 'Zlitujcie się nade mną, zlitujcie się nade mną, moi przyjaciele, bo ręka Boża mnie dotknęła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 22, 'Czemu mnie prześladujecie jak Bóg? Czy nie dość wam mojego ciała?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 23, 'Oby teraz zostały zapisane moje słowa! Oby je w księdze utrwalono!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 24, 'Oby rylcem z żelaza i ołowiem zostały na wieczną pamiątkę wyryte na skale!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 25, 'Wiem bowiem, że mój Odkupiciel żyje i że w ostateczny dzień stanie na ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 26, 'A choć moja skóra się rozłoży, to w swoim ciele ujrzę Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 27, 'Ujrzę go ja sam, ujrzą go moje oczy, a nie kto inny, choć moje nerki zniszczały w moim wnętrzu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 28, 'Powinniście mówić: Czemu go prześladujemy? Gdyż we mnie znajduje się korzeń sprawy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 29, 'Wy sami lękajcie się miecza, bo gniew za nieprawość sprowadza miecz, abyście wiedzieli, że jest sąd.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 1, 'Wtedy Sofar z Naama odpowiedział:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 2, 'Dlatego moje myśli skłaniają mnie do odpowiedzi i z tego powodu mówię pośpiesznie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 3, 'Słuchałem obraźliwego upomnienia i duch mojego zrozumienia podsuwa mi odpowiedź:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 4, 'Czy nie wiesz, że od wieków, odkąd człowieka postawiono na ziemi;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 5, 'Radość niegodziwych jest krótka, a wesołość obłudnika trwa okamgnienie?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 6, 'Choćby jego wyniosłość sięgała aż do niebios, a jego głowa – do obłoków;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 7, 'To jednak zginie on na wieki jak jego własny gnój, a ci, którzy go widzieli, powiedzą: Gdzie on się podział?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 8, 'Uleci jak sen i nie znajdą go; ucieknie jak nocne widzenie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 9, 'Oko, które go widziało, nie zobaczy go więcej, i już nie ujrzy go jego miejsce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 10, 'Jego synowie będą się korzyć przed ubogim, jego ręce zwrócą swe bogactwo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 11, 'Jego kości są pełne grzechów jego młodości, razem z nim spoczną w prochu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 12, 'A choć zło jest słodkie w jego ustach i zataja je pod swoim językiem;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 13, 'Chociaż rozkoszuje się nim i nie opuszcza go, zatrzymując je na swoim podniebieniu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 14, 'To jednak jego pokarm we wnętrznościach przemienia się, staje się żółcią żmii w jego wnętrzu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 15, 'Połknął bogactwa i zwróci je; Bóg je wyrzuci z jego brzucha.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 16, 'Będzie ssał jad żmii, zabije go język węża.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 17, 'Nie zobaczy rzek, potoków, strumieni miodu ani masła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 18, 'Zwróci swój zysk i nie połknie go; i choć znowu zdobędzie wielki majątek, nie ucieszy się z niego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 19, 'Bo uciskał i opuszczał ubogich, przemocą zabrał dom, którego nie zbudował.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 20, 'Dlatego nie zazna pokoju w swoim wnętrzu, nie zatrzyma tego, czego pragnął.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 21, 'Z jego pokarmów nic nie zostanie, nie rozmnożą się jego dobra.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 22, 'Mimo obfitości jego dostatku dosięgnie go bieda. Wszelka ręka nikczemnych uderzy na niego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 23, 'Gdy będzie miał czym napełnić swój brzuch, Bóg ześle na niego zapalczywość swego gniewu, wyleje na niego i na jego pokarmy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 24, 'Gdy będzie uciekał przed żelazną bronią, przebije go łuk spiżowy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 25, 'Wyjęta będzie strzała z grzbietu, a grot przeszyje jego wątrobę; ogarnie go strach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 26, 'Wszelka ciemność zaczai się w jego kryjówkach. Pożre go ogień niewzniecony, a ten, kto pozostał w jego przybytku, będzie udręczony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 27, 'Niebo odkryje jego nieprawość, a ziemia powstanie przeciwko niemu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 28, 'Dobytek jego domu przepadnie, jego dobra rozpłyną się w dniu Bożego gniewu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 29, 'Taki jest dział Boga dla niegodziwego i dziedzictwo przeznaczone mu przez Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 1, 'Wtedy Hiob odpowiedział:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 2, 'Słuchajcie uważnie moich słów, a to będzie dla mnie wasza pociecha.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 3, 'Pozwólcie mi mówić, a potem, gdy powiem, naśmiewajcie się ze mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 4, 'Czy swoją skargę kieruję do człowieka? A jeśli tak, to dlaczego mój duch nie miałby być wzburzony?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 5, 'Spójrzcie na mnie, zdumiewajcie się i połóżcie rękę na swoje usta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 6, 'Gdy tylko sobie przypomnę, jestem przerażony i strach ogarnia moje ciało.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 7, 'Czemu niegodziwi żyją, starzeją się, a nawet wzrastają w bogactwie?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 8, 'Ich potomstwo utrwala się przed nimi, a ich rodzina wzrasta na ich oczach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 9, 'Ich domy są bezpieczne, bez strachu i nie dotyka ich rózga Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 10, 'Ich byk zapładnia i nie zawodzi, ich krowa cieli się i nie roni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 11, 'Wypuszczają swe malutkie dzieci jak trzodę, a ich synowie podskakują.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 12, 'Chwytają za bęben i harfę i weselą się przy dźwięku fletu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 13, 'Spędzają swoje dni w dobrobycie, a w mgnieniu oka zstępują do grobu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 14, 'Dlatego mówią do Boga: Odejdź od nas, bo nie chcemy poznać twoich dróg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 15, 'Kim jest Wszechmocny, abyśmy mieli mu służyć? Cóż nam pomoże to, że będziemy się modlić do niego?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 16, 'Oto ich dobra nie są w ich rękach. Rada niegodziwych daleka jest ode mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 17, 'Jak często gaśnie pochodnia niegodziwych? Jak często przychodzi na nich zguba? Bóg im wydziela cierpienie w swoim gniewie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 18, 'Są jak słoma na wietrze i jak plewa, którą wicher porywa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 19, 'Bóg zachowuje jego nieprawość dla jego synów; odpłaca mu, aby to poczuł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 20, 'Jego oczy ujrzą jego nieszczęście i będzie pił z gniewu Wszechmocnego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 21, 'Jaką bowiem ma on rozkosz w swoim domu, po swojej śmierci, gdy liczba jego miesięcy zostanie skrócona?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 22, 'Czy ktoś może uczyć Boga wiedzy, wiedząc, że on sam sądzi najwyższych?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 23, 'Jeden umiera w pełni swoich sił, bezpieczny ze wszystkich stron i spokojny;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 24, 'Jego piersi są pełne mleka, a jego kości zwilża szpik.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 25, 'Drugi zaś umiera w goryczy ducha i nigdy nie jadał z uciechą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 26, 'Razem będą leżeć w prochu i okryją ich robaki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 27, 'Oto znam wasze myśli i zamiary, jakie przeciwko mnie złośliwie obmyślacie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 28, 'Mówicie bowiem: Gdzie jest dom księcia? A gdzie mieszkanie niegodziwych?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 29, 'Czy nie pytaliście podróżnych? Czy nie chcecie poznać ich znaków;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 30, 'Że niegodziwy jest zachowany na dzień zatracenia? Zostanie przyprowadzony na dzień gniewu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 31, 'Któż mu wypomni w oczy jego drogę? A kto mu odpłaci za to, co uczynił?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 32, 'Zaprowadzą go do grobu i zostanie w grobowcu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 33, 'Słodkie mu będą bryły ziemi z doliny i pociągnie za sobą wszystkich ludzi; a ci, którzy szli przed nim, są niezliczeni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 34, 'Czemu więc daremnie mnie pocieszacie, skoro w waszych odpowiedziach pozostaje fałsz?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 1, 'Wtedy Elifaz z Temanu odpowiedział:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 2, 'Czy człowiek może być użyteczny dla Boga? Mądry jest raczej użyteczny dla samego siebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 3, 'Czy Wszechmocny ma upodobanie w tym, że jesteś sprawiedliwy? Czy ma zysk z tego, że doskonalisz swoje drogi?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 4, 'Czy będzie cię karać z powodu strachu przed tobą? Czy stawia cię przed sądem?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 5, 'Czy twoja niegodziwość nie jest wielka i twoje nieprawości nie mają końca?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 6, 'Brałeś bowiem zastaw od swoich braci bez powodu i nagich z szat obdzierałeś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 7, 'Nie podałeś wody zmęczonemu, a głodnemu odmówiłeś chleba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 8, 'Ale możnemu dałeś ziemię, a poważany mieszkał w niej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 9, 'Wdowy odprawiłeś z niczym, a sierotom połamałeś ramiona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 10, 'Dlatego ogarnęły cię sidła, a trwoży cię nagły strach;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 11, 'Lub ogarnęła cię ciemność, bo nie widzisz, a wezbrane wody okryły cię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 12, 'Czy Bóg nie jest na wysokości niebios? Spójrz na najwyższe gwiazdy, jakże są wysoko!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 13, 'A ty mówisz: Cóż Bóg wie? Czy przez chmury będzie sądził?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 14, 'Obłoki są jego zasłoną, więc nie widzi, po okręgu niebios się przechadza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 15, 'Czy zwróciłeś uwagę na stare ścieżki, którymi kroczyli niegodziwcy?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 16, 'Oni zostali wykorzenieni przed czasem, powódź zalała ich fundamenty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 17, 'Mówili Bogu: Odejdź od nas. Cóż może im uczynić Wszechmogący?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 18, 'Przecież napełnił ich domy dobrem. Ale rada niegodziwych jest daleka ode mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 19, 'Widzą to sprawiedliwi i cieszą się, a niewinny naśmiewa się z nich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 20, 'Nasz dobytek bowiem nie zostaje zniszczony, lecz ich resztkę pochłonął ogień.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 21, 'Zapoznaj się z nim i zawrzyj z nim pokój, bo będzie ci się szczęściło.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 22, 'Przyjmij, proszę, prawo z jego ust i złóż jego słowa w swoim sercu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 23, 'Jeśli się nawrócisz do Wszechmocnego, zostaniesz odbudowany i oddalisz nieprawość od swego namiotu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 24, 'Wtedy zgromadzisz złota jak prochu, a złota z Ofiru jak kamienia z potoku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 25, 'Wszechmocny będzie twoim złotem, srebrem i twoją siłą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 26, 'Wtedy będziesz się rozkoszować we Wszechmocnym i podniesiesz do Boga swoje oblicze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 27, 'Będziesz się modlił do niego, a on cię wysłucha, a ty wypełnisz swoje śluby.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 28, 'Cokolwiek postanowisz, to ci się spełni, a na twoich drogach rozbłyśnie światłość.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 29, 'Gdy inni będą upokorzeni, ty powiesz: Będzie wywyższenie, bo Bóg zbawia pokornego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 30, 'Wybawi także tego, który nie jest bez winy, a zostanie wybawiony dzięki czystości twoich rąk.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 1, 'Wtedy Hiob odpowiedział:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 2, 'Również dziś moja skarga jest gorzka, choć moje nieszczęście jest cięższe niż moje jęki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 3, 'O gdybym wiedział, gdzie mógłbym go znaleźć, udałbym się aż do jego tronu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 4, 'Przedstawiłbym mu swoją sprawę, a moje usta napełniłbym dowodami;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 5, 'Poznałbym słowa jego odpowiedzi i zrozumiałbym, co chce mi powiedzieć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 6, 'Czy w swojej wielkiej mocy będzie się spierał ze mną? Nie, raczej sam doda mi siły.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 7, 'Tam człowiek prawy rozprawiałby z nim, a ja na zawsze byłbym wolny od mojego sędziego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 8, 'Ale oto idę prosto, a jego nie ma; cofam się, a nie dostrzegam go.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 9, 'Idę w lewo, gdzie on działa, a nie oglądam go; idę na prawo, a nie widzę go.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 10, 'Gdyż on zna drogę, którą kroczę; kiedy mnie doświadczy, wyjdę jak złoto.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 11, 'Moja noga trzymała się jego śladu, przestrzegałem jego drogi i nie zbaczałem z niej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 12, 'Od przykazania jego ust nie odchodziłem; ceniłem słowa jego ust bardziej niż mój własny pokarm.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 13, 'Lecz on jest niezmienny, któż go odwróci? Czego bowiem jego dusza zapragnie, to uczyni;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 14, 'Bo on wykona, co postanowił o mnie; u niego jest wiele takich przykładów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 15, 'Dlatego drżę przed jego obliczem; gdy to rozważam, lękam się go.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 16, 'Bóg osłabił moje serce, Wszechmocny mnie zatrwożył.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 17, 'O mało bowiem nie zginąłem od ciemności, nie zakrył mroku przed moim obliczem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 1, 'Czemu, skoro od Wszechmocnego nie są zakryte czasy, ci, którzy go znają, nie widzą jego dni?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 2, 'Niektórzy przesuwają granice, zabierają trzody i pasą je.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 3, 'Osła sierot pędzą i wołu wdowy biorą w zastaw.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 4, 'Spychają z drogi ubogich, biedni ziemi muszą się kryć razem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 5, 'Oto jak dzikie osły na pustyni wychodzą oni do swojej pracy, wstając rano na łup. Pustynia wydaje chleb dla nich oraz ich dzieci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 6, 'Na polu żną zboże i zbierają grona w winnicy niegodziwych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 7, 'Nagich zmuszają nocować bez ubrania, tak że nie mają czym się nakryć w czasie chłodów;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 8, 'Przemoczeni ulewą górską, bez schronienia przytulają się do skały.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 9, 'Odrywają od piersi sieroty, od ubogiego biorą zastaw.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 10, 'Nagiego zmuszają do chodzenia bez ubrania, a głodnym zabierają snopy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 11, 'A ci, którzy pośród ich murów wyciskają oliwę i tłoczą w prasach, są spragnieni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 12, 'Ludzie w mieście wzdychają, dusze śmiertelnie rannych wołają, a Bóg im w tym nie przeszkadza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 13, 'To są ci, którzy się sprzeciwiają światłości, nie znają jej dróg ani nie trwają na jej ścieżkach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 14, 'Morderca wstaje przed świtem i zabija ubogiego i potrzebującego, a w nocy jest jak złodziej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 15, 'Oko cudzołożnika czeka na zmierzch, mówiąc: Nikt mnie nie zobaczy, i zakrywa on swoje oblicze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 16, 'W ciemności podkopują domy, które sobie za dnia oznaczyli, nie znają światła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 17, 'Dla nich bowiem poranek jest jak cień śmierci. Jeśli ktoś ich rozpozna, ogarnia ich strach cienia śmierci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 18, 'Lekko unoszą się na wodach, przeklęty jest ich dział na ziemi, nie patrzą na drogę do winnic.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 19, 'Jak susza i upał trawią wody śniegu, tak grób trawi grzeszników.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 20, 'Zapomni o nim łono jego matki, a robak będzie się nim karmić jak słodycz; nikt go więcej nie wspomni, a nieprawość zostanie połamana jak drzewo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 21, 'Dręczy niepłodną, która nie rodziła, a wdowie nie czyni dobra.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 22, 'Pociąga też mocarzy swoją siłą; gdy powstaje, nikt nie jest pewien swego życia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 23, 'Dano mu, że może oprzeć się bezpiecznie; jego oczy jednak patrzą na ich drogi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 24, 'Na chwilę zostali wywyższeni, ale już ich nie ma; zostali poniżeni i ściśnieni jak wszyscy inni, a jak wierzch kłosa zostaną wycięci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 25, 'A jeśli tak nie jest, kto mi udowodni kłamstwo i obróci wniwecz moje słowa?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 1, 'Wtedy Bildad z Szuach odpowiedział:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 2, 'Przy nim jest panowanie i strach, on czyni pokój na swoich wysokościach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 3, 'Czy można zliczyć jego wojska? A nad kim nie wschodzi jego światło?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 4, 'Jak więc może człowiek być usprawiedliwiony przed Bogiem? Albo jak może być czysty ten, kto się urodził z kobiety?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 5, 'Oto nawet księżyc nie świeci i gwiazdy nie są czyste w jego oczach;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 6, 'Tym bardziej człowiek, który jest robakiem, i syn człowieczy, który jest czerwiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 1, 'A Hiob tak odpowiedział:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 2, 'Jakże uratowałeś tego, który nie ma mocy? Jakże wybawiłeś ramię, które nie ma siły?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 3, 'Jakże doradziłeś temu, który nie ma mądrości? Jakże dokładnie nauczyłeś tej sprawy?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 4, 'Komu powiedziałeś te słowa? Czyj to duch wyszedł od ciebie?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 5, 'Rzeczy martwe rodzą się pod wodami oraz ich mieszkańcy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 6, 'Piekło jest odkryte przed nim i zatracenie nie ma przykrycia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 7, 'Rozciągnął północ nad pustym miejscem i ziemię zawiesił na niczym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 8, 'Zawiązuje wody w swoich obłokach, a obłok nie pęka pod nimi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 9, 'Zatrzymuje widok swego tronu, rozciąga nad nim swój obłok.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 10, 'Wodom nakreślił granice, aż nastąpi koniec światłości i ciemności.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 11, 'Filary niebios trzęsą się i zdumiewają się jego gromem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 12, 'Swoją mocą dzieli morze, a swoją roztropnością uśmierza jego nawałnicę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 13, 'Swoim duchem przyozdobił niebiosa, a jego ręka stworzyła pokrzywionego węża.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 14, 'Oto tylko cząstka jego dróg, ale jakże mało o nim słyszymy! A kto pojmie grzmot jego wielkiej potęgi?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 1, 'Hiob ciągnął dalej swoją odpowiedź:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 2, 'Jak żyje Bóg, który odrzucił mój sąd, i Wszechmocny, który rozgoryczył moją duszę;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 3, 'Dopóki jest we mnie tchnienie i duch Boży w moich nozdrzach;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 4, 'Moje wargi nie będą mówiły niegodziwości, a mój język nie wypowie fałszu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 5, 'Nie daj Boże, abym miał was usprawiedliwiać; do śmierci nie odstąpię od swej niewinności.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 6, 'Będę trzymał się swojej sprawiedliwości i nie puszczę jej; moje serce nie oskarży mnie, póki żyję.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 7, 'Niech mój wróg będzie jak niegodziwiec, a ten, który powstaje przeciwko mnie, jak niesprawiedliwy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 8, 'Jaka bowiem jest nadzieja obłudnika, choćby zysk osiągnął, gdy Bóg zabiera mu duszę?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 9, 'Czy Bóg usłyszy jego wołanie, gdy spadnie na niego nieszczęście?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 10, 'Czy będzie się rozkoszować Wszechmocnym? Czy będzie wciąż wzywał Boga?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 11, 'Pouczę was, będąc w ręce Boga, nie zataję niczego o Wszechmocnym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 12, 'Oto wy wszyscy to widzicie; po co więc te próżne słowa?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 13, 'Taki jest dział niegodziwca u Boga i takie dziedzictwo, które otrzymają od Wszechmocnego ciemięzcy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 14, 'Jeśli rozmnożą się jego synowie, pójdą pod miecz; a jego potomstwo nie nasyci się chlebem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 15, 'Ci, którzy po nim pozostaną, będą pogrzebani w śmierci, a jego wdowy nie będą go opłakiwały;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 16, 'Choćby nagromadził srebra jak prochu i przygotował sobie szat jak gliny;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 17, 'To choć je przygotuje, włoży je sprawiedliwy, a niewinny będzie dzielić srebro.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 18, 'Zbuduje swój dom jak mól, jak szałas, który stawia stróż.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 19, 'Bogaty zaśnie, a nie będzie pogrzebany; otworzy oczy, ale już go nie ma.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 20, 'Ogarnie go strach jak wody, w nocy porwie go wicher.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 21, 'Uniesie go wiatr wschodni, a odejdzie; bo wicher wyrwie go z jego miejsca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 22, 'To bowiem Bóg rzuci na niego i nie oszczędzi go, choć bardzo chciał uciekać przed jego ręką.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 23, 'Będą klaskać nad nim w dłonie i wygwizdywać go z jego miejsca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 1, 'Doprawdy, istnieją złoża, z których pochodzi srebro, i miejsca, gdzie złoto się oczyszcza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 2, 'Żelazo się wydobywa z ziemi, a miedź wytapia z kamienia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 3, 'Kładzie się kres ciemności i przeszukuje się wszystko dokładnie, kamienie leżące w ciemności i cieniu śmierci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 4, 'Rzeka wyleje ze swego miejsca, tak że nie sposób ją przejść, zostaje jednak zahamowana przemysłem człowieka i odchodzi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 5, 'Z ziemi pochodzi chleb, lecz pod nią zamienia się jakby w ogień.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 6, 'Jej kamienie zawierają szafiry i piasek złoty;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 7, 'Ścieżki do nich nie zna ptak ani nie widziało jej oko sępa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 8, 'Nie kroczą po niej dzikie zwierzęta ani lew nią nie przeszedł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 9, 'Wyciąga swą rękę po krzemień, wywraca góry od korzenia;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 10, 'Ze skał wykuwa strumienie, a jego oko wypatruje każdej kosztownej rzeczy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 11, 'Nie pozwala rozlewać się rzekom, a ukryte rzeczy wywodzi na światło.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 12, 'Ale gdzie można znaleźć mądrość? Gdzie znajduje się miejsce rozumu?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 13, 'Człowiek nie zna jej ceny ani nie można jej znaleźć w ziemi żyjących.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 14, 'Głębia mówi: Nie ma jej we mnie. Morze powiada: U mnie też jej nie ma.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 15, 'Nie nabywa się jej za szczere złoto ani nie odważa się zapłaty za nią w srebrze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 16, 'Nie można jej wycenić w złocie z Ofiru ani w onyksie drogocennym, ani w szafirze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 17, 'Złoto i kryształ nie dorównają jej, nie można jej wymienić na klejnoty z czystego złota.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 18, 'Nie wypada wspominać o koralach i perłach, bo nabycie mądrości przewyższa perły.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 19, 'Nie dorówna jej topaz z Etiopii i nie można jej wycenić w szczerym złocie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 20, 'Skąd więc mądrość pochodzi? I gdzie znajduje się miejsce rozumu?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 21, 'Przecież jest zakryta dla oczu wszystkich żyjących i utajona przed ptactwem niebieskim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 22, 'Zniszczenie i śmierć mówią: Własnymi uszami usłyszałyśmy o jej sławie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 23, 'Bóg rozumie jej drogę, on zna jej miejsce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 24, 'On bowiem patrzy na krańce ziemi i widzi wszystko, co jest pod niebem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 25, 'Określił wagę wiatrom i odważył miarą wody.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 26, 'Gdy ustanowił prawo dla deszczu i drogę dla błyskawicy gromu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 27, 'Wtedy ją widział i ogłosił; przygotował ją i przebadał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 28, 'A do człowieka powiedział: Oto bojaźń Pana, ona jest mądrością, a odstąpienie od zła jest rozumem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 1, 'Hiob ciągnął swoją przypowieść i mówił:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 2, 'Obym był taki jak za dawnych miesięcy, za tych dni, w których Bóg mnie strzegł;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 3, 'Gdy jego pochodnia świeciła nad moją głową, a przy jego świetle przechodziłem w ciemności;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 4, 'Taki, jaki byłem za dni swojej młodości, gdy tajemnica Boga pozostawała nad moim namiotem;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 5, 'Gdy Wszechmocny był jeszcze ze mną i otaczały mnie moje dzieci;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 6, 'Gdy moje ścieżki opływały w masło, a opoka wylewała mi źródła oliwy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 7, 'Gdy wychodziłem do bramy przez miasto i na rynku przygotowałem sobie miejsce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 8, 'Widząc mnie, młodzi ukrywali się, a starcy podnosili się i stali.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 9, 'Książęta przestawali mówić i kładli rękę na swoich ustach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 10, 'Głos dostojników cichł, a ich język przylegał im do podniebienia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 11, 'Ucho, które mnie słyszało, błogosławiło mnie, a oko, które mnie widziało, dawało o mnie świadectwo;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 12, 'Bo wybawiałem ubogiego, gdy wołał, sierotę oraz tego, który nie miał pomocnika.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 13, 'Błogosławieństwo ginącego przychodziło do mnie, a serce wdowy radowałem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 14, 'Przyoblekłem się w sprawiedliwość i ona mnie okryła. Mój sąd był jak płaszcz i korona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 15, 'Byłem oczami dla ślepego, a nogami dla chromego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 16, 'Byłem ojcem ubogich, a sprawę, której nie znałem, badałem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 17, 'I kruszyłem szczękę niegodziwca, a z jego zębów wydzierałem łup.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 18, 'Dlatego powiedziałem: Umrę w swoim gnieździe, rozmnożę swoje dni jak piasek.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 19, 'Mój korzeń rozciągnął się przy wodach, a rosa trwała całą noc na moich gałązkach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 20, 'Moja chwała odświeżała się we mnie, a mój łuk odnowił się w mojej ręce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 21, 'Słuchali mnie i oczekiwali, przyjmowali moją radę w milczeniu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 22, 'Po moich słowach już nie mówili, moja mowa kropiła na nich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 23, 'Oczekiwali mnie jak deszczu, otwierali swe usta jak na późny deszcz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 24, 'Jeśli się śmiałem do nich, nie wierzyli, a światła mojej twarzy nie odrzucali.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 25, 'Wytyczałem im drogę, siadałem na czele i przybywałem jak król wśród wojska, jak ten, który smutnych pociesza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 1, 'Ale teraz śmieją się ze mnie młodsi ode mnie, ci, których ojców nie uznałbym za godnych, by postawić ich z psami swojej trzody.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 2, 'Na cóż by mi się przydała siła ich rąk, u których zginęła starość?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 3, 'Byli samotni z powodu niedostatku i głodu i uciekali na pustkowie ciemne, jałowe i spustoszone.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 4, 'Zrywają sobie malwę przy krzakach i korzenie jałowcowe na pokarm.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 5, 'Wygnano ich spośród ludzi, wołano za nimi jak za złodziejem;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 6, 'Tak że musieli mieszkać w rozpadlinach dolin, w jaskiniach podziemnych i skałach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 7, 'Między krzakami ryczeli, gromadzili się pod pokrzywami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 8, 'To byli synowie ludzi wzgardzonych i synowie ludzi nikczemnych, podlejsi niż proch ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 9, 'Ale teraz jestem tematem ich pieśni, stałem się tematem ich przysłowia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 10, 'Brzydzą się mną i oddalają się ode mnie, nie wstydzą się pluć mi w twarz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 11, 'A ponieważ on rozluźnił mój sznur i upokorzył mnie, oni też rzucili przede mnie wędzidło.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 12, 'Po mojej prawicy powstają młodzieńcy, odtrącają moje nogi i torują przeciwko mnie swoje drogi zguby.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 13, 'Popsuli moją ścieżkę i przyczynili się do mojej nędzy, a nie mają pomocnika.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 14, 'Napadli na mnie niczym przez szeroki wyłom i wśród spustoszenia nacierali na mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 15, 'Strach obrócił się przeciwko mnie, ściga moją duszę jak wiatr. Moje szczęście przemija jak chmura.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 16, 'A teraz rozpływa się we mnie moja dusza, ogarnęły mnie dni cierpienia;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 17, 'W nocy ból przeszywa moje kości, a moje żyły nie mają odpoczynku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 18, 'Z powodu wielkiego cierpienia zmieniła się moja szata i ściska mnie jak kołnierz mej tuniki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 19, 'Wrzucił mnie w błoto, stałem się podobny do prochu i popiołu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 20, 'Wołam do ciebie, ale nie słuchasz mnie; staję, a na mnie nie patrzysz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 21, 'Stałeś się dla mnie okrutny, sprzeciwiasz mi się swoją mocną ręką.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 22, 'Unosisz mnie na wietrze i wsadzasz mnie na niego, a rozwiewasz mój dobytek.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 23, 'Wiem bowiem, że wydasz mnie na śmierć i do domu przeznaczonego dla wszystkich żyjących.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 24, 'Do grobu jednak nie ściągnie swej ręki, choćby wołali, gdy będzie niszczyć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 25, 'Czy nie płakałem nad strapionym? Czy moja dusza nie smuciła się nad ubogim?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 26, 'Gdy oczekiwałem dobra, oto przyszło zło; a gdy spodziewałem się światła, przyszła ciemność.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 27, 'Moje wnętrze zawrzało i nie uspokoiło się; zaskoczyły mnie dni utrapienia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 28, 'Chodzę sczerniały, ale nie od słońca; powstaję i wołam w zgromadzeniu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 29, 'Stałem się bratem smoków, a towarzyszem młodych strusiów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 30, 'Moja skóra poczerniała na mnie i moje kości są spalone od gorączki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 31, 'Moja harfa zamieniła się w lament, a mój flet – w głos płaczących.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 1, 'Zawarłem przymierze ze swoimi oczami; jak mógłbym więc myśleć o pannie?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 2, 'Jaki bowiem byłby dział od Boga z góry? I jakie byłoby dziedzictwo od Wszechmocnego z wysoka?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 3, 'Czy zatracenie nie jest przygotowane dla niegodziwych i sroga pomsta dla czyniących nieprawość?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 4, 'Czyż on nie widzi moich dróg i nie liczy wszystkich moich kroków?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 5, 'Jeśli postępowałem kłamliwie, jeśli moja noga spieszyła się do oszustwa;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 6, 'To niech zważy mnie na wadze sprawiedliwej i niech Bóg pozna moją prawość.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 7, 'Jeśli moja noga zboczyła z drogi i moje serce poszło za moimi oczami, i jeśli jakaś zmaza przylgnęła do moich rąk;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 8, 'Wtedy niech ja sieję, a inny spożywa, niech moje latorośle będą wykorzenione.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 9, 'Jeśli moje serce uwiodła kobieta i jeśli czyhałem pod drzwiami swego bliźniego;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 10, 'To niech moja żona mieli innemu i niech inni się nad nią schylają.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 11, 'Jest to bowiem haniebny czyn, karygodna nieprawość;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 12, 'To jest ogień, który pożera aż do zatracenia i może wykorzenić cały mój dobytek.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 13, 'Jeśli zlekceważyłem sprawę swojego sługi albo swojej służącej, gdy wiedli spór ze mną;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 14, 'Co zrobię, gdy Bóg powstanie? Gdy mnie nawiedzi, co mu odpowiem?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 15, 'Czy ten, który mnie stworzył w łonie, nie stworzył też jego? Czy nie on jeden ukształtował nas w łonie?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 16, 'Jeśli odmówiłem prośbie ubogich i jeśli zasmuciłem oczy wdowy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 17, 'Jeśli sam jadłem swoją kromkę i nie jadła z niej sierota;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 18, '(Od swojej młodości bowiem wychowywałem ją jak ojciec, a od łona swojej matki prowadziłem wdowę);');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 19, 'Jeśli widziałem ginącego z powodu braku ubrania albo biedaka bez okrycia;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 20, 'Jeśli jego biodra nie błogosławiły mi dlatego, że się zagrzał wełną moich owiec;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 21, 'Jeśli podniosłem rękę przeciwko sierocie, gdy widziałem w bramie swoją pomoc;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 22, 'Wtedy niech odpadnie mój bark od karku, a niech moje ramię wyjdzie ze stawu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 23, 'Bałem się bowiem klęski od Boga, a przed jego majestatem nie mógłbym się ostać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 24, 'Jeśli pokładałem w złocie swoją nadzieję, a do czystego złota mówiłem: Ty jesteś moją ufnością;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 25, 'Jeśli radowałem się ze swojego wielkiego bogactwa i tego, że moja ręka nabyła wiele;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 26, 'Jeśli patrzyłem na słońce, gdy świeciło, i na księżyc, gdy sunął wspaniale;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 27, 'A moje serce dało się uwieść potajemnie i moje usta całowały moją rękę;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 28, 'I to byłaby nieprawość karygodna, bo zaparłbym się Boga z wysoka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 29, 'Jeśli cieszyłem się z upadku tego, który mnie nienawidzi, jeśli wyniosłem się, gdy mu się źle wiodło;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 30, '(Nawet nie pozwoliłem zgrzeszyć swoim ustom, pragnąc przekleństwa na jego duszy);');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 31, 'Czy ludzie z mojego namiotu nie mówili: Obyśmy mieli z jego mięsa! Nie możemy się najeść.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 32, 'Obcy nie nocował na dworze, swoje drzwi otwierałem podróżnemu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 33, 'Jeśli ukrywałem swoje przestępstwa jak Adam i chowałem w zanadrzu swoją nieprawość;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 34, 'Czy strach przed wielką zgrają albo pogarda bliskich przeraziły mnie, abym milczał i nie wychodził za drzwi?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 35, 'Obym miał kogoś, kto by mnie wysłuchał! Oto moja prośba, aby Wszechmogący odpowiedział mi i aby mój wróg napisał księgę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 36, 'Czy nie nosiłbym jej na swoim ramieniu i nie przywiązałbym jej sobie jak koronę?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 37, 'Oznajmiłbym mu liczbę swoich kroków; zbliżyłbym się do niego jak książę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 38, 'Jeśli moja ziemia wołała przeciwko mnie, jeśli razem z nią płakały jej bruzdy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 39, 'Jeśli spożywałem z jej plonów bez zapłaty, jeśli jej właścicieli pozbawiłem życia;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 40, 'Niech rosną ciernie zamiast pszenicy i sam kąkol zamiast jęczmienia. Skończyły się słowa Hioba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 1, 'A gdy ci trzej mężczyźni przestali odpowiadać Hiobowi, ponieważ był sprawiedliwy we własnych oczach;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 2, 'Wtedy zapłonął gniewem Elihu, syn Barakeela, Buzyta, z rodu Ram; rozgniewał się na Hioba, gdyż usprawiedliwiał siebie bardziej niż Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 3, 'Rozpalił się także jego gniew na jego trzech przyjaciół, bo nie znaleźli żadnej odpowiedzi, a jednak potępiali Hioba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 4, 'Elihu czekał, aż Hiob skończy odpowiedź, gdyż oni byli od niego starsi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 5, 'Gdy Elihu zauważył, że w ustach trzech mężczyzn nie ma żadnej odpowiedzi, zapłonął gniewem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 6, 'I Elihu, syn Barakeela, Buzyta, odpowiedział: Ja jestem młody, a wy jesteście starzy, dlatego bałem się i nie śmiałem wyjawić wam swego zdania.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 7, 'Myślałem: Niech przemówią dni, a mnogość lat niech uczy mądrości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 8, 'Ale to duch jest w człowieku i tchnienie Wszechmogącego daje rozum.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 9, 'Wielcy nie zawsze są mądrzy, a starcy nie zawsze rozumieją sąd.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 10, 'Dlatego mówię: Posłuchajcie mnie, ja też wypowiem swoje zdanie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 11, 'Oto czekałem na wasze słowa, przysłuchiwałem się waszym dowodom, gdy przygotowywaliście mowę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 12, 'I przypatrywałem się wam, a oto żaden z was nie przekonał Hioba i nikt nie odpowiedział na jego słowa;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 13, 'I nie możecie powiedzieć: Znaleźliśmy mądrość. Sam Bóg go strąca, nie człowiek.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 14, 'Nie do mnie skierował swoje słowa, a ja nie odpowiem mu waszymi słowami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 15, 'Zaniepokoili się i już nie odpowiadali; przestali mówić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 16, 'Czekałem, lecz nie mówili, ale stanęli i już nic nie powiedzieli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 17, 'Odpowiem ze swojej strony, wypowiem też swoje zdanie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 18, 'Jestem bowiem pełny słów, mój duch przymusza mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 19, 'Oto moje wnętrze jest jak wino, które nie ma ujścia; jak nowe bukłaki zagrożone pęknięciem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 20, 'Będę więc mówić, aby ulżyć sobie; otworzę swoje wargi i odpowiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 21, 'Nie będę miał względu na nikogo i nikomu nie będę schlebiał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 22, 'Nie umiem bowiem schlebiać, gdyż mój Stwórca wnet by mnie porwał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 1, 'Teraz więc, Hiobie, posłuchaj, proszę, mojej mowy i nadstaw uszu na wszystkie moje słowa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 2, 'Oto teraz otworzyłem swoje usta, a mój język będzie mówił pod podniebieniem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 3, 'Moje słowa pochodzą ze szczerości mego serca, a moje wargi wyraźnie wypowiedzą wiedzę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 4, 'Duch Boży stworzył mnie, tchnienie Wszechmocnego ożywiło mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 5, 'Jeśli możesz, odpowiedz mi; przygotuj się i stań przede mną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 6, 'Oto ja, według twoich słów, odpowiem ci za Boga, chociaż też jestem z błota ulepiony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 7, 'Oto mój strach nie zatrwoży cię, a moja ręka nie zaciąży na tobie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 8, 'Ty jednak powiedziałeś mi do uszu, słyszałem dźwięk twoich słów:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 9, 'Jestem czysty, bez przestępstwa, jestem niewinny i nie ma we mnie nieprawości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 10, 'Oto on znajduje zarzuty przeciwko mnie i uważa mnie za swego wroga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 11, 'Zakuł moje nogi w dyby, a zważa na wszystkie moje ścieżki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 12, 'Otóż w tym nie jesteś sprawiedliwy. Powiem ci, że Bóg jest większy od człowieka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 13, 'Dlaczego z nim się spierasz? Przecież on nie tłumaczy się z żadnych swoich spraw.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 14, 'Bóg bowiem mówi raz i drugi, ale człowiek tego nie dostrzega.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 15, 'We śnie, w nocnym widzeniu, gdy twardy sen spada na ludzi, w czasie drzemki na łóżku;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 16, 'Wtedy otwiera ucho ludzkie i pieczętuje ich pouczenie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 17, 'Aby odwieść człowieka od złego czynu i zabrać od niego pychę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 18, 'Powstrzymuje jego duszę od dołu, a jego życie chroni przed śmiercią od miecza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 19, 'Każe go też cierpieniem na jego łożu i bólem we wszystkich jego kościach;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 20, 'Tak że jego życiu obrzydza chleb, a jego duszy przysmaki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 21, 'Jego ciało niszczeje nie do poznania, a wystają jego kości, które nie były widoczne.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 22, 'Jego dusza zbliża się do grobu, a jego życie do niosących śmierć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 23, 'Jeśli będzie przy nim jakiś anioł, pośrednik, jeden z tysiąca, aby oznajmić człowiekowi jego powinność;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 24, 'Wtedy zlituje się nad nim i powie: Wybaw go od zejścia do dołu, bo znalazłem okup.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 25, 'I jego ciało odzyska dziecięcą świeżość, wróci do dni swojej młodości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 26, 'Będzie się modlił do Boga i on przyjmie go łaskawie, ujrzy jego oblicze z radością i przywróci człowiekowi jego sprawiedliwość;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 27, 'Spojrzy na ludzi i jeśli ktoś powie: Zgrzeszyłem, wypaczyłem to, co prawe, i to nie było dla mnie korzystne;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 28, 'On wybawi jego duszę od zejścia do dołu, a jego życie ujrzy światło.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 29, 'Wszystko to czyni Bóg z człowiekiem kilkakrotnie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 30, 'Aby odwrócić jego duszę od dołu i aby był oświecony światłem żyjących.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 31, 'Zważ na to, Hiobie, słuchaj mnie; milcz, a ja będę mówił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 32, 'Jeśli jednak masz coś do powiedzenia, odpowiedz mi; mów, bo chciałbym cię usprawiedliwić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 33, 'A jeśli nie, słuchaj mnie; milcz, a nauczę cię mądrości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 1, 'Elihu mówił dalej:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 2, 'Słuchajcie, mądrzy, moich słów i wy, uczeni, posłuchajcie mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 3, 'Ucho bowiem bada słowa, jak podniebienie smakuje pokarm.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 4, 'Wybierzmy sobie sąd, rozeznajmy między sobą, co jest dobre.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 5, 'Hiob bowiem powiedział: Jestem sprawiedliwy, a Bóg odrzucił moją sprawę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 6, 'Czy mam kłamać wbrew swojej racji? Nieuleczalna jest moja rana, bez przestępstwa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 7, 'Czy jest człowiek podobny do Hioba, który pije obelgi jak wodę?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 8, 'I który obraca się w towarzystwie czyniących nieprawość i chodzi z niegodziwcami?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 9, 'Powiedział bowiem: Nic to nie pomoże człowiekowi, że ma upodobanie w Bogu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 10, 'Dlatego posłuchajcie mnie, ludzie rozumni: Daleki jest Bóg od niegodziwości, Wszechmocny – od nieprawości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 11, 'Bo odpłaci człowiekowi według jego czynu i wynagrodzi każdemu według jego drogi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 12, 'Nie, naprawdę Bóg nie czyni przewrotnie, Wszechmocny nie wypacza sądu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 13, 'Któż mu powierzył ziemię? Kto urządził cały okrąg świata?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 14, 'Gdyby zwrócił ku człowiekowi swoje serce, gdyby wziął do siebie jego ducha i tchnienie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 15, 'To zginęłoby wszelkie ciało razem, a człowiek w proch by się obrócił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 16, 'Jeśli więc masz rozum, posłuchaj tego i nadstaw uszu na moje słowa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 17, 'Czy ma panować ten, który nienawidzi prawości? Czy potępisz tego, który jest bardzo sprawiedliwy?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 18, 'Czy wypada do króla mówić: Nikczemniku? A do książąt: Bezbożni?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 19, 'Tym bardziej do tego, który nie ma względu na książąt i nie stawia bogacza nad ubogim? Oni wszyscy bowiem są dziełem jego rąk.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 20, 'Umrą nagle, o północy lud będzie wzruszony i przeminie, a mocarz zostanie usunięty bez udziału ręki ludzkiej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 21, 'Jego oczy bowiem patrzą na drogi człowieka i on widzi wszystkie jego kroki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 22, 'Nie ma ciemności ani cienia śmierci, gdzie mogliby się ukryć ci, którzy czynią nieprawość.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 23, 'Na człowieka bowiem nie wkłada więcej niż to, co słuszne, aby stawił się na sąd przed Bogiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 24, 'Rozbije wielu mocarzy i innych osadzi w ich miejsce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 25, 'A ponieważ zna ich czyny, wywraca ich w nocy, aby byli zmiażdżeni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 26, 'Chłoszcze ich jako niegodziwych w miejscu widocznym;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 27, 'Za to, że odstąpili od niego i nie zważali na żadne jego drogi;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 28, 'Z tego powodu dochodzi do niego wołanie biednych, a on wysłuchuje wołania ubogich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 29, 'Gdy zaprowadzi pokój, któż go zburzy? A gdy zakryje swoje oblicze, któż go ujrzy? A czyni tak zarówno narodowi, jak i człowiekowi;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 30, 'Aby obłudnik już nie panował i nie był pułapką dla ludzi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 31, 'Doprawdy, powinieneś mówić do Boga: Poniosłem karę, a nie będę już grzeszyć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 32, 'Naucz mnie tego, czego nie widzę; jeśli popełniłem nieprawość, już więcej tego nie uczynię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 33, 'Czy wszystko ma być po twojej myśli? On odpłaci, czy odrzucisz, czy wybierzesz, a nie ja. Ale jeśli wiesz lepiej, to powiedz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 34, 'Niech mi powiedzą ludzie rozumni, niech człowiek mądry posłucha mnie:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 35, 'Hiob mówi niemądrze, a jego słowa nie są roztropne.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 36, 'Niech Hiob zostanie doświadczony do końca za swoje odpowiedzi odnośnie do niegodziwych ludzi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 37, 'Dodaje bowiem buntu do swego grzechu, klaszcze przy nas rękoma i mnoży swoje słowa przeciwko Bogu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 1, 'Elihu mówił dalej:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 2, 'Czy uważasz to za słuszne, że powiedziałeś: Mam więcej sprawiedliwości niż Bóg?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 3, 'Powiedziałeś bowiem: Cóż mi pomoże? Jaki będę miał pożytek z tego, że zostanę oczyszczony z grzechu?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 4, 'Odpowiem dowodnie tobie i twoim towarzyszom wraz z tobą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 5, 'Spójrz w niebo i zobacz, przypatrz się obłokom, które są wyżej od ciebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 6, 'Jeśli zgrzeszysz, co zrobisz przeciwko niemu? A jeśli pomnożą się twoje nieprawości, co mu uczynisz?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 7, 'Jeśli jesteś sprawiedliwy, co mu dajesz? Albo co otrzymuje z twojej ręki?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 8, 'Twoja niegodziwość zaszkodzi człowiekowi takiemu jak ty, a twoja sprawiedliwość pomoże synowi człowieka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 9, 'Ludzie krzyczą z powodu mnóstwa ucisków, wołają z powodu ramienia mocarzy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 10, 'Ale nikt nie mówi: Gdzie jest Bóg, mój Stwórca, który w nocy daje pieśni;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 11, 'Ten, który uczy nas więcej niż zwierzęta ziemskie i czyni nas mądrzejszymi od ptactwa niebieskiego?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 12, 'Tak więc wołają, ale nikt nie wysłuchuje z powodu pychy złych ludzi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 13, 'Doprawdy, Bóg nie wysłucha słów obłudy, Wszechmocny na nią nie zważa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 14, 'Chociaż mówisz, że go nie widzisz, sąd jest przed nim, więc mu zaufaj.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 15, 'Teraz jednak jego gniew spadł na ciebie w niewielkim stopniu, jakby nie znał wielkości twoich grzechów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 16, 'Dlatego Hiob na próżno otwiera swe usta; mnoży słowa bez poznania.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 1, 'Elihu mówił jeszcze:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 2, 'Poczekaj trochę, a pouczę cię, bo jeszcze przemówię za Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 3, 'Z daleka przyniosę swą wiedzę i uznam sprawiedliwość mego Stwórcy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 4, 'Bo naprawdę moje słowa nie są kłamstwem, a człowiek z doskonałą wiedzą stoi przed tobą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 5, 'Oto Bóg jest potężny, a nie gardzi nikim. On jest potężny w sile serca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 6, 'Nie pozostawia niegodziwych przy życiu, a ubogim przyznaje prawa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 7, 'Nie odwraca swoich oczu od sprawiedliwego, ale sadza ich na wieki z królami na tronie – i są wywyższeni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 8, 'A jeśli są związani okowami albo spętani powrozami utrapienia;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 9, 'Wtedy oznajmia im ich czyny i przestępstwa – to, że się wzmogły.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 10, 'Otwiera im ucho, aby przyjęli karę, i każe im odwrócić się od nieprawości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 11, 'Jeśli będą posłuszni i będą mu służyć, dopełnią swoich dni w dobrobycie, a swoich lat w rozkoszach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 12, 'Ale jeśli nie usłuchają, zginą od miecza, umrą bez poznania.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 13, 'Lecz ludzie obłudnego serca gromadzą gniew, nie wołają, kiedy ich wiąże.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 14, 'Umierają w młodości, swoje życie spędzają wśród rozpustników.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 15, 'Wyrywa ubogiego z utrapienia i otwiera ich uszy w ucisku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 16, 'Również ciebie wyrwałby z ciasnego miejsca na miejsce przestronne, gdzie nie ma ucisku, a zastawiłby twój stół pełnią tłuszczu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 17, 'Ale ty zasłużyłeś na sąd niegodziwego, dlatego prawo i sąd będą cię trzymać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 18, 'Gniew wisi, więc uważaj, by nie poraził cię karą, gdyż nie wybawił cię żaden okup.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 19, 'Czy będzie zważał na twoje bogactwa? Nie, ani na złoto, ani na jakiekolwiek siły lub potęgi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 20, 'Nie tęsknij za nocą, kiedy ludzie są porwani ze swojego miejsca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 21, 'Strzeż się, abyś nie zważał na nieprawość; gdyż wybrałeś to sobie zamiast utrapienia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 22, 'Oto Bóg jest najwyższy w swojej potędze, któż może tak nauczyć jak on?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 23, 'Kto mu wytyczył jego drogę? Albo kto mu powie: Popełniłeś nieprawość?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 24, 'Pamiętaj, abyś wysławiał jego dzieło, któremu przypatrują się ludzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 25, 'Wszyscy ludzie je widzą, człowiek przypatruje się nim z daleka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 26, 'Oto Bóg jest wielki, a poznać go nie możemy, a liczba jego lat jest niezbadana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 27, 'On wyciąga bowiem krople wód, które padają z pary jako deszcz;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 28, 'Który spuszczają chmury i który obficie spływa na ludzi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 29, '(A kto zrozumie rozmieszczenie chmur i grzmot jego namiotu?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 30, 'Oto rozciąga nad nim swoją światłość i okrywa głębiny morskie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 31, 'Przez te rzeczy bowiem sądzi narody i daje pokarm w obfitości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 32, 'Chmurami okrywa światłość i rozkazuje jej ukrywać się za wyznaczoną chmurą).');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 33, 'Grzmot daje o nim znać, a także bydło – o parze unoszącej się w górę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 1, 'I drży z tego powodu moje serce, i wyrywa się ze swego miejsca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 2, 'Słuchajcie uważnie grzmotu jego głosu i dźwięku, który wychodzi z jego ust.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 3, 'Pod całym niebem go wypuszcza, a jego błyskawicę – na krańce ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 4, 'Po niej huczy grzmot, grzmi głosem swojego majestatu, i nie powstrzymuje ich, gdy słychać jego głos.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 5, 'Bóg cudownie grzmi swoim głosem, czyni wielkie rzeczy, których nie możemy zrozumieć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 6, 'Mówi bowiem do śniegu: Padaj na ziemię, a także do deszczu i do ulewy jego potęgi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 7, 'Pieczętuje rękę każdego człowieka, aby wszyscy ludzie poznali jego dzieło.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 8, 'Wtedy zwierzęta wchodzą do jaskini i zostają w swoich jamach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 9, 'Od południa przychodzi wicher, a zima od wiatrów północnych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 10, 'Swoim tchnieniem Bóg czyni lód i ścinają się szerokie wody.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 11, 'Także wilgocią ziemi obciąża obłok, rozpędza chmurę swoim światłem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 12, 'One krążą według jego rady, aby czyniły wszystko, co rozkazuje na powierzchni okręgu ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 13, 'A on sprawia, że się pojawiają – czy to dla karania, czy dla swojej ziemi, czy dla okazywania miłosierdzia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 14, 'Słuchaj tego uważnie, Hiobie; zastanów się i rozważ cudowne dzieła Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 15, 'Czy wiesz, kiedy i co postanawia Bóg o tych sprawach albo kiedy rozjaśnia światło swej chmury?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 16, 'Czy wiesz, jak wiszą chmury – cuda tego, który jest doskonały we wszelkiej wiedzy?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 17, 'Czy wiesz, jak twoje szaty się rozgrzewają, gdy on uspokaja ziemię wiatrem południowym?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 18, 'Czy rozpościerałeś z nim niebiosa, które są trwałe i podobne do zwierciadła odlanego?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 19, 'Poucz nas, co mamy mu powiedzieć, bo nie możemy ułożyć słów z powodu ciemności.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 20, 'Czy należy go powiadomić, że przemawiam? Przecież jeśli ktoś przemówi, zostanie na pewno pożarty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 21, 'Teraz jednak ludzie nie mogą patrzyć na światło, gdy jaśnieje w chmurach, gdy wiatr przechodzi i rozprasza je.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 22, 'Od północy przychodzi jakby złoty blask, ale w Bogu jest straszliwy majestat.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 23, 'On jest Wszechmocny, nie możemy go doścignąć. On jest wielki w potędze i sądzie i bogaty w sprawiedliwość. Nie uciska nikogo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 24, 'Dlatego boją się go ludzie. On nie ma względu na żadnego, który jest mądry w sercu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 1, 'Potem Pan odpowiedział Hiobowi spośród wichru:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 2, 'Kim jest ten, co zaciemnia radę słowami bez poznania?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 3, 'Przepasz teraz swe biodra jak mężczyzna, będę cię pytał, a ty mi odpowiadaj.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 4, 'Gdzie byłeś, kiedy zakładałem fundamenty ziemi? Powiedz, jeśli masz tę wiedzę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 5, 'Kto określił jej rozmiary? Czy wiesz? Kto rozciągnął nad nią sznur?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 6, 'Na czym są oparte jej podstawy? Kto położył jej kamień węgielny;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 7, 'Gdy gwiazdy poranne razem śpiewały i radowali się wszyscy synowie Boży?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 8, 'Kto zamknął bramą morze, gdy się wyrywało jakby wychodzące z łona?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 9, 'Gdy chmurę uczyniłem jego szatą, a ciemność jego pieluszkami;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 10, 'Gdy ustanowiłem o nim swój dekret i poustawiałem rygle i bramy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 11, 'I powiedziałem: Dotąd dojdziesz, a nie dalej; tu położysz swe nadęte fale.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 12, 'Czy kiedykolwiek w swoim życiu rozkazywałeś rankowi i wskazałeś zorzy jej miejsce;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 13, 'Aby ogarnęła krańce ziemi i aby niegodziwi zostali z niej strząśnięci?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 14, 'Ona zmienia się jak glina pod pieczęcią, a wszystko stoi jak szata.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 15, 'Niegodziwym jest odebrana ich światłość, a wyniosłe ramię będzie złamane.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 16, 'Czy dotarłeś aż do źródeł morza? Czy przechadzałeś się po dnie głębin?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 17, 'Czy bramy śmierci zostały przed tobą odkryte? Czy widziałeś bramy cienia śmierci?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 18, 'Czy pojąłeś szerokość ziemi? Powiedz mi, jeśli to wszystko wiesz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 19, 'Gdzie jest droga do miejsca przebywania światłości? Gdzie swoje miejsce ma ciemność;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 20, 'Abyś ją zaprowadził do jej granic i mógł poznać ścieżki do jej domu?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 21, 'Czy wiesz to, bo wtedy się urodziłeś i liczba twoich dni jest wielka?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 22, 'Czy dotarłeś do skarbnic śniegu? Czy widziałeś skarbnice gradu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 23, 'Który zachowuję na czas ucisku, na dzień bitwy i wojny?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 24, 'Jaką drogą dzieli się światłość, która rozpędza wiatr wschodni po ziemi?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 25, 'Kto podzielił kanał dla ulewy i drogę dla błyskawicy grzmotu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 26, 'Aby padał deszcz na ziemię, w której nikt nie mieszka, i na pustynię, gdzie nie ma człowieka;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 27, 'Aby nasycił miejsce puste i jałowe oraz zasilił rosnącą tam trawę?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 28, 'Czy deszcz ma ojca? A kto spłodził krople rosy?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 29, 'Z czyjego łona wychodzi lód? A kto spłodził szron niebieski?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 30, 'Wody zostają przykryte niczym kamieniem, gdy powierzchnia głębiny zamarza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 31, 'Czy możesz związać jasne gwiazdy Plejad albo rozluźnić więzy Oriona?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 32, 'Czy wyprowadzisz w swym czasie gwiazdy południowe? Czy poprowadzisz Niedźwiedzicę z jej synami?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 33, 'Czy znasz porządek nieba? Czy możesz ustanowić jego panowanie na ziemi?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 34, 'Czy podniesiesz swój głos ku chmurom, aby cię ulewa przykryła?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 35, 'Czy możesz wypuścić błyskawice, aby przyszły i mówiły: Oto jesteśmy?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 36, 'Kto włożył we wnętrze ludzkie mądrość? Kto dał sercu rozum?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 37, 'Kto zdoła policzyć chmury swoją mądrością? Kto uspokoi, kiedy leje z nieba;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 38, 'Gdy proch twardnieje, a bryły przylegają do siebie?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 39, 'Czy lwu zdobyczy nałowisz, czy zaspokoisz głód lwiątek;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 40, 'Gdy tulą się w swoich jaskiniach i czyhają w cieniu swoich jam?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 41, 'Kto dostarcza krukowi pokarmu, gdy jego młode wołają do Boga i tułają się bez pożywienia?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 1, 'Czy znasz porę, kiedy rodzą górskie kozice? Czy wiesz, kiedy rodzą łanie?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 2, 'Czy możesz zliczyć miesiące, w których noszą młode? Czy znasz czas ich porodu?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 3, 'Przykucają, rodzą swoje młode, pozbywają się ich z bólem;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 4, 'Ich młode wzmacniają się, rosną wśród zboża, odchodzą i już do nich nie wracają.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 5, 'Kto wypuścił dzikiego osła na wolność i kto rozwiązał jego pęta?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 6, 'Za dom dałem mu pustynię, a za jego mieszkanie słone miejsca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 7, 'On naśmiewa się ze zgiełku miejskiego i nie słucha głosu poganiacza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 8, 'Wypatruje w górach paszy i szuka wszelkiej zielonej trawy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 9, 'Czy jednorożec zechce ci służyć albo nocować przy twoim żłobie?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 10, 'Czy możesz powrozem zaprzęgać jednorożca do bruzdy? Czy będzie bronował doliny za tobą?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 11, 'Czy zaufasz mu, ponieważ jego siła jest wielka? Czy powierzysz mu swoją pracę?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 12, 'Czy zawierzysz mu, że zwiezie twoje ziarno i zgromadzi je w twoim spichlerzu?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 13, 'Czy dałeś pawiowi piękne skrzydła, a skrzydła i pióra strusiowi?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 14, 'Składa swoje jaja na ziemię i ogrzewa je w prochu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 15, 'I zapomina, że noga może je rozgnieść lub dzikie zwierzę może zdeptać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 16, 'Jest twardy dla swoich młodych, jakby nie były jego. Nie boi się, że jego trud jest próżny;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 17, 'Bo Bóg pozbawił go mądrości i nie udzielił mu rozumu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 18, 'Kiedy jednak podnosi się wysoko, naśmiewa się z konia i z jego jeźdźca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 19, 'Czy możesz dać koniowi moc? Czy rżeniem ozdobiłeś jego szyję?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 20, 'Czy przestraszysz go jak szarańczę? Parskanie jego nozdrzy jest straszne.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 21, 'Grzebie kopytem w ziemi i cieszy się swą siłą, biegnie przeciwko uzbrojonym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 22, 'Drwi sobie z lęku i nie boi się, i nie ustępuje przed ostrzem miecza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 23, 'Kołczan na nim chrzęści, błyszczy oszczep i dzida.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 24, 'Z grzmotem i z gniewem pochłania ziemię i nie staje spokojnie na głos trąby.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 25, 'Na głos trąby mówi: Ha, ha; z daleka czuje bitwę, grom dowódców i okrzyk.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 26, 'Czy dzięki twojemu rozumowi lata jastrząb i rozciąga swe skrzydła ku południu?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 27, 'Czy na twój rozkaz orzeł wzbija się i zakłada swoje gniazdo wysoko?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 28, 'Mieszka na skale, przebywa na iglicach jak na zamku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 29, 'Stamtąd wypatruje sobie pokarmu, jego oczy widzą daleko.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 30, 'Jego młode też piją krew, a gdzie są zabici, tam jest on.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 1, 'Pan mówił dalej do Hioba:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 2, 'Czy ten, co wiedzie spór z Wszechmogącym, będzie go pouczał? Niech na to odpowie ten, który strofuje Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 3, 'Wtedy Hiob odpowiedział Panu:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 4, 'Oto jestem nędzny, cóż ci odpowiem? Przyłożę swoją rękę do ust.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 5, 'Raz mówiłem i drugi, ale więcej nie odpowiem, niczego więcej nie dodam.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 6, 'Nadto Pan odpowiedział Hiobowi spośród wichru:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 7, 'Przepasz teraz swe biodra jak mężczyzna: będę cię pytał, a ty mnie pouczysz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 8, 'Czy chcesz wniwecz obrócić mój sąd? Czy potępisz mnie, aby usprawiedliwić samego siebie?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 9, 'Czy masz ramię jak Bóg? Czy zagrzmisz głosem jak on?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 10, 'Ozdób się teraz w majestat i dostojeństwo, przyoblecz się w chwałę i piękno.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 11, 'Rozlej swój gwałtowny gniew, spójrz na każdego pysznego i poniż go.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 12, 'Spójrz na każdego pysznego i upokórz go, zdepcz niegodziwych na ich miejscu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 13, 'Zakryj ich razem w prochu, zamknij w ukryciu ich oblicza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 14, 'Wtedy i ja ci wyznam, że twoja prawica może cię wybawić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 15, 'Oto behemot, którego stworzyłem wraz z tobą; je trawę jak wół.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 16, 'Oto jego siła jest w jego biodrach, a jego moc w pępku jego brzucha.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 17, 'Rusza swoim ogonem jak cedrem, ścięgna jego bioder są splecione.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 18, 'Jego kości jak rury spiżowe; jego kości jak drągi żelazne.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 19, 'On jest przednim dziełem Boga. Ten, który go uczynił, sam może na niego natrzeć swoim mieczem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 20, 'Żywność dostarczają mu góry, gdzie wszystkie polne zwierzęta hasają.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 21, 'Leży pod cienistymi drzewami, w ukryciu trzcin i bagien.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 22, 'Drzewa cieniste osłaniają go cieniem, wierzby potoku otaczają go.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 23, 'Oto wypija rzekę i nie spieszy się, będąc pewny, że może wchłonąć Jordan do swojej paszczy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 24, 'Czy można go złapać za oczy albo powrozy przeciągnąć mu przez nozdrza?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 1, 'Czy lewiatana wyciągniesz wędką? Czy za jego język wyciągniesz go sznurem opuszczonym?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 2, 'Czy przewleczesz hak przez jego nozdrza? Czy kolcem przebijesz mu szczęki?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 3, 'Czy będzie cię błagać? Czy będzie z tobą rozmawiał łagodnie?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 4, 'Czy zawrze z tobą przymierze? Czy przyjmiesz go za sługę na zawsze?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 5, 'Czy będziesz z nim igrał jak z ptaszkiem? Czy uwiążesz go dla swoich córek?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 6, 'Czy twoi towarzysze wyprawią sobie z niego ucztę? Czy podzielą go między siebie kupcy?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 7, 'Czy poprzebijasz jego skórę grotami albo jego głowę harpunami?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 8, 'Połóż tylko rękę na niego i wspomnij o walce, więcej tego nie zrobisz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 9, 'Oto nadzieja pojmania go jest złudna. Czy na sam jego widok nie zostanie człowiek powalony?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 10, 'Nikt nie odważy się go obudzić. Kto zdoła więc stanąć przede mną?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 11, 'Kto mi coś dał, abym mu odpłacił? Cokolwiek znajduje się pod całym niebem należy do mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 12, 'Nie będę milczał o jego członkach ani o jego potędze, ani o jego wspaniałej budowie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 13, 'Kto odkryje wierzch jego szaty? Kto przystąpi do niego z podwójnym wędzidłem?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 14, 'Kto otworzy wrota jego paszczy? Groza roztacza się wokół jego zębów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 15, 'Jego łuski to jego pycha, ściśle spięte razem jakby pieczęcią.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 16, 'Jedna do drugiej tak przylega, że powietrze nie wejdzie między nie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 17, 'Jedna z drugą jest spojona, są tak złączone, że nie można ich rozdzielić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 18, 'Przez jego kichanie błyszczy światło, a jego oczy są jak powieki zorzy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 19, 'Z jego paszczy wychodzą pochodnie, tryskają iskry ognia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 20, 'Z jego nozdrzy wychodzi dym jak z wrzącego garnca lub kotła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 21, 'Jego oddech rozpala węgle, z jego paszczy wychodzi płomień.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 22, 'W jego szyi spoczywa moc i przed nim ucieka smutek.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 23, 'Warstwy jego ciała są spojone, tak twarde, że się nie poruszają.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 24, 'Jego serce jest twarde jak kamień, tak twarde jak część dolnego kamienia młyńskiego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 25, 'Gdy się podnosi, drżą mocarze, a od strachu oczyszczają się.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 26, 'Miecz, który go dosięga, nie ostaje się, podobnie drzewce, strzała i pancerz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 27, 'Żelazo uważa za słomę, a miedź za zbutwiałe drewno.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 28, 'Strzała nie spłoszy go, a kamienie z procy są dla niego jak źdźbło.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 29, 'Oszczep uważa za słomę, a drwi sobie z szarpania włócznią.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 30, 'Pod nim są ostre skorupy; w błocie ścieli sobie wszelkimi ostrymi rzeczami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 31, 'Sprawia, że głębiny wrą jak kocioł, a morze mąci jak w moździerzu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 32, 'Zostawia za sobą błyszczącą ścieżkę, tak że się wydaje, że głębiny mają siwiznę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 33, 'Nie ma na ziemi jemu podobnego, który został tak stworzony, że niczego się nie boi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 34, 'Lekceważy wszelką wysoką rzecz. On jest królem nad wszystkimi synami pychy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 1, 'Wtedy Hiob odpowiedział Panu:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 2, 'Wiem, że ty wszystko możesz i że żaden twój zamysł nie może być powstrzymany.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 3, 'Kim jest ten, który zaciemnia radę bez wiedzy? Właśnie dlatego mówiłem to, czego nie rozumiałem; mówiłem o rzeczach zbyt cudownych, których nie mogłem pojąć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 4, 'Wysłuchaj, proszę, a będę mówił; będę cię pytał, a ty mnie pouczysz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 5, 'Dotąd tylko moje ucho słyszało o tobie, lecz teraz moje oko cię ujrzało.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 6, 'Dlatego żałuję i pokutuję w prochu i popiele.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 7, 'A gdy Pan wypowiedział te słowa do Hioba, powiedział Pan do Elifaza z Temanu: Mój gniew zapłonął przeciw tobie i przeciw dwom twoim przyjaciołom, ponieważ nie mówiliście o mnie prawdy jak mój sługa Hiob.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 8, 'Teraz więc weźcie sobie siedem cielców i siedem baranów, idźcie do mego sługi Hioba i złóżcie całopalenie za siebie; a Hiob, mój sługa, będzie się modlił za was, bo jego przyjmę, abym nie uczynił z wami według waszej głupoty. Nie mówiliście bowiem o mnie prawdy jak mój sługa Hiob.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 9, 'Poszli więc Elifaz z Temanu, Bildad z Szuach i Sofar z Naamy i uczynili, jak Pan im rozkazał. Pan także przyjął Hioba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 10, 'Pan przywrócił to, co zostało zabrane Hiobowi, gdy się modlił za swoich przyjaciół. Pan także pomnożył Hiobowi w dwójnasób wszystko, co miał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 11, 'Wtedy zeszli się do niego wszyscy jego bracia, wszystkie jego siostry i wszyscy dawni znajomi i jedli z nim chleb w jego domu. Ubolewali nad nim i pocieszali go z powodu wszystkich nieszczęść, które Pan sprowadził na niego. Każdy dał mu po jednym srebrniku i każdy po jednym złotym kolczyku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 12, 'I tak Pan błogosławił ostatnie lata Hioba bardziej niż początkowe. Miał bowiem czternaście tysięcy owiec, sześć tysięcy wielbłądów, tysiąc jarzm wołów i tysiąc oślic.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 13, 'Miał też siedmiu synów i trzy córki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 14, 'I nadał pierwszej imię Jemima, drugiej Kecja i trzeciej Kerenhappuk.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 15, 'W całej ziemi nie można było znaleźć kobiet tak pięknych jak córki Hioba. Ich ojciec dał im dziedzictwo wśród ich braci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 16, 'Potem Hiob żył jeszcze sto czterdzieści lat i oglądał swoich synów i synów swoich synów aż do czwartego pokolenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 17, 'I umarł Hiob stary i syty dni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 1, 'Błogosławiony człowiek, który nie idzie za radą niegodziwych, nie stoi na drodze grzeszników i nie zasiada w gronie szyderców;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 2, 'Lecz ma upodobanie w prawie Pana i nad jego prawem rozmyśla we dnie i w nocy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 3, 'Będzie on bowiem jak drzewo zasadzone nad strumieniami wód, które wydaje swój owoc w swoim czasie; jego liść nie zwiędnie i wszystko, co robi, powiedzie się.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 4, 'Nie tak niegodziwi; oni są jak plewa, którą wiatr rozmiata.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 5, 'Dlatego niegodziwi nie ostoją się na sądzie ani grzesznicy w zgromadzeniu sprawiedliwych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 6, 'Pan bowiem zna drogę sprawiedliwych, ale droga niegodziwych zaginie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 1, 'Dlaczego poganie się buntują, a narody knują próżne zamysły?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 2, 'Królowie ziemscy powstają, a władcy naradzają się wspólnie przeciwko Panu i jego pomazańcowi, mówiąc:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 3, 'Zerwijmy ich więzy i zrzućmy z siebie ich pęta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 4, 'Lecz ten, który mieszka w niebie, będzie się śmiał, Pan będzie z nich szydził.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 5, 'Wtedy przemówi do nich w swoim gniewie i swą zapalczywością ich zatrwoży:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 6, 'Ja ustanowiłem mojego króla na Syjonie, mojej świętej górze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 7, 'Ogłoszę dekret: Pan powiedział do mnie: Ty jesteś moim Synem, ja ciebie dziś zrodziłem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 8, 'Poproś mnie, a dam ci narody w dziedzictwo i krańce ziemi na własność.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 9, 'Potłuczesz je laską żelazną, jak naczynie gliniane je pokruszysz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 10, 'Teraz więc, królowie, zrozumcie, przyjmijcie pouczenie, sędziowie ziemi!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 11, 'Służcie Panu z bojaźnią i radujcie się z drżeniem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 12, 'Pocałujcie Syna, by się nie rozgniewał i abyście nie zginęli w drodze, gdyby jego gniew choć trochę się zapalił. Błogosławieni wszyscy, którzy mu ufają.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 1, 'Psalm Dawida, gdy uciekał przed swoim synem Absalomem. Panie, jakże się namnożyło moich nieprzyjaciół, jak wielu powstaje przeciwko mnie!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 2, 'Wielu mówi o mojej duszy: Nie ma dla niego ratunku u Boga. Sela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 3, 'Ale ty, Panie, jesteś moją tarczą, moją chwałą, tym, który podnosi moją głowę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 4, 'Swym głosem wołałem do Pana i wysłuchał mnie ze swojej świętej góry. Sela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 5, 'Położyłem się i zasnąłem, i obudziłem się, bo Pan mnie podtrzymał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 6, 'Nie przestraszę się dziesiątków tysięcy ludzi, którzy zewsząd na mnie nastają.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 7, 'Powstań, Panie! Wybaw mnie, mój Boże! Uderzyłeś bowiem w szczękę wszystkich moich wrogów i połamałeś zęby niegodziwych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 8, 'Od Pana jest zbawienie. Twoje błogosławieństwo jest nad twoim ludem. Sela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 1, 'Przewodnikowi chóru, na Neginot. Psalm Dawida. Wysłuchaj mnie, gdy cię wzywam, Boże mojej sprawiedliwości! Ty wyzwoliłeś mnie w czasie ucisku. Zmiłuj się nade mną i wysłuchaj mojej modlitwy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 2, 'Synowie ludzcy, jak długo będziecie znieważać moją chwałę? Jak długo będziecie miłować marność i szukać kłamstwa? Sela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 3, 'Wiedzcie, że Pan oddzielił dla siebie pobożnego. Pan wysłucha, gdy zawołam do niego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 4, 'Zadrżyjcie i nie grzeszcie. Rozmyślajcie w swym sercu na łożu i zamilczcie. Sela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 5, 'Składajcie ofiary sprawiedliwości i ufajcie Panu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 6, 'Wielu mówi: Któż pokaże nam dobro? Panie, wznieś nad nami światło twego oblicza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 7, 'Wlałeś w moje serce więcej radości niż w czasie, gdy obfitowały ich zboże i wino.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 8, 'W spokoju się położę i zasnę, bo ty sam, Panie, sprawiasz, że mieszkam bezpiecznie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 1, 'Przewodnikowi chóru, na Nechylot. Psalm Dawida. Nakłoń ucha ku moim słowom, Panie, zważ na moje westchnienie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 2, 'Słuchaj pilnie głosu mego wołania, mój Królu i mój Boże, bo się do ciebie modlę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 3, 'Panie, z rana usłyszysz mój głos, z rana zaniosę do ciebie modlitwę i będę czekał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 4, 'Ty bowiem nie jesteś Bogiem, który miłuje nieprawość, zły z tobą nie zamieszka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 5, 'Głupcy nie ostoją się przed twymi oczyma. Nienawidzisz wszystkich czyniących nieprawość.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 6, 'Wytracisz tych, którzy mówią kłamstwa. Pan brzydzi się człowiekiem krwawym i podstępnym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 7, 'Lecz ja dzięki obfitości twego miłosierdzia wejdę do twego domu, oddam pokłon przed twoim świętym przybytkiem w twojej bojaźni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 8, 'Prowadź mnie, Panie, w swojej sprawiedliwości ze względu na moich wrogów; wyprostuj przede mną twoją drogę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 9, 'Bo w ich ustach nie ma szczerości, ich wnętrze pełne przewrotności, ich gardło jest grobem otwartym, swoim językiem pochlebiają.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 10, 'Spustosz ich, Boże! Niech upadną przez własne zamiary. Z powodu ich licznych występków odtrąć ich, ponieważ buntują się przeciwko tobie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 11, 'Lecz niech się radują wszyscy, którzy tobie ufają; niech zawsze wykrzykują z radości, bo ty będziesz ich osłaniał. Niech rozradują się w tobie ci, którzy miłują twoje imię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 12, 'Ty bowiem, Panie, będziesz błogosławił sprawiedliwego, osłonisz go dobrocią jak tarczą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 1, 'Przewodnikowi chóru, na Neginot i Seminit. Psalm Dawida. Panie, nie karć mnie w swoim gniewie i nie karz mnie w swojej zapalczywości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 2, 'Zmiłuj się nade mną, Panie, bo jestem słaby; uzdrów mnie, Panie, bo moje kości drżą;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 3, 'I moja dusza bardzo się zatrwożyła; lecz ty, Panie, jak długo jeszcze?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 4, 'Zawróć, Panie, ocal moją duszę; wybaw mnie ze względu na twe miłosierdzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 5, 'W śmierci bowiem nie ma pamięci o tobie, a w grobie któż cię będzie wysławiać?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 6, 'Zmęczyłem się moim wzdychaniem, co noc zalewam łzami moje posłanie, moje łoże jest mokre od płaczu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 7, 'Moje oko zaćmiło się od smutku, zestarzało się z powodu wszystkich moich wrogów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 8, 'Odstąpcie ode mnie, wszyscy czyniący nieprawość, bo Pan usłyszał głos mego płaczu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 9, 'Usłyszał Pan moją prośbę, Pan przyjął moją modlitwę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 10, 'Niech się zawstydzą i bardzo zatrwożą wszyscy moi wrogowie, niech uciekną i będą pohańbieni w jednej chwili.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 1, 'Syggajon Dawida, które śpiewał Panu z powodu słów Kusza Beniaminity. Panie, mój Boże, tobie ufam, wybaw mnie od wszystkich moich prześladowców i ocal mnie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 2, 'By ktoś jak lew nie porwał mojej duszy i nie rozszarpał, gdy nie będzie nikogo, kto by ją ocalił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 3, 'Panie, mój Boże, jeśli to zrobiłem, jeśli nieprawość jest na moich rękach;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 4, 'Jeśli złem odpłaciłem temu, kto żył ze mną w pokoju, jeśli nie wyratowałem tego, który mnie dręczył bez przyczyny;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 5, 'To niech wróg prześladuje moją duszę i niech pochwyci i wdepcze w ziemię moje życie, niech moją godność w proch obróci. Sela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 6, 'Powstań, Panie, w swoim gniewie; podnieś się przeciwko wściekłości moich wrogów. Przebudź się w mojej obronie, bo ustanowiłeś sąd.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 7, 'Wtedy otoczy cię zgromadzenie narodów, a ty zasiądź na wysokości ze względu na nich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 8, 'Pan będzie sądził narody. Osądź mnie, Panie, według mojej sprawiedliwości i według mojej uczciwości, która jest we mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 9, 'Niech skończy się zło niegodziwych, a umocnij sprawiedliwego, Boże sprawiedliwy, ty, który badasz serca i nerki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 10, 'Moją tarczą jest Bóg, który wybawia ludzi prawego serca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 11, 'Bóg jest sędzią sprawiedliwym, Bóg codziennie gniewa się na bezbożnego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 12, 'Jeśli się nie nawróci, on swój miecz naostrzy; swój łuk napiął i przygotował go.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 13, 'Przygotował na niego broń śmiertelną, a swoje strzały sporządził na prześladowców.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 14, 'Oto bezbożny rodzi nieprawość, jest brzemienny krzywdą i zrodził kłamstwo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 15, 'Wykopał dół i pogłębił go, lecz sam wpadnie do jamy, którą przygotował.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 16, 'Krzywda, którą wyrządzał, obróci się przeciwko niemu, a jego nieprawość spadnie mu na głowę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 17, 'Będę wysławiał Pana według jego sprawiedliwości, będę śpiewał imieniu Pana Najwyższego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 1, 'Przewodnikowi chóru, na Gittyt. Psalm Dawida. O Panie, nasz Panie, jak sławne jest twoje imię na całej ziemi! Ty, który swoją chwałę wyniosłeś nad niebiosa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 2, 'Przez usta niemowląt i ssących ugruntowałeś swą potęgę z powodu twoich wrogów, aby poskromić nieprzyjaciela i mściciela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 3, 'Gdy przypatruję się twoim niebiosom, dziełu twoich palców, księżycowi i gwiazdom, które utwierdziłeś;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 4, 'Wtedy mówię: Czymże jest człowiek, że o nim pamiętasz, albo syn człowieczy, że troszczysz się o niego?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 5, 'Uczyniłeś go bowiem niewiele mniejszym od aniołów, chwałą i czcią go ukoronowałeś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 6, 'Dałeś mu panowanie nad dziełami twoich rąk, wszystko poddałeś pod jego stopy:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 7, 'Owce i wszelkie bydło, a także zwierzęta polne;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 8, 'Ptactwo niebieskie i ryby morskie, i wszystko, co przemierza szlaki mórz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 9, 'O Panie, nasz Panie, jak sławne jest twoje imię na całej ziemi!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 1, 'Przewodnikowi chóru, na Halmutlabben. Pieśń Dawida. Będę cię wysławiał, Panie, całym mym sercem; będę opowiadał o wszystkich twoich cudach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 2, 'Będę się cieszył i radował tobą, będę śpiewał twemu imieniu, o Najwyższy!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 3, 'Gdy cofną się moi nieprzyjaciele, upadną i znikną sprzed twego oblicza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 4, 'Ty bowiem przeprowadziłeś mój sąd i moją sprawę, zasiadłeś na tronie jako sędzia sprawiedliwy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 5, 'Skarciłeś pogan, wytraciłeś niegodziwych, wymazałeś ich imię na wieki wieków.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 6, 'O nieprzyjacielu, twoje spustoszenia skończyły się na zawsze, zburzyłeś miasta, ich pamięć przepadła razem z nimi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 7, 'Ale Pan trwa na wieki, ustawił swój tron, by sądzić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 8, 'On będzie sądził świat sprawiedliwie, osądzi narody według słuszności.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 9, 'I będzie Pan ucieczką dla uciśnionego, schronieniem w czasie niedoli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 10, 'I będą ufać tobie ci, którzy znają twoje imię, bo nie opuszczasz, Panie, tych, którzy cię szukają.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 11, 'Śpiewajcie Panu, który mieszka na Syjonie, opowiadajcie wśród narodów o jego dziełach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 12, 'Bo on dopomina się krwi i pamięta o nich, a nie zapomina wołania strapionych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 13, 'Zmiłuj się nade mną, Panie, spójrz, jak mnie uciskają ci, którzy mnie nienawidzą, ty, który podnosisz mnie z bram śmierci;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 14, 'Abym głosił wszelką twą chwałę w bramach córki Syjonu; będę się radował twoim zbawieniem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 15, 'Poganie wpadli w dół, który wykopali; w sidłach, które zastawili, uwięzła ich noga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 16, 'Pan dał się poznać, gdy odbył sąd, w dzieła swoich rąk uwikłał się niegodziwy. Higgajon. Sela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 17, 'Niegodziwi zstąpią do piekła, wszystkie narody, które zapominają Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 18, 'Bo biedak nie będzie zapomniany na zawsze, nadzieja ubogich nie zginie na wieki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 19, 'Powstań, Panie, niech nie triumfuje człowiek, niech narody zostaną osądzone przed twoim obliczem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 20, 'Panie, ześlij na nie strach, aby narody poznały, że są tylko ludźmi. Sela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 1, 'Dlaczego, Panie, stoisz z daleka? Dlaczego ukrywasz się w czasie niedoli?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 2, 'Niegodziwy w swej pysze prześladuje ubogiego, niech niegodziwi uwikłają się w zamysły, które uknuli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 3, 'Bo niegodziwy chełpi się pragnieniem swej duszy, a chciwiec błogosławi sobie i znieważa Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 4, 'Niegodziwy przez pychę, którą po sobie pokazuje, nie szuka Boga; całe jego myślenie to że nie ma Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 5, 'Jego drogi zawsze są ciężkie, twoje sądy są zbyt daleko od niego, parska na wszystkich swoich wrogów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 6, 'Mówi w swoim sercu: Nie zachwieję się, nie zaznam zła po wszystkie pokolenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 7, 'Jego usta pełne są przekleństw, zdrady i podstępu, pod jego językiem krzywda i nieprawość.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 8, 'Siedzi w zasadzkach wsi, w ukryciach zabija niewinnego, jego oczy wypatrują ubogiego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 9, 'Czyha w kryjówce jak lew w swej jaskini; czatuje, by schwytać ubogiego, porywa go i wciąga w swe sieci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 10, 'Schyla się, zniża się, od jego mocy padają ubodzy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 11, 'Mówi w swym sercu: Bóg zapomniał, zakrył swoje oblicze, nigdy nie zobaczy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 12, 'Powstań, Panie Boże, podnieś swą rękę; nie zapominaj o ubogich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 13, 'Dlaczego niegodziwy znieważa Boga? Mówi w swym sercu: Nie będziesz się upominał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 14, 'Lecz ty widzisz utrapienie i patrzysz na krzywdę, aby za nie odpłacić twą ręką. Na ciebie się zdaje ubogi, ty jesteś pomocnikiem sierocie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 15, 'Złam ramię niegodziwego i złego, dochodź jego nieprawości, aż jej już nie będzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 16, 'Pan jest Królem na wieki wieków, z jego ziemi zniknęły narody.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 17, 'Usłyszałeś pragnienia pokornych, Panie, utwierdzisz ich serca, nakłonisz swego ucha;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 18, 'Aby bronić sieroty i udręczonego, aby śmiertelny człowiek nie gnębił już na ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 1, 'Przewodnikowi chóru. Psalm Dawida. W Panu pokładam ufność. Jakże więc możecie mówić mojej duszy: Odleć jak ptak na twoją górę?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 2, 'Bo oto niegodziwi napinają łuk, kładą strzałę na cięciwę, aby w ciemności strzelać do tych, którzy są prawego serca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 3, 'Gdy zostaną zburzone fundamenty, cóż może zrobić sprawiedliwy?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 4, 'Pan jest w swym świętym przybytku, tron Pana jest w niebie, jego oczy patrzą, jego powieki badają synów ludzkich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 5, 'Pan doświadcza sprawiedliwego, ale jego dusza nienawidzi niegodziwego i tego, kto kocha bezprawie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 6, 'Spuści na niegodziwych deszcz sideł, ognia i siarki, a palący wicher będzie udziałem ich kielicha.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 7, 'Bo sprawiedliwy Pan kocha sprawiedliwość, jego oczy patrzą na prawego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 1, 'Przewodnikowi chóru, na Seminit. Psalm Dawida. Ratuj, Panie, bo już nie ma pobożnego, zniknęli wierni spośród synów ludzkich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 2, 'Wszyscy mówią kłamliwie do bliźniego, mówią schlebiającymi wargami i z obłudnym sercem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 3, 'Niech Pan wytępi wszystkie wargi schlebiające i język mówiący przechwałki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 4, 'Oni mówią: Swoim językiem zwyciężymy, nasze wargi należą do nas, któż jest naszym panem?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 5, 'Ze względu na ucisk ubogich i jęk nędzarzy teraz powstanę – mówi Pan – zapewnię bezpieczeństwo temu, na kogo zastawiają sidła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 6, 'Słowa Pana to słowa czyste jak srebro wypróbowane w ziemnym tyglu, siedmiokrotnie oczyszczone.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 7, 'Ty, Panie, zachowasz ich, będziesz ich strzegł od tego pokolenia aż na wieki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 8, 'Niegodziwi krążą wokoło, gdy najpodlejsi z ludzi zostają wywyższeni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 1, 'Przewodnikowi chóru. Psalm Dawida. Jak długo, Panie? Zapomnisz o mnie na wieki? Jak długo będziesz ukrywał przede mną swoje oblicze?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 2, 'Jak długo będę szukał rady w swojej duszy i codziennie trapił się w sercu? Jak długo mój wróg będzie się nade mnie wynosił?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 3, 'Spójrz i wysłuchaj mnie, Panie, mój Boże! Oświeć moje oczy, bym nie zasnął w śmierci;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 4, 'By nie powiedział mój wróg: Pokonałem go! Niech się nie cieszą moi nieprzyjaciele, gdy się zachwieję.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 5, 'Lecz ja zaufałem twemu miłosierdziu; moje serce rozraduje się twoim zbawieniem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 6, 'Będę śpiewał Panu, bo obdarzył mnie dobrem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 1, 'Przewodnikowi chóru. Dawidowy. Głupi powiedział w swoim sercu: Nie ma Boga. Są zepsuci, popełniają obrzydliwe czyny. Nie ma nikogo, kto by czynił dobro.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 2, 'Pan spojrzał z niebios na synów ludzkich, aby zobaczyć, czy jest ktoś rozumny i szukający Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 3, 'Wszyscy zboczyli z drogi, wszyscy jednakowo znikczemnieli. Nie ma nikogo, kto by czynił dobro, nie ma ani jednego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 4, 'Czyż są nierozumni wszyscy czyniący nieprawość, którzy pożerają mój lud, jakby chleb jedli, a Pana nie wzywają?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 5, 'Tam ogarnie ich strach, gdyż Bóg jest pośród pokolenia sprawiedliwych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 6, 'Szydzicie z rady ubogiego, ale Pan jest jego ucieczką.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 7, 'Oby przyszło z Syjonu zbawienie Izraela! Gdy Pan odwróci niewolę swego ludu, Jakub się rozraduje i Izrael się rozweseli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 1, 'Psalm Dawida. Panie, kto będzie przebywał w twoim przybytku? Kto zamieszka na twojej świętej górze?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 2, 'Ten, kto postępuje nienagannie i czyni sprawiedliwość, a w swoim sercu mówi prawdę;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 3, 'Kto nie obmawia swym językiem, nie wyrządza bliźniemu nic złego, nie znieważa bliźniego;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 4, 'Ten, przed którego oczami bezbożny jest wzgardzony, a który szanuje tych, co się boją Pana; kto, choć przysięga na własną niekorzyść, nie wycofuje się;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 5, 'Kto swych pieniędzy nie pożycza na lichwę i nie daje się przekupić przeciwko niewinnemu. Kto tak postępuje, nigdy się nie zachwieje.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 1, 'Miktam Dawida. Strzeż mnie, o Boże, bo tobie ufam.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 2, 'Moja dusza mówi do Pana: Ty jesteś moim Panem, a moja dobroć nie przynosi ci żadnej korzyści;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 3, 'Lecz świętym, którzy są na ziemi, i szlachetnym, w których całe moje upodobanie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 4, 'Rozmnożą się boleści tych, którzy chodzą za obcymi bogami. Nie złożę im ofiar z krwi i nie wymówię ich imion swoimi ustami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 5, 'Pan jest udziałem mego dziedzictwa i kielicha; ty strzeżesz mojego losu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 6, 'Sznury miernicze wyznaczyły mi przyjemne miejsca i miłe jest moje dziedzictwo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 7, 'Będę błogosławił Pana, który udzielił mi rady, bo nawet w nocy pouczają mnie moje nerki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 8, 'Stawiam Pana zawsze przed oczami; skoro on jest po mojej prawicy, nie zachwieję się.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 9, 'Dlatego cieszy się moje serce i raduje się moja chwała, a moje ciało będzie spoczywać bezpiecznie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 10, 'Nie zostawisz bowiem mojej duszy w piekle ani nie dopuścisz swemu Świętemu doznać zniszczenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 11, 'Dasz mi poznać drogę życia, pełnię radości przed twoim obliczem, rozkosze po twojej prawicy na wieki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 1, 'Modlitwa Dawida. Wysłuchaj, Panie, mojej słusznej sprawy, zważ na moje wołanie, nakłoń ucha na modlitwę moich nieobłudnych ust.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 2, 'Niech wyrok o mnie wyjdzie sprzed twego oblicza, niech twoje oczy widzą to, co słuszne.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 3, 'Doświadczyłeś moje serce, nawiedziłeś mnie nocą, wypróbowałeś mnie ogniem, ale nic nie znalazłeś. Postanowiłem, że moje usta nie zgrzeszą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 4, 'Co się tyczy spraw ludzkich, dzięki słowom twoich ust wystrzegałem się dróg okrutnika.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 5, 'Zatrzymaj moje kroki na twoich drogach, aby nie zachwiały się moje nogi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 6, 'Wzywam cię, Boże, bo mnie wysłuchasz. Nakłoń ku mnie swego ucha, wysłuchaj moich słów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 7, 'Okaż swoje miłosierdzie, ty, który wybawiasz ufających tobie od tych, którzy powstają przeciwko twojej prawicy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 8, 'Strzeż mnie jak źrenicy oka, ukryj mnie w cieniu swych skrzydeł;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 9, 'Przed niegodziwymi, którzy mnie gnębią, przed wrogami mojej duszy, którzy mnie osaczyli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 10, 'Okryli się swoim tłuszczem, zuchwale mówią swymi ustami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 11, 'Gdziekolwiek idziemy, otaczają nas, wytężają swój wzrok, aby nas powalić na ziemię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 12, 'Podobni są do lwa żądnego łupu, do lwiątka siedzącego w ukryciu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 13, 'Powstań, Panie, wystąp przeciwko niemu i powal go, swoim mieczem ocal moją duszę od niegodziwego;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 14, 'A swoją ręką, Panie, od ludzi, od ludzi tego świata, których udziałem jest to życie, a których brzuchy napełniasz swymi skarbami, tak że nasyceni są nawet ich synowie, a resztę zostawiają ich dzieciom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 15, 'Ja zaś w sprawiedliwości ujrzę twe oblicze, a gdy się obudzę, nasycę się twoim podobieństwem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 1, 'Przewodnikowi chóru. Psalm sługi Pana, Dawida, który wypowiedział do Pana słowa tej pieśni w dniu, gdy go Pan ocalił z rąk wszystkich jego wrogów i z ręki Saula. Powiedział wtedy: Będę cię miłował, Panie, mocy moja.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 2, 'Pan moją skałą, moją twierdzą i wybawicielem. Mój Bóg moją opoką, której będę ufał, moją tarczą i rogiem mego zbawienia, moją warownią.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 3, 'Wezwę Pana, który jest godny chwały, a będę wybawiony od moich wrogów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 4, 'Ogarnęły mnie boleści śmierci i zatrwożyły mnie potoki bezbożnych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 5, 'Boleści piekła mnie oplotły, pochwyciły mnie sidła śmierci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 6, 'W moim utrapieniu wzywałem Pana i wołałem do mego Boga. Ze swojej świątyni usłyszał mój głos, a moje wołanie dotarło przed jego oblicze, do jego uszu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 7, 'Wtedy ziemia poruszyła się i zadrżała, a posady gór zatrzęsły się i zachwiały od jego gniewu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 8, 'Z jego nozdrzy unosił się dym, z jego ust buchnął ogień trawiący, węgle zapaliły się od niego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 9, 'Nachylił niebiosa i zstąpił, a ciemność była pod jego stopami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 10, 'Dosiadł cherubina i latał; latał na skrzydłach wiatru.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 11, 'Z ciemności zrobił sobie ukrycie, namiotem wokół niego były ciemne wody i gęste obłoki nieba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 12, 'Przed jego blaskiem rozeszły się jego obłoki, grad i węgle ogniste.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 13, 'I zagrzmiał Pan na niebiosach, Najwyższy wydał swój głos, grad i węgle ogniste.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 14, 'Wypuścił swe strzały i rozproszył ich, cisnął błyskawicami i ich rozgromił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 15, 'I ukazały się głębiny wód, i odsłoniły się fundamenty świata od twojego upomnienia, Panie, i od podmuchu tchnienia twoich nozdrzy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 16, 'Posłał z wysoka, chwycił mnie, wyciągnął mnie z wielkich wód.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 17, 'Ocalił mnie od potężnego wroga mego i od tych, którzy mnie nienawidzą, choć byli ode mnie mocniejsi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 18, 'Zaskoczyli mnie w dniu mego utrapienia, lecz Pan był moją podporą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 19, 'Wyprowadził mnie na miejsce przestronne, wybawił mnie, bo mnie sobie upodobał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 20, 'Nagrodził mnie Pan według mojej sprawiedliwości, oddał mi według czystości moich rąk.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 21, 'Strzegłem bowiem dróg Pana i nie odstąpiłem niegodziwie od mego Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 22, 'Bo miałem przed oczyma wszystkie jego nakazy i nie odrzucałem od siebie jego praw.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 23, 'Byłem wobec niego nienaganny i wystrzegałem się swojej nieprawości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 24, 'Dlatego oddał mi Pan według mojej sprawiedliwości, według czystości moich rąk przed jego oczyma.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 25, 'Ty z miłosiernym miłosiernie się obejdziesz, a z człowiekiem nienagannym postąpisz nienagannie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 26, 'Wobec czystego okażesz się czysty, a wobec przewrotnego postąpisz przewrotnie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 27, 'Ty bowiem lud strapiony wybawisz, a oczy wyniosłe poniżysz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 28, 'Bo ty zapalisz moją pochodnię; Pan, Bóg mój, rozjaśni moje ciemności.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 29, 'Bo z tobą przebiłem się przez wojsko, z moim Bogiem przeskoczyłem mur.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 30, 'Droga Boga jest doskonała, słowo Pana w ogniu wypróbowane. Tarczą jest dla wszystkich, którzy mu ufają.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 31, 'Bo któż jest Bogiem oprócz Pana? Któż skałą oprócz naszego Boga?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 32, 'To Bóg, który przepasuje mnie mocą i doskonałą czyni moją drogę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 33, 'Moje nogi czyni jak u łani i stawia mnie na wyżynach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 34, 'Ćwiczy moje ręce do walki, tak że mogę kruszyć spiżowy łuk swymi ramionami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 35, 'Dałeś mi też tarczę swego zbawienia i wspierała mnie twoja prawica, a twoja dobrotliwość uczyniła mnie wielkim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 36, 'Rozszerzyłeś ścieżkę dla mych kroków, tak że moje stopy się nie zachwiały.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 37, 'Ścigałem moich wrogów i dopadłem ich, nie zawróciłem, aż ich nie wytraciłem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 38, 'Powaliłem ich tak, że nie mogli powstać, upadli pod moje stopy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 39, 'Przepasałeś mnie mocą do walki, powaliłeś pod moje stopy moich przeciwników.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 40, 'Zmuszałeś moich wrogów do ucieczki, abym wykorzenił tych, którzy mnie nienawidzą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 41, 'Wołali, lecz nie było nikogo, kto by ich wybawił; wołali do Pana, lecz ich nie wysłuchał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 42, 'Starłem ich jak proch na wietrze, wyrzuciłem jak błoto uliczne.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 43, 'Wyzwoliłeś mnie od kłótni ludzkich, ustanowiłeś mnie głową narodów. Będzie mi służył lud, którego nie znałem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 44, 'Jak tylko usłyszą o mnie, będą mi posłuszni, cudzoziemcy będą udawać uległość.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 45, 'Cudzoziemcy zmarnieją i będą drżeć w swoich warowniach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 46, 'Pan żyje, niech będzie błogosławiona moja skała, niech będzie wywyższony Bóg mego zbawienia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 47, 'Bóg dokonuje za mnie zemsty i poddaje mi narody.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 48, 'Ty wyzwalasz mnie od moich wrogów; ty wywyższyłeś mnie ponad moich przeciwników, ocaliłeś mnie od gwałtownika.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 49, 'Dlatego będę cię, Panie, sławił wśród narodów i będę śpiewał twemu imieniu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 50, 'Bo dajesz wielkie wybawienie swemu królowi i na wieki okazujesz miłosierdzie swemu pomazańcowi Dawidowi i jego potomstwu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 1, 'Przewodnikowi chóru. Psalm Dawida. Niebiosa głoszą chwałę Boga, a firmament obwieszcza dzieło jego rąk.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 2, 'Dzień dniowi opowiada słowo, a noc nocy oznajmia wiedzę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 3, 'Nie ma języka ani mowy, w których nie słychać ich głosu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 4, 'Ich zasięg rozchodzi się po całej ziemi i na krańce świata ich słowa. Na nich wystawił namiot słońcu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 5, 'A ono wychodzi jak oblubieniec ze swojej komnaty, cieszy się jak mocarz, który rozpoczyna bieg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 6, 'Wyrusza z jednego krańca nieba i obchodzi je aż na drugi kraniec, a nic nie ukryje się przed jego żarem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 7, 'Prawo Pana jest doskonałe, nawracające duszę; świadectwo Pana pewne, dające mądrość prostemu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 8, 'Nakazy Pana są prawe, radujące serce; przykazanie Pana czyste, oświecające oczy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 9, 'Bojaźń Pana jest czysta, trwająca na wieki; sądy Pana prawdziwe, wszystkie są słuszne.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 10, 'Bardziej pożądane niż złoto, niż mnóstwo szczerego złota, i słodsze niż miód, nawet niż plaster miodu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 11, 'Także twój sługa jest przez nie pouczony, a kto ich przestrzega, otrzymuje wielką nagrodę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 12, 'Lecz kto dostrzeże własne błędy? Oczyść mnie z tych, które są ukryte przede mną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 13, 'Chroń też swego sługę od zuchwałych grzechów, aby nie panowały nade mną. Wtedy będę nienaganny i wolny od wielkiego przestępstwa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 14, 'Niech będą ci miłe słowa moich ust i rozmyślanie mego serca, Panie, moja Skało i mój Odkupicielu!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 1, 'Przewodnikowi chóru. Psalm Dawida. Niech cię wysłucha Pan w dniu utrapienia, niech cię chroni imię Boga Jakuba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 2, 'Niech ci ześle pomoc ze świątyni i niech cię wesprze z Syjonu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 3, 'Niech pamięta wszystkie twoje ofiary i niech przyjmie twoje całopalenia. Sela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 4, 'Niech da ci wszystko, czego pragnie twoje serce, i każdy twój zamysł niech wypełni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 5, 'Będziemy się radować z twojego zbawienia i w imię naszego Boga sztandary podniesiemy. Niech Pan spełni wszystkie twoje prośby.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 6, 'Teraz wiem, że Pan wybawia swego pomazańca, wysłucha go ze swego świętego nieba zbawczą mocą swojej prawicy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 7, 'Jedni pokładają ufność w rydwanach, inni w koniach, lecz my będziemy wspominać imię Pana, naszego Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 8, 'Tamci zachwiali się i upadli, a my powstaliśmy i ostoimy się.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 9, 'Panie, wybaw nas, a król niech nas wysłucha w dniu naszego wołania.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 1, 'Przewodnikowi chóru. Psalm Dawida. Panie, król cieszy się z twojej mocy i bardzo się raduje twoim zbawieniem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 2, 'Spełniłeś pragnienie jego serca i prośbie jego ust nie odmówiłeś. Sela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 3, 'Wyszedłeś mu bowiem naprzeciw z hojnymi błogosławieństwami, koronę szczerozłotą włożyłeś mu na głowę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 4, 'Prosił cię o życie i dałeś mu je, długie dni na wieki wieków.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 5, 'Wielka jest jego chwała dzięki twemu zbawieniu, okryłeś go sławą i dostojeństwem;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 6, 'Bo uczyniłeś go błogosławieństwem na wieki, rozradowałeś go swoim obliczem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 7, 'Król bowiem w Panu pokłada nadzieję i nie zachwieje się dzięki miłosierdziu Najwyższego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 8, 'Twoja ręka znajdzie wszystkich twoich wrogów; twoja prawica dosięgnie wszystkich, którzy cię nienawidzą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 9, 'Uczynisz ich jakby piecem ognistym w czasie twego gniewu; Pan w swojej zapalczywości pochłonie ich, a ogień ich strawi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 10, 'Wytracisz z ziemi ich ród, a ich potomstwo spośród synów ludzkich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 11, 'Bo zamierzali zło przeciwko tobie, uknuli spisek, którego nie mogli wykonać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 12, 'Dlatego ich zmusisz do ucieczki, strzały na twej cięciwie wymierzysz w ich twarze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 13, 'Powstań, Panie, w swojej mocy; będziemy śpiewać i wysławiać twą potęgę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 1, 'Przewodnikowi chóru, na Ajjelet haszahar. Psalm Dawida. Boże mój, Boże mój, czemu mnie opuściłeś? Czemu jesteś tak daleki od wybawienia mnie, od słów mego jęku?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 2, 'Boże mój, wołam we dnie, a nie odzywasz się do mnie; w nocy, a nie mogę się uspokoić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 3, 'Ale ty jesteś Święty, mieszkający wśród chwały Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 4, 'Tobie ufali nasi ojcowie, ufali i wyzwoliłeś ich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 5, 'Do ciebie wołali i zostali wybawieni, tobie ufali i się nie zawiedli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 6, 'Ja zaś jestem robakiem, a nie człowiekiem, pośmiewiskiem ludzi i wzgardą ludu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 7, 'Wszyscy, którzy mnie widzą, szydzą ze mnie, wykrzywiają usta, potrząsają głową, mówiąc:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 8, 'Zaufał Panu, niech go wyzwoli; niech go ocali, skoro go kocha.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 9, 'Ale to ty mnie wydobyłeś z łona, napełniłeś mnie ufnością jeszcze u piersi mojej matki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 10, 'Na ciebie byłem zdany od narodzenia, od łona matki ty jesteś moim Bogiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 11, 'Nie oddalaj się ode mnie, bo utrapienie bliskie, a nie ma nikogo, kto by mnie wspomógł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 12, 'Otoczyło mnie mnóstwo cielców, osaczyły mnie byki Baszanu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 13, 'Rozwarły na mnie swe paszcze jak lew drapieżny i ryczący.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 14, 'Rozpłynąłem się jak woda i rozłączyły się wszystkie moje kości; moje serce stało się jak wosk, roztopiło się w moim wnętrzu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 15, 'Moja siła wyschła jak skorupa, a mój język przylgnął do podniebienia; położyłeś mnie w prochu śmierci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 16, 'Psy bowiem mnie osaczyły, obległa mnie zgraja złoczyńców; przebili moje ręce i nogi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 17, 'Mogę policzyć wszystkie moje kości; a oni patrzą na mnie, przypatrują się.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 18, 'Dzielą między siebie moje szaty i o moją tunikę rzucają losy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 19, 'Ale ty, Panie, nie oddalaj się; mocy moja, spiesz mi na ratunek.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 20, 'Ocal od miecza moją duszę, od mocy psów cenną duszę moją.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 21, 'Wybaw mnie z lwiej paszczy, bo i od rogów jednorożców mnie ocaliłeś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 22, 'Będę głosił twoje imię moim braciom, będę cię chwalił pośród zgromadzenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 23, 'Chwalcie Pana, wy, którzy się go boicie; wysławiajcie go, całe potomstwo Jakuba; bójcie się go, wszyscy potomkowie Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 24, 'Bo nie wzgardził ani się nie brzydził utrapieniem ubogiego, ani nie ukrył przed nim swego oblicza, lecz gdy ten do niego wołał, wysłuchał go.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 25, 'Od ciebie pochodzi moja chwała w wielkim zgromadzeniu; wypełnię swoje śluby wobec tych, którzy się ciebie boją.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 26, 'Ubodzy będą jeść i nasycą się, chwalić Pana będą ci, którzy go szukają; wasze serce będzie żyć na wieki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 27, 'Przypomną sobie i nawrócą się do Pana wszystkie krańce ziemi i oddadzą pokłon przed twoim obliczem wszystkie rodziny narodów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 28, 'Do Pana bowiem należy królestwo i on panuje nad narodami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 29, 'Wszyscy bogaci ziemi będą jeść i oddawać mu pokłon, upadną przed jego obliczem wszyscy, którzy zstępują w proch, którzy nie mogą swej duszy zachować przy życiu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 30, 'Potomstwo będzie mu służyć i będzie poczytane Panu za pokolenie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 31, 'Przyjdą i ludowi, który się narodzi, opowiedzą jego sprawiedliwość – że on tak uczynił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 1, 'Psalm Dawida. Pan jest moim pasterzem, niczego mi nie zabraknie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 2, 'Sprawia, że kładę się na zielonych pastwiskach, prowadzi mnie nad spokojne wody.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 3, 'Posila moją duszę, prowadzi mnie ścieżkami sprawiedliwości ze względu na swoje imię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 4, 'Choćbym nawet chodził doliną cienia śmierci, zła się nie ulęknę, bo ty jesteś ze mną; twoja laska i kij pocieszają mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 5, 'Zastawiasz przede mną stół wobec moich wrogów, namaszczasz mi głowę olejkiem, mój kielich przelewa się.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 6, 'Zaprawdę dobroć i miłosierdzie pójdą w ślad za mną po wszystkie dni mego życia i będę mieszkał w domu Pana przez długie czasy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 1, 'Psalm Dawida. Do Pana należy ziemia i wszystko, co ją napełnia, świat i jego mieszkańcy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 2, 'Na morzach bowiem ugruntował go i utwierdził na rzekach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 3, 'Któż wstąpi na górę Pana? Kto stanie w jego świętym miejscu?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 4, 'Człowiek rąk nieskalanych i czystego serca, który nie skłania swej duszy ku marności i nie przysięga podstępnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 5, 'On otrzyma błogosławieństwo od Pana i sprawiedliwość od Boga, swego Zbawiciela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 6, 'To jest pokolenie tych, którzy go szukają, którzy szukają twego oblicza, Boże Jakuba. Sela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 7, 'Podnieście, o bramy, wasze głowy; podnieście się, wrota odwieczne, aby wszedł Król chwały.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 8, 'Któż jest tym Królem chwały? Pan mocny i potężny, Pan potężny w boju.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 9, 'Podnieście, o bramy, wasze głowy; podnieście się, wrota odwieczne, aby wszedł Król chwały.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 10, 'Któż jest tym Królem chwały? Pan zastępów, on jest Królem chwały. Sela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 1, 'Psalm Dawida. Do ciebie, Panie, wznoszę moją duszę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 2, 'Mój Boże, tobie ufam, niech nie doznam wstydu; niech moi wrogowie nie tryumfują nade mną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 3, 'Zaprawdę nikt, kto ciebie oczekuje, nie dozna wstydu; zawstydzą się ci, którzy bez powodu popełniają nieprawość.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 4, 'Panie, daj mi poznać twe drogi, naucz mnie twoich ścieżek.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 5, 'Prowadź mnie w twojej prawdzie i pouczaj mnie, bo ty jesteś Bogiem mego zbawienia; ciebie co dzień oczekuję.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 6, 'Pamiętaj o swoim miłosierdziu, Panie, i o twoich łaskach, które trwają od wieków.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 7, 'I nie wspominaj grzechów mojej młodości i moich występków; pamiętaj o mnie według twego miłosierdzia, ze względu na twą dobroć, Panie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 8, 'Pan jest dobry i prawy, dlatego grzeszników naucza drogi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 9, 'Poprowadzi pokornych w sprawiedliwości, pokornych nauczy swojej drogi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 10, 'Wszystkie ścieżki Pana to miłosierdzie i prawda dla tych, którzy strzegą jego przymierza i świadectwa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 11, 'Panie, przez wzgląd na twoje imię przebacz moją nieprawość, bo jest wielka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 12, 'Który to człowiek, co się boi Pana? Nauczy go drogi, którą ma wybrać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 13, 'Jego dusza będzie trwać w szczęściu i jego potomstwo odziedziczy ziemię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 14, 'Tajemnica Pana jest objawiona tym, którzy się go boją, oznajmi im swoje przymierze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 15, 'Moje oczy nieustannie patrzą na Pana, bo on wyrwie z sidła moje nogi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 16, 'Zwróć się ku mnie i zmiłuj się nade mną, bo jestem nędzny i opuszczony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 17, 'Utrapienia mego serca rozmnożyły się, wyzwól mnie z moich udręczeń.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 18, 'Spójrz na moje utrapienie i trud i przebacz wszystkie moje grzechy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 19, 'Popatrz, jak wielu jest moich wrogów i jak strasznie mnie nienawidzą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 20, 'Strzeż mojej duszy i ocal mnie, abym nie doznał wstydu; w tobie bowiem pokładam nadzieję.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 21, 'Niech mnie strzegą uczciwość i prawość, bo ciebie oczekuję.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 22, 'Boże, wybaw Izraela ze wszystkich jego udręczeń.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 1, 'Psalm Dawida. Osądź mnie, Panie, bo postępuję uczciwie, zaufałem Panu i nie zachwieję się.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 2, 'Zbadaj mnie, Panie, i doświadcz mnie; poddaj próbie moje nerki i serce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 3, 'Mam bowiem twoje miłosierdzie przed oczyma i postępuję w twojej prawdzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 4, 'Nie zasiadałem z ludźmi próżnymi i nie zadaję się z obłudnikami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 5, 'Nienawidzę zgromadzenia złoczyńców i z niegodziwymi nie usiądę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 6, 'Umyję w niewinności swoje ręce i obejdę twój ołtarz, Panie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 7, 'Aby wznosić głos dziękczynienia i opowiadać o wszystkich twoich cudach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 8, 'Panie, miłuję dom, w którym mieszkasz, i miejsce, gdzie przebywa twoja chwała.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 9, 'Nie zabieraj mojej duszy z grzesznikami ani mojego życia z krwawymi ludźmi;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 10, 'W ich rękach jest przewrotność, a ich prawica pełna jest przekupstwa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 11, 'Lecz ja będę postępować uczciwie, odkup mnie i zmiłuj się nade mną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 12, 'Moja noga stoi na równej drodze, będę błogosławił Pana w zgromadzeniach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 1, 'Psalm Dawida. Pan jest moją światłością i moim zbawieniem, kogóż będę się bać? Pan jest mocą mego życia, kogóż mam się lękać?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 2, 'Gdy złoczyńcy, moi przeciwnicy i wrogowie, wystąpili przeciwko mnie, aby pożreć moje ciało, potknęli się i upadli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 3, 'Choćby wojsko rozbiło naprzeciw mnie obóz, moje serce się nie ulęknie; choćby wojna wybuchła przeciw mnie, nawet wtedy będę ufał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 4, 'O jedno proszę Pana i o to będę zabiegał: abym mieszkał w domu Pana po wszystkie dni mego życia, abym oglądał piękno Pana i dowiadywał się w jego świątyni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 5, 'Skryje mnie bowiem w dniu niedoli w swoim przybytku, schowa mnie w ukryciu swego namiotu i wyniesie mnie na skałę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 6, 'A teraz moja głowa będzie wzniesiona nad moimi nieprzyjaciółmi, którzy mnie otaczają; będę składał w jego przybytku ofiary radości, będę śpiewał i oddawał Panu chwałę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 7, 'Usłysz, Panie, mój głos, gdy wołam; zmiłuj się nade mną i wysłuchaj mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 8, 'Gdy mówiłeś: Szukajcie mojego oblicza, moje serce mówiło do ciebie: Twojego oblicza, Panie, będę szukać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 9, 'Nie ukrywaj przede mną twojego oblicza ani nie odtrącaj w gniewie swego sługi; ty jesteś moją pomocą, nie opuszczaj mnie i nie odchodź, Boże mego zbawienia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 10, 'Choćby ojciec i matka opuścili mnie, to Pan mnie przygarnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 11, 'Naucz mnie, Panie, twojej drogi i prowadź mnie ścieżką prostą ze względu na moich wrogów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 12, 'Nie wydawaj mnie na pastwę moich nieprzyjaciół, bo powstali przeciwko mnie fałszywi świadkowie i ci, którzy dyszą okrucieństwem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 13, 'Zniechęciłbym się, gdybym nie wierzył, że będę oglądał dobroć Pana w ziemi żyjących.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 14, 'Oczekuj Pana, bądź dzielny, a on umocni twoje serce; oczekuj więc Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 1, 'Psalm Dawida. Do ciebie wołam, Panie, Skało moja; nie bądź głuchy na moje wołanie, abym jeśli się nie odezwiesz, nie stał się podobny do zstępujących do dołu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 2, 'Usłysz głos mego błagania, gdy wołam do ciebie, gdy podnoszę ręce ku twojemu miejscu najświętszemu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 3, 'Nie zabieraj mnie z niegodziwymi i z czyniącymi nieprawość, którzy mówią o pokoju z bliźnimi, a zło jest w ich sercach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 4, 'Oddaj im według ich uczynków i według zła ich postępków; według czynów ich rąk odpłać im, oddaj im, co im się należy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 5, 'Skoro nie zważają na czyny Pana ani na dzieła jego rąk, on zniszczy ich i nie odbuduje.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 6, 'Błogosławiony niech będzie Pan, bo wysłuchał głosu mego błagania.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 7, 'Pan jest moją siłą i tarczą, moje serce jemu zaufało i doznałem pomocy; dlatego moje serce się rozweseliło i moją pieśnią będę go chwalić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 8, 'Pan jest siłą dla swoich i twierdzą zbawienia swego pomazańca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 9, 'Wybaw twój lud, Panie, błogosław twemu dziedzictwu, paś ich i nieś na wieki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 1, 'Psalm Dawida. Oddajcie Panu, synowie mocarzy, oddajcie Panu chwałę i moc.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 2, 'Oddajcie Panu chwałę należną jego imieniu, oddajcie Panu pokłon w ozdobie świętości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 3, 'Głos Pana nad wodami; zagrzmiał Bóg chwały, Pan nad wielkimi wodami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 4, 'Głos Pana potężny, głos Pana pełen majestatu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 5, 'Głos Pana łamie cedry, Pan łamie cedry Libanu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 6, 'I sprawia, że skaczą jak cielę, Liban i Sirion jak młody jednorożec.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 7, 'Głos Pana krzesze płomienie ognia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 8, 'Głos Pana wstrząsa pustynią, Pan wstrząsa pustynią Kadesz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 9, 'Głos Pana sprawia, że z bólem rodzą łanie i ogołacają się lasy, a w jego świątyni każdy opowiada o jego chwale.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 10, 'Pan zasiada nad potopem, Pan zasiada jako Król na wieki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 11, 'Pan doda mocy swojemu ludowi, Pan pobłogosławi swój lud pokojem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 1, 'Psalm i pieśń na poświęcenie przybytku Dawida. Panie, będę cię wywyższać, bo podniosłeś mnie i nie pozwoliłeś mym wrogom cieszyć się z mojego powodu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 2, 'Panie, Boże mój, wołałem do ciebie i uzdrowiłeś mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 3, 'Panie, wyprowadziłeś moją duszę z piekła, zachowałeś mnie przy życiu, abym nie zstąpił do dołu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 4, 'Śpiewajcie Panu, święci jego, i wysławiajcie go, wspominając jego świętość.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 5, 'Jego gniew bowiem trwa tylko chwilę, a jego łaskawość przez całe życie; choćby płacz trwał przez noc, rankiem nastanie radość.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 6, 'Powiedziałem w czasie mej pomyślności: Nigdy się nie zachwieję.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 7, 'Panie, w swojej łaskawości umocniłeś moją górę; ale gdy ukryłeś swoje oblicze, strwożyłem się.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 8, 'Wołałem do ciebie, Panie, modliłem się do Pana:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 9, 'Jaki pożytek z mojej krwi, gdybym zstąpił do dołu? Czy proch będzie cię chwalić? Czy będzie głosić twoją prawdę?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 10, 'Usłysz, Panie, i zmiłuj się nade mną; Panie, bądź moim pomocnikiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 11, 'Mój płacz zmieniłeś w taniec, zdjąłeś ze mnie wór pokutny, a przepasałeś mnie radością;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 12, 'Aby moja chwała śpiewała ci i nie milkła; Panie, mój Boże, będę cię wysławiać na wieki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 1, 'Przewodnikowi chóru. Psalm Dawida. W tobie, Panie, pokładam nadzieję, niech nigdy nie doznam wstydu, wyzwól mnie w swojej sprawiedliwości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 2, 'Nakłoń ku mnie swego ucha, czym prędzej mnie ocal; bądź mi mocną skałą, domem obronnym, abyś mnie wybawił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 3, 'Ty bowiem jesteś moją skałą i twierdzą; dlatego przez wzgląd na twoje imię kieruj mnie i prowadź.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 4, 'Wyciągnij mnie z sieci, którą zastawili na mnie, bo ty jesteś moją siłą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 5, 'W twoje ręce powierzam mego ducha; odkupiłeś mnie, Panie, Boże wierny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 6, 'Nienawidzę tych, którzy zważają na próżne marności, bo ja w Panu pokładam nadzieję.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 7, 'Będę się radował i weselił w twoim miłosierdziu, bo wejrzałeś na moje utrapienie i poznałeś udręki mojej duszy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 8, 'I nie wydałeś mnie w ręce wroga, postawiłeś moje nogi na miejscu przestronnym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 9, 'Zmiłuj się nade mną, Panie, bo jestem uciśniony, od żałości osłabły moje oczy, a także moja dusza i moje wnętrzności.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 10, 'W bólu bowiem upływa moje życie, a moje lata na wzdychaniu; moja siła osłabła z powodu mej nieprawości, a moje kości wyschły.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 11, 'Stałem się pośmiewiskiem dla wszystkich moich wrogów, zwłaszcza dla moich sąsiadów, i postrachem dla znajomych; ci, którzy mnie widzą na dworze, uciekają przede mną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 12, 'Zapomniano o mnie jak o umarłym, stałem się jak rozbite naczynie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 13, 'Słyszę bowiem oszczerstwa wielu; strach czai się zewsząd; gdy wspólnie naradzają się przeciwko mnie, spiskują, jak odebrać mi życie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 14, 'Ale ja zaufałem tobie, Panie; powiedziałem: Ty jesteś moim Bogiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 15, 'Mój czas jest w twoich rękach, ocal mnie z ręki moich nieprzyjaciół i od tych, którzy mnie prześladują.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 16, 'Rozjaśnij swe oblicze nad twoim sługą, wybaw mnie w twoim miłosierdziu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 17, 'Panie, niech nie doznam wstydu, skoro cię wzywam; niech niegodziwi się wstydzą i zamilkną w grobie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 18, 'Niech zaniemówią wargi kłamliwe, które w pysze i pogardzie mówią krzywdzące słowa przeciwko sprawiedliwemu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 19, 'Jakże wielka jest twoja dobroć, którą zachowujesz dla bojących się ciebie i okazujesz tym, co ufają tobie wobec synów ludzkich!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 20, 'Ukryjesz ich pod osłoną twojej obecności przed pychą człowieka, ochronisz ich w namiocie przed kłótliwymi językami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 21, 'Błogosławiony niech będzie Pan, bo okazał mi swą cudowną łaskę w mieście warownym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 22, 'Powiedziałem w pośpiechu: Odrzuciłeś mnie sprzed twych oczu; lecz ty wysłuchałeś głosu mego błagania, gdy wołałem do ciebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 23, 'Miłujcie Pana, wszyscy jego święci, bo Pan strzeże wiernych, a postępującym wyniośle odpłaca z nawiązką.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 24, 'Bądźcie dzielni, wszyscy, którzy pokładacie nadzieję w Panu, a on umocni wasze serca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 1, 'Psalm Dawida. Pieśń pouczająca. Błogosławiony ten, komu przebaczono występek, komu grzech zakryto.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 2, 'Błogosławiony człowiek, któremu Pan nie poczytuje nieprawości i w którego duchu nie ma podstępu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 3, 'Gdy milczałem, moje kości schły od moich całodziennych narzekań.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 4, 'We dnie i w nocy bowiem ciążyła na mnie twoja ręka, usychałem jak podczas letniej suszy. Sela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 5, 'Wyznałem ci swój grzech i nie kryłem mojej nieprawości. Powiedziałem: Wyznam moje występki Panu, a ty przebaczyłeś nieprawość mego grzechu. Sela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 6, 'Dlatego do ciebie będzie się modlił każdy pobożny w czasie, gdy można cię znaleźć; nawet w czasie powodzi wielkich wód, one go nie dosięgną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 7, 'Ty jesteś moim schronieniem, zachowasz mnie od ucisku; otaczasz mnie pieśniami wybawienia. Sela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 8, 'Pouczę cię i nauczę cię drogi, którą masz kroczyć, poprowadzę cię swoim okiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 9, 'Nie bądźcie bezrozumni jak koń czy jak muł, których pyski trzeba okiełznać uzdą i wędzidłem, aby się na ciebie nie porywały.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 10, 'Wiele cierpień spada na niegodziwego, lecz ufającego Panu otoczy miłosierdzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 11, 'Weselcie się w Panu i radujcie się sprawiedliwi, wykrzykujcie radośnie, wszyscy prawego serca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 1, 'Weselcie się w Panu, sprawiedliwi, bo prawym przystoi chwała.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 2, 'Wysławiajcie Pana na harfie, śpiewajcie mu przy cytrze i z instrumentem o dziesięciu strunach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 3, 'Śpiewajcie mu nową pieśń, pięknie i głośno mu grajcie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 4, 'Słowo Pana bowiem jest prawe i wszystkie jego dzieła są dokonane w wierności.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 5, 'On miłuje sprawiedliwość i sąd, pełna jest ziemia miłosierdzia Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 6, 'Słowem Pana zostały uczynione niebiosa i tchnieniem jego ust wszystkie ich zastępy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 7, 'On gromadzi wody morskie jak na stos i w skarbcach zbiera głębiny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 8, 'Niech cała ziemia boi się Pana, niech się go lękają wszyscy mieszkańcy świata.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 9, 'On bowiem przemówił i stało się; on rozkazał i powstało.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 10, 'Pan udaremnia zamiary narodów, niweczy zamysły ludów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 11, 'Zamiar Pana trwa na wieki, myśli jego serca z pokolenia na pokolenie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 12, 'Błogosławiony naród, którego Bogiem jest Pan; lud, który on wybrał sobie na dziedzictwo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 13, 'Pan patrzy z nieba, widzi wszystkich synów ludzkich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 14, 'Z miejsca, w którym przebywa, spogląda na wszystkich mieszkańców ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 15, 'Ukształtował serce każdego z nich, przygląda się wszystkim ich czynom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 16, 'Nie wybawi króla liczne wojsko ani nie ocali wojownika wielka siła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 17, 'Koń jest zwodniczy w wybawieniu, nie ocali swą wielką siłą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 18, 'Oto oko Pana nad tymi, którzy się go boją, nad tymi, którzy ufają jego miłosierdziu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 19, 'Aby ocalić od śmierci ich duszę i żywić ich w czasie głodu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 20, 'Nasza dusza oczekuje Pana, on jest naszą pomocą i tarczą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 21, 'W nim bowiem rozraduje się nasze serce, bo ufamy jego świętemu imieniu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 22, 'Niech będzie nad nami twoje miłosierdzie, Panie, według pokładanej w tobie nadziei.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 1, 'Psalm Dawida, gdy zmienił swoje zachowanie przed Abimelekiem i wypędzony przez niego, odszedł. Będę błogosławił Pana w każdym czasie, jego chwała zawsze będzie na moich ustach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 2, 'Moja dusza będzie się chlubić Panem; pokorni to usłyszą i rozradują się.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 3, 'Uwielbiajcie Pana ze mną i wspólnie wywyższajmy jego imię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 4, 'Szukałem Pana, a on mnie wysłuchał i uwolnił od wszystkich mych trwóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 5, 'Spojrzeli na niego i rozpromienili się, a ich oblicza nie doznały wstydu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 6, 'Ten oto biedak wołał, a Pan wysłuchał i wybawił go ze wszystkich jego utrapień.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 7, 'Anioł Pana rozbija obóz dokoła tych, którzy się go boją, i wybawia ich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 8, 'Skosztujcie i zobaczcie, jak dobry jest Pan: Błogosławiony człowiek, który mu ufa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 9, 'Bójcie się Pana, jego święci, bo niczego nie braknie tym, którzy się go boją.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 10, 'Lwięta cierpią niedostatek i głód, lecz szukającym Pana nie zabraknie żadnego dobra.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 11, 'Chodźcie, synowie, słuchajcie mnie; nauczę was bojaźni Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 12, 'Który człowiek chce długo żyć i pragnie wiele dni, aby móc oglądać dobro?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 13, 'Strzeż swego języka od zła, a swoich warg od podstępnej mowy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 14, 'Odwróć się od zła i czyń dobrze, szukaj pokoju i dąż do niego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 15, 'Oczy Pana są zwrócone na sprawiedliwych, a jego uszy nachylone na ich wołanie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 16, 'Lecz oblicze Pana jest przeciwko złoczyńcom, aby pamięć o nich wymazać z ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 17, 'Wołają sprawiedliwi, a Pan wysłuchuje ich i uwalnia od wszelkich trudności.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 18, 'Bliski jest Pan skruszonym w sercu i wybawia złamanych na duchu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 19, 'Liczne są cierpienia sprawiedliwego, ale Pan uwalnia go od nich wszystkich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 20, 'On strzeże wszystkich jego kości; ani jedna z nich nie będzie złamana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 21, 'Zło zabija niegodziwego i ci, którzy nienawidzą sprawiedliwego, będą zniszczeni;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 22, 'Pan odkupi dusze swoich sług i nie będą zniszczeni ci, którzy mu ufają.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 1, 'Psalm Dawida. Spieraj się, Panie, z tymi, którzy się ze mną spierają; walcz z tymi, którzy walczą ze mną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 2, 'Chwyć tarczę i puklerz i powstań mi na pomoc.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 3, 'Dobądź włóczni i zagrodź drogę tym, którzy mnie prześladują. Powiedz mojej duszy: Ja jestem twoim zbawieniem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 4, 'Niech hańba i wstyd okryją tych, którzy czyhają na moją duszę; niech cofną się i niech będą zawstydzeni ci, którzy obmyślają zło przeciwko mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 5, 'Niech będą jak plewy na wietrze i niech anioł Pana ich rozproszy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 6, 'Niech droga ich będzie ciemna i śliska i niech anioł Pana ich ściga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 7, 'Bez powodu bowiem zastawili na mnie w dole sieci, bez powodu wykopali dół na moją duszę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 8, 'Niech niespodziewanie przyjdzie na nich zniszczenie; niech złowi ich sieć, którą zastawili. Niech w nią wpadną ku zniszczeniu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 9, 'A moja dusza będzie się radować w Panu, będzie się weselić jego zbawieniem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 10, 'Wszystkie moje kości powiedzą: Panie, któż podobny do ciebie, który uwalniasz uciśnionego od silniejszego, a nędznego i ubogiego od łupieżcy?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 11, 'Powstają fałszywi świadkowie i pytają mnie o to, czego nie wiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 12, 'Odpłacają mi złem za dobro, chcąc pozbawić mnie mojej duszy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 13, 'Lecz ja, gdy oni chorowali, wkładałem wór pokutny, umartwiałem postem moją duszę i moja modlitwa wracała do mojej piersi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 14, 'Postępowałem jak z przyjacielem, jak z bratem, uginałem się pod brzemieniem smutku jak w żałobie po matce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 15, 'Lecz gdy ja byłem strapiony, oni się cieszyli i zbierali się; gromadzili się przeciwko mnie nikczemni, a tego nie widziałem; szarpali mnie nieustannie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 16, 'Wraz z obłudnikami, szydercami i pochlebcami zgrzytali na mnie zębami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 17, 'Panie, jak długo będziesz na to patrzeć? Wybaw od zniszczenia moją duszę, od lwów drogą duszę moją.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 18, 'Będę cię wysławiał w wielkim zgromadzeniu, wśród licznego ludu będę cię chwalił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 19, 'Niech się nie cieszą z mojego powodu ci, którzy bez przyczyny są moimi wrogami, niech nie mrugają okiem ci, którzy niesłusznie mnie nienawidzą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 20, 'Nie mówią bowiem o pokoju, lecz przeciwko spokojnym na ziemi obmyślają zdradliwe słowa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 21, 'Owszem, otwierają przeciw mnie swe usta, mówiąc: Ha, ha! Widzieliśmy to na własne oczy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 22, 'Widziałeś to, Panie, nie milcz; Panie, nie oddalaj się ode mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 23, 'Obudź się i wystąp w mojej obronie, w mojej sprawie, mój Boże i Panie!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 24, 'Osądź mnie według swojej sprawiedliwości, Panie, mój Boże! Niech się nie cieszą z mojego powodu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 25, 'Niech nie mówią w swoim sercu: Ha! Tego chcieliśmy! Niech nie mówią: Pożarliśmy go!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 26, 'Niech się zawstydzą i zawiodą wszyscy, którzy cieszą się z mojego nieszczęścia; niech się okryją wstydem i hańbą ci, którzy wynoszą się nade mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 27, 'Ale niech śpiewają i radują się ci, którzy sprzyjają mojej słusznej sprawie; niech mówią nieustannie: Niech będzie wywyższony Pan, który pragnie pokoju dla swego sługi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 28, 'A mój język będzie głosił twoją sprawiedliwość i chwałę twoją przez cały dzień.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 1, 'Przewodnikowi chóru. Psalm Dawida, sługi Pana. Nieprawość niegodziwego świadczy w mym sercu, że nie ma bojaźni Bożej przed jego oczyma.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 2, 'Schlebia sobie bowiem w swoich oczach, aż jego nieprawość okaże się obrzydliwa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 3, 'Słowa jego ust to niegodziwość i fałsz, porzucił mądrość i czynienie dobra.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 4, 'Na swoim łożu obmyśla nieprawość, stoi na drodze niedobrej i nie brzydzi się złem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 5, 'Panie, twoje miłosierdzie sięga niebios, twoja wierność aż do obłoków.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 6, 'Twoja sprawiedliwość jak najwyższe góry, twoje sądy jak wielka przepaść; ty, Panie, zachowujesz ludzi i zwierzęta!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 7, 'Jak cenne jest twoje miłosierdzie, Boże! Dlatego synowie ludzcy chronią się w cieniu twoich skrzydeł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 8, 'Nasycą się obfitością twego domu, napoisz ich strumieniem twoich rozkoszy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 9, 'U ciebie bowiem jest źródło życia, w twojej światłości ujrzymy światłość.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 10, 'Roztocz twe miłosierdzie nad tymi, którzy cię znają, a twoją sprawiedliwość nad ludźmi prawego serca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 11, 'Niech nie następuje na mnie noga pyszałka, niech nie wygania mnie ręka niegodziwego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 12, 'Oto tam upadli czyniący nieprawość, zostali powaleni i nie będą mogli powstać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 1, 'Psalm Dawida. Nie oburzaj się z powodu złoczyńców ani nie zazdrość czyniącym nieprawość.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 2, 'Jak trawa bowiem prędko zostaną podcięci i zwiędną jak świeża zieleń.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 3, 'Ufaj Panu i czyń dobrze; będziesz mieszkał na ziemi i na pewno będziesz nakarmiony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 4, 'Rozkoszuj się Panem, a on spełni pragnienia twego serca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 5, 'Powierz Panu swoją drogę i zaufaj mu, a on wszystko wykona;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 6, 'I wyniesie twoją sprawiedliwość jak światłość, a twoją prawość jak południe.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 7, 'Poddaj się Panu i oczekuj go; nie oburzaj się na tego, komu powodzi się w drodze, na człowieka, który spełnia swe złe zamiary.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 8, 'Zaprzestań gniewu i zaniechaj zapalczywości; nie zapalaj się gniewem do czynienia zła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 9, 'Złoczyńcy bowiem będą wytępieni, a ci, którzy oczekują Pana, odziedziczą ziemię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 10, 'Jeszcze chwila, a nie będzie niegodziwego; spojrzysz na jego miejsce, a już go nie będzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 11, 'Lecz pokorni odziedziczą ziemię i będą się rozkoszować obfitością pokoju.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 12, 'Niegodziwy knuje przeciwko sprawiedliwemu i zgrzyta na niego zębami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 13, 'Lecz Pan śmieje się z niego, bo widzi, że nadchodzi jego dzień.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 14, 'Niegodziwi dobyli miecz i napinają swój łuk, aby powalić ubogiego i potrzebującego, aby zgładzić tych, którzy idą prawą drogą;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 15, 'Lecz ich miecz przeszyje ich własne serca, a ich łuki będą złamane.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 16, 'Lepsza jest odrobina, którą ma sprawiedliwy, niż wielkie bogactwa wielu niegodziwych;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 17, 'Ramiona bowiem niegodziwych będą połamane, ale sprawiedliwych Pan podtrzymuje.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 18, 'Pan zna dni nienagannych, ich dziedzictwo będzie trwać na wieki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 19, 'W czasie nieszczęścia nie doznają wstydu, a w dniach głodu będą nasyceni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 20, 'Niegodziwi zaś wyginą, a wrogowie Pana znikną jak tłuszcz barani, jak dym się rozwieją.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 21, 'Niegodziwy pożycza i nie zwraca, a sprawiedliwy lituje się i rozdaje.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 22, 'Błogosławieni przez Pana odziedziczą ziemię, a przeklęci przez niego zostaną wytępieni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 23, 'Pan kieruje krokami dobrego człowieka i jego droga mu się podoba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 24, 'Choćby upadł, nie zostanie całkowicie powalony, bo Pan podtrzymuje go swą ręką.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 25, 'Byłem młody i jestem już stary, lecz nie widziałem sprawiedliwego, który by był opuszczony, ani żeby jego potomstwo żebrało o chleb.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 26, 'Każdego dnia lituje się i pożycza, a jego potomstwo jest błogosławione.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 27, 'Odstąp od złego i czyń dobrze, a będziesz trwał na wieki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 28, 'Pan bowiem miłuje prawość i nie opuszcza swoich świętych, strzeże ich na wieki; a potomstwo niegodziwych będzie wytępione.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 29, 'Sprawiedliwi odziedziczą ziemię i będą na niej mieszkać na wieki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 30, 'Usta sprawiedliwego wypowiadają mądrość, a jego język mówi o sądzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 31, 'Prawo jego Boga jest w jego sercu, jego kroki się nie zachwieją.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 32, 'Niegodziwy czyha na sprawiedliwego i szuka sposobności, aby go zabić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 33, 'Lecz Pan nie zostawi go w jego ręku i nie potępi, gdy będzie sądzony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 34, 'Oczekuj Pana i strzeż jego drogi, a on cię wywyższy, abyś odziedziczył ziemię; zobaczysz zatracenie niegodziwych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 35, 'Widziałem niegodziwego bardzo wyniosłego i rozpierającego się jak zielone drzewo laurowe;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 36, 'Lecz przeminął i oto już go nie było; szukałem go, ale nie mogłem go znaleźć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 37, 'Spójrz na nienagannego i przypatruj się prawemu, bo ten na końcu osiągnie pokój.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 38, 'Lecz przestępcy razem zginą, niegodziwi na końcu zostaną wytępieni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 39, 'Zbawienie zaś sprawiedliwych pochodzi od Pana; on jest ich siłą w czasie utrapienia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 40, 'Pan ich wspomoże i wyzwoli; wyzwoli ich od niegodziwych i wybawi, bo w nim pokładają nadzieję.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 1, 'Psalm Dawida. Dla przypomnienia. Panie, nie karć mnie w swym gniewie i nie karz mnie w swojej zapalczywości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 2, 'Twoje strzały utkwiły bowiem we mnie i ciąży na mnie twoja ręka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 3, 'Nie ma nic zdrowego w moim ciele wskutek twego gniewu, nie ma odpoczynku dla moich kości z powodu mojego grzechu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 4, 'Bo moje nieprawości sięgają ponad moją głowę, obciążają mnie jak ciężkie brzemię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 5, 'Cuchną i ropieją moje rany z powodu mej głupoty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 6, 'Jestem zgnębiony i bardzo pochylony, przez cały dzień chodzę smutny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 7, 'Moje wnętrze bowiem pali straszna dolegliwość i nie ma nic zdrowego w moim ciele.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 8, 'Jestem osłabiony i bardzo załamany, zawodzę z powodu trwogi mego serca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 9, 'Panie, przed tobą są wszystkie moje pragnienia i moje wzdychanie nie jest przed tobą ukryte.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 10, 'Moje serce trzepocze, opuściła mnie siła, a światło moich oczu znikło.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 11, 'Moi bliscy i przyjaciele stronią od moich ran, a moi krewni stoją z daleka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 12, 'Ci, którzy czyhają na moją duszę, zastawiają sidła, a ci, którzy pragną mego nieszczęścia, mówią przewrotnie i przez cały dzień knują podstępy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 13, 'Lecz ja niczym głuchy nie słyszałem i byłem jak niemy, który nie otwiera swych ust.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 14, 'I stałem się jak człowiek, który nic nie słyszy i nie ma w ustach upomnień.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 15, 'Ciebie bowiem, Panie, oczekuję; ty odpowiesz, Panie, mój Boże.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 16, 'Bo powiedziałem: Niech się nie cieszą z mojego powodu; gdy moja noga poślizgnie się, niech nie wynoszą się nade mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 17, 'Jestem bowiem bliski upadku i moja boleść zawsze jest przede mną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 18, 'Wyznaję więc moją nieprawość i boleję nad swoim grzechem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 19, 'Lecz moi wrogowie są zdrowi i silni i namnożyło się tych, którzy bez powodu mnie nienawidzą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 20, 'Odpłacają mi złem za dobro i sprzeciwiają mi się, bo podążam za dobrem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 21, 'Nie opuszczaj mnie, Panie, mój Boże, nie oddalaj się ode mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 22, 'Pospiesz mi z pomocą, Panie, moje zbawienie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 1, 'Przewodnikowi chóru, Jedutunowi. Psalm Dawida. Powiedziałem: Będę strzegł moich dróg, abym nie zgrzeszył językiem; nałożę na usta wędzidło, dopóki niegodziwy będzie przede mną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 2, 'Zaniemówiłem oniemiały, zamilkłem nawet w dobrej sprawie, lecz moja boleść się wzmagała.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 3, 'Rozgorzało we mnie serce; gdy rozmyślałem, zapłonął ogień, a wtedy mój język tak przemówił:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 4, 'Panie, daj mi poznać mój kres i miarę moich dni, abym wiedział, jak jestem słaby.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 5, 'Oto wymierzyłeś moje dni na szerokość dłoni, a mój wiek jest niczym przed tobą; zaprawdę każdy człowiek, nawet najlepszy, jest całkowitą marnością. Sela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 6, 'Doprawdy człowiek przemija jak cień; doprawdy na próżno się kłopocze; gromadzi, a nie wie, kto to zabierze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 7, 'A teraz czego mam oczekiwać, Panie? W tobie jest moja nadzieja.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 8, 'Uwolnij mnie od wszystkich moich występków, nie wystawiaj mnie na pośmiewisko głupca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 9, 'Zamilkłem i nie otworzyłem moich ust, bo ty to sprawiłeś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 10, 'Oddal ode mnie twoje karanie, bo ginę od uderzeń twojej ręki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 11, 'Gdy karą chłoszczesz człowieka za nieprawość, to jak mól niszczysz jego piękno; doprawdy marnością jest każdy człowiek. Sela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 12, 'Wysłuchaj mojej modlitwy, Panie, i nakłoń ucha na moje wołanie; nie bądź głuchy na moje łzy, bo jestem gościem u ciebie i przychodniem, jak wszyscy moi ojcowie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 13, 'Oszczędzaj mnie, abym się wzmacniał, zanim odejdę i już mnie nie będzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 1, 'Przewodnikowi chóru. Psalm Dawida. Z tęsknotą czekałem na Pana, a skłonił się ku mnie i wysłuchał mojego wołania.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 2, 'Wyciągnął mnie ze strasznego dołu i z błota grząskiego i postawił moje stopy na skale, i umocnił moje kroki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 3, 'I włożył w moje usta nową pieśń, chwałę dla naszego Boga. Wielu to zobaczy i ulęknie się, i zaufa Panu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 4, 'Błogosławiony człowiek, który pokłada w Panu swoją nadzieję, a nie ma względu na pysznych ani na tych, którzy podążają za kłamstwem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 5, 'Wiele uczyniłeś cudów, Panie, mój Boże, a twoich zamysłów wobec nas nikt nie potrafi wyliczyć przed tobą; gdybym chciał je opowiedzieć i ogłosić, jest ich więcej, niż zdołałbym wypowiedzieć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 6, 'Ofiary i daru nie chciałeś, lecz otworzyłeś mi uszy; nie żądałeś całopalenia i ofiary za grzech.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 7, 'Wtedy powiedziałem: Oto przychodzę, na początku księgi jest napisane o mnie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 8, 'Pragnę czynić twoją wolę, mój Boże, a twoje prawo jest w moim wnętrzu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 9, 'Głosiłem twoją sprawiedliwość w wielkim zgromadzeniu; oto nie powściągałem moich ust; ty wiesz o tym, Panie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 10, 'Twojej sprawiedliwości nie kryłem w głębi serca, opowiadałem twoją wierność i zbawienie; nie taiłem twego miłosierdzia i prawdy w wielkim zgromadzeniu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 11, 'Dlatego ty, Panie, nie odmawiaj mi twej litości; twoje miłosierdzie i prawda niech mnie zawsze strzegą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 12, 'Otoczyły mnie bowiem nieszczęścia, których nie sposób zliczyć; dosięgły mnie moje nieprawości, tak że nie mogę ich przejrzeć; więcej ich niż włosów na mej głowie, więc serce we mnie ustaje.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 13, 'Panie, racz mnie ocalić; Panie, pospiesz mi na pomoc.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 14, 'Niech się zawiodą i zawstydzą wszyscy, którzy czyhają, by zatracić moją duszę; niech się cofną i zawstydzą ci, którzy mi źle życzą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 15, 'Niech będą spustoszeni wskutek swej hańby ci, którzy mi mówią: Ha, ha!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 16, 'Niech się radują i weselą w tobie wszyscy, którzy cię szukają; niech ci, którzy miłują twoje zbawienie, mówią zawsze: Niech Pan będzie wywyższony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 17, 'Ja wprawdzie jestem ubogi i nędzny, lecz Pan myśli o mnie. Ty jesteś moją pomocą i wybawicielem, mój Boże, nie zwlekaj.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 1, 'Przewodnikowi chóru. Psalm Dawida. Błogosławiony, kto zważa na ubogiego, Pan go wybawi w dniu niedoli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 2, 'Pan będzie go strzegł, zachowa przy życiu, będzie mu błogosławił na ziemi i nie wyda go na pastwę jego wrogów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 3, 'Pan pokrzepi go na łożu boleści, w czasie choroby poprawi całe jego posłanie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 4, 'Powiedziałem: Panie, zmiłuj się nade mną, uzdrów moją duszę, bo zgrzeszyłem przeciwko tobie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 5, 'Moi wrogowie źle o mnie mówią: Kiedy on umrze i zginie jego imię?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 6, 'Jeśli któryś przychodzi mnie odwiedzić, mówi obłudnie; w swoim sercu gromadzi nieprawość, a gdy wychodzi, rozpowiada.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 7, 'Wszyscy, którzy mnie nienawidzą, szepczą wspólnie przeciwko mnie, przeciwko mnie obmyślają zło;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 8, 'Mówiąc: Spadła na niego złośliwa zaraza, położył się i już nie wstanie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 9, 'Nawet mój przyjaciel, któremu ufałem, który jadł mój chleb, podniósł przeciwko mnie piętę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 10, 'Ale ty, Panie, zmiłuj się nade mną i podnieś mnie, abym im odpłacił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 11, 'Po tym poznam, że mnie sobie upodobałeś, że mój wróg nie będzie triumfował nade mną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 12, 'Ty zaś wesprzesz mnie ze względu na moją uczciwość i na wieki postawisz mnie przed swoim obliczem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 13, 'Błogosławiony Pan, Bóg Izraela, od wieków aż na wieki. Amen, amen.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 1, 'Przewodnikowi chóru. Psalm pouczający dla synów Korego. Jak jeleń pragnie wód strumieni, tak moja dusza pragnie ciebie, Boże.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 2, 'Moja dusza jest spragniona Boga, Boga żywego. Kiedy przyjdę i ukażę się przed obliczem Boga?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 3, 'Łzy stały się dla mnie chlebem we dnie i w nocy, gdy mówią do mnie co dzień: Gdzie jest twój Bóg?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 4, 'Wylewam swą duszę, gdy wspominam, jak krocząc w tłumie, szedłem z nimi do domu Bożego wśród głosów radości i chwały, pośród świętującego tłumu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 5, 'Dlaczego się smucisz, moja duszo, i czemu się we mnie trwożysz? Zaufaj Bogu, bo jeszcze będę go wysławiał za jego zbawcze oblicze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 6, 'Mój Boże, smuci się we mnie moja dusza, dlatego wspominam cię z ziemi Jordanu i Hermonu, z góry Misar.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 7, 'Przepaść przyzywa przepaść szumem twoich upustów; wszystkie twoje fale i nawałnice przewalają się nade mną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 8, 'Lecz we dnie Pan udzieli mi swego miłosierdzia, a w nocy będzie we mnie jego pieśń i moja modlitwa do Boga mego życia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 9, 'Powiem Bogu, mojej skale: Czemu o mnie zapomniałeś? Czemu chodzę smutny z powodu ucisku wroga?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 10, 'Jak rana w moich kościach, tak mnie urągają moi wrogowie, gdy mówią do mnie każdego dnia: Gdzie jest twój Bóg?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 11, 'Czemu się smucisz, moja duszo, i czemu się we mnie trwożysz? Zaufaj Bogu, bo jeszcze będę go wysławiał, gdyż on jest zbawieniem mego oblicza i moim Bogiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 1, 'Osądź mnie, Boże, broń mojej sprawy przeciwko narodowi bezbożnemu; wybaw mnie od człowieka podstępnego i bezbożnego;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 2, 'Bo ty jesteś Bogiem mojej siły. Czemu mnie odrzuciłeś? Czemu chodzę smutny z powodu ucisku wroga?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 3, 'Ześlij twoje światło i prawdę, niech mnie wiodą i wprowadzą na twoją świętą górę i do twoich przybytków.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 4, 'Wtedy przystąpię do ołtarza Bożego, do Boga, mojego wesela i radości; będę cię wysławiał na harfie, Boże, mój Boże.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 5, 'Czemu się smucisz, moja duszo, i czemu się we mnie trwożysz? Zaufaj Bogu, bo jeszcze będę go wysławiał, gdyż on jest zbawieniem mego oblicza i moim Bogiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 1, 'Przewodnikowi chóru. Psalm pouczający dla synów Korego. Boże, słyszeliśmy na własne uszy, nasi ojcowie opowiadali nam o tym, czego dokonałeś za ich dni, w czasach dawnych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 2, 'Ty własną ręką wypędziłeś pogan, a ich osadziłeś; wyniszczyłeś narody, a ich rozprzestrzeniłeś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 3, 'Nie zdobyli bowiem ziemi swym mieczem ani ich nie wybawiło własne ramię, lecz twoja prawica i twoje ramię, i światło twego oblicza, bo upodobałeś ich sobie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 4, 'Ty jesteś moim Królem, o Boże; daj wybawienie Jakubowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 5, 'Dzięki tobie pokonamy naszych wrogów, w twoje imię zdepczemy naszych przeciwników.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 6, 'Nie zaufam bowiem mojemu łukowi i nie wybawi mnie mój miecz;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 7, 'Lecz ty nas wybawiłeś od naszych wrogów i zawstydziłeś tych, którzy nas nienawidzą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 8, 'Każdego dnia chlubimy się Bogiem, a twoje imię będziemy sławić na wieki. Sela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 9, 'Teraz jednak odrzuciłeś nas i zawstydziłeś, i nie wyruszasz z naszymi wojskami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 10, 'Sprawiłeś, że cofnęliśmy się przed wrogiem, a ci, którzy nas nienawidzą, złupili nas.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 11, 'Wydałeś nas na rzeź jak owce i rozproszyłeś nas wśród pogan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 12, 'Sprzedałeś swój lud za bezcen i nie zyskałeś na jego sprzedaży.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 13, 'Wystawiłeś nas na wzgardę naszym sąsiadom, na szyderstwo i pośmiewisko tym, którzy nas otaczają.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 14, 'Uczyniłeś nas tematem przysłowia wśród pogan, tak że narody kiwają głowami nad nami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 15, 'Mój wstyd wciąż jest przede mną, a hańba mi twarz okrywa;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 16, 'Na głos tego, który gardzi i bluźni, z powodu wroga i mściciela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 17, 'To wszystko nas spotkało, a jednak nie zapomnieliśmy o tobie ani nie naruszyliśmy twojego przymierza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 18, 'Nasze serce się nie odwróciło ani nasze kroki nie zboczyły z twej ścieżki;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 19, 'Chociaż powaliłeś nas w miejscu smoków i okryłeś nas cieniem śmierci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 20, 'Gdybyśmy zapomnieli imienia naszego Boga i wyciągnęli ręce do obcego boga;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 21, 'Czyż Bóg by się o tym nie dowiedział? Przecież on zna tajniki serca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 22, 'Lecz z powodu ciebie przez cały dzień nas zabijają, uważają nas za owce przeznaczone na rzeź.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 23, 'Ocknij się; czemu śpisz, Panie? Obudź się, nie odrzucaj nas na wieki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 24, 'Czemu ukrywasz swoje oblicze i zapominasz o naszym utrapieniu i ucisku?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 25, 'Nasza dusza bowiem pogrążyła się w prochu, nasz brzuch przylgnął do ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 26, 'Powstań nam na pomoc, odkup nas ze względu na twoje miłosierdzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 1, 'Przewodnikowi chóru, na Szoszanim dla synów Korego. Psalm pouczający. Pieśń miłosna. Wezbrało moje serce dobrym słowem; dzieła, które wypowiadam, dotyczą króla; mój język będzie jak pióro biegłego pisarza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 2, 'Ty jesteś najpiękniejszym z synów ludzkich; wdzięk rozlał się na twoich wargach, dlatego Bóg pobłogosławił cię na wieki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 3, 'Przypasz do biodra swój miecz, mocarzu, w swej chwale i majestacie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 4, 'A w swym dostojeństwie wyrusz szczęśliwie ze słowem prawdy, łagodności i sprawiedliwości, a twoja prawica dokona strasznych rzeczy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 5, 'Twoje ostre strzały, od których upadają narody pod twoje stopy, przenikają serce wrogów króla.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 6, 'Twój tron, o Boże, na wieki wieków, berłem sprawiedliwości jest berło twego królestwa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 7, 'Miłujesz sprawiedliwość, a nienawidzisz nieprawości, dlatego namaścił cię, o Boże, twój Bóg olejkiem radości bardziej niż twoich towarzyszy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 8, 'Wszystkie twoje szaty pachną mirrą, aloesem i kasją, gdy wychodzisz z pałaców z kości słoniowej, z których cię rozweselają.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 9, 'Córki królewskie są wśród twoich czcigodnych kobiet, królowa w złocie z Ofiru stoi po twojej prawicy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 10, 'Posłuchaj, córko, spójrz i nakłoń ucha, zapomnij o swoim narodzie i o domu swojego ojca;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 11, 'A król zapragnie twojego piękna, bo on jest twoim Panem; oddaj mu pokłon.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 12, 'Także córka Tyru przyjdzie z darami, najbogatsi z narodów będą zabiegać o twą przychylność.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 13, 'Córka królewska jest pełna chwały w swej komnacie, a jej szaty złotem tkane.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 14, 'W szacie haftowanej będą ją wieść do króla, za nią dziewice, jej towarzyszki, przyprowadzą do ciebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 15, 'Wiodą je z weselem i z radością i wejdą do królewskiego pałacu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 16, 'Miejsce twoich ojców zajmą twoi synowie, których ustanowisz książętami po całej ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 17, 'Upamiętnię twoje imię po wszystkie pokolenia; dlatego narody będą cię wysławiać na wieki wieków.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 1, 'Przewodnikowi chóru dla synów Korego. Pieśń na Alamot. Bóg jest naszą ucieczką i siłą, najpewniejszą pomocą w utrapieniu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 2, 'Dlatego nie będziemy się bać, choćby się poruszyła ziemia, choćby się przeniosły góry w sam środek morza;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 3, 'Choćby huczały i burzyły się jego wody i zatrzęsły się góry od jego nawałnicy. Sela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 4, 'Jest rzeka, której strumienie rozweselają miasto Boże, miejsce święte przybytków Najwyższego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 5, 'Bóg jest pośrodku niego, nie będzie zachwiane; Bóg je wspomoże zaraz o świcie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 6, 'Wzburzyły się narody, zachwiały się królestwa, on wydał swój głos i rozpłynęła się ziemia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 7, 'Pan zastępów jest z nami; Bóg Jakuba jest naszą twierdzą. Sela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 8, 'Chodźcie, zobaczcie dzieła Pana, jakie spustoszenia uczynił na ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 9, 'On kładzie kres wojnom aż po krańce ziemi, kruszy łuki i łamie włócznie, a rydwany pali ogniem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 10, 'Uspokójcie się i uznajcie, że ja jestem Bogiem; będę wywyższony wśród narodów, będę wywyższony na ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 11, 'Pan zastępów jest z nami, Bóg Jakuba jest naszą twierdzą. Sela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 1, 'Przewodnikowi chóru. Psalm dla synów Korego. Klaszczcie w dłonie, wszystkie narody, wykrzykujcie Bogu radosnym głosem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 2, 'Gdyż Pan Najwyższy budzi grozę, jest wielkim Królem nad całą ziemią.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 3, 'Podda nam ludzi i narody pod nasze stopy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 4, 'Wybrał nam nasze dziedzictwo, chlubę Jakuba, którego umiłował. Sela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 5, 'Wstąpił Bóg wśród okrzyków, Pan przy dźwięku trąby.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 6, 'Śpiewajcie Bogu, śpiewajcie; śpiewajcie naszemu Królowi, śpiewajcie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 7, 'Bóg bowiem jest Królem całej ziemi, śpiewajcie pieśni pouczające.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 8, 'Bóg króluje nad narodami, Bóg zasiada na swym świętym tronie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 9, 'Władcy narodów zebrali się z ludem Boga Abrahama, bo do Boga należą tarcze ziemi; on jest wielce wywyższony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 1, 'Pieśń i psalm dla synów Korego. Wielki jest Pan i godzien wielkiej chwały w mieście naszego Boga, na swej świętej górze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 2, 'Pięknie wzniesiona, radością całej ziemi jest góra Syjon na krańcach północy, miasto wielkiego Króla.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 3, 'Bóg w pałacach jego jest uznany za twierdzę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 4, 'Bo oto zgromadzili się królowie i razem ruszyli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 5, 'Gdy zobaczyli, zdumieli się, przerazili się i uciekli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 6, 'Strach ich tam ogarnął i ból, jak rodzącą kobietę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 7, 'Wiatrem wschodnim rozbijasz okręty Tarszisz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 8, 'To, co słyszeliśmy, to zobaczyliśmy w mieście Pana zastępów, w mieście naszego Boga; Bóg je ugruntuje na wieki. Sela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 9, 'Rozważamy, o Boże, twoje miłosierdzie we wnętrzu twej świątyni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 10, 'Jak twoje imię, Boże, tak i chwała twoja sięga aż po krańce ziemi; twoja prawica pełna jest sprawiedliwości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 11, 'Niech się weseli góra Syjon, niech się radują córki Judy z powodu twoich sądów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 12, 'Okrążcie Syjon i obejdźcie go, policzcie jego wieże.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 13, 'Przyjrzyjcie się jego wałom obronnym, oglądajcie jego pałace, abyście mogli opowiadać przyszłemu pokoleniu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 14, 'Bo ten Bóg jest naszym Bogiem na wieki wieków, on będzie nas prowadził aż do śmierci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 1, 'Przewodnikowi chóru. Psalm dla synów Korego. Słuchajcie tego wszystkie narody, nadstawcie ucha wszyscy mieszkańcy świata.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 2, 'Zarówno wy, prości, jak i wy, możni; zarówno bogaty, jak i ubogi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 3, 'Moje usta wypowiedzą mądrość, a rozmyślaniem mego serca będzie roztropność.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 4, 'Nakłonię ucha ku przypowieści, przy harfie rozwiążę moją zagadkę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 5, 'Dlaczego mam się bać w dniach niedoli, gdy otacza mnie nieprawość tych, którzy mnie depczą?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 6, 'Ci, którzy ufają swym bogactwom i chlubią się swym wielkim dostatkiem;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 7, 'Nikt z nich w żaden sposób nie odkupi swego brata ani nie może dać Bogu za niego okupu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 8, '(Kosztowny bowiem jest okup za ich dusze i nigdy się nie zdarzy);');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 9, 'Aby żył na wieki i nie doznał zniszczenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 10, 'Każdy bowiem widzi, że mądrzy umierają, tak samo jak ginie głupiec i prostak, i zostawiają obcym swoje bogactwa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 11, 'Myślą, że ich domy są wieczne, a ich mieszkania będą trwać z pokolenia na pokolenie; nazywają ziemie swymi imionami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 12, 'Lecz człowiek, choć otoczony czcią, nie przetrwa; podobny jest do bydląt, które giną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 13, 'Ich droga jest ich głupstwem, mimo to ich potomkowie pochwalają ich mowę. Sela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 14, 'Jak owce będą złożeni w grobie, śmierć ich pożre; prawi będą nad nimi panować o poranku, ich postać zostanie zniszczona w grobie, gdy opuszczą swoje mieszkanie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 15, 'Ale Bóg wykupi moją duszę z mocy grobu, bo mnie przyjmie. Sela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 16, 'Nie bój się, gdy się ktoś wzbogaci, gdy się rozmnoży sława jego domu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 17, 'Bo gdy umrze, niczego ze sobą nie weźmie i nie pójdzie za nim jego sława.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 18, 'Chociaż za życia swej duszy pochlebiał i chwalono go, gdy dobrze się urządził;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 19, 'Pójdzie jednak do grona swych ojców; nigdy nie ujrzą światła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 20, 'Człowiek, który jest otoczony czcią, a nie rozumie tego, podobny jest do bydląt, które giną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 1, 'Psalm Asafa. Bóg nad bogami, Pan, przemówił i wezwał ziemię od wschodu słońca aż do jego zachodu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 2, 'Z Syjonu, doskonałego piękna, zajaśniał Bóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 3, 'Nasz Bóg przyjdzie i nie będzie milczał; ogień będzie trawił przed nim, a wokół niego powstanie potężna burza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 4, 'Wezwie z góry niebiosa i ziemię, aby sądzić swój lud:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 5, 'Zgromadźcie mi moich świętych, którzy zawarli ze mną przymierze przez ofiarę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 6, 'Wtedy niebiosa ogłoszą jego sprawiedliwość, bo sam Bóg jest sędzią. Sela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 7, 'Słuchaj, mój ludu, a będę mówił; słuchaj, Izraelu, a będę świadczył przeciw tobie: Ja jestem Bogiem, twoim Bogiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 8, 'Nie będę cię ganił za twoje ofiary ani za twoje całopalenia, które są zawsze przede mną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 9, 'Nie przyjmę cielca z twojego domu ani kozłów z twoich zagród.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 10, 'Do mnie bowiem należy wszelkie zwierzę leśne i tysiące bydła na górach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 11, 'Znam wszelkie ptactwo górskie i moje są zwierzęta polne.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 12, 'Gdybym był głodny, nie mówiłbym ci o tym, bo mój jest świat i wszystko, co go napełnia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 13, 'Czyż będę jadł mięso wołów albo pił krew kozłów?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 14, 'Ofiaruj Bogu dziękczynienie i spełnij swoje śluby wobec Najwyższego;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 15, 'I wzywaj mnie w dniu utrapienia; wtedy cię wybawię, a ty mnie uwielbisz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 16, 'Lecz do niegodziwego Bóg mówi: Po co ogłaszasz moje prawa i masz na ustach moje przymierze;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 17, 'Skoro nienawidzisz karności i rzucasz za siebie moje słowa?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 18, 'Gdy widzisz złodzieja, pochwalasz go, i zadajesz się z cudzołożnikami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 19, 'Pozwalasz swym ustom źle mówić, a twój język knuje podstępy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 20, 'Siedzisz i mówisz przeciwko twemu bratu, obmawiasz syna swej matki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 21, 'To czyniłeś, a ja milczałem; sądziłeś, że jestem do ciebie podobny, ale będę cię napominał i postawię ci to przed oczy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 22, 'Zrozumcie to teraz wy, którzy zapominacie o Bogu, bym was nie rozszarpał, a nie byłoby nikogo, kto by was ocalił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 23, 'Kto mi ofiaruje chwałę, ten oddaje mi cześć; a temu, kto chodzi prostą drogą, ukażę Boże zbawienie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 1, 'Przewodnikowi chóru. Psalm Dawida, gdy do niego przyszedł prorok Natan po tym, jak on wszedł do Batszeby. Zmiłuj się nade mną, Boże, według twojego miłosierdzia; według twojej wielkiej litości zgładź moje występki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 2, 'Obmyj mnie zupełnie z mojej nieprawości i oczyść mnie z mego grzechu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 3, 'Uznaję bowiem moje występki, a mój grzech zawsze jest przede mną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 4, 'Przeciw tobie, tobie samemu, zgrzeszyłem i zło uczyniłem na twoich oczach, abyś okazał się sprawiedliwy w swoich słowach i czysty w swoim sądzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 5, 'Oto zostałem zrodzony w nieprawości i w grzechu poczęła mnie moja matka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 6, 'Oto miłujesz prawdę wewnętrzną i w głębi serca dasz mi poznać mądrość.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 7, 'Oczyść mnie hizopem, a będę oczyszczony; obmyj mnie, a stanę się bielszy od śniegu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 8, 'Daj mi usłyszeć radość i wesele; niech się rozradują kości, które skruszyłeś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 9, 'Odwróć swe oblicze od moich grzechów i zgładź wszystkie moje nieprawości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 10, 'Stwórz we mnie serce czyste, o Boże, i odnów we mnie ducha prawego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 11, 'Nie odrzucaj mnie sprzed twego oblicza i nie odbieraj mi swego Ducha Świętego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 12, 'Przywróć mi radość twego zbawienia i wesprzyj mnie duchem ochoczym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 13, 'Wtedy będę nauczał przestępców twoich dróg i grzesznicy nawrócą się do ciebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 14, 'Uwolnij mnie od winy za przelanie krwi, o Boże, Boże mego zbawienia, a mój język będzie wysławiał twoją sprawiedliwość.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 15, 'Panie, otwórz moje wargi, a moje usta będą głosić twoją chwałę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 16, 'Ty bowiem nie pragniesz ofiar, choćbym ci je dał, ani nie przyjmiesz całopalenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 17, 'Ofiary dla Boga to duch skruszony; sercem skruszonym i zgnębionym nie wzgardzisz, o Boże!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 18, 'Okaż dobroć Syjonowi według twego upodobania; odbuduj mury Jeruzalem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 19, 'Wtedy przyjmiesz ofiary sprawiedliwości, ofiary ogniste i całopalenia; wtedy będą składać cielce na twoim ołtarzu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 1, 'Przewodnikowi chóru. Psalm pouczający Dawida, gdy przybył Doeg Edomita i oznajmił Saulowi: Dawid wszedł do domu Achimeleka. Czemu chlubisz się złem, mocarzu? Miłosierdzie Boże trwa nieustannie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 2, 'Twój język knuje przewrotność, ostry jak brzytwa, działający podstępnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 3, 'Miłujesz zło bardziej niż dobro i kłamstwo bardziej niż mowę sprawiedliwą. Sela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 4, 'Miłujesz wszelkie słowa szkodliwe, podstępny języku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 5, 'Dlatego Bóg zniszczy cię na wieki, pochwyci cię i wyrwie z namiotu, i wykorzeni cię z ziemi żyjących. Sela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 6, 'Zobaczą to sprawiedliwi i zlękną się, i będą się z niego śmiać:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 7, 'Oto człowiek, który nie uczynił Boga swoją siłą, ale ufał swym wielkim bogactwom i umacniał się w swojej nieprawości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 8, 'Ja zaś jestem jak zielone drzewo oliwne w domu Bożym, zaufałem miłosierdziu Boga na wieki wieków.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 9, 'Będę cię wysławiał na wieki, że to uczyniłeś, i będę oczekiwał twego imienia, gdyż jest dobre w oczach twoich świętych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 1, 'Przewodnikowi chóru, na Machalat. Psalm pouczający Dawida. Głupi mówi w swoim sercu: Nie ma Boga. Są zepsuci i czynią obrzydliwą nieprawość; nie ma nikogo, kto by czynił dobro.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 2, 'Bóg spojrzał z niebios na synów ludzkich, aby zobaczyć, czy jest ktoś rozumny i szukający Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 3, 'Wszyscy zboczyli z drogi, wszyscy jednakowo znikczemnieli; nie ma nikogo, kto by czynił dobro, nie ma ani jednego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 4, 'Czyż są nierozumni czyniący nieprawość, którzy pożerają mój lud, jakby chleb jedli, a Boga nie wzywają?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 5, 'Tam ogarnął ich strach, gdzie nie było powodu do strachu, Bóg bowiem rozproszył kości tych, którzy cię oblegali; ty okryjesz ich hańbą, bo Bóg nimi wzgardził.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 6, 'Któż ześle z Syjonu zbawienie Izraelowi? Gdy Bóg odwróci niewolę swego ludu, Jakub się rozraduje i rozweseli się Izrael.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 1, 'Przewodnikowi chóru, na Neginot. Psalm pouczający Dawida, gdy przyszli mieszkańcy Zif i powiedzieli do Saula: Dawid się u nas ukrywa. Boże, wybaw mnie twoim imieniem i twoją mocą broń mojej sprawy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 2, 'Boże, wysłuchaj mojej modlitwy, nakłoń ucha ku słowom moich ust.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 3, 'Gdyż obcy powstali przeciwko mnie, a okrutnicy czyhają na moją duszę; nie mają Boga przed oczami. Sela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 4, 'Oto Bóg jest moim pomocnikiem; Pan jest z tymi, którzy podtrzymują moje życie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 5, 'Odpłaci złem moim wrogom; w twojej prawdzie wytrać ich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 6, 'Będę ci dobrowolnie składał ofiary, będę wysławiał twoje imię, Panie, bo jest dobre.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 7, 'Uwolniłeś mnie bowiem z każdego utrapienia, a moje oko widziało zemstę nad moimi wrogami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 1, 'Przewodnikowi chóru, na Neginot. Pieśń pouczająca Dawida. Boże, nakłoń ucha ku mojej modlitwie i nie ukrywaj się przed moją prośbą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 2, 'Posłuchaj uważnie i wysłuchaj mnie; uskarżam się w swej modlitwie i jęczę;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 3, 'Z powodu głosu wroga, z powodu ucisku niegodziwego; zwalają na mnie nieprawość i w gniewie sprzeciwiają mi się.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 4, 'Moje serce boleje we mnie i dopadł mnie strach przed śmiercią.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 5, 'Przyszły na mnie bojaźń i drżenie i przejęła mnie trwoga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 6, 'I powiedziałem: O, gdybym miał skrzydła jak gołębica, uleciałbym i odpoczął.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 7, 'Oto bym uleciał daleko i zamieszkał na pustyni. Sela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 8, 'Pospieszyłbym, aby ujść przed wichrem i nawałnicą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 9, 'Zniszcz, Panie, rozdziel ich język, bo widzę przemoc i niezgodę w mieście.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 10, 'Dniem i nocą krążą wokoło po jego murach, a wewnątrz niego zło i ucisk.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 11, 'Wewnątrz niego jest niegodziwość, a z jego ulic nie znika oszustwo i podstęp.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 12, 'Bo to nie wróg mnie lżył, co mógłbym znieść; nie powstał przeciwko mnie ten, który mnie nienawidził – wtedy ukryłbym się przed nim;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 13, 'Ale ty, człowiek równy mi, mój wódz i przyjaciel.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 14, 'Mile naradzaliśmy się ze sobą i razem chodziliśmy do domu Bożego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 15, 'Niech śmierć ich zaskoczy, niech żywcem zstąpią do piekła, bo w ich domach i wśród nich mieszka zło.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 16, 'Ja zaś do Boga zawołam i Pan mnie wybawi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 17, 'Wieczorem, rano i w południe będę się modlić i głośno wołać, a on wysłucha mego głosu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 18, 'Odkupił moją duszę, abym miał spokój od walki, jaką ze mną toczyli, bo wielu ich było przy mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 19, 'Bóg wysłucha i będzie ich trapić ten, który trwa od wieków. Sela. Bo nie poprawiają się i nie boją się Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 20, 'Podniósł rękę na tych, którzy utrzymywali z nim pokój; złamał swoje przymierze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 21, 'Gładsze niż masło były słowa jego ust, lecz wrogość miał w sercu; miększe niż oliwa jego słowa, ale były jak obnażone miecze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 22, 'Przerzuć swój ciężar na Pana, a on cię podtrzyma; nie dopuści nigdy, by miał się zachwiać sprawiedliwy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 23, 'Ale ty, Boże, wtrącisz ich w dół zatracenia; ludzie krwawi i podstępni nie dożyją połowy swoich dni; ja zaś zaufam tobie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 1, 'Przewodnikowi chóru, na Jonat elem rechokim. Miktam Dawida, gdy Filistyni schwytali go w Gat. Zmiłuj się nade mną, Boże, bo chce mnie pochłonąć człowiek; każdego dnia uciska mnie walką.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 2, 'Moi wrogowie każdego dnia chcą mnie połknąć; wielu bowiem walczy przeciwko mnie, o Najwyższy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 3, 'Ilekroć strach mnie ogarnia, ufam tobie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 4, 'W Bogu będę wysławiać jego słowo; Bogu ufam i nie będę się bał tego, co człowiek może mi uczynić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 5, 'Przez cały dzień przekręcają moje słowa, przeciwko mnie kierują wszystkie swe zamysły, ku memu nieszczęściu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 6, 'Zbierają się, ukrywają i śledzą moje kroki, czyhając na moją duszę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 7, 'Czy unikną zemsty za nieprawość? Boże, powal te narody w swoim gniewie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 8, 'Ty policzyłeś dni mojej tułaczki, zbierz też moje łzy do swego bukłaka; czyż nie są spisane w twojej księdze?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 9, 'Gdy zawołam, cofną się moi wrogowie; to wiem, bo Bóg jest ze mną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 10, 'W Bogu będę wysławiać jego słowa, w Panu będę chwalić jego słowo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 11, 'Bogu ufam, nie będę się bał tego, co mi może uczynić człowiek.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 12, 'Tobie, Boże, śluby złożyłem, dlatego też tobie oddam chwałę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 13, 'Ocaliłeś bowiem moją duszę od śmierci, a moje nogi od upadku, abym chodził przed Bogiem w światłości żyjących.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 1, 'Przewodnikowi chóru. Al taszchet. Miktam Dawida, kiedy uciekał przed Saulem do jaskini. Zmiłuj się nade mną, Boże, zmiłuj się nade mną, bo moja dusza ufa tobie; w cieniu twoich skrzydeł będę się chronił, aż przeminie nieszczęście.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 2, 'Będę wołał do Boga Najwyższego, do Boga, który doprowadzi moją sprawę do końca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 3, 'On ześle pomoc z nieba i wybawi mnie od urągania tego, który chce mnie pochłonąć. Sela. Ześle mi Bóg swoje miłosierdzie i prawdę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 4, 'Moja dusza przebywa wśród lwów; leżę wśród płonących, wśród synów ludzkich, których zęby są jak włócznie i strzały, a język jak miecz ostry.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 5, 'Bądź wywyższony, Boże, ponad niebiosa, a twoja chwała ponad całą ziemię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 6, 'Zastawili sidła na moje kroki, zgnębili moją duszę, wykopali przede mną dół, ale sami do niego wpadli. Sela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 7, 'Gotowe jest moje serce, Boże, gotowe jest moje serce; będę śpiewał i oddawał chwałę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 8, 'Obudź się, moja chwało, obudź się, cytro i harfo; ja się zbudzę o świcie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 9, 'Będę cię wysławiał wśród ludu, Panie, będę ci śpiewał wśród narodów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 10, 'Bo wielkie jest twoje miłosierdzie, aż do niebios, i aż pod obłoki twoja prawda.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 11, 'Bądź wywyższony ponad niebiosa, Boże, a ponad całą ziemię twoja chwała.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 1, 'Przewodnikowi chóru. Al taszchet. Miktam Dawida. O zgromadzenie, czy rzeczywiście mówicie to, co sprawiedliwe? Czy słusznie sądzicie, synowie ludzcy?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 2, 'Przeciwnie, w sercu knujecie nieprawości, wymierzacie przemoc waszych rąk na ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 3, 'Niegodziwi zeszli na bezdroża już od łona matki, od urodzenia błądzą, mówiąc kłamstwo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 4, 'Ich jad podobny do jadu węża, są jak głucha żmija, która zatyka uszy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 5, 'Aby nie słyszeć głosu zaklinaczy ani czarownika, co biegle zaklina.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 6, 'Boże, skrusz zęby w ich ustach; Panie, połam zęby trzonowe lwiąt.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 7, 'Niech znikną jak spływająca woda, niech będą jak ten, który naciąga łuk, lecz jego strzały się łamią.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 8, 'Niech przeminą jak ślimak, który się rozpływa; jak poroniony płód kobiety niech nie zobaczą słońca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 9, 'Zanim wasze ciernie wypuszczą kolce, gdy jeszcze są zielone, porwie je wicher gniewu Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 10, 'Będzie się weselił sprawiedliwy, gdy ujrzy pomstę; swoje stopy umyje we krwi niegodziwego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 11, 'A ludzie powiedzą: Jest, doprawdy, nagroda dla sprawiedliwego; doprawdy jest Bóg, który sądzi na ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 1, 'Przewodnikowi chóru. Al taszchet. Miktam Dawida, gdy Saul posłał ludzi, którzy pilnowali domu Dawida, aby go zabić. Ocal mnie od moich wrogów, mój Boże; obroń mnie przed tymi, którzy powstają przeciwko mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 2, 'Ocal mnie od czyniących nieprawość i wybaw mnie przed krwawymi ludźmi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 3, 'Oto bowiem czyhają na moją duszę; zbierają się przeciwko mnie mocarze, chociaż nie zawiniłem ani nie zgrzeszyłem, Panie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 4, 'Chociaż nie popełniłem nieprawości, biegną i szykują się; powstań, wyjdź mi na spotkanie i zobacz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 5, 'Ty, Panie, Boże zastępów, Boże Izraela, obudź się, aby nawiedzić wszystkie narody; nie lituj się nad żadnym z tych nikczemnych przestępców. Sela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 6, 'Wracają wieczorem, ujadają jak psy i krążą po mieście.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 7, 'Oto bluzgają swymi ustami, miecze na ich wargach. Mówią bowiem: Któż słyszy?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 8, 'Lecz ty, Panie, będziesz się śmiał z nich, szydzić będziesz ze wszystkich narodów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 9, 'Z powodu jego mocy będę się trzymać ciebie, bo ty, Boże, jesteś moją twierdzą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 10, 'Mój miłosierny Bóg wyjdzie mi naprzeciw, Bóg pozwoli mi oglądać zemstę nad moimi wrogami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 11, 'Nie zabijaj ich, aby mój lud nie zapomniał, lecz rozprosz ich swoją mocą i powal, o Panie, nasza tarczo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 12, 'Za grzech ich ust i słowa ich warg niech schwytani będą w swej pysze; za złorzeczenia i kłamstwa, które mówią.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 13, 'Wytrać ich w gniewie, wytrać, by już ich nie było. Niech poznają, że Bóg panuje w Jakubie i po krańce ziemi. Sela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 14, 'I niech wracają wieczorem, niech ujadają jak psy i krążą po mieście.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 15, 'Niech się włóczą, szukając pokarmu; niech warczą, gdy się nie nasycą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 16, 'Ale ja będę śpiewał o twojej mocy, rankiem będę wysławiać twoje miłosierdzie, bo ty stałeś się dla mnie twierdzą i ucieczką w dniu mego ucisku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 17, 'Moja mocy, tobie będę śpiewał; bo ty, Boże, jesteś moją twierdzą, Boże mój miłosierny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 1, 'Przewodnikowi chóru, na Sussanedut. Miktam Dawida dla pouczenia; gdy walczył przeciw Syryjczykom Nacharaim i przeciw Syryjczykom Soby, gdy Joab, wracając, pobił dwanaście tysięcy Edomitów w Dolinie Soli. Boże, odrzuciłeś nas, rozproszyłeś nas i rozgniewałeś się; powróć znowu do nas.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 2, 'Wstrząsnąłeś ziemią i rozdarłeś ją; ulecz jej rozpadliny, bo się chwieje.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 3, 'Okazywałeś twemu ludowi ciężkie rzeczy, napoiłeś nas winem odurzającym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 4, 'Dałeś chorągiew tym, którzy się ciebie boją, aby wynieśli ją z powodu twej prawdy. Sela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 5, 'Aby byli ocaleni twoi umiłowani, wybaw ich swoją prawicą i wysłuchaj mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 6, 'Bóg przemówił w swojej świętości; będę się radował, rozdzielę Sychem i wymierzę dolinę Sukkot.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 7, 'Mój jest Gilead, mój i Manasses, Efraim mocą mojej głowy, Juda moim prawodawcą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 8, 'Moab moją misą do mycia, na Edom wrzucę mój but; Filisteo, wykrzykuj z mojego powodu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 9, 'Kto mnie wprowadzi do miasta warownego? Kto mnie doprowadzi aż do Edomu?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 10, 'Czy nie ty, o Boże, który nas odrzuciłeś i nie wychodziłeś, Boże, z naszymi wojskami?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 11, 'Udziel nam pomocy w utrapieniu, bo próżna jest pomoc ludzka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 12, 'W Bogu będziemy mężni, bo on podepcze naszych nieprzyjaciół.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 1, 'Przewodnikowi chóru, na Neginot. Psalm Dawida. Wysłuchaj, Boże, mojego wołania, miej wzgląd na moją modlitwę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 2, 'Z krańców ziemi wołam do ciebie, gdy moje serce jest zatrwożone; wprowadź mnie na skałę, która jest wyższa ode mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 3, 'Ty bowiem jesteś moją ucieczką i wieżą warowną przed wrogiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 4, 'Będę mieszkał w twoim przybytku na wieki, chroniąc się pod osłoną twych skrzydeł. Sela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 5, 'Bo ty, Boże, wysłuchałeś moich ślubów; dałeś dziedzictwo tym, którzy się boją twego imienia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 6, 'Przedłużysz dni króla, jego lata – z pokolenia na pokolenie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 7, 'Będzie trwał na wieki przed Bogiem; przygotuj miłosierdzie i prawdę, niech go strzegą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 8, 'Tak będę śpiewał twemu imieniu na wieki i będę spełniał moje śluby każdego dnia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 1, 'Przewodnikowi chóru, dla Jedutuna. Psalm Dawida. Tylko w Bogu spoczywa moja dusza, od niego pochodzi moje zbawienie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 2, 'Tylko on jest moją skałą i zbawieniem, moją twierdzą; nie zachwieję się za bardzo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 3, 'Jak długo będziecie knuć zło przeciwko człowiekowi? Wy wszyscy będziecie zabici, będziecie jak pochylona ściana i jak walący się mur.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 4, 'Oni tylko naradzają się, jak go strącić z dostojeństwa; mają upodobanie w kłamstwie, ustami swymi błogosławią, ale w sercu złorzeczą. Sela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 5, 'Tylko w Bogu spocznij, moja duszo, bo od niego pochodzi moja nadzieja.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 6, 'On jedynie jest moją skałą i zbawieniem, moją twierdzą; nie zachwieję się.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 7, 'W Bogu moje wybawienie i moja chwała; skała mojej mocy, moja ucieczka jest w Bogu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 8, 'Ufajcie mu w każdym czasie, o narody, wylewajcie przed nim wasze serca; Bóg jest naszą ucieczką. Sela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 9, 'Doprawdy synowie ludzcy są marnością, synowie mocarzy – zawodni; położeni na wagę, wszyscy razem są lżejsi niż marność.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 10, 'Nie pokładajcie ufności w ucisku ani nie łudźcie się grabieżą; jeśli przybędzie wam bogactw, nie przywiązujcie do nich serca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 11, 'Bóg raz przemówił, dwa razy to słyszałem, że moc należy do Boga;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 12, 'I do ciebie, Panie, należy miłosierdzie, bo ty oddajesz każdemu według jego uczynków.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 1, 'Psalm Dawida, gdy przebywał na Pustyni Judzkiej. Boże, ty jesteś moim Bogiem, od rana cię szukam; pragnie ciebie moja dusza, tęskni do ciebie moje ciało w ziemi suchej i spragnionej, w której nie ma wody;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 2, 'Abym widział twoją moc i chwałę tak, jak cię ujrzałem w twojej świątyni;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 3, 'Skoro lepsze jest twoje miłosierdzie niż życie, moje wargi będą cię chwaliły;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 4, 'Tak błogosławić cię będę póki żyję, wzniosę swe ręce w imię twoje.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 5, 'Jak tłuszczem i sadłem będzie nasycona moja dusza, moje usta będą cię wielbić radosnymi wargami;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 6, 'Gdy cię wspominam na moim posłaniu i rozmyślam o tobie podczas nocnych straży.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 7, 'Ponieważ byłeś mi pomocą, w cieniu twoich skrzydeł będę się weselił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 8, 'Moja dusza przylgnęła do ciebie, twoja prawica mnie podtrzymuje.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 9, 'Ale ci, którzy dążą do zguby mojej duszy, sami zejdą do głębi ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 10, 'Będą wydani pod ostrze miecza, staną się łupem lisów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 11, 'Lecz król będzie się weselił w Bogu, będzie się chlubił każdy, kto na niego przysięga, a usta kłamców zostaną zamknięte.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 1, 'Przewodnikowi chóru. Psalm Dawida. Wysłuchaj, o Boże, mego głosu, gdy się modlę; zachowaj moje życie od strachu przed wrogiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 2, 'Ukryj mnie przed tajemną radą złoczyńców, przed zgrają czyniących nieprawość;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 3, 'Którzy naostrzyli swój język jak miecz, nałożyli swoje strzały, słowa jadowite;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 4, 'Aby strzelać z ukrycia w niewinnego; strzelają znienacka i nikogo się nie boją.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 5, 'Utwierdzają się w złym zamiarze, zmawiają się, jak ukryć pułapki, i mówią: Któż je zobaczy?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 6, 'Szukają nieprawości, starannie jej poszukują; ich wnętrze i serce są głębokie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 7, 'Ale Bóg wypuści na nich strzałę, nagle odniosą rany;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 8, 'Własny język doprowadzi ich do upadku; wszyscy, którzy ich zobaczą, uciekną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 9, 'I zlękną się wszyscy ludzie, będą opowiadali o dziele Boga i zrozumieją jego czyny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 10, 'A sprawiedliwy będzie się weselić w Panu i będzie mu ufał; i będą się chlubili wszyscy prawego serca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 1, 'Przewodnikowi chóru. Psalm i pieśń Dawida. Tobie, Boże, należy się chwała na Syjonie i tobie złożone śluby należy wypełnić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 2, 'Ty wysłuchujesz modlitwy, dlatego do ciebie przyjdzie wszelkie ciało.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 3, 'Wielkie nieprawości wzięły górę nad nami; ty oczyszczasz nasze występki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 4, 'Błogosławiony, kogo ty wybierasz i przyjmujesz, aby mieszkał w twoich przedsionkach; będziemy nasyceni dobrami twego domu, twej świętej świątyni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 5, 'Straszliwymi rzeczami odpowiesz nam według sprawiedliwości, Boże naszego zbawienia, nadziejo wszystkich krańców ziemi i mórz dalekich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 6, 'Ty, który utwierdzasz góry swoją mocą, przepasany potęgą;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 7, 'Ty, który uciszasz szum morza, szum jego fal, i wrzawę narodów;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 8, 'Mieszkańcy krańców ziemi boją się twoich znaków; ty radujesz ich nastawaniem poranka i wieczora.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 9, 'Nawiedzasz ziemię i zraszasz ją, wzbogacasz ją obficie strumieniem Bożym pełnym wody. Przygotowujesz im zboże, gdy tak przysposabiasz ziemię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 10, 'Nawadniasz jej zagony, wyrównujesz jej bruzdy, zmiękczasz ją deszczami i błogosławisz jej urodzaje.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 11, 'Wieńczysz rok swoją dobrocią, a twoje ścieżki ociekają tłuszczem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 12, 'Skrapiasz pustynne pastwiska, a pagórki przepasują się radością.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 13, 'Łąki przyodziewają się stadami, a doliny okrywają się zbożem; wykrzykują radośnie i śpiewają.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 1, 'Przewodnikowi chóru. Pieśń i psalm. Radośnie wykrzykujcie Bogu, wszystkie ziemie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 2, 'Wyśpiewujcie chwałę jego imienia, oddawajcie mu chwalebną cześć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 3, 'Powiedzcie Bogu: Jak straszliwe są twe dzieła! Z powodu twojej wielkiej mocy poddadzą się twoi wrogowie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 4, 'Cała ziemia odda ci pokłon i śpiewać ci będzie; śpiewać będzie twemu imieniu. Sela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 5, 'Chodźcie, zobaczcie dzieła Boże, straszliwe są jego dzieła pośród synów ludzkich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 6, 'Zamienił morze w suchą ziemię, pieszo przeszli przez rzekę; tam się nim weseliliśmy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 7, 'Panuje w swej mocy na wieki, jego oczy patrzą na narody, buntownicy nie wywyższą się. Sela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 8, 'Błogosławcie, narody, naszego Boga i rozgłaszajcie jego chwałę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 9, 'Zachował przy życiu naszą duszę i nie dał się zachwiać naszej nodze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 10, 'Doświadczyłeś nas bowiem, Boże, wypróbowałeś nas ogniem, jak srebro jest oczyszczone.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 11, 'Zaprowadziłeś nas w sidła, włożyłeś ucisk na nasze biodra.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 12, 'Pozwoliłeś ludziom deptać nam po głowach, przeszliśmy przez ogień i wodę, ale nas wyprowadziłeś na miejsce obfitości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 13, 'Dlatego wejdę do twego domu z całopaleniem i wypełnię śluby;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 14, 'Które wyraziły moje wargi i wypowiedziały moje usta w utrapieniu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 15, 'Będę ci składał w ofierze całopalenia z tłustych zwierząt wraz z wonnością baranów, ofiaruję ci woły i kozły. Sela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 16, 'Chodźcie, słuchajcie, wszyscy, którzy się boicie Boga, a opowiem, co uczynił dla mojej duszy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 17, 'Do niego wołałem moimi ustami i wychwalałem go moim językiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 18, 'Gdybym zważał na nieprawość w swoim sercu, Pan by mnie nie wysłuchał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 19, 'A jednak Bóg wysłuchał, przychylił się do głosu mojej modlitwy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 20, 'Błogosławiony Bóg, który nie odrzucił mojej modlitwy i nie odebrał mi swego miłosierdzia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 1, 'Przewodnikowi chóru, na Neginot. Psalm i pieśń. Niech Bóg się zmiłuje nad nami i błogosławi nam, niech rozjaśni nad nami swoje oblicze. Sela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 2, 'Aby poznano na ziemi twoją drogę, wśród wszystkich narodów twoje zbawienie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 3, 'Niech cię wysławiają ludy, o Boże, niech cię wysławiają wszystkie ludy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 4, 'Niech narody się radują i wykrzykują, bo ty będziesz sądził ludy sprawiedliwie i rządzić będziesz narodami na ziemi. Sela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 5, 'Niech cię wysławiają ludy, o Boże, niech cię wysławiają wszystkie ludy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 6, 'Wtedy ziemia wyda swój plon i Bóg, nasz Bóg, będzie nam błogosławić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 7, 'Niech nam Bóg błogosławi i niech się go boją wszystkie krańce ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 1, 'Przewodnikowi chóru. Psalm i pieśń Dawida. Niech Bóg powstanie, a rozproszeni będą jego wrogowie; niech pouciekają przed jego obliczem ci, którzy go nienawidzą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 2, 'Jak dym jest rozwiany, tak ich rozpędzisz; jak wosk się rozpływa od ognia, tak niegodziwi poginą przed obliczem Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 3, 'A sprawiedliwi będą się weselić i cieszyć przed obliczem Boga, i będą się radować niezmiernie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 4, 'Śpiewajcie Bogu, śpiewajcie psalmy jego imieniu, wywyższajcie tego, który przemierza niebiosa; Pan to jego imię, radujcie się przed jego obliczem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 5, 'Ojcem dla sierot i sędzią dla wdów jest Bóg w swym świętym przybytku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 6, 'Bóg samotnym daje dom, więźniów uwalnia z oków, ale oporni mieszkają w suchej ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 7, 'Boże, gdy wyruszałeś przed swoim ludem, gdy kroczyłeś przez pustynię. Sela;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 8, 'Ziemia się trzęsła, a niebiosa rozpływały się przed obliczem Boga i sama góra Synaj zadrżała przed obliczem Boga, Boga Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 9, 'Zesłałeś obfity deszcz, Boże, otrzeźwiłeś swoje dziedzictwo, gdy omdlewało.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 10, 'Twoje zastępy mieszkają w nim; ty, Boże, w swojej dobroci przygotowałeś je dla ubogiego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 11, 'Pan dał swoje słowo, wielki był zastęp zwiastujących dobre wieści.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 12, 'Królowie wojsk uciekali, uciekali; a ta, która doglądała domu, dzieliła łupy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 13, 'Chociaż musieliście leżeć wśród kotłów, będziecie jak skrzydła gołębicy pokryte srebrem, a jej pióra żółtym złotem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 14, 'Gdy Wszechmogący rozproszył królów w ziemi, była biała jak śnieg na górze Salmon.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 15, 'Góra Boża jest jak góra Baszanu, wzgórze wysokie, jak góra Baszanu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 16, 'Dlaczego wyskakujecie, wzgórza wysokie? Na tej górze spodobało się Bogu mieszkać, tam Pan będzie mieszkał na wieki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 17, 'Rydwanów Bożych jest dwadzieścia tysięcy, wiele tysięcy aniołów; Pan przebywa wśród nich w świątyni, jak na Synaju.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 18, 'Wstąpiłeś na wysokość, poprowadziłeś pojmanych jeńców, przyjąłeś dary dla ludzi, nawet dla buntowników, aby Pan Bóg mógł z nimi zamieszkać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 19, 'Błogosławiony Pan; codziennie obsypuje nas swymi dobrami Bóg naszego zbawienia. Sela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 20, 'Nasz Bóg jest Bogiem zbawienia, Pan Bóg wybawia od śmierci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 21, 'Bóg zrani głowę swoich wrogów i owłosioną czaszkę tego, który trwa w swoich grzechach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 22, 'Pan powiedział: Wyprowadzę znów swoich z Baszanu, wyprowadzę ich znowu z głębin morskich;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 23, 'Aby twoja stopa była skąpana we krwi, a język twoich psów we krwi wrogów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 24, 'Widzieli twoje pochody, Boże; pochody mego Boga, mego Króla w świątyni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 25, 'Przodem szli śpiewacy, za nimi grający na instrumentach, wśród nich dziewczęta uderzające w bębenki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 26, 'W zgromadzeniach błogosławcie Boga, Pana, wy, którzy pochodzicie ze źródła Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 27, 'Tam jest mały Beniamin, który im przewodzi, władcy Judy i ich hufce, władcy Zebulona i władcy Neftalego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 28, 'Twój Bóg obdarzył cię siłą; umocnij, Boże, to, co dla nas uczyniłeś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 29, 'Ze względu na twoją świątynię w Jeruzalem królowie będą przynosić ci dary.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 30, 'Zgrom rzeszę kopijników, stado byków z cielcami ludu, chlubiących się kawałkiem srebra; rozprosz narody pragnące wojny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 31, 'Przyjdą dostojnicy z Egiptu; Etiopia szybko wyciągnie swe ręce do Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 32, 'Śpiewajcie Bogu, królestwa ziemi, wysławiajcie Pana. Sela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 33, 'Temu, który przemierza najwyższe niebiosa odwieczne; oto wydaje swój głos, głos potężny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 34, 'Uznajcie moc Boga, jego majestat jest nad Izraelem i jego moc w obłokach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 35, 'Groźny jesteś, Boże, ze swych świętych przybytków; Bóg Izraela sam daje moc i siłę swemu ludowi. Niech będzie Bóg błogosławiony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 1, 'Przewodnikowi chóru, na Sosannim. Psalm Dawida. Wybaw mnie, Boże, bo wody sięgają aż do mojej duszy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 2, 'Grzęznę w głębokim błocie, gdzie nie ma dna; dostałem się w głębokie wody i nurt mnie porywa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 3, 'Zmęczyłem się wołaniem, wyschło mi gardło; słabną moje oczy, gdy czekam na mojego Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 4, 'Więcej niż włosów na mojej głowie jest tych, którzy mnie nienawidzą bez powodu; ci, którzy niesłusznie są moimi wrogami i chcą mnie zniszczyć, wzmocnili się; musiałem zapłacić za to, czego nie zabrałem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 5, 'Boże, ty znasz moją głupotę, a moje grzechy nie są ukryte przed tobą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 6, 'Niech nie zaznają wstydu z mego powodu ci, którzy ciebie oczekują, Panie Boże zastępów, niech nie rumienią się z mego powodu ci, którzy ciebie szukają, Boże Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 7, 'Bo dla ciebie znoszę urąganie, hańba okrywa moją twarz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 8, 'Stałem się obcy dla moich braci i cudzoziemcem dla synów mojej matki;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 9, 'Bo gorliwość o twój dom zżarła mnie i spadły na mnie urągania urągających tobie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 10, 'Płakałem i umartwiałem postem swą duszę, a stało się to moją hańbą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 11, 'Założyłem wór pokutny jako szatę i stałem się dla nich pośmiewiskiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 12, 'Mówili o mnie ci, którzy siedzą w bramie, i byłem tematem pieśni pijaków.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 13, 'Ale ja kieruję swoją modlitwę do ciebie, Panie, w czasie pomyślnym; Boże, wysłuchaj mnie według twego wielkiego miłosierdzia, dla prawdy twego zbawienia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 14, 'Uwolnij mnie z błota, abym nie ugrzązł; ocal mnie od tych, którzy mnie nienawidzą, i z głębokich wód.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 15, 'Niech nie zaleją mnie wezbrane wody ani nie pożre głębia i niech otchłań nie zamknie nade mną swej paszczy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 16, 'Wysłuchaj mnie, Panie, bo dobre jest twoje miłosierdzie, według twojej wielkiej litości spójrz na mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 17, 'Nie zakrywaj twego oblicza przed swoim sługą, bo jestem w utrapieniu; wysłuchaj mnie czym prędzej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 18, 'Zbliż się do mojej duszy i wybaw ją, odkup mnie ze względu na mych wrogów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 19, 'Ty znasz moją hańbę, mój wstyd i niesławę, przed tobą są wszyscy moi wrogowie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 20, 'Hańba złamała moje serce, ogarnęło mnie przygnębienie; oczekiwałem współczującego, ale go nie było; szukałem pocieszającego, ale nie znalazłem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 21, 'Zamiast pokarmu podali mi żółć, a gdy pragnąłem, napoili mnie octem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 22, 'Niech ich stół stanie się dla nich sidłem, a ich pomyślność – pułapką.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 23, 'Niech zaćmią się ich oczy, aby nie widzieli, a ich biodra niech się zawsze chwieją.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 24, 'Wylej na nich swoje oburzenie, a żar twego gniewu niech ich dosięgnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 25, 'Niech ich dom opustoszeje, w ich namiotach niech nikt nie mieszka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 26, 'Bo prześladują tego, którego ty uderzyłeś, i rozpowiadają o boleściach tych, których zraniłeś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 27, 'Dodaj nieprawość do ich nieprawości i niech nie dostąpią twojej sprawiedliwości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 28, 'Niech będą wymazani z księgi żyjących i niech nie będą zapisani ze sprawiedliwymi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 29, 'Ja zaś jestem strapiony i zbolały; niech twoje zbawienie, Boże, podniesie mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 30, 'Będę chwalił imię Boga pieśnią, będę go wywyższał dziękczynieniem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 31, 'I będzie to milsze Panu niż wół albo cielec rogaty z kopytami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 32, 'Pokorni to ujrzą i rozradują się, ożyje serce szukających Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 33, 'Pan bowiem wysłuchuje ubogich i swymi więźniami nie gardzi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 34, 'Niech go chwalą niebiosa i ziemia, morze i wszystko, co się w nich porusza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 35, 'Bóg bowiem wybawi Syjon i odbuduje miasta Judy; będą tam mieszkać i posiądą tę ziemię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 36, 'Także i potomstwo jego sług ją odziedziczy i zamieszkają w niej ci, którzy miłują jego imię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 1, 'Przewodnikowi chóru. Psalm Dawida dla przypomnienia. Boże, racz mnie ocalić; Panie, pospiesz mi na pomoc.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 2, 'Niech się zawstydzą i okryją hańbą ci, którzy czyhają na moją duszę; niech się cofną ze wstydem ci, którzy mi źle życzą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 3, 'Niech się cofną wskutek swej hańby ci, którzy mi mówią: Ha, ha!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 4, 'Niech się weselą i radują w tobie wszyscy, którzy cię szukają; niech ci, którzy miłują twoje zbawienie, mówią zawsze: Niech Bóg będzie wywyższony!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 5, 'Ja zaś jestem nędzny i ubogi, Boże, pospiesz ku mnie, ty jesteś moją pomocą i wybawicielem; Panie, nie zwlekaj.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 1, 'W tobie, Panie, pokładam ufność, niech nigdy nie będę zawstydzony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 2, 'Według swej sprawiedliwości ocal mnie i wyzwól; nakłoń ku mnie ucha i wybaw mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 3, 'Bądź mi skałą schronienia, gdzie zawsze mogę uciec; przykazałeś, aby mnie wybawiono, bo ty jesteś moją skałą i twierdzą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 4, 'Mój Boże, wyzwól mnie z ręki niegodziwego, z ręki przewrotnego i ciemiężyciela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 5, 'Ty bowiem jesteś moją nadzieją, Panie Boże, moją ufnością od młodości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 6, 'Ty byłeś moją podporą od narodzin, ty mnie wyprowadziłeś z łona mojej matki; w tobie zawsze będzie moja chwała.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 7, 'Dla wielu jestem jakby cudem, lecz ty jesteś moim potężnym schronieniem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 8, 'Niech moje usta będą pełne twojej chwały, twojej sławy przez cały dzień.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 9, 'Nie odrzucaj mnie w czasie starości; gdy ustanie moja siła, nie opuszczaj mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 10, 'Moi wrogowie bowiem mówili przeciwko mnie, a ci, którzy czyhają na moją duszę, wspólnie się naradzają;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 11, 'Mówiąc: Bóg go opuścił, gońcie go i schwytajcie, bo nie ma nikogo, kto by go ocalił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 12, 'Boże, nie oddalaj się ode mnie; mój Boże, pospiesz mi na pomoc.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 13, 'Niech się zawstydzą i zginą przeciwnicy mojej duszy, niech się okryją hańbą i wstydem ci, którzy szukają mego nieszczęścia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 14, 'Ja zaś zawsze będę ufał i jeszcze bardziej pomnożę twoją chwałę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 15, 'Moje usta głosić będą twoją sprawiedliwość i twoje zbawienie przez cały dzień, choć nie znam ich miary.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 16, 'Pójdę w wielkiej mocy Pana Boga, będę wspominał tylko twoją sprawiedliwość.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 17, 'Boże, uczyłeś mnie od mojej młodości i dotąd głoszę twoje cudowne dzieła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 18, 'Dlatego i w starości, gdy będę już siwy, nie opuszczaj mnie, Boże, aż opowiem o twojej mocy temu pokoleniu i wszystkim potomkom o twojej potędze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 19, 'Twoja sprawiedliwość, Boże, jest wywyższona, czynisz wielkie rzeczy; Boże, któż jest podobny do ciebie?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 20, 'Zesłałeś na mnie wielkie i ciężkie utrapienia, lecz znowu przywrócisz mi życie i z głębi ziemi znów mnie wydobędziesz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 21, 'Pomnożysz moje dostojeństwo i znowu mnie pocieszysz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 22, 'A ja na instrumentach muzycznych będę wysławiać ciebie i twoją prawdę, mój Boże; będę ci śpiewał z harfą, Święty Izraela!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 23, 'Rozradują się moje wargi, gdy będę ci śpiewał, i moja dusza, którą odkupiłeś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 24, 'Również mój język będzie głosił przez cały dzień twoją sprawiedliwość, bo okryli się wstydem i hańbą ci, którzy szukali mego nieszczęścia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 1, 'Psalm dla Salomona. Boże, daj królowi swoje sądy i swoją sprawiedliwość synowi króla;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 2, 'Będzie sądził twój lud w sprawiedliwości, a twoich ubogich w prawości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 3, 'Góry przyniosą ludowi pokój, a pagórki sprawiedliwość.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 4, 'Będzie sądził ubogich z ludu, wybawi synów potrzebującego, a zgniecie ciemiężyciela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 5, 'Będą się bać ciebie, póki trwać będzie słońce i księżyc, z pokolenia na pokolenie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 6, 'Zstąpi jak deszcz na skoszoną trawę, jak krople deszczu nawadniające ziemię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 7, 'Za jego dni zakwitnie sprawiedliwy i będzie obfitość pokoju, dopóki księżyc trwa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 8, 'Będzie panował od morza do morza, od rzeki aż po krańce ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 9, 'Przed nim upadną mieszkańcy pustyni, a jego wrogowie będą proch lizać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 10, 'Królowie Tarszisz i wysp przyniosą dary, królowie Szeby i Saby złożą daninę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 11, 'I oddadzą mu pokłon wszyscy królowie; wszystkie narody będą mu służyć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 12, 'Ocali bowiem ubogiego, gdy zawoła, i nędznego, który nie ma pomocnika.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 13, 'Zmiłuje się nad ubogim i potrzebującym i wybawi dusze nędzarzy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 14, 'Wybawi ich dusze od podstępu i przemocy, bo ich krew jest cenna w jego oczach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 15, 'I będzie żył, i dadzą mu złoto z Szeby; nieustannie będą się za niego modlić i codziennie mu błogosławić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 16, 'Gdy się zasieje garść zboża w ziemi na szczytach gór, jego plon zaszumi jak Liban, a mieszkańcy miast zakwitną jak polna trawa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 17, 'Jego imię trwać będzie na wieki; póki słońce trwa, trwać będzie jego imię; ludzie będą błogosławieni w nim, a wszystkie narody nazwą go błogosławionym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 18, 'Błogosławiony niech będzie Pan Bóg, Bóg Izraela, który sam jeden czyni cuda.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 19, 'I błogosławione na wieki jego chwalebne imię; niech cała ziemia będzie napełniona jego chwałą. Amen, amen.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 20, 'I tu się kończą modlitwy Dawida, syna Jessego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 1, 'Psalm Asafa. Doprawdy Bóg jest dobry dla Izraela; dla tych, którzy są czystego serca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 2, 'Ale moje nogi niemal się potknęły, moje kroki omal się nie zachwiały;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 3, 'Bo zazdrościłem głupcom, widząc pomyślność niegodziwych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 4, 'Nie mają bowiem więzów aż do śmierci, ale w całości zostaje ich siła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 5, 'Nie doznają trudu ludzkiego ani cierpień jak inni ludzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 6, 'Dlatego są opasani pychą jak złotym łańcuchem i odziani w okrucieństwo jak w szatę ozdobną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 7, 'Ich oczy wystają od tłuszczu; mają więcej niż serce mogłoby sobie życzyć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 8, 'Oddali się rozpuście i mówią przewrotnie o ucisku, mówią wyniośle.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 9, 'Zwracają swe usta przeciwko niebu, a ich język krąży po ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 10, 'Dlatego jego lud wraca dotąd i obficie leją się na nich wody;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 11, 'Bo mówią: Jakże Bóg może o tym wiedzieć? Czy Najwyższy ma wiedzę?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 12, 'Oto ci są niegodziwi, a powodzi im się na świecie i pomnażają bogactwa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 13, 'A więc na próżno oczyściłem swoje serce i w niewinności obmywałem ręce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 14, 'Cały dzień bowiem znoszę cierpienia i co rano jestem chłostany.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 15, 'Gdybym powiedział: Będę mówił tak samo, skrzywdziłbym ród twoich synów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 16, 'Starałem się to rozumieć, ale było dla mnie zbyt trudne;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 17, 'Aż wszedłem do świątyni Bożej i tu zrozumiałem, jaki jest ich koniec.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 18, 'Doprawdy na śliskich miejscach ich postawiłeś i strącasz ich na zatracenie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 19, 'Oto jak doznali zguby! Nagle niszczeją, strawieni przerażeniem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 20, 'Jak sen po przebudzeniu, Panie, gdy się ockniesz, wzgardzisz ich obrazem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 21, 'Gdy gorycz miałem w sercu, a w nerkach czułem kłucie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 22, 'Byłem głupi i nic nie rozumiałem, byłem przed tobą jak zwierzę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 23, 'A jednak zawsze jestem z tobą, bo mnie trzymałeś za prawą rękę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 24, 'Poprowadzisz mnie według swej rady, a potem przyjmiesz mnie do chwały.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 25, 'Kogo innego mam w niebie? I na ziemi oprócz ciebie w nikim innym nie mam upodobania.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 26, 'Choć moje ciało i serce ustanie, Bóg jest skałą mego serca i moim dziedzictwem na wieki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 27, 'Oto bowiem ci, którzy się oddalają od ciebie, zginą; wytracasz tych, którzy cudzołożą, odstępując od ciebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 28, 'Mnie zaś dobrze jest zbliżyć się do Boga; pokładam w Panu Bogu moją ufność, aby opowiadać wszystkie jego dzieła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 1, 'Pieśń pouczająca. Asafa. Boże, dlaczego odrzuciłeś nas na zawsze? Czemu płonie twój gniew przeciwko owcom twego pastwiska?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 2, 'Wspomnij na swoje zgromadzenie, które dawno nabyłeś; na szczep twego dziedzictwa, który odkupiłeś; na górę Syjon, na której mieszkasz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 3, 'Pospiesz na miejsce ciągłych spustoszeń; o, jak wróg zburzył wszystko w świątyni!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 4, 'Ryknęli twoi wrogowie pośrodku twego zgromadzenia, a na znak zatknęli swoje sztandary.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 5, 'Za sławnego uważano tego, który wznosił wysoko siekierę na gęste drzewo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 6, 'A teraz już jego rzeźby rąbią siekierami i młotami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 7, 'Oddali na pastwę ognia twoją świątynię i obaliwszy na ziemię, zbezcześcili przybytek twego imienia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 8, 'Mówili w swym sercu: Zburzmy ich razem! Spalili wszystkie miejsca zgromadzeń Bożych na ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 9, 'Nie widzimy naszych znaków; już nie ma proroka i nikt spośród nas nie wie, jak długo to ma trwać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 10, 'Jak długo, Boże, przeciwnik będzie urągać? Czy wróg będzie wiecznie bluźnił przeciwko twemu imieniu?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 11, 'Dlaczego cofasz swoją rękę i swojej prawicy z zanadrza nie wyjmujesz?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 12, 'Przecież ty, Boże, jesteś moim Królem od dawna, ty dokonujesz zbawienia na ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 13, 'Ty swoją mocą rozdzieliłeś morze, zmiażdżyłeś głowy smoków w wodach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 14, 'Ty skruszyłeś głowy Lewiatana, dałeś go na pokarm mieszkańcom pustyni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 15, 'Ty rozszczepiłeś źródła i potoki, ty osuszyłeś potężne rzeki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 16, 'Twój jest dzień, twoja i noc, ty ustanowiłeś światło i słońce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 17, 'Ty wyznaczyłeś wszystkie granice ziemi, ty ustanowiłeś lato i zimę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 18, 'Pamiętaj o tym, że wróg zelżył ciebie, Panie, a głupi lud urągał twemu imieniu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 19, 'Nie wydawaj tej zgrai duszy twojej synogarlicy, nie zapominaj nigdy o stadku twoich ubogich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 20, 'Zważ na twoje przymierze, bo ciemne zakątki ziemi pełne są siedlisk przemocy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 21, 'Niech uciśniony nie wraca ze wstydem, niech ubogi i potrzebujący chwali twoje imię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 22, 'Powstań, Boże, broń swojej sprawy; pamiętaj o zniewadze, którą co dzień wyrządza ci głupiec.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 23, 'Nie zapominaj krzyku twoich wrogów, wciąż rosnącej wrzawy tych, którzy powstają przeciwko tobie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 1, 'Przewodnikowi chóru. Al taszchet. Psalm i pieśń Asafa. Wysławiamy cię, Boże, wysławiamy, bo bliskie twoje imię; opowiadają to twoje cudowne dzieła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 2, 'Gdy wyznaczę czas, będę sądzić sprawiedliwie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 3, 'Roztopiła się ziemia i wszyscy jej mieszkańcy, ale ja umacniam jej filary. Sela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 4, 'Powiedziałem głupcom: Nie szalejcie, a niegodziwym: Nie podnoście rogu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 5, 'Nie podnoście wysoko swego rogu i nie mówcie wyniośle;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 6, 'Bo nie ze wschodu ani z zachodu, ani z południa przychodzi wywyższenie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 7, 'Lecz Bóg jest sędzią; tego poniża, a tamtego wywyższa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 8, 'W ręku Pana bowiem jest kielich mętnego wina, pełnego przypraw; z niego nalewa tak, że wszyscy niegodziwi ziemi wycisną nawet męty i wypiją je.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 9, 'Ja zaś będę zawsze opowiadał, będę śpiewał Bogu Jakuba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 10, 'I połamię wszystkie rogi niegodziwych, a rogi sprawiedliwego będą wzniesione.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 1, 'Przewodnikowi chóru, na Neginot. Psalm i pieśń Asafa. Bóg znany jest w Judzie, jego imię jest wielkie w Izraelu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 2, 'W Salem jest jego przybytek, a jego mieszkanie na Syjonie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 3, 'Tam połamał ogniste strzały łuku, tarczę i miecz i położył kres bitwie. Sela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 4, 'Wspanialszy jesteś i dostojniejszy niż góry zdobyczy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 5, 'Odważni stali się łupem, pogrążyli się we śnie, mężni nie znaleźli siły w swych rękach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 6, 'Od twego gromienia, Boże Jakuba, mocno zasnęły wozy i konie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 7, 'Ty, ty sam, jesteś straszliwy; i któż się ostoi przed twoim obliczem, gdy się rozgniewasz?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 8, 'Z nieba dajesz słyszeć swój wyrok, ziemia się zlękła i zamilkła;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 9, 'Gdy Bóg powstał na sąd, aby wybawić wszystkich pokornych na ziemi. Sela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 10, 'Doprawdy nawet gniew człowieka będzie cię chwalić, a ty resztkę tego gniewu powstrzymasz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 11, 'Składajcie śluby i wypełniajcie je wobec Pana, waszego Boga; wszyscy otaczający go, przynoście dary temu, który napawa strachem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 12, 'On zabierze ducha książąt, on wzbudza strach u królów ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 1, 'Przewodnikowi chóru dla Jedutuna. Psalm Asafa. Wzniosłem swój głos do Boga i zawołałem; wzniosłem swój głos do Boga i mnie wysłuchał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 2, 'W dniu mego utrapienia szukałem Pana, moje ręce wyciągałem w nocy nieustannie, moja dusza nie dała się pocieszyć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 3, 'Gdy wspominałem Boga, byłem strwożony; rozmyślałem, a mój duch był ogarnięty utrapieniem. Sela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 4, 'Ty zatrzymujesz otwarte powieki mych oczu, jestem tak zaniepokojony, że nie potrafię mówić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 5, 'Rozpamiętuję dni przeszłe i dawne lata.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 6, 'Przypominam sobie mój śpiew; nocą rozmyślam w sercu i mój duch docieka:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 7, 'Czy Pan odrzuci na wieki i już więcej nie okaże łaski?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 8, 'Czy jego miłosierdzie ustało na zawsze i jego obietnica nigdy się nie spełni?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 9, 'Czy Bóg zapomniał o litości? Czy w gniewie stłumił swoją łaskawość? Sela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 10, 'I powiedziałem: To jest moja niemoc; jednak będę wspominał lata prawicy Najwyższego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 11, 'Będę wspominał dzieła Pana, będę wspominał twoje dawne cuda.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 12, 'Będę rozmyślał o wszystkich twoich dziełach i o twoich czynach będę mówił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 13, 'Boże, święta jest twoja droga; który bóg jest tak wielki, jak nasz Bóg?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 14, 'Ty jesteś Bogiem, który czyni cuda; dałeś poznać narodom swoją moc.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 15, 'Odkupiłeś swoim ramieniem twój lud, synów Jakuba i Józefa. Sela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 16, 'Widziały cię wody, o Boże, widziały cię wody i ulękły się, poruszyły się głębiny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 17, 'Chmury spłynęły wodą, niebiosa wydały gromy i poleciały twoje strzały.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 18, 'Huk twego grzmotu wśród obłoków, błyskawice oświetliły świat, ziemia poruszyła się i zatrzęsła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 19, 'Twoja droga wiodła przez morze, twoje ścieżki przez wielkie wody i nie było znać twoich śladów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 20, 'Prowadziłeś swój lud jak stado owiec ręką Mojżesza i Aarona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 1, 'Pieśń pouczająca. Asafa. Słuchaj, mój ludu, mego prawa, nakłońcie uszu ku słowom moich ust.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 2, 'Otworzę moje usta do przypowieści, opowiem starodawne tajemnice;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 3, 'Cośmy słyszeli i poznali i co nam opowiadali nasi ojcowie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 4, 'Nie zataimy tego przed ich synami, opowiemy przyszłemu pokoleniu o chwale Pana, o jego mocy i cudach, które czynił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 5, 'Ustanowił bowiem świadectwo w Jakubie, nadał prawo w Izraelu i nakazał naszym ojcom, aby je oznajmiali swoim synom;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 6, 'Aby poznało przyszłe pokolenie, synowie, którzy się urodzą; aby powstawszy, przekazywali je swoim synom;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 7, 'Żeby pokładali w Bogu nadzieję i nie zapominali o dziełach Boga, lecz strzegli jego przykazań;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 8, 'Żeby nie byli, jak ich ojcowie, pokoleniem opornym i nieposłusznym; pokoleniem, które nie przygotowało swego serca i którego duch nie był wierny Bogu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 9, 'Synowie Efraima, uzbrojeni i wyposażeni w łuki, w dniu bitwy wycofali się.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 10, 'Bo nie strzegli przymierza Boga i nie chcieli postępować według jego prawa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 11, 'Zapomnieli o jego dziełach i cudach, które im ukazał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 12, 'Przed ich ojcami czynił cuda w ziemi Egiptu, na polu Soanu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 13, 'Rozdzielił morze i przeprowadził ich, i sprawił, że wody stanęły jak wał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 14, 'Prowadził ich w obłoku za dnia, a całą noc w blasku ognia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 15, 'Rozszczepił skały na pustyni i napoił ich jakby z wielkich głębin.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 16, 'Wydobył strumienie ze skały i sprawił, że wody płynęły jak rzeki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 17, 'Lecz oni jeszcze więcej grzeszyli przeciwko niemu i pobudzili do gniewu Najwyższego na pustyni;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 18, 'I wystawiali Boga na próbę w swych sercach, żądając pokarmu według swego pragnienia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 19, 'I mówili przeciwko Bogu tymi słowy: Czy Bóg może zastawić stół na tej pustyni?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 20, 'Oto uderzył w skałę i wypłynęły wody, i wezbrały strumienie; czy będzie mógł też dać chleb? Czy przygotuje mięso swemu ludowi?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 21, 'Gdy Pan to usłyszał, rozgniewał się i ogień zapłonął przeciw Jakubowi, i gniew wybuchnął przeciw Izraelowi;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 22, 'Bo nie uwierzyli Bogu i nie zaufali jego zbawieniu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 23, 'Choć rozkazał chmurom w górze i bramy nieba otworzył.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 24, 'I zesłał im jak deszcz mannę do jedzenia, i zboże z nieba im dał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 25, 'Człowiek jadł chleb anielski; zesłał im pokarm do syta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 26, 'Wzbudził na niebie wiatr ze wschodu i sprowadził swą mocą wiatr południowy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 27, 'Zesłał im mięso jak pył i ptactwo skrzydlate jak piasek morski.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 28, 'Spadło ono pośrodku ich obozu, wokół ich namiotów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 29, 'Jedli i w pełni się nasycili; dał im, czego pragnęli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 30, 'A gdy jeszcze nie zaspokoili swego pragnienia, gdy jeszcze pokarm był w ich ustach;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 31, 'Spadł na nich gniew Boży i zabił ich tłustych, a znakomitszych z Izraela powalił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 32, 'Mimo to nadal grzeszyli i nie wierzyli jego cudom;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 33, 'Dlatego sprawił, że ich dni przemijały w marności, a ich lata – w trwodze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 34, 'Gdy ich zabijał, szukali go; nawracali się i o świcie szukali Boga;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 35, 'Przypominali sobie, że Bóg jest ich skałą, że Bóg Najwyższy – ich Odkupicielem;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 36, 'Pochlebiali mu jednak swoimi ustami i okłamywali go swym językiem;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 37, 'A ich serce nie było przed nim szczere i nie byli wierni jego przymierzu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 38, 'On jednak, będąc miłosiernym, przebaczał ich nieprawości i nie wytracał ich; często odwracał swój gniew i nie pobudzał całej swej zapalczywości;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 39, 'Bo pamiętał, że są ciałem; wiatrem, który ulatuje i nie wraca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 40, 'Jak często pobudzali go do gniewu na pustyni i zasmucali go na pustkowiu!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 41, 'Odwracali się i wystawiali Boga na próbę, i stawiali granice Świętemu Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 42, 'Nie pamiętali jego ręki ani dnia, w którym ich wybawił z utrapienia;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 43, 'Gdy czynił swe znaki w Egipcie i swe cuda na polu Soanu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 44, 'Gdy zamienił w krew ich rzeki i ich strumienie, tak że nie mogli z nich pić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 45, 'Zesłał na nich rozmaite muchy, aby ich kąsały, i żaby, aby ich niszczyły;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 46, 'I dał robactwu ich plony, a ich pracę szarańczy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 47, 'Zniszczył gradem ich winorośle, a sykomory szronem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 48, 'Ich bydło wydał na pastwę gradu, a ich stada na pastwę błyskawic.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 49, 'Wylał na nich żar swojego gniewu, zapalczywość, oburzenie i udrękę, zesławszy na nich złych aniołów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 50, 'Otworzył drogę dla swego gniewu, nie zachował ich duszy od śmierci, a ich życie wydał zarazie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 51, 'Wytracił wszystko pierworodne w Egipcie, pierwociny ich mocy w namiotach Chama;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 52, 'Ale swój lud wyprowadził jak owce i wiódł ich po pustyni jak stado.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 53, 'Prowadził ich bezpiecznie, tak że się nie lękali, a ich wrogów przykryło morze;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 54, 'I przyprowadził ich do swej świętej granicy; do góry, którą nabyła jego prawica.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 55, 'Wypędził przed nimi narody, sznurem wyznaczył im dziedzictwo, żeby pokolenia Izraela mieszkały w swoich namiotach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 56, 'Oni jednak wystawiali na próbę i pobudzali do gniewu Boga Najwyższego, i nie strzegli jego świadectw.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 57, 'Lecz odwrócili się i postępowali przewrotnie jak ich ojcowie, schodzili z drogi jak łuk zawodny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 58, 'Pobudzali go bowiem do gniewu przez swe wyżyny i rzeźbionymi posągami wzbudzali jego zazdrość.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 59, 'Gdy Bóg to usłyszał, rozgniewał się i wielce wzgardził Izraelem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 60, 'I opuścił przybytek w Szilo; namiot, który rozbił wśród ludzi;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 61, 'I oddał w niewolę swoją moc i swoją chwałę w ręce wroga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 62, 'Wydał swój lud pod miecz i rozgniewał się na swoje dziedzictwo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 63, 'Ich młodzieńców pochłonął ogień, a ich dziewic nie wydano za mąż.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 64, 'Ich kapłani padli od miecza, a ich wdowy nie lamentowały.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 65, 'Lecz potem Pan ocknął się jak ze snu, jak mocarz wykrzykujący od wina.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 66, 'I uderzył na tyły swoich wrogów, okrył ich wieczną hańbą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 67, 'Ale choć wzgardził namiotem Józefa i pokolenia Efraima nie wybrał;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 68, 'Jednak wybrał pokolenie Judy, górę Syjon, którą umiłował.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 69, 'I zbudował swoją świątynię jak wysoki pałac; jak ziemię, którą ugruntował na wieki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 70, 'Wybrał też Dawida, swego sługę; wziął go z owczych zagród;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 71, 'Przywołał go, gdy chodził za karmiącymi owcami, aby pasł Jakuba, jego lud, i Izraela, jego dziedzictwo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 72, 'A on ich pasł w prawości swego serca i prowadził ich roztropną ręką.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 1, 'Psalm Asafa. Boże, poganie wtargnęli do twego dziedzictwa, splugawili twoją świętą świątynię, Jeruzalem zamienili w ruiny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 2, 'Zwłoki twoich sług dali na żer ptactwu niebieskiemu, ciała twoich świętych bestiom ziemskim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 3, 'Rozlali ich krew jak wodę wokół Jeruzalem i nie było nikogo, kto by ich pogrzebał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 4, 'Staliśmy się hańbą dla naszych sąsiadów, pośmiewiskiem i drwiną dla tych, którzy są wokoło nas.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 5, 'Jak długo, Panie? Czy wiecznie będziesz się gniewać? Czy twoja zapalczywość będzie płonąć jak ogień?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 6, 'Wylej twój gniew na pogan, którzy cię nie znają, i na królestwa, które nie wzywają twego imienia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 7, 'Pożarli bowiem Jakuba i spustoszyli jego mieszkanie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 8, 'Nie pamiętaj nam dawnych nieprawości naszych, niech nas prędko spotka twoje miłosierdzie, bo jesteśmy bardzo wynędzniali.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 9, 'Wspomóż nas, Boże naszego zbawienia, dla chwały imienia twego; ocal nas i przebacz nam grzechy ze względu na twoje imię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 10, 'Dlaczego poganie mają mówić: Gdzież jest ich Bóg? Niech będzie znany wśród pogan na naszych oczach przez dokonanie zemsty za przelaną krew twoich sług.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 11, 'Niech dotrze do ciebie jęk więźniów, według potęgi twego ramienia zachowaj skazanych na śmierć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 12, 'I odpłać naszym sąsiadom siedmiokrotnie w ich zanadrze za zniewagę, którą ci wyrządzili, Panie!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 13, 'My zaś, twój lud i owce twego pastwiska, będziemy cię wielbić na wieki, będziemy głosić twoją chwałę z pokolenia na pokolenie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 1, 'Przewodnikowi chóru, na Sosannim. Psalm świadectwa Asafa. Posłuchaj, Pasterzu Izraela, ty, który prowadzisz Józefa jak stado owiec, ty, który zasiadasz między cherubinami, zabłyśnij.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 2, 'Przed Efraimem, Beniaminem i Manassesem wzbudź swoją moc i przyjdź nas zbawić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 3, 'Boże, odnów nas, rozjaśnij nad nami swoje oblicze, a będziemy wybawieni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 4, 'Panie, Boże zastępów, jak długo będziesz się gniewał na modlitwę swego ludu?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 5, 'Nakarmiłeś ich chlebem płaczu i napoiłeś ich łzami nad miarę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 6, 'Zrobiłeś z nas przedmiot sporu dla naszych sąsiadów, a nasi wrogowie śmieją się z nas.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 7, 'Boże zastępów, odnów nas, rozjaśnij nad nami swoje oblicze, a będziemy wybawieni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 8, 'Ty przeniosłeś winorośl z Egiptu; wygnałeś pogan, a ją zasadziłeś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 9, 'Przygotowałeś jej miejsce i sprawiłeś, że zapuściła korzenie i napełniła ziemię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 10, 'Góry okryły się jej cieniem, a jej gałęzie były jak najwyższe cedry.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 11, 'Wypuścił swe latorośle aż do morza i swoje pędy aż do rzeki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 12, 'Dlaczego więc zburzyłeś jej ogrodzenie, tak że obrywają ją wszyscy, którzy przechodzą drogą?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 13, 'Niszczy ją dzik leśny, a zwierzę polne pożera ją.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 14, 'O Boże zastępów, proszę, powróć, spójrz z nieba i zobacz, nawiedź tę winorośl;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 15, 'Tę winnicę, którą zasadziła twoja prawica, i latorośl, którą umocniłeś dla siebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 16, 'Spalona jest ogniem i wycięta; giną od zgromienia twojego oblicza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 17, 'Niech twoja ręka będzie nad mężem twojej prawicy, nad synem człowieczym, którego umocniłeś dla siebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 18, 'A my nie odstąpimy od ciebie; zachowaj nas przy życiu, a będziemy wzywać twego imienia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 19, 'Panie, Boże zastępów, odnów nas, rozjaśnij nad nami swoje oblicze, a będziemy wybawieni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 1, 'Przewodnikowi chóru, na Gittyt. Asafa. Radośnie śpiewajcie Bogu, naszej mocy; radośnie wykrzykujcie Bogu Jakuba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 2, 'Weźcie psalm, przynieście bęben, wdzięczną harfę i cytrę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 3, 'Zadmijcie w trąbę w czas nowiu, w czasie wyznaczonym, w dniu naszego uroczystego święta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 4, 'Jest bowiem taki nakaz w Izraelu, prawo Boga Jakuba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 5, 'Ustanowił to świadectwem dla Józefa, kiedy wyszedł przeciw ziemi Egiptu, gdzie słyszałem język, którego nie zrozumiałem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 6, 'Uwolniłem od brzemienia jego barki, a jego ręce od dźwigania kotłów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 7, 'Wzywałeś mnie w ucisku i wybawiłem cię; odpowiedziałem ci w skrytości gromu, doświadczyłem cię u wód Meriba. Sela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 8, 'Słuchaj, mój ludu, a oświadczę ci; Izraelu, jeśli będziesz mnie słuchał;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 9, 'Nie będziesz miał cudzego boga ani nie oddasz pokłonu obcemu bogu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 10, 'Ja, Pan, jestem twoim Bogiem, który cię wyprowadził z ziemi Egiptu; otwórz usta, a ja je napełnię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 11, 'Lecz mój lud nie usłuchał mego głosu, a Izrael nie chciał mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 12, 'Zostawiłem ich więc żądzom ich serca i postępowali według swoich zamysłów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 13, 'O, gdyby mój lud mnie posłuchał, a Izrael chodził moimi drogami!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 14, 'W krótkim czasie poniżyłbym ich nieprzyjaciół i zwróciłbym rękę przeciw ich wrogom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 15, 'Nienawidzący Pana, choć obłudnie, musieliby mu się poddać, a ich czas trwałby wiecznie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 16, 'I karmiłbym ich wyborną pszenicą, a nasyciłbym cię miodem ze skały.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 1, 'Psalm Asafa. Bóg stoi w zgromadzeniu Bożym, pośród bogów sprawuje sąd:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 2, 'Jak długo będziecie sądzić niesprawiedliwie i trzymać stronę niegodziwych? Sela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 3, 'Bierzcie w obronę ubogiego i sierotę, oddajcie sprawiedliwość strapionemu i potrzebującemu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 4, 'Wyzwólcie biedaka i nędzarza, ocalcie go z ręki niegodziwych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 5, 'Lecz oni nic nie wiedzą i nie rozumieją, ciągle chodzą w ciemności; zachwiały się wszystkie fundamenty ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 6, 'Powiedziałem: Jesteście bogami i wszyscy wy jesteście synami Najwyższego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 7, 'Lecz pomrzecie jak inni ludzie i upadniecie jak jeden z książąt.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 8, 'Powstań, Boże, osądź ziemię, bo ty otrzymasz w dziedzictwo wszystkie narody.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 1, 'Pieśń i psalm Asafa. Boże, nie milcz; nie bądź głuchy i bezczynny, Boże!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 2, 'Bo oto burzą się twoi wrogowie, a ci, którzy cię nienawidzą, podnoszą głowę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 3, 'Przeciwko twemu ludowi knują spisek i naradzali się przeciw tym, których ochraniasz;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 4, 'Mówiąc: Chodźcie, wytępmy ich, niech nie będą narodem, żeby więcej nie wspominano imienia Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 5, 'Zmówili się bowiem jednomyślnie, przeciwko tobie zawarli przymierze:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 6, 'Namioty Edomitów i Izmaelitów, Moab i Hagaryci;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 7, 'Gebal, Ammon i Amalek; Filistyni z mieszkańcami Tyru.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 8, 'Także Assur przyłączył się do nich, wsparł swym ramieniem synów Lota. Sela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 9, 'Uczyń im tak, jak Midianitom, jak Syserze, jak Jabinowi nad potokiem Kiszon;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 10, 'Którzy zostali wytępieni w Endor, stali się jak gnój dla ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 11, 'Z ich dostojnikami postąp jak z Orebem i Zeebem, jak z Zebachem i Salmunną, ze wszystkimi ich książętami;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 12, 'Którzy mówili: Weźmy w posiadanie przybytki Boże.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 13, 'Mój Boże, uczyń ich jak koło i jak źdźbło na wietrze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 14, 'Jak ogień, który pali las, i jak płomień, który wypala góry;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 15, 'Tak ty ich ścigaj swoją nawałnicą i swoją burzą zatrwóż ich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 16, 'Okryj ich twarze hańbą, aby szukali twego imienia, Panie!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 17, 'Niech się zawstydzą i zatrwożą na wieki, niech się okryją hańbą i zginą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 18, 'Niech poznają, że jedynie ty, którego imię jest Pan, ty jesteś Najwyższy ponad całą ziemią.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 1, 'Przewodnikowi chóru, na Gittyt. Psalm dla synów Korego. O, jak miłe są twoje przybytki, Panie zastępów!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 2, 'Moja dusza wzdycha i omdlewa z tęsknoty do przedsionków Pana; moje serce i ciało wołają radośnie do Boga żywego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 3, 'Oto nawet wróbel znalazł sobie dom i jaskółka gniazdo, gdzie składa swe pisklęta, u twoich ołtarzy, Panie zastępów, mój Królu i mój Boże!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 4, 'Błogosławieni ci, którzy mieszkają w twoim domu, nieustannie będą cię chwalić. Sela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 5, 'Błogosławiony człowiek, którego siła jest w tobie, w którego sercu są twoje drogi;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 6, 'Ci, którzy przechodząc przez dolinę Baka, zmieniają ją w źródło, a deszcz okrywa ją błogosławieństwem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 7, 'I idą z mocy w moc, i ukażą się przed Bogiem na Syjonie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 8, 'O Panie, Boże zastępów, wysłuchaj mojej modlitwy, nakłoń ucha, Boże Jakuba. Sela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 9, 'Spójrz, Boże, nasza tarczo, i wejrzyj na oblicze twego pomazańca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 10, 'Lepszy bowiem jest jeden dzień w twoich przedsionkach niż tysiąc gdzie indziej; wolę raczej stać w progu domu mego Boga, niż mieszkać w namiotach niegodziwców.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 11, 'Pan Bóg bowiem jest słońcem i tarczą, Pan obdarza łaską i chwałą, nie odmawia dobra tym, którzy postępują nienagannie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 12, 'Panie zastępów, błogosławiony człowiek, który ufa tobie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 1, 'Przewodnikowi chóru. Psalm dla synów Korego. Panie, okazałeś łaskę swej ziemi, przyprowadziłeś z niewoli Jakuba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 2, 'Przebaczyłeś nieprawość twego ludu, zakryłeś wszystkie ich grzechy. Sela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 3, 'Uśmierzyłeś całe swoje zagniewanie, odwróciłeś się od zapalczywości twojego gniewu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 4, 'Odnów nas, Boże naszego zbawienia, i odwróć od nas swój gniew.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 5, 'Czy wiecznie będziesz się na nas gniewać? Czy rozciągniesz swój gniew na wszystkie pokolenia?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 6, 'Czy nie ożywisz nas na nowo, aby twój lud rozradował się w tobie?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 7, 'Panie, okaż nam twoje miłosierdzie i daj nam swoje zbawienie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 8, 'Posłucham, co będzie mówił Bóg, Pan; zaprawdę, ogłosi pokój swojemu ludowi i swoim świętym, aby tylko nie wracali do swojej głupoty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 9, 'Doprawdy jego zbawienie jest blisko tych, którzy się go boją, aby jego chwała zamieszkała w naszej ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 10, 'Miłosierdzie i prawda spotkają się ze sobą, sprawiedliwość i pokój ucałują się.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 11, 'Prawda wyrośnie z ziemi, a sprawiedliwość wyjrzy z nieba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 12, 'Pan też obdarzy tym, co dobre, a nasza ziemia wyda swój plon.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 13, 'Sprawiedliwość przed nim pójdzie i będzie wytyczać drogę jego krokom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 1, 'Modlitwa Dawida. Nakłoń swego ucha, Panie, wysłuchaj mnie, bo jestem nędzny i ubogi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 2, 'Strzeż mojej duszy, bo jestem pobożny; mój Boże, wybaw twego sługę, który ufa tobie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 3, 'Zmiłuj się nade mną, Panie, bo do ciebie codziennie wołam.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 4, 'Rozraduj duszę twego sługi, bo do ciebie, Panie, wznoszę swą duszę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 5, 'Bo ty, Panie, jesteś dobry i przebaczający, i pełen miłosierdzia dla wszystkich, którzy cię wzywają.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 6, 'Wysłuchaj, Panie, mojej modlitwy i zważ na głos mojego błagania.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 7, 'Wzywam cię w dniu mego ucisku, bo ty mnie wysłuchasz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 8, 'Nie ma wśród bogów podobnego tobie, Panie, i nie ma dzieł takich jak twoje.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 9, 'Wszystkie narody, które stworzyłeś, przyjdą i oddadzą ci pokłon, Panie, i będą wielbić twoje imię;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 10, 'Bo ty jesteś wielki i czynisz cuda; tylko ty jesteś Bogiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 11, 'Naucz mnie, Panie, twojej drogi, abym chodził w twojej prawdzie; nakłoń moje serce ku bojaźni twego imienia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 12, 'Będę cię chwalił, Panie, mój Boże, z całego serca i będę wielbił twoje imię na wieki;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 13, 'Bo wielkie jest twoje miłosierdzie dla mnie; ty ocaliłeś moją duszę z najgłębszego piekła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 14, 'Boże, pyszni powstali przeciwko mnie i zgraja gwałtowników czyhała na moją duszę, a nie mają ciebie przed oczyma.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 15, 'Ale ty, Panie, jesteś Bogiem łaskawym i litościwym, nieskorym do gniewu, pełnym miłosierdzia i prawdy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 16, 'Spójrz na mnie i zmiłuj się nade mną, udziel swojej mocy twemu słudze i wybaw syna twojej służącej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 17, 'Daj mi znak twojej dobroci, aby ci, którzy mnie nienawidzą, zobaczyli i zawstydzili się, że ty, Panie, wspomogłeś mnie i pocieszyłeś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 1, 'Psalm i pieśń dla synów Korego. Jego fundament jest na świętych górach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 2, 'Pan miłuje bramy Syjonu bardziej niż wszystkie przybytki Jakuba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 3, 'Chwalebne rzeczy mówi się o tobie, o miasto Boże. Sela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 4, 'Wspomnę Rahab i Babilon wśród tych, którzy mnie znają; oto Filistea i Tyr, i Etiopia: Ten się tam urodził.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 5, 'O Syjonie też będą mówić: Ten i tamten urodził się w nim; a sam Najwyższy go utwierdzi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 6, 'Pan wyliczy, spisując narody: Ten się tam urodził. Sela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 7, 'I pląsając, będą śpiewać: W tobie są wszystkie me źródła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 1, 'Pieśń i psalm dla synów Korego, przewodnikowi chóru, na Machalat do śpiewania, pouczający, od Hemana Ezrachity. Panie, Boże mego zbawienia, we dnie i w nocy wołam do ciebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 2, 'Niech dojdzie do ciebie moja modlitwa, nakłoń swego ucha na moje wołanie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 3, 'Moja dusza bowiem jest nasycona utrapieniem, a moje życie zbliża się do grobu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 4, 'Zaliczono mnie do tych, którzy zstępują do dołu; stałem się jak człowiek bez siły.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 5, 'Zaliczono mnie do umarłych; jestem jak zabici, którzy leżą w grobie, o których już nie pamiętasz i którzy są odłączeni od twojej ręki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 6, 'Strąciłeś mnie w najgłębszy dół, w ciemności, w głębie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 7, 'Twój gniew ciąży na mnie i przytłoczyłeś mnie wszystkimi twymi falami. Sela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 8, 'Oddaliłeś ode mnie moich znajomych, uczyniłeś mnie dla nich ohydą; jestem uwięziony i nie mam wyjścia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 9, 'Moje oko płacze nad moim utrapieniem; wzywam cię, Panie, codziennie, wyciągam do ciebie swe ręce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 10, 'Czy dla umarłych będziesz czynił cuda? Czy umarli powstaną, aby cię wysławiać? Sela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 11, 'Czy w grobie będzie się opowiadać o twoim miłosierdziu, a o twojej wierności – w zniszczeniu?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 12, 'Czy twoje cuda pozna się w ciemnościach, a twoją sprawiedliwość w ziemi zapomnienia?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 13, 'Lecz ja, Panie, do ciebie wołam; rankiem wita cię moja modlitwa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 14, 'Dlaczego, Panie, odrzucasz moją duszę i ukrywasz przede mną swoje oblicze?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 15, 'Jestem strapiony i od młodości bliski śmierci; znoszę twoją grozę i trwożę się.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 16, 'Twój srogi gniew spadł na mnie i wyniszczyła mnie twoja groza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 17, 'Ogarniają mnie co dzień jak woda, wszystkie mnie otaczają.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 18, 'Oddaliłeś ode mnie przyjaciela i towarzysza, a moich znajomych – w ciemności.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 1, 'Pieśń pouczający Etana Ezrachity. Będę śpiewać o miłosierdziu Pana na wieki, swymi ustami będę głosił twoją wierność przez wszystkie pokolenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 2, 'Powiedziałem bowiem: Miłosierdzie będzie budowane na wieki, na niebiosach utwierdziłeś swoją wierność.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 3, 'Zawarłem przymierze z moim wybrańcem; przysiągłem Dawidowi, swemu słudze;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 4, 'Na wieki utwierdzę twoje potomstwo i zbuduję twój tron na wszystkie pokolenia. Sela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 5, 'Panie, niebiosa wysławiają twoje cuda i twoją wierność w zgromadzeniu świętych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 6, 'Któż bowiem na niebie może się równać z Panem? Kto pośród synów mocarzy jest podobny do Pana?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 7, 'Bóg jest straszliwy w zgromadzeniu świętych i budzi grozę wśród wszystkich, którzy są wokół niego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 8, 'Panie, Boże zastępów, któż jest jak ty, Pan mocny? Twoja wierność bowiem cię otacza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 9, 'Ty panujesz nad wzburzonym morzem; gdy się podnoszą jego fale, ty je poskramiasz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 10, 'Ty zmiażdżyłeś Rahaba jak rannego, mocą twego ramienia rozproszyłeś swoich wrogów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 11, 'Twoje są niebiosa, twoja też ziemia; ty ugruntowałeś świat i wszystko, co go napełnia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 12, 'Ty stworzyłeś północ i południe; Tabor i Hermon śpiewają o twoim imieniu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 13, 'Twoje ramię jest mocne, twoja ręka potężna, a twoja prawica wzniesiona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 14, 'Sprawiedliwość i sąd są podstawą twego tronu, miłosierdzie i prawda idą przed twoim obliczem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 15, 'Błogosławiony lud, który zna okrzyk radości; będzie chodzić w świetle twego oblicza, Panie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 16, 'W twoim imieniu będą się weselić każdego dnia, a w twojej sprawiedliwości będą wywyższeni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 17, 'Ty bowiem jesteś chwałą ich mocy i z twojej woli nasz róg będzie wzniesiony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 18, 'Bo Pan jest naszą tarczą, a Święty Izraela naszym królem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 19, 'Powiedziałeś wtedy w widzeniu do twego świętego: Udzieliłem pomocy mocarzowi, wywyższyłem wybranego z ludu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 20, 'Znalazłem Dawida, mego sługę, namaściłem go swoim świętym olejem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 21, 'Moja ręka będzie przy nim i wzmocni go moje ramię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 22, 'Nie będzie uciskany przez wroga, a syn nieprawości go nie pognębi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 23, 'Zetrę na jego oczach jego przeciwników, a tych, którzy go nienawidzą, powalę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 24, 'Ponadto moja prawda i miłosierdzie będą z nim, a w moim imieniu jego róg będzie wzniesiony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 25, 'I położę na morzu jego rękę i na rzekach jego prawicę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 26, 'On zawoła: Ty jesteś moim ojcem, moim Bogiem i skałą mego zbawienia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 27, 'Ja też uczynię go pierworodnym i najwyższym wśród królów ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 28, 'Na wieki zachowam dla niego swoje miłosierdzie, a moje przymierze z nim będzie trwałe.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 29, 'Jego potomstwo utrwalę na wieki, a jego tron – jak dni niebios.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 30, 'Ale jeśli jego synowie porzucą moje prawo i nie będą postępowali według moich nakazów;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 31, 'Jeśli moje ustawy znieważą, a moich przykazań nie będą przestrzegać;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 32, 'Wtedy ukarzę rózgą ich przestępstwo, a ich nieprawość biczami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 33, 'Ale nie odbiorę mu mojego miłosierdzia ani nie zawiodę w mojej wierności.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 34, 'Nie złamię mego przymierza ani nie zmienię tego, co wyszło z moich ust.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 35, 'Raz przysiągłem na moją świętość, że nie skłamię Dawidowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 36, 'Jego potomstwo będzie trwać na wieki, a jego tron jak słońce przede mną;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 37, 'Jak księżyc będzie utwierdzone na wieki i jak wierny świadek na niebie. Sela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 38, 'A jednak odrzuciłeś go i wzgardziłeś nim, rozgniewałeś się na twego pomazańca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 39, 'Zerwałeś przymierze z twoim sługą, strąciłeś na ziemię jego koronę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 40, 'Zburzyłeś wszystkie jego płoty i rozwaliłeś jego baszty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 41, 'Grabią go wszyscy, którzy przechodzą drogą; stał się pośmiewiskiem dla swoich sąsiadów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 42, 'Podniosłeś prawicę jego przeciwników, sprawiłeś radość wszystkim jego wrogom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 43, 'Stępiłeś też ostrze jego miecza i nie wsparłeś go w walce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 44, 'Położyłeś koniec jego chwale, a jego tron obaliłeś na ziemię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 45, 'Skróciłeś dni jego młodości, okryłeś go hańbą. Sela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 46, 'Jak długo, Panie? Czy wiecznie będziesz się ukrywał? Czy twoja zapalczywość będzie płonąć jak ogień?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 47, 'Pamiętaj, jak krótkie jest moje życie; czy na próżno stworzyłeś wszystkich synów ludzkich?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 48, 'Któż z ludzi może żyć i nie ujrzeć śmierci? Któż wyrwie swą duszę z mocy grobu? Sela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 49, 'Gdzie są, o Panie, twoje dawne łaski, które przysiągłeś Dawidowi w swej prawdzie?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 50, 'Pamiętaj, Panie, o zniewadze twoich sług; o tym, że noszę w swym zanadrzu wzgardę wszystkich możnych narodów;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 51, 'Którą twoi wrogowie znieważają, Panie, którą znieważają ścieżki twego pomazańca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 52, 'Błogosławiony niech będzie Pan na wieki. Amen, amen.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 1, 'Modlitwa Mojżesza, męża Bożego. Panie, ty byłeś naszą ucieczką z pokolenia na pokolenie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 2, 'Zanim zrodziły się góry, zanim ukształtowałeś ziemię i świat, od wieków na wieki ty jesteś Bogiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 3, 'Obracasz człowieka w proch i mówisz: Wracajcie, synowie ludzcy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 4, 'Tysiąc lat bowiem w twoich oczach jest jak dzień wczorajszy, który minął, i jak straż nocna.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 5, 'Porywasz ich jakby powodzią, są jak sen i jak trawa, która rośnie o poranku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 6, 'Rano kwitnie i rośnie, a wieczorem zostaje skoszona i usycha.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 7, 'Giniemy bowiem od twego gniewu i jesteśmy przerażeni twoją zapalczywością.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 8, 'Położyłeś przed sobą nasze nieprawości, nasze skryte grzechy w świetle twego oblicza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 9, 'Wszystkie nasze dni przemijają z powodu twego gniewu, nasze lata nikną jak westchnienie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 10, 'Liczbą naszych dni jest lat siedemdziesiąt, a jeśli sił starczy, lat osiemdziesiąt, a to, co w nich najlepsze, to tylko kłopot i cierpienie, bo szybko mijają, a my odlatujemy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 11, 'Któż zna srogość twego gniewu? Albo kto, bojąc się ciebie, zna twoją zapalczywość?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 12, 'Naucz nas liczyć nasze dni, abyśmy przywiedli serce do mądrości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 13, 'Powróć, Panie. Jak długo jeszcze? Zlituj się nad swymi sługami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 14, 'Nasyć nas z rana twoim miłosierdziem, abyśmy mogli się cieszyć i radować przez wszystkie nasze dni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 15, 'Spraw nam radość według dni, w których nas trapiłeś; według lat, w których zaznaliśmy zła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 16, 'Niech się ukaże twoim sługom twoje dzieło, a twoja chwała ich synom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 17, 'Niech dobroć Pana, naszego Boga, będzie z nami; i utwierdź wśród nas dzieło naszych rąk; utwierdź dzieło naszych rąk!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 1, 'Kto mieszka pod osłoną Najwyższego, w cieniu Wszechmocnego przebywać będzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 2, 'Będę mówił o Panu: Moja ucieczka i twierdza, mój Bóg, jemu będę ufał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 3, 'Zaprawdę, on wybawi cię z sideł łowcy i od zgubnej zarazy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 4, 'Okryje cię swymi piórami i pod jego skrzydłami będziesz bezpieczny; jego prawda będzie ci tarczą i puklerzem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 5, 'Nie ulękniesz się strachu nocnego ani strzały lecącej za dnia;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 6, 'Ani zarazy, która przychodzi w ciemności, ani dżumy, która pustoszy w południe.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 7, 'Tysiąc padnie u twego boku, a dziesięć tysięcy po twojej prawicy, lecz ciebie to nie dosięgnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 8, 'Tylko zobaczysz na własne oczy i ujrzysz zapłatę daną niegodziwym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 9, 'Ponieważ Pana, moją ucieczkę i Najwyższego, uczyniłeś swoim mieszkaniem;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 10, 'Nie spotka cię nic złego ani żadna plaga nie zbliży się do twego namiotu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 11, 'Rozkaże bowiem o tobie swoim aniołom, aby cię strzegli na wszystkich twoich drogach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 12, 'Na rękach będą cię nosić, byś przypadkiem nie uderzył swojej nogi o kamień.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 13, 'Będziesz stąpał po lwie i po żmii, lwiątko i smoka podepczesz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 14, 'Wybawię go, bo mnie umiłował; wywyższę go, bo poznał moje imię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 15, 'Będzie mnie wzywał, a ja go wysłucham; będę z nim w utrapieniu, wyrwę go i otoczę chwałą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 16, 'Długimi dniami go nasycę i ukażę mu moje zbawienie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 1, 'Psalm i pieśń na dzień szabatu. Dobrą rzeczą jest wysławiać Pana i śpiewać twemu imieniu, o Najwyższy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 2, 'Głosić rankiem twoje miłosierdzie, a nocami twoją wierność;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 3, 'Na instrumencie o dziesięciu strunach, na cytrze i na harfie ze śpiewaniem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 4, 'Ty bowiem rozradowałeś mnie, Panie, twymi czynami; będę śpiewać o dziełach twoich rąk.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 5, 'Jakże wielkie są twoje dzieła, Panie; bardzo głębokie są twoje myśli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 6, 'Prostak nie zna, a głupi tego nie rozumie:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 7, 'Gdy niegodziwi wyrastają jak ziele i kwitną wszyscy czyniący nieprawość, to tylko po to, aby byli wykorzenieni aż na wieki;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 8, 'Ty zaś, Panie, jesteś Najwyższy na wieki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 9, 'Oto bowiem twoi wrogowie, Panie, oto bowiem twoi wrogowie zginą, rozproszą się wszyscy czyniący nieprawość.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 10, 'Ale mój róg wzniesiesz jak u jednorożca, będę namaszczony świeżym olejem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 11, 'I moje oko zobaczy nieszczęście tych, którzy na mnie czyhają; moje uszy usłyszą o klęsce złoczyńców, którzy powstają przeciwko mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 12, 'Sprawiedliwy zakwitnie jak palma, rozrośnie się jak cedr na Libanie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 13, 'Zasadzeni w domu Pana rozkwitną na dziedzińcach naszego Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 14, 'Nawet w starości wydadzą owoc, pełni sił i kwitnący;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 15, 'Aby opowiadać, że Pan jest prawy; on jest moją skałą i nie ma w nim żadnej nieprawości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 1, 'Pan króluje, przyoblekł się w majestat, odział się Pan i przepasał potęgą; utwierdził też świat, że się nie zachwieje.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 2, 'Twój tron jest utwierdzony od wieków, ty jesteś od wieczności.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 3, 'Podniosły rzeki, Panie, podniosły rzeki swój szum, podniosły rzeki swoje fale.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 4, 'Nad szum wielkich wód, nad potężne fale morskie mocniejszy jest Pan na wysokości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 5, 'Twoje świadectwa są bardzo pewne; twemu domowi, Panie, przystoi świętość na wieczne czasy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 1, 'Boże zemsty, Panie Boże zemsty, objaw się!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 2, 'Powstań, Sędzio całej ziemi, odpłać pysznym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 3, 'Jak długo niegodziwi, Panie, jak długo niegodziwi będą się radować?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 4, 'Jak długo będą pleść, mówić zuchwale i chełpić się wszyscy czyniący nieprawość?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 5, 'Depczą twój lud, Panie, i gnębią twoje dziedzictwo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 6, 'Mordują wdowy i przybysza, zabijają sieroty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 7, 'I mówią: Pan tego nie widzi, nie dostrzega tego Bóg Jakuba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 8, 'Zrozumcie, nierozumni wśród ludu! A wy, głupcy, kiedy zmądrzejecie?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 9, 'Czy ten, który wszczepił ucho, nie słyszy? Czy ten, który ukształtował oko, nie widzi?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 10, 'Czy ten, który chłoszcze narody, nie będzie karał? Ten, który uczy człowieka wiedzy, czy nie wie?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 11, 'Pan zna myśli ludzkie; wie, że są marnością.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 12, 'Błogosławiony mąż, którego ty chłoszczesz, Panie, i uczysz go twym prawem;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 13, 'Aby dać mu odpocząć od złych dni, aż będzie wykopany dół dla niegodziwego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 14, 'Pan bowiem nie odrzuci swego ludu i nie opuści swego dziedzictwa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 15, 'Ale sąd powróci do sprawiedliwości, a wszyscy serca prawego pójdą za nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 16, 'Któż stanie przy mnie przeciwko złoczyńcom? Kto ujmie się za mną przeciwko czyniącym nieprawość?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 17, 'Gdyby Pan nie przyszedł mi z pomocą, moja dusza przebywałaby w milczeniu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 18, 'Gdy powiedziałem: Moja noga się chwieje, twoje miłosierdzie, Panie, mnie wsparło.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 19, 'W niezliczonych myślach mego serca twoje pociechy rozweselają moją duszę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 20, 'Czy sprzymierzy się z tobą tron nieprawości, który wyrządza krzywdę pod pozorem prawa?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 21, 'Zbierają się przeciw duszy sprawiedliwego i krew niewinną potępiają.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 22, 'Lecz Pan jest moją twierdzą, mój Bóg – skałą mojej ucieczki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 23, 'On obróci przeciwko nim ich nieprawość i za ich zło ich wytraci; wytraci ich Pan, nasz Bóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 1, 'Chodźcie, śpiewajmy Panu, wykrzykujmy radośnie skale naszego zbawienia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 2, 'Przyjdźmy przed jego oblicze z chwałą, radośnie śpiewajmy mu psalmy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 3, 'Pan bowiem jest wielkim Bogiem i wielkim Królem nad wszystkimi bogami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 4, 'W jego rękach są głębiny ziemi i jego są szczyty gór.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 5, 'Jego jest morze, bo on je uczynił, i jego ręce ukształtowały suchy ląd.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 6, 'Chodźcie, oddajmy pokłon i padajmy przed nim; klęknijmy przed Panem, naszym Stwórcą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 7, 'On bowiem jest naszym Bogiem, a my ludem jego pastwiska i owcami jego rąk. Dzisiaj, jeśli jego głos usłyszycie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 8, 'Nie zatwardzajcie waszych serc jak w Meriba, jak w czasie kuszenia na pustyni;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 9, 'Kiedy mnie wystawiali na próbę wasi ojcowie, doświadczali mnie i widzieli moje dzieła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 10, 'Przez czterdzieści lat czułem odrazę do tego pokolenia i powiedziałem: Ten lud błądzi sercem i nie poznał moich dróg;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 11, 'Przysiągłem im w gniewie, że nie wejdą do mego odpoczynku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 1, 'Śpiewajcie Panu nową pieśń, śpiewaj Panu, cała ziemio!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 2, 'Śpiewajcie Panu, błogosławcie jego imię, opowiadajcie o jego zbawieniu dzień po dniu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 3, 'Głoście wśród narodów jego chwałę, wśród wszystkich ludów jego cuda.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 4, 'Wielki bowiem jest Pan i godny wszelkiej chwały, straszliwszy nad wszystkich bogów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 5, 'Gdyż wszyscy bogowie narodów są bożkami, a Pan uczynił niebiosa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 6, 'Cześć i majestat przed jego obliczem, moc i piękno w jego świątyni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 7, 'Oddajcie Panu, rodziny narodów, oddajcie Panu chwałę i moc.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 8, 'Oddajcie Panu chwałę jego imienia, przynieście dary i wejdźcie do jego przedsionków.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 9, 'Oddajcie Panu pokłon w ozdobie świętości, niech cała ziemia drży przed nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 10, 'Mówcie wśród pogan: Pan króluje; świat będzie utwierdzony, aby się nie poruszył, i on będzie sądził ludzi sprawiedliwie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 11, 'Niech się weselą niebiosa i niech raduje się ziemia; niech zaszumi morze i to, co w nim jest.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 12, 'Niech radują się pola i wszystko, co jest na nich, wtedy radośnie wykrzykną wszystkie drzewa leśne;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 13, 'Przed obliczem Pana, bo idzie, zaprawdę idzie, aby sądzić ziemię. Będzie sądził świat w sprawiedliwości, a narody w swojej prawdzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 1, 'Pan króluje, raduj się, ziemio, i weselcie się, niezliczone wyspy!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 2, 'Chmury i ciemność wokół niego, sprawiedliwość i sąd podstawą jego tronu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 3, 'Ogień idzie przed nim i pożera jego wrogów wokoło.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 4, 'Jego błyskawice oświetlają świat, widzi to ziemia i drży.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 5, 'Góry topią się jak wosk przed obliczem Pana, przed obliczem Pana całej ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 6, 'Niebiosa opowiadają jego sprawiedliwość, a wszystkie narody widzą jego chwałę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 7, 'Niech będą zawstydzeni wszyscy, którzy służą posągom, którzy chlubią się bożkami; oddajcie mu pokłon, wszyscy bogowie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 8, 'Syjon to usłyszał i weseli się, a córki Judy będą się radować z powodu twoich sądów, Panie!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 9, 'Ty bowiem, Panie, jesteś Najwyższy na całej ziemi, wywyższony ponad wszystkich bogów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 10, 'Wy, którzy miłujecie Pana, miejcie w nienawiści zło; on strzeże dusz swoich świętych, ocala ich z ręki niegodziwych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 11, 'Światło jest zasiane dla sprawiedliwego i radość dla tych, którzy są prawego serca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 12, 'Weselcie się w Panu, sprawiedliwi, i wysławiajcie go, pamiętając o jego świętości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 1, 'Psalm. Śpiewajcie Panu nową pieśń, bo cudownych rzeczy dokonał, jego prawica i święte ramię przyniosły mu zwycięstwo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 2, 'Pan objawił swoje zbawienie, okazał swoją sprawiedliwość na oczach pogan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 3, 'Pamiętał o swoim miłosierdziu i swojej prawdzie wobec domu Izraela; wszystkie krańce ziemi ujrzały zbawienie naszego Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 4, 'Radośnie wykrzykuj Panu, cała ziemio; wykrzykujcie, weselcie się i śpiewajcie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 5, 'Grajcie Panu na harfie, na harfie, przy słowach pieśni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 6, 'Przy trąbach i dźwięku kornetów wykrzykujcie radośnie przed Panem, Królem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 7, 'Niech zaszumi morze i to, co w nim jest, świat i jego mieszkańcy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 8, 'Niech rzeki klaszczą w dłonie, niech góry radują się wspólnie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 9, 'Przed Panem, bo przychodzi, by sądzić ziemię. Będzie sądził świat sprawiedliwie i narody według słuszności.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 1, 'Pan króluje, niech drżą narody; siedzi między cherubinami, niech zachwieje się ziemia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 2, 'Wielki jest Pan na Syjonie i wywyższony nad wszystkie narody.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 3, 'Niech wysławiają twoje wielkie i straszne imię, bo jest święte.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 4, 'Moc króla miłuje sąd, ty ustanowiłeś słuszność, ty wykonujesz sąd i sprawiedliwość w Jakubie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 5, 'Wywyższajcie Pana, naszego Boga, i oddajcie pokłon u podnóżka jego stóp, bo on jest święty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 6, 'Mojżesz i Aaron wśród jego kapłanów, a Samuel wśród tych, którzy wzywają jego imienia; wołali do Pana, a on ich wysłuchał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 7, 'W słupie obłoku mówił do nich, a oni strzegli jego świadectw i praw, które im dał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 8, 'Panie, nasz Boże, ty ich wysłuchiwałeś, byłeś dla nich Bogiem, który przebacza, choć karałeś ich za ich występki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 9, 'Wywyższajcie Pana, naszego Boga, i oddajcie pokłon na jego świętej górze, bo Pan, nasz Bóg, jest święty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 1, 'Psalm na dziękczynienie. Radośnie wykrzykujcie Panu, wszystkie ziemie!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 2, 'Służcie Panu z weselem, przychodźcie z radością przed jego oblicze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 3, 'Wiedzcie, że Pan jest Bogiem, to on nas uczynił, a nie my sami siebie; jesteśmy jego ludem i owcami jego pastwiska.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 4, 'Wejdźcie w jego bramy z dziękczynieniem i do jego przedsionków z wychwalaniem; wysławiajcie go, błogosławcie jego imię;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 5, 'Pan bowiem jest dobry, jego miłosierdzie trwa na wieki, a jego prawda z pokolenia na pokolenie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 1, 'Psalm Dawida. Będę śpiewał o miłosierdziu i sądzie; tobie, Panie, będę śpiewać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 2, 'Kroczyć będę mądrze drogą prawą. Kiedy przyjdziesz do mnie? Będę postępował w swoim domu w prawości serca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 3, 'Nie będę stawiał przed oczami niegodziwej rzeczy; nienawidzę czynów ludzi występnych, nie przylgną one do mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 4, 'Serce przewrotne odstąpi ode mnie, nie chcę znać złego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 5, 'Zgładzę tego, który potajemnie oczernia swego bliźniego, nie zniosę wyniosłych oczu i nadętego serca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 6, 'Moje oczy zwrócone będą na wiernych tej ziemi, aby mieszkali ze mną; kto chodzi drogą prawą, ten będzie mi służyć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 7, 'Nie zamieszka w moim domu oszust, kłamca nie ostoi się przed mymi oczyma.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 8, 'Każdego ranka będę tępić wszystkich niegodziwych na ziemi, aby tak wykorzenić z miasta Pana wszystkich złoczyńców.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 1, 'Modlitwa strapionego, gdy uciśniony wylewa przed Panem swoją skargę. Panie, wysłuchaj mojej modlitwy i niech przyjdzie do ciebie moje wołanie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 2, 'Nie ukrywaj przede mną swego oblicza, w dniu mego ucisku nakłoń ku mnie swego ucha; w dniu, w którym cię wzywam, szybko mnie wysłuchaj.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 3, 'Moje dni bowiem nikną jak dym, a moje kości są rozpalone jak ognisko.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 4, 'Moje serce jest porażone i usycha jak trawa, tak że zapomniałem jeść chleb.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 5, 'Od głosu mego wołania moje kości przylgnęły mi do ciała.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 6, 'Jestem podobny do pelikana na pustyni, jestem jak sowa na pustkowiu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 7, 'Czuwam i jestem jak samotny wróbel na dachu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 8, 'Przez cały dzień znieważają mnie moi wrogowie i przeklinają mnie ci, którzy szaleją przeciwko mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 9, 'Jadam bowiem popiół jak chleb, a mój napój mieszam ze łzami;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 10, 'Z powodu twego gniewu i zapalczywości, bo podniosłeś mnie i strąciłeś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 11, 'Moje dni są jak chylący się cień, a ja usycham jak trawa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 12, 'Ale ty, Panie, trwasz na wieki, a twoja pamięć z pokolenia na pokolenie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 13, 'Powstaniesz i zmiłujesz się nad Syjonem, bo czas, byś się nad nim zlitował, gdyż nadszedł czas wyznaczony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 14, 'Twoi słudzy bowiem miłują jego kamienie i litują się nad jego prochem;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 15, 'A poganie będą się bać imienia Pana i wszyscy królowie ziemi – twojej chwały;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 16, 'Gdy Pan odbuduje Syjon i ukaże się w swojej chwale;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 17, 'Przychyli się do modlitwy opuszczonych i nie pogardzi ich modlitwą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 18, 'Zapiszą to dla przyszłego pokolenia, a lud, który ma być stworzony, będzie chwalić Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 19, 'Spojrzał bowiem z wysokości swojej świątyni; Pan popatrzył z nieba na ziemię;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 20, 'Aby wysłuchać jęku więźniów i uwolnić skazanych na śmierć;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 21, 'Aby głosili na Syjonie imię Pana i jego chwałę w Jeruzalem;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 22, 'Gdy się zgromadzą razem narody i królestwa, aby służyć Panu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 23, 'Osłabił w drodze moją siłę, skrócił moje dni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 24, 'Powiedziałem: Mój Boże, nie zabieraj mnie w połowie moich dni; twoje lata bowiem trwają z pokolenia na pokolenie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 25, 'Ty dawno założyłeś fundamenty ziemi i niebiosa są dziełem twoich rąk.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 26, 'One przeminą, ale ty pozostajesz; wszystkie jak szata się zestarzeją, zmienisz je jak płaszcz i będą odmienione.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 27, 'Ale ty zawsze jesteś ten sam, a twoje lata nigdy się nie skończą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 28, 'Synowie twoich sług będą trwać u ciebie, a ich potomstwo zostanie przed tobą utwierdzone.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 1, 'Psalm Dawida. Błogosław, moja duszo, Pana, i całe moje wnętrze – jego święte imię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 2, 'Błogosław, moja duszo, Pana, i nie zapominaj o wszystkich jego dobrodziejstwach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 3, 'On przebacza wszystkie twoje nieprawości, on uzdrawia wszystkie twoje choroby;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 4, 'On wybawia twoje życie od zguby, on cię koronuje miłosierdziem i wielką litością.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 5, 'On nasyca dobrem twoje usta i odnawia twoją młodość jak u orła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 6, 'Pan wymierza sprawiedliwość i sąd wszystkim uciśnionym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 7, 'Dał poznać swe drogi Mojżeszowi, a synom Izraela swoje dzieła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 8, 'Łaskawy i litościwy jest Pan, nieskory do gniewu i pełen wielkiego miłosierdzia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 9, 'Nie będzie się spierał bez końca ani wiecznie gniewu chował.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 10, 'Nie postępuje z nami według naszych grzechów ani nie odpłaca nam według naszych nieprawości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 11, 'Jak wysoko bowiem są niebiosa nad ziemią, tak wielkie jest jego miłosierdzie nad tymi, którzy się go boją.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 12, 'Jak daleko jest wschód od zachodu, tak daleko oddalił od nas nasze występki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 13, 'Jak ojciec ma litość nad dziećmi, tak Pan ma litość nad tymi, którzy się go boją.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 14, 'On bowiem wie, z czego jesteśmy ulepieni; pamięta, że jesteśmy prochem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 15, 'Dni człowieka są jak trawa, kwitnie jak kwiat polny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 16, 'Wiatr na niego powieje, a już go nie ma i nie pozna go już jego miejsce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 17, 'Ale miłosierdzie Pana od wieków na wieki nad tymi, którzy się go boją, a jego sprawiedliwość nad synami synów;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 18, 'Nad tymi, którzy strzegą jego przymierza i pamiętają, aby wypełnić jego przykazania.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 19, 'Pan na niebiosach ustanowił swój tron, a jego królestwo panuje nad wszystkimi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 20, 'Błogosławcie Pana, jego aniołowie, potężni siłą, którzy wypełniacie jego rozkazy, będąc posłuszni głosowi jego słowa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 21, 'Błogosławcie Pana, wszystkie jego zastępy, jego słudzy, którzy spełniacie jego wolę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 22, 'Błogosławcie Pana, wszystkie jego dzieła, we wszystkich miejscach jego panowania. Błogosław, moja duszo, Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 1, 'Błogosław, moja duszo, Pana. Panie, mój Boże, jesteś bardzo wielki; odziałeś się w chwałę i majestat.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 2, 'Okryłeś się światłością jak szatą, rozciągnąłeś niebiosa jak zasłonę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 3, 'Zbudowałeś na wodach swoje komnaty, czynisz obłoki swym rydwanem, chodzisz na skrzydłach wiatru.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 4, 'Czynisz swoich aniołów duchami, swe sługi ogniem płonącym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 5, 'Założyłeś fundamenty ziemi, tak że się nigdy nie zachwieje.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 6, 'Okryłeś ją głębią jak szatą, wody stanęły nad górami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 7, 'Na twoje zgromienie rozbiegły się, a na głos twego grzmotu szybko pouciekały.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 8, 'Wzniosły się ponad góry, zniżyły się w doliny, na miejsce, które dla nich założyłeś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 9, 'Wyznaczyłeś im granicę, aby jej nie przekroczyły ani nie powróciły, by okryć ziemię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 10, 'Wypuszczasz źródła po dolinach, aby płynęły między górami;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 11, 'I napoiły wszystkie zwierzęta polne, dzikie osły gaszą w nich swoje pragnienie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 12, 'Przy nich mieszka ptactwo niebieskie i śpiewa pośród gałęzi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 13, 'Nawadniasz góry ze swoich komnat, owocami twoich dzieł syci się ziemia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 14, 'Sprawiasz, że rośnie trawa dla bydła i zioła na użytek człowieka, żeby dobywał chleb z ziemi;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 15, 'I wino, które rozwesela serce człowieka, i oliwę, od której rozjaśnia się twarz, i chleb, który krzepi serce ludzkie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 16, 'Nasycone są drzewa Pana, cedry Libanu, które zasadził;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 17, 'Na których ptaki mają swe gniazda; jedliny, na których bocian ma swój dom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 18, 'Wysokie góry są dla górskich kozłów, a skały są schronieniem dla królików.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 19, 'Uczynił księżyc, aby odmierzał czas; słońce zna swój zachód.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 20, 'Sprowadzasz ciemność i nastaje noc, w której wychodzą wszystkie zwierzęta leśne.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 21, 'Lwiątka ryczą za łupem i szukają swego pokarmu od Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 22, 'Słońce wstaje, schodzą się razem i kładą się w swoich jamach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 23, 'Wtedy wychodzi człowiek do swojej roboty i do swojej pracy aż do wieczora.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 24, 'O, jak liczne są twoje dzieła, Panie! Wszystkie je uczyniłeś mądrze, ziemia jest pełna twego bogactwa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 25, 'Oto morze wielkie i szerokie, w nim niezliczone istoty pełzające, zwierzęta małe i wielkie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 26, 'Po nim pływają okręty i Lewiatan, którego stworzyłeś, aby w nim igrał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 27, 'Wszystko to czeka na ciebie, abyś dał im pokarm we właściwym czasie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 28, 'Gdy dajesz im, zbierają; gdy otwierasz swą rękę, sycą się dobrami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 29, 'Lecz gdy ukrywasz swe oblicze, trwożą się; gdy odbierasz im ducha, giną i obracają się w proch.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 30, 'Gdy wysyłasz twego ducha, zostają stworzone i odnawiasz oblicze ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 31, 'Niech chwała Pana trwa na wieki, niech się raduje Pan swymi dziełami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 32, 'Patrzy na ziemię, a ona drży, dotyka gór, a dymią.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 33, 'Będę śpiewał Panu, póki żyję; będę śpiewał memu Bogu, póki istnieję.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 34, 'Moje rozmyślanie o nim wdzięczne będzie, rozraduję się w Panu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 35, 'Niech zostaną wytraceni z ziemi grzesznicy i niech nie będzie już niegodziwych! Błogosław, moja duszo, Pana. Alleluja.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 1, 'Wysławiajcie Pana, wzywajcie jego imienia, opowiadajcie jego dzieła wśród narodów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 2, 'Śpiewajcie mu, śpiewajcie mu psalmy, rozmawiajcie o wszystkich jego cudach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 3, 'Chlubcie się jego świętym imieniem, niech się weseli serce szukających Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 4, 'Szukajcie Pana i jego mocy, szukajcie zawsze jego oblicza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 5, 'Przypominajcie sobie dzieła, które czynił; jego cuda i wyroki jego ust.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 6, 'Wy, potomkowie Abrahama, jego słudzy; wy, synowie Jakuba, jego wybrańcy!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 7, 'On jest Panem, naszym Bogiem, jego sądy po całej ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 8, 'Pamięta wiecznie o swoim przymierzu; o słowie, które nakazał po tysiąc pokoleń;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 9, 'O przymierzu, które zawarł z Abrahamem, i o przysiędze złożonej Izaakowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 10, 'Ustanowił je jako prawo dla Jakuba, dla Izraela jako wieczne przymierze;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 11, 'Mówiąc: Tobie dam ziemię Kanaan jako dział waszego dziedzictwa;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 12, 'Kiedy ich było niewielu, nieliczni i obcy w niej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 13, 'I wędrowali od narodu do narodu, z jednego królestwa do innego ludu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 14, 'Nikomu nie pozwolił ich krzywdzić, nawet karcił królów z ich powodu, mówiąc:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 15, 'Nie dotykajcie moich pomazańców, a moim prorokom nie czyńcie nic złego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 16, 'Potem przywołał głód na ziemię i zniszczył cały zapas chleba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 17, 'Posłał przed nimi męża, Józefa, który został sprzedany jako niewolnik;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 18, 'Którego nogi ranili pętami, a w żelazo zakuto jego ciało;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 19, 'Aż do tego czasu, gdy jego słowo się spełniło, słowo Pana doświadczało go.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 20, 'Posłał król i kazał go uwolnić, władca narodu wypuścił go na wolność.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 21, 'Ustanowił go panem swego domu i władcą wszystkich swoich posiadłości;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 22, 'Aby rządził jego dostojnikami według swego uznania i jego starszych nauczał mądrości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 23, 'Potem Izrael wszedł do Egiptu, a Jakub był gościem w ziemi Chama;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 24, 'Gdzie Bóg bardzo rozmnożył swój lud i uczynił go potężniejszym od jego wrogów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 25, 'Odmienił ich serca, żeby znienawidzili jego lud i postępowali przebiegle wobec jego sług.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 26, 'Posłał Mojżesza, swego sługę, i Aarona, którego wybrał;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 27, 'Pokazali im jego znaki i cuda w ziemi Chama.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 28, 'Zesłał ciemności i nastał mrok, i nie buntowali się przeciw jego słowu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 29, 'Zamienił ich wody w krew i pozabijał ich ryby.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 30, 'Ich ziemia wydała mnóstwo żab, były nawet w komnatach królewskich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 31, 'Rozkazał i zjawiły się rozmaite muchy i wszy w całym ich kraju.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 32, 'Zesłał grad zamiast deszczu, ogień płonący na ich ziemię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 33, 'Zniszczył ich winnice i figowce i połamał drzewa w ich kraju.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 34, 'Rozkazał i zjawiła się szarańcza, niezliczone mnóstwo larw;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 35, 'I pożarły całą zieleń w ich kraju, i zjadły płody ich ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 36, 'Zabił też wszystko, co pierworodne w ich ziemi, pierwociny wszelkiej ich siły.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 37, 'Wyprowadził ich ze srebrem i złotem i nie było słabego wśród ich plemion.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 38, 'Egipt się radował, gdy wychodzili, bo ogarnął go strach przed nimi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 39, 'Rozpostarł obłok jak osłonę, a ogień, by świecił w nocy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 40, 'Na ich żądanie zesłał przepiórki i nasycił ich chlebem z nieba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 41, 'Otworzył skałę i trysnęły wody, popłynęły po suchych miejscach jak rzeka;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 42, 'Pamiętał bowiem o swoim świętym słowie i o Abrahamie, swym słudze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 43, 'Wyprowadził swój lud wśród wesela, swoich wybranych wśród radości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 44, 'I dał im ziemię pogan, i zawładnęli dorobkiem narodów;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 45, 'Aby zachowywali jego nakazy i przestrzegali jego praw. Alleluja.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 1, 'Alleluja. Wysławiajcie Pana, bo jest dobry, bo jego miłosierdzie trwa na wieki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 2, 'Któż wypowie wielkie dzieła Pana i ogłosi całą jego chwałę?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 3, 'Błogosławieni, którzy strzegą sądu i czynią sprawiedliwość w każdym czasie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 4, 'Pamiętaj o mnie, Panie, przez miłość do swego ludu; nawiedź mnie swoim zbawieniem;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 5, 'Abym widział szczęście twoich wybranych, cieszył się radością twego narodu i chlubił się razem z twoim dziedzictwem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 6, 'Zgrzeszyliśmy wraz z naszymi ojcami, popełniliśmy nieprawość i postąpiliśmy niegodziwie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 7, 'Nasi ojcowie w Egipcie nie zrozumieli twoich cudów, nie pamiętali wielkości twego miłosierdzia, lecz buntowali się nad Morzem Czerwonym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 8, 'A jednak ich wybawił przez wzgląd na swoje imię, aby okazać swą moc.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 9, 'Zgromił Morze Czerwone i wyschło; i przeprowadził ich przez głębiny jak przez pustynię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 10, 'Tak wybawił ich z ręki tego, który ich nienawidził, i odkupił ich z ręki wroga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 11, 'Wody okryły ich ciemięzców, nie został ani jeden z nich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 12, 'Wtedy uwierzyli jego słowom i śpiewali na jego chwałę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 13, 'Szybko jednak zapomnieli o jego dziełach, nie czekali na jego rady.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 14, 'Pałali żądzą na pustyni, na próbę wystawiali Boga na pustkowiu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 15, 'I dał im, czego żądali, lecz zesłał na ich dusze wycieńczenie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 16, 'Gdy w obozie zazdrościli Mojżeszowi i Aaronowi, świętemu Pana;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 17, 'Otworzyła się ziemia i pochłonęła Datana, i zakryła zgromadzenie Abirama;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 18, 'I zapłonął ogień w tym zgromadzeniu, płomień spalił niegodziwych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 19, 'Zrobili cielca na Horebie i odlanemu posągowi oddali pokłon;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 20, 'I zamienili swą chwałę na podobieństwo wołu jedzącego trawę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 21, 'Zapomnieli o Bogu, swoim wybawcy, który dokonywał wielkich czynów w Egipcie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 22, 'Cudownych dzieł w ziemi Chama, rzeczy strasznych nad Morzem Czerwonym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 23, 'Dlatego powiedział, że wytraciłby ich, gdyby Mojżesz, jego wybrany, nie stanął w wyłomie przed nim, aby odwrócić jego gniew, by ich nie wytracił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 24, 'Wzgardzili też wspaniałą ziemią, nie wierząc jego słowu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 25, 'I szemrząc w swoich namiotach, nie byli posłuszni głosowi Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 26, 'Dlatego podniósł na nich swoją rękę, aby ich wytracić na pustyni;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 27, 'Aby ich potomstwo rozrzucić wśród pogan i rozproszyć ich po ziemiach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 28, 'Przyłączyli się też do Baal-Peor i jedli ofiary składane umarłym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 29, 'Tak pobudzili Boga do gniewu swymi postępkami, że spadła na nich plaga;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 30, 'Wtedy powstał Pinchas, dokonał sądu i plaga ustała.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 31, 'Poczytano mu to za sprawiedliwość po wszystkie pokolenia, na wieki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 32, 'Rozgniewali go znowu u wód Meriba, tak że Mojżesz wiele ucierpiał z ich powodu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 33, 'Rozdrażnili bowiem jego ducha i mówił nierozważnie swymi ustami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 34, 'Nie wytępili narodów, jak im to Pan nakazał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 35, 'Lecz zmieszali się z tymi narodami i nauczyli się ich czynów;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 36, 'I służyli ich bożkom, które stały się dla nich pułapką.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 37, 'Ofiarowali bowiem demonom swoich synów i swoje córki;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 38, 'I przelewali krew niewinną, krew swoich synów i córek, których ofiarowali bożkom Kanaanu, i ziemia została skalana rozlewem krwi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 39, 'Splamili się swymi czynami i cudzołożyli swymi postępkami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 40, 'Dlatego Pan zapłonął gniewem przeciw swemu ludowi, tak że obrzydził sobie swoje dziedzictwo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 41, 'I wydał ich w ręce pogan, i panowali nad nimi ci, którzy ich nienawidzili.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 42, 'I uciskali ich wrogowie, ujarzmili ich swoją ręką.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 43, 'Wielokrotnie ich ocalał, lecz oni rozgniewali go swymi zamysłami i zostali upokorzeni przez swoje nieprawości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 44, 'A jednak wejrzał na ich ucisk i usłyszał ich wołanie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 45, 'Przypomniał sobie bowiem o swoim przymierzu z nimi i pożałował według swej wielkiej litości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 46, 'Wzbudził też litość dla nich u wszystkich, którzy ich uprowadzili w niewolę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 47, 'Wybaw nas, Panie, nasz Boże, i zgromadź nas spośród pogan, abyśmy wysławiali twoje święte imię i chlubili się twoją chwałą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 48, 'Błogosławiony Pan, Bóg Izraela, od wieków na wieki; niech cały lud powie: Amen. Alleluja.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 1, 'Wysławiajcie Pana, bo jest dobry, bo jego miłosierdzie trwa na wieki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 2, 'Niech to mówią odkupieni przez Pana, ci, których odkupił z ręki wroga;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 3, 'I zgromadził z ziem, ze wschodu i zachodu, z północy i południa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 4, 'Błądzili po pustyni, po bezdrożnym pustkowiu, nie znajdując miasta, gdzie mogliby zamieszkać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 5, 'Byli głodni i spragnieni, aż omdlewała w nich dusza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 6, 'A gdy zawołali do Pana w swoim utrapieniu, uwolnił ich z ucisku;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 7, 'I prowadził ich prostą drogą, aby doszli do miasta, w którym mogliby zamieszkać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 8, 'Niech wysławiają Pana za jego miłosierdzie i cudowne dzieła wobec synów ludzkich;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 9, 'Bo napoił spragnioną duszę, a głodną duszę napełnił dobrami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 10, 'Siedzieli w ciemności i w cieniu śmierci, spętani nędzą i żelazem;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 11, 'Bo buntowali się przeciw słowom Boga i pogardzili radą Najwyższego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 12, 'Dlatego upokorzył ich serce trudem, upadli, a nie było nikogo, kto by im pomógł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 13, 'A gdy wołali do Pana w swoim utrapieniu, wybawił ich z ucisku;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 14, 'Wyprowadził ich z ciemności i z cienia śmierci, a ich pęta rozerwał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 15, 'Niech wysławiają Pana za jego miłosierdzie i za cudowne dzieła wobec synów ludzkich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 16, 'Bo skruszył bramy spiżowe i połamał żelazne rygle.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 17, 'Głupcy z powodu swej występnej drogi i nieprawości doznają utrapień.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 18, 'Ich dusza brzydzi się wszelkim pokarmem i zbliżają się do bram śmierci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 19, 'A gdy wołają do Pana w swoim utrapieniu, wybawia ich z udręczeń.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 20, 'Posłał swoje słowo i uzdrowił ich, i wybawił ich z grobu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 21, 'Niech wysławiają Pana za jego miłosierdzie i cudowne dzieła wobec synów ludzkich;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 22, 'I niech składają ofiary dziękczynienia, i głoszą z radością jego dzieła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 23, 'Ci, którzy na statkach wyruszają w morze, handlujący na wielkich wodach;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 24, 'Widzą dzieła Pana i jego cuda w głębinach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 25, 'Gdy daje rozkaz, powstaje wicher i podnoszą się fale morskie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 26, 'Oni wstępują aż do nieba i zstępują w głębiny, tak że ich dusza mdleje w niebezpieczeństwie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 27, 'Chwieją się i zataczają jak pijany, a cała ich mądrość zanika.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 28, 'Gdy wołają do Pana w swoim utrapieniu, wybawia ich z udręczeń.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 29, 'Zamienia burzę w ciszę, tak że uspokajają się jej fale.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 30, 'Wtedy oni weselą się, że ucichły; i tak przyprowadza ich do upragnionego portu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 31, 'Niech wysławiają Pana za jego miłosierdzie i cudowne dzieła wobec synów ludzkich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 32, 'Niech go wywyższają w zgromadzeniu ludu i w radzie starszych niech go chwalą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 33, 'Zamienia rzeki w pustynię, a źródła wód w suchą ziemię;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 34, 'Ziemię urodzajną zamienia w jałową z powodu niegodziwości tych, którzy w niej mieszkają.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 35, 'Pustynię zamienia w jezioro, a suchą ziemię w źródła wód.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 36, 'I osadza tam głodnych, aby zakładali miasta do zamieszkania;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 37, 'I obsiewali pole, sadzili winnice i zbierali obfity plon.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 38, 'Błogosławi im tak, że bardzo się rozmnażają, i nie zmniejsza liczebności ich bydła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 39, 'Ale potem maleje ich liczba i upokorzeni są uciskiem, nędzą i utrapieniem;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 40, 'On wylewa wzgardę na władców i sprawia, że błądzą po bezdrożach pustkowia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 41, 'Lecz podnosi nędznego z utrapienia i rozmnaża jego rodzinę jak stado.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 42, 'Widząc to, prawi rozweselą się, a wszelka nieprawość zamknie swe usta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 43, 'Kto jest tak mądry, aby tego upatrywał i rozumiał litość Pana?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 1, 'Pieśń. Psalm Dawida. Boże, moje serce jest gotowe; będę ci śpiewać i wysławiać cię, także i moja chwała.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 2, 'Obudź się, cytro i harfo, gdy o świcie powstanę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 3, 'Będę cię wysławiać wśród ludu, Panie, będę ci śpiewał wśród narodów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 4, 'Twoje miłosierdzie bowiem jest wielkie, sięga ponad niebiosa, a twoja prawda aż pod obłoki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 5, 'Bądź wywyższony ponad niebiosa, Boże, a twoja chwała ponad całą ziemię;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 6, 'Aby twoi umiłowani byli ocaleni, wybaw ich swoją prawicą i wysłuchaj mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 7, 'Bóg przemówił w swej świętości: Będę się weselić, rozdzielę Sychem, a dolinę Sukkot wymierzę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 8, 'Mój jest Gilead, mój i Manasses, Efraim mocą mojej głowy, Juda moim prawodawcą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 9, 'Moab jest moją miednicą do mycia, na Edom rzucę moje obuwie, nad Filisteą zatriumfuję.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 10, 'Kto mnie wprowadzi do miasta warownego? Kto mnie doprowadzi aż do Edomu?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 11, 'Czy nie ty, Boże, który nas odrzuciłeś? Czy nie wyruszysz, Boże, z naszymi wojskami?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 12, 'Udziel nam pomocy w ucisku, bo próżna jest pomoc ludzka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 13, 'W Bogu będziemy mężni, on podepcze naszych wrogów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 1, 'Przewodnikowi chóru. Psalm Dawida. Boże mojej chwały, nie milcz;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 2, 'Bo otworzyły się przeciwko mnie usta niegodziwego i usta podstępnego; mówili przeciwko mnie językiem kłamliwym;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 3, 'Otoczyli mnie słowami nienawiści i walczą przeciwko mnie bez przyczyny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 4, 'Sprzeciwiają mi się w zamian za moją miłość, choć ja się za nich modliłem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 5, 'Odpłacają mi złem za dobro i nienawiścią za moją miłość.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 6, 'Postaw nad nim niegodziwego, a szatan niech stoi po jego prawicy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 7, 'Gdy stanie przed sądem, niech wyjdzie potępiony, a jego modlitwa niech zamieni się w grzech.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 8, 'Niech jego dni będą krótkie, a jego urząd niech przejmie inny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 9, 'Niech jego dzieci będą sierotami, a jego żona wdową.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 10, 'Niech jego dzieci będą tułaczami i żebrzą, niech żebrzą z dala od swoich opustoszałych miejsc.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 11, 'Niech lichwiarz przejmie wszystko, co ma, a obcy niech rozgrabią owoc jego pracy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 12, 'Niech nie będzie nikogo, kto by mu okazał miłosierdzie; niech nie będzie nikogo, kto by się zlitował nad jego sierotami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 13, 'Niech jego potomkowie zostaną wykorzenieni, niech ich imię zginie w drugim pokoleniu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 14, 'Niech Pan pamięta nieprawość jego przodków, a grzech jego matki niech nie będzie zgładzony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 15, 'Niech będą zawsze przed Panem, aż wykorzeni z ziemi pamięć o nich;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 16, 'Dlatego że nie pamiętał, by okazać miłosierdzie, ale prześladował człowieka nędznego i ubogiego, a strapionego w sercu chciał zabić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 17, 'Skoro umiłował przekleństwo, niech na niego spadnie; skoro nie chciał błogosławieństwa, niech się od niego oddali.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 18, 'Ubierał się w przekleństwo jak w szatę, więc niech wejdzie jak woda do jego wnętrzności i jak oliwa do jego kości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 19, 'Niech mu będzie jak płaszcz, który go okrywa, i jak pas, który go zawsze opasuje.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 20, 'Taka niech będzie zapłata od Pana dla moich przeciwników i tych, którzy źle mówią przeciwko mojej duszy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 21, 'Ale ty, Boże, Panie, ujmij się za mną przez wzgląd na twoje imię; ocal mnie, bo wielkie jest twoje miłosierdzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 22, 'Jestem bowiem ubogi i nędzny, a moje serce we mnie jest zranione.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 23, 'Niknę jak cień, który się chyli, strząsają mnie jak szarańczę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 24, 'Moje kolana słabną od postu, a moje ciało wychudło bez tłuszczu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 25, 'Stałem się też dla nich pośmiewiskiem; gdy mnie widzą, kiwają głowami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 26, 'Wspomóż mnie, Panie, mój Boże; wybaw mnie według swego miłosierdzia;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 27, 'Aby mogli poznać, że to twoja ręka; że ty, Panie, to uczyniłeś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 28, 'Niech oni przeklinają, ale ty błogosław; gdy powstają, niech będą zawstydzeni, a twój sługa niech się weseli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 29, 'Niech moi przeciwnicy okryją się hańbą i niech się okryją własnym wstydem jak płaszczem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 30, 'Będę wielce wysławiał Pana swymi ustami i pośród tłumu będę go chwalić;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 31, 'Bo staje po prawicy nędznego, aby go wybawić od tych, którzy osądzają jego duszę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 1, 'Psalm Dawida. Powiedział Pan do mego Pana: Usiądź po mojej prawicy, aż położę twoich wrogów jako podnóżek pod twoje stopy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 2, 'Laskę twojej mocy pośle Pan z Syjonu, mówiąc: Panuj pośród twoich wrogów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 3, 'Twój lud będzie ochoczy w dniu twej potęgi, w ozdobie świętości i z łona jutrzenki; twoja jest rosa młodości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 4, 'Pan przysiągł i nie będzie żałował: Ty jesteś kapłanem na wieki według porządku Melchizedeka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 5, 'Pan po twojej prawicy zetrze królów w dniu swego gniewu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 6, 'Będzie sądził narody i trupami napełni wszystko; roztrzaska głowy panujące nad wieloma ziemiami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 7, 'Ze strumienia będzie pił po drodze, dlatego podniesie głowę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 1, 'Alleluja. Będę wysławiał Pana całym sercem w radzie prawych i w zgromadzeniu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 2, 'Wielkie są dzieła Pana, rozważane przez wszystkich, którzy je miłują.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 3, 'Jego dzieło jest chwalebne i wspaniałe, a jego sprawiedliwość trwa na wieki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 4, 'Pamiętnymi uczynił swe cuda; miłosierny i litościwy jest Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 5, 'Dał pokarm tym, którzy się go boją, pamięta wiecznie o swoim przymierzu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 6, 'Okazał swemu ludowi potęgę swoich dzieł, dając mu dziedzictwo pogan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 7, 'Dzieła rąk jego to prawda i sąd, niezmienne są wszystkie jego przykazania;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 8, 'Ustalone na wieki wieków, ustanowione w prawdzie i prawości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 9, 'Zesłał swemu ludowi odkupienie, ustanowił na wieki swoje przymierze; jego imię jest święte i straszne.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 10, 'Bojaźń Pana jest początkiem mądrości; prawdziwego rozumu nabywają wszyscy, którzy wypełniają jego przykazania; jego chwała trwa na wieki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 1, 'Alleluja. Błogosławiony człowiek, który boi się Pana i ma upodobanie w jego przykazaniach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 2, 'Jego potomstwo będzie potężne na ziemi, pokolenie prawych będzie błogosławione.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 3, 'Dobrobyt i bogactwo są w jego domu, a jego sprawiedliwość trwa na wieki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 4, 'Dla prawych wschodzi światłość w ciemności; on jest łaskawy, miłosierny i sprawiedliwy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 5, 'Dobry człowiek lituje się i pożycza, i prowadzi swoje sprawy rozważnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 6, 'Na pewno nigdy się nie zachwieje, sprawiedliwy na wieki pozostanie w pamięci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 7, 'Nie będzie się bał złej nowiny, jego serce jest stateczne, ufa Panu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 8, 'Jego serce jest umocnione, nie będzie się bał, aż zobaczy pomstę nad swymi wrogami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 9, 'Rozrzucił i dał ubogim, jego sprawiedliwość trwa na wieki, jego róg będzie wywyższony w chwale.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 10, 'Niegodziwy zobaczy to i rozgniewa się, zgrzytnie zębami i uschnie, pragnienie niegodziwych zginie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 1, 'Alleluja. Chwalcie, słudzy Pana, chwalcie imię Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 2, 'Niech imię Pana będzie błogosławione, odtąd aż na wieki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 3, 'Od wschodu słońca aż do jego zachodu, niech imię Pana będzie pochwalone.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 4, 'Pan jest wywyższony ponad wszystkie narody, jego chwała ponad niebiosa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 5, 'Któż jak Pan, nasz Bóg, który mieszka na wysokości;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 6, 'Który zniża się, aby patrzeć na to, co jest na niebie i na ziemi?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 7, 'Podnosi nędznego z prochu, a z gnoju podnosi ubogiego;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 8, 'Aby go posadzić z książętami, z książętami swego ludu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 9, 'On sprawia, że niepłodna staje się matką domu, cieszącą się dziećmi. Alleluja.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 1, 'Gdy Izrael wychodził z Egiptu, dom Jakuba spośród ludu obcego języka;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 2, 'Juda stał się jego świątynią, Izrael jego panowaniem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 3, 'Morze to ujrzało i uciekło, Jordan wstecz się odwrócił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 4, 'Góry skakały jak barany, pagórki jak jagnięta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 5, 'Morze, cóż ci się stało, żeś uciekło, a tobie, Jordanie, że wstecz się odwróciłeś?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 6, 'Góry, że skakałyście jak barany, a wy, pagórki, jak jagnięta?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 7, 'Zadrżyj, ziemio, przed obliczem Pana, przed obliczem Boga Jakuba;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 8, 'Który zamienia skałę w jezioro, a krzemień w źródło wód.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 1, 'Nie nam, Panie, nie nam, ale twemu imieniu daj chwałę za twoje miłosierdzie i prawdę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 2, 'Czemu mają mówić poganie: Gdzież teraz jest ich Bóg?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 3, 'A nasz Bóg jest w niebie, czyni wszystko, co zechce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 4, 'Ich bożki to srebro i złoto, dzieło rąk ludzkich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 5, 'Usta mają, ale nie mówią; mają oczy, ale nie widzą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 6, 'Uszy mają, ale nie słyszą; mają nozdrza, ale nie czują.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 7, 'Ręce mają, ale nie dotykają; mają nogi, ale nie chodzą; ani gardłem swoim nie wydają głosu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 8, 'Niech będą do nich podobni ci, którzy je robią, i wszyscy, którzy im ufają.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 9, 'Izraelu, ufaj Panu; on jest ich pomocą i tarczą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 10, 'Domu Aarona, ufaj Panu; on jest ich pomocą i tarczą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 11, 'Wy, którzy się boicie Pana, ufajcie Panu; on jest ich pomocą i tarczą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 12, 'Pan pamięta o nas, będzie błogosławił; będzie błogosławił domowi Izraela, będzie błogosławił domowi Aarona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 13, 'Będzie błogosławił tym, którzy boją się Pana, i małym, i wielkim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 14, 'Rozmnoży was Pan, was i waszych synów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 15, 'Błogosławieni jesteście przez Pana, który stworzył niebo i ziemię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 16, 'Niebiosa są niebiosami Pana, ale ziemię dał synom ludzkim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 17, 'Umarli nie będą chwalili Pana ani nikt z tych, którzy zstępują do miejsca milczenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 18, 'Ale my będziemy błogosławili Pana, odtąd aż na wieki. Alleluja.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 1, 'Miłuję Pana, bo usłyszał mój głos i moje prośby.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 2, 'Nakłonił bowiem swego ucha ku mnie, dlatego będę go wzywał za moich dni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 3, 'Otoczyły mnie boleści śmierci, utrapienia piekła przeniknęły mnie; przyszły na mnie ucisk i boleść.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 4, 'Wtedy wezwałem imienia Pana, mówiąc: Panie, proszę, wybaw moją duszę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 5, 'Łaskawy jest Pan i sprawiedliwy, nasz Bóg jest miłosierny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 6, 'Pan strzeże ludzi prostych; byłem uciśniony, a wybawił mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 7, 'Powróć, moja duszo, do swego odpoczynku, bo Pan dobrze ci uczynił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 8, 'Wybawił bowiem moją duszę od śmierci, oczy moje od płaczu, moją nogę od upadku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 9, 'Będę chodził przed obliczem Pana w ziemi żyjących.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 10, 'Uwierzyłem i dlatego przemówiłem; byłem bardzo strapiony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 11, 'Powiedziałem w zatrwożeniu: Każdy człowiek to kłamca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 12, 'Cóż oddam Panu za wszystkie jego dobrodziejstwa, które mi wyświadczył?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 13, 'Wezmę kielich zbawienia i będę wzywać imienia Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 14, 'Moje śluby złożone Panu wypełnię teraz przed całym jego ludem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 15, 'Cenna jest w oczach Pana śmierć jego świętych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 16, 'O Panie, jestem twoim sługą; jestem twoim sługą i synem twojej służącej; rozerwałeś moje więzy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 17, 'Tobie złożę ofiarę chwały i będę wzywać imienia Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 18, 'Moje śluby złożone Panu wypełnię teraz przed całym jego ludem;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 19, 'W dziedzińcach domu Pana, pośrodku ciebie, Jeruzalem! Alleluja.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 117, 1, 'Chwalcie Pana, wszystkie narody! Chwalcie go, wszyscy ludzie!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 117, 2, 'Wielkie jest bowiem jego miłosierdzie nad nami, a prawda Pana trwa na wieki. Alleluja.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 1, 'Wysławiajcie Pana, bo jest dobry, bo jego miłosierdzie trwa na wieki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 2, 'Niech powie teraz Izrael, że jego miłosierdzie trwa na wieki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 3, 'Niech powie teraz dom Aarona, że jego miłosierdzie trwa na wieki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 4, 'Niech powiedzą teraz ci, którzy się boją Pana, że jego miłosierdzie trwa na wieki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 5, 'Wzywałem Pana w ucisku; Pan mnie wysłuchał i postawił mnie na miejscu przestronnym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 6, 'Pan jest ze mną, nie będę się bał; cóż może mi uczynić człowiek?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 7, 'Pan jest ze mną wśród tych, którzy mi pomagają, więc zobaczę pomstę nad tymi, którzy mnie nienawidzą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 8, 'Lepiej ufać Panu, niż polegać na człowieku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 9, 'Lepiej ufać Panu, niż polegać na władcach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 10, 'Wszystkie narody mnie otoczyły, ale w imię Pana wytępiłem je.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 11, 'Otoczyły mnie, tak, otoczyły mnie, ale w imię Pana wytępiłem je.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 12, 'Otoczyły mnie jak pszczoły, ale zgasły jak ogień z cierni, bo w imię Pana wytępiłem je.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 13, 'Pchnąłeś mnie silnie, abym upadł, ale Pan mi pomógł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 14, 'Pan jest moją siłą i pieśnią, on stał się moim zbawieniem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 15, 'Głos radości i zbawienia w namiotach sprawiedliwych: Prawica Pana działa potężnie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 16, 'Prawica Pana jest wywyższona, prawica Pana działa potężnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 17, 'Nie umrę, lecz będę żył i opowiadał dzieła Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 18, 'Pan ukarał mnie surowo, ale nie wydał mnie na śmierć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 19, 'Otwórzcie mi bramy sprawiedliwości, a wejdę w nie i będę wysławiał Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 20, 'To jest brama Pana, którą wchodzą sprawiedliwi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 21, 'Będę cię wysławiać, bo mnie wysłuchałeś i stałeś się moim zbawieniem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 22, 'Kamień, który odrzucili budujący, stał się kamieniem węgielnym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 23, 'Pan to sprawił i jest to cudowne w naszych oczach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 24, 'Oto dzień, który Pan uczynił, weselmy się i radujmy się w nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 25, 'Proszę, Panie, wybaw teraz; proszę, Panie, daj pomyślność.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 26, 'Błogosławiony, który przychodzi w imię Pana; błogosławimy wam z domu Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 27, 'Bóg jest Panem, on nas oświecił; przywiążcie baranki powrozami aż do rogów ołtarza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 28, 'Ty jesteś moim Bogiem, będę cię wysławiać; mój Boże, będę cię wywyższać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 29, 'Wysławiajcie Pana, bo jest dobry, bo jego miłosierdzie trwa na wieki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 1, 'Błogosławieni ci, których droga jest nieskalana, którzy zgodnie z prawem Pana postępują.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 2, 'Błogosławieni ci, którzy strzegą jego świadectw i szukają go całym sercem;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 3, 'Którzy nie czynią nieprawości, ale chodzą jego drogami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 4, 'Ty rozkazałeś pilnie przestrzegać twoich nakazów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 5, 'Oby moje drogi były skierowane na przestrzeganie twoich praw!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 6, 'Wtedy nie doznam wstydu, gdy będę zważał na wszystkie twoje przykazania.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 7, 'Będę cię wysławiał w szczerości serca, gdy nauczę się twoich sprawiedliwych praw.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 8, 'Będę przestrzegał twoich praw, nigdy mnie nie opuszczaj.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 9, 'W jaki sposób oczyści młodzieniec swoją ścieżkę? Gdy zachowuje się według twego słowa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 10, 'Z całego serca cię szukam, nie pozwól mi zboczyć od twoich przykazań.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 11, 'W swoim sercu zachowuję twoje słowa, aby nie zgrzeszyć przeciwko tobie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 12, 'Błogosławiony jesteś, Panie; naucz mnie twoich praw.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 13, 'Swoimi wargami opowiadam wszystkie nakazy twoich ust.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 14, 'Cieszę się drogą twoich świadectw bardziej niż z wszelkiego bogactwa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 15, 'Rozmyślam o twoich przykazaniach i przypatruję się twoim drogom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 16, 'Rozkoszuję się twoimi prawami i nie zapominam twoich słów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 17, 'Okaż dobroć swemu słudze, abym żył i przestrzegał twoich słów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 18, 'Otwórz moje oczy, abym ujrzał cuda twego prawa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 19, 'Jestem obcym na ziemi, nie ukrywaj przede mną twoich przykazań.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 20, 'Moja dusza omdlewa, tęskniąc cały czas za twoimi sądami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 21, 'Zgromiłeś pysznych, przeklęci są ci, którzy odstępują od twoich przykazań.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 22, 'Oddal ode mnie hańbę i wzgardę, gdyż przestrzegam twoich świadectw.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 23, 'Władcy też zasiadają i mówią przeciwko mnie, lecz twój sługa rozmyśla o twoich prawach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 24, 'Twoje świadectwa też są moją rozkoszą i moimi doradcami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 25, 'Moja dusza przylgnęła do prochu, ożyw mnie według twego słowa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 26, 'Opowiedziałem ci moje drogi i wysłuchałeś mnie; naucz mnie twoich praw.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 27, 'Spraw, bym zrozumiał drogę twoich nakazów, a będę rozmyślał o twoich cudownych dziełach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 28, 'Dusza moja rozpływa się we łzach ze smutku, umocnij mnie według twego słowa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 29, 'Oddal ode mnie drogę kłamstwa, a obdarz mnie swoim prawem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 30, 'Wybrałem drogę prawdy, a twoje nakazy stawiam przed sobą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 31, 'Przylgnąłem do twoich świadectw; Panie, nie pozwól mi zaznać wstydu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 32, 'Pobiegnę drogą twoich przykazań, gdy rozszerzysz moje serce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 33, 'Naucz mnie, Panie, drogi twoich praw, a będę jej strzegł aż do końca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 34, 'Daj mi rozum, abym zachował twoje prawo; żebym go przestrzegał z całego serca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 35, 'Spraw, bym chodził ścieżką twoich przykazań, gdyż w nich mam upodobanie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 36, 'Nakłoń moje serce do twoich świadectw, a nie do chciwości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 37, 'Odwróć moje oczy, aby nie patrzyły na marność, ożyw mnie na twojej drodze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 38, 'Utwierdź swoje słowo względem twego sługi, który się oddał twojej bojaźni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 39, 'Oddal ode mnie mą hańbę, której się boję, bo twoje sądy są dobre.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 40, 'Oto pragnę twoich nakazów; ożyw mnie w swej sprawiedliwości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 41, 'Niech zstąpi na mnie twoja łaskawość, Panie, twoje zbawienie według twego słowa;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 42, 'Abym mógł dać odpowiedź temu, który mi urąga, bo ufam twojemu słowu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 43, 'I nie wyjmuj z moich ust słowa prawdy, bo twoich sądów oczekuję.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 44, 'I będę zawsze strzegł twego prawa, na wieki wieków.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 45, 'A będę chodził drogą przestronną, bo szukam twoich nakazów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 46, 'Owszem, będę mówił o twoich świadectwach przed królami i nie doznam wstydu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 47, 'Będę się rozkoszował twoimi przykazaniami, które umiłowałem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 48, 'Wznoszę też swoje ręce ku twoim przykazaniom, które miłuję, i będę rozmyślał o twoich prawach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 49, 'Pamiętaj o słowie danym twemu słudze, na którym to słowie kazałeś mi polegać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 50, 'To jest moja pociecha w utrapieniu, bo twoje słowo mnie ożywia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 51, 'Pyszni bardzo się ze mnie naśmiewają, lecz nie odstępuję od twego prawa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 52, 'Pamiętam o twoich wiecznych sądach, Panie, i pocieszam się nimi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 53, 'Strach mnie ogarnął z powodu niegodziwych, którzy porzucają twoje prawo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 54, 'Twoje prawa są dla mnie pieśniami w domu mego pielgrzymowania.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 55, 'Nocą wspominam twoje imię, Panie, i strzegę twego prawa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 56, 'To mam, bo przestrzegam twoich przykazań.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 57, 'Panie, ty jesteś moim udziałem, przyrzekłem przestrzegać twoich słów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 58, 'Modliłem się przed twoim obliczem z całego serca, zlituj się nade mną według twego słowa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 59, 'Rozmyślałem nad moimi drogami i zwracałem kroki ku twoim świadectwom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 60, 'Spieszyłem się i nie zwlekałem z przestrzeganiem twoich przykazań.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 61, 'Hufce niegodziwych złupiły mnie, ale nie zapominam twojego prawa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 62, 'O północy wstaję, aby wysławiać cię za twoje sprawiedliwe sądy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 63, 'Jestem przyjacielem wszystkich, którzy boją się ciebie, i tych, którzy przestrzegają twoich przykazań.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 64, 'Panie, ziemia jest pełna twego miłosierdzia; naucz mnie twoich praw.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 65, 'Wyświadczyłeś dobro twemu słudze, Panie, według twego słowa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 66, 'Naucz mnie trafnego sądu i wiedzy, bo uwierzyłem twoim przykazaniom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 67, 'Zanim doznałem utrapienia, błądziłem; lecz teraz przestrzegam twego słowa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 68, 'Jesteś dobry i czynisz dobro; naucz mnie twoich praw.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 69, 'Zuchwali zmyślili przeciwko mnie kłamstwo, ale ja całym sercem strzegę twoich przykazań.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 70, 'Serce ich utyło jak sadło, ale ja rozkoszuję się twoim prawem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 71, 'Dobrze to dla mnie, że zostałem uciśniony, abym się nauczył twoich praw.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 72, 'Prawo twoich ust jest lepsze dla mnie niż tysiące sztuk złota i srebra.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 73, 'Twoje ręce mnie uczyniły i ukształtowały; daj mi rozum, abym się nauczył twoich przykazań;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 74, 'Bojący się ciebie, widząc mnie, będą się radować, że pokładam nadzieję w twoim słowie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 75, 'Wiem, Panie, że twoje sądy są sprawiedliwe i że słusznie mnie trapiłeś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 76, 'Proszę cię, niech mnie ucieszy twoje miłosierdzie według twego słowa do twego sługi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 77, 'Niech przyjdzie na mnie twoje miłosierdzie, abym żył; bo twoje prawo jest moją rozkoszą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 78, 'Niech się zawstydzą zuchwali, bo niesłusznie znieważali mnie, ale ja będę rozmyślać o twoich przykazaniach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 79, 'Niech się zwrócą do mnie ci, którzy się boją ciebie, i ci, którzy znają twoje świadectwa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 80, 'Niech moje serce będzie nienaganne w twoich prawach, abym nie doznał wstydu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 81, 'Moja dusza tęskni do twego zbawienia, pokładam nadzieję w twoim słowie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 82, 'Moje oczy słabną, czekając na twoje słowo, gdy mówię: Kiedy mnie pocieszysz?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 83, 'Chociaż jestem jak bukłak w dymie, jednak nie zapomniałem twoich praw.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 84, 'Ile będzie dni twego sługi? Kiedy wykonasz wyrok na tych, którzy mnie prześladują?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 85, 'Doły wykopali dla mnie zuchwali, którzy nie postępują według twego prawa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 86, 'Wszystkie twoje przykazania są prawdą; bez powodu mnie prześladują; pomóż mi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 87, 'Omal nie zgładzili mnie na ziemi; ja zaś nie porzuciłem twoich przykazań.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 88, 'Według twego miłosierdzia ożyw mnie, abym strzegł świadectwa twoich ust.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 89, 'Na wieki, o Panie, twoje słowo trwa w niebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 90, 'Z pokolenia na pokolenie twoja prawda; ugruntowałeś ziemię i trwa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 91, 'Wszystko trwa do dziś według twego rozporządzenia; to wszystko służy tobie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 92, 'Gdyby twoje prawo nie było moją rozkoszą, dawno zginąłbym w moim utrapieniu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 93, 'Nigdy nie zapomnę twoich przykazań, bo nimi mnie ożywiłeś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 94, 'Twoim jestem, wybaw mnie, bo szukam twoich przykazań.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 95, 'Czyhają na mnie niegodziwi, aby mnie stracić, ale ja rozważam twoje świadectwa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 96, 'Widziałem koniec wszelkiej doskonałości, ale twoje przykazanie jest bezkresne.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 97, 'O, jakże miłuję twoje prawo! Przez cały dzień o nim rozmyślam.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 98, 'Czynisz mnie mądrzejszym od moich nieprzyjaciół dzięki twoim przykazaniom, bo mam je zawsze przed sobą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 99, 'Stałem się rozumniejszy od wszystkich moich nauczycieli, bo rozmyślam o twoich świadectwach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 100, 'Jestem roztropniejszy od starszych, bo przestrzegam twoich przykazań.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 101, 'Powstrzymuję swoje nogi od wszelkiej drogi złej, abym strzegł twego słowa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 102, 'Nie odstępuję od twoich nakazów, bo ty mnie uczysz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 103, 'O, jakże słodkie są twoje słowa dla mego podniebienia! Są słodsze niż miód dla moich ust.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 104, 'Dzięki twoim przykazaniom nabywam rozumu; dlatego nienawidzę wszelkiej ścieżki fałszywej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 105, 'Twoje słowo jest pochodnią dla moich nóg i światłością na mojej ścieżce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 106, 'Złożyłem przysięgę i wypełnię ją, będę przestrzegał twoich sprawiedliwych nakazów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 107, 'Jestem bardzo strapiony; Panie, ożyw mnie według słowa twego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 108, 'Panie, przyjmij dobrowolne ofiary moich ust i naucz mnie twoich nakazów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 109, 'Moja dusza jest stale w niebezpieczeństwie, ale nie zapominam twojego prawa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 110, 'Niegodziwi zastawili na mnie sidła, lecz ja nie odstępuję od twoich przykazań.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 111, 'Wziąłem twoje świadectwa jako wieczne dziedzictwo, bo są radością mego serca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 112, 'Nakłoniłem moje serce, by zawsze wykonywać twoje prawa, aż do końca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 113, 'Nienawidzę chwiejnych myśli, ale miłuję twoje prawo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 114, 'Ty jesteś moją ucieczką i tarczą, pokładam nadzieję w twoim słowie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 115, 'Odstąpcie ode mnie, złoczyńcy, będę strzegł przykazania mojego Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 116, 'Wesprzyj mnie według słowa twego, abym żył, i niech nie doznam wstydu ze względu na moją nadzieję.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 117, 'Podtrzymaj mnie, a będę wybawiony i będę rozmyślał zawsze o twoich prawach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 118, 'Podeptałeś wszystkich, którzy odstępują od twoich praw, bo ich zdrada to fałsz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 119, 'Odrzucasz jak żużel wszystkich niegodziwych ziemi; dlatego miłuję twoje świadectwa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 120, 'Moje ciało drży ze strachu przed tobą, bo lękam się twoich sądów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 121, 'Sprawowałem sąd i sprawiedliwość; nie wydawaj mnie moim ciemięzcom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 122, 'Bądź poręczycielem dla twego sługi ku dobremu, aby nie uciskali mnie zuchwalcy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 123, 'Moje oczy słabną, czekając na twoje zbawienie i na słowo twojej sprawiedliwości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 124, 'Postąp ze swoim sługą według twego miłosierdzia i naucz mnie twoich praw.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 125, 'Jestem twoim sługą, daj mi rozum, abym poznał twoje świadectwa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 126, 'Już czas, Panie, abyś działał, bo naruszono twoje prawo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 127, 'Dlatego umiłowałem twoje przykazania nad złoto, nad szczere złoto.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 128, 'Bo wszystkie twoje przykazania uznaję za prawdziwe, a nienawidzę wszelkiej fałszywej drogi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 129, 'Twoje świadectwa są przedziwne, dlatego moja dusza ich strzeże.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 130, 'Początek twoich słów oświeca i daje rozum prostym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 131, 'Otwieram usta i wzdycham, bo pragnąłem twoich przykazań.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 132, 'Spójrz na mnie i zmiłuj się nade mną, jak postępujesz z tymi, którzy miłują twoje imię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 133, 'Utwierdź moje kroki w twoim słowie, niech nie panuje nade mną żadna nieprawość.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 134, 'Wybaw mnie z ludzkiego ucisku, abym strzegł twoich nakazów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 135, 'Rozjaśnij swe oblicze nad twoim sługą i naucz mnie twoich praw.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 136, 'Strumienie wód płyną z mych oczu, bo nie strzegą twego prawa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 137, 'Sprawiedliwy jesteś, Panie, i słuszne są twoje sądy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 138, 'Twoje świadectwa, które nadałeś, są sprawiedliwe i bardzo wierne.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 139, 'Gorliwość pożarła mnie, bo moi nieprzyjaciele zapominają twoje słowa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 140, 'Twoje słowo jest w pełni wypróbowane, dlatego twój sługa je kocha.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 141, 'Ja jestem mały i wzgardzony, lecz nie zapominam twoich przykazań.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 142, 'Twoja sprawiedliwość jest sprawiedliwością wieczną, a twoje prawo jest prawdą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 143, 'Ucisk i utrapienie spadły na mnie, lecz twoje przykazania są moją rozkoszą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 144, 'Sprawiedliwość twoich świadectw trwa na wieki; daj mi rozum, a będę żył.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 145, 'Wołam z całego serca, wysłuchaj mnie, o Panie, a będę strzegł twoich praw.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 146, 'Wołam do ciebie, wybaw mnie, a będę strzegł twoich świadectw.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 147, 'Wstaję przed świtem i wołam, oczekuję na twoje słowo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 148, 'Moje oczy wyprzedzają straże nocne, abym mógł rozmyślać o twoim słowie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 149, 'Panie, usłysz mój głos według twego miłosierdzia; ożyw mnie według twego wyroku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 150, 'Zbliżają się niegodziwi prześladowcy, są daleko od twego prawa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 151, 'Blisko jesteś, Panie, i wszystkie twoje przykazania są prawdą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 152, 'Od dawna wiem o twoich świadectwach, że ugruntowałeś je na wieki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 153, 'Wejrzyj na moje utrapienie i wyzwól mnie, bo nie zapomniałem twojego prawa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 154, 'Broń mojej sprawy i wybaw mnie; ożyw mnie według twego słowa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 155, 'Zbawienie jest daleko od niegodziwych, bo nie szukają twoich praw.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 156, 'Wielka jest twoja litość, Panie; ożyw mnie według twoich wyroków.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 157, 'Liczni są moi prześladowcy i nieprzyjaciele; lecz nie uchylam się od twoich świadectw.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 158, 'Widziałem przestępców i czułem odrazę, że nie przestrzegali twego słowa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 159, 'Patrz, jak miłuję twoje nakazy, Panie; ożyw mnie według twego miłosierdzia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 160, 'Podstawą twego słowa jest prawda, a wszelki wyrok twojej sprawiedliwości trwa na wieki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 161, 'Władcy prześladują mnie bez przyczyny; moje serce zaś boi się twoich słów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 162, 'Raduję się z twego słowa jak ten, który znajduje wielki łup.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 163, 'Nienawidzę kłamstwa i brzydzę się nim, ale miłuję twoje prawo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 164, 'Chwalę cię siedem razy dziennie za twoje sprawiedliwe sądy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 165, 'Wielki pokój dla tych, którzy miłują twoje prawo, a nie doznają żadnego zgorszenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 166, 'Panie, oczekuję na twoje zbawienie i zachowuję twoje przykazania.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 167, 'Moja dusza przestrzega twoich świadectw, bo bardzo je miłuję.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 168, 'Przestrzegam twoich przykazań i świadectw, bo wszystkie moje drogi są przed tobą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 169, 'Panie, niech dotrze moje wołanie przed twoje oblicze, daj mi zrozumienie według słowa twego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 170, 'Niech dojdzie moja prośba przed twoje oblicze, ocal mnie według twojej obietnicy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 171, 'Moje wargi wygłoszą chwałę, gdy nauczysz mnie twoich praw.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 172, 'Mój język będzie głosił twoje słowo, bo wszystkie twoje przykazania są sprawiedliwością.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 173, 'Niech twoja ręka będzie mi pomocą, bo wybrałem twoje przykazania.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 174, 'Panie, pragnę twego zbawienia, a twoje prawo jest moją rozkoszą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 175, 'Pozwól mojej duszy żyć, a będzie cię chwalić; niech twoje nakazy będą dla mnie pomocą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 176, 'Błądzę jak zgubiona owca; szukaj twego sługi, bo nie zapominam twoich przykazań.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 1, 'Pieśń stopni. Wołałem do Pana w swoim utrapieniu i wysłuchał mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 2, 'Ocal, Panie, moją duszę od warg kłamliwych i od zdradliwego języka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 3, 'Cóż będzie ci dane albo co się stanie z tobą, zdradliwy języku?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 4, 'Ostre strzały mocarza i węgle z jałowca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 5, 'Biada mi, że przebywam w Meszek i mieszkam w namiotach Kedaru.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 6, 'Moja dusza długo mieszka z tymi, którzy nienawidzą pokoju.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 7, 'Ja jestem za pokojem, ale gdy o tym mówię, oni są za wojną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 1, 'Pieśń stopni. Oczy moje podnoszę ku górom, skąd przyjdzie mi pomoc.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 2, 'Moja pomoc jest od Pana, który stworzył niebo i ziemię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 3, 'Nie pozwoli zachwiać się twojej nodze; twój stróż nie drzemie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 4, 'Oto ten, który strzeże Izraela, nie zdrzemnie się ani nie zaśnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 5, 'Pan jest twoim stróżem, Pan jest cieniem twoim po twojej prawicy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 6, 'Słońce nie porazi cię za dnia ani księżyc w nocy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 7, 'Pan będzie cię strzegł od wszelkiego zła; on będzie strzegł twojej duszy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 8, 'Pan będzie strzegł twego wyjścia i przyjścia, odtąd aż na wieki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 1, 'Pieśń stopni Dawida. Uradowałem się, gdy mi powiedziano: Pójdziemy do domu Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 2, 'Nasze nogi stanęły w twoich bramach, o Jeruzalem!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 3, 'Jeruzalem, pięknie budowane jak miasto, w jedną całość zespolone;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 4, 'Bo tam wstępują pokolenia, pokolenia Pana, do świadectwa Izraela, aby wysławiać imię Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 5, 'Tam bowiem są postawione trony sądu, trony domu Dawida.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 6, 'Proście o pokój dla Jeruzalem: Niech się szczęści tym, którzy cię miłują.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 7, 'Niech będzie pokój w twoich murach i spokój w twoich pałacach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 8, 'Ze względu na moich braci i dla moich przyjaciół będę teraz ci życzył pokoju.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 9, 'Ze względu na dom Pana, naszego Boga, będę zabiegał o twoje dobro.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 123, 1, 'Pieśń stopni. Do ciebie podnoszę moje oczy, który mieszkasz w niebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 123, 2, 'Oto jak oczy sług są zwrócone na ręce ich panów i jak oczy służącej na ręce jej pani, tak nasze oczy na Pana, Boga naszego, aż się zmiłuje nad nami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 123, 3, 'Zmiłuj się nad nami, Panie; zmiłuj się nad nami, bo jesteśmy nad miarę nasyceni wzgardą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 123, 4, 'Nasza dusza jest nad miarę nasycona szyderstwem bezbożnych i wzgardą pysznych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 1, 'Pieśń stopni Dawida. Gdyby Pan nie był z nami, niech powie teraz Izrael;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 2, 'Gdyby Pan nie był z nami, gdy ludzie powstawali przeciwko nam;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 3, 'Wtedy połknęliby nas żywcem, gdy płonęli gniewem przeciwko nam;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 4, 'Wtedy wody zalałyby nas, a potok porwałby nasze dusze;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 5, 'Wtedy gwałtowne wody porwałyby nasze dusze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 6, 'Błogosławiony Pan, który nas nie wydał na pastwę ich zębom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 7, 'Nasza dusza umknęła jak ptak z sideł ptaszników; sidła się podarły, a my uciekliśmy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 8, 'Nasza pomoc jest w imieniu Pana, który stworzył niebo i ziemię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 1, 'Pieśń stopni. Ci, którzy ufają Panu, są jak góra Syjon, która się nie porusza, ale trwa na wieki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 2, 'Jak góry otaczają Jeruzalem, tak Pan otacza swój lud, teraz i na wieki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 3, 'Nie zaciąży bowiem berło niegodziwych nad losem sprawiedliwych, by sprawiedliwi nie wyciągali swych rąk ku nieprawości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 4, 'Czyń dobrze, Panie, dobrym i tym, którzy są prawego serca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 5, 'A tych, którzy zbaczają na kręte swe drogi, niech Pan odprawi wraz z czyniącymi nieprawość. Niech będzie pokój nad Izraelem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 1, 'Pieśń stopni. Gdy Pan odwrócił niewolę Syjonu, byliśmy jak we śnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 2, 'Wtedy usta nasze napełniły się śmiechem, a nasz język radością; wtedy mówiono między narodami: Pan uczynił wielkie rzeczy dla nich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 3, 'Pan uczynił dla nas wielkie rzeczy i z tego się radujemy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 4, 'Odwróć, Panie, naszą niewolę jak strumienie na południu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 5, 'Ci, którzy sieją we łzach, będą żąć z radością.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 6, 'Kto wychodzi z płaczem, niosąc drogie ziarno, powróci z radością, przynosząc swoje snopy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 1, 'Pieśń stopni dla Salomona. Jeśli Pan nie zbuduje domu, na próżno trudzą się ci, którzy go wznoszą; jeśli Pan nie będzie strzegł miasta, na próżno czuwa strażnik.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 2, 'Daremne jest dla was wstawać rano, wysiadywać do późna i jeść chleb boleści, bo to on daje sen swemu umiłowanemu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 3, 'Oto dzieci są dziedzictwem od Pana, a owoc łona nagrodą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 4, 'Jak strzały w ręku mocarza, tak są dzieci zrodzone za młodu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 5, 'Błogosławiony mąż, który napełnił nimi swój kołczan; nie doznają wstydu, gdy się w bramie będą rozprawiać z nieprzyjaciółmi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 1, 'Pieśń stopni. Błogosławiony każdy, kto się boi Pana; kto kroczy jego drogami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 2, 'Bo będziesz spożywać z pracy twoich rąk; będziesz błogosławionym i będzie ci się dobrze wiodło.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 3, 'Twoja żona będzie jak płodna winorośl obok twego domu; twoje dzieci jak sadzonki oliwne dokoła twego stołu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 4, 'Oto tak będzie błogosławiony mąż, który się boi Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 5, 'Niech ci Pan błogosławi z Syjonu, abyś oglądał dobro Jeruzalem po wszystkie dni twego życia;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 6, 'I abyś oglądał dzieci twoich synów i pokój nad Izraelem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 1, 'Pieśń stopni. Bardzo mnie uciskali od mojej młodości, niech powie teraz Izrael;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 2, 'Bardzo mnie uciskali od mojej młodości, lecz mnie nie przemogli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 3, 'Zorali mój grzbiet oracze i długie bruzdy porobili.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 4, 'Ale Pan jest sprawiedliwy; poprzecinał powrozy niegodziwych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 5, 'Niech się zawstydzą i cofną wszyscy, którzy nienawidzą Syjonu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 6, 'Będą jak trawa na dachu, która usycha, zanim zakwitnie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 7, 'Którą żniwiarz nie napełni swej garści ani swego naręcza ten, który wiąże snopy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 8, 'I nie powiedzą przechodnie: Niech będzie z wami błogosławieństwo Pana albo: Błogosławimy wam w imię Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 1, 'Pieśń stopni. Z głębokości wołam do ciebie, Panie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 2, 'Panie, wysłuchaj mego głosu. Nakłoń swych uszu na głos mojego błagania.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 3, 'Panie, jeśli będziesz zważał na nieprawości, o Panie, któż się ostoi?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 4, 'Ale u ciebie jest przebaczenie, aby się ciebie bano.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 5, 'Oczekuję Pana, moja dusza oczekuje; i w jego słowie pokładam nadzieję.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 6, 'Moja dusza oczekuje Pana bardziej niż strażnicy świtu, bardziej niż ci, którzy strzegą do poranka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 7, 'Niech Izrael oczekuje Pana; u Pana bowiem jest miłosierdzie i u niego obfite odkupienie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 8, 'On sam odkupi Izraela ze wszystkich jego nieprawości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 131, 1, 'Pieśń stopni Dawida. Panie, moje serce nie wywyższa się i moje oczy nie są wyniosłe ani nie ubiegam się o wielkie rzeczy albo zbyt cudowne dla mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 131, 2, 'Doprawdy uciszyłem i uspokoiłem swoją duszę jak dziecko odstawione od piersi swej matki; moja dusza jest jak dziecko odstawione.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 131, 3, 'Niech Izrael pokłada nadzieję w Panu odtąd na wieki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 1, 'Pieśń stopni. Pamiętaj, Panie, Dawida i wszystkie jego utrapienia;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 2, 'Jak przysiągł Panu i ślubował potężnemu Bogu Jakuba, mówiąc:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 3, 'Zaprawdę, nie wejdę do przybytku, do mego domu, i nie wstąpię na posłanie mego łoża;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 4, 'I nie dam zasnąć swoim oczom ani drzemać swoim powiekom;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 5, 'Póki nie znajdę miejsca dla Pana, mieszkania dla potężnego Boga Jakuba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 6, 'Oto usłyszeliśmy o niej w Efrata, znaleźliśmy ją na polach leśnych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 7, 'Wejdźmy do jego przybytków, oddajmy pokłon u podnóżka jego stóp.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 8, 'Powstań, Panie, i wejdź do miejsca twego odpoczynku, ty i arka twojej mocy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 9, 'Niech twoi kapłani ubiorą się w sprawiedliwość, a twoi święci niech się radują.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 10, 'Ze względu na Dawida, twego sługę, nie odtrącaj oblicza twego pomazańca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 11, 'Przysiągł Pan Dawidowi prawdę i nie wycofa się z tego: Z owocu twoich bioder posadzę na twoim tronie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 12, 'Jeśli twoi synowie będą strzegli mojego przymierza i moich świadectw, których ich nauczę, to wtedy i ich synowie aż na wieki będą siedzieli na twoim tronie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 13, 'Pan bowiem wybrał Syjon i upodobał go sobie na mieszkanie:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 14, 'To będzie mój odpoczynek aż na wieki; tu będę mieszkał, bo go sobie upodobałem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 15, 'Będę obficie błogosławił jego żywność, a jego ubogich nasycę chlebem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 16, 'Jego kapłanów przyodzieję zbawieniem, a jego święci będą wołać radośnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 17, 'Tam sprawię, że zakwitnie róg Dawida; tam zgotuję pochodnię memu pomazańcowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 18, 'Okryję jego nieprzyjaciół wstydem, ale nad nim rozkwitnie jego korona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 133, 1, 'Pieśń stopni Dawida. Oto jak dobrze i jak miło, gdy bracia zgodnie mieszkają.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 133, 2, 'Jest to jak wyborny olejek na głowę, który spływa na brodę, na brodę Aarona; który spływa na brzeg jego szat;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 133, 3, 'Jak rosa Hermonu, która opada na góry Syjon; tam bowiem Pan daje błogosławieństwo i życie na wieki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 134, 1, 'Pieśń stopni. Oto błogosławcie Pana, wszyscy słudzy Pana, którzy nocami stoicie w domu Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 134, 2, 'Wznieście wasze ręce ku świątyni i błogosławcie Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 134, 3, 'Niech cię błogosławi z Syjonu Pan, który stworzył niebo i ziemię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 1, 'Alleluja. Chwalcie imię Pana; chwalcie, słudzy Pana;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 2, 'Którzy stoicie w domu Pana, w przedsionkach domu naszego Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 3, 'Chwalcie Pana, bo Pan jest dobry; śpiewajcie jego imieniu, bo jest wdzięczne.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 4, 'Pan bowiem wybrał sobie Jakuba i Izraela na swoją szczególną własność.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 5, 'Wiem, że wielki jest Pan, a nasz Pan jest ponad wszystkimi bogami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 6, 'Wszystko, co Pan chce, to czyni na niebie i na ziemi, w morzu i we wszystkich głębinach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 7, 'On sprawia, że mgły wznoszą się z krańców ziemi; wywołuje błyskawice i deszcz, wydobywa wiatr ze swoich skarbców;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 8, 'Poraził pierworodnych w Egipcie, od człowieka aż do zwierzęcia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 9, 'Zesłał znaki i cuda pośród ciebie, Egipcie; na faraona i na wszystkie jego sługi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 10, 'Pobił wiele narodów i zgładził potężnych królów;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 11, 'Sychona, króla Amorytów, i Oga, króla Baszanu, i wszystkie królestwa Kanaanu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 12, 'I dał ich ziemię w dziedzictwo, w dziedzictwo Izraelowi, swemu ludowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 13, 'Twoje imię, Panie, trwa na wieki; twoja pamięć, Panie, z pokolenia na pokolenie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 14, 'Bo Pan będzie sądzić swój lud i zmiłuje się nad swymi sługami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 15, 'Bożki pogan to srebro i złoto, dzieło ludzkich rąk.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 16, 'Mają usta, ale nie mówią; mają oczy, ale nie widzą;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 17, 'Mają uszy, ale nie słyszą, i nie ma oddechu w ich ustach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 18, 'Podobni są do nich ci, którzy je robią, i wszyscy, którzy w nich pokładają ufność.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 19, 'Domu Izraela, błogosławcie Pana; domu Aarona, błogosławcie Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 20, 'Domu Lewiego, błogosławcie Pana; wy, którzy się boicie Pana, błogosławcie Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 21, 'Niech będzie błogosławiony z Syjonu Pan, który mieszka w Jeruzalem. Alleluja.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 1, 'Wysławiajcie Pana, bo jest dobry; bo na wieki jego miłosierdzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 2, 'Wysławiajcie Boga bogów, bo na wieki jego miłosierdzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 3, 'Wysławiajcie Pana panów, bo na wieki jego miłosierdzie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 4, 'Tego, który sam czyni wielkie cuda, bo na wieki jego miłosierdzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 5, 'Tego, który w mądrości uczynił niebiosa, bo na wieki jego miłosierdzie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 6, 'Tego, który rozpostarł ziemię nad wodami, bo na wieki jego miłosierdzie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 7, 'Tego, który uczynił wielkie światła, bo na wieki jego miłosierdzie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 8, 'Słońce, aby panowało we dnie, bo na wieki jego miłosierdzie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 9, 'Księżyc i gwiazdy, aby panowały w nocy, bo na wieki jego miłosierdzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 10, 'Tego, który poraził Egipt w jego pierworodnych, bo na wieki jego miłosierdzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 11, 'Tego, który wyprowadził spośród niego Izraela, bo na wieki jego miłosierdzie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 12, 'Mocną ręką i wyciągniętym ramieniem, bo na wieki jego miłosierdzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 13, 'Tego, który rozdzielił Morze Czerwone na części, bo na wieki jego miłosierdzie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 14, 'I przeprowadził środkiem Izraela, bo na wieki jego miłosierdzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 15, 'I wrzucił faraona z jego wojskiem w Morze Czerwone, bo na wieki jego miłosierdzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 16, 'Tego, który prowadził swój lud przez pustynię, bo na wieki jego miłosierdzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 17, 'Tego, który pobił wielkich królów, bo na wieki jego miłosierdzie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 18, 'I zgładził potężnych królów, bo na wieki jego miłosierdzie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 19, 'Sychona, króla Amorytów, bo na wieki jego miłosierdzie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 20, 'I Oga, króla Baszanu, bo na wieki jego miłosierdzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 21, 'I dał ich ziemię w dziedzictwo, bo na wieki jego miłosierdzie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 22, 'W dziedzictwo Izraelowi, swemu słudze, bo na wieki jego miłosierdzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 23, 'Tego, który w naszym poniżeniu pamiętał o nas, bo na wieki jego miłosierdzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 24, 'I wybawił nas od naszych nieprzyjaciół, bo na wieki jego miłosierdzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 25, 'Tego, który daje pokarm wszelkiemu ciału, bo na wieki jego miłosierdzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 26, 'Wysławiajcie Boga niebios, bo na wieki jego miłosierdzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 1, 'Nad rzekami Babilonu, tam siedzieliśmy i płakaliśmy, wspominając Syjon.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 2, 'Na wierzbach tamtej krainy zawiesiliśmy nasze harfy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 3, 'Bo tam ci, którzy nas wzięli w niewolę, żądali od nas pieśni, a nasi ciemięzcy – radości, mówiąc: Śpiewajcie nam którąś z pieśni Syjonu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 4, 'Jakże możemy śpiewać pieśń Pana na obcej ziemi?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 5, 'Jeśli zapomnę o tobie, Jeruzalem, niech sama o sobie zapomni moja prawica.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 6, 'Niech mi język przylgnie do podniebienia, jeśli nie będę pamiętał o tobie, jeśli nie postawię Jeruzalem ponad największą moją radość.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 7, 'Pamiętaj, Panie, synów Edomu i dzień Jeruzalem, gdy mówili: Zburzcie, zburzcie je aż do jego fundamentu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 8, 'O córko Babilonu, i ty będziesz spustoszona. Błogosławiony, kto ci odpłaci za zło, jakie nam uczyniłaś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 9, 'Błogosławiony, kto schwyci i roztrzaska twe dzieci o skałę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 1, 'Psalm Dawida. Będę cię wysławiał, Panie, z całego mego serca; będę ci śpiewał wobec bogów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 2, 'Oddam ci pokłon ku twej świętej świątyni i będę wysławiał twoje imię za miłosierdzie twoje i prawdę; bo wywyższyłeś twoje imię i słowo ponad wszystko.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 3, 'W dniu, gdy cię wzywałem, wysłuchałeś mnie i mocą posiliłeś moją duszę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 4, 'Wszyscy królowie będą cię wysławiali, Panie, gdy usłyszą słowa twoich ust.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 5, 'I będą śpiewali o drogach Pana, że wielka jest chwała Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 6, 'A choć wywyższony jest Pan, jednak ma wzgląd na pokornego, a wyniosłego poznaje z daleka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 7, 'Choćbym chodził pośród utrapienia, ożywisz mnie; wyciągniesz swoją rękę przeciw gniewowi moich nieprzyjaciół, a twoja prawica mnie wybawi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 8, 'Pan dokona wszystkiego za mnie. Panie, twoje miłosierdzie trwa na wieki; nie opuszczaj dzieł twoich rąk.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 1, 'Przewodnikowi chóru. Psalm Dawida. Panie, przeniknąłeś mnie i znasz mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 2, 'Wiesz, kiedy siedzę i wstaję, z daleka znasz moje myśli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 3, 'Otaczasz moją ścieżkę i spoczynek, wszystkie moje drogi są ci znane.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 4, 'Zanim na moim języku pojawi się słowo, ty, Panie, już je znasz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 5, 'Otaczasz mnie z tyłu i z przodu i położyłeś na mnie twoją rękę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 6, 'Zbyt cudowna jest dla mnie twoja wiedza; jest wzniosła, nie mogę jej pojąć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 7, 'Dokąd ujdę przed twoim duchem? Dokąd ucieknę przed twoim obliczem?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 8, 'Jeśli wstąpię do nieba, jesteś tam; jeśli przygotuję sobie posłanie w piekle, tam też jesteś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 9, 'Gdybym wziął skrzydła zorzy porannej, aby zamieszkać na krańcu morza;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 10, 'I tam twoja ręka prowadziłaby mnie i twoja prawica by mnie podtrzymała.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 11, 'Jeśli powiem: Na pewno zakryją mnie ciemności, to i noc będzie dokoła mnie światłem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 12, 'Nawet ciemność nic przed tobą nie skryje, dla ciebie noc świeci jak dzień, ciemność jest jak światłość.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 13, 'Ty bowiem panujesz nad moimi nerkami; okryłeś mnie w łonie mojej matki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 14, 'Wysławiam cię, bo zostałem stworzony w sposób zadziwiający i cudowny; przedziwne są twoje dzieła, a moja dusza zna je bardzo dobrze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 15, 'Żadna moja kość nie była zakryta przed tobą, gdy zostałem stworzony w skrytości i misternie złożony w głębiach ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 16, 'Twoje oczy widziały niedoskonały płód mego ciała; w twojej księdze są zapisane wszystkie moje członki i dni, w które były kształtowane, gdy jeszcze żadnego z nich nie było.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 17, 'Jak drogie są dla mnie twoje myśli, Boże! Jak wielka jest ich liczba!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 18, 'Gdybym chciał je zliczyć, byłoby ich więcej niż piasku; gdy się budzę, jeszcze jestem z tobą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 19, 'Zgładzisz, Boże, niegodziwego; niech odstąpią ode mnie ludzie krwawi;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 20, 'Którzy mówią obrzydliwości przeciwko tobie, twoi wrogowie nadaremnie biorą twoje imię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 21, 'Czy nie nienawidzę tych, Panie, którzy nienawidzą ciebie? I nie brzydzę się tymi, którzy przeciwko tobie powstają?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 22, 'Nienawidzę ich pełnią nienawiści i mam ich za wrogów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 23, 'Przeniknij mnie, Boże, i poznaj moje serce; wypróbuj mnie i poznaj moje myśli;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 24, 'I zobacz, czy jest we mnie droga nieprawości, a prowadź mnie drogą wieczną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 1, 'Przewodnikowi chóru. Psalm Dawida. Wybaw mnie, Panie, od złego człowieka; strzeż mnie od okrutnika;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 2, 'Od tych, którzy knują w sercu złe rzeczy, każdego dnia zbierają się na wojnę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 3, 'Wyostrzają swe języki jak węże, jad żmii pod ich wargami. Sela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 4, 'Zachowaj mnie, Panie, od rąk niegodziwego, strzeż mnie od okrutnika; od tych, którzy postanowili zwalić mnie z nóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 5, 'Pyszni zastawili na mnie sidła i przygotowali powrozy; rozciągnęli sieci przy ścieżce; zastawili na mnie pułapkę. Sela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 6, 'Powiedziałem Panu: Ty jesteś moim Bogiem; wysłuchaj, Panie, głosu moich błagań.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 7, 'Panie Boże, mocy mego zbawienia, który osłaniasz moją głowę w dniu bitwy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 8, 'Nie spełniaj, Panie, pragnień niegodziwego; nie wspomagaj jego złych zamysłów, aby się nie podniósł. Sela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 9, 'Niech nieprawość ich własnych warg okryje wodza tych, którzy mnie otoczyli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 10, 'Niech na nich spadną rozżarzone węgle; niech będą wrzuceni do ognia i do głębokich dołów, by już nie powstali.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 11, 'Niech oszczerca nie będzie utwierdzony na ziemi, a człowiek okrutny upadnie przygnieciony złem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 12, 'Wiem, że Pan ujmie się za strapionym i pomści krzywdę nędzarzy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 13, 'Zaprawdę sprawiedliwi będą wysławiać twoje imię, a prawi będą mieszkać przed twoim obliczem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 1, 'Pieśń Dawida. Panie, wołam do ciebie, pospiesz ku mnie; wysłuchaj mego głosu, gdy wołam do ciebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 2, 'Niech moja modlitwa będzie przed tobą jak kadzidło, a podniesienie moich rąk jak wieczorna ofiara.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 3, 'Panie, postaw straż przy moich ustach; strzeż drzwi moich warg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 4, 'Nie skłaniaj mego serca ku złemu, abym nie popełniał czynów niegodziwych z ludźmi, którzy czynią nieprawość, i żebym się nie karmił ich rozkoszami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 5, 'Niech mnie bije sprawiedliwy, a przyjmę to za miłosierdzie; i niech mnie strofuje, a będzie mi to jak wyborny olejek, który nie zaszkodzi mojej głowie; bo jeszcze będę się modlił w czasie ich nieszczęścia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 6, 'Gdy ich sędziowie będą zrzuceni do miejsc skalistych, usłyszą moje słowa, bo są wdzięczne.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 7, 'Jak gdyby kto rąbał i łupał drwa na ziemi, tak nasze kości są rozrzucone przy wejściu do grobu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 8, 'Ale podnoszę swoje oczy do ciebie, Boże, Panie; tobie ufam, nie porzucaj mojej duszy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 9, 'Strzeż mnie od sidła, które zastawili na mnie, i od pułapek czyniących nieprawość.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 10, 'Niech niegodziwi wpadną w swoje sieci, podczas gdy ja ujdę cało.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 1, 'Pieśń pouczająca Dawida, jego modlitwa, gdy był w jaskini. Swoim głosem wołam do Pana; swoim głosem modlę się do Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 2, 'Wylewam przed nim swoją troskę i opowiadam mu swoje utrapienie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 3, 'Gdy mój duch jest we mnie zdruzgotany, ty znasz moją ścieżkę; na drodze, którą chodziłem, zastawili na mnie sidło.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 4, 'Oglądałem się na prawo i spojrzałem, ale nie było nikogo, kto mnie znał; nie było dla mnie ucieczki, nikt się nie troszczył o moją duszę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 5, 'Panie, wołam do ciebie, mówiąc: Ty jesteś moją nadzieją, ty jesteś moim udziałem w ziemi żyjących.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 6, 'Wysłuchaj mego wołania, bo jestem bardzo udręczony; ocal mnie od moich prześladowców, bo są mocniejsi ode mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 7, 'Wyprowadź moją duszę z więzienia, abym chwalił twoje imię; sprawiedliwi otoczą mnie, gdy okażesz mi dobroć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 1, 'Psalm Dawida. Panie, wysłuchaj mojej modlitwy i nadstaw ucha na moje prośby; wysłuchaj mnie w swojej wierności i sprawiedliwości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 2, 'A nie stawiaj przed sądem swojego sługi, bo nikt z żyjących nie będzie usprawiedliwiony przed tobą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 3, 'Nieprzyjaciel bowiem prześladuje moją duszę, powalił na ziemię moje życie; sprawił, że muszę mieszkać w ciemności jak dawno umarły.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 4, 'I mój duch jest zdruzgotany we mnie, serce we mnie niszczeje.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 5, 'Wspominam dawne dni, rozmyślam o wszystkich twoich dziełach i rozważam czyny twoich rąk.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 6, 'Wyciągam ku tobie swoje ręce; moja dusza pragnie ciebie jak sucha ziemia. Sela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 7, 'Wysłuchaj mnie prędko, Panie; mój duch omdlewa; nie ukrywaj przede mną swego oblicza, bym się nie stał jak ci, którzy schodzą do dołu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 8, 'Spraw, abym rano słyszał o twoim miłosierdziu, bo tobie ufam; oznajmij mi drogę, którą mam chodzić, bo do ciebie wznoszę moją duszę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 9, 'Ocal mnie od moich wrogów, Panie; do ciebie się uciekam.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 10, 'Naucz mnie czynić twoją wolę, bo ty jesteś moim Bogiem; twój duch jest dobry; prowadź mnie do ziemi prawości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 11, 'Ożyw mnie, Panie, dla twojego imienia; ze względu na twoją sprawiedliwość wyprowadź moją duszę z utrapienia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 12, 'W swoim miłosierdziu wytrać moich wrogów i zgładź wszystkich przeciwników mojej duszy, bo jestem twoim sługą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 1, 'Pieśń Dawida. Błogosławiony Pan, moja skała, który zaprawia moje ręce do walki, a moje palce do wojny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 2, 'Moje miłosierdzie i moja twierdza, moja warownia, mój wybawiciel i moja tarcza; ten, któremu ufam, on mi poddaje mój lud.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 3, 'Panie, czym jest człowiek, że zwracasz na niego uwagę? Albo syn człowieczy, że go poważasz?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 4, 'Człowiek jest podobny do marności; jego dni jak cień, który przemija.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 5, 'Panie, nachyl twoich niebios i zstąp; dotknij gór, a będą dymić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 6, 'Zabłyśnij błyskawicą i rozprosz ich; wypuść swoje strzały i poraź ich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 7, 'Wyciągnij swą rękę z wysokości; wybaw mnie i ocal z wielkich wód, z rąk cudzoziemców;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 8, 'Których usta mówią kłamstwo, a ich prawica jest prawicą fałszywą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 9, 'Boże, zaśpiewam tobie nową pieśń; będę ci śpiewał przy dźwiękach lutni i harfy o dziesięciu strunach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 10, 'Ty dajesz królom zwycięstwo, a Dawida, swego sługę, wybawiasz od srogiego miecza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 11, 'Wybaw mnie i ocal z rąk cudzoziemców, których usta mówią kłamstwo, a ich prawica jest prawicą fałszywą;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 12, 'Aby nasi synowie byli jak szczepy wyrosłe w swojej młodości, a nasze córki jak kamienie węgielne, wyrzeźbione na wzór pałacu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 13, 'Aby nasze spichlerze były pełne, obficie zaopatrzone we wszystko, nasze stada rodziły tysiące i dziesięć tysięcy w naszych zagrodach;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 14, 'Aby nasze woły były tłuste, żeby nie było włamań ani ucieczek, ani narzekania na naszych ulicach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 15, 'Błogosławiony lud, któremu się tak dzieje. Błogosławiony lud, którego Bogiem jest Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 1, 'Pieśń pochwalna Dawida. Będę cię wywyższać, Boże mój, królu mój, i będę błogosławić twe imię na wieki wieków.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 2, 'Każdego dnia będę cię błogosławić i chwalić twoje imię na wieki wieków.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 3, 'Wielki jest Pan i godzien wielkiej chwały, a jego wielkość jest niezbadana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 4, 'Pokolenie pokoleniu będzie wychwalać twoje dzieła i opowiadać o twoich potężnych czynach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 5, 'Będę wysławiać wspaniałość chwały twojego majestatu i twoje cudowne dzieła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 6, 'I będą mówić o mocy twoich straszliwych czynów, a ja będę opowiadać twoją wielkość.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 7, 'Będą wysławiać pamięć twojej wielkiej dobroci i śpiewać o twojej sprawiedliwości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 8, 'Łaskawy jest Pan i litościwy, nieskory do gniewu i bardzo miłosierny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 9, 'Dobry jest Pan dla wszystkich, a jego miłosierdzie nad wszystkimi jego dziełami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 10, 'Twoje dzieła będą cię wysławiać, Panie, a twoi święci będą ci błogosławić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 11, 'Będą opowiadać o chwale twego królestwa i mówić o twojej potędze;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 12, 'Aby oznajmić synom ludzkim jego potężne czyny i wspaniałą chwałę jego królestwa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 13, 'Twoje królestwo jest królestwem wiecznym, a twoje panowanie trwa przez wszystkie pokolenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 14, 'Pan podtrzymuje wszystkich, którzy upadają, i podnosi wszystkich przygnębionych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 15, 'Oczy wszystkich oczekują ciebie, a ty im dajesz pokarm we właściwym czasie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 16, 'Otwierasz swoją rękę i nasycasz do woli wszystko, co żyje.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 17, 'Sprawiedliwy jest Pan we wszystkich swoich drogach i miłosierny we wszystkich swoich dziełach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 18, 'Bliski jest Pan wszystkim, którzy go wzywają; wszystkim, którzy go wzywają w prawdzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 19, 'Spełni pragnienia tych, którzy się go boją; usłyszy ich wołanie i wybawi ich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 20, 'Pan strzeże wszystkich, którzy go miłują; a wytraci wszystkich niegodziwych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 21, 'Moje usta będą głosić chwałę Pana i niech wszelkie ciało błogosławi jego święte imię na wieki wieków.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 1, 'Alleluja. Chwal, duszo moja, Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 2, 'Będę chwalić Pana, póki żyję; będę śpiewał memu Bogu, póki będę istniał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 3, 'Nie pokładajcie ufności we władcach ani w żadnym synu ludzkim, u którego nie ma wybawienia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 4, 'Opuszcza go duch i wraca do swojej ziemi; w tymże dniu zginą wszystkie jego myśli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 5, 'Błogosławiony ten, kogo pomocą jest Bóg Jakuba, kto nadzieję pokłada w Panu, jego Bogu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 6, 'Który uczynił niebo i ziemię, morze i wszystko, co w nich jest; który dochowuje prawdy na wieki;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 7, 'Który oddaje sprawiedliwość pokrzywdzonym i daje chleb głodnym; Pan uwalnia więźniów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 8, 'Pan otwiera oczy ślepych; Pan podnosi przygnębionych; Pan miłuje sprawiedliwych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 9, 'Pan strzeże przychodniów, wspomaga sierotę i wdowę, ale krzyżuje drogę niegodziwych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 10, 'Pan będzie królował na wieki, twój Bóg, o Syjonie, z pokolenia na pokolenie. Alleluja.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 1, 'Chwalcie Pana, bo dobrze jest śpiewać naszemu Bogu; jest to bowiem miłe i piękna jest chwała.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 2, 'Pan buduje Jeruzalem i gromadzi rozproszonych Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 3, 'On uzdrawia skruszonych w sercu i opatruje ich rany.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 4, 'On liczy gwiazdy, nazywa każdą z nich po imieniu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 5, 'Wielki jest nasz Pan i zasobny w moc; jego mądrość jest niezmierzona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 6, 'Pan podnosi pokornych, a niegodziwych poniża aż do ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 7, 'Śpiewajcie Panu z dziękczynieniem; śpiewajcie naszemu Bogu przy dźwiękach harfy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 8, 'Który okrywa niebiosa obłokami i przygotowuje deszcz dla ziemi; który sprawia, że trawa rośnie na górach;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 9, 'Który daje pokarm bydłu i młodym krukom wołającym do niego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 10, 'Nie lubuje się w mocy konia ani nie ma upodobania w goleniach mężczyzny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 11, 'Pan ma upodobanie w tych, którzy się go boją, którzy ufają jego miłosierdziu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 12, 'Chwal Pana, Jeruzalem; chwal swego Boga, Syjonie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 13, 'On bowiem umacnia zasuwy twoich bram i błogosławi synów twoich pośród ciebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 14, 'Zapewnia pokój w twoich granicach i syci cię najwyborniejszą pszenicą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 15, 'On wysyła swój rozkaz na ziemię; szybko biegnie jego słowo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 16, 'On daje śnieg jak wełnę, rozsypuje szron jak popiół.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 17, 'Rzuca swój lód jak okruchy; któż ostoi się przed jego zimnem?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 18, 'Posyła swoje słowo i lody topnieją; wionie swym wiatrem i wody spływają.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 19, 'Oznajmia swe słowo Jakubowi, swe prawa i sądy Izraelowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 20, 'Nie uczynił tak żadnemu narodowi, nie poznali jego sądów. Alleluja.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 1, 'Alleluja. Chwalcie Pana z niebios, chwalcie go na wysokościach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 2, 'Chwalcie go, wszyscy jego aniołowie; chwalcie go, wszystkie jego zastępy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 3, 'Chwalcie go, słońce i księżycu; chwalcie go, wszystkie gwiazdy święcące.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 4, 'Chwalcie go, niebiosa nad niebiosami i wody, które są nad niebiosami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 5, 'Niech chwalą imię Pana, on bowiem rozkazał i zostały stworzone.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 6, 'I ustanowił je na wieki wieków; dał prawo, które nie przeminie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 7, 'Chwalcie Pana z ziemi, smoki i wszystkie głębiny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 8, 'Ogniu i gradzie, śniegu i paro, wietrze gwałtowny, wykonujący jego rozkaz;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 9, 'Góry i wszystkie pagórki, drzewa owocowe i wszystkie cedry;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 10, 'Zwierzęta i wszelkie bydło, istoty pełzające i ptactwo skrzydlate.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 11, 'Królowie ziemscy i wszystkie narody; władcy i wszyscy sędziowie ziemi;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 12, 'Młodzieńcy, a także dziewice, starzy i dzieci;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 13, 'Niech chwalą imię Pana, bo tylko jego imię jest wzniosłe, a jego chwała nad ziemią i niebem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 14, 'I wywyższył róg swego ludu, chwałę wszystkich jego świętych, zwłaszcza synów Izraela, ludu mu bliskiego. Alleluja.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 1, 'Alleluja. Śpiewajcie Panu nową pieśń; niech jego chwała zabrzmi w zgromadzeniu świętych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 2, 'Niech Izrael cieszy się swoim Stwórcą; niech synowie Syjonu radują się swoim Królem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 3, 'Niech chwalą jego imię tańcem; niech grają mu na bębnie i na harfie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 4, 'Pan bowiem swój lud upodobał sobie; zdobi pokornych zbawieniem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 5, 'Niech święci się radują w chwale Bożej, niech śpiewają na swych posłaniach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 6, 'Niech chwała Boża będzie na ich ustach, a miecz obosieczny w ich rękach;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 7, 'Aby dokonali zemsty na poganach i ukarali narody;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 8, 'Aby zakuli ich królów w kajdany, a ich dostojników w żelazne okowy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 9, 'Aby wykonali na nich zapisany wyrok. Taka jest chwała wszystkich jego świętych. Alleluja.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 1, 'Alleluja. Chwalcie Boga w jego świątyni; chwalcie go na firmamencie jego mocy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 2, 'Chwalcie go za jego potężne dzieła; chwalcie go za jego wielką dostojność.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 3, 'Chwalcie go na głośnych trąbach; chwalcie go na cytrze i na harfie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 4, 'Chwalcie go bębnem i tańcem; chwalcie go na strunach i na fletach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 5, 'Chwalcie go na głośnych cymbałach; chwalcie go na cymbałach brzęczących.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 6, 'Niech wszystko, co oddycha, chwali Pana. Alleluja.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 1, 'Przysłowia Salomona, syna Dawida, króla Izraela;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 2, 'Do poznania mądrości i karności, do zrozumienia słów roztropnych;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 3, 'Do zdobycia pouczenia w mądrości, w sprawiedliwości, w sądzie i w prawości;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 4, 'Do udzielenia prostym rozwagi, a młodemu – wiedzy i roztropności.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 5, 'Mądry posłucha i przybędzie mu wiedzy, a rozumny nabędzie rad;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 6, 'Aby rozumieć przysłowia i ich wykładnię, słowa mądrych i ich zagadki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 7, 'Bojaźń Pana jest początkiem wiedzy, ale głupcy gardzą mądrością i karnością.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 8, 'Synu mój, słuchaj pouczenia swego ojca i nie odrzucaj nauki swojej matki;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 9, 'Bo one będą wdzięczną ozdobą na twojej głowie i kosztownym łańcuchem na szyi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 10, 'Synu mój, jeśli grzesznicy cię namawiają, nie pozwalaj.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 11, 'Jeśli mówią: Chodź z nami, czyhajmy na krew, zaczajmy się na niewinnego bez powodu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 12, 'Pożremy ich żywcem jak grób, całych, jak zstępujących do dołu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 13, 'Znajdziemy wszelkie kosztowności, napełnimy swoje domy łupem;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 14, 'Dziel z nami swój los; miejmy wszyscy jedną sakiewkę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 15, 'Synu mój, nie wyruszaj z nimi w drogę; powstrzymaj swoją nogę od ich ścieżki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 16, 'Ich nogi bowiem biegną do zła i spieszą się do przelania krwi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 17, 'Na próżno zastawia się sieci na oczach wszelkiego ptactwa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 18, 'Oni też czyhają na własną krew, czają się na własne życie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 19, 'Takie są ścieżki każdego, który jest chciwy zysku; swojemu właścicielowi taki zysk odbiera życie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 20, 'Mądrość woła na dworze, podnosi swój głos na ulicach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 21, 'Woła w największym zgiełku, u wrót bram, w mieście wygłasza swoje słowa:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 22, 'Jak długo, prości, będziecie kochać głupotę, szydercy – lubować się w swoim szyderstwie, a głupi – nienawidzić wiedzy?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 23, 'Nawróćcie się na moje upomnienie; oto wyleję na was mojego ducha, oznajmię wam moje słowa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 24, 'Ponieważ wołałam, a odmawialiście; wyciągałam rękę, a nikt nie zważał;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 25, 'Owszem, odrzuciliście całą moją radę i nie chcieliście przyjąć mojego upomnienia;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 26, 'Dlatego będę się śmiać z waszego nieszczęścia, będę szydzić z was, gdy przyjdzie to, czego się boicie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 27, 'Gdy nadejdzie jak spustoszenie to, czego się boicie, i gdy wasze nieszczęście nadciągnie jak wicher, gdy nadejdzie na was ucisk i cierpienie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 28, 'Wtedy będą mnie wzywać, a nie wysłucham; będą mnie szukać pilnie, lecz mnie nie znajdą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 29, 'Bo znienawidzili wiedzę i nie wybrali bojaźni Pana;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 30, 'Ani nie chcieli mojej rady, ale gardzili każdym moim upomnieniem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 31, 'Dlatego spożyją owoc swoich dróg i będą nasyceni swymi radami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 32, 'Bo odstępstwo prostych zabije ich i szczęście głupich zgubi ich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 33, 'Ale kto mnie słucha, będzie mieszkać bezpiecznie i będzie wolny od strachu przed złem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 1, 'Synu mój, jeśli przyjmiesz moje słowa i zachowasz u siebie moje przykazania;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 2, 'Nadstawiając swego ucha na mądrość i nakłaniając swe serce ku rozumowi;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 3, 'Tak, jeśli przywołasz roztropność i swoim głosem wezwiesz rozum;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 4, 'Jeśli będziesz jej szukać jak srebra i poszukiwać jej jak ukrytych skarbów;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 5, 'Wtedy zrozumiesz bojaźń Pana i dojdziesz do poznania Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 6, 'Pan bowiem daje mądrość, z jego ust pochodzi wiedza i rozum.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 7, 'On zachowuje prawdziwą mądrość dla prawych; on jest tarczą dla tych, którzy postępują uczciwie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 8, 'Strzeże ścieżek sądu i chroni drogę swoich świętych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 9, 'Wtedy zrozumiesz sprawiedliwość, sąd, prawość i wszelką dobrą ścieżkę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 10, 'Gdy mądrość wejdzie do twojego serca i wiedza będzie miła twojej duszy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 11, 'Wtedy rozwaga będzie cię strzegła i rozum cię zachowa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 12, 'By uwolnić cię od złej drogi i od człowieka, który mówi przewrotnie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 13, 'Od tych, którzy opuszczają ścieżki prawości, żeby chodzić drogami ciemności;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 14, 'Którzy się radują, gdy czynią zło, a cieszą się w złośliwej przewrotności;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 15, 'Których ścieżki są kręte i sami są przewrotni na swoich drogach;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 16, 'Aby cię uwolnić od cudzej kobiety, od obcej, która pochlebia łagodnymi słowami;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 17, 'Która opuszcza przewodnika swojej młodości i zapomina o przymierzu swojego Boga;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 18, 'Bo jej dom chyli się ku śmierci, a jej ścieżki ku umarłym;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 19, 'Nikt z tych, którzy do niej wchodzą, nie wraca ani nie trafia na ścieżkę życia;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 20, 'Abyś chodził drogą dobrych i przestrzegał ścieżek sprawiedliwych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 21, 'Prawi bowiem będą mieszkali na ziemi i nienaganni na niej pozostaną;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 22, 'Ale niegodziwi będą wykorzenieni z ziemi i przewrotni będą z niej wyrwani.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 1, 'Synu mój, nie zapominaj mego prawa, a niech twoje serce strzeże moich przykazań;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 2, 'Bo przyniosą ci długie dni i lata życia oraz pokoju.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 3, 'Niech cię nie opuszczają miłosierdzie i prawda, przywiąż je do swojej szyi, wypisz je na tablicy swojego serca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 4, 'Wtedy znajdziesz łaskę i uznanie w oczach Boga i ludzi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 5, 'Ufaj Panu z całego swego serca i nie polegaj na swoim rozumie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 6, 'Zważaj na niego we wszystkich swoich drogach, a on będzie prostować twoje ścieżki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 7, 'Nie bądź mądrym we własnych oczach, ale bój się Pana i odstąp od zła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 8, 'To da twemu ciału zdrowie i pokrzepienie twoim kościom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 9, 'Czcij Pana swoim majątkiem i pierwocinami wszystkich twoich dochodów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 10, 'A twoje spichrze będą napełnione dostatkiem i twoje prasy będą przelewać się od nowego wina.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 11, 'Synu mój, nie gardź karceniem Pana i nie zniechęcaj się jego upomnieniem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 12, 'Bo kogo Pan miłuje, tego karze, jak ojciec syna, którego kocha.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 13, 'Błogosławiony człowiek, który znajduje mądrość, i człowiek, który nabiera rozumu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 14, 'Gdyż jego nabycie jest lepsze niż nabycie srebra, jego zdobycie bardziej pożyteczne niż złoto.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 15, 'Jest droższa nad perły i żadna rzecz, której pragniesz, nie dorówna jej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 16, 'Długie dni są w jej prawej ręce, a w lewej bogactwa i chwała.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 17, 'Jej drogi są drogami rozkoszy i wszystkie jej ścieżki spokojne.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 18, 'Jest drzewem życia dla tych, którzy się jej chwycą; a ci, którzy się jej trzymają, są błogosławieni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 19, 'Pan ugruntował ziemię mądrością, a niebiosa umocnił rozumem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 20, 'Dzięki jego wiedzy rozstąpiły się głębiny, a obłoki spuszczają rosę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 21, 'Synu mój, niech one ci z oczu nie schodzą; strzeż prawdziwej mądrości i roztropności;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 22, 'A będą życiem twojej duszy i ozdobą twojej szyi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 23, 'Wtedy będziesz bezpiecznie chodził swoją drogą, a noga twoja się nie potknie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 24, 'Gdy się położysz, nie będziesz się lękał; a gdy zaśniesz, twój sen będzie przyjemny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 25, 'Nie lękaj się nagłego strachu ani spustoszenia niegodziwych, gdy przyjdzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 26, 'Pan bowiem będzie twoją ufnością i twojej nogi będzie strzegł od sideł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 27, 'Nie wzbraniaj się dobrze czynić potrzebującemu, gdy stać cię na to, aby dobrze czynić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 28, 'Nie mów bliźniemu: Idź i przyjdź znowu, dam ci jutro, gdy masz to u siebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 29, 'Nie knuj zła przeciwko swemu bliźniemu, gdy spokojnie mieszka obok ciebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 30, 'Nie spieraj się z człowiekiem bez przyczyny, jeśli ci nic złego nie wyrządził.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 31, 'Nie zazdrość ciemięzcy i nie wybieraj żadnej z jego dróg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 32, 'Przewrotny bowiem budzi w Panu odrazę, ale jego tajemnica jest z prawymi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 33, 'Przekleństwo Pana jest w domu niegodziwego, lecz Pan błogosławi mieszkanie sprawiedliwych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 34, 'On szydzi z szyderców, ale daje łaskę pokornym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 35, 'Mądrzy odziedziczą chwałę, a głupi poniosą hańbę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 1, 'Słuchajcie, synowie, pouczenia ojca i zważajcie na to, abyście poznali roztropność;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 2, 'Bo daję wam dobrą naukę, nie porzucajcie mego prawa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 3, 'Byłem bowiem synem mego ojca i miłym jedynakiem w oczach mojej matki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 4, 'On mnie uczył, mówiąc mi: Niech twoje serce zachowa moje słowa; strzeż moich przykazań, a będziesz żył.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 5, 'Zdobywaj mądrość, zdobywaj roztropność; nie zapominaj i nie odstępuj od słów moich ust.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 6, 'Nie opuszczaj jej, a będzie cię strzegła; ukochaj ją, a zachowa cię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 7, 'Podstawą wszystkiego jest mądrość; zdobywaj mądrość i za cały swój majątek zdobywaj roztropność.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 8, 'Wywyższaj ją, a ona wywyższy ciebie, rozsławi cię, gdy ją przyjmiesz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 9, 'Wdzięczną ozdobę włoży ci na głowę, obdarzy cię koroną chwały.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 10, 'Słuchaj, synu mój, i przyjmij moje słowa, a pomnożą się lata twojego życia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 11, 'Nauczyłem cię drogi mądrości, po ścieżkach prawości cię wiodłem;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 12, 'Gdy nimi pójdziesz, twoje kroki nie będą skrępowane; a jeśli pobiegniesz, nie potkniesz się.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 13, 'Trzymaj się karności, nie opuszczaj jej, strzeż jej, bo ona jest twoim życiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 14, 'Nie chodź ścieżką niegodziwych i nie wchodź na drogę złych ludzi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 15, 'Unikaj jej, nie chodź po niej; odwróć się od niej i omiń ją;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 16, 'Bo oni nie zasną, dopóki nie zrobią czegoś złego; sen ich odleci, aż przywiodą kogoś do upadku;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 17, 'Jedzą bowiem chleb nieprawości i piją wino przemocy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 18, 'Ale ścieżka sprawiedliwych jest jak jasne światło, które świeci coraz jaśniej aż do dnia doskonałego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 19, 'Droga niegodziwych jest jak ciemność; nie wiedzą, o co mogą się potknąć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 20, 'Synu mój, zważaj na moje słowa; ku moim naukom nakłoń swe ucho.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 21, 'Niech nie schodzą ci z oczu, zachowaj je w głębi twego serca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 22, 'Są bowiem życiem dla tych, którzy je znajdują, i lekarstwem dla całego ich ciała.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 23, 'Strzeż twego serca z całą pilnością, bo z niego tryska życie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 24, 'Odsuń od siebie przewrotność ust, oddal od siebie złośliwe wargi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 25, 'Niech twoje oczy patrzą na wprost, a twoje powieki niech będą zwrócone przed siebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 26, 'Uważaj na ścieżkę twoich nóg, aby wszystkie twoje drogi były pewne.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 27, 'Nie zbaczaj ani na prawo, ani na lewo; odwróć twoją nogę od zła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 1, 'Synu mój, zważaj na moją mądrość i nakłoń twego ucha ku mojemu rozumowi;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 2, 'Abyś zachował rozwagę i aby twoje wargi strzegły wiedzy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 3, 'Bo wargi obcej kobiety ociekają miodem, a jej usta gładsze są niż oliwa;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 4, 'Lecz jej koniec jest gorzki jak piołun, ostry jak miecz obosieczny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 5, 'Jej nogi zstępują do śmierci, jej kroki prowadzą do piekła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 6, 'Abyś nie rozważał ścieżki życia, jej drogi są tak niestałe, że nie poznasz ich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 7, 'Teraz więc, synowie, słuchajcie mnie i nie odstępujcie od słów moich ust.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 8, 'Oddal od niej swą drogę i nie zbliżaj się do drzwi jej domu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 9, 'Abyś nie oddał obcym twojej sławy, a twoich lat okrutnikowi;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 10, 'Aby obcy nie nasycili się twoim dobytkiem, a twój dorobek nie został w cudzym domu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 11, 'I abyś nie jęczał u kresu swych dni, gdy twoja skóra i ciało będą zniszczone;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 12, 'I nie musiał powiedzieć: O, jakże nienawidziłem karności i moje serce gardziło upomnieniem!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 13, 'Nie słuchałem głosu moich wychowawców i nie nakłaniałem ucha ku tym, którzy mnie nauczali!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 14, 'O mało co nie wpadłem we wszelkie nieszczęście wśród zebrania i zgromadzenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 15, 'Pij wodę z własnego zdroju i wody płynące z twojego źródła!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 16, 'Niech rozproszą się twoje źródła, a po ulicach strumienie wód.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 17, 'Niech należą tylko do ciebie, a nie do obcych wraz z tobą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 18, 'Niech twój zdrój będzie błogosławiony i ciesz się żoną twojej młodości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 19, 'Niech będzie jak wdzięczna łania i rozkoszna sarna; niech jej piersi zawsze cię nasycają, nieustannie zachwycaj się jej miłością.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 20, 'Dlaczego, synu mój, masz zachwycać się obcą kobietą i obejmować piersi cudzej?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 21, 'Gdyż drogi człowieka są przed oczami Pana i waży on wszystkie jego ścieżki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 22, 'Niegodziwego schwytają jego własne nieprawości i uwikła się w powrozy swego grzechu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 23, 'Umrze z braku karności i będzie błądził z powodu swojej wielkiej głupoty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 1, 'Synu mój, jeśli poręczyłeś za swego bliźniego i dałeś porękę za obcego;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 2, 'Związałeś się słowami ust twoich, schwytany jesteś mową twoich ust.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 3, 'Uczyń więc tak, synu mój, uwolnij się, gdy wpadłeś w ręce swego bliźniego; idź, upokórz się i nalegaj na twego bliźniego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 4, 'Nie daj snu swoim oczom i nie pozwól powiekom drzemać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 5, 'Uwolnij się jak sarna z rąk myśliwego i jak ptak z ręki ptasznika.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 6, 'Idź do mrówki, leniwcze, przypatrz się jej drogom i bądź mądry;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 7, 'Chociaż nie ma ona wodza ani przełożonego, ani pana;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 8, 'To w lecie przygotowuje swój pokarm i gromadzi w żniwa swą żywność.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 9, 'Jak długo będziesz leżał, leniwcze? Kiedy wstaniesz ze swego snu?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 10, 'Jeszcze trochę snu, trochę drzemania, trochę założenia rąk, aby zasnąć;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 11, 'A twoje ubóstwo przyjdzie jak podróżny i twój niedostatek jak mąż uzbrojony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 12, 'Człowiek nikczemny i niegodziwy chodzi z przewrotnością na ustach;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 13, 'Mruga swymi oczyma, mówi swymi nogami, wskazuje swymi palcami;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 14, 'Przewrotność jest w jego sercu, stale knuje zło i sieje niezgodę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 15, 'Dlatego nagle spadnie na niego nieszczęście; nagle zostanie złamany i pozbawiony ratunku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 16, 'Jest sześć rzeczy, których nienawidzi Pan, siedem budzi w nim odrazę:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 17, 'Wyniosłe oczy, kłamliwy język i ręce, które przelewają krew niewinną;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 18, 'Serce, które knuje złe myśli; nogi, które spiesznie biegną do zła;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 19, 'Fałszywy świadek, który mówi kłamstwa, i ten, który sieje niezgodę między braćmi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 20, 'Synu mój, strzeż przykazania twego ojca i nie odrzucaj prawa twojej matki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 21, 'Przywiąż je na zawsze do serca twego i zawieś je sobie na szyi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 22, 'Gdy będziesz chodził, poprowadzi cię; gdy zaśniesz, strzec cię będzie, a gdy się obudzisz, będzie mówić do ciebie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 23, 'Bo przykazanie jest pochodnią, prawo światłością, a upomnienia do karności są drogą życia;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 24, 'Aby cię strzegły przed złą kobietą i przed gładkim językiem obcej kobiety.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 25, 'Nie pożądaj w twoim sercu jej piękności i niech cię nie łowi swymi powiekami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 26, 'Bo dla kobiety nierządnej zubożeje człowiek o kawałek chleba, a żona cudzołożna czyha na cenne życie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 27, 'Czy może ktoś wziąć ogień w zanadrze, a jego szaty się nie spalą?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 28, 'Czy może ktoś chodzić po rozżarzonych węglach, a jego nogi się nie poparzą?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 29, 'Tak ten, kto wchodzi do żony swego bliźniego; ktokolwiek ją dotknie, nie będzie bez winy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 30, 'Nie pogardza się złodziejem, jeśli kradnie, by nasycić swoją duszę, będąc głodnym;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 31, 'Ale jeśli go złapią, zwróci siedmiokrotnie albo odda cały dobytek swego domu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 32, 'Lecz kto cudzołoży z kobietą, jest pozbawiony rozsądku; kto tak robi, gubi swoją duszę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 33, 'Znajdzie chłostę i wstyd, a jego hańba nie będzie zmazana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 34, 'Bo zazdrość rozpala gniew mężczyzny i nie będzie pobłażał w dniu zemsty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 35, 'Nie będzie miał względu na żaden okup i nie przyjmie darów, choćbyś najwięcej mu dawał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 1, 'Synu mój, strzeż moich słów i przechowuj u siebie moje przykazania.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 2, 'Strzeż moich przykazań, a będziesz żył; strzeż mojego prawa jak źrenicy swych oczu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 3, 'Przywiąż je do swoich palców, wypisz je na tablicy twego serca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 4, 'Mów do mądrości: Jesteś moją siostrą, a roztropność nazywaj przyjaciółką;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 5, 'Aby cię strzegły przed cudzą żoną i przed obcą, która mówi gładkie słowa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 6, 'Bo z okna swego domu wyglądałem przez kratę;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 7, 'I zobaczyłem wśród prostych, zauważyłem wśród chłopców nierozumnego młodzieńca;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 8, 'Który przechodził ulicą blisko jej narożnika, idąc drogą do jej domu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 9, 'O zmierzchu, pod wieczór, w ciemności nocnej i w mroku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 10, 'A oto spotkała go kobieta w stroju nierządnicy, chytrego serca;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 11, 'Wrzaskliwa i nieopanowana, której nogi nie mogą pozostać w domu:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 12, 'Raz na dworze, raz na ulicach i czyha na każdym rogu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 13, 'Chwyciła go i pocałowała, z bezczelną miną powiedziała do niego:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 14, 'U mnie są ofiary pojednawcze; spełniłam dzisiaj swoje śluby.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 15, 'Dlatego wyszłam ci naprzeciw, szukałam pilnie twojej twarzy i znalazłam cię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 16, 'Obiłam kobiercami swoje łoże, przystrojone rzeźbieniem i prześcieradłami z Egiptu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 17, 'Skropiłam swoje posłanie mirrą, aloesem i cynamonem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 18, 'Chodź, upójmy się miłością aż do rana, nacieszmy się miłością.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 19, 'Bo mojego męża nie ma w domu; pojechał w daleką drogę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 20, 'Wziął ze sobą worek pieniędzy; umówionego dnia wróci do domu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 21, 'Nakłoniła go mnóstwem swoich słów i zniewoliła go pochlebstwem swoich warg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 22, 'Wnet poszedł za nią jak wół prowadzony na rzeź i jak głupi na karę pęt.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 23, 'Aż strzała przebije mu wątrobę; spieszy jak ptak w sidła, nie wiedząc, że chodzi o jego życie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 24, 'Więc teraz słuchajcie mnie, synowie, i zważajcie na słowa moich ust.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 25, 'Niech twoje serce nie zbacza na jej drogi i nie tułaj się po jej ścieżkach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 26, 'Bo wielu zranionych strąciła i wielu mocarzy pozabijała.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 27, 'Jej dom jest drogą do piekła, która wiedzie do komnat śmierci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 1, 'Czy mądrość nie woła i rozum nie wydaje swego głosu?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 2, 'Stoi na szczycie wysokich miejsc, przy drodze, na rozstajach dróg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 3, 'Przy bramach, przy wjeździe do miasta, przy wejściu, u drzwi woła:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 4, 'Do was wołam, o mężowie, mój głos kieruję do synów ludzkich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 5, 'Prości, uczcie się rozwagi, a wy, głupi, bądźcie rozumnego serca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 6, 'Słuchajcie, bo będę mówił o rzeczach wzniosłych, a wargi moje otworzą się, aby głosić prawość.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 7, 'Moje usta bowiem mówią prawdę, a niegodziwością brzydzą się moje wargi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 8, 'Sprawiedliwe są wszystkie słowa moich ust; nie ma w nich nic fałszywego ani przewrotnego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 9, 'Wszystkie są jasne dla rozumnego i prawe dla tych, którzy znajdują wiedzę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 10, 'Przyjmijcie moje pouczenie zamiast srebra i wiedzę raczej niż wyborne złoto.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 11, 'Lepsza bowiem jest mądrość niż perły i żadna rzecz, której pragniesz, nie dorówna jej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 12, 'Ja, mądrość, mieszkam z rozwagą i odkrywam wiedzę roztropności.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 13, 'Bojaźń Pana to nienawidzić zła. Ja nienawidzę pychy, wyniosłości, złej drogi i ust przewrotnych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 14, 'Moja jest rada i prawdziwa mądrość, ja jestem roztropnością i moja jest moc.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 15, 'Dzięki mnie królowie rządzą i władcy stanowią sprawiedliwość.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 16, 'Dzięki mnie panują władcy i dostojnicy, wszyscy sędziowie ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 17, 'Miłuję tych, którzy mnie miłują, a ci, którzy szukają mnie pilnie, znajdą mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 18, 'Przy mnie jest bogactwo i chwała, trwałe bogactwo i sprawiedliwość.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 19, 'Mój owoc jest lepszy niż złoto, nawet najczystsze złoto, a moje plony lepsze niż wyborne srebro.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 20, 'Prowadzę ścieżką sprawiedliwości, pośród ścieżek sądu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 21, 'Aby tym, którzy mnie miłują, dać w dziedzictwo majątek wieczny i napełnić ich skarbce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 22, 'Pan posiadł mnie na początku swej drogi, przed swymi dziełami, przed wszystkimi czasy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 23, 'Przed wiekami zostałam ustanowiona, od początku; zanim powstała ziemia;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 24, 'Gdy jeszcze nie było głębin, zostałam zrodzona, kiedy jeszcze nie było źródeł obfitujących w wody.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 25, 'Zanim góry zostały założone, nim były pagórki, zostałam zrodzona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 26, 'Gdy jeszcze nie stworzył ziemi ani pól, ani początku prochu okręgu ziemskiego;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 27, 'Kiedy przygotowywał niebiosa, byłam tam; gdy odmierzał okrąg nad powierzchnią głębi;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 28, 'Gdy w górze utwierdzał obłoki i umacniał źródła głębin;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 29, 'Gdy wyznaczał morzu jego granice, by wody nie przekraczały jego rozkazu, kiedy ustalał fundamenty ziemi;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 30, 'Byłam wtedy przy nim jak wychowanka i byłam jego radością każdego dnia, ciesząc się zawsze przed nim;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 31, 'Radując się na okręgu jego ziemi, rozkoszując się synami ludzkimi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 32, 'Teraz więc, synowie, słuchajcie mnie, bo błogosławieni są ci, którzy strzegą moich dróg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 33, 'Słuchajcie pouczeń, nabądźcie mądrości i nie odrzucajcie jej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 34, 'Błogosławiony człowiek, który mnie słucha, czuwając u moich wrót każdego dnia i strzegąc odrzwi moich bram.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 35, 'Bo kto mnie znajduje, znajduje życie i otrzyma łaskę od Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 36, 'Ale kto grzeszy przeciwko mnie, wyrządza krzywdę swojej duszy; wszyscy, którzy mnie nienawidzą, miłują śmierć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 1, 'Mądrość zbudowała sobie dom i wyciosała siedem słupów;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 2, 'Zabiła swoje bydło, zmieszała wino i zastawiła stół;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 3, 'Rozesłała swoje służące, woła na szczytach najwyższych miejsc miasta:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 4, 'Ktokolwiek jest prostym, niech wstąpi; a do nierozumnego mówi:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 5, 'Chodźcie, jedzcie mój chleb i pijcie wino, które zmieszałam.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 6, 'Porzućcie głupotę, a będziecie żyli, i chodźcie drogą roztropności.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 7, 'Kto upomina szydercę, ściąga na siebie hańbę, a kto strofuje niegodziwego, ten się plami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 8, 'Nie strofuj szydercy, aby cię nie znienawidził; strofuj mądrego, a będzie cię miłował.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 9, 'Upomnij mądrego, a będzie mądrzejszy; poucz sprawiedliwego, a pomnoży swą wiedzę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 10, 'Początkiem mądrości jest bojaźń Pana, a wiedza o tym, co święte, to rozum.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 11, 'Bo dzięki mnie rozmnożą się twoje dni i przedłużą się lata twojego życia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 12, 'Jeśli będziesz mądry, tobie samemu będzie służyła twoja mądrość; a jeśli szydercą, sam poniesiesz szkodę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 13, 'Głupia kobieta jest wrzaskliwa, prosta i nic nie rozumie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 14, 'Siedzi u drzwi swego domu, na krześle, na wysokich miejscach w mieście;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 15, 'Aby wołać na przechodzących, którzy idą prosto swoimi ścieżkami:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 16, 'Ktokolwiek jest prosty, niech wstąpi; a do nierozumnego mówi:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 17, 'Kradzione wody są słodkie, a chleb jedzony pokątnie smaczny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 18, 'Ale on nie wie, że tam są umarli, że jej zaproszeni są w głębinach piekła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 1, 'Przysłowia Salomona. Mądry syn sprawia ojcu radość, a głupi syn jest zgryzotą swojej matki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 2, 'Skarby niegodziwości nie przynoszą pożytku, lecz sprawiedliwość uwalnia od śmierci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 3, 'Pan nie pozwoli, by dusza sprawiedliwego cierpiała głód, a rozproszy majątek niegodziwych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 4, 'Leniwa ręka prowadzi do nędzy, a ręka pracowita ubogaca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 5, 'Kto zbiera w lecie, jest synem roztropnym; syn, który śpi w czasie żniwa, przynosi hańbę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 6, 'Błogosławieństwa są na głowie sprawiedliwego, a usta niegodziwych kryją nieprawość.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 7, 'Pamięć sprawiedliwego jest błogosławiona, a imię niegodziwych zgnije.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 8, 'Człowiek mądrego serca przyjmuje przykazania, a gadatliwy głupiec upadnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 9, 'Kto postępuje uczciwie, postępuje bezpiecznie, a kto jest przewrotny w swoich drogach, zostanie ujawniony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 10, 'Kto mruga okiem, przynosi cierpienie, a gadatliwy głupiec upadnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 11, 'Usta sprawiedliwego są źródłem życia, a usta niegodziwych kryją nieprawość.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 12, 'Nienawiść wznieca kłótnie, a miłość zakrywa wszystkie grzechy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 13, 'Na wargach rozumnego znajduje się mądrość, a kij na grzbiecie nierozumnego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 14, 'Mądrzy gromadzą wiedzę, a usta głupiego grożą zniszczeniem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 15, 'Majątek bogacza jest jego warownym miastem, a zniszczeniem ubogich jest ich nędza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 16, 'Praca sprawiedliwego prowadzi do życia, a dochód niegodziwych do grzechu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 17, 'Kto przestrzega karności, idzie ścieżką życia, a kto gardzi upomnieniem, błądzi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 18, 'Kto kryje nienawiść kłamliwymi wargami i kto rozgłasza oszczerstwo, jest głupcem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 19, 'Wielomówność nie bywa bez grzechu, a kto powściąga swoje wargi, jest roztropny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 20, 'Język sprawiedliwego jest wybornym srebrem, a serce niegodziwych jest mało warte.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 21, 'Wargi sprawiedliwego żywią wielu, a głupi umierają przez brak rozumu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 22, 'Błogosławieństwo Pana wzbogaca i nie przynosi z sobą zmartwień.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 23, 'Dla głupiego popełnić haniebny czyn to zabawa, a człowiek roztropny trzyma się mądrości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 24, 'Niegodziwego spotka to, czego się boi, a sprawiedliwym Bóg daje to, czego pragną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 25, 'Jak wicher przemija, tak niegodziwy nie przetrwa, a sprawiedliwy ma wieczny fundament.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 26, 'Czym ocet dla zębów i dym dla oczu, tym jest leniwy dla tych, którzy go posyłają.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 27, 'Bojaźń Pana przedłuża dni, a lata niegodziwego będą skrócone.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 28, 'Oczekiwanie sprawiedliwych przynosi radość, a nadzieja niegodziwych zginie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 29, 'Droga Pana jest mocą dla prawego, a zgubą dla czyniących nieprawość.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 30, 'Sprawiedliwy nigdy się nie zachwieje, a niegodziwi nie będą mieszkać na ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 31, 'Usta sprawiedliwego wydają mądrość, a język przewrotny będzie wycięty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 32, 'Wargi sprawiedliwego wiedzą, co wypada, a usta niegodziwych są przewrotne.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 1, 'Fałszywa waga budzi odrazę w Panu, ale podobają mu się uczciwe odważniki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 2, 'Za pychą przychodzi hańba, a u pokornych jest mądrość.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 3, 'Uczciwość prawych poprowadzi ich, lecz grzeszników zgubi ich przewrotność.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 4, 'Bogactwa nie pomogą w dniu gniewu, ale sprawiedliwość ocala od śmierci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 5, 'Sprawiedliwość nienagannego toruje mu drogę, a niegodziwy upadnie przez swoją niegodziwość.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 6, 'Sprawiedliwość prawych ocali ich, a przewrotni będą schwytani w swojej przewrotności.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 7, 'Gdy umiera niegodziwy, ginie jego nadzieja, a oczekiwanie niesprawiedliwych znika.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 8, 'Sprawiedliwy bywa wybawiony z ucisku, a na jego miejsce przychodzi niegodziwy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 9, 'Obłudnik ustami niszczy swego bliźniego, a sprawiedliwi bywają wybawieni dzięki wiedzy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 10, 'Gdy sprawiedliwym się powodzi, miasto się cieszy, a gdy giną niegodziwi, panuje radość.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 11, 'Dzięki błogosławieństwu prawych wznosi się miasto, a usta niegodziwych je burzą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 12, 'Nierozumny gardzi swym bliźnim, a człowiek roztropny milczy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 13, 'Plotkarz wyjawia tajemnice, ale człowiek wiernego serca ukrywa powierzoną sprawę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 14, 'Gdzie nie ma dobrej rady, lud upada, a gdzie wielu radców, tam jest wybawienie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 15, 'Bardzo sobie szkodzi, kto ręczy za obcego, a kto nienawidzi poręki, jest bezpieczny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 16, 'Miła kobieta dostępuje chwały, a mocarze zdobywają bogactwa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 17, 'Człowiek miłosierny czyni dobrze swej duszy, a okrutnik dręczy własne ciało.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 18, 'Niegodziwy czyni zwodnicze dzieło, a kto sieje sprawiedliwość, ma zapłatę pewną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 19, 'Jak sprawiedliwość prowadzi do życia, tak do śmierci zmierza ten, kto naśladuje zło.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 20, 'Ludzie przewrotnego serca budzą odrazę w Panu, a podobają mu się ci, których droga jest prawa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 21, 'Zły nie uniknie kary, choćby innych wezwał na pomoc, a potomstwo sprawiedliwych będzie ocalone.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 22, 'Czym złoty kolczyk w ryju świni, tym piękna kobieta pozbawiona roztropności.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 23, 'Pragnieniem sprawiedliwych jest tylko dobro, oczekiwaniem zaś niegodziwych – gniew.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 24, 'Jeden hojnie rozdaje, a jednak mu przybywa, drugi nad miarę skąpi, a ubożeje.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 25, 'Człowiek szczodry będzie bogatszy, a kto innych syci, sam też będzie nasycony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 26, 'Kto zatrzymuje zboże, tego lud przeklnie, a błogosławieństwo będzie nad głową tego, który je sprzedaje.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 27, 'Kto pilnie szuka dobrego, zdobędzie przychylność, lecz kto szuka zła, przyjdzie ono na niego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 28, 'Kto ufność pokłada w swych bogactwach, ten upadnie, a sprawiedliwi będą zielenić się jak latorośl.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 29, 'Kto niepokoi swój dom, odziedziczy wiatr, a głupi będzie sługą mądrego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 30, 'Owoc sprawiedliwego jest drzewem życia; a kto zyskuje dusze, jest mądry.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 31, 'Jeśli sprawiedliwy otrzyma zapłatę na ziemi, to tym bardziej niegodziwy i grzesznik.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 1, 'Kto kocha karność, kocha wiedzę, a kto nienawidzi upomnienia, jest głupi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 2, 'Dobry człowiek zdobędzie łaskę Pana, ale Pan potępi podstępnego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 3, 'Człowiek nie umocni się niegodziwością, lecz korzeń sprawiedliwych nie będzie poruszony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 4, 'Żona cnotliwa jest koroną swego męża, ale ta, która go hańbi, jest jak zgnilizna w jego kościach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 5, 'Myśli sprawiedliwych są prawe, a rady niegodziwych zdradliwe.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 6, 'Słowa niegodziwych czyhają na krew, lecz usta prawych ocalą ich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 7, 'Niegodziwi zostają powaleni i już ich nie ma, a dom sprawiedliwych się ostoi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 8, 'Człowiek będzie chwalony za jego mądrość, a kto jest przewrotnego serca, zostanie wzgardzony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 9, 'Lepszy jest człowiek wzgardzony, który ma sługę, niż ten, kto się chwali, a któremu brak chleba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 10, 'Sprawiedliwy dba o życie swego bydła, a serce niegodziwych jest okrutne.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 11, 'Kto uprawia swoją ziemię, nasyci się chlebem, a kto naśladuje próżnujących, jest nierozumny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 12, 'Niegodziwy pragnie sieci złych, a korzeń sprawiedliwych wydaje owoc.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 13, 'Zły zostaje usidlony przez grzech swoich warg, a sprawiedliwy wyjdzie z ucisku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 14, 'Człowiek nasyci się dobrem z owocu swoich ust, a za dzieła swoich rąk otrzyma zapłatę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 15, 'Droga głupiego wydaje się słuszna w jego oczach, ale kto słucha rady, jest mądry.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 16, 'Gniew głupiego objawia się od razu, a roztropny skrywa hańbę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 17, 'Kto mówi prawdę, wyraża sprawiedliwość, ale fałszywy świadek – oszustwo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 18, 'Znajdzie się taki, którego słowa są jak miecz przeszywający, lecz język mądrych jest lekarstwem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 19, 'Prawdomówne wargi będą trwać na wieki, ale język kłamliwy trwa króciutko.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 20, 'Podstęp jest w sercu tych, którzy knują zło, lecz u doradzających pokój jest radość.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 21, 'Sprawiedliwego nie spotka żadne zło, ale niegodziwi będą pełni nieszczęścia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 22, 'Wargi kłamliwe budzą odrazę w Panu, a ci, którzy postępują w prawdzie, podobają mu się.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 23, 'Człowiek roztropny ukrywa wiedzę, a serce głupich rozgłasza głupotę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 24, 'Ręka pracowitych będzie panowała, a leniwa będzie płaciła daninę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 25, 'Troska w sercu człowieka przygnębia je, a dobre słowo je rozwesela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 26, 'Sprawiedliwy jest zacniejszy od swego bliźniego, a droga niegodziwych prowadzi ich na manowce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 27, 'Leniwy nie upiecze tego, co upolował, ale mienie człowieka pracowitego jest cenne.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 28, 'Na ścieżce sprawiedliwości jest życie, na jej drodze nie ma śmierci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 1, 'Mądry syn przyjmuje pouczenie ojca, a szyderca nie słucha strofowania.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 2, 'Człowiek będzie spożywać dobro z owocu swoich ust, a dusza przewrotnych będzie spożywać przemoc.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 3, 'Kto strzeże swych ust, strzeże swojej duszy; kto szeroko otwiera swe wargi, będzie zniszczony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 4, 'Dusza leniwego pragnie, a nic nie ma, a dusza pracowitych zostanie obficie nasycona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 5, 'Sprawiedliwy nienawidzi kłamliwego słowa, a niegodziwy staje się obrzydliwy i zhańbiony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 6, 'Sprawiedliwość strzeże tego, który postępuje uczciwie, a niegodziwość powala grzesznika.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 7, 'Znajduje się taki, który czyni siebie bogatym, a nie ma nic; inny czyni siebie ubogim, choć ma wiele bogactw.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 8, 'Okupem za życie człowieka jest jego bogactwo, a ubogi nie słucha strofowania.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 9, 'Radośnie błyszczy światło sprawiedliwych, a pochodnia niegodziwych zgaśnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 10, 'Spór powstaje tylko dzięki pysze, a mądrość jest przy tych, co przyjmują radę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 11, 'Łatwo zdobyte bogactwo zmniejsza się, a kto je gromadzi swą ręką, pomnaża je.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 12, 'Przedłużająca się nadzieja sprawia ból sercu, a spełnione pragnienie jest drzewem życia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 13, 'Kto gardzi słowem Bożym, ten zginie, a kto się boi przykazania, dostanie nagrodę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 14, 'Prawo mądrego jest źródłem życia, by uniknąć sideł śmierci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 15, 'Prawdziwy rozum daje łaskę, a droga przewrotnych jest ciężka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 16, 'Każdy roztropny postępuje rozważnie, a głupi ujawnia głupotę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 17, 'Niegodziwy posłaniec popada w zło, a wierny wysłannik jest lekarstwem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 18, 'Ubóstwo i hańba spadną na tego, który odrzuca karność, a kto szanuje upomnienia, dozna czci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 19, 'Spełnione pragnienie jest słodkie dla duszy, a odwrócenie się od zła budzi odrazę w głupcach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 20, 'Kto przestaje z mądrymi, będzie mądry, a towarzysz głupców będzie zniszczony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 21, 'Nieszczęście ściga grzeszników, a sprawiedliwych Bóg nagrodzi dobrem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 22, 'Dobry człowiek zostawia dziedzictwo dzieciom swoich dzieci, a majątek grzesznika jest zachowany dla sprawiedliwego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 23, 'Obfita żywność jest na roli ubogich, lecz i ta może niszczeć przez nieroztropność.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 24, 'Kto oszczędza swą rózgę, nienawidzi swego syna, a kto go kocha, karze w porę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 25, 'Sprawiedliwy je i syci swoją duszę, a żołądek niegodziwych cierpi niedostatek.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 1, 'Mądra kobieta buduje swój dom, a głupia burzy go własnymi rękami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 2, 'Kto postępuje w sposób prawy, boi się Pana, a przewrotny na swoich drogach gardzi nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 3, 'W ustach głupiego jest rózga pychy, a mądrych strzegą ich wargi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 4, 'Gdzie nie ma wołów, żłób jest pusty, lecz dzięki sile wołów mnoży się obfitość zboża.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 5, 'Wierny świadek nie kłamie, a fałszywy świadek mówi kłamstwa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 6, 'Szyderca szuka mądrości, a nie znajduje, lecz rozumnemu wiedza przychodzi łatwo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 7, 'Odsuń się od głupiego, gdyż nie znajdziesz u niego warg rozumnych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 8, 'Mądrość roztropnego to poznanie swojej drogi, a głupotą głupich jest oszustwo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 9, 'Głupcy szydzą z grzechu, a u prawych jest przychylność.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 10, 'Serce zna własną gorycz, a obcy nie wtrąca się w jego radość.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 11, 'Dom niegodziwych będzie zgładzony, a mieszkanie prawych zakwitnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 12, 'Jest droga, która człowiekowi wydaje się słuszna, lecz końcem jej jest droga do śmierci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 13, 'Nawet w śmiechu serce boleje, a końcem takiej wesołości jest smutek.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 14, 'Serce odstępcy nasyci się jego drogami, a dobry człowiek – swoimi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 15, 'Prosty wierzy każdemu słowu, a roztropny zważa na swoje kroki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 16, 'Mądry boi się i odwraca się od zła, ale głupi w swym szaleństwie jest pewny siebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 17, 'Człowiek porywczy popełnia głupstwa, a podstępny jest znienawidzony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 18, 'Prości ludzie dziedziczą głupotę, a roztropni są koronowani wiedzą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 19, 'Źli kłaniają się przed dobrymi, a niegodziwi u bram sprawiedliwego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 20, 'Ubogi jest znienawidzony nawet przez swego bliźniego, a bogaty ma wielu przyjaciół.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 21, 'Kto gardzi swym bliźnim, ten grzeszy, a kto lituje się nad ubogimi, jest błogosławiony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 22, 'Czyż nie błądzą ci, którzy obmyślają zło? Ale miłosierdzie i prawda są z tymi, którzy obmyślają dobro.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 23, 'Każda praca przynosi pożytek, a puste słowa prowadzą do nędzy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 24, 'Koroną mądrych jest ich bogactwo, ale głupota głupich pozostaje głupotą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 25, 'Prawdomówny świadek ocala dusze, a fałszywy mówi kłamstwa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 26, 'W bojaźni Pana jest mocne zaufanie, a jego synowie będą mieć ucieczkę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 27, 'Bojaźń Pana jest źródłem życia, by uniknąć sideł śmierci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 28, 'Liczny lud to chwała króla, a brak ludu to zguba władcy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 29, 'Nieskory do gniewu jest bardzo roztropny, lecz porywczy wywyższa głupotę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 30, 'Zdrowe serce jest życiem ciała, a zazdrość jest zgnilizną kości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 31, 'Kto gnębi ubogiego, uwłacza jego Stwórcy, a czci go ten, kto lituje się nad ubogim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 32, 'Niegodziwy zostaje wygnany z powodu swojego zła, a sprawiedliwy ma nadzieję nawet w czasie swojej śmierci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 33, 'Mądrość spoczywa w sercu rozumnego, a co jest w sercu głupich, wychodzi na jaw.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 34, 'Sprawiedliwość wywyższa naród, a grzech jest hańbą narodów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 35, 'Król jest przychylny dla roztropnego sługi, lecz gniewa się na tego, który przynosi hańbę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 1, 'Łagodna odpowiedź uśmierza zapalczywość, a przykre słowa wzniecają gniew.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 2, 'Język mądrych zdobi wiedzę, ale usta głupich tryskają głupotą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 3, 'Oczy Pana są na każdym miejscu, upatrują złych i dobrych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 4, 'Zdrowy język jest drzewem życia, a jego przewrotność jest zniszczeniem dla ducha.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 5, 'Głupi gardzi pouczeniem swego ojca, a kto przyjmuje upomnienia, jest roztropny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 6, 'W domu sprawiedliwego jest wielki dostatek, a w dochodach niegodziwego jest zamieszanie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 7, 'Wargi mądrych szerzą wiedzę, a serce głupich nie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 8, 'Ofiara niegodziwych budzi odrazę w Panu, a modlitwa prawych mu się podoba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 9, 'Droga niegodziwego wzbudza odrazę w Panu, a miłuje on tego, kto podąża za sprawiedliwością.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 10, 'Sroga kara należy się temu, kto zbacza z drogi, a kto nienawidzi upomnień, umrze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 11, 'Piekło i zatracenie są przed Panem; o ileż bardziej serca synów ludzkich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 12, 'Szyderca nie miłuje tego, który go strofuje, ani nie pójdzie do mądrych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 13, 'Radosne serce rozwesela twarz, ale gdy smutek w sercu, duch jest przygnębiony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 14, 'Serce rozumne szuka wiedzy, a usta głupich karmią się głupotą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 15, 'Wszystkie dni strapionego są złe, ale kto jest wesołego serca, ma nieustanną ucztę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 16, 'Lepiej mieć mało z bojaźnią Pana niż wielki skarb z kłopotem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 17, 'Lepsza jest potrawa z jarzyn, gdzie miłość, niż tuczny wół, gdzie panuje nienawiść.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 18, 'Człowiek gniewny wszczyna kłótnie, a nieskory do gniewu łagodzi spory.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 19, 'Droga leniwego jest jak płot cierniowy, a ścieżka prawych jest wyrównana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 20, 'Mądry syn jest radością ojca, a człowiek głupi gardzi własną matką.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 21, 'Głupota jest radością dla nierozumnego, a człowiek roztropny postępuje uczciwie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 22, 'Gdzie nie ma rady, nie udają się zamysły; powiodą się zaś przy mnóstwie doradców.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 23, 'Człowiek cieszy się z odpowiedzi swoich ust, a słowo powiedziane we właściwym czasie jakże jest dobre!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 24, 'Droga życia dla mądrego jest w górze, aby uniknął głębokiego piekła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 25, 'Pan zniszczy dom pysznych, a utwierdzi granicę wdowy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 26, 'Myśli złego budzą odrazę w Panu, a słowa czystych są przyjemne.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 27, 'Kto jest chciwy zysku, ściąga kłopoty na własny dom, a kto nienawidzi darów, będzie żył.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 28, 'Serce sprawiedliwego rozmyśla nad odpowiedzią, a usta niegodziwych tryskają złymi rzeczami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 29, 'Pan jest daleko od niegodziwych, ale wysłuchuje modlitwy sprawiedliwych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 30, 'Światło oczu rozwesela serce, a dobra wieść tuczy kości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 31, 'Ucho, które słucha upomnienia życia, będzie mieszkać pośród mądrych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 32, 'Kto odrzuca karność, gardzi własną duszą, a kto przyjmuje upomnienie, nabiera rozumu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 33, 'Bojaźń Pana jest pouczeniem w mądrości, a pokora poprzedza chwałę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 1, 'W człowieku są zamysły serca, ale odpowiedź języka jest od Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 2, 'Wszystkie drogi człowieka są czyste w jego oczach, ale Pan waży duchy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 3, 'Powierz Panu swe dzieła, a twoje zamysły będą utwierdzone.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 4, 'Pan uczynił wszystko dla samego siebie, nawet niegodziwego na dzień zła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 5, 'Każdy, który jest wyniosłego serca, budzi odrazę w Panu; choć weźmie innych do pomocy, nie uniknie kary.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 6, 'Dzięki miłosierdziu i prawdzie oczyszcza się nieprawość, a w bojaźni Pana oddalamy się od zła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 7, 'Gdy drogi człowieka podobają się Panu, to godzi z nim nawet jego nieprzyjaciół.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 8, 'Lepiej mieć mało ze sprawiedliwością niż wiele dochodów nieprawnych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 9, 'Serce człowieka obmyśla swe drogi, ale Pan kieruje jego krokami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 10, 'Wyrok Boży jest na wargach króla; jego usta nie błądzą w sądzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 11, 'Sprawiedliwa waga i szale należą do Pana i wszystkie odważniki w worku są jego dziełem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 12, 'Popełnienie niegodziwości budzi odrazę w królach, bo sprawiedliwością tron jest umocniony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 13, 'Wargi sprawiedliwe są rozkoszą królów, kochają oni tego, który mówi to, co słuszne.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 14, 'Gniew króla jest posłańcem śmierci, ale mądry człowiek przebłaga go.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 15, 'W jasności twarzy króla jest życie, a jego przychylność jest jak obłok z późnym deszczem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 16, 'O wiele lepiej jest nabyć mądrość niż złoto; a nabyć rozum lepiej niż srebro.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 17, 'Droga prawych to odstąpić od zła; kto strzeże swojej drogi, strzeże swej duszy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 18, 'Pycha poprzedza zgubę, a wyniosły duch – upadek.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 19, 'Lepiej być uniżonego ducha z pokornymi, niż dzielić łup z pysznymi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 20, 'Kto zważa na słowo, znajdzie dobro, a kto ufa Panu, jest błogosławiony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 21, 'Kto jest mądrego serca, zwie się rozumnym, a słodycz warg pomnaża wiedzę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 22, 'Rozum jest zdrojem życia dla tych, którzy go mają, a pouczenie głupich jest głupotą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 23, 'Serce mądrego czyni jego usta roztropnymi i dodaje nauki jego wargom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 24, 'Miłe słowa są jak plaster miodu, słodycz dla duszy i lekarstwo dla kości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 25, 'Jest droga, która wydaje się człowiekowi słuszna, ale jej końcem jest droga do śmierci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 26, 'Robotnik pracuje dla siebie, bo usta pobudzają go do tego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 27, 'Człowiek nikczemny wykopuje zło, a na jego wargach jakby ogień płonący.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 28, 'Człowiek przewrotny rozsiewa spory, a plotkarz rozdziela przyjaciół.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 29, 'Człowiek gwałtowny zwabia swego bliźniego i wprowadza go na drogę niedobrą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 30, 'Mruga swymi oczami, by knuć podstępy; rusza wargami i popełnia zło.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 31, 'Siwa głowa jest koroną chwały, zdobywa się ją na drodze sprawiedliwości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 32, 'Lepszy jest nieskory do gniewu niż mocarz, a kto panuje nad swym duchem, jest lepszy niż ten, kto zdobywa miasto.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 33, 'Losy wrzuca się w zanadrze, ale całe rozstrzygnięcie ich zależy od Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 1, 'Lepszy jest kęs suchego chleba, a przy tym spokój, niż dom pełen bydła ofiarnego z kłótnią.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 2, 'Sługa roztropny będzie panował nad synem, który przynosi hańbę, i wraz z jego braćmi będzie miał udział w dziedzictwie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 3, 'Tygiel dla srebra, piec dla złota, ale serca bada Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 4, 'Zły zważa na wargi fałszywe, a kłamca słucha przewrotnego języka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 5, 'Kto naśmiewa się z ubogiego, uwłacza jego Stwórcy, a kto się cieszy z nieszczęścia, nie uniknie kary.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 6, 'Koroną starców są synowie synów, a chlubą synów są ich ojcowie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 7, 'Poważna mowa nie przystoi głupiemu, tym mniej kłamliwe usta dostojnikowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 8, 'Dar jest jak drogocenny kamień w oczach tego, kto go posiada; gdziekolwiek z nim zmierza, ma powodzenie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 9, 'Kto kryje grzech, szuka miłości, a kto wyjawia sprawę, rozdziela przyjaciół.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 10, 'Nagana lepiej działa na rozumnego niż sto razów na głupiego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 11, 'Zły szuka jedynie buntu; dlatego zostanie wysłany przeciw niemu okrutny posłaniec.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 12, 'Lepiej człowiekowi spotkać się z niedźwiedzicą, której zabrano młode, niż z głupim w jego głupocie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 13, 'Kto odpłaca złem za dobro, temu zło z domu nie ustąpi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 14, 'Kto zaczyna kłótnię, jest jak ten, co puszcza wodę; dlatego zaniechaj sporu, zanim wybuchnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 15, 'Kto usprawiedliwia niegodziwego i kto potępia sprawiedliwego, obaj budzą odrazę w Panu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 16, 'Na cóż w ręku głupiego pieniądze, by zdobyć mądrość, skoro nie ma rozumu?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 17, 'Przyjaciel kocha w każdym czasie, a brat rodzi się w nieszczęściu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 18, 'Nierozumny człowiek daje porękę i ręczy na oczach przyjaciela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 19, 'Kto kocha grzech, kocha spór, a kto podwyższa swoją bramę, szuka zagłady.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 20, 'Przewrotny w sercu nie znajduje dobra, a kto ma przewrotny język, wpadnie w zło.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 21, 'Kto spłodzi głupca, zrobi to na swój smutek, a ojciec głupiego nie doznaje radości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 22, 'Wesołe serce działa dobrze jak lekarstwo, a przygnębiony duch wysusza kości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 23, 'Niegodziwy bierze dar z zanadrza, aby wypaczać ścieżki sądu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 24, 'Mądrość jest przed obliczem rozumnego, a oczy głupca są aż na krańcu ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 25, 'Głupi syn jest zmartwieniem dla ojca i goryczą dla rodzicielki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 26, 'Zaprawdę to niedobrze wymierzyć karę sprawiedliwemu ani bić władców za prawość.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 27, 'Kto ma wiedzę, powściąga swoje słowa, człowiek roztropny jest zacnego ducha.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 28, 'Nawet głupi, gdy milczy, uchodzi za mądrego, a kto zamyka swoje wargi – za rozumnego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 1, 'Samolub szuka tego, co mu się podoba, i wtrąca się w każdą sprawę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 2, 'Głupi nie ma upodobania w rozumie, lecz w tym, co serce mu objawia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 3, 'Gdy przychodzi niegodziwy, przychodzi też pogarda, a z hańbą urąganie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 4, 'Słowa ust człowieka są jak głębokie wody, a źródło mądrości jak płynący potok.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 5, 'Niedobrze przez wzgląd na osobę niegodziwą krzywdzić sprawiedliwego w sądzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 6, 'Wargi głupiego wchodzą w spór, a jego usta wołają o razy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 7, 'Usta głupiego są jego zgubą, a jego wargi sidłem jego duszy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 8, 'Słowa plotkarza są jak rany i przenikają do głębi wnętrzności.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 9, 'Kto jest niedbały w pracy, jest bratem marnotrawcy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 10, 'Imię Pana jest potężną wieżą, sprawiedliwy ucieka do niej i jest bezpieczny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 11, 'Zamożność bogacza jest jego warownym miastem i jak wysoki mur w jego wyobrażeniu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 12, 'Przed upadkiem serce człowieka jest wyniosłe, a chwałę poprzedza pokora.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 13, 'Kto odpowiada, zanim wysłucha, ujawnia głupotę i ściąga na siebie hańbę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 14, 'Duch człowieka zniesie jego chorobę, ale któż zniesie strapionego ducha?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 15, 'Serce rozumnego zdobywa wiedzę, a ucho mądrych szuka wiedzy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 16, 'Dar człowieka toruje mu drogę i prowadzi go przed wielkich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 17, 'Ten, który jest pierwszy w swojej sprawie, zdaje się sprawiedliwy, ale przychodzi jego bliźni i sprawdza go.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 18, 'Los kładzie kres sporom i rozstrzyga między możnymi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 19, 'Brat obrażony trudniejszy do zdobycia niż warowne miasto, a spory są jak rygle w zamku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 20, 'Owocem swoich ust nasyci człowiek swoje wnętrze, nasyci się plonem swych warg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 21, 'Śmierć i życie są w mocy języka, a kto go miłuje, spożyje jego owoc.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 22, 'Kto znalazł żonę, znalazł coś dobrego i dostąpił łaski od Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 23, 'Ubogi prosi pokornie, ale bogaty odpowiada surowo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 24, 'Człowiek, który ma przyjaciół, musi obchodzić się z nimi po przyjacielsku, a jest przyjaciel, który przylgnie bardziej niż brat.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 1, 'Lepszy jest ubogi, który postępuje uczciwie, niż człowiek o przewrotnych wargach, który jest głupcem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 2, 'Nie jest też dobrze, by dusza nie miała wiedzy, a kto jest prędkich nóg, grzeszy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 3, 'Głupota człowieka wypacza jego drogę, a jego serce zapala się gniewem przeciwko Panu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 4, 'Bogactwo przyciąga wielu przyjaciół, ale ubogi zostaje odłączony od przyjaciela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 5, 'Fałszywy świadek nie uniknie kary, a kto mówi kłamstwa, nie ujdzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 6, 'Wielu uprasza o przychylność dostojnika i każdy jest przyjacielem człowieka hojnego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 7, 'Wszyscy bracia ubogiego nienawidzą go, tym bardziej oddalają się od niego jego przyjaciele; ściga ich słowami, ale ich nie ma.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 8, 'Kto zdobywa rozum, miłuje swoją duszę, a kto strzeże roztropności, znajdzie dobro.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 9, 'Fałszywy świadek nie uniknie kary, a kto mówi kłamstwa, zginie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 10, 'Głupiemu nie przystoi życie w rozkoszach, tym mniej słudze panować nad książętami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 11, 'Roztropność człowieka powściąga jego gniew, a jego chwałą jest darować wykroczenie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 12, 'Gniew króla jest jak ryk lwa, a jego przychylność jak rosa na trawie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 13, 'Głupi syn jest utrapieniem dla swego ojca, a kłótliwa żona jest jak nieustanne kapanie z dachu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 14, 'Dom i bogactwo są dziedzictwem po ojcach, ale roztropna żona jest od Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 15, 'Lenistwo pogrąża w twardym śnie, a leniwa dusza będzie cierpieć głód.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 16, 'Kto przestrzega przykazania, zachowuje swoją duszę, ale kto gardzi swymi drogami, zginie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 17, 'Kto lituje się nad ubogim, pożycza Panu, a on mu odpłaci za jego dobrodziejstwo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 18, 'Karz swego syna, dopóki jest nadzieja, i niech twoja dusza mu nie pobłaża z powodu jego płaczu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 19, 'Człowiek wielkiego gniewu poniesie karę, a jeśli go uwolnisz, znowu będziesz musiał to zrobić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 20, 'Posłuchaj rady i przyjmij pouczenie, abyś był mądry u kresu swych dni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 21, 'Wiele jest zamysłów w sercu człowieka, ale rada Pana się ostoi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 22, 'Pragnienie człowieka to jego dobroczynność i lepszy jest ubogi niż kłamca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 23, 'Bojaźń Pana prowadzi do życia, a kto ją ma, spocznie syty i nie nawiedzi go zło.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 24, 'Leniwy kryje swą rękę pod pachę i do ust jej nie podnosi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 25, 'Uderz szydercę, a prosty będzie roztropniejszy; strofuj rozumnego, a pojmie wiedzę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 26, 'Kto trwoni dobra ojca i wypędza matkę, ten jest synem, który przynosi wstyd i hańbę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 27, 'Synu mój, przestań słuchać pouczeń, które cię odwodzą od słów rozumnych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 28, 'Nikczemny świadek naśmiewa się z sądu, a usta niegodziwych pożerają nieprawość.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 29, 'Sądy są przygotowane dla szyderców, a razy na grzbiet głupców.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 1, 'Wino jest szydercą, mocny trunek – wrzaskliwy, a każdy, kto zostaje zwiedziony przez nie, jest niemądry.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 2, 'Strach, który budzi król, jest jak ryk lwa; kto go rozgniewa, grzeszy przeciwko swojej duszy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 3, 'Zaprzestać sporu jest zaszczytem dla człowieka, ale każdy głupiec się w niego wdaje.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 4, 'Leniwy nie orze z powodu zimna; dlatego będzie żebrać we żniwa, ale nic nie otrzyma.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 5, 'Rada w sercu człowieka jest jak głęboka woda, lecz człowiek roztropny zaczerpnie jej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 6, 'Większość ludzi przechwala się swoją dobrocią, ale wiernego człowieka któż znajdzie?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 7, 'Sprawiedliwy postępuje uczciwie, błogosławione są po nim jego dzieci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 8, 'Król siedzący na swoim sędziowskim tronie rozprasza swoimi oczami wszelkie zło.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 9, 'Któż może powiedzieć: Oczyściłem swoje serce, jestem czysty od swego grzechu?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 10, 'Dwojakie odważniki i dwojaka miara – obydwa budzą odrazę w Panu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 11, 'Nawet dziecko poznaje się po uczynkach, czy jego czyn jest czysty i prawy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 12, 'Ucho, które słyszy, i oko, które widzi, oba uczynił Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 13, 'Nie kochaj spania, byś nie zubożał; otwórz oczy, a nasycisz się chlebem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 14, 'To liche, to liche, mówi kupujący, ale chwali się, gdy odchodzi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 15, 'Istnieje złoto i obfitość pereł, ale wargi rozumne są kosztownym klejnotem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 16, 'Zabierz szatę tego, który ręczył za obcego, a od tego, który ręczył za cudzą kobietę, zabierz zastaw.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 17, 'Chleb oszustwa smakuje człowiekowi, ale potem jego usta będą napełnione piaskiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 18, 'Zamysły są utwierdzone dzięki radzie, a wojnę prowadź z rozwagą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 19, 'Plotkarz zdradza tajemnice; dlatego nie zadawaj się z tym, który pochlebia wargami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 20, 'Kto złorzeczy swemu ojcu albo matce, tego pochodnia zgaśnie w gęstych ciemnościach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 21, 'Dziedzictwo prędko nabyte na początku nie będzie błogosławione na końcu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 22, 'Nie mów: Odpłacę złem. Czekaj na Pana, a wybawi cię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 23, 'Dwojakie odważniki budzą odrazę w Panu, a fałszywa waga nie jest dobra.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 24, 'Od Pana pochodzą drogi człowieka; jakże może człowiek zrozumieć własną drogę?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 25, 'Sidłem dla człowieka jest pożreć to, co święte, i zastanowić się dopiero po złożeniu ślubów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 26, 'Mądry król rozprasza niegodziwych i wywiera na nich zemstę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 27, 'Duch człowieka jest pochodnią Pana, która bada wszystkie skrytości wnętrza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 28, 'Miłosierdzie i prawda strzegą króla, a jego tron oparty jest na miłosierdziu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 29, 'Chlubą młodzieńców jest ich siła, a ozdobą starców – sędziwość.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 30, 'Siność ran oczyszcza zło, a razy – głębię wnętrza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 1, 'Serce króla jest w ręku Pana jak potoki wód; kieruje je, dokąd chce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 2, 'Wszelka droga człowieka jest słuszna w jego oczach, ale Pan waży serca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 3, 'Czynienie sprawiedliwości i sądu bardziej się podobają Panu niż ofiara.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 4, 'Wyniosłe oczy, pyszne serce i praca niegodziwych są grzechem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 5, 'Myśli pracowitego przynoszą pewny dostatek, a myśli każdego spieszącego się – niedostatek.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 6, 'Gromadzenie skarbów kłamliwym językiem jest przemijającą marnością tych, którzy szukają śmierci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 7, 'Grabież niegodziwych zniszczy ich, bo nie chcą czynić tego, co sprawiedliwe.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 8, 'Droga człowieka jest przewrotna i obca, ale dzieło czystego jest prawe.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 9, 'Lepiej mieszkać w kącie dachu niż z kłótliwą żoną w przestronnym domu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 10, 'Dusza niegodziwego pragnie zła, a jego bliźni nie znajduje łaski w jego oczach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 11, 'Gdy się karze szydercę, prosty mądrzeje, a gdy uczą mądrego, przyjmuje wiedzę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 12, 'Sprawiedliwy zważa na dom niegodziwego, ale Bóg powala niegodziwych za ich nieprawość.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 13, 'Kto zatyka swe ucho na wołanie ubogiego, ten sam będzie wołał, a nie zostanie wysłuchany.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 14, 'Potajemny dar łagodzi zapalczywość i upominek w zanadrzu uspokaja wielki gniew.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 15, 'Radością jest dla sprawiedliwego czynić sąd, a na czyniących nieprawość przyjdzie zniszczenie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 16, 'Człowiek, który zbacza z drogi mądrości, odpocznie w zgromadzeniu umarłych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 17, 'Kto kocha zabawę, zubożeje, a kto kocha wino i olejek, nie wzbogaci się.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 18, 'Niegodziwy będzie okupem za sprawiedliwego, a przewrotny – za prawych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 19, 'Lepiej mieszkać na pustyni niż z kłótliwą i gniewliwą żoną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 20, 'Pożądany skarb i olej są w mieszkaniu mądrego, ale głupiec je trwoni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 21, 'Kto podąża za sprawiedliwością i miłosierdziem, znajduje życie, sprawiedliwość i chwałę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 22, 'Mądry wdziera się do miasta mocarzy i burzy potęgę ich ufności.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 23, 'Kto strzeże swoich ust i języka, strzeże swojej duszy przed utrapieniem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 24, 'Hardy i pyszny szyderca – oto imię tego, kto działa w pysznym gniewie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 25, 'Pragnienie leniwego zabija go, bo jego ręce nie chcą pracować.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 26, 'Przez cały dzień pożąda on zachłannie, a sprawiedliwy daje i nie szczędzi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 27, 'Ofiara niegodziwych budzi odrazę, a cóż dopiero, gdy ją w niegodziwości ofiarują.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 28, 'Fałszywy świadek zginie, lecz kto słucha, będzie mówił nieustannie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 29, 'Niegodziwy ma upór na twarzy, ale prawy wytycza swoją drogę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 30, 'Nie ma mądrości ani rozumu, ani rady przeciwko Panu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 31, 'Konia przygotowują na dzień bitwy, ale wybawienie zależy od Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 1, 'Cenniejsze jest dobre imię niż wielkie bogactwa, a przychylność lepsza niż srebro i złoto.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 2, 'Bogaty i ubogi spotykają się, Pan jest stwórcą obydwu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 3, 'Roztropny dostrzega zło i ukrywa się, ale prości idą dalej i ponoszą karę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 4, 'Owocem pokory i bojaźni Pana jest bogactwo, chwała i życie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 5, 'Ciernie i sidła są na drodze przewrotnego; kto strzeże swej duszy, trzyma się z dala od nich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 6, 'Pouczaj dziecko w drodze, którą ma iść, a gdy się zestarzeje, nie odstąpi od niej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 7, 'Bogaty panuje nad ubogimi, a ten, co pożycza, jest sługą tego, który mu pożycza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 8, 'Kto sieje nieprawość, będzie żąć cierpienie, a rózga jego gniewu przepadnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 9, 'Kto ma dobrotliwe oko, będzie błogosławiony, bo dzieli się swym chlebem z ubogim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 10, 'Wyrzuć szydercę, a ustanie spór, owszem, zakończy się kłótnia i zniewaga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 11, 'Kto kocha czystość serca, tego wdzięk warg sprawi, że król będzie jego przyjacielem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 12, 'Oczy Pana strzegą wiedzy, a on obala słowa przewrotnego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 13, 'Leniwy mówi: Lew jest na dworze, będę zabity na środku ulicy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 14, 'Usta obcych kobiet są głębokim dołem; wpadnie tam ten, na kogo Pan się gniewa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 15, 'Głupota jest przywiązana do serca dziecka, ale rózga karności wypędzi ją z niego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 16, 'Kto ciemięży ubogiego, aby przysporzyć sobie bogactwa, i kto daje bogatemu, pewnie zubożeje.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 17, 'Nadstaw ucha i słuchaj słów mędrców, i skłoń swe serce do mojej wiedzy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 18, 'Bo to miło, jeśli zachowasz je w swoim sercu, będą razem ułożone na wargach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 19, 'Oznajmiłem to dzisiaj właśnie tobie, abyś pokładał ufność w Panu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 20, 'Czy nie napisałem ci znamienitych rzeczy zawierających rady i wiedzę;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 21, 'Aby dać ci poznać pewność słów prawdy; abyś umiał odpowiedzieć słowami prawdy tym, którzy do ciebie posyłają?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 22, 'Nie okradaj nędzarza, ponieważ jest ubogi, ani nie uciskaj w bramie biednego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 23, 'Pan bowiem będzie bronił ich sprawy i wydrze duszę tym, którzy im wydzierają.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 24, 'Nie przyjaźnij się z człowiekiem gniewliwym i nie obcuj z człowiekiem porywczym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 25, 'Byś nie przywykł do jego dróg i nie zastawił sideł na swą duszę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 26, 'Nie bądź z tych, którzy dają porękę, ani z tych, którzy ręczą za długi;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 27, 'Jeśli nie masz czym zapłacić, dlaczego miałby ktoś zabrać spod ciebie posłanie?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 28, 'Nie przesuwaj dawnej granicy, którą ustalili twoi ojcowie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 29, 'Widzisz człowieka pilnego w swoich sprawach? On będzie stał przed królami, nie będzie stał przed podłymi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 1, 'Gdy usiądziesz do posiłku z władcą, zważaj pilnie, co jest przed tobą;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 2, 'I przyłóż nóż do gardła, jeśli jesteś łakomy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 3, 'Nie pragnij jego przysmaków, bo to pokarm zwodniczy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 4, 'Nie zabiegaj o bogactwo, porzuć swoją mądrość.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 5, 'Czy obrócisz swoje oczy na to, co jest niczym? Bo bogactwa robią sobie skrzydła i ulatują do nieba jak orzeł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 6, 'Nie jedz chleba człowieka, który ma złe oko, ani nie pożądaj jego przysmaków.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 7, 'Bo jak myśli w swym sercu, taki on jest. Jedz i pij – mówi do ciebie, ale jego serce nie jest z tobą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 8, 'Kęs, który zjadłeś, zwrócisz i utracisz swoje wdzięczne słowa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 9, 'Nie mów do uszu głupca, bo wzgardzi mądrością twoich słów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 10, 'Nie przesuwaj dawnej granicy i nie wchodź na pole sierot.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 11, 'Bo ich obrońca jest mocny, przeprowadzi ich sprawę przeciwko tobie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 12, 'Nakłoń swoje serce na pouczenie, a swe uszy na słowa rozumne.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 13, 'Nie szczędź dziecku karcenia, bo jeśli je bijesz rózgą, nie umrze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 14, 'Będziesz je bił rózgą, a jego duszę ocalisz od piekła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 15, 'Synu mój, jeśli twoje serce będzie mądre, moje serce będzie się radowało, właśnie moje;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 16, 'I moje nerki będą się weselić, gdy twoje usta będą mówiły to, co jest prawe.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 17, 'Niech twoje serce nie zazdrości grzesznikom, lecz każdego dnia postępuj w bojaźni Pana;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 18, 'Bo koniec jest pewny i twoja nadzieja nie będzie zawiedziona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 19, 'Słuchaj, synu mój, i bądź mądry, i skieruj swoje serce na drogę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 20, 'Nie bywaj wśród pijaków ani wśród obżerających się mięsem;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 21, 'Bo pijak i żarłok zubożeją, a ospały będzie chodził w łachmanach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 22, 'Słuchaj ojca, który cię spłodził, a nie gardź matką, gdy się zestarzeje.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 23, 'Kupuj prawdę i nie sprzedawaj jej; kupuj mądrość, karność i rozum.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 24, 'Ojciec sprawiedliwego będzie się wielce radował, a kto spłodzi mądrego, będzie się z niego cieszył.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 25, 'Niech się weseli twój ojciec i matka i niech się raduje ta, która cię rodziła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 26, 'Synu mój, daj mi swoje serce, a niech twoje oczy strzegą moich dróg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 27, 'Bo nierządnica jest głębokim dołem, a cudza kobieta jest ciasną studnią.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 28, 'Ona też czyha jak zbój i pomnaża przewrotnych wśród ludzi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 29, 'U kogo biada? U kogo żal? U kogo kłótnie? U kogo szemranie? Kto ma rany bez powodu? Kto ma zaczerwienione oczy?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 30, 'Ci, którzy przesiadują przy winie; ci, którzy idą szukać zmieszanego wina.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 31, 'Nie patrz na wino, gdy się czerwieni; gdy wydaje łunę swą w kielichu, a samo się przesuwa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 32, 'Na koniec ugryzie jak wąż i ukąsi jak żmija;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 33, 'Twoje oczy będą patrzeć na cudze kobiety, a twoje serce będzie mówiło rzeczy przewrotne;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 34, 'I będziesz jak ten, który leży na środku morza, i jak ten, który śpi na szczycie masztu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 35, 'Powiesz: Bili mnie, a nie bolało, uderzyli mnie, a nic nie czułem. Gdy się obudzę, znów go poszukam.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 1, 'Nie zazdrość złym ludziom ani nie pragnij z nimi przebywać;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 2, 'Ich serce bowiem obmyśla przemoc, a ich wargi mówią o krzywdzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 3, 'Dom buduje się mądrością, a umacnia się rozumem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 4, 'Dzięki wiedzy komory będą napełnione wszelkimi kosztownymi i przyjemnymi bogactwami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 5, 'Mądry człowiek jest silny, a mąż, który ma wiedzę, dodaje siły.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 6, 'Bo dzięki mądrej radzie poprowadzisz wojnę, a mnóstwo doradców da ci wybawienie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 7, 'Mądrość jest dla głupca zbyt wzniosła; nie otwiera ust swoich w bramie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 8, 'Kto knuje zło, będzie zwany złośliwym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 9, 'Obmyślanie głupoty jest grzechem, a szyderca budzi odrazę w ludziach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 10, 'Jeśli w dniu ucisku ustaniesz, twoja siła jest słaba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 11, 'Jeśli odmówisz ratunku prowadzonym na śmierć i tym, którzy idą na stracenie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 12, 'Jeśli powiesz: Nie wiedzieliśmy o tym; czy ten, który waży serca, nie rozumie? A ten, który strzeże twojej duszy, nie pozna? I czy nie odda człowiekowi według jego uczynków?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 13, 'Synu mój, jedz miód, bo jest dobry, i plaster miodu słodki dla twojego podniebienia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 14, 'Tak będzie poznanie mądrości dla twojej duszy; jeśli ją znajdziesz, będzie nagroda, a twoja nadzieja nie będzie zawiedziona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 15, 'Nie czyhaj, niegodziwcze, przed mieszkaniem sprawiedliwego, nie burz miejsca jego odpoczynku;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 16, 'Bo sprawiedliwy upada siedem razy, jednak znowu powstaje; a niegodziwi popadną w nieszczęście.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 17, 'Nie ciesz się, gdy twój nieprzyjaciel upadnie, i niech twoje serce się nie raduje, gdy się potknie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 18, 'Aby Pan tego nie widział i nie uznał za zło, i nie odwrócił od niego swojego gniewu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 19, 'Nie gniewaj się z powodu złoczyńców ani nie zazdrość niegodziwym;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 20, 'Bo zły nie otrzyma nagrody, pochodnia niegodziwych zostanie zgaszona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 21, 'Synu mój, bój się Pana i króla, a nie przestawaj z chwiejnymi;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 22, 'Bo ich nieszczęście nastąpi nagle, a któż zna upadek obydwóch?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 23, 'I to też należy do mądrych. Niedobrze jest mieć wzgląd na osobę w sądzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 24, 'Kto mówi niegodziwemu: Jesteś sprawiedliwy, tego będą ludzie przeklinać, a narody będą się nim brzydzić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 25, 'A ci, którzy go strofują, będą szczęśliwi i przyjdzie na nich obfite błogosławieństwo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 26, 'Pocałują wargi tego, który daje słuszną odpowiedź.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 27, 'Przygotuj swoją pracę na zewnątrz, a wykonuj ją na swoim polu, a potem buduj swój dom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 28, 'Nie bądź bez powodu świadkiem przeciw swemu bliźniemu ani nie oszukuj swymi wargami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 29, 'Nie mów: Zrobię mu, jak on mi zrobił, oddam temu człowiekowi według jego uczynku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 30, 'Szedłem koło pola leniwego i koło winnicy nierozumnego;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 31, 'A oto wszystko zarosło cierniem, pokrzywy pokryły wszystko, a kamienny mur był zburzony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 32, 'Spojrzałem i rozważałem w sercu; obejrzałem i wyciągnąłem naukę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 33, 'Trochę snu, trochę drzemania, trochę założenia rąk, by odpocząć;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 34, 'A twoje ubóstwo przyjdzie jak podróżny, a niedostatek – jak mąż uzbrojony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 1, 'To również są przysłowia Salomona, które przepisali mężowie Ezechiasza, króla Judy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 2, 'Chwałą Boga jest sprawę taić, ale chwałą królów – dociekać sprawy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 3, 'Wysokość niebios i głębia ziemi, i serca królów są niezbadane.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 4, 'Usuń żużel ze srebra, a wyjdzie naczynie dla złotnika.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 5, 'Usuń niegodziwego sprzed króla, a jego tron umocni się w sprawiedliwości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 6, 'Nie wywyższaj się przed królem i nie stawaj na miejscu wielkich;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 7, 'Bo lepiej, żeby ci powiedziano: Podejdź tu, niż żeby cię poniżono przed księciem, którego twoje oczy widziały.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 8, 'Nie spiesz się do kłótni, bo na końcu nie będziesz wiedział, co zrobić, gdy cię zawstydzi twój bliźni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 9, 'Załatw sprawę ze swoim bliźnim i nie zdradzaj tajemnicy drugiemu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 10, 'By ten, który słucha, nie zawstydził cię, a twoja niesława nie przylgnęła do ciebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 11, 'Odpowiednio wypowiedziane słowo jest jak złote jabłko w srebrnych rzeźbach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 12, 'Jak złoty kolczyk i klejnot ze szczerego złota tak jest dla uszu posłusznego ten, który mądrze strofuje.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 13, 'Czym chłód śniegu w czasie żniwa, tym wierny posłaniec dla tych, którzy go posyłają, bo pokrzepia dusze swych panów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 14, 'Człowiek, który się chlubi zmyślonym darem, jest jak chmury i wiatr bez deszczu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 15, 'Cierpliwością można przekonać władcę, a łagodny język łamie kości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 16, 'Czy znalazłeś miód? Zjedz tyle, ile trzeba, byś objadłszy się, nie zwrócił go.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 17, 'Oddal nogę od domu bliźniego, by nie miał cię dość i cię nie znienawidził.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 18, 'Kto mówi fałszywe świadectwo przeciw swemu bliźniemu, jest młotem i mieczem, i ostrą strzałą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 19, 'Ufność w człowieka niewiernego w dniu ucisku jest jak złamany ząb i zwichnięta noga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 20, 'Jak ten, kto zabiera odzienie w czasie zimy i jak ocet na saletrze taki jest ten, kto śpiewa pieśni smutnemu sercu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 21, 'Jeśli twój nieprzyjaciel jest głodny, nakarm go chlebem, a jeśli jest spragniony, napój go wodą;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 22, 'Bo zgarniesz rozżarzone węgle na jego głowę, a Pan cię nagrodzi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 23, 'Jak północny wiatr przepędza deszcz, tak gniewna twarz przepędza plotkarski język.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 24, 'Lepiej mieszkać w kącie pod dachem niż z kłótliwą żoną w przestronnym domu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 25, 'Jak zimna woda dla pragnącej duszy, tak dobra wieść z dalekiej ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 26, 'Jak zmącone źródło i zepsuty zdrój, tak sprawiedliwy, który upada przed niegodziwym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 27, 'Niedobrze jest jeść za dużo miodu, a szukanie własnej chwały nie jest chwałą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 28, 'Człowiek, który nie panuje nad swoim duchem, jest jak miasto zburzone i bez muru.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 1, 'Jak śnieg w lecie i jak deszcz we żniwa, tak głupiemu nie przystoi chwała.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 2, 'Jak ptak się tuła i jak jaskółka lata, tak nie przyjdzie niezasłużone przekleństwo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 3, 'Bicz na konia, wędzidło na osła, a kij na grzbiet głupiego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 4, 'Nie odpowiadaj głupiemu według jego głupoty, abyś i ty nie był do niego podobny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 5, 'Odpowiedz głupiemu według jego głupoty, aby nie był mądry we własnych oczach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 6, 'Kto powierza głupiemu posłannictwo, odcina sobie nogi i pije na własną szkodę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 7, 'Jak nierówne są nogi chromego, tak przysłowie w ustach głupich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 8, 'Jaki jest ten, kto przywiązuje kamień do procy, taki ten, kto oddaje cześć głupiemu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 9, 'Jak cierń wbija się w rękę pijaka, tak przysłowie w ustach głupców.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 10, 'Wielki Bóg stworzył wszystko i odpłaca głupiemu, odpłaca również przestępcom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 11, 'Jak pies powraca do swoich wymiocin, tak głupi powtarza swoją głupotę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 12, 'Widzisz człowieka, co mądry w swoich oczach? Więcej nadziei dla głupca niż dla niego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 13, 'Leniwy mówi: Lew na drodze, lew na ulicach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 14, 'Jak drzwi się obracają na swoich zawiasach, tak leniwy na swoim łóżku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 15, 'Leniwy kryje rękę pod pachę, a ciężko mu ją podnosić do ust.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 16, 'Leniwy uważa się za mądrzejszego niż siedmiu odpowiadających rozsądnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 17, 'Kto przechodzi i wtrąca się w cudzy spór, jest jak ten, który łapie psa za uszy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 18, 'Jak szalony wypuszcza iskry, strzały i śmierć;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 19, 'Taki jest każdy, kto zwodzi swego bliźniego i mówi: Czy nie żartowałem?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 20, 'Gdy nie ma drew, ogień gaśnie; tak gdy nie ma plotkarza, ustaje spór.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 21, 'Jak węgiel dla żaru i drwa do ognia, tak kłótliwy człowiek do wzniecenia sporu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 22, 'Słowa plotkarzy są jak rany; przenikają do głębi wnętrzności.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 23, 'Palące wargi i złe serce są jak gliniana skorupa pokryta żużlem srebrnym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 24, 'Ten, kto nienawidzi, udaje wargami, lecz w sercu knuje podstęp.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 25, 'Gdy mówi miłym głosem, nie wierz mu, bo siedem obrzydliwości ma w swoim sercu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 26, 'Nienawiść człowieka bywa pokryta podstępem, ale jego niegodziwość będzie odkryta na zgromadzeniu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 27, 'Kto kopie dół, wpadnie w niego; kto kamień toczy, na niego się on obróci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 28, 'Kłamliwy język nienawidzi tych, których uciska, a usta pochlebcze prowadzą do zguby.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 1, 'Nie chlub się dniem jutrzejszym, bo nie wiesz, co dzień przyniesie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 2, 'Niech inny cię chwali, a nie twoje usta; ktoś obcy, a nie twoje wargi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 3, 'Ciężki jest kamień i piasek waży, ale gniew głupca cięższy od obu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 4, 'Okrutny jest gniew i straszliwa zapalczywość, lecz któż się ostoi przed zazdrością?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 5, 'Lepsza jest jawna nagana niż skryta miłość.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 6, 'Rany przyjaciela są wierne, ale pocałunki wroga są zwodnicze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 7, 'Dusza nasycona podepcze plaster miodu, a dla głodnej duszy wszystko, co gorzkie, jest słodkie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 8, 'Jak ptak odlatuje od swego gniazda, tak człowiek odchodzi od swego miejsca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 9, 'Maść i kadzidło radują serce, tak słodycz przyjaciela dzięki radzie od serca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 10, 'Nie opuszczaj swego przyjaciela ani przyjaciela twego ojca, a w dniu twego nieszczęścia nie wchodź do domu twego brata, bo lepszy jest sąsiad bliski niż brat daleki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 11, 'Bądź mądrym, synu mój, rozwesel moje serce, abym mógł odpowiedzieć temu, który mi urąga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 12, 'Roztropny dostrzega zło i ukrywa się, a prości idą dalej i ponoszą karę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 13, 'Zabierz szatę temu, kto ręczył za obcego, i od tego, który ręczył za cudzą kobietę, weź zastaw.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 14, 'Kto wczesnym rankiem błogosławi swemu przyjacielowi donośnym głosem, temu będzie to poczytane za przekleństwo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 15, 'Nieustające kapanie w dniu rzęsistego deszczu i kłótliwa żona są sobie podobne;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 16, 'Kto ją ukrywa, ukrywa wiatr i w prawej ręce wonny olejek, który sam siebie wydaje.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 17, 'Żelazo ostrzy się żelazem, tak człowiek zaostrza oblicze swego przyjaciela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 18, 'Kto strzeże drzewa figowego, spożyje jego owoc; tak kto posługuje swemu panu, dozna czci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 19, 'Jak w wodzie odbija się twarz, tak w sercu człowieka – człowiek.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 20, 'Piekło i zatracenie są nienasycone, tak oczy człowieka są niesyte.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 21, 'Czym dla srebra jest tygiel, a dla złota piec, tym dla człowieka pochwała.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 22, 'Choćbyś zmiażdżył głupca w moździerzu tłuczkiem razem z ziarnami, nie opuści go głupota.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 23, 'Doglądaj pilnie swego dobytku i troszcz się o swe stada.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 24, 'Bo bogactwo nie trwa na wieki ani korona przez wszystkie pokolenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 25, 'Trawa wyrasta, pojawia się zieleń, z gór zioła zbierają.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 26, 'Owce są na twoje szaty, a kozły są zapłatą za pole.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 27, 'I dosyć mleka koziego na pokarm dla ciebie, na wyżywienie twego domu i na utrzymanie twoich służebnic.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 1, 'Niegodziwi uciekają, choć nikt ich nie goni, ale sprawiedliwi są dzielni jak lew.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 2, 'Z powodu grzechu ziemi wielu jest jej władców, ale dzięki człowiekowi roztropnemu i rozumnemu będzie trwała.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 3, 'Ubogi człowiek, który gnębi biednych, jest jak gwałtowny deszcz, po którym nie ma chleba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 4, 'Ci, którzy odstępują od prawa, chwalą niegodziwych, lecz ci, którzy przestrzegają prawa, zwalczają ich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 5, 'Źli ludzie nie rozumieją sądu, ale ci, którzy szukają Pana, rozumieją wszystko.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 6, 'Lepszy jest ubogi, który postępuje uczciwie, niż człowiek przewrotny w swych drogach, chociaż jest bogaty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 7, 'Kto przestrzega prawa, jest rozumnym synem, a towarzysz rozwiązłych hańbi swego ojca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 8, 'Kto pomnaża swój majątek lichwą i odsetkami, zbiera go dla tego, kto zlituje się nad ubogimi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 9, 'Kto odwraca swe ucho, aby nie słyszeć prawa, nawet jego modlitwa budzi odrazę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 10, 'Kto sprowadza prawych na złą drogę, sam wpadnie we własny dół, ale nienaganni odziedziczą dobro.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 11, 'Bogacz jest mądry w swoich oczach, ale rozumny biedak go bada.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 12, 'Gdy sprawiedliwi się radują, jest wielka chwała, a gdy niegodziwi powstają, człowiek się kryje.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 13, 'Kto ukrywa swe grzechy, nie będzie miał szczęścia, ale kto je wyznaje i porzuca, dostąpi miłosierdzia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 14, 'Błogosławiony człowiek, który się zawsze boi, ale kto zatwardza swoje serce, wpada w nieszczęście.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 15, 'Jak lew ryczący i zgłodniały niedźwiedź, tak niegodziwy władca panujący nad ubogim ludem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 16, 'Władca bezrozumny jest wielkim ciemięzcą, a kto nienawidzi chciwości, przedłuży swoje dni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 17, 'Człowiek, który przeleje krew ludzką, ucieknie aż do dołu; niech nikt go nie zatrzymuje.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 18, 'Kto postępuje uczciwie, będzie wybawiony, a przewrotny na swoich drogach nagle upadnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 19, 'Kto uprawia swoją ziemię, nasyci się chlebem, a kto naśladuje próżniaków, nasyci się nędzą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 20, 'Wierny człowiek będzie opływał w błogosławieństwa, a kto chce się szybko wzbogacić, nie będzie bez winy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 21, 'Niedobrze jest mieć wzgląd na osobę, bo dla kęsa chleba niejeden popełni przestępstwo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 22, 'Kto chce szybko się wzbogacić, ma złe oko, a nie wie, że przyjdzie na niego bieda.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 23, 'Kto strofuje człowieka, znajdzie potem więcej przychylności niż ten, który pochlebia językiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 24, 'Kto kradnie ojcu lub matce i mówi: To nie grzech, jest towarzyszem zbójcy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 25, 'Człowiek wyniosły wszczyna spór, ale kto pokłada ufność w Panu, będzie nasycony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 26, 'Kto ufa własnemu sercu, jest głupi, a kto mądrze postępuje, będzie ocalony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 27, 'Kto daje ubogiemu, nie zazna braku, a na tego, kto odwraca swe oczy od niego, spadnie wiele przekleństw.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 28, 'Gdy niegodziwi powstają, ludzie się kryją, ale gdy giną, sprawiedliwi się mnożą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 1, 'Człowiek, który czyni twardym swój kark mimo częstych nagan, zostanie nagle zniszczony i pozbawiony ratunku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 2, 'Gdy sprawiedliwi są u władzy, lud się weseli, a gdy panują niegodziwi, lud wzdycha.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 3, 'Kto miłuje mądrość, raduje swego ojca, a kto zadaje się z nierządnicami, trwoni majątek.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 4, 'Król utwierdza ziemię sądem, ale kto przyjmuje dary, burzy ją.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 5, 'Człowiek, który pochlebia swemu bliźniemu, rozciąga sieć przed jego nogami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 6, 'Grzech złego człowieka jest jego sidłem, ale sprawiedliwy śpiewa i weseli się.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 7, 'Sprawiedliwy zważa na sprawę ubogich, a niegodziwemu nie zależy na jej poznawaniu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 8, 'Szydercy prowadzą miasto w sidła, ale mądrzy odwracają gniew.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 9, 'Jeśli mądry człowiek spiera się z głupim, czy się gniewa, czy się śmieje, nie ma pokoju.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 10, 'Krwiożercy nienawidzą prawego, ale sprawiedliwi szukają jego duszy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 11, 'Głupi ujawnia cały swój umysł, a mądry zachowuje go na później.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 12, 'Jeśli władca słucha kłamstw, to wszyscy jego słudzy są niegodziwi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 13, 'Ubogi i zdzierca spotykają się, a Pan obu oświeca oczy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 14, 'Tron króla, który sądzi ubogich według prawdy, będzie umocniony na wieki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 15, 'Rózga i upomnienia dają mądrość, a samowolne dziecko przynosi wstyd swojej matce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 16, 'Gdy niegodziwi się mnożą, to mnoży się i przestępstwo, lecz sprawiedliwi ujrzą ich upadek.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 17, 'Karć swego syna, a da ci odpocząć i przyniesie rozkosz twojej duszy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 18, 'Gdy nie ma proroctwa, lud ginie, a kto przestrzega prawa, jest błogosławiony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 19, 'Sługi nie poprawi się słowami, bo choć rozumie, jednak nie odpowiada.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 20, 'Widzisz człowieka, który jest pochopny w swoich słowach? Więcej nadziei dla głupca niż dla niego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 21, 'Kto czule wychowuje sługę od młodości, na ostatek będzie go miał za syna.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 22, 'Człowiek gniewliwy wszczyna spór, a człowiek porywczy mnoży grzechy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 23, 'Pycha człowieka poniża go, ale pokorny w duchu dostąpi chwały.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 24, 'Wspólnik złodzieja nienawidzi swojej duszy; słyszy przekleństwa, a nie wydaje go.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 25, 'Strach przed człowiekiem zastawia sidła, ale kto ufa Panu, będzie bezpieczny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 26, 'Wielu zabiega o względy władcy, ale sąd każdego człowieka pochodzi od Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 27, 'Bezbożny budzi odrazę w sprawiedliwych, a kto postępuje uczciwie, budzi odrazę w niegodziwych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 1, 'Słowa Agura, syna Jake, proroctwo tego człowieka do Itiela, do Itiela i Ukala.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 2, 'Zaprawdę jestem najgłupszym z ludzi i nie mam ludzkiego rozumu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 3, 'Ani nie nauczyłem się mądrości, ani nie mam wiedzy o tym, co święty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 4, 'Któż wstąpił do nieba i zstąpił? Któż zebrał wiatr w swoje garście? Któż zgarnął wody do swej szaty? Któż utwierdził wszystkie krańce ziemi? Jakie jest jego imię? A jakie jest imię jego syna? Czy wiesz?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 5, 'Każde słowo Boga jest czyste; on jest tarczą dla tych, którzy mu ufają.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 6, 'Nie dodawaj nic do jego słów, aby cię nie strofował i abyś nie okazał się kłamcą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 7, 'Proszę cię o dwie rzeczy; nie odmawiaj mi ich, zanim umrę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 8, 'Oddal ode mnie marność i słowo kłamliwe; nie dawaj mi ani ubóstwa, ani bogactwa; żyw mnie odpowiednim dla mnie pokarmem;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 9, 'Abym będąc syty, nie zaparł się ciebie i nie mówił: Kim jest Pan? Albo zubożawszy, nie kradł i nie brał imienia mego Boga nadaremnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 10, 'Nie oczerniaj sługi przed jego panem, aby ci nie złorzeczył i byś nie okazał się winny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 11, 'Jest pokolenie, które złorzeczy swemu ojcu i nie błogosławi swojej matce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 12, 'Jest pokolenie, które we własnych oczach jest czyste, lecz nie jest obmyte ze swego plugastwa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 13, 'Jest pokolenie, którego oczy są wyniosłe i powieki wzniesione.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 14, 'Jest pokolenie, którego zęby są jak miecze, a zęby trzonowe jak noże, by pożreć ubogich na ziemi i nędzarzy spośród ludzi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 15, 'Pijawka ma dwie córki, które mówią: Daj, daj. Trzy są rzeczy, które nie mogą się nasycić; cztery, które nie mówią: Dość.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 16, 'Grób, niepłodne łono, ziemia niesyta wody i ogień, który nie mówi: Dość.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 17, 'Oko, które wyśmiewa ojca i gardzi posłuszeństwem matce, wydziobią kruki nad potokami i wyjedzą orlęta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 18, 'Trzy są rzeczy dla mnie zbyt zdumiewające, czterech nie znam:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 19, 'Drogi orła w powietrzu, drogi węża na skale, drogi okrętu na środku morza i drogi mężczyzny z młodą kobietą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 20, 'Taka jest droga kobiety cudzołożnej: je i obciera swoje usta, i mówi: Nie zrobiłam nic złego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 21, 'Pod trzema rzeczami drży ziemia, czterech nie może znieść:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 22, 'Sługi, kiedy panuje, głupca, kiedy syci się chlebem;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 23, 'Obmierzłej kobiety, kiedy wychodzi za mąż, i służącej, kiedy dziedziczy po swojej pani.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 24, 'Cztery są rzeczy najmniejsze na ziemi, jednak mędrsze nad mędrców:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 25, 'Mrówki, lud słaby, a jednak w lecie przygotowują pokarm;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 26, 'Króliki, lud słaby, a jednak budują swój dom w skale;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 27, 'Szarańcze nie mają króla, a jednak wszystkie wyruszają chmarą;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 28, 'Pająk pracuje rękoma, a bywa w pałacach królewskich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 29, 'Trzy są rzeczy, które poruszają się wspaniale, cztery kroczą dostojnie:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 30, 'Lew, najsilniejszy wśród zwierząt, który przed nikim nie ustępuje;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 31, 'Chart i kozioł, i król, przeciw któremu nikt nie powstaje.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 32, 'Jeśli głupio postąpiłeś, wynosząc się, albo jeśli pomyślałeś źle, połóż rękę na ustach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 33, 'Jak ubijanie mleka daje masło i wycieranie nosa wywołuje krew, tak kto wzbudza gniew, wszczyna kłótnię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 1, 'Słowa króla Lemuela, proroctwo, którego nauczyła go jego matka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 2, 'Cóż, synu mój? Cóż, synu mojego łona? I cóż, synu moich ślubów?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 3, 'Nie oddawaj kobietom swej siły ani twoich dróg temu, co prowadzi do zguby królów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 4, 'Nie królom, o Lemuelu, nie królom wypada pić wina i nie książętom bawić się mocnym napojem;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 5, 'By pijąc, nie zapomnieli praw i nie wypaczyli sprawy wszystkich ludzi uciśnionych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 6, 'Dajcie mocny napój ginącym, a wino strapionym na duchu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 7, 'Niech się napiją i zapomną o swoim ubóstwie, i niech nie pamiętają więcej swego utrapienia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 8, 'Otwórz swe usta dla niemych w sprawie wszystkich osądzonych na śmierć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 9, 'Otwórz swe usta, sądź sprawiedliwie i broń sprawy ubogiego i nędzarza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 10, 'Któż znajdzie kobietę cnotliwą? Jej wartość przewyższa perły.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 11, 'Serce męża jej ufa i zysku mu nie zabraknie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 12, 'Dobro mu będzie wyświadczać, a nie zło, po wszystkie dni swego życia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 13, 'Szuka wełny i lnu i chętnie pracuje swymi rękami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 14, 'Podobna jest do okrętów handlowych; przywozi żywność z daleka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 15, 'Wstaje, gdy jeszcze jest noc, i daje pokarm swoim domownikom i odpowiednią porcję swym służącym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 16, 'Myśli o polu i kupuje je; z zarobku swych rąk sadzi winnice.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 17, 'Przepasuje swe biodra siłą i umacnia swoje ramiona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 18, 'Dostrzega, że jej dorobek jest dobry, a jej pochodnia w nocy nie gaśnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 19, 'Wyciąga ręce po kądziel, a dłonią chwyta wrzeciono.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 20, 'Otwiera dłoń przed ubogim i wyciąga swe ręce do nędzarza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 21, 'Nie boi się śniegu dla swych domowników, bo wszyscy jej domownicy są ubrani w szkarłat.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 22, 'Robi sobie kobierce; jej ubiór jest z jedwabiu i purpury.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 23, 'Jej mąż jest znany w bramach, gdy siedzi wśród starszyzny ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 24, 'Wyrabia płótno i sprzedaje je, dostarcza pasy kupcowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 25, 'Siła i godność są jej strojem; będzie się cieszyła jeszcze w przyszłości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 26, 'Otwiera swe usta mądrze i na jej języku jest prawo miłosierdzia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 27, 'Dogląda spraw swego domu i nie je chleba próżniactwa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 28, 'Jej dzieci powstają i błogosławią jej, mąż także ją chwali:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 29, 'Wiele kobiet poczynało sobie cnotliwie, ale ty przewyższasz je wszystkie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 30, 'Wdzięk jest zwodniczy i piękność próżna, lecz kobieta, która się boi Pana, jest godna pochwały.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 31, 'Dajcie jej z owocu jej rąk i niech jej czyny chwalą ją w bramach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 1, 'Słowa Kaznodziei, syna Dawida, króla w Jerozolimie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 2, 'Marność nad marnościami – mówi Kaznodzieja – marność nad marnościami. Wszystko jest marnością.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 3, 'Jaki pożytek ma człowiek z całego swego trudu, który podejmuje pod słońcem?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 4, 'Jedno pokolenie przemija, drugie pokolenie przychodzi, lecz ziemia trwa na wieki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 5, 'Słońce wschodzi i słońce zachodzi, i spieszy do swego miejsca, z którego znów wschodzi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 6, 'Wiatr idzie na południe i zawraca na północ, krąży nieustannie i znowu wraca na drogę swego krążenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 7, 'Wszystkie rzeki płyną do morza, lecz morze się nie przepełnia; do miejsca, z którego rzeki płyną, znowu wracają.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 8, 'Wszystkie rzeczy są pełne trudu, a człowiek nie zdoła tego wyrazić. Oko nie nasyci się patrzeniem ani ucho nie napełni się słuchaniem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 9, 'To, co było, jest tym, co będzie; a to, co się stało, jest tym, co się stanie. I nie ma nic nowego pod słońcem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 10, 'Czy jest coś, o czym można by powiedzieć: Patrz, to jest coś nowego? I to już było w dawnych czasach, które były przed nami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 11, 'Nie ma pamięci o dawnych rzeczach; także o tych, które będą, nie będzie pamięci u tych, którzy potem nastaną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 12, 'Ja, Kaznodzieja, byłem królem nad Izraelem w Jerozolimie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 13, 'I przyłożyłem się w swoim sercu do tego, aby mądrością szukać wszystkiego i wybadać wszystko, co się dzieje pod niebem. To uciążliwe zadanie Bóg dał synom ludzkim, aby się nim trudzili.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 14, 'Widziałem wszystkie sprawy, jakie się dzieją pod słońcem, a oto wszystko jest marnością i utrapieniem ducha.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 15, 'Tego, co krzywe, nie da się wyprostować, a tego, czego brak, nie da się policzyć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 16, 'Tak więc pomyślałem w swoim sercu: Oto wzbogaciłem się i dano mi więcej mądrości niż wszystkim, którzy byli przede mną w Jerozolimie. I moje serce doświadczyło wielkiej mądrości i wiedzy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 17, 'I przyłożyłem się w swoim sercu do tego, aby poznać mądrość, a także by poznać szaleństwo i głupotę. Ale poznałem, że i to jest utrapieniem ducha.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 18, 'Gdzie bowiem jest wiele mądrości, tam jest wiele smutku. A kto przysparza wiedzy, przysparza i cierpienia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 1, 'Powiedziałem w sercu: Niech teraz doświadczę cię w radości, zażywaj więc przyjemności. Lecz to także jest marnością.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 2, 'O śmiechu powiedziałem: To szaleństwo, a o radości: Co to daje?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 3, 'Postanowiłem w sercu, że poddam swoje ciało winu – serce jednak kierowałem mądrością – i że będę się trzymać głupoty, aż zobaczę, co dla synów ludzkich jest dobrem spośród tego, co mają czynić pod niebem, przez wszystkie dni ich życia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 4, 'Dokonałem wielkich dzieł, zbudowałem sobie domy, zasadziłem sobie winnice.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 5, 'Założyłem sobie ogrody i sady i posadziłem w nich wszelkiego rodzaju drzewa owocowe.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 6, 'Zbudowałem też sobie stawy na wodę, by nawadniać nią las rosnących drzew.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 7, 'Nabyłem sługi i służące, miałem też sługi urodzone w swoim domu. Posiadałem również stada wołów i trzody owiec większe niż wszyscy, którzy byli przede mną w Jerozolimie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 8, 'Zgromadziłem sobie srebro i złoto, i klejnoty królów i prowincji. Przygotowałem sobie śpiewaków i śpiewaczki, i inne rozkosze synów ludzkich oraz liczne instrumenty muzyczne.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 9, 'I tak stałem się większy i możniejszy niż wszyscy, którzy byli przede mną w Jerozolimie. W dodatku moja mądrość pozostała przy mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 10, 'Nie wzbraniałem swoim oczom niczego, czego pragnęły, nie odmawiałem swemu sercu żadnej uciechy; moje serce bowiem radowało się z całego mojego trudu. A to był mój dział za cały mój trud.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 11, 'Następnie przyjrzałem się wszystkim dziełom, jakich dokonały moje ręce, i trudowi, jaki podjąłem dla ich wykonania, a oto wszystko to marność i utrapienie ducha i nie ma żadnego pożytku pod słońcem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 12, 'Odwróciłem się więc, aby przyjrzeć się mądrości, szaleństwu i głupocie. Co bowiem może uczynić człowiek, który nastąpi po królu? To, co czynili już inni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 13, 'I zobaczyłem, że mądrość jest pożyteczniejsza od głupoty, tak jak światło jest pożyteczniejsze od ciemności.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 14, 'Mądry ma oczy w swojej głowie, głupi zaś chodzi w ciemności. A poznałem, że ten sam los spotyka wszystkich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 15, 'Dlatego powiedziałem w sercu: Los, który spotyka głupiego, spotka również mnie. Po co więc przewyższyłem go mądrością? Wtedy powiedziałem w sercu, że to także jest marnością.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 16, 'Nie ma bowiem pamięci zarówno o mądrym, jak i o głupcu na wieki, gdyż to, co jest teraz, w najbliższych dniach pójdzie w niepamięć. A jak umiera mądry? Tak jak głupi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 17, 'Dlatego obrzydło mi życie, gdyż przykre mi są wszystkie sprawy dokonane pod słońcem. Wszystko bowiem jest marnością i utrapieniem ducha.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 18, 'Zbrzydł mi nawet cały mój trud, który podejmowałem pod słońcem, gdyż muszę go zostawić człowiekowi, który przyjdzie po mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 19, 'A kto wie, czy będzie mądry, czy głupi? A jednak będzie władać całą moją pracą, w którą włożyłem swój trud i mądrość pod słońcem. Także i to jest marnością.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 20, 'Doszedłem więc do tego, że zwątpiłem w sercu w cały swój trud, jaki podjąłem pod słońcem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 21, 'Gdyż niejeden człowiek pracuje mądrze, umiejętnie i sprawiedliwie, a swój dział pozostawia innemu, który się nim nie trudził. Także i to jest marnością i wielkim złem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 22, 'Cóż bowiem ma człowiek z całej swojej pracy i z utrapienia swego serca, którymi się trudzi pod słońcem?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 23, 'Bo wszystkie jego dni są cierpieniem, a jego zajęcie – smutkiem; nawet w nocy jego serce nie zaznaje spokoju. Także i to jest marnością.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 24, 'Nie ma nic lepszego dla człowieka, niż aby jadł i pił, i czynił dobrze swojej duszy przy swojej pracy. Zobaczyłem też, że pochodzi to z ręki Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 25, 'Kto bowiem potrafi jeść i cieszyć się tym słuszniej niż ja?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 26, 'Bo człowiekowi, który mu się podoba, daje mądrość, wiedzę i radość. Ale grzesznikowi zadaje trud, aby zbierał i gromadził, i potem zostawił to temu, który się Bogu podoba. Także i to jest marnością i utrapieniem ducha.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 1, 'Jest pora na wszystko i czas na każdą sprawę pod niebem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 2, 'Jest czas rodzenia i czas umierania, czas sadzenia i czas wyrywania tego, co zasadzono;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 3, 'Czas zabijania i czas leczenia, czas burzenia i czas budowania;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 4, 'Czas płaczu i czas śmiechu, czas smutku i czas pląsów;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 5, 'Czas rzucania kamieni i czas zbierania kamieni, czas uścisków i czas powstrzymywania się od uścisków;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 6, 'Czas szukania i czas tracenia, czas zachowania i czas wyrzucania;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 7, 'Czas rozdzierania i czas zszywania, czas milczenia i czas mówienia;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 8, 'Czas miłowania i czas nienawiści, czas wojny i czas pokoju.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 9, 'Jaki pożytek ma ten, kto pracuje, z całego swego trudu?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 10, 'Widziałem pracę, którą Bóg dał synom ludzkim, aby się nią trudzili.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 11, 'Wszystko dobrze uczynił w swoim czasie. Włożył także świat w ich serca, mimo że człowiek nie zdoła pojąć dzieła, którego Bóg dokonuje od początku do końca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 12, 'Dlatego wiem, że dla nich nie ma nic lepszego nad to, by się radowali i czynili dobrze za swego życia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 13, 'Również i to, gdy każdy człowiek je i pije, i cieszy się dobrem całego swego trudu, jest darem Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 14, 'Wiem i to, że cokolwiek czyni Bóg, będzie trwać na wieki. Nie można do tego nic dodać ani z tego odjąć, a Bóg czyni to, aby ludzie się go bali.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 15, 'To, co było, jest teraz, a to, co będzie, już było. Bóg bowiem żąda tego, co przeminęło.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 16, 'Widziałem jeszcze pod słońcem niegodziwość w miejscu sądu, a w miejscu sprawiedliwości – nieprawość.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 17, 'I powiedziałem w sercu: Bóg osądzi zarówno sprawiedliwego, jak i niegodziwego, gdyż tam będzie czas na osądzenie każdego zamiaru i uczynku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 18, 'Powiedziałem w sercu o sprawie synów ludzkich: Oby Bóg im pokazał, aby wiedzieli, że są tylko zwierzętami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 19, 'Bo jednakowy jest los synów ludzkich i los zwierząt. Jak umiera ten, tak umiera i tamto. Wszyscy mają jednakowe tchnienie, a nie ma człowiek przewagi nad zwierzęciem, gdyż wszystko jest marnością.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 20, 'Wszystko to idzie do jednego miejsca; wszystko jest z prochu i wszystko w proch się obraca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 21, 'A któż wie, że duch synów ludzkich idzie w górę, a duch zwierzęcia zstępuje do ziemi?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 22, 'Dlatego zobaczyłem, że nie ma nic lepszego nad to, żeby człowiek się radował ze swoich dzieł, gdyż to jest jego dział. Któż bowiem doprowadzi go do tego, aby poznał to, co ma być po nim?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 1, 'Potem zwróciłem się w stronę wszystkich ucisków, jakie zdarzają się pod słońcem, i przyjrzałem się im. I oto widziałem łzy uciśnionych, a nie mieli pocieszyciela. Siła była w rękach ciemięzców, a tamci nie mieli pocieszyciela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 2, 'Dlatego chwaliłem umarłych, którzy już odeszli, bardziej niż żywych, którzy jeszcze żyją.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 3, 'Nawet lepszy od nich obu jest ten, którego jeszcze nie było i który nie widział zła, jakie się dzieje pod słońcem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 4, 'Zobaczyłem też, że wszelka praca i każde dobre dzieło wywołują tylko zazdrość jednego wobec drugiego. Także i to jest marnością i utrapieniem ducha.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 5, 'Głupi składa swoje ręce i zjada własne ciało.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 6, 'Lepsza jest pełna garść z pokojem niż obie pełne garści z trudem i utrapieniem ducha.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 7, 'Znowu obróciłem się i zobaczyłem kolejną marność pod słońcem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 8, 'Jest to człowiek samotny, bez towarzysza, nie ma ani syna, ani brata i nie ma końca wszelki jego trud, a jego oczy nie mogą nasycić się bogactwem. Nie myśli: Dla kogo ja pracuję i odmawiam dobra swojej duszy? Także i to jest marnością i ciężką udręką.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 9, 'Lepiej jest dwom niż jednemu, gdyż mają dobry pożytek ze swojej pracy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 10, 'Jeśli bowiem jeden upadnie, drugi podniesie swego towarzysza. Lecz biada samotnemu, gdy upadnie, bo nie ma drugiego, który by go podniósł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 11, 'Także jeśli dwoje ludzi śpi razem, grzeją się wzajemnie. Ale jeden jakże się ogrzeje?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 12, 'A jeśli kto przemaga jednego, to dwaj stawią mu czoła, a potrójny sznur nie rozerwie się tak łatwo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 13, 'Lepszy jest chłopiec ubogi i mądry niż król stary i głupi, który nie potrafi już przyjmować napomnienia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 14, 'Bo tamten wychodzi z więzienia, aby królować, a ten urodzony w swoim królestwie zubożeje.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 15, 'Widziałem, jak wszyscy żyjący, którzy chodzą pod słońcem, przestawali z chłopcem, potomkiem, który miał wstąpić na miejsce tamtego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 16, 'Niezliczony jest cały lud, jaki żył przed nimi. Lecz następni nie będą się z niego cieszyć. A tak i to jest marność i utrapienie ducha.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 1, 'Pilnuj swoich kroków, gdy idziesz do domu Bożego, i bądź skłonny raczej ku temu, aby słuchać, niż dawać ofiarę głupich. Nie wiedzą oni bowiem, że źle czynią.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 2, 'Nie mów pochopnie i niech twoje serce nie wypowiada pospiesznie słów przed Bogiem. Bóg bowiem jest w niebie, a ty na ziemi. Niech więc niewiele będzie twoich słów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 3, 'Bo z wielu zajęć przychodzi sen, a mowa głupca z wielu słów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 4, 'Gdy złożysz Bogu jakiś ślub, nie zwlekaj z jego wypełnieniem, gdyż w głupcach nie ma on upodobania. Cokolwiek ślubujesz, wypełnij.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 5, 'Lepiej jest nie ślubować, niż ślubować i tego nie wypełnić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 6, 'Nie pozwól, by twoje usta przywiodły do grzechu twoje ciało i nie mów przed aniołem, że to był błąd. Dlaczego Bóg miałby się gniewać na twoje słowa i obrócić wniwecz dzieło twoich rąk?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 7, 'Gdzie bowiem jest wiele snów, tam też wiele słów i marności. Ale ty bój się Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 8, 'Jeśli widzisz w prowincji ucisk ubogiego i wypaczanie sądu i sprawiedliwości, nie dziw się temu, gdyż ten, który jest wyższy od najwyższych, czuwa, a są wyżsi od nich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 9, 'Korzyści z ziemi służą wszystkim. Nawet królowi służy pole.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 10, 'Kto kocha pieniądze, nie nasyci się pieniędzmi, a kto kocha bogactwa, nie będzie miał z nich pożytku. Także i to jest marnością.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 11, 'Gdy dobra się mnożą, mnożą się też ci, którzy je zjadają. Cóż więc za pożytek ma z tego właściciel? Jedynie to, że patrzy na nie swoimi oczami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 12, 'Słodki jest sen robotnika, czy je mało, czy dużo, ale obfitość bogatego nie daje mu spać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 13, 'Jest ciężka bieda, którą widziałem pod słońcem: bogactwo przechowywane dla właściciela na jego własną szkodę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 14, 'Takie bogactwo bowiem przepada przez złe zajęcia. A syn, którego spłodzi, nie będzie miał nic w swoich rękach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 15, 'Jak wyszedł z łona swojej matki, tak też nagi wróci, jak przyszedł, i nie zabierze nic ze swojej pracy, co mógłby wziąć do ręki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 16, 'Także i to jest ciężką niedolą, że jak przyszedł, tak odejdzie. Cóż więc za pożytek, że trudził się na wiatr?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 17, 'Po wszystkie swoje dni jadał w ciemności, smutku, chorobie i gniewie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 18, 'Oto co zobaczyłem: rzecz dobra i piękna to jeść i pić, i cieszyć się dobrem ze wszelkiego swego trudu, który człowiek podejmuje pod słońcem po wszystkie dni swego życia, jakie dał mu Bóg. To bowiem jest jego działem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 19, 'Dla każdego też człowieka, któremu Bóg dał majątek i bogactwo, i dał mu możliwość, by z nich korzystał i odbierał swój dział i radował się ze swojego trudu – to jest dar Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 20, 'Nie będzie bowiem wiele pamiętał o dniach swego życia, gdyż Bóg go wysłuchuje, napełniając jego serce radością.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 1, 'Jest zło, które widziałem pod słońcem i które jest powszechne wśród ludzi:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 2, 'Gdy jakiemuś człowiekowi Bóg dał bogactwo, majątek i sławę, tak że nie brakuje jego duszy nic z tego, czegokolwiek by pragnął, jednak Bóg nie daje mu możliwości spożywać tego, ale spożywa to obcy człowiek. Jest to marnością i ciężką niedolą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 3, 'Choćby ktoś spłodził stu synów, żył wiele lat i dni jego lat się przedłużyły, a jego dusza nie była nasycona dobrem i nie miał nawet pogrzebu, powiadam: lepszy jest od niego martwy płód.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 4, 'Ten bowiem przychodzi w marności i odchodzi w ciemności, a jego imię zostaje okryte ciemnością.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 5, 'Nie widział nawet słońca i nic nie wie. Ma on większy spokój niż tamten.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 6, 'Bo choćby nawet żył przez dwa tysiące lat, nie zaznałby żadnego dobra. Czy wszyscy nie idą do jednego miejsca?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 7, 'Wszelki trud człowieka jest dla jego ust, a jednak jego dusza nie może się nasycić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 8, 'Czego więcej ma bowiem mądry od głupca? Albo czego więcej ma ubogi, który umie postępować wśród żyjących?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 9, 'Lepsze jest to, co oczy widzą, niż ciągłe pragnienie. To również jest marnością i utrapieniem ducha.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 10, 'Temu, kto jest, już nadano imię i wiadomo, że jest człowiekiem i że nie może się on spierać z mocniejszym od siebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 11, 'Ponieważ wiele jest rzeczy, które pomnażają marność, jaką z nich korzyść ma człowiek?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 12, 'Któż bowiem wie, co jest dobre dla człowieka w tym życiu po wszystkie dni jego marnego życia, które jak cień przemijają? Albo kto oznajmi człowiekowi, co po nim będzie pod słońcem?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 1, 'Lepsze jest dobre imię niż wyborny olejek, a dzień śmierci niż dzień urodzenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 2, 'Lepiej iść do domu żałoby niż do domu wesela, gdyż w tamtym widzimy koniec każdego człowieka, a człowiek żyjący weźmie to sobie do serca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 3, 'Lepszy jest smutek niż śmiech, bo przez smutek twarzy serce szlachetnieje.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 4, 'Serce mądrych jest w domu żałoby, ale serce głupich w domu wesela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 5, 'Lepiej jest słuchać upomnień mądrego niż pieśni głupców.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 6, 'Czym bowiem jest trzaskanie cierni pod kotłem, tym jest śmiech głupca. Także i to jest marnością.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 7, 'Doprawdy, ucisk doprowadza mądrego do szaleństwa, a dar psuje serce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 8, 'Lepsze jest dokończenie sprawy niż jej początek. Lepszy jest człowiek cierpliwego ducha niż człowiek wyniosłego ducha.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 9, 'Nie bądź w duchu skory do gniewu, gdyż gniew spoczywa w piersi głupich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 10, 'Nie mów: Jak to jest, że dawne dni były lepsze niż te obecne? Bo niemądrze byś o to pytał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 11, 'Dobra jest mądrość przy dziedzictwie i jest pożyteczna dla tych, którzy widzą słońce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 12, 'Mądrość bowiem jest osłoną, osłoną są też pieniądze; lecz korzyść z poznania jest taka: mądrość daje życie tym, którzy ją mają.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 13, 'Przypatrz się dziełu Boga. Kto bowiem może wyprostować to, co on krzywym uczynił?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 14, 'W dniu powodzenia raduj się, a w dniu nieszczęścia rozważaj: Bóg uczynił zarówno jedno, jak i drugie po to, aby człowiek nie dociekł tego, co po nim nastanie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 15, 'Wszystko widziałem za swych marnych dni: niejeden sprawiedliwy ginie w swojej sprawiedliwości, a niejeden niegodziwiec żyje długo w swojej niegodziwości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 16, 'Nie bądź przesadnie sprawiedliwy ani przesadnie mądry. Czemu miałbyś się sam do zguby prowadzić?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 17, 'Nie bądź zbyt niegodziwy i nie bądź głupi. Czemu miałbyś umrzeć przed swoim czasem?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 18, 'Dobrze będzie, jeśli będziesz się tego trzymał, ale i tamtego z rąk nie wypuszczaj. Kto bowiem boi się Boga, uniknie tego wszystkiego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 19, 'Mądrość daje mądremu więcej siły, niż posiada ją dziesięciu mocarzy, którzy są w mieście.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 20, 'Doprawdy, nie ma człowieka sprawiedliwego na ziemi, który czyniłby dobrze i nie grzeszył.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 21, 'Nie zwracaj też uwagi na wszystkie słowa, które wypowiadają ludzie, byś nie usłyszał, jak ci złorzeczy twój sługa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 22, 'Wie bowiem twoje serce, że i ty wielokroć złorzeczyłeś innym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 23, 'Tego wszystkiego doświadczyłem mądrością i powiedziałem: Będę mądry. Ale mądrość oddaliła się ode mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 24, 'To, co jest dalekie, i to, co jest bardzo głębokie – któż to może zgłębić?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 25, 'Zwróciłem swoje serce ku poznaniu, badaniu i szukaniu mądrości oraz rozeznaniu rzeczy, by poznać niegodziwość głupstwa, głupoty i szaleństwa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 26, 'I odkryłem, że bardziej gorzka niż śmierć jest kobieta, której serce jest jak sieć i sidło, a jej ręce jak pęta. Kto się Bogu podoba, uwolni się od niej, ale grzesznik będzie przez nią usidlony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 27, 'Oto co odkryłem – mówi Kaznodzieja – badając jedną po drugiej, aby dojść do istoty rzeczy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 28, 'Czego jeszcze szuka moja dusza, lecz nie znajduje: Jednego mężczyznę spośród tysiąca znalazłem, ale kobiety spośród wszystkich nie znalazłem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 29, 'Oto to tylko odkryłem: Bóg stworzył człowieka prawego, ale oni szukali rozlicznych wymysłów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 1, 'Kto jest mądrym człowiekiem? Kto zna wyjaśnienie rzeczy? Mądrość człowieka rozjaśnia jego oblicze i odmienia srogość jego twarzy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 2, 'Radzę ci, abyś przestrzegał rozkazu króla, a to ze względu na przysięgę Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 3, 'Nie spiesz się z odejściem sprzed jego oblicza ani nie upieraj się przy złej sprawie. Czyni bowiem wszystko tak, jak mu się podoba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 4, 'Gdzie słowo króla, tam i jego moc. Któż mu powie: Co czynisz?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 5, 'Kto przestrzega przykazania, nie zazna niczego złego. A serce mądrego zna czas i sąd.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 6, 'Na każdą sprawę jest czas i sąd, dlatego wielkie nieszczęście trzyma się człowieka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 7, 'Nie wie bowiem, co będzie. Kto mu oznajmi, kiedy co się przydarzy?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 8, 'Nie ma człowieka, który miałby władzę nad duchem, żeby powstrzymać ducha, ani moc nad dniem śmierci. Nie ma też zwolnienia z tego boju, a niegodziwych nie wybawi ich niegodziwość.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 9, 'To wszystko widziałem, gdy zwróciłem swoje serce do każdego dzieła, którego się dokonuje pod słońcem. Bywa czas, kiedy jeden człowiek panuje nad drugim ku jego krzywdzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 10, 'Widziałem więc niegodziwych pogrzebanych, którzy przychodzili do miejsca świętego i odchodzili z niego, a zapomniano o nich w mieście, gdzie tak czynili. I to również jest marnością.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 11, 'Ponieważ wyroku za zły czyn nie wykonuje się od razu, serce synów ludzkich jest w nich zawzięte i gotowe na to, aby popełniali zło.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 12, 'I chociaż grzesznik po stokroć czyni zło i jego dni się przedłużą, to jednak wiem, że szczęści się tym, którzy boją się Boga, którzy się boją jego oblicza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 13, 'Ale niegodziwemu nie szczęści się i nie przedłuży on swoich dni, przeminą bowiem jak cień, ponieważ nie boi się Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 14, 'Jest też marność, która się dzieje na ziemi: są ludzie sprawiedliwi, którym się zdarza to, na co zasługują uczynki niegodziwych; są też ludzie niegodziwi, którym się zdarza to, na co zasługują uczynki sprawiedliwych. Powiedziałem, że i to jest marnością.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 15, 'Chwaliłem więc radość, gdyż nie ma dla człowieka nic lepszego pod słońcem nad to, by jadł, pił i radował się. To bowiem zostanie mu z jego trudu po wszystkie dni jego życia, które pod słońcem dał mu Bóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 16, 'Gdy zwróciłem swoje serce na to, aby poznać mądrość i rozważać sprawy, jakie się dzieją na ziemi, z powodu których oczy człowieka nie zaznają snu ani we dnie, ani w nocy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 17, 'Wówczas zobaczyłem całe dzieło Boga – to, że człowiek nie potrafi zgłębić sprawy, która się dzieje pod słońcem. Choćby człowiek starał się do tego dojść, nie zgłębi tego; choćby nawet mądry zamierzył to poznać, nie zdoła tego zgłębić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 1, 'Zaprawdę, wszystko to rozważałem w swoim sercu po to, aby to wszystko wyjaśnić – że sprawiedliwi i mądrzy oraz ich dzieła są w rękach Boga. Człowiek nie zna ani miłości, ani nienawiści ze wszystkich rzeczy, które są przed nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 2, 'Wszystkich spotyka to samo: ten sam los spotyka sprawiedliwego i niegodziwego, dobrego i czystego, i nieczystego, składającego ofiary i tego, który nie składa ofiar, zarówno dobrego, jak i grzesznika, przysięgającego i tego, kto boi się przysięgi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 3, 'Jest takie zło we wszystkim, co się dzieje pod słońcem: jeden los spotyka wszystkich. A przy tym serce synów ludzkich jest pełne zła, a głupota znajduje się w ich sercach, póki żyją, a potem idą do zmarłych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 4, 'Ktokolwiek bowiem jest złączony ze wszystkimi żyjącymi, ma nadzieję, gdyż lepszy jest żywy pies niż zdechły lew.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 5, 'Żyjący bowiem wiedzą, że umrą, ale umarli o niczym nie wiedzą i nie mają już żadnej zapłaty, gdyż pamięć o nich uległa zapomnieniu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 6, 'Tak samo ich miłość, nienawiść i zazdrość już zginęły. I już nigdy więcej nie będą mieć działu we wszystkim, co się dzieje pod słońcem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 7, 'Idź więc, jedz z radością swój chleb i pij z wesołym sercem swe wino, gdyż Bóg już przyjął twoje dzieła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 8, 'Niech twoje szaty będą zawsze białe i niech nie zabraknie olejku na twoją głowę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 9, 'Ciesz się życiem z żoną, którą ukochałeś po wszystkie dni swego marnego życia, jakie dał ci Bóg pod słońcem, po wszystkie dni swojej marności. To jest bowiem twój dział w życiu i w trudzie, który podejmujesz pod słońcem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 10, 'Wszystko, cokolwiek twoja ręka postanowi czynić, czyń z całej swojej siły; nie ma bowiem żadnej pracy ani zamysłu, ani wiedzy, ani mądrości w grobie, do którego zmierzasz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 11, 'Potem obróciłem się i widziałem pod słońcem, że bieg nie należy do szybkich ani wojna do dzielnych, ani żywność do mądrych, ani bogactwo do roztropnych, ani łaska do zdolnych, lecz czas i przypadek spotyka wszystkich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 12, 'Człowiek bowiem nie zna swojego czasu, ale jak ryby, które się łowi szkodliwą siecią, i jak ptaki chwytane w sidła, tak synowie ludzcy są uwikłani w złej chwili, gdy ta nagle na nich spadnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 13, 'Widziałem również tę mądrość pod słońcem, która wydała mi się wielka:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 14, 'Było małe miasto, a w nim niewielu ludzi. I wyruszył przeciw niemu potężny król, obległ je i zbudował przeciwko niemu wielkie wały.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 15, 'I znalazł się w nim człowiek ubogi i mądry, który wybawił to miasto przez swoją mądrość. Nikt jednak nie pamiętał tego ubogiego człowieka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 16, 'I powiedziałem: Lepsza jest mądrość niż siła. Lecz mądrość ubogiego bywa wzgardzona i jego słów nikt nie słucha.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 17, 'Spokojnych słów ludzi mądrych należy słuchać bardziej niż krzyku tego, który panuje wśród głupców.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 18, 'Lepsza jest mądrość niż oręż wojenny, ale jeden grzesznik niszczy wiele dobrego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 1, 'Zdechłe muchy zasmradzają i psują olejek aptekarza. Tak samo odrobina głupstwa psuje człowieka poważanego z powodu jego mądrości i sławy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 2, 'Serce mądrego jest po jego prawicy, ale serce głupca po jego lewicy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 3, 'Nawet gdy głupiec idzie drogą, brakuje mu rozumu, i mówi wszystkim, że jest głupcem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 4, 'Jeśli duch władcy powstaje przeciwko tobie, nie opuszczaj swego miejsca, gdyż pokora zapobiega wielkim wykroczeniom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 5, 'Jest zło, które widziałem pod słońcem, to błąd, który pochodzi od władcy:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 6, 'Głupota jest wywyższona do wielkiej godności, a bogaci w mądrość siedzą nisko.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 7, 'Widziałem sługi na koniach, a książąt idących pieszo jak słudzy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 8, 'Kto kopie dół, sam w niego wpadnie, kto rozwala płot, tego ukąsi wąż.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 9, 'Kto przenosi kamienie, porani się nimi, kto rąbie drwa, naraża się na niebezpieczeństwo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 10, 'Jeśli stępi się żelazo, a nie naostrzy się jego ostrza, wtedy trzeba wytężyć siły. Ale lepiej skutkuje mądrość.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 11, 'Wąż ukąsi bez zaklęcia, a gaduła nie jest niczym lepszym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 12, 'Słowa z ust mądrego są łaskawe, ale wargi głupca pożerają jego samego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 13, 'Początek słów jego ust to głupota, a koniec jego mowy to wielkie szaleństwo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 14, 'Głupiec wiele mówi, choć człowiek nie wie, co nastąpi. Któż mu oznajmi, co po nim nastanie?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 15, 'Głupi męczą się trudem, a nie wiedzą nawet, jak dojść do miasta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 16, 'Biada tobie, ziemio, gdy twoim królem dziecko, a twoi książęta z rana biesiadują.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 17, 'Błogosławiona jesteś, ziemio, gdy twój król pochodzi ze szlachetnego rodu, a twoi książęta we właściwym czasie jadają, by się posilić, a nie dla pijaństwa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 18, 'Z powodu lenistwa chyli się dach, a wskutek opieszałości rąk przecieka dom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 19, 'Dla uciechy wyprawia się ucztę i wino rozwesela życie, ale pieniądze umożliwiają wszystko.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 20, 'Nawet w swoich myślach nie złorzecz królowi ani w swojej sypialni nie przeklinaj bogatego, bo ptak niebieski zaniesie ten głos, a to, co skrzydlate, rozgłosi sprawę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 1, 'Rzucaj swój chleb na wody, bo po wielu dniach odnajdziesz go.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 2, 'Rozdaj dział siedmiu lub ośmiu, bo nie wiesz, co złego wydarzy się na ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 3, 'Gdy chmury napełniają się deszczem, spuszczają go na ziemię. Gdy drzewo upada na południe lub na północ, w miejscu, gdzie upadnie to drzewo, tam zostanie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 4, 'Kto zważa na wiatr, nigdy nie będzie siał, a kto patrzy na chmury, nie będzie żąć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 5, 'Jak nie wiesz, jaka jest droga ducha, i jak się kształtują kości w łonie brzemiennej, tak nie znasz spraw Boga, który wszystko czyni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 6, 'Rano siej swoje ziarno, a wieczorem nie pozwól spocząć swojej ręce, gdyż nie wiesz, co się uda, czy to, czy tamto, czy też oboje będą równie dobre.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 7, 'Doprawdy, światło jest słodkie i miła to rzecz dla oczu widzieć słońce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 8, 'A choćby człowiek żył przez wiele lat i radował się nimi wszystkimi, to niech pamięta o dniach ciemności, bo będzie ich wiele. Wszystko, co nastąpi, to tylko marność.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 9, 'Dlatego raduj się, młodzieńcze, w swojej młodości, niech twoje serce cieszy cię za dni twojej młodości i krocz drogami swego serca oraz według zdania swoich oczu, ale wiedz, że za to wszystko Bóg przyprowadzi cię na sąd.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 10, 'Usuń więc gniew ze swojego serca i odrzuć zło od swego ciała, gdyż dzieciństwo i młodość są marnością.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 1, 'Pamiętaj więc o swoim Stwórcy w dniach swojej młodości, zanim nastaną złe dni i przyjdą lata, o których powiesz: Nie podobają mi się.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 2, 'Zanim zaćmią się słońce, światło, księżyc i gwiazdy, a chmury powrócą po deszczu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 3, 'W dzień, w którym trząść się będą stróże domu i pochylą się silni mężczyźni, ustaną mielący, gdyż będzie ich mało, i zaćmią się patrzące przez okna;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 4, 'I zamkną się drzwi na ulicę, gdy odgłos mielenia osłabnie, gdy będzie się wstawać na głos ptaków i przycichną wszystkie córki śpiewające.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 5, 'Gdy też będą się bać wysokich miejsc i lękać na drodze, gdy zakwitnie drzewo migdałowe i szarańcza będzie ciężka i pragnienie ustanie, bo człowiek idzie do swego wiecznego domu, a płaczący będą chodzić po ulicach;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 6, 'Zanim się zerwie srebrny sznur i stłucze złota czasza, nim rozbije się dzban u źródła i złamie się koło przy studni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 7, 'Wtedy proch powróci do ziemi, jak nią był, a duch powróci do Boga, który go dał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 8, 'Marność nad marnościami – mówi Kaznodzieja – wszystko to marność.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 9, 'A poza tym, że Kaznodzieja był mądry, uczył lud wiedzy; rozważał, badał i ułożył wiele przysłów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 10, 'Kaznodzieja starał się znaleźć słowa przyjemne i napisał to, co jest dobre – słowa prawdy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 11, 'Słowa mądrych są jak ościenie i jak gwoździe wbite przez tych, którzy je złożyli, i pochodzą od jednego pasterza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 12, 'Ponadto, mój synu, przyjmij przestrogę z tych słów: Pisaniu wielu ksiąg nie ma końca, a wiele nauki męczy ciało.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 13, 'Wysłuchaj podsumowania wszystkiego: Bój się Boga i przestrzegaj jego przykazań. Ponieważ to jest cały obowiązek człowieka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 14, 'Bóg przywiedzie bowiem każdy uczynek na sąd, nawet każdą rzecz utajoną, czy dobrą, czy złą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 1, 'Pieśń nad pieśniami Salomona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 2, 'Niech mnie pocałuje pocałunkami swoich ust. Twoja miłość bowiem jest lepsza od wina.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 3, 'Z powodu wonności twoich olejków twoje imię jest jak rozlany olejek; dlatego miłują cię dziewice.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 4, 'Pociągnij mnie, a pobiegniemy za tobą. Król wprowadził mnie do swoich komnat. Będziemy się cieszyć i radować tobą, będziemy pamiętać o twojej miłości bardziej niż o winie. Miłują cię prawi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 5, 'Czarna jestem, ale piękna, o córki Jerozolimy, jak namioty Kedaru, jak zasłony Salomona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 6, 'Nie patrzcie na mnie, że jestem czarna, gdyż słońce mnie opaliło. Synowie mojej matki rozgniewali się na mnie, postawili mnie na straży winnic; a mojej własnej winnicy nie ustrzegłam.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 7, 'Powiedz mi ty, którego miłuje moja dusza, gdzie wypasasz, gdzie dajesz swojej trzodzie odpocząć w południe. Czemu bowiem mam być jak błądząca przy trzodach twoich towarzyszy?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 8, 'Jeśli nie wiesz, najpiękniejsza wśród kobiet, to idź śladem trzody i paś swoje koźlątka przy szałasach pasterzy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 9, 'Przyrównam cię, moja umiłowana, do zaprzęgu rydwanów faraona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 10, 'Twoje lica są piękne, ozdobione klejnotami, a twoja szyja – łańcuchami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 11, 'Uczynimy ci złote klejnoty nakrapiane srebrem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 12, 'Dopóki król jest przy swoim stole, mój nard rozsiewa swoją woń.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 13, 'Jak wiązka mirry jest dla mnie mój miły, spoczywa na moich piersiach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 14, 'Mój miły jest dla mnie jak grono cyprysu pośród winnic w En-Gedi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 15, 'O jaka ty jesteś piękna, moja umiłowana! O jaka ty jesteś piękna! Twoje oczy są jak oczy gołębicy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 16, 'O jaki ty jesteś piękny, mój umiłowany, i jak miły! Łoże nasze się zieleni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 17, 'Belki naszego domu są cedrowe, a nasze stropy – cyprysowe.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 1, 'Jestem różą Saronu i lilią dolin.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 2, 'Jak lilia między cierniami, tak moja umiłowana między pannami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 3, 'Jak jabłoń między leśnymi drzewami, tak mój miły między młodzieńcami. Z wielkim pragnieniem usiadłam w jego cieniu, a jego owoc jest słodki memu podniebieniu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 4, 'Wprowadził mnie do komnaty biesiadnej, a jego chorągwią nade mną jest miłość.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 5, 'Pokrzepcie mnie bukłakami, posilcie mnie jabłkami, bo jestem chora z miłości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 6, 'Jego lewa ręka pod moją głową, a jego prawa ręka mnie obejmuje.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 7, 'Zaklinam was, córki Jerozolimy, na sarny i łanie polne: Nie budźcie mego umiłowanego i nie przerywajcie jego snu, dopóki nie zechce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 8, 'Głos mego umiłowanego! Oto idzie, skacząc po górach, a podskakując po pagórkach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 9, 'Mój umiłowany podobny jest do sarny albo młodego jelenia. Oto stoi za naszym murem, zagląda przez okna, patrzy przez kraty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 10, 'Mój umiłowany odezwał się i powiedział mi: Wstań, moja umiłowana, moja piękna, i chodź!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 11, 'Oto bowiem minęła zima, deszcz ustał i przeszedł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 12, 'Kwiatki pokazały się na ziemi, nadszedł czas śpiewania i głos synogarlicy słychać w naszej ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 13, 'Drzewo figowe już wypuściło swoje niedojrzałe figi, a kwitnąca winorośl wydaje swoją woń. Wstań, moja umiłowana, moja piękna, i chodź!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 14, 'Moja gołębico, mieszkająca w skalnych szczelinach, w stromych kryjówkach, ukaż mi swoją twarz, daj mi usłyszeć swój głos, gdyż twój głos jest słodki i twoja twarz piękna.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 15, 'Schwytajcie nam lisy, małe lisy, które psują winnice, ponieważ nasze winnice kwitną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 16, 'Mój umiłowany jest mój, a ja jestem jego. Pasie on wśród lilii.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 17, 'Nim zaświta dzień i znikną cienie, zawróć, mój umiłowany, bądź jak sarna albo młode jelenie na górach Beter.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 1, 'Na swoim łożu wśród nocy szukałam tego, którego miłuje moja dusza. Szukałam go, ale go nie znalazłam.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 2, 'Wstanę więc już i obiegnę miasto, po ulicach i placach będę szukać tego, którego miłuje moja dusza. Szukałam go, ale nie znalazłam.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 3, 'Znaleźli mnie strażnicy, którzy obchodzili miasto, i spytałam: Widzieliście tego, którego miłuje moja dusza?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 4, 'A gdy ledwie od nich odeszłam, zaraz znalazłam tego, którego miłuje moja dusza. Uchwyciłam go i nie puszczę, aż go wprowadzę do domu mojej matki, do pokoju mojej rodzicielki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 5, 'Zaklinam was, córki Jerozolimy, na sarny i łanie polne: Nie budźcie mego umiłowanego i nie przerywajcie jego snu, dopóki nie zechce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 6, 'Kim jest ta, która wyłania się z pustyni jak słupy dymu, owiana wonią mirry i kadzidła oraz wszelkim wonnym proszkiem od kupca?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 7, 'Oto łoże Salomona, dokoła którego stoi sześćdziesięciu dzielnych wojowników spośród dzielnych Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 8, 'Wszyscy trzymają miecz, wyćwiczeni w boju. Każdy z nich ma swój miecz u boku przez wzgląd na strach nocny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 9, 'Król Salomon uczynił sobie lektykę z drzewa Libanu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 10, 'Jej słupki uczynił ze srebra, jej pokład ze złota, podniebienie z purpury, a wnętrze wyścielone miłością córek Jerozolimy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 11, 'Wyjdźcie, córki Syjonu, i popatrzcie na króla Salomona w koronie, którą ukoronowała go jego matka w dniu jego zaręczyn i w dniu radości jego serca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 1, 'O jaka ty jesteś piękna, moja umiłowana! O jaka ty jesteś piękna! Twoje oczy między twymi kędziorkami są jak oczy gołębicy; twoje włosy są jak stado kóz, które widać na górze Gileadu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 2, 'Twoje zęby są jak stado strzyżonych owiec, gdy wychodzą z kąpieli; wszystkie mają bliźnięta i nie ma żadnej niepłodnej wśród nich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 3, 'Twoje wargi są jak nić purpurowa, a twoja wymowa pełna wdzięku. Twoje skronie są jak połówki granatu między twymi kędziorkami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 4, 'Twoja szyja jest jak wieża Dawida, zbudowana na zbrojownię, na której tysiąc puklerzy zawieszono, wszystko to tarcze dzielnych wojowników.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 5, 'Twoje piersi są jak dwoje bliźniaczych sarniąt, które pasą się między liliami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 6, 'Nim zaświta dzień i znikną cienie, wejdę na górę mirry i na pagórek kadzidła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 7, 'Cała jesteś piękna, moja umiłowana, i nie ma w tobie żadnej skazy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 8, 'Przyjdź ze mną z Libanu, moja oblubienico, przyjdź ze mną z Libanu. Spójrz ze szczytu góry Amana, ze szczytu góry Senir i Hermon, z jaskiń lwów i z gór lampartów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 9, 'Zachwyciłaś moje serce, moja siostro, moja oblubienico! Zachwyciłaś moje serce jednym twoim okiem i jednym łańcuszkiem na twojej szyi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 10, 'Jakże piękna jest twoja miłość, moja siostro, moja oblubienico! Jak daleko lepsza jest twoja miłość od wina, a woń twoich olejków od wszystkich innych wonności!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 11, 'Z twoich warg ocieka miód jak z plastrów, moja oblubienico! Miód i mleko pod twoim językiem, a woń twoich szat jest jak woń Libanu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 12, 'Jesteś zamkniętym ogrodem, moja siostro, moja oblubienico; źródłem zamkniętym, zdrojem zapieczętowanym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 13, 'Twoje pędy to sad drzew granatu z wybornym owocem cyprysu i nardu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 14, 'Nard i szafran, tatarak i cynamon, ze wszelkimi drzewami, kadzidło, mirra i aloes, ze wszelkimi wybornymi wonnościami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 15, 'Źródło ogrodów, zdrój żywych wód, które płyną z Libanu!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 16, 'Powstań, wietrze północny, i przyjdź, wietrze z południa, powiej przez mój ogród, by się rozpłynęły jego wonności. Niech przyjdzie mój umiłowany do swego ogrodu i niech je swoje rozkoszne owoce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 1, 'Wszedłem do mojego ogrodu, moja siostro, moja oblubienico. Zbierałem moją mirrę z moimi wonnościami; zjadłem mój plaster z moim miodem, piję moje wino z moim mlekiem. Jedzcie, przyjaciele, pijcie, a pijcie obficie, moi mili.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 2, 'Ja śpię, ale moje serce czuwa. Oto głos mego umiłowanego, który puka i mówi: Otwórz mi, moja siostro, moja umiłowana, moja gołębico, moja nieskalana. Moja głowa bowiem jest pełna rosy, moje kędziory – kropli nocy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 3, 'Zdjęłam już swoją suknię, jakże mam ją wkładać? Umyłam swoje nogi, jakże mam je pobrudzić?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 4, 'Mój umiłowany wsunął swoją rękę przez otwór, a moje wnętrze poruszyło się we mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 5, 'Wstałam, aby otworzyć mojemu umiłowanemu, a oto z moich rąk kapała mirra, z moich palców mirra spływała na uchwyt zasuwy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 6, 'Otworzyłam mojemu umiłowanemu, lecz mój umiłowany już odszedł i zniknął. Moja dusza zasłabła na jego głos. Szukałam go, ale nie znalazłam, wołałam go, ale mi nie odpowiedział.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 7, 'Znaleźli mnie strażnicy, którzy obchodzili miasto; pobili mnie i zranili, strażnicy murów zabrali mi zasłonę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 8, 'Zaklinam was, córki Jerozolimy: Jeśli znajdziecie mojego umiłowanego, to powiedzcie mu, że jestem chora z miłości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 9, 'Czym przewyższa twój umiłowany innych umiłowanych, o najpiękniejsza wśród kobiet? Czym przewyższa twój umiłowany innych umiłowanych, że tak nas zaklinasz?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 10, 'Mój umiłowany jest biały i rumiany, i najznakomitszy spośród dziesięciu tysięcy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 11, 'Jego głowa jest jak najczystsze złoto; jego kędziory faliste, czarne jak kruk.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 12, 'Jego oczy są jak gołębice nad strumieniami wody, jakby umyte w mleku, osadzone w swej oprawie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 13, 'Jego policzki jak grządka wonności, jak pachnące kwiatki; jego wargi jak lilie ociekające wyborną mirrą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 14, 'Jego ręce jak złote pierścienie wysadzone berylem; jego tors jak jasna kość słoniowa pokryta szafirem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 15, 'Jego nogi jak słupy z marmuru, postawione na szczerozłotych podstawkach; jego oblicze jak Liban, wyborne jak cedry.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 16, 'Jego usta przesłodkie i jest on cały przepiękny. Taki jest mój umiłowany i taki jest mój przyjaciel, córki Jerozolimy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 1, 'Dokąd poszedł twój umiłowany, o najpiękniejsza wśród kobiet? Dokąd się zwrócił twój umiłowany, abyśmy szukali go wraz z tobą?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 2, 'Mój umiłowany zstąpił do swojego ogrodu między grządki wonności, aby paść w ogrodach i zbierać lilie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 3, 'Ja należę do mego umiłowanego, a mój umiłowany należy do mnie; pasie on wśród lilii.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 4, 'Piękna jesteś, moja umiłowana, jak Tirsa; urodziwa jak Jerozolima; groźna jak wojsko z chorągwiami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 5, 'Odwróć ode mnie swoje oczy, gdyż one mnie urzekają. Twoje włosy są jak stado kóz, które schodzą z Gileadu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 6, 'Twoje zęby są jak stado owiec, które wychodzą z kąpieli, wszystkie mają bliźnięta, a nie ma żadnej niepłodnej wśród nich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 7, 'Twoje skronie między twoimi kędziorkami są jak połówki granatu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 8, 'Sześćdziesiąt jest królowych i osiemdziesiąt nałożnic, a dziewic bez liku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 9, 'Lecz moja gołębica, moja nieskalana, jest jedna; jedynaczka u swojej matki, bez skazy u swojej rodzicielki. Widziały ją córki i nazwały ją błogosławioną, także królowe i nałożnice, i chwaliły ją, mówiąc:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 10, 'Kim jest ta, która pokazuje się jak zorza poranna, piękna jak księżyc, czysta jak słońce, groźna jak uszykowane wojsko z chorągwiami?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 11, 'Zeszłam do ogrodu orzechów, aby patrzeć na owoce rosnące w dolinach, by zobaczyć, czy winorośl kwitnie i czy granaty wypuszczają pączki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 12, 'Nim się zorientowałam, moja dusza wsadziła mnie jakby w rydwany książąt mego ludu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 13, 'Zawróć, zawróć, Szulamitko; zawróć, zawróć, abyśmy mogli na ciebie patrzeć. Cóż widzicie w Szulamitce? Widzimy jakby oddziały wojenne.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 1, 'Jak piękne są twoje nogi w sandałach, córko książęca! Linia twoich bioder jest jak klejnot, jak dzieło rąk rzemieślnika.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 2, 'Twój pępek jest jak okrągła czasza, której nie brakuje napoju. Twój brzuch jest jak stóg pszenicy okolony liliami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 3, 'Twoje piersi są jak dwoje sarniąt, bliźniąt.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 4, 'Twoja szyja jest jak wieża z kości słoniowej; twoje oczy jak sadzawki Cheszbonu przy bramie Bat-Rabbim; twój nos jak wieża Libanu zwrócona w stronę Damaszku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 5, 'Twoja głowa na tobie jak Karmel, a włosy twojej głowy jak purpura. Król na twój widok jest jakby przywiązany w swoich krużgankach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 6, 'Jakże piękna jesteś i jak miła, o miłości przerozkoszna!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 7, 'Twój wzrost jest podobny do palmy, a twoje piersi do kiści winogron.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 8, 'Powiedziałem: Wejdę na palmę i uchwycę się jej gałęzi. Niech twoje piersi będą jak kiście winorośli, a woń twojego oddechu jak zapach jabłek;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 9, 'Twoje usta jak wyborne wino, które mile spływa po podniebieniu i sprawia, że wargi śpiących mówią.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 10, 'Ja należę do mojego umiłowanego i do mnie zwraca się jego pożądanie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 11, 'Chodź, mój umiłowany, wyjdźmy w pole i przenocujemy we wsiach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 12, 'Rankiem wstaniemy i pójdziemy do winnic, zobaczymy, czy kwitnie winorośl, czy otworzyły się już pączki, czy już kwitną granaty. Tam cię obdarzę swoją miłością.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 13, 'Mandragory wydają swoją woń, a przed naszymi drzwiami są wszelkie wyborne owoce, nowe i stare, które przechowałam dla ciebie, mój umiłowany.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 1, 'O gdybyś był dla mnie jak brat, który ssał piersi mojej matki! Wtedy spotykałabym cię na dworze, całowałabym cię, a nie byłabym wzgardzona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 2, 'Powiodłabym cię i wprowadziła do domu swojej matki, gdzie byś mnie uczył. A ja dałabym ci do picia wino korzenne, moszcz ze swoich granatów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 3, 'Jego lewa ręka byłaby pod moją głową, a prawa ręka objęłaby mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 4, 'Zaklinam was, córki Jerozolimy: Nie budźcie mego umiłowanego ani nie przerywajcie jego snu, dopóki on nie zechce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 5, 'Kim jest ta, która wyłania się z pustyni, wsparta na swym umiłowanym? Pod jabłonią cię wzbudziłam. Tam cię urodziła twoja matka, tam cię urodziła twoja rodzicielka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 6, 'Przyłóż mnie do swego serca jak pieczęć, jak pieczęć na swoim ramieniu. Miłość bowiem jest silna jak śmierć, zawiść twarda jak grób. Jej żar jak żar ognia i jak żarliwy płomień.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 7, 'Wielkie wody nie zdołają zagasić miłości ani rzeki jej zatopić. Choćby ktoś oddał cały majątek swego domu za taką miłość, byłby z pewnością wzgardzony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 8, 'Mamy małą siostrę, która jeszcze nie ma piersi. Cóż uczynimy z naszą siostrą w dniu, w którym będą o nią zabiegać?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 9, 'Jeśli jest murem, zbudujemy na niej srebrny pałac; a jeśli drzwiami, oprawimy ją deskami z cedru.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 10, 'Ja jestem murem, a moje piersi jak wieże. Odtąd byłam w jego oczach jak ta, która znalazła pokój.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 11, 'Salomon miał winnicę w Baal-Hamon, którą najął stróżom; każdy miał przynosić za jej owoc tysiąc srebrników.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 12, 'Ale moja winnica, którą mam, jest przede mną. Miej ty sobie tysiąc srebrników, Salomonie, a dwieście niech wezmą ci, którzy strzegą jej owocu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 13, 'O ty, która mieszkasz w ogrodach, przyjaciele słuchają twego głosu; daj mi go usłyszeć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 14, 'Pospiesz się, mój umiłowany, i bądź podobny do sarny albo młodego jelenia na górach wonności.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 1, 'Widzenie Izajasza, syna Amosa, dotyczące Judy i Jerozolimy, które miał za dni Uzjasza, Jotama, Achaza i Ezechiasza – królów Judy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 2, 'Słuchajcie, niebiosa, a ty, ziemio, nakłoń ucha. Pan bowiem przemówił: Wychowałem i wywyższyłem synów, ale oni zbuntowali się przeciw mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 3, 'Wół zna swojego gospodarza i osioł żłób swego pana, lecz Izrael mnie nie zna, mój lud się nie zastanawia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 4, 'Biada narodowi grzesznemu, ludowi obciążonemu nieprawością, potomstwu złoczyńców, synom powodującym zepsucie! Opuścili Pana, pobudzili do gniewu Świętego Izraela, odwrócili się od niego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 5, 'Po co was jeszcze bić, skoro mnożycie przestępstwa? Cała głowa chora, całe serce omdlałe.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 6, 'Od stopy aż do głowy nie ma w nim nic zdrowego; same rany i sińce, i gnijące rany; nieopatrzone ani nieprzewiązane, ani niezmiękczone olejkiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 7, 'Wasza ziemia jest spustoszona, wasze miasta – spalone ogniem. Waszą ziemię pożerają na waszych oczach cudzoziemcy i pustoszą, jak to zwykli czynić obcy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 8, 'I córka Syjonu została jak szałas w winnicy, jak budka w ogrodzie ogórkowym, jak miasto oblężone.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 9, 'Gdyby Pan zastępów nie zostawił nam malutkiej resztki, bylibyśmy jak Sodoma, stalibyśmy się podobni do Gomory.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 10, 'Słuchajcie słowa Pana, przywódcy Sodomy! Nakłońcie ucha ku prawu naszego Boga, ludzie Gomory!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 11, 'Co mi po mnóstwie waszych ofiar? – mówi Pan. Jestem syty całopaleń baranów i tłuszczu tuczonych zwierząt; nie pragnę krwi cielców, jagniąt i kozłów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 12, 'Gdy przychodzicie, by stanąć przede mną, kto od waszych rąk żądał tego, abyście deptali po moich dziedzińcach?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 13, 'Nie składajcie już więcej daremnych ofiar. Kadzidło wzbudza we mnie odrazę; nowiów i szabatów, zgromadzeń nie mogę znieść – bo to nieprawość, ani uroczystości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 14, 'Waszych nowiów i świąt nienawidzi moja dusza. Stały się dla mnie ciężarem; znużyło mnie ich znoszenie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 15, 'Gdy wyciągniecie swoje ręce, skryję swoje oczy przed wami. A gdy będziecie mnożyć modlitwy, nie wysłucham, gdyż wasze ręce są pełne krwi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 16, 'Obmyjcie się i oczyśćcie; usuńcie sprzed moich oczu zło waszych uczynków; przestańcie źle czynić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 17, 'Uczcie się czynić dobrze; szukajcie tego, co sprawiedliwe, wspomagajcie uciśnionego, brońcie sieroty, wstawiajcie się za wdową.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 18, 'Chodźcie teraz, a rozsądźmy, mówi Pan: Choćby wasze grzechy były jak szkarłat, jak śnieg wybieleją; choćby były czerwone jak karmazyn, staną się białe jak wełna.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 19, 'Jeśli będziecie ulegli i posłuszni, będziecie zażywali dóbr ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 20, 'Lecz jeśli będziecie nieposłuszni i uparci, miecz was pożre. Tak bowiem wyrzekły usta Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 21, 'Jakże to wierne miasto stało się nierządnicą! Niegdyś pełne sądu; mieszkała w nim sprawiedliwość, lecz teraz – mordercy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 22, 'Twoje srebro zamieniło się w żużel, twoje wino zmieszane z wodą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 23, 'Twoi książęta są buntownikami i wspólnikami złodziei. Każdy z nich kocha dary, goni za nagrodą; sierocie nie wymierzają sprawiedliwości, a sprawa wdowy do nich nie dociera.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 24, 'Dlatego mówi Pan, Pan zastępów, Mocarz Izraela: Biada! Ulżę sobie od swoich przeciwników i zemszczę się na moich wrogach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 25, 'I zwrócę moją rękę przeciwko tobie, wypalę twój żużel i usunę całą twoją cynę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 26, 'I przywrócę twoich sędziów, tak jak dawniej, i twoich doradców, jak na początku. Potem nazwą cię Miastem Sprawiedliwości, Miastem Wiernym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 27, 'Syjon zostanie odkupiony przez sąd, a jego nawróceni – przez sprawiedliwość.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 28, 'Ale przestępcy i grzesznicy będą razem starci, a ci, którzy opuścili Pana, zginą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 29, 'Będziecie bowiem zawstydzeni z powodu dębów, których pożądaliście, i zarumienicie się z powodu ogrodów, które sobie wybraliście.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 30, 'Staniecie się bowiem jak dąb, którego liście zwiędły, i jak ogród, w którym nie ma wody.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 31, 'I mocarz będzie jak paździerz, a ten, który go uczynił – jak iskra; i zapłoną obaj razem, a nie będzie nikogo, kto by ich ugasił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 1, 'Słowo, które widział Izajasz, syn Amosa, dotyczące Judy i Jerozolimy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 2, 'Stanie się w dniach ostatecznych, że góra domu Pana będzie utwierdzona na szczycie gór i wywyższona ponad pagórki; i wszystkie narody popłyną do niej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 3, 'I pójdzie wiele ludów, i powie: Chodźcie, wstąpmy na górę Pana, do domu Boga Jakuba; on będzie nas uczył swoich dróg, a my będziemy kroczyli jego ścieżkami. Z Syjonu bowiem wyjdzie prawo, a słowo Pana z Jerozolimy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 4, 'On będzie sądził wśród narodów i karcił wielu ludzi. I przekują swe miecze na lemiesze, a swoje włócznie na sierpy. Naród przeciw narodowi nie podniesie już miecza i nie będą się już ćwiczyć do wojny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 5, 'Domu Jakuba, chodźcie, postępujmy w światłości Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 6, 'Ale ty opuściłeś swój lud, dom Jakuba, gdyż pełen jest obrzydliwości wschodu i są oni wróżbitami jak Filistyni, a kochają się w cudzych synach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 7, 'Ich ziemia jest pełna srebra i złota i nie ma końca ich skarbom. Ich ziemia jest pełna koni i nie ma końca ich rydwanom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 8, 'Ich ziemia jest pełna bożków, oni oddają pokłon dziełom własnych rąk, które wykonały ich palce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 9, 'Kłania się przed nimi prosty człowiek, poniża się też wielki; nie przebaczaj im.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 10, 'Wejdź w skałę i ukryj się w prochu ze strachu przed Panem i przed chwałą jego majestatu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 11, 'Wyniosłe oczy człowieka ukorzą się, ludzka pycha będzie poniżona, a sam tylko Pan zostanie wywyższony w tym dniu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 12, 'Przyjdzie bowiem dzień Pana zastępów przeciwko każdemu pysznemu i wyniosłemu, i przeciwko każdemu wywyższonemu, a każdy zostanie poniżony;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 13, 'Przeciwko wszystkim cedrom Libanu, które są wysokie a wyniosłe, i przeciwko wszystkim dębom Baszanu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 14, 'Przeciwko wszystkim wysokim górom i przeciwko wszystkim wyniosłym pagórkom;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 15, 'Przeciwko każdej wysokiej wieży i przeciwko każdemu murowi obronnemu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 16, 'Przeciwko wszystkim okrętom Tarszisz i przeciwko wszelkiemu pięknemu malarstwu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 17, 'I wyniosłość człowieka będzie ugięta i pycha ludzka będzie poniżona, a sam tylko Pan zostanie wywyższony w tym dniu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 18, 'A bożki zniszczy doszczętnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 19, 'Wtedy wejdą do jaskiń skalnych i do jam podziemnych ze strachu przed Panem i przed chwałą jego majestatu, gdy powstanie, by przerazić ziemię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 20, 'W tym dniu człowiek wrzuci kretom i nietoperzom swoje bożki srebrne i złote, które uczynił, aby oddawać im pokłon;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 21, 'I wejdzie w szczeliny skalne i na szczyty opok ze strachu przed Panem i przed chwałą jego majestatu, gdy powstanie, aby przerazić ziemię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 22, 'Przestańcie polegać na człowieku, którego tchnienie jest w jego nozdrzach. Za co bowiem ma być uznany?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 1, 'Oto bowiem Pan, Pan zastępów, odbierze Jerozolimie i Judzie podporę i laskę, wszelką podporę w chlebie i wszelką podporę w wodzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 2, 'Mocarza i męża walecznego, sędziego i proroka, mędrca i starca;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 3, 'Dowódcę pięćdziesiątki i dostojnika, doradcę, wybitnego rzemieślnika i krasomówcę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 4, 'Książętami ustanowię chłopców, dzieci będą panować nad nimi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 5, 'Ludzie będą gnębić jeden drugiego, każdy swego bliźniego. Dziecko powstanie przeciwko starcowi, a podły przeciwko dostojnikowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 6, 'Gdy człowiek uchwyci się swego brata z domu swego ojca i powie: Masz ubranie, bądź naszym wodzem, niech te ruiny będą pod twoją ręką;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 7, 'Ten przysięgnie w tym dniu, mówiąc: Nie będę opatrywał tych ran; w moim domu bowiem nie ma chleba ani ubrania; nie czyńcie mnie wodzem ludu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 8, 'Bo Jerozolima upada, a Juda się wali, gdyż ich język i czyny są przeciwko Panu, aby pobudzić do gniewu oczy jego majestatu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 9, 'Wyraz ich twarzy świadczy przeciwko nim; jak Sodoma ogłaszają swój grzech, nie kryją go. Biada ich duszy! Gdyż sami na siebie sprowadzają zło.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 10, 'Powiedzcie sprawiedliwemu, że będzie mu dobrze, bo będzie spożywać owoc swoich rąk.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 11, 'Biada niegodziwemu! Będzie mu źle, odpłacą mu bowiem według czynów jego rąk.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 12, 'Ciemięzcami mego ludu są dzieci i kobiety nim rządzą. O ludu mój! Twoi wodzowie cię zwodzą i niszczą drogę twoich ścieżek.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 13, 'Pan powstał, aby się rozprawić, stoi, aby sądzić lud.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 14, 'Pan stawi na sąd starszych swego ludu i ich książąt: Wy spustoszyliście moją winnicę, w waszych domach znajduje się łup ubogich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 15, 'Po co miażdżycie mój lud i uciskacie oblicza ubogich? – mówi Pan Bóg zastępów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 16, 'Pan powiedział: Ponieważ wynoszą się córki Syjonu i chodzą z wyciągniętą szyją, uwodzą oczami, a chodząc, drepczą i pobrzękują swoimi nogami;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 17, 'Dlatego Pan ogoli wierzch głowy córek Syjonu i Pan obnaży ich nagość.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 18, 'W tym dniu Pan odejmie ozdobne brzękadła od ich stóp, ich czepce i księżyce;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 19, 'Łańcuszki, bransolety i welony;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 20, 'Czapeczki, ozdoby u nóg, opaski, naszyjniki i kolczyki;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 21, 'Pierścionki i wisiorki na czołach;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 22, 'Odświętne szaty, płaszcze, szale i torebki;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 23, 'Zwierciadełka, bisior, turbany i narzutki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 24, 'I wtedy zamiast wonności będzie smród, zamiast pasa będzie rozdarcie, zamiast upiętych włosów będzie łysina, zamiast szerokiej szaty będzie przepasanie worem i zamiast piękna będzie oparzenie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 25, 'Twoi mężczyźni polegną od miecza i twoi mocarze – na wojnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 26, 'Jej bramy zasmucą się i zapłaczą, a ona, spustoszona, usiądzie na ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 1, 'W tym dniu siedem kobiet uchwyci się jednego mężczyzny, mówiąc: Będziemy jadły swój chleb i ubierały się we własne ubranie, tylko niech zwiemy się twoim imieniem, odejmij od nas hańbę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 2, 'W ten dzień latorośl Pana będzie piękna i chwalebna, a owoc ziemi wyborny i wspaniały dla ocalałych spośród Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 3, 'I stanie się tak, że ten, kto zostanie na Syjonie, i ten, kto pozostanie w Jerozolimie, będą nazwani świętymi – każdy, kto jest zapisany wśród żywych w Jerozolimie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 4, 'Gdy Pan obmyje brud córek Syjonu i oczyści duchem sądu i duchem wypalenia krew Jerozolimy z jej wnętrza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 5, 'I Pan stworzy nad każdym miejscem zamieszkania góry Syjon i nad każdym jej zgromadzeniem obłok i dym za dnia, a blask płonącego ognia w nocy. Nad całą chwałą bowiem będzie osłona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 6, 'I będzie namiot, by za dnia dawać cień w upale; na schronienie i ukrycie przed burzą i deszczem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 1, 'Zaśpiewam teraz mojemu umiłowanemu pieśń mego ukochanego o jego winnicy. Mój umiłowany ma winnicę na urodzajnym pagórku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 2, 'Ogrodził ją, oczyścił z kamieni, zasadził szlachetną winorośl, zbudował pośrodku niej wieżę i sporządził w niej tłocznię. I oczekiwał, że wyda winogrona, ale ona wydała dzikie winogrona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 3, 'Teraz więc, mieszkańcy Jerozolimy i mężczyźni Judy, rozsądźcie, proszę, między mną a moją winnicą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 4, 'Co jeszcze należało uczynić dla mojej winnicy, czego dla niej nie uczyniłem? Dlaczego gdy oczekiwałem, że wyda winogrona, wydała ona dzikie winogrona?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 5, 'Oto oznajmię wam, co uczynię dla mojej winnicy: rozbiorę jej płot i będzie spustoszona, zniszczę jej ogrodzenie i będzie zdeptana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 6, 'I uczynię z niej pustkowie. Nie będzie przycinana ani okopywana, ale porośnie cierniem i ostem; chmurom także nakażę, aby nie spuszczały na nią deszczu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 7, 'Otóż winnicą Pana zastępów jest dom Izraela, a lud Judy jego rozkosznym szczepem. Oczekiwał sądu, a oto ucisk; oczekiwał sprawiedliwości, a oto krzyk.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 8, 'Biada tym, którzy przyłączają dom do domu i pole dodają do pola, tak że nie ma już wolnego miejsca, tak jakby mieli sami mieszkać na ziemi!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 9, 'Do moich uszu mówił Pan zastępów: Zaprawdę wiele domów spustoszeje, a wielkie i piękne domy będą bez mieszkańca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 10, 'Do tego dziesięć morgów winnicy wyda jeden bat, a jeden chomer ziarna wyda jedną efę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 11, 'Biada tym, którzy od wczesnego ranka wstają, by gonić za mocnym trunkiem, a tak trwają do wieczora, aż wino ich rozpala!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 12, 'Na ich biesiadach jest harfa, lutnia, bęben, flet i wino. Lecz sprawy Pana nic ich nie obchodzą ani nie zważają na dzieła jego rąk.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 13, 'Mój lud pójdzie więc w niewolę, bo nie ma poznania, a jego dostojnicy będą głodni i jego pospólstwo wyschnie z pragnienia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 14, 'Dlatego piekło rozszerzyło swą gardziel, rozwarło swoją paszczę bez miary. I do niego zstąpi jego szlachta i pospólstwo, jego zgiełk i weselący się.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 15, 'W ten sposób zostanie upokorzony prosty człowiek, wielki człowiek zostanie poniżony i oczy wyniosłych zostaną poniżone.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 16, 'Ale Pan zastępów będzie wywyższony przez swój sąd, a Święty Bóg okaże się święty w sprawiedliwości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 17, 'Baranki będą się paść według swego zwyczaju, a obcy pożywią się na opuszczonych polach bogaczy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 18, 'Biada tym, którzy ciągną nieprawość sznurami marności, a grzech – jakby powrozem wozu!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 19, 'Tym, którzy mówią: Niech się pospieszy i niech przyspieszy swoje dzieło, abyśmy je widzieli, niech się przybliży i przyjdzie zamysł Świętego Izraela, abyśmy go poznali.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 20, 'Biada tym, którzy zło nazywają dobrem, a dobro złem; którzy ciemność uważają za światłość, a światłość za ciemność; którzy gorycz uważają za słodycz, a słodycz za gorycz!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 21, 'Biada tym, którzy we własnych oczach uchodzą za mądrych i uważają się za roztropnych!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 22, 'Biada tym, którzy są mocni w piciu wina i dzielni w mieszaniu mocnego napoju!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 23, 'Tym, którzy za podarek usprawiedliwiają niegodziwego, a odejmują sprawiedliwym ich sprawiedliwość!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 24, 'Dlatego jak ogień pożera ściernisko i jak płomień trawi plewy, tak ich korzeń będzie jak zgnilizna, a ich kwiat ku górze uleci jak proch. Odrzucili bowiem prawo Pana zastępów i wzgardzili słowem Świętego Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 25, 'Zapłonął więc gniew Pana na jego lud, wyciągnął na niego swą rękę i uderzył go, aż góry zadrżały i trupy leżały jak gnój rozrzucony po ulicach. Mimo tego wszystkiego jego gniew nie ustał, ale jego ręka jest jeszcze wyciągnięta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 26, 'I wzniesie on sztandar dla narodów z daleka, i zaświszcze na nie z krańców ziemi, a oto śpiesznie i prędko przybędą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 27, 'Nie będzie wśród nich ani spracowanego, ani potykającego; nie będzie drzemiącego ani śpiącego, nikomu nie rozluźni się pas na biodrach ani nie pęknie rzemyk u sandałów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 28, 'Ich strzały są ostre i wszystkie ich łuki napięte; kopyta ich koni są jak krzemień, a ich koła jak wicher.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 29, 'Ich ryk jak ryk lwicy, będą ryczeć jak lwiątka. Będą zgrzytać i porywać łup, z którym uciekną i nikt im tego nie wyrwie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 30, 'W tym dniu będą ryczeć na nich jak szum morza. Gdy spojrzy się na ziemię, oto ciemność i ucisk, a na niebie przyćmi się światło.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 1, 'W roku, w którym umarł król Uzjasz, widziałem Pana siedzącego na wysokim i wyniosłym tronie, a tren jego szaty wypełnił świątynię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 2, 'Serafiny stały ponad nim, a każdy z nich miał po sześć skrzydeł: dwoma zakrywał swoją twarz, dwoma przykrywał swoje nogi, a dwoma latał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 3, 'I wołał jeden do drugiego: Święty, święty, święty, Pan zastępów. Cała ziemia jest pełna jego chwały.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 4, 'I filary drzwi poruszyły się od głosu wołającego, a dom napełnił się dymem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 5, 'I powiedziałem: Biada mi! Już zginąłem; jestem bowiem człowiekiem o nieczystych wargach i mieszkam wśród ludu o nieczystych wargach, a moje oczy widziały Króla, Pana zastępów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 6, 'Wówczas przyleciał do mnie jeden z serafinów, mając w ręku rozżarzony węgiel, który wziął kleszczami z ołtarza;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 7, 'I dotknął nim moich ust, i powiedział: Oto ten węgiel dotknął twoich warg; twoja nieprawość jest usunięta, a twój grzech zgładzony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 8, 'Potem usłyszałem głos Pana mówiącego: Kogo poślę i kto nam pójdzie? Wtedy odpowiedziałem: Oto jestem, poślij mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 9, 'A on powiedział: Idź i powiedz temu ludowi: Słuchajcie uważnie, ale nie rozumiejcie, patrzcie uważnie, ale nie poznawajcie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 10, 'Zatwardź serce tego ludu, uczyń jego uszy ciężkimi do słuchania i zaślep jego oczy, aby nie widział swoimi oczami, nie słyszał swoimi uszami i nie zrozumiał swoim sercem, aby nie nawrócił się i nie był uzdrowiony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 11, 'Wtedy zapytałem: Jak długo, Panie? A on odpowiedział: Aż miasta zostaną spustoszone i bez mieszkańca, domy bez ludzi, a ziemia zostanie doszczętnie spustoszona;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 12, 'Aż Pan zapędzi ludzi daleko i będzie wielkie spustoszenie pośród ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 13, 'Lecz zostanie w niej dziesiąta część, która powróci i ulegnie zniszczeniu. A jak po ścięciu terebintu lub dębu zostaje pień, tak samo będzie ze świętym potomstwem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 1, 'Za czasów Achaza, syna Jotama, syna Uzjasza, króla Judy, wyruszył Resin, król Syrii, wraz z Pekachem, synem Remaliasza, królem Izraela, przeciw Jerozolimie, aby z nią walczyć, lecz nie mógł jej zdobyć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 2, 'I doniesiono domowi Dawida: Syria zmówiła się z Efraimem. Wtedy zadrżało jego serce i serce jego ludu, jak drżą od wiatru drzewa w lesie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 3, 'Wtedy Pan powiedział do Izajasza: Wyjdź teraz naprzeciw Achaza, ty i Szear-Jaszub, twój syn, na koniec kanału górnej sadzawki przy drodze pola folusznika;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 4, 'I powiedz mu: Uważaj i bądź spokojny; nie bój się i niech twoje serce nie lęka się z powodu dwóch niedopałków dymiących głowni, z powodu zapalczywego gniewu Resina z Syrią oraz syna Remaliasza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 5, 'A ponieważ Syria, Efraim i syn Remaliasza uknuli przeciwko tobie zło, mówiąc:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 6, 'Wyruszmy przeciw Judzie i nastraszmy ją, zróbmy sobie w niej wyłom i ustanówmy w niej królem syna Tabeela;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 7, 'Tak mówi Pan Bóg: Nie stanie się to i nie dojdzie do tego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 8, 'Głową Syrii bowiem jest Damaszek, a głową Damaszku Resin; a po sześćdziesięciu pięciu latach Efraim będzie tak rozbity, że już nie będzie ludem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 9, 'A głową Efraima jest Samaria, głową zaś Samarii – syn Remaliasza. Jeśli nie uwierzycie, na pewno się nie ostoicie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 10, 'Ponadto Pan powiedział do Achaza:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 11, 'Proś dla siebie o znak od Pana, twego Boga, czy to z głębin, czy wysoko w górze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 12, 'Wtedy Achaz odpowiedział: Nie będę prosił Pana ani wystawiał go na próbę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 13, 'A on powiedział: Posłuchaj teraz, domu Dawida! Czy mało wam naprzykrzać się ludziom, że naprzykrzacie się także mojemu Bogu?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 14, 'Dlatego sam Pan da wam znak. Oto dziewica pocznie i urodzi syna, i nazwie go Emmanuel.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 15, 'Będzie on jadł masło i miód, aż będzie umiał odrzucać zło, a wybierać dobro.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 16, 'Zanim bowiem to dziecko będzie umiało odrzucać zło i wybierać dobro, ziemia, którą się brzydzisz, zostanie opuszczona przez dwóch swoich królów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 17, 'Pan sprowadzi na ciebie, na twój lud i na dom twego ojca dni, jakich nie było od dnia, w którym Efraim odstąpił od Judy – za sprawą króla Asyrii.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 18, 'I stanie się w tym dniu, że Pan zaświszcze na muchy, które są na krańcach rzek Egiptu, i na pszczoły, które są w ziemi Asyrii.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 19, 'I przybędą, i wszystkie obsiądą puste doliny i rozpadliny skalne, wszelkie krzaki kolczaste i wszelkie krzewy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 20, 'W tym dniu Pan ogoli wynajętą brzytwą – tymi, którzy są za rzeką, czyli królem Asyrii – głowę i włosy na nogach, także i brodę obetnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 21, 'I stanie się w tym dniu, że człowiek będzie hodował jedną krowę i dwie owce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 22, 'A dzięki obfitemu udojowi mleka będzie jadł masło. Każdy bowiem, kto pozostanie w ziemi, będzie jadł masło i miód.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 23, 'Stanie się też w tym dniu, że każde miejsce, gdzie rosło tysiąc winorośli wartości tysiąca srebrników, zarośnie ostem i cierniem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 24, 'Wtedy ze strzałami i z łukiem będą tam chodzić, bo cała ziemia zarośnie ostem i cierniem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 25, 'A na wszystkie góry, które uprawiano motyką, nie dojdzie strach przed ostem i cierniem. Ale będą przeznaczone na pastwisko dla wołów i do deptania przez trzodę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 1, 'I Pan powiedział do mnie: Weź sobie wielką księgę i napisz w niej ludzkim pismem: Maherszalalchaszbaz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 2, 'Wziąłem sobie wtedy za wiernych świadków Uriasza, kapłana, i Zachariasza, syna Jeberechiasza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 3, 'Potem zbliżyłem się do prorokini, a ona poczęła i urodziła syna. I Pan powiedział do mnie: Nazwij go: Maherszalalchaszbaz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 4, 'Zanim bowiem to dziecko nauczy się wołać: Mój ojcze i moja matko, bogactwa Damaszku i łupy Samarii zostaną wywiezione przed króla Asyrii.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 5, 'Ponadto Pan powiedział do mnie:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 6, 'Ponieważ ten lud wzgardził wodami Siloe, które płyną łagodnie, a chlubi się Resinem i synem Remaliasza;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 7, 'Oto Pan sprowadzi na niego wody rzeki, gwałtowne i obfite – króla Asyrii i całą jego chwałę. Wystąpi ze wszystkich swoich strumieni i wyleje ze wszystkich swoich brzegów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 8, 'Wedrze się do Judy, zaleje i rozejdzie się, aż dosięgnie szyi; a jego rozpostarte skrzydła napełnią szerokość twojej ziemi, Emmanuelu!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 9, 'Zbierajcie się, ludy, a zostaniecie zgniecione, nakłońcie ucha, wszyscy z dalekich ziem: Przepaszcie się, a zostaniecie zmiażdżeni; przepaszcie się, a zostaniecie zmiażdżeni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 10, 'Obmyślajcie plan, a będzie udaremniony; wypowiedzcie słowo, a nie ostoi się, bo Bóg jest z nami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 11, 'Tak bowiem Pan powiedział do mnie, gdy chwycił mnie za rękę, i przestrzegł mnie, abym nie kroczył drogą tego ludu:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 12, 'Nie mówcie: sprzysiężenie, kiedy ten lud mówi: sprzysiężenie; nie bójcie się tego, czego on się boi, ani się nie lękajcie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 13, 'Pana zastępów – jego uświęcajcie; niech on będzie waszą bojaźnią i on waszą trwogą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 14, 'On będzie dla was świątynią, ale kamieniem potknięcia i skałą zgorszenia dla obu domów Izraela, pułapką i sidłem dla mieszkańców Jerozolimy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 15, 'I wielu z nich się potknie, upadnie i rozbije, będą usidleni i pojmani.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 16, 'Zawiąż to świadectwo, zapieczętuj prawo wśród moich uczniów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 17, 'I będę czekał na Pana, który ukrył swoje oblicze przed domem Jakuba, i będę go oczekiwać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 18, 'Oto ja i dzieci, które Pan mi dał, jesteśmy znakami i cudami w Izraelu od Pana zastępów, który mieszka na górze Syjon.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 19, 'A gdy będą wam mówić: Radźcie się czarowników i wróżbitów, którzy szepcą i mruczą, powiedzcie: Czyż lud nie powinien radzić się swego Boga? Czy ma się radzić umarłych w sprawie żywych?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 20, 'Do prawa i do świadectwa! Jeśli nie będą mówić według tego słowa, to w nim nie ma żadnej światłości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 21, 'A będą się tułali po ziemi, uciskani i wygłodzeni; a cierpiąc głód, będą się złościć i złorzeczyć swemu królowi oraz swemu Bogu, spoglądając ku górze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 22, 'I spojrzą na ziemię, a oto ucisk i ciemność, mrok i cierpienie, i będą zapędzeni w ciemności.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 1, 'Mrok jednak nie będzie taki, jak był w czasie jej ucisku, gdy Bóg dotknął ziemię Zebulona i ziemię Neftalego, ani jak potem, gdy trapił ją przy drodze morskiej za Jordanem, w Galilei pogan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 2, 'Lud, który chodził w ciemności, ujrzał wielką światłość, a mieszkającym w ziemi cienia śmierci zajaśniała światłość.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 3, 'Rozmnożyłeś ten naród, ale nie zwiększyłeś radości. Będą się jednak radować przed tobą, jak się radują w czasie żniwa, jak się radują przy podziale łupów;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 4, 'Gdyż złamałeś jarzmo jego ciężaru i laskę jego ramienia, pręt jego ciemięzcy, jak za dni Midianitów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 5, 'Każdej bitwie wojowników towarzyszą trzask i szaty zbroczone krwią, lecz tej – spalenie i ogień.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 6, 'Dziecko bowiem narodziło się nam, syn został nam dany. Na jego ramieniu spocznie władza, a nazwą go imieniem: Cudowny, Doradca, Bóg Mocny, Ojciec Wieczności, Książę Pokoju;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 7, 'A rozszerzeniu jego władzy i pokoju nie będzie końca, zasiądzie na tronie Dawida i nad jego królestwem, aż je ustanowi i utwierdzi sądem i sprawiedliwością, odtąd i na wieki. Dokona tego gorliwość Pana zastępów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 8, 'Pan posłał słowo do Jakuba i spadło na Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 9, 'Pozna je cały lud, Efraim i mieszkańcy Samarii, którzy mówią w pysze i wyniosłości serca:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 10, 'Cegły rozsypały się, ale my będziemy budować ciosanym kamieniem. Wycięto sykomory, ale my zastąpimy je cedrami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 11, 'Pan wywyższy wrogów Resina przeciwko niemu i zjednoczy jego nieprzyjaciół;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 12, 'Syryjczyków z przodu i Filistynów z tyłu; i pożrą Izraela całą paszczą. Mimo tego wszystkiego jego gniew nie ustał, ale jego ręka jest jeszcze wyciągnięta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 13, 'Lud bowiem nie nawraca się do tego, który go bije, ani nie szuka Pana zastępów;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 14, 'Dlatego Pan odetnie Izraelowi głowę i ogon, gałąź i sitowie, w jednym dniu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 15, 'Starzec i dostojnik – to głowa, a prorok, który uczy kłamstwa – to ogon.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 16, 'Przywódcy tego ludu stali się bowiem zwodzicielami, a ci, którym przewodzą, giną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 17, 'Dlatego Pan nie ucieszy się z jego młodzieńców i nie zlituje się nad jego sierotami i wdowami. Wszyscy bowiem są obłudni i niegodziwi, a każde usta mówią sprośności. Mimo tego wszystkiego jego gniew nie ustał, ale jego ręka jest jeszcze wyciągnięta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 18, 'Niegodziwość bowiem płonie jak ogień, pożre głogi i ciernie, potem zapali się w gęstwinach lasu, skąd jak dym unoszą się.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 19, 'Od gniewu Pana zastępów zaćmi się ziemia, a ten lud będzie jak strawa dla ognia. Nikt nie oszczędzi swego brata.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 20, 'A porwie, co znajduje się po prawej stronie, ale nadal będzie głodny; zje, co z lewej, ale nie nasyci się. Każdy z nich będzie pożerać ciało swego ramienia;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 21, 'Manasses – Efraima, a Efraim – Manassesa, a obaj razem będą przeciwko Judzie. Mimo tego wszystkiego jego gniew nie ustał, ale jego ręka jest jeszcze wyciągnięta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 1, 'Biada tym, którzy wydają niesprawiedliwe ustawy, i tym, którzy wypisują dekrety ucisku;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 2, 'Aby odepchnąć ubogiego od sądu i pozbawić sprawiedliwości ubogich mego ludu, aby wdowy stały się ich łupem i aby mogli ograbiać sieroty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 3, 'A co uczynicie w dniu nawiedzenia i spustoszenia, który przyjdzie z daleka? Do kogo będziecie uciekać się o pomoc? I gdzie zostawicie swoją chwałę?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 4, 'Beze mnie skulą się wśród więźniów, upadną wśród zabitych. Mimo tego wszystkiego jego gniew nie ustał, ale jego ręka jest jeszcze wyciągnięta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 5, 'Ach, Asyryjczyk, rózga mego gniewu; w jego ręku jest kij mojego oburzenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 6, 'Wyślę go przeciw obłudnemu narodowi, przeciw ludowi mojego gniewu przykażę mu, aby zebrał łup i zdobycz, aby zdeptał go, jak błoto na ulicach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 7, 'Lecz on nie tak będzie mniemał i jego serce nie będzie tak myślało, ponieważ w swoim sercu umyślił wytracić i wytępić niemało narodów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 8, 'Mówi bowiem: Czyż moi książęta nie są królami?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 9, 'Czy Kalno nie jest jak Karkemisz? Czy Chamat nie jest jak Arpad? Czy Samaria nie jest jak Damaszek?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 10, 'Jak moja ręka dosięgła królestw bożków, chociaż ich bożki przewyższały te w Jerozolimie i Samarii;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 11, 'Czyż nie uczynię z Jerozolimą i jej bożkami tak, jak uczyniłem z Samarią i jej bożkami?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 12, 'I stanie się, że gdy Pan dokona całego swojego dzieła nad górą Syjonu i nad Jerozolimą, ukarzę owoc wyniosłego serca króla Asyrii i pychę jego zuchwałych oczu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 13, 'Mówi bowiem: Dokonałem tego mocą swojej ręki i własną mądrością, bo jestem mądry. Zniosłem granice narodów, zabrałem ich skarby i powaliłem mieszkańców jak mocarz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 14, 'Moja ręka sięgnęła po bogactwo narodów jak do gniazda. A jak się zbiera porzucone jajka, tak ja zgarnąłem całą ziemię; i nikt nawet skrzydłem nie poruszył, nie otworzył dzioba ani nie pisnął.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 15, 'Czy chełpi się siekiera wobec tego, który nią rąbie? Czy wynosi się piła nad tego, który nią piłuje? Jak gdyby rózga wywijała tym, który ją podnosi, jak gdyby kij podnosił się, jakby nie był drewnem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 16, 'Dlatego Pan, Pan zastępów, ześle wycieńczenie na jego opasłych, a pod jego chwałą rozpali ogień, jakby płonący ogień.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 17, 'A Światłość Izraela będzie ogniem, a jego Święty – płomieniem, który spali i strawi jego ciernie i osty w jednym dniu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 18, 'Strawi także wspaniałość jego lasu i urodzajnych pól, od duszy aż do ciała, i stanie się tak jak wtedy, gdy chorąży ucieka ze strachu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 19, 'A pozostałych drzew jego lasu będzie tak niewiele, że nawet dziecko będzie mogło je spisać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 20, 'I w tym dniu stanie się, że resztka Izraela i ci, którzy ocaleli z domu Jakuba, nie będą już polegać na tym, który ich bije, lecz będą prawdziwie polegać na Panu, Świętym Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 21, 'Resztka zawróci, resztka Jakuba, do Boga mocnego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 22, 'Bo choćby twój lud, Izraelu, był jak piasek morski, tylko resztka z niego powróci. Postanowione wytracenie będzie opływało w sprawiedliwość.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 23, 'Pan Bóg zastępów dokona bowiem postanowionego wytracenia pośród całej tej ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 24, 'Dlatego tak mówi Pan Bóg zastępów: Mój ludu, który mieszkasz na Syjonie, nie bój się Asyryjczyka. Uderzy cię rózgą i swą laskę podniesie na ciebie, tak jak Egipt.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 25, 'Jeszcze chwila bowiem, a skończy się mój gniew i moja zapalczywość – ku ich zniszczeniu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 26, 'I Pan zastępów wzbudzi bicz na niego, jak podczas porażki Midianitów przy skale Oreba, i podniesie swą laskę tak, jak ją podniósł nad morzem, w Egipcie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 27, 'I stanie się w tym dniu, że jego brzemię zostanie zdjęte z twoich ramion i jego jarzmo z twojej szyi, a to jarzmo zostanie zniszczone z powodu namaszczenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 28, 'Przybył do Ajjat, przeszedł przez Migron, w Mikmas zostawił swój oręż.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 29, 'Przeszyli przełęcz, w Geba zanocowali; zlękła się Rama, uciekła Gibea Saula.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 30, 'Podnieś swój głos, córko Gallim! Niech słyszą w Laisz, biedny Anatot!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 31, 'Madmena ustąpiła, mieszkańcy Gabim szykują się do ucieczki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 32, 'Jeszcze przez dzień zostanie w Nob, potrząśnie swoją ręką przeciwko córce Syjonu, wzgórzu Jerozolimy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 33, 'Oto Pan, Pan zastępów odetnie latorośle gwałtownie. Wznoszące się wysoko zostaną ścięte, a wyniosłe będą poniżone.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 34, 'Wytnie także gęstwiny lasu siekierą, a Liban upadnie od wielmożnego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 1, 'I wyjdzie gałązka z pnia Jessego, a latorośl z jego korzenia wyrośnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 2, 'I spocznie na nim Duch Pana, duch mądrości i rozumu, duch rady i mocy, duch poznania i bojaźni Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 3, 'I będzie czujny w bojaźni Pana, nie będzie sądził według tego, co oczy widzą, ani karał według tego, co uszy słyszą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 4, 'Ale w sprawiedliwości będzie sądził ubogich, a w prawości będzie rozstrzygał sprawy cichych na ziemi. Uderzy ziemię rózgą swoich ust, a tchnieniem swoich warg zabije niegodziwego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 5, 'Sprawiedliwość będzie pasem jego bioder, a prawda pasem jego lędźwi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 6, 'I wilk będzie przebywał z barankiem, a lampart będzie leżał przy koźlęciu; także cielę i młody lew, i tuczne bydło będą razem; a małe dziecko będzie je prowadziło.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 7, 'Krowa i niedźwiedzica razem będą się pasły, ich młode będą leżały razem, a lew, jak wół, będzie jeść słomę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 8, 'Niemowlę będzie się bawić nad jamą żmii; a dziecko włoży swą rękę do nory jadowitego węża.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 9, 'Nie będą wyrządzać krzywdy ani zabijać na całej mojej świętej górze, bo ziemia będzie napełniona poznaniem Pana, tak jak wody okrywają morze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 10, 'W tym dniu korzeń Jessego będzie stać jako sztandar dla narodów. Poganie będą się do niego zwracać, a jego odpoczynek będzie cudowny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 11, 'Stanie się też w tym dniu, że Pan ponownie wyciągnie swą rękę, aby wykupić resztkę swego ludu, który pozostanie, z Asyrii i Egiptu, z Patros i Chus, z Elamu i Szinearu, i z Chamat, i wysp morskich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 12, 'I podniesie sztandar dla narodów, i zgromadzi wygnańców z Izraela, a rozproszonych z Judy zbierze z czterech krańców ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 13, 'Ustanie zazdrość Efraima, a nieprzyjaciele Judy zostaną wytraceni. Efraim nie będzie zazdrościł Judzie, a Juda nie będzie trapił Efraima;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 14, 'Ale polecą na ramionach Filistynów ku zachodowi, razem złupią narody na wschodzie; na Edomitów i Moabitów położą swą rękę, a synowie Amona będą im posłuszni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 15, 'I Pan zniszczy odnogę morza Egiptu i swoim potężnym wiatrem potrząśnie swoją ręką nad rzeką, uderzy jej siedem strumieni i sprawi, że będą przez nią przechodzić w obuwiu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 16, 'Tak powstanie droga dla resztki jego ludu, który pozostanie z Asyrii, jak powstała dla Izraela w tym dniu, kiedy wychodził z ziemi Egiptu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 1, 'I w tym dniu powiesz: Wysławiać cię będę, Panie, bo choć gniewałeś się na mnie, odwróciłeś swój gniew i pocieszyłeś mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 2, 'Oto Bóg jest moim zbawieniem, zaufam i nie będę się lękał, gdyż Jehowa Bóg jest moją mocą i moją pieśnią; i on stał się moim zbawieniem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 3, 'Z radością więc będziecie czerpać wodę ze zdrojów zbawienia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 4, 'W tym dniu powiecie: Wysławiajcie Pana, wzywajcie jego imienia, rozgłaszajcie wśród ludów jego dzieła, przypominajcie, że jego imię jest wywyższone.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 5, 'Śpiewajcie Panu, gdyż uczynił wielkie rzeczy. Niech będzie o tym wiadomo w całej ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 6, 'Wykrzykuj i śpiewaj, mieszkanko Syjonu! Wielki bowiem jest pośród ciebie Święty Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 1, 'Brzemię Babilonu, które widział Izajasz, syn Amosa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 2, 'Na wysokiej górze wznieście sztandar, podnieście na nich głos, machajcie ręką, aby weszli w bramy książąt.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 3, 'Ja nakazałem swoim poświęconym, wezwałem też swoich mocarzy do okazywania mojego gniewu, tych, którzy radują się z mojego majestatu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 4, 'Odgłosy zgrai na górach jakby licznego ludu, odgłosy zgiełku królestw, zgromadzonych narodów. Pan zastępów gromadzi wojsko na wojnę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 5, 'Przybywają z dalekiej ziemi, z krańców nieba, Pan i narzędzia jego zapalczywości, aby spustoszyć całą ziemię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 6, 'Zawódźcie, bo bliski jest dzień Pana; przyjdzie jak spustoszenie od Wszechmocnego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 7, 'Dlatego wszelkie ręce opadną, a każde serce człowieka struchleje.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 8, 'I będą przerażeni: ogarną ich skurcze i boleści, będą wić się z bólu jak rodząca kobieta. Jeden na drugiego spojrzy z osłupieniem, ich twarze będą podobne do płomieni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 9, 'Oto dzień Pana nadchodzi, okrutny, w zapalczywości i srogim gniewie, aby zamienić tę ziemię w pustynię i wytępić z niej grzeszników.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 10, 'Gwiazdy nieba bowiem i ich konstelacje nie będą jaśniały swoim światłem. Słońce się zaćmi, gdy tylko wzejdzie, a księżyc nie zabłyśnie swoim światłem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 11, 'I ukarzę świat za jego zło i niegodziwych za ich nieprawość; położę kres pysze zuchwałych i poniżę wyniosłość okrutników.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 12, 'Uczynię człowieka droższym niż czyste złoto, a nawet droższym niż złoto z Ofiru.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 13, 'Dlatego zatrząsnę niebem, a ziemia ruszy się ze swego miejsca pod zapalczywością Pana zastępów i w dniu jego srogiego gniewu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 14, 'I będzie jak spłoszona sarna i jak trzoda, której nikt nie gromadzi: każdy powróci do swego ludu i każdy ucieknie do swojej ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 15, 'Każdy, kogo znajdą, zostanie przebity; a każdy, kto się do nich przyłączy, polegnie od miecza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 16, 'Ich dzieci będą roztrzaskane na ich oczach, ich domy będą splądrowane, a ich żony – zgwałcone.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 17, 'Oto pobudzę przeciwko nim Medów, którzy o srebro nie będą dbać, a w złocie nie będą się lubować.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 18, 'Ich łuki roztrzaskają młodzieńców, nie zlitują się nad płodem łona, ich oko nie przepuści dzieciom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 19, 'I Babilon, ozdoba królestw i chluba majestatu Chaldejczyków, stanie się jak Sodoma i Gomora, kiedy Bóg je zniszczył.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 20, 'Nie będzie nigdy więcej zamieszkany ani zasiedlony z pokolenia na pokolenie; Arab nie rozbije tam namiotu ani pasterze nie odpoczną tam z trzodami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 21, 'Ale dziki zwierz pustyni będzie tam odpoczywać, a ich domy będą pełne wyjących bestii; zamieszkają tam sowy, a kozice będą tam podskakiwać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 22, 'Straszne bestie wysp będą wyć w ich opuszczonych domach, a smoki w ich wspaniałych pałacach. Jego czas jest bliski, jego dni nie będą przedłużone.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 1, 'Pan bowiem zlituje się nad Jakubem i znowu wybierze Izraela, i osadzi ich w ich własnej ziemi. Cudzoziemcy przyłączą się do nich i przystaną do domu Jakuba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 2, 'Wezmą ich narody i przyprowadzą do ich miejsca. A dom Izraela weźmie ich w posiadanie w ziemi Pana jako sługi i służące. I będą trzymać w niewoli tych, u których byli w niewoli, i będą panować nad swoimi ciemięzcami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 3, 'W tym dniu, kiedy Pan da ci odpoczynek po twojej udręce, po twoim strachu i po twojej ciężkiej niewoli, w którą zostałeś podbity;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 4, 'Podejmiesz tę przypowieść przeciw królowi Babilonu i powiesz: O jakże ustał ciemięzca! Jakże ustało złote miasto!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 5, 'Pan złamał kij niegodziwych i berło panujących;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 6, 'Tego, który smagał ludzi z wściekłością nieustannymi ciosami, który panował w gniewie nad narodami i dręczył bez litości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 7, 'Teraz cała ziemia odpoczywa i jest spokojna, wszyscy głośno śpiewają;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 8, 'Nawet cyprysy radują się z powodu ciebie, a także cedry Libanu, mówiąc: Odkąd ległeś, żaden drwal nie powstał przeciwko nam.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 9, 'Piekło w dole poruszyło się przez ciebie, by wyjść ci na spotkanie; dla ciebie obudziło umarłych, wszystkich książąt ziemi; rozkazało wszystkim królom narodów powstać ze swoich tronów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 10, 'Ci wszyscy odezwą się i powiedzą ci: Czyż zasłabłeś jak i my? Czy stałeś się podobny do nas?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 11, 'Strącono do piekła twój przepych i dźwięk twojej lutni. Twoim posłaniem jest robactwo, robactwo też jest twoim przykryciem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 12, 'O jakże spadłeś z nieba, Lucyferze, synu jutrzenki! Powalony jesteś aż na ziemię, ty, który osłabiałeś narody!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 13, 'Ty bowiem mówiłeś w swoim sercu: Wstąpię do nieba, ponad gwiazdy Boga wywyższę swój tron. Zasiądę na górze zgromadzenia, na krańcach północy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 14, 'Wzniosę się nad szczyty obłoków, będę równy Najwyższemu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 15, 'Lecz zostaniesz strącony aż do piekła, do krańców dołu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 16, 'Ci, którzy cię ujrzą, będą patrzeć na ciebie i zastanawiać się nad tobą, mówiąc: Czy to ten, który wprawił w drżenie ziemię i trząsł królestwami?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 17, 'Ten, który świat zamienił w pustynię i zniszczył jego miasta, a swoich więźniów nie wypuścił z ciemnicy?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 18, 'Wszyscy królowie narodów, wszyscy oni spoczywają w chwale, każdy w swoim domu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 19, 'Ale ty zostałeś wyrzucony ze swego grobu jak obrzydła latorośl, jak szata zabitych, których przeszyto mieczem, którzy zstępują do kamiennego dołu, zdeptani jak padlina.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 20, 'Nie będziesz uczestniczył wraz z nimi w pogrzebie, bo zniszczyłeś swoją ziemię i wymordowałeś swój lud. Potomstwo złoczyńców nie będzie wspominane na wieki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 21, 'Przygotujcie rzeź dla jego synów z powodu nieprawości ich ojców, aby nie powstali ani nie odziedziczyli ziemi, ani nie pokryli powierzchni ziemi miastami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 22, 'Powstanę bowiem przeciwko nim, mówi Pan zastępów, a zniszczę z Babilonu imię, resztkę, syna i wnuka, mówi Pan;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 23, 'I uczynię go siedliskiem bąków i stawami wodnymi. I wymiotę go miotłą spustoszenia, mówi Pan zastępów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 24, 'Przysiągł Pan zastępów, mówiąc: Zaprawdę, jak obmyśliłem, tak będzie, a jak postanowiłem, tak się stanie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 25, 'Złamię Asyryjczyka w mojej ziemi i na moich górach zdepczę go. Wtedy spadnie z nich jego jarzmo i jego brzemię spadnie z ich ramion.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 26, 'To jest powzięty zamiar co do całej ziemi i to jest ręka wyciągnięta nad wszystkie narody.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 27, 'Skoro Pan zastępów postanowił, któż to udaremni? Jego ręka jest wyciągnięta, któż ją odwróci?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 28, 'W roku, w którym umarł król Achaz, stało się takie oto proroctwo:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 29, 'Nie raduj się, cała ziemio Filisteo, z tego, że został złamany kij tego, który cię bił, bo z korzenia węża wyjdzie żmija, jego płodem będzie ognisty smok latający.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 30, 'Pierworodni nędzarzy będą się paść, a ubodzy odpoczną bezpiecznie. Lecz twój korzeń wytępię głodem, a zabiję twoją resztkę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 31, 'Zawódź, bramo! Krzycz, miasto! Ty, cała Filisteo, już się rozpłynęłaś. Od północy bowiem nadciąga dym i nikt nie będzie stronił od jego szeregów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 32, 'I cóż odpowiedzieć posłom narodu? To, że Pan ugruntował Syjon i w nim będą się chronić ubodzy jego ludu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 1, 'Brzemię Moabu. Ponieważ w nocy Ar-Moab został zburzony i spustoszony, ponieważ w nocy Kir-Moab został zburzony i spustoszony;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 2, 'Wstąpił do Bajit i do Dibonu, na wyżyny, by płakać. Moab będzie lamentować nad Nebo i Medebą; wszystkie ich głowy będą ogolone, a każda broda będzie obcięta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 3, 'Na jego ulicach przepasują się worem; na jego dachach i placach każdy będzie zawodził, rozpływając się we łzach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 4, 'Cheszbon i Eleale będą krzyczeć, a ich głos będzie słychać aż w Jahaza. Dlatego uzbrojeni wojownicy Moabu będą biadać, a dusza każdego rozrzewni się w sobie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 5, 'Moje serce jęczy nad Moabem, jego uchodźcy uciekną aż do Zoar jak jałowica trzyletnia; bo drogą pod górę do Luchit pójdą z płaczem, a na drodze do Choronaim podniosą krzyk z powodu klęski.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 6, 'Wody Nimrim staną się bowiem pustkowiem, bo trawa uschła, zieleń zwiędła, nie ma nic zielonego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 7, 'Dlatego swój majątek i to, co zgromadzili, przenoszą nad Potok Wierzbowy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 8, 'Bo krzyk obiega granicę Moabu, aż do Eglaim jego lament i aż do Beer-Elim jego zawodzenie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 9, 'Ponieważ wody Dimonu będą pełne krwi, gdyż sprowadzę na Dimon jeszcze więcej – lwy na tych, którzy uszli z Moabu i na resztkę tej ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 1, 'Poślijcie baranki, władcy ziemi, od Sela aż do pustyni, do góry córki Syjonu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 2, 'Bo inaczej jak ptak wędrowny i z gniazda wypłoszony będą córki Moabu przy brodach Arnonu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 3, 'Naradź się, rozstrzygnij sprawę; rozłóż swój cień w pełne południe jak w nocy; ukryj wygnańców, nie wydawaj tułacza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 4, 'Niech mieszkają u ciebie moi wygnańcy, Moabie; bądź ich schronieniem przed grabieżcą. Ustanie bowiem gnębiciel, przeminie grabieżca, a ciemięzca zostanie zgładzony z ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 5, 'I tron będzie utwierdzony dzięki miłosierdziu; zasiądzie na nim w prawdzie, w przybytku Dawida, ten, który będzie sądził i dbał o prawo, i niezwłocznie wymierzy sprawiedliwość.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 6, 'Słyszeliśmy o pysze Moabu, że jest bardzo pyszny, o jego zuchwałości, wyniosłości i gniewie. Lecz jego zamiary nie dojdą do skutku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 7, 'Dlatego Moab będzie zawodzić nad Moabem, wszyscy będą zawodzić. Nad gruntami miasta Kir-Chareset będą wzdychać, mówiąc: Już są zniszczone.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 8, 'Spustoszone są bowiem pola Cheszbonu i winorośl Sibmy. Władcy narodów stratowali najwyborniejsze jej latorośle, które sięgały aż do Jazer, a szerzyły się na pustyni; jej latorośle rozłożyły się i przeszły morze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 9, 'Dlatego jak opłakuję Jazer, będę opłakiwał winorośl Sibmy. Zroszę cię swymi łzami, Cheszbonie i Eleale, bo na twój letni owoc i na twoje żniwo padł okrzyk wojenny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 10, 'Znikło wesele i znikła radość z urodzajnego pola; w winnicach nie będzie śpiewania ani okrzyku. Nie będzie się tłoczyć wina w tłoczniach; powstrzymałem okrzyki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 11, 'Dlatego moje wnętrze będzie jęczeć nad Moabem jak harfa, a moje serce nad Kir-Chares.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 12, 'I stanie się, gdy się okaże, że Moab się męczył na wyżynie, że wejdzie on do swojej świątyni, aby się modlić, ale nie przemoże.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 13, 'To jest słowo, które Pan niegdyś powiedział o Moabie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 14, 'Ale teraz Pan powiedział: Po trzech latach, liczonych jak lata najemnika, chwała Moabu zostanie wzgardzona wraz z całym jego wielkim tłumem, a jego resztka będzie bardzo mała i bezsilna.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 1, 'Brzemię Damaszku. Oto Damaszek przestanie być miastem, a stanie się rumowiskiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 2, 'Miasta Aroeru będą opuszczone. Będą dla trzód, by się tam kładły, a nikt ich nie spłoszy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 3, 'Nastąpi koniec twierdzy Efraima i królestwa Damaszku. A z resztką Syrii będzie jak z chwałą synów Izraela, mówi Pan zastępów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 4, 'I stanie się w tym dniu tak, że chwała Jakuba zmaleje, a jego tłuste ciało schudnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 5, 'I będzie tak jak wtedy, gdy żniwiarz zbiera zboże, a jego ramię ścina kłosy; będzie jak ten, co zbiera kłosy w dolinie Refaim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 6, 'Pozostanie na nim jednak pokłosie, jak przy otrząsaniu drzewa oliwnego: dwie lub trzy oliwki zostaną na samym wierzchołku drzewa, a cztery lub pięć na urodzajnych gałęziach, mówi Pan, Bóg Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 7, 'W tym dniu człowiek spojrzy na swego Stwórcę i jego oczy będą spoglądać na Świętego Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 8, 'A nie popatrzy więcej na ołtarze, dzieło swoich rąk, ani nie będzie patrzeć na to, co uczyniły jego palce ani na gaje, ani na posągi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 9, 'W tym dniu jego miasta warowne będą jak porzucony konar i sucha gałąź, które opuścili przed synami Izraela – i będzie spustoszenie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 10, 'A ponieważ zapomniałeś o Bogu twojego zbawienia i nie pamiętałeś o skale twojej mocy, to choć zasadzasz rozkoszne sadzonki i sadzisz obce winorośle;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 11, 'I w dniu sprawiasz, że sadzonka rośnie, i rano doprowadzasz swój siew do rozkwitu, w dniu żniwa będziesz żąć mnóstwo smutku i nieuleczalnej rozpaczy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 12, 'Biada tłumom licznych ludów, które huczą jak rozhukane morze, i zgiełkowi narodów, które szumią jak szum wód gwałtownych!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 13, 'Narody szumią jak szum wielkich wód, ale Pan je zgromi i uciekną daleko gnane wiatrem jak plewy na górach i jak biegacz stepowy przed wichurą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 14, 'Oto w porze wieczornej trwoga, a nim nadejdzie poranek, już go nie ma. Taki jest dział tych, którzy nas łupią, i los tych, którzy nas plądrują.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 1, 'Biada ziemi, którą zacieniają skrzydła, ziemi leżącej za rzekami Etiopii;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 2, 'Która wysyła posłów przez morze w łodziach z sitowia po wodach, mówiąc: Idźcie, prędcy posłańcy, do narodu rozszarpanego i splądrowanego, do ludu, który budzi grozę, odkąd istnieje, do narodu zdeptanego do szczętu, którego ziemię rozrywają rzeki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 3, 'Wszyscy mieszkańcy świata i osiedleńcy ziemi, zobaczycie, jak sztandar zostanie wzniesiony na górach, i usłyszycie, gdy zadmą w trąby.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 4, 'Tak bowiem mówi Pan do mnie: Będę spokojny i będę przypatrywać się z mojego przybytku – jak pogodne ciepło po deszczu, jak obłok rosy w upalne żniwo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 5, 'Bo przed żniwem, gdy puszczą pączki, a kwiat wyda dojrzewające cierpkie grono, wtedy obetnie gałązki nożami i gałęzie usunie i obetnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 6, 'I będą pozostawione wszystkie razem ptakom górskim i zwierzętom polnym. Ptaki spędzą na nich lato, a wszystkie zwierzęta polne na nich przezimują.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 7, 'W tym czasie będzie przyniesiony dar Panu zastępów od ludu rozszarpanego i splądrowanego, od ludu budzącego grozę, odkąd istnieje aż do dziś, od narodu do szczętu zdeptanego, którego ziemię rozrywały rzeki, na miejsce imienia Pana zastępów, na górę Syjon.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 1, 'Brzemię Egiptu. Oto Pan jedzie na lekkim obłoku i przybędzie do Egiptu. Zadrżą przed nim bożki Egiptu, a serce Egiptu stopnieje w jego wnętrzu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 2, 'Podburzę Egipcjan przeciw Egipcjanom, tak że każdy będzie walczyć przeciwko swemu bratu i każdy przeciwko swemu bliźniemu, miasto przeciwko miastu, królestwo przeciwko królestwu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 3, 'I osłabnie duch Egiptu, a jego zamiar obrócę wniwecz. I będą się radzić bożków i zaklinaczy, czarowników i wróżbitów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 4, 'I wydam Egipcjan w ręce okrutnego pana, a srogi król będzie panować nad nimi, mówi Pan, Pan zastępów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 5, 'I zginą wody z morza, a rzeka opadnie i wyschnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 6, 'Ustaną rzeki, opadną i powysychają potoki ujęte groblami, a trzcina i sitowie powiędną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 7, 'Trawa przy brzegach potoków i przy ich ujściu oraz wszelki zasiew przy potokach wyschną i wyginą, i już ich nie będzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 8, 'Rybacy będą się smucić, będą lamentować wszyscy, którzy w rzece zarzucają wędkę, i ci, którzy rozciągają sieci na wodzie, będą rozpaczać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 9, 'Zawiedzeni będą też ci, którzy uprawiają wyborny len, i ci, którzy tkają sieci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 10, 'Będą przygnębieni swoim losem wszyscy, którzy robią stawy do hodowli ryb.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 11, 'Doprawdy, książęta Soanu są głupcami, zgłupiała rada mądrych doradców faraona. Jak możecie mówić do faraona: Jestem synem mędrców, synem starożytnych królów?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 12, 'Gdzie teraz są twoi mędrcy? Niech ci teraz oznajmią, jeśli wiedzą, co Pan zastępów postanowił wobec Egiptu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 13, 'Zgłupieli książęta Soanu, zwiedzeni są książęta Nof; zwiedli Egipt naczelnicy jego rodów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 14, 'Pan umieścił pośród nich wypaczonego ducha, a oni sprawili, że Egipt zbłądził w każdej swojej sprawie, tak jak błądzi wymiotujący pijak.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 15, 'I nie będzie żadnego dzieła w Egipcie, którego będą mogły dokonać głowa lub ogon, gałąź lub sitowie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 16, 'W tym dniu Egipt będzie podobny do kobiet, bo będzie się lękać i drżeć przed ręką Pana zastępów, którą podniesie przeciwko niemu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 17, 'Ziemia Judy stanie się postrachem dla Egiptu. Każdy, kto o niej wspomni, będzie się lękał z powodu zamiaru, który powziął przeciwko niemu Pan zastępów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 18, 'W tym dniu w ziemi Egiptu będzie pięć miast mówiących językiem Kanaanu i przysięgających na Pana zastępów, a jedno z nich będzie nazwane Miastem Spustoszenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 19, 'W tym dniu będzie ołtarz dla Pana pośród ziemi Egiptu i słup dla Pana przy jego granicy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 20, 'I będzie to znakiem i świadectwem dla Pana zastępów w ziemi Egiptu. A gdy zawołają do Pana z powodu ciemięzców, pośle im zbawiciela i księcia, który ich wybawi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 21, 'I Pan będzie znany w Egipcie, gdyż Egipcjanie tego dnia poznają Pana i będą składać mu ofiary i dary, będą składać Panu śluby i wypełnią je.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 22, 'A Pan uderzy Egipt, uderzy go i uzdrowi. Oni nawrócą się do Pana, a on da się im ubłagać i uzdrowi ich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 23, 'W tym dniu będzie droga z Egiptu do Asyrii i Asyryjczyk będzie chodzić do Egiptu, a Egipcjanin do Asyrii, i Egipcjanie będą służyć z Asyryjczykami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 24, 'W tym dniu Izrael będzie jako trzeci wraz z Egiptem i Asyrią, będzie błogosławieństwem pośrodku ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 25, 'Pan zastępów bowiem będzie im błogosławił: Niech będzie błogosławiony mój lud Egipt i Asyria, dzieło moich rąk, oraz Izrael, moje dziedzictwo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 1, 'W roku, w którym Tartan przybył do Aszdodu, wysłany tam przez Sargona, króla Asyrii, walczył przeciw Aszdodu i go zdobył;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 2, 'W tym czasie Pan powiedział przez Izajasza, syna Amosa: Idź, zdejmij wór ze swych bioder i obuwie ze swoich nóg. I uczynił tak, chodząc nago i boso.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 3, 'I Pan powiedział: Jak mój sługa Izajasz chodzi nago i boso przez trzy lata jako znak i cud dla Egiptu i Etiopii;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 4, 'Tak król Asyrii uprowadzi więźniów Egiptu i jeńców Etiopii, młodych i starych, nagich i bosych, z obnażonymi pośladkami, na pohańbienie Egiptu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 5, 'I przestraszą się, i zawstydzą z powodu Etiopii, ich nadziei, i z powodu Egiptu, ich chluby.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 6, 'Tego dnia mieszkaniec tej wyspy powie: Oto co się stało z naszą nadzieją, do której uciekliśmy się o pomoc, abyśmy zostali wyzwoleni od króla Asyrii. A teraz jak zdołamy ujść cało?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 1, 'Brzemię pustynnego morza. Jak wicher na południe nadciąga, tak przyjdzie z pustyni, ze strasznej ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 2, 'Srogie widzenie jest mi pokazane. Zdrajca zdradza, niszczyciel niszczy. Nadciągnij, Elamie! Oblegaj, Medio! Położę kres wszelkiemu wzdychaniu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 3, 'Dlatego moje biodra są wypełnione bólem, ogarnęły mnie skurcze jak skurcze rodzącej. Wstrząśnięty jestem tym, co słyszę, przerażony tym, co widzę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 4, 'Zlękło się moje serce, strach mnie ogarnął. Noc moich rozkoszy zamieniła się w postrach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 5, 'Przygotuj stół, niech strażnik trzyma straż; jedz, pij. Wstańcie, książęta, namaszczajcie tarcze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 6, 'Tak bowiem powiedział mi Pan: Idź, postaw strażnika, niech mówi, co widzi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 7, 'I zobaczył rydwan z dwoma jeźdźcami, który ciągnęły osły, i rydwan, który ciągnęły wielbłądy; i przypatrywał się im z wielką uwagą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 8, 'Wtedy zawołał jak lew: Panie mój! Stoję ciągle za dnia na wieży strażniczej; stoję na warcie całymi nocami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 9, 'A oto nadciągają mężczyźni na rydwanie z dwoma jeźdźcami. I zawołał: Upadł, upadł Babilon i wszystkie rzeźbione posągi jego bogów roztrzaskane zostały o ziemię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 10, 'O moi wymłóceni i zboże mego klepiska! Co usłyszałem od Pana zastępów, Boga Izraela, to wam oznajmiłem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 11, 'Brzemię Dumy. Z Seiru ktoś woła do mnie: Strażniku, co się stało w nocy? Strażniku, co się stało w nocy?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 12, 'Strażnik odpowiedział: Nadchodzi poranek, a także noc. Jeśli chcecie dopytywać, dopytujcie, nawróćcie się, przyjdźcie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 13, 'Brzemię na Arabię. W lasach Arabii będziecie nocować, wy, karawany Dedanitów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 14, 'Niech mieszkańcy Tema wyjdą z wodą naprzeciw spragnionych, ze swoim chlebem niech wyjdą na spotkanie uciekającym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 15, 'Będą bowiem uciekali przed mieczami, przed dobytym mieczem, przed napiętym łukiem, przed ciężką bitwą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 16, 'Gdyż tak Pan powiedział do mnie: Za rok, liczony jak rok najemnika, ustanie cała chwała Kedaru.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 17, 'A reszta spośród łuczników, dzielni wojownicy spośród synów Kedaru, będzie zmniejszona. Tak bowiem powiedział Pan, Bóg Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 1, 'Brzemię Doliny Widzenia. Co ci się stało, że cała wystąpiłaś na dachy?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 2, 'Miasto pełne wrzasku i zgiełku, miasto wesołe! Twoi zabici nie padli od miecza ani nie zginęli w bitwie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 3, 'Wszyscy twoi dowódcy pierzchli razem, związani przez łuczników. Zostali związani razem ci, których znaleziono u ciebie, ci, którzy uciekli z daleka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 4, 'Dlatego powiedziałem: Odwróćcie swój wzrok ode mnie, abym gorzko zapłakał; nie próbujcie mnie pocieszać z powodu spustoszenia córki mojego ludu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 5, 'To jest bowiem dzień ucisku, deptania i zamieszania od Pana, Boga zastępów, w Dolinie Widzenia, dzień burzenia murów i wołania na góry.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 6, 'Elam wziął kołczan z rydwanami ludu wojennego, a Kir odsłonił swoją tarczę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 7, 'I stało się tak, że najpiękniejsze doliny były pełne rydwanów, a jeźdźcy ustawili się potężnie przy bramie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 8, 'I odkryto osłonę Judy, i w tym dniu spoglądałeś na zbrojownię w Domu Lasu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 9, 'I spoglądaliście na wyłomy miasta Dawida – na to, że były liczne, i zgromadziliście wody Dolnej Sadzawki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 10, 'Policzyliście domy w Jerozolimie i burzyliście domy, aby wzmocnić mur.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 11, 'Zrobiliście też zbiornik między dwoma murami na wodę Starej Sadzawki, ale nie spoglądaliście na jej twórcę ani nie widzieliście tego, który od dawna ją ukształtował.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 12, 'W tym dniu Pan, Bóg zastępów, wzywał do płaczu i do żałoby, do ostrzyżenia się i do przepasania się worem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 13, 'A oto radość i wesele, zabijanie wołów i owiec, spożywanie mięsa i picie wina: Jedzmy, pijmy, bo jutro umrzemy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 14, 'Ale Pan zastępów objawił mi to, mówiąc do mych uszu: Na pewno ta nieprawość nie będzie wam przebaczona aż do śmierci, mówi Pan, Bóg zastępów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 15, 'Tak mówi Pan, Bóg zastępów: Idź, udaj się do tego skarbnika, do Szebny, przełożonego domu, i powiedz:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 16, 'Co ty tu masz i kogo tu masz, że wykułeś sobie w tym miejscu grób? Wykułeś sobie grób wysoko, wydrążyłeś sobie w skale swoje mieszkanie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 17, 'Oto Pan, który cię przykrył jak zacnego człowieka i który cię kosztownie przyoblekł;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 18, 'Tocząc cię, zwinie i rzuci jak kulę w przestronną ziemię. Tam umrzesz, tam też rydwany twojej chwały będą hańbą domu twego pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 19, 'Wypędzę cię z twego stanowiska, z twego urzędu ściągnę cię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 20, 'W tym dniu powołam swego sługę Eliakima, syna Chilkiasza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 21, 'I ubiorę go w twoją szatę, i przepaszę go twoim pasem, i oddam w jego ręce twoją władzę; i będzie on ojcem dla mieszkańców Jerozolimy i domu Judy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 22, 'I położę klucz domu Dawida na jego ramieniu; gdy on otworzy, nikt nie zamknie, a gdy zamknie, nikt nie otworzy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 23, 'I wbiję go jak gwóźdź na miejscu pewnym, a będzie tronem chwały dla domu swego ojca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 24, 'I zawieszą na nim cała chwała domu jego ojca, synowie i córki, wszelkie drobne naczynia, od kubków do wszelkich dzbanów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 25, 'W tym dniu, mówi Pan zastępów, gwóźdź, który był wbity w miejscu pewnym, zostanie wyjęty i przycięty, i spadnie; a brzemię, które wisiało na nim, zostanie odcięte. Tak bowiem Pan to powiedział.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 1, 'Brzemię Tyru. Zawódźcie, okręty Tarszisz, bo został zburzony tak, że nie ma ani domu, ani żadnego portu; oznajmiono im z ziemi Kittim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 2, 'Zamilczcie, mieszkańcy wyspy; którą napełnili kupcy Sydonu, przepływając przez morze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 3, 'I ziarno Szichoru, sprowadzane przez wielkie wody, żniwo rzeki, było jego dochodem; był też rynkiem narodów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 4, 'Wstydź się, Sydonie. Przemówiło bowiem morze, przemówiła twierdza morska: Nie wiję się w bólu ani nie rodzę, nie wychowuję młodzieńców ani nie odchowuję dziewic.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 5, 'Jak na wieść o Egipcie tak będą się wić na wieść o Tyrze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 6, 'Przeprawcie się do Tarszisz, zawódźcie, mieszkańcy wyspy!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 7, 'Czy to jest wasze wesołe miasto, którego historia sięga dawnych dni? Jego własne nogi zawiodą je na daleką wędrówkę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 8, 'Kto powziął takie postanowienie przeciw Tyrowi, który rozdawał korony, którego kupcy są książętami, a jego handlarze – szanowanymi ziemi?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 9, 'Pan zastępów to postanowił, aby poniżyć pychę całej jego chwały i aby znieważyć wszystkich szanowanych ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 10, 'Przeprawcie się przez swoją ziemię jak rzeka, o córko Tarszisz. Nie ma już siły.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 11, 'Wyciągnął swoją rękę nad morze, zatrząsnął królestwami. Pan wydał rozkaz przeciwko Kanaanowi, aby zburzyć jego twierdze;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 12, 'I powiedział: Już nie będziesz się weselić, ty zhańbiona dziewico, córko Syjonu. Powstań, przepraw się do Kittim; lecz i tam nie będziesz miała odpoczynku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 13, 'Oto ziemia Chaldejczyków – ten lud nie był ludem. Asyryjczyk założył ją dla mieszkańców pustyni. Wznieśli jej wieże, pobudowali jej pałace, ale on obrócił ją w gruzy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 14, 'Zawódźcie, okręty Tarszisz, gdyż wasza twierdza jest zburzona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 15, 'I stanie się w tym dniu, że Tyr pójdzie w zapomnienie na siedemdziesiąt lat, na okres dni jednego króla. A po upływie siedemdziesięciu lat Tyr będzie śpiewał jak nierządnica.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 16, 'Weź harfę, obejdź miasto, zapomniana nierządnico! Graj ładnie, śpiewaj dużo, by przypomniano sobie ciebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 17, 'I stanie się po upływie siedemdziesięciu lat, że Pan nawiedzi Tyr, a ten wróci do czerpania korzyści ze swego nierządu i będzie go uprawiał ze wszystkimi królestwami świata na powierzchni ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 18, 'Lecz jego dochody i jego zysk będą poświęcone Panu. Nie będzie ich odkładać i gromadzić. Jego dochody będą dla tych, którzy przebywają przed Panem, aby mogli jeść do syta i mieć dobre ubranie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 1, 'Oto Pan opróżni ziemię i spustoszy ją, odmieni jej oblicze i rozproszy jej mieszkańców.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 2, 'I będzie z ludem jak z kapłanem, ze sługą jak z jego panem, ze służącą jak z jej panią, z kupującym jak ze sprzedającym, z udzielającym pożyczki jak z biorącym jej, z lichwiarzem jak z płacącym lichwę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 3, 'Ziemia zostanie całkowicie opróżniona i doszczętnie ograbiona, bo Pan wypowiedział to słowo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 4, 'Ziemia płacze i więdnie, świat marnieje i niszczeje, marnieją wyniosłe ludy ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 5, 'Ziemia jest splugawiona pod swoimi mieszkańcami; przekroczyli bowiem prawa, zmienili ustawy, złamali wieczne przymierze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 6, 'Dlatego przekleństwo pożre ziemię, a jej mieszkańcy zniszczeją. Dlatego mieszkańcy ziemi są przypaleni, a zostało mało ludzi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 7, 'Młode wino smuci się, winorośl marnieje, wzdychają wszyscy ludzie wesołego serca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 8, 'Ustała wesołość bębnów, skończył się krzyk weselących się, ucichł radosny dźwięk harfy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 9, 'Nie będą pić wina wśród pieśni; zgorzknieje mocny napój tym, którzy go piją.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 10, 'Zburzone jest miasto bezładu. Zamknięty jest każdy dom, tak że wejść nie można.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 11, 'Na ulicach wołanie o wino; zgasła wszelka radość, a wesołość ziemi odeszła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 12, 'W mieście pozostało spustoszenie, a bramy zburzone.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 13, 'Tak bowiem będzie pośród ziemi, pośród ludu, jak przy otrząsaniu drzewa oliwnego, jak ostatki winogron po winobraniu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 14, 'Tamci poniosą swój głos, będą śpiewać dla majestatu Pana, wykrzykną od strony morza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 15, 'Dlatego wysławiajcie Pana w dolinach, na wyspach morskich – imię Pana, Boga Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 16, 'Od krańców ziemi słyszeliśmy pieśni o chwale sprawiedliwego. Ale ja powiedziałem: Jestem wynędzniały, jestem wynędzniały, biada mi! Zdrajcy zdradzili, tak, bardzo zdradzili zdrajcy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 17, 'Strach, dół i sidła na ciebie, mieszkańcu ziemi!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 18, 'I stanie się, że kto ucieknie przed głosem strachu, wpadnie w dół, a kto wyjdzie z dołu, będzie złapany w sidłach. Otworzą się bowiem upusty w górze i zadrżą fundamenty ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 19, 'Ziemia rozpadła się całkowicie, ziemia rozpłynęła się doszczętnie; jest wielce wstrząśnięta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 20, 'Ziemia będzie się słaniać jak pijany, będzie chwiać się jak lepianka. Zaciąży na niej jej nieprawość i upadnie, a już nie powstanie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 21, 'W tym dniu Pan nawiedzi zastęp wysokich na wysokości, także i królów ziemskich na ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 22, 'I będą zgromadzeni jak więźniowie zebrani w ciemnicy, i będą zamknięci w więzieniu, a po wielu dniach zostaną nawiedzeni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 23, 'Wtedy księżyc zarumieni się i słońce się zawstydzi, gdy Pan zastępów będzie królować na górze Syjon, w Jerozolimie, i wobec swoich starszych w swej wielkiej chwale.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 1, 'Panie, ty jesteś moim Bogiem; będę cię wywyższać i wysławiać twoje imię, bo uczyniłeś cudowne rzeczy; twoje postanowienia, z dawna powzięte, są wiernością i prawdą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 2, 'Bo obróciłeś miasto w rumowisko, miasto obronne w ruiny. Pałac cudzoziemców przestał być miastem, nigdy nie będzie odbudowany.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 3, 'Dlatego będzie cię wielbić lud mocny; miasto okrutnych narodów będzie się ciebie bać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 4, 'Ty bowiem jesteś twierdzą dla ubogiego, twierdzą dla nędzarza w jego ucisku, ucieczką przed powodzią, zasłoną przed upałem, gdy wściekłość okrutników jest jak powódź bijąca w ścianę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 5, 'Wrzawę cudzoziemców stłumisz jak upał na wysuszonej ziemi, jak upał – cieniem obłoku. Okrucieństwo okrutników będzie poniżone.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 6, 'Na tej górze Pan zastępów wyprawi wszystkim ludom ucztę z tłustych potraw, ucztę z wystałego wina, z tłustych potraw ze szpikiem, z wina wystałego i czystego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 7, 'I zniszczy na tej górze zasłonę rozpostartą nad wszystkimi ludźmi i przykrycie rozciągnięte nad wszystkimi narodami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 8, 'Połknie śmierć w zwycięstwie, a Pan Bóg otrze łzy z każdego oblicza i zdejmie z całej ziemi hańbę swego ludu, bo tak Pan powiedział.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 9, 'I w tym dniu będzie się mówić: Oto nasz Bóg, jego oczekiwaliśmy i on nas wybawi. To jest Pan, jego oczekiwaliśmy; będziemy się weselić i radować z jego zbawienia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 10, 'Na tej górze bowiem spocznie ręka Pana, a Moab będzie zdeptany przez niego, jak depcze się słomę na gnojowisku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 11, 'I rozciągnie swoje ręce pośrodku niego, jak je rozciąga pływak, by pływać, i poniży jego wyniosłość wraz z wysiłkami jego rąk.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 12, 'A twoje wysokie mury obronne obali, zburzy i zrzuci na ziemię – obróci je w proch.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 1, 'W tym dniu śpiewana będzie taka pieśń w ziemi Judy: Mamy miasto obronne, Bóg zaopatrzy je w zbawienie jako mur i wały obronne.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 2, 'Otwórzcie bramy, niech wejdzie naród sprawiedliwy, który strzeże prawdy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 3, 'Człowieka polegającego na tobie zachowujesz w doskonałym pokoju, bo tobie ufa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 4, 'Pokładajcie nadzieję w Panu na wieki, bo Jehowa Bóg jest wieczną skałą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 5, 'On bowiem poniża tych, którzy mieszkają wysoko; burzy miasto wyniosłe, burzy je aż do ziemi, i strąca aż do prochu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 6, 'Depcze je noga; nogi ubogiego, stopy nędzarzy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 7, 'Ścieżka sprawiedliwego jest prosta; wyrównujesz prostą drogę sprawiedliwego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 8, 'Na drodze twoich sądów, o Panie, oczekujemy cię; pragnieniem naszej duszy jest twoje imię i wspominanie ciebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 9, 'Moja dusza pragnie cię w nocy; swoim duchem, który jest we mnie, szukam cię nawet rano. Gdy bowiem twoje sądy odbywają się na ziemi, mieszkańcy świata uczą się sprawiedliwości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 10, 'Choć niegodziwemu okaże się łaskę, nie nauczy się sprawiedliwości. W ziemi prawości będzie czynić nieprawość i nie będzie zważać na majestat Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 11, 'Panie, choć twoja ręka jest wywyższona, oni jednak tego nie widzą. Ale ujrzą i będą zawstydzeni z powodu ich zazdrości wobec twego ludu; ponadto ogień twoich wrogów pożre ich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 12, 'Panie, zaprowadzisz nam pokój, bo wszystko, co się działo przy nas, czyniłeś ku naszemu dobru.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 13, 'Panie, nasz Boże, panowali nad nami inni panowie niż ty, ale my, ufając tylko tobie, wspominamy twoje imię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 14, 'Umarli oni i nie ożyją, są martwi i nie powstaną, ponieważ nawiedziłeś ich i wytępiłeś, i zgładziłeś wszelką pamięć o nich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 15, 'Rozmnożyłeś naród, Panie, rozmnożyłeś naród. Jesteś uwielbiony, choć go wypędziłeś na wszystkie krańce ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 16, 'Panie, w ucisku ciebie szukali; gdy ich karałeś, wylewali swoje modlitwy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 17, 'Jak brzemienna, gdy zbliża się poród, odczuwa ból i woła w boleściach, takimi byliśmy przed tobą, Panie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 18, 'Poczęliśmy, wiliśmy się z bólu, ale zrodziliśmy jakby tylko wiatr; żadnego wybawienia nie dokonaliśmy na ziemi i nie upadli mieszkańcy świata.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 19, 'Twoi umarli ożyją, wraz z moim trupem powstaną. Ocućcie się i śpiewajcie, wy, którzy spoczywacie w prochu! Twoja rosa bowiem będzie jak rosa na ziołach, a ziemia wyda umarłych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 20, 'Chodź, mój ludu! Wejdź do swoich komnat i zamknij swoje drzwi za sobą. Skryj się na krótką chwilę, aż gniew przeminie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 21, 'Oto bowiem Pan wychodzi ze swojego miejsca, aby nawiedzić nieprawość mieszkańców ziemi. Wtedy ziemia ujawni swoją krew i nie będzie już ukrywać swoich zabitych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 1, 'W tym dniu Pan ukarze swoim mieczem srogim, wielkim i mocnym Lewiatana, węża długiego, Lewiatana, węża skręconego, i zabije smoka, który jest w morzu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 2, 'Tego dnia śpiewajcie o winnicy wybornego wina.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 3, 'Ja, Pan, który jej strzeże, co chwila będę ją podlewać i żeby nikt jej nie zniszczył, będę jej strzegł nocą i dniem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 4, 'Nie ma we mnie żadnej zapalczywości. Kto wystawi osty i ciernie do walki ze mną, abym z nimi walczył? Spaliłbym je do szczętu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 5, 'Niech raczej uchwyci moją siłę, aby zawrzeć ze mną pokój, a pokój ze mną uczyni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 6, 'Przyjdzie dzień, gdy Jakub się rozkorzeni, Izrael zakwitnie, puści pędy i napełni powierzchnię ziemi owocem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 7, 'Czy uderzył go, jak uderzył jego wroga? Czy zabito go, jak inni zostali zabici przez niego?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 8, 'Z umiarem go ukarze, bo gdy ten wypuści gałązki, zabierze go swoim gwałtownym wiatrem w dniu wschodniego wichru.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 9, 'Dlatego w ten sposób będzie oczyszczona nieprawość Jakuba; a taki będzie wszelki owoc usunięcia jego grzechu: rozrzuci wszystkie kamienie ołtarza, jak rozbija się kamienie wapienne, a nie będą już stać gaje i posągi słoneczne.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 10, 'Gdyż miasto obronne opustoszeje, a będzie mieszkaniem porzuconym i opuszczonym jak pustynia. Tam cielec będzie się paść, tam będzie leżeć i ogryzać jego gałązki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 11, 'Gdy jego gałązki uschną, będą się odłamywać; przyjdą kobiety i spalą je. Ten lud bowiem nie ma żadnego rozumu; dlatego ten, który go uczynił, nie zlituje się nad nim, a ten, który go stworzył, nie okaże mu żadnej łaski.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 12, 'Tego dnia Pan będzie młócił od koryta rzeki do potoku Egiptu; i wy, synowie Izraela, będziecie zbierani jeden po drugim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 13, 'I stanie się też w tym dniu, że zadmą w wielką trąbę i przyjdą zaginieni w ziemi Asyrii oraz ci, którzy byli wygnani do ziemi Egiptu; i będą oddawać pokłon Panu na świętej górze w Jerozolimie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 1, 'Biada koronie pychy, pijakom Efraima, których wspaniała ozdoba jest więdnącym kwiatem rosnącym na szczycie urodzajnych dolin odurzonych winem!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 2, 'Oto ktoś od Pana, mocny i silny, jak burza gradowa, jak niszcząca nawałnica, jak ulewa gwałtownych rwących wód, rzuci ją na ziemię swoją ręką.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 3, 'Zostanie zdeptana nogami korona pychy, pijacy Efraima.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 4, 'A wspaniała ozdoba, która jest na szczycie urodzajnej doliny, będzie więdnącym kwiatem jak przed latem wczesny owoc; kto go tylko zobaczy, weźmie do ręki i zje.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 5, 'W tym dniu Pan zastępów będzie koroną chwały i diademem ozdoby dla resztki swojego ludu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 6, 'Duchem sądu dla zasiadającego w sądzie i mocą dla tych, którzy odpierają atak aż do bramy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 7, 'Ale również ci od wina błądzą i od mocnego napoju zataczają się. Kapłan i prorok błądzą od mocnego napoju, utonęli w winie, zataczają się od mocnego napoju, błądzą w widzeniach, potykają się w sądzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 8, 'Wszystkie ich stoły bowiem są pełne wymiotów i plugastwa, tak że nie ma czystego miejsca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 9, 'Kogo ma uczyć poznania? Komu ma wyjaśnić naukę? Czyż odstawionym od mleka i odłożonym od piersi?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 10, 'Ponieważ podaje się przykazanie za przykazaniem, przykazanie za przykazaniem, przepis za przepisem, przepis za przepisem, trochę tu, trochę tam.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 11, 'Bo wargami jąkających się i obcym językiem będę mówił do tego ludu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 12, 'A gdy im powiedział: To jest odpoczynek, dajcie odpocząć spracowanemu; to jest wytchnienie. Ale oni nie chcieli słuchać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 13, 'I słowo Pana będzie im: przykazanie za przykazaniem, przykazanie za przykazaniem, przepis za przepisem, przepis za przepisem, trochę tu, trochę tam, po to, aby szli, padli na wznak i rozbili się, aby zostali uwikłani i pojmani.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 14, 'Dlatego słuchajcie słowa Pana, wy, mężowie szyderczy, panujący nad tym ludem, który jest w Jerozolimie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 15, 'Ponieważ mówicie: Zawarliśmy przymierze ze śmiercią i z piekłem mamy układ; gdy przejdzie bicz gwałtowny, nie dosięgnie nas, gdyż kłamstwo uczyniliśmy naszą ucieczką i skryliśmy się za fałszem;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 16, 'Dlatego tak powiedział Pan Bóg: Oto kładę jako grunt na Syjonie kamień, kamień wypróbowany, węgielny, drogocenny, utwierdzony fundament. Kto uwierzy, nie pospieszy się.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 17, 'A wykonam sąd według sznura, a sprawiedliwość według pionu. I grad zmiecie schronienie kłamstw, a wody zaleją kryjówkę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 18, 'Wasze przymierze ze śmiercią zostanie zerwane, a wasz układ z piekłem nie ostoi się; gdy ten bicz gwałtowny przejdzie, zostaniecie przez niego zdeptani.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 19, 'Jak tylko zacznie przechodzić, pochwyci was, bo każdego poranka będzie przechodzić, dniem i nocą. Sam tylko postrach zaprowadzi was do zrozumienia tego, co słyszeliście;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 20, 'Bo łóżko będzie za krótkie, aby się na nim rozciągnąć, przykrycie zbyt wąskie, by się nim owinąć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 21, 'Pan bowiem powstanie jak na górze Perazym i rozgniewa się jak w dolinie Gibeon, aby dokonać swego dzieła, swego niezwykłego dzieła, aby dokończyć swoje zadanie, swoje niezwykłe zadanie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 22, 'Teraz więc nie naśmiewajcie się, aby wasze węzły nie zacisnęły się mocniej, gdyż słyszałem od Pana, Boga zastępów, że postanowione jest zniszczenie na całej ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 23, 'Nadstawcie uszu, posłuchajcie mego głosu; bądźcie uważni, słuchajcie mojej mowy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 24, 'Czyż oracz codziennie orze, aby siać? Czy robi bruzdy i bronuje swoją rolę?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 25, 'Czyż gdy wyrówna jej powierzchnię, nie rozsiewa czarnuszki, nie rozsiewa kminu i nie obsiewa pszenicą wyborną, jęczmieniem przednim i orkiszem w odpowiednich miejscach?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 26, 'Jego Bóg uczy go roztropności i poucza go.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 27, 'Czarnuszki bowiem nie młóci się saniami młockarskimi ani nie przetacza się koła wozu po kminku; ale kijem wybija się czarnuszkę, a kminek – laską.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 28, 'Pszenicę młóci się, ale nie bez końca, i nie pociera jej kołem wozu ani jej nie kruszy zaprzęgiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 29, 'I to także pochodzi od Pana zastępów, który jest cudowny w radzie i wielki w działaniu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 1, 'Biada Arielu, Arielu, miasto, w którym mieszkał Dawid. Dodawajcie rok do roku, niech zarzynają barany.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 2, 'Ześlę jednak ucisk na Ariela i nastanie smutek i lament, i będzie mi jak Ariel.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 3, 'Rozbiję obóz przeciwko tobie dokoła, otoczę cię wałami i wzniosę przeciwko tobie baszty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 4, 'Wtedy poniżony będziesz mówił z ziemi, z prochu ledwie wyjdzie twoja mowa i twój głos będzie mówił z ziemi jak głos czarownika, a twoja mowa z prochu jak szept.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 5, 'Mnóstwo twoich wrogów będzie jak drobny pył, a zgraja okrutników jak rozwiane plewy. A stanie się to nagle, w okamgnieniu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 6, 'Zostaniesz nawiedzony od Pana zastępów grzmotem, trzęsieniem ziemi i wielkim hukiem, wichurą, burzą i płomieniem trawiącego ognia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 7, 'Jak sen nocnego widzenia będzie zgraja wszystkich narodów walczących przeciwko Arielowi i wszystkich, którzy walczą przeciwko niemu i jego twierdzom, oraz tych, którzy go uciskają.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 8, 'Będzie tak jak wtedy, gdy śni się głodnemu, że je, ale gdy się obudzi, ma pusty żołądek; i jak wtedy, gdy śni się spragnionemu, że pije, a gdy się obudzi, nadal jest słaby i jego dusza jest spragniona. Tak będzie ze zgrają wszystkich narodów walczących przeciwko górze Syjon.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 9, 'Zatrzymujcie się i zdumiewajcie; rozkoszujcie, choćbyście mieli wołać na pomoc. Upili się, ale nie winem; zataczają się, ale nie od mocnego napoju.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 10, 'Pan bowiem wylał na was ducha twardego snu i zamknął wasze oczy. Oczy waszych proroków i książąt, widzących, zasłonił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 11, 'Dlatego całe to widzenie stało się dla was jak słowa zapieczętowanej księgi, którą podaje się temu, kto umie czytać, mówiąc: Przeczytaj to, proszę, na co odpowiada: Nie mogę, bo jest zapieczętowana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 12, 'A jeśli podaje się księgę temu, kto nie umie czytać, mówiąc: Czytaj to, proszę, ten wtedy odpowiada: Nie umiem czytać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 13, 'Mówi więc Pan: Ponieważ ten lud zbliża się do mnie swymi ustami i czci mnie swymi wargami, a jego serce jest daleko ode mnie i jego bojaźń wobec mnie jest wyuczoną przez nakazy ludzi;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 14, 'Dlatego ja będę postępował przedziwnie z tym ludem, przedziwnie i cudownie; zginie mądrość jego mądrych, a rozum jego roztropnych się skryje.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 15, 'Biada tym, którzy głęboko przed Panem ukrywają swój zamysł, których czyny są popełnione w ciemności i mówią: Kto nas widzi? Kto o nas wie?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 16, 'Wasze przewrotne myśli są jak glina garncarska. Czyż glina powie o tym, co ją uczynił: Nie uczynił mnie? Czyż to, co ulepione, powie o tym, co je ulepił: Nie miał rozumu?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 17, 'Czyż nie w bardzo krótkim czasie Liban obróci się w pole, a pole będzie uważane za las?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 18, 'Tego dnia głusi usłyszą słowa księgi, a oczy ślepych przejrzą z mroku i ciemności.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 19, 'Cisi jeszcze bardziej się rozweselą w Panu, a ubodzy spośród ludzi rozradują się w Świętym Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 20, 'Gdyż nastanie kres dla okrutnika, zniszczeje szyderca i zostaną wytępieni wszyscy, którzy czyhają na nieprawość;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 21, 'Którzy obwiniają człowieka za słowo, zastawiają sidło na tego, który ich strofuje w bramie, i bez powodu doprowadzają sprawiedliwego do upadku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 22, 'Dlatego tak mówi Pan, który odkupił Abrahama, o domu Jakuba: Jakub już więcej nie zazna wstydu ani jego twarz już nie zblednie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 23, 'Gdy bowiem ujrzy pośród siebie swoich synów, dzieło moich rąk, poświęcą moje imię, poświęcą Świętego Jakuba, i będą się bać Boga Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 24, 'Ci, którzy błądzili duchem, nabiorą rozumu, ci, którzy szemrali, przyjmą naukę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 1, 'Biada upartym synom, mówi Pan, którzy naradzają się, ale nie ze mną, i zasłaniają nakryciem, ale nie z mojego ducha, aby dodawać grzech do grzechu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 2, 'Którzy wyruszają, by zejść do Egiptu, nie radząc się moich ust, aby umocnić się siłą faraona i schronić się w cieniu Egiptu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 3, 'Dlatego siła faraona będzie dla was zawstydzeniem, a schronienie w cieniu Egiptu waszą hańbą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 4, 'Jego książęta bowiem byli w Soan i jego posłowie dotarli do Chanes.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 5, 'Wszyscy zawstydzili się przez lud, który nie był dla nich użyteczny ani pomocny i nie przynosił żadnych korzyści, lecz tylko wstyd i hańbę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 6, 'Brzemię zwierząt południa. Do ziemi ucisku i utrapienia, skąd pochodzi lew i lwiątko, żmija i ognisty smok latający, zaniosą swoje bogactwa na grzbietach osłów i swe skarby na garbach wielbłądów do ludu, który im nic nie pomoże;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 7, 'Bo pomoc Egipcjan będzie daremna i próżna. Dlatego ogłaszam, że ich siłą jest siedzieć w pokoju.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 8, 'Teraz idź, napisz to na tablicy przy nich i utrwal w księdze, aby zostało to zachowane na przyszłość i aż na wieki wieków:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 9, 'Że ten lud jest uparty, że to synowie kłamliwi, synowie, którzy nie chcą słuchać prawa Pana;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 10, 'Którzy mówią do widzących: Nie miejcie widzenia; a prorokom: Nie prorokujcie nam, co jest prawe; mówcie nam rzeczy przyjemne, prorokujcie oszustwa;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 11, 'Zejdźcie z drogi, zejdźcie ze ścieżki, zabierzcie sprzed nas Świętego Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 12, 'Dlatego tak mówi Święty Izraela: Ponieważ gardzicie tym słowem, a pokładacie ufność w krzywdzie i przewrotności i na nich polegacie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 13, 'Dlatego ta nieprawość będzie dla was jak pęknięcie grożące zawaleniem i jak wygięcie na wysokim murze, który zawala się nagle, w mgnieniu oka;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 14, 'I rozbije ją, jak rozbija się gliniane naczynie stłuczone tak bezlitośnie, że nie znajdzie się wśród jego odłamków skorupki, aby nabrać ognia z ogniska lub zaczerpnąć wody ze zbiornika.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 15, 'Tak bowiem mówi Pan Bóg, Święty Izraela: W nawróceniu i spokoju będziecie zbawieni; w ciszy i ufności będzie wasza siła. Ale nie chcieliście;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 16, 'Przeciwnie, powiedzieliście: Nie tak, ale na koniach uciekniemy! Dlatego będziecie uciekać. Na szybkich koniach pojedziemy! Dlatego będą szybsi ci, którzy będą was ścigać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 17, 'Tysiąc was ucieknie przed groźbą jednego, a przed groźbą pięciu wszyscy uciekniecie, aż zostaniecie jak maszt na szczycie góry i jak sztandar na pagórku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 18, 'I dlatego Pan będzie czekać, aby okazać wam łaskę, i dlatego będzie wywyższony, aby się zlitować nad wami. Pan bowiem jest Bogiem sądu. Błogosławieni wszyscy, którzy na niego czekają.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 19, 'Lud bowiem będzie mieszkał na Syjonie, w Jerozolimie, nie będziesz już płakał. Na pewno zlituje się nad tobą na głos twego wołania, a gdy tylko cię usłyszy, odezwie się.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 20, 'A choć Pan dał wam chleb niedoli i wodę ucisku, to jednak twoi nauczyciele nie będą już usunięci, ale twoje oczy zobaczą twoich nauczycieli;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 21, 'Twoje uszy usłyszą słowo wołające za tobą: To jest droga, chodźcie nią – gdybyście zboczyli na prawo lub na lewo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 22, 'Wtedy uznasz za nieczyste obicie swoich rzeźbionych posągów ze srebra i odzienie swoich odlanych posągów ze złota. Wyrzucisz je jako nieczystość miesiączkującej kobiety i powiesz im: Precz stąd.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 23, 'Bóg ześle deszcz na twój siew, którym obsiewasz ziemię, i chleb z plonów ziemi będzie syty i obfity. W tym dniu twoje bydło będzie się pasło na rozległych pastwiskach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 24, 'Także woły i osły uprawiające ziemię będą się karmić czystą paszą, która została przesiana wiejadłem i szuflą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 25, 'Na każdej wysokiej górze i na każdym wyniosłym pagórku będą strumienie i potoki wód, w dniu wielkiej rzezi, gdy wieże upadną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 26, 'Światło księżyca będzie jak światło słońca, światło słońca będzie siedmiokrotnie jaśniejsze, jakby światło siedmiu dni – w dniu, kiedy Pan obwiąże złamanie swego ludu i uleczy zadaną mu ranę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 27, 'Oto imię Pana przybywa z daleka, jego gniew płonie, jego brzemię ciężkie. Jego wargi są pełne gniewu, a jego język jak trawiący ogień.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 28, 'A jego tchnienie jest jak wezbrana rzeka, która aż po gardła sięga, aby przesiewać narody rzeszotem zniszczenia i włożyć na szczęki narodów zwodnicze wędzidło.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 29, 'Wtedy zaśpiewacie jak w noc, gdy obchodzi się uroczyste święto, a rozweselicie się w sercu jak ten, który idzie wśród dźwięków fletu na górę Pana, do Skały Izraela;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 30, 'Gdy Pan da usłyszeć swój wspaniały głos i pokaże swoje wyciągnięte ramię w zapalczywości swego gniewu, w płomieniu trawiącego ognia, z rozproszeniem, wśród nawałnic i gradu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 31, 'Bo głosem Pana zostanie starty Asyryjczyk, który bił kijem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 32, 'I każde uderzenie utwierdzoną rózgą, którą go Pan uderzy, zadane będzie z bębnami i harfami. A w srogich bitwach będzie walczyć z nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 33, 'Od dawna bowiem przygotowane jest piekło, także dla samego króla jest przygotowane; uczynił je głębokim i szerokim, jego stos to ogień i wiele drew. Tchnienie Pana, jak strumień siarki, rozpala je.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 1, 'Biada tym, którzy zstępują do Egiptu po pomoc, polegają na koniach i ufają rydwanom, bo jest ich wiele, i jeźdźcom, bo są bardzo silni, a nie patrzą na Świętego Izraela i nie szukają Pana!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 2, 'Ale on też jest mądry, dlatego sprowadzi zło, a swoich słów nie cofnie. Lecz powstanie przeciw domowi złoczyńców i przeciwko pomocy tych, którzy czynią nieprawość.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 3, 'Przecież Egipcjanie są ludźmi, a nie Bogiem, ich konie są ciałem, a nie duchem. Gdy więc Pan wyciągnie swą rękę, padnie i ten, co pomaga, padnie i ten, któremu on pomaga, i tak wszyscy razem zginą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 4, 'Tak bowiem Pan powiedział do mnie: Jak ryczy lew lub lwiątko nad swym łupem, choć zwoła się przeciwko niemu gromadę pasterzy i nie lęka się ich wrzasku ani nie kuli się przed ich hałasem, tak zstąpi Pan zastępów, aby walczyć o górę Syjon i o jej pagórek.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 5, 'Jak ptaki latają koło swego gniazda, tak Pan zastępów obroni Jerozolimę; owszem, obroni i wybawi, a przechodząc, zachowa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 6, 'Nawróćcie się do tego, od którego synowie Izraela mocno odstąpili.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 7, 'Tego dnia bowiem każdy porzuci swoje bożki ze srebra i swoje bożki ze złota, które wasze ręce uczyniły wam na grzech.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 8, 'Wtedy Asyryjczyk padnie od miecza, lecz nie człowieka walecznego, a miecz nieludzki pochłonie go. I ucieknie przed mieczem, a jego młodzieńcy będą podbici.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 9, 'Swoją twierdzę ominie ze strachu, a jego książęta ulękną się sztandaru, mówi Pan, którego ogień jest na Syjonie, a jego piec – w Jerozolimie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 1, 'Oto król będzie panował w sprawiedliwości, a książęta będą rządzić w prawości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 2, 'I ten mężczyzna będzie jak zasłona przed wiatrem i jak schronienie przed burzą; jak strumienie wód w suchym miejscu, jak cień wielkiej skały w spragnionej ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 3, 'Oczy patrzących nie będą zaćmione i uszy słuchających będą uważnie słuchać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 4, 'Serce pochopnych zrozumie wiedzę, a język jąkających się będzie mówić pewnie i wyraźnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 5, 'Nieszlachetnego nie będą już nazywać szlachetnym ani o skąpym nie powie się, że jest szczodry;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 6, 'Nieszlachetny bowiem mówi nikczemnie i jego serce obmyśla nieprawość, aby postępował obłudnie i mówił przeciwko Panu przewrotnie, by wyniszczył duszę głodnego i spragnionego pozbawił napoju.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 7, 'Zamierzenia skąpego są złe, bo chytrze obmyśla, jak zniszczyć biednych słowami kłamstwa i mówić przeciwko ubogim przed sądem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 8, 'Ale szczodry ma szczodrobliwe myśli i będzie obstawać przy swojej szczodrobliwości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 9, 'Kobiety beztroskie, powstańcie, słuchajcie mego głosu; córki pewne siebie, nakłońcie ucha na moją mowę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 10, 'Przez wiele dni i lat będziecie zatrwożone, wy pewne siebie! Ustanie bowiem winobranie, zbioru nie będzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 11, 'Zatrwóżcie się, wy beztroskie, ulęknijcie się, pewne siebie! Rozbierzcie się i obnażcie się, a przepaszcie worem biodra.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 12, 'Nastanie lament nad piersiami, nad rozkosznymi polami i nad urodzajną winoroślą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 13, 'Na ziemi mojego ludu wyrosną ciernie i osty – tak, we wszystkich wesołych domach w rozbawionym mieście.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 14, 'Pałace bowiem zostaną opuszczone, ustanie wrzawa miasta, zamek i baszty staną się jaskiniami na zawsze, miejscem uciechy dla dzikich osłów, pastwiskiem dla stad;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 15, 'Aż zostanie wylany na nas duch z wysoka, pustynia obróci się w urodzajne pole, a urodzajne pole będzie uważane za las.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 16, 'Sąd zamieszka na pustyni, sprawiedliwość osiądzie na urodzajnym polu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 17, 'Dziełem sprawiedliwości będzie pokój, owocem sprawiedliwości odpoczynek i bezpieczeństwo na wieki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 18, 'Mój lud bowiem będzie mieszkał w przybytku pokoju, w bezpiecznych mieszkaniach i w spokojnych miejscach odpoczynku;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 19, 'Gdy spadnie na las grad, a miasto będzie bardzo poniżone.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 20, 'Błogosławieni jesteście, wy, którzy siejecie na wszelkich urodzajnych miejscach, puszczając tam wolno woły i osły.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 1, 'Biada tobie, który łupisz, chociaż sam nie byłeś złupiony, i który zdradzasz, chociaż sam nie byłeś zdradzony! Gdy przestaniesz łupić, też zostaniesz złupiony; gdy przestaniesz zdradzać, też będą cię zdradzać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 2, 'Panie, zlituj się nad nami, ciebie oczekujemy. Bądź ramieniem dla swoich każdego poranka i naszym zbawieniem w czasie ucisku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 3, 'Na głos wrzawy rozpierzchną się narody; gdy się podniesiesz, rozproszą się poganie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 4, 'I wasze łupy będą zebrane, jak się zbiera robactwo; a jak rzuca się szarańcza, tak on przypadnie na nie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 5, 'Pan jest wywyższony, bo mieszka na wysokości. Napełni Syjon sądem i sprawiedliwością.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 6, 'Mądrość i wiedza będą utwierdzeniem twych czasów, siłą i twoim obfitym zbawieniem, a bojaźń Pana to jego skarb.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 7, 'Oto ich mocarze wołają na dworze, posłowie pokoju gorzko płaczą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 8, 'Opustoszały drogi, przechodzień przestał podążać ścieżką. Zerwał przymierze, znieważył miasta, a z człowiekiem się nie liczy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 9, 'Ziemia płacze i marnieje; Liban jest zawstydzony i usycha; Szaron stał się niczym pustynia, a Baszan i Karmel są ogołocone.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 10, 'Teraz powstanę – mówi Pan – teraz się wywyższę, teraz się podniosę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 11, 'Poczniecie słomę i zrodzicie ściernisko; wasze tchnienie pożre was jak ogień.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 12, 'I narody będą jak wypalone wapno; jak ścięte ciernie będą spalone ogniem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 13, 'Słuchajcie, wy, którzy jesteście daleko, co uczyniłem, a wy, bliscy, poznajcie moją moc.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 14, 'Grzesznicy na Syjonie zlękli się, strach ogarnął obłudników: Kto z nas może przebywać przy trawiącym ogniu? Kto z nas może przebywać przy wiecznym płomieniu?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 15, 'Ten, kto postępuje w sprawiedliwości i mówi to, co prawe; ten, kto brzydzi się zyskiem niesprawiedliwym, kto otrząsa swe ręce, by nie brać darów, kto zatyka uszy, by nie słuchać o rozlewie krwi, i zamyka oczy, by nie patrzeć na zło;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 16, 'Ten będzie mieszkać na wysokościach, zamki na skałach będą jego ucieczką; będzie mu dany chleb i wody mu nie zabraknie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 17, 'Twoje oczy ujrzą króla w jego pięknie, ujrzą ziemię daleką.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 18, 'Twoje serce będzie wspominać grozę: Gdzie jest pisarz? Gdzie jest poborca? Gdzie jest ten, co liczył wieże?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 19, 'Nie zobaczysz już okrutnego ludu, ludu o ciemnej, niewyraźnej mowie, o bełkotliwym i niezrozumiałym języku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 20, 'Spójrz na Syjon, miasto naszych uroczystych świąt. Twoje oczy zobaczą Jerozolimę, spokojne miejsce zamieszkania, namiot, który nie będzie przeniesiony; jego kołki nigdy nie zostaną wyciągnięte i żaden z jego sznurów nie będzie zerwany.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 21, 'Wielmożny Pan sam będzie dla nas miejscem szerokich rzek i strumieni, po których nie popłynie okręt wiosłowy ani przez które okazały statek się nie przeprawi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 22, 'Pan bowiem jest naszym sędzią, Pan naszym prawodawcą, Pan naszym królem. On nas zbawi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 23, 'Osłabły twoje liny, nie będą mogli utrzymać twego masztu ani rozciągnąć żagla. Wtedy zostanie rozdzielony ogromny łup, chromi pochwycą zdobycz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 24, 'I żaden z mieszkańców nie powie: Zachorowałem. Ludowi, który mieszka w nim, zostanie przebaczona nieprawość.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 1, 'Zbliżcie się, narody, aby słuchać, i wy, ludy, słuchajcie uważnie! Niech słucha ziemia i to, co ją napełnia, świat i wszystko, co się na nim rodzi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 2, 'Bo oburzenie Pana spadło na wszystkie narody, jego zapalczywość – na wszystkie ich wojska. Wytracił je doszczętnie, wydał je na rzeź.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 3, 'Ich zabici będą porzuceni, a z ich trupów będzie unosił się smród i ich krew z gór popłynie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 4, 'Cały zastęp niebios stopnieje, a niebiosa jak zwój zostaną zwinięte, całe ich zastępy opadną, jak opada liść z winorośli i jak opada niedojrzały owoc z drzewa figowego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 5, 'Mój miecz bowiem nasyci się na niebie. Oto spadnie na Edom i na lud, który przekląłem, na sąd.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 6, 'Miecz Pana jest pełny krwi, pokrył się tłuszczem i krwią baranków i kozłów, tłuszczem nerek baranich, bo ofiara Pana dokonuje się w Bosra, a wielka rzeź w ziemi Edom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 7, 'Zstąpią z nimi jednorożce i byki z wołami, ich ziemia nasiąknie krwią, a ich proch nasyci się tłuszczem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 8, 'To jest bowiem dzień pomsty Pana i rok odpłaty za spór z Syjonem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 9, 'Potoki obrócą się w smołę, a proch w siarkę, jego ziemia stanie się smołą płonącą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 10, 'Nie zagaśnie ani w nocy, ani w dzień, jej dym będzie się unosił na wieki. Z pokolenia na pokolenie będzie pustkowiem; na wieki wieków nikt przez nią nie przejdzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 11, 'Ale pelikan i bąk ją posiądą, a sowa i kruk w niej zamieszkają. Rozciągnie on nad nią sznur spustoszenia i próżne wagi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 12, 'Wezwą jej szlachtę na królestwo, ale nie będzie tam żadnego, a wszyscy jej książęta obrócą się wniwecz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 13, 'W ich pałacach wyrosną ciernie, w ich zamkach – pokrzywy i osty. Będzie siedliskiem smoków i dziedzińcem dla strusiów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 14, 'Tam będą się spotykać dzikie zwierzęta pustyni ze strasznymi bestiami wysp, a kozice będą się nawoływać; tam leżeć będzie płomykówka i znajdzie dla siebie odpoczynek.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 15, 'Tam sowa się zagnieździ, zniesie jajka, wyleży młode i zbierze je w swoim cieniu. Tam też zlecą się sępy, jeden z drugim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 16, 'Szukajcie w księdze Pana i czytajcie. Ani jedno z nich nie przepadnie, żadne z nich nie będzie bez drugiego, bo usta Pana to rozkazały, a jego Duch je zgromadził.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 17, 'On też rzucił dla nich los i jego ręka wydzieliła im to sznurem mierniczym. Posiadać ją będą na wieki, będą w niej mieszkać z pokolenia na pokolenie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 1, 'Będzie się weselić z tego pustkowie i spieczona ziemia, pustynia rozraduje się i zakwitnie jak róża.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 2, 'Bujnie zakwitnie i rozweseli się w radości i wśród okrzyków. Chwała Libanu będzie jej dana, ozdoba Karmelu i Szaronu. Ujrzą chwałę Pana i wspaniałość naszego Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 3, 'Wzmacniajcie osłabłe ręce i posilcie omdlałe kolana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 4, 'Mówcie do zatrwożonych w sercu: Bądźcie mocni, nie bójcie się. Oto wasz Bóg przyjdzie z pomstą, z odpłatą przyjdzie sam Bóg i zbawi was.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 5, 'Wtedy otworzą się oczy ślepych i otworzą się uszy głuchych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 6, 'Wtedy chromy podskoczy jak jeleń i język niemych będzie śpiewać. Wytrysną bowiem wody na pustkowiu i potoki na pustyni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 7, 'Sucha ziemia stanie się jeziorem i spieczona ziemia – źródłami wód. W kryjówkach smoków, gdzie odpoczywały, urośnie trawa, trzcina i sitowie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 8, 'I będzie tam ścieżka i droga, którą nazwą Drogą Świętą. Nie będzie po niej chodził nieczysty, ale będzie ona dla nich. Ci, którzy tą drogą będą chodzić, nawet głupcy, nie zbłądzą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 9, 'Nie będzie tam lwa i żaden drapieżny zwierz po niej nie będzie chodził ani się tam nie znajdzie, ale będą chodzić po niej wybawieni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 10, 'Odkupieni Pana powrócą i przyjdą na Syjon ze śpiewem, a wieczna radość będzie na ich głowach. Dostąpią radości i wesela, a smutek i wzdychanie znikną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 1, 'W czternastym roku królowania Ezechiasza Sennacheryb, król Asyrii, wyruszył przeciwko wszystkim warownym miastom Judy i zdobył je.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 2, 'I król Asyrii posłał Rabszaka z Lakisz do Jerozolimy, do króla Ezechiasza, z wielkim wojskiem. Ten stanął przy kanale górnej sadzawki przy drodze pola folusznika.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 3, 'Wtedy wyszli do niego Eliakim, syn Chilkiasza, przełożony domu, i Szebna, pisarz, oraz Joach, syn Asafa, kronikarz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 4, 'Wtedy Rabszak powiedział do nich: Proszę, powiedzcie Ezechiaszowi: Tak mówi wielki król, król Asyrii: Co to za ufność, na której polegasz?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 5, 'Mówisz – ale to słowa daremne – mam dość dużo rad i siły do wojny. Teraz więc w kim pokładasz ufność, że zbuntowałeś się przeciwko mnie?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 6, 'Oto opierasz się na tej nadłamanej lasce trzcinowej – na Egipcie – która, gdy ktoś się oprze na niej, wbija mu się w dłoń i przebija ją. Taki jest faraon, król Egiptu, dla wszystkich, którzy mu ufają.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 7, 'A jeśli mi powiesz: Ufamy Panu, naszemu Bogu, czy on nie jest tym, którego wyżyny i ołtarze zniósł Ezechiasz i nakazał Judzie i Jerozolimie: Przed tym ołtarzem będziecie oddawać pokłon?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 8, 'Dlatego teraz proszę, daj zastaw memu panu, królowi Asyrii, a ja dam ci dwa tysiące koni, jeśli zdołasz posadzić na nich jeźdźców.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 9, 'Jakże więc stawisz opór jednemu dowódcy z najmniejszych sług mego pana, a pokładasz nadzieję w Egipcie, że otrzymasz rydwany i jeźdźców?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 10, 'Poza tym czy bez woli Pana wyruszyłem przeciw tej ziemi, aby ją zniszczyć? Pan powiedział do mnie: Wyrusz przeciwko tej ziemi i spustosz ją.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 11, 'Wtedy Eliakim, Szebna i Joach powiedzieli do Rabszaka: Proszę, mów do swoich sług po syryjsku, bo rozumiemy, a nie mów do nas po hebrajsku wobec ludu, który jest na murze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 12, 'Lecz Rabszak odpowiedział: Czy do twego pana i do ciebie posłał mnie mój pan, abym mówił te słowa? Czyż nie do tych mężczyzn siedzących na murze, aby jedli swój kał i pili swój mocz razem z wami?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 13, 'Stał więc Rabszak i zawołał donośnym głosem po hebrajsku tymi słowami: Słuchajcie słów wielkiego króla, króla Asyrii.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 14, 'Tak mówi król: Niech was nie zwodzi Ezechiasz, bo nie będzie mógł was wybawić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 15, 'A nie dajcie się przekonać Ezechiaszowi, by zaufać Panu, gdy mówi: Na pewno Pan nas wybawi i to miasto nie będzie wydane w ręce króla Asyrii.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 16, 'Nie słuchajcie Ezechiasza. Tak bowiem powiedział król Asyrii: Zawrzyjcie ze mną przymierze i wyjdźcie do mnie, a każdy będzie jeść ze swojej winorośli i ze swego drzewa figowego i każdy będzie pić wodę ze swojej studni;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 17, 'Aż przyjdę i zabiorę was do ziemi podobnej do waszej ziemi, do ziemi zboża i wina, do ziemi chleba i winnic.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 18, 'Niech Ezechiasz nie zwodzi was, mówiąc: Pan nas wybawi. Czy bogowie innych narodów mogli wybawić swoją ziemię z ręki króla Asyrii?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 19, 'Gdzie są bogowie Chamatu i Arpadu? Gdzie są bogowie Sefarwaim? Czy wybawili Samarię z mojej ręki?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 20, 'Którzy spośród wszystkich bogów tych ziem wybawili swoją ziemię z mojej ręki, żeby Pan miał wybawić Jerozolimę z mojej ręki?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 21, 'Lecz lud milczał i nie odpowiedział mu ani słowa, bo taki był rozkaz króla: Nie odpowiadajcie mu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 22, 'Wtedy przełożony domu Eliakim, syn Chilkiasza, pisarz Szebna i kronikarz Joach, syn Asafa, przyszli do Ezechiasza z rozdartymi szatami i oznajmili mu słowa Rabszaka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 1, 'A gdy król Ezechiasz to usłyszał, rozdarł swoje szaty, oblekł się w wór i wszedł do domu Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 2, 'I posłał Eliakima, przełożonego swego domu, pisarza Szebnę i starszych spośród kapłanów, obleczonych w wory, do proroka Izajasza, syna Amosa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 3, 'I powiedzieli mu: Tak mówi Ezechiasz: Ten dzień jest dniem utrapienia, upomnienia i bluźnierstwa. Nadszedł bowiem czas porodu dzieci, a nie ma siły, aby je urodzić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 4, 'Może Pan, twój Bóg, usłyszy słowa Rabszaka, którego przysłał król Asyrii, jego pan, aby znieważać Boga żywego, i pomści słowa, które usłyszał Pan, twój Bóg. Zanieś więc modlitwę za resztkę, która pozostaje.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 5, 'Tak to słudzy króla Ezechiasza przyszli do Izajasza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 6, 'A Izajasz im odpowiedział: Tak powiedzcie waszemu panu: Tak mówi Pan: Nie bój się tych słów, które słyszałeś, którymi bluźnili mi słudzy króla Asyrii.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 7, 'Oto ześlę na niego ducha i usłyszy pewną wieść, a potem wróci do swojej ziemi i sprawię, że padnie od miecza w swojej ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 8, 'Wrócił więc Rabszak i zastał króla Asyrii walczącego przeciwko Libnie. Usłyszał bowiem, że odstąpił od Lakisz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 9, 'A dotarło do niego, że mówiono o Tirhace, królu Etiopii: Oto wyruszył na wojnę przeciwko tobie. Gdy to usłyszał, wysłał posłańców do Ezechiasza z tymi słowami:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 10, 'Tak powiedzcie Ezechiaszowi, królowi Judy: Niech cię nie zwodzi twój Bóg, któremu ufasz, mówiąc: Jerozolima nie zostanie wydana w ręce króla Asyrii.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 11, 'Oto słyszałeś, co uczynili królowie Asyrii wszystkim ziemiom, niszcząc je. A ty miałbyś zostać wybawiony?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 12, 'Czy bogowie narodów wybawili tych, których moi ojcowie wygubili: Gozan, Charan, Resef i synów Edenu, którzy byli w Telassar?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 13, 'Gdzie jest król Chamatu, król Arpadu i król miasta Sefarwaim, Heny i Iwwy?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 14, 'Gdy Ezechiasz wziął list z rąk posłów, przeczytał go, wszedł do domu Pana i rozwinął go przed Panem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 15, 'I Ezechiasz modlił się do Pana, mówiąc:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 16, 'Panie zastępów, Boże Izraela, który zasiadasz pomiędzy cherubinami, ty, ty jedynie jesteś Bogiem wszystkich królestw ziemi, ty stworzyłeś niebo i ziemię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 17, 'Nakłoń swego ucha, Panie, i słuchaj. Otwórz swe oczy, Panie, i spójrz. Słuchaj wszystkich słów Sennacheryba, które przesłał, aby znieważać Boga żywego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 18, 'To prawda, Panie, że królowie Asyrii spustoszyli wszystkie narody i ich ziemie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 19, 'I powrzucali ich bogów do ognia. Nie byli bowiem bogami, ale dziełem rąk ludzkich, drewnem i kamieniem. Dlatego ich zniszczyli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 20, 'Teraz więc, Panie, nasz Boże, wybaw nas z jego ręki, aby wszystkie królestwa ziemi poznały, że jedynie ty jesteś Panem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 21, 'Wtedy Izajasz, syn Amosa, posłał wiadomość do Ezechiasza: Tak mówi Pan, Bóg Izraela: Ponieważ modliłeś się do mnie w sprawie Sennacheryba, króla Asyrii;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 22, 'Oto słowo, które Pan o nim wypowiedział: Dziewica, córka Syjonu, wzgardziła tobą i śmiała się z ciebie. Córka Jerozolimy kiwała głową za tobą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 23, 'Kogo znieważyłeś i komu bluźniłeś? Przeciwko komu podniosłeś swój głos i wysoko podniosłeś swoje oczy? Przeciwko Świętemu Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 24, 'Przez swoje sługi znieważyłeś Pana i powiedziałeś: Z mnóstwem swoich rydwanów wyszedłem na wysokie góry i zbocza Libanu. Wytnę jego wysokie cedry i jego wyborowe cyprysy i przyjdę aż do najwyższego jego szczytu, do lasów i do lasu jego pola.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 25, 'Ja wykopałem studnie i piłem wody, swoimi stopami wysuszyłem wszystkie rzeki oblężonych miejsc.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 26, 'Czy nie słyszałeś, że ja dawno to uczyniłem i za dawnych dni to sprawiłem? A teraz wypełniam, gdy obracasz warowne miasta w stosy gruzów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 27, 'Ich mieszkańcy, bezsilni, przestraszyli się i zawstydzili. Byli jak trawa polna, jak świeża zieleń, jak trawa na dachach, jak zboże, które uschło, zanim dojrzało.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 28, 'Znam twoje miejsce pobytu, twoje wyjście i twoje wejście, a także twoją wściekłość przeciwko mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 29, 'Ponieważ twoja wściekłość na mnie i twoja zuchwałość doszły do moich uszu, włożę moje kółko w twoje nozdrza i moje wędzidło na twoje wargi i zawrócę cię tą drogą, którą przyszedłeś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 30, 'A to będzie znakiem dla ciebie: Tego roku będziesz jadł zboże samorodne, w drugim roku także zboże samorodne, w trzecim roku zaś siejcie i zbierajcie żniwo, sadźcie winnice i jedzcie ich owoce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 31, 'Resztka ocalonych z domu Judy ponownie zapuści korzenie w głąb i wyda owoc w górze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 32, 'Z Jerozolimy wyjdą bowiem resztka i ci, którzy ocaleli z góry Syjon. Sprawi to gorliwość Pana zastępów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 33, 'Dlatego tak mówi Pan o królu Asyrii: Nie wejdzie do tego miasta ani nie wypuści tam strzały, nie wyruszy przeciw niemu z tarczą ani nie usypie szańców przeciwko niemu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 34, 'Drogą, którą przyszedł, powróci, a do tego miasta nie wejdzie, mówi Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 35, 'Będę bowiem bronił tego miasta i ocalę je ze względu na siebie i ze względu na Dawida, swego sługę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 36, 'Wtedy wyszedł Anioł Pana i zabił w obozie Asyrii sto osiemdziesiąt pięć tysięcy osób. A gdy wstali wcześnie rano, oto wszędzie było pełno trupów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 37, 'Sennacheryb, król Asyrii, wycofał się więc i wyruszył. Wrócił i zamieszkał w Niniwie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 38, 'A gdy oddawał pokłon w domu swego boga Nisroka, jego synowie – Adramelek i Sareser – zabili go mieczem. Potem uciekli do ziemi Ararat. I Asarchaddon, jego syn, królował w jego miejsce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 1, 'W tych dniach Ezechiasz śmiertelnie zachorował. Przyszedł do niego prorok Izajasz, syn Amosa, i powiedział do niego: Tak mówi Pan: Uporządkuj swój dom, bo umrzesz i nie będziesz żył.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 2, 'Wtedy Ezechiasz odwrócił swoją twarz do ściany i modlił się do Pana;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 3, 'I powiedział: O Panie, proszę cię, wspomnij teraz, że postępowałem wobec ciebie w prawdzie i z doskonałym sercem, czyniąc to, co dobre w twoich oczach. I Ezechiasz płakał bardzo rzewnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 4, 'Wtedy doszło do Izajasza słowo Pana:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 5, 'Idź i powiedz Ezechiaszowi: Tak mówi Pan, Bóg Dawida, twego ojca: Wysłuchałem twojej modlitwy, widziałem twoje łzy. Oto dodam do twoich dni piętnaście lat;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 6, 'Wybawię cię i to miasto z ręki króla Asyrii i będę bronić tego miasta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 7, 'A taki będzie znak dla ciebie od Pana, że Pan uczyni to, o czym mówił:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 8, 'Oto cofnę cień o dziesięć stopni w stopniach, po których przesunął się na zegarze słonecznym Achaza. I cofnęło się słońce o dziesięć stopni w tych stopniach, po których przesunęło się.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 9, '(Oto pismo Ezechiasza, króla Judy, gdy zachorował i wyzdrowiał:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 10, 'Mówiłem, gdy skrócono moje dni: Zejdę do bram grobu, zostanę pozbawiony reszty swoich lat.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 11, 'Powiedziałem: Nie ujrzę Pana, Pana w ziemi żyjących. Już nie zobaczę człowieka pośród mieszkańców świata.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 12, 'Moje życie przeminęło i przenoszone jest ode mnie jak namiot pasterski. Odciąłem swoje życie jak tkacz, on mnie odetnie od krosien. Dziś, zanim noc nadejdzie, zakończysz mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 13, 'Rozmyślałem sobie o poranku, że jak lew on zmiażdży wszystkie moje kości. Dziś, zanim noc nadejdzie, wykończysz mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 14, 'Jak żuraw i jaskółka kwiliłem, gruchałem jak gołąb. Moje oczy słabną, patrzą w górę. Panie, cierpię w udręce, przedłuż mi życie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 15, 'Cóż powiem? On przemówił do mnie i sam to uczynił. Będę kroczyć przez wszystkie swoje lata z goryczą w swojej duszy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 16, 'Panie, przez te rzeczy ludzie żyją i w nich wszystkich jest życie mego ducha. Przecież przywróciłeś mi zdrowie i zachowałeś mnie przy życiu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 17, 'Oto w czasie pokoju zaznałem ciężkiej goryczy, ale z miłości do mojej duszy wyrwałeś ją z dołu zniszczenia, gdyż rzuciłeś za siebie wszystkie moje grzechy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 18, 'Grób bowiem nie wysławia cię ani śmierć cię nie chwali. Ci, którzy w dół zstępują, nie oczekują twojej prawdy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 19, 'Żywy, żywy będzie cię wysławiać jak ja dzisiaj. Ojciec oznajmi dzieciom twoją prawdę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 20, 'Pan zechciał mnie wybawić. Dlatego będziemy śpiewać moje pieśni przy dźwiękach strun po wszystkie dni naszego życia w domu Pana).');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 21, 'Izajasz bowiem powiedział: Niech wezmą bryłę suchych fig i przyłożą na wrzód, a będzie uzdrowiony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 22, 'Ezechiasz zaś powiedział: Jaki jest znak, że wejdę do domu Pana?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 1, 'W tym czasie Merodak-Baladan, syn Baladana, król Babilonu, posłał listy i dar do Ezechiasza. Usłyszał bowiem, że chorował, a potem wyzdrowiał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 2, 'I Ezechiasz ucieszył się z tego, i pokazał im cały skarbiec swoich kosztowności: srebro i złoto, wonności, drogocenne olejki oraz swoją zbrojownię, a także wszystko, co się znajdowało w jego skarbcach. Nie było niczego, czego Ezechiasz by im nie pokazał w swoim domu i w całym swoim państwie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 3, 'Wtedy prorok Izajasz przyszedł do króla Ezechiasza i zapytał go: Co powiedzieli ci mężczyźni i skąd przyszli do ciebie? Ezechiasz odpowiedział: Przybyli do mnie z dalekiej ziemi, z Babilonu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 4, 'Znowu zapytał: Co widzieli w twoim domu? Ezechiasz odpowiedział: Widzieli wszystko, co jest w moim domu. Nie było niczego, czego bym im nie pokazał w swoich skarbcach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 5, 'Wtedy Izajasz powiedział do Ezechiasza: Słuchaj słowa Pana zastępów:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 6, 'Oto przyjdą dni, gdy zabiorą do Babilonu wszystko, co jest w twoim domu i co twoi ojcowie zgromadzili aż do tego dnia, mówi Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 7, 'A z twoich synów, którzy będą pochodzić od ciebie i których spłodzisz, zabiorą niektórych i będą eunuchami w pałacu króla Babilonu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 8, 'Wtedy Ezechiasz powiedział do Izajasza: Dobre jest słowo Pana, które wypowiedziałeś. I dodał: Będzie bowiem pokój i prawda za moich dni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 1, 'Pocieszajcie, pocieszajcie mój lud, mówi wasz Bóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 2, 'Przemawiajcie do serca Jerozolimy, wołajcie do niej, że dopełnił się jej postanowiony czas, że została przebaczona jej nieprawość, bo otrzymała z ręki Pana w dwójnasób za wszystkie swoje grzechy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 3, 'Głos wołającego na pustyni: Przygotujcie drogę Pana, prostujcie na pustyni ścieżkę naszego Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 4, 'Każda dolina niech będzie podniesiona, a każda góra i każdy pagórek – obniżone. To, co krzywe, niech się wyprostuje, a wyboiste miejsca niech będą równiną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 5, 'Wtedy objawi się chwała Pana i ujrzy to razem wszelkie ciało. Tak bowiem mówiły usta Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 6, 'Głos przemówił: Wołaj. I zapytano: Co mam wołać? Wszelkie ciało jest trawą, a cały jego wdzięk jak kwiat polny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 7, 'Trawa usycha, kwiat więdnie, gdy wiatr Pana powieje na nie. Zaprawdę ludzie są trawą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 8, 'Trawa usycha, kwiat więdnie, ale słowo naszego Boga trwa na wieki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 9, 'Wstąp na wysoką górę, Syjonie, który opowiadasz dobre wieści. Podnieś mocno swój głos, Jerozolimo, która opowiadasz dobre wieści; podnieś go, nie bój się, powiedz miastom Judy: Oto wasz Bóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 10, 'Oto Pan Bóg przyjdzie z mocą, jego ramię będzie panować. Oto jego zapłata z nim, a jego dzieło przed nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 11, 'Jak pasterz będzie pasł swoją trzodę, swoim ramieniem zgromadzi baranki, na swoim łonie będzie je nosił, a ciężarne poprowadzi ostrożnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 12, 'Kto zmierzył wody swoją garścią, a niebiosa piędzią wymierzył? Kto miarą odmierzył proch ziemi? Kto zważył góry na wadze, a pagórki na szalach?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 13, 'Kto kierował Duchem Pana, a kto był jego doradcą, aby go pouczać?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 14, 'Kogo się radził, aby nabyć rozumu? Kto pouczył go o ścieżkach sądu? Kto nauczył go wiedzy i wskazał mu drogę roztropności?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 15, 'Oto narody są jak kropla w wiadrze, znaczą tyle, co pyłek na wadze. Oto porywa wyspy jak bardzo małą rzecz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 16, 'I Libanu nie wystarczy na ogień ani jego zwierzyny nie wystarczy na całopalenie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 17, 'Wszystkie narody przed nim są niczym; uważa je za nicość i marność.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 18, 'Do kogo więc przyrównacie Boga? A jaką podobiznę z nim porównacie?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 19, 'Rzemieślnik odlewa posąg, a złotnik powleka go złotem i odlewa do niego srebrne łańcuszki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 20, 'Kogo z powodu ubóstwa nie stać na ofiarę, wybiera drzewo, które nie próchnieje; wyszukuje zdolnego rzemieślnika, aby przygotował rzeźbiony posąg, który się nie chwieje.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 21, 'Czy nie wiecie? Czy nie słyszeliście? Czy wam nie opowiadano od początku? Czy nie zrozumieliście tego od założenia fundamentów ziemi?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 22, 'To ten, który zasiada nad okręgiem ziemi – jej mieszkańcy są jak szarańcza; ten, który rozpostarł niebiosa jak zasłonę i rozciągnął je jak namiot mieszkalny;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 23, 'Ten, który książąt obraca wniwecz, sędziów ziemi czyni nicością.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 24, 'Nie będą wszczepieni ani posiani ani ich pień nie zakorzeni się w ziemi; powieje na nich, wnet usychają, a wicher unosi ich jak ściernisko.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 25, 'Do kogo więc mnie przyrównacie, abym był do niego podobny? – mówi Święty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 26, 'Podnieście w górę swoje oczy i patrzcie: Kto stworzył te rzeczy? Ten, kto wyprowadza ich zastępy według liczby i to wszystko po imieniu nazywa, według ogromu jego siły i wielkiej potęgi, tak że ani jedna z nich nie zginie?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 27, 'Czemu więc mówisz, Jakubie, i twierdzisz, Izraelu: Zakryta jest moja droga przed Panem, a moja sprawa nie dociera do mego Boga?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 28, 'Czy nie wiesz? Czy nie słyszałeś, że wieczny Bóg, Pan, Stwórca krańców ziemi, nie ustaje ani się nie męczy i że jego mądrość jest niezgłębiona?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 29, 'On dodaje siły spracowanemu i przymnaża mocy temu, który nie ma żadnej siły.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 30, 'Młodzież ustaje i mdleje, a młodzieńcy potykają się i padają;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 31, 'Ale ci, którzy oczekują Pana, nabiorą nowych sił; wzbiją się na skrzydłach jak orły, będą biec, a się nie zmęczą, będą chodzić, a nie ustaną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 1, 'Zamilczcie przede mną, wyspy, a niech narody nabiorą sił. Niech się zbliżą, wtedy niech mówią: Zbliżmy się razem do sądu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 2, 'Kto wzbudził ze wschodu tego sprawiedliwego i wezwał go, aby go naśladował? Kto mu podbił narody, aby nad królami panował? Podał je jak proch pod jego miecz i jak rozproszone ściernisko pod jego łuk.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 3, 'Ścigał ich, przeszedł spokojnie ścieżkę, po której swoimi nogami nie chodził.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 4, 'Kto to sprawił i uczynił? Kto wzywał pokolenia od początku? Ja, Pan – pierwszy i ostatni – ja sam.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 5, 'Widziały wyspy i zlękły się; krańce ziemi przestraszyły się, zgromadziły się i zeszły.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 6, 'Jeden drugiemu pomagał i mówił do swego brata: Bądź odważny!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 7, 'Tak więc stolarz zachęcał złotnika, a ten, co młotem blachę wygładza – kującego na kowadle, mówiąc: Jest gotowe do lutowania. Potem to przytwierdził gwoździami, aby się nie chwiało.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 8, 'Ale ty, Izraelu, mój sługo, ty, Jakubie, którego wybrałem, potomku Abrahama, mojego przyjaciela!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 9, 'Ty, którego pochwyciłem z krańców ziemi, a pomijając znamienitych, powołałem cię i powiedziałem ci: Jesteś moim sługą, wybrałem cię i nie odrzuciłem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 10, 'Nie bój się, bo ja jestem z tobą. Nie lękaj się, bo ja jestem twoim Bogiem. Umocnię cię, wspomogę cię i podeprę cię prawicą swojej sprawiedliwości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 11, 'Oto zawstydzą się i będą pohańbieni wszyscy, którzy płoną gniewem przeciwko tobie. Będą jak nicość i zginą ci, którzy tobie się sprzeciwiają.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 12, 'Będziesz ich szukał, a nie znajdziesz ich; ci, którzy się tobie sprzeciwiają, będą jak nicość, a ci, którzy walczą z tobą, zostaną wniwecz obróceni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 13, 'Ja bowiem, Pan, twój Bóg, trzymam cię za twoją prawicę i mówię: Nie bój się, ja cię wspomogę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 14, 'Nie bój się, robaczku, Jakubie, garstko ludu Izraela; ja cię wspomogę, mówi Pan i twój Odkupiciel, Święty Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 15, 'Oto uczynię z ciebie sanie młockarskie, nowe, z zębami po obu stronach. Będziesz młócił góry i zetrzesz je, a pagórki zamienisz w plewy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 16, 'Przewiejesz je, a wiatr je porwie i wicher je rozproszy. A ty się rozradujesz w Panu, będziesz się chlubił w Świętym Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 17, 'Gdy ubodzy i nędzarze szukają wody, a jej nie ma, a ich język usycha z pragnienia, ja, Pan, wysłucham ich, ja, Bóg Izraela, nie opuszczę ich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 18, 'Otworzę rzeki w miejscach wysokich, a źródła pośrodku dolin. Zamienię pustynię w jeziora wód, a suchą ziemię w strumienie wód.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 19, 'Posadzę na pustkowiu cedry, akacje, mirty i drzewa oliwne; posadzę na pustyni razem cyprys, wiąz i bukszpan;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 20, 'Aby widzieli i poznali, rozważali i zrozumieli, że ręka Pana to uczyniła i Święty Izraela to stworzył.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 21, 'Przedstawcie swoją sprawę, mówi Pan; pokażcie swoje mocne dowody, mówi Król Jakuba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 22, 'Niech przystąpią i niech nam oznajmią to, co ma się stać. Powiedzcie o dawnych rzeczach, które już były, abyśmy rozważyli to w swoim sercu i poznali ich koniec albo przynajmniej oznajmijcie nam przyszłe rzeczy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 23, 'Oznajmijcie, co nastąpi w przyszłości, a poznamy, że jesteście bogami. Tak, zróbcie coś dobrego lub złego, abyśmy się zdumiewali i razem to oglądali.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 24, 'Oto wy jesteście niczym, a wasze dzieła też są niczym. Obrzydliwy jest ten, kto was sobie wybiera.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 25, 'Wzbudziłem lud od północy, który nadciągnie, i od wschodu, który będzie wzywać mego imienia. Rozdepcze książąt jak błoto, jak garncarz depcze glinę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 26, 'Kto oznajmił to od początku, abyśmy wiedzieli od dawnych czasów, abyśmy powiedzieli: On jest sprawiedliwy? Nie ma nikogo, kto to oznajmił, nie ma nikogo, kto by to ogłosił ani kto by słyszał wasze słowa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 27, 'Ja pierwszy powiem Syjonowi: Oto, oto są. A Jerozolimie dam zwiastuna dobrych wieści.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 28, 'Spojrzałem bowiem, a nie było nikogo, nie było wśród nich doradcy, który by na moje pytania mógł odpowiedzieć słowo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 29, 'Oto ci wszyscy są marnością, ich uczynki są niczym. Ich odlewane posągi są wiatrem i pustką.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 1, 'Oto mój sługa, którego wspieram, mój wybrany, którego sobie upodobała moja dusza. Dałem mu swojego Ducha, on przyniesie narodom sąd.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 2, 'Nie będzie wołał ani się wywyższał, nie będzie słychać jego głosu na ulicy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 3, 'Trzciny nadłamanej nie złamie, a knota tlącego się nie zagasi. Wyda sąd według prawdy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 4, 'Nie ustanie ani się nie zniechęci, dopóki nie utrwali sądu na ziemi, a jego prawa będą oczekiwać wyspy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 5, 'Tak mówi Bóg, Pan, który stworzył niebiosa i je rozpostarł; który rozszerzył ziemię i to, co się z niej rodzi; który daje tchnienie ludziom mieszkającym na niej i ducha tym, co po niej chodzą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 6, 'Ja, Pan, wezwałem cię w sprawiedliwości i ująłem cię za rękę, będę cię strzegł i dam cię jako przymierze dla ludu, jako światłość dla narodów;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 7, 'Abyś otwierał oczy ślepym, wyprowadził więźniów z ciemnicy i z więzienia tych, co siedzą w ciemności.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 8, 'Ja, Pan, to jest moje imię, a mojej chwały nie oddam innemu ani mojej czci – rzeźbionym posągom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 9, 'Oto nastąpiły pierwsze rzeczy, a ja ogłaszam nowe; zanim się zaczną, dam wam o nich słyszeć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 10, 'Śpiewajcie Panu nową pieśń, jego chwałę od krańców ziemi, wy, którzy się w morzu pławicie, i wszystko, co w nim jest, wyspy i ich mieszkańcy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 11, 'Niech podniosą głos pustynia i jej miasta oraz wsie, w których mieszka Kedar. Niech wykrzykują mieszkańcy skały, niech wołają ze szczytu gór.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 12, 'Oddajcie cześć Panu i głoście jego chwałę na wyspach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 13, 'Pan wyruszy jak mocarz, jak mąż waleczny wzbudzi swoją gorliwość. Zawoła, nawet zagrzmi i odniesie zwycięstwo nad swoimi wrogami;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 14, 'Mówiąc: Milczałem dość długo, w spokoju wstrzymywałem się; ale teraz będę krzyczeć jak rodząca, spustoszę i pożrę wszystkich razem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 15, 'Góry i pagórki zamienię w pustynię i całą ich zieleń wysuszę. Zamienię rzeki w wyspy, a jeziora wysuszę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 16, 'Powiodę ślepych drogą, której nie znali, poprowadzę ich ścieżkami, o których nie wiedzieli. Ciemność zamienię w światłość przed nimi, a miejsca nierówne – w równinę. To są rzeczy, które dla nich uczynię, a nie opuszczę ich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 17, 'Cofną się i bardzo zawstydzą się ci, którzy ufają rzeźbionym posągom, którzy mówią odlanym posągom: Wy jesteście naszymi bogami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 18, 'O głusi, słuchajcie! Wy, ślepi, przejrzyjcie, abyście widzieli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 19, 'Kto jest ślepy, jeśli nie mój sługa, i głuchy, jeśli nie mój posłaniec, którego posłałem? Kto jest tak ślepy jak ten, który jest doskonały, kto tak ślepy jak sługa Pana?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 20, 'Widzi wiele rzeczy, lecz nie zważa na nie; otwarte ma uszy, ale nie słucha.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 21, 'Pan go sobie upodobał ze względu na swoją sprawiedliwość; wywyższy prawo i uczyni je sławnym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 22, 'Ale ten lud jest złupiony i ograbiony, wszyscy spętani są w ciemnicach; wydani są na łup, a nie ma nikogo, kto by ich wybawił; wydani są na rabunek, a nikt nie mówi: Oddaj.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 23, 'Kto z was nakłoni na to ucha? Kto usłyszy i posłucha na przyszły czas?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 24, 'Kto wydał Jakuba na rabunek, a Izraela łupieżcom? Czy nie Pan, przeciwko któremu zgrzeszyliśmy? Nie chcieli bowiem kroczyć jego drogami ani słuchać jego prawa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 25, 'Dlatego Pan wylał na niego zapalczywość swego gniewu i gwałtowną wojnę. Rozgorzała wokół niego, lecz on tego nie poznał, paliła go, ale nie wziął tego do serca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 1, 'Ale teraz tak mówi Pan, który cię stworzył, Jakubie, i który cię ukształtował, Izraelu: Nie bój się, bo cię odkupiłem i wezwałem cię po imieniu; jesteś mój.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 2, 'Gdy pójdziesz przez wody, będę z tobą, jeśli przez rzeki, one cię nie zaleją. Gdy pójdziesz przez ogień, nie spłoniesz i płomień cię nie spali.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 3, 'Ja bowiem jestem Panem, twoim Bogiem, Świętym Izraela, twoim Zbawicielem. Dałem Egipt na okup za ciebie, Etiopię i Sabę zamiast ciebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 4, 'Ponieważ jesteś w moich oczach drogi, jesteś uwielbiony, a ja cię umiłowałem – dlatego dałem ludzi za ciebie i narody za twoje życie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 5, 'Nie bój się, bo ja jestem z tobą; ze wschodu przyprowadzę twoje potomstwo i z zachodu cię zgromadzę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 6, 'Powiem północy: Oddaj; a południu: Nie zatrzymuj. Przyprowadź moich synów z daleka i moje córki z krańców ziemi;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 7, 'Każdego, kto nazywany jest moim imieniem i którego dla swojej chwały stworzyłem, ukształtowałem i uczyniłem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 8, 'Wyprowadź lud ślepy, który już ma oczy, i głuchy, który już ma uszy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 9, 'Niech wszystkie narody zbiorą się razem i niech się zgromadzą ludy. Kto spośród nich może ogłosić i oznajmić nam przeszłe rzeczy? Niech postawią swoich świadków, a będą usprawiedliwieni; albo niech słyszą i powiedzą: To jest prawda!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 10, 'Wy jesteście moimi świadkami, mówi Pan, i moim sługą, którego wybrałem, abyście poznali mnie i wierzyli mi, i zrozumieli, że to ja jestem. Przede mną nie został stworzony żaden Bóg ani po mnie nie będzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 11, 'Ja, ja jestem Panem i oprócz mnie nie ma zbawiciela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 12, 'Ja ogłaszałem, wybawiałem i opowiadałem, gdy nie było wśród was żadnego obcego boga. Wy jesteście moimi świadkami, mówi Pan, że ja jestem Bogiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 13, 'Zanim powstał dzień, ja jestem, a nie ma nikogo, kto by wyrwał cokolwiek z mojej ręki. Gdy coś uczynię, któż to odwróci?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 14, 'Tak mówi Pan, wasz Odkupiciel, Święty Izraela: Ze względu na was posłałem do Babilonu i zerwałem wszystkie rygle, i powaliłem Chaldejczyków, którzy się chlubią w swoich okrętach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 15, 'Ja jestem Panem, waszym Świętym, Stwórcą Izraela, waszym Królem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 16, 'Tak mówi Pan, który toruje drogę przez morze i ścieżkę przez potężne wody;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 17, 'Który wyprowadza rydwany i konie, wojsko i siły; upadli razem, a nie powstaną: zgaśli, dotlili się jak knot.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 18, 'Nie wspominajcie przeszłych rzeczy, na starodawne nie zważajcie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 19, 'Oto ja czynię nową rzecz i zaraz się pojawi. Czy nie poznacie tego? Utoruję drogę na pustkowiu i uczynię rzeki na pustyni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 20, 'Chwalić mnie będą zwierzęta polne, smoki i sowy, gdyż dostarczę wodę na pustkowie i uczynię rzeki na pustyni, aby napoić swój lud, swój lud wybrany.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 21, 'Ten lud, który dla siebie stworzyłem, będzie opowiadać moją chwałę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 22, 'A jednak ty nie wzywałeś mnie, Jakubie, lecz męczyłeś się mną, Izraelu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 23, 'Nie przyniosłeś mi baranka na swoje całopalenie, nie czciłeś mnie swymi ofiarami. Nie zmuszałem cię do służenia mi ofiarami i nie obciążałem cię ofiarą kadzidła;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 24, 'Nie kupiłeś mi za pieniądze wonności ani mnie nie nasyciłeś tłuszczem swoich ofiar. Ale obciążyłeś mnie swoimi grzechami i utrudziłeś mnie swoimi nieprawościami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 25, 'Ja, właśnie ja, zmazuję twoje przestępstwa ze względu na siebie, a twoich grzechów nie wspomnę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 26, 'Przypomnij mi, rozprawmy się ze sobą, powiedz, co masz na swoje usprawiedliwienie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 27, 'Twój pierwszy ojciec zgrzeszył, a twoi nauczyciele wykroczyli przeciwko mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 28, 'Dlatego zhańbiłem książąt świątyni i wydałem Jakuba klątwie, a Izraela zniewagom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 1, 'A teraz słuchaj, Jakubie, mój sługo, i ty, Izraelu, którego wybrałem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 2, 'Tak mówi Pan, który cię uczynił i który cię ukształtował już od łona matki, i który cię wspomaga: Nie bój się, Jakubie, mój sługo, i Jeszurunie, którego wybrałem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 3, 'Wyleję bowiem wody na spragnionego, a potoki na suchą ziemię. Wyleję mego Ducha na twoje potomstwo i moje błogosławieństwo na twoich potomków.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 4, 'I rozkrzewią się tak jakby pomiędzy trawą i jak wierzby nad potokami wód.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 5, 'Jeden powie: Ja należę do Pana, drugi nazwie się imieniem Jakuba, a inny napisze swoją ręką: Panu, i będzie się nazywał imieniem Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 6, 'Tak mówi Pan, Król Izraela i jego Odkupiciel, Pan zastępów: Ja jestem pierwszy i ja jestem ostatni, a oprócz mnie nie ma Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 7, 'Czy od czasów, gdy ustanowiłem pierwszy lud na świecie, znalazł się ktoś, kto jak ja jest w stanie ogłosić i opowiedzieć rzeczy przyszłe? Jeśli tak – niech więc powie, co ma nastąpić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 8, 'Nie bójcie się i nie lękajcie. Czy od dawna nie oznajmiałem wam wszystkiego i nie opowiadałem? Wy sami jesteście moimi świadkami. Czy jest Bóg oprócz mnie? Nie ma innej Skały; nie znam żadnej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 9, 'Wytwórcy rzeźbionych posągów są niczym, a ich piękne dzieła nic im nie pomogą; oni sami sobie są świadkami, że nic nie widzą ani nie rozumieją – ku swemu zawstydzeniu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 10, 'Kto utworzył boga i odlewał posąg, który nie przynosi żadnego pożytku?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 11, 'Oto wszyscy jego towarzysze będą zawstydzeni. Rzemieślnicy są tylko ludźmi. Niech się zbiorą wszyscy i niech staną. Przelęknąć się muszą i razem będą zawstydzeni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 12, 'Kowal kleszczami pracuje przy węglu, młotami kształtuje posąg i wykonuje go siłą swoich ramion, aż z głodu jego siły opadają, wody nie pije i omdlewa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 13, 'Cieśla zaś rozciąga sznur, wyznacza farbowanym sznurem, ciosa toporem, zaznacza go cyrklem i wykonuje go na podobieństwo człowieka, na podobieństwo pięknego człowieka, aby pozostawał w domu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 14, 'Narąbie sobie cedrów i bierze cyprys i dąb lub to, co jest najsilniejsze spośród drzew leśnych, wsadzi jesion, który rośnie dzięki deszczom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 15, 'Wtedy służy to człowiekowi na opał: bierze z tego, aby się ogrzać, także roznieca ogień, aby upiec chleb, ponadto robi sobie boga i oddaje mu pokłon, czyni z tego posąg i pada przed nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 16, 'Część tego spala w ogniu, przy drugiej części je mięso – przyrządza pieczeń i syci się. Także grzeje się i mówi: Ach, jak mi ciepło, widziałem ogień.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 17, 'A z reszty tego czyni boga, swój posąg. Pada przed nim, oddaje mu pokłon i modli się do niego, mówiąc: Ratuj mnie, bo ty jesteś moim bogiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 18, 'Nie wiedzą ani nie rozumieją, bo Bóg zaślepił ich oczy, aby nie widzieli, i ich serca, aby nie rozumieli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 19, 'I nie rozważają tego w swoim sercu, nie mają wiedzy ani rozumu, by powiedzieć: Część tego spaliłem w ogniu, a na węglu z tego wypiekłem chleb, upiekłem mięso i najadłem się. Czyż z reszty tego mam uczynić coś obrzydliwego? Czyż mam padać przed klocem drzewa?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 20, 'Taki się karmi popiołem, jego zwiedzione serce wprowadziło go w błąd, tak że nie może wybawić swojej duszy ani powiedzieć: Czyż nie jest fałszem to, co znajduje się w mojej prawicy?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 21, 'Pamiętaj o tym, Jakubie i Izraelu, gdyż jesteś moim sługą. Stworzyłem cię, jesteś moim sługą. O Izraelu, nie zapomnę o tobie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 22, 'Zmazałem twoje nieprawości jak obłok, a twoje grzechy jak mgłę. Nawróć się do mnie, bo cię odkupiłem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 23, 'Śpiewajcie, niebiosa, bo Pan to uczynił. Wykrzykujcie, głębiny ziemi. Rozbrzmiewajcie śpiewaniem góry, lesie wraz ze wszystkimi drzewami; Pan bowiem odkupił Jakuba, a w Izraelu okrył się chwałą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 24, 'Tak mówi Pan, twój Odkupiciel, który cię stworzył już od łona matki: Ja, Pan, wszystko czynię: sam rozciągam niebiosa, rozpościeram ziemię swoją mocą;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 25, 'Wniwecz obracam znaki kłamców i z wróżbitów czynię szaleńców; mędrców zmuszam do odwrotu, a ich wiedzę czynię głupstwem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 26, 'Potwierdzam słowa swego sługi i spełniam radę swoich posłańców. Ja mówię do Jerozolimy: Będziesz zamieszkana, do miast Judy: Będziecie odbudowane, bo podniosę jej ruiny;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 27, 'To ja mówię głębinie: Wysychaj, ja wysuszę twoje potoki;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 28, 'I o Cyrusie mówię: On jest moim pasterzem, bo wypełni całą moją wolę; i mówię do Jerozolimy: Będziesz odbudowana, a do świątyni: Będziesz założona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 1, 'Tak mówi Pan do swego pomazańca Cyrusa, którego prawicę ująłem, by podbić przed nim narody, rozpinać biodra królów i otworzyć przed nim wrota, a bramy nie będą zamknięte.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 2, 'Ja pójdę przed tobą, a krzywe drogi wyprostuję, skruszę spiżowe wrota, a połamię żelazne rygle.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 3, 'I dam ci ukryte skarby i bogactwa schowane, abyś poznał, że ja jestem Panem, Bogiem Izraela, który cię wzywa po imieniu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 4, 'Ze względu na swego sługę Jakuba i Izraela, swego wybrańca, nazwałem cię twoim imieniem, nadałem ci zaszczytny tytuł, chociaż mnie nie znałeś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 5, 'Ja jestem Panem i nie ma żadnego innego, oprócz mnie nie ma żadnego Boga. Przepasałem cię, chociaż mnie nie znałeś;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 6, 'Aby poznali od wschodu i od zachodu, że nie ma nikogo oprócz mnie. Ja jestem Panem i nie ma żadnego innego;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 7, 'Ja tworzę światłość i stwarzam ciemność. Czynię pokój i stwarzam nieszczęście. Ja, Pan, czynię to wszystko.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 8, 'Niebiosa, spuśćcie rosę z góry i niech obłoki wylewają sprawiedliwość. Niech ziemia się otworzy i niech wyrośnie zbawienie, a razem z nim niech zakwitnie sprawiedliwość. Ja, Pan, to stworzyłem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 9, 'Biada temu, który się spiera ze swoim Stwórcą, będąc skorupą jak inne skorupy gliniane. Czy glina powie swemu garncarzowi: Cóż czynisz? A twoje dzieło: On nie ma rąk?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 10, 'Biada temu, który mówi ojcu: Cóż spłodziłeś? A do kobiety: Cóż urodziłaś?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 11, 'Tak mówi Pan, Święty Izraela i jego Stwórca: Pytajcie mnie o przyszłe rzeczy moich synów i sprawę moich rąk pozostawcie mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 12, 'Ja uczyniłem ziemię i stworzyłem na niej człowieka. To ja – moje ręce rozciągnęły niebiosa i całemu ich zastępowi rozkazuję.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 13, 'Ja go wzbudziłem w sprawiedliwości i wyprostuję wszystkie jego drogi. On odbuduje moje miasto i wypuści moich więźniów, nie za okup ani za dar, mówi Pan zastępów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 14, 'Tak mówi Pan: Dorobek Egiptu i kupiectwo Etiopii i Sabejczyków, wysocy mężczyźni, przyjdą do ciebie i będą twoi. Pójdą za tobą; przyjdą w pętach, upadną przed tobą i będą błagać, mówiąc: Tylko u ciebie jest Bóg, a nie ma żadnego innego oprócz tego Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 15, 'Zaprawdę ty jesteś Bogiem ukrytym, Boże Izraela, Zbawicielu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 16, 'Wszyscy oni się zawstydzą i będą zhańbieni. Razem odejdą w hańbie wytwórcy bożków.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 17, 'Ale Izrael będzie zbawiony przez Pana zbawieniem wiecznym. Nie zawstydzicie się ani nie będziecie zhańbieni aż na wieki wieków.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 18, 'Bo tak mówi Pan, który stworzył niebiosa, Bóg, który stworzył ziemię i uczynił ją, który ją utwierdził, nie na próżno stworzył ją, lecz na mieszkanie ją utworzył: Ja jestem Panem i nie ma żadnego innego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 19, 'Nie mówiłem potajemnie, w ciemnym miejscu na ziemi, nie mówiłem do potomstwa Jakuba: Na próżno mnie szukajcie. Ja, Pan, mówię sprawiedliwość i zwiastuję to, co słuszne.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 20, 'Zgromadźcie się i przyjdźcie; zbliżcie się razem, wy, którzy ocaleliście spośród narodów. Nic nie wiedzą ci, którzy noszą swoje drewniane bożki i modlą się do boga, który nie może zbawić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 21, 'Oznajmijcie i przyprowadźcie ich, niech naradzają się razem: Kto to od dawna przepowiadał? Kto od tamtego czasu to ogłaszał? Czy nie ja, Pan? A nie ma żadnego innego Boga oprócz mnie. Nie ma Boga sprawiedliwego ani innego Zbawiciela oprócz mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 22, 'Spójrzcie na mnie, abyście byli zbawieni, wszystkie krańce ziemi, gdyż ja jestem Bogiem i nie ma żadnego innego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 23, 'Przysiągłem na siebie, z moich ust wyszło słowo sprawiedliwe, które jest nieodwołalne: Przede mną będzie się zginać każde kolano, będzie przysięgać każdy język;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 24, 'Mówiąc: Tylko w Panu mam wszelką sprawiedliwość i siłę. Ci do niego przyjdą, ale będą zhańbieni wszyscy, którzy płoną gniewem przeciwko niemu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 25, 'W Panu będzie usprawiedliwione i będzie się chlubić całe potomstwo Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 1, 'Ugiął się Bel, chyli się Nebo. Ich posągi włożono na zwierzęta i bydło, które będąc obciążone, zmęczyły się pod brzemieniem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 2, 'Pochyliły się i ugięły się razem; nie mogły ratować brzemion, ale one same poszły w niewolę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 3, 'Słuchajcie mnie, domu Jakuba i cała resztko domu Izraela, których noszę od łona, których piastuję od urodzenia:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 4, 'Aż do waszej starości ja jestem ten sam i aż do siwizny będę was nosić. Ja was uczyniłem, ja też nosić będę; ja mówię, będę was nosił i was wybawię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 5, 'Do kogo mnie porównacie i z kim mnie zestawicie albo do kogo uczynicie mnie podobnym, abyśmy byli sobie równi?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 6, 'Wysypują złoto z worka i odważają srebro na szalach, najmują złotnika, aby uczynił z nich bożka, przed którym padają i któremu oddają pokłon.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 7, 'Noszą go na ramieniu, dźwigają go i stawiają go na swoim miejscu. I stoi, nie ruszy się ze swego miejsca. Jeśli ktoś zawoła do niego, nie odzywa się ani go nie wybawia z jego utrapienia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 8, 'Pamiętajcie o tym i wstydźcie się, weźcie to sobie do serca, przestępcy!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 9, 'Wspomnijcie rzeczy dawne i odwieczne, bo ja jestem Bogiem, nie ma żadnego innego, jestem Bogiem i nie ma nikogo podobnego do mnie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 10, 'Zapowiadam od początku rzeczy ostatnie i od dawna to, czego jeszcze nie było. Mówię: Mój zamiar się spełni i wykonam całą swoją wolę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 11, 'Przywołuję ze wschodu ptaka drapieżnego, z dalekiej ziemi mężczyznę, który wykonuje moją radę. Powiedziałem i wykonam to, postanowiłem i uczynię to.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 12, 'Słuchajcie mnie, wy, twardego serca, którzy jesteście dalecy od sprawiedliwości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 13, 'Zbliżę moją sprawiedliwość, nie będzie ona daleko, a moje zbawienie nie odwlecze się. I położę w Syjonie zbawienie, a w Izraelu moją chwałę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 1, 'Zstąp i usiądź w prochu, dziewico, córko Babilonu! Siądź na ziemi, a nie na tronie, córko chaldejska, gdyż już cię nie będą nazywać delikatną i rozkoszną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 2, 'Weź żarna i miel mąkę, odkryj swoje warkocze, obnaż nogi, odkryj uda, brnij przez rzeki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 3, 'Twoja nagość będzie odkryta i twoja hańba będzie widoczna. Dokonam pomsty, żaden człowiek mnie nie powstrzyma.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 4, 'Tak mówi nasz Odkupiciel, jego imię to Pan zastępów, Święty Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 5, 'Usiądź w milczeniu i wejdź w ciemności, córko chaldejska, bo już nie będą cię nazywali panią królestw.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 6, 'Rozgniewałem się na mój lud, splugawiłem moje dziedzictwo i oddałem je w twoje ręce, ale ty nie okazałaś im miłosierdzia i starców niezmiernie obciążyłaś swoim jarzmem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 7, 'I powiedziałaś: Będę panią na wieki. I nie wzięłaś sobie tego do serca ani nie pamiętałaś o tym, jakie będzie tego zakończenie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 8, 'Dlatego słuchaj teraz, rozkosznico, która mieszkasz bezpiecznie i mówisz w swoim sercu: Ja jestem i nie ma oprócz mnie żadnej innej, nie będę wdową ani nie zaznam bezdzietności!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 9, 'Lecz obie te rzeczy spadną na ciebie nagle, w jednym dniu: bezdzietność i wdowieństwo. W pełni spadną na ciebie z powodu mnóstwa twoich guseł i z powodu twoich licznych czarów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 10, 'Zaufałaś bowiem swojej niegodziwości i mówiłaś: Nikt mnie nie widzi. Twoja mądrość i twoja wiedza uczyniły cię przewrotną i mówiłaś w swoim sercu: Ja jestem i nie ma oprócz mnie żadnej innej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 11, 'Dlatego przyjdzie na ciebie zło, ale nie poznasz, skąd pochodzi, spadnie na ciebie nieszczęście, którego nie będziesz mogła się pozbyć, i przyjdzie na ciebie nagle spustoszenie, którego nie spostrzeżesz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 12, 'Pozostań przy swoich czarach i mnóstwie swych guseł, którymi się trudziłaś od młodości; może zdołasz sobie pomóc, może się umocnisz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 13, 'Jesteś zmęczona mnóstwem swoich rad. Niech teraz staną astrolodzy, ci, którzy przypatrują się gwiazdom, ci, którzy przepowiadają co miesiąc, co ma się wydarzyć, i niech cię wybawią z tego, co ma przyjść na ciebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 14, 'Oto są oni jak ściernisko, ogień ich spali i nie wybawią swojej duszy z mocy płomienia. Nie zostanie węgla do ogrzania się ani ognia, aby przy nim posiedzieć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 15, 'Tacy będą dla ciebie handlarze, z którymi się zadawałaś od młodości: każdy z nich uda się w swoją stronę, nie będzie nikogo, kto by cię ocalił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 1, 'Słuchajcie tego, domu Jakuba, którzy jesteście nazywani imieniem Izraela i pochodzicie z wód Judy, którzy przysięgacie na imię Pana i wspominacie Boga Izraela, ale nie w prawdzie ani w sprawiedliwości;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 2, 'Nazywacie się od miasta świętego i opieracie się na Bogu Izraela, jego imię to Pan zastępów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 3, 'Rzeczy przeszłe zapowiadałem od dawna, z moich ust wyszły i ogłaszałem je, wykonywałem je od razu i nastąpiły.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 4, 'Ponieważ wiedziałem, że jesteś uparty i że twoja szyja jest ścięgnem żelaznym, a twoje czoło – miedziane;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 5, 'Oznajmiałem ci od dawna, ogłosiłem to, zanim nastąpiło, abyś nie powiedział: Mój bożek to uczynił, mój rzeźbiony posąg i mój odlewany posąg to nakazał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 6, 'Słyszałeś o tym, spójrz na to wszystko. Czy wy tego nie opowiecie? Teraz już ogłaszam nowe i tajemne rzeczy, o których nie wiedziałeś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 7, 'Teraz są stworzone, a nie od dawna, rzeczy, o których przed tym dniem nic nie słyszałeś, byś nie powiedział: Oto wiedziałem o tym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 8, 'Ani nie słyszałeś, ani nie wiedziałeś, ani twoje ucho nie było otwarte w tym czasie, bo wiedziałem, że postąpisz przewrotnie i że nazwano cię przestępcą od łona matki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 9, 'Ze względu na moje imię powściągam swój gniew i ze względu na moją chwałę powstrzymam swój gniew na ciebie, aby cię nie wytępić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 10, 'Oto wytapiałem cię, ale nie jak srebro; wybrałem cię w piecu utrapienia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 11, 'Ze względu na siebie, na siebie samego, to uczynię, bo jakże miałoby być splugawione moje imię? Przecież mojej chwały nie oddam innemu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 12, 'Słuchaj mnie, Jakubie i Izraelu, mój wezwany: Ja jestem, ja jestem pierwszy i ja jestem ostatni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 13, 'To moja ręka założyła ziemię i moja prawica zmierzyła niebiosa. Gdy na nie zawołam, zaraz staną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 14, 'Zbierzcie się wszyscy i słuchajcie. Któż spośród nich to opowiedział? Pan go umiłował, on wykona jego wolę na Babilonie i jego ramię będzie przeciw Chaldejczykom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 15, 'Ja, ja mówiłem i ja go wezwałem; przyprowadziłem go i powiedzie mu się jego droga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 16, 'Zbliżcie się do mnie i słuchajcie tego; od początku nie mówiłem w skrytości; ale od tego czasu, kiedy to się działo, tam byłem. A teraz Pan Bóg posłał mnie, i jego Duch.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 17, 'Tak mówi Pan, twój Odkupiciel, Święty Izraela: Ja jestem Panem, twoim Bogiem, który cię uczy tego, co jest pożyteczne, i prowadzi cię drogą, którą masz chodzić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 18, 'O gdybyś zważał na moje przykazania, twój pokój byłby jak rzeka i twoja sprawiedliwość jak fale morskie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 19, 'Twoje potomstwo byłoby jak piasek i płód twego łona jak jego ziarnko; jego imię nie zostałoby wytępione ani zgładzone sprzed mego oblicza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 20, 'Wyjdźcie z Babilonu, uciekajcie od Chaldejczyków. Głosem śpiewu to obwieszczajcie, rozgłaszajcie to, zwiastujcie to aż do krańców ziemi; mówcie: Pan odkupił swego sługę Jakuba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 21, 'Nie zaznali pragnienia, gdy ich prowadził przez pustynię. Sprawił, że wody trysnęły dla nich ze skał. Rozszczepił skałę i wypłynęły wody.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 22, 'Nie ma pokoju dla niegodziwych, mówi Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 1, 'Słuchajcie mnie, wyspy, a narody dalekie, uważajcie! Pan wezwał mnie od łona, od łona mojej matki wspominał moje imię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 2, 'I uczynił moje usta jak ostry miecz, w cieniu swej ręki ukrył mnie i uczynił mnie wyostrzoną strzałą; w swoim kołczanie schował mnie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 3, 'I powiedział mi: Jesteś moim sługą, Izraelu, w tobie się rozsławię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 4, 'A ja powiedziałem: Na darmo się trudziłem, na próżno i daremnie zużyłem swoją siłę. A jednak mój sąd jest u Pana i moje dzieło – u mojego Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 5, 'A teraz mówi Pan, który stworzył mnie na swego sługę już od łona, abym przyprowadził do niego Jakuba, a choćby Izrael nie był zebrany, będę jednak wysławiony w oczach Pana, a mój Bóg będzie moją siłą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 6, 'I powiedział: To za mało, że jesteś moim sługą, aby podźwignąć pokolenia Jakuba i przywrócić ocalonych z Izraela. Dlatego ustanowię cię światłością dla pogan, abyś był moim zbawieniem aż do krańców ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 7, 'Tak mówi Pan, Odkupiciel Izraela, jego Święty, do tego, którym każdy gardzi i którym brzydzą się narody, do sługi władców: Królowie zobaczą cię i powstaną, książęta oddadzą ci pokłon przez wzgląd na Pana, który jest wierny, przez wzgląd na Świętego Izraela, który cię wybrał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 8, 'Tak mówi Pan: W czasie pomyślnym wysłuchałem cię, a w dniu zbawienia przyszedłem ci z pomocą. Będę cię strzegł i ustanowię cię przymierzem dla ludu, abyś utwierdził ziemię i rozdzielił opustoszałe dziedzictwa;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 9, 'Abyś mówił więźniom: Wyjdźcie; a tym, którzy są w ciemności: Pokażcie się. Będą się paśli przy drogach i na wszystkich miejscach wysokich będą ich pastwiska.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 10, 'Nie zaznają głodu ani pragnienia i nie porazi ich upał ani słońce, bo ten, który lituje się nad nimi, poprowadzi ich, poprowadzi ich do źródeł wód.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 11, 'Na wszystkich moich górach utoruję drogę, a moje gościńce będą wyżej wzniesione.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 12, 'Oto ci przyjdą z daleka, drudzy z północy i od strony morza, a jeszcze inni z ziemi Sinim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 13, 'Śpiewajcie, niebiosa, rozraduj się, ziemio, głośno zabrzmijcie, góry! Pan bowiem pocieszył swój lud i zlitował się nad swoimi ubogimi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 14, 'Ale Syjon powiedział: Pan mnie opuścił, Pan o mnie zapomniał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 15, 'Czy kobieta może zapomnieć o swoim niemowlęciu i nie zlitować się nad płodem swego łona? A choćby też i one zapomniały, ja jednak o tobie nie zapomnę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 16, 'Oto na swoich dłoniach wyryłem cię; twoje mury są zawsze przede mną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 17, 'Pospieszą się twoi synowie, a ci, którzy cię burzyli i pustoszyli, odejdą od ciebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 18, 'Podnieś wokoło swoje oczy i zobacz: oni wszyscy się gromadzą i przychodzą do ciebie. Jak żyję ja, mówi Pan, przyozdobisz się nimi jak klejnotem i przepaszesz się nimi jak oblubienica;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 19, 'Bo twoje ruiny, twoje opustoszałe miejsca i zniszczona ziemia będą zbyt ciasne dla mieszkańców, oddalą się ci, którzy cię pożerali.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 20, 'A synowie, których będziesz miała po utraceniu pierwszych, powiedzą ci do uszu: To miejsce jest zbyt ciasne; daj mi miejsce, abym mógł mieszkać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 21, 'I powiesz w swoim sercu: Kto mi tych spłodził? Przecież byłam osierocona i samotna, wygnana i tułałam się. Kto więc tych wychował? Oto ja sama pozostałam, gdzie więc oni byli?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 22, 'Tak mówi Pan Bóg: Oto wzniosę rękę ku narodom, podniosę swój sztandar ku ludom. I przyniosą twoich synów na rękach, i twoje córki będą nieść na ramionach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 23, 'I królowie będą twoimi piastunami, a ich księżne – twoimi mamkami. Z twarzą ku ziemi będą się tobie kłaniać i pył twoich nóg będą lizać. Wtedy poznasz, że ja jestem Panem i że nie bywają zawstydzeni ci, którzy mnie oczekują.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 24, 'Czy można odebrać mocarzowi zdobycz? Czy słusznie pojmany lud będzie wybawiony?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 25, 'Ale tak mówi Pan: Pojmany lud zostanie odebrany mocarzowi i zdobycz okrutnika zostanie wybawiona. Ja bowiem sprzeciwię się twemu przeciwnikowi i ocalę twoich synów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 26, 'I tych, którzy cię gnębią, nakarmię ich własnym ciałem, a własną krwią się upiją jak moszczem. I wszelkie ciało pozna, że ja jestem Panem, twoim Zbawicielem i twoim Odkupicielem, Mocarzem Jakuba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 1, 'Tak mówi Pan: Gdzie jest list rozwodowy waszej matki, którym ją oddaliłem? Albo któremu ze swoich wierzycieli was sprzedałem? Oto z powodu waszych nieprawości sami siebie sprzedaliście, a z powodu waszych przestępstw wasza matka została oddalona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 2, 'Dlaczego gdy przyszedłem, nie było nikogo? A gdy wołałem, nikt się nie odezwał? Czy moja ręka jest zbyt krótka, aby odkupić? Czy nie ma we mnie mocy, aby wybawić? Oto swoją groźbą osuszam morze, zamieniam rzeki w pustynię, tak że ich ryby śmierdzą z braku wody i zdychają z pragnienia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 3, 'Powlekam niebiosa ciemnością i wór im daję za osłonę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 4, 'Pan Bóg dał mi język uczonych, abym umiał znużonemu mówić słowo w odpowiednim czasie. Budzi mnie każdego ranka, pobudza moje uszy, abym słuchał tak jak uczeni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 5, 'Pan Bóg otworzył mi uszy, a ja się nie sprzeciwiłem ani się nie cofnąłem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 6, 'Podałem moje plecy bijącym, a moje policzki rwącym mi brodę. Nie zakrywałem mojej twarzy przed zniewagami i pluciem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 7, 'Bo Pan Bóg wspomoże mnie, dlatego nie będę zhańbiony. Dlatego uczyniłem swoją twarz jak krzemień i wiem, że nie będę zawstydzony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 8, 'Blisko jest ten, który mnie usprawiedliwia. Kto będzie się spierać ze mną? Stańmy razem. Kto chce prawować się ze mną, niech przystąpi do mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 9, 'Oto Pan Bóg pomoże mi; któż mnie potępi? Oto wszyscy jak szata się zestarzeją, a mól ich pożre.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 10, 'Kto wśród was boi się Pana? Kto słucha głosu jego sługi? Kto chodzi w ciemności i nie ma światłości? Niech zaufa imieniu Pana i polega na swoim Bogu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 11, 'Oto wy wszyscy, którzy rozniecacie ogień i przepasujecie się iskrami, chodźcie w światłości waszego ognia i w iskrach, które rozpaliliście. Spotka was to z mojej ręki, że będziecie leżeć w boleści.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 1, 'Słuchajcie mnie, wy, którzy podążacie za sprawiedliwością, którzy szukacie Pana. Spójrzcie na skałę, z której was wyciosano i na głębokość dołu, skąd was wykopano.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 2, 'Spójrzcie na Abrahama, waszego ojca, i na Sarę, która was porodziła, gdyż jego jednego wezwałem, pobłogosławiłem i rozmnożyłem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 3, 'Pan bowiem pocieszy Syjon, pocieszy wszystkie jego ruiny i uczyni jego pustkowia jak Eden, a jego pustynię jak ogród Pana. Znajdzie się w nim radość i wesele, dziękczynienie i głos śpiewania.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 4, 'Słuchaj mnie, mój ludu, nadstaw ucha, mój narodzie. Ode mnie bowiem wyjdzie prawo, a wystawię mój sąd jako światłość dla narodów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 5, 'Bliska jest moja sprawiedliwość, wyszło moje zbawienie, a moje ramiona będą sądzić narody. Wyspy będą mnie oczekiwać i w moim ramieniu będą pokładać nadzieję.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 6, 'Podnieście ku niebu swoje oczy i spójrzcie na dół, na ziemię: Niebiosa jak dym się rozwieją i ziemia jak szata się zestarzeje, a jej mieszkańcy zginą jak one. Ale moje zbawienie będzie trwać na wieki i moja sprawiedliwość nie ustanie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 7, 'Słuchajcie mnie, wy, którzy znacie sprawiedliwość, ludu, w którego sercu jest moje prawo! Nie bójcie się urągania ludzi i nie lękajcie się ich lżenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 8, 'Mól bowiem pożre ich jak szatę, a robak pogryzie ich jak wełnę. Ale moja sprawiedliwość będzie trwać na wieki i moje zbawienie – z pokolenia na pokolenie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 9, 'Zbudź się, zbudź się, przyoblecz się w siłę, ramię Pana! Zbudź się jak za dawnych dni i jak za pokoleń minionych! Czyś to nie ty porąbało Egipt i zraniło smoka?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 10, 'Czyś to nie ty wysuszyło morze, wody wielkiej głębi, i zamieniło głębiny morskie w drogę, aby przeszli odkupieni?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 11, 'Powrócą więc odkupieni przez Pana i przyjdą do Syjonu ze śpiewaniem, a wieczna radość będzie nad ich głową. Dostąpią wesela i radości i ucieknie smutek i wzdychanie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 12, 'Ja, to ja jestem waszym pocieszycielem. Kim jesteś, że się boisz człowieka śmiertelnego i syna człowieczego, który jest jak trawa;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 13, 'I zapominasz o Panu, swoim Stwórcy, który rozciągnął niebiosa i założył ziemię; że lękasz się nieustannie każdego dnia z powodu wściekłości ciemięzcy, gdy zmierza do tego, aby zniszczyć? Ale gdzie jest ta wściekłość ciemięzcy?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 14, 'Jeniec spieszy się, aby zostać uwolniony, bo nie chce umrzeć w dole ani z braku chleba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 15, 'Doprawdy ja jestem Panem, twoim Bogiem, który rozdziela morze tak, że szumią jego fale. Pan zastępów to moje imię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 16, 'Ja włożyłem swoje słowa w twoje usta i w cieniu swojej ręki cię zakryłem, aby osadzić niebiosa i założyć ziemię, i powiedzieć Syjonowi: Ty jesteś moim ludem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 17, 'Zbudź się, zbudź się, powstań Jerozolimo, która piłaś z ręki Pana kubek jego gniewu; wypiłaś męty z kubka odurzenia i je wysączyłaś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 18, 'Nikt jej nie prowadzi spośród wszystkich synów, których urodziła, i nikt jej za rękę nie trzyma ze wszystkich synów, których wychowała.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 19, 'Dwie rzeczy cię spotkały, któż się użali nad tobą? Spustoszenie i zniszczenie, głód i miecz; któż cię pocieszy?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 20, 'Twoi synowie leżeli omdlali na rogach wszystkich ulic, jak dziki wół w sieci. Są pełni gniewu Pana, upomnienia twego Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 21, 'Dlatego teraz słuchaj tego, utrapiona i pijana, lecz nie winem:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 22, 'Tak mówi twój Pan i twój Bóg, który wstawia się za swoim ludem: Oto zabieram z twojej ręki kubek odurzenia, męty kubka swojej wściekłości. Nie będziesz już pić z niego;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 23, 'Ale podam go w rękę tych, którzy cię trapią, którzy mówili twojej duszy: Nachyl się, abyśmy przeszli przez ciebie. A ty uczyniłaś swoje plecy jakby ziemią i jakby ulicą dla przechodzących.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 1, 'Obudź się, obudź się; przyoblecz się w swoją siłę, Syjonie! Przyoblecz się w swą wspaniałą szatę, Jerozolimo, miasto święte! Już bowiem nie wtargnie do ciebie nieobrzezany ani nieczysty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 2, 'Otrząśnij się z prochu, powstań i usiądź, Jerozolimo! Uwolnij się z okowów swojej szyi, pojmana córko Syjonu!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 3, 'Tak bowiem mówi Pan: Za darmo sprzedaliście się i bez pieniędzy zostaniecie odkupieni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 4, 'Tak bowiem mówi Pan Bóg: Mój lud niegdyś wstąpił do Egiptu, aby tam przebywać; ale Asyryjczyk bez przyczyny go trapił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 5, 'A teraz co mam czynić, mówi Pan, skoro mój lud został zabrany bez powodu, a ci, którzy panują nad nim, doprowadzają go do płaczu, mówi Pan, natomiast moje imię nieustannie każdego dnia jest bluźnione?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 6, 'Dlatego mój lud pozna moje imię. Dlatego pozna w tym dniu, że ja jestem tym, który mówi. Oto ja.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 7, 'O jak piękne są na górach nogi tego, kto zwiastuje dobre wieści i ogłasza pokój; tego, kto zwiastuje dobro i ogłasza zbawienie, kto mówi do Syjonu: Twój Bóg króluje!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 8, 'Twoi stróże podnoszą głos, tym głosem wspólnie wznoszą okrzyki, bo oko w oko ujrzą, jak Pan przywróci Syjon.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 9, 'Wykrzykujcie i śpiewajcie razem, ruiny Jerozolimy! Pan bowiem pocieszył swój lud, odkupił Jerozolimę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 10, 'Pan obnażył swoje święte ramię na oczach wszystkich narodów i wszystkie krańce ziemi zobaczą zbawienie naszego Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 11, 'Odstąpcie, odstąpcie, wyjdźcie stamtąd, nieczystego nie dotykajcie; wyjdźcie spośród niego; oczyśćcie się, wy, którzy nosicie naczynia Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 12, 'Nie wyjdziecie bowiem w pośpiechu ani nie będziecie uciekać, gdyż Pan pójdzie przed wami, a Bóg Izraela będzie za wami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 13, 'Oto się szczęśliwie powiedzie memu słudze. Będzie on wywyższony, wyniesiony i wielce uwielbiony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 14, 'Jak wielu przeraziło się z jego powodu, że zeszpecono jego wygląd bardziej niż innych ludzi, a jego postać – bardziej niż synów ludzkich;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 15, 'Tak też pokropi wiele narodów, królowie zamkną przed nim swoje usta, dlatego że ujrzą to, czego im nie powiedziano, i zrozumieją to, o czym nie słyszeli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 1, 'Któż uwierzył naszemu głoszeniu, a komu jest objawione ramię Pana?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 2, 'Wyrósł bowiem przed nim jak latorośl i jak korzeń z suchej ziemi. Nie miał kształtu ani urody; i gdy widzieliśmy go, nie było wyglądu, który by się nam podobał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 3, 'Wzgardzony i odrzucony przez ludzi; mąż boleści i doświadczony cierpieniem. I przed nim ukrywaliśmy jakby swoją twarz; wzgardzony tak, że mieliśmy go za nic.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 4, 'Zaprawdę on wziął na siebie nasze cierpienia i nosił naszą boleść. A my uważaliśmy, że jest zraniony, uderzony przez Boga i utrapiony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 5, 'Lecz on był zraniony za nasze występki, starty za nasze nieprawości. Kara dla naszego pokoju była na nim, a jego ranami zostaliśmy uzdrowieni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 6, 'Wszyscy jak owce zbłądziliśmy, każdy z nas zboczył na swą drogę, a Pan włożył na niego nieprawość nas wszystkich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 7, 'Uciśniony i gnębiony, ale nie otworzył swoich ust. Jak baranek na rzeź prowadzony i jak owca przed tymi, którzy ją strzygą, zamilkł i nie otworzył swoich ust.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 8, 'Został zabrany z więzienia i z sądu. Kto wypowie jego pokolenie? Został bowiem wyrwany z ziemi żyjących i zraniony za przestępstwo mojego ludu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 9, 'I wyznaczono mu grób z niegodziwcami, a z bogaczami była jego śmierć, choć nieprawości nie uczynił ani nie znaleziono fałszu w jego ustach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 10, 'Lecz spodobało się Panu zetrzeć go i zgnębić. A po złożeniu swojej duszy na ofiarę za grzech, ujrzy swoje potomstwo, przedłuży swoje dni i to, co się podoba Panu, przez jego rękę szczęśliwie się spełni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 11, 'Z udręki swojej duszy ujrzy owoc i nasyci się. Mój sprawiedliwy sługa swoim poznaniem usprawiedliwi wielu, bo sam poniesie ich nieprawości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 12, 'Dlatego dam mu dział wśród wielkich, aby dzielił się zdobyczami z mocarzami, ponieważ wylał swoją duszę na śmierć. Został zaliczony do przestępców, sam poniósł grzech wielu i wstawił się za przestępcami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 1, 'Śpiewaj, niepłodna, która nie rodziłaś, śpiewaj głośno i krzycz, która nie zaznałaś bólów rodzenia. Więcej bowiem jest synów opuszczonej niż synów zamężnej, mówi Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 2, 'Rozszerz miejsce swego namiotu, a niech rozciągają zasłony twoich mieszkań; nie oszczędzaj, wydłuż swoje powrozy i wzmocnij swoje kołki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 3, 'Rozprzestrzenisz się bowiem na prawo i lewo, a twoje potomstwo odziedziczy narody i zaludni spustoszone miasta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 4, 'Nie bój się, bo nie zostaniesz zawstydzona, nie rumień się, bo nie doznasz hańby, gdyż zapomnisz o wstydzie swojej młodości i o niesławie swego wdowieństwa już więcej nie wspomnisz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 5, 'Bo twoim małżonkiem jest twój Stwórca, Pan zastępów – to jego imię, a twoim Odkupicielem jest Święty Izraela – będzie nazywany Bogiem całej ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 6, 'Pan bowiem powołał cię jak żonę opuszczoną i przygnębioną na duchu, jak młodą żonę, gdy była porzucona, mówi twój Bóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 7, 'Na krótką chwilę cię opuściłem, ale w wielkim miłosierdziu przygarniam cię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 8, 'W niewielkim gniewie ukryłem na chwilę swoją twarz przed tobą, ale zlituję się nad tobą w wiecznym miłosierdziu, mówi Pan, twój Odkupiciel.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 9, 'Jest to bowiem dla mnie tak, jak było przy potopie Noego: jak przysięgałem, że wody Noego już więcej nie będą rozlewać się po ziemi, tak też przysięgałem, że nie rozgniewam się na ciebie ani nie będę cię gromić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 10, 'A choćby i góry się poruszyły i pagórki się zachwiały, moje miłosierdzie nie odstąpi od ciebie, a przymierze mojego pokoju nie zachwieje się, mówi Pan, który lituje się nad tobą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 11, 'O utrapiona, smagana wichrem, niepocieszona! Oto położę twoje kamienie na błyszczących kamieniach, a twoje fundamenty na szafirach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 12, 'I uczynię twoje okna z kryształu, twoje bramy z kamienia rubinowego i wszystkie twoje mury graniczne z drogich kamieni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 13, 'A wszystkie twoje dzieci będą wyuczone przez Pana, wielki będzie pokój twoich dzieci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 14, 'W sprawiedliwości będziesz utwierdzona, będziesz daleka od ucisku, bo nie będziesz się go bać; i od trwogi, bo nie zbliży się do ciebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 15, 'Oto zbiorą się razem, ale nie przeze mnie. Ktokolwiek zbierze się przeciwko tobie, upadnie ze względu na ciebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 16, 'Oto stworzyłem kowala, który dmie na węgiel w ogniu i wyciąga narzędzia do obróbki. Ja stworzyłem też burzyciela, aby niszczył.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 17, 'Żadna broń przeciw tobie sporządzona nie będzie skuteczna, a każdy język, który w sądzie występuje przeciw tobie, potępisz. To jest dziedzictwo sług Pana, a ich sprawiedliwość pochodzi ode mnie, mówi Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 1, 'O wszyscy spragnieni, przyjdźcie do wód, i wy, którzy nie macie pieniędzy, przyjdźcie, kupujcie i jedzcie; tak, przyjdźcie, kupujcie bez pieniędzy i bez zapłaty wino i mleko.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 2, 'Czemu wydajecie pieniądze nie na chleb, swoją pracę na to, co nie nasyci? Słuchajcie mnie uważnie, a jedzcie to, co jest dobre, i niech wasza dusza rozkoszuje się tłuszczem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 3, 'Nakłońcie swego ucha i przyjdźcie do mnie, słuchajcie, a wasza dusza będzie żyć. I zawrę z wami wieczne przymierze, pewne miłosierdzia Dawida.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 4, 'Oto ustanowiłem go świadkiem dla narodów, wodzem i dowódcą dla narodów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 5, 'Oto przywołasz naród, którego nie znałeś, a narody, które cię nie znały, zbiegną się do ciebie ze względu na Pana, twego Boga, i Świętego Izraela, bo on cię uwielbił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 6, 'Szukajcie Pana, póki może być znaleziony; wzywajcie go, póki jest blisko.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 7, 'Niech bezbożny opuści swoją drogę, a człowiek nieprawy swoje myśli i niech wróci do Pana, a on się zlituje; niech wróci do naszego Boga, gdyż jest on hojny w przebaczeniu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 8, 'Moje myśli bowiem nie są waszymi myślami ani wasze drogi nie są moimi drogami, mówi Pan;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 9, 'Ale jak niebiosa są wyższe niż ziemia, tak moje drogi przewyższają wasze drogi, a moje myśli – wasze myśli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 10, 'Bo jak spada deszcz i śnieg z nieba i już tam nie wraca, ale nawadnia ziemię i czyni ją płodną, czyni ją też urodzajną, tak że wydaje siewcy nasienie, a chleb jedzącym;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 11, 'Tak będzie z moim słowem, które wyjdzie z moich ust: nie wróci do mnie na próżno, ale uczyni to, co mi się podoba, i poszczęści mu się w tym, do czego je poślę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 12, 'Dlatego wyjdziecie z radością i w pokoju poprowadzą was. Góry i pagórki będą śpiewać głośno przed wami i wszystkie drzewa polne będą klaskać w dłonie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 13, 'Zamiast cierni wyrośnie cyprys, zamiast pokrzywy wyrośnie mirt. I będzie to dla Pana na chwałę, na wieczny znak, który nigdy nie będzie wymazany.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 1, 'Tak mówi Pan: Strzeżcie sądu i czyńcie sprawiedliwość, bo bliskie jest nadejście mojego zbawienia i objawienie się mojej sprawiedliwości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 2, 'Błogosławiony człowiek, który to czyni, i syn człowieczy, który się tego trzyma, który przestrzega szabatu, aby go nie bezcześcić, który strzeże swej ręki, aby nie czyniła nic złego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 3, 'Niech więc nie mówi cudzoziemiec, który przyłączył się do Pana: Pan na pewno odłączył mnie od swego ludu. Niech też eunuch nie mówi: Oto jestem suchym drzewem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 4, 'Tak bowiem mówi Pan o eunuchach, którzy przestrzegają moich szabatów i wybierają to, co mi się podoba, i trzymają się mojego przymierza:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 5, 'Dam im miejsce w swoim domu i w swoich murach oraz imię lepsze od synów i córek; dam im imię wieczne, które nie będzie zgładzone.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 6, 'A cudzoziemców, którzy przyłączyli się do Pana, aby mu służyć, miłować imię Pana i być jego sługami, wszystkich przestrzegających szabatu, by go nie bezcześcić, i trzymających się mojego przymierza;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 7, 'Tych przyprowadzę na swoją świętą górę i rozraduję ich w swoim domu modlitwy. Ich całopalenia i ofiary będą przyjęte na moim ołtarzu, bo mój dom będzie nazywany domem modlitwy dla wszystkich narodów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 8, 'Tak mówi Pan Bóg, który gromadzi rozproszonych z Izraela: Jeszcze innych zgromadzę do niego i do jego zgromadzonych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 9, 'Wszystkie zwierzęta polne, przyjdźcie na żer, i wy, wszystkie zwierzęta leśne.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 10, 'Jego stróżowie są ślepi wszyscy, nic nie wiedzą, wszyscy są niemymi psami, nie mogą szczekać; są ospali, leżą, kochają drzemać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 11, 'A są to psy żarłoczne i nienasycone; są to pasterze niezdolni do zrozumienia. Wszyscy udali się w swoją drogę, każdy w swoim miejscu szuka własnego zysku, mówiąc:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 12, 'Przyjdźcie, wezmę wino i upijemy się mocnym napojem; jutro będzie tak jak dziś i jeszcze bardziej obficie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 1, 'Sprawiedliwy ginie, a nikt nie bierze sobie tego do serca. Ludzie pobożni odchodzą, a nikt nie zważa na to, że sprawiedliwy jest zabierany przed nadejściem zła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 2, 'Dostąpi pokoju i odpocznie na swoim łożu każdy, kto postępuje uczciwie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 3, 'Ale wy zbliżcie się tutaj, synowie czarownicy, potomstwo cudzołożnika i nierządnicy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 4, 'Z kogo się naigrawacie? Na kogo rozdziawiacie usta i wywieszacie język? Czy nie jesteście synami nierządu, potomstwem fałszu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 5, 'Wy, którzy uprawiacie nierząd z posągami pod każdym zielonym drzewem, zabijając swoje dzieci przy potokach, pod wysokimi skałami?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 6, 'Wśród gładkich kamieni potoku jest twój dział. Właśnie one są twoim losem, na nie wylewasz ofiarę z płynów i ofiarowujesz ofiarę z pokarmów. Czyż w tym miałbym mieć upodobanie?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 7, 'Na górze wysokiej i wyniosłej postawiłaś swoje łoże i tam wstępowałaś, aby składać ofiary.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 8, 'A za drzwiami i za odrzwiami postawiłaś swoją pamiątkę, gdyż odchodząc ode mnie, odkrywałaś się innym, wstąpiłaś i rozszerzyłaś swoje łoże, czyniąc z nimi przymierze; kochałaś ich łoże w każdym miejscu, gdzie je widziałaś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 9, 'Chodziłaś także do króla z olejkiem i mnożyłaś swoje wonności; posłałaś daleko swoich posłańców, a poniżałaś się aż do grobu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 10, 'Zmęczyłaś się licznymi swymi drogami, ale nie powiedziałaś: Na próżno. Znalazłaś pomoc w swojej ręce, dlatego nie osłabłaś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 11, 'Kogo się bałaś i lękałaś, że skłamałaś, i nie pamiętałaś o mnie ani nie wzięłaś sobie tego do serca? Czy ja nie milczałem, i to od dawna, a ty mnie się nie boisz?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 12, 'Opowiem twoją sprawiedliwość i twoje uczynki, które nic ci nie pomogą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 13, 'Gdy zawołasz, niech wybawi cię twoja zgraja; ale wszystkich ich wiatr rozniesie i pochwyci marność. Lecz ten, który mi zaufa, odziedziczy ziemię i posiądzie moją świętą górę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 14, 'I powiedzą: Wyrównajcie, wyrównajcie, przygotujcie drogę, usuńcie przeszkody z drogi mojego ludu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 15, 'Tak bowiem mówi Wysoki i Wyniosły, który zamieszkuje wieczność, którego imię to Święty: Ja, który mieszkam na wysokościach, na miejscu świętym, mieszkam i z tym, który jest skruszony i uniżony w duchu, aby ożywić ducha pokornych i ożywić serce skruszonych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 16, 'Nie będę się spierał na wieki ani nie będę wiecznie się gniewał, bo zemdlałby przede mną duch i dusze, które uczyniłem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 17, 'Z powodu jego niegodziwej chciwości rozgniewałem się i uderzyłem go. Ukryłem się i rozgniewałem, on jednak był uparty i poszedł drogą swego serca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 18, 'Widziałem jego drogi, lecz uzdrowię go. Poprowadzę go i przywrócę mu pociechę, również tym, którzy z nim płaczą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 19, 'Stworzę owoc warg: Pokój, pokój dalekiemu i bliskiemu, mówi Pan; i tak uzdrowię go.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 20, 'Lecz bezbożni będą jak wzburzone morze niemogące się uspokoić, którego wody wyrzucają muł i błoto.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 21, 'Nie ma pokoju dla bezbożnych, mówi mój Bóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 1, 'Wołaj donośnie, nie wstrzymuj się, podnoś swój głos jak trąba i oznajmij mojemu ludowi ich przestępstwa, a domowi Jakuba ich grzechy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 2, 'Mimo że szukają mnie każdego dnia i chcą poznać moje drogi, niczym naród, który czyni sprawiedliwość i nie opuszcza sądu swego Boga. Pytają mnie o sądy sprawiedliwości i pragną zbliżyć się do Boga, mówiąc:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 3, 'Czemu pościmy, a tego nie widzisz? Czemu trapimy nasze dusze, a tego nie zauważasz? Oto w dzień waszego postu wykonujecie swoją wolę i żądacie wykonywania wszystkich prac.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 4, 'Oto pościcie dla kłótni i sporów i aby bić niegodziwą pięścią. Nie pośćcie tak, jak robicie dzisiaj, aby wasz głos był słyszany w górze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 5, 'Czy to jest ten post, który wybrałem, dzień, w którym człowiek trapi swoją duszę, żeby zwiesić swoją głowę jak sitowie i słać sobie posłanie z wora i popiołu? Czyż to nazwiesz postem i dniem przyjemnym dla Pana?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 6, 'Czy nie to jest tym postem, który wybrałem: rozerwać więzy niegodziwości, rozwiązać ciężkie brzemiona, puścić wolno uciśnionych i połamać wszelkie jarzmo;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 7, 'Dzielić swój chleb z głodnym i ubogich wygnańców wprowadzić do swego domu, a widząc nagiego, przyodziać go i nie ukrywać się przed nikim, kto jest twoim ciałem?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 8, 'Wtedy twoje światło zabłyśnie jak poranna zorza i twoje zdrowie szybko zakwitnie. Twoja sprawiedliwość pójdzie przed tobą i chwała Pana będzie za tobą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 9, 'Wtedy będziesz wzywał, a Pan wysłucha; zawołasz, a odpowie: Oto jestem. Jeśli usuniesz spośród siebie jarzmo, przestaniesz wytykać palcem i mówić nieprawości;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 10, 'Jeśli otworzysz swoją duszę głodnemu i nasycisz duszę utrapioną, wtedy twoje światło wzejdzie wśród ciemności, a twój zmierzch będzie jak południe.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 11, 'I Pan nieustannie będzie cię prowadził i nasyci twoją duszę w czasie suszy, i utuczy twoje kości. I będziesz jak nawodniony ogród i jak źródło wody, którego wody nie ustają.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 12, 'Twoi potomni odbudują starodawne ruiny, wzniesiesz fundamenty wielu pokoleń i nazwą cię naprawcą wyłomów i odnowicielem ścieżek na zamieszkanie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 13, 'Jeśli powstrzymasz swoją nogę od przekraczania szabatu, aby nie wykonać swojej woli w moim świętym dniu; jeśli nazwiesz szabat rozkoszą, dzień święty Pana – szanownym; jeśli go uczcisz, nie czyniąc swoich spraw ani nie wykonując swojej woli, ani nie mówiąc słowa próżnego;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 14, 'Wtedy będziesz rozkoszował się Panem, a wprowadzę cię na wysokie miejsca ziemi i nakarmię cię dziedzictwem Jakuba, twego ojca. Tak bowiem powiedziały usta Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 1, 'Oto ręka Pana nie jest skrócona, aby nie mogła zbawić, ani jego ucho nie jest przytępione, aby nie mogło wysłuchać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 2, 'Ale wasze nieprawości uczyniły przepaść między wami a waszym Bogiem i wasze grzechy sprawiły, że ukrył twarz przed wami, tak że nie słyszy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 3, 'Wasze ręce bowiem są splamione krwią, a wasze palce – nieprawością. Wasze wargi mówią kłamstwa, a wasz język szepce przewrotności.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 4, 'Nikt nie woła o sprawiedliwość i nikt się nie spiera o prawdę. Ufają marności i mówią kłamstwa, wyrządzają krzywdę i rodzą nieprawość.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 5, 'Wylęgają jaja węża i tkają pajęczynę. Kto spożywa ich jaja, umiera, a jeśli je stłucze, wykluwa się żmija.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 6, 'Ich pajęczyny nie nadają się na szatę ani nie okryją się swoimi uczynkami. Ich uczynki to uczynki nieprawości i w ich rękach są czyny przemocy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 7, 'Ich nogi biegną do zła i spieszą się do przelewania niewinnej krwi. Ich myśli są myślami nieprawości, spustoszenie i zniszczenie na ich drogach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 8, 'Drogi pokoju nie znają i nie ma na ich drogach sprawiedliwości. Uczynili sobie kręte ścieżki; ten, kto po nich chodzi, nie zazna pokoju.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 9, 'Dlatego sąd jest daleki od nas i nie dociera do nas sprawiedliwość. Czekamy na światłość – a oto ciemność, na jasność – ale kroczymy w mrokach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 10, 'Macamy ściany jak ślepi, macamy, jakbyśmy oczu nie mieli. Potykamy się w południe jak o zmierzchu; w miejscach opustoszałych – jak umarli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 11, 'Ryczymy wszyscy jak niedźwiedzie, jak gołębie ciągle wzdychamy; oczekujemy sądu, ale go nie ma; oczekujemy na wybawienie, ale jest od nas daleko.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 12, 'Rozmnożyły się bowiem nasze przestępstwa przed tobą i nasze grzechy świadczą przeciwko nam, ponieważ nasze nieprawości są przy nas i uznajemy swoje przestępstwa;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 13, 'Zgrzeszyliśmy i kłamaliśmy przeciw Panu i odwróciliśmy się od naszego Boga, aby nie chodzić za nim; mówiliśmy o ucisku i buncie, obmyślaliśmy i wypowiadaliśmy słowa kłamliwe ze swego serca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 14, 'Dlatego sąd został wycofany i sprawiedliwość stoi z daleka, bo prawda runęła na ulicy, a prawość nie może tam wejść.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 15, 'Tak, prawda zginęła, a ten, kto odstępuje od zła, pada ofiarą łupu. Pan to widział i nie podobało mu się, że nie ma sądu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 16, 'Widział, że nie ma żadnego człowieka i zdziwił się, że nie ma nikogo, kto by się wstawił. Dlatego jego ramię przyniosło mu zbawienie i jego własna sprawiedliwość była jego podporą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 17, 'Przyodział się bowiem w sprawiedliwość jak w pancerz i włożył hełm zbawienia na swą głowę. Przyoblekł się w odzienie pomsty jak w szatę i okrył się gorliwością jak płaszczem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 18, 'Według uczynków, stosownie do nich, odpłaci gniewem swoim przeciwnikom, odwetem swoim wrogom; wyspom odpłaci odwetem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 19, 'I ci, którzy są na zachodzie, będą się bali imienia Pana, i ci, którzy na wschodzie – jego chwały. Gdy wróg przyjdzie jak rzeka, Duch Pana przepędzi go.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 20, 'Przyjdzie bowiem Odkupiciel do Syjonu i do tych spośród Jakuba, którzy odwracają się od występków, mówi Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 21, 'A to będzie moje przymierze z nimi, mówi Pan: Mój Duch, który jest w tobie, i moje słowa, które włożyłem w twoje usta, nie odstąpią od twoich ust ani od ust twego potomstwa, ani od ust potomków twego potomstwa, mówi Pan, odtąd aż na wieki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 1, 'Powstań, zajaśniej, ponieważ przyszła twoja światłość i chwała Pana wzeszła nad tobą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 2, 'Oto bowiem ciemność okryje ziemię i mrok – ludy, ale nad tobą wzejdzie Pan i jego chwała pojawi się nad tobą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 3, 'I pójdą narody do twojej światłości, a królowie do blasku twojego wschodu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 4, 'Podnieś wokoło swe oczy i spójrz: ci wszyscy, którzy się zgromadzili, przyjdą do ciebie. Twoi synowie przyjdą z daleka i twoje córki będą wychowane przy twoim boku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 5, 'Wtedy zobaczysz i rozweselisz się, twoje serce zadrży i rozszerzy się, gdyż nawróci się do ciebie tłum morski, a siły narodów przyjdą do ciebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 6, 'Okryje cię mnóstwo wielbłądów, dromadery z Midianu i Efy. Przyjdą wszyscy z Szeby, przyniosą złoto i kadzidło i będą głosić chwałę Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 7, 'Wszystkie stada Kedaru zgromadzą się u ciebie, barany Nebajotu będą ci służyć: wstąpią na mój ołtarz, gdzie będą przyjęte; i tak ozdobię dom mego majestatu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 8, 'I powiesz: Kim są ci, co nadciągają jak obłoki i jak gołębie do swoich okien?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 9, 'Zaprawdę wyspy oczekują mnie, a na czele okręty Tarszisz, aby przyprowadzić twoich synów z daleka, a z nimi ich srebro i złoto, do imienia Pana, twego Boga, i do Świętego Izraela, bo cię uwielbił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 10, 'Synowie cudzoziemców odbudują twoje mury i ich królowie będą ci służyć, gdyż w moim gniewie uderzyłem cię, a w mojej łaskawości zlitowałem się nad tobą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 11, 'I twoje bramy będą nieustannie otwarte, nie będą zamknięte ani w dzień, ani w nocy, aby można było przyprowadzić do ciebie siły narodów, i aby ich królowie byli przyprowadzeni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 12, 'Ten naród i królestwo, które nie będą ci służyć, zginą. Takie narody właśnie zostaną do szczętu spustoszone.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 13, 'Chwała Libanu przyjdzie do ciebie: razem cyprys, sosna oraz bukszpan, na ozdobę miejsca mojej świątyni. I wsławię miejsce moich nóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 14, 'Przyjdą też do ciebie w pokorze synowie tych, którzy cię trapili, i będą się kłaniać do twoich stóp wszyscy ci, którzy tobą wzgardzili. I nazwą cię Miastem Pana, Syjonem Świętego Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 15, 'Za to, że byłaś opuszczona i znienawidzona tak, że nie było nikogo, kto by przez ciebie przechodził, uczynię cię wiecznym dostojeństwem, radością z pokolenia na pokolenie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 16, 'Będziesz ssać mleko narodów i piersiami królów będziesz karmiona. I poznasz, że ja jestem Panem, twoim Zbawicielem i twoim Odkupicielem, Mocarzem Jakuba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 17, 'Zamiast miedzi naniosę złota, a zamiast żelaza naniosę srebra, zamiast drewna – miedzi, a zamiast kamieni – żelazo. Ustanowię nad tobą spokojnych zwierzchników i urzędników sprawiedliwych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 18, 'Nie będzie więcej słychać o przemocy w twojej ziemi ani o spustoszeniu i zniszczeniu w twoich granicach; ale nazwiesz swoje mury Zbawieniem, a twoje bramy – Chwałą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 19, 'Słońce nie będzie już twoją światłością za dnia ani księżyc już nie zaświeci ci swoim blaskiem; ale Pan będzie twoją wieczną światłością, a twój Bóg – twoją chwałą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 20, 'Nie zajdzie już więcej twoje słońce, a twój księżyc nie ukryje się, bo Pan będzie twoją wieczną światłością i skończą się dni twojej żałoby.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 21, 'Cały twój lud będzie sprawiedliwy. Odziedziczy ziemię na wieki, będzie latoroślą mego szczepu, dziełem moich rąk, abym był uwielbiony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 22, 'Najmniejszy rozmnoży się tysiąckrotnie, a malutki – w naród potężny. Ja, Pan, dokonam tego rychło, w swoim czasie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 1, 'Duch Pana Boga jest nade mną, bo Pan mnie namaścił, abym głosił dobrą nowinę cichym, posłał mnie, abym opatrzył rany skruszonym w sercu, abym zwiastował uwięzionym wyzwolenie, a związanym otworzenie więzienia;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 2, 'Abym ogłosił miłościwy rok Pana i dzień pomsty naszego Boga; abym pocieszył wszystkich płaczących;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 3, 'Abym sprawił radość płaczącym w Syjonie i dał im ozdobę zamiast popiołu, olejek radości zamiast smutku, szatę chwały zamiast ducha przygnębienia; i będą nazwani drzewami sprawiedliwości, szczepem Pana, aby był uwielbiony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 4, 'I odbudują starodawne ruiny, naprawią dawne spustoszenia i odnowią zniszczone miasta, opustoszałe od wielu pokoleń.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 5, 'I stawią się cudzoziemcy, i będą paść wasze stada, a synowie cudzoziemców będą waszymi oraczami i winogrodnikami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 6, 'Ale wy będziecie nazwani kapłanami Pana, będą was nazywać sługami naszego Boga. Będziecie korzystać z bogactwa narodów i będziecie się chlubić ich chwałą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 7, 'Za waszą hańbę wynagrodzę wam podwójnie, a zamiast wstydzić się, będziecie śpiewać; dlatego posiądziecie podwójne dziedzictwo z ich działu i w ich ziemi. I będziecie mieć wieczną radość.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 8, 'Ja bowiem, Pan, miłuję sąd i nienawidzę grabieży dla całopalenia; dlatego sprawię, by wykonali swoje dzieła w prawdzie i zawrę z nimi wieczne przymierze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 9, 'Ich potomstwo będzie znane wśród pogan, a ich potomkowie pośród ludów; wszyscy, którzy ich zobaczą, poznają, że są potomstwem błogosławionym przez Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 10, 'Będę się wielce radować w Panu i moja dusza rozraduje się w moim Bogu, bo przyoblekł mnie w szaty zbawienia i przyodział mnie w płaszcz sprawiedliwości, jak przyozdobionego oblubieńca i jak oblubienicę ozdobioną swoimi klejnotami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 11, 'Jak ziemia bowiem wydaje swe plony i jak ogród wydaje nasienie, tak Pan Bóg sprawi, że wzejdzie sprawiedliwość i chwała przed wszystkimi narodami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 1, 'Ze względu na Syjon nie będę milczeć, ze względu na Jerozolimę nie spocznę, dopóki jego sprawiedliwość nie wzejdzie jak blask i jego zbawienie nie zapłonie jak pochodnia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 2, 'I ujrzą narody twoją sprawiedliwość i wszyscy królowie – twoją chwałę. I nazwą cię nowym imieniem, które usta Pana ustalą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 3, 'I będziesz koroną chwały w ręku Pana i królewskim diademem w ręce twego Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 4, 'Nie będą cię więcej zwać Opuszczoną ani twoja ziemia nie będzie więcej nazwana Spustoszoną. Ale ty będziesz nazywana Chefsiba, a twoja ziemia Beula, bo Pan ma w tobie upodobanie i twoja ziemia będzie poślubiona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 5, 'Jak bowiem młodzieniec poślubia dziewicę, tak twoi synowie cię poślubią. I jak oblubieniec raduje się z oblubienicy, tak twój Bóg będzie się radować z ciebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 6, 'Na twoich murach, Jerozolimo, postawiłem stróżów, którzy przez cały dzień i całą noc nigdy nie zamilkną. Wy, którzy wspominacie Pana, nie milczcie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 7, 'I nie dajcie mu odpoczynku, dopóki nie utwierdzi i dopóki nie uczyni Jerozolimy chwałą na ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 8, 'Pan przysiągł na swoją prawicę i na ramię swojej mocy: Nie wydam już twojej pszenicy na pokarm twoim wrogom, a synowie cudzoziemców nie będą pić twego wina, przy którym się trudziłaś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 9, 'Ale ci, którzy je zgromadzą, będą je spożywać i chwalić Pana; a ci, którzy je zbierają, będą je pić w dziedzińcach mojej świątyni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 10, 'Przechodźcie, przechodźcie przez bramy! Torujcie drogę ludowi; wyrównajcie, wyrównajcie gościńce; usuwajcie kamienie, podnieście sztandar dla narodów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 11, 'Oto Pan rozkaże wołać aż po krańce ziemi: Powiedzcie córce Syjonu: Oto nadchodzi twój Zbawiciel, oto jego zapłata z nim, a jego dzieło przed nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 12, 'Twoich synów nazwą Ludem Świętym, Odkupionymi Pana, a ciebie nazwą Poszukiwaną, Miastem Nieopuszczonym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 1, 'Kim jest ten, który przybywa z Edomu, w farbowanych szatach z Bosry? Ten wspaniały w swoich szatach, kroczący w swojej wielkiej mocy? To ja jestem, który mówię w sprawiedliwości, potężny w wybawieniu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 2, 'Dlaczego twoja odzież jest czerwona? A twoje szaty jak u tego, który tłoczy w prasie?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 3, 'Sam jeden tłoczyłem prasę i spośród ludu nie było ze mną nikogo. Tłoczyłem go w swoim gniewie i deptałem go w swojej zapalczywości, aż pryskała jego krew na moje szaty, poplamiłem całą swą odzież.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 4, 'Dzień pomsty był bowiem w moim sercu, a rok moich odkupionych nadszedł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 5, 'Rozglądałem się, ale nie było pomocnika, zdumiałem się, że nikogo nie było, kto by mnie podparł. Dlatego moje ramię przyniosło mi zbawienie, a moja zapalczywość – ona mnie podparła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 6, 'Zdeptałem narody w swoim gniewie, upoiłem je w swojej zapalczywości i uderzyłem o ziemię ich mocarzy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 7, 'Będę wspominać miłosierdzie Pana i chwałę Pana za wszystko, co nam Pan wyświadczył, i za wielką dobroć, którą okazał domowi Izraela według swego miłosierdzia i według swojej wielkiej łaskawości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 8, 'Powiedział bowiem: Na pewno są moim ludem, synami, którzy mi się nie sprzeniewierzą. I tak stał się ich Zbawicielem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 9, 'We wszelkim ich ucisku i on był uciśniony, a Anioł jego oblicza zbawił ich. W swojej miłości i litości on ich odkupił. Troszczył się o nich i nosił ich przez wszystkie dni wieków.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 10, 'Ale oni się zbuntowali i zasmucili jego Świętego Ducha. Dlatego zamienił się w ich wroga i walczył przeciwko nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 11, 'Wówczas wspomniał dawne dni, Mojżesza i jego lud, mówiąc: Gdzież jest ten, który ich wyprowadził z morza, z pasterzem swojej trzody? Gdzież jest ten, który włożył w jego wnętrze swego Świętego Ducha?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 12, 'Który prowadził ich prawicą Mojżesza dzięki swemu chwalebnemu ramieniu i rozdzielił wody przed nimi, aby uczynić sobie wieczne imię?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 13, 'Który ich przeprowadził przez głębiny, jak konia na pustyni, tak że się nie potknęli?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 14, 'Jak bydło schodzące w dolinę tak Duch Pana spokojnie ich prowadził. Tak prowadziłeś swój lud, aby uczynić sobie chwalebne imię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 15, 'Spójrz z nieba i popatrz z przybytku swojej świętości i chwały. Gdzie twoja gorliwość i twoja wielka siła? Gdzie poruszenie twoich uczuć i litości przede mną? Czy powstrzymałeś je?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 16, 'Przecież ty jesteś naszym ojcem, bo Abraham nas nie zna, a Izrael nas nie uznaje. Ty, Panie, jesteś naszym ojcem, naszym Odkupicielem; twoje imię jest od wieków.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 17, 'Czemu, Panie, pozwoliłeś nam zboczyć z twoich dróg i zatwardziłeś nasze serce, abyśmy się ciebie nie bali? Odwróć się ze względu na twoje sługi, pokolenia twego dziedzictwa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 18, 'Lud posiadł ją na krótki czas, nasi wrogowie zaś zdeptali twoją świątynię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 19, 'My jesteśmy twoi. Nad nimi nigdy nie panowałeś ani nie byli nazywani twoimi imieniem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 1, 'Obyś rozdarł niebiosa i zstąpił, aby góry rozpłynęły się przed tobą;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 2, 'Jak płonie ogień rozżarzony, ogień, który doprowadza wodę do wrzenia, abyś oznajmił swoje imię twoim wrogom, tak by narody zadrżały przed tobą;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 3, 'Jak kiedyś, gdy czyniłeś rzeczy przedziwne, których się nie spodziewaliśmy; zstąpiłeś, a góry rozpływały się przed tobą!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 4, 'Czego od początku świata nie słyszano ani do uszu nie dochodziło, ani oko nie widziało oprócz ciebie samego, Boże, który by tak uczynił dla tego, który go oczekuje.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 5, 'Wychodzisz naprzeciw radosnego i czyniącego sprawiedliwość, i tych, którzy krocząc po twoich drogach pamiętają o tobie. Oto się rozgniewałeś, gdyż grzeszyliśmy ustawicznie, nie krocząc po tych drogach, lecz będziemy zbawieni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 6, 'My wszyscy jednak jesteśmy jak nieczyści, a wszystkie nasze sprawiedliwości są jak szata splugawiona; wszyscy opadliśmy jak liść, a nasze nieprawości uniosły nas jak wiatr.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 7, 'I nie ma nikogo, kto by wzywał twego imienia i zbudził się, aby się ciebie chwycić. Zakryłeś bowiem swoje oblicze przed nami i sprawiłeś, że niszczejemy z powodu naszych nieprawości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 8, 'Ale teraz, Panie, ty jesteś naszym ojcem, my jesteśmy gliną, a ty jesteś naszym garncarzem; i jesteśmy wszyscy dziełem twojej ręki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 9, 'Nie gniewaj się, Panie, tak bardzo i nie pamiętaj o naszych nieprawościach na wieki. Oto spójrz, prosimy, my wszyscy jesteśmy twoim ludem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 10, 'Twoje święte miasta zostały obrócone w pustynię, Syjon jest pustynią, Jerozolima stała się spustoszeniem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 11, 'Nasz dom, święty i wspaniały, w którym cię chwalili nasi ojcowie, został spalony w ogniu, i wszystkie nasze najkosztowniejsze rzeczy leżą w gruzach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 12, 'Czy wobec tego powstrzymasz się, Panie? Czy będziesz milczeć i tak bardzo nas trapić?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 1, 'Objawiłem się tym, którzy o mnie nie pytali, zostałem znaleziony przez tych, którzy mnie nie szukali. Do narodu, który się nie nazywał moim imieniem, mówiłem: Oto jestem, oto jestem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 2, 'Cały dzień wyciągałem swoje ręce do ludu buntowniczego, który kroczy drogą niedobrą, za własnymi myślami;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 3, 'Do ludu, który stale i zuchwale pobudza mnie do gniewu, składając ofiary w ogrodach i paląc kadzidło na cegłach;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 4, 'Który przesiaduje na grobach i nocuje przy swoich bożkach, który je mięso wieprzowe, a obrzydliwa polewka jest w jego naczyniach;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 5, 'I mówi: Odsuń się, nie zbliżaj się do mnie, bo jestem świętszy od ciebie. On jest dymem w moich nozdrzach i ogniem płonącym przez cały dzień.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 6, 'Oto zapisano to przede mną. Nie zamilknę, ale oddam i odpłacę im w zanadrzu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 7, 'Za wasze nieprawości i nieprawości waszych ojców, mówi Pan, którzy palili kadzidło na górach i hańbili mnie na pagórkach; dlatego wymierzę im w zanadrze za ich dawne czyny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 8, 'Tak mówi Pan: Jak wtedy, gdy znajduje się wino w kiści i mówi się: Nie psuj go, bo w nim jest błogosławieństwo, tak i ja uczynię przez wzgląd na moje sługi – nie zniszczę ich wszystkich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 9, 'Bo wywiodę z Jakuba potomstwo, a z Judy dziedzica moich gór. Moi wybrani posiądą je i moi słudzy będą tam mieszkać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 10, 'A Szaron stanie się pastwiskiem dla owiec, a dolina Akor legowiskiem dla wołów – to dla mojego ludu, który mnie szukał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 11, 'Ale was, którzy opuściliście Pana, którzy zapominacie o mojej świętej górze, którzy zastawiacie stół dla tego wojska i składacie ofiary z płynów temu mnóstwu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 12, 'Was przeznaczę pod miecz i wy wszyscy schylicie się na rzeź, ponieważ wołałem, a nie odezwaliście się, mówiłem, a nie słyszeliście, ale czyniliście to, co złe w moich oczach, i wybraliście to, co mi się nie podobało.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 13, 'Dlatego tak mówi Pan Bóg: Oto moi słudzy będą jeść, a wy będziecie głodni. Oto moi słudzy będą pić, a wy będziecie spragnieni. Oto moi słudzy będą się radować, a wy będziecie zawstydzeni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 14, 'Oto moi słudzy będą śpiewać z radości serca, a wy będziecie krzyczeć z boleści serca i zawodzić z powodu zrozpaczonego ducha.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 15, 'I zostawicie swoje imię moim wybranym na przekleństwo, gdyż Pan Bóg zabije was, a swoje sługi nazwie innym imieniem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 16, 'Ten, który będzie sobie błogosławił na ziemi, będzie sobie błogosławił w Bogu prawdziwym, a kto będzie przysięgał na ziemi, będzie przysięgał na Boga prawdziwego, bo dawne uciski pójdą w zapomnienie i będą zakryte przed moimi oczami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 17, 'Oto bowiem stworzę nowe niebiosa i nową ziemię i nie będą wspominane pierwsze rzeczy ani nie przyjdą na myśl.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 18, 'Lecz weselcie się i radujcie na wieki wieków z tego, co ja stworzę, bo oto stworzę Jerozolimę radością i jej lud weselem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 19, 'I będę się radować z powodu Jerozolimy i weselić z powodu mojego ludu, a nie będzie już słychać w nim głosu płaczu ani narzekania.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 20, 'Nie będzie tam już ani niemowlęcia żyjącego tylko kilka dni, ani starca, który by nie dożył swoich dni, bo dziecko umrze jako stuletni, ale grzesznik, choćby miał i sto lat, będzie przeklęty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 21, 'Pobudują też domy i będą w nich mieszkać, zasadzą winnice i będą jeść z nich owoce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 22, 'Nie będą budować, by ktoś inny tam mieszkał, nie będą sadzić, by ktoś inny jadł, bo dni mojego ludu będą jak dni drzewa i moi wybrani długo będą korzystać z dzieła swoich rąk.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 23, 'Nie będą trudzić się na próżno ani rodzić, aby się bać, gdyż są potomstwem błogosławionym przez Pana, oni i ich potomkowie wraz z nimi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 24, 'I będzie tak, że zanim zawołają, ja się odezwę, gdy jeszcze będą mówić, ja wysłucham.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 25, 'Wilk z barankiem paść się będą razem, lew jak wół będzie jeść słomę i proch będzie pokarmem węża. Nie będą szkodzić ani niszczyć na całej mojej świętej górze, mówi Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 1, 'Tak mówi Pan: Niebo jest moim tronem, a ziemia podnóżkiem moich stóp. Gdzie więc będzie ten dom, który mi zbudujecie? Gdzie będzie miejsce mego odpoczynku?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 2, 'Bo to wszystko moja ręka uczyniła i dzięki niej powstało to wszystko, mówi Pan. Lecz ja patrzę na tego, który jest ubogi i skruszony w duchu i który drży na moje słowo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 3, 'Ten, kto zabija wołu na ofiarę, to jakby zabił człowieka; kto zabija na ofiarę barana, to jakby ściął psu głowę; kto przynosi ofiarę, to jakby ofiarował krew świni; kto pali kadzidło, to jakby błogosławił bożkowi. Lecz jak oni wybrali sobie swoje drogi i ich dusza ma upodobanie w obrzydliwościach;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 4, 'Tak i ja wybiorę ich zmyślenia i sprowadzę na nich to, czego się boją, ponieważ gdy wołałem, nikt się nie odezwał, gdy mówiłem, nie słuchali, ale czynili to, co złe w moich oczach, i wybrali to, co mi się nie podobało.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 5, 'Słuchajcie słowa Pana, wy, którzy drżycie na jego słowo. Wasi bracia, którzy was nienawidzą, którzy wypędzają was ze względu na moje imię, mówią: Niech Pan pokaże swoją chwałę. Ukaże się jednak dla waszej radości, a oni będą zawstydzeni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 6, 'Odgłos zgiełku z miasta, głos ze świątyni, głos Pana oddającego zapłatę swoim wrogom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 7, 'Zanim odczuła bóle porodu, urodziła, zanim ogarnął ją ból, urodziła chłopca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 8, 'Kto słyszał o czymś takim? Kto widział coś podobnego? Czy ziemia może urodzić w jednym dniu? Czy naród rodzi się od razu? Ale Syjon ledwie zaczął odczuwać bóle, a już urodził swoich synów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 9, 'Czyżbym ja, który otwieram łono, nie doprowadził do rodzenia? – mówi Pan. Czyżbym ja, który doprowadzam do rodzenia, zamknął łono? – mówi twój Bóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 10, 'Weselcie się z Jerozolimą i radujcie się z nią wszyscy, którzy ją miłujecie. Cieszcie się z nią wielce wszyscy, którzy nad nią płaczecie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 11, 'Aby ssać do syta z piersi jej pociech; abyście ssali i rozkoszowali się pełnią jej chwały.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 12, 'Tak bowiem mówi Pan: Oto skieruję do niej pokój jak rzekę i chwałę narodów jak strumień wezbrany. Wtedy będziecie ssać, będziecie noszeni na rękach i pieszczeni na kolanach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 13, 'Jak tego, którego pociesza matka, tak ja was będę pocieszał; i tak w Jerozolimie doznacie pociechy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 14, 'Ujrzycie to i rozraduje się wasze serce, a wasze kości zakwitną jak trawa. I będzie rozpoznana ręka Pana wobec jego sług, a jego gniew – wobec jego wrogów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 15, 'Oto bowiem Pan przyjdzie w ogniu, a jego rydwany będą jak wicher, by wylać zapalczywość swego gniewu i ukazać swoją grozę w płomieniu ognia;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 16, 'Gdyż Pan będzie sądził ogniem i mieczem wszelkie ciało, a wielu będzie pobitych przez Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 17, 'I ci, którzy się uświęcają i oczyszczają w środku ogrodów, jeden za drugim, którzy jedzą mięso wieprzowe oraz inną obrzydliwość, a także myszy, wszyscy razem zginą – mówi Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 18, 'Ja znam bowiem ich uczynki i myśli. I przyjdzie czas, że zgromadzę wszystkie narody i języki, a one przyjdą i ujrzą moją chwałę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 19, 'I ustanowię wśród nich znak i wyślę ocalałych spośród nich do narodów do Tarszisz, Pul i Lud, a tych, którzy naciągają łuk – do Tubala i Jawan, do wysp dalekich, które nic o mnie nie słyszały i nie widziały mojej chwały; i będą głosić moją chwałę wśród narodów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 20, 'I przyprowadzą wszystkich waszych braci jako dar dla Pana ze wszystkich narodów, na koniach, na rydwanach, w lektykach, na mułach i na wielbłądach, na moją świętą górę, do Jerozolimy, mówi Pan, tak jak synowie Izraela przynoszą dar w czystym naczyniu do domu Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 21, 'I z nich także wezmę sobie kapłanów i Lewitów, mówi Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 22, 'Jak bowiem to nowe niebo i ta nowa ziemia, które ja uczynię, będą trwać przede mną, mówi Pan, tak będzie trwać wasze potomstwo i wasze imię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 23, 'I stanie się tak, że od nowiu do nowiu księżyca i od szabatu do szabatu przychodzić będzie wszelkie ciało, aby oddać pokłon przede mną, mówi Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 24, 'I gdy wyjdą, zobaczą trupy ludzi, którzy wystąpili przeciwko mnie. Ich robak bowiem nie zdechnie i ich ogień nie zgaśnie, i będą obrzydliwością dla wszelkiego ciała.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 1, 'Słowa Jeremiasza, syna Chilkiasza, z rodu kapłanów, którzy byli w Anatot, w ziemi Beniamina;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 2, 'Do którego doszło słowo Pana za dni Jozjasza, syna Amona, króla Judy, w trzynastym roku jego panowania.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 3, 'Doszło także za dni Joakima, syna Jozjasza, króla Judy, aż do końca jedenastego roku Sedekiasza, syna Jozjasza, króla Judy, aż do uprowadzenia do niewoli mieszkańców Jerozolimy w piątym miesiącu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 4, 'Doszło do mnie słowo Pana mówiące:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 5, 'Zanim ukształtowałem cię w łonie, znałem cię, zanim wyszedłeś z łona, uświęciłem cię i ustanowiłem prorokiem dla narodów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 6, 'Wtedy powiedziałem: Ach, Panie Boże! Oto nie umiem mówić, bo jestem dzieckiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 7, 'Ale Pan powiedział do mnie: Nie mów: Jestem dzieckiem. Pójdziesz bowiem, do kogokolwiek cię poślę, i będziesz mówił, cokolwiek ci rozkażę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 8, 'Nie bój się ich twarzy, bo ja jestem z tobą, aby cię wybawić, mówi Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 9, 'Wtedy Pan wyciągnął swoją rękę i dotknął moich ust. I powiedział do mnie Pan: Oto wkładam moje słowa do twoich ust.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 10, 'Patrz, dziś ustanawiam cię nad narodami i królestwami, abyś wykorzeniał, burzył, wytracał i niszczył, byś budował i sadził.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 11, 'Potem doszło do mnie słowo Pana mówiące: Co widzisz, Jeremiaszu? I odpowiedziałem: Widzę gałązkę migdałowca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 12, 'I Pan powiedział do mnie: Dobrze widzisz. Ja bowiem przyspieszam swoje słowo, aby je wykonać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 13, 'Ponownie doszło do mnie słowo Pana mówiące: Co widzisz? Odpowiedziałem: Widzę wrzący kocioł, a jego przednia strona skierowana jest ku północy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 14, 'I Pan powiedział do mnie: Od północy spadnie nieszczęście na wszystkich mieszkańców tej ziemi;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 15, 'Bo oto zwołam wszystkie rody z królestw północnych, mówi Pan, i przyjdą, a każdy z nich ustawi swój tron u wejścia do bram Jerozolimy, przeciw wszystkim jej murom i przeciw miastom Judy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 16, 'I ogłoszę przeciwko nim moje sądy za całą ich niegodziwość: przeciwko tym, którzy mnie opuścili, palili kadzidło innym bogom i oddali pokłon dziełom swoich rąk.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 17, 'Dlatego ty przepasz swoje biodra, wstań i mów do nich wszystko, co ci nakazuję. Nie bój się ich twarzy, bym cię nie napełnił lękiem przed nimi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 18, 'Oto bowiem ustanawiam cię dziś miastem obronnym, żelazną kolumną i murem spiżowym przeciwko całej tej ziemi, przeciwko królom Judy, ich książętom, ich kapłanom i ludowi tej ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 19, 'I będą walczyć przeciwko tobie, ale cię nie przemogą, bo ja jestem z tobą, mówi Pan, aby cię wybawić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 1, 'I doszło do mnie słowo Pana mówiące:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 2, 'Idź i wołaj do uszu Jerozolimy tymi słowy: Tak mówi Pan: Wspominam cię, życzliwość twojej młodości i miłość twojego narzeczeństwa, gdy chodziłaś za mną na pustyni, w ziemi nieobsiewanej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 3, 'Izrael był świętością dla Pana i pierwocinami jego plonu. Wszyscy, którzy go pożerali, ściągali na siebie winę, spadało na nich nieszczęście, mówi Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 4, 'Słuchajcie słowa Pana, domu Jakuba, i wszystkie rody domu Izraela!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 5, 'Tak mówi Pan: Jaką nieprawość znaleźli we mnie wasi ojcowie, że oddalili się ode mnie, poszli za marnością i stali się próżni?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 6, 'I nie pytali: Gdzie jest Pan, który nas wyprowadził z ziemi Egiptu, który nas prowadził przez pustkowie, przez ziemię pustą i pełną rozpadlin, przez ziemię suszy i cienia śmierci, przez ziemię, po której nikt nie chodził i gdzie żaden człowiek nie mieszkał?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 7, 'Ja was wprowadziłem do ziemi obfitej, abyście spożywali jej owoce i dobra, lecz gdy weszliście, splugawiliście moją ziemię i moje dziedzictwo uczyniliście obrzydliwością.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 8, 'Kapłani nie pytali: Gdzie jest Pan? Ci, którzy zajmowali się prawem, nie poznali mnie. Pasterze odstąpili ode mnie i prorocy prorokowali przez Baala, i chodzili za bezużytecznymi rzeczami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 9, 'Dlatego będę wiódł spór z wami, mówi Pan, i z synami waszych synów będę się spierać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 10, 'Przejdźcie bowiem na wyspy Kittim i zobaczcie; poślijcie do Kedaru i rozważcie dokładnie, przypatrzcie się, czy zdarzyło się coś podobnego:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 11, 'Czy jakiś naród zmienił swoich bogów, choć ci nie są bogami? Ale mój lud zamienił swoją chwałę na to, co jest nieużyteczne.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 12, 'Zdumiejcie się nad tym, niebiosa, ulęknijcie i bardzo się zatrwóżcie, mówi Pan;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 13, 'Bo mój lud popełnił podwójne zło: opuścił mnie, źródło żywych wód, i wykopał sobie cysterny, cysterny popękane, które nie mogą utrzymać wody.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 14, 'Czy Izrael jest sługą lub niewolnikiem z urodzenia? Czemu więc stał się łupem?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 15, 'Lwięta ryczą na niego i wydają swój głos, i zamieniają jego ziemię w pustynię; jego miasta są spalone, pozbawione mieszkańców.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 16, 'Ponadto synowie Nof i Tachpanes starli czubek twojej głowy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 17, 'Czy nie sprawiłeś tego sam sobie, opuszczając Pana, swego Boga, kiedy prowadził cię drogą?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 18, 'A teraz, po co ci drogi Egiptu – by pić wodę z Nilu? Albo po co ci drogi Asyrii – by pić wodę z jej rzeki?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 19, 'Twoja niegodziwość ukarze cię i twoje odstępstwo cię skarci. Dlatego poznaj i zobacz, że rzeczą złą i gorzką jest to, że opuściłeś Pana, swego Boga, i że nie ma w tobie mojej bojaźni, mówi Pan, Bóg zastępów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 20, 'Dawno bowiem złamałem twoje jarzmo i rozerwałem twoje więzy, i mówiłaś: Nie będę służyła bożkom; a przecież tułałaś się na każdym wysokim pagórku i pod każdym zielonym drzewem jak nierządnica!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 21, 'A ja cię zasadziłem jako wyborną winorośl, nasienie zupełnie prawdziwe. Jakże więc zmieniłaś mi się w zwyrodniałe pędy dzikiej winorośli?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 22, 'Bo choćbyś mocno się obmyła, i saletrą, i mydłem, to jednak twoja nieprawość pozostanie widoczna przede mną, mówi Pan Bóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 23, 'Jak możesz mówić: Nie jestem splugawiona, za Baalami nie chodziłam? Spójrz na swą drogę w tej dolinie, zobacz, co uczyniłaś, chyża wielbłądzico wikłająca swoje drogi;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 24, 'Dzika oślico, przywykła do pustyni, która łapczywie chwytasz powietrze w swej namiętności. Któż powstrzyma jej żądzę? Wszyscy, którzy jej szukają, nie będą się trudzić, znajdą ją w jej miesiącu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 25, 'Uważaj na swoją nogę, aby nie była bosa, i swoje gardło – by nie pragnęło. Lecz ty mówisz: Na próżno; nie uczynię tego, bo rozkochałam się w obcych i pójdę za nimi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 26, 'Jak złodziej wstydzi się, kiedy go schwytają, tak wstydzi się dom Izraela, jego królowie i książęta, jego kapłani i prorocy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 27, 'Którzy mówią do drewna: Ty jesteś moim ojcem, a do kamienia: Ty mnie zrodziłeś. Obrócili się bowiem do mnie plecami, a nie twarzą. Ale w czasie swojej niedoli powiedzą: Powstań i wybaw nas!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 28, 'A gdzie są twoi bogowie, których sobie uczyniłaś? Niech powstaną, jeśli cię mogą wybawić w czasie twojej niedoli, bo ile twoich miast, tyle jest twoich bogów, Judo!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 29, 'Czemu chcecie się ze mną spierać? Wy wszyscy odstąpiliście ode mnie, mówi Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 30, 'Na próżno biłem waszych synów, nie przyjęli pouczenia. Wasz własny miecz pożarł waszych proroków, jak niszczący lew.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 31, 'Pokolenie, rozważaj słowa Pana. Czy byłem pustynią dla Izraela albo ziemią ciemności? Czemu mój lud mówi: My panujemy, już nie przyjdziemy do ciebie?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 32, 'Czy panna zapomina o swoich ozdobach albo oblubienica o swoich klejnotach? Ale mój lud zapomniał o mnie od dni niezliczonych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 33, 'Czemu przyozdabiasz swoją drogę w poszukiwaniu miłości? Przecież nauczyłaś inne nierządnice swoich złych dróg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 34, 'Ponadto na brzegach twoich szat znajduje się krew dusz ubogich i niewinnych. Nie znalazłem tego z trudnością, lecz widać na wszystkich twoich brzegach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 35, 'Lecz mówisz: Ponieważ jestem niewinna, na pewno jego gniew odwróci się ode mnie. Oto będę cię sądził za to, że mówisz: Nie zgrzeszyłam.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 36, 'Czemu tak ganiasz, zmieniając swoje drogi? Będziesz pohańbiona przez Egipt, jak byłaś pohańbiona przez Asyrię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 37, 'I stamtąd wyjdziesz z rękami na głowie, bo Pan odrzucił tych, którym zaufałaś, a nie powiedzie ci się z nimi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 1, 'Jest powiedziane: Jeśli mąż oddali swoją żonę, a ona odejdzie od niego i stanie się żoną innego – czy on jeszcze do niej wróci? Czy ta ziemia nie byłaby wielce splugawiona? Ale ty uprawiałaś nierząd z wieloma kochankami. Powróć jednak do mnie, mówi Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 2, 'Podnieś swoje oczy na wyżyny i sprawdź, czy jest miejsce, gdzie nie uprawiałaś nierządu. Przy drogach siadałaś dla nich, jak Arab na pustyni, i splugawiłaś ziemię swoim nierządem i swą niegodziwością.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 3, 'I dlatego deszcze jesienne zostały wstrzymane, i nie było deszczu wiosennego, lecz nadal masz czoło nierządnicy i nie chcesz się wstydzić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 4, 'Czy teraz nie będziesz wołać do mnie: Mój ojcze! Ty jesteś wodzem mojej młodości?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 5, 'Czy Bóg będzie się gniewał na wieki? Czy zachowa gniew na zawsze? Tak oto mówiłaś i czyniłaś zło, ile tylko mogłaś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 6, 'Wtedy Pan powiedział do mnie za dni króla Jozjasza: Czy widziałeś, co uczyniła odstępczyni Izrael? Chodziła na każdą wysoką górę i pod każde zielone drzewo i tam uprawiała nierząd.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 7, 'I powiedziałem po tym wszystkim, co uczyniła: Powróć do mnie. Lecz nie powróciła. A widziała to jej zdradliwa siostra Juda.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 8, 'I widziałem, gdy z powodu nierządu odstępczyni Izrael oddaliłem ją i dałem jej list rozwodowy, jednak jej zdradliwa siostra Juda nie ulękła się, lecz poszła i również uprawiała nierząd.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 9, 'I przez swój haniebny nierząd zbezcześciła ziemię, i cudzołożyła z kamieniem i drewnem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 10, 'Mimo tego wszystkiego jej zdradliwa siostra Juda nie powróciła do mnie całym sercem, lecz pozornie, mówi Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 11, 'Dlatego Pan powiedział do mnie: Odstępczyni Izrael okazała się sprawiedliwsza niż zdradliwa Juda.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 12, 'Idź i głoś te słowa ku północy, i mów: Wróć, odstępczyni Izrael, mówi Pan, a nie wybuchnie na was mój gniew. Ja bowiem jestem miłosierny, mówi Pan, i nie chowam gniewu na wieki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 13, 'Tylko uznaj swoją nieprawość, że odstąpiłaś od Pana, swego Boga, i biegałaś swoimi drogami do obcych pod każde zielone drzewo, a mojego głosu nie słuchaliście, mówi Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 14, 'Nawróćcie się, synowie odstępczy, mówi Pan, bo ja jestem waszym małżonkiem i przyjmę was po jednym z miasta i po dwóch z każdego rodu i zaprowadzę was do Syjonu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 15, 'I dam wam pasterzy według mego serca, i będą was paść umiejętnie i roztropnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 16, 'A gdy się rozmnożycie i rozplenicie w tej ziemi w tych dniach, mówi Pan, już nie będą mówić: Arka przymierza Pana. Nikomu nie przyjdzie to na myśl. Nie wspomną o niej ani nie odwiedzą jej, ani już nie uczynią jej nową.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 17, 'W tym czasie Jerozolima będzie nazwana tronem Pana, a wszystkie narody zgromadzą się u niej, u imienia Pana, w Jerozolimie, i już nie będą postępować według uporu swego złego serca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 18, 'W te dni dom Judy będzie chodził z domem Izraela i przybędą razem z ziemi północnej do ziemi, którą dałem w dziedzictwo waszym ojcom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 19, 'Ja zaś powiedziałem sobie: Jakże miałbym cię zaliczyć do synów i dać ci ziemię rozkoszną, piękne dziedzictwo zastępów narodów? Chyba że będziesz do mnie wołał: Mój ojcze! I nie odwrócisz się ode mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 20, 'Ponieważ jak żona sprzeniewierza się swemu mężowi, tak mi się sprzeniewierzyłeś, domu Izraela, mówi Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 21, 'Głos się rozlega na wyżynach, błagalny płacz synów Izraela, bo wypaczyli swe drogi i zapomnieli o Panu, swym Bogu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 22, 'Nawróćcie się, odstępczy synowie, a uleczę wasze odstępstwa. Oto przychodzimy do ciebie, bo ty jesteś Panem, naszym Bogiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 23, 'Zaprawdę złudna jest nadzieja w pagórkach i mnóstwie gór. Zaprawdę w Panu, naszym Bogu, jest zbawienie Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 24, 'Od naszej młodości bowiem ta hańba pożerała pracę naszych ojców, ich trzody i stada, ich synów i córki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 25, 'Leżymy w swojej hańbie i nasz wstyd nas przykrywa, bo grzeszyliśmy przeciwko Panu, swemu Bogu, my i nasi ojcowie, od swojej młodości aż do dziś, i nie usłuchaliśmy głosu Pana, naszego Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 1, 'Jeśli chcesz powrócić, Izraelu, mówi Pan, to wróć do mnie. A jeśli usuniesz swoje obrzydliwości sprzed mego oblicza, to już nie będziesz się tułał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 2, 'I przysięgniesz: Jak żyje Pan w prawdzie, w sądzie i w sprawiedliwości. Wtedy narody będą sobie błogosławić w nim i w nim będą się chlubić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 3, 'Tak bowiem mówi Pan do mężczyzn z Judy i Jerozolimy: Przeorzcie swoje ugory, a nie siejcie między ciernie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 4, 'Obrzeżcie się dla Pana i usuńcie napletki waszych serc, Judejczycy i mieszkańcy Jerozolimy, aby moja zapalczywość nie wybuchła jak ogień i nie paliła się tak, że nikt nie zdoła jej zgasić z powodu zła waszych uczynków.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 5, 'Opowiadajcie w Judzie, ogłaszajcie w Jerozolimie i mówcie: Dmijcie w trąbę w całej ziemi; wołajcie, zgromadźcie się i mówcie: Zbierzcie się i wejdźmy do miast warownych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 6, 'Podnieście sztandar w kierunku Syjonu, uciekajcie, nie zastanawiajcie się. Sprowadzam bowiem nieszczęście od północy i wielkie zniszczenie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 7, 'Lew wyszedł ze swojej jaskini, niszczyciel narodów wyruszył, wyszedł ze swego miejsca, aby zamienić twoją ziemię w pustkowie, a twoje miasta zostaną zburzone i pozbawione mieszkańców.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 8, 'Dlatego przepaszcie się worami, lamentujcie i zawódźcie, bo nie odwróciła się od nas zapalczywość gniewu Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 9, 'I stanie się w owym dniu, mówi Pan, że zginie serce króla i serce książąt, a zdumieją się kapłani i prorocy dziwić się będą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 10, 'I powiedziałem: Ach, Panie Boże! Naprawdę bardzo zawiodłeś ten lud i Jerozolimę, mówiąc: Będziecie mieć pokój! A tymczasem miecz przeniknął nas aż do duszy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 11, 'W owym czasie będzie się mówić do tego ludu i do Jerozolimy: Gorący wiatr wyżynny z pustyni idzie prosto na mój lud, lecz nie po to, by go przewiać czy oczyścić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 12, 'Wiatr silniejszy niż oni przyjdzie do mnie; teraz ja też wydam na nich wyrok.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 13, 'Oto nadciągnie jak obłoki, a jego rydwany jak wicher, jego konie są szybsze niż orły. Biada nam, bo jesteśmy spustoszeni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 14, 'Obmyj z nieprawości swoje serce, Jerozolimo, abyś została wybawiona. Jak długo będą trwać w tobie twoje niegodziwe myśli?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 15, 'Głos bowiem opowiada od strony Dan i z góry Efraim ogłasza klęskę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 16, 'Przypominajcie narodom: Oto ogłaszajcie Jerozolimie, że stróże nadciągają z dalekiej ziemi i wznoszą swój głos przeciwko miastom Judy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 17, 'Jak stróże pól otoczą ją dokoła, bo zbuntowała się przeciwko mnie, mówi Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 18, 'Twoja droga i twoje uczynki sprowadziły to na ciebie; twoja niegodziwość sprawia, że jest to gorzkie i że przenika aż do twego serca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 19, 'O moje wnętrze, moje wnętrze! Cierpię z boleści do samego serca! Trwoży się we mnie moje serce, nie mogę milczeć, bo usłyszałaś, moja duszo, głos trąby i okrzyk wojenny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 20, 'Klęska za klęską ogłasza się, bo cała ziemia jest spustoszona. Nagle zniszczone zostały moje namioty, w okamgnieniu – moje zasłony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 21, 'Jak długo mam patrzeć na sztandar i słyszeć dźwięk trąby?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 22, 'Bo mój lud jest głupi, nie zna mnie; to są dzieci niemądre i nierozumne. Są mądre w czynieniu zła, lecz dobrze czynić nie umieją.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 23, 'Spojrzałem na ziemię, a oto bezkształtna i pusta; na niebo, a nie było na nim światła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 24, 'Spojrzałem na góry, a oto się trzęsły i wszystkie pagórki się chwiały.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 25, 'Spojrzałem, a oto nie było człowieka i wszelkie ptactwo niebieskie odleciało.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 26, 'Spojrzałem, a oto pole urodzajne stało się pustynią, a wszystkie jego miasta zostały zburzone przed Panem i przez zapalczywość jego gniewu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 27, 'Bo tak mówi Pan: Cała ziemia zostanie spustoszona, lecz całkowicie jej nie zniszczę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 28, 'Nad tym ziemia będzie lamentować, a niebiosa w górze zaćmią się, gdyż powiedziałem i postanowiłem, a nie będę żałował ani nie odwrócę się od tego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 29, 'Przed wrzawą jeźdźców i łuczników ucieknie całe miasto; wejdą w gęstwiny i wstąpią na skały. Wszystkie miasta będą opuszczone i nie będzie w nich żadnego mieszkańca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 30, 'A ty, spustoszona, cóż uczynisz? Choćbyś się ubrała w szkarłat, choćbyś się przystroiła w złote ozdoby, choćbyś też przyozdobiła swoją twarz kolorem, na próżno się stroisz; twoi kochankowie pogardzą tobą, będą czyhać na twoje życie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 31, 'Słyszałem bowiem głos jakby rodzącej kobiety, udrękę jakby rodzącej po raz pierwszy, głos córki Syjonu, która lamentuje i wyciąga swe ręce, mówiąc: Biada mi teraz, bo moja dusza omdlewa z powodu morderców.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 1, 'Przebiegnijcie ulice Jerozolimy, wypatrujcie teraz i zobaczcie, szukajcie po jej ulicach, czy znajdziecie człowieka, kogoś, kto by wymierzał sprawiedliwy sąd i szukał prawdy, a przebaczę jej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 2, 'Ale choć mówią: Jak żyje Pan, to przecież przysięgają fałszywie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 3, 'Panie, czy twoje oczy nie są zwrócone ku prawdzie? Biłeś ich, ale oni nie czują bólu; obróciłeś ich wniwecz, ale nie chcą przyjąć pouczenia. Uczynili swe twarze twardszymi od skały, nie chcą się nawrócić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 4, 'Wtedy powiedziałem: Naprawdę oni są nędzni i głupio postępują. Nie znają bowiem drogi Pana ani sądu swego Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 5, 'Pójdę do wielkich i będę mówił do nich, bo oni znają drogę Pana i sąd swego Boga. Lecz oni również złamali jarzmo, zerwali więzy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 6, 'Dlatego zabije ich lew z lasu, wilk wieczorny wygubi ich, lampart będzie czyhać przy ich miastach. Ktokolwiek z nich wyjdzie, zostanie rozszarpany. Rozmnożyły się bowiem ich przestępstwa i wzmogły ich odstępstwa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 7, 'Dlaczego miałbym ci to przebaczyć? Twoi synowie opuścili mnie i przysięgają na tych, którzy nie są bogami. Jak tylko ich nakarmiłem, zaraz cudzołożyli i tłumnie zbierali się w domu nierządnicy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 8, 'Gdy wstają rano, są jak konie wypasione, każdy z nich rży do żony swego bliźniego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 9, 'Czyż za to nie powinienem ich nawiedzić? – mówi Pan. Czy nad takim narodem moja dusza ma się nie zemścić?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 10, 'Wstąpcie na jej mury i niszczcie, lecz nie niszczcie doszczętnie. Usuńcie filary jej murów, gdyż nie są od Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 11, 'Bo dom Izraela i dom Judy zupełnie mi się sprzeniewierzyły, mówi Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 12, 'Zaparły się Pana i powiedziały: Nie tak, nie spadnie na nas nic złego, nie doznamy miecza ani głodu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 13, 'A prorocy przeminą z wiatrem, nie ma w nich żadnego słowa Bożego. Tak im się właśnie stanie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 14, 'Dlatego tak mówi Pan, Bóg zastępów: Ponieważ tak mówiliście, oto uczynię moje słowa w twoich ustach ogniem, a ten lud drewnem i pożre ich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 15, 'Oto sprowadzę na was, domu Izraela, naród z daleka, mówi Pan. Naród mocny, naród starożytny, naród, którego języka nie znasz ani nie rozumiesz, co mówi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 16, 'Jego kołczan jest jak grób otwarty, wszyscy są wojownikami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 17, 'Pochłoną twój plon i twój chleb, pochłoną twoich synów i twoje córki. Pochłoną twoje trzody i stada, pochłoną twoją winorośl i twoje drzewa figowe, a twoje miasta warowne, w których pokładasz ufność, zniszczą mieczem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 18, 'Lecz w tych dniach, mówi Pan, nie zniszczę was doszczętnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 19, 'Gdy bowiem powiecie: Za co Pan, nasz Bóg, uczynił nam to wszystko? Wtedy im odpowiesz: Jak wy mnie opuściliście i służyliście obcym bogom w swojej ziemi, tak będziecie służyć cudzoziemcom w nie swojej ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 20, 'Głoście to w domu Jakuba, a rozgłaszajcie to w Judzie, mówiąc:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 21, 'Słuchaj tego teraz, ludu głupi i bezrozumny, wy, którzy macie oczy, a nie widzicie, którzy macie uszy, a nie słyszycie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 22, 'Czy mnie nie będziecie się bać? – mówi Pan. Czy nie będziecie się lękać mnie, który położyłem piasek jako granicę morza mocą wieczystej ustawy, a ono jej nie przekroczy. Choćby fale się burzyły, jednak nie przemogą; choćby huczały, jednak nie przeskoczą go.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 23, 'Ale ten lud ma serce krnąbrne i buntownicze; odstąpił ode mnie i odszedł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 24, 'I nie powiedzieli w swoim sercu: Bójmy się Pana, naszego Boga, który daje deszcz jesienny i wiosenny w swoim czasie; który zapewnia nam ustalone tygodnie żniwa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 25, 'Ale to wasze nieprawości to odwróciły, a wasze grzechy wstrzymały wam to dobro.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 26, 'Wśród mego ludu bowiem znajdują się niegodziwcy, którzy czyhają jak łowcy, rozciągają sieci, zastawiają sidła, łapią ludzi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 27, 'Jak klatka pełna jest ptaków, tak ich domy pełne są zdrady. Dlatego stali się wielcy i bogaci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 28, 'Otyli i rozjaśnili się, innych przewyższają swoją nieprawością. Nie sądzą sprawy, nawet sprawy sierot; jednak powodzi się im, chociaż nie bronią sprawy ubogiego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 29, 'Czyż za to nie powinienem ich nawiedzić? – mówi Pan. Czy nad takim narodem moja dusza ma się nie mścić?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 30, 'Rzecz przedziwna i straszna dzieje się w tej ziemi:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 31, 'Prorocy kłamliwie prorokują i kapłani panują przez ich ręce, a mój lud to kocha. Cóż uczynicie, kiedy nadejdzie koniec?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 1, 'Synowie Beniamina, zgromadźcie się, by uciekać z Jerozolimy, zadmijcie w trąbę w Tekoa, wznieście znak nad Bet-Kerem. Z północy bowiem nadchodzi nieszczęście i wielkie zniszczenie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 2, 'Przyrównałem córkę Syjonu do pięknej, rozkosznej panny;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 3, 'Do niej przyjdą pasterze wraz ze swymi trzodami; rozbiją naprzeciwko niej namioty dokoła, każdy będzie paść w swoim miejscu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 4, 'Ogłoście przeciwko niej wojnę, wstańcie, wyruszymy w południe. Biada nam, bo dzień się kończy, bo wydłużają się cienie wieczorne!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 5, 'Wstańcie, wtargniemy w nocy i zburzmy jej pałace.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 6, 'Tak bowiem mówi Pan zastępów: Narąbcie drzewa i usypcie wał przeciw Jerozolimie. Jest to miasto, które ma być ukarane; pośrodku niej jest całkowity ucisk.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 7, 'Jak źródło wylewa swe wody, tak ona wylewa swoją niegodziwość. Słychać w niej ucisk i spustoszenie, mam przed sobą nieustannie cierpienie i bicie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 8, 'Przyjmij upomnienie, Jerozolimo, aby moja dusza nie odstąpiła od ciebie, bym cię nie zamienił w pustkowie, ziemię bezludną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 9, 'Tak mówi Pan zastępów: Wyzbierają resztkę Izraela aż do grona, jak winorośl. Sięgaj swoją ręką do kosza, jak zbieracz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 10, 'Do kogo będę mówić i kogo ostrzegę, aby słyszeli? Oto ich uszy są nieobrzezane, tak że nie mogą słuchać. Oto słowo Pana uważają za hańbę i nie mają w nim upodobania.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 11, 'Dlatego jestem pełen zapalczywości Pana, zamęczam się, aby ją powstrzymać. Wyleję ją zarówno na dzieci na ulicy, jak i na gromadę młodzieńców, gdyż będą pojmani – mąż z żoną, starzec z podeszłym w wieku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 12, 'Ich domy przypadną innym, także ich pola i żony, gdyż wyciągnę swoją rękę na mieszkańców tej ziemi, mówi Pan;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 13, 'Gdyż od najmniejszego z nich aż do największego – wszyscy oddani są chciwości i od proroka aż do kapłana – wszyscy popełniają oszustwo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 14, 'I leczą rany córki mego ludu tylko powierzchownie, mówiąc: Pokój, pokój! Ale nie ma pokoju.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 15, 'Czy zawstydzili się, że popełnili obrzydliwość? Bynajmniej, wcale nie wstydzili się ani nie potrafili rumienić. Dlatego upadną wśród tych, którzy mają upaść. W czasie gdy ich nawiedzę, upadną, mówi Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 16, 'Tak mówi Pan: Stańcie na drogach, spójrzcie i pytajcie o stare ścieżki, gdzie jest ta dobra droga – i idźcie nią, a znajdziecie odpoczynek dla waszej duszy. Lecz powiedzieli: Nie pójdziemy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 17, 'I ustanowiłem nad wami stróżów, mówiąc: Słuchajcie głosu trąby! Wtedy powiedzieli: Nie będziemy słuchać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 18, 'Dlatego słuchajcie, narody; poznaj, o zgromadzenie, co się wśród nich dzieje.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 19, 'Słuchaj, ziemio! Oto sprowadzę nieszczęście na ten lud – owoc jego myśli, gdyż nie słuchał moich słów ani mego prawa, ale je odrzucił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 20, 'Na cóż mi kadzidło z Szeby i cynamon wonny i wyborny z dalekiej ziemi? Wasze całopalenia nie są dla mnie przyjemne i wasze ofiary nie podobają mi się.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 21, 'Dlatego tak mówi Pan: Oto kładę przed tym ludem przeszkody, o które potykać się będą ojcowie wraz z synami; sąsiad i jego przyjaciel zginą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 22, 'Tak mówi Pan: Oto nadciągnie lud z ziemi północnej, wielki naród powstanie z krańców ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 23, 'Łuk i włócznię trzymają, są okrutni i bezlitośni. Ich głos huczy jak morze i na koniach jeżdżą, gotowi jak jeden mąż do walki przeciwko tobie, o córko Syjonu!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 24, 'Gdy usłyszeliśmy wieść o nich, nasze ręce osłabły, ogarnęły nas trwoga i ból, jak u rodzącej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 25, 'Nie wychodźcie na pole i nie idźcie po drodze, bo miecz wroga i strach dokoła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 26, 'Córko mojego ludu, przepasz się worem i tarzaj się w popiele. Urządź sobie żałobę jak po jedynaku, gorzką żałobę, bo nagle spadnie na nas niszczyciel.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 27, 'Ustanowiłem cię basztą i wieżą wśród mego ludu, abyś poznał i zbadał jego drogi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 28, 'Wszyscy są ogromnie krnąbrni, postępują jak oszczercy. Są jak miedź i żelazo; wszyscy są skażeni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 29, 'Miech uległ zużyciu, ołów od ognia niszczeje; na próżno przetapia go hutnik, bo źli nie zostali oddaleni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 30, 'Będą nazwani srebrem odrzuconym, bo Pan ich odrzucił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 1, 'Słowo, które doszło od Pana do Jeremiasza, mówiące:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 2, 'Stań w bramie domu Pana i głoś tam to słowo, i mów: Słuchajcie słowa Pana, wy wszyscy z Judy, którzy wchodzicie do tych bram, aby oddać Panu pokłon.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 3, 'Tak mówi Pan zastępów, Bóg Izraela: Poprawcie swoje drogi i czyny, a sprawię, że będziecie mieszkać w tym miejscu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 4, 'Nie pokładajcie swojej nadziei w słowach kłamliwych, mówiąc: Świątynia Pana, Świątynia Pana, to jest Świątynia Pana!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 5, 'Ale jeśli naprawdę poprawiacie swoje drogi i czyny, jeśli będziecie sprawiedliwie sprawować sąd pomiędzy człowiekiem a jego bliźnim;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 6, 'Jeśli nie będziecie uciskać przybysza, sieroty i wdowy, nie rozlejecie krwi niewinnej w tym miejscu i za innymi bogami nie pójdziecie na swoje nieszczęście;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 7, 'Wtedy sprawię, że będziecie mieszkać w tym miejscu, w ziemi, którą dałem waszym ojcom na wieki wieków.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 8, 'Oto pokładacie swoją nadzieję w słowach kłamliwych, które nie pomogą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 9, 'Czy będziecie kraść, zabijać, cudzołożyć, przysięgać fałszywie, palić kadzidło Baalowi, iść za innymi bogami, których nie znacie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 10, 'A potem – przychodzić i stawać przede mną w tym domu, który nazwany jest moim imieniem, i mówić: Zostaliśmy wybawieni, aby popełniać te wszystkie obrzydliwości?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 11, 'Czy ten dom, który jest nazwany moim imieniem, jest w waszych oczach jaskinią zbójców? Oto ja to widzę, mówi Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 12, 'Ale idźcie teraz do mojego miejsca, które było w Szilo, gdzie kiedyś ustanowiłem przybytek dla mego imienia, i zobaczcie, co z nim zrobiłem ze względu na niegodziwość mego ludu Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 13, 'A teraz, ponieważ popełniliście te wszystkie czyny, mówi Pan, a ja nieustannie mówiłem do was z wczesnym wstawaniem, a wy nie słuchaliście; wołałem do was, a nie odpowiadaliście;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 14, 'Uczynię temu domowi, który jest nazwany moim imieniem, w którym wy pokładacie ufność, oraz temu miejscu, które dałem wam i waszym ojcom, jak uczyniłem Szilo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 15, 'I odrzucę was sprzed swego oblicza, jak odrzuciłem waszych braci – całe potomstwo Efraima.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 16, 'Ty więc nie módl się o ten lud i nie zanoś za niego ani wołania, ani modlitwy i nie nalegaj na mnie, bo cię nie wysłucham.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 17, 'Czyż sam nie widzisz, co robią w miastach Judy i na ulicach Jerozolimy?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 18, 'Synowie zbierają drwa, ojcowie rozniecają ogień, a ich żony ugniatają ciasto, aby robić placki dla królowej niebios i wylewać ofiary z płynów innym bogom, aby mnie do gniewu pobudzać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 19, 'Czy to jest przeciwko mnie, że mnie do gniewu pobudzają? – mówi Pan. Czy nie raczej przeciwko nim, ku ich własnemu pohańbieniu?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 20, 'Dlatego tak mówi Pan Bóg: Oto mój gniew i moja zapalczywość zostaną wylane na to miejsce, na ludzi i na zwierzęta, na drzewa polne i na owoce ziemi; rozpalą się i nie zgasną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 21, 'Tak mówi Pan zastępów, Bóg Izraela: Dodajcie swoje całopalenia do swoich ofiar i jedzcie mięso.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 22, 'Bo nie mówiłem waszym ojcom ani niczego im nie nakazałem o całopaleniach i ofiarach w dniu, kiedy wyprowadziłem ich z ziemi Egiptu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 23, 'Ale to jedno im nakazałem, mówiąc: Słuchajcie mojego głosu i będę waszym Bogiem, a wy będziecie moim ludem; idźcie każdą drogą, którą wam nakazałem, aby się wam dobrze działo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 24, 'Lecz oni nie posłuchali ani nie nakłonili swego ucha, ale szli za radą i według uporu swego złego serca. I odwrócili się plecami, a nie twarzą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 25, 'Od dnia, kiedy wasi ojcowie wyszli z ziemi Egiptu, aż do dziś, posyłałem do was wszystkie moje sługi, proroków z wczesnym wstawaniem i przesłaniem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 26, 'Oni jednak nie słuchali mnie i nie nakłonili swego ucha, ale zatwardzili swój kark i gorzej czynili niż ich ojcowie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 27, 'Będziesz im mówił wszystkie te słowa, ale cię nie usłuchają; będziesz wołać do nich, ale nie odpowiedzą ci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 28, 'Dlatego mów do nich: To jest naród, który nie słucha głosu Pana, swego Boga, ani nie przyjmuje pouczenia. Zginęła prawda, została starta z ich ust.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 29, 'Ostrzyż swoje włosy, Jerozolimo, i odrzuć je, podnieś lament na wyżynach, bo Pan odrzucił i opuścił to pokolenie, na które bardzo się gniewa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 30, 'Synowie Judy bowiem czynili zło przed moimi oczami, mówi Pan; ustawili swoje obrzydliwości w tym domu, który jest nazwany moim imieniem, aby go zbezcześcić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 31, 'Ponadto zbudowali wyżyny Tofet, która jest w dolinie syna Hinnom, aby palić swoich synów i swoje córki w ogniu, czego nie nakazałem i co nie przyszło mi nawet na myśl.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 32, 'Dlatego oto nadchodzą dni, mówi Pan, gdy to już nie będzie nazywać się Tofet ani Doliną Syna Hinnom, lecz Doliną Rzezi; i będą grzebać zmarłych w Tofet, bo nie będzie innego miejsca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 33, 'I trupy tego ludu będą pokarmem dla ptactwa na niebie i zwierząt na ziemi, a nikt ich nie spłoszy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 34, 'I sprawię, że w miastach Judy i na ulicach Jerozolimy ustanie głos radości, głos wesela, głos oblubieńca i głos oblubienicy, bo ziemia zostanie spustoszona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 1, 'W tym czasie, mówi Pan, wydobędą z ich grobów kości królów Judy, kości ich książąt, kości kapłanów, kości proroków i kości mieszkańców Jerozolimy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 2, 'I rozrzucą je przed słońcem, przed księżycem i przed całym zastępem nieba, które oni kochali, którym służyli, za którymi szli, których szukali i którym oddawali pokłon. Nie będą zebrane ani pogrzebane, lecz staną się nawozem na powierzchni ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 3, 'I cała reszta ocalałych z tego przewrotnego rodu będzie wybierać raczej śmierć niż życie we wszystkich miejscach, gdzie zostali, kiedy ich wygnałem, mówi Pan zastępów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 4, 'Dlatego powiesz do nich: Tak mówi Pan: Czy nie powstaje ten, który upadł? Czy nie zawraca ten, który zbłądził?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 5, 'Czemu więc odwrócił się ten lud Jerozolimy wiecznym odstępstwem? Trzymają się kłamstwa, nie chcą wrócić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 6, 'Uważałem i słyszałem: nie mówią właściwie, nikt nie żałuje swej niegodziwości, mówiąc: Cóż uczyniłem? Każdy biegnie swoją drogą, jak koń pędzący do bitwy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 7, 'Nawet bocian na niebiosach zna swoje ustalone pory; synogarlica, żuraw i jaskółka przestrzegają czasu swego przylotu. Lecz mój lud nie zna sądu Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 8, 'Jakże możecie mówić: My jesteśmy mądrzy, a prawo Pana jest przy nas? Oto zaprawdę na próżno uczynił je; daremne jest pióro pisarzy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 9, 'Mędrcy się zawstydzili. Są przestraszeni i pojmani. Oto odrzucają słowo Pana, jaką więc mają mądrość?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 10, 'Dlatego ich żony dam innym, ich pola tym, którzy ich zdobędą, bo od najmniejszego aż do największego – wszyscy są oddani chciwości, od proroka aż do kapłana – wszyscy działają podstępnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 11, 'I leczą rany córki mego ludu tylko powierzchownie, mówiąc: Pokój, pokój! Ale nie ma pokoju.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 12, 'Czy zawstydzili się, że popełnili obrzydliwość? Bynajmniej, wcale się nie zawstydzili ani nie potrafili rumienić. Dlatego upadną wśród tych, co mają upaść. W czasie gdy ich nawiedzę, upadną, mówi Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 13, 'Doszczętnie ich wykorzenię, mówi Pan. Nie będzie winogron na winorośli ani żadnych fig na drzewie figowym, nawet liść opadnie, a to, co im dałem, zostanie im zabrane.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 14, 'Czemu tu siedzimy? Zbierzcie się, wejdźmy do miast warownych i tam będziemy milczeć. Pan bowiem, nasz Bóg, każe nam milczeć i daje nam do picia wodę żółci, gdyż zgrzeszyliśmy przeciwko Panu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 15, 'Oczekiwaliśmy pokoju, ale nic dobrego nie przyszło; czasu uzdrowienia – a oto strach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 16, 'Od Dan słychać parskanie jego koni, na odgłos rżenia jego mocarzy zadrżała cała ziemia. Nadciągają, aby pożreć ziemię i wszystko, co jest na niej, miasto i jego mieszkańców.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 17, 'Oto bowiem poślę na was najbardziej jadowite węże, których nie można zaklinać, i będą was kąsać, mówi Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 18, 'Moje serce, które miało mnie posilać w smutku, mdleje we mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 19, 'Oto głos krzyku córki mego ludu z dalekiej ziemi: Czy nie ma Pana na Syjonie? Czy nie ma na nim jego króla? Czemu pobudzili mnie do gniewu swoimi bożkami i obcymi próżnościami? – odpowiada Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 20, 'Przeminęło żniwo, skończyło się lato, a my nie jesteśmy wybawieni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 21, 'Z powodu rany córki mojego ludu jestem ranny, pogrążony w żałobie, ogarnęło mnie przerażenie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 22, 'Czy nie ma balsamu w Gileadzie? Czy nie ma tam lekarza? Czemu więc nie jest uleczona córka mojego ludu?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 1, 'Oby moja głowa była wodą, a moje oczy źródłem łez, abym dniem i nocą opłakiwał pomordowanych córki mego ludu!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 2, 'Obym miał na pustyni schronisko dla podróżnych, abym mógł opuścić swój lud i oddalić się od nich! Wszyscy bowiem są cudzołożnikami, zgrają zdrajców;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 3, 'I jak łuk napinają swój język do kłamstwa. Nie wzmocnili się prawdą na ziemi, bo od zła do zła przechodzą, a mnie nie znają, mówi Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 4, 'Niech się każdy strzeże swego bliźniego, a bratu nie ufa, bo każdy brat oszukuje podstępnie i każdy bliźni postępuje jak oszczerca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 5, 'Każdy też oszukuje swego bliźniego i nie mówi prawdy. Przyuczyli swój język do mówienia kłamstwa, męczą się, aby popełnić nieprawość.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 6, 'Twoje mieszkanie jest pośród ludu podstępnego; z powodu podstępu nie chcą mnie poznać, mówi Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 7, 'Dlatego tak mówi Pan zastępów: Oto przetopię ich i wypróbuję; jak bowiem mam postąpić z córką mego ludu?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 8, 'Ich język jest śmiercionośną strzałą, wypowiada oszustwa. Jeden mówi ustami o pokoju ze swym przyjacielem, ale w sercu zastawia na niego sidła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 9, 'Czyż za to nie powinienem ich nawiedzić? – mówi Pan. Czyż nad takim narodem moja dusza nie powinna się zemścić?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 10, 'Z powodu tych gór podniosę płacz i lament, z powodu pastwisk na pustkowiu – pieśń żałobną. Są bowiem spalone tak, że nikt tamtędy nie przechodzi ani odgłosu bydła nie słychać; ptactwo niebieskie i zwierzęta rozbiegły się i odeszły.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 11, 'I zamienię Jerozolimę w gruzy, w legowisko smoków, a miasta Judy – w pustkowie, zostaną bez mieszkańca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 12, 'Któż jest tak mądry, aby mógł to zrozumieć? A do kogo mówiły usta Pana, aby mógł ogłosić, dlaczego ziemia ginie i jest spalona jak pustynia, tak że przez nią nikt nie przechodzi?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 13, 'Pan bowiem mówi: Dlatego że porzucili moje prawo, które im przedłożyłem, a nie słuchali mojego głosu ani nie szli za nim;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 14, 'Ale postępowali według uporu swego serca i szli za Baalami, jak ich nauczyli ich ojcowie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 15, 'Dlatego tak mówi Pan zastępów, Bóg Izraela: Oto nakarmię ich, ten lud, piołunem i napoję ich wodą żółci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 16, 'Rozproszę ich między narodami, których nie znali oni ani ich ojcowie, i poślę za nimi miecz, aż ich doszczętnie wytracę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 17, 'Tak mówi Pan zastępów: Zastanówcie się i wezwijcie płaczki, i niech przyjdą; poślijcie po te, które są wyćwiczone w tym, i niech przyjdą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 18, 'Niech się pospieszą, niech podniosą nad nami lament, aby łzami spływały nam oczy i powieki ociekały wodą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 19, 'Głos lamentu bowiem słychać z Syjonu: Jakże jesteśmy spustoszeni! Jesteśmy bardzo zawstydzeni, bo opuściliśmy ziemię, zburzono nasze mieszkania.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 20, 'Słuchajcie więc, kobiety, słowa Pana, niech wasze ucho przyjmie wyrok jego ust, abyście uczyły wasze córki lamentu, a jedna drugą – pieśni żałobnej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 21, 'Śmierć bowiem wtargnęła przez nasze okna, weszła do naszych pałaców, aby wytracić dzieci na rynku i młodzieńców na ulicach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 22, 'Mów: Tak mówi Pan: Nawet trupy ludzkie padną jak gnój na polu i jak snopy za żniwiarzem, a nikt ich nie zbierze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 23, 'Tak mówi Pan: Niech się nie chlubi mądry swoją mądrością, niech się nie chlubi mocarz swoją siłą i niech się nie chlubi bogaty swoim bogactwem;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 24, 'Ale kto chce się chlubić, niech się chlubi tym, że rozumie i zna mnie, wie, że ja jestem Pan, który okazuje miłosierdzie, sąd i sprawiedliwość na ziemi. To bowiem mi się podoba, mówi Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 25, 'Oto nadchodzą dni, mówi Pan, w których nawiedzę każdego obrzezanego i nieobrzezanego;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 26, 'Egipt, Judę, Edom, Ammonitów, Moabitów i wszystkich, którzy są w najdalszych zakątkach i mieszkają na pustyni. Wszystkie te narody bowiem są nieobrzezane, a cały dom Izraela ma nieobrzezane serce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 1, 'Słuchajcie słowa, które Pan mówi do was, domu Izraela!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 2, 'Tak mówi Pan: Nie uczcie się drogi pogan i nie bójcie się znaków na niebie, bo to poganie ich się boją.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 3, 'Zwyczaje tych narodów są bowiem marnością, gdyż drzewo ścinają w lesie siekierą, dzieło rąk rzemieślnika;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 4, 'Przyozdabiają je srebrem i złotem, przytwierdzają je gwoździami i młotkiem, aby się nie chwiało.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 5, 'Stoją prosto jak palma, ale nie mówią. Trzeba je nosić, bo nie mogą chodzić. Nie bójcie się ich, bo nie mogą czynić nic złego ani nic dobrego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 6, 'Nie ma nikogo jak ty, Panie! Ty jesteś wielki i wielkie jest w mocy twoje imię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 7, 'Któż by się ciebie nie bał, Królu narodów? Tobie bowiem to się należy, ponieważ pośród wszystkich mędrców narodów i we wszystkich ich królestwach nie ma nikogo jak ty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 8, 'Wszyscy razem są głupi i nierozumni; czerpanie nauki z drewna to całkowita marność.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 9, 'Srebro sklepane, przywiezione z Tarszisz, a złoto z Ufas – dzieło rzemieślnika i rąk złotnika. Ich szaty z błękitu i purpury, wszystko to jest dziełem uzdolnionych rzemieślników.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 10, 'Ale Pan jest prawdziwym Bogiem, jest Bogiem żywym i królem wiecznym. Od jego gniewu drży ziemia, a narody nie mogą znieść jego oburzenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 11, 'Tak więc im powiecie: Ci bogowie, którzy nie stworzyli nieba i ziemi, znikną z ziemi i spod nieba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 12, 'On uczynił ziemię swoją mocą, utwierdził okrąg świata swoją mądrością i swoją roztropnością rozpostarł niebiosa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 13, 'Gdy on wydaje głos, huczą wody w niebiosach, on sprawia, że chmury wznoszą się z krańców ziemi; czyni błyskawice z deszczem i wyprowadza wiatr ze swoich skarbców.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 14, 'Każdy człowiek jest głupcem i nie wie, że każdy złotnik jest okryty hańbą z powodu posągu, bo jego odlany posąg jest fałszem i nie ma w nich ducha.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 15, 'Są marnością i dziełem błędów; w czasie swego nawiedzenia zginą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 16, 'Nie takim jak one jest dział Jakuba, bo on jest Stwórcą wszystkiego, a Izrael jest szczepem jego dziedzictwa. Pan zastępów – to jego imię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 17, 'Pozbieraj z ziemi swoje towary, ty, która mieszkasz w miejscu warownym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 18, 'Tak bowiem mówi Pan: Oto ja tym razem jak z procy cisnę w mieszkańców tej ziemi i udręczę ich, aby tego doznali.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 19, 'Biada mi z powodu mego zniszczenia, moja rana jest bolesna, ale mówiłem: Właśnie to jest moje cierpienie, muszę je znieść.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 20, 'Mój namiot został zburzony i wszystkie moje powrozy są zerwane. Moi synowie odeszli ode mnie i nie ma ich. Nie ma już nikogo, kto by rozbił mój namiot i rozciągnął moje zasłony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 21, 'Pasterze bowiem stali się głupi i nie szukali Pana. Dlatego im się nie powiedzie, a cała ich trzoda zostanie rozproszona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 22, 'Oto nadchodzi wieść i wielka wrzawa z ziemi północnej, aby miasta Judy zamienić w pustkowie i w siedlisko smoków.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 23, 'Wiem, Panie, że droga człowieka nie zależy od niego ani nie leży w mocy człowieka kierować swoimi krokami, gdy chodzi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 24, 'Karć mnie, Panie, ale według słusznej miary, nie w swym gniewie, abyś mnie nie zniszczył.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 25, 'Wylej swoją zapalczywość na te narody, które cię nie znają, i na rody, które nie wzywają twego imienia. Pochłonęły bowiem Jakuba i pożarły go, strawiły go, a jego mieszkanie zamieniły w pustkowie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 1, 'Słowo, które doszło do Jeremiasza od Pana, mówiące:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 2, 'Słuchajcie słów tego przymierza i mówcie do mężczyzn Judy i do mieszkańców Jerozolimy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 3, 'Powiedz do nich: Tak mówi Pan, Bóg Izraela: Przeklęty ten człowiek, który nie posłucha słów tego przymierza;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 4, 'Które nakazałem waszym ojcom w dniu, kiedy wyprowadziłem ich z ziemi Egiptu, z pieca do topienia żelaza, mówiąc: Słuchajcie mojego głosu i czyńcie to wszystko, co wam nakazuję; i będziecie moim ludem, a ja będę waszym Bogiem;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 5, 'Abym mógł wypełnić przysięgę, którą złożyłem waszym ojcom, że dam im ziemię opływającą mlekiem i miodem, jak to jest dzisiaj. A ja odpowiedziałem: Amen, Panie!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 6, 'I Pan powiedział do mnie: Głoś wszystkie te słowa w miastach Judy i po ulicach Jerozolimy, mówiąc: Słuchajcie słów tego przymierza i wypełniajcie je.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 7, 'Usilnie bowiem ostrzegałem waszych ojców od dnia, kiedy wyprowadziłem ich z ziemi Egiptu, aż do dziś, z wczesnym wstawaniem i ostrzeganiem, mówiąc: Słuchajcie mego głosu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 8, 'Oni jednak nie usłuchali ani nie nakłonili swego ucha, ale każdy postępował według uporu swego złego serca. Dlatego sprowadziłem na nich wszystkie słowa tego przymierza, które nakazałem im wypełniać, a nie wypełnili.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 9, 'I Pan powiedział do mnie: Znalazł się spisek wśród mężczyzn Judy i mieszkańców Jerozolimy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 10, 'Wrócili do nieprawości swoich przodków, którzy nie chcieli słuchać moich słów; poszli i oni za innymi bogami, aby im służyć. Dom Izraela i dom Judy złamały moje przymierze, które zawarłem z ich ojcami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 11, 'Dlatego tak mówi Pan: Oto sprowadzę na nich nieszczęście, z którego nie będą mogli się wydostać; a choćby wołali do mnie, nie wysłucham ich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 12, 'I pójdą miasta Judy i mieszkańcy Jerozolimy i będą wołać do bogów, którym palą kadzidło, lecz oni wcale ich nie wybawią w czasie ich utrapienia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 13, 'Ile bowiem jest twoich miast, tylu twoich bogów, Judo! Ile ulic w Jerozolimie, tyle wznieśliście ołtarzy obrzydliwości, ołtarzy do palenia kadzidła Baalowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 14, 'Dlatego ty się nie módl za ten lud i nie zanoś za niego wołania ani modlitwy, bo ja go nie wysłucham, gdy do mnie będzie wołać w czasie swego utrapienia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 15, 'Cóż chce moja umiłowana w moim domu, skoro bez wstydu dopuściła się sprośności z wieloma, a ofiary święte odeszły od ciebie? Radujesz się, gdy czynisz zło.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 16, 'Pan nazwał cię zielonym drzewem oliwnym, pięknym, dającym piękny owoc, ale wśród huku wielkiej burzy rozpalił nad nim ogień, połamane są jego gałęzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 17, 'Pan zastępów bowiem, który cię zasadził, zapowiedział przeciwko tobie to nieszczęście z powodu niegodziwości domu Izraela i domu Judy, którą popełniły na własną szkodę, aby mnie pobudzać do gniewu, paląc kadzidło Baalowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 18, 'A Pan oznajmił mi to i zrozumiałem; wtedy ukazałeś mi ich uczynki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 19, 'Ja zaś byłem jak baranek i wół prowadzony na rzeź, bo nie wiedziałem, że przeciwko mnie knuli zamysły, mówiąc: Zniszczmy drzewo wraz z jego owocem i wykorzeńmy go z ziemi żyjących, aby jego imię już nie było wspominane.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 20, 'Lecz, Panie zastępów, który sądzisz sprawiedliwie i badasz nerki i serca, niech zobaczę twoją pomstę nad nimi. Wyjawiłem ci bowiem swoją sprawę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 21, 'Dlatego tak mówi Pan o mężczyznach z Anatot, którzy nastają na twoje życie i mówią: Nie prorokuj w imię Pana, abyś nie zginął z naszej ręki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 22, 'Dlatego tak mówi Pan zastępów: Oto nawiedzę ich; ich młodzieńcy zginą od miecza, ich synowie i córki umrą z głodu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 23, 'I nikt z nich nie zostanie, bo sprowadzę nieszczęście na ludzi z Anatot w roku ich nawiedzenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 1, 'Sprawiedliwy jesteś, Panie, choćbym się z tobą spierał. Ja jednak będę rozmawiać z tobą o twoich sądach. Czemu szczęści się droga bezbożnych? Czemu spokojnie żyją wszyscy, którzy postępują bardzo zdradliwie?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 2, 'Zasadziłeś ich, zapuścili też korzenie; rosną i nawet wydają owoc. Bliski jesteś ich ust, ale daleki od ich nerek.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 3, 'Ale ty, Panie, znasz mnie, wypatrujesz mnie i doświadczyłeś moje serce, i wiesz, że jest z tobą. Odłącz ich jak owce na rzeź i przygotuj ich na dzień zabicia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 4, 'Jak długo ziemia będzie płakać, a trawa na wszystkich polach będzie usychać z powodu niegodziwości jej mieszkańców? Giną wszystkie zwierzęta i ptactwo, bo mówią: Nie widzi naszego końca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 5, 'Jeśli biegłeś z pieszymi i zmęczyłeś się, to jak zmierzysz się z końmi? A jeśli zmęczyłeś się w spokojnej ziemi, w której pokładałeś nadzieję, co zrobisz przy wezbraniu Jordanu?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 6, 'Nawet twoi bracia i dom twego ojca sprzeniewierzyli się tobie, oni też głośno wołają za tobą. Ale nie wierz im, choćby mówili do ciebie piękne słowa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 7, 'Opuściłem swój dom, porzuciłem swoje dziedzictwo; umiłowaną mojej duszy wydałem w ręce jej wrogów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 8, 'Moje dziedzictwo stało się dla mnie jak lew w lesie; podnosi przeciwko mnie swój głos, dlatego je znienawidziłem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 9, 'Moje dziedzictwo jest pstrym ptakiem, ptaki dokoła będą przeciwko niemu. Chodźcie, zbierzcie wszystkie zwierzęta polne, zejdźcie się na żer.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 10, 'Wielu pasterzy zniszczyło moją winnicę, zdeptało mój dział; mój rozkoszny dział zamienili w opustoszałe pustkowie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 11, 'Zamienili go w pustkowie; a spustoszony leży w żałobie przede mną; cała ziemia pustoszeje, bo nikt tego nie bierze sobie do serca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 12, 'Na wszystkie pustynne wzniesienia przyjdą niszczyciele, bo miecz Pana pożre wszystko od jednego krańca do drugiego krańca ziemi. Żadne ciało nie będzie miało pokoju.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 13, 'Posiali pszenicę, ale będą zbierać ciernie; natrudzili się, ale nic nie osiągną. Zawstydzą się ze swoich plonów z powodu zapalczywego gniewu Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 14, 'Tak mówi Pan o wszystkich moich złych sąsiadach dotykających mojego dziedzictwa, które dałem w dziedzictwo memu ludowi Izraelowi: Oto wykorzenię ich z ich ziemi, a dom Judy wyrwę spośród nich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 15, 'A gdy ich wyrwę, wrócę, zlituję się nad nimi i znowu przyprowadzę każdego z nich do jego dziedzictwa i każdego z nich do jego ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 16, 'I jeśli dokładnie się nauczą dróg mojego ludu, i będą przysięgać na moje imię, mówiąc: Pan żyje, podobnie jak nauczali mój lud przysięgać na Baala, wtedy zostaną zbudowani wśród mego ludu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 17, 'Ale jeśli nie usłuchają, wtedy wykorzenię ten naród, wyrwę i wytracę go, mówi Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 1, 'Tak powiedział Pan do mnie: Idź i kup sobie lniany pas, przepasz nim swoje biodra, ale nie kładź go do wody.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 2, 'Kupiłem więc pas według rozkazu Pana i przepasałem nim swoje biodra.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 3, 'Potem ponownie doszło do mnie słowo Pana mówiące:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 4, 'Weź ten pas, który kupiłeś i który jest na twoich biodrach, i wstań, idź nad Eufrat i ukryj go tam w szczelinie skalnej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 5, 'Poszedłem więc i ukryłem go nad Eufratem, jak mi Pan rozkazał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 6, 'A po upływie wielu dni Pan powiedział do mnie: Wstań, idź nad Eufrat i weź stamtąd pas, który ci rozkazałem tam ukryć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 7, 'Poszedłem wtedy nad Eufrat, wykopałem i wziąłem pas z miejsca, gdzie go ukryłem, a oto pas był zbutwiały tak, że do niczego się nie nadawał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 8, 'Potem doszło do mnie słowo Pana mówiące:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 9, 'Tak mówi Pan: Tak zniszczę pychę Judy i wielką pychę Jerozolimy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 10, 'Ten zły lud, który się wzbrania słuchać moich słów, który postępuje według uporu swego serca i idzie za innymi bogami, aby im służyć i dać im pokłon, stanie się jak ten pas, który się do niczego nie nadaje.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 11, 'Jak bowiem pas przylega do bioder mężczyzny, tak sprawiłem, że przylgnął do mnie cały dom Izraela i cały dom Judy, mówi Pan, aby był moim ludem, moją sławą, chwałą i ozdobą. Lecz nie posłuchali.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 12, 'Dlatego powiedz im to słowo: Tak mówi Pan, Bóg Izraela: Każdy dzban zostanie napełniony winem; a gdy powiedzą: Czyż nie wiemy, że wszelki dzban zostanie napełniony winem?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 13, 'Wtedy im odpowiesz: Tak mówi Pan: Oto napełnię pijaństwem wszystkich mieszkańców tej ziemi i królów, którzy siedzą na tronie Dawida, i kapłanów oraz proroków, a także wszystkich mieszkańców Jerozolimy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 14, 'I roztrzaskam jednych o drugich, zarówno ojców, jak i synów, mówi Pan. Nie pożałuję i nie oszczędzę nikogo ani nie zlituję się, lecz zniszczę ich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 15, 'Słuchajcie i nakłońcie ucha, nie wynoście się, bo Pan przemawia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 16, 'Oddajcie chwałę Panu, swemu Bogu, zanim sprowadzi ciemność i zanim potkną się wasze nogi w mrocznych górach; gdy będziecie czekać na światłość, oto Bóg zamieni je w cień śmierci i przemieni w mrok.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 17, 'A jeśli tego nie usłuchacie, moja dusza będzie płakać w skrytości z powodu waszej pychy, a moje oko będzie nieustannie płakało i roniło łzy, bo trzoda Pana zostanie pojmana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 18, 'Powiedz królowi i królowej: Ukorzcie się i usiądźcie na ziemi, bo spadła z waszej głowy korona waszej chwały.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 19, 'Miasta południa będą zamknięte i nikt ich nie otworzy. Cała Juda zostanie uprowadzona do niewoli, zostanie całkowicie uprowadzona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 20, 'Podnieście swoje oczy i patrzcie na tych, którzy przybywają z północy. Gdzie jest ta trzoda, którą ci powierzono, twoja wspaniała trzoda?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 21, 'Co powiesz, gdy on cię nawiedzi? Ty bowiem nauczyłaś ich, aby byli wodzami i zwierzchnikami nad tobą. Czy nie ogarną cię bóle jak rodzącą kobietę?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 22, 'A jeśli powiesz w swoim sercu: Dlaczego to mnie spotkało? Z powodu ogromu twojej nieprawości poły twojej szaty zostały odkryte i twoje pięty będą gwałtownie obnażone.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 23, 'Czy Etiopczyk może zmienić swoją skórę albo lampart swoje pręgi? Podobnie wy, czy możecie czynić dobrze, skoro przywykliście czynić źle?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 24, 'Dlatego rozproszę ich jak plewy unoszone przez wiatr pustynny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 25, 'Taki będzie twój los i dział wymierzony ci przeze mnie, mówi Pan, za to, że o mnie zapomniałaś i zaufałaś kłamstwu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 26, 'Tak więc odkryję poły twojej szaty aż do twarzy, aby była widoczna twoja sromota.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 27, 'Widziałem twoje cudzołóstwa i twoje rżenie, hańbę twojego nierządu i twoje obrzydliwości na pagórkach i na polach. Biada tobie, Jerozolimo! Czy się nie oczyścisz? Jak długo jeszcze?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 1, 'Słowo Pana, które doszło do Jeremiasza w związku z suszą:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 2, 'Ziemia Judy płacze, a jej bramy osłabły, w szacie żałobnej siedzą na ziemi, a krzyk Jerozolimy się podnosi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 3, 'Ich szlachetni posyłają swoje sługi po wodę. A gdy przyszli do cystern, nie znaleźli wody i powrócili z pustymi naczyniami. Zapłonęli i zawstydzili się, i zakryli swoje głowy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 4, 'Z powodu spękanej ziemi – bo nie było deszczu na ziemi – oracze ze wstydu zakryli swoje głowy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 5, 'Nawet łania rodząca na polu porzuciła młode, bo nie było trawy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 6, 'A dzikie osły, stojąc na wysokich miejscach, chwyciły wiatr jak smoki; ich oczy osłabły, bo nie było trawy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 7, 'Panie, chociaż nasze nieprawości świadczą przeciwko nam, działaj przez wzgląd na twoje imię. Liczne są bowiem nasze odstępstwa, zgrzeszyliśmy przeciwko tobie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 8, 'Nadziejo Izraela, jego Zbawicielu w czasie utrapienia, czemu jesteś jak przybysz w tej ziemi, jak podróżny, który zatrzymuje się na nocleg?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 9, 'Czemu jesteś jak człowiek osłupiały albo jak mocarz, który nie może wybawić? Ty jednak jesteś pośród nas, Panie, i twoje imię jest wzywane nad nami. Nie opuszczaj nas.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 10, 'Tak mówi Pan o tym ludzie: Tak kochają błądzić, swoich nóg nie powstrzymają; dlatego Pan nie ma w nich upodobania, teraz wspomina ich nieprawość i nawiedza ich za ich grzechy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 11, 'Potem Pan powiedział do mnie: Nie módl się o dobro tego ludu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 12, 'Gdy będą pościć, nie wysłucham ich wołania, a gdy będą składać całopalenia i ofiarę z pokarmów, nie przyjmę tego, ale wytracę ich mieczem, głodem i zarazą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 13, 'Wtedy powiedziałem: Ach, Panie Boże! Oto prorocy mówią im: Nie zobaczycie miecza ani nie dotknie was głód, ale dam wam trwały pokój na tym miejscu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 14, 'I Pan powiedział do mnie: Ci prorocy fałszywie prorokują w moje imię. Nie posłałem ich ani im niczego nie nakazywałem, ani nie mówiłem do nich. Prorokują wam kłamliwe widzenie i wróżbę, marność i urojenie swego serca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 15, 'Dlatego tak mówi Pan o prorokach, którzy prorokują w moje imię, chociaż ich nie posłałem, i którzy mówią: Miecza i głodu nie będzie w tej ziemi. Ci sami prorocy od miecza i głodu zginą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 16, 'A ten lud, któremu oni prorokują, będzie wyrzucony na ulice Jerozolimy z powodu głodu i miecza i nie będzie nikogo, kto by pogrzebał ich samych ani ich żon, ani ich synów i córek. Tak wyleję na nich ich niegodziwość.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 17, 'Dlatego powiesz im to słowo: Moje oczy wylewają łzy w nocy i we dnie, bez przerwy, bo dziewicza córka mego ludu została dotknięta wielką klęską, ciosem bardzo bolesnym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 18, 'Jeśli wychodzę na pole – oto pobici mieczem, jeśli wchodzę do miasta – oto ginący od głodu. Tak, zarówno prorok, jak i kapłan kupczą ziemią, a ludzie tego nie zauważają.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 19, 'Czy całkowicie odrzucasz Judę? Czy twoja dusza obrzydziła sobie Syjon? Czemu nas bijesz, tak że już nie ma dla nas uzdrowienia? Oczekiwaliśmy pokoju, ale nie ma nic dobrego; oczekiwaliśmy czasu uleczenia, a oto trwoga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 20, 'Uznajemy, Panie, swoją niegodziwość i nieprawość naszych ojców, bo zgrzeszyliśmy przeciw tobie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 21, 'Nie odrzucaj nas przez wzgląd na twoje imię, nie dopuść do znieważenia tronu swojej chwały. Pamiętaj o swoim przymierzu i nie zrywaj go z nami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 22, 'Czy wśród marności pogan są takie, co spuszczają deszcz? Czy niebiosa mogą same dawać deszcze? Czy to nie ty, Panie, nasz Boże? Dlatego oczekujemy ciebie, bo ty czynisz to wszystko.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 1, 'Wtedy Pan powiedział do mnie: Choćby Mojżesz i Samuel stanęli przede mną, nie miałbym serca do tego ludu. Wypędź ich sprzed mego oblicza i niech idą precz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 2, 'A jeśli zapytają: Dokąd pójdziemy? Wtedy im powiesz: Tak mówi Pan: Kto przeznaczony na śmierć, pójdzie na śmierć; kto pod miecz – pod miecz, kto na głód – na głód, a kto na niewolę – w niewolę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 3, 'I nawiedzę ich czterema rodzajami kar, mówi Pan: Mieczem, aby zabijał, psami, aby rozszarpywały, ptactwem nieba i zwierzętami ziemi, aby pożerały i niszczyły.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 4, 'I sprawię, że zostaną wysiedleni do wszystkich królestw ziemi z powodu Manassesa, syna Ezechiasza, króla Judy, za to, co uczynił w Jerozolimie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 5, 'Któż bowiem zlituje się nad tobą, Jerozolimo? Któż się użali nad tobą? Któż zboczy z drogi, aby zapytać, jak ci się powodzi?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 6, 'Ty mnie opuściłaś, mówi Pan, odwróciłaś się ode mnie. Dlatego wyciągnę na ciebie moją rękę, aby cię wytracić; zmęczyłem się żałowaniem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 7, 'Rozwieję ich wiejadłem w bramach tej ziemi, osierocę i wygubię mój lud, bo nie zawrócili ze swoich dróg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 8, 'Ich wdów więcej mi się namnożyło niż nadmorskich piasków. Sprowadziłem na nich, na matki młodzieńców, niszczyciela w południe. Sprawię, że nagle napadnie na to miasto, a jego mieszkańcy będą przestraszeni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 9, 'Mdleje ta, która urodziła siedmioro, wyzionęła ducha; jeszcze za dnia zaszło jej słońce. Zapłonęła i zawstydziła się. A ich resztkę wydam na pastwę miecza przed ich wrogami, mówi Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 10, 'Biada mi, moja matko, że urodziłaś mnie, mężczyznę kłótni i sporu na całej ziemi. Nie pożyczyłem im na lichwę ani oni na lichwę mnie nie pożyczali, a jednak każdy mi złorzeczy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 11, 'I Pan powiedział: Zapewniam, że będzie dobrze tym, którzy pozostaną. Sprawię, że wróg zatroszczy się o ciebie w czasie utrapienia i ucisku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 12, 'Czy zwykłe żelazo pokruszy żelazo z północy i stal?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 13, 'Twoje bogactwo, Judo, i twoje skarby wydam na łup, bez opłaty, za wszystkie twoje grzechy we wszystkich twoich granicach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 14, 'I sprawię, że pójdziesz ze swymi wrogami do ziemi, której nie znasz. Rozpalił się bowiem ogień mojego gniewu i będzie płonąć nad wami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 15, 'Ty mnie znasz, Panie, wspomnij i wejrzyj na mnie, a pomścij mnie wobec moich prześladowców. Nie porywaj mnie w swojej pobłażliwości wobec nich. Wiedz, że dla ciebie znoszę hańbę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 16, 'Gdy się znalazły twoje słowa, zjadłem je, a twoje słowo było dla mnie weselem i radością mego serca. Nazywam się bowiem twoim imieniem, Panie, Boże zastępów!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 17, 'Nie zasiadałem w radzie naśmiewców ani się z nimi nie radowałem; ale zasiadałem samotnie z powodu twojej surowej ręki, bo napełniłeś mnie gniewem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 18, 'Czemu mój ból ma trwać wiecznie i moja rana ma być nieuleczalna, i nie chce się goić? Czy masz być dla mnie jak kłamca, jak wody zawodne?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 19, 'Dlatego tak mówi Pan: Jeśli zawrócisz, wtedy zawrócę cię, abyś stał przede mną. I jeśli odłączysz to, co cenne, od tego, co nikczemne, będziesz jakby moimi ustami. Niech oni zawrócą do ciebie, ale ty nie zawracaj do nich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 20, 'A uczynię cię dla tego ludu warownym murem spiżowym. Będą walczyć przeciwko tobie, ale cię nie przemogą, bo ja jestem z tobą, aby cię wybawić i ocalić, mówi Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 21, 'Wyrwę cię z rąk niegodziwców i odkupię cię z rąk okrutników.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 1, 'I doszło do mnie słowo Pana mówiące:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 2, 'Nie pojmiesz sobie żony ani nie będziesz miał synów i córek na tym miejscu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 3, 'Tak bowiem mówi Pan o synach i córkach urodzonych na tym miejscu, o ich matkach, które ich urodzą, i o ich ojcach, którzy ich spłodzą w tej ziemi:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 4, 'Pomrą od ciężkich śmiertelnych chorób; nie będą opłakiwani ani pogrzebani, lecz staną się nawozem na powierzchni ziemi. Wyginą od miecza i głodu, a ich trupy będą pokarmem dla ptactwa nieba i zwierząt ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 5, 'Tak bowiem mówi Pan: Nie wchodź do domu żałoby i nie chodź opłakiwać ani żałować ich, bo odjąłem mój pokój od tego ludu, miłosierdzie i litość, mówi Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 6, 'Pomrą wielcy i mali w tej ziemi. Nie będą pogrzebani ani opłakiwani, nikt nie będzie dla nich się nacinał ani robił sobie łysiny;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 7, 'Nikt nie będzie łamać chleba z tymi, którzy są w żałobie, aby ich pocieszyć po zmarłym, ani nie dadzą im pić z kubka pocieszenia za ich ojca lub matkę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 8, 'Nie wchodź do domu uczty, by zasiąść z nimi do jedzenia i picia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 9, 'Tak bowiem mówi Pan zastępów, Bóg Izraela: Oto sprawię, że na waszych oczach i za waszych dni ustanie na tym miejscu głos wesela i głos radości, głos oblubieńca i głos oblubienicy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 10, 'A gdy ogłosisz temu ludowi wszystkie te słowa, a zapytają cię: Czemu Pan zapowiedział przeciwko nam całe to wielkie nieszczęście? I jaka jest nasza nieprawość, i jaki nasz grzech, który popełniliśmy przeciwko Panu, naszemu Bogu?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 11, 'Wtedy powiesz im: Dlatego, że wasi ojcowie opuścili mnie, mówi Pan, i poszli za innymi bogami, służyli im i oddawali im pokłon, mnie zaś opuścili i nie przestrzegali mojego prawa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 12, 'A wy czyniliście jeszcze gorzej niż wasi ojcowie, bo oto każdy z was postępuje według uporu swego złego serca, nie słuchając mnie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 13, 'Dlatego wyrzucę was z tej ziemi do ziemi, której nie znaliście, ani wy, ani wasi ojcowie, i tam będziecie służyć innym bogom dniem i nocą, gdzie nie okażę wam miłosierdzia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 14, 'Dlatego oto nadchodzą dni, mówi Pan, że już nie będą mówić: Jak żyje Pan, który wyprowadził synów Izraela z ziemi Egiptu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 15, 'Ale: Jak żyje Pan, który wyprowadził synów Izraela z ziemi północnej i ze wszystkich ziem, do których ich wygnał. I sprowadzę ich znowu do ich ziemi, którą dałem ich ojcom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 16, 'Oto poślę po wielu rybaków, mówi Pan, i ci ich wyłowią; potem poślę po wielu myśliwych, i ci ich upolują na każdej górze i na każdym pagórku, i w rozpadlinach skalnych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 17, 'Moje oczy bowiem patrzą na wszystkie ich drogi. Nie są ukryte przed moim obliczem ani ich nieprawość nie jest zakryta przed moimi oczami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 18, 'Najpierw odpłacę im podwójnie za ich nieprawości i za ich grzechy, za to, że zbezcześcili moją ziemię trupami swoich obrzydliwości i napełnili moje dziedzictwo swoimi ohydami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 19, 'Panie, moja mocy i siło, moja ucieczko w dniu utrapienia! Do ciebie przyjdą poganie od krańców ziemi i powiedzą: Zaprawdę, nasi ojcowie odziedziczyli kłamstwa i marności, w których nie było żadnego pożytku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 20, 'Czy człowiek może uczynić sobie bogów? Przecież to nie są bogowie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 21, 'Dlatego oto ja sprawię, że poznają tym razem; sprawię, że poznają moją rękę i moc, i dowiedzą się, że moje imię to Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 1, 'Grzech Judy jest zapisany żelaznym rylcem, ostrzem diamentu jest wyryty na tablicy ich serca i na rogach waszych ołtarzy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 2, 'Gdy ich synowie wspominają ich ołtarze i gaje pod drzewami zielonymi, na wysokich pagórkach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 3, 'Moja góro na polu! Twoje bogactwo i wszystkie twoje skarby wydam na łup z powodu grzechu twoich wyżyn we wszystkich twoich granicach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 4, 'A ty opuścisz swoje dziedzictwo, które ci dałem. I sprawię, że będziesz służył swoim wrogom w ziemi, której nie znasz, bo rozpaliliście ogień mojej zapalczywości, który będzie płonąć na wieki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 5, 'Tak mówi Pan: Przeklęty człowiek, który ufa człowiekowi i który czyni ciało swoim ramieniem, a od Pana odstępuje jego serce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 6, 'Będzie bowiem jak wrzos na pustyni, który nie czuje, gdy przychodzi coś dobrego, ale wybiera suche miejsca na pustyni, w ziemi słonej i bezludnej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 7, 'Błogosławiony człowiek, który ufa Panu, a którego nadzieją jest Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 8, 'Będzie bowiem jak drzewo zasadzone nad wodami, które swoje korzenie zapuszcza nad strumieniem i nie zauważa, gdy upał przychodzi, ale jego liść pozostaje zielony. W roku suszy nie troszczy się i nie przestaje przynosić owocu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 9, 'Najzdradliwsze ponad wszystko jest serce i najbardziej przewrotne. Któż zdoła je poznać?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 10, 'Ja, Pan, badam serca i doświadczam nerki, aby oddać każdemu według jego dróg i według owocu jego uczynków.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 11, 'Jak kuropatwa gromadzi swoje jajka, ale ich nie wysiaduje, tak kto zbiera bogactwa niesprawiedliwie, zostawi je w połowie swoich dni, a u swego kresu okaże się głupcem;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 12, 'Wzniosłym tronem chwały od początku jest miejsce naszej świątyni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 13, 'Panie, nadziejo Izraela! Wszyscy, którzy cię opuszczają, będą zawstydzeni; ci, którzy odstępują ode mnie, będą zapisani na ziemi, gdyż opuścili Pana, źródło żywych wód.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 14, 'Uzdrów mnie, Panie, a będę uzdrowiony; zbaw mnie, a będę zbawiony. Ty bowiem jesteś moją chwałą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 15, 'Oto oni mówią do mnie: Gdzie jest słowo Pana? Niech się już spełni!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 16, 'Ale ja nie zabiegałem, aby być twoim pasterzem ani nie pragnąłem dnia boleści; ty wiesz: cokolwiek wyszło z moich ust, jest przed twoim obliczem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 17, 'Nie bądź dla mnie postrachem. Ty jesteś moją nadzieją w dniu utrapienia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 18, 'Niech będą zawstydzeni ci, którzy mnie prześladują, lecz niech ja nie będę zawstydzony. Niech się oni lękają, lecz niech ja się nie lękam. Sprowadź na nich dzień utrapienia i zniszcz ich podwójnym zniszczeniem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 19, 'Tak Pan powiedział do mnie: Idź i stań w bramie synów tego ludu, którą wchodzą i wychodzą królowie Judy, oraz we wszystkich bramach Jerozolimy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 20, 'I powiedz im: Słuchajcie słowa Pana, królowie Judy, cała Judo i wszyscy mieszkańcy Jerozolimy, którzy wchodzicie przez te bramy!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 21, 'Tak mówi Pan: Strzeżcie pilnie waszych dusz i nie noście żadnego ciężaru w dzień szabatu ani nie wnoście tego przez bramy Jerozolimy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 22, 'Nie wynoście ciężarów z waszych domów w dzień szabatu ani nie wykonujcie żadnej pracy, ale święćcie dzień szabatu, jak nakazałem waszym ojcom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 23, 'Oni jednak nie usłuchali ani nie nakłonili swego ucha, lecz zatwardzili swój kark, aby nie słuchać i nie przyjąć pouczenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 24, 'A jeśli będziecie mnie pilnie słuchać, mówi Pan, i nie wnosić ciężarów przez bramy tego miasta w dzień szabatu, ale będziecie święcić dzień szabatu, nie wykonując w nim żadnej pracy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 25, 'Wtedy przez bramy tego miasta będą wchodzić królowie i książęta zasiadający na tronie Dawida, będą wjeżdżać na rydwanach i na koniach, oni, ich książęta, Judejczycy i mieszkańcy Jerozolimy, a to miasto będzie trwać na wieki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 26, 'I zbiegną się z miast Judy, z okolic Jerozolimy i z ziemi Beniamina, z równin, z gór i z południa, przynosząc całopalenia, ofiary, dary i kadzidło i przynosząc także dziękczynienie do domu Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 27, 'Ale jeśli mnie nie usłuchacie, aby święcić dzień szabatu i nie nosić ciężaru, gdy wchodzicie przez bramy Jerozolimy w dzień szabatu, wtedy rozniecę ogień w jej bramach, który pochłonie pałace Jerozolimy i nie będzie ugaszony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 1, 'Słowo, które doszło do Jeremiasza od Pana, mówiące:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 2, 'Wstań i zejdź do domu garncarza, a tam sprawię, że usłyszysz moje słowa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 3, 'Zstąpiłem więc do domu garncarza, a oto on wykonywał pracę na kole.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 4, 'A naczynie, które wykonywał z gliny, uległo zniekształceniu w ręce garncarza. Uczynił więc z niej inne naczynie, jak mu się podobało uczynić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 5, 'I doszło do mnie słowo Pana mówiące:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 6, 'Czyż nie mogę z wami postąpić tak jak ten garncarz, domu Izraela? – mówi Pan. Oto jak glina w ręce garncarza tak wy jesteście w moim ręku, domu Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 7, 'Gdy raz ogłoszę przeciwko narodowi i przeciwko królestwu, że je wykorzenię, wywrócę i zniszczę;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 8, 'A jednak ten naród, przeciw któremu mówiłem, odwróci się od swojego zła, będę żałował nieszczęścia, które zamierzam na niego zesłać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 9, 'Gdy innym razem ogłoszę o narodzie i o królestwie, że je zbuduję i zasadzę;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 10, 'Jeśli jednak uczyni to, co złe w moich oczach i nie usłucha mego głosu, ja będę żałował tego dobrodziejstwa, jakim obiecałem je obdarzyć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 11, 'Dlatego powiedz teraz do Judejczyków i do mieszkańców Jerozolimy: Tak mówi Pan: Oto przygotowuję na was nieszczęście i obmyślam zamysł przeciwko wam. Niech więc każdy zawróci ze swojej złej drogi; poprawcie wasze drogi i czyny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 12, 'Ale oni odpowiedzieli: Nic z tego. Pójdziemy raczej za własnymi zamysłami, każdy będzie postępował według uporu swego złego serca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 13, 'Dlatego tak mówi Pan: Zapytajcie teraz wśród pogan, czy ktoś słyszał coś takiego. Straszny czyn popełniła dziewica Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 14, 'Czy człowiek opuści śnieg ze skalistych pól Libanu? Czy ktoś opuści zimne wody płynące z daleka?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 15, 'Ale mój lud zapomniał o mnie, pali kadzidło marnościom, które sprawiły, że potyka się na swoich drogach, na starodawnych ścieżkach, by chodzić po ścieżkach, po drodze nieutorowanej;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 16, 'Aby zamienić swoją ziemię w spustoszenie, w wieczne świstanie. Każdy, kto będzie przez nią przechodził, zdumieje się i będzie kiwał głową.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 17, 'Jak wschodni wiatr rozproszę ich przed wrogiem. Pokażę im plecy, a nie twarz w dniu ich zatracenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 18, 'I powiedzieli: Chodźcie, obmyślmy zamysły przeciwko Jeremiaszowi, bo nie zaginie prawo od kapłana, ani rada od mądrego, ani słowo od proroka. Chodźcie, uderzmy go językiem i nie zważajmy na żadne jego słowa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 19, 'Zważaj na mnie, Panie, i słuchaj głosu tych, którzy się spierają ze mną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 20, 'Czy odpłaca się złem za dobro? Bo wykopali dół dla mojej duszy. Wspomnij, że stawałem przed tobą, aby mówić za nimi dla ich dobra i odwrócić od nich twój gniew.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 21, 'Dlatego wydaj ich dzieci na głód i spraw, aby padli od mocy miecza; niech ich żony będą osierocone i owdowiałe, ich mężczyźni haniebnie uśmierceni, a ich młodzieńcy zabici mieczem na wojnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 22, 'Niech będzie słychać krzyk z ich domów, gdy nagle sprowadzisz na nich wojsko. Wykopali bowiem dół, aby mnie schwytać, zastawili sidła na moje nogi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 23, 'Lecz ty, Panie, znasz wszystkie ich plany przeciwko mnie, chcą mojej śmierci. Nie przebaczaj im ich nieprawości, a ich grzechu nie zmaż sprzed swego oblicza, ale niech upadną przed tobą. Postąp z nimi tak w czasie twojego gniewu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 1, 'Tak mówi Pan: Idź i kup dzban gliniany od garncarza, weź ze sobą kilka osób spośród starszych ludu i starszych kapłanów;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 2, 'Wyjdź do doliny syna Hinnom, która znajduje się przy wejściu do Bramy Wschodniej, i głoś tam słowa, które do ciebie będę mówić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 3, 'Powiedz: Słuchajcie słowa Pana, królowie Judy i mieszkańcy Jerozolimy! Tak mówi Pan zastępów, Bóg Izraela: Oto sprowadzę nieszczęście na to miejsce, a każdemu, kto usłyszy, zaszumi w uszach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 4, 'Ponieważ mnie opuścili i zbezcześcili to miejsce, paląc w nim kadzidło innym bogom, których nie znali oni ani ich ojcowie oraz królowie Judy, i napełnili to miejsce krwią niewinnych;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 5, 'I pobudowali wyżyny Baalowi, aby spalić swoich synów w ogniu jako całopalenia dla Baala, czego im nie nakazałem ani nie mówiłem i co nie przyszło mi nawet na myśl.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 6, 'Dlatego oto nadchodzą dni, mówi Pan, w których to miejsce nie będzie już nazywane Tofet ani Doliną Syna Hinnom, ale Doliną Rzezi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 7, 'I wniwecz obrócę radę Judy i Jerozolimy na tym miejscu i sprawię, że padną od miecza przed swoimi wrogami i od ręki tych, którzy czyhają na ich życie. I wydam ich trupy na pożarcie ptactwu nieba i zwierzętom ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 8, 'Wydam także to miasto na spustoszenie i na świstanie; każdy, kto będzie przechodził obok, zdumieje się i będzie świstać z powodu wszystkich jego plag.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 9, 'I sprawię, że będą jeść ciała swoich synów i ciała swoich córek, a każdy z nich będzie jeść ciało swego bliźniego podczas oblężenia i w ucisku, którymi ścisną ich wrogowie i ci, którzy czyhają na ich życie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 10, 'Potem stłucz ten dzban na oczach tych mężczyzn, którzy pójdą z tobą;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 11, 'I powiedz im: Tak mówi Pan zastępów: Tak samo rozbiję ten lud i to miasto, jak tłucze się naczynie garncarskie, którego nie można potem naprawić. I będą grzebać zmarłych w Tofet, bo nie będzie innego miejsca na grzebanie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 12, 'Tak uczynię temu miejscu, mówi Pan, i jego mieszkańcom, i postąpię z tym miastem tak jak z Tofet.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 13, 'I domy Jerozolimy i domy królów Judy będą nieczyste jak to miejsce Tofet z powodu wszystkich domów, na których dachach palili kadzidło wszystkim zastępom nieba i wylewali ofiary z płynów innym bogom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 14, 'Wtedy Jeremiasz wrócił z Tofet, dokąd wysłał go Pan, aby tam prorokował, stanął na dziedzińcu domu Pana i powiedział do całego ludu:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 15, 'Tak mówi Pan zastępów, Bóg Izraela: Oto sprowadzę na to miasto i na wszystkie okoliczne miasta całe to nieszczęście, które zapowiedziałem przeciwko niemu, bo zatwardzili swój kark, aby nie słuchać moich słów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 1, 'A kapłan Paszchur, syn Immera, który był naczelnym przywódcą w domu Pana, usłyszał Jeremiasza prorokującego o tym;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 2, 'I Paszchur uderzył proroka Jeremiasza, i zakuł go w dyby, które były w Górnej Bramie Beniamina, przy domu Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 3, 'A nazajutrz, gdy Paszchur uwolnił Jeremiasza z dybów, Jeremiasz powiedział do niego: Pan nie nazwał cię Paszchur, lecz Magormissabib.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 4, 'Tak bowiem mówi Pan: Oto uczynię z ciebie postrach dla ciebie samego i dla wszystkich twoich przyjaciół. Padną od miecza swoich wrogów, a twoje oczy będą na to patrzeć. Całą Judę wydam w ręce króla Babilonu, który ich uprowadzi do niewoli do Babilonu i pozabija mieczem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 5, 'Wydam też wszystkie bogactwa tego miasta, cały jego dobytek, wszystkie jego kosztowności i wszystkie skarby królów Judy – wydam w ręce ich wrogów. Ci złupią je, zabiorą i wywiozą do Babilonu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 6, 'Ale ty, Paszchurze, i wszyscy, którzy mieszkają w twym domu, pójdziecie do niewoli. Przyjdziesz do Babilonu i tam umrzesz, i tam zostaniesz pogrzebany, ty i wszyscy twoi przyjaciele, którym kłamliwie prorokowałeś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 7, 'Namówiłeś mnie, Panie, a dałem się namówić. Ty jesteś silniejszy ode mnie i mnie przemogłeś. Jestem wystawiony na pośmiewisko każdego dnia, każdy się ze mnie naśmiewa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 8, 'Odkąd bowiem zacząłem mówić, wołam; krzyczę o przemocy i spustoszeniu, bo słowo Pana stało się dla mnie pohańbieniem i pośmiewiskiem każdego dnia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 9, 'I powiedziałem: Nie będę go wspominał ani nie będę już mówił w jego imię. Ale słowo Boże jest w moim sercu jakby ogień płonący, zamknięty w moich kościach, i usiłowałem je wstrzymać, ale nie mogłem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 10, 'Słyszę bowiem oszczerstwo wielu, strach dokoła. Mówią: Donoście, a my o tym doniesiemy. Wszyscy moi przyjaciele czyhają na mój upadek, mówiąc: Może da się zwabić, potem przemożemy go i zemścimy się na nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 11, 'Ale Pan jest ze mną jak straszliwy mocarz. Dlatego moi prześladowcy upadną i nie przemogą mnie. Będą bardzo zawstydzeni, że im się nie powiodło. Ich wieczna hańba nie będzie zapomniana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 12, 'Dlatego, Panie zastępów, który doświadczasz sprawiedliwego, który widzisz nerki i serce, niech zobaczę twoją pomstę nad nimi. Tobie bowiem powierzyłem swoją sprawę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 13, 'Śpiewajcie Panu, chwalcie Pana, gdyż wybawił duszę ubogiego z ręki złoczyńców.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 14, 'Przeklęty dzień, w którym się urodziłem. Niech dzień, w którym urodziła mnie moja matka, nie będzie błogosławiony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 15, 'Przeklęty człowiek, który oznajmił memu ojcu, mówiąc: Urodziło ci się dziecko, chłopiec, sprawiając mu wielką radość.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 16, 'Niech ten człowiek będzie jak miasta, które Pan zniszczył bez żalu. Niech słyszy krzyk o poranku i wołanie w południe;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 17, 'Za to, że mnie nie zabił zaraz od łona, by moja matka była moim grobem, a jej łono – wiecznie brzemienne!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 18, 'Po co wyszedłem z łona – aby doznawać trudu i smutku, aby moje dni były strawione wśród hańby?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 1, 'Słowo, które doszło do Jeremiasza od Pana, gdy król Sedekiasz posłał do niego Paszchura, syna Malkiasza, i Sofoniasza, syna Maasejasza, kapłana, aby powiedzieli:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 2, 'Poradź się, proszę, Pana w naszej sprawie, bo Nabuchodonozor, król Babilonu, walczy przeciwko nam. Może Pan postąpi z nami zgodnie ze wszystkimi swoimi cudownymi dziełami, aby ten odstąpił od nas.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 3, 'Jeremiasz odpowiedział im: Tak powiedzcie Sedekiaszowi:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 4, 'Tak mówi Pan, Bóg Izraela: Oto odwrócę sprzęt wojenny, który jest w waszych rękach, i którym walczycie przeciw królowi Babilonu i przeciwko Chaldejczykom, którzy was oblegli dokoła muru, i zgromadzę ich w środku tego miasta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 5, 'A ja sam będę walczył przeciwko wam wyciągniętą ręką i mocnym ramieniem, z gniewem, zawziętością i wielką zapalczywością.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 6, 'I pobiję mieszkańców tego miasta, zarówno ludzi, jak i zwierzęta. Umrą od wielkiej zarazy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 7, 'A potem, mówi Pan, wydam Sedekiasza, króla Judy, jego sługi i lud oraz ocalałych w tym mieście od zarazy, od miecza i od głodu w ręce Nabuchodonozora, króla Babilonu, w ręce ich wrogów i w ręce czyhających na ich życie. A on pobije ich ostrzem miecza, nie pożałuje ich ani nie oszczędzi, ani się nie zlituje.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 8, 'A ludowi temu powiedz: Tak mówi Pan: Oto kładę przed wami drogę życia i drogę śmierci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 9, 'Ktokolwiek zostanie w tym mieście, zginie od miecza, z głodu i od zarazy. Kto zaś wyjdzie i podda się Chaldejczykom, którzy was oblegli, pozostanie żywy i jego życie będzie dla niego jak zdobycz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 10, 'Zwróciłem bowiem swoje oblicze przeciwko temu miastu na zło, a nie na dobro, mówi Pan. Będzie wydane w ręce króla Babilonu, a on spali je ogniem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 11, 'Ale do domu króla Judy powiedz: Słuchajcie słowa Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 12, 'Domu Dawida, tak mówi Pan: Sprawujcie sąd każdego poranka i wybawiajcie uciśnionego z ręki ciemięzcy, aby moja zapalczywość nie wybuchła jak ogień i nie płonął on tak, że nikt nie zdoła go zgasić z powodu zła waszych uczynków.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 13, 'Oto ja jestem przeciwko tobie, mieszkanko doliny, skało równiny, mówi Pan – przeciwko wam, którzy mówicie: Któż nadciągnie na nas? Któż wejdzie do naszych mieszkań?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 14, 'Lecz ja was nawiedzę według owocu waszych uczynków, mówi Pan. Rozniecę ogień w jej lesie, który pochłonie wszystko dokoła niego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 1, 'Tak mówi Pan: Zejdź do domu króla Judy i mów tam to słowo;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 2, 'Powiedz: Słuchaj słowa Pana, królu Judy, który zasiadasz na tronie Dawida, ty i twoi słudzy oraz twój lud, którzy wchodzicie przez te bramy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 3, 'Tak mówi Pan: Wykonajcie sąd i sprawiedliwość i wybawiajcie uciśnionego z ręki ciemięzcy. Nie krzywdźcie ani nie uciskajcie obcego, sieroty i wdowy i nie przelewajcie krwi niewinnej na tym miejscu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 4, 'Jeśli bowiem rzeczywiście spełnicie to słowo, wtedy będą wchodzić przez bramy tego domu królowie zasiadający na tronie, jeżdżący na rydwanach i na koniach, sam król i jego słudzy, i jego lud.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 5, 'Lecz jeśli nie posłuchacie tych słów, sam na siebie przysięgam, mówi Pan, że ten dom stanie się pustkowiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 6, 'Tak bowiem mówi Pan o domu króla Judy: Ty jesteś mi Gileadem i szczytem Libanu, lecz naprawdę zamienię cię w pustynię i w miasta niezamieszkane.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 7, 'I przygotuję przeciwko tobie niszczycieli, każdego ze swoim sprzętem. Wytną twoje wyborne cedry i wrzucą je w ogień.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 8, 'I wiele narodów będzie przechodzić koło tego miasta, i powiedzą jeden do drugiego: Dlaczego Pan tak uczynił temu wielkiemu miastu?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 9, 'Wtedy odpowiedzą: Dlatego że porzucili przymierze Pana, swego Boga, a oddawali pokłon innym bogom i służyli im.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 10, 'Nie opłakujcie zmarłego ani nie żałujcie go, lecz nieustannie płaczcie nad tym, który odchodzi, bo już nigdy nie wróci ani nie zobaczy swojej rodzinnej ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 11, 'Tak bowiem mówi Pan o Szallumie, synu Jozjasza, króla Judy, który królował w miejsce Jozjasza, swego ojca, który wyszedł z tego miejsca: Już nigdy nie wróci;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 12, 'Ale umrze na tym miejscu, gdzie go przeniosą, i już nie zobaczy tej ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 13, 'Biada temu, kto buduje swój dom na niesprawiedliwości, a swoje komnaty na krzywdzie; kto swemu bliźniemu każe pracować za darmo i nie daje mu jego zapłaty;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 14, 'Który mówi: Zbuduję sobie wielki dom i przestronne komnaty; wybija sobie okna, wykłada jego wnętrze drzewem cedrowym i maluje cynobrem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 15, 'Czy będziesz królował dlatego, że otaczasz się cedrem? Czyż twój ojciec nie jadał i nie pijał? A kiedy wykonywał sąd i sprawiedliwość, wtedy było mu dobrze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 16, 'Gdy sądził sprawę ubogiego i nędznego, wtedy było mu dobrze. Czy nie na tym polega poznanie mnie? – mówi Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 17, 'Lecz twoje oczy i serce pragną jedynie własnej korzyści, przelania niewinnej krwi, wywierania ucisku oraz przemocy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 18, 'Dlatego tak mówi Pan o Joakimie, synu Jozjasza, króla Judy: Nie będą go opłakiwać ani mówić: Ach, mój bracie! Albo: Ach, siostro! Nie będą go opłakiwać ani mówić: Ach, panie! Albo: Ach, jego majestat!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 19, 'Będzie pogrzebany jak osioł, wywloką go i wyrzucą poza bramy Jerozolimy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 20, 'Wejdź na Liban i wołaj, na Baszanie podnieś swój głos, wołaj też z przełęczy, gdyż wszyscy twoi kochankowie zostali zniszczeni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 21, 'Przemówiłem do ciebie w czasie twojej pomyślności, ale powiedziałaś: Nie posłucham. Taka jest twoja droga od twej młodości, nie usłuchałaś mojego głosu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 22, 'Wiatr rozproszy wszystkich twoich pasterzy i twoi kochankowie pójdę w niewolę. Wtedy będziesz się rumienić i wstydzić z powodu całej twojej niegodziwości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 23, 'Ty, która mieszkasz na Libanie, która robisz sobie gniazdo wśród cedrów, jakże będziesz pełna wdzięku, gdy ogarną cię boleści jak bóle rodzącej!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 24, 'Jak żyję ja, mówi Pan, choćby Choniasz, syn Joakima, króla Judy, był sygnetem na mojej prawej ręce, zerwałbym cię stamtąd;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 25, 'I wydam cię w ręce tych, którzy czyhają na twoje życie, i w ręce tych, których twarzy ty się lękasz, to jest, w ręce Nabuchodonozora, króla Babilonu, i w ręce Chaldejczyków;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 26, 'Wyrzucę ciebie i twoją matkę, która cię urodziła, do obcej ziemi, w której się nie urodziliście, i tam pomrzecie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 27, 'Lecz do ziemi, za którą będą tęsknić, aby tam wrócić, nie wrócą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 28, 'Czy ten człowiek, Choniasz, jest posągiem wzgardzonym i zdruzgotanym? Albo naczyniem, w którym nie ma żadnego piękna? Czemu zostali odrzuceni on i jego potomstwo i wyrzuceni do ziemi, której nie znają?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 29, 'Ziemio, ziemio, ziemio! Słuchaj słowa Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 30, 'Tak mówi Pan: Zapiszcie tego człowieka jako bezpotomnego i że mu się nie poszczęści za jego dni. Nie poszczęści się nikomu z jego potomstwa, by zasiąść na tronie Dawida i panować jeszcze w Judzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 1, 'Biada pasterzom, którzy gubią i rozpraszają trzodę mego pastwiska! – mówi Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 2, 'Dlatego tak mówi Pan, Bóg Izraela, do pasterzy, którzy pasą mój lud: Wy rozpraszacie moje owce i rozganiacie je, a nie nawiedzaliście ich. Oto nawiedzę was za zło waszych uczynków, mówi Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 3, 'I zgromadzę resztkę moich owiec ze wszystkich krajów, do których je rozpędziłem, i sprowadzę je do ich owczarni; będą płodne i rozmnożą się.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 4, 'Ustanowię nad nimi pasterzy, którzy będą je paść, aby już się nie lękały i nie trwożyły, i aby żadna z nich nie zginęła, mówi Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 5, 'Oto nadchodzą dni, mówi Pan, w których wzbudzę Dawidowi sprawiedliwą Latorośl i będzie panować Król, i będzie mu się szczęściło; będzie wykonywał sąd i sprawiedliwość na ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 6, 'Za jego dni Juda będzie zbawiona, a Izrael będzie mieszkał bezpiecznie. A to jest jego imię, którym będą go nazywać: Pan Naszą Sprawiedliwością.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 7, 'Dlatego oto nadejdą dni, mówi Pan, że nie będą mówić już: Jak żyje Pan, który wyprowadził synów Izraela z ziemi Egiptu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 8, 'Ale: Jak żyje Pan, który wyprowadził i który sprowadził potomstwo domu Izraela z kraju północnego i ze wszystkich krajów, do których rozpędziłem ich, i będą mieszkać w swojej ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 9, 'Moje serce pęka we mnie z powodu proroków, wszystkie moje kości drżą; jestem jak człowiek pijany, jak człowiek, którego zmogło wino, z powodu Pana i z powodu słów jego świętości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 10, 'Ziemia bowiem jest pełna cudzołożników i płacze z powodu przekleństwa; pastwiska na pustkowiu wyschły; ich dążenia są niegodziwe, a ich siła jest niewłaściwa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 11, 'Bo zarówno prorok, jak i kapłan są obłudnikami, nawet w moim domu znajduje się ich niegodziwość, mówi Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 12, 'Dlatego ich droga stanie się dla nich jak ślizgawica w ciemności, na którą będą popędzeni i upadną, gdy sprowadzę na nich nieszczęście w roku, kiedy ich nawiedzę, mówi Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 13, 'Widziałem u proroków Samarii głupstwo: prorokowali w imię Baala i zwodzili mój lud Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 14, 'A u proroków Jerozolimy widziałem okropność: cudzołożą i postępują kłamliwie, utwierdzają też ręce złoczyńców, tak że żaden z nich nie odwraca się od swojej niegodziwości. Wszyscy stali się dla mnie jak Sodoma, a jego mieszkańcy jak Gomora.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 15, 'Dlatego tak mówi Pan zastępów o tych prorokach: Oto nakarmię ich piołunem i napoję ich wodą żółci, bo od proroków Jerozolimy rozeszła się niegodziwość na całą tę ziemię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 16, 'Tak mówi Pan zastępów: Nie słuchajcie słów tych proroków, którzy wam prorokują. Oni was zwodzą, zwiastują wam widzenie własnego serca, a nie z ust Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 17, 'Nieustannie mówią tym, którzy mną gardzą: Pan mówił: Będziecie mieć pokój. A każdemu, który postępuje według uporu swego serca, mówią: Nie spotka was nic złego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 18, 'Któż bowiem stał w radzie Pana, widział i słyszał jego słowo? Kto rozważył jego słowa i usłyszał je?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 19, 'Oto wicher Pana wyjdzie z zapalczywością, wicher ciężki spadnie na głowę bezbożnych;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 20, 'Nie odwróci się gniew Pana, aż spełni i wykona on myśli swego serca. W ostatecznych czasach dokładnie to zrozumiecie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 21, 'Nie posłałem tych proroków, a oni jednak pobiegli. Nie mówiłem do nich, oni jednak prorokowali.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 22, 'Lecz gdyby stali w mojej radzie i głosili mojemu ludowi moje słowa, odwróciliby go od jego złej drogi i od zła jego uczynków.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 23, 'Czy jestem tylko Bogiem z bliska? – mówi Pan, a nie Bogiem także z daleka?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 24, 'Czy może się kto schować w ukryciu, abym go nie widział? – mówi Pan. Czy nie wypełniam nieba i ziemi? – mówi Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 25, 'Słyszałem, co mówią prorocy, którzy prorokują kłamstwa w moje imię, mówiąc: Miałem sen, miałem sen.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 26, 'Jak długo to będzie w sercu tych proroków, którzy prorokują kłamstwa? Są przecież prorokami złudy własnego serca;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 27, 'Którzy zamierzają sprawić, aby mój lud zapomniał moje imię przez swoje sny, które każdy opowiada swemu bliźniemu, jak ich ojcowie zapomnieli o moim imieniu dla Baala.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 28, 'Prorok, który ma sen, niech ten sen opowiada, ale ten, który ma moje słowo, niech wiernie mówi moje słowo. Cóż plewie do pszenicy? – mówi Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 29, 'Czy moje słowo nie jest jak ogień? – mówi Pan – i jak młot, który kruszy skałę?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 30, 'Dlatego oto powstaję przeciwko tym prorokom, mówi Pan, którzy kradną moje słowa, każdy kradnie je swojemu bliźniemu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 31, 'Oto powstaję przeciwko tym prorokom, mówi Pan, którzy używają swego języka, aby mówić: Pan mówi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 32, 'Oto powstaję, mówi Pan, przeciwko tym, którzy prorokują sny kłamliwe, opowiadają je i zwodzą mój lud swymi kłamstwami i plotkami, chociaż ja ich nie posłałem ani im niczego nie rozkazałem. Dlatego nic nie pomagają temu ludowi, mówi Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 33, 'A gdy ten lud albo prorok lub kapłan zapytają cię: Jakie jest brzemię Pana? – wtedy odpowiesz: Jakie brzemię? – właśnie takie: Opuszczę was, mówi Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 34, 'A proroka i kapłana oraz ten lud, którzy powiedzą: Brzemię Pana, naprawdę nawiedzę karą – ich i ich dom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 35, 'Ale tak mówcie każdy do swego bliźniego i każdy do swego brata: Cóż odpowiedział Pan? albo: Cóż mówił Pan?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 36, 'I nie wspomnicie już brzemienia Pana, bo brzemieniem stanie się dla każdego jego słowo, gdyż wy wypaczyliście słowa Boga żywego, Pana zastępów, naszego Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 37, 'Tak więc powiesz do proroka: Cóż ci odpowiedział Pan? albo: Co mówił Pan?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 38, 'Ale ponieważ mówicie: Brzemię Pana, to wtedy tak mówi Pan: Ponieważ mówicie to słowo: Brzemię Pana, chociaż nakazałem wam, mówiąc: Nie mówcie: Brzemię Pana;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 39, 'Oto ja zapomnę o was całkowicie i odrzucę sprzed mego oblicza was i to miasto, które dałem wam i waszym ojcom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 40, 'I okryję was wieczną wzgardą i wieczną hańbą, która nigdy nie pójdzie w zapomnienie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 1, 'Pan ukazał mi widzenie, a oto dwa kosze fig były postawione przed świątynią Pana, gdy Nabuchodonozor, król Babilonu, uprowadził do niewoli Jechoniasza, syna Joakima, króla Judy, oraz książąt Judy, cieśli i kowali z Jerozolimy, i przyprowadził ich do Babilonu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 2, 'Jeden kosz zawierał bardzo dobre figi, jakimi są figi dojrzałe, a drugi kosz zawierał bardzo złe figi, tak złe, że nie można było ich jeść.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 3, 'I Pan zapytał mnie: Co widzisz, Jeremiaszu? Odpowiedziałem: Figi. Dobre figi są bardzo dobre, a złe są bardzo złe, tak złe, że nie można było ich jeść.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 4, 'I doszło do mnie słowo Pana mówiące:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 5, 'Tak mówi Pan, Bóg Izraela: Jak na te dobre figi, tak spojrzę łaskawie na tych z Judy, którzy zostali uprowadzeni do niewoli, których wysłałem z tego miejsca do ziemi Chaldejczyków, dla ich dobra.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 6, 'I zwrócę na nich swoje oko dla ich dobra i przyprowadzę ich do tej ziemi, gdzie ich odbuduję, a nie zburzę, i zasadzę, a nie wykorzenię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 7, 'Dam im bowiem serce, aby mnie poznali, że ja jestem Pan. Oni będą moim ludem, a ja będę ich Bogiem, gdyż nawrócą się do mnie całym swoim sercem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 8, 'A jak te złe figi, których nie można jeść, bo są tak złe, tak mówi Pan: Tak samo postąpię z Sedekiaszem, królem Judy, z jego książętami, z resztką Jerozolimy, która pozostała w tej ziemi, oraz z tymi, którzy mieszkają w ziemi Egiptu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 9, 'Wydam ich na wysiedlenie i na ucisk we wszystkich królestwach ziemi, na pohańbienie i na przysłowie, na pośmiewisko i na przekleństwo we wszystkich miejscach, do których ich wypędzę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 10, 'I będę posyłał na nich miecz, głód i zarazę, aż będą wytraceni z ziemi, którą dałem im oraz ich ojcom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 1, 'Słowo, które doszło do Jeremiasza o całym ludzie Judy w czwartym roku Joakima, syna Jozjasza, króla Judy, a był to pierwszy rok Nabuchodonozora, króla Babilonu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 2, 'Które wypowiedział prorok Jeremiasz do całego ludu Judy i do wszystkich mieszkańców Jerozolimy, mówiąc:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 3, 'Od trzynastego roku Jozjasza, syna Amona, króla Judy, aż do dziś, to znaczy już przez dwadzieścia trzy lata, dochodziło do mnie słowo Pana i przemawiałem do was z wczesnym wstawaniem i mówieniem, ale nie słuchaliście.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 4, 'Pan też posyłał do was wszystkie swoje sługi, proroków, z wczesnym wstawaniem i przesłaniem, ale nie usłuchaliście ani nie nakłoniliście swego ucha, aby usłyszeć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 5, 'Oni mówili: Niech teraz każdy z was się odwróci od swojej złej drogi i od zła swoich uczynków, a będziecie mieszkać w tej ziemi, którą Pan dał wam i waszym ojcom na wieki wieków.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 6, 'Nie chodźcie za innymi bogami, aby im służyć i oddawać im pokłon, i nie pobudzajcie mnie do gniewu uczynkami waszych rąk, a ja nie uczynię wam nic złego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 7, 'Ale nie usłuchaliście mnie, mówi Pan, pobudzając mnie do gniewu uczynkami swoich rąk na własne nieszczęście.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 8, 'Dlatego tak mówi Pan zastępów: Ponieważ nie usłuchaliście moich słów;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 9, 'Oto poślę po wszystkie rody północne i zbiorę je, mówi Pan, i Nabuchodonozora, króla Babilonu, swego sługę, i sprowadzę ich na tę ziemię, na jej mieszkańców i na te wszystkie okoliczne narody, a doszczętnie zniszczę ich i uczynię ich przedmiotem zdumienia i świstania, i wiecznym spustoszeniem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 10, 'I sprawię, że zaniknie głos wesela i głos radości, głos oblubieńca i głos oblubienicy, odgłos żaren i światło pochodni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 11, 'I cała ta ziemia stanie się spustoszeniem i zdumieniem, a te narody będą służyć królowi Babilonu przez siedemdziesiąt lat.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 12, 'A gdy się dopełni siedemdziesiąt lat, ukarzę króla Babilonu i ten naród, mówi Pan, za ich nieprawość, oraz ziemię Chaldejczyków, i zamienię ją w wieczne spustoszenie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 13, 'I sprowadzę na tę ziemię wszystkie moje słowa, które wypowiedziałem przeciw niej, mianowicie to wszystko, co jest napisane w tej księdze, co prorokował Jeremiasz przeciw wszystkim narodom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 14, 'Gdyż i one będą podbite i wzięte do niewoli przez liczne narody i wielkich królów. Odpłacę im według ich czynów i według uczynków ich rąk.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 15, 'Tak bowiem powiedział do mnie Pan, Bóg Izraela: Weź z mojej ręki kubek wina tej zapalczywości i daj z niego pić wszystkim narodom, do których cię posyłam.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 16, 'Będą pić i zataczać się, a nawet szaleć przed ostrzem miecza, który posyłam między nie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 17, 'Wziąłem więc kubek z ręki Pana i napoiłem wszystkie narody, do których Pan mnie posłał:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 18, 'Jerozolimę i miasta ziemi Judy, jej królów i książąt, aby uczynić ich przedmiotem spustoszenia, zdumienia, świstania i przekleństwa, jak to jest dzisiaj;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 19, 'Faraona, króla Egiptu, jego sługi i książąt, oraz cały jego lud;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 20, 'Całą różnorodną ludność, wszystkich królów ziemi Uz, wszystkich królów ziemi Filistynów oraz Aszkelon, Gazę, Ekron i resztkę Aszdodu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 21, 'Edom, Moab i synów Ammona;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 22, 'Wszystkich królów Tyru, wszystkich królów Sydonu oraz królów zamorskich wysp;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 23, 'Dedan, Temę, Buzę i wszystkich mieszkańców w najdalszych zakątkach:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 24, 'Wszystkich królów Arabii i wszystkich królów różnorodnej ludności mieszkającej na pustyni;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 25, 'Wszystkich królów Zimri, wszystkich królów Elamu i wszystkich królów Medii;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 26, 'I wszystkich królów Północy, bliskich i dalekich, jednego po drugim; wszystkie królestwa ziemi, jakie są na powierzchni ziemi. A król Szeszak będzie po nich pił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 27, 'I powiesz im: Tak mówi Pan zastępów, Bóg Izraela: Pijcie i upijacie się, wymiotujcie i padajcie, aby już nie powstać z powodu miecza, który ja poślę między was.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 28, 'A jeśli nie zechcą wziąć kubka z twojej ręki, aby pić, wtedy im powiesz: Tak mówi Pan zastępów: Koniecznie będziecie pić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 29, 'Oto bowiem na to miasto, nad którym jest wzywane moje imię, zaczynam sprowadzać nieszczęście, a wy mielibyście pozostać nieukarani? Nie ujdziecie karze, bo ja przyzywam miecz na wszystkich mieszkańców tej ziemi, mówi Pan zastępów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 30, 'Dlatego ty prorokuj przeciwko nim wszystkie te słowa i powiedz im: Pan zagrzmi z wysoka i ze swego Świętego Przybytku wyda swój głos; zagrzmi nad swoim miejscem zamieszkania; wzniesie okrzyk jak tłoczący winogrona przeciwko wszystkim mieszkańcom tej ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 31, 'I dojdzie wrzawa aż do krańców ziemi, bo Pan prowadzi spór z tymi narodami, sprawuje sąd nad wszelkim ciałem, bezbożnych wyda pod miecz, mówi Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 32, 'Tak mówi Pan zastępów: Oto nieszczęście przejdzie z narodu na naród, a wielki wicher zerwie się od krańców ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 33, 'I pobici przez Pana w tym dniu leżeć będą od krańca ziemi aż po kraniec ziemi; nie będą ich opłakiwać ani zbierać, ani grzebać, będą jak nawóz na polu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 34, 'Zawódźcie, pasterze, i wołajcie, tarzajcie się w popiele, wy, przewodnicy tej trzody! Dopełniły się bowiem dni waszej rzezi i rozproszenia i padniecie jak drogie naczynie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 35, 'Nie będzie ucieczki dla pasterzy ani ocalenia dla przewodników tej trzody.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 36, 'Będzie słychać głos wołania pasterzy i zawodzenie przewodników tej trzody, bo Pan spustoszy ich pastwiska.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 37, 'I będą zniszczone spokojne łąki z powodu zapalczywości gniewu Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 38, 'Opuścił jak lew swoją jaskinię, bo ich ziemia jest spustoszona z powodu zapalczywości niszczyciela i zapalczywości jego gniewu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 1, 'Na początku królowania Joakima, syna Jozjasza, króla Judy, doszło to słowo od Pana mówiące:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 2, 'Tak mówi Pan: Stań na dziedzińcu domu Pana i mów do wszystkich miast Judy, do tych, którzy przychodzą oddać pokłon w domu Pana, wszystkie słowa, które nakazuję ci mówić do nich; nie ujmuj ani słowa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 3, 'Może usłuchają i odwrócą się, każdy od swojej złej drogi, abym żałował nieszczęścia, które zamierzałem im uczynić z powodu zła ich uczynków.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 4, 'I powiesz im: Tak mówi Pan: Jeśli mnie nie usłuchacie, by postępować według mojego prawa, które wam przedłożyłem;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 5, 'By słuchać słów moich sług, proroków, których posłałem do was, z wczesnym wstawaniem i przesłaniem, a przecież nie usłuchaliście;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 6, 'Wtedy postąpię z tym domem tak jak z Szilo, a to miasto uczynię przekleństwem dla wszystkich narodów ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 7, 'A kapłani i prorocy oraz cały lud słyszeli Jeremiasza mówiącego te słowa w domu Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 8, 'A gdy Jeremiasz skończył mówić wszystko, co Pan mu nakazał powiedzieć całemu ludowi, pojmali go ci kapłani i prorocy oraz cały lud, mówiąc: Musisz umrzeć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 9, 'Czemu prorokowałeś w imię Pana, głosząc: Z tym domem stanie się jak z Szilo, a to miasto tak spustoszeje, że nie będzie w nim mieszkańca? I zgromadził się cały lud przeciwko Jeremiaszowi w domu Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 10, 'Gdy książęta Judy usłyszeli te rzeczy, przyszli z domu królewskiego do domu Pana i zasiedli u wejścia nowej bramy Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 11, 'Wtedy kapłani i prorocy powiedzieli do książąt i do całego ludu: Ten człowiek zasługuje na śmierć, bo prorokował przeciwko temu miastu, jak to słyszeliście na własne uszy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 12, 'Jeremiasz zaś odezwał się do wszystkich książąt i do całego ludu, mówiąc: Pan mnie posłał, abym prorokował przeciw temu domowi i przeciw temu miastu to wszystko, co słyszeliście.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 13, 'Dlatego teraz poprawcie swoje drogi i swoje uczynki i usłuchajcie głosu Pana, swego Boga, a pożałuje Pan tego nieszczęścia, jakie zapowiedział przeciwko wam.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 14, 'Co do mnie, ja jestem w waszych rękach, czyńcie ze mną to, co dobre i sprawiedliwe w waszych oczach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 15, 'Wiedzcie jednak na pewno – jeśli mnie zabijecie, ściągniecie krew niewinną na siebie, na to miasto i na jego mieszkańców. Naprawdę bowiem Pan posłał mnie do was, abym mówił te wszystkie słowa do waszych uszu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 16, 'Wtedy książęta i cały lud powiedzieli do kapłanów i do proroków: Ten człowiek nie zasługuje na śmierć, ponieważ przemawiał do nas w imię Pana, naszego Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 17, 'Powstali też niektórzy ze starszych tej ziemi i powiedzieli do całego zgromadzenia ludu:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 18, 'Micheasz z Moreszet prorokował za dni Ezechiasza, króla Judy, i mówił do całego ludu Judy: Tak mówi Pan zastępów: Syjon będzie zaorany jak pole, Jerozolima stanie się rumowiskiem, a góra tego domu – jak zalesione wzgórze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 19, 'Czy zabił go Ezechiasz, król Judy, i Juda? Czy nie ulękli się Pana i nie modlili się do Pana tak, że Pan żałował tego nieszczęścia, jakie zapowiedział przeciwko nim? Przecież ściągniemy na nasze dusze wielkie nieszczęście.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 20, 'Był także człowiek, który prorokował w imię Pana, Uriasz, syn Szemajasza, z Kiriat-Jearim. Prorokował on przeciwko temu miastu i przeciwko tej ziemi zgodnie ze wszystkimi słowami Jeremiasza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 21, 'A gdy król Joakim, wszyscy jego wojownicy i wszyscy książęta usłyszeli jego słowa, król usiłował go zabić. Lecz gdy Uriasz o tym usłyszał, zląkł się, uciekł i przybył do Egiptu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 22, 'Ale król Joakim posłał ludzi do Egiptu: Elnatana, syna Akbora, i innych razem z nim do Egiptu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 23, 'Ci sprowadzili Uriasza z Egiptu i przyprowadzili go do króla Joakima, a ten zabił go mieczem i wrzucił jego zwłoki do grobów pospólstwa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 24, 'Natomiast ręka Achikama, syna Szafana, była przy Jeremiaszu, aby nie został wydany w ręce ludu i nie został zabity.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 1, 'Na początku królowania Joakima, syna Jozjasza, króla Judy, doszło to słowo do Jeremiasza od Pana mówiące:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 2, 'Tak mówi do mnie Pan: Sporządź sobie więzy i jarzma i nałóż je na swoją szyję;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 3, 'Potem poślij je do króla Edomu, do króla Moabu, do króla Ammonitów, do króla Tyru i do króla Sydonu przez posłańców, którzy przyjdą do Jerozolimy, do Sedekiasza, króla Judy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 4, 'I rozkaż im, aby swym panom powiedzieli: Tak mówi Pan zastępów, Bóg Izraela. Tak powiecie swym panom:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 5, 'Ja uczyniłem ziemię, człowieka i zwierzęta, które są na powierzchni ziemi, swoją wielką mocą i wyciągniętym ramieniem, i daję temu, który w moich oczach ma upodobanie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 6, 'A teraz dałem te wszystkie ziemie do rąk Nabuchodonozora, króla Babilonu, mego sługi; oddałem mu nawet zwierzęta polne, aby mu służyły.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 7, 'Dlatego będą mu służyły te wszystkie narody, jego synowi i synowi jego syna, aż nadejdzie czas na jego ziemię. Wtedy ujarzmią go liczne narody i wielcy królowie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 8, 'A ten naród i to królestwo, które nie będzie służyło Nabuchodonozorowi, królowi Babilonu, i które nie podda swego karku pod jarzmo króla Babilonu, taki naród nawiedzę mieczem, głodem i zarazą, mówi Pan, aż wytracę je jego ręką.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 9, 'Dlatego nie słuchajcie swoich proroków, wróżbitów ani tych, co mają sny, ani swoich wróżbiarzy, ani swoich czarowników, którzy wam mówią: Nie będziecie służyć królowi Babilonu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 10, 'Oni bowiem prorokują wam kłamstwo, aby was oddalić od waszej ziemi, abym was wygnał i abyście poginęli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 11, 'A naród, który podda swój kark pod jarzmo króla Babilonu i będzie mu służył, ten pozostawię w jego ziemi, mówi Pan, aby ją uprawiał i mieszkał w niej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 12, 'A do Sedekiasza, króla Judy, powiedziałem zgodnie ze wszystkimi tymi słowami: Poddajcie swoje karki pod jarzmo króla Babilonu i służcie mu i jego ludowi, a będziecie żyć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 13, 'Czemu macie zginąć, ty i twój lud, od miecza, od głodu i od zarazy, jak mówił Pan o narodzie, który nie chce służyć królowi Babilonu?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 14, 'Nie słuchajcie więc słów tych proroków, którzy mówią do was: Nie będziecie służyć królowi Babilonu. Oni bowiem prorokują wam kłamstwo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 15, 'Nie posłałem ich, mówi Pan, a jednak oni prorokują kłamliwie w moje imię, abym was wypędził i abyście zginęli, wy i prorocy, którzy wam prorokują.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 16, 'Także do kapłanów i do całego ludu powiedziałem: Tak mówi Pan: Nie słuchajcie słów swoich proroków, którzy prorokują wam, mówiąc: Oto naczynia domu Pana zostaną już wkrótce przywrócone z Babilonu. Oni bowiem prorokują wam kłamstwo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 17, 'Nie słuchajcie ich, służcie królowi Babilonu, a będziecie żyć. Czemu to miasto miałoby stać się ruiną?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 18, 'A jeśli oni są prorokami i jeśli słowo Pana jest u nich, proszę, niech wstawią się u Pana zastępów, aby te naczynia, które pozostały w domu Pana, w domu króla Judy i w Jerozolimie, nie dostały się do Babilonu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 19, 'Tak bowiem mówi Pan zastępów o tych kolumnach, o morzu, o podstawkach i reszcie naczyń, które pozostały w tym mieście;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 20, 'Których nie zabrał Nabuchodonozor, król Babilonu, gdy uprowadził do niewoli Jechoniasza, syna Joakima, króla Judy, z Jerozolimy do Babilonu, oraz wszystkich dostojników z Judy i Jerozolimy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 21, 'Tak mówi Pan zastępów, Bóg Izraela, o tych naczyniach, które pozostały w domu Pana, w domu króla Judy i w Jerozolimie:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 22, 'Zostaną zawiezione do Babilonu i będą tam aż do dnia, w którym upomnę się o nie, mówi Pan. Wtedy sprowadzę je i przywrócę na to miejsce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 1, 'W tym samym roku, na początku królowania Sedekiasza, króla Judy, w piątym miesiącu czwartego roku, Chananiasz, syn Azzura, prorok, który był z Gibeonu, powiedział do mnie w domu Pana przed kapłanami i przed całym ludem:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 2, 'Tak mówi Pan zastępów, Bóg Izraela: Złamałem jarzmo króla Babilonu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 3, 'W ciągu dwóch lat sprowadzę z powrotem na to miejsce wszystkie naczynia domu Pana, które Nabuchodonozor, król Babilonu, zabrał z tego miejsca i zawiózł je do Babilonu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 4, 'Także Jechoniasza, syna Joakima, króla Judy, i wszystkich uprowadzonych z Judy, którzy dostali się do Babilonu, ja sprowadzę z powrotem na to miejsce, mówi Pan. Skruszę bowiem jarzmo króla Babilonu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 5, 'Wtedy prorok Jeremiasz powiedział do proroka Chananiasza wobec kapłanów i wobec całego ludu, który stał w domu Pana;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 6, 'Prorok Jeremiasz powiedział: Amen, niech Pan tak uczyni! Niech Pan utwierdzi twoje słowa, które prorokowałeś, że sprowadzi z Babilonu na to miejsce naczynia domu Pana i wszystkich, którzy zostali uprowadzeni do niewoli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 7, 'Posłuchaj jednak teraz tego słowa, które ja mówię do twoich uszu i do uszu całego tego ludu:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 8, 'Prorocy, którzy byli przede mną i przed tobą od dawna, prorokowali przeciwko wielu ziemiom i przeciwko wielkim królestwom o wojnie, o nieszczęściu i o zarazie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 9, 'Ten prorok, który prorokuje o pokoju, dopiero będzie uznany za proroka, którego Pan posłał, gdy spełni się jego słowo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 10, 'Wtedy prorok Chananiasz zdjął jarzmo z szyi proroka Jeremiasza i złamał je.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 11, 'I Chananiasz powiedział wobec całego ludu: Tak mówi Pan: Tak złamię jarzmo Nabuchodonozora, króla Babilonu, znad szyi wszystkich narodów w ciągu dwóch lat. I prorok Jeremiasz poszedł swoją drogą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 12, 'Po jakimś czasie od złamania jarzma na szyi proroka Jeremiasza przez proroka Chananiasza doszło do Jeremiasza słowo Pana mówiące:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 13, 'Idź i powiedz Chananiaszowi: Tak mówi Pan: Złamałeś jarzma drewniane, ale sporządzisz zamiast nich jarzma żelazne.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 14, 'Tak bowiem mówi Pan zastępów, Bóg Izraela: Włożę jarzmo żelazne na szyję wszystkich tych narodów, aby służyły Nabuchodonozorowi, królowi Babilonu; i będą mu służyły. Poddałem mu nawet zwierzęta polne.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 15, 'Potem prorok Jeremiasz powiedział do proroka Chananiasza: Posłuchaj teraz, Chananiaszu! Pan cię nie posłał, a sprawiasz, że ludzie ufają kłamstwu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 16, 'Dlatego tak mówi Pan: Oto usunę cię z powierzchni ziemi. Umrzesz w tym roku, bo głosiłeś bunt przeciwko Panu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 17, 'I umarł prorok Chananiasz w tym roku, w miesiącu siódmym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 1, 'A to są słowa listu, który prorok Jeremiasz posłał z Jerozolimy do pozostałych starszych, którzy byli na wygnaniu, i do kapłanów, do proroków i do całego ludu – których Nabuchodonozor uprowadził z Jerozolimy do Babilonu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 2, 'Było to po wyjściu z Jerozolimy króla Jechoniasza, królowej, dworzan, książąt Judy i Jerozolimy oraz cieśli i kowali.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 3, 'List w ysłał przez Elasę, syna Szafana, i Gemariasza, syna Chilkiasza, których Sedekiasz, król Judy, posłał do Babilonu do Nabuchodonozora, króla Babilonu; był on tej treści:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 4, 'Tak mówi Pan zastępów, Bóg Izraela, do wszystkich wygnańców, których uprowadziłem z Jerozolimy do Babilonu:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 5, 'Budujcie domy i mieszkajcie w nich; zakładajcie ogrody i spożywajcie ich owoce;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 6, 'Pojmujcie żony i płodźcie synów i córki; wybierajcie żony dla waszych synów i wydawajcie swoje córki za mąż, aby rodziły synów i córki. Rozmnażajcie się tam i niech was nie ubywa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 7, 'Zabiegajcie o pokój dla tego miasta, do którego was uprowadziłem, i módlcie się za nie do Pana, bo od jego pokoju zależy wasz pokój.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 8, 'Tak bowiem mówi Pan zastępów, Bóg Izraela: Niech was nie zwodzą wasi prorocy i wróżbici, którzy są wśród was, i nie zwracajcie uwagi na wasze sny, które się wam śnią.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 9, 'Bo oni prorokują wam kłamliwie w moje imię. Nie posłałem ich, mówi Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 10, 'Tak bowiem mówi Pan: Gdy wypełni się dla Babilonu siedemdziesiąt lat, nawiedzę was i spełnię wobec was swoje dobre słowo, by was sprowadzić z powrotem na to miejsce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 11, 'Gdyż ja znam myśli, które mam o was, mówi Pan: myśli o pokoju, a nie o utrapieniu, aby zapewnić wam koniec, jakiego oczekujecie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 12, 'Wtedy będziecie mnie wzywać, pójdziecie i będziecie modlić się do mnie, a ja was wysłucham;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 13, 'Będziecie mnie szukać i znajdziecie mnie, gdy będziecie szukać całym swym sercem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 14, 'I dam wam się znaleźć, mówi Pan, i odwrócę waszą niewolę, i zgromadzę was ze wszystkich narodów i ze wszystkich miejsc, do których was wygnałem, mówi Pan. I przyprowadzę was na to miejsce, z którego was uprowadziłem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 15, 'A ponieważ mówicie: Pan wzbudził nam proroków w Babilonie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 16, 'Tak mówi Pan o królu, który zasiada na tronie Dawida, i o całym ludzie, który mieszka w tym mieście, o waszych braciach, którzy nie poszli z wami do niewoli;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 17, 'Tak mówi Pan zastępów: Oto poślę na nich miecz, głód i zarazę i uczynię z nimi jak ze złymi figami, których nie można jeść, bo są tak złe.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 18, 'Będę ich bowiem prześladować mieczem, głodem i zarazą i sprawię, że zostaną wysiedleni do wszystkich królestw ziemi, uczynię ich przedmiotem przekleństwa, zdumienia, poświstania i hańby wśród wszystkich narodów, do których ich wypędziłem;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 19, 'Za to, że nie słuchali moich słów, mówi Pan, które posłałem do nich przez swoje sługi, proroków, z wczesnym wstawaniem i przesłaniem. Ale nie słuchaliście, mówi Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 20, 'Dlatego słuchajcie słowa Pana, wy, wszyscy wygnańcy, których wysłałem z Jerozolimy do Babilonu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 21, 'Tak mówi Pan zastępów, Bóg Izraela, o Achabie, synu Kolajasza, i o Sedekiaszu, synu Maasejasza, którzy prorokują wam kłamstwo w moje imię: Oto wydam ich w ręce Nabuchodonozora, króla Babilonu, a ten zabije ich na waszych oczach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 22, 'Od nich będzie wzięte przekleństwo przez wszystkich wygnańców z Judy, którzy są w Babilonie, wyrażone w słowach: Niech Pan ci uczyni jak z Sedekiaszem i jak z Achabem, których król Babilonu usmażył w ogniu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 23, 'Za to, że popełniali nikczemność w Izraelu, cudzołożyli z żonami swoich bliźnich i mówili słowa kłamliwe w moje imię, czego im nie nakazałem. Ja o tym wiem i jestem tego świadkiem, mówi Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 24, 'A do Szemajasza Nechalamity powiesz:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 25, 'Tak mówi Pan zastępów, Bóg Izraela: Ponieważ we własnym imieniu posłałeś listy do całego ludu, który jest w Jerozolimie, i do Sofoniasza, syna Maasejasza, kapłana, i do wszystkich kapłanów, tej treści:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 26, 'Pan ustanowił cię kapłanem w miejsce kapłana Jehojady i abyście mieli nadzór w domu Pana nad każdym szaleńcem udającym proroka, abyś osadzał takiego w więzieniu i zakuwał w dyby.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 27, 'Dlaczego więc nie skarciłeś Jeremiasza z Anatot, który wam prorokuje?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 28, 'Posłał bowiem do nas do Babilonu słowo: Będzie to trwało długo. Budujcie domy i mieszkajcie w nich, zakładajcie ogrody i spożywajcie ich owoce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 29, 'A kapłan Sofoniasz odczytał ten list do uszu proroka Jeremiasza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 30, 'I doszło słowo Pana do Jeremiasza mówiące:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 31, 'Poślij do wszystkich uprowadzonych do niewoli takie słowa: Tak mówi Pan o Szemajaszu Nechalamicie: Ponieważ Szemajasz prorokował wam, chociaż ja go nie posłałem, a wywołuje w was ufność w kłamstwo;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 32, 'Dlatego tak mówi Pan: Oto nawiedzę Szemajasza Nechalamitę i jego potomstwo. Nie będzie miał nikogo, kto by mieszkał pośród tego ludu, ani nie ujrzy tego dobra, które uczynię swemu ludowi, mówi Pan, bo głosił bunt przeciwko Panu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 1, 'Słowo, które doszło do Jeremiasza od Pana, mówiące:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 2, 'Tak mówi Pan, Bóg Izraela: Napisz sobie w księdze wszystkie słowa, które powiedziałem do ciebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 3, 'Oto bowiem nadchodzą dni, mówi Pan, gdy odwrócę niewolę swego ludu Izraela i Judy, mówi Pan, i sprowadzę ich do ziemi, którą dałem ich ojcom, i posiądą ją.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 4, 'A to są słowa, które Pan mówił o Izraelu i o Judzie:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 5, 'Tak mówi Pan: Słyszeliśmy głos strachu i lęku, a nie pokoju.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 6, 'Pytajcie teraz i zobaczcie: Czy mężczyzna może rodzić? Czemu więc widzę, że każdy mężczyzna trzyma ręce na biodrach – jak u rodzącej – i że ich twarze stały się blade?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 7, 'Biada! Bo wielki jest ten dzień, że nie będzie mu równego. To jest czas utrapienia Jakuba, ale będzie z niego wybawiony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 8, 'W tym dniu bowiem, mówi Pan zastępów, złamię jego jarzmo znad twojej szyi i rozerwę twoje więzy, i cudzoziemcy już nie będą go ujarzmiać;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 9, 'Ale będą służyć Panu, swemu Bogu, i Dawidowi, swemu królowi, którego im wzbudzę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 10, 'Dlatego nie bój się, mój sługo, Jakubie, mówi Pan, nie lękaj się, Izraelu! Oto bowiem wybawię cię z daleka, twoje potomstwo z ziemi jego niewoli. Powróci Jakub, aby zaznać odpoczynku i spokoju i nikt nie będzie go straszył.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 11, 'Ja bowiem jestem z tobą, mówi Pan, aby cię wybawić. A chociaż położę kres wszystkim narodom, wśród których cię rozproszyłem, tobie jednak nie położę kresu, ale ukarzę cię sprawiedliwie, nie zostawię cię całkiem bez kary.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 12, 'Tak mówi Pan: Twoje zranienie jest nieuleczalne, bardzo bolesna twoja rana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 13, 'Nie ma nikogo, kto by bronił twojej sprawy, abyś była uleczona. Nie masz lekarstwa na gojenie ran.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 14, 'Wszyscy twoi kochankowie zapomnieli o tobie, nie szukają cię, gdyż zraniłem cię ciosem wroga i okrutnym karaniem z powodu mnóstwa twoich nieprawości i twoich niezliczonych grzechów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 15, 'Czemu wołasz z powodu swej rany i ciężkiej boleści? Za ogrom twoich nieprawości i twoje niezliczone grzechy uczyniłem ci to.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 16, 'Wszyscy jednak, co cię pożerają, zostaną pożarci; wszyscy, którzy cię uciskają, pójdą w niewolę; ci, którzy cię ograbiają, zostaną ograbieni; a wszystkich, którzy cię łupią, wydam na łup.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 17, 'Przywrócę ci bowiem zdrowie i uleczę cię z twoich ran, mówi Pan, gdyż nazwali cię Odrzuconą, mówiąc: To jest Syjon, o który nikt się nie troszczy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 18, 'Tak mówi Pan: Oto odwrócę niewolę namiotów Jakuba i zlituję się nad jego mieszkaniem, i miasto zostanie odbudowane na swoim wzgórzu, a pałac wystawiony według swego porządku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 19, 'I rozlegnie się stamtąd dziękczynienie i głos weselących się. Rozmnożę ich i nie będzie ich ubywało, uwielbię ich i nie będą poniżeni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 20, 'Jego synowie będą tak jak dawniej i jego zgromadzenie będzie utwierdzone przede mną, ale ukarzę wszystkich, którzy ich trapią.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 21, 'I z niego powstanie jego władca, panujący nad nim spośród niego wyjdzie; każę mu się zbliżyć, a przystąpi do mnie. Kim bowiem jest ten, co odważyłby się w sercu zbliżyć do mnie? – mówi Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 22, 'I będziecie moim ludem, a ja będę waszym Bogiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 23, 'Oto wicher Pana zrywa się w zapalczywości, trwający wicher spadnie nad głowy bezbożnych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 24, 'Zapalczywość gniewu Pana nie odwróci się, aż on to uczyni i wykona zamysły swego serca. W dniach ostatecznych to zrozumiecie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 1, 'W tym czasie, mówi Pan, będę Bogiem wszystkich rodów Izraela, a one będą moim ludem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 2, 'Tak mówi Pan: Lud, który ocalał od miecza, znalazł łaskę na pustyni, gdy kroczyłem przed nim, aby dać odpoczynek Izraelowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 3, 'Powiedz: Dawno Pan mi się ukazał, mówiąc: Owszem, umiłowałem cię wieczną miłością, dlatego przyciągam cię swoim miłosierdziem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 4, 'Odbuduję cię znowu i będziesz odbudowana, dziewico Izraela! Znowu przyozdobisz się w swe bębenki i wystąpisz wśród tańców pełnych wesela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 5, 'Znów będziesz sadziła winnice na górach Samarii; siewcy będą sadzić i spożywać z tego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 6, 'Nastanie bowiem dzień, kiedy stróże będą wołać na górze Efraim: Wstańcie, wejdźmy na Syjon do Pana, swego Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 7, 'Tak bowiem mówi Pan: Śpiewajcie radośnie dla Jakuba i wykrzykujcie przed przodującym wśród narodów. Głoście, wychwalajcie i mówcie: Panie, wybaw resztkę twego ludu Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 8, 'Oto przyprowadzę ich z ziemi północnej i zgromadzę ich z krańców ziemi; wśród nich będą ślepi i chromi, brzemienne i rodzące. Powrócą tu wielką gromadą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 9, 'Przyjdą z płaczem i przyprowadzę ich wśród modlitw, a poprowadzę ich nad strumienie wód prostą drogą, na której się nie potkną. Jestem bowiem ojcem dla Izraela, a Efraim jest moim pierworodnym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 10, 'Słuchajcie słowa Pana, o narody, głoście je na dalekich wyspach i mówcie: Ten, który rozproszył Izraela, zgromadzi go i będzie go strzec jak pasterz swoich trzód.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 11, 'Pan bowiem wykupił Jakuba i wybawił go z ręki silniejszego od niego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 12, 'Przyjdą więc i będą śpiewać na wyżynie Syjonu, i zbiegną się do dobroci Pana za zboże, za wino i za oliwę, za jagnięta i za cielęta, a ich dusza będzie jak nawodniony ogród i już nie będą się smucić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 13, 'Wtedy dziewica będzie radować się wśród pląsów, także młodzieńcy i starcy razem. Zamienię bowiem ich żałobę w radość, pocieszę ich i rozraduję po ich smutku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 14, 'I nasycę duszę ich kapłanów tłuszczem, a mój lud nasyci się moją dobrocią, mówi Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 15, 'Tak mówi Pan: W Rama słychać głos, lament i gorzki płacz: Rachel opłakuje swoich synów, nie daje się pocieszyć po stracie swoich synów, bo ich już nie ma.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 16, 'Tak mówi Pan: Powstrzymaj swój głos od płaczu, a swe oczy od łez, bo otrzymasz zapłatę za swoją pracę, mówi Pan. Powrócą z ziemi wroga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 17, 'Jest nadzieja na twój kres – mówi Pan – twoi synowie powrócą do swojej krainy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 18, 'Zaprawdę, usłyszałem jak Efraim się użala: Karciłeś mnie i poniosłem karę jak nieokiełznane cielę. Nawróć mnie, a będę nawrócony, bo ty jesteś Panem, moim Bogiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 19, 'Bo po moim nawróceniu pokutowałem; gdy poznałem samego siebie, uderzyłem się w biodro; wstydzę się i rumienię, gdyż noszę hańbę swej młodości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 20, 'Czyż Efraim nie jest moim drogim synem? Czyż nie jest rozkoszny? Ilekroć bowiem mówię przeciwko niemu, nieustannie go wspominam. Dlatego wzrusza się moje wnętrze z jego powodu; na pewno zlituję się nad nim, mówi Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 21, 'Postaw sobie drogowskazy, połóż sobie stosy kamieni. Zwróć swoje serce na gościniec, na drogę, którą chodziłaś. Powróć, dziewico Izraela! Powróć do tych swoich miast.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 22, 'Jak długo będziesz się błąkać, córko uparta? Pan bowiem stworzył nową rzecz na ziemi: kobieta ogarnie mężczyznę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 23, 'Tak mówi Pan zastępów, Bóg Izraela: Jeszcze będą mówić to słowo w ziemi Judy i w jej miastach, gdy odwrócę ich niewolę: Niech Pan cię błogosławi, mieszkanie sprawiedliwości, góro świętości!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 24, 'Zamieszkają bowiem w ziemi Judy i we wszystkich jego miastach razem rolnicy i ci, którzy chodzą za stadem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 25, 'Napoiłem spragnioną duszę i nasyciłem wszelką smutną duszę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 26, 'Wtedy się obudziłem i spojrzałem, a mój sen był dla mnie przyjemny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 27, 'Oto nadchodzą dni, mówi Pan, w których zasieję dom Izraela i dom Judy nasieniem ludzi i nasieniem zwierząt.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 28, 'A jak się starałem ich wykorzeniać, burzyć, obalać, niszczyć i trapić, tak będę nad nimi czuwał, by ich budować i sadzić, mówi Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 29, 'W tych dniach już nie będą mówić: Ojcowie jedli cierpkie winogrona, a synom ścierpły zęby;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 30, 'Lecz każdy umrze za swoją nieprawość. Każdemu człowiekowi, który zje cierpkie winogrona, ścierpną zęby.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 31, 'Oto nadchodzą dni, mówi Pan, kiedy zawrę z domem Izraela i z domem Judy nowe przymierze;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 32, 'Nie takie przymierze, jakie zawarłem z ich ojcami w dniu, kiedy ująłem ich za rękę, aby ich wyprowadzić z ziemi Egiptu. Oni bowiem złamali moje przymierze, chociaż ja byłem ich mężem, mówi Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 33, 'Ale takie będzie przymierze, które zawrę z domem Izraela po tych dniach, mówi Pan: Włożę moje prawo w ich wnętrzu i wypisze je na ich sercach. I będę ich Bogiem, a oni będą moim ludem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 34, 'I nikt nie będzie już uczył swego bliźniego ani nikt swego brata, mówiąc: Poznaj Pana, bo wszyscy będą mnie znali, od najmniejszego aż do największego z nich, mówi Pan. Przebaczę bowiem ich nieprawość, a ich grzechów nigdy więcej nie wspomnę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 35, 'Tak mówi Pan, który daje słońce na światłość w dzień, prawa księżyca i gwiazd na światłość w nocy; który rozdziela morze tak, że huczą jego fale; Pan zastępów – to jego imię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 36, 'Gdyby te prawa ustały przede mną, mówi Pan, wtedy i potomstwo Izraela przestanie być narodem przede mną na wieki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 37, 'Tak mówi Pan: Jeśli można zmierzyć niebiosa w górze i zbadać fundamenty ziemi w dole, wtedy i ja odrzucę całe potomstwo Izraela za to wszystko, co uczynili, mówi Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 38, 'Oto nadchodzą dni, mówi Pan, w których to miasto zostanie odbudowane Panu od Wieży Chananeela aż do Bramy Narożnej;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 39, 'I będzie się ciągnął dalej sznur mierniczy na wprost ku wzgórzu Gareb, a potem zwróci się ku Goa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 40, 'I cała dolina trupów i popiołu, wszystkie pola aż do potoku Cedron i narożnika Bramy Końskiej ku wschodowi będą poświęcone Panu. Nie zostaną już wykorzenione ani zburzone na wieki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 1, 'Słowo, które doszło do Jeremiasza od Pana w dziesiątym roku Sedekiasza, króla Judy, a był to osiemnasty rok Nabuchodonozora.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 2, 'W tym czasie wojsko króla Babilonu obległo Jerozolimę, a prorok Jeremiasz był zamknięty na dziedzińcu więzienia, które znajdowało się w domu króla Judy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 3, 'Uwięził go bowiem Sedekiasz, król Judy, mówiąc: Czemu prorokujesz tymi słowami: Tak mówi Pan: Oto wydam to miasto w ręce króla Babilonu, a on je zdobędzie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 4, 'Sedekiasz zaś, król Judy, nie ujdzie z rąk Chaldejczyków, ale na pewno będzie wydany w ręce króla Babilonu i będzie z nim rozmawiał z ust do ust, i zobaczy go oko w oko;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 5, 'I uprowadzi Sedekiasza do Babilonu, i będzie tam, aż go nawiedzę, mówi Pan. A jeśli będziecie walczyć z Chaldejczykami, nie poszczęści się wam.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 6, 'Wtedy Jeremiasz odpowiedział: Doszło do mnie słowo Pana mówiące:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 7, 'Oto Chanameel, syn Szalluma, twego stryja, przyjdzie do ciebie i powie: Kup sobie moje pole, które jest w Anatot, bo do ciebie należy prawo wykupu, aby je nabyć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 8, 'I Chanameel, syn mego stryja, przyszedł do mnie na dziedziniec więzienia zgodnie ze słowem Pana, i powiedział do mnie: Proszę, kup moje pole, które jest w Anatot, w ziemi Beniamina, bo do ciebie należy prawo dziedzictwa i wykupu; kup je sobie. Wtedy zrozumiałem, że było to słowo Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 9, 'I kupiłem od Chanameela, syna mego stryja, pole, które było w Anatot, i odważyłem mu pieniądze – siedemnaście syklów srebra.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 10, 'Spisałem akt, zapieczętowałem go, ujawniłem wobec świadków i odważyłem pieniądze na wadze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 11, 'Potem wziąłem akt kupna, zarówno ten zapieczętowany zgodnie z prawem i przepisami, jak i ten otwarty;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 12, 'I oddałem ten akt kupna Baruchowi, synowi Neriasza, syna Machsejasza, na oczach Chanameela, syna mego stryja, i na oczach świadków, którzy podpisali ten akt kupna, i na oczach wszystkich Żydów, którzy siedzieli na dziedzińcu więzienia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 13, 'I nakazałem Baruchowi w ich obecności, mówiąc:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 14, 'Tak mówi Pan zastępów, Bóg Izraela: Weź te akty, zarówno zapieczętowany akt kupna, jak i ten otwarty, i włóż je do naczynia glinianego, aby przetrwały wiele lat.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 15, 'Tak bowiem mówi Pan zastępów, Bóg Izraela: Znowu będzie się kupowało domy, pola i winnice w tej ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 16, 'A po przekazaniu aktu kupna Baruchowi, synowi Neriasza, modliłem się do Pana tymi słowami:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 17, 'Ach, Panie Boże! Oto uczyniłeś niebo i ziemię swoją wielką mocą i wyciągniętym ramieniem i nie ma dla ciebie rzeczy zbyt trudniej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 18, 'Okazujesz miłosierdzie tysiącom i odpłacasz nieprawość ojców w zanadrze ich synów po nich. Bóg wielki i potężny, Pan zastępów – to twoje imię;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 19, 'Wielki w radzie i potężny w dziele, ponieważ twoje oczy są otwarte na wszystkie drogi synów ludzkich, by oddać każdemu według jego dróg i według owoców jego uczynków.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 20, 'Czyniłeś znaki i cuda w ziemi Egiptu aż do dziś, zarówno w Izraelu, jak i wśród innych ludzi, i uczyniłeś sobie imię, jak to jest dzisiaj.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 21, 'Wyprowadziłeś swój lud Izraela z ziemi Egiptu wśród znaków i cudów potężną ręką i wyciągniętym ramieniem, i wśród wielkiego strachu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 22, 'I dałeś im tę ziemię, którą przysiągłeś dać ich ojcom, ziemię opływającą mlekiem i miodem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 23, 'A gdy weszli i posiedli ją, nie usłuchali twojego głosu i nie postępowali według twojego prawa; nie wypełnili nic z tego wszystkiego, co im rozkazałeś wypełnić. Dlatego sprawiłeś, że spotkało ich to całe nieszczęście.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 24, 'Oto wały usypano przeciwko miastu, aby je zdobyć, miasto jest wydane w ręce Chaldejczyków, którzy walczą przeciw niemu, przez miecz, głód i zarazę. Stało się, jak powiedziałeś, sam to widzisz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 25, 'Ty jednak, Panie Boże, powiedziałeś mi: Kup sobie to pole za pieniądze i ujawnij to wobec świadków, choć miasto jest już wydane w ręce Chaldejczyków.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 26, 'I doszło słowo Pana do Jeremiasza mówiące:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 27, 'Oto jestem Panem, Bogiem wszelkiego ciała. Czy jakakolwiek rzecz jest dla mnie zbyt trudna?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 28, 'Dlatego tak mówi Pan: Oto wydaję to miasto w ręce Chaldejczyków i w ręce Nabuchodonozora, króla Babilonu, i on je zdobędzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 29, 'A Chaldejczycy, którzy walczą przeciwko temu miastu, wejdą i podłożą ogień pod to miasto, i spalą je wraz z domami, na których dachach palili kadzidło Baalowi i wylewali ofiary z płynów innym bogom, aby mnie pobudzić do gniewu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 30, 'Synowie Izraela bowiem i synowie Judy od swojej młodości czynią tylko to, co jest złe w moich oczach. Tak, synowie Izraela tylko drażnili mnie dziełami swoich rąk, mówi Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 31, 'To miasto bowiem jest powodem mojej zapalczywości i gniewu od dnia, kiedy je zbudowali, aż do dzisiaj, tak że usunę je sprzed mego oblicza;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 32, 'Z powodu wszelkiego zła synów Izraela i synów Judy, które popełniali, by pobudzić mnie do gniewu, oni, ich królowie i książęta, ich kapłani i prorocy, Judejczycy i mieszkańcy Jerozolimy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 33, 'Obrócili się do mnie tyłem, a nie twarzą, i chociaż ich nauczałem z wczesnym wstawaniem i nauczaniem, oni jednak nie słuchali, aby przyjąć pouczenie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 34, 'Umieścili swoje obrzydliwości w domu, nad którym jest nazwane moje imię, by go zbezcześcić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 35, 'Zbudowali wyżyny Baala w dolinie syna Hinnom, by przeprowadzić swoich synów i swoje córki przez ogień ku czci Molocha, czego im nie nakazałem, nie przyszło mi nawet na myśl, by czynić tę obrzydliwość i Judę przywodzić do grzechu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 36, 'Dlatego teraz tak mówi Pan, Bóg Izraela, o tym mieście, o którym wy mówicie: Zostanie wydane w ręce króla Babilonu przez miecz, głód i zarazę:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 37, 'Oto zgromadzę ich ze wszystkich ziem, do których ich wygnałem w swoim gniewie, w swoim oburzeniu i w wielkiej zapalczywości i przyprowadzę ich z powrotem na to miejsce, i sprawię, że będą mieszkać bezpiecznie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 38, 'I będą moim ludem, a ja będę ich Bogiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 39, 'I dam im jedno serce i jedną drogę, aby bali się mnie przez wszystkie dni, dla dobra ich samych i ich dzieci po nich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 40, 'I zawrę z nimi wieczne przymierze, że się od nich nie odwrócę i nie przestanę im dobrze czynić, lecz włożę w ich serca moją bojaźń, aby nie odstępowali ode mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 41, 'I będę się radował z nich, aby wyświadczyć im dobro, i osadzę ich z pewnością w tej ziemi z całego swego serca i całą swoją duszą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 42, 'Tak bowiem mówi Pan: Jak sprowadziłem na ten lud całe to nieszczęście, tak sprowadzę na niego całe dobro, które mu obiecałem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 43, 'Wtedy będzie się kupować pola w tej ziemi, o której mówicie: Jest tak spustoszona, że nie ma w niej ani człowieka, ani zwierzęcia, jest wydana w ręce Chaldejczyków.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 44, 'Będą kupować pola za pieniądze i spisywać akty, zapieczętowywać je i ujawniać wobec świadków w ziemi Beniamina, w okolicach Jerozolimy, w miastach Judy, w miastach górskich, w miastach dolin i w miastach na południu. Odwrócę bowiem ich niewolę, mówi Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 1, 'I słowo Pana doszło do Jeremiasza po raz drugi, gdy ten był jeszcze zamknięty na dziedzińcu więzienia, mówiące:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 2, 'Tak mówi Pan, Sprawca tego: Pan, który to ukształtował i utwierdził; Pan to jego imię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 3, 'Wołaj do mnie, a odpowiem ci i oznajmię ci rzeczy wielkie i ukryte, których nie znasz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 4, 'Tak bowiem mówi Pan, Bóg Izraela, o domach tego miasta i o domach królów Judy, które są zburzone dzięki taranom i mieczom:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 5, 'Idą, aby walczyć z Chaldejczykami, ale napełnią te domy trupami ludzi, których pobiłem w swoim gniewie i w swojej zapalczywości i zakryłem swoje oblicze przed tym miastem z powodu całej ich niegodziwości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 6, 'Oto dam mu zdrowie i uleczenie, i uzdrowię ich oraz objawię im obfitość pokoju i prawdy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 7, 'Odwrócę bowiem niewolę Judy i niewolę Izraela i odbuduję ich jak przedtem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 8, 'Oczyszczę ich z wszelkiej nieprawości, którą zgrzeszyli przeciwko mnie, i przebaczę im wszystkie winy, jakimi zgrzeszyli przeciwko mnie i jakimi wykroczyli przeciwko mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 9, 'A będzie dla mnie przyczyną radości, chwałą i ozdobą wśród wszystkich narodów ziemi, które usłyszą o wszelkim dobru, jakie im wyświadczam. Zlękną się i zadrżą z powodu całej tej dobroci i pomyślności, które im przygotowuję.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 10, 'Tak mówi Pan: Na tym miejscu, o którym wy mówicie: Zostanie spustoszone, pozbawione człowieka i zwierzęcia, w miastach Judy i na ulicach Jerozolimy, spustoszonych, bezludnych i pozbawionych mieszkańców i zwierząt, znów będzie słychać;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 11, 'Głos radości i głos wesela, głos oblubieńca i głos oblubienicy, głos tych, którzy mówią: Wysławiajcie Pana zastępów, bo Pan jest dobry, bo jego miłosierdzie trwa na wieki; to głos przynoszących ofiarę chwały do domu Pana. Odwrócę bowiem niewolę tej ziemi, jak na początku, mówi Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 12, 'Tak mówi Pan zastępów: Znowu na tym spustoszonym miejscu bez ludzi i zwierząt i we wszystkich jego miastach będzie schronisko dla pasterzy, dających trzodom odpoczynek.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 13, 'W miastach górskich, w miastach na równinach i w miastach na południe, w ziemi Beniamina i w okolicach Jerozolimy oraz w miastach Judy znowu będą przechodzić trzody pod ręką tego, który je liczy, mówi Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 14, 'Oto nadchodzą dni, mówi Pan, kiedy utwierdzę to dobre słowo, które zapowiedziałem domowi Izraela i domowi Judy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 15, 'W tych dniach i w tym czasie sprawię, że wyrośnie Dawidowi Latorośl sprawiedliwa. Będzie on sprawował sąd i wymierzał sprawiedliwość na ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 16, 'W tych dniach Juda będzie zbawiona, a Jerozolima będzie mieszkać bezpiecznie. A takie jest imię, którym będą ją nazywać: Pan naszą sprawiedliwością.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 17, 'Tak bowiem mówi Pan: Nie zabraknie Dawidowi potomka zasiadającego na tronie domu Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 18, 'Kapłanom Lewitom też nie zabraknie przede mną człowieka, by składał całopalenia, spalał ofiary z pokarmów i składał ofiary przez wszystkie dni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 19, 'Następnie do Jeremiasza doszło słowo Pana mówiące:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 20, 'Tak mówi Pan: Jeśli będziecie mogli złamać moje przymierze z dniem i moje przymierze z nocą, aby nie było dnia ani nocy w swoim czasie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 21, 'Wtedy też będzie złamane moje przymierze z Dawidem, moim sługą, aby nie miał syna, który by królował na jego tronie, i z Lewitami kapłanami, moimi sługami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 22, 'Jak niezliczone są zastępy niebios i niezmierzony piasek morski tak rozmnożę potomstwo Dawida, mojego sługi, i Lewitów, którzy mi służą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 23, 'Ponownie do Jeremiasza doszło słowo Pana mówiące:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 24, 'Czyż nie widzisz, co ten lud mówi: Dwa rody, które Pan wybrał, już odrzucił! Tak więc gardzą moim ludem, jakby już nie był narodem w ich oczach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 25, 'Tak mówi Pan: Jeśli nie istnieje moje przymierze z dniem i nocą i jeśli nie ustaliłem praw dla niebios i ziemi;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 26, 'Wtedy potomstwo Jakuba i Dawida, mego sługi, odrzucę, aby nie brać z jego rodu tych, którzy mieliby panować nad potomstwem Abrahama, Izaaka i Jakuba. Odwrócę bowiem ich niewolę i zlituję się nad nimi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 1, 'Słowo, które doszło do Jeremiasza od Pana, gdy Nabuchodonozor, król Babilonu, całe jego wojsko, wszystkie królestwa ziemi podległe jego władzy oraz wszystkie ludy walczyli przeciwko Jerozolimie i przeciwko wszystkim jej miastom, mówiące:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 2, 'Tak mówi Pan, Bóg Izraela: Idź i przemów do Sedekiasza, króla Judy, i powiedz mu: Tak mówi Pan: Oto wydam to miasto w ręce króla Babilonu, a on spali je ogniem;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 3, 'Ty też nie ujdziesz jego ręki, lecz na pewno zostaniesz pojmany i wydany w jego ręce; twoje oczy zobaczą oczy króla Babilonu i on będzie z tobą rozmawiał z ust do ust, a ty pójdziesz do Babilonu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 4, 'Posłuchaj jednak słowa Pana, Sedekiaszu, królu Judy: Tak mówi Pan o tobie: Nie umrzesz od miecza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 5, 'Umrzesz w pokoju i podobnie jak palono wonności dla twoich ojców, dawniejszych królów, którzy byli przed tobą, tak będą palić dla ciebie; i będą cię opłakiwać, mówiąc: Ach, panie! Ja bowiem wyrzekłem to słowo, mówi Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 6, 'Wtedy prorok Jeremiasz powiedział wszystkie te słowa do Sedekiasza, króla Judy, w Jerozolimie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 7, 'Gdy wojsko króla Babilonu walczyło przeciwko Jerozolimie i przeciwko wszystkim pozostałym miastom Judy: przeciwko Lakisz i przeciw Azece. Tylko bowiem te warowne miasta pozostały z miast Judy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 8, 'Słowo, które doszło do Jeremiasza od Pana, gdy król Sedekiasz zawarł przymierze z całym ludem, który był w Jerozolimie, dla ogłoszenia mu wolności;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 9, 'Że każdy puści wolno swego niewolnika Hebrajczyka i niewolnicę Hebrajkę, aby nikt nie trzymał w niewoli Żyda, swego brata.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 10, 'Wszyscy książęta i cały lud, którzy zawarli przymierze o tym, aby każdy wypuścił wolno swego niewolnika i swą niewolnicę, by ich już nie trzymano w niewoli, usłuchali i puścili ich wolno.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 11, 'Lecz potem rozmyślili się i z powrotem ściągnęli niewolników i niewolnice, których puścili wolno, i zmusili ich do służby jako niewolników i niewolnice.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 12, 'Dlatego od Pana doszło do Jeremiasza słowo Pana mówiące:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 13, 'Tak mówi Pan, Bóg Izraela: Ja zawarłem przymierze z waszymi ojcami w dniu, w którym wyprowadziłem ich z ziemi Egiptu, z domu niewoli, mówiąc:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 14, 'Po upływie siedmiu lat niech każdy puści wolno swego brata Hebrajczyka, który się tobie zaprzedał; będzie ci służył przez sześć lat, po czym puścisz go wolno od siebie. Ale wasi ojcowie nie słuchali mnie ani nie nakłonili swego ucha.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 15, 'Wy zaś nawróciliście się dziś i uczyniliście to, co jest dobre w moich oczach, ogłaszając wolność – każdy swemu bliźniemu, i zawarliście przymierze przede mną w domu nazywanym moim imieniem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 16, 'Lecz cofnęliście się i splugawiliście moje imię, bo każdy z powrotem ściągnął swego niewolnika i swą niewolnicę, których poprzednio puścił wolno według życzenia, i zmusił ich do służby jako niewolników i niewolnice.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 17, 'Dlatego tak mówi Pan: Nie posłuchaliście mnie, aby każdy ogłosił wolność swemu bratu i bliźniemu. Oto ogłaszam wam, mówi Pan, wolność pod miecz, na zarazę i głód, i wydam was na wysiedlenie do wszystkich królestw ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 18, 'Wydam tych ludzi, którzy przekroczyli moje przymierze i nie dotrzymali słów tego przymierza, jakie wypowiedzieli przede mną, gdy rozcięli cielca na dwoje i przeszli pomiędzy jego częściami;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 19, 'To jest książąt Judy i książąt Jerozolimy, dworzan i kapłanów oraz cały lud tej ziemi, tych, którzy przeszli pomiędzy częściami tego cielca;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 20, 'Właśnie ich wydam w ręce ich wrogów i w ręce czyhających na ich życie, i ich trupy będą żerem dla ptactwa nieba i zwierząt ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 21, 'Również Sedekiasza, króla Judy, i jego książąt wydam w ręce ich wrogów i w ręce czyhających na ich życie, w ręce wojska króla Babilonu, które odstąpiło od was.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 22, 'Oto wydam rozkaz, mówi Pan, i sprowadzę ich z powrotem do tego miasta, i będą walczyć przeciwko niemu, zdobędą je i spalą ogniem. Miasta Judy zamienię w pustkowie, bez mieszkańców.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 1, 'Słowo, które doszło do Jeremiasza od Pana za dni Joakima, syna Jozjasza, króla Judy, mówiące:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 2, 'Idź do domu Rekabitów, porozmawiaj z nimi i wprowadź ich do domu Pana, do jednej z komnat, i daj im wino do picia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 3, 'Zabrałem więc ze sobą Jaazaniasza, syna Jeremiasza, syna Chabasiniasza, jego braci, wszystkich jego synów i cały dom Rekabitów;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 4, 'I wprowadziłem ich do domu Pana, do komnaty synów Chanana, syna Jigdaliasza, męża Bożego, która była obok komnaty książęcej nad komnatą Maasejasza, syna Szalluma, stróża progu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 5, 'Potem postawiłem przed synami domu Rekabitów czasze pełne wina i kubki i powiedziałem do nich: Pijcie wino.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 6, 'Lecz oni odpowiedzieli: Nie pijemy wina, bo Jonadab, syn Rekaba, nasz ojciec, nakazał nam, mówiąc: Nie pijcie wina, ani wy, ani wasi synowie, aż na wieki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 7, 'Nie budujcie też domów ani nie obsiewajcie nasieniem, nie sadźcie winnic ani nie posiadajcie żadnej, ale mieszkajcie w namiotach przez wszystkie wasze dni, abyście żyli przez wiele dni na powierzchni ziemi, w której jesteście przybyszami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 8, 'Byliśmy więc posłuszni głosowi Jonadaba, syna Rekaba, naszego ojca, we wszystkim, co nam nakazał: nie piliśmy wina przez wszystkie nasze dni, my, nasze żony, nasi synowie i nasze córki;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 9, 'I nie budowaliśmy sobie domów do zamieszkania ani nie mieliśmy winnicy ani pola, ani siewu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 10, 'Ale mieszkamy w namiotach; byliśmy posłuszni i postępujemy zgodnie ze wszystkim, co nam nakazał Jonadab, nasz ojciec.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 11, 'A gdy Nabuchodonozor, król Babilonu, nadciągnął do naszej ziemi, powiedzieliśmy: Chodźcie, wejdźmy do Jerozolimy przed wojskiem Chaldejczyków i przed wojskiem Syryjczyków. Zostaliśmy więc w Jerozolimie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 12, 'Wówczas doszło słowo Pana do Jeremiasza mówiące:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 13, 'Tak mówi Pan zastępów, Bóg Izraela: Idź i powiedz Judejczykom i mieszkańcom Jerozolimy: Czy nie przyjmiecie pouczenia, by słuchać moich słów? – mówi Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 14, 'Wypełniane są słowa Jonadaba, syna Rekaba, które przykazał swoim synom, aby nie pili wina. Nie piją go bowiem aż do dziś, bo są posłuszni przykazaniu swego ojca. Ja jednak mówiłem do was, z wczesnym wstawaniem i mówieniem, lecz nie słuchaliście mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 15, 'Posłałem też do was wszystkie swe sługi, proroków, z wczesnym wstawaniem i przesłaniem, mówiąc: Niech każdy zawróci już ze swej złej drogi i poprawi swoje uczynki, nie chodźcie za innymi bogami ani im nie służcie, a będziecie mieszkać w tej ziemi, którą dałem wam i waszym ojcom. Ale nie nakłoniliście swego ucha ani mnie nie usłuchaliście.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 16, 'I chociaż synowie Jonadaba, syna Rekaba, wypełnili nakaz swego ojca, który im przekazał, to jednak ten lud nie był mi posłuszny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 17, 'Dlatego tak mówi Pan, Bóg zastępów, Bóg Izraela: Oto sprowadzę na Judę i na wszystkich mieszkańców Jerozolimy całe nieszczęście, które wypowiedziałem przeciwko nim, gdyż mówiłem do nich, a nie słuchali, wołałem ich, a nie odpowiedzieli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 18, 'Domowi Rekabitów Jeremiasz zaś powiedział: Tak mówi Pan zastępów, Bóg Izraela: Ponieważ byliście posłuszni nakazowi Jonadaba, waszego ojca, i przestrzegaliście wszystkich jego przykazań, i postępowaliście zgodnie ze wszystkim, co wam nakazał;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 19, 'Dlatego tak mówi Pan zastępów, Bóg Izraela: Nie zabraknie Jonadabowi, synowi Rekaba, potomka, który by stał przede mną po wszystkie dni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 1, 'W czwartym roku Joakima, syna Jozjasza, króla Judy, doszło do Jeremiasza słowo od Pana mówiące:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 2, 'Weź sobie zwój księgi i napisz na nim wszystkie słowa, które wypowiadałem do ciebie przeciw Izraelowi, przeciw Judzie i przeciw wszystkim narodom od dnia, kiedy zacząłem mówić do ciebie, od dni Jozjasza aż do dziś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 3, 'Może gdy dom Judy usłyszy o całym tym nieszczęściu, które zamierzam im uczynić, odwróci się każdy od swojej złej drogi, abym przebaczył ich nieprawość i grzech.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 4, 'Jeremiasz więc wezwał Barucha, syna Neriasza, a Baruch spisał z ust Jeremiasza na zwoju księgi wszystkie słowa Pana, które mówił do niego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 5, 'Potem Jeremiasz nakazał Baruchowi: Jestem powstrzymany i nie mogę wejść do domu Pana;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 6, 'Dlatego ty idź i odczytaj z tego zwoju, co napisałeś z moich ust – słowa Pana – do uszu ludu w domu Pana, w dzień postu. Odczytaj to także do uszu wszystkich z Judy, którzy przychodzą ze swoich miast.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 7, 'Może skierują swoje błaganie przed oblicze Pana i każdy odwróci się od swojej złej drogi. Wielkie są bowiem gniew i zapalczywość, które Pan wypowiedział przeciwko temu ludowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 8, 'I postąpił Baruch, syn Neriasza, zgodnie ze wszystkim, co prorok Jeremiasz mu nakazał, odczytując z księgi słowa Pana w domu Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 9, 'W piątym roku Joakima, syna Jozjasza, króla Judy, w dziewiątym miesiącu, zapowiedziano post przed Panem całemu ludowi w Jerozolimie i całemu ludowi, który przybył z miast Judy do Jerozolimy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 10, 'I Baruch odczytał z księgi słowa Jeremiasza w domu Pana, w komnacie Gemariasza, syna Szafana, pisarza, na górnym dziedzińcu, u wejścia do Bramy Nowej domu Pana, do uszu całego ludu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 11, 'A gdy Micheasz, syn Gemariasza, syna Szafana, usłyszał wszystkie słowa Pana z księgi;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 12, 'Zszedł do domu króla, do komnaty pisarza, a oto siedzieli tam wszyscy książęta: Eliszama, pisarz, Delajasz, syn Szemajasza, Elnatan, syn Akbora, Gemariasz, syn Szafana, Sedekiasz, syn Chananiasza, i pozostali książęta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 13, 'I Micheasz powiedział im wszystkie słowa, które usłyszał, gdy Baruch czytał z księgi do uszu ludu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 14, 'Wtedy wszyscy książęta posłali do Barucha Jehudiego, syna Netaniasza, syna Szelemiasza, syna Kusziego, z poleceniem: Weź do ręki zwój, z którego czytałeś do uszu ludu, i przyjdź. Baruch więc, syn Neriasza, wziął zwój do ręki i przyszedł do nich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 15, 'I powiedzieli do niego: Usiądź proszę i odczytaj to do naszych uszu. Czytał więc Baruch do ich uszu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 16, 'A gdy usłyszeli wszystkie te słowa, spojrzeli przerażeni jeden na drugiego i powiedzieli do Barucha: Musimy powiadomić króla o tych wszystkich słowach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 17, 'I zapytali Barucha: Powiedz nam teraz, jak spisywałeś wszystkie te słowa z jego ust?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 18, 'Baruch odpowiedział: Ustnie podawał mi wszystkie te słowa, a ja spisałem je atramentem w księdze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 19, 'Wtedy książęta powiedzieli do Barucha: Idź, ukryj się, ty i Jeremiasz, a niech nikt nie wie, gdzie jesteście.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 20, 'Potem weszli do króla na dziedziniec, ale księgę ukryli w komnacie Eliszamy, pisarza, i opowiedzieli do uszu króla wszystkie te słowa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 21, 'Król więc posłał Jehudiego, aby wziął zwój, a ten zabrał go z komnaty Eliszamy, pisarza. I Jehudi odczytał go do uszu króla i wszystkich książąt, którzy stali przed królem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 22, 'A król siedział w domu zimowym, w dziewiątym miesiącu, i ogień płonął na palenisku przed nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 23, 'Gdy Jehudi przeczytał trzy lub cztery karty, odcinał je nożem pisarskim i wrzucał do ognia, który rozpalony był na palenisku, aż cały zwój spłonął w ogniu na palenisku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 24, 'Ale nie przerazili się i nie rozdarli swoich szat ani król, ani jego słudzy, którzy słyszeli wszystkie te słowa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 25, 'Elnatan jednak, Delajasz i Gemariasz nalegali na króla, aby nie palił tego zwoju, ale ich nie usłuchał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 26, 'I król rozkazał Jerachmeelowi, synowi Meleka, Serajaszowi, synowi Azriela, i Szelemiaszowi, synowi Abdeela, aby pojmali Barucha, pisarza, i proroka Jeremiasza. Ale Pan ich ukrył.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 27, 'I do Jeremiasza doszło słowo Pana po spaleniu przez króla zwoju i słowa, które Baruch spisał z ust Jeremiasza, mówiące:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 28, 'Weź sobie jeszcze inny zwój i zapisz na nim wszystkie poprzednie słowa, które były na pierwszym zwoju, spalonym przez Joakima, króla Judy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 29, 'A do Joakima, króla Judy, powiedz: Tak mówi Pan: Ty spaliłeś ten zwój, mówiąc: Czemu napisałeś na nim: Na pewno król Babilonu nadciągnie, zniszczy tę ziemię i wytępi w niej człowieka i zwierzęta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 30, 'Dlatego tak mówi Pan o Joakimie, królu Judy: Nie będzie miał nikogo, kto zasiadłby na tronie Dawida, a jego zwłoki będą rzucone na upał we dnie i na mróz w nocy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 31, 'Nawiedzę go bowiem, jego potomstwo i jego sługi za ich nieprawość i sprowadzę na nich, na mieszkańców Jerozolimy i na Judejczyków całe to nieszczęście, które im zapowiedziałem, ale nie słuchali.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 32, 'Wtedy Jeremiasz wziął inny zwój i dał go Baruchowi, synowi Neriasza, pisarzowi, a ten spisał na nim z ust Jeremiasza wszystkie słowa tamtego zwoju, który spalił w ogniu Joakim, król Judy. Nadto zostało dodane do nich wiele podobnych słów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 1, 'Potem królował król Sedekiasz, syn Jozjasza, w miejsce Choniasza, syna Joakima, którego Nabuchodonozor, król Babilonu, ustanowił królem w ziemi Judy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 2, 'Lecz ani on, ani jego słudzy, ani lud tej ziemi nie słuchali słów Pana, które wypowiedział przez proroka Jeremiasza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 3, 'Król Sedekiasz jednak posłał Jehuchala, syna Szelemiasza, i Sofoniasza, syna Maasejasza, kapłana, do proroka Jeremiasza, aby powiedzieli: Módl się za nas do Pana, naszego Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 4, 'Jeremiasz zaś chodził swobodnie wśród ludu, gdyż jeszcze nie wtrącono go do więzienia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 5, 'Tymczasem wojsko faraona wyruszyło z Egiptu. A gdy usłyszeli tę wieść Chaldejczycy oblegający Jerozolimę, odstąpili od Jerozolimy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 6, 'I słowo Pana doszło do proroka Jeremiasza mówiące:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 7, 'To mówi Pan, Bóg Izraela: Tak powiedzcie królowi Judy, który posłał was do mnie, abyście się mnie radzili: Oto wojsko faraona, które wyruszyło wam na pomoc, wróci do swojej ziemi, do Egiptu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 8, 'I Chaldejczycy powrócą, i będą walczyli przeciwko temu miastu, zdobędą je i spalą ogniem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 9, 'Tak mówi Pan: Nie zwódźcie samych siebie, mówiąc: Z pewnością Chaldejczycy odstąpią od nas. Bo nie odstąpią.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 10, 'Choćbyście nawet pobili całe wojsko Chaldejczyków, którzy walczą z wami, i zostaliby z nich tylko ranni, to ci powstaliby ze swoich namiotów i ogniem spaliliby to miasto.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 11, 'A gdy wojsko Chaldejczyków odstąpiło od Jerozolimy przed wojskiem faraona;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 12, 'Jeremiasz wychodził z Jerozolimy, aby udać się do ziemi Beniamina, by tym sposobem ujść stamtąd pośród ludu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 13, 'A gdy był już w Bramie Beniamina, znajdował się tam dowódca straży, imieniem Jirijasz, syn Szelemiasza, syna Chananiasza; ten pojmał proroka Jeremiasza, mówiąc: Przechodzisz do Chaldejczyków!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 14, 'Jeremiasz odpowiedział: Nieprawda, nie przechodzę do Chaldejczyków. Ale tamten nie chciał go słuchać. Jirijasz pojmał Jeremiasza i przyprowadził go do książąt.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 15, 'Książęta rozgniewali się na Jeremiasza, bili go i wsadzili do więzienia w domu Jonatana, pisarza, bo ten zamieniono na więzienie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 16, 'A gdy Jeremiasz wszedł do tego lochu i do celi, i siedział tam Jeremiasz przez wiele dni;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 17, 'Wtedy król Sedekiasz posłał, aby go przyprowadzono. I król wypytywał go potajemnie w swoim domu: Czy jest jakieś słowo od Pana? Jeremiasz odpowiedział: Jest. I dodał: Będziesz wydany w ręce króla Babilonu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 18, 'Nadto Jeremiasz powiedział do króla Sedekiasza: Czym zgrzeszyłem przeciwko tobie, twoim sługom lub twemu ludowi, że wsadziliście mnie do tego więzienia?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 19, 'Gdzie są wasi prorocy, którzy wam prorokowali, mówiąc: Król Babilonu nie nadciągnie przeciwko wam ani przeciwko tej ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 20, 'Teraz więc słuchaj, proszę, królu, mój panie. Niech moja prośba dotrze do ciebie: Nie odsyłaj mnie do domu Jonatana, pisarza, abym tam nie umarł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 21, 'Król Sedekiasz rozkazał więc oddać Jeremiasza pod straż na dziedzińcu więzienia i aby dawano mu bochenek chleba dziennie z ulicy Piekarzy, póki nie został wyczerpany cały chleb w mieście. A Jeremiasz pozostał na dziedzińcu więzienia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 1, 'Wtedy Szefatiasz, syn Matana, Gedaliasz, syn Paszchura, Jukal, syn Szelemiasza, i Paszchur, syn Malkiasza, usłyszeli słowa, które Jeremiasz wypowiadał do całego ludu:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 2, 'Tak mówi Pan: Kto zostanie w tym mieście, zginie od miecza, od głodu i od zarazy. Ale kto przejdzie do Chaldejczyków, będzie żyć; jego życie będzie dla niego jak zdobycz i pozostanie żywy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 3, 'Tak mówi Pan: To miasto na pewno będzie wydane w ręce wojska króla Babilonu i on je zdobędzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 4, 'Dlatego książęta powiedzieli do króla: Ten człowiek musi umrzeć, ponieważ osłabia on ręce wojowników, którzy pozostali w tym mieście, i ręce całego ludu, gdy mówi do nich takie słowa. Ten człowiek bowiem nie szuka pomyślności tego ludu, lecz jego nieszczęścia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 5, 'Wtedy król Sedekiasz powiedział: Oto jest w waszych rękach, bo król nic nie może czynić przeciwko wam.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 6, 'Zabrali więc Jeremiasza i wrzucili go do lochu Malkiasza, syna Meleka, który zbudowany był na dziedzińcu więzienia; spuścili Jeremiasza na sznurach. A w tym lochu nie było żadnej wody, tylko samo błoto. I Jeremiasz ugrzązł w tym błocie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 7, 'A gdy Ebedmelek, Etiopczyk, eunuch w domu króla, usłyszał, że Jeremiasza wrzucono do lochu – a król siedział w Bramie Beniamina;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 8, 'Ebedmelek wyszedł z domu króla i powiedział do króla:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 9, 'Królu, mój panie! Ci ludzie postąpili źle we wszystkim, co uczynili wobec proroka Jeremiasza, którego wrzucili do tego lochu; umrze z głodu w tym miejscu, ponieważ już nie ma chleba w mieście.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 10, 'Wtedy król rozkazał Ebedmelekowi, Etiopczykowi: Weź stąd ze sobą trzydziestu mężczyzn i wyciągnij proroka Jeremiasza z lochu, zanim umrze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 11, 'Wziął więc Ebedmelek tych mężczyzn ze sobą, wszedł do domu króla pod skarbnicę i zabrał stamtąd stare, podarte łachmany i zbutwiałe szmaty, które spuścił na sznurach do Jeremiasza, do lochu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 12, 'I Ebedmelek, Etiopczyk, powiedział do Jeremiasza: Podłóż te stare, podarte łachmany i zbutwiałe szmaty pod pachy swoich rąk, pod sznury. I Jeremiasz tak uczynił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 13, 'Wyciągnęli więc Jeremiasza sznurami i wydobyli go z lochu. Potem Jeremiasz siedział na dziedzińcu więzienia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 14, 'Następnie król Sedekiasz posłał i wziął proroka Jeremiasza do siebie, do trzeciego wejścia domu Pana. I król powiedział do Jeremiasza: Zapytam cię o jedną rzecz, nie taj niczego przede mną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 15, 'Jeremiasz odpowiedział Sedekiaszowi: Jeśli ci powiem, czy na pewno nie zabijesz mnie? Jeśli ci coś poradzę, nie posłuchasz mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 16, 'Wedy król Sedekiasz przysiągł Jeremiaszowi potajemnie: Jak żyje Pan, który stworzył nam dusze, nie zabiję cię ani nie wydam cię w ręce tych mężczyzn, którzy czyhają na twoje życie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 17, 'Jeremiasz powiedział do Sedekiasza: Tak mówi Pan, Bóg zastępów, Bóg Izraela: Jeśli dobrowolnie wyjdziesz do książąt króla Babilonu, wtedy twoja dusza będzie żyć, a to miasto nie zostanie spalone ogniem; pozostaniesz żywy ty i twój dom;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 18, 'Ale jeśli nie wyjdziesz do książąt króla Babilonu, na pewno to miasto będzie wydane w ręce Chaldejczyków, którzy spalą je ogniem, a ty nie ujdziesz z ich rąk.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 19, 'Król Sedekiasz powiedział do Jeremiasza: Bardzo się boję Żydów, którzy przeszli do Chaldejczyków, by czasem nie wydali mnie w ich ręce i nie szydzili ze mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 20, 'Jeremiasz odpowiedział: Nie wydadzą cię. Posłuchaj, proszę, głosu Pana, który ci przekazuję, a dobrze ci się powiedzie i twoja dusza będzie żyć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 21, 'Jeśli zaś będziesz wzbraniał się wyjść, takie jest słowo, które Pan mi pokazał:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 22, 'Oto wszystkie kobiety, które pozostały w domu króla Judy, będą wyprowadzone do książąt króla Babilonu i tak one powiedzą: Twoi przyjaciele oszukali cię i przemogli, twoje nogi ugrzęzły w błocie, a oni się wycofali.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 23, 'Wszystkie twoje żony i twoich synów wyprowadzą do Chaldejczyków, a i ty nie ujdziesz ich rękom, lecz będziesz pojmany ręką króla Babilonu, a to miasto spalą ogniem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 24, 'Wtedy Sedekiasz powiedział do Jeremiasza: Niech nikt nie wie o tej rozmowie, a ty nie umrzesz;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 25, 'A jeśli książęta usłyszą, że rozmawiałem z tobą, przyjdą do ciebie i powiedzą: Powiedz nam, proszę, co mówiłeś do króla; nie ukrywaj przed nami, a nie zabijemy cię; a co ci mówił król?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 26, 'Wtedy im powiesz: Przedłożyłem królowi moją prośbę, aby mnie nie odsyłał do domu Jonatana, abym tam nie umarł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 27, 'I wszyscy książęta przyszli do Jeremiasza, i pytali go, a on odpowiedział im zgodnie z tym wszystkim, co król mu rozkazał. I odstąpili w milczeniu od niego, gdyż sprawa nie wyszła na jaw.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 28, 'A Jeremiasz przebywał na dziedzińcu więzienia aż do tego dnia, kiedy zdobyto Jerozolimę. Był tam, gdy Jerozolima została zdobyta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 1, 'W dziewiątym roku Sedekiasza, króla Judy, dziesiątego miesiąca, nadciągnął Nabuchodonozor, król Babilonu, z całym swoim wojskiem do Jerozolimy i obległ ją.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 2, 'A w jedenastym roku Sedekiasza, czwartego miesiąca, dziewiątego dnia tego miesiąca, zrobiono wyłom w murach miasta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 3, 'I weszli do niego wszyscy książęta króla Babilonu, i zasiedli w Bramie Środkowej: Nergalsarezer, Samgarnebo, Sarsechim, Rabsaris, Nergalsarezer, Rabmag i pozostali książęta króla Babilonu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 4, 'Gdy zobaczył ich Sedekiasz, król Judy, i wszyscy wojownicy, uciekli, wychodząc nocą z miasta drogą ogrodu królewskiego, przez bramę między dwoma murami. I król szedł drogą w stronę równiny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 5, 'Lecz wojsko Chaldejczyków ścigało ich i doścignęło Sedekiasza na równinach Jerycha; pojmali go i przyprowadzili do Nabuchodonozora, króla Babilonu, do Ribla, w ziemi Chamat, gdzie ten wydał na niego wyrok.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 6, 'Król Babilonu zabił synów Sedekiasza w Ribla na jego oczach. Król Babilonu zabił również wszystkich dostojników Judy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 7, 'Ale Sedekiaszowi wyłupił oczy i zakuł go w łańcuchy, aby go uprowadzić do Babilonu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 8, 'Chaldejczycy spalili ogniem dom króla i domy ludu, a mury Jerozolimy zburzyli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 9, 'Ale resztę ludu, który pozostał w mieście, i zbiegów, którzy przeszli do niego, oraz pozostałych ludzi Nebuzaradan, dowódca gwardii, uprowadził do niewoli do Babilonu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 10, 'Natomiast ubogich spośród ludu, którzy nic nie mieli, Nebuzaradan, dowódca gwardii, pozostawił w ziemi Judy i dał im równocześnie winnice i pola.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 11, 'A co do Jeremiasza Nabuchodonozor, król Babilonu, nakazał Nebuzaradanowi, dowódcy gwardii:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 12, 'Weź go, zajmij się nim i nie czyń mu nic złego, lecz postąp z nim tak, jak on ci powie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 13, 'Posłali więc Nebuzaradan, dowódca gwardii, oraz Nebuszasban, Rabsaris, Nergalsarezer, Rabmag i wszyscy dostojnicy króla Babilonu po niego;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 14, 'Oni wszyscy posłali po Jeremiasza i zabrali go z dziedzińca więzienia, i przekazali Gedaliaszowi, synowi Achikama, syna Szafana, aby go zaprowadził do domu. Zamieszkał więc pośród ludu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 15, 'I słowo Pana doszło do Jeremiasza, gdy ten jeszcze był zamknięty na dziedzińcu więzienia, mówiące:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 16, 'Idź i powiedz Ebedmelekowi, Etiopczykowi: Tak mówi Pan zastępów, Bóg Izraela: Oto spełnię swoje słowa wypowiedziane nad tym miastem ku złemu, a nie ku dobremu, i wypełnią się w owym dniu na twoich oczach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 17, 'Ale ciebie wybawię w tym dniu, mówi Pan, i nie będziesz wydany w ręce mężczyzn, których się boisz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 18, 'Na pewno bowiem cię wybawię i nie padniesz od miecza, ale twoje życie będzie dla ciebie jak zdobycz, gdyż złożyłeś ufność we mnie, mówi Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 1, 'Słowo, które doszło od Pana do Jeremiasza, po uwolnieniu go z Rama przez Nebuzaradana, dowódcę gwardii, gdy go zabrał związanego łańcuchami spośród wszystkich więźniów Jerozolimy i Judy, których uprowadzono do Babilonu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 2, 'Dowódca gwardii wziął Jeremiasza i powiedział do niego: Pan, twój Bóg, zapowiedział to nieszczęście przeciwko temu miejscu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 3, 'Pan więc sprowadził je i spełnił, jak powiedział. Zgrzeszyliście bowiem przeciwko Panu i nie słuchaliście jego głosu, dlatego was to spotkało.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 4, 'Teraz oto uwalniam cię dziś z tych łańcuchów, które są na twoich rękach. Jeśli uważasz za słuszne pójść ze mną do Babilonu, chodź; ja zatroszczę się o ciebie. A jeśli uważasz za niesłuszne pójść ze mną do Babilonu, zaniechaj tego. Oto cała ziemia jest przed tobą. Gdzie uważasz, że dobrze i słusznie byłoby pójść, tam idź.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 5, 'A gdy on jeszcze nie odchodził, powiedział: Udaj się do Gedaliasza, syna Achikama, syna Szafana, którego król Babilonu ustanowił namiestnikiem nad miastami Judy, i zamieszkaj z nim pośród ludu albo idź, gdziekolwiek uważasz za słuszne. I dowódca gwardii dał mu żywność i podarunek i odprawił go.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 6, 'Wtedy Jeremiasz udał się do Gedaliasza, syna Achikama, do Mispy, i mieszkał z nim wśród ludu, który pozostał w ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 7, 'A gdy wszyscy dowódcy wojsk, którzy przebywali na polach, oni i ich ludzie, usłyszeli, że król Babilonu ustanowił Gedaliasza, syna Achikama, namiestnikiem w ziemi i że powierzył mu mężczyzn, kobiety, dzieci i ubogich tej ziemi, których nie uprowadzono do Babilonu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 8, 'Do Gedaliasza do Mispy przyszli: Izmael, syn Netaniasza, Jochanan i Jonatan, synowie Kareacha, Serajasz, syn Tanchumeta, synowie Efaja Netofatyty, oraz Jezaniasz, syn Maachatyty, oni i ich ludzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 9, 'Wtedy Gedaliasz, syn Achikama, syna Szafana, przysiągł im i ich ludziom: Nie bójcie się służyć Chaldejczykom. Pozostańcie w ziemi i służcie królowi Babilonu, a będzie wam dobrze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 10, 'Oto bowiem mieszkam w Mispie, aby służyć Chaldejczykom, którzy przyjdą do nas; a wy zbierajcie wino, letnie owoce i oliwę, gromadźcie w swoich naczyniach i mieszkajcie w swoich miastach, które zajmujecie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 11, 'Także i wszyscy Żydzi, którzy byli w Moabie, pośród synów Ammona, w Edomie i we wszystkich innych ziemiach, gdy usłyszeli, że król Babilonu pozostawił resztkę z Judy i że ustanowił nad nimi Gedaliasza, syna Achikama, syna Szafana;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 12, 'Wrócili wszyscy ci Żydzi ze wszystkich miejsc, do których zostali wygnani, i przyszli do ziemi Judy, do Gedaliasza do Mispy, i nazbierali bardzo obficie wina i letnich owoców.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 13, 'Ale Jochanan, syn Kareacha, i wszyscy dowódcy wojsk, którzy przebywali na polach, przyszli do Gedaliasza do Mispy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 14, 'I powiedzieli do niego: Czy wiesz o tym, że Baalis, król synów Ammona, posłał Izmaela, syna Netaniasza, aby cię zabić? Ale Gedaliasz, syn Achikama, nie uwierzył im.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 15, 'Wtedy Jochanan, syn Kareacha, powiedział potajemnie do Gedaliasza w Mispie: Pozwól mi pójść, proszę, i zabiję Izmaela, syna Netaniasza, a nikt się o tym nie dowie. Dlaczego ma cię zabić, aby zostali rozproszeni wszyscy Żydzi, którzy się zebrali u ciebie, i aby zginęła resztka Judy?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 16, 'Ale Gedaliasz, syn Achikama, odpowiedział Jochananowi, synowi Kareacha: Nie czyń tego, bo to, co mówisz o Izmaelu, jest nieprawdą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 1, 'Zdarzyło się, że w siódmym miesiącu Izmael, syn Netaniasza, syna Eliszamy, z potomstwa króla, a wraz z nim dowódcy króla w liczbie dziesięciu mężczyzn przybyli do Gedaliasza, syna Achikama, do Mispy, i razem spożywali tam posiłek, w Mispie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 2, 'Potem wstał Izmael, syn Netaniasza, oraz dziesięciu mężczyzn, którzy z nim byli, i zabili mieczem Gedaliasza, syna Achikama, syna Szafana; zabili tego, którego król Babilonu ustanowił namiestnikiem w ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 3, 'Izmael zabił też wszystkich Żydów, którzy byli z nim, z Gedaliaszem, w Mispie, oraz Chaldejczyków, którzy się tam znajdowali, a także wojowników.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 4, 'Na drugi dzień po zabójstwie Gedaliasza, gdy nikt o tym jeszcze nie wiedział;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 5, 'Przyszli ludzie z Sychem, z Szilo i Samarii w liczbie osiemdziesięciu, z ogolonymi brodami, w rozdartych szatach i z nacięciami na ciele, mając w rękach ofiary i kadzidło, aby je złożyć w domu Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 6, 'Wtedy Izmael, syn Netaniasza, wyszedł im naprzeciw z Mispy, a gdy szedł, płakał. Gdy ich spotkał, powiedział do nich: Chodźcie do Gedaliasza, syna Achikama.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 7, 'Ale gdy weszli do miasta, zabił ich Izmael, syn Netaniasza, i wrzucił do cysterny, on i mężczyźni, którzy z nim byli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 8, 'Lecz pośród tamtych znalazło się dziesięciu, którzy powiedzieli do Izmaela: Nie zabijaj nas, bo mamy ukryte w polu skarby: pszenicę i jęczmień, oliwę i miód. Wstrzymał się więc i nie zabił ich razem z ich braćmi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 9, 'A cysterna, do której Izmael wrzucił wszystkie zwłoki tych mężczyzn, których zabił z powodu Gedaliasza, była tą samą, którą wykonał król Asa z obawy przed Baszą, królem Izraela. Tę cysternę Izmael, syn Netaniasza, wypełnił zabitymi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 10, 'Potem Izmael uprowadził do niewoli resztę ludu, który był w Mispie: córki króla i cały lud, który pozostał w Mispie, a których Nebuzaradan, dowódca gwardii, powierzył Gedaliaszowi, synowi Achikama. Izmael, syn Netaniasza, uprowadził ich i wyruszył, by przejść do synów Ammona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 11, 'Gdy jednak Jochanan, syn Kareacha, i wszyscy dowódcy wojsk, którzy byli z nim, usłyszeli o całej tej niegodziwości, którą popełnił Izmael, syn Netaniasza;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 12, 'Zebrali wszystkich mężczyzn i nadciągnęli, aby walczyć z Izmaelem, synem Netaniasza. I znaleźli go przy wielkich wodach, które są w Gibeonie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 13, 'Gdy cały lud, który był z Izmaelem, zobaczył Jochanana, syna Kareacha, i wszystkich dowódców wojsk, którzy z nim byli, uradował się.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 14, 'Cały lud więc, który Izmael uprowadził do niewoli z Mispy, odwrócił się i ruszył z powrotem, i przyszedł do Jochanana, syna Kareacha.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 15, 'Izmael zaś, syn Netaniasza, uciekł z ośmioma mężczyznami przed Jochananem i przybył do synów Ammona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 16, 'Wtedy Jochanan, syn Kareacha, wraz ze wszystkimi dowódcami wojsk, którzy z nim byli, zebrał całą resztę ludu, który odzyskał od Izmaela, syna Netaniasza, z Mispy, po zabójstwie Gedaliasza, syna Achikama, walecznych wojowników, kobiety, dzieci i eunuchów, których przywiódł z powrotem z Gibeonu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 17, 'Odeszli i zatrzymali się w gospodzie Kimhama, w pobliżu Betlejem, zamierzając udać się do Egiptu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 18, 'Z obawy przed Chaldejczykami. Bali się ich bowiem, ponieważ Izmael, syn Netaniasza, zabił Gedaliasza, syna Achikama, którego król Babilonu ustanowił namiestnikiem w ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 1, 'Potem wszyscy dowódcy wojsk, Jochanan, syn Kareacha, Jezaniasz, syn Hoszajasza, oraz cały lud, od małego do wielkiego, przystąpili;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 2, 'I powiedzieli do proroka Jeremiasza: Niech nasza prośba dotrze do ciebie i módl się za nami do Pana, twojego Boga, za całą tę resztkę, bo mało nas pozostało z wielkiej liczby, jak sam widzisz na własne oczy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 3, 'I niech Pan, twój Bóg, wskaże nam drogę, którą mamy iść, i to, co mamy czynić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 4, 'Wtedy prorok Jeremiasz odpowiedział im: Słyszałem. Oto będę się modlić do Pana, waszego Boga, według waszych słów, a cokolwiek Pan wam odpowie, ja wam oznajmię, niczego przed wami nie zataję.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 5, 'Oni zaś powiedzieli do Jeremiasza: Niech Pan będzie między nami prawdziwym i wiernym świadkiem, jeśli nie postąpimy według każdego słowa, z którym Pan, twój Bóg, pośle cię do nas.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 6, 'Czy będzie dobre, czy złe – usłuchamy głosu Pana, naszego Boga, do którego cię posyłamy; aby nam się dobrze powodziło, gdy będziemy słuchać głosu Pana, naszego Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 7, 'A po upływie dziesięciu dni doszło do Jeremiasza słowo Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 8, 'Zawołał więc Jochanana, syna Kareacha, i wszystkich dowódców wojsk, którzy z nim byli, oraz cały lud, od małego do wielkiego;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 9, 'I powiedział do nich: Tak mówi Pan, Bóg Izraela, do którego mnie posłaliście, abym przedłożył mu waszą prośbę;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 10, 'Jeśli pozostaniecie na stałe w tej ziemi, odbuduję was i nie zburzę, zasadzę was i nie wykorzenię. Żal mi bowiem tego nieszczęścia, które wam uczyniłem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 11, 'Nie bójcie się króla Babilonu, którego tak się boicie. Nie bójcie się go, mówi Pan, bo ja jestem z wami, aby was wybawić i wyrwać z jego ręki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 12, 'Okażę wam łaskę, aby on się zlitował nad wami i dał wam wrócić do waszej ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 13, 'Ale jeśli powiecie: Nie zostaniemy w tej ziemi, nie usłuchamy głosu Pana, waszego Boga;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 14, 'Mówiąc: Żadną miarą! Lecz pójdziemy do ziemi Egiptu, gdzie nie zobaczymy wojny ani nie usłyszymy dźwięku trąby, ani nie będziemy łaknąć chleba; tam będziemy mieszkać;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 15, 'To posłuchajcie teraz słowa Pana, resztko Judy: Tak mówi Pan zastępów, Bóg Izraela: Jeśli w uporze przy tym zostaniecie, aby pójść do ziemi Egiptu, i pójdziecie, aby tam przebywać;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 16, 'Wtedy miecz, którego się boicie, dosięgnie was tam w ziemi Egiptu, a głód, którego się obawiacie, będzie was ścigał tam w Egipcie, i tam pomrzecie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 17, 'Tak się stanie wszystkim, którzy koniecznie chcą iść do Egiptu, aby tam przebywać: umrą od miecza, od głodu i od zarazy, żaden z nich nie pozostanie ani nie ujdzie przed tym nieszczęściem, jakie na nich sprowadzę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 18, 'Tak bowiem mówi Pan zastępów, Bóg Izraela: Jak się wylały mój gniew i moja zapalczywość na mieszkańców Jerozolimy, tak się wyleje moja zapalczywość na was, gdy wejdziecie do Egiptu. I będziecie przedmiotem złorzeczenia, zdumienia, przekleństwa i hańby, a nie zobaczycie już tego miejsca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 19, 'Pan do was mówi, resztko Judy: Nie idźcie do Egiptu. Wiedzcie na pewno, że dziś was ostrzegam.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 20, 'Zwiedliście bowiem swoje dusze, gdy posłaliście mnie do Pana, waszego Boga, mówiąc: Módl się za nami do Pana, naszego Boga, i oznajmij nam wszystko, co powie Pan, nasz Bóg, a my to wykonamy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 21, 'Dzisiaj to wam oznajmiam, wy jednak nie słuchacie głosu Pana, waszego Boga, we wszystkim, z czym mnie do was posłał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 22, 'Dlatego mówię: Wiedzcie na pewno, że umrzecie od miecza, od głodu i od zarazy w tym miejscu, do którego pragniecie iść, aby tam przebywać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 1, 'Gdy Jeremiasz przestał mówić do całego ludu te wszystkie słowa Pana, ich Boga, z którymi posłał go do nich Pan, ich Bóg, wszystkie te słowa;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 2, 'Azariasz, syn Hoszajasza, i Jochanan, syn Kareacha, oraz wszyscy pyszni mężczyźni powiedzieli do Jeremiasza: Kłamstwo mówisz! Nie posłał cię Pan, nasz Bóg, byś mówił: Nie idźcie do Egiptu, aby tam przebywać;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 3, 'Ale Baruch, syn Neriasza, podburza cię przeciwko nam, aby nas wydać w ręce Chaldejczyków, żeby nas pobili albo uprowadzili do niewoli do Babilonu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 4, 'Dlatego Jochanan, syn Kareacha, oraz wszyscy dowódcy wojsk, a także cały lud nie słuchali głosu Pana, aby pozostać w ziemi Judy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 5, 'Lecz Jochanan, syn Kareacha, i wszyscy dowódcy wojsk zabrali całą resztkę Judy, która powróciła ze wszystkich narodów, do których została wygnana, by zamieszkać w ziemi Judy:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 6, 'Mężczyzn, kobiety, dzieci, córki króla oraz każdą duszę, którą pozostawił Nebuzaradan, dowódca gwardii, z Gedaliaszem, synem Achikama, syna Szafana, z prorokiem Jeremiaszem i z Baruchem, synem Neriasza;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 7, 'I poszli do ziemi Egiptu, bo nie usłuchali głosu Pana. I przybyli do Tachpanches.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 8, 'I w Tachpanches doszło do Jeremiasza słowo Pana mówiące:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 9, 'Weź do rąk wielkie kamienie i ukryj je w glinie w piecu do wypalania cegieł, który jest przy wejściu do domu faraona w Tachpanches, na oczach mężczyzn Judy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 10, 'I powiedz im: Tak mówi Pan zastępów, Bóg Izraela: Oto poślę po Nabuchodonozora, króla Babilonu, mego sługę, i sprowadzę go, i ustawię jego tron na tych kamieniach, które ukryłem; i rozciągnie swój baldachim na nich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 11, 'Gdy przyjdzie, pobije ziemię Egiptu, a oddani na śmierć na śmierć pójdą, oddani do niewoli do niewoli pójdą, i oddani pod miecz pod miecz pójdą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 12, 'Podłożę ogień w domach bogów Egiptu i on je spali, i uprowadzi. Przyozdobi się ziemią Egiptu, jak pasterz zakłada swoją szatę, i wyjdzie stamtąd w pokoju.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 13, 'Rozbije posągi w Betszemesz, które jest w ziemi Egiptu, oraz ogniem spali domy bogów egipskich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 1, 'Słowo, które doszło do Jeremiasza o wszystkich Żydach mieszkających w ziemi Egiptu, którzy mieszkali w Migdol, w Tachpanches, w Nof i w ziemi Patros, mówiące:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 2, 'Tak mówi Pan zastępów, Bóg Izraela: Wy widzieliście wszystkie nieszczęścia, które sprowadziłem na Jerozolimę i na wszystkie miasta Judy, a oto są dzisiaj spustoszeniem, nie ma w nich mieszkańców.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 3, 'Z powodu ich niegodziwości, którą popełniali, aby pobudzać mnie do gniewu, gdy palili kadzidło i służyli innym bogom, których nie znali ani oni, ani wy, ani wasi ojcowie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 4, 'Chociaż posyłałem do was wszystkie moje sługi, proroków, z wczesnym wstawaniem i przesłaniem, mówiąc: Nie czyńcie, proszę, tej obrzydliwości, której nienawidzę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 5, 'Ale oni nie usłuchali ani nie nakłonili swego ucha, aby odwrócić się od swojej niegodziwości i nie palić kadzidła innym bogom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 6, 'Dlatego został wylany mój gniew i moja zapalczywość zapłonęła w miastach Judy i na ulicach Jerozolimy, tak że stały się pustkowiem i spustoszeniem, jak to jest dzisiaj.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 7, 'Dlatego teraz tak mówi Pan, Bóg zastępów, Bóg Izraela: Czemu wyrządzacie swoim duszom to wielkie zło, przyczyniając się do wyniszczenia mężczyzn, kobiet, dzieci i niemowląt spośród Judy, tak, aby nikt z was nie pozostało;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 8, 'Gdyż pobudzacie mnie do gniewu uczynkami swoich rąk, paląc kadzidło innym bogom w ziemi Egiptu, do której weszliście, by tam mieszkać – i abyście byli wyniszczeni, i stali się przekleństwem i hańbą u wszystkich narodów na ziemi?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 9, 'Czy zapomnieliście o niegodziwości waszych ojców, o niegodziwości królów Judy, o niegodziwości ich żon, o waszej niegodziwości i o niegodziwości waszych żon, których się dopuszczały w ziemi Judy i na ulicach Jerozolimy?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 10, 'Po dziś dzień nie ukorzyli się ani się nie boją, ani nie postępują według mojego prawa i moich ustaw, które dałem wam i waszym ojcom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 11, 'Dlatego tak mówi Pan zastępów, Bóg Izraela: Oto zwrócę swoje oblicze przeciwko wam na nieszczęście, aby wyniszczyć całą Judę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 12, 'Wezmę resztę Judy, tych, którzy z uporem poszli do ziemi Egiptu, aby tam przebywać, i wyginą wszyscy w ziemi Egiptu; wyginą od miecza i od głodu, wyginą od najmniejszego do największego; pomrą od miecza i od głodu. I będą przedmiotem złorzeczenia, zdumienia, przekleństwa i hańby.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 13, 'Bo nawiedzę tych, którzy mieszkają w ziemi Egiptu, jak nawiedziłem Jerozolimę – mieczem, głodem i zarazą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 14, 'I z reszty Judy, która przybyła do ziemi Egiptu, by tam przebywać, nikt nie ujdzie ani nie ocaleje, by powrócić do ziemi Judy, do której pragną wrócić, by tam zamieszkać. Nikt bowiem nie powróci oprócz tych, którzy ujdą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 15, 'Wtedy wszyscy mężczyźni, którzy wiedzieli, że ich żony paliły kadzidło innym bogom, wszystkie kobiety stojące w wielkiej gromadzie i cały lud, który mieszkał w ziemi Egiptu, w Patros, odpowiedzieli Jeremiaszowi:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 16, 'Co do słowa, które mówiłeś do nas w imię Pana, nie usłuchamy cię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 17, 'Ale na pewno wypełnimy każde słowo, które wyjdzie z naszych ust: będziemy spalać kadzidło królowej niebios i wylewać dla niej ofiary z płynów, jak dotąd czyniliśmy, my i nasi ojcowie, nasi królowie i nasi książęta, w miastach Judy i na ulicach Jerozolimy. Wtedy bowiem najadaliśmy się chleba, było nam dobrze i nic złego nas nie spotkało.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 18, 'Lecz odkąd przestaliśmy palić kadzidło królowej niebios i składać jej ofiary z płynów, brakuje nam wszystkiego i giniemy od miecza i głodu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 19, 'A gdy paliliśmy kadzidło królowej niebios i wylewaliśmy dla niej ofiary z płynów, czy bez zgody naszych mężów czyniliśmy placki ku jej czci i składaliśmy jej ofiary z płynów?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 20, 'Wtedy Jeremiasz powiedział do całego ludu: do mężczyzn i kobiet oraz do wszystkich ludzi, którzy mu tak odpowiedzieli:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 21, 'Czy Pan nie pamięta kadzidła, które paliliście w miastach Judy i na ulicach Jerozolimy, wy i wasi ojcowie, wasi królowie i wasi książęta oraz lud ziemi, i czy nie wziął sobie tego do serca?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 22, 'Tak że Pan nie mógł już dłużej znosić zła waszych uczynków i obrzydliwości, które popełnialiście. Dlatego wasza ziemia stała się spustoszeniem i przedmiotem zdumienia i przekleństwa, bez mieszkańców, jak to jest dzisiaj.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 23, 'Ponieważ paliliście kadzidło i grzeszyliście przeciw Panu, a nie słuchaliście głosu Pana i nie postępowaliście według jego prawa, jego ustaw i jego świadectw, spotkało was to nieszczęście, jak to jest dzisiaj.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 24, 'Następnie Jeremiasz powiedział do całego ludu i do wszystkich kobiet: Słuchajcie słowa Pana, wszyscy z Judy, którzy jesteście w ziemi Egiptu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 25, 'Tak mówi Pan zastępów, Bóg Izraela: Wy i wasze żony wypowiadaliście to własnymi ustami i spełnialiście to swoimi rękami, mówiąc: Na pewno wypełnimy swoje śluby, które złożyliśmy, aby palić kadzidło królowej niebios i składać jej ofiary z płynów. Tak, na pewno spełnicie swoje śluby i wykonacie swoje śluby.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 26, 'Dlatego słuchajcie słowa Pana, wszyscy ludzie Judy, którzy mieszkacie w ziemi Egiptu: Oto przysięgam na swoje wielkie imię, mówi Pan, że moje imię nie będzie już wzywane ustami żadnego człowieka z Judy w całej ziemi Egiptu, który by mówił: Jak żyje Pan Bóg!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 27, 'Oto będę czuwał nad nimi ku złemu, a nie ku dobremu. I wszyscy ludzie z Judy, którzy są w ziemi Egiptu, zginą od miecza i głodu, doszczętnie wyginą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 28, 'I tylko mała liczba ujdzie spod miecza, i powróci z ziemi Egiptu do ziemi Judy, a cała reszta Judy, która weszła do ziemi Egiptu, aby tam przebywać, pozna, czyje słowo się spełni: moje czy jej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 29, 'A to będzie dla was znakiem, mówi Pan, że ja was ukarzę w tym miejscu, abyście wiedzieli, że moje słowa na pewno się spełnią ku waszemu nieszczęściu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 30, 'Tak mówi Pan: Oto wydam faraona Chofrę, króla Egiptu, w ręce jego wrogów i w ręce tych, którzy czyhają na jego życie, tak jak wydałem Sedekiasza, króla Judy, w ręce Nabuchodonozora, króla Babilonu, jego wroga, który czyhał na jego życie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 1, 'Słowo, które prorok Jeremiasz wypowiedział do Barucha, syna Neriasza, gdy spisał te słowa w księdze z ust Jeremiasza w czwartym roku Joakima, syna Jozjasza, króla Judy:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 2, 'Tak mówi Pan, Bóg Izraela, do ciebie, Baruchu:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 3, 'Powiedziałeś: Biada mi teraz! Bo Pan przydaje smutku do mojego bólu; utrudziłem się swoim wzdychaniem i nie znajduję odpoczynku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 4, 'Tak powiesz do niego: Tak mówi Pan: Oto co zbudowałem, zburzę, co zasadziłem, wyplenię, tę całą ziemię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 5, 'A ty szukasz dla siebie wielkich rzeczy? Nie szukaj. Oto bowiem sprowadzę nieszczęście na wszelkie ciało, mówi Pan. Ale tobie dam twoje życie jako zdobycz we wszystkich miejscach, dokądkolwiek pójdziesz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 1, 'Słowo Pana, które doszło do proroka Jeremiasza przeciw poganom;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 2, 'Przeciw Egiptowi, przeciw wojsku faraona Neko, króla Egiptu, które znajdowało się nad rzeką Eufrat pod Karkemisz, a które pobił Nabuchodonozor, król Babilonu, w czwartym roku Joakima, syna Jozjasza, króla Judy:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 3, 'Przygotujcie puklerz i tarczę i ruszajcie do walki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 4, 'Zaprzęgajcie konie i wsiadajcie, jeźdźcy; stańcie w hełmach, ostrzcie włócznie, przywdziejcie pancerze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 5, 'Czemu widzę ich zatrwożonych i cofających się? Ich mocarze są pobici i uciekają w popłochu, nie oglądając się. Strach jest wszędzie, mówi Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 6, 'Prędki nie ucieknie i mocarz nie ujdzie; na północy, nad brzegiem rzeki Eufrat, potkną się i upadną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 7, 'Kim jest ten, co się podnosi jak rzeka, a jego wody piętrzą się jak rzeki?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 8, 'Egipt podnosi się jak rzeka, a jego wody piętrzą się jak w rzece i mówi: Podnoszę się, pokryję ziemię, zniszczę miasto i jego mieszkańców.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 9, 'Nacierajcie, konie, pędźcie, rydwany; niech się ruszą mocarze: Etiopczycy i Libańczycy noszący tarcze, Ludyjczycy, którzy noszą i napinają łuk.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 10, 'Ten dzień bowiem należy do Pana Boga zastępów i jest dniem pomsty, aby się zemścił nad swoimi wrogami. Miecz będzie pożerał i nasyci się, i upije się ich krwią, gdyż Pan Bóg zastępów ma ofiarę w ziemi północnej, nad rzeką Eufrat.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 11, 'Wstąp do Gileadu i nabierz balsamu, dziewico, córko Egiptu. Ale daremnie używasz wielu lekarstw, bo nie będziesz uleczona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 12, 'Narody słyszały o twojej hańbie i twój lament napełnił ziemię, gdyż mocarz potknął się o mocarza i obaj razem upadli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 13, 'Słowo, które Pan wypowiedział do proroka Jeremiasza, o wyprawie Nabuchodonozora, króla Babilonu, aby uderzyć ziemię Egiptu:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 14, 'Oznajmijcie w Egipcie i ogłoście w Migdol; opowiadajcie w Nof i w Tachpanches. Powiedzcie: Stań i przygotuj się, bo miecz pożre to, co jest dokoła ciebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 15, 'Czemu twoi mocarze zostali powaleni? Nie mogli się ostać, gdyż natarł na nich Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 16, 'Wielu potknęło się, a padli jeden na drugiego. Mówili: Wstań, wróćmy do naszego ludu i do ziemi ojczystej przed ostrzem niszczycielskiego miecza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 17, 'Tam zawołali: Faraon, król Egiptu, to tylko próżny trzask; jego ustalony czas już minął.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 18, 'Jak żyję ja – mówi Król, a jego imię Pan zastępów – jak Tabor wśród gór i jak Karmel nad morzem, tak on przyjdzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 19, 'Córko, która mieszkasz w Egipcie, przygotuj swoje rzeczy na niewolę, bo Nof będzie pustkowiem i spustoszeniem, bez mieszkańców.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 20, 'Egipt jest jak piękna jałówka, ale jej zniszczenie nadchodzi, idzie z północy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 21, 'Najemnicy pośród niego są jak tuczone cielęta, bo oni także odwrócili się i uciekli razem. Nie ostali się, bo przyszedł na nich dzień ich porażki, czas ich nawiedzenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 22, 'Jego głos jak głos węża, bo nadciągną z wojskiem, z siekierami przyjdą przeciw niemu jak rąbiący drzewa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 23, 'Wyrąbią jego las, mówi Pan, choć nie da się go policzyć. Są bowiem liczniejsi od szarańczy i niezliczeni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 24, 'Zawstydzi się córka Egiptu, będzie wydana w ręce ludu z północy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 25, 'Pan zastępów, Bóg Izraela, mówi: Oto ukarzę cały liczny lud miasta No, także faraona i Egipt, jego bogów i królów, faraona i tych, którzy pokładają w nim ufność.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 26, 'I wydam ich w ręce tych, którzy czyhają na ich życie, w ręce Nabuchodonozora, króla Babilonu, i w ręce jego sług. Lecz potem będzie zamieszkały jak za dawnych dni, mówi Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 27, 'Ale ty się nie bój, mój sługo, Jakubie, i nie lękaj się, Izraelu. Oto bowiem wybawię cię z daleka i twoje potomstwo z ziemi jego niewoli. Jakub powróci i zazna odpoczynku i pokoju, a nikt go nie zatrwoży.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 28, 'Nie bój się, Jakubie, mój sługo, mówi Pan, bo ja jestem z tobą. Położę kres wszystkim narodom, do których cię wypędziłem. Tobie jednak nie położę kresu, ale będę cię karał sprawiedliwie; nie zostawię cię całkiem bez kary.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 1, 'Słowo Pana, które doszło do proroka Jeremiasza przeciw Filistynom, zanim faraon pobił Gazę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 2, 'Tak mówi Pan: Oto wody wznoszą się od północy i będą jak gwałtowna powódź, zatopią ziemię i wszystko, co na niej jest, miasto i jego mieszkańców. Wtedy ludzie będą wołać, zawyją wszyscy mieszkańcy ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 3, 'Na odgłos tętentu kopyt jego silnych koni, z powodu turkotu jego rydwanów i trzasku jego kół ojcowie nie obejrzą się na synów, gdyż zasłabną im ręce;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 4, 'Z powodu dnia, który nadchodzi, by zniszczyć wszystkich Filistynów i wytępić z Tyru i Sydonu każdą pozostałą pomoc. Pan bowiem zniszczy Filistynów, resztę z wyspy Kaftor.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 5, 'Przyszło na Gazę łysienie; wyniszczony został Aszkelon i resztki ich doliny. Jak długo będziesz czynić sobie nacięcia?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 6, 'Mieczu Pana, jak długo jeszcze nie spoczniesz? Wróć do swojej pochwy, powstrzymaj się i uspokój.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 7, 'Ale jakże ma się uspokoić, skoro Pan wydał mu rozkaz przeciwko Aszkelonowi i przeciwko brzegowi morskiemu? Tam go skierował.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 1, 'Przeciw Moabowi tak mówi Pan zastępów, Bóg Izraela: Biada miastu Nebo, bo jest spustoszone. Kiriataim jest pohańbione i zdobyte. Misgab jest zawstydzone i przerażone.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 2, 'Nie będzie już chwały dla Moabu, w Cheszbonie obmyślono przeciwko niemu nieszczęście: Chodźcie, wytępmy go spośród narodów. I ty, Madmenie, zostaniesz wykorzeniony, miecz będzie cię ścigał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 3, 'Głos krzyku z Choronaim, spustoszenie i wielkie zniszczenie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 4, 'Moab jest zmiażdżony, usłyszy się krzyk jego małych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 5, 'Będzie bowiem ciągły płacz przy wchodzeniu do Luchit, a przy schodzeniu do Choronaim wrogowie usłyszą krzyk nad zniszczeniem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 6, 'Uciekajcie, ratujcie swoje życie i bądźcie jak wrzos na pustyni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 7, 'Ponieważ pokładasz ufność w swoich dziełach i skarbach, ty też będziesz zdobyty. Kemosz pójdzie do niewoli wraz ze swoimi kapłanami i książętami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 8, 'Niszczyciel przyjdzie do każdego miasta i żadne miasto nie ocaleje. Dolina też zginie i równina będzie spustoszona, jak mówi Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 9, 'Dajcie skrzydła Moabowi, niech szybko uleci, bo jego miasta zostaną spustoszone, tak że nie będzie w nich mieszkańców.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 10, 'Przeklęty, kto wykonuje dzieło Pana podstępnie; przeklęty także, kto swój miecz powstrzymuje od krwi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 11, 'Moab miał pokój od swojej młodości, spoczywał na swoich drożdżach i nie był przelewany z naczynia do naczynia, nie poszedł do niewoli. Dlatego zachował się w nim jego smak i jego zapach się nie zmienił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 12, 'Dlatego oto nadchodzą dni, mówi Pan, że poślę na niego najeźdźców, którzy go uprowadzą, a opróżnią jego naczynia i potłuką jego dzbany.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 13, 'I Moab będzie się wstydzić Kemosza, jak dom Izraela wstydził się Betel, jego nadziei.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 14, 'Jakże możecie mówić: Jesteśmy mocnymi i dzielnymi wojownikami w walce?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 15, 'Moab jest zburzony i wyszedł ze swoich miast, a wyborni jego młodzieńcy pójdą na rzeź, mówi Król, jego imię to Pan zastępów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 16, 'Zbliża się klęska Moabu, jego nieszczęście nadchodzi spiesznie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 17, 'Opłakujcie go, wszyscy, jego sąsiedzi; wszyscy, którzy znacie jego imię, mówcie: Jakże się złamała mocna laska i berło ozdobne!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 18, 'Zejdź ze swej chwały i siądź w pragnieniu, córko, mieszkanko Dibonu! Bo niszczyciel Moabu nadciągnie przeciwko tobie, rozrzuci twoje twierdze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 19, 'Stań na drodze i przypatrz się uważnie, mieszkanko Aroeru! Spytaj tego, który ucieka, i tej, która uchodzi: Co się dzieje?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 20, 'Moab jest zawstydzony, bo jest rozgromiony; zawódźcie i krzyczcie, opowiadajcie w Arnon, że Moab jest spustoszony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 21, 'Sąd nadszedł na ziemię tej równiny, na Cholon, na Jahazę i na Mefaat;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 22, 'Na Dibon, na Nebo i na Bet-Dyblataim;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 23, 'Na Kiriataim, na Betgamul i na Bet-Meon.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 24, 'Na Keriot, na Bosrę i na wszystkie miasta ziemi Moabu, dalekie i bliskie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 25, 'Róg Moabu został odcięty i jego ramię złamane, mówi Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 26, 'Upójcie go, ponieważ wynosił się przeciw Panu. Niech Moab tarza się w swoich wymiocinach i niech również stanie się pośmiewiskiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 27, 'Czy Izrael nie był dla ciebie pośmiewiskiem? Czy złapano go wśród złodziei? Ilekroć bowiem mówisz o nim, skaczesz z radości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 28, 'Opuszczajcie miasta i zamieszkajcie na skale, mieszkańcy Moabu! Bądźcie jak gołębica, która się gnieździ na ścianach gardzieli urwiska.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 29, 'Słyszeliśmy o pysze Moabu, że jest niezmiernie pyszny, o jego zuchwałości, o jego zarozumiałości, o jego dumie i o wyniosłości jego serca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 30, 'Znam jego gniew, mówi Pan, lecz mu się nie poszczęści; jego kłamstwa nie dojdą do skutku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 31, 'Dlatego nad Moabem będę zawodził, nad całym Moabem będę wołał, i nad ludźmi z Kir-Cheres moje serce będzie wzdychało.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 32, 'Płaczę nad tobą, jak opłakiwano Jazer, winorośli Sibmy! Twoje latorośle sięgają aż za morze, dochodzą aż do morza Jazer. Na twoje letnie owoce i na twoje winobranie wpadł niszczyciel.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 33, 'I zniknęły wesele i radość z urodzajnych pól i z ziemi Moabu, i sprawiłem, że wino się skończyło z pras; nie będą go tłoczyć wśród okrzyków, a ich okrzyk nie będzie okrzykiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 34, 'Od krzyku Cheszbonu aż do Eleale i aż do Jahazy wydają swój głos, z Soaru aż do Choronaim, jak trzyletnia jałówka; bo wody Nimrim też staną się spustoszeniem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 35, 'I sprawię, mówi Pan, że już nie będzie w Moabie nikogo, kto składa ofiarę na wyżynach lub pali kadzidło swoim bogom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 36, 'Dlatego moje serce będzie jęczeć nad Moabem jak flet; nad ludźmi z Kir-Cheres moje serce zawodzi jak flet, gdyż ich zgromadzony dobytek wniwecz się obrócił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 37, 'Na każdej bowiem głowie będzie łysina i każda broda zostanie ogolona. Na wszystkich rękach będą nacięcia i na biodrach wory.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 38, 'Na wszystkich dachach Moabu i na jego ulicach tylko powszechny lament, bo rozbiłem Moab jak naczynie nieużyteczne, mówi Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 39, 'Będą zawodzić, mówiąc: Jakże jest rozbity! Jak haniebnie uciekł Moab! Moab będzie pośmiewiskiem i postrachem dla wszystkich, którzy są dokoła niego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 40, 'Tak bowiem mówi Pan: Oto wróg jak orzeł przyleci i rozciągnie swe skrzydła nad Moabem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 41, 'Keriot jest zdobyty i twierdze są wzięte, a serce mocarzy Moabu w tym dniu będzie jak serce rodzącej kobiety.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 42, 'Moab zostanie zniszczony, przestanie być ludem, bo wynosił się przeciwko Panu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 43, 'Strach, dół i sidło nad tobą, który mieszkasz w Moabie, mówi Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 44, 'Kto ucieknie przed strachem, wpadnie w dół, a kto wyjdzie z dołu, wpadnie w sidła. Sprowadzę bowiem na niego, na Moab, rok jego nawiedzenia, mówi Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 45, 'W cieniu Cheszbonu zatrzymali się ci, którzy uciekali przed przemocą. Ale ogień wyjdzie z Cheszbonu i płomień ze środka Sichona i pożre krańce Moabu, i czaszkę tych, którzy czynią zgiełk.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 46, 'Biada tobie, Moabie! Ginie lud Kemosza, bo twoi synowie zostali zabrani do niewoli i twoje córki – na wygnanie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 47, 'Odwrócę jednak niewolę Moabu w dniach ostatecznych, mówi Pan. Dotąd sąd nad Moabem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 1, 'O Ammonitach tak mówi Pan: Czyż Izrael nie ma synów? Czyż nie ma żadnego dziedzica? Czemu ich król dziedzicznie opanował Gad, a jego lud mieszka w jego miastach?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 2, 'Dlatego oto nadchodzą dni, mówi Pan, gdy sprawię, że usłyszą okrzyk wojenny w Rabbie synów Ammona i stanie się ona rumowiskiem, a inne jej miasta będą spalone ogniem. Wtedy Izrael posiądzie swoich dzierżawców, mówi Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 3, 'Zawódź, Cheszbonie, bo Aj jest spustoszone. Krzyczcie, córki Rabby, przepaszcie się worami, lamentujcie i biegajcie wśród płotów, bo wasz król pójdzie do niewoli wraz ze swoimi kapłanami i książętami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 4, 'Czemu się chlubisz dolinami? Twoja dolina spłynęła, córko buntownicza, która ufasz swym skarbom, mówiąc: Któż nadciągnie przeciwko mnie?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 5, 'Oto sprowadzę na ciebie strach, mówi Pan Bóg zastępów, od wszystkich, którzy są dokoła ciebie; będziecie wygnani każdy osobno, a nikt nie pozbiera tułaczy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 6, 'Potem jednak odwrócę niewolę synów Ammona, mówi Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 7, 'O Edomie tak mówi Pan zastępów: Czyż nie ma już mądrości w Temanie? Czyż zginęła rada od roztropnych i obróciła się wniwecz ich mądrość?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 8, 'Uciekajcie, zawracajcie, ukryjcie się w głębokich kryjówkach, mieszkańcy Dedanu, bo sprowadzę na niego klęskę Ezawa, w czasie gdy go nawiedzę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 9, 'Gdyby zbieracze przyszli do ciebie, czy nie zostawiliby jakichś winogron? Gdyby się wkradli złodzieje w nocy, szkodziliby dotąd, aż mieliby dość.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 10, 'Lecz ja obnażę Ezawa, odkryję jego kryjówki, tak że nie będzie mógł się ukryć. Zniszczone jest jego potomstwo, jego bracia i jego sąsiedzi, i nie będzie go.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 11, 'Zostaw swoje sieroty, ja będę je żywić, a twoje wdowy niech mi zaufają.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 12, 'Tak bowiem mówi Pan: Oto ci, którzy nie byli skazani na picie z tego kielicha, musieli pić z niego, a ty miałbyś ujść z tego bezkarnie? Nie ujdziesz, ale na pewno będziesz pił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 13, 'Przysięgam bowiem na siebie samego, mówi Pan, że Bosra stanie się spustoszeniem, hańbą, ruiną i przekleństwem, a wszystkie jej miasta będą ruiną na wieki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 14, 'Usłyszałem wieść od Pana, że do narodów wysłany jest poseł mówiący: Zgromadźcie się, wyruszcie przeciw niej, powstańcie do bitwy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 15, 'Oto bowiem sprawię, że będziesz mały wśród narodów i wzgardzony między ludźmi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 16, 'Zdradziła cię twoja zuchwałość i pycha twego serca, ty, który mieszkasz w rozpadlinach skalnych, który trzymasz się wysokich pagórków. Choćbyś założył swoje gniazdo wysoko jak orzeł, nawet stamtąd cię strącę, mówi Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 17, 'Edom będzie spustoszeniem, ktokolwiek będzie przechodził obok niego, zdumieje się i będzie świstać nad wszystkimi jego plagami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 18, 'Jak po zniszczeniu Sodomy i Gomory oraz miast sąsiednich, mówi Pan, nikt tam nie zamieszka i żaden syn człowieka nie będzie w nim gościł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 19, 'Oto jak lew wystąpi z wezbrania Jordanu przeciwko przybytkowi mocarza. Wypędzę go jednak nagle z tej ziemi, a ustanowię nad nią mojego wybrańca. Któż bowiem jest mi równy? Kto wyznaczy mi termin rozprawy? A kto jest tym pasterzem, który się ostoi przede mną?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 20, 'Dlatego słuchajcie postanowienia Pana, które powziął przeciwko Edomowi, i jego zamysłów, które przygotował przeciwko mieszkańcom Temanu: Zaprawdę, wywloką ich najmniejsi z tej trzody, spustoszą ich i ich mieszkania.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 21, 'Od grzmotu ich upadku ziemia się porusza, głos ich krzyku słychać nad Morzem Czerwonym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 22, 'Oto jak orzeł wzbije się i przyleci, i rozciągnie swoje skrzydła nad Bosrą. W tym dniu serce mocarzy Edomu stanie się jak serce rodzącej kobiety.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 23, 'O Damaszku. Wstydzą się Chamat i Arpad, bo usłyszały złą wieść. Zatrwożyły się tak, że nawet morze się wzruszy, a nie będzie mogło się uspokoić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 24, 'Osłabł Damaszek i rzuca się do ucieczki, strach go ogarnął. Udręka i bóle ogarnęły go jak rodzącą kobietę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 25, 'Ale powiedzą: Jakże się nie miało ostać miasto sławne, miasto mej radości?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 26, 'Dlatego jego młodzieńcy upadną na jego ulicach, a wszyscy waleczni wojownicy w tym dniu zostaną wytraceni, mówi Pan zastępów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 27, 'I wzniecę ogień w murze Damaszku, który strawi pałace Ben-Hadada.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 28, 'O Kedarze i królestwach Chasoru, które ma pobić Nabuchodonozor, król Babilonu, tak mówi Pan: Wstańcie, wyruszajcie na Kedar i spustoszcie narody wschodnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 29, 'Zabiorą ich namioty i trzody, wezmą ze sobą ich zasłony, wszystkie ich sprzęty oraz ich wielbłądy. I zawołają na nich: Strach dokoła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 30, 'Uciekajcie, rozbiegnijcie się prędko, ukryjcie się w głębokich kryjówkach, mieszkańcy Chasoru, mówi Pan. Radził się bowiem przeciwko wam Nabuchodonozor, król Babilonu, i obmyślił przeciwko wam zdradę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 31, 'Wstańcie, ruszajcie na naród spokojny, mieszkający bezpiecznie, mówi Pan, nie ma ani wrót, ani rygli, mieszka samotnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 32, 'Ich wielbłądy będą łupem, a liczne ich stada – zdobyczą. Rozproszę na wszystkie wiatry tych, którzy mieszkają w najdalszych zakątkach, i sprowadzę na nich klęskę ze wszystkich stron, mówi Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 33, 'Chasor stanie się siedliskiem smoków, pustkowiem na wieki. Nikt tam nie zamieszka i żaden syn człowieka nie będzie w nim gościł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 34, 'Słowo Pana, które doszło do proroka Jeremiasza przeciwko Elamowi na początku królowania Sedekiasza, króla Judy, mówiące:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 35, 'Tak mówi Pan zastępów: Oto złamię łuk Elamu, podstawę jego potęgi;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 36, 'I sprowadzę na Elam cztery wiatry z czterech stron świata, i rozproszę go na wszystkie te wiatry tak, że nie będzie narodu, do którego by nie przyszli wygnańcy Elamu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 37, 'I napełnię Elam trwogą przed jego wrogami i przed tymi, którzy czyhają na jego życie. Sprowadzę na nich nieszczęście, zapalczywość mego gniewu, mówi Pan, i poślę też za nimi miecz, aż ich wyniszczę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 38, 'I ustawię swój tron w Elamie i stamtąd wytępię króla i książąt, mówi Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 39, 'Stanie się jednak w ostatecznych dniach, że odwrócę niewolę Elamu, mówi Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 1, 'Słowo, które Pan wypowiedział przeciwko Babilonowi i przeciwko ziemi Chaldejczyków przez proroka Jeremiasza:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 2, 'Opowiadajcie wśród narodów, rozgłaszajcie, podnieście sztandar, głoście i nie zatajajcie. Mówcie: Babilon wzięty, Bel pohańbiony, Merodach rozbity; jego posągi pohańbione, jego bożki pokruszone.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 3, 'Nadciągnie bowiem przeciwko niemu naród z północy, który zamieni jego ziemię w pustkowie, tak że nikt w niej nie zamieszka. Uciekną i odejdą zarówno ludzie, jak i zwierzęta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 4, 'W tych dniach i w tym czasie, mówi Pan, przyjdą synowie Izraela, a wraz z nimi synowie Judy; będą szli w płaczu i będą szukać Pana, swego Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 5, 'Będą pytać o drogę na Syjon i zwróciwszy tam swoje twarze, powiedzą: Chodźcie i przyłączmy się do Pana wiecznym przymierzem, które nie ulegnie zapomnieniu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 6, 'Mój lud był trzodą owiec zbłąkanych, ich pasterze wiedli ich na manowce, po górach ich rozegnali. Schodził z góry na pagórek, zapomniał o swoim legowisku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 7, 'Wszyscy, którzy ich spotykali, pożerali ich, a ich wrogowie mówią: Nie jesteśmy nic winni, bo to oni zgrzeszyli przeciwko Panu, przybytkowi sprawiedliwości, przeciwko Panu, nadziei ich ojców.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 8, 'Uchodźcie ze środka Babilonu, wychodźcie z ziemi Chaldejczyków i bądźcie jak kozły przed trzodą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 9, 'Oto bowiem wzbudzę i sprowadzę na Babilon gromadę wielkich narodów z ziemi północnej. I uszykują się przeciwko niemu, i stamtąd będzie zdobyty. Ich strzały będą jak u wprawnego mocarza, żadna nie wróci bez skutku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 10, 'Chaldea będzie łupem, a wszyscy, którzy ją złupią, zostaną nasyceni, mówi Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 11, 'Ponieważ się cieszyliście, ponieważ się radowaliście, grabieżcy mego dziedzictwa; ponieważ utyliście jak jałówka na trawie i ryczycie jak wół;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 12, 'Wasza matka będzie bardzo zawstydzona, spłonie ze wstydu wasza rodzicielka. Oto stanie się ostatnią z narodów, pustkowiem, ziemią suchą i pustynną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 13, 'Z powodu gniewu Pana nie będzie zamieszkana, ale cała zostanie spustoszona. Ktokolwiek będzie przechodził obok Babilonu, zdumieje się i będzie świstał nad wszystkimi jego plagami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 14, 'Ustawcie się przeciw Babilonowi w koło. Wszyscy, którzy napinacie łuk, strzelajcie do niego, nie żałujcie strzał, bo zgrzeszył przeciwko Panu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 15, 'Wołajcie przeciwko niemu zewsząd. Poddał się, upadły jego fundamenty, jego mury są zburzone. Jest to bowiem zemsta Pana. Pomścijcie się nad nim; jak on czynił innym, tak jemu też uczyńcie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 16, 'Wyniszczcie z Babilonu siewcę i tego, który chwyta sierp w czasie żniwa. Przed mieczem niszczycielskim każdy się zwróci do swego ludu i każdy ucieknie do swojej ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 17, 'Izrael jest owcą przegnaną, którą spłoszyły lwy. Najpierw król Asyrii pożarł go, a na koniec ten Nabuchodonozor, król Babilonu, pokruszył jego kości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 18, 'Dlatego tak mówi Pan zastępów, Bóg Izraela: Oto ukarzę króla Babilonu i jego ziemię, jak ukarałem króla Asyrii.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 19, 'I znowu przyprowadzę Izraela do swego mieszkania, i będzie się paść na Karmelu i w Baszanie, i jego dusza nasyci się na górze Efraim i w Gileadzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 20, 'W tych dniach i w tym czasie, mówi Pan, będą szukać nieprawości Izraela, ale jej nie będzie, i grzechów Judy, ale nie będą znalezione. Przebaczę bowiem tym, których pozostawię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 21, 'Wyrusz przeciwko ziemi Meratajim, przeciwko niej i mieszkańcom Pekod. Spustosz i zniszcz doszczętnie, goniąc ich, mówi Pan, i uczyń wszystko, jak ci rozkazałem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 22, 'Wrzawa wojenna w tej ziemi i wielkie spustoszenie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 23, 'Jakże jest rozbity i złamany młot całej ziemi? Jakże Babilon stał się spustoszeniem wśród narodów?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 24, 'Zastawiłem na ciebie sidła i zostałeś schwytany, Babilonie, a nie zauważyłeś tego. Znaleziono cię i pochwycono, ponieważ spierałeś się z Panem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 25, 'Pan otworzył swoją zbrojownię i wyniósł oręż swego gniewu. To bowiem jest dzieło Pana Boga zastępów w ziemi Chaldejczyków.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 26, 'Ruszajcie przeciwko niemu z krańców ziemi, otwórzcie jego spichlerze. Zbierzcie go w sterty i zniszczcie go doszczętnie, by nic z niego nie pozostało.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 27, 'Pozabijajcie wszystkie jego cielce, niech idą na rzeź. Biada im, bo nadszedł ich dzień, czas ich nawiedzenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 28, 'Słychać głos uciekających i tych, co uchodzą z ziemi Babilonu, aby ogłosić na Syjonie pomstę Pana, naszego Boga, pomstę za jego świątynię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 29, 'Zgromadźcie przeciwko Babilonowi wszystkich strzelców, którzy napinają łuk; rozbijcie obóz przeciw niemu dokoła, aby nikt nie uszedł. Odpłaćcie mu według jego uczynków, według wszystkiego, co innym czynił, uczyńcie mu. Wynosił się bowiem przeciwko Panu, przeciwko Świętemu Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 30, 'Dlatego jego młodzieńcy polegną na ulicach i wszyscy jego wojownicy zostaną zgładzeni w tym dniu, mówi Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 31, 'Oto jestem przeciwko tobie, zuchwalcze, mówi Pan, Bóg zastępów. Nadszedł bowiem twój dzień i czas, gdy cię nawiedzę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 32, 'Potknie się zuchwalec i upadnie, i nikt go nie podniesie. Wzniecę ogień w jego miastach, który pochłonie wszystko wokół niego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 33, 'Tak mówi Pan zastępów: Synowie Izraela i synowie Judy razem cierpią ucisk. Wszyscy, którzy ich pojmali, trzymają ich i nie chcą ich wypuścić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 34, 'Ale ich Odkupiciel jest potężny, jego imię to Pan zastępów, skutecznie będzie bronił ich sprawy, aby zapewnić pokój tej ziemi i trwożyć mieszkańców Babilonu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 35, 'Miecz spadnie na Chaldejczyków, mówi Pan, i na mieszkańców Babilonu, na jego książąt i mędrców;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 36, 'Miecz na kłamców, aby zgłupieli, miecz na jego wojowników, aby byli przerażeni;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 37, 'Miecz na jego konie i rydwany oraz na całą różnorodną ludność, która jest pośród niego, aby była jak kobiety; miecz na jego skarby, aby były zagrabione;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 38, 'Susza na jego wody, aby wyschły. Ziemia bowiem jest pełna rzeźbionych obrazów, a szaleją przy swoich bożkach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 39, 'Dlatego zamieszkają tam dzikie zwierzęta pustyni i straszne bestie wysp, zamieszkają w nim też młode sowy. Nie będzie już zaludniony na wieki i nie będą w nim mieszkać po wszystkie pokolenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 40, 'Jak Bóg zniszczył Sodomę i Gomorę oraz sąsiednie miasta, mówi Pan, tak też nikt tam nie zamieszka ani syn człowieczy nie będzie w nim gościł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 41, 'Oto lud nadciągnie z północy, naród wielki, i liczni królowie zostaną wzbudzeni z krańców ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 42, 'Pochwycą łuk i włócznię, są okrutni i bezlitośni; ich głos huczy jak morze i jeżdżą na koniach, każdy uszykowany do walki przeciwko tobie, córko Babilonu!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 43, 'Król Babilonu usłyszał o nich wieść i osłabły mu ręce. Ogarnęła go udręka i bóle jak rodzącą kobietę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 44, 'Oto jak lew wystąpi z wezbrania Jordanu przeciwko przybytkowi mocarza. Wypędzę go jednak nagle z tej ziemi, a ustanowię nad nią mojego wybrańca. Któż bowiem jest mi równy? Kto wyznaczy mi termin rozprawy? A kto jest tym pasterzem, który się ostoi przede mną?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 45, 'Dlatego słuchajcie postanowienia Pana, które powziął przeciwko Babilonowi i jego zamysłów, które przygotował przeciwko ziemi Chaldejczyków. Zaprawdę, wywloką ich najmniejsi z tej trzody, spustoszą ich i ich mieszkania.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 46, 'Od huku przy zdobyciu Babilonu ziemia się porusza, słychać krzyk wśród narodów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 1, 'Tak mówi Pan: Oto wzbudzę niszczący wiatr przeciwko Babilonowi i przeciwko tym, którzy mieszkają pośród powstających przeciwko mnie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 2, 'I poślę do Babilonu obcych, którzy będą go przewiewać, i opróżnią jego ziemię, gdyż zewsząd zwrócą się przeciwko niemu w dniu ucisku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 3, 'Niech łucznik napina swój łuk przeciwko niemu i przeciwko stającym do walki w swoich pancerzach. Nie oszczędzajcie jego młodzieńców, zgładźcie całe jego wojsko.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 4, 'Tak padną zabici w ziemi Chaldejczyków i przebici na jego ulicach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 5, 'Nie są bowiem opuszczone Izrael ani Juda przez swego Boga, Pana zastępów, choć ich ziemia była pełna grzechu przeciwko Świętemu Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 6, 'Uciekajcie ze środka Babilonu i niech każdy ratuje swoją duszę. Nie gińcie w jego nieprawości, bo jest to czas zemsty Pana, on oddaje mu zapłatę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 7, 'Babilon był złotym kielichem w ręce Pana, upajającym całą ziemię. Z jego wina piły narody, dlatego narody szaleją.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 8, 'Nagle upadł Babilon i został rozbity. Zawódźcie nad nim, weźcie balsam na jego ból, może da się go wyleczyć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 9, 'Leczyliśmy Babilon, ale nie został uleczony. Opuśćmy go i niech każdy pójdzie do swojej ziemi, bo jego sąd aż do nieba sięga i wznosi się aż po obłoki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 10, 'Pan ujawnił naszą sprawiedliwość. Chodźcie, głośmy na Syjonie dzieło Pana, naszego Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 11, 'Wyostrzcie strzały, przygotujcie tarcze. Pan wzbudził ducha królów Medii, bo jego zamiar jest przeciwko Babilonowi, aby go zniszczyć. Jest to bowiem pomsta Pana, pomsta za jego świątynię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 12, 'Podnieście sztandar na murach Babilonu, wzmocnijcie straże, postawcie stróżów, przygotujcie zasadzki. Pan bowiem obmyślił i wykonał to, co wypowiedział przeciwko mieszkańcom Babilonu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 13, 'Ty, który mieszkasz nad wieloma wodami, bogaty w skarby! Nadszedł twój koniec, kres twojej chciwości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 14, 'Pan zastępów przysiągł na siebie samego: Zaprawdę, napełnię cię ludźmi jak szarańczą, wzniosą nad tobą okrzyk wojenny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 15, 'On uczynił ziemię swoją mocą, utwierdził świat swoją mądrością i rozpostarł niebiosa swoją roztropnością.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 16, 'Gdy on wydaje głos, huczą wody w niebiosach, on sprawia, że chmury wznoszą się z krańców ziemi. I czyni błyskawice z deszczem, a wywodzi wiatr ze swoich skarbców.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 17, 'Głupi jest każdy człowiek, kto tego nie zna, każdy złotnik jest zawstydzony z powodu posągu, bo jego odlany posąg jest fałszem i nie ma w nich ducha.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 18, 'Są marnością i dziełem błędów; zginą w czasie swego nawiedzenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 19, 'Nie takim jak one jest dział Jakuba, bo on jest Stwórcą wszystkiego, a Izrael jest szczepem jego dziedzictwa. Pan zastępów – to jego imię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 20, 'Jesteś moim młotem i orężem wojennym. Tobą zmiażdżę narody, tobą zniszczę królestwa;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 21, 'Tobą zmiażdżę konia i jeźdźca, tobą zmiażdżę rydwan i jego woźnicę;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 22, 'Tobą zmiażdżę mężczyznę i kobietę, tobą zmiażdżę starca i dziecko, tobą zmiażdżę młodzieńca i pannę;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 23, 'Tobą zmiażdżę pasterza i jego trzodę, tobą zmiażdżę oracza i jego zaprzęg, tobą zmiażdżę dowódców i rządców.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 24, 'Ale odpłacę Babilonowi i wszystkim mieszkańcom Chaldei za całe ich zło, które czynili na Syjonie na waszych oczach, mówi Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 25, 'Oto jestem przeciwko tobie, góro niszczycielska, mówi Pan, która niszczysz całą ziemię. Wyciągnę swoją rękę przeciwko tobie i strącę cię ze skał, i uczynię cię górą wypaloną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 26, 'A nie wezmą z ciebie kamienia węgielnego ani kamienia na fundamenty, bo staniesz się wiecznym pustkowiem, mówi Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 27, 'Podnieście sztandar w ziemi, zadmijcie w trąbę wśród narodów, przygotujcie przeciwko niemu narody, zwołajcie przeciwko niemu królestwa Ararat, Minni i Aszkenaz; ustanówcie przeciwko niemu dowódcę, sprowadźcie konie jak najeżone szarańcze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 28, 'Przygotujcie przeciwko niemu narody, królów Medii, ich dowódców i wszystkich ich rządców, oraz całą ziemię pod ich władzą;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 29, 'Wtedy ziemia zadrży i będzie w bólach, gdyż spełnią się przeciwko Babilonowi zamiary Pana, aby zamienić ziemię Babilonu w pustkowie, bez mieszkańców.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 30, 'Mocarze Babilonu przestali walczyć, siedzą w warowniach, osłabło ich męstwo, stali się jak kobiety. Spalono jego mieszkania, wyłamano jego rygle.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 31, 'Goniec wybiegnie na spotkanie gońca, posłaniec – na spotkanie posłańca, aby opowiedzieć królowi Babilonu, że wzięto jego miasto z jednej strony;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 32, 'Że brody są zajęte, sitowia spalone ogniem, a wojownicy przerażeni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 33, 'Tak bowiem mówi Pan zastępów, Bóg Izraela: Córka Babilonu jest jak klepisko, nadszedł czas, gdy się je udeptuje; jeszcze chwila, a przyjdzie czas jej żniwa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 34, 'Pożarł mnie i zmiażdżył Nabuchodonozor, król Babilonu, uczynił mnie pustym naczyniem, połknął mnie jak smok, napełnił swój brzuch moimi rozkoszami i wypędził mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 35, 'Krzywda zadana mi i memu ciału niech spadnie na Babilon, powie mieszkanka Syjonu, a moja krew – na mieszkańców Chaldei, powie Jerozolima.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 36, 'Dlatego tak mówi Pan: Oto będę bronił twojej sprawy i pomszczę cię; wysuszę jego morze i sprawię, że wyschną jego źródła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 37, 'I Babilon stanie się rumowiskiem, legowiskiem smoków, zdumieniem i świstaniem, pozbawionym mieszkańców.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 38, 'Będą ryczeć razem jak lwy, warczeć jak lwie szczenięta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 39, 'Gdy się rozpalą, uczynię im ucztę i upoję ich tak, aby weselili się i zasnęli wiecznym snem, by już się nie obudzili, mówi Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 40, 'Sprowadzę ich jak baranki na rzeź, jak barany wraz z kozłami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 41, 'Jakże został zdobyty Szeszak! Jakże została wzięta chwała całej ziemi! Jakże Babilon stał się spustoszeniem wśród narodów!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 42, 'Wystąpiło morze przeciwko Babilonowi, został przykryty mnóstwem jego fal.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 43, 'Jego miasta stały się spustoszeniem, ziemią suchą i pustynną, ziemią, w której nikt nie mieszka, i przez którą nie przechodzi żaden syn człowieczy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 44, 'Nawiedzę też Bela w Babilonie i wyrwę mu z paszczy to, co pochłonął. Narody już nie będą napływać do niego; upadnie też mur Babilonu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 45, 'Wyjdźcie spośród niego, mój ludu, i niech każdy ratuje swoją duszę przed zapalczywością gniewu Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 46, 'A niech wasze serce nie omdlewa ani się nie lękajcie wieści, którą będzie słychać w tej ziemi, gdy przyjdzie jednego roku wieść, potem drugiego roku wieść, ucisk w ziemi, władca przeciwko władcy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 47, 'Dlatego oto nadchodzą dni, gdy nawiedzę rzeźbione obrazy Babilonu. Cała jego ziemia zostanie pohańbiona i wszyscy jego zabici padną pośród niego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 48, 'Wtedy niebo, ziemia i wszystko, co w nich jest, będą śpiewać nad Babilonem. Z północy bowiem przyjdą na niego niszczyciele, mówi Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 49, 'Jak przez Babilon padli zabici Izraela, tak w Babilonie padną zabici całej ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 50, 'Wy, którzy uszliście spod miecza, idźcie, nie zatrzymujcie się! Wspominajcie Pana z daleka i niech przyjdzie wam na myśl Jerozolima.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 51, 'Powiedzcie: Wstydzimy się, że słyszymy zniewagi, hańba okryła nasze twarze. Weszli bowiem cudzoziemcy do świętych miejsc domu Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 52, 'Dlatego oto nadchodzą dni, mówi Pan, że nawiedzę jego rzeźbione obrazy, a po całej jego ziemi będą jęczeć jego zranieni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 53, 'Choćby Babilon wstąpił do nieba i obwarował szczyty swojej potęgi, mimo to wyjdą ode mnie jego niszczyciele, mówi Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 54, 'Słychać głos krzyku z Babilonu i wielkie zniszczenie z ziemi Chaldejczyków;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 55, 'Bo Pan pustoszy Babilon i wytraci z niego wielki głos, choćby ich fale huczały jak wielkie wody i rozlegał się szum ich głosu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 56, 'Niszczyciel bowiem nadciąga na niego, na Babilon, i jego mocarze zostaną pojmani, ich łuki będą połamane. Pan bowiem, Bóg odpłaty, odpłaci im niezawodnie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 57, 'Upiję jego książąt i mędrców, jego dowódców i rządców oraz jego mocarzy, aby zasnęli wiecznym snem i już się nie obudzili, mówi Król, Pan zastępów to jego imię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 58, 'Tak mówi Pan zastępów: Szerokie mury Babilonu będą doszczętnie zniszczone i jego wysokie bramy zostaną spalone ogniem; ludzie będą trudzić się na darmo i narody – przy ogniu, a osłabną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 59, 'Słowo, które prorok Jeremiasz polecił Serajaszowi, synowi Neriasza, syna Machsejasza, gdy ten udał się z Sedekiaszem, królem Judy, do Babilonu, w czwartym roku jego królowania. A Serajasz był spokojnym księciem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 60, 'Jeremiasz więc spisał w jednej księdze całe nieszczęście, które miało spaść na Babilon, wszystkie słowa, które zostały napisane przeciwko Babilonowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 61, 'I Jeremiasz powiedział do Serajasza: Gdy przybędziesz do Babilonu i zobaczysz go, i przeczytasz wszystkie te słowa;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 62, 'Powiesz: Panie, ty mówiłeś przeciwko temu miejscu, że je wyniszczysz, aby nikt w nim nie mieszkał, ani człowiek, ani zwierzę, ale żeby było wiecznym pustkowiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 63, 'A gdy dokończysz czytanie tej księgi, przywiążesz do niej kamień i wrzucisz ją w środek Eufratu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 64, 'I powiesz: Tak utonie Babilon i już nie powstanie z tego nieszczęścia, które na niego sprowadzę, i osłabną. Dotąd słowa Jeremiasza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 1, 'Sedekiasz miał dwadzieścia jeden lat, kiedy zaczął królować, i królował jedenaście lat w Jerozolimie. Jego matka miała na imię Chamutal i była córką Jeremiasza z Libny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 2, 'Czynił on to, co złe w oczach Pana, zupełnie tak, jak czynił Joakim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 3, 'Z powodu gniewu Pana przyszło to na Jerozolimę i Judę, aż odrzucił ich sprzed swego oblicza. Sedekiasz bowiem zbuntował się przeciw królowi Babilonu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 4, 'W dziewiątym roku jego panowania, dziesiątego miesiąca, dziesiątego dnia tego miesiąca Nabuchodonozor, król Babilonu, wraz z całym swym wojskiem wyruszył przeciw Jerozolimie, rozbił obóz pod nią i zbudował przeciwko niej szańce dokoła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 5, 'Miasto więc było oblężone aż do jedenastego roku króla Sedekiasza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 6, 'A w czwartym miesiącu, dziewiątego dnia tego miesiąca, wzmógł się głód w mieście i nie było chleba dla ludu tej ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 7, 'Kiedy zrobiono wyłom w murze miasta, wszyscy wojownicy uciekli i wyszli z miasta w nocy przez bramę między dwoma murami obok królewskiego ogrodu; Chaldejczycy zaś leżeli wokół miasta, a tamci poszli w stronę pustyni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 8, 'Lecz wojsko Chaldejczyków ścigało króla i dogoniło Sedekiasza na równinach Jerycha, a całe jego wojsko rozpierzchło się od niego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 9, 'Pojmali więc króla i przyprowadzili go do króla Babilonu, do Ribla w ziemi Chamat, gdzie ten wydał na niego wyrok.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 10, 'Król Babilonu zabił synów Sedekiasza na jego oczach, a także wszystkich książąt Judy pozabijał w Ribla.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 11, 'A Sedekiaszowi wyłupił oczy, potem król Babilonu zakuł go w łańcuchy, uprowadził go do Babilonu i wsadził do więzienia aż do jego śmierci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 12, 'W piątym miesiącu, dziesiątego dnia tego miesiąca – był to dziewiętnasty rok Nabuchodonozora, króla Babilonu – do Jerozolimy przybył Nebuzaradan, dowódca gwardii, sługa króla Babilonu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 13, 'I spalił dom Pana i dom króla; wszystkie domy Jerozolimy i wszystkie wielkie budowle spalił ogniem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 14, 'Całe wojsko Chaldejczyków, które było z dowódcą gwardii, zburzyło wszystkie mury wokół Jerozolimy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 15, 'A część ubogich z ludu i resztę ludu, która pozostała w mieście, zbiegów, którzy przeszli do króla Babilonu, oraz resztę pospólstwa Nebuzaradan, dowódca gwardii, uprowadził do niewoli;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 16, 'Lecz pozostawił niektórych z ubogich tej ziemi, aby byli winogrodnikami i rolnikami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 17, 'Chaldejczycy rozbili kolumny z brązu, które były w domu Pana, podstawy i morze z brązu, które było w domu Pana, a brąz z nich przenieśli do Babilonu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 18, 'Zabrali też kotły, szufle, nożyce, miski, czasze oraz wszystkie naczynia z brązu, których używano do służby.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 19, 'Dowódca gwardii zabrał kropielnice, kadzielnice, misy, kotły, świeczniki, czasze i kubki; co było ze złota – jako złoto, co było ze srebra – jako srebro;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 20, 'Dwie kolumny, jedno morze i dwanaście wołów z brązu, które były pod podstawami, a które wykonał król Salomon w domu Pana; a nie było można zmierzyć wagi brązu tych wszystkich przedmiotów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 21, 'Co do kolumn, to każda miała osiemnaście łokci wysokości i dwanaście łokci obwodu, jej grubość wynosiła cztery palce, a w środku była pusta;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 22, 'Głowica na niej była z brązu, wysokość jednej głowicy wynosiła pięć łokci, naokoło głowicy była siatka i jabłka granatowe, wszystko z brązu. Tak samo było z jabłkami granatu drugiej kolumny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 23, 'A tych jabłek granatu było dziewięćdziesiąt sześć po każdej stronie; wszystkich jabłek granatu było po sto na siatce wokoło.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 24, 'Dowódca gwardii pojmał też najwyższego kapłana Serajasza, drugiego kapłana Sofoniasza i trzech stróżów progu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 25, 'Z miasta zaś zabrał dworzanina, który był przełożonym nad wojownikami, siedmiu z tych, którzy stawali przed królem, a których znaleziono w mieście, naczelnego pisarza wojskowego, dokonującego spisu ludu tej ziemi, oraz sześćdziesięciu mężczyzn spośród ludu tej ziemi, których znaleziono w mieście.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 26, 'Tych więc zabrał Nebuzaradan, dowódca gwardii, i zaprowadził ich do króla Babilonu do Ribla.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 27, 'I król Babilonu pobił ich, i uśmiercił w Ribla, w ziemi Chamat. Tak został uprowadzony Juda ze swojej ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 28, 'Taka jest liczba ludu, który Nabuchodonozor uprowadził do niewoli: w siódmym roku trzy tysiące dwudziestu trzech Żydów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 29, 'W osiemnastym roku Nabuchodonozora, uprowadził z Jerozolimy osiemset trzydzieści dwie osoby.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 30, 'W dwudziestym trzecim roku Nabuchodonozora dowódca gwardii Nebuzaradan uprowadził spośród Żydów siedemset czterdzieści pięć osób. Razem cztery tysiące sześćset osób.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 31, 'A w trzydziestym siódmym roku po uprowadzeniu do niewoli Joachina, króla Judy, w dwunastym miesiącu, dwudziestego piątego dnia tego miesiąca, Ewil-Merodak, król Babilonu, w roku objęcia królestwa, wywyższył głowę Joachina, króla Judy, i uwolnił go z więzienia;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 32, 'Rozmawiał z nim łaskawie i ustawił jego tron wyżej niż tron królów, którzy byli z nim w Babilonie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 33, 'I zmienił jego szaty więzienne. I jadał on chleb zawsze przed nim po wszystkie dni swego życia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 34, 'Na jego utrzymanie zapewniono mu dzienną porcję przez króla Babilonu aż do jego śmierci, po wszystkie dni jego życia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 1, 'Ach, jak samotnie siedzi miasto niegdyś tak pełne ludzi! Stało się jak wdowa! Niegdyś wielka wśród narodów i księżniczka wśród prowincji, teraz stała się podwładną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 2, 'Nieustannie płacze w nocy, a na jej policzkach łzy. Nie ma nikogo, kto by ją pocieszył pośród wszystkich jej kochanków. Wszyscy jej przyjaciele zdradzili ją i stali się jej wrogami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 3, 'Juda poszedł na wygnanie z powodu ucisku i wielkiej niewoli, mieszka między poganami i nie znajduje odpoczynku. Wszyscy jego prześladowcy dopadli go pośród ucisków.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 4, 'Drogi Syjonu płaczą, bo nikt nie przychodzi na uroczyste święta. Wszystkie jego bramy opustoszały, jego kapłani wzdychają, jego dziewice są smutne, a on sam jest pełny goryczy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 5, 'Jego wrogowie są zwierzchnikami, jego przeciwnikom szczęśliwie się powodzi. Pan bowiem trapił go z powodu mnóstwa jego występków. Jego dzieci poszły do niewoli przed ciemięzcą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 6, 'A tak odjęte zostało od córki Syjonu całe jej dostojeństwo. Jej książęta stali się jak jelenie, które nie znajdują pastwiska, i uchodzą bez siły przed tym, który je ściga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 7, 'W dniach swego utrapienia i swej niedoli Jerozolima wspomina wszystkie swoje kosztowności, jakie miała za dawnych dni, gdy jej lud wpadł w ręce wroga, a nikt jej nie pomógł; nieprzyjaciele, widząc ją, naśmiewali się z jej szabatów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 8, 'Jerozolima ciężko zgrzeszyła, dlatego została odłączona jako nieczysta. Wszyscy, którzy ją szanowali, gardzą nią, gdyż widzą jej nagość, a ona wzdycha i odwraca się plecami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 9, 'Jej nieczystość jest na brzegach jej szat, nie pamięta swego końca; dlatego wielce ją poniżono i nikt jej nie pociesza. Spójrz, Panie, na moje utrapienie, bo wróg się wywyższył.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 10, 'Wróg wyciągnął swoją rękę po wszystkie jej kosztowności. Patrzy, jak poganie, którym zakazałeś wchodzić do twego zgromadzenia, wchodzą do jej świątyni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 11, 'Cały jej lud wzdycha i szuka chleba, daje swoje kosztowności za pokarm, aby posilić duszę. Spójrz, Panie, i zobacz, że zostałam znieważona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 12, 'Czy nic was to nie obchodzi, wszyscy, którzy przechodzicie obok? Spójrzcie i zobaczcie, czy jest boleść podobna do mojej boleści, jaką mi zadano, którą dotknął mnie Pan w dniu swojego zapalczywego gniewu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 13, 'Z wysoka zesłał ogień na moje kości, który je pokonał. Rozciągnął sieć na moje nogi i zawrócił mnie, wydał mnie na spustoszenie i przez cały dzień omdlewam.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 14, 'Jarzmo moich nieprawości jest związane jego ręką, splotły się i weszły na moją szyję, a to poraziło moją siłę. Pan wydał mnie w ręce wrogów i nie mogę powstać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 15, 'Pan podeptał wszystkich moich mocarzy, którzy są pośród mnie, zwołał przeciwko mnie gromadę, aby zmiażdżyć moich młodzieńców. Pan, jak w tłoczni, podeptał dziewicę, córkę Judy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 16, 'Dlatego ja płaczę; z oczu, z moich oczu, ciekną wody, gdyż daleko jest ode mnie pocieszyciel, który by pokrzepił moją duszę; moi synowie są wytraceni, bo wróg zwyciężył.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 17, 'Syjon wyciąga swoje ręce, nie ma nikogo, kto by go pocieszył. Pan pobudził dokoła Jakuba jego wrogów; Jerozolima jest wśród nich jak kobieta oddalona z powodu jej nieczystości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 18, 'Pan jest sprawiedliwy, bo zbuntowałam się przeciwko jego słowu. Słuchajcie, proszę, wszyscy ludzie, i zobaczcie moje boleści. Moje dziewice i moi młodzieńcy poszli do niewoli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 19, 'Wołałam do moich kochanków, lecz oni mnie zdradzili. Moi kapłani i starcy zginęli w mieście, kiedy szukali pokarmu dla siebie, aby posilić swoją duszę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 20, 'Spójrz, Panie, bo jestem utrapiona, moje wnętrzności drżą, moje serce przewraca się we mnie, gdyż uparcie się buntowałam. Na dworze miecz osieroca, a w domu nie ma nic oprócz śmierci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 21, 'Słyszą, że wzdycham, ale nie ma nikogo, kto by mnie pocieszył; wszyscy moi wrogowie słyszeli o moim nieszczęściu i cieszą się, że to uczyniłeś. Sprowadzasz dzień, który zapowiedziałeś, a staną się podobni do mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 22, 'Niech cała ich niegodziwość przyjdzie przed ciebie; uczyń im tak, jak mnie uczyniłeś z powodu wszystkich moich przestępstw. Wiele bowiem jest moich westchnień, a moje serce omdlewa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 1, 'Jakże zaciemnił Pan córkę Syjonu chmurą w swoim gniewie, zrzucił z nieba na ziemię chwałę Izraela, a nie wspomniał na podnóżek swoich nóg w dniu swej zapalczywości!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 2, 'Pan pochłonął bez litości wszystkie domy Jakuba, zburzył w swej zapalczywości twierdze córki Judy, rzucił je o ziemię i zhańbił królestwo i jego książąt.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 3, 'Odciął w zapalczywości swego gniewu cały róg Izraela, cofnął swoją prawicę od wroga i zapłonął przeciwko Jakubowi jak ogień płonący, który pożera do szczętu wokoło.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 4, 'Naciągnął swój łuk jak wróg, postawił swoją prawicę jak przeciwnik i zabił wszystkich miłych dla oczu. W namiocie córki Syjonu wylał jak ogień swoją zapalczywość.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 5, 'Pan stał się jak wróg, pochłonął Izraela, pochłonął wszystkie jego pałace, zniszczył jego twierdze i pomnożył płacz i lament u córki Judy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 6, 'Oderwał siłą swój namiot jak ogród, zniszczył swoje mieszkanie. Pan skazał na zapomnienie uroczyste święta i szabaty na Syjonie i w zapalczywości swego gniewu wzgardził królem i kapłanem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 7, 'Pan odrzucił swój ołtarz, zbrzydła mu jego świątynia, wydał w ręce wroga mury jej pałacu. Podnieśli krzyk w domu Pana jak w dzień uroczystego święta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 8, 'Pan postanowił zburzyć mur córki Syjonu, rozciągnął sznur mierniczy i nie cofnął swej ręki od zniszczenia. Pogrążył w żałobie baszty i mur, tak że razem omdlewają.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 9, 'Jej bramy zapadły się w ziemię, połamał i pokruszył jej rygle. Jej król i książęta są pośród pogan, nie ma już Prawa i jej prorocy nie mają widzenia od Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 10, 'Starsi córki Syjonu usiedli na ziemi i zamilkli. Posypali prochem swe głowy i przepasali się worami. Dziewice Jerozolimy pochylają do ziemi swoje głowy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 11, 'Moje oczy osłabły od łez, strwożyły się moje wnętrzności, moja wątroba wylała się na ziemię z powodu zniszczenia córki mojego ludu, gdy dzieci i niemowlęta omdlewają na ulicach miasta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 12, 'Mówią swoim matkom: Gdzie jest zboże i wino? – gdy mdleją jak zranieni na ulicach miasta i oddają swoją duszę na łonie swoich matek.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 13, 'Kogo na świadka ustanowię? Do kogo cię przyrównam, o córko Jerozolimy? Do kogo cię porównam, abym cię pocieszył, dziewicza córko Syjonu? Twoja klęska bowiem jest wielka jak morze. Któż cię uleczy?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 14, 'Twoi prorocy przepowiadali ci kłamstwo i marność, a nie odkrywali twojej nieprawości, aby zapobiec twojej niewoli, lecz przepowiadali kłamliwe brzemiona przyczyniające się do twojego wygnania.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 15, 'Klaskają nad tobą w dłonie wszyscy, którzy przechodzą drogą; świstają i kiwają głowami nad córką Jerozolimy, mówiąc: Czyż to jest miasto, które nazywano doskonałą pięknością i radością całej ziemi?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 16, 'Otworzyli przeciw tobie swe usta wszyscy twoi wrogowie, świstają i zgrzytają zębami, mówiąc: Pochłonęliśmy je. Oto jest dzień, na który czekaliśmy; znaleźliśmy i zobaczyliśmy go.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 17, 'Pan uczynił, jak postanowił, wypełnił swoje słowo, które zapowiedział w dniach dawnych. Zburzył bez litości, pozwolił wrogowi radować się nad tobą, wywyższył róg twoich przeciwników.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 18, 'Ich serce wołało do Pana. Murze córki Syjonu, wylewaj łzy we dnie i w nocy jak strumień, nie dawaj sobie odpoczynku i niech nie uspokaja się źrenica twego oka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 19, 'Wstań, wołaj w nocy na początku straży, wylewaj swe serce jak wodę przed obliczem Pana. Podnoś do niego swe ręce za duszę swych dzieci, które omdlewają z głodu na rogach wszystkich ulic.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 20, 'Spójrz, Panie, i zobacz, komu tak uczyniłeś. Czy kobiety mają jeść swój płód, pieszczone niemowlęta? Czy kapłan i prorok mają być zabici w świątyni Pana?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 21, 'Leżą na ziemi, na ulicach, dziecko i starzec. Moje dziewice i moi młodzieńcy polegli od miecza; pobiłeś ich w dzień swego gniewu, zabiłeś ich bez litości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 22, 'Zwołałeś zewsząd, jak w dniu święta, moje trwogi, w dniu gniewu Pana nikt nie uszedł, nikt nie ocalał. Tych, których piastowałam i wychowałam, mój wróg wyniszczył.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 1, 'Ja jestem tym człowiekiem, który widział utrapienie pod rózgą jego gniewu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 2, 'Prowadził mnie i zawiódł do ciemności, a nie do światła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 3, 'Oburzył się na mnie, zwraca swoją rękę przeciwko mnie przez cały dzień.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 4, 'Sprawił, że zestarzały się moje ciało i moja skóra, połamał moje kości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 5, 'Obudował mnie i otoczył żółcią i trudem;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 6, 'Posadził mnie w ciemnych miejscach jak dawno umarłych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 7, 'Ogrodził mnie, abym nie mógł wyjść, obciążył moje kajdany.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 8, 'A choć wołam i krzyczę, zatyka uszy na moją modlitwę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 9, 'Zagrodził moją drogę kamieniem ciosanym, poplątał moje ścieżki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 10, 'Stał się dla mnie jak niedźwiedź czyhający na mnie, jak lew w ukryciu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 11, 'Zmylił moje drogi, rozszarpał mnie i uczynił mnie spustoszonym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 12, 'Napiął swój łuk i uczynił ze mnie cel dla swej strzały.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 13, 'Przebił moje nerki strzałami swego kołczana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 14, 'Stałem się pośmiewiskiem dla całego mojego ludu, tematem jego pieśni przez cały dzień.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 15, 'Napełnił mnie goryczą, upoił mnie piołunem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 16, 'Ponadto wykruszył żwirem moje zęby i pogrążył mnie w popiele.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 17, 'Oddaliłeś moją duszę od pokoju. Zapomniałem, co to pomyślność.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 18, 'I powiedziałem: Zginęła moja siła i moja nadzieja, jaką pokładałem w Panu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 19, 'Wspominam swoje utrapienie i swój płacz, piołun i żółć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 20, 'Moja dusza nieustannie to wspomina i uniża się we mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 21, 'Biorę to sobie do serca, dlatego mam nadzieję.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 22, 'To wielkie miłosierdzie Pana, że nie zginęliśmy, gdyż nie ustaje jego litość.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 23, 'Każdego poranka się odnawia, wielka jest twoja wierność.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 24, 'Pan jest moim działem – mówi moja dusza – dlatego mam w nim nadzieję.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 25, 'Dobry jest Pan dla tych, którzy go oczekują, dla duszy, która go szuka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 26, 'Dobrze jest cierpliwie oczekiwać na zbawienie Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 27, 'Dobrze jest człowiekowi nosić jarzmo od swej młodości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 28, 'Siedzi samotnie w milczeniu, gdyż na niego je włożono.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 29, 'Kładzie swe usta w prochu, może jest jeszcze nadzieja.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 30, 'Nadstawia bijącemu policzek, jest nasycony zniewagą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 31, 'Pan bowiem nie odrzuca na wieki;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 32, 'A jeśli zasmuca, znów się lituje według obfitości swego miłosierdzia;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 33, 'Gdyż nie trapi chętnie ani nie zasmuca synów ludzkich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 34, 'Miażdżenie pod nogami wszystkich więźniów ziemi;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 35, 'Naginanie prawa człowieka przed obliczem Najwyższego;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 36, 'Krzywdzenie człowieka w jego sprawie – Pan nie ma w tym upodobania.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 37, 'Któż może powiedzieć, że coś się stanie, gdy Pan tego nie rozkazał?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 38, 'Czyż z ust Najwyższego nie pochodzi zło i dobro?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 39, 'Czemu więc żali się człowiek żyjący, człowiek – z powodu kary za swoje grzechy?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 40, 'Doświadczajmy i badajmy nasze drogi, nawróćmy się do Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 41, 'Wznieśmy swoje serca i ręce do Boga w niebiosach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 42, 'Zgrzeszyliśmy i zbuntowaliśmy się, a ty nie przebaczyłeś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 43, 'Okryłeś się gniewem i prześladowałeś nas, zabiłeś bez litości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 44, 'Okryłeś się obłokiem, aby nie dotarła do ciebie modlitwa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 45, 'Uczyniłeś nas śmieciem i pogardą pośród tych narodów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 46, 'Otworzyli na nas swoje usta wszyscy nasi wrogowie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 47, 'Spadły na nas strach i pułapka, spustoszenie i zniszczenie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 48, 'Strumienie wód płyną z moich oczu z powodu zniszczenia córki mojego ludu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 49, 'Z moich oczu bez przerwy spływają łzy, bo nie ma żadnej ulgi;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 50, 'Póki nie spojrzy i nie zobaczy Pan z nieba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 51, 'Moje oczy trapią moją duszę z powodu wszystkich córek mojego miasta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 52, 'Moi wrogowie polowali na mnie nieustannie jak na ptaka, bez powodu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 53, 'Wyniszczyli moje życie w lochu i przywalili mnie kamieniem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 54, 'Wezbrały wody nad moją głową i powiedziałem: Już po mnie!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 55, 'Wzywałem twego imienia, Panie, z głębokiego lochu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 56, 'Usłyszałeś mój głos, nie zakrywaj swego ucha przed moim wzdychaniem i przed moim wołaniem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 57, 'Zbliżyłeś się do mnie w dniu, kiedy cię wzywałem, i powiedziałeś: Nie bój się.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 58, 'Broniłeś, Panie, sprawy mojej duszy, wybawiłeś moje życie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 59, 'Panie, widzisz moją krzywdę, osądź moją sprawę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 60, 'Widzisz całą ich zemstę i wszystkie ich zamysły przeciwko mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 61, 'Słyszysz ich urąganie, Panie, i wszystkie ich zamysły przeciwko mnie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 62, 'Słyszysz słowa z warg tych, którzy powstają przeciwko mnie, i ich zamiary, jakie obmyślają przeciwko mnie przez cały dzień.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 63, 'Zobacz – gdy siedzą i gdy wstają, jestem treścią ich pieśni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 64, 'Oddaj im zapłatę, Panie, według dzieła ich rąk.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 65, 'Daj im zatwardziałe serce i ześlij na nich twoje przekleństwo;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 66, 'Ścigaj ich w gniewie i zgładź ich spod niebios, Panie!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 1, 'O jakże zaśniedziało złoto! Jakże zmieniło się najczystsze złoto! Rozrzucono kamienie świątyni po rogach wszystkich ulic.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 2, 'Szlachetni synowie Syjonu, cenieni jak czyste złoto, jakże są poczytywani za gliniane naczynia, za dzieło rąk garncarza!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 3, 'Nawet smoki dają pierś i karmią swoje młode, ale córka mojego ludu stała się okrutna jak strusie na pustyni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 4, 'Język ssącego przylgnął do podniebienia z powodu pragnienia, dzieci prosiły o chleb, lecz nikt im go nie ułamał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 5, 'Ci, którzy jadali wyborne potrawy, giną na ulicach. Ci, którzy byli wychowani w szkarłacie, przytulają się do gnoju.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 6, 'Większa jest nieprawość córki mojego ludu niż grzech Sodomy, co została zniszczona w okamgnieniu, a nie dotknęła jej żadna ręka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 7, 'Jej nazirejczycy byli czystsi niż śnieg, bielsi niż mleko, ich ciała bardziej rumiane niż rubiny, byli wyciosani jak szafir.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 8, 'Ale teraz ich wygląd jest czarniejszy niż węgiel, nie poznaje się ich na ulicach. Ich skóra przyschła do kości, wyschła i stała się jak drewno.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 9, 'Lepiej jest tym, którzy zostali pobici od miecza, niż tym, co umierają z głodu, gdyż oni giną, będąc przebici brakiem plonów pola.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 10, 'Ręce czułych kobiet gotowały własne dzieci. Były ich pokarmem w czasie klęski córki mojego ludu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 11, 'Dopełnił Pan swego wzburzenia, wylał swój zapalczywy gniew i rozpalił ogień na Syjonie, który strawił jego fundamenty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 12, 'Nigdy nie uwierzyliby królowie ziemi i wszyscy mieszkańcy świata, że przeciwnik i wróg mógłby wejść w bramy Jerozolimy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 13, 'Z powodu grzechów jej proroków i nieprawości jej kapłanów, którzy przelewali krew sprawiedliwych pośród niej;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 14, 'Tułali się jak ślepi po ulicach, splugawili się krwią, tak że nie można było dotknąć ich szat.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 15, 'Dlatego wołano na nich: Odstąpcie, nieczyści! Odstąpcie, odstąpcie, nie dotykajcie! Gdy odeszli i tułali się, mówiono wśród pogan: Nie będą już mogli tam zamieszkać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 16, 'Oblicze Pana rozproszyło ich, już więcej nie spojrzy na nich; nie ma szacunku dla kapłanów ani nie ma litości dla starców.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 17, 'Aż dotąd nasze oczy słabły z powodu naszej daremnej pomocy. Wypatrywaliśmy czujnie narodu, który nie mógł nas wybawić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 18, 'Śledzą nasze kroki tak, że nie możemy chodzić po naszych ulicach. Zbliżył się nasz koniec, wypełniły się nasze dni, nadszedł nasz kres.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 19, 'Nasi prześladowcy są szybsi niż orły niebieskie; ścigają nas po górach i czyhają na nas na pustyni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 20, 'Oddech naszych nozdrzy, pomazaniec Pana, został schwytany w ich doły; o nim mówiliśmy: W jego cieniu będziemy żyć wśród pogan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 21, 'Raduj się i wesel, córko Edomu, która mieszkasz w ziemi Us; przejdzie też do ciebie kielich, upijesz się i obnażysz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 22, 'Skończyła się twoja kara, o córko Syjonu; on nie będzie cię dłużej trzymał na wygnaniu. Nawiedzi twoją nieprawość, córko Edomu, i odkryje twoje grzechy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 1, 'Wspomnij, Panie, na to, co nas spotkało. Spójrz i zobacz nasze pohańbienie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 2, 'Nasze dziedzictwo przypadło obcym, a nasze domy – cudzoziemcom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 3, 'Staliśmy się sierotami, bez ojca; nasze matki są jak wdowy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 4, 'Własną wodę pijemy za pieniądze, nasze drwa za pieniądze kupujemy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 5, 'Prześladowanie ciąży na naszym karku. Pracujemy, a nie dają nam odpocząć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 6, 'Podawaliśmy rękę Egipcjanom i Asyryjczykom, aby nasycić się chlebem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 7, 'Nasi ojcowie zgrzeszyli, nie ma ich, a my nosimy ich nieprawość.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 8, 'Niewolnicy panują nad nami, nie ma nikogo, kto by nas wybawił z ich ręki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 9, 'Z narażeniem życia szukamy swego chleba z powodu miecza na pustyni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 10, 'Nasza skóra jak piec zaciemniła się od strasznego głodu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 11, 'Kobiety na Syjonie hańbiono, a panny – w miastach Judy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 12, 'Książęta byli wieszani ich rękami, oblicza starszych nie uszanowano.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 13, 'Młodzieńców wzięli do młócenia, dzieci padały pod ciężarem drewna.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 14, 'Starcy w bramach już nie siadają, młodzieńcy przestali śpiewać swoje pieśni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 15, 'Radość zniknęła z naszych serc, nasze pląsanie zamieniło się w żałobę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 16, 'Spadła korona z naszej głowy. Biada nam, bo zgrzeszyliśmy!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 17, 'Dlatego nasze serce omdlewa, dlatego nasze oczy są zaćmione.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 18, 'Z powodu spustoszonej góry Syjonu lisy chodzą po niej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 19, 'Ty, Panie, trwasz na wieki, twój tron z pokolenia na pokolenie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 20, 'Czemu zapominasz o nas na wieki i opuszczasz nas na tak długi czas?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 21, 'Nawróć nas do siebie, Panie, a będziemy nawróceni; odnów nasze dni, jak dawniej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 22, 'Czy odrzuciłeś nas całkowicie? Czy bardzo się na nas gniewałeś?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 1, 'I stało się w trzydziestym roku, w czwartym miesiącu, piątego dnia tego miesiąca, gdy byłem wśród uprowadzonych nad rzeką Kebar, że otworzyły się niebiosa i miałem widzenie Boże.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 2, 'Piątego dnia tego miesiąca – był to piąty rok od uprowadzenia do niewoli króla Jojakina;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 3, 'Słowo Pana doszło wyraźnie do kapłana Ezechiela, syna Buziego, w ziemi Chaldejczyków nad rzeką Kebar, a była nad nim ręka Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 4, 'I spojrzałem, a oto gwałtowny wiatr nadszedł od północy, a z nim wielka chmura, ogień pałający oraz blask dokoła niego, a z jego środka widoczne było coś jakby blask bursztynu – ze środka ognia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 5, 'Także ze środka ukazało się coś na kształt czterech istot żywych. A wyglądały tak: miały one postać człowieka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 6, 'Każda z nich miała po cztery twarze i każda po cztery skrzydła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 7, 'Ich nogi były proste, a ich stopy jak stopy u cielca; lśniły jak polerowany brąz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 8, 'Pod skrzydłami, po czterech bokach, miały ręce ludzkie; a one cztery miały twarze i skrzydła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 9, 'Ich skrzydła były złączone jedno z drugim; gdy szły, nie odwracały się, ale każda istota szła prosto przed siebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 10, 'A ich twarze miały taki wygląd: wszystkie cztery miały z przodu twarz ludzką, z prawej strony – twarz lwa, z lewej strony wszystkie cztery miały twarze wołu, a także z tyłu miały wszystkie twarz orła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 11, 'A ich twarze i skrzydła były rozwinięte ku górze; dwa skrzydła każdej istoty łączyły się ze sobą, a dwa okrywały ich ciało;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 12, 'A każda z istot szła prosto przed siebie. Dokądkolwiek duch zmierzał, tam szły, a gdy szły, nie odwracały się.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 13, 'A wygląd tych istot był taki: wyglądały jak węgle rozżarzone w ogniu, jak palące się pochodnie. Ten ogień krążył między istotami, jaśniał blaskiem, a z niego wychodziła błyskawica.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 14, 'Te istoty biegały tam i z powrotem jak błysk pioruna.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 15, 'A gdy się przypatrywałem tym istotom żywym, oto znajdowało się jedno koło na ziemi przy tych czterech istotach mających cztery twarze;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 16, 'Wygląd tych kół i ich wykonanie były jak blask berylu i wszystkie cztery koła miały jednakowy kształt, a tak wyglądały i tak były wykonane, jakby jedno koło było w środku drugiego koła;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 17, 'Gdy się poruszały, szły w czterech kierunkach, a idąc, nie odwracały się.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 18, 'Obręcze były tak wysokie, że wzbudzały strach, a te cztery obręcze miały pełno oczu wokoło.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 19, 'A gdy istoty żywe szły, koła szły obok nich; gdy istoty żywe podnosiły się ponad ziemię, podnosiły się także koła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 20, 'Dokądkolwiek zmierzał duch, tam szły – właśnie tam, gdzie zmierzał duch; a koła podnosiły się przed nimi, bo duch istot żywych był w kołach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 21, 'Gdy one szły, poruszyły się i koła; gdy one stawały, zatrzymywały się i koła; a gdy podnosiły się ponad ziemię, wraz z nimi podnosiły się też koła, bo duch istot żywych był w kołach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 22, 'Nad głowami istot żywych było coś na kształt sklepienia jak blask straszliwego kryształu, rozpostartego w górze nad ich głowami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 23, 'A pod sklepieniem skrzydła ich były podniesione, jedno z drugim złączone; każda istota miała po dwa, którymi okrywała jedną stronę, i każda miała po dwa, którymi okrywała drugą stronę swego ciała.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 24, 'I gdy szły, słyszałem szum ich skrzydeł jak szum wielkich wód, jak głos Wszechmocnego i głos huku, jak zgiełk wojska. A gdy stały, opuszczały swoje skrzydła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 25, 'Gdy stały i opuszczały swoje skrzydła, rozległ się głos znad sklepienia, które było nad ich głową.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 26, 'A ponad sklepieniem, które było nad ich głową, było coś podobnego do tronu, z wyglądu jak kamień szafiru. I u góry, na tym, co było podobne do tronu, znajdowało się coś z wyglądu przypominające człowieka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 27, 'I widziałem jakby kolor bursztynu niczym ogień wewnątrz niego wokoło; od jego bioder wzwyż i od jego bioder w dół widziałem coś, co wyglądało jak ogień, a wokół niego blask.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 28, 'Jak widok tęczy, która pojawia się w chmurze w dzień deszczowy, tak wyglądał blask wokoło. To było widzenie podobieństwa chwały Pana. A gdy ją zobaczyłem, upadłem na twarz i usłyszałem głos mówiącego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 1, 'I powiedział do mnie: Synu człowieczy, stań na nogi, a będę do ciebie mówił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 2, 'I wstąpił we mnie duch, gdy przemówił do mnie, i postawił mnie na nogi; potem słyszałem tego, który mówił do mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 3, 'Powiedział mi: Synu człowieczy, ja cię posyłam do synów Izraela, do narodu buntowniczego, który mi się sprzeciwił. Oni i ich ojcowie występowali przeciwko mnie aż do dziś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 4, 'Są to synowie o bezczelnych twarzach i zatwardziałym sercu. Do nich cię posyłam. Powiesz im: Tak mówi Pan Bóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 5, 'A oni, czy posłuchają, czy nie – gdyż są domem buntowniczym – przecież będą wiedzieć, że był wśród nich prorok.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 6, 'Ale ty, synu człowieczy, nie bój się ich ani nie lękaj się ich słów, chociaż otaczają cię osty i ciernie i mieszkasz wśród skorpionów. Nie bój się ich słów ani nie lękaj się ich twarzy, gdyż są domem buntowniczym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 7, 'Powiedz im moje słowa, czy usłuchają, czy nie, gdyż są zbuntowani.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 8, 'Lecz ty, synu człowieczy, słuchaj, co mówię do ciebie: Nie bądź zbuntowany jak ten dom buntowniczy. Otwórz swe usta i zjedz, co ci daję.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 9, 'I spojrzałem, a oto ręka była wyciągnięta do mnie, a w niej zwój księgi;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 10, 'A on rozwinął go przede mną. Był zapisany z jednej i z drugiej strony, a spisane były w nim lamenty, żal i biadania.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 1, 'I powiedział do mnie: Synu człowieczy, zjedz to, co jest przed tobą; zjedz ten zwój i idź, przemawiaj do domu Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 2, 'Otworzyłem więc swe usta i dał mi zjeść ten zwój.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 3, 'I powiedział mi: Synu człowieczy, nakarm swój brzuch i napełnij swoje wnętrzności tym zwojem, który ci daję. Zjadłem go, a był w moich ustach słodki jak miód.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 4, 'Potem powiedział do mnie: Synu człowieczy, idź, udaj się do domu Izraela i mów do niego moimi słowami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 5, 'Bo nie posyłam cię do ludu o niezrozumiałej mowie lub trudnym języku, ale do domu Izraela;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 6, 'Nie do wielu narodów o niezrozumiałej mowie i trudnym języku, których słów byś nie zrozumiał, chociaż gdybym cię do nich posłał, usłuchałyby cię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 7, 'Lecz dom Izraela nie będzie chciał cię słuchać, ponieważ mnie samego nie chce usłuchać. Cały dom Izraela ma bowiem twarde czoło i zatwardziałe serce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 8, 'Oto uczyniłem twoją twarz twardą przeciwko ich twarzom, a twoje czoło twarde przeciwko ich czołom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 9, 'Uczyniłem twe czoło jak diament, twardszym od krzemienia. Nie bój się ich ani nie lękaj się ich twarzy, gdyż są domem buntowniczym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 10, 'I powiedział do mnie: Synu człowieczy, weź sobie do serca wszystkie moje słowa, które będę do ciebie mówić, i słuchaj ich uszami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 11, 'Idź, udaj się do pojmanych, do synów twego ludu, i powiedz im: Tak mówi Pan Bóg – czy będą słuchać, czy nie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 12, 'Wtedy duch uniósł mnie i usłyszałem za sobą huk wielkiego grzmotu: Niech będzie błogosławiona chwała Pana ze swego miejsca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 13, 'Usłyszałem też szum skrzydeł tych istot żywych, które się dotykały nawzajem, głos kół naprzeciwko nich i głos wielkiego grzmotu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 14, 'A duch uniósł mnie i zabrał. I poszedłem w goryczy i w gniewie swego ducha, lecz ręka Pana mocno ciążyła nade mną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 15, 'I przyszedłem do pojmanych w Tel-Abib, którzy mieszkali nad rzeką Kebar, i usiadłem tam, gdzie oni mieszkali, pozostałem tam osłupiały wśród nich przez siedem dni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 16, 'A gdy minęło siedem dni, doszło do mnie słowo Pana mówiące:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 17, 'Synu człowieczy, ustanowiłem cię stróżem domu Izraela. Usłysz więc słowo z moich ust i upominaj go ode mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 18, 'Gdy powiem bezbożnemu: Z pewnością umrzesz, a nie upomnisz go ani nie ostrzeżesz, aby go odwieść od jego bezbożnej drogi, aby uratować jego życie, to ten bezbożny umrze w swojej nieprawości, ale jego krwi zażądam z twojej ręki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 19, 'Lecz jeśli ostrzeżesz bezbożnego, a on nie odwróci się od swej bezbożności i od swej bezbożnej drogi, to on umrze w swojej nieprawości, ale ty wybawisz swoją duszę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 20, 'Gdy zaś sprawiedliwy odwróci się od swojej sprawiedliwości i popełni nieprawość, a ja ześlę na niego przeszkodę, to on umrze. Ponieważ nie ostrzegłeś go, umrze w swym grzechu i nie będzie się pamiętać o jego sprawiedliwości, którą czynił, lecz jego krwi zażądam z twojej ręki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 21, 'Ale jeśli ostrzeżesz sprawiedliwego, aby sprawiedliwy nie zgrzeszył, i on nie zgrzeszy, na pewno będzie żył, bo przyjął ostrzeżenie, a ty ocalisz swoją duszę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 22, 'I spoczęła tam nade mną ręka Pana, i powiedział do mnie: Wstań i pójdź na równinę, tam będę z tobą mówił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 23, 'Wstałem więc i wyszedłem na równinę, a oto chwała Pana stała tam, taka jak chwała, którą widziałem nad rzeką Kebar, i upadłem na twarz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 24, 'Wtedy duch wstąpił we mnie, postawił mnie na nogi i przemówił do mnie: Idź i zamknij się w swym domu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 25, 'Bo oto, synu człowieczy, włożą na ciebie powrozy i zwiążą cię nimi, a nie będziesz mógł wyjść między nich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 26, 'A ja sprawię, że twój język przylgnie do twego podniebienia i będziesz niemy, i nie będziesz dla nich człowiekiem, który strofuje, gdyż są domem buntowniczym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 27, 'Ale gdy będę z tobą mówić, otworzę ci usta i powiesz do nich: Tak mówi Pan Bóg: Kto chce słuchać, niech słucha, a kto nie chce, niech nie słucha – gdyż są domem buntowniczym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 1, 'A ty, synu człowieczy, weź sobie glinianą tabliczkę, połóż ją przed sobą i wyryj na niej miasto Jerozolimę;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 2, 'Sporządź jego oblężenie, zbuduj przeciwko niemu szańce, usyp przeciwko niemu wał, uszykuj przeciwko niemu wojska i ustaw przeciwko niemu tarany dokoła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 3, 'Następnie weź sobie patelnię żelazną, postaw ją jakby mur żelazny pomiędzy sobą a miastem i odwróć swą twarz przeciwko niemu. Ono będzie oblężone, a ty będziesz je oblegał. To będzie znak dla domu Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 4, 'Potem połóż się na lewym boku i złóż na nim nieprawość domu Izraela. Ile dni będziesz na nim leżał, tak długo będziesz znosił ich nieprawość.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 5, 'A ja wyznaczam ci lata ich nieprawości według liczby dni: trzysta dziewięćdziesiąt dni. Tak długo będziesz znosił nieprawość domu Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 6, 'A gdy je wypełnisz, położysz się na prawym boku i będziesz znosił nieprawość domu Judy przez czterdzieści dni. Wyznaczam ci jeden dzień za każdy rok.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 7, 'Tak więc obróć swoją twarz na oblężenie Jerozolimy, obnaż swoje ramię i prorokuj przeciwko niej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 8, 'A oto kładę na ciebie pęta, abyś nie mógł się obrócić z jednego boku na drugi, aż wypełnisz dni swego oblężenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 9, 'Weź sobie też pszenicę, jęczmień, bób, soczewicę, proso i orkisz, włóż to do jednego naczynia i przygotuj sobie z tego chleb, a będziesz go jadł przez tyle dni, ile będziesz leżeć na swym boku – przez trzysta dziewięćdziesiąt dni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 10, 'A waga twego pokarmu, który będziesz jadł, wyniesie dwadzieścia syklów na dzień. Będziesz go jadł w ustalonym czasie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 11, 'Także wodę będziesz pił w określonej ilości; szóstą część hinu będziesz pił w ustalonym czasie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 12, 'Chleb będziesz jadł jak podpłomyki jęczmienne, upieczesz go na ich oczach na ludzkich odchodach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 13, 'I Pan powiedział: Tak synowie Izraela będą jeść swój nieczysty chleb wśród pogan, do których ich wypędzę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 14, 'I powiedziałem: Ach, Panie Boże! Oto moja dusza nigdy się nie splamiła: od mojego dzieciństwa aż do tej pory nie jadłem padliny ani tego, co zwierzę rozszarpało; żadne mięso obrzydłe nie weszło do moich ust.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 15, 'Ale on powiedział do mnie: Oto daję ci odchody wołowe zamiast odchodów ludzkich, abyś sobie na nich upiekł chleb.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 16, 'Potem powiedział do mnie: Synu człowieczy, oto ja zniszczę zapas chleba w Jerozolimie, tak że będą jedli chleb w odważonej ilości i w zmartwieniu i będą pić wodę w odmierzonej ilości i z przerażeniem;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 17, 'Aby im brakowało chleba i wody, aby każdy z nich był przerażony i niszczał w swoich nieprawościach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 1, 'Ty zaś, synu człowieczy, weź sobie ostry nóż, weź sobie brzytwę fryzjerską i ogól nią sobie głowę oraz brodę. Potem weź sobie wagę i rozdziel włosy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 2, 'Jedną trzecią spal w ogniu w środku miasta, gdy wypełnią się dni oblężenia. Potem weź trzecią część i posiekaj mieczem dokoła, a trzecią część rozrzuć na wiatr, bo ja dobędę miecz na nich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 3, 'Ale weź z nich małą ilość i zawiń w poły swojej szaty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 4, 'Z tych weź jeszcze trochę, wrzuć je w środek ognia i spal je w ogniu; stamtąd wyjdzie ogień na cały dom Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 5, 'Tak mówi Pan Bóg: To jest Jerozolima, którą umieściłem pośród pogan, otoczona zewsząd krajami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 6, 'Ale zamieniła moje sądy w niegodziwość, bardziej niż poganie, a moje ustawy – bardziej niż kraje, które ją otaczają. Wzgardzili bowiem moimi sądami i nie postępowali według moich ustaw.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 7, 'Dlatego tak mówi Pan Bóg: Ponieważ przewyższyliście swoimi grzechami pogan, którzy was otaczają, a nie postępowaliście według moich ustaw i nie przestrzegaliście moich sądów, nawet nie czyniliście według sądów pogan, którzy są dokoła was;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 8, 'Dlatego tak mówi Pan Bóg: Oto występuję przeciwko tobie i wykonam sądy pośrodku ciebie, na oczach pogan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 9, 'I z powodu wszystkich twoich obrzydliwości uczynię ci to, czego wcześniej nie uczyniłem, i czego już więcej nie uczynię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 10, 'Dlatego ojcowie będą jeść synów pośród ciebie, a synowie będą jeść swoich ojców. Wykonam sądy nad tobą i rozproszę całą twoją resztkę na wszystkie wiatry.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 11, 'Dlatego jak żyję, mówi Pan Bóg: Ponieważ zbezcześciłeś moją świątynię wszelkimi twymi nieczystościami i wszelkimi twymi obrzydliwościami, ja także poniżę ciebie, moje oko nie oszczędzi cię i nie zlituję się nad tobą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 12, 'Trzecia część twoich ludzi umrze od zarazy i wyginie z głodu pośród ciebie, trzecia część padnie od miecza wokół ciebie, a trzecią część rozproszę na wszystkie wiatry i miecz na nich dobędę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 13, 'Tak dopełni się mój gniew i natrę na nich swoją zapalczywością, i ucieszę się. I poznają, że ja, Pan, powiedziałem to w swojej zapalczywości, gdy wykonam na nich swój gniew.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 14, 'I zamienię cię w spustoszenie i w hańbę narodów, które są wokoło ciebie, na oczach każdego przechodnia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 15, 'A tak staniesz się hańbą, pośmiewiskiem, przykładem i przerażeniem dla narodów, które cię otaczają, gdy wykonam na tobie sądy w zapalczywości i gniewie, i w srogich upomnieniach. Ja, Pan, to powiedziałem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 16, 'Gdy wypuszczę przeciw wam srogie strzały głodu, które będą leciały ku zniszczeniu, a które wypuszczę, aby was wyniszczyć, wzmogę głód przeciwko wam i zniszczę wasz zapas chleba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 17, 'Ześlę więc na was głód i okrutne zwierzęta, które cię osierocą. Przejdą przez ciebie zaraza i krew i sprowadzę na ciebie miecz. Ja, Pan, to powiedziałem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 1, 'I doszło do mnie słowo Pana mówiące:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 2, 'Synu człowieczy, zwróć swoją twarz ku górom Izraela i prorokuj przeciwko nim;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 3, 'I mów: Góry Izraela, słuchajcie słowa Pana Boga. Tak mówi Pan Bóg do gór i pagórków, do strumieni i dolin: Oto ja, właśnie ja sprowadzę na was miecz i zniszczę wasze wyżyny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 4, 'Wasze ołtarze będą spustoszone i wasze posągi będą połamane, a porozrzucam waszych pobitych przed waszymi bożkami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 5, 'Trupy synów Izraela położę przed ich bożkami i rozrzucę wasze kości wokół waszych ołtarzy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 6, 'Wszędzie, gdzie mieszkacie, miasta zostaną spustoszone i wyżyny spustoszeją, tak że wasze ołtarze będą zburzone i zniszczone, wasze bożki będą rozbite i przestaną istnieć, wasze posągi będą wycięte, a wasze dzieła wyniszczone.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 7, 'I pobici padną pośród was, a poznacie, że ja jestem Panem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 8, 'Lecz pozostawię niektórych spośród was, którzy ujdą spod miecza pogan, gdy będziecie rozproszeni po krajach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 9, 'Ci z was, którzy ocaleją, będą o mnie pamiętać pośród narodów, do których zostaną uprowadzeni, bo ubolewam nad ich cudzołożnym sercem, które odstąpiło ode mnie, i nad ich oczami, które uprawiały nierząd, idąc za swymi bożkami. I poczują wstręt do samych siebie z powodu zła, które popełnili we wszystkich swoich obrzydliwościach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 10, 'I poznają, że ja jestem Panem i że nie na próżno mówiłem, że sprowadzę na nich to nieszczęście.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 11, 'Tak mówi Pan Bóg: Klaśnij swą dłonią, tupnij swą nogą i mów: Biada z powodu wszystkich złych obrzydliwości domu Izraela! Padną bowiem od miecza, od głodu i od zarazy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 12, 'Ten, co będzie daleko, umrze od zarazy, ten, co blisko, polegnie od miecza, a ten, co pozostanie i będzie oblężony, umrze od głodu. Tak dopełnię na nich swej zapalczywości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 13, 'Wtedy poznacie, że ja jestem Panem, gdy ich pobici będą leżeli wśród ich bożków i dokoła ich ołtarzy, na każdym wysokim pagórku, po wszystkich szczytach górskich, pod każdym drzewem zielonym i pod każdym rozłożystym dębem, gdzie składali miłą woń wszystkim swoim bożkom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 14, 'Wyciągnę swoją rękę przeciwko nim i uczynię tę ziemię spustoszoną, bardziej spustoszoną od pustyni Diblat, wszędzie, gdzie mieszkają. I tak poznają, że ja jestem Panem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 1, 'Potem doszło do mnie słowo Pana mówiące:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 2, 'Synu człowieczy, tak mówi Pan Bóg do ziemi Izraela: Koniec, koniec nadszedł dla wszystkich czterech stron ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 3, 'Teraz nadejdzie koniec dla ciebie. Ześlę na ciebie swój gniew, będę cię sądził według twoich dróg i oddam ci według wszystkich twoich obrzydliwości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 4, 'Moje oko nie oszczędzi cię i nie zlituję się nad tobą, ale oddam ci za twoje drogi, a twoje obrzydliwości zostaną pośród ciebie, i poznacie, że ja jestem Panem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 5, 'Tak mówi Pan Bóg: Utrapienie, oto nadchodzi jedno utrapienie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 6, 'Nadszedł koniec, przyszedł koniec, ocknął się przeciwko tobie, oto nadszedł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 7, 'Nadszedł poranek dla ciebie, obywatelu ziemi. Nadszedł czas, zbliża się dzień grzmotu, a nie głosu rozlegającego się po górach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 8, 'Już wkrótce wyleję swój gniew na ciebie i dopełnię na tobie swojej zapalczywości. Osądzę cię według twoich dróg i oddam ci za wszystkie twoje obrzydliwości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 9, 'Moje oko nie oszczędzi cię i nie zlituję się nad tobą, ale oddam ci według twoich dróg i twoich obrzydliwości, które znajdują się pośród ciebie. I tak poznacie, że ja jestem Panem, który uderza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 10, 'Oto ten dzień, oto nadszedł; nastał poranek, zakwitła rózga, wyrosła pycha.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 11, 'Przemoc wyrosła w rózgę niegodziwości. Nie pozostanie z nich nic – ani z ich mnóstwa, ani z ich bogactwa i nie będzie żadnego zawodzenia nad nimi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 12, 'Nadszedł czas, zbliża się dzień. Kto kupuje, niech się nie cieszy, a kto sprzedaje, niech się nie smuci, bo przyjdzie gniew na całe ich mnóstwo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 13, 'Bo ten, kto sprzedał, nie wróci do rzeczy sprzedanej, choćby jeszcze żył. Widzenie bowiem dotyczące całego ich mnóstwa nie będzie cofnięte i nikt nie wzmocni się w nieprawości swego życia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 14, 'Zadęli w trąbę i wszystko przygotowali, lecz nikt nie ruszy do walki. Mój gniew bowiem jest skierowany na całe ich mnóstwo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 15, 'Miecz na zewnątrz, a zaraza i głód wewnątrz. Kto będzie na polu, umrze od miecza, a kto w mieście, tego pochłoną głód i zaraza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 16, 'Lecz ci, którzy z nich uciekną, będą w górach jak gołębice z dolin. Wszyscy będą lamentować, każdy nad swoją nieprawością.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 17, 'Wszystkie ręce opadną i wszystkie kolana osłabną jak woda.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 18, 'Obleką się w wory, okryje ich strach, na wszelkiej twarzy będzie wstyd i na wszystkich ich głowach łysina.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 19, 'Swoje srebro porzucą na ulice, a ich złoto będzie jak nieczystość. Ich srebro i złoto nie będzie ich mogło wybawić w dzień gniewu Pana. Nie nasycą nimi swojej duszy ani nie napełnią swych wnętrzności, bo były dla nich kamieniem potknięcia do nieprawości;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 20, 'W sławie swojej ozdoby, którą Bóg wystawił na swoją chwałę, uczynili posągi swoich obrzydliwości i plugastw. Dlatego zamienię im ją w nieczystość.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 21, 'Wydam ją w ręce cudzoziemców na grabież i bezbożnych ziemi na łup, a oni ją splugawią.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 22, 'Odwrócę też od nich swą twarz, a zbezczeszczą moją świątynię. Wejdą bowiem do niej zbójcy i splugawią ją.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 23, 'Uczyń łańcuch, bo ziemia jest pełna krwawych wyroków, a miasto pełne przemocy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 24, 'Dlatego sprowadzę najgorszych z pogan, aby posiedli ich domy. Położę kres pysze mocarzy, a ich miejsca święte będą splugawione.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 25, 'Nadchodzi zniszczenie, dlatego będą szukać pokoju, ale go nie będzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 26, 'Przyjdzie klęska za klęską, wieść za wieścią nadejdzie; będą szukać widzenia od proroka, ale prawo przepadnie kapłanowi, a rada starcom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 27, 'Król będzie w żałobie, książę okryje się smutkiem i ręce ludu ziemi będą strwożone. Uczynię im według ich drogi i według ich sądów osądzę ich. I poznają, że ja jestem Panem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 1, 'A w szóstym roku, w szóstym miesiącu, piątego dnia, kiedy siedziałem w swym domu, a starsi Judy siedzieli przede mną, dotknęła mnie tam ręka Pana Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 2, 'Spojrzałem, a oto coś z wyglądu podobnego do ognia: od bioder w dół wyglądało jak ogień, a od bioder wzwyż wyglądało jak blask, jak blask bursztynu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 3, 'Wtedy wyciągnął coś w kształcie ręki i uchwycił mnie za kędziory mojej głowy; a duch uniósł mnie między ziemią a niebem i zaprowadził mnie w widzeniach Bożych do Jerozolimy, do wejścia bramy wewnętrznej zwróconej ku północy, gdzie znajdował się tron posągu zawiści, pobudzający do zazdrości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 4, 'A oto była tam chwała Boga Izraela, podobna to tej, którą widziałem na równinie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 5, 'I powiedział do mnie: Synu człowieczy, podnieś teraz swe oczy w kierunku północy. Podniosłem więc swe oczy w kierunku północy, a oto na północ od bramy ołtarza, u wejścia, stał bożek pobudzający do zazdrości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 6, 'Znowu powiedział do mnie: Synu człowieczy, czy widzisz, co oni czynią? Te wielkie obrzydliwości, które czyni tu dom Izraela, tak że muszę się oddalić od swojej świątyni? Ale odwróć się i ujrzysz jeszcze większe obrzydliwości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 7, 'I przyprowadził mnie do drzwi dziedzińca, a gdy spojrzałem, oto dziura w ścianie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 8, 'I powiedział do mnie: Synu człowieczy, przebij teraz tę ścianę. I przebiłem ścianę, a oto drzwi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 9, 'I powiedział do mnie: Wejdź i zobacz te niegodziwe obrzydliwości, które oni tu czynią.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 10, 'Wszedłem więc i patrzyłem, a oto wszelkiego rodzaju zwierzęta pełzające, zwierzęta obrzydłe i wszystkie posągi domu Izraela były wyryte na ścianie, wszędzie dokoła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 11, 'Siedemdziesięciu mężów spośród starszych domu Izraela – wśród nich stał Jaazaniasz, syn Szafana – stało przed nimi, każdy miał w ręku swoją kadzielnicę, a unosił się gęsty obłok kadzidła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 12, 'Wtedy zapytał mnie: Czy widziałeś, synu człowieczy, co starsi domu Izraela czynią w ciemności, każdy w swoich komnatach pełnych obrazów? Mówią bowiem: Pan nas nie widzi, Pan opuścił tę ziemię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 13, 'Ponadto powiedział do mnie: Odwróć się znowu i zobaczysz jeszcze większe obrzydliwości, które oni czynią.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 14, 'I zaprowadził mnie do wejścia bramy domu Pana, która znajdowała się po stronie północnej, a oto siedziały tam kobiety opłakujące Tammuza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 15, 'I zapytał mnie: Czy widziałeś to, synu człowieczy? Odwróć się znowu i zobaczysz jeszcze większe obrzydliwości niż te.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 16, 'Wtedy wprowadził mnie na wewnętrzny dziedziniec domu Pana, a oto u wejścia do świątyni Pana, między przedsionkiem a ołtarzem, było około dwudziestu pięciu mężczyzn. Każdy z nich był odwrócony plecami do świątyni Pana, ich twarze były zwrócone na wschód i oddawali pokłon słońcu w kierunku wschodu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 17, 'I zapytał mnie: Czy widziałeś, synu człowieczy? Czy to zbyt mało dla domu Judy czynić takie obrzydliwości, jakie tu czynią? Napełnili bowiem ziemię nieprawością, odwrócili się, aby pobudzać mnie do gniewu, i oto przykładają gałązkę do swoich nosów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 18, 'Dlatego ja również postąpię z nimi w zapalczywości. Moje oko ich nie oszczędzi i nie zlituję się nad nimi. Będą wołać do moich uszu donośnym głosem, lecz ich nie wysłucham.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 1, 'Potem zawołał donośnym głosem do moich uszu, mówiąc: Zbliżcie się straże miasta, każda z niszczycielską bronią w ręku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 2, 'A oto sześciu mężów przyszło drogą od górnej bramy, która jest zwrócona ku północy, i każdy z nich miał w ręku niszczycielską broń. Jeden mąż wśród nich był ubrany w lnianą szatę, z kałamarzem pisarskim u boku. Weszli i stanęli obok ołtarza z brązu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 3, 'A chwała Boga Izraela uniosła się znad cherubina, na którym spoczywała, i sięgnęła do progu świątyni. Potem zawołał na tego męża ubranego w lnianą szatę, który miał kałamarz pisarski u boku;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 4, 'Pan powiedział do niego: Przejdź przez środek miasta, przez środek Jerozolimy, i uczyń znak na czołach mężczyzn, którzy wzdychają i lamentują nad wszystkimi obrzydliwościami, jakie popełnia się pośród niej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 5, 'A słyszałem, że tamtym powiedział tak: Idźcie za nim przez miasto i zabijajcie. Niech wasze oko nie oszczędzi nikogo i nie zlituję się nad nikim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 6, 'Wybijcie do szczętu starców i młodzieńców, panny, dzieci i kobiety, ale nie przystępujcie do nikogo, na którym będzie ten znak. Rozpocznijcie od mojej świątyni. Zaczęli więc od starszych, którzy byli przed domem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 7, 'Powiedział im: Splugawcie ten dom i napełnijcie dziedziniec zabitymi. Idźcie. Wyszli więc i zabijali w mieście.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 8, 'A gdy ich zabijali, a ja pozostałem, wtedy padłem na twarz i zawołałem: Ach, Panie Boże! Czy wytracisz całą resztkę Izraela, wylewając swoją zapalczywość na Jerozolimę?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 9, 'Odpowiedział mi: Nieprawość domu Izraela i Judy jest niezmiernie wielka, ziemia jest pełna krwi i miasto pełne przewrotności. Mówią bowiem: Pan opuścił tę ziemię, Pan nas nie widzi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 10, 'A więc ja to uczynię, moje oko nie oszczędzi nikogo i nie zlituję się nad nikim, złożę im na głowę ich własne postępowanie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 11, 'A oto ten mąż odziany w lnianą szatę, który miał kałamarz u boku, oznajmił: Uczyniłem tak, jak mi rozkazałeś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 1, 'Potem spojrzałem, a oto na firmamencie, który był nad głową cherubinów, ukazało się nad nimi coś jakby kamień szafiru, z wyglądu podobne do tronu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 2, 'Wtedy powiedział do tego męża ubranego w lnianą szatę: Wejdź między koła pod cherubinami, napełnij swe ręce rozżarzonymi węglami spomiędzy cherubinów i rozrzuć po mieście. I wszedł tam na moich oczach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 3, 'A cherubiny stały po prawej stronie domu, gdy wchodził ten mąż, a obłok napełnił dziedziniec wewnętrzny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 4, 'Następnie chwała Pana uniosła się znad cherubinów i sięgnęła do progu domu, a dom napełnił się obłokiem i dziedziniec napełnił się chwałą Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 5, 'I szum skrzydeł cherubinów było słychać aż na dziedzińcu zewnętrznym, jak głos Boga Wszechmocnego, gdy mówi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 6, 'Gdy rozkazał więc temu mężowi ubranemu w lnianą szatę, mówiąc: Weź ognia spomiędzy kół, spomiędzy cherubinów; to ten wszedł i stanął obok kół.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 7, 'Wtedy jeden cherubin wyciągnął rękę spomiędzy cherubinów do ognia, który był pomiędzy cherubinami, wziął i podał go do rąk męża ubranego w lnianą szatę. Ten go wziął i wyszedł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 8, 'A przy cherubinach, pod ich skrzydłami, ukazał się kształt ręki ludzkiej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 9, 'Potem spojrzałem, a oto cztery koła przy cherubinach, jedno koło obok jednego cherubina, każde koło obok każdego cherubina, a koła z wyglądu miały barwę kamienia berylu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 10, 'Co do wyglądu, wszystkie cztery miały jednakowy kształt, jakby koło znajdowało się w środku koła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 11, 'Gdy się poruszały, szły w czterech swoich kierunkach. A idąc, nie odwracały się, ale podążały w tym kierunku, w którym zwracała się głowa, i nie odwracały się, gdy szły.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 12, 'A całe ich ciało, ich plecy, ich ręce i ich skrzydła, a także koła były pełne oczu dokoła, one cztery i ich koła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 13, 'A słyszałem, że te koła nazwał kręgiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 14, 'A każda istota miała cztery twarze: pierwsza to twarz cherubina, druga to twarz człowieka, trzecia to twarz lwa, a czwarta to twarz orła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 15, 'I cherubiny się podniosły. Była to ta sama istota, którą widziałem nad rzeką Kebar.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 16, 'A gdy się poruszały cherubiny, poruszały się także koła obok nich. A gdy cherubiny podnosiły swoje skrzydła, aby się unieść ponad ziemię, koła nie odwracały się od nich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 17, 'Gdy tamci stawali, one stały, a gdy tamci się podnosili, one też się podnosiły wraz z nimi, bo był w nich duch istoty żywej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 18, 'Potem chwała Pana odeszła od progu domu i stanęła nad cherubinami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 19, 'A cherubiny podniosły swoje skrzydła i uniosły się z ziemi na moich oczach. Gdy odchodziły, koła były przy ich boku. Stanęły u wejścia do wschodniej bramy domu Pana, a chwała Boga Izraela była nad nimi u góry.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 20, 'To jest ta istota, którą widziałem pod Bogiem Izraela nad rzeką Kebar; i poznałem, że były to cherubiny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 21, 'Każdy z nich miał po cztery twarze i każdy miał po cztery skrzydła, a pod skrzydłami było coś w kształcie rąk ludzkich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 22, 'A wygląd ich twarzy był taki sam jak twarze, które widziałem nad rzeką Kebar. Tak właśnie wyglądały ich twarze i oni sami. Każdy z nich poruszał się prosto przed siebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 1, 'Potem duch uniósł mnie i zaprowadził do wschodniej bramy domu Pana, która jest zwrócona na wschód. A oto u wejścia tej bramy było dwudziestu pięciu mężczyzn, wśród których zobaczyłem Jaazaniasza, syna Azzura, i Pelatiasza, syna Benajasza, książąt ludu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 2, 'Wtedy powiedział mi: Synu człowieczy, to są mężczyźni, którzy obmyślają nieprawość i dają złe rady w tym mieście;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 3, 'Mówią: To nie tak blisko, budujmy domy. Oto miasto jest kotłem, a my – mięsem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 4, 'Dlatego prorokuj przeciwko nim, prorokuj, synu człowieczy!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 5, 'Wtedy zstąpił na mnie Duch Pana i powiedział do mnie: Mów: Tak mówi Pan: Tak mówiliście, domu Izraela. Znam bowiem wszystko, co wam przychodzi na myśl.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 6, 'Zabiliście wielkie mnóstwo ludzi w tym mieście i napełniliście ulice zabitymi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 7, 'Dlatego tak mówi Pan Bóg: Wasi zabici, których położyliście w środku miasta, są mięsem, a miasto – kotłem. Lecz wyprowadzę was z niego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 8, 'Baliście się miecza, a ja sprowadzę na was miecz, mówi Pan Bóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 9, 'A wyprowadzę was z niego, wydam was w ręce obcych i wykonam nad wami sądy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 10, 'Padniecie od miecza, osądzę was na granicy Izraela i dowiecie się, że ja jestem Panem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 11, 'Miasto nie będzie dla was kotłem ani wy nie będziecie w nim mięsem; na granicy Izraela osądzę was.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 12, 'I dowiecie się, że ja jestem Panem, ponieważ nie postępowaliście według moich ustaw, nie wykonaliście moich sądów, ale czyniliście według sądów tych pogan, którzy są dokoła was.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 13, 'A gdy prorokowałem, umarł Pelatiasz, syn Benajasza. Wtedy upadłem na twarz i zawołałem donośnym głosem: Ach, Panie Boże! Czy doszczętnie wyniszczysz resztkę Izraela?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 14, 'I doszło do mnie słowo Pana mówiące:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 15, 'Synu człowieczy, twoi bracia, właśnie twoi bracia, twoi krewni i cały dom Izraela są tymi, do których mówili mieszkańcy Jerozolimy: Oddalcie się od Pana. Nam została dana ta ziemia w posiadanie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 16, 'Dlatego mów: Tak mówi Pan Bóg: Chociaż wygnałem ich daleko pomiędzy pogan i chociaż rozproszyłem ich po krajach, jednak przez krótki czas będę dla nich świątynią w krajach, do których przybędą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 17, 'Dlatego mów: Tak mówi Pan Bóg: Zgromadzę was z pogan i zbiorę was z krajów, do których zostaliście rozproszeni, i dam wam ziemię Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 18, 'Wejdą tam i usuną z niej wszystkie jej plugastwa i wszystkie jej obrzydliwości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 19, 'I dam im jedno serce, i włożę nowego ducha w wasze wnętrze; usunę z ich ciała serce kamienne, a dam im serce mięsiste;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 20, 'Aby postępowali według moich ustaw i strzegli moich sądów oraz czynili je. I będą moim ludem, a ja będę ich Bogiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 21, 'Ale co do tych, których serce chodzi za żądzami ich plugastw i obrzydliwości, złożę im na głowę ich własną drogę, mówi Pan Bóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 22, 'Wtedy cherubiny podniosły swoje skrzydła i wraz z nimi koła, a chwała Boga Izraela była nad nimi u góry.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 23, 'I odeszła chwała Pana z pośrodku miasta, i stanęła na górze, która jest na wschód od miasta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 24, 'A duch uniósł mnie i przyprowadził w widzeniu przez Ducha Bożego do ziemi Chaldei, do pojmanych. I odeszło ode mnie widzenie, które miałem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 25, 'Następnie opowiedziałem pojmanym te wszystkie rzeczy, które Pan mi ukazał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 1, 'I doszło do mnie słowo Pana mówiące:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 2, 'Synu człowieczy, mieszkasz pośród domu buntowniczego, który ma oczy, aby widzieć, a nie widzi, ma uszy, aby słyszeć, a nie słyszy. Jest bowiem domem buntowniczym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 3, 'Ty więc, synu człowieczy, przygotuj sobie toboły wygnańca i wyprowadź się za dnia na ich oczach; przenieś się na ich oczach ze swego miejsca na inne. Może zrozumieją, chociaż są domem buntowniczym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 4, 'Wyniesiesz swoje rzeczy za dnia na ich oczach, jak toboły wygnańca; wyjdź wieczorem na ich oczach, jak wychodzą wygnańcy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 5, 'Na ich oczach przebij sobie mur i wynieś przez niego swoje rzeczy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 6, 'Na ich oczach podnieś je na ramiona i wynieś o zmierzchu, zakryj sobie twarz i nie patrz na ziemię. Dałem cię bowiem jako znak domowi Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 7, 'I uczyniłem tak, jak mi rozkazano: wyniosłem swoje rzeczy za dnia, jak toboły wygnańca, a wieczorem przebiłem ręką mur; o zmierzchu wyniosłem je, na ramionach niosąc je na ich oczach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 8, 'A rano doszło do mnie słowo Pana mówiące:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 9, 'Synu człowieczy, czy dom Izraela, ten dom buntowniczy, nie zapytał cię: Cóż ty czynisz?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 10, 'Powiedz im: Tak mówi Pan Bóg: To brzemię odnosi się do księcia, który jest w Jerozolimie, i do całego domu Izraela, który tam się znajduje.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 11, 'Powiedz im: Ja jestem waszym znakiem. Jak uczyniłem, tak się im stanie: Pójdą na wygnanie, w niewolę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 12, 'A książę, który jest pośród nich, weźmie toboły na ramieniu o zmierzchu i wyjdzie. Przebiją mur, aby go przez niego przeprowadzić. Zakryje sobie twarz, aby swymi oczami nie widział ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 13, 'Rozciągnę bowiem nad nim swoją sieć i zostanie schwytany w moje sidła. Zaprowadzę go do Babilonu, do ziemi Chaldejczyków, lecz jej nie zobaczy, a tam umrze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 14, 'A wszystkich, którzy go otaczają, by mu pomóc, i wszystkie jego oddziały rozproszę na wszystkie wiatry i miecz na nich dobędę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 15, 'I poznają, że ja jestem Panem, gdy ich rozproszę między narody i rozrzucę po krajach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 16, 'Zachowam jednak niewielu z nich od miecza, głodu i zarazy, aby opowiadali o wszystkich swoich obrzydliwościach pomiędzy narodami, do których przybędą; i poznają, że ja jestem Panem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 17, 'I znowu doszło do mnie słowo Pana mówiące:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 18, 'Synu człowieczy, jedz swój chleb w strachu i pij swoją wodę z drżeniem i smutkiem;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 19, 'I powiedz do ludu tej ziemi: Tak mówi Pan Bóg o mieszkańcach Jerozolimy, o ziemi Izraela: Będą jeść swój chleb w smutku i będą pić swą wodę w trwodze, aby ich ziemia była ograbiona ze swoich dostatków z powodu bezprawia wszystkich jej mieszkańców;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 20, 'Także miasta, w których mieszkają, będą spustoszone, a ziemia opustoszeje: I poznacie, że ja jestem Panem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 21, 'I doszło do mnie słowo Pana mówiące:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 22, 'Synu człowieczy, cóż to jest za przysłowie u was o ziemi Izraela, które brzmi: Dłużą się dni, a każde widzenie zawodzi?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 23, 'Dlatego mów do nich: Tak mówi Pan Bóg: Sprawię, że to przysłowie ustanie i nie będą go więcej powtarzać w Izraelu. Powiedz im: Zbliżają się te dni i spełnienie wszelkiego widzenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 24, 'Nie będzie już bowiem żadnego marnego widzenia ani pochlebnej wróżby pośród domu Izraela;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 25, 'Gdyż ja, Pan, będę mówić, a słowo, które wypowiem, spełni się i nie ulegnie więcej opóźnieniu. Za waszych dni, domu buntowniczy, wypowiem słowo i wypełnię je, mówi Pan Bóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 26, 'I doszło do mnie słowo Pana mówiące:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 27, 'Synu człowieczy, oto dom Izraela mówi: To widzenie, które on ma, odnosi się do dni odległych, on prorokuje o czasach dalekich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 28, 'Dlatego powiedz im: Tak mówi Pan Bóg: Żadne z moich słów już się nie opóźni, ale słowo, które wypowiem, spełni się, mówi Pan Bóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 1, 'I doszło do mnie słowo Pana mówiące:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 2, 'Synu człowieczy, prorokuj przeciw prorokom Izraela, którzy prorokują, i mów do tych, którzy prorokują z własnego serca: Słuchajcie słowa Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 3, 'Tak mówi Pan Bóg: Biada głupim prorokom, którzy idą za swoim duchem, choć nic nie widzieli!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 4, 'Izraelu, twoi prorocy są jak lisy na pustyniach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 5, 'Nie wstąpiliście na wyłomy ani nie uzupełniliście muru wokół domu Izraela, aby mógł ostać się w bitwie w dzień Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 6, 'Widzą ułudę i kłamliwe wróżby i mówią: Pan mówi, choć Pan ich nie posłał. I dają nadzieję ludowi, że ich słowo się spełni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 7, 'Czy nie mieliście złudnego widzenia i nie głosiliście kłamliwej wróżby? Mówicie bowiem: Pan mówi, chociaż ja nie mówiłem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 8, 'Dlatego tak mówi Pan Bóg: Ponieważ mówicie rzeczy złudne i widzicie kłamstwo, oto ja jestem przeciwko wam, mówi Pan Bóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 9, 'I moja ręka będzie przeciwko prorokom, którzy widzą rzeczy złudne i wróżą kłamstwo. Nie będą w zgromadzeniu mego ludu i w poczet domu Izraela nie będą wpisani, i do ziemi Izraela nie wejdą. A poznacie, że ja jestem Pan Bóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 10, 'Dlatego, właśnie dlatego, że zwodzili mój lud, mówiąc: Pokój, choć nie było pokoju; jeden zbudował glinianą ścianę, a inni tynkowali ją słabym tynkiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 11, 'Mów do tych, którzy ją tynkują słabym tynkiem: Zawali się. Przyjdzie ulewny deszcz, a wy, wielkie kule gradu, spadniecie, i gwałtowny wiatr ją zburzy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 12, 'A oto gdy ściana runie, czy nie powiedzą wam: Gdzie jest tynk, którym tynkowaliście?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 13, 'Dlatego tak mówi Pan Bóg: W mojej zapalczywości zburzę ją gwałtownym wiatrem; na skutek mojego gniewu przyjdzie ulewny deszcz i na skutek mojego oburzenia przyjdzie wielki grad, by ją zniszczyć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 14, 'I zburzę tę ścianę, którą tynkowaliście słabym tynkiem, zrównam ją z ziemią tak, że jej fundamenty zostaną odsłonięte, i runie, a wy zginiecie pośród niej. I poznacie, że ja jestem Panem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 15, 'A gdy dopełnię mojego gniewu nad tą ścianą i nad tymi, którzy ją tynkowali słabym tynkiem, powiem do was: Nie ma już tej ściany, nie ma tych, którzy ją tynkowali;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 16, 'To jest proroków Izraela, którzy prorokują o Jerozolimie i mają o niej widzenia pokoju, choć nie ma pokoju, mówi Pan Bóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 17, 'Ale ty, synu człowieczy, zwróć swą twarz przeciwko córkom swego ludu, które prorokują z własnego serca, i prorokuj przeciwko nim;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 18, 'I mów: Tak mówi Pan Bóg: Biada tym kobietom, które szyją poduszki pod wszystkie łokcie rąk mego ludu i robią nakrycia głowy dla ludzi każdego wzrostu, aby łowić dusze! Czy będziecie łowić dusze mego ludu, aby zachować dusze, które przybędą do was?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 19, 'Bo bezcześcicie mnie wobec mego ludu dla garści jęczmienia i dla kęsa chleba, zabijając dusze, które nie powinny umrzeć, a oszczędzając dusze, które nie powinny żyć – gdy okłamujecie mój lud, który słucha kłamstwa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 20, 'Dlatego tak mówi Pan Bóg: Oto wystąpię przeciwko waszym poduszkom, którymi łowicie dusze, aby je zwieść. Zerwę je z waszych ramion i wypuszczę dusze, które łowicie, aby je zwieść.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 21, 'I rozerwę wasze nakrycia, i wybawię swój lud z waszej ręki, aby już nie był łupem w waszym ręku. I poznacie, że ja jestem Panem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 22, 'Ponieważ zasmucacie kłamstwem serce sprawiedliwego, chociaż ja go nie zasmuciłem, i wzmacniacie ręce bezbożnego, aby się nie odwrócił od swojej złej drogi, ożywiając go;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 23, 'Dlatego nie będziecie już mieć widzeń złudnych i nie będziecie prorokować żadnej wróżby. Wyrwę bowiem swój lud z waszej ręki i poznacie, że ja jestem Panem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 1, 'Potem przyszli do mnie niektórzy spośród starszych Izraela i usiedli przede mną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 2, 'I doszło do mnie słowo Pana mówiące:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 3, 'Synu człowieczy, ci ludzie postawili swoje bożki w swym sercu, a kamień potknięcia do nieprawości położyli przed twarzą. Czy uważasz, że szczerze pytają mnie o radę?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 4, 'Dlatego przemów do nich i powiedz im: Tak mówi Pan Bóg: Każdemu z domu Izraela, który stawia swoje bożki w swym sercu i położy przed twarzą kamień potknięcia do nieprawości, a przyjdzie do proroka, ja, Pan, odpowiem według liczby jego bożków;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 5, 'Aby uchwycić dom Izraela za serce, gdyż oni wszyscy odeszli ode mnie z powodu swoich bożków.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 6, 'Dlatego powiedz do domu Izraela: Tak mówi Pan Bóg: Nawróćcie się i odwróćcie się od swoich bożków, i odwróćcie swoje twarze od wszystkich waszych obrzydliwości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 7, 'Każdemu bowiem z domu Izraela i z obcych przebywających w Izraelu, który odwróci się od naśladowania mnie, a postawi swoje bożki w swym sercu, położy przed twarzą kamień potknięcia do nieprawości i przyjdzie do proroka, aby radzić się mnie przez niego, ja, Pan, sam mu odpowiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 8, 'I zwrócę swoją twarz przeciw temu człowiekowi, i uczynię z niego znak i przysłowie, i wytracę go spośród mego ludu. I poznacie, że ja jestem Panem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 9, 'A jeśli prorok dał się zwieść i mówił słowo, ja, Pan, zwiodłem tego proroka. Wyciągnę na niego swoją rękę i zgładzę go spośród mego ludu Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 10, 'I poniosą karę za swoją nieprawość: kara proroka będzie taka sama jak kara tego, który u niego się radził;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 11, 'Aby dom Izraela już więcej nie oddalał się ode mnie ani nie plamił się więcej swymi przestępstwami; aby był moim ludem, a ja – ich Bogiem, mówi Pan Bóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 12, 'Słowo Pana ponownie doszło do mnie mówiące:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 13, 'Synu człowieczy, jeśli ziemia zgrzeszy przeciwko mnie, niezmiernie dopuszczając się przestępstwa, wtedy wyciągnę na nią swą rękę, zniszczę jej zapas chleba, ześlę na nią głód i wytracę z niej ludzi i zwierzęta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 14, 'Choćby byli pośród niej ci trzej mężowie: Noe, Daniel i Hiob, to oni przez swoją sprawiedliwość wybawiliby tylko własne dusze, mówi Pan Bóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 15, 'A jeśli ześlę na ziemię dzikie zwierzęta, a one ją wyludnią i będzie spustoszona tak, że nikt nie będzie mógł przechodzić z powodu zwierząt;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 16, 'Jak żyję, mówi Pan Bóg, że choćby ci trzej mężowie byli pośród niej, żadną miarą nie wybawiliby ani synów, ani córek. Tylko oni sami byliby wybawieni, lecz ziemia byłaby spustoszona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 17, 'Albo jeśli sprowadzę miecz na tę ziemię i powiem do miecza: Przejdź przez tę ziemię; i wytracę z niej ludzi i zwierzęta;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 18, 'Jak żyję, mówi Pan Bóg – choćby ci trzej mężowie byli pośrodku niej, żadną miarą nie wybawiliby ani synów, ani córek, ale tylko oni sami byliby wybawieni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 19, 'Albo jeśli ześlę zarazę na tę ziemię i wyleję na nią swoją zapalczywość w sposób krwawy, aby wyniszczyć z niej ludzi i zwierzęta;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 20, 'Choćby Noe, Daniel i Hiob byli pośród niej, jak żyję, mówi Pan Bóg, żadną miarą nie wybawiliby ani syna, ani córki; oni przez swoją sprawiedliwość wybawiliby tylko swoje dusze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 21, 'Tak bowiem mówi Pan Bóg: Tym bardziej, gdy ześlę na Jerozolimę moje cztery ciężkie kary: miecz, głód, dzikie zwierzęta i zarazę, aby wytraciły z niej ludzi i zwierzęta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 22, 'Oto jednak zostanie w niej resztka, która zostanie wyprowadzona – synowie i córki. Oto oni wyjdą do was i zobaczycie ich drogę i czyny, a wy będziecie pocieszeni z powodu tego nieszczęścia, które sprowadziłem na Jerozolimę – wszystkiego, co sprowadziłem na nią.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 23, 'I oni będą was pocieszać, gdy zobaczycie ich drogę i czyny. I zrozumiecie, że tego wszystkiego, co w niej uczyniłem, nie uczyniłem bez przyczyny, mówi Pan Bóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 1, 'Wtedy doszło do mnie słowo Pana mówiące:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 2, 'Synu człowieczy, w czym jest lepsze drzewo winogronowe od wszelkiego innego drzewa albo od latorośli, która jest wśród drzew leśnych?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 3, 'Czy weźmie się z niego drewno do zrobienia czegoś? Czy zrobią z niego kołek do zawieszania na nim jakiegoś naczynia?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 4, 'Oto w ogień rzuca się je na spalenie; ogień strawi oba jego końce, a środek jego jest zwęglony. Na co się jeszcze przyda?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 5, 'Oto póki było całe, nic nie można było z niego zrobić. Tym bardziej gdy strawił je ogień i spaliło się, na nic się więcej nie przyda.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 6, 'Dlatego tak mówi Pan Bóg: Jak wśród drzew leśnych jest drzewo winogronowe, które wydałem ogniowi na spalenie, tak też wydam mieszkańców Jerozolimy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 7, 'Zwrócę bowiem swoją twarz przeciwko nim; z jednego ognia wyjdą, a drugi ogień ich strawi. I poznacie, że ja jestem Panem, gdy zwrócę swoją twarz przeciwko nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 8, 'I zamienię ich ziemię w spustoszenie, bo dopuścili się przestępstwa, mówi Pan Bóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 1, 'I doszło do mnie słowo Pana mówiące:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 2, 'Synu człowieczy, uświadom Jerozolimie jej obrzydliwości;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 3, 'I powiedz: Tak mówi Pan Bóg do Jerozolimy: Twoje pochodzenie i twój ród wywodzą się z ziemi Kanaan; twój ojciec był Amorytą, a twoja matka – Chetytką.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 4, 'A takie były twoje narodziny: W dniu, kiedy się urodziłaś, nie odcięto ci pępowiny ani nie obmyto cię wodą, aby cię oczyścić; nie natarto cię solą ani w pieluszki nie owinięto.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 5, 'Żadne oko nie zlitowało się nad tobą, aby uczynić wobec ciebie jedną z tych rzeczy i okazać ci współczucie. Ale porzucono cię na otwartym polu, brzydząc się tobą w dniu, kiedy się urodziłaś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 6, 'A gdy przechodziłem obok ciebie i widziałem cię podaną na podeptanie w twojej krwi, powiedziałem ci leżącej w swojej krwi: Żyj! Tak, powiedziałem do ciebie, leżącej w swojej krwi: Żyj!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 7, 'Rozmnożyłem cię jak kwiat polny, a rozmnożyłaś się i stałaś się wielka, i doszłaś do pełnej urody. Twoje piersi nabrały kształtów, a twoje włosy urosły, chociaż byłaś naga i odkryta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 8, 'A gdy przechodziłem obok ciebie i spojrzałem na ciebie, oto był to twój czas, czas miłości, rozciągnąłem połę swojej szaty na ciebie i zakryłem twoją nagość, związałem się z tobą przysięgą i zawarłem z tobą przymierze, mówi Pan Bóg. I stałaś się moja.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 9, 'Potem obmyłem cię wodą, zmyłem z ciebie twoją krew i namaściłem cię olejkiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 10, 'Następnie przyodziałem cię szatą haftowaną, włożyłem ci buty z kosztownej skóry, opasałem bisiorem i okryłem cię jedwabiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 11, 'Przystroiłem cię klejnotami, włożyłem bransolety na twoje ręce i złoty łańcuch na szyję.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 12, 'Włożyłem wisiorek na twoje czoło, kolczyki w twoje uszy i ozdobną koronę na twoją głowę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 13, 'Tak zostałaś przystrojona złotem i srebrem, a twoje szaty były z bisioru, jedwabiu i z tkaniny haftowanej; jadałaś najlepszą mąkę, miód i oliwę. Byłaś bardzo piękna i tak ci się powodziło, że stałaś się królestwem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 14, 'Twoja sława rozeszła się wśród narodów z powodu twojej piękności. Była bowiem doskonała dzięki mojej ozdobie, którą włożyłem na ciebie, mówi Pan Bóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 15, 'Ale zaufałaś swojej piękności i uprawiałaś nierząd, będąc tak sławna; uprawiałaś nierząd z każdym, kto przechodził. Jemu się oddawałaś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 16, 'Nabrałaś swoich szat i uczyniłaś sobie wyżyny o rozmaitych barwach, i na nich uprawiałaś nierząd, co nigdy więcej nie przyjdzie ani czego nigdy więcej nie będzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 17, 'Ponadto nabrałaś swoich pięknych klejnotów z mojego złota i srebra, które ci dałem, uczyniłaś sobie posągi mężczyzn i uprawiałaś z nimi nierząd.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 18, 'Wzięłaś też swe haftowane szaty i odziałaś je, kładłaś przed nimi moją oliwę i moje kadzidło;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 19, 'Nawet mój chleb, który ci dałem, najlepszą mąkę, oliwę i miód, którymi cię karmiłem, kładłaś przed nimi jako miłą woń. Tak było, mówi Pan Bóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 20, 'Brałaś też swoich synów i swoje córki, które mi urodziłaś, i składałaś je im w ofierze na pożarcie. Czy za mało było twojego nierządu?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 21, 'Zabijałaś przecież moje dzieci i oddawałaś je, aby przenoszono je przez ogień dla bożków.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 22, 'We wszystkich swoich obrzydliwościach i nierządach nie pamiętałaś o dniach twojej młodości, gdy byłaś naga, odkryta i oddana na podeptanie w swojej krwi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 23, 'A po całej twojej niegodziwości (biada, biada tobie! – mówi Pan Bóg);');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 24, 'Zbudowałaś sobie wzniosłe miejsce i zrobiłaś sobie wyżyny na każdej ulicy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 25, 'Na każdym rozstaju dróg budowałaś swoje wyżyny i swoją piękność uczyniłaś wstrętną; rozkładałaś swoje nogi przed każdym, kto przechodził, i rozmnożyłaś swoje nierządne czyny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 26, 'Uprawiałaś nierząd z Egipcjanami, z twoimi sąsiadami o potężnych ciałach, i rozmnożyłaś swoje nierządy, aby pobudzić mnie do gniewu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 27, 'Dlatego oto ja wyciągnąłem przeciw tobie swoją rękę i zmniejszyłem twoją porcję, i wydałem cię żądzy nienawidzących cię córek Filistynów, które się wstydzą twojej rozwiązłej drogi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 28, 'Uprawiałaś też nierząd z Asyryjczykami, bo byłaś nienasycona; cudzołożyłaś z nimi, a i tak się nie nasyciłaś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 29, 'Rozmnożyłaś też swoje nierządy w ziemi Kanaan i Chaldei, a i tak się nie nasyciłaś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 30, 'O jak słabe jest twoje serce – mówi Pan Bóg – że się dopuszczasz tych rzeczy, postępków bezwstydnej nierządnicy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 31, 'Budując sobie wzniosłe miejsca na każdym rozstaju dróg i stawiając sobie wyżynę na każdej ulicy; gardząc jednak zapłatą, nie byłaś podobna do nierządnicy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 32, 'Lecz do żony cudzołożnej, która zamiast swego męża dopuszcza obcych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 33, 'Wszystkim nierządnicom daje się zapłatę, lecz ty dajesz swe dary wszystkim swoim kochankom i wynagradzasz im, aby przychodzili do ciebie zewsząd i uprawiali z tobą nierząd.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 34, 'U ciebie, w twoim nierządzie, dzieje się odwrotnie niż u innych kobiet. Nikt nie goni za tobą, by uprawiać nierząd. To ty dajesz zapłatę, a tobie nie dają zapłaty. U ciebie jest na odwrót.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 35, 'Dlatego, nierządnico, słuchaj słowa Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 36, 'Tak mówi Pan Bóg: Ponieważ wylała się twoja nieczystość i odkryła się twoja nagość przez twój nierząd z twoimi kochankami i ze wszystkimi twymi obrzydłymi bożkami i przez rozlanie krwi twoich dzieci, które im dałaś;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 37, 'Oto zgromadzę wszystkich kochanków, z którymi obcowałaś, i wszystkich, których kochałaś, wraz ze wszystkimi, których nienawidziłaś; zgromadzę ich zewsząd przeciwko tobie i odkryję twoją nagość przed nimi, aby widzieli całą twoją nagość.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 38, 'I osądzę cię tak, jak sądzi się cudzołożnice i przelewających krew; i oddam ci w zamian krew w gniewie i zazdrości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 39, 'Wydam cię w ich ręce, a oni zburzą twoje wzniosłe miejsca, zniszczą twoje wyżyny, rozbiorą cię z twoich szat, zabiorą ci twoje piękne klejnoty i zostawią cię nagą i odkrytą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 40, 'Zwołają przeciw tobie zgromadzenie i ukamienują cię, i przebiją cię swoimi mieczami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 41, 'I spalą twoje domy w ogniu, i wykonają na tobie sąd na oczach wielu kobiet. I sprawię, że przestaniesz być nierządnicą, i więcej nie będziesz dawała zapłaty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 42, 'Tak uśmierzę swój gniew na tobie i odstąpi od ciebie moja zazdrość; uspokoję się i już nie będę się gniewał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 43, 'Ponieważ nie pamiętałaś o dniach swojej młodości, ale tym wszystkim mnie drażniłaś, oto i ja złożę ci na głowę twoją własną drogę, mówi Pan Bóg. Nie popełnisz już tej rozwiązłości ponad wszystkie twoje obrzydliwości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 44, 'Oto każdy, kto mówi przysłowia, wypowie o tobie takie przysłowie: Jaka matka, taka jej córka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 45, 'Ty jesteś córką swojej matki, która obrzydziła sobie swego męża i swoje dzieci; jesteś siostrą obu swoich sióstr, które obrzydziły sobie swoich mężów i swoje dzieci. Wasza matka była Chetytką, a wasz ojciec – Amorytą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 46, 'Twoją starszą siostrą jest Samaria, która wraz z córkami mieszka po twojej lewicy; a twoją młodszą siostrą jest Sodoma, która mieszka wraz z jej córkami po twojej prawicy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 47, 'Ty jednak nie kroczyłaś ich drogami ani nie popełniłaś takich obrzydliwości jak one. Ale uważając to za małą rzecz, zepsułaś się bardziej niż one na wszystkich swoich drogach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 48, 'Jak żyję, mówi Pan Bóg, twoja siostra Sodoma i jej córki nie czyniły tak, jak ty czyniłaś wraz ze swoimi córkami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 49, 'Oto taka była nieprawość Sodomy, twojej siostry: pycha, dostatek chleba i wielkie próżniactwo były w niej i jej córkach, nie wzmacniała też ręki ubogiego i nędznego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 50, 'Były wyniosłe i popełniały obrzydliwość przede mną. Dlatego usunąłem je, jak uważałem za słuszne.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 51, 'A Samaria nie popełniła nawet połowy twoich grzechów, bo rozmnożyłaś swoje obrzydliwości bardziej niż ona i usprawiedliwiłaś swoje siostry wszystkimi twymi obrzydliwościami, które popełniłaś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 52, 'Ty więc, która sądziłaś swoje siostry, znoś swoją hańbę z powodu twoich grzechów, bo obrzydliwsze od nich popełniłaś. One są sprawiedliwsze od ciebie. Wstydź się więc i znoś swoją hańbę, gdyż usprawiedliwiłaś swoje siostry.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 53, 'Kiedy odwrócę ich niewolę, to jest niewolę Sodomy i jej córek i niewolę Samarii i jej córek, to wtedy też odwrócę niewolę twoich pojmanych pośród nich;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 54, 'Abyś znosiła swoją hańbę i wstydziła się z powodu wszystkiego, co uczyniłaś, sprawiając im pociechę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 55, 'Jeśli twoje siostry, Sodoma i jej córki, wrócą do swego pierwotnego stanu, a także Samaria i jej córki wrócą do swego pierwotnego stanu, wtedy również i ty ze swoimi córkami wrócisz do swego pierwotnego stanu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 56, 'W dniu twojej pychy bowiem nie było mowy w twoich ustach o twojej siostrze Sodomie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 57, 'Dopóki nie została odkryta twoja niegodziwość; jak za czasu twojego pohańbienia doznanego od córek Syrii i wszystkich, którzy są dokoła nich, od córek Filistynów, które tobą gardzą ze wszystkich stron.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 58, 'Ponosisz karę za swoją rozwiązłość i obrzydliwość, mówi Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 59, 'Tak bowiem mówi Pan Bóg: Uczynię ci tak, jak ty uczyniłaś, gdy wzgardziłaś przysięgą i złamałaś przymierze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 60, 'Ja jednak wspomnę na swoje przymierze z tobą zawarte za dni twojej młodości i ustanowię z tobą wieczne przymierze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 61, 'Wtedy wspomnisz swoje drogi i zawstydzisz się, gdy przyjmiesz swoje siostry, starsze i młodsze od ciebie, i dam ci je za córki, ale nie według twego przymierza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 62, 'Tak ustanowię swoje przymierze z tobą. I poznasz, że ja jestem Panem;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 63, 'Abyś pamiętała i wstydziła się, i nigdy więcej nie otworzyła ust ze wstydu, gdy cię oczyszczę ze wszystkiego, co uczyniłaś, mówi Pan Bóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 1, 'I doszło do mnie słowo Pana mówiące:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 2, 'Synu człowieczy, zadaj zagadkę i opowiedz domowi Izraela przypowieść;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 3, 'I powiedz: Tak mówi Pan Bóg: Wielki orzeł o wielkich i długich skrzydłach, pełen pstrego pierza, przyleciał nad Liban i wziął wierzchołek cedru.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 4, 'Ułamał koniec jego pędów, zaniósł go do ziemi kupieckiej i złożył go w mieście kupieckim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 5, 'Wziął też nasienie tej ziemi i zasadził na urodzajnym polu; umieścił je nad wielkimi wodami jak wierzbę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 6, 'I urosło, i stało się bujną winoroślą, choć niskiego wzrostu; jej latorośle zwracały się ku niemu, a korzenie były mu poddane. I stało się winoroślą, która wydała latorośle i wypuściła pędy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 7, 'Ale był inny wielki orzeł o wielkich skrzydłach i gęstym pierzu, a oto ta winorośl zwróciła swoje korzenie ku niemu i rozciągnęła swe latorośle do niego, aby on ją nawadniał z bruzd swego sadu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 8, 'A była przecież zasadzona na dobrym polu, nad wielkimi wodami, aby wypuściła latorośle, wydała owoc i stała się wspaniałą winoroślą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 9, 'Wtedy powiedz: Tak mówi Pan Bóg: Czy się jej poszczęści? Czy orzeł nie wyrwie jej korzeni i nie oberwie jej owocu tak, by uschła? Uschną wszystkie listki, które wypuści, i nie będzie trzeba wielkiej mocy ani licznego ludu, aby ją wyrwać z korzeniami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 10, 'Oto jakkolwiek będzie zasadzona, czy się jej poszczęści? Czy doszczętnie nie uschnie, gdy dotknie ją wiatr wschodni? Uschnie w bruzdach, w których wyrosła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 11, 'Potem doszło do mnie słowo Pana:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 12, 'Mów teraz do domu buntowniczego: Czyż nie wiecie, co znaczą te rzeczy? Powiedz: Oto król Babilonu przybył do Jerozolimy, zabrał jej króla i książąt i uprowadził ich ze sobą do Babilonu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 13, 'Wziął też jednego z potomków króla, zawarł z nim przymierze i związał go przysięgą. Zabrał też możnych tej ziemi;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 14, 'Aby królestwo było poniżone, tak by się nie podnosiło, ale by tak trwało, zachowując jego przymierze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 15, 'Lecz on zbuntował się przeciwko niemu, wysyłając swych posłów do Egiptu, aby dano mu koni i liczny lud. Czy mu się poszczęści? Czy ujdzie zemsty ten, który tak czynił? Czy ocali się ten, który złamał przymierze?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 16, 'Jak żyję, mówi Pan Bóg, w miejscu tego króla, który go uczynił królem, a którego przysięgą wzgardził i którego przymierze złamał, u niego w Babilonie umrze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 17, 'I ani faraon z wielkim wojskiem i z licznym zastępem nie pomoże mu na wojnie, gdy usypie wały i pobuduje wieże, aby zniszczyć mnóstwo ludzi;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 18, 'Ponieważ wzgardził przysięgą, łamiąc przymierze. Oto bowiem dał na to swą rękę, a to wszystko uczynił. Nie ujdzie zemsty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 19, 'Dlatego tak mówi Pan Bóg: Jak żyję, moją przysięgę, którą wzgardził, i moje przymierze, które złamał, złożę mu na głowę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 20, 'Rozciągnę na nim swoją sieć i zostanie schwytany w moje sidła, i zaprowadzę go do Babilonu, a tam się z nim rozprawię za jego występek, którym zgrzeszył przeciwko mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 21, 'A wszyscy, którzy uciekli od niego wraz ze wszystkimi jego hufcami, od miecza polegną, a pozostali zostaną rozproszeni na wszystkie wiatry. I poznacie, że ja, Pan, to powiedziałem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 22, 'Tak mówi Pan Bóg: Wezmę wierzchołek tego wysokiego cedru i zasadzę; z najwyższych jego gałązek odłamię młodą gałązkę i zasadzę ją na wysokiej i wyniosłej górze;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 23, 'Na wysokiej górze Izraela ją zasadzę. Wypuści gałązki, wyda owoc i stanie się cedrem wspaniałym. I będzie mieszkać pod nim wszelkie ptactwo skrzydlate; pod cieniem jego gałęzi będą mieszkać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 24, 'A tak wszystkie drzewa polne poznają, że ja, Pan, poniżyłem drzewo wysokie, a wywyższyłem drzewo niskie, ususzyłem drzewo zielone, a sprawiłem, że zakwitło drzewo suche. Ja, Pan, to powiedziałem i uczynię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 1, 'I doszło do mnie słowo Pana mówiące:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 2, 'Dlaczego powtarzacie między sobą takie przysłowie o ziemi Izraela, mówiąc: Ojcowie jedli kwaśne winogrona, a synom zęby cierpną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 3, 'Jak żyję, mówi Pan Bóg, nie będziecie więcej powtarzać tego przysłowia w Izraelu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 4, 'Oto wszystkie dusze są moje, tak dusza ojca, jak i dusza syna jest moja. Dusza, która grzeszy, ona umrze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 5, 'Lecz jeśli człowiek jest sprawiedliwy i wykonuje sąd i sprawiedliwość;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 6, 'I nie jadał na górach, nie podnosi swych oczu ku bożkom domu Izraela ani nie hańbił żony swego bliźniego, ani nie zbliżał się do kobiety podczas jej nieczystości;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 7, 'Nikogo nie uciskał, zwracał zastaw dłużnikowi, nie popełnił grabieży, dawał swój chleb głodnemu i przyodziewał nagiego szatą;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 8, 'Nie uprawiał lichwy i nie brał odsetek, odwracał swą rękę od nieprawości i sprawiedliwy sąd wykonywał między jednym człowiekiem a drugim;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 9, 'Postępował według moich ustaw i przestrzegał moich sądów, czyniąc to, co prawe – ten jest sprawiedliwy, na pewno żyć będzie, mówi Pan Bóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 10, 'A jeśli spłodził syna zbójcę i rozlewającego krew, który popełnił jedną z tych rzeczy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 11, 'Który żadnej z tamtych dobrych rzeczy nie czynił, ale raczej jadał na górach, hańbił żonę swego bliźniego;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 12, 'Uciskał ubogiego i nędznego, popełniał grabież, nie zwracał zastawu, podnosił oczy ku bożkom, czynił obrzydliwość;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 13, 'Uprawiał lichwę i brał odsetki – czy ten będzie żył? Nie będzie żył, ponieważ popełnił te wszystkie obrzydliwości. Ten na pewno umrze. Jego krew spadnie na niego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 14, 'A oto jeśli spłodził syna, który widział wszystkie grzechy swego ojca, jakie czynił, a widząc je, nie czynił nic podobnego;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 15, 'Nie jadał na górach, nie podnosił swych oczu ku bożkom domu Izraela, nie hańbił żony swego bliźniego;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 16, 'Nikogo nie uciskał, nie zatrzymywał zastawu, nie popełniał grabieży, dawał swój chleb głodnemu i przyodziewał szatą nagiego;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 17, 'Odwracał swą rękę od ucisku nad ubogim, nie uprawiał lichwy i nie brał odsetek, wykonywał moje sądy i postępował według moich ustaw – ten nie umrze za nieprawość swego ojca, ale na pewno będzie żył.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 18, 'Lecz jego ojciec, ponieważ czynił krzywdę, popełniał grabież i nie czynił tego, co dobre pośród swego ludu, oto umrze za swoją nieprawość.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 19, 'Ale mówicie: Czemu? Czy syn nie ponosi kary za nieprawość ojca? Gdy syn czynił to, co prawe i sprawiedliwe, i przestrzegał wszystkich moich ustaw, i wypełniał je, na pewno będzie żył.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 20, 'Dusza, która grzeszy, umrze. Syn nie poniesie kary za nieprawość ojca ani ojciec nie poniesie kary za nieprawość syna. Sprawiedliwość sprawiedliwego pozostanie na nim, a niegodziwość niegodziwego pozostanie na nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 21, 'A jeśli niegodziwy odwróci się od wszystkich swoich grzechów, które popełnił, będzie strzegł wszystkich moich ustaw i będzie czynił to, co prawe i sprawiedliwe, na pewno będzie żył, nie umrze;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 22, 'Żadne jego występki, których się dopuścił, nie będą mu wspominane. Będzie żył w swej sprawiedliwości, którą czynił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 23, 'Czyż ja mam upodobanie w śmierci niegodziwego? – mówi Pan Bóg, a nie raczej w tym, aby się odwrócił od swoich dróg i żył?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 24, 'Ale jeśli sprawiedliwy odwróci się od swojej sprawiedliwości i popełni nieprawość, czyniąc według wszystkich obrzydliwości, które popełnia niegodziwy, czy taki będzie żył? Wszystkie jego sprawiedliwości, które czynił, nie będą wspominane. Z powodu swego przestępstwa, które popełniał, i z powodu swego grzechu, którego się dopuścił, z powodu tych rzeczy umrze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 25, 'Ale mówicie: Droga Pana nie jest słuszna. Słuchajcie teraz, domu Izraela: Czy moja droga nie jest prosta? Czy raczej wasze drogi są niesłuszne?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 26, 'Gdy sprawiedliwy odwróci się od swojej sprawiedliwości, a czyniąc nieprawość umrze, to z powodu swojej nieprawości, którą czynił, umrze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 27, 'Ale gdy niegodziwy odwróci się od swojej niegodziwości, której się dopuścił, a czyni to, co prawe i sprawiedliwe, ten zachowa swoją duszę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 28, 'Ponieważ zastanowił się i odwrócił się od wszystkich swoich występków, których się dopuścił, na pewno będzie żył, nie umrze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 29, 'A jednak dom Izraela mówi: Droga Pana nie jest słuszna. Czy moje drogi nie są słuszne, domu Izraela? Czy raczej wasze drogi są niesłuszne?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 30, 'Dlatego, domu Izraela, będę sądzić każdego z was według jego dróg, mówi Pan Bóg. Nawróćcie się i odwróćcie się od wszystkich swoich występków, aby nieprawość nie stała się waszą zgubą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 31, 'Odrzućcie od siebie wszystkie swoje przestępstwa, których się dopuszczaliście, i uczyńcie sobie nowe serce i nowego ducha. Czemu macie umrzeć, domu Izraela?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 32, 'Nie mam bowiem żadnego upodobania w śmierci umierającego, mówi Pan Bóg. Odwróćcie się więc, a będziecie żyć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 1, 'A ty podnieś lament nad książętami Izraela;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 2, 'I mów: Czym była twoja matka? Lwicą leżącą między lwami, która karmiła swoje szczenięta wśród lwiąt.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 3, 'A gdy odchowała jedno ze swoich szczeniąt, stało się młodym lwem, który się nauczył chwytać łup; pożerał też ludzi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 4, 'Narody o nim usłyszały, został schwytany w ich dół i zaprowadzony w łańcuchach do ziemi Egiptu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 5, 'Gdy lwica zobaczyła, że daremnie czeka i że jej nadzieja przepadła, wzięła inne ze swoich szczeniąt i uczyniła je młodym lwem;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 6, 'Chodziło w środku lwów i stało się młodym lwem, który nauczył się chwytać łup; pożerał też ludzi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 7, 'Burzył ich pałace i pustoszył ich miasta tak, że ziemia i to, co ją napełnia, stały się spustoszone od jego głośnego ryku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 8, 'Wtedy zebrały się przeciwko niemu narody z okolicznych krain i zarzuciły na niego swoją sieć. Został schwytany w ich dół.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 9, 'I wsadziły go do klatki w łańcuchach, i przyprowadziły do króla Babilonu. Wprowadziły go do ciężkiego więzienia, aby jego głos nie był więcej słyszany na górach Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 10, 'Twoja matka była jak winorośl w twojej krwi, zasadzona przy wodach. Była płodna i gałęzista dzięki obfitości wód.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 11, 'I miała potężne rózgi na berła dla panujących, a jej wzrost górował nad gęstymi gałęziami tak, że była widoczna z powodu swej wysokości dzięki mnóstwu swoich gałęzi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 12, 'Ale w gniewie została wyrwana i rzucona na ziemię, a wschodni wiatr wysuszył jej owoc. Jej potężne rózgi zostały złamane i uschły, ogień je strawił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 13, 'A teraz została zasadzona na pustyni, na ziemi suchej i spragnionej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 14, 'Nadto ogień wyszedł z rózgi jej gałęzi i pochłonął jej owoc tak, że nie ma na niej potężnej rózgi na berła dla panującego. Jest to lament i będzie to lamentem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 1, 'W siódmym roku, w piątym miesiącu, dziesiątego dnia tego miesiąca, przyszli niektórzy spośród starszych Izraela, aby radzić się Pana, i usiedli przede mną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 2, 'Wtedy doszło do mnie słowo Pana mówiące:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 3, 'Synu człowieczy, przemów do starszych Izraela i powiedz im: Tak mówi Pan Bóg: Czy przychodzicie, aby się mnie radzić? Jak żyję, nie pozwolę wam radzić się mnie, mówi Pan Bóg;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 4, 'Czy będziesz ich sądził, synu człowieczy, czy będziesz ich sądził? Uświadom im obrzydliwości ich ojców.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 5, 'Powiedz im: Tak mówi Pan Bóg: W dniu, kiedy wybrałem Izraela i podniosłem rękę ku potomstwu domu Jakuba, i dałem się im poznać w ziemi Egiptu, kiedy podniosłem rękę ku nim, mówiąc: ja jestem Panem, waszym Bogiem;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 6, 'Tego dnia podniosłem ku nim swoją rękę, że wyprowadzę ich z ziemi Egiptu do ziemi, którą im wyszukałem, opływającej mlekiem i miodem, która jest ozdobą wszystkich ziem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 7, 'I powiedziałem im: Niech każdy z was porzuci obrzydliwości sprzed swych oczu, a nie kalajcie się bożkami Egiptu. Ja jestem Panem, waszym Bogiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 8, 'Ale buntowali się i nie chcieli mnie słuchać: żaden z nich nie odrzucił obrzydliwości sprzed swych oczu ani nie opuścił bożków Egiptu. Wtedy powiedziałem: Wyleję na nich swój gniew, aby dopełnić na nich mojej zapalczywości w środku ziemi Egiptu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 9, 'Działałem ze względu na moje imię, aby nie było zbezczeszczone na oczach tych narodów, wśród których byli i przed których oczami dałem się im poznać, wyprowadzając ich z ziemi Egiptu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 10, 'A tak wyprowadziłem ich z ziemi Egiptu i przyprowadziłem na pustynię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 11, 'Dałem im moje ustawy i objawiłem im moje prawa, które jeśli człowiek wypełnia, będzie przez nie żył.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 12, 'Ponadto dałem im moje szabaty, aby były znakiem między mną a nimi, aby wiedzieli, że ja jestem Panem, który ich uświęca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 13, 'Ale dom Izraela zbuntował się przeciwko mnie na pustyni: nie postępowali według moich ustaw i wzgardzili moimi prawami, które jeśli człowiek wypełnia, będzie przez nie żył. Również moje szabaty bezcześcili. Dlatego powiedziałem, że wyleję na nich moją zapalczywość na pustyni, aby ich wytracić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 14, 'Lecz działałem ze względu na moje imię, aby nie było zbezczeszczone na oczach tych narodów, przed których oczami ich wyprowadziłem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 15, 'Ponadto podniosłem ku nim swą rękę na tej pustyni, że nie wprowadzę ich do ziemi, którą im dałem, opływającej mlekiem i miodem, która jest ozdobą wszystkich ziem;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 16, 'Ponieważ wzgardzili moimi prawami, nie postępowali według moich ustaw i bezcześcili moje szabaty, gdyż ich serce poszło za ich bożkami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 17, 'Ale moje oko zlitowało się nad nimi tak, że ich nie wytraciłem i nie wyniszczyłem na pustyni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 18, 'Powiedziałem do ich synów na tej pustyni: Nie postępujcie według ustaw waszych ojców i nie przestrzegajcie ich praw ani nie kalajcie się ich bożkami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 19, 'Ja jestem Panem, waszym Bogiem; postępujcie według moich ustaw, a strzeżcie moich praw i wypełniajcie je;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 20, 'Święćcie też moje szabaty, będą one znakiem między mną a wami, abyście wiedzieli, że ja jestem Panem, waszym Bogiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 21, 'Lecz ci synowie zbuntowali się przeciwko mnie: nie postępowali według moich ustaw, nie przestrzegali moich praw, aby je wypełnić; praw, które jeśli człowiek wypełnia, będzie przez nie żył, i zbezcześcili moje szabaty. Wtedy powiedziałem: Wyleję na nich swój gniew, aby dopełnić na nich mojej zapalczywości na tej pustyni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 22, 'Lecz cofnąłem moją rękę i działałem ze względu na moje imię, aby nie było zbezczeszczone na oczach tych narodów, przed których oczami ich wyprowadziłem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 23, 'Podniosłem ku nim moją rękę na pustyni, że ich rozproszę pomiędzy poganami i rozrzucę po ziemiach;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 24, 'Ponieważ nie wykonywali moich sądów, wzgardzili moimi ustawami, zbezcześcili moje szabaty, a ich oczy zwracały się ku bożkom ich ojców.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 25, 'Dlatego dałem im też ustawy, które nie były dobre, i sądy, według których nie mogli żyć;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 26, 'I splugawiłem ich własnymi ich darami, gdy przeprowadzili przez ogień wszystko, co pierworodne, aby ich spustoszyć, i aby poznali, że ja jestem Panem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 27, 'Dlatego, synu człowieczy, przemów do domu Izraela i powiedz mu: Tak mówi Pan Bóg: Jeszcze i w tym lżyli mnie wasi ojcowie, dopuszczając się przeciwko mnie przestępstwa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 28, 'Gdy bowiem wprowadziłem ich do ziemi, którą przysiągłem im dać, to gdy zobaczyli jakikolwiek wysoki pagórek i jakiekolwiek drzewa gałęziste, zaraz tam składali swoje ofiary i tam oddawali swoje drażniące dary, tam też składali swoją miłą woń i wylewali swoje ofiary z płynów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 29, 'I zapytałem ich: Cóż to za wyżyna, do której wy chodzicie? A nazywa się ją Bamah aż do dziś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 30, 'Dlatego powiedz domowi Izraela: Tak mówi Pan Bóg: Czy kalacie się drogami swoich ojców i uprawiacie nierząd z ich obrzydliwościami?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 31, 'Gdy składacie swoje ofiary i przeprowadzacie swoich synów przez ogień, to kalacie się wszystkimi waszymi bożkami aż do dziś. Czy mam pozwolić wam radzić się u mnie, domu Izraela? Jak żyję, mówi Pan Bóg, nie pozwolę wam się radzić u mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 32, 'A to, co wam na myśl przychodzi, nigdy się nie stanie. Mówicie bowiem: Będziemy jak inne narody, jak plemiona innych ziem, będziemy służyć drewnu i kamieniowi;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 33, 'Jak żyję, mówi Pan Bóg, potężną ręką, wyciągniętym ramieniem i w wylanej zapalczywości będę królował nad wami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 34, 'I wyprowadzę was spośród narodów i zgromadzę was z ziem, do których zostaliście rozproszeni, potężną ręką, wyciągniętym ramieniem i w wylanej zapalczywości;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 35, 'Zaprowadzę was na pustynię tych narodów i tam będę was sądzić twarzą w twarz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 36, 'Jak sądziłem waszych ojców na pustyni ziemi Egiptu, tak was będę sądzić, mówi Pan Bóg;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 37, 'I przeprowadzę was pod rózgą, i wprowadzę was w związek przymierza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 38, 'I oddzielę od was buntowników i tych, którzy grzeszą przeciwko mnie. Wyprowadzę ich z ziemi, gdzie przebywają, lecz do ziemi Izraela nie wejdą. I poznacie, że ja jestem Panem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 39, 'Wy więc, domu Izraela, tak mówi Pan Bóg: Idźcie i służcie, każdy swoim bożkom, nawet i w przyszłości, ponieważ mnie nie słuchacie; ale już więcej nie kalajcie mego świętego imienia waszymi darami i waszymi bożkami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 40, 'Na mojej świętej górze bowiem, na wysokiej górze Izraela, mówi Pan Bóg, tam cały dom Izraela będzie mi służyć, wszyscy, którzy będą w tej ziemi. Tam ich przyjmę i tam będę żądał waszych ofiar, waszych ofiar z pierwocin wraz ze wszystkimi waszymi świętymi rzeczami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 41, 'Z waszą miłą wonią przyjmę was łaskawie, gdy was wyprowadzę spośród narodów i zgromadzę was z tych ziem, do których zostaliście rozproszeni; i będę uświęcony w was na oczach tych narodów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 42, 'I poznacie, że ja jestem Panem, gdy was wprowadzę do ziemi Izraela, do tej ziemi, co do której podniosłem swoją rękę, że dam ją waszym ojcom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 43, 'Tam wspomnicie o waszych drogach i o wszystkich waszych czynach, którymi się splugawiliście; i obrzydzicie sobie siebie samych za wszystkie wasze złe czyny, które popełniliście.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 44, 'Tam poznacie, że ja jestem Panem, gdy postąpię z wami przez wzgląd na swoje imię, a nie według waszych złych dróg ani według waszych zepsutych czynów, domu Izraela, mówi Pan Bóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 45, 'I doszło do mnie słowo Pana mówiące:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 46, 'Synu człowieczy, odwróć swoją twarz w stronę południa i krop swoją mowę ku południu, i prorokuj przeciwko lasowi południowego pola;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 47, 'Powiedz do południowego lasu: Słuchaj słowa Pana: Tak mówi Pan Bóg: Oto rozniecę w tobie ogień, który strawi w tobie wszelkie drzewo zielone i wszelkie drzewo suche. Nie zostanie ugaszony płomień pałający i spłoną w nim wszystkie twarze od południa aż do północy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 48, 'I wszelkie ciało ujrzy, że ja, Pan, go rozpaliłem; nie będzie ugaszony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 49, 'I powiedziałem: Ach, Panie Boże! Oni mówią o mnie: On tylko mówi w przypowieściach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 1, 'I doszło do mnie słowo Pana mówiące:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 2, 'Synu człowieczy, odwróć swoją twarz w stronę Jerozolimy i krop swoją mowę ku świętym miejscom, i prorokuj przeciwko ziemi Izraela;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 3, 'Powiedz ziemi Izraela: Tak mówi Pan Bóg: Oto ja jestem przeciwko tobie i dobędę swój miecz z pochwy, i wytnę spośród ciebie sprawiedliwego i bezbożnego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 4, 'Ponieważ wytnę spośród ciebie sprawiedliwego i bezbożnego, mój miecz wyjdzie ze swej pochwy przeciwko wszelkiemu ciału od południa aż do północy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 5, 'I pozna wszelkie ciało, że ja, Pan, dobyłem swój miecz z pochwy i już do niej nie wróci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 6, 'A ty, synu człowieczy, wzdychaj, jakbyś miał złamane biodro, w goryczy wzdychaj na ich oczach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 7, 'A gdy zapytają: Dlaczego wzdychasz? – to odpowiesz: Z powodu wieści, która nadchodzi, bo każde serce się rozpłynie, wszystkie ręce osłabną, wszelki duch omdleje i wszystkie kolana rozpłyną się jak woda. Oto nadchodzi to i stanie się, mówi Pan Bóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 8, 'I doszło do mnie słowo Pana:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 9, 'Synu człowieczy, prorokuj i mów: Tak mówi Pan. Mów: Miecz, miecz jest wyostrzony i wypolerowany.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 10, 'Wyostrzony, aby dokonać rzezi, wypolerowany, aby lśnił. Czy mamy się cieszyć? Gdyż gardzi rózgą mego syna jak każdym drzewem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 11, 'Dał go na wypolerowanie, aby mógł być ujęty w dłoń, ten miecz jest wyostrzony, jest też wypolerowany, aby dać go w ręce zabójcy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 12, 'Wołaj i zawódź, synu człowieczy, gdyż ten miecz będzie przeciwko memu ludowi, przeciwko wszystkim książętom Izraela. Strach miecza przyjdzie na mój lud, dlatego uderz się w biodro.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 13, 'Jest to bowiem próba, a cóż jeśli miecz będzie gardzić rózgą? Już jej nie będzie, mówi Pan Bóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 14, 'Ty więc, synu człowieczy, prorokuj i bij dłonią o dłoń. Niech przyjdzie miecz drugi i trzeci raz, miecz zabitych, ten wielki miecz zabitych, przenikający aż do ich komnat.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 15, 'Postawiłem strach miecza we wszystkich ich bramach, aby ich serce się rozpłynęło i pomnożyły się ich upadki. Ach! Jest wypolerowany, aby błyszczeć, wyostrzony, aby zabić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 16, 'Zbierz się, mieczu, udaj się w prawo i w lewo, dokądkolwiek twoja twarz jest zwrócona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 17, 'Ja również uderzę dłonią o dłoń i uspokoję swoją zapalczywość. Ja, Pan, to powiedziałem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 18, 'Potem znowu doszło do mnie słowo Pana mówiące:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 19, 'A ty, synu człowieczy, wyznacz sobie dwie drogi, którymi ma przyjść miecz króla Babilonu. Obie niech wychodzą z jednej ziemi, wybierz miejsce na rozstaju dróg wiodących do miasta, wybierz je.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 20, 'Wyznacz drogę, którą ma przyjść miecz: do Rabby synów Ammona i do Judy w obwarowanej Jerozolimie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 21, 'Król Babilonu bowiem stanął na rozdrożu, na początku dwóch dróg, aby zasięgnąć wróżby: polerował strzały, radził się bożków, patrzył na wątrobę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 22, 'Wyrocznia wskazała na jego prawą rękę, na Jerozolimę, aby szykował dowódców, którzy mieli wydać rozkaz rzezi i podnieść okrzyk bojowy, aby ustawić tarany pod bramami, aby usypać wał i budować szańce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 23, 'I w ich oczach będzie to fałszywa wróżba, gdyż zobowiązali się przysięgami, lecz on im przypomni ich nieprawość, aby zostali pojmani.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 24, 'Dlatego tak mówi Pan Bóg: Ponieważ przypominacie mi swoją nieprawość, odsłaniając wasze przestępstwo tak, że wasze grzechy są jawne we wszystkich waszych czynach – ponieważ przypominacie mi o tym, zostaniecie pojmani tą ręką.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 25, 'A ty, nieczysty bezbożniku, księciu Izraela, którego dzień nadejdzie, gdy nastanie koniec ich nieprawości;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 26, 'Tak mówi Pan Bóg: Zdejmij diadem, zrzuć koronę. Ta już nigdy taka nie będzie. To, co niskie, będzie wywyższone, a to, co wysokie, będzie poniżone.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 27, 'Wniwecz, wniwecz, wniwecz ją obrócę. I już jej nie będzie, aż przyjdzie ten, który do niej ma prawo, i jemu ją oddam.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 28, 'Ale ty, synu człowieczy, prorokuj i mów: Tak mówi Pan Bóg o synach Ammona i o ich hańbie. Powiedz: Miecz, miecz jest dobyty, jest wypolerowany na rzeź, błyszczy, aby wytracić wszystko;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 29, 'Chociaż opowiadają ci złudne widzenia i wróżą kłamstwo, aby cię przyłożyć do szyi bezbożnych pobitych, których dzień nadejdzie, gdy nastanie koniec ich nieprawości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 30, 'Schowaj jednak miecz do pochwy. Będę cię sądził w miejscu, gdzie zostałeś stworzony, w ziemi twego pochodzenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 31, 'I wyleję na ciebie swoją zapalczywość, tchnę przeciwko tobie ogniem swojego gniewu i wydam cię w ręce okrutnych ludzi i wprawnych w wytraceniu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 32, 'Staniesz się strawą dla ognia, twoja krew będzie rozlana po całej ziemi, nie będziesz już wspominany, bo ja, Pan, to powiedziałem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 1, 'I doszło do mnie słowo Pana mówiące:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 2, 'A ty, synu człowieczy, czy zechcesz sądzić, czy zechcesz sądzić to krwawe miasto? Uświadom mu więc wszystkie jego obrzydliwości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 3, 'Powiedz: Tak mówi Pan Bóg: O miasto, które rozlewasz krew u siebie, aby przyszedł twój czas, i czynisz sobie bożki przeciwko sobie, aby się nimi plugawić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 4, 'Przez krew, którąś przelało, jesteś winne, i przez swoje bożki, któreś robiło, jesteś skalane, i tyś sprawiło, że przybliżyły się twoje dni, tyś doszło do swoich lat. Dlatego wydam cię na pohańbienie narodom i na pośmiewisko wszystkim ziemiom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 5, 'Ci, którzy są blisko, i ci, którzy są daleko od ciebie, będą się z ciebie naśmiewać, o miasto złej sławy i pełne zgiełku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 6, 'Oto książęta Izraela, każdy był w tobie, po to, aby całą siłą krew rozlewać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 7, 'W tobie ojca i matkę znieważają, u ciebie czynią krzywdę przybyszowi, w tobie uciskają sierotę i wdowę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 8, 'Wzgardzasz moimi świętymi rzeczami i zbezczeszczasz moje szabaty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 9, 'W tobie są oszczercy w celu rozlania krwi, w tobie jadają na górach, u ciebie popełniają czyny haniebne.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 10, 'W tobie odkrywa się nagość ojca, w tobie hańbią oddaloną z powodu jej nieczystości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 11, 'Jeden popełnia obrzydliwość z żoną swego bliźniego, drugi sprośnie plami swoją synową, inny zaś u ciebie hańbi swoją siostrę, córkę swego ojca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 12, 'W tobie biorą dary za rozlanie krwi, pobierasz lichwę i odsetki, wyzyskujesz swego bliźniego przez ucisk i zapominasz o mnie, mówi Pan Bóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 13, 'Dlatego oto ja klasnąłem w swą dłoń z powodu twego nieuczciwego zysku, któreś zdobyło, i z powodu krwi, którą u ciebie rozlano.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 14, 'Czy twoje serce wytrzyma? Czy twoje ręce będą na tyle mocne w dniach, kiedy ja będę miał z tobą sprawę? Ja, Pan, to powiedziałem i uczynię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 15, 'Rozproszę cię między poganami i rozrzucę cię po ziemiach, i usunę z ciebie twoją nieczystość.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 16, 'I będziesz splugawione na oczach pogan, i poznasz, że ja jestem Panem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 17, 'Potem doszło do mnie słowo Pana mówiące:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 18, 'Synu człowieczy, dom Izraela zamienił mi się w żużel; wszyscy są miedzią, cyną, żelazem i ołowiem w środku pieca; stali się żużlem srebra.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 19, 'Dlatego tak mówi Pan Bóg: Ponieważ wy wszyscy staliście się żużlem, oto zgromadzę was w środku Jerozolimy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 20, 'Jak gromadzi się srebro, miedź, żelazo, ołów i cynę wewnątrz pieca, aby rozdmuchano na nie ogień, by je roztopić, tak was zgromadzę w swojej zapalczywości i w swoim gniewie, złożę was i roztopię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 21, 'Tak, zgromadzę was i rozdmucham na was ogień swojej zapalczywości i zostaniecie roztopieni w jej środku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 22, 'Jak topi się srebro w środku pieca, tak i wy zostaniecie roztopieni w jej środku; i poznacie, że ja, Pan, wylałem na was swoją zapalczywość.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 23, 'Ponadto doszło do mnie słowo Pana:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 24, 'Synu człowieczy, mów do niej: Ty jesteś ziemią nieoczyszczoną i nieobmytą deszczem w dniu mojej zapalczywości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 25, 'W środku tej ziemi znajduje się spisek jej proroków, podobni są oni do ryczącego lwa, co rozdziera zdobycz. Pożerają dusze, zabierają bogactwa i kosztowności i mnożą wdowy pośród niej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 26, 'Jej kapłani złamali moje prawo i plugawią moje święte rzeczy. Nie czynią różnicy między tym, co święte, a tym, co pospolite, nie rozsądzają między nieczystym a czystym. Ponadto zakrywają sobie oczy przed moimi szabatami, tak że doznaję zniewagi pośród nich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 27, 'Jej książęta pośród niej są jak wilki rozdzierające zdobycz, rozlewające krew i tracące dusze, aby zdobyć nieuczciwy zysk.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 28, 'A jej prorocy tynkują słabym tynkiem, głosząc złudne widzenia i wróżąc im kłamstwo, mówiąc: Tak mówi Pan Bóg, choć Pan nie mówił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 29, 'Lud tej ziemi dopuszcza się ucisku i dokonuje grabieży; krzywdzi ubogiego i nędznego i bezprawnie uciska cudzoziemca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 30, 'I szukałem wśród nich męża, który by naprawił mur i stanął w wyłomie przede mną w obronie ziemi, abym jej nie zniszczył. Ale nie znalazłem żadnego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 31, 'Wylałem więc na nich swój gniew, wyniszczyłem ich ogniem swojej zapalczywości. Złożyłem im na głowę ich własną drogę, mówi Pan Bóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 1, 'I doszło do mnie słowo Pana mówiące:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 2, 'Synu człowieczy, były dwie kobiety, córki jednej matki;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 3, 'One uprawiały nierząd w Egipcie, w swojej młodości uprawiały nierząd; tam ściskano ich piersi i tam przygniatano piersi ich dziewictwa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 4, 'A ich imiona: starsza Ohola, a jej siostra – Oholiba. One były moje i urodziły synów i córki. Ich imiona: Samaria to Ohola, a Jerozolima to Oholiba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 5, 'Ohola uprawiała nierząd, będąc moją, zapałała namiętnością do swoich kochanków, do Asyryjczyków, sąsiadów;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 6, 'Którzy byli odziani w błękit, dowódcy i rządcy, wszyscy oni to powabni młodzieńcy, jeźdźcy dosiadający koni;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 7, 'Popełniała z nimi nierząd, ze wszystkimi najlepszymi synami Asyrii i ze wszystkimi, do których pałała namiętnością; plamiła się wszystkimi ich bożkami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 8, 'Nie porzuciła też swego nierządu z Egiptu, bo spali z nią w jej młodości, przygniatali piersi jej dziewictwa i wylali na nią swój nierząd.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 9, 'Dlatego wydałem ją w ręce jej kochanków, w ręce Asyryjczyków, do których pałała namiętnością.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 10, 'Oni odsłonili jej nagość, zabrali jej synów i córki, a ją samą zabili mieczem. I stała się osławiona wśród kobiet, gdy wykonano na niej sąd.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 11, 'A choć widziała to jej siostra Oholiba, bardziej niż ona zapałała rozwiązłą miłością, a jej nierząd był jeszcze większy niż nierząd jej siostry.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 12, 'Do swych sąsiadów Asyryjczyków pałała namiętnością, do dowódców i rządców, i władców, ubranych w kosztowne szaty, do jeźdźców dosiadających konie, wszyscy oni to powabni młodzieńcy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 13, 'I widziałem, że się hańbiła i że obydwie kroczyły tą samą drogą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 14, 'Ale ta posunęła się jeszcze dalej w swoich nierządnych czynach, bo widząc mężczyzn wymalowanych na ścianie, obrazy Chaldejczyków malowane farbami;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 15, 'Opasanych wokół bioder pasami, z zawojami ufarbowanymi na głowach – a wszyscy oni z wyglądu jak bohaterowie, podobni do Babilończyków pochodzących z ziemi Chaldei;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 16, 'Pałała do nich namiętnością, jak tylko spojrzała na nich swymi oczami, i wyprawiła do nich posłańców, do Chaldei.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 17, 'Wtedy Babilończycy weszli do niej, na łoże miłości, i plamili ją swoim nierządem; a gdy się skalała z nimi, jej dusza odwróciła się od nich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 18, 'I gdy ujawniła swoje czyny nierządne i odsłoniła swoją nagość, moja dusza odwróciła się od niej, tak jak odwróciła się moja dusza od jej siostry.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 19, 'Lecz ona mnożyła swoje czyny nierządne, przypominając sobie dni swojej młodości, kiedy uprawiała nierząd w ziemi Egiptu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 20, 'I pałała namiętnością do ich kochanków, których ciała są jak ciała osłów, a ich wytrysk jak wytrysk koni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 21, 'Tak powróciłaś do rozwiązłości swojej młodości, gdy Egipcjanie przygniatali twoje piersi dla piersi twojej młodości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 22, 'Dlatego, Oholibo, tak mówi Pan Bóg: Oto pobudzę przeciwko tobie twoich kochanków, tych, od których odwróciła się twoja dusza, i sprowadzę ich zewsząd przeciwko tobie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 23, 'Babilończyków, wszystkich Chaldejczyków, Pekod, Szoa, Koa, a z nimi wszystkich Asyryjczyków. Oni wszyscy to powabni młodzieńcy, dowódcy i rządcy, dostojnicy i zacni ludzie, wszyscy jeżdżący na koniach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 24, 'I wyruszą przeciwko tobie na rydwanach, na wozach żelaznych, na furmankach i z gromadą narodów. Zewsząd rozłożą się przeciwko tobie z puklerzami, tarczami i hełmami. I dam im prawo, aby cię sądzili według swoich praw.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 25, 'I wyleję na ciebie swoją zazdrość, i obejdą się z tobą z gniewem. Odetną ci nos i uszy, a twoja resztka polegnie od miecza. Wezmą twoich synów i twoje córki, a to, co z ciebie zostanie, strawi ogień.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 26, 'I zdejmą z ciebie twoje szaty, i zabiorą ci twoje piękne klejnoty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 27, 'Tak położę kres twojej rozwiązłości i twojemu nierządowi, które przyniosłaś z ziemi Egiptu. Nie podniesiesz już ku nim swych oczu ani nie będziesz więcej wspominać Egiptu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 28, 'Tak bowiem mówi Pan Bóg: Oto wydam cię w ręce tych, których nienawidzisz, w ręce tych, od których odwróciła się twoja dusza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 29, 'I postąpią z tobą z nienawiścią, zabiorą ci cały twój dorobek, zostawią cię nagą i obnażoną i zostaną odkryte nagość twego nierządu, twoja rozwiązłość i twoje czyny nierządne.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 30, 'To ci się przydarzy, dlatego że uprawiałaś nierząd, naśladując pogan; dlatego że skalałaś się ich bożkami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 31, 'Chodziłaś drogą swojej siostry, dlatego dam jej kielich w twoją rękę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 32, 'Tak mówi Pan Bóg: Będziesz pić z kielicha swojej siostry, głębokiego i szerokiego, będziesz pośmiewiskiem i szyderstwem, bo on wiele zmieści.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 33, 'Będziesz napełniona pijaństwem i bólem, kielichem spustoszenia i smutku, kielichem twojej siostry Samarii.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 34, 'Wypijesz go i wychylisz do dna, potem go rozbijesz na kawałki, a swoje piersi poobrywasz. Ja bowiem to powiedziałem, mówi Pan Bóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 35, 'Dlatego tak mówi Pan Bóg: Ponieważ zapomniałaś o mnie i rzuciłaś mnie za swoje plecy, ty także znoś swoją rozwiązłość i swój nierząd.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 36, 'I Pan powiedział do mnie: Synu człowieczy, czy będziesz sądził Oholę i Oholibę? Uświadom im ich obrzydliwości;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 37, 'Że cudzołożyły i krew jest na ich rękach; z bożkami cudzołożyły, także swych synów, których mi urodziły, przeprowadziły przez ogień, by byli strawieni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 38, 'I jeszcze to mi uczyniły, że moją świątynię splugawiły w tym samym dniu i zbezcześciły moje szabaty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 39, 'Gdy bowiem zabiły swoje dzieci dla swoich bożków, wchodziły do mojej świątyni w tym samym dniu, aby ją zbezcześcić; oto tak czyniły wewnątrz mego domu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 40, 'Ponadto posyłały po mężczyzn, aby przyszli z daleka; wysłano więc posłańca, a oni przyszli. Dla nich się myłaś, barwiłaś swoje oczy i stroiłaś się w ozdoby;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 41, 'Siadałaś na wspaniałym łożu, przed którym był przygotowany stół i na którym kładłaś moje kadzidło i mój olejek.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 42, 'I rozległ się u niej głos beztroskiego tłumu, a wraz z ludem pospolitym przyprowadzono z pustyni Sabejczyków, którzy wkładali bransolety na ich ręce i ozdobne korony na ich głowy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 43, 'I powiedziałem do tej cudzołożnicy zestarzałej: Czy oni będą uprawiać nierząd z nią, a ona z nimi?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 44, 'I obcowali z nią, jak się obcuje z nierządnicą. Tak właśnie obcowali z Oholą i Oholibą, kobietami rozwiązłymi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 45, 'Dlatego mężowie sprawiedliwi będą je sądzić, jak się sądzi cudzołożnice i jak się sądzi przelewających krew, gdyż one są cudzołożnicami, a krew jest na ich rękach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 46, 'Tak bowiem mówi Pan Bóg: Sprowadzę na nie wojsko i wydam je na wysiedlenie i na łup.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 47, 'I ta gromada ukamienuje je, i rozsiecze swymi mieczami, zabije ich synów i córki, a ich domy spali ogniem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 48, 'Tak usunę rozwiązłość z tej ziemi, aby wszystkie kobiety otrzymały ostrzeżenie i nie czyniły według waszej rozwiązłości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 49, 'I będzie nałożona na was wasza rozwiązłość, i poniesiecie grzechy waszych bożków. I poznacie, że ja jestem Panem Bogiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 1, 'W dziewiątym roku, w dziesiątym miesiącu, dziesiątego dnia tego miesiąca, znowu doszło do mnie słowo Pana mówiące:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 2, 'Synu człowieczy, napisz sobie datę tego dnia, tego właśnie dnia. W tym dniu bowiem król Babilonu obległ Jerozolimę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 3, 'I opowiedz przypowieść temu domowi buntowniczemu. Powiedz do niego: Tak mówi Pan Bóg: Postaw kocioł, postaw i nalej do niego wody.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 4, 'Włóż do niego kawałki mięsa, każdy dobry kawałek, udziec i łopatkę, napełnij go najlepszymi kośćmi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 5, 'Weź to, co najlepsze ze stada, rozpal pod nim ogień z kości, aby wrzało i kipiało, i niech się ugotują w nim kości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 6, 'Dlatego tak mówi Pan Bóg: Biada miastu krwawemu, kotłowi, w którym jest jego szumowina i z którego szumowina nie wychodzi. Wyciągaj z niego kawałek po kawałku, niech nie padnie na niego los.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 7, 'W nim bowiem jest krew przelana przez niego; wystawiono ją na wierzchu skały, nie wylano jej na ziemię, aby była przykryta prochem;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 8, 'Aby rozniecić zapalczywość dla dokonania zemsty. Wystawiłem więc jego krew na wierzchu skały, aby nie była przykryta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 9, 'Dlatego tak mówi Pan Bóg: Biada miastu krwawemu! Ja ułożę wielki stos drew.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 10, 'Nakładaj drwa, rozniecaj ogień, ugotuj mięso i przypraw korzeniem, niech kości się spalą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 11, 'Potem postaw pusty kocioł na węglach, aby się rozgrzał i rozpaliła jego miedź, by się roztopiła w nim jego nieczystość i jego szumowina była zniszczona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 12, 'Zmęczyła się swymi kłamstwami, a ogrom jej szumowiny nie wychodzi z niej, jej szumowina będzie strawiona w ogniu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 13, 'W twojej nieczystości jest rozwiązłość. Ponieważ chciałem cię oczyścić, a nie dałaś się oczyścić, to już nie będziesz oczyszczona ze swojej nieczystości, aż uśmierzę na tobie swoją zapalczywość.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 14, 'Ja, Pan, powiedziałem. Przyjdzie to i dokonam tego, nie cofnę się i nie zlituję się ani nie będę żałował; według twoich dróg i według twoich czynów będę cię sądzić, mówi Pan Bóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 15, 'I doszło do mnie słowo Pana mówiące:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 16, 'Synu człowieczy, oto zabiorę ci nagle rozkosz twoich oczu, ale ty nie lamentuj ani nie płacz, niech twoje łzy się nie wylewają.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 17, 'Zaniechaj zawodzenia, nie urządzaj żałoby po zmarłej; zawiąż sobie zawój, nałóż obuwie na nogi, nie zasłaniaj warg i nie jedz niczyjego chleba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 18, 'Rano przemówiłem więc do ludu, a wieczorem umarła moja żona; i uczyniłem rano, jak mi rozkazano.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 19, 'I lud zapytał mnie: Czy nie powiesz nam, co znaczą dla nas te rzeczy, które czynisz?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 20, 'Wtedy odpowiedziałem im: Słowo Pana doszło do mnie mówiące:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 21, 'Powiedz domowi Izraela: Tak mówi Pan Bóg: Oto zbezczeszczę swoją świątynię, chlubę waszej potęgi, rozkosz waszych oczu i miłość waszej duszy, a wasi synowie i wasze córki, które pozostawiliście, polegną od miecza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 22, 'I uczynicie tak, jak ja uczyniłem: nie zasłonicie warg i nie będziecie jeść niczyjego chleba;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 23, 'Wasze zawoje będą na waszych głowach i wasze obuwie na nogach; nie będziecie zawodzić ani płakać, lecz będziecie schnąć z powodu waszych nieprawości i będziecie wzdychać jeden do drugiego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 24, 'I Ezechiel będzie dla was znakiem: wszystko, co on uczynił, wy będziecie czynić. A gdy to nastąpi, poznacie, że ja jestem Panem Bogiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 25, 'A ty, synu człowieczy, czy w tym dniu, w którym zabiorę im ich moc, radość ich chluby, rozkosz ich oczu i tęsknotę duszy, ich synów i córki;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 26, 'Czy w tym dniu nie przyjdzie do ciebie ten, co ucieknie, aby przynieść wieść dla twoich uszu?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 27, 'W tym dniu otworzą się twoje usta przed tym, który uszedł, i będziesz mówił, a nie będziesz już niemy. Będziesz dla nich znakiem i poznają, że ja jestem Panem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 1, 'I doszło do mnie słowo Pana mówiące:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 2, 'Synu człowieczy, zwróć swoją twarz przeciwko Ammonitom i prorokuj przeciwko nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 3, 'Powiedz Ammonitom: Słuchajcie słowa Pana Boga. Tak mówi Pan Bóg: Ponieważ mówiłeś: Ha! na moją świątynię, gdy została zbezczeszczona, i na ziemię Izraela, gdy była spustoszona, i na dom Judy, gdy poszedł w niewolę;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 4, 'Oto wydam cię w posiadanie narodom Wschodu. Pobudują swoje pałace u ciebie i urządzą u ciebie swoje mieszkania. Będą jeść twoje plony i będą pić twoje mleko.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 5, 'I uczynię z Rabby legowisko dla wielbłądów, a z miast Ammonitów – legowisko dla trzód. I poznacie, że ja jestem Panem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 6, 'Tak bowiem mówi Pan Bóg: Ponieważ klaskałeś rękami, tupałeś nogami i cieszyłeś się w sercu z całą pogardą wobec ziemi Izraela;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 7, 'Oto wyciągnę swą rękę przeciwko tobie i wydam cię na łup poganom; wytnę cię spośród narodów, wytracę cię z ziem i wyniszczę cię. I poznasz, że ja jestem Panem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 8, 'Tak mówi Pan Bóg: Ponieważ Moab i Seir mówią: Oto dom Judy jest jak wszystkie inne narody;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 9, 'Dlatego odsłonię zbocze Moabu od miast, od jego granicznych miast, które są ozdobą ziemi: Bet-Jeszimot, Baal-Meon i Kiriataim;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 10, 'Przed narodami Wschodu wraz z Ammonitami; dam je w posiadanie, aby nie wspominano Ammonitów między narodami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 11, 'I dokonam sądów nad Moabem, i poznają, że ja jestem Panem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 12, 'Tak mówi Pan Bóg: Ponieważ Edom srodze się mścił nad domem Judy i ciężko zawinił, mszcząc się nad nim;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 13, 'Tak mówi Pan Bóg: Wyciągnę też swoją rękę na ziemię Edomu i wytracę z niej ludzi i zwierzęta, i zamienię ją w pustynię; od Temanu aż do Dedanu polegną od miecza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 14, 'I dokonam swojej zemsty na Edomie przez ręce mego ludu Izraela, a postąpią z Edomem według mojej zapalczywości i według mojego gniewu. I poznają moją pomstę, mówi Pan Bóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 15, 'Tak mówi Pan Bóg: Ponieważ Filistyni się mścili i dokonali zemsty złośliwym sercem, aby prowadzić do zguby z powodu odwiecznej nieprzyjaźni;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 16, 'Dlatego tak mówi Pan Bóg: Oto wyciągnę swoją rękę na Filistynów, wykorzenię Keretytów i wytracę resztkę wybrzeża morskiego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 17, 'I dokonam na nich wielkiej pomsty, karząc ich w zapalczywości; i poznają, że ja jestem Panem, gdy wywrę na nich swoją pomstę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 1, 'W jedenastym roku, pierwszego dnia miesiąca, doszło do mnie słowo Pana mówiące:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 2, 'Synu człowieczy, ponieważ Tyr mówił o Jerozolimie: Ha! Zniszczona została brama ludu, obróciła się do mnie. Teraz będę napełniony, gdyż ona jest spustoszona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 3, 'Dlatego tak mówi Pan Bóg: Oto wystąpię przeciwko tobie, Tyrze, i sprowadzę na ciebie wiele narodów, jak morze podnosi swoje fale.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 4, 'Zburzą mury Tyru i wywrócą jego wieże. Wymiotę z niego jego proch i uczynię go wierzchołkiem gładkiej skały.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 5, 'Stanie się miejscem suszenia sieci pośród morza, bo ja to powiedziałem, mówi Pan Bóg. Stanie się łupem narodów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 6, 'A jego córki, które będą na polu, zostaną zabite mieczem; i poznają, że ja jestem Panem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 7, 'Tak bowiem mówi Pan Bóg: Oto sprowadzę z północy przeciwko Tyrowi Nabuchodonozora, króla Babilonu, króla królów, z końmi, rydwanami, jeźdźcami, oddziałami i z wielkim ludem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 8, 'Twoje córki na polu zabije mieczem, zbuduje przeciwko tobie baszty, usypie przeciwko tobie wał i podniesie przeciwko tobie tarczę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 9, 'Skieruje tarany przeciwko twoim murom i zburzy twoje wieże swymi młotami wojennymi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 10, 'Z powodu mnóstwa jego koni okryje cię ich kurz; od grzmotu jeźdźców, wozów i rydwanów zadrżą twoje mury, gdy wjedzie w twoje bramy, jak wtedy, gdy wjeżdża się do zburzonego miasta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 11, 'Kopytami swoich koni zdepcze wszystkie twoje ulice, twój lud zabije mieczem i twoje potężne słupy runą na ziemię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 12, 'Złupią twoje bogactwo i zrabują twoje towary, zburzą twoje mury i zniszczą twoje wspaniałe domy, a twoje kamienie, drewno i proch wrzucą do wody.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 13, 'I sprawię, że ustanie głos twoich pieśni, a dźwięku twoich harf nie będzie już słychać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 14, 'I uczynię cię wierzchołkiem gładkiej skały, staniesz się miejscem suszenia sieci i nie będziesz już odbudowany, bo ja, Pan, to powiedziałem, mówi Pan Bóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 15, 'Tak mówi Pan Bóg do Tyru: Czy nie zadrżą wyspy na huk twego upadku, gdy ranni będą wołać, gdy będzie okrutna rzeź pośród ciebie?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 16, 'Wtedy wszyscy książęta morscy zejdą ze swoich tronów, złożą z siebie swoje płaszcze i zdejmą swoje haftowane szaty. Przyobleką się w strach, usiądą na ziemi, będą drżeć nieustannie i zdumiewać się nad tobą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 17, 'I podniosą lament nad tobą, i będą mówić do ciebie: Jakżeś zginęło, miasto zamieszkane z powodu swej bliskości do morza, miasto sławne, które było potężne na morzu, ono i jego mieszkańcy, którzy budzili grozę u wszystkich mieszkańców na morzu!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 18, 'Wtedy zadrżą wysypy w dniu twego upadku; tak, wyspy morskie zatrwożą się z powodu twego zginięcia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 19, 'Tak bowiem mówi Pan Bóg: Gdy uczynię cię miastem spustoszonym jak miasta, w których nikt nie mieszka, gdy sprowadzę na ciebie głębinę, tak że przykryją cię wielkie fale;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 20, 'Gdy strącę cię do tych, którzy zstępują do dołu, do ludu dawnego, i umieszczę cię w najniższych stronach ziemi – w dawnych miejscach opustoszałych – z tymi, co zstępują do dołu, abyś nie było zamieszkane, wtedy pokażę sławę w ziemi żyjących.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 21, 'Uczynię z ciebie postrach i przestaniesz istnieć; a choć będą cię szukać, nigdy cię nie znajdą, mówi Pan Bóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 1, 'I doszło do mnie słowo Pana mówiące:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 2, 'A ty, synu człowieczy, podnieś lament nad Tyrem;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 3, 'I powiedz Tyrowi, który leży u wejścia do morza i prowadzi handel z narodami na wielu wyspach: Tak mówi Pan Bóg: Tyrze, ty powiedziałeś: Ja jestem doskonały w swojej piękności.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 4, 'Twoje granice są w środku morza, twoi budowniczowie uczynili doskonałą twoją piękność.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 5, 'Z cyprysów Seniru pobudowali wszystkie twoje deski pokładowe, brali cedry z Libanu, aby zrobić maszty dla ciebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 6, 'Z dębów Baszanu wykonywali twoje wiosła, urobili twoje ławy z kości słoniowych i bukszpanu z wysp Kittim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 7, 'Bisior haftowany z Egiptu był twoim płótnem, z którego zrobiłeś swoje żagle; błękit i purpura z wysp Eliszy były twoim nakryciem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 8, 'Mieszkańcy Sydonu i Arwadu byli twoimi żeglarzami. Twoi mędrcy, Tyrze, którzy pochodzili z ciebie, byli twoimi sternikami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 9, 'Starcy z Gebalu i jego mędrcy naprawiali u ciebie twoje pęknięcia; wszystkie okręty morskie i ich żeglarze przebywali u ciebie, aby prowadzić z tobą handel.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 10, 'Mieszkańcy Persji, Lud i Put służyli w twoim wojsku jako twoi wojownicy. Wieszali u ciebie tarczę i hełm i dodawali ci piękna.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 11, 'Synowie Arwadu wraz z twoim wojskiem stali na twoich murach dokoła, także Gammadejczycy czuwali na twoich wieżach, wieszali swoje tarcze na twoich murach dokoła. Oni uczynili doskonałą twoją piękność.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 12, 'Tarszisz prowadził z tobą handel ze względu na obfitość wszelkiego bogactwa. Na twoich jarmarkach handlowali srebrem, żelazem, cyną i ołowiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 13, 'Jawan, Tubal i Meszek prowadzili z tobą handel. Za twoje towary dawali ludzi i naczynia z brązu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 14, 'Dom Togarmy handlował końmi, jeźdźcami i mułami na twoich jarmarkach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 15, 'Synowie Dedanu prowadzili z tobą handel i wiele wysp kupowało towary twojej ręki. Dawali ci w zamian rogi, kość słoniową i drewno hebanu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 16, 'Syryjczycy prowadzili z tobą handel ze względu na mnóstwo twoich wyrobów. Handlowali karbunkułami, purpurą, haftowaną tkaniną, bisiorem, koralami i kryształami na twoich jarmarkach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 17, 'Juda i ziemia Izraela prowadziły z tobą handel; dawali ci w zamian pszenicę z Minnit i Pannag, miód, oliwę i balsam.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 18, 'Damaszek prowadził z tobą handel ze względu na mnóstwo twoich wyrobów i ze względu na obfitość wszelkiego bogactwa; handlował winem z Chelbonu i białą wełną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 19, 'Także Dan i Jawan, wędrowni handlarze na twoich jarmarkach, dawali ci w zamian żelazo polerowane, kasję i ziela tataraku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 20, 'Dedan prowadził handel u ciebie kosztowną tkaniną na rydwany.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 21, 'Arabia i wszyscy książęta Kedaru prowadzili z tobą handel jagniętami, baranami i kozłami; tym handlowali u ciebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 22, 'Kupcy z Szeby i Rama prowadzili z tobą handel. Handlowali w twoich jarmarkach najlepszymi ze wszystkich woni oraz wszelkim drogim kamieniem i złotem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 23, 'Charan, Kanne i Eden, kupcy z Szeby, Assur i Kilmad prowadzili z tobą handel.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 24, 'Handlowali z tobą szatami z błękitu, haftowaną tkaniną i skrzyniami z cedru dla kosztownych szat, które zawiązywano sznurami; tym handlowali u ciebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 25, 'Okręty morskie przypłynęły po twoje towary wymienne. Napełniłeś się i byłeś wielce uwielbiony w sercu mórz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 26, 'Twoi wioślarze wyprowadzili cię na wielkie wody. Wschodni wiatr rozbił cię w sercu mórz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 27, 'Twoje bogactwa, twoje jarmarki, twoje towary, twoi żeglarze i sternicy oraz ci, którzy naprawiali twoje pęknięcia, twoi nabywcy, kupcy twoich towarów, wszyscy twoi wojownicy, którzy są u ciebie, i cały twój tłum, który znajduje się u ciebie, wpadną do środka morza w dniu twego upadku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 28, 'Na głos krzyku twoich sterników zadrżą wybrzeża.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 29, 'I zejdą ze swoich okrętów wszyscy wioślarze, żeglarze i wszyscy sternicy morscy, i staną na lądzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 30, 'Będą lamentować nad tobą donośnym głosem i gorzko będą zawodzić; posypią prochem swoje głowy i w popiele będą się tarzać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 31, 'Z powodu ciebie ogolą sobie głowy, przepaszą się worami i będą płakać nad tobą w goryczy swej duszy i gorzkim zawodzeniu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 32, 'Uczynią nad tobą lament żałosny i będą nad tobą zawodzić, mówiąc: Które miasto jest podobne do Tyru, który zniszczono pośrodku morza?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 33, 'Gdy twoje towary szły z morza, syciłeś wiele narodów; mnóstwem twoich bogactw i wyrobów wzbogaciłeś królów ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 34, 'Ale gdy będziesz zdruzgotany przez morza w głębinach wód, twoje towary i cały twój tłum pośród ciebie upadnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 35, 'Wszyscy mieszkańcy wysp będą zdumiewać się nad tobą, a ich królowie będą zdjęci strachem, z zatrwożoną twarzą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 36, 'Kupcy spośród narodów świsną nad tobą; będziesz dla nich postrachem i przestaniesz istnieć na wieki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 1, 'I doszło do mnie słowo Pana mówiące:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 2, 'Synu człowieczy, powiedz księciu Tyru: Tak mówi Pan Bóg: Ponieważ uniosło się twoje serce i powiedziałeś: Ja jestem Bogiem, zasiadam na Bożym tronie w sercu mórz – ale ty jesteś człowiekiem, a nie Bogiem, choć twoje serce stawiasz na równi z sercem Boga;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 3, 'Oto jesteś mądrzejszy od Daniela, żadna tajemnica nie jest zakryta przed tobą;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 4, 'Swoją mądrością i roztropnością zdobyłeś sobie bogactwo i nagromadziłeś złota i srebra w swoich skarbcach;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 5, 'Dzięki wielkości twojej mądrości i twojemu kupiectwu rozmnożyłeś swoje bogactwa; a tak uniosło się twoje serce z powodu twoich bogactw;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 6, 'Dlatego tak mówi Pan Bóg: Ponieważ postawiłeś swoje serce jak serce Boga;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 7, 'Oto sprowadzę na ciebie cudzoziemców, najsroższe z narodów. Dobędą swoje miecze przeciwko piękności twej mądrości i splugawią twój blask.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 8, 'Strącą cię do dołu i umrzesz srogą śmiercią w sercu mórz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 9, 'Czy powiesz przed tym, który cię zabije: Jestem Bogiem? Przecież jesteś człowiekiem, a nie Bogiem w ręku tego, który cię zabije.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 10, 'Umrzesz śmiercią nieobrzezanych, z ręki cudzoziemców. Ja bowiem to powiedziałem, mówi Pan Bóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 11, 'I doszło do mnie słowo Pana mówiące:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 12, 'Synu człowieczy, podnieś lament nad królem Tyru i mów do niego: Tak mówi Pan Bóg: Ty pieczętujesz sumę, pełen mądrości i doskonały w swej piękności;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 13, 'Byłeś w Edenie, ogrodzie Bożym; twoim nakryciem był wszelki drogi kamień: karneol, topaz i jaspis, chryzolit, onyks i beryl, szafir, karbunkuł i szmaragd oraz złoto. Wykonanie twoich bębenków i fletów zostało przygotowane w dniu, kiedy zostałeś stworzony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 14, 'Ty jesteś namaszczonym cherubinem nakrywającym; ja cię ustanowiłem. Byłeś na świętej górze Boga, przechadzałeś się wśród kamieni ognistych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 15, 'Byłeś doskonały w swoich drogach od dnia, kiedy zostałeś stworzony, aż znalazła się w tobie nieprawość.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 16, 'Przez twój ogromny handel pełno pośród ciebie bezprawia, i zgrzeszyłeś. Dlatego zrzucę cię z góry Boga, cherubinie nakrywający, wyniszczę cię spośród kamieni ognistych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 17, 'Uniosło się twoje serce z powodu twojej piękności, znieważyłeś swoją mądrość z powodu twojego blasku. Rzucę cię na ziemię i postawię cię przed królami, aby się tobie przypatrzyli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 18, 'Mnóstwem twoich nieprawości i nieprawością twego handlu splugawiłeś swoją świątynię. Dlatego wywiodę ogień z twego wnętrza, który cię pożre, a zamienię cię w popiół na ziemi na oczach wszystkich, którzy na ciebie patrzą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 19, 'Wszyscy, którzy cię znają wśród narodów, zdumieją się nad tobą. Staniesz się postrachem i nie będzie ciebie już na wieki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 20, 'I doszło do mnie słowo Pana mówiące:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 21, 'Synu człowieczy, zwróć swoją twarz przeciw Sydonowi i prorokuj przeciw niemu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 22, 'Mów: Tak mówi Pan Bóg: Oto jestem przeciwko tobie, Sydonie, będę uwielbiony pośród ciebie. I poznają, że ja jestem Panem, gdy wykonam na niego sądy i będę w nim uświęcony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 23, 'I ześlę na niego zarazę i krew na jego ulice; zranieni upadną pośród niego od miecza, który spadnie na nich ze wszystkich stron. I poznają, że ja jestem Panem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 24, 'I tak dla domu Izraela nie będzie już kłującego ciernia ani bolesnego kolca spośród wszystkich okolicznych mieszkańców, którzy nim wzgardzili. I poznają, że ja jestem Panem Bogiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 25, 'Tak mówi Pan Bóg: Gdy zgromadzę dom Izraela spośród narodów, wśród których został rozproszony, i będę w nich uświęcony na oczach pogan, wtedy będą mieszkać w swojej ziemi, którą dałem swemu słudze Jakubowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 26, 'I będą w niej mieszkać bezpiecznie, pobudują domy i zasadzą winnice. Będą mieszkać bezpiecznie, gdy wykonam sądy na wszystkich dokoła nich, którzy nimi wzgardzili. I poznają, że ja jestem Panem, ich Bogiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 1, 'W dziesiątym roku, dziesiątego miesiąca, dwunastego dnia tego miesiąca doszło do mnie słowo Pana mówiące:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 2, 'Synu człowieczy, zwróć swoją twarz przeciwko faraonowi, królowi Egiptu, i prorokuj przeciw niemu i całemu Egiptowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 3, 'Przemów i powiedz: Tak mówi Pan Bóg: Oto jestem przeciwko tobie, faraonie, królu Egiptu, wielki smoku leżący wśród swoich rzek, który mówisz: Moja jest rzeka, ja ją sobie uczyniłem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 4, 'Dlatego włożę haki w twoje szczęki i sprawię, że ryby twoich rzek przylgną do twoich łusek. Wyciągnę cię spośród twoich rzek i wszystkie ryby twoich rzek przylgną do twoich łusek.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 5, 'I zostawię cię na pustyni, ciebie i wszystkie ryby twoich rzek. Upadniesz na otwartym polu i nie będziesz zebrany ani zgromadzony. Dam cię na pożarcie zwierzętom ziemi i ptactwu nieba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 6, 'I poznają wszyscy mieszkańcy Egiptu, że ja jestem Panem, ponieważ byłeś laską z trzciny dla domu Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 7, 'Gdy chwytali się ciebie ręką, łamałeś się i rozcinałeś im całe ramię. Gdy się opierali na tobie, kruszyłeś się i unieruchamiałeś im wszystkie biodra.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 8, 'Dlatego tak mówi Pan Bóg: Oto sprowadzę na ciebie miecz i wytracę z ciebie człowieka i zwierzę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 9, 'A ziemia Egiptu będzie spustoszeniem i pustkowiem; i poznają, że ja jestem Panem, ponieważ mówiłeś: Moja jest rzeka, ja ją sobie uczyniłem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 10, 'Dlatego oto ja będę przeciwko tobie i przeciwko twojej rzece i zamienię ziemię Egiptu w straszną ruinę i spustoszenie, od wieży Sewene aż do granic Etiopii.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 11, 'Nie przejdzie przez nią noga człowieka ani też nie przejdzie przez nią noga zwierzęcia, i nie będzie zamieszkana przez czterdzieści lat.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 12, 'I uczynię z ziemi Egiptu pustkowie pośród spustoszonych ziem, a jej miasta wśród zrujnowanych miast będą spustoszone przez czterdzieści lat. I rozproszę Egipcjan między narodami, i rozrzucę ich po ziemiach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 13, 'Jednak tak mówi Pan Bóg: Po upływie czterdziestu lat zgromadzę Egipcjan z narodów, wśród których zostali rozproszeni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 14, 'I odwrócę niewolę Egiptu, i przyprowadzę ich do ziemi Patros, do ziemi ich zamieszkania, i będą tam nieznacznym królestwem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 15, 'Będzie ono najmniej znaczące spośród królestw i nie wyniesie się więcej nad inne narody. Umniejszę ich, aby nie panowali nad narodami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 16, 'I nie będzie już ufnością domu Izraela, co przypominałoby o jego nieprawości, gdy zwracał się do niego. I poznają, że ja jestem Panem Bogiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 17, 'Potem, w roku dwudziestym siódmym, w pierwszym miesiącu, pierwszego dnia tego miesiąca, doszło do mnie słowo Pana:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 18, 'Synu człowieczy, Nabuchodonozor, król Babilonu, zmusił swoje wojsko do ciężkiej służby przeciwko Tyrowi: każda głowa wyłysiała i każde ramię się obnażyło, lecz ani on, ani jego wojsko nie otrzymali zapłaty z Tyru za tę służbę, którą podejmował, walcząc przeciwko niemu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 19, 'Dlatego tak mówi Pan Bóg: Oto daję Nabuchodonozorowi, królowi Babilonu, ziemię Egiptu, i zabierze jej dostatek, weźmie jej łup, i pochwyci jej zdobycze, aby to było zapłatą dla jego wojska.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 20, 'Daję im ziemię Egiptu za ich pracę, którą dla mnie podjęli, gdyż dla mnie pracowali, mówi Pan Bóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 21, 'W tym dniu sprawię, że wyrośnie róg domu Izraela, tobie też pozwolę otworzyć usta pośród nich. I poznają, że ja jestem Panem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 1, 'I doszło do mnie słowo Pana mówiące:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 2, 'Synu człowieczy, prorokuj i mów: Tak mówi Pan Bóg: Zawódźcie, mówiąc: Ach, jakiż to dzień!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 3, 'Bliski bowiem jest dzień, bliski jest dzień Pana; będzie to dzień pochmurny i czas pogan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 4, 'I spadnie miecz na Egipt, i będzie wielka trwoga w Etiopii, gdy polegną zabici w Egipcie, gdy zabiorą jego dostatek i jego fundamenty będą zburzone.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 5, 'Etiopia, Put i Lud, cała różnorodna ludność, Kub i mieszkańcy sprzymierzonej ziemi padną razem z nimi od miecza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 6, 'Tak mówi Pan: Upadną ci, którzy wspierają Egipt, i runie pycha jego mocy. Od wieży Sewene padną w niej od miecza, mówi Pan Bóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 7, 'I będą spustoszeni wśród spustoszonych ziem, a ich miasta znajdą się wśród zburzonych miast.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 8, 'I poznają, że ja jestem Panem, gdy rozpalę ogień w Egipcie, i wszyscy jego pomocnicy zostaną skruszeni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 9, 'W tym dniu posłańcy wyruszą ode mnie w okrętach na postrach spokojnej ziemi Etiopii; i ogarnie ich wielka trwoga, jaka była w dniu porażki Egiptu. Oto bowiem nadchodzi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 10, 'Tak mówi Pan Bóg: Położę kres mnóstwu Egiptu przez rękę Nabuchodonozora, króla Babilonu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 11, 'On i z nim jego lud, najsrożsi z narodów, będą sprowadzeni, aby zniszczyć tę ziemię. Dobędą swe miecze przeciw Egiptowi i napełnią ziemię pobitymi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 12, 'Wysuszę rzeki i sprzedam ziemię w ręce niegodziwych. Ręką cudzoziemców spustoszę ziemię wraz ze wszystkim, co ją napełnia. Ja, Pan, to powiedziałem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 13, 'Tak mówi Pan Bóg: Zniszczę bożki i usunę posągi z Nof, i nie będzie już księcia w ziemi Egiptu. Ześlę strach na ziemię Egiptu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 14, 'Spustoszę Patros, rozniecę ogień w Soan i wykonam sąd w No.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 15, 'Wyleję swoją zapalczywość na Sin, twierdzę Egiptu, i wytracę tłumy z No.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 16, 'Rozniecę ogień w Egipcie, Sin będzie cierpieć z bólu, No zostanie zniszczone i Nof będzie codziennie dręczone.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 17, 'Młodzieńcy z Awen i Pibeset polegną od miecza, te miasta pójdą do niewoli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 18, 'W Tachpanches dzień ogarną ciemności, gdy złamię tam jarzma Egiptu, i ustanie w nim pycha jego mocy. Okryje go chmura i jego córki pójdą do niewoli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 19, 'Tak wykonam sądy nad Egiptem. I poznają, że ja jestem Panem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 20, 'W roku jedenastym, w pierwszym miesiącu, siódmego dnia miesiąca, doszło do mnie słowo Pana mówiące:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 21, 'Synu człowieczy, złamałem ramię faraona, króla Egiptu, i oto nie będzie ono obwiązane w celu uleczenia ani nie zostanie owinięte bandażami, ani nie będzie związane, by je wzmocnić, aby mogło trzymać miecz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 22, 'Dlatego tak mówi Pan Bóg: Oto jestem przeciwko faraonowi, królowi Egiptu, skruszę mu ramiona, zarówno to mocne, jak i to złamane, i wytrącę miecz z jego ręki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 23, 'I rozproszę Egipcjan między narodami, i rozrzucę ich po ziemiach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 24, 'Wzmocnię ramiona króla Babilonu i włożę swój miecz w jego ręce, a ramiona faraona złamię i będzie przed nim stękał, jak stęka śmiertelnie zraniony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 25, 'Wzmocnię – mówię – ramiona króla Babilonu, a ramiona faraona upadną; i poznają, że ja jestem Panem, gdy włożę swój miecz w ręce króla Babilonu, aby go wyciągnął na ziemię Egiptu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 26, 'I rozproszę Egipcjan między narodami, i rozrzucę ich po ziemiach. I poznają, że jestem Panem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 1, 'Potem, w jedenastym roku, w trzecim miesiącu, pierwszego dnia tego miesiąca, doszło do mnie słowo Pana mówiące:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 2, 'Synu człowieczy, mów do faraona, króla Egiptu, i do jego ludu: Do kogo jesteś podobny w swojej wielkości?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 3, 'Oto Assur był jak cedr na Libanie, o pięknych gałęziach i szeroko rzucającym cieniu, o wysokim wzroście, a jego wierzchołek był wśród gęstych gałęzi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 4, 'Wody dodały mu wzrostu i głębiny go wywyższyły, ich rzeki roztoczyły dokoła jego korzeń i puściły swoje strumienie ku wszystkim drzewom polnym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 5, 'Dlatego swym wzrostem przewyższył wszystkie drzewa polne i jego konary rozkrzewiły się, a dzięki obfitości wód rozszerzyły się jego gałęzie, które wypuścił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 6, 'Na jego gałęziach uwiło sobie gniazda wszelkie ptactwo niebieskie, pod jego gałęziami rodziły się wszelkie zwierzęta polne i w jego cieniu siadały wszystkie wielkie narody.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 7, 'Był piękny w swojej wielkości przez długość swoich gałęzi, gdyż jego korzeń był nad obfitymi wodami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 8, 'Cedry w ogrodzie Bożym nie przewyższały go. Cyprysy nie były podobne do jego gałęzi i drzewa kasztanowe nie były podobne do jego konarów. Żadne drzewo w ogrodzie Bożym nie dorównało mu swoją pięknością.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 9, 'Ja uczyniłem go pięknym przez mnóstwo jego gałęzi. Zazdrościły mu wszystkie drzewa Edenu, które były w ogrodzie Bożym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 10, 'Dlatego tak mówi Pan Bóg: Ponieważ wysoko wyrósł, wywyższył swój wierzchołek wśród gęstych gałęzi i jego serce podniosło się z powodu jego wysokości;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 11, 'Wydałem go w rękę najmocniejszego z narodów, aby się z nim srogo obszedł. Odrzuciłem go z powodu jego niegodziwości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 12, 'A cudzoziemcy, ci najsrożsi z narodów, wycięli go i porzucili. Jego gałęzie padły na górach i we wszystkich dolinach i jego konary połamały się nad wszystkimi strumieniami tej ziemi. Wszystkie ludy ziemi ustąpiły spod jego cienia i opuściły go.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 13, 'Na jego powalonym pniu osiądzie wszelkie ptactwo niebieskie i na jego gałęziach będzie wszelki zwierz polny;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 14, 'Aby żadne drzewo stojące nad wodami nie wynosiło się z powodu swego wzrostu i nie wypuszczało swoich wierzchołków wśród gęstych gałęzi, i nie pyszniło się swoją wysokością żadne drzewo, które pije wodę. Ci wszyscy bowiem są wydani na śmierć, wrzuceni do najgłębszych stron ziemi, wśród synów ludzkich wraz z tymi, którzy zstępują do dołu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 15, 'Tak mówi Pan Bóg: W dniu, kiedy zstąpił do grobu, wzbudziłem lament, zamknąłem dla niego głębinę i wstrzymałem jej strumienie, i zastawiłem wielkie wody. Sprawiłem, że Liban okrył się ciemnością z jego powodu i z jego powodu wszystkie drzewa polne zemdlały.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 16, 'Na huk jego upadku zadrżały narody, gdy go wrzucałem do piekła z tymi, co do dołu zstępują. Wszystkie drzewa Edenu, najwyborniejsze i najlepsze z Libanu, które piją wodę, doznają pociechy w najgłębszych stronach ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 17, 'One także zstąpiły z nim do piekła, do zabitych mieczem, którzy byli jego ramieniem i którzy mieszkali w jego cieniu wśród narodów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 18, 'Do kogo byłeś podobny chwałą i wielkością między drzewami Edenu? Oto zostaniesz zrzucony wraz z drzewami Edenu do najgłębszych stron ziemi. Będziesz leżał wśród nieobrzezanych wraz z pobitymi mieczem. To jest z faraonem i całą jego rzeszą – mówi Pan Bóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 1, 'W dwunastym roku, w dwunastym miesiącu, pierwszego dnia tego miesiąca, doszło do mnie słowo Pana mówiące:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 2, 'Synu człowieczy, podnieś lament nad faraonem, królem Egiptu, i powiedz mu: Jesteś podobny do młodego lwa pośród narodów, jesteś jak wieloryb w morzu, gdyż bujając po swoich rzekach, mącisz wody swoimi nogami i mieszasz jego rzeki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 3, 'Tak mówi Pan Bóg: Rozciągnę nad tobą swoją sieć w zgromadzeniu wielu narodów, a wyciągną cię w swoim niewodzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 4, 'I zostawię cię na ziemi, porzucę cię na otwartym polu i sprawię, że obsiądzie cię wszelkie ptactwo niebieskie, i nasycę tobą zwierzęta całej ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 5, 'Rozrzucę twoje ciało po górach i napełnię doliny twoją wysokością.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 6, 'Twoją ziemię, w której pływasz, napoję twoją krwią aż do gór, i rzeki będą napełnione tobą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 7, 'A gdy cię zgaszę, zakryję niebo i zaciemnię jego gwiazdy, słońce zakryję chmurą, a księżyc nie da swego światła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 8, 'Wszystkie świecące światła na niebie zaciemnię z twojego powodu i sprowadzę ciemność na twoją ziemię, mówi Pan Bóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 9, 'Nadto zasmucę serce wielu narodów, gdy za moją sprawą nadejdzie wieść o twoim zniszczeniu do narodów, do ziem, których nie znałeś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 10, 'Tak, sprawię, że zdumieje się nad tobą wiele narodów, a ich królowie bardzo się zatrwożą z twojego powodu, gdy zacznę wywijać swoim mieczem przed nimi; i będą drżeć nieustannie – każdy o swoją duszę – w dniu twego upadku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 11, 'Tak bowiem mówi Pan Bóg: Miecz króla Babilonu spadnie na ciebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 12, 'Mieczami mocarzy powalę twoją rzeszę. Najokrutniejsi ze wszystkich narodów zniszczą pychę Egiptu i będzie zgładzone całe jego mnóstwo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 13, 'Wytępię całe jego bydło znad wielkich wód, tak że nie zamąci ich stopa ludzka ani nie zamąci ich kopyto bydlęcia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 14, 'Wtedy sprawię, że ich wody uspokoją się, a ich rzeki popłyną jak oliwa – mówi Pan Bóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 15, 'Gdy zamienię ziemię Egiptu w spustoszenie, a ziemia zostanie pozbawiona tego, co ją napełnia, gdy pobiję wszystkich jej mieszkańców, wtedy poznają, że ja jestem Panem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 16, 'To jest lament, który podniosą nad nią. Córki narodów będą ją opłakiwać. Nad Egiptem i nad całą jego rzeszą będą lamentować, mówi Pan Bóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 17, 'Potem, w dwunastym roku, piętnastego dnia miesiąca, doszło do mnie słowo Pana mówiące;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 18, 'Synu człowieczy, zawódź nad rzeszą Egiptu, zepchnij ją i córki tych sławnych narodów aż do najniższych stron ziemi, do tych, którzy zstępują do dołu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 19, 'I mów: Kogo przewyższasz pięknem? Zstąp i połóż się z nieobrzezanymi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 20, 'Padną pośród pobitych mieczem; został wydany pod miecz, wywleczcie go z całą jego rzeszą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 21, 'Najmocniejsi z mocarzy będą do niego mówić spośród piekła wraz z jego pomocnikami. Zstąpili tam, leżą z nieobrzezanymi pobitymi mieczem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 22, 'Tam jest Assur i cała jego rzesza, wokół niego są jego groby; wszyscy ci pobici upadli od miecza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 23, 'Ich groby są położone po stronach dołu, jego rzesza jest dokoła jego grobu. Ci wszyscy pobici polegli od miecza, ci, którzy szerzyli postrach w ziemi żyjących.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 24, 'Tam jest Elam i cała jego rzesza dokoła jego grobu, ci wszyscy pobici upadli od miecza i zstąpili nieobrzezani do najgłębszych stron ziemi; szerzyli swój postrach w ziemi żyjących. Już znoszą swoją hańbę z tymi, którzy zstępują do dołu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 25, 'Postawili mu łoże pośród pobitych z całą jego rzeszą, wokół niego są jego groby. Wszyscy ci nieobrzezani są pobici mieczem. Ich postrach szerzył się w ziemi żyjących, ale już ponoszą swoją hańbę z tymi, którzy zstąpili do dołu, a wśród pobitych zostali położeni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 26, 'Tam jest Meszek, Tubal i cała jego rzesza, i wokoło niego jego groby. Ci wszyscy nieobrzezani zostali pobici mieczem, choć szerzyli swój postrach w ziemi żyjących.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 27, 'Oni jednak nie będą leżeć z mocarzami, którzy spośród nieobrzezanych upadli i zstąpili do grobu ze swym orężem wojennym i położono im miecze pod głowy. Ich nieprawości zaś zostaną na ich kościach, chociaż byli postrachem dla mocarzy w ziemi żyjących.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 28, 'I ty będziesz skruszony wśród nieobrzezanych, i będziesz leżał pośród pobitych mieczem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 29, 'Tam jest Edom, jego królowie i wszyscy jego książęta, którzy zostali położeni ze swoją mocą i wraz z pobitymi mieczem. Ci będą leżeć z nieobrzezanymi i z tymi, którzy zstępują do dołu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 30, 'Tam są wszyscy książęta północy i wszyscy Sydończycy, którzy zstępują do pobitych; wstydzą się swego postrachu, jaki szerzyli swoją mocą, i leżą nieobrzezani z pobitymi mieczem. Znoszą swoją hańbę z tymi, którzy zstępują do dołu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 31, 'Zobaczy ich faraon i ucieszy się z całej swojej rzeszy, którą pobito mieczem, faraon i całe jego wojsko – mówi Pan Bóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 32, 'Szerzyłem bowiem swój postrach w ziemi żyjących i zostanie położony wśród nieobrzezanych z pobitymi mieczem – faraon i cała jego rzesza – mówi Pan Bóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 1, 'I doszło do mnie słowo Pana mówiące:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 2, 'Synu człowieczy, przemów do synów twego ludu i powiedz im: Gdy sprowadzam miecz na jakąś ziemię, a lud tej ziemi weźmie jakiegoś mężczyznę spośród siebie i ustanowi go sobie stróżem;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 3, 'A on, gdy zobaczy nadciągający miecz na tę ziemię, zadmie w trąbę i ostrzeże lud;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 4, 'A ktoś usłyszy dźwięk trąby i nie przyjmie przestrogi, a miecz przyjdzie i zabierze go, to jego krew spadnie na jego własną głowę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 5, 'Dźwięk trąby usłyszał, ale nie przyjął przestrogi, jego krew spadnie na niego. Ten jednak, który przyjmie przestrogę, ocali swoją duszę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 6, 'Ale jeśli stróż zobaczy nadciągający miecz, a nie zadmie w trąbę i ludu nie ostrzeże, a przyjdzie miecz i zabierze kogoś z nich, to ten jest porwany w swojej nieprawości, ale jego krwi zażądam z ręki tego stróża.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 7, 'Ciebie, synu człowieczy, ciebie ustanowiłem stróżem dla domu Izraela. Gdy usłyszysz słowo z moich ust, ostrzeżesz go ode mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 8, 'Gdy mówię do bezbożnego: Bezbożniku, na pewno umrzesz – a ty mu tego nie powiesz, aby przestrzec bezbożnika przed jego drogą, to ten bezbożnik umrze z powodu swojej nieprawości; ale jego krwi zażądam z twojej ręki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 9, 'Jeśli jednak ostrzeżesz bezbożnego przed jego drogą, aby odwrócił się od niej, a on się nie odwróci od swojej drogi, to umrze on z powodu swojej nieprawości; ale ty ocalisz swoją duszę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 10, 'Ty więc, synu człowieczy, mów do domu Izraela: Tak mówicie: Skoro ciążą na nas nasze występki i nasze grzechy, tak że w nich marniejemy, to jakże możemy żyć?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 11, 'Powiedz im: Jak żyję, mówi Pan Bóg: Nie pragnę śmierci bezbożnego, ale aby bezbożny odwrócił się od swojej drogi i żył. Odwróćcie się, odwróćcie się od swoich złych dróg. Dlaczego macie umrzeć, domu Izraela?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 12, 'Ty więc, synu człowieczy, mów do synów swego ludu: Sprawiedliwość sprawiedliwego nie wybawi go w dniu jego przestępstwa, a bezbożność bezbożnego nie zgubi go w dniu, kiedy się odwróci od swojej bezbożności. Sprawiedliwy nie będzie mógł żyć dzięki swojej sprawiedliwości w dniu, kiedy zgrzeszy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 13, 'Jeśli powiem sprawiedliwemu: Na pewno będziesz żyć, a on, polegając na swojej sprawiedliwości, uczyni nieprawość, to żadna jego sprawiedliwość nie będzie wspomniana, ale umrze z powodu swojej nieprawości, którą uczynił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 14, 'A jeśli powiem bezbożnemu: Na pewno umrzesz, a on odwróci się od swego grzechu i uczyni to, co prawe i sprawiedliwe;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 15, 'Jeśli bezbożny zwróci zastaw, odda to, co wydarł, i będzie chodził według praw życia, nie czyniąc nieprawości, na pewno będzie żył i nie umrze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 16, 'Żadne jego grzechy, które popełnił, nie będą mu wspominane. Czynił to, co prawe i sprawiedliwe; na pewno będzie żył.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 17, 'Lecz synowie twego ludu mówią: Droga Pana nie jest słuszna, choć to ich droga nie jest słuszna.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 18, 'Jeśli sprawiedliwy odwróci się od swojej sprawiedliwości i będzie czynił nieprawość, to umrze z jej powodu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 19, 'Ale jeśli bezbożny odwróci się od swojej bezbożności i będzie czynił to, co prawe i sprawiedliwe, to dzięki temu będzie żył.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 20, 'Wy jednak mówicie: Droga Pana nie jest słuszna. Domu Izraela, będę sądził każdego z was według jego drogi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 21, 'I stało się w dwunastym roku naszego uprowadzenia, w dziesiątym miesiącu, piątego dnia tego miesiąca, że przyszedł do mnie jeden zbieg z Jerozolimy, mówiąc: Zdobyto miasto.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 22, 'A ręka Pana była nade mną wieczorem, zanim przyszedł ten zbieg, i otworzyła moje usta, aż ten przyszedł do mnie rano. Otworzyła moje usta i nie byłem już niemy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 23, 'I doszło do mnie słowo Pana mówiące:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 24, 'Synu człowieczy, mieszkańcy tych spustoszonych miejsc w ziemi Izraela mówią: Abraham był jeden i wziął ziemię w posiadanie. Ale nas jest wielu, nam więc dana jest ta ziemia w posiadanie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 25, 'Dlatego mów do nich: Tak mówi Pan Bóg: Jadacie z krwią, podnosicie swe oczy ku swoim bożkom i przelewacie krew, a ziemię chcielibyście wziąć w posiadanie?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 26, 'Opieracie się na swoim mieczu, popełniacie obrzydliwość i każdy plugawi żonę swego bliźniego, a ziemię chcielibyście wziąć w posiadanie?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 27, 'Tak im powiedz: Tak mówi Pan Bóg: Jak żyję, ci, którzy są w spustoszonych miejscach, polegną od miecza, a kto jest na otwartym polu, tego wydam zwierzętom na pożarcie, a ci, którzy są w warowniach lub w jaskiniach, umrą od zarazy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 28, 'I wydam ziemię na wielkie spustoszenie, i ustanie pycha jej mocy; spustoszeją góry Izraela i nikt przez nie będzie przechodził.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 29, 'I poznają, że ja jestem Panem, gdy wydam ich ziemię na wielkie spustoszenie z powodu wszystkich ich obrzydliwości, które czynili.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 30, 'Ale co do ciebie, synu człowieczy, synowie twego ludu często rozmawiają o tobie przy murach i w drzwiach domów, i mówi jeden do drugiego, każdy do swego bliźniego: Chodźcie i posłuchajcie, co za słowo wyszło od Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 31, 'I przychodzą do ciebie, tak zwykł przychodzić lud, zasiadają przed tobą jak mój lud i słuchają twoich słów, ale ich nie wypełniają. Mają bowiem miłość na ustach, lecz ich serce podąża za niegodziwym zyskiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 32, 'A oto jesteś dla nich jak urokliwa pieśń tego, który ma piękny głos i cudownie gra. Słuchają bowiem twoich słów, ale ich nie wykonują.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 33, 'Lecz gdy to nadejdzie – oto nadejdzie – wtedy poznają, że prorok był pośród nich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 1, 'I doszło do mnie słowo Pana mówiące:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 2, 'Synu człowieczy, prorokuj przeciwko pasterzom Izraela, prorokuj i powiedz im: Tak mówi Pan Bóg do tych pasterzy: Biada pasterzom Izraela, którzy sami siebie pasą! Czy pasterze nie powinni paść trzody?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 3, 'Jadacie tłuszcz, okrywacie się wełną i zabijacie tuczne zwierzęta, lecz trzody nie pasiecie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 4, 'Słabych nie posilacie, chorego nie leczycie, złamanego nie obwiązujecie, spłoszonego nie przyprowadzacie ani zgubionego nie szukacie, ale siłą i okrucieństwem panujecie nad nimi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 5, 'Tak że rozproszyły się, bo nie było pasterza, i stały się żerem dla wszelkiego zwierzęcia polnego, ponieważ się rozpierzchnęły.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 6, 'Moje owce błąkają się po wszystkich górach i po każdym wysokim pagórku. Moja trzoda rozproszyła się po całej ziemi, a nikt ich nie szukał i nikt o nie nie pytał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 7, 'Dlatego wy, pasterze, słuchajcie słowa Pana:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 8, 'Jak żyję, mówi Pan Bóg: Ponieważ moja trzoda stała się łupem i moje owce stały się żerem wszelkiego zwierzęcia polnego, bo nie ma pasterza, a moi pasterze nie szukali moich owiec, ale pasterze paśli tylko samych siebie, a moich owiec nie paśli;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 9, 'Dlatego, pasterze, słuchajcie słowa Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 10, 'Tak mówi Pan Bóg: Oto jestem przeciwko pasterzom. Zażądam moich owiec z ich ręki i sprawię, że przestaną paść moje owce i pasterze nie będą już paśli samych siebie. Wyrwę moje owce z ich paszczy i nie będą już dla nich pokarmem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 11, 'Tak bowiem mówi Pan Bóg: Oto ja sam będę szukać moich owiec i o nie pytać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 12, 'Jak pasterz troszczy się o swoją trzodę, kiedy znajduje się wśród swoich rozproszonych owiec, tak ja będę troszczył się o moje owce i wyrwę je ze wszystkich miejsc, dokąd zostały rozproszone w dzień pochmurny i mroczny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 13, 'Wyprowadzę je z narodów, zgromadzę je z ziem i przyprowadzę je do ich ziemi, i będę je pasł na górach Izraela nad strumieniami i po wszystkich zamieszkałych miejscach tej ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 14, 'Będę je pasł na dobrym pastwisku, a ich pastwisko będzie na wysokich górach Izraela. Tam będą odpoczywać na bujnych błoniach i na tłustych pastwiskach będą się pasły na górach Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 15, 'Ja sam będę pasł moje owce i sprawię, że położą się, mówi Pan Bóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 16, 'Będę szukał zagubionej i przyprowadzę spłoszoną, obwiążę to, co złamane, i posilę słabą. Ale wytracę tłustą i mocną, bo będę je pasł w prawości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 17, 'A do was, moja trzodo, tak mówi Pan Bóg: Oto będę rozsądzał między owcą a owcą, między baranami a kozłami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 18, 'Czy mało wam, że się pasiecie na dobrym pastwisku, a resztę waszych pastwisk depczecie swoimi nogami; że pijecie czystą wodę, a resztę mącicie swoimi nogami?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 19, 'A moje owce muszą się paść na tym, co zdeptaliście swoimi nogami, i pić to, co zmąciliście swoimi nogami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 20, 'Dlatego tak mówi do nich Pan Bóg: Oto sam rozsądzę między owcą tłustą i owcą chudą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 21, 'Ponieważ bokiem i ramieniem odpychaliście i swoimi rogami bodliście wszystkie słabe, tak że je rozpędziliście;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 22, 'Ocalę moje owce i nie będą już łupem. Rozsądzę między owcą a owcą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 23, 'I ustanowię nad nimi jednego pasterza, który będzie je pasł, mego sługę Dawida. On będzie je pasł i on będzie ich pasterzem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 24, 'A ja, Pan, będę ich Bogiem, a mój sługa Dawid będzie księciem pośród nich. Ja, Pan, to powiedziałem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 25, 'Zawrę z nimi przymierze pokoju i wytępię dzikie zwierzęta z ziemi. I będą bezpiecznie mieszkały na pustyni, i spały w lasach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 26, 'Ponadto dam błogosławieństwo im oraz okolicy mojego pagórka. Będę zsyłał deszcz w swoim czasie, będą to deszcze błogosławieństwa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 27, 'Drzewo polne wyda swój owoc i ziemia wyda swój plon. Będą oni bezpieczni na swojej ziemi i poznają, że ja jestem Panem, gdy połamię drążki ich jarzma i wyrwę ich z ręki tych, którzy ich zniewolili.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 28, 'I już nie będą łupem narodów ani zwierzęta ziemi nie będą ich pożerały, ale będą bezpiecznie mieszkali i nikt ich nie będzie straszył.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 29, 'Wzbudzę im sławną latorośl i już nie będą niszczeni głodem w ziemi, ani nie będą znosili zniewag pogan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 30, 'I poznają, że ja, Pan, ich Bóg, jestem z nimi, a oni, dom Izraela, są moim ludem, mówi Pan Bóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 31, 'A wy, moje owce, owce mego pastwiska, jesteście ludźmi, a ja jestem waszym Bogiem, mówi Pan Bóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 1, 'I doszło do mnie słowo Pana mówiące:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 2, 'Synu człowieczy, zwróć swoją twarz przeciwko górze Seir i prorokuj przeciwko niej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 3, 'Mów do niej: Tak mówi Pan Bóg: Oto jestem przeciwko tobie, góro Seir, wyciągnę moją rękę przeciwko tobie i wydam cię na wielkie spustoszenie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 4, 'Twoje miasta zamienię w ruiny i będziesz spustoszona. I poznasz, że ja jestem Panem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 5, 'Ponieważ żywiłaś wieczną nienawiść i wydałaś synów Izraela pod ostrze miecza w czasie ich utrapienia, w czasie wykonywania ich kary;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 6, 'Dlatego, jak żyję, mówi Pan Bóg, wydam cię na zabicie i krew będzie cię ścigać. Ponieważ nie znienawidziłaś krwi, krew będzie cię ścigać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 7, 'I zamienię górę Seir w wielkie spustoszenie, wygubię z niej każdego, który przechodzi i który wraca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 8, 'Jej góry napełnię jej zabitymi. Na twoich pagórkach, na twoich dolinach i we wszystkich twoich strumieniach padną pobici mieczem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 9, 'Zamienię cię w wieczne spustoszenie i twoje miasta nie będą zamieszkałe. I poznacie, że ja jestem Panem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 10, 'Ponieważ powiedziałaś: Te dwa narody i te dwa kraje będą moje, weźmiemy je w posiadanie, chociaż Pan tam przebywał;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 11, 'Jak żyję, mówi Pan Bóg, uczynię według twego gniewu i według twojej zawiści, z jaką postąpiłaś w swej nienawiści względem nich, i dam się poznać wśród nich, gdy cię osądzę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 12, 'I poznasz, że ja jestem Panem i słyszałem wszystkie twoje obelgi, które wypowiedziałaś przeciw górom Izraela, mówiąc: Są spustoszone, zostały nam dane na pożarcie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 13, 'Tak się wynosiliście swoimi ustami przeciwko mnie i mnożyliście swoje słowa przeciwko mnie. Ja to słyszałem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 14, 'Tak mówi Pan Bóg: Kiedy cała ziemia będzie się radować, wtedy zamienię cię w pustkowie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 15, 'Jak ty się radowałaś nad dziedzictwem domu Izraela, że zostało spustoszone, tak uczynię i tobie: będziesz spustoszona, góro Seir i cały Edomie. I poznają, że ja jestem Panem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 1, 'A ty, synu człowieczy, prorokuj o górach Izraela i mów: Góry Izraela, słuchajcie słowa Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 2, 'Tak mówi Pan Bóg: Ponieważ wróg powiedział o was: Ha! Prastare wysokości stały się naszą posiadłością;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 3, 'Prorokuj i mów: Tak mówi Pan Bóg: Ponieważ zburzono was i pochłonięto zewsząd, abyście się stały dziedzictwem reszty narodów i wzięto was na język oraz na obmowę ludzi;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 4, 'Dlatego, góry Izraela, słuchajcie słowa Pana Boga. Tak mówi Pan Bóg do gór i pagórków, do strumieni i dolin, do spustoszonych ruin i opuszczonych miast, które stały się łupem i pośmiewiskiem dla reszty okolicznych narodów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 5, 'Dlatego tak mówi Pan Bóg: Zaprawdę, w ogniu swojej zapalczywości będę mówił przeciw reszcie tych narodów i przeciwko całemu Edomowi, którzy wzięli sobie moją ziemię w posiadanie z radością całego serca i z pogardą duszy, aby siedlisko jej wygnańców stało się łupem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 6, 'Dlatego prorokuj o ziemi Izraela i mów do gór i pagórków, do strumieni i dolin: Tak mówi Pan Bóg: Oto przemówiłem w swojej zazdrości i w swojej zapalczywości, ponieważ znosiliście zniewagi narodów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 7, 'Dlatego tak mówi Pan Bóg: Ja podniosłem swoją rękę: Zaprawdę, te narody, które są wokół was, same będą znosić swoją hańbę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 8, 'A wy, góry Izraela, wypuścicie swe gałązki i wydacie swój owoc memu ludowi Izraela, bo zbliża się jego przyjście.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 9, 'Oto bowiem idę do was i powrócę do was, będziecie uprawiane i obsiane.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 10, 'I rozmnożę na was ludzi, cały dom Izraela, miasta będą zamieszkane i miejsca zburzone zostaną odbudowane.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 11, 'Rozmnożę na was ludzi i bydło, będą liczni i płodni. I sprawię, że będziecie mieszkać jak za waszych dawnych czasów i będę wam czynić lepiej niż na początku. I poznacie, że ja jestem Panem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 12, 'Bo przyprowadzę na was ludzi, swój lud Izraela. Posiądą cię i będziesz dla nich dziedzictwem, i nigdy więcej nie pozbawisz ich potomstwa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 13, 'Tak mówi Pan Bóg: Ponieważ mówią do was: Ty jesteś tą ziemią, która pożera ludzi i pozbawia narody potomstwa;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 14, 'Już nie będziesz pożerać ludzi ani pozbawiać potomstwa swoje narody, mówi Pan Bóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 15, 'I już nie dopuszczę, aby w tobie były słyszane obelgi narodów, nie będziesz już znosić zniewag ludzi i nie będziesz już doprowadzać swoich narodów do upadku, mówi Pan Bóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 16, 'I doszło do mnie słowo Pana mówiące:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 17, 'Synu człowieczy, gdy dom Izraela mieszkał w swej ziemi, plugawił ją swymi drogami i czynami. Jego droga wobec mnie była jak nieczystość odłączonej kobiety.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 18, 'Dlatego wylałem na nich swój gniew z powodu krwi, którą wylali na ziemię, i z powodu ich bożków, którymi ją splugawili.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 19, 'I rozproszyłem ich między narodami, i zostali rozrzuceni po ziemiach. Osądziłem ich według ich dróg i według ich czynów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 20, 'A gdy weszli do narodów, do których przybyli, zbezcześcili tam moje święte imię, gdy o nich mówiono: To jest lud Pana, a z jego ziemi wyszli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 21, 'Ale żal mi się zrobiło mojego świętego imienia, które zbezcześcił dom Izraela wśród narodów, do których przybył.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 22, 'Dlatego mów do domu Izraela: Tak mówi Pan Bóg: Nie dla was ja to czynię, domu Izraela, ale przez wzgląd na moje święte imię, które zbezcześciliście wśród narodów, do których przybyliście.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 23, 'I uświęcę moje wielkie imię, które było zbezczeszczone wśród narodów, które wy zbezcześciliście pośród nich. I poznają narody, że ja jestem Panem, mówi Pan Bóg, gdy będę uświęcony w was na ich oczach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 24, 'Zabiorę was bowiem spośród narodów, zgromadzę was ze wszystkich ziem i przyprowadzę was do waszej ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 25, 'I pokropię was czystą wodą, i będziecie czyści. Oczyszczę was ze wszystkich waszych nieczystości i ze wszystkich waszych bożków.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 26, 'I dam wam nowe serce, i włożę nowego ducha do waszego wnętrza. Wyjmę serce kamienne z waszego ciała, a dam wam serce mięsiste.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 27, 'Włożę mego Ducha do waszego wnętrza i sprawię, że będziecie chodzić według moich ustaw i będziecie przestrzegać moich sądów, i wykonywać je.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 28, 'Zamieszkacie w ziemi, którą dałem waszym ojcom, będziecie moim ludem, a ja będę waszym Bogiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 29, 'I wyzwolę was od wszystkich waszych nieczystości. Przywołam zboża i rozmnożę je, a nie dopuszczę do was głodu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 30, 'Rozmnożę też owoc drzew i plony pól, abyście już nie znosili hańby głodu wśród narodów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 31, 'Wtedy przypomnicie sobie wasze złe drogi i wasze czyny, które nie były dobre, i samych siebie będziecie się brzydzić z powodu waszych nieprawości i obrzydliwości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 32, 'Nie ze względu na was to czynię, mówi Pan Bóg, niech wam to będzie wiadome. Wstydźcie się i rumieńcie się z powodu waszych dróg, domu Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 33, 'Tak mówi Pan Bóg: W dniu, w którym was oczyszczę ze wszystkich waszych nieprawości, zaludnię miasta i miejsca zburzone zostaną odbudowane.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 34, 'A spustoszała ziemia będzie uprawiana, zamiast być spustoszeniem na oczach wszystkich przechodniów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 35, 'I powiedzą: Ta spustoszona ziemia stała się jak ogród Eden; miasta puste, opuszczone i zniszczone, są teraz obwarowane i zamieszkałe.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 36, 'I narody, które wokół was pozostaną, poznają, że ja, Pan, odbudowałem to, co zburzone, i zasadziłem to, co spustoszone. Ja, Pan, to powiedziałem i uczynię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 37, 'Tak mówi Pan Bóg: Jeszcze w tym jednym dam się uprosić domowi Izraela, aby im to uczynić: Pomnożę liczbę ich ludzi jak trzodę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 38, 'Jak trzodę na ofiary, jak trzodę Jerozolimy w czasie jej uroczystych świąt, tak spustoszone miasta będą wypełnione trzodami ludzi. I poznają, że ja jestem Panem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 1, 'Ręka Pana była nade mną i on wyprowadził mnie w duchu Pana, i postawił mnie w środku doliny, która była pełna kości;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 2, 'Przeprowadził mnie obok nich dokoła, a oto było ich bardzo dużo na obszarze tej doliny, a oto były bardzo wyschłe.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 3, 'I powiedział do mnie: Synu człowieczy, czy te kości ożyją? Odpowiedziałem: Panie Boże, ty wiesz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 4, 'Wtedy powiedział do mnie: Prorokuj o tych kościach i mów do nich: Wyschłe kości, słuchajcie słowa Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 5, 'Tak mówi Pan Bóg do tych kości: Oto sprawię, że wstąpi w was tchnienie i ożyjecie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 6, 'Nałożę na was ścięgna i sprawię, że obrośniecie ciałem, oblekę was w skórę, i włożę w was tchnienie, i ożyjecie. I poznacie, że ja jestem Panem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 7, 'Prorokowałem więc, jak mi rozkazano. A gdy prorokowałem, powstał szum, a oto poruszenie; i kości zbliżyły się do siebie, kość do swojej kości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 8, 'I spojrzałem, a oto pojawiły się na nich ścięgna, obrosły ciałem i skóra je powlekła z wierzchu, ale nie było w nich tchnienia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 9, 'I powiedział do mnie: Prorokuj do wiatru, prorokuj, synu człowieczy, i powiedz do wiatru: Tak mówi Pan Bóg: Przyjdź od czterech wiatrów, tchnienie, i powiej na tych zabitych, i niech ożyją.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 10, 'Prorokowałem więc, jak mi rozkazał, i wstąpiło w nie tchnienie, a ożyły i stanęły na nogach, bardzo, bardzo liczne wojsko.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 11, 'I powiedział do mnie: Synu człowieczy, te kości to cały dom Izraela. Oto mówią: Nasze kości wyschły, nasza nadzieja przepadła, jesteśmy zgubieni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 12, 'Dlatego prorokuj i mów do nich: Tak mówi Pan Bóg: Oto otworzę wasze groby i wyprowadzę was z waszych grobów, ludu mój, i przyprowadzę was do ziemi Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 13, 'I poznacie, że ja jestem Panem, gdy otworzę wasze groby i wyprowadzę was z waszych grobów, ludu mój.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 14, 'Włożę w was mojego ducha i ożyjecie, i osadzę was w waszej ziemi. I poznacie, że ja, Pan, to powiedziałem i uczyniłem, mówi Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 15, 'I doszło do mnie słowo Pana mówiące:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 16, 'A ty, synu człowieczy, weź sobie kawałek drewna i napisz na nim: Dla Judy i synów Izraela, jego towarzyszy. Weź też drugi kawałek drewna i napisz na nim: Dla Józefa, drewno Efraima i całego domu Izraela, jego towarzyszy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 17, 'I złóż je jedno z drugim w jeden kawałek, aby stanowiły jedno w twoim ręku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 18, 'A gdy synowie twego ludu zapytają cię: Czy nie oznajmisz nam, co przez to rozumiesz?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 19, 'Powiesz im: Tak mówi Pan Bóg: Oto wezmę drewno Józefa, które jest w ręku Efraima oraz pokolenia Izraela, jego towarzyszy, i przyłożę je do tamtego, do drewna Judy, i uczynię je jednym drewnem, i staną się jednym w moim ręku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 20, 'A te drewna, na których napiszesz, będą w twoim ręku na ich oczach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 21, 'Potem powiedz do nich: Tak mówi Pan Bóg: Oto wezmę synów Izraela spośród narodów, do których przybyli, zgromadzę ich zewsząd i przyprowadzę ich do ich ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 22, 'I uczynię ich jednym narodem w ziemi, na górach Izraela, i jeden król będzie królem nad nimi wszystkimi. Nie będą już dwoma narodami i już nie podzielą się na dwa królestwa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 23, 'Nie splugawią się już swymi bożkami i obrzydliwościami oraz wszelkimi występkami. Wybawię ich ze wszystkich ich miejsc zamieszkania, gdzie zgrzeszyli, i oczyszczę ich. I będą moim ludem, a ja będę ich Bogiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 24, 'Mój sługa Dawid będzie królem nad nimi i wszyscy będą mieli jednego pasterza. Będą chodzić według moich sądów, będą przestrzegać moich ustaw i wykonywać je.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 25, 'I zamieszkają w tej ziemi, którą dałem mojemu słudze Jakubowi, w której mieszkali wasi ojcowie; będą w niej mieszkali, oni, ich synowie i synowie ich synów, aż na wieki, a mój sługa Dawid będzie ich księciem na wieki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 26, 'Zawrę też z nimi przymierze pokoju, które będzie przymierzem wiecznym z nimi. Osadzę ich i rozmnożę, i umieszczę swoją świątynię pośród nich na wieki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 27, 'Mój przybytek będzie wśród nich i będę ich Bogiem, a oni będą moim ludem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 28, 'I poznają narody, że ja jestem Panem, który uświęca Izraela, gdy moja świątynia będzie wśród nich na wieki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 1, 'I doszło do mnie słowo Pana mówiące:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 2, 'Synu człowieczy, zwróć swoją twarz przeciwko Gogowi w ziemi Magog, naczelnemu księciu w Meszek i Tubal, i prorokuj przeciw niemu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 3, 'I mów: Tak mówi Pan Bóg: Oto jestem przeciw tobie, Gogu, naczelny księciu w Meszek i Tubal.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 4, 'Zawrócę cię i włożę haki w twoje szczęki, i wyprowadzę ciebie i całe twoje wojsko, konie i jeźdźców, wszystkich w pełnym uzbrojeniu, wielki zastęp z tarczami i puklerzami, wszystkich władających mieczem;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 5, 'A z nimi Persów, Etiopczyków i Putejczyków, wszystkich uzbrojonych w tarczę i hełm;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 6, 'Gomer i wszystkie jego oddziały, dom Togarmy z północnych stron i wszystkie jego oddziały, liczne narody z tobą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 7, 'Przygotuj się i bądź gotowy, ty i twoje wszystkie zastępy, które się zebrały u ciebie, i bądź ich stróżem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 8, 'Po wielu dniach zostaniesz nawiedzony, przy końcu lat przybędziesz do ziemi uwolnionej od miecza, której lud został zebrany spośród wielu narodów, na góry Izraela, które były długo spustoszeniem, a będąc wyprowadzeni spośród narodów, oni wszyscy zamieszkają bezpiecznie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 9, 'Wyruszysz i nadciągniesz jak burza, będziesz jak chmura okrywająca ziemię, ty i wszystkie twoje zastępy oraz liczne ludy z tobą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 10, 'Tak mówi Pan Bóg: W tym dniu zrodzą się myśli w twoim sercu i będziesz miał złe zamiary;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 11, 'I powiesz: Wyruszę do ziemi o nieobwarowanych wsiach; napadnę na ludzi spokojnych, którzy mieszkają bezpiecznie, na wszystkich, którzy mieszkają bez murów i nie mają ani rygli, ani bram;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 12, 'Aby zabrać łupy i zagarnąć zdobycze, aby swą rękę położyć na spustoszone miejsca, które znowu zostały zamieszkane, i na lud zgromadzony spośród narodów, który zdobył bydło i dobra, a mieszka w środku ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 13, 'Szeba, Dedan i kupcy Tarszisz oraz wszystkie jego lwięta zapytają cię: Czy przybyłeś, aby zabrać łupy? Czy na zagarnięcie zdobyczy zgromadziłeś swoje zastępy, aby zabrać srebro i złoto, zabierać bydło i dobra, aby zgarnąć wielki łup?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 14, 'Dlatego prorokuj, synu człowieczy, i mów do Goga: Tak mówi Pan Bóg: Czy w dniu, gdy mój lud Izraela będzie mieszkał bezpiecznie, nie będziesz o tym wiedział?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 15, 'I przyjdziesz ze swego miejsca z północnych stron, ty i liczne ludy z tobą, wszyscy jadący na koniach, wielki zastęp i liczne wojsko;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 16, 'I nadciągniesz przeciwko mojemu ludowi Izraela jak chmura, by okryć tę ziemię. W dniach ostatecznych przyprowadzę cię do swojej ziemi, aby poznały mnie narody, gdy będę uświęcony w tobie, Gogu, na ich oczach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 17, 'Tak mówi Pan Bóg: Czyż ty nie jesteś tym, o którym mówiłem w dawnych dniach przez moje sługi, proroków Izraela, którzy prorokowali za dni tamtych lat, że ja sprowadzę cię na nich?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 18, 'Ale w dniu, w którym Gog nadciągnie przeciwko ziemi Izraela, mówi Pan Bóg, wzmoże się zapalczywość mego gniewu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 19, 'Powiedziałem bowiem w swojej gorliwości i w ogniu swojego gniewu: Zaprawdę, w tym dniu będzie wielkie trzęsienie w ziemi Izraela;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 20, 'I zadrżą przede mną ryby morskie i ptactwo niebieskie, zwierzęta polne i wszelkie zwierzęta pełzające po ziemi, a także wszyscy ludzie, którzy są na powierzchni ziemi; rozpadną się góry, upadną wysokie wieże i każdy mur runie na ziemię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 21, 'Przywołam miecz przeciwko niemu po wszystkich moich górach, mówi Pan Bóg. Miecz każdego zwróci się przeciwko swemu bratu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 22, 'I osądzę go zarazą i krwią, ześlę ulewny deszcz i kamienie gradu, ogień i siarkę – na niego, na jego wojska i na liczne ludy, które z nim będą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 23, 'Okażę się wielki i święty i dam się poznać na oczach wielu narodów, i poznają, że ja jestem Panem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 1, 'Ty więc, synu człowieczy, prorokuj przeciwko Gogowi i mów: Tak mówi Pan Bóg: Oto jestem przeciwko tobie, Gogu, naczelny księciu w Meszek i Tubal.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 2, 'Zawrócę cię i zostawię z ciebie tylko szóstą część, wyprowadzę cię z północnych stron i wprowadzę cię na góry Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 3, 'Wytrącę twój łuk z twej lewej ręki i wybiję twoje strzały z twej prawej ręki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 4, 'Na górach Izraela padniesz ty i wszystkie twoje zastępy oraz ludy, które będą z tobą. Wydam cię na pożarcie ptactwu, wszelkim istotom skrzydlatym i zwierzętom polnym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 5, 'Padniesz na otwartym polu, bo ja to wypowiedziałem, mówi Pan Bóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 6, 'I ześlę ogień na Magoga i na tych, którzy bezpiecznie mieszkają na wyspach. I poznają, że ja jestem Panem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 7, 'A dam poznać moje święte imię pośród mojego ludu Izraela i nie pozwolę już zbezcześcić mojego świętego imienia. I poznają narody, że ja jestem Panem, Święty w Izraelu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 8, 'Oto nadchodzi to i spełni się, mówi Pan Bóg. To jest dzień, o którym mówiłem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 9, 'Wtedy mieszkańcy miast Izraela wyjdą, rozniecą ogień i spalą oręże: tarcze i puklerze, łuki i strzały, oszczepy i włócznie. I będą tym palić ogień przez siedem lat.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 10, 'Nie będą znosić drwa z pola ani rąbać go w lasach, ale orężem będzie się palić. A złupią tych, którzy ich łupili, i będą plądrować tych, którzy ich plądrowali, mówi Pan Bóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 11, 'I stanie się w tym dniu, że dam Gogowi miejsce na grób, tam w Izraelu, dolinę przechodzących na wschód od morza, która zatka usta przechodniów. Pogrzebią tam Goga i całą jego rzeszę i nazwą ją Doliną Hamon-Gog.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 12, 'Dom Izraela będzie ich grzebać przez siedem miesięcy, aby oczyścić ziemię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 13, 'A tak będzie ich grzebał cały lud tej ziemi i wyjdzie mu to na chwałę w dniu, w którym będę uwielbiony, mówi Pan Bóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 14, 'I wyznaczą mężczyzn, którzy będą stale przechodzić po tej ziemi, aby wraz z przechodniami grzebać tych, którzy pozostali na ziemi, by ją oczyścić. Po upływie siedmiu miesięcy zaczną przeszukiwanie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 15, 'A gdy przybysze będą przechodzić przez ziemię, a któryś z nich zobaczy kość ludzką, postawią przy niej znak, aż grabarze ją pogrzebią w Dolinie Hamon-Gog.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 16, 'A nazwa tego miasta będzie Hamona. I tak oczyszczą ziemię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 17, 'A ty, synu człowieczy, tak mówi Pan Bóg: Powiedz ptactwu, wszelkim istotom skrzydlatym i zwierzętom polnym: Zbierzcie się i przyjdźcie, zgromadźcie się zewsząd na moją ofiarę, którą wam przygotowałem, wielką ofiarę na górach Izraela, abyście jedli mięso i pili krew.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 18, 'Będziecie jeść mięso mocarzy i pić krew książąt ziemi, baranów, jagniąt, kozłów i cielców, wszystkie tuczniki z Baszanu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 19, 'Najecie się tłuszczu do syta i upoicie się krwią z mojej ofiary, którą wam przygotowałem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 20, 'I nasycicie się przy moim stole końmi, jeźdźcami, mocarzami i wszystkimi wojownikami, mówi Pan Bóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 21, 'Tak objawię moją chwałę wśród narodów. Wszystkie narody zobaczą mój sąd, który wykonałem, i moją rękę, którą na nie wyciągnąłem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 22, 'I pozna dom Izraela, że ja jestem Panem, ich Bogiem, od tego dnia i na zawsze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 23, 'Poznają też narody, że dom Izraela z powodu swojej nieprawości został uprowadzony do niewoli, ponieważ wystąpił przeciwko mnie. Dlatego też zakryłem przed nim swoje oblicze i wydałem go w ręce jego wrogów, i polegli wszyscy od miecza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 24, 'Według ich nieczystości i według ich występków postąpiłem z nimi i zakryłem przed nimi swoje oblicze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 25, 'Dlatego tak mówi Pan Bóg: Teraz odwrócę niewolę Jakuba i zmiłuję się nad całym domem Izraela, i będę zazdrosny o moje święte imię;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 26, 'Gdy już zniosą swoją hańbę i wszystkie swoje przestępstwa, którymi wystąpili przeciwko mnie, wtedy gdy bezpiecznie mieszkali w swojej ziemi, a nikt ich nie trwożył.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 27, 'A gdy sprowadzę ich z narodów i zgromadzę z ziem ich wrogów, i będę w nich uświęcony na oczach wielu narodów;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 28, 'Wtedy poznają, że ja jestem Panem, ich Bogiem, który uprowadził ich do niewoli wśród narodów, ale teraz zgromadzę ich znowu w ich ziemi, a nie pozostawię tam żadnego z nich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 29, 'I nie zakryję już przed nimi mojego oblicza, gdyż wyleję mojego ducha na dom Izraela, mówi Pan Bóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 1, 'W dwudziestym piątym roku naszego wygnania, na początku roku, dziesiątego dnia miesiąca, czternaście lat po zburzeniu miasta, w tym właśnie dniu spoczęła na mnie ręka Pana i zaprowadził mnie tam.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 2, 'W widzeniach Bożych przywiódł mnie do ziemi Izraela i postawił na bardzo wysokiej górze, na której było coś jakby budowa miasta, na południu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 3, 'I zaprowadził mnie tam, a oto mąż, który z wyglądu był jakby ze spiżu, miał lniany sznur w ręku i pręt mierniczy, a stał w bramie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 4, 'I przemówił do mnie ten mąż: Synu człowieczy, popatrz swymi oczami, słuchaj swymi uszami i weź sobie do serca wszystko, co ci pokażę. Po to bowiem zostałeś tu przyprowadzony, aby ci to pokazać. Oznajmij wszystko, co widzisz, domowi Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 5, 'I oto mur otaczał dom ze wszystkich stron dokoła, a w ręku tego męża był pręt mierniczy na sześć łokci – liczonych jako łokieć i szerokość dłoni – i wymierzył grubość budowli – jeden pręt, i wysokość – jeden pręt.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 6, 'Potem wszedł do bramy, która była zwrócona ku wschodowi, wszedł po schodach i zmierzył próg bramy: jeden pręt szerokości, a drugi próg miał jeden pręt szerokości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 7, 'Każda wnęka miała jeden pręt długości i jeden pręt szerokości, a między wnękami był odstęp na pięć łokci; próg bramy obok przedsionka bramy od wewnątrz wynosił jeden pręt.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 8, 'I zmierzył przedsionek bramy od wewnątrz – jeden pręt.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 9, 'Zmierzył też przedsionek bramy – osiem łokci, a jej filary – dwa łokcie. Przedsionek bramy był wewnątrz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 10, 'Wnęki bramy wschodniej były trzy z jednej i trzy z drugiej strony; wszystkie trzy miały ten sam wymiar. Jeden wymiar miały też filary po obu stronach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 11, 'Zmierzył też szerokość wejścia bramy – dziesięć łokci, a długość bramy – trzynaście łokci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 12, 'Przed wnękami była także przegroda na jeden łokieć, jeden łokieć miała też przegroda po drugiej stronie. Każda wnęka miała po sześć łokci z jednej i sześć łokci z drugiej strony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 13, 'Potem zmierzył bramę od dachu jednej wnęki aż do dachu drugiej, szerokość była na dwadzieścia pięć łokci, a drzwi były naprzeciwko siebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 14, 'I uczynił filary na sześćdziesiąt łokci, a każdy filar na dziedzińcu u bramy wokoło miał jedną miarę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 15, 'A od fasady bramy wejściowej do fasady przedsionka wewnątrz bramy było pięćdziesiąt łokci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 16, 'Były też wąskie okna we wnękach, przy filarach wewnątrz bramy dokoła, a także przy przedsionkach. Dokoła od wewnątrz były okna, a na filarach były palmy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 17, 'Potem przyprowadził mnie na dziedziniec zewnętrzny, a oto znajdowały się tam komory i posadzka uczyniona na dziedzińcu zewsząd dokoła: trzydzieści komór było na tej posadzce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 18, 'A posadzka była wzdłuż bram, odpowiednio do długości bram. Była to posadzka dolna.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 19, 'Potem zmierzył odległość od fasady bramy dolnej do fasady bramy dziedzińca wewnętrznego z zewnątrz: sto łokci w kierunku wschodnim i północnym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 20, 'Zmierzył też długość i szerokość bramy północnej na dziedzińcu zewnętrznym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 21, 'Miała trzy wnęki z jednej i trzy z drugiej strony; jej filary i przedsionki miały taki sam wymiar jak pierwsza brama: pięćdziesiąt łokci długości i dwadzieścia pięć łokci szerokości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 22, 'Jej okna, przedsionek i palmy miały taki sam wymiar jak brama wschodnia. Po siedmiu stopniach wchodziło się do niej, a jej przedsionek był tuż przed schodami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 23, 'Brama dziedzińca wewnętrznego była naprzeciwko bramy północnej, jak brama wschodnia; i zmierzył od bramy do bramy – sto łokci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 24, 'Potem zaprowadził mnie w stronę południa, a oto była brama południowa; i zmierzył jej filary i przedsionek – miały te same wymiary.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 25, 'Miała ona, podobnie jak jej przedsionek, okna wokoło, tak jak tamte okna. Miała pięćdziesiąt łokci długości i dwadzieścia pięć łokci szerokości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 26, 'Prowadziło do niej siedem stopni, a jej przedsionek był przed nimi. Miała ona palmy na filarach z jednej i z drugiej strony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 27, 'Była też brama południowa na dziedzińcu wewnętrznym; i zmierzył od bramy do bramy w stronę południa – sto łokci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 28, 'Potem zaprowadził mnie na dziedziniec wewnętrzny przez bramę południową i zmierzył bramę południową: miała te same wymiary.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 29, 'A jej wnęki, jej filary i jej przedsionek miały te same wymiary. Miała ona również, jak i jej przedsionek, okna wokoło. Miała pięćdziesiąt łokci długości i dwadzieścia pięć łokci szerokości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 30, 'Dokoła był przedsionek na dwadzieścia pięć łokci długości i pięć łokci szerokości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 31, 'A jej przedsionek był na dziedzińcu zewnętrznym, a na jej filarach były palmy. Prowadziło do niej osiem stopni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 32, 'Zaprowadził mnie też na dziedziniec wewnętrzny w stronę wschodu i zmierzył bramę: m iała te same wymiary.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 33, 'Jej wnęki, jej filary i jej przedsionek miały te same wymiary. Miała ona również, tak jak jej przedsionek, okna wokoło. Miała pięćdziesiąt łokci długości, dwadzieścia pięć łokci szerokości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 34, 'A jej przedsionek był na dziedzińcu zewnętrznym, a na jej filarach były palmy po obu stronach. Prowadziło do niej osiem stopni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 35, 'Potem zaprowadził mnie do bramy północnej i zmierzył ją: miała te same wymiary;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 36, 'Jej wnęki, jej filary i jej przedsionek, a także jej okna wokoło. Jej długość wynosiła pięćdziesiąt łokci, a jej szerokość – dwadzieścia pięć łokci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 37, 'Jej filary były na dziedzińcu zewnętrznym, a na jej filarach były palmy po obu stronach. Prowadziło do niej osiem stopni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 38, 'Były też komory i wejście do nich przy filarach bram, tam obmywano ofiarę całopalną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 39, 'W przedsionku bramy były dwa stoły po jednej stronie i dwa stoły po drugiej stronie, na których zabijano ofiarę całopalną, ofiarę za grzech i ofiarę za przewinienie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 40, 'Na stronie zewnętrznej, przy wejściu bramy północnej, były dwa stoły, także i po drugiej stronie, która jest przy przedsionku bramy, były dwa stoły.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 41, 'Cztery stoły z jednej i cztery stoły z drugiej strony, z boku bramy; wszystkich stołów, na których zabijano ofiary, było osiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 42, 'Te cztery stoły do całopalenia były z kamienia ciosanego, długie na półtora łokcia, szerokie na półtora łokcia i wysokie na jeden łokieć. Na nich kładziono sprzęt do zabijania ofiary całopalnej i innych ofiar.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 43, 'Wokoło były też przymocowane haki o grubości jednej dłoni, a mięso leżało na stołach dla ofiar.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 44, 'Na zewnątrz bramy wewnętrznej, na dziedzińcu wewnętrznym, były komory dla śpiewaków. Jeden rząd był z boku bramy północnej, zwrócony w kierunku południa, drugi rząd był z boku bramy wschodniej, zwrócony w kierunku północy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 45, 'I powiedział do mnie: Te komory, które są zwrócone w kierunku południa, są dla kapłanów, którzy pełnią straż w domu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 46, 'Te zaś komory, które są zwrócone w kierunku północy, są dla kapłanów, którzy pełnią straż przy ołtarzu. Są to synowie Sadoka, którzy spośród synów Lewiego zbliżają się do Pana, aby mu służyć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 47, 'I zmierzył dziedziniec: długość wynosiła sto łokci, szerokość – sto łokci, był to kwadrat; a ołtarz był przed domem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 48, 'Potem wprowadził mnie do przedsionka domu i zmierzył filary przedsionka: pięć łokci z jednej i pięć łokci z drugiej strony. Szerokość bramy wynosiła trzy łokcie z jednej i trzy łokcie z drugiej strony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 49, 'Długość przedsionka wynosiła dwadzieścia łokci, a szerokość – jedenaście łokci. Wstępowało się do niego po stopniach; były też kolumny przy filarach, jedna z jednej, druga z drugiej strony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 1, 'Potem wprowadził mnie do świątyni i zmierzył filary: sześć łokci wynosiła szerokość z jednej strony i sześć łokci szerokość z drugiej strony, według szerokości przybytku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 2, 'A szerokość drzwi wynosiła dziesięć łokci, a boczne ściany wejścia miały pięć łokci z jednej i pięć łokci z drugiej strony. I zmierzył jej długość: czterdzieści łokci, a jej szerokość: dwadzieścia łokci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 3, 'Następnie wszedł do wnętrza i zmierzył filary przy wejściu – dwa łokcie, drzwi – sześć łokci, a szerokość drzwi – siedem łokci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 4, 'Zmierzył też długość – dwadzieścia łokci, jego szerokość – dwadzieścia łokci, odpowiednio do świątyni. I powiedział do mnie: To jest Miejsce Najświętsze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 5, 'Potem zmierzył mur domu – sześć łokci, a szerokość każdej bocznej komory – cztery łokcie wokół całego domu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 6, 'Boczne komory znajdowały się na trzech poziomach, jedna nad drugą, w liczbie trzydziestu. Wchodziły one w mur otaczający dom, aby komory na nim się opierały, ale nie opierały się na murze domu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 7, 'I rozszerzały się boczne komory dokoła domu, odpowiednio do wzrastającej wysokości, gdyż mur dokoła domu tracił na grubości. Dlatego szerokość domu wzrastała od najniższych komór do najwyższych, do których się wchodziło schodami poprzez te środkowe.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 8, 'Widziałem też wysokość domu dokoła i fundament tych komór, a miał pełny pręt – sześć łokci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 9, 'Grubość zewnętrznego muru bocznych komór wynosiła pięć łokci, a przed komorami, które były przy domu, pozostała wolna przestrzeń.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 10, 'A między komorami i komórkami odległość wynosiła dwadzieścia łokci wszędzie wokół domu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 11, 'A drzwi bocznych komór wychodziły na wolną przestrzeń, jedne drzwi na północ, a drugie na południe. Szerokość tej wolnej przestrzeni wynosiła pięć łokci wszędzie dokoła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 12, 'A budowla, która była poza obszarem wyznaczonym na stronie zachodniej, miała szerokość siedemdziesięciu łokci, mur tej budowli miał grubość pięciu łokci wszędzie wokoło i jej długość wynosiła dziewięćdziesiąt łokci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 13, 'Potem zmierzył dom – miał długość stu łokci; a obszar wyznaczony, budowla i jej mury miały długość stu łokci;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 14, 'Także szerokość fasady domu oraz obszaru wyznaczonego od strony wschodniej wynosiła sto łokci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 15, 'Zmierzył też długość budowli przed obszarem wyznaczonym, która była za nim, także i jej krużganki z jednej i z drugiej strony, i wynosiła sto łokci, a tak samo było z wewnętrzną świątynią wraz z przedsionkami dziedzińca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 16, 'Progi, wąskie okna, krużganki wokoło trzech stron naprzeciwko progu pokryte były deskami dokoła, od ziemi aż do okien, a okna były pokryte deskami;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 17, 'Od wierzchu drzwi aż do wewnętrznej i zewnętrznej strony domu, i cały mur wszędzie dokoła, wewnątrz i zewnątrz, dobrze wymierzony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 18, 'Tak oto były wykonane cherubiny i palmy: każda palma była między dwoma cherubinami, a każdy cherubin miał dwie twarze;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 19, 'Twarz ludzka była zwrócona w stronę palmy z jednej strony, a twarz młodego lwa zwrócona w stronę palmy z drugiej strony. Tak wykonano to w całym domu wszędzie wokoło.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 20, 'Od ziemi aż ponad wejście były wyrzeźbione cherubiny i palmy, także na ścianie świątyni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 21, 'Filary świątyni były czworokątne, a wygląd Miejsca Najświętszego był jak wygląd świątyni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 22, 'Ołtarz drewniany był wysoki na trzy łokcie i szeroki na dwa łokcie; jego rogi, jego podstawa i jego ściany były z drewna. Wtedy powiedział do mnie: To jest stół, który stoi przed Panem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 23, 'A świątynia i Miejsce Najświętsze miały podwójne drzwi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 24, 'A drzwi były dwuskrzydłowe, miały dwa skrzydła obrotowe; dwa skrzydła miały jedne drzwi i dwa miały drugie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 25, 'A wykonano na nich, na tych drzwiach świątyni, cherubiny i palmy, tak jak wykonano je na ścianach; były także drewniane belki nad przedsionkiem na zewnątrz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 26, 'Na wąskich oknach były palmy po obu stronach, na bokach przedsionka, także na bocznych komorach domu i na belkach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 1, 'I wyprowadził mnie na dziedziniec zewnętrzny w kierunku północy, i wprowadził mnie do tych komórek, które stały naprzeciwko obszaru wyznaczonego i naprzeciwko budowli, od strony północy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 2, 'Ich długość od strony północnych drzwi wynosiła sto łokci, a ich szerokość pięćdziesiąt łokci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 3, 'Naprzeciw dziedzińca wewnętrznego, który miał dwadzieścia łokci, i naprzeciw posadzki dziedzińca zewnętrznego, były krużganki naprzeciw krużganków na trzech poziomach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 4, 'A przed komórkami było przejście szerokie na dziesięć łokci wewnątrz i ścieżka do nich na jeden łokieć, a ich drzwi były od północy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 5, 'A górne komórki były węższe, ponieważ ich krużganki były szersze od tych w dolnej i środkowej części budowli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 6, 'Były bowiem trzypiętrowe, ale nie miały słupów jak słupy dziedzińców. Dlatego były węższe niż dolne i środkowe, począwszy od ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 7, 'A mur, który był na zewnątrz naprzeciw tych komórek w kierunku dziedzińca zewnętrznego przed komórkami, miał pięćdziesiąt łokci długości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 8, 'Długość bowiem komórek, które były na dziedzińcu zewnętrznym, wynosiła pięćdziesiąt łokci, a tych przed świątynią – sto łokci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 9, 'A poniżej tych komórek było wejście od wschodu, przez które wchodzi się do nich z dziedzińca zewnętrznego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 10, 'Na szerokości muru dziedzińca od strony wschodniej naprzeciw obszaru wyznaczonego i naprzeciw budowli były także komórki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 11, 'A ścieżka przed nimi była taka sama jak ścieżka tamtych komórek, które znajdowały się po stronie północnej: miały taką samą długość i taką samą szerokość. Takie same były ich wyjścia, ich drzwi oraz ich układ.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 12, 'A drzwi do tych komórek, które były po stronie południowej, były podobne do drzwi na początku przejścia, właśnie tego przejścia przed murem w stronę wschodu, którędy się do nich wchodzi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 13, 'Wtedy powiedział do mnie: Komórki północne i komórki południowe, które są przed obszarem wyznaczonym, to komórki święte, gdzie kapłani, którzy zbliżają się do Pana, będą jadali najświętsze rzeczy. Tam będą kłaść rzeczy najświętsze, ofiary z pokarmów, ofiary za grzech i ofiary za przewinienie. Jest to bowiem miejsce święte.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 14, 'Gdy kapłani wejdą tam, nie wyjdą ze świątyni na dziedziniec zewnętrzny, ale tam złożą swoje szaty, w których służyli, bo są święte. I założą inne szaty, i wtedy będą mogli zbliżyć się do tego, co należy do ludu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 15, 'A gdy ukończył mierzenie domu wewnętrznego, wyprowadził mnie w stronę bramy, która była zwrócona na wschód, i zmierzył zewsząd dokoła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 16, 'Prętem mierniczym zmierzył stronę wschodnią – pięćset prętów wokoło według pręta mierniczego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 17, 'Zmierzył także stronę północną – pięćset prętów wokoło według pręta mierniczego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 18, 'I zmierzył stronę południową – pięćset prętów mierniczych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 19, 'Potem obrócił się na stronę zachodnią i zmierzył – pięćset prętów według pręta mierniczego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 20, 'Zmierzył po czterech stronach mur zewsząd dokoła: długi na pięćset prętów i szeroki na pięćset prętów, aby oddzielić miejsce święte od pospolitego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 1, 'Potem zaprowadził mnie do bramy, do bramy, która była zwrócona w kierunku wschodnim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 2, 'A oto chwała Boga Izraela przybyła od wschodu i jego głos był jak szum wielkich wód, a ziemia jaśniała od jego chwały.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 3, 'A to widzenie, które miałem, było podobne do tego widzenia, które miałem, gdy przybyłem, aby zniszczyć miasto; widzenie, podobne do tego widzenia, które miałem nad rzeką Kebar. I upadłem na twarz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 4, 'Gdy chwała Pana weszła do domu przez bramę wschodnią;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 5, 'Wtedy uniósł mnie duch i wprowadził na dziedziniec wewnętrzny, a oto dom był pełen chwały Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 6, 'I usłyszałem, jak ktoś mówił do mnie z domu, a jakiś mąż stał obok mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 7, 'I powiedział do mnie: Synu człowieczy, oto miejsce mojego tronu i miejsce dla moich stóp, gdzie będę mieszkać pośród synów Izraela na wieki. Dom Izraela już nie zbezcześci mojego świętego imienia, ani on, ani jego królowie, przez swój nierząd i przez zwłoki swych królów na wyżynach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 8, 'Gdy kładli swój próg obok mojego progu, swoje odrzwia obok moich odrzwi i ścianę między mną a sobą, zbezcześcili bardzo moje święte imię przez swoje obrzydliwości, które popełniali. Dlatego zniszczyłem ich w swoim gniewie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 9, 'Ale teraz niech oddalą ode mnie swój nierząd i zwłoki swoich królów, a zamieszkam wśród nich na wieki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 10, 'Ty, synu człowieczy, powiedz domowi Izraela o tym domu, aby się wstydzili swoich nieprawości. Niech sobie wymierzą jego plan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 11, 'A jeśli się zawstydzą wszystkiego, co uczynili, wtedy opisz im wygląd tego domu, jego układ, jego wyjście i wejścia, cały jego kształt i wszystkie jego ustawy, cały kształt i wszystkie jego prawa. Zapisz to przed ich oczami, aby przestrzegali całego jego kształtu i wszystkich jego ustaw i czynili je.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 12, 'A takie jest prawo tego domu: Na szczycie góry cały jego obszar wszędzie dokoła ma być bardzo święty. Oto takie jest prawo tego domu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 13, 'I takie są wymiary ołtarza w łokciach liczonych na łokieć i cztery palce: jego podstawa wysoka na łokieć i szeroka na łokieć, a obramowanie na jego brzegu wokoło ma wynosić jedną piędź. Taka będzie górna część ołtarza:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 14, 'Od podstawy na ziemi aż do dolnego odstępu dwa łokcie, a jeden łokieć szerokości; od mniejszego odstępu do większego odstępu cztery łokcie, a jeden łokieć szerokości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 15, 'Ale sam ołtarz ma mieć cztery łokcie wysokości, a z ołtarza w górę – cztery rogi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 16, 'A ołtarz ma mieć dwanaście łokci długości i dwanaście szerokości, ma być czworokątny po czterech swoich bokach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 17, 'Górny odstęp ma mieć czternaście łokci długości i czternaście szerokości, po czterech bokach, a obramowanie wokół niego ma być na pół łokcia, jego podstawa – na łokieć wokoło i jego stopnie skierowane ku wschodowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 18, 'I powiedział do mnie: Synu człowieczy, tak mówi Pan Bóg: To są ustawy ołtarza na dzień, w którym zostanie zbudowany, aby na nim składać całopalenia i skrapiać go krwią.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 19, 'A kapłanom, Lewitom, którzy są z potomstwa Sadoka i zbliżają się do mnie, aby mi służyć, mówi Pan Bóg, dasz młodego cielca na ofiarę za grzech.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 20, 'Wtedy weźmiesz z jego krwi i nałożysz na cztery rogi, na cztery narożniki odstępu i na obramowanie wokoło. W ten sposób oczyścisz go i poświęcisz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 21, 'Potem weźmiesz tego cielca za grzech i spalisz go w oznaczonym miejscu domu poza świątynią.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 22, 'A drugiego dnia złożysz kozła bez skazy na ofiarę za grzech i oczyszczą ołtarz, tak jak oczyścili go cielcem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 23, 'A gdy dokonasz oczyszczenia, będziesz ofiarowywać młodego cielca bez skazy i barana z trzody bez skazy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 24, 'Gdy je ofiarujesz przed Panem, kapłani rzucą na nie sól i złożą je na całopalenie dla Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 25, 'Przez siedem dni codziennie będziesz składał kozła na ofiarę za grzech. Ma być przygotowany także młody cielec i baran z trzody bez skazy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 26, 'Przez siedem dni będą oczyszczać ołtarz i poświęcać go. I poświęcą się.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 27, 'A po upływie tych dni, dnia ósmego i w następne kapłani będą składali na ołtarzu wasze całopalenia i ofiary pojednawcze i przyjmę was łaskawie, mówi Pan Bóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 1, 'Potem zaprowadził mnie w stronę bramy świątyni zewnętrznej, która była zwrócona ku wschodowi, a była zamknięta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 2, 'I Pan powiedział do mnie: Ta brama będzie zamknięta i nie będzie otwierana ani nikt nie będzie przez nią wchodził. Pan bowiem, Bóg Izraela, wszedł przez nią i dlatego będzie zamknięta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 3, 'Jest dla księcia. Jedynie książę będzie zasiadać w niej, aby jeść chleb przed Panem. Będzie wchodził przez przedsionek tej bramy i tą samą drogą będzie wychodził.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 4, 'Następnie zaprowadził mnie przez bramę północną do przedniej strony domu. I spojrzałem, a oto chwała Pana napełniła dom Pana. I upadłem na twarz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 5, 'A Pan powiedział do mnie: Synu człowieczy, zwróć uwagę, patrz swoimi oczami i słuchaj swoimi uszami wszystkiego, co ci powiem o wszystkich ustawach domu Pana i o wszystkich jego prawach. Zwróć uwagę na wejście do domu i na wszystkie wyjścia ze świątyni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 6, 'I powiedz buntownikom, domowi Izraela: Tak mówi Pan Bóg: Dosyć już wszystkich waszych obrzydliwości, domu Izraela!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 7, 'Wprowadziliście tu cudzoziemców nieobrzezanych na sercu i nieobrzezanych na ciele, aby przebywali w mojej świątyni i zbezcześcili mój dom, gdy ofiarowaliście mój chleb, tłuszcz i krew, a oni łamali moje przymierze przez wszystkie wasze obrzydliwości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 8, 'A nie pełniliście straży przy moich świętych rzeczach, ale ustanowiliście sobie stróżów nad moją służbą w mojej świątyni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 9, 'Tak mówi Pan Bóg: Żaden cudzoziemiec nieobrzezany na sercu i nieobrzezany na ciele nie wejdzie do mojej świątyni, żaden spośród cudzoziemców, którzy są wśród synów Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 10, 'Także i Lewici, którzy się oddalili ode mnie, gdy Izrael błądził i odszedł ode mnie za swoimi bożkami, obciążą się swoją nieprawością.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 11, 'Lecz będą sługami w mojej świątyni, pełniąc obowiązki przy bramach domu, i będą służyć przy domu: będą zabijać ofiary na całopalenie i ofiary dla ludu i będą stać przed nimi, aby im służyć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 12, 'Ponieważ służyli im przed ich bożkami i byli dla domu Izraela przyczyną upadku w nieprawość, podniosłem rękę przeciwko nim, mówi Pan Bóg, i obciążą się swoją nieprawością.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 13, 'Nie będą się zbliżać do mnie, aby sprawować mi urząd kapłański, i nie będą zbliżać się do moich świętych rzeczy ani do najświętszych, ale poniosą swoją hańbę i obrzydliwości, które popełnili.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 14, 'Dlatego ustanowię ich stróżami porządku domu do każdej posługi i do wszystkiego, co będzie w nim wykonywane.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 15, 'Lecz kapłani, Lewici, synowie Sadoka, którzy pełnili straż w mojej świątyni, gdy synowie Izraela odeszli ode mnie, oni zbliżą się do mnie, aby mi służyć, i staną przede mną, aby mi ofiarować tłuszcz i krew, mówi Pan Bóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 16, 'Oni będą wchodzić do mojej świątyni i będą przystępować do mego stołu, aby mi służyć i pełnić moją służbę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 17, 'A gdy będą mieli wchodzić przez bramę dziedzińca wewnętrznego, ubiorą się w lniane szaty. Nie włożą na siebie nic wełnianego, gdy będą pełnić służbę w bramach dziedzińca wewnętrznego i wewnątrz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 18, 'Lniane mitry będą mieli na swej głowie i lniane spodnie na swych biodrach; nie będą się opasywać niczym, co wywołuje pot.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 19, 'A gdy będą wychodzić na dziedziniec zewnętrzny, do ludu na dziedzińcu zewnętrznym, zdejmą z siebie swoje szaty, w których pełnili służbę, a złożą je w komorach świątyni i ubiorą się w inne szaty; nie będą uświęcali ludu swoimi szatami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 20, 'Nie będą golić swojej głowy ani nie będą zapuszczać włosów, ale będą równo strzyc swoje głowy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 21, 'Żaden kapłan nie będzie pił wina, gdy będzie miał wchodzić na dziedziniec wewnętrzny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 22, 'Nie będą brali sobie za żonę ani wdowy, ani porzuconej, ale wezmą sobie dziewicę z potomstwa domu Izraela lub wdowę, która została wdową po kapłanie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 23, 'Będą uczyć mój lud różnicy pomiędzy tym, co święte, a tym, co nieświęte, a także mają uczyć rozróżniać pomiędzy tym, co nieczyste, a tym, co czyste.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 24, 'A gdy będzie jakiś spór, oni staną, aby sądzić, i będą sądzić według moich sądów. Będą przestrzegali moich praw i moich ustaw we wszystkie moje uroczyste święta i będą święcili moje szabaty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 25, 'Nie będą się zbliżać do człowieka zmarłego, aby się nie zanieczyścić. Mogą się jednak zanieczyścić przy ojcu lub matce, przy synu lub córce i przy bracie lub siostrze, która jeszcze nie była zamężna.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 26, 'A po jego oczyszczeniu odliczą mu siedem dni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 27, 'W tym dniu, w którym będzie wchodził do świątyni, na dziedziniec wewnętrzny, aby pełnić służbę w świątyni, złoży ofiarę za swój grzech, mówi Pan Bóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 28, 'To będzie ich dziedzictwo: Ja jestem ich dziedzictwem. Nie będzie się im dawać posiadłości w Izraelu. Ja jestem ich posiadłością.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 29, 'Będą spożywali ofiarę z pokarmów, ofiarę za grzech i ofiarę za przewinienie. Do nich będzie należała wszelka rzecz ofiarowana Bogu w Izraelu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 30, 'I to, co najlepsze ze wszystkich pierwocin wszystkiego, i każda ofiara podniesiona ze wszystkich rzeczy, wszystkie wasze ofiary będą należeć do kapłana. To, co najlepsze z waszych ciast, również dacie kapłanowi, aby sprawił, że błogosławieństwo spocznie na twoim domu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 31, 'Kapłani nie będą jedli żadnej padliny ani tego, co rozszarpane, czy to z ptactwa, czy z bydlęcia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 1, 'Gdy będziecie dzielić tę ziemię w dziedzictwo przez losowanie, oddacie na ofiarę Panu dział święty z tej ziemi, długi na dwadzieścia pięć tysięcy prętów i szeroki na dziesięć tysięcy. Będzie to święty dział we wszystkich waszych granicach dokoła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 2, 'Z tego będzie kwadrat na świątynię pięćset prętów długości na pięćset szerokości dokoła; a wokół niego będzie wolna przestrzeń na pięćdziesiąt łokci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 3, 'Z tej pierwszej miary odmierzysz dwadzieścia pięć tysięcy długości i dziesięć tysięcy szerokości, a na tym będzie świątynia i Miejsce Najświętsze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 4, 'Ten święty dział ziemi będzie należeć do kapłanów pełniących służbę w świątyni, którzy przystępują, aby służyć Panu. Będzie to miejsce na ich domy i miejsce święte na świątynię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 5, 'A obszar długi na dwadzieścia pięć tysięcy i szeroki na dziesięć tysięcy też będzie dla Lewitów, którzy służą w domu, na posiadłość liczącą dwadzieścia komórek.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 6, 'A na własność dacie miastu obszar szeroki na pięć tysięcy i długi na dwadzieścia pięć tysięcy wzdłuż działu świętej ofiary. Będzie to dla całego domu Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 7, 'Dla księcia będzie obszar z obu stron działu świętej ofiary i własności miasta, przed działem świętej ofiary i przed własnością miasta, od strony zachodniej ku zachodowi i od strony wschodniej ku wschodowi, a długość będzie naprzeciwko każdego z tych działów od granicy zachodniej aż do granicy wschodniej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 8, 'Ten dział ziemi będzie jego posiadłością w Izraelu, a moi książęta nie będą już uciskać mojego ludu; ale wydzielą ziemię domowi Izraela według jego pokoleń.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 9, 'Tak mówi Pan Bóg: Dosyć tego, książęta Izraela! Zaniechajcie przemocy i grabieży, wykonujcie sąd i sprawiedliwość i wycofajcie wasze obciążenia od mego ludu, mówi Pan Bóg;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 10, 'Będziecie mieli sprawiedliwe wagi, sprawiedliwą efę i sprawiedliwy bat.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 11, 'Efa i bat będą miały jednakową miarę, tak by bat zawierał dziesiątą część chomera, a także efa dziesiątą część chomera. Chomer będzie podstawą miary.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 12, 'Sykl będzie miał dwadzieścia ger. Dwadzieścia syklów, dwadzieścia pięć syklów i piętnaście syklów stanowi dla was minę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 13, 'A taka będzie ofiara wzniesienia, którą będziecie ofiarowywać: szóstą część efy z chomera pszenicy; dacie również szóstą część efy z chomera jęczmienia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 14, 'Ustawa dotycząca oliwy jest taka: bat jest miarą oliwy. Będziecie dawać dziesiątą część bat z kor, czyli chomer z dziesięciu bat, bo dziesięć bat stanowi chomer.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 15, 'Także jedną owcę z trzody liczącej dwieście owiec z bujnych pastwisk Izraela na ofiarę z pokarmów, na całopalenie i na ofiary pojednawcze, aby dokonać przebłagania za nich, mówi Pan Bóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 16, 'Cały lud tej ziemi ma składać te ofiary wzniesienia księciu w Izraelu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 17, 'Na księciu będzie ciążył obowiązek całopaleń i ofiar z pokarmów i z płynów na święta, na dni nowiu, na szabaty i na wszystkie uroczyste święta domu Izraela. On będzie sprawować ofiarę za grzech, ofiarę z pokarmów i całopalną oraz ofiary pojednawcze, aby dokonać przebłagania za dom Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 18, 'Tak mówi Pan Bóg: Pierwszego dnia pierwszego miesiąca weźmiesz młodego cielca bez skazy i oczyścisz świątynię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 19, 'Kapłan weźmie nieco krwi z ofiary za grzech i pomaże odrzwia domu, cztery narożniki podstawy tego ołtarza i odrzwia bramy dziedzińca wewnętrznego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 20, 'Tak samo uczynisz siódmego dnia tego miesiąca za każdego, który zgrzeszył nieświadomie, i za prostego. Tak oczyścicie dom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 21, 'W pierwszym miesiącu, czternastego dnia tego miesiąca, będziecie mieli święto Paschy, święto siedmiu dni, w których będą spożywane chleby przaśne.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 22, 'I w tym dniu książę złoży cielca na ofiarę za grzech za siebie i za cały lud tej ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 23, 'Przez siedem dni tego święta będzie ofiarowywać Panu na całopalenie siedem cielców i siedem baranów bez skazy, codziennie, przez siedem dni, a na ofiarę za grzech codziennie jednego kozła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 24, 'A na ofiarę z pokarmów złoży efę na cielca, efę na barana i hin oliwy na efę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 25, 'W siódmym miesiącu, piętnastego dnia tego miesiąca, w święto, będzie ofiarowywać właśnie to samo przez siedem dni, jak również ofiarę za grzech, całopalenie, ofiarę z pokarmów i oliwę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 1, 'Tak mówi Pan Bóg: Brama dziedzińca wewnętrznego, która jest zwrócona ku wschodowi, będzie zamknięta przez sześć dni roboczych. Ale w dniu szabatu będzie otwarta, także i w dniu nowiu będzie otwarta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 2, 'I książę wejdzie przez przedsionek bramy zewnętrznej, i stanie przy odrzwiach tej bramy. Następnie kapłani złożą jego całopalenie i ofiary pojednawcze, a on odda pokłon na progu bramy. Potem wyjdzie, lecz brama nie będzie zamknięta aż do wieczora.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 3, 'Podobnie lud tej ziemi będzie oddawał pokłon przed Panem u wejścia tej bramy w dni szabatu i w czasie nowiu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 4, 'A całopalenie, które książę będzie ofiarowywał Panu w dniu szabatu, będzie się składało z sześciu baranków bez skazy i jednego barana bez skazy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 5, 'Ofiara z pokarmów z efy na barana, a na baranki ofiara z pokarmów będzie według woli jego ręki oraz hin oliwy na efę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 6, 'A na dzień nowiu ma to być młody cielec bez skazy oraz sześć baranków i baran bez skazy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 7, 'Na ofiarę z pokarmów ma ofiarować efę na cielca, efę na barana i na baranka według woli swojej ręki oraz hin oliwy na efę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 8, 'A gdy książę będzie wchodził, wejdzie przez przedsionek tej bramy i wyjdzie tą samą drogą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 9, 'Ale gdy lud tej ziemi wejdzie przed oblicze Pana na święta uroczyste, to ten, który wejdzie przez bramę północną, aby oddać pokłon, wyjdzie przez bramę południową; a kto wejdzie przez bramę południową, wyjdzie przez bramę północną. Nie wróci przez bramę, którą wszedł, ale wyjdzie przeciwległą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 10, 'A gdy oni będą wchodzić, książę wśród nich wejdzie; a gdy będą wychodzić, wyjdzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 11, 'Także na święta i na uroczyste święta ofiarą z pokarmów będzie efa na cielca, efa na barana, a na baranki według woli jego ręki oraz hin oliwy na efę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 12, 'A gdy książę będzie składał Panu dobrowolną ofiarę całopalną lub dobrowolną ofiarę pojednawczą, to niech mu otworzą wschodnią bramę, a złoży swoje całopalenie i ofiary pojednawcze, jak to czyni w dniu szabatu. Potem wyjdzie, a po jego wyjściu niech zamkną bramę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 13, 'Ponadto codziennie złożysz Panu baranka rocznego bez skazy na całopalenie. Każdego rana złożysz go.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 14, 'Także ofiarę z pokarmów będziesz ofiarowywał przy nim każdego ranka: szóstą część efy, trzecią część hinu oliwy, aby pokropić najlepszą mąkę, jako nieustanną ofiarę z pokarmów dla Pana wiecznym postanowieniem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 15, 'Tak więc mają składać baranka, ofiarę z pokarmów i oliwę każdego rana jako całopalenie nieustanne.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 16, 'Tak mówi Pan Bóg: Jeśli książę da jakiś dar któremuś ze swych synów, będzie to dziedzictwem jego synów. Będzie to ich własność dziedziczna.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 17, 'Ale jeśli przekaże dar ze swego dziedzictwa któremuś ze swoich sług, wtedy będzie to jego aż do roku wyzwolenia, a potem wróci do tego księcia. Ale do synów będzie należeć jego dziedzictwo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 18, 'Książę nie będzie brał z dziedzictwa ludu, pozbawiając go siłą jego posiadłości. Lecz ze swojej posiadłości da dziedzictwo swoim synom, aby nikt z mojego ludu nie był wyrzucony ze swojej posiadłości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 19, 'Następnie wprowadził mnie przez wejście, które było z boku bramy, do komórek świętych dla kapłanów, które były zwrócone na północ, a oto było tam miejsce po obu stronach na zachód.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 20, 'I powiedział do mnie: To jest miejsce, gdzie kapłani będą gotować ofiarę za przewinienie i ofiarę za grzech, gdzie będą piec ofiarę z pokarmów, aby nie musieli wynosić ich na dziedziniec zewnętrzny na uświęcanie ludu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 21, 'Potem wyprowadził mnie na dziedziniec zewnętrzny i oprowadził mnie po czterech rogach dziedzińca, a oto był dziedziniec w każdym rogu dziedzińca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 22, 'W czterech kątach dziedzińca były dziedzińce długie na czterdzieści łokci i szerokie na trzydzieści łokci. Te cztery narożne dziedzińce miały ten sam wymiar.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 23, 'A dokoła nich czterech były rzędy pomieszczeń, a pod tymi rzędami uczyniono wokoło paleniska.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 24, 'I powiedział mi: To są miejsca dla tych, którzy gotują, gdzie słudzy domu będą gotować ofiary ludu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 1, 'Potem zaprowadził mnie do wejścia domu, a oto wody wypływały spod progu domu w kierunku wschodnim, gdyż przednia strona domu była zwrócona ku wschodowi, a wody spływały spod prawej strony domu ku południowej stronie od ołtarza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 2, 'Stamtąd wyprowadził mnie przez bramę północną i poprowadził mnie drogą zewnętrzną do bramy zewnętrznej, drogą wschodnią; a oto wody wypływały z prawej strony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 3, 'A gdy ten mąż ze sznurem w ręku wyszedł w kierunku wschodnim, odmierzył tysiąc łokci i przeprowadził mnie przez wodę, a woda sięgała aż do kostek.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 4, 'Potem odmierzył drugi tysiąc i przeprowadził mnie przez wodę, a woda sięgała aż do kolan; i znów odmierzył tysiąc i przeprowadził mnie przez wodę, a ta sięgała aż do bioder.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 5, 'A gdy znowu odmierzył tysiąc, była rzeka, której nie mogłem przebrnąć, gdyż woda wezbrała. Była to woda, którą trzeba było przepłynąć, i rzeka, której nie mogłem przejść.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 6, 'Wtedy powiedział do mnie: Czy widziałeś to, synu człowieczy? Potem poprowadził mnie i zaprowadził na brzeg tej rzeki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 7, 'A gdy się odwróciłem, oto na brzegu tej rzeki było bardzo wiele drzew po obu stronach;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 8, 'I powiedział do mnie: Te wody wypływają ku krainie wschodniej, schodzą do równin i wpadają do morza. A gdy wpadają do morza, wody zostają uzdrowione.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 9, 'I stanie się, że każda istota żyjąca, która się porusza, gdziekolwiek popłyną potoki, będzie żyć. I będzie bardzo dużo ryb, bo dotrą tam wody i zostaną uzdrowione. Wszystko będzie żyć, dokądkolwiek dotrze potok.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 10, 'Stanie się i to, że rybacy staną nad nim od En-Gedi aż do zdroju Eglaim; tam będą rozciągać sieci; będzie bardzo dużo ryb rozmaitego rodzaju, będą jak ryby wielkiego morza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 11, 'Lecz jego błota i bajora nie będą uzdrowione, ale będą przeznaczone na sól.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 12, 'A nad rzeką wyrosną na jego brzegu po obu stronach wszelkie drzewa wydające owoce, drzewa, których liść nie więdnie ani owoc nie ustaje. W swoich miesiącach wydadzą pierwociny, bo wody dla nich wypływają ze świątyni. Dlatego ich owoc będzie na pokarm, a ich liście na lekarstwo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 13, 'Tak mówi Pan Bóg: To jest granica, według której podzielicie ziemię w dziedzictwo według dwunastu pokoleń Izraela: Józef będzie miał dwie części.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 14, 'Posiądziecie ją dziedzicznie, po równo jedno pokolenie, jak i drugie – ziemię, którą przysiągłem dać waszym ojcom. I ta ziemia przypadnie wam w dziedzictwo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 15, 'To jest więc granica tej ziemi od strony północnej: od Wielkiego Morza, w kierunku Chetlon, idąc do Sedada.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 16, 'Chamat, Berota, Sibraim, które są pomiędzy granicą Damaszku a granicą Chamat, Chasar-Hattikon, które jest przy granicy Chauranu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 17, 'Granicą od morza będzie Chasar-Enan, granica Damaszku i północna strona na północy, i granica Chamat. To jest strona północna.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 18, 'A strona wschodnia: między Chauran i między Damaszkiem, między Gileadem i między ziemią Izraela przy Jordanie. Będziecie mierzyć od tej granicy przy Morzu Wschodnim. To jest strona wschodnia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 19, 'A strona południowa na południu: od Tamar aż do wód sporu w Kadesz, od rzeki aż do Wielkiego Morza. To jest strona południowa na południu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 20, 'Strona zaś zachodnia: Wielkie Morze od granicy aż do miejsca, skąd idzie się do Chamat. To jest strona zachodnia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 21, 'A tak podzielicie sobie tę ziemię według pokoleń Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 22, 'A gdy ją podzielicie, przypadnie ona w dziedzictwo wam i cudzoziemcom, którzy przebywają wśród was, którzy zrodzą synów wśród was. Będą dla was jak zrodzeni w ziemi pośród synów Izraela. Z wami będą mieli dziedzictwo pośród pokoleń Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 23, 'A w którymkolwiek pokoleniu cudzoziemiec będzie przebywał, tam mu dacie jego dziedzictwo – mówi Pan Bóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 1, 'A oto imiona pokoleń: Na północnym krańcu wzdłuż drogi Chetlon, w kierunku Chamat, Chasar-Enan, do granicy Damaszku na północy i aż do Chamat, od strony wschodniej aż na zachód, jeden dział dla Dana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 2, 'A obok granicy Dana, od strony wschodniej aż do strony zachodniej, jeden dział dla Aszera.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 3, 'A obok granicy Aszera, od strony wschodniej aż do strony zachodniej, jeden dział dla Neftalego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 4, 'A obok granicy Neftalego, od strony wschodniej aż do strony zachodniej, jeden dział dla Manassesa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 5, 'A obok granicy Manassesa, od strony wschodniej aż do strony zachodniej, jeden dział dla Efraima.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 6, 'A obok granicy Efraima, od strony wschodniej aż do strony zachodniej, jeden dział dla Rubena.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 7, 'A obok granicy Rubena, od strony wschodniej aż do strony zachodniej, jeden dział dla Judy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 8, 'A obok granicy Judy, od strony wschodniej aż do strony zachodniej, będzie święty dział, szeroki na dwadzieścia pięć tysięcy prętów i długi jak każdy z pozostałych działów od strony wschodniej do strony zachodniej, a w jego środku będzie świątynia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 9, 'Ten dział, który macie ofiarować Panu, będzie długi na dwadzieścia pięć tysięcy prętów i szeroki na dziesięć tysięcy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 10, 'Do nich, to jest kapłanów, będzie należał ten święty dział: na północy dwadzieścia pięć tysięcy prętów, na zachodzie dziesięć tysięcy szerokości, na wschodzie dziesięć tysięcy szerokości i na południe dwadzieścia pięć tysięcy długości. W jego środku będzie świątynia Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 11, 'To ma być dla uświęconych kapłanów spośród synów Sadoka, którzy pełnili moją służbę i nie błądzili, gdy błądzili synowie Izraela, jak błądzili inni Lewici.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 12, 'I ten święty dział z ofiar tej ziemi będzie rzeczą najświętszą obok granicy Lewitów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 13, 'Obok granicy kapłanów będzie dział Lewitów o długości dwudziestu pięciu tysięcy prętów i o szerokości dziesięciu tysięcy. Cała długość będzie wynosiła dwadzieścia pięć tysięcy, a szerokość dziesięć tysięcy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 14, 'I nie będą mogli go sprzedać ani zamienić, ani pierwocin ziemi przekazać innym, gdyż jest poświęcony Panu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 15, 'A pięć tysięcy prętów, które pozostaną z szerokości wzdłuż dwudziestu pięciu tysięcy, stanowi miejsce pospolite na miasto, na zamieszkanie i na pastwiska. A miasto będzie w jego środku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 16, 'Oto jego wymiary: strona północna – cztery tysiące pięćset prętów, strona południowa – cztery tysiące pięćset, strona wschodnia – cztery tysiące pięćset i strona zachodnia – cztery tysiące pięćset.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 17, 'Pastwiska miasta na północ – dwieście pięćdziesiąt prętów, na południe – dwieście pięćdziesiąt, na wschód – dwieście pięćdziesiąt i na zachód – dwieście pięćdziesiąt.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 18, 'To, co pozostanie wzdłuż świętego działu, będzie mieć dziesięć tysięcy prętów na wschód i dziesięć tysięcy na zachód. Będzie to wzdłuż świętego działu, a plony tego miejsca będą na utrzymanie sług miasta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 19, 'A ci, co służą miastu, będą sługami spośród wszystkich pokoleń Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 20, 'Cały ten święty dział będzie wynosił dwadzieścia pięć tysięcy prętów na dwadzieścia pięć tysięcy. Ofiarujecie kwadrat świętego działu wraz z posiadłością miasta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 21, 'To, co pozostanie, będzie dla księcia z obu stron świętego działu i posiadłości miasta, wzdłuż dwudziestu pięciu tysięcy prętów ofiary aż do granicy wschodniej i na zachód wzdłuż dwudziestu pięciu tysięcy prętów do granicy zachodniej, wzdłuż innych działów, będzie to dla księcia. A będzie to święty dział, a świątynia domu będzie w jego środku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 22, 'A od posiadłości Lewitów i od posiadłości miasta, które będą w środku tego, co należy do księcia, pomiędzy granicą Judy i granicą Beniamina, będzie to należało do księcia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 23, 'Pozostałe pokolenia, od strony wschodniej aż do strony zachodniej: jeden dział dla Beniamina.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 24, 'Obok granicy Beniamina, od strony wschodniej aż do strony zachodniej, jeden dział dla Symeona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 25, 'Obok granicy Symeona, od strony wschodniej aż do strony zachodniej, jeden dział dla Issachara.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 26, 'Obok granicy Issachara, od strony wschodniej aż do strony zachodniej, jeden dział dla Zebulona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 27, 'Obok granicy Zebulona, od strony wschodniej aż do strony zachodniej, jeden dział dla Gada.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 28, 'Obok granicy Gada, po stronie południowej na południe, granica będzie od Tamar aż do wód sporu w Kadesz, w stronę rzeki do Wielkiego Morza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 29, 'To jest ziemia, którą podzielicie przez losowanie między pokolenia Izraela, i to są działy, mówi Pan Bóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 30, 'To też są wyjścia z miasta: od strony północnej – cztery tysiące pięćset prętów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 31, 'A bramy miasta będą nazwane według imion pokoleń Izraela. Trzy bramy na północy: brama Rubena jedna, brama Judy jedna i brama Lewiego jedna.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 32, 'Od strony wschodniej – cztery tysiące pięćset, a bramy trzy: brama Józefa jedna, brama Beniamina jedna i brama Dana jedna.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 33, 'Od strony południowej – cztery tysiące pięćset prętów, a bramy trzy: brama Symeona jedna, brama Issachara jedna i brama Zebulona jedna.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 34, 'Od strony zachodniej – cztery tysiące pięćset, a bramy trzy: Brama Gada jedna, brama Aszera jedna i brama Neftalego jedna.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 35, 'Wokoło osiemnaście tysięcy prętów. A imię miasta od tego dnia będzie: Pan tam mieszka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 1, 'W trzecim roku panowania Joakima, króla Judy, do Jerozolimy nadciągnął Nabuchodonozor, król Babilonu, i obległ ją.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 2, 'I Pan wydał w jego rękę Joakima, króla Judy, oraz część naczyń domu Bożego, a on je zabrał do ziemi Szinear, do domu swego boga, i wniósł te naczynia do skarbca swego boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 3, 'I król rozkazał Aszpenazowi, przełożonemu swoich eunuchów, aby przyprowadził niektórych spośród synów Izraela, z potomstwa króla i z książąt;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 4, 'Młodzieńców, w których by nie było żadnej skazy, o pięknym wyglądzie, biegłych we wszelkiej mądrości, posiadających wiedzę i pojętnych w nauce, którzy byliby zdatni stanąć w pałacu króla, i aby ich nauczać pisma i języka chaldejskiego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 5, 'I król wyznaczył im codzienną porcję potraw królewskich i wina, które on sam pił. Mieli być tak wychowywani, by po upływie trzech lat mogli stanąć przed królem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 6, 'Wśród nich, spośród synów Judy, byli: Daniel, Chananiasz, Miszael i Azariasz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 7, 'I przełożony eunuchów nadał im imiona: Daniela nazwał Belteszassarem, Chananiasza – Szadrakiem, Miszaela – Meszakiem i Azariasza – Abed-Nego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 8, 'Ale Daniel postanowił w swoim sercu, że nie splami się potrawami króla ani winem, które król pił. Poprosił więc przełożonego eunuchów, aby nie musiał się splamić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 9, 'I Bóg zjednał Danielowi łaskę i miłość przełożonego eunuchów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 10, 'Przełożony eunuchów powiedział do Daniela: Boję się króla, mojego pana, który wyznaczył wasz pokarm i wasz napój. Jeśli zobaczy, że wasze twarze są chudsze niż innych młodzieńców, którzy razem z wami mają być wychowani, wtedy narazicie u króla na niebezpieczeństwo moją głowę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 11, 'Wtedy Daniel powiedział do sługi, którego przełożony eunuchów ustanowił nad Danielem, Chananiaszem, Miszaelem i Azariaszem;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 12, 'Poddaj próbie, proszę, twoje sługi przez dziesięć dni. Niech nam dają jarzyny do jedzenia i wodę do picia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 13, 'Potem przypatrzysz się naszym twarzom oraz twarzom młodzieńców, którzy jadają pokarm z potraw królewskich, i według tego, co zobaczysz, tak postąpisz ze swoimi sługami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 14, 'I posłuchał ich w tej sprawie, i poddał ich próbie przez dziesięć dni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 15, 'A po upływie dziesięciu dni okazało się, że ich twarze wyglądały lepiej i ich ciała były tęższe niż wszystkich młodzieńców, którzy jadali pokarm z potraw królewskich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 16, 'Sługa zabrał więc ich potrawy oraz wino, które mieli pić, a dał im jarzyny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 17, 'Tym czterem młodzieńcom dał Bóg wiedzę i zrozumienie we wszelkim piśmie oraz mądrość. Ponadto Danielowi dał zrozumienie wszelkich widzeń i snów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 18, 'Gdy minęły dni wyznaczone przez króla, by ich przyprowadzić, przełożony dworzan wprowadził ich przed Nabuchodonozora.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 19, 'I król rozmawiał z nimi, ale nie znalazł się pośród nich wszystkich nikt taki, jak Daniel, Chananiasz, Miszael i Azariasz. I stanęli przed królem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 20, 'We wszystkich sprawach mądrości i rozumu, o które pytał ich król, stwierdzał, że są dziesięciokrotnie bieglejsi od wszystkich magów i astrologów, którzy byli w całym jego królestwie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 21, 'I Daniel był tam aż do pierwszego roku króla Cyrusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 1, 'W drugim roku panowania Nabuchodonozora miał Nabuchodonozor sen i strwożył się jego duch, i nie mógł spać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 2, 'Wtedy król rozkazał zwołać magów, astrologów, czarowników i Chaldejczyków, aby opowiedzieli królowi jego sen. Przyszli więc i stanęli przed królem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 3, 'Król powiedział do nich: Miałem sen i strwożył się mój duch, i chcę wiedzieć, co ten sen oznacza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 4, 'Wtedy Chaldejczycy odpowiedzieli królowi po syryjsku: Królu, żyj na wieki! Opowiedz sen swoim sługom, a objaśnimy jego znaczenie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 5, 'Król odpowiedział Chaldejczykom: Ta sprawa już uleciała mi z pamięci. Jeśli nie oznajmicie mi snu i jego znaczenia, będziecie rozsiekani na kawałki, a wasze domy będą zamienione w gnojowisko.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 6, 'Ale jeśli oznajmicie mi sen i jego znaczenie, otrzymacie ode mnie dary i nagrody oraz wielką cześć. Dlatego oznajmijcie mi sen i jego znaczenie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 7, 'Odpowiedzieli powtórnie: Niech król opowie sen swoim sługom, a objaśnimy jego znaczenie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 8, 'Król odpowiedział: Wiem na pewno, że celowo to odkładacie, gdyż wiecie, że ten sen uleciał mi z pamięci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 9, 'Jeśli więc nie oznajmicie mi snu, jest dla was tylko jeden dekret. Postanowiliście bowiem mówić wobec mnie słowa kłamliwe i przewrotne, aż czas upłynie. Dlatego oznajmijcie mi sen, a przekonam się, że będziecie mogli objaśnić mi jego znaczenie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 10, 'Chaldejczycy odpowiedzieli królowi: Nie ma człowieka na ziemi, który by mógł oznajmić tę rzecz królowi. Dlatego żaden król, książę albo władca nie wymaga takiej rzeczy od żadnego maga, astrologa lub Chaldejczyka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 11, 'Rzecz, której król wymaga, jest trudna, a nie ma nikogo, kto by mógł ją oznajmić królowi, oprócz bogów, którzy nie mieszkają wśród ludzi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 12, 'Z tej przyczyny król się rozzłościł i bardzo się rozgniewał, i rozkazał wytracić wszystkich mędrców Babilonu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 13, 'A gdy wyszedł dekret, aby zgładzić mędrców, szukano także Daniela i jego towarzyszy, aby ich wymordować.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 14, 'Wtedy Daniel odpowiedział mądrze i roztropnie Ariochowi, dowódcy gwardii królewskiej, który wyszedł zabić mędrców Babilonu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 15, 'Powiedział do Ariocha, dowódcy króla: Czemu ten dekret tak szybko wyszedł od króla? Wtedy Arioch oznajmił Danielowi sprawę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 16, 'Wszedł więc Daniel do króla i poprosił go, aby dał mu czas na oznajmienie królowi znaczenia snu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 17, 'Potem Daniel poszedł do swego domu i opowiedział sprawę swoim towarzyszom: Chananiaszowi, Miszaelowi i Azariaszowi;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 18, 'Aby prosili Boga nieba o miłosierdzie względem tej tajemnicy, żeby nie zginęli Daniel i jego towarzysze z resztą mędrców Babilonu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 19, 'Wtedy Danielowi została objawiona ta tajemnica w nocnym widzeniu, za co Daniel błogosławił Bogu nieba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 20, 'Daniel powiedział: Niech będzie błogosławione imię Boga na wieki wieków, bo mądrość i moc do niego należą;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 21, 'On zmienia czasy i okresy, usuwa królów i ustanawia królów. Daje mądrość mądrym, a wiedzę rozumnym;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 22, 'On objawia rzeczy głębokie i ukryte, wie, co jest w ciemności, a światłość z nim mieszka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 23, 'Ciebie, Boże moich ojców, wysławiam i chwalę za to, że dałeś mi mądrość i moc, że oznajmiłeś mi teraz to, o co cię prosiliśmy. Oznajmiłeś nam bowiem sen króla.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 24, 'Dlatego Daniel wszedł do Ariocha, którego król ustanowił, aby wytracił mędrców Babilonu. Gdy przyszedł, tak powiedział do niego: Nie trać mędrców Babilonu. Wprowadź mnie do króla, a ja oznajmię królowi znaczenie snu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 25, 'Wtedy Arioch z pośpiechem wprowadził Daniela do króla i tak mu powiedział: Znalazłem męża spośród uprowadzonych z Judy, który oznajmi królowi znaczenie snu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 26, 'Król odpowiedział Danielowi, któremu na imię było Belteszassar: Czy potrafisz oznajmić mi sen, który miałem, oraz jego znaczenie?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 27, 'Daniel odpowiedział królowi: Tajemnicy, o którą król pyta, nie mogą oznajmić królowi mędrcy, astrologowie, magowie i wróżbici;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 28, 'Jest jednak Bóg w niebie, który objawia tajemnice, i on oznajmił królowi Nabuchodonozorowi, co nastąpi w ostatecznych dniach. Twój sen i widzenia w twojej głowie, które miałeś na swoim łożu, są takie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 29, 'Tobie, królu, przychodziły na twoim łożu myśli o tym, co ma nastąpić później. Ten zaś, który objawia tajemnice, oznajmił ci to, co nastąpi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 30, 'I mnie została objawiona tajemnica, nie za jakąś mądrość, jakbym miał jej więcej niż wszyscy żyjący, ale przez modlitwę, aby znaczenie snu było oznajmione królowi i abyś poznał myśli swego serca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 31, 'Ty, królu, miałeś takie widzenie: Oto posąg wielki; ten wielki posąg o nadzwyczajnym blasku stał przed tobą, a jego wygląd był straszny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 32, 'Głowa tego posągu wykonana była z czystego złota, jego piersi i ramiona – ze srebra, jego brzuch i biodra – z brązu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 33, 'Jego golenie – z żelaza, jego stopy – częściowo z żelaza, częściowo z gliny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 34, 'Patrzyłeś na to, aż został odcięty kamień bez pomocy rąk, i uderzył posąg w jego stopy z żelaza i gliny, i skruszył je.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 35, 'Wtedy zostały skruszone razem: żelazo, glina, brąz, srebro i złoto i stały się jak plewy na klepisku w lecie; i wiatr niósł je tak, że nie znaleziono ich w żadnym miejscu. Kamień zaś, który uderzył w posąg, stał się wielką górą i napełnił całą ziemię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 36, 'Taki jest sen. Jego znaczenie też wypowiemy przed królem;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 37, 'Ty, królu, jesteś królem królów, bo tobie Bóg nieba dał królestwo, moc, potęgę i sławę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 38, 'I dał w twoją rękę wszystko to, gdzie mieszkają synowie ludzi, zwierzęta polne i ptactwo niebieskie, i ustanowił cię panem nad tym wszystkim. Ty jesteś tą głową ze złota.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 39, 'Ale po tobie powstanie inne królestwo, mniejsze od twojego, a potem trzecie królestwo z brązu, które będzie panować nad całą ziemią.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 40, 'Czwarte królestwo będzie mocne jak żelazo, bo jak żelazo kruszy i miażdży wszystko, jak żelazo łamie wszystko, tak i ono połamie i pokruszy wszystko.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 41, 'A że widziałeś stopy i palce częściowo z gliny garncarskiej, a częściowo z żelaza – oznacza to, że królestwo będzie podzielone. Będzie w nim nieco siły żelaza, tak jak widziałeś żelazo zmieszane z mulistą gliną;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 42, 'A palce stóp częściowo z żelaza a częściowo z gliny znaczą, że królestwo będzie częściowo silne, a częściowo kruche.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 43, 'A że widziałeś żelazo zmieszane z mulistą gliną, oznacza to, że się zmieszają ze sobą ludzie, ale nie będzie się trzymał jeden drugiego, tak jak żelaza nie można zmieszać z gliną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 44, 'Ale w dniach tych królów Bóg nieba wzbudzi królestwo, które nigdy nie będzie zniszczone. To królestwo nie przejdzie na inny lud, ale połamie i zniszczy wszystkie te królestwa, samo zaś będzie trwać na wieki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 45, 'To, że widziałeś, jak kamień został odcięty z góry bez pomocy rąk i skruszył żelazo, brąz, glinę, srebro i złoto, oznacza, że wielki Bóg oznajmił królowi, co nastąpi potem. Sen jest prawdziwy i jego znaczenie pewne.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 46, 'Wtedy król Nabuchodonozor padł na twarz, oddał pokłon Danielowi i rozkazał, aby złożono mu ofiarę i kadzidło.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 47, 'Następnie król zwrócił się do Daniela i powiedział: Zaprawdę wasz Bóg jest Bogiem bogów i Panem królów, który objawia tajemnice, ponieważ zdołałeś objawić tę tajemnicę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 48, 'Potem król wywyższył Daniela i dał mu wiele wielkich darów, i uczynił go panem nad całą prowincją Babilonu i głównym przełożonym nad wszystkimi mędrcami Babilonu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 49, 'Ale Daniel wyprosił króla, aby ustanowił nad sprawami prowincji Babilonu Szadraka, Meszaka i Abed-Nego; Daniel zaś pozostał w bramie króla.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 1, 'Król Nabuchodonozor wykonał złoty posąg o wysokości sześćdziesięciu łokci i szerokości sześciu łokci i postawił go na równinie Dura w prowincji Babilonu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 2, 'Wtedy król Nabuchodonozor rozesłał posłów, aby zebrali książąt, starostów, dowódców, sędziów, skarbników, prawników, urzędników i wszystkich przełożonych prowincji, by przyszli na poświęcenie posągu, który wystawił król Nabuchodonozor.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 3, 'Wtedy zgromadzili się książęta, starostowie, dowódcy, sędziowie, skarbnicy, prawnicy, urzędnicy i wszyscy przełożeni prowincji na poświęcenie posągu, który wzniósł król Nabuchodonozor; i stanęli przed posągiem, który wystawił Nabuchodonozor.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 4, 'A herold zawołał donośnym głosem: Rozkazuje się wam, ludy, narody i języki;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 5, 'W chwili gdy usłyszycie dźwięk trąby, fletu, harfy, sambuki, psałterionu, cymbałów i wszelkiego instrumentu muzycznego, macie paść i oddać pokłon złotemu posągowi, który wystawił król Nabuchodonozor.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 6, 'A kto nie upadnie i nie odda pokłonu, zostanie w tej samej godzinie wrzucony do pieca rozpalonego ogniem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 7, 'W chwili więc, gdy wszyscy ludzie usłyszeli dźwięk trąby, fletu, harfy, sambuki, psałterionu i wszelkich instrumentów muzycznych, upadli wszyscy ludzie, wszystkie narody i języki i oddali pokłon złotemu posągowi, który wystawił król Nabuchodonozor.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 8, 'Dlatego w tym czasie przyszli niektórzy Chaldejczycy i złożyli skargę przeciwko Żydom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 9, 'Mówili do króla Nabuchodonozora: Królu, żyj na wieki!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 10, 'Ty, królu, wydałeś dekret, aby każdy człowiek, który usłyszy dźwięk trąby, fletu, harfy, sambuki, psałterionu, cymbałów i wszelkich instrumentów muzycznych, upadł i oddał pokłon złotemu posągowi;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 11, 'A kto by nie upadł i nie oddał pokłonu, aby został wrzucony do pieca rozpalonego ogniem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 12, 'Znaleźli się jednak niektórzy Żydzi, których ustanowiłeś nad sprawami prowincji Babilonu: Szadrak, Meszak i Abed-Nego. Ci mężczyźni zlekceważyli twój dekret, królu. Nie chwalą twoich bogów i nie oddają pokłonu złotemu posągowi, który wystawiłeś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 13, 'Wtedy Nabuchodonozor we wściekłości i gniewie rozkazał przyprowadzić Szadraka, Meszaka i Abed-Nego; przyprowadzono więc ich przed króla.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 14, 'I zwrócił się do nich Nabuchodonozor, i zapytał ich: Czy to prawda, Szadraku, Meszaku i Abed-Nego, że nie czcicie moich bogów i nie oddajecie pokłonu złotemu posągowi, który wystawiłem?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 15, 'Teraz więc bądźcie gotowi, aby w chwili, gdy usłyszycie dźwięk trąby, fletu, harfy, sambuki, psałterionu, cymbałów i wszelkich instrumentów muzycznych, upaść i oddać pokłon posągowi, który wykonałem. Jeśli nie oddacie pokłonu, zostaniecie w tej samej godzinie wrzuceni do środka pieca rozpalonego ogniem, a kim jest ten Bóg, który by mógł was wyrwać z mojej ręki?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 16, 'Szadrak, Meszak i Abed-Nego odpowiedzieli królowi: Nabuchodonozorze, my się nie martwimy tym, co odpowiedzieć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 17, 'Nasz Bóg, którego chwalimy, może nas wyrwać z pieca rozpalonego ogniem i z twojej ręki. Czy wyrwie nas, królu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 18, 'Czy nie wyrwie, niech ci będzie wiadomo, królu, że nie będziemy chwalić twoich bogów ani nie oddamy pokłonu złotemu posągowi, który wystawiłeś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 19, 'Wtedy Nabuchodonozor napełnił się wściekłością, tak że wyraz jego twarzy zmienił się wobec Szadraka, Meszaka i Abed-Nego. Wydał rozkaz, by rozpalono piec siedem razy mocniej, niż zwykle rozpalano.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 20, 'Najsilniejszym ludziom ze swego wojska rozkazał związać Szadraka, Meszaka i Abed-Nego i wrzucić do pieca rozpalonego ogniem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 21, 'Wtedy związano tych mężczyzn w ich płaszczach i ubraniach, w ich czapkach i szatach i wrzucono ich do środka pieca rozpalonego ogniem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 22, 'Ponieważ rozkaz króla przynaglał, a piec był bardzo rozpalony, płomień ognia zabił tych ludzi, którzy wrzucili Szadraka, Meszaka i Abed-Nego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 23, 'A ci trzej mężowie, Szadrak, Meszak i Abed-Nego, wpadli związani do środka pieca rozpalonego ogniem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 24, 'Wtedy król Nabuchodonozor zdumiał się, powstał spiesznie i zapytał swoich doradców: Czy nie wrzuciliśmy trzech związanych mężów do środka ognia? A oni odpowiedzieli królowi: Prawda, królu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 25, 'A on odpowiedział: Oto widzę czterech mężów rozwiązanych, przechadzających się pośród ognia, i nie odnoszą żadnej szkody, a wygląd czwartej osoby jest podobny do Syna Bożego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 26, 'Wtedy zbliżył się Nabuchodonozor do otworu pieca rozpalonego ogniem i powiedział: Szadraku, Meszaku i Abed-Nego, słudzy Najwyższego Boga, wyjdźcie i przyjdźcie tutaj. Wyszli więc Szadrak, Meszak i Abed-Nego ze środka ognia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 27, 'A zgromadziwszy się, książęta, starostowie, urzędnicy i dowódcy króla widzieli tych mężczyzn, to, że ogień nie miał żadnej mocy nad ich ciałami, włosy z ich głowy nie spaliły się, ich płaszcze nie były zniszczone ani swąd ognia ich nie przeniknął.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 28, 'Wtedy Nabuchodonozor powiedział: Błogosławiony niech będzie Bóg Szadraka, Meszaka i Abed-Nego, który posłał swego Anioła i wyrwał swoje sługi, którzy mu ufali, którzy nie posłuchali słowa króla, ale oddali swe ciała, aby nie służyć ani oddawać pokłonu żadnemu bogu oprócz swego Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 29, 'Dlatego wydaję taki dekret: Ktokolwiek ze wszelkiego ludu, narodu i języka wypowie bluźnierstwo przeciwko Bogu Szadraka, Meszaka i Abed-Nego, zostanie rozsiekany na kawałki, a jego dom zamieniony w gnojowisko, gdyż nie ma innego Boga, który mógłby wyrwać jak ten.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 30, 'Wtedy król wywyższył Szadraka, Meszaka i Abed-Nego w prowincji Babilonu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 1, 'Król Nabuchodonozor do wszystkich ludzi, narodów i języków, którzy mieszkają w całej ziemi: Niech pokój się wam rozmnoży!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 2, 'Uważałem za stosowne opowiedzieć o znakach i cudach, które uczynił dla mnie Bóg Najwyższy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 3, 'Jakże wielkie są jego znaki i jak potężne jego cuda! Jego królestwo jest królestwem wiecznym i jego władza trwa z pokolenia na pokolenie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 4, 'Ja, Nabuchodonozor, żyłem spokojnie w swoim domu i rozkwitałem w swoim pałacu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 5, 'Miałem sen, który mnie przestraszył, a myśli, które miałem na swoim łożu, oraz widzenia w mojej głowie zatrwożyły mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 6, 'Wydałem więc dekret, aby przyprowadzano przede mnie wszystkich mędrców Babilonu, żeby oznajmili mi znaczenie tego snu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 7, 'Wtedy przyszli magowie, astrologowie, Chaldejczycy i wróżbici; i opowiedziałem im sen, ale nie potrafili mi oznajmić jego znaczenia;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 8, 'Aż w końcu przyszedł przede mnie Daniel, którego imię brzmi Belteszassar, zgodnie z imieniem mojego boga, a w którym jest duch świętych bogów, i przed nim opowiedziałem sen;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 9, 'Belteszassarze, przełożony magów, wiem, że duch świętych bogów jest w tobie i że żadna tajemnica nie jest dla ciebie trudna. Posłuchaj widzenia z mojego snu, który miałem, i powiedz mi jego znaczenie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 10, 'Takie są widzenia w mojej głowie, jakie miałem na swoim łożu: Patrzyłem, a oto drzewo pośrodku ziemi, a jego wysokość była ogromna.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 11, 'Drzewo rosło i było potężne, a jego wysokość dosięgła nieba i było widoczne aż po krańce całej ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 12, 'Jego liście były piękne, jego owoc obfity i na nim był pokarm dla wszystkich. Pod nim znajdowały cień zwierzęta polne, na jego gałęziach mieszkało ptactwo niebieskie i z niego miało pożywienie wszelkie ciało.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 13, 'Widziałem jeszcze w widzeniach w mojej głowie na swoim łożu: Oto stróż i święty zstąpił z nieba;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 14, 'Zawołał ze wszystkich sił i tak powiedział: Wyrąbcie to drzewo i obetnijcie jego gałęzie, otrząśnijcie jego liście i rozrzućcie jego owoc. Niech zwierzę ucieknie spod niego i ptactwo z jego gałęzi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 15, 'Lecz pień jego korzenia zostawcie w ziemi i to w okowach żelaza i brązu na polnej trawie, aby był skrapiany rosą z nieba, a trawę ziemi niech dzieli ze zwierzętami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 16, 'Niech się odmieni jego ludzkie serce i niech będzie mu dane serce zwierzęce, a niech przejdzie nad nim siedem czasów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 17, 'Ta sprawa jest według dekretu stróżów i to żądanie jest według słowa świętych po to, aby wszyscy żyjący poznali, że Najwyższy panuje nad królestwem ludzkim i daje je, komu chce, a najniższych z ludzi ustanawia nad nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 18, 'Taki sen miałem ja, król Nabuchodonozor. A ty, Belteszassarze, powiedz jego znaczenie, gdyż wszyscy mędrcy mojego królestwa nie mogli mi oznajmić jego znaczenia. Ale ty możesz, bo duch świętych bogów jest w tobie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 19, 'Wtedy Daniel, który miał na imię Belteszassar, stał osłupiony przez jedną godzinę i jego myśli trwożyły go. Król odezwał się i powiedział: Belteszassarze, niech cię nie trwoży sen i jego znaczenie. Belteszassar odpowiedział: Mój panie, niech ten sen spadnie na tych, którzy cię nienawidzą, a jego znaczenie na twoich wrogów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 20, 'Drzewo, które widziałeś, które rosło i było potężne, jego wysokość dosięgła nieba, a było widoczne na całej ziemi;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 21, 'Którego liście były piękne, a owoc obfity, na którym był pokarm dla wszystkich, pod którym mieszkało zwierzę polne i na którego gałęziach przebywało ptactwo niebieskie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 22, 'To ty, królu, który rosłeś i stałeś się potężny, twoja wielkość urosła i dosięgła nieba, a twoja władza – aż po krańce ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 23, 'A to, że król widział stróża i świętego zstępującego z nieba i mówiącego: Wyrąbcie to drzewo i zniszczcie je, lecz pień jego korzeni zostawcie w ziemi i to w okowach żelaza i brązu na polnej trawie, aby był skrapiany rosą z nieba; a trawę polną niech dzieli ze zwierzętami polnymi, aż wypełni się siedem czasów nad nim;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 24, 'Takie jest znaczenie, o królu, i dekret Najwyższego, który przyszedł na króla, mego pana;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 25, 'Wypędzą cię spośród ludzi, będziesz mieszkał ze zwierzętami polnymi, będą cię żywić trawą jak woły, będziesz skrapiany rosą z nieba i wypełni się nad tobą siedem czasów, aż poznasz, że Najwyższy panuje nad królestwem ludzkim i daje je, komu chce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 26, 'A to, że rozkazano zostawić pień korzeni tego drzewa, oznacza, że twoje królestwo zostanie przy tobie, gdy poznasz, że niebiosa sprawują władzę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 27, 'Dlatego, królu, niech ci się spodoba moja rada i przerwij swoje grzechy sprawiedliwością, a swoje nieprawości miłosierdziem nad biednymi; może przedłuży się twój pokój.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 28, 'To wszystko przyszło na króla Nabuchodonozora.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 29, 'Po upływie dwunastu miesięcy, gdy przechadzał się w pałacu królewskim w Babilonie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 30, 'Król zaczął mówić: Czy to nie jest ten wielki Babilon, który ja, w sile swej potęgi, zbudowałem jako siedzibę królestwa i dla chwały swojego majestatu?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 31, 'A gdy słowo to jeszcze było w ustach króla, oto spadł głos z nieba: Do ciebie się mówi, królu Nabuchodonozorze. Twoje królestwo odeszło od ciebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 32, 'Wypędzą cię spośród ludzi, będziesz mieszkał ze zwierzętami polnymi, będą cię żywić trawą jak woły i wypełni się nad tobą siedem czasów, aż poznasz, że Najwyższy panuje nad królestwem ludzkim i daje je, komu chce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 33, 'Tej godziny wypełniło się to słowo nad Nabuchodonozorem: Wypędzono go spośród ludzi, jadł trawę jak woły i jego ciało było skrapiane rosą z nieba, aż jego włosy urosły jak pióra orłów, a jego paznokcie jak szpony ptaków.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 34, 'Pod koniec tych dni, ja, Nabuchodonozor, podniosłem swoje oczy do nieba i wrócił mi mój rozum. Wtedy błogosławiłem Najwyższego i chwaliłem go, i wysławiałem Żyjącego na wieki, bo jego władza to władza wieczna, a jego królestwo trwa z pokolenia na pokolenie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 35, 'Wszyscy mieszkańcy ziemi są uważani za nic. Według swojej woli postępuje z wojskiem niebieskim i z mieszkańcami ziemi, a nie ma nikogo, kto by wstrzymał jego rękę lub powiedział mu: Co czynisz?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 36, 'W tym czasie wrócił mi mój rozum i ku chwale mego królestwa wróciła do mnie moja dostojność i mój blask. Ponadto moi doradcy i książęta szukali mnie, zostałem umocniony w swoim królestwie i dano mi jeszcze większy majestat.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 37, 'A teraz ja, Nabuchodonozor, chwalę, wywyższam i wysławiam Króla niebios, którego wszystkie dzieła są prawdą, a jego ścieżki sprawiedliwością, a tych, którzy postępują w pysze, może on poniżyć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 1, 'Król Belszazar urządził wielką ucztę dla tysiąca swoich książąt i przed tym tysiącem pił wino.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 2, 'A gdy Belszazar pił wino, rozkazał przynieść złote i srebrne naczynia, które jego ojciec, Nabuchodonozor, zabrał ze świątyni w Jerozolimie, aby pili z niego król, jego książęta, jego żony i jego nałożnice.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 3, 'Wtedy przyniesiono złote naczynia, które zabrano ze świątyni domu Bożego, który był w Jerozolimie, i pili z nich król, jego książęta, jego żony i jego nałożnice.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 4, 'Pili wino i chwalili bogów ze złota i srebra, z brązu i żelaza, z drewna i kamienia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 5, 'W tej samej godzinie ukazały się palce ręki ludzkiej, które pisały naprzeciw świecznika na wapnie ściany pałacu króla, a król widział część ręki, która pisała.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 6, 'Wtedy oblicze króla zmieniło się, jego myśli zatrwożyły go, stawy jego bioder rozluźniły się i jego kolana uderzały jedno o drugie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 7, 'I zawołał król ze wszystkich sił, aby przyprowadzono astrologów, Chaldejczyków i wróżbitów. Król powiedział do mędrców Babilonu: Ktokolwiek to pismo odczyta i oznajmi mi jego znaczenie, będzie odziany w purpurę, dadzą mu złoty łańcuch na szyję i będzie panował w królestwie jako trzeci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 8, 'Weszli więc wszyscy mędrcy króla, ale nie mogli odczytać pisma ani oznajmić królowi jego znaczenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 9, 'Wtedy król Belszazar bardzo się zatrwożył i jego oblicze się zmieniło, a jego książęta struchleli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 10, 'Wówczas królowa weszła do domu uczty z powodu słów króla i jego książąt. Odezwała się królowa i powiedziała: Królu, żyj na wieki! Niech cię nie trwożą twoje myśli i niech się nie zmienia twoje oblicze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 11, 'Jest w twoim królestwie mężczyzna, w którym jest duch świętych bogów, w którym za dni twego ojca znalazły się światło, rozum i mądrość podobna do mądrości bogów i którego król Nabuchodonozor, twój ojciec, mówię ci, twój ojciec, król, ustanowił przełożonym magów, astrologów, Chaldejczyków i wróżbitów;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 12, 'Dlatego że znalazły się w nim nadzwyczajny duch, wiedza, rozum, wykładanie snów, objawianie zagadek i rozwiązywanie rzeczy trudnych, w Danielu, któremu król nadał imię Belteszassar. Niech więc teraz wezwą Daniela, a on oznajmi znaczenie pisma.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 13, 'Wtedy Daniel został przyprowadzony do króla. A król zapytał Daniela: Czy ty jesteś tym Danielem z synów uprowadzonych z Judy, którego król, mój ojciec, sprowadził z ziemi Judy?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 14, 'Słyszałem o tobie, że duch bogów jest w tobie, że światło, rozum i obfita mądrość znajdują się w tobie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 15, 'Właśnie przyprowadzono przede mnie mędrców i astrologów, aby mi to pismo odczytali i oznajmili jego znaczenie. Oni jednak nie potrafili tego zrobić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 16, 'A słyszałem o tobie, że możesz dawać wyjaśnienie i rozwiązywać trudności. Jeśli więc teraz możesz to pismo odczytać i oznajmić mi jego znaczenie, będziesz odziany w purpurę, będzie włożony złoty łańcuch na twoją szyję i będziesz panował w królestwie jako trzeci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 17, 'Wtedy Daniel odpowiedział przed królem: Twoje upominki niech pozostaną przy tobie, a twoje dary daj innemu; pismo jednak odczytam królowi i oznajmię mu znaczenie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 18, 'Ty, królu, posłuchaj. Bóg Najwyższy dał Nabuchodonozorowi, twemu ojcu, królestwo, majestat, sławę i cześć;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 19, 'A z powodu wielkości, którą mu dał, wszyscy ludzie, narody i języki drżały przed nim i bały się go. Kogo chciał, zabijał, a kogo chciał, zostawiał przy życiu, kogo chciał, wywyższał, a kogo chciał, poniżał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 20, 'Ale gdy jego serce stało się wyniosłe i jego duch utwierdził się w pysze, został strącony z tronu swego królestwa i odebrano mu sławę;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 21, 'Został wypędzony spośród synów ludzkich, jego serce stało się podobne do serca zwierzęcia i mieszkał z dzikimi osłami. Żywili go trawą jak woły i jego ciało było skrapiane rosą z nieba, aż poznał, że Bóg Najwyższy ma władzę nad królestwem ludzkim i ustanawia nad nim, kogo chce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 22, 'Ty, też, Belszazarze, jego synu, nie ukorzyłeś swego serca, chociaż o tym wszystkim wiedziałeś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 23, 'Lecz uniosłeś się przeciwko Panu nieba i naczynia jego domu przyniesiono przed ciebie, a ty, twoi książęta, twoje żony i twoje nałożnice piliście wino z nich. Ponadto chwaliłeś bogów ze srebra, złota, brązu, żelaza, drewna i kamienia, które nie widzą ani nie słyszą i nic nie wiedzą. Bogu zaś, w którego ręku jest twoje tchnienie i u którego są wszystkie twoje drogi, nie oddałeś czci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 24, 'Dlatego przez niego została posłana część ręki i pismo to zostało napisane.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 25, 'A to jest pismo, które zostało napisane: Mene, Mene, Tekel, Uparsin.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 26, 'Takie jest znaczenie tych słów: Mene: Bóg policzył twoje królestwo i doprowadził je do końca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 27, 'Tekel: Zważono cię na wadze i okazałeś się lekki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 28, 'Peres: Twoje królestwo zostało podzielone i oddane Medom i Persom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 29, 'Wtedy Belszazar wydał rozkaz i odziano Daniela w purpurę, złoty łańcuch włożono mu na szyję i ogłoszono o nim, że będzie panował jako trzeci w królestwie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 30, 'Tej samej nocy Belszazar, król Chaldejczyków, został zabity.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 31, 'A Dariusz, Med, przejął królestwo, mając około sześćdziesięciu dwóch lat.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 1, 'Dariuszowi spodobało się ustanowić nad królestwem stu dwudziestu satrapów, którzy byliby po całym królestwie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 2, 'A nad nimi trzech zwierzchników, z których Daniel był pierwszym. Im zdawali sprawozdanie satrapowie, aby król nie doznał żadnej szkody.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 3, 'A sam Daniel przewyższał tych książąt i satrapów, ponieważ był w nim nadzwyczajny duch, i król zamierzał ustanowić go nad całym królestwem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 4, 'Wtedy zwierzchnicy i satrapowie usiłowali znaleźć przeciwko Danielowi powód oskarżenia dotyczący królestwa; nie mogli jednak znaleźć żadnego pretekstu ani wady, ponieważ był on wierny i żadnej winy ani wady nie można było w nim znaleźć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 5, 'Dlatego ci mężczyźni powiedzieli: Nie znajdziemy przeciwko temu Danielowi żadnego powodu do oskarżenia, chyba że znajdziemy coś przeciwko niemu w prawie jego Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 6, 'Wtedy ci zwierzchnicy i satrapowie zgromadzili się przy królu i tak mu powiedzieli: Królu Dariuszu, żyj na wieki!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 7, 'Wszyscy zwierzchnicy królestwa, przełożeni i satrapowie, urzędnicy i dowódcy uzgodnili, aby ustanowić dekret królewski i zatwierdzić prawo, że ktokolwiek w ciągu trzydziestu dni poprosi o cokolwiek któregokolwiek boga lub człowieka prócz ciebie, królu, zostanie wrzucony do lwiej jamy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 8, 'I tak teraz, królu, zatwierdź to prawo i podaj go na piśmie, aby było nieodwołalne według prawa Medów i Persów, które nie może być cofnięte.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 9, 'Król Dariusz ogłosił więc na piśmie to prawo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 10, 'A gdy Daniel dowiedział się, że zostało podane na piśmie, wszedł do swego domu; a otwierając okna w swoim pokoju w stronę Jerozolimy, trzy razy dziennie klękał na kolanach, modlił się i chwalił swego Boga, jak to czynił przedtem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 11, 'Wtedy ci mężczyźni zgromadzili się i kiedy znaleźli Daniela modlącego się i błagającego swego Boga;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 12, 'Przyszli i powiedzieli królowi o dekrecie królewskim: Czy nie wydałeś dekretu, że każdy człowiek, który w ciągu trzydziestu dni poprosi o cokolwiek któregokolwiek boga lub człowieka prócz ciebie, królu, zostanie wrzucony do lwiej jamy? Król odpowiedział: Prawdziwa to jest mowa, zgodnie z prawem Medów i Persów, które nie może być cofnięte.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 13, 'Wtedy odezwali się i powiedzieli do króla: Ten Daniel, który jest z uprowadzonych synów Judy, nie liczy się z tobą, królu, ani z twoim dekretem, który wydałeś, bo trzy razy dziennie odmawia swoją modlitwę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 14, 'Gdy król usłyszał te słowa, bardzo się zasmucił z tego powodu i postanowił wybawić Daniela; aż do zachodu słońca usiłował go uratować.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 15, 'Ale ci mężczyźni zgromadzili się przy królu i powiedzieli do niego: Wiedz, królu, że prawo u Medów i Persów jest takie, że żadne prawo ani żaden dekret, który król ustanowił, nie może być zmieniony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 16, 'Wtedy król rozkazał, aby przyprowadzono Daniela i wrzucono go do lwiej jamy. A król powiedział do Daniela: Twój Bóg, któremu nieustannie służysz, on wybawi cię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 17, 'I przyniesiono kamień, i położono go na otworze jamy, a król opieczętował go swoim sygnetem i sygnetami swoich książąt, aby dekret wydany przeciwko Danielowi nie był zmieniony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 18, 'Następnie król poszedł do swego pałacu i pościł przez całą noc. Nie dopuścił do siebie niczego, co mogłoby go weselić, i sen odszedł od niego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 19, 'Potem król wstał bardzo wcześnie, o świcie, i spiesznie poszedł do lwiej jamy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 20, 'A gdy się zbliżył do jamy, zawołał do Daniela żałosnym głosem. Król zapytał Daniela: Danielu, sługo Boga żywego, czy twój Bóg, któremu nieustannie służysz, mógł cię wybawić od lwów?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 21, 'Wtedy Daniel odpowiedział królowi: Królu, żyj na wieki!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 22, 'Mój Bóg posłał swego Anioła, który zamknął paszcze lwom, aby mi nie wyrządziły żadnej szkody, dlatego że przed nim znalazła się we mnie niewinność. Owszem, również przed tobą, królu, nic złego nie uczyniłem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 23, 'Wtedy król bardzo się ucieszył z tego i rozkazał wyciągnąć Daniela z jamy. I wyciągnięto Daniela z jamy i nie znaleziono na nim żadnej rany, bo wierzył w swojego Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 24, 'I król rozkazał przyprowadzić tych mężczyzn, którzy oskarżyli Daniela, i wrzucono ich do lwiej jamy, ich samych, ich synów i ich żony. A zanim wpadli na dno jamy, lwy ich pochwyciły i zmiażdżyły wszystkie ich kości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 25, 'Wtedy król Dariusz napisał do wszystkich ludzi, narodów i języków, którzy mieszkali po całej ziemi: Niech pokój wam się rozmnoży!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 26, 'Wydaję dekret, aby w całym państwie mego królestwa wszyscy drżeli i bali się Boga Daniela, bo on jest Bogiem żywym i trwa na wieki, a jego królestwo nie będzie zniszczone i jego władza będzie trwać do końca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 27, 'On wyrywa i wybawia, czyni znaki i cuda na niebie i na ziemi; on wyrwał Daniela z mocy lwów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 28, 'A Danielowi dobrze się powodziło w królestwie Dariusza i w królestwie Cyrusa Persa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 1, 'W pierwszym roku Belszazara, króla Babilonu, Daniel miał sen i widzenia w swojej głowie na swoim łożu. Wtedy spisał ten sen i podał ogół rzeczy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 2, 'Daniel powiedział: Oto co zobaczyłem w swoim widzeniu w nocy: Oto cztery wiatry niebieskie potykały się na wielkim morzu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 3, 'A cztery wielkie bestie wyszły z morza, jedna różniła się od drugiej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 4, 'Pierwsza była podobna do lwa i miała orle skrzydła. Przypatrywałem się jej, aż jej skrzydła zostały wyrwane i podniosła się z ziemi tak, że stanęła na nogach jak człowiek, a dano jej serce ludzkie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 5, 'Potem oto druga bestia, podobna do niedźwiedzia. I stanęła na jednym boku, mając trzy żebra w paszczy między zębami. I tak mówiono do niej: Wstań, pożeraj dużo mięsa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 6, 'Potem spojrzałem, a oto inna bestia, podobna do pantery, która miała cztery ptasie skrzydła na grzbiecie. Bestia miała także cztery głowy i dano jej władzę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 7, 'Potem widziałem w nocnych widzeniach: Oto czwarta bestia, straszna, przerażająca i bardzo silna, mająca wielkie żelazne zęby. Pożerała i miażdżyła, a resztę deptała swoimi nogami. Różniła się od wszystkich bestii, które były przed nią, i miała dziesięć rogów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 8, 'Uważnie przypatrywałem się rogom, a oto mały róg wyrósł między nimi i trzy spośród tych pierwszych rogów zostały wyrwane przed nim. A oto w tym rogu były oczy podobne do oczu ludzkich i usta mówiące wielkie rzeczy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 9, 'I patrzyłem, aż trony zostały postawione, a Odwieczny zasiadł; jego szata była biała jak śnieg, a włosy jego głowy jak czysta wełna, jego tron jak ogniste płomienie, a jego koła jak płonący ogień.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 10, 'Strumień ognia wypływał i tryskał sprzed niego. Tysiąc tysięcy służyło mu, a dziesięć tysięcy po dziesięć tysięcy stało przed nim. Sąd zasiadł i otwarto księgi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 11, 'Wtedy patrzyłem z powodu głosu wielkich słów, które wypowiedział róg. Przypatrywałem się, aż bestia została zabita, a jej ciało zniszczone i wydane na spalenie w ogniu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 12, 'Także i pozostałym bestiom odebrano władzę i dano im przedłużenie życia aż do zamierzonego okresu i czasu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 13, 'Widziałem też w nocnym widzeniu: Oto w obłokach nieba przybył ktoś podobny do Syna Człowieka, przyszedł aż do Odwiecznego i przyprowadzono go przed niego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 14, 'I dano mu władzę, cześć i królestwo, aby wszyscy ludzie, wszystkie narody i języki służyli mu. Jego władza jest władzą wieczną, która nie przeminie, a jego królestwo nie będzie zniszczone.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 15, 'I ja, Daniel, zatrwożyłem się w duchu, w środku mego ciała, a widzenia w mojej głowie przestraszyły mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 16, 'Wtedy zbliżyłem się do jednego z tych, którzy tam stali, i pytałem go o prawdziwość tego wszystkiego. I powiedział mi, i oznajmił mi znaczenie tych rzeczy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 17, 'Te wielkie bestie, w liczbie czterech, to czterej królowie, którzy powstaną z ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 18, 'Ale święci Najwyższego wezmą królestwo i posiądą je na wieki, aż na wieki wieków.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 19, 'Wtedy pragnąłem poznać prawdę o czwartej bestii, która różniła się od wszystkich innych, straszna nad miarę, której zęby były żelazne, a pazury z brązu; która pożerała i miażdżyła, a resztę deptała swoimi nogami;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 20, 'Także o tych dziesięciu rogach, które były na jej głowie, i o innym, który wyrósł, przed którym upadły trzy, o tym właśnie rogu, który miał oczy i usta mówiące wielkie rzeczy, a wyglądał na większy od innych rogów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 21, 'I przypatrywałem się, a oto ten róg walczył ze świętymi i przemagał ich;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 22, 'Aż przyszedł Odwieczny i oddano sąd świętym Najwyższego; i nadszedł czas, aby święci otrzymali królestwo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 23, 'I powiedział tak: Czwarta bestia oznacza czwarte królestwo na ziemi, które będzie różniło się od wszystkich królestw, i pożre całą ziemię, podepcze i zmiażdży ją.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 24, 'A dziesięć rogów oznacza, że z tego królestwa powstanie dziesięciu królów, a po nich powstanie inny, który będzie różnił się od pierwszych i poniży trzech królów;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 25, 'Będzie mówił słowa przeciw Najwyższemu i wytracał świętych Najwyższego; będzie zamierzał zmienić czasy i prawa, gdyż będą wydane w jego ręce aż do czasu, czasów i połowy czasu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 26, 'Potem zasiądzie sąd i tam odbiorą mu władzę, aby została zniszczona i wytracona aż do końca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 27, 'A królestwo, władza i wielkość królestwa pod całym niebem zostaną oddane ludowi świętych Najwyższego, którego królestwo będzie królestwem wiecznym, a wszystkie zwierzchności będą mu służyć i jego słuchać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 28, 'Tutaj jest koniec tych słów. A mnie Daniela bardzo zatrwożyły moje myśli i moje oblicze zmieniło się. Zachowałem jednak tę sprawę w swoim sercu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 1, 'W trzecim roku panowania króla Belszazara ukazało mi się widzenie, mnie Danielowi, po tym, które ukazało mi się na początku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 2, 'Zobaczyłem w widzeniu, że jestem w pałacu Suza, który znajdował się w prowincji Elam; zobaczyłem w widzeniu, że jestem nad rzeką Ulaj.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 3, 'I podniosłem swoje oczy, i spojrzałem, a oto nad rzeką stał baran mający dwa rogi. Te dwa rogi były wysokie, lecz jeden był wyższy od drugiego, ale ten wyższy wyrósł później.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 4, 'Widziałem, jak baran bódł na zachód, na północ i na południe, a żadna bestia nie mogła stać przed nim i nie było nikogo, kto by wyrwał się z jego ręki. Czynił on według swojej woli i stał się wielki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 5, 'Gdy się zastanawiałem nad tym, oto przyszedł kozioł z zachodu po powierzchni całej ziemi, nie dotykając ziemi. A ten kozioł miał okazały róg między swoimi oczami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 6, 'I przyszedł aż do tego barana, który miał dwa rogi, którego widziałem stojącego nad rzeką; podbiegł do niego w zapalczywości swojej siły.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 7, 'Widziałem także, że natarł na tego barana, a rozjuszywszy się na niego, uderzył barana, tak że złamał mu oba rogi. I baran nie miał siły, aby go odeprzeć; i rzucił go o ziemię, zdeptał go, a nie było nikogo, kto by wyrwał barana z jego mocy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 8, 'Wtedy kozioł stawał się bardzo wielki, ale gdy stał się potężny, złamał się wielki róg, a na jego miejsce wyrosły cztery rogi okazałe na cztery strony świata.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 9, 'Z jednego z nich wyrósł mały róg, a ten bardzo wzrastał ku południu, ku wschodowi i ku wspaniałej ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 10, 'Wzrósł aż do wojska niebieskiego i zrzucił na ziemię część wojska oraz gwiazd i podeptał je.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 11, 'Wzniósł się nawet aż do księcia tego wojska i przez niego została odjęta codzienna ofiara i zostało porzucone miejsce jego świątyni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 12, 'Także wojsko zostało mu podane przeciwko codziennej ofierze z powodu przestępstwa i porzucił prawdę na ziemię, a cokolwiek czynił, powodziło mu się.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 13, 'Wtedy usłyszałem jednego ze świętych mówiącego, a inny święty zapytał tego, który mówił: Jak długo będzie trwać widzenie o codziennej ofierze i przestępstwie spustoszenia, a świątynia i wojsko będą podane na podeptanie?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 14, 'I powiedział do mnie: Aż do dwóch tysięcy trzystu wieczorów i poranków. Wtedy świątynia zostanie oczyszczona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 15, 'A gdy ja, Daniel, patrzyłem na to widzenie i pytałem się o jego znaczenie, oto stanął przede mną ktoś o wyglądzie mężczyzny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 16, 'Usłyszałem też ludzki głos między brzegami Ulaj, który zawołał: Gabrielu, wyjaśnij mu to widzenie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 17, 'I przyszedł do mnie, gdzie stałem. A gdy przyszedł, zląkłem się i padłem na twarz. I powiedział do mnie: Zrozum, synu człowieczy, bo to widzenie spełni się w czasie ostatecznym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 18, 'Gdy mówił do mnie, zapadłem w głęboki sen, leżąc twarzą ku ziemi. Wtedy dotknął mnie i postawił na nogi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 19, 'I powiedział: Oto oznajmię tobie, co się będzie dziać, kiedy skończy się gniew, bo koniec nastąpi w czasie oznaczonym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 20, 'Ten baran, którego widziałeś, o dwóch rogach, to są królowie Medów i Persów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 21, 'A ten kosmaty kozioł to król Grecji, a ten wielki róg między jego oczami to pierwszy król.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 22, 'A to, że został złamany, a powstały cztery inne w jego miejsce, oznacza, że cztery królestwa powstaną z jego narodu, ale nie będą miały jego potęgi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 23, 'A pod koniec ich panowania, gdy przestępcy dopełnią swej miary, powstanie król o srogim obliczu i podstępny;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 24, 'Jego moc będzie potężna, lecz nie dzięki własnej sile. Będzie niszczył w sposób zadziwiający i szczęśliwie mu się powiedzie w działaniu, bo zniszczy mocarzy i lud święty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 25, 'A dzięki jego pomyślności poszczęści mu się podstęp w jego ręku, będzie się wynosił w swoim sercu i w czasie pokoju zniszczy wielu. Ponadto powstanie przeciw Księciu książąt, lecz bez udziału ręki ludzkiej zostanie skruszony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 26, 'A to widzenie wieczorne i poranne, o którym była mowa, jest prawdą. Dlatego zapieczętuj to widzenie, bo spełni się po wielu dniach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 27, 'Wtedy ja, Daniel, zemdlałem i chorowałem przez kilka dni; potem wstałem i załatwiałem sprawy króla; zdumiewałem się nad tym widzeniem, ale nikt go nie rozumiał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 1, 'W pierwszym roku Dariusza, syna Aswerusa, z rodu Medów, który był ustanowiony królem nad królestwem Chaldejczyków;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 2, 'W pierwszym roku jego królowania ja, Daniel, zrozumiałem dzięki księgom liczbę lat, o których doszło słowo Pana do proroka Jeremiasza, że miało się wypełnić spustoszenie Jerozolimy w siedemdziesiąt lat.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 3, 'I zwróciłem swoją twarz do Pana Boga, by szukać go modlitwą i błaganiem, w poście, worze i popiele.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 4, 'Modliłem się więc do Pana, mojego Boga, wyznawałem i mówiłem: Panie, Boże wielki i straszny, strzegący przymierza i miłosierdzia względem tych, którzy cię miłują i przestrzegają twoich przykazań;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 5, 'Zgrzeszyliśmy, dopuściliśmy się nieprawości, postępowaliśmy niegodziwie i zbuntowaliśmy się, odstępując od twoich przykazań i praw;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 6, 'I nie usłuchaliśmy twoich sług, proroków, którzy mówili w twoim imieniu do naszych królów, do naszych książąt, do naszych ojców i do całego ludu ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 7, 'Do ciebie, Panie, należy sprawiedliwość, a nam się należy wstyd na twarzach, jak to jest dziś, oraz mężczyznom Judy, mieszkańcom Jerozolimy i całemu Izraelowi, bliskim i dalekim we wszystkich ziemiach, do których ich wygnałeś z powodu ich występków, jakie popełnili przeciwko tobie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 8, 'Panie, nam się należy wstyd na twarzy, naszym królom, naszym książętom i naszym ojcom, bo zgrzeszyliśmy przeciwko tobie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 9, 'Ale do Pana, naszego Boga, należą miłosierdzie i przebaczenie, choć zbuntowaliśmy się przeciwko niemu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 10, 'A nie byliśmy posłuszni głosowi Pana, naszego Boga, by postępować według jego ustaw, które dał nam przez swoje sługi, proroków;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 11, 'Owszem, cały Izrael przekroczył twoje prawo i odstąpił od ciebie, aby nie słuchać twego głosu. Dlatego wylały się na nas przekleństwo i przysięga, które są zapisane w Prawie Mojżesza, sługi Boga. Zgrzeszyli bowiem przeciwko niemu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 12, 'A on spełnił swoje słowa, które wypowiedział przeciwko nam i przeciwko naszym sędziom, którzy nas sądzili, i sprowadził na nas to wielkie nieszczęście. Nie zdarzyło się bowiem pod całym niebem to, co zdarzyło się w Jerozolimie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 13, 'Tak jak jest napisane w Prawie Mojżesza, całe to nieszczęście spadło na nas. My jednak nie błagaliśmy Pana, naszego Boga, o to, abyśmy mogli odwrócić się od naszych nieprawości i mieli wzgląd na twoją prawdę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 14, 'Dlatego czuwał Pan nad tym nieszczęściem i sprowadził je na nas, bo Pan, nasz Bóg, jest sprawiedliwy we wszystkich swoich dziełach, których dokonuje. My zaś nie usłuchaliśmy jego głosu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 15, 'A teraz, Panie, nasz Boże, który wyprowadziłeś swój lud z ziemi Egiptu mocną ręką i uczyniłeś sobie imię, jak to jest dziś: zgrzeszyliśmy i postępowaliśmy niegodziwie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 16, 'Panie, według wszelkiej twojej sprawiedliwości proszę, niech się odwróci twoja zapalczywość i twój gniew od twojego miasta, Jerozolimy, od twojej świętej góry, bo z powodu naszych grzechów i nieprawości naszych ojców Jerozolima i twój lud stały się przedmiotem zniewagi wśród wszystkich, którzy są dokoła nas.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 17, 'Teraz więc wysłuchaj, nasz Boże, modlitwy twego sługi i jego błagań, a rozjaśnij swe oblicze nad swoją spustoszoną świątynią ze względu na Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 18, 'Nakłoń, mój Boże, swego ucha i wysłuchaj; otwórz swe oczy i zobacz nasze spustoszenia i miasto, które jest nazwane twoim imieniem, bo nie ze względu na naszą sprawiedliwość zanosimy swoje błagania przed ciebie, ale ze względu na twoje wielkie miłosierdzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 19, 'Panie, wysłuchaj! Panie, przebacz! Panie, spójrz i działaj. Nie zwlekaj ze względu na siebie samego, mój Boże, bo twoje miasto i twój lud są nazwane twoim imieniem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 20, 'A gdy jeszcze mówiłem, modliłem się i wyznawałem swój grzech oraz grzech mego ludu Izraela, i zanosiłem swoje błagania przed Pana, mojego Boga, za świętą górę mojego Boga;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 21, 'Gdy jeszcze mówiłem w modlitwie, oto mąż Gabriel, którego widziałem w widzeniu na początku, przyleciał spiesznie i dotknął mnie w czasie ofiary wieczornej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 22, 'I wyjaśniał mi, i rozmawiał ze mną, mówiąc: Danielu, teraz wyszedłem, aby uczynić cię zdolnym do zrozumienia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 23, 'Na początku twoich błagań wyszło słowo, a ja przybyłem, aby ci je oznajmić, bo jesteś bardzo umiłowany. Tak więc rozważ to słowo i zrozum widzenie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 24, 'Siedemdziesiąt tygodni wyznaczono nad twoim ludem i twoim świętym miastem na zakończenie przestępstwa, na zgładzenie grzechów i na przebłaganie za nieprawość, na wprowadzenie wiecznej sprawiedliwości, na opieczętowanie widzenia i proroctwa oraz na namaszczenie Najświętszego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 25, 'Dlatego wiedz i zrozum, że od wyjścia nakazu o przywróceniu i odbudowaniu Jerozolimy aż do Księcia Mesjasza będzie siedem tygodni i sześćdziesiąt dwa tygodnie. Zostaną odbudowane ulica i mur, ale w czasach trudnych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 26, 'A po tych sześćdziesięciu dwóch tygodniach zostanie zabity Mesjasz, lecz nie za siebie. A lud księcia, który przyjdzie, zniszczy miasto i świątynię i jego koniec nastąpi wśród powodzi; i do końca wojny są postanowione spustoszenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 27, 'Utrwali przymierze z wieloma przez jeden tydzień. A w połowie tego tygodnia sprawi, że ustanie ofiara spalana i ofiara z pokarmów, a przez mnóstwo obrzydliwości uczyni spustoszenie aż do końca, i wyleje się to, co postanowione, na tego, który ma być spustoszony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 1, 'W trzecim roku Cyrusa, króla Persji, zostało objawione słowo Danielowi, któremu nadano imię Belteszassar; to słowo było prawdziwe i zamierzony czas był długi. Zrozumiał to słowo, bo otrzymał zrozumienie w widzeniu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 2, 'W tych dniach ja, Daniel, byłem smutny przez trzy tygodnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 3, 'Nie jadłem smacznego chleba, mięsa i wina nie brałem do ust, i nie namaszczałem się olejkiem, aż się wypełniły trzy tygodnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 4, 'A dwudziestego czwartego dnia pierwszego miesiąca byłem nad brzegiem wielkiej rzeki, to jest Chiddekel;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 5, 'I podniosłem swoje oczy, i spojrzałem, a oto stał pewien mąż ubrany w lnianą szatę, a jego biodra były przepasane czystym złotem z Ufas;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 6, 'Jego ciało było jak z berylu, jego oblicze z wyglądu jak błyskawica, jego oczy – jak pochodnie ogniste, jego ramiona i nogi – jak blask wypolerowanej miedzi, a dźwięk jego słów – jak głos tłumu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 7, 'Tylko ja sam, Daniel, miałem to widzenie. Mężczyźni, którzy byli ze mną, nie mieli tego widzenia; ale wielki strach padł na nich i pouciekali, aby się ukryć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 8, 'A ja sam zostałem i miałem to wielkie widzenie, ale nie pozostało we mnie siły. Moja uroda zmieniła się i zepsuła, i nie miałem żadnej siły.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 9, 'Wtedy usłyszałem dźwięk jego słów; a gdy usłyszałem dźwięk jego słów, upadłem na twarz w głęboki sen, twarzą ku ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 10, 'I oto dotknęła mnie ręka, i podniosła mnie na moje kolana i na dłonie moich rąk.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 11, 'I powiedział do mnie: Danielu, mężu bardzo umiłowany, uważaj na moje słowa, które mówię do ciebie, i stań na nogi, bo jestem teraz posłany do ciebie. A gdy przemówił do mnie to słowo, stanąłem drżąc.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 12, 'Wtedy powiedział do mnie: Nie bój się, Danielu, bo od pierwszego dnia, gdy wziąłeś sobie do serca to, aby zrozumieć i ukorzyć się przed swoim Bogiem, twoje słowa zostały wysłuchane, a ja przybyłem ze względu na twoje słowa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 13, 'Lecz książę królestwa Persji sprzeciwiał mi się przez dwadzieścia jeden dni, ale oto Michał, jeden z przedniejszych książąt, przyszedł mi z pomocą; a ja zostałem tam przy królach Persji.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 14, 'Ale przybyłem, aby ci oznajmić, co spotka twój lud w dniach ostatecznych, bo to widzenie będzie jeszcze na te dni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 15, 'A gdy mówił do mnie tymi słowy, opuściłem twarz ku ziemi i zamilkłem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 16, 'A oto ktoś jakby podobny do synów ludzkich dotknął moich warg. Otworzyłem usta i mówiłem, powiedziałem do stojącego przede mną: Mój panie, z powodu tego widzenia dopadły mnie boleści i nie mam żadnej siły.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 17, 'A jakże będzie mógł taki sługa mego pana rozmawiać w ten sposób z moim panem? Gdyż od tego czasu nie została we mnie siła i nie ma we mnie tchu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 18, 'Wtedy ponownie dotknął mnie ten, który był podobny do człowieka, i wzmocnił mnie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 19, 'I powiedział: Nie bój się, mężu bardzo umiłowany, pokój tobie! Wzmocnij się, mówię, wzmocnij się. A gdy mówił do mnie, nabrałem siły i powiedziałem: Niech mój pan mówi, bo mnie wzmocniłeś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 20, 'Powiedział: Czy wiesz, dlaczego przybyłem do ciebie? Teraz wrócę, aby walczyć z księciem Persji. A gdy odejdę stamtąd, oto nadejdzie książę Grecji.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 21, 'Ale oznajmię ci to, co jest zapisane w piśmie prawdy. I nie ma nikogo, który by mężnie stał przy mnie w tych sprawach, oprócz Michała, waszego księcia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 1, 'W pierwszym roku Dariusza Meda stanąłem, aby go pokrzepić i wzmocnić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 2, 'A teraz oznajmię ci prawdę: Oto jeszcze trzej królowie będą panować w Persji, potem czwarty wzbogaci się o wiele bardziej niż wszyscy, a gdy się umocni w swoich bogactwach, podburzy wszystkich przeciw królestwu Grecji.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 3, 'I powstanie potężny król, który będzie sprawował wielką władzę, i będzie czynił według swojej woli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 4, 'A gdy on się umocni, jego królestwo zostanie pokruszone i rozdzielone na cztery strony świata, ale nie między jego potomków i nie według władzy, jaką sprawował. Jego królestwo bowiem zostanie wykorzenione, a dostanie się innym, ale nie tym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 5, 'Wtedy umocni się król południa oraz jeden z jego książąt. Ten będzie mocniejszy od niego i będzie panować, a jego władza będzie władzą rozległą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 6, 'Lecz po upływie kilku lat połączą się, bo córka króla południa przybędzie do króla północy, aby zawrzeć przymierze. Ona jednak nie otrzyma siły ramienia ani on nie ostoi się ze swoim ramieniem. Ale zostanie ona wydana, a z nią ci, którzy ją sprowadzili, jej syn oraz ten, co ją umacniał w tych czasach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 7, 'Potem z latorośli jej korzenia powstanie ktoś na jego miejsce, kto nadciągnie ze swoim wojskiem, wkroczy do twierdzy króla północy, będzie rządził nimi i zwycięży.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 8, 'Także ich bogów wraz z ich książętami i drogimi naczyniami ze srebra i złota uprowadzi do niewoli do Egiptu; i będzie bezpieczny przez wiele lat od króla północy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 9, 'A król południa wtargnie do królestwa i wróci do swojej ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 10, 'Ale jego synowie będą walczyć i zgromadzą mnóstwo wielkich wojsk. Jeden z nich nadciągnie z siłą jak powódź i przejdzie. Potem wróci i wojskiem będzie nacierać aż do jego twierdzy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 11, 'Wtedy król południa, będąc rozjuszony, wyruszy i będzie walczył z nim, to jest z królem północy. Uszykuje wielkie mnóstwo, ale to mnóstwo zostanie wydane w jego rękę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 12, 'A gdy to mnóstwo zostanie rozbite, jego serce się wywyższy, a choć powali dziesiątki tysięcy, nie umocni się.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 13, 'Wróci bowiem król północy i uszykuje większe mnóstwo niż poprzednie, i po upływie kilku lat przyjdzie na pewno z wielkim wojskiem i mnóstwem bogactw.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 14, 'W tych czasach wielu powstanie przeciwko królowi południa. Synowie zbójców spośród twego ludu powstaną, aby utwierdzić widzenie, ale upadną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 15, 'Nadciągnie więc król północy, usypie wały i zdobędzie miasta warowne, a nie oprą się ramiona południa ani jego lud wybrany, i nie będą mieć siły, by stawić opór.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 16, 'Ten, który nadciągnie przeciwko niemu, uczyni według swojej woli, i nie będzie nikogo, kto by mu się przeciwstawił; stanie też w pięknej ziemi, która zostanie zniszczona przez jego rękę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 17, 'Potem zwróci swoją twarz, aby przyjść z siłą całego swego królestwa, i będzie wyglądał, jakby szukał zgody, i uczyni tak: da mu córkę piękną, aby doprowadził go przez nią do zguby. Ale ona nie będzie go wspierać ani nie będzie za nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 18, 'Potem zwróci swoją twarz ku wyspom i zdobędzie ich wiele. Ale pewien wódz położy kres jego zniewadze, ponadto odpłaci mu za tę zniewagę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 19, 'Dlatego zwróci swoją twarz ku twierdzom swojej ziemi, lecz potknie się i upadnie, i nie będzie już znaleziony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 20, 'I powstanie na jego miejsce taki, który roześle poborców w chwale królestwa. Ale po niewielu dniach zostanie zniszczony, lecz nie w gniewie ani nie w bitwie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 21, 'Potem powstanie na jego miejsce człowiek godny pogardy, któremu nie dadzą godności królestwa. Przyjdzie jednak w pokoju i zdobędzie królestwo pochlebstwem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 22, 'A ramionami, jakby powodzią, zostaną porwani sprzed jego oblicza i skruszeni, a także książę przymierza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 23, 'Po zawarciu przymierza z nim będzie postępował zdradliwie. Nadciągnie bowiem i umocni się z niewielkim ludem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 24, 'Nieoczekiwanie wkroczy nawet do najbogatszych miejsc prowincji i uczyni to, czego nie czynili jego ojcowie ani ojcowie jego ojców. Łup, zdobycz i bogactwo rozdzieli między nich. Uknuje plany przeciw warowniom, ale do czasu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 25, 'Potem pobudzi swoją moc i swe serce przeciw królowi południa z wielkim wojskiem. Król południa przygotuje się do walki z wielkim i potężnym wojskiem, ale się nie oprze, gdyż obmyślą przeciwko niemu zdradę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 26, 'Ci, którzy jedzą jego chleb, zniszczą go, gdy jego wojsko najedzie jak powódź, i padnie wielu zabitych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 27, 'Obaj królowie w swych sercach będą mieli złe zamiary i przy jednym stole będą mówić kłamstwa; ale to się im nie uda, gdyż koniec będzie w jeszcze innym wyznaczonym czasie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 28, 'Potem powróci do swojej ziemi z wielkim bogactwem, a jego serce zwróci się przeciwko świętemu przymierzu; tak będzie działał i wróci do swojej ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 29, 'W czasie wyznaczonym wróci i skieruje się na południe, ale nie powiedzie mu się tak jak za pierwszym i drugim razem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 30, 'Przeciwko niemu bowiem wyruszą okręty z Kittim, będzie przygnębiony, wróci i rozgniewa się na święte przymierze; tak będzie działał. I znowu wróci, i zawrze porozumienie z tymi, którzy opuścili święte przymierze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 31, 'A powstaną przez niego wojska, które zbezczeszczą świątynię-twierdzę i zniosą codzienną ofiarę, a postawią obrzydliwość spustoszenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 32, 'A tych, którzy będą postępować niegodziwie przeciwko przymierzu, splugawi pochlebstwem. Ale lud znający swego Boga umocni się i będzie działać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 33, 'A rozumni wśród ludu będą nauczać wielu, ale będą padać od miecza, od ognia, od niewoli i od łupu przez wiele dni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 34, 'Gdy padną, będą mieli niewielką pomoc i wielu przyłączy się do nich pochlebstwem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 35, 'Spośród tych rozumnych niektórzy padną, aby byli doświadczeni, oczyszczeni i wybieleni aż do czasu ostatecznego, bo to jeszcze potrwa aż do czasu wyznaczonego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 36, 'A król uczyni według swojej woli, wyniesie się i wywyższy się ponad każdego boga; będzie mówić dziwne rzeczy przeciwko Bogu bogów i poszczęści mu się, aż dokona się gniew. To bowiem, co zostało postanowione, dokona się.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 37, 'Nie będzie miał względu ani na boga swoich ojców, ani na pożądanie kobiet, ani na żadnego boga, gdyż wyniesie się ponad wszystko.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 38, 'Zamiast tego będzie czcił boga twierdz; boga, którego nie znali jego ojcowie, będzie czcił złotem, srebrem i drogocennymi kamieniami, i kosztownościami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 39, 'Tak postąpi w twierdzach obcego boga, a którego uzna i obdarzy sławą. I sprawi, że będą panowali nad wieloma, i rozdzieli im ziemię jako zapłatę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 40, 'A pod koniec czasu będzie z nim walczył król południa; ale król północy uderzy na niego jak burza z rydwanami, jeźdźcami i licznymi okrętami, wtargnie do krajów, zaleje je i przejdzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 41, 'Potem wkroczy do pięknej ziemi i wiele krajów padnie. Te jednak ujdą z jego rąk: Edom, Moab i pierwsi z synów Ammona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 42, 'Wyciągnie swą rękę po kraje, a ziemia Egiptu nie zdoła mu ujść.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 43, 'Opanuje skarby złota i srebra oraz wszystkie kosztowności Egiptu, a Libijczycy i Etiopczycy pójdą za nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 44, 'Ale wieści ze wschodu i z północy przestraszą go. Dlatego wyruszy z wielkim gniewem, aby wielu wygubić i wytępić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 45, 'I rozbije namioty swego pałacu między morzami na pięknej górze świętej; ale jego koniec przyjdzie na niego i nikt mu nie pomoże.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 1, 'W tym czasie powstanie Michał, wielki książę, który wstawia się za synami twego ludu. Nastanie czas ucisku, jakiego nie było, odkąd narody zaczęły istnieć aż do tego czasu. W tym czasie twój lud zostanie wybawiony, każdy, kto znajdzie się zapisany w księdze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 2, 'A wielu z tych, którzy śpią w prochu ziemi, obudzi się, jedni do życia wiecznego, a drudzy ku hańbie i wiecznej pogardzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 3, 'Ci, którzy są mądrzy, będą świecić jak blask firmamentu, a ci, którzy przyprowadzili wielu do sprawiedliwości – jak gwiazdy na wieki wieków.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 4, 'Ale ty Danielu zamknij te słowa i zapieczętuj tę księgę aż do czasu ostatecznego. Wielu będzie przebiegać, a pomnoży się wiedza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 5, 'I ja, Daniel, spojrzałem, a oto stało dwóch innych, jeden na brzegu rzeki po tej stronie, a drugi na brzegu rzeki po tamtej stronie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 6, 'Jeden powiedział do męża odzianego w lnianą szatę, który stał nad wodami rzeki: Kiedy będzie koniec tych dziwnych rzeczy?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 7, 'I usłyszałem tego męża odzianego w lnianą szatę, który stał nad wodami rzeki. Podniósł swoją prawą i lewą rękę do nieba i przysiągł na Żyjącego na wieki, że będzie to na czas, czasy i połowę czasu. I gdy doszczętnie rozproszy siłę świętego ludu, wtedy to się wszystko wypełni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 8, 'Ja to usłyszałem, ale nie zrozumiałem, więc zapytałem: Mój Panie, jaki będzie koniec tych rzeczy?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 9, 'Wtedy odpowiedział: Idź, Danielu, bo te słowa są zamknięte i zapieczętowane aż do czasu ostatecznego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 10, 'Wielu będzie oczyszczonych, wybielonych i doświadczonych, ale bezbożni będą postępować bezbożnie. Żaden bezbożny nie zrozumie, ale mądrzy zrozumieją.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 11, 'A od tego czasu, kiedy zostanie zniesiona ofiara codzienna i będzie postawiona obrzydliwość spustoszenia, upłynie tysiąc dwieście dziewięćdziesiąt dni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 12, 'Błogosławiony, kto doczeka i dojdzie do tysiąca trzystu trzydziestu pięciu dni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 13, 'Ale ty idź swoją drogą do końca. Odpoczniesz i pozostaniesz w swoim losie przy końcu dni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 1, 'Słowo Pana, które doszło do Ozeasza, syna Beeriego, za dni Uzjasza, Jotama, Achaza, Ezechiasza, królów Judy, i za dni Jeroboama, syna Joasza, króla Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 2, 'Początek słowa Pana przez Ozeasza. Pan powiedział do Ozeasza: Idź, weź sobie nierządnicę za żonę i dzieci nierządu. Ziemia bowiem uprawiała wstydliwy nierząd, odwróciła się od Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 3, 'Poszedł więc i wziął sobie za żonę Gomerę, córkę Diblaima, a ona poczęła i urodziła mu syna.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 4, 'Pan powiedział do niego: Nadaj mu imię Jizreel, bo już niedługo pomszczę na domu Jehu krew Jizreel i sprawię, że ustanie królestwo domu Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 5, 'W tym dniu złamię łuk Izraela w dolinie Jizreel.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 6, 'I poczęła znowu, i urodziła córkę. Pan powiedział do niego: Nadaj jej imię Lo-Ruchama, bo już nie zlituję się nad domem Izraela, lecz na pewno go wytępię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 7, 'Ale zlituję się nad domem Judy i wybawię go przez Pana, jego Boga, lecz nie wybawię łukiem ani mieczem, ani wojną, ani końmi, ani jeźdźcami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 8, 'Gdy odstawiła od piersi Lo-Ruchamę, znowu poczęła i urodziła syna.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 9, 'I Pan powiedział: Nadaj mu imię Lo-Ammi, bo wy nie jesteście moim ludem, ja też nie będę waszym Bogiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 10, 'Jednak liczba synów Izraela będzie jak piasek morski, którego nie można zmierzyć ani zliczyć. I stanie się, że w miejscu, gdzie im mówiono: Nie jesteście moim ludem, będzie się do nich mówić: Wy jesteście synami Boga żywego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 11, 'I będą zgromadzeni razem synowie Judy i synowie Izraela, ustanowią sobie jedną głowę i wyjdą z tej ziemi. Wielki bowiem będzie dzień Jizreel.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 1, 'Mówcie swoim braciom: Ammi, i swoim siostrom, Ruchama!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 2, 'Spierajcie się z waszą matką, spierajcie się, bo ona nie jest moją żoną, a ja też nie jestem jej mężem. Niech usunie swoje czyny nierządu sprzed swego oblicza, a swoje cudzołóstwa spośród swoich piersi;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 3, 'W przeciwnym razie rozbiorę ją do naga i wystawię taką, jaka była w dniu swego narodzenia; uczynię ją podobną do pustyni, zostawię ją jak suchą ziemię i uśmiercę ją pragnieniem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 4, 'Nie zlituję się nad jej dziećmi, gdyż są dziećmi nierządu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 5, 'Ich matka bowiem uprawiała nierząd, bezwstydnie postępowała ich rodzicielka. Mówiła bowiem: Pójdę za moimi kochankami, którzy dają mi mój chleb i moją wodę, moją wełnę i mój len, moją oliwę i moje napoje.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 6, 'Dlatego oto zagrodzę jej drogę cierniami i otoczę murem, aby nie mogła znaleźć swoich ścieżek.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 7, 'Wtedy będzie biegać za swymi kochankami, lecz ich nie dogoni; będzie ich szukać, ale nie znajdzie. Potem powie: Pójdę i wrócę do swego pierwszego męża, bo lepiej mi było wtedy niż teraz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 8, 'Ona bowiem nie wie, że to ja dawałem jej zboże, moszcz i oliwę, że dawałem jej obfitość srebra i złota, których oni używali dla Baala.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 9, 'Dlatego wrócę i zabiorę moje zboże w swoim czasie, mój moszcz w swoim czasie, odbiorę jej moją wełnę i mój len, który dałem na okrywanie jej nagości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 10, 'A teraz odkryję jej bezwstydność na oczach jej kochanków i nikt jej nie wyrwie z mojej ręki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 11, 'I położę kres całej jej radości, jej świętom, jej nowiom, jej szabatom i wszystkim jej uroczystym świętom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 12, 'Zniszczę też jej winorośle i drzewa figowe, o których mówiła: Oto moja zapłata, którą mi dali moi kochankowie. I zamienię je w lasy, które pożrą polne zwierzęta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 13, 'I ukarzę ją za te dni Baalów, gdy im paliła kadzidło, stroiła się w swoje kolczyki i klejnoty i chodziła za swymi kochankami, a o mnie zapomniała, mówi Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 14, 'Dlatego oto zwabię ją, zaprowadzę na pustynię i będę mówić do niej łaskawie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 15, 'I dam jej winnice z tego miejsca i dolinę Akor jako wrota nadziei. Ona będzie tam śpiewała jak za dni swej młodości, jak w dniu, kiedy wyszła z ziemi Egiptu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 16, 'W tym dniu, mówi Pan, będziesz mnie nazywać Iszi – mój mężu, a nie będziesz mnie już nazywała Baal – mój panie!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 17, 'Usunę bowiem z twoich ust imiona Baalów i ich imiona nie będą już wspomniane.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 18, 'W tym dniu zawrę dla ciebie przymierze z polnymi zwierzętami, z ptactwem nieba i z tym, co pełza po ziemi. Pokruszę łuk i miecz, wojnę z ziemi usunę i sprawię, że będą mieszkać bezpiecznie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 19, 'I poślubię cię sobie na wieki; poślubię cię sobie w sprawiedliwości, w sądzie, w miłosierdziu i w litości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 20, 'Poślubię cię też sobie w wierności i poznasz Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 21, 'W tym dniu wysłucham, mówi Pan, wysłucham niebios, a one wysłuchają ziemi;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 22, 'Ziemia wysłucha zboża, moszczu i oliwy, a te rzeczy wysłuchają Jizreel.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 23, 'Zasieję go sobie na ziemi i zlituję się nad tym, który nie dostąpił miłosierdzia, i powiem do tego, który nie był moim ludem: Ty jesteś moim ludem! A on powie: Ty jesteś moim Bogiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 1, 'I powiedział do mnie Pan: Idź jeszcze, pokochaj kobietę kochaną przez innego – cudzołożnicę, tak jak Pan miłuje synów Izraela, choć oni oglądają się za innymi bogami i kochają bukłaki wina.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 2, 'Więc kupiłem ją sobie za piętnaście srebrników i za półtora chomera jęczmienia;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 3, 'I powiedziałem do niej: Pozostaniesz u mnie przez wiele dni. Nie będziesz uprawiała nierządu ani nie będziesz należała do innego mężczyzny, a ja też będę dla ciebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 4, 'Przez wiele dni bowiem synowie Izraela będą bez króla, bez księcia, bez ofiary, bez posągu, bez efodu i bez terafim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 5, 'Potem synowie Izraela nawrócą się i będą szukać Pana, swego Boga, i Dawida, swego króla; a w ostatecznych dniach będą się bać Pana i jego dobroci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 1, 'Słuchajcie słowa Pana, synowie Izraela, bo Pan wnosi skargę przeciwko mieszkańcom tej ziemi, gdyż nie ma prawdy ani żadnego miłosierdzia, ani poznania Boga w ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 2, 'Krzywoprzysięstwo, kłamstwo, zabójstwo, kradzież i cudzołóstwo mnożą się, a morderstwo goni morderstwo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 3, 'Dlatego ziemia będzie lamentować i marnieje wszystko, co w niej mieszka, wraz z polnymi zwierzętami i ptactwem nieba, nawet ryby morskie wyginą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 4, 'Ale niech nikt z nimi się nie spiera ani ich nie strofuje, bo twój lud jest jak ci, którzy spierają się z kapłanem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 5, 'Dlatego upadniesz we dnie, upadnie też wraz z tobą prorok w nocy; wyniszczę twoją matkę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 6, 'Mój lud ginie z braku poznania; a ponieważ ty odrzuciłeś poznanie, ja też ciebie odrzucę, abyś już nie był dla mnie kapłanem. Skoro zapomniałeś o prawie twego Boga, ja też zapomnę o twoich synach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 7, 'Im bardziej się rozmnożyli, tym więcej grzeszyli przeciwko mnie. Dlatego ich chwałę zamienię w hańbę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 8, 'Pożerają ofiary za grzech mego ludu i swoją duszą pragną jego nieprawości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 9, 'I tak samo stanie się z ludem jak z kapłanem, bo ukarzę ich za ich drogi i oddam im za ich uczynki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 10, 'Będą jeść, ale się nie nasycą, będą uprawiać nierząd, ale się nie pomnożą, bo nie chcą zważać na Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 11, 'Nierząd, wino i moszcz odbierają serce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 12, 'Mój lud radzi się u swego drewna, a jego kij mu odpowiada, bo duch nierządu wprowadza ich w błąd i uprawiali nierząd, odstępując od swego Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 13, 'Na szczytach gór składają ofiary i na pagórkach palą kadzidło pod dębem, topolą i wiązem, bo ich cień jest dobry. Dlatego wasze córki uprawiają nierząd i wasze kobiety cudzołożą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 14, 'Nie będę karał waszych córek, gdy uprawiają nierząd, ani waszych kobiet, gdy cudzołożą. Oni sami bowiem odłączają się z nierządnicami i składają ofiary wraz z nierządnicami. A lud, który tego nie rozumie, upadnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 15, 'Jeśli ty, Izraelu, uprawiasz nierząd, niech chociaż Juda nie obciąży się winą. Nie idźcie do Gilgal ani nie wstępujcie do Bet-Awen, ani nie przysięgajcie: Jak żyje Pan!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 16, 'Izrael bowiem jest nieujarzmiony jak narowista jałówka. Zaprawdę, Pan będzie ich paść jak jagnię na rozległym miejscu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 17, 'Efraim związał się z bożkami. Zostaw go.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 18, 'Ich napój czyni ich upartymi; nieustannie uprawiają nierząd; jego obrońcy wstydliwie kochają dary.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 19, 'Pochwyci ich wiatr swoimi skrzydłami i będą zawstydzeni z powodu swoich ofiar.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 1, 'Słuchajcie tego, kapłani, zważ na to, domu Izraela, i nakłoń ucha, domu króla. Przeciwko wam bowiem jest sąd, ponieważ byliście sidłem dla Mispy i siecią rozciągniętą na Taborze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 2, 'Owszem, udają się podstępnie na rzeź, ale ja ukarzę każdego z nich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 3, 'Znam Efraima i Izrael nie jest ukryty przede mną, bo teraz, Efraimie, uprawiasz nierząd, a Izrael się splugawił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 4, 'Nie chcą zmienić swoich czynów, aby się nawrócić do swego Boga, dlatego że duch nierządu jest wśród nich i nie poznali Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 5, 'Pycha Izraela świadczy przeciwko niemu. Dlatego Izrael i Efraim upadną z powodu swojej nieprawości, upadnie wraz z nimi też Juda.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 6, 'Ze swoimi trzodami i swoim bydłem pójdą szukać Pana, ale go nie znajdą, bo odstąpił od nich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 7, 'Sprzeniewierzyli się Panu, bo napłodzili obcych synów, a teraz miesiąc pożre ich wraz z ich dziedzictwami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 8, 'Zadmijcie w trąbę w Gibea i w trąbę w Rama; krzyczcie w Bet-Awen: Wróg za tobą, Beniaminie!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 9, 'Efraim będzie spustoszony w dniu kary. Oznajmiłem wśród pokoleń Izraela to, co pewne.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 10, 'Książęta Judy stali się jak ci, którzy przesuwają granice. Wyleję na nich swój gniew jak wodę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 11, 'Efraim jest uciskany i pokruszony sądem, gdyż chętnie chodził za rozkazem ludzkim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 12, 'Dlatego będę dla Efraima jak mól, a dla domu Judy jak próchnica.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 13, 'Gdy Efraim zauważył swoją chorobę, a Juda swoją ranę, uciekł Efraim do Asyryjczyka i posłał do króla Jareb. Ale on was nie będzie mógł uzdrowić ani uleczyć waszej rany.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 14, 'Będę bowiem dla Efraima jak srogi lew, a dla domu Judy jak młody lew. Ja, ja sam porwę i odejdę; wezmę, a nikt mi go nie wydrze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 15, 'Pójdę i wrócę do swego miejsca, aż uznają swoją winę i zaczną szukać mojego oblicza. W swoim utrapieniu będą mnie pilnie szukać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 1, 'Chodźcie i zawróćmy do Pana, bo on nas poszarpał i on nas uzdrowi; uderzył, a opatrzy nasze rany.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 2, 'Ożywi nas po dwóch dniach, a trzeciego dnia wzbudzi nas i będziemy żyć przed jego obliczem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 3, 'Wtedy poznamy i będziemy się starać poznać Pana. Jego wyjście bowiem jest przygotowane jak zorza poranna, przyjdzie do nas jak deszcz wiosenny i jesienny, który nawadnia ziemię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 4, 'Cóż mam ci uczynić, Efraimie? Cóż mam ci uczynić, Judo? Wasza dobroć bowiem jest jak obłok poranny, jak rosa, która rano znika.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 5, 'Dlatego ciosałem ich przez proroków, zabijałem ich słowami moich ust, aby wyszła światłość twoich sądów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 6, 'Pragnę bowiem miłosierdzia, a nie ofiary, i poznania Boga bardziej niż całopalenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 7, 'Ale oni zerwali moje przymierze jako ludzkie, w tym mi się sprzeniewierzyli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 8, 'Gilead jest miastem czyniących nieprawość, splamionym krwią.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 9, 'A jak zbójcy czyhają na człowieka, tak czyni zgraja kapłanów na drodze do Sychem, bo popełniają czyny wstydliwe.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 10, 'Widziałem w domu Izraela rzeczy okropne: tam jest nierząd Efraima, a Izrael się splugawił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 11, 'I dla ciebie, Judo, wyznaczył żniwo, gdy odwróciłem niewolę mojego ludu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 1, 'Gdy leczyłem Izraela, wtedy odkryła się nieprawość Efraima i niegodziwość Samarii, bo postępują kłamliwie; złodziej włamuje się do środka, rozbójnicy rabują na zewnątrz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 2, 'A nie myślą w swoim sercu, że pamiętam o całej ich niegodziwości; a teraz ich czyny osaczają ich i są przed moim obliczem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 3, 'Króla rozweselają swoją niegodziwością, a książąt swymi kłamstwami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 4, 'Wszyscy cudzołożą, są jak piec rozpalony od piekarza, który przestaje czuwać, gdy zaczynił ciasto, aż się zakwasi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 5, 'W dniu naszego króla książęta wprawili go w chorobę bukłakami wina, tak że wyciągał swoją rękę wraz z szydercami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 6, 'Bo przygotowali swe serce do zasadzek jak rozpalony piec. Ich piekarz śpi całą noc, a rano płonie jak płomień ognia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 7, 'Wszyscy są rozpaleni jak piec i pożerają swoich sędziów; wszyscy ich królowie upadli. Nie ma wśród nich nikogo, kto by wołał do mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 8, 'Efraim zmieszał się z narodami; Efraim jest jak podpłomyk nieodwrócony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 9, 'Obcy pochłonęli jego siłę, a on o tym nie wie; siwizna przyprószyła mu włosy, ale on tego nie dostrzega.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 10, 'I choć pycha Izraela świadczy przeciwko niemu, to nie nawracają się do Pana, swego Boga, ani go w tym wszystkim nie szukają.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 11, 'Efraim stał się jak głupia gołębica bez serca. Przyzywają Egipt, uciekają do Asyrii.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 12, 'Gdy odejdą, rozciągnę na nich swoją sieć, ściągnę ich jak ptactwo niebieskie; ukarzę ich, jak im mówiono o tym w ich zgromadzeniu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 13, 'Biada im, bo uciekli ode mnie! Niech spadnie na nich spustoszenie, gdyż wystąpili przeciwko mnie. Chociaż ich odkupiłem, oni mówili kłamstwa przeciwko mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 14, 'I nie wołają do mnie ze swego serca, gdy wyją na swoich łożach. Wprawdzie dla zboża i moszczu gromadzą się, ale ode mnie odstępują.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 15, 'Choć opatrzyłem i wzmocniłem ich ramiona, oni obmyślają zło przeciwko mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 16, 'Zawracają, ale nie do Najwyższego. Są jak łuk zawodny; ich książęta polegną od miecza z powodu zapalczywości swego języka. To wystawi ich na pośmiewisko w ziemi Egiptu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 1, 'Przyłóż trąbę do ust i mów: Oto przyleci na dom Pana jak orzeł, gdyż złamali moje przymierze i przekroczyli moje Prawo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 2, 'Izrael będzie wołać do mnie: Mój Boże, znamy cię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 3, 'Ale Izrael odrzucił dobro. Wróg będzie go ścigać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 4, 'Oni ustanawiają królów, ale beze mnie; wybierają książąt, lecz bez mojej wiedzy. Ze swego srebra i złota czynią sobie bożki na własną zgubę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 5, 'Twój cielec cię odrzucił, Samario! Mój gniew zapłonął przeciwko nim. Jak długo jeszcze nie będą oczyszczeni?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 6, 'On bowiem jest z Izraela, rzemieślnik go wykonał, nie jest więc Bogiem. Cielec Samarii obróci się w proch.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 7, 'Oni bowiem posiali wiatr, będą zbierać wicher. Nie ma żadnego źdźbła. Kłos nie wyda mąki, a choćby wydał, obcy ją zjedzą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 8, 'Izrael będzie pożarty, wkrótce staną się wśród pogan jak naczynie, z którego nie ma żadnej pociechy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 9, 'Uciekli bowiem do Asyrii jak dziki samotny osioł. Efraim najął sobie kochanków.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 10, 'A chociaż najęli spośród narodów, ja ich wkrótce zbiorę i ucierpią nieco z powodu brzemienia króla książąt.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 11, 'Ponieważ Efraim pomnożył ołtarze, by grzeszyć, te ołtarze staną się dla niego powodem grzechu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 12, 'Wypisałem mu wielkie rzeczy z mojego Prawa, ale on je uważał za coś obcego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 13, 'Z ofiar moich darów składają w ofierze mięso i jedzą je, ale Pan tego nie przyjmuje. Już wspomina ich nieprawość i ukarze ich za grzechy. Powrócą do Egiptu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 14, 'Zapomniał Izrael o swoim Stwórcy i pobudował świątynie, a Juda rozmnożył miasta warowne. Ale ja poślę ogień na jego miasta, który pożre jego pałace.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 1, 'Nie ciesz się, Izraelu, nie raduj się jak inne narody, bo uprawiałeś nierząd, odwracając się od swego Boga, i umiłowałeś zapłatę nierządnicy na wszystkich klepiskach zbożowych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 2, 'Klepisko i prasa nie będą ich żywiły, a moszczu im zabraknie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 3, 'Nie będą mieszkać w ziemi Pana, ale Efraim wróci do Egiptu i w Asyrii będą jedli nieczyste rzeczy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 4, 'Nie będą wylewali Panu ofiar z wina, nie będą mu one przyjemne. Ich ofiary będą dla nich jak chleb żałoby; wszyscy, którzy będą z niego jedli, będą nieczyści. Ich chleb bowiem za ich dusze nie wejdzie do domu Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 5, 'Cóż będziecie czynić w uroczysty dzień i w dzień święta Pana?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 6, 'Oto bowiem poszli z powodu spustoszenia. Egipt ich zgromadzi, a Memfis ich pogrzebie. Przyjemne miejsca na ich srebro odziedziczy pokrzywa, a w ich namiotach wyrosną ciernie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 7, 'Przyjdą dni nawiedzenia, przyjdą dni zapłaty. Izrael pozna, że prorok jest głupcem, a człowiek duchowy – szalony, z powodu twojej wielkiej nieprawości i wielkiej nienawiści.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 8, 'Prorok, który trzymał straż nad Efraimem razem z moim Bogiem, stał się sidłem ptasznika na wszystkich jego drogach; nienawiść jest w domu jego Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 9, 'Zepsuli się do głębi, jak za dni Gibea. Pan będzie pamiętał o ich nieprawości i ukarze ich za grzechy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 10, 'Znalazłem Izraela jak winne grona na pustyni, widziałem twoich ojców jak pierwszy owoc figowca na jego początku. Ale oni poszli do Baal-Peor i oddali się tej hańbie, i stali się obrzydliwi, tak jak się im upodobało.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 11, 'Jak ptak sława Efraima uleci zaraz od urodzenia, od łona i od poczęcia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 12, 'A choćby odchowali swoich synów, osierocę ich, zanim osiągną wiek męski. Owszem, biada im, gdy ja od nich odstąpię!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 13, 'Efraim, jak widzę, jest jak Tyr zasadzony na przyjemnym miejscu. Efraim jednak wyprowadzi swoich synów do mordercy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 14, 'Daj im, Panie! Cóż im dasz? Daj im łono bezpłodne i wyschnięte piersi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 15, 'Cała ich niegodziwość jest w Gilgal, dlatego tam ich nienawidzę. Z powodu zła ich uczynków wyrzucę ich z mego domu, nie będę ich już miłował. Wszyscy ich książęta są buntownikami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 16, 'Efraim jest powalony, ich korzeń wysechł, nie przynoszą owocu. A choćby też zrodzili, zabiję umiłowane dzieci ich łona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 17, 'Mój Bóg ich odrzuci, bo nie chcieli go słuchać, a będą tułaczami wśród narodów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 1, 'Izrael jest próżną winoroślą, sam sobie przynosi owoc. Im więcej miał owocu, tym więcej pobudował ołtarzy, a im obfitsza była jego ziemia, tym piękniejsze wystawiał posągi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 2, 'Ich serce jest rozdzielone, teraz są winni. On pokruszy ich ołtarze i zniszczy ich posągi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 3, 'Mówią bowiem: Nie mamy króla, bo nie baliśmy się Pana, a cóż może dla nas uczynić król?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 4, 'Wypowiadają słowa, przysięgając kłamliwie, gdy zawierają przymierze. Sąd wzrośnie jak trujący chwast w bruzdach polnych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 5, 'Mieszkańcy Samarii zatrwożą się z powodu cielców Bet-Awen. Będą go bowiem opłakiwać jego lud oraz jego kapłani, którzy się radowali z niego, gdyż jego chwała odeszła od niego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 6, 'Nawet i on sam zostanie zaprowadzony do Asyrii jako dar dla króla Jareb. Efraim okryje się hańbą i Izrael zawstydzi się z powodu swojej rady.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 7, 'Król Samarii zostanie wycięty jak piana na powierzchni wody.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 8, 'Wyżyny Awen, grzech Izraela, zostaną zniszczone. Ciernie i oset wyrosną na ich ołtarzach, a powiedzą do gór: Przykryjcie nas; a do pagórków: Padnijcie na nas.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 9, 'Od dni Gibea grzeszysz, Izraelu. Tam się ostali. Nie pochwyciła ich w Gibea bitwa przeciwko synom nieprawości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 10, 'Ukarzę ich według mego upodobania; narody zbiorą się przeciwko nim, aby zostali ukarani za swoje dwie nieprawości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 11, 'Efraim jest jak wyćwiczona jałówka, która lubi młócić. Lecz ja nadepnąłem na jej cudny kark, aby użyć Efraima do jazdy; Juda będzie orać, a Jakub będzie bronować.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 12, 'Siejcie sobie w sprawiedliwości, żnijcie w miłosierdziu, orzcie swoje ugory. Czas bowiem szukać Pana, aż przyjdzie i spuści na was sprawiedliwość jak deszcz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 13, 'Ale oraliście niegodziwość, zbieraliście nieprawość i jedliście owoc kłamstwa. Zaufałeś bowiem swej drodze i wielkiej liczbie swoich wojowników.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 14, 'Dlatego powstanie zgiełk pośród twego ludu i wszystkie twoje zamki zostaną zburzone, tak jak Szalman zburzył Bet-Arbel w dniu bitwy, gdy matki z synami zostały roztrzaskane.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 15, 'Oto tak wam uczyni Betel z powodu waszej wielkiej niegodziwości. Król Izraela o świcie zostanie doszczętnie zgładzony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 1, 'Gdy Izrael był dzieckiem, umiłowałem go, a z Egiptu wezwałem mego syna.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 2, 'Prorocy wzywali ich, ale oni tym bardziej odchodzili sprzed ich oblicza. Składali ofiary Baalom i palili kadzidło rzeźbionym bożkom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 3, 'Postawiłem Efraima na nogi, biorąc ich na ramiona, ale nie chcieli poznać, że ja ich wyleczyłem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 4, 'Ciągnąłem ich powrozami ludzkimi, więzami miłości, a byłem dla nich jak ci, którzy zdejmują jarzmo z ich szczęk, i podawałem im pokarm.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 5, 'Nie wróci on do ziemi Egiptu, ale Asyryjczyk będzie jego królem, gdyż nie chcieli się nawrócić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 6, 'Ponadto miecz będzie trwać w jego miastach, zniszczy jego gałęzie i pożre je z powodu ich rad.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 7, 'Mój lud jest skłonny do odstępowania ode mnie, a chociaż wezwano go do Najwyższego, nikt go nie wywyższa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 8, 'Jakże mógłbym cię porzucić, Efraimie? Jakże mógłbym cię wydać, Izraelu? Jakże mógłbym cię równać z Admą i postąpić z tobą jak z Seboim? Moje serce odmieniło się we mnie, moja litość poruszyła się.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 9, 'Nie wykonam zapalczywości swojego gniewu i nie zniszczę Efraima ponownie, bo jestem Bogiem, a nie człowiekiem; Święty pośród ciebie. I nie nadciągnę przeciwko miastu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 10, 'Pójdą za Panem, który jak lew będzie ryczał. Gdy zaryczy, synowie z drżeniem przybiegną z zachodu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 11, 'Przybiegną z drżeniem jak ptaki z Egiptu i jak gołębica z ziemi Asyrii i posadzę ich w ich domach, mówi Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 12, 'Efraim otoczył mnie kłamstwem, a dom Izraela – zdradą, gdy Juda jeszcze panuje z Bogiem i jest wierny ze świętymi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 1, 'Efraim karmi się wiatrem, goni za wiatrem wschodnim. Przez cały dzień mnoży kłamstwo i spustoszenie, bo zawiera przymierze z Asyryjczykami i wynosi oliwę do Egiptu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 2, 'Pan wiedzie też spór z Judą i ukarze Jakuba według jego dróg, odda mu według jego czynów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 3, 'Jeszcze w łonie ujął on za piętę swego brata, a swoją siłą mężnie zmagał się z Bogiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 4, 'Mężnie zmagał się z Aniołem i go przemógł. Płakał i go prosił. Znalazł go w Betel i tam z nami rozmawiał;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 5, 'To jest Pan, Bóg zastępów, Pan to jego pamiętne imię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 6, 'Ty więc nawróć się do swego Boga, przestrzegaj miłosierdzia i sądu i oczekuj swego Boga nieustannie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 7, 'Jest kupcem, w jego ręce jest fałszywa waga, lubi uciskać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 8, 'I Efraim powiedział: Ale wzbogaciłem się, zdobyłem dla siebie bogactwo. We wszystkich moich trudach nie znajdą przy mnie nieprawości, co byłoby grzechem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 9, 'Jednak ja jestem Pan, twój Bóg, od wyjścia z ziemi Egiptu. Jeszcze sprawię, że będziecie mieszkać w namiotach, jak za dni uroczystych świąt.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 10, 'Mówiłem przez proroków, mnożyłem widzenia i przez proroków podawałem przypowieści.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 11, 'Czy tylko w Gileadzie była nieprawość i marność? I w Gilgal składają ofiary z wołów, owszem, ich ołtarzów pełno jak stosów kamieni w bruzdach na polach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 12, 'Tam uciekł Jakub do ziemi Syrii, gdzie Izrael służył za żonę i za żonę strzegł stada.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 13, 'Ale Pan przez proroka wyprowadził Izraela z Egiptu i przez proroka był strzeżony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 14, 'Lecz Efraim pobudził Pana do gorzkiego gniewu. Dlatego na niego wyleje się jego krew i jego Pan odpłaci mu za jego zniewagę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 1, 'Gdy Efraim przemawiał, panował strach, bo był wywyższony w Izraelu; ale gdy zgrzeszył przy Baalu, wtedy umarł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 2, 'A teraz dodają do swego grzechu, bo czynią sobie odlane posągi ze swego srebra i straszne bożki według swego pomysłu, a to wszystko jest dziełem rzemieślnika; jednak sami o nich mówią: Ludzie, którzy składają ofiary, niech całują cielce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 3, 'Dlatego staną się jak obłok poranny, jak przemijająca rosa poranna, jak plewy przez wicher porwane z klepiska i jak dym z komina.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 4, 'Ale ja jestem Pan, twój Bóg, od wyjścia z ziemi Egiptu, a nie będziesz znał innego Boga oprócz mnie. I nie ma innego zbawiciela oprócz mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 5, 'Ja cię poznałem na pustyni, w ziemi bardzo suchej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 6, 'Byli nasyceni dobrymi pastwiskami, ale gdy się nasycili, ich serce się wywyższyło; dlatego zapomnieli o mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 7, 'Będę więc dla nich jak lew, jak lampart przy drodze będę czyhał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 8, 'Napadnę na nich jak niedźwiedzica, której zabrano młode, rozerwę powłokę ich serca i pożrę ich tam jak lew, dziki zwierz ich rozszarpie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 9, 'Zniszczyłeś się sam, Izraelu, ale we mnie jest twoja pomoc.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 10, 'Ja jestem twoim królem. Gdzież jest ten, który ma cię wybawić we wszystkich twoich miastach? I twoi sędziowie, o których mówiłeś: Daj mi króla i książąt.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 11, 'Dałem ci więc króla w swoim gniewie i odebrałem go w swojej zapalczywości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 12, 'Nieprawość Efraima jest związana, jego grzech jest ukryty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 13, 'Ogarną go bóle rodzącej. On jest niemądrym synem, bo inaczej nie zostałby tak długo w łonie matki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 14, 'Wybawię ich z mocy grobu, wykupię ich od śmierci. O śmierci, będę twoją śmiercią! O grobie, będę twoim zniszczeniem! Żal się ukryje przed moimi oczami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 15, 'Choćby on wśród braci przyniósł owoc, przyjdzie jednak wiatr ze wschodu, wiatr Pana wyruszy z pustyni i wysuszy jego źródło, i wysuszy jego zdrój. On zagarnie skarby wszelkich kosztownych naczyń.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 16, 'Samaria będzie spustoszona, ponieważ sprzeciwiła się swemu Bogu. Padną od miecza, jej niemowlęta będą roztrzaskane, a jej brzemienne będą rozprute.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 1, 'Izraelu, nawróć się całkowicie do Pana, swego Boga. Upadłeś bowiem z powodu swojej nieprawości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 2, 'Weźcie ze sobą słowa i zawróćcie do Pana. Mówcie do niego: Przebacz całą naszą nieprawość i daj to, co dobre, wtedy oddamy ci cielce naszych warg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 3, 'Asyria nas nie wybawi, nie będziemy jeździć na koniach i nie będziemy już mówili do dzieł naszych rąk: Wy jesteście naszymi bogami. W tobie bowiem sierota znajduje miłosierdzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 4, 'Uzdrowię ich odstępstwo i umiłuję ich dobrowolnie, bo mój gniew odwrócił się od nich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 5, 'Będę dla Izraela jak rosa, tak że rozkwitnie jak lilia i zapuści korzenie jak Liban.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 6, 'Jego gałęzie rozrosną się i jego piękno będzie jak drzewo oliwne, a jego woń jak Liban.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 7, 'Wrócą, aby siedzieć pod jego cieniem, ożyją jak zboże i rozkwitną jak winorośl, ich sława będzie jak wino Libanu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 8, 'Efraim powie: Cóż mi już do bożków? Ja cię wysłucham i wejrzę na ciebie. Ja jestem jak zielona jodła, ode mnie pochodzi twój owoc.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 9, 'Kto mądry, niech to zrozumie, a kto roztropny, niech to pozna. Drogi Pana bowiem są proste; sprawiedliwi po nich będą chodzić, ale przestępcy na nich upadną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 1, 'Słowo Pana, które doszło do Joela, syna Petuela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 2, 'Słuchajcie tego, starcy, nakłońcie ucha wszyscy mieszkańcy tej ziemi. Czy zdarzyło się coś podobnego za waszych dni albo za dni waszych ojców?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 3, 'Opowiadajcie o tym swoim synom, a wasi synowie niech opowiedzą swoim synom, a ich synowie przyszłemu pokoleniu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 4, 'Co zostało po gąsienicy, zjadła szarańcza, co zostało po szarańczy, zjadła larwa, a co zostało po larwie, zjadło robactwo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 5, 'Ocknijcie się, pijani, i płaczcie; wszyscy, którzy pijecie wino, zawódźcie z powodu moszczu, bo został odjęty od waszych ust.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 6, 'Nadciągnął bowiem naród do mojej ziemi, mocny i niezliczony, jego zęby to zęby lwa, a zęby trzonowe ma jak srogi lew.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 7, 'Spustoszył moją winorośl i połupał moje drzewo figowe. Odarł je doszczętnie i porzucił tak, że zbielały jego gałęzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 8, 'Lamentuj jak dziewica przepasana worem nad mężem swojej młodości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 9, 'Odjęto ofiarę z pokarmów i z płynów od domu Pana; płaczą kapłani, słudzy Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 10, 'Pole zostało spustoszone i ziemia się smuci, ponieważ zniszczono zboże. Wysechł moszcz, zginęła oliwa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 11, 'Zawstydźcie się, rolnicy; zawódźcie winogrodnicy z powodu pszenicy i jęczmienia, bo przepadło żniwo polne.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 12, 'Uschła winorośl i zwiędło drzewo figowe; drzewo granatowe, palma, jabłoń i wszystkie drzewa polne uschły, bo radość znikła spośród synów ludzkich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 13, 'Przepaszcie się i płaczcie, kapłani. Zawódźcie, słudzy ołtarza. Przyjdźcie i nocujcie w worach, słudzy mojego Boga, bo zabrakło ofiar z pokarmów i płynów w domu waszego Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 14, 'Ogłoście święty post, zwołajcie zgromadzenie, zbierzcie starców i wszystkich mieszkańców ziemi w domu Pana, waszego Boga, i wołajcie do Pana:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 15, 'Ach, co to za dzień! Bliski bowiem jest dzień Pana i nadejdzie jak spustoszenie od Wszechmocnego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 16, 'Czyż na naszych oczach nie zginęła żywność, a z domu naszego Boga – radość i wesele?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 17, 'Zgniły ziarna pod swymi skibami, spustoszone są spichlerze, zburzone stodoły, bo uschło zboże.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 18, 'Jakże ryczy bydło? Błąkają się stada wołów, bo nie mają pastwisk, nawet i trzody owiec wyginęły.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 19, 'Do ciebie wołam, Panie, bo ogień pożarł pastwiska na pustyni, a płomień spalił wszystkie drzewa polne;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 20, 'Także i zwierzęta polne ryczą do ciebie, ponieważ wyschły strumienie wód, a ogień pożarł pastwiska na pustyni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 1, 'Zadmijcie w trąbę na Syjonie, krzyczcie na mojej świętej górze! Niech zadrżą wszyscy mieszkańcy ziemi, bo nadchodzi dzień Pana, bo już jest bliski;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 2, 'Dzień ciemności i mroku, dzień obłoku i chmury, jak zorza ranna rozciągnięta po górach. Lud wielki i potężny, któremu równego nie było od wieków i po nim nigdy nie będzie aż do lat najdalszych pokoleń.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 3, 'Przed jego obliczem ogień pożerający, a za nim płomień palący. Ta ziemia jest przed nim jak ogród Eden, ale po nim będzie opustoszałe pustkowie – przed nim nie ujdzie nikt.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 4, 'Ich wygląd jest podobny do wyglądu koni i pobiegną jak jeźdźcy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 5, 'Po wierzchołkach gór będą skakać jak grzmot rydwanów, jak szum płomienia ognia, co pożera ściernisko, jak lud potężny uszykowany do bitwy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 6, 'Na ich widok narody się zlękną, wszystkie ich twarze poczernieją jak garnek.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 7, 'Pobiegną jak wojownicy, wedrą się na mury jak waleczni wojownicy; każdy z nich pójdzie swoją drogą, a nie zboczą ze swoich ścieżek.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 8, 'Jeden drugiego nie ściśnie, każdy pójdzie swoją drogą. A choć i na miecz upadną, nie będą zranieni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 9, 'Po mieście będą chodzić, po murze będą biegać, wdrapią się na domy i wejdą oknami jak złodziej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 10, 'Przed nimi zadrży ziemia, niebiosa się poruszą, słońce i księżyc będą zaćmione, a gwiazdy stracą swój blask.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 11, 'A Pan wyda swój głos przed swoim wojskiem, gdyż jego obóz jest ogromny, gdyż mocny jest ten, który wykonuje jego słowo. Wielki jest bowiem dzień Pana i bardzo straszliwy! Któż go zniesie?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 12, 'Dlatego jeszcze i teraz, mówi Pan, wróćcie do mnie całym swym sercem, w poście, płaczu i w lamencie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 13, 'Rozdzierajcie swoje serca, a nie swoje szaty, i nawróćcie się do Pana, waszego Boga, bo on jest łaskawy i miłosierny, nieskory do gniewu i hojny w miłosierdzie i żałuje nieszczęścia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 14, 'Któż wie, czy nie zawróci i nie będzie mu żal, i nie zostawi po sobie błogosławieństwa na ofiarę z pokarmów i z płynów dla Pana, swego Boga?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 15, 'Zadmijcie w trąbę na Syjonie, ogłoście święty post, zwołajcie zgromadzenie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 16, 'Zgromadźcie lud, poświęćcie zgromadzenie, zbierzcie starców, zbierzcie dzieci i niemowlęta ssące piersi. Niech oblubieniec wyjdzie ze swojej izby, a oblubienica ze swojej komnaty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 17, 'Niech kapłani, słudzy Pana, płaczą między przedsionkiem a ołtarzem i niech mówią: Przepuść, Panie, swemu ludowi i nie wydawaj swego dziedzictwa na pohańbienie, aby poganie nad nimi nie panowali. Czemu mieliby mówić wśród narodów: Gdzie jest ich Bóg?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 18, 'Wtedy Pan będzie zazdrosny o swoją ziemię i zlituje się nad swoim ludem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 19, 'I Pan odezwie się, i powie do swego ludu: Oto ześlę wam zboże, moszcz i oliwę i nasycicie się nimi, a już nie wydam was na pohańbienie pośród pogan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 20, 'Oddalę od was północne wojsko i zapędzę je do ziemi suchej i spustoszonej. Przednia jego straż obróci się ku morzu wschodniemu, a jego tylna straż – ku morzu zachodniemu; i rozejdzie się jego smród i zgnilizna, bo postępował wyniośle.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 21, 'Nie bój się, ziemio! Ciesz się i raduj, bo Pan uczyni wielkie rzeczy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 22, 'Nie bójcie się, polne zwierzęta, bo zarosło pastwisko na pustyni, a drzewa wydają swoje owoce, drzewo figowe i winorośl wydają swoją moc.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 23, 'I wy, synowie Syjonu, cieszcie się i radujcie w Panu, waszym Bogu. Da wam bowiem deszcz wczesny i ześle wam deszcz jesienny i wiosenny, jak dawniej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 24, 'I spichlerze będą napełnione zbożem, a tłocznie będą opływać moszczem i oliwą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 25, 'W ten sposób wynagrodzę wam lata zjedzone przez szarańczę, larwę, robactwo i gąsienicę, moje wielkie wojsko, które wysyłałem na was.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 26, 'Wtedy będziecie jeść obficie i będziecie nasyceni; będziecie chwalić imię Pana, swego Boga, który uczynił wam cudowne rzeczy, a mój lud nigdy nie będzie pohańbiony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 27, 'I dowiecie się, że ja jestem wśród Izraela, że ja jestem Pan, wasz Bóg, i że nie ma żadnego innego; a mój lud nigdy nie będzie pohańbiony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 28, 'I stanie się potem, że wyleję swojego Ducha na wszelkie ciało, i będą prorokować wasi synowie i wasze córki, wasi starcy będą mieć sny, a wasi młodzieńcy – widzenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 29, 'Nawet na sługi i służebnice wyleję w tych dniach swojego Ducha.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 30, 'I ukażę cuda na niebie i na ziemi, krew, ogień i kłęby dymu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 31, 'Słońce zamieni się w ciemność, a księżyc w krew, zanim nadejdzie dzień Pana, wielki i straszny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 32, 'I stanie się, że każdy, kto wezwie imienia Pana, zostanie wybawiony, bo na górze Syjon i w Jerozolimie będzie wybawienie, jak powiedział Pan, to jest w resztkach, które Pan powoła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 1, 'Oto bowiem w tych dniach i w tym czasie, gdy odwrócę niewolę ludu Judy i Jerozolimy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 2, 'Zgromadzę też wszystkie narody i sprowadzę je do Doliny Jehoszafata, i będę tam z nimi rozprawiał o swoim ludzie i o swoim dziedzictwie Izraela, które rozproszyły wśród narodów i podzieliły moją ziemię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 3, 'O mój lud rzucały los, dawały chłopca za nierządnicę i dziewczynę sprzedawały za wino, aby piły.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 4, 'Ale wy cóż macie przeciwko mnie, Tyrze i Sydonie, oraz wszystkie granice filistyńskie? Czy chcecie dać mi odpłatę? Jeśli mi odpłacicie, to prędko i niezwłocznie i ja zwrócę waszą odpłatę na waszą głowę;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 5, 'Gdyż zabraliście moje srebro i złoto, a moje wspaniałe klejnoty wnieśliście do swoich świątyń;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 6, 'A synów Judy i synów Jerozolimy sprzedaliście Grekom, by ich oddalić od ich granic.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 7, 'Oto wzbudzę ich z tego miejsca, do którego ich sprzedaliście, i zwrócę waszą zapłatę na waszą głowę;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 8, 'I sprzedam waszych synów i wasze córki w ręce synów Judy, a oni sprzedadzą ich Sabejczykom, narodowi dalekiemu. Tak bowiem Pan powiedział.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 9, 'Rozgłoście to wśród pogan, ogłoście wojnę, pobudźcie wojowników, niech przybędą i niech wyruszą wszyscy mężowie waleczni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 10, 'Przekujcie wasze lemiesze na miecze, a wasze sierpy na oszczepy; kto słaby, niech powie: Jestem silny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 11, 'Zgromadźcie się i przyjdźcie, wszystkie okoliczne narody – zbierzcie się. Sprowadź tam, Panie, swoich wojowników.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 12, 'Niech poganie się ockną i nadciągną na Dolinę Jehoszafata. Tam bowiem zasiądę, aby sądzić wszystkie okoliczne narody.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 13, 'Zapuśćcie sierp, bo dojrzało żniwo. Pójdźcie i zstąpcie, bo tłocznia jest pełna, kadzie przelewają się, bo ich zło jest wielkie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 14, 'Tłumy, tłumy w dolinie wyroku. Bliski bowiem jest dzień Pana w dolinie wyroku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 15, 'Słońce i księżyc się zaćmią i gwiazdy stracą swój blask.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 16, 'I Pan zagrzmi z Syjonu, a z Jerozolimy wyda swój głos, tak że zadrżą niebiosa i ziemia. Ale Pan będzie ucieczką dla swego ludu i siłą synów Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 17, 'I poznacie, że ja jestem Panem, waszym Bogiem, który mieszka na Syjonie, mojej świętej górze. I Jerozolima stanie się święta, a obcy już nie będą przez nią przechodzić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 18, 'I stanie się w tym dniu, że góry będą kropić moszczem, pagórki opływać mlekiem i wszystkie strumienie Judy napełnią się wodą, a z domu Pana wyjdzie źródło, które nawodni dolinę Sittim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 19, 'Egipt zostanie spustoszony, a ziemia Edom zamieni się w opustoszałe pustkowie z powodu przemocy wyrządzonej synom Judy, bo przelewali niewinną krew w ich ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 20, 'Ale Juda będzie trwać na wieki, a Jerozolima – z pokolenia na pokolenie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 21, 'I oczyszczę tych, których krwi nie oczyściłem. Pan bowiem mieszka na Syjonie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 1, 'Słowa Amosa, który był jednym spośród pasterzy z Tekoa, które widział o Izraelu za dni Uzjasza, króla Judy, i za dni Jeroboama, syna Joasza, króla Izraela, dwa lata przed trzęsieniem ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 2, 'I powiedział: Pan zagrzmi z Syjonu, z Jerozolimy wyda swój głos; mieszkania pasterzy będą lamentować, a wyschnie szczyt Karmelu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 3, 'Tak mówi Pan: Z powodu trzech występków Damaszku i z powodu czterech nie przepuszczę mu, ponieważ młócili Gilead narzędziami z żelaza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 4, 'Ale ześlę ogień na dom Chazaela, który strawi pałace Ben-Hadada.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 5, 'Połamię też rygiel Damaszku i wykorzenię mieszkańca z doliny Awen i tego, który trzyma berło z domu Eden. I lud Syrii pójdzie do niewoli do Kir, mówi Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 6, 'Tak mówi Pan: Z powodu trzech występków Gazy i z powodu czterech nie przepuszczę im, ponieważ uprowadzili wszystkich jeńców, aby ich wydać Edomowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 7, 'Ale ześlę ogień na mur Gazy, który strawi jej pałace.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 8, 'Wykorzenię też mieszkańca z Aszdodu i tego, który trzyma berło z Aszkelonu, i zwrócę swoją rękę przeciwko Ekronowi, i zginie resztka Filistynów, mówi Pan Bóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 9, 'Tak mówi Pan: Z powodu trzech występków Tyru i z powodu czterech nie przepuszczę mu, ponieważ wydali wszystkich jeńców Edomowi, a nie pamiętali o braterskim przymierzu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 10, 'Ale ześlę ogień na mur Tyru, który strawi jego pałace.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 11, 'Tak mówi Pan: Z powodu trzech występków Edomu i z powodu czterech nie przepuszczę mu, ponieważ prześladował mieczem swego brata, tłumiąc w sobie wszelaką litość, a nieustannie pałał gniewem, swoją zapalczywość chował na zawsze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 12, 'Ale ześlę ogień na Teman i strawi pałace Bosry.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 13, 'Tak mówi Pan: Z powodu trzech występków synów Ammona i z powodu czterech nie przepuszczę im, ponieważ rozcinali brzemienne w Gileadzie tylko po to, by rozszerzyć swoje granice.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 14, 'Ale rozniecę ogień na murze Rabby, który strawi jego pałace wśród krzyku w dzień bitwy, podczas wichru w dzień burzy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 15, 'I pójdzie ich król do niewoli, on i jego książęta razem z nim, mówi Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 1, 'Tak mówi Pan: Z powodu trzech występków Moabu i z powodu czterech nie przepuszczę mu, ponieważ spalił kości króla Edomu na wapno.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 2, 'Ale ześlę ogień na Moab, który strawi pałace Keriotu. I umrze Moab wśród wrzawy, wśród krzyku i przy dźwięku trąby.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 3, 'I wytracę sędziów spośród niego, i zabiję wraz z nim wszystkich jego książąt, mówi Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 4, 'Tak mówi Pan: Z powodu trzech występków Judy i z powodu czterech nie przepuszczę mu, ponieważ odrzucili prawo Pana i nie przestrzegali jego przykazań, a dali się zwieść swoim kłamstwom, za którymi chodzili ich ojcowie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 5, 'Ale ześlę ogień na Judę, który strawi pałace Jerozolimy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 6, 'Tak mówi Pan: Z powodu trzech występków Izraela i z powodu czterech nie przepuszczę mu, ponieważ sprzedali sprawiedliwego za srebro, a ubogiego za parę sandałów;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 7, 'Którzy dążą do tego, aby w prochu deptać głowy ubogich i drogę pokornych wypaczają. Ponadto syn i jego ojciec obcują z tą samą dziewczyną, aby splamić moje święte imię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 8, 'I na szatach danych im w zastaw kładą się przy każdym ołtarzu, a wino ukaranych piją w domu swoich bogów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 9, 'A przecież wytraciłem przed nimi Amorytę, który był wysoki jak cedry, a mocny jak dęby. Zniszczyłem jednak jego owoc od góry, a z dołu jego korzenie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 10, 'A was wyprowadziłem z ziemi Egiptu i prowadziłem przez pustynię czterdzieści lat, abyście posiedli ziemię Amoryty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 11, 'I wzbudzałem spośród waszych synów proroków i spośród waszych młodzieńców nazirejczyków. Czy nie jest tak, synowie Izraela? – mówi Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 12, 'Ale wy poiliście nazirejczyków winem, a prorokom rozkazywaliście, mówiąc: Nie prorokujcie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 13, 'Oto ścisnę waszą ziemię, tak jak ciśnie wóz pełen snopów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 14, 'Szybkiemu nie uda się ucieczka, mocny nie doda sobie sił i mocarz nie wybawi swojej duszy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 15, 'A ten, który trzyma łuk, nie ostoi się, i szybki na nogach nie ucieknie, a jeździec na koniu nie zachowa swojej duszy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 16, 'A najodważniejszy spośród mocarzy ucieknie w tym dniu nagi, mówi Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 1, 'Słuchajcie tego słowa, które Pan mówi przeciwko wam, synowie Izraela, przeciwko całemu pokoleniu, które wyprowadziłem z ziemi Egiptu:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 2, 'Tylko was uznałem spośród wszystkich rodów ziemi, dlatego was ukarzę za wszystkie wasze nieprawości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 3, 'Czy dwóch może chodzić razem, jeśli się nie zgadzają?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 4, 'Czy lew zaryczy w lesie, gdy nie ma łupu? Czy młody lew wyda swój głos ze swojego legowiska, jeśli nic nie złowił?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 5, 'Czy ptak wpadnie w sidła na ziemi, jeśli nie ma pułapki? Czy podniesie się sidła z ziemi, jeśli nic nie schwytały?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 6, 'Czy trąba zadmie w mieście, a lud się nie ulęknie? Czy w mieście zdarzy się nieszczęście, którego Pan by nie uczynił?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 7, 'Doprawdy, Pan Bóg nic nie czyni, jeśli nie objawi swojej tajemnicy swym sługom, prorokom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 8, 'Lew ryknął, któż się nie ulęknie? Pan Bóg przemówił, któż nie będzie prorokował?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 9, 'Głoście w pałacach w Aszdodzie i w pałacach ziemi Egiptu i mówcie: Zbierzcie się na górach Samarii i zobaczcie w niej wielkie zamieszanie oraz cierpiących w niej ucisk;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 10, 'Nie umieją bowiem czynić tego, co jest prawe, mówi Pan. Zbierają w swoich pałacach skarby ze zdzierstwa i z grabieży.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 11, 'Dlatego tak mówi Pan Bóg: Wróg otoczy tę ziemię i pozbawi cię twojej siły, i twoje pałace zostaną ograbione.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 12, 'Tak mówi Pan: Jak pasterz wyrywa z lwiej paszczy dwie nogi lub kawałek ucha, tak zostaną wyrwani synowie Izraela, którzy mieszkają w Samarii na rogu łoża i w Damaszku na posłaniach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 13, 'Słuchajcie i oświadczcie w domu Jakuba, mówi Pan Bóg, Bóg zastępów;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 14, 'Bo w tym dniu, w którym ukarzę Izraela za jego przestępstwa, ukarzę też ołtarze w Betel. I rogi ołtarza zostaną odcięte i upadną na ziemię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 15, 'I zburzę dom zimowy i dom letni, zginą domy z kości słoniowej i dla wielkich domów nastanie koniec, mówi Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 1, 'Słuchajcie tego słowa, krowy Baszanu, które jesteście na górach Samarii, które uciskacie biednych i niszczycie ubogich, które mówicie ich panom: Przynieście, abyśmy mogli pić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 2, 'Przysiągł Pan Bóg na swoją świętość, że oto nadejdą na was dni, kiedy pochwyci was hakami, a wasze potomstwo wędkami rybackimi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 3, 'I wyjdziecie wyłomami, jedna za drugą, i będziecie rozrzucać wszystko, co jest w waszych pałacach, mówi Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 4, 'Przychodźcie do Betel i grzeszcie, w Gilgal rozmnóżcie przestępstwo; przynoście każdego ranka swoje ofiary, a trzeciego roku – swoje dziesięciny;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 5, 'I spalajcie kwaszoną ofiarę dziękczynną, ogłaszajcie i rozgłoście dobrowolne ofiary, ponieważ tak wam się podoba, synowie Izraela, mówi Pan Bóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 6, 'A chociaż dałem wam czystość zębów we wszystkich waszych miastach i niedostatek chleba po wszystkich waszych miejscach, wy jednak nie nawróciliście się do mnie, mówi Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 7, 'Ja też wstrzymałem wam deszcz, gdy jeszcze brakowało trzech miesięcy do żniwa. Spuszczałem deszcz na jedno miasto, a na drugie miasto nie spuszczałem. Jedną część pola zraszał deszcz, a druga część, na którą deszcz nie padał, uschła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 8, 'I chodzili z dwóch, trzech miast do jednego miasta, aby się napić, ale nie mogli zaspokoić swego pragnienia. A jednak nie nawróciliście się do mnie, mówi Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 9, 'Dotknąłem was suszą i pleśnią. Gdy obfitowały wasze ogrody, winnice, sady figowe i drzewa oliwne przynosiły owoc, gąsienice to pożarły, a jednak nie nawróciliście się do mnie, mówi Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 10, 'Zesłałem na was zarazę, tak jak na Egipt, wybiłem mieczem waszych młodzieńców, pozwoliłem uprowadzić wasze konie i sprawiłem, że smród waszych wojsk dotarł do waszych nozdrzy, a jednak nie nawróciliście się do mnie, mówi Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 11, 'Spustoszyłem was, jak Bóg spustoszył Sodomę i Gomorę, i staliście się jak głownia wyrwana z ognia, a jednak nie nawróciliście się do mnie, mówi Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 12, 'Dlatego tak ci uczynię, Izraelu, a ponieważ zamierzam ci tak uczynić, przygotuj się na spotkanie ze swym Bogiem, Izraelu!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 13, 'Oto bowiem on jest tym, który kształtuje góry, tworzy wiatr, oznajmia człowiekowi, jaka jest jego myśl; on z rannej zorzy czyni ciemność i stąpa po wyżynach ziemi. Pan, Bóg zastępów, to jego imię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 1, 'Słuchajcie tego słowa, które jako lament podnoszę przeciwko wam, domu Izraela!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 2, 'Upadła i już nie powstanie dziewica Izraela. Leży opuszczona w swej ziemi i nie ma nikogo, kto by ją podniósł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 3, 'Tak bowiem mówi Pan Bóg: W mieście, z którego wychodziło tysiąc, pozostanie sto, a w tym, z którego wychodziło sto, pozostanie domowi Izraela dziesięciu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 4, 'Tak bowiem mówi Pan do domu Izraela: Szukajcie mnie, a będziecie żyć;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 5, 'A nie szukajcie Betel, nie chodźcie do Gilgal i do Beer-Szeby nie udawajcie się, gdyż Gilgal zostanie uprowadzony do niewoli, a Betel wniwecz się obróci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 6, 'Szukajcie Pana, a będziecie żyć, aby nie wybuchł jak ogień w domu Józefa i nie pochłonął go, a nie będzie nikogo w Betel, kto by go ugasił;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 7, 'Wy, którzy zamieniacie sąd w piołun, a sprawiedliwość porzucacie na ziemi;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 8, 'Szukajcie tego, który uczynił Plejady i Oriona, który przemienia cień śmierci w poranek i dzień w ciemności nocne; który przyzywa wody morskie i wylewa je na powierzchni ziemi, Pan jest jego imię;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 9, 'Który wzmacnia słabego przeciwko mocnemu, tak że ten osłabiony naciera na twierdzę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 10, 'Nienawidzą tego, który upomina ich w bramie, i brzydzą się tym, który mówi prawdę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 11, 'Ponieważ uciskacie ubogiego i zabieracie mu ciężar zboża, to chociaż pobudowaliście domy z kamienia ciosanego, nie będziecie w nich mieszkać; zasadzaliście rozkoszne winnice, ale nie będziecie pić z nich wina.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 12, 'Znam bowiem wasze wielkie przestępstwa i ogromne grzechy: uciskacie sprawiedliwego, bierzecie łapówkę i wypaczacie sprawy ubogich w bramie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 13, 'Dlatego roztropny milczy w tym czasie, bo jest to czas zły.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 14, 'Szukajcie dobra, a nie zła, abyście żyli. A Pan, Bóg zastępów, będzie z wami, tak jak mówicie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 15, 'Nienawidźcie zła, a miłujcie dobro i ustanówcie sąd w bramie. Może wtedy Pan, Bóg zastępów, zlituje się nad resztką Józefa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 16, 'Dlatego tak mówi Pan, Bóg zastępów, Pan: Na wszystkich ulicach będzie zawodzenie, a na wszystkich drogach będą krzyczeć: Biada, biada! I zawołają oracza do płaczu, a tych, którzy umieją lamentować, do zawodzenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 17, 'I we wszystkich winnicach będzie zawodzenie, gdy przejdę pośród ciebie, mówi Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 18, 'Biada tym, którzy pragną dnia Pana! Cóż wam po tym dniu Pana? Jest on ciemnością, a nie światłością.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 19, 'Jak gdyby ktoś uciekał przed lwem, a spotkał go niedźwiedź; albo jak gdyby wszedł do domu i oparł się ręką o ścianę, a ukąsiłby go wąż.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 20, 'Czy dzień Pana nie jest ciemnością, a nie światłością? Mrokiem bez żadnej jasności?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 21, 'Nienawidzę waszych uroczystych świąt i gardzę nimi, i woń na waszych zgromadzeniach nie jest mi miła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 22, 'Jeśli bowiem będziecie mi składać całopalenia i swoje ofiary pokarmowe, nie przyjmę ich ani nie wejrzę na ofiary pojednawcze z waszego tuczonego bydła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 23, 'Oddal ode mnie wrzask waszych pieśni, bo nie chcę słuchać dźwięku waszych cytr.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 24, 'Niech raczej sąd tryska jak woda, a sprawiedliwość jak gwałtowny strumień.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 25, 'Czy składaliście mi ofiary i dary na pustyni przez czterdzieści lat, domu Izraela?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 26, 'Przecież nosiliście przybytek waszego Molocha i Kijuna, wasze bożki, gwiazdę waszych bogów, których sobie uczyniliście.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 27, 'Dlatego uprowadzę was do niewoli poza Damaszek, mówi Pan, Bóg zastępów, to jego imię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 1, 'Biada beztroskim na Syjonie i pokładającym ufność w górze Samarii; tym, którzy są przywódcami wśród tych narodów, do których schodzi się dom Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 2, 'Idźcie do Kalne i rozejrzyjcie się, a stamtąd idźcie do Chamat wielkiego. Potem zstąpcie do Gat filistyńskiego. Czy są to lepsze królestwa niż te? Czy ich obszar jest większy niż wasz obszar?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 3, 'Biada wam, którzy sądzicie, że dzień zły jest daleko i przybliżacie panowanie przemocy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 4, 'Którzy sypiacie na łożach z kości słoniowej, a rozciągacie się na swoich posłaniach; którzy jadacie jagnięta z trzody, a cielce tuczone z zagrody;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 5, 'Którzy śpiewacie przy lutni i wymyślacie sobie instrumenty muzyczne jak Dawid;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 6, 'Którzy pijecie wino z czasz i namaszczacie się drogimi maściami, a nie bolejecie nad utrapieniem Józefa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 7, 'Dlatego teraz pójdą do niewoli na czele pojmanych i skończy się biesiada hulaków.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 8, 'Pan Bóg przysiągł na siebie samego, mówi Pan, Bóg zastępów: Obrzydła mi pycha Jakuba i nienawidzę jego pałaców. Dlatego wydam miasto i wszystko, co w nim jest.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 9, 'A stanie się tak: Jeśli pozostanie dziesięć osób w jednym domu i one pomrą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 10, 'I każdego z nich weźmie jego stryj, i spali go, aby wynieść kości z domu, i zapyta tego, który jest w zakątkach domu: Czy jest jeszcze ktoś z tobą? A ten odpowie: Nie ma. Wtedy powie: Milcz, bo nie wolno wspominać imienia Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 11, 'Oto bowiem Pan rozkaże i uderzy w wielki dom rozpadlinami, a w mały dom – pęknięciem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 12, 'Czy konie mogą biegać po skale? Czy można tam orać wołami? Sąd bowiem zamieniliście w truciznę, a owoc sprawiedliwości w piołun.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 13, 'Biada wam, którzy się cieszycie, a to z niczego, mówiąc: Czy nie wzięliśmy sobie rogów własną siłą?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 14, 'Ale oto ja wzbudzę naród przeciwko wam, domu Izraela, mówi Pan, Bóg zastępów, który was będzie uciskał od wejścia do Chamat aż do strumienia pustyni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 1, 'To mi ukazał Pan Bóg. Oto tworzył koniki polne na początku odrastania potrawu, a oto był to potraw po sianokosach królewskich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 2, 'A gdy zjadły trawę ziemi, powiedziałem: Panie Boże! Przebacz, proszę. Któż zostanie Jakubowi? Jest bowiem malutki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 3, 'I żałował tego Pan. Pan powiedział: To się nie stanie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 4, 'To mi ukazał Pan Bóg: Oto Pan Bóg wezwał ogień w celu sądu, a wchłonął wielką głębię i strawił dział.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 5, 'Wtedy powiedziałem: Panie Boże! Zaniechaj tego, proszę. Któż zostanie Jakubowi? Jest bowiem malutki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 6, 'I żałował tego Pan. Pan Bóg powiedział: I to się nie stanie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 7, 'Potem to mi ukazał: oto Pan stał na murze wybudowanym za pomocą pionu, z pionem w ręku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 8, 'I Pan powiedział do mnie: Co widzisz, Amosie? Odpowiedziałem: Pion. Wtedy Pan powiedział: Oto przyłożę pion pośród mojego ludu, Izraela. Już mu więcej nie odpuszczę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 9, 'Wyżyny Izaaka będą spustoszone i świątynie Izraela zostaną zburzone, i powstanę z mieczem przeciwko domowi Jeroboama.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 10, 'Wtedy Amazjasz, kapłan Betel, posłał do Jeroboama, króla Izraela, taką wiadomość: Amos spiskuje przeciwko tobie pośród domu Izraela, tak że ziemia nie może znieść wszystkich jego słów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 11, 'Tak bowiem mówi Amos: Jeroboam umrze od miecza, a Izrael na pewno zostanie uprowadzony ze swojej ziemi do niewoli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 12, 'Potem Amazjasz powiedział do Amosa: Widzący, idź, uciekaj do ziemi Judy i tam jedz chleb, i tam prorokuj.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 13, 'A w Betel już więcej nie prorokuj, bo to jest świątynia króla i dom królewski.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 14, 'Wtedy Amos odpowiedział Amazjaszowi: Nie byłem prorokiem ani nawet synem proroka, lecz byłem pasterzem bydła i tym, który zbiera figi sykomory.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 15, 'Ale Pan mnie wziął, gdy chodziłem za bydłem, i powiedział do mnie Pan: Idź, prorokuj memu ludowi Izraelowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 16, 'Teraz więc słuchaj słowa Pana. Ty mówisz: Nie prorokuj w Izraelu i nie głoś przeciwko domowi Izaaka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 17, 'Dlatego tak mówi Pan: Twoja żona będzie nierządnicą w mieście, twoi synowie i twoje córki padną od miecza, twoja ziemia będzie podzielona sznurem, a ty umrzesz w ziemi nieczystej; Izrael zaś na pewno zostanie uprowadzony do niewoli ze swojej ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 1, 'To mi ukazał Pan Bóg: Oto stał kosz letnich owoców.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 2, 'Wtedy zapytał: Co widzisz, Amosie? Odpowiedziałem: Kosz letnich owoców. Pan znowu powiedział do mnie: Nadszedł koniec mojego ludu, Izraela, nie będę mu już więcej odpuszczał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 3, 'W tym dniu pieśni świątyni zamienią się w zawodzenie, mówi Pan Bóg. Będzie mnóstwo trupów na każdym miejscu, w ciszy będą wyrzucone.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 4, 'Słuchajcie tego, wy, którzy pożeracie ubogiego, abyście wykorzenili biednych z ziemi;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 5, 'Mówiąc: Kiedy przeminie nów księżyca, abyśmy mogli sprzedać zboże? Kiedy minie szabat, abyśmy mogli otworzyć spichlerze, abyśmy mogli umniejszać efę, podwyższać sykl i wagi podstępnie fałszować;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 6, 'Abyśmy mogli kupować ubogich za srebro, a nędzarza za parę sandałów; i abyśmy mogli plewy zboża sprzedawać?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 7, 'Pan przysiągł na chwałę Jakuba: Nigdy nie zapomnę wszystkich ich uczynków.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 8, 'Czyż z tego powodu nie zadrży ziemia i nie będzie lamentować każdy, kto w niej mieszka? Wzbierze się cała jak rzeka i zostanie porwana i zatopiona jakby przez rzekę Egiptu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 9, 'W tym dniu, mówi Pan Bóg, sprawię, że słońce zajdzie o południu, i przyprowadzę na ziemię ciemność w jasny dzień;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 10, 'I zamienię wasze święta w żałobę, a wszystkie wasze pieśni w lament. Sprawię, że na wszystkich biodrach będzie wór i na każdej głowie łysina. I będzie w tej ziemi żałoba jak po jedynaku, jej koniec jak dzień goryczy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 11, 'Oto nadchodzą dni, mówi Pan Bóg, gdy ześlę głód na ziemię, nie głód chleba ani pragnienie wody, ale słuchania słów Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 12, 'I będą się błąkać od morza do morza, i od północy aż na wschód będą biegać, szukając słowa Pana, ale go nie znajdą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 13, 'W tym dniu piękne dziewice i nawet młodzieńcy zemdleją z pragnienia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 14, 'Ci, którzy przysięgają na grzech Samarii, i mówią: Jak żyje twój Bóg, Danie, i jak żyje droga Beer-Szeby, oni upadną i już nigdy nie powstaną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 1, 'Widziałem Pana stojącego na ołtarzu i powiedział: Uderz w nadproże, aż zadrżą węgary. Rozetnij głowy ich wszystkich, a pozostałych zabiję mieczem. Żaden z nich nie ucieknie i żaden z nich nie ocaleje.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 2, 'Choćby się zakopali aż do piekła, moja ręka wyciągnie ich stamtąd; choćby wstąpili aż do nieba i stamtąd ich ściągnę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 3, 'Choćby się ukryli na szczycie Karmelu, odnajdę i wezmę ich stamtąd; a choćby się ukryli przed moimi oczami na dnie morza, rozkażę wężowi, aby ich tam ukąsił;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 4, 'Choćby poszli do niewoli przed swymi wrogami, nawet tam rozkażę mieczowi, aby ich zabijał. Zwrócę na nich swoje oczy dla zła, a nie dla dobra.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 5, 'Pan Bóg zastępów dotyka ziemi, a ta rozpływa się i płaczą wszyscy jej mieszkańcy. Wzbierze cała jak rzeka i zostanie zatopiona jakby przez rzekę Egiptu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 6, 'On zbudował w niebie swoje stopnie i ustanowił na ziemi swój zastęp; on przywołuje wody morskie i rozlewa je po powierzchni ziemi. Pan to jego imię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 7, 'Synowie Izraela, czy nie jesteście dla mnie jak synowie Etiopii? – mówi Pan. Czy nie wyprowadziłem Izraela z ziemi Egiptu, Filistynów z Kaftor i Syryjczyków z Kir?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 8, 'Oto oczy Pana Boga zwrócone są na to grzeszne królestwo i zgładzę je z powierzchni ziemi. Jednak nie zgładzę doszczętnie domu Jakuba, mówi Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 9, 'Oto bowiem wydam rozkaz i przesieję dom Izraela wśród wszystkich narodów, jak pszenicę przesiewa się przetakiem, tak że żadne ziarenko nie spadnie na ziemię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 10, 'Wszyscy grzesznicy spośród mojego ludu od miecza umrą, ci, którzy mówią: Nie dosięgnie nas ani nie zaskoczy nas to zło.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 11, 'W tym dniu podniosę upadły przybytek Dawida i zamuruję jego wyłomy; wzniosę jego ruiny i odbuduję go, jak za dawnych dni;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 12, 'Aby posiedli resztki Edomu i wszystkie narody, nad którymi wzywano mojego imienia, mówi Pan, który to czyni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 13, 'Oto nadchodzą dni, mówi Pan, że oracz będzie za żniwiarzem, a depczący winogrona za siejącym ziarno; góry będą ociekać moszczem, a wszystkie pagórki się rozpłyną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 14, 'Odwrócę niewolę mojego ludu, Izraela; odbudują miasta spustoszone i zamieszkają w nich; zasadzą też winnice i będą pić z nich wino; założą też sady i będą jedli ich owoce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 15, 'Zasadzę ich w ich ziemi; i nigdy nie zostaną wykorzenieni ze swojej ziemi, którą im dałem, mówi Pan, twój Bóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 1, 'Widzenie Abdiasza. Tak mówi Pan Bóg o Edomie: Usłyszeliśmy wieść od Pana, a posłaniec został wysłany do narodów: Powstańcie, wyruszmy przeciwko niemu do bitwy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 2, 'Oto uczyniłem cię małym wśród narodów, jesteś bardzo wzgardzony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 3, 'Pycha twego serca zwiodła cię, ty, który mieszkasz w rozpadlinach skalnych, masz swoje mieszkanie na wysokości; ty, który mówisz w swoim sercu: Któż mnie ściągnie na ziemię?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 4, 'Choćbyś wywyższył się jak orzeł, choćbyś założył swoje gniazdo wśród gwiazd, stamtąd cię strącę, mówi Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 5, 'Jakże jesteś zniszczony! Gdyby złodzieje przyszli do ciebie, gdyby rabusie zjawili się w nocy, czy nie kradliby tyle, ile potrzebują? Gdyby przyszli do ciebie zbieracze winogron, czy nie zostawiliby trochę winogron?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 6, 'Jakże przeszukane są skarby Ezawa, a przetrząśnięte jego skryte rzeczy!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 7, 'Aż do granicy wypchnęli cię wszyscy twoi sprzymierzeńcy. Ci, z którymi miałeś pokój, zdradzili cię i pokonali; ci, którzy jedli twój chleb, zranili cię zdradliwie. Nie ma zrozumienia u niego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 8, 'Czyż w owym dniu – mówi Pan – nie wytracę mędrców z Edomu, a rozumu – z góry Ezawa?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 9, 'I tak się zlękną twoi mocarze, Temanie, że wszyscy z góry Ezawa zostaną wycięci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 10, 'Z powodu przemocy wobec twego brata Jakuba okryje cię hańba i zostaniesz wykorzeniony na wieki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 11, 'W dniu, gdy stałeś naprzeciwko, w dniu, gdy obcy brali do niewoli jego wojsko i gdy cudzoziemcy wchodzili w jego bramy i o Jerozolimę rzucali losy, to ty byłeś też jak jeden z nich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 12, 'Nie powinieneś był patrzeć na dzień swego brata, w dniu jego pojmania, ani cieszyć się z powodu synów Judy w dniu ich zniszczenia, ani mówić zuchwale w dniu ucisku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 13, 'Nie powinieneś był wchodzić w bramę mojego ludu w dniu jego klęski ani patrzeć na jego nieszczęście w dniu jego klęski, ani wyciągać swej ręki po jego mienie w dniu jego klęski;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 14, 'Nie powinieneś był stać na rozstaju dróg, aby wytracić tych, którzy uciekali, ani wydać tych, którzy pozostali spośród nich w dniu ucisku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 15, 'Bliski bowiem jest dzień Pana dla wszystkich narodów. Jak ty postępowałeś, tak postąpią z tobą. Twoja odpłata spadnie na twoją głowę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 16, 'Bo jak wy piliście na mojej świętej górze, tak będą stale pić wszystkie narody; będą pić i pochłaniać, aż będzie z nimi tak, jakby ich nigdy nie było.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 17, 'A na górze Syjon będzie wybawienie i będzie ona święta, a dom Jakuba posiądzie swoje posiadłości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 18, 'Dom Jakuba stanie się ogniem, a dom Józefa płomieniem, dom Ezawa zaś ścierniskiem. Podpalą go i strawią, i nikt nie pozostanie z domu Ezawa, bo Pan to powiedział.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 19, 'Ci z krainy południa odziedziczą górę Ezawa, ci z równiny – Filistynów. Posiądą też krainę Efraima i krainę Samarii, a Beniamin posiądzie Gilead.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 20, 'A wygnańcy tego wojska z synów Izraela posiądą to, co należało do Kananejczyków aż do Sarepty; wygnańcy zaś z Jerozolimy, którzy są w Sefarad, posiądą miasta na południu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 21, 'I wstąpią wybawiciele na górę Syjon, aby sądzić górę Ezawa. I królestwo będzie należeć do Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 1, 'Słowo Pana doszło do Jonasza, syna Amittaja, mówiące:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 2, 'Wstań, idź do Niniwy, tego wielkiego miasta, i wołaj przeciwko niej, bo jej niegodziwość wzniosła się przed moje oblicze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 3, 'Ale Jonasz wstał, aby uciec do Tarszisz sprzed oblicza Pana, i przybył do Jafy. Znalazł okręt, który płynął do Tarszisz, zapłacił za przejazd i wsiadł na niego, aby płynąć z nimi do Tarszisz i uciec sprzed oblicza Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 4, 'Lecz Pan zesłał gwałtowny wiatr na morze i powstała potężna burza na morzu, tak że zdawało się, że okręt się rozbije.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 5, 'A żeglarze przestraszyli się i każdy z nich wołał do swego boga, a wyrzucali do morza ładunek, który był na okręcie, aby ten był lżejszy. Ale Jonasz zszedł wcześniej na niższy pokład okrętu, położył się i twardo zasnął.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 6, 'Przyszedł więc do niego sternik i zapytał go: Cóż ty czynisz, śpiochu? Wstań, wołaj do swego Boga, może Bóg wspomni na nas, abyśmy nie zginęli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 7, 'Wtedy powiedzieli jeden do drugiego: Chodźcie, rzućmy losy, abyśmy się dowiedzieli, przez kogo spadło na nas to nieszczęście. Rzucili więc losy i padło na Jonasza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 8, 'I powiedzieli do niego: Powiedz nam, prosimy, przez kogo spadło na nas to nieszczęście. Jaki jest twój zawód? Skąd pochodzisz? Z jakiego kraju i z jakiego narodu jesteś?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 9, 'Odpowiedział im: Jestem Hebrajczykiem i boję się Pana, Boga nieba, który stworzył morze i ziemię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 10, 'Wtedy ci mężczyźni bardzo się zlękli i zapytali: Czemu tak uczyniłeś? Oni bowiem dowiedzieli się, że ucieka sprzed oblicza Pana, bo im to powiedział.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 11, 'Powiedzieli jeszcze do niego: Cóż mamy z tobą uczynić, aby morze się uspokoiło? Morze bowiem coraz bardziej się burzyło.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 12, 'Odpowiedział im: Weźcie mnie i wrzućcie do morza, a ono uspokoi się dla was, gdyż wiem, że z mojego powodu ta wielka burza przyszła na was.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 13, 'Lecz ci mężczyźni wiosłowali silniej, aby dotrzeć do brzegu, ale nie mogli, bo morze coraz bardziej się burzyło przeciwko nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 14, 'Zawołali więc do Pana: Panie, prosimy, nie pozwól nam zginąć z powodu życia tego człowieka i nie obciążaj nas krwią niewinną. Ty bowiem, Panie, uczyniłeś, jak ci się spodobało.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 15, 'Potem wzięli Jonasza i wrzucili do morza, a morze przestało się burzyć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 16, 'Wtedy ci mężczyźni, zdjęci wielkim strachem przed Panem, złożyli Panu ofiarę i uczynili śluby.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 17, 'A Pan przygotował wielką rybę, która połknęła Jonasza. I Jonasz był we wnętrznościach tej ryby trzy dni i trzy noce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 1, 'I modlił się Jonasz do Pana, swego Boga, we wnętrznościach tej ryby;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 2, 'I powiedział: Wołałem do Pana w swoim ucisku i wysłuchał mnie; z głębi piekła wołałem i wysłuchałeś mego głosu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 3, 'Rzuciłeś mnie bowiem w głębię, w sam środek morza, i ogarnęła mnie toń. Wszystkie twoje nawałnice i fale przewaliły się nade mną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 4, 'Wtedy powiedziałem: Zostałem wygnany sprzed twoich oczu, ale będę jeszcze patrzył w stronę twej świętej świątyni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 5, 'Wody ogarnęły mnie aż do duszy, przepaść mnie otoczyła, moją głowę owinęła trawa morska.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 6, 'Zstąpiłem aż do posad gór, swymi ryglami ziemia zamknęła się przede mną na wieki. Ty jednak wyprowadziłeś moje życie z dołu, Panie, mój Boże!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 7, 'Gdy moja dusza we mnie omdlewała, wspomniałem na Pana, a moja modlitwa przyszła do ciebie, do twej świętej świątyni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 8, 'Ci, którzy trzymają się próżnych marności, pozbawiają się miłosierdzia;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 9, 'Ale ja z głosem dziękczynienia będę ci składał ofiary, wypełnię to, co ślubowałem. Od Pana pochodzi wybawienie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 10, 'Wtedy Pan rozkazał tej rybie, a ona wypluła Jonasza na brzeg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 1, 'Wtedy słowo Pana doszło do Jonasza po raz drugi mówiące:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 2, 'Wstań, idź do Niniwy, tego wielkiego miasta, i głoś przeciwko niej to, co ci rozkazuję.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 3, 'Wstał więc Jonasz i poszedł do Niniwy zgodnie ze słowem Pana. A Niniwa była bardzo wielkim miastem, na trzy dni drogi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 4, 'Jonasz zaczął chodzić po mieście, ile mógł przejść w jeden dzień, i wołał: Po czterdziestu dniach Niniwa zostanie zburzona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 5, 'I mieszkańcy Niniwy uwierzyli Bogu, ogłosili post i oblekli się w wory, od największego z nich aż do najmniejszego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 6, 'Doszła bowiem ta sprawa do króla Niniwy i powstał z tronu, i zdjął z siebie płaszcz, po czym oblekł się w wór i siedział w popiele.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 7, 'Rozkazał ogłosić i opowiadać w Niniwie z dekretu króla i swoich książąt: Ludzie i zwierzęta, woły i owce niech nic nie jedzą, niech się nie pasą i wody nie piją;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 8, 'Ale ludzie i zwierzęta niech się okryją worami i niech gorliwie wołają do Boga. Niech każdy się odwróci od swojej złej drogi i od grabieży popełnianej swoimi rękami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 9, 'Kto wie, czy Bóg się nie odwróci i nie pożałuje, i nie odstąpi od zapalczywości swego gniewu, abyśmy nie zginęli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 10, 'I Bóg widział ich czyny, że odwrócili się od swojej złej drogi, i Bóg pożałował tego nieszczęścia, które zapowiedział im czynić, a nie uczynił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 1, 'Ale Jonaszowi bardzo się to nie podobało i rozgniewał się.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 2, 'I modlił się do Pana, mówiąc: Proszę, Panie, czy tego nie mówiłem, gdy jeszcze byłem w swojej ziemi? Dlatego zaraz uciekłem do Tarszisz, gdyż wiedziałem, że ty jesteś Bogiem łaskawym i litościwym, nieskorym do gniewu i pełnym wielkiego miłosierdzia, który żałuje nieszczęścia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 3, 'A teraz, Panie, proszę, zabierz ode mnie moje życie, bo lepiej mi umrzeć, niż żyć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 4, 'Pan odpowiedział: Czy to dobrze, że tak się gniewasz?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 5, 'Wyszedł więc Jonasz z miasta i usiadł po wschodniej stronie miasta. Tam zrobił sobie szałas i usiadł w jego cieniu, by zobaczyć, co się stanie z tym miastem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 6, 'A Pan Bóg sprawił, że nad Jonaszem wyrosła tykwa, aby zasłaniała jego głowę i chroniła go przed upałem. I Jonasz bardzo się cieszył z tej tykwy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 7, 'Ale nazajutrz o świcie Bóg sprawił, że robak podgryzł tę tykwę, tak że uschła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 8, 'I gdy wzeszło słońce, Bóg wzbudził suchy wiatr wschodni; i słońce tak prażyło głowę Jonasza, że omdlewał i życzył sobie śmierci, mówiąc: Lepiej mi umrzeć, niż żyć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 9, 'I Bóg powiedział do Jonasza: Czy to dobrze, że tak się gniewasz z powodu tej tykwy? I odpowiedział: To dobrze, że się gniewam, nawet aż na śmierć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 10, 'Wtedy Pan mu powiedział: Żałujesz tej tykwy, przy której nie pracowałeś ani nie dałeś jej wzrostu; wyrosła w jedną noc i w jedną noc uschła;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 11, 'A ja miałbym nie żałować Niniwy, tego wielkiego miasta, w którym jest więcej niż sto dwadzieścia tysięcy ludzi, którzy nie umieją rozróżnić swej prawej ręki od lewej, a także wiele bydła?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 1, 'Słowo Pana, które doszło do Micheasza z Moreszet za dni Jotama, Achaza i Ezechiasza, królów Judy – to, co widział o Samarii i Jerozolimie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 2, 'Słuchajcie, wszystkie narody; słuchaj, ziemio, i wszystko, co na niej jest. A niech Pan Bóg będzie świadkiem przeciwko wam, Pan ze swego świętego przybytku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 3, 'Oto bowiem Pan wychodzi ze swojego miejsca, zstąpi i będzie deptać po wysokościach ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 4, 'I stopnieją pod nim góry, a doliny rozdzielą się tak, jak wosk przed ogniem i jak wody, które spływają po zboczu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 5, 'To wszystko się stanie z powodu przestępstwa Jakuba i z powodu grzechów domu Izraela. Jakie jest przestępstwo Jakuba? Czy to nie Samaria? Co jest wyżyną Judy? Czy nie Jerozolima?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 6, 'Dlatego zamienię Samarię w kupę gruzu na polu, w miejsce pod założenie winnicy. Powrzucam w dolinę jej kamienie i odkryję jej fundamenty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 7, 'I wszystkie jej wyrzeźbione obrazy będą potłuczone, wszystkie jej dary spalone ogniem i wszystkie jej bożki zamienię w ruinę. To bowiem zgromadziła z zapłaty nierządnicy, to więc obróci się w zapłatę nierządnicy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 8, 'Nad tym będę zawodzić i lamentować, chodząc nagi, bez ubrań. Podnoszę zawodzenie jak smoki i lament jak młode strusie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 9, 'Jej rana bowiem jest nieuleczalna, gdyż doszła aż do Judy, a dotarła do bramy mego ludu aż do Jerozolimy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 10, 'Nie opowiadajcie tego w Gat ani nie płaczcie. Tarzajcie się w prochu, w domu Afra.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 11, 'Przejdź ty, która mieszkasz w Szafirze w haniebnej nagości. Ta, która mieszka w Saananie, nie wyszła na żałobę w Bet-Hezel; weźmie od was swoją żywność.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 12, 'Ta, która mieszka w Marot, oczekiwała dobra, ale zło zstąpiło od Pana aż do bramy Jerozolimy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 13, 'Zaprzęgaj konie do rydwanu, mieszkanko Lakisz, która jesteś powodem grzechu córki Syjonu, gdyż w tobie znalezione są przestępstwa Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 14, 'Dlatego poślesz dary do Moreszet-Gat. Domy Akzibu będą ułudą dla królów Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 15, 'Jeszcze przyprowadzę ci dziedzica, mieszkanko Mareszy. Przyjdzie aż do Adullam, do chwały Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 16, 'Ogol się i ostrzyż z powodu swoich ukochanych synów; rozszerz swą łysinę jak orzeł, bo poszli od ciebie do niewoli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 1, 'Biada tym, którzy wymyślają nieprawość i knują zło na swoich łożach, a o świcie wykonują je, bo jest to w ich mocy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 2, 'Pożądają pól i wydzierają je; także domów i je zabierają. W ten sposób gnębią człowieka i jego dom, człowieka i jego dziedzictwo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 3, 'Dlatego tak mówi Pan: Oto obmyślam dla tego rodu nieszczęście, z którego nie będziecie mogli wyciągnąć swoich szyj ani nie będziecie chodzić zuchwale. Będzie to bowiem czas nieszczęścia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 4, 'W tym dniu powstanie o was przypowieść i podniosą nad wami żałosny lament, mówiąc: Jesteśmy doszczętnie spustoszeni. Odmienił dział mego ludu, jakże mi go odjął! Gdy wziął nasze pole, rozdzielił je.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 5, 'Dlatego nie będziesz miał nikogo, kto rzuciłby sznurem na los w zgromadzeniu Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 6, 'Mówią: Nie prorokujcie, niech nam inni prorokują. Nie prorokują bowiem tak, jak ci. Żaden z nich nie przestaje mówić obraźliwie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 7, 'O ty, ludu, który słyniesz domem Jakuba! Czy Duch Pana jest ograniczony? Czy takie są jego dzieła? Czy moje słowa nie są dobre dla tego, który postępuje w sposób prawy?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 8, 'Wczoraj był moim ludem, a dziś jak wróg powstaje. Zdzieracie płaszcz wraz z szatą z tych, którzy przechodzą bezpiecznie, jakby wracali z wojny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 9, 'Kobiety mego ludu wyganiacie z ich przytulnych domów; ich dzieciom odebraliście moją chwałę na zawsze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 10, 'Wstańcie i odejdźcie, bo tu nie ma odpoczynku. Z powodu nieczystości zniszczy was, i to zniszczeniem srogim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 11, 'Gdy ktoś podaje się za proroka i kłamie, mówiąc: Będę prorokował o winie i o mocnym napoju, to taki staje się prorokiem tego ludu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 12, 'Na pewno zgromadzę ciebie całego, Jakubie, na pewno zgromadzę resztkę Izraela. Zbiorę ich razem jak owce Bozra, jak trzodę w środku owczarni, i będzie bardzo głośno z powodu mnóstwa ludzi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 13, 'Zstąpi przed nimi ten, który będzie przełamywać. Przełamali się, przeszli przez bramę i wyszli przez nią. Ich król pójdzie przed nimi, a Pan na ich czele.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 1, 'I powiedziałem: Słuchajcie, naczelnicy Jakuba i wodzowie domu Izraela! Czy wy nie powinniście znać sądu?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 2, 'Wy, którzy nienawidzicie dobra, a kochacie zło, którzy zdzieracie z ludu skórę i ciało z jego kości;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 3, 'Którzy jecie ciało mojego ludu, skórę z niego zdzieracie, jego kości łamiecie i kroicie je na kawałki jak do garnca i jak mięso do kotła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 4, 'Wtedy będą wołać do Pana, a nie wysłucha ich, lecz zakryje swoje oblicze przed nimi w tym czasie, gdyż oni popełniali złe czyny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 5, 'Tak mówi Pan o tych prorokach, którzy w błąd wprowadzą mój lud, którzy gryzą swoimi zębami i głoszą pokój, a temu, który nic im nie włoży do ust, wypowiadają wojnę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 6, 'Dlatego wasze widzenie zamienia się w noc, a wasza wróżba – w ciemność; słońce zajdzie nad prorokami i dzień się zaćmi nad nimi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 7, 'Wtedy widzący będą się wstydzić i wróżbiarze się zarumienią. Oni wszyscy zakryją swoje wargi, bo nie będzie żadnej odpowiedzi od Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 8, 'Ale ja jestem napełniony mocą Ducha Pana oraz sądu i siły, aby oznajmić Jakubowi jego występki i Izraelowi jego grzech.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 9, 'Słuchajcie tego, naczelnicy domu Jakuba i wodzowie domu Izraela, którzy brzydzicie się sądem i wypaczacie wszystko, co sprawiedliwe.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 10, 'Każdy buduje Syjon krwią, a Jerozolimę nieprawością.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 11, 'Jej naczelnicy sądzą za dary, jego kapłani uczą za zapłatę i jego prorocy prorokują za pieniądze. Polegają jednak na Panu, mówiąc: Czy Pan nie jest wśród nas? Nie spotka nas nic złego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 12, 'Dlatego Syjon stanie się dla was jak zaorane pole, Jerozolima zamieni się w kupę gruzu, a góra domu – w zalesione wzgórze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 1, 'Ale w ostatecznych dniach stanie się, że góra domu Pana będzie utwierdzona na szczycie gór i wywyższona ponad pagórki, a narody do niej popłyną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 2, 'I wiele narodów przybędzie, mówiąc: Chodźcie, wstąpmy na górę Pana, do domu Boga Jakuba, i będzie nas nauczał swoich dróg, a my będziemy chodzili jego ścieżkami. Z Syjonu bowiem wyjdzie prawo i słowo Pana z Jerozolimy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 3, 'On będzie sądzić wśród wielu narodów i będzie karać narody potężne i odległe. I przekują swoje miecze na lemiesze, a swoje oszczepy na sierpy. Naród przeciwko narodowi nie podniesie miecza i już nie będą się uczyć sztuki wojennej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 4, 'Ale każdy będzie siedział pod swoją winoroślą i pod swoim drzewem figowym i nikt nie będzie ich straszył, bo to usta Pana zastępów powiedziały.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 5, 'Wszystkie narody bowiem będą chodzić, każdy w imię swego boga, ale my będziemy chodzić w imię Pana, naszego Boga, na wieki wieków.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 6, 'W tym dniu, mówi Pan, zgromadzę chromą, zbiorę wygnaną oraz tę, którą trapiłem;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 7, 'A z tej chromej uczynię resztkę, a z wygnanej – potężny naród. I Pan będzie królował nad nimi na górze Syjon odtąd aż na wieki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 8, 'A ty, wieżo trzody, twierdzo córki Syjonu, wiedz, że do ciebie przyjdzie, przyjdzie pierwsze panowanie, królestwo córki Jerozolimy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 9, 'Czemu teraz tak bardzo krzyczysz? Czy nie ma króla u ciebie? Czy twój doradca zginął, że cię ból ogarnął jak rodzącą?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 10, 'Odczuwaj ból i jęcz, córko Syjonu, jak rodząca, bo już wyjdziesz z miasta i zamieszkasz w polu, i pójdziesz aż do Babilonu. Tam będziesz wybawiona, tam cię Pan odkupi z rąk twoich wrogów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 11, 'Teraz zebrało się przeciwko tobie wiele narodów, które mówią: Niech będzie zbezczeszczona, niech nasze oko patrzy na Syjon.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 12, 'One jednak nie znają myśli Pana ani nie rozumieją jego rady. On bowiem je zgromadzi jak snopy na klepisku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 13, 'Wstań i młóć, córko Syjonu, bo twój róg uczynię z żelaza i twoje kopyta uczynię ze spiżu, i zmiażdżysz wiele narodów. Poświęcę Panu ich łupy i ich bogactwo Panu całej ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 1, 'Zbierz się teraz w oddziały, córko oddziałów! Obległ nas. Laską będą bić w policzek sędziego Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 2, 'Ale ty, Betlejem Efrata, choć jesteś najmniejsze wśród tysięcy w Judzie, z ciebie jednak wyjdzie mi ten, który będzie władcą w Izraelu, a jego wyjścia są od dawna, od dni wiecznych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 3, 'Dlatego wyda ich aż do czasu, kiedy rodząca porodzi. Wtedy resztka jego braci wróci do synów Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 4, 'Powstanie i będzie paść w mocy Pana i w majestacie imienia Pana, swego Boga. I będą mieszkać spokojnie, bo już będzie on wielki aż po krańce ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 5, 'I będzie on pokojem, gdy Asyryjczyk wtargnie do naszej ziemi. I gdy podepcze nasze pałace, wtedy wystawimy przeciw niemu siedmiu pasterzy i ośmiu książąt z ludu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 6, 'Ci ogołocą ziemię Asyrii mieczem i ziemię Nimroda na jej granicach. W ten sposób wybawi nas od Asyryjczyka, gdy nadciągnie do naszej ziemi i gdy będzie stąpał w naszych granicach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 7, 'Dlatego resztka Jakuba będzie pośród wielu narodów jak rosa od Pana, jak deszcze skrapiające trawę, które nie czekają na człowieka ani nie polegają na synach ludzkich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 8, 'Resztka Jakuba będzie też pośród pogan, wśród wielu narodów, jak lew między leśnymi zwierzętami i jak lwiątko między trzodami owiec, które – gdy przechodzi – depcze i szarpie, a nie ma nikogo, kto by je ocalił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 9, 'Wywyższy się twoja ręka nad twoimi wrogami, a wszyscy twoi przeciwnicy będą wykorzenieni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 10, 'I stanie się w tym dniu, mówi Pan, że wytracę twoje konie spośród ciebie i zniszczę twoje rydwany.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 11, 'Wygubię miasta twojej ziemi i zburzę wszystkie twoje twierdze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 12, 'Wytracę czary z twojej ręki i nie będzie już u ciebie wróżbitów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 13, 'Wyniszczę też twoje rzeźbione bożki i twoje obrazy spośród ciebie i nie będziesz już oddawać pokłonu dziełu swoich rąk.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 14, 'Wykorzenię twoje gaje spośród ciebie i zgładzę twoich wrogów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 15, 'Tak w gniewie i zapalczywości dokonam zemsty nad narodami, które nie były posłuszne.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 1, 'Słuchajcie tego, co mówi Pan: Wstań, spieraj się z górami i niech pagórki słuchają twego głosu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 2, 'Słuchajcie, góry, sporu Pana, i najmocniejsze fundamenty ziemi, bo Pan wiedzie spór ze swoim ludem i rozprawia się z Jerozolimą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 3, 'Mój ludu, cóż ci uczyniłem? W czym ci się uprzykrzyłem? Zeznaj przeciwko mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 4, 'Wyprowadziłem cię bowiem z ziemi Egiptu, odkupiłem cię z domu niewolników i posłałem przed tobą Mojżesza, Aarona i Miriam.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 5, 'Mój ludu! Wspomnij teraz, co zamierzał Balak, król Moabu, a co mu odpowiedział Balaam, syn Beora; wspomnij też, co się działo od Szittim aż do Gilgal, abyś poznał sprawiedliwość Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 6, 'Z czym mam się stawić przed Panem i pokłonić się Bogu najwyższemu? Czy mam stawić się przed nim z ofiarami całopalnymi i jednorocznymi cielcami?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 7, 'Czy Pan ma upodobanie w tysiącach baranów i w dziesiątkach tysięcy strumieni oliwy? Czy mam mu dać swego pierworodnego za mój występek, owoc mego łona za grzech mojej duszy?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 8, 'On ci oznajmił, człowieku, co jest dobre i czego Pan żąda od ciebie: jedynie tego, byś czynił sprawiedliwie, kochał miłosierdzie i pokornie chodził z twoim Bogiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 9, 'Głos Pana woła do miasta (ale roztropny sam ujrzy twoje imię): Słuchajcie rózgi i tego, kto ją ustanowił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 10, 'Czy jeszcze są w domu bezbożnego skarby niesprawiedliwe i miara niesprawiedliwa i obrzydliwa?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 11, 'Czy mam usprawiedliwić oszukańczą wagę i worek fałszywych odważników?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 12, 'Jego bogacze są pełni zdzierstwa, jego mieszkańcy mówią kłamstwo i ich język w ich ustach jest kłamliwy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 13, 'Dlatego też dotknę cię chorobą, uderzę cię i zniszczę z powodu twoich grzechów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 14, 'Będziesz jeść, ale się nie nasycisz; twoje poniżenie będzie w środku ciebie. Pochwycisz, ale nie ocalisz, a co ocalisz, wydam pod miecz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 15, 'Będziesz siał, ale nie będziesz żął; będziesz tłoczył oliwki, ale nie namaścisz się oliwą; będziesz wyciskał moszcz, ale nie napijesz się wina.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 16, 'Przestrzegacie bowiem ustaw Omriego i wszystkich czynów domu Achaba i postępujecie według ich rad. Dlatego cię wydam na spustoszenie i jego mieszkańców na pośmiewisko. Będziecie więc nosić hańbę mego ludu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 1, 'Biada mi! Jestem bowiem jak ostatki po letnich zbiorach, jak pokłosie grona po winobraniu. Nie ma żadnego grona do zjedzenia, moja dusza pragnęła pierwocin z owocu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 2, 'Pobożny zginął z ziemi, nie ma prawego wśród ludzi. Wszyscy czyhają na krew, każdy zastawia sieci dla swego brata.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 3, 'By chętnie czynić zło obiema rękami, książę i sędzia żądają datku; zamożny człowiek wypowiada swoją przewrotną żądzę. I razem wszystko splatają.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 4, 'Najlepszy z nich jest jak oset; najuczciwszy – jak płot ciernisty. Nadchodzi dzień twoich stróżów i twojego nawiedzenia; już nastanie ich zamieszanie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 5, 'Nie wierzcie przyjacielowi, nie ufajcie wodzowi. Strzeż bramy swoich ust przed tą, która leży na twoim łonie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 6, 'Syn bowiem lekceważy ojca, córka powstaje przeciwko swojej matce, synowa przeciwko swojej teściowej, a wrogami człowieka są jego domownicy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 7, 'Dlatego będę wypatrywał Pana, będę oczekiwać Boga mego zbawienia. Mój Bóg mnie wysłucha.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 8, 'Nie ciesz się z mojego powodu, moja nieprzyjaciółko! Chociaż upadłem, powstanę; choć siedzę w ciemności, Pan jest moją światłością.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 9, 'Zniosę gniew Pana, bo zgrzeszyłem przeciwko niemu, aż będzie bronił mojej sprawy i wykona dla mnie sąd. Wyprowadzi mnie na światło i ujrzę jego sprawiedliwość.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 10, 'Ujrzy to moja nieprzyjaciółka i wstyd okryje tę, która do mnie mówi: Gdzie jest Pan, twój Bóg? Moje oczy będą patrzyć na nią, gdy będzie podeptana jak błoto na ulicach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 11, 'W tym dniu, kiedy będą odbudowywać twoje mury, w tym dniu dekret rozejdzie się daleko.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 12, 'W tym dniu będą przychodzić do ciebie od Asyrii aż po miasta obronne, od miast obronnych aż po rzekę, od morza aż do morza i od góry aż do góry.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 13, 'Ta ziemia jednak będzie spustoszona z powodu swoich mieszkańców, z powodu owocu ich czynów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 14, 'Paś swój lud laską swoją, trzodę swojego dziedzictwa, która mieszka samotnie w lesie i w środku Karmelu. Niech się pasą w Baszanie i Gileadzie jak za dawnych dni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 15, 'Ukażę mu cudowne rzeczy jak za dni, gdy wyszedłeś z ziemi Egiptu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 16, 'Ujrzą to narody i zawstydzą się całej swojej potęgi. Przyłożą rękę do ust, a ich uszy ogłuchną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 17, 'Będą lizać proch jak wąż, wyjdą ze swoich nor jak zwierzęta pełzające do Pana, naszego Boga, ze strachem i będą się bać ciebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 18, 'Któż jest Bogiem jak ty, który przebacza nieprawość i daruje występek resztki swego dziedzictwa? Nie chowa swego gniewu na wieki, bo ma upodobanie w miłosierdziu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 19, 'Odwróci się i zlituje się nad nami; pokona nasze nieprawości i wrzuci w głębiny morza wszystkie nasze grzechy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 20, 'Pokażesz prawdę Jakubowi i okażesz miłosierdzie Abrahamowi, tak jak przysiągłeś naszym ojcom za dawnych dni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 1, 'Brzemię Niniwy. Księga widzenia Nahuma Elkoszyty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 2, 'Pan jest Bogiem zazdrosnym i mściwym; Pan jest mściwy i pełen gniewu; Pan mści się nad swoimi przeciwnikami i zachowuje gniew wobec swoich wrogów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 3, 'Pan jest nieskory do gniewu i wielki w mocy, a winnego nie uniewinni. Droga Pana jest w wichrze i w burzy, a obłok jest prochem pod jego stopami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 4, 'On gromi morze i je wysusza, wysusza też wszystkie rzeki. Przed nim Baszan i Karmel mdleje, a kwiat Libanu więdnie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 5, 'Góry drżą przed nim, a pagórki się rozpływają; ziemia płonie przed jego obliczem, okrąg ziemi i wszyscy jej mieszkańcy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 6, 'Któż się ostoi przed jego oburzeniem? Kto wytrzyma zapalczywość jego gniewu? Jego gniew wylewa się jak ogień, a skały rozpadają się przed nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 7, 'Dobry jest Pan – warownia w dniu ucisku; zna tych, którzy mu ufają.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 8, 'Ale gwałtowną powodzią zniszczy jej miejsce, ciemność będzie ścigała jego wrogów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 9, 'Co zamierzacie przeciwko Panu? On dokona zniszczenia, ucisk nie powstanie po raz drugi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 10, 'Gdy bowiem będą jak splecione ciernie i jak pijacy upojeni winem, jak suche ściernisko do szczętu spłoną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 11, 'Z ciebie wyszedł ten, który obmyślił zło przeciwko Panu, doradca nikczemny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 12, 'Tak mówi Pan: Chociaż są spokojni i tak liczni, będą jednak skoszeni, gdy przejdzie. Chociaż cię trapiłem, już więcej nie będę cię trapił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 13, 'Teraz bowiem złamię jego jarzmo, aby na tobie nie leżało, a rozerwę twoje więzy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 14, 'O tobie Pan rozkazał, że twoje imię już nie będzie miało więcej potomstwa. Wyniszczę z domu twoich bogów rzeźbione i lane posągi. Przygotuję ci grób, gdyż jesteś nikczemny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 15, 'Oto na górach nogi opowiadającego dobre wieści, zwiastującego pokój. Obchodź, Judo, swoje uroczyste święta, wypełniaj swoje śluby. Nikczemnik bowiem już nie przejdzie przez ciebie, został doszczętnie zgładzony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 1, 'Nadciąga niszczyciel przeciwko tobie! Strzeż miejsc obronnych, obserwuj drogę, wzmocnij biodra i zbierz wszystkie swe siły.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 2, 'Pan bowiem odwrócił pychę Jakuba jak pychę Izraela, gdyż złupili ich grabieżcy i zniszczyli ich latorośle.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 3, 'Tarcza jego mocarzy czerwona, jego wojownicy ubrani w szkarłat, rydwany będą jak płonące pochodnie w dniu jego przygotowania, a jodły będą strasznie się trząść.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 4, 'Rydwany po ulicach będą szaleć i na rynku skrzypieć. Z wyglądu będą podobne do pochodni, jak błyskawice będą pędzić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 5, 'Wezwie swoich mocarzy; zatoczą się w swoim pochodzie, pospieszą się do murów, obrona będzie przygotowana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 6, 'Bramy przy rzekach otworzą się i pałac się rozpłynie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 7, 'A Chusab zostanie uprowadzona do niewoli, jej służące będą ją prowadzić, jęcząc jak gołębie i bijąc się w piersi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 8, 'A Niniwa od swego początku była jak sadzawka wód, ale uciekną. I choć ktoś powie: Stójcie, stójcie! – nikt jednak się nie obejrzy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 9, 'Rabujcie srebro, rabujcie złoto, bo nie ma końca bogactwo i przepych wszystkich kosztowności.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 10, 'Pusta, opróżniona i spustoszona! Serce topnieje, trzęsą się kolana, czuć ból w biodrach wszystkich ludzi, a twarze wszystkich czernieją.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 11, 'Gdzie jest jaskinia lwów i pastwisko lwiąt, dokąd chodziły lew, ten wielki lew, oraz lwięta, a nie było nikogo, kto by je straszył.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 12, 'Lew już dosyć rozszarpał ofiar dla swych lwiąt i zadusił je dla swoich lwic, napełniał łupem swoje jaskinie, a zdobyczą swoje legowiska.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 13, 'Oto jestem przeciwko tobie, mówi Pan zastępów, spalę na proch twoje rydwany i twoje lwięta pożre miecz. Wykorzenię z ziemi twój łup i nie będzie już słychać głosu twoich posłów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 1, 'Biada krwawemu miastu! Jest ono całe pełne kłamstwa i grabieży, a łup z niego nie wychodzi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 2, 'Słychać trzask biczów, grzmot kół, tupanie koni i podskakiwanie rydwanów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 3, 'Jeździec dobywa błyszczący miecz i lśniący oszczep. Mnóstwo rannych i tak wielka ilość trupów, że nie można ich zliczyć; potykają się o zwłoki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 4, 'Z powodu mnóstwa czynów nierządu tej rozkosznej nierządnicy, mistrzyni czarów, która zaprzedawała narody swoim nierządem i ludy swoimi czarami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 5, 'Oto jestem przeciwko tobie, mówi Pan zastępów, odkryję poły twojej szaty aż do twarzy i ukażę narodom twoją nagość, a królestwom – twoją hańbę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 6, 'Rzucę na ciebie obrzydliwości, znieważę cię i wystawię cię na widowisko.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 7, 'Ten, kto cię ujrzy, oddali się od ciebie i powie: Zburzona jest Niniwa, któż będzie jej żałował? Gdzie mam szukać dla ciebie pocieszycieli?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 8, 'Czy jesteś lepsza niż ludne miasto No, które leżało pomiędzy rzekami, otoczone wodami, którego wałem było morze i morze jego murem?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 9, 'Etiopia i Egipt były jego siłą, nieograniczona; Put i Libijczycy byli jego pomocą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 10, 'Ono jednak zostało uprowadzone do niewoli, jego niemowlęta roztrzaskiwano na rogach wszystkich ulic, o jego najsławniejszych rzucano losy i wszystkich jego wielkich zakuto w kajdany.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 11, 'Także i ty będziesz upojona. Ukryjesz się i będziesz szukać pomocy przeciwko wrogowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 12, 'Wszystkie twoje twierdze są jak drzewo figowe z wczesnymi owocami. Gdy się nimi potrząśnie, wpadają do ust jedzącego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 13, 'Oto twój lud pośród ciebie to kobiety. Bramy twojej ziemi będą szeroko otwarte przed twoimi wrogami. Ogień strawi twoje rygle.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 14, 'Naczerp sobie wody na oblężenie, umacniaj swoje twierdze. Wejdź w błoto, depcz glinę i napraw piec.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 15, 'Tam cię pochłonie ogień, wytnie cię miecz, pożre cię jak larwa. Rozmnóż się jak larwa, rozmnóż się jak szarańcza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 16, 'Rozmnożyłaś swoich kupców ponad gwiazdy niebios. Jak larwa pożerają i odlatują.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 17, 'Twoi szlachetni są jak szarańcza, twoi dowódcy – jak wielkie koniki polne, które siadają na płotach w czasie zimy, lecz gdy słońce wschodzi, odlatują i nie wiadomo, gdzie są.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 18, 'Drzemią twoi pasterze, królu Asyrii! Twoi sławni będą leżeć, twój lud rozproszył się po górach, ale nikt go nie zgromadzi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 19, 'Nie ma lekarstwa na twoją ranę, twoje zranienie jest nieuleczalne. Wszyscy, którzy usłyszą wieść o tobie, będą klaskać w dłonie nad tobą. Kogo bowiem nie dotykało nieustannie twoje okrucieństwo?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 1, 'Brzemię, które widział prorok Habakuk.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 2, 'Panie, jak długo będę wołać, a nie będziesz wysłuchiwał? Jak długo będę krzyczeć do ciebie o krzywdzie, a nie będziesz wybawiał?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 3, 'Czemu dopuszczasz, abym patrzył na nieprawość i widział bezprawie? Zguba i przemoc są przede mną i znajduje się ten, który roznieca spory i niezgodę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 4, 'Dlatego prawo jest naruszone, a nie ma już sprawiedliwości. Niegodziwy bowiem osacza sprawiedliwego, dlatego wydawane są błędne wyroki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 5, 'Spójrzcie na narody, zobaczcie i zdumiejcie się bardzo, gdyż dokonuję dzieła za waszych dni, w które nie uwierzycie, gdy wam o nim opowiedzą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 6, 'Oto bowiem wzbudzę Chaldejczyków, naród srogi i gwałtowny; przejdą przez szerokość ziemi, aby posiąść cudze miejsca zamieszkania.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 7, 'Straszni są i groźni. Sami ustalają swój sąd i swoją wielkość.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 8, 'Ich konie są szybsze niż lamparty, dziksze niż wilki o zmierzchu. Ich jeźdźcy rozciągną się szeroko, ich jeźdźcy przybędą z daleka, przylecą jak orzeł spieszący się na żer.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 9, 'Każdy z nich przybędzie dla łupu. Ich twarze będą zwrócone na wschód i zgromadzą jeńców jak piasek.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 10, 'Będą szydzić z królów, a książęta będą u nich przedmiotem pogardy. Z każdej twierdzy będą się naśmiewać, usypią wały i zdobędą ją.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 11, 'Wtedy jego duch się odmieni, a wystąpi i zawini, myśląc, że jego moc pochodzi od jego boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 12, 'Czy ty nie jesteś od wieków, Panie, mój Boże, mój Święty? My nie umrzemy. Panie, postawiłeś ich na sąd. Ty, nasza Skało, przeznaczyłeś ich na karanie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 13, 'Twoje oczy są tak czyste, że nie możesz patrzeć na zło ani widzieć bezprawia. Czemu patrzysz na czyniących przewrotność? Czemu milczysz, gdy niegodziwy pożera sprawiedliwszego niż on sam?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 14, 'Czemu czynisz ludzi jak ryby morskie, jak zwierzęta pełzające, które nie mają pana?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 15, 'Wyciąga wszystkie wędką, zagarnia je swoim niewodem i gromadzi je w swojej sieci. Dlatego cieszy się i raduje.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 16, 'Dlatego składa ofiarę swemu niewodowi i pali kadzidło swojej sieci. Przez nie bowiem jego dział jest obfity i jego pożywienie bogatsze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 17, 'Czy dlatego będzie zarzucać swoją sieć, by nieustannie zabijać narody bez litości?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 1, 'Na swej warcie będę stać, stanę na baszcie i będę się wpatrywać, aby zobaczyć, co Bóg będzie mówił i co mam odpowiedzieć, gdy zostanę upomniany.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 2, 'Wtedy Pan mi odpowiedział: Zapisz to widzenie, zapisz je wyraźnie na tablicach, aby czytający mógł je szybko przeczytać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 3, 'To widzenie bowiem dotyczy oznaczonego czasu, a na końcu oznajmi, a nie skłamie; a choćby się odwlekało, oczekuj go, bo z pewnością przyjdzie, nie spóźni się.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 4, 'Oto dusza tego, który się wywyższa, nie jest w nim prawa. Ale sprawiedliwy będzie żył ze swojej wiary.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 5, 'Owszem, ponieważ upija się, jest on hardym człowiekiem i nie pozostaje w swoim domu; pomnaża swoją żądzę jak piekło i jak śmierć nie może się nasycić, choć zgromadził u siebie wszystkie narody i zebrał u siebie wszystkich ludzi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 6, 'Czy ci wszyscy nie ułożą o nim przypowieści i szyderczego przysłowia, mówiąc: Biada temu, który gromadzi nie swoje rzeczy (jak długo?) i obciąża się gęstym błotem!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 7, 'Czy nie powstaną nagle ci, którzy będą cię kąsać, i nie obudzą się ci, którzy będą cię szarpać? A staniesz się dla nich łupem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 8, 'Ponieważ złupiłeś wiele narodów, złupią cię też wszystkie pozostałe narody z powodu krwi ludzkiej i przemocy dokonanej w ziemi, miastu i wszystkim jego mieszkańcom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 9, 'Biada temu, który chciwie pragnie niegodziwego zysku dla swego domu, aby wystawił wysoko swoje gniazdo i tak uszedł mocy zła!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 10, 'Postanowiłeś wytracić wiele narodów na hańbę swemu domowi, a grzeszyłeś przeciwko własnej duszy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 11, 'Kamień bowiem będzie wołać z muru i sęk z drewna da o tym świadectwo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 12, 'Biada temu, który krwią buduje miasto i utwierdza miasto nieprawością!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 13, 'Czyż to nie pochodzi od Pana zastępów, że ludy będą się trudzić przy ogniu, a narody będą się męczyć daremnie?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 14, 'Ziemia bowiem będzie napełniona poznaniem chwały Pana, jak wody napełniają morze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 15, 'Biada temu, który poi swego bliźniego, przystawiając mu swe naczynie, aż go upoi, by patrzeć na jego nagość!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 16, 'Nasyciłeś się hańbą zamiast sławą; upij się sam i będziesz obnażony. Kielich prawicy Pana zwróci się przeciw tobie i sromotne wymioty pokryją twoją sławę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 17, 'Okryje cię bowiem bezprawie Libanu i spustoszenie bestii, które ich straszyły, z powodu krwi ludzkiej i przemocy dokonanej w ziemi miastu i wszystkim jego mieszkańcom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 18, 'Cóż pomoże rzeźbiony posąg, który wykonał jego rzemieślnik, albo odlany obraz i nauczyciel kłamstwa, aby rzemieślnik pokładał w nim ufność, czyniąc nieme bożki?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 19, 'Biada temu, który mówi do drewna: Przebudź się, a do niemego kamienia: Obudź się! Czyż on może nauczać? Spójrz na niego, jest powleczony złotem i srebrem, ale nie ma w nim żadnego ducha.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 20, 'Pan jest w swoim świętym przybytku. Niech cała ziemia zamilknie przed nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 1, 'Modlitwa proroka Habakuka na Syggajon.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 2, 'Panie, usłyszałem twoją wieść i uląkłem się. Panie, ożyw swoje dzieło w środku lat, objaw je w środku lat; w gniewie pamiętaj o miłosierdziu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 3, 'Bóg szedł z Temanu, Święty z góry Paran, Sela! Jego majestat okrył niebiosa, ziemia była pełna jego chwały.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 4, 'Jego blask był jak światłość, rogi wychodziły z jego rąk, a tam była ukryta jego moc.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 5, 'Przed nim szła zaraza, płonące węgle szły przed jego nogami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 6, 'Stanął i zmierzył ziemię, spojrzał i rozproszył narody; góry wieczyste zostały skruszone, skłoniły się pagórki dawne. Jego drogi są wieczne.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 7, 'Widziałem namioty Kuszanu dotknięte uciskiem, a zasłony ziemi Midian drżały.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 8, 'Czy Pan rozgniewał się przeciwko rzekom? Czy skierowałeś przeciwko rzekom swój gniew? Czy przeciwko morzu zwróciło się twoje oburzenie, gdy jechałeś na swoich koniach i na swoich rydwanach zbawienia?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 9, 'Twój łuk został obnażony z powodu przysięgi wypowiedzianej pokoleniom. Sela. Podzieliłeś ziemię rzekami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 10, 'Widziały cię góry i zadrżały, ulewa wód przeminęła. Przepaść wydała swój głos, wysoko podniosła swoje ręce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 11, 'Słońce i księżyc zatrzymały się w swoim przybytku, szli przy blasku twoich strzałów i przy blasku twojej lśniącej włóczni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 12, 'W gniewie deptałeś ziemię, w zapalczywości młóciłeś pogan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 13, 'Wyruszyłeś, aby wybawić swój lud, by ze swoim pomazańcem go wybawić; zraniłeś głowę z domu niegodziwego, odkrywając fundament aż do szyi. Sela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 14, 'Jego oszczepami przebiłeś głowę jego wsi; burzyli się jak wicher, aby mnie rozproszyć; cieszyli się, jakby mieli potajemnie pożreć ubogiego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 15, 'Jechałeś przez morze na swoich koniach, przez skupisko wielkich wód.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 16, 'Gdy to usłyszałem, zatrzęsło się moje wnętrze, na ten głos zadrżały moje wargi. Zgnilizna przeniknęła moje kości i cały się trząsłem, słysząc, że mam odpocząć w dniu utrapienia. Gdy nadciągnie na ten lud, zgładzi ich swoim wojskiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 17, 'Choćby drzewo figowe nie zakwitło i nie było plonu w winnicach, choćby i owoc oliwy zawiódł, i pola nie przyniosły żywności, trzoda zniknęła z owczarni, i nie było bydła w oborach;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 18, 'Ja jednak będę się radował w Panu, rozraduję się w Bogu mojego zbawienia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 19, 'Pan Bóg jest moją siłą i uczyni moje nogi jak nogi łań, i sprawi, że będę chodzić po wyżynach. Przewodnikowi chóru, na moje instrumenty strunowe.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 1, 'Słowo Pana, które doszło do Sofoniasza, syna Kusziego, syna Gedaliasza, syna Amariasza, syna Ezechiasza, za dni Jozjasza, syna Amona, króla Judy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 2, 'Zgładzę całkowicie wszystko z powierzchni tej ziemi, mówi Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 3, 'Zgładzę ludzi i zwierzęta, zgładzę ptactwo niebieskie i ryby morskie, i zgorszenia wraz z bezbożnymi. Wykorzenię człowieka z powierzchni tej ziemi, mówi Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 4, 'Wyciągnę bowiem swoją rękę na Judę i na wszystkich mieszkańców Jerozolimy; wykorzenię z tego miejsca pozostałości Baala i imiona bałwochwalczych kapłanów wraz z kapłanami;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 5, 'I tych, którzy na dachach oddają pokłon wojsku niebieskiemu; i tych, którzy oddają pokłon, przysięgając na Pana i na Milkoma;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 6, 'I tych, którzy się odwracają od naśladowania Pana i którzy nie szukali Pana ani o niego nie pytali.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 7, 'Umilknij przed obliczem Pana Boga, gdyż bliski jest dzień Pana. Pan bowiem przygotował ofiarę i poświęcił swoich zaproszonych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 8, 'I stanie się w dniu ofiary Pana, że ukarzę książąt i synów króla oraz wszystkich, którzy się ubierają w szaty cudzoziemskie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 9, 'Ukarzę też w tym dniu tych, którzy przeskakują próg, którzy napełniają domy swoich panów grabieżą i bezprawiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 10, 'W tym dniu, mówi Pan, będzie słychać głos wołania od Bramy Rybnej, zawodzenie od drugiej strony miasta i wielki trzask od pagórków.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 11, 'Zawódźcie, mieszkańcy Maktesz, bo będzie zniszczony cały lud kupiecki, będą wykorzenieni wszyscy, którzy noszą srebro.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 12, 'I stanie się w tym czasie, że będę przeszukiwał Jerozolimę z pochodniami i ukarzę mężczyzn, którzy spoczywali na swoich drożdżach, mówiąc w swoim sercu: Pan nie uczyni dobrze ani źle nie uczyni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 13, 'Dlatego ich mienie będzie łupem, a ich domy – spustoszeniem. Pobudują domy, lecz nie będą w nich mieszkać; zasadzą winnice, ale nie będą pić z nich wina.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 14, 'Bliski jest wielki dzień Pana, bliski jest i bardzo szybko nadchodzi głos dnia Pana. Tam nawet mocarz zawoła gorzko.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 15, 'Ten dzień będzie dniem gniewu, dniem utrapienia i ucisku, dniem ruiny i spustoszenia, dniem ciemności i mroku, dniem obłoku i gęstych chmur;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 16, 'Dniem trąby i trąbienia przeciwko miastom warownym i przeciwko basztom wysokim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 17, 'Ścisnę ludzi utrapieniem, tak że będą chodzić jak ślepi, ponieważ zgrzeszyli przeciwko Panu. Ich krew będzie rozlana jak proch, a ich ciała – jak gnój.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 18, 'Ani ich srebro, ani ich złoto nie zdołają ich wybawić w dniu gniewu Pana, bo cała ziemia będzie pożarta ogniem jego zapalczywości. Z pewnością bowiem dokona rychłego końca wszystkich mieszkańców ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 1, 'Zbierzcie się, zbierzcie, narodzie wstrętny;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 2, 'Zanim wyjdzie dekret i dzień przeminie jak plewy; zanim przyjdzie na was zapalczywość gniewu Pana, zanim przyjdzie na was dzień gniewu Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 3, 'Szukajcie Pana, wszyscy pokorni ziemi, którzy wypełniacie jego prawo; szukajcie sprawiedliwości, szukajcie pokory, może ukryjecie się w dniu gniewu Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 4, 'Gaza bowiem będzie opuszczona i Aszkelon spustoszony, Aszdod w południe wyrzucą, a Ekron będzie wykorzeniony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 5, 'Biada mieszkańcom wybrzeża morskiego, narodowi Keretytów! Słowo Pana jest przeciwko wam, Kanaanie, ziemio Filistynów; wytracę cię tak, że nie będzie żadnego mieszkańca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 6, 'Wybrzeże morskie będzie przeznaczone na schroniska i budki dla pasterzy, i na zagrody dla trzód.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 7, 'Wybrzeże też przypadnie reszcie domu Judy i będą na nim wypasać. W domach Aszkelonu będą się kłaść wieczorem, gdyż nawiedzi ich Pan, ich Bóg, i odwróci ich niewolę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 8, 'Słyszałem obelgi Moabu i lżenie synów Ammona, którymi urągali mojemu ludowi i wynosili się na jego granicach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 9, 'Dlatego jak żyję, mówi Pan zastępów, Bóg Izraela, Moab stanie się jak Sodoma, a synowie Ammona jak Gomora – miejscem pokrzyw, dołem soli i pustynią aż na wieki. Resztka mego ludu złupi ich i pozostali z mego ludu posiądą ich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 10, 'To ich spotka za ich pychę, gdyż lżyli i wynosili się nad lud Pana zastępów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 11, 'Pan okaże się dla nich straszny, bo sprawi, że zmarnieją wszyscy bogowie ziemi; i wszystkie wyspy pogan będą mu oddawać pokłon, każdy ze swego miejsca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 12, 'Wy też, Etiopczycy, będziecie pobici moim mieczem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 13, 'Wyciągnie bowiem swoją rękę na północ i wytraci Asyrię; zamieni Niniwę w spustoszenie i suchy obszar jak pustynię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 14, 'I będą się w niej wylegiwać trzody, wszelkie zwierzęta narodów; i pelikan, i bąk na głowicach jej kolumn będą nocować, ich głos będzie słychać w oknach, jej filary spustoszą, gdyż zerwą cedrowe obicie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 15, 'Takie będzie to wesołe miasto, które mieszkało bezpiecznie i mówiło w swoim sercu: Ja jestem i oprócz mnie nie ma innego. Jakże stało się spustoszeniem, legowiskiem zwierząt! Każdy, kto będzie przechodził obok niego, zaświśnie i machnie ręką.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 1, 'Biada brudnemu i splugawionemu miastu ucisku!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 2, 'Nie słuchało głosu ani nie przyjmuje upomnienia, nie zaufało Panu, nie zbliżyło się do swego Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 3, 'Jego książęta pośrodku niego są lwami ryczącymi, jego sędziowie są wilkami nocnymi, które nie gryzą kości aż do rana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 4, 'Jego prorocy są lekkomyślni, to ludzie przewrotni; jego kapłani zbezcześcili świątynię, pogwałcili prawo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 5, 'Pan sprawiedliwy jest pośród niego, nie czyni nieprawości; każdego poranka wystawia swój sąd na światłość i nie zawodzi; lecz złośnik nie zna wstydu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 6, 'Wykorzeniłem narody, ich baszty są spustoszone, spustoszyłem ich ulice, tak że nikt nie przechodzi. Ich miasta są zniszczone, tak że nie ma ani człowieka, ani żadnego mieszkańca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 7, 'Powiedziałem: Teraz na pewno będziesz się mnie bać, przyjmiesz upomnienie, aby nie zostało zniszczone twoje mieszkanie, jakkolwiek cię ukarzę. Ale wstali rano i psuli wszystkie swoje czyny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 8, 'Dlatego oczekujcie mnie, mówi Pan, do dnia, w którym powstanę do łupu. Postanowiłem bowiem zebrać narody i zgromadzić królestwa, aby wylać na nie swoje rozgniewanie, całą zapalczywość swojego gniewu. Zaprawdę, cała ziemia będzie pożarta ogniem mojej gorliwości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 9, 'Wówczas bowiem przywrócę narodom czyste wargi, aby wszyscy wzywali imienia Pana i służyli mu jednomyślnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 10, 'Zza rzek Etiopii przyniosą mi dary moi czciciele, córa moich rozproszonych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 11, 'W tym dniu nie zawstydzisz się z powodu wszystkich twoich uczynków, którymi wystąpiłeś przeciwko mnie. Wtedy bowiem usunę spośród ciebie tych, którzy chełpią się twoją sławą, i już nie będziesz się wywyższać na mojej świętej górze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 12, 'I pozostawię pośród ciebie lud ubogi i nędzny, i będzie ufać imieniu Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 13, 'Resztka Izraela nie będzie czynić nieprawości ani nie będzie mówić kłamstwa; nie znajdzie się w jej ustach język zdradliwy. Ale będzie się paść i odpoczywać, a nikt nie będzie jej straszyć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 14, 'Zaśpiewaj, córko Syjonu! Wykrzykuj, Izraelu! Ciesz się i raduj z całego serca, córko Jerozolimy!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 15, 'Pan oddalił twoje sądy, usunął twojego wroga. Król Izraela, Pan, jest pośród ciebie. Nie będziesz już oglądał zła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 16, 'W tym dniu powiedzą do Jerozolimy: Nie bój się! A do Syjonu: Niech nie mdleją twoje ręce!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 17, 'Pan, twój Bóg, pośród ciebie jest potężny; on cię zbawi i rozraduje się wielce nad tobą; będzie się cieszyć ze swojej miłości wobec ciebie i rozweseli się nad tobą ze śpiewaniem, mówiąc:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 18, 'Zbiorę tęskniących za uroczystym zgromadzeniem, bo wśród ciebie są też smutni z powodu brzemienia zniewagi włożonego na ciebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 19, 'Oto w tym czasie uczynię kres wszystkim, którzy cię trapią, a zbawię chromą i zgromadzę wygnaną; okryję ich chwałą i imieniem w całej ziemi, w której doznawali hańby.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 20, 'W tym czasie przyprowadzę was, w tym czasie, mówię, zgromadzę was. Dam wam bowiem imię i chwałę pośród wszystkich narodów ziemi, gdy na waszych oczach odwrócę waszą niewolę – mówi Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 1, 'W drugim roku króla Dariusza, w szóstym miesiącu, pierwszego dnia tego miesiąca, słowo Pana doszło przez proroka Aggeusza do Zorobabela, syna Szealtiela, namiestnika Judy, i do Jozuego, syna Josadaka, najwyższego kapłana, mówiące:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 2, 'Tak mówi Pan zastępów: Ten lud powiada: Jeszcze nie nadszedł czas, czas budowania domu Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 3, 'Wówczas słowo Pana doszło przez proroka Aggeusza mówiące:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 4, 'A czy dla was jest to czas, abyście mieszkali w swoich domach wyłożonych deskami, podczas gdy ten dom leży opustoszały?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 5, 'Teraz więc tak mówi Pan zastępów: Zastanówcie się nad swoimi drogami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 6, 'Siejecie wiele, a mało zbieracie; jecie, ale się nie nasycacie; pijecie, ale nie gasicie pragnienia; ubieracie się, lecz nikt nie może się ogrzać, a ten, kto gromadzi zarobek, gromadzi go w dziurawym worku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 7, 'Tak mówi Pan zastępów: Zastanówcie się nad swoimi drogami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 8, 'Wstąpcie na tę górę i sprowadźcie drewno; zbudujcie ten dom, a upodobam go sobie i będę uwielbiony, mówi Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 9, 'Liczyliście na wiele, a oto było tego mało, a to, co przynieśliście do domu, ja rozdmuchałem. Dlaczego? – mówi Pan zastępów. Dlatego że mój dom jest pusty, podczas gdy każdy z was troszczy się o swój dom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 10, 'Dlatego niebo wstrzymało nad wami rosę, a ziemia wstrzymała wydawanie swego plonu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 11, 'Sprowadziłem suszę na tę ziemię, na te góry, na pszenicę, na moszcz i na oliwę, na to, co ziemia wydaje, na ludzi i na bydło, i na wszelką pracę rąk.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 12, 'Wtedy Zorobabel, syn Szealtiela, i najwyższy kapłan Jozue, syn Josadaka, oraz cała resztka ludu wysłuchali głosu Pana, swego Boga, i słów proroka Aggeusza, ponieważ posłał go Pan, ich Bóg, a lud bał się Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 13, 'Wtedy Aggeusz, posłaniec Pana, przemówił do ludu, głosząc przesłanie Pana: Ja jestem z wami, mówi Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 14, 'I Pan wzbudził ducha Zorobabela, syna Szealtiela, namiestnika Judy, i ducha Jozuego, syna Josadaka, najwyższego kapłana, oraz ducha całej reszty ludu, tak że przyszli i podjęli pracę przy domu Pana zastępów, swego Boga;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 15, 'Dnia dwudziestego czwartego, szóstego miesiąca, w drugim roku króla Dariusza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 1, 'W siódmym miesiącu, dwudziestego pierwszego dnia tego miesiąca, słowo Pana doszło przez proroka Aggeusza mówiące:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 2, 'Mów teraz do Zorobabela, syna Szealtiela, namiestnika Judy, i do Jozuego, syna Josadaka, najwyższego kapłana, oraz do reszty ludu:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 3, 'Któż pozostał pośród was, który widział ten dom w jego dawnej chwale? A jakim go teraz widzicie? Czy nie wydaje się wam, że jest niczym w porównaniu z tamtym?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 4, 'Teraz jednak umocnij się, Zorobabelu, mówi Pan; umocnij się, Jozue, synu Josadaka, najwyższy kapłanie; umocnij się też, cały ludu tej ziemi, mówi Pan, i pracujcie. Ja bowiem jestem z wami, mówi Pan zastępów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 5, 'Zgodnie ze słowem, przez które zawarłem z wami przymierze, gdy wyszliście z Egiptu, mój Duch jest stale wśród was, nie bójcie się.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 6, 'Tak bowiem mówi Pan zastępów: Jeszcze raz, po krótkim czasie, wstrząsnę niebem i ziemią, morzem i lądem;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 7, 'Wstrząsnę wszystkimi narodami i przyjdzie Pożądany przez wszystkie narody. I napełnię ten dom chwałą, mówi Pan zastępów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 8, 'Moje jest srebro i moje jest złoto, mówi Pan zastępów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 9, 'Chwała tego domu będzie większa od tej, jaką miał tamten dawny, mówi Pan zastępów; bo to miejsce obdarzę pokojem, mówi Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 10, 'Dnia dwudziestego czwartego, dziewiątego miesiąca, w drugim roku Dariusza, słowo Pana doszło przez proroka Aggeusza mówiące:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 11, 'Tak mówi Pan zastępów: Zapytaj teraz kapłanów o prawo:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 12, 'Gdyby ktoś niósł poświęcone mięso włożone za połę swojej szaty, a połą dotknął chleba, potrawy, wina, oliwy lub jakiegokolwiek pokarmu, czy to stałoby się poświęcone? Odpowiedzieli kapłani: Nie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 13, 'Wtedy Aggeusz zapytał: Jeśli ktoś, będąc nieczysty od zwłok, dotknie którejś z tych rzeczy, czy staje się ona nieczysta? Odpowiedzieli kapłani: Stanie się nieczysta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 14, 'Wtedy Aggeusz odezwał się i powiedział: Taki jest ten lud, taki jest ten naród przede mną, mówi Pan; takie jest każde dzieło ich rąk; i wszystko, co tam składają w ofierze, jest nieczyste.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 15, 'Teraz więc, proszę, zastanówcie się, jak się wam powodziło od dzisiejszego dnia do minionych dni, zanim ułożono kamień na kamieniu w świątyni Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 16, 'Dawniej, gdy ktoś przyszedł do stosu zboża z dwudziestu miar, było ich tylko dziesięć; gdy przyszedł do prasy, aby naczerpać pięćdziesiąt wiader wina, było ich tylko dwadzieścia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 17, 'Karałem was suszą, pleśnią i gradem we wszystkich dziełach waszych rąk; lecz żaden z was nie wrócił do mnie, mówi Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 18, 'Zastanówcie się teraz nad okresem od dzisiejszego dnia po dni minione, od dnia dwudziestego czwartego, dziewiątego miesiąca, to znaczy od dnia, w którym położono fundament świątyni Pana; zastanówcie się.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 19, 'Czy ziarno jeszcze jest w spichlerzu? I owszem ani winorośl, ani drzewo figowe, granatowe i oliwne nie wydały jeszcze owocu. Od tego dnia będę wam błogosławił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 20, 'Potem słowo Pana doszło po raz drugi do Aggeusza dnia dwudziestego czwartego tego miesiąca mówiące:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 21, 'Mów do Zorobabela, namiestnika Judy: Ja wstrząsnę niebiosami i ziemią;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 22, 'I przewrócę tron królestw, i zniszczę moc królestw pogan; przewrócę także rydwany i tych, którzy na nich jeżdżą; i upadną konie i ich jeźdźcy, każdy od miecza swego brata.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 23, 'W tym dniu, mówi Pan zastępów, wezmę cię, Zorobabelu, mój sługo, synu Szealtiela, mówi Pan, i uczynię cię niczym sygnet. Ja bowiem wybrałem ciebie, mówi Pan zastępów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 1, 'W ósmym miesiącu drugiego roku Dariusza słowo Pana doszło do Zachariasza, syna Berechiasza, syna Iddo proroka, mówiące:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 2, 'Pan bardzo się rozgniewał na waszych ojców.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 3, 'Dlatego powiedz im: Tak mówi Pan zastępów: Powróćcie do mnie, mówi Pan zastępów, a ja powrócę do was, mówi Pan zastępów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 4, 'Nie bądźcie jak wasi ojcowie, do których wołali dawni prorocy, mówiąc: Tak mówi Pan zastępów: Odwróćcie się teraz od waszych złych dróg i od waszych złych uczynków. Ale oni nie usłuchali ani nie zważali na mnie, mówi Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 5, 'Gdzie są wasi ojcowie? A prorocy, czy żyją wiecznie?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 6, 'Czyż jednak moje słowa i ustawy, które rozkazałem moim sługom, prorokom, nie dotarły do waszych ojców? Powrócili i powiedzieli: Jak Pan zastępów zamierzył uczynić nam według naszych dróg i naszych uczynków, tak nam uczynił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 7, 'Dnia dwudziestego czwartego, jedenastego miesiąca, czyli w miesiącu Szebat, w drugim roku Dariusza, słowo Pana doszło do Zachariasza, syna Berechiasza, syna proroka Iddo, mówiące:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 8, 'Widziałem w nocy, a oto mąż jechał na rudym koniu, który stał wśród mirtów, które były na nizinie, a za nim konie rude, pstrokate i białe.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 9, 'Wtedy zapytałem: Kim oni są, mój panie? I Anioł, który rozmawiał ze mną, odpowiedział mi: Ja ci pokażę, kim oni są.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 10, 'I mąż, który stał wśród mirtów, odpowiedział: To są ci, których Pan posłał, aby obeszli ziemię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 11, 'I odpowiedzieli Aniołowi Pana stojącemu wśród mirtów: Obeszliśmy ziemię, a oto cała ziemia żyje bezpiecznie i zażywa pokoju.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 12, 'Wtedy Anioł Pana odpowiedział: Panie zastępów, jak długo jeszcze nie będziesz się litował nad Jerozolimą i nad miastami Judy, na które się gniewasz już siedemdziesiąt lat?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 13, 'Pan odpowiedział Aniołowi, który rozmawiał ze mną, słowami dobrymi, słowami pociechy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 14, 'Potem Anioł, który rozmawiał ze mną, powiedział: Wołaj i mów: Tak mówi Pan zastępów: Zapłonąłem wielką gorliwością o Jerozolimę i o Syjon.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 15, 'A bardzo się gniewam na te narody, które zażywają pokoju, bo gdy się trochę gniewałem, one wtedy przyczyniły się do nieszczęścia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 16, 'Dlatego tak mówi Pan: Zwróciłem się do Jerozolimy w miłosierdziu, mój dom zostanie w niej zbudowany, mówi Pan zastępów, i sznur będzie rozciągnięty nad Jerozolimą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 17, 'Wołaj jeszcze: Tak mówi Pan zastępów: Moje miasta jeszcze się rozciągną z powodu obfitości dobra, Pan jeszcze pocieszy Syjon i jeszcze wybierze Jerozolimę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 18, 'Wtedy podniosłem swe oczy i spojrzałem, a oto cztery rogi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 19, 'I zapytałem Anioła, który rozmawiał ze mną: Cóż to jest? I odpowiedział mi: To są rogi, które rozproszyły Judę, Izraela i Jerozolimę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 20, 'Następnie Pan ukazał mi czterech kowali.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 21, 'I zapytałem: Co oni przyszli czynić? I odpowiedział: To są rogi, które rozproszyły Judę, tak że nikt nie mógł podnieść swojej głowy. Dlatego oni przyszli, aby je przestraszyć i strącić rogi tych narodów, które podniosły swoje rogi przeciwko ziemi Judy, aby ją rozproszyć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 1, 'Potem znowu podniosłem swoje oczy i spojrzałem, a oto mężczyzna, w którego ręce był sznur mierniczy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 2, 'I zapytałem: Dokąd idziesz? Odpowiedział mi: Idę zmierzyć Jerozolimę, by zobaczyć, jaka jest jej szerokość i jaka jej długość.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 3, 'A oto gdy Anioł, który rozmawiał ze mną, odchodził, inny anioł wyszedł mu naprzeciw.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 4, 'I powiedział do niego: Biegnij i powiedz temu młodzieńcowi: Jerozolima będzie zamieszkana jak miasta bez murów ze względu na mnóstwo ludu i bydła w niej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 5, 'A ja, mówi Pan, będę dla niej murem ognistym dokoła i będę chwałą pośród niej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 6, 'Hej, hej! Uciekajcie z ziemi północnej, mówi Pan, ponieważ rozproszyłem was na cztery strony świata, mówi Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 7, 'Ratuj się, o Syjonie, który mieszkasz u córki Babilonu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 8, 'Tak bowiem mówi Pan zastępów – posłał mnie na chwałę do tych narodów, które was ograbiły, bo kto was dotyka, dotyka źrenicy jego oka;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 9, 'Oto podniosę swoją rękę przeciwko nim i staną sią łupem dla swoich sług. I poznacie, że Pan zastępów mnie posłał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 10, 'Zaśpiewaj i raduj się, córko Syjonu, bo oto przyjdę i zamieszkam pośród ciebie, mówi Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 11, 'Wiele narodów przyłączy się w tym dniu do Pana i będą moim ludem, a ja zamieszkam pośród ciebie i poznasz, że Pan zastępów posłał mnie do ciebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 12, 'Wtedy Pan weźmie Judę w posiadanie jako swój dział w ziemi świętej i znowu wybierze Jerozolimę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 13, 'Niech umilknie wszelkie ciało przed Panem. On bowiem powstał ze swego świętego przybytku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 1, 'Potem ukazał mi Jozuego, najwyższego kapłana, który stał przed Aniołem Pana, i szatana stojącego po jego prawicy, aby mu się sprzeciwiać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 2, 'Ale Pan powiedział do szatana: Niech cię Pan zgromi, szatanie! Niech cię skarci Pan, który wybrał Jerozolimę. Czyż nie jest on jak głownia wyrwana z ognia?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 3, 'A Jozue był ubrany w brudne szaty i stał przed Aniołem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 4, 'Ten odezwał się do tych, którzy stali przed nim, i powiedział: Zdejmijcie z niego te brudne szaty. Do niego zaś powiedział: Oto zdjąłem z ciebie twoją nieprawość i oblekłem cię w inne szaty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 5, 'Powiedział jeszcze: Niech włożą mu na głowę piękną mitrę. Włożyli więc piękną mitrę na jego głowę i oblekli go w szaty, a Anioł Pana stał obok.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 6, 'Potem Anioł Pana oświadczył Jozuemu:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 7, 'Tak mówi Pan zastępów: Jeśli będziesz chodził moimi drogami i jeśli będziesz przestrzegał moich ustaw, wtedy też będziesz sądził mój dom i będziesz strzegł moich dziedzińców, i pozwolę ci chodzić wśród tych, którzy tu stoją.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 8, 'Słuchaj więc teraz, Jozue, najwyższy kapłanie, ty i twoi towarzysze, którzy siedzą przed tobą. Są oni bowiem jakby ludźmi niezwykłymi, gdyż oto przywiodę swojego sługę – Latorośl.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 9, 'Oto bowiem ten kamień, który kładę przed Jozuem: na tym jednym kamieniu będzie siedmioro oczu. Oto wykonam na nim ryt, mówi Pan zastępów, i zgładzę nieprawość tej ziemi w jednym dniu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 10, 'W tym dniu, mówi Pan zastępów, każdy wezwie swego bliźniego pod winoroślą i pod drzewem figowym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 1, 'Potem Anioł, który rozmawiał ze mną, powrócił i obudził mnie, jak budzi się kogoś ze snu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 2, 'I zapytał mnie: Co widzisz? Odpowiedziałem: Spojrzałem, a oto świecznik cały ze złota, a na jego szczycie jest czasza, na nim siedem lamp, a także siedem rurek do tych siedmiu lamp, które są na jego szczycie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 3, 'Dwa drzewa oliwne obok niego, jedno po prawej stronie czaszy, a drugie po jej lewej stronie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 4, 'Wtedy odezwałem się do Anioła, który rozmawiał ze mną, i zapytałem: Co to jest, mój Panie?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 5, 'Anioł, który rozmawiał ze mną, odpowiedział mi: Czy nie wiesz, co to jest? Odpowiedziałem: Nie wiem, mój Panie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 6, 'Wtedy odpowiedział mi: Oto słowo Pana do Zorobabela: Nie wojskiem ani siłą, ale moim Duchem, mówi Pan zastępów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 7, 'Czymże ty jesteś, góro wielka? Wobec Zorobabela staniesz się równiną. On bowiem wyniesie główny kamień z głośnym okrzykiem: Łaska, łaska nad nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 8, 'I doszło słowo Pana do mnie mówiące:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 9, 'Ręce Zorobabela położyły fundamenty tego domu, jego ręce go dokończą; a poznasz, że Pan zastępów posłał mnie do was.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 10, 'Któż bowiem wzgardził dniem małych początków? Oni bowiem będą się radować, patrząc na pion w ręku Zorobabela i na tych siedmioro oczu Pana, które przebiegają całą ziemię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 11, 'Wtedy odezwałem się i zapytałem go: Co oznaczają te dwa drzewa oliwne po prawej i lewej stronie tego świecznika?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 12, 'I ponownie odezwałem się, i zapytałem go: Co oznaczają te dwie gałęzie oliwne, które dwiema złotymi rurkami wypuszczają z siebie złocistą oliwę?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 13, 'On zapytał: Nie wiesz, co to jest? Odpowiedziałem: Nie wiem, mój Panie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 14, 'Wtedy powiedział: To są dwaj pomazańcy, którzy stoją przed Panem całej ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 1, 'Potem odwróciłem się i gdy podniosłem swe oczy, spojrzałem, a oto latający zwój.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 2, 'I zapytał mnie: Co widzisz? Odpowiedziałem: Widzę latający zwój, jego długość dwadzieścia łokci, a jego szerokość dziesięć łokci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 3, 'Wtedy powiedział do mnie: To jest przekleństwo, które wyjdzie na całą powierzchnię ziemi. Każdy złodziej bowiem zostanie wykorzeniony według przekleństwa z tej strony i każdy krzywoprzysięzca zostanie wykorzeniony według przekleństwa z drugiej strony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 4, 'Wyprowadzę je, mówi Pan zastępów, aby weszło do domu złodzieja i do domu tego, kto krzywo przysięga na moje imię. Pozostanie w jego domu i zniszczy go wraz z jego drewnem i kamieniem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 5, 'Wtedy wyszedł Anioł, który ze mną rozmawiał, i powiedział mi: Podnieś teraz swoje oczy i zobacz, co to jest, co wychodzi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 6, 'Zapytałem: Co to jest? On odpowiedział: To, co wychodzi, to efa. I dodał: Taki jest ich wygląd w całej ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 7, 'A oto podniósł się talent ołowiu, a przy tym była kobieta, która siedziała wewnątrz efy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 8, 'Wtedy Anioł powiedział: To jest bezbożność. I wrzucił ją do wnętrza efy, wrzucił także do otworu efy ten talent ołowiu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 9, 'Potem podniosłem swoje oczy i spojrzałem, a oto wyszły dwie kobiety mające wiatr pod swoimi skrzydłami, a ich skrzydła przypominały skrzydła bocianie. I podniosły efę między ziemią i niebem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 10, 'Wtedym zapytałem tego Anioła, który rozmawiał ze mną: Dokąd niosą tę efę?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 11, 'Powiedział mi: By zbudować dla niej dom w ziemi Szinear, a gdy będzie założony, postawią ją na jej własnej podstawie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 1, 'Potem odwróciłem się, podniosłem swoje oczy i spojrzałem, a oto cztery rydwany wychodziły spomiędzy dwóch gór, a te góry były z miedzi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 2, 'Przy pierwszym rydwanie były konie rude, przy drugim rydwanie – konie kare;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 3, 'Przy trzecim rydwanie – konie białe, a przy czwartym rydwanie były konie pstrokate i gniade.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 4, 'Wtedy zapytałem Anioła, który rozmawiał ze mną: Co to jest, mój Panie?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 5, 'I Anioł odpowiedział mi: To są cztery duchy nieba, wyruszają one z miejsca, gdzie stały przed Panem całej ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 6, 'Zaprzężone konie kare wyruszają do ziemi północnej, białe wyruszają za nimi, pstrokate zaś wyruszają do ziemi południowej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 7, 'A te gniade konie wyruszyły, rwały się do biegu, aby obejść ziemię. Wtedy powiedział: Idźcie i obejdźcie ziemię! I obeszły ziemię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 8, 'Potem zawołał mnie i powiedział: Oto te, które wyruszyły do ziemi północnej, uspokoiły mojego ducha w ziemi północnej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 9, 'I doszło do mnie słowo Pana mówiące:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 10, 'Weź dary od tych, co byli w niewoli: od Cheldaja, od Tobiasza i od Jedajasza, którzy przybyli z Babilonu, i przyjdź w tym samym dniu, i wejdź do domu Jozjasza, syna Sofoniasza;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 11, 'Weź srebro i złoto, zrób korony i włóż je na głowę Jozuego, syna Josadaka, najwyższego kapłana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 12, 'I powiedz do niego: Tak mówi Pan zastępów: Oto mąż, którego imię brzmi Latorośl; on wyrośnie ze swego miejsca i zbuduje świątynię Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 13, 'On zbuduje świątynię Pana, będzie obdarzony chwałą, zasiądzie na swoim tronie i będzie panować na nim, i będzie on kapłanem na swoim tronie; i rada pokoju będzie między nimi oboma.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 14, 'A te korony będą dla Chelema, Tobiasza, Jedajasza i Chena, syna Sofoniasza, jako pamiątka w świątyni Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 15, 'Przyjdą ludzie z dalekich stron i będą budować świątynię Pana, i poznacie, że Pan zastępów posłał mnie do was. A to się stanie, jeśli pilnie będziecie słuchać głosu Pana, swego Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 1, 'W czwartym roku króla Dariusza słowo Pana doszło do Zachariasza, czwartego dnia dziewiątego miesiąca, to jest w miesiącu Kislew;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 2, 'Gdy lud posłał do domu Bożego Saresera i Regem-Meleka z ich ludźmi, aby się modlili przed Panem;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 3, 'I aby zapytali kapłanów, którzy byli w domu Pana zastępów, a także proroków: Czy w piątym miesiącu mam jeszcze płakać, poświęcając się, jak to już czyniłem przez tyle lat?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 4, 'Doszło do mnie słowo Pana zastępów mówiące:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 5, 'Powiedz do całego ludu tej ziemi i do kapłanów: Gdy pościliście i płakaliście w piątym i siódmym miesiącu przez te siedemdziesiąt lat, czy pościliście dla mnie?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 6, 'A gdy jecie i pijecie, czy nie dla siebie jecie i nie dla siebie pijecie?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 7, 'Czy nie należało raczej czynić według słowa, które Pan głosił przez dawnych proroków, gdy Jerozolima była jeszcze zamieszkana i zażywała pokoju, a także jej okoliczne miasta, gdy południe i równina były zamieszkane?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 8, 'I słowo Pana doszło do Zachariasza mówiące:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 9, 'Tak mówi Pan zastępów: Sądźcie sprawiedliwie i okazujcie miłosierdzie i litość, każdy swojemu bratu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 10, 'Nie uciskajcie wdowy i sieroty, obcego i ubogiego i nie obmyślajcie zła w swoich sercach, jedni przeciwko drugim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 11, 'Ale oni nie chcieli słuchać i odwrócili się plecami, i zatkali swoje uszy, aby nie słyszeć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 12, 'Zatwardzili swoje serca jak diament, aby nie słuchać prawa i słów, które posyłał Pan zastępów przez swego Ducha za pośrednictwem dawnych proroków. Dlatego nadszedł wielki gniew od Pana zastępów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 13, 'I stało się tak, że podobnie jak gdy on wołał, a oni nie słuchali, tak też gdy oni wołali, ja ich nie wysłuchałem, mówi Pan zastępów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 14, 'I rozproszyłem ich wichrem pomiędzy wszystkimi narodami, których nie znali, a ta ziemia opustoszała po nich, tak że nikt nie przechodził ani nie wracał. Zamienili bowiem rozkoszną ziemię w spustoszenie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 1, 'Potem doszło do mnie słowo Pana zastępów mówiące:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 2, 'Tak mówi Pan zastępów: Byłem zazdrosny o Syjon w wielkiej gorliwości, byłem zazdrosny w wielkim gniewie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 3, 'Tak mówi Pan: Wróciłem na Syjon i zamieszkam w Jerozolimie; a Jerozolima będzie nazwana Miastem Wiernym, a góra Pana zastępów – Górą Świętą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 4, 'Tak mówi Pan zastępów: Jeszcze siadać będą starcy i staruszki na ulicach Jerozolimy, każdy z nich z laską w ręku z powodu podeszłego wieku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 5, 'I ulice miasta będą pełne bawiących się na nich chłopców i dziewcząt.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 6, 'Tak mówi Pan zastępów: Jeśli w tych dniach wyda się to niemożliwe w oczach resztki tego ludu, czy będzie to też niemożliwe w moich oczach? – mówi Pan zastępów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 7, 'Tak mówi Pan zastępów: Oto wybawię swój lud z ziemi wschodniej i z ziemi zachodniej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 8, 'Sprowadzę go i zamieszka w Jerozolimie, i będzie moim ludem, a ja będę jego Bogiem, w prawdzie i sprawiedliwości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 9, 'Tak mówi Pan zastępów: Niech się umocnią wasze ręce, wy, którzy słuchaliście w tych dniach słów z ust proroków, którzy byli w dniu, kiedy założono fundament domu Pana zastępów, aby świątynia została odbudowana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 10, 'Przed tymi dniami bowiem nie była wynagrodzona praca ludzka i praca bydląt. Dla wychodzących i wchodzących nie było pokoju z powodu wroga, bo ja podburzyłem wszystkich ludzi, jednych przeciwko drugim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 11, 'Lecz teraz nie uczynię z resztką tego ludu tak jak za dawnych dni, mówi Pan zastępów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 12, 'Ale siewy będą rosły w pokoju, winorośl wyda swój owoc, ziemia wyda swoje plony i niebiosa także spuszczą swoją rosę, a to wszystko dam resztce tego ludu w posiadanie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 13, 'I stanie się, że jak byliście przekleństwem wśród pogan, domu Judy i domu Izraela, tak was wybawię i będziecie błogosławieństwem. Nie bójcie się i niech się umocnią wasze ręce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 14, 'Tak bowiem mówi Pan zastępów: Jak postanowiłem ukarać was, gdy wasi ojcowie pobudzali mnie do gniewu, mówi Pan zastępów – i nie żałowałem tego;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 15, 'Tak znowu postanowiłem w tych dniach uczynić dobrze Jerozolimie i domowi Judy. Nie bójcie się.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 16, 'To są rzeczy, które będziecie czynić: Mówcie prawdę, każdy ze swoim bliźnim, wykonujcie sprawiedliwy i spokojny sąd w waszych bramach;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 17, 'Nie obmyślajcie zła w sercach waszych, jeden przeciwko drugiemu, i nie lubujcie się w krzywoprzysięstwie, gdyż tego wszystkiego nienawidzę, mówi Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 18, 'I doszło do mnie słowo Pana zastępów mówiące:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 19, 'Tak mówi Pan zastępów: Post w czwartym, piątym, siódmym i dziesiątym miesiącu zamienią się dla domu Judy w radość i wesele, i w rozkoszne święta. Miłujcie więc prawdę i pokój.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 20, 'Tak mówi Pan zastępów: Jeszcze będą przychodzić narody i mieszkańcy wielu miast.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 21, 'Mieszkańcy jednego miasta pójdą do drugiego, mówiąc: Pójdźmy ochoczo przebłagać oblicze Pana i szukać Pana zastępów. Ja także pójdę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 22, 'A tak liczne ludy i potężne narody przybędą szukać Pana zastępów w Jerozolimie i przebłagać oblicze Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 23, 'Tak mówi Pan zastępów: W tych dniach dziesięciu ludzi ze wszystkich języków narodów uchwyci się poły jednego Żyda, mówiąc: Pójdziemy z wami, bo usłyszeliśmy, że Bóg jest z wami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 1, 'Brzemię słowa Pana w ziemi Chadraku, a Damaszek będzie jego odpoczynkiem, gdyż Panu przypatrzą się oczy ludzi i wszystkich pokoleń Izraela;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 2, 'Nawet Chamat będzie miał z nim granicę, a także Tyr i Sydon, choć są bardzo mądre.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 3, 'Tyr bowiem zbudował sobie twierdzę i nagromadził srebra jak prochu, a złota jak błota na ulicach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 4, 'Oto Pan go wypędzi i wrzuci w morze jego siłę, on sam zostanie strawiony ogniem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 5, 'Ujrzy to Aszkelon i ulęknie się, podobnie Gaza – i pogrąży się w smutku; również Ekron, bo jego nadzieja zawiedzie. I zginie król z Gazy, a Aszkelon nie będzie zamieszkany.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 6, 'I bękart będzie mieszkał w Aszdodzie, a tak zniszczę pychę Filistynów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 7, 'Usunę krew każdego z jego ust i obrzydliwości spomiędzy jego zębów. Kto pozostanie, będzie należał do naszego Boga, aby był jak książę w Judzie i Ekron, jak Jebusyta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 8, 'I rozłożę obóz dokoła swego domu z powodu wojska i z powodu tych, którzy przechodzą i wracają. I już nie przejdzie przez nich żaden ciemięzca. Teraz bowiem widziały to moje oczy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 9, 'Raduj się wielce, córko Syjonu! Wykrzykuj, córko Jerozolimy! Oto twój Król przychodzi do ciebie; sprawiedliwy i Zbawiciel, cichy i siedzący na ośle, na oślątku, źrebięciu oślicy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 10, 'Zniszczę bowiem rydwany z Efraima i konie z Jerozolimy, a łuki wojenne będą połamane. I ogłosi pokój narodom, a jego władza będzie sięgać od morza aż do morza i od rzeki aż po krańce ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 11, 'A co do ciebie, ze względu na krew twego przymierza wypuściłem twoich więźniów z dołu, w którym nie ma wody.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 12, 'Wróćcie do twierdzy, więźniowie, którzy macie nadzieję. Dziś bowiem ogłaszam, że wynagrodzę w dwójnasób;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 13, 'Gdy jak łuk naciągnę Judę, a na nim nałożę Efraima; wzbudzę twoich synów, Syjonie, przeciwko twoim synom, Jawanie, i zrobię z ciebie miecz mocarza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 14, 'Pan bowiem ukaże się nad nimi i jak błyskawica wyleci jego strzała. Pan Bóg zadmie w trąbę i wyruszy w wichrach południa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 15, 'Pan zastępów będzie ochraniać swój lud; pochłoną i przemogą kamienie z procy, będą pić i krzyczeć jak od wina; i napełnią się jak czasza i jak rogi ołtarza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 16, 'W tym dniu Pan, ich Bóg, wybawi ich jak trzodę swego ludu. Będą bowiem jak kamienie w koronie, wystawieni jak sztandar w jego ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 17, 'Jak wielkie bowiem jest jego błogosławieństwo! Jak wspaniałe jego piękno! Zboże pocieszy młodzieńców, a moszcz – panny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 1, 'Proście Pana o deszcz w późnej porze deszczowej, a Pan stworzy chmury burzowe i da wam obfity deszcz i każdemu trawę na polu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 2, 'Bożki wypowiadają bowiem słowa próżności, a wróżbici prorokują kłamstwo i opowiadają zmyślone sny, daremnie pocieszają. Dlatego błąkali się jak trzoda, byli utrapieni, bo nie było pasterza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 3, 'Mój gniew zapłonął przeciwko tym pasterzom i ukarałem te kozły, ale Pan zastępów nawiedzi swoją trzodę, dom Judy, i uczyni z niej wspaniałego konia do boju.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 4, 'Od niego wywodzi się kamień węgielny, od niego gwóźdź, od niego łuk wojenny, od niego także wszelki poborca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 5, 'I będą jak mocarze, którzy wdeptują wroga w błoto uliczne podczas bitwy. I będą walczyć, bo Pan jest z nimi; a zawstydzą jeźdźców konnych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 6, 'Umocnię dom Judy, wybawię dom Józefa i sprowadzę ich z powrotem w pokoju, bo zlituję się nad nimi. I będą takimi, jak gdybym ich nie odrzucił. Ja bowiem jestem Pan, ich Bóg, i wysłucham ich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 7, 'Efraimici będą jak mocarz, ich serce rozweseli się jak od wina. Ich synowie to zobaczą i będą się cieszyć, a ich serce rozraduje się w Panu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 8, 'Zaświstam na nich i zgromadzę ich, bo ich odkupiłem; i będą tak liczni, jak byli dawniej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 9, 'I rozsieję ich wśród narodów, aby w dalekich krajach przypomnieli sobie o mnie, a żyjąc tam ze swoimi dziećmi, nawrócą się.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 10, 'Wyprowadzę ich znowu z ziemi Egiptu i zgromadzę ich z Asyrii, zaprowadzę do ziemi Gilead i do Libanu, ale nie starczy dla nich miejsca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 11, 'Przejdzie przez morze ucisku, rozbije fale na morzu i wyschną wszystkie głębie rzeki. Wtedy pycha Asyrii będzie poniżona, a berło Egiptu zniknie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 12, 'Umocnię ich też w Panu i będą chodzić w jego imię, mówi Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 1, 'Otwórz swe wrota, Libanie, niech ogień strawi twoje cedry.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 2, 'Zawódź, jodło, bo upadł cedr, bo wielcy są spustoszeni. Zawódźcie, dęby Baszanu, bo niedostępny las został wycięty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 3, 'Słychać głos narzekania pasterzy, bo ich wspaniałość została zburzona; słychać głos ryku lwiąt, bo pycha Jordanu jest zburzona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 4, 'Tak mówi Pan, mój Bóg: Paś owce przeznaczone na rzeź;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 5, 'Które kupcy zabijają, a nie czują się winni, a sprzedający je mówią: Błogosławiony Pan, że się wzbogaciłem. A ich pasterze nie mają dla nich litości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 6, 'Dlatego już nie będę miał litości dla mieszkańców tej ziemi, mówi Pan. Oto wydam tych ludzi, każdego z nich, w ręce jego bliźniego i w ręce jego króla. I zniszczą ziemię, a nikogo nie wyrwę z ich rąk.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 7, 'Będę więc pasł owce przeznaczone na rzeź, was, mówię, biedne owce! Wziąłem sobie dwie laski, jedną nazwałem Piękno, a drugą nazwałem Więzy, i pasłem te owce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 8, 'Zgładziłem trzech pasterzy w jednym miesiącu; i moja dusza czuła niechęć do nich, a ich dusza też brzydziła się mną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 9, 'Wtedy powiedziałem: Nie będę was pasł. Co umiera, niech umrze, a co ma być zgładzone, niech będzie zgładzone, a ci, co pozostaną, niech każdy pożera ciało drugiego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 10, 'Wziąłem więc swoją laskę, Piękno, i złamałem ją, aby zerwać swoje przymierze, które zawarłem z całym ludem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 11, 'I zostało zerwane w tym dniu, a biedni spośród trzody, którzy przyglądali się mnie, poznali, że to słowo Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 12, 'Potem powiedziałem do nich: Jeśli to jest dobre w waszych oczach, dajcie mi moją zapłatę, a jeśli nie, zaniechajcie jej. Odważyli więc moją zapłatę: trzydzieści srebrników.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 13, 'Potem Pan powiedział do mnie: Rzuć je przed garncarza. Wspaniała to zapłata, na jaką mnie tak drogo oszacowali! Wziąłem więc trzydzieści srebrników i rzuciłem je przed garncarza w domu Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 14, 'Potem złamałem swoją drugą laskę, Więzy, aby zerwać braterstwo między Judą a Izraelem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 15, 'I Pan powiedział do mnie: Weź sobie jeszcze narzędzie głupiego pasterza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 16, 'Oto bowiem wzbudzę pasterza w tej ziemi, który nie będzie troszczył się o zaginione, nie będzie szukał jagniątek, nie będzie leczyć okaleczonych i tego, co stoi, nie będzie karmił. Ale będzie jeść mięso tucznych, a ich kopyta oberwie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 17, 'Biada pasterzowi nieużytecznemu, który opuszcza trzodę! Niech spadnie miecz na jego ramię i na jego prawe oko. Jego ramię całkiem uschnie, a jego prawe oko całkiem oślepnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 1, 'Brzemię słowa Pana nad Izraelem. Tak mówi Pan, który rozpostarł niebiosa, założył fundamenty ziemi i stwarza ducha człowieka w jego wnętrzu:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 2, 'Oto uczynię Jerozolimę kielichem odurzenia dla wszystkich okolicznych narodów, gdy nastanie oblężenie przeciwko Judzie i przeciwko Jerozolimie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 3, 'W tym dniu uczynię Jerozolimę ciężkim kamieniem dla wszystkich narodów. Wszyscy, którzy będą go dźwigać, bardzo się zranią, choćby się zgromadziły przeciwko niemu wszystkie narody ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 4, 'Tego dnia, mówi Pan, każdego konia porażę trwogą i jego jeźdźca – szaleństwem; ale nad domem Judy otworzę swoje oczy, a każdego konia narodów porażę ślepotą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 5, 'I przywódcy Judy powiedzą w swoim sercu: Mieszkańcy Jerozolimy będą naszą siłą w Panu zastępów, swoim Bogu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 6, 'W tym dniu uczynię przywódców Judy jak węgle ogniste wśród drwa i jak płonącą pochodnię pośród snopów; i pożrą wszystkie okoliczne narody na prawo i na lewo. I Jerozolima pozostanie na swoim miejscu, w Jerozolimie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 7, 'I najpierw Pan wybawi namioty Judy, aby chwała domu Dawida i chwała mieszkańców Jerozolimy nie wywyższały się przeciwko Judzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 8, 'W tym dniu Pan będzie bronił mieszkańców Jerozolimy, a najsłabszy pośród nich stanie się tego dnia podobny do Dawida, a dom Dawida podobny do Boga, podobny do Anioła Pana na ich czele.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 9, 'I stanie się w tym dniu, że będę zmierzać do zniszczenia wszystkich narodów, które wyruszą przeciwko Jerozolimie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 10, 'I wyleję na dom Dawida i na mieszkańców Jerozolimy ducha łaski i modlitwy. Będą patrzyć na mnie, którego przebili, i będą go opłakiwać, jak się opłakuje jedynaka; będą gorzko płakać nad nim, jak się płacze gorzko nad pierworodnym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 11, 'W tym dniu będzie wielki lament w Jerozolimie, jak lament w Hadad-Rimmon na równinie Megiddo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 12, 'Ziemia będzie lamentować, każdy ród osobno: ród domu Dawida osobno i jego kobiety osobno; ród domu Natana osobno i jego kobiety osobno;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 13, 'Ród domu Lewiego osobno i jego kobiety osobno; ród Szimejego osobno i jego kobiety osobno;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 14, 'Wszystkie pozostałe rody, każdy ród osobno i ich kobiety osobno.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 1, 'W tym dniu zostanie otwarte źródło dla domu Dawida i mieszkańców Jerozolimy dla obmycia grzechu i nieczystości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 2, 'I stanie się w tym dniu, mówi Pan zastępów, że wykorzenię imiona bożków z ziemi, tak że nie będą więcej wspominane. Usunę z ziemi także proroków i ducha nieczystego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 3, 'A gdyby ktoś jeszcze prorokował, jego ojciec i matka, którzy go zrodzili, powiedzą mu: Nie będziesz żył, gdyż mówiłeś kłamstwo w imię Pana. I jego ojciec, i matka, którzy go zrodzili, przebiją go za to, że prorokował.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 4, 'I stanie się w tym dniu, że każdy z tych proroków zawstydzi się z powodu swojego widzenia, gdy prorokował, i nie oblecze się w kosmatą szatę, aby kłamać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 5, 'Ale każdy powie: Nie jestem prorokiem, ale rolnikiem, bo tego mnie uczono od dzieciństwa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 6, 'A jeśli ktoś go zapyta: Co to za rany na twoich rękach? Wtedy powie: Zostałem zraniony w domu moich przyjaciół.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 7, 'Mieczu, ocknij się przeciwko mojemu pasterzowi i przeciwko mężczyźnie, który jest moim towarzyszem, mówi Pan zastępów. Uderz pasterza, a owce zostaną rozproszone. Ja zaś zwrócę swoją rękę ku malutkim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 8, 'I stanie się na całej ziemi, mówi Pan, że dwie części w niej zostaną wycięte i zginą, a trzecia część pozostanie w niej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 9, 'I przeprowadzę tę trzecią część przez ogień i oczyszczę ich jak się czyści srebro, wypróbuję ich, jak się próbuje złoto. Będą wzywali mego imienia, a ja ich wysłucham. Powiem: Ty jesteś moim ludem, a on powie: Pan jest moim Bogiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 1, 'Oto przychodzi dzień Pana, a twój łup będzie rozdzielony pośród ciebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 2, 'Zgromadzę bowiem do bitwy wszystkie narody przeciwko Jerozolimie, a miasto zostanie zdobyte, domy splądrowane i kobiety zgwałcone. Połowa miasta pójdzie do niewoli, a resztka ludu nie będzie wygnana z miasta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 3, 'Wtedy Pan wyruszy i będzie walczył przeciwko tym narodom, tak jak wtedy, gdy walczył w dniu bitwy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 4, 'I jego nogi staną w tym dniu na Górze Oliwnej, która leży naprzeciw Jerozolimy od strony wschodniej, a Góra Oliwna rozpadnie się na pół, na wschód i na zachód, tworząc wielką dolinę; i połowa tej góry cofnie się na północ, a połowa jej – na południe.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 5, 'Wtedy będziecie uciekać do doliny tych gór, bo dolina tych gór będzie sięgać aż do Azal. Będziecie uciekać, jak uciekaliście przed trzęsieniem ziemi za dni Uzjasza, króla Judy. Potem przyjdzie Pan, mój Bóg, a z nim wszyscy święci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 6, 'A w tym dniu nie będzie wspaniałej światłości ani gęstej ciemności;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 7, 'Lecz będzie to jeden dzień, który jest znany tylko Panu, nie będzie to dzień ani noc. A o wieczornej porze nastanie światło.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 8, 'W tym dniu wyjdą wody żywe z Jerozolimy; połowa ich do morza wschodniego, a połowa – do morza zachodniego. Będzie to w lecie i w zimie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 9, 'A Pan będzie królem nad całą ziemią. W tym dniu jeden będzie Pan i jedno jego imię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 10, 'Cała ziemia zamieni się w równinę od Geba aż do Rimmon, na południe od Jerozolimy. Będzie wywyższona i zamieszkana na swoim miejscu, od Bramy Beniamina aż do miejsca dawnej bramy i aż do Bramy Narożnej i od Wieży Chananeela aż do tłoczni królewskich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 11, 'I będą w niej mieszkać, a nie będzie już przekleństwem. Jerozolima będzie zamieszkiwać w pokoju.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 12, 'A taka będzie plaga, którą Pan dotknie wszystkie narody, które walczyły przeciwko Jerozolimie: Ich ciała będą się rozkładać, gdy jeszcze będą stać na nogach, ich oczy będą gnić w oczodołach i ich język zgnije w ustach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 13, 'W tym dniu będzie wśród nich wielkie zamieszanie od Pana, tak że jeden uchwyci rękę drugiego, a jego ręka podniesie się na rękę swego bliźniego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 14, 'Juda także będzie walczyć w Jerozolimie, a bogactwa wszystkich narodów okolicznych będą zgromadzone: złoto, srebro i szaty w wielkiej ilości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 15, 'A taka sama plaga jak tamta dotknie konie, muły, wielbłądy, osły oraz wszystkie zwierzęta, które będą w tym obozie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 16, 'Wszyscy pozostali spośród wszystkich narodów, które wyruszyły przeciwko Jerozolimie, będą przychodzić od roku do roku, by oddawać pokłon Królowi, Panu zastępów, i obchodzić Święto Namiotów;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 17, 'A jeśli ktoś spośród rodów ziemi nie pójdzie do Jerozolimy, by oddawać pokłon Królowi, Panu zastępów, na tego nie będzie padać deszcz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 18, 'A jeśli ród Egiptu nie wyruszy i nie przyjdzie, choć na niego deszcz nie pada, spadnie jednak na niego ta plaga, którą Pan dotknie narody, które nie przyjdą, by obchodzić Święto Namiotów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 19, 'Taka będzie kara dla Egiptu i kara dla wszystkich narodów, które nie przychodzą na obchody Święta Namiotów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 20, 'W tym dniu na dzwoneczkach koni będzie taki napis: Świętość Panu; a kotłów w domu Pana będzie jak czasz przed ołtarzem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 21, 'Każdy kocioł w Jerozolimie i Judzie będzie poświęcony Panu zastępów. Wszyscy, którzy składają ofiary, przyjdą i będą je brali, i będą w nich gotowali. W tym dniu nie będzie już Kananejczyka w domu Pana zastępów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 1, 'Brzemię słowa Pana do Izraela przez Malachiasza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 2, 'Umiłowałem was, mówi Pan, a wy mówicie: W czym nas umiłowałeś? Czy Ezaw nie był bratem Jakuba? – mówi Pan, a jednak umiłowałem Jakuba;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 3, 'A Ezawa znienawidziłem i wydałem jego góry na spustoszenie, a jego dziedzictwo – smokom na pustkowiu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 4, 'Choćby Edom powiedział: Staliśmy się ubodzy, ale wrócimy i odbudujemy spustoszone miejsca, to tak mówi Pan zastępów: Niech oni budują, a ja zburzę; i nazwą ich granicą bezbożności oraz ludem, na który Pan zapałał gniewem aż na wieki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 5, 'Wasze oczy spojrzą i powiecie: Pan będzie uwielbiony w granicach Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 6, 'Syn czci ojca, a sługa swego pana. Jeśli więc jestem ojcem, gdzie jest moja cześć? Jeśli jestem panem, gdzie jest bojaźń przede mną? – mówi Pan zastępów do was, kapłani, którzy lekceważycie moje imię. Wy jednak mówicie: W czym lekceważymy twoje imię?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 7, 'Przynosicie na mój ołtarz pokarm nieczysty i mówicie: Czym cię zanieczyściliśmy? Tym, że mówicie: Stołem Pana można wzgardzić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 8, 'Gdy bowiem przyprowadzacie na ofiarę to, co jest ślepe, czyż nie jest to zła rzecz? I gdy przyprowadzacie kulawe i chore, czy to nie jest zła rzecz? Ofiaruj to twemu namiestnikowi, zobaczysz, czy będzie mu się podobać. Czy przyjmie twoją osobę? – mówi Pan zastępów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 9, 'Dlatego teraz, proszę, przebłagajcie Boga, aby się zlitował nad nami. To się dzieje z waszych rąk, czy więc przyjmie waszą osobę? – mówi Pan zastępów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 10, 'Kto spośród was za darmo zamknąłby drzwi albo zapaliłby ogień na moim ołtarzu? Nie mam w was upodobania, mówi Pan zastępów, i nie przyjmę ofiary z waszej ręki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 11, 'Od wschodu słońca bowiem aż do jego zachodu moje imię będzie wielkie wśród pogan; na każdym miejscu będą składane mojemu imieniu kadzidło i ofiara czysta. Moje imię bowiem będzie wielkie wśród narodów, mówi Pan zastępów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 12, 'Lecz wy bezcześcicie je, gdy mówicie: Stół Pana jest nieczysty; a to, co kładziecie na nim, jest wzgardzonym pokarmem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 13, 'Mówicie też: Jakiż to wysiłek! I parskacie na to, co mówi Pan zastępów, i przynosicie to, co jest rozszarpane, kulawe i chore, takie ofiary przynosicie. Czy mam to przyjąć z waszej ręki? – mówi Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 14, 'Niech będzie przeklęty oszust, który mając w swej trzodzie samca, ślubuje, a składa Panu w ofierze to, co jest ułomne. Jestem bowiem wielkim Królem, mówi Pan zastępów, a moje imię jest straszne między narodami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 1, 'Teraz, kapłani, ten rozkaz dotyczy was.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 2, 'Jeśli nie usłuchacie i nie weźmiecie tego do serca, aby oddać chwałę mojemu imieniu, mówi Pan zastępów, wtedy ześlę na was przekleństwo i będę przeklinać wasze błogosławieństwa. I już je przekląłem, bo nie bierzecie tego do serca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 3, 'Oto wam zepsuję wasze siewy i rzucę wam gnojem w twarz, gnojem waszych ofiar. I zabiorą was razem z nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 4, 'I dowiecie się, że posłałem do was ten rozkaz, aby moje przymierze było z Lewim, mówi Pan zastępów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 5, 'Moje przymierze z nim było przymierzem życia i pokoju; dałem mu je z powodu bojaźni, którą mnie się bał, i ponieważ przed moim imieniem był zatrwożony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 6, 'Prawo prawdy było na jego ustach i nie znaleziono na jego wargach nieprawości. Chodził ze mną w pokoju i prawości i wielu odwrócił od nieprawości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 7, 'Wargi kapłana bowiem mają strzec poznania i jego ustami ludzie mają pytać o prawo, gdyż on jest posłańcem Pana zastępów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 8, 'Ale wy zboczyliście z drogi i byliście powodem potknięcia o prawo dla wielu, zepsuliście przymierze Lewiego, mówi Pan zastępów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 9, 'Dlatego i ja sprawiłem, że zostaliście wzgardzeni i poniżeni u wszystkich ludzi, ponieważ nie strzegliście moich dróg i jesteście stronniczy w stosowaniu prawa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 10, 'Czy nie mamy wszyscy jednego ojca? Czy nie stworzył nas jeden Bóg? Czemu więc brat zdradza swego brata, naruszając przymierze naszych ojców?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 11, 'Juda postępuje zdradliwie, obrzydliwość dzieje się w Izraelu i Jerozolimie. Juda bowiem zbezcześcił świętość Pana, którą miał kochać, i pojął za żonę córkę obcego boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 12, 'Pan wykorzeni z namiotów Jakuba tego człowieka, który to czyni, zarówno czuwającego, jak i odpowiadającego oraz składającego ofiarę Panu zastępów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 13, 'A oto kolejna rzecz, którą uczyniliście: okrywacie ołtarz Pana łzami, płaczem i wołaniem, tak że już nie patrzy na ofiarę ani już nie przyjmuje chętnie ofiary z waszej ręki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 14, 'Wy jednak mówicie: Dlaczego? Dlatego że Pan jest świadkiem między tobą a żoną twojej młodości, którą zdradziłeś. Ona przecież jest twoją towarzyszką i żoną twego przymierza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 15, 'Czy nie uczynił jednej, choć mu jeszcze zostało ducha? A czemu jedną? Aby szukał potomstwa Bożego. Tak więc strzeżcie swego ducha i niech nikt nie postępuje zdradliwie z żoną swojej młodości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 16, 'Mówi bowiem Pan, Bóg Izraela, że nienawidzi oddalania, gdyż ten, kto to robi, okrywa swoim płaszczem okrucieństwo, mówi Pan zastępów. Tak więc strzeżcie swego ducha i nie postępujcie zdradliwie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 17, 'Naprzykrzaliście się Panu swoimi słowami. A mówicie: W czym mu się naprzykrzaliśmy? W tym, gdy mówicie: Każdy, kto czyni zło, podoba się Panu i w takich ma on swe upodobanie; albo: Gdzież jest Bóg sądu?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 1, 'Oto posyłam mego posłańca, który przygotuje drogę przed moim obliczem. I nagle przybędzie do swojej świątyni Pan, którego wy szukacie, Posłaniec przymierza, którego wy pragniecie. Oto przyjdzie, mówi Pan zastępów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 2, 'Lecz któż będzie mógł znieść dzień jego przyjścia? I kto się ostanie, gdy on się ukaże? Jest bowiem jak ogień złotnika i jak mydło foluszników.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 3, 'I zasiądzie jako ten, kto roztapia i oczyszcza srebro: oczyści synów Lewiego, oczyści ich jak złoto i srebro i będą składać Panu ofiarę w sprawiedliwości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 4, 'Wtedy ofiara Judy i Jerozolimy będzie miła Panu, jak za dawnych dni i jak za lat minionych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 5, 'I zbliżę się do was na sąd, i będę rychłym świadkiem przeciwko czarownikom, przeciwko cudzołożnikom, przeciwko krzywoprzysięzcom, przeciwko tym, którzy uciskają najemników przy ich zapłatach oraz wdowy i sieroty i krzywdzą cudzoziemca, a nie boją się mnie, mówi Pan zastępów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 6, 'Gdyż ja, Pan, nie zmieniam się, dlatego wy, synowie Jakuba, nie zostaliście zniszczeni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 7, 'Od dni waszych ojców odstępowaliście od moich ustaw i nie przestrzegaliście ich. Zawróćcie do mnie, a ja zawrócę do was, mówi Pan zastępów. Ale wy mówicie: Pod jakim względem mamy zawrócić?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 8, 'Czy człowiek okradnie Boga? Wy jednak mnie okradacie. Lecz mówicie: Z czego cię okradamy? Z dziesięcin i ofiar.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 9, 'Jesteście zupełnie przeklęci, ponieważ mnie okradacie, wy i cały wasz naród.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 10, 'Przynieście całą dziesięcinę do szpichlerza, aby żywność była w moim domu, a doświadczcie mnie teraz w tym, mówi Pan zastępów, czy wam nie otworzę okien niebios i nie wyleję na was błogosławieństwa, tak że nie będziecie mieli gdzie go podziać;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 11, 'I zgromię ze względu na was tego, który pożera, a nie popsuje wam plonu ziemi i winorośl nie będzie pozbawiona owocu na polu, mówi Pan zastępów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 12, 'I wszystkie narody będą was nazywać błogosławionymi, bo będziecie ziemią rozkoszną, mówi Pan zastępów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 13, 'Zuchwałe są wasze słowa przeciwko mnie, mówi Pan. Wy jednak mówicie: Cóż powiedzieliśmy przeciwko tobie?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 14, 'Mówiliście: Na próżno służyć Bogu. Co za pożytek z tego, że przestrzegaliśmy jego przykazań i chodziliśmy smutni przed Panem zastępów?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 15, 'A teraz pysznych mamy za błogosławionych, ponieważ ci się budują, którzy czynią niegodziwość, a ci, którzy kuszą Boga, są wybawieni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 16, 'Wtedy rozmawiali o tym między sobą ci, którzy się bali Pana. Pan zobaczył to i usłyszał, i napisano księgę wspomnień przed nim z powodu tych, którzy się boją Pana i rozmyślają o jego imieniu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 17, 'Oni będą moimi, mówi Pan zastępów, w dniu, kiedy uczynię ich moją własnością. Zlituję się nad nimi, jak się lituje ojciec nad swoim synem, który mu służy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 18, 'Wtedy zawrócicie i zobaczycie różnicę między sprawiedliwym i bezbożnym, między tym, który służy Bogu, i tym, który mu nie służy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 1, 'Oto bowiem nadchodzi dzień palący jak piec, a wszyscy pyszni i wszyscy czyniący niegodziwie będą jak ściernisko. I spali ich ten nadchodzący dzień, mówi Pan zastępów, tak że nie pozostawi im ani korzenia, ani gałązki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 2, 'Ale dla was, którzy się boicie mojego imienia, wzejdzie Słońce sprawiedliwości z uzdrowieniem na swoich skrzydłach; wtedy wyjdziecie i wyrośniecie jak cielęta z zagrody.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 3, 'I podepczecie bezbożnych, gdyż będą prochem pod waszymi nogami w dniu, kiedy to uczynię, mówi Pan zastępów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 4, 'Pamiętajcie o prawie Mojżesza, mego sługi, które mu nadałem na Horebie dla całego Izraela, oraz o ustawach i sądach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 5, 'Oto poślę wam Eliasza proroka, zanim przyjdzie ten wielki i straszny dzień Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 6, 'On zwróci serca ojców ku synom, a serca synów ku ich ojcom, abym nie ukarał ziemi przekleństwem, gdy przyjdę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 1, 'Księga rodu Jezusa Chrystusa, syna Dawida, syna Abrahama.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 2, 'Abraham spłodził Izaaka, a Izaak spłodził Jakuba, a Jakub spłodził Judę i jego braci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 3, 'A Juda spłodził z Tamar Faresa i Zarę, a Fares spłodził Ezroma, a Ezrom spłodził Arama.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 4, 'A Aram spłodził Aminadaba, a Aminadab spłodził Naasona, a Naason spłodził Salmona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 5, 'A Salmon spłodził z Rachab Booza, a Booz spłodził z Rut Obeda, a Obed spłodził Jessego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 6, 'A Jesse spłodził króla Dawida, a król Dawid spłodził Salomona z tej, która była żoną Uriasza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 7, 'A Salomon spłodził Roboama, a Roboam spłodził Abiasza, a Abiasz spłodził Azę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 8, 'A Aza spłodził Jozafata, a Jozafat spłodził Jorama, a Joram spłodził Ozjasza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 9, 'A Ozjasz spłodził Joatama, a Joatam spłodził Achaza, a Achaz spłodził Ezechiasza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 10, 'A Ezechiasz spłodził Manassesa, a Manasses spłodził Amona, a Amon spłodził Jozjasza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 11, 'A Jozjasz spłodził Jechoniasza i jego braci w czasie uprowadzenia do Babilonu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 12, 'A po uprowadzeniu do Babilonu Jechoniasz spłodził Salatiela, a Salatiel spłodził Zorobabela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 13, 'A Zorobabel spłodził Abiuda, a Abiud spłodził Eliakima, a Eliakim spłodził Azora.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 14, 'A Azor spłodził Sadoka, a Sadok spłodził Achima, a Achim spłodził Eliuda.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 15, 'A Eliud spłodził Eleazara, a Eleazar spłodził Matana, a Matan spłodził Jakuba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 16, 'A Jakub spłodził Józefa, męża Marii, z której narodził się Jezus, zwany Chrystusem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 17, 'Tak więc wszystkich pokoleń od Abrahama aż do Dawida jest czternaście; a od Dawida aż do uprowadzenia do Babilonu – pokoleń czternaście; a od uprowadzenia do Babilonu aż do Chrystusa – pokoleń czternaście.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 18, 'A z narodzeniem Jezusa Chrystusa było tak: Gdy Maria, jego matka, została zaślubiona Józefowi, zanim się zeszli, okazało się, że jest brzemienna z Ducha Świętego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 19, 'Ale Józef, jej mąż, będąc sprawiedliwym i nie chcąc jej zniesławić, chciał ją potajemnie oddalić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 20, 'A gdy o tym rozmyślał, oto anioł Pana ukazał mu się we śnie i powiedział: Józefie, synu Dawida, nie bój się przyjąć Marii, twojej żony. To bowiem, co się w niej poczęło, jest z Ducha Świętego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 21, 'I urodzi syna, któremu nadasz imię Jezus. On bowiem zbawi swój lud od jego grzechów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 22, 'A to wszystko się stało, aby się wypełniło, co powiedział Pan przez proroka:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 23, 'Oto dziewica będzie brzemienna i urodzi syna, któremu nadadzą imię Emmanuel, co się tłumaczy: Bóg z nami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 24, 'Wtedy Józef, obudziwszy się ze snu, uczynił tak, jak mu rozkazał anioł Pana, i przyjął swoją żonę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 25, 'Ale nie obcował z nią, dopóki nie urodziła swego pierworodnego syna, któremu nadał imię Jezus.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 1, 'A gdy Jezus urodził się w Betlejem w Judei za dni króla Heroda, oto mędrcy ze Wschodu przybyli do Jerozolimy i pytali:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 2, 'Gdzież jest ten król Żydów, który się urodził? Widzieliśmy bowiem jego gwiazdę na Wschodzie i przyjechaliśmy, aby oddać mu pokłon.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 3, 'Gdy król Herod to usłyszał, przeraził się, a z nim cała Jerozolima.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 4, 'Zebrawszy więc wszystkich naczelnych kapłanów i nauczycieli ludu, wypytywał ich, gdzie miał się urodzić Chrystus.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 5, 'A oni mu powiedzieli: W Betlejem w Judei; bo tak jest napisane przez proroka:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 6, 'A ty, Betlejem, ziemio Judy, wcale nie jesteś najmniejsze wśród władców Judei, z ciebie bowiem wyjdzie władca, który będzie rządził moim ludem, Izraelem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 7, 'Wtedy Herod wezwał potajemnie mędrców i dowiadywał się dokładnie o czas ukazania się gwiazdy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 8, 'A posyłając ich do Betlejem, powiedział: Jedźcie i wypytajcie się dokładnie o to dziecko, a gdy je znajdziecie, donieście mi, abym i ja pojechał i oddał mu pokłon.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 9, 'Oni więc, wysłuchawszy króla, odeszli. A oto gwiazda, którą widzieli na Wschodzie, prowadziła ich, aż przyszła i zatrzymała się nad miejscem, gdzie było dziecko.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 10, 'A gdy zobaczyli gwiazdę, ogromnie się ucieszyli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 11, 'Kiedy weszli do domu, zobaczyli dziecko z Marią, jego matką, i upadłszy, oddali mu pokłon, potem otworzyli swoje skarby i ofiarowali mu dary: złoto, kadzidło i mirrę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 12, 'Lecz będąc ostrzeżeni przez Boga we śnie, aby nie wracali do Heroda, powrócili do swojej ziemi inną drogą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 13, 'A gdy oni odeszli, oto anioł Pana ukazał się we śnie Józefowi i powiedział: Wstań, weź dziecko oraz jego matkę i uciekaj do Egiptu, i zostań tam, aż ci powiem. Herod bowiem będzie szukał dziecka, aby je zabić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 14, 'Wstał więc, wziął w nocy dziecko oraz jego matkę i uciekł do Egiptu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 15, 'I przebywał tam aż do śmierci Heroda, aby się wypełniło, co powiedział Pan przez proroka: Z Egiptu wezwałem mego syna.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 16, 'Wówczas Herod, widząc, że został oszukany przez mędrców, bardzo się rozgniewał i kazał zabić wszystkie dzieci, które były w Betlejem i całej okolicy, w wieku do dwóch lat, stosownie do czasu, o którym się dokładnie dowiedział od mędrców.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 17, 'Wtedy wypełniło się to, co zostało powiedziane przez proroka Jeremiasza:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 18, 'Słychać głos w Rama, lament, płacz i wielkie zawodzenie. Rachel opłakuje swoje dzieci i nie daje się pocieszyć, bo już ich nie ma.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 19, 'A gdy Herod umarł, oto anioł Pana ukazał się we śnie Józefowi w Egipcie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 20, 'I powiedział: Wstań, weź dziecko oraz jego matkę i idź do ziemi izraelskiej. Umarli bowiem ci, którzy czyhali na życie dziecka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 21, 'Wstał więc, wziął dziecko oraz jego matkę i przybył do ziemi izraelskiej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 22, 'Lecz gdy usłyszał, że Archelaus króluje w Judei w miejsce Heroda, swego ojca, bał się tam iść. Ale będąc napomniany przez Boga we śnie, odszedł w strony Galilei.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 23, 'A przyszedłszy, mieszkał w mieście zwanym Nazaret, aby się wypełniło to, co zostało powiedziane przez proroków: Będzie nazwany Nazarejczykiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 1, 'W tych dniach przyszedł Jan Chrzciciel, głosząc na pustyni judzkiej:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 2, 'Pokutujcie, bo przybliżyło się królestwo niebieskie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 3, 'To bowiem jest ten, o którym powiedziano przez proroka Izajasza: Głos wołającego na pustyni: Przygotujcie drogę Pana, prostujcie jego ścieżki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 4, 'A ów Jan miał ubranie z sierści wielbłądziej i pas skórzany wokół bioder, a jego pokarmem była szarańcza i miód leśny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 5, 'Wtedy przychodziła do niego Jerozolima oraz cała Judea i cała okolica nad Jordanem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 6, 'I byli przez niego chrzczeni w Jordanie, wyznając swoje grzechy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 7, 'A gdy zobaczył wielu spośród faryzeuszy i saduceuszy przychodzących do chrztu, powiedział im: Plemię żmijowe, któż was ostrzegł, żebyście uciekali przed nadchodzącym gniewem?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 8, 'Wydajcie więc owoce godne pokuty;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 9, 'A nie myślcie, że możecie sobie mówić: Naszym ojcem jest Abraham. Mówię wam bowiem, że Bóg może i z tych kamieni wzbudzić dzieci Abrahamowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 10, 'Już i siekiera do korzenia drzew jest przyłożona. Każde więc drzewo, które nie wydaje dobrego owocu, zostaje wycięte i wrzucone w ogień.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 11, 'Ja was chrzczę wodą ku pokucie; ten zaś, który idzie za mną, jest mocniejszy ode mnie; nie jestem godny nosić mu obuwia. On będzie was chrzcił Duchem Świętym i ogniem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 12, 'Ma swoje wiejadło w ręku i wyczyści swoje klepisko, i zgromadzi swoją pszenicę do spichlerza, a plewy spali w ogniu nieugaszonym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 13, 'Wtedy Jezus przyszedł z Galilei nad Jordan do Jana, aby być przez niego ochrzczonym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 14, 'Ale Jan powstrzymywał go, mówiąc: Ja potrzebuję być ochrzczonym przez ciebie, a ty przychodzisz do mnie?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 15, 'A Jezus mu odpowiedział: Ustąp teraz, bo godzi się nam wypełnić wszelką sprawiedliwość. Wtedy mu ustąpił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 16, 'A gdy Jezus został ochrzczony, zaraz wyszedł z wody, a oto otworzyły mu się niebiosa i ujrzał Ducha Bożego zstępującego jak gołębica i przychodzącego na niego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 17, 'I rozległ się głos z nieba: To jest mój umiłowany Syn, w którym mam upodobanie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 1, 'Wtedy Jezus został zaprowadzony przez Ducha na pustynię, aby był kuszony przez diabła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 2, 'A po czterdziestu dniach i czterdziestu nocach postu poczuł głód.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 3, 'Wówczas przystąpił do niego kusiciel i powiedział: Jeśli jesteś Synem Bożym, powiedz, aby te kamienie stały się chlebem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 4, 'A on odpowiedział: Jest napisane: Nie samym chlebem będzie żył człowiek, ale każdym słowem pochodzącym z ust Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 5, 'Wtedy diabeł wziął go do miasta świętego i postawił na szczycie świątyni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 6, 'I powiedział mu: Jeśli jesteś Synem Bożym, rzuć się w dół, jest bowiem napisane: Rozkaże o tobie swoim aniołom i będą cię nosić na rękach, abyś nie uderzył swojej nogi o kamień.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 7, 'Jezus mu odpowiedział: Jest też napisane: Nie będziesz wystawiał na próbę Pana, swego Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 8, 'Znowu wziął go diabeł na bardzo wysoką górę i pokazał mu wszystkie królestwa świata oraz ich wspaniałość.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 9, 'I powiedział do niego: Dam ci to wszystko, jeśli upadniesz i oddasz mi pokłon.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 10, 'Wtedy Jezus powiedział mu: Idź precz, szatanie! Jest bowiem napisane: Panu, swemu Bogu, będziesz oddawał pokłon i tylko jemu będziesz służył.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 11, 'Wówczas diabeł go opuścił, a oto aniołowie przystąpili do niego i mu służyli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 12, 'A gdy Jezus usłyszał, że Jan został wtrącony do więzienia, wrócił do Galilei.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 13, 'A opuściwszy Nazaret, przyszedł i zamieszkał w Kafarnaum, które leży nad morzem, w granicach Zabulona i Neftalego;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 14, 'Aby się wypełniło, co zostało powiedziane przez proroka Izajasza:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 15, 'Ziemia Zabulona i ziemia Neftalego, wzdłuż drogi nadmorskiej, za Jordanem, Galilea pogan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 16, 'Lud, który siedział w ciemności, ujrzał światłość wielką, a siedzącym w krainie i cieniu śmierci wzeszła światłość.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 17, 'Od tego czasu Jezus zaczął głosić i mówić: Pokutujcie, przybliżyło się bowiem królestwo niebieskie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 18, 'A gdy Jezus przechodził nad Morzem Galilejskim, zobaczył dwóch braci: Szymona, zwanego Piotrem, i Andrzeja, jego brata, którzy zapuszczali sieć w morze; byli bowiem rybakami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 19, 'I powiedział im: Chodźcie za mną, a uczynię was rybakami ludzi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 20, 'Oni natychmiast porzucili sieci i poszli za nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 21, 'A gdy poszedł stamtąd dalej, zobaczył innych dwóch braci, Jakuba, syna Zebedeusza, i Jana, jego brata, jak ze swoim ojcem Zebedeuszem naprawiali w łodzi swoje sieci. I wezwał ich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 22, 'A oni natychmiast opuścili łódź i swego ojca i poszli za nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 23, 'I obchodził Jezus całą Galileę, nauczając w ich synagogach, głosząc ewangelię królestwa i uzdrawiając wszystkie choroby i wszelkie dolegliwości wśród ludzi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 24, 'A wieść o nim rozeszła się po całej Syrii. I przyprowadzano do niego wszystkich, którzy się źle czuli, którzy byli nękani różnymi chorobami i cierpieniami, a także opętanych, obłąkanych i sparaliżowanych, a on ich uzdrawiał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 25, 'A szło za nim mnóstwo ludzi z Galilei i Dekapolu, Jerozolimy, Judei i Zajordania.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 1, 'A Jezus, widząc tłumy, wszedł na górę, a gdy usiadł, podeszli do niego jego uczniowie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 2, 'Wtedy otworzył usta i nauczał ich:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 3, 'Błogosławieni ubodzy w duchu, ponieważ do nich należy królestwo niebieskie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 4, 'Błogosławieni, którzy się smucą, ponieważ oni będą pocieszeni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 5, 'Błogosławieni cisi, ponieważ oni odziedziczą ziemię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 6, 'Błogosławieni, którzy łakną i pragną sprawiedliwości, ponieważ oni będą nasyceni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 7, 'Błogosławieni miłosierni, ponieważ oni dostąpią miłosierdzia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 8, 'Błogosławieni czystego serca, ponieważ oni zobaczą Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 9, 'Błogosławieni czyniący pokój, ponieważ oni będą nazwani synami Bożymi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 10, 'Błogosławieni, którzy cierpią prześladowanie z powodu sprawiedliwości, ponieważ do nich należy królestwo niebieskie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 11, 'Błogosławieni jesteście, gdy z mego powodu będą wam złorzeczyć, prześladować was i mówić kłamliwie wszystko, co złe, przeciwko wam.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 12, 'Radujcie się i weselcie, ponieważ obfita jest wasza nagroda w niebie; tak bowiem prześladowali proroków, którzy byli przed wami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 13, 'Wy jesteście solą ziemi; lecz jeśli sól zwietrzeje, czym ją posolą? Na nic się już nie przyda, tylko na wyrzucenie i podeptanie przez ludzi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 14, 'Wy jesteście światłością świata. Nie może się ukryć miasto położone na górze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 15, 'Nie zapala się świecy i nie stawia jej pod naczyniem, ale na świeczniku, i świeci wszystkim, którzy są w domu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 16, 'Tak niech wasza światłość świeci przed ludźmi, aby widzieli wasze dobre uczynki i chwalili waszego Ojca, który jest w niebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 17, 'Nie sądźcie, że przyszedłem znieść Prawo albo Proroków. Nie przyszedłem znieść, ale wypełnić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 18, 'Zaprawdę bowiem powiadam wam: Dopóki niebo i ziemia nie przeminą, ani jedna jota, ani jedna kreska nie przeminie z prawa, aż wszystko się wypełni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 19, 'Kto by więc złamał jedno z tych najmniejszych przykazań i uczyłby tak ludzi, będzie nazwany najmniejszym w królestwie niebieskim. A kto by je wypełniał i uczył, ten będzie nazwany wielkim w królestwie niebieskim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 20, 'Mówię wam bowiem: Jeśli wasza sprawiedliwość nie będzie obfitsza niż uczonych w Piśmie i faryzeuszy, żadnym sposobem nie wejdziecie do królestwa niebieskiego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 21, 'Słyszeliście, że powiedziano przodkom: Nie będziesz zabijał, a kto by zabił, podlega sądowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 22, 'Lecz ja wam mówię: Każdy, kto się gniewa na swego brata bez przyczyny, podlega sądowi, a kto powie swemu bratu: Raka, podlega Radzie, a kto powie: Głupcze, podlega karze ognia piekielnego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 23, 'Jeśli więc przyniesiesz swój dar na ołtarz i tam przypomnisz sobie, że twój brat ma coś przeciwko tobie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 24, 'Zostaw swój dar tam przed ołtarzem, idź i najpierw pojednaj się ze swoim bratem, a potem przyjdź i ofiaruj swój dar.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 25, 'Pogódź się ze swoim przeciwnikiem szybko, dopóki jesteś z nim w drodze, aby przeciwnik nie wydał cię sędziemu, a sędzia strażnikowi, i aby nie wtrącono cię do więzienia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 26, 'Zaprawdę powiadam ci: Nie wyjdziesz stamtąd, dopóki nie oddasz ostatniego grosza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 27, 'Słyszeliście, że powiedziano przodkom: Nie będziesz cudzołożył.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 28, 'Lecz ja wam mówię: Każdy, kto patrzy na kobietę, aby jej pożądać, już popełnił z nią cudzołóstwo w swoim sercu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 29, 'Jeśli więc twoje prawe oko jest ci powodem upadku, wyłup je i odrzuć od siebie. Pożyteczniej bowiem jest dla ciebie, aby zginął jeden z twoich członków, niż żeby całe twoje ciało było wrzucone do ognia piekielnego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 30, 'A jeśli twoja prawa ręka jest ci powodem upadku, odetnij ją i odrzuć od siebie. Pożyteczniej bowiem jest dla ciebie, aby zginął jeden z twoich członków, niż żeby całe twoje ciało było wrzucone do ognia piekielnego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 31, 'Powiedziano też: Kto oddala swoją żonę, niech jej da list rozwodowy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 32, 'Lecz ja wam mówię: Kto oddala swoją żonę – poza przypadkiem nierządu – prowadzi ją do cudzołóstwa, a kto żeni się z oddaloną, cudzołoży.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 33, 'Słyszeliście też, że powiedziano przodkom: Nie będziesz fałszywie przysięgał, ale dotrzymasz Panu swych przysiąg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 34, 'Lecz ja wam mówię: Wcale nie przysięgajcie – ani na niebo, gdyż jest tronem Boga;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 35, 'Ani na ziemię, gdyż jest podnóżkiem jego stóp, ani na Jerozolimę, gdyż jest miastem wielkiego króla.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 36, 'Ani na swoją głowę nie będziesz przysięgał, gdyż nie możesz jednego włosa uczynić białym albo czarnym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 37, 'Ale wasza mowa niech będzie: Tak – tak, nie – nie. A co jest ponadto, pochodzi od złego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 38, 'Słyszeliście, że powiedziano: Oko za oko i ząb za ząb.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 39, 'Lecz ja wam mówię: Nie sprzeciwiajcie się złemu, ale jeśli ktoś uderzy cię w prawy policzek, nadstaw mu i drugi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 40, 'Temu, kto chce się z tobą procesować i wziąć twoją szatę, zostaw i płaszcz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 41, 'A jeśli ktoś cię przymusza, żebyś szedł z nim jedną milę, idź z nim i dwie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 42, 'Temu, kto cię prosi, daj, a od tego, kto chce od ciebie pożyczyć, nie odwracaj się.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 43, 'Słyszeliście, że powiedziano: Będziesz miłował swego bliźniego, a swego nieprzyjaciela będziesz nienawidził.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 44, 'Lecz ja wam mówię: Miłujcie waszych nieprzyjaciół, błogosławcie tym, którzy was przeklinają, dobrze czyńcie tym, którzy was nienawidzą i módlcie się za tych, którzy wam wyrządzają zło i prześladują was;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 45, 'Abyście byli synami waszego Ojca, który jest w niebie. On bowiem sprawia, że jego słońce wschodzi nad złymi i nad dobrymi i deszcz zsyła na sprawiedliwych i niesprawiedliwych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 46, 'Jeśli bowiem miłujecie tych, którzy was miłują, jakąż macie nagrodę? Czyż i celnicy tego nie czynią?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 47, 'A jeśli tylko waszych braci pozdrawiacie, cóż szczególnego czynicie? Czyż i celnicy tak nie czynią?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 48, 'Bądźcie więc doskonali, tak jak doskonały jest wasz Ojciec, który jest w niebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 1, 'Pilnujcie się, abyście waszej jałmużny nie dawali przed ludźmi po to, aby was widzieli, inaczej nie będziecie mieli nagrody u waszego Ojca, który jest w niebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 2, 'Dlatego, gdy dajesz jałmużnę, nie trąb przed sobą, jak to robią obłudnicy w synagogach i na ulicach, aby ich ludzie chwalili. Zaprawdę powiadam wam: Odbierają swoją nagrodę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 3, 'Ale ty, gdy dajesz jałmużnę, niech nie wie twoja lewa ręka, co czyni prawa;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 4, 'Aby twoja jałmużna pozostała w ukryciu, a twój Ojciec, który widzi w ukryciu, odda ci jawnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 5, 'A gdy się modlisz, nie bądź jak obłudnicy. Oni bowiem chętnie modlą się, stojąc w synagogach i na rogach ulic, aby ludzie ich widzieli. Zaprawdę powiadam wam: Odbierają swoją nagrodę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 6, 'Ale ty, gdy się modlisz, wejdź do swego pokoju, zamknij drzwi i módl się do twego Ojca, który jest w ukryciu, a twój Ojciec, który widzi w ukryciu, odda ci jawnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 7, 'A modląc się, nie bądźcie wielomówni jak poganie; oni bowiem sądzą, że ze względu na swoją wielomówność będą wysłuchani.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 8, 'Nie bądźcie do nich podobni, gdyż wasz Ojciec wie, czego potrzebujecie, zanim go poprosicie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 9, 'Wy więc tak się módlcie: Ojcze nasz, który jesteś w niebie, niech będzie uświęcone twoje imię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 10, 'Niech przyjdzie twoje królestwo, niech się dzieje twoja wola na ziemi, tak jak w niebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 11, 'Daj nam dzisiaj naszego powszedniego chleba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 12, 'I przebacz nam nasze winy, jak i my przebaczamy tym, którzy przeciw nam zawinili.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 13, 'I nie wystawiaj nas na pokusę, ale wybaw nas od złego; twoje bowiem jest królestwo, moc i chwała na wieki. Amen.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 14, 'Bo jeśli przebaczycie ludziom ich przewinienia, i wam przebaczy wasz Ojciec niebieski.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 15, 'Lecz jeśli nie przebaczycie ludziom ich przewinień, to i wasz Ojciec nie przebaczy wam waszych przewinień.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 16, 'A gdy pościcie, nie miejcie twarzy smutnej jak obłudnicy; szpecą bowiem swoje twarze, aby ludzie widzieli, że poszczą. Zaprawdę powiadam wam: Odbierają swoją nagrodę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 17, 'Ale ty, gdy pościsz, namaść sobie głowę i umyj twarz;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 18, 'Aby nie ludzie widzieli, że pościsz, lecz twój Ojciec, który jest w ukryciu; a twój Ojciec, który widzi w ukryciu, odda ci jawnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 19, 'Nie gromadźcie sobie skarbów na ziemi, gdzie mól i rdza niszczą i gdzie złodzieje włamują się i kradną;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 20, 'Ale gromadźcie sobie skarby w niebie, gdzie ani mól, ani rdza nie niszczą i gdzie złodzieje nie włamują się i nie kradną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 21, 'Gdzie bowiem jest wasz skarb, tam będzie i wasze serce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 22, 'Światłem ciała jest oko. Jeśli więc twoje oko jest szczere, całe twoje ciało będzie pełne światła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 23, 'Jeśli zaś twoje oko jest złe, całe twoje ciało będzie pełne ciemności. Jeśli więc światło, które jest w tobie, jest ciemnością, sama ciemność jakaż będzie?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 24, 'Nikt nie może dwom panom służyć, gdyż albo jednego będzie nienawidził, a drugiego będzie miłował, albo jednego będzie się trzymał, a drugim pogardzi. Nie możecie służyć Bogu i mamonie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 25, 'Dlatego mówię wam: Nie troszczcie się o wasze życie, co będziecie jeść albo co będziecie pić, ani o wasze ciało, w co będziecie się ubierać. Czyż życie nie jest czymś więcej niż pokarm, a ciało niż ubranie?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 26, 'Spójrzcie na ptaki nieba, że nie sieją ani nie żną, ani nie zbierają do spichlerzy, a jednak wasz Ojciec niebieski żywi je. Czy wy nie jesteście o wiele cenniejsi niż one?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 27, 'I któż z was, martwiąc się, może dodać do swego wzrostu jeden łokieć?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 28, 'A o ubranie dlaczego się troszczycie? Przypatrzcie się liliom polnym, jak rosną; nie pracują ani nie przędą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 29, 'A mówię wam, że nawet Salomon w całej swojej chwale nie był tak ubrany, jak jedna z nich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 30, 'Jeśli więc trawę polną, która dziś jest, a jutro zostanie wrzucona do pieca, Bóg tak ubiera, czyż nie tym bardziej was, ludzie małej wiary?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 31, 'Nie troszczcie się więc, mówiąc: Cóż będziemy jeść? albo: Co będziemy pić? albo: W co się ubierzemy?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 32, 'Bo o to wszystko poganie zabiegają. Wie bowiem wasz Ojciec niebieski, że tego wszystkiego potrzebujecie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 33, 'Ale szukajcie najpierw królestwa Bożego i jego sprawiedliwości, a to wszystko będzie wam dodane.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 34, 'Dlatego nie troszczcie się o dzień jutrzejszy, gdyż dzień jutrzejszy sam się zatroszczy o swoje potrzeby. Dosyć ma dzień swego utrapienia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 1, 'Nie sądźcie, abyście nie byli sądzeni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 2, 'Jakim bowiem sądem sądzicie, takim będziecie sądzeni, i jaką miarą mierzycie, taką będzie wam odmierzone.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 3, 'A czemu widzisz źdźbło w oku swego brata, a na belkę, która jest w twoim oku, nie zwracasz uwagi?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 4, 'Albo jak możesz mówić swemu bratu: Pozwól, że wyjmę źdźbło z twego oka, gdy belka jest w twoim oku?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 5, 'Obłudniku, wyjmij najpierw belkę ze swego oka, a wtedy przejrzysz, aby wyjąć źdźbło z oka twego brata.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 6, 'Nie dawajcie psom tego, co święte, i nie rzucajcie swoich pereł przed świnie, by ich nie podeptały swymi nogami i odwróciwszy się, nie rozszarpały was.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 7, 'Proście, a będzie wam dane, szukajcie, a znajdziecie, pukajcie, a będzie wam otworzone.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 8, 'Każdy bowiem, kto prosi, otrzymuje, kto szuka, znajduje, a temu, kto puka, będzie otworzone.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 9, 'I czy jest wśród was człowiek, który da synowi kamień, gdy ten prosi o chleb?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 10, 'A gdy prosi o rybę, czy da mu węża?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 11, 'Jeśli więc wy, będąc złymi, umiecie dawać dobre dary waszym dzieciom, o ileż bardziej wasz Ojciec, który jest w niebie, da dobre rzeczy tym, którzy go proszą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 12, 'Wszystko więc, co chcecie, aby wam ludzie czynili, i wy im czyńcie. To bowiem jest Prawo i Prorocy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 13, 'Wchodźcie przez ciasną bramę. Szeroka bowiem jest brama i przestronna droga, która prowadzi na zatracenie, a wielu jest takich, którzy przez nią wchodzą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 14, 'Ciasna bowiem jest brama i wąska droga, która prowadzi do życia, a mało jest takich, którzy ją znajdują.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 15, 'Strzeżcie się fałszywych proroków, którzy przychodzą do was w owczej skórze, ale wewnątrz są drapieżnymi wilkami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 16, 'Po ich owocach poznacie ich. Czy zbierają winogrona z cierni albo z ostu figi?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 17, 'Tak każde dobre drzewo wydaje dobre owoce, ale złe drzewo wydaje złe owoce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 18, 'Nie może dobre drzewo wydawać złych owoców ani złe drzewo wydawać dobrych owoców.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 19, 'Każde drzewo, które nie wydaje dobrego owocu, zostaje wycięte i wrzucone w ogień.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 20, 'Tak więc po ich owocach poznacie ich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 21, 'Nie każdy, kto mi mówi: Panie, Panie, wejdzie do królestwa niebieskiego, lecz ten, kto wypełnia wolę mojego Ojca, który jest w niebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 22, 'Wielu powie mi tego dnia: Panie, Panie, czyż nie prorokowaliśmy w twoim imieniu i w twoim imieniu nie wypędzaliśmy demonów, i w twoim imieniu nie czyniliśmy wielu cudów?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 23, 'A wtedy im oświadczę: Nigdy was nie znałem. Odstąpcie ode mnie wy, którzy czynicie nieprawość.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 24, 'Każdego więc, kto słucha tych moich słów i wypełnia je, przyrównam do człowieka mądrego, który zbudował swój dom na skale.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 25, 'I spadł deszcz, przyszła powódź, zerwały się wichry i uderzyły w ten dom, ale się nie zawalił, bo był założony na skale.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 26, 'A każdy, kto słucha tych moich słów, a nie wypełnia ich, będzie przyrównany do człowieka głupiego, który zbudował swój dom na piasku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 27, 'I spadł deszcz, przyszła powódź, zerwały się wichry i uderzyły w ten dom, i zawalił się, a jego upadek był wielki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 28, 'A gdy Jezus dokończył tych słów, ludzie zdumiewali się jego nauką.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 29, 'Uczył ich bowiem jak ten, który ma moc, a nie jak uczeni w Piśmie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 1, 'A gdy zszedł z góry, poszło za nim mnóstwo ludzi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 2, 'A oto trędowaty podszedł i oddał mu pokłon, mówiąc: Panie, jeśli chcesz, możesz mnie oczyścić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 3, 'Jezus wyciągnął rękę i dotknął go, mówiąc: Chcę, bądź oczyszczony. I natychmiast został oczyszczony z trądu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 4, 'Wtedy Jezus powiedział do niego: Uważaj, abyś nikomu nie mówił, ale idź, pokaż się kapłanowi i ofiaruj dar, który nakazał Mojżesz, na świadectwo dla nich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 5, 'A gdy Jezus wszedł do Kafarnaum, przyszedł do niego setnik i prosił go:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 6, 'Panie, mój sługa leży w domu sparaliżowany i bardzo cierpi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 7, 'I powiedział mu Jezus: Przyjdę i uzdrowię go.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 8, 'Lecz setnik odpowiedział: Panie, nie jestem godny, abyś wszedł pod mój dach, ale powiedz tylko słowo, a mój sługa będzie uzdrowiony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 9, 'Bo i ja jestem człowiekiem podległym władzy i mam pod sobą żołnierzy. Mówię jednemu: Idź, a idzie; a drugiemu: Chodź tu, a przychodzi; a memu słudze: Zrób to, a robi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 10, 'A gdy Jezus to usłyszał, zdziwił się i powiedział do tych, którzy szli za nim: Zaprawdę powiadam wam: Nawet w Izraelu nie znalazłem tak wielkiej wiary.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 11, 'A mówię wam: Wielu przyjdzie ze wschodu i z zachodu i zasiądą za stołem z Abrahamem, Izaakiem i Jakubem w królestwie niebieskim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 12, 'Lecz synowie królestwa będą wyrzuceni do ciemności zewnętrznych. Tam będzie płacz i zgrzytanie zębów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 13, 'I powiedział Jezus setnikowi: Idź, a jak uwierzyłeś, tak niech ci się stanie. I o tej godzinie jego sługa został uzdrowiony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 14, 'A gdy Jezus przyszedł do domu Piotra, zobaczył jego teściową, która leżała w gorączce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 15, 'Dotknął więc jej ręki i opuściła ją gorączka. Ona zaś wstała i usługiwała im.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 16, 'Kiedy nastał wieczór, przyprowadzono do niego wielu opętanych. A on wypędził duchy słowem i uzdrowił wszystkich chorych;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 17, 'Aby się wypełniło, co zostało powiedziane przez proroka Izajasza: On nasze słabości wziął na siebie i nosił nasze choroby.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 18, 'A Jezus, widząc wokół siebie mnóstwo ludzi, kazał przeprawić się na drugi brzeg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 19, 'Wtedy podszedł pewien uczony w Piśmie i powiedział do niego: Mistrzu, pójdę za tobą, dokądkolwiek pójdziesz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 20, 'I powiedział mu Jezus: Lisy mają nory, a ptaki niebieskie – gniazda, ale Syn Człowieczy nie ma gdzie położyć głowy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 21, 'A inny spośród jego uczniów powiedział do niego: Panie, pozwól mi najpierw pójść i pogrzebać mego ojca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 22, 'Ale Jezus mu odpowiedział: Pójdź za mną, a umarli niech grzebią swoich umarłych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 23, 'Gdy wsiadł do łodzi, weszli za nim i jego uczniowie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 24, 'A oto zerwała się na morzu wielka burza, tak że fale zalewały łódź. On zaś spał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 25, 'A jego uczniowie, podszedłszy, obudzili go, mówiąc: Panie, ratuj nas! Giniemy!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 26, 'I powiedział do nich: Czemu się boicie, ludzie małej wiary? Potem wstał, zgromił wichry i morze i nastała wielka cisza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 27, 'A ludzie dziwili się i mówili: Cóż to za człowiek, że nawet wichry i morze są mu posłuszne?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 28, 'Kiedy przeprawił się na drugą stronę do krainy Gerazeńczyków, zabiegli mu drogę dwaj opętani, którzy wyszli z grobowców, tak bardzo groźni, że nikt nie mógł przechodzić tą drogą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 29, 'I zaczęli krzyczeć: Cóż my mamy z tobą, Jezusie, Synu Boży? Przyszedłeś tu przed czasem dręczyć nas?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 30, 'Z dala od nich pasło się wielkie stado świń.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 31, 'Demony więc prosiły go: Jeśli nas wypędzasz, pozwól nam wejść w to stado świń.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 32, 'I powiedział im: Idźcie. A one, wyszedłszy, weszły w to stado świń. Naraz całe stado ruszyło pędem po urwisku do morza i zginęło w wodach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 33, 'A pasterze uciekli i poszedłszy do miasta, opowiedzieli wszystko, także to, co się stało z opętanymi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 34, 'Wówczas całe miasto wyszło Jezusowi na spotkanie, a ujrzawszy go, prosili, aby odszedł z ich granic.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 1, 'Wtedy wsiadł do łodzi, przeprawił się na drugi brzeg i przybył do swego miasta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 2, 'A oto przynieśli mu sparaliżowanego, leżącego na posłaniu. Jezus, widząc ich wiarę, powiedział do sparaliżowanego: Ufaj, synu! Twoje grzechy są ci przebaczone.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 3, 'A niektórzy z uczonych w Piśmie pomyśleli sobie: On bluźni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 4, 'Lecz Jezus, znając ich myśli, powiedział: Dlaczego myślicie złe rzeczy w swoich sercach?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 5, 'Cóż bowiem jest łatwiej powiedzieć: Przebaczone są twoje grzechy, czy powiedzieć: Wstań i chodź?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 6, 'Ale abyście wiedzieli, że Syn Człowieczy ma na ziemi moc przebaczać grzechy – wtedy powiedział do sparaliżowanego: Wstań, weź swoje posłanie i idź do domu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 7, 'A on wstał i poszedł do swego domu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 8, 'Kiedy tłumy to ujrzały, dziwiły się i chwaliły Boga, który dał ludziom taką moc.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 9, 'A odchodząc stamtąd, Jezus zobaczył człowieka zwanego Mateuszem, siedzącego w punkcie celnym. I powiedział do niego: Pójdź za mną. A on wstał i poszedł za nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 10, 'Gdy Jezus siedział za stołem w jego domu, przyszło wielu celników i grzeszników i usiedli z Jezusem oraz jego uczniami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 11, 'Widząc to, faryzeusze zapytali jego uczniów: Dlaczego wasz nauczyciel je z celnikami i grzesznikami?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 12, 'A gdy Jezus to usłyszał, powiedział im: Nie zdrowi, lecz chorzy potrzebują lekarza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 13, 'Idźcie więc i nauczcie się, co to znaczy: Miłosierdzia chcę, a nie ofiary. Bo nie przyszedłem wzywać do pokuty sprawiedliwych, ale grzeszników.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 14, 'Wtedy przyszli do niego uczniowie Jana i zapytali: Dlaczego my i faryzeusze często pościmy, a twoi uczniowie nie poszczą?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 15, 'I powiedział im Jezus: Czy przyjaciele oblubieńca mogą się smucić, dopóki jest z nimi oblubieniec? Ale przyjdą dni, gdy oblubieniec zostanie od nich zabrany, i wtedy będą pościć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 16, 'Nikt nie przyszywa łaty z nowego sukna do starej szaty, bo taka łata ściąga nieco szatę i rozdarcie staje się gorsze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 17, 'Ani nie wlewa się młodego wina do starych bukłaków, bo inaczej bukłaki pękają, a wino wycieka i bukłaki się psują. Ale młode wino wlewa się do nowych bukłaków, a wtedy zachowuje się jedno i drugie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 18, 'Gdy to do nich mówił, pewien przełożony synagogi przyszedł, oddał mu pokłon i powiedział: Moja córka dopiero co umarła, ale przyjdź i połóż na nią rękę, a ożyje.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 19, 'Wtedy Jezus wstał i wraz ze swoimi uczniami poszedł za nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 20, 'I oto kobieta, która od dwunastu lat cierpiała na krwotok, podeszła z tyłu i dotknęła brzegu jego szaty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 21, 'Mówiła bowiem sobie: Jeśli tylko dotknę jego szaty, będę uzdrowiona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 22, 'Ale Jezus odwrócił się i ujrzawszy ją, powiedział: Ufaj, córko! Twoja wiara cię uzdrowiła. I od tej chwili kobieta była zdrowa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 23, 'A gdy Jezus przyszedł do domu przełożonego i zobaczył flecistów i ludzi czyniących zgiełk;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 24, 'Powiedział im: Odejdźcie, bo dziewczynka nie umarła, tylko śpi. I naśmiewali się z niego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 25, 'Ale gdy wygnano tych ludzi, wszedł, ujął ją za rękę i dziewczynka wstała.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 26, 'I wieść o tym rozeszła się po całej tamtejszej ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 27, 'A gdy Jezus odchodził stamtąd, szli za nim dwaj ślepi i wołali: Synu Dawida, zmiłuj się nad nami!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 28, 'Gdy zaś wszedł do domu, przyszli do niego ślepi. I zapytał ich Jezus: Wierzycie, że mogę to uczynić? Odpowiedzieli mu: Tak, Panie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 29, 'Wtedy dotknął ich oczu i powiedział: Według waszej wiary niech się wam stanie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 30, 'I otworzyły się ich oczy, a Jezus przykazał im surowo: Uważajcie, aby nikt się o tym nie dowiedział.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 31, 'Lecz oni, wyszedłszy, rozsławili go po całej tamtejszej ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 32, 'A gdy wychodzili, przyprowadzono do niego niemowę opętanego przez demona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 33, 'Kiedy demon został wypędzony, niemy przemówił. A tłumy dziwiły się i mówiły: Nigdy czegoś takiego nie widziano w Izraelu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 34, 'Lecz faryzeusze mówili: Przez władcę demonów wypędza demony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 35, 'I obchodził Jezus wszystkie miasta i wioski, nauczając w ich synagogach i głosząc ewangelię królestwa, uzdrawiając wszystkie choroby i wszelkie słabości wśród ludzi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 36, 'A widząc tłumy ludzi, użalił się nad nimi, bo byli utrudzeni i rozproszeni jak owce niemające pasterza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 37, 'Wtedy powiedział do swoich uczniów: Żniwo wprawdzie wielkie, ale robotników mało.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 38, 'Proście więc Pana żniwa, aby wysłał robotników na swoje żniwo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 1, 'A przywoławszy swoich dwunastu uczniów, dał im moc nad duchami nieczystymi, aby je wypędzali i aby uzdrawiali wszystkie choroby i wszelkie słabości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 2, 'A takie są imiona dwunastu apostołów: pierwszy Szymon, zwany Piotrem, i jego brat Andrzej, Jakub, syn Zebedeusza, i Jan, jego brat;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 3, 'Filip i Bartłomiej, Tomasz i celnik Mateusz, Jakub, syn Alfeusza, i Lebeusz, nazwany Tadeuszem;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 4, 'Szymon Kananejczyk i Judasz Iskariota, ten, który go zdradził.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 5, 'Tych dwunastu posłał Jezus i nakazał im: Nie wchodźcie na drogę pogan i nie wstępujcie do żadnego miasta Samarytan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 6, 'Idźcie raczej do owiec zaginionych z domu Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 7, 'A idąc, głoście: Przybliżyło się królestwo niebieskie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 8, 'Uzdrawiajcie chorych, oczyszczajcie trędowatych, wskrzeszajcie umarłych, wypędzajcie demony. Darmo otrzymaliście, darmo dawajcie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 9, 'Nie bierzcie ze sobą do trzosa złota ani srebra, ani miedzi;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 10, 'Ani torby na drogę, ani dwóch ubrań, ani obuwia, ani laski. Godny jest bowiem pracownik swego wyżywienia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 11, 'A gdy wejdziecie do jakiegoś miasta albo wioski, dowiedzcie się, kto w nim jest godny i tam mieszkajcie, dopóki nie odejdziecie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 12, 'A wchodząc do domu, pozdrówcie go.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 13, 'Jeśli ten dom jest tego godny, niech zstąpi na niego wasz pokój, a jeśli nie jest godny, niech wasz pokój powróci do was.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 14, 'A jeśli ktoś was nie przyjmie i nie usłucha waszych słów, wychodząc z tego domu albo miasta, strząśnijcie pył z waszych nóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 15, 'Zaprawdę powiadam wam: Lżej będzie ziemi sodomskiej i gomorskiej w dzień sądu niż temu miastu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 16, 'Oto ja was posyłam jak owce między wilki. Bądźcie więc roztropni jak węże i niewinni jak gołębice.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 17, 'I strzeżcie się ludzi. Będą was bowiem wydawać radom i będą was biczować w swoich synagogach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 18, 'Także przed namiestników i przed królów będą was prowadzić z mego powodu, na świadectwo przeciwko nim i poganom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 19, 'Ale gdy was wydadzą, nie martwcie się, jak i co macie mówić. Będzie wam bowiem dane w tej godzinie, co macie mówić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 20, 'Bo nie wy mówicie, ale Duch waszego Ojca mówi w was.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 21, 'I wyda na śmierć brat brata, a ojciec syna. Dzieci powstaną przeciwko rodzicom i spowodują ich śmierć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 22, 'I będziecie znienawidzeni przez wszystkich z powodu mego imienia. Lecz kto wytrwa do końca, będzie zbawiony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 23, 'A gdy będą was prześladować w tym mieście, uciekajcie do innego. Zaprawdę powiadam wam, że nie obejdziecie miast Izraela, aż przyjdzie Syn Człowieczy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 24, 'Uczeń nie przewyższa mistrza ani sługa swego pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 25, 'Wystarczy uczniowi, że będzie jak jego mistrz, a sługa jak jego pan. Jeśli gospodarza nazywali Belzebubem, o ile bardziej będą tak nazywać jego domowników.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 26, 'Dlatego nie bójcie się ich. Nie ma bowiem nic ukrytego, co by nie miało być ujawnione, ani nic tajemnego, o czym by się nie miano dowiedzieć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 27, 'Co mówię wam w ciemności, opowiadajcie w świetle, a co słyszycie na ucho, rozgłaszajcie na dachach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 28, 'Nie bójcie się tych, którzy zabijają ciało, lecz nie mogą zabić duszy. Bójcie się raczej tego, który może i duszę, i ciało zatracić w piekielnym ogniu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 29, 'Czy nie sprzedają dwóch wróbli za pieniążek? A jednak żaden z nich nie spadnie na ziemię bez woli waszego Ojca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 30, 'Nawet wszystkie włosy na waszej głowie są policzone.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 31, 'Nie bójcie się więc, jesteście cenniejsi niż wiele wróbli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 32, 'Każdego więc, kto mnie wyzna przed ludźmi, i ja wyznam przed moim Ojcem, który jest w niebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 33, 'A tego, kto się mnie wyprze przed ludźmi, i ja się wyprę przed moim Ojcem, który jest w niebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 34, 'Nie sądźcie, że przyszedłem przynieść pokój na ziemię. Nie przyszedłem przynieść pokoju, ale miecz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 35, 'Bo przyszedłem poróżnić syna z jego ojcem i córkę z jej matką, a synową z teściową.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 36, 'I nieprzyjaciółmi człowieka będą jego domownicy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 37, 'Kto miłuje ojca albo matkę bardziej niż mnie, nie jest mnie godny. I kto miłuje syna albo córkę bardziej niż mnie, nie jest mnie godny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 38, 'Kto nie bierze swego krzyża i nie idzie za mną, nie jest mnie godny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 39, 'Kto znajdzie swoje życie, straci je, a kto straci swoje życie z mego powodu, znajdzie je.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 40, 'Kto was przyjmuje, mnie przyjmuje, a kto mnie przyjmuje, przyjmuje tego, który mnie posłał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 41, 'Kto przyjmuje proroka w imię proroka, otrzyma nagrodę proroka. Kto przyjmuje sprawiedliwego w imię sprawiedliwego, otrzyma nagrodę sprawiedliwego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 42, 'A kto poda jednemu z tych małych choćby kubek zimnej wody w imię ucznia, zaprawdę powiadam wam, nie straci swojej nagrody.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 1, 'Kiedy Jezus skończył rozkazywać swoim dwunastu uczniom, odszedł stamtąd, aby nauczać i głosić w ich miastach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 2, 'A gdy Jan usłyszał w więzieniu o czynach Chrystusa, posłał dwóch ze swoich uczniów;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 3, 'Z pytaniem: Czy ty jesteś tym, który ma przyjść, czy mamy oczekiwać innego?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 4, 'A Jezus odpowiedział im: Idźcie i oznajmijcie Janowi, co słyszycie i widzicie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 5, 'Ślepi widzą, chromi chodzą, trędowaci zostają oczyszczeni, głusi słyszą, umarli zmartwychwstają, a ubogim opowiadana jest ewangelia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 6, 'A błogosławiony jest ten, kto się nie zgorszy z mojego powodu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 7, 'A gdy odeszli, Jezus zaczął mówić do tłumów o Janie: Co wyszliście oglądać na pustyni? Trzcinę kołyszącą się na wietrze?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 8, 'Ale co wyszliście zobaczyć? Człowieka ubranego w miękkie szaty? Oto ci, którzy noszą miękkie szaty, są w domach królewskich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 9, 'Ale co wyszliście zobaczyć? Proroka? Owszem, mówię wam, nawet więcej niż proroka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 10, 'Bo on jest tym, o którym jest napisane: Oto ja posyłam mego posłańca przed twoim obliczem, który przygotuje twoją drogę przed tobą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 11, 'Zaprawdę powiadam wam: Nie powstał z tych, którzy rodzą się z kobiet, większy od Jana Chrzciciela. Ale ten, kto jest najmniejszy w królestwie niebieskim, jest większy niż on.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 12, 'A od dni Jana Chrzciciela aż dotąd królestwo niebieskie doznaje gwałtu i gwałtownicy je zdobywają.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 13, 'Bo wszyscy Prorocy i Prawo prorokowali aż do Jana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 14, 'A jeśli chcecie to przyjąć, on jest Eliaszem, który miał przyjść.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 15, 'Kto ma uszy do słuchania, niech słucha.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 16, 'Ale do kogo przyrównam to pokolenie? Podobne jest do dzieci, które siedzą na rynku i wołają na swoich towarzyszy:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 17, 'Graliśmy wam na flecie, a nie tańczyliście; śpiewaliśmy pieśni żałobne, a nie płakaliście.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 18, 'Przyszedł bowiem Jan, nie jadł i nie pił, a mówią: Ma demona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 19, 'Przyszedł Syn Człowieczy, jedząc i pijąc, a mówią: Oto żarłok i pijak, przyjaciel celników i grzeszników. Lecz usprawiedliwiona jest mądrość przez swoje dzieci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 20, 'Wtedy zaczął ganić miasta, w których działo się najwięcej jego cudów, że nie pokutowały, mówiąc:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 21, 'Biada tobie, Korozain! Biada tobie, Betsaido! Bo gdyby w Tyrze i Sydonie działy się te cuda, które się w was dokonały, dawno by w worze i popiele pokutowały.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 22, 'Ale mówię wam: Lżej będzie Tyrowi i Sydonowi w dniu sądu niż wam.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 23, 'A ty, Kafarnaum, które jesteś wywyższone aż do nieba, aż do piekła będziesz strącone. Bo gdyby w Sodomie działy się cuda, które się w tobie dokonały, przetrwałaby aż do dziś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 24, 'Ale mówię wam: Lżej będzie ziemi Sodomy w dzień sądu niż tobie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 25, 'W tym czasie Jezus powiedział: Wysławiam cię, Ojcze, Panie nieba i ziemi, że zakryłeś te sprawy przed mądrymi i roztropnymi, a objawiłeś je niemowlętom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 26, 'Tak, Ojcze, gdyż tak się tobie upodobało.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 27, 'Wszystko zostało mi dane od mego Ojca i nikt nie zna Syna, tylko Ojciec, ani nikt nie zna Ojca, tylko Syn i ten, komu Syn zechce objawić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 28, 'Przyjdźcie do mnie wszyscy, którzy jesteście spracowani i obciążeni, a ja wam dam odpoczynek.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 29, 'Weźcie na siebie moje jarzmo i uczcie się ode mnie, że jestem cichy i pokornego serca, a znajdziecie odpoczynek dla waszych dusz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 30, 'Moje jarzmo bowiem jest przyjemne, a moje brzemię lekkie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 1, 'W tym czasie Jezus przechodził w szabat wśród zbóż, a jego uczniowie byli głodni i zaczęli zrywać kłosy, i jeść.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 2, 'Kiedy faryzeusze to zobaczyli, powiedzieli mu: Oto twoi uczniowie robią to, czego nie wolno robić w szabat.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 3, 'A on im powiedział: Czy nie czytaliście, co zrobił Dawid, gdy był głodny, on i ci, którzy z nim byli?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 4, 'Jak wszedł do domu Bożego i jadł chleby pokładne, których nie wolno było jeść jemu ani tym, którzy z nim byli, tylko samym kapłanom?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 5, 'Albo czy nie czytaliście w prawie, że w szabat kapłani w świątyni naruszają szabat, a są bez winy?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 6, 'Ale mówię wam, że tu jest ktoś większy niż świątynia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 7, 'A gdybyście wiedzieli, co to znaczy: Miłosierdzia chcę, a nie ofiary, nie potępialibyście niewinnych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 8, 'Syn Człowieczy bowiem jest też Panem szabatu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 9, 'I odszedłszy stamtąd, wszedł do ich synagogi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 10, 'A był tam człowiek, który miał uschłą rękę. I chcąc go oskarżyć, zapytali: Czy wolno uzdrawiać w szabat?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 11, 'A on im odpowiedział: Któż z was, mając jedną owcę, która w szabat wpadłaby do dołu, nie chwyci jej i nie wyciągnie?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 12, 'A o ileż ważniejszy jest człowiek niż owca! Tak więc wolno w szabat dobrze czynić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 13, 'Wtedy powiedział do tego człowieka: Wyciągnij rękę. On ją wyciągnął i znowu stała się zdrowa jak i druga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 14, 'A faryzeusze, wyszedłszy, naradzali się przeciwko niemu, w jaki sposób go zgładzić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 15, 'Lecz Jezus, poznawszy to, odszedł stamtąd. Poszło za nim mnóstwo ludzi, a on uzdrowił ich wszystkich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 16, 'I przykazał im, aby go nie ujawniali;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 17, 'Żeby się wypełniło, co zostało powiedziane przez proroka Izajasza, który powiedział:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 18, 'Oto mój sługa, którego wybrałem, mój umiłowany, w którym moja dusza ma upodobanie. Złożę na nim mojego Ducha, a on ogłosi sąd narodom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 19, 'Nie będzie się spierał ani krzyczał i nikt nie usłyszy na ulicach jego głosu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 20, 'Trzciny nadłamanej nie złamie, a knota tlącego się nie zagasi, dopóki nie doprowadzi sądu do zwycięstwa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 21, 'A w jego imieniu narody będą pokładać nadzieję.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 22, 'Wtedy przyprowadzono do niego opętanego, który był ślepy i niemy. I uzdrowił go tak, że ten ślepy i niemy mówił i widział.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 23, 'A wszyscy ludzie, zdumieni, mówili: Czyż to nie jest syn Dawida?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 24, 'Ale faryzeusze, usłyszawszy to, powiedzieli: On nie wypędza demonów inaczej, jak tylko przez Belzebuba, władcę demonów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 25, 'Lecz Jezus, znając ich myśli, powiedział im: Każde królestwo podzielone wewnętrznie pustoszeje i żadne miasto albo dom podzielony wewnętrznie nie przetrwa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 26, 'A jeśli szatan wypędza szatana, jest podzielony wewnętrznie. Jakże więc przetrwa jego królestwo?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 27, 'Jeśli ja przez Belzebuba wypędzam demony, to przez kogo wypędzają wasi synowie? Dlatego oni będą waszymi sędziami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 28, 'A jeśli ja wypędzam demony Duchem Bożym, to przyszło do was królestwo Boże.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 29, 'Albo jak może ktoś wejść do domu mocarza i zagrabić jego własność, jeśli najpierw nie zwiąże mocarza? Dopiero wtedy ograbi jego dom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 30, 'Kto nie jest ze mną, jest przeciwko mnie, a kto nie zbiera ze mną, rozprasza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 31, 'Dlatego mówię wam: Każdy grzech i bluźnierstwo będzie ludziom przebaczone, ale bluźnierstwo przeciwko Duchowi Świętemu nie będzie ludziom przebaczone.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 32, 'I ktokolwiek powie słowo przeciwko Synowi Człowieczemu, będzie mu przebaczone, ale kto mówi przeciwko Duchowi Świętemu, nie będzie mu przebaczone ani w tym świecie, ani w przyszłym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 33, 'Sprawcie, aby drzewo było dobre i jego owoc dobry, albo sprawcie, aby drzewo było złe i jego owoc zły. Po owocu bowiem poznaje się drzewo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 34, 'Plemię żmijowe! Jakże możecie mówić dobre rzeczy, będąc złymi? Gdyż z obfitości serca mówią usta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 35, 'Dobry człowiek wydobywa z dobrego skarbca serca dobre rzeczy, a zły człowiek wydobywa ze złego skarbca złe rzeczy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 36, 'Ale mówię wam, że z każdego bezużytecznego słowa, które wypowiedzą ludzie, zdadzą sprawę w dzień sądu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 37, 'Bo na podstawie twoich słów będziesz usprawiedliwiony i na podstawie twoich słów będziesz potępiony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 38, 'Wtedy niektórzy z uczonych w Piśmie i z faryzeuszy odpowiedzieli: Nauczycielu, chcemy widzieć znak od ciebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 39, 'A on odpowiedział im: Pokolenie złe i cudzołożne żąda znaku, ale żaden znak nie będzie mu dany, oprócz znaku proroka Jonasza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 40, 'Jak bowiem Jonasz był w brzuchu wieloryba trzy dni i trzy noce, tak Syn Człowieczy będzie w sercu ziemi trzy dni i trzy noce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 41, 'Ludzie z Niniwy staną na sądzie z tym pokoleniem i potępią je, ponieważ pokutowali wskutek głoszenia Jonasza, a oto tu ktoś więcej niż Jonasz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 42, 'Królowa z Południa stanie na sądzie z tym pokoleniem i potępi je, bo przybyła z krańców ziemi, aby słuchać mądrości Salomona, a oto tu ktoś więcej niż Salomon.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 43, 'Kiedy nieczysty duch wychodzi z człowieka, przechadza się po miejscach bezwodnych, szukając odpoczynku, ale nie znajduje.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 44, 'Wtedy mówi: Wrócę do swego domu, z którego wyszedłem. A przyszedłszy, zastaje go pustym, zamiecionym i przyozdobionym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 45, 'Wówczas idzie i bierze ze sobą siedem innych duchów gorszych niż on sam i wszedłszy, mieszkają tam. I końcowy stan tego człowieka staje się gorszy niż początkowy. Tak będzie i z tym złym pokoleniem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 46, 'A gdy on jeszcze mówił do ludzi, jego matka i bracia stanęli przed domem, chcąc z nim rozmawiać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 47, 'I powiedział mu ktoś: Oto twoja matka i twoi bracia stoją przed domem, chcąc z tobą mówić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 48, 'Lecz on odpowiedział temu, który mu to oznajmił: Któż jest moją matką i kto to są moi bracia?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 49, 'A wyciągnąwszy rękę ku swoim uczniom, powiedział: Oto moja matka i moi bracia!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 50, 'Kto bowiem wypełnia wolę mojego Ojca, który jest w niebie, ten jest moim bratem i siostrą, i matką.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 1, 'A tego dnia Jezus wyszedł z domu i usiadł nad brzegiem morza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 2, 'I zebrały się wokół niego wielkie tłumy, dlatego wszedł do łodzi i usiadł, a wszyscy ludzie stali na brzegu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 3, 'I mówił do nich wiele w przypowieściach. I powiedział: Oto siewca wyszedł siać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 4, 'A gdy siał, niektóre ziarna padły przy drodze, przyleciały ptaki i wydziobały je.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 5, 'Inne padły na miejsca skaliste, gdzie nie miały wiele ziemi. Zaraz wzeszły, bo ziemia nie była głęboka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 6, 'Lecz gdy wzeszło słońce, zostały spalone, a ponieważ nie miały korzenia, uschły.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 7, 'Inne padły między ciernie, a ciernie wyrosły i zagłuszyły je.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 8, 'Inne zaś padły na dobrą ziemię i wydały plon, jedne stokrotny, inne sześćdziesięciokrotny, a jeszcze inne trzydziestokrotny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 9, 'Kto ma uszy do słuchania, niech słucha.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 10, 'Wtedy uczniowie podeszli i zapytali go: Dlaczego mówisz do nich w przypowieściach?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 11, 'A on odpowiedział im: Wam dano poznać tajemnice królestwa niebieskiego, ale im nie jest dane.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 12, 'Kto bowiem ma, temu będzie dodane i będzie miał w obfitości, ale kto nie ma, zostanie mu zabrane nawet to, co ma.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 13, 'Dlatego mówię do nich w przypowieściach, bo patrzą, a nie widzą, i słuchają, a nie słyszą ani nie rozumieją.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 14, 'I spełnia się na nich proroctwo Izajasza, które mówi: Słuchając, będziecie słyszeć, ale nie zrozumiecie i patrząc, będziecie widzieć, ale nie zobaczycie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 15, 'Utyło bowiem serce tego ludu, stępiały ich uszy i zamknęli swe oczy, żeby przypadkiem oczami nie widzieli ani uszami nie słyszeli, a sercem nie zrozumieli i nie nawrócili się, i żebym ich nie uzdrowił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 16, 'Ale błogosławione wasze oczy, bo widzą, i wasze uszy, bo słyszą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 17, 'Bo zaprawdę powiadam wam: Wielu proroków i sprawiedliwych pragnęło widzieć to, co wy widzicie, ale nie zobaczyli, i słyszeć to, co wy słyszycie, ale nie usłyszeli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 18, 'Wysłuchajcie więc przypowieści o siewcy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 19, 'Gdy ktoś słucha słowa o królestwie, a nie rozumie, przychodzi zły i porywa to, co zostało zasiane w jego sercu. To jest ten posiany przy drodze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 20, 'A posiany na miejscach skalistych to ten, który słucha słowa i natychmiast z radością je przyjmuje.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 21, 'Nie ma jednak w sobie korzenia, lecz trwa do czasu. Gdy bowiem przychodzi ucisk albo prześladowanie z powodu słowa, zaraz się gorszy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 22, 'A posiany między ciernie to ten, który słucha słowa, ale troski tego świata i ułuda bogactwa zagłuszają słowo i staje się on bezowocny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 23, 'A posiany na dobrej ziemi to ten, który słucha słowa i rozumie je. On też wydaje plon: jeden stokrotny, inny sześćdziesięciokrotny, a jeszcze inny trzydziestokrotny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 24, 'Podał im też inną przypowieść: Królestwo niebieskie podobne jest do człowieka, który zasiał dobre ziarno na swoim polu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 25, 'Lecz gdy ludzie spali, przyszedł jego nieprzyjaciel, nasiał kąkolu między pszenicę i odszedł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 26, 'A gdy zboże urosło i wydało plon, wtedy ukazał się też kąkol.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 27, 'Wówczas słudzy gospodarza przyszli i zapytali go: Panie, czy nie posiałeś na swoim polu dobrego ziarna? Skąd więc ten kąkol?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 28, 'A on im odpowiedział: Nieprzyjaciel to zrobił. I zapytali go słudzy: Czy chcesz, żebyśmy poszli i zebrali go?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 29, 'Lecz on odpowiedział: Nie, żebyście przypadkiem, zbierając kąkol, nie wykorzenili razem z nim i pszenicy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 30, 'Pozwólcie obydwu razem rosnąć aż do żniwa, a w czasie żniwa powiem żniwiarzom: Zbierzcie najpierw kąkol i zwiążcie go w snopki na spalenie, pszenicę zaś zgromadźcie w moim spichlerzu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 31, 'Podał im też inną przypowieść: Królestwo niebieskie podobne jest do ziarna gorczycy, które człowiek, wziąwszy, zasiał na swoim polu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 32, 'Jest ono najmniejsze ze wszystkich nasion, ale kiedy wyrośnie, jest największe ze wszystkich jarzyn i staje się drzewem, tak że ptaki niebieskie przylatują i gnieżdżą się w jego gałęziach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 33, 'Opowiedział im jeszcze inną przypowieść: Królestwo niebieskie podobne jest do zakwasu, który kobieta wzięła i włożyła w trzy miary mąki, aż wszystko się zakwasiło.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 34, 'To wszystko mówił Jezus do tłumu w przypowieściach, a bez przypowieści nic do nich nie mówił;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 35, 'Aby się wypełniło, co zostało powiedziane przez proroka: Otworzę moje usta w przypowieściach, wypowiem rzeczy ukryte od założenia świata.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 36, 'Wtedy Jezus odprawił tłum i przyszedł do domu. Podeszli do niego jego uczniowie i mówili: Wyjaśnij nam przypowieść o kąkolu na polu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 37, 'A on odpowiedział im: Tym, który sieje dobre ziarno, jest Syn Człowieczy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 38, 'Polem jest świat, dobrym ziarnem są synowie królestwa, kąkolem zaś są synowie złego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 39, 'Nieprzyjacielem, który go posiał, jest diabeł, żniwem jest koniec świata, a żniwiarzami są aniołowie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 40, 'Jak więc zbiera się kąkol i spala w ogniu, tak będzie przy końcu tego świata.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 41, 'Syn Człowieczy pośle swoich aniołów, a oni zbiorą z jego królestwa wszystkie zgorszenia i tych, którzy popełniają nieprawość;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 42, 'I wrzucą ich do pieca ognistego. Tam będzie płacz i zgrzytanie zębów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 43, 'Wtedy sprawiedliwi będą jaśnieć jak słońce w królestwie swego Ojca. Kto ma uszy do słuchania, niech słucha.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 44, 'Ponownie królestwo niebieskie jest podobne do skarbu ukrytego w polu, który człowiek znalazł i ukrył. Uradowany nim poszedł, sprzedał wszystko, co miał, i kupił to pole.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 45, 'Królestwo niebieskie podobne jest też do kupca, który szukał pięknych pereł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 46, 'A znalazłszy jedną bardzo cenną perłę, poszedł, sprzedał wszystko, co miał, i kupił ją.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 47, 'Królestwo niebieskie podobne jest również do sieci zarzuconej w morze i zagarniającej ryby wszelkiego rodzaju.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 48, 'Gdy się napełniła, rybacy wyciągnęli ją na brzeg, a usiadłszy, dobre ryby wybrali do naczyń, a złe wyrzucili.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 49, 'Tak będzie przy końcu świata: wyjdą aniołowie i wyłączą złych spośród sprawiedliwych;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 50, 'I wrzucą ich do pieca ognistego. Tam będzie płacz i zgrzytanie zębów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 51, 'Jezus ich zapytał: Zrozumieliście to wszystko? Odpowiedzieli mu: Tak, Panie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 52, 'A on powiedział do nich: Dlatego każdy uczony w Piśmie, który jest pouczony o królestwie niebieskim, podobny jest do gospodarza, który wydobywa ze swego skarbca nowe i stare rzeczy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 53, 'Kiedy Jezus dokończył tych przypowieści, odszedł stamtąd.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 54, 'A przyszedłszy w swoje rodzinne strony, nauczał ludzi w ich synagodze, tak że się bardzo zdumiewali i mówili: Skąd on ma tę mądrość i moc?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 55, 'Czyż to nie jest syn cieśli? Czyż jego matce nie jest na imię Maria, a jego bracia to Jakub, Józef, Szymon i Juda?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 56, 'A jego siostry, czyż wszystkie nie są wśród nas? Skąd więc on ma to wszystko?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 57, 'I byli nim zgorszeni. Lecz Jezus powiedział do nich: Nigdzie nie jest prorok bez czci, tylko w swojej ojczyźnie i w swoim domu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 58, 'I nie uczynił tam wielu cudów z powodu ich niewiary.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 1, 'W tym czasie tetrarcha Herod usłyszał wieść o Jezusie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 2, 'I powiedział swoim sługom: To jest Jan Chrzciciel. On zmartwychwstał i dlatego cuda dokonują się przez niego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 3, 'Herod bowiem schwytał Jana, związał go i wtrącił do więzienia z powodu Herodiady, żony swego brata Filipa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 4, 'Bo Jan mówił mu: Nie wolno ci jej mieć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 5, 'I chciał go zabić, ale bał się ludu, bo uważano go za proroka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 6, 'A gdy obchodzono dzień urodzin Heroda, córka Herodiady tańczyła wśród gości i spodobała się Herodowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 7, 'Dlatego pod przysięgą obiecał jej dać, o cokolwiek poprosi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 8, 'A ona, namówiona przedtem przez swoją matkę, powiedziała: Daj mi tu na misie głowę Jana Chrzciciela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 9, 'I zasmucił się król, ale ze względu na przysięgę i współbiesiadników kazał jej dać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 10, 'A posławszy kata, ściął Jana w więzieniu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 11, 'I przyniesiono jego głowę na misie, i dano dziewczynie, a ona zaniosła ją swojej matce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 12, 'Potem przyszli jego uczniowie, zabrali ciało i pogrzebali je, a poszedłszy, powiedzieli o tym Jezusowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 13, 'A Jezus, usłyszawszy to, oddalił się stamtąd łodzią na miejsce odludne, żeby być na osobności. Kiedy ludzie o tym usłyszeli, pieszo poszli za nim z miast.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 14, 'Gdy Jezus wyszedł z łodzi, zobaczył wielki tłum, ulitował się nad nimi i uzdrawiał ich chorych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 15, 'A gdy nastał wieczór, podeszli do niego jego uczniowie i powiedzieli: Miejsce to jest puste, a pora już późna. Odpraw tych ludzi, aby poszli do wiosek i kupili sobie żywności.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 16, 'Lecz Jezus im odpowiedział: Nie muszą odchodzić, wy dajcie im jeść.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 17, 'A oni mu powiedzieli: Nie mamy tu nic prócz pięciu chlebów i dwóch ryb.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 18, 'On powiedział: Przynieście mi je tutaj.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 19, 'Wtedy nakazał ludziom usiąść na trawie, wziął te pięć chlebów i dwie ryby, a spojrzawszy w niebo, pobłogosławił i łamiąc chleby, dawał uczniom, a uczniowie ludziom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 20, 'I jedli wszyscy do syta. I zebrali z pozostałych kawałków dwanaście pełnych koszy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 21, 'A tych, którzy jedli, było około pięciu tysięcy mężczyzn, nie licząc kobiet i dzieci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 22, 'Zaraz też Jezus przymusił swoich uczniów, aby wsiedli do łodzi i wyprzedzili go na drugi brzeg, a on tymczasem odprawi tłumy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 23, 'A odprawiwszy je, wszedł sam na górę, aby się modlić. A gdy nastał wieczór, nadal był tam sam.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 24, 'Łódź tymczasem była już na środku morza, miotana przez fale, bo wiatr był przeciwny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 25, 'Lecz o czwartej straży nocnej przyszedł do nich Jezus, idąc po morzu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 26, 'A uczniowie, gdy ujrzeli go idącego po morzu, przerazili się i powiedzieli: To zjawa! I krzyknęli ze strachu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 27, 'Ale Jezus zaraz do nich powiedział: Ufajcie, to ja jestem! Nie bójcie się!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 28, 'Piotr odezwał się do niego: Panie, jeśli to jesteś ty, każ mi przyjść do siebie po wodzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 29, 'A on powiedział: Przyjdź! I Piotr, wyszedłszy z łodzi, szedł po wodzie, aby przyjść do Jezusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 30, 'Lecz widząc gwałtowny wiatr, zląkł się, a gdy zaczął tonąć, krzyknął: Panie, ratuj mnie!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 31, 'Jezus natychmiast wyciągnął rękę, uchwycił go i powiedział: Człowieku małej wiary, dlaczego zwątpiłeś?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 32, 'A gdy wsiedli do łodzi, wiatr się uciszył.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 33, 'Ci zaś, którzy byli w łodzi, podeszli i oddali mu pokłon, mówiąc: Naprawdę jesteś Synem Bożym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 34, 'I przeprawiwszy się, przybyli do ziemi Genezaret.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 35, 'A ludzie z tamtych okolic, poznawszy go, rozesłali wiadomość po całej okolicy i przyniesiono do niego wszystkich chorych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 36, 'I prosili go, aby mogli dotknąć tylko brzegu jego szaty, a ci, którzy dotknęli, zostali uzdrowieni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 1, 'Wtedy z Jerozolimy przyszli do Jezusa uczeni w Piśmie i faryzeusze i zapytali:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 2, 'Czemu twoi uczniowie postępują wbrew tradycji starszych? Nie myją bowiem rąk przed jedzeniem chleba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 3, 'A on odpowiedział im: Czemu i wy postępujecie wbrew przykazaniu Bożemu dla waszej tradycji?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 4, 'Bóg bowiem nakazał: Czcij swego ojca i matkę, oraz: Kto złorzeczy ojcu albo matce, niech poniesie śmierć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 5, 'Ale wy mówicie: Kto by powiedział ojcu albo matce: To, co powinieneś otrzymać ode mnie jako pomoc, jest darem ofiarnym;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 6, 'I nie uczciłby swego ojca ani matki, będzie bez winy. I tak unieważniliście przykazanie Boże przez waszą tradycję.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 7, 'Obłudnicy, dobrze prorokował o was Izajasz:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 8, 'Lud ten przybliża się do mnie swymi ustami i czci mnie wargami, ale ich serce daleko jest ode mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 9, 'Lecz na próżno mnie czczą, ucząc nauk, które są przykazaniami ludzkimi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 10, 'Potem przywołał do siebie tłum i powiedział: Słuchajcie i zrozumiejcie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 11, 'Nie to, co wchodzi do ust, kala człowieka, ale co z ust wychodzi, to kala człowieka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 12, 'Wtedy podeszli jego uczniowie i powiedzieli do niego: Wiesz, że faryzeusze zgorszyli się, gdy usłyszeli te słowa?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 13, 'A on odpowiedział: Każda roślina, której nie zasadził mój Ojciec niebieski, będzie wykorzeniona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 14, 'Zostawcie ich! To są ślepi przewodnicy ślepych, a jeśli ślepy prowadzi ślepego, obaj w dół wpadną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 15, 'Wtedy Piotr powiedział do niego: Wyjaśnij nam tę przypowieść.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 16, 'Jezus odpowiedział: Wy też jeszcze jesteście niepojętni?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 17, 'Jeszcze nie rozumiecie, że wszystko, co wchodzi do ust, idzie do żołądka i zostaje wydalone do ustępu?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 18, 'Ale to, co z ust wychodzi, pochodzi z serca i to kala człowieka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 19, 'Z serca bowiem pochodzą złe myśli, zabójstwa, cudzołóstwa, nierząd, kradzieże, fałszywe świadectwa, bluźnierstwa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 20, 'To właśnie kala człowieka. Lecz jedzenie nieumytymi rękami nie kala człowieka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 21, 'Potem Jezus odszedł stamtąd i udał się w okolice Tyru i Sydonu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 22, 'A oto kobieta kananejska, wyszedłszy z tamtych okolic, wołała do niego: Zmiłuj się nade mną, Panie, Synu Dawida! Moja córka jest ciężko dręczona przez demona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 23, 'On jednak nie odpowiedział jej ani słowa. Wówczas jego uczniowie podeszli i prosili go: Odpraw ją, bo woła za nami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 24, 'A on odpowiedział: Jestem posłany tylko do owiec zaginionych z domu Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 25, 'Lecz ona podeszła i oddała mu pokłon, mówiąc: Panie, pomóż mi!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 26, 'On jednak odpowiedział: Niedobrze jest brać chleb dzieci i rzucać szczeniętom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 27, 'A ona powiedziała: Tak, Panie, ale i szczenięta jedzą okruchy, które spadają ze stołu ich panów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 28, 'Wtedy Jezus jej odpowiedział: O kobieto, wielka jest twoja wiara! Niech ci się stanie, jak chcesz. I od tej chwili jej córka była zdrowa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 29, 'A Jezus odszedł stamtąd i przyszedł nad Morze Galilejskie. Wszedł na górę i tam usiadł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 30, 'I przyszły do niego wielkie tłumy, mając ze sobą chromych, ślepych, niemych, ułomnych oraz wielu innych. Położyli ich u nóg Jezusa, a on ich uzdrowił;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 31, 'Tak że tłumy dziwiły się, widząc, że niemi mówią, ułomni są uzdrowieni, chromi chodzą, a ślepi widzą. I wielbili Boga Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 32, 'Lecz Jezus przywołał swoich uczniów i powiedział: Żal mi tych ludzi, bo już trzy dni przy mnie trwają i nie mają co jeść. Nie chcę ich odprawić głodnych, aby przypadkiem nie zasłabli w drodze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 33, 'Wtedy jego uczniowie powiedzieli mu: Skąd na tej pustyni weźmiemy tyle chleba, aby nakarmić takie mnóstwo ludzi?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 34, 'Zapytał ich Jezus: Ile macie chlebów? A oni odpowiedzieli: Siedem i kilka rybek.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 35, 'I nakazał ludziom usiąść na ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 36, 'Potem wziął te siedem chlebów i ryby, a podziękowawszy, łamał i dawał swoim uczniom, a uczniowie ludziom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 37, 'I jedli wszyscy do syta, a z pozostałych kawałków zebrali siedem pełnych koszy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 38, 'Tych zaś, którzy jedli, było cztery tysiące mężczyzn, nie licząc kobiet i dzieci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 39, 'A gdy odprawił ludzi, wsiadł do łodzi i przybył w okolice Magdali.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 1, 'Podeszli faryzeusze i saduceusze i wystawiając go na próbę, prosili, aby pokazał im znak z nieba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 2, 'A on im odpowiedział: Gdy nastaje wieczór, mówicie: Będzie pogoda, bo niebo się czerwieni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 3, 'Rano zaś: Dziś będzie niepogoda, bo niebo się czerwieni i jest zachmurzone. Obłudnicy, wygląd nieba umiecie rozpoznać, a znaków tych czasów nie możecie?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 4, 'Pokolenie złe i cudzołożne żąda znaku, ale żaden znak nie będzie mu dany oprócz znaku proroka Jonasza. I opuściwszy ich, odszedł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 5, 'A gdy jego uczniowie przeprawili się na drugą stronę morza, zapomnieli wziąć chleba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 6, 'I powiedział im Jezus: Uważajcie i strzeżcie się zakwasu faryzeuszy i saduceuszy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 7, 'A oni rozmawiali między sobą: Nie wzięliśmy chleba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 8, 'Gdy Jezus to zauważył, powiedział im: Ludzie małej wiary, czemu rozmawiacie między sobą o tym, że nie wzięliście chleba?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 9, 'Jeszcze nie rozumiecie ani nie pamiętacie tych pięciu chlebów i pięciu tysięcy ludzi oraz ile koszy zebraliście?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 10, 'Ani tych siedmiu chlebów i czterech tysięcy ludzi oraz ile koszy zebraliście?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 11, 'Jak to jest, że nie rozumiecie, iż nie o chlebie wam powiedziałem, mówiąc, abyście się strzegli zakwasu faryzeuszy i saduceuszy?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 12, 'Wtedy zrozumieli, że nie mówił, aby się strzegli zakwasu chlebowego, ale nauki faryzeuszy i saduceuszy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 13, 'A gdy Jezus przyszedł w okolice Cezarei Filipowej, pytał swoich uczniów: Za kogo mnie, Syna Człowieczego, uważają ludzie?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 14, 'A oni odpowiedzieli: Jedni za Jana Chrzciciela, inni za Eliasza, a jeszcze inni za Jeremiasza albo za jednego z proroków.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 15, 'I zapytał ich: A wy za kogo mnie uważacie?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 16, 'Szymon Piotr odpowiedział: Ty jesteś Chrystusem, Synem Boga żywego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 17, 'Wtedy Jezus powiedział do niego: Błogosławiony jesteś, Szymonie, synu Jonasza, bo nie objawiły ci tego ciało i krew, ale mój Ojciec, który jest w niebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 18, 'Ja ci też mówię, że ty jesteś Piotr, a na tej skale zbuduję mój kościół, a bramy piekła go nie przemogą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 19, 'I tobie dam klucze królestwa niebieskiego. Cokolwiek zwiążesz na ziemi, będzie związane i w niebie, a cokolwiek rozwiążesz na ziemi, będzie rozwiązane i w niebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 20, 'Wtedy przykazał swoim uczniom, aby nikomu nie mówili, że on, Jezus, jest Chrystusem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 21, 'I odtąd zaczął Jezus tłumaczyć swoim uczniom, że musi iść do Jerozolimy i wiele cierpieć od starszych, od naczelnych kapłanów i uczonych w Piśmie, i być zabity, a trzeciego dnia zmartwychwstać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 22, 'A Piotr, wziąwszy go na bok, zaczął go strofować, mówiąc: Zmiłuj się nad sobą, Panie! Nie przyjdzie to na ciebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 23, 'Lecz on odwrócił się i powiedział do Piotra: Odejdź ode mnie, szatanie! Jesteś dla mnie zgorszeniem, bo nie pojmujesz tego, co Boże, ale to, co ludzkie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 24, 'Wtedy Jezus powiedział do swoich uczniów: Jeśli ktoś chce pójść za mną, niech się wyprze samego siebie, weźmie swój krzyż i idzie za mną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 25, 'Bo kto chce zachować swoje życie, straci je, a kto straci swoje życie z mojego powodu, znajdzie je.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 26, 'Cóż pomoże człowiekowi, choćby cały świat pozyskał, a na swojej duszy poniósł szkodę? Albo co da człowiek w zamian za swoją duszę?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 27, 'Syn Człowieczy przyjdzie bowiem w chwale swego Ojca ze swoimi aniołami i wtedy odda każdemu według jego uczynków.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 28, 'Zaprawdę powiadam wam: Są wśród stojących tutaj tacy, którzy nie zakosztują śmierci, aż ujrzą Syna Człowieczego przychodzącego w swoim królestwie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 1, 'A po sześciu dniach wziął Jezus Piotra, Jakuba i Jana, jego brata, i wprowadził ich na wysoką górę, żeby byli na osobności.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 2, 'I został przemieniony przed nimi: jego oblicze zajaśniało jak słońce, a jego szaty stały się białe jak światło.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 3, 'A oto ukazali się im Mojżesz i Eliasz, którzy z nim rozmawiali.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 4, 'Wtedy Piotr powiedział do Jezusa: Panie, dobrze nam tu być. Jeśli chcesz, postawimy tu trzy namioty: jeden dla ciebie, jeden dla Mojżesza i jeden dla Eliasza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 5, 'Kiedy on jeszcze mówił, oto jasny obłok zacienił ich, a z obłoku rozległ się głos: To jest mój umiłowany Syn, w którym mam upodobanie, jego słuchajcie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 6, 'Uczniowie, słysząc to, upadli na twarz i bardzo się bali.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 7, 'Wtedy Jezus podszedł, dotknął ich i powiedział: Wstańcie, nie bójcie się.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 8, 'Oni zaś, podniósłszy oczy, nikogo nie widzieli, tylko samego Jezusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 9, 'A gdy schodzili z góry, Jezus im przykazał: Nikomu nie mówcie o tym widzeniu, aż Syn Człowieczy zmartwychwstanie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 10, 'I pytali go jego uczniowie: Dlaczego więc uczeni w Piśmie mówią, że najpierw ma przyjść Eliasz?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 11, 'A Jezus im odpowiedział: Istotnie, najpierw przyjdzie Eliasz i wszystko odnowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 12, 'Lecz mówię wam, że Eliasz już przyszedł, jednak nie poznali go, ale zrobili z nim, co chcieli. Tak i Syn Człowieczy dozna od nich cierpień.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 13, 'Wtedy uczniowie zrozumieli, że mówił im o Janie Chrzcicielu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 14, 'A gdy przyszli do tłumu, podszedł do niego pewien człowiek, upadł przed nim na kolana;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 15, 'I powiedział: Panie, zmiłuj się nad moim synem, bo jest obłąkanym i bardzo cierpi. Często bowiem wpada w ogień i często w wodę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 16, 'Przyprowadziłem go do twoich uczniów, ale nie mogli go uzdrowić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 17, 'A Jezus odpowiedział: O pokolenie bez wiary i przewrotne! Jak długo będę z wami? Jak długo mam was znosić? Przyprowadźcie mi go tutaj.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 18, 'I zgromił Jezus tego demona, i wyszedł z niego. Od tej chwili chłopiec był zdrowy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 19, 'Wtedy uczniowie, podszedłszy do Jezusa, zapytali go na osobności: Czemu my nie mogliśmy go wypędzić?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 20, 'A Jezus im odpowiedział: Z powodu waszej niewiary. Zaprawdę bowiem powiadam wam: Jeśli będziecie mieć wiarę jak ziarno gorczycy, powiecie tej górze: Przenieś się stąd na tamto miejsce, a przeniesie się. I nic nie będzie dla was niemożliwe.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 21, 'Lecz ten rodzaj nie wychodzi inaczej, jak tylko przez modlitwę i post.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 22, 'A gdy przebywali w Galilei, Jezus powiedział do nich: Syn Człowieczy zostanie wydany w ręce ludzi;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 23, 'I zabiją go, ale trzeciego dnia zmartwychwstanie. I bardzo się zasmucili.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 24, 'A gdy przyszli do Kafarnaum, podeszli do Piotra poborcy podatku i zapytali: Czy wasz nauczyciel nie płaci podatku?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 25, 'On odpowiedział: Płaci. A gdy wchodził do domu, uprzedził go Jezus, mówiąc: Jak ci się wydaje, Szymonie? Od kogo królowie ziemscy pobierają cło albo podatek? Od swoich synów czy od obcych?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 26, 'Piotr mu odpowiedział: Od obcych. I powiedział mu Jezus: A więc synowie są wolni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 27, 'Ale żebyśmy ich nie zgorszyli, idź nad morze, zarzuć wędkę, weź pierwszą złowioną rybę i otwórz jej pyszczek, a znajdziesz statera. Weź go i daj im za mnie i za siebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 1, 'W tym czasie podeszli do Jezusa uczniowie, pytając: Kto jest największy w królestwie niebieskim?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 2, 'A Jezus, zawoławszy dziecko, postawił je pośród nich;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 3, 'I powiedział: Zaprawdę powiadam wam: Jeśli się nie nawrócicie i nie staniecie się jak dzieci, nie wejdziecie do królestwa niebieskiego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 4, 'Kto się więc uniży jak to dziecko, ten jest największy w królestwie niebieskim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 5, 'A kto przyjmie jedno takie dziecko w moje imię, mnie przyjmuje.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 6, 'Kto zaś zgorszy jednego z tych małych, którzy we mnie wierzą, lepiej byłoby dla niego, gdyby zawieszono mu u szyi kamień młyński i utopiono go w morskiej głębinie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 7, 'Biada światu z powodu zgorszeń! Muszą bowiem przyjść zgorszenia, ale biada temu człowiekowi, przez którego przychodzi zgorszenie!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 8, 'Dlatego jeśli twoja ręka albo noga jest ci powodem upadku, odetnij ją i odrzuć od siebie. Lepiej jest dla ciebie wejść do życia chromym albo ułomnym, niż mając dwie ręce albo dwie nogi, być wrzuconym do ognia wiecznego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 9, 'A jeśli twoje oko jest ci powodem upadku, wyłup je i odrzuć od siebie. Lepiej jest dla ciebie jednookim wejść do życia, niż mając dwoje oczu, być wrzuconym do ognia piekielnego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 10, 'Uważajcie, abyście nie gardzili żadnym z tych małych. Mówię wam bowiem, że ich aniołowie w niebie zawsze patrzą na oblicze mojego Ojca, który jest w niebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 11, 'Przyszedł bowiem Syn Człowieczy, aby zbawić to, co zginęło.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 12, 'Jak wam się wydaje? Gdyby jakiś człowiek miał sto owiec, a jedna z nich zabłąkałaby się, czyż nie zostawi tych dziewięćdziesięciu dziewięciu i nie pójdzie w góry szukać zabłąkanej?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 13, 'A jeśli uda mu się ją znaleźć, zaprawdę powiadam wam, że cieszy się z niej bardziej niż z tych dziewięćdziesięciu dziewięciu, które się nie zabłąkały.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 14, 'Tak też nie jest wolą waszego Ojca, który jest w niebie, aby zginął jeden z tych małych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 15, 'Jeśli twój brat zgrzeszy przeciwko tobie, idź, strofuj go sam na sam. Jeśli cię usłucha, pozyskałeś twego brata.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 16, 'Jeśli zaś cię nie usłucha, weź ze sobą jeszcze jednego albo dwóch, aby na podstawie zeznania dwóch albo trzech świadków oparte było każde słowo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 17, 'Jeśli ich nie usłucha, powiedz kościołowi. A jeśli kościoła nie usłucha, niech będzie dla ciebie jak poganin i celnik.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 18, 'Zaprawdę powiadam wam: Cokolwiek zwiążecie na ziemi, będzie związane i w niebie. A cokolwiek rozwiążecie na ziemi, będzie rozwiązane i w niebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 19, 'Mówię wam też: Jeśli dwaj z was na ziemi będą zgodnie prosić o cokolwiek, otrzymają to od mego Ojca, który jest w niebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 20, 'Gdzie bowiem dwaj albo trzej są zgromadzeni w moje imię, tam jestem pośród nich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 21, 'Wtedy Piotr podszedł do niego i zapytał: Panie, ile razy mam przebaczyć mojemu bratu, gdy zgrzeszy przeciwko mnie? Czy aż siedem razy?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 22, 'I odpowiedział mu Jezus: Nie mówię ci, że aż siedem razy, ale aż siedemdziesiąt siedem razy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 23, 'Dlatego królestwo niebieskie podobne jest do króla, który chciał się rozliczyć ze swymi sługami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 24, 'A gdy zaczął się rozliczać, przyprowadzono mu jednego, który był mu winien dziesięć tysięcy talentów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 25, 'A ponieważ nie miał z czego oddać, jego pan kazał go sprzedać wraz z żoną, dziećmi i wszystkim, co miał, i spłacić dług.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 26, 'Wtedy sługa upadł i oddał mu pokłon, mówiąc: Panie, okaż mi cierpliwość, a wszystko ci oddam.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 27, 'Pan tego sługi, ulitowawszy się nad nim, uwolnił go i darował mu dług.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 28, 'Lecz gdy ten sługa wyszedł, spotkał jednego ze swoich współsług, który był mu winien sto groszy. Chwycił go i zaczął dusić, mówiąc: Oddaj, coś winien!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 29, 'Wtedy jego współsługa upadł mu do nóg i prosił go: Okaż mi cierpliwość, a wszystko ci oddam.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 30, 'On jednak nie chciał, ale poszedł i wtrącił go do więzienia, dopóki nie odda długu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 31, 'A jego współsłudzy, widząc, co się stało, zasmucili się bardzo i poszedłszy, oznajmili swemu panu wszystko, co zaszło.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 32, 'Wtedy jego pan wezwał go i powiedział: Zły sługo, darowałem ci cały ten dług, ponieważ mnie prosiłeś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 33, 'Czyż i ty nie powinieneś był zmiłować się nad swoim współsługą, jak ja zmiłowałem się nad tobą?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 34, 'I jego pan, rozgniewany, wydał go katom, dopóki nie odda wszystkiego, co był mu winien.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 35, 'Tak i wam uczyni mój Ojciec niebieski, jeśli każdy z was nie przebaczy z serca swemu bratu jego przewinień.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 1, 'A gdy Jezus dokończył tych mów, odszedł z Galilei i przybył na pogranicze Judei za Jordan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 2, 'I poszły za nim wielkie tłumy, a on ich tam uzdrowił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 3, 'Wtedy przyszli do niego faryzeusze, wystawiając go na próbę i pytając: Czy wolno człowiekowi oddalić swoją żonę z jakiegokolwiek powodu?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 4, 'A on im odpowiedział: Nie czytaliście, że ten, który stworzył ich na początku, uczynił ich mężczyzną i kobietą?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 5, 'I powiedział: Dlatego opuści mężczyzna ojca i matkę i połączy się ze swoją żoną, i będą dwoje jednym ciałem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 6, 'A tak już nie są dwoje, ale jedno ciało. Co więc Bóg złączył, człowiek niech nie rozłącza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 7, 'Zapytali go: Dlaczego więc Mojżesz nakazał dać list rozwodowy i oddalić ją?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 8, 'Odpowiedział im: Z powodu zatwardziałości waszego serca Mojżesz pozwolił wam oddalić wasze żony, ale od początku tak nie było.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 9, 'Lecz ja wam mówię: Kto oddala swoją żonę – z wyjątkiem przypadku nierządu – i żeni się z inną, cudzołoży, a kto żeni się z oddaloną, cudzołoży.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 10, 'Powiedzieli mu jego uczniowie: Jeśli tak ma się sprawa mężczyzny z jego żoną, to lepiej się nie żenić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 11, 'A on im powiedział: Nie wszyscy to pojmują, ale tylko ci, którym to jest dane.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 12, 'Są bowiem eunuchowie, którzy tacy wyszli z łona matki; są też eunuchowie, których ludzie takimi uczynili; są również eunuchowie, którzy się sami takimi uczynili dla królestwa niebieskiego. Kto może pojąć, niech pojmuje.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 13, 'Wtedy przyniesiono mu dzieci, aby położył na nie ręce i pomodlił się, ale uczniowie ich gromili.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 14, 'Lecz Jezus powiedział: Zostawcie dzieci i nie zabraniajcie im przychodzić do mnie, bo do takich należy królestwo niebieskie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 15, 'Położył na nie ręce i odszedł stamtąd.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 16, 'A oto pewien człowiek podszedł i zapytał go: Nauczycielu dobry, co dobrego mam czynić, aby mieć życie wieczne?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 17, 'Lecz on mu odpowiedział: Dlaczego nazywasz mnie dobrym? Nikt nie jest dobry, tylko jeden – Bóg. A jeśli chcesz wejść do życia, przestrzegaj przykazań.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 18, 'I zapytał go: Których? Jezus odpowiedział: Nie będziesz zabijał, nie będziesz cudzołożył, nie będziesz kradł, nie będziesz mówił fałszywego świadectwa;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 19, 'Czcij swego ojca i matkę oraz będziesz miłował swego bliźniego jak samego siebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 20, 'Powiedział mu młodzieniec: Tego wszystkiego przestrzegałem od mojej młodości. Czego mi jeszcze brakuje?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 21, 'Jezus mu odpowiedział: Jeśli chcesz być doskonały, idź, sprzedaj, co posiadasz, i rozdaj ubogim, a będziesz miał skarb w niebie. Potem przyjdź i chodź za mną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 22, 'Kiedy młodzieniec usłyszał te słowa, odszedł smutny, miał bowiem wiele dóbr.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 23, 'Wtedy Jezus powiedział swoim uczniom: Zaprawdę powiadam wam, że bogaty z trudnością wejdzie do królestwa niebieskiego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 24, 'Mówię wam też: Łatwiej jest wielbłądowi przejść przez ucho igielne, niż bogatemu wejść do królestwa Bożego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 25, 'Gdy jego uczniowie to usłyszeli, zdumieli się bardzo i pytali: Któż więc może być zbawiony?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 26, 'A Jezus, spojrzawszy na nich, powiedział im: U ludzi to niemożliwe, lecz u Boga wszystko jest możliwe.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 27, 'Wtedy Piotr odezwał się do niego: Oto my opuściliśmy wszystko i poszliśmy za tobą. Cóż za to będziemy mieli?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 28, 'A Jezus im powiedział: Zaprawdę powiadam wam, że przy odrodzeniu, gdy Syn Człowieczy zasiądzie na tronie swojej chwały, i wy, którzy poszliście za mną, zasiądziecie na dwunastu tronach, sądząc dwanaście pokoleń Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 29, 'I każdy, kto opuści domy, braci lub siostry, ojca lub matkę, żonę, dzieci lub pole dla mego imienia, stokroć więcej otrzyma i odziedziczy życie wieczne.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 30, 'A wielu pierwszych będzie ostatnimi, a ostatnich pierwszymi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 1, 'Królestwo niebieskie bowiem podobne jest do gospodarza, który wyszedł wczesnym rankiem, aby nająć robotników do swojej winnicy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 2, 'I umówił się z robotnikami na grosz za dzień i posłał ich do winnicy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 3, 'A wyszedłszy około godziny trzeciej, zobaczył innych, którzy stali bezczynnie na rynku;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 4, 'I powiedział do nich: Idźcie i wy do winnicy, a co będzie słuszne, dam wam. I poszli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 5, 'Około godziny szóstej i dziewiątej wyszedł znowu i zrobił tak samo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 6, 'Potem wyszedł około godziny jedenastej i znalazł innych, którzy stali bez zajęcia, i zapytał ich: Dlaczego tu bezczynnie stoicie cały dzień?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 7, 'Odpowiedzieli mu: Bo nikt nas nie najął. I powiedział im: Idźcie i wy do winnicy, a co będzie słuszne, otrzymacie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 8, 'A gdy nastał wieczór, pan winnicy powiedział do swego zarządcy: Zwołaj robotników i wypłać im należność, zaczynając od ostatnich aż do pierwszych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 9, 'Kiedy przyszli ci, którzy byli najęci około godziny jedenastej, każdy z nich otrzymał po groszu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 10, 'Gdy przyszli pierwsi, sądzili, że dostaną więcej, ale również każdy z nich otrzymał po groszu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 11, 'A otrzymawszy, szemrali przeciwko gospodarzowi;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 12, 'Mówiąc: Ci ostatni jedną godzinę pracowali, a zrównałeś ich z nami, którzy znosiliśmy ciężar dnia i upał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 13, 'A on odpowiedział jednemu z nich: Przyjacielu, nie robię ci krzywdy. Czyż nie umówiłeś się ze mną na grosz?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 14, 'Weź, co jest twoje, i odejdź. Chcę bowiem temu ostatniemu dać tyle, co tobie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 15, 'Czyż z tym, co moje, nie wolno mi robić, co chcę? Czy twoje oko jest złe dlatego, że ja jestem dobry?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 16, 'Tak to ostatni będą pierwszymi, a pierwsi ostatnimi. Wielu bowiem jest wezwanych, ale mało wybranych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 17, 'A gdy Jezus szedł do Jerozolimy, w drodze wziął ze sobą na ubocze dwunastu uczniów i powiedział do nich:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 18, 'Oto idziemy do Jerozolimy, a Syn Człowieczy zostanie wydany naczelnym kapłanom i uczonym w Piśmie, a oni skażą go na śmierć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 19, 'I wydadzą go poganom na pośmiewisko, ubiczowanie i ukrzyżowanie, ale trzeciego dnia zmartwychwstanie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 20, 'Wtedy podeszła do niego matka synów Zebedeusza ze swoimi synami, oddając mu pokłon i prosząc go o coś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 21, 'A on ją zapytał: Czego chcesz? Odpowiedziała mu: Powiedz, aby ci dwaj moi synowie siedzieli jeden po twojej prawej, a drugi po lewej stronie w twoim królestwie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 22, 'Ale Jezus odpowiedział: Nie wiecie, o co prosicie. Czy możecie pić kielich, który ja będę pił, i być ochrzczeni chrztem, którym ja się chrzczę? Odpowiedzieli mu: Możemy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 23, 'Wtedy im powiedział: Mój kielich będziecie pić i chrztem, którym ja się chrzczę, będziecie ochrzczeni, ale nie do mnie należy danie miejsca po mojej prawej i lewej stronie, lecz będzie dane tym, którym zostało przygotowane przez mojego Ojca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 24, 'A gdy owych dziesięciu to usłyszało, oburzyli się na tych dwóch braci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 25, 'Ale Jezus przywołał ich do siebie i powiedział: Wiecie, że władcy narodów panują nad nimi, a ci, którzy są wielcy, sprawują swą władzę nad nimi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 26, 'Lecz nie tak ma być wśród was, ale kto między wami chce być wielki, niech będzie waszym sługą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 27, 'I kto wśród was chce być pierwszy, niech będzie waszym sługą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 28, 'Tak jak Syn Człowieczy nie przyszedł, aby mu służono, ale aby służyć i oddać swoje życie na okup za wielu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 29, 'A gdy wychodzili z Jerycha, szedł za nim wielki tłum.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 30, 'A oto dwaj ślepi, siedzący przy drodze, usłyszawszy, że Jezus przechodzi, zawołali: Zmiłuj się nad nami, Panie, Synu Dawida!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 31, 'Tłum surowo nakazywał im milczeć, lecz oni tym bardziej wołali: Zmiłuj się nad nami, Panie, Synu Dawida!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 32, 'Wtedy Jezus zatrzymał się, zawołał ich i zapytał: Co chcecie, abym dla was zrobił?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 33, 'Odpowiedzieli mu: Panie, aby się otworzyły nasze oczy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 34, 'Wtedy Jezus ulitował się nad nimi, dotknął ich oczu, a natychmiast odzyskali wzrok i poszli za nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 1, 'A gdy się przybliżyli do Jerozolimy i przyszli do Betfage na Górę Oliwną, wtedy Jezus posłał dwóch uczniów;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 2, 'Mówiąc im: Idźcie do wsi, która jest przed wami, a zaraz znajdziecie uwiązaną oślicę i oślątko z nią. Odwiążcie je i przyprowadźcie do mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 3, 'A gdyby wam ktoś coś mówił, powiedzcie: Pan ich potrzebuje, a zaraz je puści.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 4, 'To wszystko się stało, aby się wypełniło, co zostało powiedziane przez proroka:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 5, 'Powiedzcie córce Syjonu: Oto twój król przychodzi do ciebie cichy, siedzący na ośle, na oślątku, źrebięciu oślicy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 6, 'Poszli więc uczniowie i uczynili tak, jak im nakazał Jezus.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 7, 'Przyprowadzili oślicę i oślątko, położyli na nie swoje szaty i posadzili go na nich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 8, 'A wielki tłum słał swoje szaty na drodze, inni zaś obcinali gałązki z drzew i kładli na drodze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 9, 'A tłumy, które szły przed nim i za nim, wołały: Hosanna Synowi Dawida! Błogosławiony, który przychodzi w imieniu Pana! Hosanna na wysokościach!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 10, 'Kiedy wjechał do Jerozolimy, poruszyło się całe miasto i pytano: Któż to jest?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 11, 'A tłumy odpowiadały: To jest Jezus, prorok z Nazaretu w Galilei.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 12, 'Wtedy Jezus wszedł do świątyni Boga i wypędził wszystkich sprzedających i kupujących w świątyni; poprzewracał stoły wymieniających pieniądze i stołki sprzedających gołębie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 13, 'I powiedział im: Jest napisane: Mój dom będzie nazwany domem modlitwy, a wy zrobiliście z niego jaskinię zbójców.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 14, 'Wtedy ślepi i chromi podeszli do niego w świątyni, a on ich uzdrowił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 15, 'A gdy naczelni kapłani i uczeni w Piśmie zobaczyli cuda, które czynił, i dzieci wołające w świątyni: Hosanna Synowi Dawida, rozgniewali się.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 16, 'I zapytali go: Słyszysz, co one mówią? A Jezus im odpowiedział: Tak. Czy nigdy nie czytaliście: Przez usta niemowląt i ssących przygotowałeś sobie chwałę?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 17, 'A opuściwszy ich, wyszedł z miasta do Betanii i tam przenocował.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 18, 'A wracając rano do miasta, poczuł głód.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 19, 'I widząc przy drodze drzewo figowe, podszedł do niego, ale nie znalazł na nim nic oprócz samych liści. I powiedział do niego: Niech się już nigdy nie rodzi z ciebie owoc. I drzewo figowe natychmiast uschło.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 20, 'A gdy uczniowie to zobaczyli, dziwili się, mówiąc: Jak szybko uschło to drzewo figowe!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 21, 'Wtedy Jezus im odpowiedział: Zaprawdę powiadam wam: Jeśli będziecie mieć wiarę i nie zwątpicie, nie tylko to, co się stało z drzewem figowym, uczynicie, ale jeśli i tej górze powiecie: Podnieś się i rzuć się do morza, stanie się tak.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 22, 'I wszystko, o cokolwiek poprosicie w modlitwie, wierząc, otrzymacie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 23, 'A gdy przyszedł do świątyni i nauczał, podeszli do niego naczelni kapłani i starsi ludu, pytając: Jakim prawem to czynisz? I kto dał ci tę władzę?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 24, 'A Jezus im odpowiedział: I ja was spytam o pewną rzecz. Jeśli mi odpowiecie, i ja wam powiem, jakim prawem to czynię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 25, 'Skąd pochodził chrzest Jana? Z nieba czy od ludzi? A oni zastanawiali się między sobą i mówili: Jeśli powiemy, że z nieba, zapyta nas: Czemu więc mu nie uwierzyliście?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 26, 'Jeśli zaś powiemy, że od ludzi – boimy się tłumu, bo wszyscy uważają Jana za proroka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 27, 'Odpowiedzieli więc Jezusowi: Nie wiemy. On również im odpowiedział: I ja wam nie powiem, jakim prawem to czynię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 28, 'Jak wam się wydaje? Pewien człowiek miał dwóch synów. Podszedł do pierwszego i powiedział: Synu, idź, pracuj dziś w mojej winnicy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 29, 'Ale on odpowiedział: Nie chcę. Lecz potem odczuł żal i poszedł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 30, 'Podszedł do drugiego i powiedział to samo. On zaś odpowiedział: Idę, panie. Ale nie poszedł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 31, 'Który z tych dwóch wypełnił wolę ojca? Odpowiedzieli mu: Ten pierwszy. Jezus im powiedział: Zaprawdę powiadam wam, że celnicy i nierządnice wchodzą przed wami do królestwa Bożego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 32, 'Przyszedł bowiem do was Jan drogą sprawiedliwości, a nie uwierzyliście mu, ale celnicy i nierządnice mu uwierzyli. A wy, chociaż to widzieliście, nie odczuliście żalu, aby mu uwierzyć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 33, 'Posłuchajcie innej przypowieści: Był pewien gospodarz, który założył winnicę. Ogrodził ją płotem, wykopał w niej prasę, zbudował wieżę i wydzierżawił ją rolnikom, i wyjechał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 34, 'A gdy nadszedł czas zbiorów, posłał swoje sługi do rolników, aby odebrali plony tej winnicy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 35, 'Lecz rolnicy schwytali jego sługi, jednego pobili, innego zabili, a jeszcze innego ukamienowali.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 36, 'Wtedy posłał inne sługi, więcej niż za pierwszym razem, ale postąpili z nimi tak samo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 37, 'W końcu posłał do nich swego syna, mówiąc: Uszanują mego syna.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 38, 'Lecz rolnicy, gdy zobaczyli syna, mówili między sobą: To jest dziedzic. Chodźmy, zabijmy go, a posiądziemy jego dziedzictwo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 39, 'I schwytali go, wyrzucili z winnicy i zabili.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 40, 'Gdy więc przyjdzie pan winnicy, co zrobi z tymi rolnikami?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 41, 'Odpowiedzieli mu: Złych srogo wytraci, a winnicę wydzierżawi innym rolnikom, którzy będą mu oddawać plony we właściwym czasie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 42, 'Powiedział im Jezus: Czy nigdy nie czytaliście w Pismach: Kamień, który odrzucili budujący, stał się kamieniem węgielnym; Pan to sprawił i jest to cudowne w naszych oczach?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 43, 'Dlatego mówię wam: Królestwo Boże zostanie wam zabrane, a dane narodowi, który wyda jego owoce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 44, 'A kto upadnie na ten kamień, rozbije się, na kogo zaś on upadnie, zmiażdży go.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 45, 'Kiedy naczelni kapłani i faryzeusze usłyszeli jego przypowieści, domyślili się, że o nich mówił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 46, 'I chcieli go schwytać, ale bali się tłumów, ponieważ uważały go za proroka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 1, 'A Jezus, odpowiadając, znowu mówił do nich w przypowieściach tymi słowy:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 2, 'Królestwo niebieskie podobne jest do króla, który wyprawił wesele swemu synowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 3, 'I posłał swe sługi, aby wezwali zaproszonych na wesele, ale oni nie chcieli przyjść.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 4, 'Ponownie posłał inne sługi, mówiąc: Powiedzcie zaproszonym: Oto przygotowałem moją ucztę, zabito moje woły i tuczne zwierzęta i wszystko jest gotowe. Chodźcie na wesele.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 5, 'Lecz oni zlekceważyli to i odeszli, jeden na swoje pole, a inny do swego kupiectwa;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 6, 'A inni schwytali jego sługi, znieważyli ich i zabili.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 7, 'Gdy król to usłyszał, rozgniewał się, a posławszy swoje wojska, wytracił tych morderców i spalił ich miasto.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 8, 'Potem powiedział swoim sługom: Wesele wprawdzie jest gotowe, lecz zaproszeni nie byli godni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 9, 'Idźcie więc na rozstaje dróg i zaproście na wesele wszystkich, których spotkacie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 10, 'Wtedy słudzy ci wyszli na drogi i zgromadzili wszystkich, których spotkali, złych i dobrych. I sala weselna napełniła się gośćmi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 11, 'A gdy król wszedł, aby zobaczyć gości, ujrzał tam człowieka, który nie był ubrany w strój weselny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 12, 'I zapytał go: Przyjacielu, jak tu wszedłeś, nie mając stroju weselnego? A on zaniemówił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 13, 'Wtedy król powiedział sługom: Zwiążcie mu nogi i ręce, weźcie go i wrzućcie do ciemności zewnętrznych. Tam będzie płacz i zgrzytanie zębów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 14, 'Wielu jest bowiem wezwanych, lecz mało wybranych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 15, 'Wtedy faryzeusze odeszli i naradzali się, jak by go usidlić w mowie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 16, 'I posłali do niego swoich uczniów wraz z herodianami, którzy powiedzieli: Nauczycielu, wiemy, że jesteś prawdziwy i drogi Bożej w prawdzie nauczasz, i nie zważasz na nikogo. Nie oglądasz się bowiem na osobę ludzką.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 17, 'Powiedz nam więc, jak ci się wydaje: Czy wolno płacić podatek cesarzowi, czy nie?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 18, 'Ale Jezus poznał ich niegodziwość i powiedział: Czemu wystawiacie mnie na próbę, obłudnicy?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 19, 'Pokażcie mi monetę podatkową. I podali mu grosz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 20, 'A on ich zapytał: Czyj to wizerunek i napis?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 21, 'Odpowiedzieli mu: Cesarza. Wtedy powiedział im: Oddajcie więc cesarzowi to, co należy do cesarza, a Bogu to, co należy do Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 22, 'A gdy to usłyszeli, zdziwili się, zostawili go i odeszli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 23, 'Tego dnia przyszli do niego saduceusze, którzy mówią, że nie ma zmartwychwstania, i pytali go:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 24, 'Nauczycielu, Mojżesz powiedział: Jeśli ktoś umrze, nie mając dzieci, to jego brat ma ożenić się z jego żoną i wzbudzić potomstwo swemu bratu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 25, 'Było więc u nas siedmiu braci. Pierwszy ożenił się i umarł, a nie mając potomstwa, zostawił żonę swemu bratu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 26, 'Podobnie drugi i trzeci, aż do siódmego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 27, 'A w końcu po wszystkich umarła też ta kobieta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 28, 'Żoną którego z tych siedmiu będzie więc przy zmartwychwstaniu? Gdyż wszyscy ją mieli za żonę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 29, 'A Jezus im odpowiedział: Błądzicie, nie znając Pisma ani mocy Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 30, 'Przy zmartwychwstaniu bowiem ani nie będą się żenić, ani za mąż wychodzić, ale będą jak aniołowie Boga w niebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 31, 'A co do zmartwychwstania umarłych, czy nie czytaliście, co wam zostało powiedziane przez Boga:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 32, 'Ja jestem Bogiem Abrahama, Bogiem Izaaka i Bogiem Jakuba? Bóg nie jest Bogiem umarłych, ale żywych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 33, 'A tłumy, słysząc to, zdumiewały się jego nauką.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 34, 'Lecz gdy faryzeusze usłyszeli, że zamknął usta saduceuszom, zeszli się razem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 35, 'I jeden z nich, znawca prawa, wystawiając go na próbę, spytał:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 36, 'Nauczycielu, które przykazanie w prawie jest największe?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 37, 'A Jezus mu odpowiedział: Będziesz miłował Pana, swego Boga, całym swym sercem, całą swą duszą i całym swym umysłem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 38, 'To jest pierwsze i największe przykazanie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 39, 'A drugie jest do niego podobne: Będziesz miłował swego bliźniego jak samego siebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 40, 'Na tych dwóch przykazaniach opiera się całe Prawo i Prorocy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 41, 'A gdy faryzeusze byli zebrani, Jezus ich zapytał:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 42, 'Co sądzicie o Chrystusie? Czyim jest synem? Odpowiedzieli mu: Dawida.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 43, 'I powiedział im: Jakże więc Dawid w Duchu nazywa go Panem, mówiąc:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 44, 'Powiedział Pan memu Panu: Siądź po mojej prawicy, aż położę twoich nieprzyjaciół jako podnóżek pod twoje stopy?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 45, 'Jeśli więc Dawid nazywa go Panem, to jakże może być jego synem?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 46, 'I nikt nie mógł mu odpowiedzieć ani słowa. Od tego też dnia nikt nie śmiał go więcej pytać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 1, 'Wtedy Jezus powiedział do tłumów i do swoich uczniów:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 2, 'Na katedrze Mojżesza zasiedli uczeni w Piśmie i faryzeusze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 3, 'Czyńcie więc i przestrzegajcie wszystkiego, co nakazują wam przestrzegać, ale według ich uczynków nie postępujcie. Mówią bowiem, ale nie czynią.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 4, 'Bo wiążą brzemiona ciężkie i nie do uniesienia i kładą je na barki ludzi, lecz sami nie chcą ich ruszyć nawet palcem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 5, 'A wszystkie swoje uczynki spełniają, aby ludzie ich widzieli. Poszerzają swoje filakterie i wydłużają frędzle swoich płaszczy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 6, 'Kochają też pierwsze miejsca na ucztach i pierwsze krzesła w synagogach;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 7, 'I pozdrowienia na rynkach, i aby ludzie nazywali ich: Rabbi, Rabbi!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 8, 'Ale wy nie nazywajcie się Rabbi. Jeden bowiem jest wasz Mistrz, Chrystus, a wy wszyscy jesteście braćmi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 9, 'I nikogo na ziemi nie nazywajcie waszym ojcem. Jeden bowiem jest wasz Ojciec, który jest w niebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 10, 'Niech też was nie nazywają mistrzami, gdyż jeden jest wasz Mistrz, Chrystus.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 11, 'Ale kto z was jest największy, będzie waszym sługą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 12, 'Kto się wywyższa, będzie poniżony, a kto się poniża, będzie wywyższony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 13, 'Lecz biada wam, uczeni w Piśmie i faryzeusze, obłudnicy, bo zamykacie królestwo niebieskie przed ludźmi. Sami bowiem tam nie wchodzicie ani wchodzącym nie pozwalacie wejść.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 14, 'Biada wam, uczeni w Piśmie i faryzeusze, obłudnicy, bo pożeracie domy wdów i dla pozoru odprawiacie długie modlitwy. Dlatego otrzymacie surowszy wyrok.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 15, 'Biada wam, uczeni w Piśmie i faryzeusze, obłudnicy, bo obchodzicie morza i lądy, aby pozyskać jednego współwyznawcę, a gdy się nim stanie, czynicie go synem piekła dwa razy takim jak wy sami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 16, 'Biada wam, ślepi przewodnicy, którzy mówicie: Kto przysięga na świątynię, to nic nie znaczy, ale kto przysięga na złoto świątyni, jest związany przysięgą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 17, 'Głupi i ślepi! Cóż bowiem jest ważniejsze: złoto czy świątynia, która uświęca złoto?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 18, 'A kto przysięga na ołtarz, to nic nie znaczy, lecz kto przysięga na ofiarę, która jest na nim, jest związany przysięgą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 19, 'Głupi i ślepi! Cóż bowiem jest ważniejsze: ofiara czy ołtarz, który uświęca ofiarę?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 20, 'Kto więc przysięga na ołtarz, przysięga na niego i na to wszystko, co na nim leży.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 21, 'A kto przysięga na świątynię, przysięga na nią i na tego, który w niej mieszka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 22, 'I kto przysięga na niebo, przysięga na tron Boga i na tego, który na nim zasiada.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 23, 'Biada wam, uczeni w Piśmie i faryzeusze, obłudnicy, bo dajecie dziesięcinę z mięty, anyżu i kminku, a opuszczacie to, co ważniejsze w prawie: sąd, miłosierdzie i wiarę. To należało czynić i tamtego nie zaniedbywać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 24, 'Ślepi przewodnicy! Przecedzacie komara, a połykacie wielbłąda.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 25, 'Biada wam, uczeni w Piśmie i faryzeusze, obłudnicy, bo oczyszczacie kubek i misę z zewnątrz, a wewnątrz pełne są zdzierstwa i niepowściągliwości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 26, 'Ślepy faryzeuszu, oczyść najpierw wnętrze kubka i misy, aby i to, co jest na zewnątrz, było czyste.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 27, 'Biada wam, uczeni w Piśmie i faryzeusze, obłudnicy, bo jesteście podobni do grobów pobielanych, które z zewnątrz wydają się piękne, ale wewnątrz pełne są kości umarłych i wszelkiej nieczystości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 28, 'Tak i wy na zewnątrz wydajecie się ludziom sprawiedliwi, ale wewnątrz jesteście pełni obłudy i nieprawości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 29, 'Biada wam, uczeni w Piśmie i faryzeusze, obłudnicy, bo budujecie grobowce proroków i zdobicie nagrobki sprawiedliwych;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 30, 'I mówicie: Gdybyśmy żyli za dni naszych ojców, nie bylibyśmy ich wspólnikami w przelewaniu krwi proroków.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 31, 'A tak sami sobie wystawiacie świadectwo, że jesteście synami tych, którzy pozabijali proroków.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 32, 'I wy dopełnijcie miary waszych ojców!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 33, 'Węże, plemię żmijowe! Jakże będziecie mogli uniknąć potępienia ognia piekielnego?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 34, 'Dlatego ja posyłam do was proroków, mędrców i uczonych w Piśmie. Niektórych z nich zabijecie i ukrzyżujecie, a niektórych ubiczujecie w waszych synagogach i będziecie ich prześladować od miasta do miasta;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 35, 'Aby spadła na was wszelka krew sprawiedliwa przelana na ziemi, od krwi sprawiedliwego Abla aż do krwi Zachariasza, syna Barachiasza, którego zabiliście między świątynią a ołtarzem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 36, 'Zaprawdę powiadam wam: Spadnie to wszystko na to pokolenie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 37, 'Jeruzalem, Jeruzalem, które zabijasz proroków i kamienujesz tych, którzy są do ciebie posłani! Ile razy chciałem zgromadzić twoje dzieci, tak jak kokoszka gromadzi swe kurczęta pod skrzydła, a nie chcieliście!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 38, 'Oto wasz dom zostanie wam pusty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 39, 'Mówię wam bowiem: Odtąd nie ujrzycie mnie, aż powiecie: Błogosławiony, który przychodzi w imieniu Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 1, 'A Jezus wyszedł ze świątyni i oddalił się. I podeszli do niego jego uczniowie, aby pokazać mu zabudowania świątynne.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 2, 'Lecz Jezus powiedział do nich: Czyż nie widzicie tego wszystkiego? Zaprawdę powiadam wam, nie zostanie tu kamień na kamieniu, który by nie został zwalony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 3, 'A gdy siedział na Górze Oliwnej, podeszli do niego uczniowie i pytali na osobności: Powiedz nam, kiedy się to stanie i jaki będzie znak twego przyjścia i końca świata?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 4, 'I odpowiedział im Jezus: Uważajcie, aby was ktoś nie zwiódł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 5, 'Wielu bowiem przyjdzie pod moim imieniem, mówiąc: Ja jestem Chrystusem. I wielu zwiodą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 6, 'Usłyszycie też o wojnach i pogłoski o wojnach. Uważajcie, abyście się nie trwożyli. Wszystko to bowiem musi się stać, ale to jeszcze nie koniec.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 7, 'Powstanie bowiem naród przeciwko narodowi i królestwo przeciwko królestwu i będzie głód, zaraza i trzęsienia ziemi miejscami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 8, 'Lecz to wszystko jest początkiem boleści.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 9, 'Wtedy wydadzą was na udrękę, będą was zabijać i będziecie znienawidzeni przez wszystkie narody z powodu mego imienia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 10, 'A wówczas wielu się zgorszy, będą się wzajemnie wydawać i jedni drugich nienawidzić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 11, 'Powstanie też wielu fałszywych proroków i wielu zwiodą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 12, 'A ponieważ wzmoże się nieprawość, miłość wielu oziębnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 13, 'Lecz kto wytrwa aż do końca, ten będzie zbawiony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 14, 'A ta ewangelia królestwa będzie głoszona po całym świecie na świadectwo wszystkim narodom. I wtedy przyjdzie koniec.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 15, 'Gdy więc zobaczycie obrzydliwość spustoszenia, o której mówił prorok Daniel, stojącą w miejscu świętym (kto czyta, niech rozumie);');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 16, 'Wtedy ci, którzy będą w Judei, niech uciekają w góry.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 17, 'Kto będzie na dachu, niech nie schodzi, aby coś zabrać ze swego domu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 18, 'Kto zaś będzie w polu, niech nie wraca, aby wziąć swe szaty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 19, 'A biada brzemiennym i karmiącym w tych dniach!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 20, 'Módlcie się więc, aby wasza ucieczka nie wypadła w zimie albo w szabat.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 21, 'Wtedy bowiem będzie wielki ucisk, jakiego nie było od początku świata aż dotąd ani nigdy nie będzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 22, 'A gdyby te dni nie były skrócone, żadne ciało nie byłoby zbawione. Ale ze względu na wybranych dni te będą skrócone.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 23, 'Jeśli wtedy ktoś wam powie: Oto tu jest Chrystus, albo: Jest tam – nie wierzcie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 24, 'Powstaną bowiem fałszywi Chrystusowie i fałszywi prorocy i będą czynić wielkie znaki i cuda, żeby zwieść, o ile można, nawet wybranych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 25, 'Oto wam przepowiedziałem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 26, 'Jeśli więc wam powiedzą: Oto jest na pustyni – nie wychodźcie; Oto wewnątrz domu – nie wierzcie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 27, 'Jak bowiem błyskawica pojawia się na wschodzie i jest widoczna aż na zachodzie, tak będzie z przyjściem Syna Człowieczego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 28, 'Bo gdzie jest padlina, tam się zgromadzą i orły.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 29, 'A zaraz po ucisku tych dni słońce się zaćmi i księżyc nie da swego blasku, gwiazdy będą spadać z nieba i moce niebieskie zostaną poruszone.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 30, 'Wówczas ukaże się na niebie znak Syna Człowieczego. Wtedy będą lamentować wszystkie ludy ziemi i ujrzą Syna Człowieczego przychodzącego na obłokach niebieskich z mocą i wielką chwałą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 31, 'Pośle on swoich aniołów z potężnym głosem trąby i zgromadzą jego wybranych z czterech stron świata, od jednego krańca nieba aż do drugiego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 32, 'A od drzewa figowego uczcie się przez podobieństwo: Gdy jego gałąź już staje się miękka i wypuszcza liście, poznajecie, że lato jest blisko.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 33, 'Tak i wy, gdy ujrzycie to wszystko, wiedzcie, że jest blisko, u drzwi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 34, 'Zaprawdę powiadam wam: Nie przeminie to pokolenie, aż się to wszystko stanie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 35, 'Niebo i ziemia przeminą, ale moje słowa nie przeminą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 36, 'Lecz o tym dniu i godzinie nikt nie wie, nawet aniołowie niebiescy, tylko sam mój Ojciec.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 37, 'A jak było za dni Noego, tak będzie z przyjściem Syna Człowieczego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 38, 'Jak bowiem za tych dni przed potopem jedli i pili, żenili się i za mąż wydawali aż do tego dnia, w którym Noe wszedł do arki;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 39, 'I nie spostrzegli się, aż przyszedł potop i zabrał wszystkich – tak będzie i z przyjściem Syna Człowieczego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 40, 'Wtedy dwóch będzie w polu, jeden będzie wzięty, a drugi zostawiony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 41, 'Dwie będą mleć na żarnach, jedna będzie wzięta, a druga zostawiona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 42, 'Czuwajcie więc, ponieważ nie wiecie, o której godzinie wasz Pan przyjdzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 43, 'A to wiedzcie, że gdyby gospodarz wiedział, o jakiej porze ma przyjść złodziej, czuwałby i nie pozwoliłby włamać się do swego domu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 44, 'Dlatego i wy bądźcie gotowi, bo Syn Człowieczy przyjdzie o godzinie, której się nie spodziewacie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 45, 'Któż więc jest sługą wiernym i roztropnym, którego pan ustanowił nad swoją służbą, aby im dawał pokarm o właściwej porze?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 46, 'Błogosławiony ten sługa, którego pan, gdy przyjdzie, zastanie tak czyniącego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 47, 'Zaprawdę powiadam wam, że ustanowi go nad wszystkimi swymi dobrami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 48, 'Lecz jeśli powie ten zły sługa w swoim sercu: Mój pan zwleka z przyjściem;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 49, 'I zacznie bić współsługi, jeść i pić z pijakami;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 50, 'Przyjdzie pan tego sługi w dniu, w którym się nie spodziewa, i o godzinie, której nie zna.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 51, 'Wtedy odłączy go i wyznaczy mu dział z obłudnikami. Tam będzie płacz i zgrzytanie zębów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 1, 'Wtedy królestwo niebieskie będzie podobne do dziesięciu dziewic, które wzięły swoje lampy i wyszły na spotkanie oblubieńca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 2, 'Pięć z nich było mądrych, a pięć głupich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 3, 'Te głupie, wziąwszy swoje lampy, nie wzięły ze sobą oliwy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 4, 'Lecz mądre wraz z lampami zabrały oliwę w naczyniach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 5, 'A gdy oblubieniec zwlekał z przyjściem, wszystkie zmorzył sen i zasnęły.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 6, 'O północy zaś rozległ się krzyk: Oblubieniec idzie, wyjdźcie mu na spotkanie!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 7, 'Wtedy wstały wszystkie te dziewice i przygotowały swoje lampy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 8, 'A głupie powiedziały do mądrych: Dajcie nam ze swej oliwy, bo nasze lampy gasną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 9, 'I odpowiedziały mądre: Nie damy, bo mogłoby i nam, i wam nie wystarczyć. Idźcie raczej do sprzedawców i kupcie sobie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 10, 'A gdy odeszły kupić, nadszedł oblubieniec. Te, które były gotowe, weszły z nim na wesele i zamknięto drzwi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 11, 'Potem przyszły też pozostałe dziewice i powiedziały: Panie, Panie, otwórz nam!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 12, 'Lecz on odpowiedział: Zaprawdę powiadam wam, nie znam was.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 13, 'Czuwajcie więc, bo nie znacie dnia ani godziny, o której Syn Człowieczy przyjdzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 14, 'Królestwo niebieskie bowiem podobne jest do człowieka, który odjeżdżając, zwołał swoje sługi i powierzył im swoje dobra.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 15, 'Jednemu dał pięć talentów, drugiemu dwa, a trzeciemu jeden, każdemu według jego zdolności, i zaraz odjechał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 16, 'A ten, który otrzymał pięć talentów, poszedł, obracał nimi i zyskał drugie pięć talentów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 17, 'Tak samo i ten, który otrzymał dwa, zyskał drugie dwa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 18, 'Ten zaś, który otrzymał jeden, poszedł, wykopał dół w ziemi i ukrył pieniądze swego pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 19, 'A po dłuższym czasie przybył pan tych sług i zaczął się z nimi rozliczać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 20, 'Wówczas przyszedł ten, który otrzymał pięć talentów, przyniósł drugie pięć talentów i powiedział: Panie, powierzyłeś mi pięć talentów, oto drugie pięć talentów zyskałem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 21, 'I powiedział mu jego pan: Dobrze, sługo dobry i wierny! W niewielu rzeczach byłeś wierny, nad wieloma cię ustanowię. Wejdź do radości swego pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 22, 'Przyszedł i ten, który otrzymał dwa talenty i powiedział: Panie, powierzyłeś mi dwa talenty, oto drugie dwa talenty zyskałem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 23, 'Powiedział mu jego pan: Dobrze, sługo dobry i wierny! Ponieważ byłeś wierny w niewielu rzeczach, nad wieloma cię ustanowię. Wejdź do radości swego pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 24, 'Przyszedł i ten, który otrzymał jeden talent i powiedział: Panie, wiedziałem, że jesteś człowiekiem surowym: żniesz, gdzie nie posiałeś i zbierasz, gdzie nie rozsypałeś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 25, 'Bojąc się więc, poszedłem i ukryłem twój talent w ziemi. Oto masz, co twoje.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 26, 'A jego pan mu odpowiedział: Sługo zły i leniwy! Wiedziałeś, że żnę, gdzie nie posiałem i zbieram, gdzie nie rozsypałem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 27, 'Powinieneś więc był dać moje pieniądze bankierom, a ja po powrocie odebrałbym to, co moje, z zyskiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 28, 'Dlatego odbierzcie mu ten talent i dajcie temu, który ma dziesięć talentów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 29, 'Każdemu bowiem, kto ma, będzie dane i będzie miał w obfitości. Temu zaś, kto nie ma, zostanie zabrane nawet to, co ma.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 30, 'A nieużytecznego sługę wrzućcie w ciemności zewnętrzne. Tam będzie płacz i zgrzytanie zębów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 31, 'Gdy Syn Człowieczy przyjdzie w swojej chwale i wszyscy święci aniołowie z nim, wtedy zasiądzie na tronie swojej chwały.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 32, 'I będą zgromadzone przed nim wszystkie narody, a on odłączy jedne od drugich, jak pasterz odłącza owce od kozłów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 33, 'I postawi owce po swojej prawej, a kozły po lewej stronie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 34, 'Wtedy król powie do tych, którzy będą po jego prawej stronie: Przyjdźcie, błogosławieni mego Ojca, odziedziczcie królestwo przygotowane dla was od założenia świata.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 35, 'Byłem bowiem głodny, a daliście mi jeść, byłem spragniony, a daliście mi pić, byłem obcym, a przyjęliście mnie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 36, 'Byłem nagi, a ubraliście mnie, byłem chory, a odwiedziliście mnie, byłem w więzieniu, a przyszliście do mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 37, 'Wtedy sprawiedliwi mu odpowiedzą: Panie, kiedy widzieliśmy cię głodnym i nakarmiliśmy cię albo spragnionym i daliśmy ci pić?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 38, 'I kiedy widzieliśmy cię obcym i przyjęliśmy cię albo nagim i ubraliśmy cię?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 39, 'Albo kiedy widzieliśmy cię chorym lub w więzieniu i przyszliśmy do ciebie?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 40, 'A król im odpowie: Zaprawdę powiadam wam: To, co uczyniliście jednemu z tych moich braci najmniejszych, mnie uczyniliście.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 41, 'Potem powie i do tych, którzy będą po lewej stronie: Idźcie ode mnie, przeklęci, w ogień wieczny, przygotowany dla diabła i jego aniołów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 42, 'Byłem bowiem głodny, a nie daliście mi jeść, byłem spragniony, a nie daliście mi pić;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 43, 'Byłem obcym, a nie przyjęliście mnie, byłem nagi, a nie ubraliście mnie, byłem chory i w więzieniu, a nie odwiedziliście mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 44, 'Wtedy i oni mu odpowiedzą: Panie, kiedy widzieliśmy cię głodnym albo spragnionym, albo obcym, albo nagim, albo chorym, albo w więzieniu, a nie usłużyliśmy tobie?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 45, 'Wówczas im odpowie: Zaprawdę powiadam wam, czego nie uczyniliście jednemu z tych najmniejszych, nie uczyniliście i mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 46, 'I pójdą ci na męki wieczne, sprawiedliwi zaś do życia wiecznego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 1, 'A gdy Jezus dokończył tych wszystkich mów, powiedział do swoich uczniów:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 2, 'Wiecie, że za dwa dni będzie Pascha, a Syn Człowieczy zostanie wydany na ukrzyżowanie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 3, 'Wtedy to naczelni kapłani, uczeni w Piśmie i starsi ludu zebrali się na dziedzińcu najwyższego kapłana, zwanego Kajfaszem;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 4, 'I naradzali się, jak by podstępnie schwytać i zabić Jezusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 5, 'Lecz mówili: Nie w święto, aby nie wywołać rozruchu wśród ludu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 6, 'A gdy Jezus był w Betanii, w domu Szymona Trędowatego;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 7, 'Przyszła do niego kobieta, która miała alabastrowe naczynie bardzo drogiego olejku, i wylała go na jego głowę, gdy siedział przy stole.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 8, 'Widząc to, jego uczniowie oburzyli się i powiedzieli: I na cóż to marnotrawstwo?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 9, 'Przecież można było ten olejek drogo sprzedać, a pieniądze rozdać ubogim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 10, 'Gdy Jezus to zauważył, powiedział im: Dlaczego sprawiacie przykrość tej kobiecie? Przecież dobry uczynek spełniła wobec mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 11, 'Ubogich bowiem zawsze macie u siebie, ale mnie nie zawsze mieć będziecie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 12, 'Bo ona, wylewając ten olejek na moje ciało, zrobiła to, aby przygotować mnie na mój pogrzeb.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 13, 'Zaprawdę powiadam wam: Gdziekolwiek po całym świecie będzie głoszona ta ewangelia, będzie się też opowiadać na jej pamiątkę to, co zrobiła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 14, 'Wtedy jeden z dwunastu, zwany Judaszem Iskariotą, poszedł do naczelnych kapłanów;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 15, 'I powiedział: Co chcecie mi dać, a ja wam go wydam. A oni wyznaczyli mu trzydzieści srebrników.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 16, 'I odtąd szukał sposobności, aby go wydać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 17, 'W pierwszy dzień Przaśników uczniowie podeszli do Jezusa i zapytali go: Gdzie chcesz, abyśmy przygotowali ci Paschę do spożycia?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 18, 'A on odpowiedział: Idźcie do miasta, do pewnego człowieka i powiedzcie mu: Nauczyciel mówi: Mój czas jest bliski; u ciebie będę obchodził Paschę z moimi uczniami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 19, 'Uczniowie zrobili tak, jak im nakazał Jezus, i przygotowali Paschę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 20, 'Kiedy nastał wieczór, usiadł za stołem z dwunastoma.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 21, 'A gdy jedli, powiedział: Zaprawdę powiadam wam, że jeden z was mnie wyda.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 22, 'I bardzo zasmuceni zaczęli pytać jeden po drugim: Czy to ja, Panie?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 23, 'A on odpowiedział: Ten, który macza ze mną rękę w misie, on mnie wyda.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 24, 'Syn Człowieczy odchodzi, jak jest o nim napisane, ale biada człowiekowi, przez którego Syn Człowieczy będzie wydany! Lepiej byłoby dla tego człowieka, aby się nie urodził.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 25, 'Wtedy Judasz, który go zdradził, zapytał: Czy to ja, Mistrzu? Odpowiedział mu: Ty sam to powiedziałeś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 26, 'A gdy jedli, Jezus wziął chleb, pobłogosławił, połamał i dał uczniom, mówiąc: Bierzcie, jedzcie, to jest moje ciało.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 27, 'Potem wziął kielich, złożył dziękczynienie i dał im, mówiąc: Pijcie z niego wszyscy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 28, 'To bowiem jest moja krew nowego testamentu, która wylewa się za wielu na przebaczenie grzechów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 29, 'Ale mówię wam: Odtąd nie będę pił z tego owocu winorośli aż do dnia, gdy go będę pił z wami nowy w królestwie mego Ojca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 30, 'A gdy zaśpiewali hymn, wyszli ku Górze Oliwnej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 31, 'Wtedy Jezus powiedział do nich: Wy wszyscy zgorszycie się z mojego powodu tej nocy. Jest bowiem napisane: Uderzę pasterza i rozproszą się owce stada.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 32, 'Lecz gdy zmartwychwstanę, udam się do Galilei przed wami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 33, 'A Piotr odezwał się do niego: Choćby się wszyscy zgorszyli z twojego powodu, ja się nigdy nie zgorszę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 34, 'Powiedział mu Jezus: Zaprawdę powiadam ci, że tej nocy, zanim kogut zapieje, trzy razy się mnie wyprzesz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 35, 'Odpowiedział mu Piotr: Choćbym miał z tobą umrzeć, nie wyprę się ciebie. Podobnie mówili wszyscy uczniowie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 36, 'Wtedy Jezus przyszedł z nimi na miejsce zwane Getsemani i powiedział do uczniów: Siądźcie tu, a ja tymczasem odejdę tam i będę się modlił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 37, 'A wziąwszy ze sobą Piotra i dwóch synów Zebedeusza, zaczął się smucić i odczuwać udrękę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 38, 'Wtedy Jezus powiedział do nich: Smutna jest moja dusza aż do śmierci. Zostańcie tu i czuwajcie ze mną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 39, 'A odszedłszy trochę dalej, upadł na twarz i modlił się, mówiąc: Mój Ojcze, jeśli to możliwe, niech mnie ominie ten kielich. Jednak niech się stanie nie jak ja chcę, ale jak ty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 40, 'Potem przyszedł do uczniów i zastał ich śpiących, i powiedział do Piotra: Czy nie mogliście przez jedną godzinę czuwać ze mną?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 41, 'Czuwajcie i módlcie się, abyście nie ulegli pokusie. Duch wprawdzie jest ochoczy, ale ciało słabe.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 42, 'Znowu, po raz drugi odszedł i modlił się, mówiąc: Mój Ojcze, jeśli ten kielich nie może mnie minąć, tylko abym go wypił, niech się stanie twoja wola.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 43, 'A gdy przyszedł, znowu zastał ich śpiących, bo oczy same im się zamykały.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 44, 'I zostawiwszy ich, odszedł znowu i modlił się po raz trzeci tymi samymi słowami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 45, 'Potem przyszedł do swoich uczniów i powiedział do nich: Śpijcie jeszcze i odpoczywajcie. Oto nadchodzi godzina i Syn Człowieczy będzie wydany w ręce grzeszników.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 46, 'Wstańcie, chodźmy! Oto zbliża się ten, który mnie wyda.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 47, 'A gdy on jeszcze mówił, nadszedł Judasz, jeden z dwunastu, a z nim liczny tłum z mieczami i kijami, od naczelnych kapłanów i starszych ludu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 48, 'Ten zaś, który go zdradził, ustalił z nimi znak, mówiąc: Ten, którego pocałuję, to on. Schwytajcie go.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 49, 'Zaraz też podszedł do Jezusa i powiedział: Witaj, Mistrzu! I pocałował go.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 50, 'Jezus powiedział do niego: Przyjacielu, po co przyszedłeś? Wtedy podeszli, rzucili się na Jezusa i schwytali go.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 51, 'A oto jeden z tych, którzy byli z Jezusem, wyciągnął rękę i dobył miecz, a uderzywszy sługę najwyższego kapłana, odciął mu ucho.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 52, 'Wtedy Jezus powiedział do niego: Schowaj miecz na swoje miejsce. Wszyscy bowiem, którzy za miecz chwytają, od miecza zginą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 53, 'Czy sądzisz, że nie mógłbym teraz prosić mego Ojca, a wystawiłby mi więcej niż dwanaście legionów aniołów?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 54, 'Ale jakże wypełniłyby się Pisma, które mówią, że musi się tak stać?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 55, 'W tym momencie Jezus powiedział do tłumów: Wyszliście jak na bandytę z mieczami i kijami, aby mnie schwytać. Codziennie siadałem z wami, nauczając w świątyni, a nie schwytaliście mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 56, 'Ale to wszystko się stało, aby się wypełniły Pisma proroków. Wtedy wszyscy uczniowie opuścili go i uciekli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 57, 'A ci, którzy schwytali Jezusa, zaprowadzili go do Kajfasza, najwyższego kapłana, gdzie zebrali się uczeni w Piśmie i starsi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 58, 'Piotr zaś szedł za nim z daleka aż do dziedzińca najwyższego kapłana i wszedłszy tam, siedział ze sługami, aby zobaczyć, jak to się skończy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 59, 'Tymczasem naczelni kapłani, starsi i cała Rada szukali fałszywego świadectwa przeciwko Jezusowi, aby go skazać na śmierć;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 60, 'Lecz nie znaleźli. I chociaż przychodziło wielu fałszywych świadków, jednak niczego nie znaleźli. A na koniec wystąpili dwaj fałszywi świadkowie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 61, 'Mówiąc: On powiedział: Mogę zburzyć świątynię Bożą i w trzy dni ją odbudować.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 62, 'Wtedy najwyższy kapłan powstał i zapytał go: Nic nie odpowiadasz? Cóż znaczy to, co oni przeciwko tobie zeznają?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 63, 'Lecz Jezus milczał. A najwyższy kapłan powiedział mu: Zaklinam cię na Boga żywego, abyś nam powiedział, czy ty jesteś Chrystusem, Synem Bożym?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 64, 'Odpowiedział mu Jezus: Ty powiedziałeś. Ale mówię wam: Odtąd ujrzycie Syna Człowieczego siedzącego po prawicy mocy Boga i przychodzącego na obłokach niebieskich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 65, 'Wtedy najwyższy kapłan rozdarł swoje szaty i powiedział: Zbluźnił! Czyż potrzebujemy jeszcze świadków? Oto teraz słyszeliście bluźnierstwo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 66, 'Jak wam się zdaje? A oni odpowiedzieli: Zasługuje na śmierć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 67, 'Wówczas zaczęli pluć mu w twarz i bili go pięściami, a inni go policzkowali;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 68, 'Mówiąc: Prorokuj nam, Chrystusie: Kto cię uderzył?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 69, 'Piotr zaś siedział na zewnątrz, na dziedzińcu. Podeszła do niego pewna dziewczyna i powiedziała: Ty też byłeś z Jezusem z Galilei.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 70, 'Lecz on wyparł się wobec wszystkich, mówiąc: Nie wiem, o czym mówisz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 71, 'A gdy wyszedł do przedsionka, zobaczyła go inna dziewczyna i powiedziała do tych, którzy tam byli: On też był z Jezusem z Nazaretu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 72, 'I znowu wyparł się pod przysięgą: Nie znam tego człowieka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 73, 'Po chwili ci, którzy tam stali, podeszli i powiedzieli do Piotra: Na pewno ty też jesteś jednym z nich, bo i twoja mowa cię zdradza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 74, 'Wtedy zaczął się zaklinać i przysięgać: Nie znam tego człowieka. I zaraz zapiał kogut.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 75, 'I przypomniał sobie Piotr słowa Jezusa, który mu powiedział: Zanim kogut zapieje, trzy razy się mnie wyprzesz. Wyszedł na zewnątrz i gorzko zapłakał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 1, 'A gdy nastał ranek, wszyscy naczelni kapłani i starsi ludu naradzili się przeciwko Jezusowi, aby go zabić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 2, 'Związali go, odprowadzili i wydali namiestnikowi Poncjuszowi Piłatowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 3, 'Wtedy Judasz, który go wydał, widząc, że został skazany, żałował tego i zwrócił trzydzieści srebrników naczelnym kapłanom i starszym;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 4, 'Mówiąc: Zgrzeszyłem, wydając krew niewinną. A oni powiedzieli: Cóż nam do tego? To twoja sprawa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 5, 'Wtedy rzucił te srebrniki w świątyni i oddalił się, a potem poszedł i powiesił się.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 6, 'A naczelni kapłani wzięli srebrniki i mówili: Nie wolno ich kłaść do skarbca świątynnego, gdyż jest to zapłata za krew.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 7, 'I naradziwszy się, kupili za nie pole garncarza, aby grzebać na nim cudzoziemców.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 8, 'Dlatego to pole aż do dziś nazywa się Polem Krwi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 9, 'Wtedy się wypełniło, co zostało powiedziane przez proroka Jeremiasza: I wzięli trzydzieści srebrników, zapłatę za oszacowanego, którego oszacowali synowie Izraela;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 10, 'I dali je za pole garncarza, jak mi nakazał Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 11, 'Jezus stał przed namiestnikiem. I zapytał go namiestnik: Czy ty jesteś królem Żydów? Jezus mu odpowiedział: Ty sam to mówisz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 12, 'A gdy oskarżali go naczelni kapłani i starsi, nic nie odpowiedział.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 13, 'Wtedy Piłat zapytał go: Nie słyszysz, jak wiele zeznają przeciwko tobie?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 14, 'Lecz mu nie odpowiedział na żadne słowo, tak że namiestnik bardzo się dziwił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 15, 'A na święto namiestnik miał zwyczaj wypuszczać ludowi jednego więźnia, tego, którego chcieli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 16, 'Trzymano zaś w tym czasie osławionego więźnia, zwanego Barabaszem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 17, 'Gdy więc się zebrali, zapytał ich Piłat: Którego chcecie, abym wam wypuścił? Barabasza czy Jezusa, zwanego Chrystusem?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 18, 'Wiedział bowiem, że wydali go z zawiści.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 19, 'A gdy on siedział na krześle sędziowskim, jego żona posłała wiadomość do niego: Nie miej nic do czynienia z tym sprawiedliwym, bo dzisiaj we śnie wiele wycierpiałam z jego powodu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 20, 'Tymczasem naczelni kapłani i starsi namówili tłumy, aby prosiły o Barabasza, a domagały się stracenia Jezusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 21, 'Namiestnik zapytał ich: Którego z tych dwóch chcecie, abym wam wypuścił? A oni odpowiedzieli: Barabasza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 22, 'Piłat zapytał ich: Cóż więc mam zrobić z Jezusem, którego nazywają Chrystusem? Odpowiedzieli mu wszyscy: Niech będzie ukrzyżowany!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 23, 'Namiestnik zaś zapytał: Cóż właściwie złego uczynił? Lecz oni jeszcze głośniej wołali: Niech będzie ukrzyżowany!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 24, 'Gdy Piłat zobaczył, że nic nie osiąga, ale przeciwnie, zamieszanie staje się większe, wziął wodę i umył ręce przed tłumem, mówiąc: Nie jestem winny krwi tego sprawiedliwego. To wasza sprawa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 25, 'A cały lud odpowiedział: Krew jego na nas i na nasze dzieci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 26, 'Wtedy wypuścił im Barabasza, a Jezusa, po ubiczowaniu, wydał na ukrzyżowanie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 27, 'Wówczas żołnierze namiestnika zaprowadzili Jezusa na ratusz i zebrali wokół niego cały oddział.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 28, 'A rozebrawszy go, ubrali go w szkarłatny płaszcz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 29, 'Upletli koronę z cierni i włożyli mu na głowę, a w prawą rękę dali trzcinę. I padając przed nim na kolana, naśmiewali się z niego, mówiąc: Witaj, królu Żydów!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 30, 'A plując na niego, brali tę trzcinę i bili go po głowie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 31, 'Kiedy go wyszydzili, zdjęli z niego płaszcz, ubrali go w jego szaty i odprowadzili na ukrzyżowanie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 32, 'A wychodząc, spotkali człowieka z Cyreny, imieniem Szymon. Tego przymusili, aby niósł jego krzyż.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 33, 'Gdy przyszli na miejsce zwane Golgotą, czyli Miejscem Czaszki;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 34, 'Dali mu do picia ocet zmieszany z żółcią. Skosztował, ale nie chciał pić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 35, 'A gdy go ukrzyżowali, rozdzielili jego szaty i rzucali losy, aby się wypełniło, co zostało powiedziane przez proroka: Rozdzielili między siebie moje szaty, a o moje ubranie rzucali losy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 36, 'A siedząc, tam go pilnowali.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 37, 'I umieścili nad jego głową napis z podaniem jego winy: To jest Jezus, król Żydów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 38, 'Ukrzyżowano też z nim dwóch bandytów, jednego po prawej, a drugiego po lewej stronie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 39, 'A ci, którzy przechodzili obok, bluźnili mu, kiwając głowami;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 40, 'I mówiąc: Ty, który burzysz świątynię i w trzy dni ją odbudowujesz, ratuj samego siebie. Jeśli jesteś Synem Bożym, zejdź z krzyża.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 41, 'Podobnie naczelni kapłani z uczonymi w Piśmie i starszymi, naśmiewając się, mówili:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 42, 'Innych ratował, a samego siebie uratować nie może. Jeśli jest królem Izraela, niech teraz zejdzie z krzyża, a uwierzymy mu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 43, 'Ufał Bogu, niech go teraz wybawi, jeśli go sobie upodobał. Przecież powiedział: Jestem Synem Bożym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 44, 'Tak samo urągali mu też bandyci, którzy byli z nim ukrzyżowani.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 45, 'A od godziny szóstej aż do dziewiątej ciemność ogarnęła całą ziemię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 46, 'Około godziny dziewiątej Jezus zawołał donośnym głosem: Eli, Eli, lama sabachthani? To znaczy: Boże mój, Boże mój, czemu mnie opuściłeś?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 47, 'Wtedy niektórzy z tych, co tam stali, usłyszawszy to, mówili: On woła Eliasza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 48, 'I zaraz jeden z nich podbiegł, wziął gąbkę i napełnił ją octem, a włożywszy na trzcinę, dał mu pić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 49, 'Lecz inni mówili: Przestań, zobaczmy, czy przyjdzie Eliasz, aby go wybawić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 50, 'Jezus zaś zawołał ponownie donośnym głosem i oddał ducha.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 51, 'A oto zasłona świątyni rozerwała się na pół, od góry aż do dołu, ziemia się zatrzęsła i skały popękały.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 52, 'Grobowce się otworzyły, a wiele ciał świętych, którzy zasnęli, powstało.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 53, 'I wyszli z grobów po jego zmartwychwstaniu, weszli do miasta świętego i ukazali się wielu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 54, 'Wtedy setnik i ci, którzy z nim pilnowali Jezusa, widząc trzęsienie ziemi i to, co się działo, bardzo się zlękli i powiedzieli: On prawdziwie był Synem Bożym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 55, 'A było tam wiele kobiet, które przypatrywały się z daleka. Szły one za Jezusem od Galilei i usługiwały mu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 56, 'Wśród nich były: Maria Magdalena, Maria, matka Jakuba i Józefa, oraz matka synów Zebedeusza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 57, 'A gdy nastał wieczór, przyszedł bogaty człowiek z Arymatei, imieniem Józef, który też był uczniem Jezusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 58, 'Udał się on do Piłata i poprosił o ciało Jezusa. Wtedy Piłat rozkazał, aby mu je wydano.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 59, 'A Józef zabrał ciało, owinął je w czyste płótno;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 60, 'I złożył w swoim nowym grobowcu, który wykuł w skale. Przed wejście do grobowca zatoczył wielki kamień i odszedł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 61, 'A Maria Magdalena i druga Maria siedziały tam naprzeciw grobowca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 62, 'Następnego dnia, pierwszego po dniu przygotowania, naczelni kapłani i faryzeusze zebrali się u Piłata;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 63, 'I oznajmili: Panie, przypomnieliśmy sobie, że ten zwodziciel powiedział, gdy jeszcze żył: Po trzech dniach zmartwychwstanę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 64, 'Rozkaż więc zabezpieczyć grobowiec aż do trzeciego dnia, by przypadkiem jego uczniowie nie przyszli w nocy, nie wykradli go i nie powiedzieli ludowi: Powstał z martwych. I ostatni błąd będzie gorszy niż pierwszy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 65, 'Piłat powiedział im: Macie straż. Idźcie, zabezpieczcie, jak umiecie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 66, 'Poszli więc i zabezpieczyli grobowiec, pieczętując kamień i stawiając straż.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 1, 'A gdy skończył się szabat i świtało pierwszego dnia tygodnia, Maria Magdalena i druga Maria przyszły obejrzeć grób.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 2, 'A oto powstało wielkie trzęsienie ziemi. Anioł Pana bowiem, zstąpiwszy z nieba, podszedł, odwalił kamień od wejścia i usiadł na nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 3, 'Jego oblicze było jak błyskawica, a jego szaty białe jak śnieg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 4, 'A strażnicy drżeli ze strachu i stali się jak umarli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 5, 'Anioł zaś powiedział do kobiet: Wy się nie bójcie! Wiem bowiem, że szukacie ukrzyżowanego Jezusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 6, 'Nie ma go tu. Powstał bowiem, jak powiedział. Chodźcie, zobaczcie miejsce, gdzie leżał Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 7, 'Idźcie szybko i powiedzcie jego uczniom, że zmartwychwstał i oto udaje się do Galilei przed wami. Tam go ujrzycie. Oto wam powiedziałem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 8, 'Odeszły więc szybko od grobu z bojaźnią i z wielką radością i pobiegły przekazać to jego uczniom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 9, 'Kiedy szły przekazać to jego uczniom, nagle Jezus wyszedł im na spotkanie i powiedział: Witajcie! A one podeszły, objęły go za nogi i oddały mu pokłon.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 10, 'Wtedy Jezus powiedział do nich: Nie bójcie się! Idźcie, powiedzcie moim braciom, aby poszli do Galilei. Tam mnie ujrzą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 11, 'A gdy one poszły, niektórzy ze straży przyszli do miasta i oznajmili naczelnym kapłanom wszystko, co się stało.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 12, 'Ci zaś zebrali się ze starszymi i naradziwszy się, dali żołnierzom sporo pieniędzy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 13, 'I powiedzieli: Mówcie, że jego uczniowie przyszli w nocy i wykradli go, gdy spaliście.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 14, 'A gdyby to doszło do namiestnika, my go przekonamy, a wam zapewnimy bezpieczeństwo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 15, 'Wzięli więc pieniądze i zrobili, jak ich pouczono. I rozniosła się ta wieść wśród Żydów, i trwa aż do dziś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 16, 'Potem jedenastu uczniów poszło do Galilei na górę, na którą Jezus im polecił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 17, 'A gdy go ujrzeli, oddali mu pokłon. Niektórzy jednak wątpili.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 18, 'Wtedy Jezus podszedł i powiedział do nich: Dana mi jest wszelka władza na niebie i na ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 19, 'Idźcie więc i nauczajcie wszystkie narody, chrzcząc je w imię Ojca i Syna, i Ducha Świętego;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 20, 'Ucząc je przestrzegać wszystkiego, co wam przykazałem. A oto ja jestem z wami przez wszystkie dni aż do końca świata. Amen.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 1, 'Początek ewangelii Jezusa Chrystusa, Syna Bożego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 2, 'Jak jest napisane u Proroków: Oto ja posyłam mego posłańca przed twoim obliczem, który przygotuje twoją drogę przed tobą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 3, 'Głos wołającego na pustyni: Przygotujcie drogę Pana, prostujcie jego ścieżki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 4, 'Jan chrzcił na pustyni i głosił chrzest pokuty na przebaczenie grzechów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 5, 'I przychodziła do niego cała kraina judzka i mieszkańcy Jerozolimy, i wszyscy byli chrzczeni przez niego w rzece Jordan, wyznając swoje grzechy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 6, 'Jan ubierał się w sierść wielbłądzią i miał skórzany pas wokół swoich bioder, a jadał szarańczę i miód leśny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 7, 'I głosił: Idzie za mną mocniejszy ode mnie, któremu nie jestem godny, schyliwszy się, rozwiązać rzemyka u jego obuwia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 8, 'Ja chrzciłem was wodą, ale on będzie was chrzcił Duchem Świętym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 9, 'A w tych dniach przyszedł Jezus z Nazaretu w Galilei i został ochrzczony przez Jana w Jordanie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 10, 'A zaraz, wychodząc z wody, ujrzał rozstępujące się niebiosa i Ducha jak gołębicę zstępującego na niego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 11, 'I rozległ się głos z nieba: Ty jesteś moim umiłowanym Synem, w którym mam upodobanie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 12, 'I zaraz Duch zapędził go na pustynię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 13, 'Był tam na pustyni czterdzieści dni, będąc kuszony przez szatana. I przebywał wśród zwierząt, a aniołowie służyli mu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 14, 'Lecz potem, gdy Jan został wtrącony do więzienia, Jezus przyszedł do Galilei, głosząc ewangelię królestwa Bożego;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 15, 'I mówiąc: Wypełnił się czas i przybliżyło się królestwo Boże. Pokutujcie i wierzcie ewangelii.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 16, 'A przechadzając się nad Morzem Galilejskim, zobaczył Szymona i Andrzeja, jego brata, zarzucających sieć w morze; byli bowiem rybakami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 17, 'I powiedział do nich Jezus: Pójdźcie za mną, a sprawię, że staniecie się rybakami ludzi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 18, 'A oni natychmiast zostawili swoje sieci i poszli za nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 19, 'Gdy zaś odszedł stamtąd nieco dalej, zobaczył Jakuba, syna Zebedeusza, i Jana, jego brata, którzy w łodzi naprawiali sieci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 20, 'I zaraz ich powołał, a oni zostawili swego ojca Zebedeusza w łodzi z najemnikami i poszli za nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 21, 'Potem weszli do Kafarnaum, a zaraz w szabat Jezus wszedł do synagogi i nauczał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 22, 'I zdumiewali się jego nauką, uczył ich bowiem jak ten, który ma moc, a nie jak uczeni w Piśmie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 23, 'A w ich synagodze był człowiek mający ducha nieczystego, który zawołał:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 24, 'Ach, cóż my z tobą mamy, Jezusie z Nazaretu? Przyszedłeś nas zniszczyć? Wiem, kim jesteś: Świętym Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 25, 'I zgromił go Jezus: Zamilcz i wyjdź z niego!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 26, 'Wtedy duch nieczysty szarpnął nim i zawoławszy donośnym głosem, wyszedł z niego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 27, 'I zdumieli się wszyscy, tak że pytali się między sobą: Cóż to jest? Co to za nowa nauka, że z mocą rozkazuje nawet duchom nieczystym i są mu posłuszne?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 28, 'I wieść o nim szybko się rozeszła po całej okolicy wokół Galilei.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 29, 'A zaraz po wyjściu z synagogi przyszli z Jakubem i Janem do domu Szymona i Andrzeja.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 30, 'A teściowa Szymona leżała w gorączce. Od razu też powiedzieli mu o niej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 31, 'Podszedł więc i podniósł ją, ująwszy za rękę, i natychmiast opuściła ją gorączka. A ona usługiwała im.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 32, 'Kiedy nastał wieczór i zaszło słońce, przynosili do niego wszystkich chorych oraz opętanych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 33, 'A całe miasto zgromadziło się przed drzwiami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 34, 'On zaś uzdrowił wielu cierpiących na różne choroby i wypędził wiele demonów, a nie pozwolił demonom mówić, bo go znały.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 35, 'A wstawszy wczesnym rankiem, przed świtem, wyszedł i udał się na odludne miejsce, i tam się modlił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 36, 'Poszli też za nim Szymon i ci, którzy z nim byli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 37, 'A znalazłszy go, powiedzieli mu: Wszyscy cię szukają.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 38, 'Wtedy im powiedział: Chodźmy do przyległych miasteczek, abym i tam głosił, bo po to przyszedłem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 39, 'I głosił w ich synagogach po całej Galilei, i wypędzał demony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 40, 'Wtedy przyszedł do niego trędowaty, upadł przed nim na kolana i prosił go: Jeśli chcesz, możesz mnie oczyścić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 41, 'A Jezus, zdjęty litością, wyciągnął rękę, dotknął go i powiedział do niego: Chcę, bądź oczyszczony!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 42, 'Gdy Pan to powiedział, natychmiast trąd go opuścił i został oczyszczony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 43, 'A Jezus surowo mu przykazał i zaraz go odprawił;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 44, 'Mówiąc: Uważaj, abyś nikomu nic nie mówił, ale idź, pokaż się kapłanowi i ofiaruj za swoje oczyszczenie to, co nakazał Mojżesz, na świadectwo dla nich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 45, 'Lecz on odszedł i zaczął bardzo to rozpowiadać i rozgłaszać, tak że Jezus nie mógł już jawnie wejść do miasta, ale przebywał na zewnątrz, w miejscach odludnych. A ludzie zewsząd schodzili się do niego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 1, 'A po kilku dniach znowu przyszedł do Kafarnaum i usłyszano, że jest w domu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 2, 'I zaraz zeszło się tak wielu ludzi, że nie mogli się zmieścić nawet przed drzwiami. I głosił im słowo Boże.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 3, 'Wtedy przyszli do niego, niosąc sparaliżowanego, a niosło go czterech ludzi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 4, 'A gdy nie mogli do niego podejść z powodu tłumu, odkryli dach nad miejscem, gdzie był Jezus, wyłamali go i spuścili na dół posłanie, na którym leżał sparaliżowany.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 5, 'A Jezus, widząc ich wiarę, powiedział do sparaliżowanego: Synu, twoje grzechy są ci przebaczone.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 6, 'A byli tam niektórzy z uczonych w Piśmie, siedząc i myśląc w swoich sercach:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 7, 'Czemu on mówi takie bluźnierstwa? Któż może przebaczać grzechy oprócz samego Boga?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 8, 'A zaraz Jezus, poznawszy w swym duchu, że tak myśleli, powiedział do nich: Czemuż tak myślicie w swoich sercach?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 9, 'Cóż jest łatwiej – powiedzieć sparaliżowanemu: Przebaczone są ci grzechy, czy powiedzieć: Wstań, weź swoje posłanie i chodź?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 10, 'Ale żebyście wiedzieli, że Syn Człowieczy ma na ziemi moc przebaczać grzechy – powiedział do sparaliżowanego:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 11, 'Mówię ci: Wstań, weź swoje posłanie i idź do domu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 12, 'A on natychmiast wstał, wziął swoje posłanie i wyszedł na oczach wszystkich, tak że wszyscy byli zdumieni i chwalili Boga, mówiąc: Nigdy nie widzieliśmy czegoś takiego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 13, 'I wyszedł znów nad morze. I przychodził do niego cały lud, a on ich nauczał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 14, 'A przechodząc, zobaczył Lewiego, syna Alfeusza, siedzącego w punkcie celnym, i powiedział do niego: Pójdź za mną. A on wstał i poszedł za nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 15, 'Kiedy Jezus siedział za stołem w jego domu, razem z Jezusem i jego uczniami siedziało wielu celników i grzeszników. Było ich bowiem wielu i chodzili za nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 16, 'A uczeni w Piśmie i faryzeusze, widząc, że je z celnikami i grzesznikami, mówili do jego uczniów: Cóż to jest, że on je i pije z celnikami i grzesznikami?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 17, 'A Jezus, usłyszawszy to, powiedział im: Nie zdrowi, lecz chorzy potrzebują lekarza. Nie przyszedłem wzywać do pokuty sprawiedliwych, ale grzeszników.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 18, 'A uczniowie Jana i faryzeuszy pościli. Przyszli więc i pytali go: Czemu uczniowie Jana i faryzeuszy poszczą, a twoi uczniowie nie poszczą?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 19, 'I odpowiedział im Jezus: Czy przyjaciele oblubieńca mogą pościć, gdy jest z nimi oblubieniec? Dopóki mają ze sobą oblubieńca, nie mogą pościć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 20, 'Lecz przyjdą dni, gdy oblubieniec zostanie od nich zabrany, a wtedy, w tych dniach, będą pościć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 21, 'Nikt nie przyszywa łaty z nowego sukna do starej szaty, inaczej nowa łata ujmuje nieco od starej szaty i rozdarcie staje się gorsze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 22, 'Nikt też nie wlewa młodego wina do starych bukłaków, bo inaczej młode wino rozsadza bukłaki i wino wycieka, a bukłaki się psują. Lecz nowe wino należy wlewać do nowych bukłaków.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 23, 'A gdy Jezus szedł w szabat przez zboża, jego uczniowie zaczęli po drodze zrywać kłosy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 24, 'Wtedy faryzeusze mówili do niego: Spójrz, czemu oni robią w szabat to, czego nie wolno robić?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 25, 'A on im odpowiedział: Nigdy nie czytaliście, co zrobił Dawid, gdy znalazł się w potrzebie i był głodny, on i ci, którzy z nim byli?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 26, 'Jak wszedł do domu Bożego za Abiatara, najwyższego kapłana, i jadł chleby pokładne, których nie wolno było jeść nikomu oprócz kapłanów, i dał również tym, którzy z nim byli?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 27, 'Powiedział im także: Szabat został ustanowiony dla człowieka, a nie człowiek dla szabatu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 28, 'Dlatego Syn Człowieczy jest też Panem szabatu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 1, 'I wszedł znowu do synagogi. A był tam człowiek, który miał uschłą rękę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 2, 'I obserwowali go, czy uzdrowi go w szabat, aby go oskarżyć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 3, 'Wtedy powiedział do człowieka, który miał uschłą rękę: Wyjdź na środek!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 4, 'A do nich powiedział: Czy wolno w szabat czynić dobrze czy źle? Ocalić życie czy zabić? Lecz oni milczeli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 5, 'Wtedy spojrzał po nich z gniewem i zasmucony zatwardziałością ich serca, powiedział do tego człowieka: Wyciągnij rękę! Wyciągnął, a jego ręka znowu stała się zdrowa jak i druga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 6, 'Wówczas faryzeusze wyszli i zaraz odbyli naradę z herodianami przeciwko niemu, w jaki sposób go zgładzić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 7, 'Jezus zaś ze swymi uczniami odszedł nad morze, a wielkie mnóstwo ludzi szło za nim z Galilei i Judei;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 8, 'Z Jerozolimy, Idumei i Zajordania. Również spośród tych, którzy mieszkali w okolicach Tyru i Sydonu, przyszło do niego mnóstwo ludzi, słysząc, jak wielkie rzeczy czynił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 9, 'I nakazał swoim uczniom, aby zawsze mieli przygotowaną łódkę, ze względu na tłum, aby nie napierał na niego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 10, 'Wielu bowiem uzdrowił, tak że wszyscy, którzy mieli jakieś choroby, cisnęli się do niego, aby go dotknąć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 11, 'A duchy nieczyste na jego widok padały przed nim i wołały: Ty jesteś Synem Bożym!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 12, 'Lecz on surowo im nakazywał, żeby go nie ujawniały.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 13, 'Potem wszedł na górę i wezwał do siebie tych, których sam chciał, a oni przyszli do niego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 14, 'I ustanowił dwunastu, aby z nim byli, aby ich wysłać na głoszenie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 15, 'I aby mieli moc uzdrawiania chorób i wypędzania demonów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 16, 'Ustanowił Szymona, któremu nadał imię Piotr;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 17, 'Jakuba, syna Zebedeusza, i Jana, brata Jakuba, którym nadał przydomek Boanerges, co znaczy: Synowie Gromu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 18, 'Andrzeja, Filipa, Bartłomieja, Mateusza, Tomasza, Jakuba, syna Alfeusza, Tadeusza, Szymona Kananejczyka;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 19, 'I Judasza Iskariotę, który go wydał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 20, 'Potem przyszli do domu. I znowu zgromadził się tłum, tak że nie mogli nawet zjeść chleba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 21, 'A gdy jego bliscy o tym usłyszeli, przyszli, aby go pochwycić. Mówili bowiem: Odszedł od zmysłów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 22, 'A uczeni w Piśmie, którzy przyszli z Jerozolimy, mówili: Ma Belzebuba i przez władcę demonów wypędza demony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 23, 'I przywoławszy ich do siebie, mówił do nich w przypowieściach: Jakże szatan może wypędzać szatana?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 24, 'Jeśli królestwo jest podzielone wewnętrznie, to takie królestwo nie może przetrwać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 25, 'I jeśli dom jest podzielony wewnętrznie, to taki dom nie będzie mógł przetrwać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 26, 'Jeśli więc szatan powstał przeciwko sobie samemu i jest podzielony, nie może przetrwać, ale to jego koniec.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 27, 'Nikt nie może wejść do domu mocarza i zagrabić jego własności, jeśli najpierw nie zwiąże tego mocarza; wtedy ograbi jego dom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 28, 'Zaprawdę powiadam wam: Wszystkie grzechy i bluźnierstwa, którymi bluźnią synowie ludzcy, będą im przebaczone.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 29, 'Kto jednak bluźni przeciwko Duchowi Świętemu, nigdy nie dostąpi przebaczenia, ale podlega karze wiecznego potępienia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 30, 'Bo mówili: Ma ducha nieczystego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 31, 'Wtedy przyszli jego bracia i matka, a stojąc przed domem, posłali po niego, wzywając go.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 32, 'A tłum siedział wokół niego. I powiedzieli mu: Oto twoja matka i twoi bracia są przed domem i szukają cię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 33, 'Lecz on im odpowiedział: Któż jest moją matką i moimi braćmi?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 34, 'A spojrzawszy po tych, którzy siedzieli wokół niego, powiedział: Oto moja matka i moi bracia!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 35, 'Kto bowiem wypełnia wolę Boga, ten jest moim bratem, moją siostrą i moją matką.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 1, 'I znowu zaczął nauczać nad morzem. Zgromadził się wokół niego wielki tłum, tak że wszedłszy do łodzi, siedział w niej na morzu, a wszyscy ludzie byli na brzegu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 2, 'A on nauczał ich wielu rzeczy w przypowieściach i mówił do nich w swojej nauce:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 3, 'Słuchajcie! Oto siewca wyszedł siać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 4, 'A gdy siał, jedno padło przy drodze, a ptaki niebieskie przyleciały i wydziobały je.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 5, 'Inne padło na miejsca skaliste, gdzie nie miało wiele ziemi, i szybko wzeszło, bo ziemia nie była głęboka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 6, 'A gdy słońce wzeszło, wypaliło je, a ponieważ nie miało korzenia, uschło.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 7, 'Inne zaś padło między ciernie, a ciernie wyrosły i zagłuszyły je, i nie wydało owocu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 8, 'A inne padło na dobrą ziemię i wydało bujnie wschodzący i rosnący owoc: jedno trzydziestokrotny, inne sześćdziesięciokrotny, a jeszcze inne stokrotny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 9, 'I mówił im: Kto ma uszy do słuchania, niech słucha.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 10, 'A gdy był sam, pytali go ci, którzy przy nim byli z dwunastoma, o tę przypowieść.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 11, 'A on im odpowiedział: Wam dano poznać tajemnicę królestwa Bożego. Tym zaś, którzy są na zewnątrz, wszystko podaje się w przypowieściach;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 12, 'Aby patrząc, patrzyli, a nie widzieli i słysząc, słyszeli, a nie zrozumieli, by się czasem nie nawrócili i nie były im przebaczone grzechy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 13, 'I powiedział do nich: Nie rozumiecie tej przypowieści? Jakże więc zrozumiecie wszystkie inne przypowieści?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 14, 'Siewca sieje słowo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 15, 'A ci przy drodze są tymi, którym sieje się słowo, ale gdy usłyszą, zaraz przychodzi szatan i wybiera słowo zasiane w ich sercach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 16, 'Podobnie ci, którzy zostali posiani na miejscach skalistych, są tymi, którzy, gdy usłyszą słowo, natychmiast je z radością przyjmują;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 17, 'Jednak nie mają w sobie korzenia, lecz trwają do czasu. Potem, gdy przychodzi ucisk albo prześladowanie z powodu słowa, zaraz się gorszą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 18, 'A ci, którzy zostali posiani między cierniami, są tymi, którzy słuchają słowa;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 19, 'Lecz troski tego świata, ułuda bogactwa i żądze innych rzeczy wchodzą i zagłuszają słowo, i staje się bezowocne.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 20, 'Ci zaś, którzy zostali posiani na dobrej ziemi, są tymi, którzy słuchają słowa, przyjmują je i przynoszą owoc: jedni trzydziestokrotny, inni sześćdziesięciokrotny, a jeszcze inni stokrotny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 21, 'Ponadto mówił im: Czy przynosi się świecę, aby wstawić ją pod naczynie albo pod łóżko? Czy nie po to, aby ją postawić na świeczniku?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 22, 'Nie ma bowiem nic tajemnego, co by nie miało być ujawnione ani nic ukrytego, co by nie miało wyjść na jaw.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 23, 'Jeśli ktoś ma uszy do słuchania, niech słucha.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 24, 'I powiedział do nich: Uważajcie na to, czego słuchacie. Jaką miarą mierzycie, taką będzie wam odmierzone, a wam, którzy słuchacie, zostanie jeszcze dodane.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 25, 'Kto bowiem ma, będzie mu dodane, a kto nie ma, zostanie mu zabrane nawet to, co ma.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 26, 'I mówił: Z królestwem Bożym jest tak, jak gdyby człowiek wrzucił ziarno w ziemię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 27, 'Czy śpi, czy wstaje, we dnie i w nocy, ziarno wschodzi i rośnie, a on nie wie jak.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 28, 'Bo ziemia sama z siebie wydaje plon, najpierw źdźbło, potem kłos, a potem pełne ziarno w kłosie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 29, 'A gdy plon dojrzeje, on zaraz zapuszcza sierp, bo nadeszło żniwo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 30, 'Powiedział jeszcze: Do czego przyrównamy królestwo Boże albo jaką przypowieścią je wyrazimy?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 31, 'Jest jak ziarno gorczycy, które, gdy zostaje wsiane w ziemię, jest najmniejsze ze wszystkich nasion na ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 32, 'Lecz wsiane wyrasta i staje się większe od wszystkich jarzyn, i wypuszcza wielkie gałęzie, tak że ptaki niebieskie mogą się gnieździć w jego cieniu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 33, 'I w wielu takich przypowieściach mówił im słowo, stosownie do tego, jak mogli słuchać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 34, 'A bez przypowieści nie mówił do nich. Na osobności zaś wykładał wszystko swoim uczniom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 35, 'Tego samego dnia, gdy nastał wieczór, powiedział do nich: Przeprawmy się na drugą stronę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 36, 'A gdy odprawili tłum, wzięli go ze sobą, tak jak był w łodzi. Towarzyszyły mu też inne łódki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 37, 'Wtedy zerwał się gwałtowny wicher i fale uderzały w łódź, tak że już się napełniała.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 38, 'A on spał w tyle łodzi na wezgłowiu. Obudzili go więc i mówili do niego: Nauczycielu, nie obchodzi cię, że giniemy?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 39, 'Wówczas wstał, zgromił wiatr i powiedział do morza: Milcz i uspokój się! I ustał wiatr, i nastała wielka cisza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 40, 'Wtedy powiedział do nich: Czemu się tak boicie? Jak to jest, że nie macie wiary?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 41, 'I ogarnął ich wielki strach, i mówili jeden do drugiego: Kim on jest, że nawet wiatr i morze są mu posłuszne?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 1, 'I przeprawili się za morze do krainy Gadareńczyków.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 2, 'A gdy on wyszedł z łodzi, zaraz wybiegł mu naprzeciw z grobowców człowiek mający ducha nieczystego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 3, 'Mieszkał on w grobowcach i nawet łańcuchami nikt nie mógł go związać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 4, 'Często bowiem był wiązany pętami i łańcuchami, ale rwał łańcuchy i kruszył pęta, i nikt nie mógł go poskromić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 5, 'A zawsze, we dnie i w nocy, przebywał w górach i grobowcach, krzycząc i tłukąc siebie kamieniami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 6, 'Gdy więc zobaczył Jezusa z daleka, przybiegł i oddał mu pokłon;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 7, 'A wołając donośnym głosem, powiedział: Cóż mam z tobą, Jezusie, Synu Boga najwyższego? Zaklinam cię na Boga, abyś mnie nie dręczył.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 8, 'Powiedział mu bowiem: Wyjdź, duchu nieczysty, z tego człowieka!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 9, 'I zapytał go: Jak ci na imię? A on odpowiedział: Na imię mi Legion, bo jest nas wielu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 10, 'I prosił go bardzo, aby nie wyganiał ich z tej krainy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 11, 'A pasło się tam w pobliżu góry wielkie stado świń.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 12, 'I wszystkie te demony prosiły go: Poślij nas w te świnie, abyśmy mogły w nie wejść.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 13, 'I Jezus zaraz im pozwolił. A duchy nieczyste, wyszedłszy, weszły w świnie. Wtedy stado, liczące około dwóch tysięcy, ruszyło pędem po urwisku do morza i utonęło w nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 14, 'Ci zaś, którzy paśli świnie, uciekli i opowiedzieli o tym w mieście i we wsiach. I wyszli ludzie, aby zobaczyć, co się stało.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 15, 'Przyszli więc do Jezusa i zobaczyli tego, który był opętany, w którym był legion demonów, jak siedział ubrany i przy zdrowych zmysłach. I bali się.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 16, 'A ci, którzy to widzieli, opowiedzieli im, co się stało z opętanym, a także o świniach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 17, 'Wtedy zaczęli go prosić, aby odszedł z ich granic.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 18, 'A gdy wsiadł do łodzi, prosił go ten, który był opętany, aby mógł przy nim zostać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 19, 'Lecz Jezus mu nie pozwolił, ale powiedział: Idź do domu, do swoich, i opowiedz im, jak wielkie rzeczy Pan ci uczynił i jak się nad tobą zmiłował.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 20, 'Odszedł więc i zaczął w Dekapolu opowiadać, jak wielkie rzeczy Jezus mu uczynił. I wszyscy się dziwili.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 21, 'A gdy Jezus przeprawił się z powrotem w łodzi na drugą stronę, zebrało się wokół niego mnóstwo ludzi. A on był nad morzem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 22, 'Wtedy przyszedł jeden z przełożonych synagogi, imieniem Jair, a gdy go zobaczył, padł mu do nóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 23, 'I prosił go usilnie: Moja córeczka umiera. Przyjdź, połóż na nią ręce, aby została uzdrowiona, a będzie żyła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 24, 'I poszedł z nim. Szło zaś za nim mnóstwo ludzi, którzy na niego napierali.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 25, 'Wtedy pewna kobieta, która od dwunastu lat cierpiała na upływ krwi;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 26, 'I wiele wycierpiała od licznych lekarzy, i wydała wszystko, co miała, a nic jej nie pomogło, przeciwnie, pogarszało jej się;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 27, 'Usłyszawszy o Jezusie, podeszła w tłumie od tyłu i dotknęła jego szaty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 28, 'Mówiła bowiem: Jeśli dotknę choćby jego szaty, będę zdrowa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 29, 'I natychmiast ustał jej upływ krwi, i poczuła w ciele, że została uzdrowiona ze swojej choroby.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 30, 'A Jezus od razu poznał, że wyszła z niego moc, odwrócił się do tłumu i zapytał: Kto dotknął moich szat?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 31, 'Odpowiedzieli mu jego uczniowie: Widzisz, że tłum na ciebie napiera, a pytasz: Kto mnie dotknął?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 32, 'I spojrzał wokoło, aby zobaczyć tę, która to uczyniła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 33, 'Wtedy kobieta ze strachem i z drżeniem, wiedząc, co się z nią stało, podeszła, upadła przed nim i wyznała mu całą prawdę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 34, 'A on powiedział do niej: Córko, twoja wiara cię uzdrowiła, idź w pokoju i bądź uzdrowiona ze swojej choroby.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 35, 'A gdy jeszcze mówił, przyszli ludzie od przełożonego synagogi i powiedzieli: Twoja córka umarła. Czemu jeszcze trudzisz Nauczyciela?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 36, 'Ale Jezus, gdy tylko usłyszał, co mówili, powiedział do przełożonego synagogi: Nie bój się, tylko wierz!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 37, 'I nie pozwolił iść za sobą nikomu oprócz Piotra, Jakuba i Jana, brata Jakuba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 38, 'A gdy przyszedł do domu przełożonego synagogi, zobaczył tam zamieszanie oraz płaczących i bardzo zawodzących.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 39, 'Wszedłszy więc, powiedział do nich: Dlaczego robicie zamieszanie i płaczecie? Dziewczynka nie umarła, tylko śpi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 40, 'I naśmiewali się z niego. Ale on wyrzucił wszystkich, wziął ze sobą ojca i matkę dziewczynki oraz tych, którzy przy nim byli, i wszedł tam, gdzie leżała dziewczynka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 41, 'Ujął dziewczynkę za rękę i powiedział do niej: Talitha kumi! – co się tłumaczy: Dziewczynko, mówię ci, wstań!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 42, 'I natychmiast dziewczynka wstała i chodziła, miała bowiem dwanaście lat. I ogarnęło ich wielkie zdumienie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 43, 'Wtedy przykazał im surowo, aby nikt się o tym nie dowiedział, i polecił, aby dano jej jeść.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 1, 'I wyszedłszy stamtąd, przyszedł w swoje rodzinne strony, a szli za nim jego uczniowie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 2, 'A gdy nadszedł szabat, zaczął nauczać w synagodze. Wielu zaś, słuchając go, zdumiewało się i pytało: Skąd on ma to wszystko? I co to za mądrość, która jest mu dana, że nawet takie cuda dzieją się przez jego ręce?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 3, 'Czy to nie jest cieśla, syn Marii, a brat Jakuba, Józefa, Judy i Szymona? Czyż nie ma tu wśród nas także jego sióstr? I gorszyli się z jego powodu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 4, 'Ale Jezus powiedział do nich: Nigdzie nie jest prorok bez czci, tylko w swojej ojczyźnie, wśród swoich krewnych i w swoim domu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 5, 'I nie mógł tam uczynić żadnego cudu oprócz tego, że uzdrowił niektórych chorych, kładąc na nich ręce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 6, 'I dziwił się ich niedowiarstwu. Potem obchodził okoliczne wioski, nauczając.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 7, 'Wtedy, przywoławszy do siebie dwunastu, zaczął ich rozsyłać po dwóch. Dał im też moc nad duchami nieczystymi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 8, 'I nakazał im, aby oprócz laski nie brali na drogę niczego: ani torby, ani chleba, ani pieniędzy w trzosie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 9, 'Lecz żeby założyli sandały i nie wkładali dwóch szat.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 10, 'Potem mówił do nich: Gdziekolwiek wejdziecie do jakiegoś domu, zostańcie tam, dopóki stamtąd nie odejdziecie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 11, 'A jeśli was ktoś nie przyjmie i nie usłucha, wyszedłszy stamtąd, strząśnijcie pył z waszych nóg na świadectwo przeciwko nim. Zaprawdę powiadam wam: Lżej będzie Sodomie i Gomorze w dzień sądu niż temu miastu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 12, 'Wtedy wyszli i głosili, że ludzie powinni pokutować.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 13, 'I wypędzali wiele demonów, i wielu chorych namaszczali olejkiem, i uzdrawiali.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 14, 'I usłyszał o nim król Herod (bo jego imię się rozsławiło), i powiedział: Jan Chrzciciel zmartwychwstał, dlatego cuda dokonują się przez niego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 15, 'A inni mówili: To Eliasz; jeszcze inni mówili: To prorok albo ktoś jak jeden z proroków.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 16, 'Gdy Herod o tym usłyszał, powiedział: To Jan, którego ściąłem. On zmartwychwstał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 17, 'Sam Herod bowiem kazał schwytać Jana i wtrącić go do więzienia z powodu Herodiady, żony swego brata Filipa, gdyż pojął ją za żonę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 18, 'Bo Jan mówił Herodowi: Nie wolno ci mieć żony swego brata.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 19, 'A Herodiada zawzięła się na niego i chciała go zabić, ale nie mogła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 20, 'Herod bowiem obawiał się Jana, wiedząc, że jest człowiekiem sprawiedliwym i świętym, i miał wzgląd na niego, a słuchając go, wiele czynił; i chętnie go słuchał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 21, 'A gdy nadeszła odpowiednia chwila, Herod, obchodząc dzień swoich urodzin, wyprawił ucztę dla swoich dostojników, dowódców wojskowych i znakomitości z Galilei.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 22, 'Kiedy córka tej Herodiady weszła i tańczyła, spodobała się Herodowi i współbiesiadnikom. Wtedy król powiedział do dziewczyny: Proś mnie, o co chcesz, a dam ci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 23, 'I przysiągł jej: O cokolwiek mnie poprosisz, dam ci, aż do połowy mego królestwa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 24, 'Ona więc wyszła i zapytała swoją matkę: O co mam prosić? A ta odpowiedziała: O głowę Jana Chrzciciela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 25, 'Natychmiast też weszła z pośpiechem do króla i prosiła: Chcę, żebyś mi zaraz dał na misie głowę Jana Chrzciciela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 26, 'I zasmucił się król bardzo, jednak ze względu na przysięgę i współbiesiadników nie chciał jej odmówić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 27, 'Król natychmiast posłał kata i rozkazał przynieść jego głowę. A ten, poszedłszy, ściął go w więzieniu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 28, 'Potem przyniósł na misie jego głowę i dał ją dziewczynie, a dziewczyna dała ją swojej matce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 29, 'Gdy usłyszeli o tym jego uczniowie, przyszli, zabrali jego ciało i złożyli w grobie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 30, 'A apostołowie zebrali się u Jezusa i opowiedzieli mu wszystko, co czynili i czego nauczali.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 31, 'I powiedział do nich: Pójdźcie wy na odludne miejsce i odpocznijcie trochę. Wielu bowiem przychodziło i odchodziło, tak że nie mieli wolnego czasu, żeby zjeść.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 32, 'I odpłynęli w łodzi na odludne miejsce, żeby być na osobności.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 33, 'A ludzie widzieli, że odpływają. Wielu go poznało i zbiegli się tam pieszo ze wszystkich miast, wyprzedzili ich i zgromadzili się przy nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 34, 'Kiedy Jezus wyszedł, zobaczył mnóstwo ludzi i ulitował się nad nimi, bo byli jak owce niemające pasterza. I zaczął nauczać ich wielu rzeczy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 35, 'A gdy było już późno, jego uczniowie podeszli do niego i powiedzieli: Miejsce to jest puste, a pora już późna.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 36, 'Odpraw ich, aby poszli do okolicznych osad i wsi i kupili sobie chleba, bo nie mają co jeść.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 37, 'Lecz on im odpowiedział: Wy dajcie im jeść. Zapytali go więc: Czy mamy pójść i za dwieście groszy kupić chleba, i dać im jeść?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 38, 'A on im powiedział: Ile macie chleba? Idźcie i zobaczcie. A oni, dowiedziawszy się, powiedzieli: Pięć i dwie ryby.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 39, 'Wtedy kazał im posadzić wszystkich w grupach na zielonej trawie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 40, 'I usiedli w grupach, po stu i po pięćdziesięciu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 41, 'A wziąwszy te pięć chlebów i dwie ryby, spojrzał w niebo i pobłogosławił. I połamał te chleby i dawał swoim uczniom, aby kładli przed nimi. Także te dwie ryby rozdzielił między wszystkich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 42, 'I jedli wszyscy do syta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 43, 'I zebrali dwanaście pełnych koszy kawałków i resztek z ryb.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 44, 'A tych, którzy jedli chleby, było około pięciu tysięcy mężczyzn.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 45, 'I zaraz przymusił swoich uczniów, aby wsiedli do łodzi i popłynęli przed nim na drugi brzeg w kierunku Betsaidy, a on tymczasem odprawi ludzi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 46, 'A gdy ich odprawił, odszedł na górę, aby się modlić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 47, 'Kiedy nastał wieczór, łódź znajdowała się na środku morza, a on był sam na lądzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 48, 'I widział, że są zmęczeni wiosłowaniem, bo wiatr mieli przeciwny. I tak około czwartej straży nocnej przyszedł do nich, idąc po morzu, i chciał ich wyminąć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 49, 'Ale oni, ujrzawszy go chodzącego po morzu, myśleli, że to zjawa, i krzyknęli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 50, 'Wszyscy bowiem go widzieli i przestraszyli się. Ale on zaraz przemówił do nich tymi słowami: Ufajcie, to ja jestem! Nie bójcie się!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 51, 'I wszedł do nich do łodzi, i uciszył się wiatr. A oni się bardzo zdumiewali i dziwili.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 52, 'Nie zrozumieli bowiem cudu z chlebami, gdyż ich serce było odrętwiałe.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 53, 'A przeprawiwszy się, przypłynęli do ziemi Genezaret i przybili do brzegu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 54, 'A gdy wyszli z łodzi, ludzie zaraz go poznali;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 55, 'Rozbiegli się po całej tej okolicy i zaczęli przynosić na posłaniach chorych tam, gdzie, jak słyszeli, przebywa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 56, 'A gdziekolwiek wszedł, do wsi, miast czy osad, kładli chorych na ulicach i prosili go, aby mogli dotknąć choćby brzegu jego szaty. A wszyscy, którzy go dotknęli, zostali uzdrowieni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 1, 'Wtedy zgromadzili się wokół niego faryzeusze i pewni uczeni w Piśmie, którzy przybyli z Jerozolimy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 2, 'A gdy zobaczyli, że niektórzy z jego uczniów jedzą chleb nieczystymi, to znaczy nieumytymi rękami, ganili to.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 3, 'Faryzeusze bowiem i wszyscy Żydzi, trzymając się tradycji starszych, nie jedzą, jeśli dokładnie nie umyją rąk.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 4, 'I po powrocie z rynku nie jedzą, jeśli się nie umyją. Jest jeszcze wiele innych zwyczajów, które przyjęli po to, by je zachowywać, jak obmywanie kubków, dzbanów, naczyń miedzianych i stołów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 5, 'Zapytali go więc faryzeusze i uczeni w Piśmie: Dlaczego twoi uczniowie nie postępują według tradycji starszych, lecz jedzą chleb nieumytymi rękami?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 6, 'Wtedy on im odpowiedział: Dobrze Izajasz prorokował o was, obłudnikach, jak jest napisane: Ten lud czci mnie wargami, ale ich serce daleko jest ode mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 7, 'Lecz na próżno mnie czczą, ucząc nauk, które są nakazami ludzkimi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 8, 'Wy bowiem, opuściwszy przykazania Boże, trzymacie się tradycji ludzkiej, obmywania dzbanków i kubków. I wiele innych tym podobnych rzeczy czynicie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 9, 'Mówił im też: Całkowicie znosicie przykazanie Boże, aby zachować swoją tradycję.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 10, 'Mojżesz bowiem powiedział: Czcij swego ojca i swoją matkę, oraz: Kto złorzeczy ojcu albo matce, niech poniesie śmierć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 11, 'Ale wy mówicie: Jeśli człowiek powie ojcu albo matce: To, co powinieneś otrzymać ode mnie jako pomoc, to Korban, to znaczy dar przeznaczony na ofiarę – będzie bez winy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 12, 'I nie pozwalacie mu nic więcej uczynić dla swego ojca albo matki;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 13, 'Wniwecz obracając słowo Boże przez waszą tradycję, którą przekazaliście. I wiele innych tym podobnych rzeczy czynicie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 14, 'A zwoławszy wszystkich ludzi, mówił do nich: Słuchajcie mnie wszyscy i zrozumiejcie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 15, 'Nie ma nic z zewnątrz, co wchodząc w człowieka, mogłoby go skalać, ale to, co z niego wychodzi, to kala człowieka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 16, 'Jeśli ktoś ma uszy do słuchania, niech słucha.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 17, 'A gdy oddalił się od ludzi i wszedł do domu, jego uczniowie pytali go o tę przypowieść.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 18, 'Wtedy powiedział im: Czy i wy jesteście tak bezrozumni? Czyż nie rozumiecie, że wszystko, co z zewnątrz wchodzi w człowieka, nie może go skalać?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 19, 'Nie wchodzi bowiem do jego serca, ale do żołądka i zostaje wydalone do ustępu, oczyszczając wszystkie pokarmy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 20, 'I powiedział: Co wychodzi z człowieka, to kala człowieka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 21, 'Z wnętrza bowiem, z serca ludzkiego pochodzą złe myśli, cudzołóstwa, nierząd, zabójstwa;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 22, 'Kradzieże, chciwość, niegodziwość, podstęp, wyuzdanie, oko złe, bluźnierstwo, pycha, głupota.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 23, 'Całe to zło pochodzi z wnętrza i kala człowieka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 24, 'Odszedł stamtąd i udał się w okolice Tyru i Sydonu. A wszedłszy do pewnego domu, nie chciał, aby ktoś o tym wiedział. Nie mógł się jednak ukryć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 25, 'Usłyszała bowiem o nim kobieta, której córeczka miała ducha nieczystego, i przyszła, i upadła mu do nóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 26, 'A kobieta ta była Greczynką, rodem z Syrofenicji, i prosiła go, aby wypędził demona z jej córki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 27, 'Ale Jezus jej powiedział: Niech najpierw nasycą się dzieci, bo niedobrze jest brać chleb dzieci i rzucać szczeniętom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 28, 'A ona odpowiedziała mu: Tak, Panie, lecz i szczenięta jadają pod stołem z okruszyn dzieci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 29, 'I powiedział do niej: Ze względu na te słowa idź, demon wyszedł z twojej córki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 30, 'A gdy wróciła do swego domu, spostrzegła, że demon wyszedł, a córka leżała na łóżku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 31, 'Kiedy znowu opuścił okolice Tyru i Sydonu, przyszedł nad Morze Galilejskie przez środek krainy Dekapolu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 32, 'I przyprowadzili do niego głuchego, który miał trudności z mówieniem, i prosili go, aby położył na niego rękę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 33, 'Pan, wziąwszy go z tłumu na bok, włożył palce w jego uszy i splunąwszy, dotknął jego języka;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 34, 'A spojrzawszy w niebo, westchnął i powiedział do niego: Effatha, to znaczy: Otwórz się.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 35, 'Zaraz też otworzyły się jego uszy i rozwiązały się więzy jego języka, i mówił poprawnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 36, 'Wtedy im nakazał, aby tego nikomu nie mówili. Ale im bardziej im nakazywał, tym bardziej to rozgłaszali.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 37, 'I niezmiernie się zdumiewali, mówiąc: Dobrze wszystko uczynił. Sprawia, że głusi słyszą i niemi mówią.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 1, 'A w tych dniach, gdy było z nim bardzo wielu ludzi i nie mieli co jeść, Jezus przywołał swoich uczniów i powiedział do nich:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 2, 'Żal mi tych ludzi, bo już trzy dni przy mnie trwają, a nie mają co jeść.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 3, 'A jeśli odprawię ich głodnych do domów, zasłabną w drodze, bo niektórzy z nich przyszli z daleka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 4, 'Wtedy jego uczniowie odpowiedzieli mu: Skąd tu na pustyni będzie ktoś mógł nakarmić ich chlebem?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 5, 'I zapytał ich: Ile macie chlebów? A oni odpowiedzieli: Siedem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 6, 'Wtedy nakazał ludziom usiąść na ziemi. I wziął te siedem chlebów, a podziękowawszy, łamał i dawał swoim uczniom, aby kładli przed nimi. I kładli przed ludźmi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 7, 'Mieli też kilka rybek, które pobłogosławiwszy, również kazał kłaść przed ludźmi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 8, 'Jedli więc do syta, a pozostałych kawałków zebrali siedem koszy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 9, 'A tych, którzy jedli, było około czterech tysięcy. Potem ich odprawił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 10, 'Zaraz też wsiadł do łodzi ze swoimi uczniami i przybył w okolice Dalmanuty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 11, 'Wtedy nadeszli faryzeusze i zaczęli z nim rozprawiać, a wystawiając go na próbę, żądali od niego znaku z nieba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 12, 'On zaś, westchnąwszy głęboko w duchu, powiedział: Dlaczego to pokolenie żąda znaku? Zaprawdę powiadam wam, że żaden znak nie będzie dany temu pokoleniu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 13, 'I opuściwszy ich, ponownie wsiadł do łodzi i przeprawił się na drugą stronę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 14, 'A uczniowie zapomnieli wziąć chleba i nie mieli ze sobą w łodzi nic więcej oprócz jednego bochenka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 15, 'Wtedy przykazał im: Uważajcie i strzeżcie się zakwasu faryzeuszy i zakwasu Heroda.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 16, 'I rozmawiali między sobą: Powiedział tak, bo nie mamy chleba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 17, 'Jezus, poznawszy to, powiedział do nich: Czemu rozmawiacie o tym, że nie macie chleba? Jeszcze nie pojmujecie i nie rozumiecie? Jeszcze wasze serce jest odrętwiałe?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 18, 'Macie oczy, a nie widzicie, i macie uszy, a nie słyszycie? I nie pamiętacie?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 19, 'Gdy łamałem tych pięć chlebów dla pięciu tysięcy ludzi, ile pełnych koszy kawałków zebraliście? Odpowiedzieli mu: Dwanaście.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 20, 'A gdy łamałem tych siedem chlebów dla czterech tysięcy ludzi, ile pełnych koszy kawałków zebraliście? A oni odpowiedzieli: Siedem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 21, 'I zapytał ich: Jakże więc nie rozumiecie?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 22, 'Potem przyszedł do Betsaidy. I przyprowadzili do niego ślepego, prosząc go, aby go dotknął.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 23, 'A ująwszy ślepego za rękę, wyprowadził go poza miasteczko i plunąwszy na jego oczy, położył na niego ręce i zapytał, czy coś widzi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 24, 'A on spojrzał w górę i powiedział: Widzę chodzących ludzi, jakby drzewa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 25, 'Potem znowu położył ręce na jego oczy i kazał mu spojrzeć w górę. I został uzdrowiony, tak że nawet z daleka widział wszystkich wyraźnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 26, 'I odesłał go do domu, mówiąc: Nie wchodź do tego miasteczka i nikomu z miasteczka o tym nie mów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 27, 'Wtedy Jezus poszedł ze swymi uczniami do wiosek należących do Cezarei Filipowej, a w drodze pytał swoich uczniów: Za kogo mnie ludzie uważają?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 28, 'A oni mu odpowiedzieli: Jedni za Jana Chrzciciela, inni za Eliasza, a jeszcze inni za jednego z proroków.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 29, 'Wtedy zapytał ich: A wy za kogo mnie uważacie? A Piotr mu odpowiedział: Ty jesteś Chrystusem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 30, 'I przykazał im, aby nikomu o nim nie mówili.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 31, 'I zaczął ich nauczać, że Syn Człowieczy musi wiele cierpieć i zostać odrzucony przez starszych, naczelnych kapłanów i uczonych w Piśmie, i być zabity, a po trzech dniach zmartwychwstać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 32, 'A mówił to otwarcie. Wtedy Piotr, wziąwszy go na bok, zaczął go strofować.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 33, 'Lecz on odwrócił się, spojrzał na swoich uczniów i zgromił Piotra, mówiąc: Odejdź ode mnie, szatanie, bo nie pojmujesz tego, co Boże, ale to, co ludzkie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 34, 'Potem przywołał do siebie lud wraz ze swoimi uczniami i powiedział do nich: Ktokolwiek chce pójść za mną, niech się zaprze samego siebie, weźmie swój krzyż i idzie za mną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 35, 'Bo kto chce zachować swoje życie, straci je, a kto straci swoje życie z mojego powodu i dla ewangelii, ten je zachowa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 36, 'Cóż pomoże człowiekowi, choćby cały świat pozyskał, a na swojej duszy poniósł szkodę?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 37, 'Albo co da człowiek w zamian za swoją duszę?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 38, 'Kto się bowiem wstydzi mnie i moich słów wobec tego pokolenia cudzołożnego i grzesznego, tego i Syn Człowieczy będzie się wstydził, gdy przyjdzie w chwale swego Ojca ze świętymi aniołami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 1, 'I mówił im: Zaprawdę powiadam wam, że niektórzy z tych, co tu stoją, nie zakosztują śmierci, aż ujrzą królestwo Boże przychodzące w mocy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 2, 'A po sześciu dniach Jezus wziął ze sobą Piotra, Jakuba i Jana i wprowadził ich samych na wysoką górę, żeby byli na osobności. I przemienił się przed nimi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 3, 'A jego szaty stały się lśniące i bardzo białe, jak śnieg, jak żaden folusznik na ziemi nie potrafi wybielić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 4, 'I ukazał się im Eliasz z Mojżeszem, którzy rozmawiali z Jezusem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 5, 'Wtedy Piotr powiedział do Jezusa: Mistrzu, dobrze nam tu być. Postawmy więc trzy namioty: jeden dla ciebie, jeden dla Mojżesza i jeden dla Eliasza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 6, 'Nie wiedział bowiem, co ma powiedzieć, gdyż byli przestraszeni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 7, 'I pojawił się obłok, który ich zacienił, a z obłoku rozległ się głos: To jest mój umiłowany Syn, jego słuchajcie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 8, 'A nagle, gdy się rozejrzeli, nikogo już nie widzieli obok siebie, tylko samego Jezusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 9, 'A gdy schodzili z góry, przykazał im, aby nikomu nie mówili o tym, co widzieli, aż Syn Człowieczy powstanie z martwych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 10, 'I zachowali te słowa dla siebie, rozprawiając między sobą, co znaczy powstać z martwych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 11, 'I pytali go: Dlaczego uczeni w Piśmie mówią, że najpierw ma przyjść Eliasz?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 12, 'A on im odpowiedział: Istotnie, najpierw przyjdzie Eliasz i wszystko odnowi, a jak jest napisane o Synu Człowieczym, że musi wiele cierpieć i za nic być poczytany.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 13, 'Ale mówię wam, że Eliasz już przyszedł i zrobili z nim, co chcieli, jak jest o nim napisane.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 14, 'A przyszedłszy do uczniów, zobaczył wielki tłum wokół nich oraz uczonych w Piśmie, którzy rozprawiali z nimi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 15, 'Wszyscy ludzie, gdy tylko go zobaczyli, zdumieli się i przybiegłszy, witali go.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 16, 'I zapytał uczonych w Piśmie: O czym rozprawiacie z nimi?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 17, 'A jeden z tłumu odpowiedział: Nauczycielu, przyprowadziłem do ciebie mego syna, który ma ducha niemego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 18, 'Ten, gdziekolwiek go chwyci, szarpie nim, a on się pieni, zgrzyta zębami i schnie. I mówiłem twoim uczniom, aby go wypędzili, ale nie mogli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 19, 'A on mu odpowiedział: O pokolenie bez wiary! Jak długo będę z wami? Jak długo mam was znosić? Przyprowadźcie go do mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 20, 'I przyprowadzili go do niego. A gdy tylko go zobaczył, zaraz duch nim szarpnął, a on upadł na ziemię i tarzał się z pianą na ustach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 21, 'Jezus zapytał jego ojca: Od jak dawna mu się to zdarza? A on odpowiedział: Od dzieciństwa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 22, 'I często wrzucał go w ogień i w wodę, żeby go zgubić. Ale jeśli możesz coś zrobić, zlituj się nad nami i pomóż nam.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 23, 'Jezus mu powiedział: Jeśli możesz wierzyć. Wszystko jest możliwe dla tego, kto wierzy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 24, 'I natychmiast ojciec tego chłopca zawołał ze łzami: Wierzę, Panie! Pomóż mojej niewierze!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 25, 'A Jezus, widząc, że ludzie się zbiegają, zgromił ducha nieczystego, mówiąc: Duchu niemy i głuchy! Rozkazuję ci, wyjdź z niego i więcej w niego nie wchodź.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 26, 'Wtedy duch krzyknął i szarpiąc nim gwałtownie, wyszedł. A chłopiec wyglądał jak martwy, tak że wielu mówiło, iż umarł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 27, 'Lecz Jezus ujął go za rękę i podniósł, a on wstał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 28, 'A gdy wszedł do domu, jego uczniowie pytali go na osobności: Czemu my nie mogliśmy go wypędzić?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 29, 'I odpowiedział im: Ten rodzaj demonów nie wychodzi inaczej, jak tylko przez modlitwę i post.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 30, 'A wyszedłszy stamtąd, przechodzili przez Galileę. On jednak nie chciał, aby ktoś o tym wiedział.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 31, 'Nauczał bowiem swoich uczniów i mówił im: Syn Człowieczy będzie wydany w ręce ludzi i zabiją go, ale gdy będzie zabity, trzeciego dnia zmartwychwstanie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 32, 'Oni jednak nie rozumieli tych słów, a bali się go zapytać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 33, 'I przyszedł do Kafarnaum. A gdy był w domu, zapytał ich: O czym rozmawialiście między sobą w drodze?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 34, 'Lecz oni milczeli. W drodze bowiem rozmawiali między sobą o tym, kto z nich jest największy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 35, 'A usiadłszy, zawołał dwunastu i powiedział im: Jeśli ktoś chce być pierwszy, niech będzie ostatnim ze wszystkich i sługą wszystkich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 36, 'I wziął dziecko, postawił je pośrodku nich, a wziąwszy je na ręce, powiedział do nich:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 37, 'Kto przyjmie jedno z takich dzieci w moje imię, mnie przyjmuje, a kto mnie przyjmie, nie mnie przyjmuje, ale tego, który mnie posłał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 38, 'Wtedy Jan powiedział do niego: Nauczycielu, widzieliśmy kogoś, kto w twoim imieniu wypędzał demony, a nie chodzi z nami. Zabranialiśmy mu więc, bo nie chodzi z nami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 39, 'Ale Jezus powiedział: Nie zabraniajcie mu. Nie ma bowiem nikogo, kto czyniłby cuda w moim imieniu i mógł tak łatwo źle o mnie mówić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 40, 'Bo kto nie jest przeciwko nam, ten jest z nami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 41, 'Kto bowiem poda wam kubek wody w moje imię, dlatego że należycie do Chrystusa, zaprawdę powiadam wam, nie straci swojej nagrody.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 42, 'A kto zgorszy jednego z tych małych, którzy we mnie wierzą, o wiele lepiej byłoby dla niego, gdyby zawieszono mu u szyi kamień młyński i wrzucono go do morza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 43, 'Jeśli twoja ręka jest ci powodem upadku, odetnij ją. Lepiej bowiem jest dla ciebie ułomnym wejść do życia, niż mając dwie ręce, pójść do piekła, w ogień nieugaszony;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 44, 'Gdzie robak ich nie umiera, a ogień nie gaśnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 45, 'A jeśli twoja noga jest ci powodem upadku, odetnij ją. Lepiej bowiem jest dla ciebie chromym wejść do życia, niż mając dwie nogi, zostać wrzuconym do piekła, w ogień nieugaszony;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 46, 'Gdzie robak ich nie umiera, a ogień nie gaśnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 47, 'Jeśli zaś twoje oko jest ci powodem upadku, wyłup je. Lepiej bowiem jest dla ciebie jednookim wejść do królestwa Bożego, niż mając dwoje oczu, zostać wrzuconym do ognia piekielnego;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 48, 'Gdzie robak ich nie umiera, a ogień nie gaśnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 49, 'Każdy bowiem ogniem będzie posolony i każda ofiara solą będzie posolona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 50, 'Dobra jest sól. Lecz jeśli sól przestanie być słona, czymże ją przyprawicie? Miejcie sól w samych sobie i zachowujcie pokój między sobą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 1, 'Potem wyruszył stamtąd i przyszedł w granice Judei przez krainę leżącą za Jordanem; i ponownie zeszli się do niego ludzie, i znowu ich nauczał, jak miał w zwyczaju.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 2, 'Wtedy faryzeusze podeszli i pytali go: Czy wolno mężowi oddalić żonę? A robili to, wystawiając go na próbę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 3, 'Lecz on im odpowiedział: Co wam nakazał Mojżesz?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 4, 'A oni powiedzieli: Mojżesz pozwolił napisać list rozwodowy i oddalić ją.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 5, 'Jezus odpowiedział im: Z powodu zatwardziałości waszego serca napisał wam to przykazanie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 6, 'Lecz od początku stworzenia Bóg uczynił ich mężczyzną i kobietą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 7, 'Dlatego opuści mężczyzna swego ojca i matkę i połączy się ze swoją żoną;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 8, 'I będą dwoje jednym ciałem. A tak już nie są dwoje, ale jedno ciało.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 9, 'Co więc Bóg złączył, człowiek niech nie rozłącza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 10, 'A w domu jego uczniowie znowu go o to pytali.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 11, 'I powiedział im: Kto oddala swą żonę i żeni się z inną, cudzołoży wobec niej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 12, 'A jeśli kobieta opuści swego męża i wyjdzie za innego, cudzołoży.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 13, 'I przynoszono do niego dzieci, aby ich dotknął, ale uczniowie gromili tych, którzy je przynosili.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 14, 'Gdy Jezus to zobaczył, oburzył się i powiedział do nich: Pozwólcie dzieciom przychodzić do mnie i nie zabraniajcie im. Do takich bowiem należy królestwo Boże.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 15, 'Zaprawdę powiadam wam: Kto nie przyjmie królestwa Bożego jak dziecko, nie wejdzie do niego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 16, 'I brał je na ręce, a kładąc na nie ręce, błogosławił je.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 17, 'A gdy wyruszał w drogę, przybiegł pewien człowiek, upadł przed nim na kolana i zapytał: Nauczycielu dobry, co mam czynić, aby odziedziczyć życie wieczne?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 18, 'Lecz Jezus mu odpowiedział: Dlaczego nazywasz mnie dobrym? Nikt nie jest dobry, tylko jeden – Bóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 19, 'Znasz przykazania: Nie będziesz cudzołożył, nie będziesz zabijał, nie będziesz kradł, nie będziesz mówił fałszywego świadectwa, nie będziesz oszukiwał, czcij swego ojca i matkę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 20, 'A on mu odpowiedział: Nauczycielu, tego wszystkiego przestrzegałem od mojej młodości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 21, 'Wtedy Jezus, spojrzawszy na niego, umiłował go i powiedział: Jednego ci brakuje. Idź, sprzedaj wszystko, co masz i rozdaj ubogim, a będziesz miał skarb w niebie. Potem przyjdź, weź krzyż i chodź za mną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 22, 'Lecz on zmartwił się z powodu tych słów i odszedł smutny, miał bowiem wiele dóbr.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 23, 'A Jezus, spojrzawszy wokoło, powiedział do swoich uczniów: Jakże trudno tym, którzy mają bogactwa, wejść do królestwa Bożego!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 24, 'I uczniowie zdumieli się jego słowami. Lecz Jezus znowu powiedział: Dzieci, jakże trudno jest tym, którzy ufają bogactwom, wejść do królestwa Bożego!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 25, 'Łatwiej jest wielbłądowi przejść przez ucho igielne, niż bogatemu wejść do królestwa Bożego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 26, 'A oni tym bardziej się zdumiewali i mówili między sobą: Któż więc może być zbawiony?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 27, 'A Jezus, spojrzawszy na nich, powiedział: U ludzi to niemożliwe, ale nie u Boga. U Boga bowiem wszystko jest możliwe.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 28, 'Wtedy Piotr zaczął mówić do niego: Oto my opuściliśmy wszystko i poszliśmy za tobą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 29, 'A Jezus odpowiedział: Zaprawdę powiadam wam: Nie ma nikogo, kto by opuścił dom, braci lub siostry, ojca lub matkę, żonę, dzieci lub pole ze względu na mnie i na ewangelię;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 30, 'A kto by nie otrzymał stokrotnie więcej teraz, w tym czasie, domów, braci, sióstr, matek, dzieci i pól, wśród prześladowań, a w przyszłym świecie życia wiecznego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 31, 'Ale wielu pierwszych będzie ostatnimi, a ostatnich pierwszymi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 32, 'I byli w drodze, zdążając do Jerozolimy, a Jezus szedł przed nimi. I zdumiewali się, a idąc za nim, bali się. On zaś znowu wziął ze sobą dwunastu i zaczął im mówić o tym, co miało go spotkać:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 33, 'Oto idziemy do Jerozolimy, a Syn Człowieczy zostanie wydany naczelnym kapłanom i uczonym w Piśmie. Oni skażą go na śmierć i wydadzą poganom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 34, 'I będą się z niego naśmiewać, ubiczują go, będą na niego pluć i zabiją go, ale trzeciego dnia zmartwychwstanie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 35, 'Wtedy podeszli do niego Jakub i Jan, synowie Zebedeusza, i powiedzieli: Nauczycielu, chcemy, żebyś zrobił dla nas to, o co cię poprosimy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 36, 'A on ich zapytał: Co chcecie, żebym dla was zrobił?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 37, 'Odpowiedzieli mu: Spraw, abyśmy siedzieli jeden po twojej prawej, a drugi po lewej stronie w twojej chwale.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 38, 'Lecz Jezus im powiedział: Nie wiecie, o co prosicie. Czy możecie pić kielich, który ja piję, i być ochrzczeni chrztem, którym ja się chrzczę?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 39, 'Odpowiedzieli mu: Możemy. A Jezus im powiedział: Istotnie, kielich, który ja piję, będziecie pić i chrztem, którym ja się chrzczę, będziecie ochrzczeni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 40, 'Nie do mnie jednak należy danie miejsca po mojej prawej albo lewej stronie, ale będzie dane tym, którym zostało przygotowane.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 41, 'A gdy dziesięciu to usłyszało, zaczęli się oburzać na Jakuba i Jana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 42, 'Ale Jezus przywołał ich do siebie i powiedział: Wiecie, że ci, którzy uchodzą za władców narodów, panują nad nimi, a ich wielcy sprawują nad nimi swą władzę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 43, 'Lecz nie tak ma być wśród was, ale kto między wami chce być wielki, niech będzie waszym sługą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 44, 'A kto z was chce być pierwszy, niech będzie sługą wszystkich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 45, 'Bo i Syn Człowieczy nie przyszedł, aby mu służono, ale aby służyć i aby dać swe życie na okup za wielu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 46, 'I przyszli do Jerycha. A gdy on wychodził z Jerycha ze swoimi uczniami oraz mnóstwem ludzi, ślepy Bartymeusz, syn Tymeusza, siedział przy drodze, żebrząc.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 47, 'A słysząc, że to Jezus z Nazaretu, zaczął wołać: Jezusie, Synu Dawida, zmiłuj się nade mną!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 48, 'I wielu nakazywało mu milczeć. Lecz on tym głośniej wołał: Synu Dawida, zmiłuj się nade mną!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 49, 'Wtedy Jezus zatrzymał się i kazał go zawołać. Zawołali więc ślepego i powiedzieli do niego: Ufaj! Wstań, woła cię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 50, 'A on zrzucił swój płaszcz, wstał i przyszedł do Jezusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 51, 'I zapytał go Jezus: Co chcesz, abym ci uczynił? Ślepiec mu odpowiedział: Mistrzu, żebym widział.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 52, 'A Jezus mu powiedział: Idź, twoja wiara cię uzdrowiła. Zaraz też odzyskał wzrok i szedł drogą za Jezusem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 1, 'A gdy zbliżyli się do Jerozolimy i przyszli do Betfage i Betanii przy Górze Oliwnej, posłał dwóch spośród swoich uczniów;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 2, 'I powiedział im: Idźcie do wsi, która jest przed wami, a zaraz po wejściu do niej znajdziecie uwiązane oślątko, na którym nie siedział jeszcze nikt z ludzi. Odwiążcie je i przyprowadźcie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 3, 'A gdyby ktoś was zapytał: Co robicie? – powiedzcie, że Pan go potrzebuje i zaraz je tu przyśle.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 4, 'Poszli więc i znaleźli oślątko uwiązane u drzwi na dworze, na rozstaju dróg, i odwiązali je.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 5, 'Wtedy niektórzy ze stojących tam pytali: Co robicie? Dlaczego odwiązujecie oślątko?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 6, 'A oni odpowiedzieli im tak, jak im nakazał Jezus. I puścili ich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 7, 'Przyprowadzili więc oślątko do Jezusa i włożyli na nie swoje szaty, a on wsiadł na nie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 8, 'Wielu zaś słało na drodze swoje szaty, a inni obcinali gałązki z drzew i kładli na drodze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 9, 'A ci, którzy szli przed nim i którzy podążali za nim, wołali: Hosanna! Błogosławiony, który przychodzi w imieniu Pana!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 10, 'Błogosławione królestwo naszego ojca Dawida, które przychodzi w imieniu Pana! Hosanna na wysokościach!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 11, 'I wjechał Jezus do Jerozolimy i wszedł do świątyni, a gdy obejrzał wszystko i nadszedł już wieczór, wyszedł z dwunastoma do Betanii.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 12, 'A nazajutrz, gdy wyszli z Betanii, poczuł głód.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 13, 'I widząc z daleka drzewo figowe pokryte liśćmi, podszedł, by zobaczyć, czy może czegoś na nim nie znajdzie. Lecz gdy się do niego zbliżył, nie znalazł nic oprócz liści, bo nie był to czas na figi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 14, 'Wtedy Jezus powiedział do niego: Niech już nikt nigdy nie je z ciebie owocu. A słyszeli to jego uczniowie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 15, 'I przyszli do Jerozolimy. A gdy Jezus wszedł do świątyni, zaczął wyganiać sprzedających i kupujących w świątyni oraz poprzewracał stoły wymieniających pieniądze i stołki sprzedających gołębie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 16, 'Nie pozwolił też, żeby ktoś jakiekolwiek naczynie przeniósł przez świątynię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 17, 'I nauczał ich, mówiąc: Czyż nie jest napisane: Mój dom będzie nazwany domem modlitwy dla wszystkich narodów? Lecz wy zrobiliście z niego jaskinię zbójców.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 18, 'A słyszeli to uczeni w Piśmie i naczelni kapłani i szukali sposobu, jak by go zgładzić. Bali się go bowiem, dlatego że cały lud zdumiewał się jego nauką.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 19, 'A gdy nastał wieczór, wyszedł z miasta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 20, 'A rano, przechodząc, zobaczyli, że drzewo figowe uschło od korzeni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 21, 'Wtedy Piotr przypomniał sobie o tym i powiedział do niego: Mistrzu, drzewo figowe, które przekląłeś, uschło.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 22, 'A Jezus odpowiedział im: Miejcie wiarę w Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 23, 'Bo zaprawdę powiadam wam, że kto powie tej górze: Podnieś się i rzuć się w morze, a nie zwątpi w swoim sercu, lecz będzie wierzył, że stanie się to, co mówi – spełni się mu, cokolwiek powie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 24, 'Dlatego mówię wam: O cokolwiek prosicie w modlitwie, wierzcie, że otrzymacie, a stanie się wam.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 25, 'A gdy stoicie, modląc się, przebaczcie, jeśli macie coś przeciwko komuś, aby i wasz Ojciec, który jest w niebie, przebaczył wam wasze przewinienia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 26, 'Bo jeśli wy nie przebaczycie, to i wasz Ojciec, który jest w niebie, nie przebaczy wam waszych przewinień.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 27, 'I znowu przyszli do Jerozolimy. A gdy się przechadzał po świątyni, podeszli do niego naczelni kapłani, uczeni w Piśmie i starsi;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 28, 'I zapytali: Jakim prawem to czynisz? I kto dał ci władzę, żeby to czynić?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 29, 'Wtedy Jezus im odpowiedział: Spytam was i ja o pewną rzecz. Odpowiedzcie mi, a powiem, jakim prawem to czynię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 30, 'Czy chrzest Jana pochodził z nieba czy od ludzi? Odpowiedzcie mi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 31, 'I rozważali to między sobą, mówiąc: Jeśli powiemy, że z nieba, zapyta: Dlaczego więc mu nie uwierzyliście?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 32, 'A jeśli powiemy, że od ludzi – boimy się ludu. Wszyscy bowiem uważali Jana za prawdziwego proroka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 33, 'Odpowiedzieli więc Jezusowi: Nie wiemy. Jezus im odpowiedział: I ja wam nie powiem, jakim prawem to czynię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 1, 'Wtedy zaczął do nich mówić w przypowieściach: Pewien człowiek założył winnicę, ogrodził ją płotem, wykopał prasę, zbudował wieżę i wydzierżawił ją rolnikom, i wyjechał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 2, 'A gdy nadszedł czas, posłał do rolników sługę, aby odebrał od nich plony winnicy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 3, 'Lecz oni schwytali go, pobili i odesłali z niczym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 4, 'I znowu posłał do nich innego sługę, którego ukamienowali, zranili w głowę i odesłali znieważonego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 5, 'Ponownie posłał innego sługę, lecz i tego zabili. I wielu innych, z których jednych pobili, a innych pozabijali.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 6, 'A mając jeszcze jednego, swego umiłowanego syna, posłał do nich na koniec i jego, mówiąc: Uszanują mego syna.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 7, 'Ale rolnicy mówili między sobą: To jest dziedzic. Chodźmy, zabijmy go, a dziedzictwo będzie nasze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 8, 'I schwytawszy go, zabili i wyrzucili z winnicy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 9, 'Cóż więc zrobi pan winnicy? Przyjdzie i wytraci tych rolników, a winnicę odda innym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 10, 'Czy nie czytaliście tych słów Pisma: Kamień, który odrzucili budujący, stał się kamieniem węgielnym;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 11, 'Pan to sprawił i jest to cudowne w naszych oczach?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 12, 'Starali się więc go schwytać, ale bali się ludu. Wiedzieli bowiem, że przeciwko nim powiedział tę przypowieść. Zostawili go więc i odeszli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 13, 'Potem posłali do niego niektórych z faryzeuszy i herodianów, aby go pochwycili w mowie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 14, 'Gdy przyszli, powiedzieli mu: Nauczycielu, wiemy, że jesteś prawdziwy i nie zważasz na nikogo. Nie oglądasz się bowiem na osobę ludzką, ale drogi Bożej w prawdzie uczysz. Czy wolno płacić podatek cesarzowi, czy nie? Mamy go płacić czy nie płacić?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 15, 'A on poznał ich obłudę i powiedział do nich: Czemu wystawiacie mnie na próbę? Przynieście mi grosz, żebym mógł go zobaczyć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 16, 'I przynieśli mu. A on ich zapytał: Czyj to wizerunek i napis? Odpowiedzieli mu: Cesarza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 17, 'Wtedy Jezus im powiedział: Oddawajcie więc cesarzowi to, co należy do cesarza, a co należy do Boga – Bogu. I podziwiali go.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 18, 'Potem przyszli do niego saduceusze, którzy mówią, że nie ma zmartwychwstania, i pytali go:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 19, 'Nauczycielu, Mojżesz nam napisał, że jeśli czyjś brat umrze i pozostawi żonę, a nie pozostawi dzieci, to jego brat ma ożenić się z jego żoną i wzbudzić potomstwo swemu bratu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 20, 'Otóż było siedmiu braci. Pierwszy ożenił się i umarł, nie zostawiwszy potomstwa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 21, 'Potem ożenił się z nią drugi i umarł, lecz i ten nie zostawił potomstwa, tak samo trzeci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 22, 'I tak pojęło ją siedmiu braci, ale nie zostawili potomstwa. Na koniec, po wszystkich umarła i ta kobieta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 23, 'Przy zmartwychwstaniu więc, gdy powstaną, którego z nich będzie żoną? Bo siedmiu miało ją za żonę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 24, 'Na to Jezus im odpowiedział: Czyż nie dlatego błądzicie, że nie znacie Pisma ani mocy Boga?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 25, 'Gdy bowiem zmartwychwstaną, ani się żenić nie będą, ani za mąż wychodzić, ale będą jak aniołowie w niebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 26, 'A o umarłych, że będą wskrzeszeni, nie czytaliście w księdze Mojżesza, jak Bóg do niego z krzaka przemówił: Ja jestem Bogiem Abrahama, Bogiem Izaaka i Bogiem Jakuba?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 27, 'Bóg nie jest Bogiem umarłych, ale Bogiem żywych. Wy więc bardzo błądzicie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 28, 'Podszedł jeden z uczonych w Piśmie i słysząc, że ze sobą rozmawiali oraz widząc, że im dobrze odpowiedział, zapytał go: Które przykazanie jest pierwsze ze wszystkich?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 29, 'A Jezus mu odpowiedział: Pierwsze przykazanie ze wszystkich jest to: Słuchaj, Izraelu! Pan, nasz Bóg, Pan jest jeden.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 30, 'Będziesz więc miłował Pana, swego Boga, całym swym sercem, całą swą duszą, całym swym umysłem i z całej swojej siły. To jest pierwsze przykazanie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 31, 'A drugie jest do niego podobne: Będziesz miłował swego bliźniego jak samego siebie. Nie ma innego przykazania większego od tych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 32, 'Wtedy powiedział mu uczony w Piśmie: Nauczycielu, zaprawdę dobrze powiedziałeś, że jeden jest Bóg i nie ma innego oprócz niego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 33, 'Miłować go całym sercem, całym umysłem, całą duszą i z całej siły i miłować bliźniego jak samego siebie znaczy więcej niż wszystkie całopalenia i ofiary.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 34, 'A Jezus, widząc, że mądrze odpowiedział, rzekł do niego: Niedaleko jesteś od królestwa Bożego. I nikt nie śmiał go więcej pytać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 35, 'Nauczając w świątyni, Jezus zapytał: Jak to jest, że uczeni w Piśmie mówią, że Chrystus jest Synem Dawida?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 36, 'Sam Dawid bowiem powiedział przez Ducha Świętego: Rzekł Pan memu Panu: Siądź po mojej prawicy, aż położę twoich nieprzyjaciół jako podnóżek pod twoje stopy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 37, 'Skoro sam Dawid nazywa go Panem, to jak może być jego synem? A wielki tłum chętnie go słuchał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 38, 'I mówił do nich w swoim nauczaniu: Strzeżcie się uczonych w Piśmie, którzy lubią chodzić w długich szatach i lubią pozdrowienia na rynkach;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 39, 'I pierwsze krzesła w synagogach, i pierwsze miejsca na ucztach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 40, 'Pożerają oni domy wdów i dla pozoru odprawiają długie modlitwy. Ci otrzymają surowszy wyrok.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 41, 'A siedząc naprzeciw skarbony, Jezus przypatrywał się, jak ludzie wrzucali do niej pieniądze. Wielu bogaczy wrzucało wiele.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 42, 'Przyszła też pewna uboga wdowa i wrzuciła dwie drobne monety, czyli kwartnik.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 43, 'Wtedy zawołał swoich uczniów i powiedział im: Zaprawdę powiadam wam, że ta uboga wdowa wrzuciła więcej niż wszyscy, którzy wrzucali do skarbony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 44, 'Wszyscy bowiem wrzucali z tego, co im zbywało, ale ona ze swego ubóstwa wrzuciła wszystko, co miała, całe swoje utrzymanie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 1, 'Gdy wychodził ze świątyni, jeden z jego uczniów powiedział do niego: Nauczycielu, patrz, jakie kamienie i jakie budowle!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 2, 'A Jezus mu odpowiedział: Widzisz te wielkie budowle? Nie zostanie kamień na kamieniu, który by nie został zwalony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 3, 'A gdy siedział na Górze Oliwnej, naprzeciwko świątyni, Piotr, Jakub, Jan i Andrzej pytali go na osobności:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 4, 'Powiedz nam, kiedy się to stanie i jaki będzie znak, gdy to wszystko będzie się spełniać?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 5, 'A Jezus w odpowiedzi zaczął im mówić: Uważajcie, aby was ktoś nie zwiódł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 6, 'Wielu bowiem przyjdzie pod moim imieniem, mówiąc: Ja jestem Chrystusem. I wielu zwiodą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 7, 'Gdy więc usłyszycie o wojnach i pogłoski o wojnach, nie lękajcie się. To musi się stać, ale to jeszcze nie koniec.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 8, 'Powstanie bowiem naród przeciwko narodowi i królestwo przeciwko królestwu, będą też miejscami trzęsienia ziemi, a także głód i zamęt. To jest początek boleści.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 9, 'Lecz miejcie się na baczności, bo będą was wydawać sądom i biczować w synagogach. Staniecie przed namiestnikami i królami z mojego powodu, na świadectwo przeciwko nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 10, 'A ewangelia musi być najpierw głoszona wszystkim narodom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 11, 'A gdy będą was prowadzić, żeby was wydać, nie martwcie się wcześniej, co macie mówić, ani o tym nie rozmyślajcie, ale mówcie to, co wam będzie dane w tej godzinie. Nie wy bowiem będziecie mówić, ale Duch Święty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 12, 'I wyda na śmierć brat brata, a ojciec syna. Dzieci powstaną przeciwko rodzicom i spowodują ich śmierć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 13, 'I będziecie znienawidzeni przez wszystkich z powodu mego imienia. Kto jednak wytrwa do końca, będzie zbawiony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 14, 'Gdy więc zobaczycie obrzydliwość spustoszenia, o której mówił prorok Daniel, stojącą tam, gdzie stać nie powinna (kto czyta, niech rozumie), wtedy ci, którzy będą w Judei, niech uciekają w góry;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 15, 'A kto będzie na dachu, niech nie schodzi ani nie wchodzi do domu, aby coś z niego zabrać;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 16, 'Kto zaś będzie w polu, niech nie wraca, aby wziąć swoją szatę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 17, 'Lecz biada brzemiennym i karmiącym w tych dniach!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 18, 'Módlcie się więc, aby wasza ucieczka nie wypadła w zimie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 19, 'Będą to bowiem dni takiego ucisku, jakiego nie było od początku stworzenia, którego dokonał Bóg, aż dotąd i nigdy nie będzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 20, 'A gdyby Pan nie skrócił tych dni, żadne ciało nie byłoby zbawione. Lecz ze względu na wybranych, których sobie obrał, skrócił te dni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 21, 'Jeśli wtedy ktoś wam powie: Oto tu jest Chrystus, albo: Oto tam jest – nie wierzcie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 22, 'Powstaną bowiem fałszywi Chrystusowie i fałszywi prorocy i będą czynić znaki i cuda, aby zwieść, o ile można, nawet wybranych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 23, 'Wy więc uważajcie. Wszystko wam przepowiedziałem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 24, 'Ale w tych dniach, po tym ucisku, zaćmi się słońce i księżyc nie da swego blasku;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 25, 'Gwiazdy nieba będą spadać i moce, które są na niebie, zostaną poruszone.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 26, 'A wtedy ujrzą Syna Człowieczego przychodzącego w obłokach z wielką mocą i chwałą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 27, 'Wówczas pośle swoich aniołów i zgromadzi swoich wybranych z czterech stron świata, od krańca ziemi aż do krańca nieba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 28, 'A od drzewa figowego uczcie się przez podobieństwo: Gdy już jego gałąź staje się miękka i wypuszcza liście, poznajecie, że lato jest blisko.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 29, 'Tak i wy, gdy ujrzycie, że to się dzieje, wiedzcie, że jest blisko, u drzwi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 30, 'Zaprawdę powiadam wam: Nie przeminie to pokolenie, aż się to wszystko stanie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 31, 'Niebo i ziemia przeminą, ale moje słowa nie przeminą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 32, 'Lecz o tym dniu i godzinie nikt nie wie, ani aniołowie, którzy są w niebie, ani Syn, tylko Ojciec.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 33, 'Uważajcie, czuwajcie i módlcie się, bo nie wiecie, kiedy ten czas nadejdzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 34, 'Syn Człowieczy bowiem jest jak człowiek, który wyjeżdżając, zostawił swój dom, dał władzę swoim sługom i każdemu jego pracę, a odźwiernemu nakazał czuwać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 35, 'Czuwajcie więc, bo nie wiecie, kiedy pan domu przyjdzie: wieczorem czy o północy, gdy pieją koguty czy rano;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 36, 'By przypadkiem, przyszedłszy niespodziewanie, nie zastał was śpiących.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 37, 'A to, co wam mówię, mówię wszystkim: Czuwajcie!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 1, 'A po dwóch dniach była Pascha i święto Przaśników. I naczelni kapłani oraz uczeni w Piśmie szukali sposobu, jak by go podstępnie schwytać i zabić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 2, 'Lecz mówili: Nie w święto, aby czasem nie wywołać rozruchów wśród ludu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 3, 'A gdy był w Betanii, w domu Szymona Trędowatego, i siedział przy stole, przyszła kobieta, która miała alabastrowe naczynie pełne bardzo drogiego olejku nardowego. Rozbiła naczynie i wylała mu olejek na głowę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 4, 'Niektórzy oburzyli się i mówili: Po co takie marnotrawstwo olejku?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 5, 'Przecież można to było sprzedać drożej niż za trzysta groszy i rozdać je ubogim. I szemrali przeciwko niej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 6, 'Lecz Jezus powiedział: Zostawcie ją! Dlaczego sprawiacie jej przykrość? Dobry uczynek spełniła wobec mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 7, 'Ubogich bowiem zawsze macie u siebie i kiedy zechcecie, możecie im dobrze czynić. Mnie jednak nie zawsze będziecie mieć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 8, 'Ona zrobiła, co mogła. Zawczasu namaściła moje ciało na pogrzeb.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 9, 'Zaprawdę powiadam wam: Gdziekolwiek po całym świecie będzie głoszona ta ewangelia, będzie się również opowiadać na jej pamiątkę to, co zrobiła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 10, 'Wtedy Judasz Iskariota, jeden z dwunastu, poszedł do naczelnych kapłanów, aby im go wydać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 11, 'A gdy oni to usłyszeli, ucieszyli się i obiecali dać mu pieniądze. I szukał sposobności, aby go wydać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 12, 'W pierwszy dzień Przaśników, gdy zabijano baranka paschalnego, zapytali go jego uczniowie: Gdzie chcesz, abyśmy poszli i przygotowali ci Paschę do spożycia?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 13, 'I posłał dwóch spośród swych uczniów, i powiedział im: Idźcie do miasta, a spotka się z wami człowiek niosący dzban wody. Idźcie za nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 14, 'Tam zaś, gdzie wejdzie, powiecie gospodarzowi: Nauczyciel pyta: Gdzie jest pokój, w którym będę jadł Paschę z moimi uczniami?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 15, 'A on wam pokaże wielką salę na piętrze, urządzoną i przygotowaną. Tam dla nas wszystko przygotujcie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 16, 'Odeszli więc jego uczniowie i przyszli do miasta, gdzie znaleźli wszystko tak, jak im powiedział, i przygotowali Paschę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 17, 'A gdy nastał wieczór, przyszedł z dwunastoma.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 18, 'Kiedy siedzieli za stołem i jedli, Jezus powiedział: Zaprawdę powiadam wam, że jeden z was, jedzący ze mną, wyda mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 19, 'Wtedy zaczęli się smucić i pytać jeden po drugim: Czy to ja? a inny: Czy ja?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 20, 'Lecz on im odpowiedział: Jeden z dwunastu, ten, który ze mną macza w misie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 21, 'Syn Człowieczy odchodzi, jak jest o nim napisane, ale biada temu człowiekowi, przez którego Syn Człowieczy będzie wydany! Lepiej byłoby dla tego człowieka, gdyby się nie urodził.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 22, 'A gdy jedli, Jezus wziął chleb, pobłogosławił, połamał i dał im, mówiąc: Bierzcie, jedzcie, to jest moje ciało.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 23, 'Potem wziął kielich, złożył dziękczynienie i dał im. I pili z niego wszyscy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 24, 'I powiedział im: To jest moja krew nowego testamentu, która się za wielu wylewa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 25, 'Zaprawdę powiadam wam: Nie będę więcej pił z owocu winorośli aż do tego dnia, gdy go będę pił nowy w królestwie Bożym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 26, 'A gdy zaśpiewali hymn, wyszli ku Górze Oliwnej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 27, 'Potem Jezus im powiedział: Wy wszyscy zgorszycie się z mojego powodu tej nocy, bo jest napisane: Uderzę pasterza, a rozproszą się owce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 28, 'Lecz gdy zmartwychwstanę, udam się do Galilei przed wami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 29, 'Ale Piotr mu powiedział: Jeśli nawet wszyscy się zgorszą, jednak nie ja.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 30, 'I powiedział mu Jezus: Zaprawdę powiadam ci, że dziś, tej nocy, zanim kogut dwa razy zapieje, trzy razy się mnie wyprzesz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 31, 'Ale on tym bardziej zapewniał: Choćbym miał z tobą i umrzeć, nie wyprę się ciebie. Tak samo mówili wszyscy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 32, 'I przyszli na miejsce zwane Getsemani. Wtedy powiedział do swoich uczniów: Siedźcie tu, ja tymczasem będę się modlił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 33, 'Wziąwszy ze sobą Piotra, Jakuba i Jana, zaczął odczuwać lęk i udrękę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 34, 'I powiedział do nich: Bardzo smutna jest moja dusza aż do śmierci. Zostańcie tu i czuwajcie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 35, 'A odszedłszy trochę dalej, upadł na ziemię i modlił się, aby, jeśli to możliwe, ominęła go ta godzina.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 36, 'I powiedział: Abba, Ojcze, dla ciebie wszystko jest możliwe, zabierz ode mnie ten kielich. Jednak niech się stanie nie to, co ja chcę, ale to, co Ty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 37, 'Potem przyszedł i zastał ich śpiących. I powiedział do Piotra: Szymonie, śpisz? Nie mogłeś czuwać jednej godziny?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 38, 'Czuwajcie i módlcie się, abyście nie ulegli pokusie. Duch wprawdzie jest ochoczy, ale ciało słabe.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 39, 'I odszedłszy znowu, modlił się tymi samymi słowami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 40, 'A gdy wrócił, ponownie zastał ich śpiących, bo oczy same im się zamykały; i nie wiedzieli, co mu odpowiedzieć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 41, 'I przyszedł po raz trzeci, i powiedział im: Śpijcie dalej i odpoczywajcie! Dosyć! Nadeszła godzina, oto Syn Człowieczy będzie wydany w ręce grzeszników.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 42, 'Wstańcie, chodźmy! Oto zbliża się ten, który mnie wydaje.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 43, 'I zaraz, gdy on jeszcze mówił, nadszedł Judasz, jeden z dwunastu, a z nim wielka zgraja z mieczami i kijami od naczelnych kapłanów, uczonych w Piśmie i starszych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 44, 'A ten, który go zdradził, ustalił z nimi znak, mówiąc: Ten, którego pocałuję, to on, schwytajcie go i prowadźcie ostrożnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 45, 'Gdy tylko przyszedł, natychmiast zbliżył się do niego i powiedział: Mistrzu, Mistrzu! I pocałował go.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 46, 'Wtedy tamci rzucili się na niego i schwytali go.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 47, 'A jeden z tych, którzy tam stali, dobył miecz, uderzył sługę najwyższego kapłana i odciął mu ucho.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 48, 'Jezus zaś powiedział do nich: Wyszliście jak na bandytę z mieczami i kijami, aby mnie schwytać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 49, 'Codziennie bywałem u was w świątyni, nauczając, a nie schwytaliście mnie. Ale Pisma muszą się wypełnić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 50, 'Wtedy wszyscy opuścili go i uciekli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 51, 'A szedł za nim pewien młody człowiek mający płótno narzucone na gołe ciało. I pochwycili go młodzieńcy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 52, 'Ale on zostawił płótno i nago uciekł od nich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 53, 'Wtedy przyprowadzili Jezusa do najwyższego kapłana, gdzie zeszli się wszyscy naczelni kapłani, starsi i uczeni w Piśmie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 54, 'Piotr zaś szedł za nim z daleka aż do dziedzińca najwyższego kapłana i siedział ze sługami, grzejąc się przy ogniu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 55, 'Tymczasem naczelni kapłani i cała Rada szukali świadectwa przeciwko Jezusowi, aby go skazać na śmierć, ale nie znaleźli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 56, 'Wielu bowiem fałszywie świadczyło przeciwko niemu, lecz ich świadectwa nie były zgodne.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 57, 'Wtedy niektórzy wystąpili i fałszywie świadczyli przeciwko niemu, mówiąc:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 58, 'Słyszeliśmy, jak mówił: Zburzę tę świątynię ręką uczynioną, a w trzy dni zbuduję inną, nie ręką uczynioną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 59, 'Lecz i tak ich świadectwo nie było zgodne.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 60, 'Wtedy najwyższy kapłan, stanąwszy na środku, zapytał Jezusa: Nic nie odpowiadasz? Cóż to jest, co oni przeciwko tobie zeznają?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 61, 'Ale on milczał i nic nie odpowiedział. Znowu zapytał go najwyższy kapłan: Czy ty jesteś Chrystusem, Synem Błogosławionego?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 62, 'A Jezus odpowiedział: Ja jestem. I ujrzycie Syna Człowieczego siedzącego po prawicy mocy Boga i przychodzącego z obłokami nieba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 63, 'Wtedy najwyższy kapłan rozdarł swoje szaty i powiedział: Czyż potrzebujemy jeszcze świadków?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 64, 'Słyszeliście bluźnierstwo. Jak wam się zdaje? A oni wszyscy wydali wyrok, że zasługuje na śmierć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 65, 'I niektórzy zaczęli pluć na niego, zakrywali mu twarz, bili go pięściami i mówili: Prorokuj! A słudzy go policzkowali.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 66, 'Kiedy Piotr był na dole, na dziedzińcu, przyszła jedna ze służących najwyższego kapłana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 67, 'A gdy zobaczyła, że Piotr grzeje się przy ogniu, popatrzyła na niego i powiedziała: I ty byłeś z Jezusem z Nazaretu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 68, 'Lecz on się wyparł, mówiąc: Nie wiem i nie rozumiem, o czym mówisz. I wyszedł na zewnątrz do przedsionka, a kogut zapiał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 69, 'Wtedy służąca zobaczyła go znowu i zaczęła mówić do tych, którzy tam stali: To jest jeden z nich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 70, 'A on ponownie się wyparł. I znowu, po chwili ci, którzy tam stali, powiedzieli do Piotra: Na pewno jesteś jednym z nich, bo jesteś Galilejczykiem i twoja mowa jest podobna.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 71, 'Lecz on zaczął się zaklinać i przysięgać: Nie znam tego człowieka, o którym mówicie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 72, 'Wtedy kogut zapiał po raz drugi. I przypomniał sobie Piotr słowa, które powiedział mu Jezus: Zanim kogut dwa razy zapieje, trzy razy się mnie wyprzesz. I wyszedłszy, zapłakał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 1, 'Wczesnym rankiem naczelni kapłani, naradziwszy się razem ze starszymi, uczonymi w Piśmie i całą Radą, związali Jezusa, odprowadzili go i wydali Piłatowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 2, 'A Piłat zapytał go: Czy ty jesteś królem Żydów? On mu odpowiedział: Ty sam to mówisz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 3, 'I oskarżali go naczelni kapłani o wiele rzeczy, ale on nic nie odpowiedział.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 4, 'Wtedy Piłat znowu go zapytał: Nic nie odpowiadasz? Zobacz, jak wiele zeznają przeciwko tobie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 5, 'Jezus jednak nic nie odpowiedział, tak że Piłat się dziwił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 6, 'Na święto miał on zwyczaj wypuszczać im jednego więźnia, o którego prosili.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 7, 'A był jeden, zwany Barabaszem, więziony wraz z buntownikami, którzy podczas rozruchów popełnili zabójstwo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 8, 'I tłum zaczął wołać i prosić, żeby zrobił to, co zawsze dla nich robił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 9, 'Lecz Piłat im odpowiedział: Chcecie, abym wam wypuścił króla Żydów?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 10, 'Wiedział bowiem, że naczelni kapłani wydali go z zawiści.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 11, 'Ale naczelni kapłani podburzyli tłum, żeby raczej wypuścił im Barabasza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 12, 'A Piłat znowu im odpowiedział: Cóż więc chcecie, abym uczynił z tym, którego nazywacie królem Żydów?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 13, 'A oni znowu zawołali: Ukrzyżuj go!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 14, 'Wtedy Piłat zapytał: Cóż on złego uczynił? Lecz oni jeszcze głośniej wołali: Ukrzyżuj go!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 15, 'Piłat więc, chcąc zadowolić tłum, wypuścił im Barabasza, a Jezusa ubiczował i wydał im na ukrzyżowanie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 16, 'Żołnierze wprowadzili go do sali, czyli do ratusza, i zwołali cały oddział.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 17, 'Potem ubrali go w purpurę, a uplótłszy koronę z cierni, włożyli mu na głowę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 18, 'I zaczęli go pozdrawiać: Witaj, królu Żydów!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 19, 'Bili go trzciną po głowie i pluli na niego, a upadając na kolana, oddawali mu pokłon.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 20, 'A gdy go wyszydzili, zdjęli z niego purpurę, ubrali go w jego własne szaty i wyprowadzili na ukrzyżowanie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 21, 'I przymusili przechodzącego obok niejakiego Szymona z Cyreny, który szedł z pola, ojca Aleksandra i Rufusa, aby niósł jego krzyż.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 22, 'I przyprowadzili go na miejsce zwane Golgota, co się tłumaczy: Miejsce Czaszki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 23, 'Dawali mu do picia wino z mirrą, ale go nie przyjął.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 24, 'A gdy go ukrzyżowali, rozdzielili jego szaty, rzucając o nie losy, by rozstrzygnąć, co kto ma wziąć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 25, 'A była godzina trzecia, gdy go ukrzyżowali.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 26, 'Był też napis z podaniem jego winy: Król Żydów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 27, 'I ukrzyżowali z nim dwóch bandytów, jednego po prawej, a drugiego po jego lewej stronie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 28, 'Tak wypełniło się Pismo, które mówi: Zaliczono go w poczet złoczyńców.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 29, 'A ci, którzy przechodzili obok, bluźnili mu, kiwając głowami i mówiąc: Ej! Ty, który burzysz świątynię i w trzy dni ją odbudowujesz;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 30, 'Ratuj samego siebie i zejdź z krzyża!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 31, 'Podobnie naczelni kapłani wraz z uczonymi w Piśmie, naśmiewając się, mówili między sobą: Innych ratował, a samego siebie uratować nie może.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 32, 'Niech Chrystus, król Izraela, zejdzie teraz z krzyża, żebyśmy ujrzeli i uwierzyli. Urągali mu także ci, którzy byli z nim ukrzyżowani.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 33, 'A gdy była szósta godzina, ciemność ogarnęła całą ziemię aż do godziny dziewiątej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 34, 'O godzinie dziewiątej Jezus zawołał donośnym głosem: Eloi, Eloi, lama sabachthani? – co się tłumaczy: Boże mój, Boże mój, czemu mnie opuściłeś?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 35, 'A niektórzy ze stojących tam ludzi, usłyszawszy to, mówili: Woła Eliasza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 36, 'Wtedy ktoś podbiegł, napełnił gąbkę octem i włożywszy na trzcinę, dał mu pić, mówiąc: Przestańcie, zobaczymy, czy przyjdzie Eliasz, aby go zdjąć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 37, 'A Jezus zawołał donośnym głosem i oddał ducha.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 38, 'I rozerwała się na pół zasłona świątyni, od góry aż do dołu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 39, 'A setnik, który stał naprzeciw, widząc, że tak wołając, oddał ducha, powiedział: Ten człowiek prawdziwie był Synem Bożym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 40, 'Były tam też kobiety, które przypatrywały się z daleka, a wśród nich Maria Magdalena i Maria, matka Jakuba Mniejszego i Józefa, oraz Salome.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 41, 'One to, gdy jeszcze był w Galilei, chodziły za nim i usługiwały mu. Było też wiele innych, które wraz z nim przyszły do Jerozolimy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 42, 'A ponieważ był dzień przygotowania, który jest przed szabatem, i nastał już wieczór;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 43, 'Przyszedł Józef z Arymatei, ważny członek Rady, który sam też oczekiwał królestwa Bożego, śmiało wszedł do Piłata i poprosił o ciało Jezusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 44, 'A Piłat zdziwił się, że już nie żyje, i zawoławszy setnika, zapytał go, czy dawno umarł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 45, 'I upewniony przez setnika, wydał ciało Józefowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 46, 'Ten kupił płótno, zdjął go, owinął płótnem i złożył w grobowcu, który był wykuty w skale, a przed wejście do grobowca zatoczył kamień.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 47, 'A Maria Magdalena i Maria, matka Józefa, patrzyły, gdzie go złożono.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 1, 'A gdy minął szabat, Maria Magdalena, Maria, matka Jakuba, i Salome nakupiły wonności, aby pójść i namaścić go.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 2, 'Pierwszego dnia po szabacie, wczesnym rankiem, gdy wzeszło słońce, przyszły do grobu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 3, 'I mówiły do siebie: Któż nam odwali kamień od wejścia do grobowca?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 4, '(A gdy spojrzały, zobaczyły, że kamień został odwalony). Był bowiem bardzo wielki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 5, 'Gdy weszły do grobowca, ujrzały młodzieńca siedzącego po prawej stronie, ubranego w białą szatę, i przestraszyły się.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 6, 'Lecz on powiedział do nich: Nie bójcie się. Szukacie Jezusa z Nazaretu, który był ukrzyżowany. Powstał, nie ma go tu. Oto miejsce, gdzie go złożono.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 7, 'Ale idźcie i powiedzcie jego uczniom i Piotrowi: Udaje się przed wami do Galilei. Tam go ujrzycie, jak wam powiedział.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 8, 'Wyszły więc szybko i uciekły od grobu, bo ogarnął je lęk i zdumienie. Nikomu też nic nie mówiły, ponieważ się bały.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 9, 'A Jezus, gdy zmartwychwstał wczesnym rankiem pierwszego dnia po szabacie, ukazał się najpierw Marii Magdalenie, z której wypędził siedem demonów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 10, 'Ona zaś poszła i opowiedziała to tym, którzy z nim przebywali, pogrążonym w smutku i płaczącym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 11, 'A gdy oni usłyszeli, że żyje i że go widziała, nie wierzyli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 12, 'Potem ukazał się w innej postaci dwom z nich, gdy szli na wieś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 13, 'Oni poszli i opowiedzieli pozostałym. Lecz i tym nie uwierzyli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 14, 'Na koniec ukazał się jedenastu, gdy siedzieli za stołem, i wyrzucał im ich niewiarę i zatwardziałość serca, że nie wierzyli tym, którzy go widzieli wskrzeszonego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 15, 'I powiedział do nich: Idźcie na cały świat i głoście ewangelię wszelkiemu stworzeniu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 16, 'Kto uwierzy i ochrzci się, będzie zbawiony, ale kto nie uwierzy, będzie potępiony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 17, 'A takie znaki będą towarzyszyć tym, którzy uwierzą: w moim imieniu będą wypędzać demony, będą mówić nowymi językami;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 18, 'Będą brać węże, a choćby wypili coś śmiercionośnego, nie zaszkodzi im; na chorych będą kłaść ręce, a ci odzyskają zdrowie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 19, 'A gdy Pan przestał do nich mówić, został wzięty do nieba i zasiadł po prawicy Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 20, 'Oni zaś poszli i głosili wszędzie, a Pan współdziałał z nimi i potwierdzał ich słowa znakami, które im towarzyszyły. Amen.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 1, 'Ponieważ wielu podjęło się sporządzić opis tych wydarzeń, co do których mamy zupełną pewność;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 2, 'Tak jak nam je przekazali ci, którzy od początku byli naocznymi świadkami i sługami słowa;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 3, 'Postanowiłem i ja, który to wszystko od początku dokładnie wybadałem, opisać ci to po kolei, zacny Teofilu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 4, 'Abyś nabrał pewności co do tego, czego cię nauczono.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 5, 'Za dni Heroda, króla Judei, żył pewien kapłan imieniem Zachariasz, ze zmiany Abiasza. Miał on za żonę jedną z córek Aarona, której na imię było Elżbieta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 6, 'Oboje byli sprawiedliwi w oczach Boga, postępując nienagannie według wszystkich przykazań i nakazów Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 7, 'Nie mieli jednak dziecka, ponieważ Elżbieta była niepłodna, i oboje byli w podeszłym wieku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 8, 'A gdy pełnił służbę kapłańską przed Bogiem w kolejności swojej zmiany;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 9, 'Zgodnie ze zwyczajem urzędu kapłańskiego padł na niego los, aby wejść do świątyni Pana i palić kadzidło.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 10, 'A cała rzesza ludzi modliła się na zewnątrz w czasie kadzenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 11, 'Wtedy ukazał mu się anioł Pana stojący po prawej stronie ołtarza kadzenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 12, 'I przeraził się Zachariasz na jego widok, i ogarnął go strach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 13, 'Lecz anioł powiedział do niego: Nie bój się, Zachariaszu, bo twoja modlitwa została wysłuchana. Elżbieta, twoja żona, urodzi ci syna, któremu nadasz imię Jan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 14, 'Będzie to dla ciebie radość i wesele; i wielu będzie się radować z jego narodzin.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 15, 'Będzie bowiem wielki w oczach Pana. Nie będzie pił wina ani mocnego napoju i zostanie napełniony Duchem Świętym już w łonie swojej matki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 16, 'I wielu z synów Izraela nawróci do Pana, ich Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 17, 'On bowiem pójdzie przed nim w duchu i mocy Eliasza, aby zwrócić serca ojców ku dzieciom, a opornych ku roztropności sprawiedliwych, aby przygotować Panu lud gotowy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 18, 'I powiedział Zachariasz do anioła: Po czym to poznam? Bo ja jestem stary i moja żona jest w podeszłym wieku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 19, 'A anioł mu odpowiedział: Ja jestem Gabriel, który stoi przed Bogiem. Zostałem posłany, aby mówić do ciebie i przynieść ci tę radosną nowinę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 20, 'I będziesz niemy, i nie będziesz mógł mówić aż do dnia, kiedy się to stanie, dlatego że nie uwierzyłeś moim słowom, które się wypełnią w swoim czasie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 21, 'A ludzie czekali na Zachariasza i dziwili się, że tak długo przebywa w świątyni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 22, 'Kiedy wyszedł, nie mógł do nich mówić. I zrozumieli, że miał widzenie w świątyni, bo dawał im znaki, i pozostał niemy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 23, 'A gdy skończyły się dni jego posługi, wrócił do swego domu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 24, 'Po tych dniach Elżbieta, jego żona, poczęła i ukrywała się przez pięć miesięcy, mówiąc:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 25, 'Tak mi uczynił Pan w dniach, kiedy wejrzał na mnie, aby zdjąć moją hańbę w oczach ludzi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 26, 'A w szóstym miesiącu Bóg posłał anioła Gabriela do miasta w Galilei, zwanego Nazaret;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 27, 'Do dziewicy zaślubionej mężczyźnie, któremu na imię było Józef, z rodu Dawida; a dziewicy było na imię Maria.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 28, 'Kiedy anioł przyszedł do niej, powiedział: Witaj, obdarowana łaską, Pan jest z tobą. Błogosławiona jesteś między kobietami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 29, 'Ale ona, ujrzawszy go, zlękła się z powodu jego słów i zastanawiała się, co miałoby znaczyć to pozdrowienie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 30, 'Wtedy anioł powiedział do niej: Nie bój się, Mario, znalazłaś bowiem łaskę u Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 31, 'Oto poczniesz w swym łonie i urodzisz syna, któremu nadasz imię Jezus.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 32, 'Będzie on wielki i będzie nazwany Synem Najwyższego, a Pan Bóg da mu tron jego ojca Dawida.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 33, 'I będzie królował nad domem Jakuba na wieki, a jego królestwu nie będzie końca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 34, 'Wtedy Maria powiedziała do anioła: Jak to się stanie, skoro nie obcowałam z mężczyzną?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 35, 'A anioł jej odpowiedział: Duch Święty zstąpi na ciebie i moc Najwyższego zacieni cię. Dlatego też to święte, co się z ciebie narodzi, będzie nazwane Synem Bożym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 36, 'A oto Elżbieta, twoja krewna, także poczęła syna w swojej starości i jest w szóstym miesiącu ta, którą nazywano niepłodną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 37, 'Dla Boga bowiem nie ma nic niemożliwego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 38, 'I powiedziała Maria: Oto służebnica Pana, niech mi się stanie według twego słowa. Wtedy odszedł od niej anioł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 39, 'W tych dniach Maria wstała i poszła z pośpiechem w góry do miasta w Judei.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 40, 'Weszła do domu Zachariasza i pozdrowiła Elżbietę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 41, 'A gdy Elżbieta usłyszała pozdrowienie Marii, poruszyło się dziecko w jej łonie i Elżbieta została napełniona Duchem Świętym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 42, 'I zawołała donośnym głosem: Błogosławiona jesteś między kobietami i błogosławiony jest owoc twego łona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 43, 'A skądże mi to, że matka mego Pana przyszła do mnie?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 44, 'Gdy bowiem głos twego pozdrowienia zabrzmiał w moich uszach, poruszyło się z radości dziecko w moim łonie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 45, 'A błogosławiona, która uwierzyła. Spełni się bowiem to, co zostało jej powiedziane przez Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 46, 'Wtedy Maria powiedziała: Wielbi moja dusza Pana;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 47, 'I rozradował się mój duch w Bogu, moim Zbawicielu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 48, 'Bo wejrzał na uniżenie swojej służebnicy. Oto bowiem wszystkie pokolenia będą mnie odtąd nazywać błogosławioną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 49, 'Bo uczynił mi wielkie rzeczy ten, który jest mocny, i święte jest jego imię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 50, 'A jego miłosierdzie z pokolenia na pokolenie nad tymi, którzy się go boją.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 51, 'Okazał moc swoim ramieniem i rozproszył pysznych w myślach ich serc.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 52, 'Strącił mocarzy z tronów, a wywyższył pokornych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 53, 'Głodnych napełnił dobrami, a bogaczy odprawił z niczym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 54, 'Ujął się za Izraelem, swym sługą, pomny na swoje miłosierdzie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 55, 'Jak mówił do naszych ojców, do Abrahama i jego potomstwa na wieki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 56, 'I została z nią Maria około trzech miesięcy, a potem wróciła do swego domu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 57, 'Dla Elżbiety zaś nadszedł czas porodu i urodziła syna.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 58, 'A gdy jej sąsiedzi i krewni usłyszeli, że Pan okazał jej swoje wielkie miłosierdzie, cieszyli się razem z nią.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 59, 'A ósmego dnia przyszli, aby obrzezać dziecko, i chcieli nadać mu imię jego ojca, Zachariasza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 60, 'Ale jego matka powiedziała: Nie tak, lecz będzie się nazywał Jan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 61, 'I powiedzieli do niej: Nie ma nikogo w twoim rodzie, kogo by nazwano tym imieniem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 62, 'Pytali więc znakami jego ojca, jak chce go nazwać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 63, 'A on poprosił o tabliczkę i napisał: Jan jest jego imię. I dziwili się wszyscy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 64, 'Natychmiast otworzyły się jego usta i rozwiązał się jego język, i mówił, wielbiąc Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 65, 'I padł strach na wszystkich ich sąsiadów, i po całej górskiej krainie judzkiej rozgłoszone zostały wszystkie te słowa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 66, 'Wszyscy zaś, którzy o tym słyszeli, brali to sobie do serca i mówili: Cóż to będzie za dziecko? I była z nim ręka Pańska.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 67, 'A Zachariasz, jego ojciec, będąc napełniony Duchem Świętym, prorokował:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 68, 'Błogosławiony niech będzie Pan, Bóg Izraela, bo nawiedził i odkupił swój lud;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 69, 'I wzbudził nam róg zbawienia w domu Dawida, swego sługi;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 70, 'Jak mówił przez usta swoich świętych proroków, którzy byli od wieków;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 71, 'Że nas wybawi od naszych nieprzyjaciół i z ręki wszystkich, którzy nas nienawidzą;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 72, 'Aby okazać miłosierdzie naszym ojcom i przypomnieć swoje święte przymierze;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 73, 'I przysięgę, którą złożył Abrahamowi, naszemu ojcu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 74, 'Że nam da, abyśmy mu służyli bez lęku, wybawieni z ręki naszych nieprzyjaciół;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 75, 'W świętości i sprawiedliwości przed nim po wszystkie dni naszego życia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 76, 'A ty, dziecko, będziesz nazwane prorokiem Najwyższego, bo pójdziesz przed obliczem Pana, aby przygotować jego drogi;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 77, 'I żeby jego ludowi dać poznać zbawienie przez przebaczenie mu grzechów;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 78, 'Dzięki serdecznemu miłosierdziu naszego Boga, przez które nawiedził nas wschód słońca z wysoka;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 79, 'Aby oświecić siedzących w ciemności i w cieniu śmierci, aby skierować nasze kroki na drogę pokoju.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 80, 'A dziecko rosło i umacniało się w duchu, i przebywało na pustyniach aż do dnia ukazania się przed Izraelem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 1, 'A w tych dniach wyszedł dekret cesarza Augusta, aby spisano cały świat.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 2, 'A ten pierwszy spis odbył się, gdy Kwiryniusz był namiestnikiem Syrii.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 3, 'Szli więc wszyscy, aby dać się spisać, każdy do swego miasta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 4, 'Poszedł też Józef z Galilei, z miasta Nazaret, do Judei, do miasta Dawida, zwanego Betlejem, ponieważ pochodził z domu i z rodu Dawida;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 5, 'Aby dać się spisać z Marią, poślubioną sobie małżonką, która była brzemienna.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 6, 'A gdy tam byli, nadszedł czas porodu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 7, 'I urodziła swego pierworodnego syna, owinęła go w pieluszki i położyła w żłobie, gdyż nie było dla nich miejsca w gospodzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 8, 'A byli w tej okolicy pasterze przebywający w polu i trzymający straż nocną nad swoim stadem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 9, 'I oto stanął przy nich anioł Pana, a chwała Pana zewsząd ich oświeciła. I ogarnął ich wielki strach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 10, 'I powiedział do nich anioł: Nie bójcie się, bo oto zwiastuję wam wielką radość, która będzie udziałem całego ludu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 11, 'Dziś bowiem w mieście Dawida narodził się wam Zbawiciel, którym jest Chrystus Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 12, 'A to będzie dla was znakiem: Znajdziecie niemowlę owinięte w pieluszki i leżące w żłobie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 13, 'I zaraz z aniołem przybyło mnóstwo wojsk niebieskich chwalących Boga i mówiących:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 14, 'Chwała na wysokościach Bogu, a na ziemi pokój, wobec ludzi dobra wola.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 15, 'A gdy aniołowie odeszli od nich do nieba, pasterze mówili między sobą: Chodźmy aż do Betlejem i zobaczmy to, co się wydarzyło, a co Pan nam oznajmił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 16, 'Spiesząc się więc, przyszli i znaleźli Marię, Józefa i niemowlę leżące w żłobie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 17, 'A ujrzawszy, rozgłosili to, co zostało im powiedziane o tym dziecku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 18, 'A wszyscy, którzy słyszeli, dziwili się temu, co pasterze im mówili.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 19, 'Lecz Maria zachowywała wszystkie te słowa, rozważając je w swoim sercu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 20, 'I wrócili pasterze, wielbiąc i chwaląc Boga za wszystko, co słyszeli i widzieli, tak jak im zostało powiedziane.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 21, 'A gdy minęło osiem dni i należało obrzezać dziecko, nadano mu imię Jezus, którym nazwał je anioł, zanim się poczęło w łonie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 22, 'Gdy też według Prawa Mojżesza minęły dni jej oczyszczenia, przynieśli go do Jerozolimy, aby stawić go przed Panem;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 23, '(Tak jak jest napisane w Prawie Pana: Każdy mężczyzna otwierający łono będzie nazywany świętym Panu);');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 24, 'I żeby złożyć ofiarę według tego, co zostało powiedziane w Prawie Pana, parę synogarlic albo dwa gołąbki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 25, 'A był w Jerozolimie człowiek imieniem Symeon. Ten człowiek był sprawiedliwy i bogobojny, oczekujący pociechy Izraela, a Duch Święty był nad nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 26, 'I objawił mu Bóg przez Ducha Świętego, że nie ujrzy śmierci, dopóki nie zobaczy Chrystusa Pańskiego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 27, 'Przyszedł on prowadzony przez Ducha Świętego do świątyni. A gdy rodzice wnosili dziecko – Jezusa, aby postąpić z nim według zwyczaju prawa;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 28, 'Wtedy on, wziąwszy go na ręce, chwalił Boga i mówił:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 29, 'Teraz pozwalasz odejść twemu słudze, Panie, w pokoju, według twego słowa;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 30, 'Gdyż moje oczy ujrzały twoje zbawienie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 31, 'Które przygotowałeś wobec wszystkich ludzi;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 32, 'Światłość na oświecenie pogan i chwałę twego ludu, Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 33, 'A Józef i jego matka dziwili się temu, co o nim mówiono.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 34, 'I błogosławił im Symeon, i powiedział do Marii, jego matki: Oto ten położony jest na upadek i na powstanie wielu w Izraelu, i na znak, przeciwko któremu będą mówić;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 35, '(I twoją duszę miecz przeniknie), aby myśli wielu serc zostały objawione.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 36, 'A była tam prorokini Anna, córka Fanuela, z pokolenia Asera, która była w bardzo podeszłym wieku, a żyła siedem lat z mężem od swego dziewictwa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 37, 'A była wdową mającą około osiemdziesięciu czterech lat, która nie opuszczała świątyni, służąc Bogu w postach i modlitwach dniem i nocą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 38, 'Ona też, przyszedłszy w tej właśnie chwili, dziękowała Panu i mówiła o nim wszystkim, którzy oczekiwali odkupienia w Jerozolimie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 39, 'A gdy wykonali wszystko według prawa Pana, wrócili do Galilei, do swego miasta, Nazaretu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 40, 'Dziecko zaś rosło i umacniało się w duchu, będąc pełne mądrości, a łaska Boga była nad nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 41, 'A jego rodzice chodzili co roku do Jerozolimy na święto Paschy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 42, 'I gdy miał dwanaście lat, poszli do Jerozolimy, zgodnie ze zwyczajem tego święta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 43, 'A gdy minęły te dni i już wracali, dziecię Jezus zostało w Jerozolimie, ale Józef i jego matka o tym nie wiedzieli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 44, 'Lecz sądząc, że jest w towarzystwie podróżnych, przeszli dzień drogi i szukali go wśród krewnych i znajomych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 45, 'A gdy go nie znaleźli, wrócili do Jerozolimy, szukając go.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 46, 'A po trzech dniach znaleźli go siedzącego w świątyni wśród nauczycieli, słuchającego i pytającego ich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 47, 'I wszyscy, którzy go słuchali, zdumiewali się jego rozumem i odpowiedziami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 48, 'A rodzice, ujrzawszy go, zdziwili się. I powiedziała do niego jego matka: Synu, dlaczego nam to zrobiłeś? Oto twój ojciec i ja z bólem serca szukaliśmy ciebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 49, 'I powiedział do nich: Czemu mnie szukaliście? Czy nie wiedzieliście, że muszę być w tym, co należy do mego Ojca?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 50, 'Lecz oni nie zrozumieli tych słów, które im mówił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 51, 'Wtedy poszedł z nimi i wrócił do Nazaretu, i był im posłuszny. A jego matka zachowywała wszystkie te słowa w swoim sercu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 52, 'A Jezusowi przybywało mądrości i wzrostu oraz łaski u Boga i u ludzi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 1, 'A w piętnastym roku panowania cesarza Tyberiusza, gdy Poncjusz Piłat był namiestnikiem Judei, Herod tetrarchą Galilei, jego brat Filip tetrarchą Iturei i ziemi Trachonu, a Lizaniasz tetrarchą Abileny;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 2, 'Za najwyższych kapłanów Annasza i Kajfasza doszło słowo Boże do Jana, syna Zachariasza, na pustyni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 3, 'I obchodził całą okolicę nad Jordanem, głosząc chrzest pokuty na przebaczenie grzechów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 4, 'Jak jest napisane w księdze słów proroka Izajasza: Głos wołającego na pustyni: Przygotujcie drogę Pana, prostujcie jego ścieżki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 5, 'Każda dolina będzie wypełniona, a każda góra i pagórek będą obniżone; to, co krzywe, wyprostuje się, a wyboiste drogi będą gładkie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 6, 'I ujrzy wszelkie ciało zbawienie Boże.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 7, 'Mówił więc do tłumów, które przychodziły, aby ich ochrzcił: Plemię żmijowe, któż was ostrzegł, żebyście uciekali przed przyszłym gniewem?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 8, 'Wydajcie więc owoce godne pokuty i nie zaczynajcie sobie wmawiać: Naszym ojcem jest Abraham. Mówię wam bowiem, że Bóg i z tych kamieni może wzbudzić dzieci Abrahamowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 9, 'A już siekiera do korzenia drzew jest przyłożona. Każde drzewo, które nie wydaje dobrego owocu, zostaje wycięte i wrzucone w ogień.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 10, 'I pytali go ludzie: Cóż więc mamy czynić?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 11, 'A on im odpowiedział: Kto ma dwie szaty, niech da temu, który nie ma, a kto ma pożywienie, niech uczyni tak samo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 12, 'Przyszli też celnicy, aby się ochrzcić, i pytali go: Nauczycielu, cóż mamy czynić?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 13, 'A on im odpowiedział: Nie pobierajcie nic więcej ponad to, co wam wyznaczono.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 14, 'Pytali go też żołnierze: A my co mamy czynić? I odpowiedział im: Wobec nikogo nie używajcie przemocy, nikogo fałszywie nie oskarżajcie i poprzestawajcie na waszym żołdzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 15, 'A gdy ludzie trwali w oczekiwaniu i wszyscy myśleli w swych sercach o Janie, czy może on nie jest Chrystusem;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 16, 'Odpowiedział Jan wszystkim: Ja was chrzczę wodą, lecz idzie mocniejszy ode mnie, któremu nie jestem godny rozwiązać rzemyka u jego sandałów. On będzie was chrzcił Duchem Świętym i ogniem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 17, 'Ma on swoje wiejadło w ręku i wyczyści swoje klepisko, i zgromadzi pszenicę do swego spichlerza, ale plewy spali w ogniu nieugaszonym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 18, 'A tak głosząc, dawał ludziom jeszcze wiele innych napomnień.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 19, 'Lecz tetrarcha Herod, strofowany przez niego z powodu Herodiady, żony swego brata Filipa, i z powodu wszystkich złych czynów, których się dopuścił;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 20, 'Dodał do wszystkiego i to, że wtrącił Jana do więzienia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 21, 'I stało się tak, że kiedy wszyscy ludzie byli ochrzczeni, również Jezus został ochrzczony, a gdy się modlił, otworzyło się niebo;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 22, 'I zstąpił na niego Duch Święty w kształcie cielesnym jak gołębica, a z nieba rozległ się głos: Ty jesteś moim umiłowanym Synem, w tobie mam upodobanie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 23, 'A Jezus miał około trzydziestu lat. Był, jak sądzono, synem Józefa, syna Helego;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 24, 'Syna Mattata, syna Lewiego, syna Melchiego, syna Jannaja, syna Józefa;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 25, 'Syna Matatiasza, syna Amosa, syna Nahuma, syna Esliego, syna Naggaja;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 26, 'Syna Maata, syna Matatiasza, syna Semei, syna Józefa, syna Judy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 27, 'Syna Joanana, syna Resy, syna Zorobabela, syna Salatiela, syna Neriego;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 28, 'Syna Melchiego, syna Addiego, syna Kosama, syna Elmadama, syna Era;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 29, 'Syna Jozego, syna Eliezera, syna Jorima, syna Mattata, syna Lewiego;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 30, 'Syna Symeona, syna Judy, syna Józefa, syna Jonana, syna Eliakima;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 31, 'Syna Meleasza, syna Menny, syna Mattata, syna Natana, syna Dawida;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 32, 'Syna Jessego, syna Obeda, syna Booza, syna Salmona, syna Naassona;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 33, 'Syna Aminadaba, syna Arama, syna Esroma, syna Faresa, syna Judy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 34, 'Syna Jakuba, syna Izaaka, syna Abrahama, syna Tarego, syna Nachora;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 35, 'Syna Serucha, syna Ragaua, syna Faleka, syna Hebera, syna Sali;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 36, 'Syna Kainana, syna Arfaksada, syna Sema, syna Noego, syna Lamecha;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 37, 'Syna Matusali, syna Enocha, syna Jareta, syna Maleleela, syna Kainana;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 38, 'Syna Enosa, syna Seta, syna Adama, syna Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 1, 'A Jezus, pełen Ducha Świętego, wrócił znad Jordanu i został zaprowadzony przez Ducha na pustynię;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 2, 'I przez czterdzieści dni był kuszony przez diabła. Nic nie jadł w tych dniach, a gdy minęły, poczuł głód.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 3, 'I powiedział do niego diabeł: Jeśli jesteś Synem Bożym, powiedz temu kamieniowi, aby stał się chlebem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 4, 'Ale Jezus mu odpowiedział: Jest napisane: Nie samym chlebem będzie żył człowiek, ale każdym słowem Bożym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 5, 'Wtedy wyprowadził go diabeł na wysoką górę i pokazał mu w jednej chwili wszystkie królestwa świata.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 6, 'I powiedział do niego diabeł: Dam ci całą tę potęgę i ich chwałę, bo zostały mi przekazane i daję je, komu chcę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 7, 'Jeśli więc oddasz mi pokłon, wszystko będzie twoje.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 8, 'A Jezus mu odpowiedział: Idź precz ode mnie, szatanie! Jest bowiem napisane: Panu, swemu Bogu, będziesz oddawał pokłon i tylko jemu będziesz służył.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 9, 'Potem zaprowadził go do Jerozolimy, postawił na szczycie świątyni i powiedział do niego: Jeśli jesteś Synem Bożym, rzuć się stąd w dół.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 10, 'Jest bowiem napisane: Rozkaże o tobie swoim aniołom, aby cię strzegli;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 11, 'I będą cię nosić na rękach, abyś przypadkiem nie uderzył swojej nogi o kamień.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 12, 'A Jezus mu odpowiedział: Powiedziano: Nie będziesz wystawiał na próbę Pana, swego Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 13, 'Kiedy diabeł skończył całe kuszenie, odstąpił od niego na jakiś czas.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 14, 'Jezus zaś wrócił w mocy Ducha do Galilei, a wieść o nim rozeszła się po całej okolicy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 15, 'I nauczał w ich synagogach, sławiony przez wszystkich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 16, 'Przyszedł też do Nazaretu, gdzie się wychował. Według swego zwyczaju wszedł w dzień szabatu do synagogi i wstał, aby czytać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 17, 'I podano mu księgę proroka Izajasza. Gdy otworzył księgę, znalazł miejsce, gdzie było napisane:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 18, 'Duch Pana nade mną, ponieważ namaścił mnie, abym głosił ewangelię ubogim, posłał mnie, abym uzdrawiał skruszonych w sercu, abym uwięzionym zwiastował wyzwolenie, a ślepym przejrzenie, abym uciśnionych wypuścił na wolność;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 19, 'Abym głosił miłościwy rok Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 20, 'Potem zamknął księgę, oddał ją słudze i usiadł, a oczy wszystkich w synagodze były w nim utkwione.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 21, 'I zaczął do nich mówić: Dziś wypełniły się te słowa Pisma w waszych uszach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 22, 'A wszyscy przyświadczali mu i dziwili się słowom łaski, które wychodziły z jego ust. I mówili: Czyż nie jest to syn Józefa?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 23, 'I powiedział do nich: Z pewnością powiecie mi to przysłowie: Lekarzu, ulecz samego siebie. To, o czym słyszeliśmy, że wydarzyło się w Kafarnaum, uczyń i tu, w swojej ojczyźnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 24, 'I powiedział: Zaprawdę powiadam wam: Żaden prorok nie jest dobrze przyjmowany w swojej ojczyźnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 25, 'Ale mówię wam zgodnie z prawdą, że wiele wdów było w Izraelu za dni Eliasza, gdy niebo było zamknięte przez trzy lata i sześć miesięcy, tak że wielki głód panował na całej ziemi;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 26, 'Jednak Eliasz nie został posłany do żadnej z nich, tylko do pewnej wdowy z Sarepty Sydońskiej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 27, 'I wielu było trędowatych w Izraelu za czasów proroka Elizeusza, jednak żaden z nich nie został oczyszczony, tylko Naaman Syryjczyk.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 28, 'I wszyscy w synagodze, słysząc to, zapłonęli gniewem;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 29, 'A wstawszy, wypchnęli go z miasta i wyprowadzili na szczyt góry, na której było zbudowane ich miasto, aby go z niej zrzucić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 30, 'Lecz on przeszedł między nimi i oddalił się.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 31, 'Potem przyszedł do Kafarnaum, miasta w Galilei, i tam nauczał ich w szabaty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 32, 'I zdumiewali się jego nauką, bo przemawiał z mocą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 33, 'A był w synagodze człowiek, który miał ducha demona nieczystego. Zawołał on donośnym głosem:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 34, 'Ach, cóż my z tobą mamy, Jezusie z Nazaretu? Przyszedłeś nas zniszczyć? Wiem, kim jesteś: Świętym Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 35, 'I zgromił go Jezus: Zamilcz i wyjdź z niego! Wtedy demon rzucił go na środek i wyszedł z niego, nie wyrządzając mu żadnej krzywdy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 36, 'A wszystkich ogarnęło zdumienie i rozmawiali między sobą: Cóż to za słowo? Bo z władzą i mocą rozkazuje duchom nieczystym, a one wychodzą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 37, 'I wieść o nim rozeszła się wszędzie po okolicznej krainie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 38, 'Po wyjściu z synagogi Jezus przyszedł do domu Szymona. A teściowa Szymona miała wysoką gorączkę, więc prosili go za nią.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 39, 'Wtedy on, stanąwszy nad nią, zgromił gorączkę, a ta ją opuściła. Zaraz też wstała i usługiwała im.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 40, 'A gdy słońce zachodziło, wszyscy, którzy mieli cierpiących na rozmaite choroby, przyprowadzali ich do niego, a on na każdego z nich kładł ręce i uzdrawiał ich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 41, 'Z wielu też wychodziły demony, wołając: Ty jesteś Chrystusem, Synem Bożym. Ale on gromił je i nie pozwalał im mówić. Wiedziały bowiem, że on jest Chrystusem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 42, 'Kiedy nastał dzień, wyszedł i udał się na odludne miejsce. A ludzie go szukali i przyszli aż do niego, i zatrzymywali go, aby od nich nie odchodził.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 43, 'Lecz on powiedział do nich: Także innym miastom muszę głosić królestwo Boże, bo po to zostałem posłany.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 44, 'I głosił w synagogach w Galilei.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 1, 'Pewnego razu, gdy ludzie cisnęli się do niego, aby słuchać słowa Bożego, on stał nad jeziorem Genezaret.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 2, 'I zobaczył dwie łodzie stojące przy brzegu jeziora, a rybacy, wyszedłszy z nich, płukali sieci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 3, 'Wsiadł do jednej z tych łodzi, która należała do Szymona, i poprosił go, aby trochę odpłynął od brzegu. A usiadłszy, nauczał ludzi z łodzi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 4, 'Kiedy przestał mówić, zwrócił się do Szymona: Wypłyń na głębię i zarzućcie wasze sieci na połów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 5, 'A Szymon mu odpowiedział: Mistrzu, przez całą noc pracowaliśmy i nic nie złowiliśmy, ale na twoje słowo zarzucę sieć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 6, 'A gdy to zrobili, zagarnęli wielkie mnóstwo ryb, tak że sieć im się rwała.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 7, 'Skinęli więc na towarzyszy, którzy byli w drugiej łodzi, aby przybyli i pomogli im. A oni przypłynęli i napełnili obie łodzie, tak że się zanurzały.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 8, 'Widząc to, Szymon Piotr przypadł do kolan Jezusa i powiedział: Odejdź ode mnie, Panie, bo jestem grzesznym człowiekiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 9, 'I jego bowiem, i wszystkich, którzy z nim byli, ogarnęło zdumienie z powodu połowu ryb, jakiego dokonali.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 10, 'Podobnie też Jakuba i Jana, synów Zebedeusza, którzy byli towarzyszami Szymona. I powiedział Jezus do Szymona: Nie bój się, odtąd będziesz łowił ludzi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 11, 'A oni, wyciągnąwszy łódź na brzeg, zostawili wszystko i poszli za nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 12, 'A gdy przebywał w pewnym mieście, był tam człowiek cały pokryty trądem. Kiedy zobaczył Jezusa, upadł na twarz i prosił go: Panie, jeśli chcesz, możesz mnie oczyścić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 13, 'Wtedy Jezus wyciągnął rękę, dotknął go i powiedział: Chcę, bądź oczyszczony. I natychmiast trąd go opuścił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 14, 'Potem przykazał mu, aby nikomu o tym nie mówił. I dodał: Ale idź, pokaż się kapłanowi i ofiaruj za swoje oczyszczenie, jak nakazał Mojżesz, na świadectwo dla nich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 15, 'Lecz wieść o nim jeszcze bardziej się rozchodziła. I schodziły się wielkie tłumy, aby go słuchać i aby ich uzdrowił z chorób.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 16, 'A on odchodził na pustynię i modlił się.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 17, 'Pewnego dnia, gdy nauczał, siedzieli tam też faryzeusze i nauczyciele prawa, którzy się zeszli ze wszystkich miasteczek Galilei, Judei i Jerozolimy. A moc Pana była obecna, aby ich uzdrawiać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 18, 'A oto jacyś mężczyźni nieśli na posłaniu sparaliżowanego. Szukali sposobu, jak go wnieść i położyć przed nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 19, 'Gdy jednak z powodu tłumu nie znaleźli drogi, którą by go mogli wnieść, weszli na dach i przez dachówkę spuścili go z posłaniem w sam środek, przed Jezusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 20, 'On, widząc ich wiarę, powiedział mu: Człowieku, przebaczone ci są twoje grzechy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 21, 'Wtedy uczeni w Piśmie i faryzeusze zaczęli się zastanawiać i mówić: Kim jest ten, który mówi bluźnierstwa? Któż może przebaczać grzechy oprócz samego Boga?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 22, 'Ale Jezus, poznawszy ich myśli, odpowiedział im: Co myślicie w waszych sercach?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 23, 'Cóż jest łatwiej powiedzieć: Przebaczone ci są twoje grzechy, czy powiedzieć: Wstań i chodź?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 24, 'Lecz abyście wiedzieli, że Syn Człowieczy ma na ziemi moc przebaczać grzechy – powiedział do sparaliżowanego: Mówię ci: Wstań, weź swoje posłanie i idź do domu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 25, 'A on natychmiast wstał na ich oczach, wziął to, na czym leżał, i poszedł do domu, wielbiąc Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 26, 'Wtedy wszyscy się zdumieli, chwalili Boga i pełni lęku mówili: Widzieliśmy dziś dziwne rzeczy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 27, 'Potem wyszedł i zobaczył celnika, imieniem Lewi, siedzącego w punkcie celnym, i powiedział do niego: Pójdź za mną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 28, 'A on zostawił wszystko, wstał i poszedł za nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 29, 'I przygotował mu Lewi wielką ucztę w swoim domu. A była tam wielka grupa celników i innych, którzy zasiedli z nimi za stołem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 30, 'A uczeni w Piśmie i faryzeusze szemrali, mówiąc do jego uczniów: Dlaczego jecie i pijecie z celnikami i grzesznikami?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 31, 'Jezus zaś im odpowiedział: Nie zdrowi, lecz chorzy potrzebują lekarza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 32, 'Nie przyszedłem wzywać do pokuty sprawiedliwych, ale grzeszników.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 33, 'I zapytali go: Dlaczego uczniowie Jana często poszczą i modlą się, podobnie uczniowie faryzeuszy, a twoi jedzą i piją?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 34, 'A on im odpowiedział: Czy możecie sprawić, żeby przyjaciele oblubieńca pościli, dopóki jest z nimi oblubieniec?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 35, 'Lecz przyjdą dni, gdy oblubieniec zostanie od nich zabrany, wtedy, w te dni, będą pościć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 36, 'Opowiedział im też przypowieść: Nikt nie przyszywa łaty z nowej szaty do starej, bo inaczej to, co jest nowe, drze stare, a do starego nie nadaje się łata z nowego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 37, 'I nikt nie wlewa młodego wina do starych bukłaków, bo inaczej młode wino rozsadzi bukłaki i samo wycieknie, a bukłaki się popsują.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 38, 'Ale młode wino należy wlewać do nowych bukłaków i tak zachowuje się jedno i drugie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 39, 'Nikt też, kto napił się starego, nie chce od razu młodego. Mówi bowiem: Stare jest lepsze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 1, 'W drugi szabat Jezus szedł przez zboża, a jego uczniowie zrywali kłosy i jedli, wykruszając je rękami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 2, 'Wtedy niektórzy z faryzeuszy mówili do nich: Dlaczego robicie to, czego nie wolno robić w szabat?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 3, 'A Jezus im odpowiedział: Czy nie czytaliście o tym, co zrobił Dawid, gdy był głodny, on i ci, którzy z nim byli?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 4, 'Jak wszedł do domu Bożego, wziął chleby pokładne, których nie wolno było jeść nikomu oprócz kapłanów, i jadł, i dał również tym, którzy z nim byli?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 5, 'I powiedział im: Syn Człowieczy jest też Panem szabatu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 6, 'W inny szabat Jezus wszedł do synagogi i nauczał. A był tam człowiek, który miał uschłą prawą rękę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 7, 'I obserwowali go uczeni w Piśmie i faryzeusze, czy uzdrowi w szabat, aby znaleźć powód do oskarżenia go.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 8, 'Ale on znał ich myśli i powiedział do człowieka, który miał uschłą rękę: Podnieś się i stań na środku. A on podniósł się i stanął.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 9, 'Wtedy Jezus powiedział do nich: Spytam was o pewną rzecz: Czy wolno w szabaty czynić dobrze, czy źle? Ocalić życie czy zniszczyć?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 10, 'A spojrzawszy wokoło po wszystkich, powiedział do tego człowieka: Wyciągnij rękę. A on to zrobił i jego ręka znowu stała się zdrowa tak jak druga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 11, 'Ale oni wpadli we wściekłość i rozmawiali między sobą, co by zrobić Jezusowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 12, 'W tych dniach odszedł na górę, aby się modlić, i spędził całą noc na modlitwie do Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 13, 'A gdy nastał dzień, przywołał swych uczniów i wybrał z nich dwunastu, których też nazwał apostołami:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 14, 'Szymona, którego nazwał Piotrem, i jego brata Andrzeja, Jakuba i Jana, Filipa i Bartłomieja;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 15, 'Mateusza i Tomasza, Jakuba, syna Alfeusza, i Szymona, zwanego Zelotą;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 16, 'Judasza, brata Jakuba, i Judasza Iskariotę, który stał się zdrajcą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 17, 'Potem zszedł z nimi i stanął na równinie. Była z nim też gromada jego uczniów i wielkie mnóstwo ludzi z całej Judei i Jerozolimy oraz z okolic nadmorskich, z Tyru i Sydonu, którzy przyszli, aby go słuchać i aby ich uzdrowił z chorób.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 18, 'Także ci, którzy byli dręczeni przez duchy nieczyste, zostali uzdrowieni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 19, 'A wszyscy ludzie starali się go dotknąć, ponieważ moc wychodziła z niego i uzdrawiała wszystkich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 20, 'A on podniósł oczy na uczniów i mówił: Błogosławieni jesteście wy, ubodzy, bo wasze jest królestwo Boże.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 21, 'Błogosławieni jesteście wy, którzy teraz cierpicie głód, bo będziecie nasyceni. Błogosławieni jesteście wy, którzy teraz płaczecie, bo śmiać się będziecie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 22, 'Błogosławieni będziecie, gdy ludzie będą was nienawidzić i gdy was wyłączą spośród siebie, będą was znieważać i odrzucą wasze imię jako niecne z powodu Syna Człowieczego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 23, 'Radujcie się w tym dniu i weselcie, bo obfita jest wasza nagroda w niebie. Tak samo bowiem ich ojcowie postępowali wobec proroków.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 24, 'Lecz biada wam, bogaczom, bo już otrzymaliście waszą pociechę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 25, 'Biada wam, którzy jesteście nasyceni, bo będziecie cierpieć głód. Biada wam, którzy się teraz śmiejecie, bo będziecie się smucić i płakać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 26, 'Biada wam, gdy wszyscy ludzie będą dobrze o was mówić, bo tak ich ojcowie postępowali wobec fałszywych proroków.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 27, 'Lecz mówię wam, którzy słuchacie: Miłujcie waszych nieprzyjaciół, dobrze czyńcie tym, którzy was nienawidzą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 28, 'Błogosławcie tym, którzy was przeklinają, módlcie się za tych, którzy wam wyrządzają zło.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 29, 'Temu, kto cię uderzy w policzek, nadstaw i drugi, a temu, kto zabiera ci płaszcz, i szaty nie odmawiaj.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 30, 'Każdemu, kto cię prosi, daj, a od tego, kto bierze, co twoje, nie upominaj się o zwrot.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 31, 'Jak chcecie, aby ludzie wam czynili, tak i wy im czyńcie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 32, 'Jeśli bowiem miłujecie tych, którzy was miłują, na jaką wdzięczność zasługujecie? Przecież i grzesznicy miłują tych, którzy ich miłują.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 33, 'A jeśli dobrze czynicie tym, którzy wam dobrze czynią, na jaką wdzięczność zasługujecie? Przecież i grzesznicy postępują tak samo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 34, 'I jeśli pożyczacie tym, od których spodziewacie się zwrotu, na jaką wdzięczność zasługujecie? Przecież i grzesznicy pożyczają grzesznikom, aby z powrotem odebrać tyle samo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 35, 'Ale miłujcie waszych nieprzyjaciół, czyńcie im dobrze i pożyczajcie, niczego się za to nie spodziewając, a wielka będzie wasza nagroda i będziecie synami Najwyższego. On bowiem jest dobry dla niewdzięcznych i złych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 36, 'Dlatego bądźcie miłosierni, jak i wasz Ojciec jest miłosierny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 37, 'Nie sądźcie, a nie będziecie sądzeni; nie potępiajcie, a nie będziecie potępieni; przebaczajcie, a będzie wam przebaczone.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 38, 'Dawajcie, a będzie wam dane; miarę dobrą, natłoczoną, utrzęsioną i przelewającą się dadzą w wasze zanadrze. Jaką bowiem miarą mierzycie, taką będzie wam odmierzone.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 39, 'I opowiedział im przypowieść: Czy może ślepy prowadzić ślepego? Czyż obaj nie wpadną do dołu?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 40, 'Uczeń nie przewyższa swego mistrza. Lecz doskonały będzie każdy, kto będzie jak jego mistrz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 41, 'Czemu widzisz źdźbło w oku swego brata, a na belkę, która jest w twoim oku, nie zwracasz uwagi?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 42, 'Albo jakże możesz mówić swemu bratu: Bracie, pozwól, że wyjmę źdźbło, które jest w twoim oku, gdy sam nie widzisz belki, która jest w twoim oku? Obłudniku, wyjmij najpierw belkę ze swego oka, a wtedy przejrzysz, aby wyjąć źdźbło, które jest w oku twego brata.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 43, 'Nie jest bowiem dobre to drzewo, które wydaje zły owoc, ani złe to drzewo, które wydaje dobry owoc.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 44, 'Gdyż każde drzewo poznaje się po jego owocu. Nie zbiera się bowiem fig z cierni ani winogron z głogu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 45, 'Dobry człowiek z dobrego skarbca swego serca wydobywa dobre rzeczy, a zły człowiek ze złego skarbca swego serca wydobywa złe rzeczy. Z obfitości serca bowiem mówią jego usta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 46, 'Dlaczego więc mówicie do mnie: Panie, Panie, a nie robicie tego, co mówię?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 47, 'Pokażę wam, do kogo jest podobny każdy, kto przychodzi do mnie, słucha moich słów i wypełnia je.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 48, 'Podobny jest do człowieka budującego dom, który zrobił głęboki wykop i założył fundament na skale. A gdy przyszła powódź, rzeka uderzyła w ten dom, ale nie mogła go poruszyć, bo był założony na skale.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 49, 'Ten zaś, kto słucha, a nie wypełnia, podobny jest do człowieka, który zbudował swój dom na ziemi bez fundamentu. Uderzyła w niego rzeka i natychmiast się zawalił, a upadek tego domu był wielki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 1, 'Gdy skończył mówić wszystkie te słowa w obecności ludzi, wszedł do Kafarnaum.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 2, 'A sługa pewnego setnika, bardzo przez niego ceniony, chorował i był bliski śmierci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 3, 'Kiedy setnik usłyszał o Jezusie, posłał do niego starszych spośród Żydów, prosząc, aby przyszedł i uzdrowił jego sługę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 4, 'A oni przyszli do Jezusa i prosili go usilnie: Godny jest, abyś mu to uczynił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 5, 'Miłuje bowiem nasz naród i zbudował nam synagogę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 6, 'Wtedy Jezus poszedł z nimi. Ale gdy był już niedaleko domu, setnik posłał do niego przyjaciół ze słowami: Panie, nie trudź się, bo nie jestem godny, abyś wszedł pod mój dach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 7, 'Dlatego i samego siebie nie uważałem za godnego przyjść do ciebie. Lecz powiedz słowo, a mój sługa zostanie uzdrowiony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 8, 'Bo i ja jestem człowiekiem podległym władzy i mam pod sobą żołnierzy, i mówię jednemu: Idź, a idzie, a drugiemu: Chodź tu, a przychodzi, a mojemu słudze: Zrób to, a robi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 9, 'Gdy Jezus to usłyszał, zdziwił się i odwróciwszy się, powiedział do ludzi, którzy szli za nim: Mówię wam, nawet w Izraelu nie znalazłem tak wielkiej wiary.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 10, 'Ci zaś, którzy byli posłani, po powrocie do domu zastali zdrowym sługę, który chorował.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 11, 'A nazajutrz udał się do miasta zwanego Nain. I szło z nim wielu jego uczniów i mnóstwo ludzi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 12, 'A gdy zbliżył się do bramy miasta, właśnie wynoszono zmarłego, jedynego syna matki, która była wdową. Towarzyszyło jej mnóstwo ludzi z miasta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 13, 'Kiedy Pan ją zobaczył, ulitował się nad nią i powiedział do niej: Nie płacz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 14, 'Potem podszedł i dotknął mar, a ci, którzy je nieśli, stanęli. I powiedział: Młodzieńcze, mówię ci, wstań!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 15, 'A ten, który był martwy, usiadł i zaczął mówić. I oddał go jego matce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 16, 'Wtedy wszystkich ogarnął strach i wielbili Boga, mówiąc: Wielki prorok powstał wśród nas, oraz: Bóg nawiedził swój lud.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 17, 'I rozeszła się ta wieść o nim po całej Judei i po całej okolicznej krainie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 18, 'O tym wszystkim oznajmili Janowi jego uczniowie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 19, 'A Jan, wezwawszy dwóch spośród swoich uczniów, posłał ich do Jezusa z zapytaniem: Czy ty jesteś tym, który ma przyjść, czy mamy oczekiwać innego?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 20, 'A gdy ci mężczyźni przyszli do niego, powiedzieli: Jan Chrzciciel przysłał nas do ciebie z zapytaniem: Czy ty jesteś tym, który ma przyjść, czy mamy oczekiwać innego?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 21, 'A w tym właśnie czasie wielu uzdrowił z chorób i dolegliwości i uwolnił od złych duchów, a wielu ślepych obdarzył wzrokiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 22, 'Jezus więc odpowiedział im: Idźcie i oznajmijcie Janowi to, co widzieliście i słyszeliście: Ślepi widzą, chromi chodzą, trędowaci zostają oczyszczeni, głusi słyszą, umarli zmartwychwstają, a ubogim głoszona jest ewangelia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 23, 'A błogosławiony jest ten, kto się nie zgorszy z mojego powodu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 24, 'Gdy zaś posłańcy Jana odeszli, zaczął mówić do ludzi o Janie: Co wyszliście zobaczyć na pustyni? Trzcinę kołyszącą się na wietrze?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 25, 'Ale co wyszliście zobaczyć? Człowieka ubranego w miękkie szaty? Oto ci, którzy noszą kosztowne szaty i żyją w rozkoszach, są w domach królewskich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 26, 'Ale co wyszliście zobaczyć? Proroka? Tak, mówię wam, nawet więcej niż proroka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 27, 'On jest tym, o którym jest napisane: Oto posyłam mego posłańca przed twoim obliczem, który przygotuje twoją drogę przed tobą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 28, 'Mówię wam bowiem: Nie ma wśród narodzonych z kobiet większego proroka od Jana Chrzciciela. Lecz ten, kto jest najmniejszy w królestwie Bożym, jest większy niż on.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 29, 'Słysząc to, wszyscy ludzie, jak również celnicy, przyznawali słuszność Bogu, będąc ochrzczeni chrztem Jana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 30, 'Ale faryzeusze i znawcy prawa odrzucili radę Boga sami przeciwko sobie, nie dając się przez niego ochrzcić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 31, 'I powiedział Pan: Do kogo więc przyrównam ludzi tego pokolenia? Do kogo są podobni?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 32, 'Podobni są do dzieci, które siedzą na rynku i wołają jedne na drugie: Graliśmy wam na flecie, a nie tańczyliście, śpiewaliśmy pieśni żałobne, a nie płakaliście.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 33, 'Przyszedł bowiem Jan Chrzciciel, nie jadł chleba i nie pił wina, a mówicie: Ma demona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 34, 'Przyszedł Syn Człowieczy, jedząc i pijąc, a mówicie: Oto żarłok i pijak, przyjaciel celników i grzeszników.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 35, 'Lecz usprawiedliwiona jest mądrość przez wszystkie swoje dzieci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 36, 'I zaprosił go jeden z faryzeuszy na wspólny posiłek. Wszedł więc do domu faryzeusza i usiadł przy stole.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 37, 'A oto kobieta, grzesznica, która była w tym mieście, dowiedziawszy się, że siedzi przy stole w domu faryzeusza, przyniosła alabastrowe naczynie olejku;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 38, 'I stanąwszy z tyłu u jego nóg, płacząc, zaczęła łzami obmywać jego nogi, wycierała je włosami swojej głowy, całowała i namaszczała olejkiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 39, 'A widząc to, faryzeusz, który go zaprosił, pomyślał sobie: Gdyby on był prorokiem, wiedziałby, kim i jaka jest ta kobieta, która go dotyka. Jest bowiem grzesznicą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 40, 'A Jezus odezwał się do niego: Szymonie, mam ci coś do powiedzenia. A on odrzekł: Powiedz, Nauczycielu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 41, 'Pewien wierzyciel miał dwóch dłużników. Jeden był winien pięćset groszy, a drugi pięćdziesiąt.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 42, 'A gdy nie mieli z czego oddać, darował obydwóm. Powiedz więc, który z nich będzie go bardziej miłował?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 43, 'Szymon odpowiedział: Sądzę, że ten, któremu więcej darował. A on mu powiedział: Słusznie osądziłeś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 44, 'I odwróciwszy się do kobiety, powiedział do Szymona: Widzisz tę kobietę? Wszedłem do twego domu, a nie podałeś mi wody do nóg, ona zaś łzami obmyła moje nogi i otarła je swoimi włosami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 45, 'Nie pocałowałeś mnie, a ona, odkąd wszedłem, nie przestała całować moich nóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 46, 'Nie namaściłeś mi głowy oliwą, a ona olejkiem namaściła moje nogi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 47, 'Dlatego mówię ci: Przebaczono jej wiele grzechów, gdyż bardzo umiłowała. A komu mało przebaczono, mało miłuje.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 48, 'Do niej zaś powiedział: Twoje grzechy są przebaczone.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 49, 'Wtedy współbiesiadnicy zaczęli mówić między sobą: Kim jest ten, który i grzechy przebacza?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 50, 'I powiedział do kobiety: Twoja wiara cię zbawiła. Idź w pokoju.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 1, 'Następnie chodził po miastach i po wioskach, głosząc i opowiadając ewangelię królestwa Bożego. A było z nim dwunastu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 2, 'I kilka kobiet, które uwolnił od złych duchów i chorób: Maria, zwana Magdaleną, z której wyszło siedem demonów;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 3, 'Joanna, żona Chuzy, zarządcy u Heroda, Zuzanna i wiele innych, które służyły mu swoimi dobrami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 4, 'A gdy zeszło się wielu ludzi i z różnych miast przychodzili do niego, powiedział w przypowieści:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 5, 'Siewca wyszedł siać swoje ziarno. A gdy siał, jedno padło przy drodze i zostało podeptane, a ptaki niebieskie wydziobały je.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 6, 'Inne padło na skałę, a gdy wzeszło, uschło, bo nie miało wilgoci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 7, 'Inne zaś padło między ciernie, ale ciernie razem z nim wyrosły i zagłuszyły je.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 8, 'A jeszcze inne padło na dobrą ziemię, a gdy wzrosło, wydało plon stokrotny. To powiedziawszy, zawołał: Kto ma uszy do słuchania, niech słucha.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 9, 'I pytali go jego uczniowie: Co znaczy ta przypowieść?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 10, 'A on im powiedział: Wam dano poznać tajemnice królestwa Bożego, ale innym opowiada się w przypowieściach, aby patrząc, nie widzieli i słysząc, nie rozumieli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 11, 'A takie jest znaczenie przypowieści: Ziarnem jest słowo Boże.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 12, 'Tymi przy drodze są ci, którzy słuchają; potem przychodzi diabeł i zabiera słowo z ich serca, aby nie uwierzyli i nie zostali zbawieni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 13, 'A tymi na skale są ci, którzy, gdy usłyszą, z radością przyjmują słowo. Nie mają jednak korzenia, wierzą do czasu, a w chwili pokusy odstępują.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 14, 'To zaś, które padło między ciernie, to są ci, którzy słuchają słowa, ale odchodzą i przez troski, bogactwa i rozkosze życia zostają zagłuszeni i nie wydają owocu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 15, 'Lecz to, które padło na dobrą ziemię, to są ci, którzy szczerym i dobrym sercem usłyszeli słowo i zachowują je, i wydają owoc w cierpliwości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 16, 'Nikt, zapaliwszy świecę, nie nakrywa jej naczyniem i nie stawia pod łóżkiem, ale na świeczniku, aby ci, którzy wchodzą, widzieli światło.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 17, 'Nie ma bowiem nic tajemnego, co by nie miało być ujawnione, ani nic ukrytego, o czym by się nie dowiedziano i co by nie wyszło na jaw.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 18, 'Uważajcie więc, jak słuchacie. Kto bowiem ma, temu będzie dodane, a kto nie ma, zostanie mu zabrane nawet to, co sądzi, że ma.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 19, 'Wtedy przyszli do niego jego matka i bracia, ale nie mogli podejść z powodu tłumu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 20, 'I dano mu znać, mówiąc: Twoja matka i twoi bracia stoją przed domem i chcą się z tobą widzieć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 21, 'A on im odpowiedział: Moją matką i moimi braćmi są ci, którzy słuchają słowa Bożego i wypełniają je.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 22, 'Pewnego dnia wsiadł do łodzi ze swymi uczniami i powiedział do nich: Przeprawmy się na drugą stronę jeziora. I odpłynęli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 23, 'A gdy płynęli, usnął. I zerwał się gwałtowny wicher na jeziorze, i zalewało łódź, tak że byli w niebezpieczeństwie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 24, 'Podeszli więc i obudzili go, mówiąc: Mistrzu, mistrzu, giniemy! Wówczas wstał, zgromił wiatr i wzburzone fale, a one się uspokoiły i nastała cisza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 25, 'Wtedy powiedział do nich: Gdzież jest wasza wiara? A oni, bojąc się, dziwili się i mówili między sobą: Kim on jest, że nawet wichrom i wodzie rozkazuje, a są mu posłuszne?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 26, 'I przeprawili się do krainy Gadareńczyków, która leży naprzeciw Galilei.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 27, 'A gdy wyszedł na ląd, zabiegł mu drogę pewien człowiek z miasta, który od dłuższego czasu miał demony. Nie nosił ubrania i nie mieszkał w domu, lecz w grobowcach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 28, 'Gdy zobaczył Jezusa, krzyknął, upadł przed nim i zawołał donośnym głosem: Cóż ja mam z tobą, Jezusie, Synu Boga Najwyższego? Proszę cię, nie dręcz mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 29, 'Rozkazał bowiem duchowi nieczystemu, aby wyszedł z tego człowieka. Bo od dłuższego czasu porywał go, a chociaż wiązano go łańcuchami i trzymano w pętach, on rwał więzy, a demon pędził go na pustynię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 30, 'I zapytał go Jezus: Jak ci na imię? A on odpowiedział: Legion. Wiele bowiem demonów weszło w niego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 31, 'Wtedy prosiły go, aby nie kazał im odejść stamtąd w otchłań.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 32, 'A było tam wielkie stado świń, które pasły się na górze. I demony prosiły go, aby pozwolił im w nie wejść. I pozwolił im.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 33, 'Wtedy demony wyszły z tego człowieka i weszły w świnie. I ruszyło to stado pędem po urwisku do jeziora, i utonęło.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 34, 'A pasterze, widząc, co się stało, uciekli, a poszedłszy, oznajmili to w mieście i we wsiach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 35, 'I wyszli ludzie, aby zobaczyć, co zaszło, a przyszedłszy do Jezusa, zastali człowieka, z którego wyszły demony, ubranego i przy zdrowych zmysłach, siedzącego u stóp Jezusa. I przestraszyli się.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 36, 'A ci, którzy to widzieli, opowiedzieli im, jak ten opętany został uzdrowiony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 37, 'Wówczas cała ludność okolicznej krainy Gadareńczyków prosiła go, aby od nich odszedł, gdyż ogarnął ich wielki strach. Wtedy on wsiadł do łodzi i zawrócił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 38, 'A człowiek, z którego wyszły demony, prosił go, aby mógł przy nim zostać. Lecz Jezus odprawił go, mówiąc:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 39, 'Wróć do swego domu i opowiedz, jak wielkie rzeczy Bóg ci uczynił. I odszedł, opowiadając po całym mieście, jak wielkie rzeczy Jezus mu uczynił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 40, 'A gdy Jezus wrócił, ludzie przyjęli go z radością. Wszyscy bowiem go oczekiwali.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 41, 'A oto przyszedł człowiek imieniem Jair, który był przełożonym synagogi. Upadł Jezusowi do nóg i prosił go, aby wszedł do jego domu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 42, 'Miał bowiem córkę jedynaczkę, mającą około dwunastu lat, która umierała. A gdy on szedł, ludzie napierali na niego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 43, 'A kobieta, która od dwunastu lat cierpiała na krwotok i wydała na lekarzy całe swoje mienie, a żaden nie mógł jej uleczyć;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 44, 'Podeszła z tyłu, dotknęła brzegu jego szaty i natychmiast ustał jej krwotok.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 45, 'Wtedy Jezus zapytał: Kto mnie dotknął? A gdy wszyscy się wypierali, Piotr i ci, którzy z nim byli, powiedzieli: Mistrzu, ludzie się do ciebie cisną i tłoczą, a ty pytasz: Kto mnie dotknął?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 46, 'Jezus jednak powiedział: Ktoś mnie dotknął, bo poczułem, że moc wyszła ze mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 47, 'Wtedy kobieta, widząc, że się nie ukryje, z drżeniem podeszła i upadłszy przed nim, powiedziała wobec wszystkich ludzi, dlaczego go dotknęła i jak natychmiast została uzdrowiona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 48, 'On zaś powiedział do niej: Ufaj, córko! Twoja wiara cię uzdrowiła, idź w pokoju.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 49, 'A gdy on jeszcze to mówił, przyszedł ktoś z domu przełożonego synagogi i powiedział: Twoja córka umarła, nie trudź Nauczyciela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 50, 'Ale Jezus, słysząc to, odezwał się do niego: Nie bój się, tylko wierz, a będzie uzdrowiona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 51, 'Gdy przyszedł do domu, nie pozwolił wejść ze sobą nikomu oprócz Piotra, Jakuba i Jana oraz ojca i matki dziewczynki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 52, 'A wszyscy płakali i lamentowali nad nią. Lecz on powiedział: Nie płaczcie, nie umarła, tylko śpi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 53, 'I naśmiewali się z niego, wiedząc, że umarła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 54, 'A on wyrzucił wszystkich, ujął ją za rękę i zawołał: Dziewczynko, wstań!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 55, 'Wtedy jej duch powrócił i zaraz wstała, a on polecił, aby dano jej jeść.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 56, 'I zdumieli się jej rodzice. A on im nakazał, aby nikomu nie mówili o tym, co się stało.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 1, 'A Jezus, przywoławszy swoich dwunastu uczniów, dał im moc i władzę nad wszystkimi demonami i moc, aby uzdrawiali choroby.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 2, 'I rozesłał ich, żeby głosili królestwo Boże i uzdrawiali chorych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 3, 'Powiedział też do nich: Nie bierzcie nic na drogę: ani laski, ani torby, ani chleba, ani pieniędzy i nie miejcie dwóch szat.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 4, 'A gdy wejdziecie do jakiegoś domu, tam pozostańcie i stamtąd wychodźcie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 5, 'A jeśli was nie przyjmą, wychodząc z tego miasta, strząśnijcie pył z waszych nóg na świadectwo przeciwko nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 6, 'Wyszedłszy więc, obchodzili wszystkie miasteczka, głosząc ewangelię i uzdrawiając wszędzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 7, 'A o wszystkim, co się przez niego dokonywało, usłyszał tetrarcha Herod i zaniepokoił się, ponieważ niektórzy mówili, że Jan zmartwychwstał;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 8, 'Inni zaś, że Eliasz się pojawił, a jeszcze inni, że zmartwychwstał któryś z dawnych proroków.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 9, 'A Herod powiedział: Jana ściąłem. Kim więc jest ten, o którym słyszę takie rzeczy? I chciał go zobaczyć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 10, 'Kiedy apostołowie wrócili, opowiedzieli mu wszystko, co uczynili. A on, wziąwszy ich ze sobą, odszedł osobno na odludne miejsce koło miasta zwanego Betsaidą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 11, 'Gdy ludzie się o tym dowiedzieli, poszli za nim. On ich przyjął i mówił im o królestwie Bożym, i uzdrawiał tych, którzy potrzebowali uzdrowienia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 12, 'A gdy dzień zaczął się chylić ku wieczorowi, podeszło do niego dwunastu, mówiąc: Odpraw tłum, aby poszli do okolicznych miasteczek i wsi i znaleźli żywność oraz schronienie, bo jesteśmy tu na pustkowiu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 13, 'Ale on powiedział do nich: Wy dajcie im jeść. A oni odpowiedzieli: Nie mamy nic więcej oprócz pięciu chlebów i dwóch ryb; chyba że pójdziemy i kupimy jedzenie dla tych wszystkich ludzi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 14, 'Mężczyzn bowiem było około pięciu tysięcy. I powiedział do swoich uczniów: Rozkażcie im usiąść w grupach po pięćdziesięciu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 15, 'Uczynili tak i usadowili wszystkich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 16, 'A on, wziąwszy te pięć chlebów i dwie ryby, spojrzał w niebo, pobłogosławił je, łamał i dawał uczniom, aby kładli przed ludźmi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 17, 'I jedli wszyscy do syta. A z kawałków, które im pozostały, zebrano dwanaście koszy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 18, 'I stało się tak, że kiedy modlił się na osobności, a byli z nim uczniowie, zapytał ich: Za kogo mnie ludzie uważają?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 19, 'A oni odpowiedzieli: Za Jana Chrzciciela, inni za Eliasza, a jeszcze inni mówią, że zmartwychwstał któryś z dawnych proroków.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 20, 'I powiedział do nich: A wy za kogo mnie uważacie? A Piotr odpowiedział: Za Chrystusa Bożego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 21, 'Ale on surowo ich napomniał i nakazał, aby nikomu tego nie mówili.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 22, 'I powiedział: Syn Człowieczy musi wiele cierpieć i zostać odrzucony przez starszych, naczelnych kapłanów i uczonych w Piśmie, i być zabity, a trzeciego dnia zmartwychwstać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 23, 'Mówił też do wszystkich: Jeśli ktoś chce pójść za mną, niech się wyprze samego siebie, niech bierze swój krzyż każdego dnia i idzie za mną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 24, 'Kto bowiem chce zachować swoje życie, straci je, a kto straci swe życie z mojego powodu, ten je zachowa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 25, 'Bo cóż pomoże człowiekowi, choćby cały świat pozyskał, jeśli samego siebie zatraci lub szkodę poniesie?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 26, 'Kto bowiem wstydzi się mnie i moich słów, tego Syn Człowieczy będzie się wstydził, gdy przyjdzie w chwale swojej, Ojca i świętych aniołów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 27, 'Ale zapewniam was: Niektórzy z tych, co tu stoją, nie zakosztują śmierci, dopóki nie ujrzą królestwa Bożego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 28, 'W jakieś osiem dni po tych mowach wziął ze sobą Piotra, Jana i Jakuba i wszedł na górę, aby się modlić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 29, 'A gdy się modlił, zmienił się wygląd jego oblicza, a jego szaty stały się białe i lśniące.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 30, 'A oto rozmawiało z nim dwóch mężów. Byli to Mojżesz i Eliasz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 31, 'Ukazali się oni w chwale i mówili o jego odejściu, którego miał dokonać w Jerozolimie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 32, 'A Piotra i tych, którzy z nim byli, zmógł sen. Gdy się obudzili, ujrzeli jego chwałę i tych dwóch mężów, którzy z nim stali.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 33, 'Kiedy oni od niego odeszli, Piotr powiedział do Jezusa: Mistrzu, dobrze nam tu być. Postawmy więc trzy namioty: jeden dla ciebie, jeden dla Mojżesza i jeden dla Eliasza. Nie wiedział bowiem, co mówi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 34, 'A gdy on to mówił, pojawił się obłok i zacienił ich. I zlękli się, kiedy oni wchodzili w obłok.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 35, 'I rozległ się głos z obłoku: To jest mój umiłowany Syn, jego słuchajcie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 36, 'Gdy zaś ten głos się rozległ, okazało się, że Jezus jest sam. A oni milczeli i w tych dniach nikomu nie mówili nic o tym, co widzieli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 37, 'Nazajutrz, gdy zeszli z góry, mnóstwo ludzi wyszło mu naprzeciw.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 38, 'Nagle jakiś człowiek z tłumu zawołał: Nauczycielu, proszę cię, spójrz na mego syna, bo to mój jedynak.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 39, 'I oto duch dopada go, a on nagle krzyczy. Szarpie nim tak, że się pieni i potłukłszy go, niechętnie od niego odchodzi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 40, 'I prosiłem twoich uczniów, aby go wypędzili, ale nie mogli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 41, 'Wtedy Jezus odpowiedział: O pokolenie bez wiary i przewrotne! Jak długo będę z wami i jak długo mam was znosić? Przyprowadź tu swego syna.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 42, 'A gdy on jeszcze podchodził, powalił go demon i zaczął nim targać. Lecz Jezus zgromił ducha nieczystego, uzdrowił chłopca i oddał go jego ojcu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 43, 'I zdumieli się wszyscy potęgą Boga. A gdy się dziwili wszystkiemu, co czynił Jezus, on powiedział do swoich uczniów:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 44, 'Przyjmijcie te słowa do waszych uszu, Syn Człowieczy bowiem będzie wydany w ręce ludzi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 45, 'Lecz oni nie zrozumieli tych słów i były one zakryte przed nimi, tak że ich nie pojęli, a bali się go o nie zapytać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 46, 'Wszczęła się też między nimi dyskusja o tym, kto z nich jest największy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 47, 'A Jezus, znając tę myśl ich serca, wziął dziecko, postawił je przy sobie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 48, 'I powiedział do nich: Kto przyjmie to dziecko w moje imię, mnie przyjmuje, a kto mnie przyjmie, przyjmuje tego, który mnie posłał. Kto bowiem jest najmniejszy wśród was wszystkich, ten będzie wielki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 49, 'Wtedy odezwał się Jan: Mistrzu, widzieliśmy kogoś, kto w twoim imieniu wypędzał demony i zabranialiśmy mu, bo nie chodzi z nami za tobą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 50, 'I powiedział do niego Jezus: Nie zabraniajcie mu, bo kto nie jest przeciwko nam, ten jest z nami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 51, 'A gdy wypełniły się dni, aby został wzięty w górę, mocno postanowił udać się do Jerozolimy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 52, 'I wysłał przed sobą posłańców. Poszli więc i weszli do wioski Samarytan, aby przygotować dla niego miejsce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 53, 'Lecz nie przyjęto go, ponieważ zmierzał do Jerozolimy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 54, 'A jego uczniowie Jakub i Jan, widząc to, powiedzieli: Panie, czy chcesz, żebyśmy rozkazali, aby ogień zstąpił z nieba i pochłonął ich, jak to uczynił Eliasz?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 55, 'Lecz Jezus, odwróciwszy się, zgromił ich i powiedział: Nie wiecie, jakiego jesteście ducha.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 56, 'Syn Człowieczy bowiem nie przyszedł zatracać dusz ludzkich, ale je zbawić. I poszli do innej wioski.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 57, 'Kiedy byli w drodze, ktoś powiedział do niego: Panie, pójdę za tobą, dokądkolwiek się udasz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 58, 'Jezus mu odpowiedział: Lisy mają nory, a ptaki niebieskie – gniazda, ale Syn Człowieczy nie ma gdzie położyć głowy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 59, 'Do innego zaś powiedział: Pójdź za mną! Ale on rzekł: Panie, pozwól mi najpierw odejść i pogrzebać mego ojca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 60, 'Lecz Jezus mu odpowiedział: Niech umarli grzebią swoich umarłych, a ty idź i głoś królestwo Boże.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 61, 'Jeszcze inny powiedział: Pójdę za tobą, Panie, ale pozwól mi najpierw pożegnać się z tymi, którzy są w moim domu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 62, 'Jezus mu odpowiedział: Nikt, kto przykłada swoją rękę do pługa i ogląda się wstecz, nie nadaje się do królestwa Bożego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 1, 'A potem Pan wyznaczył jeszcze innych siedemdziesięciu i rozesłał ich po dwóch przed sobą do każdego miasta i miejsca, do którego sam miał przyjść.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 2, 'I mówił im: Żniwo wprawdzie wielkie, ale robotników mało. Proście więc Pana żniwa, aby wysłał robotników na swoje żniwo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 3, 'Idźcie! Oto posyłam was jak baranki między wilki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 4, 'Nie noście ze sobą sakiewki ani torby, ani obuwia. Nikogo też w drodze nie pozdrawiajcie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 5, 'A gdy wejdziecie do jakiegoś domu, najpierw mówcie: Pokój temu domowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 6, 'Jeśli tam będzie syn pokoju, wasz pokój spocznie na nim, a jeśli nie – wróci do was.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 7, 'W tym domu zostańcie, jedząc i pijąc, co mają. Godny jest bowiem robotnik swojej zapłaty. Nie przenoście się z domu do domu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 8, 'A gdy wejdziecie do jakiegoś miasta i przyjmą was, jedzcie, co przed wami położą;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 9, 'I uzdrawiajcie chorych, którzy w nim są, i mówcie im: Przybliżyło się do was królestwo Boże.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 10, 'A jeśli wejdziecie do jakiegoś miasta, a nie przyjmą was, wyjdźcie na jego ulice i mówcie:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 11, 'Nawet pył z waszego miasta, który przylgnął do nas, strząsamy na was. Jednak wiedzcie, że przybliżyło się do was królestwo Boże.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 12, 'A mówię wam, że w ten dzień lżej będzie Sodomie niż temu miastu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 13, 'Biada tobie, Korozain! Biada tobie, Betsaido! Bo gdyby w Tyrze i Sydonie działy się te cuda, które się u was dokonały, dawno by pokutowały, siedząc w worze i popiele.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 14, 'Dlatego Tyrowi i Sydonowi lżej będzie na sądzie niż wam.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 15, 'A ty, Kafarnaum, które jesteś aż do nieba wywyższone, aż do piekła będziesz strącone.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 16, 'Kto was słucha, mnie słucha, a kto wami gardzi, mną gardzi. Kto zaś mną gardzi, gardzi tym, który mnie posłał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 17, 'I siedemdziesięciu wróciło z radością, mówiąc: Panie, nawet demony nam się poddają ze względu na twoje imię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 18, 'Wtedy powiedział do nich: Widziałem szatana spadającego z nieba jak błyskawica.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 19, 'Oto daję wam moc stąpania po wężach, skorpionach i po wszelkiej mocy nieprzyjaciela, a nic wam nie zaszkodzi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 20, 'Jednak nie z tego się cieszcie, że duchy się wam poddają, ale cieszcie się raczej, że wasze imiona są zapisane w niebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 21, 'W tej godzinie Jezus rozradował się w duchu i powiedział: Wysławiam cię, Ojcze, Panie nieba i ziemi, że zakryłeś te sprawy przed mądrymi i roztropnymi, a objawiłeś je niemowlętom. Tak, Ojcze, bo tak się tobie upodobało.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 22, 'Wszystko zostało mi przekazane od mego Ojca i nikt nie wie, kim jest Syn, tylko Ojciec, ani kim jest Ojciec, tylko Syn i ten, komu Syn zechce objawić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 23, 'Wtedy odwrócił się do uczniów i powiedział do nich na osobności: Błogosławione oczy, które widzą to, co wy widzicie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 24, 'Bo mówię wam, że wielu proroków i królów pragnęło widzieć to, co wy widzicie, a nie zobaczyli, i słyszeć to, co wy słyszycie, a nie usłyszeli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 25, 'A oto powstał pewien znawca prawa i wystawiając go na próbę, zapytał: Nauczycielu, co mam czynić, aby odziedziczyć życie wieczne?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 26, 'A on powiedział do niego: Co jest napisane w Prawie? Jak czytasz?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 27, 'A on odpowiedział: Będziesz miłował Pana, swego Boga, całym swym sercem, całą swą duszą, z całej swojej siły i całym swym umysłem, a swego bliźniego jak samego siebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 28, 'I powiedział mu: Dobrze odpowiedziałeś. Czyń to, a będziesz żył.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 29, 'On zaś, chcąc się usprawiedliwić, powiedział do Jezusa: A kto jest moim bliźnim?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 30, 'Lecz Jezus odpowiedział: Pewien człowiek schodził z Jerozolimy do Jerycha i wpadł w ręce bandytów, którzy go obrabowali, poranili i odeszli, zostawiając na pół umarłego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 31, 'A przypadkiem szedł tą drogą pewien kapłan; zobaczył go i ominął.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 32, 'Podobnie i Lewita, gdy dotarł na to miejsce, podszedł, zobaczył go i ominął.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 33, 'Lecz pewien Samarytanin, będąc w podróży, zbliżył się do niego. A gdy go zobaczył, ulitował się nad nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 34, 'A podszedłszy, opatrzył mu rany, zalewając je oliwą i winem; potem wsadził go na swoje zwierzę, zawiózł do gospody i opiekował się nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 35, 'A nazajutrz, odjeżdżając, wyjął dwa grosze, dał gospodarzowi i powiedział: Opiekuj się nim, a wszystko, co wydasz ponad to, oddam ci, gdy wrócę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 36, 'Który z tych trzech, twoim zdaniem, był bliźnim tego, który wpadł w ręce bandytów?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 37, 'A on odpowiedział: Ten, który okazał mu miłosierdzie. Wtedy Jezus mu powiedział: Idź i ty czyń podobnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 38, 'A gdy szli, wszedł do jednej wsi. Tam pewna kobieta, imieniem Marta, przyjęła go do swego domu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 39, 'Miała ona siostrę, zwaną Marią, która usiadła u nóg Jezusa i słuchała jego słów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 40, 'Ale Marta krzątała się koło rozmaitych posług, a podszedłszy, powiedziała: Panie, czy nie obchodzi cię, że moja siostra zostawiła mnie samą przy usługiwaniu? Powiedz jej, aby mi pomogła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 41, 'A Jezus jej odpowiedział: Marto, Marto, troszczysz się i martwisz o wiele spraw;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 42, 'Ale jedno jest potrzebne. Maria wybrała dobrą cząstkę, która nie będzie jej odebrana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 1, 'A gdy przebywał w jakimś miejscu na modlitwie i skończył ją, jeden z jego uczniów powiedział do niego: Panie, naucz nas się modlić, tak jak i Jan nauczył swoich uczniów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 2, 'I powiedział do nich: Gdy się modlicie, mówcie: Ojcze nasz, który jesteś w niebie, niech będzie uświęcone twoje imię. Niech przyjdzie twoje królestwo. Niech się dzieje twoja wola na ziemi, tak jak w niebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 3, 'Dawaj nam każdego dnia naszego powszedniego chleba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 4, 'Przebacz nam nasze grzechy, bo i my przebaczamy każdemu, kto przeciwko nam zawinił. I nie wystawiaj nas na pokusę, ale wybaw nas od złego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 5, 'I powiedział do nich: Któż z was, mając przyjaciela, pójdzie do niego o północy i powie mu: Przyjacielu, pożycz mi trzy chleby;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 6, 'Mój przyjaciel bowiem przyszedł do mnie z drogi, a nie mam mu co podać?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 7, 'A on z wewnątrz odpowie: Nie naprzykrzaj mi się. Drzwi są już zamknięte i moje dzieci są ze mną w łóżku. Nie mogę wstać i dać ci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 8, 'Mówię wam: Chociażby nie wstał i nie dał mu dlatego, że jest jego przyjacielem, jednak z powodu jego natarczywości wstanie i da mu, ile potrzebuje.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 9, 'I ja wam mówię: Proście, a będzie wam dane, szukajcie, a znajdziecie, pukajcie, a będzie wam otworzone.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 10, 'Każdy bowiem, kto prosi, otrzymuje, a kto szuka, znajduje, a temu, kto puka, będzie otworzone.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 11, 'I czy jest wśród was ojciec, który, gdy syn prosi go o chleb, da mu kamień? Albo gdy prosi o rybę, czy zamiast ryby da mu węża?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 12, 'Albo gdy prosi o jajko, czy da mu skorpiona?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 13, 'Jeśli więc wy, będąc złymi, umiecie dawać dobre dary waszym dzieciom, o ileż bardziej wasz Ojciec niebieski da Ducha Świętego tym, którzy go proszą?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 14, 'I wypędzał demona, który był niemy. A gdy demon wyszedł, niemy przemówił, a ludzie się dziwili.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 15, 'Lecz niektórzy z nich mówili: Przez Belzebuba, władcę demonów, wypędza demony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 16, 'Inni zaś, wystawiając go na próbę, żądali od niego znaku z nieba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 17, 'Ale on, znając ich myśli, powiedział do nich: Każde królestwo podzielone wewnętrznie pustoszeje, a dom skłócony sam ze sobą upada.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 18, 'Jeśli i szatan jest wewnętrznie podzielony, jakże przetrwa jego królestwo? Mówicie bowiem, że ja przez Belzebuba wypędzam demony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 19, 'A jeśli ja przez Belzebuba wypędzam demony, to przez kogo wypędzają wasi synowie? Dlatego oni będą waszymi sędziami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 20, 'Ale jeśli ja palcem Bożym wypędzam demony, to istotnie przyszło do was królestwo Boże.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 21, 'Gdy uzbrojony mocarz strzeże swego pałacu, bezpieczne jest jego mienie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 22, 'Lecz gdy mocniejszy od niego nadejdzie i zwycięży go, zabiera całą jego broń, na której polegał, i rozdaje jego łupy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 23, 'Kto nie jest ze mną, jest przeciwko mnie, a kto nie zbiera ze mną, rozprasza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 24, 'Gdy duch nieczysty wychodzi z człowieka, przechadza się po miejscach bezwodnych, szukając odpoczynku, a gdy nie znajduje, mówi: Wrócę do mego domu, skąd wyszedłem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 25, 'A przyszedłszy, zastaje go zamiecionym i przyozdobionym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 26, 'Wtedy idzie i bierze ze sobą siedem innych duchów, gorszych niż on sam, i wszedłszy, mieszkają tam. I końcowy stan tego człowieka staje się gorszy niż pierwszy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 27, 'A gdy on to mówił, pewna kobieta spośród zgromadzonych powiedziała do niego donośnym głosem: Błogosławione łono, które cię nosiło, i piersi, które ssałeś!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 28, 'On zaś odpowiedział: Błogosławieni są raczej ci, którzy słuchają słowa Bożego i strzegą go.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 29, 'A gdy ludzie się gromadzili, zaczął mówić: Pokolenie to jest złe. Żąda znaku, ale żaden znak nie będzie mu dany, oprócz znaku proroka Jonasza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 30, 'Jak bowiem Jonasz był znakiem dla mieszkańców Niniwy, tak będzie i Syn Człowieczy dla tego pokolenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 31, 'Królowa z południa stanie na sądzie z ludźmi tego pokolenia i potępi ich, bo przybyła z krańców ziemi, aby słuchać mądrości Salomona, a oto tu ktoś więcej niż Salomon.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 32, 'Ludzie z Niniwy staną na sądzie z tym pokoleniem i potępią je, ponieważ pokutowali na skutek głoszenia Jonasza, a oto tu ktoś więcej niż Jonasz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 33, 'Nikt nie zapala świecy i nie stawia jej w ukryciu ani pod naczyniem, ale na świeczniku, aby ci, którzy wchodzą, widzieli światło.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 34, 'Światłem ciała jest oko. Jeśli więc twoje oko jest szczere, to i całe twoje ciało będzie pełne światła, a jeśli jest złe, to i twoje ciało będzie pełne ciemności.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 35, 'Uważaj więc, aby światło, które jest w tobie, nie było ciemnością.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 36, 'Jeśli zatem całe twoje ciało będzie pełne światła, nie mając w sobie żadnej ciemnej cząstki, całe będzie tak pełne światła, jak gdy świeca oświetla cię swoim blaskiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 37, 'Kiedy to mówił, pewien faryzeusz poprosił go, aby zjadł u niego obiad. Wszedł więc i usiadł za stołem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 38, 'A faryzeusz, widząc to, dziwił się, że nie umył się przed obiadem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 39, 'Wtedy Pan powiedział do niego: Teraz wy, faryzeusze, oczyszczacie to, co jest na zewnątrz kubka i misy, ale to, co jest wewnątrz was, pełne jest zdzierstwa i nieprawości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 40, 'Głupcy, czyż ten, który uczynił to, co jest na zewnątrz, nie uczynił też tego, co jest wewnątrz?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 41, 'Raczej z tego, co jest wewnątrz, dawajcie jałmużnę, a wszystko będzie dla was czyste.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 42, 'Ale biada wam, faryzeusze, bo dajecie dziesięcinę z mięty, ruty i z każdego ziela, lecz opuszczacie sąd i miłość Boga. To należało czynić i tamtego nie opuszczać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 43, 'Biada wam, faryzeusze, bo kochacie pierwsze miejsca w synagogach i pozdrowienia na rynkach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 44, 'Biada wam, uczeni w Piśmie i faryzeusze, obłudnicy, bo jesteście jak groby, których nie widać, a ludzie, którzy chodzą po nich, nie wiedzą o tym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 45, 'I odezwał się jeden ze znawców prawa: Nauczycielu, mówiąc to, i nas znieważasz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 46, 'A on powiedział: I wam, znawcom prawa, biada, bo obciążacie ludzi brzemionami nie do uniesienia, a sami nawet jednym palcem tych brzemion nie dotykacie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 47, 'Biada wam, bo budujecie grobowce proroków, a wasi ojcowie ich pozabijali.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 48, 'Doprawdy świadczycie, że pochwalacie uczynki waszych ojców. Oni bowiem ich pozabijali, a wy budujecie ich grobowce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 49, 'Dlatego też mądrość Boża powiedziała: Poślę do nich proroków i apostołów, a niektórych z nich będą zabijać i prześladować;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 50, 'Aby dopominano się od tego pokolenia krwi wszystkich proroków, która została przelana od założenia świata;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 51, 'Od krwi Abla aż do krwi Zachariasza, który zginął między ołtarzem a świątynią. Doprawdy, mówię wam, dopominać się jej będą od tego pokolenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 52, 'Biada wam, znawcom prawa, bo zabraliście klucz poznania. Sami nie weszliście i tym, którzy chcieli wejść, przeszkodziliście.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 53, 'A gdy im to mówił, uczeni w Piśmie i faryzeusze zaczęli bardzo na niego nastawać i prowokować go do mówienia o wielu rzeczach;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 54, 'Czyhając na niego i próbując wychwycić coś z jego słów, żeby go oskarżyć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 1, 'Tymczasem, gdy zgromadziły się wielotysięczne tłumy, tak że jedni po drugich deptali, zaczął mówić najpierw do swoich uczniów: Strzeżcie się zakwasu faryzeuszy, którym jest obłuda.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 2, 'Nie ma bowiem nic ukrytego, co by nie miało być ujawnione, ani nic tajemnego, o czym by się nie miano dowiedzieć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 3, 'Dlatego to, co mówiliście w ciemności, będzie słyszane w świetle, a to, co szeptaliście do ucha w pokojach, będzie rozgłaszane na dachach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 4, 'A mówię wam, moim przyjaciołom: Nie bójcie się tych, którzy zabijają ciało, a potem już nic więcej nie mogą zrobić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 5, 'Ale pokażę wam, kogo macie się bać. Bójcie się tego, który, gdy zabije, ma moc wrzucić do ognia piekielnego. Doprawdy, mówię wam, tego się bójcie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 6, 'Czy nie sprzedają pięciu wróbli za dwa pieniążki? A jednak żaden z nich nie jest zapomniany w oczach Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 7, 'Nawet włosy na waszej głowie wszystkie są policzone. Dlatego nie bójcie się, jesteście cenniejsi niż wiele wróbli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 8, 'A mówię wam: Każdego, kto mnie wyzna przed ludźmi, tego też Syn Człowieczy wyzna przed aniołami Bożymi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 9, 'Ale kto się mnie wyprze przed ludźmi, tego też ja się wyprę przed aniołami Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 10, 'I każdemu, kto powie słowo przeciwko Synowi Człowieczemu, będzie przebaczone, ale temu, kto bluźni przeciwko Duchowi Świętemu, nie będzie przebaczone.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 11, 'A gdy będą was prowadzić do synagog, przełożonych i władz, nie martwcie się, jak i co macie odpowiedzieć na swoją obronę lub co macie mówić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 12, 'Duch Święty bowiem nauczy was w tej właśnie godzinie, co macie mówić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 13, 'I powiedział mu ktoś z tłumu: Nauczycielu, powiedz memu bratu, aby podzielił się ze mną spadkiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 14, 'Lecz on mu odpowiedział: Człowieku, któż mnie ustanowił sędzią albo rozjemcą między wami?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 15, 'Powiedział też do nich: Uważajcie i strzeżcie się chciwości, gdyż nie od tego, że ktoś ma obfitość dóbr, zależy jego życie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 16, 'I opowiedział im przypowieść: Pewnemu bogatemu człowiekowi pole przyniosło obfity plon.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 17, 'I rozważał w sobie: Cóż mam zrobić, skoro nie mam gdzie zgromadzić moich plonów?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 18, 'Powiedział więc: Zrobię tak: zburzę moje spichlerze, a zbuduję większe i zgromadzę tam wszystkie moje plony i moje dobra.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 19, 'I powiem mojej duszy: Duszo, masz wiele dóbr złożonych na wiele lat; odpoczywaj, jedz, pij i wesel się.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 20, 'Ale Bóg mu powiedział: Głupcze, tej nocy zażądają od ciebie twojej duszy, a to, co przygotowałeś, czyje będzie?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 21, 'Tak jest z każdym, kto gromadzi skarby dla siebie, a nie jest bogaty w Bogu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 22, 'Potem powiedział do swoich uczniów: Dlatego mówię wam: Nie troszczcie się o wasze życie, co będziecie jeść, ani o ciało, w co będziecie się ubierać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 23, 'Życie jest czymś więcej niż pokarm, a ciało niż ubranie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 24, 'Przypatrzcie się krukom, że nie sieją ani nie żną, nie mają spiżarni ani spichlerza, a jednak Bóg je żywi. O ileż cenniejsi jesteście wy niż ptaki!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 25, 'I któż z was, martwiąc się, może dodać do swego wzrostu jeden łokieć?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 26, 'Jeśli więc najmniejszej rzeczy nie możecie uczynić, czemu troszczycie się o inne?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 27, 'Przypatrzcie się liliom, jak rosną: nie pracują ani nie przędą, a mówię wam, że nawet Salomon w całej swojej chwale nie był tak ubrany, jak jedna z nich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 28, 'A jeśli trawę, która dziś jest na polu, a jutro będzie wrzucona do pieca, Bóg tak ubiera, o ileż bardziej was, ludzie małej wiary?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 29, 'Nie pytajcie więc, co będziecie jeść lub co będziecie pić, ani nie martwcie się o to.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 30, 'O to wszystko bowiem zabiegają narody świata. Lecz wasz Ojciec wie, że tego potrzebujecie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 31, 'Szukajcie raczej królestwa Bożego, a to wszystko będzie wam dodane.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 32, 'Nie bój się, mała trzódko, gdyż upodobało się waszemu Ojcu dać wam królestwo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 33, 'Sprzedawajcie, co posiadacie, i dawajcie jałmużnę. Przygotujcie sobie sakiewki, które nie starzeją się, skarb w niebie, którego nie ubywa, gdzie złodziej nie ma dostępu ani mól nie niszczy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 34, 'Bo gdzie jest wasz skarb, tam będzie też wasze serce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 35, 'Niech będą przepasane wasze biodra i zapalone lampy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 36, 'A wy bądźcie podobni do ludzi oczekujących swego pana, aż wróci z wesela, aby gdy przyjdzie i zapuka, zaraz mu otworzyć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 37, 'Błogosławieni ci słudzy, których pan, gdy przyjdzie, zastanie czuwających. Zaprawdę powiadam wam, że się przepasze i posadzi ich za stołem, a obchodząc, będzie im usługiwał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 38, 'Jeśli przyjdzie o drugiej czy o trzeciej straży i tak ich zastanie, błogosławieni są ci słudzy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 39, 'A to wiedzcie, że gdyby gospodarz znał godzinę, o której ma przyjść złodziej, czuwałby i nie pozwoliłby włamać się do swego domu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 40, 'Dlatego i wy bądźcie gotowi, bo Syn Człowieczy przyjdzie o godzinie, której się nie spodziewacie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 41, 'Wtedy Piotr go zapytał: Panie, czy tę przypowieść mówisz do nas, czy też do wszystkich?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 42, 'A Pan odpowiedział: Któż więc jest szafarzem wiernym i roztropnym, którego Pan ustanowi nad swoją służbą, aby we właściwym czasie wydawał jej wyznaczoną żywność?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 43, 'Błogosławiony ten sługa, którego pan, gdy przyjdzie, zastanie tak czyniącego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 44, 'Zaprawdę powiadam wam, że postawi go nad wszystkimi swoimi dobrami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 45, 'Ale jeśli ten sługa powie w swoim sercu: Mój pan zwleka ze swoim przyjściem, i zacznie bić sługi i służące, jeść, pić i upijać się;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 46, 'Przyjdzie pan tego sługi w dniu, w którym się nie spodziewa i o godzinie, której nie zna, i odłączy go, i wyznaczy mu dział z niewierzącymi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 47, 'Ten zaś sługa, który znał wolę swego pana, a nie był gotowy i nie postąpił według jego woli, otrzyma wielką chłostę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 48, 'Lecz ten, który jej nie znał i uczynił coś godnego kary, otrzyma małą chłostę. Komu wiele dano, od tego wiele się będzie wymagać, a komu wiele powierzono, więcej będzie się od niego żądać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 49, 'Przyszedłem, aby rzucić ogień na ziemię, i czegóż pragnę, skoro już zapłonął?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 50, 'Lecz chrztem mam być ochrzczony i jakże jestem udręczony, aż się to dopełni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 51, 'Czy myślicie, że przyszedłem dać ziemi pokój? Bynajmniej, mówię wam, raczej rozłam.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 52, 'Odtąd bowiem w jednym domu będzie pięciu poróżnionych, trzech przeciwko dwom, a dwóch przeciwko trzem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 53, 'Ojciec powstanie przeciwko synowi, a syn przeciwko ojcu, matka przeciwko córce, a córka przeciwko matce, teściowa przeciwko synowej, a synowa przeciwko teściowej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 54, 'Mówił też do ludu: Gdy widzicie chmurę pojawiającą się od zachodu, zaraz mówicie: Nadchodzi ulewny deszcz. I tak jest.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 55, 'A gdy wieje wiatr z południa, mówicie: Będzie gorąco. I tak jest.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 56, 'Obłudnicy, wygląd nieba i ziemi umiecie rozpoznawać, jakże więc obecnego czasu nie rozpoznajecie?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 57, 'Dlaczego sami z siebie nie umiecie osądzić, co jest sprawiedliwe?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 58, 'Gdy więc idziesz ze swoim przeciwnikiem do urzędnika, staraj się w drodze dojść z nim do zgody, aby cię nie zaciągnął przed sędziego, a sędzia przekazałby cię strażnikowi, a strażnik wtrąciłby cię do więzienia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 59, 'Mówię ci, że nie wyjdziesz stamtąd, dopóki nie oddasz ostatniego grosza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 1, 'W tym samym czasie niektórzy z tam obecnych oznajmili mu o Galilejczykach, których krew Piłat zmieszał z ich ofiarami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 2, 'A Jezus im odpowiedział: Czy myślicie, że ci Galilejczycy byli większymi grzesznikami niż wszyscy inni Galilejczycy, że to ucierpieli?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 3, 'Bynajmniej, mówię wam, lecz jeśli nie będziecie pokutować, wszyscy tak samo zginiecie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 4, 'Albo czy myślicie, że tych osiemnastu, na których runęła wieża w Siloam i zabiła ich, było większymi winowajcami niż wszyscy ludzie mieszkający w Jerozolimie?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 5, 'Bynajmniej, mówię wam, lecz jeśli nie będziecie pokutować, wszyscy tak samo zginiecie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 6, 'I opowiedział im taką przypowieść: Pewien człowiek miał drzewo figowe zasadzone w swojej winnicy. Przyszedł i szukał na nim owocu, lecz nie znalazł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 7, 'Wtedy powiedział do rolnika: Oto od trzech lat przychodzę, szukając owocu na tym drzewie figowym, lecz nie znajduję. Zetnij je, bo po co ziemię na darmo zajmuje?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 8, 'Lecz on mu odpowiedział: Panie, zostaw je jeszcze na ten rok, aż je okopię i obłożę nawozem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 9, 'Może wyda owoc, a jeśli nie, wtedy je zetniesz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 10, 'I nauczał w jednej z synagog w szabat.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 11, 'A była tam kobieta, która od osiemnastu lat miała ducha niemocy i była pochylona, i w żaden sposób nie mogła się wyprostować.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 12, 'Gdy Jezus ją zobaczył, przywołał ją do siebie i powiedział: Kobieto, jesteś uwolniona od swojej choroby.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 13, 'I położył na nią ręce, a ona natychmiast wyprostowała się i chwaliła Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 14, 'Wtedy przełożony synagogi, oburzony tym, że Jezus uzdrowił w szabat, powiedział do ludzi: Jest sześć dni, w których należy pracować. W te dni przychodźcie i leczcie się, a nie w dzień szabatu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 15, 'Ale Pan mu odpowiedział: Obłudniku, czyż każdy z was w szabat nie odwiązuje swego wołu albo osła od żłobu i nie prowadzi, żeby go napoić?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 16, 'A ta córka Abrahama, którą szatan wiązał już osiemnaście lat, czyż nie miała być uwolniona od tych więzów w dzień szabatu?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 17, 'A gdy to mówił, zawstydzili się wszyscy jego przeciwnicy, a cały lud cieszył się ze wszystkich chwalebnych czynów dokonywanych przez niego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 18, 'Potem Jezus powiedział: Do czego podobne jest królestwo Boże i z czym je porównam?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 19, 'Podobne jest do ziarna gorczycy, które człowiek wziął i posiał w swoim ogrodzie. Wyrosło i stało się wielkim drzewem, a ptaki niebieskie gnieździły się w jego gałęziach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 20, 'I znowu powiedział: Do czego przyrównam królestwo Boże?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 21, 'Podobne jest do zakwasu, który wziąwszy, kobieta włożyła w trzy miary mąki, aż wszystko się zakwasiło.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 22, 'I nauczał, chodząc po miastach i wioskach i podążając w kierunku Jerozolimy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 23, 'I ktoś go zapytał: Panie, czy mało jest tych, którzy będą zbawieni? On zaś im odpowiedział:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 24, 'Usiłujcie wejść przez ciasną bramę, bo mówię wam, że wielu będzie chciało wejść, lecz nie będą mogli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 25, 'Gdy gospodarz wstanie i zamknie drzwi, zaczniecie stać na zewnątrz i pukać do drzwi, mówiąc: Panie, Panie, otwórz nam! A on wam odpowie: Nie znam was i nie wiem, skąd jesteście.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 26, 'Wtedy zaczniecie mówić: Jedliśmy i piliśmy z tobą, i nauczałeś na naszych ulicach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 27, 'A on powie: Mówię wam, nie znam was i nie wiem, skąd jesteście; odstąpcie ode mnie wszyscy, którzy czynicie nieprawość.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 28, 'Tam będzie płacz i zgrzytanie zębów, gdy ujrzycie Abrahama, Izaaka, Jakuba i wszystkich proroków w królestwie Bożym, a samych siebie wyrzuconych precz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 29, 'I przyjdą inni ze wschodu i z zachodu, z północy i z południa, i zasiądą za stołem w królestwie Bożym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 30, 'Tak oto są ostatni, którzy będą pierwszymi, i są pierwsi, którzy będą ostatnimi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 31, 'W tym dniu przyszli niektórzy z faryzeuszy i powiedzieli mu: Wyjdź i odejdź stąd, bo Herod chce cię zabić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 32, 'I powiedział im: Idźcie i powiedzcie temu lisowi: Oto wypędzam demony i uzdrawiam dziś i jutro, a trzeciego dnia zakończę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 33, 'Jednak dziś, jutro i pojutrze muszę przebyć drogę, bo niemożliwe jest, aby prorok zginął poza Jerozolimą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 34, 'Jeruzalem, Jeruzalem, które zabijasz proroków i kamienujesz tych, którzy są do ciebie posłani. Ile razy chciałem zgromadzić twoje dzieci, tak jak kokoszka gromadzi swoje kurczęta pod skrzydła, a nie chcieliście!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 35, 'Oto wasz dom zostanie wam pusty. Zaprawdę powiadam wam, że nie ujrzycie mnie, aż przyjdzie czas, gdy powiecie: Błogosławiony, który przychodzi w imieniu Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 1, 'I stało się tak, że gdy Jezus wszedł w szabat do domu pewnego przywódcy faryzeuszy, aby jeść chleb, oni go obserwowali.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 2, 'A oto był przed nim pewien człowiek chory na puchlinę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 3, 'Wtedy Jezus zapytał znawców prawa i faryzeuszy: Czy wolno uzdrawiać w szabat?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 4, 'Lecz oni milczeli. On zaś ujął go, uzdrowił i odprawił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 5, 'I powiedział im: Któż z was, jeśli jego osioł albo wół wpadnie do studni, nie wyciągnie go natychmiast w dzień szabatu?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 6, 'I nie mogli mu na to odpowiedzieć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 7, 'Gdy zauważył, jak zaproszeni wybierali pierwsze miejsca, opowiedział im przypowieść:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 8, 'Gdy ktoś cię zaprosi na wesele, nie siadaj na pierwszym miejscu, aby czasem ktoś ważniejszy od ciebie nie był zaproszony przez niego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 9, 'Wówczas przyjdzie ten, który ciebie i jego zaprosił, i powie ci: Ustąp temu miejsca; i wtedy ze wstydem musiałbyś zająć ostatnie miejsce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 10, 'Lecz gdy będziesz zaproszony, idź i usiądź na ostatnim miejscu, a gdy przyjdzie ten, który cię zaprosił, powie ci: Przyjacielu, przesiądź się wyżej. Wtedy doznasz czci wobec współbiesiadników.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 11, 'Bo każdy, kto się wywyższa, będzie poniżony, a kto się poniża, będzie wywyższony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 12, 'Powiedział też do tego, który go zaprosił: Gdy wydajesz obiad albo kolację, nie zapraszaj swoich przyjaciół ani braci, ani krewnych, ani bogatych sąsiadów, żeby cię czasem i oni w zamian nie zaprosili, i miałbyś odpłatę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 13, 'Lecz gdy wydajesz ucztę, zaproś ubogich, ułomnych, chromych i ślepych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 14, 'A będziesz błogosławiony, bo nie mają ci czym odpłacić, ale otrzymasz odpłatę przy zmartwychwstaniu sprawiedliwych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 15, 'Gdy usłyszał to jeden ze współbiesiadników, powiedział do niego: Błogosławiony ten, kto będzie jadł chleb w królestwie Bożym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 16, 'Wtedy on mu powiedział: Pewien człowiek wydał wielką ucztę i zaprosił wielu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 17, 'A gdy nadszedł czas uczty, posłał swego sługę, żeby powiedział zaproszonym: Chodźcie, bo już wszystko gotowe.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 18, 'A oni zaczęli się wszyscy jednomyślnie wymawiać. Pierwszy mu powiedział: Kupiłem pole i muszę iść je obejrzeć. Proszę cię, uważaj mnie za wytłumaczonego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 19, 'Drugi zaś powiedział: Kupiłem pięć par wołów i idę je wypróbować. Proszę cię, uważaj mnie za wytłumaczonego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 20, 'A jeszcze inny powiedział: Pojąłem żonę i dlatego nie mogę przyjść.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 21, 'A gdy sługa wrócił, oznajmił to swemu panu. Wtedy gospodarz rozgniewał się i powiedział do swego sługi: Wyjdź szybko na ulice i zaułki miasta i wprowadź tu ubogich, ułomnych, chromych i ślepych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 22, 'I powiedział sługa: Panie, stało się, jak rozkazałeś, a jeszcze jest miejsce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 23, 'Wtedy Pan powiedział do sługi: Wyjdź na drogi i między opłotki i przymuszaj do wejścia, aby mój dom się zapełnił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 24, 'Mówię wam bowiem, że żaden z tych ludzi, którzy byli zaproszeni, nie skosztuje mojej uczty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 25, 'I szły z nim wielkie tłumy. A on, odwróciwszy się, powiedział do nich:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 26, 'Jeśli ktoś przychodzi do mnie, a nie ma w nienawiści swego ojca i matki, żony i dzieci, braci i sióstr, a nawet swego życia, nie może być moim uczniem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 27, 'Kto nie niesie swego krzyża, a idzie za mną, nie może być moim uczniem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 28, 'Bo któż z was, chcąc zbudować wieżę, najpierw nie usiądzie i nie obliczy wydatków, czy mu wystarczy na ukończenie?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 29, 'Aby czasem, gdyby położył fundament, a nie mógłby ukończyć, wszyscy, którzy by to widzieli, nie zaczęli się z niego naśmiewać;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 30, 'Mówiąc: Ten człowiek zaczął budować, a nie zdołał ukończyć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 31, 'Albo który król, wyruszając na wojnę z drugim królem, najpierw nie usiądzie i nie naradzi się, czy w dziesięć tysięcy może zmierzyć się z tym, który z dwudziestoma tysiącami nadciąga przeciwko niemu?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 32, 'A jeśli nie, to gdy tamten jeszcze jest daleko, wysyła poselstwo i prosi o warunki pokoju.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 33, 'Tak i każdy z was, kto nie wyrzeknie się wszystkiego, co posiada, nie może być moim uczniem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 34, 'Dobra jest sól. Lecz jeśli sól zwietrzeje, czym się ją przyprawi?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 35, 'Nie nadaje się ani do ziemi, ani do nawozu; precz się ją wyrzuca. Kto ma uszy do słuchania, niech słucha.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 1, 'I zbliżali się do niego wszyscy celnicy i grzesznicy, aby go słuchać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 2, 'A faryzeusze i uczeni w Piśmie szemrali, mówiąc: Ten człowiek przyjmuje grzeszników i jada z nimi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 3, 'I opowiedział im taką przypowieść:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 4, 'Któż z was, gdy ma sto owiec, a zgubi jedną z nich, nie zostawia dziewięćdziesięciu dziewięciu na pustyni i nie idzie za zgubioną, aż ją znajdzie?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 5, 'Kiedy ją znajdzie, wkłada na swoje ramiona i raduje się.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 6, 'A przyszedłszy do domu, zwołuje przyjaciół i sąsiadów i mówi im: Cieszcie się ze mną, bo znalazłem moją zgubioną owcę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 7, 'Mówię wam, że podobnie w niebie większa będzie radość z jednego pokutującego grzesznika niż z dziewięćdziesięciu dziewięciu sprawiedliwych, którzy nie potrzebują pokuty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 8, 'Albo która kobieta, mając dziesięć monet, jeśli zgubi jedną, nie zapala świecy, nie zamiata domu i nie szuka pilnie, aż ją znajdzie?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 9, 'A znalazłszy, zwołuje przyjaciółki i sąsiadki i mówi: Cieszcie się ze mną, bo znalazłam monetę, którą zgubiłam.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 10, 'Podobnie, mówię wam, będzie radość przed aniołami Boga z jednego pokutującego grzesznika.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 11, 'Powiedział też: Pewien człowiek miał dwóch synów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 12, 'I powiedział młodszy z nich do ojca: Ojcze, daj mi część majątku, która na mnie przypada. Podzielił więc majątek między nich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 13, 'Po kilku dniach młodszy syn, zabrawszy wszystko, odjechał w dalekie strony i roztrwonił tam swój majątek, żyjąc rozpustnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 14, 'A gdy wszystko wydał, nastał wielki głód w tych stronach, a on zaczął cierpieć niedostatek.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 15, 'Poszedł więc i przystał do jednego z obywateli tych stron, który posłał go na swoje pola, aby pasł świnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 16, 'I pragnął napełnić swój żołądek strąkami, które jadały świnie, ale nikt mu nie dawał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 17, 'Wtedy opamiętał się i powiedział: Iluż to najemników mego ojca ma pod dostatkiem chleba, a ja z głodu ginę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 18, 'Wstanę więc i pójdę do mego ojca, i powiem mu: Ojcze, zgrzeszyłem przeciwko niebu i względem ciebie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 19, 'I nie jestem już godny nazywać się twoim synem. Zrób ze mnie jednego ze swoich najemników.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 20, 'Wtedy wstał i poszedł do swego ojca. A gdy był jeszcze daleko, zobaczył go jego ojciec i użalił się nad nim, a podbiegłszy, rzucił mu się na szyję i ucałował go.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 21, 'I powiedział do niego syn: Ojcze, zgrzeszyłem przeciwko niebu i przed tobą; nie jestem już godny nazywać się twoim synem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 22, 'Lecz ojciec powiedział do swoich sług: Przynieście najlepszą szatę i ubierzcie go; dajcie mu też pierścień na rękę i obuwie na nogi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 23, 'Przyprowadźcie tłuste cielę i zabijcie; jedzmy i radujmy się.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 24, 'Ten mój syn bowiem był martwy, a znowu żyje, zaginął, a został znaleziony. I zaczęli się weselić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 25, 'Tymczasem jego starszy syn był na polu. Gdy wracał i był blisko domu, usłyszał muzykę i tańce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 26, 'Zawołał więc jednego ze sług i pytał, co to wszystko znaczy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 27, 'A on mu odpowiedział: Twój brat powrócił, a twój ojciec zabił tłuste cielę, ponieważ odzyskał go zdrowego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 28, 'Wtedy rozgniewał się i nie chciał wejść. Jego ojciec jednak wyszedł i namawiał go.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 29, 'A on odpowiedział ojcu: Oto tyle lat ci służę i nigdy nie przekroczyłem twego przykazania, jednak nigdy nie dałeś mi koźlęcia, abym się weselił z moimi przyjaciółmi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 30, 'Ale kiedy wrócił ten twój syn, który roztrwonił twój majątek z nierządnicami, zabiłeś dla niego tłuste cielę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 31, 'A on mu odpowiedział: Synu, ty zawsze jesteś ze mną i wszystkie moje dobra należą do ciebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 32, 'Lecz trzeba było weselić się i radować, że ten twój brat był martwy, a znowu żyje, zaginął, a został znaleziony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 1, 'Mówił też do swoich uczniów: Pewien bogaty człowiek miał szafarza, którego oskarżono przed nim, że trwoni jego dobra.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 2, 'Zawołał go i powiedział: Cóż to słyszę o tobie? Zdaj sprawę z twego zarządzania, bo już więcej nie będziesz mógł zarządzać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 3, 'Wtedy szafarz powiedział sobie: Co ja zrobię, skoro mój pan pozbawia mnie zarządu? Kopać nie mogę, żebrać się wstydzę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 4, 'Wiem, co zrobię, żeby ludzie przyjęli mnie do swoich domów, gdy zostanę odsunięty od zarządzania.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 5, 'Przywołał więc do siebie każdego z dłużników swego pana i zapytał pierwszego: Ile jesteś winien memu panu?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 6, 'A on odpowiedział: Sto baryłek oliwy. I powiedział mu: Weź swój zapis, siadaj szybko i napisz pięćdziesiąt.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 7, 'Potem zapytał drugiego: A ty ile jesteś winien? A on mu odpowiedział: Sto korców pszenicy. I powiedział mu: Weź swój zapis i napisz osiemdziesiąt.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 8, 'I pochwalił pan niesprawiedliwego szafarza, że roztropnie postąpił. Bo synowie tego świata w swoim pokoleniu są roztropniejsi od synów światłości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 9, 'I ja wam mówię: Zyskujcie sobie przyjaciół mamoną niesprawiedliwości, aby, gdy ustaniecie, przyjęto was do wiecznych przybytków.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 10, 'Kto jest wierny w najmniejszym, i w wielkim jest wierny, a kto w najmniejszym jest niesprawiedliwy, i w wielkim jest niesprawiedliwy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 11, 'Jeśli więc w niesprawiedliwej mamonie nie byliście wierni, któż wam powierzy to, co prawdziwe?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 12, 'A jeśli w cudzym nie byliście wierni, któż wam da wasze własne?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 13, 'Żaden sługa nie może dwom panom służyć, gdyż albo jednego będzie nienawidził, a drugiego miłował, albo jednego będzie się trzymał, a drugim wzgardzi. Nie możecie służyć Bogu i mamonie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 14, 'Słuchali tego wszystkiego również faryzeusze, którzy byli chciwi, i naśmiewali się z niego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 15, 'I powiedział im: Wy sami siebie usprawiedliwiacie przed ludźmi, ale Bóg zna wasze serca. To bowiem, co ludzie poważają, obrzydliwością jest w oczach Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 16, 'Prawo i Prorocy byli do Jana. Odtąd jest głoszone królestwo Boże i każdy się do niego gwałtem wdziera.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 17, 'I łatwiej jest niebu i ziemi przeminąć, niż przepaść jednej kresce prawa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 18, 'Każdy, kto oddala swoją żonę i żeni się z inną, cudzołoży, a kto żeni się z oddaloną przez męża, cudzołoży.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 19, 'Był pewien bogaty człowiek, który ubierał się w purpurę i bisior i wystawnie ucztował każdego dnia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 20, 'Był też pewien żebrak, imieniem Łazarz, który leżał u jego wrót owrzodziały;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 21, 'Pragnął on nasycić się okruchami, które spadały ze stołu bogacza. Nadto i psy przychodziły i lizały jego wrzody.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 22, 'I umarł żebrak, i został zaniesiony przez aniołów na łono Abrahama. Umarł też bogacz i został pogrzebany.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 23, 'A będąc w piekle i cierpiąc męki, podniósł oczy i ujrzał z daleka Abrahama i Łazarza na jego łonie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 24, 'Wtedy zawołał: Ojcze Abrahamie, zmiłuj się nade mną i poślij Łazarza, aby umoczył koniec swego palca w wodzie i ochłodził mi język, bo cierpię męki w tym płomieniu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 25, 'I powiedział Abraham: Synu, wspomnij, że za życia odebrałeś swoje dobro, podobnie jak Łazarz zło. A teraz on doznaje pociechy, a ty cierpisz męki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 26, 'I oprócz tego wszystkiego między nami a wami jest utwierdzona wielka przepaść, aby ci, którzy chcą stąd przejść do was, nie mogli, ani stamtąd przejść do nas.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 27, 'A on powiedział: Proszę cię więc, ojcze, abyś posłał go do domu mego ojca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 28, 'Mam bowiem pięciu braci – niech im da świadectwo, żeby i oni nie przyszli na to miejsce męki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 29, 'Lecz Abraham mu powiedział: Mają Mojżesza i Proroków, niech ich słuchają.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 30, 'A on odpowiedział: Nie, ojcze Abrahamie, lecz jeśli ktoś z umarłych przyjdzie do nich, będą pokutować.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 31, 'I powiedział do niego: Jeśli Mojżesza i Proroków nie słuchają, to choćby ktoś zmartwychwstał, nie uwierzą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 1, 'I powiedział do uczniów: Nie jest możliwe, żeby nie przyszły zgorszenia, lecz biada temu, przez którego przychodzą!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 2, 'Lepiej byłoby dla niego, gdyby zawieszono mu u szyi kamień młyński i wrzucono go do morza, niż żeby miał zgorszyć jednego z tych małych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 3, 'Miejcie się na baczności. Jeśli twój brat zgrzeszy przeciwko tobie, strofuj go, a jeśli żałuje, przebacz mu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 4, 'A jeśli siedem razy na dzień zgrzeszy przeciwko tobie i siedem razy w ciągu dnia zwróci się do ciebie, mówiąc: Żałuję tego – przebacz mu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 5, 'I powiedzieli apostołowie do Pana: Dodaj nam wiary.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 6, 'A Pan odpowiedział: Gdybyście mieli wiarę jak ziarno gorczycy i powiedzielibyście temu drzewu morwy: Wyrwij się z korzeniem i przesadź się do morza, usłuchałoby was.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 7, 'Kto z was, mając sługę, który orze albo pasie, powie mu, gdy wróci z pola: Chodź i usiądź za stołem?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 8, 'Czy nie powie mu raczej: Przygotuj mi kolację, przepasz się i usługuj mi, aż się najem i napiję, a potem i ty będziesz jadł i pił?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 9, 'Czy dziękuje słudze, że zrobił to, co mu nakazano? Nie wydaje mi się.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 10, 'Także i wy, gdy zrobicie wszystko, co wam nakazano, mówcie: Sługami nieużytecznymi jesteśmy. Zrobiliśmy to, co powinniśmy byli zrobić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 11, 'A w drodze do Jerozolimy przechodził przez pogranicze Samarii i Galilei.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 12, 'Gdy wchodził do pewnej wioski, wyszło mu naprzeciw dziesięciu trędowatych mężczyzn, którzy stanęli z daleka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 13, 'I donośnym głosem zawołali: Jezusie, Mistrzu, zmiłuj się nad nami!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 14, 'Kiedy ich zobaczył, powiedział do nich: Idźcie, pokażcie się kapłanom. A gdy szli, zostali oczyszczeni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 15, 'Lecz jeden z nich, widząc, że został uzdrowiony, wrócił, chwaląc Boga donośnym głosem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 16, 'I upadł na twarz do jego nóg, dziękując mu. A był to Samarytanin.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 17, 'Jezus zaś odezwał się: Czyż nie dziesięciu zostało oczyszczonych? Gdzie jest dziewięciu?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 18, 'Nie znalazł się nikt, kto by wrócił i oddał chwałę Bogu, tylko ten cudzoziemiec.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 19, 'I powiedział do niego: Wstań, idź! Twoja wiara cię uzdrowiła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 20, 'Zapytany zaś przez faryzeuszy, kiedy przyjdzie królestwo Boże, odpowiedział im: Królestwo Boże nie przyjdzie dostrzegalnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 21, 'I nie powiedzą: Oto tu, albo: Oto tam jest. Królestwo Boże bowiem jest wewnątrz was.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 22, 'A do uczniów powiedział: Przyjdzie czas, kiedy będziecie pragnęli zobaczyć jeden z dni Syna Człowieczego, ale nie zobaczycie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 23, 'I powiedzą wam: Oto tu, albo: Oto tam jest. Nie chodźcie tam ani nie idźcie za nimi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 24, 'Bo jak błyskawica, gdy zabłyśnie, świeci od jednego krańca nieba aż po drugi, tak będzie i z Synem Człowieczym w jego dniu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 25, 'Ale najpierw musi wiele cierpieć i zostać odrzucony przez to pokolenie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 26, 'A jak było za dni Noego, tak będzie i za dni Syna Człowieczego:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 27, 'Jedli, pili, żenili się i za mąż wychodziły aż do dnia, w którym Noe wszedł do arki; i nastał potop, i wszystkich wytracił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 28, 'Podobnie jak działo się za dni Lota: jedli, pili, kupowali, sprzedawali, sadzili, budowali;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 29, 'Lecz tego dnia, gdy Lot wyszedł z Sodomy, spadł z nieba deszcz ognia i siarki i wszystkich wytracił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 30, 'Tak też będzie w dniu, kiedy Syn Człowieczy się objawi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 31, 'Tego dnia, jeśli ktoś będzie na dachu, a jego rzeczy w domu, niech nie schodzi, aby je zabrać, a kto będzie na polu, niech również nie wraca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 32, 'Pamiętajcie żonę Lota.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 33, 'Kto chce zachować swoje życie, straci je, a kto je straci, zachowa je.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 34, 'Mówię wam: Tej nocy dwóch będzie w jednym łóżku, jeden będzie wzięty, a drugi zostawiony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 35, 'Dwie będą mleć razem, jedna będzie wzięta, a druga zostawiona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 36, 'Dwaj będą na polu, jeden będzie wzięty, a drugi zostawiony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 37, 'I pytali go: Gdzie, Panie? A on im powiedział: Gdzie jest ciało, tam zgromadzą się i orły.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 1, 'Opowiedział im też przypowieść o tym, że zawsze należy się modlić i nie ustawać;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 2, 'Mówiąc: W pewnym mieście był sędzia, który Boga się nie bał i z człowiekiem się nie liczył.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 3, 'Była też w tym mieście wdowa, która przychodziła do niego i mówiła: Pomścij moją krzywdę na moim przeciwniku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 4, 'On przez długi czas nie chciał, lecz potem powiedział sobie: Chociaż Boga się nie boję i z człowiekiem się nie liczę;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 5, 'To jednak, ponieważ naprzykrza mi się ta wdowa, pomszczę jej krzywdę, aby już nie przychodziła i nie zadręczała mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 6, 'I powiedział Pan: Słuchajcie, co mówi niesprawiedliwy sędzia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 7, 'A Bóg, czy nie pomści krzywdy swoich wybranych, którzy wołają do niego we dnie i w nocy, chociaż długo zwleka w ich sprawie?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 8, 'Mówię wam, że szybko pomści ich krzywdę. Lecz czy Syn Człowieczy znajdzie wiarę na ziemi, gdy przyjdzie?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 9, 'Powiedział też do tych, którzy ufali sobie, że są sprawiedliwi, a innych mieli za nic, taką przypowieść:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 10, 'Dwóch ludzi weszło do świątyni, żeby się modlić, jeden faryzeusz, a drugi celnik.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 11, 'Faryzeusz stanął i tak się w sobie modlił: Dziękuję ci, Boże, że nie jestem jak inni ludzie, zdziercy, niesprawiedliwi, cudzołożnicy albo jak i ten celnik.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 12, 'Poszczę dwa razy w tygodniu, daję dziesięcinę ze wszystkiego, co mam.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 13, 'A celnik, stojąc z daleka, nie chciał nawet oczu podnieść ku niebu, ale bił się w piersi, mówiąc: Boże, bądź miłosierny mnie grzesznemu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 14, 'Mówię wam, że raczej ten odszedł do swego domu usprawiedliwiony, a nie tamten. Każdy bowiem, kto się wywyższa, będzie poniżony, a kto się poniża, będzie wywyższony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 15, 'Przynoszono też do niego niemowlęta, aby je dotknął. Lecz uczniowie, widząc to, gromili ich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 16, 'Ale Jezus przywołał ich i powiedział: Pozwólcie dzieciom przychodzić do mnie i nie zabraniajcie im. Do takich bowiem należy królestwo Boże.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 17, 'Zaprawdę powiadam wam: Kto nie przyjmie królestwa Bożego jak dziecko, nie wejdzie do niego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 18, 'I zapytał go pewien dostojnik: Nauczycielu dobry, co mam czynić, aby odziedziczyć życie wieczne?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 19, 'A Jezus mu odpowiedział: Dlaczego nazywasz mnie dobrym? Nikt nie jest dobry, tylko jeden – Bóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 20, 'Znasz przykazania: Nie cudzołóż, nie zabijaj, nie kradnij, nie dawaj fałszywego świadectwa, czcij swego ojca i swoją matkę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 21, 'A on odpowiedział: Tego wszystkiego przestrzegałem od młodości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 22, 'Gdy Jezus to usłyszał, powiedział do niego: Jednego ci jeszcze brakuje. Sprzedaj wszystko, co masz, i rozdaj ubogim, a będziesz miał skarb w niebie. Potem przyjdź i chodź za mną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 23, 'A on, usłyszawszy to, ogromnie się zasmucił, bo był bardzo bogaty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 24, 'Kiedy Jezus zobaczył go bardzo zasmuconego, powiedział: Jakże trudno tym, którzy mają pieniądze, wejść do królestwa Bożego!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 25, 'Łatwiej bowiem jest wielbłądowi przejść przez ucho igielne, niż bogatemu wejść do królestwa Bożego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 26, 'Wtedy ci, którzy to słyszeli, mówili: Któż więc może być zbawiony?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 27, 'A on odpowiedział: Co niemożliwe jest u ludzi, możliwe jest u Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 28, 'Wówczas Piotr powiedział: Oto my opuściliśmy wszystko i poszliśmy za tobą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 29, 'On zaś im odpowiedział: Zaprawdę powiadam wam, że nie ma nikogo, kto by opuścił dom, rodziców lub braci, żonę lub dzieci dla królestwa Bożego;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 30, 'I nie otrzymał o wiele więcej w tym czasie, a w przyszłym świecie życia wiecznego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 31, 'Potem wziął ze sobą dwunastu i powiedział do nich: Oto idziemy do Jerozolimy i wypełni się wszystko, co zostało napisane przez proroków o Synu Człowieczym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 32, 'Będzie bowiem wydany poganom, wyśmiany, zelżony i opluty;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 33, 'Ubiczują go i zabiją, ale trzeciego dnia zmartwychwstanie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 34, 'Lecz oni nic z tego nie zrozumieli. Te słowa były przed nimi zakryte i nie wiedzieli, o czym była mowa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 35, 'A gdy zbliżał się do Jerycha, pewien ślepiec siedział przy drodze i żebrał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 36, 'A usłyszawszy przechodzący tłum, pytał, co się dzieje.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 37, 'I powiedziano mu, że przechodzi Jezus z Nazaretu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 38, 'Wtedy zawołał: Jezusie, Synu Dawida, zmiłuj się nade mną!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 39, 'Lecz ci, którzy szli z przodu, gromili go, aby milczał. On jednak jeszcze głośniej wołał: Synu Dawida, zmiłuj się nade mną!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 40, 'Wtedy Jezus zatrzymał się i kazał go przyprowadzić do siebie. A gdy się zbliżył, zapytał go:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 41, 'Co chcesz, abym ci uczynił? A on odpowiedział: Panie, żebym przejrzał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 42, 'Jezus mu powiedział: Przejrzyj, twoja wiara cię uzdrowiła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 43, 'Zaraz też odzyskał wzrok i szedł za nim, wielbiąc Boga. A wszyscy ludzie, widząc to, oddawali chwałę Bogu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 1, 'A Jezus wszedł do Jerycha i przechodził przez nie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 2, 'Był tam pewien człowiek, imieniem Zacheusz, przełożony celników, a był on bogaty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 3, 'Pragnął on zobaczyć Jezusa, kto to jest, lecz nie mógł z powodu tłumu, bo był niskiego wzrostu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 4, 'Pobiegł więc naprzód i wszedł na drzewo sykomory, aby go zobaczyć, bo miał tamtędy przechodzić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 5, 'A gdy Jezus przyszedł na to miejsce, spojrzał w górę, zobaczył go i powiedział: Zacheuszu, zejdź szybko, bo dziś muszę zatrzymać się w twoim domu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 6, 'I zszedł szybko, i przyjął go z radością.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 7, 'A wszyscy, widząc to, szemrali: Do człowieka grzesznego przybył w gościnę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 8, 'Zacheusz zaś stanął i powiedział do Pana: Panie, oto połowę mojego majątku daję ubogim, a jeśli kogoś w czymś oszukałem, oddaję poczwórnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 9, 'I powiedział Jezus do niego: Dziś zbawienie przyszło do tego domu, gdyż i on jest synem Abrahama.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 10, 'Bo Syn Człowieczy przyszedł, aby szukać i zbawić to, co zginęło.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 11, 'A gdy oni tego słuchali, opowiedział im dodatkowo przypowieść, dlatego że był blisko Jerozolimy, a oni myśleli, że wnet ma się objawić królestwo Boże.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 12, 'Mówił więc: Pewien człowiek szlachetnego rodu udał się do dalekiego kraju, aby objąć królestwo, a potem wrócić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 13, 'A przywoławszy dziesięciu swoich sług, dał im dziesięć grzywien i powiedział do nich: Obracajcie nimi, aż wrócę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 14, 'Lecz jego poddani nienawidzili go i wysłali za nim poselstwo ze słowami: Nie chcemy, aby ten człowiek królował nad nami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 15, 'A gdy wrócił po objęciu królestwa, rozkazał przywołać do siebie te sługi, którym dał pieniądze, aby się dowiedzieć, co każdy zyskał, handlując.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 16, 'Wtedy przyszedł pierwszy i powiedział: Panie, twoja grzywna zyskała dziesięć grzywien.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 17, 'I powiedział do niego: Dobrze, sługo dobry, ponieważ byłeś wierny w małym, sprawuj władzę nad dziesięcioma miastami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 18, 'Przyszedł też drugi i powiedział: Panie, twoja grzywna zyskała pięć grzywien.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 19, 'Również temu powiedział: I ty władaj pięcioma miastami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 20, 'A inny przyszedł i powiedział: Panie, oto twoja grzywna, którą miałem schowaną w chustce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 21, 'Bałem się bowiem ciebie, bo jesteś człowiekiem surowym: bierzesz, czego nie położyłeś, i żniesz, czego nie posiałeś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 22, 'Wtedy mu odpowiedział: Na podstawie twoich słów osądzę cię, zły sługo. Wiedziałeś, że jestem człowiekiem surowym, który bierze, czego nie położył, i żnie, czego nie posiał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 23, 'Dlaczego więc nie dałeś moich pieniędzy do banku, abym po powrocie odebrał je z zyskiem?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 24, 'Do tych zaś, którzy stali obok, powiedział: Odbierzcie mu grzywnę i dajcie temu, który ma dziesięć grzywien.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 25, 'Odpowiedzieli mu: Panie, ma już dziesięć grzywien.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 26, 'Zaprawdę powiadam wam, że każdemu, kto ma, będzie dodane, a temu, kto nie ma, zostanie zabrane nawet to, co ma.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 27, 'Lecz tych moich nieprzyjaciół, którzy nie chcieli, abym nad nimi panował, przyprowadźcie tu i zabijcie na moich oczach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 28, 'A powiedziawszy to, ruszył przodem, zmierzając do Jerozolimy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 29, 'A gdy przybliżył się do Betfage i Betanii, przy górze zwanej Oliwną, wysłał dwóch ze swoich uczniów;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 30, 'Mówiąc: Idźcie do wioski, która jest naprzeciwko, a wchodząc do niej, znajdziecie oślątko uwiązane, na którym nigdy nie siedział żaden człowiek. Odwiążcie je i przyprowadźcie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 31, 'A gdyby was ktoś spytał: Dlaczego je odwiązujecie? tak mu powiecie: Dlatego, że Pan go potrzebuje.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 32, 'Wtedy odeszli ci, którzy zostali posłani, i znaleźli wszystko, jak im powiedział.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 33, 'A gdy odwiązywali oślątko, zapytali ich jego właściciele: Dlaczego odwiązujecie oślątko?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 34, 'A oni odpowiedzieli: Pan go potrzebuje.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 35, 'I przyprowadzili je do Jezusa, położyli swoje szaty na oślątko i wsadzili na nie Jezusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 36, 'Kiedy jechał, słali swoje szaty na drodze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 37, 'A gdy się już zbliżał do podnóża Góry Oliwnej, całe mnóstwo uczniów zaczęło radować się i donośnym głosem chwalić Boga za wszystkie cuda, które widzieli:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 38, 'Mówili: Błogosławiony król, który przychodzi w imieniu Pana! Pokój w niebie i chwała na wysokościach!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 39, 'Lecz niektórzy faryzeusze spośród tłumu powiedzieli do niego: Nauczycielu, zgrom swoich uczniów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 40, 'A on im odpowiedział: Mówię wam, jeśli oni będą milczeć, wnet kamienie będą wołać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 41, 'A gdy się przybliżył i zobaczył miasto, zapłakał nad nim;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 42, 'Mówiąc: O gdybyś i ty poznało, przynajmniej w tym twoim dniu, co służy twemu pokojowi! Lecz teraz zakryte jest to przed twoimi oczami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 43, 'Przyjdą bowiem na ciebie dni, gdy twoi nieprzyjaciele otoczą cię wałem, oblegną cię i ścisną zewsząd.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 44, 'Zrównają z ziemią ciebie i twoje dzieci, które są w tobie, i nie zostawią w tobie kamienia na kamieniu, dlatego żeś nie poznało czasu twego nawiedzenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 45, 'A gdy wszedł do świątyni, zaczął wyganiać tych, którzy w niej sprzedawali i kupowali;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 46, 'Mówiąc im: Jest napisane: Mój dom jest domem modlitwy, a wy zrobiliście z niego jaskinię zbójców.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 47, 'I nauczał każdego dnia w świątyni. Naczelni kapłani zaś i uczeni w Piśmie oraz przywódcy ludu szukali sposobności, aby go zabić;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 48, 'Ale nie wiedzieli, co mogliby zrobić, bo wszyscy ludzie słuchali go z zapartym tchem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 1, 'A pewnego dnia, gdy nauczał ludzi w świątyni i głosił ewangelię, nadeszli naczelni kapłani i uczeni w Piśmie wraz ze starszymi;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 2, 'I zapytali go: Powiedz nam, jakim prawem to czynisz? Albo kim jest ten, kto dał ci tę władzę?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 3, 'A on im odpowiedział: I ja was spytam o jedną rzecz. Powiedzcie mi:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 4, 'Chrzest Jana pochodził z nieba czy od ludzi?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 5, 'A oni zastanawiali się między sobą i mówili: Jeśli powiemy, że z nieba, zapyta: Czemu więc mu nie uwierzyliście?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 6, 'Jeśli zaś powiemy, że od ludzi, wszyscy nas ukamienują, bo są przekonani, że Jan był prorokiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 7, 'I odpowiedzieli, że nie wiedzą, skąd pochodził.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 8, 'Wtedy Jezus im powiedział: To i ja wam nie powiem, jakim prawem to czynię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 9, 'I zaczął mówić do ludzi taką przypowieść: Pewien człowiek założył winnicę, wydzierżawił ją rolnikom i wyjechał na dłuższy czas.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 10, 'A we właściwym czasie posłał sługę do rolników, aby mu dali część plonów winnicy. Lecz oni go pobili i odesłali z niczym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 11, 'Ponownie posłał innego sługę, ale oni i tego pobili, znieważyli i odesłali z niczym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 12, 'Posłał jeszcze trzeciego, a oni również jego poranili i wyrzucili.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 13, 'Wtedy pan winnicy powiedział: Co mam zrobić? Poślę mego umiłowanego syna, może go uszanują, gdy go zobaczą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 14, 'Lecz gdy rolnicy go zobaczyli, naradzali się między sobą i mówili: To jest dziedzic. Chodźmy, zabijmy go, a dziedzictwo będzie nasze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 15, 'I wyrzuciwszy go z winnicy, zabili. Cóż więc zrobi z nimi pan winnicy?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 16, 'Przyjdzie i wytraci tych rolników, a winnicę odda innym. Gdy oni to usłyszeli, powiedzieli: Nie daj Boże!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 17, 'Lecz on spojrzał na nich i zapytał: Cóż więc znaczy to, co jest napisane: Kamień, który odrzucili budujący, stał się kamieniem węgielnym?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 18, 'Każdy, kto upadnie na ten kamień, roztrzaska się, a na kogo on upadnie, zmiażdży go.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 19, 'W tej właśnie godzinie naczelni kapłani i uczeni w Piśmie starali się dostać go w swoje ręce, ale bali się ludu. Zrozumieli bowiem, że przeciwko nim powiedział tę przypowieść.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 20, 'Obserwowali go więc i posłali szpiegów, którzy udawali sprawiedliwych, aby go złapać za słowo, a potem wydać władzy i mocy namiestnika.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 21, 'I zapytali go: Nauczycielu, wiemy, że dobrze mówisz i uczysz, i nie masz względu na osobę, lecz drogi Bożej w prawdzie nauczasz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 22, 'Czy wolno nam płacić podatek cesarzowi, czy nie?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 23, 'Ale on, przejrzawszy ich podstęp, powiedział do nich: Czemu wystawiacie mnie na próbę?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 24, 'Pokażcie mi grosz. Czyj nosi wizerunek i napis? I odpowiedzieli: Cesarza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 25, 'Wtedy on im powiedział: Oddajcie więc cesarzowi to, co należy do cesarza, a Bogu to, co należy do Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 26, 'I nie mogli go złapać za słowo w obecności ludu. Zdziwieni jego odpowiedzią, zamilkli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 27, 'Wówczas przyszli niektórzy z saduceuszy, którzy twierdzą, że nie ma zmartwychwstania, i pytali go:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 28, 'Nauczycielu, Mojżesz nam napisał: Jeśli czyjś brat umrze, mając żonę, a umrze bezdzietnie, to jego brat ma pojąć jego żonę i wzbudzić potomstwo swemu bratu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 29, 'Było więc siedmiu braci, z których pierwszy ożenił się i umarł bezdzietnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 30, 'I ożenił się z nią drugi, lecz i ten umarł bezdzietnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 31, 'Potem ożenił się z nią także trzeci, podobnie aż do siódmego, a nie zostawiwszy dzieci, poumierali.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 32, 'W końcu umarła też ta kobieta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 33, 'Żoną którego z nich będzie więc przy zmartwychwstaniu? Siedmiu bowiem miało ją za żonę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 34, 'Wtedy Jezus im odpowiedział: Dzieci tego świata żenią się i za mąż wychodzą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 35, 'Lecz ci, którzy są uznani za godnych dostąpienia tamtego świata i powstania z martwych, ani się żenić nie będą, ani za mąż wychodzić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 36, 'Nie mogą bowiem więcej umrzeć, bo są równi aniołom i będąc dziećmi zmartwychwstania, są dziećmi Bożymi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 37, 'A że umarli zmartwychwstaną, to i Mojżesz pokazał przy krzaku, gdy nazywa Pana Bogiem Abrahama, Bogiem Izaaka i Bogiem Jakuba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 38, 'Bóg przecież nie jest Bogiem umarłych, lecz żywych, bo dla niego wszyscy żyją.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 39, 'Wtedy niektórzy z uczonych w Piśmie odezwali się: Nauczycielu, dobrze powiedziałeś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 40, 'I nie śmieli go już o nic pytać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 41, 'On zaś powiedział do nich: Jak to jest, że mówią, iż Chrystus jest synem Dawida?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 42, 'A sam Dawid mówi w Księdze Psalmów: Powiedział Pan memu Panu: Siądź po mojej prawicy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 43, 'Aż położę twoich nieprzyjaciół jako podnóżek pod twoje stopy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 44, 'Jeśli więc Dawid nazywa go Panem, to jakże może być jego synem?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 45, 'A gdy wszyscy ludzie słuchali, powiedział do swoich uczniów:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 46, 'Strzeżcie się uczonych w Piśmie, którzy lubią chodzić w długich szatach, kochają pozdrowienia na rynkach, pierwsze krzesła w synagogach i pierwsze miejsca na ucztach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 47, 'Pożerają oni domy wdów i dla pozoru odprawiają długie modlitwy. Ci otrzymają surowszy wyrok.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 1, 'A gdy spojrzał, zobaczył bogaczy wrzucających swoje ofiary do skarbony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 2, 'Zobaczył też pewną ubogą wdowę wrzucającą tam dwie drobne monety.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 3, 'I powiedział: Prawdziwie mówię wam, że ta uboga wdowa wrzuciła więcej niż wszyscy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 4, 'Oni wszyscy bowiem wrzucili do darów Bożych z tego, co im zbywało, ale ona ze swego niedostatku wrzuciła wszystko, co miała na utrzymanie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 5, 'A gdy niektórzy mówili o świątyni, że jest ozdobiona pięknymi kamieniami i darami, powiedział:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 6, 'Przyjdą dni, w których z tego, co widzicie, nie zostanie kamień na kamieniu, który by nie był zwalony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 7, 'I zapytali go: Nauczycielu, kiedy to nastąpi? I jaki będzie znak, gdy się to będzie miało stać?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 8, 'A on odpowiedział: Uważajcie, abyście nie zostali zwiedzeni. Wielu bowiem przyjdzie pod moim imieniem i będą mówić: Ja jestem Chrystusem, oraz: Nadchodzi czas. Nie idźcie więc za nimi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 9, 'Gdy zaś usłyszycie o wojnach i rozruchach, nie bójcie się. To bowiem najpierw musi się stać, ale koniec nie nastąpi natychmiast.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 10, 'Wtedy mówił do nich: Powstanie naród przeciwko narodowi i królestwo przeciwko królestwu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 11, 'I będą miejscami wielkie trzęsienia ziemi oraz głód i zaraza, będą także straszne zjawiska i wielkie znaki z nieba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 12, 'Lecz przed tym wszystkim podniosą na was ręce i będą was prześladować, wydawać do synagog i więzień, prowadzić do królów i namiestników z powodu mego imienia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 13, 'A to was spotka na świadectwo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 14, 'Dlatego postanówcie sobie w sercu, aby nie obmyślać wcześniej, jak macie odpowiadać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 15, 'Ja bowiem dam wam usta i mądrość, której nie będą mogli odeprzeć ani się sprzeciwić wszyscy wasi przeciwnicy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 16, 'A wydawać was też będą rodzice i bracia, krewni i przyjaciele i zabiją niektórych z was.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 17, 'Będziecie znienawidzeni przez wszystkich z powodu mego imienia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 18, 'Ale nawet włos z waszej głowy nie zginie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 19, 'Przez swoją cierpliwość zyskajcie wasze dusze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 20, 'A gdy zobaczycie Jerozolimę otoczoną przez wojska, wtedy wiedzcie, że jej spustoszenie jest bliskie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 21, 'Wówczas ci, którzy są w Judei, niech uciekają w góry, a ci, którzy są wewnątrz miasta, niech wyjdą, a ci, którzy są na wsi, niech do niego nie wchodzą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 22, 'Będą to bowiem dni pomsty, aby się wypełniło wszystko, co jest napisane.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 23, 'Lecz biada brzemiennym i karmiącym w tych dniach! Będzie bowiem wielki ucisk w tej ziemi i gniew nad tym ludem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 24, 'I polegną od ostrza miecza, i będą uprowadzeni w niewolę między wszystkie narody. A Jerozolima będzie deptana przez pogan, aż wypełnią się czasy pogan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 25, 'I będą znaki na słońcu, księżycu i gwiazdach, a na ziemi trwoga zrozpaczonych narodów, gdy zaszumi morze i fale.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 26, 'Ludzie będą drętwieć ze strachu w oczekiwaniu tego, co przyjdzie na cały świat. Poruszą się bowiem moce niebios.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 27, 'Wtedy ujrzą Syna Człowieczego, przychodzącego w obłoku z mocą i wielką chwałą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 28, 'A gdy się to zacznie dziać, spójrzcie w górę i podnieście głowy, gdyż zbliża się wasze odkupienie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 29, 'I opowiedział im przypowieść: Popatrzcie na drzewo figowe i na wszystkie drzewa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 30, 'Gdy widzicie, że już wypuszczają pąki, sami poznajecie, że lato jest już blisko.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 31, 'Tak i wy, gdy ujrzycie, że to się dzieje, wiedzcie, iż blisko jest królestwo Boże.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 32, 'Zaprawdę powiadam wam, że nie przeminie to pokolenie, aż się to wszystko stanie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 33, 'Niebo i ziemia przeminą, ale moje słowa nie przeminą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 34, 'Pilnujcie się, aby wasze serca nie były obciążone obżarstwem, pijaństwem i troską o to życie, aby ten dzień was nie zaskoczył.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 35, 'Jak sidło bowiem przyjdzie na wszystkich, którzy mieszkają na powierzchni całej ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 36, 'Dlatego czuwajcie, modląc się w każdym czasie, abyście byli godni uniknąć tego wszystkiego, co ma nadejść, i stanąć przed Synem Człowieczym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 37, 'W ciągu dnia nauczał w świątyni, a w nocy wychodził i przebywał na górze zwanej Oliwną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 38, 'Rano zaś wszyscy ludzie schodzili się do niego, aby go słuchać w świątyni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 1, 'I zbliżało się święto Przaśników, zwane Paschą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 2, 'A naczelni kapłani i uczeni w Piśmie szukali sposobu, jak by go zabić, ale bali się ludu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 3, 'Wtedy szatan wszedł w Judasza, zwanego Iskariotą, który był z grona dwunastu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 4, 'Poszedł więc i umówił się z naczelnymi kapłanami i przełożonymi świątyni, jak ma im go wydać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 5, 'A oni ucieszyli się i umówili się z nim, że dadzą mu pieniądze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 6, 'On się zgodził i szukał sposobności, aby im go wydać z dala od tłumu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 7, 'I nadszedł dzień Przaśników, w którym należało zabić baranka paschalnego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 8, 'Wtedy posłał Piotra i Jana, mówiąc: Idźcie i przygotujcie nam Paschę, abyśmy mogli jeść.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 9, 'A oni go zapytali: Gdzie chcesz, abyśmy ją przygotowali?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 10, 'On im odpowiedział: Gdy będziecie wchodzić do miasta, spotka się z wami człowiek niosący dzban wody. Idźcie za nim do domu, do którego wejdzie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 11, 'I powiedzcie gospodarzowi tego domu: Nauczyciel cię pyta: Gdzie jest pokój, w którym będę jadł Paschę z moimi uczniami?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 12, 'On wam pokaże wielką, urządzoną salę na piętrze. Tam wszystko przygotujcie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 13, 'Odeszli więc i znaleźli wszystko tak, jak im powiedział, i przygotowali Paschę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 14, 'A gdy nadeszła pora, usiadł za stołem, a z nim dwunastu apostołów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 15, 'I powiedział do nich: Gorąco pragnąłem zjeść tę Paschę z wami, zanim będę cierpiał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 16, 'Mówię wam bowiem, że nie będę jej więcej jadł, aż się spełni w królestwie Bożym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 17, 'Potem wziął kielich, złożył dziękczynienie i powiedział: Weźcie go i rozdzielcie między siebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 18, 'Mówię wam bowiem, że nie będę pił z owocu winorośli, aż przyjdzie królestwo Boże.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 19, 'Wziął też chleb, złożył dziękczynienie, połamał i dał im, mówiąc: To jest moje ciało, które jest za was dane. To czyńcie na moją pamiątkę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 20, 'Podobnie i kielich, gdy było po wieczerzy, mówiąc: Ten kielich to nowy testament w mojej krwi, która jest za was wylana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 21, 'Lecz oto ręka tego, który mnie wydaje, jest ze mną na stole.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 22, 'Wprawdzie Syn Człowieczy odchodzi, jak zostało postanowione, ale biada temu człowiekowi, przez którego będzie wydany.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 23, 'Wtedy oni zaczęli się między sobą pytać, który z nich miałby to zrobić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 24, 'Wszczął się też między nimi spór o to, kto z nich ma być uważany za największego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 25, 'Lecz on powiedział do nich: Królowie narodów panują nad nimi, a ci, którzy sprawują nad nimi władzę, nazywani są dobroczyńcami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 26, 'Wy zaś tak nie postępujcie. Lecz kto jest największy wśród was, niech będzie jak najmniejszy, a kto jest przełożonym, niech będzie jak ten, kto służy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 27, 'Któż bowiem jest większy? Ten, kto siedzi, czy ten, kto służy? Czy nie ten, kto siedzi? Ale ja jestem pośród was jako ten, kto służy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 28, 'A wy jesteście tymi, którzy wytrwali przy mnie w moich próbach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 29, 'I ja przekazuję wam królestwo, jak mnie przekazał mój Ojciec;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 30, 'Abyście jedli i pili za moim stołem w moim królestwie, i zasiadali na tronach, sądząc dwanaście pokoleń Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 31, 'I powiedział Pan: Szymonie, Szymonie, oto szatan wyprosił, żeby was przesiać jak pszenicę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 32, 'Lecz ja prosiłem za tobą, żeby nie ustała twoja wiara. Ty zaś, gdy się nawrócisz, utwierdzaj swoich braci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 33, 'A on mu powiedział: Panie, z tobą gotów jestem iść i do więzienia, i na śmierć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 34, 'On rzekł: Mówię ci, Piotrze, nim zapieje dziś kogut, trzy razy się wyprzesz, że mnie znasz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 35, 'I powiedział do nich: Gdy was posyłałem bez sakiewki, bez torby i bez obuwia, czy brakowało wam czegoś? A oni odpowiedzieli: Niczego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 36, 'Wtedy im powiedział: Teraz jednak, kto ma sakiewkę, niech ją weźmie, podobnie i torbę. A kto nie ma miecza, niech sprzeda swoją szatę i kupi go.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 37, 'Mówię wam bowiem, że jeszcze musi się wypełnić na mnie to, co jest napisane: Zaliczono go w poczet złoczyńców. Spełnia się bowiem to, co mnie dotyczy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 38, 'Oni zaś powiedzieli: Panie, oto tu dwa miecze. A on im odpowiedział: Wystarczy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 39, 'Potem wyszedł i udał się według swego zwyczaju na Górę Oliwną, a szli za nim także jego uczniowie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 40, 'Kiedy przyszedł na miejsce, powiedział do nich: Módlcie się, abyście nie ulegli pokusie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 41, 'A sam oddalił się od nich na odległość jakby rzutu kamieniem, upadł na kolana i modlił się:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 42, 'Ojcze, jeśli chcesz, zabierz ode mnie ten kielich. Jednak nie moja wola, lecz twoja niech się stanie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 43, 'Wtedy ukazał mu się anioł z nieba i umacniał go.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 44, 'I w śmiertelnym zmaganiu jeszcze gorliwiej się modlił, a jego pot był jak krople krwi spadające na ziemię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 45, 'A gdy wstał od modlitwy i przyszedł do uczniów, zastał ich śpiących ze smutku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 46, 'I powiedział do nich: Czemu śpicie? Wstańcie i módlcie się, abyście nie ulegli pokusie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 47, 'Kiedy on jeszcze mówił, oto nadszedł tłum, a jeden z dwunastu, zwany Judaszem, idąc przodem, zbliżył się do Jezusa, aby go pocałować.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 48, 'Lecz Jezus mu powiedział: Judaszu, pocałunkiem wydajesz Syna Człowieczego?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 49, 'A ci, którzy przy nim byli, widząc, na co się zanosi, zapytali go: Panie, czy mamy uderzyć mieczem?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 50, 'I jeden z nich uderzył sługę najwyższego kapłana i odciął mu prawe ucho.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 51, 'Ale Jezus odezwał się: Pozwólcie aż dotąd. I dotknąwszy jego ucha, uzdrowił go.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 52, 'Wtedy Jezus powiedział do naczelnych kapłanów, przełożonych świątyni i starszych, którzy przyszli do niego: Jak na bandytę wyszliście z mieczami i kijami?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 53, 'Gdy codziennie bywałem z wami w świątyni, nie podnieśliście na mnie ręki. Lecz to jest wasza godzina i moc ciemności.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 54, 'Wtedy schwytali go, poprowadzili i przywiedli do domu najwyższego kapłana. A Piotr szedł za nim z daleka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 55, 'Kiedy rozniecili ogień na środku dziedzińca i usiedli razem, usiadł i Piotr wśród nich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 56, 'A pewna służąca, gdy zobaczyła go siedzącego przy ogniu, uważnie mu się przyjrzała i powiedziała: On też był z nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 57, 'Lecz on zaparł się go, mówiąc: Kobieto, nie znam go.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 58, 'A po chwili ktoś inny go zobaczył i powiedział: I ty jesteś jednym z nich. Ale Piotr odrzekł: Człowieku, nie jestem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 59, 'A po upływie około jednej godziny ktoś inny stwierdził stanowczo: Na pewno i ten człowiek był z nim, bo też jest Galilejczykiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 60, 'Piotr zaś powiedział: Człowieku, nie wiem, o czym mówisz. I natychmiast, gdy on jeszcze mówił, zapiał kogut.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 61, 'A Pan odwrócił się i spojrzał na Piotra. I przypomniał sobie Piotr słowa Pana, jak mu powiedział: Zanim kogut zapieje, trzy razy się mnie wyprzesz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 62, 'I Piotr, wyszedłszy na zewnątrz, gorzko zapłakał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 63, 'Tymczasem mężczyźni, którzy trzymali Jezusa, naśmiewali się z niego i bili go.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 64, 'A zasłoniwszy mu oczy, bili go po twarzy i mówili: Prorokuj, kto cię uderzył.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 65, 'Wiele też innych bluźnierstw wypowiadali przeciwko niemu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 66, 'A gdy nastał dzień, zebrali się starsi ludu, naczelni kapłani i uczeni w Piśmie i przyprowadzili go przed swoją Radę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 67, 'I mówili: Jeśli ty jesteś Chrystusem, powiedz nam. I odpowiedział im: Jeśli wam powiem, nie uwierzycie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 68, 'A jeśli też o coś zapytam, nie odpowiecie mi ani mnie nie wypuścicie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 69, 'Odtąd Syn Człowieczy będzie siedział po prawicy mocy Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 70, 'Wtedy wszyscy powiedzieli: Więc ty jesteś Synem Bożym? A on im odpowiedział: Wy sami mówicie, że ja jestem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 71, 'A oni rzekli: Czyż jeszcze potrzebujemy świadectwa? Sami przecież słyszeliśmy z jego ust.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 1, 'Wtedy całe to zgromadzenie powstało i zaprowadzili go do Piłata.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 2, 'I zaczęli go oskarżać, mówiąc: Zastaliśmy tego człowieka, jak odwracał naród i zakazywał płacić podatki cesarzowi, mówiąc, że on jest Chrystusem, królem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 3, 'Piłat zapytał go: Czy ty jesteś królem Żydów? A on mu odpowiedział: Ty sam to mówisz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 4, 'Wtedy Piłat powiedział do naczelnych kapłanów i do ludu: Nie znajduję żadnej winy w tym człowieku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 5, 'Lecz oni jeszcze bardziej nastawali, mówiąc: Podburza lud, nauczając po całej Judei, począwszy od Galilei aż dotąd.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 6, 'Kiedy Piłat usłyszał o Galilei, zapytał, czy człowiek ten jest Galilejczykiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 7, 'A gdy się dowiedział, że podlega władzy Heroda, odesłał go do Heroda, który w tych dniach również był w Jerozolimie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 8, 'Na widok Jezusa Herod bardzo się ucieszył. Od dawna bowiem pragnął go zobaczyć, ponieważ wiele o nim słyszał i spodziewał się, że ujrzy jakiś cud przez niego dokonany.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 9, 'I zadawał mu wiele pytań, lecz on mu nic nie odpowiedział.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 10, 'A naczelni kapłani i uczeni w Piśmie stali tam i gwałtownie go oskarżali.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 11, 'Wtedy Herod ze swymi żołnierzami wzgardził nim i naśmiewał się z niego, ubierając go w białą szatę, i odesłał z powrotem do Piłata.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 12, 'W tym dniu Piłat i Herod stali się przyjaciółmi. Przedtem bowiem byli sobie wrogami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 13, 'A Piłat, zwoławszy naczelnych kapłanów, przełożonych oraz lud;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 14, 'Powiedział do nich: Przyprowadziliście mi tego człowieka jako podburzającego lud. Otóż ja przesłuchałem go wobec was i nie znalazłem w tym człowieku żadnej winy w sprawach, o które go oskarżacie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 15, 'Ani też Herod. Odesłałem was bowiem do niego i nie znalazł w nim nic, co zasługiwałoby na śmierć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 16, 'Ubiczuję go więc i wypuszczę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 17, 'Piłat bowiem miał obowiązek wypuszczać im jednego więźnia na święto.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 18, 'Wtedy wszyscy razem zawołali: Strać tego człowieka, a wypuść nam Barabasza!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 19, 'Był on wtrącony do więzienia za jakiś rozruch wywołany w mieście i za zabójstwo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 20, 'Wtedy Piłat znowu przemówił, chcąc wypuścić Jezusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 21, 'Oni jednak wołali: Ukrzyżuj, ukrzyżuj go!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 22, 'A on po raz trzeci powiedział do nich: Cóż on złego uczynił? Nie znalazłem w nim nic, co zasługuje na śmierć. Ubiczuję go więc i wypuszczę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 23, 'Lecz oni nalegali donośnym głosem, domagając się, aby go ukrzyżowano. I wzmagały się głosy ich i naczelnych kapłanów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 24, 'Piłat więc zawyrokował, aby stało się według ich żądania.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 25, 'I uwolnił im tego, o którego prosili, a który został wtrącony do więzienia za rozruch i zabójstwo. Jezusa zaś zdał na ich wolę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 26, 'A gdy go prowadzili, zatrzymali niejakiego Szymona z Cyreny, który szedł z pola, i włożyli na niego krzyż, aby go niósł za Jezusem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 27, 'I szło za nim wielkie mnóstwo ludzi i kobiet, które płakały nad nim i zawodziły.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 28, 'Ale Jezus zwrócił się do nich i powiedział: Córki Jerozolimy, nie płaczcie nade mną, ale raczej płaczcie nad sobą i nad waszymi dziećmi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 29, 'Oto bowiem idą dni, kiedy będą mówić: Błogosławione niepłodne, łona, które nie rodziły, i piersi, które nie karmiły.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 30, 'Wtedy zaczną mówić do gór: Padnijcie na nas! A do pagórków: Przykryjcie nas!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 31, 'Bo jeśli na zielonym drzewie tak się dzieje, cóż będzie na suchym?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 32, 'Prowadzono też dwóch innych, złoczyńców, aby razem z nim zostali straceni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 33, 'A gdy przyszli na miejsce zwane Miejscem Czaszki, ukrzyżowali tam jego i złoczyńców, jednego po prawej, a drugiego po lewej stronie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 34, 'Wtedy Jezus powiedział: Ojcze, przebacz im, bo nie wiedzą, co czynią. Potem podzielili jego szaty i rzucali o nie losy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 35, 'A lud stał i przypatrywał się, i wraz z przełożonymi naśmiewał się z niego, mówiąc: Innych ratował, niech ratuje samego siebie, jeśli on jest Chrystusem, wybranym Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 36, 'Naśmiewali się z niego również żołnierze, podchodząc i podając mu ocet;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 37, 'I mówili: Jeśli ty jesteś królem Żydów, ratuj samego siebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 38, 'Był też nad nim napis sporządzony w języku greckim, łacińskim i hebrajskim: To jest król Żydów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 39, 'A jeden z tych złoczyńców, którzy z nim wisieli, urągał mu: Jeśli ty jesteś Chrystusem, ratuj siebie i nas.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 40, 'Lecz drugi odezwał się, gromiąc go słowami: I ty się Boga nie boisz, chociaż ponosisz tę samą karę?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 41, 'My doprawdy – sprawiedliwie, bo odbieramy należną zapłatę za nasze uczynki, ale on nic złego nie zrobił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 42, 'I powiedział do Jezusa: Panie, wspomnij na mnie, gdy przyjdziesz do swego królestwa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 43, 'A Jezus mu odpowiedział: Zaprawdę powiadam ci: Dziś będziesz ze mną w raju.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 44, 'A było około godziny szóstej i ciemność ogarnęła całą ziemię aż do godziny dziewiątej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 45, 'I zaćmiło się słońce, a zasłona świątyni rozerwała się przez środek.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 46, 'Wtedy Jezus zawołał donośnym głosem: Ojcze, w twoje ręce powierzam mego ducha. Gdy to powiedział, skonał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 47, 'A setnik, widząc, co się działo, chwalił Boga, mówiąc: Istotnie, to był sprawiedliwy człowiek.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 48, 'Także i wszyscy ludzie, którzy zeszli się na to widowisko, gdy zobaczyli, co się stało, bili się w piersi i zawracali.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 49, 'Wszyscy zaś jego znajomi stali z daleka, przypatrując się temu, również kobiety, które przyszły za nim z Galilei.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 50, 'A był tam człowiek imieniem Józef, który był członkiem Rady, człowiek dobry i sprawiedliwy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 51, 'Nie zgadzał się on z ich uchwałą i czynem. Pochodził z Arymatei, miasta żydowskiego, i oczekiwał królestwa Bożego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 52, 'Przyszedł on do Piłata i poprosił o ciało Jezusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 53, 'Zdjął je, owinął płótnem i położył w grobowcu wykutym w skale, w którym jeszcze nikt nigdy nie był złożony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 54, 'A był to dzień przygotowania i zbliżał się szabat.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 55, 'Poszły też za nim kobiety, które przybyły z nim z Galilei. Zobaczyły grobowiec i jak złożono jego ciało.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 56, 'A gdy wróciły, przygotowały wonności i olejki. Lecz w szabat odpoczywały zgodnie z przykazaniem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 1, 'Pierwszego dnia tygodnia wczesnym rankiem przyszły do grobu, niosąc wonności, które przygotowały, a z nimi i inne kobiety;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 2, 'I zastały kamień odwalony od grobowca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 3, 'A wszedłszy do środka, nie znalazły ciała Pana Jezusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 4, 'A gdy zakłopotały się z tego powodu, nagle dwaj mężowie stanęli przy nich w lśniących szatach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 5, 'I przestraszone, schyliły twarze ku ziemi, a oni powiedzieli do nich: Dlaczego szukacie żyjącego wśród umarłych?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 6, 'Nie ma go tu, ale powstał z martwych. Przypomnijcie sobie, jak wam mówił, gdy był jeszcze w Galilei:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 7, 'Syn Człowieczy musi być wydany w ręce grzesznych ludzi i ukrzyżowany, a trzeciego dnia zmartwychwstać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 8, 'I przypomniały sobie jego słowa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 9, 'A wróciwszy od grobu, oznajmiły to wszystko jedenastu i wszystkim pozostałym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 10, 'A były to: Maria Magdalena i Joanna, Maria, matka Jakuba, i inne z nimi, które opowiedziały to apostołom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 11, 'Lecz ich słowa wydały im się niczym baśnie i nie uwierzyli im.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 12, 'Wtedy Piotr wstał i pobiegł do grobu. A gdy się nachylił, zobaczył płótna leżące osobno i odszedł, dziwiąc się temu, co się stało.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 13, 'A tego samego dnia dwaj z nich szli do wioski zwanej Emmaus, która była oddalona o sześćdziesiąt stadiów od Jerozolimy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 14, 'I rozmawiali ze sobą o tym wszystkim, co się stało.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 15, 'A gdy tak rozmawiali i wspólnie się zastanawiali, sam Jezus przybliżył się i szedł z nimi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 16, 'Lecz ich oczy były zakryte, żeby go nie poznali.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 17, 'I zapytał ich: Cóż to za rozmowy prowadzicie między sobą w drodze? Dlaczego jesteście smutni?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 18, 'A jeden z nich, któremu było na imię Kleofas, odpowiedział mu: Czy jesteś tylko przychodniem w Jerozolimie i nie wiesz, co się tam w tych dniach stało?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 19, 'I zapytał ich: O czym? A oni mu odpowiedzieli: O Jezusie z Nazaretu, który był prorokiem potężnym w czynie i słowie przed Bogiem i całym ludem;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 20, 'Jak naczelni kapłani i nasi przywódcy wydali go na śmierć i ukrzyżowali.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 21, 'A my spodziewaliśmy się, że on odkupi Izraela. Lecz po tym wszystkim dziś już trzeci dzień, jak to się stało.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 22, 'Nadto niektóre z naszych kobiet zdumiały nas: były wcześnie rano przy grobie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 23, 'A nie znalazłszy jego ciała, przyszły, mówiąc, że miały widzenie aniołów, którzy powiedzieli, iż on żyje.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 24, 'Wówczas niektórzy z naszych poszli do grobu i zastali wszystko tak, jak mówiły kobiety, ale jego nie widzieli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 25, 'Wtedy on powiedział do nich: O głupi i serca nieskorego do wierzenia we wszystko, co powiedzieli prorocy!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 26, 'Czyż Chrystus nie musiał tego wycierpieć i wejść do swojej chwały?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 27, 'I zaczynając od Mojżesza i wszystkich proroków, wykładał im, co było o nim napisane we wszystkich Pismach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 28, 'I zbliżyli się do wsi, do której szli, a on zachowywał się tak, jakby miał iść dalej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 29, 'Lecz oni go przymusili, mówiąc: Zostań z nami, bo zbliża się wieczór i dzień się już kończy. Wszedł więc, aby z nimi zostać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 30, 'A gdy siedział z nimi za stołem, wziął chleb, pobłogosławił i łamiąc, podawał im.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 31, 'Wtedy otworzyły się im oczy i poznali go, lecz on zniknął im z oczu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 32, 'I mówili między sobą: Czy nasze serce nie pałało w nas, gdy rozmawiał z nami w drodze i otwierał nam Pisma?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 33, 'A wstawszy o tej godzinie, wrócili do Jerozolimy i zastali zgromadzonych jedenastu i tych, którzy z nimi byli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 34, 'Ci mówili: Pan naprawdę zmartwychwstał i ukazał się Szymonowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 35, 'Oni zaś opowiedzieli, co się stało w drodze i jak go poznali przy łamaniu chleba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 36, 'A gdy to mówili, sam Jezus stanął pośród nich i powiedział do nich: Pokój wam.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 37, 'A oni się zlękli i przestraszeni myśleli, że widzą ducha.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 38, 'I zapytał ich: Czemu się boicie i czemu myśli budzą się w waszych sercach?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 39, 'Popatrzcie na moje ręce i nogi, że to jestem ja. Dotknijcie mnie i zobaczcie, bo duch nie ma ciała ani kości, jak widzicie, że ja mam.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 40, 'Kiedy to powiedział, pokazał im ręce i nogi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 41, 'Lecz gdy oni z radości jeszcze nie wierzyli i dziwili się, zapytał ich: Macie tu coś do jedzenia?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 42, 'I podali mu kawałek pieczonej ryby i plaster miodu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 43, 'A on wziął i jadł przy nich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 44, 'Potem powiedział do nich: To są słowa, które mówiłem do was, będąc jeszcze z wami, że musi się wypełnić wszystko, co jest o mnie napisane w Prawie Mojżesza, u Proroków i w Psalmach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 45, 'Wtedy otworzył ich umysły, żeby rozumieli Pisma.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 46, 'I powiedział im: Tak jest napisane i tak Chrystus musiał cierpieć, i trzeciego dnia zmartwychwstać;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 47, 'I w jego imieniu ma być głoszona pokuta i przebaczenie grzechów wszystkim narodom, począwszy od Jerozolimy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 48, 'A wy jesteście tego świadkami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 49, 'A oto ja ześlę na was obietnicę mego Ojca, a wy zostańcie w mieście Jerozolimie, aż będziecie przyobleczeni mocą z wysoka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 50, 'I wyprowadził ich aż do Betanii, a podniósłszy ręce, błogosławił ich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 51, 'A gdy ich błogosławił, rozstał się z nimi i został uniesiony w górę do nieba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 52, 'A oni oddali mu pokłon i wrócili do Jerozolimy z wielką radością.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 53, 'I byli zawsze w świątyni, chwaląc i błogosławiąc Boga. Amen.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 1, 'Na początku było Słowo, a Słowo było u Boga i Bogiem było Słowo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 2, 'Ono było na początku u Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 3, 'Wszystko przez nie się stało, a bez niego nic się nie stało, co się stało.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 4, 'W nim było życie, a życie było światłością ludzi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 5, 'A ta światłość świeci w ciemności, ale ciemność jej nie ogarnęła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 6, 'Był człowiek posłany od Boga, któremu na imię było Jan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 7, 'Przyszedł on na świadectwo, aby świadczyć o tej światłości, by wszyscy przez niego uwierzyli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 8, 'Nie był on tą światłością, ale przyszedł, aby świadczyć o tej światłości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 9, 'Ten był tą prawdziwą światłością, która oświeca każdego człowieka przychodzącego na świat.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 10, 'Był na świecie, a świat został przez niego stworzony, ale świat go nie poznał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 11, 'Do swej własności przyszedł, ale swoi go nie przyjęli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 12, 'Lecz wszystkim tym, którzy go przyjęli, dał moc, aby się stali synami Bożymi, to jest tym, którzy wierzą w jego imię;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 13, 'Którzy są narodzeni nie z krwi ani z woli ciała, ani z woli mężczyzny, ale z Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 14, 'A to Słowo stało się ciałem i mieszkało wśród nas (i widzieliśmy jego chwałę, chwałę jako jednorodzonego od Ojca), pełne łaski i prawdy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 15, 'Jan świadczył o nim i wołał: To był ten, o którym mówiłem: Ten, który po mnie przychodzi, uprzedził mnie, bo wcześniej był niż ja.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 16, 'A z jego pełni my wszyscy otrzymaliśmy i łaskę za łaskę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 17, 'Prawo bowiem zostało dane przez Mojżesza, a łaska i prawda przyszły przez Jezusa Chrystusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 18, 'Boga nikt nigdy nie widział. Jednorodzony Syn, który jest w łonie Ojca, on nam o nim opowiedział.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 19, 'A takie jest świadectwo Jana, gdy Żydzi posłali z Jerozolimy kapłanów i lewitów, aby go zapytali: Kim ty jesteś?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 20, 'I wyznał, a nie zaprzeczył, ale wyznał: Ja nie jestem Chrystusem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 21, 'I pytali go: Kim więc jesteś? Jesteś Eliaszem? A on powiedział: Nie jestem. A oni: Jesteś tym prorokiem? I odpowiedział: Nie jestem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 22, 'Wtedy go zapytali: Kim jesteś, abyśmy mogli dać odpowiedź tym, którzy nas posłali? Co mówisz sam o sobie?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 23, 'Odpowiedział: Ja jestem głosem wołającego na pustyni: Prostujcie drogę Pana, jak powiedział prorok Izajasz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 24, 'A ci, którzy byli posłani, byli z faryzeuszy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 25, 'I zapytali go: Czemu więc chrzcisz, jeśli nie jesteś Chrystusem ani Eliaszem, ani tym prorokiem?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 26, 'Odpowiedział im Jan: Ja chrzczę wodą, ale pośród was stoi ten, którego wy nie znacie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 27, 'To jest ten, który przyszedłszy po mnie, uprzedził mnie, któremu ja nie jestem godny rozwiązać rzemyka u jego obuwia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 28, 'Działo się to w Betabarze za Jordanem, gdzie Jan chrzcił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 29, 'A nazajutrz Jan zobaczył Jezusa przychodzącego do niego i powiedział: Oto Baranek Boży, który gładzi grzech świata.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 30, 'To jest ten, o którym mówiłem, że idzie za mną człowiek, który mnie uprzedził, bo wcześniej był niż ja.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 31, 'Ja go nie znałem, ale przyszedłem, chrzcząc wodą, po to, aby został objawiony Izraelowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 32, 'I świadczył Jan: Widziałem Ducha zstępującego jak gołębica z nieba i spoczął na nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 33, 'A ja go nie znałem, ale ten, który mnie posłał, abym chrzcił wodą, powiedział do mnie: Na kogo ujrzysz Ducha zstępującego i spoczywającego na nim, to jest ten, który chrzci Duchem Świętym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 34, 'Ja to widziałem i świadczyłem, że on jest Synem Bożym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 35, 'Nazajutrz znowu stał tam Jan i dwóch z jego uczniów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 36, 'A gdy zobaczył Jezusa przechodzącego, powiedział: Oto Baranek Boży.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 37, 'I słyszeli ci dwaj uczniowie, jak mówił, i poszli za Jezusem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 38, 'A Jezus, odwróciwszy się i ujrzawszy, że idą za nim, zapytał ich: Czego szukacie? A oni mu odpowiedzieli: Rabbi – co się tłumaczy: Mistrzu – gdzie mieszkasz?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 39, 'Powiedział im: Chodźcie i zobaczcie. Poszli więc i zobaczyli, gdzie mieszka. I zostali z nim tego dnia, bo było około godziny dziesiątej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 40, 'A Andrzej, brat Szymona Piotra, był jednym z tych dwóch, którzy to usłyszeli od Jana i poszli za nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 41, 'On najpierw znalazł Szymona, swego brata, i powiedział do niego: Znaleźliśmy Mesjasza – co się tłumaczy: Chrystusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 42, 'I przyprowadził go do Jezusa. A Jezus spojrzał na niego i powiedział: Ty jesteś Szymon, syn Jonasza. Ty będziesz nazwany Kefas – co się tłumaczy: Piotr.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 43, 'A nazajutrz Jezus chciał pójść do Galilei. Znalazł Filipa i powiedział do niego: Pójdź za mną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 44, 'A Filip był z Betsaidy, z miasta Andrzeja i Piotra.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 45, 'Filip znalazł Natanaela i powiedział do niego: Znaleźliśmy tego, o którym pisał Mojżesz w Prawie, a także prorocy – Jezusa z Nazaretu, syna Józefa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 46, 'I zapytał go Natanael: Czyż z Nazaretu może być coś dobrego? Filip mu odpowiedział: Chodź i zobacz!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 47, 'Gdy więc Jezus zobaczył Natanaela zbliżającego się do niego, powiedział o nim: Oto prawdziwie Izraelita, w którym nie ma podstępu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 48, 'Natanael go zapytał: Skąd mnie znasz? Odpowiedział mu Jezus: Zanim Filip cię zawołał, gdy byłeś pod drzewem figowym, widziałem cię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 49, 'Odpowiedział mu Natanael: Mistrzu, ty jesteś Synem Bożym, ty jesteś królem Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 50, 'Jezus mu odpowiedział: Czy wierzysz dlatego, że ci powiedziałem: Widziałem cię pod drzewem figowym? Ujrzysz większe rzeczy niż te.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 51, 'I powiedział do niego: Zaprawdę, zaprawdę powiadam wam: Odtąd ujrzycie niebo otwarte i aniołów Boga wstępujących i zstępujących na Syna Człowieczego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 1, 'A trzeciego dnia odbywało się wesele w Kanie Galilejskiej i była tam matka Jezusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 2, 'Zaproszono na to wesele także Jezusa i jego uczniów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 3, 'A gdy zabrakło wina, matka Jezusa powiedziała do niego: Nie mają wina.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 4, 'Jezus jej odpowiedział: Co ja mam z tobą, kobieto? Jeszcze nie nadeszła moja godzina.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 5, 'Jego matka powiedziała do sług: Zróbcie wszystko, co wam powie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 6, 'A było tam sześć stągwi kamiennych, postawionych według żydowskiego zwyczaju oczyszczenia, mieszczących każda dwa albo trzy wiadra.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 7, 'Jezus im powiedział: Napełnijcie te stągwie wodą. I napełnili je aż po brzegi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 8, 'Wtedy powiedział do nich: Zaczerpnijcie teraz i zanieście przełożonemu wesela. I zanieśli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 9, 'A gdy przełożony wesela skosztował wody, która stała się winem (a nie wiedział, skąd pochodziło, lecz słudzy, którzy zaczerpnęli wody, wiedzieli), zawołał oblubieńca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 10, 'I powiedział do niego: Każdy człowiek najpierw podaje dobre wino, a gdy sobie podpiją, wtedy gorsze. A ty dobre wino zachowałeś aż do tej pory.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 11, 'Taki początek cudów uczynił Jezus w Kanie Galilejskiej i objawił swoją chwałę, i uwierzyli w niego jego uczniowie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 12, 'Potem on, jego matka, jego bracia i jego uczniowie poszli do Kafarnaum i mieszkali tam kilka dni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 13, 'A ponieważ zbliżała się Pascha żydowska, Jezus poszedł do Jerozolimy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 14, 'I zastał w świątyni sprzedających woły, owce i gołębie oraz tych, którzy siedzieli i wymieniali pieniądze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 15, 'A zrobiwszy bicz z powrozków, wypędził wszystkich ze świątyni, także owce i woły, rozsypał pieniądze wymieniających i poprzewracał stoły.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 16, 'A do sprzedających gołębie powiedział: Wynieście to stąd, a nie róbcie z domu mego Ojca domu kupieckiego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 17, 'I przypomnieli sobie jego uczniowie, że jest napisane: Gorliwość o twój dom zżarła mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 18, 'Wtedy Żydzi zapytali: Jaki nam znak pokażesz, skoro to czynisz?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 19, 'Odpowiedział im Jezus: Zburzcie tę świątynię, a w trzy dni ją wzniosę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 20, 'Wtedy Żydzi powiedzieli: Czterdzieści sześć lat budowano tę świątynię, a ty ją w trzy dni wzniesiesz?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 21, 'Ale on mówił o świątyni swego ciała.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 22, 'Gdy więc zmartwychwstał, jego uczniowie przypomnieli sobie, że im to powiedział, i uwierzyli Pismu i słowu, które wypowiedział Jezus.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 23, 'A gdy był w Jerozolimie podczas Paschy w święto, wielu uwierzyło w jego imię, widząc cuda, które czynił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 24, 'Ale Jezus nie powierzał im samego siebie, bo on znał wszystkich;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 25, 'I nie potrzebował, aby mu ktoś dawał świadectwo o człowieku. On bowiem wiedział, co było w człowieku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 1, 'A był pewien człowiek z faryzeuszy, imieniem Nikodem, dostojnik żydowski.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 2, 'Przyszedł on do Jezusa w nocy i powiedział: Mistrzu, wiemy, że przyszedłeś od Boga jako nauczyciel. Nikt bowiem nie mógłby czynić tych cudów, które ty czynisz, gdyby Bóg z nim nie był.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 3, 'Odpowiedział mu Jezus: Zaprawdę, zaprawdę powiadam ci: Jeśli się ktoś nie narodzi na nowo, nie może ujrzeć królestwa Bożego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 4, 'Nikodem zapytał go: Jakże może się człowiek narodzić, będąc stary? Czy może powtórnie wejść do łona swojej matki i narodzić się?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 5, 'Jezus odpowiedział: Zaprawdę, zaprawdę powiadam ci: Jeśli się ktoś nie narodzi z wody i z Ducha, nie może wejść do królestwa Bożego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 6, 'Co się narodziło z ciała, jest ciałem, a co się narodziło z Ducha, jest duchem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 7, 'Nie dziw się, że ci powiedziałem: Musicie się na nowo narodzić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 8, 'Wiatr wieje, gdzie chce, i słyszysz jego głos, ale nie wiesz, skąd przychodzi i dokąd zmierza. Tak jest z każdym, kto się narodził z Ducha.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 9, 'Nikodem go zapytał: Jakże się to może stać?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 10, 'Odpowiedział mu Jezus: Ty jesteś nauczycielem w Izraelu, a tego nie wiesz?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 11, 'Zaprawdę, zaprawdę powiadam ci, że co wiemy, to mówimy, a co widzieliśmy, o tym świadczymy, ale nie przyjmujecie naszego świadectwa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 12, 'Jeśli nie wierzycie, gdy wam mówiłem o ziemskich sprawach, jakże uwierzycie, jeśli będę wam mówił o niebieskich?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 13, 'A nikt nie wstąpił do nieba, tylko ten, który zstąpił z nieba, Syn Człowieczy, który jest w niebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 14, 'A jak Mojżesz wywyższył węża na pustyni, tak musi być wywyższony Syn Człowieczy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 15, 'Aby każdy, kto w niego wierzy, nie zginął, ale miał życie wieczne.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 16, 'Tak bowiem Bóg umiłował świat, że dał swego jednorodzonego Syna, aby każdy, kto w niego wierzy, nie zginął, ale miał życie wieczne.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 17, 'Bo Bóg nie posłał swego Syna na świat, aby potępił świat, lecz aby świat był przez niego zbawiony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 18, 'Kto wierzy w niego, nie będzie potępiony, ale kto nie wierzy, już jest potępiony, bo nie uwierzył w imię jednorodzonego Syna Bożego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 19, 'A potępienie polega na tym, że światłość przyszła na świat, lecz ludzie umiłowali ciemność bardziej niż światłość, bo ich uczynki były złe.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 20, 'Każdy bowiem, kto źle czyni, nienawidzi światłości i nie idzie do światłości, aby jego uczynki nie były zganione.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 21, 'Lecz kto czyni prawdę, przychodzi do światłości, aby jego uczynki były jawne, że w Bogu są dokonane.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 22, 'Potem Jezus przyszedł wraz ze swymi uczniami do Judei i tam przemieszkiwał z nimi, i chrzcił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 23, 'Także Jan chrzcił w Ainon, blisko Salim, bo było tam wiele wody. A ludzie przychodzili i chrzcili się.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 24, 'Jan bowiem jeszcze nie był wtrącony do więzienia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 25, 'Wtedy wszczęła się dyskusja między uczniami Jana i Żydami o oczyszczaniu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 26, 'I przyszli do Jana, i powiedzieli mu: Mistrzu, ten, który był z tobą za Jordanem, o którym ty dałeś świadectwo, oto on chrzci, a wszyscy idą do niego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 27, 'Odpowiedział Jan: Człowiek nie może otrzymać niczego, jeśli mu nie będzie dane z nieba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 28, 'Wy sami jesteście mi świadkami, że powiedziałem: Ja nie jestem Chrystusem, ale jestem posłany przed nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 29, 'Kto ma oblubienicę, ten jest oblubieńcem, a przyjaciel oblubieńca, który stoi i słucha go, raduje się niezmiernie z powodu głosu oblubieńca. Dlatego ta moja radość stała się pełna.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 30, 'On musi wzrastać, a ja stawać się mniejszym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 31, 'Kto przyszedł z góry, jest nad wszystkimi. Kto jest z ziemi, jest ziemski i mówi ziemskie rzeczy. Ten, który przyszedł z nieba, jest nad wszystkimi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 32, 'A świadczy o tym, co widział i słyszał, ale nikt nie przyjmuje jego świadectwa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 33, 'Kto przyjmuje jego świadectwo, ten zapieczętował, że Bóg jest prawdziwy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 34, 'Ten bowiem, którego Bóg posłał, mówi słowa Boże, bo Bóg daje mu Ducha bez miary.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 35, 'Ojciec miłuje Syna i wszystko dał w jego ręce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 36, 'Kto wierzy w Syna, ma życie wieczne, ale kto nie wierzy Synowi, nie ujrzy życia, lecz gniew Boży zostaje na nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 1, 'A gdy Pan poznał, że faryzeusze usłyszeli, iż Jezus więcej ludzi czynił uczniami i chrzcił niż Jan;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 2, '(Chociaż sam Jezus nie chrzcił, lecz jego uczniowie);');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 3, 'Opuścił Judeę i odszedł znowu do Galilei.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 4, 'A musiał iść przez Samarię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 5, 'I przyszedł do miasta w Samarii, zwanego Sychar, blisko pola, które Jakub dał swemu synowi Józefowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 6, 'A była tam studnia Jakuba. Jezus więc, zmęczony drogą, usiadł sobie na studni. A było około godziny szóstej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 7, 'I przyszła kobieta z Samarii, aby zaczerpnąć wody. Jezus powiedział do niej: Daj mi pić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 8, 'Jego uczniowie bowiem poszli do miasta, aby nakupić żywności.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 9, 'Wtedy Samarytanka powiedziała do niego: Jakże ty, będąc Żydem, prosisz mnie, Samarytankę, o coś do picia? Gdyż Żydzi nie obcują z Samarytanami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 10, 'Jezus jej odpowiedział: Gdybyś znała ten dar Boży i wiedziała, kim jest ten, który ci mówi: Daj mi pić, ty prosiłabyś go, a dałby ci wody żywej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 11, 'I powiedziała do niego kobieta: Panie, nie masz czym naczerpać, a studnia jest głęboka. Skąd więc masz tę wodę żywą?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 12, 'Czy ty jesteś większy niż nasz ojciec Jakub, który nam dał tę studnię i sam z niej pił, a także jego synowie i jego dobytek?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 13, 'Odpowiedział jej Jezus: Każdy, kto pije tę wodę, znowu będzie pragnął.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 14, 'Lecz kto by pił wodę, którą ja mu dam, nigdy nie będzie pragnął, ale woda, którą ja mu dam, stanie się w nim źródłem wody wytryskującej ku życiu wiecznemu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 15, 'Kobieta powiedziała do niego: Panie, daj mi tej wody, abym nie pragnęła i nie przychodziła tu czerpać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 16, 'Jezus jej powiedział: Idź, zawołaj swego męża i przyjdź tu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 17, 'Odpowiedziała kobieta: Nie mam męża. Jezus jej powiedział: Dobrze powiedziałaś: Nie mam męża.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 18, 'Miałaś bowiem pięciu mężów, a ten, którego masz teraz, nie jest twoim mężem. Prawdę powiedziałaś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 19, 'Kobieta mu powiedziała: Panie, widzę, że jesteś prorokiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 20, 'Nasi ojcowie na tej górze czcili Boga, a wy mówicie, że w Jerozolimie jest miejsce, gdzie należy go czcić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 21, 'Jezus powiedział do niej: Kobieto, wierz mi, że nadchodzi godzina, gdy ani na tej górze, ani w Jerozolimie nie będziecie czcić Ojca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 22, 'Wy czcicie to, czego nie znacie, a my czcimy to, co znamy, ponieważ zbawienie pochodzi od Żydów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 23, 'Ale nadchodzi godzina, i teraz jest, gdy prawdziwi czciciele będą czcić Ojca w duchu i w prawdzie. Bo i Ojciec szuka takich, którzy będą go czcić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 24, 'Bóg jest duchem, więc ci, którzy go czczą, powinni go czcić w duchu i w prawdzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 25, 'Kobieta mu powiedziała: Wiem, że przyjdzie Mesjasz, zwany Chrystusem. Gdy on przyjdzie, oznajmi nam wszystko.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 26, 'Jezus jej powiedział: Ja, który mówię z tobą, jestem nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 27, 'A wtem przyszli jego uczniowie i dziwili się, że rozmawia z kobietą. Nikt jednak nie powiedział: O co się pytasz? albo: Dlaczego z nią rozmawiasz?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 28, 'I zostawiła kobieta swoje wiadro, poszła do miasta i powiedziała ludziom:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 29, 'Chodźcie, zobaczcie człowieka, który mi powiedział wszystko, co zrobiłam. Czy to nie jest Chrystus?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 30, 'Wyszli więc z miasta i przyszli do niego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 31, 'A tymczasem uczniowie prosili go: Mistrzu, jedz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 32, 'A on im powiedział: Ja mam pokarm do jedzenia, o którym wy nie wiecie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 33, 'Uczniowie więc mówili między sobą: Czy ktoś przyniósł mu jedzenie?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 34, 'Jezus im powiedział: Moim pokarmem jest wypełniać wolę tego, który mnie posłał, i dokonać jego dzieła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 35, 'Czyż nie mówicie, że jeszcze cztery miesiące, a przyjdzie żniwo? Oto mówię wam: Podnieście wasze oczy i przypatrzcie się polom, że już są białe, gotowe do żniwa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 36, 'A kto żnie, otrzymuje zapłatę i zbiera owoc na życie wieczne, aby i ten, kto sieje, i ten, kto żnie, razem się radowali.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 37, 'W tym właśnie prawdziwe jest przysłowie: Kto inny sieje, a kto inny żnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 38, 'Ja was posłałem żąć to, nad czym nie pracowaliście. Inni pracowali, a wy weszliście w ich pracę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 39, 'Wtedy wielu Samarytan z tego miasta uwierzyło w niego z powodu opowiadania tej kobiety, która świadczyła: Powiedział mi wszystko, co zrobiłam.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 40, 'Gdy więc Samarytanie przyszli do niego, prosili go, aby u nich został. I został tam przez dwa dni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 41, 'I o wiele więcej ich uwierzyło z powodu jego słowa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 42, 'A tej kobiecie mówili: Wierzymy już nie z powodu twojego opowiadania. Sami bowiem słyszeliśmy i wiemy, że to jest prawdziwie Zbawiciel świata, Chrystus.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 43, 'A po dwóch dniach odszedł stamtąd i poszedł do Galilei.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 44, 'Sam Jezus bowiem dał świadectwo, że prorok nie doznaje czci w swojej ojczyźnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 45, 'A gdy przyszedł do Galilei, Galilejczycy przyjęli go, widząc wszystko, co uczynił w Jerozolimie w święto. Oni bowiem też przyszli na święto.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 46, 'Wtedy Jezus znowu przyszedł do Kany Galilejskiej, gdzie przemienił wodę w wino. A był w Kafarnaum pewien dworzanin królewski, którego syn chorował.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 47, 'Ten, usłyszawszy, że Jezus przyszedł z Judei do Galilei, udał się do niego i prosił go, aby przyszedł i uzdrowił jego syna, gdyż był umierający.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 48, 'I powiedział do niego Jezus: Jeśli nie ujrzycie znaków i cudów, nie uwierzycie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 49, 'Dworzanin królewski powiedział do niego: Panie, przyjdź, zanim umrze moje dziecko.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 50, 'Jezus mu powiedział: Idź, twój syn żyje. I uwierzył ten człowiek słowu, które powiedział mu Jezus, i poszedł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 51, 'A gdy już szedł, jego słudzy wyszli mu naprzeciw i oznajmili: Twoje dziecko żyje.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 52, 'Wtedy zapytał ich o godzinę, w której poczuło się lepiej. I odpowiedzieli mu: Wczoraj o godzinie siódmej opuściła go gorączka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 53, 'Wówczas ojciec poznał, że to była ta godzina, w której Jezus powiedział do niego: Twój syn żyje. I uwierzył on sam i cały jego dom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 54, 'To był drugi cud, który Jezus uczynił, przyszedłszy z Judei do Galilei.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 1, 'Potem było święto żydowskie i Jezus udał się do Jerozolimy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 2, 'A jest w Jerozolimie przy Owczej Bramie sadzawka, zwana po hebrajsku Betesda, mająca pięć ganków.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 3, 'Leżało w nich mnóstwo niedołężnych, ślepych, chromych i wychudłych, którzy czekali na poruszenie wody.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 4, 'Anioł bowiem co pewien czas zstępował do sadzawki i poruszał wodę. A kto pierwszy wszedł po poruszeniu wody, stawał się zdrowym, jakąkolwiek chorobą był dotknięty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 5, 'A był tam pewien człowiek, który przez trzydzieści osiem lat był złożony chorobą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 6, 'Gdy Jezus zobaczył go leżącego i poznał, że już długi czas choruje, zapytał: Chcesz być zdrowy?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 7, 'Chory mu odpowiedział: Panie, nie mam człowieka, który wniósłby mnie do sadzawki, gdy woda zostaje poruszona. Lecz gdy ja idę, inny wchodzi przede mną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 8, 'Jezus mu powiedział: Wstań, weź swoje posłanie i chodź.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 9, 'I natychmiast człowiek ten odzyskał zdrowie, wziął swoje posłanie i chodził. A tego dnia był szabat.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 10, 'Wtedy Żydzi powiedzieli do uzdrowionego: Jest szabat, nie wolno ci nosić posłania.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 11, 'Odpowiedział im: Ten, który mnie uzdrowił, powiedział do mnie: Weź swoje posłanie i chodź.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 12, 'I pytali go: Który człowiek ci powiedział: Weź swoje posłanie i chodź?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 13, 'A uzdrowiony nie wiedział, kto to był, bo Jezus odszedł, ponieważ mnóstwo ludzi było na tym miejscu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 14, 'Potem Jezus znalazł go w świątyni i powiedział do niego: Oto wyzdrowiałeś. Nie grzesz więcej, aby nie przydarzyło ci się coś gorszego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 15, 'Wtedy człowiek ten odszedł i powiedział Żydom, że to Jezus go uzdrowił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 16, 'I dlatego Żydzi prześladowali Jezusa i szukali sposobności, aby go zabić, bo uczynił to w szabat.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 17, 'A Jezus im odpowiedział: Mój Ojciec działa aż dotąd i ja działam.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 18, 'Dlatego Żydzi tym bardziej usiłowali go zabić, bo nie tylko łamał szabat, ale mówił, że Bóg jest jego Ojcem, czyniąc się równym Bogu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 19, 'Wtedy Jezus im odpowiedział: Zaprawdę, zaprawdę powiadam wam: Syn nie może nic czynić sam od siebie, tylko to, co widzi, że czyni Ojciec. Co bowiem on czyni, to i Syn czyni tak samo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 20, 'Bo Ojciec miłuje Syna i ukazuje mu wszystko, co sam czyni. I pokaże mu większe dzieła niż te, abyście się dziwili.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 21, 'Jak bowiem Ojciec wskrzesza umarłych i ożywia, tak i Syn ożywia tych, których chce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 22, 'Bo Ojciec nikogo nie sądzi, lecz cały sąd dał Synowi;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 23, 'Aby wszyscy czcili Syna, jak czczą Ojca. Kto nie czci Syna, nie czci i Ojca, który go posłał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 24, 'Zaprawdę, zaprawdę powiadam wam: Kto słucha mego słowa i wierzy temu, który mnie posłał, ma życie wieczne i nie będzie potępiony, ale przeszedł ze śmierci do życia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 25, 'Zaprawdę, zaprawdę powiadam wam: Nadchodzi godzina, i teraz jest, gdy umarli usłyszą głos Syna Bożego, a ci, którzy usłyszą, będą żyć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 26, 'Jak bowiem Ojciec ma życie sam w sobie, tak dał i Synowi, aby miał życie w samym sobie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 27, 'I dał mu władzę wykonywania sądu, bo jest Synem Człowieczym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 28, 'Nie dziwcie się temu, bo nadchodzi godzina, w której wszyscy, którzy są w grobach, usłyszą jego głos;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 29, 'I ci, którzy dobrze czynili, wyjdą na zmartwychwstanie do życia, ale ci, którzy źle czynili, na zmartwychwstanie na potępienie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 30, 'Ja sam od siebie nie mogę nic czynić. Jak słyszę, tak sądzę, a mój sąd jest sprawiedliwy, bo nie szukam swojej woli, ale woli tego, który mnie posłał, Ojca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 31, 'Jeśli ja świadczę sam o sobie, moje świadectwo nie jest prawdziwe.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 32, 'Jest ktoś inny, kto świadczy o mnie, i wiem, że świadectwo, które daje o mnie, jest prawdziwe.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 33, 'Wy posłaliście do Jana, a on dał świadectwo prawdzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 34, 'Lecz ja nie przyjmuję świadectwa od człowieka, ale to mówię, abyście byli zbawieni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 35, 'On był płonącą i świecącą lampą, a wy chcieliście do czasu radować się w jego światłości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 36, 'Ale ja mam świadectwo większe niż Jana. Dzieła bowiem, które Ojciec dał mi do wykonania, te właśnie dzieła, które czynię, świadczą o mnie, że Ojciec mnie posłał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 37, 'A Ojciec, który mnie posłał, on świadczył o mnie. Nigdy nie słyszeliście jego głosu ani nie widzieliście jego postaci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 38, 'I nie macie jego słowa trwającego w was, bo temu, którego on posłał, nie wierzycie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 39, 'Badajcie Pisma; sądzicie bowiem, że w nich macie życie wieczne, a one dają świadectwo o mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 40, 'A jednak nie chcecie przyjść do mnie, aby mieć życie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 41, 'Nie przyjmuję chwały od ludzi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 42, 'Ale poznałem was, że nie macie w sobie miłości Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 43, 'Przyszedłem w imieniu mego Ojca, a nie przyjmujecie mnie. Jeśli ktoś inny przyjdzie we własnym imieniu, tego przyjmiecie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 44, 'Jakże możecie wierzyć, skoro przyjmujecie chwałę jedni od drugich, a nie szukacie chwały, która jest od samego Boga?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 45, 'Nie sądźcie, że ja was będę oskarżał przed Ojcem. Jest ktoś, kto was oskarża, Mojżesz, w którym wy pokładacie nadzieję.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 46, 'Bo gdybyście wierzyli Mojżeszowi, wierzylibyście i mnie, gdyż on pisał o mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 47, 'Jeśli jednak nie wierzycie jego pismom, jakże uwierzycie moim słowom?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 1, 'Potem Jezus odszedł za Morze Galilejskie, czyli Tyberiadzkie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 2, 'A szedł za nim wielki tłum, bo widzieli cuda, które czynił na chorych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 3, 'I wszedł Jezus na górę, i usiadł tam ze swoimi uczniami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 4, 'A zbliżała się Pascha, święto żydowskie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 5, 'Wtedy Jezus, podniósłszy oczy i ujrzawszy, że mnóstwo ludzi idzie do niego, zapytał Filipa: Gdzie kupimy chleba, aby oni mogli jeść?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 6, 'Ale mówił to, wystawiając go na próbę. Wiedział bowiem, co miał czynić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 7, 'Filip mu odpowiedział: Za dwieście groszy nie wystarczy dla nich chleba, choćby każdy z nich wziął tylko trochę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 8, 'Jeden z jego uczniów, Andrzej, brat Szymona Piotra, powiedział do niego:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 9, 'Jest tu jeden chłopiec, który ma pięć chlebów jęczmiennych i dwie rybki. Ale cóż to jest na tak wielu?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 10, 'Wtedy Jezus powiedział: Każcie ludziom usiąść. A było dużo trawy na tym miejscu. Usiedli więc mężczyźni w liczbie około pięciu tysięcy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 11, 'Wówczas Jezus wziął te chleby i podziękowawszy, rozdał uczniom, a uczniowie siedzącym. Podobnie i z tych rybek, ile tylko chcieli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 12, 'A gdy się nasycili, powiedział do swoich uczniów: Zbierzcie kawałki, które zostały, żeby nic nie przepadło.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 13, 'Zebrali więc i napełnili dwanaście koszy kawałkami, które zostały z tych pięciu chlebów jęczmiennych po tych, którzy jedli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 14, 'A ci ludzie, ujrzawszy cud, który uczynił Jezus, mówili: To jest prawdziwie ten prorok, który miał przyjść na świat.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 15, 'Wtedy Jezus, poznawszy, że mieli przyjść i porwać go, aby go obwołać królem, odszedł znowu sam jeden na górę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 16, 'A gdy był wieczór, jego uczniowie zeszli nad morze;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 17, 'Wsiedli do łodzi i płynęli na drugi brzeg, do Kafarnaum. Było już ciemno, a Jezus jeszcze do nich nie przybył.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 18, 'A kiedy powstał wielki wiatr, morze zaczęło się burzyć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 19, 'Gdy odpłynęli na około dwadzieścia pięć lub trzydzieści stadiów, ujrzeli Jezusa chodzącego po morzu i zbliżającego się do łodzi i zlękli się.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 20, 'A on powiedział do nich: To ja jestem, nie bójcie się.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 21, 'Wzięli go więc chętnie do łodzi i natychmiast łódź przypłynęła do ziemi, do której płynęli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 22, 'Nazajutrz ludzie, którzy byli po drugiej stronie morza, zobaczyli, że tam nie było innej łodzi, tylko ta jedna, do której wsiedli jego uczniowie, i że Jezus nie wsiadł do łodzi ze swoimi uczniami, ale jego uczniowie odpłynęli sami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 23, '(Przypłynęły też inne łodzie z Tyberiady w pobliże tego miejsca, gdzie jedli chleb, gdy Pan złożył dziękczynienie.)');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 24, 'Gdy więc ludzie zobaczyli, że tam nie było Jezusa ani jego uczniów, wsiedli i oni do łodzi i przeprawili się do Kafarnaum, szukając Jezusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 25, 'Kiedy znaleźli go po drugiej stronie morza, zapytali: Mistrzu, kiedy tu przybyłeś?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 26, 'Jezus im odpowiedział: Zaprawdę, zaprawdę powiadam wam: Szukacie mnie nie dlatego, że widzieliście cuda, ale dlatego, że jedliście chleb i nasyciliście się.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 27, 'Zabiegajcie nie o pokarm, który ginie, ale o pokarm, który trwa ku życiu wiecznemu, który wam da Syn Człowieczy. Jego bowiem zapieczętował Bóg Ojciec.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 28, 'Wtedy zapytali go: Cóż mamy robić, abyśmy wykonywali dzieła Boga?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 29, 'Odpowiedział im Jezus: To jest dzieło Boga, abyście wierzyli w tego, którego on posłał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 30, 'Powiedzieli mu więc: Jaki znak czynisz, abyśmy widzieli i wierzyli tobie? Cóż czynisz?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 31, 'Nasi ojcowie jedli mannę na pustyni, jak jest napisane: Chleb z nieba dał im do jedzenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 32, 'Wtedy Jezus im odpowiedział: Zaprawdę, zaprawdę powiadam wam: Nie Mojżesz dał wam chleb z nieba, ale mój Ojciec daje wam prawdziwy chleb z nieba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 33, 'Chlebem Boga bowiem jest ten, który zstępuje z nieba i daje światu życie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 34, 'Wtedy powiedzieli do niego: Panie, dawaj nam zawsze tego chleba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 35, 'I odpowiedział im Jezus: Ja jestem chlebem życia. Kto przychodzi do mnie, nie będzie głodny, a kto wierzy we mnie, nigdy nie będzie odczuwał pragnienia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 36, 'Ale wam powiedziałem: Chociaż widzieliście mnie, nie wierzycie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 37, 'Wszystko, co mi daje Ojciec, przyjdzie do mnie, a tego, który przyjdzie do mnie, nie wyrzucę precz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 38, 'Zstąpiłem bowiem z nieba nie po to, żeby czynić swoją wolę, ale wolę tego, który mnie posłał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 39, 'A to jest wola Ojca, który mnie posłał, abym nie stracił nic z tego wszystkiego, co mi dał, ale abym to wskrzesił w dniu ostatecznym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 40, 'I to jest wola tego, który mnie posłał, aby każdy, kto widzi Syna i wierzy w niego, miał życie wieczne, a ja go wskrzeszę w dniu ostatecznym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 41, 'Wtedy szemrali Żydzi o nim, bo powiedział: Ja jestem chlebem, który zstąpił z nieba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 42, 'I mówili: Czyż to nie jest Jezus, syn Józefa, którego ojca i matkę znamy? Jakże więc on może mówić: Zstąpiłem z nieba?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 43, 'Wtedy Jezus im odpowiedział: Nie szemrajcie między sobą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 44, 'Nikt nie może przyjść do mnie, jeśli go nie pociągnie mój Ojciec, który mnie posłał. A ja go wskrzeszę w dniu ostatecznym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 45, 'Napisane jest u Proroków: I wszyscy będą wyuczeni przez Boga. Każdy więc, kto słyszał od Ojca i nauczył się, przychodzi do mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 46, 'Nie jakby ktoś widział Ojca, oprócz tego, który jest od Boga; ten widział Ojca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 47, 'Zaprawdę, zaprawdę powiadam wam: Kto wierzy we mnie, ma życie wieczne.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 48, 'Ja jestem tym chlebem życia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 49, 'Wasi ojcowie jedli mannę na pustyni, a poumierali.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 50, 'To jest ten chleb, który zstępuje z nieba, aby ten, kto go je, nie umarł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 51, 'Ja jestem chlebem żywym, który zstąpił z nieba. Jeśli ktoś będzie jadł z tego chleba, będzie żył na wieki. A chleb, który ja dam, to moje ciało, które ja dam za życie świata.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 52, 'Żydzi więc sprzeczali się między sobą i mówili: Jakże on może dać nam swoje ciało do jedzenia?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 53, 'I powiedział im Jezus: Zaprawdę, zaprawdę powiadam wam: Jeśli nie będziecie jeść ciała Syna Człowieczego i pić jego krwi, nie będziecie mieć życia w sobie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 54, 'Kto je moje ciało i pije moją krew, ma życie wieczne, a ja go wskrzeszę w dniu ostatecznym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 55, 'Moje ciało bowiem prawdziwie jest pokarmem, a moja krew prawdziwie jest napojem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 56, 'Kto je moje ciało i pije moją krew, mieszka we mnie, a ja w nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 57, 'Jak mnie posłał żyjący Ojciec i ja żyję przez Ojca, tak kto mnie spożywa, będzie żył przeze mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 58, 'To jest ten chleb, który zstąpił z nieba. Nie jak wasi ojcowie jedli mannę, a pomarli. Kto je ten chleb, będzie żył na wieki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 59, 'To mówił w synagodze, nauczając w Kafarnaum.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 60, 'Wielu więc z jego uczniów, słysząc to, mówiło: Twarda to jest mowa, któż jej może słuchać?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 61, 'Ale Jezus świadomy tego, że jego uczniowie o tym szemrali, powiedział do nich: To was obraża?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 62, 'Cóż dopiero, gdybyście ujrzeli Syna Człowieczego wstępującego tam, gdzie był przedtem?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 63, 'Duch jest tym, który ożywia, ciało nic nie pomaga. Słowa, które ja wam mówię, są duchem i są życiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 64, 'Lecz są wśród was tacy, którzy nie wierzą. Jezus wiedział bowiem od początku, którzy nie wierzyli i kto miał go zdradzić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 65, 'I mówił: Dlatego wam powiedziałem, że nikt nie może przyjść do mnie, jeśli mu to nie jest dane od mojego Ojca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 66, 'Od tego czasu wielu jego uczniów zawróciło i więcej z nim nie chodziło.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 67, 'Wtedy Jezus powiedział do dwunastu: Czy i wy chcecie odejść?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 68, 'I odpowiedział mu Szymon Piotr: Panie, do kogo pójdziemy? Ty masz słowa życia wiecznego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 69, 'A my uwierzyliśmy i poznaliśmy, że ty jesteś Chrystusem, Synem Boga żywego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 70, 'Jezus im odpowiedział: Czy ja nie wybrałem was dwunastu? A jeden z was jest diabłem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 71, 'A to mówił o Judaszu Iskariocie, synu Szymona, bo on miał go zdradzić, będąc jednym z dwunastu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 1, 'A potem Jezus chodził po Galilei. Nie chciał bowiem przebywać w Judei, bo Żydzi szukali sposobności, aby go zabić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 2, 'I zbliżało się żydowskie święto Namiotów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 3, 'Wtedy jego bracia powiedzieli do niego: Odejdź stąd i idź do Judei, żeby twoi uczniowie widzieli dzieła, których dokonujesz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 4, 'Nikt bowiem nie czyni nic w ukryciu, jeśli chce być znany. Dlatego ty, jeśli takie rzeczy czynisz, objaw się światu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 5, 'Bo nawet jego bracia nie wierzyli w niego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 6, 'I powiedział do nich Jezus: Mój czas jeszcze nie nadszedł, ale wasz czas zawsze jest w pogotowiu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 7, 'Świat nie może was nienawidzić, ale mnie nienawidzi, bo ja świadczę o nim, że jego uczynki są złe.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 8, 'Wy idźcie na święto, ja jeszcze nie pójdę na to święto, bo mój czas jeszcze się nie wypełnił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 9, 'Powiedziawszy im to, pozostał w Galilei.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 10, 'A gdy jego bracia poszli, wtedy i on poszedł na święto, nie jawnie, ale jakby potajemnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 11, 'A Żydzi szukali go podczas święta i mówili: Gdzie on jest?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 12, 'I wiele szemrało się o nim wśród ludzi, bo jedni mówili: Jest dobry. A inni mówili: Przeciwnie, zwodzi ludzi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 13, 'Nikt jednak nie mówił o nim jawnie z obawy przed Żydami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 14, 'A gdy już minęła połowa święta, Jezus wszedł do świątyni i nauczał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 15, 'I dziwili się Żydzi, mówiąc: Skąd on zna Pismo, skoro się nie uczył?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 16, 'Odpowiedział im Jezus: Moja nauka nie jest moją, ale tego, który mnie posłał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 17, 'Jeśli ktoś chce wypełniać jego wolę, ten będzie umiał rozeznać, czy ta nauka jest od Boga, czy ja mówię sam od siebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 18, 'Kto mówi z samego siebie, szuka własnej chwały. Kto zaś szuka chwały tego, który go posłał, ten jest prawdziwy i nie ma w nim niesprawiedliwości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 19, 'Czy Mojżesz nie dał wam prawa? A żaden z was nie przestrzega prawa. Dlaczego chcecie mnie zabić?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 20, 'Odpowiedzieli ludzie: Masz demona. Kto chce cię zabić?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 21, 'Jezus im odpowiedział: Jeden uczynek spełniłem, a wszyscy się temu dziwicie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 22, 'Przecież Mojżesz dał wam obrzezanie (nie jakoby było od Mojżesza, ale od ojców), a w szabat obrzezujecie człowieka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 23, 'Jeśli człowiek przyjmuje obrzezanie w szabat, aby nie było złamane Prawo Mojżesza, to dlaczego gniewacie się na mnie, że w szabat całkowicie uzdrowiłem człowieka?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 24, 'Nie sądźcie po pozorach, ale sądźcie sprawiedliwym sądem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 25, 'Wtedy niektórzy z mieszkańców Jerozolimy mówili: Czy to nie jest ten, którego chcą zabić?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 26, 'A oto jawnie przemawia i nic mu nie mówią. Czy przełożeni rzeczywiście poznali, że to jest prawdziwie Chrystus?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 27, 'Ale wiemy, skąd on pochodzi, lecz gdy Chrystus przyjdzie, nikt nie będzie wiedział, skąd jest.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 28, 'Wtedy Jezus, nauczając w świątyni, wołał: I znacie mnie, i wiecie, skąd jestem. A ja nie przyszedłem sam od siebie, ale prawdziwy jest ten, który mnie posłał, którego wy nie znacie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 29, 'Lecz ja go znam, bo od niego jestem i on mnie posłał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 30, 'I usiłowali go schwytać, ale nikt nie podniósł na niego ręki, bo jeszcze nie nadeszła jego godzina.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 31, 'A wielu z ludu uwierzyło w niego i mówiło: Gdy Chrystus przyjdzie, czyż uczyni więcej cudów, niż on uczynił?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 32, 'Faryzeusze słyszeli, że tak ludzie o nim szemrali. I faryzeusze i naczelni kapłani posłali sługi, aby go schwytać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 33, 'Wtedy Jezus powiedział im: Jeszcze krótki czas jestem z wami, potem odejdę do tego, który mnie posłał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 34, 'Będziecie mnie szukać, ale nie znajdziecie, a gdzie ja będę, wy przyjść nie możecie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 35, 'Wówczas Żydzi mówili między sobą: Dokąd on pójdzie, że go nie znajdziemy? Czy pójdzie do rozproszonych wśród pogan i będzie nauczał pogan?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 36, 'Cóż to za słowo, które wypowiedział: Będziecie mnie szukać, ale nie znajdziecie, a gdzie ja będę, wy przyjść nie możecie?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 37, 'A w ostatnim, wielkim dniu tego święta, Jezus stanął i wołał: Jeśli ktoś pragnie, niech przyjdzie do mnie i pije.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 38, 'Kto wierzy we mnie, jak mówi Pismo, rzeki wody żywej popłyną z jego wnętrza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 39, 'A to mówił o Duchu, którego mieli otrzymać wierzący w niego. Duch Święty bowiem jeszcze nie był dany, ponieważ Jezus nie został jeszcze uwielbiony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 40, 'Wielu więc z tych ludzi, słysząc te słowa, mówiło: To jest prawdziwie ten prorok.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 41, 'A inni mówili: To jest Chrystus. Lecz niektórzy mówili: Czyż Chrystus przyjdzie z Galilei?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 42, 'Czyż Pismo nie mówi, że Chrystus przyjdzie z potomstwa Dawida i z miasteczka Betlejem, gdzie mieszkał Dawid?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 43, 'I tak z jego powodu nastąpił rozłam wśród ludu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 44, 'I niektórzy z nich chcieli go schwytać, ale nikt nie podniósł na niego ręki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 45, 'Wtedy słudzy wrócili do naczelnych kapłanów i do faryzeuszy, którzy ich zapytali: Dlaczego go nie przyprowadziliście?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 46, 'Słudzy odpowiedzieli: Nikt nigdy nie mówił tak, jak ten człowiek.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 47, 'I odpowiedzieli im faryzeusze: Czy i wy jesteście zwiedzeni?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 48, 'Czy ktoś z przełożonych albo z faryzeuszy uwierzył w niego?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 49, 'A to pospólstwo, które nie zna prawa, jest przeklęte.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 50, 'Jeden z nich, Nikodem, ten, który przyszedł w nocy do niego, powiedział im:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 51, 'Czy nasze prawo potępia człowieka, zanim go najpierw nie wysłucha i nie zbada, co czyni?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 52, 'A oni mu odpowiedzieli: Czy i ty jesteś Galilejczykiem? Zbadaj i zobacz, że żaden prorok nie powstał z Galilei.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 53, 'I poszedł każdy do swego domu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 1, 'A Jezus poszedł na Górę Oliwną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 2, 'Potem znowu wcześnie rano przyszedł do świątyni, a cały lud zszedł się do niego. I siadłszy, nauczał ich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 3, 'I przyprowadzili do niego uczeni w Piśmie i faryzeusze kobietę przyłapaną na cudzołóstwie, a postawiwszy ją pośrodku;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 4, 'Powiedzieli do niego: Nauczycielu, tę kobietę przyłapano na uczynku cudzołóstwa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 5, 'W prawie Mojżesz nakazał nam takie kamienować. A ty co mówisz?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 6, 'A mówili to, wystawiając go na próbę, aby mogli go oskarżyć. Jezus zaś, schyliwszy się, pisał palcem po ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 7, 'A gdy nie przestawali go pytać, podniósł się i powiedział do nich: Kto z was jest bez grzechu, niech pierwszy rzuci w nią kamieniem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 8, 'I znowu schyliwszy się, pisał po ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 9, 'A gdy oni to usłyszeli, będąc przekonani przez sumienie, odchodzili jeden po drugim, począwszy od starszych aż do ostatnich. Pozostał tylko sam Jezus i ta kobieta stojąca pośrodku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 10, 'A Jezus podniósł się i nie widząc nikogo oprócz tej kobiety, powiedział do niej: Kobieto, gdzież są ci, którzy cię oskarżali? Nikt cię nie potępił?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 11, 'Ona odpowiedziała: Nikt, Panie. A Jezus powiedział do niej: I ja ciebie nie potępiam. Idź i już więcej nie grzesz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 12, 'Jezus znowu powiedział do nich: Ja jestem światłością świata. Kto idzie za mną, nie będzie chodził w ciemności, ale będzie miał światłość życia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 13, 'Powiedzieli więc do niego faryzeusze: Ty świadczysz sam o sobie, a twoje świadectwo nie jest prawdziwe.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 14, 'Odpowiedział im Jezus: Chociaż ja świadczę sam o sobie, jednak moje świadectwo jest prawdziwe, bo wiem, skąd przyszedłem i dokąd idę. Lecz wy nie wiecie, skąd przyszedłem i dokąd idę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 15, 'Wy sądzicie według ciała, ale ja nie sądzę nikogo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 16, 'A choćbym i sądził, mój sąd jest prawdziwy, bo nie jestem sam, ale jestem ja i Ojciec, który mnie posłał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 17, 'A w waszym Prawie jest napisane, że świadectwo dwóch ludzi jest prawdziwe.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 18, 'Ja jestem tym, który świadczy sam o sobie i świadczy o mnie Ojciec, który mnie posłał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 19, 'Wtedy zapytali go: Gdzie jest twój Ojciec? Jezus odpowiedział: Nie znacie ani mnie, ani mego Ojca. Gdybyście mnie znali, znalibyście i mego Ojca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 20, 'Te słowa mówił Jezus w skarbcu, nauczając w świątyni, a nikt go nie schwytał, bo jeszcze nie nadeszła jego godzina.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 21, 'Wówczas Jezus znowu powiedział do nich: Ja odchodzę, a wy będziecie mnie szukać i umrzecie w swoim grzechu. Gdzie ja idę, wy przyjść nie możecie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 22, 'Wtedy Żydzi mówili: Czyż sam się zabije, skoro mówi: Gdzie ja idę, wy przyjść nie możecie?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 23, 'I powiedział do nich: Wy jesteście z niskości, a ja jestem z wysoka. Wy jesteście z tego świata, ja zaś nie jestem z tego świata.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 24, 'Dlatego wam powiedziałem, że umrzecie w swoich grzechach. Bo jeśli nie uwierzycie, że ja jestem, umrzecie w swoich grzechach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 25, 'Wtedy zapytali go: Kim ty jesteś? I odpowiedział im Jezus: Tym, kim wam od początku mówię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 26, 'Wiele mam o was do powiedzenia i do sądzenia. Ale ten, który mnie posłał, jest prawdziwy, a ja mówię na świecie to, co od niego słyszałem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 27, 'Nie zrozumieli jednak, że mówił im o Ojcu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 28, 'Dlatego Jezus powiedział do nich: Gdy wywyższycie Syna Człowieczego, wtedy poznacie, że ja jestem, a nie czynię nic sam od siebie, ale mówię to, czego mnie nauczył mój Ojciec.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 29, 'A ten, który mnie posłał, jest ze mną. Ojciec nie zostawił mnie samego, bo ja zawsze czynię to, co mu się podoba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 30, 'Gdy to mówił, wielu uwierzyło w niego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 31, 'Wtedy Jezus mówił do tych Żydów, którzy mu uwierzyli: Jeśli będziecie trwać w moim słowie, będziecie prawdziwie moimi uczniami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 32, 'I poznacie prawdę, a prawda was wyzwoli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 33, 'Odpowiedzieli mu: My jesteśmy potomstwem Abrahama i nigdy nie służyliśmy nikomu. Jakże możesz mówić: Będziecie wolni?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 34, 'Jezus im odpowiedział: Zaprawdę, zaprawdę powiadam wam, że każdy, kto popełnia grzech, jest sługą grzechu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 35, 'A sługa nie mieszka w domu na wieki, lecz Syn mieszka na wieki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 36, 'Jeśli więc Syn was wyzwoli, będziecie prawdziwie wolni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 37, 'Wiem, że jesteście potomstwem Abrahama, lecz usiłujecie mnie zabić, bo moje słowo nie znajduje w was miejsca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 38, 'Ja mówię to, co widziałem u mego Ojca, a wy też robicie to, co widzieliście u waszego ojca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 39, 'Odpowiedzieli mu: Naszym ojcem jest Abraham. Jezus im powiedział: Gdybyście byli synami Abrahama, spełnialibyście uczynki Abrahama.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 40, 'Lecz teraz usiłujecie mnie zabić, człowieka, który wam mówił prawdę, którą słyszał od Boga. Tego Abraham nie robił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 41, 'Wy spełniacie uczynki waszego ojca. Wtedy powiedzieli mu: My nie jesteśmy spłodzeni z nierządu. Mamy jednego Ojca – Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 42, 'Jezus im powiedział: Gdyby Bóg był waszym Ojcem, miłowalibyście mnie, gdyż ja od Boga wyszedłem i przyszedłem, a nie przyszedłem sam od siebie, ale on mnie posłał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 43, 'Dlaczego nie pojmujecie tego, co mówię? Dlatego że nie możecie słuchać mojego słowa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 44, 'Wy jesteście z waszego ojca – diabła i chcecie spełniać pożądliwości waszego ojca. On był mordercą od początku i nie został w prawdzie, bo nie ma w nim prawdy. Gdy mówi kłamstwo, mówi od siebie, bo jest kłamcą i ojcem kłamstwa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 45, 'A ponieważ ja mówię prawdę, nie wierzycie mi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 46, 'Któż z was obwini mnie o grzech? Jeśli mówię prawdę, dlaczego mi nie wierzycie?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 47, 'Kto jest z Boga, słucha słów Bożych. Wy dlatego nie słuchacie, że nie jesteście z Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 48, 'Wtedy Żydzi mu odpowiedzieli: Czy nie dobrze mówimy, że jesteś Samarytaninem i masz demona?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 49, 'Jezus odpowiedział: Ja nie mam demona, ale czczę mego Ojca, a wy mnie znieważacie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 50, 'Ja nie szukam swojej chwały. Jest ktoś, kto szuka i sądzi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 51, 'Zaprawdę, zaprawdę powiadam wam: Jeśli ktoś będzie zachowywał moje słowa, nigdy nie ujrzy śmierci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 52, 'Wtedy Żydzi powiedzieli do niego: Teraz wiemy, że masz demona. Abraham umarł i prorocy, a ty mówisz: Jeśli ktoś będzie zachowywał moje słowa, nigdy nie skosztuje śmierci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 53, 'Czy ty jesteś większy od naszego ojca Abrahama, który umarł? I prorocy poumierali. Kim ty się czynisz?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 54, 'Jezus odpowiedział: Jeśli ja sam siebie chwalę, moja chwała jest niczym. Mój Ojciec jest tym, który mnie chwali, o którym wy mówicie, że jest waszym Bogiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 55, 'Lecz nie znacie go, a ja go znam. I jeślibym powiedział, że go nie znam, byłbym podobnym do was kłamcą. Ale znam go i zachowuję jego słowa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 56, 'Abraham, wasz ojciec, z radością pragnął ujrzeć mój dzień. I ujrzał, i radował się.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 57, 'Wówczas Żydzi powiedzieli do niego: Pięćdziesięciu lat jeszcze nie masz, a Abrahama widziałeś?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 58, 'Jezus im odpowiedział: Zaprawdę, zaprawdę powiadam wam: Zanim Abraham był, ja jestem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 59, 'Wtedy porwali kamienie, aby w niego rzucać. Jezus jednak ukrył się i wyszedł ze świątyni, przechodząc między nimi, i tak odszedł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 1, 'A przechodząc, zobaczył człowieka ślepego od urodzenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 2, 'I pytali go jego uczniowie: Mistrzu, kto zgrzeszył, on czy jego rodzice, że się urodził ślepy?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 3, 'Jezus odpowiedział: Ani on nie zgrzeszył, ani jego rodzice, ale stało się tak, żeby się na nim objawiły dzieła Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 4, 'Ja muszę wykonywać dzieła tego, który mnie posłał, dopóki jest dzień. Nadchodzi noc, gdy nikt nie będzie mógł działać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 5, 'Dopóki jestem na świecie, jestem światłością świata.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 6, 'To powiedziawszy, splunął na ziemię, zrobił błoto ze śliny i pomazał tym błotem oczy ślepego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 7, 'I powiedział do niego: Idź, umyj się w sadzawce Siloam – co się tłumaczy: Posłany. Poszedł więc, umył się i wrócił, widząc.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 8, 'A sąsiedzi i ci, którzy go przedtem widywali ślepego, mówili: Czy to nie jest ten, który siadał i żebrał?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 9, 'Jedni mówili: To on. A inni: Jest do niego podobny. Lecz on mówił: To ja jestem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 10, 'Wtedy zapytali go: Jak zostały otworzone twoje oczy?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 11, 'A on odpowiedział: Człowiek, którego nazywają Jezusem, zrobił błoto, pomazał moje oczy i powiedział do mnie: Idź do sadzawki Siloam i umyj się. Poszedłem więc, umyłem się i przejrzałem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 12, 'Wtedy zapytali go: Gdzież on jest? Odpowiedział: Nie wiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 13, 'Przyprowadzili więc do faryzeuszy tego, który przedtem był ślepy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 14, 'A tego dnia, gdy Jezus zrobił błoto i otworzył jego oczy, był szabat.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 15, 'Wówczas również faryzeusze pytali go, w jaki sposób przejrzał. A on im odpowiedział: Nałożył mi błoto na oczy, umyłem się i widzę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 16, 'Wtedy niektórzy z faryzeuszy powiedzieli: Ten człowiek nie jest z Boga, bo nie przestrzega szabatu. Inni natomiast mówili: Jak może grzeszny człowiek czynić takie cuda? I nastąpił wśród nich rozłam.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 17, 'Zapytali więc znowu ślepego: Co mówisz o nim, skoro otworzył twoje oczy? A on odpowiedział: Jest prorokiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 18, 'A Żydzi nie wierzyli, że był ślepy i odzyskał wzrok, aż zawołali rodziców tego, który przejrzał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 19, 'I pytali ich: Czy to jest wasz syn, o którym mówicie, że się urodził ślepy? Jakże więc teraz widzi?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 20, 'Odpowiedzieli im jego rodzice: Wiemy, że to jest nasz syn i że się urodził ślepy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 21, 'Lecz jakim sposobem teraz widzi, nie wiemy, ani kto otworzył jego oczy, nie wiemy. Ma swoje lata, pytajcie go, on sam o sobie powie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 22, 'Tak mówili jego rodzice, bo bali się Żydów. Żydzi bowiem już postanowili, że każdy, kto wyzna, iż on jest Chrystusem, będzie wyłączony z synagogi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 23, 'Dlatego jego rodzice powiedzieli: Ma swoje lata, jego pytajcie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 24, 'Wtedy znowu zawołali tego człowieka, który był ślepy i powiedzieli do niego: Oddaj chwałę Bogu. My wiemy, że ten człowiek jest grzeszny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 25, 'A on odpowiedział: Czy jest grzeszny, nie wiem. To tylko wiem, że byłem ślepy, a teraz widzę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 26, 'I zapytali go znowu: Cóż ci uczynił? Jak otworzył twoje oczy?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 27, 'Odpowiedział im: Już wam powiedziałem, a nie słuchaliście. Dlaczego jeszcze chcecie słuchać? Czy i wy chcecie być jego uczniami?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 28, 'Wtedy złorzeczyli mu i powiedzieli: Ty bądź sobie jego uczniem, my zaś jesteśmy uczniami Mojżesza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 29, 'My wiemy, że Bóg mówił do Mojżesza, lecz skąd on jest, nie wiemy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 30, 'Odpowiedział im ten człowiek: To naprawdę rzecz dziwna, że wy nie wiecie, skąd jest, a otworzył moje oczy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 31, 'A wiemy, że Bóg nie wysłuchuje grzeszników, ale jeśli ktoś jest czcicielem Boga i wypełnia jego wolę, tego wysłuchuje.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 32, 'Od wieków nie słyszano, aby ktoś otworzył oczy ślepego od urodzenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 33, 'Gdyby on nie był od Boga, nie mógłby nic uczynić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 34, 'Odpowiedzieli mu: Urodziłeś się cały w grzechach i ty nas uczysz? I wypędzili go precz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 35, 'A gdy Jezus usłyszał, że go wypędzili, znalazł go i zapytał: Czy wierzysz w Syna Bożego?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 36, 'A on odpowiedział: A któż to jest, Panie, abym w niego wierzył?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 37, 'I powiedział do niego Jezus: I widziałeś go, i ten, który mówi z tobą, jest nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 38, 'A on powiedział: Wierzę, Panie! I oddał mu pokłon.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 39, 'Jezus mu powiedział: Przyszedłem na ten świat na sąd, aby ci, którzy nie widzą, widzieli, a ci, którzy widzą, stali się ślepi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 40, 'I usłyszeli to niektórzy z faryzeuszy, którzy z nim byli, i zapytali go: Czy i my jesteśmy ślepi?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 41, 'Jezus im odpowiedział: Gdybyście byli ślepi, nie mielibyście grzechu, lecz teraz mówicie: Widzimy – dlatego wasz grzech pozostaje.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 1, 'Zaprawdę, zaprawdę powiadam wam: Kto nie wchodzi do owczarni drzwiami, ale wchodzi inną drogą, ten jest złodziejem i bandytą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 2, 'Lecz kto wchodzi drzwiami, jest pasterzem owiec.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 3, 'Temu odźwierny otwiera i owce słuchają jego głosu, a on woła swoje własne owce po imieniu i wyprowadza je.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 4, 'A gdy wypuści swoje owce, idzie przed nimi, a owce idą za nim, bo znają jego głos.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 5, 'Ale za obcym nie idą, lecz uciekają od niego, bo nie znają głosu obcych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 6, 'Tę przypowieść powiedział im Jezus, lecz oni nie zrozumieli tego, co im mówił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 7, 'Wtedy Jezus znowu powiedział do nich: Zaprawdę, zaprawdę powiadam wam: Ja jestem drzwiami dla owiec.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 8, 'Wszyscy, ilu ich przede mną przyszło, są złodziejami i bandytami, ale owce ich nie słuchały.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 9, 'Ja jestem drzwiami. Jeśli ktoś wejdzie przeze mnie, będzie zbawiony; wejdzie i wyjdzie, i znajdzie pastwisko.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 10, 'Złodziej przychodzi tylko po to, żeby kraść, zabijać i niszczyć. Ja przyszedłem, aby miały życie i aby miały je w obfitości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 11, 'Ja jestem dobrym pasterzem. Dobry pasterz oddaje swoje życie za owce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 12, 'Lecz najemnik, który nie jest pasterzem, do którego owce nie należą, widząc nadchodzącego wilka, opuszcza owce i ucieka, a wilk porywa i rozprasza owce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 13, 'Najemnik ucieka, bo jest najemnikiem i nie troszczy się o owce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 14, 'Ja jestem dobrym pasterzem i znam moje owce, a moje mnie znają.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 15, 'Jak mnie zna Ojciec, i ja znam Ojca; i oddaję moje życie za owce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 16, 'A mam także inne owce, które nie są z tej owczarni. Również te muszę przyprowadzić i będą słuchać mego głosu, i będzie jedna owczarnia i jeden pasterz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 17, 'Dlatego Ojciec mnie miłuje, bo ja oddaję swoje życie, aby je znowu wziąć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 18, 'Nikt mi go nie odbiera, ale ja oddaję je sam z siebie. Mam moc je oddać i mam moc znowu je wziąć. Ten nakaz otrzymałem od mego Ojca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 19, 'Wtedy znowu nastąpił rozłam wśród Żydów z powodu tych słów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 20, 'I wielu z nich mówiło: Ma demona i szaleje. Czemu go słuchacie?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 21, 'Inni mówili: To nie są słowa człowieka mającego demona. Czy demon może otwierać oczy ślepych?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 22, 'Była wtedy w Jerozolimie uroczystość poświęcenia świątyni. A była zima.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 23, 'I przechadzał się Jezus w świątyni, w przedsionku Salomona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 24, 'Wtedy Żydzi obstąpili go i zapytali: Jak długo będziesz nas trzymał w niepewności? Jeśli ty jesteś Chrystusem, powiedz nam otwarcie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 25, 'Jezus im odpowiedział: Powiedziałem wam, a nie wierzycie. Dzieła, które wykonuję w imieniu mego Ojca, one świadczą o mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 26, 'Ale wy nie wierzycie, bo nie jesteście z moich owiec, jak wam powiedziałem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 27, 'Moje owce słuchają mego głosu i ja je znam, a one idą za mną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 28, 'A ja daję im życie wieczne i nigdy nie zginą ani nikt nie wydrze ich z mojej ręki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 29, 'Mój Ojciec, który mi je dał, większy jest od wszystkich i nikt nie może wydrzeć ich z ręki mego Ojca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 30, 'Ja i Ojciec jedno jesteśmy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 31, 'Wtedy Żydzi znowu porwali kamienie, aby go ukamienować.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 32, 'Jezus powiedział do nich: Ukazałem wam wiele dobrych uczynków od mego Ojca. Za który z tych uczynków mnie kamienujecie?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 33, 'Odpowiedzieli mu Żydzi: Nie kamienujemy cię za dobry uczynek, ale za bluźnierstwo, to znaczy, że ty, będąc człowiekiem, czynisz samego siebie Bogiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 34, 'Jezus im odpowiedział: Czy nie jest napisane w waszym Prawie: Ja powiedziałem: Jesteście bogami?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 35, 'Jeśli nazwał bogami tych, do których doszło słowo Boże, a Pismo nie może być naruszone;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 36, 'To jakże do mnie, którego Ojciec uświęcił i posłał na świat, mówicie: Bluźnisz, bo powiedziałem: Jestem Synem Bożym?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 37, 'Jeśli nie wykonuję dzieł mego Ojca, nie wierzcie mi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 38, 'A jeśli wykonuję, choćbyście mnie nie wierzyli, wierzcie uczynkom, abyście poznali i uwierzyli, że Ojciec jest we mnie, a ja w nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 39, 'Znowu więc usiłowali go schwytać, ale wymknął się im z rąk.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 40, 'I ponownie odszedł za Jordan, na miejsce, gdzie przedtem Jan chrzcił, i tam przebywał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 41, 'A wielu przychodziło do niego i mówiło: Jan wprawdzie nie uczynił żadnego cudu, ale wszystko, co Jan o nim powiedział, było prawdziwe.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 42, 'I wielu tam uwierzyło w niego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 1, 'A był chory pewien człowiek, Łazarz z Betanii, z miasteczka Marii i jej siostry Marty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 2, 'A to była ta Maria, która namaściła Pana maścią i wycierała jego nogi swoimi włosami. Jej to brat, Łazarz, chorował.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 3, 'Siostry więc posłały do niego wiadomość: Panie, oto ten, którego miłujesz, choruje.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 4, 'A gdy Jezus to usłyszał, powiedział: Ta choroba nie jest na śmierć, ale na chwałę Bożą, aby przez nią był uwielbiony Syn Boży.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 5, 'Jezus zaś miłował Martę i jej siostrę, i Łazarza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 6, 'A gdy usłyszał, że choruje, został jeszcze dwa dni w miejscu, w którym przebywał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 7, 'Lecz potem powiedział do swoich uczniów: Chodźmy znowu do Judei.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 8, 'Uczniowie mu powiedzieli: Mistrzu, Żydzi dopiero co usiłowali cię ukamienować, a znowu tam idziesz?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 9, 'Jezus odpowiedział: Czyż dzień nie ma dwunastu godzin? Jeśli ktoś chodzi we dnie, nie potknie się, bo widzi światłość tego świata.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 10, 'A jeśli ktoś chodzi w nocy, potknie się, bo nie ma w nim światłości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 11, 'To powiedział, a potem dodał: Łazarz, nasz przyjaciel, śpi, ale idę, aby obudzić go ze snu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 12, 'Wtedy jego uczniowie powiedzieli: Panie, jeśli śpi, będzie zdrowy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 13, 'Ale Jezus mówił o jego śmierci, lecz oni myśleli, że mówił o zaśnięciu zwykłym snem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 14, 'Wówczas Jezus powiedział im otwarcie: Łazarz umarł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 15, 'I ze względu na was raduję się, że mnie tam nie było, abyście uwierzyli. Ale chodźmy do niego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 16, 'Wtedy Tomasz, zwany Didymos, powiedział do współuczniów: Chodźmy i my, aby z nim umrzeć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 17, 'Kiedy Jezus przyszedł, zastał go już cztery dni leżącego w grobie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 18, 'A Betania była niedaleko Jerozolimy, w odległości około piętnastu stadiów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 19, 'A wielu Żydów przyszło do Marty i Marii, aby je pocieszyć po stracie brata.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 20, 'Gdy Marta usłyszała, że Jezus nadchodzi, wybiegła mu naprzeciw. Ale Maria siedziała w domu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 21, 'I powiedziała Marta do Jezusa: Panie, gdybyś tu był, mój brat by nie umarł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 22, 'Ale i teraz wiem, że Bóg da tobie, o cokolwiek go poprosisz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 23, 'Jezus jej odpowiedział: Twój brat zmartwychwstanie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 24, 'Marta mu powiedziała: Wiem, że zmartwychwstanie przy zmartwychwstaniu w dniu ostatecznym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 25, 'I powiedział do niej Jezus: Ja jestem zmartwychwstaniem i życiem. Kto we mnie wierzy, choćby i umarł, będzie żył.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 26, 'A każdy, kto żyje i wierzy we mnie, nigdy nie umrze. Czy wierzysz w to?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 27, 'Odpowiedziała mu: Tak, Panie. Ja uwierzyłam, że ty jesteś Chrystusem, Synem Bożym, który miał przyjść na świat.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 28, 'A to powiedziawszy, poszła i potajemnie zawołała swoją siostrę Marię, i powiedziała: Jest tu Nauczyciel i woła cię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 29, 'Gdy tylko ona to usłyszała, zaraz wstała i poszła do niego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 30, 'A Jezus jeszcze nie wszedł do miasteczka, lecz był na tym miejscu, gdzie Marta wyszła mu naprzeciw.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 31, 'Wtedy Żydzi, którzy byli z nią w domu i pocieszali ją, widząc, że Maria szybko wstała i wyszła, poszli za nią, mówiąc: Idzie do grobu, aby tam płakać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 32, 'A gdy Maria przyszła tam, gdzie był Jezus, ujrzała go, przypadła mu do nóg i powiedziała: Panie, gdybyś tu był, mój brat by nie umarł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 33, 'Kiedy Jezus zobaczył ją płaczącą i płaczących Żydów, którzy z nią przyszli, rozrzewnił się w duchu i zasmucił się.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 34, 'I zapytał: Gdzie go położyliście? Odpowiedzieli mu: Panie, chodź i zobacz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 35, 'I Jezus zapłakał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 36, 'Wtedy Żydzi powiedzieli: Patrzcie, jak go miłował.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 37, 'A niektórzy z nich mówili: Czyż ten, który otworzył oczy ślepego, nie mógł sprawić, aby on nie umarł?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 38, 'Jezus zaś ponownie się rozrzewnił i przyszedł do grobu. Była to jaskinia, a u jej wejścia był położony kamień.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 39, 'I powiedział Jezus: Usuńcie ten kamień. Powiedziała do niego Marta, siostra zmarłego: Panie, już cuchnie, bo od czterech dni leży w grobie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 40, 'Jezus jej rzekł: Czyż nie powiedziałem ci, że jeśli uwierzysz, ujrzysz chwałę Bożą?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 41, 'Wtedy usunęli kamień z miejsca, gdzie był położony zmarły. Jezus zaś podniósł oczy w górę i powiedział: Ojcze, dziękuję ci, że mnie wysłuchałeś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 42, 'A ja wiedziałem, że mnie zawsze wysłuchujesz, ale powiedziałem to ze względu na stojących wokoło ludzi, aby uwierzyli, że ty mnie posłałeś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 43, 'Gdy to powiedział, zawołał donośnym głosem: Łazarzu, wyjdź na zewnątrz!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 44, 'I wyszedł ten, który umarł, mając ręce i nogi powiązane opaskami, a twarz obwiązaną chustką. Powiedział do nich Jezus: Rozwiążcie go i pozwólcie mu odejść.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 45, 'Wielu więc z Żydów, którzy przyszli do Marii i widzieli to, czego Jezus dokonał, uwierzyło w niego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 46, 'Lecz niektórzy z nich odeszli do faryzeuszy i powiedzieli im, co Jezus uczynił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 47, 'Wtedy naczelni kapłani i faryzeusze zebrali się na naradę i mówili: Co zrobimy? Bo ten człowiek czyni wiele cudów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 48, 'Jeśli go tak zostawimy, wszyscy uwierzą w niego i przyjdą Rzymianie, i zabiorą nam to nasze miejsce i naród.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 49, 'A jeden z nich, Kajfasz, który był tego roku najwyższym kapłanem, powiedział do nich: Wy nic nie wiecie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 50, 'I nie bierzecie pod uwagę, że pożyteczniej jest dla nas, żeby jeden człowiek umarł za lud, a żeby cały ten naród nie zginął.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 51, 'A nie mówił tego sam od siebie, ale będąc tego roku najwyższym kapłanem, prorokował, że Jezus miał umrzeć za ten naród;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 52, 'A nie tylko za ten naród, ale też po to, aby zgromadzić w jedno rozproszone dzieci Boże.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 53, 'Od tego więc dnia naradzali się wspólnie nad tym, aby go zabić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 54, 'A Jezus już nie chodził jawnie wśród Żydów, ale odszedł stamtąd do krainy, która leży w pobliżu pustyni, do miasta zwanego Efraim, i tam mieszkał ze swoimi uczniami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 55, 'A zbliżała się Pascha żydowska. I wielu z tej okolicy szło do Jerozolimy przed Paschą, aby się oczyścić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 56, 'Szukali Jezusa i stojąc w świątyni, mówili jedni do drugich: Czy myślicie, że nie przyjdzie na święto?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 57, 'A naczelni kapłani i faryzeusze wydali nakaz, aby, jeśli ktoś się dowie, gdzie jest, oznajmił to, żeby go mogli schwytać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 1, 'Na sześć dni przed Paschą Jezus przyszedł do Betanii, gdzie był Łazarz, który umarł, a którego wskrzesił z martwych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 2, 'Tam przygotowali mu wieczerzę, a Marta usługiwała. Łazarz zaś był jednym z tych, którzy razem z nim siedzieli przy stole.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 3, 'Wówczas Maria, wziąwszy funt bardzo drogiej maści nardowej, namaściła nogi Jezusa i wytarła je swoimi włosami, a dom napełnił się wonią tej maści.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 4, 'Wtedy jeden z jego uczniów, Judasz Iskariota, syn Szymona, ten, który miał go zdradzić, powiedział:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 5, 'Dlaczego tej maści nie sprzedano za trzysta groszy i nie rozdano ich ubogim?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 6, 'A to mówił nie dlatego, że troszczył się o ubogich, ale ponieważ był złodziejem i miał sakiewkę, a nosił to, co do niej włożono.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 7, 'Wtedy Jezus powiedział: Zostaw ją; zachowała to na dzień mego pogrzebu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 8, 'Ubogich bowiem zawsze macie u siebie, ale mnie nie zawsze będziecie mieć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 9, 'Wtedy wielu Żydów dowiedziało się, że tam jest; i przyszli nie tylko z powodu Jezusa, ale także, by zobaczyć Łazarza, którego wskrzesił z martwych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 10, 'I naradzali się naczelni kapłani nad tym, żeby zabić również Łazarza;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 11, 'Gdyż z jego powodu wielu spośród Żydów odstąpiło i uwierzyło w Jezusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 12, 'Nazajutrz mnóstwo ludzi, którzy przyszli na święto, usłyszawszy, że Jezus idzie do Jerozolimy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 13, 'Nabrało gałązek palmowych, wyszło mu naprzeciw i wołało: Hosanna! Błogosławiony, który przychodzi w imieniu Pana, król Izraela!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 14, 'A Jezus, znalazłszy oślątko, wsiadł na nie, jak jest napisane:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 15, 'Nie bój się, córko Syjonu. Oto twój król przychodzi, siedząc na oślątku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 16, 'Z początku jego uczniowie tego nie zrozumieli, ale gdy Jezus został uwielbiony, wtedy przypomnieli sobie, że to było o nim napisane i że mu tak uczynili.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 17, 'Dawali więc świadectwo ludzie, którzy z nim byli, gdy Łazarza wywołał z grobowca i wskrzesił go z martwych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 18, 'Dlatego też ludzie wyszli mu naprzeciw, bo usłyszeli, że on uczynił ten cud.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 19, 'Wtedy faryzeusze mówili między sobą: Widzicie, że nic nie zdziałacie. Oto świat poszedł za nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 20, 'A wśród tych, którzy przychodzili do Jerozolimy, żeby oddać cześć Bogu w święto, byli pewni Grecy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 21, 'Oni to przyszli do Filipa, który był z Betsaidy w Galilei, i prosili go: Panie, chcemy zobaczyć Jezusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 22, 'Filip przyszedł i powiedział Andrzejowi, a z kolei Andrzej i Filip powiedzieli Jezusowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 23, 'A Jezus im odpowiedział: Nadeszła godzina, aby Syn Człowieczy został uwielbiony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 24, 'Zaprawdę, zaprawdę powiadam wam: Jeśli ziarno pszenicy, wpadłszy w ziemię, nie obumrze, samo zostaje. Jeśli jednak obumrze, wydaje obfity plon.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 25, 'Kto miłuje swoje życie, utraci je, a kto nienawidzi swego życia na tym świecie, zachowa je na życie wieczne.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 26, 'Jeśli ktoś mi służy, niech idzie za mną, a gdzie ja jestem, tam będzie i mój sługa. A jeśli ktoś będzie mi służył, uczci go mój Ojciec.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 27, 'Teraz moja dusza jest zatrwożona. I cóż powiem? Ojcze, zachowaj mnie od tej godziny? Przecież dlatego przyszedłem na tę godzinę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 28, 'Ojcze, uwielbij swoje imię. Wtedy rozległ się głos z nieba: Uwielbiłem i jeszcze uwielbię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 29, 'A ludzie, którzy stali i słyszeli, mówili: Zagrzmiało. A inni mówili: Anioł do niego przemówił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 30, 'Jezus odpowiedział: Ten głos rozległ się nie ze względu na mnie, ale ze względu na was.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 31, 'Teraz odbywa się sąd tego świata, teraz władca tego świata będzie wyrzucony precz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 32, 'A ja, jeśli będę wywyższony nad ziemię, pociągnę wszystkich do siebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 33, 'A mówił to, dając znać, jaką śmiercią miał umrzeć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 34, 'Ludzie mu odpowiedzieli: Dowiedzieliśmy się z prawa, że Chrystus trwa na wieki. Jakże więc ty możesz mówić, że Syn Człowieczy musi być wywyższony? Któż to jest Syn Człowieczy?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 35, 'Wtedy Jezus powiedział im: Jeszcze przez krótki czas jest z wami światłość. Chodźcie więc, dopóki macie światłość, żeby was ciemność nie ogarnęła. Bo kto chodzi w ciemności, nie wie, dokąd idzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 36, 'Dopóki macie światłość, wierzcie w światłość, abyście byli synami światłości. Gdy Jezus to powiedział, odszedł i ukrył się przed nimi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 37, 'A choć tak wiele cudów uczynił wobec nich, jednak nie uwierzyli w niego;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 38, 'Aby się wypełniło słowo, które powiedział prorok Izajasz: Panie, któż uwierzył naszemu głoszeniu? I komu ramię Pańskie zostało objawione?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 39, 'Dlatego nie mogli uwierzyć, bo jeszcze Izajasz powiedział:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 40, 'Zaślepił ich oczy i zatwardził ich serce, aby oczami nie widzieli i sercem nie zrozumieli, aby się nie nawrócili, żebym ich nie uzdrowił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 41, 'To powiedział Izajasz, gdy widział jego chwałę i mówił o nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 42, 'Jednak i z przełożonych wielu uwierzyło w niego, ale z powodu faryzeuszy nie wyznawali go, aby nie wyłączono ich z synagogi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 43, 'Umiłowali bowiem chwałę ludzką bardziej niż chwałę Bożą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 44, 'A Jezus wołał: Kto wierzy we mnie, nie we mnie wierzy, ale w tego, który mnie posłał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 45, 'I kto mnie widzi, widzi tego, który mnie posłał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 46, 'Ja, światłość, przyszedłem na świat, aby każdy, kto wierzy we mnie, nie pozostał w ciemności.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 47, 'A jeśli ktoś słucha moich słów, a nie uwierzy, ja go nie sądzę. Nie przyszedłem bowiem po to, żeby sądzić świat, ale żeby zbawić świat.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 48, 'Kto mną gardzi i nie przyjmuje moich słów, ma kogoś, kto go sądzi: słowo, które ja mówiłem, ono go osądzi w dniu ostatecznym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 49, 'Bo ja nie mówiłem sam od siebie, ale ten, który mnie posłał, Ojciec, on mi dał nakaz, co mam powiedzieć i co mówić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 50, 'I wiem, że jego nakaz jest życiem wiecznym. Dlatego to, co ja wam mówię, mówię tak, jak mi powiedział Ojciec.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 1, 'A przed świętem Paschy Jezus, wiedząc, że nadeszła jego godzina, aby przeszedł z tego świata do Ojca, umiłowawszy swoich, którzy byli na świecie, umiłował ich aż do końca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 2, 'A gdy była wieczerza i diabeł już włożył w serce Judasza, syna Szymona Iskarioty, zamysł, aby go wydać;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 3, 'Jezus, wiedząc, że Ojciec dał wszystko w jego ręce i że od Boga wyszedł, i do Boga idzie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 4, 'Wstał od wieczerzy i złożył szaty, a wziąwszy płócienny ręcznik, przepasał się.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 5, 'Potem nalał wody do miednicy i zaczął myć nogi uczniom, i wycierać ręcznikiem, którym był przepasany.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 6, 'I podszedł do Szymona Piotra, a on powiedział do niego: Panie, ty chcesz mi umyć nogi?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 7, 'Jezus mu odpowiedział: Tego, co ja czynię, ty teraz nie rozumiesz, ale potem zrozumiesz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 8, 'Piotr mu powiedział: Nigdy nie będziesz mył moich nóg. Jezus mu odpowiedział: Jeśli cię nie umyję, nie będziesz miał działu ze mną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 9, 'Wtedy Szymon Piotr powiedział do niego: Panie, nie tylko moje nogi, ale i ręce, i głowę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 10, 'Jezus mu odpowiedział: Kto jest umyty, potrzebuje umyć tylko nogi, bo cały jest czysty. I wy jesteście czyści, lecz nie wszyscy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 11, 'Wiedział bowiem, kto ma go wydać, dlatego powiedział: Nie wszyscy jesteście czyści.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 12, 'Gdy więc umył im nogi i wziął swoje szaty, usiadłszy znowu za stołem, powiedział do nich: Czy rozumiecie, co wam uczyniłem?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 13, 'Wy nazywacie mnie Nauczycielem i Panem i dobrze mówicie, bo nim jestem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 14, 'Jeśli więc ja, Pan i Nauczyciel, umyłem wam nogi i wy powinniście sobie nawzajem myć nogi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 15, 'Dałem wam bowiem przykład, abyście i wy czynili tak, jak ja wam uczyniłem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 16, 'Zaprawdę, zaprawdę powiadam wam: Sługa nie jest większy od swego pana ani posłaniec nie jest większy od tego, który go posłał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 17, 'Jeśli to wiecie, będziecie błogosławieni, gdy tak uczynicie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 18, 'Nie mówię o was wszystkich. Ja wiem, których wybrałem, ale żeby się wypełniło Pismo: Ten, który je ze mną chleb, podniósł przeciwko mnie swoją piętę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 19, 'Teraz wam mówię, zanim to się stanie, abyście, gdy to się stanie, uwierzyli, że ja jestem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 20, 'Zaprawdę, zaprawdę powiadam wam: Kto przyjmuje tego, którego ja poślę, mnie przyjmuje, a kto mnie przyjmuje, przyjmuje tego, który mnie posłał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 21, 'To powiedziawszy, Jezus wzruszył się w duchu i oświadczył: Zaprawdę, zaprawdę powiadam wam, że jeden z was mnie wyda.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 22, 'Wtedy uczniowie spojrzeli po sobie, niepewni, o kim to mówił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 23, 'A jeden z jego uczniów, ten, którego Jezus miłował, położył się na piersi Jezusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 24, 'Skinął więc na niego Szymon Piotr, aby się wypytał, kto jest tym, o którym mówił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 25, 'A on, położywszy się na piersi Jezusa, zapytał go: Panie, kto to jest?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 26, 'Jezus odpowiedział: To ten, któremu podam umoczony kawałek chleba. A umoczywszy kawałek chleba, dał Judaszowi Iskariocie, synowi Szymona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 27, 'A zaraz po tym kawałku chleba wszedł w niego szatan. Wtedy Jezus powiedział do niego: Co masz robić, rób szybko.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 28, 'Żaden jednak z obecnych przy stole nie zrozumiał, dlaczego mu to powiedział.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 29, 'A ponieważ Judasz miał sakiewkę, niektórzy sądzili, że Jezus mu powiedział: Nakup, czego nam potrzeba na święto, albo żeby coś dał ubogim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 30, 'Wtedy on wziął ten kawałek chleba i natychmiast wyszedł. A była noc.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 31, 'A gdy wyszedł, Jezus powiedział: Teraz jest uwielbiony Syn Człowieczy i Bóg jest w nim uwielbiony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 32, 'A jeśli Bóg jest w nim uwielbiony, to go też Bóg uwielbi sam w sobie, i to wkrótce go uwielbi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 33, 'Dzieci, jeszcze krótko jestem z wami. Będziecie mnie szukać, ale jak powiedziałem Żydom: Gdzie ja idę, wy przyjść nie możecie – tak i wam teraz mówię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 34, 'Daję wam nowe przykazanie, abyście się wzajemnie miłowali; tak jak ja was umiłowałem, abyście i wy wzajemnie się miłowali.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 35, 'Po tym wszyscy poznają, że jesteście moimi uczniami, jeśli będziecie się wzajemnie miłować.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 36, 'Zapytał go Szymon Piotr: Panie, dokąd idziesz? Jezus mu odpowiedział: Dokąd ja idę, ty teraz za mną iść nie możesz, ale potem pójdziesz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 37, 'Wtedy Piotr powiedział mu: Panie, czemu teraz nie mogę iść za tobą? Moje życie oddam za ciebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 38, 'Jezus mu odpowiedział: Swoje życie za mnie oddasz? Zaprawdę, zaprawdę powiadam ci: Zanim kogut zapieje, trzy razy się mnie wyprzesz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 1, 'Niech się nie trwoży wasze serce. Wierzycie w Boga, wierzcie i we mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 2, 'W domu mego Ojca jest wiele mieszkań. Gdyby tak nie było, powiedziałbym wam. Idę, aby wam przygotować miejsce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 3, 'A gdy odejdę i przygotuję wam miejsce, przyjdę znowu i wezmę was do siebie, żebyście, gdzie ja jestem, i wy byli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 4, 'A dokąd ja idę, wiecie i drogę znacie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 5, 'Powiedział do niego Tomasz: Panie, nie wiemy, dokąd idziesz, jakże więc możemy znać drogę?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 6, 'Jezus mu odpowiedział: Ja jestem drogą, prawdą i życiem. Nikt nie przychodzi do Ojca jak tylko przeze mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 7, 'Gdybyście mnie znali, znalibyście też mego Ojca. I już teraz go znacie, i widzieliście go.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 8, 'Powiedział do niego Filip: Panie, pokaż nam Ojca, a to nam wystarczy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 9, 'Jezus mu odpowiedział: Tak długo jestem z wami, a nie poznałeś mnie, Filipie? Kto mnie widzi, widzi i mego Ojca. Jak możesz mówić: Pokaż nam Ojca?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 10, 'Nie wierzysz, że ja jestem w Ojcu, a Ojciec we mnie? Słów, które ja do was mówię, nie mówię od samego siebie, lecz Ojciec, który mieszka we mnie, on dokonuje dzieł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 11, 'Wierzcie mi, że ja jestem w Ojcu, a Ojciec we mnie. Przynajmniej z powodu samych dzieł wierzcie mi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 12, 'Zaprawdę, zaprawdę powiadam wam: Kto wierzy we mnie, dzieł, których ja dokonuję, i on będzie dokonywał, i większych od tych dokona, bo ja odchodzę do mego Ojca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 13, 'A o cokolwiek będziecie prosić w moje imię, to uczynię, aby Ojciec był uwielbiony w Synu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 14, 'Jeśli o coś będziecie prosić w moje imię, ja to uczynię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 15, 'Jeśli mnie miłujecie, zachowujcie moje przykazania.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 16, 'A ja będę prosił Ojca i da wam innego Pocieszyciela, aby z wami był na wieki;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 17, 'Ducha prawdy, którego świat nie może przyjąć, bo go nie widzi ani go nie zna. Wy jednak go znacie, gdyż z wami przebywa i w was będzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 18, 'Nie zostawię was sierotami, przyjdę do was.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 19, 'Jeszcze krótki czas, a świat nie będzie mnie już więcej oglądał, lecz wy będziecie mnie oglądać. Ponieważ ja żyję, wy też będziecie żyć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 20, 'W tym dniu poznacie, że ja jestem w moim Ojcu, a wy we mnie i ja w was.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 21, 'Kto ma moje przykazania i zachowuje je, ten mnie miłuje. A kto mnie miłuje, będzie go też miłował mój Ojciec i ja go będę miłował, i objawię mu samego siebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 22, 'Powiedział mu Judasz, ale nie Iskariota: Panie, cóż to jest, że masz się objawić nam, a nie światu?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 23, 'Jezus mu odpowiedział: Jeśli ktoś mnie miłuje, będzie zachowywał moje słowo. I mój Ojciec go umiłuje, i przyjdziemy do niego, i u niego zamieszkamy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 24, 'Kto mnie nie miłuje, nie zachowuje moich słów. A słowo, które słyszycie, nie jest moje, ale tego, który mnie posłał, Ojca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 25, 'To wam powiedziałem, przebywając z wami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 26, 'Lecz Pocieszyciel, Duch Święty, którego Ojciec pośle w moim imieniu, on nauczy was wszystkiego i przypomni wam wszystko, co wam powiedziałem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 27, 'Pokój zostawiam wam, mój pokój daję wam; daję wam nie tak, jak daje świat. Niech się nie trwoży wasze serce ani się nie lęka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 28, 'Słyszeliście, że wam powiedziałem: Odchodzę i znowu przyjdę do was. Gdybyście mnie miłowali, radowalibyście się, ponieważ powiedziałem: Idę do Ojca. Mój Ojciec bowiem jest większy niż ja.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 29, 'I teraz wam powiedziałem, zanim to się stanie, żebyście uwierzyli, gdy to się stanie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 30, 'Już nie będę z wami wiele mówił, nadchodzi bowiem władca tego świata, a on we mnie nic nie ma.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 31, 'Ale żeby świat poznał, że miłuję Ojca i jak Ojciec mi nakazał, tak czynię. Wstańcie, chodźmy stąd.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 1, 'Ja jestem prawdziwą winoroślą, a mój Ojciec jest winogrodnikiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 2, 'Każdą latorośl, która we mnie nie wydaje owocu, odcina, a każdą, która wydaje owoc, oczyszcza, aby wydawała obfitszy owoc.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 3, 'Wy już jesteście czyści z powodu słów, które do was mówiłem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 4, 'Trwajcie we mnie, a ja w was. Jak latorośl nie może wydawać owocu sama z siebie, jeśli nie będzie trwała w winorośli, tak i wy, jeśli nie będziecie trwać we mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 5, 'Ja jestem winoroślą, a wy jesteście latoroślami. Kto trwa we mnie, a ja w nim, ten wydaje obfity owoc, bo beze mnie nic nie możecie zrobić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 6, 'Jeśli ktoś nie trwa we mnie, zostanie wyrzucony precz jak latorośl i uschnie. Takie się zbiera i wrzuca do ognia, i płoną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 7, 'Jeśli będziecie trwać we mnie i moje słowa będą trwać w was, proście, o cokolwiek chcecie, a spełni się wam.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 8, 'W tym będzie uwielbiony mój Ojciec, że wydacie obfity owoc; i będziecie moimi uczniami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 9, 'Jak mnie umiłował Ojciec, tak i ja was umiłowałem. Trwajcie w mojej miłości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 10, 'Jeśli zachowacie moje przykazania, będziecie trwać w mojej miłości, jak i ja zachowałem przykazania mego Ojca i trwam w jego miłości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 11, 'To wam powiedziałem, aby moja radość trwała w was i aby wasza radość była pełna.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 12, 'To jest moje przykazanie, abyście się wzajemnie miłowali, jak i ja was umiłowałem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 13, 'Nikt nie ma większej miłości od tej, gdy ktoś oddaje swoje życie za swoich przyjaciół.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 14, 'Wy jesteście moimi przyjaciółmi, jeśli robicie to, co wam przykazuję.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 15, 'Już więcej nie będę nazywał was sługami, bo sługa nie wie, co robi jego pan. Lecz nazwałem was przyjaciółmi, bo oznajmiłem wam wszystko, co słyszałem od mego Ojca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 16, 'Nie wy mnie wybraliście, ale ja was wybrałem i przeznaczyłem, abyście wyszli i wydali owoc, i aby wasz owoc trwał, i aby Ojciec dał wam to, o cokolwiek poprosicie go w moje imię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 17, 'To wam przykazuję, abyście się wzajemnie miłowali.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 18, 'Jeśli świat was nienawidzi, wiedzcie, że znienawidził mnie wcześniej niż was.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 19, 'Gdybyście byli ze świata, świat miłowałby to, co jest jego. Ponieważ jednak nie jesteście ze świata, ale ja was wybrałem ze świata, dlatego świat was nienawidzi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 20, 'Przypomnijcie sobie słowo, które wam powiedziałem: Sługa nie jest większy od swego pana. Jeśli mnie prześladowali, to i was będą prześladować. Jeśli moje słowa zachowywali, to i wasze będą zachowywać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 21, 'Ale będą wam to wszystko czynić z powodu mego imienia, bo nie znają tego, który mnie posłał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 22, 'Gdybym nie przyszedł i nie mówił im, nie mieliby grzechu. Teraz jednak nie mają wytłumaczenia dla swego grzechu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 23, 'Kto mnie nienawidzi, nienawidzi też mego Ojca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 24, 'Gdybym nie spełniał wśród nich tych uczynków, których nikt inny nie spełniał, nie mieliby grzechu. Teraz jednak widzieli i nienawidzili i mnie, i mego Ojca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 25, 'Ale to się stało, żeby się wypełniło słowo, które jest napisane w ich Prawie: Nienawidzili mnie bez powodu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 26, 'Gdy jednak przyjdzie Pocieszyciel, którego ja wam poślę od Ojca, Duch prawdy, który wychodzi od Ojca, on będzie świadczył o mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 27, 'Ale i wy będziecie świadczyć, bo jesteście ze mną od początku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 1, 'To wam powiedziałem, abyście się nie gorszyli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 2, 'Będą was wyłączać z synagog; owszem, nadchodzi godzina, że każdy, kto was zabije, będzie sądził, że pełni służbę dla Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 3, 'A uczynią wam tak, bo nie poznali Ojca ani mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 4, 'Ale powiedziałem wam to, abyście, gdy nadejdzie ta godzina, przypomnieli sobie, że ja wam to powiedziałem. A nie mówiłem wam tego na początku, bo byłem z wami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 5, 'Lecz teraz idę do tego, który mnie posłał, a żaden z was nie pyta mnie: Dokąd idziesz?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 6, 'Ale ponieważ wam to powiedziałem, smutek napełnił wasze serce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 7, 'Lecz ja mówię wam prawdę: Pożyteczniej jest dla was, abym odszedł. Jeśli bowiem nie odejdę, Pocieszyciel do was nie przyjdzie, a jeśli odejdę, poślę go do was.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 8, 'A gdy on przyjdzie, będzie przekonywał świat o grzechu, o sprawiedliwości i o sądzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 9, 'O grzechu, mówię, bo nie uwierzyli we mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 10, 'O sprawiedliwości, bo idę do mego Ojca i już więcej mnie nie zobaczycie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 11, 'A o sądzie, bo władca tego świata już jest osądzony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 12, 'Mam wam jeszcze wiele do powiedzenia, ale teraz nie możecie tego znieść.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 13, 'Lecz gdy przyjdzie on, Duch prawdy, wprowadzi was we wszelką prawdę. Nie będzie bowiem mówił sam od siebie, ale będzie mówił to, co usłyszy, i oznajmi wam przyszłe rzeczy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 14, 'On mnie uwielbi, bo weźmie z mojego i wam oznajmi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 15, 'Wszystko, co ma Ojciec, jest moje. Dlatego powiedziałem, że weźmie z mojego i wam oznajmi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 16, 'Jeszcze krótki czas, a nie zobaczycie mnie, i znowu krótki czas, a zobaczycie mnie, bo ja idę do Ojca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 17, 'Wtedy niektórzy z jego uczniów mówili między sobą: Cóż znaczy to, co nam mówi: Jeszcze krótki czas, a nie zobaczycie mnie, i znowu krótki czas, a zobaczycie mnie? oraz: Ja idę do Ojca?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 18, 'Dlatego mówili: Cóż znaczy to, co mówi: Krótki czas? Nie rozumiemy, co mówi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 19, 'Wówczas Jezus poznał, że chcieli go pytać i powiedział do nich: Pytacie się między sobą o to, co powiedziałem: Jeszcze krótki czas, a nie zobaczycie mnie, i znowu krótki czas, a zobaczycie mnie?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 20, 'Zaprawdę, zaprawdę powiadam wam: Wy będziecie płakać i zawodzić, a świat będzie się radował. Będziecie smutni, ale wasz smutek zamieni się w radość.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 21, 'Kobieta, gdy rodzi, smuci się, bo nadeszła jej godzina. Gdy jednak urodzi dziecko, już nie pamięta cierpienia z powodu radości, że człowiek przyszedł na świat.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 22, 'I wy teraz się smucicie, ale znowu was zobaczę i wasze serce będzie się radowało, a nikt nie odbierze wam waszej radości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 23, 'A tego dnia nie będziecie mnie o nic pytać. Zaprawdę, zaprawdę powiadam wam: O cokolwiek poprosicie Ojca w moje imię, da wam.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 24, 'Dotąd o nic nie prosiliście w moje imię. Proście, a otrzymacie, aby wasza radość była pełna.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 25, 'Mówiłem wam o tym w przypowieściach. Ale nadchodzi godzina, gdy już więcej nie będę mówił wam w przypowieściach, ale otwarcie oznajmię wam o moim Ojcu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 26, 'W tym dniu będziecie prosić w moje imię. Nie mówię wam, że ja będę prosił Ojca za wami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 27, 'Sam bowiem Ojciec was miłuje, bo wy mnie umiłowaliście i uwierzyliście, że ja wyszedłem od Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 28, 'Wyszedłem od Ojca i przyszedłem na świat. Znowu opuszczam świat i idę do Ojca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 29, 'Jego uczniowie mu powiedzieli: Oto teraz mówisz otwarcie i nie opowiadasz żadnej przypowieści.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 30, 'Teraz wiemy, że wszystko wiesz i nie potrzebujesz, aby cię ktoś pytał. Dlatego wierzymy, że wyszedłeś od Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 31, 'Jezus im odpowiedział: Teraz wierzycie?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 32, 'Oto nadchodzi godzina, a nawet już nadeszła, że rozproszycie się każdy w swoją stronę, a mnie zostawicie samego. Ale nie jestem sam, bo Ojciec jest ze mną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 33, 'To wam powiedziałem, abyście mieli pokój we mnie. Na świecie będziecie mieć ucisk, ale ufajcie, ja zwyciężyłem świat.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 1, 'To powiedziawszy, Jezus podniósł swoje oczy ku niebu i rzekł: Ojcze, nadeszła godzina. Uwielbij swego Syna, aby też twój Syn uwielbił ciebie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 2, 'Jak mu dałeś władzę nad wszelkim ciałem, aby dał życie wieczne tym wszystkim, których mu dałeś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 3, 'A to jest życie wieczne, aby poznali ciebie, jedynego prawdziwego Boga i tego, którego posłałeś, Jezusa Chrystusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 4, 'Ja uwielbiłem ciebie na ziemi i dokończyłem dzieła, które mi dałeś do wykonania.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 5, 'A teraz ty, Ojcze, uwielbij mnie u siebie tą chwałą, którą miałem u ciebie, zanim powstał świat.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 6, 'Objawiłem twoje imię ludziom, których mi dałeś ze świata. Twoimi byli i dałeś mi ich, a oni zachowali twoje słowa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 7, 'A teraz poznali, że wszystko, co mi dałeś, pochodzi od ciebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 8, 'Dałem im bowiem słowa, które mi dałeś, a oni je przyjęli i prawdziwie poznali, że wyszedłem od ciebie, i uwierzyli, że ty mnie posłałeś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 9, 'Ja proszę za nimi. Nie proszę za światem, ale za tymi, których mi dałeś, bo są twoi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 10, 'I wszystko moje jest twoje, a twoje jest moje i jestem uwielbiony w nich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 11, 'A nie jestem już na świecie, ale oni są na świecie, a ja idę do ciebie. Ojcze święty, zachowaj w twoim imieniu tych, których mi dałeś, aby byli jedno jak i my.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 12, 'Gdy byłem z nimi na świecie, ja zachowywałem ich w twoim imieniu. Strzegłem tych, których mi dałeś, i żaden z nich nie zginął prócz syna zatracenia, żeby się wypełniło Pismo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 13, 'Ale teraz idę do ciebie i mówię to na świecie, aby mieli w sobie moją radość w pełni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 14, 'Ja dałem im twoje słowo, a świat ich znienawidził, bo nie są ze świata, jak i ja nie jestem ze świata.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 15, 'Nie proszę, abyś zabrał ich ze świata, ale abyś zachował ich od złego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 16, 'Nie są ze świata, jak i ja nie jestem ze świata.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 17, 'Uświęć ich w twojej prawdzie. Twoje słowo jest prawdą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 18, 'Jak ty posłałeś mnie na świat, tak i ja posłałem ich na świat.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 19, 'A ja za nich uświęcam samego siebie, aby i oni byli uświęceni w prawdzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 20, 'A nie tylko za nimi proszę, lecz i za tymi, którzy przez ich słowo uwierzą we mnie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 21, 'Aby wszyscy byli jedno, jak ty, Ojcze, we mnie, a ja w tobie, aby i oni byli w nas jedno, aby świat uwierzył, że ty mnie posłałeś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 22, 'I dałem im tę chwałę, którą mi dałeś, aby byli jedno, jak my jesteśmy jedno.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 23, 'Ja w nich, a ty we mnie, aby byli doskonali w jedno, żeby świat poznał, że ty mnie posłałeś i że umiłowałeś ich, jak i mnie umiłowałeś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 24, 'Ojcze, chcę, aby ci, których mi dałeś, byli ze mną tam, gdzie ja jestem, aby oglądali moją chwałę, którą mi dałeś, ponieważ umiłowałeś mnie przed założeniem świata.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 25, 'Ojcze sprawiedliwy, świat ciebie nie poznał, ale ja cię poznałem i oni poznali, że ty mnie posłałeś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 26, 'Objawiłem im twoje imię i jeszcze objawię, aby miłość, którą mnie umiłowałeś, była w nich i ja w nich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 1, 'To powiedziawszy, Jezus wyszedł ze swoimi uczniami za potok Cedron, gdzie był ogród, do którego wszedł on i jego uczniowie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 2, 'A Judasz, który go zdradził, znał to miejsce, bo Jezus często się tam zbierał ze swoimi uczniami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 3, 'Judasz więc, wziąwszy oddział żołnierzy i strażników od naczelnych kapłanów i faryzeuszy, przyszedł tam z latarniami, pochodniami i bronią.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 4, 'Wtedy Jezus, wiedząc o wszystkim, co miało na niego przyjść, wyszedł im naprzeciw i zapytał: Kogo szukacie?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 5, 'Odpowiedzieli mu: Jezusa z Nazaretu. Jezus powiedział do nich: Ja jestem. A stał z nimi i Judasz, który go zdradził.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 6, 'Gdy tylko im powiedział: Ja jestem, cofnęli się i padli na ziemię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 7, 'Wtedy ich znowu spytał: Kogo szukacie? A oni odpowiedzieli: Jezusa z Nazaretu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 8, 'Jezus odpowiedział: Powiedziałem wam, że ja jestem. Jeśli więc mnie szukacie, pozwólcie tym odejść.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 9, 'Stało się tak, aby się wypełniły słowa, które powiedział: Nie straciłem żadnego z tych, których mi dałeś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 10, 'Wówczas Szymon Piotr, mając miecz, dobył go, uderzył sługę najwyższego kapłana i odciął mu prawe ucho. A temu słudze było na imię Malchos.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 11, 'I powiedział Jezus do Piotra: Włóż swój miecz do pochwy. Czy nie mam pić kielicha, który mi dał Ojciec?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 12, 'Wtedy oddział żołnierzy i dowódca oraz strażnicy żydowscy schwytali Jezusa, związali go;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 13, 'I zaprowadzili go najpierw do Annasza, bo był teściem Kajfasza, który tego roku był najwyższym kapłanem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 14, 'To Kajfasz był tym, który doradził Żydom, że pożyteczniej jest, aby jeden człowiek umarł za lud.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 15, 'A szedł za Jezusem Szymon Piotr i inny uczeń. Ten uczeń zaś był znany najwyższemu kapłanowi i wszedł z Jezusem na dziedziniec najwyższego kapłana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 16, 'Ale Piotr stał na zewnątrz u drzwi. Wtedy wyszedł ten drugi uczeń, który był znany najwyższemu kapłanowi, pomówił z odźwierną i wprowadził Piotra.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 17, 'Wówczas dziewczyna odźwierna zapytała Piotra: Czy i ty nie jesteś jednym z uczniów tego człowieka? On odpowiedział: Nie jestem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 18, 'A ponieważ było zimno, strażnicy i słudzy, rozpaliwszy ogień, stali i grzali się. Stał też z nimi Piotr i grzał się.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 19, 'Tymczasem najwyższy kapłan pytał Jezusa o jego uczniów i o jego naukę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 20, 'Jezus mu odpowiedział: Ja jawnie mówiłem światu. Zawsze nauczałem w synagodze i w świątyni, gdzie zewsząd schodzą się Żydzi, a potajemnie nic nie mówiłem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 21, 'Dlaczego mnie pytasz? Zapytaj tych, którzy słyszeli to, co im mówiłem. Oto oni wiedzą, co mówiłem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 22, 'A gdy on to powiedział, jeden ze sług, który tam stał, wymierzył policzek Jezusowi, mówiąc: Tak odpowiadasz najwyższemu kapłanowi?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 23, 'Jezus mu odpowiedział: Jeśli źle powiedziałem, daj świadectwo o złu, a jeśli dobrze, dlaczego mnie bijesz?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 24, 'Bo Annasz odesłał go związanego do Kajfasza, najwyższego kapłana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 25, 'A Szymon Piotr stał i grzał się. I zapytali go: Czy i ty nie jesteś jednym z jego uczniów? A on się wyparł, mówiąc: Nie jestem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 26, 'Zapytał go jeden ze sług najwyższego kapłana, krewny tego, któremu Piotr odciął ucho: Czyż nie ciebie widziałem z nim w ogrodzie?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 27, 'Wtedy Piotr znowu się wyparł. I zaraz zapiał kogut.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 28, 'Od Kajfasza więc zaprowadzili Jezusa do ratusza; a było rano. Sami jednak nie weszli do ratusza, aby się nie skalać, lecz żeby mogli spożyć Paschę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 29, 'Wówczas Piłat wyszedł do nich i zapytał: Jaką skargę wnosicie przeciwko temu człowiekowi?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 30, 'Odpowiedzieli mu: Gdyby on nie był złoczyńcą, nie wydalibyśmy go tobie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 31, 'I powiedział Piłat: Wy go weźcie i osądźcie według waszego prawa. Żydzi mu odpowiedzieli: Nam nie wolno nikogo zabijać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 32, 'Stało się tak, aby się wypełniły słowa, które powiedział Jezus, dając znać, jaką śmiercią miał umrzeć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 33, 'Wtedy Piłat znowu wszedł do ratusza, wezwał Jezusa i zapytał go: Czy ty jesteś królem Żydów?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 34, 'Jezus mu odpowiedział: Czy mówisz to sam od siebie, czy inni powiedzieli ci o mnie?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 35, 'Piłat odpowiedział: Czy ja jestem Żydem? Twój naród i naczelni kapłani wydali mi ciebie. Cóż więc uczyniłeś?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 36, 'Jezus odpowiedział: Moje królestwo nie jest z tego świata. Gdyby moje królestwo było z tego świata, to moi słudzy walczyliby, abym nie został wydany Żydom. Teraz jednak moje królestwo nie jest stąd.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 37, 'Wtedy Piłat zapytał go: A więc jesteś królem? Jezus mu odpowiedział: Ty mówisz, że jestem królem. Ja po to się narodziłem i po to przyszedłem na świat, aby dać świadectwo prawdzie. Każdy, kto jest z prawdy, słucha mego głosu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 38, 'Piłat powiedział do niego: Cóż to jest prawda? A to powiedziawszy, wyszedł znowu do Żydów i powiedział do nich: Ja nie znajduję w nim żadnej winy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 39, 'A u was jest zwyczaj, że na Paschę wypuszczam wam jednego więźnia. Chcecie więc, abym wam wypuścił króla Żydów?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 40, 'Wówczas wszyscy znowu zawołali: Nie tego, ale Barabasza! A Barabasz był bandytą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 1, 'Wtedy Piłat wziął Jezusa i ubiczował go.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 2, 'A żołnierze upletli koronę z cierni, włożyli mu ją na głowę i ubrali go w purpurowy płaszcz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 3, 'I mówili: Witaj, królu Żydów! I policzkowali go.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 4, 'Piłat znowu wyszedł na zewnątrz i powiedział do nich: Oto wyprowadzam go do was na zewnątrz, abyście wiedzieli, że nie znajduję w nim żadnej winy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 5, 'Wtedy Jezus wyszedł na zewnątrz w cierniowej koronie i w purpurowym płaszczu. I powiedział do nich Piłat: Oto człowiek!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 6, 'A gdy naczelni kapłani i ich słudzy zobaczyli go, zawołali: Ukrzyżuj, ukrzyżuj go! Piłat powiedział do nich: Wy go weźcie i ukrzyżujcie, bo ja nie znajduję w nim żadnej winy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 7, 'Żydzi mu odpowiedzieli: My mamy prawo i według naszego prawa powinien umrzeć, bo czynił siebie Synem Bożym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 8, 'A gdy Piłat usłyszał te słowa, jeszcze bardziej się zląkł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 9, 'I wszedł znowu do ratusza, i zapytał Jezusa: Skąd ty jesteś? Lecz Jezus nie dał mu odpowiedzi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 10, 'Wtedy Piłat powiedział do niego: Nie chcesz ze mną rozmawiać? Nie wiesz, że mam władzę ukrzyżować cię i mam władzę cię wypuścić?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 11, 'Jezus odpowiedział: Nie miałbyś żadnej władzy nade mną, gdyby ci jej nie dano z góry. Dlatego ten, który mnie tobie wydał, ma większy grzech.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 12, 'Odtąd Piłat starał się go wypuścić. Żydzi jednak wołali: Jeśli go wypuścisz, nie jesteś przyjacielem cesarza. Każdy, kto się czyni królem, sprzeciwia się cesarzowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 13, 'Gdy więc Piłat usłyszał te słowa, wyprowadził Jezusa na zewnątrz i usiadł na krześle sędziowskim, na miejscu zwanym Litostrotos, a po hebrajsku Gabbata.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 14, 'A był to dzień przygotowania Paschy, około godziny szóstej. I powiedział Piłat do Żydów: Oto wasz król!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 15, 'Lecz oni zawołali: Strać, strać! Ukrzyżuj go! Piłat ich zapytał: Waszego króla mam ukrzyżować? Naczelni kapłani odpowiedzieli: Nie mamy króla poza cesarzem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 16, 'Wtedy im go wydał, żeby go ukrzyżowano. Wzięli więc Jezusa i wyprowadzili go.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 17, 'A on, niosąc swój krzyż, wyszedł na miejsce zwane Miejscem Czaszki, a po hebrajsku Golgotą;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 18, 'Gdzie go ukrzyżowali, a z nim dwóch innych z obu stron, pośrodku zaś Jezusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 19, 'Sporządził też Piłat napis i umieścił na krzyżu. A było napisane: Jezus z Nazaretu, król Żydów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 20, 'Napis ten czytało wielu Żydów, bo miejsce, gdzie ukrzyżowano Jezusa, było blisko miasta. A było to napisane po hebrajsku, po grecku i po łacinie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 21, 'Wtedy naczelni kapłani żydowscy powiedzieli do Piłata: Nie pisz: Król Żydów, ale że on mówił: Jestem królem Żydów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 22, 'Piłat odpowiedział: Co napisałem, to napisałem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 23, 'A gdy żołnierze ukrzyżowali Jezusa, wzięli jego szaty i podzielili na cztery części, każdemu żołnierzowi część. Wzięli też tunikę, a tunika ta nie była szyta, ale od góry cała tkana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 24, 'Mówili więc między sobą: Nie rozcinajmy jej, ale rzućmy losy o to, do kogo ma należeć; aby się wypełniło Pismo, które mówi: Podzielili między siebie moje szaty, a o moje ubranie rzucali losy. To właśnie zrobili żołnierze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 25, 'A przy krzyżu Jezusa stały jego matka i siostra jego matki, Maria, żona Kleofasa, i Maria Magdalena.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 26, 'Gdy więc Jezus zobaczył matkę i ucznia, którego miłował, stojącego obok, powiedział do swojej matki: Kobieto, oto twój syn.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 27, 'Potem powiedział do ucznia: Oto twoja matka. I od tej godziny uczeń ten wziął ją do siebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 28, 'Potem Jezus, widząc, że już wszystko się wykonało, aby się wypełniło Pismo, powiedział: Pragnę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 29, 'A stało tam naczynie pełne octu. Nasączono więc gąbkę octem, nałożono ją na hizop i podano mu do ust.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 30, 'A gdy Jezus skosztował octu, powiedział: Wykonało się. I schyliwszy głowę, oddał ducha.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 31, 'Wtedy Żydzi, aby ciała nie zostały na krzyżu na szabat, ponieważ był dzień przygotowania (bo ten dzień szabatu był wielkim dniem), prosili Piłata, aby połamano im golenie i zdjęto ich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 32, 'Przyszli więc żołnierze i połamali golenie pierwszemu i drugiemu, który z nim był ukrzyżowany.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 33, 'Ale gdy przyszli do Jezusa i zobaczyli, że już umarł, nie łamali mu goleni;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 34, 'Lecz jeden z żołnierzy przebił włócznią jego bok i natychmiast wypłynęła krew i woda.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 35, 'A ten, który to widział, świadczył o tym, a jego świadectwo jest prawdziwe i on wie, że mówi prawdę, abyście wy wierzyli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 36, 'Stało się to bowiem, aby się wypełniło Pismo: Żadna jego kość nie będzie złamana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 37, 'I znowu w innym miejscu Pismo mówi: Ujrzą tego, którego przebili.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 38, 'A potem Józef z Arymatei, który z obawy przed Żydami był potajemnie uczniem Jezusa, prosił Piłata, aby mógł zdjąć ciało Jezusa. A Piłat zezwolił. Poszedł więc i zdjął ciało Jezusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 39, 'Przyszedł też Nikodem, który przedtem przyszedł w nocy do Jezusa, niosąc około stu funtów mieszaniny mirry i aloesu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 40, 'Wzięli więc ciało Jezusa i owinęli je w płótna z tymi wonnościami, zgodnie z żydowskim zwyczajem grzebania zmarłych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 41, 'A na miejscu, gdzie był ukrzyżowany, był ogród, a w ogrodzie nowy grobowiec, w którym jeszcze nikt nie był złożony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 42, 'Tam więc położyli Jezusa z powodu żydowskiego dnia przygotowania, bo grób był blisko.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 1, 'A pierwszego dnia po szabacie, rano, gdy jeszcze było ciemno, Maria Magdalena przyszła do grobu i zobaczyła kamień odwalony od grobowca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 2, 'Wtedy pobiegła i przyszła do Szymona Piotra i do drugiego ucznia, którego Jezus miłował, i powiedziała do nich: Zabrali Pana z grobu i nie wiemy, gdzie go położyli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 3, 'Wyszedł więc Piotr i ten drugi uczeń i poszli do grobu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 4, 'I biegli obaj razem, ale ten drugi uczeń wyprzedził Piotra i pierwszy przybył do grobu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 5, 'Kiedy się nachylił, zobaczył leżące płótna, jednak tam nie wszedł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 6, 'Przyszedł też Szymon Piotr, idąc za nim. Wszedł do grobowca i zobaczył leżące płótna;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 7, 'I chustę, która była na jego głowie, położoną nie z płótnami, ale zwiniętą osobno na jednym miejscu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 8, 'Potem wszedł także ten drugi uczeń, który pierwszy przybył do grobu, zobaczył i uwierzył.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 9, 'Jeszcze bowiem nie rozumieli Pisma, że miał zmartwychwstać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 10, 'Wtedy uczniowie powrócili do domu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 11, 'Ale Maria stała na zewnątrz przed grobem, płacząc. A gdy płakała, nachyliła się do grobowca;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 12, 'I ujrzała dwóch aniołów w bieli, którzy siedzieli tam, gdzie było złożone ciało Jezusa, jeden u głowy, a drugi u nóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 13, 'I zapytali ją: Kobieto, czemu płaczesz? Odpowiedziała im: Bo zabrali mego Pana i nie wiem, gdzie go położyli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 14, 'A to powiedziawszy, odwróciła się i ujrzała stojącego Jezusa, lecz nie wiedziała, że to Jezus.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 15, 'Jezus ją zapytał: Kobieto, czemu płaczesz? Kogo szukasz? A ona, sądząc, że to ogrodnik, odpowiedziała mu: Panie, jeśli ty go wziąłeś, powiedz mi, gdzie go położyłeś, a ja go zabiorę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 16, 'Jezus powiedział do niej: Mario! A ona, obróciwszy się, powiedziała do niego: Rabbuni! – co się tłumaczy: Nauczycielu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 17, 'Jezus do niej powiedział: Nie dotykaj mnie, bo jeszcze nie wstąpiłem do mego Ojca. Ale idź do moich braci i powiedz im: Wstępuję do mego Ojca i waszego Ojca, i do mego Boga, i waszego Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 18, 'Przyszła więc Maria Magdalena, oznajmiając uczniom, że widziała Pana i że jej to powiedział.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 19, 'A gdy był wieczór tego pierwszego dnia po szabacie, a drzwi były zamknięte tam, gdzie zgromadzili się uczniowie z obawy przed Żydami, przyszedł Jezus, stanął pośrodku i powiedział do nich: Pokój wam.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 20, 'A to powiedziawszy, pokazał im swoje ręce i bok. I uradowali się uczniowie, ujrzawszy Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 21, 'Jezus znowu powiedział do nich: Pokój wam. Jak Ojciec mnie posłał, tak i ja was posyłam.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 22, 'A to powiedziawszy, tchnął na nich i powiedział: Weźcie Ducha Świętego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 23, 'Komukolwiek przebaczycie grzechy, są im przebaczone, a komukolwiek zatrzymacie, są im zatrzymane.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 24, 'A Tomasz, jeden z dwunastu, zwany Didymos, nie był z nimi, gdy przyszedł Jezus.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 25, 'I powiedzieli mu inni uczniowie: Widzieliśmy Pana. Lecz on powiedział do nich: Jeśli nie zobaczę na jego rękach śladów gwoździ i nie włożę mego palca w ślady gwoździ, i nie włożę mojej ręki w jego bok, nie uwierzę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 26, 'A po ośmiu dniach jego uczniowie znowu byli w domu, a Tomasz z nimi. I przyszedł Jezus, gdy drzwi były zamknięte, stanął pośrodku i powiedział: Pokój wam.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 27, 'Potem powiedział do Tomasza: Włóż tu swój palec i obejrzyj moje ręce, wyciągnij swoją rękę i włóż ją w mój bok, a nie bądź bez wiary, ale wierz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 28, 'Wtedy Tomasz mu odpowiedział: Mój Pan i mój Bóg!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 29, 'Jezus mu powiedział: Tomaszu, uwierzyłeś, ponieważ mnie ujrzałeś. Błogosławieni, którzy nie widzieli, a uwierzyli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 30, 'I wiele innych cudów uczynił Jezus na oczach swoich uczniów, które nie są napisane w tej księdze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 31, 'Lecz te są napisane, abyście wierzyli, że Jezus jest Chrystusem, Synem Bożym, i abyście wierząc, mieli życie w jego imieniu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 1, 'Potem Jezus znowu ukazał się uczniom nad Morzem Tyberiadzkim. A ukazał się tak:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 2, 'Byli razem Szymon Piotr, Tomasz, zwany Didymos, Natanael, który był z Kany Galilejskiej, synowie Zebedeusza i dwaj inni z jego uczniów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 3, 'Szymon Piotr powiedział do nich: Pójdę łowić ryby. Odpowiedzieli mu: Pójdziemy i my z tobą. Poszli więc i zaraz wsiedli do łodzi, ale tej nocy nic nie złowili.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 4, 'A gdy już nastał ranek, Jezus stanął na brzegu. Uczniowie jednak nie wiedzieli, że to Jezus.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 5, 'Wtedy Jezus zapytał ich: Dzieci, czy macie co jeść? Odpowiedzieli mu: Nie mamy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 6, 'A on powiedział do nich: Zarzućcie sieć po prawej stronie łodzi, a znajdziecie. Zarzucili więc i nie mogli jej wyciągnąć z powodu mnóstwa ryb.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 7, 'Wówczas ten uczeń, którego Jezus miłował, powiedział do Piotra: To Pan. A Szymon Piotr, usłyszawszy, że to Pan, przepasał się koszulą (bo był nagi) i rzucił się w morze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 8, 'Pozostali uczniowie przypłynęli łodzią (bo byli niedaleko od brzegu, około dwustu łokci), ciągnąc sieć z rybami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 9, 'A gdy wyszli na brzeg, zobaczyli żarzące się węgle i leżącą na nich rybę oraz chleb.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 10, 'Jezus do nich powiedział: Przynieście z tych ryb, które teraz złowiliście.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 11, 'Poszedł więc Szymon Piotr i wyciągnął na ziemię sieć pełną wielkich ryb, których było sto pięćdziesiąt trzy, a choć było ich tak wiele, sieć się nie rozdarła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 12, 'Jezus im powiedział: Chodźcie, jedzcie. I żaden z uczniów nie śmiał go pytać: Kim jesteś? Wiedzieli bowiem, że to Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 13, 'Wtedy Jezus podszedł, wziął chleb i podał im, podobnie i rybę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 14, 'To już trzeci raz, jak Jezus ukazał się swoim uczniom po zmartwychwstaniu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 15, 'A gdy zjedli, Jezus zapytał Szymona Piotra: Szymonie, synu Jonasza, miłujesz mnie bardziej niż ci? Odpowiedział mu: Tak, Panie, ty wiesz, że cię miłuję. Powiedział do niego: Paś moje baranki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 16, 'Zapytał go znowu, po raz drugi: Szymonie, synu Jonasza, miłujesz mnie? Odpowiedział mu: Tak, Panie, ty wiesz, że cię miłuję. Powiedział mu: Paś moje owce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 17, 'Zapytał go po raz trzeci: Szymonie, synu Jonasza, miłujesz mnie? I zasmucił się Piotr, że go zapytał po raz trzeci: Miłujesz mnie? I odpowiedział mu: Panie, ty wszystko wiesz, ty wiesz, że cię miłuję. Jezus powiedział do niego: Paś moje owce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 18, 'Zaprawdę, zaprawdę powiadam ci: Gdy byłeś młodszy, opasywałeś się i chodziłeś, gdzie chciałeś. Gdy jednak się zestarzejesz, wyciągniesz swoje ręce, a inny cię opasze i poprowadzi, dokąd nie chcesz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 19, 'Powiedział to, dając znać, jaką śmiercią miał uwielbić Boga. A to powiedziawszy, rzekł mu: Pójdź za mną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 20, 'A Piotr, odwróciwszy się, zobaczył ucznia, którego Jezus miłował, idącego za nim, który też przy wieczerzy położył się na jego piersi i zapytał: Panie, kto jest tym, który cię wyda?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 21, 'Gdy więc Piotr go zobaczył, zapytał Jezusa: Panie, a co z nim?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 22, 'Jezus mu odpowiedział: Jeśli chcę, żeby on został, aż przyjdę, co tobie do tego? Ty pójdź za mną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 23, 'I rozeszła się wśród braci wieść, że ten uczeń nie umrze. Jezus jednak nie powiedział mu, że nie umrze, ale: Jeśli chcę, aby został, aż przyjdę, co tobie do tego?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 24, 'To jest ten uczeń, który świadczy o tym i to napisał, a wiemy, że jego świadectwo jest prawdziwe.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 25, 'Jest też jeszcze wiele innych rzeczy, których dokonał Jezus, które gdyby miały być wszystkie z osobna spisane, sądzę, że i cały świat nie mógłby pomieścić ksiąg, które byłyby napisane. Amen.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 1, 'Pierwszą księgę napisałem, Teofilu, o wszystkim, co Jezus zaczął czynić i czego nauczać;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 2, 'Aż do dnia, w którym został wzięty w górę po tym, jak przez Ducha Świętego udzielił poleceń apostołom, których wybrał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 3, 'Im też po swojej męce objawił się jako żywy w wielu niewątpliwych dowodach, przez czterdzieści dni ukazując się im i mówiąc o królestwie Bożym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 4, 'A gdy byli zebrani razem, nakazał im: Nie odchodźcie z Jerozolimy, ale oczekujcie obietnicy Ojca, o której słyszeliście ode mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 5, 'Jan bowiem chrzcił wodą, ale wy po niewielu dniach będziecie ochrzczeni Duchem Świętym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 6, 'Tak więc zebrani pytali go: Panie, czy w tym czasie przywrócisz królestwo Izraelowi?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 7, 'Lecz on im odpowiedział: Nie do was należy znać czasy i pory, które Ojciec ustanowił swoją władzą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 8, 'Ale przyjmiecie moc Ducha Świętego, który zstąpi na was, i będziecie mi świadkami w Jerozolimie, w całej Judei, w Samarii i aż po krańce ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 9, 'Kiedy to powiedział, a oni patrzyli, został uniesiony w górę i obłok zabrał go sprzed ich oczu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 10, 'A gdy się wpatrywali w niebo, jak wstępował, oto stanęli przy nich dwaj mężowie w białych szatach;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 11, 'I powiedzieli: Mężowie z Galilei, dlaczego stoicie, wpatrując się w niebo? Ten Jezus, który został od was wzięty w górę do nieba, przyjdzie tak samo, jak go widzieliście wstępującego do nieba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 12, 'Wtedy wrócili do Jerozolimy z góry zwanej Oliwną, która leży blisko Jerozolimy, w odległości drogi szabatowej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 13, 'A gdy przyszli, weszli do sali na górze, gdzie przebywali Piotr i Jakub, Jan i Andrzej, Filip i Tomasz, Bartłomiej i Mateusz, Jakub, syn Alfeusza, i Szymon Zelota oraz Juda, brat Jakuba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 14, 'Ci wszyscy trwali jednomyślnie w modlitwie i prośbach razem z kobietami, z Marią, matką Jezusa, i jego braćmi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 15, 'W tych dniach Piotr stanął pośród uczniów (a było zgromadzonych około stu dwudziestu osób) i powiedział:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 16, 'Mężowie bracia, musiało się wypełnić słowo Pisma, w którym Duch Święty zapowiedział przez usta Dawida o Judaszu, który był przewodnikiem tych, którzy schwytali Jezusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 17, 'Zaliczał się on bowiem do nas i miał udział w tym posługiwaniu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 18, 'On nabył pole za zapłatę za nieprawość i spadłszy głową w dół, pękł na pół i wypłynęły wszystkie jego wnętrzności.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 19, 'Rozniosło się to wśród wszystkich mieszkańców Jerozolimy, tak że nazwano to pole w ich języku Hakeldamach, to znaczy: Pole Krwi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 20, 'Jest bowiem napisane w Księdze Psalmów: Niech jego dom będzie pusty, niech nikt w nim nie mieszka; oraz: Jego biskupstwo niech przejmie inny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 21, 'Trzeba więc, aby jeden z tych mężczyzn, którzy z nami byli przez cały czas, kiedy Pan Jezus przebywał wśród nas;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 22, 'Począwszy od chrztu Jana aż do dnia, w którym został wzięty od nas w górę, stał się wraz z nami świadkiem jego zmartwychwstania.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 23, 'I wybrali dwóch: Józefa, zwanego Barsabą, z przydomkiem Justus, i Macieja.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 24, 'I tak się modlili: Ty, Panie, który znasz serca wszystkich, wskaż z tych dwóch jednego, którego wybrałeś;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 25, 'Aby zajął miejsce w tym posługiwaniu i apostolstwie, któremu sprzeniewierzył się Judasz, aby odejść na swoje miejsce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 26, 'I dali im losy, a los padł na Macieja. I został przyłączony do jedenastu apostołów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 1, 'A gdy nadszedł dzień Pięćdziesiątnicy, wszyscy byli jednomyślnie na tym samym miejscu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 2, 'Nagle powstał odgłos z nieba, jakby uderzenie gwałtownego wiatru, i wypełnił cały dom, w którym siedzieli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 3, 'Ukazały się im rozdzielone języki jakby z ognia, które spoczęły na każdym z nich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 4, 'I wszyscy zostali napełnieni Duchem Świętym, i zaczęli mówić innymi językami, tak jak im Duch pozwalał mówić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 5, 'A przebywali w Jerozolimie Żydzi, mężczyźni pobożni, ze wszystkich narodów pod niebem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 6, 'A kiedy powstał ten szum, zeszło się mnóstwo ludzi i zdumieli się, bo każdy z nich słyszał ich mówiących w jego własnym języku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 7, 'I pytali się nawzajem zdziwieni i pełni zdumienia: Czy ci wszyscy, którzy mówią, nie są Galilejczykami?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 8, 'Jak to jest, że każdy z nas słyszy swój własny język ojczysty?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 9, 'Partowie, Medowie, Elamici i ci, którzy mieszkają w Mezopotamii, Judei, Kapadocji, w Poncie i Azji;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 10, 'We Frygii, w Pamfilii, Egipcie i w częściach Libii, które leżą obok Cyreny, a także przybysze z Rzymu, zarówno Żydzi, jak i prozelici;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 11, 'Kreteńczycy i Arabowie – słyszymy ich głoszących w naszych językach wielkie dzieła Boże.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 12, 'I zdumiewali się wszyscy, i dziwili, mówiąc jeden do drugiego: Co to ma znaczyć?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 13, 'Lecz inni naśmiewali się i mówili: Upili się młodym winem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 14, 'Wtedy stanął Piotr z jedenastoma, podniósł swój głos i przemówił do nich: Mężowie z Judei i wszyscy, którzy mieszkacie w Jerozolimie, przyjmijcie do wiadomości i posłuchajcie uważnie moich słów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 15, 'Oni bowiem nie są pijani, jak sądzicie, bo jest dopiero trzecia godzina dnia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 16, 'Ale to jest to, co zostało przepowiedziane przez proroka Joela:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 17, 'I stanie się w ostatecznych dniach – mówi Bóg – że wyleję z mego Ducha na wszelkie ciało i będą prorokować wasi synowie i córki, wasi młodzieńcy będą mieć widzenia, a starcy będą śnić sny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 18, 'Nawet na moje sługi i służebnice wyleję w tych dniach z mego Ducha i będą prorokować.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 19, 'I ukażę cuda na niebie w górze i znaki na ziemi na dole, krew, ogień i kłęby dymu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 20, 'Słońce zamieni się w ciemność, a księżyc w krew, zanim nadejdzie ten dzień Pański, wielki i okazały.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 21, 'I stanie się, że każdy, kto wezwie imienia Pana, będzie zbawiony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 22, 'Mężowie izraelscy, słuchajcie tych słów: Jezusa z Nazaretu, męża potwierdzonego przez Boga wśród was mocami, cudami i znakami, których Bóg dokonał przez niego wśród was, o czym sami wiecie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 23, 'Wydanego zgodnie z powziętym postanowieniem Boga oraz tym, co przedtem wiedział, wzięliście i rękami bezbożników ukrzyżowaliście i zabiliście.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 24, 'Jego to Bóg wskrzesił, uwolniwszy od boleści śmierci, bo było niemożliwe, aby ta mogła go zatrzymać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 25, 'Dawid bowiem mówi o nim: Patrzyłem na Pana zawsze przed moim obliczem, bo jest po mojej prawicy, żebym się nie zachwiał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 26, 'Dlatego rozweseliło się moje serce i rozradował się mój język, a także moje ciało będzie spoczywać w nadziei.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 27, 'Nie zostawisz bowiem mojej duszy w piekle i nie dasz swojemu Świętemu doznać zniszczenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 28, 'Dałeś mi poznać drogi życia, a twoje oblicze napełni mnie radością.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 29, 'Mężowie bracia, mogę swobodnie mówić do was o patriarsze Dawidzie, że umarł i został pogrzebany, a jego grobowiec znajduje się u nas aż do dziś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 30, 'Będąc więc prorokiem i wiedząc, że Bóg zaręczył mu przysięgą, iż z owocu jego bioder, według ciała, wzbudzi Chrystusa i posadzi na jego tronie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 31, 'Przepowiadał to i mówił o zmartwychwstaniu Chrystusa, że jego dusza nie pozostanie w piekle, a jego ciało nie dozna zniszczenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 32, 'Tego to Jezusa wskrzesił Bóg, czego my wszyscy jesteśmy świadkami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 33, 'Będąc więc wywyższony prawicą Boga, otrzymał od Ojca obietnicę Ducha Świętego i wylał to, co wy teraz widzicie i słyszycie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 34, 'Dawid bowiem nie wstąpił do nieba, a jednak sam mówi: Powiedział Pan memu Panu: Siądź po mojej prawicy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 35, 'Aż położę twoich nieprzyjaciół jako podnóżek pod twoje stopy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 36, 'Niech więc cały dom Izraela wie z pewnością, że tego Jezusa, którego wy ukrzyżowaliście, Bóg uczynił i Panem, i Chrystusem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 37, 'A słysząc to, przerazili się do głębi serca i zapytali Piotra i pozostałych apostołów: Co mamy robić, mężowie bracia?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 38, 'Wtedy Piotr powiedział do nich: Pokutujcie i niech każdy z was ochrzci się w imię Jezusa Chrystusa na przebaczenie grzechów, a otrzymacie dar Ducha Świętego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 39, 'Obietnica ta bowiem dotyczy was, waszych dzieci i wszystkich, którzy są daleko, każdego, kogo powoła Pan, nasz Bóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 40, 'W wielu też innych słowach dawał świadectwo i napominał ich: Ratujcie się od tego przewrotnego pokolenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 41, 'Ci więc, którzy chętnie przyjęli jego słowa, zostali ochrzczeni. I przyłączyło się tego dnia około trzech tysięcy dusz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 42, 'Trwali oni w nauce apostołów, w społeczności, w łamaniu chleba i w modlitwach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 43, 'I strach ogarnął każdą duszę, gdyż wiele znaków i cudów działo się przez apostołów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 44, 'A wszyscy, którzy uwierzyli, byli razem i wszystko mieli wspólne.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 45, 'Sprzedawali posiadłości i dobra i rozdzielali je wszystkim według potrzeb.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 46, 'Każdego dnia trwali zgodnie w świątyni, a łamiąc chleb po domach, przyjmowali pokarm z radością i w prostocie serca;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 47, 'Chwaląc Boga i ciesząc się przychylnością wszystkich ludzi. A Pan dodawał kościołowi każdego dnia tych, którzy mieli być zbawieni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 1, 'Piotr i Jan weszli razem do świątyni w godzinie modlitwy, o dziewiątej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 2, 'A wnoszono właśnie pewnego mężczyznę, chromego od urodzenia, którego każdego dnia sadzano u bramy świątyni, zwanej Piękną, żeby wchodzących do świątyni prosił o jałmużnę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 3, 'Gdy zobaczył Piotra i Jana, jak mieli wejść do świątyni, prosił ich o jałmużnę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 4, 'A Piotr, przypatrując mu się wraz z Janem, powiedział: Spójrz na nas.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 5, 'On więc spojrzał na nich uważnie, spodziewając się, że coś od nich otrzyma.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 6, 'Wtedy Piotr powiedział: Nie mam srebra ani złota, lecz co mam, to ci daję: W imieniu Jezusa Chrystusa z Nazaretu, wstań i chodź!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 7, 'A ująwszy go za prawą rękę, podniósł go. I natychmiast wzmocniły się jego nogi i kostki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 8, 'A on zerwał się, wstał i chodził. Wszedł z nimi do świątyni, chodząc, skacząc i chwaląc Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 9, 'A wszyscy ludzie widzieli go chodzącego i chwalącego Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 10, 'I rozpoznali w nim tego człowieka, który dla jałmużny siadał przy Pięknej Bramie świątyni, i ogarnęło ich zdumienie i zachwyt nad tym, co mu się przydarzyło.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 11, 'A gdy ten chromy, który został uzdrowiony, trzymał się Piotra i Jana, wszyscy ludzie zdumieni zbiegli się do nich w przedsionku, który zwano Salomonowym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 12, 'Kiedy Piotr to zobaczył, przemówił do ludzi: Mężowie izraelscy, dlaczego się temu dziwicie i dlaczego się nam tak uważnie przypatrujecie, jakbyśmy własną mocą albo pobożnością sprawili, że on chodzi?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 13, 'Bóg Abrahama, Izaaka i Jakuba, Bóg naszych ojców, uwielbił Jezusa, swego Syna, którego wy wydaliście i wyparliście się przed Piłatem, gdy postanowił go uwolnić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 14, 'A wy wyparliście się Świętego i Sprawiedliwego i prosiliście o uwolnienie wam mordercy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 15, 'I zabiliście Dawcę życia, którego Bóg wskrzesił z martwych, czego my jesteśmy świadkami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 16, 'A przez wiarę w jego imię, temu, którego widzicie i znacie, imię to przywróciło siły. To wiara, która jest przez niego, dała mu pełne zdrowie na oczach was wszystkich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 17, 'Ale teraz, bracia, wiem, że uczyniliście to z nieświadomości, tak jak wasi przełożeni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 18, 'Lecz Bóg w ten sposób wypełnił to, co przepowiedział przez usta wszystkich swoich proroków, że jego Chrystus będzie cierpiał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 19, 'Dlatego pokutujcie i nawróćcie się, aby wasze grzechy były zgładzone, gdy nadejdą od obecności Pana czasy ochłody;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 20, 'I pośle tego, który był wam głoszony, Jezusa Chrystusa;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 21, 'Którego niebo musi przyjąć aż do czasu odnowienia wszystkich rzeczy, jak Bóg od wieków przepowiadał przez usta wszystkich swoich świętych proroków.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 22, 'Mojżesz bowiem powiedział do ojców: Proroka jak ja wzbudzi wam Pan, wasz Bóg, spośród waszych braci. Jego będziecie słuchać we wszystkim, co wam powie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 23, 'I stanie się, że każda dusza, która nie będzie słuchać tego proroka, będzie wytracona spośród ludu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 24, 'Przepowiadali te dni także wszyscy prorocy, którzy przemawiali od czasów Samuela i inni po nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 25, 'Wy jesteście synami proroków i przymierza, które Bóg zawarł z naszymi ojcami, mówiąc do Abrahama: W twoim potomstwie będą błogosławione wszystkie narody ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 26, 'Wzbudziwszy swego Syna, Jezusa, Bóg najpierw posłał go do was, aby wam błogosławił w odwracaniu się każdego z was od swoich nieprawości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 1, 'A gdy mówili to do ludzi, nadeszli kapłani, dowódca straży świątynnej i saduceusze;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 2, 'Oburzeni, że nauczają ludzi i głoszą w Jezusie powstanie z martwych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 3, 'Schwytali ich i wtrącili do więzienia aż do następnego dnia, bo był już wieczór.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 4, 'A wielu z tych, którzy słyszeli słowo, uwierzyło. A mężczyzn było w liczbie około pięciu tysięcy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 5, 'Nazajutrz zebrali się w Jerozolimie ich przełożeni, starsi i uczeni w Piśmie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 6, 'I Annasz, najwyższy kapłan, i Kajfasz, Jan, Aleksander i ilu ich było z rodu najwyższych kapłanów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 7, 'Postawili ich na środku i pytali: Jaką mocą albo w czyim imieniu to uczyniliście?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 8, 'Wtedy Piotr, pełen Ducha Świętego, powiedział do nich: Przełożeni ludu i starsi Izraela;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 9, 'Jeśli my dziś mamy być przesłuchiwani z powodu dobrodziejstwa wyświadczonego choremu człowiekowi, dzięki czemu został on uzdrowiony;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 10, 'Niech wam wszystkim i całemu ludowi Izraela będzie wiadomo, że w imieniu Jezusa Chrystusa z Nazaretu, którego wy ukrzyżowaliście, a którego Bóg wskrzesił z martwych, przez niego on stoi przed wami zdrowy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 11, 'On jest tym kamieniem odrzuconym przez was, budujących, który stał się kamieniem węgielnym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 12, 'I nie ma w nikim innym zbawienia. Nie ma bowiem pod niebem żadnego innego imienia danego ludziom, przez które moglibyśmy być zbawieni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 13, 'Gdy zobaczyli odwagę Piotra i Jana i zrozumieli, że są ludźmi nieuczonymi i prostymi, dziwili się. Rozpoznali również, że byli z Jezusem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 14, 'Widząc też, że stoi z nimi uzdrowiony człowiek, nie mogli nic przeciwko temu powiedzieć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 15, 'Rozkazali im więc opuścić Radę i naradzali się między sobą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 16, 'Mówili: Co zrobimy z tymi ludźmi? Bo to, że dokonali oczywistego cudu, wiadomo wszystkim mieszkańcom Jerozolimy i nie możemy temu zaprzeczyć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 17, 'Lecz żeby się to bardziej nie rozchodziło wśród ludzi, zabrońmy im pod groźbą mówić do kogokolwiek w to imię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 18, 'A przywoławszy ich, nakazali, aby w ogóle nie mówili ani nie nauczali w imię Jezusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 19, 'Lecz Piotr i Jan odpowiedzieli im: Rozsądźcie, czy to sprawiedliwe w oczach Boga bardziej was słuchać niż Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 20, 'My bowiem nie możemy nie mówić o tym, co widzieliśmy i słyszeliśmy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 21, 'A oni zagrozili im, a nie znajdując żadnej podstawy do ich ukarania, wypuścili ich ze względu na ludzi, bo wszyscy chwalili Boga za to, co się stało.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 22, 'Człowiek bowiem, na którym dokonał się cud uzdrowienia, miał ponad czterdzieści lat.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 23, 'A gdy ich wypuszczono, przyszli do swoich i opowiedzieli im wszystko, co do nich mówili naczelni kapłani i starsi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 24, 'A gdy oni to usłyszeli, jednomyślnie podnieśli swój głos do Boga i powiedzieli: Panie, ty jesteś Bogiem, który uczynił niebo, ziemię, morze i wszystko, co w nich jest;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 25, 'Który przez usta swego sługi Dawida powiedziałeś: Dlaczego burzą się narody, a ludzie knują próżne rzeczy?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 26, 'Królowie ziemi powstali i książęta zebrali się razem przeciw Panu i przeciw jego Chrystusowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 27, 'Rzeczywiście bowiem Herod i Poncjusz Piłat z poganami i ludem Izraela zebrali się przeciwko twemu świętemu Synowi, Jezusowi, którego namaściłeś;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 28, 'Aby uczynić to, co twoja ręka i twój wyrok przedtem postanowiły, że ma się stać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 29, 'A teraz, Panie, spójrz na ich groźby i daj twoim sługom z całą odwagą głosić twoje słowo;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 30, 'Gdy ty wyciągniesz swoją rękę, aby uzdrawiać i dokonywać znaków i cudów przez imię twego świętego Syna, Jezusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 31, 'A gdy oni się modlili, zatrzęsło się miejsce, na którym byli zebrani, i wszyscy zostali napełnieni Duchem Świętym, i z odwagą głosili słowo Boże.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 32, 'A to mnóstwo wierzących miało jedno serce i jedną duszę. Nikt nie nazywał swoim tego, co posiadał, ale wszystko mieli wspólne.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 33, 'Apostołowie zaś z wielką mocą dawali świadectwo o zmartwychwstaniu Pana Jezusa i wielka łaska była nad nimi wszystkimi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 34, 'Nie było też wśród nich nikogo, kto by cierpiał niedostatek, gdyż ci, którzy mieli pola albo domy, sprzedawali je i przynosili pieniądze za to, co posprzedawali;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 35, 'I kładli u stóp apostołów. Rozdzielano to każdemu według potrzeb.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 36, 'Także Józef, nazwany przez apostołów Barnabą – co się tłumaczy: Syn Pocieszenia – lewita rodem z Cypru;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 37, 'Sprzedał ziemię, którą posiadał, a pieniądze przyniósł i położył u stóp apostołów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 1, 'A pewien człowiek, imieniem Ananiasz, ze swoją żoną Safirą, sprzedał swą posiadłość;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 2, 'I za wiedzą swojej żony odłożył sobie część pieniędzy, a pewną część przyniósł i złożył u stóp apostołów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 3, 'Lecz Piotr powiedział: Ananiaszu, dlaczego szatan tak napełnił twoje serce, abyś okłamał Ducha Świętego i odłożył sobie część pieniędzy za ziemię?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 4, 'Czy to, co miałeś, nie było twoje? A to, co otrzymałeś za sprzedaż, czy nie pozostawało w twojej mocy? Dlaczego dopuściłeś to do swego serca? Nie okłamałeś ludzi, lecz Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 5, 'Ananiasz zaś, usłyszawszy te słowa, padł nieżywy. I wielki strach ogarnął wszystkich, którzy to słyszeli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 6, 'Młodsi wstali, owinęli go, wynieśli i pogrzebali.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 7, 'A po około trzech godzinach weszła także jego żona, nie wiedząc, co się stało.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 8, 'I zapytał ją Piotr: Powiedz mi, czy za tyle sprzedaliście ziemię? A ona odpowiedziała: Tak, za tyle.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 9, 'Wtedy Piotr powiedział do niej: Dlaczego się ze sobą zmówiliście, aby wystawić na próbę Ducha Pańskiego? Oto są przed drzwiami ci, którzy pogrzebali twego męża, i ciebie wyniosą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 10, 'I natychmiast padła nieżywa u jego stóp. A gdy młodzieńcy weszli, znaleźli ją martwą. Wynieśli ją więc i pogrzebali obok męża.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 11, 'I wielki strach ogarnął cały kościół i wszystkich, którzy to słyszeli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 12, 'A przez ręce apostołów działo się wiele znaków i cudów wśród ludu. (I byli wszyscy jednomyślnie w przedsionku Salomona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 13, 'I z pozostałych nikt nie śmiał się do nich przyłączyć, ale ludzie bardzo ich wychwalali.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 14, 'Przybywało też Panu mnóstwo wierzących, mężczyzn i kobiet).');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 15, 'Tak, że nawet na ulice wynoszono chorych i kładziono ich na noszach i posłaniach, aby przynajmniej cień przechodzącego Piotra padł na niektórych z nich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 16, 'Schodziło się też z okolicznych miast do Jerozolimy mnóstwo ludzi, przynosząc chorych i dręczonych przez duchy nieczyste, a wszyscy zostali uzdrowieni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 17, 'Wtedy najwyższy kapłan i wszyscy, którzy z nim byli, należący do stronnictwa saduceuszy, pełni zazdrości, powstali;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 18, 'I schwytali apostołów, których wtrącili do publicznego więzienia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 19, 'Lecz anioł Pana w nocy otworzył drzwi więzienia i wyprowadziwszy ich, powiedział:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 20, 'Idźcie i wystąpiwszy, mówcie do ludzi w świątyni wszystkie słowa tego życia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 21, 'Kiedy to usłyszeli, weszli o świcie do świątyni i nauczali. Tymczasem najwyższy kapłan i ci, którzy z nim byli, przyszli, zwołali Radę oraz wszystkich starszych spośród synów Izraela i posłali do więzienia, aby ich przyprowadzono.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 22, 'Lecz gdy słudzy przyszli i nie znaleźli ich w więzieniu, wrócili i oznajmili:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 23, 'Wprawdzie zastaliśmy więzienie starannie zamknięte, a strażników stojących na zewnątrz, przed drzwiami, po otwarciu jednak nie znaleźliśmy w nim nikogo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 24, 'A gdy najwyższy kapłan i dowódca straży świątynnej oraz naczelni kapłani usłyszeli te słowa, zastanawiali się, co z tego będzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 25, 'Wówczas nadszedł ktoś i oznajmił im: Ludzie, których wtrąciliście do więzienia, stoją w świątyni i nauczają lud.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 26, 'Wtedy dowódca straży poszedł ze sługami i przyprowadził ich bez użycia siły. Bali się bowiem ludu, żeby ich nie ukamienowali.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 27, 'Gdy ich przyprowadzili, postawili ich przed Radą. I zapytał ich najwyższy kapłan:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 28, 'Czy nie zakazaliśmy wam surowo, żebyście w tym imieniu nie nauczali? A oto napełniliście Jerozolimę waszą nauką i chcecie na nas ściągnąć krew tego człowieka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 29, 'Wtedy Piotr i apostołowie odpowiedzieli: Bardziej trzeba słuchać Boga niż ludzi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 30, 'Bóg naszych ojców wskrzesił Jezusa, którego wy zabiliście, zawiesiwszy na drzewie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 31, 'Tego Bóg wywyższył swoją prawicą, aby był władcą i zbawicielem, aby ludowi Izraela dać pokutę i przebaczenie grzechów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 32, 'A my jesteśmy jego świadkami w tym, a także Duch Święty, którego Bóg dał tym, którzy są mu posłuszni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 33, 'A oni, słysząc to, wpadli w gniew i naradzali się nad tym, jakby ich zabić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 34, 'Wtedy pewien faryzeusz, imieniem Gamaliel, nauczyciel prawa, szanowany przez wszystkich ludzi, powstał na Radzie i nakazał, aby na chwilę wyprowadzono apostołów;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 35, 'I powiedział do nich: Mężowie izraelscy, zastanówcie się dobrze, co zamierzacie zrobić z tymi ludźmi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 36, 'Niedawno bowiem wystąpił Teudas, podając się za nie byle kogo, do którego przyłączyło się około czterystu ludzi. Zabito go, a wszyscy jego zwolennicy rozproszyli się i ślad po nich zaginął.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 37, 'Po nim w dniach spisu wystąpił Judasz Galilejczyk i pociągnął za sobą wielu ludzi. Lecz i on zginął, a wszyscy jego zwolennicy rozproszyli się.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 38, 'Dlatego teraz mówię wam: Odstąpcie od tych ludzi i zostawcie ich. Jeśli bowiem ten zamysł czy ta sprawa pochodzi od ludzi, obróci się wniwecz;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 39, 'Ale jeśli pochodzi od Boga, nie będziecie mogli tego zniszczyć, aby się czasem nie okazało, że walczycie z Bogiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 40, 'I posłuchali go. A przywoławszy apostołów, ubiczowali ich i zabronili im mówić w imię Jezusa, a potem ich wypuścili.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 41, 'A oni odchodzili sprzed Rady, ciesząc się, że stali się godni znosić zniewagę dla imienia Jezusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 42, 'Nie przestawali też codziennie w świątyni i po domach nauczać i głosić Jezusa Chrystusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 1, 'A w tych dniach, gdy liczba uczniów wzrastała, helleniści zaczęli szemrać przeciwko Żydom, że zaniedbywano w codziennym posługiwaniu ich wdowy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 2, 'Wtedy dwunastu, zwoławszy całe mnóstwo uczniów, powiedziało: Nie jest rzeczą słuszną, żebyśmy porzucili słowo Boże, a obsługiwali stoły.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 3, 'Upatrzcie więc, bracia, spośród siebie siedmiu mężczyzn, mających dobre świadectwo, pełnych Ducha Świętego i mądrości, którym zlecimy tę sprawę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 4, 'My zaś oddamy się modlitwie i posłudze słowa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 5, 'I spodobało się to całej gromadzie zebranych. Wybrali więc Szczepana, męża pełnego wiary i Ducha Świętego, Filipa, Prochora, Nikanora, Tymona, Parmenasa i Mikołaja, prozelitę z Antiochii.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 6, 'Przedstawili ich apostołom, którzy modląc się, położyli na nich ręce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 7, 'I rozszerzało się słowo Boże, i liczba uczniów w Jerozolimie bardzo się pomnażała; także bardzo wielu kapłanów stawało się posłusznych wierze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 8, 'A Szczepan, pełen wiary i mocy, czynił cuda i wielkie znaki wśród ludzi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 9, 'Wtedy niektórzy z synagogi zwanej synagogą Libertynów i Cyrenejczyków, i Aleksandryjczyków oraz tych, którzy pochodzili z Cylicji i Azji, wystąpili do rozprawy ze Szczepanem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 10, 'Lecz nie mogli sprostać mądrości i duchowi, z którym mówił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 11, 'Podstawili więc ludzi, którzy zeznali: Słyszeliśmy, jak mówił bluźnierstwa przeciwko Mojżeszowi i przeciwko Bogu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 12, 'I tak podburzyli lud, starszych i uczonych w Piśmie; a gdy przybiegli do niego, porwali go i przyprowadzili do Rady.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 13, 'I podstawili fałszywych świadków, którzy zeznali: Ten człowiek nie przestaje mówić bluźnierstw przeciwko temu świętemu miejscu i przeciwko prawu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 14, 'Słyszeliśmy bowiem, jak mówił, że ten Jezus z Nazaretu zburzy to miejsce i zmieni zwyczaje, które nam przekazał Mojżesz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 15, 'A wszyscy, którzy zasiadali w Radzie, przyglądali mu się uważnie i zobaczyli, że jego twarz jest jak oblicze anioła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 1, 'Wtedy najwyższy kapłan zapytał: Czy tak się sprawy mają?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 2, 'A on odpowiedział: Mężowie bracia i ojcowie, słuchajcie! Bóg chwały ukazał się naszemu ojcu Abrahamowi, gdy był w Mezopotamii, zanim zamieszkał w Charanie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 3, 'I powiedział do niego: Opuść swoją ziemię i swoją rodzinę i idź do ziemi, którą ci wskażę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 4, 'Wtedy wyszedł z ziemi chaldejskiej i zamieszkał w Charanie. A stamtąd, gdy umarł jego ojciec, Bóg przeniósł go do tej ziemi, w której wy teraz mieszkacie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 5, 'I nie dał mu w niej dziedzictwa nawet na stopę jego nogi. Obiecał tylko, że da ją w posiadanie jemu i jego potomstwu po nim, gdy jeszcze nie miał dziecka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 6, 'I tak mu Bóg powiedział: Twoje potomstwo będzie przebywać w obcej ziemi, wezmą je w niewolę i będą je uciskać przez czterysta lat.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 7, 'Lecz ten naród, u którego będzie w niewoli, ja będę sądził – powiedział Bóg. A potem wyjdą i będą mi służyć na tym miejscu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 8, 'I zawarł z nim przymierze obrzezania. Tak to Abraham spłodził Izaaka i obrzezał go ósmego dnia, a Izaak Jakuba, a Jakub dwunastu patriarchów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 9, 'A patriarchowie z zawiści sprzedali Józefa do Egiptu. Lecz Bóg był z nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 10, 'I wyrwał go ze wszystkich jego utrapień, i dał mu łaskę i mądrość w oczach faraona, króla Egiptu, który ustanowił go przełożonym nad Egiptem i nad całym swoim domem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 11, 'Potem nastał głód i wielka niedola w całej ziemi Egiptu i Kanaan, a nasi ojcowie nie znajdowali żywności.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 12, 'A gdy Jakub usłyszał, że w Egipcie jest zboże, wysłał naszych ojców pierwszy raz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 13, 'A za drugim razem Józef dał się poznać swoim braciom i faraon dowiedział się o rodzie Józefa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 14, 'Potem Józef posłał po swego ojca Jakuba i całą swoją rodzinę liczącą siedemdziesiąt pięć dusz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 15, 'Jakub przybył do Egiptu i tam umarł on sam i nasi ojcowie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 16, 'I zostali przeniesieni do Sychem i złożeni w grobie, który Abraham kupił za pieniądze u synów Chamora, ojca Sychema.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 17, 'A gdy zbliżył się czas obietnicy, którą Bóg złożył Abrahamowi, lud w Egipcie rozrodził się i rozmnożył;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 18, 'Aż nastał inny król, który nie znał Józefa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 19, 'Ten, działając podstępnie wobec naszego narodu, uciskał naszych ojców tak, że musieli porzucać swoje niemowlęta, żeby nie zostawały przy życiu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 20, 'W tym czasie urodził się Mojżesz, a był miły Bogu i wychowywano go przez trzy miesiące w domu jego ojca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 21, 'A gdy go porzucono, wzięła go córka faraona i wychowała go jak syna.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 22, 'I wyuczono Mojżesza całej mądrości egipskiej, i był potężny w słowach i czynach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 23, 'A gdy miał czterdzieści lat, przyszło mu na myśl odwiedzić swych braci, synów Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 24, 'A kiedy zobaczył, że jednemu z nich wyrządzano krzywdę, ujął się za nim i pomścił skrzywdzonego, zabijając Egipcjanina.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 25, 'Sądził bowiem, że jego bracia zrozumieją, że Bóg przez jego ręce daje im wybawienie. Lecz oni nie zrozumieli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 26, 'Następnego dnia zjawił się wśród nich, gdy się ze sobą bili, i próbował ich pogodzić, mówiąc: Ludzie, jesteście braćmi, dlaczego krzywdzicie jeden drugiego?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 27, 'Lecz ten, który krzywdził bliźniego, odepchnął go, mówiąc: Kto cię ustanowił wodzem i sędzią nad nami?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 28, 'Czy chcesz mnie zabić, tak jak wczoraj zabiłeś Egipcjanina?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 29, 'Na te słowa Mojżesz uciekł i był cudzoziemcem w ziemi Madian, gdzie spłodził dwóch synów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 30, 'Po czterdziestu latach ukazał mu się na pustyni góry Synaj anioł Pana w płomieniu ognia w krzaku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 31, 'Kiedy Mojżesz to ujrzał, zdziwił się na ten widok. A gdy podszedł, aby się temu przyjrzeć, rozległ się głos Pana:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 32, 'Ja jestem Bogiem twoich ojców, Bogiem Abrahama, Bogiem Izaaka i Bogiem Jakuba. A Mojżesz zadrżał i nie śmiał się przypatrywać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 33, 'Wtedy Pan powiedział do niego: Zdejmij z nóg obuwie, bo miejsce, na którym stoisz, jest ziemią świętą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 34, 'Patrząc, widziałem utrapienie mego ludu, który jest w Egipcie, i słyszałem jego wzdychanie, i zstąpiłem, żeby go wybawić. Dlatego teraz chodź, poślę cię do Egiptu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 35, 'Tego Mojżesza, którego się wyparli, mówiąc: Któż cię ustanowił wodzem i sędzią? – tego Bóg posłał jako wodza i wybawiciela przez rękę anioła, który mu się ukazał w krzaku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 36, 'On wyprowadził ich, czyniąc cuda i znaki w ziemi Egiptu, nad Morzem Czerwonym i na pustyni przez czterdzieści lat.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 37, 'To jest ten Mojżesz, który powiedział synom Izraela: Proroka jak ja wzbudzi wam Pan, wasz Bóg, spośród waszych braci. Jego będziecie słuchać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 38, 'On to był w zgromadzeniu na pustyni z aniołem, który mówił do niego na górze Synaj i z naszymi ojcami. On przyjął żywe słowa Boże, aby nam je przekazać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 39, 'Lecz nasi ojcowie nie chcieli mu być posłuszni, ale odepchnęli go i zwrócili swoje serca ku Egiptowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 40, 'Powiedzieli do Aarona: Zrób nam bogów, którzy będą szli przed nami, bo nie wiemy, co się stało z tym Mojżeszem, który nas wyprowadził z ziemi Egiptu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 41, 'I zrobili cielca w tych dniach, i złożyli ofiarę temu bożkowi, i cieszyli się dziełami swoich rąk.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 42, 'Wtedy Bóg odwrócił się od nich i oddał ich w służbę zastępom nieba, jak jest napisane w księdze proroków: Czy mi składaliście zabite zwierzęta i inne ofiary na pustyni przez czterdzieści lat, domu Izraela?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 43, 'Raczej obnosiliście namiot Molocha i gwiazdę waszego boga Remfana, wizerunki, które sobie zrobiliście, żeby oddawać im cześć. Dlatego zaprowadzę was poza Babilon.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 44, 'Nasi ojcowie mieli na pustyni Namiot Świadectwa, jak zarządził ten, który powiedział Mojżeszowi, aby go uczynił według wzoru, który widział.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 45, 'Nasi ojcowie z Jozuem wzięli go i wnieśli do posiadłości pogan, których Bóg wypędził sprzed oblicza naszych ojców, aż do dni Dawida;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 46, 'Który znalazł łaskę przed Bogiem i prosił, aby mógł znaleźć przybytek dla Boga Jakuba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 47, 'Lecz Salomon zbudował mu dom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 48, 'Najwyższy jednak nie mieszka w świątyniach uczynionych ręką, jak mówi prorok:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 49, 'Niebo jest moim tronem, a ziemia podnóżkiem moich stóp. Jakiż dom mi zbudujecie, mówi Pan, albo gdzie jest miejsce mego odpoczynku?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 50, 'Czy tego wszystkiego nie uczyniła moja ręka?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 51, 'Ludzie twardego karku, nieobrzezanego serca i uszu! Wy zawsze sprzeciwiacie się Duchowi Świętemu. Jak wasi ojcowie, tak i wy!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 52, 'Którego z proroków nie prześladowali wasi ojcowie? Pozabijali też tych, którzy przepowiadali przyjście Sprawiedliwego, którego wy staliście się teraz zdrajcami i mordercami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 53, 'Wy, którzy otrzymaliście prawo przez rozporządzenie aniołów, lecz nie przestrzegaliście go.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 54, 'Gdy to usłyszeli, wpadli w gniew i zgrzytali na niego zębami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 55, 'A on, pełen Ducha Świętego, patrzył uważnie w niebo i ujrzał chwałę Boga i Jezusa stojącego po prawicy Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 56, 'I powiedział: Oto widzę niebiosa otwarte i Syna Człowieczego stojącego po prawicy Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 57, 'A oni podnieśli wielki krzyk, zatkali sobie uszy i jednomyślnie się na niego rzucili.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 58, 'Wyrzucili go poza miasto i kamienowali, a świadkowie złożyli swoje szaty u stóp młodzieńca zwanego Saulem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 59, 'Tak kamienowali Szczepana, modlącego się tymi słowy: Panie Jezu, przyjmij mojego ducha.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 60, 'A upadłszy na kolana, zawołał donośnym głosem: Panie, nie poczytaj im tego za grzech. A gdy to powiedział, zasnął.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 1, 'A Saul zgodził się na zabicie go. W tym czasie zaczęło się wielkie prześladowanie kościoła w Jerozolimie i wszyscy oprócz apostołów rozproszyli się po okolicach Judei i Samarii.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 2, 'Szczepana zaś pogrzebali bogobojni ludzie i bardzo go opłakiwali.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 3, 'Tymczasem Saul niszczył kościół. Wchodził do domów, wywlekał mężczyzn i kobiety i wtrącał ich do więzienia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 4, 'A ci, którzy się rozproszyli, szli wszędzie, głosząc słowo Boże.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 5, 'Filip przybył do miasta Samarii i głosił im Chrystusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 6, 'A lud jednomyślnie przyjmował to, co mówił Filip, gdy go słyszeli i widzieli cuda, które czynił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 7, 'Duchy nieczyste bowiem wychodziły z donośnym krzykiem z wielu, którzy je mieli. Wielu też sparaliżowanych i ułomnych zostało uzdrowionych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 8, 'I wielka radość zapanowała w tym mieście.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 9, 'A pewien człowiek o imieniu Szymon, który wcześniej w tym mieście zajmował się czarami, mamił lud Samarii, twierdząc, że jest kimś wielkim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 10, 'Liczyli się z nim wszyscy od najmniejszego do największego, mówiąc: Ten człowiek jest tą wielką mocą Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 11, 'A liczyli się z nim dlatego, że od dłuższego czasu mamił ich swoimi czarami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 12, 'A gdy uwierzyli Filipowi, który głosił o królestwie Bożym i o imieniu Jezusa Chrystusa, chrzcili się zarówno mężczyźni, jak i kobiety.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 13, 'Uwierzył też sam Szymon, a gdy się ochrzcił, trzymał się Filipa i zdumiewał się, widząc cuda i wielkie znaki, jakie się działy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 14, 'Kiedy apostołowie, którzy byli w Jerozolimie, usłyszeli, że Samaria przyjęła słowo Boże, wysłali do nich Piotra i Jana;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 15, 'Którzy przyszli tam i modlili się za nich, aby otrzymali Ducha Świętego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 16, 'Na żadnego z nich bowiem jeszcze nie zstąpił. Byli tylko ochrzczeni w imię Pana Jezusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 17, 'Wtedy kładli na nich ręce, a oni otrzymywali Ducha Świętego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 18, 'A gdy Szymon zobaczył, że Duch Święty był udzielany przez nakładanie rąk apostołów, przyniósł im pieniądze;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 19, 'Mówiąc: Dajcie i mnie tę moc, aby ten, na kogo nałożę ręce, otrzymał Ducha Świętego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 20, 'I powiedział mu Piotr: Niech zginą z tobą twoje pieniądze, bo sądziłeś, że dar Boży można nabyć za pieniądze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 21, 'Nie masz w tej sprawie części ani udziału, bo twoje serce nie jest prawe przed Bogiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 22, 'Dlatego pokutuj z tej twojej nieprawości i proś Boga, a może ci przebaczy zamysł twego serca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 23, 'Widzę bowiem, że jesteś pogrążony w goryczy żółci i w więzach nieprawości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 24, 'Wtedy Szymon odpowiedział: Módlcie się za mnie do Pana, aby nic z tego, co powiedzieliście, mnie nie spotkało.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 25, 'A gdy dali świadectwo i opowiedzieli słowo Pana, udali się w drogę powrotną do Jerozolimy i głosili ewangelię w wielu wioskach samarytańskich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 26, 'Lecz anioł Pana powiedział do Filipa: Wstań i idź na południe, na drogę, która prowadzi z Jerozolimy do Gazy. Jest to droga pustynna.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 27, 'Wstał więc i poszedł. A oto przyjechał do Jerozolimy oddać cześć Bogu Etiopczyk, eunuch, dostojnik królowej etiopskiej Kandaki, który zarządzał jej wszystkimi skarbami;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 28, 'I wracał, a siedząc na swoim wozie, czytał proroka Izajasza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 29, 'A Duch powiedział do Filipa: Podejdź i przyłącz się do tego wozu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 30, 'Kiedy Filip podbiegł, usłyszał, jak tamten czyta proroka Izajasza, i zapytał: Rozumiesz, co czytasz?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 31, 'A on odpowiedział: Jak mogę rozumieć, jeśli mi nikt nie wyjaśni? I zaprosił Filipa, aby wszedł i przy nim usiadł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 32, 'A czytał ten fragment Pisma: Jak owca na rzeź był prowadzony i jak baranek milczący wobec tego, który go strzyże, tak on nie otworzył swoich ust.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 33, 'W jego poniżeniu pozbawiono go sądu, a któż wypowie jego ród? Jego życie bowiem zostało zabrane z ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 34, 'I zapytał eunuch Filipa: Proszę cię, o kim to prorok mówi? Sam o sobie czy o kimś innym?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 35, 'Wtedy Filip otworzył swe usta i zaczynając od tego fragmentu Pisma, głosił mu Jezusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 36, 'A gdy jechali drogą, przybyli nad jakąś wodę. Wówczas eunuch powiedział: Oto woda; co stoi na przeszkodzie, żebym mógł być ochrzczony?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 37, 'I powiedział Filip: Jeśli wierzysz z całego serca, możesz. A on odpowiedział: Wierzę, że Jezus Chrystus jest Synem Bożym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 38, 'Kazał więc zatrzymać wóz. Obaj, Filip i eunuch, zeszli do wody i ochrzcił go.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 39, 'A gdy wyszli z wody, Duch Pański porwał Filipa i eunuch go więcej nie widział, ale jechał swoją drogą, radując się.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 40, 'Filip zaś znalazł się w Azocie, a obchodząc wszystkie miasta, głosił ewangelię, aż dotarł do Cezarei.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 1, 'A Saul, dysząc jeszcze groźbą i chęcią mordu wobec uczniów Pana, poszedł do najwyższego kapłana;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 2, 'I prosił go o listy do synagog w Damaszku, aby mógł, jeśliby znalazł tam zwolenników tej drogi, zarówno mężczyzn, jak i kobiety, przyprowadzić ich związanych do Jerozolimy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 3, 'A gdy jadąc, zbliżał się do Damaszku, nagle olśniła go światłość z nieba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 4, 'Upadł na ziemię i usłyszał głos, który mówił do niego: Saulu, Saulu, dlaczego mnie prześladujesz?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 5, 'Wtedy zapytał: Kim jesteś, Panie? A Pan odpowiedział: Ja jestem Jezus, którego ty prześladujesz. Trudno ci wierzgać przeciw ościeniowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 6, 'A Saul, drżąc i bojąc się, powiedział: Panie, co chcesz, abym zrobił? A Pan do niego: Wstań i idź do miasta, a tam ci powiedzą, co masz robić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 7, 'A mężczyźni, którzy byli z nim w drodze, stanęli oniemiali. Słyszeli bowiem głos, lecz nikogo nie widzieli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 8, 'I podniósł się Saul z ziemi, a gdy otworzył oczy, nikogo nie mógł widzieć. Wtedy wzięli go za rękę i zaprowadzili do Damaszku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 9, 'Trzy dni nic nie widział i nie jadł ani nie pił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 10, 'A w Damaszku był pewien uczeń, imieniem Ananiasz. I powiedział do niego Pan w widzeniu: Ananiaszu! A on odpowiedział: Oto ja, Panie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 11, 'A Pan powiedział do niego: Wstań i idź na ulicę, którą nazywają Prostą, i zapytaj w domu Judy o Saula z Tarsu, oto bowiem się modli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 12, 'I ujrzał w widzeniu człowieka imieniem Ananiasz, wchodzącego i kładącego na nim rękę, aby odzyskał wzrok.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 13, 'Ananiasz zaś odpowiedział: Panie, słyszałem od wielu, ile złego wyrządził ten człowiek twoim świętym w Jerozolimie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 14, 'Tutaj także ma władzę od najwyższych kapłanów uwięzić wszystkich, którzy wzywają twego imienia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 15, 'Lecz Pan powiedział do niego: Idź, bo on jest moim wybranym naczyniem, aby zanieść moje imię do pogan, królów i synów Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 16, 'Ja bowiem pokażę mu, jak wiele musi wycierpieć dla mego imienia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 17, 'Wtedy Ananiasz poszedł, wszedł do domu, położył na nim ręce i powiedział: Saulu, bracie, Pan mnie posłał – Jezus, który ci się ukazał w drodze, którą jechałeś – żebyś odzyskał wzrok i został napełniony Duchem Świętym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 18, 'I natychmiast spadły z jego oczu jakby łuski, i zaraz przejrzał, wstał i został ochrzczony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 19, 'A gdy zjadł, odzyskał siły. I Saul przebywał przez kilka dni z uczniami, którzy byli w Damaszku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 20, 'I zaraz w synagogach zaczął głosić Chrystusa, że on jest Synem Bożym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 21, 'A wszyscy, którzy go słuchali, ze zdziwieniem pytali: Czy to nie jest ten, który w Jerozolimie tępił tych, którzy wzywali tego imienia, i przybył tu po to, aby ich związać i zaprowadzić do naczelnych kapłanów?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 22, 'A Saul coraz bardziej się wzmacniał i wprawiał w zakłopotanie Żydów, którzy mieszkali w Damaszku, dowodząc, że ten jest Chrystusem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 23, 'A po upływie wielu dni Żydzi postanowili go zabić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 24, 'Saul jednak dowiedział się o ich zasadzce. A strzegli bram we dnie i w nocy, aby go zabić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 25, 'Lecz uczniowie zabrali go w nocy i spuścili w koszu po sznurze przez mur.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 26, 'A gdy Saul przybył do Jerozolimy, usiłował przyłączyć się do uczniów, ale wszyscy się go bali, nie wierząc, że jest uczniem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 27, 'Lecz Barnaba przyjął go, zaprowadził do apostołów i opowiedział im, jak on w drodze ujrzał Pana, który mówił do niego, i jak w Damaszku z odwagą głosił w imieniu Jezusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 28, 'I przebywał z nimi w Jerozolimie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 29, 'Z odwagą też mówił w imieniu Pana Jezusa i rozprawiał z hellenistami, a oni usiłowali go zabić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 30, 'Bracia jednak dowiedzieli się o tym, wyprawili go do Cezarei i odesłali do Tarsu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 31, 'A tak kościoły w całej Judei, Galilei i Samarii cieszyły się pokojem, budując się i żyjąc w bojaźni Pańskiej, i rozrastały się przez pociechę Ducha Świętego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 32, 'I stało się, gdy Piotr odwiedzał wszystkich, że przyszedł też do świętych, którzy mieszkali w Liddzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 33, 'Spotkał tam pewnego człowieka imieniem Eneasz, który był sparaliżowany i od ośmiu lat leżał w łóżku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 34, 'I powiedział mu Piotr: Eneaszu, Jezus Chrystus cię uzdrawia. Wstań i zaściel swoje łóżko. I natychmiast wstał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 35, 'A wszyscy mieszkańcy Liddy i Saronu widzieli go i nawrócili się do Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 36, 'Mieszkała też w Jafie pewna uczennica o imieniu Tabita, co znaczy Dorkas. Jej życie wypełnione było dobrymi uczynkami i udzielaniem jałmużny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 37, 'I stało się w tych dniach, że zachorowała i umarła. Obmyto ją i położono w sali na piętrze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 38, 'A ponieważ Lidda leży blisko Jafy, gdy uczniowie usłyszeli, że jest tam Piotr, posłali do niego dwóch ludzi, prosząc, aby nie zwlekał z przyjściem do nich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 39, 'Wtedy Piotr wstał i poszedł z nimi, a gdy przyszedł, wprowadzili go do sali na piętrze. Obstąpiły go wszystkie wdowy, płacząc i pokazując tuniki i płaszcze, które Dorkas im robiła, gdy była z nimi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 40, 'A Piotr wygonił wszystkich, klęknął i modlił się. Potem zwrócił się do zmarłej i powiedział: Tabito, wstań! A ona otworzyła oczy i zobaczywszy Piotra, usiadła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 41, 'On podał jej rękę i podniósł ją, a zawoławszy świętych i wdowy, pokazał ją żywą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 42, 'I rozniosło się to po całej Jafie, i wielu uwierzyło w Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 43, 'Piotr zaś został przez wiele dni w Jafie u niejakiego Szymona, garbarza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 1, 'A w Cezarei był pewien człowiek imieniem Korneliusz, setnik z oddziału zwanego Italskim;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 2, 'Pobożny i bojący się Boga wraz z całym swoim domem. Dawał on wielkie jałmużny ludowi i zawsze modlił się do Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 3, 'Około dziewiątej godziny dnia ujrzał wyraźnie w widzeniu anioła Boga, który przyszedł do niego i powiedział: Korneliuszu!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 4, 'A on uważnie patrzył na niego i będąc przestraszonym, zapytał: Co, Panie? I odpowiedział mu: Twoje modlitwy i jałmużny dotarły przed oblicze Boga jako przypomnienie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 5, 'Dlatego teraz poślij mężczyzn do Jafy i sprowadź Szymona, zwanego Piotrem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 6, 'Zatrzymał się on u pewnego Szymona, garbarza, który ma dom nad morzem. On ci powie, co masz robić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 7, 'A gdy anioł, który mówił z Korneliuszem, odszedł, ten zawołał dwóch swoich sług i pobożnego żołnierza spośród tych, którzy stale mu posługiwali;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 8, 'I opowiedziawszy im wszystko, posłał ich do Jafy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 9, 'A nazajutrz, gdy byli w drodze i zbliżali się do miasta, około godziny szóstej Piotr wszedł na dach, aby się modlić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 10, 'A będąc głodnym, chciał coś zjeść. Gdy zaś przygotowywano mu posiłek, wpadł w zachwycenie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 11, 'Zobaczył otwarte niebo i zstępujący na niego jakiś przedmiot, podobny do wielkiego płótna, związany ze sobą czterema końcami i spuszczany ku ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 12, 'Były w nim wszelkie czworonożne zwierzęta ziemskie, bestie, gady i ptaki nieba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 13, 'I odezwał się do niego głos: Wstań, Piotrze, zabijaj i jedz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 14, 'A Piotr odpowiedział: Żadną miarą, Panie, bo nigdy nie jadłem niczego pospolitego lub nieczystego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 15, 'Wtedy znowu, po raz drugi dobiegł go głos: Tego, co Bóg oczyścił, ty nie uważaj za nieczyste.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 16, 'I stało się tak trzy razy. Wówczas ten przedmiot został z powrotem wzięty do nieba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 17, 'A gdy Piotr zastanawiał się, co ma oznaczać widzenie, które miał, oto mężczyźni wysłani przez Korneliusza, dopytawszy się o dom Szymona, stanęli przed bramą;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 18, 'I zawołali, pytając, czy tam przebywa Szymon, zwany Piotrem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 19, 'A gdy Piotr rozmyślał o tym widzeniu, powiedział do niego Duch: Szukają cię trzej mężczyźni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 20, 'Dlatego wstań, zejdź i idź z nimi bez wahania, bo ja ich posłałem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 21, 'Wtedy Piotr zszedł do mężczyzn, którzy zostali do niego posłani przez Korneliusza, i powiedział: Ja jestem tym, którego szukacie. Z jakiego powodu przyszliście?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 22, 'A oni odpowiedzieli: Setnik Korneliusz, człowiek sprawiedliwy i bojący się Boga, mający dobre świadectwo od całego narodu żydowskiego, w widzeniu otrzymał przez świętego anioła polecenie, aby cię wezwał do swego domu i wysłuchał twoich słów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 23, 'Wtedy zawołał ich do domu i udzielił gościny. A następnego dnia Piotr wyruszył z nimi i niektórzy bracia z Jafy towarzyszyli mu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 24, 'A nazajutrz weszli do Cezarei. Korneliusz zaś czekał na nich, zwoławszy swoich krewnych i bliskich przyjaciół.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 25, 'A gdy Piotr wchodził, Korneliusz wyszedł mu naprzeciw, padł mu do nóg i oddał mu pokłon.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 26, 'Lecz Piotr podniósł go, mówiąc: Wstań, ja też jestem człowiekiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 27, 'A rozmawiając z nim, wszedł i zastał wielu zebranych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 28, 'I powiedział do nich: Wiecie, że nie wolno Żydowi przestawać z cudzoziemcem albo przychodzić do niego. Lecz Bóg mi pokazał, żebym żadnego człowieka nie nazywał pospolitym lub nieczystym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 29, 'Dlatego też, będąc wezwany, przyszedłem bez sprzeciwu. Pytam więc: Dlaczego mnie wezwaliście?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 30, 'A Korneliusz odpowiedział: Cztery dni temu pościłem aż do tej godziny, a gdy o godzinie dziewiątej modliłem się w swoim domu, stanął przede mną pewien mąż w jasnej szacie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 31, 'I powiedział: Korneliuszu, twoja modlitwa została wysłuchana, a twoje jałmużny dotarły przed oblicze Boga jako przypomnienie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 32, 'Dlatego poślij do Jafy i wezwij Szymona, zwanego Piotrem. Zatrzymał się on w domu Szymona, garbarza, nad morzem. Gdy przyjdzie, będzie z tobą mówić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 33, 'Natychmiast więc posłałem po ciebie, a ty dobrze zrobiłeś, że przyszedłeś. A teraz jesteśmy tu wszyscy obecni przed Bogiem, aby słuchać wszystkiego, co ci Bóg nakazał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 34, 'Wtedy Piotr otworzył usta i powiedział: Prawdziwie dostrzegam, że Bóg nie ma względu na osoby;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 35, 'Ale w każdym narodzie miły jest mu ten, kto się go boi i czyni to, co sprawiedliwe.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 36, 'A jeśli chodzi o słowo, które posłał synom Izraela, zwiastując pokój przez Jezusa Chrystusa, który jest Panem wszystkich;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 37, 'Wy wiecie, co się działo w całej Judei, począwszy od Galilei, po chrzcie, który głosił Jan;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 38, 'Jak Bóg namaścił Duchem Świętym i mocą Jezusa z Nazaretu, który chodził, czyniąc dobrze i uzdrawiając wszystkich opanowanych przez diabła, bo Bóg był z nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 39, 'A my jesteśmy świadkami tego wszystkiego, co czynił w ziemi judzkiej i w Jerozolimie. Jego to zabili, zawiesiwszy na drzewie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 40, 'Jego też wskrzesił Bóg trzeciego dnia i sprawił, żeby się objawił;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 41, 'Nie całemu ludowi, ale świadkom przedtem wybranym przez Boga, nam, którzy z nim jedliśmy i piliśmy po jego zmartwychwstaniu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 42, 'Nakazał nam też głosić ludowi i świadczyć, że on jest ustanowionym przez Boga sędzią żywych i umarłych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 43, 'Temu wszyscy prorocy wydają świadectwo, że przez jego imię każdy, kto w niego wierzy, otrzyma przebaczenie grzechów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 44, 'A gdy jeszcze Piotr mówił te słowa, Duch Święty zstąpił na wszystkich słuchających tej mowy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 45, 'I zdziwili się ci wierzący pochodzący z obrzezania, którzy przyszli z Piotrem, że dar Ducha Świętego został wylany także na pogan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 46, 'Słyszeli ich bowiem mówiących językami i wielbiących Boga. Wtedy Piotr się odezwał:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 47, 'Czy ktoś może odmówić wody, żeby byli ochrzczeni ci, którzy otrzymali Ducha Świętego jak i my?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 48, 'I nakazał ochrzcić ich w imię Pana. I prosili go, aby u nich został kilka dni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 1, 'Apostołowie i bracia, którzy byli w Judei, usłyszeli, że również poganie przyjęli słowo Boże.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 2, 'A gdy Piotr przybył do Jerozolimy, spierali się z nim ci, którzy pochodzili z obrzezania;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 3, 'Mówiąc: Wszedłeś do ludzi nieobrzezanych i jadłeś z nimi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 4, 'Wtedy Piotr zaczął po kolei im wyjaśniać:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 5, 'Będąc w mieście Jafie, modliłem się i w zachwyceniu miałem widzenie – jakiś przedmiot zstępujący, jakby wielkie płótno, za cztery rogi uwiązane i spuszczone z nieba, i dotarło aż do mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 6, 'Wpatrzywszy się w nie uważnie, przyjrzałem się i zobaczyłem czworonożne zwierzęta ziemskie, bestie, gady i ptaki nieba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 7, 'I usłyszałem głos mówiący do mnie: Wstań, Piotrze, zabijaj i jedz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 8, 'I odpowiedziałem: Żadną miarą, Panie, bo nigdy niczego pospolitego lub nieczystego nie wziąłem do ust.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 9, 'Wtedy głos z nieba odezwał się po raz drugi: Tego, co Bóg oczyścił, nie uważaj za nieczyste.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 10, 'A to się stało trzy razy, po czym to wszystko zostało wciągnięte z powrotem do nieba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 11, 'I zaraz trzej mężczyźni posłani do mnie z Cezarei stanęli przed domem, w którym byłem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 12, 'I powiedział mi Duch, abym z nimi poszedł bez wahania. Szło też ze mną tych sześciu braci i weszliśmy do domu tego człowieka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 13, 'On nam opowiedział, jak ujrzał w swoim domu anioła, który stanął i powiedział do niego: Poślij ludzi do Jafy i przywołaj Szymona, zwanego Piotrem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 14, 'On ci powie słowa, przez które będziesz zbawiony, ty i cały twój dom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 15, 'A gdy zacząłem mówić, zstąpił na nich Duch Święty, tak jak na nas na początku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 16, 'I przypomniałem słowo Pana, gdy powiedział: Jan chrzcił wodą, ale wy będziecie ochrzczeni Duchem Świętym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 17, 'Jeśli więc Bóg dał im ten sam dar co nam, którzy uwierzyliśmy w Pana Jezusa Chrystusa, kim ja jestem, abym mógł zabronić Bogu?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 18, 'A usłyszawszy to, uspokoili się i chwalili Boga, mówiąc: A więc i poganom dał Bóg pokutę ku życiu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 19, 'Lecz ci, których rozproszyło prześladowanie, jakie wybuchło z powodu Szczepana, dotarli aż do Fenicji, na Cypr i do Antiochii, nie głosząc słowa Bożego nikomu, tylko Żydom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 20, 'A niektórzy z nich, mężczyźni z Cypru i Cyreny, gdy przybyli do Antiochii, mówili do hellenistów, głosząc Pana Jezusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 21, 'I była z nimi ręka Pana, a wielka ich liczba uwierzyła i nawróciła się do Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 22, 'I wieść o nich dotarła do uszu kościoła, który był w Jerozolimie. I posłano Barnabę aż do Antiochii.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 23, 'Gdy tam przybył i ujrzał łaskę Boga, uradował się i zachęcał wszystkich, aby zgodnie z postanowieniem serca trwali przy Panu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 24, 'Był to bowiem mąż dobry, pełen Ducha Świętego i wiary. I przybyło Panu mnóstwo ludzi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 25, 'Potem Barnaba udał się do Tarsu, aby szukać Saula.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 26, 'A gdy go znalazł, przyprowadził go do Antiochii. Przez cały rok zbierali się z tym kościołem i nauczali wielu ludzi. W Antiochii też po raz pierwszy uczniów nazwano chrześcijanami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 27, 'A w tych dniach przybyli z Jerozolimy do Antiochii prorocy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 28, 'I jeden z nich, imieniem Agabos, powstał i oznajmił przez Ducha, że w całej ziemi nastanie wielki głód. Nastał on za cesarza Klaudiusza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 29, 'Wtedy uczniowie, każdy z nich według swoich możliwości, postanowili posłać pomoc do braci, którzy mieszkali w Judei.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 30, 'Tak też zrobili, posyłając ją starszym przez ręce Barnaby i Saula.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 1, 'W tym czasie król Herod zaczął gnębić niektórych członków kościoła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 2, 'I zabił mieczem Jakuba, brata Jana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 3, 'Widząc, że to podobało się Żydom, postanowił schwytać także Piotra. A były to dni Przaśników.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 4, 'Kiedy go schwytał, wtrącił go do więzienia i oddał pod straż szesnastu żołnierzom, zamierzając po święcie Paschy wydać go ludowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 5, 'Strzeżono więc Piotra w więzieniu, a kościół nieustannie modlił się za niego do Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 6, 'A tej nocy, kiedy Herod miał go wydać, Piotr spał między dwoma żołnierzami, związany dwoma łańcuchami, a przed drzwiami strażnicy strzegli więzienia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 7, 'Wtedy zjawił się anioł Pana i w więzieniu zajaśniało światło. Trącił Piotra w bok i obudził go, mówiąc: Wstań szybko. I opadły łańcuchy z jego rąk.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 8, 'I powiedział do niego anioł: Przepasz się i włóż sandały. Tak też zrobił. I powiedział mu: Narzuć płaszcz i chodź za mną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 9, 'Piotr więc wyszedł i udał się za nim, a nie wiedział, że to, co się działo za sprawą anioła, działo się naprawdę, lecz sądził, że to widzenie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 10, 'A gdy minęli pierwszą i drugą straż, doszli do żelaznej bramy, która prowadzi do miasta, a ta sama się przed nimi otworzyła. Kiedy wyszli i przeszli jedną ulicę, natychmiast anioł odstąpił od niego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 11, 'Kiedy Piotr doszedł do siebie, powiedział: Teraz wiem na pewno, że Pan posłał swego anioła i wyrwał mnie z ręki Heroda i z tego wszystkiego, czego oczekiwał lud żydowski.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 12, 'Gdy to sobie uświadomił, przyszedł do domu Marii, matki Jana, którego nazywano Markiem, gdzie wielu zebrało się na modlitwie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 13, 'I zapukał Piotr do drzwi w bramie, i wyszła dziewczyna imieniem Rode, aby nasłuchiwać:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 14, 'Gdy poznała głos Piotra, z radości nie otworzyła bramy, lecz pobiegła i oznajmiła, że Piotr stoi przed bramą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 15, 'A oni powiedzieli do niej: Oszalałaś! Jednak ona twierdziła, że tak jest istotnie. Odpowiedzieli: To jego anioł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 16, 'Piotr zaś nie przestał pukać. A gdy otworzyli, zobaczyli go i zdumieli się.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 17, 'A dawszy im ręką znak, aby zamilkli, opowiedział im, jak Pan wyprowadził go z więzienia, i powiedział: Powiadomcie o tym Jakuba i braci. Potem wyszedł i udał się w inne miejsce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 18, 'A gdy nastał dzień, powstało niemałe poruszenie wśród żołnierzy z powodu tego, co się stało z Piotrem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 19, 'Herod zaś poszukiwał go, a gdy go nie znalazł, przesłuchał strażników i kazał ich stracić. Potem wyjechał z Judei do Cezarei i tam mieszkał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 20, 'A Herod był bardzo zagniewany na mieszkańców Tyru i Sydonu. Lecz oni jednomyślnie przyszli do niego, zjednali sobie Blasta, podkomorzego królewskiego, i prosili o pokój, ponieważ ich kraj zaopatrywał się w żywność z ziem królewskich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 21, 'W wyznaczonym dniu Herod ubrany w szaty królewskie zasiadł na tronie i wygłosił do nich mowę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 22, 'A lud wołał: Głos Boga, a nie człowieka!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 23, 'W tej chwili uderzył go anioł Pana, dlatego że nie oddał chwały Bogu, i wyzionął ducha, stoczony przez robactwo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 24, 'A słowo Pana rozrastało się i rozmnażało.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 25, 'Barnaba zaś i Saul po wykonaniu posługi wrócili z Jerozolimy, zabierając ze sobą Jana, którego nazywano Markiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 1, 'A w kościele w Antiochii byli pewni prorocy i nauczyciele: Barnaba, Szymon, zwany Nigrem, Lucjusz Cyrenejczyk i Manaen, który wychowywał się z tetrarchą Herodem, i Saul.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 2, 'A gdy jawnie pełnili służbę Panu i pościli, powiedział im Duch Święty: Odłączcie mi Barnabę i Saula do dzieła, do którego ich powołałem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 3, 'Wtedy po poście i modlitwie nałożyli na nich ręce i wyprawili ich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 4, 'A oni, posłani przez Ducha Świętego, przybyli do Seleucji, a stamtąd odpłynęli na Cypr.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 5, 'Gdy dotarli do Salaminy, głosili słowo Boże w synagogach żydowskich. Mieli też ze sobą Jana do pomocy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 6, 'A kiedy przeszli wyspę aż do Pafos, spotkali tam pewnego czarownika, fałszywego proroka, Żyda imieniem Bar-Jezus;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 7, 'Który należał do otoczenia prokonsula Sergiusza Pawła, człowieka roztropnego. On to, wezwawszy Barnabę i Saula, pragnął słuchać słowa Bożego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 8, 'Lecz sprzeciwił się im Elimas, czarownik – tak bowiem tłumaczy się jego imię – usiłując odwieść prokonsula od wiary.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 9, 'Wtedy Saul, zwany też Pawłem, napełniony Duchem Świętym, spojrzał na niego uważnie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 10, 'I powiedział: O, synu diabła, pełny wszelkiego podstępu i przewrotności, nieprzyjacielu wszelkiej sprawiedliwości! Czy nie przestaniesz wykrzywiać prostych dróg Pana?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 11, 'Oto teraz ręka Pana na tobie: oślepniesz i nie będziesz widział słońca przez pewien czas. I natychmiast ogarnęły go mrok i ciemność, i chodząc wkoło, szukał kogoś, kto by go poprowadził za rękę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 12, 'Wtedy prokonsul, widząc, co się stało, uwierzył, zdumiewając się nauką Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 13, 'A Paweł i jego towarzysze opuścili Pafos i przybyli do Perge w Pamfilii. Jan zaś odłączył się od nich i wrócił do Jerozolimy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 14, 'A oni opuścili Perge, dotarli do Antiochii Pizydyjskiej, a w dzień szabatu weszli do synagogi i usiedli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 15, 'Po odczytaniu Prawa i Proroków przełożeni synagogi posłali do nich z prośbą: Mężowie bracia, jeśli macie jakieś słowo zachęty dla ludu, to mówcie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 16, 'Wtedy Paweł wstał, dał im ręką znak i powiedział: Mężowie Izraelici i wy, którzy boicie się Boga, słuchajcie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 17, 'Bóg tego ludu Izraela wybrał naszych ojców i wywyższył lud, gdy był na obczyźnie w ziemi Egiptu i wyprowadził go z niej wyciągniętym ramieniem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 18, 'Przez około czterdzieści lat znosił ich obyczaje na pustyni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 19, 'A gdy wytępił siedem narodów w ziemi Kanaan, rozdzielił przez losowanie między nich ich ziemię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 20, 'A potem przez około czterysta pięćdziesiąt lat dawał im sędziów, aż do proroka Samuela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 21, 'Później prosili o króla. I na czterdzieści lat dał im Bóg Saula, syna Kisza, męża z pokolenia Beniamina.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 22, 'A kiedy go odrzucił, wzbudził im na króla Dawida, o którym dał świadectwo w słowach: Znalazłem Dawida, syna Jessego, męża według mego serca, który wypełni całą moją wolę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 23, 'Z jego potomstwa, zgodnie z obietnicą, Bóg wzbudził Izraelowi Zbawiciela, Jezusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 24, 'Przed jego przyjściem Jan głosił chrzest pokuty całemu ludowi Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 25, 'A gdy Jan dopełniał swego biegu, powiedział: Za kogo mnie uważacie? Nie jestem nim. Ale idzie za mną ten, któremu nie jestem godny rozwiązać obuwia na nogach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 26, 'Mężowie bracia, synowie rodu Abrahama i ci z was, którzy boją się Boga, do was zostało posłane słowo o tym zbawieniu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 27, 'Mieszkańcy Jerozolimy bowiem i ich przełożeni, nie znając tego Jezusa ani głosów proroków, które są czytane w każdy szabat, wypełnili je, osądzając go.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 28, 'Chociaż nie znaleźli w nim żadnego powodu, żeby skazać go na śmierć, prosili Piłata, aby go stracił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 29, 'A gdy wykonali wszystko, co było o nim napisane, zdjęli go z drzewa i złożyli w grobie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 30, 'Lecz Bóg wskrzesił go z martwych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 31, 'A on przez wiele dni był widziany przez tych, którzy razem z nim przyszli z Galilei do Jerozolimy, a teraz są jego świadkami przed ludem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 32, 'I my głosimy wam dobrą nowinę o obietnicy złożonej ojcom;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 33, 'Że Bóg wypełnił ją wobec nas, ich dzieci, wskrzeszając Jezusa, jak też jest napisane w psalmie drugim: Ty jesteś moim Synem, ja ciebie dziś zrodziłem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 34, 'A to, że go wskrzesił z martwych, aby już nigdy nie uległ zniszczeniu, tak wyraził: Dam wam pewne miłosierdzia Dawida.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 35, 'Dlatego w innym miejscu mówi: Nie dasz twemu Świętemu doznać zniszczenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 36, 'Dawid bowiem za swego pokolenia służył woli Boga, zasnął i został przyłączony do swoich ojców, i doznał zniszczenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 37, 'Lecz ten, którego Bóg wskrzesił, nie doznał zniszczenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 38, 'Niech więc będzie wam wiadomo, mężowie bracia, że przez niego zwiastuje się wam przebaczenie grzechów;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 39, 'I przez niego każdy, kto uwierzy, jest usprawiedliwiony we wszystkim, w czym nie mogliście być usprawiedliwieni przez Prawo Mojżesza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 40, 'Uważajcie więc, aby nie spotkało was to, co zostało powiedziane u Proroków:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 41, 'Patrzcie, szydercy, dziwcie się i przepadnijcie, bo ja za waszych dni dokonuję dzieła, w które nie uwierzycie, choćby wam ktoś o nim opowiedział.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 42, 'A kiedy wychodzili z synagogi żydowskiej, poganie prosili ich, aby również w następny szabat głosili im te same słowa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 43, 'Kiedy zgromadzenie się rozeszło, wielu Żydów i pobożnych prozelitów poszło za Pawłem i Barnabą, którzy w rozmowie radzili im, aby trwali w łasce Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 44, 'A w następny szabat niemal całe miasto zebrało się, aby słuchać słowa Bożego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 45, 'Kiedy Żydzi zobaczyli tłumy, pełni zawiści sprzeciwiali się słowom Pawła, występując przeciwko nim i bluźniąc.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 46, 'A Paweł i Barnaba powiedzieli odważnie: Wam najpierw miało być zwiastowane słowo Boże. Skoro jednak je odrzucacie i uważacie się za niegodnych życia wiecznego, zwracamy się do pogan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 47, 'Tak bowiem nakazał nam Pan: Ustanowiłem cię światłością dla pogan, abyś był zbawieniem aż po krańce ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 48, 'Kiedy poganie to usłyszeli, radowali się i wielbili słowo Pańskie, a uwierzyli wszyscy, którzy byli przeznaczeni do życia wiecznego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 49, 'I słowo Pańskie rozchodziło się po całej krainie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 50, 'A Żydzi podburzali pobożne i poważane kobiety oraz znaczących obywateli miasta, wzniecili prześladowanie Pawła i Barnaby i wypędzili ich ze swoich granic.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 51, 'A oni, strząsnąwszy na nich pył ze swoich nóg, przyszli do Ikonium.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 52, 'Uczniowie zaś byli pełni radości i Ducha Świętego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 1, 'W Ikonium również weszli do synagogi żydowskiej i mówili tak, że uwierzyła wielka liczba Żydów i Greków.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 2, 'Lecz Żydzi, którzy nie uwierzyli, podburzyli i rozjątrzyli serca pogan przeciwko braciom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 3, 'I byli tam przez długi czas, odważnie mówiąc w Panu, który dawał świadectwo słowu swojej łaski, sprawiając, że przez ich ręce dokonywały się znaki i cuda.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 4, 'I mieszkańcy miasta podzielili się: jedni byli z Żydami, a drudzy z apostołami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 5, 'Kiedy jednak wszczął się rozruch zarówno wśród pogan, jak i Żydów wraz z przełożonymi, i chcieli ich znieważyć, i ukamienować;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 6, 'Dowiedzieli się o tym i uciekli do miast Likaonii: do Listry i Derbe oraz w ich okolice;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 7, 'I tam głosili ewangelię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 8, 'A w Listrze był pewien człowiek o bezwładnych nogach, chromy już w łonie swojej matki i nigdy nie chodził.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 9, 'Słuchał on przemawiającego Pawła, który przyglądając mu się uważnie i widząc, że ma wiarę, aby zostać uzdrowionym;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 10, 'Powiedział donośnym głosem: Stań prosto na nogach! A on zerwał się i zaczął chodzić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 11, 'A ludzie, widząc, co uczynił Paweł, zaczęli wołać po likaońsku: Bogowie przybrali postać ludzi i zstąpili do nas!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 12, 'I nazwali Barnabę Jowiszem, a Pawła Merkurym, ponieważ on był głównym mówcą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 13, 'Wtedy kapłan ze świątyni Jowisza, która była przed miastem, przyprowadził do wrót woły i wieńce i razem z ludem chciał złożyć ofiarę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 14, 'Gdy usłyszeli o tym apostołowie Barnaba i Paweł, rozdarli swoje szaty i wpadli między tłum, wołając;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 15, 'Ludzie, co robicie? My też jesteśmy ludźmi, podlegamy tym samym doznaniom co wy. Głosimy wam, abyście się odwrócili od tych marności do Boga żywego, który stworzył niebo, ziemię, morze i wszystko, co się w nich znajduje.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 16, 'Za czasów minionych pozwalał on, aby wszystkie narody chodziły własnymi drogami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 17, 'Nie przestawał jednak dawać o sobie świadectwa, czyniąc dobrze. Zsyłał nam z nieba deszcz i urodzajne lata, karmił nas i napełniał radością nasze serca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 18, 'Tymi słowami ledwie powstrzymali lud od złożenia im ofiary.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 19, 'Tymczasem z Antiochii i Ikonium nadeszli Żydzi, którzy namówiwszy lud, ukamienowali Pawła i wywlekli go za miasto, myśląc, że umarł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 20, 'Lecz gdy otoczyli go uczniowie, podniósł się i wrócił do miasta, a nazajutrz udał się z Barnabą do Derbe.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 21, 'Kiedy głosili ewangelię temu miastu i pozyskali wielu uczniów, wrócili do Listry, Ikonium i do Antiochii;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 22, 'Umacniając dusze uczniów i zachęcając do trwania w wierze, mówili, że przez wiele utrapień musimy wejść do królestwa Bożego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 23, 'A gdy w każdym kościele ustanowili starszych, modląc się i poszcząc, powierzyli ich Panu, w którego uwierzyli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 24, 'Potem przeszli przez Pizydię i przybyli do Pamfilii.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 25, 'I opowiedziawszy słowo Boże w Perge, zeszli do Attalii.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 26, 'Stamtąd popłynęli do Antiochii, gdzie przedtem zostali poruczeni łasce Boga do dzieła, które wykonali.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 27, 'A gdy tam przyszli i zebrali kościół, opowiedzieli, co Bóg przez nich uczynił i jak otworzył poganom drzwi wiary.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 28, 'I mieszkali tam dość długo z uczniami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 1, 'A niektórzy przybysze z Judei nauczali braci: Jeśli nie zostaniecie obrzezani według zwyczaju Mojżesza, nie możecie być zbawieni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 2, 'Kiedy doszło do niemałych sporów i zatargów między nimi a Pawłem i Barnabą, postanowili, że Paweł i Barnaba oraz jeszcze kilku z nich pójdą w sprawie tego sporu do apostołów i starszych do Jerozolimy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 3, 'Wyprawieni przez kościół, szli przez Fenicję i Samarię, opowiadając o nawróceniu pogan, czym sprawili wielką radość wszystkim braciom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 4, 'A gdy przybyli do Jerozolimy, zostali przyjęci przez kościół, apostołów i starszych. I opowiedzieli o wszystkim, czego Bóg przez nich dokonał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 5, 'Lecz niektórzy ze stronnictwa faryzeuszy, którzy uwierzyli, powstali i powiedzieli: Trzeba ich obrzezać i nakazać, żeby zachowywali Prawo Mojżesza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 6, 'Apostołowie i starsi zebrali się więc, aby rozstrzygnąć tę sprawę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 7, 'A gdy był wielki spór o to, Piotr powstał i powiedział do nich: Mężowie bracia, wiecie, że Bóg już dawno wybrał mnie spośród was, aby z moich ust poganie usłyszeli słowa ewangelii i uwierzyli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 8, 'A Bóg, który zna serca, wydał im świadectwo, dając im Ducha Świętego, tak samo jak nam.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 9, 'I nie uczynił żadnej różnicy między nami a nimi, oczyszczając przez wiarę ich serca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 10, 'Dlaczego więc teraz wystawiacie Boga na próbę, wkładając na kark uczniów jarzmo, którego ani nasi ojcowie, ani my nie mogliśmy udźwignąć?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 11, 'Lecz wierzymy, że przez łaskę Pana Jezusa Chrystusa będziemy zbawieni, tak samo i oni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 12, 'I całe zgromadzenie umilkło, a potem słuchali Barnaby i Pawła, którzy opowiadali, jak wielkie znaki i cuda Bóg uczynił przez nich wśród pogan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 13, 'A gdy i oni umilkli, odezwał się Jakub: Mężowie bracia, posłuchajcie mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 14, 'Szymon powiedział, jak najpierw Bóg wejrzał na pogan, aby z nich wybrać lud dla swego imienia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 15, 'A z tym się zgadzają słowa proroków, jak jest napisane:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 16, 'Potem powrócę i odbuduję upadły przybytek Dawida; odbuduję jego ruiny i wzniosę go;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 17, 'Aby ludzie, którzy pozostali, szukali Pana, i wszystkie narody, nad którymi wzywane jest moje imię – mówi Pan, który to wszystko sprawia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 18, 'Znane są Bogu od wieków wszystkie jego sprawy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 19, 'Dlatego uważam, że nie należy czynić trudności tym spośród pogan, którzy się nawracają do Boga;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 20, 'Ale napisać im, aby wstrzymywali się od splugawienia bożków, od nierządu, od tego, co uduszone, i od krwi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 21, 'Mojżesz bowiem od dawien dawna ma w każdym mieście takich, którzy go głoszą, gdyż w synagogach co szabat czytają go.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 22, 'Wtedy apostołowie i starsi wraz z całym kościołem uznali za słuszne posłać do Antiochii z Pawłem i Barnabą wybranych spośród siebie ludzi: Judę, zwanego Barsabą, i Sylasa, przodujących wśród braci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 23, 'Posłali przez nich takie pismo: Apostołowie, starsi i bracia przesyłają pozdrowienia braciom pochodzącym z pogan, którzy są w Antiochii, Syrii i Cylicji.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 24, 'Ponieważ słyszeliśmy, że pewni ludzie wyszli od nas i zaniepokoili was słowami, i wzburzyli wasze dusze, mówiąc, że musicie zostać obrzezani i zachowywać prawo, czego im nie przykazaliśmy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 25, 'Zgromadzeni jednomyślnie, postanowiliśmy posłać do was wybranych ludzi wraz z naszymi umiłowanymi Barnabą i Pawłem;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 26, 'Ludźmi, którzy poświęcili swe życie dla imienia naszego Pana Jezusa Chrystusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 27, 'Dlatego posłaliśmy Judę i Sylasa, którzy powtórzą wam ustnie to samo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 28, 'Uznał bowiem Duch Święty za słuszne, i my też, nie nakładać na was żadnego ciężaru oprócz tego, co konieczne.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 29, 'Wstrzymujcie się od ofiar składanych bożkom, od krwi, od tego, co uduszone, i od nierządu. Dobrze uczynicie, jeśli będziecie się tego wystrzegać. Bywajcie zdrowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 30, 'Tak więc oni, będąc odprawieni, przybyli do Antiochii, zwołali zgromadzenie i oddali list.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 31, 'Gdy go przeczytali, uradowali się z tego pocieszania.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 32, 'A Juda i Sylas, którzy również byli prorokami, w licznych mowach zachęcali i umacniali braci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 33, 'A gdy przebywali tam jakiś czas, zostali odprawieni z życzeniem pokoju od braci do apostołów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 34, 'Lecz upodobało się Sylasowi tam pozostać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 35, 'Również Paweł i Barnaba przebywali w Antiochii, nauczając i głosząc z wieloma innymi słowo Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 36, 'Po kilku dniach Paweł powiedział do Barnaby: Wróćmy i odwiedźmy naszych braci we wszystkich miastach, w których głosiliśmy słowo Pańskie, aby zobaczyć, jak się mają.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 37, 'Barnaba chciał również wziąć ze sobą Jana, zwanego Markiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 38, 'Ale Paweł nie chciał zabrać ze sobą tego, który odszedł od nich w Pamfilii i nie uczestniczył z nimi w tej pracy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 39, 'I doszło między nimi do ostrej kłótni, tak że się rozdzielili: Barnaba wziął ze sobą Marka i popłynął na Cypr;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 40, 'Paweł zaś wybrał sobie Sylasa i wyruszył, polecony przez braci łasce Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 41, 'I przechodził Syrię i Cylicję, umacniając kościoły.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 1, 'Przybył do Derbe i Listry. A oto był tam pewien uczeń imieniem Tymoteusz, syn pewnej Żydówki, która uwierzyła, ojca natomiast Greka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 2, 'Bracia z Listry i Ikonium dawali o nim dobre świadectwo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 3, 'Paweł chciał go zabrać ze sobą, więc obrzezał go ze względu na Żydów, którzy mieszkali w tamtych stronach. Wszyscy bowiem wiedzieli, że jego ojciec był Grekiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 4, 'A gdy chodzili po miastach, przekazywali im nakazy ustanowione przez apostołów i starszych w Jerozolimie, których mieli przestrzegać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 5, 'I tak kościoły utwierdzały się w wierze i każdego dnia wzrastały liczebnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 6, 'Gdy przeszli Frygię i krainę galacką, Duch Święty zabronił im głosić słowo Boże w Azji.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 7, 'Gdy przybyli do Myzji, próbowali pójść do Bitynii, ale im Duch nie pozwolił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 8, 'Przeszli więc Myzję i zeszli do Troady.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 9, 'I w nocy Paweł miał widzenie: jakiś Macedończyk stał i prosił go: Przepraw się do Macedonii i pomóż nam!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 10, 'Zaraz po tym widzeniu staraliśmy się wyruszyć do Macedonii, będąc tego pewni, że Pan nas powołał, abyśmy im głosili ewangelię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 11, 'Odpłynąwszy więc z Troady, zdążaliśmy wprost do Samotraki, a nazajutrz do Neapolu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 12, 'Stamtąd zaś do Filippi, rzymskiej kolonii i głównego miasta tej części Macedonii, i zostaliśmy w tym mieście przez kilka dni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 13, 'A w dzień szabatu wyszliśmy za miasto nad rzekę, gdzie zwykle odbywały się modlitwy. Usiedliśmy i rozmawialiśmy z kobietami, które się tam zeszły.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 14, 'Przysłuchiwała się temu też pewna bogobojna kobieta, imieniem Lidia, z miasta Tiatyry, sprzedająca purpurę, której to serce otworzył Pan, aby uważnie słuchała tego, co mówił Paweł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 15, 'A gdy została ochrzczona razem ze swoim domem, poprosiła: Jeśli uznaliście mnie za wierną Panu, wejdźcie do mojego domu i zamieszkajcie w nim. I wymogła to na nas.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 16, 'I stało się, gdy szliśmy na modlitwę, że zabiegła nam drogę pewna dziewczyna, która miała ducha wieszczego i swoimi wróżbami przynosiła wielki dochód swoim panom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 17, 'A chodząc za Pawłem i za nami, wołała: Ci ludzie są sługami Boga Najwyższego i zwiastują nam drogę zbawienia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 18, 'A robiła to przez wiele dni. Lecz Paweł, bolejąc nad tym, odwrócił się i powiedział do ducha: Rozkazuję ci w imię Jezusa Chrystusa, abyś z niej wyszedł. I w tej chwili wyszedł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 19, 'Gdy jej panowie zobaczyli, że przepadła nadzieja ich zysku, schwytali Pawła i Sylasa, zawlekli ich na rynek przed władzę;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 20, 'Stawili ich przed pretorami i powiedzieli: Ci ludzie, którzy są Żydami, sieją zamęt w naszym mieście.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 21, 'I głoszą zwyczaje, których nam, jako Rzymianom, nie wolno przyjmować ani zachowywać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 22, 'I wystąpił tłum przeciwko nim, a pretorzy zdarli z nich szaty i kazali wychłostać ich rózgami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 23, 'Po wymierzeniu wielu razów wtrącili ich do więzienia, przykazując strażnikowi, żeby ich dobrze pilnował.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 24, 'Otrzymawszy taki rozkaz, wtrącił ich do wewnętrznego lochu, a ich nogi zakuł w dyby.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 25, 'O północy Paweł i Sylas modlili się i śpiewem chwalili Boga, a więźniowie słyszeli ich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 26, 'Nagle powstało silne trzęsienie ziemi, tak że zachwiały się fundamenty więzienia. I natychmiast otworzyły się wszystkie drzwi i wszystkim rozwiązały się więzy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 27, 'A gdy strażnik więzienia obudził się i zobaczył otwarte drzwi więzienia, dobył miecz i chciał się zabić, sądząc, że więźniowie pouciekali.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 28, 'Lecz Paweł zawołał donośnym głosem: Nie rób sobie nic złego, bo jesteśmy tu wszyscy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 29, 'Wtedy zażądał światła i wskoczył do środka, a drżąc, padł do nóg Pawła i Sylasa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 30, 'A wyprowadziwszy ich z więzienia, powiedział: Panowie, co mam czynić, abym był zbawiony?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 31, 'A oni odpowiedzieli: Uwierz w Pana Jezusa Chrystusa, a będziesz zbawiony, ty i twój dom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 32, 'I głosili słowo Pańskie jemu i wszystkim jego domownikom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 33, 'Tej samej godziny w nocy wziął ich ze sobą, obmył ich rany i natychmiast się ochrzcił, on i wszyscy jego domownicy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 34, 'Wprowadził ich do swego domu, zastawił przed nimi stół i weselił się, uwierzywszy Bogu z całym swoim domem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 35, 'Kiedy nastał dzień, pretorzy posłali służbę miejską ze słowami: Zwolnij tych ludzi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 36, 'I strażnik więzienia oznajmił Pawłowi: Pretorzy przysłali polecenie, żeby was wypuścić. Teraz więc wyjdźcie i idźcie w pokoju.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 37, 'Lecz Paweł powiedział do nich: Publicznie, bez sądu biczowali i wtrącili do więzienia nas, obywateli rzymskich, a teraz potajemnie nas wyrzucają? Nic z tego! Niech sami przyjdą i wyprowadzą nas.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 38, 'Słudzy miejscy przekazali te słowa pretorom. A gdy tamci usłyszeli, że są Rzymianami, przestraszyli się.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 39, 'Przyszli, przeprosili ich i wyprowadziwszy, prosili, aby opuścili miasto.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 40, 'Kiedy wyszli z więzienia, wstąpili do domu Lidii, a gdy zobaczyli się z braćmi, pocieszyli ich i odeszli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 1, 'A gdy przeszli Amfipolis i Apolonię, przybyli do Tesaloniki, gdzie była synagoga żydowska.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 2, 'Wtedy Paweł według swego zwyczaju wszedł do nich i przez trzy szabaty rozprawiał z nimi na podstawie Pisma;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 3, 'Wyjaśniając i nauczając, że Chrystus musiał cierpieć i powstać z martwych oraz: Ten Jezus, którego wam głoszę, jest Chrystusem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 4, 'I niektórzy z nich uwierzyli i przyłączyli się do Pawła i Sylasa, również mnóstwo pobożnych Greków i niemało znamienitych kobiet.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 5, 'Ale ci Żydzi, którzy nie uwierzyli, zdjęci zazdrością, dobrali sobie niektórych niegodziwych próżniaków, a kiedy zebrali dużą grupę, podburzyli miasto. Naszli dom Jazona i szukali ich, aby wyprowadzić ich przed lud.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 6, 'Gdy jednak ich nie znaleźli, zaciągnęli Jazona i niektórych braci przed przełożonych miasta, krzycząc: Oto ci, którzy cały świat wzburzyli, przyszli też tutaj;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 7, 'A Jazon ich przyjął. Oni wszyscy postępują wbrew dekretom cesarza, mówiąc, że jest inny król, Jezus.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 8, 'W ten sposób zaniepokoili lud i przełożonych miasta, którzy to słyszeli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 9, 'Ale po wzięciu poręczenia od Jazona i innych wypuścili ich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 10, 'Zaraz w nocy bracia wysłali Pawła i Sylasa do Berei. Kiedy tam przybyli, weszli do synagogi żydowskiej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 11, 'Ci byli szlachetniejsi od tych w Tesalonice, gdyż przyjęli słowo Boże z całą gotowością i codziennie badali Pisma, czy tak się sprawy mają.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 12, 'Wielu więc z nich uwierzyło, również niemało wpływowych greckich kobiet i mężczyzn.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 13, 'A gdy Żydzi z Tesaloniki dowiedzieli się, że i w Berei Paweł głosi słowo Boże, przyszli też tam i podburzali lud.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 14, 'Wtedy bracia natychmiast wysłali Pawła w drogę ku morzu, a Sylas i Tymoteusz tam zostali.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 15, 'Ci, którzy towarzyszyli Pawłowi, odprowadzili go aż do Aten i powrócili, otrzymawszy polecenie dla Sylasa i Tymoteusza, żeby jak najszybciej przyszli do niego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 16, 'A gdy Paweł czekał na nich w Atenach, burzył się w duchu na widok miasta oddanego bałwochwalstwu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 17, 'Rozprawiał więc w synagodze z Żydami i ludźmi pobożnymi oraz codziennie na rynku ze wszystkimi, których spotkał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 18, 'Wtedy niektórzy z filozofów epikurejskich i stoickich spierali się z nim. Jedni mówili: Co chce powiedzieć ten nowinkarz? A inni: Zdaje się, że jest zwiastunem obcych bogów. Głosił im bowiem Jezusa i zmartwychwstanie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 19, 'Zabrali go, zaprowadzili na Areopag i zapytali: Czy możemy się dowiedzieć, co to za nowa nauka, którą głosisz?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 20, 'Bo przynosisz jakieś rzeczy obce naszym uszom. Chcemy więc wiedzieć, o co właściwie chodzi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 21, '(A wszyscy Ateńczycy i mieszkający tam cudzoziemcy nie poświęcali czasu na nic innego, tylko na opowiadanie lub słuchanie czegoś nowego).');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 22, 'Wtedy Paweł stanął pośrodku Areopagu i powiedział: Mężowie ateńscy, widzę, że pod każdym względem jesteście nadzwyczaj religijni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 23, 'Przechadzając się bowiem i przypatrując waszym świętościom, znalazłem też ołtarz, na którym było napisane: Nieznanemu Bogu. Ja głoszę wam tego, którego nie znając, czcicie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 24, 'Bóg, który stworzył świat i wszystko na nim, ten, który jest Panem nieba i ziemi, nie mieszka w świątyniach zbudowanych ręką.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 25, 'Ani nie jest czczony rękoma ludzkimi tak, jakby czegoś potrzebował, ponieważ sam daje wszystkim życie i oddech, i wszystko.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 26, 'I z jednej krwi uczynił wszystkie narody ludzkie, żeby mieszkały na całej powierzchni ziemi, określiwszy czasy wcześniej wyznaczone i zamierzone granice ich zamieszkania;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 27, 'Żeby szukali Pana, czy go nie znajdą po omacku, chociaż nie jest daleko od nikogo z nas.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 28, 'Bo w nim żyjemy, poruszamy się i jesteśmy, jak też powiedzieli niektórzy z waszych poetów: I my bowiem jesteśmy z jego rodu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 29, 'Będąc więc z rodu Boga, nie powinniśmy sądzić, że Bóstwo jest podobne do złota, srebra lub kamienia, misternie wyrzeźbionych według wyobrażenia ludzkiego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 30, 'Bóg wprawdzie pomijał czasy tej nieświadomości, teraz jednak nakazuje wszędzie wszystkim ludziom pokutować;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 31, 'Gdyż wyznaczył dzień, w którym będzie sprawiedliwie sądził cały świat przez człowieka, którego do tego przeznaczył, zapewniając o tym wszystkich przez wskrzeszenie go z martwych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 32, 'Gdy usłyszeli o zmartwychwstaniu, jedni się naśmiewali, a inni mówili: Posłuchamy cię o tym ponownie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 33, 'I tak Paweł wyszedł spośród nich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 34, 'Lecz niektórzy ludzie przyłączyli się do niego i uwierzyli. Był też wśród nich Dionizy Areopagita i kobieta imieniem Damaris oraz inni z nimi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 1, 'Potem Paweł opuścił Ateny i przybył do Koryntu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 2, 'Spotkał tam pewnego Żyda, imieniem Akwila, rodem z Pontu, który niedawno przybył z Italii razem ze swoją żoną Pryscyllą (ponieważ Klaudiusz zarządził, żeby wszyscy Żydzi opuścili Rzym), i poszedł do nich;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 3, 'A ponieważ znał to samo rzemiosło, zamieszkał u nich i pracował. Zajmowali się bowiem wyrobem namiotów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 4, 'W każdy szabat rozprawiał w synagodze i przekonywał i Żydów, i Greków.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 5, 'A gdy przyszli z Macedonii Sylas i Tymoteusz, Paweł był napierany w duchu i świadczył Żydom, że Jezus jest Chrystusem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 6, 'Lecz gdy się sprzeciwiali i bluźnili, otrząsnął szaty i powiedział do nich: Krew wasza na waszą głowę, ja jestem czysty. Od tej chwili pójdę do pogan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 7, 'Odszedł stamtąd i wszedł do domu pewnego człowieka, imieniem Justus, który czcił Boga, a którego dom przylegał do synagogi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 8, 'A przełożony synagogi, Kryspus, uwierzył w Pana wraz z całym swoim domem. Także wielu Koryntian, którzy słuchali, uwierzyło i zostało ochrzczonych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 9, 'Wtedy w nocy Pan powiedział do Pawła w widzeniu: Nie bój się, lecz mów i nie milcz;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 10, 'Bo ja jestem z tobą i nikt się na ciebie nie targnie, aby cię skrzywdzić. Mam bowiem liczny lud w tym mieście.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 11, 'I mieszkał tam przez rok i sześć miesięcy, nauczając u nich słowa Bożego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 12, 'A gdy Gallio był prokonsulem w Achai, Żydzi jednomyślnie powstali przeciw Pawłowi i przyprowadzili go przed sąd;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 13, 'Mówiąc: On namawia ludzi, aby niezgodnie z prawem czcili Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 14, 'Kiedy Paweł miał już otworzyć usta, Gallio powiedział do Żydów: O Żydzi, gdyby się działo bezprawie albo jakaś niegodziwość, znosiłbym was, jak należy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 15, 'Lecz jeśli spór dotyczy słów, imion i waszego prawa, sami to rozpatrzcie. Ja bowiem nie chcę być sędzią w tych sprawach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 16, 'I wypędził ich z sądu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 17, 'Wtedy wszyscy Grecy schwytali Sostenesa, przełożonego synagogi, i bili go przed sądem, lecz Gallio na to nie zważał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 18, 'A Paweł mieszkał tam jeszcze przez wiele dni, potem pożegnał się z braćmi i popłynął do Syrii, a z nim Pryscylla i Akwila. W Kenchrach ostrzygł głowę, bo złożył ślub.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 19, 'Potem przybył do Efezu i tam ich zostawił. Sam zaś wszedł do synagogi i rozprawiał z Żydami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 20, 'A gdy go prosili, żeby u nich pozostał dłużej, nie zgodził się;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 21, 'Ale żegnając się z nimi, powiedział: Nadchodzące święto muszę koniecznie obchodzić w Jerozolimie, lecz jeśli taka będzie wola Boga, wrócę do was. I odpłynął z Efezu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 22, 'Po przybyciu do Cezarei udał się do Jerozolimy, gdzie pozdrowił kościół, a potem odszedł do Antiochii.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 23, 'Mieszkał tam przez pewien czas i wyruszył, przemierzając krainę galacką i Frygię i umacniając wszystkich uczniów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 24, 'A do Efezu przybył pewien Żyd, imieniem Apollos, rodem z Aleksandrii, człowiek wymowny i biegły w Piśmie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 25, 'Był on obeznany z drogą Pana, a pałając duchem, mówił i nauczał starannie o Panu, wiedząc tylko o chrzcie Jana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 26, 'Zaczął on odważnie mówić w synagodze. Gdy go usłyszeli Akwila i Pryscylla, przyjęli go do siebie i dokładniej wytłumaczyli drogę Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 27, 'Kiedy chciał udać się do Achai, bracia go zachęcili i napisali do uczniów, aby go przyjęli. Gdy tam przybył, bardzo pomagał tym, którzy uwierzyli dzięki łasce Bożej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 28, 'Dzielnie bowiem przekonywał Żydów, publicznie dowodząc z Pisma, że Jezus jest Chrystusem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 1, 'I stało się, że gdy Apollos przebywał w Koryncie, Paweł obszedł okolice wyżej położone i dotarł do Efezu. I znalazłszy tam niektórych uczniów;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 2, 'Zapytał ich: Czy otrzymaliście Ducha Świętego, kiedy uwierzyliście? A oni mu odpowiedzieli: Nawet nie słyszeliśmy, że jest Duch Święty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 3, 'Wtedy zapytał ich: W czym więc byliście ochrzczeni? A oni odpowiedzieli: W chrzcie Jana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 4, 'Paweł zaś powiedział: Jan chrzcił chrztem pokuty, mówiąc ludziom, aby uwierzyli w tego, który przyjdzie po nim, to znaczy w Jezusa Chrystusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 5, 'Gdy to usłyszeli, zostali ochrzczeni w imię Pana Jezusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 6, 'A kiedy Paweł położył na nich ręce, zstąpił na nich Duch Święty i mówili językami, i prorokowali.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 7, 'Wszystkich mężczyzn było około dwunastu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 8, 'Potem przez trzy miesiące przychodził do synagogi i odważnie mówił, rozprawiając i przekonując o królestwie Bożym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 9, 'Gdy jednak niektórzy się upierali i nie chcieli uwierzyć, i mówili źle o tej drodze wobec tłumów, odstąpił od nich, odłączył uczniów i codziennie rozprawiał w szkole niejakiego Tyrannosa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 10, 'Działo się tak przez dwa lata, tak że wszyscy mieszkańcy Azji usłyszeli słowo Pana Jezusa, zarówno Żydzi, jak i Grecy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 11, 'A Bóg dokonywał niezwykłych cudów przez ręce Pawła;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 12, 'Tak że nawet chustki albo przepaski z jego ciała kładziono na chorych, a choroby ich opuszczały i wychodziły z nich złe duchy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 13, 'A niektórzy wędrowni żydowscy egzorcyści ważyli się wzywać imienia Pana Jezusa nad opętanymi przez złe duchy, mówiąc: Zaklinamy was przez Jezusa, którego głosi Paweł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 14, 'Robiło tak siedmiu synów pewnego Żyda, imieniem Skewas, który był naczelnikiem kapłanów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 15, 'Zły duch im odpowiedział: Znam Jezusa i wiem, kim jest Paweł, ale wy coście za jedni?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 16, 'I rzucił się na nich człowiek, w którym był zły duch, powalił i pokonał ich, tak że nadzy i zranieni wybiegli z tego domu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 17, 'Dowiedzieli się o tym wszyscy, zarówno Żydzi, jak i Grecy, którzy mieszkali w Efezie. A na nich wszystkich padł strach i było uwielbione imię Pana Jezusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 18, 'Wielu też tych, którzy uwierzyli, przychodziło i wyznawało, i ujawniało swoje uczynki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 19, 'I wielu z tych, którzy się zajmowali sztukami magicznymi, znosiło księgi i paliło je wobec wszystkich. Obliczono ich wartość i stwierdzono, że wynosi pięćdziesiąt tysięcy srebrników.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 20, 'Tak potężnie rosło i umacniało się słowo Pańskie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 21, 'Po tych wydarzeniach Paweł postanowił w duchu, że po przejściu Macedonii i Achai pójdzie do Jerozolimy, mówiąc: Potem, gdy się tam dostanę, muszę zobaczyć także Rzym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 22, 'Wysłał więc do Macedonii dwóch z tych, którzy mu służyli, Tymoteusza i Erasta, a sam pozostał jeszcze przez jakiś czas w Azji.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 23, 'W tym czasie doszło do niemałych rozruchów z powodu tej drogi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 24, 'Bo pewien złotnik, imieniem Demetriusz, który wyrabiał ze srebra świątyńki Diany, zapewniał rzemieślnikom niemały zarobek.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 25, 'Zebrał ich i innych, zajmujących się podobnym rzemiosłem, i powiedział: Mężowie, wiecie, że nasz dobrobyt płynie z tego rzemiosła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 26, 'Widzicie też i słyszycie, że ten Paweł nie tylko w Efezie, ale prawie w całej Azji przekonał i odwiódł wielu ludzi, mówiąc, że nie są bogami ci, którzy rękami ludzkimi są uczynieni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 27, 'Należy więc obawiać się nie tylko tego, że nasze rzemiosło zostanie zlekceważone, ale też że świątynia wielkiej bogini Diany, czczonej w całej Azji i w całym świecie, zostanie poczytana za nic i zostanie zniszczony jej majestat.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 28, 'Gdy to usłyszeli, ogarnął ich gniew i zaczęli krzyczeć: Wielka jest Diana Efeska!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 29, 'I całe miasto napełniło się wrzawą. Porwawszy Gajusa i Arystarcha, Macedończyków, towarzyszy podróży Pawła, jednomyślnie ruszyli do teatru.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 30, 'Gdy Paweł chciał wejść między lud, uczniowie mu nie pozwolili.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 31, 'Również niektórzy dostojnicy Azji, będący jego przyjaciółmi, posłali do niego prośbę, aby nie wszedł do teatru.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 32, 'Tymczasem jedni krzyczeli tak, a drudzy inaczej. W zgromadzeniu bowiem zapanował zamęt, a większość z nich nie wiedziała, po co się zebrali.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 33, 'Z tłumu wyciągnięto Aleksandra, którego Żydzi wysunęli do przodu. Aleksander dał znak ręką, bo chciał zdać sprawę ludowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 34, 'Gdy jednak poznali, że jest Żydem, rozległ się jeden krzyk i wszyscy wołali przez około dwie godziny: Wielka jest Diana Efeska!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 35, 'Wtedy sekretarz miejski uspokoił tłum i powiedział: Mężowie efescy, kto z ludzi nie wie, że miasto Efez jest opiekunem świątyni wielkiej bogini Diany i jej posągu, który spadł od Jowisza?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 36, 'Skoro nikt temu nie może zaprzeczyć, powinniście się uspokoić i niczego nie czynić pochopnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 37, 'Przyprowadziliście bowiem tych ludzi, którzy nie są ani świętokradcami, ani też nie bluźnią waszej bogini.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 38, 'A jeśli Demetriusz i rzemieślnicy, którzy są z nim, mają coś przeciwko komuś, są przecież sądy, są też prokonsulowie, niech pozywają jedni drugich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 39, 'Jeśli zaś chodzi o coś innego, zostanie to rozpatrzone na prawomocnym zebraniu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 40, 'Grozi nam bowiem oskarżenie o dzisiejsze rozruchy, bo nie ma żadnego powodu, którym moglibyśmy wytłumaczyć to zbiegowisko.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 41, 'Po tych słowach rozwiązał zebranie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 1, 'A gdy ustały rozruchy, Paweł przywołał uczniów, pożegnał się z nimi i wyruszył do Macedonii.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 2, 'Przeszedł tamte okolice, udzielając wielu napomnień. Potem przybył do Grecji.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 3, 'Kiedy po trzymiesięcznym pobycie zamierzał odpłynąć do Syrii, Żydzi urządzili na niego zasadzkę, więc postanowił powrócić przez Macedonię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 4, 'Razem z nim do Azji wyruszyli Sopater z Berei, z Tesaloniczan Arystarch i Sekundus, i Gajus z Derbe, i Tymoteusz, a z Azji Tychikus i Trofim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 5, 'Ci poszli pierwsi i czekali na nas w Troadzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 6, 'My zaś po święcie Przaśników odpłynęliśmy z Filippi i po pięciu dniach przybyliśmy do nich do Troady, gdzie spędziliśmy siedem dni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 7, 'A pierwszego dnia po szabacie, gdy uczniowie zebrali się na łamanie chleba, Paweł, który miał nazajutrz odjechać, przemawiał do nich i przeciągnął mowę aż do północy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 8, 'A w sali na piętrze, w której byli zebrani, paliło się wiele lamp.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 9, 'Pewien młodzieniec, imieniem Eutych, siedział w oknie pogrążony w głębokim śnie. Kiedy Paweł długo przemawiał, zmorzony snem spadł z trzeciego piętra na dół. Gdy go podniesiono, był martwy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 10, 'Paweł zszedł na dół, przypadł do niego, objął go i powiedział: Nie bójcie się, bo jest w nim życie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 11, 'Wrócił na górę, łamał chleb i jadł, a głosił im długo, aż do świtu. Potem ruszył w drogę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 12, 'I przyprowadzili młodzieńca żywego, i byli wielce pocieszeni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 13, 'My zaś, wsiadłszy wcześniej na statek, popłynęliśmy do Assos, skąd mieliśmy zabrać Pawła. Tak bowiem postanowił, sam chcąc iść pieszo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 14, 'Kiedy spotkał się z nami w Assos, zabraliśmy go i przybyliśmy do Mityleny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 15, 'Odpłynąwszy stamtąd, nazajutrz znaleźliśmy się naprzeciw Chios, a następnego dnia przypłynęliśmy do Samos. Przenocowaliśmy w Trogillium, a dzień później dotarliśmy do Miletu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 16, 'Gdyż Paweł postanowił ominąć Efez, żeby nie spędzić czasu w Azji. Spieszył się bowiem, aby, jeśli to możliwe, być na dzień Pięćdziesiątnicy w Jerozolimie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 17, 'Z Miletu posłał do Efezu, wzywając do siebie starszych kościoła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 18, 'A gdy przybyli do niego, powiedział: Wy wiecie, jaki byłem przez cały czas wśród was od pierwszego dnia, kiedy przybyłem do Azji;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 19, 'Jak służyłem Panu z całą pokorą wśród wielu łez i doświadczeń, które mnie spotykały z powodu zasadzek Żydów;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 20, 'Jak nie uchylałem się od niczego, co pożyteczne, od przemawiania i nauczania was publicznie i po domach;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 21, 'Oświadczając zarówno Żydom, jak i Grekom o pokucie wobec Boga i o wierze w naszego Pana Jezusa Chrystusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 22, 'A teraz, związany w duchu, idę do Jerozolimy, nie wiedząc, co mnie tam spotka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 23, 'Wiem tylko, że Duch Święty poświadcza w każdym mieście, iż czekają mnie więzy i utrapienia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 24, 'Lecz ja o to nie dbam, a moje życie nie jest mi tak drogie, bylebym tylko z radością dokończył mój bieg i posługę, którą otrzymałem od Pana Jezusa, by dać świadectwo o ewangelii łaski Bożej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 25, 'A teraz wiem, że wy wszyscy, wśród których przebywałem, głosząc królestwo Boże, już więcej nie zobaczycie mojej twarzy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 26, 'Dlatego oświadczam wam dzisiaj, że nie jestem winien niczyjej krwi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 27, 'Nie uchylałem się bowiem od zwiastowania wam całej rady Bożej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 28, 'Uważajcie na samych siebie i na całe stado, w którym was Duch Święty ustanowił biskupami, abyście paśli kościół Boga, który on nabył własną krwią.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 29, 'Gdyż wiem, że po moim odejściu wejdą między was wilki drapieżne, które nie będą oszczędzać stada.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 30, 'Także spośród was samych powstaną ludzie mówiący rzeczy przewrotne, aby pociągnąć za sobą uczniów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 31, 'Dlatego czuwajcie, pamiętając, że przez trzy lata we dnie i w nocy nie przestawałem ze łzami napominać każdego z was.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 32, 'A teraz, bracia, polecam was Bogu i słowu jego łaski, które może zbudować was i dać wam dziedzictwo wśród wszystkich, którzy są uświęceni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 33, 'Nie pożądałem srebra, złota ani szaty niczyjej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 34, 'Przeciwnie, sami wiecie, że te ręce służyły zaspokajaniu potrzeb moich i tych, którzy są ze mną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 35, 'We wszystkim wam pokazałem, że tak pracując, musimy wspierać słabych i pamiętać o słowach Pana Jezusa, który powiedział: Bardziej błogosławioną rzeczą jest dawać niż brać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 36, 'Po tych słowach ukląkł i modlił się z nimi wszystkimi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 37, 'Wtedy wszyscy wybuchnęli wielkim płaczem i rzucając się Pawłowi na szyję, całowali go;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 38, 'Smucąc się najbardziej z powodu tych słów, które im powiedział, że już więcej nie zobaczą jego twarzy. I odprowadzili go na statek.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 1, 'Po rozstaniu z nimi odpłynęliśmy i prostym kursem przybyliśmy na Kos, a nazajutrz na Rodos, stamtąd zaś do Patary.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 2, 'Znalazłszy tam statek, który miał płynąć do Fenicji, wsiedliśmy na niego i odpłynęliśmy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 3, 'A gdy zobaczyliśmy Cypr, zostawiliśmy go po lewej stronie, popłynęliśmy do Syrii i przybyliśmy do Tyru. Tam bowiem miano wyładować towary ze statku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 4, 'Odszukawszy uczniów, pozostaliśmy tam siedem dni, a oni pod wpływem Ducha mówili Pawłowi, żeby nie szedł do Jerozolimy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 5, 'Po upływie tych dni odeszliśmy i wyruszyliśmy w drogę, a wszyscy z żonami i dziećmi odprowadzili nas za miasto. A uklęknąwszy na wybrzeżu, modliliśmy się.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 6, 'A gdy pożegnaliśmy się ze sobą, weszliśmy na statek, a oni wrócili do domu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 7, 'Pod koniec żeglugi z Tyru przypłynęliśmy do Ptolemaidy i powitawszy braci, spędziliśmy u nich jeden dzień.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 8, 'A wyszedłszy nazajutrz, Paweł i my, jego towarzysze, dotarliśmy do Cezarei. Weszliśmy do domu Filipa ewangelisty, który był jednym z siedmiu, i zatrzymaliśmy się u niego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 9, 'A miał on cztery córki, dziewice, które prorokowały.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 10, 'Kiedy tam mieszkaliśmy przez wiele dni, przyszedł z Judei pewien prorok, imieniem Agabos.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 11, 'Przybył do nas, wziął pas Pawła, związał sobie ręce i nogi i powiedział: To mówi Duch Święty: Tak Żydzi zwiążą w Jerozolimie i wydadzą w ręce pogan człowieka, do którego należy ten pas.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 12, 'Gdy to usłyszeliśmy, prosiliśmy my i miejscowi bracia, aby nie szedł do Jerozolimy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 13, 'Wtedy Paweł odpowiedział: Co czynicie, płacząc i rozdzierając mi serce? Ja bowiem dla imienia Pana Jezusa jestem gotowy nie tylko dać się związać, ale i umrzeć w Jerozolimie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 14, 'A gdy nie dał się przekonać, ustąpiliśmy, mówiąc: Niech się stanie wola Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 15, 'Po upływie tych dni wzięliśmy swoje rzeczy i ruszyliśmy do Jerozolimy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 16, 'Szli z nami niektórzy uczniowie z Cezarei, prowadząc niejakiego Mnazona Cypryjczyka, starego ucznia, u którego mieliśmy się zatrzymać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 17, 'A gdy przybyliśmy do Jerozolimy, bracia przyjęli nas z radością.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 18, 'Nazajutrz Paweł poszedł z nami do Jakuba, gdzie zebrali się wszyscy starsi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 19, 'Powitawszy ich, opowiedział im szczegółowo, czego Bóg dokonał wśród pogan przez jego posługę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 20, 'Gdy to usłyszeli, chwalili Pana i powiedzieli: Widzisz, bracie, ile tysięcy Żydów uwierzyło, a wszyscy gorliwie trzymają się prawa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 21, 'Lecz o tobie słyszeli, że odwodzisz od Mojżesza wszystkich Żydów, którzy są wśród pogan, mówiąc, że nie mają obrzezywać dzieci ani żyć według swoich zwyczajów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 22, 'Cóż więc czynić? Z pewnością zejdzie się lud, bo usłyszą, że przybyłeś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 23, 'Zrób zatem to, co ci mówimy. Mamy tu czterech mężczyzn, którzy złożyli ślub.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 24, 'Weź ich ze sobą, poddaj się wraz z nimi oczyszczeniu i pokryj za nich koszty, aby mogli ostrzyc głowy. Wtedy wszyscy poznają, że w tym, co o tobie słyszeli, nie ma nic z prawdy, ale że i ty sam postępujesz porządnie, przestrzegając prawa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 25, 'A co do pogan, którzy uwierzyli, napisaliśmy, postanawiając, aby niczego takiego nie zachowywali, tylko żeby się wystrzegali tego, co ofiarowane bożkom, i krwi, i tego, co uduszone, i nierządu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 26, 'Wtedy Paweł wziął ze sobą tych mężczyzn, a następnego dnia poddał się razem z nimi oczyszczeniu i wszedł do świątyni, zgłaszając wypełnienie dni oczyszczenia, aż za każdego z nich złożona zostanie ofiara.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 27, 'Kiedy zaś te siedem dni dobiegało końca, zobaczyli go w świątyni Żydzi z Azji, podburzyli tłum i rzucili się na niego;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 28, 'Wołając: Mężowie Izraelici, pomóżcie! To jest człowiek, który wszędzie wszystkich naucza przeciwko ludowi i prawu, i temu miejscu, a nadto jeszcze i Greków wprowadził do świątyni i splugawił to święte miejsce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 29, 'Przedtem bowiem widzieli z nim w mieście Trofima z Efezu i sądzili, że Paweł wprowadził go do świątyni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 30, 'I poruszyło się całe miasto, i zbiegł się lud. A schwytawszy Pawła, wyciągnęli go ze świątyni i natychmiast zamknięto drzwi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 31, 'A gdy usiłowali go zabić, dano znać dowódcy oddziału, że cała Jerozolima jest wzburzona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 32, 'Natychmiast wziął żołnierzy i setników i zbiegł do nich na dół. A kiedy zobaczyli dowódcę i żołnierzy, przestali bić Pawła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 33, 'Wtedy dowódca zbliżył się, zatrzymał go, kazał związać dwoma łańcuchami i wypytywał, kim jest i co zrobił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 34, 'I jedni z tłumu krzyczeli tak, a drudzy inaczej. A gdy z powodu zgiełku nie mógł dowiedzieć się niczego pewnego, rozkazał zaprowadzić go do twierdzy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 35, 'Kiedy znalazł się na schodach, doszło do tego, że żołnierze musieli go nieść z powodu naporu tłumu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 36, 'Wielki tłum bowiem szedł za nim, wołając: Zgładź go!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 37, 'A gdy Paweł miał być wprowadzony do twierdzy, zapytał dowódcę: Czy wolno mi coś do ciebie powiedzieć? A on odpowiedział: Mówisz po grecku?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 38, 'Czy nie jesteś tym Egipcjaninem, który przed tymi dniami wzniecił rozruchy i wyprowadził na pustynię cztery tysiące zabójców?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 39, 'A Paweł powiedział: Jestem Żydem z Tarsu, obywatelem znacznego miasta w Cylicji. Dlatego proszę cię, pozwól mi przemówić do ludu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 40, 'Gdy pozwolił, Paweł, stojąc na schodach, dał ręką znak ludowi, a gdy nastała wielka cisza, przemówił po hebrajsku:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 1, 'Mężowie bracia i ojcowie, słuchajcie mojej obrony, jaką teraz do was kieruję.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 2, 'Gdy usłyszeli, że mówił do nich po hebrajsku, jeszcze bardziej się uciszyli. A on powiedział:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 3, 'Jestem Żydem, urodzonym w Tarsie w Cylicji, lecz wychowanym w tym mieście, u stóp Gamaliela, starannie wykształconym w prawie ojczystym i byłem gorliwym względem Boga jak i wy wszyscy dzisiaj.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 4, 'Prześladowałem tę drogę aż na śmierć, wiążąc i wtrącając do więzienia zarówno mężczyzn, jak i kobiety;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 5, 'Czego mi świadkiem jest najwyższy kapłan oraz wszyscy starsi. Od nich też otrzymałem listy do braci i pojechałem do Damaszku, aby tych, którzy tam byli, przyprowadzić związanych do Jerozolimy, żeby zostali ukarani.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 6, 'A gdy byłem w drodze i zbliżałem się do Damaszku około południa, nagle ogarnęła mnie wielka światłość z nieba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 7, 'I upadłem na ziemię, i usłyszałem głos, który mówił do mnie: Saulu, Saulu, dlaczego mnie prześladujesz?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 8, 'A ja odpowiedziałem: Kim jesteś, Panie? I powiedział do mnie: Ja jestem Jezus z Nazaretu, którego ty prześladujesz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 9, 'A ci, którzy byli ze mną, wprawdzie widzieli światłość i przestraszyli się, ale głosu tego, który do mnie mówił, nie słyszeli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 10, 'Zapytałem: Co mam robić, Panie? A Pan powiedział do mnie: Wstań i idź do Damaszku, a tam ci powiedzą o wszystkim, co postanowiono, abyś uczynił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 11, 'A ponieważ zaniewidziałem z powodu blasku tej światłości, przyszedłem do Damaszku prowadzony za rękę przez tych, którzy byli ze mną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 12, 'Tam niejaki Ananiasz, człowiek pobożny według prawa, mający dobre świadectwo u wszystkich Żydów, którzy tam mieszkali;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 13, 'Przyszedł, podszedł do mnie i powiedział: Bracie Saulu, przejrzyj! I w tej chwili spojrzałem na niego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 14, 'A on powiedział: Bóg naszych ojców wybrał cię, żebyś poznał jego wolę, oglądał Sprawiedliwego i słuchał głosu z jego ust.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 15, 'Będziesz mu bowiem wobec wszystkich ludzi świadkiem tego, co widziałeś i słyszałeś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 16, 'Dlaczego teraz zwlekasz? Wstań, ochrzcij się i obmyj swoje grzechy, wzywając imienia Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 17, 'A gdy wróciłem do Jerozolimy i modliłem się w świątyni, wpadłem w zachwycenie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 18, 'I widziałem go, jak mówił do mnie: Pospiesz się i wyjdź szybko z Jerozolimy, ponieważ nie przyjmą twego świadectwa o mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 19, 'A ja odpowiedziałem: Panie, oni wiedzą, że wtrącałem do więzienia i biczowałem w synagogach tych, którzy w ciebie wierzyli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 20, 'A kiedy przelewano krew Szczepana, twojego świadka, ja też byłem przy tym i zgodziłem się na jego zabicie, i pilnowałem szat tych, którzy go zabili.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 21, 'I powiedział mi: Idź, bo ja cię poślę daleko, do pogan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 22, 'Słuchali go aż do tego słowa, potem podnieśli swój głos, mówiąc: Zgładź z ziemi takiego człowieka, bo nie godzi się, żeby żył!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 23, 'A gdy oni krzyczeli, rozrzucali szaty i ciskali proch w powietrze;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 24, 'Dowódca rozkazał go zaprowadzić do twierdzy i polecił przesłuchać go z zastosowaniem biczowania, żeby się dowiedzieć, dlaczego tak przeciwko niemu krzyczano.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 25, 'A gdy go związano, aby go ubiczować, Paweł powiedział do setnika, który stał obok: Czy wolno wam biczować Rzymianina i to bez sądu?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 26, 'Kiedy setnik to usłyszał, podszedł do dowódcy i powiedział mu: Uważaj, co robisz, bo ten człowiek jest Rzymianinem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 27, 'Dowódca podszedł i zapytał go: Powiedz mi, czy ty jesteś Rzymianinem? A on odpowiedział: Tak.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 28, 'I powiedział dowódca: Ja kupiłem to obywatelstwo za wielką sumę. Paweł zaś rzekł: A ja mam je od urodzenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 29, 'I natychmiast odstąpili od niego ci, którzy mieli go przesłuchać. Nawet i dowódca przestraszył się, kiedy się dowiedział, że jest Rzymianinem, a on kazał go związać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 30, 'A nazajutrz, chcąc się dokładnie dowiedzieć, o co Żydzi go oskarżali, uwolnił go z więzów i rozkazał zebrać się naczelnym kapłanom i całej Radzie, przyprowadził Pawła i stawił go przed nimi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 1, 'Paweł, patrząc uważnie na Radę, powiedział: Mężowie bracia, aż do dziś żyłem przed Bogiem z zupełnie czystym sumieniem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 2, 'Lecz Ananiasz, najwyższy kapłan, rozkazał tym, którzy przy nim stali, uderzyć go w twarz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 3, 'Wtedy Paweł powiedział do niego: Uderzy cię Bóg, ściano pobielana! Zasiadłeś, aby mnie sądzić według prawa, a każesz mnie bić wbrew prawu?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 4, 'Ci zaś, którzy tam stali, powiedzieli: Złorzeczysz najwyższemu kapłanowi Boga?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 5, 'Paweł odpowiedział: Nie wiedziałem, bracia, że to najwyższy kapłan. Jest bowiem napisane: Przełożonemu twego ludu nie będziesz złorzeczyć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 6, 'A Paweł, poznawszy, że jedna część składa się z saduceuszy, a druga z faryzeuszy, zawołał do Rady: Mężowie bracia, jestem faryzeuszem, synem faryzeusza. Sądzą mnie dziś z powodu nadziei i zmartwychwstania umarłych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 7, 'Gdy to powiedział, powstał spór między faryzeuszami a saduceuszami i doszło do rozdwojenia wśród gromady zebranych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 8, 'Saduceusze bowiem mówią, że nie ma zmartwychwstania ani anioła, ani ducha, a faryzeusze wyznają jedno i drugie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 9, 'I wszczął się wielki krzyk, a uczeni w Piśmie ze stronnictwa faryzeuszy zerwali się i zaczęli się spierać, mówiąc: Niczego złego nie znajdujemy w tym człowieku. Jeśli mu coś powiedział duch albo anioł, to nie walczmy z Bogiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 10, 'A gdy doszło do wielkiego wzburzenia, dowódca, obawiając się, aby Pawła nie rozszarpali, rozkazał żołnierzom zejść, wyrwać go spośród nich i zaprowadzić do twierdzy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 11, 'A następnej nocy Pan stanął przy nim i powiedział: Bądź dobrej myśli, Pawle! Tak bowiem, jak świadczyłeś o mnie w Jerozolimie, musisz świadczyć również w Rzymie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 12, 'Kiedy nastał dzień, niektórzy spośród Żydów zebrali się i zobowiązali się przysięgą, że nie będą jeść ani pić, dopóki nie zabiją Pawła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 13, 'A tych, którzy przystąpili do tego sprzysiężenia, było ponad czterdziestu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 14, 'Przyszli oni do naczelnych kapłanów i starszych i powiedzieli: Związaliśmy się przysięgą, że nie weźmiemy nic do ust, dopóki nie zabijemy Pawła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 15, 'Dlatego teraz wy razem z Radą dajcie znać dowódcy, żeby go jutro do was przyprowadził pod pozorem dokładniejszego zbadania jego sprawy, a my jesteśmy gotowi go zabić, zanim dojdzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 16, 'A gdy siostrzeniec Pawła usłyszał o tej zasadzce, przybył, wszedł do twierdzy i powiadomił o tym Pawła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 17, 'Wtedy Paweł przywołał jednego z setników i powiedział: Zaprowadź tego młodzieńca do dowódcy, bo ma mu coś do powiedzenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 18, 'Wziął go więc ze sobą, zaprowadził go do dowódcy i powiedział: Więzień Paweł przywołał mnie i poprosił, abym przyprowadził do ciebie tego młodzieńca, który ma ci coś do powiedzenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 19, 'Dowódca wziął go za rękę, odszedł z nim na bok i zapytał: O czym to masz mi powiedzieć?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 20, 'A on odpowiedział: Żydzi postanowili cię prosić, żebyś jutro zaprowadził Pawła przed Radę pod pozorem dokładniejszego zbadania jego sprawy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 21, 'Lecz nie ulegnij ich namowie, bo czyha na niego ponad czterdziestu mężczyzn, którzy związali się przysięgą, że nie będą jeść ani pić, dopóki go nie zabiją. Są już w pogotowiu, czekając na twoje pozwolenie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 22, 'Wtedy dowódca odesłał młodzieńca, przykazując, aby nikomu nie mówił, że go o tym powiadomił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 23, 'Przywoławszy dwóch setników, powiedział: Przygotujcie do wymarszu do Cezarei na godzinę trzecią w nocy dwustu żołnierzy, siedemdziesięciu jeźdźców i dwustu oszczepników.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 24, 'Kazał też przygotować zwierzęta juczne, aby wsadzić na nie Pawła i bezpiecznie doprowadzić go do namiestnika Feliksa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 25, 'Napisał też list tej treści:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 26, 'Klaudiusz Lizjasz najdostojniejszemu namiestnikowi Feliksowi przesyła pozdrowienia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 27, 'Człowieka tego schwytali Żydzi, a gdy go mieli zabić, nadbiegłem z oddziałem i uratowałem go, dowiedziawszy się, że jest Rzymianinem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 28, 'A chcąc wiedzieć, z jakiej przyczyny go oskarżają, zaprowadziłem go przed ich Radę;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 29, 'I stwierdziłem, że oskarżają go o jakieś sporne kwestie dotyczące ich prawa i że nie ma żadnej winy, dla której zasługiwałby na śmierć lub więzienie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 30, 'A gdy mi powiedziano o zasadzce, którą na niego przygotowali Żydzi, natychmiast wysłałem go do ciebie, a jego oskarżycielom nakazałem, żeby przed tobą stawiali zarzuty wobec niego. Bądź zdrów!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 31, 'Żołnierze zabrali więc Pawła zgodnie z rozkazem i zaprowadzili go nocą do Antipatris.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 32, 'A nazajutrz zostawili jeźdźców, aby jechali z nim dalej, a sami wrócili do twierdzy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 33, 'Tamci przyjechali do Cezarei, oddali list namiestnikowi i stawili przed nim Pawła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 34, 'A namiestnik po przeczytaniu listu zapytał go, z jakiej prowincji pochodzi. Kiedy dowiedział się, że z Cylicji;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 35, 'Powiedział: Przesłucham cię, gdy przybędą twoi oskarżyciele. I rozkazał strzec go w ratuszu Heroda.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 1, 'Po pięciu dniach przybył najwyższy kapłan Ananiasz wraz ze starszymi i z retorem, niejakim Tertullosem. Wnieśli oni przed namiestnika oskarżenie przeciwko Pawłowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 2, 'A gdy go wezwano, Tertullos rozpoczął mowę oskarżycielską: Ponieważ dzięki tobie cieszymy się zupełnym pokojem i dzięki twojej przezorności nasz naród doświadcza wiele dobrego;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 3, 'Przyznajemy to zawsze i wszędzie, dostojny Feliksie, z wielką wdzięcznością.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 4, 'Aby cię jednak dłużej nie zatrzymywać, proszę, abyś nas w swej łaskawości przez chwilę posłuchał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 5, 'Stwierdziliśmy, że ten człowiek jest jak zaraza, wzbudza niepokoje wśród wszystkich Żydów na całym świecie i jest dowódcą sekty nazarejczyków.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 6, 'Usiłował on też zbezcześcić świątynię. Schwytaliśmy go więc i chcieliśmy osądzić według naszego prawa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 7, 'Lecz dowódca Lizjasz przybył i wyrwał go przemocą z naszych rąk;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 8, 'Nakazując jego oskarżycielom udać się do ciebie. Gdy go przesłuchasz, sam będziesz mógł dowiedzieć się od niego wszystkiego, o co go oskarżamy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 9, 'Również Żydzi to potwierdzili, oświadczając, że tak się rzeczy mają.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 10, 'Kiedy namiestnik dał znak, aby mówił, Paweł powiedział: Wiedząc, że od wielu lat jesteś sędzią tego narodu, tym chętniej zdam sprawę z tego, co mnie dotyczy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 11, 'Możesz sprawdzić, że nie upłynęło więcej niż dwanaście dni, odkąd przybyłem do Jerozolimy, aby wielbić Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 12, 'I nie znaleźli mnie w świątyni rozprawiającego z kimkolwiek ani podburzającego lud czy to w synagogach, czy w mieście;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 13, 'Ani też nie mogą dowieść tego, o co mnie oskarżają.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 14, 'Wyznaję jednak przed tobą, że według drogi, którą oni uważają za herezję, służę Bogu moich ojców, wierząc wszystkiemu, co jest napisane w Prawie i u Proroków;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 15, 'Mając nadzieję w Bogu, że będzie zmartwychwstanie, którego i oni oczekują, zarówno sprawiedliwych, jak i niesprawiedliwych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 16, 'I sam się usilnie staram, aby zawsze mieć sumienie bez skazy wobec Boga i ludzi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 17, 'A po wielu latach przybyłem, aby złożyć jałmużny i ofiary memu narodowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 18, 'Wtedy pewni Żydzi z Azji spotkali mnie oczyszczonego w świątyni, bez tłumu i zgiełku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 19, 'Oni powinni tu stanąć przed tobą i oskarżać, jeżeli mają coś przeciwko mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 20, 'Albo niech ci tutaj sami powiedzą, czy znaleźli we mnie jakąś nieprawość, gdy stanąłem przed Radą;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 21, 'Chyba jedynie to, że stojąc wśród nich, zawołałem: Sądzicie mnie dziś z powodu zmartwychwstania umarłych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 22, 'Kiedy Feliks to usłyszał, znając dokładniej tę drogę, odroczył ich sprawę, mówiąc: Rozpatrzę waszą sprawę, kiedy tu przyjedzie dowódca Lizjasz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 23, 'I rozkazał setnikowi pilnować Pawła, zastosować ulgi i nie zabraniać żadnemu z jego przyjaciół posługiwać mu czy go odwiedzać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 24, 'A po kilku dniach przyjechał Feliks ze swoją żoną Druzyllą, która była Żydówką. Kazał zawołać Pawła i słuchał go, jak mówił o wierze w Chrystusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 25, 'A gdy on rozprawiał o sprawiedliwości, powściągliwości i przyszłym sądzie, Feliks przestraszył się i powiedział: Teraz już odejdź. Kiedy znajdę czas, każę cię zawołać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 26, 'Spodziewał się przy tym, że dostanie od Pawła pieniądze za to, że go wypuści, dlatego też częściej wzywał go do siebie na rozmowę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 27, 'A po dwóch latach następcą Feliksa został Porcjusz Festus. Feliks, chcąc sobie zjednać życzliwość Żydów, zostawił Pawła w więzieniu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 1, 'Kiedy Festus przybył do prowincji, po trzech dniach udał się z Cezarei do Jerozolimy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 2, 'Najwyższy kapłan i znamienici Żydzi wnieśli przed nim przeciwko Pawłowi skargę i prosili go;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 3, 'Aby okazał im w jego sprawie przychylność i kazał przyprowadzić go do Jerozolimy. Przygotowali bowiem zasadzkę, aby go zabić w drodze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 4, 'Lecz Festus odpowiedział, że Paweł znajduje się pod strażą w Cezarei i że on sam wkrótce tam pojedzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 5, 'I powiedział: Niech ci z was, którzy mogą, pojadą ze mną, a jeśli ten człowiek popełnił coś złego, niech go oskarżają.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 6, 'A gdy spędził u nich nie więcej niż dziesięć dni, udał się do Cezarei. Nazajutrz zasiadł na krześle sędziowskim i kazał przyprowadzić Pawła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 7, 'Kiedy ten przyszedł, otoczyli go Żydzi, którzy przybyli z Jerozolimy, i wytoczyli przeciwko Pawłowi wiele ciężkich oskarżeń, których nie mogli udowodnić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 8, 'On zaś bronił się: Nie zawiniłem w niczym ani przeciwko prawu żydowskiemu, ani przeciwko świątyni, ani przeciwko cesarzowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 9, 'Lecz Festus, chcąc sobie zjednać przychylność Żydów, odpowiedział Pawłowi: Czy chcesz pojechać do Jerozolimy i tam być przede mną sądzony w tej sprawie?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 10, 'Wtedy Paweł powiedział: Stoję przed sądem cesarskim, gdzie należy mnie sądzić. Żydom nie wyrządziłem żadnej krzywdy, o czym ty sam dobrze wiesz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 11, 'Bo jeśli w czymś zawiniłem i popełniłem coś, co zasługuje na śmierć, nie wzbraniam się umrzeć. Lecz jeśli nie ma nic w tym, o co mnie oskarżają, nikt nie może mnie im wydać. Odwołuję się do cesarza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 12, 'Wtedy Festus porozumiał się z Radą i odpowiedział: Odwołałeś się do cesarza? Do cesarza pójdziesz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 13, 'A po upływie kilku dni przyjechali do Cezarei król Agryppa i Berenike, aby powitać Festusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 14, 'A kiedy przebywali tam wiele dni, Festus przedstawił królowi sprawę Pawła, mówiąc: Feliks pozostawił w więzieniu pewnego człowieka;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 15, 'Przeciwko któremu, gdy byłem w Jerozolimie, naczelni kapłani i starsi żydowscy wnieśli skargę, żądając dla niego wyroku skazującego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 16, 'Odpowiedziałem im, że Rzymianie nie mają w zwyczaju wydawać człowieka na stracenie, zanim oskarżony nie stanie wobec oskarżycieli i nie będzie miał możliwości odpowiedzieć na zarzuty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 17, 'Gdy się tu zebrali, nazajutrz, bez żadnej zwłoki zasiadłem na krześle sędziowskim i kazałem przyprowadzić tego człowieka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 18, 'Stanęli przeciw niemu jego oskarżyciele, ale nie wnieśli żadnej skargi z tych, których się spodziewałem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 19, 'Wiedli z nim tylko jakieś spory o ich zabobony i o jakiegoś zmarłego Jezusa, o którym Paweł twierdzi, że żyje.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 20, 'Będąc niepewnym co do tego sporu, zapytałem, czy chciałby udać się do Jerozolimy i tam być sądzony w tych sprawach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 21, 'Lecz ponieważ Paweł odwołał się, by go zatrzymać do rozpatrzenia sprawy przez Augusta, rozkazałem go strzec, dopóki go nie odeślę do cesarza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 22, 'Wtedy Agryppa powiedział do Festusa: Ja również chciałbym posłuchać tego człowieka. A on odpowiedział: Jutro go usłyszysz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 23, 'Gdy nazajutrz Agryppa i Berenike przybyli z wielką okazałością i weszli do sali rozpraw z dowódcami i najznakomitszymi obywatelami miasta, na rozkaz Festusa wprowadzono Pawła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 24, 'Po czym Festus przemówił: Królu Agryppo i wszyscy tu obecni mężowie! Widzicie tego, o którego mnie prosił cały lud żydowski zarówno w Jerozolimie, jak i tutaj, wołając, że nie powinien on dłużej żyć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 25, 'Lecz ja stwierdziłem, że nie popełnił niczego, co zasługuje na śmierć. A ponieważ on sam odwołał się do Augusta, postanowiłem go odesłać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 26, 'Nie mogę jednak o nim napisać memu panu nic pewnego. Dlatego kazałem go stawić przed wami, a zwłaszcza przed tobą, królu Agryppo, abym po przesłuchaniu miał co napisać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 27, 'Bo wydaje mi się nierozsądne posyłać więźnia bez podania stawianych mu zarzutów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 1, 'Wtedy Agryppa powiedział do Pawła: Wolno ci mówić we własnej obronie. Wówczas Paweł, wyciągnąwszy rękę, zaczął się bronić:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 2, 'Królu Agryppo, uważam to za szczęście, że mam dziś bronić się wobec ciebie przed wszystkim, o co mnie oskarżają Żydzi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 3, 'Zwłaszcza że jesteś obeznany ze wszystkimi zwyczajami i sporami, które są między Żydami. Dlatego proszę cię, żebyś mnie cierpliwie wysłuchał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 4, 'Wszyscy Żydzi znają moje życie od młodości, jak je wiodłem od początku wśród mego narodu w Jerozolimie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 5, 'Znają mnie od dawna – gdyby chcieli zaświadczyć – że żyłem według zasad najsurowszego stronnictwa naszej religii jako faryzeusz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 6, 'A teraz stoję przed sądem z powodu nadziei spełnienia obietnicy danej ojcom przez Boga;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 7, 'Której spełnienia ma nadzieję doczekać dwanaście naszych pokoleń, służąc Bogu ustawicznie dniem i nocą. Z powodu tej nadziei, królu Agryppo, oskarżają mnie Żydzi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 8, 'Dlaczego uważacie za rzecz nie do wiary, że Bóg wskrzesza umarłych?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 9, 'Wprawdzie mnie samemu wydawało się, że powinienem wiele czynić przeciw imieniu Jezusa z Nazaretu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 10, 'Tak też czyniłem w Jerozolimie, gdzie wielu świętych wtrącałem do więzienia, wziąwszy upoważnienie od naczelnych kapłanów, a kiedy skazywano ich na śmierć, głosowałem przeciwko nim;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 11, 'A po wszystkich synagogach często ich karząc, zmuszałem do bluźnierstwa. Występując przeciwko nim z wielką wściekłością, prześladowałem ich nawet po obcych miastach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 12, 'Tak jechałem do Damaszku, mając upoważnienie i zlecenie od naczelnych kapłanów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 13, 'W południe, będąc w drodze, ujrzałem, królu, światłość z nieba jaśniejszą niż słońce, która oświeciła mnie i tych, którzy jechali ze mną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 14, 'A gdy wszyscy upadliśmy na ziemię, usłyszałem głos mówiący do mnie po hebrajsku: Saulu, Saulu, dlaczego mnie prześladujesz? Trudno ci przeciw ościeniowi wierzgać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 15, 'A ja zapytałem: Kim jesteś, Panie? A on odpowiedział: Ja jestem Jezus, którego ty prześladujesz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 16, 'Ale podnieś się i stań na nogi, bo ukazałem się tobie, żeby ustanowić cię sługą i świadkiem zarówno tych rzeczy, które widziałeś, jak i innych, w których ci się objawię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 17, 'Wybawię cię od tego ludu i od pogan, do których cię teraz posyłam;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 18, 'Dla otworzenia ich oczu, aby odwrócić ich od ciemności do światła, od mocy szatana do Boga, aby otrzymali przebaczenie grzechów i dziedzictwo między uświęconymi przez wiarę we mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 19, 'Dlatego też, królu Agryppo, nie byłem nieposłuszny temu niebieskiemu widzeniu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 20, 'Ale głosiłem najpierw tym, którzy są w Damaszku, w Jerozolimie, w całej Judei, i poganom, żeby pokutowali i nawrócili się do Boga, i spełniali uczynki godne pokuty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 21, 'Z tego powodu Żydzi schwytali mnie w świątyni i chcieli zabić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 22, 'Ale dzięki pomocy Boga żyję do dzisiaj, dając świadectwo małym i wielkim, nic nie mówiąc oprócz tego, co powiedzieli prorocy i Mojżesz, że nastąpi;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 23, 'Że Chrystus ma cierpieć, jako pierwszy zmartwychwstać i zwiastować światłość temu ludowi i poganom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 24, 'Gdy on to powiedział w swojej obronie, Festus odezwał się donośnym głosem: Jesteś szalony, Pawle! Wielka uczoność doprowadza cię do szaleństwa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 25, 'Ale on odpowiedział: Nie jestem szalony, dostojny Festusie, ale głoszę słowa prawdy i rozsądku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 26, 'Król bowiem, przed którym śmiało mówię, wie o tych sprawach, gdyż jestem przekonany, że nic z tych rzeczy nie jest przed nim ukryte, ponieważ nie działo się to w jakimś zakątku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 27, 'Czy wierzysz, królu Agryppo, prorokom? Wiem, że wierzysz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 28, 'Wtedy Agryppa powiedział do Pawła: Niemal przekonałeś mnie, żebym został chrześcijaninem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 29, 'Ale Paweł powiedział: Dałby Bóg, abyś i niemal, i całkowicie nie tylko ty, ale i wszyscy, którzy mnie dziś słuchają, stali się takimi, jakim ja jestem, z wyjątkiem tych więzów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 30, 'A gdy to powiedział, wstał król, namiestnik, Berenike i ci, którzy z nimi zasiadali.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 31, 'Kiedy się oddalili, rozmawiali między sobą: Ten człowiek nie czyni nic, co zasługiwałoby na śmierć lub więzienie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 32, 'Agryppa zaś powiedział do Festusa: Można by zwolnić tego człowieka, gdyby nie odwołał się do cesarza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 1, 'A gdy postanowiono, że mamy płynąć do Italii, oddano Pawła i innych więźniów setnikowi, imieniem Juliusz, z oddziału Augusta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 2, 'Wsiedliśmy na statek adramyteński, który miał płynąć wzdłuż wybrzeża Azji, i odbiliśmy od brzegu. Był też z nami Arystarch, Macedończyk z Tesaloniki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 3, 'Następnego dnia przypłynęliśmy do Sydonu, gdzie Juliusz, który życzliwie odnosił się do Pawła, pozwolił mu iść do przyjaciół, aby doznał pokrzepienia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 4, 'A wyruszywszy stamtąd, płynęliśmy pod osłoną Cypru, dlatego że wiatry były przeciwne.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 5, 'Przepłynęliśmy morze na wysokości Cylicji i Pamfilii i przybyliśmy do Miry w Licji.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 6, 'Tam setnik znalazł statek aleksandryjski płynący do Italii i umieścił nas na nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 7, 'A gdy przez wiele dni płynęliśmy wolno i dotarliśmy zaledwie na wysokość Knidos, ponieważ wiatr nam nie pozwalał, popłynęliśmy wzdłuż Krety obok Salmone.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 8, 'A płynąc z trudem wzdłuż jej brzegów, dotarliśmy do pewnego miejsca zwanego Piękne Porty, blisko którego było miasto Lasaia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 9, 'Gdy upłynęło wiele czasu i żegluga stała się niebezpieczna, bo minął już post, Paweł ich przestrzegał:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 10, 'Panowie, widzę, że żegluga będzie związana z krzywdą i wielką szkodą nie tylko ładunkowi i statkowi, ale i naszemu życiu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 11, 'Setnik jednak bardziej ufał sternikowi i właścicielowi statku niż temu, co mówił Paweł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 12, 'A ponieważ żaden port nie nadawał się do przezimowania, większość postanowiła stamtąd odpłynąć, dostać się jakoś na przezimowanie do portu Feniks na Krecie, otwartego na południowo-zachodnią i północno-zachodnią stronę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 13, 'A gdy powiał wiatr z południa, sądzili, że zamiar doprowadzą do skutku, i odbili od brzegu, i popłynęli wzdłuż Krety.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 14, 'Lecz niedługo potem uderzył na nią gwałtowny wiatr, zwany Eurokludon.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 15, 'Kiedy statek został porwany i nie mógł stawić czoła wiatrowi, puściliśmy go z wiatrem i pozwoliliśmy się unosić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 16, 'Gdy płynęliśmy wzdłuż pewnej wysepki, zwanej Klauda, z trudem zdołaliśmy uchwycić łódź ratunkową.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 17, 'Po wyciągnięciu jej przepasali statek, używając sprzętu pomocniczego. Z obawy, żeby nie wpaść na płyciznę, opuścili żagle i tak ich niosło.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 18, 'Ponieważ miotała nami gwałtowna burza, nazajutrz wyrzucili ładunek.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 19, 'A trzeciego dnia własnymi rękami wyrzuciliśmy osprzęt statku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 20, 'Lecz kiedy przez wiele dni nie pokazało się ani słońce, ani gwiazdy, a niemała nawałnica napierała, znikła już wszelka nadzieja naszego ocalenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 21, 'Gdy ludzie już długo nic nie jedli, Paweł stanął pośród nich i powiedział: Panowie, trzeba było mnie posłuchać i nie odpływać od Krety, wtedy uniknęlibyście straty i szkody.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 22, 'Lecz teraz zachęcam was, abyście byli dobrej myśli, bo nikt z was nie zginie, tylko statek.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 23, 'Tej nocy bowiem stanął przy mnie anioł Boga, do którego należę i któremu służę;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 24, 'I powiedział: Nie bój się, Pawle, musisz stanąć przed cesarzem, a oto Bóg darował ci wszystkich, którzy z tobą płyną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 25, 'Dlatego bądźcie dobrej myśli, panowie, bo wierzę Bogu, że będzie tak, jak mi powiedziano.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 26, 'Musimy jednak być wyrzuceni na jakąś wyspę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 27, 'A gdy nadeszła czternasta noc, a nas rzucało po Adriatyku, około północy zdawało się żeglarzom, że zbliżają się do jakiegoś lądu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 28, 'Wtedy spuścili sondę i stwierdzili dwadzieścia sążni. Popłynąwszy nieco dalej, znowu spuścili sondę i stwierdzili piętnaście sążni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 29, 'Bojąc się, abyśmy nie wpadli na skały, zrzucili z rufy cztery kotwice i z upragnieniem oczekiwali świtu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 30, 'A gdy żeglarze postanowili uciec ze statku, spuścili łódź ratunkową pod pozorem zrzucenia kotwic z dziobu statku;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 31, 'Paweł powiedział do setnika i żołnierzy: Jeśli ci nie zostaną na statku, nie będziecie mogli zostać ocaleni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 32, 'Wtedy żołnierze odcięli liny od łodzi ratunkowej i pozwolili jej spaść.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 33, 'Kiedy zaczynało świtać, Paweł zachęcał wszystkich do posiłku: Dziś już czternasty dzień, jak trwacie w oczekiwaniu bez posiłku, nic nie jedząc.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 34, 'Dlatego proszę was, abyście się posilili, bo to przyczyni się do waszego ocalenia, gdyż żadnemu z was włos z głowy nie spadnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 35, 'A to powiedziawszy, wziął chleb i podziękował Bogu wobec wszystkich, a gdy złamał, zaczął jeść.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 36, 'Wtedy wszyscy nabrali otuchy i posilili się.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 37, 'A nas wszystkich na statku było dwieście siedemdziesiąt sześć dusz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 38, 'Kiedy się najedli, odciążyli statek, wyrzucając zboże do morza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 39, 'Gdy nastał dzień, nie rozpoznali lądu, jednak zobaczyli jakąś zatokę o płaskim wybrzeżu, do którego postanowili, jeśli będzie można, przybić statkiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 40, 'Wyciągnąwszy więc kotwice, puścili się na morze. Poluzowali wiązania sterowe, nastawili przedni żagiel pod wiatr i zmierzali do brzegu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 41, 'Wpadli jednak na mieliznę utworzoną między dwoma prądami i osiedli ze statkiem. Dziób statku się zarył, ale rufa zaczęła się rozbijać pod naporem fal.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 42, 'Wtedy żołnierze postanowili, że zabiją więźniów, aby żaden z nich nie odpłynął i nie uciekł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 43, 'Lecz setnik, chcąc ocalić Pawła, powstrzymał ich od tego zamiaru. Potem rozkazał, aby ci, którzy umieją pływać, skoczyli pierwsi do morza i wyszli na brzeg;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 44, 'Pozostali zaś na deskach lub częściach statku. I w ten sposób wszyscy cało wyszli na ląd.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 1, 'Po ocaleniu dowiedzieli się, że ta wyspa nazywa się Malta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 2, 'A barbarzyńcy okazali nam niezwykłą życzliwość. Rozpalili bowiem ognisko i przyjęli nas, bo padał deszcz i było zimno.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 3, 'A gdy Paweł nazbierał naręcze chrustu i nałożył na ogień, na skutek gorąca wypełzła żmija i uczepiła się jego ręki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 4, 'Kiedy barbarzyńcy zobaczyli gada wiszącego u jego ręki, mówili między sobą: Ten człowiek na pewno jest mordercą, bo choć wyszedł cało z morza, zemsta nie pozwala mu żyć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 5, 'Lecz on strząsnął gada w ogień i nie doznał nic złego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 6, 'A oni oczekiwali, że spuchnie albo nagle padnie martwy. Lecz gdy długo czekali i widzieli, że nic złego mu się nie stało, zmienili zdanie i mówili, że jest bogiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 7, 'W pobliżu tego miejsca znajdowały się posiadłości naczelnika wyspy, imieniem Publiusz, który nas przyjął i przez trzy dni po przyjacielsku gościł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 8, 'A ojciec Publiusza leżał, bo miał gorączkę i czerwonkę. Paweł poszedł do niego i modlił się, a położywszy na nim ręce, uzdrowił go.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 9, 'Po tym wydarzeniu przychodzili również inni chorzy z wyspy i byli uzdrawiani.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 10, 'Okazali nam oni wielki szacunek, a gdy mieliśmy odpływać, dali wszystko, co nam było potrzebne.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 11, 'Po trzech miesiącach odpłynęliśmy na statku aleksandryjskim z godłem Kastora i Polluksa, który przezimował na tej wyspie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 12, 'Przybywszy do Syrakuz, pozostaliśmy tam trzy dni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 13, 'Stamtąd, płynąc łukiem, dotarliśmy do Regium. Po upływie jednego dnia, gdy powiał wiatr południowy, nazajutrz przypłynęliśmy do Puteoli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 14, 'Tam spotkaliśmy braci, którzy nas uprosili, żebyśmy pozostali u nich siedem dni. I tak udaliśmy się do Rzymu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 15, 'Tamtejsi bracia, gdy usłyszeli o nas, wyszli nam naprzeciw aż do Forum Appiusza i do Trzech Gospód. Kiedy Paweł ich zobaczył, podziękował Bogu i nabrał otuchy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 16, 'A gdy przybyliśmy do Rzymu, setnik oddał więźniów dowódcy wojska, ale Pawłowi pozwolono mieszkać osobno z żołnierzem, który go pilnował.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 17, 'Po trzech dniach Paweł zaprosił przywódców żydowskich. Kiedy się zeszli, powiedział do nich: Mężowie bracia, nic nie uczyniłem przeciwko ludowi i zwyczajom ojczystym, a jednak zostałem wydany w Jerozolimie jako więzień w ręce Rzymian;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 18, 'Którzy po przesłuchaniu chcieli mnie wypuścić, bo nie było we mnie nic zasługującego na śmierć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 19, 'Lecz gdy Żydzi się temu sprzeciwiali, musiałem odwołać się do cesarza, nie chcąc jednak w czymkolwiek oskarżać mego narodu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 20, 'Dlatego też zaprosiłem was, aby się z wami zobaczyć i porozmawiać, bo z powodu nadziei Izraela jestem związany tym łańcuchem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 21, 'Lecz oni powiedzieli do niego: Nie otrzymaliśmy z Judei żadnych listów o tobie ani żaden z przybyłych braci nie oznajmił, ani nie mówił o tobie nic złego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 22, 'Pragniemy jednak od ciebie usłyszeć, co myślisz, bo wiemy o tym stronnictwie, że wszędzie mówią przeciwko niemu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 23, 'Wyznaczyli mu dzień i przyszło wielu do niego do kwatery, a on od rana do wieczora przytaczał im świadectwa o królestwie Bożym i przekonywał o Jezusie na podstawie Prawa Mojżesza i Proroków.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 24, 'I niektórzy uwierzyli temu, co mówił, a inni nie uwierzyli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 25, 'Poróżnieni ze sobą rozeszli się, gdy Paweł powiedział to jedno: Słusznie Duch Święty powiedział przez proroka Izajasza do naszych ojców:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 26, 'Idź do tego ludu i mów: Słuchając, będziecie słyszeć, ale nie zrozumiecie, i patrząc, będziecie widzieć, ale nie zobaczycie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 27, 'Utyło bowiem serce tego ludu, stępiały ich uszy i zamknęli swe oczy, żeby oczami nie widzieli ani uszami nie słyszeli, a sercem nie zrozumieli i nie nawrócili się, i żebym ich nie uzdrowił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 28, 'Niech wam więc będzie wiadome, że poganom zostało posłane to zbawienie Boże, a oni będą słuchać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 29, 'A gdy to powiedział, Żydzi odeszli, wiodąc ze sobą zacięty spór.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 30, 'Przez całe dwa lata Paweł mieszkał w wynajętym mieszkaniu i przyjmował wszystkich, którzy przychodzili do niego;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 31, 'Głosząc królestwo Boże i nauczając tego, co dotyczy Pana Jezusa Chrystusa, ze wszelką odwagą i bez przeszkód.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 1, 'Paweł, sługa Jezusa Chrystusa, powołany apostoł, odłączony do głoszenia ewangelii Boga;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 2, '(Którą przedtem obiecał przez swoich proroków w Pismach świętych);');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 3, 'O jego Synu, Jezusie Chrystusie, naszym Panu, który według ciała pochodził z potomstwa Dawida;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 4, 'A pokazał z mocą, że jest Synem Bożym, według Ducha świętości, przez zmartwychwstanie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 5, 'Przez którego otrzymaliśmy łaskę i apostolstwo, by przywieść do posłuszeństwa wierze wszystkie narody dla jego imienia;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 6, 'Wśród których jesteście i wy, powołani przez Jezusa Chrystusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 7, 'Wszystkim, którzy jesteście w Rzymie, umiłowanym Boga, powołanym świętym: Łaska wam i pokój od Boga, naszego Ojca, i Pana Jezusa Chrystusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 8, 'Najpierw dziękuję mojemu Bogu przez Jezusa Chrystusa za was wszystkich, że wasza wiara słynie na cały świat.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 9, 'Bóg bowiem, któremu służę w moim duchu w ewangelii jego Syna, jest mi świadkiem, że nieustannie czynię wzmiankę o was w moich modlitwach;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 10, 'Zawsze prosząc, żeby wreszcie kiedyś udało mi się za wolą Bożą odbyć podróż do was.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 11, 'Pragnę bowiem zobaczyć was, abym wam mógł udzielić jakiegoś daru duchowego dla waszego utwierdzenia;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 12, 'To znaczy, abyśmy się wzajemnie pocieszyli obopólną wiarą, waszą i moją.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 13, 'A nie chcę, abyście i wy, bracia, nie wiedzieli, że często zamierzałem przybyć do was (ale byłem dotąd zatrzymywany), abym miał jakiś owoc zarówno wśród was, jak i wśród innych pogan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 14, 'Jestem dłużnikiem zarówno Greków, jak i barbarzyńców, zarówno mądrych, jak i niemądrych;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 15, 'Tak że na ile mogę, jestem gotowy i wam, którzy jesteście w Rzymie, głosić ewangelię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 16, 'Nie wstydzę się bowiem ewangelii Chrystusa, ponieważ jest ona mocą Boga ku zbawieniu dla każdego, kto uwierzy, najpierw Żyda, potem i Greka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 17, 'W niej bowiem objawia się sprawiedliwość Boga z wiary w wiarę, jak jest napisane: Sprawiedliwy będzie żył z wiary.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 18, 'Gniew Boży bowiem objawia się z nieba przeciwko wszelkiej bezbożności i niesprawiedliwości ludzi, którzy zatrzymują prawdę w niesprawiedliwości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 19, 'Ponieważ to, co można wiedzieć o Bogu, jest dla nich jawne, gdyż Bóg im to objawił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 20, 'To bowiem, co niewidzialne, to znaczy jego wieczna moc i bóstwo, są widzialne od stworzenia świata przez to, co stworzone, po to, aby oni byli bez wymówki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 21, 'Dlatego że poznawszy Boga, nie chwalili go jako Boga ani mu nie dziękowali, lecz znikczemnieli w swoich myślach i zaćmiło się ich bezrozumne serce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 22, 'Podając się za mądrych, zgłupieli;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 23, 'I zamienili chwałę niezniszczalnego Boga na podobieństwo obrazu zniszczalnego człowieka, ptaków, czworonożnych zwierząt i gadów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 24, 'Dlatego też Bóg wydał ich nieczystości przez pożądliwości ich serc, aby hańbili swoje ciała między sobą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 25, 'Oni to zamienili prawdę Bożą w kłamstwo i czcili stworzenie, i służyli jemu raczej niż Stwórcy, który jest błogosławiony na wieki. Amen.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 26, 'Dlatego wydał ich Bóg haniebnym namiętnościom, gdyż nawet ich kobiety zamieniły naturalne współżycie na przeciwne naturze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 27, 'Także mężczyźni, opuściwszy naturalne współżycie z kobietą, zapałali w swej pożądliwości jedni ku drugim, mężczyzna z mężczyzną, popełniając haniebne czyny i ponosząc na sobie samych należną za swój błąd zapłatę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 28, 'A skoro im się nie spodobało zachowanie poznania Boga, wydał ich Bóg na pastwę wypaczonego umysłu, aby robili to, co nie wypada;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 29, 'Będąc napełnieni wszelką nieprawością, nierządem, przewrotnością, chciwością, złośliwością; pełni zazdrości, morderstwa, sporu, podstępu, złych obyczajów;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 30, 'Plotkarze, oszczercy, nienawidzący Boga, zuchwali, pyszni, chełpliwi, wynalazcy złych rzeczy, nieposłuszni rodzicom;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 31, 'Bezrozumni, niedotrzymujący słowa, bez naturalnej miłości, nieprzejednani i bez miłosierdzia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 32, 'Oni to, poznawszy wyrok Boga, że ci, którzy robią takie rzeczy, są godni śmierci, nie tylko sami je robią, ale też pochwalają tych, którzy tak postępują.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 1, 'Dlatego jesteś bez wymówki, człowieku, kimkolwiek jesteś, który osądzasz. W czym bowiem osądzasz drugiego, osądzasz samego siebie, ponieważ ty, który osądzasz drugiego, robisz to samo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 2, 'Lecz wiemy, że sąd Boży jest według prawdy przeciwko tym, którzy robią takie rzeczy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 3, 'Czy myślisz, człowieku, który osądzasz tych, którzy robią takie rzeczy, a sam je robisz, że ty unikniesz sądu Bożego?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 4, 'Czy gardzisz bogactwem jego dobroci, cierpliwości i nieskwapliwości, nie wiedząc, że dobroć Boga prowadzi cię do pokuty?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 5, 'Ty jednak przez swoją zatwardziałość i niepokutujące serce gromadzisz sobie samemu gniew na dzień gniewu i objawienia sprawiedliwego sądu Boga;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 6, 'Który odda każdemu według jego uczynków:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 7, 'Tym, którzy przez wytrwanie w dobrym uczynku szukają chwały, czci i nieśmiertelności, odda życie wieczne;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 8, 'Natomiast swarliwym i nieposłusznym prawdzie, lecz posłusznym niesprawiedliwości, odda zapalczywość i gniew.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 9, 'Utrapienie i ucisk odda duszy każdego człowieka, który popełnia zło, najpierw Żyda, potem i Greka;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 10, 'A chwałę, cześć i pokój każdemu, kto czyni dobro, najpierw Żydowi, potem i Grekowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 11, 'U Boga bowiem nie ma względu na osobę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 12, 'Bo ci, którzy bez prawa zgrzeszyli, bez prawa też zginą, a ci, którzy w prawie zgrzeszyli, przez prawo będą sądzeni;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 13, '(Gdyż nie słuchacze prawa są sprawiedliwi przed Bogiem, ale ci, którzy wypełniają prawo, będą usprawiedliwieni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 14, 'Gdy bowiem poganie, którzy nie mają prawa, z natury czynią to, co jest w prawie, oni, nie mając prawa, sami dla siebie są prawem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 15, 'Oni to ukazują działanie prawa wpisanego w ich serca, za poświadczeniem ich sumienia i myśli wzajemnie się oskarżających lub też usprawiedliwiających);');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 16, 'W dniu, w którym Bóg przez Jezusa Chrystusa będzie sądził skryte sprawy ludzkie według mojej ewangelii.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 17, 'Oto ty się nazywasz Żydem, polegasz na prawie, chlubisz się Bogiem;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 18, 'Znasz jego wolę, rozpoznajesz to, co lepsze, będąc pouczony przez prawo;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 19, 'I uważasz się za przewodnika ślepych, za światłość tych, którzy są w ciemności;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 20, 'Wychowawcę bezrozumnych, nauczyciela niemowląt, mając w prawie kształt wiedzy i prawdy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 21, 'Ty więc, który uczysz drugiego, samego siebie nie uczysz? Ty, który głosisz, że nie wolno kraść, kradniesz?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 22, 'Ty, który mówisz, że nie wolno cudzołożyć, cudzołożysz? Ty, który się brzydzisz bożkami, dopuszczasz się świętokradztwa?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 23, 'Ty, który się chlubisz prawem, przez przekraczanie prawa znieważasz Boga?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 24, 'Ponieważ z waszego powodu, jak jest napisane, poganie bluźnią imieniu Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 25, 'Obrzezanie bowiem jest pożyteczne, jeśli wypełniasz prawo, ale jeśli przekraczasz prawo, twoje obrzezanie staje się nieobrzezaniem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 26, 'Jeśli więc nieobrzezany przestrzega przepisów prawa, czyż jego nieobrzezanie nie będzie uznane za obrzezanie?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 27, 'I ten, który jest nieobrzezany z natury, a wypełnia prawo, osądzi ciebie, który mając literę i obrzezanie, przekraczasz prawo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 28, 'Nie ten bowiem jest Żydem, kto jest Żydem na zewnątrz, ani nie to jest obrzezaniem, co jest na zewnątrz, na ciele;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 29, 'Ale ten jest Żydem, kto jest nim wewnątrz, i to jest obrzezanie, co jest obrzezaniem serca, w duchu, nie w literze, którego chwała nie pochodzi od ludzi, lecz od Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 1, 'Na czym więc polega wyższość Żyda? Albo jaki jest pożytek z obrzezania?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 2, 'Wielki pod każdym względem. Przede wszystkim ten, że im zostały powierzone słowa Boże.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 3, 'Cóż bowiem, jeśli niektórzy nie uwierzyli? Czyż ich niewiara zniweczy wiarę Boga?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 4, 'Nie daj Boże! Przeciwnie, niech Bóg będzie prawdziwy, a każdy człowiek – kłamcą, jak jest napisane: Abyś okazał się sprawiedliwy w swoich słowach i żebyś zwyciężył, gdy będziesz sądzony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 5, 'Jeśli więc nasza niesprawiedliwość uwydatnia sprawiedliwość Boga, cóż powiemy? Czyż niesprawiedliwy jest Bóg, który okazuje gniew? (Mówię po ludzku).');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 6, 'Nie daj Boże! Jak wtedy Bóg mógłby sądzić świat?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 7, 'Jeśli bowiem prawda Boża przez moje kłamstwo obfitowała ku jego chwale, czemuż jeszcze i ja jestem sądzony jako grzesznik?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 8, 'Dlaczego więc nie mówić (jak nas szkalują i jak niektórzy twierdzą, że mówimy): Będziemy robić złe rzeczy, aby przyszły dobre? Ich potępienie jest sprawiedliwe.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 9, 'Cóż więc? Czy przewyższamy ich? Żadną miarą! Ponieważ przedtem dowiedliśmy, że zarówno Żydzi, jak i Grecy, wszyscy są pod grzechem;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 10, 'Jak jest napisane: Nie ma sprawiedliwego, ani jednego;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 11, 'Nie ma rozumnego i nie ma nikogo, kto by szukał Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 12, 'Wszyscy zboczyli z drogi, razem stali się nieużyteczni, nie ma nikogo, kto by czynił dobro, nie ma ani jednego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 13, 'Grobem otwartym jest ich gardło, zdradzają swymi językami, jad żmij pod ich wargami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 14, 'Ich usta pełne są przeklinania i goryczy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 15, 'Ich nogi są szybkie do rozlewu krwi;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 16, 'Zniszczenie i nędza na ich drogach;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 17, 'A drogi pokoju nie poznali.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 18, 'Nie ma bojaźni Bożej przed ich oczami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 19, 'A wiemy, że wszystko, co mówi prawo, mówi do tych, którzy są pod prawem, aby wszystkie usta zostały zamknięte i aby cały świat podlegał karaniu Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 20, 'Dlatego z uczynków prawa nie będzie usprawiedliwione żadne ciało w jego oczach, gdyż przez prawo jest poznanie grzechu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 21, 'Lecz teraz bez prawa została objawiona sprawiedliwość Boga, poświadczona przez prawo i proroków.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 22, 'Jest to sprawiedliwość Boga przez wiarę Jezusa Chrystusa dla wszystkich i na wszystkich wierzących. Nie ma bowiem różnicy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 23, 'Wszyscy bowiem zgrzeszyli i są pozbawieni chwały Boga;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 24, 'A zostają usprawiedliwieni darmo, z jego łaski, przez odkupienie, które jest w Jezusie Chrystusie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 25, 'Jego to Bóg ustanowił przebłaganiem przez wiarę w jego krew, aby okazać swoją sprawiedliwość przez odpuszczenie, w swojej cierpliwości, przedtem popełnionych grzechów;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 26, 'Aby okazać swoją sprawiedliwość w obecnym czasie po to, aby on był sprawiedliwym i usprawiedliwiającym tego, kto wierzy w Jezusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 27, 'Gdzież więc jest powód do chluby? Został wykluczony. Przez jakie prawo? Uczynków? Nie, przez prawo wiary.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 28, 'Tak więc twierdzimy, że człowiek zostaje usprawiedliwiony przez wiarę, bez uczynków prawa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 29, 'Czy Bóg jest jedynie Bogiem Żydów? Czy też nie pogan? Istotnie, i pogan;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 30, 'Ponieważ jeden jest Bóg, który usprawiedliwi obrzezanych z wiary i nieobrzezanych przez wiarę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 31, 'Czy więc obalamy prawo przez wiarę? Nie daj Boże! Przeciwnie, utwierdzamy prawo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 1, 'Cóż więc powiemy, co zyskał Abraham, nasz ojciec, według ciała?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 2, 'Jeśli bowiem Abraham został usprawiedliwiony z uczynków, ma się czym chlubić, ale nie przed Bogiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 3, 'Cóż bowiem mówi Pismo? Abraham uwierzył Bogu i zostało mu to poczytane za sprawiedliwość.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 4, 'A temu, kto pracuje, zapłata nie jest uznana za łaskę, ale za należność.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 5, 'Temu zaś, kto nie pracuje, lecz wierzy w tego, który usprawiedliwia bezbożnego, jego wiara zostaje poczytana za sprawiedliwość.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 6, 'Jak i Dawid mówi, że błogosławiony jest człowiek, któremu Bóg przypisze sprawiedliwość bez uczynków, mówiąc:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 7, 'Błogosławieni, których nieprawości są przebaczone i których grzechy są zakryte.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 8, 'Błogosławiony człowiek, któremu Pan nie poczyta grzechu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 9, 'Czy więc to błogosławieństwo dotyczy tylko obrzezanych, czy też nieobrzezanych? Mówimy przecież, że wiara została Abrahamowi poczytana za sprawiedliwość.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 10, 'Jakże więc została mu poczytana? Gdy był obrzezany czy przed obrzezaniem? Nie po obrzezaniu, ale przed obrzezaniem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 11, 'I przyjął znak obrzezania jako pieczęć sprawiedliwości wiary, którą miał przed obrzezaniem, po to, aby był ojcem wszystkich nieobrzezanych wierzących, aby im też poczytana była sprawiedliwość;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 12, 'I aby był ojcem obrzezania, nie tylko tych, którzy są obrzezani, ale też tych, którzy chodzą śladami wiary naszego ojca Abrahama, którą miał przed obrzezaniem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 13, 'Obietnica bowiem, że ma być dziedzicem świata, nie została dana Abrahamowi czy jego potomstwu przez prawo, ale przez sprawiedliwość wiary.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 14, 'Jeśli bowiem dziedzicami są ci, którzy są z prawa, to wiara stała się daremna i obietnica obróciła się wniwecz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 15, 'Gdyż prawo sprowadza gniew, bo gdzie nie ma prawa, tam nie ma przestępstwa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 16, 'Tak więc dziedzictwo jest z wiary, aby było z łaski i żeby obietnica była niewzruszona dla całego potomstwa, nie tylko dla tego, które opiera się na prawie, ale i dla tego, które jest z wiary Abrahama, który jest ojcem nas wszystkich;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 17, '(Jak jest napisane: Ustanowiłem cię ojcem wielu narodów) przed Bogiem, któremu uwierzył, który ożywia umarłych i przywołuje te rzeczy, których nie ma, tak jakby były.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 18, 'On to wbrew nadziei, mając nadzieję, uwierzył, że stanie się ojcem wielu narodów według tego, co mu powiedziano: Takie będzie twoje potomstwo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 19, 'A nie będąc słabym w wierze, nie zważał na swoje już obumarłe ciało – bo miał około stu lat – ani na obumarłe łono Sary.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 20, 'I nie zachwiał się z powodu niewiary w obietnicę Boga, ale umocnił się wiarą i oddał chwałę Bogu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 21, 'Będąc też pewien tego, że to, co on obiecał, ma moc też uczynić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 22, 'Dlatego zostało mu to poczytane za sprawiedliwość.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 23, 'A nie tylko ze względu na niego samego napisano, że zostało mu to poczytane;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 24, 'Ale i ze względu na nas, którym ma być poczytane, którzy wierzymy w tego, który wskrzesił z martwych Jezusa, naszego Pana;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 25, 'Który został wydany za nasze grzechy i wstał z martwych dla naszego usprawiedliwienia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 1, 'Będąc więc usprawiedliwieni przez wiarę, mamy pokój z Bogiem przez naszego Pana Jezusa Chrystusa;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 2, 'Dzięki któremu też otrzymaliśmy dostęp przez wiarę do tej łaski, w której trwamy i chlubimy się nadzieją chwały Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 3, 'A nie tylko to, ale chlubimy się też uciskami, wiedząc, że ucisk wyrabia cierpliwość;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 4, 'A cierpliwość – doświadczenie, doświadczenie zaś – nadzieję;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 5, 'A nadzieja nie przynosi wstydu, ponieważ miłość Boga jest rozlana w naszych sercach przez Ducha Świętego, który został nam dany.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 6, 'Chrystus bowiem, gdy jeszcze byliśmy słabi, we właściwym czasie umarł za bezbożnych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 7, 'Choć rzadko się zdarza, że ktoś umrze za sprawiedliwego, jednak za dobrego może ktoś odważyłby się umrzeć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 8, 'Lecz Bóg okazuje nam swoją miłość przez to, że gdy jeszcze byliśmy grzesznikami, Chrystus za nas umarł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 9, 'Tym bardziej więc teraz, będąc usprawiedliwieni jego krwią, będziemy przez niego ocaleni od gniewu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 10, 'Jeśli bowiem, będąc nieprzyjaciółmi, zostaliśmy pojednani z Bogiem przez śmierć jego Syna, tym bardziej, będąc pojednani, będziemy ocaleni przez jego życie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 11, 'A nie tylko to, ale też chlubimy się Bogiem przez naszego Pana Jezusa Chrystusa, przez którego teraz otrzymaliśmy pojednanie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 12, 'Dlatego, tak jak przez jednego człowieka grzech wszedł na świat, a przez grzech – śmierć, tak też na wszystkich ludzi przeszła śmierć, ponieważ wszyscy zgrzeszyli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 13, 'Grzech bowiem był na świecie aż do nadania prawa, ale grzechu się nie poczytuje, gdy nie ma prawa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 14, 'Śmierć jednak królowała od Adama aż do Mojżesza nawet nad tymi, którzy nie popełnili grzechu podobnego do przestępstwa Adama, który jest obrazem tego, który miał przyjść.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 15, 'Lecz z przestępstwem nie jest tak, jak z darem łaski. Jeśli bowiem przez przestępstwo jednego wielu umarło, tym obficiej spłynęła na wielu łaska Boga i dar przez łaskę jednego człowieka, Jezusa Chrystusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 16, 'A z darem nie jest tak, jak z tym, co przyszło przez jednego, który zgrzeszył. Wyrok bowiem jest z powodu jednego przestępstwa ku potępieniu, ale dar łaski z powodu wielu przestępstw ku usprawiedliwieniu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 17, 'Jeśli bowiem z powodu przestępstwa jednego śmierć zaczęła królować przez jednego, tym bardziej ci, którzy przyjmują obfitość tej łaski i dar sprawiedliwości, będą królować w życiu przez jednego, Jezusa Chrystusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 18, 'Tak więc, jak przez przestępstwo jednego na wszystkich ludzi spadł wyrok ku potępieniu, tak też przez sprawiedliwość jednego na wszystkich ludzi spłynął dar ku usprawiedliwieniu dającemu życie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 19, 'Jak bowiem przez nieposłuszeństwo jednego człowieka wielu stało się grzesznikami, tak przez posłuszeństwo jednego wielu stało się sprawiedliwymi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 20, 'A prawo wkroczyło po to, aby obfitował grzech. Lecz gdzie grzech się rozmnożył, tam łaska tym bardziej obfitowała;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 21, 'Aby, jak grzech królował ku śmierci, tak też łaska królowała przez sprawiedliwość ku życiu wiecznemu przez Jezusa Chrystusa, naszego Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 1, 'Cóż więc powiemy? Czy mamy trwać w grzechu, aby łaska obfitowała?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 2, 'Nie daj Boże! My, którzy umarliśmy dla grzechu, jakże możemy jeszcze w nim żyć?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 3, 'Czyż nie wiecie, że my wszyscy, którzy zostaliśmy ochrzczeni w Jezusie Chrystusie, w jego śmierci zostaliśmy ochrzczeni?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 4, 'Zostaliśmy więc pogrzebani z nim przez chrzest w śmierci, aby jak Chrystus został wskrzeszony z martwych przez chwałę Ojca, tak żebyśmy i my postępowali w nowości życia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 5, 'Jeśli bowiem zostaliśmy z nim wszczepieni w podobieństwo jego śmierci, to będziemy też z nim wszczepieni w podobieństwo zmartwychwstania;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 6, 'Wiedząc o tym, że nasz stary człowiek został ukrzyżowany razem z nim, aby ciało grzechu zostało zniszczone, żebyśmy już więcej nie służyli grzechowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 7, 'Kto bowiem umarł, został uwolniony od grzechu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 8, 'Jeśli więc umarliśmy z Chrystusem, wierzymy, że też z nim będziemy żyć;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 9, 'Wiedząc, że Chrystus, powstawszy z martwych, więcej nie umiera i śmierć nad nim więcej nie panuje.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 10, 'To bowiem, że umarł, raz umarł dla grzechu, a że żyje, żyje dla Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 11, 'Tak i wy uważajcie siebie za martwych dla grzechu, a żywych dla Boga w Jezusie Chrystusie, naszym Panu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 12, 'Niechże więc grzech nie króluje w waszym śmiertelnym ciele, żebyście mieli mu być posłuszni w jego pożądliwościach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 13, 'I nie oddawajcie waszych członków jako oręża niesprawiedliwości grzechowi, ale oddawajcie samych siebie Bogu jako ożywieni z martwych i wasze członki jako oręż sprawiedliwości Bogu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 14, 'Grzech bowiem nie będzie nad wami panował, bo nie jesteście pod prawem, lecz pod łaską.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 15, 'Cóż więc? Będziemy grzeszyć, bo nie jesteśmy pod prawem, ale pod łaską? Nie daj Boże!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 16, 'Czyż nie wiecie, że komu oddajecie siebie jako słudzy w posłuszeństwo, komu jesteście posłuszni, tego jesteście sługami: bądź grzechu ku śmierci, bądź posłuszeństwa ku sprawiedliwości?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 17, 'Ale chwała Bogu, że gdy byliście sługami grzechu, usłuchaliście z serca wzoru tej nauki, której się poddaliście;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 18, 'A będąc uwolnieni od grzechu, staliście się sługami sprawiedliwości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 19, 'Po ludzku mówię, z powodu słabości waszego ciała. Jak bowiem oddawaliście wasze członki na służbę nieczystości i nieprawości, aby czynić nieprawość, tak teraz oddawajcie wasze członki na służbę sprawiedliwości, abyście byli uświęceni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 20, 'Dopóki bowiem byliście sługami grzechu, byliście wolni od sprawiedliwości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 21, 'Jakiż więc wówczas mieliście pożytek z tych rzeczy, których się teraz wstydzicie? Ich bowiem końcem jest śmierć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 22, 'Lecz teraz, uwolnieni od grzechu, gdy staliście się sługami Boga, macie swój pożytek ku uświęceniu, a na końcu życie wieczne.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 23, 'Zapłatą bowiem za grzech jest śmierć, ale darem łaski Boga jest życie wieczne w Jezusie Chrystusie, naszym Panu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 1, 'Czyż nie wiecie, bracia (bo mówię do znających prawo), że prawo panuje nad człowiekiem, dopóki on żyje?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 2, 'Zamężna kobieta bowiem, dopóki mąż żyje, jest z nim związana prawem, a jeśli mąż umrze, zostaje uwolniona od prawa męża.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 3, 'Tak więc, dopóki mąż żyje, będzie nazywana cudzołożnicą, jeśli zostanie żoną innego mężczyzny. Jeśli jednak jej mąż umrze, jest wolna od tego prawa, tak że nie będzie cudzołożnicą, choćby została żoną innego mężczyzny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 4, 'Tak i wy, moi bracia, zostaliście uśmierceni dla prawa przez ciało Chrystusa, abyście należeli do innego, to znaczy tego, który został wskrzeszony z martwych, abyśmy przynosili Bogu owoc.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 5, 'Gdy bowiem byliśmy w ciele, namiętności grzechów, które się wzniecały przez prawo, okazywały swą moc w naszych członkach, aby przynosić śmierci owoc.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 6, 'Lecz teraz zostaliśmy uwolnieni od prawa, gdy umarliśmy dla tego, w czym byliśmy trzymani, abyśmy służyli Bogu w nowości ducha, a nie w starości litery.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 7, 'Cóż więc powiemy? Że prawo jest grzechem? Nie daj Boże! Przeciwnie, nie poznałem grzechu jak tylko przez prawo, bo i o pożądliwości nie wiedziałbym, gdyby prawo nie mówiło: Nie będziesz pożądał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 8, 'Lecz grzech, gdy zyskał okazję przez przykazanie, wzbudził we mnie wszelką pożądliwość. Bez prawa bowiem grzech jest martwy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 9, 'I ja żyłem kiedyś bez prawa, lecz gdy przyszło przykazanie, grzech ożył, a ja umarłem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 10, 'I okazało się, że przykazanie, które miało być ku życiu, jest mi ku śmierci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 11, 'Grzech bowiem, gdy zyskał okazję przez przykazanie, zwiódł mnie i przez nie mnie zabił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 12, 'A tak prawo jest święte i przykazanie jest święte, sprawiedliwe i dobre.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 13, 'Czy więc to, co dobre, stało się dla mnie śmiercią? Nie daj Boże! Przeciwnie, grzech, aby okazał się grzechem, sprowadził na mnie śmierć przez to, co dobre, żeby grzech stał się niezmiernie grzesznym przez przykazanie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 14, 'Gdyż wiemy, że prawo jest duchowe, ale ja jestem cielesny, zaprzedany grzechowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 15, 'Tego bowiem, co robię, nie pochwalam, bo nie robię tego, co chcę, ale czego nienawidzę, to robię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 16, 'A jeśli robię to, czego nie chcę, zgadzam się z tym, że prawo jest dobre.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 17, 'Teraz więc już nie ja to robię, ale grzech, który we mnie mieszka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 18, 'Gdyż wiem, że we mnie, to jest w moim ciele, nie mieszka dobro, bo chęć jest we mnie, ale wykonać tego, co jest dobre, nie potrafię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 19, 'Nie czynię bowiem dobra, które chcę, ale zło, którego nie chcę, to czynię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 20, 'A jeśli robię to, czego nie chcę, już nie ja to robię, ale grzech, który we mnie mieszka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 21, 'Odkrywam więc w sobie to prawo, że gdy chcę czynić dobro, trzyma się mnie zło.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 22, 'Mam bowiem upodobanie w prawie Bożym według wewnętrznego człowieka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 23, 'Lecz widzę inne prawo w moich członkach, walczące z prawem mego umysłu, które bierze mnie w niewolę prawa grzechu, które jest w moich członkach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 24, 'Nędzny ja człowiek! Któż mnie wybawi z tego ciała śmierci?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 25, 'Dziękuję Bogu przez Jezusa Chrystusa, naszego Pana. Tak więc ja sam umysłem służę prawu Bożemu, lecz ciałem prawu grzechu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 1, 'Dlatego teraz żadnego potępienia nie ma dla tych, którzy są w Jezusie Chrystusie, którzy nie postępują według ciała, ale według Ducha.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 2, 'Gdyż prawo Ducha życia, które jest w Jezusie Chrystusie, uwolniło mnie od prawa grzechu i śmierci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 3, 'Co bowiem było niemożliwe dla prawa, w czym było ono słabe z powodu ciała, Bóg, posławszy swego Syna w podobieństwie grzesznego ciała i z powodu grzechu, potępił grzech w ciele;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 4, 'Aby sprawiedliwość prawa wypełniła się w nas, którzy postępujemy nie według ciała, ale według Ducha.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 5, 'Ci bowiem, którzy żyją według ciała, myślą o tym, co cielesne, ale ci, którzy żyją według Ducha, myślą o tym, co duchowe.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 6, 'Gdyż zamysł ciała to śmierć, ale zamysł Ducha to życie i pokój;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 7, 'Dlatego, że zamysł ciała jest nieprzyjacielem Boga, bo nie poddaje się prawu Bożemu, gdyż i nie może.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 8, 'Ci więc, którzy są w ciele, nie mogą podobać się Bogu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 9, 'Lecz wy nie jesteście w ciele, ale w Duchu, gdyż Duch Boży mieszka w was. A jeśli ktoś nie ma Ducha Chrystusa, ten do niego nie należy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 10, 'Ale jeśli Chrystus jest w was, to ciało jest martwe z powodu grzechu, a duch jest żywy z powodu sprawiedliwości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 11, 'A jeśli Duch tego, który Jezusa wskrzesił z martwych, mieszka w was, ten, który wskrzesił Chrystusa z martwych, ożywi i wasze śmiertelne ciała przez swego Ducha, który w was mieszka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 12, 'Tak więc, bracia, jesteśmy dłużnikami, ale nie ciała, abyśmy mieli żyć według ciała.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 13, 'Jeśli bowiem żyjecie według ciała, umrzecie, ale jeśli Duchem uśmiercacie uczynki ciała, będziecie żyć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 14, 'Wszyscy bowiem ci, którzy są prowadzeni przez Ducha Bożego, są synami Bożymi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 15, 'Gdyż nie otrzymaliście ducha niewoli, aby znowu się bać, ale otrzymaliście Ducha usynowienia, przez którego wołamy: Abba, Ojcze!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 16, 'Ten to Duch poświadcza naszemu duchowi, że jesteśmy dziećmi Bożymi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 17, 'A jeśli dziećmi, to i dziedzicami, dziedzicami Boga, a współdziedzicami Chrystusa, jeśli tylko z nim cierpimy, abyśmy też z nim byli uwielbieni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 18, 'Uważam bowiem, że cierpienia teraźniejszego czasu nie są godne porównywania z tą przyszłą chwałą, która ma się w nas objawić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 19, 'Stworzenie bowiem z gorliwym wypatrywaniem oczekuje objawienia synów Bożych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 20, 'Gdyż stworzenie jest poddane marności, nie dobrowolnie, ale z powodu tego, który je poddał, w nadziei;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 21, 'Że i samo stworzenie będzie uwolnione z niewoli zniszczenia do chwalebnej wolności dzieci Bożych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 22, 'Wiemy bowiem, że całe stworzenie razem jęczy i razem cierpi w bólach rodzenia aż dotąd.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 23, 'A nie tylko ono, ale i my, którzy mamy pierwsze plony Ducha, i my sami w sobie wzdychamy, oczekując usynowienia, odkupienia naszego ciała.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 24, 'Nadzieją bowiem jesteśmy zbawieni. A nadzieja, którą się widzi, nie jest nadzieją, bo jakże ktoś może spodziewać się tego, co widzi?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 25, 'Ale jeśli spodziewamy się tego, czego nie widzimy, to oczekujemy tego z cierpliwością.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 26, 'Podobnie i Duch dopomaga naszej słabości. Nie wiemy bowiem, o co powinniśmy się modlić, jak trzeba, ale sam Duch wstawia się za nami w niewysłowionych westchnieniach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 27, 'A ten, który bada serca, wie, jaki jest zamysł Ducha, ponieważ według woli Boga wstawia się za świętymi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 28, 'A wiemy, że wszystko współdziała dla dobra tych, którzy miłują Boga, to jest tych, którzy są powołani według postanowienia Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 29, 'Tych bowiem, których on przedtem znał, tych też przeznaczył, aby stali się podobni do obrazu jego Syna, żeby on był pierworodny między wieloma braćmi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 30, 'Tych zaś, których przeznaczył, tych też powołał, a których powołał, tych też usprawiedliwił, a których usprawiedliwił, tych też uwielbił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 31, 'Cóż więc na to powiemy? Jeśli Bóg za nami, któż przeciwko nam?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 32, 'On, który nawet własnego Syna nie oszczędził, ale wydał go za nas wszystkich, jakże nie miałby z nim darować nam wszystkiego?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 33, 'Któż będzie oskarżał wybranych Bożych? Bóg jest tym, który usprawiedliwia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 34, 'Któż potępi? Chrystus jest tym, który umarł, więcej, zmartwychwstał, który też jest po prawicy Boga i wstawia się za nami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 35, 'Któż nas odłączy od miłości Chrystusa? Czy utrapienie, czy ucisk, czy prześladowanie, czy głód, czy nagość, czy niebezpieczeństwo, czy miecz?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 36, 'Jak jest napisane: Z powodu ciebie przez cały dzień nas zabijają, uważają nas za owce przeznaczone na rzeź.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 37, 'Ale w tym wszystkim całkowicie zwyciężamy przez tego, który nas umiłował.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 38, 'Jestem bowiem pewien, że ani śmierć, ani życie, ani aniołowie, ani zwierzchności, ani moce, ani teraźniejsze, ani przyszłe rzeczy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 39, 'Ani wysokość, ani głębokość, ani żadne inne stworzenie nie będzie mogło nas odłączyć od miłości Boga, która jest w Jezusie Chrystusie, naszym Panu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 1, 'Mówię prawdę w Chrystusie, nie kłamię, co mi poświadcza moje sumienie w Duchu Świętym;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 2, 'Że odczuwam wielki smutek i nieustający ból w moim sercu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 3, 'Pragnąłbym bowiem sam być odłączony od Chrystusa za moich braci, za moich krewnych według ciała.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 4, 'Są to Izraelici, do których należy usynowienie, chwała, przymierza, nadanie prawa, służba Boża i obietnice;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 5, 'Do których należą ojcowie i z których według ciała pochodzi Chrystus, który jest nad wszystkimi, Bóg błogosławiony na wieki. Amen.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 6, 'Lecz nie jest możliwe, żeby miało zawieść słowo Boże. Nie wszyscy bowiem, którzy pochodzą od Izraela, są Izraelem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 7, 'Nie wszyscy też przez to, że są potomstwem Abrahama, są dziećmi, ale jest powiedziane: W Izaaku będzie nazwane twoje potomstwo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 8, 'To znaczy, że nie dzieci ciała są dziećmi Bożymi, lecz dzieci obietnicy są uznane za potomstwo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 9, 'Takie bowiem jest słowo obietnicy: O tym właśnie czasie przyjdę, a Sara będzie miała syna.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 10, 'A nie tylko to, ale i Rebeka, gdy poczęła z jednego mężczyzny, naszego ojca Izaaka;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 11, 'Gdy dzieci jeszcze się nie urodziły i nie zrobiły nic dobrego ani złego, aby zgodnie z wybraniem trwało postanowienie Boga, nie z uczynków, ale z tego, który powołuje;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 12, 'Powiedziano jej, że starszy będzie służył młodszemu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 13, 'Jak jest napisane: Jakuba umiłowałem, ale Ezawa znienawidziłem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 14, 'Cóż więc powiemy? Czy Bóg jest niesprawiedliwy? Nie daj Boże!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 15, 'Mówi bowiem do Mojżesza: Zmiłuję się, nad kim się zmiłuję, a zlituję się, nad kim się zlituję.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 16, 'A więc nie zależy to od tego, który chce, ani od tego, który zabiega, ale od Boga, który okazuje miłosierdzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 17, 'Pismo bowiem mówi do faraona: Po to właśnie cię wzbudziłem, aby okazać na tobie swoją moc i żeby moje imię było głoszone po całej ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 18, 'A zatem komu chce, okazuje miłosierdzie, a kogo chce, czyni zatwardziałym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 19, 'Ale mi powiesz: Dlaczego więc jeszcze oskarża? Któż bowiem sprzeciwił się jego woli?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 20, 'Człowieku! Kimże ty jesteś, że prowadzisz spór z Bogiem? Czy naczynie gliniane może powiedzieć do tego, kto je ulepił: Dlaczego mnie takim uczyniłeś?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 21, 'Czy garncarz nie ma władzy nad gliną, żeby z tej samej bryły zrobić jedno naczynie do użytku zaszczytnego, a drugie do niezaszczytnego?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 22, 'A cóż, jeśli Bóg, chcąc okazać gniew i dać poznać swoją moc, znosił w wielkiej cierpliwości naczynia gniewu przygotowane na zniszczenie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 23, 'I żeby dać poznać bogactwo swojej chwały na naczyniach miłosierdzia, które wcześniej przygotował ku chwale;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 24, 'To znaczy nas, których powołał, nie tylko z Żydów, ale i z pogan?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 25, 'Jak też u Ozeasza mówi: Lud, który nie był mój, nazwę moim ludem, a tę, która nie była umiłowana, nazwę umiłowaną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 26, 'I stanie się tak, że w miejscu, gdzie im mówiono: Wy nie jesteście moim ludem, tam będą nazwani synami Boga żywego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 27, 'A Izajasz woła o Izraelu: Choćby liczba synów Izraela była jak piasek morski, resztka będzie ocalona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 28, 'Zakończy bowiem dzieło i skróci je w sprawiedliwości. Istotnie, skróci Pan dzieło na ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 29, 'Jak i przedtem powiedział Izajasz: Gdyby Pan zastępów nie zostawił nam potomstwa, stalibyśmy się jak Sodoma i bylibyśmy podobni do Gomory.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 30, 'Cóż więc powiemy? To, że poganie, którzy nie szukali sprawiedliwości, dostąpili sprawiedliwości – sprawiedliwości, która jest z wiary.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 31, 'Izrael zaś, zabiegając o prawo sprawiedliwości, nie doszedł do prawa sprawiedliwości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 32, 'Dlaczego? Ponieważ o nie zabiegali nie z wiary, ale jakby było z uczynków prawa. Potknęli się bowiem o kamień potknięcia;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 33, 'Jak jest napisane: Oto kładę na Syjonie kamień potknięcia i skałę zgorszenia, a każdy, kto w niego wierzy, nie będzie zawstydzony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 1, 'Bracia, pragnieniem mego serca i modlitwą, którą zanoszę do Boga za Izrael, jest jego zbawienie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 2, 'Daję im bowiem świadectwo, że mają gorliwość dla Boga, ale nie według poznania.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 3, 'Nie znając bowiem sprawiedliwości Boga, a chcąc ustanowić własną sprawiedliwość, nie poddali się sprawiedliwości Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 4, 'Końcem bowiem prawa jest Chrystus ku sprawiedliwości każdego, kto wierzy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 5, 'Gdyż Mojżesz pisze o sprawiedliwości, która jest z prawa: Kto te rzeczy wypełnia, przez nie będzie żył.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 6, 'Sprawiedliwość zaś, która jest z wiary, tak powiada: Nie mów w swym sercu: Kto wstąpi do nieba? – to znaczy, aby Chrystusa na dół sprowadzić;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 7, 'Albo: Kto zstąpi do otchłani? – to znaczy, aby Chrystusa od umarłych wyprowadzić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 8, 'Ale cóż mówi: Blisko ciebie jest słowo, na twoich ustach i w twoim sercu. To jest słowo wiary, które głosimy:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 9, 'Jeśli ustami wyznasz Pana Jezusa i uwierzysz w swoim sercu, że Bóg wskrzesił go z martwych, będziesz zbawiony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 10, 'Sercem bowiem wierzy się ku sprawiedliwości, a ustami wyznaje się ku zbawieniu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 11, 'Mówi bowiem Pismo: Każdy, kto w niego wierzy, nie będzie zawstydzony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 12, 'Gdyż nie ma różnicy między Żydem a Grekiem; bo ten sam Pan wszystkich jest bogaty względem wszystkich, którzy go wzywają.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 13, 'Każdy bowiem, kto wezwie imienia Pana, będzie zbawiony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 14, 'Jakże więc będą wzywać tego, w którego nie uwierzyli? A jak uwierzą w tego, o którym nie słyszeli? A jak usłyszą bez kaznodziei?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 15, 'Jakże też będą głosić, jeśli nie zostaną posłani? Jak jest napisane: O jak piękne są nogi tych, którzy opowiadają pokój, tych, którzy opowiadają dobre rzeczy!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 16, 'Ale nie wszyscy byli posłuszni ewangelii. Izajasz bowiem mówi: Panie, któż uwierzył naszemu głoszeniu?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 17, 'Wiara więc jest ze słuchania, a słuchanie – przez słowo Boże.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 18, 'Pytam jednak: Czy nie słyszeli? Ależ tak: Po całej ziemi rozszedł się ich głos i na krańce świata ich słowa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 19, 'Pytam jednak: Czy Izrael tego nie poznał? Mojżesz pierwszy mówi: Ja pobudzę was do zawiści przez naród, który nie jest narodem, przez naród nierozumny wzbudzę w was gniew.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 20, 'A Izajasz śmiało mówi: Zostałem znaleziony przez tych, którzy mnie nie szukali, objawiłem się tym, którzy o mnie nie pytali.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 21, 'Lecz do Izraela mówi: Cały dzień wyciągałem moje ręce do ludu opornego i sprzeciwiającego się.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 1, 'Pytam więc: Czy Bóg odrzucił swój lud? Nie daj Boże! Ja bowiem też jestem Izraelitą, z potomstwa Abrahama, z pokolenia Beniamina.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 2, 'Bóg nie odrzucił swego ludu, który przedtem znał. Czyż nie wiecie, co Pismo mówi o Eliaszu? Jak się skarży przed Bogiem na Izraela:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 3, 'Panie, pozabijali twoich proroków i zburzyli twoje ołtarze; tylko ja sam pozostałem i czyhają na moje życie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 4, 'Ale cóż mu odpowiada Bóg? Zostawiłem sobie siedem tysięcy mężów, którzy nie zgięli kolan przed Baalem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 5, 'Tak i w obecnym czasie pozostała resztka według wybrania przez łaskę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 6, 'A jeśli przez łaskę, to już nie z uczynków, inaczej łaska już nie byłaby łaską. Jeśli zaś z uczynków, to już nie jest łaska, inaczej uczynek już nie byłby uczynkiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 7, 'Cóż więc? Czego Izrael szuka, tego nie osiągnął, ale wybrani osiągnęli, a inni zostali pogrążeni w zatwardziałości;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 8, '(Jak jest napisane: Bóg dał im ducha twardego snu, oczy, aby nie widzieli, i uszy, aby nie słyszeli) aż do dziś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 9, 'A Dawid mówi: Niech ich stół stanie się sidłem i pułapką, zgorszeniem i odpłatą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 10, 'Niech zaćmią się ich oczy, aby nie widzieli, a ich grzbiet zawsze pochylaj.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 11, 'Pytam więc: Czy się potknęli, aby upaść? Nie daj Boże! Ale raczej przez ich upadek zbawienie doszło do pogan, aby wzbudzić w nich zawiść.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 12, 'A jeśli ich upadek jest bogactwem świata, a ich pomniejszenie bogactwem pogan, o ileż bardziej ich pełnia?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 13, 'Mówię bowiem do was, pogan. Na ile jestem apostołem pogan, chlubię się swoją służbą;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 14, 'Może w ten sposób wzbudzę zawiść w tych, którzy są moim ciałem i zbawię niektórych z nich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 15, 'Jeśli bowiem odrzucenie ich stało się pojednaniem dla świata, czym będzie przyjęcie ich, jeśli nie powstaniem z martwych do życia?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 16, 'Ponieważ jeśli zaczyn jest święty, to i ciasto, a jeśli korzeń jest święty, to i gałęzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 17, 'Jeśli zaś niektóre z gałęzi zostały odłamane, a ty, który byłeś dzikim drzewem oliwnym, zostałeś wszczepiony zamiast nich i stałeś się uczestnikiem korzenia i tłustości drzewa oliwnego;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 18, 'Nie wynoś się nad gałęzie. Jeśli jednak się wynosisz, wiedz, że nie ty podtrzymujesz korzeń, lecz korzeń ciebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 19, 'Ale powiesz: Odłamane zostały gałęzie, abym ja został wszczepiony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 20, 'Słusznie, z powodu niewiary zostały odłamane, ty zaś trwasz przez wiarę. Nie pysznij się, ale się bój.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 21, 'Jeśli bowiem Bóg nie oszczędził naturalnych gałęzi, wiedz, że i ciebie nie oszczędzi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 22, 'Spójrz więc na dobroć i srogość Boga: srogość dla tych, którzy upadli, a dla ciebie dobroć, jeśli będziesz trwał w tej dobroci. W przeciwnym razie ty też będziesz wycięty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 23, 'Lecz i oni, jeśli nie będą trwali w niewierze, zostaną wszczepieni, gdyż Bóg ma moc ponownie ich wszczepić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 24, 'Jeśli bowiem ty zostałeś wycięty z dzikiego z natury drzewa oliwnego, a wbrew naturze zostałeś wszczepiony w szlachetne drzewo oliwne, o ileż bardziej ci, którzy są gałęziami naturalnymi, wszczepieni zostaną w swoje własne drzewo oliwne!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 25, 'Nie chcę bowiem, bracia, abyście nie znali tej tajemnicy – żebyście sami siebie nie uważali za mądrych – że zatwardziałość po części przyszła na Izrael, dopóki nie wejdzie pełnia pogan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 26, 'I tak cały Izrael będzie zbawiony, jak jest napisane: Przyjdzie z Syjonu wybawiciel i odwróci bezbożność od Jakuba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 27, 'A to będzie moje przymierze z nimi, gdy zgładzę ich grzechy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 28, 'Tak więc co do ewangelii są nieprzyjaciółmi ze względu na was, lecz co do wybrania są umiłowani ze względu na ojców.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 29, 'Nieodwołalne są bowiem dary i powołanie Boże.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 30, 'Jak bowiem wy kiedyś nie wierzyliście Bogu, ale teraz dostąpiliście miłosierdzia z powodu ich niewiary;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 31, 'Tak i oni teraz stali się nieposłuszni, aby z powodu miłosierdzia wam okazanego i oni miłosierdzia dostąpili.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 32, 'Bóg bowiem zamknął ich wszystkich w niewierze, aby się nad wszystkimi zmiłować.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 33, 'O głębokości bogactwa zarówno mądrości, jak i poznania Boga! Jak niezbadane są jego wyroki i niedocieczone jego drogi!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 34, 'Któż bowiem poznał myśl Pana albo kto był jego doradcą?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 35, 'Lub kto pierwszy mu coś dał, aby otrzymać odpłatę?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 36, 'Z niego bowiem, przez niego i w nim jest wszystko. Jemu chwała na wieki. Amen.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 1, 'Proszę więc was, bracia, przez miłosierdzie Boże, abyście składali wasze ciała jako ofiarę żywą, świętą, przyjemną Bogu, to jest wasza rozumna służba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 2, 'A nie dostosowujcie się do tego świata, ale przemieńcie się przez odnowienie waszego umysłu, abyście mogli rozeznać, co jest dobrą, przyjemną i doskonałą wolą Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 3, 'Mówię bowiem przez łaskę, która mi jest dana, każdemu, kto jest wśród was, aby nie myślał o sobie więcej niż należy, ale żeby myślał o sobie skromnie, stosownie do miary wiary, jakiej Bóg każdemu udzielił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 4, 'Jak bowiem w jednym ciele mamy wiele członków, ale nie wszystkie członki wykonują tę samą czynność;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 5, 'Tak my, chociaż liczni, jesteśmy jednym ciałem w Chrystusie, ale z osobna jesteśmy członkami jedni drugich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 6, 'Mamy więc różne dary według łaski, która nam jest dana: jeśli ktoś ma dar prorokowania, niech go używa stosownie do miary wiary;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 7, 'Jeśli usługiwania, niech usługuje; jeśli ktoś naucza, niech trwa w nauczaniu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 8, 'Jeśli ktoś napomina, to w napominaniu; jeśli ktoś rozdaje, to w szczerości; jeśli ktoś jest przełożonym, niech nim będzie w pilności; jeśli ktoś okazuje miłosierdzie, niech to czyni ochoczo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 9, 'Miłość niech będzie nieobłudna. Brzydźcie się złem, trzymając się tego, co dobre.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 10, 'Miłujcie się wzajemnie miłością braterską, wyprzedzając jedni drugich w okazywaniu szacunku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 11, 'W pracy nieleniwi, pałający duchem, służący Panu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 12, 'Radujący się w nadziei, cierpliwi w ucisku, nieustający w modlitwie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 13, 'Wspomagający świętych w potrzebach, okazujący gościnność.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 14, 'Błogosławcie tych, którzy was prześladują, błogosławcie, a nie przeklinajcie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 15, 'Radujcie się z tymi, którzy się radują, a płaczcie z tymi, którzy płaczą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 16, 'Bądźcie między sobą jednomyślni. Nie miejcie o sobie wysokiego mniemania, ale się ku niskim skłaniajcie. Nie uważajcie samych siebie za mądrych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 17, 'Nikomu złem za zło nie odpłacajcie; starajcie się o to, co uczciwe wobec wszystkich ludzi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 18, 'Jeśli to możliwe, o ile to od was zależy, ze wszystkimi ludźmi żyjcie w pokoju.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 19, 'Najmilsi, nie mścijcie się sami, ale pozostawcie miejsce gniewowi. Jest bowiem napisane: Zemsta do mnie należy, ja odpłacę – mówi Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 20, 'Jeśli więc twój nieprzyjaciel jest głodny, nakarm go, jeśli jest spragniony, napój go. Tak bowiem robiąc, rozżarzone węgle zgarniesz na jego głowę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 21, 'Nie daj się zwyciężyć złu, ale zło dobrem zwyciężaj.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 1, 'Każda dusza niech będzie poddana władzom zwierzchnim. Nie ma bowiem władzy innej, jak tylko od Boga, a te władze, które są, zostały ustanowione przez Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 2, 'Tak więc kto się sprzeciwia władzy, sprzeciwia się postanowieniu Boga. Ci zaś, którzy się sprzeciwiają, sami na siebie ściągają potępienie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 3, 'Przełożeni bowiem nie są postrachem dla uczynków dobrych, ale złych. A chcesz nie bać się władzy? Czyń dobrze, a będziesz miał od niej pochwałę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 4, 'Jest bowiem sługą Boga dla twojego dobra. Ale jeśli czynisz zło, bój się, bo nie na próżno nosi miecz, gdyż jest sługą Boga, mszczącym się w gniewie nad tym, który czyni zło.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 5, 'Dlatego trzeba być poddanym nie tylko z powodu gniewu, ale i ze względu na sumienie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 6, 'Z tego też powodu płacicie podatki. Ci bowiem, którzy tego właśnie ustawicznie pilnują, są sługami Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 7, 'Oddawajcie więc każdemu to, co mu się należy: komu podatek, temu podatek, komu cło, temu cło, komu bojaźń, temu bojaźń, komu cześć, temu cześć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 8, 'Nikomu nie bądźcie nic winni oprócz wzajemnej miłości. Kto bowiem miłuje bliźniego, wypełnił prawo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 9, 'Gdyż to: Nie będziesz cudzołożył, nie będziesz zabijał, nie będziesz kradł, nie będziesz fałszywie świadczył, nie będziesz pożądał i jakiekolwiek inne przykazanie, w tych słowach się streszcza, mianowicie: Będziesz miłował swego bliźniego jak samego siebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 10, 'Miłość nie wyrządza zła bliźniemu. Tak więc wypełnieniem prawa jest miłość.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 11, 'A czyńcie to, znając czas, że już nadeszła pora, abyśmy się obudzili ze snu. Teraz bowiem bliżej nas jest zbawienie, niż kiedy uwierzyliśmy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 12, 'Noc przeminęła, a dzień się przybliżył. Odrzućmy więc uczynki ciemności, a obleczmy się w zbroję światłości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 13, 'Postępujmy uczciwie, jak za dnia, nie w hulankach i pijaństwach, nie w rozwiązłości i rozpustach, nie w sporach ani w zazdrości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 14, 'Ale obleczcie się w Pana Jezusa Chrystusa, a nie troszczcie się o ciało, by zaspokajać pożądliwości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 1, 'A tego, kto jest słaby w wierze, przyjmujcie, lecz nie po to, aby sprzeczać się wokół spornych kwestii.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 2, 'Jeden bowiem wierzy, że może jeść wszystko, a inny, będąc słaby, jada jarzyny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 3, 'Ten, kto je, niech nie lekceważy tego, który nie je, a ten, kto nie je, niech nie potępia tego, który je, bo Bóg go przyjął.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 4, 'Kim jesteś ty, że sądzisz cudzego sługę? Dla własnego Pana stoi albo upada. Ostoi się jednak, gdyż Bóg może go utwierdzić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 5, 'Jeden bowiem czyni różnicę między dniem a dniem, a drugi każdy dzień ocenia jednakowo. Każdy niech będzie dobrze upewniony w swoim zamyśle.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 6, 'Kto przestrzega dnia, dla Pana przestrzega, a kto nie przestrzega dnia, dla Pana nie przestrzega. Kto je, dla Pana je, bo dziękuje Bogu, a kto nie je, dla Pana nie je i dziękuje Bogu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 7, 'Nikt bowiem z nas dla siebie nie żyje i nikt dla siebie nie umiera.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 8, 'Bo jeśli żyjemy, dla Pana żyjemy, jeśli umieramy, dla Pana umieramy. Dlatego czy żyjemy, czy umieramy, należymy do Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 9, 'Gdyż po to Chrystus umarł, powstał i ożył, aby panować i nad umarłymi, i nad żywymi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 10, 'Dlaczego więc ty potępiasz swego brata? Albo czemu lekceważysz swego brata? Wszyscy bowiem staniemy przed trybunałem Chrystusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 11, 'Jest bowiem napisane: Jak żyję, mówi Pan, ugnie się przede mną każde kolano i każdy język będzie wysławiał Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 12, 'Tak więc każdy z nas sam za siebie zda rachunek Bogu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 13, 'A tak już nie osądzajmy jedni drugich, ale raczej uważajcie na to, aby nie dawać bratu powodu do potknięcia się lub upadku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 14, 'Wiem i jestem przekonany przez Pana Jezusa, że nie ma niczego, co by samo w sobie było nieczyste. Tylko dla tego, kto uważa coś za nieczyste, to dla niego jest nieczyste.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 15, 'Lecz jeśli z powodu pokarmu twój brat jest zasmucony, już nie postępujesz zgodnie z miłością. Nie zatracaj swoim pokarmem tego, za którego umarł Chrystus.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 16, 'Niech więc wasze dobro nie będzie bluźnione.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 17, 'Królestwo Boże bowiem to nie pokarm i napój, ale sprawiedliwość, pokój i radość w Duchu Świętym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 18, 'Kto bowiem w tym służy Chrystusowi, podoba się Bogu i cieszy się uznaniem u ludzi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 19, 'Tak więc dążmy do tego, co służy pokojowi i wzajemnemu zbudowaniu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 20, 'Z powodu pokarmu nie niszcz dzieła Bożego. Wszystko wprawdzie jest czyste, ale staje się złe dla człowieka, który je ze zgorszeniem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 21, 'Dobrze jest nie jeść mięsa i nie pić wina ani żadnej rzeczy, przez którą twój brat się obraża, gorszy albo słabnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 22, 'Masz wiarę? Miej ją sam u siebie przed Bogiem. Szczęśliwy ten, kto samego siebie nie potępia w tym, co uważa za dobre.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 23, 'Lecz kto ma wątpliwości, jeśli je, jest potępiony, bo nie je z wiary. Wszystko bowiem, co nie jest z wiary, jest grzechem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 1, 'A tak my, którzy jesteśmy mocni, powinniśmy znosić słabości słabych, a nie szukać tego, co nam się podoba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 2, 'Dlatego każdy z nas niech szuka tego, co podoba się bliźniemu, dla dobra, ku zbudowaniu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 3, 'Ponieważ i Chrystus nie szukał tego, co mu się podobało, ale jak jest napisane: Urągania urągających tobie spadły na mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 4, 'Wszystko bowiem, co przedtem napisano, ku naszej nauce napisano, abyśmy przez cierpliwość i pociechę z Pism mieli nadzieję.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 5, 'A Bóg cierpliwości i pociechy niech sprawi, abyście byli jednomyślni między sobą na wzór Jezusa Chrystusa;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 6, 'Abyście jednomyślnie, jednymi ustami wysławiali Boga, Ojca naszego Pana Jezusa Chrystusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 7, 'Dlatego przyjmujcie siebie nawzajem, jak i Chrystus przyjął nas do chwały Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 8, 'Mówię bowiem, że Jezus Chrystus był sługą obrzezania ze względu na prawdę Bożą, aby potwierdzić obietnice dane ojcom;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 9, 'I aby poganie chwalili Boga za miłosierdzie, jak jest napisane: Dlatego będę cię wysławiał między poganami i będę śpiewał twemu imieniu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 10, 'I znowu mówi: Weselcie się, poganie, z jego ludem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 11, 'I znowu: Chwalcie Pana, wszyscy poganie, i wysławiajcie go wszyscy ludzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 12, 'I znowu Izajasz mówi: Przyjdzie korzeń Jessego, ten, który powstanie, aby panować nad poganami. W nim poganie będą pokładać nadzieję.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 13, 'A Bóg nadziei niech was napełni wszelką radością i pokojem w wierze, abyście obfitowali w nadzieję przez moc Ducha Świętego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 14, 'A też ja sam jestem pewien co do was, moi bracia, że i wy sami jesteście pełni dobroci, napełnieni wszelkim poznaniem i możecie jedni drugich napominać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 15, 'A pisałem do was, bracia, nieco śmielej, jakby przypominając wam przez łaskę, która jest mi dana od Boga;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 16, 'Po to, abym był sługą Jezusa Chrystusa dla pogan, sprawując święte usługiwanie ewangelią Boga, aby ofiara pogan stała się przyjemna, uświęcona przez Ducha Świętego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 17, 'Mam się więc czym chlubić w Jezusie Chrystusie, w sprawach Bożych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 18, 'Nie śmiałbym bowiem mówić tego, czego Chrystus nie uczyniłby przeze mnie w przywodzeniu pogan do posłuszeństwa przez słowo i uczynek;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 19, 'Przez moc znaków i cudów, przez moc Ducha Bożego, tak że obszar od Jerozolimy i okolic aż do Ilirii napełniłem ewangelią Chrystusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 20, 'A usiłowałem głosić ewangelię tam, gdzie imię Chrystusa nie było znane, aby nie budować na cudzym fundamencie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 21, 'Ale jak jest napisane: Ci, którym o nim nie mówiono, zobaczą, a ci, którzy o nim nie słyszeli, zrozumieją.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 22, 'Dlatego też często napotykałem przeszkody, tak że nie mogłem przyjść do was.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 23, 'Lecz teraz nie mam już miejsca do pracy w tych stronach, a pragnąc od wielu lat przyjść do was;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 24, 'Gdy udam się do Hiszpanii, przyjdę do was. Spodziewam się bowiem, że idąc tamtędy, zobaczę was i że wy mnie tam wyprawicie, gdy się już wami troszeczkę nacieszę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 25, 'A teraz idę do Jerozolimy, aby usłużyć świętym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 26, 'Spodobało się bowiem Macedonii i Achai wspólnie złożyć się na ubogich świętych, którzy są w Jerozolimie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 27, 'Istotnie, spodobało się im, są też ich dłużnikami. Jeśli bowiem poganie stali się uczestnikami ich dóbr duchowych, powinni im też usługiwać cielesnymi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 28, 'Dlatego, gdy to wykonam i oddam im ten zapieczętowany owoc, wstąpię do was, udając się do Hiszpanii.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 29, 'A wiem, że gdy przyjdę do was, przyjdę z pełnią błogosławieństwa ewangelii Chrystusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 30, 'A proszę was, bracia, przez naszego Pana Jezusa Chrystusa i przez miłość Ducha, abyście razem ze mną walczyli w modlitwach za mnie do Boga;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 31, 'Abym został wybawiony od tych, którzy są niewierzący w Judei, i żeby moja posługa, którą wykonuję dla Jerozolimy, została dobrze przyjęta przez świętych;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 32, 'Abym z radością przyszedł do was za wolą Boga i doznał pokrzepienia razem z wami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 33, 'A Bóg pokoju niech będzie z wami wszystkimi. Amen.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 1, 'Polecam wam Febę, naszą siostrę, która jest służebnicą kościoła w Kenchrach;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 2, 'Abyście ją przyjęli w Panu, jak przystoi świętym, i pomagali jej w każdej sprawie, w której by was potrzebowała. I ona bowiem wspomagała wielu, także i mnie samego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 3, 'Pozdrówcie Pryscyllę i Akwilę, moich pomocników w Jezusie Chrystusie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 4, 'Którzy za moje życie nadstawiali swojego własnego karku, którym nie tylko ja sam dziękuję, ale i wszystkie kościoły pogan;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 5, 'Pozdrówcie także kościół, który jest w ich domu. Pozdrówcie mojego miłego Epeneta, który jest pierwszym plonem Achai dla Chrystusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 6, 'Pozdrówcie Marię, która wiele pracowała dla nas.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 7, 'Pozdrówcie Andronika i Juniasa, moich krewnych i moich współwięźniów, którzy są poważani wśród apostołów, którzy też przede mną byli w Chrystusie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 8, 'Pozdrówcie Ampliasa, mojego umiłowanego w Panu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 9, 'Pozdrówcie Urbana, naszego pomocnika w Chrystusie, i mojego umiłowanego Stachyna.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 10, 'Pozdrówcie Apellesa, wypróbowanego w Chrystusie. Pozdrówcie tych, którzy są z domu Arystobula.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 11, 'Pozdrówcie Herodiona, mojego krewnego. Pozdrówcie tych, którzy są z domu Narcyza, tych, którzy są w Panu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 12, 'Pozdrówcie Tryfenę i Tryfozę, które pracują w Panu. Pozdrówcie umiłowaną Persydę, która wiele pracowała w Panu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 13, 'Pozdrówcie Rufusa, wybranego w Panu, oraz matkę jego i moją.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 14, 'Pozdrówcie Asynkryta, Flegonta, Hermasa, Patrobę, Hermesa i braci, którzy są z nimi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 15, 'Pozdrówcie Filologa i Julię, Nereusza i jego siostrę, Olimpasa i wszystkich świętych, którzy są z nimi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 16, 'Pozdrówcie jedni drugich pocałunkiem świętym. Pozdrawiają was kościoły Chrystusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 17, 'A proszę was, bracia, abyście wypatrywali tych, którzy powodują rozłamy i zgorszenia przeciwko tej nauce, którą przyjęliście; unikajcie ich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 18, 'Gdyż tacy nie służą naszemu Panu Jezusowi Chrystusowi, ale własnemu brzuchowi, a przez gładkie słowa i pochlebstwo zwodzą serca prostych ludzi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 19, 'Wasze posłuszeństwo bowiem stało się znane wszystkim. Dlatego też raduję się z waszego powodu, ale chcę, abyście byli mądrzy w tym, co dobre, a prości w tym, co złe.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 20, 'A Bóg pokoju wkrótce zetrze szatana pod waszymi stopami. Łaska naszego Pana Jezusa Chrystusa niech będzie z wami. Amen.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 21, 'Pozdrawia was mój współpracownik Tymoteusz oraz Lucjusz, Jazon i Sozypater, moi krewni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 22, 'Pozdrawiam was w Panu ja, Tercjusz, który pisałem ten list.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 23, 'Pozdrawia was Gajus, gospodarz mój i całego kościoła. Pozdrawia was Erastus, szafarz miejski, i Kwartus, brat.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 24, 'Łaska naszego Pana Jezusa Chrystusa niech będzie z wami wszystkimi. Amen.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 25, 'A temu, który was może utwierdzić według mojej ewangelii i głoszenia Jezusa Chrystusa, według objawienia tajemnicy od wieków okrytej milczeniem;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 26, 'Lecz teraz objawionej i przez Pisma proroków według postanowienia wiecznego Boga oznajmionej wszystkim narodom, by przywieść je do posłuszeństwa wierze;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 27, 'Temu, jedynemu mądremu Bogu, niech będzie chwała przez Jezusa Chrystusa na wieki. Amen. List do Rzymian został napisany z Koryntu i wysłany przez Febę, służebnicę kościoła w Kenchrach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 1, 'Paweł, powołany apostoł Jezusa Chrystusa z woli Boga, i Sostenes, brat;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 2, 'Do kościoła Bożego w Koryncie, do uświęconych w Chrystusie Jezusie, powołanych świętych, ze wszystkimi, którzy w każdym miejscu wzywają imienia naszego Pana Jezusa Chrystusa, ich i naszego Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 3, 'Łaska wam i pokój od Boga, naszego Ojca, i Pana Jezusa Chrystusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 4, 'Zawsze dziękuję mojemu Bogu za was, za łaskę Bożą, która została wam dana w Chrystusie Jezusie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 5, 'We wszystko bowiem jesteście wzbogaceni w nim, we wszelkie słowo i wszelkie poznanie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 6, 'Gdyż świadectwo Chrystusa jest utwierdzone w was;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 7, 'Tak że żadnego daru nie brakuje wam, którzy oczekujecie objawienia naszego Pana Jezusa Chrystusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 8, 'On też utwierdzi was aż do końca, abyście byli nienaganni w dniu naszego Pana Jezusa Chrystusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 9, 'Wierny jest Bóg, przez którego zostaliście powołani do społeczności jego Syna, Jezusa Chrystusa, naszego Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 10, 'Proszę więc was, bracia, przez imię naszego Pana Jezusa Chrystusa, żebyście wszyscy to samo mówili i żeby nie było wśród was rozłamów, ale abyście byli zespoleni jednakowym umysłem i jednakowym zdaniem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 11, 'Doniesiono mi bowiem o was, moi bracia, przez domowników Chloe, że są wśród was spory.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 12, 'Mówię to dlatego, że każdy z was twierdzi: Ja jestem Pawła, ja Apollosa, ja Kefasa, a ja Chrystusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 13, 'Czy Chrystus jest podzielony? Czy Paweł został za was ukrzyżowany? Czy w imię Pawła zostaliście ochrzczeni?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 14, 'Dziękuję Bogu, że oprócz Kryspusa i Gajusa nikogo z was nie ochrzciłem;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 15, 'Aby nikt nie powiedział, że chrzciłem w swoje imię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 16, 'Ochrzciłem też dom Stefanasa. Poza tym nie wiem, czy ochrzciłem jeszcze kogoś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 17, 'Bo Chrystus nie posłał mnie, abym chrzcił, ale abym głosił ewangelię, i to nie w mądrości słowa, aby nie zniweczyć krzyża Chrystusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 18, 'Mowa o krzyżu bowiem jest głupstwem dla tych, którzy giną, ale dla nas, którzy jesteśmy zbawieni, jest mocą Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 19, 'Bo jest napisane: Wytracę mądrość mądrych, a rozum rozumnych obrócę wniwecz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 20, 'Gdzie jest mądry? Gdzie uczony w Piśmie? Gdzie badacz tego świata? Czyż Bóg nie obrócił w głupstwo mądrości tego świata?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 21, 'Skoro bowiem w mądrości Bożej świat nie poznał Boga przez mądrość, upodobało się Bogu przez głupstwo głoszenia zbawić tych, którzy wierzą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 22, 'Gdyż Żydzi domagają się znaków, a Grecy szukają mądrości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 23, 'My zaś głosimy Chrystusa ukrzyżowanego, który dla Żydów wprawdzie jest zgorszeniem, a dla Greków głupstwem;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 24, 'Lecz dla tych, którzy są powołani, zarówno dla Żydów, jak i Greków, głosimy Chrystusa – moc Bożą i mądrość Bożą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 25, 'Głupstwo Boże bowiem jest mądrzejsze niż ludzie, a słabość Boża jest mocniejsza niż ludzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 26, 'Przypatrzcie się bowiem, bracia, waszemu powołaniu, że niewielu jest mądrych według ciała, niewielu możnych, niewielu szlachetnie urodzonych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 27, 'Ale Bóg wybrał to, co głupie u świata, aby zawstydzić mądrych, wybrał to, co słabe u świata, aby zawstydzić mocnych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 28, 'I to, co nieszlachetne u świata i wzgardzone, wybrał Bóg, a nawet to, co nie jest, aby to, co jest, obrócić wniwecz;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 29, 'Aby nie chlubiło się przed nim żadne ciało.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 30, 'Lecz wy z niego jesteście w Chrystusie Jezusie, który stał się dla nas mądrością od Boga i sprawiedliwością, i uświęceniem, i odkupieniem;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 31, 'Aby, jak to jest napisane: Ten, kto się chlubi, niech się chlubi w Panu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 1, 'I ja, bracia, gdy do was przyszedłem, nie przybyłem z wzniosłością mowy lub mądrości, głosząc wam świadectwo Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 2, 'Postanowiłem bowiem nie znać wśród was niczego innego, jak tylko Jezusa Chrystusa, i to ukrzyżowanego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 3, 'I byłem u was w słabości, w bojaźni i z wielkim drżeniem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 4, 'A moja mowa i moje głoszenie nie opierały się na powabnych słowach ludzkiej mądrości, ale na ukazywaniu Ducha i mocy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 5, 'Aby wasza wiara nie opierała się na mądrości ludzkiej, ale na mocy Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 6, 'Głosimy jednak mądrość wśród doskonałych, ale nie mądrość tego świata ani władców tego świata, którzy przemijają;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 7, 'Lecz głosimy mądrość Boga w tajemnicy, zakrytą mądrość, którą przed wiekami Bóg przeznaczył ku naszej chwale;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 8, 'Której nie poznał żaden z władców tego świata. Gdyby ją bowiem poznali, nigdy nie ukrzyżowaliby Pana chwały;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 9, 'Ale głosimy, jak jest napisane: Czego oko nie widziało ani ucho nie słyszało, ani nie wstąpiło do serca człowieka, to przygotował Bóg tym, którzy go miłują.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 10, 'Nam zaś Bóg objawił to przez swojego Ducha. Duch bowiem bada wszystko, nawet głębokości Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 11, 'Bo kto z ludzi wie, co jest w człowieku oprócz ducha ludzkiego, który w nim jest? Tak samo i tego, co jest w Bogu, nikt nie zna, oprócz Ducha Bożego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 12, 'My zaś nie przyjęliśmy ducha świata, lecz Ducha, który jest z Boga, żebyśmy wiedzieli, które rzeczy są nam od Boga darowane.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 13, 'A o tym też mówimy nie słowami, których naucza ludzka mądrość, lecz których naucza Duch Święty, stosując do duchowych spraw to, co duchowe.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 14, 'Lecz cielesny człowiek nie pojmuje tych rzeczy, które są Ducha Bożego. Są bowiem dla niego głupstwem i nie może ich poznać, ponieważ rozsądza się je duchowo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 15, 'Człowiek duchowy zaś rozsądza wszystko, lecz sam przez nikogo nie jest sądzony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 16, 'Kto bowiem poznał umysł Pana? Kto go będzie pouczał? Ale my mamy umysł Chrystusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 1, 'I ja, bracia, nie mogłem do was mówić jak do ludzi duchowych, ale jak do cielesnych, jak do niemowląt w Chrystusie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 2, 'Karmiłem was mlekiem, a nie stałym pokarmem, bo jeszcze nie mogliście go przyjąć, a nawet teraz jeszcze nie możecie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 3, 'Gdyż jeszcze jesteście cieleśni. Skoro bowiem jest między wami zazdrość, kłótnie i podziały, to czyż nie jesteście cieleśni i nie postępujecie na sposób ludzki?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 4, 'Skoro ktoś mówi: Ja jestem Pawła, a inny: Ja Apollosa, to czyż nie jesteście cieleśni?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 5, 'Kim bowiem jest Paweł? Kim Apollos? Tylko sługami, przez których uwierzyliście, a to tak, jak każdemu dał Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 6, 'Ja siałem, Apollos podlewał, ale Bóg dał wzrost.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 7, 'Tak więc ani ten, który sieje, ani ten, który podlewa, nic nie znaczą, tylko Bóg, który daje wzrost.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 8, 'Ten zaś, który sieje, i ten, który podlewa, stanowią jedno, a każdy otrzyma swoją zapłatę stosownie do swojej pracy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 9, 'Jesteśmy bowiem współpracownikami Bożymi; wy jesteście Bożą rolą i Bożą budowlą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 10, 'Według łaski Boga, która została mi dana, jak mądry budowniczy położyłem fundament, a inny na nim buduje. Jednak każdy niech uważa, jak na nim buduje.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 11, 'Nikt bowiem nie może położyć innego fundamentu niż ten, który jest położony, którym jest Jezus Chrystus.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 12, 'A czy ktoś na tym fundamencie buduje ze złota, srebra, z drogich kamieni, drewna, siana czy ze słomy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 13, 'Dzieło każdego będzie jawne. Dzień ten bowiem to pokaże, gdyż przez ogień zostanie objawione i ogień wypróbuje, jakie jest dzieło każdego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 14, 'Jeśli czyjeś dzieło budowane na tym fundamencie przetrwa, ten otrzyma zapłatę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 15, 'Jeśli zaś czyjeś dzieło spłonie, ten poniesie szkodę. Lecz on sam będzie zbawiony, tak jednak, jak przez ogień.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 16, 'Czyż nie wiecie, że jesteście świątynią Boga i że Duch Boży w was mieszka?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 17, 'A jeśli ktoś niszczy świątynię Boga, tego zniszczy Bóg, bo świątynia Boga jest święta, a wy nią jesteście.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 18, 'Niech nikt nie oszukuje samego siebie. Jeśli komuś spośród was wydaje się, że jest mądry na tym świecie, niech się stanie głupim, aby stał się mądrym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 19, 'Mądrość bowiem tego świata jest głupstwem u Boga. Bo jest napisane: On chwyta mądrych w ich przebiegłości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 20, 'I znowu: Pan zna myśli mądrych i wie, że są marnością.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 21, 'Niech się więc nikt nie chlubi ludźmi. Wszystko bowiem jest wasze:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 22, 'Czy Paweł, czy Apollos, czy Kefas, czy świat, czy życie, czy śmierć, czy to, co teraźniejsze, czy to, co przyszłe – wszystko jest wasze;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 23, 'Wy zaś jesteście Chrystusa, a Chrystus Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 1, 'Niech więc każdy uważa nas za sługi Chrystusa i szafarzy tajemnic Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 2, 'A od szafarzy wymaga się, aby każdy z nich okazał się wierny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 3, 'Mnie jednak najmniej zależy na tym, czy będę przez was sądzony, czy przez sąd ludzki. Nawet sam siebie nie sądzę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 4, 'Niczego bowiem w sobie nie dostrzegam, jednak nie jestem przez to usprawiedliwiony, lecz tym, który mnie sądzi, jest Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 5, 'Dlatego nie sądźcie przed czasem, dopóki nie przyjdzie Pan, który oświetli to, co ukryte w ciemności, i ujawni zamiary serc. Wtedy każdy otrzyma pochwałę od Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 6, 'To wszystko zaś, bracia, odniosłem do samego siebie i do Apollosa ze względu na was, abyście się nauczyli na naszym przykładzie nie wykraczać ponad to, co jest napisane, żeby jeden nie pysznił się drugim przeciw innemu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 7, 'Kto bowiem czyni cię różnym? Cóż masz, czego byś nie otrzymał? A jeśli otrzymałeś, to dlaczego się chlubisz, jakbyś nie otrzymał?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 8, 'Już jesteście nasyceni, już jesteście bogaci, bez nas królujecie. I obyście królowali, abyśmy i my z wami królowali.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 9, 'Bo uważam, że Bóg nas, apostołów, wyznaczył jako ostatnich, jakby na śmierć skazanych. Staliśmy się bowiem widowiskiem dla świata, aniołów i ludzi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 10, 'My jesteśmy głupi dla Chrystusa, ale wy mądrzy w Chrystusie, my jesteśmy słabi, ale wy mocni, wy szanowani, a my wzgardzeni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 11, 'Aż do tej chwili cierpimy głód i pragnienie, jesteśmy nadzy, policzkowani i tułamy się;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 12, 'I trudzimy się, pracując własnymi rękami. Gdy nas znieważają – błogosławimy, gdy nas prześladują – znosimy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 13, 'Gdy nam złorzeczą – modlimy się za nich. Staliśmy się jak śmiecie tego świata, jak odpadki u wszystkich, aż do tej chwili.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 14, 'Nie piszę tego po to, aby was zawstydzić, ale napominam was jako moje umiłowane dzieci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 15, 'Choćbyście bowiem mieli dziesięć tysięcy wychowawców w Chrystusie, to jednak nie macie wielu ojców. Ja bowiem przez ewangelię zrodziłem was w Chrystusie Jezusie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 16, 'Proszę was więc, bądźcie moimi naśladowcami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 17, 'Dlatego to posłałem do was Tymoteusza, który jest moim umiłowanym synem i wiernym w Panu. On wam przypomni moje drogi w Chrystusie, jak nauczam wszędzie, w każdym kościele.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 18, 'A niektórzy wbili się w pychę, jakbym nie miał przyjść do was.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 19, 'Lecz przyjdę do was wkrótce, jeśli Pan zechce, i poznam nie słowa pysznych, ale ich moc.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 20, 'Królestwo Boże bowiem przejawia się nie w słowie, ale w mocy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 21, 'Co chcecie? Czy mam przyjść do was z rózgą, czy z miłością i w duchu łagodności?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 1, 'Słyszy się powszechnie o nierządzie wśród was, i to takim nierządzie, o jakim nie wspomina się nawet wśród pogan, że ktoś ma żonę swego ojca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 2, 'A wy wbiliście się w pychę, zamiast tak się smucić, aby został usunięty spośród was ten, kto się dopuścił tego czynu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 3, 'Ja bowiem, nieobecny ciałem, lecz obecny duchem, już jakbym był obecny, osądziłem tego, który to uczynił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 4, 'W imieniu naszego Pana Jezusa Chrystusa, gdy się zgromadzicie, wy i mój duch, z mocą naszego Pana Jezusa Chrystusa;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 5, 'Wydajcie takiego szatanowi na zatracenie ciała, żeby duch był zbawiony w dniu Pana Jezusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 6, 'Wasze chlubienie się nie jest dobre. Czyż nie wiecie, że trochę zakwasu całe ciasto zakwasza?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 7, 'Usuńcie więc stary zakwas, abyście byli nowym ciastem, jako że jesteście przaśni. Chrystus bowiem, nasza Pascha, został ofiarowany za nas.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 8, 'Obchodźmy zatem święto nie ze starym zakwasem ani z zakwasem złośliwości i przewrotności, ale w przaśnikach szczerości i prawdy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 9, 'Napisałem wam w liście, żebyście nie przestawali z rozpustnikami;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 10, 'Ale nie z rozpustnikami tego świata w ogóle lub chciwymi, zdziercami czy bałwochwalcami, bo inaczej musielibyście opuścić ten świat.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 11, 'Teraz jednak napisałem wam, żebyście nie przestawali z takim, który nazywając się bratem, jest rozpustnikiem, chciwym, bałwochwalcą, złorzeczącym, pijakiem lub zdziercą. Z takim nawet nie jadajcie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 12, 'Po co mi bowiem sądzić tych, którzy są na zewnątrz? Czy wy nie sądzicie tych, którzy są wewnątrz?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 13, 'Tych, którzy są na zewnątrz, osądzi Bóg. Usuńcie więc złego spośród was samych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 1, 'Czy ktoś z was, mając sprawę z drugim, śmie procesować się przed niesprawiedliwymi zamiast przed świętymi?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 2, 'Czy nie wiecie, że święci będą sądzić świat? A jeśli świat będzie sądzony przez was, to czy nie jesteście godni osądzać sprawy pomniejsze?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 3, 'Czy nie wiecie, że będziemy sądzić aniołów? A cóż dopiero sprawy doczesne?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 4, 'Jeśli więc macie do osądzenia sprawy doczesne, ustanawiajcie sędziami najmniej poważanych w kościele.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 5, 'Mówię to ku waszemu zawstydzeniu. Czy nie ma wśród was ani jednego mądrego, który może rozsądzić między swoimi braćmi?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 6, 'A tymczasem brat z bratem się procesuje, i to przed niewierzącymi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 7, 'W ogóle już to przynosi wam ujmę, że się ze sobą procesujecie. Czemu raczej krzywdy nie cierpicie? Czemu raczej szkody nie ponosicie?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 8, 'Przeciwnie, wy krzywdzicie i wyrządzacie szkodę, i to braciom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 9, 'Czy nie wiecie, że niesprawiedliwi nie odziedziczą królestwa Bożego? Nie łudźcie się: ani rozpustnicy, ani bałwochwalcy, ani cudzołożnicy, ani zniewieściali, ani mężczyźni współżyjący ze sobą;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 10, 'Ani złodzieje, ani chciwi, ani pijacy, ani złorzeczący, ani zdziercy nie odziedziczą królestwa Bożego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 11, 'A takimi niektórzy z was byli. Lecz zostaliście obmyci, lecz zostaliście uświęceni, lecz zostaliście usprawiedliwieni w imię Pana Jezusa i przez Ducha naszego Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 12, 'Wszystko mi wolno, ale nie wszystko jest pożyteczne. Wszystko mi wolno, ale ja nie dam się niczemu zniewolić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 13, 'Pokarmy są dla brzucha, a brzuch dla pokarmów. Lecz Bóg zniszczy i jedno, i drugie. Ciało zaś nie jest dla nierządu, ale dla Pana, a Pan dla ciała.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 14, 'A Bóg i Pana wskrzesił, i nas wskrzesi swoją mocą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 15, 'Czyż nie wiecie, że wasze ciała są członkami Chrystusa? Czy więc wezmę członki Chrystusa i uczynię je członkami nierządnicy? Nie daj Boże!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 16, 'Czyż nie wiecie, że ten, kto się łączy z nierządnicą, jest z nią jednym ciałem? Dwoje bowiem, mówi on, będą jednym ciałem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 17, 'Kto zaś się łączy z Panem, jest z nim jednym duchem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 18, 'Uciekajcie od nierządu. Wszelki grzech, który człowiek popełnia, jest poza ciałem. Lecz kto dopuszcza się nierządu, grzeszy przeciwko własnemu ciału.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 19, 'Czyż nie wiecie, że wasze ciało jest świątynią Ducha Świętego, który jest w was, a którego macie od Boga, i nie należycie do samych siebie?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 20, 'Drogo bowiem zostaliście kupieni. Wysławiajcie więc Boga w waszym ciele i w waszym duchu, które należą do Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 1, 'Co do spraw, o których mi pisaliście: Dobrze jest mężczyźnie nie dotykać kobiety.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 2, 'Jednak aby uniknąć nierządu, niech każdy ma swoją żonę i każda niech ma swojego męża.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 3, 'Niech mąż oddaje powinność żonie, podobnie i żona mężowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 4, 'Żona nie ma władzy nad własnym ciałem, lecz mąż. Podobnie i mąż nie ma władzy nad własnym ciałem, lecz żona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 5, 'Nie okradajcie się z tego, chyba że za obopólną zgodą, na pewien czas, aby oddać się postowi i modlitwie. Potem znów się zejdźcie, żeby was szatan nie kusił z powodu waszej niepowściągliwości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 6, 'Lecz to, co mówię, jest z pozwolenia, a nie z rozkazu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 7, 'Chciałbym bowiem, aby wszyscy ludzie byli tacy jak ja, ale każdy ma swój własny dar od Boga, jeden taki, a drugi inny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 8, 'A do nieżonatych i wdów mówię: Dobrze będzie dla nich, jeśli pozostaną jak ja.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 9, 'Lecz jeśli nie mogą się wstrzymać, niech wstąpią w stan małżeński. Lepiej jest bowiem wstąpić w stan małżeński, niż płonąć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 10, 'Tym zaś, którzy trwają w związku małżeńskim, nakazuję nie ja, lecz Pan: Żona niech nie odchodzi od męża.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 11, 'Lecz jeśli odeszłaby, niech pozostanie bez męża albo niech się z mężem pojedna. Mąż również niech nie oddala żony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 12, 'Pozostałym zaś mówię ja, a nie Pan: Jeśli któryś z braci ma żonę niewierzącą, a ta zgadza się z nim mieszkać, niech jej nie oddala.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 13, 'A jeśli jakaś żona ma męża niewierzącego, a ten zgadza się z nią mieszkać, niech od niego nie odchodzi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 14, 'Mąż niewierzący bowiem jest uświęcony przez żonę, a żona niewierząca uświęcona jest przez męża. Inaczej wasze dzieci byłyby nieczyste, teraz zaś są święte.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 15, 'Lecz jeśli niewierzący chce odejść, niech odejdzie. W takich przypadkach ani brat, ani siostra nie są w niewoli. Bóg zaś powołał nas do pokoju.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 16, 'Co bowiem wiesz, żono, czy zbawisz męża? Albo co wiesz, mężu, czy zbawisz żonę?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 17, 'Jednak niech każdy postępuje tak, jak mu wyznaczył Bóg, zgodnie z tym, do czego go powołał Pan. Tak też zarządzam we wszystkich kościołach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 18, 'Został ktoś powołany jako obrzezany? Niech się nie staje nieobrzezanym. Został ktoś powołany jako nieobrzezany? Niech się nie obrzezuje.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 19, 'Obrzezanie nic nie znaczy i nieobrzezanie nic nie znaczy, tylko zachowywanie przykazań Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 20, 'Niech każdy pozostanie w stanie, w jakim został powołany.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 21, 'Zostałeś powołany jako niewolnik? Nie martw się tym. Lecz jeśli możesz stać się wolny, to raczej z tego skorzystaj.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 22, 'Ten bowiem, kto został powołany w Panu jako niewolnik, jest wyzwoleńcem Pana. Podobnie ten, kto został powołany jako wolny, jest niewolnikiem Chrystusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 23, 'Drogo zostaliście kupieni. Nie bądźcie niewolnikami ludzi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 24, 'Niech każdy, bracia, trwa przed Bogiem w takim stanie, w jakim został powołany.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 25, 'A co do osób dziewiczych nie mam nakazu Pańskiego, ale daję moją radę jako ten, któremu Pan dał miłosierdzie, aby był wiernym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 26, 'Uważam więc, że to jest dobre z powodu obecnych utrapień, że dobrze jest człowiekowi tak pozostać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 27, 'Jesteś związany z żoną? Nie szukaj rozłączenia. Jesteś rozwiązany od żony? Nie szukaj żony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 28, 'Ale jeśli się ożenisz, nie grzeszysz, i jeśli dziewica wyjdzie za mąż, nie grzeszy. Tacy jednak będą mieć utrapienie w ciele, a ja chciałbym wam tego oszczędzić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 29, 'Mówię to, bracia, ponieważ czas jest krótki. Odtąd ci, którzy mają żony, niech żyją tak, jakby ich nie mieli;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 30, 'Ci, którzy płaczą, jakby nie płakali; ci, którzy się radują, jakby się nie radowali; ci, którzy kupują, jakby nie posiadali;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 31, 'A ci, którzy używają tego świata, żeby nie nadużywali. Przemija bowiem postać tego świata.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 32, 'Chcę, żebyście nie mieli trosk. Nieżonaty troszczy się o sprawy Pana, o to, jak się przypodobać Panu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 33, 'Lecz żonaty troszczy się o sprawy tego świata, o to, jak się przypodobać żonie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 34, 'Jest różnica między mężatką a dziewicą. Niezamężna troszczy się o sprawy Pana, o to, by była święta i ciałem, i duchem. Mężatka zaś troszczy się o sprawy tego świata, o to, jak się przypodobać mężowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 35, 'Mówię to dla waszego dobra, nie aby zarzucać na was sidła, ale żebyście godnie i przyzwoicie stali przy Panu, nie dając się rozproszyć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 36, 'Jeśli ktoś uważa, że zachowuje się niewłaściwie wobec swojej dziewicy, gdyby przeszły już jej lata i jest taka potrzeba, niech czyni, co chce, bo nie grzeszy. Niech wyjdzie za mąż.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 37, 'Lecz jeśli ktoś mocno postanowił w swym sercu, nie mając takiej potrzeby, ale panując nad własną wolą, i osądził w swym sercu, że zachowa swoją dziewicę, dobrze czyni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 38, 'Tak więc ten, kto wydaje ją za mąż, dobrze czyni, ale ten, kto nie wydaje jej za mąż, lepiej czyni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 39, 'Żona jest związana prawem, dopóki żyje jej mąż. Jeśli mąż umrze, wolno jej wyjść za kogo chce, byle w Panu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 40, 'Szczęśliwsza jednak będzie, jeśli tak pozostanie, zgodnie z moją radą. A sądzę, że i ja mam Ducha Bożego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 1, 'Co do ofiar składanych bożkom, to oczywiście wszyscy posiadamy wiedzę. Wiedza wbija w pychę, lecz miłość buduje.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 2, 'A jeśli ktoś uważa, że coś wie, to jeszcze nie wie tak, jak wiedzieć należy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 3, 'Lecz jeśli ktoś miłuje Boga, ten jest poznany przez niego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 4, 'A więc co do spożywania pokarmów ofiarowanych bożkom, wiemy, że bożek na świecie jest niczym i że nie ma żadnego innego Boga oprócz jednego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 5, 'Bo chociaż są tacy, którzy są nazywani bogami, czy to na niebie, czy na ziemi – bo wielu jest bogów i wielu panów;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 6, 'To dla nas jest jeden Bóg, Ojciec, z którego wszystko, a my w nim, i jeden Pan, Jezus Chrystus, przez którego wszystko, a my przez niego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 7, 'Lecz nie wszyscy mają tę wiedzę. Niektórzy bowiem aż do tej pory, mając sumienie co do bożka, spożywają pokarm jako ofiarowany bożkom, a ich sumienie, będąc słabe, kala się.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 8, 'Pokarm zaś nie zbliża nas do Boga. Jeśli bowiem jemy, nic nie zyskujemy, a jeśli nie jemy, nic nie tracimy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 9, 'Jednak uważajcie, aby przypadkiem wasza wolność nie stała się dla słabych powodem do zgorszenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 10, 'Gdyby bowiem ktoś zobaczył ciebie, który masz wiedzę, siedzącego za stołem w świątyni bożka, to czy sumienie tego, kto jest słaby, nie skłoni go do jedzenia pokarmów ofiarowanych bożkom?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 11, 'I w ten sposób twoja wiedza zgubi słabego brata, za którego umarł Chrystus.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 12, 'Grzesząc tak przeciwko braciom i raniąc ich słabe sumienie, grzeszycie przeciwko Chrystusowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 13, 'Dlatego, jeśli pokarm gorszy mego brata, przenigdy nie będę jadł mięsa, aby nie gorszyć mego brata.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 1, 'Czy nie jestem apostołem? Czy nie jestem wolny? Czy nie widziałem Jezusa Chrystusa, naszego Pana? Czy wy nie jesteście moim dziełem w Panu?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 2, 'Jeśli dla innych nie jestem apostołem, to dla was na pewno nim jestem. Pieczęcią bowiem mego apostolstwa wy jesteście w Panu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 3, 'Taka jest moja obrona przeciwko tym, którzy mnie osądzają.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 4, 'Czy nie mamy prawa jeść i pić?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 5, 'Czy nie mamy prawa zabierać ze sobą siostry – żony jak inni apostołowie, bracia Pana i Kefas?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 6, 'Czy tylko ja i Barnaba nie mamy prawa nie pracować?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 7, 'Czy ktoś kiedykolwiek pełni służbę żołnierską na własny koszt? Czy ktoś uprawia winnicę, a nie spożywa jej owocu? Albo czy ktoś pasie stado, a nie spożywa mleka stada?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 8, 'Czy mówię to tylko na sposób ludzki? Czy nie mówi o tym także prawo?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 9, 'Jest bowiem napisane w Prawie Mojżesza: Nie zawiążesz pyska młócącemu wołowi. Czy o woły Bóg się troszczy?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 10, 'Czy raczej ze względu na nas to mówi? Przecież dla nas jest napisane, że w nadziei ma orać ten, kto orze, a ten, kto młóci w nadziei, swojej nadziei ma być uczestnikiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 11, 'Jeśli my zasialiśmy wam dobra duchowe, to cóż wielkiego, jeśli będziemy żąć wasze dobra cielesne?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 12, 'Jeśli inni korzystają z tego prawa w stosunku do was, czemu raczej nie my? My jednak nie korzystaliśmy z tego prawa, ale znosimy wszystko, aby nie stwarzać żadnej przeszkody ewangelii Chrystusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 13, 'Czy nie wiecie, że ci, którzy służą w tym, co jest święte, żyją ze świątyni, a ci, którzy służą przy ołtarzu, mają w ofiarach wspólny udział z ołtarzem?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 14, 'Tak też Pan postanowił, aby ci, którzy ewangelię głoszą, z ewangelii żyli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 15, 'Ale ja nie korzystałem z żadnego z tych praw. I nie napisałem tego po to, żeby tak się ze mną stało. Lepiej byłoby mi umrzeć, niż żeby ktoś pozbawił mnie mojej chluby.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 16, 'Jeśli bowiem głoszę ewangelię, nie mam się czym chlubić, bo nałożono na mnie ten obowiązek, a biada mi, gdybym ewangelii nie głosił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 17, 'Jeśli bowiem robię to dobrowolnie, mam nagrodę, jeśli zaś niedobrowolnie, to spełniam tylko powierzone mi obowiązki szafarza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 18, 'Jaką więc mam nagrodę? Taką, że głosząc ewangelię, głoszę ewangelię Chrystusa za darmo, abym nie nadużywał mojego prawa, jakie mam z ewangelii.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 19, 'Będąc bowiem wolny wobec wszystkich, samego siebie uczyniłem niewolnikiem wszystkich, abym więcej ludzi pozyskał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 20, 'I stałem się dla Żydów jak Żyd, aby Żydów pozyskać, dla tych, którzy są pod prawem, jakbym był pod prawem, aby pozyskać tych, którzy są pod prawem;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 21, 'Dla tych, którzy są bez prawa, jakbym był bez prawa – nie będąc bez prawa Bogu, lecz będąc pod prawem Chrystusowi – aby pozyskać tych, którzy są bez prawa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 22, 'Dla słabych stałem się jak słaby, aby słabych pozyskać. Stałem się wszystkim dla wszystkich, aby wszelkim sposobem niektórych zbawić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 23, 'A robię to dla ewangelii, aby stać się jej uczestnikiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 24, 'Czy nie wiecie, że ci, którzy biegną w wyścigu, wszyscy wprawdzie biegną, lecz tylko jeden zdobywa nagrodę? Tak biegnijcie, abyście ją otrzymali.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 25, 'Każdy, kto staje do zapasów, powściąga się we wszystkim. Oni, aby zdobyć koronę zniszczalną, my zaś niezniszczalną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 26, 'Ja więc tak biegnę, nie jakby na oślep, tak walczę, nie jakbym uderzał w powietrze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 27, 'Lecz poskramiam swoje ciało i biorę w niewolę, abym przypadkiem, głosząc innym, sam nie został odrzucony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 1, 'Nie chcę, bracia, żebyście nie wiedzieli, że wszyscy nasi ojcowie byli pod obłokiem i wszyscy przeszli przez morze;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 2, 'I wszyscy w Mojżesza zostali ochrzczeni w obłoku i w morzu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 3, 'Wszyscy też jedli ten sam pokarm duchowy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 4, 'I wszyscy pili ten sam duchowy napój. Pili bowiem ze skały duchowej, która szła za nimi. A tą skałą był Chrystus.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 5, 'Lecz większości z nich nie upodobał sobie Bóg. Polegli bowiem na pustyni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 6, 'A to stało się dla nas przykładem, żebyśmy nie pożądali złych rzeczy, jak oni pożądali.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 7, 'Nie bądźcie więc bałwochwalcami, jak niektórzy z nich, jak jest napisane: Usiadł lud, aby jeść i pić, i wstali, aby się bawić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 8, 'Nie dopuszczajmy się też nierządu, jak niektórzy z nich się dopuszczali i padło ich jednego dnia dwadzieścia trzy tysiące;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 9, 'I nie wystawiajmy na próbę Chrystusa, jak niektórzy z nich wystawiali i poginęli od wężów;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 10, 'Ani nie szemrajcie, jak niektórzy z nich szemrali i zostali wytraceni przez niszczyciela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 11, 'A to wszystko przydarzyło się im dla przykładu i zostało napisane dla napomnienia nas, których dosięgnął kres czasów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 12, 'Tak więc kto myśli, że stoi, niech uważa, aby nie upadł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 13, 'Nie nawiedziła was pokusa inna niż ludzka. Lecz Bóg jest wierny i nie pozwoli, żebyście byli kuszeni ponad wasze siły, ale wraz z pokusą da wyjście, żebyście mogli ją znieść.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 14, 'Dlatego, moi najmilsi, uciekajcie od bałwochwalstwa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 15, 'Mówię jak do mądrych. Osądźcie sami to, co mówię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 16, 'Kielich błogosławieństwa, który błogosławimy, czy nie jest wspólnotą krwi Chrystusa? Chleb, który łamiemy, czy nie jest wspólnotą ciała Chrystusa?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 17, 'My bowiem, choć liczni, jesteśmy jednym chlebem i jednym ciałem, bo wszyscy jesteśmy uczestnikami jednego chleba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 18, 'Przypatrzcie się Izraelowi według ciała. Czyż ci, którzy jedzą ofiary, nie są uczestnikami ołtarza?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 19, 'Cóż więc chcę powiedzieć? Że bożek jest czymś albo ofiara składana bożkom czymś jest?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 20, 'Raczej chcę powiedzieć, że to, co poganie ofiarują, demonom ofiarują, a nie Bogu. A nie chciałbym, żebyście mieli społeczność z demonami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 21, 'Nie możecie pić kielicha Pana i kielicha demonów. Nie możecie być uczestnikami stołu Pana i stołu demonów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 22, 'Czy będziemy pobudzali Pana do zazdrości? Czy jesteśmy mocniejsi od niego?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 23, 'Wszystko mi wolno, ale nie wszystko jest pożyteczne. Wszystko mi wolno, ale nie wszystko buduje.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 24, 'Niech nikt nie szuka własnego dobra, lecz dobra bliźniego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 25, 'Wszystko, co sprzedają w jatkach, jedzcie, o nic nie pytając ze względu na sumienie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 26, 'Pańska bowiem jest ziemia i wszystko, co ją napełnia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 27, 'Jeśli zaprosi was ktoś z niewierzących, a chcecie iść, jedzcie wszystko, co przed wami postawią, o nic nie pytając ze względu na sumienie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 28, 'Lecz jeśli ktoś wam powie: To jest ofiarowane bożkom, nie jedzcie ze względu na tego, który to powiedział, i ze względu na sumienie. Pańska bowiem jest ziemia i wszystko, co ją napełnia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 29, 'Ale sumienie, mówię, nie twoje, lecz tego drugiego. Dlaczego bowiem moja wolność ma być sądzona przez cudze sumienie?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 30, 'Bo jeśli ja z dziękczynieniem coś spożywam, to czemu mam być spotwarzany za to, za co dziękuję?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 31, 'Tak więc czy jecie, czy pijecie, czy cokolwiek innego robicie, wszystko róbcie ku chwale Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 32, 'Nie bądźcie zgorszeniem ani dla Żydów, ani dla Greków, ani dla kościoła Bożego;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 33, 'Tak jak i ja się wszystkim we wszystkim podobam, nie szukając w tym własnej korzyści, ale korzyści wielu, aby byli zbawieni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 1, 'Bądźcie moimi naśladowcami, jak i ja jestem naśladowcą Chrystusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 2, 'A chwalę was, bracia, za to, że we wszystkim o mnie pamiętacie i zachowujecie nauki tak, jak je wam przekazałem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 3, 'Lecz chcę, żebyście wiedzieli, że głową każdego mężczyzny jest Chrystus, a głową kobiety mężczyzna, a głową Chrystusa Bóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 4, 'Każdy mężczyzna, gdy się modli albo prorokuje z nakrytą głową, hańbi swoją głowę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 5, 'I każda kobieta, gdy się modli albo prorokuje z nienakrytą głową, hańbi swoją głowę. Bo to jest jedno i to samo, jakby była ogolona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 6, 'Jeśli więc kobieta nie nakrywa głowy, niech się też strzyże. A jeśli hańbiące jest dla kobiety być ostrzyżoną lub ogoloną, niech nakrywa głowę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 7, 'Mężczyzna zaś nie powinien nakrywać głowy, gdyż jest obrazem i chwałą Boga. Kobieta zaś jest chwałą mężczyzny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 8, 'Bo mężczyzna nie jest z kobiety, lecz kobieta z mężczyzny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 9, 'Mężczyzna bowiem nie został stworzony dla kobiety, ale kobieta dla mężczyzny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 10, 'Dlatego kobieta powinna mieć na głowie znak władzy, ze względu na aniołów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 11, 'A jednak w Panu ani mężczyzna nie jest bez kobiety, ani kobieta nie jest bez mężczyzny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 12, 'Jak bowiem kobieta jest z mężczyzny, tak też mężczyzna przez kobietę, lecz wszystko jest z Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 13, 'Osądźcie sami: Czy wypada kobiecie modlić się do Boga bez nakrycia głowy?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 14, 'Czyż sama natura nie uczy was, że gdy mężczyzna nosi długie włosy, przynosi mu to wstyd?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 15, 'Ale jeśli kobieta nosi długie włosy, przynosi jej to chwałę, gdyż włosy zostały jej dane za okrycie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 16, 'A jeśli ktoś wydaje się być kłótliwy, my takiego zwyczaju nie mamy, ani kościoły Boże.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 17, 'Mówiąc to, nie chwalę was, że się zbieracie nie ku lepszemu, ale ku gorszemu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 18, 'Najpierw bowiem słyszę, że gdy się zbieracie jako kościół, są wśród was podziały, i po części temu wierzę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 19, 'Bo muszą być między wami herezje, aby się okazało, którzy są wypróbowani wśród was.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 20, 'Gdy więc się zbieracie, nie jest to spożywanie wieczerzy Pańskiej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 21, 'Każdy bowiem najpierw je własną wieczerzę i jeden jest głodny, a drugi pijany.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 22, 'Czyż nie macie domów, aby jeść i pić? Albo czy gardzicie kościołem Bożym i zawstydzacie tych, którzy nic nie mają? Co mam wam powiedzieć? Czy mam was pochwalić? Za to was nie chwalę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 23, 'Ja bowiem otrzymałem od Pana to, co wam przekazałem, że Pan Jezus tej nocy, której został wydany, wziął chleb;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 24, 'A gdy złożył dziękczynienie, połamał i powiedział: Bierzcie i jedzcie, to jest moje ciało, które za was jest łamane. Czyńcie to na moją pamiątkę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 25, 'Podobnie po wieczerzy wziął też kielich, mówiąc: Ten kielich to nowy testament w mojej krwi. Czyńcie to, ilekroć będziecie pić, na moją pamiątkę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 26, 'Ilekroć bowiem będziecie jedli ten chleb i pili ten kielich, śmierć Pana zwiastujecie, aż przyjdzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 27, 'Dlatego też kto je ten chleb albo pije ten kielich Pański niegodnie, będzie winny ciała i krwi Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 28, 'Niech więc człowiek bada samego siebie i tak niech je z tego chleba, i niech pije z tego kielicha.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 29, 'Kto bowiem je i pije niegodnie, sąd własny je i pije, nie rozróżniając ciała Pańskiego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 30, 'Dlatego jest wśród was wielu słabych i chorych, a niemało też zasnęło.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 31, 'Bo gdybyśmy sami siebie sądzili, nie bylibyśmy sądzeni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 32, 'Lecz gdy jesteśmy sądzeni, przez Pana jesteśmy karceni, abyśmy nie byli potępieni wraz ze światem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 33, 'Tak więc, moi bracia, gdy się zbieracie, aby jeść, czekajcie jedni na drugich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 34, 'A jeśli ktoś jest głodny, niech zje w domu, żebyście się nie zbierali ku sądowi. Co do pozostałych spraw, zarządzę, gdy przyjdę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 1, 'A co do duchowych darów, bracia, nie chcę, żebyście byli w niewiedzy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 2, 'Wiecie, że gdy byliście poganami, do niemych bożków, jak was wiedziono, daliście się prowadzić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 3, 'Dlatego oznajmiam wam, że nikt, kto mówi przez Ducha Bożego, nie powie, że Jezus jest przeklęty. Nikt też nie może powiedzieć, że Jezus jest Panem, jak tylko przez Ducha Świętego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 4, 'A różne są dary, lecz ten sam Duch.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 5, 'Różne też są posługi, lecz ten sam Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 6, 'I różne są działania, lecz ten sam Bóg, który sprawia wszystko we wszystkich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 7, 'A każdemu jest dany przejaw Ducha dla wspólnego pożytku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 8, 'Jednemu bowiem przez Ducha jest dana mowa mądrości, drugiemu mowa wiedzy przez tego samego Ducha;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 9, 'Innemu wiara w tym samym Duchu, innemu dar uzdrawiania w tym samym Duchu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 10, 'Innemu dar czynienia cudów, innemu proroctwo, innemu rozróżnianie duchów, innemu różne rodzaje języków, a innemu tłumaczenie języków.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 11, 'A to wszystko sprawia jeden i ten sam Duch, udzielając każdemu z osobna, jak chce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 12, 'Jak bowiem ciało jest jedno, a członków ma wiele i wszystkie członki jednego ciała, choć jest ich wiele, są jednym ciałem, tak i Chrystus.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 13, 'Bo wszyscy przez jednego Ducha zostaliśmy ochrzczeni w jedno ciało, czy to Żydzi, czy Grecy, czy niewolnicy, czy wolni, i wszyscy zostaliśmy napojeni w jednego Ducha.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 14, 'Ciało bowiem nie jest jednym członkiem, ale wieloma.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 15, 'Gdyby noga powiedziała: Ponieważ nie jestem ręką, nie należę do ciała – czy dlatego nie należy do ciała?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 16, 'A gdyby ucho powiedziało: Ponieważ nie jestem okiem, nie należę do ciała – czy dlatego nie należy do ciała?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 17, 'Gdyby całe ciało było okiem, gdzież byłby słuch? A gdyby całe było słuchem, gdzież powonienie?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 18, 'Lecz Bóg umieścił członki w ciele, każdy z nich tak, jak chciał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 19, 'Gdyby wszystkie były jednym członkiem, gdzież byłoby ciało?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 20, 'Tymczasem wiele jest członków, lecz jedno ciało.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 21, 'Nie może więc oko powiedzieć ręce: Nie potrzebuję ciebie, albo głowa nogom: Nie potrzebuję was.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 22, 'Przeciwnie, o wiele bardziej potrzebne są te członki ciała, które wydają się najsłabsze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 23, 'A te, które uważamy za mało godne szacunku, tym większym otaczamy szacunkiem, a nasze wstydliwe członki otrzymują większe poszanowanie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 24, 'Natomiast nasze przyzwoite członki tego nie potrzebują. Lecz Bóg tak ukształtował ciało, że dał członkowi, któremu brakuje czci, więcej szacunku;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 25, 'Aby nie było podziału w ciele, ale żeby członki jednakowo troszczyły się o siebie nawzajem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 26, 'Tak więc, jeśli jeden członek cierpi, cierpią z nim wszystkie członki, a jeśli jeden członek doznaje czci, radują się z nim wszystkie członki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 27, 'Wy zaś jesteście ciałem Chrystusa, a z osobna członkami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 28, 'A Bóg ustanowił niektórych w kościele najpierw jako apostołów, potem proroków, po trzecie nauczycieli, potem cudotwórców, potem dary uzdrawiania, niesienia pomocy, rządzenia, różne języki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 29, 'Czy wszyscy są apostołami? Czy wszyscy prorokami? Czy wszyscy nauczycielami? Czy wszyscy cudotwórcami?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 30, 'Czy wszyscy mają dary uzdrawiania? Czy wszyscy mówią językami? Czy wszyscy tłumaczą?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 31, 'Starajcie się usilnie o lepsze dary; a ja wam wskażę drogę jeszcze doskonalszą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 1, 'Choćbym mówił językami ludzi i aniołów, a miłości bym nie miał, stałbym się jak miedź brzęcząca albo cymbał brzmiący.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 2, 'I choćbym miał dar prorokowania, i znał wszystkie tajemnice, i posiadał wszelką wiedzę, i choćbym miał pełnię wiary, tak, żebym góry przenosił, a miłości bym nie miał, byłbym niczym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 3, 'I choćbym rozdał na żywność dla ubogich cały swój majątek, i choćbym wydał swoje ciało na spalenie, a miłości bym nie miał, nic nie zyskam.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 4, 'Miłość jest cierpliwa, jest życzliwa. Miłość nie zazdrości, nie przechwala się, nie unosi się pychą;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 5, 'Nie postępuje nieprzyzwoicie, nie szuka swego, nie jest porywcza, nie myśli nic złego;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 6, 'Nie raduje się z niesprawiedliwości, ale raduje się z prawdy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 7, 'Wszystko znosi, wszystkiemu wierzy, wszystkiego się spodziewa, wszystko przetrzyma.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 8, 'Miłość nigdy nie ustaje. Bo choć są proroctwa, przeminą; choć języki, ustaną; choć wiedza, obróci się wniwecz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 9, 'Po części bowiem poznajemy i po części prorokujemy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 10, 'Ale gdy przyjdzie to, co doskonałe, wtedy przeminie to, co jest cząstkowe.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 11, 'Dopóki byłem dzieckiem, mówiłem jak dziecko, rozumiałem jak dziecko, myślałem jak dziecko. Lecz gdy stałem się mężczyzną, zaniechałem tego, co dziecięce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 12, 'Teraz bowiem widzimy w zwierciadle, niewyraźnie, ale wówczas twarzą w twarz. Teraz poznaję cząstkowo, ale wtedy poznam tak, jak jestem poznany.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 13, 'A teraz trwają wiara, nadzieja, miłość, te trzy. Z nich zaś największa jest miłość.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 1, 'Dążcie do miłości, starajcie się usilnie o duchowe dary, a najbardziej o to, aby prorokować.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 2, 'Ten bowiem, kto mówi obcym językiem, nie mówi ludziom, ale Bogu, bo nikt go nie rozumie. On zaś w duchu mówi tajemnice.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 3, 'Ale ten, kto prorokuje, mówi do ludzi dla zbudowania, zachęcenia i pocieszenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 4, 'Kto mówi obcym językiem, buduje samego siebie, ale kto prorokuje, buduje kościół.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 5, 'A chciałbym, żebyście wszyscy mówili językami, bardziej jednak, abyście prorokowali. Większy bowiem jest ten, kto prorokuje, niż ten, kto mówi obcymi językami, chyba że tłumaczy, aby kościół był zbudowany.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 6, 'Teraz więc, bracia, gdybym przyszedł do was, mówiąc obcymi językami, jaki pożytek mielibyście ze mnie, jeślibym nie mówił do was albo przez objawienie, albo przez wiedzę, albo przez proroctwo, albo przez naukę?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 7, 'Przecież nawet przedmioty martwe, które wydają dźwięki, jak flet albo cytra, gdyby nie wydawały różnych dźwięków, jak można byłoby rozpoznać, co się gra na flecie, a co na cytrze?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 8, 'A gdyby trąba wydawała niewyraźny głos, kto by się przygotowywał do bitwy?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 9, 'Tak i wy, jeśli nie wypowiecie językiem zrozumiałych słów, jakże ktoś zrozumie, co się mówi? Na wiatr bowiem będziecie mówić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 10, 'Na świecie jest zapewne mnóstwo różnych głosów i żaden z nich nie jest bez znaczenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 11, 'Jeśli więc nie będę rozumiał znaczenia głosu, będę cudzoziemcem dla tego, kto mówi, a ten, kto mówi, będzie cudzoziemcem dla mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 12, 'Tak i wy, ponieważ usilnie zabiegacie o dary duchowe, starajcie się obfitować w to, co buduje kościół.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 13, 'Dlatego ten, kto mówi obcym językiem, niech się modli, aby mógł tłumaczyć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 14, 'Jeśli bowiem modlę się obcym językiem, mój duch się modli, ale mój rozum nie odnosi korzyści.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 15, 'Cóż więc? Będę się modlił duchem, będę się też modlił i rozumem. Będę śpiewał duchem, będę też śpiewał i rozumem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 16, 'Jeśli bowiem będziesz błogosławił duchem, jakże ktoś spośród nieuczonych na twoje dziękczynienie odpowie „Amen”, skoro nie rozumie, co mówisz?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 17, 'Ty wprawdzie dobrze dziękujesz, ale drugi się nie buduje.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 18, 'Dziękuję mojemu Bogu, że mówię językami więcej niż wy wszyscy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 19, 'Lecz w kościele wolę powiedzieć pięć słów zrozumiałych, aby i innych nauczyć, niż dziesięć tysięcy słów obcym językiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 20, 'Bracia, nie bądźcie dziećmi w rozumieniu, ale bądźcie dziećmi w złośliwości, a w rozumieniu bądźcie dojrzali.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 21, 'W Prawie jest napisane: Przez ludzi obcych języków i przez usta obcych będę mówić do tego ludu, ale i tak mnie nie usłuchają, mówi Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 22, 'Dlatego języki są znakiem nie dla wierzących, lecz dla niewierzących, proroctwo zaś nie dla niewierzących, lecz dla wierzących.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 23, 'Jeśli więc cały kościół zbiera się w jednym miejscu i wszyscy mówią obcymi językami, a wejdą tam nieuczeni albo niewierzący, czy nie powiedzą, że szalejecie?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 24, 'Ale jeśli wszyscy prorokują, a wejdzie jakiś niewierzący albo nieuczony, będzie przekonany i osądzony przez wszystkich;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 25, 'I tak zostaną objawione tajemnice jego serca, a on upadnie na twarz, odda pokłon Bogu i wyzna, że prawdziwie Bóg jest w was.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 26, 'Cóż więc, bracia? Gdy się zbieracie, każdy z was ma psalm, ma naukę, ma język, ma objawienie, ma tłumaczenie. Niech to wszystko służy zbudowaniu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 27, 'Jeśli ktoś mówi językami, niech to czyni dwóch albo najwięcej trzech, i to po kolei, a jeden niech tłumaczy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 28, 'A jeśli nie ma tłumacza, niech milczy w kościele ten, kto mówi obcym językiem, a niech mówi samemu sobie i Bogu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 29, 'Prorocy zaś niech mówią po dwóch albo trzech, a inni niech rozsądzają.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 30, 'A gdyby innemu z siedzących zostało coś objawione, pierwszy niech milczy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 31, 'Możecie bowiem wszyscy, jeden po drugim prorokować, aby się wszyscy uczyli i wszyscy zostali pocieszeni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 32, 'A duchy proroków są poddane prorokom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 33, 'Bóg bowiem nie jest Bogiem nieładu, lecz pokoju, jak we wszystkich kościołach świętych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 34, 'Niech wasze kobiety milczą w kościołach. Bo nie pozwala się im mówić, ale mają być poddane, jak też prawo mówi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 35, 'A jeśli chcą się czegoś nauczyć, niech w domu pytają swoich mężów. Hańbą bowiem jest dla kobiety mówić w kościele.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 36, 'Czy od was wyszło słowo Boże? Czy tylko do was przyszło?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 37, 'Jeśli ktoś uważa się za proroka albo człowieka duchowego, niech uzna, że to, co wam piszę, jest nakazem Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 38, 'A jeśli ktoś jest w niewiedzy, niech pozostanie w niewiedzy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 39, 'Tak więc, bracia, starajcie się usilnie, abyście prorokowali, i nie zabraniajcie mówić obcymi językami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 40, 'Wszystko niech się odbywa godnie i w należytym porządku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 1, 'A oznajmiam wam, bracia, ewangelię, którą wam głosiłem, a którą przyjęliście i w której trwacie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 2, 'Przez którą też dostępujecie zbawienia, jeśli pamiętacie to, co wam głosiłem, chyba że uwierzyliście na próżno.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 3, 'Najpierw bowiem przekazałem wam to, co i ja otrzymałem, że Chrystus umarł za nasze grzechy, zgodnie z Pismem;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 4, 'Że został pogrzebany, że zmartwychwstał trzeciego dnia, zgodnie z Pismem;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 5, 'I że ukazał się Kefasowi, a potem tym dwunastu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 6, 'Potem ukazał się więcej niż pięciuset braciom naraz, z których większość żyje aż dotąd, a niektórzy zasnęli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 7, 'Potem ukazał się Jakubowi, potem wszystkim apostołom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 8, 'A ostatniemu ze wszystkich ukazał się i mnie, jak poronionemu płodowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 9, 'Ja bowiem jestem najmniejszym z apostołów i nie jestem godny nazywać się apostołem, bo prześladowałem kościół Boży.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 10, 'Lecz z łaski Boga jestem tym, czym jestem, a jego łaska względem mnie nie okazała się daremna, ale pracowałem więcej od nich wszystkich, jednak nie ja, lecz łaska Boga, która jest ze mną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 11, 'Czy więc ja, czy oni, tak głosimy i tak uwierzyliście.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 12, 'A jeśli się o Chrystusie głosi, że został wskrzeszony z martwych, jak mogą niektórzy pośród was mówić, że nie ma zmartwychwstania?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 13, 'Jeśli bowiem nie ma zmartwychwstania, to i Chrystus nie został wskrzeszony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 14, 'A jeśli Chrystus nie został wskrzeszony, to daremne jest nasze głoszenie, daremna też wasza wiara.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 15, 'I okazuje się, że jesteśmy fałszywymi świadkami Boga, bo świadczyliśmy o Bogu, że wskrzesił Chrystusa, którego nie wskrzesił, jeśli umarli nie są wskrzeszani.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 16, 'Jeśli bowiem umarli nie są wskrzeszani, to i Chrystus nie został wskrzeszony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 17, 'A jeśli Chrystus nie został wskrzeszony, daremna jest wasza wiara i nadal jesteście w swoich grzechach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 18, 'Tak więc i ci, którzy zasnęli w Chrystusie, poginęli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 19, 'Jeśli tylko w tym życiu mamy nadzieję w Chrystusie, jesteśmy ze wszystkich ludzi najbardziej nieszczęśliwi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 20, 'Tymczasem jednak Chrystus został wskrzeszony z martwych i stał się pierwszym plonem tych, którzy zasnęli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 21, 'Skoro bowiem śmierć przyszła przez człowieka, przez człowieka przyszło też zmartwychwstanie umarłych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 22, 'Jak bowiem w Adamie wszyscy umierają, tak też w Chrystusie wszyscy zostaną ożywieni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 23, 'Ale każdy w swojej kolejności, Chrystus jako pierwszy plon, potem ci, którzy należą do Chrystusa, w czasie jego przyjścia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 24, 'A potem będzie koniec, gdy przekaże królestwo Bogu i Ojcu, gdy zniszczy wszelką zwierzchność oraz wszelką władzę i moc.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 25, 'Bo on musi królować, aż położy wszystkich wrogów pod swoje stopy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 26, 'A ostatni wróg, który zostanie zniszczony, to śmierć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 27, 'Wszystko bowiem poddał pod jego stopy. A gdy mówi, że wszystko jest mu poddane, jest jasne, że oprócz tego, który mu wszystko poddał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 28, 'Gdy zaś wszystko zostanie mu poddane, wtedy i sam Syn będzie poddany temu, który mu poddał wszystko, aby Bóg był wszystkim we wszystkich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 29, 'Bo inaczej co zrobią ci, którzy przyjmują chrzest za zmarłych, jeśli umarli w ogóle nie są wskrzeszani? Po co przyjmują chrzest za zmarłych?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 30, 'Po co i my każdej godziny narażamy się na niebezpieczeństwo?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 31, 'Zapewniam was przez chlubę, którą mam z was w Jezusie Chrystusie, naszym Panu, że każdego dnia umieram.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 32, 'Jeśli na sposób ludzki walczyłem z bestiami w Efezie, jaki z tego mam pożytek, jeśli umarli nie są wskrzeszani? Jedzmy i pijmy, bo jutro pomrzemy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 33, 'Nie łudźcie się. Złe rozmowy psują dobre obyczaje.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 34, 'Ocknijcie się ku sprawiedliwości i nie grzeszcie; niektórzy bowiem nie mają poznania Boga. Mówię to ku waszemu zawstydzeniu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 35, 'Lecz powie ktoś: Jak umarli są wskrzeszani i w jakim ciele przychodzą?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 36, 'Głupcze! To, co siejesz, nie ożyje, jeśli nie obumrze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 37, 'I to, co siejesz, to nie ciało, które ma powstać, ale gołe ziarno, na przykład pszeniczne lub jakieś inne.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 38, 'Bóg zaś daje mu ciało, jakie chce, a każdemu z ziaren właściwe jemu ciało.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 39, 'Nie każde ciało jest jednakowe, ale inne jest ciało ludzi, a inne ciało zwierząt, inne ryb, a inne ptaków.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 40, 'Są też ciała niebieskie i ciała ziemskie, lecz inna jest chwała ciał niebieskich, a inna ziemskich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 41, 'Inna chwała słońca, inna chwała księżyca, a inna chwała gwiazd. Gwiazda bowiem od gwiazdy różni się jasnością.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 42, 'Tak też jest ze zmartwychwstaniem umarłych. Sieje się ciało w zniszczalności, a jest wskrzeszane w niezniszczalności;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 43, 'Sieje się w niesławie, a jest wskrzeszane w chwale, sieje się w słabości, a jest wskrzeszane w mocy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 44, 'Sieje się ciało cielesne, a jest wskrzeszane ciało duchowe. Jest ciało cielesne, jest też ciało duchowe.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 45, 'Tak też jest napisane: Stał się pierwszy człowiek, Adam, duszą żyjącą, a ostatni Adam duchem ożywiającym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 46, 'Jednak pierwsze nie jest to, co duchowe, ale to, co cielesne, potem duchowe.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 47, 'Pierwszy człowiek z ziemi – ziemski, drugi człowiek – sam Pan z nieba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 48, 'Jaki jest ten ziemski, tacy i ziemscy; a jaki jest niebieski, tacy i niebiescy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 49, 'A jak nosiliśmy obraz ziemskiego, tak będziemy nosili obraz niebieskiego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 50, 'To zaś mówię, bracia, że ciało i krew nie mogą odziedziczyć królestwa Bożego ani to, co zniszczalne, nie odziedziczy tego, co niezniszczalne.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 51, 'Oto oznajmiam wam tajemnicę: Nie wszyscy zaśniemy, ale wszyscy będziemy przemienieni;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 52, 'W jednej chwili, w mgnieniu oka, na ostatnią trąbę. Zabrzmi bowiem trąba, a umarli zostaną wskrzeszeni niezniszczalni, a my zostaniemy przemienieni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 53, 'To bowiem, co zniszczalne, musi przyodziać się w to, co niezniszczalne, a to, co śmiertelne, przyoblec się w nieśmiertelność.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 54, 'A gdy to, co zniszczalne, przyoblecze się w niezniszczalność, a to, co śmiertelne, przyoblecze się w nieśmiertelność, wtedy wypełni się to słowo, które jest napisane: Połknięta jest śmierć w zwycięstwie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 55, 'Gdzież jest, o śmierci, twoje żądło? Gdzież jest, o piekło, twoje zwycięstwo?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 56, 'Żądłem zaś śmierci jest grzech, a siłą grzechu prawo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 57, 'Lecz dzięki niech będą Bogu, który nam dał zwycięstwo przez naszego Pana Jezusa Chrystusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 58, 'A tak, moi mili bracia, bądźcie stali, niezachwiani, zawsze obfitujący w dziele Pana, wiedząc, że wasza praca nie jest daremna w Panu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 1, 'A co do składki na świętych, to i wy zróbcie tak, jak zarządziłem w kościołach Galacji.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 2, 'Każdego pierwszego dnia tygodnia niech każdy z was odkłada u siebie, stosownie do tego, jak mu się powodzi, aby nie urządzać składek dopiero wtedy, kiedy ja tam przybędę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 3, 'A gdy przyjdę, poślę tych, których w listach uznacie za godnych, aby zanieśli wasz hojny dar do Jerozolimy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 4, 'A jeśli będzie właściwe, abym i ja się udał, pójdą razem ze mną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 5, 'Przybędę zaś do was, kiedy przejdę Macedonię. Będę bowiem szedł przez Macedonię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 6, 'A być może zatrzymam się u was lub nawet przezimuję, żebyście mnie wyprawili, dokądkolwiek wyruszę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 7, 'Nie chcę bowiem was teraz widzieć przejazdem, ale mam nadzieję pozostać z wami przez jakiś czas, jeśli Pan pozwoli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 8, 'A w Efezie zostanę aż do Pięćdziesiątnicy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 9, 'Otworzyły się bowiem przede mną drzwi wielkie i owocne, a mam wielu przeciwników.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 10, 'Jeśli zaś przybędzie Tymoteusz, uważajcie, aby przebywał wśród was bez bojaźni, bo wykonuje dzieło Pana, jak i ja.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 11, 'Dlatego niech nikt go nie lekceważy. Lecz wyprawcie go w pokoju, aby dotarł do mnie, bo czekam na niego z braćmi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 12, 'A co do brata Apollosa, to bardzo go prosiłem, aby poszedł do was z braćmi. Lecz w ogóle nie chciał teraz iść. Pójdzie jednak w odpowiednim dla niego czasie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 13, 'Czuwajcie, trwajcie w wierze, bądźcie mężni, umacniajcie się.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 14, 'Wszystko, co czynicie, niech się dzieje w miłości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 15, 'A proszę was, bracia (bo znacie dom Stefanasa, że jest pierwszym plonem Achai i że się poświęcili na służbę świętym);');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 16, 'Żebyście byli takim poddani i każdemu, kto pomaga i pracuje z nami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 17, 'A cieszę się z przyjścia Stefanasa, Fortunata i Achaika, bo wypełnili wasz brak.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 18, 'Pokrzepili bowiem mego i waszego ducha. Szanujcie więc takich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 19, 'Pozdrawiają was kościoły Azji. Pozdrawiają was serdecznie w Panu Akwila i Pryscylla wraz z kościołem, który jest w ich domu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 20, 'Pozdrawiają was wszyscy bracia. Pozdrówcie jedni drugich pocałunkiem świętym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 21, 'Pozdrowienie moją, Pawła, ręką.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 22, 'Jeśli ktoś nie miłuje Pana Jezusa Chrystusa, niech będzie przeklęty. Maranatha.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 23, 'Łaska Pana Jezusa Chrystusa niech będzie z wami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 24, 'Miłość moja niech będzie z wami wszystkimi w Chrystusie Jezusie. Amen. Pierwszy list do Koryntian został napisany z miasta Filippi przez Stefana, Fortunata, Achaika i Tymoteusza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 1, 'Paweł, z woli Boga apostoł Jezusa Chrystusa, i Tymoteusz, brat, do kościoła Bożego, który jest w Koryncie, ze wszystkimi świętymi, którzy są w całej Achai.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 2, 'Łaska wam i pokój od Boga, naszego Ojca, i Pana Jezusa Chrystusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 3, 'Błogosławiony niech będzie Bóg i Ojciec naszego Pana Jezusa Chrystusa, Ojciec miłosierdzia i Bóg wszelkiej pociechy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 4, 'Który nas pociesza w każdym naszym utrapieniu, abyśmy i my mogli pocieszać tych, którzy są w jakimkolwiek ucisku, taką pociechą, jaką sami jesteśmy pocieszani przez Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 5, 'Jak bowiem w nas obfitują utrapienia Chrystusa, tak też przez Chrystusa obfituje nasza pociecha.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 6, 'Jeśli więc doznajemy ucisku – to dla waszego pocieszenia i zbawienia, które sprawia, że znosicie te same utrapienia, które i my cierpimy; i jeśli doznajemy pociechy – to dla waszego pocieszenia i zbawienia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 7, 'A nasza nadzieja co do was jest mocna, bo wiemy, że jak jesteście uczestnikami utrapienia, tak i pociechy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 8, 'Nie chcemy bowiem, bracia, abyście nie wiedzieli o ucisku, który nas spotkał w Azji, że byliśmy obciążeni ponad miarę i ponad siły, tak że zaczęliśmy wątpić, czy przeżyjemy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 9, 'Więcej, sami w sobie mieliśmy wyrok śmierci, abyśmy nie ufali samym sobie, lecz Bogu, który wskrzesza umarłych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 10, 'On to wyrwał nas z tak wielkiej śmierci i jeszcze wyrywa. W nim też mamy nadzieję, że nadal będzie wyrywać;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 11, 'Także przy waszej pomocy poprzez modlitwę za nas, aby dar, który otrzymaliśmy dzięki wielu, stał się dla wielu powodem dziękczynienia za nas.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 12, 'To bowiem jest naszą chlubą: świadectwo naszego sumienia, że w prostocie i w szczerości Bożej, nie w cielesnej mądrości, ale w łasce Boga postępowaliśmy na świecie, a szczególnie względem was.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 13, 'Nie piszemy wam nic innego, jak tylko to, co czytacie albo rozumiecie. Spodziewam się zaś, że też do końca zrozumiecie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 14, 'Jak już po części nas zrozumieliście, że jesteśmy waszą chlubą, jak i wy naszą w dniu Pana Jezusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 15, 'Z tą ufnością chciałem przybyć do was wcześniej, abyście otrzymali powtórne dobrodziejstwo;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 16, 'A od was udać się do Macedonii, a z Macedonii znowu przybyć do was i zostać przez was wyprawionym do Judei.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 17, 'Czy więc tak postanawiając, postąpiłem lekkomyślnie? Albo czy to, co postanawiam, postanawiam według ciała, aby było u mnie „tak, tak” i „nie, nie”?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 18, 'Lecz jak Bóg jest wierny, tak nasze słowa do was nie były „tak” i „nie”.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 19, 'Ponieważ Syn Boży, Jezus Chrystus, który wśród was głoszony był przez nas, to znaczy przeze mnie, Sylwana i Tymoteusza, nie był „tak” i „nie”, lecz było w nim „tak”.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 20, 'Ile jest bowiem obietnic Boga, w nim są „tak” i w nim są „Amen”, ku chwale Boga przez nas.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 21, 'Tym zaś, który utwierdza nas razem z wami w Chrystusie i który nas namaścił, jest Bóg;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 22, 'Który też zapieczętował nas i dał do naszych serc Ducha jako zadatek.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 23, 'A ja wzywam Boga na świadka mojej duszy, że aby was oszczędzić, nie przybyłem dotąd do Koryntu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 24, 'Nie dlatego, że panujemy nad waszą wiarą, ale jesteśmy pomocnikami waszej radości; wiarą bowiem stoicie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 1, 'A postanowiłem to sobie, aby nie przychodzić do was znowu w smutku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 2, 'Jeśli bowiem ja was zasmucam, to któż może mnie rozweselić, jeśli nie ten, którego ja zasmucam?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 3, 'A to wam napisałem, abym, gdy przyjdę, nie doznał smutku od tych, od których powinienem doznawać radości, będąc pewien co do was wszystkich, że moja radość jest także waszą radością.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 4, 'Gdyż w wielkim ucisku i utrapieniu serca, wśród wielu łez pisałem do was nie po to, abyście się smucili, ale żebyście poznali, jak wielka jest moja miłość do was.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 5, 'Jeśli więc ktoś spowodował smutek, to nie mnie zasmucił, ale po części – by nie obciążyć – was wszystkich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 6, 'Takiemu wystarczy kara wymierzona przez wielu z was.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 7, 'Tak więc przeciwnie, powinniście mu raczej przebaczyć i pocieszyć go, aby przypadkiem zbytni smutek go nie pochłonął.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 8, 'Dlatego proszę was, abyście potwierdzili swą miłość do niego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 9, 'Po to też pisałem, aby was wypróbować i się przekonać, czy we wszystkim jesteście posłuszni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 10, 'A komu wy coś przebaczacie, temu i ja, gdyż i ja, jeśli coś przebaczyłem temu, któremu przebaczyłem, zrobiłem to ze względu na was wobec Chrystusa;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 11, 'Aby nas szatan nie podszedł; jego zamysły bowiem nie są nam nieznane.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 12, 'Gdy zaś przybyłem do Troady, aby głosić ewangelię Chrystusa, a drzwi zostały mi otwarte w Panu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 13, 'Nie zaznałem spokoju ducha, bo nie znalazłem Tytusa, mego brata. Rozstawszy się więc z nimi, wyruszyłem do Macedonii.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 14, 'Lecz dzięki Bogu, który nam zawsze daje zwycięstwo w Chrystusie i roznosi przez nas woń swojego poznania w każdym miejscu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 15, 'Jesteśmy bowiem dla Boga przyjemną wonią Chrystusa wśród tych, którzy są zbawieni, i wśród tych, którzy giną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 16, 'Dla jednych wonią śmierci ku śmierci, a dla drugich wonią życia ku życiu. Lecz do tego któż jest zdatny?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 17, 'Nie jesteśmy bowiem jak wielu, którzy fałszują słowo Boże, lecz ze szczerości, jak od Boga mówimy w Chrystusie przed obliczem Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 1, 'Czy znowu zaczynamy polecać samych siebie? Albo czy potrzebujemy, jak niektórzy, listów polecających do was albo od was?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 2, 'Naszym listem wy jesteście, napisanym w naszych sercach, znanym i czytanym przez wszystkich ludzi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 3, 'Gdyż wiadomo, że jesteście listem Chrystusowym sporządzonym przez nasze posługiwanie, napisanym nie atramentem, lecz Duchem Boga żywego, nie na tablicach kamiennych, lecz na żywych tablicach serc.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 4, 'A taką ufność mamy przez Chrystusa ku Bogu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 5, 'Nie żebyśmy sami z siebie byli w stanie pomyśleć coś jakby z samych siebie, lecz nasza możność jest z Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 6, 'On też uczynił nas zdolnymi sługami nowego testamentu, nie litery, ale Ducha; litera bowiem zabija, Duch zaś ożywia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 7, 'Lecz jeśli posługiwanie śmierci, wyryte literami na kamieniach, było pełne chwały, tak że synowie Izraela nie mogli wpatrywać się w oblicze Mojżesza z powodu chwały jego oblicza, która miała przeminąć;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 8, 'To o ileż bardziej pełne chwały nie miałoby być posługiwanie Ducha?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 9, 'Jeśli bowiem posługiwanie potępienia było pełne chwały, o ileż bardziej obfituje w chwałę posługiwanie sprawiedliwości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 10, 'To bowiem, co miało chwałę, nie miało chwały w porównaniu z tą przewyższającą chwałą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 11, 'Jeśli zaś to, co przemija, było pełne chwały, tym bardziej pełne chwały jest to, co trwa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 12, 'Mając więc taką nadzieję, z całą otwartością mówimy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 13, 'A nie jak Mojżesz, który kładł sobie na twarz zasłonę, aby synowie Izraela nie wpatrywali się w koniec tego, co miało przeminąć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 14, 'Lecz ich umysły zostały zaślepione; aż do dziś bowiem przy czytaniu Starego Testamentu ta sama zasłona pozostaje nieodsłonięta, gdyż jest usuwana w Chrystusie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 15, 'I aż do dziś, gdy Mojżesz jest czytany, zasłona leży na ich sercu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 16, 'Gdy jednak nawrócą się do Pana, zasłona zostanie zdjęta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 17, 'Pan zaś jest tym Duchem, a gdzie jest Duch Pana, tam i wolność.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 18, 'Lecz my wszyscy, którzy z odsłoniętą twarzą patrzymy na chwałę Pana, jakby w zwierciadle, zostajemy przemienieni w ten sam obraz, z chwały w chwałę, za sprawą Ducha Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 1, 'Dlatego mając to posługiwanie, tak jak otrzymaliśmy miłosierdzie, nie zniechęcamy się.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 2, 'Lecz wyrzekliśmy się ukrytych haniebnych czynów, nie postępując podstępnie ani nie fałszując słowa Bożego, ale przez ujawnianie prawdy polecamy samych siebie sumieniu każdego człowieka w obliczu Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 3, 'A jeśli nasza ewangelia jest zakryta, to jest zakryta dla tych, którzy giną;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 4, 'W których bóg tego świata zaślepił umysły, w niewierzących, aby nie świeciła im światłość chwalebnej ewangelii Chrystusa, który jest obrazem Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 5, 'Nie głosimy bowiem samych siebie, lecz Chrystusa Jezusa, że jest Panem, a samych siebie, że jesteśmy waszymi sługami dla Jezusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 6, 'Ponieważ Bóg, który rozkazał, aby z ciemności zabłysnęło światło, ten zabłysnął w naszych sercach, aby zajaśniało w nas poznanie chwały Bożej w obliczu Jezusa Chrystusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 7, 'Mamy zaś ten skarb w naczyniach glinianych, aby wspaniałość tej mocy była z Boga, a nie z nas.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 8, 'Zewsząd jesteśmy uciskani, lecz nie przygnębieni, bezradni, lecz nie zrozpaczeni;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 9, 'Prześladowani, lecz nie opuszczeni, powaleni, ale nie zgładzeni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 10, 'Nieustannie nosimy w ciele umieranie Pana Jezusa, aby i życie Jezusa objawiło się w naszym ciele.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 11, 'Zawsze bowiem my, którzy żyjemy, jesteśmy wydawani na śmierć z powodu Jezusa, aby i życie Jezusa objawiło się w naszym śmiertelnym ciele.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 12, 'Tak więc w nas działa śmierć, a w was życie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 13, 'Mając zaś tego samego ducha wiary, jak jest napisane: Uwierzyłem i dlatego przemówiłem; my również wierzymy i dlatego mówimy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 14, 'Wiedząc, że ten, który wskrzesił Pana Jezusa, przez Jezusa wskrzesi także nas i postawi razem z wami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 15, 'Wszystko to bowiem dzieje się dla was, żeby obfitująca łaska, przez dziękczynienie wielu, rozmnożyła się ku chwale Bożej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 16, 'Dlatego nie zniechęcamy się, bo chociaż nasz zewnętrzny człowiek niszczeje, to jednak ten wewnętrzny odnawia się z dnia na dzień.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 17, 'Ten bowiem nasz chwilowy i lekki ucisk przynosi nam przeogromną i wieczną wagę chwały;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 18, 'Gdy nie patrzymy na to, co widzialne, lecz na to, co niewidzialne. To bowiem, co widzialne, jest doczesne, to zaś, co niewidzialne, jest wieczne.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 1, 'Wiemy bowiem, że jeśli zostanie zniszczony ten namiot naszego ziemskiego mieszkania, to mamy budowlę od Boga, dom nie ręką uczyniony, wieczny w niebiosach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 2, 'Dlatego w tym wzdychamy, pragnąc przyodziać się w nasz dom z nieba;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 3, 'Jeśli tylko zostaniemy znalezieni odziani, a nie nadzy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 4, 'Bo my, którzy jesteśmy w tym namiocie, wzdychamy, obciążeni, ponieważ nie pragniemy być rozebrani, ale przyodziani, aby to, co śmiertelne, zostało wchłonięte przez życie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 5, 'A tym, który nas do tego właśnie przygotował, jest Bóg, który nam też dał Ducha jako zadatek.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 6, 'Tak więc mamy zawsze ufność, wiedząc, że dopóki mieszkamy w tym ciele, tułamy się z dala od Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 7, '(Przez wiarę bowiem kroczymy, a nie przez widzenie.)');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 8, 'Mamy jednak ufność i wolelibyśmy raczej wyjść z ciała i zamieszkać u Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 9, 'Dlatego też zabiegamy o to, żeby się jemu podobać, czy mieszkamy w ciele, czy z niego wychodzimy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 10, 'Wszyscy bowiem musimy stanąć przed trybunałem Chrystusa, aby każdy otrzymał zapłatę za to, co czynił w ciele, według tego, co czynił, czy dobro, czy zło.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 11, 'Wiedząc zatem o tym strachu Pańskim, przekonujemy ludzi; dla Boga zaś wszystko w nas jest jawne; mam też nadzieję, że i dla waszych sumień wszystko w nas jest jawne.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 12, 'Bo nie polecamy wam ponownie samych siebie, ale dajemy wam sposobność do chlubienia się nami, żebyście mieli co odpowiedzieć tym, którzy się chlubią tym, co zewnętrzne, a nie sercem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 13, 'Jeśli zaś odchodzimy od zmysłów – dla Boga odchodzimy, jeżeli jesteśmy przy zdrowych zmysłach – dla was jesteśmy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 14, 'Miłość Chrystusa bowiem przymusza nas, jako tych, którzy uznaliśmy, że skoro jeden umarł za wszystkich, to wszyscy umarli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 15, 'A umarł za wszystkich, aby ci, którzy żyją, już więcej nie żyli dla siebie, lecz dla tego, który za nich umarł i został wskrzeszony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 16, 'Dlatego my odtąd nikogo nie znamy według ciała, a chociaż znaliśmy Chrystusa według ciała, to teraz już więcej go takim nie znamy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 17, 'Tak więc jeśli ktoś jest w Chrystusie, nowym jest stworzeniem; to, co stare, przeminęło, oto wszystko stało się nowe.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 18, 'A wszystko to jest z Boga, który nas pojednał ze sobą przez Jezusa Chrystusa i dał nam służbę pojednania.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 19, 'Bóg bowiem był w Chrystusie, jednając świat z samym sobą, nie poczytując ludziom ich grzechów, i nam powierzył to słowo pojednania.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 20, 'Tak więc w miejsce Chrystusa sprawujemy poselstwo, tak jakby Bóg upominał was przez nas. W miejsce Chrystusa prosimy: Pojednajcie się z Bogiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 21, 'On bowiem tego, który nie znał grzechu, za nas grzechem uczynił, abyśmy w nim stali się sprawiedliwością Bożą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 1, 'Jako jego współpracownicy napominamy was, abyście nie przyjmowali łaski Bożej na próżno.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 2, '(Mówi bowiem Bóg: W czasie pomyślnym wysłuchałem cię, a w dniu zbawienia przyszedłem ci z pomocą. Oto teraz czas pomyślny, oto teraz dzień zbawienia.)');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 3, 'Nie dając nikomu żadnego powodu do zgorszenia, aby nasza posługa nie była zhańbiona;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 4, 'Ale we wszystkim okazujemy się sługami Boga, w wielkiej cierpliwości, w uciskach, w niedostatkach, w utrapieniach;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 5, 'W chłostach, w więzieniach, podczas rozruchów, w trudach, w nocnych czuwaniach, w postach;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 6, 'Przez czystość i poznanie, przez wytrwałość i życzliwość, przez Ducha Świętego i nieobłudną miłość;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 7, 'Przez słowo prawdy i moc Boga, przez oręż sprawiedliwości na prawo i na lewo;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 8, 'Przez chwałę i pohańbienie, przez złą i dobrą sławę; jakby zwodziciele, a jednak prawdomówni;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 9, 'Jakby nieznani, jednak dobrze znani, jakby umierający, a oto żyjemy, jakby karani, ale nie zabici;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 10, 'Jakby smutni, jednak zawsze radośni, jakby ubodzy, jednak wielu ubogacający, jakby nic nie mający, jednak wszystko posiadający.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 11, 'Nasze usta otworzyły się przed wami, Koryntianie, nasze serce się rozszerzyło.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 12, 'Nie jest wam ciasno w nas, lecz w waszym wnętrzu jest ciasno;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 13, 'Odwzajemniając się więc nam – jak do moich dzieci mówię – rozszerzcie się i wy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 14, 'Nie wprzęgajcie się w nierówne jarzmo z niewierzącymi. Cóż bowiem wspólnego ma sprawiedliwość z niesprawiedliwością? Albo jaka jest wspólnota między światłem a ciemnością?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 15, 'Albo jaka zgoda Chrystusa z Belialem, albo co za dział wierzącego z niewierzącym?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 16, 'A co za porozumienie między świątynią Boga a bożkami? Wy bowiem jesteście świątynią Boga żywego, tak jak mówi Bóg: Będę w nich mieszkał i będę się przechadzał w nich, i będę ich Bogiem, a oni będą moim ludem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 17, 'Dlatego wyjdźcie spośród nich i odłączcie się, mówi Pan, i nieczystego nie dotykajcie, a ja was przyjmę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 18, 'I będę wam Ojcem, a wy będziecie mi synami i córkami – mówi Pan Wszechmogący.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 1, 'Mając więc te obietnice, najmilsi, oczyśćmy się z wszelkiego brudu ciała i ducha, dopełniając uświęcenia w bojaźni Bożej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 2, 'Przyjmijcie nas; nikogo nie skrzywdziliśmy, nikogo nie zepsuliśmy, nikogo nie wykorzystaliśmy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 3, 'Nie mówię tego, aby was potępiać; wcześniej bowiem powiedziałem, że jesteście w naszych sercach na wspólną śmierć i wspólne życie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 4, 'Mam wielką swobodę w mówieniu do was, bardzo się wami chlubię, jestem pełen pociechy, obfituję w radość w każdym naszym ucisku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 5, 'Kiedy bowiem przybyliśmy do Macedonii, nasze ciało nie zaznało żadnego odpoczynku, ale zewsząd byliśmy uciśnieni: na zewnątrz walki, a wewnątrz obawy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 6, 'Lecz Bóg, który pociesza uniżonych, pocieszył nas przez przybycie Tytusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 7, 'A nie tylko przez jego przybycie, ale też przez pociechę, jakiej doznał wśród was, gdy opowiedział nam o waszej tęsknocie, o waszym płaczu, o waszej gorliwości względem mnie, tak że uradowałem się jeszcze bardziej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 8, 'Choć bowiem zasmuciłem was listem, nie żałuję tego, a mimo że żałowałem (bo widzę, że ten list zasmucił was, chociaż tylko na chwilę);');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 9, 'To teraz się raduję, nie dlatego, że byliście zasmuceni, ale że byliście zasmuceni ku pokucie. Zostaliście bowiem zasmuceni według Boga, żebyście w niczym nie ponieśli szkody przez nas.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 10, 'Bo smutek, który jest według Boga, przynosi pokutę ku zbawieniu, czego nikt nie żałuje; lecz smutek według świata przynosi śmierć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 11, 'To bowiem, że byliście zasmuceni według Boga, jakąż wielką wzbudziło w was pilność, jakie uniewinnianie się, jakie oburzenie, jaką bojaźń, jaką tęsknotę, jaką gorliwość, jakie wymierzenie kary! We wszystkim okazaliście się czyści w tej sprawie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 12, 'Dlatego chociaż pisałem do was, nie pisałem z powodu tego, który wyrządził krzywdę, ani z powodu tego, który krzywdy doznał, lecz aby okazać nasze zatroskanie o was przed Bogiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 13, 'Tak więc zostaliśmy pocieszeni waszą pociechą. A jeszcze bardziej uradowaliśmy się radością Tytusa, bo jego duch został pokrzepiony przez was wszystkich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 14, 'Bo jeśli w czymś chlubiłem się wami przed nim, nie zostałem zawstydzony. Lecz tak, jak mówiliśmy wam wszystko zgodnie z prawdą, tak też nasza chluba przed Tytusem okazała się prawdziwa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 15, 'A jego serce jeszcze bardziej skłania się ku wam, gdy wspomina posłuszeństwo was wszystkich i to, jak przyjęliście go z bojaźnią i drżeniem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 16, 'Raduję się więc, że we wszystkim mogę wam ufać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 1, 'A oznajmiamy wam, bracia, o łasce Bożej, która jest dana kościołom Macedonii;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 2, 'Iż w ciężkiej próbie ucisku ich obfita radość i skrajne ubóstwo obfitowały bogactwem ich ofiarności.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 3, 'Zaświadczam bowiem, że według możliwości, a nawet ponad możliwość okazali gotowość;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 4, 'Z wielkim naleganiem prosząc nas, abyśmy przyjęli ten dar i ich udział w służbie na rzecz świętych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 5, 'A postąpili nie tylko tak, jak się spodziewaliśmy, ale samych siebie najpierw oddali Panu, a potem nam za wolą Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 6, 'Tak, że poprosiliśmy Tytusa, aby tak jak wcześniej zaczął, tak też dokończył u was tego dzieła łaski.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 7, 'Jak więc obfitujecie we wszystko, w wiarę, w mowę, w poznanie, we wszelką pilność i w miłość waszą do nas, tak i w tym dziele łaski obfitujcie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 8, 'Nie mówię tego jako rozkaz, lecz abym przez zapał innych wypróbował szczerość waszej miłości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 9, 'Znacie bowiem łaskę naszego Pana Jezusa Chrystusa, że będąc bogatym, dla was stał się ubogim, abyście wy zostali ubogaceni jego ubóstwem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 10, 'A w tej sprawie daję wam swoją radę, gdyż jest to pożyteczne dla was, którzy nie tylko zaczęliście to robić, ale już ubiegłego roku wykazaliście chęć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 11, 'Teraz więc to, co zaczęliście robić, dokończcie, aby tak, jak była gotowość w chęciach, tak też aby było wykonanie z tego, co macie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 12, 'Jeśli bowiem najpierw jest gotowość, jest przyjmowana według tego, co kto ma, a nie według tego, czego nie ma.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 13, 'Nie chodzi bowiem o to, żeby innym ulżyć, a was obciążyć;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 14, 'Lecz o równość, aby teraz wasza obfitość usłużyła ich niedostatkowi, aby też ich obfitość waszemu niedostatkowi usłużyła, tak żeby była równość;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 15, 'Jak jest napisane: Kto wiele nazbierał, nie miał za wiele, a kto mało nazbierał, nie miał za mało.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 16, 'Lecz Bogu niech będą dzięki, który wszczepił taką troskę o was w serce Tytusa;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 17, 'Że przyjął tę zachętę, a będąc bardziej gorliwym, dobrowolnie wybrał się do was.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 18, 'Posłaliśmy razem z nim brata, którego sława w ewangelii rozchodzi się po wszystkich kościołach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 19, 'A nie tylko to, ale też został wybrany przez kościoły na towarzysza naszej podróży w tym dziele łaski, którym służymy ku chwale samego Pana i ku okazaniu waszej gotowości;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 20, 'Wystrzegając się tego, aby nas ktoś nie ganił z powodu tego hojnego daru, którym służymy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 21, 'Starając się o to, co uczciwe, nie tylko przed Panem, ale też przed ludźmi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 22, 'A posłaliśmy z nimi naszego brata, którego pilność wielokrotnie wypróbowaliśmy w wielu sprawach, a który teraz jest o wiele bardziej pilny, ponieważ ma do was wielkie zaufanie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 23, 'A jeśli chodzi o Tytusa, jest on moim towarzyszem i współpracownikiem wśród was, jeśli zaś chodzi o naszych braci, są wysłannikami kościołów i chwałą Chrystusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 24, 'Okażcie im więc przed kościołami dowód waszej miłości i naszej chluby z was.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 1, 'Lecz o posłudze na rzecz świętych nie ma potrzeby, abym wam pisał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 2, 'Znam bowiem waszą gotowość, z powodu której wobec Macedończyków chlubię się wami, że Achaja jest gotowa od zeszłego roku, i wasza gorliwość pobudziła wielu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 3, 'Ale posłałem braci, żeby nasza chluba z was nie okazała się pod tym względem próżna, abyście, jak mówiłem, byli przygotowani;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 4, 'I abyśmy, jeśli przypadkiem przybyliby ze mną Macedończycy i zastali was nieprzygotowanymi, nie byli zawstydzeni my – żeby nie powiedzieć: wy – za tak śmiałe przechwalanie się.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 5, 'Uważałem więc za konieczne zachęcić braci, aby wcześniej udali się do was i zawczasu przygotowali przedtem obiecany wasz hojny dar, aby był gotowy jako wyraz hojności, a nie skąpstwa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 6, 'Lecz mówię: Kto skąpo sieje, skąpo też żąć będzie, a kto sieje obficie, obficie też żąć będzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 7, 'Każdy jak postanowił w swym sercu, tak niech zrobi, nie z żalem ani z przymusu, gdyż radosnego dawcę Bóg miłuje.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 8, 'A Bóg ma moc udzielić wam obficie wszelkiej łaski, abyście, mając zawsze wszystkiego pod dostatkiem, obfitowali we wszelki dobry uczynek;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 9, 'Jak jest napisane: Rozrzucił, dał ubogim, jego sprawiedliwość trwa na wieki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 10, 'A ten, który daje ziarno siewcy, niech i wam da chleba do jedzenia, i wasze ziarno rozmnoży, i zwiększy plon waszej sprawiedliwości;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 11, 'Abyście byli wzbogaceni we wszystko ku wszelkiej hojności, która sprawia, że z naszego powodu składane jest dziękczynienie Bogu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 12, 'Posługiwanie bowiem w tej służbie nie tylko zaspokaja niedostatki świętych, ale też obfituje w liczne dziękczynienia składane Bogu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 13, 'Gdyż przez doświadczenie tej posługi chwalą Boga za to, że jesteście posłuszni wyznawanej przez siebie ewangelii Chrystusa i hojni w udzielaniu im i wszystkim innym;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 14, 'A modląc się za was, tęsknią za wami z powodu obfitującej w was łaski Bożej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 15, 'Bogu niech będą dzięki za jego niewypowiedziany dar.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 1, 'A ja sam, Paweł, proszę was przez łagodność i życzliwość Chrystusa, ja, który, gdy jestem obecny wśród was, jestem pokorny w waszych oczach, lecz gdy jestem nieobecny, jestem śmiały wobec was.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 2, 'A proszę, żebym będąc obecny, nie musiał być śmiały tą pewnością siebie, którą zamierzam być śmiały wobec niektórych, którzy sądzą, że postępujemy według ciała.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 3, 'Chociaż bowiem w ciele żyjemy, nie walczymy według ciała;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 4, '(Gdyż oręż naszej walki nie jest cielesny, ale z Boga, i ma moc burzenia twierdz warownych);');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 5, 'Obalamy rozumowania i wszelką wyniosłość, która powstaje przeciwko poznaniu Boga, i zniewalamy wszelką myśl do posłuszeństwa Chrystusowi;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 6, 'Gotowi do ukarania wszelkiego nieposłuszeństwa, kiedy wasze posłuszeństwo będzie całkowite.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 7, 'Czy patrzycie tylko na to, co jest przed oczami? Jeśli ktoś jest przekonany, że należy do Chrystusa, to niech też weźmie pod uwagę, że jak on należy do Chrystusa, tak do Chrystusa należymy i my.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 8, 'Choćbym się bowiem jeszcze bardziej chełpił z naszej władzy, którą dał nam Pan ku zbudowaniu, a nie ku waszej zgubie, nie będę zawstydzony;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 9, 'Aby się nie wydawało, że chcę was straszyć listami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 10, 'Mówią bowiem: Listy ważkie są i mocne, ale gdy się zjawia osobiście, jest słaby, a jego mowa godna pogardy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 11, 'Kto tak sądzi, niech wie, że jakimi jesteśmy w słowach listów, będąc nieobecni, takimi też będziemy w czynie, gdy będziemy obecni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 12, 'Nie śmiemy bowiem zaliczać siebie do niektórych ani porównywać się z niektórymi, którzy polecają sami siebie. Nie mają bowiem rozumu, gdyż mierzą się własną miarą i porównują się sami ze sobą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 13, 'Lecz my nie będziemy się chlubili ponad miarę, ale według miary zasad, które Bóg nam wymierzył, miary, która sięgnęła aż do was.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 14, 'Nie przekraczamy bowiem ponad miarę samych siebie, jakbyśmy nie dotarli aż do was, bo przyszliśmy aż i do was z ewangelią Chrystusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 15, 'I nie chlubimy się ponad miarę z pracy innych, ale mamy nadzieję, że gdy wzrośnie w was wasza wiara, i my wzrośniemy obficie wśród was zgodnie z naszymi zasadami;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 16, 'Żeby głosić ewangelię poza waszymi granicami, nie chlubiąc się na cudzym obszarze tym, czego już inni dokonali.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 17, 'Kto więc się chlubi, w Panu niech się chlubi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 18, 'Nie ten bowiem, kto sam siebie poleca, jest wypróbowany, lecz ten, kogo poleca Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 1, 'O, gdybyście mogli trochę znieść moje głupstwo! Doprawdy znoście mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 2, 'Jestem bowiem zazdrosny o was Bożą zazdrością; zaślubiłem was bowiem jednemu mężowi, aby przedstawić was Chrystusowi jako czystą dziewicę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 3, 'Lecz boję się, by czasem, tak jak wąż swoją przebiegłością oszukał Ewę, tak też wasze umysły nie zostały skażone i nie odstąpiły od prostoty, która jest w Chrystusie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 4, 'Gdyby bowiem przyszedł ktoś i głosił innego Jezusa, którego my nie głosiliśmy, albo gdybyście przyjęli innego ducha, którego nie otrzymaliście, albo inną ewangelię, której nie przyjęliście, znosilibyście go z łatwością.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 5, 'A uważam, że w niczym nie ustępowałem tym wielkim apostołom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 6, 'Bo chociaż jestem prostakiem w mowie, to jednak nie w poznaniu; lecz staliśmy się jawni wobec was we wszystkim, pod każdym względem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 7, 'Czyż popełniłem grzech, uniżając samego siebie, abyście wy byli wywyższeni, że za darmo głosiłem wam ewangelię Bożą?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 8, 'Ograbiłem inne kościoły, biorąc od nich zapłatę, aby wam służyć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 9, 'A gdy byłem u was i znalazłem się w potrzebie, nikomu nie byłem ciężarem; mój niedostatek bowiem uzupełnili bracia, którzy przybyli z Macedonii. Pilnowałem się, aby w niczym nie być dla was ciężarem, i nadal będę się pilnował.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 10, 'Jak prawda Chrystusa jest we mnie, tak tej chluby nikt mi nie odbierze w granicach Achai.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 11, 'Dlaczego? Czy dlatego, że was nie miłuję? Bóg to wie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 12, 'Co zaś czynię, nadal będę czynił, aby pozbawić okazji tych, którzy jej szukają, aby w tym, z czego się chlubią, okazali się takimi jak my.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 13, 'Tacy bowiem są fałszywymi apostołami, podstępnymi pracownikami, którzy przybierają postać apostołów Chrystusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 14, 'I nic dziwnego, sam bowiem szatan przybiera postać anioła światłości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 15, 'Nic więc wielkiego, jeśli i jego słudzy przybierają postać sług sprawiedliwości. Koniec ich jednak będzie według ich uczynków.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 16, 'Mówię znowu: Niech nikt nie uważa mnie za głupiego; a jeśli już tak, to przyjmijcie mnie jako głupiego, abym i ja mógł się trochę pochlubić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 17, 'Co mówię, nie mówię według Pana, ale jakby w głupocie, w tym śmiałym przechwalaniu się.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 18, 'Skoro wielu chlubi się według ciała, i ja będę się chlubił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 19, 'Chętnie przecież znosicie głupich, sami będąc mądrymi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 20, 'Znosicie bowiem, gdy ktoś was bierze w niewolę, gdy ktoś was objada, gdy ktoś was wyzyskuje, gdy ktoś wynosi się ponad was, gdy was ktoś policzkuje.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 21, 'Mówię o hańbie, jakbyśmy byli słabi; lecz w czym ktoś jest śmiały – mówię jak głupi – ja też jestem śmiały.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 22, 'Są Hebrajczykami? Ja także. Są Izraelitami? Ja także. Są potomstwem Abrahama? Ja także.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 23, 'Są sługami Chrystusa? Mówię jak głupi: Ja jeszcze bardziej; w pracach więcej, w chłostach nad miarę, w więzieniach częściej, w niebezpieczeństwie śmierci wielokroć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 24, 'Od Żydów pięciokrotnie otrzymałem czterdzieści razów bez jednego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 25, 'Trzy razy byłem bity rózgami, raz kamienowany, trzy razy rozbił się ze mną okręt, dzień i noc spędziłem w głębinie morskiej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 26, 'Często w podróżach, w niebezpieczeństwach na rzekach, w niebezpieczeństwach od bandytów, w niebezpieczeństwach od własnego narodu, w niebezpieczeństwach od pogan, w niebezpieczeństwach w mieście, w niebezpieczeństwach na pustyni, w niebezpieczeństwach na morzu, w niebezpieczeństwach wśród fałszywych braci;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 27, 'W trudzie i znoju, często w czuwaniu, w głodzie i pragnieniu, często w postach, w zimnie i nagości;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 28, 'A poza tymi sprawami zewnętrznymi, w tym, co mi codziennie ciąży, w trosce o wszystkie kościoły.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 29, 'Któż jest słaby, żebym i ja nie był słaby? Któż się gorszy, żebym i ja nie płonął?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 30, 'Jeśli mam się chlubić, będę się chlubić z moich słabości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 31, 'Bóg i Ojciec naszego Pana Jezusa Chrystusa, który jest błogosławiony na wieki, wie, że nie kłamię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 32, 'W Damaszku namiestnik króla Aretasa otoczył strażą miasto Damasceńczyków, chcąc mnie schwytać;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 33, 'Ale przez okno spuszczono mnie w koszu przez mur i uszedłem jego rąk.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 1, 'Wprawdzie nie jest dla mnie pożyteczne chlubić się, to jednak przejdę do widzeń i objawień Pańskich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 2, 'Znam człowieka w Chrystusie, który przed czternastu laty – czy w ciele, nie wiem, czy poza ciałem, nie wiem, Bóg wie – został porwany aż do trzeciego nieba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 3, 'I znam takiego człowieka – czy w ciele, czy poza ciałem, nie wiem, Bóg wie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 4, 'Który został porwany do raju i słyszał niewypowiedziane słowa, których człowiekowi nie wolno mówić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 5, 'Z takiego człowieka będę się chlubić, a z samego siebie nie będę się chlubił, chyba że z moich słabości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 6, 'Gdybym bowiem chciał się chlubić, nie byłbym głupi, bo powiedziałbym prawdę. Powstrzymuję się jednak, aby ktoś nie myślał o mnie ponad to, jakim mnie widzi albo co ode mnie słyszy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 7, 'A żebym zbytnio nie wynosił się ogromem objawień, dany mi został cierń dla ciała, wysłannik szatana, aby mnie policzkował, żebym się ponad miarę nie wynosił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 8, 'Dlatego trzy razy prosiłem Pana, aby on odstąpił ode mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 9, 'Lecz powiedział mi: Wystarczy ci moja łaska. Moja moc bowiem doskonali się w słabości. Najchętniej więc będę się chlubił z moich słabości, aby zamieszkała we mnie moc Chrystusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 10, 'Dlatego mam upodobanie w słabościach, w zniewagach, w niedostatkach, w prześladowaniach, w uciskach ze względu na Chrystusa; gdy bowiem jestem słaby, wtedy jestem mocny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 11, 'Stałem się głupi, chlubiąc się; wy mnie do tego zmusiliście. Ja bowiem przez was powinienem być polecany, ponieważ nie byłem mniejszy niż ci wielcy apostołowie, chociaż jestem niczym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 12, 'Jednak znaki apostoła okazały się wśród was we wszelkiej cierpliwości, w znakach, cudach i przejawach mocy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 13, 'W czym bowiem jesteście gorsi od innych kościołów, jeśli nie w tym tylko, że ja sam nie byłem dla was ciężarem? Wybaczcie mi tę krzywdę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 14, 'Oto po raz trzeci jestem gotów przybyć do was i nie będę dla was ciężarem. Nie szukam bowiem tego, co wasze, ale was samych, ponieważ nie dzieci rodzicom powinny gromadzić skarby, ale rodzice dzieciom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 15, 'Lecz ja bardzo chętnie poniosę wydatki i samego siebie wydam za wasze dusze, chociaż im bardziej was miłuję, tym mniej jestem przez was miłowany.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 16, 'Ale niech i tak będzie; nie byłem dla was ciężarem, ale będąc przebiegły, zdobyłem was podstępem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 17, 'Czy wyzyskałem was przez kogoś z tych, których do was posłałem?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 18, 'Uprosiłem Tytusa i wysłałem z nim brata. Czy Tytus was wyzyskał? Czy nie postępowaliśmy w tym samym duchu? Czy nie kroczyliśmy tymi samymi śladami?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 19, 'Znowu sądzicie, że się przed wami usprawiedliwiamy? W obliczu Boga w Chrystusie mówimy, a to wszystko, najmilsi, dla waszego zbudowania.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 20, 'Obawiam się bowiem, żebym przypadkiem, gdy przyjdę, nie zastał was takimi, jakimi nie chciałbym was zastać, i żebyście wy nie zastali mnie takim, jakim nie chcielibyście; żeby przypadkiem nie było wśród was sporów, zazdrości, gniewu, kłótni, obmów, szemrania, wynoszenia się i zamieszań;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 21, 'Żeby, gdy znowu przyjdę, mój Bóg nie poniżył mnie wobec was i musiałbym opłakiwać wielu tych, którzy przedtem grzeszyli i nie pokutowali z nieczystości, nierządu i rozpusty, których się dopuścili.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 1, 'Oto teraz po raz trzeci idę do was. Na podstawie zeznania dwóch albo trzech świadków oparte będzie każde słowo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 2, 'Powiedziałem poprzednio i znowu mówię, jako obecny za drugim razem, a nieobecny teraz, piszę tym, którzy przedtem grzeszyli, i wszystkim innym, że jeśli znowu przybędę, nie oszczędzę nikogo;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 3, 'Skoro szukacie dowodu na to, że przeze mnie przemawia Chrystus, który nie jest słaby względem was, lecz jest mocny w was.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 4, 'Chociaż bowiem został ukrzyżowany wskutek słabości, to jednak żyje z mocy Boga. I my także w nim jesteśmy słabi, ale będziemy żyć z nim z mocy Boga względem was.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 5, 'Badajcie samych siebie, czy jesteście w wierze, samych siebie doświadczajcie. Czy nie wiecie o samych sobie, że Jezus Chrystus jest w was? Chyba że zostaliście odrzuceni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 6, 'Mam jednak nadzieję, że poznacie, iż my nie jesteśmy odrzuceni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 7, 'I modlę się do Boga, abyście nie czynili nic złego, nie po to, abyśmy my okazali się wypróbowani, ale abyście wy czynili to, co dobre, choćbyśmy byli jak odrzuceni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 8, 'Nie możemy bowiem nic uczynić przeciwko prawdzie, lecz dla prawdy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 9, 'Cieszymy się bowiem, gdy my jesteśmy słabi, a wy mocni; i tego też życzymy, abyście wy byli doskonali.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 10, 'Dlatego piszę to, będąc nieobecny, abym będąc obecny, nie musiał postępować surowo według mocy, którą mi dał Pan ku zbudowaniu, a nie ku niszczeniu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 11, 'Na koniec, bracia, miejcie się dobrze; bądźcie doskonali, pokrzepiajcie się, bądźcie jednomyślni, żyjcie w pokoju, a Bóg miłości i pokoju będzie z wami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 12, 'Pozdrówcie się nawzajem świętym pocałunkiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 13, 'Pozdrawiają was wszyscy święci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 14, 'Łaska Pana Jezusa Chrystusa, miłość Boga i wspólnota Ducha Świętego niech będzie z wami wszystkimi. Amen. Drugi list do Koryntian został napisany z Filippi, miasta Macedonii, przez Tytusa i Łukasza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 1, 'Paweł, apostoł nie od ludzi ani przez człowieka, ale przez Jezusa Chrystusa i Boga Ojca, który go wskrzesił z martwych;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 2, 'I wszyscy bracia, którzy są ze mną, do kościołów Galacji:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 3, 'Łaska wam i pokój od Boga Ojca i naszego Pana Jezusa Chrystusa;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 4, 'Który wydał samego siebie za nasze grzechy, aby nas wyrwać z obecnego złego świata według woli Boga i Ojca naszego;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 5, 'Któremu chwała na wieki wieków. Amen.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 6, 'Dziwię się, że tak szybko dajecie się odwieść od tego, który was powołał ku łasce Chrystusa, do innej ewangelii;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 7, 'Która nie jest inną; są tylko pewni ludzie, którzy was niepokoją i chcą wypaczyć ewangelię Chrystusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 8, 'Lecz choćbyśmy nawet my albo anioł z nieba głosił wam ewangelię inną od tej, którą wam głosiliśmy, niech będzie przeklęty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 9, 'Jak powiedzieliśmy przedtem, tak i teraz znowu mówię: Gdyby wam ktoś głosił ewangelię inną od tej, którą przyjęliście, niech będzie przeklęty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 10, 'Czy teraz bowiem chcę pozyskać ludzi, czy Boga? Albo czy staram się przypodobać ludziom? Gdybym nadal ludziom chciał się przypodobać, nie byłbym sługą Chrystusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 11, 'A oznajmiam wam, bracia, że głoszona przeze mnie ewangelia nie jest według człowieka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 12, 'Nie otrzymałem jej bowiem ani nie nauczyłem się jej od człowieka, ale przez objawienie Jezusa Chrystusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 13, 'Słyszeliście bowiem o moim dawniejszym postępowaniu w judaizmie, że ponad miarę prześladowałem kościół Boży i niszczyłem go;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 14, 'I wyprzedzałem w judaizmie wielu moich rówieśników z mojego narodu, będąc bardzo gorliwym zwolennikiem moich ojczystych tradycji.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 15, 'Lecz gdy upodobało się Bogu, który mnie odłączył w łonie mojej matki i powołał swoją łaską;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 16, 'Aby objawić swego Syna we mnie, abym głosił go wśród pogan, natychmiast, nie radząc się ciała i krwi;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 17, 'Ani nie udając się do Jerozolimy, do tych, którzy przede mną byli apostołami, poszedłem do Arabii, po czym znowu wróciłem do Damaszku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 18, 'Potem, trzy lata później, udałem się do Jerozolimy, aby zobaczyć się z Piotrem, u którego przebywałem piętnaście dni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 19, 'A spośród apostołów nie widziałem żadnego innego poza Jakubem, bratem Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 20, 'Oświadczam przed Bogiem, że w tym, co do was piszę, nie kłamię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 21, 'Potem udałem się w okolice Syrii i Cylicji;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 22, 'A nie byłem osobiście znany kościołom Judei, które są w Chrystusie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 23, 'Słyszeli tylko: ten, który kiedyś nas prześladował, teraz głosi wiarę, którą przedtem niszczył.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 24, 'I chwalili Boga z mojego powodu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 1, 'Potem, po czternastu latach, udałem się ponownie do Jerozolimy wraz z Barnabą, wziąwszy ze sobą także Tytusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 2, 'A udałem się tam zgodnie z objawieniem i przedstawiłem im ewangelię, którą głoszę wśród pogan, osobno zaś tym, którzy cieszą się uznaniem, aby się czasem nie okazało, że biegnę albo biegłem na próżno.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 3, 'Lecz nawet Tytusa, który był ze mną, nie zmuszono do obrzezania, mimo że był Grekiem;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 4, 'A to z powodu wprowadzonych fałszywych braci, którzy się wkradli, aby wyszpiegować naszą wolność, jaką mamy w Chrystusie Jezusie, aby nas zniewolić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 5, 'Nie ustąpiliśmy im ani na chwilę i nie poddaliśmy się, aby pozostała wśród was prawda ewangelii.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 6, 'A co do cieszących się uznaniem – jakimi kiedyś byli, jest dla mnie bez znaczenia, Bóg bowiem nie ma względu na osobę – ci więc, którzy cieszą się uznaniem, nic mi nie narzucili.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 7, 'Wręcz przeciwnie, gdy widzieli, że została mi powierzona ewangelia wśród nieobrzezanych, jak Piotrowi wśród obrzezanych;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 8, '(Ten bowiem, który działał skutecznie przez Piotra w sprawowaniu apostolstwa wśród obrzezanych, skutecznie działał i we mnie wśród pogan);');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 9, 'I gdy poznali daną mi łaskę, Jakub, Kefas i Jan, którzy są uważani za filary, podali mnie i Barnabie prawicę na znak wspólnoty, abyśmy my poszli do pogan, a oni do obrzezanych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 10, 'Bylebyśmy tylko pamiętali o ubogich, co też gorliwie starałem się czynić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 11, 'A gdy Piotr przybył do Antiochii, sprzeciwiłem mu się w twarz, bo był godny nagany.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 12, 'Zanim bowiem przyszli niektórzy od Jakuba, jadał razem z poganami. Gdy zaś oni przyszli, odsunął się i odłączył, obawiając się tych, którzy byli z obrzezania.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 13, 'A razem z nim obłudnie postępowali i inni Żydzi, tak że i Barnaba dał się wciągnąć w tę ich obłudę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 14, 'Lecz gdy zobaczyłem, że nie postępują zgodnie z prawdą ewangelii, powiedziałem Piotrowi wobec wszystkich: Jeśli ty, będąc Żydem, żyjesz po pogańsku, a nie po żydowsku, czemu przymuszasz pogan, aby żyli po żydowsku?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 15, 'My, którzy jesteśmy Żydami z urodzenia, a nie grzesznikami z pogan;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 16, 'Wiedząc, że człowiek nie jest usprawiedliwiony z uczynków prawa, ale przez wiarę w Jezusa Chrystusa, i my uwierzyliśmy w Jezusa Chrystusa, abyśmy byli usprawiedliwieni z wiary Chrystusa, a nie z uczynków prawa, dlatego że z uczynków prawa nie będzie usprawiedliwione żadne ciało.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 17, 'A jeśli my, szukając usprawiedliwienia w Chrystusie, sami okazaliśmy się grzesznikami, to czy Chrystus jest sługą grzechu? Nie daj Boże!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 18, 'Jeśli bowiem na nowo buduję to, co zburzyłem, samego siebie czynię przestępcą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 19, 'Bo ja przez prawo umarłem dla prawa, abym żył dla Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 20, 'Z Chrystusem jestem ukrzyżowany: żyję, ale już nie ja, lecz żyje we mnie Chrystus. A to, że teraz żyję w ciele, żyję w wierze Syna Bożego, który mnie umiłował i wydał za mnie samego siebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 21, 'Nie odrzucam łaski Boga. Jeśli bowiem przez prawo jest sprawiedliwość, to Chrystus umarł na próżno.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 1, 'O głupi Galaci! Któż was omamił, abyście nie byli posłuszni prawdzie, was, przed których oczami został wymalowany Jezus Chrystus i wśród których został ukrzyżowany?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 2, 'Tego tylko chciałbym się od was dowiedzieć: Czy przez uczynki prawa otrzymaliście Ducha, czy przez słuchanie wiary?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 3, 'Tak głupi jesteście? Rozpoczęliście duchem, a teraz kończycie ciałem?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 4, 'Tak wiele cierpieliście na próżno, jeśli rzeczywiście na próżno?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 5, 'Ten więc, który udziela wam Ducha i czyni cuda wśród was, czyni to przez uczynki prawa czy przez słuchanie wiary?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 6, 'Tak jak Abraham uwierzył Bogu i zostało mu to poczytane za sprawiedliwość.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 7, 'Wiedzcie zatem, że ci, którzy są z wiary, ci są synami Abrahama.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 8, 'A Pismo, które przewidziało, że Bóg z wiary będzie usprawiedliwiał pogan, wcześniej ogłosiło ewangelię Abrahamowi: W tobie będą błogosławione wszystkie narody.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 9, 'Tak więc ci, którzy są z wiary, dostępują błogosławieństwa wraz z wierzącym Abrahamem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 10, 'Na wszystkich bowiem, którzy są z uczynków prawa, ciąży przekleństwo, bo jest napisane: Przeklęty każdy, kto nie wytrwa w wypełnianiu wszystkiego, co jest napisane w księdze Prawa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 11, 'A że przez prawo nikt nie jest usprawiedliwiony przed Bogiem, jest oczywiste, bo: Sprawiedliwy będzie żył z wiary.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 12, 'Prawo zaś nie jest z wiary, lecz: Człowiek, który je wypełnia, przez nie będzie żył.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 13, 'Chrystus odkupił nas z przekleństwa prawa, stając się za nas przekleństwem (bo jest napisane: Przeklęty każdy, kto wisi na drzewie);');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 14, 'Aby błogosławieństwo Abrahama w Chrystusie Jezusie przeszło na pogan i abyśmy przez wiarę otrzymali obietnicę Ducha.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 15, 'Bracia, mówię po ludzku: Przecież nawet zatwierdzonego testamentu człowieka nikt nie obala ani do niego nic nie dodaje.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 16, 'Otóż Abrahamowi i jego potomkowi zostały dane obietnice. Nie mówi: I jego potomkom, jak o wielu, ale jak o jednym: I twemu potomkowi, którym jest Chrystus.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 17, 'To zaś mówię: Przymierza zatwierdzonego przedtem przez Boga względem Chrystusa nie znosi prawo, które powstało czterysta trzydzieści lat później, tak aby unieważnić obietnicę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 18, 'Jeśli bowiem dziedzictwo jest z prawa, to już nie z obietnicy. Lecz Bóg darował je Abrahamowi przez obietnicę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 19, 'Po co więc prawo? Zostało dodane z powodu przestępstw, aż do przyjścia potomka, któremu złożono obietnicę, ustanowione przez aniołów ręką pośrednika.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 20, 'Lecz pośrednik nie jest dla jednego, ale Bóg jest jeden.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 21, 'Czy więc prawo jest przeciwko obietnicom Boga? Nie daj Boże! Gdyby bowiem zostało dane prawo, które mogłoby ożywiać, sprawiedliwość rzeczywiście byłaby z prawa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 22, 'Lecz Pismo zamknęło wszystko pod grzech, aby obietnica z wiary Jezusa Chrystusa została dana wierzącym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 23, 'Zanim zaś przyszła wiara, byliśmy poddani pod straż prawa i trzymani w zamknięciu aż do tej wiary, która potem miała być objawiona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 24, 'Tak więc prawo było naszym pedagogiem do Chrystusa, abyśmy z wiary byli usprawiedliwieni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 25, 'Lecz gdy przyszła wiara, już nie jesteśmy pod pedagogiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 26, 'Wszyscy bowiem jesteście synami Bożymi przez wiarę w Chrystusa Jezusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 27, 'Bo wszyscy, którzy zostaliście ochrzczeni w Chrystusie, przyodzialiście się w Chrystusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 28, 'Nie ma Żyda ani Greka, nie ma niewolnika ani wolnego, nie ma mężczyzny ani kobiety; wszyscy bowiem jedno jesteście w Chrystusie Jezusie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 29, 'A jeśli należycie do Chrystusa, to jesteście potomstwem Abrahama, a zgodnie z obietnicą – dziedzicami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 1, 'Mówię więc: Dopóki dziedzic jest dzieckiem, niczym się nie różni od sługi, chociaż jest panem wszystkiego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 2, 'Lecz jest poddany opiekunom i zarządcom aż do czasu wyznaczonego przez ojca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 3, 'Podobnie i my, gdy byliśmy dziećmi, byliśmy w niewoli żywiołów tego świata.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 4, 'Lecz gdy nadeszła pełnia czasu, Bóg posłał swego Syna, zrodzonego z kobiety, zrodzonego pod prawem;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 5, 'Aby wykupił tych, którzy byli pod prawem, abyśmy dostąpili usynowienia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 6, 'A ponieważ jesteście synami, Bóg posłał do waszych serc Ducha swego Syna, wołającego: Abba, Ojcze!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 7, 'Tak więc już nie jesteś sługą, ale synem, a jeśli synem, to i dziedzicem Bożym przez Chrystusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 8, 'Wprawdzie dawniej, gdy nie znaliście Boga, służyliście tym, którzy z natury nie są bogami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 9, 'Ale teraz, gdy poznaliście Boga, a raczej gdy zostaliście przez Boga poznani, jakże możecie ponownie wracać do słabych i nędznych żywiołów, którym ponownie chcecie służyć?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 10, 'Zachowujecie dni i miesiące, pory i lata.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 11, 'Boję się o was, czy przypadkiem na próżno nie trudziłem się nad wami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 12, 'Bracia, proszę was, bądźcie tacy jak ja, gdyż i ja jestem taki jak wy. W niczym mnie nie skrzywdziliście.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 13, 'Wiecie przecież, że pierwszy raz głosiłem wam ewangelię w słabości ciała.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 14, 'A mojej cielesnej próby nie lekceważyliście sobie ani nie wzgardziliście, ale przyjęliście mnie jak anioła Boga, jak samego Chrystusa Jezusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 15, 'Gdzież więc się podziało to wasze błogosławieństwo? Daję wam bowiem świadectwo, że gdyby to było możliwe, wyłupilibyście sobie oczy i dali je mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 16, 'Czy mówiąc wam prawdę, stałem się waszym nieprzyjacielem?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 17, 'Gorliwie o was zabiegają niedobrze, lecz chcą was odłączyć, abyście o nich zabiegali.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 18, 'A zawsze jest dobrze zabiegać gorliwie o to, co dobre, a nie tylko wtedy, gdy jestem obecny wśród was.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 19, 'Moje dzieci, które znowu w bólach rodzę, aż Chrystus w was się ukształtuje;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 20, 'Chciałbym teraz być wśród was i zmienić swój głos, ponieważ jestem zaniepokojony o was.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 21, 'Powiedzcie mi, wy, którzy chcecie być pod prawem, czy nie słuchacie, co mówi prawo?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 22, 'Napisane jest bowiem, że Abraham miał dwóch synów, jednego z niewolnicy, a drugiego z wolnej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 23, 'Lecz ten z niewolnicy urodził się według ciała, ten zaś z wolnej – według obietnicy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 24, 'Ma to znaczenie alegoryczne: te kobiety oznaczają dwa przymierza: jedno z góry Synaj, które rodzi w niewolę – jest nim Hagar.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 25, 'Hagar bowiem to góra Synaj w Arabii, a odpowiada ona dzisiejszemu Jeruzalem, bo jest ono w niewoli wraz ze swoimi dziećmi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 26, 'Natomiast Jeruzalem, które jest w górze, jest wolne i ono jest matką nas wszystkich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 27, 'Napisane jest bowiem: Raduj się, niepłodna, która nie rodzisz, wykrzyknij i zawołaj, która nie znasz bólów porodowych, bo ta opuszczona ma więcej dzieci niż ta, która ma męża.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 28, 'My więc, bracia, jak Izaak jesteśmy dziećmi obietnicy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 29, 'Lecz jak kiedyś ten, który urodził się według ciała, prześladował tego, który urodził się według Ducha, tak dzieje się i teraz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 30, 'Co jednak mówi Pismo? Wypędź niewolnicę i jej syna. Nie będzie bowiem syn niewolnicy dziedziczył z synem wolnej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 31, 'Tak więc, bracia, nie jesteśmy dziećmi niewolnicy, ale wolnej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 1, 'Trwajcie więc w tej wolności, którą nas Chrystus wyzwolił, i nie poddawajcie się na nowo pod jarzmo niewoli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 2, 'Oto ja, Paweł, mówię wam, że jeśli dacie się obrzezać, Chrystus na nic wam się nie przyda.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 3, 'A oświadczam raz jeszcze każdemu człowiekowi, który daje się obrzezać, że jest zobowiązany wypełnić całe prawo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 4, 'Pozbawiliście się Chrystusa wszyscy, którzy usprawiedliwiacie się przez prawo; wypadliście z łaski.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 5, 'My bowiem przez Ducha oczekujemy nadziei sprawiedliwości z wiary.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 6, 'Bo w Chrystusie Jezusie ani obrzezanie nic nie znaczy, ani nieobrzezanie, ale wiara, która działa przez miłość.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 7, 'Biegliście dobrze. Któż wam przeszkodził, abyście nie byli posłuszni prawdzie?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 8, 'Namawianie to nie pochodzi od tego, który was powołuje.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 9, 'Trochę zakwasu całe ciasto zakwasza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 10, 'Mam co do was przekonanie w Panu, że nie będziecie innego zdania. A ten, kto was niepokoi, zostanie osądzony, kimkolwiek by był.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 11, 'A ja, bracia, jeśli nadal obrzezanie głoszę, to dlaczego jeszcze cierpię prześladowanie? Przecież wtedy zniesione byłoby zgorszenie krzyża.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 12, 'Bodajby byli odcięci ci, którzy was niepokoją.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 13, 'Bo wy, bracia, zostaliście powołani do wolności, tylko pod pozorem tej wolności nie pobłażajcie ciału, ale z miłości służcie jedni drugim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 14, 'Całe bowiem prawo wypełnia się w tym jednym słowie, mianowicie: Będziesz miłował swego bliźniego jak samego siebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 15, 'Lecz jeśli wzajemnie się kąsacie i pożeracie, uważajcie, abyście się wzajemnie nie zjedli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 16, 'Mówię więc: Postępujcie w Duchu, a nie spełnicie pożądania ciała.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 17, 'Ciało bowiem pożąda na przekór Duchowi, a Duch na przekór ciału; są one sobie przeciwne, tak że nie możecie czynić tego, co chcecie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 18, 'Lecz jeśli jesteście prowadzeni przez Ducha, nie jesteście pod prawem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 19, 'A znane są uczynki ciała, którymi są: cudzołóstwo, nierząd, nieczystość, rozpusta;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 20, 'Bałwochwalstwo, czary, nienawiść, niezgoda, zawiść, gniew, spory, kłótnie, herezje;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 21, 'Zazdrość, zabójstwa, pijaństwo, hulanki i tym podobne; o nich wam mówię, jak już przedtem powiedziałem, że ci, którzy takie rzeczy czynią, królestwa Bożego nie odziedziczą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 22, 'Owocem zaś Ducha jest miłość, radość, pokój, cierpliwość, życzliwość, dobroć, wiara;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 23, 'Łagodność, powściągliwość. Przeciwko takim nie ma prawa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 24, 'A ci, którzy należą do Chrystusa, ukrzyżowali swoje ciało wraz z namiętnościami i pożądliwościami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 25, 'Jeśli żyjemy w Duchu, w Duchu też postępujmy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 26, 'Nie bądźmy żądni próżnej chwały, jedni drugich drażniąc, jedni drugim zazdroszcząc.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 1, 'Bracia, jeśli przydarzy się komuś jakiś upadek, wy, którzy jesteście duchowi, poprawiajcie takiego w duchu łagodności, uważając każdy na samego siebie, abyś i ty nie był kuszony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 2, 'Jedni drugich brzemiona noście, a tak wypełniajcie prawo Chrystusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 3, 'Jeśli bowiem ktoś uważa, że jest czymś, będąc niczym, ten zwodzi samego siebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 4, 'Każdy zaś niech bada swoje własne czyny, a wtedy będzie mieć powód do chluby w samym sobie, a nie w kimś innym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 5, 'Każdy bowiem poniesie swoje własne brzemię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 6, 'A ten, kto jest nauczany słowa, niech udziela ze wszystkich dóbr temu, który go naucza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 7, 'Nie łudźcie się, Bóg nie da się z siebie naśmiewać. Co bowiem człowiek sieje, to też żąć będzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 8, 'Bo kto sieje dla swego ciała, z ciała żąć będzie zniszczenie. Kto zaś sieje dla Ducha, z Ducha żąć będzie życie wieczne.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 9, 'A w czynieniu dobra nie bądźmy znużeni, bo w swoim czasie żąć będziemy, jeśli nie ustaniemy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 10, 'Dlatego więc, dopóki mamy czas, czyńmy dobrze wszystkim, a zwłaszcza domownikom wiary.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 11, 'Widzicie, jaki długi list napisałem do was własnoręcznie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 12, 'Ci wszyscy, którzy chcą się podobać według ciała, przymuszają was do obrzezania, aby tylko nie cierpieć prześladowania z powodu krzyża Chrystusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 13, 'Ci bowiem, którzy są obrzezani, sami nie zachowują prawa, ale chcą, abyście wy dali się obrzezać, żeby się chlubić waszym ciałem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 14, 'Co do mnie, nie daj Boże, abym się miał chlubić z czegoś innego, jak tylko z krzyża naszego Pana Jezusa Chrystusa, przez którego świat jest ukrzyżowany dla mnie, a ja dla świata.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 15, 'W Chrystusie Jezusie bowiem ani obrzezanie nic nie znaczy, ani nieobrzezanie, ale nowe stworzenie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 16, 'A na tych wszystkich, którzy będą postępować według tej zasady, niech przyjdzie pokój i miłosierdzie, i na Izraela Bożego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 17, 'Odtąd niech mi nikt nie sprawia przykrości. Ja bowiem na swoim ciele noszę piętna Pana Jezusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 18, 'Łaska naszego Pana Jezusa Chrystusa niech będzie z waszym duchem, bracia. Amen. List do Galacjan został napisany z Rzymu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 1, 'Paweł, apostoł Jezusa Chrystusa z woli Boga, do świętych, którzy są w Efezie, i wiernych w Chrystusie Jezusie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 2, 'Łaska wam i pokój od Boga, naszego Ojca, i Pana Jezusa Chrystusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 3, 'Błogosławiony niech będzie Bóg i Ojciec naszego Pana Jezusa Chrystusa, który pobłogosławił nas wszelkim duchowym błogosławieństwem w miejscach niebiańskich w Chrystusie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 4, 'Jak nas wybrał w nim przed założeniem świata, abyśmy byli święci i nienaganni przed jego obliczem w miłości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 5, 'Przeznaczył nas dla siebie, ku usynowieniu przez Jezusa Chrystusa, według upodobania swojej woli;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 6, 'Dla uwielbienia chwały swojej łaski, którą obdarzył nas w umiłowanym;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 7, 'W którym mamy odkupienie przez jego krew, przebaczenie grzechów, według bogactwa jego łaski;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 8, 'Którą nam hojnie okazał we wszelkiej mądrości i roztropności;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 9, 'Oznajmiając nam tajemnicę swojej woli, według swego upodobania, które sam w sobie postanowił;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 10, 'Aby w zarządzeniu pełni czasów wszystko zebrał w jedno w Chrystusie, i to, co w niebiosach, i to, co na ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 11, 'W nim, mówię, w którym też dostąpiliśmy udziału, przeznaczeni według postanowienia tego, który dokonuje wszystkiego według rady swojej woli;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 12, 'Abyśmy istnieli dla uwielbienia jego chwały, my, którzy wcześniej położyliśmy nadzieję w Chrystusie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 13, 'W nim i wy położyliście nadzieję, kiedy usłyszeliście słowo prawdy, ewangelię waszego zbawienia, w nim też, gdy uwierzyliście, zostaliście zapieczętowani obiecanym Duchem Świętym;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 14, 'Który jest zadatkiem naszego dziedzictwa, aż nastąpi odkupienie nabytej własności, dla uwielbienia jego chwały.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 15, 'Dlatego i ja, gdy usłyszałem o waszej wierze w Pana Jezusa i o miłości względem wszystkich świętych;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 16, 'Nie przestaję dziękować za was, czyniąc o was wzmiankę w moich modlitwach;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 17, 'Prosząc, aby Bóg naszego Pana Jezusa Chrystusa, Ojciec chwały, dał wam Ducha mądrości i objawienia w poznaniu jego samego;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 18, 'Ażeby oświecił oczy waszego umysłu, abyście wiedzieli, czym jest nadzieja jego powołania, czym jest bogactwo chwały jego dziedzictwa w świętych;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 19, 'I czym jest przemożna wielkość jego mocy wobec nas, którzy wierzymy, według działania potęgi jego siły.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 20, 'Okazał ją w Chrystusie, gdy go wskrzesił z martwych i posadził po swojej prawicy w miejscach niebiańskich;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 21, 'Wysoko ponad wszelką zwierzchnością i władzą, mocą, panowaniem i ponad wszelkim imieniem wypowiadanym nie tylko w tym świecie, ale i w przyszłym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 22, 'I wszystko poddał pod jego stopy, a jego samego dał jako głowę ponad wszystkim kościołowi;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 23, 'Który jest jego ciałem i pełnią tego, który wszystko we wszystkich napełnia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 1, 'I was ożywił, którzy byliście umarli w upadkach i w grzechach;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 2, 'W których niegdyś postępowaliście według zwyczaju tego świata i według władcy, który rządzi w powietrzu, ducha, który teraz działa w synach nieposłuszeństwa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 3, 'Wśród nich i my wszyscy żyliśmy niegdyś w pożądliwościach naszego ciała, czyniąc to, co się podobało ciału i myślom, i byliśmy z natury dziećmi gniewu, jak i inni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 4, 'Lecz Bóg, który jest bogaty w miłosierdzie, z powodu swojej wielkiej miłości, którą nas umiłował;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 5, 'I to wtedy, gdy byliśmy umarli w grzechach, ożywił nas razem z Chrystusem, gdyż łaską jesteście zbawieni;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 6, 'I razem z nim wskrzesił, i razem z nim posadził w miejscach niebiańskich w Chrystusie Jezusie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 7, 'Aby okazać w przyszłych wiekach przemożne bogactwo swojej łaski przez swoją dobroć względem nas w Chrystusie Jezusie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 8, 'Łaską bowiem jesteście zbawieni przez wiarę, i to nie jest z was, jest to dar Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 9, 'Nie z uczynków, aby nikt się nie chlubił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 10, 'Jesteśmy bowiem jego dziełem, stworzeni w Chrystusie Jezusie do dobrych uczynków, które Bóg wcześniej przygotował, abyśmy w nich postępowali.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 11, 'Dlatego pamiętajcie, że wy, niegdyś poganie w ciele, zwani nieobrzezaniem przez tych, których zwano obrzezaniem dokonanym ręką na ciele;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 12, 'Byliście w tamtym czasie bez Chrystusa, obcy względem społeczności Izraela i obcy przymierzom obietnicy, niemający nadziei i bez Boga na świecie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 13, 'Lecz teraz w Chrystusie Jezusie wy, którzy niegdyś byliście daleko, staliście się bliscy przez krew Chrystusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 14, 'On bowiem jest naszym pokojem, on, który z obydwu uczynił jedno i zburzył stojący pośrodku mur, który był przegrodą;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 15, 'Znosząc przez swoje ciało nieprzyjaźń, prawo przykazań wyrażone w przepisach, aby z dwóch stworzyć w samym sobie jednego nowego człowieka, czyniąc pokój;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 16, 'I aby pojednać z Bogiem obydwu w jednym ciele przez krzyż, zgładziwszy przez niego nieprzyjaźń.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 17, 'A gdy przyszedł, zwiastował pokój wam, którzy byliście daleko, i tym, którzy byli bliscy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 18, 'Przez niego bowiem my, obie strony, mamy przystęp w jednym Duchu do Ojca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 19, 'A więc nie jesteście już więcej obcymi i przybyszami, ale współobywatelami z świętymi i domownikami Boga;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 20, 'Zbudowani na fundamencie apostołów i proroków, gdzie kamieniem węgielnym jest sam Jezus Chrystus;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 21, 'Na którym cała budowla razem zespolona rośnie w świętą świątynię w Panu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 22, 'Na którym i wy razem się budujecie, aby być mieszkaniem Boga przez Ducha.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 1, 'Dlatego ja, Paweł, więzień Chrystusa Jezusa dla was, pogan;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 2, 'Jeśli tylko słyszeliście o udzieleniu łaski Boga, która jest mi dana dla was;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 3, 'Że przez objawienie została mi oznajmiona tajemnica, jak to wam przedtem krótko napisałem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 4, 'Dlatego czytając to, możecie zrozumieć moje poznanie tajemnicy Chrystusa;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 5, 'Która w innych wiekach nie była znana synom ludzkim, jak teraz została objawiona jego świętym apostołom i prorokom przez Ducha;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 6, 'Mianowicie, że poganie są współdziedzicami i członkami tego samego ciała, i współuczestnikami jego obietnicy w Chrystusie przez ewangelię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 7, 'Stałem się jej sługą według daru łaski Boga danej mi przez działanie jego mocy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 8, 'Mnie, najmniejszemu ze wszystkich świętych, została dana ta łaska, abym wśród pogan głosił te niezgłębione bogactwa Chrystusa;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 9, 'I żebym ujawnił wszystkim, jaka jest wspólnota tej tajemnicy ukrytej od wieków w Bogu, który wszystko stworzył przez Jezusa Chrystusa;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 10, 'Aby teraz wieloraka mądrość Boga poprzez kościół stała się jawna zwierzchnościom i władzom w miejscach niebiańskich;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 11, 'Zgodnie z wiecznym postanowieniem, które powziął w Chrystusie Jezusie, naszym Panu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 12, 'W nim mamy śmiałość i przystęp z ufnością przez wiarę jego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 13, 'Proszę zatem, abyście nie zniechęcali się z powodu moich utrapień, jakie znoszę dla was, bo to one są waszą chwałą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 14, 'Dlatego zginam swoje kolana przed Ojcem naszego Pana Jezusa Chrystusa;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 15, 'Od którego cała rodzina na niebie i na ziemi bierze swoją nazwę;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 16, 'Aby według bogactwa swej chwały sprawił, żeby wasz wewnętrzny człowiek był utwierdzony mocą przez jego Ducha;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 17, 'Aby Chrystus przez wiarę mieszkał w waszych sercach, abyście zakorzenieni i ugruntowani w miłości;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 18, 'Mogli pojąć wraz ze wszystkimi świętymi, jaka jest szerokość, długość, głębokość i wysokość;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 19, 'I poznać miłość Chrystusa, która przewyższa wszelkie poznanie, abyście zostali napełnieni całą pełnią Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 20, 'Temu zaś, który według mocy działającej w nas może uczynić o wiele obficiej ponad to wszystko, o co prosimy albo o czym myślimy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 21, 'Jemu niech będzie chwała w kościele przez Chrystusa Jezusa po wszystkie pokolenia na wieki wieków. Amen.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 1, 'Proszę więc was ja, więzień w Panu, abyście postępowali w sposób godny powołania, do jakiego zostaliście wezwani;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 2, 'Z całą pokorą, łagodnością i z cierpliwością, znosząc jedni drugich w miłości;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 3, 'Starając się zachować jedność Ducha w więzi pokoju.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 4, 'Jedno jest ciało i jeden Duch, jak też zostaliście powołani w jednej nadziei waszego powołania.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 5, 'Jeden Pan, jedna wiara, jeden chrzest;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 6, 'Jeden Bóg i Ojciec wszystkich, który jest ponad wszystkimi, przez wszystkich i w was wszystkich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 7, 'A każdemu z nas została dana łaska według miary daru Chrystusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 8, 'Dlatego Pismo mówi: Wstąpiwszy na wysokość, poprowadził pojmanych jeńców i dał ludziom dary.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 9, 'Lecz to, że wstąpił, cóż oznacza, jeśli nie to, że najpierw zstąpił do niższych regionów ziemi?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 10, 'Ten, który zstąpił, jest i tym, który wstąpił wysoko ponad wszystkie niebiosa, aby napełnić wszystko.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 11, 'I on ustanowił jednych apostołami, drugich prorokami, innych ewangelistami, a jeszcze innych pasterzami i nauczycielami;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 12, 'Dla przysposobienia świętych, dla dzieła posługiwania, dla budowania ciała Chrystusa;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 13, 'Aż dojdziemy wszyscy do jedności wiary i poznania Syna Bożego, do człowieka doskonałego, do miary dojrzałości pełni Chrystusa;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 14, 'Abyśmy już nie byli dziećmi miotanymi i unoszonymi każdym powiewem nauki przez oszustwo ludzkie i przez podstęp prowadzący na manowce błędu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 15, 'Lecz będąc szczerymi w miłości, wzrastajmy we wszystkim w tego, który jest głową – w Chrystusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 16, 'Z niego całe ciało harmonijnie złożone i zespolone we wszystkich stawach, dzięki działaniu każdego członka, stosownie do jego miary, przyczynia sobie wzrostu dla budowania samego siebie w miłości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 17, 'To więc mówię i zaświadczam w Panu, abyście już więcej nie postępowali tak, jak postępują inni poganie w próżności ich umysłu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 18, 'Mając przyćmiony rozum, obcy dla życia Bożego z powodu niewiedzy, która w nich jest, z powodu zatwardziałości ich serca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 19, 'Oni, stawszy się nieczuli, oddali się rozpuście, dopuszczając się wszelkiej nieczystości z zachłannością.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 20, 'Lecz wy nie tak nauczyliście się Chrystusa;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 21, 'Jeśli tylko słyszeliście go i byliście pouczeni przez niego, zgodnie z prawdą, jaka jest w Jezusie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 22, 'Że – co się tyczy poprzedniego postępowania – powinniście zrzucić z siebie starego człowieka, który ulega zepsuciu przez zwodnicze żądze;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 23, 'I odnowić się w duchu waszego umysłu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 24, 'I przyoblec się w nowego człowieka, który jest stworzony według Boga w sprawiedliwości i w prawdziwej świętości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 25, 'Dlatego odrzuciwszy kłamstwo, niech każdy mówi prawdę swojemu bliźniemu, bo jesteśmy członkami jedni drugich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 26, 'Gniewajcie się, lecz nie grzeszcie; niech nad waszym gniewem nie zachodzi słońce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 27, 'Nie dawajcie miejsca diabłu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 28, 'Kto kradł, niech więcej nie kradnie, ale raczej niech pracuje, czyniąc własnymi rękami to, co jest dobre, aby miał z czego udzielać potrzebującemu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 29, 'Żadne plugawe słowo niech nie wychodzi z waszych ust, lecz tylko dobre, dla zbudowania, aby przynosiło łaskę słuchającym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 30, 'I nie zasmucajcie Bożego Ducha Świętego, którym jesteście zapieczętowani na dzień odkupienia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 31, 'Wszelka gorycz i zapalczywość, gniew, wrzask i złorzeczenie niech zostaną usunięte spośród was wraz ze wszelką złośliwością.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 32, 'Bądźcie dla siebie nawzajem życzliwi, miłosierni, przebaczając sobie, jak i wam Bóg przebaczył w Chrystusie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 1, 'Bądźcie więc naśladowcami Boga jako umiłowane dzieci;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 2, 'I postępujcie w miłości, jak i Chrystus umiłował nas i wydał samego siebie za nas jako dar i ofiarę Bogu na miłą woń.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 3, 'A nierząd i wszelka nieczystość albo chciwość niech nie będą nawet wśród was wspominane, jak przystoi świętym;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 4, 'Także sprośność, niedorzeczne gadanie i nieprzyzwoite żarty, ale raczej dziękczynienie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 5, 'Bo wiecie o tym, że żaden rozpustnik ani nieczysty, ani chciwiec, to znaczy bałwochwalca, nie ma dziedzictwa w królestwie Chrystusa i Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 6, 'Niech was nikt nie zwodzi próżnymi słowami, bo z powodu tych rzeczy przychodzi gniew Boga na synów nieposłuszeństwa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 7, 'Nie bądźcie więc ich wspólnikami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 8, 'Byliście bowiem niegdyś ciemnością, lecz teraz jesteście światłością w Panu. Postępujcie jak dzieci światłości;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 9, '(Bo owoc Ducha jest we wszelkiej dobroci, sprawiedliwości i prawdzie).');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 10, 'Badając to, co podoba się Panu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 11, 'I nie miejcie nic wspólnego z bezowocnymi uczynkami ciemności, ale je raczej strofujcie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 12, 'O tym bowiem, co się u nich po kryjomu dzieje, wstyd nawet mówić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 13, 'A wszystko to, gdy jest strofowane, przez światło staje się jawne; to wszystko bowiem, co ujawnia, jest światłem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 14, 'Dlatego Pismo mówi: Obudź się, który śpisz, i powstań z martwych, a zajaśnieje ci Chrystus.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 15, 'Uważajcie więc, żebyście postępowali rozważnie, nie jak niemądrzy, ale jak mądrzy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 16, 'Odkupując czas, bo dni są złe.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 17, 'Dlatego nie bądźcie nierozumnymi, ale rozumiejcie, jaka jest wola Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 18, 'A nie upijajcie się winem, w którym jest rozwiązłość, ale bądźcie napełnieni Duchem;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 19, 'Rozmawiając z sobą przez psalmy, hymny i pieśni duchowe, śpiewając i grając Panu w swoim sercu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 20, 'Dziękując zawsze za wszystko Bogu i Ojcu w imię naszego Pana Jezusa Chrystusa;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 21, 'Będąc poddani sobie nawzajem w bojaźni Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 22, 'Żony, bądźcie poddane swoim mężom jak Panu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 23, 'Bo mąż jest głową żony, jak i Chrystus głową kościoła, jest on też Zbawicielem ciała.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 24, 'Jak więc kościół poddany jest Chrystusowi, tak też żony swoim mężom we wszystkim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 25, 'Mężowie, miłujcie swoje żony, jak i Chrystus umiłował kościół i wydał za niego samego siebie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 26, 'Aby go uświęcić, oczyściwszy obmyciem wodą przez słowo;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 27, 'By stawić przed sobą kościół chwalebny, niemający skazy ani zmarszczki, ani czegoś podobnego, lecz żeby był święty i nienaganny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 28, 'Tak też mężowie powinni miłować swoje żony jak własne ciało. Kto miłuje swoją żonę, samego siebie miłuje.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 29, 'Nikt bowiem nigdy nie miał w nienawiści swego ciała, ale je żywi i pielęgnuje, jak i Pan kościół.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 30, 'Gdyż jesteśmy członkami jego ciała, z ciała jego i z kości jego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 31, 'Dlatego opuści człowiek swego ojca i matkę i połączy się ze swoją żoną, i będą dwoje jednym ciałem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 32, 'Tajemnica to wielka, lecz ja mówię w odniesieniu do Chrystusa i kościoła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 33, 'Niech więc każdy z was z osobna miłuje swoją żonę jak samego siebie, a żona niech poważa swego męża.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 1, 'Dzieci, bądźcie posłuszne waszym rodzicom w Panu, bo jest to sprawiedliwe.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 2, 'Czcij swego ojca i matkę – jest to pierwsze przykazanie z obietnicą;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 3, 'Aby ci się dobrze powodziło i abyś długo żył na ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 4, 'A wy, ojcowie, nie pobudzajcie do gniewu waszych dzieci, lecz wychowujcie je w karności i w napominaniu Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 5, 'Słudzy, z bojaźnią i z drżeniem bądźcie posłuszni panom według ciała, w prostocie serca, jak Chrystusowi;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 6, 'Nie służąc dla oka, jak ci, którzy chcą podobać się ludziom, lecz jak słudzy Chrystusa, czyniąc wolę Boga z serca;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 7, 'Służąc z życzliwością, tak jak Panu, a nie ludziom;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 8, 'Wiedząc, że każdy, kto uczyni coś dobrego, to też otrzyma od Pana, czy niewolnik, czy wolny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 9, 'A wy, panowie, tak samo wobec nich postępujcie, porzucając groźby, wiedząc, że i wy sami macie Pana w niebie, a u niego nie ma względu na osoby.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 10, 'W końcu, moi bracia, umacniajcie się w Panu i w potędze jego mocy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 11, 'Przywdziejcie pełną zbroję Bożą, abyście mogli się ostać wobec zasadzek diabła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 12, 'Nie toczymy bowiem walki przeciw krwi i ciału, ale przeciw zwierzchnościom, przeciw władzom, przeciw rządcom ciemności tego świata, przeciw duchowemu złu na wyżynach niebieskich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 13, 'Dlatego weźcie pełną zbroję Bożą, abyście mogli przeciwstawić się w dzień zły, a wykonawszy wszystko, ostać się.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 14, 'Stańcie więc, przepasawszy wasze biodra prawdą, przywdziawszy pancerz sprawiedliwości;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 15, 'I obuwszy nogi w gotowość ewangelii pokoju.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 16, 'A przede wszystkim weźcie tarczę wiary, którą będziecie mogli zgasić wszystkie ogniste strzały złego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 17, 'Weźcie też hełm zbawienia i miecz Ducha, którym jest słowo Boże;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 18, 'We wszelkiej modlitwie i prośbie modląc się w każdym czasie w Duchu, czuwając nad tym z całą wytrwałością i z prośbą za wszystkich świętych;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 19, 'I za mnie, aby była mi dana mowa, bym z odwagą otworzył moje usta do oznajmienia tajemnicy ewangelii;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 20, 'Dla której sprawuję poselstwo w łańcuchach, abym o niej odważnie mówił, tak jak powinienem mówić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 21, 'Żebyście zaś wiedzieli i wy, co się ze mną dzieje i co robię, wszystko oznajmi wam Tychik, miły brat i wierny sługa w Panu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 22, 'Którego posłałem do was właśnie po to, abyście poznali nasze sprawy i aby pocieszył wasze serca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 23, 'Pokój braciom i miłość wraz z wiarą od Boga Ojca i Pana Jezusa Chrystusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 24, 'Łaska niech będzie ze wszystkimi, którzy miłują naszego Pana Jezusa Chrystusa w szczerości. Amen. List do Efezjan został napisany z Rzymu przez Tychika.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 1, 'Paweł i Tymoteusz, słudzy Jezusa Chrystusa, do wszystkich świętych w Chrystusie Jezusie, którzy są w Filippi, wraz z biskupami i diakonami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 2, 'Łaska wam i pokój od Boga, naszego Ojca, i Pana Jezusa Chrystusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 3, 'Dziękuję memu Bogu, ilekroć was wspominam;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 4, 'Zawsze w każdej mojej modlitwie prosząc z radością za was wszystkich;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 5, 'Za wasz współudział w ewangelii od pierwszego dnia aż do chwili obecnej;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 6, 'Będąc tego pewien, że ten, który rozpoczął w was dobre dzieło, dokończy go do dnia Jezusa Chrystusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 7, 'Słuszne jest, abym tak myślał o was wszystkich, dlatego że mam was w moim sercu, bo w moim więzieniu, jak i w obronie i utwierdzaniu ewangelii wszyscy jesteście ze mną uczestnikami łaski.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 8, 'Bóg bowiem jest mi świadkiem, jak tęsknię do was wszystkich najgłębszymi uczuciami Jezusa Chrystusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 9, 'I o to się modlę, aby wasza miłość coraz bardziej obfitowała w poznanie i we wszelkie zrozumienie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 10, 'Abyście mogli rozpoznać to, co lepsze, żebyście byli szczerzy i bez zarzutu na dzień Chrystusa;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 11, 'Napełnieni owocami sprawiedliwości, które przynosicie przez Jezusa Chrystusa ku chwale i czci Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 12, 'A chcę, bracia, abyście wiedzieli, że to, co mnie spotkało, spowodowało jeszcze większe rozkrzewienie ewangelii;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 13, 'Tak że moje więzy z powodu Chrystusa stały się znane w całym pałacu i u wszystkich innych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 14, 'A wielu braci w Panu nabrało otuchy z powodu moich więzów i z większą odwagą, bez lęku zaczęło głosić słowo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 15, 'Niektórzy wprawdzie z zazdrości i sporu, inni zaś z dobrej woli głoszą Chrystusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 16, 'Jedni ze sporu głoszą Chrystusa nieszczerze, sądząc, że dodadzą ucisku moim więzom;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 17, 'Inni zaś z miłości, wiedząc, że jestem przeznaczony do obrony ewangelii.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 18, 'Cóż więc? Mimo wszystko każdym sposobem, czy obłudnie, czy szczerze, Chrystus jest głoszony. Z tego się raduję i będę się radował.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 19, 'Wiem bowiem, że to doprowadzi do mojego zbawienia dzięki waszej modlitwie i pomocy Ducha Jezusa Chrystusa;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 20, 'Zgodnie z moim gorliwym oczekiwaniem i nadzieją, że w niczym nie będę zawstydzony, lecz z całą odwagą, jak zawsze, tak i teraz, uwielbiony będzie Chrystus w moim ciele, czy to przez życie, czy przez śmierć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 21, 'Dla mnie bowiem życie to Chrystus, a śmierć to zysk.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 22, 'Lecz jeśli życie w ciele jest dla mnie owocem mojej pracy, to nie wiem, co mam wybrać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 23, 'Jedno i drugie bowiem mnie naciska: chcę odejść i być z Chrystusem, bo to o wiele lepsze;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 24, 'Lecz pozostać w ciele jest bardziej potrzebne ze względu na was.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 25, 'A będąc tego pewien, wiem, że pozostanę i będę z wami wszystkimi dla waszego rozwoju i radości wiary;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 26, 'Aby obfitowała wasza chluba w Chrystusie Jezusie ze mnie, gdy znowu przybędę do was.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 27, 'Tylko postępujcie jak przystoi na ewangelię Chrystusa, abym czy przyjdę i zobaczę was, czy nie przyjdę, słyszał o was, że trwacie w jednym duchu, jednomyślnie walcząc o wiarę ewangelii;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 28, 'I w niczym nie dając się zastraszyć przeciwnikom. Dla nich jest to dowód zguby, a dla was zbawienia, i to od Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 29, 'Gdyż wam dla Chrystusa dane jest nie tylko w niego wierzyć, ale też dla niego cierpieć;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 30, 'Staczając tę samą walkę, którą widzieliście we mnie, i o której słyszycie, że teraz we mnie się toczy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 1, 'Jeśli więc jest jakieś pocieszenie w Chrystusie, jeśli jakaś pociecha miłości, jeśli jakaś wspólnota Ducha, jeśli jakieś współczucie i miłosierdzie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 2, 'Dopełnijcie mojej radości, bądźcie tej samej myśli, mając tę samą miłość, będąc zgodni i jednomyślni;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 3, 'Nie czyńcie nic z kłótliwości ani z próżnej chwały, lecz w pokorze uważajcie jedni drugich za wyższych od siebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 4, 'Niech każdy dba nie tylko o to, co jego, ale i o to, co innych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 5, 'Niech będzie w was takie nastawienie umysłu, jakie też było w Chrystusie Jezusie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 6, 'Który, będąc w postaci Boga, nie uważał bycia równym Bogu za grabież;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 7, 'Lecz ogołocił samego siebie, przyjmując postać sługi i stając się podobny do ludzi;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 8, 'A z postawy uznany za człowieka, uniżył samego siebie i był posłuszny aż do śmierci, i to śmierci krzyżowej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 9, 'Dlatego też Bóg wielce go wywyższył i darował mu imię, które jest ponad wszelkie imię;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 10, 'Aby na imię Jezusa zginało się wszelkie kolano na niebie, na ziemi i pod ziemią.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 11, 'I aby wszelki język wyznawał, że Jezus Chrystus jest Panem ku chwale Boga Ojca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 12, 'Dlatego, moi umiłowani, tak jak zawsze byliście posłuszni, nie tylko w mojej obecności, ale jeszcze bardziej teraz, pod moją nieobecność, z bojaźnią i drżeniem wykonujcie swoje zbawienie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 13, 'Bóg bowiem sprawia w was i chęć, i wykonanie według jego upodobania.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 14, 'Wszystko czyńcie bez szemrania i sporów;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 15, 'Abyście byli nienagannymi i niewinnymi dziećmi Bożymi, bez zarzutu pośród narodu złego i przewrotnego, wśród którego świecicie jak światła na świecie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 16, 'Zachowując słowo życia, abym mógł się chlubić w dniu Chrystusa, że nie na próżno biegłem i nie na próżno pracowałem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 17, 'Lecz choćbym został złożony na ofiarę i w posłudze waszej wiary, raduję się i cieszę z wami wszystkimi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 18, 'Z tego i wy radujcie się i cieszcie ze mną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 19, 'A mam nadzieję w Panu Jezusie, że wkrótce poślę do was Tymoteusza, abym został pocieszony, dowiedziawszy się, co się u was dzieje.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 20, 'Nie mam bowiem nikogo o równych jemu myślach, który by się szczerze troszczył o wasze sprawy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 21, 'Bo wszyscy szukają swego, a nie tego, co jest Jezusa Chrystusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 22, 'Wiecie zaś, że on jest wypróbowany, gdyż jak syn z ojcem, tak on wraz ze mną służył w ewangelii.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 23, 'Mam więc nadzieję, że poślę go do was, gdy tylko zobaczę, co dalej ze mną będzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 24, 'A mam ufność w Panu, że i sam wkrótce do was przybędę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 25, 'Uznałem też za konieczne posłać do was Epafrodyta, mego brata, współpracownika i współbojownika, a waszego wysłannika i sługę w moich potrzebach;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 26, 'Ponieważ tęsknił za wami wszystkimi i bardzo się smucił, gdyż słyszeliście, że zachorował.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 27, 'Rzeczywiście bowiem chorował tak, że był bliski śmierci. Lecz Bóg zmiłował się nad nim, a nie tylko nad nim, ale i nade mną, abym nie doznawał smutku za smutkiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 28, 'Dlatego tym pilniej posłałem go, abyście widząc go znowu, ucieszyli się, a ja żebym doznawał mniej smutku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 29, 'Przyjmijcie go więc w Panu z całą radością i miejcie takich w poszanowaniu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 30, 'Ponieważ dla sprawy Chrystusa bliski był śmierci, narażając swoje życie, aby dopełnić to, czego brakowało w waszej posłudze wobec mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 1, 'W końcu, moi bracia, radujcie się w Panu. Pisać do was o tym samym mnie nie męczy, a dla was jest bezpieczne.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 2, 'Strzeżcie się psów, strzeżcie się złych pracowników, strzeżcie się obrzezywaczy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 3, 'My bowiem jesteśmy obrzezaniem, którzy w duchu służymy Bogu i chlubimy się w Chrystusie Jezusie, a nie pokładamy ufności w ciele.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 4, 'Chociaż i ja mógłbym pokładać ufność w ciele. Jeśli ktoś inny uważa, że może pokładać ufność w ciele, bardziej ja:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 5, 'Obrzezany ósmego dnia, z rodu Izraela, z pokolenia Beniamina, Hebrajczyk z Hebrajczyków, co do prawa – faryzeusz;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 6, 'Co do gorliwości – prześladowca kościoła, co do sprawiedliwości opartej na prawie – nienaganny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 7, 'Lecz to, co było dla mnie zyskiem, ze względu na Chrystusa uznałem za stratę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 8, 'Owszem, wszystko uznaję za stratę dla znakomitości poznania Chrystusa Jezusa, mojego Pana, dla którego wszystko utraciłem i uznaję to za gnój, aby zyskać Chrystusa;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 9, 'I znaleźć się w nim, nie mając własnej sprawiedliwości, tej, która jest z prawa, ale tę, która jest przez wiarę Chrystusa, to jest sprawiedliwość z Boga przez wiarę;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 10, 'Żeby poznać jego i moc jego zmartwychwstania oraz swój udział w jego cierpieniach, upodabniając się do jego śmierci;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 11, 'Abym jakimkolwiek sposobem dostąpił powstania z martwych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 12, 'Nie żebym to już osiągnął albo już był doskonały, ale dążę, aby pochwycić to, do czego też zostałem pochwycony przez Chrystusa Jezusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 13, 'Bracia, ja o sobie nie myślę, że już pochwyciłem. Lecz jedno czynię: zapominając o tym, co za mną, a zdążając do tego, co przede mną;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 14, 'Biegnę do mety, do nagrody powołania Bożego, które jest z góry w Chrystusie Jezusie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 15, 'Ilu więc nas jest doskonałych, tak myślmy. A jeśli o czymś inaczej myślicie, i to wam Bóg objawi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 16, 'Jednak w tym, do czego doszliśmy, postępujmy według jednej miary i to samo myślmy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 17, 'Bądźcie, bracia, wszyscy razem moimi naśladowcami i przypatrujcie się tym, którzy postępują według wzoru, jaki w nas macie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 18, 'Wielu bowiem, o których wam często mówiłem, postępuje inaczej, a teraz nawet z płaczem mówię, że są wrogami krzyża Chrystusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 19, 'Ich końcem jest zatracenie, ich Bogiem jest brzuch, a ich chwała jest w hańbie; myślą oni o tym, co ziemskie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 20, 'Nasza zaś ojczyzna jest w niebie, skąd też oczekujemy Zbawiciela, Pana Jezusa Chrystusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 21, 'On przemieni nasze podłe ciało, aby było podobne do jego chwalebnego ciała, zgodnie ze skuteczną mocą, którą też może poddać sobie wszystko.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 1, 'Dlatego, moi bracia umiłowani i utęsknieni, moja radości i korono, tak trwajcie w Panu, moi umiłowani.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 2, 'Proszę Ewodię i proszę Syntychę, aby były jednomyślne w Panu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 3, 'Proszę też i ciebie, wierny towarzyszu, pomagaj tym, które razem ze mną pracowały w ewangelii, wraz z Klemensem i z innymi moimi współpracownikami, których imiona są w księdze życia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 4, 'Radujcie się zawsze w Panu; mówię ponownie, radujcie się.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 5, 'Niech wasza skromność będzie znana wszystkim ludziom. Pan jest blisko.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 6, 'Nie troszczcie się o nic, ale we wszystkim przez modlitwę i prośbę z dziękczynieniem niech wasze pragnienia będą znane Bogu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 7, 'A pokój Boży, który przewyższa wszelkie zrozumienie, będzie strzegł waszych serc i myśli w Chrystusie Jezusie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 8, 'W końcu, bracia, co prawdziwe, co uczciwe, co sprawiedliwe, co czyste, co miłe, co chwalebne, jeśli jest jakaś cnota i jakaś chwała – o tym myślcie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 9, 'Czyńcie to, czego się też nauczyliście, co przyjęliście, co słyszeliście i widzieliście we mnie, a Bóg pokoju będzie z wami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 10, 'Uradowałem się bardzo w Panu, że teraz zakwitło na nowo wasze staranie o mnie, bo staraliście się o to, lecz nie mieliście sposobności.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 11, 'Nie mówię tego z powodu niedostatku, bo nauczyłem się poprzestawać na tym, co mam.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 12, 'Umiem uniżać się, umiem też obfitować. Wszędzie i we wszystkim jestem wyćwiczony: umiem być syty i cierpieć głód, obfitować i znosić niedostatek.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 13, 'Wszystko mogę w Chrystusie, który mnie umacnia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 14, 'Jednak dobrze uczyniliście, uczestnicząc w moim ucisku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 15, 'A wy, Filipianie, wiecie, że na początku ewangelii, gdy opuściłem Macedonię, żaden kościół nie uczestniczył ze mną w dawaniu i braniu, tylko wy sami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 16, 'Bo nawet do Tesaloniki raz i drugi posłaliście, czego mi było potrzeba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 17, 'Nie żebym pragnął daru, ale pragnę owocu, który by wzrastał na wasze konto.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 18, 'Gdyż mam wszystko, i to w obfitości, jestem w pełni zaopatrzony, otrzymawszy od Epafrodyta to, co zostało posłane przez was, woń dobrego zapachu, ofiarę przyjemną i podobającą się Bogu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 19, 'Lecz mój Bóg zaspokoi wszelką waszą potrzebę według swego bogactwa w chwale, w Chrystusie Jezusie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 20, 'A Bogu i Ojcu naszemu niech będzie chwała na wieki wieków. Amen.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 21, 'Pozdrówcie każdego świętego w Chrystusie Jezusie. Pozdrawiają was bracia, którzy są ze mną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 22, 'Pozdrawiają was wszyscy święci, szczególnie zaś ci z domu cesarskiego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 23, 'Łaska naszego Pana Jezusa Chrystusa niech będzie z wami wszystkimi. Amen. List do Filipian został napisany z Rzymu przez Epafrodyta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 1, 'Paweł, apostoł Jezusa Chrystusa z woli Boga, i Tymoteusz, brat;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 2, 'Do świętych i wiernych braci w Chrystusie Jezusie, którzy są w Kolosach. Łaska wam i pokój od Boga, naszego Ojca, i od Pana Jezusa Chrystusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 3, 'Dziękujemy Bogu i Ojcu naszego Pana Jezusa Chrystusa, nieustannie modląc się za was;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 4, 'Odkąd usłyszeliśmy o waszej wierze w Chrystusa Jezusa i o miłości względem wszystkich świętych;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 5, 'Z powodu nadziei odłożonej dla was w niebie. O niej to przedtem słyszeliście w słowie prawdy ewangelii;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 6, 'Która dotarła do was, jak i na cały świat, i wydaje owoc, tak jak u was od dnia, w którym usłyszeliście i poznaliście łaskę Boga w prawdzie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 7, 'Jak też nauczyliście się od naszego umiłowanego współsługi Epafrasa, który jest wiernym sługą Chrystusa dla was;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 8, 'Który też oznajmił nam waszą miłość w Duchu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 9, 'Dlatego i my od tego dnia, w którym to usłyszeliśmy, nie przestajemy za was się modlić i prosić, abyście byli napełnieni poznaniem jego woli we wszelkiej mądrości i duchowym zrozumieniu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 10, 'Abyście postępowali w sposób godny Pana, by podobać mu się we wszystkim, w każdym dobrym uczynku wydając owoc i wzrastając w poznawaniu Boga;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 11, 'Umocnieni wszelką mocą według jego chwalebnej potęgi, ku wszelkiej cierpliwości i wytrwałości z radością;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 12, 'Dziękując Ojcu, który nas uzdolnił do uczestnictwa w dziedzictwie świętych w światłości;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 13, 'Który nas wyrwał z mocy ciemności i przeniósł do królestwa swego umiłowanego Syna;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 14, 'W którym mamy odkupienie przez jego krew, przebaczenie grzechów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 15, 'On jest obrazem Boga niewidzialnego i pierworodnym wszelkiego stworzenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 16, 'Przez niego bowiem wszystko zostało stworzone, to, co w niebie i to, co na ziemi, to, co widzialne i co niewidzialne, czy trony, czy panowania, czy zwierzchności, czy władze. Wszystko przez niego i dla niego zostało stworzone.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 17, 'On jest przed wszystkim i wszystko istnieje dzięki niemu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 18, 'On też jest głową ciała – kościoła; on jest początkiem i pierworodnym z umarłych, aby we wszystkim był pierwszy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 19, 'Ponieważ upodobał sobie Ojciec, aby w nim zamieszkała cała pełnia;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 20, 'I żeby przez niego pojednał wszystko ze sobą, czyniąc pokój przez krew jego krzyża; przez niego, mówię, to, co jest na ziemi, jak i to, co jest w niebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 21, 'I was, którzy kiedyś byliście obcymi i wrogami umysłem w niegodziwych uczynkach, teraz pojednał;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 22, 'W jego doczesnym ciele przez śmierć, aby was przedstawić jako świętych, nieskalanych i nienagannych przed swoim obliczem;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 23, 'Jeśli tylko trwacie w wierze, ugruntowani i utwierdzeni, niedający się odwieść od nadziei ewangelii, którą usłyszeliście, a która jest głoszona wszelkiemu stworzeniu pod niebem, której ja, Paweł, stałem się sługą;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 24, 'Teraz raduję się w swoich cierpieniach dla was i tego, czego z udręk Chrystusa brakuje w moim ciele, dopełniam dla jego ciała, którym jest kościół.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 25, 'Jego sługą stałem się zgodnie z zarządzeniem Boga, danym mi dla was, abym wypełnił słowo Boże;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 26, 'Tajemnicę, która była ukryta od wieków i pokoleń, ale teraz została objawiona jego świętym;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 27, 'Którym Bóg zechciał oznajmić, jakie jest wśród pogan bogactwo chwały tej tajemnicy, którą jest Chrystus w was, nadzieja chwały.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 28, 'Jego to głosimy, napominając każdego człowieka i nauczając każdego człowieka we wszelkiej mądrości, aby każdego człowieka przedstawić doskonałym w Chrystusie Jezusie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 29, 'Nad tym też się trudzę, walcząc według jego mocy, która potężnie działa we mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 1, 'Chcę bowiem, abyście wiedzieli, jak wielką walkę toczę o was, o tych, którzy są w Laodycei, i o tych wszystkich, którzy nie widzieli mego oblicza w ciele;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 2, 'Aby ich serca były pocieszone, będąc zespolone w miłości, a to ku wszelkiemu bogactwu zupełnej pewności zrozumienia, ku poznaniu tajemnicy Boga, Ojca i Chrystusa;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 3, 'W którym są ukryte wszystkie skarby mądrości i poznania.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 4, 'A mówię to, aby was nikt nie zwodził podstępnymi słowami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 5, 'Choć bowiem ciałem jestem nieobecny, to jednak duchem jestem z wami i raduję się, widząc wasz porządek i stałość waszej wiary w Chrystusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 6, 'Jak więc przyjęliście Pana Jezusa Chrystusa, tak w nim postępujcie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 7, 'Zakorzenieni i zbudowani na nim, i utwierdzeni w wierze, jak was nauczono, obfitując w niej z dziękczynieniem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 8, 'Uważajcie, żeby was ktoś nie obrócił na własną korzyść przez filozofię i próżne oszustwo, oparte na ludzkiej tradycji, na żywiołach świata, a nie na Chrystusie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 9, 'Gdyż w nim mieszka cieleśnie cała pełnia Bóstwa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 10, 'I jesteście dopełnieni w nim, który jest głową wszelkiej zwierzchności i władzy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 11, 'W nim też zostaliście obrzezani obrzezaniem nie ręką uczynionym, lecz obrzezaniem Chrystusa, przez zrzucenie grzesznego ciała doczesnego;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 12, 'Pogrzebani z nim w chrzcie, w którym też razem z nim zostaliście wskrzeszeni przez wiarę, która jest działaniem Boga, który go wskrzesił z martwych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 13, 'I was, gdy byliście umarłymi w grzechach i w nieobrzezaniu waszego ciała, razem z nim ożywił, przebaczając wam wszystkie grzechy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 14, 'Wymazał obciążający nas wykaz zawarty w przepisach, który był przeciwko nam, i usunął go z drogi, przybiwszy do krzyża;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 15, 'I rozbroiwszy zwierzchności i władze, jawnie wystawił je na pokaz, gdy przez niego odniósł triumf nad nimi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 16, 'Niech więc nikt was nie osądza z powodu jedzenia lub picia, co do święta, nowiu księżyca lub szabatów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 17, 'Są to cienie rzeczy przyszłych, ciało zaś jest Chrystusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 18, 'Niech nikt, kto ma upodobanie w poniżaniu siebie i kulcie aniołów, nie pozbawia was nagrody, wdając się w to, czego nie widział, i pyszniąc się bezpodstawnie cielesnym sposobem myślenia;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 19, 'A nie trzyma się głowy, z której całe ciało, odżywiane i wespół zespolone przez stawy i ścięgna, rośnie wzrostem Bożym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 20, 'Jeśli więc umarliście z Chrystusem dla żywiołów tego świata, to dlaczego – jakbyście jeszcze żyli dla świata – poddajecie się nakazom:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 21, 'Nie dotykaj, nie kosztuj, nie ruszaj;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 22, '(To wszystko niszczeje przez używanie), według przykazań i nauk ludzkich?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 23, 'Mają one pozór mądrości w religijności według własnego upodobania, w poniżaniu siebie i nieoszczędzaniu ciała, jednak nie mają żadnej wartości, służą tylko do nasycenia ciała.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 1, 'Jeśli więc razem z Chrystusem powstaliście z martwych, szukajcie tego, co w górze, gdzie Chrystus zasiada po prawicy Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 2, 'Myślcie o tym, co w górze, nie o tym, co na ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 3, 'Umarliście bowiem i wasze życie jest ukryte z Chrystusem w Bogu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 4, 'Lecz gdy się Chrystus, nasze życie, ukaże, wtedy i wy razem z nim ukażecie się w chwale.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 5, 'Umartwiajcie więc wasze członki, które są na ziemi: nierząd, nieczystość, namiętność, złe żądze i chciwość, która jest bałwochwalstwem;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 6, 'Z powodu których przychodzi gniew Boży na synów nieposłuszeństwa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 7, 'I wy niegdyś tak postępowaliście, gdy żyliście w nich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 8, 'Lecz teraz i wy odrzućcie to wszystko: gniew, zapalczywość, złośliwość, bluźnierstwo i nieprzyzwoite słowa z waszych ust.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 9, 'Nie okłamujcie się wzajemnie, skoro zrzuciliście z siebie starego człowieka z jego uczynkami;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 10, 'A przyodzialiście się w nowego, który się odnawia w poznaniu na obraz tego, który go stworzył.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 11, 'Gdzie nie ma Greka ani Żyda, obrzezanego ani nieobrzezanego, cudzoziemca ani Scyty, niewolnika ani wolnego, ale wszystkim i we wszystkich Chrystus.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 12, 'Tak więc jako wybrani Boga, święci i umiłowani, przyodziejcie się w serdeczne miłosierdzie, dobroć, pokorę, łagodność, cierpliwość;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 13, 'Znosząc jedni drugich i przebaczając sobie nawzajem, jeśli ktoś ma skargę przeciw drugiemu: jak i Chrystus przebaczył wam, tak i wy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 14, 'A nade wszystko przyodziejcie się w miłość, która jest więzią doskonałości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 15, 'A pokój Boży niech rządzi w waszych sercach, do którego też jesteście powołani w jednym ciele. Bądźcie też wdzięczni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 16, 'Słowo Chrystusa niech mieszka w was obficie ze wszelką mądrością, nauczajcie i napominajcie się wzajemnie przez psalmy, hymny i pieśni duchowe, z wdzięcznością śpiewając w waszych sercach Panu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 17, 'A wszystko, co czynicie w słowie lub w uczynku, wszystko czyńcie w imię Pana Jezusa, dziękując Bogu i Ojcu przez niego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 18, 'Żony, bądźcie poddane swym mężom, jak przystoi w Panu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 19, 'Mężowie, miłujcie wasze żony i nie bądźcie surowi wobec nich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 20, 'Dzieci, bądźcie posłuszne rodzicom we wszystkim, to bowiem podoba się Panu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 21, 'Ojcowie, nie pobudzajcie do gniewu waszych dzieci, aby nie upadały na duchu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 22, 'Słudzy, bądźcie posłuszni we wszystkim ziemskim panom, nie służąc dla oka, jak ci, którzy chcą się podobać ludziom, lecz w szczerości serca, bojąc się Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 23, 'A wszystko, co czynicie, z serca czyńcie, jak dla Pana, a nie dla ludzi;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 24, 'Wiedząc, że od Pana otrzymacie dziedzictwo jako zapłatę, gdyż służycie Panu Chrystusowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 25, 'A ten, kto wyrządza krzywdę, otrzyma zapłatę za krzywdę, a u Boga nie ma względu na osobę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 1, 'Panowie, obchodźcie się ze sługami sprawiedliwie i słusznie, wiedząc, że i wy macie Pana w niebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 2, 'Trwajcie w modlitwie, czuwając na niej z dziękczynieniem;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 3, 'Modląc się jednocześnie i za nas, aby Bóg otworzył nam drzwi słowa, żebyśmy mówili o tajemnicy Chrystusa, z powodu której też jestem więziony;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 4, 'Abym ją objawił i mówił tak, jak powinienem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 5, 'Postępujcie mądrze wobec tych, którzy są z zewnątrz, odkupując czas.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 6, 'Wasza mowa niech zawsze będzie miła, zaprawiona solą, abyście wiedzieli, jak należy każdemu odpowiedzieć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 7, 'O wszystkim, co się ze mną dzieje, opowie wam Tychik, umiłowany brat, wierny sługa i współsługa w Panu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 8, 'Posłałem go do was właśnie po to, aby się dowiedział, co się u was dzieje i pocieszył wasze serca;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 9, 'Wraz z Onezymem, wiernym i umiłowanym bratem, który pochodzi spośród was. Oni oznajmią wam wszystko, co się tutaj dzieje.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 10, 'Pozdrawia was Arystarch, mój współwięzień, i Marek, siostrzeniec Barnaby (co do którego otrzymaliście polecenie: Przyjmijcie go, jeśli do was przybędzie);');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 11, 'I Jezus, zwany Justusem, którzy są z obrzezania. Ci są moimi jedynymi współpracownikami dla królestwa Bożego, którzy stali się dla mnie pociechą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 12, 'Pozdrawia was Epafras, który pochodzi spośród was, sługa Chrystusa, zawsze o to walczący za was w modlitwach, abyście byli doskonali i zupełni we wszelkiej woli Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 13, 'Wydaję mu bowiem świadectwo, że gorliwie troszczy się o was i o tych, którzy są w Laodycei i Hierapolis.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 14, 'Pozdrawia was Łukasz, umiłowany lekarz, i Demas.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 15, 'Pozdrówcie braci w Laodycei i Nimfasa oraz kościół, który jest w jego domu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 16, 'A gdy ten list zostanie u was przeczytany, dopilnujcie, aby przeczytano go także w kościele w Laodycei, a wy abyście przeczytali ten z Laodycei.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 17, 'Powiedzcie też Archipowi: Uważaj, abyś wypełnił posługę, którą przyjąłeś w Panu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 18, 'Pozdrowienie moją, Pawła, ręką. Pamiętajcie o moich więzach. Łaska niech będzie z wami. Amen. List do Kolosan został napisany z Rzymu przez Tychika i Onezyma.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 1, 'Paweł, Sylwan i Tymoteusz do kościoła Tesaloniczan, który jest w Bogu Ojcu i Panu Jezusie Chrystusie. Łaska wam i pokój od Boga, naszego Ojca, i Pana Jezusa Chrystusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 2, 'Zawsze dziękujemy Bogu za was wszystkich, czyniąc wzmiankę o was w naszych modlitwach;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 3, 'Nieustannie wspominając wasze dzieło wiary i trud miłości, i wytrwałość w nadziei w naszym Panu Jezusie Chrystusie, przed Bogiem i naszym Ojcem;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 4, 'Wiedząc, umiłowani bracia, że zostaliście wybrani przez Boga;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 5, 'Gdyż nasza ewangelia nie doszła was tylko w słowie, ale także w mocy i w Duchu Świętym, i w pełnym przekonaniu. Wiecie bowiem, jacy byliśmy dla was, przebywając wśród was.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 6, 'A wy staliście się naśladowcami naszymi i Pana, przyjmując słowo pośród wielkiego ucisku, z radością Ducha Świętego;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 7, 'Tak że staliście się wzorem dla wszystkich wierzących w Macedonii i Achai.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 8, 'Od was bowiem słowo Pańskie rozbrzmiewało nie tylko w Macedonii i Achai, ale też wasza wiara w Boga rozkrzewiła się w każdym miejscu, tak że nie trzeba nam mówić czegokolwiek;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 9, 'Ponieważ oni sami opowiadają o nas, jakie było nasze przybycie do was i jak nawróciliście się od bożków do Boga, aby służyć żywemu i prawdziwemu Bogu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 10, 'I oczekiwać z niebios jego Syna, którego wskrzesił z martwych, Jezusa, który nas wyrwał od nadchodzącego gniewu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 1, 'Sami bowiem wiecie, bracia, że nasze przybycie do was nie było daremne;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 2, 'Lecz chociaż przedtem, jak wiecie, doznaliśmy cierpień i byliśmy znieważeni w Filippi, to jednak odważyliśmy się w naszym Bogu, by wśród wielu zmagań głosić wam ewangelię Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 3, 'Nasze pouczenie bowiem nie wzięło się z błędu ani z nieczystości, ani z podstępu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 4, 'Lecz jak przez Boga zostaliśmy uznani za godnych powierzenia nam ewangelii, tak ją głosimy, nie aby podobać się ludziom, ale Bogu, który bada nasze serca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 5, 'Nigdy bowiem nie posługiwaliśmy się pochlebstwem w mowie, jak wiecie, ani nie kierowaliśmy się ukrytą chciwością, Bóg jest świadkiem;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 6, 'Ani nie szukaliśmy chwały u ludzi, ani u was, ani u innych, mogąc być dla was ciężarem jako apostołowie Chrystusa;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 7, 'Byliśmy jednak wśród was łagodni jak karmicielka troszcząca się o swoje dzieci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 8, 'Darzyliśmy was taką życzliwością, że gotowi byliśmy użyczyć wam nie tylko ewangelii Boga, ale i naszych dusz, bo staliście się nam drodzy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 9, 'Pamiętacie przecież, bracia, naszą pracę i trud. Pracując bowiem dniem i nocą, aby nie obciążyć nikogo z was, głosiliśmy wam ewangelię Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 10, 'Wy i Bóg jesteście świadkami, że zachowywaliśmy się w świętości, w sprawiedliwości i nienagannie pośród was, którzy wierzycie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 11, 'Wiecie bowiem, że każdego z was, jak ojciec swoje dzieci, zachęcaliśmy i pocieszaliśmy, i zaklinaliśmy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 12, 'Abyście postępowali w sposób godny Boga, który was powołał do swego królestwa i chwały.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 13, 'Dlatego też nieustannie dziękujemy Bogu, że gdy przyjęliście słowo Boże, które słyszeliście od nas, przyjęliście je nie jako słowo ludzkie, ale – jak jest naprawdę – jako słowo Boże, które też w was, którzy wierzycie, skutecznie działa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 14, 'Wy bowiem, bracia, staliście się naśladowcami kościołów Bożych, które są w Judei w Chrystusie Jezusie, bo wy to samo wycierpieliście od swoich rodaków, co i oni od Żydów;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 15, 'Którzy zabili i Pana Jezusa, i swoich własnych proroków, i nas prześladowali; a nie podobają się Bogu i sprzeciwiają się wszystkim ludziom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 16, 'Zabraniają nam zwiastować poganom, żeby ci nie byli zbawieni, aby zawsze dopełniali miary swoich grzechów; nadszedł bowiem na nich ostateczny gniew.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 17, 'My zaś, bracia, rozłączeni z wami na krótko ciałem, ale nie sercem, z tym większym pragnieniem staraliśmy się was zobaczyć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 18, 'Dlatego chcieliśmy przybyć do was, zwłaszcza ja, Paweł, raz i drugi, ale przeszkodził nam szatan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 19, 'Co bowiem jest naszą nadzieją, radością albo koroną chluby? Czy nie wy nią jesteście przed naszym Panem Jezusem Chrystusem w czasie jego przyjścia?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 20, 'Wy bowiem jesteście naszą chwałą i radością.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 1, 'Dlatego nie mogąc tego dłużej znosić, postanowiliśmy sami pozostać w Atenach;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 2, 'A Tymoteusza, naszego brata, sługę Boga i współpracownika w ewangelii Chrystusa posłaliśmy, aby was utwierdził i dodał wam otuchy w wierze;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 3, 'Aby nikt się nie zachwiał wśród tych utrapień. Sami przecież wiecie, że do tego zostaliśmy wyznaczeni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 4, 'Gdy bowiem byliśmy u was, zapowiadaliśmy wam, że będziemy cierpieć ucisk, co się też stało, jak wiecie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 5, 'Dlatego i ja, nie mogąc tego dłużej znosić, posłałem go, aby rozeznał się w waszej wierze, czy was kusiciel czasem nie kusił, a nasza praca nie okazała się daremna.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 6, 'Teraz zaś Tymoteusz wrócił od was do nas i zwiastował nam radosną wieść o waszej wierze i miłości, i o tym, że nas zawsze dobrze wspominacie, pragnąc nas widzieć, podobnie jak my was.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 7, 'Dlatego dzięki wam, bracia, zostaliśmy pocieszeni przez waszą wiarę we wszelkim naszym ucisku i potrzebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 8, 'Teraz bowiem żyjemy, jeśli wy trwacie w Panu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 9, 'Jakie więc dziękczynienie możemy złożyć Bogu za was, za całą radość, jakiej z powodu was doznajemy przed naszym Bogiem;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 10, 'Gdy w nocy i we dnie bardzo gorliwie modlimy się, abyśmy mogli zobaczyć was osobiście i uzupełnić braki waszej wiary?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 11, 'A sam Bóg i nasz Ojciec i nasz Pan Jezus Chrystus niech utoruje naszą drogę do was.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 12, 'Pan zaś niech sprawi, że będziecie wzrastać i obfitować w miłość do siebie nawzajem i do wszystkich, taką, jaką i my mamy do was;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 13, 'Aby wasze serca zostały utwierdzone jako nienaganne w świętości wobec naszego Boga i Ojca na przyjście naszego Pana Jezusa Chrystusa wraz ze wszystkimi jego świętymi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 1, 'Ponadto, bracia, prosimy was i zachęcamy przez Pana Jezusa, abyście – według otrzymanego od nas pouczenia o tym, jak należy postępować i podobać się Bogu – coraz bardziej w tym obfitowali.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 2, 'Wiecie przecież, jakie nakazy daliśmy wam przez Pana Jezusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 3, 'Taka jest bowiem wola Boga, wasze uświęcenie, żebyście powstrzymywali się od nierządu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 4, 'Aby każdy z was umiał utrzymać swoje naczynie w świętości i poszanowaniu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 5, 'Nie w namiętności żądzy jak poganie, którzy nie znają Boga;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 6, 'I aby nikt nie wykorzystywał i nie oszukiwał w żadnej sprawie swego brata, bo Pan jest mścicielem tego wszystkiego, jak wam to przedtem mówiliśmy i zaświadczaliśmy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 7, 'Bóg bowiem nie powołał nas do nieczystości, ale do świętości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 8, 'A więc kto to odrzuca, odrzuca nie człowieka, lecz Boga, który nam też dał swego Ducha Świętego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 9, 'A o miłości braterskiej nie ma potrzeby wam pisać, bo sami zostaliście pouczeni przez Boga, aby się wzajemnie miłować.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 10, 'Czynicie to przecież względem wszystkich braci w całej Macedonii; ale zachęcamy was, bracia, żebyście coraz bardziej w nią obfitowali;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 11, 'I gorliwie starali się żyć spokojnie, dbać o swoje sprawy i pracować własnymi rękami, jak wam nakazaliśmy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 12, 'Abyście uczciwie postępowali wobec tych, którzy są na zewnątrz, i w niczym nie mieli niedostatku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 13, 'A nie chcę, bracia, abyście byli w niewiedzy co do tych, którzy zasnęli, abyście się nie smucili jak inni, którzy nie mają nadziei.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 14, 'Jeśli bowiem wierzymy, że Jezus umarł i zmartwychwstał, to też tych, którzy zasnęli w Jezusie, Bóg przyprowadzi wraz z nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 15, 'Bo to wam mówimy przez słowo Pana, że my, którzy pozostaniemy żywi do przyjścia Pana, nie wyprzedzimy tych, którzy zasnęli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 16, 'Gdyż sam Pan z okrzykiem, z głosem archanioła i dźwiękiem trąby Bożej zstąpi z nieba, a zmarli w Chrystusie powstaną pierwsi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 17, 'Potem my, którzy pozostaniemy żywi, razem z nimi będziemy porwani w obłoki, w powietrze, na spotkanie Pana, i tak zawsze będziemy z Panem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 18, 'Dlatego pocieszajcie się wzajemnie tymi słowami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 1, 'A o czasach i porach, bracia, nie potrzebujecie, aby wam pisano.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 2, 'Sami bowiem dokładnie wiecie, że dzień Pana przyjdzie jak złodziej w nocy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 3, 'Bo gdy będą mówić: Pokój i bezpieczeństwo – wtedy przyjdzie na nich nagła zguba, jak bóle na kobietę brzemienną, i nie ujdą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 4, 'Lecz wy, bracia, nie jesteście w ciemności, aby ten dzień zaskoczył was jak złodziej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 5, 'Wy wszyscy jesteście synami światłości i synami dnia. Nie jesteśmy synami nocy ani ciemności.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 6, 'Nie śpijmy więc jak inni, ale czuwajmy i bądźmy trzeźwi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 7, 'Ci bowiem, którzy śpią, w nocy śpią, a ci, którzy się upijają, w nocy się upijają.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 8, 'My zaś, którzy należymy do dnia, bądźmy trzeźwi, przywdziawszy pancerz wiary i miłości oraz hełm nadziei zbawienia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 9, 'Gdyż Bóg nie przeznaczył nas na gniew, lecz abyśmy otrzymali zbawienie przez naszego Pana Jezusa Chrystusa;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 10, 'Który umarł za nas, abyśmy, czy czuwamy, czy śpimy, razem z nim żyli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 11, 'Dlatego zachęcajcie jedni drugich i budujcie się wzajemnie, jak to zresztą czynicie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 12, 'I prosimy was, bracia, abyście darzyli uznaniem tych, którzy pracują wśród was, którzy są waszymi przełożonymi w Panu i was napominają;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 13, 'Ze względu na ich pracę darzcie ich jak najgorętszą miłością. Zachowujcie pokój między sobą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 14, 'Prosimy was też, bracia, napominajcie niekarnych, pocieszajcie bojaźliwych, podtrzymujcie słabych, bądźcie cierpliwi dla wszystkich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 15, 'Uważajcie, aby nikt nikomu nie odpłacał złem za zło, ale zawsze dążcie do tego, co dobre dla siebie nawzajem i dla wszystkich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 16, 'Zawsze się radujcie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 17, 'Nieustannie się módlcie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 18, 'Za wszystko dziękujcie. Taka jest bowiem wola Boga w Chrystusie Jezusie względem was.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 19, 'Ducha nie gaście.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 20, 'Proroctw nie lekceważcie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 21, 'Wszystko badajcie, a trzymajcie się tego, co dobre.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 22, 'Od wszelkiego pozoru zła powstrzymujcie się.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 23, 'A sam Bóg pokoju niech was w pełni uświęci, a cały wasz duch, dusza i ciało niech będą zachowane bez zarzutu na przyjście naszego Pana Jezusa Chrystusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 24, 'Wierny jest ten, który was powołuje; on też tego dokona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 25, 'Bracia, módlcie się za nas.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 26, 'Pozdrówcie wszystkich braci świętym pocałunkiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 27, 'Zaklinam was na Pana, aby ten list został przeczytany wszystkim świętym braciom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 28, 'Łaska naszego Pana Jezusa Chrystusa niech będzie z wami. Amen. Pierwszy list do Tesaloniczan został napisany z Aten.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 1, 'Paweł, Sylwan i Tymoteusz do kościoła Tesaloniczan, który jest w Bogu, naszym Ojcu, i Panu Jezusie Chrystusie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 2, 'Łaska wam i pokój od Boga, naszego Ojca, i Pana Jezusa Chrystusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 3, 'Bracia, powinniśmy zawsze dziękować Bogu za was, co jest rzeczą słuszną, bo bardzo wzrasta wasza wiara i u każdego z was pomnaża się wzajemna miłość;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 4, 'Tak że i my sami chlubimy się wami w kościołach Bożych z powodu waszej cierpliwości i wiary we wszystkich waszych prześladowaniach i uciskach, które znosicie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 5, 'Są one dowodem sprawiedliwego sądu Boga, abyście byli uznani za godnych królestwa Bożego, za które też cierpicie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 6, 'Ponieważ jest rzeczą sprawiedliwą u Boga, żeby odpłacić uciskiem tym, którzy was uciskają;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 7, 'A wam, uciśnionym, dać odpoczynek wraz z nami, gdy z nieba objawi się Pan Jezus z aniołami swojej mocy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 8, 'W ogniu płomienistym wywierając zemstę na tych, którzy Boga nie znają i nie są posłuszni ewangelii naszego Pana Jezusa Chrystusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 9, 'Poniosą oni karę, wieczne zatracenie od oblicza Pana i od chwały jego mocy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 10, 'Gdy przyjdzie, aby był uwielbiony w swoich świętych i podziwiany w tym dniu przez wszystkich wierzących, ponieważ wśród was uwierzono naszemu świadectwu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 11, 'Dlatego też nieustannie modlimy się za was, aby nasz Bóg uznał was za godnych tego powołania i wypełnił wszelkie upodobanie swojej dobroci i dzieła wiary w mocy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 12, 'Aby imię naszego Pana Jezusa Chrystusa zostało uwielbione w was, a wy w nim, według łaski naszego Boga i Pana Jezusa Chrystusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 1, 'Prosimy was, bracia, przez wzgląd na przyjście naszego Pana Jezusa Chrystusa i nasze zgromadzenie się przy nim;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 2, 'Abyście nie tak łatwo dali się zachwiać w waszym umyśle i zatrwożyć się ani przez ducha, ani przez mowę, ani przez list rzekomo przez nas pisany, jakoby już nadchodził dzień Chrystusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 3, 'Niech was nikt w żaden sposób nie zwodzi. Ten dzień bowiem nie nadejdzie, dopóki najpierw nie przyjdzie odstępstwo i nie objawi się człowiek grzechu, syn zatracenia;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 4, 'Który się sprzeciwia i wynosi ponad wszystko, co się nazywa Bogiem lub co jest przedmiotem czci, tak że zasiądzie w świątyni Boga jako Bóg, podając się za Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 5, 'Czy nie pamiętacie, że jeszcze będąc u was, mówiłem o tym?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 6, 'A teraz wiecie, co przeszkadza, tak że się objawi w swoim czasie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 7, 'Tajemnica nieprawości bowiem już działa. Tylko że ten, który teraz przeszkadza, będzie przeszkadzał, aż zostanie usunięty z drogi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 8, 'Wówczas pojawi się ów niegodziwiec, którego Pan zabije duchem swoich ust i zniszczy blaskiem swego przyjścia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 9, 'Niegodziwiec przyjdzie za sprawą szatana, z całą mocą, wśród znaków i fałszywych cudów;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 10, 'Wśród wszelkiego zwodzenia nieprawości wobec tych, którzy giną, ponieważ nie przyjęli miłości prawdy, by zostali zbawieni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 11, 'Dlatego Bóg zsyła im silne omamienie, tak że uwierzą kłamstwu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 12, 'Aby zostali osądzeni wszyscy, którzy nie uwierzyli prawdzie, ale upodobali sobie niesprawiedliwość.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 13, 'Lecz my nieustannie powinniśmy dziękować Bogu za was, bracia umiłowani przez Pana, że Bóg od początku wybrał was do zbawienia przez uświęcenie Ducha i wiarę w prawdę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 14, 'Do tego powołał was przez naszą ewangelię, abyście dostąpili chwały naszego Pana Jezusa Chrystusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 15, 'Dlatego, bracia, stójcie niewzruszenie i trzymajcie się przekazanych nauk, o których zostaliście pouczeni czy to przez mowę, czy przez nasz list.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 16, 'A sam nasz Pan Jezus Chrystus i Bóg, nasz Ojciec, który nas umiłował i dał wieczną pociechę i dobrą nadzieję przez łaskę;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 17, 'Niech pocieszy wasze serca i utwierdzi was w każdym dobrym słowie i uczynku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 1, 'Na koniec, bracia, módlcie się za nas, aby słowo Pana szerzyło się i rozsławiało jak i u was;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 2, 'I abyśmy byli wybawieni od przewrotnych i złych ludzi; nie wszyscy bowiem mają wiarę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 3, 'Lecz wierny jest Pan, który was utwierdzi i będzie strzec od złego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 4, 'Co do was, mamy ufność w Panu, że to, co nakazujemy, czynicie i będziecie czynić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 5, 'Pan zaś niech skieruje wasze serca ku miłości Bożej i ku cierpliwemu oczekiwaniu Chrystusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 6, 'A nakazujemy wam, bracia, w imię naszego Pana Jezusa Chrystusa, abyście stronili od każdego brata, który postępuje nieporządnie, a nie według przekazanych nauk, które otrzymał od nas.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 7, 'Sami bowiem wiecie, jak należy nas naśladować, ponieważ nie żyliśmy wśród was nieporządnie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 8, 'Ani u nikogo nie jedliśmy chleba za darmo, ale pracowaliśmy w trudzie i zmęczeniu we dnie i w nocy, aby dla nikogo z was nie być ciężarem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 9, 'Nie jakobyśmy nie mieli do tego prawa, lecz żeby dać wam samych siebie za przykład do naśladowania.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 10, 'Gdy bowiem byliśmy u was, to nakazaliśmy wam: Kto nie chce pracować, niech też nie je.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 11, 'Bo słyszymy, że niektórzy wśród was postępują nieporządnie, wcale nie pracują, lecz zajmują się niepotrzebnymi rzeczami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 12, 'Dlatego nakazujemy im i napominamy przez naszego Pana Jezusa Chrystusa, aby spokojnie pracując, własny chleb jedli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 13, 'Wy zaś, bracia, nie bądźcie znużeni w czynieniu dobra.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 14, 'Jeśli ktoś nie posłucha naszych słów zawartych w tym liście, to zwróćcie na niego uwagę i nie przestawajcie z nim, aby się zawstydził.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 15, 'Nie uważajcie go jednak za nieprzyjaciela, lecz napominajcie jak brata.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 16, 'A sam Pan pokoju niech was obdarza pokojem zawsze i na wszelki sposób. Pan niech będzie z wami wszystkimi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 17, 'Pozdrowienie moją, Pawła, ręką; jest ono znakiem w każdym liście; tak piszę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 18, 'Łaska naszego Pana Jezusa Chrystusa niech będzie z wami wszystkimi. Amen. Drugi list do Tesaloniczan został napisany z Aten.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 1, 'Paweł, apostoł Jezusa Chrystusa według nakazu Boga, naszego Zbawiciela, i Pana Jezusa Chrystusa, który jest naszą nadzieją;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 2, 'Do Tymoteusza, mego własnego syna w wierze. Łaska, miłosierdzie i pokój od Boga, naszego Ojca, i Chrystusa Jezusa, naszego Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 3, 'Jak cię prosiłem, gdy wybierałem się do Macedonii, byś pozostał w Efezie, tak teraz proszę, abyś nakazał niektórym, żeby inaczej nie nauczali;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 4, 'I nie zajmowali się baśniami i niekończącymi się rodowodami, które wywołują raczej spory niż zbudowanie Boże, które oparte jest na wierze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 5, 'Końcem zaś przykazania jest miłość płynąca z czystego serca, z prawego sumienia i wiary nieobłudnej;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 6, 'Od czego niektórzy odstąpili i zwrócili się ku czczej gadaninie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 7, 'Chcąc być nauczycielami prawa, nie rozumiejąc ani tego, co mówią, ani tego, co stanowczo twierdzą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 8, 'Wiemy zaś, że prawo jest dobre, jeśli ktoś je właściwie stosuje.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 9, 'Rozumiemy, że prawo nie jest ustanowione dla sprawiedliwego, ale dla nieprawych i nieposłusznych, dla bezbożnych i grzeszników, dla niegodziwych i nieczystych, dla ojcobójców, matkobójców i morderców;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 10, 'Dla rozpustników, mężczyzn współżyjących ze sobą, handlarzy ludźmi, dla kłamców, krzywoprzysięzców i dla wszystkiego, co jest przeciwne zdrowej nauce;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 11, 'Zgodnie z chwalebną ewangelią błogosławionego Boga, którą mi powierzono.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 12, 'Dziękuję więc temu, który mnie umocnił, Chrystusowi Jezusowi, naszemu Panu, że uznał mnie za wiernego, przeznaczając mnie do posługi;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 13, 'Mnie, który przedtem byłem bluźniercą, prześladowcą i gnębicielem, ale dostąpiłem miłosierdzia, bo czyniłem to nieświadomie, w niewierze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 14, 'A łaska naszego Pana stała się bardzo obfita wraz z wiarą i miłością, która jest w Chrystusie Jezusie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 15, 'Wiarygodne to słowa i godne całkowitego przyjęcia, że Chrystus Jezus przyszedł na świat, aby zbawić grzeszników, z których ja jestem pierwszy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 16, 'Lecz dostąpiłem miłosierdzia po to, aby we mnie pierwszym Jezus Chrystus okazał wszelką cierpliwość jako przykład dla tych, którzy mają w niego uwierzyć ku życiu wiecznemu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 17, 'A Królowi wieków, nieśmiertelnemu, niewidzialnemu, jedynemu mądremu Bogu niech będzie cześć i chwała na wieki wieków. Amen.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 18, 'Ten nakaz daję tobie, synu Tymoteuszu, według wcześniej wygłoszonych o tobie proroctw, abyś toczył zgodnie z nimi dobry bój;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 19, 'Mając wiarę i czyste sumienie, które niektórzy odrzucili i stali się rozbitkami w wierze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 20, 'Do nich należą Hymenajos i Aleksander, których oddałem szatanowi, aby nauczyli się nie bluźnić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 1, 'Zachęcam więc przede wszystkim, aby zanoszone były prośby, modlitwy, wstawiennictwa i dziękczynienia za wszystkich ludzi;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 2, 'Za królów i za wszystkich sprawujących władzę, abyśmy mogli prowadzić życie ciche i spokojne, z całą pobożnością i uczciwością.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 3, 'Jest to bowiem rzecz dobra i miła w oczach Boga, naszego Zbawiciela;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 4, 'Który chce, aby wszyscy ludzie zostali zbawieni i doszli do poznania prawdy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 5, 'Jeden bowiem jest Bóg, jeden też pośrednik między Bogiem a ludźmi, człowiek Chrystus Jezus;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 6, 'Który wydał samego siebie na okup za wszystkich, na świadectwo we właściwym czasie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 7, 'Ze względu na nie zostałem ustanowiony kaznodzieją i apostołem – mówię prawdę w Chrystusie, nie kłamię – nauczycielem pogan w wierze i prawdzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 8, 'Chcę więc, aby mężczyźni modlili się na każdym miejscu, podnosząc ręce czyste, bez gniewu i sporu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 9, 'Podobnie też kobiety niech się zdobią ubiorem przyzwoitym, ze wstydliwością i umiarem, nie z zaplatanymi włosami albo złotem, albo perłami, albo kosztownymi strojami;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 10, 'Lecz dobrymi uczynkami, jak przystoi kobietom, które uznają się za pobożne.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 11, 'Kobieta niech się uczy w cichości, w pełnej uległości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 12, 'Nie pozwalam zaś kobiecie nauczać ani mieć władzy nad mężczyzną, lecz aby trwała w cichości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 13, 'Bo Adam został stworzony najpierw, potem Ewa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 14, 'I nie Adam został zwiedziony, lecz kobieta, gdy została zwiedziona, popadła w przestępstwo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 15, 'Lecz będzie zbawiona przez rodzenie dzieci, jeśli zostaną w wierze, miłości i świętości z umiarem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 1, 'Wiarygodne to słowa: Jeśli ktoś pragnie biskupstwa, pragnie dobrej pracy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 2, 'Biskup więc ma być nienaganny, mąż jednej żony, czujny, trzeźwy, przyzwoity, gościnny, zdolny do nauczania;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 3, 'Nieoddający się piciu wina, nieskłonny do bicia, niełakomy na brudny zysk, ale opanowany, niekłótliwy, niechciwy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 4, 'Dobrze rządzący własnym domem, trzymający dzieci w posłuszeństwie i wszelkim szacunku;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 5, 'Jeśli bowiem ktoś nie umie rządzić własnym domem, jakże będzie mógł troszczyć się o kościół Boży?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 6, 'Nie nowicjusz, żeby nie wbił się w pychę i nie wpadł w potępienie diabelskie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 7, 'Musi też mieć dobre świadectwo od tych, którzy są na zewnątrz, żeby nie ściągał na siebie hańby i nie wpadł w sidła diabła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 8, 'Diakoni także mają być poważni, niedwulicowi, nienadużywający wina, niełakomi na brudny zysk;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 9, 'Zachowujący tajemnicę wiary w czystym sumieniu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 10, 'I niech będą najpierw wypróbowani, a potem niech służą, jeśli są nienaganni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 11, 'Ich żony także niech będą poważne, nierzucające oszczerstw, trzeźwe, wierne we wszystkim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 12, 'Diakoni niech będą mężami jednej żony, rządzący dobrze dziećmi i własnymi domami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 13, 'Ci bowiem, którzy dobrze pełnią służbę, zyskują sobie zaszczytny stopień i wielką śmiałość w wierze, która jest w Chrystusie Jezusie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 14, 'Piszę ci to, mając nadzieję, że wkrótce przybędę do ciebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 15, 'A gdybym się opóźniał, piszę, abyś wiedział, jak należy postępować w domu Bożym, który jest kościołem Boga żywego, filarem i podporą prawdy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 16, 'A bez wątpienia wielka jest tajemnica pobożności: Bóg objawiony został w ciele, usprawiedliwiony w Duchu, widziany był przez anioły, głoszony był poganom, uwierzono mu na świecie, wzięty został w górę do chwały.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 1, 'A Duch otwarcie mówi, że w czasach ostatecznych niektórzy odstąpią od wiary, dając posłuch zwodniczym duchom i naukom demonów;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 2, 'Mówiąc kłamstwo w obłudzie, mając napiętnowane sumienie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 3, 'Zabraniając wstępować w związki małżeńskie, nakazując powstrzymywać się od pokarmów, które Bóg stworzył, aby je przyjmowali z dziękczynieniem wierzący i ci, którzy poznali prawdę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 4, 'Wszelkie bowiem stworzenie Boże jest dobre i nie należy odrzucać niczego, co się przyjmuje z dziękczynieniem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 5, 'Uświęcone bowiem zostaje przez słowo Boże i modlitwę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 6, 'Przedkładając to braciom, będziesz dobrym sługą Chrystusa Jezusa, wykarmionym słowami wiary i dobrej nauki, za którą poszedłeś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 7, 'Odrzucaj natomiast pospolite i babskie baśnie. Sam zaś ćwicz się w pobożności.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 8, 'Ćwiczenie cielesne bowiem przynosi niewiele pożytku, lecz pobożność do wszystkiego jest przydatna, gdyż zawiera obietnicę życia obecnego i przyszłego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 9, 'Wiarygodne to słowa i godne całkowitego przyjęcia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 10, 'Dlatego pracujemy i jesteśmy lżeni, że pokładamy nadzieję w Bogu żywym, który jest Zbawicielem wszystkich ludzi, zwłaszcza wierzących.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 11, 'To nakazuj i tego nauczaj.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 12, 'Niech nikt nie lekceważy twego młodego wieku; lecz bądź dla wierzących przykładem w mowie, w postępowaniu, w miłości, w duchu, w wierze, w czystości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 13, 'Dopóki nie przyjdę, pilnuj czytania, zachęcania i nauki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 14, 'Nie zaniedbuj daru, który jest w tobie, który został ci dany przez proroctwo wraz z nałożeniem rąk starszych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 15, 'O tym rozmyślaj, temu się oddawaj, aby twoje postępy były widoczne dla wszystkich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 16, 'Pilnuj samego siebie i nauki, trwaj w tych rzeczach, bo to czyniąc, i samego siebie zbawisz, i tych, którzy cię słuchają.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 1, 'Starszego człowieka nie strofuj, lecz nakłaniaj jak ojca, młodszych – jak braci;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 2, 'Starsze kobiety – jak matki, młodsze – jak siostry, z całą czystością.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 3, 'Okazuj szacunek wdowom, które rzeczywiście są wdowami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 4, 'Jeśli zaś jakaś wdowa ma dzieci lub wnuki, niech się one najpierw uczą być pobożnymi względem własnego domu i odwzajemniać się rodzicom; jest to bowiem rzecz dobra i miła w oczach Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 5, 'Ta zaś, która rzeczywiście jest wdową i jest osamotniona, pokłada nadzieję w Bogu i trwa w prośbach i modlitwach we dnie i w nocy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 6, 'Lecz ta, która oddaje się rozkoszom, jest martwa, chociaż żyje.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 7, 'To więc nakazuj, żeby były nienaganne.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 8, 'A jeśli ktoś nie dba o swoich, a zwłaszcza o domowników, ten wyparł się wiary i gorszy jest od niewierzącego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 9, 'Do wdów niech będzie zaliczona taka, która nie ma mniej niż sześćdziesiąt lat, była żoną jednego męża;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 10, 'Znana z dobrych uczynków, jeśli wychowała dzieci, jeśli udzielała gościny, jeśli obmywała nogi świętym, jeśli wspomagała strapionych, jeśli wykonywała każdy dobry uczynek.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 11, 'Natomiast młodszych wdów do nich nie zaliczaj, bo gdy rozkosze odwodzą je od Chrystusa, chcą wyjść za mąż;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 12, 'Ściągając na siebie potępienie, ponieważ odrzuciły pierwszą wiarę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 13, 'Co więcej, uczą się bezczynności, chodząc od domu do domu, i nie tylko są bezczynne, lecz też gadatliwe, wścibskie, mówiące to, co nie wypada.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 14, 'Chcę więc, żeby młodsze wychodziły za mąż, rodziły dzieci, zajmowały się domem, nie dawały przeciwnikowi żadnego powodu do obmowy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 15, 'Już bowiem niektóre odwróciły się i poszły za szatanem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 16, 'A jeśli jakiś wierzący lub wierząca ma w rodzinie wdowy, niech im pomaga, aby kościół nie był obciążony i mógł przyjść z pomocą tym, które rzeczywiście są wdowami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 17, 'Starsi, którzy dobrze przewodzą, niech będą uważani za godnych podwójnej czci, a zwłaszcza ci, którzy pracują w słowie i w nauce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 18, 'Mówi bowiem Pismo: Młócącemu wołowi nie zawiążesz pyska, oraz: Godny jest robotnik swojej zapłaty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 19, 'Nie przyjmuj oskarżenia przeciwko starszemu, chyba że na podstawie zeznania dwóch albo trzech świadków.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 20, 'A tych, którzy grzeszą, strofuj w obecności wszystkich, aby i inni się bali.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 21, 'Zaklinam cię wobec Boga i Pana Jezusa Chrystusa, i wybranych aniołów, abyś tego przestrzegał, nie mając względu na osoby, nie kierując się stronniczością.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 22, 'Rąk na nikogo pospiesznie nie wkładaj ani nie bądź uczestnikiem cudzych grzechów. Siebie samego zachowaj czystym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 23, 'Samej wody już nie pij, ale używaj trochę wina ze względu na twój żołądek i częste niedomagania.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 24, 'Grzechy niektórych ludzi są jawne, jeszcze zanim zostaną osądzone, a za niektórymi idą w ślad.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 25, 'Podobnie dobre uczynki są jawne, a te, które nie są, pozostać w ukryciu nie mogą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 1, 'Wszyscy słudzy, którzy są pod jarzmem, niech uważają swych panów za godnych wszelkiej czci, aby nie bluźniono imieniu Boga i nauce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 2, 'A ci, którzy mają panów wierzących, niech ich nie lekceważą dlatego, że są braćmi, ale tym bardziej niech im służą, bo są wiernymi i umiłowanymi, uczestnikami dobrodziejstwa. Tego nauczaj i do tego zachęcaj.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 3, 'Jeśli ktoś inaczej naucza i nie trzyma się zdrowych słów naszego Pana Jezusa Chrystusa i nauki zgodnej z pobożnością;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 4, 'Ten jest nadęty i nic nie wie, lecz ma chorobliwą skłonność do dociekań i sporów o słowa, z których rodzą się zawiść, spory, złorzeczenia, złośliwe podejrzenia;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 5, 'Przewrotne spory ludzi o wypaczonym umyśle, pozbawionych prawdy, którzy uważają, że pobożność jest zyskiem cielesnym. Strońcie od takich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 6, 'Wielkim zaś zyskiem jest pobożność wraz z poprzestawaniem na tym, co się ma.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 7, 'Niczego bowiem nie przynieśliśmy na ten świat, z pewnością też niczego wynieść nie możemy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 8, 'Mając natomiast jedzenie i ubranie, poprzestawajmy na tym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 9, 'A ci, którzy chcą być bogaci, wpadają w pokusy i w sidła oraz w wiele głupich i szkodliwych pożądliwości, które pogrążają ludzi w zgubie i zatraceniu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 10, 'Korzeniem bowiem wszelkiego zła jest miłość do pieniędzy; niektórzy, pragnąc ich, zboczyli z drogi wiary i poprzebijali się wieloma boleściami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 11, 'Ty zaś, człowieku Boży, uciekaj od tego wszystkiego, a podążaj za sprawiedliwością, pobożnością, wiarą, miłością, cierpliwością, łagodnością.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 12, 'Staczaj dobrą walkę wiary, uchwyć się życia wiecznego, do którego też zostałeś powołany i o którym złożyłeś dobre wyznanie wobec wielu świadków.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 13, 'Nakazuję ci przed Bogiem, który ożywia wszystko, i przed Chrystusem Jezusem, który złożył dobre wyznanie przed Poncjuszem Piłatem;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 14, 'Abyś zachował to przykazanie bez skazy i bez zarzutu aż do objawienia się naszego Pana Jezusa Chrystusa;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 15, 'Które we właściwym czasie ukaże błogosławiony i jedyny Władca, Król królów i Pan panów;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 16, 'Jedyny mający nieśmiertelność i mieszkający w światłości niedostępnej, którego żaden z ludzi nie widział ani widzieć nie może; jemu niech będzie cześć i moc wieczna. Amen.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 17, 'Bogaczom tego świata nakazuj, aby się nie wynosili i nie pokładali nadziei w niepewnym bogactwie, lecz w Bogu żywym, który nam wszystkiego obficie udziela, abyśmy z tego korzystali.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 18, 'Niech innym dobrze czynią, bogacą się w dobre uczynki, chętnie dają i dzielą się z innymi;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 19, 'Gromadząc sobie skarby jako dobry fundament na przyszłość, aby uchwycić się życia wiecznego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 20, 'Tymoteuszu, strzeż tego, co ci powierzono, unikaj pospolitej, czczej gadaniny i sprzecznych twierdzeń rzekomej wiedzy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 21, 'Którą się niektórzy szczycąc, pobłądzili w wierze. Łaska niech będzie z tobą. Amen. Pierwszy list do Tymoteusza został napisany z Laodycei, która jest głównym miastem Frygii Pakacyjańskiej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 1, 'Paweł, apostoł Jezusa Chrystusa z woli Boga, zgodnie z obietnicą życia, które jest w Chrystusie Jezusie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 2, 'Do Tymoteusza, umiłowanego syna. Łaska, miłosierdzie i pokój od Boga Ojca i Chrystusa Jezusa, naszego Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 3, 'Dziękuję Bogu, któremu jak moi przodkowie służę z czystym sumieniem, że nieustannie ciebie wspominam w swoich modlitwach, w nocy i we dnie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 4, 'Wspominając twoje łzy, pragnę cię zobaczyć, aby napełnić się radością;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 5, 'Pamiętając nieobłudną wiarę, która jest w tobie, a która najpierw mieszkała w twojej babce Lois i w twojej matce Eunice, jestem też pewien, że i w tobie mieszka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 6, 'Z tego powodu przypominam ci, abyś rozniecił dar Boży, który jest w tobie przez nałożenie moich rąk.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 7, 'Nie dał nam bowiem Bóg ducha bojaźni, lecz mocy i miłości, i zdrowego umysłu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 8, 'Nie wstydź się więc świadectwa naszego Pana ani mnie, jego więźnia, lecz weź udział w cierpieniach dla ewangelii według mocy Boga;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 9, 'Który nas zbawił i powołał świętym powołaniem nie na podstawie naszych uczynków, ale na podstawie swojego postanowienia i łaski, która została nam dana w Chrystusie Jezusie przed wiecznymi czasy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 10, 'A obecnie została objawiona przez pojawienie się naszego Zbawiciela, Jezusa Chrystusa, który zniszczył śmierć, a życie i nieśmiertelność wydobył na jaw przez ewangelię;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 11, 'Dla której zostałem ustanowiony kaznodzieją, apostołem i nauczycielem pogan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 12, 'Z tego też powodu znoszę te cierpienia, ale się nie wstydzę, gdyż wiem, komu uwierzyłem, i jestem pewien, że on ma moc zachować to, co jemu powierzyłem, aż do owego dnia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 13, 'Trzymaj się wzoru zdrowych słów, które ode mnie usłyszałeś, w wierze i miłości, która jest w Chrystusie Jezusie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 14, 'Strzeż tego dobrego, które powierzył ci Duch Święty, który w nas mieszka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 15, 'Wiesz o tym, że odwrócili się ode mnie wszyscy, którzy są w Azji, do których należą Figelos i Hermogenes.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 16, 'Niech Pan okaże swoje miłosierdzie domowi Onezyfora, bo mnie często pokrzepiał i mojego łańcucha się nie wstydził;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 17, 'Lecz gdy był w Rzymie, usilnie mnie szukał i odnalazł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 18, 'Niech mu Pan da, aby w owym dniu znalazł miłosierdzie u Pana. A jak wiele usług oddał mi w Efezie, ty sam dobrze wiesz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 1, 'Ty więc, mój synu, wzmacniaj się w łasce, która jest w Chrystusie Jezusie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 2, 'A co słyszałeś ode mnie wobec wielu świadków, to powierz wiernym ludziom, którzy będą zdolni nauczać także innych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 3, 'Dlatego znoś trudy jak dobry żołnierz Jezusa Chrystusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 4, 'Nikt, kto pełni służbę żołnierską, nie wikła się w sprawy tego życia, aby podobać się temu, który go powołał na żołnierza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 5, 'Również jeśli ktoś staje do zapasów, nie otrzymuje korony, jeżeli nie walczy prawidłowo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 6, 'Rolnik, który pracuje, jako pierwszy powinien korzystać z plonów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 7, 'Rozważ, co mówię, a niech Pan ci da zrozumienie we wszystkim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 8, 'Pamiętaj, że Jezus Chrystus, potomek Dawida, powstał z martwych według mojej ewangelii;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 9, 'Dla której znoszę cierpienia jak złoczyńca, aż do więzów, ale słowo Boże nie jest związane.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 10, 'Dlatego wszystko znoszę przez wzgląd na wybranych, aby i oni dostąpili zbawienia, które jest w Chrystusie Jezusie wraz z wieczną chwałą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 11, 'Wiarygodne to słowa. Jeśli bowiem z nim umarliśmy, z nim też będziemy żyć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 12, 'Jeśli cierpimy, z nim też będziemy królować, jeśli się go wyprzemy, i on się nas wyprze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 13, 'Jeśli jesteśmy niewierni, on pozostaje wierny, bo samego siebie wyprzeć się nie może.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 14, 'To wszystko przypominaj, zaklinając ich przed Panem, aby się nie wdawali w spory o słowa, bo to niczemu nie służy, tylko prowadzi do zguby słuchaczy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 15, 'Staraj się, abyś stanął przed Bogiem jako wypróbowany pracownik, który nie ma się czego wstydzić i który dobrze rozkłada słowo prawdy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 16, 'Unikaj zaś pospolitej, czczej gadaniny, bo prowadzi ona do coraz większej bezbożności.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 17, 'A ich mowa szerzy się jak gangrena. Do nich należą Hymenajos i Filetos;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 18, 'Którzy pobłądzili w sprawie prawdy, mówiąc, że zmartwychwstanie już nastąpiło, i wywracają wiarę niektórych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 19, 'Mimo to fundament Boży stoi niewzruszony, mając taką pieczęć: Zna Pan tych, którzy należą do niego, oraz: Niech odstąpi od nieprawości każdy, kto wzywa imienia Chrystusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 20, 'W wielkim zaś domu znajdują się nie tylko naczynia złote i srebrne, lecz także drewniane i gliniane, niektóre do użytku zaszczytnego, a inne do niezaszczytnego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 21, 'Jeśli więc ktoś oczyści samego siebie z tego wszystkiego, będzie naczyniem do użytku zaszczytnego, uświęconym i użytecznym dla Pana, przygotowanym do każdego dobrego czynu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 22, 'Uciekaj też od młodzieńczych pożądliwości, a zabiegaj o sprawiedliwość, wiarę, miłość, pokój wraz z tymi, którzy wzywają Pana z czystego serca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 23, 'Unikaj zaś głupich i niedouczonych rozmów, wiedząc, że rodzą kłótnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 24, 'A sługa Pana nie powinien wdawać się w kłótnie, lecz ma być uprzejmy względem wszystkich, zdolny do nauczania, cierpliwie znoszący złych;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 25, 'Łagodnie nauczający tych, którzy się sprzeciwiają; może kiedyś Bóg da im pokutę, aby uznali prawdę;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 26, 'Oprzytomnieli i wyrwali się z sideł diabła, przez którego zostali schwytani do pełnienia jego woli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 1, 'A to wiedz, że w ostatecznych dniach nastaną trudne czasy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 2, 'Ludzie bowiem będą samolubni, chciwi, chełpliwi, pyszni, bluźniący, nieposłuszni rodzicom, niewdzięczni, bezbożni;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 3, 'Bez naturalnej miłości, niedotrzymujący słowa, oszczercy, niepowściągliwi, okrutni, niemiłujący dobrych;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 4, 'Zdrajcy, porywczy, nadęci, miłujący bardziej rozkosze niż Boga;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 5, 'Przybierający pozór pobożności, ale wyrzekający się jej mocy. Takich ludzi unikaj.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 6, 'Z takich bowiem są ci, którzy wkradają się do domów i usidlają naiwne kobietki obciążone grzechami, wiedzione przez rozmaite pożądliwości;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 7, 'Które zawsze się uczą, a nigdy nie mogą dojść do poznania prawdy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 8, 'Jak Jannes i Jambres sprzeciwiali się Mojżeszowi, tak też oni sprzeciwiają się prawdzie, ludzie o wypaczonym umyśle, odrzuceni jeśli chodzi o wiarę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 9, 'Lecz daleko nie zajdą, bo ich głupota będzie jawna dla wszystkich, jak to się stało i z tamtymi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 10, 'Ale ty pojąłeś moją naukę, sposób życia, dążenia, wiarę, wytrwałość, miłość i cierpliwość;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 11, 'Prześladowania, cierpienia, które mnie spotkały w Antiochii, w Ikonium i Listrze – prześladowania, które zniosłem, a ze wszystkich wyrwał mnie Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 12, 'Tak i wszyscy, którzy chcą żyć pobożnie w Chrystusie Jezusie, będą prześladowani.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 13, 'Lecz ludzie źli i zwodziciele coraz bardziej będą brnąć w zło, błądząc i innych wprowadzając w błąd.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 14, 'Ty zaś trwaj w tym, czego się nauczyłeś i co ci powierzono, wiedząc, od kogo się tego nauczyłeś;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 15, 'I ponieważ od dziecka znasz Pisma święte, które cię mogą uczynić mądrym ku zbawieniu przez wiarę, która jest w Chrystusie Jezusie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 16, 'Całe Pismo jest natchnione przez Boga i pożyteczne do nauki, do strofowania, do poprawiania, do wychowywania w sprawiedliwości;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 17, 'Aby człowiek Boży był doskonały, do wszelkiego dobrego dzieła w pełni przygotowany.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 1, 'Zaklinam cię więc przed Bogiem i Panem Jezusem Chrystusem, który będzie sądził żywych i umarłych w czasie swego przyjścia i swego królestwa;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 2, 'Głoś słowo Boże, nalegaj w porę i nie w porę, upominaj, strofuj i zachęcaj ze wszelką cierpliwością i nauką.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 3, 'Przyjdzie bowiem czas, gdy zdrowej nauki nie zniosą, ale zgromadzą sobie nauczycieli według swoich pożądliwości, ponieważ ich uszy świerzbią.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 4, 'I odwrócą uszy od prawdy, a zwrócą się ku baśniom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 5, 'Lecz ty bądź czujny we wszystkim, znoś cierpienia, wykonuj dzieło ewangelisty, w pełni dowódź swojej służby.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 6, 'Ja bowiem już mam być złożony w ofierze, a czas mojego odejścia nadchodzi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 7, 'Dobrą walkę stoczyłem, bieg ukończyłem, wiarę zachowałem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 8, 'Odtąd odłożona jest dla mnie korona sprawiedliwości, którą mi w owym dniu da Pan, sędzia sprawiedliwy, a nie tylko mnie, ale i wszystkim, którzy umiłowali jego przyjście.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 9, 'Postaraj się przybyć do mnie szybko.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 10, 'Demas bowiem mnie opuścił, umiłowawszy ten świat, i udał się do Tesaloniki, Krescens do Galacji, Tytus do Dalmacji;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 11, 'Tylko Łukasz jest ze mną. Weź Marka i przyprowadź ze sobą, bo jest mi bardzo przydatny do służby.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 12, 'Tychika zaś posłałem do Efezu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 13, 'Płaszcz, który zostawiłem w Troadzie u Karposa, przynieś ze sobą, gdy przyjdziesz, a także księgi, zwłaszcza pergaminy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 14, 'Aleksander, ludwisarz, wyrządził mi wiele zła; niech mu Pan odda według jego uczynków.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 15, 'I ty się go strzeż, bo bardzo sprzeciwiał się naszym słowom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 16, 'Podczas pierwszej mojej obrony nikt przy mnie nie stanął, lecz wszyscy mnie opuścili. Niech im to nie będzie policzone.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 17, 'Lecz Pan stanął przy mnie i umocnił mnie, aby głoszenie było przeze mnie całkowicie utwierdzone, aby usłyszeli je wszyscy poganie; i zostałem wyrwany z paszczy lwa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 18, 'Wyrwie mnie też Pan ze wszelkiego złego uczynku i zachowa dla swojego królestwa niebieskiego. Jemu chwała na wieki wieków. Amen.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 19, 'Pozdrów Pryskę i Akwilę oraz dom Onezyfora.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 20, 'Erast pozostał w Koryncie, a Trofima zostawiłem chorego w Milecie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 21, 'Postaraj się przybyć przed zimą. Pozdrawia cię Eubulos, Pudens, Linus, Klaudia i wszyscy bracia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 22, 'Pan Jezus Chrystus niech będzie z twoim duchem. Łaska niech będzie z wami. Amen. Drugi list został napisany z Rzymu do Tymoteusza (który był ustanowiony pierwszym biskupem w Efezie), gdy Paweł był postawiony przed cesarza Nerona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 1, 'Paweł, sługa Boga i apostoł Jezusa Chrystusa według wiary wybranych Bożych i poznania prawdy, która jest zgodna z pobożnością;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 2, 'W nadziei życia wiecznego, które obiecał przed dawnymi wiekami ten, który nie kłamie, Bóg;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 3, 'I we właściwym czasie objawił swoje słowo przez głoszenie, które zostało mi powierzone zgodnie z nakazem Boga, naszego Zbawiciela;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 4, 'Do Tytusa, mego własnego syna we wspólnej wierze. Łaska, miłosierdzie i pokój od Boga Ojca i Pana Jezusa Chrystusa, naszego Zbawiciela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 5, 'Zostawiłem cię na Krecie w tym celu, abyś uporządkował to, co tam jeszcze zostało do zrobienia, i ustanowił w każdym mieście starszych, jak ci nakazałem;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 6, 'Jeśli ktoś jest nienaganny, mąż jednej żony, mający dzieci wierne, nieobwiniane o hulaszcze życie lub niekarność.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 7, 'Biskup bowiem, jako szafarz Boży, ma być nienaganny, niesamowolny, nieskory do gniewu, nieoddający się piciu wina, nieskłonny do bicia, niegoniący za brudnym zyskiem;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 8, 'Lecz gościnny, miłujący dobro, roztropny, sprawiedliwy, święty, powściągliwy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 9, 'Trzymający się wiernego słowa, zgodnego z nauką, aby też mógł przez zdrową naukę napominać i przekonywać tych, którzy się sprzeciwiają.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 10, 'Jest bowiem wielu niekarnych, oddających się czczej gadaninie i zwodzicieli, zwłaszcza wśród obrzezanych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 11, 'Im trzeba zamknąć usta, gdyż całe domy wywracają, nauczając, czego nie należy, dla brudnego zysku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 12, 'Jeden z nich, ich własny prorok, powiedział: Kreteńczycy to zawsze kłamcy, złe bestie, brzuchy leniwe.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 13, 'Świadectwo to jest prawdziwe. Dlatego karć ich surowo, aby byli zdrowi w wierze;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 14, 'I nie zajmowali się żydowskimi baśniami i przykazaniami ludzi odwracających się od prawdy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 15, 'Dla czystych wszystko jest czyste, natomiast dla skalanych i niewierzących nie ma nic czystego, lecz skalany jest zarówno ich umysł, jak i sumienie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 16, 'Twierdzą, że znają Boga, ale swymi uczynkami temu przeczą, budząc obrzydzenie, będąc nieposłusznymi i niezdolnymi do wszelkiego dobrego uczynku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 1, 'Ty zaś mów to, co jest zgodne ze zdrową nauką.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 2, 'Starsi mężczyźni niech będą trzeźwi, poważni, roztropni, zdrowi w wierze, w miłości, w cierpliwości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 3, 'Podobnie starsze kobiety niech zachowują się w sposób godny świętych, niech nie oczerniają, nie nadużywają wina, uczą tego, co dobre.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 4, 'Niech uczą młodsze kobiety rozsądku, jak mają kochać swoich mężów i dzieci;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 5, 'Żeby były roztropne, czyste, żeby zajmowały się domem, były dobre, posłuszne swoim mężom, aby nie bluźniono słowu Bożemu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 6, 'Młodzieńców także napominaj, aby byli trzeźwi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 7, 'We wszystkim stawiaj samego siebie za wzór dobrych uczynków. W nauczaniu okazuj prawość, powagę;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 8, 'Słowa zdrowe, nienaganne, aby ten, kto się sprzeciwia, był zawstydzony, nie mając o was nic złego do powiedzenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 9, 'Sługi nauczaj, aby byli poddani swoim panom i we wszystkim się im podobali, nie sprzeciwiając się;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 10, 'Niczego sobie nie przywłaszczając, ale we wszystkim okazując doskonałą wierność, aby we wszystkim zdobili naukę Boga, naszego Zbawiciela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 11, 'Objawiła się bowiem łaska Boga, niosąca zbawienie wszystkim ludziom;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 12, 'Pouczająca nas, abyśmy wyrzekłszy się bezbożności i światowych pożądliwości, trzeźwo, sprawiedliwie i pobożnie żyli na tym świecie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 13, 'Oczekując błogosławionej nadziei i chwalebnego objawienia się wielkiego Boga i Zbawiciela naszego, Jezusa Chrystusa;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 14, 'Który wydał samego siebie za nas, aby nas wykupić od wszelkiej nieprawości i oczyścić sobie lud na własność, gorliwy w spełnianiu dobrych uczynków.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 15, 'To mów, do tego zachęcaj i strofuj z całą powagą; niech nikt tobą nie gardzi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 1, 'Przypominaj im, aby zwierzchnościom i władzom byli poddani i posłuszni, gotowi do każdego dobrego uczynku;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 2, 'Nikomu nie ubliżali, nie byli kłótliwi, ale uprzejmi, okazujący wszelką łagodność wobec wszystkich ludzi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 3, 'Niegdyś bowiem i my byliśmy głupi, oporni, błądzący, służący rozmaitym pożądliwościom i rozkoszom, żyjący w złośliwości i zazdrości, znienawidzeni i nienawidzący jedni drugich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 4, 'Lecz gdy się objawiła dobroć i miłość Boga, naszego Zbawiciela, względem ludzi;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 5, 'Nie z uczynków sprawiedliwości, które my spełniliśmy, ale według swego miłosierdzia zbawił nas przez obmycie odrodzenia i odnowienie Ducha Świętego;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 6, 'Którego wylał na nas obficie przez Jezusa Chrystusa, naszego Zbawiciela;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 7, 'Abyśmy, usprawiedliwieni jego łaską, stali się dziedzicami zgodnie z nadzieją życia wiecznego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 8, 'Wiarygodne to słowo i chcę, abyś o tym zapewniał, żeby ci, którzy uwierzyli Bogu, zabiegali o celowanie w dobrych uczynkach. Jest to dobre i pożyteczne dla ludzi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 9, 'Unikaj zaś głupich dociekań, rodowodów, sporów i kłótni o prawo; są bowiem nieużyteczne i próżne.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 10, 'Heretyka po pierwszym i drugim upomnieniu unikaj;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 11, 'Wiedząc, że taki człowiek jest przewrotny i grzeszy, i sam siebie osądza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 12, 'Gdy poślę do ciebie Artemasa lub Tychika, staraj się przybyć do mnie do Nikopolis, bo tam postanowiłem spędzić zimę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 13, 'Zenasa, uczonego w prawie, i Apollosa starannie wypraw, aby im niczego nie brakowało.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 14, 'A niech i nasi uczą się przodować w dobrych uczynkach, gdzie tego potrzeba, żeby nie byli bezowocni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 15, 'Pozdrawiają cię wszyscy, którzy są ze mną. Pozdrów tych, którzy nas miłują w wierze. Łaska niech będzie z wami wszystkimi. Amen. List do Tytusa, który był pierwszym biskupem kościoła na Krecie, napisany z Nikopolis, miasta Macedonii.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 1, 'Paweł, więzień Chrystusa Jezusa, i Tymoteusz, brat, do umiłowanego Filemona, naszego współpracownika;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 2, 'Do naszej umiłowanej Apfii, do Archipa, naszego współbojownika i do kościoła, który jest w twoim domu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 3, 'Łaska wam i pokój od Boga, naszego Ojca, i Pana Jezusa Chrystusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 4, 'Dziękuję mojemu Bogu, zawsze wzmiankę czyniąc o tobie w moich modlitwach;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 5, 'Słysząc o twojej miłości i wierze, którą masz względem Pana Jezusa i względem wszystkich świętych;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 6, 'Modlę się, aby udzielenie twojej wiary doprowadziło do poznania wszelkiego dobra, które jest w was przez Chrystusa Jezusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 7, 'Mamy bowiem wielką radość i pociechę z powodu twojej miłości, bracie, gdyż przez ciebie serca świętych zostały pokrzepione.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 8, 'Dlatego, chociaż mogę śmiało w Chrystusie nakazać ci, co należy czynić;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 9, 'To jednak ze względu na miłość raczej proszę, będąc tym, kim jestem – Pawłem, starcem, a teraz i więźniem Jezusa Chrystusa;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 10, 'Proszę cię za moim synem, Onezymem, którego zrodziłem w moich więzach;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 11, 'Który niegdyś był dla ciebie nieużyteczny, ale teraz dla ciebie i dla mnie jest bardzo użyteczny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 12, 'Jego odsyłam, przyjmij go więc jak moje serce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 13, 'Zamierzałem go przy sobie zatrzymać, aby zamiast ciebie posługiwał mi w więzach ewangelii.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 14, 'Lecz bez twojej zgody nie chciałem nic czynić, aby twój dobry uczynek nie był jakby z przymusu, ale z własnej woli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 15, 'Może bowiem dlatego oddalił się na chwilę od ciebie, abyś go odzyskał na zawsze;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 16, 'Już nie jako sługę, lecz więcej niż sługę, jako brata umiłowanego, zwłaszcza dla mnie, a tym bardziej dla ciebie, i w ciele, i w Panu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 17, 'Jeżeli więc masz mnie za przyjaciela, przyjmij go jak mnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 18, 'A jeśli wyrządził ci jakąś szkodę albo jest ci coś winien, policz to na mój rachunek.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 19, 'Ja, Paweł, napisałem własnoręcznie, ja zapłacę, by nie mówić już o tym, że jesteś mi winien samego siebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 20, 'Tak, bracie, niech ja dzięki tobie doznam radości w Panu, pokrzep moje serce w Panu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 21, 'Napisałem ci, będąc pewny twego posłuszeństwa, wiedząc, że uczynisz nawet więcej, niż mówię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 22, 'A zarazem przygotuj mi też gościnę; mam bowiem ufność, że dzięki waszym modlitwom będę wam oddany.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 23, 'Pozdrawiają cię Epafras, mój współwięzień w Chrystusie Jezusie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 24, 'Marek, Arystarch, Demas, Łukasz – moi współpracownicy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 25, 'Łaska naszego Pana Jezusa Chrystusa niech będzie z waszym duchem. Amen. List do Filemona napisany z Rzymu przez Onezyma, sługę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 1, 'Bóg, który wielokrotnie i na różne sposoby przemawiał niegdyś do ojców przez proroków;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 2, 'W tych ostatecznych dniach przemówił do nas przez swego Syna, którego ustanowił dziedzicem wszystkiego, przez którego też stworzył światy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 3, 'Który, będąc blaskiem jego chwały i wyrazem jego istoty i podtrzymując wszystko słowem swojej mocy, dokonawszy oczyszczenia z naszych grzechów przez samego siebie, zasiadł po prawicy Majestatu na wysokościach;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 4, 'I stał się o tyle wyższy od aniołów, o ile znamienitsze od nich odziedziczył imię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 5, 'Do którego bowiem z aniołów powiedział kiedykolwiek: Ty jesteś moim Synem, ja ciebie dziś zrodziłem? I znowu: Ja będę mu Ojcem, a on będzie mi Synem?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 6, 'I znowu, gdy wprowadza pierworodnego na świat, mówi: Niech mu oddają pokłon wszyscy aniołowie Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 7, 'O aniołach zaś mówi: On czyni swoich aniołów duchami, a swoje sługi płomieniami ognia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 8, 'Lecz do Syna mówi: Twój tron, o Boże, na wieki wieków, berłem sprawiedliwości jest berło twego królestwa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 9, 'Umiłowałeś sprawiedliwość, a znienawidziłeś nieprawość, dlatego namaścił cię, o Boże, twój Bóg olejkiem radości bardziej niż twoich towarzyszy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 10, 'Oraz: Ty, Panie, na początku założyłeś fundamenty ziemi, a niebiosa są dziełem twoich rąk.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 11, 'One przeminą, ale ty zostaniesz i wszystkie jak szata się zestarzeją;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 12, 'I jak płaszcz je zwiniesz, i zostaną odmienione. Ty zaś jesteś ten sam, a twoje lata się nie skończą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 13, 'Do którego też z aniołów kiedykolwiek powiedział: Siądź po mojej prawicy, aż położę twoich nieprzyjaciół jako podnóżek pod twoje stopy?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 14, 'Czy nie są oni wszyscy duchami służebnymi, posyłanymi, by służyć tym, którzy mają odziedziczyć zbawienie?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 1, 'Dlatego musimy tym bardziej trzymać się tego, co słyszeliśmy, aby nam to czasem nie uciekło.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 2, 'Bo jeśli słowo wypowiedziane przez aniołów było niewzruszone, a wszelkie wykroczenie i nieposłuszeństwo otrzymało sprawiedliwą odpłatę;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 3, 'Jakże my ujdziemy, jeśli zaniedbamy tak wielkie zbawienie, które było głoszone na początku przez Pana, a potwierdzone nam przez tych, którzy go słyszeli?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 4, 'Którym i Bóg dał świadectwo przez znaki, cuda i różnorakie moce oraz przez udzielanie Ducha Świętego według swojej woli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 5, 'Nie aniołom bowiem poddał przyszły świat, o którym mówimy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 6, 'Ktoś to gdzieś stwierdził, gdy powiedział: Czym jest człowiek, że o nim pamiętasz, albo syn człowieczy, że troszczysz się o niego?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 7, 'Uczyniłeś go niewiele mniejszym od aniołów, chwałą i czcią ukoronowałeś go i ustanowiłeś go nad uczynkami twoich rąk.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 8, 'Wszystko poddałeś pod jego stopy. A skoro poddał mu wszystko, nie pozostawił niczego, co nie byłoby mu poddane. Lecz teraz jeszcze nie widzimy, aby wszystko było mu poddane.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 9, 'Ale widzimy Jezusa, który stał się niewiele mniejszy od aniołów, ukoronowanego chwałą i czcią za cierpienia śmierci, aby z łaski Boga zakosztował śmierci za wszystkich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 10, 'Wypadało bowiem temu, dla którego jest wszystko i przez którego jest wszystko, aby, doprowadzając wielu synów do chwały, wodza ich zbawienia uczynił doskonałym przez cierpienie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 11, 'Zarówno bowiem ten, który uświęca, jak i uświęceni, z jednego są wszyscy. Z tego powodu nie wstydzi się nazywać ich braćmi;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 12, 'Mówiąc: Oznajmię twoje imię moim braciom, pośród zgromadzenia będę ci śpiewał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 13, 'I znowu: Będę pokładał w nim ufność. I znowu: Oto ja i dzieci, które dał mi Bóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 14, 'Ponieważ zaś dzieci są uczestnikami ciała i krwi, i on także stał się ich uczestnikiem, aby przez śmierć zniszczyć tego, który miał władzę nad śmiercią, to jest diabła;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 15, 'I aby wyzwolić tych, którzy z powodu lęku przed śmiercią przez całe życie podlegali niewoli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 16, 'Bo zaprawdę nie przyjął natury aniołów, ale potomstwo Abrahama.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 17, 'Dlatego musiał we wszystkim upodobnić się do braci, aby stał się miłosiernym i wiernym najwyższym kapłanem wobec Boga dla przebłagania za grzechy ludu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 18, 'A że sam cierpiał, będąc kuszony, może dopomóc tym, którzy są w pokusach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 1, 'Dlatego, bracia święci, uczestnicy niebieskiego powołania, zwróćcie uwagę na Apostoła i Najwyższego Kapłana naszego wyznania, Chrystusa Jezusa;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 2, 'Wiernego temu, który go ustanowił, podobnie jak Mojżesz był w całym jego domu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 3, 'Tym większej bowiem chwały jest on godzien od Mojżesza, im większą cześć od domu ma jego budowniczy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 4, 'Bo każdy dom jest przez kogoś zbudowany, lecz tym, który wszystko zbudował, jest Bóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 5, 'I Mojżesz wprawdzie był wierny w całym jego domu jako sługa, na świadectwo tego, co potem miało być powiedziane;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 6, 'Lecz Chrystus jako syn panuje nad swoim domem. Jego domem my jesteśmy, jeśli tylko ufność i chwalebną nadzieję aż do końca niewzruszenie zachowamy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 7, 'Dlatego, jak mówi Duch Święty: Dzisiaj, jeśli usłyszycie jego głos;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 8, 'Nie zatwardzajcie waszych serc jak podczas rozdrażnienia, w dniu próby na pustyni;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 9, 'Gdzie mnie wystawiali na próbę wasi ojcowie i doświadczali, i oglądali moje dzieła przez czterdzieści lat.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 10, 'Dlatego się rozgniewałem na to pokolenie i powiedziałem: Oni zawsze błądzą sercem i nie poznali moich dróg;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 11, 'Toteż przysiągłem w moim gniewie, że nie wejdą do mojego odpoczynku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 12, 'Uważajcie, bracia, żeby nie było czasem w kimś z was przewrotnego serca niewiary, które by odstępowało od Boga żywego;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 13, 'Lecz zachęcajcie się wzajemnie każdego dnia, dopóki nazywa się „Dzisiaj”, aby nikt z was nie popadł w zatwardziałość przez oszustwo grzechu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 14, 'Staliśmy się bowiem uczestnikami Chrystusa, jeśli tylko nasze pierwotne przeświadczenie aż do końca niewzruszenie zachowamy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 15, 'Dopóki jest powiedziane: Dzisiaj, jeśli usłyszycie jego głos, nie zatwardzajcie waszych serc jak w dniu rozdrażnienia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 16, 'Niektórzy bowiem, usłyszawszy, rozdrażnili Pana, ale nie wszyscy z tych, którzy wyszli z Egiptu pod wodzą Mojżesza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 17, 'A na kogo gniewał się przez czterdzieści lat? Czy nie na tych, którzy zgrzeszyli, a których ciała legły na pustyni?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 18, 'A którym przysiągł, że nie wejdą do jego odpoczynku, jeśli nie tym, którzy byli nieposłuszni?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 19, 'Widzimy więc, że nie mogli wejść z powodu niewiary.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 1, 'Bójmy się więc, gdy jeszcze trwa obietnica wejścia do jego odpoczynku, aby czasem się nie okazało, że ktoś z was jej nie osiągnął.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 2, 'I nam bowiem głoszono ewangelię jak i tamtym. Lecz tamtym nie pomogło słowo, które słyszeli, gdyż nie było powiązane z wiarą tych, którzy je słyszeli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 3, 'Bo do odpoczynku wchodzimy my, którzy uwierzyliśmy, jak powiedział: Dlatego przysiągłem w moim gniewie, że nie wejdą do mojego odpoczynku, choć jego dzieła były dokonane od założenia świata.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 4, 'Powiedział bowiem w pewnym miejscu o siódmym dniu tak: I odpoczął Bóg siódmego dnia od wszystkich swoich dzieł.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 5, 'A tutaj znowu: Nie wejdą do mego odpoczynku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 6, 'Ponieważ więc jest tak, że niektórzy mają wejść do niego, a ci, którym najpierw głoszono, nie weszli z powodu niewiary;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 7, 'Znowu wyznacza pewien dzień, mówiąc przez Dawida po tak długim czasie „Dzisiaj”, jak to zostało powiedziane: Dzisiaj, jeśli usłyszycie jego głos, nie zatwardzajcie waszych serc.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 8, 'Gdyby bowiem Jozue zapewnił im odpoczynek, Bóg nie mówiłby potem o innym dniu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 9, 'A tak zostaje jeszcze odpoczynek dla ludu Bożego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 10, 'Kto bowiem wszedł do jego odpoczynku, on także odpoczął od swoich czynów, tak jak Bóg od swoich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 11, 'Starajmy się więc wejść do owego odpoczynku, aby nikt nie wpadł w ten sam przykład niewiary.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 12, 'Słowo Boże bowiem jest żywe i skuteczne, ostrzejsze niż wszelki miecz obosieczny, przenikające aż do rozdzielenia duszy i ducha, stawów i szpiku, zdolne rozsądzić myśli i zamiary serca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 13, 'Żadne stworzenie nie ukryje się przed nim, przeciwnie, wszystko jest obnażone i odkryte przed oczami tego, któremu musimy zdać sprawę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 14, 'Mając więc wielkiego najwyższego kapłana, który przeszedł przez niebiosa, Jezusa, Syna Bożego, trzymajmy się naszego wyznania.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 15, 'Nie mamy bowiem najwyższego kapłana, który by nie mógł współczuć naszym słabościom, lecz kuszonego we wszystkim podobnie jak my, ale bez grzechu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 16, 'Przystąpmy więc z ufnością do tronu łaski, abyśmy dostąpili miłosierdzia i znaleźli łaskę ku pomocy w stosownej chwili.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 1, 'Każdy bowiem najwyższy kapłan wzięty spośród ludzi, dla ludzi jest ustanowiony w sprawach odnoszących się do Boga, aby składał dary i ofiary za grzechy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 2, 'Który może współczuć nieświadomym i błądzącym, gdyż sam podlega słabościom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 3, 'I z tego powodu powinien, jak za lud, tak i za samego siebie składać ofiary za grzechy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 4, 'A nikt sam sobie nie bierze tej godności, tylko ten, który zostaje powołany przez Boga, tak jak Aaron.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 5, 'Podobnie i Chrystus nie sam siebie okrył chwałą, aby stać się najwyższym kapłanem, ale ten, który powiedział do niego: Ty jesteś moim Synem, ja ciebie dziś zrodziłem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 6, 'Tak jak i w innym miejscu mówi: Ty jesteś kapłanem na wieki według porządku Melchizedeka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 7, 'On za dni swego ciała zanosił z głośnym wołaniem i ze łzami modlitwy i usilne prośby do tego, który mógł go wybawić od śmierci, i został wysłuchany z powodu swojej bogobojności.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 8, 'Chociaż był Synem, nauczył się posłuszeństwa przez to, co wycierpiał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 9, 'A uczyniony doskonałym, stał się sprawcą wiecznego zbawienia dla wszystkich, którzy są mu posłuszni;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 10, 'Nazwany przez Boga najwyższym kapłanem według porządku Melchizedeka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 11, 'Wiele mamy o nim do powiedzenia, a trudno wam to wyjaśnić, ponieważ staliście się ociężali w słuchaniu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 12, 'Chociaż bowiem ze względu na czas powinniście być nauczycielami, znowu potrzebujecie, żeby was ktoś uczył początkowych zasad słów Bożych, i staliście się ludźmi, którzy potrzebują mleka, a nie stałego pokarmu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 13, 'Każdy bowiem, kto żywi się tylko mlekiem, jest niewprawny w słowie sprawiedliwości, bo jest niemowlęciem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 14, 'Natomiast pokarm stały jest dla dorosłych, którzy przez praktykę mają zmysły wyćwiczone do rozróżniania dobra i zła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 1, 'Dlatego zostawmy podstawowe nauki o Chrystusie i przejdźmy do tego, co doskonałe, nie zakładając ponownie fundamentu, którym jest pokuta od martwych uczynków i wiara w Boga;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 2, 'Nauka o chrztach i nakładaniu rąk, o zmartwychwstaniu umarłych i sądzie wiecznym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 3, 'I to uczynimy, jeśli Bóg pozwoli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 4, 'Niemożliwe jest bowiem, żeby tych, którzy raz zostali oświeceni i zakosztowali daru niebieskiego, i stali się uczestnikami Ducha Świętego;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 5, 'Zakosztowali też dobrego słowa Bożego i mocy przyszłego wieku;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 6, 'A odpadli – ponownie odnowić ku pokucie, gdyż sami sobie znowu krzyżują Syna Bożego i wystawiają go na hańbę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 7, 'Ziemia bowiem, która pije deszcz często na nią spadający i rodzi rośliny użyteczne dla tych, którzy ją uprawiają, otrzymuje błogosławieństwo od Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 8, 'Lecz ta, która wydaje ciernie i osty, jest odrzucona i bliska przekleństwa, a jej końcem jest spalenie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 9, 'Ale chociaż tak mówimy, umiłowani, jesteśmy co do was przekonani o czymś lepszym i towarzyszącym zbawieniu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 10, 'Bóg bowiem nie jest niesprawiedliwy, aby miał zapomnieć o waszym dziele i trudzie miłości, którą okazaliście dla jego imienia, gdy służyliście świętym i nadal służycie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 11, 'Pragniemy zaś, aby każdy z was okazywał tę samą gorliwość, żebyście mieli pełnię nadziei aż do końca;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 12, 'Abyście nie byli ociężali, ale naśladowali tych, którzy przez wiarę i cierpliwość dziedziczą obietnice.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 13, 'Gdy bowiem Bóg dał obietnicę Abrahamowi, a nie miał nikogo większego, na kogo mógłby przysiąc, przysiągł na siebie samego;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 14, 'Mówiąc: Zaprawdę, błogosławiąc, błogosławić ci będę i rozmnażając, rozmnożę cię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 15, 'A ponieważ tak cierpliwie czekał, dostąpił spełnienia obietnicy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 16, 'Ludzie bowiem przysięgają na kogoś większego, a przysięga dla potwierdzenia jest zakończeniem wszystkich sporów między nimi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 17, 'Dlatego też Bóg, chcąc dobitniej okazać dziedzicom obietnicy niezmienność swojego postanowienia, poręczył ją przysięgą;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 18, 'Abyśmy przez dwie niezmienne rzeczy, w których jest niemożliwe, aby Bóg kłamał, mieli silną pociechę, my, którzy uciekliśmy, by pochwycić się zaoferowanej nam nadziei;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 19, 'Którą mamy jako kotwicę duszy, bezpieczną i niewzruszoną, sięgającą poza zasłonę;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 20, 'Gdzie jako poprzednik wszedł dla nas Jezus, stawszy się najwyższym kapłanem na wieki według porządku Melchizedeka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 1, 'Ten bowiem Melchizedek, król Salemu, kapłan Boga najwyższego, wyszedł na spotkanie Abrahama wracającego po rozgromieniu królów i pobłogosławił go.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 2, 'Jemu też Abraham wydzielił dziesięcinę ze wszystkiego. Jest on najpierw, według tłumaczenia, królem sprawiedliwości, potem też królem Salemu, co znaczy król pokoju.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 3, 'Bez ojca, bez matki, bez rodowodu, niemający ani początku dni, ani końca życia, ale upodobniony do Syna Bożego, pozostaje kapłanem na zawsze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 4, 'Rozważcie więc, jak wielki był ten, któremu sam patriarcha Abraham dał dziesięcinę z łupu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 5, 'Wprawdzie ci z synów Lewiego, którzy otrzymują urząd kapłański, mają nakaz zgodnie z prawem pobierać dziesięcinę od ludu, to jest od swoich braci, chociaż wywodzą się z lędźwi Abrahama;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 6, 'Lecz ten, który nie wywodził się z ich rodu, otrzymał dziesięcinę od Abrahama i pobłogosławił temu, który miał obietnice.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 7, 'A jest to rzecz bezsporna, że mniejszy otrzymuje błogosławieństwo od większego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 8, 'Ponadto tu biorą dziesięciny ludzie, którzy umierają, tam zaś ten, o którym zaświadczono, że żyje.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 9, 'I jeśli tak można powiedzieć, także Lewi, który otrzymuje dziesięciny, dał dziesięcinę w Abrahamie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 10, 'Był bowiem jeszcze w lędźwiach swego ojca, gdy Melchizedek wyszedł mu na spotkanie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 11, 'Gdyby więc doskonałość była osiągalna przez kapłaństwo lewickie – gdyż lud otrzymał prawo oparte na nim – to jaka byłaby jeszcze potrzeba, aby pojawił się inny kapłan według porządku Melchizedeka, a nie był mianowany według porządku Aarona?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 12, 'A skoro zmienia się kapłaństwo, musi też nastąpić zmiana prawa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 13, 'Ten zaś, o którym się to mówi, należał do innego pokolenia, z którego nikt nie służył przy ołtarzu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 14, 'Wiadomo bowiem, że nasz Pan pochodził z pokolenia Judy, o którym to pokoleniu odnośnie kapłaństwa Mojżesz nic nie mówi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 15, 'Jest to jeszcze bardziej oczywiste, skoro na podobieństwo Melchizedeka pojawia się inny kapłan;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 16, 'Który stał się nim nie według cielesnego przykazania prawa, ale według mocy niezniszczalnego życia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 17, 'Tak bowiem świadczy: Ty jesteś kapłanem na wieki według porządku Melchizedeka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 18, 'Zostało więc zniesione poprzednie przykazanie z powodu jego słabości i nieużyteczności.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 19, 'Prawo bowiem nie uczyniło niczego doskonałym, ale na jego miejsce została wprowadzona lepsza nadzieja, przez którą zbliżamy się do Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 20, 'A stało się to nie bez złożenia przysięgi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 21, 'Tamci bowiem zostali kapłanami bez przysięgi, ten zaś na podstawie przysięgi tego, który powiedział do niego: Przysiągł Pan i nie będzie żałował: Ty jesteś kapłanem na wieki według porządku Melchizedeka;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 22, 'O tyle też Jezus stał się poręczycielem lepszego przymierza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 23, 'A wprawdzie tamtych kapłanów było wielu, gdyż śmierć nie pozwoliła im trwać na zawsze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 24, 'Ten zaś, ponieważ trwa na wieki, ma kapłaństwo nieprzemijające.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 25, 'Dlatego też całkowicie może zbawić tych, którzy przez niego przychodzą do Boga, bo zawsze żyje, aby wstawiać się za nimi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 26, 'Takiego to przystało nam mieć najwyższego kapłana: świętego, niewinnego, nieskalanego, oddzielonego od grzeszników i wywyższonego ponad niebiosa;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 27, 'Który nie musi codziennie, jak tamci najwyżsi kapłani, składać ofiar najpierw za własne grzechy, a potem za grzechy ludu. Uczynił to bowiem raz, ofiarując samego siebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 28, 'Prawo bowiem ustanawiało najwyższymi kapłanami ludzi, którzy podlegają słabościom, słowo zaś przysięgi, która nastąpiła po prawie, ustanowiło Syna doskonałego na wieki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 1, 'A oto podsumowanie tego, co mówimy: mamy takiego najwyższego kapłana, który zasiadł po prawicy tronu Majestatu w niebiosach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 2, 'Jest on sługą świątyni i prawdziwego przybytku zbudowanego przez Pana, a nie człowieka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 3, 'Każdy bowiem najwyższy kapłan jest ustanawiany do składania darów i ofiar. Dlatego było konieczne, żeby i ten miał co ofiarować.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 4, 'Gdyby zaś był na ziemi, nie byłby kapłanem, gdyż są tu inni kapłani, którzy ofiarują dary zgodnie z prawem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 5, 'Służą oni obrazowi i cieniowi tego, co niebiańskie, jak Bóg powiedział Mojżeszowi, gdy miał zbudować przybytek: Uważaj – powiedział – abyś uczynił wszystko według wzoru, który ci został ukazany na górze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 6, 'Teraz zaś nasz kapłan o tyle znakomitszą otrzymał służbę, o ile jest pośrednikiem lepszego przymierza, które zostało oparte na lepszych obietnicach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 7, 'Gdyby bowiem to pierwsze było nienaganne, to nie szukano by miejsca na drugie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 8, 'Tymczasem, ganiąc ich, mówi: Oto nadchodzą dni, mówi Pan, gdy zawrę z domem Izraela i z domem Judy nowe przymierze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 9, 'Nie takie przymierze, jakie zawarłem z ich ojcami w dniu, gdy ująłem ich za rękę, aby ich wyprowadzić z ziemi Egiptu. Ponieważ oni nie wytrwali w moim przymierzu, ja też przestałem o nich dbać, mówi Pan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 10, 'Takie zaś jest przymierze, które zawrę z domem Izraela po tych dniach, mówi Pan: Dam moje prawa w ich umysły i wypiszę je na ich sercach. I będę im Bogiem, a oni będą mi ludem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 11, 'I nikt nie będzie uczył swego bliźniego ani nikt swego brata, mówiąc: Poznaj Pana, bo wszyscy będą mnie znali, od najmniejszego aż do największego z nich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 12, 'Będę bowiem łaskawy dla ich występków, a ich grzechów i nieprawości więcej nie wspomnę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 13, 'A gdy mówi „nowe”, uznaje pierwsze za przedawnione; a to, co się przedawnia i starzeje, bliskie jest zaniku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 1, 'Wprawdzie i pierwsze przymierze miało przepisy o służbie Bożej oraz ziemską świątynię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 2, 'Został bowiem zbudowany przybytek, w którego pierwszej części, zwanej Miejscem Świętym, znajdował się świecznik, stół i chleby pokładne.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 3, 'Za drugą zaś zasłoną był przybytek, który zwano Miejscem Najświętszym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 4, 'Posiadało ono złotą kadzielnicę i arkę przymierza całą pokrytą złotem, w której było złote naczynie z manną, laska Aarona, która zakwitła, i tablice przymierza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 5, 'Nad arką były cherubiny chwały, które zacieniały przebłagalnię. Nie ma teraz potrzeby szczegółowo o tym wszystkim mówić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 6, 'A odkąd zostało to tak urządzone, do pierwszej części przybytku zawsze wchodzą kapłani pełniący służbę Bożą;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 7, 'Do drugiej zaś raz w roku tylko sam najwyższy kapłan, i to nie bez krwi, którą ofiaruje za siebie i za grzechy niewiedzy ludu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 8, 'W ten sposób Duch Święty pokazuje, że jeszcze nie została objawiona droga do Miejsca Najświętszego, dopóki jeszcze stał pierwszy przybytek.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 9, 'Był on obrazem na tamten czas, a składano w nim dary i ofiary, które nie mogły uczynić doskonałym w sumieniu tego, który pełnił służbę Bożą;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 10, 'Która polegała tylko na pokarmach, napojach i różnych obmyciach, i przepisach cielesnych nałożonych aż do czasu naprawy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 11, 'Lecz Chrystus, gdy przyszedł jako najwyższy kapłan dóbr przyszłych, przez większy i doskonalszy przybytek, nieuczyniony ręką, to jest nienależący do tego budynku;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 12, 'Ani nie przez krew kozłów i cieląt, ale przez własną krew wszedł raz do Miejsca Najświętszego, zdobywszy wieczne odkupienie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 13, 'Jeśli bowiem krew wołów i kozłów oraz popiół z jałówki, którymi skrapia się nieczystych, uświęca aż do oczyszczenia ciała;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 14, 'To o ileż bardziej krew Chrystusa, który przez Ducha wiecznego ofiarował Bogu samego siebie bez skazy, oczyści wasze sumienie z martwych uczynków, by służyć Bogu żywemu?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 15, 'I dlatego jest pośrednikiem nowego testamentu, ażeby przez śmierć poniesioną dla odkupienia występków, popełnionych za pierwszego testamentu, ci, którzy zostali powołani, otrzymali obietnicę wiecznego dziedzictwa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 16, 'Gdzie bowiem jest testament, tam musi nastąpić śmierć tego, który go sporządził.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 17, 'Testament przecież nabiera mocy po śmierci, gdyż nie jest ważny, dopóki żyje ten, kto sporządził testament.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 18, 'Dlatego i pierwszy testament nie był zapoczątkowany bez krwi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 19, 'Gdy bowiem Mojżesz ogłosił całemu ludowi każde przykazanie zgodnie z prawem, wziął krew cieląt i kozłów z wodą, wełną szkarłatną i hizopem i pokropił zarówno samą księgę, jak i cały lud;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 20, 'Mówiąc: To jest krew przymierza, które Bóg dla was ustanowił.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 21, 'Podobnie też pokropił krwią przybytek i wszystkie naczynia przeznaczone do służby Bożej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 22, 'I prawie wszystko jest oczyszczane krwią zgodnie z prawem, a bez przelania krwi nie ma przebaczenia grzechów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 23, 'Było więc konieczne, aby obrazy rzeczy, które są w niebie, były oczyszczone w ten sposób, same zaś rzeczy niebiańskie – lepszymi ofiarami od tamtych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 24, 'Chrystus bowiem wszedł nie do świątyni zbudowanej ręką, która była odbiciem prawdziwej, ale do samego nieba, aby teraz stawać dla nas przed obliczem Boga;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 25, 'I nie po to, żeby często ofiarować samego siebie jak najwyższy kapłan, który wchodzi co roku do Miejsca Najświętszego z cudzą krwią;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 26, 'Bo inaczej musiałby cierpieć wiele razy od początku świata. Lecz teraz na końcu wieków pojawił się raz dla zgładzenia grzechu przez ofiarowanie samego siebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 27, 'A jak jest postanowione ludziom raz umrzeć, a potem sąd;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 28, 'Tak też Chrystus raz ofiarowany na zgładzenie grzechów wielu, drugi raz ukaże się bez grzechu tym, którzy go oczekują dla zbawienia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 1, 'Prawo bowiem, zawierając cień przyszłych dóbr, a nie sam obraz rzeczy, nie może nigdy przez te same ofiary, które co roku są nieustannie składane, uczynić doskonałymi tych, którzy przychodzą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 2, 'W przeciwnym razie przestano by je składać, dlatego że składający je, raz oczyszczeni, nie mieliby już żadnych grzechów na sumieniu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 3, 'A jednak przez te ofiary każdego roku odbywa się przypominanie grzechów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 4, 'Niemożliwe jest bowiem, aby krew wołów i kozłów gładziła grzechy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 5, 'Dlatego przychodząc na świat, mówi: Ofiary ani daru nie chciałeś, ale przygotowałeś mi ciało.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 6, 'Całopalenia i ofiary za grzech nie podobały się tobie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 7, 'Wtedy powiedziałem: Oto przychodzę – na początku księgi jest napisane o mnie – abym spełniał twoją wolę, o Boże.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 8, 'Powiedziawszy wyżej: Ofiar, darów, całopaleń i ofiar za grzech nie chciałeś i nie podobały się tobie, choć składa się je zgodnie z prawem;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 9, 'Następnie powiedział: Oto przychodzę, abym spełniał twoją wolę, o Boże. Znosi pierwsze, aby ustanowić drugie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 10, 'Za sprawą tej woli jesteśmy uświęceni przez ofiarę ciała Jezusa Chrystusa raz na zawsze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 11, 'A każdy kapłan staje codziennie do wykonywania służby Bożej, wiele razy składając te same ofiary, które nigdy nie mogą zgładzić grzechów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 12, 'Lecz ten, gdy złożył jedną ofiarę za grzechy na zawsze, zasiadł po prawicy Boga;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 13, 'Oczekując odtąd, aż jego nieprzyjaciele będą położeni jako podnóżek pod jego stopy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 14, 'Jedną bowiem ofiarą uczynił doskonałymi na zawsze tych, którzy są uświęceni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 15, 'A poświadcza nam to także Duch Święty. Bo powiedziawszy najpierw:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 16, 'Takie jest przymierze, które zawrę z nimi po tych dniach, mówi Pan: Włożę moje prawa w ich serca i wypiszę je na ich umysłach;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 17, 'Potem dodaje: A ich grzechów i nieprawości więcej nie wspomnę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 18, 'Gdzie zaś jest ich odpuszczenie, tam nie potrzeba już ofiary za grzech.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 19, 'Mając więc, bracia, śmiałość, aby przez krew Jezusa wejść do Najświętszego Miejsca;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 20, 'Drogą nową i żywą, którą zapoczątkował dla nas przez zasłonę, to jest przez swoje ciało;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 21, 'I mając wielkiego kapłana nad domem Bożym;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 22, 'Zbliżmy się ze szczerym sercem, w pełni wiary, mając serca oczyszczone od złego sumienia i ciało obmyte czystą wodą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 23, 'Trzymajmy wyznanie nadziei niechwiejące się, bo wierny jest ten, który obiecał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 24, 'I okazujmy staranie jedni o drugich, by pobudzać się do miłości i dobrych uczynków;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 25, 'Nie opuszczając naszego wspólnego zgromadzenia, jak to niektórzy mają w zwyczaju, ale zachęcając się nawzajem, i to tym bardziej, im bardziej widzicie, że zbliża się ten dzień.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 26, 'Jeśli bowiem dobrowolnie grzeszymy po otrzymaniu poznania prawdy, to nie pozostaje już ofiara za grzechy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 27, 'Lecz jakieś straszliwe oczekiwanie sądu i żar ognia, który strawić ma przeciwników.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 28, 'Kto gardził Prawem Mojżesza, ponosił śmierć bez miłosierdzia na podstawie zeznania dwóch albo trzech świadków.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 29, 'Jak wam się wydaje, na ileż surowszą karę zasługuje ten, kto by podeptał Syna Bożego i zbezcześcił krew przymierza, przez którą został uświęcony, i znieważył Ducha łaski?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 30, 'Znamy bowiem tego, który powiedział: Zemsta do mnie należy, ja odpłacę, mówi Pan. I znowu: Pan będzie sądzić swój lud.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 31, 'Straszna to rzecz wpaść w ręce Boga żywego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 32, 'Przypomnijcie sobie dawne dni, kiedy to po oświeceniu znosiliście wielkie zmagania z cierpieniem;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 33, 'Czy to gdy byliście publicznie wystawieni na pośmiewisko i prześladowania, czy też gdy staliście się uczestnikami w cierpieniach tych, z którymi się tak obchodzono.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 34, 'Cierpieliście bowiem ze mną w moich więzach i przyjęliście z radością grabież waszego mienia, wiedząc, że macie w sobie lepszą i trwałą majętność w niebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 35, 'Nie odrzucajcie więc waszej ufności, która ma wielką zapłatę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 36, 'Potrzeba wam bowiem cierpliwości, abyście wypełniając wolę Boga, dostąpili spełnienia obietnicy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 37, 'Bo jeszcze tylko bardzo krótka chwila, a przyjdzie ten, który ma przyjść, i nie będzie zwlekał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 38, 'A sprawiedliwy będzie żył z wiary, lecz jeśli się ktoś cofnie, moja dusza nie będzie miała w nim upodobania.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 39, 'My zaś nie jesteśmy z tych, którzy się wycofują ku zatraceniu, ale z tych, którzy wierzą ku zbawieniu duszy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 1, 'A wiara jest podstawą tego, czego się spodziewamy, i dowodem tego, czego nie widzimy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 2, 'Przez nią bowiem przodkowie otrzymali chlubne świadectwo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 3, 'Przez wiarę rozumiemy, że światy zostały ukształtowane słowem Boga, tak że to, co widzimy, nie powstało z tego, co widzialne.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 4, 'Przez wiarę Abel złożył Bogu ofiarę lepszą niż Kain, dzięki czemu otrzymał świadectwo, że jest sprawiedliwy, bo Bóg zaświadczył o jego darach. Przez nią też, choć umarł, jeszcze mówi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 5, 'Przez wiarę Henoch został przeniesiony, aby nie oglądał śmierci, i nie znaleziono go, ponieważ Bóg go przeniósł. Zanim bowiem został przeniesiony, miał świadectwo, że podobał się Bogu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 6, 'Bez wiary zaś nie można podobać się Bogu, bo ten, kto przychodzi do Boga, musi wierzyć, że on jest i że nagradza tych, którzy go szukają.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 7, 'Przez wiarę Noe, ostrzeżony przez Boga o tym, czego jeszcze nie widziano, kierowany bojaźnią zbudował arkę, aby ocalić swój dom. Przez nią też potępił świat i stał się dziedzicem sprawiedliwości, która jest z wiary.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 8, 'Przez wiarę Abraham, gdy został wezwany, aby pójść na miejsce, które miał wziąć w dziedzictwo, usłuchał i wyszedł, nie wiedząc, dokąd idzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 9, 'Przez wiarę przebywał w ziemi obiecanej jak w obcej, mieszkając w namiotach z Izaakiem i Jakubem, współdziedzicami tej samej obietnicy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 10, 'Oczekiwał bowiem miasta mającego fundamenty, którego budowniczym i twórcą jest Bóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 11, 'Przez wiarę także sama Sara, mimo podeszłego wieku, otrzymała moc poczęcia potomstwa i urodziła, gdyż za wiernego uznała tego, który obiecał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 12, 'Dlatego z jednego człowieka, i to obumarłego, zrodziło się potomstwo tak liczne, jak gwiazdy niebieskie i jak niezliczony piasek na brzegu morza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 13, 'Wszyscy oni umarli w wierze, nie otrzymawszy spełnienia obietnic, ale z daleka je ujrzeli, cieszyli się nimi i witali je, i wyznawali, że są obcymi i pielgrzymami na ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 14, 'Ci bowiem, którzy tak mówią, wyraźnie okazują, że szukają ojczyzny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 15, 'Gdyby przecież wspominali tę, z której wyszli, mieliby sposobność powrócić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 16, 'Teraz jednak pragną lepszej, to jest niebiańskiej. Dlatego Bóg nie wstydzi się być nazywany ich Bogiem, bo przygotował dla nich miasto.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 17, 'Przez wiarę Abraham, wystawiony na próbę, ofiarował Izaaka. On, który otrzymał obietnicę, złożył w ofierze jednorodzonego syna;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 18, 'On, któremu powiedziano: W Izaaku będzie nazwane twoje potomstwo;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 19, 'Uważał, że Bóg może nawet wskrzesić z martwych, skąd go też otrzymał na podobieństwo zmartwychwstania.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 20, 'Przez wiarę Izaak pobłogosławił Jakuba i Ezawa odnośnie tego, co miało nastąpić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 21, 'Przez wiarę Jakub, umierając, pobłogosławił każdego z synów Józefa i pokłonił się, wsparty o wierzchołek swojej laski.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 22, 'Przez wiarę Józef, umierając, wspomniał o wyjściu synów Izraela i wydał polecenie co do swoich kości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 23, 'Przez wiarę Mojżesz po urodzeniu przez trzy miesiące był ukrywany przez swoich rodziców, ponieważ widzieli, że dziecko jest urodziwe, i nie ulękli się rozkazu króla.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 24, 'Przez wiarę Mojżesz, gdy dorósł, odmówił nazywania się synem córki faraona;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 25, 'Wybierając raczej cierpieć uciski z ludem Bożym, niż mieć doczesną rozkosz z grzechu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 26, 'Uważał zniewagi znoszone dla Chrystusa za większe bogactwo niż skarby Egiptu, bo wypatrywał zapłaty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 27, 'Przez wiarę opuścił Egipt, nie lękając się gniewu króla, bo wytrwał, tak jakby widział Niewidzialnego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 28, 'Przez wiarę obchodził Paschę i pokropienie krwią, aby nie dotknął ich ten, który niszczył pierworodne.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 29, 'Przez wiarę przeszli przez Morze Czerwone jak po suchej ziemi, a gdy Egipcjanie próbowali to uczynić, potonęli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 30, 'Przez wiarę upadły mury Jerycha, gdy je okrążano przez siedem dni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 31, 'Przez wiarę nierządnica Rachab nie zginęła razem z niewierzącymi, gdyż w pokoju przyjęła szpiegów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 32, 'I co jeszcze mam powiedzieć? Nie wystarczyłoby mi bowiem czasu, gdybym miał opowiadać o Gedeonie, Baraku, Samsonie, Jeftem, Dawidzie, Samuelu i o prorokach;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 33, 'Którzy przez wiarę pokonali królestwa, czynili sprawiedliwość, dostąpili spełnienia obietnic, zamknęli paszcze lwom;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 34, 'Zgasili moc ognia, uniknęli ostrza miecza, umocnieni powstawali z niemocy, stali się dzielni na wojnie, zmusili do ucieczki obce wojska.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 35, 'Kobiety odzyskały swoich zmarłych przez wskrzeszenie. Inni zaś byli torturowani, nie przyjąwszy uwolnienia, aby dostąpić lepszego zmartwychwstania.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 36, 'Jeszcze inni doświadczyli szyderstw i biczowania, ponadto kajdan i więzienia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 37, 'Byli kamienowani, przerzynani piłą, doświadczani, zabijani mieczem, tułali się w owczych i kozich skórach, cierpieli niedostatek, ucisk, utrapienie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 38, '(Których świat nie był godny). Błąkali się po pustyniach i górach, po jaskiniach i rozpadlinach ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 39, 'A ci wszyscy, choć zyskali chlubne świadectwo dzięki wierze, nie dostąpili spełnienia obietnicy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 40, 'Ponieważ Bóg przewidział dla nas coś lepszego, aby oni nie stali się doskonali bez nas.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 1, 'Skoro i my mamy wokół siebie tak wielką chmurę świadków, zrzućmy z siebie wszelki ciężar i grzech, który nas tak łatwo osacza, w cierpliwości biegnijmy w wyznaczonym nam wyścigu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 2, 'Patrząc na Jezusa, twórcę i dokończyciela wiary, który z powodu przygotowanej mu radości wycierpiał krzyż, nie zważając na hańbę, i zasiadł po prawicy tronu Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 3, 'Pomyślcie więc o tym, który zniósł tak wielki sprzeciw wobec siebie ze strony grzeszników, abyście nie zniechęcali się w waszych umysłach i nie ustawali.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 4, 'Jeszcze nie stawialiście oporu aż do krwi, walcząc przeciwko grzechowi;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 5, 'I zapomnieliście o napomnieniu, które jest kierowane do was jako synów: Mój synu, nie lekceważ karania Pana i nie zniechęcaj się, gdy on cię napomina.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 6, 'Kogo bowiem Pan miłuje, tego karze, a chłoszcze każdego, którego za syna przyjmuje.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 7, 'Jeśli znosicie karanie, Bóg obchodzi się z wami jak z synami. Jaki to bowiem syn, którego ojciec nie karze?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 8, 'A jeśli jesteście bez karania, którego wszyscy są uczestnikami, wtedy jesteście bękartami, a nie synami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 9, 'Poza tym nasi cieleśni ojcowie nas karali, a szanowaliśmy ich. Czyż nie tym bardziej powinniśmy poddać się Ojcu duchów, abyśmy żyli?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 10, 'Tamci bowiem karali nas przez krótki czas według swego uznania. Ten zaś czyni to dla naszego dobra, abyśmy byli uczestnikami jego świętości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 11, 'A żadne karanie w danej chwili nie wydaje się radosne, ale smutne. Potem jednak przynosi błogi owoc sprawiedliwości tym, którzy przez nie byli ćwiczeni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 12, 'Dlatego wyprostujcie opadłe ręce i omdlałe kolana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 13, 'Prostujcie ścieżki dla waszych stóp, aby to, co chrome, nie zeszło z drogi, ale raczej zostało uzdrowione.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 14, 'Dążcie do pokoju ze wszystkimi i do świętości, bez której nikt nie ujrzy Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 15, 'Uważajcie, żeby nikt nie pozbawił się łaski Boga, żeby jakiś korzeń goryczy, wyrastając, nie wyrządził szkody i aby przez niego nie skalało się wielu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 16, 'Żeby nie było żadnego rozpustnika lub bezbożnika jak Ezaw, który za jedną potrawę sprzedał swoje pierworodztwo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 17, 'Wiecie przecież, że potem, gdy chciał odziedziczyć błogosławieństwo, został odrzucony. Nie znalazł bowiem miejsca na pokutę, choć ze łzami jej szukał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 18, 'Bo nie podeszliście do góry, która da się dotknąć i płonącej ogniem, do mroku, ciemności i burzy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 19, 'Ani do dźwięku trąby i takiego głosu słów, że ci, którzy go słyszeli, prosili, aby już do nich nie mówiono;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 20, '(Nie mogli bowiem znieść tego rozkazu: Gdyby nawet zwierzę dotknęło góry, będzie ukamienowane lub przebite strzałą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 21, 'A tak straszne było to zjawisko, że Mojżesz powiedział: Jestem przerażony i drżę;)');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 22, 'Lecz podeszliście do góry Syjon i do miasta Boga żywego, do niebiańskiego Jeruzalem i do niezliczonej rzeszy aniołów;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 23, 'Na powszechne zebranie, do zgromadzenia pierworodnych, którzy są zapisani w niebie, do Boga, sędziego wszystkich, do duchów sprawiedliwych uczynionych doskonałymi;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 24, 'I do pośrednika nowego przymierza, Jezusa, do krwi, którą się kropi, a która mówi lepsze rzeczy niż krew Abla.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 25, 'Uważajcie, abyście nie odtrącili tego, który przemawia. Jeśli bowiem tamci nie uniknęli kary, odtrąciwszy tego, który na ziemi mówił, tym bardziej my, jeśli odwrócimy się od tego, który przemawia z nieba;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 26, 'Którego głos wstrząsnął wówczas ziemią, a teraz obiecuje, mówiąc: Jeszcze raz wstrząsnę nie tylko ziemią, ale i niebem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 27, 'A słowa „jeszcze raz” ukazują usunięcie tego, co się chwieje, jako tego, co stworzone, aby pozostało to, co się nie chwieje.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 28, 'Dlatego otrzymując królestwo niezachwiane, miejmy łaskę, przez którą możemy służyć Bogu tak, jak mu się to podoba, z czcią i bojaźnią.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 29, 'Nasz Bóg bowiem jest ogniem trawiącym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 1, 'Niech trwa braterska miłość.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 2, 'Nie zapominajcie o gościnności, gdyż przez nią niektórzy, nie wiedząc, aniołów gościli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 3, 'Pamiętajcie o więźniach, jakbyście byli razem z nimi więzieni, o uciskanych, jako ci, którzy też jesteście w ciele.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 4, 'Małżeństwo jest godne czci u wszystkich i łoże nieskalane. Rozpustników zaś i cudzołożników osądzi Bóg.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 5, 'Wasze postępowanie niech będzie wolne od chciwości, poprzestawajcie na tym, co macie. Sam bowiem powiedział: Nie porzucę cię ani nie opuszczę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 6, 'Śmiało więc możemy mówić: Pan jest moim pomocnikiem, nie będę się lękał tego, co może mi uczynić człowiek.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 7, 'Pamiętajcie o swoich przywódcach, którzy głosili wam słowo Boże, i rozważając koniec ich życia, naśladujcie ich wiarę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 8, 'Jezus Chrystus wczoraj i dziś, ten sam i na wieki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 9, 'Nie dajcie się zwieść rozmaitym i obcym naukom. Dobrze jest bowiem umacniać serce łaską, a nie pokarmami, co nie przyniosły pożytku tym, którzy się nimi zajmowali.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 10, 'Mamy ołtarz, z którego nie mają prawa spożywać ci, którzy służą przybytkowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 11, 'Ciała bowiem tych zwierząt, których krew najwyższy kapłan wnosi do Najświętszego Miejsca za grzech, są spalane za obozem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 12, 'Dlatego i Jezus, aby uświęcić lud własną krwią, cierpiał poza bramą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 13, 'Wyjdźmy więc do niego poza obóz, biorąc na siebie jego pohańbienie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 14, 'Nie mamy tu bowiem miasta trwałego, lecz tego przyszłego szukamy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 15, 'Przez niego więc nieustannie składajmy Bogu ofiarę chwały, to jest owoc warg, które wyznają jego imię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 16, 'Nie zapominajcie też o dobroczynności i udzieleniu dóbr, takie bowiem ofiary podobają się Bogu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 17, 'Bądźcie posłuszni waszym przywódcom i bądźcie im ulegli, ponieważ oni czuwają nad waszymi duszami jako ci, którzy muszą zdać z tego sprawę. Niech to czynią z radością, a nie ze wzdychaniem, bo to nie byłoby dla was korzystne.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 18, 'Módlcie się za nas. Ufamy bowiem, że mamy czyste sumienie, gdyż chcemy we wszystkim dobrze postępować.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 19, 'A tym bardziej proszę was, abyście to czynili, abym jak najszybciej został wam przywrócony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 20, 'A Bóg pokoju, który przez krew wiecznego przymierza wyprowadził spośród umarłych wielkiego pasterza owiec, naszego Pana Jezusa;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 21, 'Niech was uczyni doskonałymi w każdym dobrym uczynku, abyście spełniali jego wolę, dokonując w was tego, co miłe w jego oczach, przez Jezusa Chrystusa, któremu chwała na wieki wieków. Amen.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 22, 'A proszę was, bracia, przyjmijcie to słowo zachęty, bo krótki list do was napisałem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 23, 'Wiedzcie, że brat Tymoteusz został uwolniony. Jeśli niedługo przybędzie, wraz z nim was zobaczę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 24, 'Pozdrówcie wszystkich waszych przywódców i wszystkich świętych. Pozdrawiają was bracia, którzy są z Italii.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 25, 'Łaska niech będzie z wami wszystkimi. Amen. List do Hebrajczyków napisany z Italii przez Tymoteusza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 1, 'Jakub, sługa Boga i Pana Jezusa Chrystusa, przesyła pozdrowienia dwunastu pokoleniom, które są w rozproszeniu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 2, 'Poczytujcie to sobie za największą radość, moi bracia, gdy rozmaite próby przechodzicie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 3, 'Wiedząc, że doświadczenie waszej wiary wyrabia cierpliwość.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 4, 'Cierpliwość zaś niech dopełni swego dzieła, abyście byli doskonali i zupełni, niemający żadnych braków.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 5, 'A jeśli komuś z was brakuje mądrości, niech prosi Boga, który daje wszystkim obficie i bez wypominania, a będzie mu dana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 6, 'Ale niech prosi z wiarą, bez powątpiewania. Kto bowiem wątpi, podobny jest do fali morskiej pędzonej przez wiatr i miotanej tu i tam.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 7, 'Człowiek taki niech nie myśli, że coś otrzyma od Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 8, 'Człowiek umysłu dwoistego jest niestały we wszystkich swoich drogach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 9, 'Niech ubogi brat chlubi się ze swojego wywyższenia;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 10, 'A bogaty ze swego poniżenia, bo przeminie jak kwiat trawy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 11, 'Jak bowiem wzeszło palące słońce, wysuszyło trawę, a kwiat jej opadł i zginęło piękno jego wyglądu, tak też bogaty zmarnieje na swoich drogach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 12, 'Błogosławiony człowiek, który znosi próbę, bo gdy zostanie wypróbowany, otrzyma koronę życia, którą obiecał Pan tym, którzy go miłują.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 13, 'Niech nikt, gdy jest kuszony, nie mówi: Jestem kuszony przez Boga. Bóg bowiem nie może być kuszony do złego ani sam nikogo nie kusi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 14, 'Lecz każdy jest kuszony przez własną pożądliwość, która go pociąga i nęci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 15, 'Następnie pożądliwość, gdy pocznie, rodzi grzech, a grzech, gdy będzie wykonany, rodzi śmierć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 16, 'Nie błądźcie, moi umiłowani bracia!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 17, 'Wszelki dar dobry i wszelki dar doskonały pochodzi z góry i zstępuje od Ojca światłości, u którego nie ma zmiany ani cienia zmienności.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 18, 'Ze swojej woli zrodził nas słowem prawdy, abyśmy byli jakby pierwocinami jego stworzeń.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 19, 'Tak więc, moi umiłowani bracia, niech każdy człowiek będzie skory do słuchania, nieskory do mówienia i nieskory do gniewu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 20, 'Gniew bowiem człowieka nie wykonuje sprawiedliwości Bożej.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 21, 'Odrzućcie więc wszelką plugawość oraz bezmiar zła i z łagodnością przyjmijcie zaszczepione w was słowo, które może zbawić wasze dusze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 22, 'Bądźcie więc wykonawcami słowa, a nie tylko słuchaczami, oszukującymi samych siebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 23, 'Jeśli bowiem ktoś jest słuchaczem słowa, a nie wykonawcą, podobny jest do człowieka, który przygląda się w lustrze swemu naturalnemu obliczu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 24, 'Bo przyjrzał się sobie, odszedł i zaraz zapomniał, jakim był.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 25, 'Lecz kto wpatruje się w doskonałe prawo wolności i trwa w nim, nie jest słuchaczem, który zapomina, lecz wykonawcą dzieła, ten będzie błogosławiony w swoim działaniu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 26, 'Jeśli ktoś wśród was sądzi, że jest pobożny, a nie powściąga swego języka, lecz oszukuje swe serce, tego pobożność jest próżna.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 27, 'Czysta i nieskalana pobożność u Boga i Ojca polega na tym, aby przychodzić z pomocą sierotom i wdowom w ich utrapieniu i zachować samego siebie nieskażonym przez świat.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 1, 'Bracia moi, niech wiara naszego Pana Jezusa Chrystusa, Pana chwały, będzie wolna od względu na osobę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 2, 'Gdyby bowiem na wasze zgromadzenie przyszedł człowiek ze złotym pierścieniem i we wspaniałej szacie i przyszedłby też ubogi w nędznym stroju;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 3, 'A wy zwrócicie oczy na tego, który ma wspaniałą szatę i powiecie: Ty usiądź tu w zaszczytnym miejscu, do ubogiego zaś powiecie: Ty stań tam lub usiądź tu u mego podnóżka;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 4, 'To czy nie czynicie różnicy między sobą i nie stajecie się sędziami o przewrotnych myślach?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 5, 'Posłuchajcie, moi umiłowani bracia: Czyż Bóg nie wybrał ubogich tego świata, aby byli bogatymi w wierze i dziedzicami królestwa, które obiecał tym, którzy go miłują?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 6, 'Lecz wy wzgardziliście ubogim. Czyż to nie bogaci was uciskają i nie oni ciągną was do sądów?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 7, 'Czyż nie oni bluźnią zaszczytnemu imieniu, od którego jesteście nazwani?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 8, 'A jeśli wypełniacie królewskie prawo zgodnie z Pismem: Będziesz miłował swego bliźniego jak samego siebie, dobrze czynicie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 9, 'Lecz jeśli macie wzgląd na osobę, popełniacie grzech i jesteście osądzeni przez prawo jako przestępcy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 10, 'Kto bowiem przestrzega całego prawa, a przekroczy jedno przykazanie, staje się winnym wszystkich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 11, 'Bo ten, który powiedział: Nie będziesz cudzołożył, powiedział też: Nie będziesz zabijał. Jeżeli więc nie cudzołożysz, ale zabijasz, jesteś przestępcą prawa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 12, 'Tak mówcie i tak czyńcie, jak ci, którzy mają być sądzeni przez prawo wolności.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 13, 'Sąd bowiem bez miłosierdzia odbędzie się nad tym, który nie czynił miłosierdzia, a miłosierdzie chlubi się przeciwko sądowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 14, 'Jaki z tego pożytek, moi bracia, jeśli ktoś mówi, że ma wiarę, a nie ma uczynków? Czy wiara może go zbawić?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 15, 'Gdyby brat albo siostra nie mieli się w co ubrać i brakowałoby im codziennego pożywienia;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 16, 'A ktoś z was powiedziałby im: Idźcie w pokoju, ogrzejcie się i najedzcie, a nie dalibyście im tego, czego potrzebuje ciało, jaki z tego pożytek?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 17, 'Tak i wiara, jeśli nie ma uczynków, martwa jest sama w sobie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 18, 'Lecz ktoś może powiedzieć: Ty masz wiarę, a ja mam uczynki; pokaż mi swoją wiarę bez twoich uczynków, a ja ci pokażę swoją wiarę z moich uczynków.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 19, 'Ty wierzysz, że jest jeden Bóg, i dobrze czynisz. Demony także wierzą i drżą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 20, 'Czy chcesz się przekonać, marny człowieku, że wiara bez uczynków jest martwa?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 21, 'Czy Abraham, nasz ojciec, nie został usprawiedliwiony z uczynków, gdy ofiarował Izaaka, swego syna, na ołtarzu?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 22, 'Widzisz, że wiara współdziałała z jego uczynkami i przez uczynki wiara stała się doskonała.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 23, 'I tak wypełniło się Pismo, które mówi: Uwierzył Abraham Bogu i poczytano mu to za sprawiedliwość, i został nazwany przyjacielem Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 24, 'Widzicie więc, że człowiek zostaje usprawiedliwiony z uczynków, a nie tylko z wiary.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 25, 'Podobnie i nierządnica Rachab, czy nie z uczynków została usprawiedliwiona, gdy przyjęła wysłanników i wypuściła ich inną drogą?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 26, 'Jak bowiem ciało bez ducha jest martwe, tak i wiara bez uczynków jest martwa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 1, 'Niech niewielu z was zostaje nauczycielami, moi bracia, gdyż wiecie, że czeka nas surowszy sąd.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 2, 'Wszyscy bowiem w wielu sprawach upadamy. Jeśli ktoś nie upada w mowie, jest człowiekiem doskonałym, który też może utrzymać na wodzy całe ciało.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 3, 'Oto koniom wkładamy wędzidła do pysków, aby były nam posłuszne, i kierujemy całym ich ciałem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 4, 'Podobnie i statki, choć są tak wielkie i pędzone gwałtownymi wichrami, jednak za pomocą niewielkiego steru są kierowane tam, dokąd chce sternik.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 5, 'Tak też język jest małym organem, lecz bardzo się przechwala. Jakże wielki las zapala mały ogień!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 6, 'Język też jest ogniem i światem nieprawości. Język jest tak ułożony wśród naszych członków, że kala całe ciało i zapala bieg życia, i jest zapalony przez ogień piekielny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 7, 'Wszelki bowiem rodzaj dzikich zwierząt, ptaków, gadów i morskich stworzeń można ujarzmić i zostaje ujarzmiony przez człowieka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 8, 'Natomiast nikt z ludzi nie może ujarzmić języka. Jest to nieokiełznane zło, pełne śmiercionośnego jadu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 9, 'Nim błogosławimy Boga i Ojca i nim przeklinamy ludzi stworzonych na podobieństwo Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 10, 'Z tych samych ust wychodzi błogosławieństwo i przekleństwo. Tak być nie powinno, moi bracia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 11, 'Czy źródło z tej samej szczeliny tryska wodą słodką i gorzką?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 12, 'Czy może, moi bracia, drzewo figowe rodzić oliwki albo winorośl figi? Tak też żadne źródło nie może wydać słonej i słodkiej wody.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 13, 'Kto wśród was jest mądry i rozumny? Niech pokaże dobrym postępowaniem swoje uczynki z łagodnością właściwą mądrości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 14, 'Jeśli jednak macie w waszym sercu gorzką zazdrość i kłótliwość, to nie przechwalajcie się i nie kłamcie wbrew prawdzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 15, 'Nie jest to mądrość zstępująca z góry, lecz ziemska, zmysłowa, diabelska.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 16, 'Gdzie bowiem jest zazdrość i kłótliwość, tam też niepokój i wszelki zły czyn.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 17, 'Mądrość zaś, która jest z góry, jest przede wszystkim czysta, następnie pokojowo usposobiona, łagodna, ustępliwa, pełna miłosierdzia i dobrych owoców, bezstronna i nieobłudna.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 18, 'A owoc sprawiedliwości jest siany w pokoju przez tych, którzy czynią pokój.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 1, 'Skąd wojny i walki wśród was? Czy nie z waszych żądz, które toczą bój w waszych członkach?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 2, 'Pożądacie, a nie macie, zabijacie i zazdrościcie, a nie możecie osiągnąć. Toczycie wojny i walki, a nie macie, bo nie prosicie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 3, 'Prosicie, a nie otrzymujecie, dlatego że źle prosicie, chcąc tym zaspokoić wasze żądze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 4, 'Cudzołożnicy i cudzołożnice, czy nie wiecie, że przyjaźń ze światem jest nieprzyjaźnią z Bogiem? Jeśli więc ktoś chce być przyjacielem świata, staje się nieprzyjacielem Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 5, 'Czy sądzicie, że na próżno Pismo mówi: Duch, który w nas mieszka, zazdrośnie pożąda?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 6, 'Większą zaś daje łaskę, bo mówi: Bóg sprzeciwia się pysznym, a pokornym daje łaskę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 7, 'Poddajcie się więc Bogu, przeciwstawcie się diabłu, a ucieknie od was.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 8, 'Zbliżcie się do Boga, a on zbliży się do was. Obmyjcie ręce, grzesznicy, i oczyśćcie serca, ludzie umysłu dwoistego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 9, 'Ubolewajcie, smućcie się i płaczcie. Wasz śmiech niech się obróci w smutek, a radość w przygnębienie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 10, 'Uniżcie się przed Panem, a on was wywyższy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 11, 'Nie obmawiajcie jedni drugich, bracia. Kto obmawia brata i osądza brata, obmawia prawo i osądza prawo. Jeśli zaś osądzasz prawo, nie jesteś wykonawcą prawa, lecz sędzią.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 12, 'Jeden jest prawodawca, który ma moc zbawić i zatracić. A ty kim jesteś, że osądzasz drugiego?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 13, 'A teraz wy, którzy mówicie: Dziś albo jutro udamy się do tego miasta i zatrzymamy się tam przez rok, będziemy handlować i osiągniemy zyski;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 14, 'Wy, którzy nie wiecie, co jutro będzie. Bo czymże jest wasze życie? Doprawdy jest parą, która pojawia się na krótko, a potem znika.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 15, 'Zamiast tego powinniście mówić: Jeżeli Pan zechce i będziemy żyli, zrobimy to lub owo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 16, 'Teraz zaś przechwalacie się w waszej pysze. Wszelkie takie przechwalanie się jest złe.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 17, 'Kto więc umie dobrze czynić, a nie czyni, popełnia grzech.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 1, 'A teraz wy, bogacze, płaczcie, zawodząc nad nieszczęściami, które na was przyjdą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 2, 'Wasze bogactwo zgniło, a wasze szaty zjadły mole.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 3, 'Wasze złoto i srebro zardzewiało, a ich rdza będzie świadczyła przeciwko wam i strawi wasze ciała jak ogień. Nagromadziliście skarby na ostatnie dni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 4, 'Oto zapłata robotników, którzy żęli wasze pola, zatrzymana przez was, krzyczy, a krzyk żniwiarzy doszedł do uszu Pana zastępów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 5, 'Żyliście w rozkoszach i zbytku na ziemi, utuczyliście wasze serca jak na dzień rzezi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 6, 'Skazaliście i zabiliście sprawiedliwego, a on nie stawia wam oporu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 7, 'Bądźcie więc cierpliwi, bracia, aż do przyjścia Pana. Oto rolnik cierpliwie czeka na cenny plon ziemi, dopóki nie spadnie deszcz wczesny i późny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 8, 'Bądźcie i wy cierpliwi i umacniajcie swoje serca, bo przyjście Pana jest bliskie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 9, 'Bracia, nie narzekajcie jedni na drugich, abyście nie zostali osądzeni. Oto sędzia stoi przed drzwiami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 10, 'Weźcie za przykład, moi bracia, utrapienia i cierpliwość proroków, którzy mówili w imieniu Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 11, 'Oto za błogosławionych uważamy tych, którzy wytrwali. Słyszeliście o cierpliwości Hioba i widzieliście koniec przygotowany przez Pana, że Pan jest pełen litości i miłosierdzia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 12, 'A przede wszystkim, moi bracia, nie przysięgajcie ani na niebo, ani na ziemię, ani nie składajcie żadnej innej przysięgi. Lecz niech wasze „tak” będzie „tak”, a „nie” niech będzie „nie”, abyście nie byli sądzeni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 13, 'Cierpi ktoś wśród was? Niech się modli. Raduje się ktoś? Niech śpiewa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 14, 'Choruje ktoś wśród was? Niech przywoła starszych kościoła i niech się modlą nad nim, namaszczając go olejem w imię Pana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 15, 'A modlitwa wiary uzdrowi chorego i Pan go podźwignie. Jeśli zaś popełnił grzechy, będą mu przebaczone.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 16, 'Wyznawajcie sobie nawzajem upadki i módlcie się jedni za drugich, abyście byli uzdrowieni. Wiele może usilna modlitwa sprawiedliwego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 17, 'Eliasz był człowiekiem podlegającym tym samym doznaniom co my i modlił się gorliwie, żeby nie padał deszcz, i nie spadł deszcz na ziemię przez trzy lata i sześć miesięcy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 18, 'Potem znowu się modlił i niebo spuściło deszcz, i ziemia wydała swój plon.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 19, 'Bracia, jeśli ktoś z was zejdzie z drogi prawdy, a ktoś go nawróci;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 20, 'Niech wie, że kto nawróci grzesznika z jego błędnej drogi, wybawi duszę od śmierci i zakryje mnóstwo grzechów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 1, 'Piotr, apostoł Jezusa Chrystusa, do wychodźców rozproszonych w Poncie, Galacji, Kapadocji, Azji i Bitynii;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 2, 'Wybranych według uprzedniej wiedzy Boga Ojca, przez uświęcenie Ducha dla posłuszeństwa i pokropienia krwią Jezusa Chrystusa. Łaska i pokój niech się wam pomnożą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 3, 'Błogosławiony niech będzie Bóg i Ojciec naszego Pana Jezusa Chrystusa, który według swego wielkiego miłosierdzia zrodził nas na nowo do żywej nadziei przez wskrzeszenie Jezusa Chrystusa z martwych;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 4, 'Do dziedzictwa niezniszczalnego i nieskalanego, i niewiędnącego, zachowanego w niebie dla was;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 5, 'Którzy jesteście strzeżeni mocą Boga przez wiarę ku zbawieniu, przygotowanemu do objawienia się w czasie ostatecznym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 6, 'Z tego się radujecie, choć teraz na krótko, jeśli trzeba, zasmuceni jesteście z powodu rozmaitych prób;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 7, 'Aby doświadczenie waszej wiary, o wiele cenniejszej od zniszczalnego złota, które jednak próbuje się w ogniu, okazało się ku chwale, czci i sławie przy objawieniu Jezusa Chrystusa;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 8, 'A choć go nie widzieliście, miłujecie; i w niego, choć teraz go nie widzicie, wierzycie; i cieszycie się radością niewysłowioną i pełną chwały;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 9, 'Otrzymując koniec waszej wiary – zbawienie dusz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 10, 'O to zbawienie wywiadywali się i badali je prorocy, którzy prorokowali o przeznaczonej dla was łasce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 11, 'Badali oni, na jaką i jakiego rodzaju porę wskazywał Duch Chrystusa, który był w nich, przepowiadając cierpienia, które miały przyjść na Chrystusa i mającą potem nastąpić chwałę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 12, 'Zostało im objawione, że nie im samym, lecz nam służyły sprawy wam teraz zwiastowane przez tych, którzy wam głosili ewangelię przez Ducha Świętego zesłanego z nieba. W te sprawy pragną wejrzeć aniołowie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 13, 'Dlatego przepaszcie biodra waszego umysłu i bądźcie trzeźwi, pokładając doskonałą nadzieję w łasce, która będzie wam dana przy objawieniu Jezusa Chrystusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 14, 'Jak posłuszne dzieci nie ulegajcie pożądliwościom, jakie władały wami wcześniej, w czasie waszej nieświadomości;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 15, 'Lecz jak ten, który was powołał, jest święty, tak i wy bądźcie świętymi we wszelkim waszym postępowaniu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 16, 'Gdyż jest napisane: Świętymi bądźcie, bo ja jestem święty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 17, 'A jeżeli Ojcem nazywacie tego, który bez względu na osobę sądzi każdego według uczynków, spędzajcie czas waszego pielgrzymowania w bojaźni;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 18, 'Wiedząc, że nie tym, co zniszczalne, srebrem lub złotem, zostaliście wykupieni z waszego marnego postępowania przekazanego przez ojców;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 19, 'Lecz drogą krwią Chrystusa jako baranka niewinnego i nieskalanego;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 20, 'Przeznaczonego do tego przed założeniem świata, a objawionego w czasach ostatecznych ze względu na was.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 21, 'Wy przez niego uwierzyliście w Boga, który go wskrzesił z martwych i dał mu chwałę, aby wasza wiara i nadzieja były w Bogu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 22, 'Skoro oczyściliście swoje dusze, będąc posłuszni prawdzie przez Ducha ku nieobłudnej braterskiej miłości, czystym sercem jedni drugich gorąco miłujcie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 23, 'Będąc odrodzeni nie z nasienia zniszczalnego, ale z niezniszczalnego, przez słowo Boże, które jest żywe i trwa na wieki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 24, 'Gdyż wszelkie ciało jest jak trawa, a wszelka chwała człowieka jak kwiat trawy. Trawa uschła, a jej kwiat opadł;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 25, 'Lecz słowo Pana trwa na wieki. A jest to słowo, które zostało wam zwiastowane.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 1, 'Odrzucając więc wszelką złośliwość, wszelki podstęp i obłudę, zazdrość i wszelkie obmowy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 2, 'Jak nowo narodzone niemowlęta pragnijcie czystego mleka słowa Bożego, abyście dzięki niemu rośli;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 3, 'Jeśli tylko zakosztowaliście, że Pan jest dobry.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 4, 'Zbliżając się do niego, do kamienia żywego, odrzuconego wprawdzie przez ludzi, ale przez Boga wybranego i drogocennego;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 5, 'I wy sami, jak żywe kamienie, jesteście budowani w duchowy dom, stanowicie święte kapłaństwo, aby składać duchowe ofiary, przyjemne Bogu przez Jezusa Chrystusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 6, 'Dlatego mówi Pismo: Oto kładę na Syjonie kamień węgielny, wybrany, drogocenny, a kto w niego wierzy, nie będzie zawstydzony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 7, 'Dla was więc, którzy wierzycie, jest on cenny, dla nieposłusznych zaś ten kamień, który odrzucili budujący, stał się kamieniem węgielnym;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 8, 'Kamieniem potknięcia i skałą zgorszenia dla tych, którzy nie wierząc, potykają się o słowo, na co też są przeznaczeni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 9, 'Lecz wy jesteście rodem wybranym, królewskim kapłaństwem, narodem świętym, ludem nabytym, abyście rozgłaszali cnoty tego, który was powołał z ciemności do swej cudownej światłości;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 10, 'Wy, którzy kiedyś nie byliście ludem, teraz jesteście ludem Bożym, wy, którzy kiedyś nie dostąpiliście miłosierdzia, teraz miłosierdzia dostąpiliście.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 11, 'Umiłowani, proszę was, abyście jak obcy i goście powstrzymywali się od cielesnych pożądliwości, które walczą przeciwko duszy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 12, 'Postępujcie wśród pogan nienagannie, aby ci, którzy oczerniają was jako złoczyńców, przypatrując się waszym dobrym uczynkom, chwalili Boga w dniu nawiedzenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 13, 'Bądźcie więc poddani każdej ludzkiej władzy ze względu na Pana: czy to królowi jako najwyżej postawionemu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 14, 'Czy to namiestnikom jako przez niego posłanym dla karania złoczyńców i udzielania pochwały tym, którzy dobrze czynią.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 15, 'Taka bowiem jest wola Boga, abyście dobrze czyniąc, zamknęli usta niewiedzy głupich ludzi;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 16, 'Jak ludzie wolni, ale nie jak ci, którzy używają wolności jako zasłony dla zła, lecz jak słudzy Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 17, 'Wszystkich szanujcie, braci miłujcie, Boga się bójcie, króla czcijcie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 18, 'Słudzy, z całą bojaźnią bądźcie poddani panom, nie tylko dobrym i łagodnym, ale też przykrym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 19, 'To bowiem podoba się Bogu, jeśli ktoś znosi smutki ze względu na sumienie wobec Boga, cierpiąc niewinnie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 20, 'Bo cóż to za chwała, jeśli grzesząc, cierpliwie znosicie, choćby was i pięściami bito? Lecz jeśli dobrze czynicie i znosicie cierpienia, to podoba się Bogu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 21, 'Do tego bowiem jesteście powołani, bo i Chrystus cierpiał za nas, zostawiając nam przykład, abyście szli w jego ślady;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 22, 'Który grzechu nie popełnił, a w jego ustach nie znaleziono podstępu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 23, 'Który, gdy mu złorzeczono, nie odpowiadał złorzeczeniem, gdy cierpiał, nie groził, ale powierzył sprawę temu, który sądzi sprawiedliwie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 24, 'On nasze grzechy na swoim ciele poniósł na drzewo, abyśmy obumarłszy grzechom, żyli dla sprawiedliwości; przez jego rany zostaliście uzdrowieni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 25, 'Byliście bowiem jak zbłąkane owce, lecz teraz nawróciliście się do Pasterza i Biskupa waszych dusz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 1, 'Podobnie żony, bądźcie poddane swoim mężom, aby nawet ci, którzy nie wierzą słowu, przez postępowanie żon zostali pozyskani bez słowa;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 2, 'Widząc wasze czyste, pełne bojaźni postępowanie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 3, 'Niech waszą ozdobą nie będzie to, co zewnętrzne: zaplatanie włosów, obłożenie się złotem lub strojenie w szaty;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 4, 'Lecz ukryty, wewnętrzny człowiek w niezniszczalnej ozdobie łagodności i spokoju ducha, który jest cenny w oczach Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 5, 'Tak bowiem niegdyś przyozdabiały się święte kobiety, pokładające nadzieję w Bogu, będąc poddane swoim mężom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 6, 'Tak też Sara była posłuszna Abrahamowi, nazywając go panem. Jej córkami jesteście wy, jeśli tylko dobrze czynicie i nie dajecie się niczym zastraszyć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 7, 'Podobnie wy, mężowie, żyjcie z nimi umiejętnie, okazując im szacunek jako słabszemu naczyniu kobiecemu i jako tym, które współdziedziczą łaskę życia, aby wasze modlitwy nie doznały przeszkód.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 8, 'Na koniec zaś wszyscy bądźcie jednomyślni, współczujący, miłujący braci, miłosierni i uprzejmi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 9, 'Nie oddawajcie złem za zło ani obelgą za obelgę. Przeciwnie, błogosławcie, gdyż wiecie, że do tego zostaliście powołani, abyście odziedziczyli błogosławieństwo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 10, 'Kto bowiem chce miłować życie i oglądać dni dobre, niech powstrzyma język od zła, a usta od podstępnej mowy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 11, 'Niech odwróci się od zła i czyni dobro, niech szuka pokoju i dąży do niego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 12, 'Oczy Pana bowiem zwrócone są na sprawiedliwych, a jego uszy ku ich prośbom, lecz oblicze Pana przeciwko tym, którzy źle czynią.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 13, 'Kto wyrządzi wam zło, jeśli będziecie naśladowcami dobra?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 14, 'Ale jeśli nawet cierpicie dla sprawiedliwości, błogosławieni jesteście. Nie bójcie się ich gróźb ani się nie lękajcie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 15, 'Lecz Pana Boga uświęcajcie w waszych sercach i bądźcie zawsze gotowi udzielić odpowiedzi każdemu, kto domaga się od was uzasadnienia waszej nadziei, z łagodnością i bojaźnią.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 16, 'Miejcie czyste sumienie, aby za to, że mówią o was źle, jak o złoczyńcach, zostali zawstydzeni ci, którzy zniesławiają wasze dobre postępowanie w Chrystusie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 17, 'Lepiej bowiem – jeśli taka jest wola Boga – cierpieć, czyniąc dobrze, aniżeli czyniąc źle.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 18, 'Gdyż i Chrystus raz za grzechy cierpiał, sprawiedliwy za niesprawiedliwych, aby nas przyprowadzić do Boga; uśmiercony w ciele, lecz ożywiony Duchem;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 19, 'W którym poszedł i głosił też duchom będącym w więzieniu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 20, 'Niegdyś nieposłusznym, gdy za dni Noego raz oczekiwała Boża cierpliwość, kiedy budowano arkę, w której niewiele, to jest osiem dusz, zostało uratowanych przez wodę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 21, 'Teraz też chrzest, będąc tego odbiciem, zbawia nas – nie jest usunięciem cielesnego brudu, ale odpowiedzią czystego sumienia wobec Boga – przez zmartwychwstanie Jezusa Chrystusa;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 22, 'Który, poszedłszy do nieba, jest po prawicy Boga, a zostali mu poddani aniołowie, zwierzchności i moce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 1, 'Skoro więc Chrystus cierpiał za nas w ciele, wy również uzbrójcie się tą samą myślą, że ten, kto cierpiał w ciele, zaprzestał grzechu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 2, 'Aby żyć resztę czasu w ciele już nie dla ludzkich pożądliwości, lecz dla woli Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 3, 'Wystarczy nam bowiem, że w minionym okresie życia spełnialiśmy zachcianki pogan, żyjąc w rozpuście, pożądliwościach, pijaństwie, biesiadach, pijatykach i niegodziwym bałwochwalstwie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 4, 'Dlatego dziwią się, że nie nurzacie się z nimi w tym samym zalewie rozpusty, i źle o was mówią.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 5, 'Zdadzą oni sprawę temu, który gotowy jest sądzić żywych i umarłych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 6, 'Dlatego bowiem i umarłym głoszono ewangelię, aby byli sądzeni według ludzi w ciele, ale żyli według Boga w duchu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 7, 'Zbliża się zaś koniec wszystkiego. Bądźcie więc trzeźwi i czujni w modlitwie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 8, 'Przede wszystkim miejcie gorliwą miłość jedni dla drugich, bo miłość zakrywa mnóstwo grzechów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 9, 'Bądźcie dla siebie gościnni bez szemrania.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 10, 'Jako dobrzy szafarze różnorakiej łaski Bożej usługujcie sobie nawzajem tym darem, jaki każdy otrzymał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 11, 'Jeśli ktoś przemawia, niech mówi jak wyroki Boga, jeśli ktoś usługuje, niech to czyni z mocy, której Bóg udziela, aby we wszystkim był uwielbiony Bóg przez Jezusa Chrystusa. Jemu chwała i panowanie na wieki wieków. Amen.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 12, 'Umiłowani, nie dziwcie się temu ogniowi, który na was przychodzi, aby was doświadczyć, jakby was coś niezwykłego spotkało;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 13, 'Lecz radujcie się z tego, że jesteście uczestnikami cierpień Chrystusa, abyście i podczas objawienia jego chwały cieszyli się i weselili.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 14, 'Jeśli was znieważają z powodu imienia Chrystusa, błogosławieni jesteście, gdyż Duch chwały, Duch Boży spoczywa na was, który przez nich jest bluźniony, ale przez was jest uwielbiony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 15, 'Nikt z was niech nie cierpi jednak jako morderca albo złodziej, albo złoczyńca, albo jako człowiek, który się wtrąca do cudzych spraw.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 16, 'Lecz jeśli cierpi jako chrześcijanin, niech się nie wstydzi, niech raczej chwali Boga z tego powodu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 17, 'Nadszedł bowiem czas, aby sąd rozpoczął się od domu Bożego, a jeśli rozpoczyna się od nas, to jaki będzie koniec tych, którzy są nieposłuszni ewangelii Bożej?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 18, 'A ponieważ sprawiedliwy z trudnością będzie zbawiony, gdzie się znajdzie bezbożny i grzesznik?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 19, 'Tak więc ci, którzy cierpią zgodnie z wolą Boga, niech powierzają swoje dusze jemu jako wiernemu Stwórcy, dobrze czyniąc.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 1, 'Starszych, którzy są wśród was, proszę jako również starszy i świadek cierpień Chrystusa oraz uczestnik chwały, która ma się objawić:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 2, 'Paście stado Boga, które jest wśród was, doglądając go nie z przymusu, ale dobrowolnie, nie dla brudnego zysku, ale z ochotą;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 3, 'I nie jak ci, którzy panują nad dziedzictwem Pana, lecz jako wzór dla stada.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 4, 'A gdy się objawi Najwyższy Pasterz, otrzymacie niewiędnącą koronę chwały.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 5, 'Podobnie młodsi, bądźcie poddani starszym. Wszyscy zaś wobec siebie bądźcie poddani. Przyobleczcie się w pokorę, gdyż Bóg pysznym się sprzeciwia, a pokornym łaskę daje.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 6, 'Uniżcie się więc pod potężną ręką Boga, aby was wywyższył w odpowiednim czasie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 7, 'Wszystkie wasze troski przerzućcie na niego, gdyż on troszczy się o was.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 8, 'Bądźcie trzeźwi, czuwajcie, bo wasz przeciwnik, diabeł, jak lew ryczący krąży, szukając, kogo by pożreć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 9, 'Przeciwstawiajcie się mu, mocni w wierze, wiedząc, że te same cierpienia są udziałem waszych braci na świecie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 10, 'A Bóg wszelkiej łaski, ten, który nas powołał do swojej wiecznej chwały w Chrystusie Jezusie, po krótkotrwałych cierpieniach waszych niech uczyni was doskonałymi, utwierdzi, umocni i ugruntuje.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 11, 'Jemu chwała i moc na wieki wieków. Amen.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 12, 'Przez Sylwana, wiernego wam brata, jak sądzę, napisałem krótko, napominając i świadcząc, że to jest prawdziwa łaska Boga, w której trwacie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 13, 'Pozdrawia was kościół w Babilonie, razem z wami wybrany, i Marek, mój syn.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 14, 'Pozdrówcie się nawzajem pocałunkiem miłości. Pokój wam wszystkim, którzy jesteście w Chrystusie Jezusie. Amen.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 1, 'Szymon Piotr, sługa i apostoł Jezusa Chrystusa, do tych, którzy otrzymali wiarę równie cenną jak nasza, dzięki sprawiedliwości naszego Boga i Zbawiciela, Jezusa Chrystusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 2, 'Łaska i pokój niech się wam pomnożą przez poznanie Boga i Jezusa, naszego Pana;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 3, 'Jako że jego Boska moc obdarzyła nas wszystkim, co potrzebne do życia i pobożności, przez poznanie tego, który nas powołał do chwały i cnoty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 4, 'Przez to zostały nam dane bardzo wielkie i cenne obietnice, abyście przez nie stali się uczestnikami Boskiej natury, uniknąwszy zepsucia, które wskutek pożądliwości jest na świecie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 5, 'Dlatego też, dokładając wszelkich starań, dodajcie do waszej wiary cnotę, do cnoty poznanie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 6, 'Do poznania powściągliwość, do powściągliwości cierpliwość, do cierpliwości pobożność;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 7, 'Do pobożności braterską życzliwość, a do życzliwości braterskiej miłość.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 8, 'Gdy bowiem będą one w was, i to w obfitości, to nie uczynią was bezczynnymi ani bezowocnymi w poznawaniu naszego Pana Jezusa Chrystusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 9, 'Kto zaś ich nie ma, jest ślepy, krótkowzroczny i zapomniał, że został oczyszczony ze swoich dawnych grzechów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 10, 'Dlatego, bracia, tym bardziej starajcie się umocnić wasze powołanie i wybranie. To bowiem czyniąc, nigdy się nie potkniecie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 11, 'W ten sposób hojnie będzie wam dane wejście do wiecznego królestwa naszego Pana i Zbawiciela, Jezusa Chrystusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 12, 'Dlatego nie zaniedbam zawsze wam o tych sprawach przypominać, chociaż je znacie i utwierdzeni jesteście w obecnej prawdzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 13, 'Uważam bowiem za słuszne, dopóki jestem w tym namiocie, pobudzać was przez przypominanie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 14, 'Wiedząc, że bliskie jest zwinięcie mojego namiotu, jak mi to też objawił nasz Pan Jezus Chrystus.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 15, 'Dołożę jednak starań, abyście po moim odejściu zawsze mieli to w pamięci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 16, 'Gdyż daliśmy wam poznać moc i przyjście naszego Pana Jezusa Chrystusa, nie podążając za zręcznie wymyślonymi baśniami, ale jako naoczni świadkowie jego wielkości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 17, 'Otrzymał on bowiem od Boga Ojca cześć i chwałę, gdy doszedł go taki głos od wspaniałej chwały: To jest mój umiłowany Syn, w którym mam upodobanie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 18, 'I słyszeliśmy ten głos dochodzący z nieba, gdy byliśmy z nim na świętej górze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 19, 'Mamy też mocniejsze słowo prorockie, a wy dobrze czynicie, trzymając się go jak lampy, która świeci w ciemnym miejscu, dopóki dzień nie zaświta i jutrzenka nie wzejdzie w waszych sercach;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 20, 'To przede wszystkim wiedząc, że żadne proroctwo Pisma nie podlega własnemu wykładowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 21, 'Nie z ludzkiej bowiem woli przyniesione zostało kiedyś proroctwo, ale święci Boży ludzie przemawiali prowadzeni przez Ducha Świętego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 1, 'Byli też fałszywi prorocy wśród ludu, jak i wśród was będą fałszywi nauczyciele, którzy potajemnie wprowadzą herezje zatracenia, wypierając się Pana, który ich odkupił, i sprowadzą na siebie rychłą zgubę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 2, 'Wielu zaś podąży za ich zgubną drogą, a droga prawdy z ich powodu będzie bluźniona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 3, 'I z chciwości będą wami kupczyć przez zmyślone opowieści. Ich sąd od dawna nie zwleka, a ich zatracenie nie śpi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 4, 'Jeśli bowiem Bóg nie oszczędził aniołów, którzy zgrzeszyli, ale strąciwszy ich do piekła, wydał więzom ciemności, aby byli zachowani na sąd;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 5, 'Także dawnego świata nie oszczędził, ale zbawił jako ósmego Noego, kaznodzieję sprawiedliwości, gdy zesłał potop na świat bezbożnych;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 6, 'I miasta Sodomę i Gomorę, obracając w popiół, skazał na potępienie, stawiając je jako przykład dla tych, którzy żyją bezbożnie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 7, 'A sprawiedliwego Lota, udręczonego rozpustnym postępowaniem bezbożników, wyrwał;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 8, '(Ten sprawiedliwy bowiem, mieszkając wśród nich, patrząc i słuchając, trapił dzień po dniu swą sprawiedliwą duszę ich bezbożnymi uczynkami);');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 9, 'Umie Pan pobożnych wyrwać z pokusy, a niesprawiedliwych zachować na dzień sądu, aby byli ukarani;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 10, 'Przede wszystkim zaś tych, którzy podążają za ciałem w nieczystej żądzy i pogardzają władzą. Zuchwali i samowolni, nie boją się bluźnić przeciwko przełożonym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 11, 'Tymczasem aniołowie, więksi siłą i mocą, nie wnoszą przeciwko nim przed Pana bluźnierczego oskarżenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 12, 'Ale ci, jak nierozumne zwierzęta, z natury przeznaczone na schwytanie i zagładę, bluźnią przeciwko temu, czego nie znają, toteż zginą w swoim zepsuciu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 13, 'I otrzymają zapłatę za niesprawiedliwość, skoro uważają za przyjemność hulanie za dnia. Zakały i plugawcy, upajają się swymi oszustwami, gdy z wami ucztują.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 14, 'Mając oczy pełne cudzołóstwa i nieprzestające grzeszyć, zwabiają dusze niestałe. Serce mają wyćwiczone w chciwości, synowie przekleństwa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 15, 'Opuścili oni prostą drogę i zbłądzili, podążając drogą Balaama, syna Bosora, który umiłował zapłatę za niesprawiedliwość;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 16, 'Został jednak skarcony za swoją nieprawość: niema juczna oślica, przemówiwszy ludzkim głosem, powstrzymała szaleństwo proroka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 17, 'Oni są źródłami bez wody, obłokami pędzonymi przez wicher, dla których mroki ciemności zachowane są na wieki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 18, 'Mówiąc bowiem słowa wyniosłe i puste, zwabiają żądzami ciała i rozpustą tych, którzy prawdziwie uciekli od żyjących w błędzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 19, 'Wolność im obiecują, a sami są niewolnikami zepsucia. Przez co bowiem jest ktoś pokonany, przez to też jest zniewolony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 20, 'Bo jeśli uciekli oni od plugastw świata przez poznanie Pana i Zbawiciela Jezusa Chrystusa, a potem znowu się w nie wikłają i zostają pokonani, to ich ostateczny stan jest gorszy niż pierwszy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 21, 'Lepiej bowiem byłoby dla nich nie poznać drogi sprawiedliwości, aniżeli poznawszy ją, odwrócić się od przekazanego im świętego przykazania.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 22, 'Ale przydarzyło się im zgodnie z prawdziwym przysłowiem: Pies wrócił do swoich wymiocin, a świnia umyta do tarzania się w błocie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 1, 'Umiłowani, piszę do was już ten drugi list. W nich przez przypominanie pobudzam wasz czysty umysł;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 2, 'Abyście pamiętali słowa wcześniej wypowiedziane przez świętych proroków oraz przykazanie od nas, którzy jesteśmy apostołami Pana i Zbawiciela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 3, 'Przede wszystkim to wiedzcie, że w ostatecznych dniach przyjdą szydercy, którzy będą postępować według swoich własnych pożądliwości;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 4, 'I będą mówili: Co z obietnicą jego przyjścia? Bo odkąd zasnęli ojcowie, wszystko tak trwa, jak od początku stworzenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 5, 'Tego bowiem umyślnie nie chcą wiedzieć, że niebiosa były od dawna i ziemia z wody, i w wodzie stanęła przez słowo Boże;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 6, 'Przez które ówczesny świat, zalany wodą, zginął.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 7, 'A obecne niebiosa i ziemia przez to samo słowo są utrzymane i zachowane dla ognia na dzień sądu i zatracenia bezbożnych ludzi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 8, 'Ale niech to jedno, umiłowani, nie będzie przed wami zakryte, że jeden dzień u Pana jest jak tysiąc lat, a tysiąc lat jak jeden dzień.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 9, 'Nie zwleka Pan ze spełnieniem obietnicy, jak niektórzy uważają, że zwleka, ale okazuje względem nas cierpliwość, nie chcąc, aby ktokolwiek zginął, lecz aby wszyscy doszli do pokuty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 10, 'A jak złodziej w nocy przyjdzie dzień Pana, w którym niebiosa z wielkim hukiem przeminą, żywioły rozpalone ogniem stopią się, a ziemia i dzieła, które są na niej, spłoną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 11, 'Skoro to wszystko ma się rozpłynąć, to jakimi wy powinniście być w świętym postępowaniu i pobożności;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 12, 'Oczekując i spiesząc się na przyjście dnia Boga, w którym płonące niebiosa rozpuszczą się, a rozpalone żywioły się roztopią.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 13, 'Lecz my, zgodnie z jego obietnicą, oczekujemy nowych niebios i nowej ziemi, w których mieszka sprawiedliwość.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 14, 'Dlatego, umiłowani, oczekując tego, starajcie się, abyście zostali przez niego znalezieni bez skazy i nienaganni, w pokoju;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 15, 'A cierpliwość naszego Pana uważajcie za zbawienie, jak i nasz umiłowany brat Paweł według danej mu mądrości pisał do was;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 16, 'Jak też mówi o tym we wszystkich listach. Są w nich pewne rzeczy trudne do zrozumienia, które, podobnie jak inne Pisma, ludzie niedouczeni i nieutwierdzeni przekręcają ku swemu własnemu zatraceniu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 17, 'Wy zatem, umiłowani, wiedząc o tym wcześniej, miejcie się na baczności, abyście nie byli zwiedzeni przez błąd bezbożników i nie wypadli z waszej stałości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 18, 'Wzrastajcie zaś w łasce i poznaniu naszego Pana i Zbawiciela, Jezusa Chrystusa. Jemu chwała i teraz, i na wieczne czasy. Amen.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 1, 'To, co było od początku, co słyszeliśmy, co widzieliśmy na własne oczy, na co patrzyliśmy i czego dotykały nasze ręce, o Słowie życia;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 2, '(Bo życie zostało objawione, a my je widzieliśmy i świadczymy o nim, i zwiastujemy wam to życie wieczne, które było u Ojca, a nam zostało objawione).');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 3, 'To, co widzieliśmy i słyszeliśmy, to wam zwiastujemy, abyście i wy mieli z nami społeczność, a nasza społeczność to społeczność z Ojcem i z jego Synem, Jezusem Chrystusem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 4, 'A piszemy to wam, aby wasza radość była pełna.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 5, 'Przesłanie zaś, które słyszeliśmy od niego i wam zwiastujemy, jest takie: Bóg jest światłością i nie ma w nim żadnej ciemności.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 6, 'Jeśli mówimy, że mamy z nim społeczność, a chodzimy w ciemności, kłamiemy i nie czynimy prawdy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 7, 'A jeśli chodzimy w światłości, tak jak on jest w światłości, mamy społeczność między sobą, a krew Jezusa Chrystusa, jego Syna, oczyszcza nas z wszelkiego grzechu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 8, 'Jeśli mówimy, że nie mamy grzechu, sami siebie zwodzimy i nie ma w nas prawdy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 9, 'Jeśli wyznajemy nasze grzechy, Bóg jest wierny i sprawiedliwy, aby nam przebaczyć grzechy i oczyścić nas z wszelkiej nieprawości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 10, 'Jeśli mówimy, że nie zgrzeszyliśmy, robimy z niego kłamcę i nie ma w nas jego słowa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 1, 'Moje dzieci, piszę wam to, abyście nie grzeszyli. Jeśli jednak ktoś zgrzeszy, mamy orędownika u Ojca, Jezusa Chrystusa sprawiedliwego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 2, 'I on jest przebłaganiem za nasze grzechy, a nie tylko za nasze, lecz także za grzechy całego świata.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 3, 'A po tym poznajemy, że go znamy, jeśli zachowujemy jego przykazania.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 4, 'Kto mówi: Znam go, a nie zachowuje jego przykazań, jest kłamcą i nie ma w nim prawdy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 5, 'Lecz kto zachowuje jego słowo, w nim prawdziwie wypełniła się miłość Boga. Po tym poznajemy, że w nim jesteśmy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 6, 'Kto mówi, że w nim trwa, powinien sam postępować tak, jak on postępował.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 7, 'Bracia, nie piszę wam nowego przykazania, ale przykazanie stare, które mieliście od początku. Tym starym przykazaniem jest słowo, które słyszeliście od początku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 8, 'Zarazem piszę wam nowe przykazanie, które jest prawdziwe w nim i w was, ponieważ ciemność przemija, a prawdziwa światłość już świeci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 9, 'Kto mówi, że jest w światłości, a nienawidzi swego brata, dotąd jeszcze jest w ciemności.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 10, 'Kto miłuje swego brata, trwa w światłości i nie ma w nim powodu do upadku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 11, 'Lecz kto nienawidzi swego brata, jest w ciemności i chodzi w ciemności, i nie wie, dokąd idzie, bo ciemność zaślepiła jego oczy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 12, 'Piszę do was, dzieci, bo zostały wam przebaczone grzechy ze względu na jego imię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 13, 'Piszę do was, ojcowie, bo poznaliście tego, który jest od początku. Piszę do was, młodzieńcy, bo zwyciężyliście złego. Piszę do was, dzieci, bo poznałyście Ojca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 14, 'Napisałem do was, ojcowie, bo poznaliście tego, który jest od początku. Napisałem do was, młodzieńcy, bo jesteście mocni i słowo Boże w was mieszka, i zwyciężyliście złego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 15, 'Nie miłujcie świata ani tego, co jest na świecie. Jeśli ktoś miłuje świat, nie ma w nim miłości Ojca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 16, 'Wszystko bowiem, co jest na świecie – pożądliwość ciała, pożądliwość oczu i pycha życia – nie pochodzi od Ojca, ale od świata.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 17, 'A świat przemija wraz ze swoją pożądliwością, ale kto wypełnia wolę Boga, trwa na wieki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 18, 'Dzieci, to już ostatnia godzina i jak słyszeliście, że antychryst ma przyjść, tak teraz pojawiło się wielu antychrystów. Stąd wiemy, że jest już ostatnia godzina.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 19, 'Wyszli spośród nas, ale nie byli z nas. Gdyby bowiem byli z nas, zostaliby z nami. Lecz wyszli spośród nas, aby się okazało, że nie wszyscy są z nas.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 20, 'Ale wy macie namaszczenie od Świętego i wiecie wszystko.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 21, 'Napisałem do was nie dlatego, że nie znaliście prawdy, ale dlatego, że ją znacie i że żadne kłamstwo nie wywodzi się z prawdy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 22, 'Któż jest kłamcą? Czy nie ten, kto zaprzecza, że Jezus jest Chrystusem? Ten jest antychrystem, który wypiera się Ojca i Syna.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 23, 'Każdy, kto wypiera się Syna, nie ma i Ojca. Kto zaś wyznaje Syna, ma i Ojca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 24, 'To więc, co słyszeliście od początku, niech w was pozostanie. Jeśli pozostanie w was to, co słyszeliście od początku, to i wy pozostaniecie w Synu i w Ojcu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 25, 'A to jest obietnica, którą on nam dał – życie wieczne.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 26, 'To wszystko wam napisałem o tych, którzy was zwodzą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 27, 'Ale to namaszczenie, które otrzymaliście od niego, pozostaje w was i nie potrzebujecie, aby was ktoś uczył. Lecz jak to namaszczenie uczy was o wszystkim, a jest ono prawdziwe i nie jest kłamstwem i jak was nauczyło, tak w nim pozostaniecie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 28, 'A teraz, dzieci, pozostańcie w nim, abyśmy, gdy się ukaże, mieli ufność i nie zostali zawstydzeni przez niego w czasie jego przyjścia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 29, 'Jeżeli wiecie, że on jest sprawiedliwy, wiedzcie też, że każdy, kto czyni sprawiedliwość, z niego się narodził.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 1, 'Patrzcie, jaką miłością obdarzył nas Ojciec, że zostaliśmy nazwani dziećmi Bożymi. Dlatego świat nas nie zna, bo jego nie zna.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 2, 'Umiłowani, teraz jesteśmy dziećmi Bożymi, ale jeszcze się nie objawiło, czym będziemy. Wiemy jednak, że gdy on się objawi, będziemy podobni do niego, gdyż ujrzymy go takim, jakim jest.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 3, 'A każdy, kto pokłada w nim tę nadzieję, oczyszcza się, jak i on jest czysty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 4, 'Każdy, kto popełnia grzech, przekracza też prawo, ponieważ grzech jest przekroczeniem prawa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 5, 'A wiecie, że on się objawił, aby zgładzić nasze grzechy, a w nim nie ma grzechu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 6, 'Każdy więc, kto w nim trwa, nie grzeszy. Każdy, kto grzeszy, nie widział go ani go nie poznał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 7, 'Dzieci, niech was nikt nie zwodzi. Kto czyni sprawiedliwość, jest sprawiedliwy, tak jak i on jest sprawiedliwy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 8, 'Kto popełnia grzech, jest z diabła, gdyż diabeł od początku grzeszy. Po to objawił się Syn Boży, aby zniszczyć dzieła diabła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 9, 'Każdy, kto się narodził z Boga, nie popełnia grzechu, bo jego nasienie w nim pozostaje i nie może grzeszyć, gdyż narodził się z Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 10, 'Po tym poznaje się dzieci Boże i dzieci diabła: Każdy, kto nie czyni sprawiedliwości, nie jest z Boga, jak i ten, kto nie miłuje swego brata.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 11, 'To jest przesłanie, które słyszeliście od początku, że mamy się wzajemnie miłować.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 12, 'Nie jak Kain, który pochodził od złego i zabił swego brata. A dlaczego go zabił? Bo jego uczynki były złe, a jego brata sprawiedliwe.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 13, 'Nie dziwcie się, moi bracia, jeśli świat was nienawidzi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 14, 'My wiemy, że przeszliśmy ze śmierci do życia, bo miłujemy braci. Kto nie miłuje brata, pozostaje w śmierci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 15, 'Każdy, kto nienawidzi swego brata, jest mordercą, a wiecie, że żaden morderca nie ma życia wiecznego zostającego w sobie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 16, 'Po tym poznaliśmy miłość Boga, że on oddał za nas swoje życie. My również powinniśmy oddawać życie za braci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 17, 'A kto miałby majętność tego świata i widziałby swego brata w potrzebie, a zamknąłby przed nim swoje serce, jakże może mieszkać w nim miłość Boga?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 18, 'Moje dzieci, nie miłujmy słowem ani językiem, ale uczynkiem i prawdą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 19, 'Po tym poznamy, że jesteśmy z prawdy i uspokoimy przed nim nasze serca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 20, 'Bo jeśli nasze serce nas potępia, Bóg jest większy niż nasze serce i wie wszystko.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 21, 'Umiłowani, jeśli nasze serce nas nie potępia, mamy ufność ku Bogu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 22, 'I o cokolwiek prosimy, otrzymujemy od niego, bo zachowujemy jego przykazania i robimy to, co miłe w jego oczach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 23, 'A to jest jego przykazanie, abyśmy wierzyli w imię jego Syna, Jezusa Chrystusa, i miłowali się wzajemnie, jak nam przykazał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 24, 'Bo kto zachowuje jego przykazania, mieszka w nim, a on w nim. A wiemy, że w nas mieszka, przez Ducha, którego nam dał.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 1, 'Umiłowani, nie wierzcie każdemu duchowi, ale badajcie duchy, czy są z Boga, gdyż wielu fałszywych proroków wyszło na świat.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 2, 'Po tym poznacie Ducha Bożego: każdy duch, który wyznaje, że Jezus Chrystus przyszedł w ciele, jest z Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 3, 'Każdy zaś duch, który nie wyznaje, że Jezus Chrystus przyszedł w ciele, nie jest z Boga. Jest to duch antychrysta, o którym słyszeliście, że nadchodzi i już teraz jest na świecie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 4, 'Dzieci, wy jesteście z Boga i zwyciężyliście ich, ponieważ ten, który jest w was, jest większy niż ten, który jest na świecie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 5, 'Oni są ze świata, dlatego mówią o świecie, a świat ich słucha.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 6, 'My jesteśmy z Boga. Kto zna Boga, słucha nas, kto nie jest z Boga, nie słucha nas. Po tym poznajemy ducha prawdy i ducha błędu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 7, 'Umiłowani, miłujmy się wzajemnie, gdyż miłość jest z Boga i każdy, kto miłuje, narodził się z Boga i zna Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 8, 'Kto nie miłuje, nie zna Boga, gdyż Bóg jest miłością.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 9, 'Przez to objawiła się miłość Boga ku nam, że Bóg posłał na świat swego jednorodzonego Syna, abyśmy żyli przez niego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 10, 'Na tym polega miłość, że nie my umiłowaliśmy Boga, ale że on nas umiłował i posłał swego Syna, aby był przebłaganiem za nasze grzechy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 11, 'Umiłowani, jeśli Bóg tak nas umiłował, to i my powinniśmy się wzajemnie miłować.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 12, 'Boga nikt nigdy nie widział, ale jeśli miłujemy się wzajemnie, Bóg w nas mieszka, a jego miłość jest w nas doskonała.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 13, 'Po tym poznajemy, że w nim mieszkamy, a on w nas, że dał nam ze swego Ducha.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 14, 'My zaś widzieliśmy i świadczymy, że Ojciec posłał Syna, aby był Zbawicielem świata.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 15, 'Każdy, kto wyzna, że Jezus jest Synem Bożym, w tym mieszka Bóg, a on w Bogu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 16, 'My poznaliśmy i uwierzyliśmy w miłość, którą ma Bóg do nas. Bóg jest miłością, a kto trwa w miłości, mieszka w Bogu, a Bóg w nim.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 17, 'W tym jest doskonała miłość w nas, abyśmy mieli ufność w dniu sądu, że jaki on jest, tacy i my jesteśmy na tym świecie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 18, 'W miłości nie ma lęku, ale doskonała miłość usuwa lęk, bo lęk przynosi udrękę, a kto się boi, nie jest doskonały w miłości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 19, 'My go miłujemy, ponieważ on pierwszy nas umiłował.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 20, 'Jeśli ktoś mówi: Miłuję Boga, a nienawidzi swego brata, jest kłamcą. Kto bowiem nie miłuje swego brata, którego widzi, jak może miłować Boga, którego nie widzi?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 21, 'A takie przykazanie mamy od niego, aby ten, kto miłuje Boga, miłował też swego brata.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 1, 'Każdy, kto wierzy, że Jezus jest Chrystusem, narodził się z Boga, a każdy, kto miłuje tego, który zrodził, miłuje też tego, który się z niego narodził.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 2, 'Po tym poznajemy, że miłujemy dzieci Boże, gdy miłujemy Boga i zachowujemy jego przykazania.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 3, 'Na tym bowiem polega miłość Boga, że zachowujemy jego przykazania, a jego przykazania nie są ciężkie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 4, 'Bo wszystko, co się narodziło z Boga, zwycięża świat. A tym zwycięstwem, które zwyciężyło świat, jest nasza wiara.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 5, 'Kto zwycięża świat, jeśli nie ten, kto wierzy, że Jezus jest Synem Bożym?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 6, 'To jest ten, który przyszedł przez wodę i krew, Jezus Chrystus, nie tylko w wodzie, ale w wodzie i we krwi; a Duch jest tym, który świadczy, bo Duch jest prawdą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 7, 'Trzej bowiem świadczą w niebie: Ojciec, Słowo i Duch Święty, a ci trzej jedno są.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 8, 'A trzej świadczą na ziemi: Duch, woda i krew, a ci trzej są zgodni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 9, 'Jeśli przyjmujemy świadectwo ludzi, to świadectwo Boga jest większe. To bowiem jest świadectwo Boga, które dał o swoim Synu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 10, 'Kto wierzy w Syna Bożego, ma świadectwo w sobie. Kto nie wierzy Bogu, zrobił z niego kłamcę, bo nie uwierzył świadectwu, które Bóg dał o swoim Synu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 11, 'A to świadectwo jest takie, że Bóg dał nam życie wieczne, a to życie jest w jego Synu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 12, 'Kto ma Syna, ma życie, kto nie ma Syna Bożego, nie ma życia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 13, 'To napisałem wam, którzy wierzycie w imię Syna Bożego, abyście wiedzieli, że macie życie wieczne i abyście wierzyli w imię Syna Bożego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 14, 'Taka zaś jest ufność, którą mamy do niego, że jeśli o coś prosimy zgodnie z jego wolą, wysłuchuje nas.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 15, 'A jeśli wiemy, że nas wysłuchuje, o cokolwiek prosimy, wtedy wiemy, że otrzymujemy to, o co go prosiliśmy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 16, 'Jeśli ktoś widzi swego brata, który popełnia grzech nie na śmierć, niech się za niego modli, a Bóg da mu życie, to jest tym, którzy popełniają grzech nie na śmierć. Jest grzech na śmierć. Nie mówię, aby ktoś modlił się za to.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 17, 'Wszelka niesprawiedliwość jest grzechem, jest jednak grzech nie na śmierć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 18, 'Wiemy, że każdy, kto się narodził z Boga, nie grzeszy, ale kto się narodził z Boga, zachowuje samego siebie, a zły go nie dotyka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 19, 'Wiemy, że jesteśmy z Boga, a cały świat tkwi w niegodziwości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 20, 'A wiemy, że Syn Boży przyszedł i dał nam rozum, abyśmy poznali prawdziwego Boga, i jesteśmy w tym prawdziwym, to jest w jego Synu, Jezusie Chrystusie. On jest prawdziwym Bogiem i życiem wiecznym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 21, 'Dzieci, wystrzegajcie się bożków. Amen.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 1, 'Starszy do wybranej pani i do jej dzieci, które miłuję w prawdzie, a nie tylko ja, ale i wszyscy, którzy poznali prawdę;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 2, 'Ze względu na prawdę, która pozostaje w nas i będzie z nami na wieki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 3, 'Łaska, miłosierdzie i pokój od Boga Ojca i od Pana Jezusa Chrystusa, Syna Ojca, niech będzie z wami w prawdzie i miłości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 4, 'Ucieszyłem się bardzo, że wśród twoich dzieci znalazłem takie, które postępują w prawdzie, jak otrzymaliśmy przykazanie od Ojca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 5, 'A teraz proszę cię, pani, nie piszę ci jako nowe przykazanie, ale jako to, które mieliśmy od początku, abyśmy się wzajemnie miłowali.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 6, 'A na tym polega miłość, żebyśmy postępowali według jego przykazań. A przykazanie jest takie, jak słyszeliście od początku, że macie według niego postępować.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 7, 'Gdyż pojawiło się na świecie wielu zwodzicieli, którzy nie uznają, że Jezus Chrystus przyszedł w ciele. Taki jest zwodzicielem i antychrystem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 8, 'Miejcie się na baczności, żebyśmy nie stracili tego, nad czym pracowaliśmy, ale żebyśmy otrzymali pełną zapłatę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 9, 'Każdy, kto wykracza poza naukę Chrystusa, a nie pozostaje w niej, ten nie ma Boga. Kto pozostaje w nauce Chrystusa, ten ma i Ojca, i Syna.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 10, 'Jeśli ktoś przychodzi do was i nie przynosi tej nauki, nie przyjmujcie go do domu ani go nie pozdrawiajcie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 11, 'Kto bowiem takiego pozdrawia, staje się uczestnikiem jego złych uczynków.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 12, 'Mam wam wiele do napisania, ale nie chcę posługiwać się papierem i atramentem. Mam jednak nadzieję, że przybędę do was i porozmawiam z wami osobiście, aby nasza radość była pełna.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 13, 'Pozdrawiają cię dzieci twojej wybranej siostry. Amen.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 1, 'Starszy do umiłowanego Gajusa, którego miłuję w prawdzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 2, 'Umiłowany, pragnę przede wszystkim, aby ci się dobrze powodziło i abyś był zdrowy, tak jak dobrze się powodzi twojej duszy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 3, 'Uradowałem się bowiem bardzo, gdy przyszli bracia i dali świadectwo o prawdzie w tobie, jak postępujesz w prawdzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 4, 'Nie ma dla mnie większej radości od tej, gdy słyszę, że moje dzieci postępują w prawdzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 5, 'Umiłowany, wiernie wykonujesz wszystko, co robisz dla braci oraz dla obcych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 6, 'Dali oni świadectwo przed kościołem o twojej miłości. Dobrze też zrobisz, jeśli ich wyprawisz, jak przystoi przed Bogiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 7, 'Wyruszyli bowiem dla jego imienia, nie biorąc niczego od pogan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 8, 'Powinniśmy więc takich przyjmować, abyśmy się stali współpracownikami dla prawdy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 9, 'Napisałem do kościoła, lecz Diotrefes, który chce być pierwszym wśród nich, nie przyjmuje nas.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 10, 'Dlatego, jeśli przybędę, przypomnę jego uczynki, których się dopuszcza, gdy nas obmawia złośliwymi słowami. A nie poprzestając na tym, sam braci nie przyjmuje, a nawet zabrania tym, którzy chcą ich przyjąć, i wyrzuca ich z kościoła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 11, 'Umiłowany, nie naśladuj tego, co złe, lecz to, co dobre. Kto czyni dobrze, jest z Boga, kto zaś czyni źle, nie widział Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 12, 'Demetriuszowi wystawili dobre świadectwo wszyscy, nawet sama prawda. My również dajemy o nim świadectwo, a wiecie, że nasze świadectwo jest prawdziwe.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 13, 'Wiele miałem do napisania, ale nie chcę posługiwać się atramentem i piórem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 14, 'Mam bowiem nadzieję, że zobaczę cię wkrótce, a wtedy porozmawiamy osobiście. Pokój tobie. Pozdrawiają cię przyjaciele. Ty też pozdrów przyjaciół imiennie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 1, 'Juda, sługa Jezusa Chrystusa, a brat Jakuba, do uświęconych przez Boga Ojca, zachowanych w Jezusie Chrystusie i powołanych:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 2, 'Miłosierdzie, pokój i miłość niech się wam pomnożą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 3, 'Umiłowani, podejmując usilne starania, aby pisać wam o wspólnym zbawieniu, uznałem za konieczne napisać do was i zachęcić do walki o wiarę raz przekazaną świętym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 4, 'Wkradli się bowiem pewni ludzie, od dawna przeznaczeni na to potępienie, bezbożni, którzy łaskę naszego Boga zamieniają na rozpustę i wypierają się jedynego Pana Boga i naszego Pana Jezusa Chrystusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 5, 'Chcę więc wam przypomnieć, chociaż już kiedyś o tym wiedzieliście, że Pan, który wybawił lud z ziemi Egiptu, potem wytracił tych, którzy nie uwierzyli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 6, 'Także aniołów, którzy nie zachowali swego pierwotnego stanu, lecz opuścili własne mieszkanie, zatrzymał w wiecznych pętach w ciemnościach na sąd wielkiego dnia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 7, 'Tak samo Sodoma i Gomora oraz okoliczne miasta, które w podobny sposób jak i one oddały się nierządowi i podążały za cudzym ciałem, służą za przykład, ponosząc karę wiecznego ognia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 8, 'Podobnie ci ludzie rojący sny plugawią ciało, gardzą panowaniem i bluźnią przełożonym.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 9, 'Lecz archanioł Michał, rozprawiając z diabłem, spierał się o ciało Mojżesza, nie ośmielił się wypowiedzieć przeciwko niemu bluźnierczego oskarżenia, ale powiedział: Niech cię Pan zgromi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 10, 'Ci zaś bluźnią przeciwko temu, czego nie znają, a to, co znają w sposób naturalny, jak bezrozumne zwierzęta, w tym psują samych siebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 11, 'Biada im, bo poszli drogą Kaina, udali się za błędem Baalama dla zapłaty i zginęli w buncie Korego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 12, 'Oni są zakałami na waszych ucztach braterskich, którzy z wami bez bojaźni ucztują, pasąc samych siebie. Są to bezwodne chmury wiatrami unoszone; drzewa zwiędłe, bez owoców, dwukrotnie obumarłe i wykorzenione;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 13, 'Rozhukane fale morskie wypluwające swoją hańbę; błąkające się gwiazdy, dla których mroki ciemności zachowane są na wieki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 14, 'O nich też prorokował Henoch, siódmy po Adamie, mówiąc: Oto idzie Pan z tysiącami swoich świętych;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 15, 'Aby dokonać sądu nad wszystkimi i ukarać wszystkich bezbożników spośród nich za wszystkie ich bezbożne czyny, których się bezbożnie dopuścili, i za wszystkie ostre słowa, które wypowiadali przeciwko niemu bezbożni grzesznicy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 16, 'Oni to zawsze szemrają, narzekają, postępują według swoich pożądliwości. Ich usta wypowiadają zuchwałe słowa i schlebiają ludziom dla korzyści.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 17, 'Wy zaś, umiłowani, pamiętajcie słowa wcześniej wypowiedziane przez apostołów naszego Pana Jezusa Chrystusa;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 18, 'Gdy mówili do was, że w czasach ostatecznych pojawią się szydercy, postępujący według własnych bezbożnych pożądliwości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 19, 'Oni są tymi, którzy sami się odłączają, zmysłowi, niemający Ducha.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 20, 'Wy jednak, umiłowani, budując samych siebie na waszej najświętszej wierze, modląc się w Duchu Świętym;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 21, 'Zachowajcie samych siebie w miłości Boga, oczekując miłosierdzia naszego Pana Jezusa Chrystusa ku życiu wiecznemu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 22, 'I rozróżniając, nad jednymi zmiłujcie się;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 23, 'Innych zaś ratujcie przez strach, wyrywając ich z ognia, mając w nienawiści nawet szatę, która została skalana przez ciało.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 24, 'A temu, który może was ustrzec od upadku i z radością przedstawić jako nienagannych przed obliczem swojej chwały;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 25, 'Jedynemu mądremu Bogu, naszemu Zbawicielowi, niech będzie chwała i majestat, moc i władza, teraz i po wszystkie wieki. Amen.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 1, 'Objawienie Jezusa Chrystusa, które dał mu Bóg, aby ukazać swoim sługom to, co ma się stać wkrótce, a on to ukazał i posłał przez swojego anioła swemu słudze Janowi;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 2, 'Który poświadczył słowo Boże i świadectwo Jezusa Chrystusa, i wszystko, co widział.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 3, 'Błogosławiony ten, kto czyta, i ci, którzy słuchają słów tego proroctwa i zachowują to, co w nim jest napisane, bo czas jest bliski.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 4, 'Jan do siedmiu kościołów, które są w Azji. Łaska wam i pokój od tego, który jest i który był, i który ma przyjść, i od siedmiu Duchów, które są przed jego tronem;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 5, 'I od Jezusa Chrystusa, który jest wiernym świadkiem i pierworodnym z umarłych, i władcą królów ziemi. Temu, który nas umiłował i obmył nas z naszych grzechów swoją krwią;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 6, 'I uczynił nas królami i kapłanami dla Boga, swego Ojca, jemu chwała i moc na wieki wieków. Amen.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 7, 'Oto przychodzi z obłokami i ujrzy go wszelkie oko, także ci, którzy go przebili. I będą lamentować przed nim wszystkie plemiona ziemi. Tak, amen.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 8, 'Ja jestem Alfa i Omega, początek i koniec, mówi Pan, który jest i który był, i który ma przyjść, Wszechmogący.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 9, 'Ja, Jan, który też jestem waszym bratem i współuczestnikiem w ucisku i królestwie oraz w cierpliwości Jezusa Chrystusa, byłem na wyspie zwanej Patmos z powodu słowa Bożego i świadectwa Jezusa Chrystusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 10, 'Znalazłem się w zachwyceniu Ducha w dniu Pańskim i usłyszałem za sobą głos potężny jakby trąby;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 11, 'Który mówił: Ja jestem Alfa i Omega, pierwszy i ostatni. Co widzisz, napisz w księdze i poślij do siedmiu kościołów, które są w Azji: do Efezu, Smyrny, Pergamonu, Tiatyry, Sardes, Filadelfii i Laodycei.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 12, 'I odwróciłem się, aby zobaczyć, co to za głos mówił do mnie. A gdy się odwróciłem, zobaczyłem siedem złotych świeczników;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 13, 'A pośród tych siedmiu świeczników kogoś podobnego do Syna Człowieczego, ubranego w długą szatę i przepasanego na piersi złotym pasem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 14, 'Jego głowa i włosy były białe jak biała wełna, jak śnieg, a jego oczy jak płomień ognia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 15, 'Jego stopy podobne do mosiądzu, jakby w piecu rozżarzonego, a jego głos jak szum wielu wód.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 16, 'W swej prawej ręce miał siedem gwiazd, a z jego ust wychodził ostry miecz obosieczny. Jego oblicze było jak słońce, gdy świeci w pełni swej mocy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 17, 'Gdy go zobaczyłem, padłem do jego stóp jak martwy i położył na mnie swą prawą rękę, mówiąc mi: Nie bój się! Ja jestem pierwszy i ostatni;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 18, 'I żyjący, a byłem umarły. A oto żyję na wieki wieków i mam klucze piekła i śmierci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 19, 'Napisz to, co widziałeś, i co jest, i co ma się stać potem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 20, 'Tajemnica siedmiu gwiazd, które widziałeś w mojej prawej ręce i siedmiu złotych świeczników jest taka: siedem gwiazd to aniołowie siedmiu kościołów, a siedem świeczników, które widziałeś, to siedem kościołów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 1, 'Do anioła kościoła w Efezie napisz: To mówi ten, który trzyma siedem gwiazd w swojej prawej ręce, który się przechadza wśród siedmiu złotych świeczników:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 2, 'Znam twoje uczynki, twoją pracę i twoją cierpliwość i wiem, że nie możesz znieść złych i że poddałeś próbie tych, którzy nazywają się apostołami, a nimi nie są, i stwierdziłeś, że są kłamcami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 3, 'Wytrwałeś też i masz cierpliwość, i pracowałeś dla mego imienia, a nie ustałeś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 4, 'Ale mam nieco przeciw tobie – że porzuciłeś twoją pierwszą miłość.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 5, 'Pamiętaj więc, skąd spadłeś, i pokutuj, i spełniaj pierwsze uczynki. A jeśli nie, przyjdę do ciebie szybko i ruszę twój świecznik z jego miejsca, jeśli nie będziesz pokutował.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 6, 'Ale masz tę zaletę, że nienawidzisz uczynków nikolaitów, których i ja nienawidzę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 7, 'Kto ma uszy, niech słucha, co Duch mówi do kościołów: Temu, kto zwycięży, dam jeść z drzewa życia, które jest pośrodku raju Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 8, 'A do anioła kościoła w Smyrnie napisz: To mówi pierwszy i ostatni, który był umarły, a ożył:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 9, 'Znam twoje uczynki, ucisk i ubóstwo – lecz jesteś bogaty – i bluźnierstwo tych, którzy mówią, że są Żydami, a nimi nie są, ale są synagogą szatana.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 10, 'Nic się nie bój tego, co masz cierpieć. Oto diabeł wtrąci niektórych z was do więzienia, abyście byli doświadczeni, i będziecie znosić ucisk przez dziesięć dni. Bądź wierny aż do śmierci, a dam ci koronę życia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 11, 'Kto ma uszy, niech słucha, co Duch mówi do kościołów: Ten, kto zwycięży, nie dozna szkody od drugiej śmierci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 12, 'A do anioła kościoła w Pergamonie napisz: To mówi ten, który ma ostry miecz obosieczny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 13, 'Znam twoje uczynki i wiem, gdzie mieszkasz – tam, gdzie jest tron szatana – a trzymasz się mojego imienia i nie wyparłeś się mojej wiary nawet w dniach, gdy Antypas, mój wierny świadek, został zabity u was, tam, gdzie mieszka szatan.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 14, 'Ale mam nieco przeciwko tobie – że masz tam takich, którzy trzymają się nauki Balaama, który uczył Balaka, jak doprowadzić do upadku synów Izraela, żeby jedli ofiary składane bożkom i uprawiali nierząd.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 15, 'Podobnie masz i tych, którzy trzymają się nauki nikolaitów, czego nienawidzę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 16, 'Pokutuj! A jeśli nie, przyjdę do ciebie szybko i będę walczył z nimi mieczem moich ust.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 17, 'Kto ma uszy, niech słucha, co Duch mówi do kościołów: Temu, kto zwycięży, dam jeść z manny ukrytej i dam mu kamyk biały, a na kamyku wypisane nowe imię, którego nikt nie zna oprócz tego, który je otrzymuje.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 18, 'A do anioła kościoła w Tiatyrze napisz: To mówi Syn Boży, który ma oczy jak płomień ognia, a jego stopy podobne są do mosiądzu:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 19, 'Znam twoje uczynki i miłość, i służbę, i wiarę, i twoją cierpliwość, i twoje uczynki, i wiem, że ostatnich rzeczy jest więcej niż pierwszych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 20, 'Ale mam nieco przeciwko tobie – że kobiecie Jezabel, która nazywa siebie prorokinią, pozwalasz nauczać i zwodzić moje sługi, żeby uprawiali nierząd i jedli ofiary składane bożkom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 21, 'I dałem jej czas, aby pokutowała ze swego nierządu, ale nie pokutowała.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 22, 'Oto rzucę ją na łoże, a tych, którzy z nią cudzołożą, w ucisk wielki, jeśli nie będą pokutować ze swoich uczynków;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 23, 'A jej dzieci porażę śmiercią. I poznają wszystkie kościoły, że ja jestem tym, który bada nerki i serca. I oddam każdemu z was według waszych uczynków.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 24, 'Wam zaś i pozostałym w Tiatyrze, którzy nie mają tej nauki i którzy nie poznali – jak mówią – głębin szatana, oświadczam: Nie nałożę na was innego brzemienia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 25, 'Trzymajcie się jednak tego, co macie, aż przyjdę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 26, 'Temu, kto zwycięży i zachowa aż do końca moje uczynki, dam władzę nad narodami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 27, 'I będzie rządził nimi laską żelazną, jak naczynia gliniane będą skruszeni, jak i ja otrzymałem od mego Ojca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 28, 'I dam mu gwiazdę poranną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 29, 'Kto ma uszy, niech słucha, co Duch mówi do kościołów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 1, 'A do anioła kościoła w Sardes napisz: To mówi ten, który ma siedem Duchów Boga i siedem gwiazd: Znam twoje uczynki, że masz imię, które mówi, że żyjesz, ale jesteś martwy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 2, 'Bądź czujny i utwierdź, co pozostało, a co bliskie jest śmierci. Nie uznałem bowiem twoich uczynków za doskonałe przed Bogiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 3, 'Pamiętaj zatem, jak otrzymałeś i usłyszałeś, i strzeż tego, i pokutuj. Jeśli więc czuwać nie będziesz, przyjdę do ciebie jak złodziej, a nie będziesz wiedział, o której godzinie przyjdę do ciebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 4, 'Lecz masz kilka osób w Sardes, które nie splamiły swoich szat. Będą chodzić ze mną w białych szatach, bo są godni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 5, 'Kto zwycięży, będzie ubrany w białe szaty i nie wymażę jego imienia z księgi życia, lecz wyznam jego imię przed moim Ojcem i przed jego aniołami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 6, 'Kto ma uszy, niech słucha, co Duch mówi do kościołów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 7, 'A do anioła kościoła w Filadelfii napisz: To mówi Święty, Prawdziwy, ten, który ma klucz Dawida, ten, który otwiera i nikt nie zamknie, zamyka i nikt nie otworzy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 8, 'Znam twoje uczynki. Oto postawiłem przed tobą otwarte drzwi, których nikt nie może zamknąć, bo choć masz niewielką moc, jednak zachowałeś moje słowo i nie wyparłeś się mego imienia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 9, 'Oto dam ci ludzi z synagogi szatana, którzy mówią, że są Żydami, a nimi nie są, lecz kłamią. Oto sprawię, że przyjdą i pokłonią się przed twoimi nogami, i poznają, że ja ciebie umiłowałem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 10, 'Ponieważ zachowałeś słowo mojej cierpliwości, ja też zachowam cię od godziny próby, która przyjdzie na cały świat, aby doświadczyć mieszkańców ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 11, 'Oto przyjdę wkrótce, trzymaj to, co masz, aby nikt nie wziął twojej korony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 12, 'Tego, kto zwycięży, uczynię filarem w świątyni mojego Boga i już nie wyjdzie na zewnątrz. Napiszę też na nim imię mego Boga i nazwę miasta mego Boga, nowego Jeruzalem, które zstępuje z nieba od mego Boga, i moje nowe imię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 13, 'Kto ma uszy, niech słucha, co Duch mówi do kościołów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 14, 'A do anioła kościoła w Laodycei napisz: To mówi Amen, świadek wierny i prawdziwy, początek stworzenia Bożego:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 15, 'Znam twoje uczynki: nie jesteś ani zimny, ani gorący. Obyś był zimny albo gorący.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 16, 'A tak, ponieważ jesteś letni i ani zimny, ani gorący, wypluję cię z moich ust.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 17, 'Mówisz bowiem: Jestem bogaty i wzbogaciłem się, i niczego nie potrzebuję, a nie wiesz, że jesteś nędzny i pożałowania godny, biedny, ślepy i nagi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 18, 'Radzę ci kupić u mnie złota w ogniu wypróbowanego, abyś się wzbogacił, i białe szaty, abyś się ubrał i żeby nie ujawniła się hańba twojej nagości, a swoje oczy namaść maścią, abyś widział.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 19, 'Ja wszystkich, których miłuję, strofuję i karcę. Bądź więc gorliwy i pokutuj.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 20, 'Oto stoję u drzwi i pukam. Jeśli ktoś usłyszy mój głos i otworzy drzwi, wejdę do niego i spożyję z nim wieczerzę, a on ze mną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 21, 'Temu, kto zwycięży, dam zasiąść ze mną na moim tronie, jak i ja zwyciężyłem i zasiadłem z moim Ojcem na jego tronie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 22, 'Kto ma uszy, niech słucha, co Duch mówi do kościołów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 1, 'Potem zobaczyłem, a oto drzwi były otwarte w niebie, a pierwszy głos, który słyszałem, jakby trąby mówiącej do mnie, powiedział: Wstąp tutaj, a pokażę ci, co się ma stać potem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 2, 'I zaraz znalazłem się w zachwyceniu ducha. A oto w niebie stał tron, a na tronie ktoś siedział.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 3, 'A ten, który siedział, podobny był z wyglądu do kamienia jaspisowego i karneolowego, a dokoła tronu była tęcza podobna z wyglądu do szmaragdu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 4, 'Wokoło tronu były dwadzieścia cztery trony. Na tronach widziałem siedzących dwudziestu czterech starszych, ubranych w białe szaty, a na ich głowach złote korony.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 5, 'Z tronu wychodziły błyskawice, gromy i głosy, a przed tronem paliło się siedem ognistych pochodni, które są siedmioma Duchami Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 6, 'Przed tronem było też morze szklane podobne do kryształu. A pośrodku tronu i wokoło tronu były cztery stworzenia pełne oczu z przodu i z tyłu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 7, 'Pierwsze stworzenie podobne było do lwa, drugie stworzenie podobne do cielca, trzecie stworzenie miało twarz jakby ludzką, a czwarte stworzenie podobne było do lecącego orła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 8, 'Każde zaś z tych czterech stworzeń miało po sześć skrzydeł dokoła, a wewnątrz były pełne oczu. I bez odpoczynku, dniem i nocą mówią: Święty, święty, święty, Pan Bóg Wszechmogący, ten, który był i który jest, i który ma przyjść.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 9, 'A gdy stworzenia oddawały chwałę i cześć, i dziękczynienie zasiadającemu na tronie, żyjącemu na wieki wieków;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 10, 'Upadło dwudziestu czterech starszych przed zasiadającym na tronie i oddało pokłon żyjącemu na wieki wieków, i rzucało swoje korony przed tronem, mówiąc:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 11, 'Godzien jesteś, Panie, wziąć chwałę i cześć, i moc, ponieważ ty stworzyłeś wszystko i z twojej woli trwa i zostało stworzone.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 1, 'I zobaczyłem w prawej ręce zasiadającego na tronie księgę zapisaną wewnątrz i na zewnątrz, opieczętowaną siedmioma pieczęciami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 2, 'I zobaczyłem potężnego anioła wołającego donośnym głosem: Kto jest godny otworzyć księgę i złamać jej pieczęcie?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 3, 'Ale nikt w niebie ani na ziemi, ani pod ziemią nie mógł otworzyć księgi ani do niej zajrzeć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 4, 'I bardzo płakałem, że nie znalazł się nikt godny, aby otworzyć i czytać księgę, i do niej zajrzeć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 5, 'Wtedy jeden ze starszych powiedział do mnie: Nie płacz! Oto zwyciężył lew z pokolenia Judy, korzeń Dawida, aby otworzyć księgę i złamać siedem jej pieczęci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 6, 'I zobaczyłem, a oto między tronem i czterema stworzeniami, i między starszymi stał Baranek jakby zabity, który miał siedem rogów i siedmioro oczu, które są siedmioma Duchami Boga posłanymi na całą ziemię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 7, 'Wtedy on podszedł i wziął księgę z prawej ręki zasiadającego na tronie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 8, 'A gdy wziął księgę, cztery stworzenia i dwudziestu czterech starszych upadło przed Barankiem, a każdy z nich miał harfę i złote czasze pełne wonności, którymi są modlitwy świętych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 9, 'I śpiewali nową pieśń: Godzien jesteś wziąć księgę i otworzyć jej pieczęcie, ponieważ zostałeś zabity i odkupiłeś nas dla Boga przez swoją krew z każdego plemienia, języka, ludu i narodu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 10, 'I uczyniłeś nas dla naszego Boga królami i kapłanami, i będziemy królować na ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 11, 'Zobaczyłem też i usłyszałem głos wielu aniołów dokoła tronu i stworzeń, i starszych, a liczba ich wynosiła dziesięć tysięcy razy dziesięć tysięcy i tysiące tysięcy;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 12, 'Mówiących donośnym głosem: Godzien jest Baranek zabity wziąć moc i bogactwo, i mądrość, i siłę, i cześć, i chwałę, i błogosławieństwo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 13, 'A wszelkie stworzenie, które jest w niebie i na ziemi, i pod ziemią, i w morzu, i wszystko, co w nich jest, słyszałem, jak mówiło: Zasiadającemu na tronie i Barankowi błogosławieństwo i cześć, i chwała, i moc na wieki wieków.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 14, 'A cztery stworzenia mówiły: Amen. A dwudziestu czterech starszych upadło i oddało pokłon żyjącemu na wieki wieków.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 1, 'I zobaczyłem, gdy Baranek otworzył pierwszą z pieczęci, i usłyszałem pierwsze z czterech stworzeń mówiące jakby głosem gromu: Chodź i zobacz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 2, 'I zobaczyłem, a oto biały koń, ten zaś, który na nim siedział, miał łuk. I dano mu koronę, i wyruszył jako zwycięzca, żeby zwyciężać.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 3, 'A gdy otworzył drugą pieczęć, usłyszałem drugie stworzenie mówiące: Chodź i zobacz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 4, 'I wyszedł inny koń, rudy, a temu, który na nim siedział, pozwolono odebrać ziemi pokój, aby ludzie zabijali się nawzajem. I dano mu wielki miecz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 5, 'A gdy otworzył trzecią pieczęć, usłyszałem trzecie stworzenie mówiące: Chodź i zobacz. I zobaczyłem, a oto koń czarny, ten zaś, który na nim siedział, miał w swojej ręce wagę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 6, 'I usłyszałem głos pośród czterech stworzeń mówiący: Miara pszenicy za grosz i trzy miary jęczmienia za grosz. A nie krzywdź oliwy i wina.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 7, 'A gdy otworzył czwartą pieczęć, usłyszałem głos czwartego stworzenia mówiący: Chodź i zobacz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 8, 'I zobaczyłem, oto koń płowy, a temu, który na nim siedział, było na imię Śmierć, a Piekło szło za nim. I dano im władzę nad czwartą częścią ziemi, aby zabijali mieczem i głodem, i zarazą, i przez zwierzęta ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 9, 'A gdy otworzył piątą pieczęć, widziałem pod ołtarzem dusze zabitych z powodu słowa Bożego i świadectwa, które złożyli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 10, 'I wołały donośnym głosem: Jak długo jeszcze, Panie święty i prawdziwy, nie będziesz sądził i nie pomścisz naszej krwi na mieszkańcach ziemi?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 11, 'I dano każdemu z nich białą szatę, i powiedziano im, aby odpoczywali jeszcze przez krótki czas, aż dopełni się liczba ich współsług i braci, którzy mają zostać zabici jak i oni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 12, 'I zobaczyłem, gdy otworzył szóstą pieczęć, a oto nastąpiło wielkie trzęsienie ziemi i słońce stało się czarne jak włosiany wór, a księżyc stał się jak krew.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 13, 'Gwiazdy niebieskie spadły na ziemię, podobnie jak drzewo figowe zrzuca niedojrzałe figi, gdy potrząśnie nim gwałtowny wiatr.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 14, 'I niebo ustąpiło jak zwój zrolowany, a każda góra i wyspa ruszyły się ze swoich miejsc.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 15, 'A królowie ziemscy i możnowładcy, i bogacze, i wodzowie, i mocarze, i każdy niewolnik, i każdy wolny ukryli się w jaskiniach i skałach górskich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 16, 'I mówili do gór i skał: Padnijcie na nas i zakryjcie nas przed obliczem zasiadającego na tronie i przed gniewem Baranka;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 17, 'Bo nadszedł wielki dzień jego gniewu. I któż może się ostać?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 1, 'Potem zobaczyłem czterech aniołów stojących na czterech krańcach ziemi, trzymających cztery wiatry ziemi, aby wiatr nie wiał na ziemię ani na morze, ani na żadne drzewo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 2, 'I zobaczyłem innego anioła wstępującego od wschodu słońca, który miał pieczęć Boga żywego i zawołał donośnym głosem do czterech aniołów, którym pozwolono wyrządzać szkodę ziemi i morzu:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 3, 'Nie wyrządzajcie szkody ziemi ani morzu, ani drzewom, dopóki nie opieczętujemy sług naszego Boga na ich czołach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 4, 'I usłyszałem liczbę opieczętowanych: sto czterdzieści cztery tysiące opieczętowanych ze wszystkich pokoleń synów Izraela:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 5, 'Z pokolenia Judy dwanaście tysięcy opieczętowanych, z pokolenia Rubena dwanaście tysięcy opieczętowanych, z pokolenia Gada dwanaście tysięcy opieczętowanych;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 6, 'Z pokolenia Asera dwanaście tysięcy opieczętowanych, z pokolenia Neftalego dwanaście tysięcy opieczętowanych, z pokolenia Manassesa dwanaście tysięcy opieczętowanych;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 7, 'Z pokolenia Symeona dwanaście tysięcy opieczętowanych, z pokolenia Lewiego dwanaście tysięcy opieczętowanych, z pokolenia Issachara dwanaście tysięcy opieczętowanych;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 8, 'Z pokolenia Zabulona dwanaście tysięcy opieczętowanych, z pokolenia Józefa dwanaście tysięcy opieczętowanych, z pokolenia Beniamina dwanaście tysięcy opieczętowanych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 9, 'Potem zobaczyłem, a oto wielki tłum, którego nikt nie mógł policzyć, z każdego narodu, plemienia, ludu i języka, który stał przed tronem i przed Barankiem ubrani w białe szaty, a palmy w ich rękach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 10, 'I wołali donośnym głosem: Zbawienie należy do naszego Boga zasiadającego na tronie i do Baranka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 11, 'A wszyscy aniołowie stali dokoła tronu i starszych, i czterech stworzeń, i upadli przed tronem na twarze, i oddali pokłon Bogu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 12, 'Mówiąc: Amen. Błogosławieństwo i chwała, i mądrość, i dziękczynienie, i cześć, i moc, i siła naszemu Bogu na wieki wieków. Amen.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 13, 'A jeden ze starszych odezwał się do mnie tymi słowy: Kim są ci, którzy są ubrani w białe szaty i skąd przybyli?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 14, 'Odpowiedziałem mu: Panie, ty wiesz. I powiedział do mnie: To są ci, którzy przyszli z wielkiego ucisku i wyprali swoje szaty, i wybielili je we krwi Baranka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 15, 'Dlatego są przed tronem Boga i służą mu we dnie i w nocy w jego świątyni, a zasiadający na tronie osłoni ich sobą jak namiotem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 16, 'Nie zaznają już głodu ani pragnienia, nie porazi ich słońce ani żaden upał;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 17, 'Ponieważ Baranek, który jest pośrodku tronu, będzie ich pasł i poprowadzi ich do żywych źródeł wód, i otrze Bóg wszelką łzę z ich oczu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 1, 'A gdy otworzył siódmą pieczęć, nastała w niebie cisza na około pół godziny.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 2, 'I zobaczyłem siedmiu aniołów, którzy stoją przed Bogiem. I dano im siedem trąb.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 3, 'I przyszedł inny anioł, i stanął przy ołtarzu, mając złotą kadzielnicę. Dano mu wiele kadzideł, aby je ofiarował z modlitwami wszystkich świętych na złotym ołtarzu, który jest przed tronem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 4, 'I dym kadzideł z modlitwami świętych wzniósł się z ręki anioła przed Bogiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 5, 'Anioł zaś wziął kadzielnicę, napełnił ją ogniem z ołtarza i zrzucił na ziemię. I nastąpiły głosy i gromy, i błyskawice, i trzęsienie ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 6, 'A siedmiu aniołów, którzy mieli siedem trąb, przygotowało się, aby zatrąbić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 7, 'I zatrąbił pierwszy anioł, i powstały grad i ogień zmieszane z krwią, i zrzucono je na ziemię. I spłonęła trzecia część drzew, spłonęła też cała zielona trawa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 8, 'I zatrąbił drugi anioł, i jakby wielka góra płonąca ogniem została wrzucona w morze, i trzecia część morza zamieniła się w krew.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 9, 'I zginęła w morzu trzecia część żywych stworzeń, i trzecia część statków uległa zniszczeniu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 10, 'I zatrąbił trzeci anioł, i spadła z nieba wielka gwiazda, płonąca jak pochodnia, i spadła na trzecią część rzek i na źródła wód.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 11, 'A imię gwiazdy brzmi Piołun. I trzecia część wód zamieniła się w piołun, i wielu ludzi umarło od tych wód, bo stały się gorzkie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 12, 'I zatrąbił czwarty anioł, i rażona została trzecia część słońca i trzecia część księżyca, i trzecia część gwiazd, tak że zaćmiła się trzecia ich część i dzień przez jedną trzecią swoją część nie jaśniał, podobnie i noc.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 13, 'I zobaczyłem, i usłyszałem jednego anioła lecącego środkiem nieba, który mówił donośnym głosem: Biada, biada, biada mieszkańcom ziemi z powodu pozostałych głosów trąb trzech aniołów, którzy mają zatrąbić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 1, 'I zatrąbił piąty anioł, i zobaczyłem gwiazdę, która spadła z nieba na ziemię i dano jej klucz do studni otchłani.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 2, 'I otworzyła studnię otchłani, i wzbił się dym ze studni, jakby dym wielkiego pieca, a słońce i powietrze zaćmiły się od dymu studni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 3, 'A z dymu wyszła szarańcza na ziemię i dano jej moc, jaką mają skorpiony ziemskie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 4, 'I powiedziano jej, żeby nie wyrządzała szkody trawie na ziemi ani niczemu zielonemu, ani żadnemu drzewu, lecz tylko samym ludziom, którzy nie mają pieczęci Boga na czołach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 5, 'I dano jej nakaz, aby ich nie zabijały, lecz dręczyły przez pięć miesięcy. A ich cierpienia były jak cierpienia zadane przez skorpiona, gdy ukąsi człowieka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 6, 'I w owe dni ludzie będą szukać śmierci, lecz jej nie znajdą, i będą chcieli umrzeć, ale śmierć od nich ucieknie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 7, 'A szarańcza z wyglądu była podobna do koni przygotowanych do boju, na ich głowach jakby korony podobne do złota, a ich twarze jakby twarze ludzkie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 8, 'I miały włosy jakby włosy kobiece, a ich zęby były jak u lwów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 9, 'Miały też pancerze jakby z żelaza, a szum ich skrzydeł jakby odgłos wielokonnych rydwanów pędzących do boju.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 10, 'I miały ogony podobne do skorpionów, a żądła były w ich ogonach. I dano im moc wyrządzania ludziom szkody przez pięć miesięcy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 11, 'Mają nad sobą króla, anioła otchłani, którego imię po hebrajsku brzmi Abaddon, a po grecku Apollyon.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 12, 'Jedno „biada” minęło, a oto jeszcze dwa „biada” potem nadchodzą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 13, 'I zatrąbił szósty anioł, i usłyszałem jeden głos od czterech rogów złotego ołtarza, który jest przed Bogiem;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 14, 'Mówiący do szóstego anioła, który miał trąbę: Uwolnij czterech aniołów związanych nad wielką rzeką Eufrat.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 15, 'I zostali uwolnieni czterej aniołowie, przygotowani na godzinę, na dzień, na miesiąc i na rok, aby zabić trzecią część ludzi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 16, 'A liczba wojsk konnych wynosiła dwieście milionów, bo usłyszałem ich liczbę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 17, 'I tak zobaczyłem w widzeniu konie i tych, którzy na nich siedzieli, mających pancerze barwy ognia, hiacyntu i siarki. A głowy koni były jak głowy lwów, a z ich pysków wychodził ogień, dym i siarka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 18, 'A od tych trzech plag została zabita trzecia część ludzi, od ognia, dymu i siarki, które wychodziły z ich pysków.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 19, 'Moc bowiem tych koni jest w ich pyskach i w ogonach, bo ich ogony są podobne do węży, które mają głowy i nimi wyrządzają szkody.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 20, 'A pozostali ludzie, którzy nie zostali zabici przez te plagi, nie pokutowali od uczynków swoich rąk, tak by nie oddawać pokłonu demonom i bożkom złotym, srebrnym, miedzianym, kamiennym i drewnianym, które nie mogą ani widzieć, ani słyszeć, ani chodzić.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 21, 'I nie pokutowali od swoich morderstw ani od swoich czarów, ani od swego nierządu, ani od swoich kradzieży.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 1, 'I zobaczyłem innego potężnego anioła, zstępującego z nieba, ubranego w obłok, nad jego głową była tęcza, jego twarz jak słońce, a jego nogi jak słupy ognia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 2, 'W swojej ręce miał otwartą książeczkę. I postawił prawą nogę na morzu, a lewą na ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 3, 'I zawołał donośnym głosem, tak jak ryczy lew. A gdy zawołał, siedem gromów odezwało się swoimi głosami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 4, 'A gdy siedem gromów przemówiło swoimi głosami, zabrałem się do pisania, lecz usłyszałem głos z nieba, który mówił do mnie: Zapieczętuj to, co mówiło siedem gromów, i nie pisz tego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 5, 'A anioł, którego widziałem stojącego na morzu i na ziemi, podniósł swoją rękę ku niebu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 6, 'I przysiągł na tego, który żyje na wieki wieków, który stworzył niebo i to, co w nim jest, i ziemię i to, co na niej, i morze, i to, co w nim, że czasu już nie będzie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 7, 'Lecz w dniach głosu siódmego anioła, gdy zacznie trąbić, dokona się tajemnica Boga, jak to oznajmił swoim sługom, prorokom.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 8, 'A głos, który usłyszałem z nieba, znowu przemówił do mnie: Idź, weź tę otwartą książeczkę, która jest w ręce anioła stojącego na morzu i na ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 9, 'Podszedłem więc do anioła i powiedziałem mu: Daj mi tę książeczkę. I powiedział do mnie: Weź ją i zjedz, a spowoduje gorycz w twoim brzuchu, lecz w twoich ustach będzie słodka jak miód.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 10, 'I wziąłem książeczkę z ręki anioła i zjadłem ją, a była w moich ustach słodka jak miód. Lecz gdy ją zjadłem, mój brzuch napełnił się goryczą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 11, 'I powiedział do mnie: Musisz znowu prorokować przed wieloma ludami, narodami, językami i królami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 1, 'I dano mi trzcinę podobną do pręta. I stanął anioł, mówiąc: Wstań i zmierz świątynię Boga i ołtarz oraz tych, którzy w niej oddają pokłon.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 2, 'Lecz dziedziniec zewnętrzny świątyni wyłącz i nie mierz go, gdyż został dany poganom. I będą deptać święte miasto przez czterdzieści dwa miesiące.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 3, 'I dam władzę dwóm moim świadkom, którzy będą prorokować przez tysiąc dwieście sześćdziesiąt dni ubrani w wory.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 4, 'Oni są dwoma drzewami oliwnymi i dwoma świecznikami, które stoją przed Bogiem ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 5, 'A gdy ktoś chce ich skrzywdzić, ogień wychodzi z ich ust i pożera ich wrogów. Jeśli więc ktoś chciałby ich skrzywdzić, w ten sposób musi być zabity.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 6, 'Oni mają władzę zamknąć niebo, aby nie padał deszcz za dni ich prorokowania, i mają władzę nad wodami, aby je zamieniać w krew i porazić ziemię wszelkimi plagami, ilekroć zechcą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 7, 'A gdy dopełnią swojego świadectwa, bestia, która wychodzi z otchłani, stoczy z nimi walkę i zwycięży ich, i zabije ich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 8, 'A ich zwłoki będą leżeć na ulicy wielkiego miasta, które duchowo nazywa się Sodomą i Egiptem, gdzie też nasz Pan został ukrzyżowany.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 9, 'I wielu spośród ludów, plemion, języków i narodów będzie patrzeć na ich zwłoki przez trzy i pół dnia i nie pozwolą złożyć ich zwłok do grobu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 10, 'A mieszkańcy ziemi będą się cieszyć i radować z ich powodu. I będą sobie nawzajem posyłać podarunki, bo ci dwaj prorocy dręczyli mieszkańców ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 11, 'A po trzech i pół dnia duch życia od Boga wszedł w nich i stanęli na nogach, a wielki strach padł na tych, którzy na nich patrzyli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 12, 'Potem usłyszeli donośny głos z nieba mówiący: Wstąp tutaj. I wstąpili do nieba w obłoku, a ich nieprzyjaciele patrzyli na nich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 13, 'W tej godzinie nastąpiło wielkie trzęsienie ziemi i zawaliła się dziesiąta część miasta, i zginęło w trzęsieniu ziemi siedem tysięcy ludzi, a pozostali przerazili się i oddali chwałę Bogu nieba.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 14, 'Minęło drugie „biada”, a oto nadchodzi szybko trzecie „biada”.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 15, 'I zatrąbił siódmy anioł, i odezwały się donośne głosy w niebie mówiące: Królestwa świata stały się królestwami naszego Pana i jego Chrystusa i będzie królować na wieki wieków.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 16, 'A dwudziestu czterech starszych, którzy siedzą przed Bogiem na swoich tronach, upadło na twarze i oddało Bogu pokłon;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 17, 'Mówiąc: Dziękujemy tobie, Panie Boże Wszechmogący, który jesteś i który byłeś, i który masz przyjść, że wziąłeś swą potężną moc i objąłeś królestwo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 18, 'I rozgniewały się narody, i nadszedł twój gniew i czas osądzenia umarłych, i oddania zapłaty twoim sługom prorokom i świętym oraz tym, którzy się boją twego imienia, małym i wielkim, i zniszczenia tych, którzy niszczą ziemię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 19, 'Potem otworzyła się świątynia Boga w niebie i arka jego przymierza ukazała się w jego świątyni, i nastąpiły błyskawice, głosy, grzmoty, trzęsienia ziemi i wielki grad.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 1, 'I ukazał się wielki cud na niebie: Kobieta ubrana w słońce i księżyc pod jej nogami, a na jej głowie korona z dwunastu gwiazd.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 2, 'A była brzemienna i krzyczała w bólach porodowych i w mękach rodzenia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 3, 'I ukazał się inny cud na niebie: Oto wielki rudy smok mający siedem głów i dziesięć rogów, a na jego głowach siedem koron.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 4, 'A jego ogon wlókł trzecią część gwiazd nieba i zrzucił je na ziemię. I stanął smok przed kobietą, która właśnie miała urodzić, aby gdy tylko urodzi, pożreć jej dziecko.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 5, 'I urodziła syna – mężczyznę, który będzie rządził wszystkimi narodami laską żelazną. I porwane zostało jej dziecko do Boga i do jego tronu;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 6, 'A kobieta uciekła na pustynię, gdzie ma miejsce przygotowane przez Boga, aby ją tam żywiono przez tysiąc dwieście sześćdziesiąt dni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 7, 'I nastąpiła walka w niebie. Michał i jego aniołowie walczyli ze smokiem. I walczył smok i jego aniołowie;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 8, 'Ale nie zwyciężyli i nie było już dla nich miejsca w niebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 9, 'I zrzucony został wielki smok, wąż starodawny, zwany diabłem i szatanem, zwodzący cały świat. Został zrzucony na ziemię, z nim też zrzuceni zostali jego aniołowie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 10, 'I usłyszałem donośny głos mówiący w niebie: Teraz nastało zbawienie, moc i królestwo naszego Boga, i władza jego Chrystusa, bo został zrzucony oskarżyciel naszych braci, który dniem i nocą oskarżał ich przed naszym Bogiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 11, 'Ale oni zwyciężyli go przez krew Baranka i przez słowo swego świadectwa i nie umiłowali swojego życia – aż do śmierci.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 12, 'Dlatego radujcie się niebiosa i wy, ich mieszkańcy. Biada mieszkańcom ziemi i morza, bo zszedł do was diabeł pałający wielkim gniewem, gdyż wie, że ma niewiele czasu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 13, 'A gdy smok zobaczył, że został zrzucony na ziemię, zaczął prześladować kobietę, która urodziła mężczyznę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 14, 'I dano kobiecie dwa skrzydła wielkiego orła, aby poleciała na pustynię, na swoje miejsce, gdzie jest żywiona przez czas i czasy, i połowę czasu, z dala od węża.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 15, 'I wyrzucił wąż ze swojej paszczy za kobietą wodę jak rzekę, aby ją rzeka porwała.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 16, 'Lecz ziemia przyszła kobiecie z pomocą i otworzyła ziemia swą gardziel, i pochłonęła rzekę, którą smok wyrzucił ze swojej paszczy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 17, 'I rozgniewał się smok na kobietę, i odszedł, aby walczyć z resztą jej potomstwa, z tymi, którzy zachowują przykazania Boga i mają świadectwo Jezusa Chrystusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 1, 'I stanąłem na piasku morza. I zobaczyłem bestię wychodzącą z morza, mającą siedem głów i dziesięć rogów, a na jej rogach było dziesięć koron, a na jej głowach imię bluźnierstwa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 2, 'A bestia, którą widziałem, podobna była do pantery, a jej łapy jak u niedźwiedzia, a jej paszcza jak paszcza lwa. I dał jej smok swoją moc, swój tron i wielką władzę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 3, 'I zobaczyłem jedną z jej głów jakby śmiertelnie zranioną, lecz jej śmiertelna rana została uleczona. I cała ziemia zdziwiła się, i poszła za bestią.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 4, 'I oddali pokłon smokowi, który dał władzę bestii. Oddali też pokłon bestii, mówiąc: Któż jest podobny do bestii? Któż z nią może walczyć?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 5, 'I dano jej paszczę mówiącą rzeczy wielkie i bluźnierstwa. Dano jej też moc, aby działała przez czterdzieści dwa miesiące.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 6, 'I otworzyła swoją paszczę, by bluźnić przeciwko Bogu, by bluźnić jego imieniu, jego przybytkowi i tym, którzy mieszkają w niebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 7, 'Pozwolono jej też walczyć ze świętymi i zwyciężać ich. I dano jej władzę nad każdym plemieniem, językiem i narodem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 8, 'Wszyscy mieszkańcy ziemi oddadzą jej pokłon, ci, których imiona nie są zapisane w księdze życia Baranka zabitego od założenia świata.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 9, 'Jeśli ktoś ma uszy, niech słucha!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 10, 'Jeśli ktoś do niewoli bierze, do niewoli pójdzie, jeśli ktoś zabija mieczem, mieczem musi zostać zabity. Tu jest cierpliwość i wiara świętych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 11, 'Potem zobaczyłem inną bestię wychodzącą z ziemi, a miała dwa rogi podobne do Baranka, ale mówiła jak smok.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 12, 'I całą władzę pierwszej bestii sprawuje na jej oczach, i sprawia, że ziemia i jej mieszkańcy oddają pokłon pierwszej bestii, której śmiertelna rana została wyleczona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 13, 'I czyni wielkie cuda, sprawiając, że nawet ogień zstępuje z nieba na ziemię na oczach ludzi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 14, 'I zwodzi mieszkańców ziemi przez cuda, które jej pozwolono czynić przed bestią, mówiąc mieszkańcom ziemi, aby sporządzili wizerunek bestii, która miała ranę od miecza, ale ożyła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 15, 'I pozwolono jej tchnąć ducha w wizerunek bestii, tak żeby przemówił wizerunek bestii i sprawił, że ci, którzy nie oddali pokłonu wizerunkowi bestii, zostali zabici.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 16, 'I sprawia, aby wszyscy, mali i wielcy, bogaci i biedni, wolni i niewolnicy, przyjęli znamię na prawą rękę lub na czoło;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 17, 'I aby nikt nie mógł kupić ani sprzedać, tylko ten, kto ma znamię, imię bestii lub liczbę jej imienia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 18, 'Tu jest mądrość. Kto ma rozum, niech obliczy liczbę bestii, gdyż jest to liczba człowieka. A liczba jej: sześćset sześćdziesiąt sześć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 1, 'I zobaczyłem, a oto Baranek stał na górze Syjon, a z nim sto czterdzieści cztery tysiące tych, którzy mieli imię jego Ojca wypisane na czołach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 2, 'I usłyszałem z nieba głos jakby głos wielu wód i jakby głos wielkiego gromu. I słyszałem głos harfiarzy grających na swoich harfach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 3, 'I śpiewali jakby nową pieśń przed tronem i przed czterema stworzeniami, i przed starszymi. A nikt się tej pieśni nie mógł nauczyć oprócz stu czterdziestu czterech tysięcy, którzy zostali wykupieni z ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 4, 'Są to ci, którzy nie skalali się z kobietami, są bowiem dziewiczy. To ci, którzy podążają za Barankiem, dokądkolwiek idzie. Oni zostali wykupieni spośród ludzi, aby byli pierwocinami dla Boga i dla Baranka;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 5, 'A w ich ustach nie znaleziono podstępu. Są bowiem bez skazy przed tronem Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 6, 'I zobaczyłem innego anioła lecącego środkiem nieba, który miał ewangelię wieczną, aby ją zwiastować mieszkańcom ziemi, wszystkim narodom, plemionom, językom i ludom;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 7, 'Mówiącego donośnym głosem: Bójcie się Boga i oddajcie mu chwałę, bo przyszła godzina jego sądu. Oddajcie pokłon temu, który stworzył niebo i ziemię, morze i źródła wód.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 8, 'A za nim szedł inny anioł i mówił: Upadł, upadł Babilon, wielkie miasto, bo winem gniewu swego nierządu napoiło wszystkie narody.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 9, 'A po nich przyszedł trzeci anioł i donośnym głosem mówił: Jeśli ktoś odda pokłon bestii i jej wizerunkowi i przyjmie znamię na czoło lub na rękę;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 10, 'Ten również będzie pił z wina zapalczywości Boga, nierozcieńczonego, nalanego do kielicha jego gniewu, i będzie męczony w ogniu i siarce przed świętymi aniołami i przed Barankiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 11, 'A dym ich męki wznosi się na wieki wieków i nie zaznają odpoczynku we dnie i w nocy ci, którzy oddają pokłon bestii i jej wizerunkowi, i ten, kto przyjmuje znamię jej imienia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 12, 'Tu jest cierpliwość świętych, tu są ci, którzy zachowują przykazania Boga i wiarę Jezusa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 13, 'I usłyszałem głos z nieba, który mówił do mnie: Napisz: Błogosławieni są umarli, którzy odtąd umierają w Panu, tak, mówi Duch, aby odpoczęli od swoich prac, a ich uczynki idą za nimi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 14, 'I zobaczyłem, a oto biały obłok, a na obłoku siedział ktoś podobny do Syna Człowieczego, który miał na głowie złotą koronę, a w ręku ostry sierp.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 15, 'A inny anioł wyszedł ze świątyni, wołając donośnym głosem do tego, który siedział na obłoku: Zapuść swój sierp i żnij, gdyż nadeszła dla ciebie pora, abyś żął, bo dojrzało żniwo ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 16, 'Wtedy rzucił ten, który siedział na obłoku, swój sierp na ziemię i ziemia została zżęta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 17, 'I inny anioł wyszedł ze świątyni, która jest w niebie, mając także ostry sierp.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 18, 'Potem od ołtarza wyszedł inny anioł, który miał władzę nad ogniem i zawołał donośnym głosem do tego, który miał ostry sierp: Zapuść swój ostry sierp i zbierz grona winorośli ziemi, bo dojrzały jej winne grona.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 19, 'I rzucił anioł swój ostry sierp na ziemię, i zebrał grona winorośli ziemi, i wrzucił je do wielkiej tłoczni gniewu Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 20, 'I udeptano tłocznię poza miastem, a z tłoczni wypłynęła krew aż po wędzidła koni, na tysiąc sześćset stadiów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 1, 'Potem zobaczyłem inny znak na niebie, wielki i zadziwiający: siedmiu aniołów, którzy mieli siedem plag ostatecznych, bo przez nie dopełnił się gniew Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 2, 'I zobaczyłem jakby morze szklane zmieszane z ogniem i tych, którzy odnieśli zwycięstwo nad bestią, nad jej wizerunkiem, nad jej znamieniem i nad liczbą jej imienia, stojących nad szklanym morzem, mających harfy Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 3, 'I śpiewali pieśń Mojżesza, sługi Boga, i pieśń Baranka: Wielkie i zadziwiające są twoje dzieła, Panie Boże Wszechmogący. Sprawiedliwe i prawdziwe są twoje drogi, o Królu świętych;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 4, 'Któż by się nie bał ciebie, Panie, i nie uwielbił twego imienia? Bo ty jedynie jesteś święty, bo wszystkie narody przyjdą i oddadzą tobie pokłon, bo objawiły się twoje wyroki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 5, 'Potem zobaczyłem, a oto została otwarta świątynia Przybytku Świadectwa w niebie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 6, 'I wyszło ze świątyni siedmiu aniołów mających siedem plag, ubranych w czysty, lśniący len i przepasanych na piersi złotymi pasami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 7, 'A jedno z czterech stworzeń dało siedmiu aniołom siedem złotych czasz pełnych gniewu Boga, który żyje na wieki wieków.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 8, 'I napełniła się świątynia dymem od chwały Boga i jego mocy. I nikt nie mógł wejść do świątyni, dopóki nie dopełniło się siedem plag siedmiu aniołów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 1, 'I usłyszałem donośny głos ze świątyni mówiący do siedmiu aniołów: Idźcie i wylejcie siedem czasz gniewu Boga na ziemię.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 2, 'I poszedł pierwszy, i wylał swoją czaszę na ziemię. I pojawiły się bolesne i złośliwe wrzody na ludziach, którzy mieli znamię bestii, i na tych, którzy oddali pokłon jej wizerunkowi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 3, 'A drugi anioł wylał swoją czaszę na morze i stało się ono jak krew zmarłego. I każda dusza żywa umarła w morzu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 4, 'A trzeci anioł wylał swoją czaszę na rzeki i źródła wód i przemieniły się w krew.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 5, 'I usłyszałem anioła wód mówiącego: Sprawiedliwy jesteś, Panie, który jesteś i który byłeś, i święty, że tak osądziłeś.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 6, 'Ponieważ wylali krew świętych i proroków, dałeś im również krew do picia, bo na to zasłużyli.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 7, 'I usłyszałem, jak inny mówił od ołtarza: Tak, Panie Boże Wszechmogący, prawdziwe i sprawiedliwe są twoje wyroki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 8, 'A czwarty anioł wylał swoją czaszę na słońce i pozwolono mu przypalać ludzi ogniem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 9, 'I ludzie zostali popaleni wielkim żarem, i bluźnili imieniu Boga, który ma władzę nad tymi plagami, a nie pokutowali, aby oddać mu chwałę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 10, 'A piąty anioł wylał swoją czaszę na tron bestii i jej królestwo pogrążyło się w ciemności, a ludzie gryźli z bólu języki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 11, 'I bluźnili Bogu nieba z powodu swoich bólów i wrzodów, lecz nie pokutowali ze swoich czynów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 12, 'A szósty anioł wylał swoją czaszę na wielką rzekę Eufrat. I wyschła jej woda, aby została przygotowana droga dla królów ze Wschodu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 13, 'I zobaczyłem trzy duchy nieczyste jakby żaby, które wychodziły z paszczy smoka i z paszczy bestii, i z ust fałszywego proroka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 14, 'A są to duchy demonów, które czynią cuda i wychodzą do królów ziemi i na cały świat, aby ich zgromadzić na wojnę w wielki dzień Boga Wszechmogącego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 15, 'Oto przychodzę jak złodziej. Błogosławiony, kto czuwa i strzeże swoich szat, aby nie chodził nago i aby nie widziano jego hańby.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 16, 'I zgromadził ich na miejsce zwane po hebrajsku Armageddon.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 17, 'A siódmy anioł wylał swoją czaszę w powietrze. I ze świątyni nieba, od tronu rozległ się donośny głos, który powiedział: Stało się!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 18, 'I nastąpiły głosy i gromy, i błyskawice, i nastało wielkie trzęsienie ziemi, jakiego nie było, odkąd człowiek jest na ziemi, tak potężne było to trzęsienie ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 19, 'A wielkie miasto rozpadło się na trzy części i runęły miasta narodów. I został wspomniany przed Bogiem wielki Babilon, aby dać mu kielich wina zapalczywości swego gniewu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 20, 'Pierzchły wszystkie wyspy i gór już nie znaleziono.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 21, 'I spadł z nieba na ludzi wielki grad o wadze około jednego talentu. A ludzie bluźnili Bogu z powodu plagi gradu, bo plaga ta była bardzo wielka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 1, 'I przyszedł jeden z siedmiu aniołów, którzy mieli siedem czasz, i odezwał się do mnie, mówiąc mi: Chodź, pokażę ci sąd nad wielką nierządnicą, która siedzi nad wieloma wodami;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 2, 'Z którą nierząd uprawiali królowie ziemi, a mieszkańcy ziemi upili się winem jej nierządu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 3, 'I zaniósł mnie w duchu na pustynię. I zobaczyłem kobietę siedzącą na szkarłatnej bestii pełnej imion bluźnierstwa, mającej siedem głów i dziesięć rogów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 4, 'A kobieta była ubrana w purpurę i szkarłat i przyozdobiona złotem, drogimi kamieniami i perłami. Miała w swej ręce złoty kielich pełen obrzydliwości i nieczystości swego nierządu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 5, 'A na jej czole wypisane było imię: Tajemnica, wielki Babilon, matka nierządnic i obrzydliwości ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 6, 'I zobaczyłem kobietę pijaną krwią świętych i krwią męczenników Jezusa. A gdy ją zobaczyłem, zdumiałem się bardzo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 7, 'I powiedział do mnie anioł: Czemu się zdumiałeś? Ja ci wyjaśnię tajemnicę kobiety i bestii, która ją nosi, a która ma siedem głów i dziesięć rogów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 8, 'Bestia, którą widziałeś, była, a nie ma jej i ma wyjść z otchłani, i iść na zatracenie. I zdziwią się mieszkańcy ziemi, których imiona nie są zapisane w księdze życia od założenia świata, widząc bestię, która była i nie ma jej, a jednak jest.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 9, 'Tu jest rozum, który ma mądrość. Siedem głów to siedem gór, na których siedzi kobieta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 10, 'I królów jest siedmiu – pięciu upadło, jeden jest, inny jeszcze nie przyszedł, a gdy przyjdzie, ma pozostać na krótko.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 11, 'A bestia, która była, a nie ma jej, ona sama jest ósmym, a jest spośród siedmiu i idzie na zatracenie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 12, 'A dziesięć rogów, które widziałeś, to dziesięciu królów, którzy jeszcze nie objęli królestwa, ale wezmą władzę jak królowie na jedną godzinę wraz z bestią.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 13, 'Mają oni jeden zamysł, a swoją moc i władzę oddadzą bestii.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 14, 'Oni będą walczyć z Barankiem, a Baranek ich zwycięży, bo jest Panem panów i Królem królów, a ci, którzy są z nim, są powołani, wybrani i wierni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 15, 'I powiedział do mnie: Wody, które widziałeś, nad którymi siedzi nierządnica, to ludy, tłumy, narody i języki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 16, 'A dziesięć rogów, które widziałeś na bestii – oni znienawidzą nierządnicę i sprawią, że będzie spustoszona i naga i będą jeść jej ciało, i spalą ją w ogniu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 17, 'Bóg bowiem włożył im do serc, aby wykonali jego wolę, i to jednomyślnie, i oddali swoje królestwo bestii, aż wypełnią się słowa Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 18, 'A kobieta, którą zobaczyłeś, to wielkie miasto, które króluje nad królami ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 1, 'Potem zobaczyłem innego anioła zstępującego z nieba, mającego wielką władzę, i zajaśniała ziemia od jego chwały.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 2, 'I zawołał potężnie donośnym głosem: Upadł, upadł wielki Babilon, metropolia. Stała się mieszkaniem demonów, schronieniem wszelkiego ducha nieczystego i schronieniem wszelkiego ptactwa nieczystego i znienawidzonego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 3, 'Gdyż wszystkie narody piły wino zapalczywości jej nierządu, a królowie ziemi uprawiali z nią nierząd i kupcy ziemi wzbogacili się na jej wielkim przepychu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 4, 'I usłyszałem inny głos z nieba, który mówił: Wyjdźcie z niej, mój ludu, abyście nie byli uczestnikami jej grzechów i aby was nie dotknęły jej plagi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 5, 'Jej grzechy bowiem dosięgły aż do nieba i wspomniał Bóg na jej nieprawości.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 6, 'Odpłaćcie jej, jak i ona odpłacała wam, i oddajcie jej w dwójnasób według jej uczynków. Do kielicha, w który wam nalewała, nalejcie jej w dwójnasób.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 7, 'Ile sama się rozsławiła i pławiła się w przepychu, tyle zadajcie jej udręki i smutku, bo mówi w swoim sercu: Zasiadam jak królowa, nie jestem wdową i nie zaznam smutku.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 8, 'Dlatego w jednym dniu przyjdą na nią jej plagi, śmierć, smutek i głód i zostanie spalona ogniem, bo mocny jest Pan Bóg, który ją osądzi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 9, 'I będą płakać, i lamentować nad nią królowie ziemi, którzy uprawiali z nią nierząd i pławili się w przepychu, gdy zobaczą dym jej pożaru.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 10, 'Stojąc z daleka z powodu strachu przed jej męką, powiedzą: Biada, biada tobie, wielkie miasto, Babilonie, metropolio potężna, bo w jednej godzinie nadszedł twój sąd!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 11, 'A kupcy ziemi będą płakać i lamentować nad nią, bo już nikt nie będzie kupował ich towaru;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 12, 'Towaru złota, srebra, drogich kamieni, pereł, bisioru, purpury, jedwabiu, szkarłatu, wszelkiego drewna tujowego, wszelkich przedmiotów z kości słoniowej, wszelkich przedmiotów z najkosztowniejszego drewna, brązu, żelaza i marmuru;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 13, 'Cynamonu i wonności, olejku i kadzidła, wina i oliwy, najczystszej mąki i pszenicy, bydła i owiec, koni i wozów, niewolników i dusz ludzkich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 14, 'Owoce, których pożądała twoja dusza, opuściły ciebie i wszystko, co tłuste i świetne, opuściło ciebie i już nigdy tego nie znajdziesz.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 15, 'Ci, którzy tym handlowali i wzbogacili się na niej, będą stać z daleka z powodu strachu przed jej męką, płacząc i lamentując w słowach:');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 16, 'Biada, biada tobie, wielkie miasto, ubrane w bisior, purpurę i szkarłat, przyozdobione złotem, drogimi kamieniami i perłami;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 17, 'Bo w jednej godzinie przepadło tak wielkie bogactwo; a każdy sternik i całe rzesze pływających na okrętach, i marynarze, i wszyscy, którzy pracują na morzu, stanęli z daleka;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 18, 'I wołali, widząc dym jego pożaru: Które miasto jest podobne do tego wielkiego miasta?');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 19, 'I sypali proch na swoje głowy, i wołali, płacząc i lamentując: Biada, biada tobie, wielkie miasto, w którym, dzięki jego dostatkowi, wzbogacili się wszyscy, którzy mieli statki na morzu, bo w jednej godzinie zostało spustoszone.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 20, 'Raduj się nad nim niebo oraz święci apostołowie i prorocy, bo Bóg pomścił na nim waszą krzywdę.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 21, 'A jeden potężny anioł podniósł kamień, wielki jak kamień młyński, i wrzucił go do morza, mówiąc: Tak gwałtownie będzie zrzucony Babilon, wielkie miasto, i już go nie znajdą.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 22, 'I głosu harfiarzy, śpiewaków, flecistów i trębaczy nie będzie już słychać w tobie, i żaden rzemieślnik jakiegokolwiek rzemiosła już się nie znajdzie w tobie, i odgłosu kamienia młyńskiego już się w tobie nie usłyszy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 23, 'I światło lampy nie zabłyśnie już w tobie, i głosu oblubieńca i oblubienicy nie będzie już słychać w tobie, bo twoi kupcy byli możnowładcami ziemi, bo twoimi czarami zostały zwiedzione wszystkie narody.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 24, 'W nim też znaleziono krew proroków i świętych, i wszystkich zabitych na ziemi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 1, 'Potem usłyszałem donośny głos wielkiego tłumu ludzi w niebie, który mówił: Alleluja! Zbawienie i chwała, i cześć, i moc Panu, naszemu Bogu.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 2, 'Bo jego wyroki są prawdziwe i sprawiedliwe, gdyż osądził wielką nierządnicę, która skaziła ziemię swoim nierządem, i pomścił krew swoich sług z jej ręki.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 3, 'I powtórnie powiedzieli: Alleluja! A jej dym wznosi się na wieki wieków.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 4, 'I upadło dwudziestu czterech starszych i cztery stworzenia, i oddali pokłon Bogu zasiadającemu na tronie, mówiąc: Amen! Alleluja!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 5, 'A od tronu rozległ się głos, który mówił: Chwalcie naszego Boga wszyscy jego słudzy i ci, którzy się go boicie, i mali, i wielcy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 6, 'I usłyszałem jakby głos wielkiego tłumu i jakby głos wielu wód, i jakby głos potężnych gromów mówiących: Alleluja, bo objął królestwo Pan Bóg Wszechmogący.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 7, 'Cieszmy się i radujmy, i oddajmy mu chwałę, bo nadeszło wesele Baranka, a jego małżonka się przygotowała.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 8, 'I dano jej ubrać się w bisior czysty i lśniący, bo bisior to sprawiedliwość świętych.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 9, 'I powiedział mi: Napisz: Błogosławieni, którzy są wezwani na ucztę weselną Baranka. I powiedział mi: To są prawdziwe słowa Boga.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 10, 'I upadłem mu do nóg, aby oddać mu pokłon, lecz powiedział mi: Nie rób tego, bo jestem sługą razem z tobą i twoimi braćmi, którzy mają świadectwo Jezusa. Bogu oddaj pokłon, bowiem świadectwem Jezusa jest duch proroctwa.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 11, 'Potem zobaczyłem niebo otwarte, a oto koń biały, a ten, który na nim siedział, nazywa się Wiernym i Prawdziwym i w sprawiedliwości sądzi i walczy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 12, 'Jego oczy były jak płomień ognia, a na jego głowie było wiele koron. I miał wypisane imię, którego nikt nie zna, tylko on sam.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 13, 'Ubrany był w szatę zmoczoną we krwi, a jego imię brzmi: Słowo Boże.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 14, 'A wojska w niebie podążały za nim na białych koniach, ubrane w bisior biały i czysty.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 15, 'A z jego ust wychodził ostry miecz, aby nim pobił narody. On bowiem będzie rządził nimi laską żelazną i on wyciska w tłoczni wino zapalczywości i gniewu Boga Wszechmogącego.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 16, 'A na szacie i na biodrze ma wypisane imię: Król królów i Pan panów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 17, 'I zobaczyłem jednego anioła stojącego w słońcu. I zawołał donośnym głosem do wszystkich ptaków latających środkiem nieba: Chodźcie, zgromadźcie się na ucztę wielkiego Boga;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 18, 'Aby jeść ciała królów, ciała wodzów i ciała mocarzy, ciała koni i ich jeźdźców, i ciała wszystkich: wolnych i niewolników, małych i wielkich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 19, 'I zobaczyłem bestię i królów ziemi, i ich wojska zgromadzone, by stoczyć bitwę z tym, który siedzi na koniu, i z jego wojskiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 20, 'I schwytana została bestia, a z nią fałszywy prorok, który czynił przed nią cuda, jakimi zwiódł tych, którzy przyjęli znamię bestii i oddawali pokłon jej wizerunkowi. Oboje zostali żywcem wrzuceni do jeziora ognia, płonącego siarką.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 21, 'Pozostali zaś zostali zabici mieczem wychodzącym z ust tego, który siedział na koniu. I wszystkie ptaki najadły się ich ciałami.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 1, 'I zobaczyłem anioła zstępującego z nieba, mającego klucz do otchłani i wielki łańcuch w ręce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 2, 'I chwycił smoka, węża starodawnego, którym jest diabeł i szatan, i związał go na tysiąc lat.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 3, 'I wrzucił go do otchłani, zamknął go i opieczętował, aby już nie zwodził narodów, aż się dopełni tysiąc lat. A potem musi być wypuszczony na krótki czas.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 4, 'Zobaczyłem też trony i zasiedli na nich, i dano im władzę sądzenia. I zobaczyłem dusze ściętych z powodu świadectwa Jezusa i z powodu słowa Bożego oraz tych, którzy nie oddali pokłonu bestii ani jej wizerunkowi i nie przyjęli jej znamienia na czoło ani na rękę. I ożyli, i królowali z Chrystusem tysiąc lat.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 5, 'A inni z umarłych nie ożyli, aż się dopełniło tysiąc lat. To jest pierwsze zmartwychwstanie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 6, 'Błogosławiony i święty ten, kto ma udział w pierwszym zmartwychwstaniu. Nad nimi druga śmierć nie ma władzy, lecz będą kapłanami Boga i Chrystusa i będą z nim królować tysiąc lat.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 7, 'A gdy się skończy tysiąc lat, szatan zostanie wypuszczony ze swego więzienia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 8, 'I wyjdzie, aby zwieść narody z czterech krańców ziemi, Goga i Magoga, by zgromadzić je do bitwy. A ich liczba jest jak piasek morski.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 9, 'I wyszli na szerokość ziemi, otoczyli obóz świętych i miasto umiłowane. Zstąpił jednak ogień od Boga z nieba i pochłonął ich.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 10, 'A diabeł, który ich zwodził, został wrzucony do jeziora ognia i siarki, gdzie jest bestia i fałszywy prorok. I będą męczeni we dnie i w nocy na wieki wieków.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 11, 'I zobaczyłem wielki biały tron i zasiadającego na nim, sprzed którego oblicza uciekła ziemia i niebo, i nie znaleziono dla nich miejsca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 12, 'I zobaczyłem umarłych, wielkich i małych, stojących przed Bogiem, i otwarto księgi. Otwarto też inną księgę, księgę życia. I osądzeni zostali umarli według tego, co było napisane w księgach, to znaczy według ich uczynków.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 13, 'I wydało morze umarłych, którzy w nim byli, również śmierć i piekło wydały umarłych, którzy w nich byli. I zostali osądzeni, każdy według swoich uczynków.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 14, 'A śmierć i piekło zostały wrzucone do jeziora ognia. To jest druga śmierć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 15, 'I jeśli się ktoś nie znalazł zapisany w księdze życia, został wrzucony do jeziora ognia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 1, 'Potem zobaczyłem nowe niebo i nową ziemię. Pierwsze niebo bowiem i pierwsza ziemia przeminęły i nie było już morza.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 2, 'A ja, Jan, zobaczyłem święte miasto, nowe Jeruzalem, zstępujące z nieba od Boga, przygotowane jak oblubienica przyozdobiona dla swego męża.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 3, 'I usłyszałem donośny głos z nieba: Oto przybytek Boga jest z ludźmi i będzie mieszkał z nimi. Oni będą jego ludem, a sam Bóg będzie z nimi i będzie ich Bogiem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 4, 'I otrze Bóg wszelką łzę z ich oczu, i śmierci już nie będzie ani smutku, ani krzyku, ani bólu nie będzie, bo pierwsze rzeczy przeminęły.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 5, 'A zasiadający na tronie powiedział: Oto wszystko czynię nowe. I powiedział do mnie: Napisz, bo te słowa są wiarygodne i prawdziwe.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 6, 'I powiedział do mnie: Stało się. Ja jestem Alfa i Omega, początek i koniec. Ja spragnionemu dam darmo ze źródła wody życia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 7, 'Kto zwycięży, odziedziczy wszystko i będę dla niego Bogiem, a on będzie dla mnie synem.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 8, 'Ale bojaźliwi, niewierzący, obrzydliwi, mordercy, rozpustnicy, czarownicy, bałwochwalcy i wszyscy kłamcy będą mieli udział w jeziorze płonącym ogniem i siarką. To jest druga śmierć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 9, 'I przyszedł do mnie jeden z siedmiu aniołów, którzy mieli siedem czasz napełnionych siedmioma ostatecznymi plagami, i odezwał się do mnie, mówiąc: Chodź tutaj, pokażę ci oblubienicę, małżonkę Baranka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 10, 'I przeniósł mnie w duchu na górę wielką i wysoką, i pokazał mi wielkie miasto, święte Jeruzalem, zstępujące z nieba od Boga;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 11, 'Mające chwałę Boga. Jego blask podobny był do drogocennego kamienia, jakby jaspisu, przezroczystego jak kryształ.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 12, 'Miało ono wielki i wysoki mur, miało dwanaście bram, a na bramach dwunastu aniołów i wypisane imiona, które są imionami dwunastu pokoleń synów Izraela.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 13, 'Od wschodu trzy bramy, od północy trzy bramy, od południa trzy bramy i od zachodu trzy bramy.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 14, 'A mur miasta miał dwanaście fundamentów, a na nich dwanaście imion dwunastu apostołów Baranka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 15, 'A ten, który rozmawiał ze mną, miał złotą trzcinę, aby zmierzyć miasto, jego bramy i jego mur.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 16, 'Miasto ma kształt czworoboku, a jego długość jest taka sama jak i szerokość. I wymierzył miasto trzciną na dwanaście tysięcy stadiów. Jego długość, szerokość i wysokość są równe.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 17, 'I wymierzył jego mur na sto czterdzieści cztery łokcie według miary człowieka, która jest miarą anioła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 18, 'Jego mur jest zbudowany z jaspisu, miasto zaś ze szczerego złota podobnego do czystego szkła.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 19, 'Fundamenty muru miasta ozdobione były wszelkimi drogimi kamieniami. Pierwszy fundament to jaspis, drugi – szafir, trzeci – chalcedon, czwarty – szmaragd;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 20, 'Piąty – sardoniks, szósty – karneol, siódmy – chryzolit, ósmy – beryl, dziewiąty – topaz, dziesiąty – chryzopraz, jedenasty – hiacynt, dwunasty – ametyst.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 21, 'A dwanaście bram to dwanaście pereł. Każda brama była z jednej perły. A rynek miasta to szczere złoto, jak przezroczyste szkło.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 22, 'Lecz świątyni w nim nie widziałem, bo jego świątynią jest Pan Bóg Wszechmogący oraz Baranek.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 23, 'A miasto nie potrzebuje słońca ani księżyca, aby świeciły w nim, bo oświetla je chwała Boga, a jego lampą jest Baranek.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 24, 'Narody, które będą zbawione, będą chodziły w jego świetle, a królowie ziemi wniosą do niego swoją chwałę i cześć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 25, 'W dzień jego bramy nie będą zamknięte, bo nocy tam nie będzie.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 26, 'I wniosą do niego chwałę i cześć narodów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 27, 'I nie wejdzie do niego nic nieczystego ani ten, kto popełnia obrzydliwość i kłamstwo, tylko ci, którzy są zapisani w księdze życia Baranka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 1, 'I pokazał mi czystą rzekę wody życia, przejrzystą jak kryształ, wypływającą z tronu Boga i Baranka.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 2, 'A pośrodku rynku miasta, po obu stronach rzeki, było drzewo życia przynoszące owoc dwunastu rodzajów, wydające swój owoc co miesiąc. A liście drzewa służą do uzdrawiania narodów.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 3, 'I nie będzie już żadnego przekleństwa. Lecz będzie w nim tron Boga i Baranka, a jego słudzy będą mu służyć.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 4, 'I będą oglądać jego oblicze, a jego imię będzie na ich czołach.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 5, 'I nocy tam nie będzie, i nie będzie im potrzeba lampy ani światła słońca, bo Pan Bóg będzie im świecił i będą królować na wieki wieków.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 6, 'I powiedział do mnie: Te słowa są wiarygodne i prawdziwe, a Pan, Bóg świętych proroków, posłał swego anioła, aby pokazać swym sługom, co ma się stać wkrótce.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 7, 'Oto przyjdę wkrótce: Błogosławiony, który zachowuje słowa proroctwa tej księgi.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 8, 'A ja, Jan, widziałem to wszystko i słyszałem. A gdy usłyszałem i zobaczyłem, upadłem do nóg anioła, który mi to pokazywał, aby oddać mu pokłon.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 9, 'Lecz powiedział do mnie: Nie rób tego, bo jestem sługą z tobą i twoimi braćmi prorokami, i z tymi, którzy zachowują słowa tej księgi. Bogu oddaj pokłon.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 10, 'Potem powiedział do mnie: Nie pieczętuj słów proroctwa tej księgi, bo czas jest bliski.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 11, 'Kto krzywdzi, niech nadal wyrządza krzywdę, kto plugawy, niech się nadal plugawi, kto sprawiedliwy, niech nadal będzie sprawiedliwy, a kto święty, niech się nadal uświęca.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 12, 'A oto przyjdę wkrótce, a moja zapłata jest ze mną, aby oddać każdemu według jego uczynków.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 13, 'Ja jestem Alfa i Omega, początek i koniec, pierwszy i ostatni.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 14, 'Błogosławieni, którzy wypełniają jego przykazania, aby mieli prawo do drzewa życia i aby weszli przez bramy do miasta.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 15, 'Na zewnątrz zaś są psy, czarownicy, rozpustnicy, mordercy, bałwochwalcy i każdy, kto miłuje i czyni kłamstwo.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 16, 'Ja, Jezus, posłałem mojego anioła, aby wam świadczył o tym w kościołach. Ja jestem korzeniem i potomkiem Dawida, jasną gwiazdą poranną.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 17, 'A Duch i oblubienica mówią: Przyjdź! A kto słyszy, niech powie: Przyjdź! A kto pragnie, niech przyjdzie, a kto chce, niech darmo weźmie wodę życia.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 18, 'Oświadczam zaś każdemu, kto słucha słów proroctwa tej księgi: Jeśli ktoś dołoży coś do tego, dołoży mu też Bóg plag opisanych w tej księdze;');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 19, 'A jeśli ktoś odejmie coś ze słów księgi tego proroctwa, odejmie też Bóg jego dział z księgi życia i ze świętego miasta, i z rzeczy, które są opisane w tej księdze.');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 20, 'Tak mówi ten, który zaświadcza o tym: Zaprawdę, przyjdę wkrótce. Amen! O tak, przyjdź, Panie Jezu!');
INSERT INTO `PolUGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 21, 'Łaska naszego Pana Jezusa Chrystusa niech będzie z wami wszystkimi. Amen.');
